/* 放射医学技术副高题库 · 公开版（不含答案·gid/gs/mk 供共用题干题使用）v3 */
window.QUESTIONS_ALL=[{"id": "053-001", "t": "单选题", "s": "在颅脑CT横断面影像上，识别中央沟最可靠的标志是", "o": {"A": "顶枕沟", "B": "外侧裂", "C": "中央沟上端抵达大脑半球上缘处呈“切迹”样凹陷", "D": "扣带沟", "E": "距状裂"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-01", "kp": "颅脑横断面影像解剖", "ch": "一、人体断面影像解剖 → 1.头部 → 颅脑横断面影像解剖", "ex": "【为什么对】中央沟在CT/MRI横断面上最特征性表现为：中央沟上端抵达大脑半球上缘处，形成明显“切迹”样凹陷，是识别中央沟最可靠的影像学标志。中央沟前方为额叶（中央前回），后方为顶叶（中央后回）。【为什么错】A顶枕沟位于大脑半球内侧面后部，为顶叶与枕叶分界。B外侧裂位于外侧面，为颞叶与额顶叶分界。D扣带沟位于内侧面属边缘系统。E距状裂位于枕叶内侧面。", "tr": "部分考生易将外侧裂（B）误认为中央沟定位标志——外侧裂呈“Y”形或“T”形、位置偏下偏外侧。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-002", "t": "多选题", "s": "关于颈部CT横断面影像解剖，以下描述正确的是", "o": {"A": "甲状腺位于气管两侧，平第5颈椎至第1胸椎水平，CT平扫呈均匀软组织密度", "B": "颈总动脉在甲状软骨上缘水平分为颈内动脉和颈外动脉", "C": "颈内静脉位于颈总动脉的外侧，管径通常大于颈总动脉", "D": "喉室在横断面上位于真假声带之间，呈含气空腔", "E": "食管在颈段始终位于气管正后方"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-02", "kp": "颈部断面影像解剖", "ch": "一、人体断面影像解剖 → 2.颈部 → 颈部断面影像解剖", "ex": "【为什么对】A正确：甲状腺平C5-T1，CT呈均匀稍高软组织密度（含碘）。B正确：分叉在甲状软骨上缘（约C3-C4）。C正确：颈内静脉居外侧、管径较大。D正确：喉室为真假声带间含气腔隙。【为什么错】E错误：食管颈段并非始终位于气管正后方——颈根部食管略偏左侧，气管食管沟内有喉返神经走行。", "tr": "E描述过于绝对——食管颈段入胸廓上口时向左偏移。颈动脉鞘内：动脉居内侧、静脉居外侧、迷走神经居后方。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "颈部", "页": 8}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-003", "t": "单选题", "s": "在胸部CT横断面影像上，隆突下间隙位于", "o": {"A": "气管与食管之间", "B": "主动脉弓与肺动脉干之间", "C": "左、右主支气管分叉处下方", "D": "上腔静脉与升主动脉之间", "E": "奇静脉弓与气管之间"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-03", "kp": "胸部断面影像解剖", "ch": "一、人体断面影像解剖 → 3.胸部 → 胸部断面影像解剖", "ex": "【为什么对】隆突下间隙指气管隆突（左、右主支气管分叉处）下方区域，是第7组淋巴结分布区。【为什么错】A为气管食管沟；B为主肺动脉窗（第5组淋巴结）；D为上腔静脉后间隙；E为奇静脉食管隐窝上份。", "tr": "容易将主肺动脉窗（B）与隆突下间隙混淆——两者均为纵隔淋巴结区域但层面位置不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-004", "t": "案例分析题", "s": "患者男性，55岁，因上腹部不适行上腹部MRI平扫+增强检查。横断面T2WI脂肪抑制序列上，肝右叶第VIII段见类圆形高信号灶，边界清晰，约2.5cm×2.0cm，增强扫描动脉期明显均匀强化，门静脉期及延迟期呈等信号。", "o": {"A": "该病灶Couinaud分段为第VIII段，位于肝右静脉与肝中静脉之间、肝右叶上份", "B": "T2WI脂肪抑制呈高信号提示病灶含水量增加，常见于恶性肿瘤", "C": "“动脉期明显强化+门静脉期及延迟期等信号”是典型血管瘤的强化模式", "D": "肝第VIII段血供主要来自门静脉右支", "E": "该患者最可能的诊断是肝细胞肝癌"}, "d": "难", "c": "分析", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-04", "kp": "腹部断面影像解剖与Couinaud分段", "ch": "一、人体断面影像解剖 → 4.腹部 → 腹部断面影像解剖与Couinaud分段", "ex": "【为什么对】A正确：第VIII段位于肝右叶上份，内侧肝中静脉、外侧肝右静脉。【为什么错】B错误：T2WI高信号良恶性均可见。C错误：动脉期均匀强化+延迟期等信号是FNH或肝腺瘤特征，非血管瘤（血管瘤为周边结节样→向心性填充）。D错误：肝脏各段均为肝动脉+门静脉双重供血。E错误：根据影像特征更可能是FNH而非肝癌（肝癌为“快进快出”）。", "tr": "C将FNH强化模式描述为血管瘤特征。血管瘤=“早出晚归”（周边结节样→向心性填充），肝癌=“快进快出”，FNH=“快进等出”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": true, "src": "回忆版", "mk": 0}, {"id": "053-005", "t": "单选题", "s": "在男性盆腔MRI横断面T2WI上，前列腺中央带相对于周围带的信号特征是", "o": {"A": "中央带呈高信号，周围带呈低信号", "B": "中央带呈低信号，周围带呈高信号", "C": "中央带与周围带均呈等信号", "D": "中央带呈等信号，周围带呈高信号", "E": "中央带呈高信号，周围带呈等信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-05", "kp": "盆腔断面影像解剖", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → 盆腔断面影像解剖", "ex": "【为什么对】T2WI上周围带因富含腺体和液体呈均匀高信号；中央带因含较多平滑肌和致密基质呈低信号。约70%前列腺癌起源于周围带，在高信号背景上呈低信号区。【为什么错】A信号特征颠倒。C、D、E均与实际不符——周围带T2WI明确高信号，中央带低信号。", "tr": "考生可能受CT思维影响认为各带信号差异不大（C），但MRI T2WI上周围带与中央带信号差异是识别前列腺解剖分区的关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-006", "t": "多选题", "s": "关于脊柱MRI矢状面影像解剖，以下描述正确的是", "o": {"A": "正常成人椎间盘在T2WI上呈高信号，中央可见“水平线”样低信号裂隙", "B": "脊髓圆锥末端在成人通常平第L1椎体下缘水平", "C": "后纵韧带在MRI各序列上均呈低信号，紧贴椎体后缘", "D": "椎管前后径最窄的部位位于T4-T9水平", "E": "黄韧带位于椎板前方，在T1WI和T2WI上均呈中等信号"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-06", "kp": "脊柱断面影像解剖", "ch": "一、人体断面影像解剖 → 6.脊柱区 → 脊柱断面影像解剖", "ex": "【为什么对】A正确：正常椎间盘T2WI高信号，中央水平裂隙为椎间盘内裂（正常）。B正确：圆锥末端约L1下缘。C正确：后纵韧带纤维性→各序列低信号。D正确：T4-T9椎管最窄。【为什么错】E错误：黄韧带富含弹性蛋白，信号介于肌肉和脂肪之间（中等至稍高信号），非所有序列均单纯中等信号。", "tr": "黄韧带（弹性蛋白为主）与其他韧带（胶原纤维为主）MRI信号不同——后者各序列低信号，黄韧带信号有所升高。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "脊柱区", "页": 21}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-007", "t": "单选题", "s": "X线管产生X线的效率约为", "o": {"A": "0.1%以下", "B": "约1%", "C": "约5%", "D": "约10%", "E": "约30%"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XRAY-01", "kp": "X线产生效率", "ch": "二、医学物理基础 → 1.X线的产生 → X线产生效率", "ex": "【为什么对】X线产生效率约1%，约99%电子动能转化为热能。η≈K×Z×kVp（K≈1×10⁻⁹），钨靶（Z=74）在100kVp下η≈0.74%。【为什么错】A过低；C、D、E均显著高估。临床诊断用X线管效率在0.5%-1.5%之间。", "tr": "考生凭直觉可能认为X线效率较高（C/D/E），但X线管是效率极低的热能转换器。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-008", "t": "多选题", "s": "以下哪些属于X线的物理特性", "o": {"A": "穿透作用", "B": "荧光作用", "C": "电离作用", "D": "感光作用", "E": "生物效应"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XRAY-02", "kp": "X线的特性", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → X线的特性", "ex": "【为什么对】物理特性包括：①穿透作用；②荧光作用（透视和增感屏基础）；③电离作用（剂量学和放疗基础）。【为什么错】D感光作用属化学特性——X线使溴化银感光。E生物效应属生物特性——X线对生物体的损伤效应。", "tr": "感光作用常被误归为物理特性，但实质是卤化银光化学反应。生物效应虽基于物理电离，但已涉及生命体反应。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-009", "t": "单选题", "s": "在诊断X线能量范围内（20-150keV），X线与物质最主要的相互作用形式是", "o": {"A": "光电效应", "B": "康普顿散射", "C": "电子对效应", "D": "瑞利散射", "E": "光核反应"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XRAY-03", "kp": "X线与物质的相互作用", "ch": "二、医学物理基础 → 3.X线的本质及与物质的相互作用 → X线与物质的相互作用", "ex": "【为什么对】诊断能量范围内光电效应占主导，是形成X线影像对比度的主要物理基础。光电效应概率∝Z³⁻⁴，与E³成反比，使骨骼与软组织产生良好天然对比。【为什么错】B康普顿散射在诊断能量范围内次要，随能量升高占比增大。C电子对效应需>1.022MeV。D瑞利散射占比约5-10%，不产生电离。E光核反应需>10MeV。", "tr": "考生常误选康普顿散射（B），因CT较高kVp时占比增加。但常规X线摄影有效能量范围（40-80keV）光电效应仍是主导。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-010", "t": "单选题", "s": "半价层（HVL）反映了X线的哪种特性", "o": {"A": "X线的空间分布", "B": "X线的质（穿透能力）", "C": "X线的量（光子数目）", "D": "X线的散射程度", "E": "X线的焦点大小"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XRAY-04", "kp": "X线的衰减与质控参数", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → X线的衰减与质控参数", "ex": "【为什么对】HVL定义为使入射X线强度衰减至一半所需吸收物质厚度（mmAl或mmCu），反映X线束的“质”（穿透能力/硬度）。HVL越大穿透力越强。【为什么错】A不反映空间分布。C反映质而非量（量用mAs衡量）。D散射程度与多种因素有关。E焦点大小为X线管几何参数。", "tr": "初学者易将HVL与“量”混淆——“衰减一半”听起来像测数量，但HVL实质是测穿透能力（质）。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-011", "t": "单选题", "s": "MRI中，Larmor频率与主磁场强度B₀的关系是", "o": {"A": "正比关系", "B": "反比关系", "C": "无关系", "D": "指数关系", "E": "对数关系"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MRI-01", "kp": "Larmor方程与磁共振物理", "ch": "二、医学物理基础 → 5.磁学基础知识 → Larmor方程与磁共振物理", "ex": "【为什么对】Larmor方程：ω₀=γB₀，Larmor频率与B₀成正比。氢质子γ=42.58MHz/T，1.5T下f₀≈63.9MHz，3.0T下f₀≈127.7MHz。【为什么错】B、C、D、E均与Larmor方程不符——是严格线性正比关系。", "tr": "考生可能混淆Larmor频率与T1/T2弛豫时间对场强的依赖性。T1与场强一般正相关，T2依赖性较小。Larmor频率严格正比于B₀。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-012", "t": "多选题", "s": "关于T1和T2弛豫的描述，以下正确的是", "o": {"A": "T1弛豫又称自旋-晶格弛豫，反映纵向磁化矢量恢复过程", "B": "T2弛豫又称自旋-自旋弛豫，反映横向磁化矢量衰减过程", "C": "脂肪的T1值长于水的T1值", "D": "在3.0T场强下组织的T1值通常较1.5T下延长", "E": "T2*总是大于或等于T2"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MRI-02", "kp": "T1/T2/T2*弛豫机制", "ch": "二、医学物理基础 → 5.磁学基础知识 → T1/T2/T2*弛豫机制", "ex": "【为什么对】A正确：T1弛豫为纵向磁化恢复过程。B正确：T2弛豫为横向磁化衰减过程。D正确：随场强增高T1值普遍延长。【为什么错】C错误：脂肪T1短（约260ms/1.5T），水T1长（约3000ms/1.5T）。E错误：T2*≤T2，因T2*包含主磁场不均匀性导致的额外失相（1/T2*=1/T2+1/T2'）。", "tr": "两个陷阱：①C将脂肪和水T1长短说反——脂肪T1WI高信号正因为T1值短。②E将T2*与T2大小关系颠倒——T2*<T2。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-013", "t": "单选题", "s": "放射防护三原则不包括以下哪项", "o": {"A": "实践正当化", "B": "防护最优化", "C": "个人剂量限值", "D": "辐射剂量最小化至零", "E": "以上都不是（三原则包含A、B、C）"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-01", "kp": "放射防护三原则", "ch": "二、医学物理基础 → 6.X线防护与测量 → 放射防护三原则", "ex": "【为什么对】ICRP放射防护三原则：①实践正当化；②防护最优化（ALARA）；③个人剂量限值。“辐射剂量最小化至零”不是防护原则——医学实践中零辐射意味着放弃所有放射学检查，不符合正当化。【为什么错】A、B、C均为正确三原则。E为干扰项。", "tr": "D“最小化至零”听起来像防护极致要求，但放射防护追求ALARA（可合理达到的尽量低），非绝对零剂量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-014", "t": "多选题", "s": "关于X线在物质中的衰减规律，正确的描述是", "o": {"A": "单能X线窄束衰减符合指数衰减规律：I=I₀e^{-μx}", "B": "线衰减系数μ与物质密度成正比", "C": "质量衰减系数μ/ρ与物质的物理状态（固态/液态/气态）无关", "D": "增加管电压（kVp）可使X线束穿透力增强，表现为半价层增大", "E": "CT中使用的Hounsfield单位是基于水的质量衰减系数（而非线衰减系数）定义的"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-ATTN-01", "kp": "X线衰减规律与CT值", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → X线衰减规律与CT值", "ex": "【为什么对】A正确——单能窄束X线衰减严格遵循指数规律 I=I₀e^{-μx}。B正确——线衰减系数μ与物质密度成正比（同种成分下）。C正确——质量衰减系数μ/ρ消除了密度差异，仅取决于原子组成与X线能量，与物理状态无关。D正确——提高kVp使平均光子能量升高、线束硬度增加，半价层（HVL）增大、穿透力增强。【为什么错】E错误——CT值定义为 HU=(μ_物质−μ_水)/μ_水×1000，式中μ为线衰减系数（linear attenuation coefficient），是与水比较的基准；质量衰减系数μ/ρ用于消除密度影响以比较物质固有衰减能力，并不参与CT值计算。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——CT值定义为 HU=(μ_物质−μ_水)/μ_水×1000，式中μ为线衰减系数（linear attenuation coefficient），是与水比较的基准；质量衰减系数μ/ρ用于消除密度影响以比较物质固有衰减能力，并不参与CT值计算。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-015", "t": "单选题", "s": "旋转阳极X线管与固定阳极X线管相比，其主要优势是", "o": {"A": "更低的管电压要求", "B": "更小的焦点", "C": "更大的热容量和更高的输出功率", "D": "更简单的制造工艺", "E": "更低的成本"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-01", "kp": "X线管结构与阳极特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → X线管结构与阳极特性", "ex": "【为什么对】旋转阳极核心优势：阳极靶盘高速旋转（3000-10000rpm），电子轰击热量分布在环形靶道上，有效焦点面积小但实际受热面积大幅增加，热容量显著提升，允许更高输出功率。【为什么错】A与管电压无关。B可实现更小有效焦点（阳极倾角效应），但非核心优势。D、E旋转阳极结构更复杂、成本更高。", "tr": "部分考生可能误选B——虽然旋转阳极配合倾角可实现微焦点，但设计初衷是解决散热、提高功率承载能力。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-016", "t": "多选题", "s": "关于CR（计算机X线摄影）系统的成像过程，以下正确的是", "o": {"A": "CR使用IP（成像板）作为X线探测器，IP核心材料是光激励发光荧光体（如BaFX:Eu²⁺）", "B": "IP经X线曝光后形成潜影，潜影可在室温下稳定存储数小时至数天", "C": "IP读取时使用紫外（UV）激光逐点扫描，激发出的荧光被光电倍增管收集并数字化", "D": "CR系统的空间分辨率主要受IP荧光体层厚度和激光扫描点大小限制", "E": "CR与DR的根本区别在于CR需要“读取”步骤，而DR直接产生数字信号"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-02", "kp": "CR成像原理与流程", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → CR成像原理与流程", "ex": "【为什么对】A正确——CR的IP核心为掺铕氟卤化钡（BaFX:Eu²⁺）光激励发光荧光体。B正确——X线激发形成的F中心潜影在室温下可稳定数小时至数天（存在fading）。D正确——CR空间分辨率受IP荧光体层厚度与激光扫描光斑尺寸限制，典型值2.5–5 lp/mm。E正确——CR须经独立“读取”步骤才能输出数字信号，而DR探测器直接产生数字信号，这是二者根本区别。【为什么错】C错误——CR读取采用红-近红外激光（如He-Ne 633 nm或半导体680 nm）激发IP中Eu²⁺陷阱释放光激励发光（PSL）荧光，由PMT收集；紫外激光不能有效激发该荧光体，故“紫外激光”之说错误。", "tr": "本题已将原“全选”改为四项正确；注意选项C为刻意设置的错误项——CR读取采用红-近红外激光（如He-Ne 633 nm或半导体680 nm）激发IP中Eu²⁺陷阱释放光激励发光（PSL）荧光，由PMT收集；紫外激光不能有效激发该荧光体，故“紫外激光”之说错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-017", "t": "单选题", "s": "多层螺旋CT中，决定Z轴空间分辨率的最关键因素是", "o": {"A": "球管旋转速度", "B": "螺距（pitch）", "C": "准直宽度（探测器排宽×排数）与重建层厚", "D": "扫描视野（FOV）", "E": "矩阵大小"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-03", "kp": "CT成像参数与图像质量", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → CT成像参数与图像质量", "ex": "【为什么对】Z轴空间分辨率主要取决于准直宽度和重建层厚。层厚越薄、准直越窄，Z轴分辨率越高。现代MDCT通过亚毫米准直+薄层重建实现各向同性。【为什么错】A球管转速影响时间分辨率。B螺距影响覆盖速度和Z轴采样密度，是次级因素。D FOV影响XY平面。E矩阵影响XY平面。", "tr": "部分考生误选B（螺距）——螺距确实影响Z轴采样质量，但层厚才是Z轴分辨率的一级决定因素。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-018", "t": "单选题", "s": "DSA减影过程中，mask像是指", "o": {"A": "注射对比剂后的血管充盈像", "B": "注射对比剂前不含对比剂的平片", "C": "注射对比剂后延迟采集的像", "D": "经像素移位校正后的图像", "E": "对数变换后的图像"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-04", "kp": "DSA减影原理", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → DSA减影原理", "ex": "【为什么对】mask像（蒙片）是注射对比剂前采集的不含血管对比剂的平片。减影流程：mask像−造影像=减影像（仅显示血管内对比剂）。【为什么错】A为造影像（live像）。C仍属造影像。D为减影后配准修正。E为减影前预处理。", "tr": "记忆：mask=“蒙”（蒙在背景上、无对比剂），live=“活”（有对比剂、血管显影）。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-019", "t": "多选题", "s": "关于MRI自旋回波（SE）序列中TR和TE对图像对比度的影响，正确的是", "o": {"A": "短TR+短TE产生T1加权对比", "B": "长TR+长TE产生T2加权对比", "C": "长TR+短TE产生质子密度加权对比", "D": "TR主要控制T1权重，TE主要控制T2权重", "E": "在SE序列中，只要TR足够长（>5×最长组织T1），无论TE多短，图像总是T2加权"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-05", "kp": "MRI脉冲序列与加权成像", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → MRI脉冲序列与加权成像", "ex": "【为什么对】A正确：短TR+短TE=T1WI。B正确：长TR+长TE=T2WI。C正确：长TR+短TE=PDWI。D正确：TR调节T1权重，TE调节T2权重。【为什么错】E错误：长TR+短TE=质子密度加权——长TR消除T1差异，短TE消除T2差异。要获得T2加权必须长TR+长TE。", "tr": "E是经典陷阱——长TR消除T1效应正确，但要获得T2加权还需长TE。口诀：短TR短TE→T1WI；长TR长TE→T2WI；长TR短TE→PDWI。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-020", "t": "案例分析题", "s": "某医院计划采购一台64排螺旋CT设备，用于常规临床检查和冠状动脉CTA。影像科主任要求技术组评估该设备的关键技术参数。以下分析哪些是正确的", "o": {"A": "机架旋转速度至少应达到≤0.35s/圈，以满足冠状动脉CTA的时间分辨率要求", "B": "探测器准直宽度应≥32mm（如64×0.5mm或64×0.625mm），以实现足够Z轴覆盖", "C": "螺距设置对于冠脉CTA非常关键，通常使用前瞻性心电门控扫描模式，螺距接近0.2-0.3", "D": "管电流（mA）和管电压（kVp）的自动调制技术对于降低辐射剂量至关重要", "E": "64排CT的Z轴空间分辨率理论上可达到各向同性（如0.5mm×0.5mm×0.5mm）"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-06", "kp": "CT设备关键参数与临床应用评估", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → CT设备关键参数与临床应用评估", "ex": "【为什么对】五项均正确。A：冠脉CTA要求极高时间分辨率。B：64×0.5/0.625mm配置提供约32-40mm Z轴覆盖。C：前瞻性门控采用极低进床速度确保在心脏相对静止期完整采集数据。D：ATCM和自动kVp是低剂量CT核心技术。E：亚毫米准直+薄层重建实现各向同性分辨率。【为什么错】无错误选项。", "tr": "C易被误判——前瞻性心电门控实际为轴向扫描（step-and-shoot），但结论（低螺距/极低进床速度）正确。需注意prospective vs retrospective gating差异。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-021", "t": "单选题", "s": "DR系统使用的平板探测器，其核心转换材料中，非晶硒（a-Se）属于", "o": {"A": "间接转换型探测器，利用闪烁体将X线转换为可见光再转换为电荷", "B": "直接转换型探测器，直接将X线转换为电荷", "C": "光激励发光型探测器", "D": "热释光型探测器", "E": "CMOS型探测器"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-07", "kp": "DR探测器类型与原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → DR探测器类型与原理", "ex": "【为什么对】非晶硒（a-Se）是直接转换型平板探测器核心材料。X线光子直接作用于a-Se层产生电子-空穴对，被TFT阵列收集并数字化——无可见光转换步骤。【为什么错】A为间接转换型（CsI:Tl/Gd₂O₂S:Tb）。C为CR技术原理。D为热释光剂量计。E为读出电路技术。", "tr": "DR探测器分类：直接转换（a-Se）vs间接转换（CsI/Gd₂O₂S），核心区别在于是否需要“可见光”中间步骤。a-Si配合CsI使用（间接型），a-Se是直接转换材料——两者易混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-022", "t": "多选题", "s": "关于MRI梯度系统的功能，以下正确的是", "o": {"A": "层面选择梯度（Gss/Gz）用于选择成像层面，通常与RF脉冲配合使用", "B": "相位编码梯度（Gpe/Gy）用于在K空间的相位编码方向上进行空间定位", "C": "频率编码梯度（Gro/Gx）用于在信号读出期间进行频率编码，也称读出梯度", "D": "梯度场的最大强度和切换率（slew rate）共同决定了MRI的扫描速度", "E": "EPI（回波平面成像）对梯度系统的性能要求远低于常规SE序列"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-08", "kp": "MRI梯度系统与空间编码", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → MRI梯度系统与空间编码", "ex": "【为什么对】A正确——层面选择梯度在RF激励期间施加，配合RF带宽选层。B正确——相位编码梯度赋予质子沿相位编码方向线性变化的相位，实现该向定位。C正确——频率编码梯度在信号读出期间施加，使不同位置质子频率不同，故称读出梯度。D正确——梯度最大强度决定最小FOV/最小层厚，切换率（slew rate）决定最短梯度爬升时间，二者共同决定扫描速度。【为什么错】E错误——EPI要求在一次射频激发内完成整幅K空间所有相位编码行的填充，梯度场须在亚毫秒级反复高速切换至高振幅，对梯度强度与切换率要求极高，远高于常规SE序列，而非“远低于”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——EPI要求在一次射频激发内完成整幅K空间所有相位编码行的填充，梯度场须在亚毫秒级反复高速切换至高振幅，对梯度强度与切换率要求极高，远高于常规SE序列，而非“远低于”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-023", "t": "单选题", "s": "下列关于碘对比剂不良反应的描述，错误的是", "o": {"A": "碘对比剂不良反应分为类过敏反应（非特异质）和特异质反应两大类", "B": "急性肾损伤（AKI）是碘对比剂的重要并发症，糖尿病合并肾功能不全患者风险更高", "C": "碘对比剂不良反应的发生率与对比剂的渗透压呈正相关——等渗对比剂的安全性最高", "D": "一旦发生严重过敏反应，首选皮下注射肾上腺素", "E": "使用碘对比剂前常规进行碘过敏皮试可以完全预防严重过敏反应"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CONTRAST-01", "kp": "碘对比剂不良反应与安全管理", "ch": "四、对比剂 → 1.X线对比剂 → 碘对比剂不良反应与安全管理", "ex": "【为什么对】E表述错误——碘过敏皮试对预测严重过敏反应灵敏度和特异度均极低，ACR和ESUR已不推荐常规皮试。严重过敏反应无法通过皮试预测。【为什么错】A正确：不良反应分类确为类过敏和特异质。B正确：CA-AKI高危因素包括肾功能不全、糖尿病等。C正确：高渗对比剂不良反应率显著高于低渗和等渗。D方向正确，但最新指南推荐肌注而非皮下注射——但E为根本性错误。", "tr": "D存在潜在陷阱——最新指南推荐肾上腺素肌注（大腿前外侧）而非皮下注射。但E（皮试可完全预防过敏）明显根本性错误，为最佳答案。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-024", "t": "多选题", "s": "关于MR对比剂（钆剂）的描述，正确的是", "o": {"A": "钆喷酸葡胺（Gd-DTPA）属于线性结构钆螯合物，是最早应用于临床的钆剂之一", "B": "钆剂的主要作用是延长T1和T2弛豫时间，临床上以T1延长效应为主", "C": "大环状结构钆剂（如钆布醇、钆特酸）较线性钆剂具有更高的热力学和动力学稳定性，钆离子解离风险更低", "D": "肾源性系统性纤维化（NSF）的发生与游离钆离子在组织中的沉积密切相关，高危人群为重度肾功能不全患者", "E": "钆剂在颅内结构的沉积（“钆沉积”）已被证实，但其远期临床意义目前仍不明确"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CONTRAST-02", "kp": "MR对比剂分类与安全", "ch": "四、对比剂 → 2.MR对比剂 → MR对比剂分类与安全", "ex": "【为什么对】A正确——Gd-DTPA（马根维显）属线性离子型钆螯合物，是最早临床应用的钆剂之一（1988年）。C正确——大环状钆剂（如钆布醇、钆特酸）热力学/动力学稳定性显著高于线性剂，游离钆离子解离风险更低。D正确——肾源性系统性纤维化（NSF）与游离钆沉积相关，几乎仅见于重度肾功能不全者使用线性非离子型钆剂。E正确——钆在脑深部核团（齿状核、苍白球）的剂量依赖性沉积已被证实，远期临床意义尚不明确。【为什么错】B错误——钆对比剂含顺磁性Gd³⁺（7个未成对电子），通过偶极-偶极相互作用缩短周围组织T1（为主）与T2弛豫时间，从而产生T1WI强化；“延长弛豫时间”与事实相反。", "tr": "本题已将原“全选”改为四项正确；注意选项B为刻意设置的错误项——钆对比剂含顺磁性Gd³⁺（7个未成对电子），通过偶极-偶极相互作用缩短周围组织T1（为主）与T2弛豫时间，从而产生T1WI强化；“延长弛豫时间”与事实相反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-025", "t": "单选题", "s": "以下关于碘对比剂的分类，按渗透压从高到低排列正确的是", "o": {"A": "非离子型单体 > 离子型单体 > 非离子型二聚体", "B": "离子型单体 > 非离子型单体 > 非离子型二聚体", "C": "离子型单体 > 非离子型二聚体 > 非离子型单体", "D": "非离子型二聚体 > 非离子型单体 > 离子型单体", "E": "非离子型单体 > 非离子型二聚体 > 离子型单体"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CONTRAST-03", "kp": "碘对比剂分类与理化特性", "ch": "四、对比剂 → 1.X线对比剂 → 碘对比剂分类与理化特性", "ex": "【为什么对】渗透压排序：离子型单体（约1500-2100mOsm/kg）>非离子型单体（约600-900mOsm/kg）>非离子型二聚体（约290mOsm/kg，等渗）。离子型单体解离产生2个渗透活性粒子（比值=1.5），渗透压很高；非离子型单体不解离（比值=3）；非离子型二聚体6个碘不解离（比值=6），可达等渗。【为什么错】其他排列均与上述原理不符。", "tr": "核心记忆：“解离产生更多粒子→渗透压更高”。离子型单体>非离子型单体>非离子型二聚体。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-026", "t": "案例分析题", "s": "患者男性，68岁，体重70kg，因腹痛行腹部增强CT检查。既往有高血压病史15年、2型糖尿病史8年（口服二甲双胍），实验室检查：血肌酐142μmol/L（eGFR≈48ml/min/1.73m²）。医生开具碘对比剂（非离子型单体，含碘350mgI/ml，计划注射量100ml）。作为CT技术组负责人，以下处理方案正确的有哪些", "o": {"A": "该患者eGFR<60，属对比剂急性肾损伤（CA-AKI）高风险人群，检查前应充分水化（如0.9%NaCl 1ml/kg/h×12h）", "B": "应停用二甲双胍至少48小时，待增强CT后肾功能稳定（复查血肌酐无显著升高）方可恢复用药", "C": "碘对比剂总量100ml（含碘35g），对该患者属于常规剂量，无需调整", "D": "在条件允许的情况下，应优先考虑使用等渗对比剂（碘克沙醇）替代非离子型单体以降低肾毒性风险", "E": "增强CT检查后应继续水化至少24小时，并在48-72小时内复查肾功能"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CONTRAST-04", "kp": "对比剂安全管理与临床决策", "ch": "四、对比剂 → 1.X线对比剂 → 对比剂安全管理与临床决策", "ex": "【为什么对】A正确：eGFR<60是CA-AKI高危人群，水化是最有效预防措施。B正确：二甲双胍在eGFR 30-60之间国内多数医院谨慎停药48h。D正确：等渗对比剂在肾功能不全患者中CA-AKI发生率可能更低。E正确：检查后持续水化+随访肾功能是标准流程。【为什么错】C错误：对于eGFR<60患者，应在保证诊断需求前提下尽可能减少对比剂用量——对比剂剂量与CA-AKI风险正相关。", "tr": "C是主要陷阱——“常规剂量”对肾功能不全患者可能过高。核心原则：在满足诊断条件下使用最低剂量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-027", "t": "单选题", "s": "CT图像质量评价中，调制传递函数（MTF）主要用于评价", "o": {"A": "噪声水平", "B": "空间分辨率", "C": "低对比度分辨率", "D": "CT值线性度", "E": "时间分辨率"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QC-01", "kp": "CT图像质量评价参数", "ch": "五、影像质量管理 → 1.CT图像质量控制 → CT图像质量评价参数", "ex": "【为什么对】MTF是评价成像系统空间分辨率的客观量化指标，描述系统对不同空间频率（lp/cm）信号的传递能力。MTF=1表示完美传递，MTF=0表示完全不能分辨。常用MTF=10%对应空间频率为极限分辨率。【为什么错】A噪声用NPS或SD评价。C低对比度分辨率用LCD评价。D CT值线性度通过扫描已知CT值模体评价。E时间分辨率通过机架旋转速度评价。", "tr": "部分考生易将MTF与对比度分辨率混淆——MTF是高频响应（边缘锐利度），低对比度分辨率是低频检测能力。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-028", "t": "多选题", "s": "MRI日常质量控制（QC）应包括以下哪些测试项目", "o": {"A": "中心频率（共振频率）校准", "B": "信噪比（SNR）测量", "C": "图像均匀度测试", "D": "几何畸变测试", "E": "层厚精度测量不属于MRI QC常规项目，仅CT质控需要"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QC-02", "kp": "MRI质量控制项目", "ch": "五、影像质量管理 → 2.MR图像质量控制 → MRI质量控制项目", "ex": "【为什么对】A正确——中心频率（共振频率）校准确保RF与Larmor频率匹配，通常每日测试。B正确——信噪比（SNR）是最综合的图像质量指标。C正确——图像均匀度反映B₁与B₀场均匀性。D正确——几何畸变测试反映梯度场线性度，对高场强尤为关键。【为什么错】E错误——层厚精度（slice thickness accuracy）是MRI QC的常规测试项目（ACR/AAPM推荐），用以监测因梯度非线性和射频选择性偏差导致的实际层厚偏离；并非“仅CT需要”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——层厚精度（slice thickness accuracy）是MRI QC的常规测试项目（ACR/AAPM推荐），用以监测因梯度非线性和射频选择性偏差导致的实际层厚偏离；并非“仅CT需要”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-029", "t": "单选题", "s": "在数字X线图像处理中，窗口技术中的“窗宽”（window width）决定了", "o": {"A": "图像的整体亮度", "B": "图像的显示对比度（灰阶范围）", "C": "图像的空间分辨率", "D": "图像的信噪比", "E": "图像的几何放大率"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIGITAL-01", "kp": "窗口技术与灰阶处理", "ch": "六、数字X线成像基础 → 1.数字图像处理 → 窗口技术与灰阶处理", "ex": "【为什么对】窗宽（WW）定义显示灰阶所覆盖的CT值/HU值范围。窗宽越宽→CT值范围越大→组织间灰阶差异越小（低对比度）；窗宽越窄→范围越小→差异越大（高对比度）。窗宽决定对比度。【为什么错】A窗位（WL）决定整体亮度。C空间分辨率取决于探测器像素/FOV/矩阵。D SNR是采集参数函数。E几何放大率由焦点-物体-探测器距离决定。", "tr": "窗宽和窗位作用常混淆——窗宽→对比度（灰阶范围），窗位→亮度（中心位置）。口诀：“宽-范围-对比度，位-位置-亮度”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-030", "t": "多选题", "s": "关于探测器量子检测效率（DQE），以下描述正确的是", "o": {"A": "DQE定义为输出信噪比平方与输入信噪比平方之比：DQE=(SNR_out)²/(SNR_in)²", "B": "DQE是衡量探测器X线利用效率的综合指标，理想探测器DQE=1（100%）", "C": "DQE随空间频率增加而升高", "D": "DR系统的DQE通常在60%-80%，显著高于CR系统（约30%-50%）", "E": "增加探测器X线吸收层的厚度可以提高DQE但可能降低空间分辨率"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIGITAL-02", "kp": "DQE定义及影响因素", "ch": "六、数字X线成像基础 → 2.数字图像评价 → DQE定义及影响因素", "ex": "【为什么对】A正确——DQE定义为 (SNR_out)²/(SNR_in)²，即输出与输入信噪比平方之比。B正确——理想探测器不引入额外噪声时DQE=1（100%）。D正确——DR的DQE约60%–80%，显著高于CR（约30%–50%）。E正确——增加吸收层厚度提高X线吸收效率，但增加散射与光扩散，可能降低空间分辨率，是DQE与分辨率的经典权衡。【为什么错】C错误——DQE具有空间频率依赖性，随空间频率升高而下降（高频处量子统计与散射损失更显著），并非升高；故须以DQE(0)或指定频率处DQE来描述探测器性能。", "tr": "本题已将原“全选”改为四项正确；注意选项C为刻意设置的错误项——DQE具有空间频率依赖性，随空间频率升高而下降（高频处量子统计与散射损失更显著），并非升高；故须以DQE(0)或指定频率处DQE来描述探测器性能。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-031", "t": "案例分析题", "s": "在胸部X线正位片上，以下哪项最支持左心房增大的诊断", "o": {"A": "肺动脉段突出", "B": "右心缘双房影", "C": "左心缘出现“四弧征”（或称“病理性第三弓”）", "D": "心尖向左下移位", "E": "上腔静脉增宽"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-01", "kp": "心脏大血管X线诊断", "ch": "七、影像诊断学基础 → 1.胸部与心脏 → 心脏大血管X线诊断", "ex": "【为什么对】左心房增大特征性表现为：左心缘肺动脉段下方出现额外弧状突起（左心耳突出），使左心缘由正常“三弧”变为“四弧”，为“病理性第三弓”，是左心房增大的重要直接征象。【为什么错】A肺动脉段突出是肺动脉高压表现。B双房影虽是左心房增大表现但敏感性不如四弧征。D心尖向左下移位是左心室增大特征。E上腔静脉增宽见于右心功能不全。", "tr": "B（右心缘双房影）确实是左心房增大表现但出现较晚且受投照条件影响。C四弧征/病理性第三弓是更典型的直接征象。", "bk": "副高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "心脏大血管病变的基本X线表现", "页": 156}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-032", "t": "多选题", "s": "在CT影像上，以下哪些是周围型肺癌的典型表现", "o": {"A": "分叶征——肿瘤边缘呈分叶状，与肿瘤各方向生长速度不均有关", "B": "毛刺征——肿瘤边缘放射状细小短条索影，提示肿瘤浸润周围肺间质", "C": "胸膜凹陷征——肿瘤与胸膜间线状/三角形牵拉影", "D": "空泡征——肿瘤内残存含气肺泡或支气管，常见于腺癌", "E": "病变均匀钙化，CT值>200HU"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-02", "kp": "肺部肿瘤CT诊断", "ch": "七、影像诊断学基础 → 1.胸部与心脏 → 肺部肿瘤CT诊断", "ex": "【为什么对】A、B、C、D均为周围型肺癌常见CT征象。分叶征反映不均匀生长；毛刺征提示肿瘤向肺间质浸润；胸膜凹陷征是肿瘤牵拉胸膜；空泡征是腺癌特征（包绕未完全破坏的含气肺泡）。【为什么错】E错误：均匀钙化伴CT值>200HU高度提示良性病变（错构瘤、结核球等）。肺癌钙化少见且通常为点状、偏心性。", "tr": "E是区分良恶性肺结节重要考点——均匀钙化>200HU基本排除恶性肿瘤。但需注意形态比有无钙化更重要。", "bk": "副高", "ref": {"篇": "胸部", "章": "呼吸系统基本病变的影像学表现", "节": "肺部有关名词", "页": 115}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-033", "t": "案例分析题", "s": "以下关于肝海绵状血管瘤的MRI表现，错误的是", "o": {"A": "T1WI呈低信号，T2WI呈显著高信号（灯泡征）", "B": "增强扫描动脉期周边结节样强化，随时间推移呈向心性填充（“早出晚归”）", "C": "延迟期（5-10min）持续强化呈等或高信号", "D": "DWI上呈显著弥散受限（高b值高信号，ADC值极低）", "E": "重T2WI上血管瘤信号随TE延长而保持高信号（“灯泡征”在长TE序列更明显）"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-03", "kp": "肝脏常见肿瘤MRI诊断", "ch": "七、影像诊断学基础 → 2.腹部 → 肝脏常见肿瘤MRI诊断", "ex": "【为什么对】D对肝血管瘤的DWI描述错误——血管瘤为良性富血供病变，内为缓慢流动血液（血池），DWI上不表现为显著弥散受限。DWI可呈稍高信号（T2穿透效应），但ADC值通常较高或接近正常肝实质。DWI显著弥散受限+ADC极低应考虑肝癌。【为什么错】A、B、C、E均为正确表现。重T2WI灯泡征更明显是因肝实质T2较短随TE延长快速衰减，血管瘤内血液T2极长。", "tr": "许多考生认为血管瘤因T2极高在DWI上也会呈显著高信号（弥散受限）。但DWI信号同时受T2效应和真实弥散限制两方面影响——血管瘤DWI高信号主要来自“T2穿透效应”（T2 shine-through），ADC图呈等或高信号可鉴别。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-034", "t": "案例分析题", "s": "以下关于急性脑梗死的影像学表现，按时间顺序最早出现的是", "o": {"A": "CT平扫脑沟消失、脑回肿胀", "B": "T2WI/FLAIR上高信号", "C": "DWI上高信号伴ADC值降低", "D": "T1WI上低信号", "E": "增强扫描脑回样强化"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-04", "kp": "脑梗死影像诊断", "ch": "七、影像诊断学基础 → 3.颅脑中枢神经系统 → 脑梗死影像诊断", "ex": "【为什么对】急性脑梗死影像学异常出现时间顺序：DWI（数分钟至数小时）→CT早期征象（3-6h）→T2WI/FLAIR（6-12h）→T1WI低信号（12-24h）→增强脑回样强化（3-7天达峰）。DWI可检测细胞毒性水肿导致的弥散受限，是急性脑梗死最早、最敏感征象，可在症状发作后数分钟内呈阳性。【为什么错】CT早期征象需数小时才显现（敏感性约50-60%）。T2WI和T1WI变化更晚。增强脑回样强化是亚急性期表现。", "tr": "部分考生可能首选CT（A）因为急诊常用CT排除出血。但本题问“最早出现”的影像学异常——细胞毒性水肿（DWI高信号/ADC降低）是缺血后最早事件。临床先做CT是为了排除出血。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑缺血和脑梗死", "页": 34}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-035", "t": "案例分析题", "s": "患者女性，42岁，因右侧耳鸣伴听力下降3个月就诊。颞骨HRCT扫描显示右侧内听道内一软组织密度结节，大小约0.8cm×0.6cm，内听道无明显扩大。MRI显示右侧内听道内小结节，T1WI等信号、T2WI稍高信号，增强扫描呈明显均匀强化，边界清晰。", "o": {"A": "该病灶最可能的诊断是听神经瘤（前庭神经鞘瘤）", "B": "内听道无明显扩大与该病灶较小（<1cm）有关，不能排除听神经瘤", "C": "增强扫描明显均匀强化是听神经瘤的典型特征，据此可确诊", "D": "鉴别诊断应考虑内听道内脑膜瘤，脑膜瘤增强也呈明显强化但常有“硬膜尾征”", "E": "对于此类小听神经瘤，首选伽马刀治疗而非手术切除"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-05", "kp": "五官疾病影像诊断", "ch": "七、影像诊断学基础 → 4.五官与颈部 → 五官疾病影像诊断", "ex": "【为什么对】A正确：内听道结节（T1等/T2稍高+明显均匀强化）是听神经瘤典型表现。B正确：内听道扩大与肿瘤大小有关，<1cm微小听神经瘤可无内听道扩大。D正确：内听道脑膜瘤也可明显强化，特征为硬膜基底+硬膜尾征。【为什么错】C错误：明显均匀强化不能据此确诊——内听道脑膜瘤、面神经鞘瘤也可有类似强化。E错误：小听神经瘤治疗策略需综合多因素个体化决定，非首选伽马刀。", "tr": "C用“可据此确诊”诱导忽视鉴别诊断。E以“首选伽马刀”绝对化表述制造陷阱——稳定小肿瘤可能仅需随访观察。", "bk": "副高", "ref": null, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-036", "t": "多选题", "s": "关于骨肉瘤的X线和MRI表现，以下正确的是", "o": {"A": "好发于长骨干骺端，特别是股骨远端和胫骨近端", "B": "X线可见Codman三角（骨膜新生骨被抬起形成三角形），是骨肉瘤的特征性表现", "C": "肿瘤骨（瘤骨）是骨肉瘤最重要的X线特征——肿瘤细胞直接产生的不规则骨样组织", "D": "MRI对评价骨髓浸润范围、软组织肿块及跳跃性病灶优于X线和CT", "E": "骨肉瘤在T1WI上通常呈高信号、T2WI呈低信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-06", "kp": "骨肿瘤影像诊断", "ch": "七、影像诊断学基础 → 5.脊柱与四肢关节 → 骨肿瘤影像诊断", "ex": "【为什么对】A正确：骨肉瘤好发于长骨干骺端。B正确：Codman三角是骨膜被肿瘤抬起形成的三角形骨膜新生骨。C正确：瘤骨（肿瘤性骨样组织/编织骨）是骨肉瘤定性诊断依据。D正确：MRI对髓腔浸润范围、软组织肿块及跳跃灶评估优于X线/CT。【为什么错】E错误：骨肉瘤T1WI通常呈低至等信号（替代骨髓高信号脂肪），T2WI呈不均匀高信号（肿瘤含水量高）。", "tr": "E将T1/T2信号特征说反——正常骨髓T1WI高信号（脂肪），肿瘤替代后T1WI低信号。瘤骨在T2WI为低信号，但整体肿瘤T2WI以高信号为主。", "bk": "副高", "ref": null, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-037", "t": "案例分析题", "s": "在急性胆囊炎的腹部CT检查中，以下哪项是诊断价值最高的直接影像学征象", "o": {"A": "胆囊体积增大（横径>4cm）", "B": "胆囊壁弥漫性增厚（>3mm）", "C": "胆囊壁内积气（气肿性胆囊炎表现）", "D": "胆囊周围脂肪间隙模糊、条索状密度增高（pericholecystic fat stranding）", "E": "胆囊内结石"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-07", "kp": "腹部急症影像诊断", "ch": "七、影像诊断学基础 → 2.腹部 → 腹部急症影像诊断", "ex": "【为什么对】D正确——胆囊周围脂肪间隙模糊、条索状密度增高（pericholecystic fat stranding）是急性胆囊炎在CT上最可靠的直接征象，敏感性与特异性均较高，反映胆囊壁炎症累及周围脂肪，是CT诊断急性胆囊炎的核心标准。【为什么错】A、B、E虽常见但特异性不足：胆囊淤积、慢性胆囊炎、肝硬化低蛋白血症等均可致胆囊增大或壁增厚，结石亦可无症状存在；C为气肿性胆囊炎表现，属少见重症类型，而非一般急性胆囊炎的直接征象。", "tr": "易将“胆囊壁增厚>3mm”误认为最直接征象；但壁增厚也见于慢性胆囊炎、低蛋白血症，特异性低于胆囊周围脂肪条索影。", "bk": "副高", "ref": null, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-038", "t": "多选题", "s": "关于椎间盘突出的CT和MRI表现，正确的是", "o": {"A": "CT横断面上，椎间盘突出表现为椎间盘后缘局限性超出椎体后缘的软组织密度影", "B": "MRI上椎间盘突出可分为膨出（bulging）、突出（protrusion）、脱出（extrusion）和游离（sequestration）四种类型", "C": "Schmorl结节是指椎间盘向椎体内突出（纵向疝入），常见于Scheuermann病", "D": "椎间盘突出的方向以后外侧型最为常见，因为后纵韧带在该区域最薄弱", "E": "增强MRI扫描中，突出的椎间盘髓核通常呈明显均匀强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-08", "kp": "脊柱病变影像诊断", "ch": "七、影像诊断学基础 → 5.脊柱与四肢关节 → 脊柱病变影像诊断", "ex": "【为什么对】A正确：CT横断面椎间盘突出直接征象为间盘后缘局限性超出椎体终板边缘。B正确：MRI分型确为膨出、突出、脱出、游离四级。C正确：Schmorl结节是椎间盘经终板薄弱区向椎体内疝入。D正确：后外侧型最常见——后纵韧带中线较厚而两侧薄弱。【为什么错】E错误：正常椎间盘无血供，突出髓核通常不强化或仅边缘轻度强化（肉芽组织）。明显均匀强化应考虑椎间盘炎或肿瘤。", "tr": "E是主要陷阱——突出髓核本身无血供不强化，但周围肉芽组织可出现边缘强化。明显均匀强化是椎间盘炎的典型表现。", "bk": "副高", "ref": {"篇": "骨与骨关节", "章": "正常脊柱", "节": "脊柱的发生", "页": 274}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-039", "t": "单选题", "s": "成人胸部后前位（PA位）摄影的标准体位要求不包括", "o": {"A": "患者站立，前胸紧贴探测器/IP板", "B": "双肘弯曲、手背置于髋部，使肩胛骨外展离开肺野", "C": "X线管焦点-探测器距离（SID）为100cm", "D": "深吸气后屏气曝光", "E": "中心线对准第6胸椎水平（肩胛骨下角水平）"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-01", "kp": "胸部X线摄影技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → 胸部X线摄影技术", "ex": "【为什么对】本题要求选不正确的选项。成人胸部后前位标准SID应为180cm（或至少150cm以上），而非100cm。使用长SID目的是减小心脏/纵隔的几何放大失真和减少散射。【为什么错】A正确：后前位即前胸贴板。B正确：手背置髋部外展肩胛骨是标准操作。D正确：深吸气后屏气可最大限度扩张肺野。E正确：中心线对应T6（约肩胛骨下角水平）。", "tr": "SID距离是胸部摄影最常见考点。各部位标准SID：胸部PA 180cm，腹部 100cm，四肢 100cm，脊柱 100cm。考生容易将胸部SID与腹部/四肢SID（均为100cm）混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-040", "t": "多选题", "s": "关于乳腺X线摄影（钼靶）的技术要点，以下正确的是", "o": {"A": "乳腺摄影使用钼（Mo）或铑（Rh）靶X线管，产生低能特征X线（17.5keV和19.6keV），以提高乳腺软组织的对比度", "B": "乳腺摄影常规采用头尾位（CC）和内外斜位（MLO）两个基本体位", "C": "乳腺摄影必须使用压迫装置，目的是降低辐射剂量、减少散射、提高对比度和减少运动伪影", "D": "数字化乳腺断层融合摄影（DBT）可以在不增加辐射剂量的前提下提高病变检出率", "E": "隆胸术后患者乳腺摄影需采用特殊技术（Eklund法），将假体推开后压迫乳腺组织"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-02", "kp": "乳腺X线摄影技术", "ch": "八、普通X线检查技术 → 2.乳腺与口腔X线摄影检查 → 乳腺X线摄影技术", "ex": "【为什么对】A正确：钼靶利用17.5keV和19.6keV特征辐射优化软组织对比。B正确：CC和MLO是标准基本体位。C正确：压迫可降低厚度→降低剂量、减少散射→提高对比度、固定乳房→减少运动伪影。E正确：Eklund法将假体推向胸壁后压迫前方乳腺组织。【为什么错】D错误：DBT通过多角度低剂量扫描减少组织重叠，但通常需附加额外剂量——虽然合成2D图像可适当替代传统2D扫描控制总剂量，但单独DBT扫描剂量不一定低于2D。", "tr": "D是典型陷阱——DBT与剂量关系复杂。“不增加辐射剂量”是过度绝对化表述。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-041", "t": "案例分析题", "s": "上消化道钡餐造影检查中，以下哪种征象是食管静脉曲张的特征性表现", "o": {"A": "食管黏膜皱襞增粗、迂曲，呈“串珠样”或“蚯蚓样”充盈缺损", "B": "食管下段鸟嘴样狭窄伴近端扩张", "C": "食管中段光滑的圆形充盈缺损", "D": "食管全程僵硬、蠕动消失", "E": "食管黏膜不规则龛影"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-03", "kp": "消化道造影技术", "ch": "八、普通X线检查技术 → 3.X线造影检查 → 消化道造影技术", "ex": "【为什么对】食管静脉曲张在钡餐造影中表现为食管中下段黏膜皱襞增粗、迂曲，呈特征性“串珠样”或“蚯蚓样”充盈缺损（曲张静脉突入食管腔），管壁柔软、蠕动存在，严重时可累及全程。是肝硬化门静脉高压的重要提示。【为什么错】B：食管下段鸟嘴样狭窄是贲门失弛缓特征。C：光滑圆形充盈缺损见于食管平滑肌瘤。D：全程僵硬+蠕动消失是硬皮病食管典型表现。E：黏膜不规则龛影见于食管癌（溃疡型）或反流性食管炎。", "tr": "注意鉴别：贲门失弛缓（B）=鸟嘴征/“萝卜根”征+近端扩张；食管癌=黏膜破坏/不规则充盈缺损/龛影/管壁僵硬；食管静脉曲张=串珠样/蚯蚓样充盈缺损+管壁柔软。三个消化道造影经典征象容易混淆，需要记忆各自特点和对应疾病。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-042", "t": "单选题", "s": "静脉肾盂造影（IVP）检查中，注射对比剂后通常拍摄的时间节点不包括", "o": {"A": "注射后即刻（肾实质显影期）", "B": "注射后5分钟", "C": "注射后15分钟", "D": "注射后30分钟", "E": "注射后60分钟"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-04", "kp": "泌尿系统造影技术", "ch": "八、普通X线检查技术 → 3.X线造影检查 → 泌尿系统造影技术", "ex": "【为什么对】IVP标准摄片时间：①腹部平片（注射前）；②5-7分钟（肾盂肾盏显影）；③15分钟（输尿管显影）；④30分钟（膀胱显影）；⑤必要时60分钟延迟片。“注射后即刻”不是标准时间点——对比剂需约3-5分钟才能经肾小球滤过到达肾盂肾盏。【为什么错】B、C、D、E均为常规或必要时时间点。", "tr": "部分考生可能认为注射后即刻也需拍片（观察肾实质显影）。但IVP中对比剂需经滤过过程，注射后即刻片缺乏诊断价值。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-043", "t": "多选题", "s": "关于骨骼系统X线摄影的体位选择原则，以下正确的是", "o": {"A": "四肢长骨摄影应至少包含一端关节，正侧位互相垂直", "B": "怀疑舟骨骨折，常规腕关节正侧位已足够，不需特殊体位", "C": "颈椎外伤患者首选颈椎CT，在排除不稳定骨折后方可行颈椎X线摄影", "D": "脊柱全长正侧位摄影用于评估脊柱侧弯，SID应≥180cm以减少放大失真", "E": "面骨骨折需拍摄Water位（顶颏位），用于评估上颌窦和眶底"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-05", "kp": "骨骼系统X线摄影体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → 骨骼系统X线摄影体位", "ex": "【为什么对】A正确：长骨摄片必须包含一端关节+正侧位90°垂直。C正确：颈椎外伤尤其不稳定骨折，X线体位摆放可能加重脊髓损伤，应首选CT。D正确：脊柱全长片需长SID（≥180cm）减轻几何放大和拼接误差。E正确：Water位是评估面中部骨折的标准体位。【为什么错】B错误：舟骨骨折常规腕关节正侧位极易漏诊（检出率仅约70%），必须加拍舟骨特殊位——手腕尺偏位（舟骨位），使舟骨长轴平行于探测器。", "tr": "B是经典考点——舟骨骨折因特殊解剖和血供特点漏诊后果严重。必须加拍“舟骨位”（腕关节尺偏、后前位、球管向头侧倾斜10-20°）。“常规正侧位已足够”是明显错误信号。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-044", "t": "案例分析题", "s": "患者男性，35岁，因突发右侧胸痛伴呼吸困难2小时急诊入院。临床怀疑右侧气胸。作为放射科技师，以下处理方案正确的是", "o": {"A": "立即拍摄胸部后前位（PA）片，如患者不能站立则改拍卧位前后位（AP）", "B": "气胸在卧位片上表现为“深沟征”（deep sulcus sign）——患侧肋膈角加深、透亮度增高", "C": "呼气相胸片可增加气胸的检出敏感性——肺含气量减少而胸膜腔内气体量不变，使肺与气胸的密度对比加大", "D": "拍摄胸片后应立即电话通知临床医生初步结果（口头报告），无需等待正式诊断报告", "E": "如果胸片阴性但临床高度怀疑，建议行胸部CT检查（CT是检测少量气胸最敏感的方法）"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-06", "kp": "急诊胸部X线摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → 急诊胸部X线摄影", "ex": "【为什么对】五项处理方案均正确。A：PA立位为标准体位，无法站立改卧位AP。B：卧位时气体移至前外侧，“深沟征”是卧位气胸最重要X线征象。C：呼气相肺体积缩小而胸膜腔内气体量不变，气胸相对比例增大更易检测。D：急诊危重情况下技师发现明确异常应启动危急值通报流程。E：CT是检测少量气胸的金标准，敏感性接近100%。【为什么错】无错误选项。", "tr": "部分考生可能对C（呼气相摄影）存疑——认为常规是吸气相拍摄。但呼气相胸片是专门针对气胸检测的特殊技术。“深沟征”（B）是卧位气胸最重要的直接X线征象。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-045", "t": "单选题", "s": "关于子宫输卵管造影（HSG），以下描述错误的是", "o": {"A": "HSG应安排在月经干净后3-7天内进行", "B": "造影剂首选水溶性非离子型碘对比剂而非碘化油", "C": "正常输卵管在造影片上应显示对比剂从伞端溢出进入腹腔（“腹膜涂抹征”阳性）", "D": "HSG检查前应常规进行碘过敏皮试", "E": "一侧输卵管不显影可能系输卵管痉挛所致，可注射解痉药物后复查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-07", "kp": "妇科造影技术", "ch": "八、普通X线检查技术 → 3.X线造影检查 → 妇科造影技术", "ex": "【为什么对】本题要求选出错误选项。D表述错误——碘对比剂过敏皮试对预测严重过敏反应灵敏度和特异度均极低，国内外专业学会已不推荐常规进行碘过敏皮试。HSG使用水溶性非离子型碘对比剂，不需皮试。【为什么错】A正确：月经干净后3-7天进行可避免月经期干扰和排卵后可能的早期妊娠风险。B正确：水溶性对比剂安全性和便捷性优于碘化油。C正确：对比剂自伞端弥散入腹腔是输卵管通畅的直接证据。E正确：输卵管痉挛可导致假性阻塞，使用解痉剂后可复查确认。", "tr": "D关于碘过敏皮试的陷阱——ACR和ESUR均明确建议不推荐常规皮试。E中输卵管痉挛导致假性阻塞概念也很重要——HSG报告的阻塞中有相当部分是功能性痉挛。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-046", "t": "多选题", "s": "关于X线摄影中散射线的控制方法，以下正确的是", "o": {"A": "使用滤线栅（grid）是控制散射线最有效的方法，滤线栅比（grid ratio）越大散射消除能力越强", "B": "缩小照射野（准直器调节）可以减少组织受照体积，从而减少散射线产生", "C": "使用空气间隙技术（增加物体-探测器距离）可替代滤线栅，其原理是散射线各向同性“发散”而初级射线方向性好", "D": "KVp越高散射线产生越多，因此在满足穿透力的前提下应使用尽可能低的KVp", "E": "目前数字X线系统广泛采用虚拟滤线栅技术，可完全替代物理滤线栅"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-08", "kp": "散射线控制技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → 散射线控制技术", "ex": "【为什么对】A正确：滤线栅通过铅条选择性吸收斜入射散射线。栅比越大清除越彻底。B正确：缩小照射野→受照体积减小→散射线减少，是最基本的散射线控制手段。C正确：空气间隙技术利用散射线发散性与初级线方向性差异。D正确：KVp增高→康普顿散射占比增加→散射线增多。【为什么错】E错误：虚拟滤线栅（软件后处理算法）可在一定程度上抑制散射效应，但无法完全替代物理滤线栅——物理滤线栅在信号采集前就去除散射线，虚拟滤线栅后处理无法恢复已混入散射信号的低对比度信息损失。", "tr": "E使用“完全替代”绝对化措辞制造陷阱。虚拟滤线栅在移动DR、床旁摄影等场景可减少物理滤线栅使用，但物理滤线栅的“事前”优势是软件“事后”处理无法完全弥补的。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-047", "t": "单选题", "s": "下列哪项不是多层螺旋CT相对于单层螺旋CT的优势", "o": {"A": "扫描速度更快，Z轴覆盖范围更大", "B": "Z轴空间分辨率提高，可实现各向同性成像", "C": "球管热容量需求大幅降低", "D": "时间分辨率提高，有利于心脏成像", "E": "对比剂使用效率更高（相同碘量下强化效果更好）"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-01", "kp": "多层螺旋CT技术特点", "ch": "九、CT检查技术 → 1.CT检查基本知识 → 多层螺旋CT技术特点", "ex": "【为什么对】本题要求选出不是优势的选项。C表述错误——多层螺旋CT扫描速度更快、数据采集量更大，对球管热容量需求实际上是大幅增加而非降低。MDCT要求球管能承受连续长时间螺旋扫描（如多期增强、大范围CTA），球管热容量通常需要5-8MHU甚至更高。【为什么错】A、B、D、E均为MDCT实际优势。A：多排探测器同时采集实现快速大范围扫描。B：亚毫米准直+薄层重建实现各向同性。D：快速机架转速（≤0.35s）提高时间分辨率。E：扫描速度更快可在对比剂峰值浓度期间完成采集，使用效率更高。", "tr": "部分考生可能误认为MDCT扫描快→球管负荷小→热容量需求低（C）。但实际正相反：MDCT的快速连续扫描、多期增强等技术对球管热容量和散热能力提出了更高要求。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-048", "t": "单选题", "s": "在CT扫描参数中，降低管电流（mAs）最主要的影响是", "o": {"A": "降低空间分辨率", "B": "增加图像噪声", "C": "改变CT值", "D": "增加部分容积效应", "E": "降低时间分辨率"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-02", "kp": "CT扫描参数对图像质量的影响", "ch": "九、CT检查技术 → 1.CT检查基本知识 → CT扫描参数对图像质量的影响", "ex": "【为什么对】管电流（mAs）决定X线光子数量。降低mAs→到达探测器的光子数减少→量子噪声增加→图像噪声增大（噪声与1/√mAs成正比）。这是CT低剂量技术的核心权衡：降低辐射剂量（降低mAs）以增加噪声为代价。【为什么错】A空间分辨率主要由准直/层厚/重建算法/FOV/矩阵决定，与mAs关系不大（仅极低mAs时噪声严重致细节模糊）。C CT值由物质线衰减系数决定，与mAs无关（除非噪声导致测量误差增大）。D部分容积效应由层厚和病灶大小决定。E时间分辨率由机架转速决定。", "tr": "考生可能误选A——认为降低mAs会降低空间分辨率。mAs降低主要增加噪声（使颗粒感增强），但空间分辨率（边缘锐利度/细节分辨）主要由几何参数和重建算法决定。极低剂量时噪声可能淹没细节，但空间分辨率本身不直接由mAs决定。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-049", "t": "案例分析题", "s": "关于CT增强扫描的时相选择，以下正确的是", "o": {"A": "肝脏增强扫描常规采用三期扫描：肝动脉期（注射后20-30s）、门静脉期（60-70s）、延迟期（3-5min）", "B": "胰腺增强扫描的双期包括胰腺实质期（35-40s）和门静脉期（60-70s），胰腺实质期对胰腺癌检出最重要", "C": "肾脏增强扫描包括皮质期（25-30s）、皮髓质期（70-90s）和排泄期（3-5min）", "D": "主动脉CTA触发阈值通常设置在升主动脉100-150HU，采用自动触发（bolus tracking）技术", "E": "肝脏动脉晚期是肝细胞肝癌检出的最佳时相，此时肝癌强化最明显而肝实质尚未强化"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-03", "kp": "CT增强扫描时相技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → CT增强扫描时相技术", "ex": "【为什么对】五项均正确。A：肝脏三期扫描为标准方案（动脉晚期+门脉期+延迟期）。B：胰腺实质期（35-40s）对胰腺癌（低血供）与明显强化的胰腺实质对比最佳。C：肾脏三期皮质期-皮髓质期-排泄期为标准方案。D：主动脉CTA bolus tracking触发阈值通常100-150HU于升主动脉。E：肝动脉晚期（注射后约35s）肝癌由肝动脉供血强化而肝实质仍主要门静脉供血未强化，形成最大对比。【为什么错】无错误选项。", "tr": "E需注意——肝动脉晚期不等于动脉早期。肝动脉早期（20-25s）仅有动脉显影；动脉晚期（30-35s）肝癌强化达峰、门静脉开始显影但肝实质尚未明显强化——这才是肝癌最佳检出时相。“动脉晚期”这一精确表述是区分点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-050", "t": "案例分析题", "s": "患者男性，58岁，因胸痛伴气促行胸部CTA检查，临床怀疑急性主动脉综合征（AAS）。以下关于扫描方案和影像分析的描述，正确的有哪些", "o": {"A": "主动脉CTA应覆盖范围从胸廓入口至耻骨联合下缘（包括髂动脉分叉），以全面评估主动脉全程", "B": "扫描方向应为头-足方向，以配合对比剂血流方向和减少对比剂用量", "C": "应采用心电门控技术以消除主动脉根部和升主动脉的搏动伪影", "D": "主动脉壁间血肿（IMH）在CT平扫上表现为主动脉壁新月形或环形高密度增厚（“高密度新月征”），增强扫描无强化", "E": "穿透性主动脉溃疡（PAU）表现为主动脉壁“龛影”样突出，伴周围壁间血肿"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-04", "kp": "主动脉CTA检查技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 主动脉CTA检查技术", "ex": "【为什么对】五项均正确。A：主动脉CTA需覆盖全程（胸+腹主动脉至髂动脉分叉）。B：头-足方向扫描配合血流方向可减少对比剂用量并优化强化一致性。C：心电门控（前瞻性或回顾性）对消除主动脉根部搏动伪影至关重要，尤其在评估主动脉瓣和冠脉开口时。D：IMH为主动脉滋养血管破裂致壁内出血，平扫呈高密度新月征（急性期CT值60-70HU），增强无强化是与主动脉夹层鉴别核心。E：PAU是主动脉粥样硬化斑块穿透内膜形成溃疡，表现为壁龛影样突出。【为什么错】无错误选项。", "tr": "AAS三种类型（主动脉夹层、IMH、PAU）的CT鉴别特征是高频考点：夹层=内膜片+双腔；IMH=壁内高密度新月征+无内膜片+无强化；PAU=溃疡龛影+壁间血肿。三者可共存或转化。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-051", "t": "单选题", "s": "颅脑CT扫描的基线（OM线）是指", "o": {"A": "眶下缘-外耳道上缘连线", "B": "眶上缘-外耳道下缘连线", "C": "眶下缘-外耳道下缘连线", "D": "眶上缘-外耳道上缘连线", "E": "鼻根-枕外隆凸连线"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-05", "kp": "颅脑CT扫描技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 颅脑CT扫描技术", "ex": "【为什么对】OM线（Orbitomeatal line，听眦线）是指眶下缘（眶下缘最低点）至外耳道上缘的连线，是颅脑CT扫描最常用的基线。扫描层面通常与此线平行或向上倾斜10-15°（与眶耳线平行，即Reid基线），以减少晶状体辐射剂量。【为什么错】B眶上缘-外耳道下缘连线不是标准OM线。C眶下缘-外耳道下缘连线为Reid基线（人类学基线）。D不是标准基线。E鼻根-枕外隆凸连线不是CT基线。", "tr": "OM线与Reid基线容易混淆：OM线=眶下缘-外耳道上缘（听眦线）；Reid基线=眶下缘-外耳道下缘（下缘比上缘略低约1cm）。CT扫描常用OM线，脑血管造影常用Reid基线（眶下缘-外耳道下缘）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-052", "t": "案例分析题", "s": "关于冠状动脉CTA的检查技术要点，以下正确的是", "o": {"A": "患者心率控制是冠脉CTA成功的关键，理想心率应<65次/分且心律规整", "B": "扫描前3-5分钟舌下含服硝酸甘油可扩张冠脉提高血管显示质量", "C": "前瞻性心电门控（prospective gating）较回顾性门控辐射剂量显著降低，但要求稳定的低心率", "D": "重度钙化（Agatston积分>400）会显著影响冠脉CTA的管腔狭窄评估准确性", "E": "碘对比剂注射方案通常采用双筒高压注射器：对比剂50-80ml+生理盐水30-50ml（团注追踪触发）"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-06", "kp": "冠状动脉CTA扫描技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 冠状动脉CTA扫描技术", "ex": "【为什么对】五项均正确。A：心率<65bpm且规整是冠脉CTA理想条件（高心率需使用β受体阻滞剂控制）。B：硝酸甘油扩张冠脉提高显示质量，为常规操作。C：前瞻性门控仅采集心脏特定时相数据&辐射剂量大幅降低（可低至1-3mSv），但要求稳定低心率。D：重度钙化产生晕状伪影和Blooming效应，高估狭窄程度，是冠脉CTA的主要局限性。E：双筒注射器对比剂+盐水追注为标准方案。【为什么错】无错误选项。", "tr": "全选，考生需注意前瞻性门控与回顾性门控的选择：前瞻性门控=低剂量+需要稳定低心率（<65bpm且规整）；回顾性门控=高剂量+可回顾性选择最佳时相+可评估心功能。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-053", "t": "单选题", "s": "腹部CT检查中，口服对比剂的主要作用是", "o": {"A": "提高肝脏CT值", "B": "充盈胃肠道以区分肠管与腹腔占位", "C": "降低辐射剂量", "D": "减少呼吸运动伪影", "E": "增强胰腺强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-07", "kp": "腹部CT检查技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 腹部CT检查技术", "ex": "【为什么对】腹部CT口服对比剂（阳性对比剂如2%泛影葡胺溶液或中性对比剂如水）的主要作用是充盈胃肠道管腔，使肠管与腹腔占位、淋巴结、血管等结构可区分。未充盈的肠管可被误认为腹腔肿块或淋巴结。【为什么错】A口服对比剂不进入血液不提高肝实质CT值。C口服对比剂不降低辐射剂量。D口服对比剂不能减少运动伪影（肠蠕动伪影可用低张药如654-2控制）。E口服对比剂不增强胰腺强化（胰腺增强依赖静脉注射对比剂）。", "tr": "考生需区分口服对比剂和静脉对比剂的作用：口服对比剂→填充肠腔（区分肠管与腹腔结构）；静脉对比剂→显示血管和脏器灌注特征。两者目的完全不同不可混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-054", "t": "多选题", "s": "关于CT低剂量扫描技术，以下正确的是", "o": {"A": "自动管电流调制（ATCM）可根据患者体型和解剖部位自动调整mA，是降低辐射剂量最常用的技术", "B": "降低管电压（kVp）可显著降低辐射剂量（剂量∝kVp²），同时可提高碘对比剂的强化效果（因碘的K缘效应）", "C": "迭代重建（IR）算法可在相同剂量下降低图像噪声，或在保持相同噪声的前提下降低辐射剂量", "D": "器官剂量调制技术（如乳腺/甲状腺前屏蔽）可选择性降低敏感器官的辐射剂量", "E": "CT透视（fluoroscopy）引导下穿刺可以明显降低辐射剂量"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-08", "kp": "CT低剂量技术", "ch": "九、CT检查技术 → 1.CT检查基本知识 → CT低剂量技术", "ex": "【为什么对】A正确：ATCM是CT低剂量最基础和最常用技术（纵向+角度双调制）。B正确：降低kVp可大幅降低剂量（剂量∝kVp²）且碘对比剂在低kVp下因靠近K缘（33.2keV）而强化更明显（光电效应增强）。C正确：迭代重建是低剂量CT的核心技术——FBP在低剂量下噪声大，IR可有效降噪。D正确：器官剂量调制如乳腺屏蔽、甲状腺屏蔽等技术可选择性降低敏感器官剂量。【为什么错】E错误：CT透视引导下穿刺操作辐射剂量往往较高（持续曝光监控穿刺针位置），并非降低剂量的技术——反而是需要重点关注辐射防护的环节。", "tr": "E是典型陷阱——CT透视因持续曝光，操作者和患者的辐射剂量均较高，需要严格防护措施（如使用低mA透视模式、间歇性扫描代替连续透视等）。“引导穿刺”不等于“降低剂量”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-055", "t": "单选题", "s": "CT图像重建中，骨算法（bone algorithm）与标准算法的根本区别在于", "o": {"A": "使用不同的矩阵大小", "B": "使用不同的重建滤波函数（kernel）——骨算法强调高频信息", "C": "使用不同的FOV", "D": "使用不同的层厚", "E": "使用不同的窗宽窗位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-09", "kp": "CT图像重建算法", "ch": "九、CT检查技术 → 1.CT检查基本知识 → CT图像重建算法", "ex": "【为什么对】CT图像重建中，骨算法与标准算法的根本区别在于卷积核（kernel/filter）的选择——骨算法使用高频增强滤波函数（锐利核/sharp kernel），强化边缘和细节，适合显示骨质和肺纹理；标准算法使用平滑滤波函数（smooth kernel），降低噪声，适合软组织显示。【为什么错】A矩阵大小可独立设置，非算法区别。C FOV可独立调整。D层厚独立于重建算法。E窗宽窗位是显示参数（后处理）非重建参数，且骨窗（WW2000/WL500）和软组织窗（WW350/WL50）使用的是不同的窗值设定而非重建算法本身。", "tr": "考生常混淆重建算法（kernel）与窗口技术（WW/WL）：骨算法=锐利核（重建时使用），骨窗=宽窗宽高窗位（显示时使用）。两者经常配合使用但本质不同——重建算法影响原始数据的图像生成方式，窗口技术仅影响显示方式。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-056", "t": "多选题", "s": "关于CT尿路造影（CTU）的检查技术，以下正确的是", "o": {"A": "CTU通常包括平扫（KUB）、增强实质期和排泄期三个时相", "B": "排泄期扫描通常在注射对比剂后5-10分钟进行，以显示肾盂肾盏和输尿管的对比剂充盈", "C": "CTU的排泄期图像经MIP/VR后处理可生成类似IVP的“三维尿路造影”图像", "D": "为促进对比剂排泄，可在注射对比剂后静脉推注呋塞米（速尿）10-20mg", "E": "CTU的辐射剂量通常低于常规IVP检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-10", "kp": "CT尿路造影技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → CT尿路造影技术", "ex": "【为什么对】A正确：CTU标准方案=平扫+实质期（肾增强）+排泄期（尿路充盈）。B正确：排泄期通常在5-10分钟（正常肾功能），肾功能减退者需延迟更久。C正确：MIP/VR后处理可从排泄期数据生成类似IVP的尿路造影图像。D正确：呋塞米可促进利尿、加速对比剂排泄，优化尿路充盈（尤其输尿管中下段）。【为什么错】E错误：CTU辐射剂量通常显著高于IVP——CTU为多时相扫描（至少2-3次），总DLP可>20mGy·cm；而IVP为单片X线摄影，剂量较低。但CTU的诊断信息量也远大于IVP。", "tr": "E是常见误区——CTU虽然诊断价值高于IVP，但辐射剂量也明显更高。目前IVP已基本被CTU替代，但在某些场景（如年轻女性、需避免高辐射）IVP仍有一席之地。“通常低于IVP”不符合事实。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-057", "t": "案例分析题", "s": "患者男性，65岁，体检超声发现右肾中部一个约2cm的低回声结节。行肾脏CT平扫+多期增强检查。以下关于扫描方案和影像分析，正确的有哪些", "o": {"A": "肾脏CT扫描范围应包括双肾全部（从肾上级至肾下级），层厚≤3mm以利于小病灶检测", "B": "增强扫描皮质期（25-30s）可显示肾皮质强化而髓质尚未强化（皮质-髓质分界清晰），此期有利于肾皮质小肿瘤检测", "C": "肾透明细胞癌典型表现为{LQ}快进快出{RQ}——皮质期明显不均匀强化、皮髓质期强化程度迅速下降", "D": "CT平扫是检出肾结石最敏感的手段，所有肾结石（包括尿酸结石）均可在CT平扫上清晰显示", "E": "肾血管平滑肌脂肪瘤（AML）的CT诊断依据是病灶内含“肉眼可见”的脂肪密度（CT值<-10HU）"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-11", "kp": "肾脏CT检查技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 肾脏CT检查技术", "ex": "【为什么对】A正确：肾脏CT小病灶检测需薄层（≤3mm）扫描。B正确：皮质期（25-30s）皮质强化、髓质未强化，形成皮质-髓质分界，有利于皮质小肿瘤检测。C正确：肾透明细胞癌典型强化模式为皮质期明显不均匀强化+皮髓质期/实质期强化迅速减退。E正确：AML确诊依据为病灶内含脂肪密度（CT值<-10HU），因AML含成熟脂肪组织+血管+平滑肌三种成分。【为什么错】D错误：并非所有肾结石均在CT平扫上清晰显示——茚地那韦（抗HIV药物）所致结石和少数纯尿酸结石在CT上可呈等密度或低密度而难以检出。虽然绝大多数（>95%）肾结石CT可清晰显示，但{D}使用“所有”一词绝对化。", "tr": "D使用“所有”绝对化措辞——虽然CT是检出肾结石最敏感手段（敏感性>95%），但茚地那韦结石和少数纯基质结石在CT上密度低可漏诊。考试中“所有”、“一定”等绝对词往往是错误信号。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-058", "t": "案例分析题", "s": "关于CT灌注成像的原理，以下描述错误的是", "o": {"A": "CT灌注使用连续动态扫描监测对比剂在兴趣组织中的首次通过过程", "B": "通过时间-密度曲线（TDC）可计算出血流量（BF）、血容量（BV）、平均通过时间（MTT）和表面通透性（PS）", "C": "CT灌注成像的辐射剂量较低，与常规CT平扫相当", "D": "脑CT灌注主要用于急性脑梗死缺血半暗带的评估", "E": "体部CT灌注可用于肿瘤血管生成的评价和抗血管生成治疗疗效评估"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-12", "kp": "CT灌注成像", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → CT灌注成像", "ex": "【为什么对】本题要求选出错误选项。C错误——CT灌注成像需在同一层面进行连续动态扫描（通常30-60次扫描），辐射剂量远高于常规CT平扫（可为常规平扫的10-50倍），是CT灌注的主要限制之一。【为什么错】A正确：CT灌注通过动态监测对比剂首次通过过程获取血流动力学参数。B正确：TDC分析可计算BF、BV、MTT、PS等定量参数（基于中心容积定理和去卷积模型）。D正确：脑CT灌注核心应用是急性脑梗死的缺血半暗带评估（CBF/CBV不匹配区）。E正确：体部CT灌注可定量评价肿瘤血管生成（BF、BV、PS增高提示血管丰富），用于抗血管生成治疗疗效评估。", "tr": "CT灌注辐射剂量高是其重要缺点，考生容易低估——因涉及连续动态扫描（每次扫描间隔1-3秒，持续40-60秒），总扫描次数多，辐射剂量远远超过常规检查。这也是限制CT灌注广泛应用的主要因素之一。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-059", "t": "多选题", "s": "关于CT引导下穿刺活检，以下正确的是", "o": {"A": "CT引导的优势在于精确定位、可避开重要结构（大血管、肠道等）", "B": "穿刺路径设计应遵循最短距离原则，同时避开叶间裂、大血管和重要脏器", "C": "肺内小结节（<1cm）穿刺时，气胸是最常见的并发症", "D": "使用同轴穿刺针技术可一次穿刺多次取样，提高诊断率并降低并发症", "E": "凝血功能异常（INR>1.5，PLT<50×10⁹/L）不是穿刺活检的禁忌，可常规进行"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-13", "kp": "CT引导下介入技术", "ch": "九、CT检查技术 → 3.检查方法 → CT引导下介入技术", "ex": "【为什么对】A正确——CT引导提供三维解剖信息，可精确定位并设计避开大血管、肠道等危险结构的路径。B正确——最短距离且避开叶间裂、大血管与重要脏器是穿刺路径设计基本原则。C正确——肺小结节（<1 cm）穿刺气胸发生率约20%–30%，是最常见并发症。D正确——同轴针技术一次置管可多次取样，提高诊断率并降低反复穿刺所致气胸/出血。【为什么错】E错误——凝血功能障碍（INR>1.5或PLT<50×10⁹/L）显著增加穿刺后出血风险，属相对禁忌证，须先纠正凝血指标再施术，绝非“可常规进行”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——凝血功能障碍（INR>1.5或PLT<50×10⁹/L）显著增加穿刺后出血风险，属相对禁忌证，须先纠正凝血指标再施术，绝非“可常规进行”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-060", "t": "单选题", "s": "以下关于螺距（pitch）的描述，错误的是", "o": {"A": "螺距=进床速度（mm/圈）/准直宽度（mm）", "B": "螺距增大可缩短扫描时间、减少辐射剂量", "C": "螺距增大会导致Z轴空间分辨率下降和部分容积效应增加", "D": "螺距>1时扫描存在数据间隙，需通过插值填补", "E": "螺距为0表示螺旋扫描，螺距为1表示轴向扫描"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-14", "kp": "CT螺距概念", "ch": "九、CT检查技术 → 1.CT检查基本知识 → CT螺距概念", "ex": "【为什么对】本题要求选错误选项。E错误——螺距（pitch）是螺旋扫描参数，定义为进床速度/准直宽度。pitch>0即为螺旋扫描，pitch=0不存在（没有进床即不是螺旋扫描）。轴向扫描不涉及螺距概念。螺距=1表示进床速度等于准直宽度（相邻螺旋圈刚好衔接），螺距<1表示重叠扫描（剂量增高），螺距>1表示数据有间隙。【为什么错】A正确：螺距标准定义。B正确：螺距增大→扫描覆盖更快→扫描时间短、辐射剂量降低。C正确：螺距增大→Z轴采样密度降低→SSP展宽→Z轴分辨率下降。D正确：螺距>1时螺旋圈间存在数据间隙，需通过360°或180°插值算法重建缺失数据。", "tr": "E中“螺距为0”和“螺距为1表示轴向扫描”均为概念错误：轴向扫描（步进式）根本不涉及螺距概念。简单记忆：pitch=进床速度/准直宽度，pitch>0即为螺旋扫描。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-061", "t": "单选题", "s": "以下哪项是MRI检查的绝对禁忌证", "o": {"A": "体内有心脏起搏器（非MRI兼容型）", "B": "金属烤瓷牙", "C": "人工髋关节置换术后（非磁性材料）", "D": "宫内节育器", "E": "冠状动脉支架（术后>6周）"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-01", "kp": "MRI禁忌证与安全筛查", "ch": "十、MR检查技术 → 1.MR检查准备 → MRI禁忌证与安全筛查", "ex": "【为什么对】非MRI兼容型心脏起搏器是MRI检查的绝对禁忌证——强磁场可能导致起搏器功能紊乱（导线感应电流、簧片开关误触发、电池耗竭等），危及生命。现代MRI兼容起搏器（MR Conditional）在特定条件下可安全检查。【为什么错】B金属烤瓷牙通常为镍铬合金或贵金属，虽可产生伪影但不属绝对禁忌。C非磁性材料人工关节（钛合金等）在MRI中是安全的。D宫内节育器（多数为铜或含塑料）在1.5T及以下场强通常安全（>3.0T需确认）。E冠脉支架（裸金属或DES）术后>6周通常安全（已完全内皮化），多数现代支架为MRI兼容。", "tr": "考生需严格区分绝对禁忌证与相对禁忌证。非MRI兼容起搏器=绝对禁忌；金属植入物需分情况判断：非铁磁性材料（钛合金、镍钛合金等）=安全；铁磁性材料（部分老旧动脉瘤夹等）=绝对禁忌。多数现代植入物标注MRI Conditional。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-062", "t": "多选题", "s": "关于MRI检查的安全管理，以下正确的是", "o": {"A": "所有进入MRI扫描室的人员（包括陪护家属和医务人员）都必须经过严格的安全筛查", "B": "MRI扫描室的强磁场始终存在（24h/7d），即使未进行扫描时磁场也不会关闭", "C": "1高斯线（1 G line）是MRI扫描室的安全控制边界，起搏器佩戴者严禁进入1G线以内", "D": "造影剂过敏反应在MRI增强检查中也可能发生（钆剂过敏），扫描室应配备急救设备", "E": "金属异物（如眼内铁屑、体内弹片）在MRI检查中可能发生移位或产热导致组织损伤"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-02", "kp": "MRI安全管理", "ch": "十、MR检查技术 → 1.MR检查准备 → MRI安全管理", "ex": "【为什么对】A正确——所有进入扫描室人员（含陪护与医务）均须经过严格金属与植入物筛查。B正确——超导MRI主磁场7×24 h始终存在，即使不扫描也不关闭。D正确——钆剂虽过敏率远低于碘剂，仍可发生过敏反应，扫描室须配备急救设备。E正确——铁磁性异物（眼内铁屑、体内弹片）在强磁场中可受力移位或产热，造成组织损伤。【为什么错】C错误——MRI扫描室公认的安全控制边界是5高斯线（5 G line，约0.5 mT），而非1高斯线；高风险铁磁性植入物（如部分起搏器）佩戴者严禁进入5 G线以内区域。", "tr": "本题已将原“全选”改为四项正确；注意选项C为刻意设置的错误项——MRI扫描室公认的安全控制边界是5高斯线（5 G line，约0.5 mT），而非1高斯线；高风险铁磁性植入物（如部分起搏器）佩戴者严禁进入5 G线以内区域。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-063", "t": "单选题", "s": "关于MRI功能成像技术中DWI（弥散加权成像）的原理，以下描述错误的是", "o": {"A": "DWI通过施加弥散敏感梯度（b值）来检测水分子的微观随机运动（布朗运动）", "B": "b值越高，DWI对弥散的敏感性越高，但图像信噪比越低", "C": "ADC图可以消除T2穿透效应的影响，真实反映组织的弥散受限程度", "D": "恶性肿瘤通常表现为DWI高信号+ADC高信号（ADC值升高）", "E": "脑脓肿与脑肿瘤坏死囊变的鉴别中，DWI/ADC具有重要价值"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-03", "kp": "弥散加权成像原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → 弥散加权成像原理", "ex": "【为什么对】本题要求选错误选项。D错误——恶性肿瘤因细胞密度高、核浆比大、细胞外间隙减小，水分子弥散受限，表现为DWI高信号+ADC低信号（ADC值降低），而非ADC高信号。【为什么错】A正确：DWI基础是Stejskal-Tanner脉冲梯度序列检测水分子弥散。B正确：高b值提高弥散权重但降低SNR。C正确：ADC图通过至少两个b值计算得出，可去除T2穿透效应（T2 shine-through），真实反映弥散受限。E正确：脑脓肿腔内含黏稠脓液（大量蛋白和多核白细胞）弥散受限→DWI高信号/ADC低；肿瘤坏死囊变多为清亮液体→DWI低信号/ADC高。这是两者最重要的MRI鉴别点。", "tr": "D将恶性肿瘤的DWI/ADC特征说反——正确关系：恶性肿瘤=细胞密集+弥散受限=DWI高信号+ADC降低。ADC降低是恶性肿瘤的重要特征，良性病变ADC值通常正常或升高。记忆：“ADC降低=恶性”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-064", "t": "案例分析题", "s": "关于MRA（磁共振血管成像）技术，以下正确的是", "o": {"A": "时间飞跃法MRA（TOF-MRA）利用血液流入效应——未饱和的流入血液质子产生高信号", "B": "TOF-MRA对血流方向敏感，通常用于颅内动脉成像（Willis环MRA）", "C": "相位对比法MRA（PC-MRA）利用流动质子的相位变化进行血管成像，可同时提供流速定量信息", "D": "对比增强MRA（CE-MRA）使用钆剂缩短血液T1值，是目前主动脉和外周血管MRA的首选技术", "E": "TOF-MRA的主要缺点是血流信号丢失——涡流、湍流或缓慢血流可致信号丢失而“夸大”狭窄程度"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-04", "kp": "磁共振血管成像技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 磁共振血管成像技术", "ex": "【为什么对】五项均正确。A：TOF利用梯度回波序列中静止组织被反复RF激励而饱和（低信号），新鲜流入血液未饱和（高信号）形成血管对比。B：TOF-MRA是颅内动脉成像最常用技术（3D-TOF）。C：PC-MRA通过双极梯度编码检测流动质子相位变化，可定量流速，广泛用于脑脊液流量分析。D：CE-MRA使用钆剂缩短血液T1，不受血流方向/速度影响，是大血管MRA金标准。E：TOF-MRA最大缺点是血流相关信号丢失——涡流、湍流或极慢血流可致质子饱和而信号丢失，从而高估狭窄。【为什么错】无错误选项。", "tr": "全选。E中TOF高估狭窄是其最重要局限性——狭窄后湍流/涡流导致质子饱和信号丢失，在MRA上表现为信号中断，容易被{LQ}过度诊断{RQ}为重度狭窄或闭塞。结合原始图像和PC-MRA可减少此误判。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-065", "t": "案例分析题", "s": "患者女性，38岁，因反复头痛就诊。头颅MRI平扫+增强检查示：左侧额叶白质内多发小类圆形病灶，部分垂直于侧脑室分布（Dawson手指征），T1WI低信号、T2WI/FLAIR高信号，增强扫描部分病灶呈环形或开环状强化。DWI示部分病灶边缘高信号。", "o": {"A": "该MRI表现高度提示多发性硬化（MS），Dawson手指征是MS的典型特征", "B": "病灶垂直于侧脑室分布提示脱髓鞘病变沿脑室周围静脉走行", "C": "开环状强化提示病灶活动性（急性期），环形强化部分朝向白质侧开口", "D": "脊髓MRI检查对MS的诊断价值不大，可不予检查", "E": "该患者病灶在SWI（磁敏感加权成像）序列上病灶内静脉应显示不清"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-05", "kp": "头颅MRI检查与神经影像诊断", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 头颅MRI检查与神经影像诊断", "ex": "【为什么对】A正确：Dawson手指征（垂直于侧脑室的卵圆形白质病灶）是MS高度特征性表现。B正确：病灶沿脑室周围小静脉（室周静脉）走行，反映MS的静脉周围炎病理基础。C正确：开环状强化（open-ring sign）是MS活动期特征——环形强化不完整，开口朝向灰质/基底节侧。【为什么错】D错误：脊髓MRI对MS诊断价值极大——约80%-90%的MS患者存在脊髓病灶（颈髓最常见），脊髓MRI是MS诊断的重要组成部分（McDonald标准）。E错误：SWI上MS病灶内常可见中心静脉征（central vein sign）——病灶中心可见小静脉呈低信号穿行，是MS区别于其他白质病变的重要特征。SWI病灶内静脉显示不清与MS不符。", "tr": "D和E是关键陷阱。D中“脊髓MRI价值不大”与MS诊断标准严重不符——脊髓MRI是MS诊断常规检查。E中“SWI上静脉显示不清”与MS的中心静脉征特征相反——“中心静脉征”是MS区别于其他白质病变的新型影像标志。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-066", "t": "单选题", "s": "肝脏MRI检查中，以下哪种序列对肝内铁沉积的检测最敏感", "o": {"A": "T1WI同相位/反相位（in-phase/opposed-phase）双回波成像", "B": "T2*WI梯度回波序列", "C": "T2WI FSE序列", "D": "DWI序列", "E": "T1WI增强扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-06", "kp": "腹部MRI检查技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 腹部MRI检查技术", "ex": "【为什么对】T2*WI梯度回波序列对铁沉积最敏感——铁为超顺磁性物质，造成局部磁场不均匀→T2*显著缩短→信号明显降低。肝铁沉积（如血色素沉着症）在T2*WI上表现为肝脏信号弥漫性显著降低（黑肝），且T2*值可定量测量铁浓度。T2*WI GRE序列是肝铁检测和定量的金标准。【为什么错】A同反相位主要用于检测肝细胞内脂肪（脂肪肝）——反相位信号较同相位降低提示脂肪变性，不是铁检测首选。C T2WI FSE使用180°重聚焦脉冲可部分补偿磁场不均匀效应，对铁不如T2*敏感。D DWI也可显示铁沉积但不具特异性。E增强扫描不用于铁沉积检测。", "tr": "考生容易混淆肝铁沉积和肝脂肪变性的MR检测方法：铁沉积→T2*WI GRE（信号明显降低）+T2*定量；脂肪变性→同反相位双回波（反相位信号降低）+MRS/PDFF定量。两者检测序列完全不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-067", "t": "多选题", "s": "关于前列腺MRI（多参数MRI，mp-MRI），以下正确的是", "o": {"A": "mp-MRI包括T2WI、DWI/ADC、DCE（动态增强）三个核心序列，PI-RADS评分基于此三者", "B": "前列腺癌在T2WI上典型表现为周围带高信号背景中的局限性低信号区", "C": "DWI上ADC值显著降低（<800×10⁻⁶mm²/s）高度提示临床有意义的前列腺癌", "D": "DCE的阳性标准是病灶呈{LQ}快进快出{RQ}强化模式（早期快速强化+早期廓清）", "E": "mp-MRI主要用于已确诊前列腺癌的分期，不推荐用于初次穿刺前的病灶检测"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-07", "kp": "前列腺MRI检查技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 前列腺MRI检查技术", "ex": "【为什么对】A正确：PI-RADS v2.1基于T2WI+DWI+DCE三个核心序列进行评分。B正确：周围带正常组织T2WI高信号，癌灶呈低信号。C正确：ADC显著降低（<800或<900）是前列腺癌重要标志（细胞密集→弥散受限）。D正确：DCE阳性标准为病灶早期快速强化（wash-in）+早期廓清（wash-out），即“快进快出”。【为什么错】E错误：mp-MRI最重要的临床应用恰恰是初次穿刺前的病灶检测和定位——对临床怀疑前列腺癌（PSA升高、DRE异常）的患者，mp-MRI可在穿刺前定位可疑病灶，指导靶向穿刺（MRI-TRUS融合穿刺），显著提高临床有意义癌的检出率。", "tr": "E将mp-MRI的主要用途说反——mp-MRI核心价值在于“穿刺前”检测和定位，而非仅用于分期。PI-RADS系统正是为穿刺前风险分层而设计的。“不推荐用于初次穿刺前”与当前国际指南（EAU、NCCN、AUA）推荐严重不符。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-068", "t": "案例分析题", "s": "关于膝关节MRI检查的扫描方位，以下描述错误的是", "o": {"A": "矢状面是膝关节MRI最重要的扫描方位，通常以前交叉韧带（ACL）走行方向为扫描基线", "B": "冠状面用于评估内/外侧副韧带、半月板体部和关节软骨", "C": "横断面用于评估髌骨轨迹和关节积液", "D": "矢状面扫描层厚通常为3-4mm，以保证SNR和层面覆盖", "E": "膝关节MRI常规不需要冠状面扫描，矢状面+横断面即可满足诊断需求"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-08", "kp": "骨关节MRI检查技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 骨关节MRI检查技术", "ex": "【为什么对】本题要求选错误选项。E错误——膝关节MRI常规必须包括三个方位（矢状面+冠状面+横断面）。冠状面对评估内/外侧副韧带、半月板体部和关节软骨至关重要，不可省略。【为什么错】A正确：矢状面以ACL走行为基线（向前内侧倾斜约15°），可最佳显示ACL全长、半月板前后角。B正确：冠状面是评估侧副韧带和半月板体部的最佳方位。C正确：横断面评估髌股关节和积液。D正确：膝关节MRI矢状面层厚通常3-4mm（≤0.3mm像素）。", "tr": "膝关节MRI三方位常规扫描是不可省略的基本要求：矢状面→ACL/PCL+半月板前后角；冠状面→侧副韧带+半月板体部+软骨；横断面→髌股关节+积液。三者各有不可替代的诊断价值。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-069", "t": "单选题", "s": "关于MRI波谱成像（MRS）在脑肿瘤中的应用，以下描述正确的是", "o": {"A": "正常脑组织的NAA（N-乙酰天门冬氨酸）峰是神经元完整性的标志", "B": "Cho（胆碱）峰升高反映细胞膜合成/降解活跃，是肿瘤增殖的标志", "C": "高级别胶质瘤的典型MRS表现为NAA降低+Cho升高+“Lac（乳酸）/Lip（脂质）”峰出现", "D": "MRS可作为脑肿瘤与非肿瘤病变（如脱髓鞘、感染）鉴别的重要辅助手段", "E": "以上均正确"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-09", "kp": "MR波谱成像", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → MR波谱成像", "ex": "【为什么对】以上均正确。A：NAA几乎仅存在于神经元及其突起中，是神经元密度和功能完整性的标志——脑肿瘤（神经元被肿瘤细胞替代）→NAA降低。B：Cho峰反映细胞膜磷脂代谢，肿瘤细胞快速增殖→膜合成活跃→Cho升高。C：高级别胶质瘤→NAA降低+Cho升高+Lac（无氧糖酵解产物，反映缺氧/坏死）+Lip（脂质峰出现反映坏死）。D：MRS代谢物谱特征有助于鉴别肿瘤（NAA↓+Cho↑）与脱髓鞘（NAA可保留+Cho轻度升高）、感染/脓肿（出现特殊代谢物如乙酸、琥珀酸等）。【为什么错】见上述解析中各错误选项分析。", "tr": "本题选项E为以上均正确，需逐项核实。MRS各代谢物峰的临床意义：NAA=神经元标志；Cho=细胞膜增殖标志；Cr（肌酸）=能量代谢参考峰；Lac=无氧代谢/坏死；Lip=坏死/脂肪。脑肿瘤MRS特征：NAA↓+Cho↑+（高级别时Lac/Lip出现）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-070", "t": "多选题", "s": "关于心脏MRI（CMR）检查技术，以下正确的是", "o": {"A": "CMR是评价心脏结构和功能的金标准，可精确测量心室容积、射血分数和心肌质量", "B": "心肌延迟强化（LGE）使用钆剂注射后10-20分钟扫描，存活心肌不强化而纤维化/瘢痕心肌呈高信号", "C": "T2-STIR序列用于检测心肌水肿（如急性心肌炎、急性心梗）", "D": "CMR检查需要心电门控和呼吸门控配合，以消除心脏搏动和呼吸运动伪影", "E": "CMR在心律失常（如频发室早、房颤）患者中仍可获得完美的图像质量"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-10", "kp": "心脏MRI检查技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 心脏MRI检查技术", "ex": "【为什么对】A正确：CMR是心功能测量的金标准（准确性优于超声心动图）。B正确：LGE原理——钆剂在正常心肌中被快速洗脱（存活心肌细胞膜完整），而纤维化/瘢痕心肌因细胞外间隙增大+洗脱缓慢而呈高信号。C正确：T2-STIR对组织游离水增加（水肿）敏感，可用于心肌水肿检测。D正确：CMR需心电门控（触发采集与心脏运动同步）+呼吸门控/屏气（消除呼吸运动伪影）。【为什么错】E错误：心律失常（频发室早、房颤等）会导致心电门控触发异常→数据采集时相不一致→图像出现严重运动伪影，是CMR的常见失败原因。中重度心律失常是CMR的相对禁忌证或限制。", "tr": "E使用“仍可获得完美图像质量”绝对化表述——心律失常恰恰是CMR最常见的技术失败原因。房颤患者CMR常因RR间期不等导致采集窗变化、数据不一致。实时CMR技术（如实时SSFP）可一定程度弥补，但空间和时间分辨率均低于门控采集。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-071", "t": "单选题", "s": "以下哪项不是DSA检查的禁忌证", "o": {"A": "严重碘对比剂过敏史", "B": "严重肾功能不全（eGFR<30ml/min/1.73m²）", "C": "穿刺部位局部感染", "D": "轻度高血压（血压150/90mmHg，控制可）", "E": "妊娠期"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-01", "kp": "DSA禁忌证与适应症", "ch": "十一、DSA检查技术 → 1.检查前准备 → DSA禁忌证与适应症", "ex": "【为什么对】本题要求选出不是禁忌证的选项。D——轻度高血压（150/90mmHg）在血压控制稳定情况下不是DSA的禁忌证，临床可安全进行检查。高血压并非DSA禁忌除非血压极高（如>180/110mmHg）增加穿刺出血风险。【为什么错】A严重碘过敏史是重要禁忌证需改用其他检查（如MRA）或在充分准备下使用钆剂/CO₂造影。B严重肾功能不全（eGFR<30）是碘对比剂使用相对禁忌需充分评估获益/风险+水化+减少对比剂用量。C穿刺部位感染是绝对禁忌（可能导致感染扩散入血）。E妊娠期是相对禁忌（电离辐射+碘对比剂对胎儿潜在危害），仅在获益明确大于风险时进行。", "tr": "考生需区分绝对禁忌和相对禁忌。A、B、C、E均为不同程度的禁忌（C为绝对禁忌），而D轻度高血压不是禁忌。需注意：严重高血压（>180/110mmHg）才是禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-072", "t": "单选题", "s": "在DSA脑血管造影中，颈内动脉造影的标准投照体位不包括", "o": {"A": "后前位（AP位/正位）", "B": "侧位", "C": "斜位（45°）", "D": "颅底位（颏顶位）", "E": "汤氏位（Towne位，30°前后位）"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-02", "kp": "脑血管DSA造影技术", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → 脑血管DSA造影技术", "ex": "【为什么对】本题要求选出不包括的体位。D颅底位（颏顶位）不是颈内动脉DSA造影的标准投照体位——此体位主要用于显示颅底骨结构和部分颅底病变，不是脑血管造影常规体位。【为什么错】A AP正位：显示大脑前动脉（ACA）、大脑中动脉（MCA）及Willis环前后位全貌。B侧位：显示ACA、MCA、大脑后动脉（PCA）的侧位走行，是脑血管造影最基本体位。C 45°斜位：分离ACA和MCA分支，减少血管重叠。E Towne位（30°前后位+头倾）：显示基底动脉系统（后循环）和静脉窦。A、B、C、E均为颈内动脉DSA造影标准体位。", "tr": "颅脑血管DSA标准投照体位：AP正位+侧位+斜位（45°LAO/RAO）+Towne位。颅底位主要用于颅骨病变而非脑血管造影。考生需熟悉各体位的显示优势。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-073", "t": "多选题", "s": "关于DSA肝脏血管造影技术，以下正确的是", "o": {"A": "腹腔干动脉造影是肝脏介入的常规起始步骤，通常在T12-L1水平寻找腹腔干开口", "B": "间接门静脉造影经肠系膜上动脉或脾动脉注射对比剂，通过静脉回流显示门静脉系统", "C": "肝动脉DSA造影可清晰显示肝内肿瘤的异常血管（肿瘤染色、动静脉瘘等）", "D": "DSA的旋转血管造影（3D-DSA）可从多角度观察血管，对动脉瘤、AVM等复杂病变的评估价值极高", "E": "门静脉主干完全阻塞不是TACE的禁忌证，反而可增强疗效"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-03", "kp": "腹部血管DSA技术", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → 腹部血管DSA技术", "ex": "【为什么对】A正确——腹腔干多起于T12–L1水平腹主动脉前壁，是肝脏介入的常规起始造影步骤。B正确——间接门静脉造影经肠系膜上动脉或脾动脉注药，经静脉回流显示门静脉系统。C正确——肝动脉DSA可显示肿瘤染色、新生血管、动静脉瘘等异常血管。D正确——3D-DSA（旋转采集+重建）生成三维血管模型，对动脉瘤、AVM等复杂病变评估价值极高。【为什么错】E错误——门静脉主干完全阻塞时肝实质缺乏门静脉供血，TACE（经动脉化疗栓塞）后正常肝组织难以代偿、肝衰竭风险极高，故属TACE禁忌证，而非“非禁忌、可增强疗效”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——门静脉主干完全阻塞时肝实质缺乏门静脉供血，TACE（经动脉化疗栓塞）后正常肝组织难以代偿、肝衰竭风险极高，故属TACE禁忌证，而非“非禁忌、可增强疗效”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-074", "t": "案例分析题", "s": "患者男性，72岁，因间歇性跛行6个月，临床怀疑下肢动脉硬化闭塞症，将行下肢动脉DSA。以下关于检查方案的描述，正确的有哪些", "o": {"A": "下肢动脉DSA通常采用步进式（bolus chase）技术，从腹主动脉分叉至足部一次造影完成全程", "B": "穿刺入路常规选择对侧股动脉逆行穿刺（cross-over技术），以利于双侧下肢动脉评估", "C": "对比剂注射方案：总量80-120ml，流率8-12ml/s，采用{ LQ}团注追踪{RQ}（bolus chase）技术", "D": "DSA主要并发症包括穿刺部位血肿、假性动脉瘤、对比剂肾病和远端栓塞", "E": "下肢动脉闭塞性病变的DSA表现包括管腔不规则狭窄、闭塞及侧支循环建立"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-04", "kp": "外周血管DSA技术", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → 外周血管DSA技术", "ex": "【为什么对】五项均正确。A：步进式DSA可一次注射跟踪对比剂从腹主动脉至足部，完成全程显影。B：对侧股动脉逆行穿刺+翻山（cross-over）是双侧下肢动脉评估的标准入路。C：下肢动脉DSA对比剂用量较大（因覆盖范围广），通常80-120ml+8-12ml/s。D：DSA主要并发症包括穿刺点并发症（血肿、假性动脉瘤、动静脉瘘）、对比剂肾病、血管损伤（夹层、破裂）、远端栓塞等。E：下肢动脉硬化闭塞的DSA典型表现为管腔不规则狭窄/闭塞+侧支循环形成+远端血流减慢。【为什么错】无错误选项。", "tr": "“步进式”技术需注意：对比剂追踪需精确匹配血流速度——若进床太快（超过对比剂流速）则远端血管不显影，太慢则近端对比剂已排空。另外步进式DSA辐射剂量较高，但可一次完成全程成像避免多次注射。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-075", "t": "单选题", "s": "关于DSA三维旋转血管造影（3D-RA）与常规2D-DSA的比较，以下描述错误的是", "o": {"A": "3D-RA通过C臂旋转采集（通常旋转200°）获得多角度投影数据，经重建生成三维血管模型", "B": "3D-RA可显著提高颅内动脉瘤的检出率，特别是小动脉瘤（<3mm）", "C": "3D-RA的辐射剂量和对比剂用量通常低于常规多角度2D-DSA", "D": "3D-RA图像可进行任意角度旋转观察，优化工作角度选择", "E": "3D-RA在动静脉畸形（AVM）的供血动脉和引流静脉评估中具有明显优势"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-05", "kp": "DSA技术新进展", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → DSA技术新进展", "ex": "【为什么对】本题要求选错误选项。C错误——3D-RA的辐射剂量通常高于常规单角度2D-DSA（因需连续旋转采集数百帧图像），但低于多次不同角度的2D-DSA总和。对比剂用量通常也较大（因旋转采集持续时间更长需维持血管内对比剂浓度）。【为什么错】A正确：3D-RA通过C臂200°旋转采集→重建三维容积数据。B正确：3D-RA对小动脉瘤（<3mm）检出率显著优于2D-DSA（消除血管重叠和角度依赖）。D正确：3D-RA可在工作站上任意角度旋转观察，帮助选择最佳工作角度。E正确：3D-RA对AVM的血管构筑（供血动脉+nidus+引流静脉）显示远优于2D-DSA。", "tr": "C是常见误区——虽然3D-RA可减少多次注射和多次不同角度DSA的需要（从而减少总对比剂和辐射），但单次3D-RA的剂量和对比剂通常不低于单次2D-DSA。需全面理解两者的比较维度。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-076", "t": "单选题", "s": "关于DICOM标准，以下描述错误的是", "o": {"A": "DICOM（Digital Imaging and Communications in Medicine）是医学数字成像和通信的国际标准", "B": "DICOM标准仅涵盖医学图像的存储格式，不包括传输和打印", "C": "DICOM文件包含图像数据和元数据（患者信息、检查参数等），采用标签（tag）结构", "D": "DICOM协议基于TCP/IP网络通信，支持存储（Storage）、查询/检索（Query/Retrieve）等服务类", "E": "DICOM一致性声明（Conformance Statement）是设备互联互通的重要参考文件"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-01", "kp": "DICOM标准", "ch": "十二、PACS技术 → 1.国际标准与规范 → DICOM标准", "ex": "【为什么对】本题要求选错误选项。B错误——DICOM标准涵盖范围极为广泛，不仅包括图像存储格式，还包括网络传输协议、打印管理、工作流管理（Modality Worklist, MPPS）、结构化报告等多种服务类。“不包括传输和打印”与事实严重不符。【为什么错】A正确：DICOM确为医学数字成像与通信国际标准（NEMA/ISO 12052）。C正确：DICOM文件使用标签（tag, 如0010,0010=患者姓名，0008,0020=检查日期）存储元数据和图像数据。D正确：DICOM网络服务基于TCP/IP，支持C-STORE（存储）、C-FIND（查询）、C-MOVE（检索）等。E正确：DICOM一致性声明详细列出设备支持的SOP类和选项，是互联互通的基础文档。", "tr": "DICOM标准的涵盖范围远不止图像格式——它是一个包含18+个部分的庞大标准体系，涵盖网络传输、存储、打印、工作流、安全、结构化报告等。考生需了解DICOM不是简单的图像文件格式（如JPEG/DICOM），而是完整的医学影像信息学框架。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-077", "t": "多选题", "s": "关于PACS（影像归档与通信系统）的系统组成，以下正确的是", "o": {"A": "PACS核心组成部分包括影像采集网关、PACS服务器（归档/数据库）、存储系统和诊断工作站", "B": "RIS（放射信息系统）与PACS的集成（RIS/PACS集成）是实现放射科数字化转型的关键", "C": "PACS存储架构通常仅采用两级存储（在线与离线），不存在近线存储", "D": "HIS/RIS/PACS的集成需要HL7标准支持，DICOM和HL7是PACS的两大核心通信标准", "E": "云PACS是当前发展趋势——将影像存储和部分应用迁移至云端，可降低本地存储压力并实现远程会诊"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-02", "kp": "PACS系统架构与组成", "ch": "十二、PACS技术 → 2.PACS发展与组成 → PACS系统架构与组成", "ex": "【为什么对】A正确——PACS核心包括影像采集网关、PACS服务器（归档/数据库）、存储系统与诊断工作站。B正确——RIS/PACS集成实现登记、排程、报告与影像的一体化，是放射科数字化转型关键。D正确——HIS/RIS/PACS集成以HL7（文本信息）与DICOM（影像）为两大核心通信标准。E正确——云PACS将存储与部分应用迁移云端，降低本地压力并支持远程会诊。【为什么错】C错误——PACS普遍采用三级存储模型：在线（FC/SAS，高速高成本）、近线（SATA/NL-SAS，中速中成本）、离线（磁带/光盘，长期归档低成本）；近线存储是兼顾访问速度与成本的关键层级，并非“无近线两级存储”。", "tr": "本题已将原“全选”改为四项正确；注意选项C为刻意设置的错误项——PACS普遍采用三级存储模型：在线（FC/SAS，高速高成本）、近线（SATA/NL-SAS，中速中成本）、离线（磁带/光盘，长期归档低成本）；近线存储是兼顾访问速度与成本的关键层级，并非“无近线两级存储”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-078", "t": "单选题", "s": "关于PACS影像压缩技术，以下描述正确的是", "o": {"A": "有损压缩（如JPEG、JPEG2000）可实现极高压缩比（10:1-30:1），但不适用于临床诊断（可能丢失诊断信息）", "B": "无损压缩（如JPEG-LS、JPEG2000 lossless）压缩比较低（约2:1-3:1），但完全保留影像诊断信息", "C": "DICOM标准支持JPEG、JPEG-LS、JPEG2000、RLE等多种压缩算法", "D": "影像压缩在PACS中主要用于长期归档以减少存储成本，短期在线存储通常使用非压缩格式以保证最快访问速度", "E": "以上均正确"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-03", "kp": "PACS影像压缩与存储", "ch": "十二、PACS技术 → 2.PACS发展与组成 → PACS影像压缩与存储", "ex": "【为什么对】以上均正确。A：有损压缩在极高压缩比下可能丢失诊断相关信息（尤其对纹理/细微结构的显示），不推荐用于初次诊断（但可用于临床浏览和教学）。B：无损压缩完全保留数据，但压缩比低（通常2:1-3:1）。C：DICOM标准支持多种压缩Transfer Syntax。D：PACS中近/在线存储通常保持非压缩或无损压缩以保证最快访问和最佳质量，长期归档可选择性使用有损压缩以节省成本。各选项均正确。【为什么错】见上述解析中各错误选项分析。", "tr": "本题A、B、C、D均为正确，选项E为以上均正确。有损压缩在临床实践中应用存在争议——ACR和CAR推荐诊断使用非压缩或无损压缩图像，有损压缩可能适合临床浏览和远程会诊场景。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-079", "t": "单选题", "s": "激光胶片打印机中，激光的作用是", "o": {"A": "加热胶片使其显影", "B": "曝光胶片上的感光层以形成潜影", "C": "读取胶片上的影像信息", "D": "定影胶片以稳定图像", "E": "干燥胶片以加速冲洗"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRINT-01", "kp": "激光打印技术", "ch": "十三、图像打印技术 → 1.激光成像 → 激光打印技术", "ex": "【为什么对】激光胶片打印机（laser imager）中，激光束按图像信号调制成不同强度，逐点扫描曝光胶片上的感光乳剂层，形成潜影（latent image），后续经过化学显影→定影→水洗→干燥等流程完成胶片成像。激光曝光是数字影像到胶片硬拷贝的关键步骤。【为什么错】A加热是热敏打印的原理（干式打印），非激光打印。C读取影像信息是扫描仪/CR读取器的功能。D定影使用化学定影液（硫代硫酸铵等）。E干燥是胶片冲洗的最后一步。", "tr": "考生容易混淆激光打印和热敏打印的原理：激光打印=激光曝光感光胶片+化学冲洗（湿式）；热敏打印=加热头直接加热热敏胶片显色（干式、无需化学冲洗）。两种技术完全不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-080", "t": "多选题", "s": "关于医用干式打印技术（dry printing），以下正确的是", "o": {"A": "干式打印无需化学冲洗（显影/定影液），环保无废液排放", "B": "干式热敏打印使用热敏胶片，加热头（thermal head）直接加热使胶片微胶囊破裂而显色", "C": "干式激光打印使用光热敏胶片（photothermographic film），激光曝光后经加热处理显影", "D": "干式打印的图像质量和稳定性已可媲美传统湿式激光打印，已基本取代湿式打印成为主流", "E": "干式打印的Dmax（最大密度）和灰阶层次通常优于湿式激光打印"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRINT-02", "kp": "热敏与干式打印", "ch": "十三、图像打印技术 → 2.热敏成像技术 → 热敏与干式打印", "ex": "【为什么对】A正确：干式打印无液态化学品，操作简便、环保。B正确：干式热敏使用微胶囊热敏技术（如FUJI DryPix）——加热使微胶囊破裂释放染料。C正确：干式激光使用光热敏胶片（如Carestream DryView）——激光曝光+热显影（无湿式化学步骤）。D正确：干式打印已基本取代湿式成为主流。E错误：传统湿式激光打印的Dmax（>3.5）和灰阶层次通常略优于干式打印——湿式技术的灰阶动态范围和最大密度仍有微弱优势，但干式打印已能满足临床诊断需求。【为什么错】E将两者优劣说反或过度绝对化。", "tr": "E是常见误区——传统湿式激光打印在Dmax和灰阶方面的物理极限仍略高于干式（尤其在大幅面高精度打印），但差别已极小不影响临床诊断。“通常优于”过度绝对化了干式的优势。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "概述", "页": 355}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-081", "t": "单选题", "s": "数字乳腺断层融合摄影（DBT）相较于传统二维乳腺X线摄影（2D MG）的主要优势是", "o": {"A": "显著降低辐射剂量", "B": "消除乳腺组织重叠效应，提高病变检出率和降低召回率", "C": "完全替代超声作为乳腺筛查工具", "D": "图像采集速度大幅提高", "E": "不需要压迫乳腺"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DIG-01", "kp": "数字乳腺断层融合摄影", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT（3D乳腺摄影）核心优势：通过X线管弧形运动采集多个低剂量投影（通常15-25个角度），经重建生成一系列薄层（1mm）图像，有效消除传统2D摄影中致密乳腺的组织重叠效应——使重叠掩盖的病变可见（提高检出率），使重叠伪像导致的假阳性减少（降低召回率）。多项大型临床试验证实DBT可将召回率降低15%-40%。【为什么错】A DBT辐射剂量与2D相当或略高。C DBT不能替代超声——超声在致密乳腺补充筛查、囊实性鉴别方面仍有不可替代价值。D DBT采集时间与2D相似（均需数秒）。E DBT仍需压迫乳腺（标准操作），压迫对保证图像质量和降低剂量至关重要。", "tr": "DBT主要解决的是乳腺影像学根本困境——组织重叠。致密乳腺中2D MG敏感度可降至40-50%，DBT通过薄层重建消除重叠，显著提升致密乳腺中病变的检出。但DBT不能替代超声，也不解决所有问题（如微钙化显示在2D合成图上可能略逊于直接2D）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-082", "t": "多选题", "s": "关于双能X线骨密度仪（DXA）的技术原理与应用，以下正确的是", "o": {"A": "DXA利用高能和低能两种X线束穿透人体，利用骨骼和软组织在不同能量下的衰减差异区分两者", "B": "DXA是目前WHO推荐的骨质疏松诊断金标准，诊断基于T-score（与年轻健康成人峰值骨密度比较的标准差）", "C": "按照WHO标准，T-score≤-2.5可诊断为骨质疏松症", "D": "DXA测量部位常规包括腰椎（L1-L4）和髋部（股骨颈和全髋），前臂作为替代部位", "E": "DXA的辐射剂量与胸部CT相当（约数mSv）"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DIG-02", "kp": "双能X线骨密度仪", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → 双能X线骨密度仪", "ex": "【为什么对】A正确——DXA利用骨骼与软组织在高、低能X线下衰减差异，经算法分离骨矿与软组织。B正确——DXA是WHO推荐的骨质疏松诊断金标准，基于T-score（与年轻成人峰值骨密度比较的标准差）。C正确——按WHO标准T-score≤−2.5诊断为骨质疏松。D正确——常规测量腰椎（L1–L4）与髋部（股骨颈、全髋），前臂为替代部位。【为什么错】E错误——DXA辐射剂量极低（约1–10 μSv），显著低于胸部X线摄影（约50–100 μSv）与胸部CT（数mSv），而非“与胸部CT相当”；低剂量正是其作为人群筛查工具的优势。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——DXA辐射剂量极低（约1–10 μSv），显著低于胸部X线摄影（约50–100 μSv）与胸部CT（数mSv），而非“与胸部CT相当”；低剂量正是其作为人群筛查工具的优势。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-083", "t": "单选题", "s": "关于光子计数探测器CT（PCCT）相较于传统能量积分探测器CT的优势，以下描述错误的是", "o": {"A": "光子计数可直接区分不同能量的光子，实现多能谱成像", "B": "光子计数可消除电子噪声，显著提升低剂量下的图像质量", "C": "光子计数探测器的空间分辨率通常低于传统能量积分探测器", "D": "光子计数可实现组织成分的定量分析（如痛风结节中尿酸钠的识别）", "E": "光子计数探测器具有内在的光谱/能量分辨能力，无需额外硬件即可实现能谱成像"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DIG-03", "kp": "光子计数CT技术", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → 光子计数探测器CT技术", "ex": "【为什么对】本题要求选错误选项。C错误——光子计数探测器（PCD）的空间分辨率通常高于传统能量积分探测器（EID），而非更低。因为PCD无需分隔栅（septa），像素可做得更小且无光学串扰；同时PCD对小像素中电荷共享效应可通过校正算法处理，实现更高空间分辨率。【为什么错】A正确：PCD可设定能量阈值，将光子按能量分bin计数，天然实现多能谱成像。B正确：PCD可设定低能阈值剔除电子噪声（噪声光子能量低于阈值不计数），在低剂量下图像质量显著优于EID。D正确：PCD多能谱数据可实现物质鉴别和定量分析（如痛风结节中的尿酸钠vs钙盐）。E正确：PCD能谱能力来自探测器本身（无需双层探测器或kVp切换等额外硬件）。", "tr": "C将PCD和EID的空间分辨率优劣颠倒——PCD因无分隔栅、像素更小，空间分辨率更高。这是PCD最重要的技术优势之一（可实现超高分辨率CT，像素尺寸可小至0.15-0.2mm）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-084", "t": "多选题", "s": "关于数字化X线摄影技术的最新进展，以下正确的是", "o": {"A": "无线平板探测器（wireless FPD）使DR系统更加便携和灵活，在床旁摄影和术中应用具有显著优势", "B": "动态DR（Dynamic DR）仅能进行静态摄影，不具备透视与动态序列采集功能", "C": "人工智能辅助X线诊断（如AI肺结节检测、骨折检测）可提高放射科医师的诊断效率和准确性", "D": "超高分辨率DR系统（使用微焦点X线管和小像素探测器）可实现空间分辨率>10lp/mm，用于微细结构成像", "E": "数字化X线技术的发展方向之一是降低辐射剂量——通过新型探测器材料、高效图像处理算法和AI降噪技术的综合应用"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DIG-04", "kp": "数字化X线技术发展趋势", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → 数字化X线技术发展趋势", "ex": "【为什么对】A正确——无线平板探测器（wireless FPD）使DR便携灵活，床旁与术中优势显著。C正确——AI辅助X线诊断（肺结节、骨折检测等）可提升医师效率与准确性，已获多项FDA/CE认证。D正确——超高分辨率DR（微焦点管+小像素探测器）空间分辨率可>10 lp/mm，用于微细结构成像。E正确——降低辐射剂量是数字化X线核心方向，依赖新型探测器材料、高效算法与AI降噪的综合策略。【为什么错】B错误——动态DR（Dynamic DR）的核心特征正在于兼具摄影与连续透视/动态序列采集能力，可一次检查中实时观察吞咽、关节运动等并捕获动态影像，而非“仅能静态摄影”。", "tr": "本题已将原“全选”改为四项正确；注意选项B为刻意设置的错误项——动态DR（Dynamic DR）的核心特征正在于兼具摄影与连续透视/动态序列采集能力，可一次检查中实时观察吞咽、关节运动等并捕获动态影像，而非“仅能静态摄影”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-085", "t": "单选题", "s": "关于DSA图像融合技术，以下描述错误的是", "o": {"A": "DSA图像可与CT/MR图像进行融合，实现解剖与功能信息的叠加显示", "B": "三维路图（3D roadmap）技术将3D血管影像与实时透视叠加，引导导管/导丝操作", "C": "DSA-CT融合图像可用于介入治疗计划制定和术中导航", "D": "图像融合技术可完全替代多角度DSA采集，从而显著降低辐射剂量", "E": "锥形束CT（CBCT）与DSA的结合是当前介入影像的重要发展方向"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-01", "kp": "DSA图像融合与导航技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】本题要求选错误选项。D错误——图像融合技术不能完全替代多角度DSA采集。图像融合基于已有的CT/MR/3D-DSA数据，只能在已有数据基础上叠加信息，无法提供实时血流动力学信息（如血流速度、侧支循环动态等），因此不能完全替代DSA的多角度实时采集。【为什么错】A正确：DSA与CT/MR融合可实现血管解剖与周围组织关系的同时显示。B正确：3D roadmap是DSA最实用的导航技术之一——将3D血管模型与实时透视匹配，即使C臂角度变化也能自动更新。C正确：融合图像在介入规划中价值极高。E正确：CBCT（C臂CT）与DSA在同一设备上结合，实现一站式介入诊疗。", "tr": "D使用“完全替代”绝对化措辞——图像融合是已有数据的叠加显示，无法替代实时的、功能性的DSA采集。融合技术的价值在于“增强”而非“替代”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-086", "t": "单选题", "s": "关于低剂量DSA技术，以下描述错误的是", "o": {"A": "降低脉冲频率（f/s）可从15f/s降至7.5f/s甚至更低，是降低DSA辐射剂量最直接的方法", "B": "使用低剂量模式（降低每帧mA）可在保持图像质量的前提下降低辐射剂量", "C": "DSA辐射剂量的降低可通过降低对比剂浓度来补偿图像质量损失", "D": "图像降噪算法（如实时自适应降噪、时域滤波）是低剂量DSA的重要辅助技术", "E": "DSA操作者辐射防护的最基本原则是时间、距离和屏蔽"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-02", "kp": "DSA低剂量与辐射防护", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → DSA低剂量与辐射防护", "ex": "【为什么对】本题要求选错误选项。C错误——降低DSA辐射剂量会导致图像噪声增加、信噪比下降，这需要通过图像降噪算法来补偿，而非通过降低对比剂浓度（降低对比剂浓度会进一步恶化血管显影质量，适得其反）。对比剂浓度和辐射剂量是两个独立参数。【为什么错】A正确：降低帧率是最直接的降剂量方法。B正确：低剂量模式（降低管电流/脉冲宽度）可有效降低辐射。D正确：图像降噪算法（如自适应空间-时间滤波）是低剂量DSA不可或缺的后处理手段。E正确：时间、距离、屏蔽是放射防护基本原则，对操作者同样适用（鉛屏、铅衣、距离控制）。", "tr": "C错误地将降低对比剂浓度与辐射剂量补偿关联——这是两个独立维度：辐射剂量影响噪声水平（需降噪算法补偿）；对比剂浓度影响血管显影密度（需调整注射参数）。两者不能互相替代。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-087", "t": "多选题", "s": "关于DSA新技术进展，以下正确的是", "o": {"A": "4D-DSA技术可提供时间分辨的三维血管影像，动态显示血流过程（如AVM的供血时序）", "B": "双能DSA可减少骨性结构伪影，提高颅底/脊柱区域血管的显示质量", "C": "CO₂血管造影可作为肾功能不全患者碘对比剂的替代方案，尤其适用于腹主动脉和外周血管成像", "D": "平板探测器DSA的空间分辨率较传统影像增强器DSA有显著提升（像素尺寸可<0.2mm）", "E": "双能DSA消除骨性伪影的核心机制与X线能量无关，仅靠两次曝光的图像配准与减影即可实现"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-03", "kp": "DSA新技术进展", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → DSA新技术进展", "ex": "【为什么对】A正确——4D-DSA提供时间分辨的三维血管影像，可动态显示血流过程（如AVM供血时序）。B正确——双能DSA利用高低能量减影消除骨性重叠，提升颅底/脊柱区域血管显示。C正确——CO₂血管造影无肾毒性、无过敏，是肾功能不全患者（尤腹主动脉、外周血管）的有效替代。D正确——平板探测器DSA像素尺寸可<0.2 mm，空间分辨率较影像增强器DSA显著提升。【为什么错】E错误——双能DSA（dual-energy DSA）正是利用碘、骨与软组织在高低两种X线能量下衰减系数的差异，经能量加权减影选择性去除骨性结构；其骨去除效果本质上依赖于\"能量\"维度，而非单纯的两次曝光配准减影（后者是传统时间减影的原理）。故\"与X线能量无关\"之说错误。", "tr": "本题已将原\"全选\"改为四项正确；注意选项E为刻意设置的错误项——双能DSA骨去除依赖高低能量衰减差异（能量维度），并非与能量无关；\"仅靠两次曝光配准减影\"是传统单能时间减影的原理。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-088", "t": "案例分析题", "s": "某介入中心计划升级DSA设备，考虑引入以下新技术。作为技术评估组成员，以下哪些技术的描述是正确的", "o": {"A": "3D旋转血管造影+路图导航技术可显著提高颅内动脉瘤介入栓塞的精确性和安全性", "B": "支架精细显影（StentBoost）技术通过图像增强算法提高冠脉/颅内支架的可视化程度", "C": "双平板DSA系统可在单次注射下同时获得正位和侧位两个投影，减少对比剂用量和辐射", "D": "CBCT（锥形束CT）功能可在DSA设备上实现CT样成像，用于术中评估出血和器械位置", "E": "人工智能辅助DSA技术目前已被FDA批准用于全自动介入手术操作"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-04", "kp": "DSA设备升级与技术评估", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → DSA设备升级与技术评估", "ex": "【为什么对】A正确：3D roadmap将重建血管模型与实时透视融合，大幅提高动脉瘤栓塞的精确度和安全性（减少术中破裂风险）。B正确：StentBoost（或类似技术如ClearStent）通过运动校正和多帧叠加提高支架可视化。C正确：双平板（Biplane）系统可在一次注射下获得双平面影像，减少对比剂注射次数和总量。D正确：CBCT功能已广泛应用于DSA设备（如西门子syngo DynaCT、飞利浦XperCT），提供术中CT样成像。【为什么错】E错误：目前AI辅助DSA技术仍限于辅助诊断（如血管狭窄自动检测、动脉瘤识别）和图像优化（降噪、融合），尚未达到“全自动介入手术操作”的水平。介入手术的全自动化涉及极其复杂的机器人操作和临床决策，目前仍处于研究阶段。", "tr": "E使用“全自动介入手术操作”过度夸大AI在DSA中的当前应用水平——AI在DSA中目前主要是“辅助工具”（辅助诊断、图像优化），而非替代术者进行全自动操作。机器人辅助血管介入技术（如CorPath GRX）可远程操控导丝/导管，但仍需术者全程控制，非“全自动”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-089", "t": "单选题", "s": "关于双能量CT（DECT）的基本原理，以下描述正确的是", "o": {"A": "双能量CT利用同一种X线能量在不同时间点扫描获得两组数据", "B": "双能量CT利用两种不同能量的X线（高kVp和低kVp）扫描同一部位，利用物质对不同能量X线衰减的差异进行物质分离", "C": "双能量CT必须在两个不同的CT设备上完成", "D": "双能量CT只能分离两种物质（如碘和水）", "E": "双能量CT的辐射剂量是常规CT的两倍"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-01", "kp": "双能量CT基本原理", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → 双能量CT基本原理", "ex": "【为什么对】B正确——双能量CT的基本原理是利用两种不同能量的X线（如80kVp和140kVp，或100kVp和Sn140kVp）扫描同一解剖部位，根据不同物质（如碘、钙、水、脂肪等）在两种能量下衰减差异的规律，通过数学分解算法（三物质分解法等）实现物质分离和定量分析。【为什么错】A错误：双能量CT是同一时间或极短间隔内用两种能量扫描，非不同时间点。C错误：DECT可在单台设备上完成（双源CT、快速kVp切换、双层探测器等）。D错误：DECT理论上可分离三种物质（如脂肪、软组织和碘），三物质分解是DECT的经典算法。E错误：现代DECT的辐射剂量与常规单能CT相当或仅略高。", "tr": "DECT的四种实现方式容易混淆：①双源CT（两个球管同时不同kVp）；②快速kVp切换（单个球管快速切换kVp）；③双层探测器（单kVp照射，探测器上下层分别接收低/高能光子）；④双旋扫描（两次扫描不同kVp）。各方式各有优缺点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-090", "t": "多选题", "s": "双能量CT在临床中的典型应用包括", "o": {"A": "虚拟平扫（VNC）——从增强数据中减去碘信息生成虚拟平扫图像，可减少一次平扫的辐射剂量", "B": "碘图（iodine map）——定量显示组织碘摄取量，用于肿瘤灌注和血管评估", "C": "痛风结石成分分析——鉴别尿酸钠结石（可药物溶解）与钙盐结石（需碎石/手术）", "D": "肺灌注成像——利用碘图评估肺栓塞导致的灌注缺损", "E": "骨髓水肿检测——双能CT可直接显示骨髓水肿的病理形态，与MRI具有同等软组织对比"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-02", "kp": "能量CT临床应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → 能量CT临床应用", "ex": "【为什么对】A正确——虚拟平扫（VNC）从增强数据数字化去除碘，生成类平扫图像，可省去平扫、降低约30%辐射。B正确——碘图定量组织碘浓度（mgI/ml），用于灌注与血供评估。C正确——DECT鉴别尿酸（非钙）结石与钙盐结石，尿酸结石可药物溶解，避免不必要手术。D正确——肺碘图显示栓塞供血区的灌注缺损，实现CT肺灌注成像。【为什么错】E错误——双能CT对骨髓水肿为间接检测：经虚拟去钙（VNCa）去除骨小梁钙质后，水肿区因含水呈相对高密度而凸显；其软组织对比远不及MRI（MRI为骨髓水肿诊断金标准），并非“直接显示且等同MRI”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——双能CT对骨髓水肿为间接检测：经虚拟去钙（VNCa）去除骨小梁钙质后，水肿区因含水呈相对高密度而凸显；其软组织对比远不及MRI（MRI为骨髓水肿诊断金标准），并非“直接显示且等同MRI”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-091", "t": "单选题", "s": "以下关于能量CT物质分离技术，错误的是", "o": {"A": "三物质分解法假设每个体素由三种基础物质的混合物组成，通过两种能量下的衰减值解方程组求解", "B": "常用的基础物质对包括碘-水、钙-水、碘-钙、尿酸-钙等", "C": "双能量指数（DEI）或双能量比值可用于区分不同物质", "D": "能量CT物质分离技术只能用于定性分析，不能用于定量测量", "E": "双层探测器CT可在探测器层面实现能量分离，其优势是无需预设双能量扫描协议"}, "d": "难", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-03", "kp": "能量CT物质分离技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → 能量CT物质分离技术", "ex": "【为什么对】本题要求选错误选项。D错误——能量CT物质分离技术不仅可用于定性分析，更重要的是可实现定量测量：如碘浓度定量（mgI/ml）、钙定量（mg/cm³）、脂肪分数定量等。定量能力恰恰是能量CT相对于传统CT的核心优势之一。【为什么错】A正确：三物质分解是DECT核心算法——三个未知数（三种基础物质体积分数）+两个已知数（低能和高能CT值）+一个约束条件（体积分数之和=1）=可解。B正确：不同的基础物质对用于不同的临床应用场景。C正确：不同物质的高低能衰减比值不同，该比值可用于物质鉴别。E正确：双层探测器CT的优势在于所有扫描天然具有能谱信息（探测器上下层分别接收低能和高能光子），操作者无需预先决定是否需要双能量扫描。", "tr": "D将能量CT的定量能力否定——恰恰相反，{LQ}定量{RQ}是能量CT相对于传统CT的革命性进步。传统CT的CT值（HU）受多种因素影响（kVp、患者体型等）不具有绝对定量能力；能量CT通过物质分离可实现碘浓度等参数的绝对定量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-092", "t": "案例分析题", "s": "关于CT低剂量技术的原理，以下描述错误的是", "o": {"A": "迭代重建（IR）算法可在相同辐射剂量下降低图像噪声，或在降低剂量的同时保持相同噪声水平", "B": "自动管电流调制（ATCM）可根据扫描部位和患者体型实时调整mA，是CT低剂量最基础的技术", "C": "降低管电压（kVp）可同时降低辐射剂量和增加碘对比度（因碘的K缘效应），在CTA和儿童检查中应用广泛", "D": "减少扫描期相（如肝脏CT仅做动脉期+门脉期而不做延迟期）是降低总辐射剂量的有效方式", "E": "使用更大螺距（如pitch=1.5）会显著增加辐射剂量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-04", "kp": "CT低剂量技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → CT低剂量技术", "ex": "【为什么对】本题要求选错误选项。E错误——增大螺距（pitch>1）会降低辐射剂量（因重叠扫描减少），而非增加。螺距与辐射剂量成反比：剂量∝1/pitch。【为什么错】A正确：IR算法是低剂量CT核心技术（如ASIR-V、 ADMIRE、AiCE等）。B正确：ATCM是最基础的低剂量技术。C正确：低kVp增强碘强化（碘的K缘33.2keV）的同时降低剂量（剂量∝kVp²）。D正确：减少扫描期相是降低累积剂量的直接方法——需权衡诊断价值与辐射风险。", "tr": "E将螺距与剂量的关系说反——pitch增大=进床快=同一部位受照时间短=剂量降低。剂量∝1/pitch。但pitch增大也会导致层面敏感度曲线展宽（Z轴分辨率降低）和数据间隙（需插值），需要在图像质量和剂量之间权衡。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-093", "t": "多选题", "s": "关于CT低剂量检查的临床应用策略，以下正确的是", "o": {"A": "儿童CT检查应严格遵循ALARA原则，使用专门的儿童低剂量扫描协议（低kVp+低mA+IR重建）", "B": "肺癌低剂量筛查CT（LDCT）使用极低辐射剂量（约1-2mSv），用于高危人群的年度筛查", "C": "冠状动脉CTA低剂量策略包括：前瞻性心电门控、低kVp（70-100kVp）、迭代重建和高螺距螺旋扫描", "D": "CT结肠成像（CTC）低剂量策略强调低kVp（降低腹部剂量）+俯卧位/仰卧位互补扫描以弥补低剂量导致的噪声增加", "E": "急诊创伤全身CT（pan-scan）因需要快速诊断，辐射剂量优化不是优先考虑的问题"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-05", "kp": "CT低剂量临床应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → CT低剂量临床应用", "ex": "【为什么对】A正确：儿童对辐射的敏感性为成人的3-5倍（因细胞分裂活跃+预期寿命更长），儿童CT必须使用专门的极低剂量协议。B正确：LDCT肺癌筛查（如NLST试验方案）有效剂量约1-2mSv，显著低于诊断性胸部CT（约5-8mSv）。C正确：冠脉CTA低剂量综合策略包括前瞻性门控（减少无效扫描）、低kVp、IR重建、大螺距（如Flash Spiral）等。D正确：CTC可使用极低剂量（因结肠黏膜与充气肠腔有天然高对比），俯仰卧位互补可在低剂量下保证诊断质量。【为什么错】E错误：急诊创伤全身CT虽然需要快速诊断，但辐射剂量优化绝不能忽视——全身体CT（头+颈+胸+腹+盆）累积辐射剂量可>30mSv，尤其多数创伤患者为年轻人，必须在保障诊断的前提下尽可能降低剂量。现代创伤CT协议均整合了剂量优化策略（ATCM、低kVp、IR等）。", "tr": "E使用“不是优先考虑的问题”诱导考生认为急诊场景可以忽视辐射防护——这是严重错误观念。辐射防护在任何场景下都应重视，急诊创伤患者年龄偏轻（车祸、坠落等），辐射的远期致癌风险更需关注。“快速诊断”与“辐射优化”不矛盾——现代CT技术可同时实现。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-094", "t": "案例分析题", "s": "某医院拟开展低剂量CT肺癌筛查项目。作为技术负责人，需要设计筛查方案。以下哪些措施是正确的", "o": {"A": "采用低剂量扫描协议：管电压100-120kVp，管电流20-50mAs（具体根据患者体型调整），总辐射剂量目标<3mSv", "B": "扫描范围从肺尖至肋膈角（包括全部肺实质），层厚≤1.5mm（薄层以利小结节检测和随访）", "C": "筛查阳性标准参照Lung-RADS分类系统，基线筛查发现的实性结节<6mm可继续年度筛查", "D": "阳性筛查结果的管理遵循“结节生长”评估原则——两次筛查间结节体积倍增时间（VDT）是判断良恶性的重要参数", "E": "所有LDCT发现的肺结节均应立即行PET-CT检查以明确诊断"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-06", "kp": "低剂量CT肺癌筛查", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → 低剂量CT肺癌筛查", "ex": "【为什么对】A正确：LDCT筛查辐射剂量目标<3mSv（NLST 1.5mSv，NELSON约1-2mSv），使用低mA（20-50mAs）扫描。B正确：全肺覆盖+薄层重建（≤1.5mm，国际肺筛查共识推荐层厚≤1mm）是肺结节检测的标准要求。C正确：Lung-RADS 1.1中基线筛查<6mm实性结节（或<30mm²体积）为阴性，可常规年度随访。D正确：体积倍增时间（VDT）是结节生长评估的重要指标——恶性结节VDT通常30-400天；VDT<30天提示感染/炎症；VDT>400天提示良性（如错构瘤）。【为什么错】E错误：所有LDCT发现结节均行PET-CT是严重过度检查——PET-CT成本高、辐射剂量大（约10-15mSv），仅适用于≥8mm实性结节且CT特征不确定者。绝大多数<8mm结节通过LDCT随访即可。", "tr": "E使用“所有...均应立即”绝对化——LDCT筛查的核心策略是“风险分层管理”：低风险结节→LDCT随访；中高风险结节→进一步检查（PET-CT/穿刺/手术）。“一刀切”行PET-CT是临床资源的巨大浪费和过度医疗。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-095", "t": "单选题", "s": "关于BOLD-fMRI（血氧水平依赖功能磁共振成像）的原理，以下描述正确的是", "o": {"A": "BOLD信号基于脱氧血红蛋白的顺磁性效应——脱氧血红蛋白作为内源性对比剂引起局部磁场不均匀→T2*信号降低", "B": "神经元激活→局部脑血流和氧合增加（氧合过度）→脱氧血红蛋白浓度相对降低→T2*信号增高→BOLD信号增高", "C": "BOLD-fMRI的时间分辨率受限于血流动力学响应函数（HRF），通常为秒级（约5-8秒达峰）", "D": "BOLD-fMRI可用于术前脑功能区定位（运动、语言、感觉等），以规划手术入路和保护功能", "E": "以上均正确"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-01", "kp": "BOLD-fMRI原理与应用", "ch": "十七、MR技术的进展 → 2.MR检查技术 → BOLD-fMRI原理与应用", "ex": "【为什么对】以上均正确。A：BOLD信号的物理基础是脱氧血红蛋白的顺磁性——脱氧Hb引起局部磁场梯度→T2*缩短→信号降低。B：神经元激活→血流增加>氧耗增加→脱氧Hb浓度净降低→T2*信号增高（BOLD增高）——这是神经血管耦合的核心。C：BOLD-fMRI的时间分辨率受限于缓慢的血流动力学响应（HRF），而非神经电活动的速度（毫秒级），这是fMRI的固有局限。D：术前fMRI功能定位（task fMRI）是神经外科的重要工具。【为什么错】见上述解析中各错误选项分析。", "tr": "本题选项E为以上均正确。BOLD-fMRI的神经生理学基础（神经血管耦合）和物理基础（脱氧Hb顺磁性）是两大核心概念。BOLD-fMRI的空间分辨率约2-3mm，时间分辨率约1-3秒（受HRF限制）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-096", "t": "多选题", "s": "关于磁共振弥散张量成像（DTI）及其临床应用，以下正确的是", "o": {"A": "DTI通过施加至少6个非共线方向的弥散敏感梯度，测量水分子弥散的各向异性", "B": "各向异性分数（FA）是DTI最常用的参数——FA值0-1，反映纤维束的方向性和完整性", "C": "DTI纤维束示踪（tractography）可三维显示白质纤维束走行，用于术前规划（如避开锥体束）", "D": "DTI在急性脑梗死的应用不如DWI——因为DTI扫描时间较长且对运动敏感", "E": "FA值升高通常提示白质纤维束损伤（如脱髓鞘、轴突损伤）"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-02", "kp": "弥散张量成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → 弥散张量成像", "ex": "【为什么对】A正确：DTI需≥6个方向（临床常用20-64方向）的弥散梯度，通过张量模型计算弥散椭球体（三个特征值λ₁, λ₂, λ₃）。B正确：FA=(各向异性扩散量)/(总扩散量)，0=完全各向同性（灰质、CSF），1=完全各向异性（白质纤维束）。C正确：纤维束示踪（tractography）可在三维空间追踪白质通路，在脑肿瘤手术规划中避免损伤关键纤维束。D正确：DWI扫描<30s即可完成，而DTI扫描时间更长（通常>2-3min），急性卒中首选DWI。【为什么错】E错误：白质纤维束损伤通常导致FA值降低（而非升高）——脱髓鞘/轴突损伤→纤维束方向性丧失+水分子弥散各向异性降低→FA下降。FA升高在临床上少见（可见于纤维束发育/髓鞘形成过程）。", "tr": "E将FA值变化方向说反——核心记忆：{LQ}FA降低=白质损伤{RQ}（脱髓鞘、轴突损伤、肿瘤浸润等导致纤维束方向性破坏→弥散各向同性增加→FA降低）。FA值降低是白质病变最重要和最常见的DTI改变。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-097", "t": "案例分析题", "s": "某三级医院计划将MRI研究平台从3.0T升级至7.0T超高场强。作为技术组，需要评估7.0T的优势和挑战。以下分析正确的有哪些", "o": {"A": "7.0T的SNR约为3.0T的2.3倍（与场强近似正比），可实现更高空间分辨率或更短扫描时间", "B": "7.0T的B1场不均匀性（介电效应）更为显著，腹部和盆腔成像面临更大技术挑战", "C": "7.0T下组织T1值进一步延长，TR需相应延长以保持T1对比", "D": "7.0T的SAR（比吸收率）限制更严格，许多高功率快速序列在7.0T下使用受限", "E": "7.0T的化学位移和磁敏感伪影较3.0T显著增大，但这也使BOLD-fMRI和SWI的灵敏度更高"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-03", "kp": "7.0T超高场MRI", "ch": "十七、MR技术的进展 → 1.MR设备 → 7.0T超高场MRI", "ex": "【为什么对】五项均正确。A：SNR近似与B₀成正比→7.0T/3.0T≈2.3倍SNR增益（理想条件下）。B：介电效应（B1波长缩短至约12cm，与人体尺寸可比拟）导致B1场严重不均匀，腹部成像挑战极大。C：场强↑→T1值延长→需要更长TR保持T1对比度。D：SAR∝B₀²→7.0T下SAR约为3.0T的5-6倍，高功率序列（如TSE、FLAIR等）需要使用并行发射、特殊脉冲设计等技术控制SAR。E：磁敏感效应（Δχ∝B₀）和化学位移（Hz∝B₀）均与场强成正比增大——这是一把双刃剑：伪影增大但BOLD和SWI灵敏度也更高。【为什么错】无错误选项。", "tr": "7.0T的优势与挑战并存：优势=高SNR、高BOLD/SWI灵敏度、高化学位移分离；挑战=B1不均匀性、高SAR、T1延长、伪影放大。7.0T目前主要仍限于神经和肌肉骨骼领域，体部应用面临很大技术障碍。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": true, "src": "回忆版", "mk": 1}, {"id": "053-098", "t": "多选题", "s": "关于压缩感知（CS）和并行成像在MR快速成像中的应用，以下正确的是", "o": {"A": "并行成像（如SENSE、GRAPPA）利用多通道线圈的空间信息减少相位编码步数，加速因子通常2-4倍", "B": "压缩感知利用MR图像在变换域的稀疏性，且无需任何K空间欠采样即可实现5–10倍加速", "C": "并行成像的主要限制是g因子相关的噪声放大，高加速因子下SNR急剧下降", "D": "压缩感知与并行成像可以联合应用（如CS-SENSE），实现更高倍加速", "E": "压缩感知重建图像的质量与欠采样模式（随机采样>规则采样）和稀疏变换选择密切相关"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-04", "kp": "MR快速成像技术", "ch": "十七、MR技术的进展 → 1.MR设备 → MR快速成像技术", "ex": "【为什么对】A正确——并行成像（SENSE/GRAPPA）利用多通道线圈灵敏度差异减少相位编码步数，加速因子通常2–4倍。C正确——并行成像受g因子噪声放大限制，高加速因子下SNR急剧下降（SNR_acc=SNR_full/(g√R)）。D正确——CS与并行成像可联合（如CS-SENSE）实现更高倍加速。E正确——CS重建质量与欠采样模式（随机>规则）及稀疏变换选择密切相关。【为什么错】B错误——压缩感知的前提正是对K空间进行随机/伪随机欠采样（以减少采集数据量），再依靠图像稀疏性与迭代重建恢复完整图像；若无欠采样便无加速可言，“无需欠采样即可加速”自相矛盾。", "tr": "本题已将原“全选”改为四项正确；注意选项B为刻意设置的错误项——压缩感知的前提正是对K空间进行随机/伪随机欠采样（以减少采集数据量），再依靠图像稀疏性与迭代重建恢复完整图像；若无欠采样便无加速可言，“无需欠采样即可加速”自相矛盾。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "回忆版", "mk": 1}, {"id": "053-099", "t": "单选题", "s": "关于ASL（动脉自旋标记）灌注成像与DSC（动态磁敏感对比增强）灌注成像的比较，以下描述错误的是", "o": {"A": "ASL使用动脉血中的水分子作为内源性示踪剂（射频标记），完全无创、无需注射对比剂", "B": "DSC使用钆剂作为外源性示踪剂，通过首过效应计算灌注参数", "C": "ASL的SNR低于DSC，单次采集时间较长（4-8分钟），但可重复性强", "D": "ASL更适合需要重复灌注评估的场景（如治疗随访、脑血管储备功能评估）", "E": "ASL可以同时提供与DSC完全相同的一组灌注参数（包括CBV、CBF、MTT、PS等）"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-05", "kp": "ASL灌注成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → ASL灌注成像", "ex": "【为什么对】本题要求选错误选项。E错误——ASL和DSC提供的灌注参数不完全相同。ASL直接测量CBF（脑血流），可间接推算CBV（通过动脉血容量修正），但无法提供MTT和PS等参数（这些需要对比剂动力学模型）。DSC通过对比剂首过效应可计算CBV、CBF、MTT、Tmax、TTP等全套灌注参数。【为什么错】A正确：ASL使用射频脉冲标记颈动脉血液中的水质子作为内源性示踪剂，完全无创。B正确：DSC通过静脉注射钆剂追踪其首过脑循环过程。C正确：ASL的SNR仅约为DSC的1/3-1/4（因标记与对照相减的信号差很小），需多次平均（4-8分钟）。D正确：ASL的无创性和可重复性使其非常适合需要多次灌注评估的场景。", "tr": "E将ASL和DSC的灌注参数等同——ASL仅直接测量CBF，不能测量MTT和PS。ASL的优势在于无创可重复；DSC的优势在于参数全面且SNR高但需注射对比剂。两者互补而非相互替代。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "053-100", "t": "单选题", "s": "关于3.0T MRI在临床应用的总体评价，以下描述错误的是", "o": {"A": "3.0T SNR约为1.5T的两倍，可提高空间分辨率或缩短扫描时间", "B": "3.0T的化学位移效应增大，使脂肪抑制技术（如SPIR、FatSat）效果更好", "C": "3.0T的磁敏感伪影（如颅内含气腔隙附近、金属植入物旁）较1.5T显著加重", "D": "3.0T在全身各部位的成像质量均全面优于1.5T，应作为所有临床检查的首选", "E": "3.0T的SAR限制更严格，需要使用并行发射、特殊脉冲设计等技术优化"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-06", "kp": "3.0T临床MRI", "ch": "十七、MR技术的进展 → 1.MR设备 → 3.0T临床MRI", "ex": "【为什么对】本题要求选错误选项。D错误——3.0T并非在所有部位和场景下均优于1.5T。3.0T的局限性包括：①SAR高限制某些序列使用；②磁敏感伪影更重（影响DWI和梯度回波序列在颅底、含气腔隙附近的图像质量）；③B1不均匀性大（尤其在腹部和盆腔）；④介电效应导致信号不均匀；⑤运动伪影更敏感；⑥植入物兼容性更差。1.5T在某些场景（如腹部、盆腔、心脏、植入物患者）仍是更优选择。【为什么错】A正确：3.0T SNR≈2倍1.5T。B正确：化学位移（Hz）与场强成正比→3.0T下脂肪和水峰更分离→频率选择性脂肪抑制效果更好。C正确：磁敏感伪影（Δχ∝B₀）在3.0T下更重。E正确：SAR限制是3.0T的主要技术挑战。", "tr": "D使用“全面优于...所有...首选”多重绝对化措辞——这是典型的错误信号。临床MRI设备选择需根据检查部位、患者情况和临床问题综合决策：1.5T适合腹部、盆腔、心脏和植入物患者；3.0T适合神经、骨关节、血管成像（MRA/TOF）。不存在“万能”场强。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "回忆版", "mk": 0}, {"id": "U01-0101", "t": "单选题", "s": "颅脑CT经鞍上池层面，鞍上池多呈“五角星”形，其向前伸出的前角所连通的结构是", "o": {"A": "大脑纵裂池", "B": "外侧裂池", "C": "环池", "D": "脚间池", "E": "四叠体池"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-001", "kp": "鞍上池形态与毗邻", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】鞍上池由交叉池、脚间池等汇合而成，横断面上典型呈“五角星”形：前角向前连通大脑纵裂池，两个前外侧角分别连通左右外侧裂池，两个后外侧角连通左右环池。故前角对应大脑纵裂池，选A。【为什么错】B外侧裂池对应的是两个前外侧角，不是前角。C环池对应两个后外侧角。D脚间池位于五角星后部中央，当其明显显影并单独构成一角时，鞍上池即由“五角星”变为“六角星”形，但它不在前角。E四叠体池位于中脑背侧、松果体区，层面更靠后，不参与鞍上池构成。", "tr": "“五角星”与“六角星”之分只在于后方脚间池是否单独成角，而不是前角变化；命题人常把“环池”与“外侧裂池”所对应的角位互换设陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0102", "t": "单选题", "s": "基底节区横断面上，内囊后肢所处的解剖位置是", "o": {"A": "尾状核头与豆状核之间", "B": "丘脑与豆状核之间", "C": "丘脑与尾状核头之间", "D": "豆状核与屏状核之间", "E": "屏状核与岛叶皮质之间"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-002", "kp": "内囊分部与毗邻结构", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】内囊在横断面上呈尖端向内的“><”形。后肢介于背侧丘脑（内侧）与豆状核（外侧）之间，其中皮质脊髓束、皮质核束的部分纤维及丘脑皮质束由此通过，故选B。【为什么错】A尾状核头与豆状核之间为内囊前肢，主要通过额桥束和丘脑前辐射。C丘脑与尾状核头之间并非内囊某一固定分部，二者之间为内囊膝部前方过渡区域，描述不准确。D豆状核与屏状核之间为外囊，主要为联络纤维。E屏状核与岛叶皮质之间为最外囊。【为什么错】补充：这三层结构由内向外依次为内囊、豆状核、外囊、屏状核、最外囊、岛叶皮质。", "tr": "内囊前肢“夹在尾状核头与豆状核之间”、后肢“夹在丘脑与豆状核之间”，两者的内侧界不同（前肢是尾状核头、后肢是丘脑），这是最常被互换的考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0103", "t": "多选题", "s": "关于颅脑横断面半卵圆中心层面的断层影像解剖，描述正确的有", "o": {"A": "该层面位于胼胝体上方，双侧侧脑室尚未出现或仅见顶部", "B": "半卵圆中心由投射纤维、联络纤维和连合纤维共同构成", "C": "CT上白质相对灰质呈略低密度，T2WI上白质信号低于皮质", "D": "中线可见大脑镰，为大脑纵裂内的硬脑膜结构", "E": "该层面可清楚显示基底节、丘脑与内囊"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-003", "kp": "半卵圆中心层面识别", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：半卵圆中心层面在胼胝体之上，侧脑室体部尚未出现或仅显示其顶部，是识别该层面的关键。B正确：半卵圆中心为大量有髓纤维汇聚区，包含投射纤维（如放射冠）、联络纤维（如上纵束）和连合纤维（如胼胝体辐射）。C正确：白质髓鞘含脂质、含水量低，CT呈略低密度，T2WI信号低于灰质皮质，T1WI则高于皮质。D正确：大脑镰为纵裂内硬脑膜皱襞，CT上因含少量钙化或与血管邻近常呈线状稍高密度。【为什么错】E错误：基底节、丘脑与内囊位于更低的层面（侧脑室体部及室间孔层面），半卵圆中心层面尚未出现这些灰质核团，见到它们即说明层面偏低。", "tr": "半卵圆中心层面的判定依据是“见不到侧脑室体部与基底节”；若图像上出现内囊“><”形结构，说明已进入基底节区层面，不能再称半卵圆中心层面。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0104", "t": "单选题", "s": "中脑层面横断面图像上，位于两侧大脑脚之间、呈尖端向前三角形的脑池是", "o": {"A": "环池", "B": "脚间池", "C": "四叠体池", "D": "桥前池", "E": "小脑延髓池"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-004", "kp": "中脑层面脑池识别", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】中脑层面上，两侧大脑脚呈“八”字形向前外分开，其间的三角形低密度／长T2信号区即脚间池，内含大脑后动脉起始段、小脑上动脉及动眼神经出脑处，故选B。【为什么错】A环池位于中脑（大脑脚）的外侧，呈细带状绕行，向后与四叠体池相续，不在两脚之间。C四叠体池位于中脑背侧、上下丘后方，内有大脑大静脉与松果体。D桥前池位于脑桥腹侧，层面更低。E小脑延髓池（枕大池）位于延髓背侧与小脑之间，层面最低。", "tr": "脚间池、环池、四叠体池在中脑同一层面上呈“前—外—后”依次环绕的关系；蛛网膜下腔出血时三者同时高密度，容易混淆定位，务必以大脑脚为参照。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0105", "t": "多选题", "s": "有关海马的MRI断层影像解剖，正确的描述有", "o": {"A": "垂直于海马长轴的斜冠状面是显示海马结构的最佳方位", "B": "海马位于颞叶内侧、侧脑室下角（颞角）的内下方", "C": "高分辨T2WI上可辨认海马沟、齿状回与海马伞", "D": "横断面上海马位于中脑的外侧，与环池相邻", "E": "横断面上海马位于四叠体池的后方"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-005", "kp": "海马断层解剖与最佳成像方位", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】A正确：海马长轴自前外下斜向后内上，只有做垂直于其长轴的斜冠状面才能获得真正的“横截面”，避免容积效应造成的假性信号增高。B正确：海马位于颞叶内侧面，构成侧脑室下角的内下壁。C正确：3.0 T高分辨T2WI（层厚2～3 mm）可分辨海马沟残腔、齿状回、海马伞及海马内部结构。D正确：横断面上海马头体部位于中脑外侧，与环池仅隔脉络裂相邻，颞叶钩回疝时即在此处压迫中脑。【为什么错】E错误：四叠体池位于中脑背侧，海马尾虽可延伸至该区外侧，但海马主体并不位于四叠体池后方，该描述定位错误。", "tr": "评估颞叶癫痫时若仅做常规横断面，海马会因斜切产生部分容积效应而被误判为“信号增高、体积缩小”，斜冠状面T2WI／FLAIR是避免假阳性的关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0106", "t": "多选题", "s": "构成大脑动脉环（Willis环）的血管包括", "o": {"A": "双侧大脑前动脉A1段", "B": "前交通动脉", "C": "双侧颈内动脉床突上段（终末段）", "D": "双侧大脑中动脉M1段", "E": "双侧后交通动脉与大脑后动脉P1段"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-006", "kp": "Willis环组成与CTA/MRA显示", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】Willis环位于蝶鞍上方、脚间池内，由前交通动脉（1条）、双侧大脑前动脉A1段（水平段）、双侧颈内动脉床突上段、双侧后交通动脉与双侧大脑后动脉P1段（交通前段）共9条血管首尾相接构成，故A、B、C、E正确。【为什么错】D错误：大脑中动脉M1段虽由颈内动脉终末端发出，但它不参与环的闭合，只是从环上发出的分支，不属于Willis环的组成血管。", "tr": "大脑中动脉是Willis环最常被误加入的血管；另需注意大脑后动脉参与成环的是P1段（交通前段）而非P2段，交通动脉发育不良／缺如是环不完整的常见变异。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0107", "t": "单选题", "s": "垂体MRI冠状面上，行于海绵窦腔内、紧邻颈内动脉海绵窦段外侧的脑神经是", "o": {"A": "动眼神经", "B": "滑车神经", "C": "三叉神经眼支", "D": "展神经", "E": "面神经"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-007", "kp": "海绵窦区断层解剖", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】海绵窦内穿行的脑神经中，只有展神经（第Ⅵ对）真正位于海绵窦腔内，紧贴颈内动脉海绵窦段的外侧走行，其余神经均嵌于海绵窦外侧壁的两层硬膜之间，故选D。【为什么错】A动眼神经位于海绵窦外侧壁最上方。B滑车神经位于外侧壁、动眼神经的下方。C三叉神经眼支（V1）位于外侧壁、滑车神经下方，其下方为上颌支（V2）。E面神经不经过海绵窦，它经内耳道入面神经管，属桥小脑角区结构。", "tr": "海绵窦病变时展神经因“泡在窦腔内”最早受累，出现单纯外展受限；命题常以“外侧壁自上而下依次为Ⅲ、Ⅳ、V1、V2”与“腔内为Ⅵ和颈内动脉”作对照设题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0108", "t": "案例分析题", "s": "患者女性，56岁，突发右侧肢体无力3天。临床需明确病灶与内囊后肢皮质脊髓束的空间关系，以判断预后并指导康复。科室配备3.0 T MRI，可任意设定成像基线与方位。技师需要在一次横断面采集中，尽可能在同一或相邻层面上完整显示尾状核头、内囊前肢、膝部、后肢、豆状核与丘脑的相互关系，同时保证左右两侧对称便于对比。此时最恰当的扫描基线设置是", "o": {"A": "以正中矢状面定位，横断面平行于前连合—后连合（AC-PC）连线扫描", "B": "横断面平行于听眦线（OM线）扫描，层厚8 mm", "C": "横断面平行于颅底（眶耳基线以下）扫描，层厚10 mm", "D": "横断面平行于胼胝体膝—压部连线上方15°倾斜扫描", "E": "直接采用冠状面扫描替代横断面"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-008", "kp": "基底节区扫描基线与断层显示", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】前连合—后连合（AC-PC）连线是脑功能影像与立体定向的国际通用标准基线。以正中矢状面定位、横断面平行于AC-PC线扫描时，基底节区诸核团与内囊三部分恰好位于同一水平面内，可在一个层面上完整显示“尾状核头—内囊前肢—豆状核—内囊后肢—丘脑”由内前向外后的排列，且左右对称性最好，便于测量与随访对比，故选A。【为什么错】B听眦线（OM线）是常规颅脑CT基线，相对AC-PC线约有10°～15°夹角，会使基底节结构斜切、前后肢不在同一层面。C平行于颅底扫描倾斜度更大，基底节区被明显斜切，且后颅窝伪影增多。D该基线为主观设定，无标准依据，且过度倾斜会破坏左右对称性。E冠状面虽利于观察内囊上下走行，但无法一次显示尾状核头至丘脑的前后毗邻顺序，且不是本题要求的横断面方案。", "tr": "OM线适用于常规颅脑CT，AC-PC线适用于需要精确解剖定位的MRI；把两者混用会导致基底节层面斜切，出现内囊“看不全”的假象。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0109", "t": "单选题", "s": "颈部CT横断面图像上，会厌前间隙（前会厌间隙）所处的位置是", "o": {"A": "舌骨、舌会厌襞与会厌之间的脂肪间隙", "B": "会厌与杓状会厌襞之间", "C": "甲状软骨板与环状软骨之间", "D": "真声带与假声带之间", "E": "咽后壁与椎前筋膜之间"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-001", "kp": "喉部间隙断层解剖", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】会厌前间隙位于舌骨与甲状舌骨膜之前上方、舌会厌襞之下、会厌软骨之前，是充填脂肪的三角形区域，CT上呈明确脂肪密度，是会厌癌向前扩散的重要通道，故选A。【为什么错】B会厌与杓状会厌襞之间为梨状窝上部，属下咽结构。C甲状软骨板与环状软骨之间为环甲间隙／环甲膜区。D真声带与假声带之间为喉室，是含气腔隙。E咽后壁与椎前筋膜之间为咽后间隙，属颈深部筋膜间隙，与喉内间隙无关。", "tr": "会厌前间隙与声门旁间隙同为喉癌扩散途径，前者位于会厌之前呈脂肪三角，后者位于甲状软骨内侧、呈上下走行的条形脂肪带，两者层面与形态均不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0110", "t": "多选题", "s": "在颈部断层影像上，关于咽旁间隙及其分区的描述，正确的有", "o": {"A": "茎突及茎突诸肌将咽旁间隙分为茎突前间隙与茎突后间隙", "B": "茎突后间隙即颈动脉间隙，内含颈内动脉、颈内静脉与第Ⅸ～Ⅻ对脑神经", "C": "茎突前间隙主要为脂肪，并含腮腺深叶与咽升动脉", "D": "咽旁间隙在横断面上呈尖端向下的倒锥形脂肪影，是判断邻近病变来源方向的重要标志", "E": "咽旁间隙的下界终止于舌骨水平，不与颌下间隙相通"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-002", "kp": "咽旁间隙分区与内容", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：茎突及其附着的茎突舌肌、茎突舌骨肌、茎突咽肌构成分界，将咽旁间隙分为前、后两部。B正确：茎突后间隙即颈动脉间隙（颈动脉鞘区），内含颈内动脉、颈内静脉、迷走神经及舌咽、副、舌下神经与交感干。C正确：茎突前间隙以脂肪为主，含腮腺深叶、咽升动脉及三叉神经下颌支分支。D正确：咽旁间隙横断面呈倒置锥形脂肪低密度区，其受压移位方向可提示病变来源——向内移位提示腮腺深叶来源，向外移位提示咽黏膜间隙来源。【为什么错】E错误：咽旁间隙上起颅底，下达舌骨大角水平，并经其下端与颌下间隙、咽后间隙相通，是感染向下蔓延至纵隔的潜在途径。", "tr": "“咽旁脂肪移位方向”是定位病变来源的经典技巧：脂肪被推向外侧提示咽黏膜间隙（如鼻咽癌），推向内侧提示腮腺深叶肿瘤，推向前方提示颈动脉间隙病变。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0111", "t": "多选题", "s": "有关颈部筋膜间隙的断层影像解剖，下列描述正确的有", "o": {"A": "咽后间隙位于咽后壁与椎前筋膜之间，向下可直接通向后纵隔", "B": "颈深筋膜浅层、中层与深层均参与颈动脉鞘的构成", "C": "“危险间隙”位于咽后间隙与椎前间隙之间，由翼状筋膜分隔", "D": "椎前间隙位于椎前筋膜与椎体、椎前肌之间", "E": "咽旁间隙内主要为淋巴组织，几乎不含脂肪"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-003", "kp": "颈深筋膜间隙分区", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：咽后间隙上起颅底，下至上纵隔（约T3水平），是咽部感染向纵隔蔓延的主要途径。B正确：颈动脉鞘由颈深筋膜浅层（封套筋膜）、中层（气管前筋膜）和深层（椎前筋膜）三层共同参与构成，故颈动脉间隙上下贯通颅底至主动脉弓。C正确：翼状筋膜位于咽后间隙与椎前筋膜之间，其与椎前筋膜间的潜在腔隙称“危险间隙”，可下达膈肌水平。D正确：椎前间隙位于椎前筋膜深面与椎体、颈长肌之间，结核性脓肿常积聚于此。【为什么错】E错误：咽旁间隙以脂肪为主要成分，正是这一脂肪信号／密度使其在CT、MRI上易于辨认，并可依其受压方向判断病变来源。", "tr": "咽后间隙感染下达上纵隔，危险间隙可下达膈肌，两者蔓延范围不同；CT上二者难以直接区分，报告时统称“咽后区”更稳妥。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U01-0112", "t": "单选题", "s": "喉部CT横断面上，判断层面已达真声带水平最可靠的解剖标志是", "o": {"A": "甲状软骨上角", "B": "杓状软骨声带突", "C": "环状软骨板下缘", "D": "舌骨大角", "E": "会厌软骨游离缘"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-004", "kp": "喉部层面识别标志", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】声带附着于杓状软骨的声带突，横断面上一旦显示杓状软骨声带突，即为真声带层面；此层面上双侧声带呈三角形软组织影，前端汇合于甲状软骨内面构成前联合，故选B。【为什么错】A甲状软骨上角位于喉的上部，相当于舌骨下方，远高于声带。C环状软骨板下缘位于声带下方，属声门下区。D舌骨大角为舌骨水平标志，位于会厌层面附近，明显高于声带。E会厌软骨游离缘所在层面为喉前庭上部，位于假声带之上。", "tr": "假声带层面见到的是杓状软骨的“肌突”及较多脂肪，密度偏低；真声带层面见“声带突”且声带呈均匀软组织密度，二者最可靠的鉴别就是杓状软骨的哪一个突。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0113", "t": "案例分析题", "s": "患者男性，58岁，右颈部无痛性肿块2个月，吸烟史30年。颈部增强CT示：右侧颈内静脉链周围多发肿大淋巴结，最大者短径18 mm，中央呈低密度坏死。测量显示这组淋巴结的上界位于舌骨体下缘水平，下界位于环状软骨下缘水平，位于胸锁乳突肌深面、颈内静脉外侧。技师在整理图像与结构化报告时，需按国际通用的颈部淋巴结影像学分区标准对该组淋巴结进行定位标注。该组淋巴结应标注为", "o": {"A": "Ⅱ区", "B": "Ⅲ区", "C": "Ⅳ区", "D": "Ⅴ区", "E": "Ⅵ区"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-005", "kp": "颈部淋巴结影像学分区", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】颈部淋巴结影像学分区以横断面上可重复识别的骨性／软骨标志为界：Ⅱ区自颅底至舌骨体下缘，Ⅲ区自舌骨体下缘至环状软骨下缘，Ⅳ区自环状软骨下缘至锁骨上缘，三者均沿颈内静脉链分布。本例上界为舌骨体下缘、下界为环状软骨下缘，恰好符合Ⅲ区（颈内静脉中组），故选B。【为什么错】A Ⅱ区上界为颅底、下界为舌骨体下缘，本例位于舌骨下方，不符。C Ⅳ区位于环状软骨下缘以下至锁骨，本例下界止于环状软骨下缘，未进入Ⅳ区。D Ⅴ区为颈后三角区，位于胸锁乳突肌后缘之后、斜方肌前缘之前，本例位于胸锁乳突肌深面、颈内静脉外侧，不属后三角。E Ⅵ区为中央区（气管前、气管旁、喉前），位于双侧颈总动脉之间，本例明显偏外侧。", "tr": "分区边界必须用横断面上的舌骨体下缘、环状软骨下缘、胸锁乳突肌后缘这三个影像学标志，而不能沿用外科触诊描述；此外Ⅱ区与Ⅲ区的分界是“舌骨体下缘”，不是“舌骨上缘”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "颈部", "页": 8}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0114", "t": "单选题", "s": "胸部CT横断面上，奇静脉弓自后向前跨过右主支气管上方汇入上腔静脉后壁，该层面相当于", "o": {"A": "胸骨颈静脉切迹水平", "B": "主动脉弓上缘水平", "C": "主动脉弓下缘与气管隆突之间", "D": "左心房水平", "E": "膈肌顶水平"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-001", "kp": "奇静脉弓层面识别", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】奇静脉沿脊柱右前方上行，至约第4胸椎水平（气管杈上方）向前弓形跨过右主支气管根部上方，汇入上腔静脉后壁。该处在CT横断面上位于主动脉弓下缘之下、气管隆突之上，故选C。【为什么错】A胸骨颈静脉切迹水平相当于胸廓入口，此处可见头臂静脉与三大分支动脉，奇静脉尚未成弓。B主动脉弓上缘水平所见为左头臂静脉、三大分支血管，奇静脉仍在脊柱旁上行。D左心房层面已在隆突下方数厘米，奇静脉弓早已汇入。E膈肌顶水平仅见奇静脉与半奇静脉的下段及主动脉裂孔区结构。", "tr": "奇静脉弓层面是纵隔淋巴结分区中第4R组（下气管旁）与第2R组（上气管旁）的分界标志之一；勿把奇静脉弓的“弓形高密度”误判为纵隔淋巴结或右上肺静脉。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0115", "t": "单选题", "s": "CT横断面上，左肺动脉与左主支气管之间的位置关系是", "o": {"A": "左肺动脉始终位于左主支气管的正前方", "B": "左肺动脉跨过左主支气管上方并转向其后外侧下行", "C": "左肺动脉位于左主支气管的正下方", "D": "左肺动脉位于左主支气管的内侧并与食管相邻", "E": "左肺动脉在左主支气管内部走行"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-002", "kp": "肺门血管与支气管毗邻", "ch": "一、人体断面影像解剖 → 3.胸部 → (3)主要断层影像解剖", "ex": "【为什么对】左肺动脉在肺门处呈“骑跨”式：先自肺动脉干向左后上方走行，跨过左主支气管上方，然后转至其后外侧下行成为左下肺动脉。因此在连续横断面上，高层面见左肺动脉在支气管上方，低层面见其位于支气管后外侧，选B。【为什么错】A“始终位于正前方”描述的是右肺动脉（右肺动脉主干经升主动脉与上腔静脉后方向右横行，位于右主支气管前方）。C左肺动脉不在左主支气管下方，下方为左下肺静脉引流区。D左主支气管内侧邻近的是降主动脉与食管，不是左肺动脉。E血管不可能在支气管腔内走行，属明显错误。", "tr": "记忆口诀“右前左上”——右肺动脉在右主支气管前方、左肺动脉跨越左主支气管上方；这是左右肺门断层最核心的不对称点，也是肺门肿块定位的解剖依据。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0116", "t": "多选题", "s": "有关肺叶、肺段的断层影像解剖，下列描述正确的有", "o": {"A": "右肺上叶分为尖段（S1）、后段（S2）和前段（S3）", "B": "左肺上叶因无独立后段，S1与S2合为尖后段", "C": "右肺中叶分为外侧段（S4）和内侧段（S5）", "D": "左肺下叶常缺如内侧底段，或与前底段合并为前内侧底段", "E": "右肺下叶背段（S6）位于斜裂后方最上部，其前方紧邻中叶"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-003", "kp": "肺段划分与断层定位", "ch": "一、人体断面影像解剖 → 3.胸部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：右肺上叶三段划分为S1尖段、S2后段、S3前段。B正确：左肺上叶尖段与后段合并称尖后段（S1+2），另有前段S3及上、下舌段S4、S5。C正确：右肺中叶只有外侧段S4与内侧段S5两段。D正确：左肺下叶多缺乏独立的内侧底段（S7），常与前底段合并为前内侧底段（S7+8）。【为什么错】E错误：背段（S6）位于下叶最上部、斜裂后方，其前方隔斜裂相邻的是上叶后段（右侧S2），而不是中叶；中叶位于斜裂前下、水平裂之下，与背段不在同一水平。", "tr": "背段（S6）与上叶后段（S2）以斜裂为界“前后相贴”，是CT上最易混淆的一对肺段；判断时先找斜裂走行，斜裂之后为下叶，之前为上叶。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0117", "t": "多选题", "s": "关于纵隔分区及各区内容结构的断层影像解剖，正确的有", "o": {"A": "前纵隔位于胸骨后与心包、大血管前缘之间，含胸腺、脂肪与淋巴结", "B": "中纵隔含心包、心脏、升主动脉、肺动脉干、上腔静脉、气管分叉与膈神经", "C": "后纵隔含降主动脉、食管、奇静脉与半奇静脉、胸导管及交感干", "D": "成人胸腺多被脂肪替代，CT上呈脂肪密度伴少量条索状软组织影", "E": "血管前间隙属于中纵隔的组成部分"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-004", "kp": "纵隔分区及内容", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】A正确：前纵隔（血管前间隙）以胸骨后缘为前界、心包及大血管前缘为后界，是胸腺瘤、畸胎瘤、淋巴瘤、甲状腺肿“4T”好发部位。B正确：中纵隔以心包及大血管所占区域为主，含心脏、升主动脉、肺动脉干、上腔静脉、气管及分叉、主支气管、膈神经与相应淋巴结。C正确：后纵隔位于心包后缘与椎体前缘（或椎旁沟）之间，含降主动脉、食管、奇静脉与半奇静脉、胸导管、交感干及迷走神经。D正确：成人胸腺随年龄脂肪化，CT表现为前纵隔脂肪密度内散在条索状软组织，勿误为病变。【为什么错】E错误：血管前间隙位于大血管之前、胸骨之后，恰恰是前纵隔的核心区域，不属于中纵隔。", "tr": "前纵隔＝血管前间隙，这一等价关系常被反向设错；另需注意胸腺“脂肪化”与真正的前纵隔肿块的鉴别，前者密度接近脂肪、无占位效应。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U01-0118", "t": "单选题", "s": "四腔心层面的胸部CT横断面上，位置最靠前、紧邻胸骨后方的心腔是", "o": {"A": "左心房", "B": "左心室", "C": "右心房", "D": "右心室", "E": "主动脉根部"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-005", "kp": "心腔断层位置关系", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】心脏在胸腔内呈左前下斜位，四腔心层面上四个心腔的前后顺序为：右心室最靠前（紧贴胸骨后方与前胸壁），其后为左心室，右心房居右侧，左心房位于最后方并紧邻食管与降主动脉，故选D。【为什么错】A左心房位置最靠后，是判断左心房增大时压迫食管的解剖基础。B左心室位于右心室的左后方，构成心脏左缘与心尖。C右心房构成心脏右缘，位于右侧偏后，不是最靠前的心腔。E主动脉根部位于四腔心层面上方（五腔心／左室流出道层面），且居于心脏中央偏右后，并非紧邻胸骨。", "tr": "“最前是右室、最后是左房”是胸部断层的基本口诀；心包积液和外伤时右心室最易受压，左心房增大最先影响食管，均由此位置关系决定。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0119", "t": "多选题", "s": "有关胸部CT上叶间裂的断层影像表现，正确的描述有", "o": {"A": "常规层厚（5～10 mm）横断面上，右肺水平裂常表现为相对乏血管的透亮带", "B": "薄层高分辨CT上叶间裂可直接显示为纤细的线状高密度影", "C": "斜裂在横断面上自后内斜向前外，上部层面位置偏后，向下逐层前移", "D": "奇静脉裂由奇静脉及其包绕的四层胸膜内陷形成，位于右肺上叶内侧", "E": "叶间裂处无胸膜结构，仅为肺组织之间的自然间隙"}, "d": "中", "c": "分析", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-006", "kp": "叶间裂断层表现", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】A正确：水平裂近似与扫描层面平行，厚层图像上因部分容积效应不能显示为线，而表现为血管稀疏的透亮带。B正确：HRCT层厚1 mm左右时，脏层胸膜相互贴合可直接呈现为细线状高密度影。C正确：斜裂近似冠状斜行，在上部层面靠近后胸壁，随层面下降逐渐向前外移动，至下部层面已接近前胸壁。D正确：奇静脉裂为发育变异，奇静脉在下移过程中携带两层脏层胸膜与两层壁层胸膜共四层内陷形成，其内侧的肺组织称奇静脉叶。【为什么错】E错误：叶间裂正是相邻肺叶脏层胸膜相互返折贴合所形成的结构，并非无胸膜的自然间隙；正因为含胸膜，才可在HRCT上显示为线状影，并成为病变蔓延的屏障。", "tr": "厚层上水平裂“看不见线只见乏血管带”是正常现象，不可据此报告叶间裂缺如；判断胸腔积液是否为叶间积液，也要依据叶间裂走行而非单纯位置。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0120", "t": "案例分析题", "s": "患者男性，62岁，吸烟40年，低剂量CT筛查发现右肺门旁一直径12 mm的实性结节。呼吸科要求明确该结节位于哪一肺段、与哪一级支气管相邻，以便制定胸腔镜下肺段切除方案。原始数据为64排CT螺旋采集，可任意做薄层重建与后处理。作为技师，为准确完成肺段定位，最恰当的技术处理方案是", "o": {"A": "以≤1 mm层厚重建，沿段支气管走行做多平面重组（MPR）与曲面重组，逐级追踪叶—段支气管以确定结节所属肺段", "B": "直接在5 mm轴位图像上按结节与胸壁的距离估算肺段", "C": "只做冠状面10 mm厚层重组，观察结节与肺门的关系", "D": "做全肺最小密度投影（MinIP）后按气道透亮度判断肺段", "E": "增加管电流重新扫描一次，用高噪声抑制算法提高结节边缘清晰度"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-007", "kp": "肺段定位的重建策略", "ch": "一、人体断面影像解剖 → 3.胸部 → (3)主要断层影像解剖", "ex": "【为什么对】肺段的解剖学定义是“段支气管及其伴行肺动脉所支配的肺组织”，因此肺段定位的金标准是追踪支气管树。采用亚毫米（≤1 mm）薄层重建可获得各向同性体素，再沿支气管长轴做MPR／曲面重组，能够连续追踪主支气管—叶支气管—段支气管，确定结节归属，同时显示段间静脉这一段间分界标志，故A最恰当。【为什么错】B 5 mm厚层因部分容积效应无法分辨段支气管，用与胸壁距离估算属主观推测。C 10 mm厚层冠状重组丢失细节，且单一方位难以追踪三维走行的段支气管。D MinIP有利于显示气道整体形态与低密度病变，但不能明确结节与段支气管的三维隶属关系。E本例问题在于后处理方法而非图像噪声，重新扫描既增加受检者剂量又不解决定位问题，违背防护最优化原则。", "tr": "肺段定位要“跟着支气管走”，而不是“按胸壁分区猜”；段间静脉走行于相邻两段之间，可辅助勾画段界，段内动脉与段支气管伴行则确认段属。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0121", "t": "单选题", "s": "按Couinaud分段法，横断面上肝右静脉所分隔的两个肝区是", "o": {"A": "左内叶与左外叶", "B": "右前叶与右后叶", "C": "左半肝与右半肝", "D": "尾状叶与左外叶", "E": "S2段与S3段"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-001", "kp": "肝静脉与肝段分界", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】三支肝静脉是Couinaud分段的纵行分界标志：肝右静脉走行于右叶间裂内，将肝右叶分为右前叶（S5、S8）与右后叶（S6、S7），故选B。【为什么错】A左内叶与左外叶由肝左静脉及镰状韧带／静脉韧带裂分隔。C左、右半肝由肝中静脉与胆囊窝—下腔静脉连线（Cantlie线）所在平面分隔。D尾状叶（S1）以静脉韧带裂与左外叶相隔，并非肝右静脉。E S2与S3段由门静脉左支矢状部所在的横断平面上下分隔，与肝右静脉无关。", "tr": "“肝中静脉分左右、肝右静脉分前后、肝左静脉分内外”是三句核心口诀；而上下（S8/S5、S7/S6、S4a/S4b）的分界是门静脉左右支主干所在横断面，属于横行标志，切勿与纵行的肝静脉混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0122", "t": "多选题", "s": "关于Couinaud肝段划分所依据的断层影像标志，正确的有", "o": {"A": "肝中静脉与胆囊窝—下腔静脉连线所在的纵行平面（Cantlie线）分隔左、右半肝", "B": "镰状韧带／静脉韧带裂与肝左静脉分隔左外叶（S2、S3）与左内叶（S4）", "C": "门静脉左、右支主干所在的横断平面将各叶再分为上、下段", "D": "尾状叶（S1）接受左、右门静脉双重供血，其静脉直接回流入下腔静脉", "E": "S4段位于肝右叶前段，紧邻胆囊窝右侧"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-002", "kp": "Couinaud分段标志平面", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：Cantlie线为功能性左右半肝分界，其体表投影自胆囊窝中点至下腔静脉左缘，横断面上以肝中静脉为标志。B正确：左段间裂由肝左静脉及其上方的镰状韧带、下方的静脉韧带裂共同确定，分隔S2、S3与S4。C正确：门静脉左、右支主干所在的横断面为上下段的分界，其上为S8、S7、S4a、S2，其下为S5、S6、S4b、S3。D正确：尾状叶血供与回流均独立，门静脉左右支均有分支供血，肝短静脉直接汇入下腔静脉，故Budd-Chiari综合征时尾状叶代偿性肥大。【为什么错】E错误：S4为左内叶（方叶），位于镰状韧带／静脉韧带裂与肝中静脉之间，属左半肝，位于胆囊窝的左侧而非右侧；胆囊窝右侧为S5。", "tr": "S4属于左半肝这一点常被忽视——胆囊窝是左右半肝的分界，胆囊左侧是S4、右侧是S5；此外S1的“双重供血、直接回流”特点是尾状叶在肝硬化与Budd-Chiari中表现特殊的解剖基础。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U01-0123", "t": "单选题", "s": "肾门层面横断面图像上，肾蒂内主要结构由前向后的排列顺序是", "o": {"A": "肾动脉、肾静脉、肾盂", "B": "肾静脉、肾动脉、肾盂", "C": "肾盂、肾动脉、肾静脉", "D": "肾静脉、肾盂、肾动脉", "E": "肾动脉、肾盂、肾静脉"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-003", "kp": "肾蒂结构排列顺序", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】肾蒂内结构由前向后依次为肾静脉、肾动脉、肾盂（可记为“静—动—盂”或“V-A-P”），横断面增强皮髓质期最易辨认，故选B。【为什么错】A、C、D、E均颠倒了三者的前后顺序。补充：左肾静脉较长，跨越腹主动脉前方汇入下腔静脉，若被腹主动脉与肠系膜上动脉夹持则形成“胡桃夹现象”；右肾动脉较长，需经下腔静脉后方向右走行，这两点是肾蒂断层解剖的重要延伸。", "tr": "肾蒂顺序为“前静后盂”，与肺门“前静后支”不同，也与肝门“前胆管、后门静脉、居中肝动脉”的三联管排列不同，三者常被交叉设错。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0124", "t": "多选题", "s": "有关腹膜后间隙的断层影像分区与内容，下列描述正确的有", "o": {"A": "肾旁前间隙位于后腹膜与肾前筋膜之间，含胰腺、十二指肠降部与水平部及升、降结肠", "B": "肾周间隙位于肾前筋膜与肾后筋膜之间，含肾、肾上腺、肾周脂肪及输尿管上段", "C": "肾旁后间隙位于肾后筋膜与腹横筋膜之间，主要为脂肪，无实质脏器", "D": "急性胰腺炎的渗出液最常首先累及肾旁前间隙", "E": "左、右肾周间隙在中线区广泛相通，故一侧积液常迅速蔓延至对侧"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-004", "kp": "腹膜后间隙三分区", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：肾旁前间隙前界为后腹膜、后界为肾前筋膜（Gerota筋膜），内含胰腺、十二指肠降部与水平部、升结肠与降结肠。B正确：肾周间隙位于肾前筋膜与肾后筋膜（Zuckerkandl筋膜）之间，内容为肾、肾上腺、输尿管上段及肾周脂肪。C正确：肾旁后间隙内仅有脂肪、血管与神经，无实质器官，向外与腹膜外脂肪相续。D正确：胰腺位于肾旁前间隙内，故急性胰腺炎渗液首先沿该间隙蔓延，向下可达髂窝。【为什么错】E错误：左右肾周间隙在中线区被大血管及其周围结缔组织分隔，一般不直接相通；两侧交通主要通过肾旁后间隙及骨盆入口区的潜在通道，且交通有限，故临床上肾周积液多为单侧局限。", "tr": "“肾周间隙左右不通、肾旁前间隙可向下延续至髂窝”是判断腹膜后积液来源的关键；胰腺炎渗液出现于肾旁前间隙、肾上腺出血局限于肾周间隙，反推可定位病变。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0125", "t": "单选题", "s": "上腹部CT横断面上，能够勾勒胰腺体尾部后缘、作为其可靠定位标志的血管是", "o": {"A": "肠系膜上动脉", "B": "脾静脉", "C": "腹腔干", "D": "左肾静脉", "E": "门静脉主干"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-005", "kp": "胰腺断层定位标志", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】脾静脉自脾门向右走行，紧贴胰腺体尾部的后缘，横断面上呈一条自左向右的细带状血管影，正好勾勒出胰体尾的后界，并在胰颈后方与肠系膜上静脉汇合成门静脉，因此是胰腺体尾部最可靠的定位标志，选B。【为什么错】A肠系膜上动脉起自腹主动脉前壁，位于胰颈后下方，其周围脂肪环是判断胰腺钩突与血管关系的标志，但不勾勒胰体尾后缘。C腹腔干位于胰腺上方水平（约T12），是胰腺上界的层面标志而非后缘。D左肾静脉走行于胰腺后方更深处、腹主动脉前方，位置低于脾静脉，二者不可混淆。E门静脉主干位于胰颈后方斜向右上走行至肝门，只能标志胰颈区。", "tr": "脾静脉与左肾静脉在横断面上都呈横行走行、易混淆：脾静脉紧贴胰后缘、位置偏上偏前；左肾静脉跨越腹主动脉前方、位置偏下偏后，且向右汇入下腔静脉。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0126", "t": "案例分析题", "s": "患者男性，64岁，进行性无痛性黄疸1个月。上腹部CT平扫加三期增强示胰头区一约30 mm低强化肿块，胆总管下段截断，胰管扩张。外科需要明确肿瘤与肠系膜上动脉、肠系膜上静脉及腹腔干的接触范围和角度，以评估可切除性。设备为128层CT，已获得0.625 mm薄层动脉期与门静脉期数据。为准确显示胰腺钩突与肠系膜上动脉的空间关系，技师应采取的最佳后处理方案是", "o": {"A": "以薄层横断面为基础，加做沿肠系膜上动脉长轴的斜冠状面与斜矢状面重组，并辅以曲面重组测量肿瘤—血管接触弧度", "B": "仅保留5 mm常规横断面图像，由医师直接阅片判断", "C": "对全部数据做大范围最大密度投影（MIP），仅提供血管整体图像", "D": "做容积再现（VR）彩色三维图像替代所有断面图像", "E": "将门静脉期图像做10 mm厚层冠状重组以突出肿瘤边界"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-006", "kp": "胰腺钩突与肠系膜血管关系评估", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】胰腺钩突自胰头下部向左后方延伸，位于肠系膜上静脉与肠系膜上动脉的后方、下腔静脉与腹主动脉的前方，三者呈“前—中—后”叠置关系。单纯横断面难以完整显示纵向走行的肠系膜上动脉全长，故需以薄层横断面为基础，沿血管长轴加做斜冠状／斜矢状重组，并用曲面重组测量肿瘤包绕血管的接触弧度（＜180°与≥180°是判断可切除性的关键阈值），故A最恰当。【为什么错】B 5 mm厚层分辨率不足，无法准确测量接触弧度与判断钩突边界。C MIP会把肿瘤等软组织信息叠掩，只适合展示血管走行，不能替代断面评估。D VR为表面渲染性质的展示图，受阈值影响大，不能用于定量测量与浸润判断。E 10 mm厚层因部分容积效应会人为夸大或掩盖肿瘤与血管的接触面。", "tr": "钩突“绕到肠系膜上静脉后方”是其独有特征，横断面上表现为胰头下部向左侧延伸的楔形组织；勿把钩突正常组织误判为肿块，也勿仅凭横断面判断动脉包绕程度。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0127", "t": "案例分析题", "s": "患者女性，48岁，乙肝肝硬化随访，上腹部MRI发现肝内一枚直径15 mm结节，介入科拟行射频消融，要求影像报告精确注明结节所在的Couinaud肝段及与邻近肝静脉、门静脉分支的距离。技师需在3.0 T设备上完成检查，并在工作站上完成分段定位标注。为使肝段定位准确可靠，最恰当的做法是", "o": {"A": "以屏气薄层T1加权三维梯度回波（T1-FFE／VIBE／LAVA）门静脉期数据为基础，先在横断面上辨认三支肝静脉与门静脉左右支主干平面，再据此逐层划分肝段", "B": "在T2WI上按结节距肝右缘的距离估算肝段", "C": "以体表肋骨计数投影推算结节所在肝段", "D": "仅用弥散加权成像（DWI）高信号灶的位置确定肝段", "E": "以冠状面单次激发快速自旋回波（SSFSE／HASTE）图像作为分段的唯一依据"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-007", "kp": "MRI肝段定位技术", "ch": "一、人体断面影像解剖 → 4.腹部 → (2)MRI断层表现", "ex": "【为什么对】Couinaud分段依赖两类标志：纵行的三支肝静脉（分左右、分前后、分内外）与横行的门静脉左右支主干平面（分上下段）。屏气薄层三维扰相梯度回波序列在门静脉期可同时清晰显示肝静脉与门静脉分支，层厚薄、无呼吸伪影，是分段定位的最佳数据源，故A正确。【为什么错】B按距肝缘距离估算完全不符合以血管为界的分段原则。C体表肋骨计数受体位、呼吸相与个体差异影响极大，不能用于肝段定位。D DWI层厚较厚、几何变形明显、缺少血管解剖信息，只能提示病灶存在。E冠状面SSFSE可辅助观察病灶上下位置，但难以显示肝静脉与门静脉分支的完整走行，不能作为唯一依据。", "tr": "肝段定位一定要“先找血管再定段”；此外应注意扫描时的屏气状态一致，呼吸相不同会造成同一结节在不同序列上跨段错位，影响消融布针。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0128", "t": "单选题", "s": "女性盆腔MRI矢状面T2WI上，子宫体自内向外呈现三层信号，其中“结合带”表现为", "o": {"A": "最内层的高信号带，代表子宫内膜", "B": "内膜外侧的低信号带，代表内层子宫肌层", "C": "最外层的中等信号带，代表外层子宫肌层", "D": "浆膜面的极低信号线，代表子宫浆膜", "E": "宫腔内的无信号区，代表宫腔积气"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-001", "kp": "子宫T2WI三层结构", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】育龄期女性子宫体在T2WI上自内向外呈三层：内层为高信号的子宫内膜，中层为低信号的结合带（junctional zone，即排列致密、含水量低的内层肌层），外层为中等信号的外层子宫肌层，故选B。【为什么错】A最内层高信号是子宫内膜本身，不是结合带。C最外层中等信号为外层肌层。D浆膜层极薄，MRI上通常不能单独分辨为一层。E宫腔正常不含气，宫腔积气属病理表现，与三层结构无关。", "tr": "结合带增厚（一般＞12 mm）是子宫腺肌症的重要征象，而结合带的中断则是判断子宫内膜癌肌层浸润深度的关键；勿把T2WI上低信号的结合带误认为是子宫内膜或病变。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0129", "t": "多选题", "s": "关于盆底与会阴部的断层影像解剖，下列描述正确的有", "o": {"A": "肛提肌由耻骨直肠肌、耻骨尾骨肌和髂骨尾骨肌组成", "B": "坐骨肛门窝（坐骨直肠窝）内充满脂肪，横断面上呈尖端向上的楔形", "C": "直肠系膜由直肠固有筋膜包绕，内含脂肪、血管与淋巴结，是全直肠系膜切除的解剖基础", "D": "会阴中心腱（会阴体）位于肛管与阴道下段或尿道球之间", "E": "尿生殖膈位于肛提肌的上方，构成盆膈的上层"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-002", "kp": "盆底肌与会阴断层解剖", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：肛提肌为盆膈主体，由耻骨直肠肌、耻骨尾骨肌与髂骨尾骨肌三部分构成，MRI冠状面显示其“漏斗状”形态最佳。B正确：坐骨肛门窝位于肛管两侧，上界为肛提肌下面、外侧界为闭孔内肌与坐骨结节，内充脂肪，横断面呈尖向上的楔形（冠状面呈三角形），是肛周脓肿与瘘管好发部位。C正确：直肠系膜是直肠周围由直肠固有筋膜包绕的脂肪结缔组织，含直肠上血管与淋巴结，其筋膜（MRF）是否受累决定直肠癌手术方式与新辅助治疗决策。D正确：会阴中心腱是多块会阴肌的共同附着点，女性位于阴道下段与肛管之间，男性位于尿道球与肛管之间。【为什么错】E错误：尿生殖膈位于盆膈（肛提肌与尾骨肌）的下方、尿生殖三角内，不在肛提肌上方，更不构成盆膈的上层。", "tr": "盆膈在上、尿生殖膈在下，二者上下关系颠倒是常见错误；此外坐骨肛门窝内的脂肪信号是判断肛瘘走行分级（括约肌间型、经括约肌型、括约肌上型、括约肌外型）的背景对照。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0130", "t": "单选题", "s": "男性盆腔横断面上，位于膀胱后方、前列腺上方两侧，呈“八字形”或“兔耳”样的结构是", "o": {"A": "输精管壶腹", "B": "精囊腺", "C": "输尿管末段", "D": "直肠膀胱陷凹", "E": "前列腺静脉丛"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-003", "kp": "精囊腺断层形态", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (1)CT断层表现", "ex": "【为什么对】精囊腺位于膀胱底后方、前列腺上方、直肠前方，为一对迂曲呈囊袋状的腺体，横断面上左右对称向外后方张开，形似“八字”或“兔耳”，T2WI上因富含液体呈明显高信号，故选B。【为什么错】A输精管壶腹位于两侧精囊腺的内侧，管径较细，呈条状，不构成“兔耳”外形。C输尿管末段自后外斜向前内穿膀胱壁，管径细小，且不成对呈囊袋状。D直肠膀胱陷凹是腹膜返折形成的腔隙，位于膀胱与直肠之间，非实性成对结构。E前列腺静脉丛（Santorini丛）位于前列腺前外侧与耻骨联合之间，不在膀胱后上方。", "tr": "精囊角（膀胱后壁与精囊之间的脂肪间隙）消失是前列腺癌或膀胱癌侵犯精囊的重要征象；勿把T2WI上高信号的正常精囊误判为囊性病变。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0131", "t": "单选题", "s": "仰卧位时女性腹膜腔的最低部位、少量盆腔积液最先积聚的解剖间隙是", "o": {"A": "膀胱子宫陷凹", "B": "直肠子宫陷凹", "C": "卵巢窝", "D": "膀胱前间隙", "E": "闭孔内肌旁间隙"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-004", "kp": "盆腔腹膜陷凹", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】直肠子宫陷凹（又称Douglas窝）位于子宫与直肠之间，是女性站立位与仰卧位时腹膜腔的最低点，少量腹腔积液、积血或腹膜转移种植最先出现于此，故选B。【为什么错】A膀胱子宫陷凹位置较高、较浅，积液出现晚于直肠子宫陷凹。C卵巢窝位于髂内、髂外血管夹角处的盆侧壁，为卵巢所在位置，不是最低点。D膀胱前间隙（Retzius间隙）位于腹膜外，不与腹膜腔相通，其内积液多为膀胱破裂或血肿。E闭孔内肌旁间隙不属于腹膜腔陷凹。", "tr": "男性对应的最低点为直肠膀胱陷凹；此外要注意膀胱前间隙为腹膜外间隙，其积液性质与腹膜腔积液的临床意义完全不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0132", "t": "案例分析题", "s": "患者男性，60岁，便血3个月，肠镜示距肛缘7 cm处直肠肿物，病理为腺癌。外科要求术前MRI明确肿瘤浸润深度、直肠系膜筋膜（MRF）是否受累以及壁外血管侵犯情况，以决定是否行新辅助放化疗。设备为3.0 T MRI，使用体部相控阵线圈。为满足上述分期要求，技师在扫描方位设置上最恰当的做法是", "o": {"A": "先获取正中矢状面定位，再设置垂直于病变段直肠肠管长轴的斜横断面高分辨小视野T2WI，并辅以平行于肠管长轴的斜冠状面", "B": "沿人体解剖轴设置常规横断面T2WI，层厚6 mm，视野40 cm", "C": "仅采集矢状面T2WI与横断面T1WI增强，不做斜断面", "D": "采用大视野横断面脂肪抑制T2WI以覆盖全盆腔淋巴结", "E": "以弥散加权成像替代高分辨T2WI进行分期"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-005", "kp": "直肠MRI分期的斜断面设置", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】直肠在盆腔内呈骶曲与会阴曲，肠管长轴与人体解剖横轴并不垂直。只有以正中矢状面定位、设置垂直于病变段肠管长轴的斜横断面，才能获得肠壁的真正“横截面”，准确判断肿瘤突破固有肌层的深度（T分期）以及肿瘤最外缘与直肠系膜筋膜之间的最短距离（MRF状态）。高分辨（层厚3 mm、小视野、高矩阵）T2WI是国际公认的直肠癌分期序列，斜冠状面则有助于评估低位肿瘤与肛提肌、括约肌复合体的关系，故A正确。【为什么错】B常规横断面斜切肠壁会造成部分容积效应，人为夸大浸润深度；6 mm层厚与40 cm视野分辨率不足。C缺少与肠管垂直的斜断面，无法准确测量MRF距离；且直肠癌分期以高分辨T2WI为主，增强并非必需。D脂肪抑制会消除直肠系膜脂肪与肿瘤的天然对比，反而不利于判断MRF受累与壁外血管侵犯。E DWI敏感性高但空间分辨率低、几何变形明显，只能作为T2WI的补充，不能替代分期序列。", "tr": "直肠MRI分期的高分辨T2WI原则上不加脂肪抑制——直肠系膜脂肪的高信号背景正是判断肿瘤外侵与MRF距离的对比来源；斜横断面“垂直于肿瘤所在段肠管”而非垂直于整个直肠。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0133", "t": "单选题", "s": "腰椎MRI上，经L4／5椎间孔穿出椎管的神经根是", "o": {"A": "L3神经根", "B": "L4神经根", "C": "L5神经根", "D": "S1神经根", "E": "马尾神经末端"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-001", "kp": "腰椎间孔与神经根对应关系", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (2)MRI断层表现", "ex": "【为什么对】腰段脊神经根自同序数椎体下方的椎间孔穿出，即L4神经根经L4／5椎间孔出椎管，故选B。该神经根在孔内位于孔的上部、紧邻上位椎弓根下缘，称为“出口根”。【为什么错】A L3神经根经L3／4椎间孔穿出。C L5神经根经L5／S1椎间孔穿出；但L5在L4／5水平已离开硬膜囊并沿侧隐窝下行，称为该节段的“走行根”，旁中央型L4／5椎间盘突出压迫的正是L5而非L4。D S1神经根经S1骶前孔穿出，在L5／S1水平为走行根。E马尾神经在腰段椎管内成束下行，不特指某一椎间孔的穿出根。", "tr": "同一椎间盘水平存在“出口根”与“走行根”两套神经根：椎间孔型（极外侧型）突出压迫出口根（L4／5压迫L4），旁中央型突出压迫走行根（L4／5压迫L5）；把二者混淆是最典型的失分点。颈段规律与腰段不同——颈神经根从同序数椎体上方的椎间孔穿出，C8经C7／T1孔穿出。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0134", "t": "多选题", "s": "有关椎管横断面的影像解剖，下列描述正确的有", "o": {"A": "硬膜外间隙内含脂肪与静脉丛，以腰段最为丰富", "B": "黄韧带附着于相邻椎板的前面，T2WI上呈相对低信号", "C": "侧隐窝前界为椎体后缘或椎间盘，后界为上关节突，外侧界为椎弓根内缘", "D": "成人脊髓圆锥末端多位于第1腰椎下缘水平", "E": "齿状韧带位于脊髓正后方中线处，连接软脊膜与硬脊膜"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-002", "kp": "椎管内结构断层解剖", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：硬膜外间隙位于硬脊膜与椎管骨壁之间，含脂肪、椎内静脉丛与结缔组织，腰段脂肪最丰富，是T1WI上勾勒硬膜囊轮廓的天然对比。B正确：黄韧带由弹力纤维构成，连接相邻椎板前面，T1WI与T2WI均呈相对低信号，肥厚时可致椎管后方受压。C正确：侧隐窝是神经根离开硬膜囊后进入椎间孔前的通道，其三个边界即前为椎体后缘／椎间盘、后为上关节突、外为椎弓根内缘，狭窄时压迫走行根。D正确：成人脊髓圆锥末端多位于T12下缘至L1下缘水平，低于L2下缘则提示脊髓栓系。【为什么错】E错误：齿状韧带位于脊髓两侧、脊神经前根与后根之间，呈三角形齿状突起连于硬脊膜，起固定脊髓的作用，并非位于脊髓正后方中线。", "tr": "侧隐窝狭窄与椎间孔狭窄压迫的神经根不同：侧隐窝压迫走行根，椎间孔压迫出口根；此外脊髓圆锥位置是判断脊髓栓系的定量指标，勿凭印象报告。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-0135", "t": "单选题", "s": "颈椎CT横断面上，成人寰齿前间隙（寰椎前弓后缘与齿突前缘之间距离）的正常上限约为", "o": {"A": "1 mm", "B": "2 mm", "C": "3 mm", "D": "5 mm", "E": "7 mm"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-003", "kp": "寰枢关节测量标准", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (1)CT断层表现", "ex": "【为什么对】寰齿前间隙由寰椎横韧带维持，成人正常不超过3 mm，超过3 mm提示寰椎横韧带损伤或松弛（如类风湿关节炎、外伤、先天性齿突畸形），故选C。【为什么错】A、B为正常范围内的常见数值，但不是判定上限。D 5 mm是儿童（12岁以下）的正常上限，因儿童韧带较松弛、齿突尚未完全骨化，若用于成人会漏诊寰枢不稳。E 7 mm已明显超出成人与儿童的正常范围，提示横韧带完全断裂。", "tr": "成人≤3 mm、儿童≤5 mm是一对必须分清的数值；此外横断面测量易受层面倾斜影响，标准做法是在寰椎前弓与齿突同层的横断面或正中矢状面重组图像上测量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0136", "t": "案例分析题", "s": "患者男性，55岁，右下肢放射痛3个月，疼痛沿大腿前外侧至小腿内侧分布，膝反射减弱，符合L4神经根受累表现。腰椎MRI常规横断面未见明显中央型或旁中央型椎间盘突出，硬膜囊形态正常。临床高度怀疑椎间孔区或极外侧病变。设备为1.5 T MRI。为明确椎间孔内神经根的受压情况，最应重点采集或重点观察的图像是", "o": {"A": "经双侧椎间孔的旁矢状面薄层T1WI，观察孔内脂肪是否被病变取代及神经根形态", "B": "正中矢状面T2WI，观察椎管前后径", "C": "冠状面脂肪抑制T2WI，观察椎旁肌信号", "D": "横断面梯度回波T2*加权，观察椎体骨髓信号", "E": "全脊柱大范围矢状面定位像，测量脊柱曲度"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-004", "kp": "椎间孔狭窄的成像方位选择", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (2)MRI断层表现", "ex": "【为什么对】腰椎间孔在旁矢状面上呈上宽下窄的“倒泪滴”形，孔内神经根位于上部，被高信号脂肪环绕。T1WI上脂肪信号高、神经根呈中等信号，两者对比最佳，一旦孔内脂肪被突出椎间盘、骨赘或囊肿取代，即提示椎间孔狭窄与出口根受压，故A最恰当。本例症状为L4出口根受累而横断面阴性，正是极外侧／椎间孔型突出的典型情况。【为什么错】B正中矢状面只能评价中央椎管，无法显示位于侧方的椎间孔。C冠状面脂肪抑制T2WI主要用于评估椎旁软组织与骶髂关节，且脂肪抑制反而消除了椎间孔内脂肪这一重要对比。D T2*加权对骨髓与出血敏感，与椎间孔神经根受压评估无关。E定位像分辨率低，只能测曲度，不能评估神经根。", "tr": "极外侧型（椎间孔外）椎间盘突出在常规横断面上位于扫描范围边缘，极易漏诊；凡症状与影像不符的根性痛，务必加做旁矢状面T1WI并适当扩大横断面覆盖至椎弓根外缘。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0137", "t": "单选题", "s": "腕关节影像上，近侧列腕骨由桡侧向尺侧的排列顺序是", "o": {"A": "手舟骨、月骨、三角骨、豌豆骨", "B": "大多角骨、小多角骨、头状骨、钩骨", "C": "月骨、手舟骨、豌豆骨、三角骨", "D": "手舟骨、大多角骨、月骨、三角骨", "E": "头状骨、月骨、三角骨、钩骨"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-001", "kp": "腕骨排列与识别", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (1)CT断层表现", "ex": "【为什么对】腕骨共8块，分近、远两列。近侧列由桡侧向尺侧依次为手舟骨、月骨、三角骨、豌豆骨，故选A。【为什么错】B为远侧列腕骨的正确排列（大多角骨、小多角骨、头状骨、钩骨），题目问的是近侧列。C颠倒了手舟骨与月骨、三角骨与豌豆骨的顺序。D把远侧列的大多角骨混入近侧列。E把远侧列的头状骨与钩骨混入近侧列。", "tr": "豌豆骨是籽骨，位于三角骨掌侧，在横断面上比其他近侧列腕骨更靠掌侧、层面更低；手舟骨腰部骨折因血供自远端逆行进入，近端易发生缺血坏死，是CT／MRI追加检查的重点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-0138", "t": "多选题", "s": "关于膝关节MRI的断层影像解剖，下列描述正确的有", "o": {"A": "前交叉韧带起自胫骨髁间隆起前区，止于股骨外侧髁的内侧面，斜矢状面显示最佳", "B": "后交叉韧带在矢状面上呈弓形，正常时各序列均呈较均匀低信号", "C": "半月板在矢状面周边层面呈“领结征”，靠近中央的层面呈前后两个三角形", "D": "关节软骨在质子密度加权脂肪抑制序列上与关节液、软骨下骨的对比较好", "E": "内侧半月板较外侧半月板活动度大，因此更易发生撕裂"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-002", "kp": "膝关节MRI断层解剖", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】A正确：前交叉韧带自胫骨髁间隆起前区斜向后上外，止于股骨外侧髁内侧面，其走行与矢状面成角，需将扫描平面向外旋转约15°做斜矢状面才能在单一层面完整显示。B正确：后交叉韧带纤维致密、含水量低，矢状面呈弓形，各序列均为均匀低信号，若出现内部高信号提示损伤。C正确：矢状面上周边层面切到半月板体部，前后角相连呈“领结征”（bow-tie sign），越靠近关节中央越只见前、后角两个三角形。D正确：质子密度加权脂肪抑制序列兼具较高信噪比与软骨—关节液对比，是关节软骨评价的常用序列。【为什么错】E错误：内侧半月板呈“C”形，其外缘与内侧副韧带深层及关节囊紧密相连，活动度小、缓冲能力差，因此更容易撕裂；外侧半月板近“O”形，与外侧副韧带之间隔有腘肌腱，活动度反而更大。", "tr": "“活动度小反而更易撕裂”与直觉相反，是内侧半月板撕裂发生率更高的力学原因；另需注意“领结征”少于两个层面提示桶柄样撕裂，是矢状面判读的重要间接征象。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U01-0139", "t": "单选题", "s": "肩关节MRI斜冠状面上，构成肩袖上部、经肩峰下间隙走行且最常发生撕裂的肌腱是", "o": {"A": "肩胛下肌腱", "B": "冈上肌腱", "C": "冈下肌腱", "D": "小圆肌腱", "E": "肱二头肌长头腱"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-003", "kp": "肩袖构成与成像方位", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】肩袖由冈上肌、冈下肌、小圆肌和肩胛下肌四条肌腱构成。冈上肌腱位于肩袖上部，自冈上窝经肩峰与肱骨头之间的肩峰下间隙止于肱骨大结节上压迹，此处空间狭小、血供相对乏乏（“危险区”位于止点内侧约1 cm），撞击与退变最重，是最常撕裂的肌腱，斜冠状面（平行于冈上肌腱长轴）显示最佳，故选B。【为什么错】A肩胛下肌腱位于肩袖前部，止于小结节，斜横断面显示最佳。C冈下肌腱位于肩袖后上部，止于大结节中压迹。D小圆肌腱位于肩袖后下部，止于大结节下压迹，撕裂少见。E肱二头肌长头腱并不属于肩袖，它经结节间沟进入关节内止于盂上结节，属关节内滑膜外结构。", "tr": "肱二头肌长头腱常被误列入肩袖；肩关节MRI三个基本方位各有分工——斜冠状面看冈上肌腱、斜矢状面看肩袖间隙与肩峰形态、横断面看肩胛下肌腱与盂唇前后部。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1001", "t": "单选题", "s": "颅脑CT增强横断面图像上，小脑幕的典型形态与位置是", "o": {"A": "在颅前窝呈水平走行的低密度线状影", "B": "在颅后窝上方呈“V”形（或“八”字形）走行的致密线状影", "C": "在颅中窝呈横行的低密度宽带影", "D": "在小脑半球之间呈垂直走行的致密带", "E": "在枕骨内板下方呈新月形低密度影"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-101", "kp": "小脑幕断层表现", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】小脑幕为硬脑膜突入颅腔形成的结构，分隔枕叶与小脑，其游离缘围成小脑幕切迹。横断面增强扫描或老年钙化时，小脑幕呈自前内侧向后外侧走行、形似“V”字（“八”字形）的致密线状影，故选B。【为什么错】A小脑幕位于颅后窝，不位于颅前窝；颅前窝内容以额叶为主。C颅中窝主要为颞叶与蝶鞍区结构，小脑幕在颅后窝上方而非颅中窝。D垂直走行、分隔左右小脑半球的硬脑膜结构是小脑镰，小脑幕呈斜行。E新月形低密度影多见于硬膜下积液（血）或蛛网膜下腔增宽，与硬脑膜内层结构无关。", "tr": "小脑幕（斜行、分隔枕叶与小脑）与小脑镰（垂直、分隔左右小脑半球）形态与位置不同，是断层识别的经典易混点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1002", "t": "单选题", "s": "正中矢状面MRI上，第四脑室的位置与形态正确的是", "o": {"A": "位于脑桥腹侧，呈水平带状低信号", "B": "位于脑桥与延髓后方、小脑前方，呈帐篷状（三角形）", "C": "位于中脑导水管前方，呈裂隙状", "D": "位于小脑蚓部后上方，呈类圆形", "E": "位于延髓腹侧，呈新月形"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-102", "kp": "第四脑室MRI断层表现", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】第四脑室位于脑桥、延髓背侧与小脑腹侧之间，上借中脑导水管通第三脑室，下连脊髓中央管。正中矢状面上其轮廓呈顶朝后上、底朝前下的帐篷状（近似三角形），T1WI呈均匀低信号，故选B。【为什么错】A脑桥腹侧为桥前池，第四脑室在其背侧。C中脑导水管位于第四脑室上方、中脑内，其前方为四叠体池，并非导水管位于第四脑室前方。D小脑蚓部后上方为枕大池（小脑延髓池），呈三角形或新月形脑脊液信号，非第四脑室。E延髓腹侧为延髓前池，第四脑室在延髓背侧。", "tr": "第四脑室横断面呈菱形（菱形窝概念），矢状面呈帐篷状（三角形），两种断面形态勿混；第四脑室始终位于脑干背侧、小脑腹侧。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1003", "t": "单选题", "s": "正中矢状面T1WI上，关于胼胝体的形态学描述正确的是", "o": {"A": "胼胝体自前向后依次分为嘴部、膝部、体部、压部", "B": "胼胝体位于侧脑室体部的后方", "C": "胼胝体膝部与穹窿相延续", "D": "胼胝体压部位于嘴部的前方", "E": "胼胝体是大脑皮质灰质的一部分"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-103", "kp": "胼胝体矢状面解剖", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】胼胝体是连接两侧大脑半球的最大连合纤维，位于大脑纵裂底，正中矢状面上自前向后依次为嘴部（最前下方）、膝部、体部、压部（最后方），故选A。【为什么错】B胼胝体位于侧脑室体部上方，其下为透明隔与侧脑室，而非位于其后方。C与胼胝体相延续的是穹窿附近的穹窿连合，胼胝体膝部并不与穹窿延续；穹窿位于胼胝体下方、第三脑室上方。D压部是胼胝体最后方的膨大部，嘴部在最前方，两者位置颠倒。E胼胝体为白质纤维束（连合纤维），不是灰质。", "tr": "胼胝体四部分由前向后的顺序（嘴、膝、体、压）易倒置；它属白质连合纤维而非灰质，正中矢状面显示最清楚。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1004", "t": "单选题", "s": "经桥小脑角池层面的横断面CT上，池内穿行的颅神经是", "o": {"A": "视神经与动眼神经", "B": "面神经与前庭蜗神经", "C": "舌咽神经与迷走神经", "D": "三叉神经与展神经", "E": "嗅神经与滑车神经"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-104", "kp": "桥小脑角池内容物", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】桥小脑角池位于脑桥与小脑之间、内耳门前内侧，面神经（Ⅶ）与前庭蜗神经（Ⅷ）自脑干发出后经该池进入内听道，故选B。【为什么错】A视神经走行于眶内及视神经管，动眼神经位于脚间池及鞍上池区域。C舌咽神经、迷走神经位于延髓外侧池（桥小脑角池下方）及颈静脉孔附近。D三叉神经位于桥前池，其神经节位于Meckel腔（三叉神经腔）；展神经位于桥前池下部。E嗅神经在嗅沟，滑车神经细长、走行于环池。", "tr": "面神经与前庭蜗神经（Ⅶ、Ⅷ）共同穿桥小脑角池进入内听道；三叉神经（Ⅴ）位于桥前池及Meckel腔，两者池别最易混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1005", "t": "单选题", "s": "成人颅脑CT上，松果体钙化的解剖定位标志是", "o": {"A": "位于鞍上池的中央", "B": "位于四叠体池内、紧邻第三脑室后方", "C": "位于侧脑室三角区内", "D": "位于桥小脑角池内", "E": "位于枕大池内"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-105", "kp": "松果体钙化定位", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】松果体位于中脑背侧、四叠体池内，其前上方紧邻第三脑室后部（松果体隐窝），成人钙化发生率很高，是颅脑CT上重要的解剖定位标志，故选B。【为什么错】A鞍上池中央可见视交叉与垂体柄，松果体位置远在其后上方。C侧脑室三角区内的生理钙化为脉络丛球钙化，松果体不位于脑室内。D桥小脑角池位于脑桥外侧，内为面神经与前庭蜗神经。E枕大池位于颅后窝小脑后方与枕骨之间，内为脑脊液。", "tr": "松果体钙化（四叠体池、第三脑室后）与脉络丛球钙化（侧脑室三角区）是CT上两个常见的生理性钙化，位置一前一后，极易混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1006", "t": "单选题", "s": "经第三脑室层面的横断面CT上，位于丘脑外侧、内囊外方的灰质核团是", "o": {"A": "尾状核头", "B": "豆状核", "C": "杏仁核", "D": "屏状核", "E": "红核"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-106", "kp": "基底节区核团位置关系", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】第三脑室层面由内向外可见丘脑、内囊后肢、豆状核（由壳核与苍白球组成）、屏状核、岛叶。内囊位于丘脑与豆状核之间，豆状核位于丘脑外侧、内囊外方，故选B。【为什么错】A尾状核头位于内囊前肢的内侧、侧脑室前角外侧。C杏仁核位于颞叶钩回内侧，属边缘系统，位置更靠下。D屏状核位于豆状核与岛叶皮质之间，较豆状核更靠外，不符合“内囊外方紧邻”的定位。E红核位于中脑被盖部，在第三脑室层面更下方。", "tr": "基底节断层“内囊前肢—尾状核头、内囊后肢—丘脑、豆状核—内囊外”的毗邻顺序常设陷阱；屏状核在豆状核更外侧、紧邻岛叶。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1007", "t": "单选题", "s": "鞍上池层面横断面CT上，视交叉的解剖位置是", "o": {"A": "位于垂体柄后方，呈圆形钙化影", "B": "位于鞍上池中央前部，呈“束带”状连接双侧视神经与视束", "C": "位于大脑脚之间，呈三角形", "D": "位于外侧裂池内", "E": "位于脑桥前方，呈线状低密度"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-107", "kp": "视交叉断层解剖", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】视交叉位于鞍上池内偏前部，呈“束带”状（蝴蝶结样）软组织影，前接双侧视神经，后连双侧视束，是鞍上池内最重要的结构之一，故选B。【为什么错】A垂体柄位于视交叉后方、偏下方，视交叉位于其前方，而非垂体柄位于前方；且视交叉为软组织影而非钙化。C大脑脚之间为脚间池，内有动眼神经穿行。D外侧裂池位于额颞叶之间，视交叉与其无关。E脑桥前方为桥前池，内有三叉神经等。", "tr": "鞍上池内视交叉（前、“束带”状）与垂体柄（后、居中）的前后毗邻关系是常考点，两结构位置颠倒即成为陷阱选项。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1008", "t": "单选题", "s": "分隔两侧侧脑室前角与体部的膜性结构是", "o": {"A": "透明隔", "B": "穹窿", "C": "丘脑", "D": "尾状核", "E": "脉络丛"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-108", "kp": "透明隔断层解剖", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】透明隔是位于两侧侧脑室前角与体部之间的薄层膜性结构，由两层神经胶质组成，其前下方为胼胝体膝部，后上方为胼胝体体部，故选A。【为什么错】B穹窿位于透明隔下方、第三脑室顶壁，是边缘系统纤维束，不直接分隔侧脑室。C丘脑位于第三脑室两侧、侧脑室下方。D尾状核位于侧脑室前角外侧，不参与分隔。E脉络丛位于侧脑室体部底壁及第三、四脑室顶，为脑脊液产生部位。", "tr": "透明隔（分隔左右侧脑室）与穹窿（第三脑室上方）位置相邻、功能不同，横断面上两者易被误认为同一结构。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1009", "t": "单选题", "s": "颅脑横断面CT平扫上，正常脑白质的CT值约为", "o": {"A": "0～10 HU", "B": "20～24 HU", "C": "30～35 HU", "D": "60～100 HU", "E": "1000 HU以上"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-109", "kp": "颅脑正常结构CT值", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】颅脑CT平扫中，正常脑白质CT值约为30～35 HU，灰质约35～40 HU，两者相差仅约5 HU，灰质略高于白质，故选C。【为什么错】A 0～10 HU为脑脊液（脑室、脑池）的CT值范围。B 20～24 HU偏低，更接近水肿或囊变区。D 60～100 HU为钙化灶的常见范围。E 1000 HU以上为致密骨皮质（内耳、颞骨岩部）的CT值。", "tr": "灰质（35～40 HU）与白质（30～35 HU）CT值仅相差5 HU左右，方向易记反（应为灰质略高于白质），是窗宽窗位调节中需牢记的数值。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1010", "t": "单选题", "s": "横断面CT经侧脑室下角层面，下列结构定位描述错误的是", "o": {"A": "侧脑室下角—位于颞叶内", "B": "外侧裂—分隔额叶与颞叶", "C": "环池—围绕中脑", "D": "内听道—位于枕骨内", "E": "桥小脑角池—位于岩骨与小脑之间"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-110", "kp": "侧脑室下角层面结构定位", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】题干要求选出错误的定位描述。内听道位于颞骨岩部（岩锥）后内侧面，是面神经与前庭蜗神经穿行的骨性管道，而非位于枕骨内，故D错误。【为什么错】A侧脑室下角（颞角）确实伸入颞叶内，描述正确。B外侧裂是分隔额叶与颞叶的脑沟，其深部有岛叶，描述正确。C环池围绕中脑，连接四叠体池与脚间池，描述正确。E桥小脑角池位于颞骨岩部（岩骨）后内缘与小脑之间，面神经、前庭蜗神经穿行其中，描述正确。", "tr": "内听道位于颞骨岩部（而非枕骨），其前方为耳蜗、后方为前庭，是断层定位常考点；枕骨内对应枕大孔与枕内嵴。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U01-1011", "t": "单选题", "s": "颈部CT横断面图像上，关于甲状腺的解剖描述正确的是", "o": {"A": "甲状腺左右叶位于气管前方，峡部位于气管两侧", "B": "甲状腺位于气管前外侧，峡部跨越气管前方连接左右叶", "C": "甲状腺位于颈动脉鞘的外侧", "D": "甲状腺位于胸锁乳突肌与椎体之间", "E": "甲状腺峡部位于环状软骨上方"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-101", "kp": "甲状腺断层解剖", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】甲状腺分为左右两个侧叶及中间的峡部，左右叶位于气管前外侧，峡部于第2～4气管软骨环前方跨越气管连接两叶，故选B。【为什么错】A将两叶与峡部的位置关系弄反：两叶在气管两侧，峡部在前方。C甲状腺位于颈动脉鞘内侧，颈总动脉、颈内静脉在甲状腺外侧，位置关系颠倒。D胸锁乳突肌与椎体之间为椎前结构及颈深淋巴结，甲状腺位于气管前方偏外。E峡部位于环状软骨下方（第2～4气管软骨环前方），环状软骨上方为甲状软骨及声门区。", "tr": "甲状腺“两叶贴气管两侧、峡部跨于气管前方”的位置关系，与甲状软骨（更高、声门区）、环状软骨（更低、气管起始）的层次区分是常考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1012", "t": "单选题", "s": "颈部CT上，可作为确定气管起始层面标志的喉软骨是", "o": {"A": "甲状软骨", "B": "环状软骨", "C": "会厌软骨", "D": "杓状软骨", "E": "舌骨"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-102", "kp": "环状软骨层面标志", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】环状软骨是喉部唯一的完整软骨环，构成喉的底座，其下缘即气管的起始部，因此颈横断面上环状软骨层面是确定气管起始的标志性层面，故选B。【为什么错】A甲状软骨是最大的喉软骨，呈盾牌状，位于环状软骨上方，属声门区上缘水平。C会厌软骨位于舌骨后方、喉入口前方，为扁平的弹性软骨。D杓状软骨位于真声带后方，参与构音，不成环。E舌骨是游离骨，不属喉软骨，位于甲状软骨上方。", "tr": "环状软骨（唯一完整软骨环、气管起始标志）与甲状软骨（最大喉软骨、声门区标志）的鉴别是颈部断层识别的经典考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1013", "t": "单选题", "s": "颈总动脉分叉为颈内、颈外动脉的横断面约平对", "o": {"A": "舌骨体水平", "B": "甲状软骨上缘水平（约C4椎体）", "C": "环状软骨水平", "D": "锁骨上窝水平", "E": "下颌骨下缘上方1 cm"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-103", "kp": "颈总动脉分叉水平", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】颈总动脉在甲状软骨上缘水平（约C4椎体平面）分为颈内动脉与颈外动脉，分叉处稍膨大称颈动脉窦，是颈动脉粥样硬化斑块的好发部位，故选B。【为什么错】A舌骨体约平C3水平，位于分叉部上方附近但并非分叉平面。C环状软骨约平C6水平，位于分叉部下方。D锁骨上窝水平已接近颈根部，远低于分叉部。E下颌骨下缘约平C2～C3水平，高于分叉部。", "tr": "颈总动脉分叉（甲状软骨上缘、C4）与甲状腺峡部（环状软骨下方、C6）的水平位置不同，颈部断层定位时极易混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "颈部", "页": 8}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U01-1014", "t": "单选题", "s": "颈部横断面图像上，颈动脉鞘内包含的结构是", "o": {"A": "颈总动脉、颈内静脉、迷走神经", "B": "颈总动脉、椎动脉、舌下神经", "C": "颈外动脉、胸导管、膈神经", "D": "颈内动脉、颈外静脉、交感干", "E": "颈总动脉、喉返神经、副神经"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-104", "kp": "颈动脉鞘内容", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】颈动脉鞘是颈深筋膜包绕形成的血管神经鞘，内含颈总（内）动脉、颈内静脉与迷走神经，三者由内向外依次为动脉、静脉、迷走神经，故选A。【为什么错】B椎动脉走行于颈椎横突孔内，舌下神经经舌下神经管出颅，均不在颈动脉鞘内。C胸导管在左侧颈根部汇入静脉角，膈神经走行于前斜角肌前方，均与颈动脉鞘无关。D颈外静脉位于胸锁乳突肌表面皮下，交感干位于颈动脉鞘后方、椎前筋膜深面。E喉返神经走行于气管食管沟，副神经走行于颈动脉鞘后方及胸锁乳突肌深面。", "tr": "迷走神经在颈动脉鞘内（颈内静脉与颈总动脉之间后方），而交感干、膈神经、副神经均在鞘外，“鞘内外结构”是命题热点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1015", "t": "单选题", "s": "主动脉弓层面的胸部CT横断面上，位于主动脉弓前右侧的纵隔结构是", "o": {"A": "左主支气管", "B": "上腔静脉", "C": "食管", "D": "胸主动脉", "E": "心包"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-101", "kp": "主动脉弓层面纵隔结构", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】主动脉弓层面，上腔静脉位于主动脉弓的前右侧，二者在纵隔上部形成特征性关系；气管位于主动脉弓后方（略偏右），食管在气管后方，故选B。【为什么错】A左主支气管出现在气管隆突层面（主动脉弓下方），主动脉弓层面仅见气管。C食管位于主动脉弓后方、气管后方。D胸主动脉（降主动脉）位于主动脉弓的左后下方，主动脉弓层面已开始转为其延续。E心包位于主动脉弓下方的心包层面，更靠下。", "tr": "主动脉弓层面辨认“三血管”：主动脉弓（居中偏左）、上腔静脉（前右侧）、气管与食管（后方），上腔静脉的位置是易错点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1016", "t": "单选题", "s": "胸部CT上，气管隆突约位于胸椎哪一水平，其下方分为左右主支气管", "o": {"A": "第3胸椎下缘", "B": "第4～5胸椎水平", "C": "第7胸椎水平", "D": "第9胸椎水平", "E": "第12胸椎水平"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-102", "kp": "气管隆突定位水平", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】气管隆突位于气管分叉处，约平第4～5胸椎水平，与胸骨角（Louis角）平面相当，是胸部断层影像中重要的分界标志，故选B。【为什么错】A第3胸椎下缘约平主动脉弓上缘水平，略高于隆突。C第7胸椎为下腔静脉与心脏下缘、膈顶附近水平。D第9胸椎接近肝顶水平。E第12胸椎为膈肌及肾上腺水平，与气管分叉无关。", "tr": "胸骨角（第2肋软骨、第4～5胸椎）对应气管隆突与主动脉弓下缘，“隆突=第4～5胸椎”与“弓上缘=第3胸椎”需区分。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1017", "t": "单选题", "s": "右肺门层面的胸部CT横断面上，位于中间支气管后方的结构是", "o": {"A": "右上肺静脉", "B": "右肺动脉", "C": "右主支气管", "D": "食管", "E": "上腔静脉"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-103", "kp": "右肺门层面解剖", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】右肺门层面，中间支气管呈低密度含气管道位于肺门中心，其正后方紧邻食管（食管位于脊柱前、中间支气管与右肺之间），故选D。【为什么错】A右上肺静脉位于中间支气管前方及外侧。B右肺动脉位于中间支气管前方及外侧，其下干跨过支气管前方。C右主支气管在更上方已分出右上叶支气管，中间支气管是其延续，不在其“后方”。E上腔静脉位于纵隔前方、升主动脉右侧，距中间支气管较远。", "tr": "右肺门“肺动脉在前、支气管居中、静脉偏前下”的空间关系；食管紧贴中间支气管正后方，是纵隔淋巴结与食管病变鉴别的解剖基础。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U01-1018", "t": "单选题", "s": "上腹部CT增强扫描中，胰头钩突的断层解剖位置是", "o": {"A": "位于肠系膜上静脉后方、下腔静脉前方", "B": "位于门静脉主干正前方", "C": "位于脾动脉前方", "D": "位于左肾静脉后方", "E": "位于腹主动脉正前方"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-111", "kp": "胰头钩突毗邻结构", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：胰头钩突是胰头下部向内下方伸出的突起，位于肠系膜上静脉（SMV）后方、下腔静脉（IVC）前方，被肠系膜上血管与下腔静脉夹持；胰头癌时钩突增大可致肠系膜上血管受压移位。【为什么错】B门静脉主干位于胰颈后方、胰头上方，钩突位于其下方偏后方。C脾动脉沿胰体尾上缘走行，与钩突无直接毗邻。D左肾静脉跨腹主动脉前方走行，位于胰腺后下方，钩突不以其为界。E腹主动脉位于钩突的左后方，钩突紧邻下腔静脉前方而非主动脉正前方。", "tr": "钩突位于“肠系膜上静脉后方、下腔静脉前方”，与胰头被“十二指肠降部与下腔静脉夹持”是两个不同的夹持关系，勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1019", "t": "单选题", "s": "横断面CT增强扫描上，右肾上腺的典型形态是", "o": {"A": "三角形", "B": "倒“Y”形（“人”字形）", "C": "水平线形", "D": "圆形结节状", "E": "新月形贴于下腔静脉前方"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-102", "kp": "肾上腺断层形态", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】右肾上腺位于右肾上极内上方、下腔静脉后方、肝右叶内侧，横断面上呈倒“Y”形（“人”字形）或线形，故选B。【为什么错】A三角形是左肾上腺的典型形态。C水平线形为非典型描述，肾上腺有明确的肢体结构。D圆形结节提示肾上腺增生或腺瘤，正常肾上腺不呈圆形结节。E右肾上腺位于下腔静脉后方而非前方，新月形贴附不是其正常形态。", "tr": "左右肾上腺形态不对称：右侧呈倒“Y”/人字形，左侧呈三角形/半月形；位置一右（下腔静脉后方）一左（脾静脉后方），勿记反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1020", "t": "单选题", "s": "上腹部CT横断面上，关于胰尾与脾门位置关系的描述正确的是", "o": {"A": "胰尾位于脾门后方", "B": "胰尾位于脾门前方（脾脏内前方）", "C": "胰尾位于脾脏外侧", "D": "胰尾位于脾脏下方", "E": "胰尾与脾脏不相邻"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-103", "kp": "胰尾与脾门位置关系", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】胰尾自胰体向左延伸，位于脾门前方（脾脏内前方），脾静脉走行于胰尾后方，脾动脉沿胰体尾上缘走行，故选B。【为什么错】A胰尾在脾门前方而非后方，脾门后为左肾上极区域。C胰尾向脾门方向延伸，位于脾脏内侧，不会越过脾脏到外侧。D胰尾在脾门水平，与脾门相邻，脾脏下方为结肠脾曲。E胰尾与脾门关系密切，是脾脏血管与胰腺关系的解剖基础。", "tr": "胰尾紧邻脾门前方、脾静脉在其后方，此关系是胰腺尾部肿瘤与脾门结构鉴别的关键解剖依据。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1021", "t": "单选题", "s": "肾门层面横断面CT增强扫描，右肾静脉与下腔静脉的解剖关系是", "o": {"A": "右肾静脉短而粗，直接注入下腔静脉右侧壁", "B": "右肾静脉细长，绕腹主动脉后方注入下腔静脉", "C": "右肾静脉走行于腹主动脉前方汇入下腔静脉", "D": "右肾静脉汇入左肾静脉后再入下腔静脉", "E": "右肾静脉位于右肾动脉后方且较长"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-104", "kp": "右肾静脉与下腔静脉关系", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】右肾静脉短而粗，在肾门水平几乎水平走行，直接注入下腔静脉右侧壁；左肾静脉长，跨越腹主动脉前方后汇入下腔静脉左前壁，故选A。【为什么错】B右侧肾静脉短，长且绕腹主动脉后方的是左肾静脉的变异描述，方向错误。C跨越腹主动脉前方的是左肾静脉，不是右肾静脉。D左右肾静脉分别独立汇入下腔静脉，两者不相通汇。E右肾静脉短，右肾动脉反而较长（绕下腔静脉后方入右肾门），方向刚好相反。", "tr": "左右肾静脉长短相反：右短直入下腔、左长跨主动脉；而肾动脉是右长（绕下腔静脉）、左短，“动静脉长短”最容易记反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1022", "t": "单选题", "s": "男性盆腔MRI轴位T2WI上，前列腺外周带与中央带（中央区+移行区）的信号特点正确的是", "o": {"A": "外周带呈高信号，中央带呈低信号", "B": "外周带呈低信号，中央带呈高信号", "C": "外周带与中央带均呈高信号", "D": "外周带与中央带均呈低信号", "E": "外周带呈低信号，中央带呈等信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-101", "kp": "前列腺T2WI分区信号", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】前列腺T2WI上，外周带富含腺体、含液量高，呈均匀高信号；中央带（中央区与移行区）富含平滑肌与基质、腺体少，呈低信号。前列腺癌好发于外周带，表现为外周带内低信号结节，故选A。【为什么错】B将两带信号完全颠倒，与T2WI实际表现不符。C两带信号存在明显差异，中央带为低信号，不会都呈高信号。D外周带为高信号，不会都呈低信号。E外周带应呈高信号而非低信号，中央带为低信号而非等信号。", "tr": "前列腺T2WI“外周带高、中央带低”的信号对比是前列腺癌诊断的基础，“中央带高信号”是常见陷阱选项。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1023", "t": "单选题", "s": "女性盆腔横断面图像上，正常卵巢最常见的定位标志是", "o": {"A": "膀胱两侧", "B": "子宫两侧、髂外动脉与髂内动脉之间的卵巢窝内", "C": "子宫直肠陷凹内", "D": "耻骨联合后方", "E": "骶骨前方紧贴直肠"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-102", "kp": "卵巢断层定位", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】卵巢位于盆腔侧壁、髂外动脉与髂内动脉之间的卵巢窝（ovarian fossa）内，即子宫体两侧偏上方，故B正确。【为什么错】A膀胱两侧主要为阔韧带及输尿管，卵巢位置更高、偏外侧。C子宫直肠陷凹（Douglas窝）为盆腔最低点、积液好发处，卵巢不位于其中。D耻骨联合后方为膀胱前区及膀胱。E骶骨前方为直肠与骶前区，卵巢位置在其前方偏外。", "tr": "卵巢在髂内外动脉分叉处（卵巢窝）、子宫两侧；绝经后卵巢萎缩缩小、识别困难时以髂血管为定位标志。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1024", "t": "单选题", "s": "会阴部横断面图像上，位于肛管两侧、肛提肌下方的脂肪间隙是", "o": {"A": "坐骨直肠窝（坐骨肛门窝）", "B": "膀胱前间隙", "C": "直肠后间隙", "D": "闭孔内肌间隙", "E": "会阴浅隙"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-103", "kp": "坐骨直肠窝断层解剖", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】坐骨直肠窝（坐骨肛门窝）位于肛管两侧、肛提肌下方，为楔形脂肪间隙，两侧对称，内含肛门血管与阴部神经等，是肛周脓肿好发部位，故选A。【为什么错】B膀胱前间隙位于耻骨联合与膀胱之间，位置在会阴前方上方。C直肠后间隙位于直肠与骶骨之间，在肛管上方。D闭孔内肌间隙为闭孔内肌与周围结构间的潜在间隙，不特指肛管两侧。E会阴浅隙位于会阴浅筋膜与尿生殖膈下筋膜之间，位置更表浅且偏前。", "tr": "坐骨直肠窝（肛管两侧、肛提肌下方）与直肠后间隙（直肠与骶骨之间）一前外侧、一正后方，位置易混。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1025", "t": "单选题", "s": "腰椎MRI矢状面T2WI上，正常椎间盘髓核的信号特点是", "o": {"A": "高信号，位于纤维环内后方", "B": "高信号，位于纤维环内", "C": "低信号，与纤维环相同", "D": "无信号区", "E": "与骨皮质信号一致的低信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-101", "kp": "椎间盘髓核MRI信号", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (2)MRI断层表现", "ex": "【为什么对】椎间盘由外周纤维环与中央髓核构成，髓核含水量高，T2WI呈高信号，位于纤维环包绕的中心部，故B正确。【为什么错】A髓核位于椎间盘中心，纤维环包绕其四周，“位于纤维环内后方”不准确；向后突出的髓核组织可位于后部，但正常髓核居中。C纤维环在T2WI呈低信号，髓核为高信号，两者不同。D髓核有明确信号，不是无信号。E髓核高信号与骨皮质低信号截然不同。", "tr": "年轻正常椎间盘“纤维环低信号+髓核高信号”；老年退变髓核因脱水信号降低，勿将正常年轻表现与退变混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1026", "t": "单选题", "s": "髋关节MRI冠状面T1WI上，股骨头圆韧带（股骨头韧带）的正常MRI表现是", "o": {"A": "股骨头中央横行的低信号带", "B": "股骨头后上方的高信号区", "C": "股骨颈外侧的高信号带", "D": "股骨头内的圆形液性信号", "E": "股骨颈内侧的线状高信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-LIMB-101", "kp": "股骨头圆韧带MRI表现", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】股骨头圆韧带自股骨头凹连至髋臼横韧带，是纤维性结构，MRI冠状面上于股骨头中央呈低信号带，是重要的解剖标志，故选A。【为什么错】B股骨头后上方为圆韧带附着点附近的高信号脂肪，不是圆韧带本身。C股骨颈外侧为转子区脂肪与肌肉，非圆韧带。D股骨头内圆形液性信号提示软骨下囊变，属异常表现。E股骨颈内侧线状结构多为支持带或血管断面，圆韧带低信号带位于股骨头而非股骨颈。", "tr": "圆韧带呈股骨头内横行低信号带，勿将其误认为股骨头隐匿性骨折线；两者鉴别点是圆韧带位置恒定、走行至股骨头凹。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1027", "t": "单选题", "s": "踝关节MRI矢状面图像上，距骨滑车上方主要相对并构成承重关节面的结构是", "o": {"A": "胫骨远端关节面", "B": "跟骨前突", "C": "腓骨远端关节面", "D": "舟骨", "E": "骰骨"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-LIMB-102", "kp": "踝关节面构成", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (3)主要断层影像解剖", "ex": "【为什么对】踝关节为屈戌关节，距骨滑车上方与胫骨远端下关节面构成主要的承重关节面（胫距关节），两侧尚有内踝、外踝夹持距骨，故选A。【为什么错】B跟骨前突与骰骨、舟骨形成跟骰关节、距跟舟关节，属跗骨间关节，不直接参与踝关节承重。C腓骨远端（外踝）与距骨外侧关节面构成踝关节的外侧部分，但其主要承重面在胫距之间。D舟骨与距骨头形成距舟关节，属跗横关节的一部分。E骰骨与跟骨前突相关节，与距骨滑车无关。", "tr": "踝关节主要承重面是胫距关节面（距骨滑车上为胫骨远端），腓骨外踝只参与外侧构成，“距骨上方对应腓骨”是常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1028", "t": "多选题", "s": "关于小脑幕及小脑幕切迹的断层影像解剖，正确的描述有", "o": {"A": "小脑幕分隔枕叶与小脑", "B": "横断面增强扫描小脑幕呈“V”形致密线影", "C": "小脑幕切迹内有中脑通过", "D": "小脑幕前缘附着于枕骨内板及横窦沟", "E": "幕切迹疝可压迫同侧动眼神经"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-111", "kp": "小脑幕及幕切迹", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】A小脑幕呈水平位略后倾的硬脑膜结构，将颅腔分隔为幕上（枕叶为主）与幕下（小脑为主）两部分，正确。B增强扫描或钙化时小脑幕在横断面上呈“V”（“八”）字形致密线影，正确。C小脑幕游离缘围成的幕切迹内有中脑通过，正确。E小脑幕切迹疝（钩回疝）时，中脑受压、同侧动眼神经受压可致同侧瞳孔散大，正确。【为什么错】D小脑幕后缘（外侧缘）附着于枕骨内板及横窦沟，而前缘为游离缘、围成幕切迹，附着于颞骨岩部上缘及鞍背（后床突），该项将前后缘附着关系颠倒，错误。", "tr": "小脑幕“后缘附着枕骨、前缘游离围成切迹”，附着关系是辨析重点；幕切迹疝压迫动眼神经与钩回（海马旁回钩）有明确对应关系。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1029", "t": "多选题", "s": "关于侧脑室各部的断层影像解剖，正确的描述有", "o": {"A": "侧脑室前角伸入额叶", "B": "侧脑室后角伸入枕叶", "C": "侧脑室下角伸入颞叶", "D": "侧脑室体部位于顶叶深部", "E": "侧脑室三角区仅位于顶叶内"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-112", "kp": "侧脑室分部", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】A侧脑室前角（额角）向前伸入额叶，其外侧为尾状核头，正确。B后角（枕角）向后伸入枕叶，两侧常不对称，正确。C下角（颞角）伸入颞叶内，底壁有海马，正确。D体部位于顶叶深部，其下为丘脑，正确。【为什么错】E侧脑室三角区是体部、后角、下角三者汇合处，位于顶、枕、颞三叶交界区，而非仅位于顶叶内，错误。", "tr": "侧脑室五个部分（前角、体部、后角、下角、三角区）与脑叶对应关系是断层识别的考点，三角区属三叶交界而非单一脑叶。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1030", "t": "多选题", "s": "关于颅脑各主要脑池的位置，正确的描述有", "o": {"A": "鞍上池位于蝶鞍上方", "B": "环池环绕中脑", "C": "桥小脑角池位于脑桥与小脑之间", "D": "四叠体池位于中脑背侧", "E": "枕大池位于颅前窝内"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-113", "kp": "脑池位置", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】A鞍上池位于蝶鞍（蝶骨鞍区）上方，内含视交叉、垂体柄等，正确。B环池环绕中脑，连接四叠体池与脚间池，正确。C桥小脑角池位于脑桥与小脑之间、内耳门前内侧，正确。D四叠体池位于中脑背侧（四叠体后方），内有松果体及大脑大静脉，正确。【为什么错】E枕大池（小脑延髓池）位于颅后窝小脑蚓部后方与枕骨之间，属颅后窝结构，说“位于颅前窝”错误。", "tr": "脑池归属：鞍上池（幕上）、枕大池（颅后窝）、环池（中脑周围），“枕大池在颅前窝”是常用陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1031", "t": "多选题", "s": "颅脑横断面CT由下向上逐层观察，各层面的识别要点正确的有", "o": {"A": "鞍上池层面可见视交叉与垂体柄", "B": "中脑层面可见大脑脚与黑质", "C": "第三脑室层面可见丘脑与内囊", "D": "半卵圆中心层面可见侧脑室体部", "E": "侧脑室顶消失后进入半卵圆中心层面"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-114", "kp": "颅脑断层层面识别", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】A鞍上池层面以“五角星”形脑脊液池为特征，内含视交叉、垂体柄及颈内动脉，正确。B中脑层面可见中脑、大脑脚、黑质与红核，四叠体池、环池环绕，正确。C第三脑室层面可见丘脑位于三脑室两侧、内囊后肢与豆状核，正确。E继续向上，侧脑室顶消失后即进入半卵圆中心层面，该层面仅见大脑白质区，正确。【为什么错】D半卵圆中心位于侧脑室顶部之上，该层面侧脑室已完全消失，说“可见侧脑室体部”错误，侧脑室体部见于其下方的层面。", "tr": "半卵圆中心是“侧脑室顶以上”的白质层面，层序判断“脑室→消失→半卵圆中心”是识别高层面的关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U01-1032", "t": "多选题", "s": "关于颈部甲状腺的断层影像解剖与信号表现，正确的描述有", "o": {"A": "甲状腺左右叶位于气管两侧", "B": "峡部位于第2～4气管软骨环前方", "C": "甲状腺T2WI信号低于颈部肌肉", "D": "甲状腺位于颈动脉鞘的内侧", "E": "CT增强扫描甲状腺呈明显均匀强化"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-105", "kp": "甲状腺断层解剖与信号", "ch": "一、人体断面影像解剖 → 2.颈部 → (2)MRI断层表现", "ex": "【为什么对】A甲状腺左右叶贴附于气管前外侧，正确。B峡部于第2～4气管软骨环前方连接左右叶，正确。D甲状腺位于颈动脉鞘（颈总动脉、颈内静脉）内侧，正确。E甲状腺血供丰富、含碘，CT增强扫描呈明显均匀强化，正确。【为什么错】C甲状腺因富含碘及腺体，T1WI、T2WI信号均高于颈部肌肉（与肌肉比较为稍高信号），说“低于肌肉”与MRI实际表现相反，错误。", "tr": "甲状腺MRI信号高于肌肉（含碘、富血供），与肌肉比较是记忆关键；信号方向记反即落入陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1033", "t": "多选题", "s": "关于喉部声门区CT断层影像解剖，正确的描述有", "o": {"A": "真声带层面可见前联合与后联合", "B": "真声带位于环状软骨上缘水平", "C": "喉室位于真声带与假声带之间", "D": "杓状软骨位于声门裂的前外侧", "E": "声门下区横断面呈四边形，侧壁为弹性圆锥"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-106", "kp": "喉部声门区断层解剖", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】A真声带层面声门裂前后端分别为前联合（甲状软骨板前正中）与后联合（杓状软骨声带突之间），正确。B真声带约位于环状软骨板上缘水平，是声门区标志性层面，正确。C喉室是声带与室带（假声带）之间的陷凹，正确。E声门下区由弹性圆锥围成，横断面近似四边形，正确。【为什么错】D杓状软骨位于真声带后方、声门裂后外侧（其声带突连于声带后端），说“位于声门裂前外侧”位置错误。", "tr": "杓状软骨在声门裂后方（声带突在后），前联合是双侧声带前端交汇处，“前联合—声带前、杓状软骨—声带后”的对应关系是考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1034", "t": "多选题", "s": "关于肺叶间裂与肺叶划分的CT断层影像解剖，正确的描述有", "o": {"A": "右侧水平裂分隔右上叶与右中叶", "B": "横断面上斜裂呈粗大的低密度带", "C": "左肺只有斜裂，分为上下两叶", "D": "右肺由斜裂与水平裂分为上中下三叶", "E": "右中叶支气管开口于中间支气管前外侧壁"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-104", "kp": "叶间裂与肺叶划分", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】A右侧水平裂（横裂）位于右肺门水平，分隔右上叶与右中叶，正确。C左肺仅有一条斜裂，将其分为左上叶与左下叶，正确。D右肺由斜裂与水平裂分为上、中、下三叶，正确。E右中叶支气管自中间支气管前外侧壁发出，向前外走行，正确。【为什么错】B横断面上斜裂表现为细线状影（或乏血管带），正常厚度仅1～2 mm，“粗大的低密度带”描述错误。", "tr": "叶间裂在横断面CT上呈细线状影而非低密度带；水平裂仅见于右侧，左肺无水平裂。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1035", "t": "多选题", "s": "关于腹腔干及其主要分支的断层影像解剖，正确的描述有", "o": {"A": "腹腔干发自腹主动脉前壁", "B": "腹腔干分为肝总动脉、脾动脉与胃左动脉三大分支", "C": "脾动脉沿胰体尾部上缘向左走行", "D": "肝总动脉沿胰头上缘向右走行", "E": "腹腔干位于门静脉主干前方"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-112", "kp": "腹腔干分支断层解剖", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A腹腔干于第12胸椎至第1腰椎水平发自腹主动脉前壁，是腹主动脉的第一个前壁脏支，正确。B腹腔干分出肝总动脉、脾动脉和胃左动脉三大分支，正确。C脾动脉沿胰体尾部上缘走行达脾门，正确。D肝总动脉沿胰头上缘向右走行，分出胃十二指肠动脉与肝固有动脉，正确。【为什么错】E门静脉主干位于胰颈后方、下腔静脉前方，腹腔干位于门静脉主干的后下方，说“腹腔干位于门静脉前方”位置颠倒，错误。", "tr": "腹腔干（T12～L1、腹主动脉前壁）与肠系膜上动脉（L1、位于腹腔干下方）的起始水平及分支易混；腹腔干位于门静脉主干后下方。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1036", "t": "多选题", "s": "关于上腹部门静脉系的断层影像解剖，正确的描述有", "o": {"A": "门静脉主干由肠系膜上静脉与脾静脉汇合而成", "B": "门静脉主干位于胰头后方", "C": "脾静脉走行于胰体尾部后方", "D": "门静脉在肝门处分为左、右支", "E": "门静脉主干位于下腔静脉后方"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-106", "kp": "门静脉系断层解剖", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A门静脉主干由肠系膜上静脉与脾静脉在胰颈后方汇合而成，正确。B汇合处即门静脉起始部位于胰头后上方，正确。C脾静脉自脾门发出后沿胰体尾后方走行，正确。D门静脉在肝门处分为左、右支，分别进入左右半肝，正确。【为什么错】E门静脉主干位于胰颈后方、下腔静脉的前方（二者之间隔以胰钩突/脂肪），说“位于下腔静脉后方”位置关系颠倒，错误。", "tr": "门静脉主干在下腔静脉前方、胰头后方，“门—腔”前后关系颠倒即落入陷阱；门静脉右支位于胆囊窝水平。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1037", "t": "多选题", "s": "关于男性盆腔断层影像解剖，正确的描述有", "o": {"A": "膀胱位于耻骨联合后方", "B": "精囊腺位于膀胱底后方", "C": "前列腺位于膀胱下方并包绕尿道起始部", "D": "直肠位于骶骨前方", "E": "直肠位于膀胱前方"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-104", "kp": "男性盆腔器官毗邻", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】A膀胱位于耻骨联合后方，二者间为膀胱前间隙，正确。B精囊腺位于膀胱底后方、前列腺上方两侧，正确。C前列腺位于膀胱颈下方、耻骨联合后方，包绕尿道前列腺部，正确。D直肠位于骶骨前方、膀胱及精囊腺后方，正确。【为什么错】E直肠位于膀胱及精囊腺后方（直肠膀胱陷凹后方），说“位于膀胱前方”位置错误。", "tr": "男性盆腔由前向后：膀胱—精囊腺—直肠；直肠永远在最后方紧邻骶骨，“直肠在膀胱前方”是常用陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1038", "t": "多选题", "s": "关于脊柱各段断层影像解剖与结构特点，正确的描述有", "o": {"A": "颈椎横突孔内有椎动脉走行", "B": "胸椎横突与肋骨构成肋横关节", "C": "腰椎椎管横断面近似三角形", "D": "骶骨由5块骶椎融合而成", "E": "寰椎有椎体，位于前弓与后弓之间"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-102", "kp": "脊柱分段结构特点", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】A颈椎横突孔是椎动脉穿行的骨性管道，正确。B胸椎横突末端与肋骨结节相关节（肋横关节），正确。C腰椎椎体粗大，椎管横断面呈三角形，两侧椎弓根粗短，正确。D骶骨由5块骶椎融合而成，形成骶管及骶前后孔，正确。【为什么错】E寰椎（C1）无椎体、无棘突，由前弓、后弓及两侧块构成，两侧块上关节面承托枕髁；说“寰椎有椎体”错误。", "tr": "寰椎（无椎体、承托颅骨）与枢椎（有齿突）是颈椎结构特化的重点，“寰椎有椎体”是常见陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "脊柱区", "页": 21}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1039", "t": "多选题", "s": "关于膝关节MRI断层影像解剖，正确的描述有", "o": {"A": "前交叉韧带起于胫骨髁间隆起前方，止于股骨外髁内侧面", "B": "后交叉韧带T2WI全程均呈均匀低信号", "C": "半月板T2WI呈均匀低信号", "D": "内侧半月板呈“C”形", "E": "外侧半月板较内侧半月板更近似“O”形"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-LIMB-103", "kp": "膝关节交叉韧带与半月板MRI", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】A前交叉韧带起自胫骨髁间隆起前外侧，止于股骨外髁内侧面，斜行走行，正确。C半月板含纤维软骨，T2WI呈均匀低信号，正确。D内侧半月板呈“C”形，较宽大，正确。E外侧半月板更近似“O”形，活动度较大，正确。【为什么错】B后交叉韧带虽以低信号为主，但因走行弯曲、魔角效应及部分容积效应，其近中段常可呈局灶性稍高信号，“全程均呈均匀低信号”表述过于绝对，错误。", "tr": "交叉韧带低信号中可出现魔角效应所致的假性高信号（常见于后交叉韧带中段），不可将其误诊为撕裂；“全程低信号”的绝对化表述是陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1040", "t": "多选题", "s": "颅脑MRI横断面T2WI上，下列表现中属于正常或生理性表现的有", "o": {"A": "成人松果体钙化", "B": "侧脑室枕角不对称", "C": "透明隔腔存在", "D": "脉络丛球钙化", "E": "脑室周围白质弥漫性高信号伴侧脑室扩大"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-115", "kp": "颅脑MRI正常变异与异常鉴别", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】A成人松果体钙化属正常生理性钙化，正确。B两侧侧脑室枕角（后角）大小常不对称，属正常变异，正确。C透明隔腔（第五脑室）在成人可终生存在，属正常变异，正确。D脉络丛球钙化位于侧脑室三角区，成人常见，属生理性钙化，正确。【为什么错】E脑室周围白质弥漫性高信号伴侧脑室扩大，提示脑白质病变（脱髓鞘、缺血）或脑积水/脑室旁白质异常，是异常表现而非正常表现，错误。", "tr": "松果体钙化、脉络丛钙化、枕角不对称、透明隔腔均为正常变异；而“白质高信号+脑室扩大”组合提示病变，勿将正常变异误读为病变。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U01-1041", "t": "多选题", "s": "关于颈部横断面断层影像解剖，正确的描述有", "o": {"A": "胸锁乳突肌位于颈动脉鞘的外前方", "B": "颈内静脉位于颈总动脉的前外侧", "C": "甲状腺位于胸锁乳突肌的内侧", "D": "食管位于气管前方", "E": "椎动脉位于颈椎横突孔内"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-107", "kp": "颈部横断面主要结构毗邻", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】A胸锁乳突肌自乳突至胸锁关节，位于颈动脉鞘外前方，正确。B颈动脉鞘内颈内静脉位于颈总动脉前外侧，正确。C甲状腺位于气管前方偏外，较胸锁乳突肌更靠内，正确。E椎动脉由C6以上进入横突孔向上穿行，正确。【为什么错】D食管位于气管后方、椎体前方（气管食管沟内走行喉返神经），说“位于气管前方”位置错误。", "tr": "颈段食管位于气管正后方，“气管前方为甲状腺峡部”而非食管；气管食管沟是喉返神经走行区。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "颈部", "页": 8}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U01-1042", "t": "多选题", "s": "上腹部CT增强扫描，关于下腔静脉、门静脉与腹主动脉的位置关系，正确的描述有", "o": {"A": "下腔静脉位于腹主动脉右侧", "B": "门静脉主干位于下腔静脉前方", "C": "胰头位于十二指肠降部与下腔静脉之间", "D": "腹主动脉位于脊柱前方偏左", "E": "脾静脉于胰头前方汇入门静脉"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-107", "kp": "上腹部大血管位置关系", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A下腔静脉位于腹主动脉右侧，二者均在脊柱前方，正确。B门静脉主干位于下腔静脉前方、胰头后方，正确。C胰头被十二指肠降部与下腔静脉夹持，位于二者之间，是胰头癌“十二指肠降部受压”的解剖基础，正确。D腹主动脉位于脊柱前方偏左，下腔静脉位于其右前方，正确。【为什么错】E脾静脉在胰体尾后方自左向右走行，与肠系膜上静脉在胰颈后方汇合成门静脉主干，说“于胰头前方汇入”位置错误，汇合点在胰颈后方而非胰头前方。", "tr": "门静脉汇合点在胰颈后方（脾静脉+肠系膜上静脉），胰头被十二指肠降部与下腔静脉夹持，这两个“前后”关系是腹部断层高频考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U01-1043a", "t": "共用题干题", "s": "鞍区冠状面MRI上，位于鞍上池内、呈“束带”状连接双侧视神经与视束的结构是", "o": {"A": "垂体柄", "B": "视交叉", "C": "乳头体", "D": "大脑脚", "E": "海马"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-116", "kp": "鞍上池内视交叉识别", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】视交叉位于鞍上池中央偏前，冠状面呈“束带”（蝴蝶形）软组织影，前方为双侧视神经、后方为双侧视束，是与鞍区病变关系最密切的结构，故选B。【为什么错】A垂体柄位于视交叉后方偏下，呈垂直走行的细线状结构，连于垂体上缘。C乳头体位于脚间池，位置更低更靠后。D大脑脚位于中脑腹侧，与鞍上池不在同一平面。E海马位于颞叶内侧、侧脑室下角底壁。", "tr": "冠状面上视交叉（前、束带状）与垂体柄（后、垂直细线）前后关系易混，鞍区手术与病变评估的关键就在二者的识别。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0101", "gs": "患者男性，54岁，因头痛伴双眼视力进行性下降3个月就诊。临床疑诊鞍区占位性病变，拟行颅脑MRI平扫加增强检查，需重点观察鞍区及邻近脑池、垂体与视交叉的关系，为手术入路提供断层解剖依据。"}, {"id": "U01-1043b", "t": "共用题干题", "s": "为清晰显示垂体上缘与视交叉的空间关系，应首选下列哪种成像方案", "o": {"A": "横断面T2WI", "B": "矢状面T1WI", "C": "冠状面薄层扫描（层厚≤3 mm）", "D": "斜轴位扫描", "E": "CT灌注成像"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-117", "kp": "鞍区MRI成像方位选择", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】鞍区病变（垂体瘤）向上生长是否压迫视交叉，须在冠状面观察最佳，因冠状面能同时显示蝶鞍、垂体、鞍上池与视交叉的上下关系，且应薄层扫描（≤3 mm）以减少部分容积效应，故选C。【为什么错】A横断面利于观察鞍旁颈内动脉及鞍上池前后径，但上下关系显示不佳。B矢状面利于显示垂体柄前后走行与蝶鞍前后径，对视交叉受压的上下评估不如冠状面直观。D斜轴位不解决上下毗邻关系的显示问题。E CT灌注成像用于血流灌注评估，与解剖关系显示无关。", "tr": "鞍区评估“横看血管、矢看柄、冠状看交叉”：视交叉受压必须在冠状面评估，这是垂体瘤术前评估的规范。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0101", "gs": ""}, {"id": "U01-1043c", "t": "共用题干题", "s": "若鞍内占位明显向上生长突入鞍上池，最先受压并产生视力障碍的结构是", "o": {"A": "视交叉", "B": "垂体柄", "C": "大脑前动脉", "D": "中脑导水管", "E": "海马"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-118", "kp": "鞍上占位压迫视交叉", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】鞍上池紧邻蝶鞍上方，垂体瘤向上生长首先占据鞍上池，视交叉恰位于鞍上池内、垂体上方，向上生长的肿瘤最先压迫视交叉，引起双颞侧偏盲等视力障碍，故选A。【为什么错】B垂体柄受压可引起内分泌改变（尿崩等），一般不直接产生视力障碍。C大脑前动脉位于视交叉上方较远处，受压较晚且表现为肢体症状而非视力障碍。D中脑导水管位于鞍上池后上方更远处，受压将引起梗阻性脑积水。E海马位于颞叶内侧，远离鞍区。", "tr": "鞍内肿瘤“向上先压视交叉”产生双颞侧偏盲，是鞍区断层解剖的经典应用；视力障碍与垂体柄受压所致内分泌症状需区分。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0101", "gs": ""}, {"id": "U01-1044a", "t": "共用题干题", "s": "右肺门层面增强CT上，位于中间支气管前方、自纵隔跨向肺门的血管结构是", "o": {"A": "右肺动脉（右下肺动脉干）", "B": "食管", "C": "奇静脉", "D": "上腔静脉", "E": "升主动脉"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-108", "kp": "右肺门肺动脉与支气管关系", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】A正确：右肺动脉干（下干）在右肺门处跨过中间支气管前方进入肺门，构成“肺动脉在前、支气管居中”的经典肺门关系；增强扫描其管腔强化明显，与含气低密度的支气管易于鉴别。【为什么错】B食管位于中间支气管正后方，是另一侧的毗邻结构。C奇静脉弓位于纵隔后方，多在主动脉弓层面自后向前汇入上腔静脉。D上腔静脉位于纵隔前部、升主动脉右侧，距中间支气管较远。E升主动脉位于纵隔前部、上腔静脉内侧，不在肺门平面紧邻中间支气管。", "tr": "右肺门“肺动脉在前、支气管居中、食管贴后”的空间关系；左肺门则以左肺动脉位于左主支气管上方为其特点，两侧肺门关系勿互换。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0102", "gs": "患者男性，60岁，体检胸部CT发现右肺门区及纵隔结构显示不清，拟行胸部CT增强扫描，需仔细辨认肺门与纵隔血管、支气管的断层关系，以鉴别血管性结构与肿大淋巴结。"}, {"id": "U01-1044b", "t": "共用题干题", "s": "胸部CT增强扫描中，鉴别纵隔血管断面与肿大淋巴结最可靠的方法是", "o": {"A": "增大窗宽并降低窗位", "B": "连续层面追踪血管走行并观察其强化程度", "C": "加宽扫描层厚", "D": "口服阳性对比剂", "E": "增大扫描螺距"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-106", "kp": "纵隔血管与淋巴结鉴别", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】增强CT上，纵隔血管（肺动脉、肺静脉、上腔静脉等）内腔显著强化，且具有连续走行、逐层延续、管径渐变的特征；肿大淋巴结强化程度低于血管且无连续走行规律。连续层面追踪血管走行并结合其强化程度，是鉴别二者的最可靠方法，故选B。【为什么错】A窗宽窗位调整仅改善显示，不能改变组织本质鉴别。C加宽层厚会加重部分容积效应，使鉴别更困难。D口服对比剂只用于显示消化道，对纵隔血管与淋巴结鉴别无帮助。E增大螺距提高扫描速度，但与结构鉴别无关。", "tr": "血管“走行连续+强化明显”，淋巴结“团块样+轻度强化”；单凭某一层面密度判断易误诊，必须连续追踪层面。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0102", "gs": ""}, {"id": "U01-1045a", "t": "共用题干题", "s": "肝门层面CT增强扫描，肝蒂内三管结构由前向后的排列顺序是", "o": {"A": "门静脉、肝动脉、胆管", "B": "胆管、肝动脉、门静脉", "C": "肝动脉、胆管、门静脉", "D": "门静脉、胆管、肝动脉", "E": "胆管、门静脉、肝动脉"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-108", "kp": "肝门三管排列顺序", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】肝门（肝蒂）横断面上，三管结构由前向后依次为胆管（肝总管/胆总管上段，最前方）、肝动脉（中间）、门静脉（最后方、管径最粗），故选B。【为什么错】A门静脉在最前方错误，门静脉是三者中最粗且位于最后方者。C肝动脉居中最前方应为胆管。D门静脉与胆管位置颠倒。E胆管与门静脉位置颠倒，门静脉应在最后方。", "tr": "肝蒂三管口诀“胆、动、门”（前中后），门静脉最粗最后方；肝门部病变压迫顺序判断依赖此排列。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0103", "gs": "患者女性，50岁，上腹隐痛1个月，超声提示肝门部占位性病变。行上腹部CT增强检查，以明确肝门区结构关系，评估门静脉、肝动脉与胆管是否受压及有无移位。"}, {"id": "U01-1045b", "t": "共用题干题", "s": "若该患者门静脉主干明显增宽且伴脾大，肝门层面最可能出现的断层表现是", "o": {"A": "门静脉主干纤细", "B": "门静脉主干增宽伴脾静脉增宽、脾脏增大", "C": "肝动脉管径消失", "D": "胆总管普遍扩张", "E": "肝静脉明显增宽"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-109", "kp": "门静脉高压断层表现", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】门静脉主干增宽伴脾静脉增宽、脾脏增大，是门静脉高压的典型断层表现；门静脉高压时门静脉压力增高、管径扩张，脾静脉回流入门静脉、随压力增高而增宽，脾脏淤血肿大，故选B。【为什么错】A门静脉纤细提示门静脉发育不良或栓塞后萎缩，与门静脉高压方向相反。C肝动脉在门静脉高压时常代偿性增粗而非消失。D胆总管扩张提示胆道梗阻，与门静脉高压的血管性改变无关。E肝静脉为回流下腔静脉的肝内静脉，门静脉高压时一般不变宽。", "tr": "门静脉高压三联征“门静脉主干增宽+脾静脉增宽+脾大”，与门静脉血栓（管腔内充盈缺损）鉴别是增强扫描的重点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0103", "gs": ""}, {"id": "U01-1046a", "t": "共用题干题", "s": "腰椎横断面MRI上，椎管内位于最前方的结构是", "o": {"A": "硬膜囊", "B": "马尾神经", "C": "硬膜外脂肪", "D": "后纵韧带与椎体后缘", "E": "黄韧带"}, "d": "易", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-103", "kp": "椎管横断面层次", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】腰椎横断面椎管由前向后依次为：椎体后缘与后纵韧带（最前方）、硬膜外脂肪、硬膜囊、硬膜外脂肪、黄韧带与椎弓（最后方）。后纵韧带紧贴椎体后缘，是椎管内最前部结构，故选D。【为什么错】A硬膜囊位于椎管中央，包绕脑脊液与马尾神经，其后有黄韧带。B马尾神经位于硬膜囊内脑脊液中。C硬膜外脂肪分布于硬膜囊与骨性椎管之间（前间隙、后间隙）。E黄韧带位于椎管后外侧、椎弓板前面，是最靠后的结构之一。", "tr": "椎管前后层次“后纵韧带—脂肪—硬膜囊—脂肪—黄韧带”，黄韧带在后、后纵韧带在前，两者位置勿颠倒。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0104", "gs": "患者男性，48岁，腰痛伴右下肢放射麻木2个月。腰椎MRI显示L4/5水平椎间盘突出，需结合椎管与神经根的断层解剖确定受压部位与程度，为治疗方案提供依据。"}, {"id": "U01-1046b", "t": "共用题干题", "s": "L4/5椎间盘向后外侧突出时，最常受压并产生症状的神经根是", "o": {"A": "L4神经根", "B": "L5神经根", "C": "S1神经根", "D": "双侧L4神经根", "E": "马尾神经"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-104", "kp": "椎间盘突出与神经根对应", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】腰椎神经根自同节段椎体上缘水平出椎管后向下斜行，在椎间盘层面神经根已离开该节段。L4/5椎间盘向后外侧突出时，突出物位于L5神经根出椎管的通道（侧隐窝上口）处，压迫的是L5神经根，故选B。【为什么错】A L4神经根在L4/5椎间盘水平已自L4/5椎间孔上方出椎管，位于突出物上方，一般不直接受压。C S1神经根受压多见于L5/S1椎间盘突出。D腰椎间盘突出多为单侧。E马尾神经受压见于巨大中央型突出，与本例侧后方突出不符。", "tr": "椎间盘突出“上一节段压下一根”：L4/5突出压L5神经根，L5/S1突出压S1神经根，根与节段的对应关系是反复命题点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0104", "gs": ""}, {"id": "U01-1047", "t": "案例分析题", "s": "患者男性，65岁，突发剧烈头痛伴喷射性呕吐2小时急诊入院。临床高度怀疑小脑幕旁出血或幕上幕下同时受累的病变，行颅脑CT平扫。技师需确保扫描范围完整覆盖幕上与幕下结构，避免遗漏小脑幕下方（后颅窝）的病变，同时保证小脑幕两侧对称显示。此时最合适的扫描范围设置是", "o": {"A": "以听眦线为基线，自颅顶连续扫描至枕骨大孔下缘，覆盖全颅", "B": "仅扫描幕上结构（自颅顶至鞍上池层面）", "C": "以蝶鞍为中心的小范围局部扫描", "D": "仅以枕骨大孔为中心的下后颅窝薄层扫描", "E": "不设定扫描范围，直接按默认条件扫描"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-119", "kp": "颅脑CT全颅覆盖与小脑幕观察", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】颅脑CT平扫应自颅顶（半卵圆中心上方）连续扫描至枕骨大孔下缘，完整覆盖幕上与幕下结构，才能同时观察小脑幕上方（枕叶、基底节）与下方（小脑、脑干）的病变，故选A。【为什么错】B仅扫描幕上结构会遗漏后颅窝病变，不符合“排除幕下病变”的临床要求。C以蝶鞍为中心的局部扫描范围过小，无法覆盖小脑幕全貌。D仅扫描下后颅窝会遗漏幕上病变，同样不完整。E不设定范围违反扫描规范，无法保证覆盖完整性。", "tr": "颅脑CT“全颅覆盖”（颅顶至枕骨大孔下缘）是排除幕下病变的前提，小脑幕呈“V”形线影在增强或钙化时清晰可见，扫描范围不足是常见遗漏。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1048", "t": "案例分析题", "s": "患者女性，38岁，颈部增粗伴吞咽不适1个月，超声提示甲状腺右叶下极结节，边界尚清。术前拟行颈部CT增强检查，以明确结节与气管、颈动脉鞘及食管的关系。技师需要利用颈部可靠的骨性/软骨性解剖标志在断层图像上对结节所在层面进行精确定位。此时最宜选用的定位标志是", "o": {"A": "环状软骨（作为气管起始的标志）", "B": "甲状软骨上缘", "C": "下颌角水平", "D": "锁骨上窝皮肤皱褶", "E": "胸锁乳突肌前缘"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-108", "kp": "甲状腺结节断层定位", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】环状软骨是唯一完整的软骨环，是气管起始的恒定标志。以环状软骨为基准向下计数气管软骨环，即可精确定位甲状腺下极及结节所在层面（甲状腺峡部位于第2～4气管软骨环前方），故选A。【为什么错】B甲状软骨上缘是颈总动脉分叉和声门区标志，位置高于甲状腺下极。C下颌角平C2～C3，与甲状腺位置相距较远。D锁骨上窝皮肤皱褶因人而异、受体位影响，非恒定骨性标志。E胸锁乳突肌是肌性标志，仅提示外侧边界，不能定位结节层面。", "tr": "环状软骨（气管起始）是颈部分层的“锚点”，向下计数气管环即达甲状腺；把甲状软骨当作定位基准会整体高估层面。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1049", "t": "案例分析题", "s": "患者男性，58岁，痰中带血1周。胸部CT平扫示左肺门区不规则软组织影，与左肺动脉关系密切，需进一步明确病灶与肺门血管、支气管的空间关系。拟行胸部CT增强扫描并行多平面重建。为在重建图像上最直观地显示左肺门病灶与左肺动脉的上下位置关系，并保留支气管管腔的连续性，应优先采用下列哪种重建方式", "o": {"A": "轴位薄层重建", "B": "矢状面MPR", "C": "冠状面MPR", "D": "沿左主支气管长轴的曲面重建（CPR）", "E": "最大密度投影（MIP）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-107", "kp": "左肺门病灶重建方式选择", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】左主支气管及左肺动脉在冠状面上均呈弯曲走行，单纯平面MPR难以将其全长显示于同一平面。沿左主支气管长轴作曲面重建（CPR），可将弯曲走行的支气管及邻近血管展开在同一幅图像上，最直观地显示病灶与左肺动脉的上下毗邻及管腔关系，故选D。【为什么错】A轴位薄层重建虽为诊断基础，但只能显示单层断面，不能直观显示上下空间关系。B矢状面MPR对左肺门前后关系显示尚可，但上下走行关系显示不如CPR。C冠状面MPR可显示上下关系，但因支气管弯曲，全程在同一冠状面内显示困难。E MIP为投影类重建，会重叠遮挡肺门血管与病灶的细节关系。", "tr": "肺门血管与支气管的空间关系首选沿支气管长轴的曲面重建（CPR），普通MPR因结构弯曲而显示不全，MIP有重叠遮挡。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1050", "t": "案例分析题", "s": "患者男性，52岁，体检发现肝右叶占位性病变，拟行肿瘤切除手术。术前增强CT需在横断面上精确判断病灶所属的Couinaud肝段，以决定切除范围并评估切除后剩余肝体积。技师在阅片时，判断病灶位于右前段（Ⅴ、Ⅷ段）还是右后段（Ⅵ、Ⅶ段）所依据的最关键断层标志是", "o": {"A": "肝中静脉走行", "B": "肝右静脉走行", "C": "门静脉左支矢状部", "D": "胆囊窝位置", "E": "下腔静脉断面"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-110", "kp": "肝段定位的静脉标志", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】肝右静脉走行于右叶间裂，是右前段（Ⅴ、Ⅷ段）与右后段（Ⅵ、Ⅶ段）的分界标志。病灶位于肝右静脉平面以前（前方）属右前段，位于其以后（后方）属右后段，故选B。【为什么错】A肝中静脉为左内叶（Ⅳ段）与右前叶（Ⅴ、Ⅷ段）的分界标志，用于区分左右叶而非右前、右后段。C门静脉左支矢状部是左外叶与左内叶的分界标志，位于左半肝。D胆囊窝与下腔静脉连线代表肝中裂（左右半肝分界），用于区分左叶与右叶。E下腔静脉为各肝静脉回流的汇合处，本身不用于段间分界。", "tr": "三条肝静脉各司其职：肝右静脉分右前/右后段，肝中静脉分左内/右前叶，肝左静脉分左外/左内叶；“用肝中静脉分右前右后”是常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1051", "t": "案例分析题", "s": "患者男性，66岁，体检发现血清PSA升高，临床拟行前列腺MRI检查以评估有无前列腺癌及有无包膜侵犯。技师需要选择能清楚区分前列腺外周带与中央带、显示前列腺包膜的成像序列，同时兼顾扫描时间与图像信噪比。此时轴位前列腺成像最恰当的序列选择是", "o": {"A": "轴位T1WI", "B": "轴位高分辨T2WI（小视野、薄层、高矩阵）", "C": "轴位DWI", "D": "矢状位T1WI", "E": "轴位T2*WI"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-105", "kp": "前列腺MRI序列选择", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】前列腺外周带在T2WI上呈高信号、中央带呈低信号，T2WI是显示前列腺分区解剖与包膜的最佳序列；轴位小视野、薄层、高矩阵的T2WI能清晰显示外周带内低信号结节及包膜连续性，故选B。【为什么错】A T1WI上前列腺各带信号差异不明显，主要用于显示出血（T1WI高信号）及淋巴结。C DWI用于功能成像（表观弥散系数），解剖分区显示不如T2WI。D矢状位T1WI对包膜及分区显示不佳，主要用于评估尖部与精囊腺关系。E T2*WI对磁化效应敏感，用于出血与钙化显示，分区解剖显示差。", "tr": "前列腺分区解剖“T2WI看”（外周带高、中央带低）是成像基础；T1WI、DWI是补充序列，不能替代T2WI的分区显示功能。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1052", "t": "案例分析题", "s": "患者男性，35岁，进行性双下肢麻木无力2个月，临床疑诊颈椎管狭窄。行颈椎MRI检查，技师需要在轴位T2WI上测量椎管有效前后径，以定量评估椎管狭窄程度并与正常参考值比较。此时轴位上椎管前后径的标准测量方法是", "o": {"A": "椎体后缘中点至棘突基部前缘的连线", "B": "椎体前缘至椎弓板后缘的连线", "C": "椎间盘后缘至黄韧带的连线", "D": "椎间孔上下径", "E": "侧隐窝左右径"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-105", "kp": "颈椎管前后径测量", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】颈椎管有效前后径（矢状径）的标准测量为椎体后缘中点到棘突基部前缘（椎弓板内面）的连线，反映骨性椎管的有效容纳空间；成人颈椎管前后径小于12 mm即提示狭窄，故选A。【为什么错】B从椎体前缘测量包含了椎体本身，属椎体矢状径而非椎管有效前后径。C椎间盘后缘至黄韧带反映的是椎管前后间隙在椎间盘层面的距离，非骨性椎管径线。D椎间孔上下径是神经根通道的径线，用于评估椎间孔狭窄。E侧隐窝左右径用于评估侧隐窝狭窄，与椎管前后径测量不同。", "tr": "椎管前后径“椎体后缘中点至棘突基部前缘”，测量止点在后部骨结构（椎弓板/棘突基部），起止点记错即得错误径线。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1053", "t": "案例分析题", "s": "患者男性，28岁，运动中扭伤右膝后疼痛伴交锁感1周，临床疑诊内侧半月板撕裂，行膝关节MRI检查。技师需设置斜矢状面序列，使半月板的前后角及体部能连续、完整地显示于同一层面内，同时兼顾前后交叉韧带。此时斜矢状面的定位基线应选择", "o": {"A": "平行于股骨干长轴", "B": "平行于内侧副韧带走行", "C": "平行于前交叉韧带长轴（经股骨内外髁后缘连线）", "D": "垂直于胫骨平台关节面", "E": "平行于髌韧带"}, "d": "易", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-LIMB-104", "kp": "膝关节斜矢状面定位", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】膝关节MRI的斜矢状面扫描基线取平行于前交叉韧带长轴的方向（或经股骨内、外髁后缘的连线），使半月板体部、前后角及前后交叉韧带能连续显示于同一矢状层面，是半月板评估的标准方位，故选C。【为什么错】A平行于股骨干长轴的是常规矢状面，半月板内侧角与外缘不在同一层面连续显示。B内侧副韧带为纵行韧带，与其平行不能兼顾半月板形态。D垂直于胫骨平台为关节面垂直方向，用于胫骨平台骨折评估。E髌韧带位于前方，与其平行不适合半月板显示。", "tr": "半月板及交叉韧带观察需“斜矢状面”（基线平行ACL），常规矢状面（平行股骨长轴）会导致半月板前后角分离显示不全。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1054", "t": "案例分析题", "s": "患者女性，70岁，记忆力减退伴步态不稳半年，临床疑诊正常压力性脑积水或脑白质病变，行颅脑MRI检查。技师需评价脑室系统的大小、形态以及脑室周围白质有无信号改变，并注意与脑脊液信号干扰相鉴别。此时评价脑室周围白质病变的最佳序列组合是", "o": {"A": "轴位T1WI与矢状面T2WI", "B": "轴位T2WI与轴位FLAIR", "C": "轴位DWI", "D": "仅轴位T1WI", "E": "仅三维时间飞跃法MRA"}, "d": "易", "c": "分析", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-120", "kp": "脑室周围白质病变显示序列", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】轴位T2WI显示脑室形态与脑白质信号总体情况，轴位FLAIR通过反转脉冲抑制脑脊液信号，使紧邻脑室壁的白质高信号（PVWMH）不被脑脊液高信号掩盖而清晰显示，二者组合是评估脑室周围白质病变的常规方案，故选B。【为什么错】A T1WI对白质高信号显示不敏感，脑室评估也不以矢状面为主。C DWI用于急性梗死与弥散受限病变，不用于白质高信号常规评估。D仅T1WI无法显示FLAIR所见的脑室旁白质高信号。E MRA用于血管成像，与白质病变评估无关。", "tr": "FLAIR序列“抑制脑脊液、凸显脑室旁白质高信号”是评估PVWMH的关键，漏用FLAIR会把脑室旁病变误判为脑脊液伪影。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-1055", "t": "案例分析题", "s": "患者女性，45岁，产后出现会阴部坠胀不适，临床拟行盆腔MRI评估盆底肌及会阴部结构。技师需在图像上识别肛提肌、闭孔内肌以及肛管两侧脂肪间隙的层次关系，为评估盆底功能障碍提供解剖依据。盆腔内脂肪与骨骼肌的对比是显示盆底肌结构的关键，同时需兼顾扫描时间与呼吸运动的影响。此时显示盆底肌层次结构最适宜的成像方案是", "o": {"A": "轴位T1WI加增强扫描", "B": "轴位高分辨T2WI联合矢状面T2WI薄层扫描", "C": "仅行DWI功能成像", "D": "横断面CT平扫", "E": "三维时间飞跃法MRA"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-107", "kp": "盆底肌MRI成像方案", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】B正确：肛提肌、闭孔内肌等盆底肌为骨骼肌，T2WI上呈均匀中等低信号，与周围脂肪高信号形成良好对比；轴位高分辨T2WI显示盆底肌横断面形态最佳，联合矢状面薄层T2WI可整体评估盆底肌连续性及其与肛管、直肠、尿道的位置关系。【为什么错】A T1WI对肌肉与脂肪的对比不及T2WI，增强扫描非盆底结构评估的常规要求。C DWI反映水分子弥散受限情况，不用于盆底肌形态学显示。D CT软组织分辨率明显低于MRI，对盆底筋膜与肌肉层次显示差，且存在电离辐射。E MRA用于血管成像，与盆底肌显示无关。", "tr": "盆底肌评估首选T2WI（肌肉低信号、脂肪高信号对比佳），CT对软组织层次分辨力不足，仅用于骨盆骨质评估。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-9101", "t": "单选题", "s": "在四肢骨骼的 MRI 断层解剖中，膝关节外侧半月板与内侧半月板形态的主要区别是", "o": {"A": "外侧半月板较小、近似圆形（O 形），内侧半月板较大、呈 C 形", "B": "内侧半月板较小、近似圆形，外侧半月板较大、呈 C 形", "C": "两者形态基本一致，均为 C 形", "D": "外侧半月板前角明显大于后角", "E": "内侧半月板后角明显小于前角"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "KP-BU-1-9101-副高", "kp": "膝关节半月板断层解剖", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (补充)四肢骨骼断层解剖", "ex": "【为什么对】A 正确：外侧半月板因受腓骨小头及腘肌腱的束缚，活动度大、形态较小且近似圆形（O 形）；内侧半月板与关节囊及内侧副韧带结合紧密、活动度小、较大呈 C 形。【为什么错】B 将内外侧形态颠倒；C、D、E 与实际解剖不符。", "tr": "易将内、外侧半月板的形态与大小记反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "补充", "mk": 0}, {"id": "U01-9201", "t": "单选题", "s": "四肢长骨 X 线摄影时，基本要求是", "o": {"A": "至少包括邻近一侧关节", "B": "只照病变局部", "C": "必须双侧对比", "D": "仅正位即可", "E": "无需标注左右"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-9201", "kp": "四肢摄影原则", "ch": "一、人体断面影像解剖 → 7.四肢骨骼", "ex": "【为什么对】四肢长骨摄影至少应包括邻近一侧关节，以明确骨端与位置关系。\n【为什么错】仅照局部易漏诊骨骺病变。", "tr": "长骨摄影包括一端关节。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U01-9202", "t": "单选题", "s": "关于手正斜位摄影，常规投照的手指是", "o": {"A": "第 2～5 指", "B": "仅拇指", "C": "仅小指", "D": "全部六指", "E": "仅食指"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-9202", "kp": "手斜位", "ch": "一、人体断面影像解剖 → 7.四肢骨骼", "ex": "【为什么对】手斜位主要显示第 2～5 掌指及指间关节，拇指单独摄正侧位。\n【为什么错】拇指不做常规斜位。", "tr": "手斜位显示2-5指。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0101", "t": "单选题", "s": "X线由德国物理学家伦琴（W. C. Röntgen）发现的年份是", "o": {"A": "1885年", "B": "1895年", "C": "1896年", "D": "1901年", "E": "1905年"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-001", "kp": "X线的发现", "ch": "二、医学物理基础 → 1.X线的产生 → (1)X线的发现", "ex": "【为什么对】1895年11月8日，德国物理学家伦琴在研究阴极射线管时发现了一种能穿透物质并使荧光屏发光的未知射线，命名为X射线，故选B。【为什么错】A 1885年尚无此发现。C 1896年是X线发现后被迅速应用于临床并在世界范围传播的年份，而非发现年份。D 1901年是伦琴因发现X线获得首届诺贝尔物理学奖的年份，属于获奖时间而非发现时间。E 1905年与X线发现史无关。", "tr": "1895年（发现）与1901年（首届诺贝尔物理学奖）是一对必须区分的年份，命题常以“获奖年”替换“发现年”作干扰。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0102", "t": "多选题", "s": "产生X线所必须具备的基本条件包括", "o": {"A": "能够发射电子的电子源", "B": "使电子高速运动的强电场（高电压）", "C": "阻碍高速电子运动的靶物质", "D": "X线管内保持高度真空", "E": "阳极靶面必须处于高速旋转状态"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-002", "kp": "X线产生的基本条件", "ch": "二、医学物理基础 → 1.X线的产生 → (2)X线的产生", "ex": "【为什么对】A正确：灯丝加热产生热电子发射，提供电子源。B正确：阳极与阴极间施加高电压形成强电场，使电子获得足以产生韧致辐射的动能。C正确：高速电子必须撞击高原子序数、高熔点的靶物质（如钨）而骤然减速，才能把动能转化为X线。D正确：管内高真空可避免电子与气体分子碰撞损失能量、防止灯丝氧化并保证管电流稳定，是X线管正常工作的必要条件。【为什么错】E错误：旋转阳极的作用是把电子轰击的热量分散到整个环形焦点轨迹上，从而提高瞬时负荷能力，属于提高管功率的工程措施；固定阳极X线管（如牙科机、部分移动机）同样能产生X线，故靶面旋转不是产生X线的必要条件。", "tr": "把“提高性能的条件”当成“产生X线的必要条件”是典型误区：旋转阳极、附加滤过、栅控技术都属前者；真正的必要条件只有电子源、加速电场、靶物质与高真空环境。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0103", "t": "单选题", "s": "管电压为100 kV时，连续X线谱的最短波长约为", "o": {"A": "0.0124 nm", "B": "0.124 nm", "C": "1.24 nm", "D": "12.4 nm", "E": "0.00124 nm"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-003", "kp": "连续X线最短波长计算", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】连续X线谱的最短波长对应于电子把全部动能一次性转化为一个光子的极限情况，由杜安－亨特定律给出：λmin(nm)＝1.24／U(kV)。代入U＝100 kV，得λmin＝1.24／100＝0.0124 nm，故选A。【为什么错】B相当于按10 kV计算，数值大10倍。C相当于按1 kV计算，大100倍。D数量级完全偏离，已属紫外线波段。E相当于按1000 kV计算，小10倍。", "tr": "最短波长只由管电压峰值决定，与管电流、曝光时间、靶物质、滤过均无关；增加滤过会提高平均能量却不改变λmin，这是“线质硬化不移动谱线左端”的物理依据。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0104", "t": "单选题", "s": "钨靶X线管产生K系特征X线所需的最低管电压约为", "o": {"A": "30 kV", "B": "50 kV", "C": "70 kV", "D": "100 kV", "E": "120 kV"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-004", "kp": "特征X线产生条件", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】特征X线的产生要求入射电子的动能大于靶原子相应壳层电子的结合能。钨的K层电子结合能约为69.5 keV，故管电压须达到约70 kV以上才能击出K层电子并产生K系特征辐射，选C。【为什么错】A 30 kV时电子动能仅30 keV，远低于钨K层结合能，只能产生L系及以下的低能特征辐射（能量很低，几乎全被管壁与固有滤过吸收）与连续辐射。B 50 kV同样低于阈值。D 100 kV与E 120 kV虽都能产生K系特征X线，但题目问的是“最低管电压”，二者高于阈值，不是答案。", "tr": "特征X线的能量（波长）由靶物质决定，与管电压无关；管电压只决定“能不能产生”以及产生的多少。钼靶（K层约20 keV）在26～32 kV即可产生K系特征X线，这正是乳腺摄影选用钼靶低管电压的原因。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0105", "t": "多选题", "s": "有关影响X线产生的因素，下列描述正确的有", "o": {"A": "管电流决定单位时间内撞击靶面的电子数目，X线量与之成正比", "B": "管电压升高既增加X线量又提高X线质", "C": "靶物质原子序数越高，韧致辐射（连续X线）的产生效率越高", "D": "高压波形纹波越小（如高频、恒压），X线产生效率越高、平均能量越高", "E": "特征X线的波长随管电压升高而变短"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-005", "kp": "影响X线产生的因素", "ch": "二、医学物理基础 → 1.X线的产生 → (4)影响X线产生的因素", "ex": "【为什么对】A正确：管电流由灯丝加热电流控制，决定热电子发射数量，X线光子总数与管电流成正比。B正确：管电压升高使电子动能增大，既提高单个光子的最高能量与平均能量（质），又使韧致辐射效率上升从而增加光子数（量）。C正确：韧致辐射效率η＝k·Z·U，与靶物质原子序数Z成正比，故采用高原子序数的钨（Z＝74）作靶。D正确：纹波小意味着在整个曝光期间管电压都接近峰值，有效能量高、低能成分少，输出效率与平均能量都提高。【为什么错】E错误：特征X线的波长（能量）仅取决于靶物质的壳层能级差，是靶元素的“指纹”，与管电压无关；管电压只影响特征X线能否产生及其强度占比。", "tr": "连续X线的最短波长随kV升高而变短，特征X线的波长却固定不变——命题人常把二者的规律互换。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0106", "t": "单选题", "s": "有关X线管的阳极效应（足跟效应）及其临床利用，下列描述正确的是", "o": {"A": "近阳极端的X线强度明显高于近阴极端", "B": "近阴极端X线强度高于近阳极端，摄影时宜将人体较厚部位置于阴极侧", "C": "靶面倾角越大，阳极效应越明显", "D": "焦点至探测器距离越大，阳极效应越明显", "E": "阳极效应是X线在空气中发生散射所致"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-006", "kp": "阳极效应与空间分布", "ch": "二、医学物理基础 → 1.X线的产生 → (5)X线强度的空间分布", "ex": "【为什么对】X线在靶内一定深度产生后向外射出，射向阳极侧的射线需穿过更厚的靶体自身而被吸收，因而近阳极端强度低、近阴极端强度高，形成沿阳极—阴极轴的强度梯度。临床上应利用这一梯度，把人体较厚、密度较高的部位（如胸椎摄影的下胸段、足部摄影的跟部、乳腺摄影的胸壁侧）置于阴极侧，以获得较均匀的影像密度，故选B。【为什么错】A方向恰好相反。C靶面倾角越小，射线在靶内穿行路径越长，阳极效应越显著；倾角增大则效应减弱。D距离增大时，同样大小的照射野所对应的射线出射角范围变小，落在强度梯度较平缓的中心区域，阳极效应反而减弱。E阳极效应源于靶物质对自身产生X线的吸收（自吸收），与空气散射无关。", "tr": "“厚的一端放阴极”是唯一需要记住的临床结论；乳腺摄影因胸壁侧组织最厚，规定阴极侧朝向胸壁，这是阳极效应最典型的应用实例。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U02-0107", "t": "案例分析题", "s": "患者男性，45岁，身高172 cm，体重100 kg（BMI约34），因腰痛需摄腰椎正侧位。技师在完成正位后，以75 kV、100 mAs、小焦点摄侧位，连续两次曝光效果均偏薄，第三次尝试时设备出现X线管过热保护提示并暂停曝光。已知X线管的产生效率η＝k·Z·U（k≈1.1×10⁻⁹，U以V计），电子动能的绝大部分转化为热能。从X线产生原理出发，下列处理最合理的是", "o": {"A": "改用大焦点并适当提高管电压、相应降低mAs，在维持影像密度的同时减少阳极热负荷", "B": "继续使用小焦点并提高管电流、延长曝光时间以增加输出", "C": "降低管电压至60 kV，同时把mAs提高到200 mAs", "D": "取消附加滤过以提高X线输出效率", "E": "缩短焦点至探测器距离至80 cm，其余条件不变"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-007", "kp": "X线产生效率与阳极热负荷", "ch": "二、医学物理基础 → 1.X线的产生 → (2)X线的产生", "ex": "【为什么对】按η＝k·Z·U，75 kV钨靶的X线产生效率约为1.1×10⁻⁹×74×7.5×10⁴≈0.6%，即99%以上的电子动能转化为阳极热量，这正是过热保护的根源。提高管电压既提高产生效率（η与U成正比）又提高穿透力，可显著减少所需mAs；而阳极热量与kV×mAs×时间因数相关，mAs大幅下降后总热量下降。改用大焦点则把热量分散到更大的实际焦点面积上，提高瞬时负荷能力。因此A是兼顾成像与热负荷的正确策略。【为什么错】B小焦点热容量小，提高管电流、延长曝光只会加剧过热，并增加运动模糊。C降低管电压使效率下降、穿透力不足，为维持密度必须成倍增加mAs，热负荷不降反升，且患者皮肤剂量明显增加。D附加滤过并不产生于阳极之后的热量，取消滤过不会减少阳极负荷，反而使大量低能光子进入人体、显著增加患者剂量，违反防护最优化原则。E缩短距离虽可减少所需曝光量，但会增大皮肤入射剂量并加重几何放大与失真，且腰椎侧位标准距离不宜随意更改。", "tr": "X线管“99%产热、约1%出线”是理解所有热负荷问题的基础；解决过热应优先“升kV降mAs＋换大焦点”，而不是“加大mA拖长时间”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0108", "t": "单选题", "s": "某X线光子的波长为0.02 nm，其光子能量约为", "o": {"A": "12.4 keV", "B": "24.8 keV", "C": "62 keV", "D": "124 keV", "E": "620 keV"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-001", "kp": "光子能量与波长关系", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (1)X线的本质与特性", "ex": "【为什么对】X线本质是电磁波，具有波粒二象性，光子能量E＝hν＝hc／λ。工程上常用简化式E(keV)＝1.24／λ(nm)。代入λ＝0.02 nm，得E＝1.24／0.02＝62 keV，故选C。【为什么错】A相当于λ＝0.1 nm的能量。B相当于λ＝0.05 nm。D相当于λ＝0.01 nm，波长取小了一半。E数量级错误，已属高能γ射线范畴，超出诊断X线范围。", "tr": "E(keV)＝1.24／λ(nm)与λmin(nm)＝1.24／U(kV)形式相同但含义不同：前者是任意单个光子的能量—波长换算，后者是给定管电压下整个连续谱的短波极限，二者不可混用。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0109", "t": "单选题", "s": "诊断X线能量范围内，光子与物质作用后能量不变、仅改变传播方向的相互作用是", "o": {"A": "光电效应", "B": "康普顿效应", "C": "相干散射", "D": "电子对效应", "E": "光核反应"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-002", "kp": "相干散射特点", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】相干散射（又称经典散射、汤姆逊散射或瑞利散射）中，低能光子使束缚电子整体振荡并再发射同频率的电磁波，光子只改变方向而不损失能量，也不产生电离，故选C。【为什么错】A光电效应中光子被完全吸收，能量全部转移给光电子与特征辐射，光子消失。B康普顿效应中光子把部分能量传给反冲电子，散射光子能量降低、波长变长。D电子对效应要求光子能量大于1.02 MeV，光子转化为正负电子对，在诊断能量段不发生。E光核反应阈能通常在8 MeV以上，属放射治疗高能范畴。", "tr": "相干散射虽“无电离、不损失能量”，但它改变了光子方向，仍会形成散射线并降低影像对比度；在诊断能量段其占比不大（一般小于5%），常被误认为“完全无害”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0110", "t": "单选题", "s": "光电效应的发生概率与物质原子序数Z、光子能量E之间的关系是", "o": {"A": "与Z³成正比、与E³成反比", "B": "与Z成正比、与E成反比", "C": "与Z²成正比、与E²成反比", "D": "与Z³成反比、与E³成正比", "E": "与Z、E均无关，只取决于物质密度"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-003", "kp": "光电效应的Z与E依赖性", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】光电效应的质量衰减系数近似满足τ／ρ∝Z³／E³（部分教材写作Z³～Z⁴／E³），即随原子序数迅速上升、随光子能量迅速下降，故选A。这解释了两个临床现象：一是骨（有效Z约13.8）与软组织（有效Z约7.4）在低kV下对比度极高；二是碘（Z＝53）、钡（Z＝56）之所以成为优良对比剂。【为什么错】B、C低估了Z与E的幂次，无法解释对比剂的显著增强效应。D方向完全颠倒，若成立则高能光子在高Z物质中反而更易被光电吸收，与事实相悖。E光电效应对Z与E的依赖极强，密度只影响单位体积内的原子数，不改变每个原子的作用截面。", "tr": "记住“光电吃Z、康普顿吃电子密度”：光电效应∝Z³／E³，康普顿效应与Z基本无关而与每克电子数近似成正比，这一对比是判断“何时提高kV、何时选用对比剂”的物理基础。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0111", "t": "多选题", "s": "有关康普顿效应的性质与临床影响，下列描述正确的有", "o": {"A": "其发生概率与物质每克电子数成正比，与原子序数基本无关", "B": "在诊断X线能量范围内，它是软组织中占主导地位的相互作用形式，且随kV升高而愈发突出", "C": "散射光子的能量小于入射光子，散射角越大能量损失越多", "D": "康普顿散射线是影像灰雾的主要来源，会降低图像对比度并构成机房内散射线防护的主要对象", "E": "康普顿效应的发生概率随光子能量升高而迅速增大"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-004", "kp": "康普顿效应特点与临床意义", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】A正确：康普顿效应作用于外层近似自由的电子，其截面正比于单位质量中的电子数；除氢外多数元素每克电子数相近，故对Z不敏感。B正确：软组织中光子能量超过约26 keV后康普顿即开始占优，诊断段（有效能量约30～70 keV）以康普顿为主，且随kV升高光电占比进一步下降。C正确：由康普顿位移公式Δλ＝(h／m₀c)(1－cosθ)可知，散射角θ越大，波长增加越多、散射光子能量越低；180°反散射时能量损失最大。D正确：康普顿散射线方向随机、能量与原射线接近，是探测器上灰雾与机房内散射线的主要来源，需用滤线栅、限束与屏蔽加以控制。【为什么错】E错误：在诊断能量范围内康普顿效应的发生概率随光子能量升高而缓慢下降，只是因为光电效应下降得更快（∝1／E³），才显得康普顿“相对占比升高”。", "tr": "“康普顿相对占比升高”不等于“康普顿绝对概率升高”——这是绝对量与相对量混淆的经典陷阱；此外散射线量还与照射野面积、被照体厚度密切相关，限束是最经济的散射控制手段。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U02-0112", "t": "案例分析题", "s": "患者女性，48岁，因乳腺筛查行双侧乳腺X线摄影。设备为钼靶／钼滤过数字乳腺机，技师按标准流程选择自动曝光控制，系统给出的管电压为28 kV。该患者随后询问：为什么胸片用110 kV而乳腺只用28 kV。技师需要从X线与物质相互作用的角度作出解释。乳腺摄影采用26～32 kV低管电压的核心物理学依据是", "o": {"A": "低能量段光电效应占主导，其∝Z³／E³的特性可最大化腺体、纤维组织、钙化与病变间的微小衰减差异，从而获得高对比度", "B": "低管电压可显著降低乳腺腺体的吸收剂量", "C": "低管电压可增加康普顿散射比例，从而提高影像对比度", "D": "低管电压可提高X线管的产生效率，缩短曝光时间", "E": "低管电压可减小几何模糊，提高空间分辨率"}, "d": "中", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-005", "kp": "低管电压与光电效应的临床应用", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】乳腺内各种软组织的有效原子序数与密度差异极小，只有让光电效应成为主导相互作用，才能把这些微小差异放大为可见的密度差。由τ∝Z³／E³可知，降低光子能量能使光电效应贡献急剧上升；钼靶在17.5 keV与19.6 keV处的K系特征X线配合钼滤过，可产生集中于该能段的准单能谱，正好兼顾对比度与穿透力，故A正确。【为什么错】B恰恰相反，低管电压使低能光子在浅表被大量吸收，平均腺体剂量升高，这正是乳腺摄影必须严格控制曝光量并采用自动曝光控制的原因。C康普顿散射产生灰雾、降低而非提高对比度，乳腺摄影反而要用滤线栅和压迫来减少散射。D X线产生效率η∝U，管电压越低效率越低，曝光时间反而延长。E几何模糊由焦点尺寸、物—片距与焦—片距决定，与管电压无关。", "tr": "“高对比”与“低剂量”在乳腺摄影中是一对矛盾：低kV提高对比但增加腺体剂量，因此必须依靠压迫（减薄组织）、自动曝光控制与合适的靶／滤过组合（Mo／Mo、Mo／Rh、W／Rh）来平衡，而不能靠单纯降kV。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0113", "t": "多选题", "s": "关于X线与物质各类相互作用的能量条件及其诊断学意义，下列描述正确的有", "o": {"A": "电子对效应的发生阈能为1.02 MeV，故诊断X线能量范围内不会发生", "B": "光电效应无统一的能量下限，但要求入射光子能量不低于相应壳层电子的结合能", "C": "相干散射在诊断能量段所占比例很小，一般不超过5%", "D": "光核反应的阈能一般在8 MeV以上，属放射治疗能量范畴", "E": "康普顿效应主要发生在原子的内层紧束缚电子上"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-006", "kp": "各类相互作用的能量阈值", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】A正确：电子对效应是光子在原子核库仑场中转化为一对正负电子，需至少提供两个电子的静止能量2×0.511 MeV＝1.02 MeV，诊断段最高不过150 keV，故不可能发生。B正确：光电效应要求E光子≥E结合能；当光子能量恰好略高于某壳层结合能时截面骤增，形成“吸收边”（如碘K边33.2 keV）。C正确：相干散射截面随能量升高迅速下降，在诊断段贡献很小。D正确：光核反应需击出核内核子，阈能一般在8 MeV以上，与诊断放射学无关。【为什么错】E错误：康普顿效应发生在外层的松束缚（近似自由）电子上，其前提正是光子能量远大于该电子结合能；若作用于紧束缚内层电子且光子被完全吸收，那是光电效应而非康普顿效应。", "tr": "四种作用按能量从低到高的出场顺序为“相干散射→光电效应→康普顿效应→电子对效应→光核反应”；诊断放射学只涉及前三种，超出此范围的选项属超纲干扰项，应能一眼识别。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0114", "t": "案例分析题", "s": "患者女性，32岁，体重52 kg，因突发胸痛、D-二聚体升高需行肺动脉CTA除外肺栓塞。考虑到患者年轻、需减少辐射与对比剂负荷，技师拟将管电压由常规120 kV降至70 kV，并把碘对比剂用量由60 mL减至40 mL，同时提高管电流并采用迭代重建以控制噪声。该低管电压方案能够在减少碘量的同时维持甚至提高血管强化程度，其核心物理学依据是", "o": {"A": "70 kV时X线束的有效能量更接近碘的K吸收边（33.2 keV），碘的光电吸收显著增强、质量衰减系数增大，单位碘浓度产生的CT值明显升高", "B": "低管电压使康普顿效应占比增加，血管内碘的散射增强", "C": "低管电压使X线管输出量增加，血管信号随之增强", "D": "低管电压使对比剂在血管内的浓度自然升高", "E": "低管电压主要通过减少图像噪声来提高血管的对比噪声比"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-007", "kp": "低管电压CTA与碘K吸收边", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】碘的K层结合能为33.2 keV，光子能量刚超过该值时光电吸收截面骤然跃升。120 kV束的有效能量约55～65 keV，远离K边；降至70 kV后有效能量降至约40～45 keV，更靠近33.2 keV，碘的质量衰减系数显著增大，同样的碘浓度可产生更高的CT值（文献报道70 kV下碘的强化效率较120 kV提高约60%～80%），从而允许减少对比剂用量，故A正确。【为什么错】B康普顿效应与原子序数基本无关，不可能造成碘的选择性强化，且散射只会降低图像质量。C管电压降低时X线输出量按近似U²关系下降而非增加，正因如此才需要成倍提高管电流补偿。D对比剂在血管内的浓度由注射方案与循环决定，与管电压无关。E低管电压在同等mAs下噪声反而增加，本方案需靠提高mAs与迭代重建来抑制噪声；提高对比噪声比的主导因素是分子端的碘强化增益，而非噪声下降。", "tr": "低kV“增强变亮但噪声也变大”，能否获益取决于碘增益是否超过噪声增幅，因此更适用于体型偏瘦者；肥胖患者盲目降kV会因穿透不足导致噪声与伪影急剧恶化。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U02-0115", "t": "单选题", "s": "物理学上X线强度（I）的严格定义是", "o": {"A": "单位时间内通过与射线方向垂直的单位面积上的光子数与各自能量乘积的总和", "B": "单位时间内产生的X线光子总个数", "C": "X线束中能量最高的那个光子所具有的能量", "D": "单位质量物质所吸收的X线能量", "E": "X线束穿透标准铝板后的剩余百分比"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-001", "kp": "X线强度的定义", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (2)X线强度", "ex": "【为什么对】X线强度是能量流密度概念：单位时间内通过垂直于射线传播方向的单位面积上的光子数目与其光子能量乘积的总和，因此它同时包含“量”（光子数）与“质”（单个光子能量）两个要素，故选A。【为什么错】B只描述了光子数量，即X线的“量”，未包含能量因素。C描述的是连续谱的最高光子能量，只与管电压有关，属“质”的一个极端指标。D是吸收剂量的定义（单位质量物质吸收的辐射能量，单位Gy），描述的是受照物质而非射线束本身。E描述的是穿透率／半价层测量的操作过程，属“质”的实用表征方法。", "tr": "X线强度＝光子数×光子能量，所以单靠mAs（改变光子数）或单靠kV（改变光子能量与数目）都能改变强度；把强度等同于“光子数”是最常见的概念性错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0116", "t": "单选题", "s": "其他条件不变时，将管电压由70 kV升高至100 kV，X线输出强度约变为原来的", "o": {"A": "1.4倍", "B": "2倍", "C": "2.8倍", "D": "4倍", "E": "5.6倍"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-002", "kp": "X线强度与管电压的平方关系", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (1)X线的波长与管电压", "ex": "【为什么对】X线强度的经典表达式为I＝K·i·Z·U²，即在管电流、靶物质不变时，输出强度与管电压的平方成正比。(100／70)²＝(1.43)²≈2.04，约为原来的2倍，故选B。【为什么错】A 1.4倍是管电压比值本身（一次方关系），低估了平方效应。C 2.8倍相当于把比值1.43再乘以2，无物理依据。D 4倍相当于管电压翻倍时的平方结果（2²＝4），本题管电压并未翻倍。E 5.6倍数值过大，接近三次方关系(1.43³≈2.9)的两倍，无依据。", "tr": "教材公式给出的是I∝U²，而摄影实践中因滤过与被照体衰减的共同作用，穿过人体到达探测器的剂量随kV的变化常接近三次方甚至更陡，故临床“15%法则”（kV升15%相当于mAs加倍）与理论平方关系并不矛盾，注意区分“管输出”与“探测器接收”两个不同环节。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0117", "t": "多选题", "s": "有关X线管附加滤过板的作用，下列描述正确的有", "o": {"A": "选择性吸收低能光子，使X线束的平均能量升高", "B": "使半价层增大，即提高X线的质", "C": "显著降低受检者的皮肤入射剂量", "D": "使X线束的总输出强度下降", "E": "使被检部位的影像对比度明显提高"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-003", "kp": "滤过对X线质与量的影响", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (3)X线质", "ex": "【为什么对】A正确：低能光子的衰减系数远大于高能光子，铝滤过板优先滤除软射线，使剩余束平均能量升高，即“线质硬化”。B正确：平均能量升高必然使半价层（HVL）增大，这是X线质提高的量化表现。C正确：被滤除的低能光子几乎全部沉积在患者浅表组织而对成像无贡献，滤过是降低皮肤剂量最有效的措施之一，故国家标准对总滤过（一般≥2.5 mm Al当量）有强制要求。D正确：滤过在滤除软射线的同时也会衰减部分有用射线，总输出强度必然下降，需相应增加mAs补偿。【为什么错】E错误：影像对比度主要来源于组织间衰减差异，而低能光子的光电效应贡献最大。滤过提高平均能量后，光电效应占比下降，对比度实际上略有降低。滤过换取的是剂量安全，而不是对比度。", "tr": "“滤过提高线质”与“滤过提高对比度”是两回事——前者正确、后者错误；滤过是以牺牲少量对比度换取患者剂量的大幅下降，属典型的防护最优化权衡。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0118", "t": "多选题", "s": "关于X线的质与量及其影响因素，下列描述正确的有", "o": {"A": "X线的量主要由管电流量（mAs）决定，二者近似成正比", "B": "X线的质主要由管电压与滤过决定，与mAs基本无关", "C": "管电压升高时，X线的质与量同时增加", "D": "半价层是描述X线质的实用物理量，半价层越大表示穿透力越强", "E": "标称管电压峰值相同的两台设备，输出X线的质必定相同"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-004", "kp": "X线质与量的决定因素", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (4)X线量", "ex": "【为什么对】A正确：mAs决定撞击靶面的电子总数，进而决定光子总数，与X线量成正比，这是曝光量互易律的基础。B正确：单个光子能量分布由加速电压与滤过决定，改变mAs只改变光子数目而不改变能谱形状。C正确：管电压升高既提高光子平均能量（质）又提高韧致辐射效率与光子数（量），这正是kV“一石二鸟”的特点。D正确：半价层定义为使X线强度衰减到原来一半所需的标准物质（诊断段常用铝）厚度，HVL越大说明束越硬、穿透力越强。【为什么错】E错误：即便标称kVp相同，两台设备的总滤过量、高压发生器波形（单相、三相、高频）、纹波系数都可能不同，导致有效能量与半价层不同。因此设备验收与质量控制必须实测半价层，而不能仅凭标称kVp判断线质。", "tr": "mAs只管“量”、kV同时管“质和量”、滤过只管“质”（并附带降低量）——三者的分工是本细目的核心；把“kVp相同即线质相同”当作常识是设备质控中的典型误判。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0119", "t": "单选题", "s": "临床摄影中通常用来表示X线量的物理量是", "o": {"A": "管电压kV", "B": "管电流量mAs", "C": "半价层HVL", "D": "波长λ", "E": "照射野面积"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-005", "kp": "X线量的表征", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (4)X线量", "ex": "【为什么对】X线的量指X线束中光子的数目，与管电流和曝光时间的乘积（mAs）成正比，因此临床上直接用mAs表示X线量，故选B。【为什么错】A管电压表征的主要是X线的质，虽然它也影响量，但不是量的直接表征量。C半价层是X线质的标准量化指标。D波长描述单个光子的能量属性，属质的范畴。E照射野面积决定受照体积与散射线量，不表示X线束中的光子数目。", "tr": "“量看mAs、质看kV与HVL”是最简记忆；注意曝光量互易律在数字探测器中基本成立，但在极短或极长曝光时间下可能出现互易律失效，需结合设备特性判断。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0120", "t": "案例分析题", "s": "患者男性，60岁，胸椎压缩性骨折需摄胸椎侧位。技师原用75 kV、40 mAs可获得密度合适的图像，但该患者疼痛明显、屏气困难，曝光时间过长导致呼吸运动模糊。技师决定采用提高管电压、缩短曝光时间的策略，并按摄影条件换算的“15%法则”进行调整，即管电压升高约15%时X线到达探测器的量约增加一倍。若把管电压提高到约86 kV，为维持原有影像密度，mAs应调整为", "o": {"A": "10 mAs", "B": "20 mAs", "C": "30 mAs", "D": "40 mAs", "E": "60 mAs"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-006", "kp": "kV-mAs换算的15%法则", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (1)X线的波长与管电压", "ex": "【为什么对】75 kV提高15%约为86 kV，按15%法则此时到达探测器的曝光量约为原来的2倍，为保持影像密度不变必须把mAs减半，即40 mAs／2＝20 mAs，故选B。这一调整同时把曝光时间缩短一半，有效抑制呼吸运动模糊，并降低患者受照剂量。【为什么错】A 10 mAs相当于减为1／4，对应管电压需再提高约15%（约99 kV），本题只升到86 kV，会造成影像密度不足。C 30 mAs仅减少25%，影像会过黑。D 40 mAs不变则密度明显过高。E 60 mAs反而增加曝光量，与目的相悖。", "tr": "15%法则中“kV升15%≈mAs加倍”，若反向应用（降低kV 15%需把mAs加倍）同样成立；但要注意提高kV会降低影像对比度，对需要高对比的部位（如乳腺、四肢小骨）不宜滥用此法则。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0121", "t": "单选题", "s": "焦点至探测器距离由100 cm增加到150 cm，若其他条件不变，为使探测器接收的剂量保持不变，mAs应", "o": {"A": "减为原来的1／2.25", "B": "增为原来的2.25倍", "C": "增为原来的1.5倍", "D": "减为原来的2／3", "E": "保持不变"}, "d": "易", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-001", "kp": "距离平方反比定律", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (1)距离的衰减", "ex": "【为什么对】点状辐射源在真空或空气中，射线强度与距离的平方成反比：I₁／I₂＝(d₂／d₁)²。距离由100 cm增至150 cm，强度降为原来的(100／150)²＝1／2.25，因此mAs需增加到原来的(150／100)²＝2.25倍才能维持相同的接收剂量，故选B。【为什么错】A方向相反，会导致影像明显欠曝。C 1.5倍只按距离一次方补偿，补偿不足。D减为2／3属反向操作，欠曝更严重。E不作调整则影像密度不足。", "tr": "距离平方反比反映的是几何扩散造成的“距离衰减”，与物质吸收无关；它同时是距离防护的物理基础——工作人员与辐射源距离加倍，受照剂量降为1／4。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0122", "t": "单选题", "s": "某单能窄束X线在某物质中的线性衰减系数μ＝0.35 cm⁻¹，该物质对此射线的半价层约为", "o": {"A": "0.35 cm", "B": "0.69 cm", "C": "1.0 cm", "D": "2.0 cm", "E": "3.5 cm"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-002", "kp": "半价层与线性衰减系数", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (4)衰减系数与影响衰减的因素", "ex": "【为什么对】单能窄束遵循指数衰减规律I＝I₀e^(－μd)。令I／I₀＝1／2，得μ·HVL＝ln2＝0.693，故HVL＝0.693／μ＝0.693／0.35≈1.98 cm，约2.0 cm，选D。【为什么错】A把μ的数值直接当作厚度，属公式误用。B误把ln2＝0.693直接当成半价层，忽略了除以μ。C凑整错误，1.0 cm对应μ≈0.693 cm⁻¹。E 3.5 cm相当于μ≈0.2 cm⁻¹，数值不符。", "tr": "HVL＝0.693／μ与十分之一值层TVL＝2.303／μ是一对常用公式；此外该指数关系严格成立的前提是“单能”和“窄束”，多能宽束条件下必须引入线质硬化与散射累积因子修正。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0123", "t": "多选题", "s": "有关连续能谱X线（多能X线束）在物质中的衰减特点，下列描述正确的有", "o": {"A": "低能光子优先被吸收，透过后线束的平均能量升高，即线质硬化", "B": "随穿透深度增加，第二个半价层大于第一个半价层", "C": "严格的指数衰减规律只适用于单能窄束，多能束并不完全遵循", "D": "线质硬化是CT杯状伪影与条状伪影产生的重要原因", "E": "连续X线经物质衰减后其最短波长随之增大"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-003", "kp": "连续X线的衰减特点", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】A正确：低能光子衰减系数大，先被吸收，剩余束平均能量升高。B正确：束变硬后继续衰减一半所需厚度增大，因此第二半价层大于第一半价层，二者之比称为均质系数，是衡量线束单能性的指标。C正确：I＝I₀e^(－μd)要求μ为常数，而多能束在穿透过程中有效μ不断减小，故偏离单一指数规律。D正确：射束硬化使投影数据与线性假设不符，重建后表现为均匀体模中心CT值偏低的“杯状伪影”，以及两高密度结构之间的暗带条状伪影。【为什么错】E错误：最短波长λmin＝1.24／U仅由管电压决定，滤过或人体吸收只能削减低能端（长波侧）的光子数，不会改变短波极限位置。", "tr": "“衰减使束变硬”不等于“衰减改变最短波长”——能谱是被“削低端”而不是“整体右移”；均质系数（第一HVL／第二HVL）越接近1，说明射线越接近单能。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0124", "t": "单选题", "s": "有关质量衰减系数（μ／ρ），下列描述正确的是", "o": {"A": "同一元素的质量衰减系数随其物理状态（气态、液态、固态）改变而显著改变", "B": "质量衰减系数的单位是cm⁻¹", "C": "对同一元素而言，质量衰减系数与物质密度无关，仅取决于原子序数与光子能量", "D": "质量衰减系数随光子能量升高而单调下降，不存在突变", "E": "质量衰减系数等于线性衰减系数与物质密度的乘积"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-004", "kp": "质量衰减系数的性质", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (4)衰减系数与影响衰减的因素", "ex": "【为什么对】质量衰减系数定义为μ／ρ，其物理意义是单位质量厚度（g/cm²）物质对射线的衰减本领。由于已经除去了密度因素，它只反映原子层面的相互作用截面，因而对同一元素只取决于原子序数与光子能量，与密度和物理状态无关，故选C。这也是水与水蒸气的质量衰减系数相同、而线性衰减系数相差千倍的原因。【为什么错】A物理状态改变的是密度而非原子结构，质量衰减系数保持不变。B cm⁻¹是线性衰减系数μ的单位，质量衰减系数的单位为cm²/g。D在各壳层的吸收边（如碘K边33.2 keV、钡K边37.4 keV）处，质量衰减系数会突然跃升，并非单调下降，这正是K边成像与双能量CT物质分离的物理基础。E关系式为μ／ρ，是商而不是积。", "tr": "“质量衰减系数与密度无关”是本考点的核心结论；同时必须记住吸收边处的不连续跃升，否则会与D这类“看似合理”的干扰项混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U02-0125", "t": "多选题", "s": "影响X线在物质中衰减程度的主要因素包括", "o": {"A": "X线光子的能量（受管电压与滤过共同决定）", "B": "被照物质的原子序数", "C": "被照物质的密度", "D": "被照物质的厚度", "E": "曝光时间（mAs）"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-005", "kp": "影响衰减的因素", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (4)衰减系数与影响衰减的因素", "ex": "【为什么对】A正确：光子能量越高，光电与康普顿截面均下降，穿透力增强、衰减减少。B正确：原子序数通过光电效应（∝Z³）强烈影响衰减，是骨与软组织形成对比的根本原因。C正确：密度决定单位体积内的原子数，线性衰减系数μ＝(μ／ρ)·ρ，密度越大衰减越强，这是肺（低密度）与实变肺组织形成对比的原因。D正确：按指数规律I＝I₀e^(－μd)，厚度d直接进入指数项。【为什么错】E错误：mAs只改变入射光子的总数，不改变每个光子被衰减的概率，因而不影响衰减的百分比。增加mAs会使透过的光子数按比例增加，但透射率I／I₀不变。", "tr": "“衰减程度”指的是透射比例而不是透射的绝对光子数；mAs属于“输入量”，衰减系数属于“系统属性”，把二者混为一谈会导致对曝光条件与图像对比关系的错误理解。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0126", "t": "单选题", "s": "人体主要组织成分对X线衰减能力由强到弱的正确排序是", "o": {"A": "骨＞肌肉（水）＞脂肪＞空气", "B": "骨＞脂肪＞肌肉（水）＞空气", "C": "肌肉（水）＞骨＞脂肪＞空气", "D": "脂肪＞肌肉（水）＞骨＞空气", "E": "空气＞脂肪＞肌肉（水）＞骨"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-006", "kp": "人体组织对X线的衰减", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (5)人体对X线的衰减", "ex": "【为什么对】人体四大基本密度由高到低为骨（含钙，有效原子序数约13.8、密度约1.85 g/cm³）＞软组织／肌肉（近似水，有效Z约7.4，密度约1.0）＞脂肪（有效Z约6.3，密度约0.9）＞空气（密度约0.0013），衰减能力依此递减，故选A。这也是X线平片“四种自然对比”的物理基础，以及CT值标定（水0 HU、空气－1000 HU、致密骨可达＋1000 HU以上）的依据。【为什么错】B把脂肪排在肌肉之前，脂肪的有效原子序数与密度均低于肌肉。C骨的衰减明显强于肌肉，顺序颠倒。D、E顺序完全倒置，与临床影像表现相悖。", "tr": "脂肪的衰减略低于水，故CT上脂肪为负值（约－100～－50 HU）；但在低kV下由于光电效应加强，骨与软组织的对比会进一步拉大，说明“组织对比”并非固定，而与线质相关。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0127", "t": "案例分析题", "s": "患者男性，70岁，因眩晕行颅脑CT平扫。图像显示后颅窝小脑半球区出现两侧颞骨岩部之间的带状低密度以及沿颅骨内板向内的“杯状”密度偏低区，脑实质CT值较正常偏低约8 HU，影响小脑病变判读。设备为64排CT，扫描条件为120 kV、自动管电流调制、层厚5 mm。从X线在物质中的衰减机制分析，该现象的最主要成因及相应技术对策是", "o": {"A": "射束硬化——颅骨优先吸收低能光子使束变硬，导致投影数据偏离线性假设；对策为提高管电压、加用成形（bow-tie）滤过、启用射束硬化校正算法或采用双能量单能谱重建", "B": "部分容积效应——对策为增加层厚以提高信噪比", "C": "患者运动伪影——对策为缩短扫描时间并加固定带", "D": "金属植入物伪影——对策为启用金属伪影抑制算法", "E": "图像噪声过大——对策为单纯提高管电流并加大重建核锐利度"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-007", "kp": "射束硬化伪影的成因与对策", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】CT重建基于“衰减呈单一指数规律”的线性假设。实际使用的是连续能谱束，穿过高密度厚重的颅骨（尤其颞骨岩部与枕骨）后低能成分被大量吸收，射线变硬、有效衰减系数下降，使中心区域投影值系统性偏低，重建后形成中心CT值偏低的“杯状伪影”，两高密度结构之间则出现带状暗影（Hounsfield暗带），这正是本例后颅窝表现的典型成因。对策包括提高管电压使束本身更硬、使用成形滤过预硬化、应用厂家的射束硬化（骨）校正算法，以及采用双能量／能谱CT重建虚拟单能量图像，故A正确。【为什么错】B部分容积效应表现为界面处密度平均化，增加层厚只会加重而非改善，方向错误。C运动伪影表现为条纹状或重影，与“杯状密度分布”不符，且不解释颞骨间的固定带状暗影。D患者无金属植入物，且金属伪影多为放射状粗大条纹伴明显高低密度交替。E噪声表现为颗粒状随机波动，不会造成系统性CT值偏低；加大锐利度反而放大噪声。", "tr": "后颅窝的带状暗影长期被称为“Hounsfield伪影”，与运动、金属伪影形态不同，鉴别要点是它固定出现于两高密度骨结构连线上；此外要理解“提高kV可减轻射束硬化”与“提高kV增加剂量”的权衡关系。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U02-0128", "t": "单选题", "s": "下列原子核中，自旋量子数为零、不具有磁共振特性的是", "o": {"A": "¹H", "B": "¹³C", "C": "¹⁹F", "D": "¹²C", "E": "³¹P"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-001", "kp": "磁性与非磁性原子核判据", "ch": "二、医学物理基础 → 5.磁学基础知识 → (2)磁性和非磁性原子核", "ex": "【为什么对】原子核是否具有自旋磁矩，取决于其质子数与中子数的奇偶性：质子数为奇数或中子数为奇数（即质量数为奇数，或质量数为偶数但质子数与中子数皆为奇数）时，自旋量子数不为零，属磁性核。¹²C含6个质子、6个中子，二者皆为偶数，自旋量子数I＝0，无磁矩、不产生磁共振现象，故选D。【为什么错】A ¹H为单质子，I＝1／2，是人体内丰度最高、旋磁比最大的磁性核，为临床MRI的成像核素。B ¹³C含6质子7中子，中子数为奇数，I＝1／2，是磁性核，可用于超极化¹³C代谢成像。C ¹⁹F含9质子10中子，质子数为奇数，I＝1／2，为磁性核，可用于氟成像与波谱。E ³¹P含15质子16中子，质子数为奇数，I＝1／2，是磁共振波谱研究能量代谢的重要核素。", "tr": "判据是“质子数或中子数为奇数”，而不是“质量数为奇数”——²H（氘，1质子1中子，质量数为偶数）质子与中子皆为奇数，仍是磁性核（I＝1）；¹⁶O、¹²C、³²S这类质子与中子皆为偶数者才是非磁性核。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0129", "t": "多选题", "s": "有关磁性原子核的性质与应用，下列描述正确的有", "o": {"A": "只有质子数或中子数为奇数的原子核才具有自旋磁矩，才能产生磁共振现象", "B": "¹H因人体内丰度最高、旋磁比最大，成为临床MRI的主要成像核素", "C": "¹⁶O与¹²C的质子数、中子数均为偶数，自旋量子数为零，无磁共振现象", "D": "²³Na、³¹P、¹⁹F均属磁性核，可用于磁共振成像或波谱研究", "E": "原子核的磁矩方向与其自旋角动量方向之间没有确定关系"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-002", "kp": "磁性原子核与自旋", "ch": "二、医学物理基础 → 5.磁学基础知识 → (1)自旋和核磁的概念", "ex": "【为什么对】A正确：核内质子与中子均倾向成对且自旋反向抵消，只有存在未配对核子（质子数或中子数为奇数）时才有净自旋与磁矩。B正确：人体约70%为水，氢质子摩尔浓度最高；¹H旋磁比γ／2π＝42.58 MHz/T，在常见核素中最大，两者共同决定了氢质子成像信噪比最高。C正确：¹⁶O（8质子8中子）与¹²C（6质子6中子）皆为偶偶核，I＝0。D正确：²³Na（11质子12中子）、³¹P（15质子16中子）、¹⁹F（9质子10中子）均含奇数质子，是磁性核，已分别用于钠成像、磷谱与氟成像。【为什么错】E错误：核磁矩μ与自旋角动量P之间通过旋磁比γ相联系，μ＝γ·P，二者方向共线（质子的γ为正，磁矩与角动量同向）。正是这一确定关系使Larmor方程ω₀＝γB₀得以成立。", "tr": "旋磁比γ是核的固有常数，决定同一磁场下不同核的共振频率；把“丰度最高”与“旋磁比最大”混为一谈，或误以为任何原子核都能成像，都是常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0130", "t": "单选题", "s": "已知1.5 T磁场中氢质子的Larmor频率约为63.87 MHz。若主磁场提高到3.0 T，其Larmor频率约为", "o": {"A": "31.9 MHz", "B": "63.9 MHz", "C": "95.8 MHz", "D": "127.7 MHz", "E": "255.5 MHz"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-003", "kp": "Larmor方程的定量计算", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】Larmor方程ω₀＝γB₀，用频率表示为f₀＝(γ／2π)·B₀。氢质子的γ／2π＝42.58 MHz/T，故3.0 T时f₀＝42.58×3.0≈127.7 MHz，故选D。也可由比例直接得出：63.87×(3.0／1.5)＝127.74 MHz。【为什么错】A 31.9 MHz对应0.75 T，方向相反。B 63.9 MHz仍为1.5 T的频率，未随场强变化，误认为共振频率与场强无关。C 95.8 MHz对应2.25 T，属按平均值错算。E 255.5 MHz对应6.0 T，把倍数取错。", "tr": "Larmor频率与B₀成严格线性关系，这决定了3.0 T设备的射频波长更短、介电效应与B₁场不均匀更明显，也使比吸收率（SAR）近似随场强平方上升——这些都是高场成像必须面对的连锁效应。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0131", "t": "单选题", "s": "已知³¹P的旋磁比γ／2π＝17.24 MHz/T。在3.0 T MR系统上开展³¹P磁共振波谱检查时，射频发射与接收的中心频率应设置为约", "o": {"A": "51.7 MHz", "B": "60.0 MHz", "C": "127.7 MHz", "D": "17.2 MHz", "E": "42.6 MHz"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-004", "kp": "多核共振频率与旋磁比", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】任何磁性核的共振频率均由f₀＝(γ／2π)·B₀决定。³¹P在3.0 T下的共振频率为17.24×3.0≈51.7 MHz，故射频系统的中心频率须设置在约51.7 MHz，且必须配备相应的³¹P专用（或双调谐）线圈，选A。【为什么错】B 60.0 MHz为任意数值，无对应关系。C 127.7 MHz是同一场强下¹H的共振频率，若误用则完全无法激发磷核。D 17.2 MHz是³¹P在1.0 T下的频率，漏乘场强。E 42.6 MHz是¹H在1.0 T下的频率，属核素与场强双重混淆。", "tr": "不同核在同一磁场中共振频率相差甚远（3.0 T下¹H为127.7 MHz、³¹P为51.7 MHz、²³Na约33.8 MHz），因此多核成像必须使用双调谐或专用线圈，且需单独做频率校准与匀场；直接套用氢质子频率是多核波谱失败的常见原因。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0132", "t": "单选题", "s": "关于热平衡状态下人体组织的宏观纵向磁化矢量M₀，下列描述正确的是", "o": {"A": "M₀随主磁场强度B₀增大而近似线性增大，这是高场MRI信噪比更高的根本原因之一", "B": "M₀的方向与B₀方向相互垂直", "C": "M₀随组织温度升高而增大", "D": "热平衡状态下存在可被接收线圈检出的横向磁化分量", "E": "M₀的大小与组织的质子密度无关"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-005", "kp": "宏观磁化矢量的形成", "ch": "二、医学物理基础 → 5.磁学基础知识 → (1)自旋和核磁的概念", "ex": "【为什么对】置于B₀中的质子按能量分为顺磁场（低能）与逆磁场（高能）两个自旋态，按玻尔兹曼分布低能态略多，其差值形成沿B₀方向的宏观纵向磁化M₀。M₀正比于质子密度与B₀、反比于绝对温度，故场强越高M₀越大、可用信号越强，这是高场MRI信噪比优势的物理根源，选A。【为什么错】B M₀方向与B₀平行同向（沿z轴），不是垂直。C 由居里定律M₀∝1／T，温度升高使能级布居差减小，M₀反而下降；这一原理也是MR测温技术的基础之一。D 平衡态下各质子的进动相位随机分布，横向分量相互抵消，净横向磁化为零，因此必须施加射频脉冲产生相位相干后才有可检测信号。E M₀与单位体积内参与共振的质子数（质子密度）成正比，这正是质子密度加权成像的物理依据。", "tr": "“平衡态无横向磁化”与“纵向磁化不能被直接检测”是理解射频激发必要性的两个关键点：接收线圈只能感应垂直于B₀平面内旋转的磁化分量，故必须先把M₀翻转到横向平面。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0133", "t": "多选题", "s": "有关纵向弛豫（T1）与横向弛豫（T2）在机制上的差异，下列描述正确的有", "o": {"A": "T1弛豫是受激质子把能量传递给周围晶格（分子环境）的过程，存在净能量交换", "B": "T2弛豫源于质子之间的自旋—自旋相互作用导致的相位散失，不涉及向外的净能量传递", "C": "同一组织的T2值总是小于或等于其T1值", "D": "当分子运动频率越接近Larmor频率时，能量传递效率越高、T1值越短，脂肪即属此类", "E": "主磁场强度升高时，组织的T1值缩短而T2值明显延长"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-006", "kp": "T1与T2弛豫机制的本质差异", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】A正确：纵向弛豫又称自旋—晶格弛豫，是高能态质子把吸收的射频能量释放给周围分子（晶格）并返回低能态的过程，伴随实际的能量转移。B正确：横向弛豫又称自旋—自旋弛豫，是相邻质子微观磁场相互干扰造成进动相位逐渐失去相干，宏观横向磁化衰减，系统内部能量重新分配而不向外释放。C正确：横向失相位既受自旋—自旋作用影响，也受纵向恢复的连带影响，理论与实测均满足T2≤T1，纯液体中二者可接近相等。D正确：弛豫效率取决于分子运动频率与Larmor频率的匹配程度；脂肪的中等大小分子其运动频率接近Larmor频率，能量传递高效，故T1最短、T1WI上呈高信号。【为什么错】E错误：场强升高时分子运动频率与更高的Larmor频率匹配变差，能量传递效率下降，组织T1值普遍延长（3.0 T较1.5 T约延长20%～40%）；T2值则轻度缩短或基本不变，绝非“明显延长”。", "tr": "“T1随场强延长、T2基本不变或略缩短”是高场序列参数必须重新优化的根本原因；另需注意T1的长短取决于分子运动频率与Larmor频率的“匹配度”，而不是简单的“分子越大T1越短”——大分子（如蛋白）运动过慢，T1反而长。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U02-0134", "t": "单选题", "s": "关于T2与T2*的区别及其成像意义，下列描述错误的是", "o": {"A": "T2*同时包含自旋—自旋相互作用与主磁场不均匀性两方面的影响", "B": "同一组织的T2*总是小于或等于其T2", "C": "自旋回波序列的180°复相脉冲可补偿静磁场不均匀造成的失相位，所测得的是T2", "D": "梯度回波序列依靠读出梯度反转产生回波，不能补偿静磁场不均匀，所测得的是T2*", "E": "磁敏感加权成像（SWI）与血氧水平依赖成像（BOLD）主要依赖T2缩短效应，与T2*无关"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-007", "kp": "T2与T2*的区别", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】E为错误项，故为本题答案。SWI利用组织间磁化率差异造成的局部磁场不均匀，BOLD则利用脱氧血红蛋白的顺磁性引起的局部场畸变，二者的对比机制本质上都是T2*效应，必须采用梯度回波类序列并使用较长TE才能显现；若改用自旋回波，180°脉冲会把这些磁化率效应“聚焦”掉，对比随之消失。【为什么错】A正确：1／T2*＝1／T2＋1／T2′，其中T2′项由静磁场不均匀（含化学位移与磁化率差异）引起。B正确：由上式可知T2*≤T2，衰减更快。C正确：180°脉冲使因静磁场不均匀而超前或滞后的自旋在回波时刻重新相干，故SE测得的是真正的T2。D正确：梯度反转只能补偿由读出梯度自身引起的失相位，对静磁场不均匀无能为力，因此GRE测得T2*。", "tr": "凡涉及磁化率（出血、铁沉积、钙化、骨小梁、气—组织界面、BOLD）的成像，都要靠T2*而不是T2；相反，若要消除磁化率伪影（如金属植入物附近、颅底），则应选择自旋回波类序列并缩短TE、增大带宽。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0135", "t": "多选题", "s": "有关共振与磁共振现象，下列描述正确的有", "o": {"A": "只有当射频脉冲频率等于该核在当前磁场中的Larmor频率时，才能发生共振并有效吸收能量", "B": "射频脉冲使宏观磁化矢量偏离B₀方向，翻转角由脉冲幅度与作用时间共同决定", "C": "90°脉冲可使纵向磁化完全转变为横向磁化", "D": "射频脉冲停止后，质子通过弛豫释放能量，并在接收线圈中感应出自由感应衰减信号", "E": "磁共振过程中原子核吸收射频能量跃迁至高能态，属于电离辐射作用"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-008", "kp": "磁共振现象的产生条件", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】A正确：共振的本质是能量匹配，射频光子能量须恰好等于两个自旋能级之差，对应频率即Larmor频率；这正是选层梯度配合特定频率射频脉冲能实现选择性激发的原理。B正确：翻转角α＝γ·B₁·t，由射频场幅度B₁与持续时间t共同决定。C正确：90°脉冲把全部纵向磁化翻转到横向平面，此时纵向磁化为零、横向磁化最大。D正确：射频关闭后横向磁化在xy平面进动并逐渐衰减，在接收线圈中感应出按T2*衰减的自由感应衰减（FID）信号。【为什么错】E错误：射频属于非电离辐射，其光子能量在10⁻⁷ eV量级，远低于使物质电离所需的十几电子伏，不能引起电离与化学键断裂。MRI的主要生物学效应是射频致热（以SAR限值管理）、梯度切换致周围神经刺激与噪声，而非电离损伤。", "tr": "把“核跃迁”与“电离”混为一谈是概念性错误；MRI的安全关注点是SAR、dB/dt、噪声、主磁场吸引效应与植入物相容性，与X线的辐射防护体系完全不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0136", "t": "案例分析题", "s": "患者男性，45岁，反复头痛就诊，行颅脑MRI平扫。科室近期由1.5 T升级为3.0 T超导MRI，技师沿用原1.5 T的自旋回波T1加权参数（TR 450 ms、TE 12 ms、层厚5 mm）扫描，结果发现图像整体信噪比虽有提升，但灰质与白质的对比度明显下降，脑室与脑实质的分界不如原1.5 T图像清晰。从核磁弛豫的场强依赖性分析，最恰当的参数调整是", "o": {"A": "适当延长重复时间（如550～700 ms），或改用反转恢复预备的T1加权序列以重建灰白质对比", "B": "进一步缩短重复时间至300 ms以增强T1权重", "C": "延长回波时间至40 ms以增加对比", "D": "把射频翻转角提高到180°", "E": "改用梯度回波T2*加权序列替代T1加权序列"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-009", "kp": "场强对T1弛豫及序列参数的影响", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】主磁场升高使Larmor频率升高，组织分子运动频率与之匹配程度下降，纵向弛豫效率降低，各种脑组织的T1值普遍延长且彼此差值相对压缩。若仍沿用1.5 T的短TR，则灰、白质的纵向磁化在TR末均恢复很少且差异被压缩，对比度自然下降，同时信号强度损失。正确做法是适当延长TR至550～700 ms使两者恢复差异重新拉开，或采用反转恢复预备的T1加权序列（如IR-FSE、MPRAGE／BRAVO／3D-TFE），利用反转脉冲放大T1差异，故A正确。【为什么错】B进一步缩短TR会使两种组织的恢复量都趋近于零，对比与信噪比同时恶化。C延长TE会引入T2权重并降低信号，与T1加权的目的相反。D 180°脉冲会把磁化矢量翻至负纵轴，不产生横向磁化，无法形成常规激发。E改用T2*加权虽然可成像，但完全放弃了T1对比信息，不能解决灰白质T1对比的问题，且3.0 T下磁化率伪影更重。", "tr": "“1.5 T参数直接搬到3.0 T”是升级设备后最常见的技术失误；除TR需要重新优化外，还需注意SAR升高（限制回波链长度与翻转角）、化学位移伪影加倍（需加大带宽）以及介电／驻波效应带来的信号不均匀。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0137", "t": "单选题", "s": "下列电离辐射生物效应中，属于随机性效应的是", "o": {"A": "皮肤红斑", "B": "放射性白内障", "C": "急性放射病", "D": "辐射致癌与可遗传效应", "E": "暂时性不育"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-001", "kp": "确定性效应与随机性效应", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (1)生物效应", "ex": "【为什么对】随机性效应的特点是不存在剂量阈值、发生概率与剂量成正比而严重程度与剂量无关，主要包括辐射致癌与可遗传（遗传）效应，其机制为单个细胞DNA损伤后错误修复而存活并增殖，故选D。【为什么错】A皮肤红斑、B放射性白内障、C急性放射病、E暂时性不育均属确定性效应（组织反应），它们存在明确的剂量阈值，超过阈值后严重程度随剂量增加而加重，机制为大量细胞被杀死导致组织功能丧失。", "tr": "确定性效应“有阈值、比严重程度”，随机性效应“无阈值、比发生概率”；诊断放射学中患者与工作人员的剂量通常远低于确定性效应阈值，防护的主要目标正是把随机性效应的风险降到可合理达到的最低水平，但介入放射学中皮肤确定性效应仍需警惕。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0138", "t": "多选题", "s": "影响电离辐射损伤程度的主要因素包括", "o": {"A": "受照剂量与剂量率，在总剂量相同时剂量率越高损伤越重", "B": "射线的种类与能量，传能线密度越高者相对生物效应越大", "C": "受照部位与受照面积，全身照射较同剂量局部照射后果更严重", "D": "组织细胞的辐射敏感性，分裂旺盛、分化程度低的细胞更敏感", "E": "机体的年龄与生理状态对辐射敏感性没有影响"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-002", "kp": "影响辐射损伤的因素", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (2)影响辐射损伤的因素", "ex": "【为什么对】A正确：剂量率高则单位时间内损伤集中，机体来不及修复，损伤更重；分次小剂量照射因存在亚致死损伤修复而后果较轻。B正确：α粒子、中子等高传能线密度（LET）辐射在单位径迹上电离密集，易造成DNA双链断裂，相对生物效应（RBE）远高于X、γ射线，这正是辐射权重因子取值不同的依据。C正确：全身照射可累及造血、消化等关键系统，同剂量下后果远重于局部照射；受照面积越大后果越重。D正确：Bergonié-Tribondeau定律指出，细胞分裂越旺盛、分化程度越低、代谢越活跃者对辐射越敏感。【为什么错】E错误：年龄与生理状态显著影响辐射敏感性，胎儿与婴幼儿最敏感，儿童高于成人，妊娠期、营养不良、合并疾病或免疫抑制状态时敏感性升高。这正是儿科影像必须严格执行低剂量原则的依据。", "tr": "“分次照射比一次照射损伤轻”是剂量率效应的直接推论，也是放射治疗分次给量的原理；但对随机性效应而言，其风险按累积剂量线性无阈估算，分次并不降低总风险。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0139", "t": "单选题", "s": "按Bergonié-Tribondeau定律，下列组织中对电离辐射最敏感的是", "o": {"A": "肌肉组织", "B": "神经组织", "C": "淋巴组织", "D": "成熟骨组织", "E": "软骨组织"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-003", "kp": "组织辐射敏感性排序", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (1)生物效应", "ex": "【为什么对】辐射敏感性与细胞的增殖能力成正比、与分化程度成反比。高度敏感组织包括淋巴组织、骨髓造血组织、生殖腺（精原细胞）、胃肠道上皮与胚胎组织，其中淋巴细胞即使在间期也极易凋亡，是最敏感的细胞类型之一，外周血淋巴细胞计数下降是急性放射损伤最早的实验室指标，故选C。【为什么错】A肌肉细胞属高度分化、不再分裂，辐射敏感性低。B神经组织（尤其成熟神经元）分化程度最高、几乎不分裂，是敏感性最低的组织之一。D成熟骨组织代谢缓慢，敏感性低；但生长期骨骺软骨敏感性明显高于成熟骨。E成熟软骨敏感性亦低。", "tr": "“生长期”与“成熟期”组织敏感性差别巨大：儿童骨骺、乳腺芽、甲状腺的敏感性远高于成人对应组织，这是儿科防护中屏蔽与限束特别强调的部位。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0140", "t": "案例分析题", "s": "患者女性，28岁，末次月经距今10周（相当于受孕后约8周），因车祸致腹部闭合性损伤送入急诊，血压偏低、腹部压痛明显，临床高度怀疑腹腔内出血需迅速明确诊断。急诊超声因肠气干扰显示不满意。科室配备128层CT与3.0 T MRI，MRI当日排队时间约3小时。关于该患者的检查决策与辐射风险，下列处理最恰当的是", "o": {"A": "受孕后9天至8周为器官形成期、畸形风险相对最高，应先尽力用超声与临床评估；若病情危急且检查确属必需，可在充分告知并优化参数（降低管电压与管电流、严格限束、缩小扫描范围、避免重复期相）后行腹部CT", "B": "妊娠期属CT的绝对禁忌证，任何情况下均不得行腹部CT", "C": "该孕周尚处于“全或无”阶段，胎儿不会发生畸形，可直接按常规剂量完成多期增强CT", "D": "只要在腹部覆盖铅围裙即可完全消除胎儿受照，故无需调整扫描参数", "E": "改用腹部X线平片，其胎儿剂量与腹部CT相当但更为安全"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-004", "kp": "胎儿出生前受照效应与孕期检查决策", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (3)胎儿出生前受照效应", "ex": "【为什么对】胎儿受照效应有明显的时间窗依赖：受孕后0～8天为着床前期，表现为“全或无”（胚胎死亡或完全正常）；9天至8周为器官形成期，畸形风险最高；8～15周中枢神经系统增殖迁移最活跃，智力发育障碍风险最高，16～25周风险次之；整个孕期均存在诱发儿童期恶性肿瘤的随机性风险。本例处于器官形成期末，因此原则是能不照就不照、必须照就把剂量压到最低，同时履行告知义务，这正是正当化与最优化两原则在孕期的具体落实，故A正确。【为什么错】B妊娠并非CT的绝对禁忌，母体生命受威胁时抢救优先；一次腹部CT的胎儿剂量通常在数十mGy以内，远低于100 mGy的公认阈值参考水平。C“全或无”仅适用于受孕后8天以内，本例已超出该阶段，说法错误且会导致不必要的高剂量照射。D胎儿受照主要来自机体内部散射，扫描野内的铅围裙无法阻挡内散射，只能减少体外杂散射，作用有限。E腹部平片虽剂量低于CT，但其诊断腹腔内出血的能力远不足以满足临床需求，不能达到正当化要求；且“剂量与CT相当”的说法不成立。", "tr": "孕期影像决策的两个常见极端都错误：一是“绝对禁止”导致延误抢救，二是“无所谓”导致不必要照射。正确做法是逐例进行正当性判断、优先选择无电离辐射方法、必要时优化参数并记录估算胎儿剂量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0141", "t": "多选题", "s": "关于电离辐射的皮肤效应与外照射慢性放射病，下列描述正确的有", "o": {"A": "皮肤效应属确定性效应，存在剂量阈值，超过阈值后其严重程度随剂量增加而加重", "B": "一次急性照射引起早期一过性红斑的剂量阈值约为2 Gy，暂时性脱毛的阈值约为3 Gy", "C": "介入放射学长时间透视可导致皮肤放射性损伤，应记录并控制患者皮肤入射剂量", "D": "外照射慢性放射病是较长时间内累积接受超过剂量限值照射后引起的全身性疾病，以造血系统改变为主要表现", "E": "皮肤放射性损伤均在受照后24小时内显现"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-005", "kp": "皮肤效应与外照射慢性放射病", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (4)皮肤效应", "ex": "【为什么对】A正确：皮肤损伤由基底层细胞大量死亡引起，属典型的组织反应（确定性效应）。B正确：常用参考阈值为早期一过性红斑约2 Gy、暂时性脱毛约3 Gy、永久性脱毛约7 Gy、干性脱屑约10 Gy、湿性脱屑约15～18 Gy、皮肤坏死约20～25 Gy。C正确：复杂介入手术单次皮肤剂量可达数Gy，国际与国内规范均要求监测参考点空气比释动能与剂量面积乘积，超过警戒值时告知并随访。D正确：外照射慢性放射病以乏力、头晕等神经衰弱症候群与白细胞、血小板减少等造血抑制为主要表现，诊断需结合职业史与个人剂量档案。【为什么错】E错误：皮肤放射性损伤具有明显的潜伏期，早期一过性红斑可在数小时内出现并消退，而主要红斑多在照射后约10天至2周出现，脱毛约2～3周，湿性脱屑与坏死可延迟数周至数月，晚期还可出现萎缩、毛细血管扩张与纤维化。", "tr": "介入术后患者若在数周后出现界限清楚的方形红斑或脱毛，应首先想到放射性皮肤损伤而非皮肤病；“照射当时无异常”绝不能作为排除依据，潜伏期是确定性皮肤效应的重要特征。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0142", "t": "单选题", "s": "在保证获得必要诊断信息的前提下，把受检者所受剂量降低到可合理达到的最低水平（ALARA），体现的放射防护基本原则是", "o": {"A": "实践的正当化", "B": "防护与安全的最优化", "C": "个人剂量限值", "D": "时间防护", "E": "距离防护"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-001", "kp": "放射防护三原则的内涵", "ch": "二、医学物理基础 → 7.X线防护与测量 → (1)放射防护基本原则", "ex": "【为什么对】国际放射防护委员会（ICRP）提出的三项基本原则中，防护与安全的最优化即ALARA原则：在考虑经济与社会因素后，把受照剂量与受照人数保持在可合理达到的尽量低水平。“在满足诊断要求前提下尽量降低剂量”正是该原则的标准表述，故选B。【为什么错】A实践的正当化解决“该不该做这项检查”的问题，即所带来的利益必须大于其可能引起的辐射危害。C个人剂量限值用于限制职业照射与公众照射，明确不适用于患者的医疗照射，因此不能用来解释患者剂量优化。D时间防护与E距离防护属外照射防护的具体技术措施，是最优化原则在操作层面的落实手段，而非基本原则本身。", "tr": "三原则中只有正当化与最优化适用于医疗照射，剂量限值不适用于患者——这是最容易被误答的一点；医疗照射的剂量管理依靠“诊断参考水平”而非“剂量限值”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0143", "t": "多选题", "s": "依据GB 18871—2002《电离辐射防护与辐射源安全基本标准》，关于剂量限值的下列表述，正确的有", "o": {"A": "职业照射的有效剂量限值为连续5年内平均每年20 mSv", "B": "任何单一年份内职业照射的有效剂量不得超过50 mSv", "C": "公众照射的年有效剂量限值为1 mSv", "D": "该标准规定职业照射眼晶状体的年当量剂量限值为150 mSv", "E": "剂量限值同样适用于患者所受的医疗照射"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-002", "kp": "我国放射卫生防护标准的剂量限值", "ch": "二、医学物理基础 → 7.X线防护与测量 → (4)我国放射卫生防护标准", "ex": "【为什么对】A、B正确：GB 18871—2002规定职业人员有效剂量为连续5年平均20 mSv/年（5年总计不超过100 mSv），且任何单一年份不超过50 mSv，二者必须同时满足。C正确：公众成员的年有效剂量限值为1 mSv；特殊情况下如5年平均不超过1 mSv/年，单年可适当提高。D正确：该标准中职业照射的眼晶状体年当量剂量限值为150 mSv，四肢（手和足）或皮肤为500 mSv。【为什么错】E错误：剂量限值仅适用于职业照射与公众照射，不适用于患者的医疗照射。医疗照射通过正当化判断与诊断参考水平进行管理，若对患者设定剂量限值，反而可能因限制必要检查而损害其健康利益。", "tr": "职业照射“5年平均20、单年不超50”是一对必须同时记住的数字，只记一个即被扣分；此外ICRP在2011年建议把眼晶状体职业限值收紧为5年平均20 mSv/年、单年不超50 mSv，与GB 18871—2002的150 mSv不同，答题时应以我国现行标准为准并注意题干指向。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0144", "t": "单选题", "s": "外照射防护的三大基本技术措施是", "o": {"A": "实践正当化、防护最优化、剂量限值", "B": "时间防护、距离防护、屏蔽防护", "C": "个人防护、集体防护、环境防护", "D": "源项控制、途径控制、人员控制", "E": "限束、滤过、滤线栅"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-003", "kp": "外照射防护的一般措施", "ch": "二、医学物理基础 → 7.X线防护与测量 → (2)外照射防护一般措施", "ex": "【为什么对】外照射防护的三大技术措施为时间防护（缩短受照时间，剂量与时间成正比）、距离防护（增大与源的距离，剂量按距离平方反比下降）和屏蔽防护（在人与源之间设置铅、混凝土等屏蔽体使射线按指数规律衰减），故选B。【为什么错】A是放射防护的三项基本原则，属管理与决策层面，不是具体技术措施。C为按防护对象所作的分类描述，非标准三措施。D属放射性污染控制的思路，主要针对内照射与开放型放射源。E限束、滤过、滤线栅是X线摄影中改善图像质量与降低剂量的具体技术手段，可归入最优化措施，但不是外照射防护的三大基本措施。", "tr": "“三原则”与“三措施”是本细目最高频的混淆点：原则回答“该不该做、做到什么程度、不得超过多少”，措施回答“具体怎么做”；答题时先看题干问的是“基本原则”还是“防护措施”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0145", "t": "单选题", "s": "某防护材料对特定能量X线的半价层为0.25 mm铅当量。若要把透过的辐射剂量率降至原来的1／16，所需屏蔽层厚度至少为", "o": {"A": "0.25 mm铅当量", "B": "0.5 mm铅当量", "C": "1.0 mm铅当量", "D": "2.0 mm铅当量", "E": "4.0 mm铅当量"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-004", "kp": "屏蔽厚度的半价层计算", "ch": "二、医学物理基础 → 7.X线防护与测量 → (3)外照射屏蔽防护", "ex": "【为什么对】每增加一个半价层，透射剂量率减半。1／16＝(1／2)⁴，需要4个半价层，故所需厚度＝4×0.25 mm＝1.0 mm铅当量，选C。【为什么错】A仅1个半价层，透射率为1／2。B为2个半价层，透射率1／4。D为8个半价层，透射率1／256，虽满足要求但远超“至少”所需，不符合题意。E为16个半价层，屏蔽严重过度，既不经济也无必要。", "tr": "半价层法计算屏蔽的前提是射线束线质在穿透过程中基本稳定；实际防护设计中射束硬化会使后续半价层逐渐增大，因此规范中的屏蔽厚度还需考虑宽束条件下的散射累积因子与工作负荷、居留因子、利用因子，不能仅凭半价层数简单外推。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-0146", "t": "多选题", "s": "有关辐射剂量学中的各量及其单位，下列描述正确的有", "o": {"A": "照射量的SI单位为库仑每千克（C/kg），专用单位为伦琴（R），1 R＝2.58×10⁻⁴ C/kg", "B": "吸收剂量的SI单位为戈瑞（Gy），1 Gy＝1 J/kg", "C": "当量剂量等于吸收剂量与辐射权重因子之积，SI单位为希沃特（Sv）", "D": "有效剂量等于各器官或组织的当量剂量按组织权重因子加权求和，SI单位为希沃特（Sv）", "E": "照射量适用于任何介质中任何类型的电离辐射"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-005", "kp": "照射量、吸收剂量与防护量", "ch": "二、医学物理基础 → 7.X线防护与测量 → (5)照射量测量", "ex": "【为什么对】A正确：照射量以X、γ射线在空气中产生的电离电荷量定义，SI单位C/kg，专用单位伦琴，换算关系为1 R＝2.58×10⁻⁴ C/kg。B正确：吸收剂量D＝dε／dm，SI单位Gy，1 Gy＝1 J/kg，适用于任何介质与任何辐射类型。C正确：当量剂量HT＝Σ wR·DT,R，X、γ射线与电子的辐射权重因子为1，α粒子为20，单位Sv。D正确：有效剂量E＝Σ wT·HT，用于评价全身随机性效应风险，单位Sv。【为什么错】E错误：照射量的定义严格限定于空气介质中的X射线与γ射线，且能量范围有限（一般在数十keV至约3 MeV），不适用于α、β、中子等其他辐射，也不适用于空气以外的介质，这正是国际上逐步用空气比释动能取代照射量的原因。", "tr": "常用换算关系为1 R在空气中约相当于8.76 mGy的空气吸收剂量，在软组织中约9.5 mGy，切勿把“1 R≈1 Gy”当成近似成立；此外Gy与Sv虽量纲相同（J/kg），但物理含义不同，不能互换使用。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-0147", "t": "案例分析题", "s": "某导管室为患者男性、68岁行冠状动脉介入治疗，预计透视时间较长。技师需在机房内协助操作台旁工作，全程不能离开床边。机房配备铅橡胶围裙、甲状腺护领、铅眼镜、床侧铅帘与悬吊式铅屏，C形臂可在床上或床下放置X线管，透视模式可选连续透视与脉冲透视（3、7.5、15帧/s可调）。为把工作人员职业受照降至可合理达到的最低水平，下列措施组合最恰当的是", "o": {"A": "穿0.35 mm铅当量以上铅衣并配戴甲状腺护领与铅眼镜，充分使用床侧铅帘与悬吊铅屏，X线管置于检查床下方，尽量站在探测器一侧并远离球管，采用低帧率脉冲透视并缩短累计透视时间，同时规范佩戴个人剂量计", "B": "只需穿铅衣，不必使用甲状腺护领与铅屏，通过提高透视帧率缩短总操作时间来降低剂量", "C": "尽量站在X线管一侧，因为散射线主要沿原射线方向朝探测器传播", "D": "正位透视时将X线管置于检查床上方，可减少术者受照", "E": "用连续透视替代脉冲透视，图像更连贯且总剂量更低"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-006", "kp": "介入放射学的职业防护措施", "ch": "二、医学物理基础 → 7.X线防护与测量 → (2)外照射防护一般措施", "ex": "【为什么对】介入操作中工作人员受照几乎全部来自患者体内产生的散射线，其强度以患者被照射体积为中心向各方向发散，且以射线入射侧（球管侧）最强。A项完整体现了三大防护措施：屏蔽（铅衣、护领、铅眼镜、床侧铅帘与悬吊铅屏，其中铅眼镜针对晶状体这一敏感器官）、距离（站在探测器侧、尽量远离球管）、时间（低帧率脉冲透视、缩短累计透视时间）；把X线管置于床下可使强散射区集中在术者下肢并被床侧铅帘阻挡，而非直接照射躯干与头颈部；规范佩戴个人剂量计则满足职业照射监测要求，故A正确。【为什么错】B甲状腺与晶状体是介入人员的重点防护部位，省略护领与铅屏会显著增加受照；提高帧率会成倍增加剂量率，不能靠“更快完成”抵消。C散射线在患者体内产生后向各方向发射，其中背向散射（朝向球管侧）强度最高，站在球管一侧受照最重，说法完全颠倒。D球管置于床上方时，患者入射侧朝上，强散射区正对术者头颈与晶状体，是应当避免的错误摆位。E脉冲透视通过降低单位时间曝光次数显著减少剂量，同帧率下连续透视剂量明显更高，说法与事实相反。", "tr": "“球管在下、探测器在上”“人在探测器侧”是介入防护的两条铁律；此外个人剂量计的规范佩戴方式为躯干铅衣内佩戴一枚用于评价有效剂量，必要时在铅衣外衣领处再佩戴一枚以估算头颈部与晶状体剂量，二者不可相互替代。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1001", "t": "单选题", "s": "伦琴将1895年发现的未知射线命名为X射线，其含义是", "o": {"A": "取发现者伦琴姓氏的首字母", "B": "数学中常用X代表未知数，表示“未知射线”", "C": "表示射线按X级能量分类", "D": "表示射线波长的计量单位", "E": "表示辐射剂量等级"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-101", "kp": "X线命名的含义", "ch": "二、医学物理基础 → 1.X线的产生 → (1)X线的发现", "ex": "【为什么对】伦琴发现该射线时对其本质尚不清楚，因数学中常用字母X表示未知数，故命名为X射线，以示“未知射线”，故选B。【为什么错】A X射线的命名并非取姓氏首字母（伦琴Röntgen的R未被使用）。C X线不以“X级”能量分类命名。D X线的波长单位为纳米（nm），与X字母无关。E辐射剂量等级另有专有单位，与命名无关。", "tr": "X（未知）而非X级、X单位，命名的本质是“未知”含义，常与伦琴获奖年份等史实混淆命题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1002", "t": "单选题", "s": "固定阳极X线管中，高速电子轰击阳极靶面时，其动能绝大部分转化为", "o": {"A": "特征X线能", "B": "连续X线能", "C": "热能", "D": "荧光能", "E": "二次电子动能"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-102", "kp": "X线产生中的能量转化", "ch": "二、医学物理基础 → 1.X线的产生 → (2)X线的产生", "ex": "【为什么对】高速电子轰击阳极靶面时，其动能绝大部分（99%以上）转化为热能，仅有不足1%转化为X线能，因此阳极需要良好的散热结构，故选C。【为什么错】A特征X线能只占X线总能量的小部分（约10%～20%的X线输出）。B连续X线（韧致辐射）占X线输出的大部分，但两者合计仍不足电子动能的1%。D荧光是X线作用于荧光物质时产生的次级可见光，与阳极过程无关。E二次电子数量少、能量低，非主要能量转化去向。", "tr": "电子动能的99%以上转化为热、不足1%转化为X线，这是旋转阳极与散热设计（热容量）的物理基础。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1003", "t": "单选题", "s": "连续X线（韧致辐射）产生的物理机制是", "o": {"A": "外层电子跃迁至内层电子空位", "B": "高速电子受原子核库仑场作用急剧减速，部分动能以光子形式辐射", "C": "原子核放射性衰变释放光子", "D": "正负电子对湮灭产生光子", "E": "电子从金属表面逸出形成光电流"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-103", "kp": "连续X线产生机制", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】高速电子接近原子核时，受核库仑电场强烈吸引而急剧减速，损失的功能以电磁辐射（光子）形式释放，即为韧致辐射（连续X线），故选B。【为什么错】A外层电子跃迁至内层空位产生的是特征X线，能量固定、为线状谱。C放射性核素衰变释放的γ射线属核过程，与X线产生机制无关。D正负电子对湮灭产生511 keV光子对，发生在高能γ辐射领域。E光电效应中的光电子是电子发射，不产生X线。", "tr": "连续X线=韧致辐射（电子减速）；特征X线=电子跃迁；两种谱的机制与能谱形态（连续谱vs线状谱）是核心区分点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1004", "t": "单选题", "s": "管电压为120 kV时，连续X线谱的最短波长约为", "o": {"A": "0.0050 nm", "B": "0.0103 nm", "C": "0.0200 nm", "D": "0.1030 nm", "E": "0.1240 nm"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-104", "kp": "连续X线最短波长计算", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】根据公式λ_min（nm）=1.24/U（kV），当U=120 kV时，λ_min=1.24/120≈0.0103 nm，故选B。【为什么错】A 0.0050 nm对应约248 kV，明显偏低。C 0.0200 nm对应约62 kV，与120 kV不符。D 0.1030 nm对应约12 kV，为软X线能量。E 0.1240 nm为1 kV能量对应的换算常数（1.24 nm），不是结果。", "tr": "公式λ_min(nm)=1.24/U(kV)，注意单位是纳米而非埃（若用埃为单位则λ_min=12.4/U Å），系数混用是最常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1005", "t": "单选题", "s": "钨靶X线管产生K系特征X线的具体过程是", "o": {"A": "高速电子将K壳层电子击出，L壳层电子跃迁填充K壳层空位并释放特征光子", "B": "K壳层电子自发逃逸", "C": "外层电子被加速后逸出原子", "D": "原子核捕获外层电子", "E": "正负电子对湮灭后释放光子"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-105", "kp": "K系特征X线产生过程", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】当高速电子的能量足以将靶原子K壳层电子击出形成空位时，L（或M等）壳层电子跃迁至K壳层空位，释放的能量差即为K系特征X线光子，故选A。【为什么错】B K壳层电子被击出需要外来高速电子提供能量，不会自发逃逸。C外层电子被加速逸出是韧致辐射过程中的次级过程，不产生特征X线。D原子核捕获电子属核过程，与特征X线无关。E电子对湮灭发生在高能领域，与靶物质特征X线无关。", "tr": "特征X线光子能量=跃迁壳层能级差，取决于靶物质原子序数；产生前提是管电压超过K壳层激发电位（钨约69.5 kV）。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1006", "t": "单选题", "s": "其他条件不变，增大X线管电流时，X线输出量的变化正确的是", "o": {"A": "X线质与量均增大", "B": "X线量增大，X线质不变", "C": "X线质增大，X线量不变", "D": "X线质与量均不变", "E": "连续谱最短波长变短"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-106", "kp": "管电流对X线量影响", "ch": "二、医学物理基础 → 1.X线的产生 → (4)影响X线产生的因素", "ex": "【为什么对】增大管电流使单位时间轰击靶面的电子数增多，X线光子数（X线量）随之成正比增大；但每个光子的能量由管电压决定，故X线质（硬度、能谱分布）不变，故选B。【为什么错】A“质均增大”错误，质由管电压决定。C“质增大、量不变”方向完全颠倒。D“均不变”与X线量随管电流增大的事实不符。E最短波长由管电压决定（λ_min=1.24/U），与管电流无关，管电流不影响。", "tr": "管电流影响X线“量”（光子数），管电压影响X线“质”（能谱/硬度）同时也影响量（平方关系），二者作用维度不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1007", "t": "单选题", "s": "利用阳极效应（足跟效应）拍摄人体长骨全长摄影时，正确的摆位原则是", "o": {"A": "将长骨较薄部位置于阴极侧", "B": "将长骨较厚部位置于阴极侧（X线强度较大侧）", "C": "将管球阳极侧对准长骨中部", "D": "一律利用阳极侧强束", "E": "使长骨长轴垂直于X线束中心线"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-107", "kp": "阳极效应的临床利用", "ch": "二、医学物理基础 → 1.X线的产生 → (5)X线强度的空间分布", "ex": "【为什么对】阳极效应（足跟效应）使沿X线管长轴方向上阴极侧X线强度大于阳极侧。拍摄长骨全长时，将较厚（衰减大）的部位置于阴极侧、较薄部位置于阳极侧，可使胶片两端受照量趋于均匀，故选B。【为什么错】A把厚部放阳极侧会使厚部曝光不足、薄部过度曝光，与补偿目的相反。C管球阳极侧为弱束区，对准中部不能均衡两端。D一味利用阳极侧会加剧两端受照不均。E长骨长轴应与X线束长轴方向一致（平行）放置以利用强度梯度，垂直放置不能利用足跟效应。", "tr": "足跟效应“阴极侧强度大”，厚部放阴极、薄部放阳极；方向记反即落入陷阱，同时注意长骨长轴需与球管长轴方向平行。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1008", "t": "单选题", "s": "关于X线的本质，正确的是", "o": {"A": "X线是带负电的高速粒子流", "B": "X线是波长很短的电磁波，具有波粒二象性", "C": "X线是一种超声波", "D": "X线是光电子与反冲电子的混合流", "E": "X线本质是机械波，需介质传播"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-101", "kp": "X线的本质", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (1)X线的本质与特性", "ex": "【为什么对】X线是波长很短的电磁波，同时具有波动性（干涉、衍射）与粒子性（光子），即波粒二象性，在真空与空气中均以光速传播，故选B。【为什么错】A电子流才是带负电的粒子流，X线光子不带电。C超声波是机械波，频率低、不能穿透人体厚组织。D光电子与反冲电子是X线与物质作用的次级产物，不是X线本身。E机械波需要介质传播，而X线可在真空中传播，属电磁波。", "tr": "X线=电磁波（波粒二象性、真空可传播），与超声（机械波、需介质）本质不同，“X线是粒子流”是常见陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1009", "t": "单选题", "s": "X线照射荧光物质（如钨酸钙）时使其发出可见光，这一特性称为", "o": {"A": "穿透作用", "B": "荧光作用", "C": "电离作用", "D": "感光作用", "E": "生物效应"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-102", "kp": "X线的荧光作用", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (1)X线的本质与特性", "ex": "【为什么对】X线能使钨酸钙、硫氧化钆等荧光物质产生可见荧光，此即荧光作用，是透视检查和增感屏成像的基础，故选B。【为什么错】A穿透作用是X线穿透不同密度物质的能力，是摄影成像的基础。C电离作用使物质产生正负离子，是剂量测量与放射损伤的基础。D感光作用是X线使胶片银盐感光形成潜影，是胶片摄影的基础。E生物效应是X线对机体的损伤作用，用于放射防护与治疗。", "tr": "X线四大效应“穿透、荧光、电离、感光”对应不同应用：透视用荧光、摄影用感光、测剂量用电离，一一对应是常考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1010", "t": "单选题", "s": "在诊断用X线能量范围内，光电效应发生的概率与光子能量的关系约呈", "o": {"A": "与光子能量成正比", "B": "与光子能量平方成正比", "C": "与光子能量的三次方成反比", "D": "与光子能量无关", "E": "与光子能量平方成反比"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-103", "kp": "光电效应的能量依赖", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】在诊断X线能量范围内，光电效应的发生概率与物质原子序数Z的3～4次方成正比，与光子能量的3次方成反比（约∝1/E³），即低能光子、高原子序数物质中光电效应更易发生，故选C。【为什么错】A、B光电效应概率随能量升高而降低，与能量正比或平方正比均与物理规律相反。D光电效应强烈依赖能量，“无关”错误。E平方反比不准确，应为三次方反比。", "tr": "光电效应“∝Z³～Z⁴、∝1/E³”两个依赖关系是命题核心，三次方反比与平方反比、Z与E的依赖方向是易错点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1011", "t": "单选题", "s": "能量为100 keV的X线光子与软组织（近似水）相互作用时，占主导地位的作用过程是", "o": {"A": "相干散射", "B": "光电效应", "C": "康普顿散射", "D": "电子对效应", "E": "光核反应"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-104", "kp": "诊断能量范围主要作用形式", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】软组织（水）的有效原子序数低（约7.4），在30 keV以上能量区间康普顿散射即占优势；100 keV时光电效应已很弱（∝1/E³），康普顿散射占主导，故选C。【为什么错】A相干散射仅占极小份额，且主要见于极低能区。B光电效应在低能（<30 keV）与高原子序数物质中占优，100 keV软组织中比例很低。D电子对效应需光子能量≥1.02 MeV，100 keV远达不到。E光核反应阈值更高（约数MeV以上），诊断能量下不可能发生。", "tr": "软组织在诊断能量范围以康普顿散射为主；骨因含钙（Z高）在低能时光电效应占比明显高于软组织，两者组织差异是考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U02-1012", "t": "单选题", "s": "电子对效应（电子偶效应）发生所需的光子能量阈值为", "o": {"A": "0.511 keV", "B": "1.02 keV", "C": "1.02 MeV", "D": "10 MeV", "E": "100 MeV"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-105", "kp": "电子对效应能量阈值", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】电子对效应中，光子能量必须大于正负电子对的静质量能之和，即2×0.511 MeV≈1.022 MeV，故阈值约1.02 MeV，故选C。【为什么错】A 0.511 MeV是电子静质量能，仅为阈值的一半。B 1.02 keV数值太小（差三个数量级），阈值以MeV计。D、E 10 MeV与100 MeV远高于实际阈值，不属于阈值描述。", "tr": "电子对效应阈值1.02 MeV意味着诊断X线能量（<150 keV）下绝不可能发生电子对效应，该效应的Z²依赖只对高能辐射有意义。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1013", "t": "单选题", "s": "康普顿散射中，入射光子与原子外层电子作用后发生的变化是", "o": {"A": "光子能量不变，仅改变传播方向", "B": "光子将部分能量传递给电子（反冲电子），自身能量降低且方向改变", "C": "光子被原子完全吸收", "D": "光子能量增大后继续传播", "E": "产生正负电子对"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-106", "kp": "康普顿散射过程", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】康普顿散射中，入射光子与原子外层（结合能很低的轨道）电子发生非弹性碰撞，光子将部分能量传给电子使其脱离原子成为反冲电子，自身能量降低、波长变长并改变方向，即散射光子，故选B。【为什么错】A能量不变仅方向改变是相干（弹性）散射的特征，康普顿散射为非弹性。C光子被完全吸收是光电效应的特征，康普顿散射中光子以散射光子形式继续存在。D光子能量只减不增。E正负电子对由电子对效应产生，需≥1.02 MeV能量，与康普顿散射无关。", "tr": "康普顿散射“能量降低+方向改变+产生反冲电子”与相干散射“能量不变+仅方向改变”的区分是相互作用考点的核心。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1014", "t": "单选题", "s": "其他条件不变，将管电流由50 mA增至100 mA、管电压由80 kV增至100 kV时，X线强度约增大为原来的", "o": {"A": "2倍", "B": "4倍", "C": "3.1倍", "D": "8倍", "E": "16倍"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-108", "kp": "X线强度与管参数关系计算", "ch": "二、医学物理基础 → 1.X线的产生 → (4)影响X线产生的因素", "ex": "【为什么对】X线强度与管电流成正比、与管电压的平方成正比。管电流增大为原来的100/50=2倍；管电压增大引起的强度增加为（100/80）²=1.5625倍；总强度变化为2×1.5625≈3.1倍，故选C。【为什么错】A 2倍只考虑了管电流的变化。B 4倍为（2）²的错误组合或误将管电压当作一次方。D 8倍是2×2²再乘以2的重复计算。E 16倍是对各因素过度乘方。", "tr": "强度公式“I∝mA·U²”：管电流一次方、管电压二次方，需分别计算后相乘，漏乘或错乘次数即出错。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1015", "t": "单选题", "s": "表示X线质（硬度）最常用的物理量是", "o": {"A": "管电流（mA）", "B": "照射野面积", "C": "半价层（HVL）", "D": "毫安秒（mAs）", "E": "焦点标称值"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQUAL-101", "kp": "X线质的表示", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (3)X线质", "ex": "【为什么对】X线质表示X线的硬度，即穿透能力，通常用半价层（HVL）表示，也可用管电压、滤过及有效能量间接表示，故选C。【为什么错】A管电流大小决定X线量，不直接表示硬度。B照射野面积是投照技术参数，与X线质无关。D mAs表示X线量（曝光量）。E焦点标称值反映X线管焦点成像性能，与X线质无关。", "tr": "X线“质=半价层/硬度”、“量=mAs”，质与量的表示物理量是高频考点，二者不可互换。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1016", "t": "单选题", "s": "X线源至探测器距离由100 cm增至200 cm，其他条件不变时，探测器处照射量变为原来的", "o": {"A": "1/2", "B": "1/4", "C": "1/8", "D": "1/16", "E": "不变"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-101", "kp": "距离平方反比定律", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (1)距离的衰减", "ex": "【为什么对】对点源而言，照射量与距离的平方成反比（平方反比定律）。距离由100 cm增至200 cm，变为原来的2倍，则照射量变为原来的1/2²=1/4，故选B。【为什么错】A 1/2是距离比值的倒数，未按平方计算。C 1/8无物理依据。D 1/16按4倍距离或更高次方错误计算。E“不变”与平方反比规律明显矛盾。", "tr": "平方反比定律“剂量∝1/d²”：距离加倍剂量减为1/4，防护理“远距离操作”即基于此定律。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1017", "t": "单选题", "s": "使入射X线强度衰减为原来一半所需的吸收物质厚度称为", "o": {"A": "十分之一价层", "B": "半价层（HVL）", "C": "质量衰减系数", "D": "线性衰减系数", "E": "有效原子序数"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-102", "kp": "半价层定义", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (2)物质吸收的衰减", "ex": "【为什么对】半价层（HVL）是指使入射X线强度衰减至原来一半时所需吸收体的厚度，是表示X线穿透力（质）的重要参数，故选B。【为什么错】A十分之一价层是使强度衰减至1/10所需的厚度，数值大于半价层。C质量衰减系数是μ/ρ，反映单位质量物质的衰减能力。D线性衰减系数μ是单位厚度物质对X线的衰减率。E有效原子序数是反映化合物等效原子序数的参数，与厚度无关。", "tr": "半价层（HVL，衰减一半）与十分之一价层（TVL，衰减到1/10）的数值关系HVL≈0.3×TVL，防护屏蔽计算中极易混用。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1018", "t": "单选题", "s": "某X线束在铅中的半价层为0.25 mm，穿过1.0 mm铅板后，X线强度约为原来的", "o": {"A": "1/4", "B": "1/8", "C": "1/16", "D": "1/32", "E": "1/64"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-103", "kp": "半价层衰减计算", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (2)物质吸收的衰减", "ex": "【为什么对】每经过一个半价层厚度，X线强度衰减为原来的一半。铅板厚度1.0 mm含半价层个数为1.0/0.25=4个，透过的强度为原来的（1/2）⁴=1/16，故选C。【为什么错】A 1/4对应2个半价层（0.5 mm）。B 1/8对应3个半价层（0.75 mm）。D 1/32对应5个半价层（1.25 mm）。E 1/64对应6个半价层（1.5 mm）。", "tr": "衰减计算“I=I₀/2ⁿ，n=厚度/半价层”，先求半价层个数再作2的幂次，顺序与单位换算是易错点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1019", "t": "单选题", "s": "人体各主要组织成分对X线衰减能力由强到弱的正确顺序是", "o": {"A": "骨＞脂肪＞肌肉＞气体", "B": "骨＞肌肉＞脂肪＞气体", "C": "肌肉＞骨＞脂肪＞气体", "D": "脂肪＞肌肉＞骨＞气体", "E": "气体＞脂肪＞肌肉＞骨"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-104", "kp": "人体组织对X线的衰减顺序", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (5)人体对X线的衰减", "ex": "【为什么对】X线在物质中的衰减主要取决于物质的有效原子序数、密度与厚度。骨骼含钙（原子序数高）且密度大，衰减最强；肌肉密度略高于脂肪；气体密度最低、衰减最弱，故顺序为骨＞肌肉＞脂肪＞气体，故选B。【为什么错】A脂肪在肌肉之前错误，肌肉有效原子序数与密度均略高于脂肪。C骨应排第一而非第二。D脂肪大于骨错误。E气体衰减最弱应排最后。", "tr": "衰减顺序“骨＞肌肉＞脂肪＞气体”与CT值顺序一致（骨最高、气体最低），记忆顺序时勿将脂肪与肌肉位置颠倒。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1020", "t": "单选题", "s": "MRI成像中最常用、含量最丰富的磁性原子核是", "o": {"A": "¹²C", "B": "¹⁶O", "C": "¹H（氢质子）", "D": "²³Na", "E": "³¹P"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-101", "kp": "MRI常用磁性原子核", "ch": "二、医学物理基础 → 5.磁学基础知识 → (2)磁性和非磁性原子核", "ex": "【为什么对】氢原子核（¹H）自旋量子数为1/2、在人体内含量最丰富（水、脂肪等）、旋磁比高，产生的MR信号最强，是MRI成像的主力原子核，故选C。【为什么错】A ¹²C质量数和原子序数均为偶数，自旋量子数为零，属非磁性核。B ¹⁶O同理为非磁性核。D ²³Na虽有磁性，但含量低、信号弱。E ³¹P虽有磁性，但灵敏度低于¹H，仅用于特殊研究。", "tr": "磁性原子核判据是自旋量子数≠0（质量数为奇数的核多为磁性核）；¹²C、¹⁶O是典型的非磁性核，与¹H形成对比考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1021", "t": "单选题", "s": "在静磁场中，对氢质子施加频率等于拉莫尔频率的90°射频脉冲后，宏观纵向磁化矢量发生的变化是", "o": {"A": "增大为原来的两倍", "B": "减小为零，同时产生横向磁化分量", "C": "保持不变", "D": "反向翻转180°", "E": "消失且不产生横向磁化"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-102", "kp": "90°射频脉冲作用", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】当射频脉冲频率与质子进动频率（拉莫尔频率）相同时发生共振，90°脉冲使宏观纵向磁化矢量整体翻转90°、纵向分量降为零，同时各质子相位趋于一致形成横向磁化分量，故选B。【为什么错】A射频脉冲不增加纵向磁化大小。C磁化矢量被明显扰动，不会保持不变。D反向翻转180°是180°反转脉冲的作用，90°脉冲只翻转90°。E90°脉冲必然产生横向磁化分量，否则无法接收MR信号。", "tr": "90°脉冲（纵向归零、产生横向磁化）与180°反转脉冲（纵向反转）的作用方向不同，序列设计中二者常交替使用。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1022", "t": "单选题", "s": "纵向弛豫（T1弛豫）的准确定义是", "o": {"A": "横向磁化衰减至37%所需的时间", "B": "纵向磁化恢复至其平衡值63%所需的时间", "C": "纵向磁化完全恢复所需的时间", "D": "质子相位重聚所需的时间", "E": "质子进动一周所需的时间"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-103", "kp": "T1弛豫定义", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】90°脉冲后纵向磁化从零按指数规律恢复，其时间常数T1定义为纵向磁化恢复到平衡值63%（即1-e⁻¹≈63%）所需的时间，又称自旋-晶格弛豫时间，故选B。【为什么错】A横向磁化衰减至37%是T2的定义。C完全恢复需约5倍T1，定义用63%而非完全恢复。D相位重聚与自旋回波技术相关，非T1定义。E质子进动周期与拉莫尔频率相关，与弛豫无关。", "tr": "T1（纵向恢复63%）与T2（横向衰减37%）两个百分比是经典易混点，“恢复63%/衰减37%”必须成对记忆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1023", "t": "单选题", "s": "横向弛豫（T2弛豫）的物理本质是", "o": {"A": "质子将能量传递给周围晶格", "B": "质子间相位失相干（自旋-自旋相互作用）导致横向磁化指数衰减", "C": "质子进动频率加快", "D": "纵向磁化重新恢复", "E": "磁场不均匀导致的质子频率离散"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-104", "kp": "T2弛豫本质", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】90°脉冲后横向磁化因质子间局部磁场差异导致的相位失相干（自旋-自旋相互作用）而按指数规律衰减，其时间常数即T2，故选B。【为什么错】A将能量传递给周围晶格是T1（自旋-晶格）弛豫的机制。C进动频率由旋磁比与磁场强度决定，与弛豫过程无关。D纵向磁化恢复是T1弛豫过程。E磁场不均匀导致的是T2*衰减（含T2与磁场不均匀性），不是T2的本质，且T2*≤T2。", "tr": "T2=自旋-自旋（相位失相干），T1=自旋-晶格（能量释放）；T2*再叠加磁场不均匀性，三者的层级关系（T2*≤T2）是难点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1024", "t": "单选题", "s": "在T1WI上，组织T1时间越长，其信号强度的变化规律是", "o": {"A": "信号越低", "B": "信号越高", "C": "信号不变", "D": "与T1时间无关", "E": "信号先升高后降低"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-105", "kp": "T1WI信号与T1时间关系", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】T1WI通过短TR、短TE突出组织间T1差异。TR一定时，T1长的组织在给定TR内纵向磁化恢复少，信号低；T1短的组织恢复快，信号高。即“长T1→低信号”，故选A。【为什么错】B“T1越长信号越高”与T1WI规律相反。C信号强度明确依赖T1差异。D T1WI就是利用T1差异成像，不能无关。E信号随T1单调变化，无先升后降。", "tr": "T1WI“长T1低信号、短T1高信号”（如脑脊液低信号、脂肪高信号）；T2WI则“长T2高信号”，两个权重的信号方向相反，最易混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1025", "t": "单选题", "s": "将吸收剂量换算为当量剂量时所乘的、反映辐射类型生物效应大小的因子是", "o": {"A": "组织权重因子", "B": "辐射权重因子（WR）", "C": "剂量率因子", "D": "照射时间因子", "E": "能量吸收因子"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-RADB-101", "kp": "辐射权重因子", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (1)生物效应", "ex": "【为什么对】当量剂量H=吸收剂量D×辐射权重因子WR，WR反映不同辐射类型（X、γ、α、中子等）的相对生物效应强弱，故选B。【为什么错】A组织权重因子用于由当量剂量计算有效剂量（E=ΣHT×WT），反映不同组织器官的辐射敏感性。C剂量率因子不是标准剂量学概念。D照射时间因子属防护时间概念的延伸，不是换算因子。E能量吸收因子非规范术语。", "tr": "辐射权重因子WR（射线类型）与组织权重因子WT（器官敏感性）分别在当量剂量、有效剂量的计算中使用，两个“权重因子”最易混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1026", "t": "单选题", "s": "国际单位制中，当量剂量与有效剂量的单位是", "o": {"A": "戈瑞（Gy）", "B": "希沃特（Sv）", "C": "伦琴（R）", "D": "库仑每千克（C/kg）", "E": "焦耳（J）"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-101", "kp": "当量剂量单位", "ch": "二、医学物理基础 → 7.X线防护与测量 → (6)吸收剂量测量", "ex": "【为什么对】当量剂量与有效剂量的国际单位均为希沃特（Sv），1 Sv=1 J/kg（经权重因子修正），故选B。【为什么错】A戈瑞（Gy）是吸收剂量的单位，1 Gy=1 J/kg，未经辐射权重修正。C伦琴（R）是照射量的旧专用单位。D库仑每千克（C/kg）是照射量的国际单位。E焦耳是能量单位，不是剂量单位。", "tr": "剂量单位三件套：吸收剂量Gy、当量/有效剂量Sv、照射量C/kg（旧单位R），“Gy与Sv混用”是常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1027", "t": "单选题", "s": "防护材料“铅当量”的物理含义是", "o": {"A": "材料的密度大小", "B": "与该材料厚度具有相同屏蔽效果所需的铅厚度（以mmPb表示）", "C": "材料的实际物理厚度", "D": "材料的原子序数", "E": "材料的导电率"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-102", "kp": "铅当量概念", "ch": "二、医学物理基础 → 7.X线防护与测量 → (3)外照射屏蔽防护", "ex": "【为什么对】铅当量是指某防护材料在一定条件下对X（γ）射线的屏蔽能力相当于一定厚度铅的屏蔽能力，用等效铅厚度（mmPb）表示，如1 mm铅当量即与该厚度材料的屏蔽效果等价于1 mm铅，故选B。【为什么错】A密度仅是影响屏蔽的因素之一，不等于铅当量。C实际物理厚度不等于等效屏蔽厚度，不同材料所需厚度不同。D原子序数影响衰减能力，但不直接等于铅当量。E导电率与辐射屏蔽无关。", "tr": "铅当量是“等效屏蔽厚度”而非实际厚度：同等屏蔽效果下，混凝土、钡砖的物理厚度远大于铅，铅当量统一了屏蔽能力的度量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-1028", "t": "多选题", "s": "关于X线的物理特性及其临床应用的对应关系，正确的描述有", "o": {"A": "穿透作用—X线摄影成像的基础", "B": "荧光作用—透视检查的基础", "C": "电离作用—辐射剂量测量的基础", "D": "感光作用—胶片摄影的基础", "E": "X线无生物效应，对人体组织无损伤作用"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-107", "kp": "X线特性与应用", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (1)X线的本质与特性", "ex": "【为什么对】A穿透作用是X线穿过不同密度物质的能力，是摄影成像的基础，正确。B荧光作用使荧光物质发光，是透视的基础，正确。C电离作用使物质电离，是电离室等剂量测量的基础，正确。D感光作用使胶片银盐感光形成潜影，是胶片摄影的基础，正确。【为什么错】E X线具有明确的生物效应，可引起细胞损伤、突变甚至致癌，既是放疗工具也是防护对象，说“无生物效应”错误。", "tr": "X线四大效应“穿透、荧光、电离、感光”各有应用对应，生物效应是防护与放疗的基础，“X线无生物效应”是常识性陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1029", "t": "多选题", "s": "关于连续X线能谱特征的描述，正确的有", "o": {"A": "具有明确的最短波长（λmin）", "B": "波长在λmin以上呈连续分布", "C": "强度最大的波长约为最短波长的2倍", "D": "连续X线由韧致辐射（轫致辐射）产生", "E": "提高管电压可使谱峰向短波方向移动"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-109", "kp": "连续X线能谱特征", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】A连续谱存在由管电压决定的最短波长λmin=1.24/U（kV）nm，正确。B短于λmin的波长不存在，λmin以上波长连续分布，正确。D连续X线由高速电子韧致辐射产生，正确。E提高管电压使λmin缩短、谱峰及平均能量移向短波（硬）方向，正确。【为什么错】C连续谱中强度最大处的波长约为最短波长的1.5倍（约1.5λmin），而不是2倍，错误。", "tr": "连续谱“强度峰≈1.5λmin”与“最短波长λmin”是两个不同参数，倍率记忆错误是最常见陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1030", "t": "多选题", "s": "关于特征X线的描述，正确的有", "o": {"A": "特征X线的波长取决于靶物质的原子序数", "B": "管电压必须超过相应壳层的激发电压才能产生", "C": "特征X线的能量与管电流大小无关", "D": "特征X线在总X线输出中所占比例较小", "E": "特征X线波长随管电压升高而变短"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-110", "kp": "特征X线特点", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】A特征X线光子能量等于跃迁壳层间能级差，能级差取决于靶物质原子序数（越高则能级差越大、波长越短），正确。B需管电压超过该壳层激发电压才能击出该壳层电子，正确。C特征X线能量与管电流无关（管电流只影响产生数量），正确。D常规钨靶X线管中特征X线仅占输出的小部分（诊断能量范围内），正确。【为什么错】E特征X线波长由靶物质能级差决定，是固定线系谱，与管电压无关；管电压升高只改变连续谱及能否激发更高壳层，错误。", "tr": "特征X线“波长固定、由靶物质决定”，管电压只决定能否产生（阈值），这是“特征X线随管电压变化”类陷阱的考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1031", "t": "多选题", "s": "关于X线强度的空间分布（阳极效应），正确的描述有", "o": {"A": "沿X线管长轴方向，阴极侧X线强度大于阳极侧", "B": "垂直于靶面方向的X线强度最大", "C": "阳极效应在管电压较高时更加明显", "D": "阳极效应在管电压较低时更加明显", "E": "可把受检体较厚部位置于阴极侧以利用强度梯度"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-111", "kp": "X线强度空间分布", "ch": "二、医学物理基础 → 1.X线的产生 → (5)X线强度的空间分布", "ex": "【为什么对】A阳极效应（足跟效应）使阴极侧射线经靶面自吸收较少、强度大于阳极侧，正确。B垂直于靶面方向的射线穿透靶层最薄、强度最大，正确。D管电压低时X线质软、靶面自吸收相对更显著，阳极效应更明显，正确。E利用阴极侧强束补偿厚部、阳极侧弱束照顾薄部，可改善照片两端密度均匀性，正确。【为什么错】C管电压较高时X线变硬、靶面自吸收减弱，阳极效应反而不明显，说“高kV时更明显”错误。", "tr": "阳极效应“低kV更明显”（软线自吸收强）与“阴极侧强度大”是两个独立考点，方向或条件记反即错。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1032", "t": "多选题", "s": "影响X线质（硬度）的主要因素包括", "o": {"A": "管电压", "B": "滤过", "C": "阳极靶物质原子序数", "D": "管电流", "E": "高压波形（脉动程度）"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQUAL-102", "kp": "X线质的影响因素", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (3)X线质", "ex": "【为什么对】A管电压越高，X线光子能量越高、质越硬，正确。B滤过（尤其附加滤过）吸收低能软线、使平均能量升高、质变硬，正确。C靶物质原子序数影响特征X线能量与连续谱强度分布，进而影响质，正确。E高压波形脉动大则X线质软，恒压（三相或高频）输出时质较硬，正确。【为什么错】D管电流只决定X线量（光子数），不改变光子能量谱，不影响X线质，错误。", "tr": "“管电流只管量、管电压管质”：凡将管电流列入影响X线质的选项均为错误项，这是质与量考点的经典陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1033", "t": "多选题", "s": "关于X线在物质中的衰减规律，正确的描述有", "o": {"A": "窄束（准直）X线衰减遵循指数规律I=I₀e⁻⁽μx⁾", "B": "宽束X线含大量散射线，衰减不严格遵循指数规律", "C": "半价层与线性衰减系数关系为HVL=0.693/μ", "D": "质量衰减系数μ/ρ与物质密度大小无关", "E": "气体对X线的衰减能力大于骨骼"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-105", "kp": "X线衰减基本规律", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (2)物质吸收的衰减", "ex": "【为什么对】A窄束单能X线的衰减符合指数定律I=I₀e⁻⁽μx⁾，正确。B宽束X线因散射线混入，实测衰减偏离指数规律（较指数衰减慢），正确。C由I=I₀e⁻⁽μx⁾令I=I₀/2可得HVL=ln2/μ≈0.693/μ，正确。D质量衰减系数μ/ρ为线性衰减系数除以密度，与物质密度无关、仅与能量和原子序数相关，正确。【为什么错】E气体密度极低、衰减最弱，骨骼含钙、密度高、衰减最强，顺序应为骨＞肌肉＞脂肪＞气体，说“气体衰减大于骨”错误。", "tr": "窄束指数衰减与宽束含散射线偏离指数规律、质量衰减系数与密度无关，三个概念是衰减规律的核心，气体与骨的衰减顺序勿颠倒。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1034", "t": "多选题", "s": "关于连续X线在人体内衰减及其影像学影响的描述，正确的有", "o": {"A": "低能光子优先被吸收，射线在深部逐渐“变硬”（射束硬化）", "B": "射束硬化可产生CT的杯状（cupping）伪影", "C": "人体对X线的衰减取决于有效原子序数、密度与厚度", "D": "乳腺X线摄影采用低kV以增强光电效应、提高软组织对比", "E": "提高管电压可明显提高骨与软组织的对比度"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-106", "kp": "连续X线衰减特点与应用", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】A多能X线穿过物质时低能部分先被吸收，剩余射线平均能量升高即“变硬”，正确。B射束硬化使中心区光子能量高于边缘，产生CT的杯状伪影（中心CT值偏低），正确。C衰减强度与物质有效原子序数、密度、厚度密切相关，正确。D低kV时光电效应占比增大，而光电效应突出原子序数差异，可提高乳腺（脂肪-腺体）软组织对比，正确。【为什么错】E提高管电压使X线质变硬、光电效应减少、康普顿散射为主，骨与软组织间的对比度反而下降，说“明显提高骨软组织对比”错误。", "tr": "kV越高对比越低（硬线、康普顿为主），kV越低越利于软组织和骨对比（光电效应突出），这一“反向关系”是摄影能量选择的依据。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U02-1035", "t": "多选题", "s": "关于磁性与非磁性原子核的条件及MR信号，正确的描述有", "o": {"A": "自旋量子数不为零的原子核具有磁性", "B": "质量数为奇数的原子核多为磁性核", "C": "质量数和原子序数均为偶数的原子核自旋量子数为零", "D": "原子核带正电荷且自旋时产生磁矩", "E": "只有氢原子核能产生MR信号"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-106", "kp": "磁性原子核条件", "ch": "二、医学物理基础 → 5.磁学基础知识 → (2)磁性和非磁性原子核", "ex": "【为什么对】A原子核的自旋量子数I≠0时具有自旋磁矩，为磁性核，正确。B质量数为奇数的原子核I为半整数（1/2、3/2等），多为磁性核，正确。C质量数、原子序数均为偶数时I=0、为非磁性核，正确。D质子带正电荷，原子核自旋产生环形电流从而具有磁矩，正确。【为什么错】E除氢外，³¹P、²³Na、¹³C等磁性核同样能产生MR信号，只是灵敏度低、临床少用，说“只有氢核能产生”错误。", "tr": "磁性核判据“质量数奇数→有磁性、质量数+原子序数均偶→无磁性”；“只有¹H能成像”是绝对化陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1036", "t": "多选题", "s": "关于质子进动与拉莫尔频率，正确的描述有", "o": {"A": "质子进动（旋进）频率与主磁场强度成正比", "B": "拉莫尔方程ω₀=γB₀中的γ为旋磁比", "C": "1.5 T场强下氢质子的拉莫尔频率约63.9 MHz", "D": "3.0 T场强下氢质子的拉莫尔频率约127.8 MHz", "E": "拉莫尔频率随射频脉冲能量的增大而升高"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-107", "kp": "拉莫尔频率定量关系", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】A质子进动频率正比于主磁场强度，是MR成像的基本关系，正确。B拉莫尔方程ω₀=γB₀中γ为旋磁比，氢质子γ/2π≈42.58 MHz/T，正确。C 42.58×1.5≈63.9 MHz，正确。D 42.58×3.0≈127.8 MHz，正确。【为什么错】E拉莫尔频率仅由旋磁比与主磁场强度决定，射频脉冲只能通过共振条件（频率匹配）激发质子，不能改变进动频率，错误。", "tr": "氢质子旋磁比42.58 MHz/T要记牢：场强1.5 T对应约64 MHz、3.0 T对应约128 MHz，计算与射频频率设定直接相关。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1037", "t": "多选题", "s": "关于人体各组织弛豫时间（T1、T2）及其成像信号特点，正确的描述有", "o": {"A": "同一组织的T2时间一般小于或等于T1时间", "B": "脂肪的T1较短，在T1WI上呈高信号", "C": "脑脊液T1长、T2长，在T2WI上呈高信号", "D": "组织含水增多时T1与T2一般均延长", "E": "所有组织的T1与T2时间均相等"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-108", "kp": "组织弛豫时间比较", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】A横向弛豫一般快于纵向弛豫，故T2≤T1，正确。B脂肪分子运动适中、T1短，T1WI呈高信号，正确。C脑脊液含水量高，T1长、T2长，T2WI呈高信号，正确。D含水量增多使质子环境更接近自由水，T1、T2均延长（如水肿），正确。【为什么错】E不同组织T1、T2差异很大，正是这些差异构成MRI组织对比的基础，“所有组织相等”错误。", "tr": "“T2≤T1”与“含水多T1T2均延长”是弛豫规律的常考点；不同组织弛豫时间的差异本身就是成像对比的来源。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1038", "t": "多选题", "s": "关于电离辐射的确定性效应（组织反应），正确的描述有", "o": {"A": "存在剂量阈值", "B": "效应的严重程度随剂量增大而加重", "C": "效应的发生概率随剂量增大而增大", "D": "皮肤红斑、放射性白内障属于确定性效应", "E": "低于阈值的剂量不会产生该效应"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-RADB-102", "kp": "确定性效应特征", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (1)生物效应", "ex": "【为什么对】A确定性效应存在剂量阈值，低于阈值不发生，正确。B剂量超过阈值后，效应严重程度随剂量增大而加重（如皮肤损伤程度），正确。D皮肤红斑、脱发、放射性白内障、造血抑制等均属确定性效应，正确。E阈值以下不发生该效应，是确定性效应的基本特征，正确。【为什么错】C“发生概率随剂量增大而增大”是随机性效应（致癌、遗传效应）的特征，确定性效应的特征是严重程度随剂量加重而非发生概率增大，错误。", "tr": "确定性效应“有阈值、重程度”，随机性效应“无阈值、增概率”，二者的核心区别（阈值与剂量关系）是反复命题点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U02-1039", "t": "多选题", "s": "根据国家标准GB 18871—2002，我国放射工作人员与公众剂量限值的正确描述有", "o": {"A": "放射工作人员连续5年的年平均有效剂量不超过20 mSv", "B": "放射工作人员任何单一年份的有效剂量不超过50 mSv", "C": "放射工作人员眼晶体的年当量剂量限值为150 mSv", "D": "公众个人年有效剂量限值为1 mSv", "E": "放射工作人员年有效剂量限值为100 mSv"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-103", "kp": "剂量限值标准", "ch": "二、医学物理基础 → 7.X线防护与测量 → (4)我国放射卫生防护标准", "ex": "【为什么对】A职业照射连续5年平均年有效剂量不超过20 mSv，正确。B任何一年不超过50 mSv，正确。C职业照射眼晶体年当量剂量限值150 mSv，正确。D公众个人年有效剂量限值为1 mSv，正确。【为什么错】E放射工作人员个人剂量限值采用“5年平均20 mSv/年、任一年不超过50 mSv”，100 mSv并非我国标准中的个人年有效剂量限值，错误。", "tr": "剂量限值“职业20/50、公众1”：5年平均20 mSv与任何一年50 mSv必须成对记忆，公众1 mSv易与职业数值混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1040", "t": "多选题", "s": "关于外照射防护“时间、距离、屏蔽”三要素的实际应用，正确的描述有", "o": {"A": "增大与辐射源的距离可显著降低剂量（平方反比）", "B": "缩短受照时间可成比例减少累积剂量", "C": "屏蔽厚度增加一倍，透过剂量一定减为原来的一半", "D": "铅、混凝土、水是常用的屏蔽材料", "E": "防护屏的屏蔽效果可用铅当量进行评价"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-104", "kp": "外照射防护三要素应用", "ch": "二、医学物理基础 → 7.X线防护与测量 → (2)外照射防护一般措施", "ex": "【为什么对】A距离防护利用平方反比定律，增大距离剂量显著下降，正确。B剂量与受照时间成正比，缩短时间即减少剂量，正确。D铅、混凝土、水（尤其对中子水是良好慢化剂）为常用屏蔽材料，正确。E屏蔽能力以铅当量统一评价，正确。【为什么错】C只有屏蔽厚度恰好增加一个半价层时透过剂量才减半；屏蔽厚度与透过剂量之间按指数规律衰减，“厚度翻倍剂量必减半”不成立，错误。", "tr": "屏蔽衰减是指数规律（每增一个半价层减半），不是线性比例；“厚度翻倍剂量减半”是貌似合理的错误表述。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1041", "t": "多选题", "s": "关于照射量与吸收剂量的测量及其量纲，正确的描述有", "o": {"A": "照射量仅适用于X、γ射线在空气中的测量", "B": "照射量的国际单位为库仑每千克（C/kg）", "C": "吸收剂量的国际单位为戈瑞（Gy）", "D": "1 Gy=1 J/kg", "E": "照射量适用于任何介质中任何类型的辐射"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-105", "kp": "照射量与吸收剂量", "ch": "二、医学物理基础 → 7.X线防护与测量 → (5)照射量测量", "ex": "【为什么对】A照射量定义基于X、γ射线对空气的电离效应，仅适用于空气（或等效空气介质），正确。B照射量国际单位C/kg（旧单位伦琴R），正确。C吸收剂量单位Gy（旧单位rad），正确。D吸收剂量为单位质量物质吸收的能量，1 Gy=1 J/kg，正确。【为什么错】E照射量只能在X、γ射线与空气中定义和测量，不适用于其他介质（如组织、水）及α、β、中子等辐射，说“任何介质任何辐射”错误。", "tr": "照射量“只限X、γ射线+空气”，是量程最窄的辐射量；吸收剂量适用于任何介质、任何辐射（Gy），两者适用条件差异是考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U02-1042", "t": "多选题", "s": "某X线机房外检测发现关注点剂量率超标，下列降低墙外关注点剂量的措施中正确的有", "o": {"A": "增加机房防护墙的铅当量厚度", "B": "缩短机房内曝光时间", "C": "增大辐射源至墙外关注点的距离", "D": "在源与墙之间加设移动铅防护屏", "E": "将机房整体迁至更高楼层以降低剂量"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-106", "kp": "机房屏蔽降剂量措施", "ch": "二、医学物理基础 → 7.X线防护与测量 → (3)外照射屏蔽防护", "ex": "【为什么对】A增加防护墙铅当量属于屏蔽防护，可降低透过剂量，正确。B缩短曝光时间减少单位时间剂量累积与机房门开启期间泄漏，正确。C增大源至关注点距离利用平方反比定律降低剂量率，正确。D移动铅屏可直接遮挡原发射线与散射线，是临时性的有效屏蔽手段，正确。【为什么错】E机房楼层位置不改变辐射源与关注点的几何关系，也不改变屏蔽需求，“迁移楼层即可从根本上降低剂量”缺乏物理依据，错误。", "tr": "降剂量必须落到“时间、距离、屏蔽”三要素上，任何脱离物理规律的措施（如改楼层）都是无效干扰项。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U02-2043a", "t": "共用题干题", "s": "乳腺X线摄影采用低管电压（约25～32 kV）的主要目的是", "o": {"A": "缩短曝光时间", "B": "提高光电效应比例，增强乳腺软组织的X线对比", "C": "降低散射线产生", "D": "减少患者运动伪影", "E": "提高X线穿透能力"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-108", "kp": "乳腺摄影低kV的物理原理", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】乳腺内脂肪与腺体组织有效原子序数相差很小，需利用光电效应放大原子序数差异才能显示对比。低管电压时X线光子能量低，光电效应比例显著增大（∝1/E³），乳腺软组织对比度提高，故选B。【为什么错】A曝光时间由管电流与剂量控制决定，与低kV无关。C散射线主要与照射野、厚度及kV有关，低kV不降低散射线。D运动伪影与曝光时间相关，与kV无关。E低kV反而使X线穿透力下降，这正是需要压迫配合的原因。", "tr": "低kV摄影“借光电效应放大Z差异”是乳腺高对比的物理基础，“低kV提高穿透力”是方向性陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0201", "gs": "患者女性，50岁，临床触诊右乳上方可疑肿块，行乳腺X线摄影检查。技师需在保证图像质量的前提下提高乳腺软组织对比并控制受照剂量，遂采用钼靶X线管、低管电压与适当滤过的组合进行摄影。"}, {"id": "U02-2043b", "t": "共用题干题", "s": "低管电压使X线穿透力下降、受照剂量偏高，乳腺摄影中最常用的补偿措施是", "o": {"A": "增大阳极靶面焦点面积", "B": "选用钼（或铑）滤过并加压压迫乳腺、缩短曝光时间", "C": "去除滤线栅以减少吸收", "D": "增大照射野提高宽容度", "E": "将管电流提高至设备极限"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-112", "kp": "低kV摄影的剂量补偿", "ch": "二、医学物理基础 → 1.X线的产生 → (4)影响X线产生的因素", "ex": "【为什么对】低kV下X线质软、穿透弱，需通过乳腺加压（压缩）减薄乳腺厚度、降低散射线与入射剂量，并选用钼/铑滤过优化能谱、配以足够管电流缩短曝光时间，这是乳腺摄影的常规综合措施，故选B。【为什么错】A增大焦点面积与剂量补偿无关，反而降低空间分辨率。C去除滤线栅虽减少射线吸收，但会明显增加散射线、降低对比度，得不偿失。D增大照射野会增加散射线与不必要的照射。E管电流提高至设备极限会带来热容量与剂量控制问题，并非规范补偿手段。", "tr": "乳腺摄影剂量补偿是“压迫+滤过+合适mA”的组合拳，单靠某一项（如无限提管电流）不是规范做法。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0201", "gs": ""}, {"id": "U02-2043c", "t": "共用题干题", "s": "乳腺X线摄影中加压（压迫）乳腺的主要目的是", "o": {"A": "减小乳腺厚度，降低散射线并减少受照剂量", "B": "增加乳腺的血流灌注", "C": "便于乳腺病变的定位标记", "D": "提高摄影管电压", "E": "扩大有效照射野"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-107", "kp": "乳腺摄影压迫的目的", "ch": "二、医学物理基础 → 7.X线防护与测量 → (1)放射防护基本原则", "ex": "【为什么对】加压使乳腺厚度减小，一方面降低散射线产生、提高对比度，另一方面减少入射剂量并缩短曝光时间，是乳腺摄影质量与剂量平衡的关键措施，故选A。【为什么错】B压迫减少而非增加血流。C定位标记与压迫无直接关系。D压迫并不改变管电压设置。E压迫缩小乳腺厚度分布，不扩大照射野。", "tr": "压迫的四大收益“减薄、降散、减量、防动”：注意压迫是减小厚度而非常规意义上“固定”，其剂量学意义是核心考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0201", "gs": ""}, {"id": "U02-2044a", "t": "共用题干题", "s": "颅脑CT中因骨与软组织对多能X线衰减差异导致的条带状低密度伪影，最常见的成因是", "o": {"A": "呼吸运动伪影", "B": "射束硬化（低能光子被颅骨优先吸收）", "C": "探测器通道损坏", "D": "金属植入物伪影", "E": "部分容积效应"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-107", "kp": "射束硬化伪影成因", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】颅骨含钙、密度高，多能X线穿过颅骨时低能部分被优先吸收，出射射线“变硬”（平均能量升高），导致邻近脑组织（尤其两骨板之间）出现条带状低密度伪影，即射束硬化伪影，故选B。【为什么错】A呼吸运动伪影多见于胸腹部，颅脑扫描无呼吸运动干扰。C探测器通道损坏产生环形伪影。D金属植入物伪影呈星芒状高密度条带，本例无金属物。E部分容积效应出现在高密度界面的层面间平均效应，不呈条带状骨旁低密度。", "tr": "射束硬化伪影“骨旁条带低密度”（颅底、岩骨旁、椎体旁）与金属伪影“星芒状”形态不同，成因均与能谱衰减有关但表现各异。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0202", "gs": "患者男性，70岁，行颅脑CT平扫。技师发现颅骨下方脑组织出现条带状低密度伪影，影响基底节区观察，考虑与X线能谱及骨质对射线衰减差异有关，需要明确伪影成因并予以纠正。"}, {"id": "U02-2044b", "t": "共用题干题", "s": "为减轻上述射束硬化伪影对基底节区观察的影响，下列措施中最有效的是", "o": {"A": "增大扫描层厚", "B": "采用射束硬化校正算法（骨校正）", "C": "降低扫描管电压", "D": "增大扫描螺距", "E": "延长每层扫描时间"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-108", "kp": "射束硬化伪影校正", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】现代CT通过射束硬化校正算法（如骨校正、迭代重建中的物理模型校正）对多能谱衰减进行补偿，能显著减轻颅底、椎体旁射束硬化伪影，故选B。【为什么错】A增大层厚加重部分容积效应，不能减轻射束硬化。C降低管电压使X线更软、骨吸收更突出，伪影反而加重。D增大螺距提高扫描速度，与射束硬化校正无关。E延长扫描时间增加辐射剂量且不校正伪影。", "tr": "射束硬化伪影的对策是“校正算法”（骨校正/迭代重建）而非降低kV或加大层厚，降低kV反而加重低能光子被骨吸收的现象。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0202", "gs": ""}, {"id": "U02-2045a", "t": "共用题干题", "s": "颅脑MRI中，脑脊液在T2WI上的信号特点是", "o": {"A": "低信号", "B": "高信号", "C": "无信号", "D": "中等信号", "E": "与脂肪信号相同的短T1高信号"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-109", "kp": "脑脊液T2WI信号", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】脑脊液几乎为纯水，T2时间很长，在T2WI上呈显著高信号，这是MRI中“水呈高信号”的典型表现，故选B。【为什么错】A低信号是脑脊液在T1WI上的表现（T1长）。C脑脊液有明确信号，不会无信号。D中等信号描述不准确，T2WI上脑脊液为明显高信号。E脂肪为短T1、T2中等，T2WI上呈中等偏高信号，脑脊液与之信号并不相同。", "tr": "脑脊液“T1WI低信号、T2WI高信号”（长T1、长T2），两个权重下的信号方向相反，是MRI信号判读的基础考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0203", "gs": "患者女性，42岁，头痛伴视物模糊就诊，行颅脑MRI检查。技师需选择能清晰显示脑脊液信号、辅助区分囊性病变与实性占位的序列，并注意弛豫时间对信号强度的影响。"}, {"id": "U02-2045b", "t": "共用题干题", "s": "为鉴别脑内含液囊性病变与实性占位，最常用的序列组合是", "o": {"A": "T1WI与T2WI联合判读", "B": "仅轴位T1WI", "C": "仅轴位DWI", "D": "仅轴位T2*WI", "E": "仅三维时间飞跃法MRA"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-110", "kp": "囊性病变与实性占位鉴别序列", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】含液囊性病变（如囊肿）为长T1长T2，T1WI呈低信号、T2WI呈均匀高信号，与脑脊液信号一致；实性占位T1WI为等低信号、T2WI为等或稍高信号且不均匀。联合T1WI与T2WI的信号特征即可可靠区分二者，故选A。【为什么错】B仅T1WI上液体与部分实性病变均呈低信号，无法区分。C DWI反映弥散受限，不能作为常规鉴别手段。D T2*WI对磁化效应敏感，主要用于出血与钙化显示。E MRA为血管成像，与囊实性鉴别无关。", "tr": "囊性病变“T1低、T2均匀高、与脑脊液同信号”，实性病变“T2不均匀等稍高”，两序列联合的信号模式是鉴别核心。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0203", "gs": ""}, {"id": "U02-2046a", "t": "共用题干题", "s": "评价X线机房屏蔽墙效果时，墙外测量最常使用的辐射量是", "o": {"A": "照射量率（或空气比释动能率）", "B": "放射性活度", "C": "核素半衰期", "D": "入射光子总数", "E": "线性能量转移（LET）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-108", "kp": "机房屏蔽检测辐射量", "ch": "二、医学物理基础 → 7.X线防护与测量 → (5)照射量测量", "ex": "【为什么对】X线机屏蔽验收时，通常用照射量率或空气比释动能率（及相应的吸收剂量率）在墙外关注点测量，与限值标准（剂量率）直接比较，故选A。【为什么错】B放射性活度（Bq）描述放射源衰变速率，适用于放射性核素而非X线机。C半衰期描述核素衰变快慢，与屏蔽评估无关。D光子总数不反映剂量学后果。E LET描述辐射线质（能量沉积密度），不用于屏蔽效果的直接测量。", "tr": "机房检测测“率”（照射量率/剂量率），活度与半衰期是核医学概念，勿将X线机当作放射性核素源来测量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0204", "gs": "某新建X线机房安装验收时，需在屏蔽墙外进行辐射剂量检测。工程师使用剂量仪在墙体不同距离处测量，并依据国家标准评估机房屏蔽是否满足剂量限值要求。"}, {"id": "U02-2046b", "t": "共用题干题", "s": "若墙外关注点剂量率超标且无法增厚防护墙，最可行的降剂量方案是", "o": {"A": "增大源与关注点距离并延长曝光时间", "B": "增大源与关注点距离并缩短曝光时间", "C": "增大照射野面积", "D": "改用更高管电压扫描", "E": "增大毫安秒（mAs）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-109", "kp": "距离与时间的联合防护", "ch": "二、医学物理基础 → 7.X线防护与测量 → (2)外照射防护一般措施", "ex": "【为什么对】依据外照射防护三要素，增大源与关注点距离（平方反比降低剂量率）与缩短曝光时间（降低累积剂量）联合使用，可在不增厚墙体的情况下使剂量降到限值以下，故选B。【为什么错】A延长曝光时间会增加累积剂量，与降剂量目标相反。C增大照射野增加散射线与剂量。D更高管电压增加输出剂量率。E增大mAs增加曝光量，方向完全相反。", "tr": "防护“时间短、距离远、屏蔽厚”：任何“延长时间、增大mAs、提高kV”的选项都与降剂量目标相悖，是明显干扰项。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0204", "gs": ""}, {"id": "U02-2047", "t": "案例分析题", "s": "患者男性，55岁，腰椎退变复查，行腰椎正位X线摄影。技师根据影像放大率及投照要求将焦点-胶片距离（FFD）由100 cm调整为140 cm。在球管输出条件不变的条件下，若要维持照片密度基本不变，需要同步调整曝光参数。此时管电流时间乘积（mAs）应调整为原来的约", "o": {"A": "0.5倍", "B": "0.7倍", "C": "1.4倍", "D": "2.0倍", "E": "1.2倍"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-109", "kp": "距离变化时的mAs补偿", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (1)距离的衰减", "ex": "【为什么对】照片密度与到达胶片的X线量成正比，而X线量与距离平方成反比。FFD由100 cm增至140 cm，到达胶片的剂量率降为原来的（100/140）²≈0.51，为维持相同密度需将mAs补偿为原来的1/0.51≈1.96倍，即约2.0倍，故选D。【为什么错】A 0.5倍是距离比值的平方小于1的错误方向，FFD增大应增加而非减少mAs。B 0.7倍约为距离比值的0.71倍，与平方反比规律不符。C 1.4倍为距离比值本身，未按平方计算。E 1.2倍与平方补偿不符。", "tr": "mAs补偿按“距离平方反比”：FFD增至1.4倍，mAs应增至约2倍（1.4²≈2），只按比例不按平方是常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-2048", "t": "案例分析题", "s": "某介入诊疗操作中，技师需要站在远离X线源的位置进行床边监测。已知距X线源（视为点源）2 m处的空气吸收剂量率为1 mGy/h，若技师改在距源4 m处站位观察，忽略空气吸收及其他因素，该位置的剂量率约为", "o": {"A": "0.5 mGy/h", "B": "0.25 mGy/h", "C": "0.125 mGy/h", "D": "2 mGy/h", "E": "4 mGy/h"}, "d": "易", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-110", "kp": "距离防护的剂量计算", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (1)距离的衰减", "ex": "【为什么对】按距离平方反比定律，剂量率与距离平方成反比。距离由2 m增至4 m（2倍），剂量率降为原来的1/2²=1/4，即1 mGy/h×1/4=0.25 mGy/h，故选B。【为什么错】A 0.5 mGy/h是按距离一次方反比（1/2）计算的结果，未用平方。C 0.125 mGy/h为1/8，对应距离3倍以上或额外因素。D 2 mGy/h与4 mGy/h均为距离增大剂量率反而升高的错误方向。", "tr": "距离防护是平方反比而非一次方反比，“距离翻倍剂量减为1/4”必须按平方记忆，减半是常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-2049", "t": "案例分析题", "s": "患者男性，40岁，左膝关节外伤后肿痛，临床需同时评估骨质有无骨折及周围软组织有无肿胀，行左膝关节X线摄影。技师拟选择合适的管电压以兼顾骨骼与软组织的显示。此时选用中等管电压（约60～70 kV）的物理依据是", "o": {"A": "管电压越高，骨与软组织对比度越大", "B": "中等管电压下光电效应与康普顿散射相互平衡，骨骼、软组织与脂肪的密度差异均可较好显示", "C": "管电压越低，散射线越少、剂量越低", "D": "中等管电压时X线穿透力达到最大", "E": "管电压与组织对比度没有任何关系"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-109", "kp": "管电压与组织对比度的关系", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】管电压较低时光电效应占优，突出原子序数差异，利于骨与软组织对比；管电压较高时康普顿散射为主，各组织差异缩小。中等管电压使光电效应与康普顿效应达到平衡，骨、软组织、脂肪的密度差异均能在照片上较好显示，故选B。【为什么错】A管电压越高，光电效应越少、组织间对比越差，方向相反。C降低kV并不直接减少散射线（散射线与照射野、厚度关系更大），且剂量补偿需要额外措施。D中等kV不是穿透力最大状态，管电压越高穿透力越强。E管电压是决定X线质与组织对比的核心因素，“无关系”错误。", "tr": "kV与对比的“反比”关系（高kV低对比、低kV高对比）是能量选择核心，中等kV平衡兼顾是四肢摄影的常用选择。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U02-2050", "t": "案例分析题", "s": "患者男性，45岁，复查颅脑MRI。科室新装机为3.0 T，此前设备为1.5 T。技师需要在3.0 T设备上重新设置T1WI序列参数以利用场强优势。关于3.0 T相对于1.5 T的物理特性，正确的认识是", "o": {"A": "组织T1时间总体延长，信噪比更高，灰白质T1对比通常更好", "B": "组织T1时间缩短，组织对比明显变差", "C": "氢质子的旋磁比增大", "D": "质子进动频率不变", "E": "可直接沿用1.5 T的全部序列参数而无须调整"}, "d": "易", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-111", "kp": "场强对弛豫与信噪比的影响", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】场强升高使氢质子热平衡宏观磁化增大，信噪比提高；组织T1时间随场强升高而总体延长，但不同组织延长程度不同，灰质与白质的T1对比通常在3.0 T更优，故选A。【为什么错】B场强升高使T1延长而非缩短，且对比并不变差。C旋磁比是原子核固有属性，与场强无关。D质子进动频率（拉莫尔频率）随场强升高而成正比增大（3T约127.8 MHz）。E场强改变后须调整TR、SAR、频率等参数，直接沿用1.5 T参数是不安全的做法。", "tr": "场强升高“信噪比升、T1延长、进动频率升、旋磁比不变”，四个变化方向各不相同，“旋磁比随场强变化”是典型陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-2051", "t": "案例分析题", "s": "某放射技师长期在介入导管室参与心血管介入操作，科室为其配备个人剂量计并建立剂量档案，每季度进行监测与记录。依据GB 18871—2002《电离辐射防护与辐射源安全基本标准》，该技师连续5年个人剂量监测结果应满足的年平均有效剂量限值为", "o": {"A": "1 mSv", "B": "10 mSv", "C": "20 mSv", "D": "50 mSv", "E": "150 mSv"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-110", "kp": "职业照射年剂量限值", "ch": "二、医学物理基础 → 7.X线防护与测量 → (4)我国放射卫生防护标准", "ex": "【为什么对】依据GB 18871—2002，放射工作人员连续5年内的年平均有效剂量不超过20 mSv，且任何单一年份不超过50 mSv，故选C。【为什么错】A 1 mSv为公众个人年有效剂量限值，不适用于放射职业人员。B 10 mSv无标准依据。D 50 mSv是任何单一年份的限值，而非5年平均值。E 150 mSv为职业眼晶体年当量剂量限值，属局部器官限值。", "tr": "职业照射“连续5年平均20 mSv”与“任一年不超过50 mSv”成对出现，与公众1 mSv、眼晶体150 mSv三个数值构成标准考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-2052", "t": "案例分析题", "s": "某X线机房设计时需用铅板对初级射线束进行屏蔽，设计要求使透过铅板的X线强度衰减至入射强度的1/16。已知该能量条件下铅的半价层（HVL）为0.5 mm，则所需铅板的总厚度约为", "o": {"A": "0.5 mm", "B": "1.0 mm", "C": "2.0 mm", "D": "4.0 mm", "E": "0.125 mm"}, "d": "易", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-111", "kp": "半价层求屏蔽厚度", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (2)物质吸收的衰减", "ex": "【为什么对】每经过一个半价层，强度衰减为原来的1/2。要求衰减至1/16=（1/2）⁴，即需要4个半价层厚度，4×0.5 mm=2.0 mm，故选C。【为什么错】A 0.5 mm为1个半价层，仅衰减至1/2。B 1.0 mm为2个半价层，衰减至1/4。D 4.0 mm为8个半价层，衰减至1/256，超出设计要求。E 0.125 mm为1/4个半价层，衰减更弱。", "tr": "由“剩余比例求半价层个数”再乘HVL厚度，1/16=2⁻⁴对应4个HVL，指数运算与倍数混淆是易错点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-2053", "t": "案例分析题", "s": "乳腺X线摄影机采用钼（Mo）靶X线管，其K系特征X线能量约为17.5 keV（Kα）与19.6 keV（Kβ）。技师利用钼的特征X线作为主要工作射线进行乳腺摄影。选择钼靶特征X线的物理依据是", "o": {"A": "钼K系特征X线能量较低，恰好处于乳腺组织光电效应占优的能量区间，可提高软组织对比度", "B": "钼K系特征X线能量在所有医用靶材中最高，穿透力最强", "C": "钼的原子序数高于钨，特征X线能量最高", "D": "特征X线能量越高，软组织对比度越好", "E": "钼靶X线管只产生特征X线，不产生连续X线"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-113", "kp": "钼靶特征X线在乳腺摄影中的应用", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】乳腺为软组织，脂肪与腺体原子序数差异极小。钼K系特征X线能量低（约17～20 keV），处于乳腺组织光电效应占优的能量区间，光电效应放大原子序数差异，从而显著提高软组织对比度，故选A。【为什么错】B钼的K系能量（17～20 keV）远低于钨（约59～69 keV），并非最高。C钼的原子序数（42）低于钨（74），特征X线能量也低于钨。D能量越高软组织对比越差（光电效应减少），方向相反。E钼靶X线管同样产生连续X线（韧致辐射），只是特征X线相对较强，说“只产生特征X线”错误。", "tr": "钼靶“低能特征线匹配乳腺光电效应区”是乳腺摄影的关键设计；钨靶特征线能量高、不适于软组织摄影，靶材与用途的对应关系是考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U02-2054", "t": "案例分析题", "s": "某科研项目拟利用MRI技术在体观察肿瘤的磷代谢状态，选用³¹P核进行磁共振波谱（MRS）研究。技师需确认³¹P核具备产生MR信号的基本物理条件。³¹P核能产生MR信号所必需的条件是", "o": {"A": "³¹P核的自旋量子数不为零（³¹P质量数为奇数）", "B": "³¹P核的原子序数为零", "C": "³¹P核不产生核磁矩", "D": "³¹P核的质量数为偶数", "E": "³¹P核不带正电荷"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-112", "kp": "³¹P核的磁性条件", "ch": "二、医学物理基础 → 5.磁学基础知识 → (2)磁性和非磁性原子核", "ex": "【为什么对】³¹P质量数为31（奇数），自旋量子数为1/2，属磁性原子核，可产生MR信号，故选A。【为什么错】B原子序数不可能为零，且MR信号与自旋量子数而非原子序数直接相关。C³¹P自旋时产生核磁矩，这是产生信号的前提。D质量数为奇数（31）而非偶数；质量数与原子序数均为偶数的核自旋为零。E³¹P核带正电荷，带电与自旋共同产生磁矩。", "tr": "磁性核判据是“质量数为奇数→自旋量子数≠0”；³¹P（31，奇数）、¹H（1，奇数）均为磁性核，¹²C、¹⁶O为偶数非磁性核。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-2055", "t": "案例分析题", "s": "医学物理师使用标准自由空气电离室（标准电离室）对某X线机输出进行照射量校准。校准需严格按照射量的定义进行测量。标准自由空气电离室测量照射量的基本原理是", "o": {"A": "收集X线电离空气产生的电荷，由电荷量与空气质量之比计算照射量", "B": "测量X线照射后物质的温度升高量", "C": "测量X线使荧光物质发出的可见光亮度", "D": "测量X线穿过物质后的衰减程度", "E": "测量X线使胶片形成的黑化度"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-111", "kp": "自由空气电离室测量原理", "ch": "二、医学物理基础 → 7.X线防护与测量 → (5)照射量测量", "ex": "【为什么对】照射量的定义是X、γ射线在空气中产生的同符号离子总电荷量与空气质量之比。自由空气电离室收集X线在确定空气质量内电离产生的电荷，据此直接计算照射量，是照射量的标准测量装置，故选A。【为什么错】B测温升属量热法，用于吸收剂量测量。C荧光亮度用于透视与增感屏原理，不用于照射量定量。D衰减程度测量用于评估屏蔽与X线质，非照射量测量。E胶片黑化度属感光测量，受胶片性能影响，非标准照射量测量。", "tr": "自由空气电离室“收集电荷、除以空气质量”严格对应照射量定义；量热法（测温升）对应吸收剂量，测量原理与辐射量的对应是考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-9101", "t": "单选题", "s": "关于电离辐射的确定性效应与随机性效应，下列说法正确的是", "o": {"A": "确定性效应有剂量阈值、严重程度随剂量增加而加重；随机性效应无阈值、发生概率随剂量增加而升高", "B": "随机性效应存在明确的剂量阈值", "C": "确定性效应不存在剂量阈值", "D": "两类效应均存在剂量阈值", "E": "两类效应均无阈值且严重程度随剂量线性增加"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "KP-BU-2-9101-副高", "kp": "确定性效应与随机性效应", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (补充)辐射生物效应", "ex": "【为什么对】A 正确：确定性效应（如放射性白内障、皮肤红斑、造血抑制）存在剂量阈值，超过阈值后严重程度随剂量增加；随机性效应（致癌、遗传效应）无阈值，发生概率（非严重程度）随剂量线性增加。【为什么错】B、C、D、E 均混淆了两类效应与阈值的关系。", "tr": "易把\"随机性效应\"与\"阈值\"错误绑定，牢记随机效应无阈值、讲概率。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "补充", "mk": 0}, {"id": "U02-9201", "t": "单选题", "s": "X 线质（硬度）主要取决于", "o": {"A": "管电压（kV）", "B": "管电流（mA）", "C": "曝光时间", "D": "焦点大小", "E": "滤过厚度无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-9201", "kp": "X线质", "ch": "二、医学物理基础 → 3.X线强度及X线质与量", "ex": "【为什么对】X 线质反映穿透力，主要由管电压 kV 决定。\n【为什么错】管电流与曝光时间决定量而非质。", "tr": "X线质由管电压决定。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-9202", "t": "单选题", "s": "X 线量（强度）与下列哪项成正比关系最密切", "o": {"A": "mAs", "B": "kV 单独", "C": "焦点尺寸", "D": "滤过", "E": "距离单独"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-9202", "kp": "X线量", "ch": "二、医学物理基础 → 3.X线强度及X线质与量", "ex": "【为什么对】X 线量（曝光量）与 mAs（管电流×时间）成正比。\n【为什么错】kV 影响质与量但非线性；mAs 是最直接量度。", "tr": "X线量随mAs成正比。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-9203", "t": "单选题", "s": "电离辐射的确定性效应（组织反应）的特点是", "o": {"A": "存在剂量阈值", "B": "无阈值随机发生", "C": "仅遗传效应", "D": "仅远期癌效应", "E": "与剂量率无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-9203", "kp": "确定性效应", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害", "ex": "【为什么对】确定性效应有剂量阈值，超过阈值才发生且严重程度随剂量增加。\n【为什么错】随机效应无阈值。", "tr": "确定性效应有阈值。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U02-9204", "t": "单选题", "s": "下列哪项属于电离辐射的随机性效应", "o": {"A": "白内障", "B": "皮肤红斑", "C": "癌症与遗传效应", "D": "造血抑制", "E": "不育"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-9204", "kp": "随机性效应", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害", "ex": "【为什么对】随机性效应（癌、遗传效应）无阈值，发生概率随剂量增加但严重程度不随剂量变化。\n【为什么错】白内障/红斑/造血抑制等多为确定性效应（有阈值）。", "tr": "随机效应=癌/遗传。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-0101", "t": "单选题", "s": "X线管采用线状焦点原理以兼顾高负荷与小焦点。若某旋转阳极X线管实际焦点在阳极—阴极方向上的长度为6.0 mm，阳极靶面倾角为16°，则该方向上有效焦点的投影长度约为", "o": {"A": "0.60 mm", "B": "1.7 mm", "C": "3.0 mm", "D": "6.0 mm", "E": "21.8 mm"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-001", "kp": "线状焦点原理与有效焦点计算", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (3)X线管的焦点", "ex": "【为什么对】线状焦点原理的核心是把实际焦点（电子撞击靶面的真实区域）做成细长条，再借助倾斜靶面向管轴方向投影，从而在保持较大受热面积的同时获得小的有效焦点。计算式为有效焦点长度＝实际焦点长度×sinθ。本题 6.0 mm×sin16°≈6.0×0.276≈1.66 mm，约 1.7 mm。【为什么错】A 是把正确结果又缩小了约10倍，属数量级错误。C 相当于按 sin30°≈0.5 计算，误用了倾角数值。D 未作投影换算，把实际焦点直接当成有效焦点。E 把乘法误作除法（6.0÷sin16°≈21.8），方向完全相反——倾斜投影只会使焦点变小，不可能变大。", "tr": "只有沿阳极—阴极方向（长轴）的尺寸被 sinθ 压缩，垂直方向的宽度不变，故有效焦点近似为方形；命题常把\"实际焦点\"与\"有效焦点\"互换，或把乘 sinθ 改成除 sinθ。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0102", "t": "单选题", "s": "临床摄影可观察到X线束沿阳极—阴极方向强度分布不均，靠近阳极侧的影像密度偏低，此即阳极效应（足跟效应）。其产生的根本原因是", "o": {"A": "阴极灯丝发射的电子束在管内发生偏转", "B": "管套窗口的附加滤过板对阳极侧射线的选择性吸收", "C": "倾斜的阳极靶面对其自身深部产生的X线存在吸收（靶面自吸收），朝阳极侧出射的射线被更多衰减", "D": "阳极高速旋转使焦点沿轨道移动而产生的强度调制", "E": "阳极侧靶物质的原子序数高于阴极侧"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-002", "kp": "阳极效应（足跟效应）的机制", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】X线在靶面一定深度内产生，向阳极侧出射时需穿过更长的靶物质路径，被靶自身吸收得更多；靶面倾角越小，这段路径越长，阳极侧强度衰减越明显。因此近阳极端射线强度低、近阴极端强度高，最大强度约位于中心线偏阴极侧。【为什么错】A 电子束在聚焦罩约束下指向靶面，其偏转不是强度分布不均的原因。B 附加滤过板对整个射野是均匀作用的，不会造成阳极—阴极方向的梯度。D 阳极旋转是为分散热量，焦点轨道旋转不改变射野内的空间强度分布。E 靶面为同一种钨（钨铼合金）材料，不存在两侧原子序数差异。", "tr": "足跟效应随倾角减小、照射野增大、焦—片距缩短而更明显；把原因误记为\"滤过\"或\"电子偏转\"是常见失分点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0103", "t": "多选题", "s": "为改善影像密度的均匀性，技师可主动利用或抑制阳极效应。下列关于摆位与条件安排的表述，正确的有", "o": {"A": "胸椎正位摄影时将患者头端置于阳极侧、腰骶端置于阴极侧，使较厚部位获得更高的射线强度", "B": "股骨全长正位摄影时将股骨近端（较厚）置于阴极侧、膝端置于阳极侧", "C": "焦—片距（SID）增大时，阳极效应造成的密度不均将更加显著", "D": "在实际焦点不变的条件下，阳极靶面倾角越小，阳极效应越显著", "E": "适当缩小照射野、只使用射野中心区域，可减轻阳极效应对密度均匀性的影响"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-003", "kp": "阳极效应的临床摆位应用", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】A 胸椎上段薄、下段与腰骶交界厚，把厚部放在射线强度高的阴极侧可平衡密度。B 股骨近端软组织厚、膝端薄，同理厚部对阴极。D 倾角越小，靶面自吸收路径越长，阳极侧衰减越重，效应越显著。E 射野边缘处强度差最大，缩野后仅用中心区域，密度梯度自然减小。【为什么错】C 方向说反了：SID 增大后，同一探测器尺寸对应的张角变小，所用射线更集中于中心区，密度不均反而减轻。", "tr": "记忆口诀是\"厚部对阴极、薄部对阳极\"；C 项是最常见的反向陷阱——把\"距离越远越不均\"与平方反比定律混为一谈。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0104", "t": "单选题", "s": "将旋转阳极X线管的靶面倾角由16°减小到12°，在实际焦点尺寸保持不变的条件下，其直接影响是", "o": {"A": "有效焦点增大，有效照射野也随之增大", "B": "有效焦点不变，但阳极热容量明显提高", "C": "有效焦点减小，阳极效应（足跟效应）随之减弱", "D": "有效焦点减小、几何模糊减少，但有效照射野缩小且阳极效应加重", "E": "有效焦点减小，同时X线管瞬时最大允许负荷同步提高"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-004", "kp": "阳极倾角对焦点、射野与负荷的影响", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (4)旋转阳极X线管", "ex": "【为什么对】有效焦点＝实际焦点×sinθ，倾角减小则有效焦点变小，几何模糊（半影）随之减少、锐利度提高；但倾角决定X线束的张角，倾角越小射线锥角越窄，可覆盖的探测器尺寸（有效照射野）越小，同时靶面自吸收路径变长使阳极效应加重。这正是乳腺X线管采用小倾角、通用摄影管采用12°~17°折中的原因。【为什么错】A 方向相反。B 热容量取决于阳极盘质量、材料与散热结构，与倾角无直接关系。C 阳极效应是加重而非减弱。E 实际焦点面积未变，焦点轨道承受的功率密度不变，最大允许负荷不会因倾角减小而提高。", "tr": "倾角是\"锐利度\"与\"照射野\"之间的取舍：小倾角＝小有效焦点＋小射野＋重足跟效应。E 项利用\"小焦点也能大负荷\"的模糊印象设陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0105", "t": "多选题", "s": "关于旋转阳极X线管的阳极热容量与瞬时最大允许负荷，下列表述正确的有", "o": {"A": "阳极热容量常用热单位（HU）表示，单相全波整流时 HU＝kV(峰值)×mA×s，三相或高频设备需乘以约1.35的换算系数", "B": "增大阳极盘直径、提高转速（由3000 r/min 提高至9000~10000 r/min）都可提高瞬时最大允许负荷", "C": "在阳极盘背面复合石墨层，主要用于增大阳极的热容量并改善辐射散热", "D": "靶面采用钨铼合金的首要目的是提高X线转换效率，而非延缓靶面龟裂", "E": "在同一支X线管上，曝光时间越长，所允许使用的管电流（mA）越大"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-005", "kp": "阳极热容量、散热率与管负荷特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】A 热单位是阳极蓄热能力的常用工程单位，三相/高频因波形接近恒压、平均电压高于单相有效值，需乘约1.35。B 盘径增大使焦点轨道周长增加、转速提高使单位面积受热时间缩短，两者都降低瞬时功率密度，从而提高允许负荷。C 石墨密度低、比热大、辐射发射率高，作为背衬可显著提高蓄热量与辐射散热能力。【为什么错】D 因果颠倒：钨的原子序数高保证转换效率，掺铼（约5%~10%）的主要目的是提高高温下的韧性、延缓靶面龟裂与粗糙化，从而延长管寿命。E 与管负荷特性曲线相反——曝光时间延长意味着能量持续输入，允许的管电流必须下降，故负荷特性曲线随时间下行。", "tr": "热容量（能装多少热，HU 或 kJ）与散热率（每分钟能散多少热，HU/min 或 kW）是两个独立指标，命题常将二者混为一谈。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0106", "t": "单选题", "s": "栅控X线管在阴极聚焦罩上增设了栅极，与普通X线管相比其工作原理与主要用途是", "o": {"A": "在栅极上施加负偏压使电子束被截止，从而实现毫秒级曝光通断，用于DSA脉冲曝光与快速连续摄影", "B": "在栅极上施加正偏压以增大管电流，用于提高乳腺摄影的X线输出量", "C": "通过栅极控制阳极转速，缩短曝光前的旋转启动时间", "D": "通过栅极滤除低能光子，使X线束硬化并降低皮肤剂量", "E": "通过栅极吸收被检者产生的散射线，从而替代滤线栅"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-006", "kp": "栅控X线管的原理与应用", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (7)特殊X线管", "ex": "【为什么对】栅控管在聚焦罩（栅极）与阴极间加上超过截止电压的负偏压时，空间电荷被推回、电子无法飞向阳极，管电流被瞬间切断；撤去负压则立即导通。由于开关在电子层面完成，通断时间可达毫秒级，且不依赖高压初级的接触器，因此适用于DSA脉冲曝光、心血管电影摄影和脉冲透视。【为什么错】B 正偏压并非其设计用途，乳腺机靠灯丝电流与曝光量控制输出。C 阳极转速由定子绕组的旋转磁场控制，与栅极无关。D 束硬化由固有滤过与附加滤过实现。E 抑制散射线依靠滤线栅、缩野和空气间隙，栅极位于管内，与散射线无关。", "tr": "\"栅控管的栅极\"与\"滤线栅\"仅一字之差却完全不同：前者控制管电流通断，后者位于患者与探测器之间去散射。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0107", "t": "单选题", "s": "下列各类医用X线高压发生器，按输出电压纹波率由大到小排列，正确的是", "o": {"A": "三相十二脉冲＞三相六脉冲＞单相全波整流＞高频逆变", "B": "高频逆变＞三相六脉冲＞三相十二脉冲＞单相全波整流", "C": "三相六脉冲＞三相十二脉冲＞单相全波整流＞高频逆变", "D": "单相全波整流＞三相十二脉冲＞三相六脉冲＞高频逆变", "E": "单相全波整流＞三相六脉冲＞三相十二脉冲＞高频逆变"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-007", "kp": "高压发生器类型与电压纹波", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】纹波率反映输出直流电压的波动幅度：单相全波整流约100%，三相六脉冲约13%，三相十二脉冲约3.5%，高频（中频逆变）通常小于2%~4%，输出最接近恒定电压。故由大到小为单相全波＞三相六脉冲＞三相十二脉冲＞高频逆变。【为什么错】A、C 把三相十二脉冲或六脉冲排在最前，与其脉冲数越多、波动越小的规律相悖。B 把纹波最小的高频排在首位，完全颠倒。D 把六脉冲与十二脉冲的顺序对调——脉冲数多者纹波必定更小。", "tr": "记忆主线是\"脉冲数越多、频率越高，纹波越小\"；纹波大意味着低能软射线比例高、皮肤剂量高、线质重复性差。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0108", "t": "多选题", "s": "与三相十二脉冲高压发生器相比，高频（中频逆变）高压发生器所具备的优势包括", "o": {"A": "逆变频率多在20~100 kHz，输出接近恒定电压，线质稳定、曝光重复性好", "B": "相同管电压设定下有效光子能量提高、低能软射线所占比例下降，患者皮肤入射剂量相对降低", "C": "体积小、重量轻，便于装入移动X线机、床旁机与口腔科X线机", "D": "可实现毫秒级的 kV／mAs 闭环反馈控制，曝光时间短、剂量精度高", "E": "由于输出电压恒定、能谱纯净，可以省去X线管的固有滤过与附加滤过"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-008", "kp": "高频高压发生器的性能特点", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】A 工频交流先整流再由逆变电路升频至千赫兹级，经高压变压器与倍压整流后纹波极小。B 波形接近恒压意味着曝光全过程都工作在设定 kV 附近，软射线比例下降，皮肤剂量降低而影像信息不减。C 高频使变压器铁芯与绕组体积大幅缩小，是移动设备小型化的关键。D 微机对 kV 与 mAs 实时采样并闭环调节，可做到毫秒级精度，配合AEC提高一致性。【为什么错】E 固有滤过来自管壁、绝缘油与窗口，本身不可拆除；附加滤过（通常总滤过≥2.5 mm Al 当量）是国家标准强制要求，用于滤除对成像无贡献的软射线，与发生器类型无关，任何设备都不得省去。", "tr": "高频发生器\"减少软射线\"是相对意义上的能谱改善，绝不等于可以取消滤过；把辐射防护的强制要求当成可选项是典型的原则性错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0109", "t": "单选题", "s": "一名45岁女性行乳腺X线摄影，压迫后腺体厚度62 mm，腺体密度为致密型（ACR c 类）。为在可接受剂量下兼顾穿透力与软组织对比度，下列靶面／滤过组合中较为合理的是", "o": {"A": "Mo/Mo（钼靶＋30 μm 钼滤过）", "B": "Rh/Mo（铑靶＋钼滤过）", "C": "Mo/Rh 或 W/Rh（钼靶或钨靶＋铑滤过）", "D": "W/Mo（钨靶＋钼滤过）", "E": "Mo/Al（钼靶＋铝滤过）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-009", "kp": "乳腺X线机靶面与滤过组合的选择", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (13)乳腺X线机", "ex": "【为什么对】钼的特征X线为 Kα 17.5 keV、Kβ 19.6 keV，钼滤过的 K 吸收缘为20.0 keV，恰好把20 keV 以上的连续谱大幅削掉，形成17~20 keV 的准单能\"通带\"，适合薄的、脂肪型乳腺。对致密而较厚的乳腺，17~20 keV 穿透不足会导致曝光时间延长、剂量升高。铑滤过的 K 吸收缘为23.2 keV，可把通带上移至20~23 keV，线质变硬、穿透力增强，故 Mo/Rh、W/Rh（数字乳腺常用W/Rh、W/Ag）是致密厚乳腺的合理选择。【为什么错】A 适用于较薄或脂肪型乳腺，用于62 mm 致密腺体会造成剂量偏高、对比不足。B 铑靶特征线为20.2、22.7 keV，而钼滤过的 K 缘在20.0 keV，恰好把铑的特征线大量吸收，组合自相矛盾。D 钨靶主要靠连续谱，其特征线（约59、67 keV）远高于乳腺成像所需能区，再用20.0 keV 的钼滤过则把有用能段几乎截断，效率极低。E 铝没有合适的 K 吸收缘，无法形成准单能通带，能谱过宽、对比度差，不用于诊断性乳腺摄影。", "tr": "解题主线是\"滤过材料的 K 吸收缘决定通带上限\"；乳腺越厚越致密，越需要把通带上移（Mo→Rh→Ag）。切勿只背\"乳腺用钼靶钼滤过\"。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0110", "t": "多选题", "s": "关于全数字乳腺X线摄影设备的结构与技术特点，下列表述正确的有", "o": {"A": "采用双焦点设计，大焦点标称约0.3 mm 用于常规摄影，小焦点约0.1 mm 用于放大摄影", "B": "X线管窗口多采用铍窗，以减少对17~25 keV 低能光子的固有滤过", "C": "靶面倾角很小并将整个管轴倾斜安装，使射野的强射线侧对准胸壁缘，减少胸壁侧腺体漏摄", "D": "放大摄影时应同时使用活动滤线栅与空气间隙，两者联合去散射效果最佳", "E": "常规摄影使用活动滤线栅，栅比多为4∶1~5∶1，低于普通X线摄影所用栅比"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-010", "kp": "乳腺X线机的结构特点", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (13)乳腺X线机", "ex": "【为什么对】A 乳腺摄影对空间分辨率要求极高，常规位用0.3 mm 焦点，放大位（1.5~1.8倍）必须用0.1 mm 微焦点以控制几何模糊。B 铍的原子序数仅为4，对低能光子吸收极小，可最大限度保留17~25 keV 的有用能段。C 乳腺机把管轴倾斜并使射野强度较高的一侧对着胸壁，既符合胸壁侧组织较厚的需要，也保证胸壁缘不被漏摄。E 乳腺压迫后厚度小、散射线相对少，采用低栅比（4∶1~5∶1）的活动栅即可，栅比过高只会徒增剂量。【为什么错】D 放大摄影时被检乳腺被抬高、远离探测器，本身已形成足够的空气间隙来发散散射线；此时必须撤去滤线栅，否则栅吸收造成剂量大幅上升且无额外收益。", "tr": "\"放大摄影撤栅、用空气间隙\"是必考点；另一常错处是把乳腺栅比记成普通摄影的8∶1~12∶1。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0111", "t": "案例分析题", "s": "ICU 一名78岁男性，重症肺炎、经口气管插管机械通气中，深度镇静、无法搬动，需床旁胸部正位摄影复查气管插管深度与右颈内静脉置管位置。科室配备电池贮能式移动DR，管电压范围40~125 kV，最高输出功率32 kW，机器未配置滤线栅。病床两侧空间狭窄，患者可摇高床头呈半坐位，邻床相距约1.5 m。作为当班技师，下列技术处置最合理的是", "o": {"A": "采用60~70 kV 低千伏配合大 mAs，以增强肺纹理对比", "B": "在床垫下加装一块8∶1 固定滤线栅以去除散射线", "C": "采用110~125 kV 高千伏配合短曝光时间，缩小照射野至胸部范围，适当加大被检体与探测器的距离以形成空气间隙，并在呼吸机吸气末（潮气量峰值）触发曝光", "D": "把 SID 缩短至50 cm，以充分利用有限的输出功率", "E": "嘱患者深吸气后屏气20 s 以彻底消除运动伪影"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-011", "kp": "移动X线机床旁胸片的技术决策", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (11)移动X线机", "ex": "【为什么对】高千伏摄影可压缩纵隔与肺野之间过大的密度差，使纵隔内的插管、导管、椎体轮廓与含气肺野同屏可见，同时因光子穿透力强而所需 mAs 小、曝光时间短，能有效抑制心搏与机械通气造成的运动模糊，还能显著降低皮肤入射剂量。无滤线栅时靠严格缩野与空气间隙控制散射线。镇静患者不能配合屏气，选择呼吸机吸气末触发是唯一可行的呼吸控制方式。【为什么错】A 低千伏软射线绝大部分被胸壁吸收，皮肤剂量高、曝光时间长、运动模糊重，且难以穿透纵隔。B 床旁摄影无法保证栅焦距、栅中心与射线中心线的对准，极易发生栅切割形成条状密度不均，且贮能式移动机输出有限，加栅后剂量代价过大。D SID 缩短使入射皮肤剂量按平方反比急剧上升，心影与纵隔放大失真加重，插管位置判断受影响。E 深度镇静并机械通气的患者无法执行主动屏气指令，20 s 屏气本身也不现实。", "tr": "床旁摄影的三大原则：高千伏短时间、严格缩野加空气间隙、随呼吸机时相曝光；另需提醒周围人员避让或穿铅衣，操作者应距球管2 m 以上并避开射线束方向。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0112", "t": "单选题", "s": "关于X线管管套（管头）的结构与功能，下列描述错误的是", "o": {"A": "管套内充绝缘油，兼起高压绝缘与传导散热的作用", "B": "管套设有膨胀器（波纹管）以缓冲绝缘油受热膨胀，并可联动过热保护开关", "C": "管套壁内衬铅层用于限制漏射线，其漏射线量应符合国家标准规定的限值", "D": "安装在管套窗口外的遮线器（限束器）及其滤过板属于X线管的固有滤过", "E": "管套窗口材料、绝缘油与管壁玻璃共同构成X线管的固有滤过"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-012", "kp": "X线管管套的结构与固有滤过", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (6)X线管管套", "ex": "【为什么对】本题选错误项。固有滤过特指X线离开管套前必然穿过的、不可拆卸的部件，包括X线管管壁玻璃（或金属陶瓷窗）、绝缘油层与管套窗口材料；而遮线器（限束器）是安装在管套外部、可拆卸更换的附件，其内的滤过板属于附加滤过，故 D 的归类错误。【为什么错】A 绝缘油既承担数万伏至十余万伏的绝缘任务，又把阳极热量传导至管套外壳散出，表述正确。B 膨胀器（波纹管）为受热膨胀的油提供缓冲空间，其位移可推动微动开关实现过热保护，表述正确。C 除窗口外，管套壁内衬铅可把漏射线限制在标准规定的范围内，表述正确。E 这正是固有滤过的定义，表述正确。", "tr": "固有滤过＋附加滤过＝总滤过；诊断用X线机在80 kV 以上通常要求总滤过不低于2.5 mm Al 当量。把限束器滤过板归入固有滤过是高频错项。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0113", "t": "单选题", "s": "口腔曲面体层（全景）X线机能把弯曲的牙弓展开成一幅平面影像，其实现这一效果的成像原理关键在于", "o": {"A": "采用大面积锥形束一次曝光后由计算机重建展开牙弓", "B": "X线管与探测器围绕患者做同步反向运动，经狭缝准直的窄束沿牙弓分段扫描，且旋转中心按牙弓形态连续移动", "C": "通过多次定点分段摄影后由软件自动拼接完成", "D": "利用双能量减影去除颈椎与颌骨的重叠", "E": "X线管固定不动，仅靠探测器高速往复摆动实现体层效果"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-013", "kp": "口腔曲面体层机的成像原理", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (12)口腔科X线机", "ex": "【为什么对】曲面体层属于狭缝扫描体层技术：X线管与探测器分置患者两侧、绕头部同步反向运动，射线被准直成垂直窄缝；由于牙弓并非正圆，机器让旋转中心沿一条与牙弓形态匹配的轨迹连续移动，使聚焦层面（体层域）始终贴合牙列，位于层面内的结构清晰成像，层面外结构因移动模糊而被抹除，最终把三维弯曲的牙弓展平为一幅连续图像。【为什么错】A 锥形束一次曝光后重建属于口腔 CBCT，不是曲面体层机的原理。C 曲面体层是连续同步扫描而非分段摄影后拼接，后者是DR长骨/全脊柱拼接技术。D 双能减影用于胸部骨与软组织分离，全景机不具备该功能。E 若X线管静止则无法形成体层效应，也无法沿牙弓展开。", "tr": "曲面体层（狭缝扫描＋移动旋转中心）与口腔 CBCT（锥束＋三维重建）是两种完全不同的设备，命题最常在此处混淆；层面外结构模糊与\"重影/伪影\"（如对侧下颌支、颈椎重叠）也常一并考查。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0114", "t": "单选题", "s": "CR 成像板（IP）在曝光后能把X线信息以潜影形式保存，并在激光扫描时释放出来。关于其光激励发光（PSL）过程，描述正确的是", "o": {"A": "X线使 BaFX∶Eu²⁺ 中的 Eu²⁺ 电离释放电子，电子被卤素空位（F 中心）俘获形成潜影；约633 nm 的激光激励使被俘获电子脱陷并与 Eu³⁺ 复合，发出约400 nm 的蓝紫色荧光", "B": "X线直接使荧光体发出400 nm 荧光，由光电倍增管即时采集成像", "C": "激光照射使荧光体产生热释光，其发射波长与激励光波长相同", "D": "X线在 IP 内产生电子—空穴对，并在外加偏置电场作用下被直接收集为电荷信号", "E": "激光使 Eu³⁺ 跃迁至激发态，退激时发出与激励光同波长的红色荧光"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-001", "kp": "IP 光激励发光（PSL）机制", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】IP 的荧光体为掺铕的氟卤化钡 BaFX∶Eu²⁺（X 为 Br、I、Cl）。曝光时 X 光子的能量使 Eu²⁺ 失去电子变为 Eu³⁺，逸出的电子被晶格中的卤素空位（F 色心）俘获于亚稳态，形成与入射剂量成正比的潜影，可稳定保存一段时间。读取时用 He-Ne 激光（633 nm）或半导体激光（约680 nm）逐点扫描，赋予被俘获电子足够能量脱陷，返回并与 Eu³⁺ 复合，多余能量以约390~400 nm 的蓝紫色光发出，经集光器与光电倍增管转为电信号后数字化。激励光与发射光波长明显分离，正是滤光片能滤掉激励光、只收集 PSL 光的前提。【为什么错】B 曝光瞬间的即时荧光属于增感屏的机制，CR 的关键恰恰是\"延迟发光\"。C 热释光需加热激发，是热释光剂量计的原理；且发射光若与激励光同波长将无法分离。D 直接产生电子—空穴对并由电场收集，是非晶硒直接转换平板探测器的机制。E 发射红光的说法与实际相反，PSL 光为蓝紫光。", "tr": "牢记\"红光激励、蓝紫光发射\"的波长关系；把 PSL 与增感屏即时荧光、热释光或直接转换混淆是最常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-0115", "t": "多选题", "s": "关于 CR 成像板（IP）与 CR 系统的特性，下列表述正确的有", "o": {"A": "IP 的荧光体多为掺铕的氟卤化钡 BaFX∶Eu²⁺（X 代表 Br、I、Cl）", "B": "IP 上的潜影会随时间自行衰退（fading），曝光后应尽快读取，长时间放置会使信号明显下降", "C": "读取后需用强光照射（擦除灯）清除残留潜影，方可重复使用", "D": "IP 的X线吸收效率与探测量子效率（DQE）高于非晶硒平板探测器", "E": "CR 的空间分辨率主要由激光束斑直径、采样间隔以及荧光体层内的光散射共同决定"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-002", "kp": "IP 的组成、衰退与 CR 系统特性", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】A 这是 IP 荧光体的标准组成。B 被俘获在 F 中心的电子会自发脱陷，室温下曝光后8 h 约衰减10%~25%，因此规范要求尽快读取，急诊尤其如此。C 读取只释放部分被俘获电子，必须用强光二次擦除，否则残留潜影将在下一次成像中形成\"鬼影\"。E 激光束斑越细、采样间隔越小则分辨率越高，而荧光体层越厚，激光在层内散射越宽，分辨率越低——这正是 CR 在灵敏度与分辨率之间的固有矛盾。【为什么错】D 结论相反：IP 的荧光体层薄、光收集效率有限，且读取过程中存在光散射与光电倍增管噪声，其 DQE 明显低于平板探测器；这也是同等影像质量下 CR 所需剂量高于 DR 的根本原因。", "tr": "\"IP 可重复使用上万次\"不等于\"性能不衰减\"：反复使用后灵敏度下降、划痕增多，需定期做灵敏度与均匀性检测并淘汰老化板。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-0116", "t": "单选题", "s": "在数字X线摄影中，非晶硒（a-Se）平板探测器与碘化铯＋非晶硅（CsI∶Tl／a-Si）平板探测器采用了不同的能量转换路径。关于非晶硒探测器的技术特点，正确的是", "o": {"A": "a-Se 先把X线转换为可见光再转换为电荷，转换环节多、锐利度较低", "B": "CsI∶Tl 为粉末状荧光体，光扩散明显，其锐利度低于 Gd₂O₂S∶Tb 增感屏", "C": "a-Se 的有效原子序数与 K 吸收缘决定其在70~120 kV 下的X线吸收效率高于 CsI", "D": "两者都必须通过光导纤维板与 CCD 耦合才能完成信号读出", "E": "a-Se 把X线直接转换为电子—空穴对，并在偏置电场作用下沿垂直方向收集，几乎不产生横向扩散，故 MTF 较高"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-003", "kp": "直接转换与间接转换平板探测器的比较", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】非晶硒属直接转换型：X线在硒层内直接激发出电子—空穴对，在数千伏偏置电场作用下电荷几乎垂直迁移到像素电极，横向扩散极小，因此调制传递函数（MTF）与空间分辨率优于间接转换型，这是其最突出的优势，也是其适合乳腺摄影等高分辨需求的原因。【为什么错】A 描述的是间接转换（CsI／a-Si）的路径，与 a-Se 恰好相反。B 结论颠倒：CsI∶Tl 为针状（柱状）晶体，像光纤一样把可见光约束在柱内向下传导，光扩散远小于粉末状 Gd₂O₂S∶Tb，锐利度更高。C 硒的原子序数仅34、K 吸收缘约12.7 keV，对常规摄影能量的吸收效率明显低于碘（Z＝53）和铯（Z＝55），所以在同等厚度与低剂量条件下 CsI 间接型的 DQE 通常更优。D 光导纤维板／CCD 耦合是早期 CCD 型数字摄影的读出方式，两种平板探测器均采用薄膜晶体管（TFT）阵列直接寻址读出。", "tr": "记忆分工：直接转换（a-Se）胜在分辨率，间接转换（CsI／a-Si）胜在X线吸收效率与低剂量 DQE；此外 a-Se 对温度较敏感、需控温，间接型对温度稳定性要求相对宽松。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-0117", "t": "多选题", "s": "填充因子与探测量子效率（DQE）是评价平板探测器性能的两个关键量。下列表述正确的有", "o": {"A": "填充因子是指像素内有效感光（收集）面积占该像素总面积的比例", "B": "在相同工艺水平下缩小像素尺寸会使填充因子下降，导致量子利用率与信噪比降低", "C": "DQE 随空间频率升高而升高，故高频细节的信噪传递优于低频", "D": "直接转换型 a-Se 探测器的电荷收集电极可近似覆盖整个像素，其等效填充因子高于同等像素尺寸的间接转换型", "E": "DQE 只取决于探测器对X线量子的吸收效率，与噪声功率谱（NPS）和调制传递函数（MTF）无关"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-004", "kp": "填充因子与 DQE", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】A 这是填充因子的定义。间接转换像素内除光电二极管外，还必须容纳 TFT 开关、数据线与栅线，这些区域不感光。B 像素缩小时 TFT 与走线所占的绝对面积不能等比例缩小，感光区占比随之下降，落到探测器上的X线量子有更大比例未被有效利用，信噪比降低——这正是小像素高分辨探测器的工艺瓶颈。D 直接转换型无需光电二极管，像素电极可几乎铺满整个像素，等效填充因子接近100%，这是 a-Se 用于高分辨乳腺摄影的另一优势。【为什么错】C 方向相反：DQE 一般在零频或低频最高，随空间频率升高而下降，因为高频处 MTF 衰减而噪声相对不减。E DQE 由公式 DQE(f)＝MTF²(f)/[NPS(f)·q] 决定，同时受量子吸收效率、MTF 与 NPS 三者影响，说\"与 NPS 和 MTF 无关\"是概念性错误。", "tr": "DQE 是\"综合性能\"指标，MTF 只反映锐利度、NPS 只反映噪声；把 DQE 简化为\"吸收效率\"，或误记为随频率上升，都是典型失分点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-0118", "t": "单选题", "s": "在 CR 图像后处理中，能够压缩影像的动态范围，使厚薄悬殊部位（如颈胸交界、纵隔与肺野）在同一幅图像上都获得良好显示的处理技术是", "o": {"A": "谐调处理——改变特性曲线的斜率与位置，调节影像整体的对比度与密度", "B": "空间频率处理——通过非锐化掩模强调或抑制特定频带的结构", "C": "动态范围压缩（组织均衡）处理——选择性抬高低信号区、压低高信号区，使密度差极大的部位同屏显示", "D": "能量减影处理——利用两种管电压曝光分离骨骼与软组织", "E": "时间减影处理——利用对比剂注入前后的图像相减"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-005", "kp": "CR 图像处理技术的分类", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (3)CR图像处理技术", "ex": "【为什么对】动态范围压缩（DRC，各厂家亦称组织均衡、层次均衡）先用低通滤波提取图像的大尺度背景亮度分布，再对该背景做非线性压缩后与原图合成，从而在保持局部对比度的前提下把极亮与极暗区域拉近，使颈胸交界、纵隔后区与含气肺野同时可读。【为什么错】A 谐调处理只是整体地平移或改变特性曲线的斜率，可调节整体黑白与反差，但不能在同一幅图内选择性地压缩局部亮度差。B 空间频率处理改变的是边缘锐利度与结构强调程度，属于对比细节增强，与动态范围压缩不是同一维度。D 能量减影需要双能曝光数据，用于骨与软组织分离，不能解决密度动态范围问题。E 时间减影用于血管造影，需要蒙片，与平片的动态范围无关。", "tr": "谐调处理调\"整体\"、空间频率处理调\"锐利度\"、动态范围压缩调\"局部亮度差\"，三者常被混答；注意组织均衡过度会造成图像发灰、伪边缘（黑边或晕环）。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-0119", "t": "单选题", "s": "数字X线摄影中，曝光指数用于监控探测器接受的剂量水平。关于富士 S 值（sensitivity）与 IEC 62494 标准中的曝光指数 EI、偏差指数 DI，正确的是", "o": {"A": "S 值与探测器接受剂量成正比，S 值升高提示曝光过度", "B": "S 值与探测器接受剂量成反比，S 值升高提示曝光不足", "C": "IEC 标准的 EI 与探测器接受剂量成反比，EI 越大剂量越低", "D": "数字探测器宽容度大，曝光量适度增加不会带来明显剂量代价，故不必监控", "E": "偏差指数 DI 等于0，表示实际曝光量约为目标曝光量的两倍"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-006", "kp": "曝光指数与剂量监控", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (2)CR计算机系统配置", "ex": "【为什么对】富士 S 值的定义决定其与 IP 接受剂量成反比：剂量越低、读出信号越弱，系统需要更高增益，S 值就越大。因此 S 值升高提示曝光不足（图像颗粒噪声增大），S 值降低提示曝光过度。【为什么错】A 把反比关系记反了。C IEC 62494 规定的 EI 与探测器空气比释动能成正比，剂量越大 EI 越大，恰与 S 值相反——这正是两套指标最容易混淆之处。D 数字系统的宽容度只是掩盖了曝光过度的\"影像表现\"，患者剂量却实实在在增加，这种\"剂量蠕变\"正是必须监控曝光指数的原因。E DI＝10·lg(EI/EI_T)，DI 为0 表示实际曝光与目标曝光一致；DI 约＋3.0 才对应约两倍剂量，约－3.0 对应约一半剂量。", "tr": "\"S 值反比、EI 正比、DI 为0 达标\"必须一起记；数字摄影没有胶片那样的过曝变黑警示，只能靠曝光指数发现剂量蠕变。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-0120", "t": "多选题", "s": "与 CR 系统相比，非晶硅平板 DR 系统所具有的优势包括", "o": {"A": "探测量子效率（DQE）更高，在获得同等影像质量时可降低患者受照剂量", "B": "无需 IP 的传送、读取与擦除环节，单次检查的工作流程时间明显缩短", "C": "平板 DR 的空间分辨率在多数情况下优于 CR 系统", "D": "响应线性好、动态范围宽，曝光宽容度大且信号与剂量关系稳定", "E": "动态平板探测器可兼做透视与点片，实现造影检查一体化"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-007", "kp": "DR 与 CR 的性能比较", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (4)DR基本结构及特性", "ex": "【为什么对】A CsI 柱状晶体层较厚且吸收效率高，光扩散被限制，DQE 明显高于 IP，是 DR 得以降低剂量的物理基础。B DR 曝光后数秒即可在控制台显示，省去了 IP 往返、扫描读取与强光擦除，检查通量大幅提升。D 平板探测器输出信号与入射剂量在很宽范围内保持线性，宽容度大且便于用曝光指数量化管理。E 动态平板具备高帧率读出能力，可完成透视、点片乃至数字胃肠与血管造影。【为什么错】C 表述过于绝对。空间分辨率取决于像素间距与光扩散：普通 DR 像素多为140~200 μm，而高分辨 CR（尤其乳腺专用 IP，采样间距可达50 μm）在极限分辨率上可以超过普通 DR。DR 的优势主要在 DQE、工作流与动态范围，而非绝对分辨率。", "tr": "\"DR 一定比 CR 清晰\"是常见误区；正确表述是同等剂量下 DR 的低对比可探测能力与 DQE 更优，极限空间分辨率需按具体像素间距比较。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-0121", "t": "案例分析题", "s": "某院使用 CR 系统开展床旁胸片。近一周多张影像上出现与激光扫描方向平行的、位置固定的规则细线状低密度（白色）伪影，更换患者与摄影条件后仍反复出现；追踪发现这些伪影总是伴随同一批次的两块 IP，同时这两块 IP 的图像颗粒感较其他 IP 明显增粗。工程师已用测试程序确认读出器的激光偏转与同步信号正常。作为技师，最合理的处置是", "o": {"A": "更换该批次老化或划伤的 IP，同时对读出器的导光板（集光器）与激光通路进行清洁除尘，处理后用均匀曝光的测试影像复核", "B": "提高摄影 mAs，用较高密度掩盖线状伪影", "C": "加大空间频率处理强度，使伪影在视觉上被弱化", "D": "把该 IP 置于强光下擦除30 min 后继续使用", "E": "缩小照射野后重新摄影，避开出现伪影的区域"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-008", "kp": "CR 系统伪影的识别与处理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (2)CR计算机系统配置", "ex": "【为什么对】与激光扫描方向平行的规则细线伪影，来源通常有二：一是 IP 表面划痕或污染，二是读出器集光器（导光板）入口积尘遮挡了 PSL 光的收集通路；本例伪影与特定 IP 绑定，提示以 IP 损伤为主，但读出光路清洁应同步完成以排除叠加因素。颗粒感增粗则提示这些 IP 反复使用后灵敏度下降、信噪比变差，已达到更换标准。处理后必须用均匀曝光影像复核，确认伪影消除并重新评估灵敏度一致性。【为什么错】B 提高 mAs 只是增加患者剂量，伪影是信号缺失所致，不会因整体密度升高而消失。C 空间频率处理反而会强化线状边缘，使伪影更醒目，且属掩盖问题而非解决问题。D 擦除只能清除残留潜影（鬼影），对划痕与灵敏度衰减无效，且伪影固定出现说明并非残影。E 缩野不能解决探测介质本身的缺陷，还可能漏摄解剖结构，属于本末倒置。", "tr": "判读伪影先分\"随患者变\"还是\"随硬件变\"：本例伪影绑定特定 IP 且位置固定，即为硬件源；若伪影随机出现且与位置无关，才考虑残影或散射因素。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-0122", "t": "案例分析题", "s": "某二级医院拟为急诊室配置一台悬吊式 DR，主要承担胸腹部、骨盆与四肢创伤摄影，兼顾夜间低剂量与快速工作流。厂家提供两种探测器方案：①碘化铯＋非晶硅间接转换探测器，像素间距140 μm；②非晶硒直接转换探测器，像素间距85 μm。两者价格相近，急诊室环境温度波动较大。作为设备论证组技师，最合理的选择与理由是", "o": {"A": "选②，因为 a-Se 空间分辨率高，可同时满足急诊各类需求且低剂量表现最佳", "B": "选①，因为 CsI 柱状晶体对60~120 kV 的X线吸收效率高，低剂量下 DQE 更优，适合急诊快速低剂量的大部位摄影；140 μm 像素对胸腹与骨盆已足够，且对环境温度波动的耐受性更好", "C": "选②，因为 a-Se 无温度依赖性，在温差较大的急诊环境中更稳定", "D": "选①，因为间接转换探测器的像素间距小于直接转换型，细节显示更好", "E": "两种方案的 DQE 与分辨率完全等价，只需比较采购价格与售后条款"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-009", "kp": "DR 探测器选型的技术论证", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】选型必须回到临床用途：急诊以胸腹、骨盆等大部位、低剂量、快节奏摄影为主，对极限空间分辨率的要求远低于乳腺；此时决定影像质量的是低剂量下的 DQE。CsI（Z 分别为53、55）对常规摄影能区吸收效率高，柱状晶体又抑制了光扩散，低剂量 DQE 优于 a-Se；140 μm 像素对应约3.6 lp/mm，完全满足胸腹骨盆需求，且数据量小、成像更快。此外 a-Se 的载流子迁移特性与暗电流受温度影响较大，需较严格的控温，急诊环境不利。【为什么错】A a-Se 对60~120 kV 光子的吸收效率低（Z＝34、K 缘约12.7 keV），低剂量下 DQE 并不占优，\"分辨率高\"不能替代\"量子利用率高\"。C 与事实相反，a-Se 恰恰对温度较敏感。D 与题干数据自相矛盾：①的像素间距140 μm 大于②的85 μm。E 两者在转换机制、吸收效率与 MTF 上差异明显，以\"完全等价\"为前提的采购论证不成立。", "tr": "\"像素越小越好\"是选型误区：像素缩小会降低填充因子、增加噪声与数据量，应按临床任务所需的极限分辨率来匹配，而不是一味求小。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0123", "t": "单选题", "s": "螺旋 CT 之所以能够实现机架连续单向旋转并同步进床扫描，其决定性的硬件突破是", "o": {"A": "采用滑环（slip ring）以电刷或非接触方式在旋转部件与固定部件间传递电源和信号，取消了机架电缆往复缠绕的限制", "B": "采用了热容量更大的X线管", "C": "用固体探测器取代了气体探测器", "D": "引入了锥形束重建算法", "E": "配备了可连续移动的检查床"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-001", "kp": "滑环技术与螺旋扫描", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】非螺旋 CT 的机架靠电缆供电与传输数据，旋转一圈后必须反向回绕，形成\"扫描—回位—进床\"的间断模式。滑环用环状导电轨道配电刷（或非接触式电容/光电耦合）实现旋转部件与固定部件之间的持续电气连接，机架从此可以单向连续旋转，配合匀速进床即形成螺旋轨迹，这是螺旋 CT 诞生的根本前提。滑环又分低压滑环（传输数百伏交流电，高压发生器置于旋转机架内）与高压滑环两类，目前以低压滑环为主流，数据传输多采用光电或射频非接触方式。【为什么错】B 高热容量球管是支撑长时间连续扫描的必要条件，但不解决\"能否连续旋转\"的问题。C 探测器类型影响效率与响应速度，与连续旋转无关。D 锥形束重建是多排 CT 出现后为解决锥角问题而发展的算法，属于软件层面且晚于滑环。E 连续进床本身在滑环出现前无法与连续旋转配合，只是螺旋扫描的另一半条件而非突破点。", "tr": "区分\"螺旋扫描的前提（滑环）\"与\"螺旋扫描的表现（连续进床）\"；另需记住低压滑环把高压发生器搬进机架，避免了高压打火与绝缘难题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0124", "t": "多选题", "s": "关于 CT 探测器的类型与性能，下列表述正确的有", "o": {"A": "气体探测器多采用高压氙气电离室，其X线吸收效率低于固体探测器，但通道间一致性好、稳定性高", "B": "掺镨硫氧化钆（Gd₂O₂S∶Pr）等稀土陶瓷或钨酸镉（CdWO₄）闪烁体配光电二极管构成固体探测器，转换效率高、余辉短，是多层螺旋 CT 的主流", "C": "探测器余辉（afterglow）过长会引起图像残影，并可能形成环状伪影", "D": "多排探测器的物理排数总是等于同时可采集的层数", "E": "气体探测器易于制成二维阵列，因此更适合用于多排螺旋 CT"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-002", "kp": "CT 探测器的类型与性能指标", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】A 氙气密度远低于固体闪烁体，即便加压至十几个大气压，量子吸收效率仍只有固体探测器的一半左右；但其结构简单、各通道由同一气室分隔而成，一致性和长期稳定性较好，这是早期 CT 采用它的原因。B 稀土陶瓷与 CdWO₄ 具有高光输出、短余辉、良好线性和抗辐射损伤能力，配硅光电二极管后转换效率可达气体探测器的两倍以上。C 余辉是闪烁体在X线停止后仍持续发光的现象，过长会使前一投影的信号\"拖尾\"进入后一投影，表现为残影，若某通道余辉异常则形成环状伪影。【为什么错】D 排数与层数是两个概念：同时采集的层数取决于数据采集系统（DAS）的通道数与探测器单元的组合方式，例如16排探测器在特定组合下只采集4层，而带 Z 轴飞焦点的64排可获得128层数据。E 与事实相反：氙气电离室需要沿射线方向有足够深度并用薄钨片分隔通道，很难在 Z 轴方向叠成多排，这正是多排 CT 全面转向固体探测器的原因。", "tr": "\"排数≠层数\"是高频考点；余辉、光输出、动态范围、通道一致性构成探测器性能的四要素，命题常以环状伪影反向考查余辉与通道一致性。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0125", "t": "单选题", "s": "多层螺旋 CT 的机架内在球管侧与探测器侧分别设置了准直装置。关于准直器的作用，正确的是", "o": {"A": "前准直器决定图像层厚，后准直器决定螺距大小", "B": "单层 CT 无需后准直器，多层 CT 完全依靠后准直器决定层厚", "C": "准直器开口越宽，Z 轴空间分辨率越高", "D": "前准直器（球管侧）限制射线束在 Z 轴方向的宽度，决定总采集束宽并直接影响受检者剂量；后准直器（探测器侧）主要用于抑制到达探测器的散射线", "E": "准直器的宽度与螺旋扫描的过扫描辐射（over-ranging）无关"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-003", "kp": "CT 准直器的功能", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】前准直器把射线束在 Z 轴方向限制为所需的采集宽度，凡是被它挡住的光子都不会照射患者，因而是控制受检者剂量的关键部件；后准直器（探测器侧的隔板/栅格）则主要拦截来自被检体的散射线，改善图像对比噪声比。【为什么错】A 螺距是床进距离与总准直宽度之比，由扫描协议设定，不由前准直器\"决定\"；层厚在多层 CT 中由探测器单元组合与重建参数决定。B 单层 CT 的层厚正是由前后准直器共同限定的；而多层 CT 的层厚取决于探测器单元的组合与 DAS 通道分配，而非后准直器。C 结论相反：准直越宽则单层厚度越大、部分容积效应越明显，Z 轴分辨率下降。E 过扫描辐射恰恰与准直宽度密切相关——螺旋扫描首末端为满足插值重建需要额外旋转的距离与束宽成正比，宽体探测器的过扫描剂量代价更大，需用动态准直器（自适应准直）加以抑制。", "tr": "\"前准直控剂量与束宽、后准直去散射\"是主线；单层 CT 与多层 CT 的层厚决定机制不同，这是最容易张冠李戴之处。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0126", "t": "单选题", "s": "部分高端 CT 采用飞焦点（flying focal spot）技术提升采样密度。关于该技术的作用机制与效果，正确的是", "o": {"A": "在机架旋转过程中让焦点随患者移动，实现对目标的连续追踪", "B": "利用偏转线圈使电子束在阳极靶面上的落点沿 Z 轴和／或扫描平面内高频交替，使同一次旋转获得双倍投影采样，从而提高 Z 轴分辨率或抑制混叠伪影", "C": "通过两只球管交替曝光以获取双能量数据", "D": "通过提高阳极转速使焦点变小，从而提高空间分辨率", "E": "让焦点在时间上抖动以分散热负荷，从而允许延长曝光时间"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-004", "kp": "飞焦点技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】飞焦点通过电磁偏转线圈在毫秒以下的时间尺度内让电子束落点在靶面上来回跳变。沿 Z 轴方向跳变（Z-flying focal spot）时，探测器每排在一次旋转中获得两套在 Z 轴上相互交错的采样，等效采样密度加倍，可使64排探测器输出128层数据，显著提高 Z 轴分辨率并减少风车状伪影；在扫描平面内跳变（φ 方向）则提高平面内的角向与径向采样密度，抑制因采样不足导致的混叠（条纹）伪影。【为什么错】A 描述的是不存在的\"焦点追踪\"概念，CT 的焦点相对机架是固定在球管内的。C 双球管交替曝光是双源 CT 的双能实现方式，与飞焦点无关；双能亦可用快速 kV 切换或双层探测器实现。D 阳极转速影响的是热负荷能力，不改变焦点尺寸；焦点尺寸由灯丝与聚焦系统决定。E 飞焦点的跳变幅度仅零点几毫米，对热分散贡献有限，其设计目的是提高采样而非提升负荷。", "tr": "把飞焦点误认为\"双源\"或\"双能\"是常见错误；记住关键词是\"采样加倍\"，Z 向飞焦点解决 Z 轴分辨率与风车伪影，面内飞焦点解决混叠伪影。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0127", "t": "多选题", "s": "关于多层螺旋 CT 的 Z 轴覆盖能力与螺距等扫描参数，下列表述正确的有", "o": {"A": "单圈 Z 轴覆盖宽度等于采集层数与单层准直宽度的乘积，如64×0.625 mm 约为40 mm", "B": "在机架旋转周期固定时，增大螺距可提高进床速度、缩短完成同一范围扫描所需的时间", "C": "螺距等于机架旋转一周检查床移动的距离除以总准直宽度", "D": "在关闭自动管电流调制、每圈 mAs 设定不变时，增大螺距会使有效 mAs 下降，受检者剂量随之降低", "E": "Z 轴覆盖宽度越大，锥形束伪影越轻"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-005", "kp": "Z 轴覆盖、螺距与有效 mAs", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】A 这是 Z 轴覆盖的定义式，64×0.625 mm＝40 mm。B 进床速度＝螺距×总准直宽度÷旋转周期，螺距增大则速度提高、总时间缩短。C 这是国际通用的螺距定义（beam pitch）。D 有效 mAs＝每圈 mAs÷螺距，螺距增大使同一断面被照射的次数减少，剂量下降（代价是噪声增加，故现代设备多用自动管电流调制维持图像质量）。【为什么错】E 结论相反：Z 轴覆盖越宽，射线束的锥角越大，边缘排探测器接收的射线偏离横断面越远，重建时的近似误差越大，锥形束伪影（尤其在高对比界面如颅底、肩部）越明显，因此宽体 CT 必须依赖锥形束重建算法（如 Feldkamp 类或加权迭代）加以校正。", "tr": "\"增大螺距降剂量\"的前提是每圈 mAs 固定；若使用自动管电流调制，设备会自动补偿使图像质量恒定，此时剂量未必下降，这是临床与考题的关键差别。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0128", "t": "单选题", "s": "关于 CT 图像重建算法的分类归属与特点，正确的是", "o": {"A": "迭代重建属于解析法的一种改进，其本质仍是一次性反投影", "B": "迭代重建的核心是提高卷积核（重建函数）的锐利度", "C": "滤波反投影（FBP）属于解析法重建；迭代重建（IR）在投影域与图像域之间反复进行正投影、比较、修正以逼近真实值，属于代数或统计迭代类算法", "D": "迭代重建不能降低图像噪声，只能改善空间分辨率", "E": "反投影法与滤波反投影法都属于迭代法"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-006", "kp": "解析法与迭代重建的原理归属", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (2)软件结构", "ex": "【为什么对】CT 重建算法分为解析法与迭代法两大类。解析法以中心切片定理为基础，用卷积（滤波）消除反投影固有的星状模糊后一次性反投影成像，代表即 FBP，速度快但对噪声与欠采样敏感。迭代法先给出初始图像估计，经正投影得到模拟投影，与实测投影比较后按一定准则（代数 ART、统计最大似然、基于模型 MBIR）修正图像，反复循环直至收敛；它可在重建过程中引入噪声统计模型、系统光学模型与先验约束，从而在低剂量下显著抑制噪声与伪影。【为什么错】A 迭代法与解析法在数学框架上完全不同，且其核心正是\"反复\"而非一次性反投影。B 卷积核锐利度属于 FBP 的参数选择，不是迭代重建的核心。D 与实际相反：抑制噪声、允许降低剂量恰恰是迭代重建最主要的临床价值，同时可改善低对比可探测能力。E 反投影法与 FBP 均属解析法，归类错误。", "tr": "\"迭代重建＝降剂量\"要有条件：迭代强度过高会使图像呈蜡样／塑料感、纹理改变，影响低对比病灶判读，故临床多采用中等强度混合迭代。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0129", "t": "多选题", "s": "关于 CT 扫描机架内的主要硬件系统，下列表述正确的有", "o": {"A": "数据采集系统（DAS）完成探测器电信号的放大、积分、采样与模／数转换，其通道数决定了可同时采集的层数", "B": "目前主流 CT 多采用低压滑环，把高压发生器安装在旋转机架内，以避免高压滑环打火与绝缘难题", "C": "参考探测器用于实时监测球管输出的波动，并据此对投影数据进行归一化校正", "D": "球管的阳极热容量越大，其单位时间的散热率必然越高", "E": "探测器排数增加可直接提高单扇区重建的时间分辨率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-007", "kp": "CT 机架硬件构成与功能", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】A DAS 是探测器与重建计算机之间的桥梁，其通道数是\"能同时读出多少路数据\"的硬约束，因而决定同时采集的层数。B 低压滑环只传输数百伏交流电，绝缘与打火风险远小于传输上万伏的高压滑环，代价是高压发生器须小型化并承受旋转离心力，这也是高频发生器技术的功劳。C 参考探测器位于射线束边缘、不经过被检体，其读数反映球管每次投影的实际输出，用于消除管电流波动带来的环状与条状伪影。【为什么错】D 热容量（单位 MHU 或 kJ，衡量能蓄多少热）与散热率（单位 kHU/min 或 kW，衡量单位时间能散多少热）是两个相互独立的指标：大热容量球管可以承受长时间连续扫描，但如果散热率低，冷却等待时间反而更长。E 单扇区时间分辨率约等于机架旋转周期的一半，由旋转速度决定；增加探测器排数只扩大 Z 轴覆盖、缩短总扫描时间，并不改变单圈的时间分辨率。", "tr": "\"热容量 vs 散热率\"\"覆盖范围 vs 时间分辨率\"是两组最易混淆的配对；提高时间分辨率的正途是加快机架转速、采用多扇区重建或双源系统。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0130", "t": "案例分析题", "s": "一名62岁男性，反复胸闷，心内科申请冠状动脉 CTA。检查前测得心率78次/分且节律不齐（心房颤动），舌下含服硝酸甘油后心率无明显下降，患者屏气配合尚可。科室设备为64排 CT（64×0.625 mm，Z 轴覆盖40 mm），机架最快旋转0.35 s/圈，具备前瞻性心电门控轴扫、回顾性心电门控螺旋扫描以及心电编辑功能。从设备性能与心律条件出发，最合理的扫描方案是", "o": {"A": "关闭心电门控，采用常规螺旋扫描后作多期相重建", "B": "采用前瞻性心电门控轴扫（step-and-shoot），仅在 R-R 间期75%处采集", "C": "采用大螺距（3.0 以上）单心动周期螺旋扫描", "D": "采用回顾性心电门控螺旋扫描，取小螺距（约0.2）全期相采集，扫描结束后利用心电编辑剔除或校正异常心搏，再从多期相中挑选运动伪影最小的期相重建", "E": "把机架旋转速度提高到0.20 s/圈以获得更高的时间分辨率"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-008", "kp": "心律不齐患者冠脉 CTA 的设备条件与门控选择", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】房颤患者 R-R 间期长短不一，无法事先预测下一个心动周期的静止期落点，唯有回顾性门控在整个心动周期内连续采集数据并同步记录心电信号，才为事后补救留出余地：心电编辑可删除早搏、插入或移动触发点，再在多个期相中挑选运动伪影最小者重建。代价是辐射剂量较高，可通过管电流调制（在目标期相外降低 mA）部分抵消。【为什么错】A 无门控扫描不记录心电时相信息，重建时无从对应心动周期，冠脉必然被搏动模糊，也无法事后补救。B 前瞻性门控只在预设期相曝光，房颤时极易采到收缩期或运动期，且相邻采集块之间会出现层间错位（阶梯状伪影），更没有其他期相可供替换。C 大螺距单心跳扫描依赖双源 CT 的高时间分辨率（约75 ms）并要求心率低而规整，64排单源设备根本不具备该能力，强行使用会造成数据缺失。E 机架旋转速度是设备的固有硬件上限，操作者不可能自行提升；0.35 s/圈对应的单扇区时间分辨率约175 ms，这正是本例必须依靠期相选择而非单纯提速的原因。", "tr": "门控选择的判断依据是\"心率快慢\"与\"节律是否规整\"两条线：心率低且规整优先前瞻门控省剂量；心律不齐必须选回顾门控＋心电编辑。切勿因\"低剂量\"惯性思维而在房颤患者上强用前瞻门控。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0131", "t": "案例分析题", "s": "某院 CT 室在连续完成十余例全腹部增强扫描后，控制台弹出提示\"球管热容量已达92%，请等待冷却\"。此时急诊送来一名高处坠落的多发伤患者，生命体征尚平稳但需尽快完成头颅、颈椎、胸腹盆的创伤全身 CT 以指导手术决策。备用 CT 正在进行设备年检无法使用。作为当班技师，在保证诊断质量前提下最优的处置是", "o": {"A": "重新规划扫描方案：适当提高螺距、开启自动管电流调制并降低参考 mAs、采用迭代重建以补偿噪声，精确设定扫描范围避免重叠曝光，同时保持机架强制风冷运行，分段完成检查", "B": "关机重启以清零热容量读数后按常规方案扫描", "C": "忽略提示按常规方案连续扫描，热容量指示不影响图像质量", "D": "把管电压由120 kV 提高到140 kV，以缩短曝光时间来减少产热", "E": "等待球管自然冷却至50%以下后再开始检查"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-009", "kp": "球管热容量限制下的扫描方案调整", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】球管产热量正比于管电压、管电流与曝光时间的乘积。提高螺距减少了单位长度上的曝光次数，开启自动管电流调制并适当下调参考 mAs 直接降低管电流，精确规划范围避免无谓曝光，三者叠加可显著降低总热负荷；随之上升的图像噪声由迭代重建加以抑制，从而在不牺牲诊断信息的前提下把检查完成。同时保持机架运行使风冷系统持续工作，比停机静置散热更快。【为什么错】B 热容量是通过阳极温度模型实时计算的物理量，重启只会丢失或重置显示值而不改变阳极的真实温度，强行曝光可能触发保护停机，严重时造成靶面熔蚀、真空度下降等不可逆损坏。C 热容量超限会触发降功率或停机保护，扫描中途中断对多发伤患者风险极高。D 提高 kV 使球管输入功率按管电压增大而上升，产热不降反升，与降热目标背道而驰，同时降低组织对比。E 多发伤属时间敏感的急诊，等待球管自然冷却可能延误手术时机，而通过参数优化本可立即完成检查，属于不必要的等待。", "tr": "设备保护提示不可强行绕过，但也不等于只能被动等待；\"降 mAs＋提螺距＋控范围＋迭代重建\"是热负荷受限时的标准应对组合。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0132", "t": "单选题", "s": "DSA 在把注药前后的两帧图像相减之前，需要先对图像信号作对数变换。这一处理步骤的根本原因是", "o": {"A": "对数变换可以提高图像的空间分辨率", "B": "对数变换可以自动消除因患者移动造成的运动性伪影", "C": "对数变换可以压缩数据量以便于长期存储", "D": "对数变换用于把相减产生的负值转换为正值以便显示", "E": "X线经人体衰减遵从指数规律，取对数后信号与被穿透组织的厚度及碘浓度呈线性关系，相减才能彻底消除背景并使碘信号具有可比性"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-001", "kp": "DSA 对数变换的意义", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】X线透过人体后强度按 I＝I₀e^(−μd) 衰减，探测到的信号与组织厚度、衰减系数呈指数关系。若直接相减，背景骨骼与软组织的贡献不能完全抵消，且相同碘量在厚薄不同的部位会产生不同的差值。取对数后 lnI₀−lnI＝μd，信号与厚度、碘浓度呈线性叠加关系，两帧相减即可精确抵消所有未变化的背景成分，只剩下与碘量成正比的差值，这既保证了背景清除的彻底性，也使不同部位的血管强化程度具有可比性，是后续定量分析的前提。【为什么错】A 对数变换是逐像素的灰度变换，不改变系统的调制传递特性，与空间分辨率无关。B 运动伪影须靠屏气配合、缩短采集时间、像素移位与再蒙片处理，对数变换无此能力。C 对数变换用于线性化而非压缩存储，DSA 数据通常以12~14 bit 保存。D 相减产生的负值靠加偏置量与窗口调节显示，与对数变换不是同一环节。", "tr": "\"先对数、后相减\"的顺序不能颠倒；把对数变换误解为\"增强对比\"或\"去噪\"是常见错误，它的本质是把指数衰减线性化。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0133", "t": "单选题", "s": "与影像增强器—电视系统（II-TV）相比，采用动态平板探测器的 DSA 系统在成像链上的主要优势是", "o": {"A": "没有枕形畸变与边缘失真，无渐晕效应，动态范围宽、DQE 高，视野呈矩形且切换视野时几何关系保持一致", "B": "空间分辨率较低但时间分辨率明显提高", "C": "由于不设输入屏，因此不再需要抗散射滤线栅", "D": "平板探测器输出为模拟视频信号，需另经模／数转换器数字化", "E": "平板探测器不能进行脉冲透视，只能连续透视"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-002", "kp": "平板 DSA 与影像增强器系统的比较", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】影像增强器靠电子光学把输入屏图像缩小到输出屏，电子轨迹在边缘处偏离理想路径造成枕形畸变，输入屏为球面又导致边缘变形；同时输出屏边缘亮度低于中心，形成渐晕。平板探测器为平面像素阵列，逐像素对应、几何关系严格线性，无上述缺陷；其圆形视野变为矩形，有效面积利用率更高，且不同视野只是读出区域不同，几何标定保持一致，有利于三维旋转采集与路径图的配准。此外平板动态范围可达10⁴以上，DQE 高，可在更低剂量下工作。【为什么错】B 平板 DSA 的空间分辨率与时间分辨率均不低于同代 II-TV 系统，说\"分辨率较低\"不成立。C 抗散射依赖滤线栅、缩野与空气间隙，与探测器类型无关，平板同样需要滤线栅。D 平板探测器在像素级完成电荷读出并直接数字化输出，无需模拟视频链路，这正是它取代 II-TV 的技术特征。E 平板可按设定帧率脉冲曝光，脉冲透视是其降低剂量的常规手段。", "tr": "枕形畸变、渐晕、S 形畸变（受地磁与杂散磁场影响）都是影像增强器特有的问题；把它们套用到平板系统上，或反过来认为平板\"无需滤线栅\"，都是概念错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0134", "t": "单选题", "s": "一名下肢动脉硬化闭塞症患者行下肢动脉 DSA，因肢体疼痛难以制动，常规掩模像方式（mask mode）减影后图像上出现明显的骨骼错位性伪影，血管显示被干扰。在不重复大量注射对比剂的前提下，最适宜采取的措施是", "o": {"A": "改用能量减影（K 缘减影）方式采集", "B": "把采集帧率提高到30帧/s 并缩短单帧曝光时间", "C": "先行像素移位（pixel shift）配准并选取更接近的帧作再蒙片（remask），仍不满意时改用时间间隔差（TID）方式减影", "D": "提高对比剂浓度与注射流率以增强血管信号", "E": "改用路径图（road map）模式进行诊断性采集"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-003", "kp": "DSA 运动伪影的减影方式选择", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】像素移位是在后处理中把蒙片整体或分区平移、旋转以与充盈帧重新配准，可校正小幅度的刚性移动；再蒙片则是重新选择一帧与目标帧运动状态更接近的图像作蒙片，二者都不需要追加对比剂。若移动幅度较大，改用时间间隔差方式（以序列中相隔固定帧数的两帧互为蒙片相减）能进一步减轻长时程漂移的影响，代价是背景抑制不如常规掩模方式彻底。【为什么错】A 能量减影需在极短时间内切换两种管电压并利用碘的 K 吸收缘（33.2 keV）作双能相减，对设备要求高、软组织信号残留多，临床应用有限，也不能解决大幅度移动。B 提高帧率只是增加采样密度和辐射剂量，运动本身仍会造成蒙片与充盈帧的错配。D 加大浓度与流率增加碘负荷与血管损伤风险，且无法消除背景错位。E 路径图是把已充盈的血管影作为背景叠加在实时透视上，用于导丝导管导航，不作为诊断性减影序列。", "tr": "处理运动伪影的顺序是\"先无创后有创\"：屏气与固定→像素移位→再蒙片→更换减影方式→最后才考虑重复造影；把路径图当成诊断序列是常见混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-0135", "t": "多选题", "s": "关于 DSA 设备的结构、功能与参数设置，下列表述正确的有", "o": {"A": "C 形臂支持多角度投照与旋转采集（3D-DSA），并可与高压注射器实现曝光—注射同步（设定X线延迟或注射延迟）", "B": "为降低皮肤剂量，透视时应尽量增大探测器与患者的距离，同时缩短球管到患者的距离", "C": "图像信号经对数放大后由模／数转换器数字化（通常为12~14 bit），再送入图像存储器完成实时相减", "D": "DSA 的时间分辨率取决于采集帧率，冠状动脉造影常用15~30帧/s，脑血管造影常用2~6帧/s", "E": "3D 旋转采集依靠影像增强器的枕形畸变进行几何标定"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-004", "kp": "DSA 设备结构与采集参数", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】A 旋转采集要求 C 形臂在等中心条件下匀速转过约200°，与高压注射器的同步延迟设置决定了旋转期间血管始终处于充盈状态。C 对数放大把指数衰减线性化，12~14 bit 量化保证了在宽动态范围内仍有足够的灰阶层次供相减使用。D 帧率决定能分辨的血流时相，冠脉因心脏搏动快需高帧率，脑血管血流相对缓慢、且为降低剂量常用低帧率。【为什么错】B 完全说反：探测器应尽量贴近患者以减少放大率、提高图像质量并利用自动亮度控制降低输出；球管则应尽量远离患者，因为入射皮肤剂量遵循平方反比定律，球管越近皮肤剂量越高，这是介入放射防护的核心原则之一。E 因果颠倒：枕形畸变是影像增强器的固有缺陷，做三维重建时必须先用标定模体测量并校正这一畸变，而不是\"依靠\"它；平板探测器无此畸变，更适合 3D-DSA。", "tr": "介入防护三要点：探测器贴近患者、球管远离患者、尽量少用放大视野与陡角度投照；B 项是最典型的反向陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0136", "t": "案例分析题", "s": "一名56岁男性肝癌患者行经导管肝动脉化疗栓塞（TACE）术前肝动脉 DSA。导管头端位于肝固有动脉，注射参数为对比剂300 mgI/ml、流率3 ml/s、总量12 ml，采集帧率6帧/s，患者清醒、未使用镇静剂。所得减影图像上肝区出现随呼吸起伏的条带状伪影，肝右叶末梢分支显示不清，肿瘤染色难以判断。作为导管室技师，最合理的调整是", "o": {"A": "把采集帧率提高至15帧/s 以\"追上\"呼吸运动", "B": "关闭抗散射滤线栅以提高图像亮度", "C": "把管电压提高到110 kV 以增强对膈下区域的穿透", "D": "把导管退至腹腔干开口并将流率提高到8 ml/s", "E": "训练并嘱患者于呼气末屏气后再曝光，适当降低帧率至3帧/s 并延长采集时间以覆盖实质期与肿瘤染色期，必要时结合像素移位与再蒙片处理残余错配"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-005", "kp": "腹部 DSA 呼吸运动伪影的技术处置", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】肝脏 DSA 的首要干扰是膈肌运动造成的蒙片与充盈帧错配。呼气末屏气是最有效且零成本的措施，且呼气末位置重复性优于吸气末。肝动脉血流较慢、肿瘤染色出现晚，3帧/s 足以刻画时相，同时可延长采集时间覆盖实质期与染色期，还能显著降低患者与术者的受照剂量。残余小幅错配再用像素移位与再蒙片校正。【为什么错】A 提高帧率只能增加采样密度，蒙片与充盈帧之间的呼吸位移依然存在，伪影不减而剂量倍增。B 撤除滤线栅后散射线大量进入探测器，对比度下降、噪声增加，虽然亮度提高但图像质量恶化，且对运动伪影毫无帮助。C 单纯提高管电压会降低碘与周围组织的对比（碘的衰减优势在较低能量区更明显），末梢分支反而更难显示。D 退至腹腔干并大幅提高流率会使脾动脉、胃十二指肠动脉等大量分支同时显影而与肝区重叠，且8 ml/s 对肝动脉超选造影而言流率过高，可能造成血管痉挛甚至内膜损伤，与\"看清肝右叶末梢\"的目标背道而驰。", "tr": "腹部 DSA 的时相安排要覆盖动脉期—实质期—静脉期；高帧率并非万能，遇运动伪影首先想到呼吸控制而不是提高帧率或加大注射。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0137", "t": "单选题", "s": "超导型 MRI 设备在特定条件下会发生失超（quench）。关于失超的过程与应急处置，描述正确的是", "o": {"A": "失超时主磁场保持不变，仅损失部分液氦", "B": "超导线圈因局部升温而丧失超导态、电阻骤增并大量产热，液氦急剧汽化经失超管排出室外，磁场在数秒至数十秒内迅速衰减；此时应立即撤离人员、开启强制排风，切勿滞留观察", "C": "失超管的作用是在液氦不足时向磁体自动补充液氦", "D": "失超发生时应立即打开磁体间门窗，并安排工作人员在室内观察磁场衰减情况", "E": "失超只能由人为按下紧急失超按钮引起，不会自发发生"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-001", "kp": "失超的机制与应急处置", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】超导线圈在液氦温度（约4.2 K）下电阻为零，一旦某处温度超过临界值即恢复电阻，强大的储存能量瞬间转化为焦耳热，液氦剧烈沸腾。1 L 液氦可膨胀成约700 L 气体，必须由失超管（专用排气管道）迅速导出室外。磁场随电流衰减而在数秒至数十秒内基本消失。现场风险来自氦气置换空气造成的窒息、极低温冻伤以及室内正压导致外开门推不开，故正确做法是立即撤离并开启强制排风。【为什么错】A 失超的本质就是磁场消失，说\"磁场保持不变\"从根本上错误。C 失超管只出不进，补充液氦需由工程师用杜瓦罐经专用接口完成。D 若氦气已泄漏入室内，人员滞留极其危险；且开窗并不能替代专用排气与新风系统。E 除人为按下急停按钮外，机械振动、真空层失效、液氦液面过低、匀场电流异常等均可引发自发失超。紧急失超按钮仅在人员被铁磁物体挤压等危及生命时才可使用。", "tr": "务必区分\"紧急失超按钮\"与\"急停（关闭梯度与射频）按钮\"：前者会毁掉磁场并造成巨额充磁与液氦费用，只在生命受威胁时使用。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0138", "t": "多选题", "s": "关于 MRI 系统的匀场（shimming）技术，下列表述正确的有", "o": {"A": "无源匀场是在磁体孔内特定位置贴放小铁片（匀场片）作被动补偿，通常在安装或大修时完成", "B": "有源匀场通过向匀场线圈通入特定电流产生补偿磁场，可在每次检查中针对扫描野作自动或高阶匀场", "C": "磁场均匀度通常以高斯（G）为绝对值表示，其数值与所取球形容积（DSV）的大小无关", "D": "场均匀度对波谱成像、频率选择性脂肪抑制以及 EPI 的几何保真度影响显著", "E": "匀场可以补偿梯度切换引起的涡流所造成的时变磁场误差"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-002", "kp": "有源匀场与无源匀场", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】A 无源匀场利用铁磁片在主磁场中被磁化后产生的附加场抵消不均匀分量，属一次性的粗调，安装、搬迁或环境改变后需重做。B 有源匀场线圈可产生一阶（线性）乃至二阶、三阶球谐分量，在每例检查中依据实际扫描野作自动匀场，是临床最常用的精调手段。D 化学位移只有百万分之几的量级，场不均匀会使波谱峰增宽重叠、脂肪抑制脉冲频率失准导致抑制不均，EPI 因带宽极低而对场偏差高度敏感，表现为几何变形。【为什么错】C 均匀度必须用相对量 ppm 表示，并且必须注明所取球形容积直径（如40 cm DSV 内小于1 ppm）；容积越大越难保证均匀，脱离 DSV 谈均匀度没有意义。E 涡流是梯度切换引起的快速时变干扰，匀场系统的响应速度远达不到毫秒级补偿要求，对策是主动屏蔽梯度线圈与预加重，而非匀场。", "tr": "\"无源＝铁片、有源＝线圈\"要记牢；均匀度必须\"ppm＋DSV\"成对表述，只给 ppm 不给容积是不完整的。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0139", "t": "单选题", "s": "某 MRI 设备的梯度系统标称最大梯度场强为45 mT/m，由零升至最大值所需的爬升时间为200 μs。据此计算其梯度切换率（slew rate）为", "o": {"A": "0.225 mT/(m·ms)", "B": "9 mT/(m·ms)", "C": "225 mT/(m·ms)", "D": "900 mT/(m·ms)", "E": "4500 mT/(m·ms)"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-003", "kp": "梯度系统三大指标与切换率计算", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】切换率＝最大梯度场强÷爬升时间。200 μs＝0.2 ms，45 mT/m÷0.2 ms＝225 mT/(m·ms)，即225 T/(m·s)。梯度场强、切换率与爬升时间是描述梯度系统的三个核心指标，其中前两者越高、后者越短，代表性能越强，这直接决定了最短 TR/TE、EPI 单次激发的回波链速度以及扩散加权可达到的 b 值。【为什么错】A 把毫秒误当作秒进行换算，结果小了三个数量级。B 相当于用45÷5 计算，误把爬升时间当作5 ms。D 在正确结果上又多乘了4，运算错误。E 相当于按0.01 ms 爬升时间计算，与题干给出的200 μs 不符。", "tr": "切换率越高，dB/dt 越大，周围神经刺激（PNS）风险越高，因此国际标准对其设有上限；临床上高切换率带来的收益（更快的 EPI、更高 b 值）必须与 PNS 和梯度噪声之间取得平衡。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0140", "t": "多选题", "s": "梯度磁场的快速切换会在磁体冷屏、射频屏蔽等导体结构中感应出涡流。关于涡流及其对策，下列表述正确的有", "o": {"A": "涡流产生的寄生磁场与所加梯度场同向，使梯度波形的上升沿变得更陡峭", "B": "采用主动屏蔽梯度线圈（在主绕组外加反向屏蔽绕组）可显著减少泄漏到周围导体上的杂散梯度场", "C": "预加重（pre-emphasis）通过对梯度驱动电流波形作反向预失真，补偿涡流造成的波形畸变", "D": "涡流可导致 EPI／DWI 图像的几何变形、鬼影以及脂肪抑制失败", "E": "提高接收带宽是消除涡流的根本方法"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-004", "kp": "涡流效应与预加重补偿", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】B 主动屏蔽梯度在主线圈外再绕一层反向线圈，使梯度场在成像区内保留而在磁体外侧近乎抵消，从源头减少感应涡流，是现代梯度系统的标准配置。C 预加重先测出系统的涡流时间常数与幅度，然后在驱动波形上叠加相反的补偿分量，使实际产生的梯度接近理想矩形波。D 涡流使读出梯度面积偏离设计值，在带宽极低的 EPI 相位编码方向上表现为几何变形与鬼影；同时残余的时变场偏移使频率选择性脂肪抑制脉冲失准，抑制不均。【为什么错】A 方向错误：由楞次定律，感应涡流产生的磁场总是反抗原磁场的变化，其寄生场与梯度变化方向相反，结果是梯度上升沿变钝、平台出现漂移与拖尾。E 提高接收带宽可以减轻化学位移伪影和 EPI 变形的表现程度，属于\"减轻症状\"，且以牺牲信噪比为代价，并未消除涡流本身。", "tr": "涡流对策的层次是\"源头屏蔽（主动屏蔽梯度）—波形补偿（预加重）—序列层面缓解（提高带宽、并行采集、场图校正）\"；把楞次定律的方向记反是本题最主要的失分点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0141", "t": "多选题", "s": "关于 MRI 射频线圈的类型、配置与临床使用，下列表述正确的有", "o": {"A": "内置于磁体孔内的体线圈常用作发射线圈，其发射场 B₁ 相对均匀、覆盖范围大", "B": "相控阵线圈由多个小单元组成，各单元独立接收后合成，兼顾高信噪比与大视野，并且是并行采集技术（SENSE／GRAPPA／ASSET）的硬件基础", "C": "表面线圈接收到的信号强度随深度迅速衰减，浅表信噪比高但深部信号弱、均匀性差", "D": "为提高信噪比，同一部位应尽量选用尺寸更大的接收线圈", "E": "接收单元数越多，图像信噪比总是越高，与线圈填充因子及单元间噪声耦合无关"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-005", "kp": "射频线圈的类型与选择原则", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】A 体线圈（鸟笼式为主）孔径大、B₁ 均匀，适合作全身激发的发射线圈，也可在缺乏专用线圈时兼作接收。B 相控阵把多个小线圈的高局部信噪比与大视野结合起来，各单元的空间敏感度差异同时提供了额外的空间编码信息，成为并行采集加速的前提。C 表面线圈的敏感深度大致相当于其半径，越深信号越弱，故常需配合表面线圈强度校正。【为什么错】D 与选择原则相反：线圈尺寸应尽量贴合被检部位，线圈越大接收到的噪声体积越大、填充因子越低，信噪比反而下降；正确做法是\"能小则小、贴合紧密\"。E 表述绝对且忽略物理限制：单元过多、排布过密会加剧单元间的电磁耦合与噪声相关性，边际收益递减，同时并行加速因子过高会放大噪声（g 因子），信噪比并不随单元数无限提高。", "tr": "线圈选择的两条铁律：与部位尺寸匹配、与被检部位紧贴（提高填充因子）；相控阵单元数是并行加速能力的上限依据，而非信噪比的保证。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-0142", "t": "单选题", "s": "MRI 检查室的墙壁、天花板、地面与观察窗内均设有铜板或铜网构成的完整屏蔽层（法拉第笼）。设置该屏蔽的主要目的是", "o": {"A": "屏蔽主磁场的杂散磁场，从而缩小5高斯线的范围", "B": "阻止梯度切换产生的噪声向室外传播", "C": "屏蔽X线散射线，保护候诊区人员", "D": "阻止外界射频电磁波（广播电视、通信、电机火花等）进入检查室干扰接收信号，同时防止本机发射的射频能量外泄", "E": "减少液氦的蒸发损耗"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-006", "kp": "射频屏蔽（法拉第笼）与磁屏蔽的区别", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】MR 信号极其微弱，其频率（1.5T 约63.9 MHz、3.0T 约127.7 MHz）恰好落在广播通信频段附近。铜质屏蔽层构成闭合导体壳，把外界射频反射与吸收在外，同时限制本机射频外泄。屏蔽的完整性依赖屏蔽门指簧的良好接触、观察窗铜网、所有穿墙管线经波导管以及电源与信号线经滤波板进入，任何一处破损都会导致屏蔽效能下降。【为什么错】A 限制杂散磁场靠磁屏蔽——自屏蔽磁体的反向超导线圈或机房内的硅钢板／铁磁屏蔽，与铜屏蔽是完全不同的两套系统。B 梯度噪声属声学噪声，靠隔声结构与隔声门处理。C MRI 不产生电离辐射，无需铅防护。E 液氦蒸发由磁体自身的真空绝热层、冷头与制冷机控制，与机房屏蔽无关。", "tr": "\"射频屏蔽用铜、磁屏蔽用铁\"是关键区分点；屏蔽破损的典型影像表现为拉链状（zipper）伪影或沿相位编码方向的条纹噪声。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0143", "t": "单选题", "s": "MRI 机房管理中常提到\"5高斯线\"。关于这一概念，正确的说法是", "o": {"A": "5高斯线（0.5 mT 等磁力线）是公认的安全警戒线，装有心脏起搏器等有源植入物者及未受控人员不得越过，该线所包围的区域必须设置明显标识并加以门禁管理", "B": "5高斯线以内属绝对安全区，铁磁性物品可以自由进入", "C": "5高斯线的范围与磁体是否采用主动屏蔽无关", "D": "5高斯线只存在于磁体所在的水平面上，上下楼层不受影响", "E": "5高斯线是指梯度磁场作用范围的边界"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-007", "kp": "5高斯线与磁体安全管理", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】0.5 mT 是普遍采用的有源植入物安全阈值，5高斯线因而成为磁场控制区的划界依据，线内区域应有醒目标识、实体隔离与门禁，非受控人员、起搏器与神经刺激器携带者禁止进入。【为什么错】B 恰恰相反：5高斯线以内磁场更强，铁磁物品进入会产生抛射效应（missile effect），是 MRI 最严重的安全事故来源。C 主动屏蔽磁体在主线圈外设置反向超导绕组抵消外泄磁场，可把5高斯线从数米压缩到磁体周围一两米范围，这正是现代 MRI 得以在有限机房面积内安装的原因。D 磁力线在三维空间中闭合，5高斯线是一个立体包络面，上下楼层同样可能被覆盖，机房选址时必须评估楼上楼下的用途。E 5高斯线描述的是主磁场 B₀ 的空间分布，与梯度场无关。", "tr": "MR 安全分区（Ⅰ~Ⅳ区）与5高斯线常被合并考查；注意\"5高斯线以内更危险\"这一方向性，切勿把它理解成安全区边界向内即安全。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0144", "t": "案例分析题", "s": "某院飞利浦3.0T MRI 检查室，近一周多例颅脑检查的图像上出现沿相位编码方向的一条明亮\"拉链状\"（zipper）条纹，位置基本固定于图像中部；技师先后更换了头颈联合相控阵线圈、更换患者、重做预扫描与自动匀场，条纹依旧存在。追问得知，一周前保洁车曾撞击机房屏蔽门，门下缘指簧有明显变形，且近期机房外走廊新增了一台无线路由设备。作为技师，对该现象最合理的判断与首选处置是", "o": {"A": "主磁场均匀性下降所致，应重新进行无源匀场", "B": "射频屏蔽失效使外界射频干扰进入检查室，应立即停止使用并检查修复屏蔽门指簧、波导管与滤波板，复测屏蔽效能合格后方可恢复扫描，同时排查并移开新增的射频源", "C": "梯度线圈涡流补偿失效，应重新标定预加重参数", "D": "液氦液面过低导致磁体不稳定，应尽快补充液氦", "E": "相控阵线圈的某个接收单元损坏，应更换线圈"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-008", "kp": "射频干扰伪影的判断与处置", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】拉链状伪影是外来窄带射频信号混入接收链的典型表现：干扰信号只有单一或很窄的频率成分，经傅里叶变换后在频率编码方向上定位于某一点，而在相位编码方向上没有确定的相位关系，于是沿相位编码方向铺展成一条亮线。本例的时间关联（屏蔽门指簧撞击变形、走廊新增无线设备）与排除性证据（更换线圈、更换患者、重做匀场均无效）共同指向屏蔽完整性受损，故应停机检修屏蔽门指簧、波导管与滤波板，用场强仪复测屏蔽效能，并排查外部射频源。【为什么错】A 场均匀性下降主要表现为脂肪抑制不均、图像变形与信号强度不均，而非固定位置的单条亮线，且题干已说明重做自动匀场无效。C 涡流补偿失效表现为几何变形、鬼影与脂肪抑制失败，常见于 EPI 类序列，与拉链伪影的形态不符。D 液氦不足会触发液面报警并最终导致失超，不会以拉链伪影为首发表现。E 已被\"更换线圈后仍存在\"这一关键信息排除；单元损坏通常表现为局部信号缺失或敏感度不均。", "tr": "MRI 伪影排查的方法学是\"变量替换法\"：换线圈、换患者、换序列、换机房时段，逐一排除；拉链伪影首先想到射频屏蔽，其次才是硬件老化与序列参数问题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-0145", "t": "单选题", "s": "关于医用高压注射器的结构与安全功能，下列表述正确的是", "o": {"A": "注射流率与总量一经设定即不能分段编程", "B": "双筒注射器的第二个针筒仅能用于注射对比剂", "C": "高压注射器无法与 CT／MR 实现曝光与注射的同步触发", "D": "用于 MR 检查的高压注射器可以直接沿用 CT 注射器的铁磁性部件", "E": "具备压力限制功能，当导管阻塞或血管外渗使管路压力超过设定上限时可自动报警并终止注射"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-001", "kp": "医用高压注射器的结构与安全功能", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (2)医用高压注射器", "ex": "【为什么对】压力限制是高压注射器最重要的安全设计：系统实时监测推注压力，当导管打折、留置针阻塞或对比剂渗入血管外使阻力骤增、压力超过预设上限（通常按导管耐压值设定）时立即报警并停止推注，可有效减少大量外渗与导管爆裂事故。【为什么错】A 现代注射器普遍支持多段程序，可设定不同流率、不同容量的多个阶段以及生理盐水冲刷段，用于优化团注形态。B 双筒设计的第二个针筒通常装载生理盐水，用于注射后冲刷残留于静脉与管路中的对比剂，既提高利用率又减少上腔静脉高浓度伪影。C 注射器与主机之间可通过同步接口实现\"注射触发曝光\"或\"曝光触发注射\"，这是团注追踪与动态增强的技术基础。D MR 检查室内的注射器必须使用无磁或弱磁材料并按磁场分区放置，直接沿用铁磁部件会造成抛射事故与图像伪影，属严重违规。", "tr": "压力限制只能减轻而不能杜绝外渗：低压缓慢渗漏可能不足以触发压力报警，因此注射全程仍须有人观察穿刺部位与患者主诉。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-0146", "t": "多选题", "s": "关于医用诊断显示器的性能要求与质量控制，下列表述正确的有", "o": {"A": "应按 DICOM PS3.14 灰度标准显示函数（GSDF）进行校准，使等间隔的驱动电平产生视觉上等间隔的可觉察灰度差（JND）", "B": "诊断报告用显示器的最大亮度要求高于临床浏览用显示器，其中乳腺阅片对分辨率与亮度的要求最高", "C": "可使用 SMPTE 或 AAPM TG18-QC 测试图对亮度响应、几何失真、伪轮廓与低对比可见度作主观评价", "D": "显示器验收合格后无需再定期校准，只要不更换设备即可长期使用", "E": "阅片室环境照度越高，越有利于观察低对比度病灶"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-002", "kp": "医用显示器的性能与质量控制", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (3)医用显示器", "ex": "【为什么对】A GSDF 的意义在于把显示器的亮度响应曲线映射为符合人眼对比敏感度特性的曲线，保证同一图像在不同显示器上呈现一致的可觉察灰度层次。B 诊断用显示器需要更高的最大亮度与对比度以展开宽动态范围的数字影像，乳腺影像因需分辨微钙化，对分辨率（常要求5 MP）与亮度的要求最为严格。C 这两套测试图是主观评价的通用工具，可快速发现亮度响应异常、几何失真、伪轮廓与低对比分辨能力下降。【为什么错】D 液晶背光会随使用时间衰减、色温漂移，必须按规定周期（通常每年一次完整校准，日常有开机自检与定期一致性检测）复校，这是质量控制体系的强制要求。E 恰恰相反：环境光在屏幕表面产生反射，抬高显示的最低亮度、压缩有效对比度，使低对比病灶更难识别，故诊断阅片室要求低照度并避免屏幕受直射光与反光干扰。", "tr": "\"验收合格＝永久合格\"是质量管理中的典型错误认识；显示器质量控制包含验收检测、状态检测与稳定性检测三个层次，缺一不可。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-0147", "t": "案例分析题", "s": "某院使用干式激光相机打印 CT 胶片。近两日打印出的胶片沿走片方向出现规律性、间距基本相等的浅色横向条带，更换不同批次、不同包装的胶片后条带依旧；调阅同一序列在诊断显示器上的图像显示完全正常，PACS 与打印机之间的 DICOM Print 通信日志无异常，打印任务亦无排队报错。作为技师，下列判断与处置最合理的是", "o": {"A": "判断为胶片受潮所致，改用其他品牌胶片即可", "B": "判断为显示器未按 GSDF 校准，重新校准显示器后再打印", "C": "判断为打印机机械走片系统或热鼓／激光扫描单元存在周期性异常，应暂停该设备并通知工程师检查输片辊、热鼓与激光偏转部件，检修后用 SMPTE 或 TG18 测试图打印复核密度与均匀性", "D": "判断为窗宽窗位设置不当，调整后重新打印", "E": "判断为网络丢包导致图像数据不完整，重启 PACS 服务器"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-003", "kp": "干式激光相机打印伪影的分析与处理", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (1)医用打印机", "ex": "【为什么对】\"沿走片方向、间距相等\"的规律性条带是典型的周期性机械或热学缺陷特征：输片辊表面附着物或磨损会以辊子周长为周期在胶片上留下痕迹，热敏成像的热鼓温度不均或激光扫描单元的偏转周期异常同样会形成等距条带。题干已用三条证据锁定故障在打印机本身——更换不同批次胶片无效（排除耗材）、显示器图像正常（排除图像数据与显示环节）、通信日志正常（排除网络与传输）。因此应停用设备交由工程师检修，检修后必须用标准测试图打印复核光学密度与均匀性，确认合格再投入临床。【为什么错】A 已更换不同批次与包装的胶片仍出现，受潮假设与证据矛盾。B 显示器校准影响的是屏幕观察效果，不改变送往打印机的像素数据，且题干显示图像本身正常。D 窗宽窗位异常会表现为整幅图像的对比或亮度失当，不会形成等距横带。E 网络丢包通常导致任务失败、图像残缺或错位，而不是规律性的密度条带，且日志已排除。", "tr": "打印质量问题的排查顺序为\"图像源→传输→打印机→耗材→环境\"；识别伪影的\"周期性\"与\"方向性\"是定位机械故障的关键线索。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1001", "t": "单选题", "s": "固定阳极X线管阳极靶面通常采用的制作材料是", "o": {"A": "钨", "B": "钼", "C": "铜", "D": "铝", "E": "银"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-001", "kp": "固定阳极X线管结构", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (1)固定阳极X线管", "ex": "【为什么对】钨的原子序数高（74）、熔点高（约3370℃）、蒸发率低、耐高温能力强，是X线管阳极靶面的理想材料。【为什么错】B钼是乳腺X线机阳极靶材，原子序数较低以产生软X线；C铜多用作阳极体散热材料，熔点低于钨；D铝常用作X线束滤过材料；E银熔点低且不耐高温，不用于靶面。", "tr": "易将乳腺机的“钼靶”误认为所有X线管通用靶材，实际普通X线管靶材为钨。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1002", "t": "单选题", "s": "旋转阳极X线管将阳极做成可旋转圆盘，其主要目的是", "o": {"A": "增大有效散热面积，提高瞬间功率承受能力", "B": "缩小实际焦点面积", "C": "降低管电压", "D": "减少X线散射线", "E": "提高X线质（能谱）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-002", "kp": "旋转阳极X线管结构", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (4)旋转阳极X线管", "ex": "【为什么对】旋转阳极使靶面不断旋转，电子轰击的热量轮流分布于整个靶盘，散热面积显著增大，能承受更大的瞬时负载功率。【为什么错】B旋转不改变实际焦点（实际焦点由灯丝形状与聚焦罩决定），只改善散热；C管电压由高压发生器决定；D散射线主要靠准直器与滤线栅减少；E X线质由管电压决定。", "tr": "旋转阳极解决的是“散热与功率”问题，而非直接缩小焦点；缩小有效焦点靠减小阳极倾角。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1003", "t": "单选题", "s": "关于X线管实际焦点与有效焦点的叙述，正确的是", "o": {"A": "实际焦点面积等于有效焦点面积乘以sinα", "B": "有效焦点是灯丝电子轰击阳极靶面的实际面积", "C": "阳极倾角越小，有效焦点越小，成像越清晰", "D": "有效焦点越大，空间分辨力越高", "E": "阳极倾角越大，X线输出效率越低"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-003", "kp": "X线管的焦点", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (3)X线管的焦点", "ex": "【为什么对】有效焦点＝实际焦点×sinα（α为阳极倾角），阳极倾角越小有效焦点越小，影像半影越小，空间分辨力越高。【为什么错】A公式写反，应为实际焦点＝有效焦点/sinα；B有效焦点是从窗口（成像方向）观察到的焦点投影，而非靶面实际轰击面积；D焦点越大分辨力越低；E阳极倾角主要影响有效焦点与足跟效应，与X线输出效率无直接对应。", "tr": "牢记“有效焦点＝实际焦点×sinα”，倾角小→有效焦点小→分辨力高，但小焦点承受功率下降。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1004", "t": "单选题", "s": "关于X线管阳极效应（足跟效应）的叙述，正确的是", "o": {"A": "阳极端X线强度低于阴极端", "B": "阴极端X线强度低于阳极端", "C": "焦点越小效应越明显", "D": "与阳极倾角无关", "E": "只影响特征X线，不影响连续X线"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-004", "kp": "X线管的规格与特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】X线在阳极靶面内斜射穿行时被靶物质吸收，阳极端吸收较多，故阳极端X线强度低于阴极端，即阳极效应。【为什么错】B恰好说反；C阳极效应主要与阳极倾角及照射野有关，与焦点大小关系不大；D倾角越小斜射距离越长，效应越明显；E阳极效应对各能量成分的X线均有影响。", "tr": "摄影时把较厚部位放在阴极端，利用阴极端强度较高的特点补偿密度差异。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1005", "t": "单选题", "s": "关于X线管空间电荷效应的描述，正确的是", "o": {"A": "管电压升高时管电流随之增大", "B": "管电压升高时管电流减小", "C": "空间电荷由灯丝加热电流决定，与管电压无关", "D": "空间电荷（电子云）越多，管电流越大", "E": "该效应使mAs控制更加准确"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-005", "kp": "X线管的规格与特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】灯丝发射的电子在管电压较低时受空间电荷（电子云）斥力限制，管电压升高后斥力作用减弱，到达阳极的电子增多，管电流随之增大，称空间电荷效应。【为什么错】B方向说反；C空间电荷效应正是管电压与灯丝电流共同作用的结果；D空间电荷越多对后续电子的排斥越强，反而不利于电子到达阳极；E该效应使管电流不稳，需加装空间电荷补偿器修正。", "tr": "空间电荷效应≠空间电荷本身多少，重点在“管电压升高→管电流增大”的联动关系。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1006", "t": "单选题", "s": "高速电子撞击阳极靶面时，其动能转换为X线的效率约为", "o": {"A": "1%", "B": "5%", "C": "20%", "D": "50%", "E": "99%"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-006", "kp": "X线管产生X线的过程", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (2)X线管产生X线的过程", "ex": "【为什么对】X线管产生的X线仅占电子总动能的约1%，其余约99%转化为热能。【为什么错】B、C、D均高估了转换效率；E将99%误认为X线转换比例，实际99%是转化为热能的比率。", "tr": "1%是X线、99%是热能，二者比例极易记反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1007", "t": "单选题", "s": "调节X线机控制台上的“mA（管电流）”旋钮，实际调节的是", "o": {"A": "灯丝加热电流", "B": "阳极转速", "C": "高压变压器初级电压", "D": "曝光时间", "E": "焦点大小"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-001", "kp": "X线管产生X线的过程", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (2)X线管产生X线的过程", "ex": "【为什么对】管电流由灯丝发射电子数决定，调节灯丝加热电流即改变发射电子数量，从而改变管电流（mA）。【为什么错】B阳极转速为固定分挡（普通/高速），与mA调节无关；C初级电压调节的是kV；D曝光时间由计时器控制；E焦点由灯丝尺寸与聚焦罩决定。", "tr": "“kV调高压发生器、mA调灯丝电流、时间调曝光”是曝光三要素的基本分工。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1008", "t": "单选题", "s": "乳腺X线摄影机X线管阳极靶面通常采用", "o": {"A": "钼（Mo）", "B": "钨（W）", "C": "铜（Cu）", "D": "银（Ag）", "E": "铱（Ir）"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-007", "kp": "特殊X线管", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (7)特殊X线管", "ex": "【为什么对】钼原子序数较低（42），其特征X线能量（约17～20keV）恰在乳腺摄影所需软X线范围，软组织对比度好。【为什么错】B钨是普通X线管靶材；C铜用于散热；D银、E铱均不用于乳腺X线管靶面。", "tr": "乳腺机钼靶＋铍窗＋小焦点＋低管电压（约22～35kV）是一组常考特征。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1009", "t": "单选题", "s": "乳腺X线机X线管窗口采用铍（Be）窗，其目的是", "o": {"A": "减少X线束中低能成分被滤过，保留软射线", "B": "增大管电流", "C": "增大焦点", "D": "提高管电压上限", "E": "便于阳极散热"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-008", "kp": "特殊X线管", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (7)特殊X线管", "ex": "【为什么对】铍原子序数低（4）、密度小，对X线吸收极少，使低能软X线能透过窗口射出，满足乳腺摄影需要。【为什么错】B管电流取决于灯丝电流；C窗口材料与焦点无关；D管电压由高压装置设定；E散热依靠绝缘油与阳极结构，与铍窗无关。", "tr": "铍窗的关键词是“透射率高、保留软X线”，与滤过方向相反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1010", "t": "单选题", "s": "医用X线高压变压器次级绕组中心点接地的目的是", "o": {"A": "使X线管两端对地电压各为管电压的一半，降低绝缘要求、保证安全", "B": "提高输出电压", "C": "减少电能损耗", "D": "稳定管电流", "E": "便于灯丝加热"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-002", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】次级中心点接地后，阳极、阴极对地电压均为管电压的一半，降低了对地绝缘要求，同时避免单端高压带来的安全隐患。【为什么错】B接地不影响输出电压幅值；C损耗与接地无关；D管电流稳定靠空间电荷补偿；E灯丝加热由灯丝变压器独立供电。", "tr": "“中心点接地”不是把其中一端接地，而是取次级绕组中点接地。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1011", "t": "单选题", "s": "现代高频X线机高压发生器通常先将工频交流电转换为", "o": {"A": "高频交流电（逆变）后再升压整流", "B": "直流电后直接升压", "C": "三相交流后直接整流", "D": "低压直流电", "E": "脉冲电压"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-003", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】高频机采用逆变技术，将工频交流整流为直流后，经逆变器变换为数十kHz的高频交流，再经高压变压器升压整流，输出纹波小、kV稳定。【为什么错】B、C直接升压/整流是传统工频机型方式；D低压直流无法直接产生管电压；E“脉冲电压”描述不完整。", "tr": "高频机优点：体积小、重量轻、kV/mA精确稳定、输出纹波小。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1012", "t": "单选题", "s": "医用X线机高压电缆内的芯线一般有", "o": {"A": "3根，分别连接阳极、阴极和地线", "B": "2根，连接阳极与阴极", "C": "4根，供两组灯丝", "D": "1根同轴芯线", "E": "5根"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-004", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】高压电缆为三芯结构：阳极芯线、阴极芯线分别接X线管两极，第三芯为零电位（地线）芯线，与金属屏蔽层相连起保护作用。【为什么错】B缺地线不安全；C灯丝电流经阴极芯线传递，无需独立4芯；D单芯无法构成阳极-阴极回路；E无5芯标准结构。", "tr": "高压电缆从内到外：芯线、绝缘层、金属屏蔽层、保护层，屏蔽层接地防电击。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1013", "t": "单选题", "s": "下列X线高压整流方式中，输出电压波纹最小、X线质最稳定的是", "o": {"A": "单相全波整流", "B": "单相半波整流", "C": "自整流", "D": "三相十二波整流", "E": "无整流"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-005", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】三相十二波整流将三相电压多相叠加，输出波纹很小，管电压接近恒定，X线质稳定、输出效率高。【为什么错】A单相全波波纹仍较大；B半波仅半周期有输出；C自整流靠X线管自身整流，仅用于小型机；E无整流无法工作。", "tr": "高频逆变机输出波纹比三相十二波更小，二者均属“小波纹”考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1014", "t": "单选题", "s": "对同一部位摄影，将管电压从60kV升至70kV，若要保持探测器接收的X线量不变，应", "o": {"A": "减少mAs", "B": "增加mAs", "C": "增大焦点", "D": "缩短焦片距", "E": "降低管电压"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-006", "kp": "曝光参数应用", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】X线输出量与管电压平方近似成正比，kV升高后X线输出显著增加，需相应减少mAs才能保持影像密度不变。【为什么错】B方向相反；C焦点影响空间分辨力，不影响密度；D缩短焦片距会增大探测器照射量，方向不对；E题干已设定升高。", "tr": "“kV升高→mAs必须下降”是经典技术换算思路，高kV技术（胸片120～150kV）配低mAs。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1015", "t": "单选题", "s": "床旁（移动式）X线机多采用", "o": {"A": "小型固定阳极X线管、单相电源，便于移动", "B": "大型旋转阳极X线管、三相电源", "C": "高频大功率球管", "D": "双X线管结构", "E": "永磁式主磁体"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MOB-001", "kp": "移动X线机", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (11)移动X线机", "ex": "【为什么对】移动式X线机要求体积小、重量轻、可灵活推送，故多采用小型固定阳极X线管与单相（220V）电源，功率较低。【为什么错】B、C高功率大体积设备不便移动；D移动机通常为单球管；E永磁体是MRI主磁体类型，与X线机无关。", "tr": "移动X线机功率小、X线质较软，床旁摄影需适当调整曝光条件。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1016", "t": "单选题", "s": "CR系统中成像板（IP）感光层采用的光激励荧光体是", "o": {"A": "氟卤化钡∶铕（BaFX:Eu²⁺）", "B": "非晶硒", "C": "碘化铯", "D": "锗酸铋", "E": "钨酸钙"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CR-001", "kp": "CR基本结构及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】IP感光层为氟卤化钡∶铕光激励荧光体，X线照射时Eu²⁺吸收能量形成潜影，激光激励时释放荧光。【为什么错】B非晶硒为直接转换DR材料；C碘化铯为间接转换DR闪烁体；D锗酸铋为PET探测器材料；E钨酸钙为老式增感屏材料。", "tr": "“光激励荧光体”是CR核心，与DR闪烁体的光电转换机制不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1017", "t": "单选题", "s": "CR成像过程中，IP经X线照射后再用激光扫描读取，所利用的物理现象是", "o": {"A": "光激励发光（PSL）", "B": "光电效应", "C": "康普顿效应", "D": "热释光", "E": "荧光猝灭"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CR-002", "kp": "CR基本结构及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】激光激发IP中存储潜影的荧光体，使其释放与X线剂量成正比的可见光，即光激励发光，经光电倍增管转为电信号。【为什么错】B、C为X线与物质相互作用方式；D热释光用于剂量测量（TLD）；E荧光猝灭是发光效率降低的现象。", "tr": "CR是“激光读出潜影”，DR是“直接转电信号”，读出机制完全不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1018", "t": "单选题", "s": "CR成像板（IP）读取图像后可再次使用，其残余潜影通过下列哪种方式清除", "o": {"A": "强光照射擦除", "B": "热水冲洗", "C": "化学定影", "D": "低温冷藏", "E": "高压放电"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CR-003", "kp": "CR基本结构及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】IP读取后经强光（紫外/可见光）充分照射，将残余潜影擦除，即可重复使用。【为什么错】B、C为湿式胶片冲洗工艺；D冷藏无擦除作用；E高压放电会损坏IP。", "tr": "IP可重复使用数千次，但需防潮、防划伤并定期校准。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1019", "t": "单选题", "s": "非晶硅（a-Si）平板探测器属于", "o": {"A": "间接转换型DR探测器", "B": "直接转换型DR探测器", "C": "CR成像板", "D": "CT气体探测器", "E": "影像增强器"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-001", "kp": "DR探测器结构性能及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】非晶硅平板探测器需先由闪烁体（碘化铯）将X线转为可见光，再经非晶硅光电二极管转为电信号，故属间接转换。【为什么错】B直接转换用非晶硒；C CR用IP；D气体探测器用于早期CT；E影像增强器为老式透视/DSA部件。", "tr": "“非晶硅＝间接（有闪烁体）、非晶硒＝直接（无闪烁体）”要记牢。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1020", "t": "单选题", "s": "非晶硒（a-Se）直接转换DR探测器将X线直接转换为", "o": {"A": "电子-空穴对电信号", "B": "可见光", "C": "荧光", "D": "热能", "E": "声波"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-002", "kp": "DR探测器结构性能及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】非晶硒受X线照射后直接产生电子-空穴对，在偏置电场作用下形成电信号，无可见光中间环节。【为什么错】B可见光是间接转换的中间产物；C荧光为闪烁体发光；D热能非有效转换方式；E与声学无关。", "tr": "直接转换无光散射环节，空间分辨力与DQE（量子检出效率）较高。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1021", "t": "单选题", "s": "间接转换DR探测器采用柱状碘化铯（CsI）晶体作为闪烁体的主要目的是", "o": {"A": "引导可见光垂直传导，减少光扩散，提高分辨力", "B": "提高探测器耐压性能", "C": "降低X线探测下限", "D": "减少X线辐射剂量", "E": "便于散热"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-003", "kp": "DR探测器结构性能及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】柱状晶体结构像光纤一样引导可见光沿柱体向下传导，减少横向光扩散，使空间分辨力明显提高。【为什么错】B耐压与闪烁体材料无关；C灵敏度取决于材料对X线的吸收；D剂量降低是间接效应而非目的；E散热不是闪烁体功能。", "tr": "柱状碘化铯是间接转换DR维持高分辨力的关键结构设计。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1022", "t": "单选题", "s": "CT值的单位及水的CT值分别是", "o": {"A": "HU，0", "B": "HU，1000", "C": "CT，0", "D": "dB，-1000", "E": "mA，0"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-001", "kp": "CT基本成像原理", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (4)CT基本成像原理", "ex": "【为什么对】CT值以亨氏单位（HU）表示，规定水的CT值为0，空气为-1000，致密骨约+1000。【为什么错】B水应为0而非1000；C单位应为HU而非CT；D dB为分贝单位，空气为-1000；E mA是管电流单位。", "tr": "CT值公式为CT值＝1000×(μx-μ水)/μ水，记住“水0、空气-1000、骨+1000”三个锚点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1023", "t": "单选题", "s": "CT扫描中位于X线球管侧的前准直器（源准直器）的主要作用是", "o": {"A": "限定X线束宽度，决定层厚并减少散射线", "B": "滤除低能X线、硬化线束", "C": "探测X线强度", "D": "承载被检者", "E": "重建图像"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-002", "kp": "CT硬件结构", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】前准直器用于限定X线束的宽度与形状，决定扫描层厚并减少散射线照射。【为什么错】B硬化滤过由楔形滤过器完成；C探测X线是探测器与数据采集系统的任务；D承载患者是扫描床；E重建是计算机系统的功能。", "tr": "前准直器管“层厚与散射线”，楔形滤过器管“能谱硬化”，两者功能勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1024", "t": "单选题", "s": "目前多层螺旋CT普遍采用的探测器类型是", "o": {"A": "固体闪烁探测器（闪烁晶体＋光电二极管）", "B": "气体电离室探测器", "C": "影像增强器", "D": "非晶硒平板探测器", "E": "IP成像板"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-003", "kp": "CT硬件结构", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】固体探测器（如硫氧化钆GOS等闪烁晶体配光电二极管）灵敏度高、响应快，是现代CT主流探测器。【为什么错】B气体探测器（氙电离室）为早期CT所用；C影像增强器用于透视/DSA；D非晶硒用于DR直接转换；E IP是CR部件。", "tr": "CT探测器固体化、多层化是发展趋势，GOS是常用闪烁材料。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1025", "t": "单选题", "s": "螺旋CT实现X线球管向同一方向连续旋转扫描的关键技术是", "o": {"A": "滑环（电刷滑环）技术", "B": "磁悬浮机架技术", "C": "液态金属轴承技术", "D": "高压电缆直接供电", "E": "无线充电技术"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-004", "kp": "螺旋CT结构特点", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】滑环技术以环状电刷滑环替代缠绕的高压电缆，使球管可向同一方向连续旋转，为螺旋扫描提供基础。【为什么错】B磁悬浮机架是减摩技术之一，非连续旋转的关键；C液态金属轴承是球管轴承技术；D高压电缆直连会缠绕，无法连续旋转；E无无线充电供电方式。", "tr": "螺旋CT三要素：滑环、球管连续旋转、扫描床连续移动。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1026", "t": "单选题", "s": "单层螺旋CT扫描时，螺距（pitch）为1.5、准直层厚5mm，则机架旋转一圈扫描床移动的距离为", "o": {"A": "7.5mm", "B": "5.0mm", "C": "3.3mm", "D": "10.0mm", "E": "15.0mm"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-005", "kp": "螺旋CT结构特点", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】螺距＝床移动距离/准直宽度，故床移动距离＝1.5×5＝7.5mm。【为什么错】B为螺距1时的移动量；C为螺距小于1时的移动量（5/1.5≈3.3mm）；D、E与给定条件不对应。", "tr": "螺距公式“螺距＝每圈进床距离/准直宽度”，与“螺距＝床速×扫描时间/层厚”本质一致。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1027", "t": "单选题", "s": "DSA数字减影成像的基本原理是", "o": {"A": "造影图像减去蒙片（mask）图像", "B": "两张造影图像相减", "C": "能量相加", "D": "图像时间相加", "E": "图像锐化增强"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-001", "kp": "DSA成像原理", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】先采集无对比剂的蒙片，再采集含对比剂的造影图像，两者像素逐一相减，去除骨骼与软组织背景，仅保留血管影像。【为什么错】B减影必须在蒙片与造影图之间进行；C能量相加无减影意义；D时间相加不能消除背景；E锐化是图像后处理，非减影原理。", "tr": "“蒙片＋造影图→相减”是最基础的时间减影方式。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1028", "t": "单选题", "s": "DSA检查中应用最广泛的减影方式是", "o": {"A": "时间减影", "B": "能量减影", "C": "混合减影", "D": "空间减影", "E": "密度减影"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-002", "kp": "DSA成像原理", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】时间减影（mask方式）简便有效、设备要求低，是临床应用最广的减影方式。【为什么错】B能量减影需双能量X线，设备复杂；C混合减影为时间＋能量减影的结合；D空间减影需双X线管；E无“密度减影”标准术语。", "tr": "时间减影分为常规、脉冲、超脉冲、连续等模式，均属mask减影。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1029", "t": "单选题", "s": "临床上最常用、场强最高的MRI主磁体类型是", "o": {"A": "超导磁体", "B": "常导磁体", "C": "永磁体", "D": "电磁铁", "E": "混合磁体"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-001", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】超导磁体采用铌钛合金线圈，在液氦（约4.2K）低温下电阻为零，可产生高而稳定的磁场（1.5T、3T）。【为什么错】B常导磁体功耗大、场强低；C永磁体场强低（多小于0.5T）；D电磁铁为早期分类；E混合磁体非常规主流。", "tr": "超导磁体的关键：超导材料＋液氦低温环境，发生失超后磁场迅速消失。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1030", "t": "单选题", "s": "氢质子（¹H）的旋磁比γ约为", "o": {"A": "42.58MHz/T", "B": "10.7MHz/T", "C": "11.26MHz/T", "D": "63.87MHz/T", "E": "3.2MHz/T"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-002", "kp": "MR成像基本原理", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】氢质子的旋磁比约42.58MHz/T，拉莫尔频率f＝γ×B0。【为什么错】B、C为其他核素（如碳、磷）相关数值；D为1.5T场强下的拉莫尔频率（42.58×1.5≈63.87MHz）；E无对应意义。", "tr": "42.58是“每特斯拉”的进动频率，实际进动频率＝42.58×场强。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1031", "t": "单选题", "s": "MRI中梯度磁场的主要作用是", "o": {"A": "实现空间定位（选层、相位编码、频率编码）", "B": "产生主磁场", "C": "接收MR信号", "D": "发射射频脉冲", "E": "维持超导低温"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-003", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】三组梯度线圈在X、Y、Z方向叠加线性变化磁场，使不同位置质子进动频率不同，完成选层、相位编码与频率编码定位。【为什么错】B主磁场由主磁体产生；C信号由接收线圈接收；D射频激励由发射线圈完成；E低温维持与梯度无关。", "tr": "梯度磁场是“空间编码”工具，梯度场强与爬升率决定成像速度与最小FOV。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1032", "t": "单选题", "s": "关于组织T1弛豫的叙述，正确的是", "o": {"A": "脂肪T1短，T1加权像上呈高信号", "B": "脂肪T1长，T1加权像上呈低信号", "C": "水T1短，T1加权像上呈高信号", "D": "钙化T1长，呈高信号", "E": "T1弛豫时间与场强无关"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-004", "kp": "MR成像基本原理", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】脂肪分子运动频率接近拉莫尔频率，纵向弛豫快、T1短，T1加权像呈高信号。【为什么错】B将脂肪T1说反；C水的T1长，T1WI呈低信号；D钙化T1WI多呈低信号；E T1弛豫时间随场强升高而延长。", "tr": "“T1短＝亮（T1WI高信号）”，脂肪亮、水黑是T1WI的记忆口诀。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1033", "t": "多选题", "s": "下列属于X线管产生X线必备条件的是", "o": {"A": "灯丝加热发射电子", "B": "管壳内保持高度真空", "C": "阴极与阳极之间施加高压加速电子", "D": "用强磁场聚焦电子束", "E": "靶面材料为放射性物质"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-009", "kp": "X线管产生X线的过程", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (2)X线管产生X线的过程", "ex": "【为什么对】产生X线需具备：热阴极灯丝加热发射电子（A）、真空管壳保证电子自由飞行（B）、高压电场加速电子并轰击靶面（C）。【为什么错】D X线管采用聚焦罩静电聚焦，而非强磁场聚焦；E靶面须为原子序数高、熔点高的材料（如钨），放射性物质并不是必要条件。", "tr": "X线管聚焦用静电聚焦罩，与CRT用磁场聚焦不同，勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1034", "t": "多选题", "s": "旋转阳极X线管相对于固定阳极X线管的优点包括", "o": {"A": "散热面积大，可承受更大的瞬时功率", "B": "可在保持较小有效焦点的同时提高功率", "C": "适合连续快速曝光", "D": "无需高压供电", "E": "使用寿命无限长"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-010", "kp": "旋转阳极X线管", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (4)旋转阳极X线管", "ex": "【为什么对】旋转阳极使热量分布于整个靶盘，散热面积大、功率高（A），因而能在保持小有效焦点的情况下提供大功率（B），适应连续快速曝光（C）。【为什么错】D X线管必须高压供电才能加速电子；E任何X线管都有使用寿命（灯丝老化、靶面损伤），并非无限长。", "tr": "旋转阳极解决散热/功率问题，但X线管总体寿命仍然有限。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1035", "t": "多选题", "s": "X线管管套的主要作用包括", "o": {"A": "高压绝缘（防电击）", "B": "散热", "C": "防X线泄漏（辐射防护）", "D": "缩小焦点", "E": "调节管电压"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-011", "kp": "X线管管套", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (6)X线管管套", "ex": "【为什么对】管套内充绝缘油并带铅防护，承担高压绝缘防电击（A）、散热（B）、防X线泄漏（C）三大功能。【为什么错】D焦点由灯丝与聚焦罩决定，与管套无关；E管电压由高压发生器调节。", "tr": "管套内还有膨胀鼓、温度保护装置，但核心作用是绝缘、散热与辐射防护。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1036", "t": "多选题", "s": "X线管阳极靶面材料应具备的条件包括", "o": {"A": "原子序数高", "B": "熔点高", "C": "热传导性能好", "D": "蒸发率高", "E": "质地松软易加工"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-012", "kp": "X线管规格与特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】靶材需原子序数高以产生高强度X线（A）、熔点高以耐受电子轰击（B）、热传导性好以利散热（C）。【为什么错】D蒸发率高会导致钨丝与靶面损耗加快，是不利因素；E质地松软不耐高温轰击，不满足要求。", "tr": "钨是唯一同时满足A、B、C条件的常用靶材；蒸发率低是其另一优点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1037", "t": "多选题", "s": "医用X线高压发生器的主要组成部件包括", "o": {"A": "高压变压器", "B": "灯丝变压器", "C": "整流器", "D": "高压交换闸", "E": "影像增强器"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-007", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】高压发生器由高压变压器、灯丝变压器、整流器及高压交换闸（多球管切换）等组成。【为什么错】E影像增强器属于透视/DSA成像部件，不属于高压发生器。", "tr": "高压交换闸用于多球管X线机在多个X线管之间切换高压回路。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-1038", "t": "多选题", "s": "高压电缆的组成部分包括", "o": {"A": "金属芯线", "B": "绝缘层", "C": "金属屏蔽层", "D": "外层保护套", "E": "光电倍增管"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-008", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】高压电缆由内到外依次为芯线（A）、高压绝缘层（B）、金属屏蔽层（C）与外层保护套（D），屏蔽层接地防电击。【为什么错】E光电倍增管是CR读出等光学探测部件，与高压电缆无关。", "tr": "金属屏蔽层接地是防止电缆击穿伤人的关键结构。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-1039", "t": "多选题", "s": "CR系统动态范围（宽容度）大带来的临床意义包括", "o": {"A": "允许曝光条件有较大偏差仍能获得满意图像", "B": "可经图像后处理补偿曝光不足或过量", "C": "空间分辨力显著高于直接DR", "D": "成像速度显著快于DR", "E": "无需任何后处理即可直接诊断"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CR-004", "kp": "CR图像处理技术", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (3)CR图像处理技术", "ex": "【为什么对】CR动态范围宽，曝光过/不足在一定范围内可经后处理校正获得满意图像（A、B）。【为什么错】C CR空间分辨力一般低于直接DR；D CR需激光逐行扫描读出，成像速度慢于DR；E CR图像仍需窗宽窗位等后处理优化。", "tr": "“宽容度大→允许曝光误差”是CR重要优势，但空间分辨力与成像速度是其短板。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-1040", "t": "多选题", "s": "关于直接转换DR探测器（非晶硒）的特点，正确的是", "o": {"A": "X线直接转换为电信号，无可见光环节", "B": "无光散射，空间分辨力较高", "C": "量子检出效率（DQE）较高", "D": "必须使用碘化铯闪烁体", "E": "属间接转换方式"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-004", "kp": "DR探测器结构性能及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】非晶硒受X线照射直接产生电子-空穴对（A），无光散射环节、空间分辨力高（B），量子检出效率高（C）。【为什么错】D碘化铯是间接转换（非晶硅）的闪烁体，非晶硒无需闪烁体；E非晶硒属直接转换，而非间接转换。", "tr": "“直接转换用非晶硒、间接转换用非晶硅＋碘化铯”是最常考的对应关系。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-1041", "t": "多选题", "s": "CT扫描设备硬件结构的组成部分包括", "o": {"A": "X线球管与高压发生器", "B": "探测器与数据采集系统（DAS）", "C": "准直器与滤过器", "D": "扫描床与图像重建计算机", "E": "IP成像板"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-006", "kp": "CT硬件结构", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】CT硬件包括扫描架（球管、准直器、滤过器、探测器、DAS）、高压发生器、扫描床、计算机与操作台等（A、B、C、D）。【为什么错】E IP成像板是CR系统的部件，不属于CT。", "tr": "CT成像链“球管→准直器→滤过器→人体→探测器→DAS→重建”要整体记忆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1042", "t": "多选题", "s": "螺旋CT相对于非螺旋（步进式）CT的特点包括", "o": {"A": "球管连续旋转，扫描床连续移动", "B": "可进行任意位置的多平面重建", "C": "扫描速度快，利于动态与血管成像", "D": "必须使用双X线管", "E": "图像均为非容积数据"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-007", "kp": "螺旋CT结构特点", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】螺旋CT凭借滑环技术实现球管连续旋转与床连续移动（A），采集容积数据可任意重建（B），速度快利于CTA等（C）。【为什么错】D螺旋CT单球管即可实现，双源CT只是特殊类型；E螺旋CT获取的是容积数据，不是非容积数据。", "tr": "容积采集＋插值重建是螺旋CT与步进CT的本质区别。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1043", "t": "多选题", "s": "多层螺旋CT（MSCT）的主要优势包括", "o": {"A": "一次旋转可同时采集多层图像，扫描速度更快", "B": "Z轴覆盖范围大，可薄层扫描实现各向同性成像", "C": "可进行心脏等运动器官的快速采集", "D": "球管与探测器数量均较单层CT成倍增加", "E": "辐射剂量必然低于单层CT"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-008", "kp": "螺旋CT结构特点", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】MSCT探测器排数多，一次旋转多层采集、速度快（A），Z轴覆盖大、可薄层各向同性（B），利于心脏与动态成像（C）。【为什么错】D MSCT探测器排数增加，但球管通常仍为一个（双源CT除外）；E辐射剂量与扫描方案相关，MSCT未必低于单层CT，且剂量管理需主动控制。", "tr": "MSCT不等于必然低剂量，恰恰需要重视辐射剂量优化。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1044", "t": "多选题", "s": "DSA的减影方式包括", "o": {"A": "时间减影", "B": "能量减影", "C": "混合减影", "D": "密度减影", "E": "光谱减影"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-003", "kp": "DSA成像原理", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】DSA基本减影方式分为时间减影、能量减影与混合减影（时间＋能量）三类。【为什么错】D、E“密度减影”“光谱减影”并非DSA标准减影方式术语。", "tr": "混合减影＝时间减影＋能量减影结合，能更好地消除软组织与骨骼运动伪影。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-1045", "t": "多选题", "s": "DSA成像设备的主要组成部分包括", "o": {"A": "X线发生系统（球管、高压发生器）", "B": "平板探测器与电视系统", "C": "图像处理与存储计算机", "D": "高压注射器", "E": "超声探头"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-004", "kp": "DSA结构与功能", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】DSA设备由X线发生系统、平板探测器（或影像增强器）与电视系统、图像处理计算机及高压注射器组成。【为什么错】E超声探头属超声设备，不属于DSA。", "tr": "高压注射器是DSA实现对比剂快速恒速注入的重要配套设备。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1046", "t": "多选题", "s": "MRI主磁体的类型包括", "o": {"A": "超导磁体", "B": "常导磁体", "C": "永磁体", "D": "单极梯度磁体", "E": "射频聚焦磁体"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-005", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】MRI主磁体按产生方式分为超导磁体、常导磁体和永磁体三类。【为什么错】D梯度磁体是梯度系统的组成，不属主磁体；E射频聚焦磁体不是MRI标准部件。", "tr": "主磁体管“静磁场”，梯度线圈管“空间编码”，射频线圈管“激发与接收”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1047", "t": "多选题", "s": "MRI梯度系统在成像中的具体作用包括", "o": {"A": "实现选层", "B": "实现相位编码", "C": "实现频率编码", "D": "产生均匀主磁场", "E": "发射90°射频脉冲"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-006", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】梯度磁场沿三个方向线性变化，分别完成选层梯度（A）、相位编码梯度（B）和频率编码梯度（C）。【为什么错】D主磁场由主磁体产生；E 90°脉冲由射频发射系统产生。", "tr": "“选层、相位编码、频率编码”三梯度是MRI空间定位的核心，常考多选题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1048", "t": "多选题", "s": "MRI射频系统的组成部分包括", "o": {"A": "射频发射（激发）线圈", "B": "射频接收线圈", "C": "射频功率放大器", "D": "梯度放大器", "E": "液氦压缩机"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-007", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】射频系统包括射频发射线圈、接收线圈以及射频功率放大器等，负责发射射频脉冲激发质子和接收MR信号。【为什么错】D梯度放大器属于梯度系统；E液氦压缩机属于超导低温保障系统。", "tr": "射频系统管“激发与接收”，梯度系统管“空间编码”，低温系统管“超导冷却”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U03-1049", "t": "多选题", "s": "医用高压注射器可预先设定的参数包括", "o": {"A": "注射流速（ml/s）", "B": "对比剂总量", "C": "注射延迟时间", "D": "扫描床高度", "E": "窗宽窗位"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-001", "kp": "医用高压注射器", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (2)医用高压注射器", "ex": "【为什么对】高压注射器可设定流速、总量、延迟时间、压力上限及双期相方案等注射参数。【为什么错】D扫描床高度属CT设备运动控制；E窗宽窗位是图像显示参数，与注射器无关。", "tr": "双筒注射器一筒对比剂、一筒生理盐水，生理盐水用于冲管减少伪影。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U03-1050a", "t": "共用题干题", "s": "若患者心率72次/分且配合屏气欠佳，欲获得高质量的冠脉图像，下列设备与技术选择最合理的是", "o": {"A": "选择双源CT等高时间分辨力设备，配合心电门控采集", "B": "嘱患者浅快呼吸下完成扫描", "C": "降低管电压至70kV以下以缩短采集时间", "D": "放弃CTA改行有创DSA", "E": "增大螺距至3以加快扫描"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-009", "kp": "心脏CTA时间分辨力", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】冠脉CTA对时间分辨力要求高，双源CT等高时间分辨力设备配合心电门控（回顾性或前瞻性门控）可在较高心率下获得清晰冠脉图像。【为什么错】B心脏搏动不受呼吸控制，浅快呼吸不能解决心脏运动伪影；C降低kV主要影响对比噪声比，不能缩短采集时间；D DSA为有创检查，非首选初筛手段；E螺距过大降低Z轴分辨力，不利于细小冠脉显示。", "tr": "高心率冠脉成像的关键是时间分辨力与心电门控，而非单纯调整kV或螺距。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0301", "gs": "患者男，58岁，反复活动后胸闷、心前区压榨感3个月，疑诊冠状动脉粥样硬化性心脏病，拟行冠状动脉CTA检查。技师需根据设备条件与患者情况合理制定扫描方案。"}, {"id": "U03-1050b", "t": "共用题干题", "s": "扫描完成后，技师进行冠脉图像后处理，最常用于完整显示冠脉全程走行的重建方式是", "o": {"A": "曲面重组（CPR）", "B": "多平面重组（MPR）", "C": "最大密度投影（MIP）", "D": "表面遮盖显示（SSD）", "E": "仿真内镜（VE）"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-010", "kp": "CT图像后处理技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (2)软件结构", "ex": "【为什么对】曲面重组（CPR）可沿冠脉走行方向拉直血管，完整显示管腔与管壁全程，最适合冠脉评估。【为什么错】B MPR为直平面重组，单帧难以容纳全程弯曲的冠脉；C MIP适合显示高密度血管整体形态，但缺乏管壁细节与层次；D SSD仅显示表面轮廓，无管腔内部信息；E仿真内镜多用于管腔内部观，受阈值与狭窄影响大，非冠脉首选。", "tr": "冠脉狭窄评估常用CPR＋VR＋轴位综合分析，其中CPR是显示全程的关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0301", "gs": ""}, {"id": "U03-1050c", "t": "共用题干题", "s": "该患者检查前口服美托洛尔将心率降至58次/分，改用前瞻性心电门控采集，其主要优点是", "o": {"A": "辐射剂量较回顾性门控显著降低", "B": "无需控制心率即可完成", "C": "可获得任意心动周期的图像", "D": "时间分辨力必然高于双源CT", "E": "不受心律失常影响"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-011", "kp": "心电门控技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】前瞻性门控仅在特定心动时相（如舒张期）曝光，辐射剂量较全心动周期采集的回顾性门控显著降低。【为什么错】B正因心率需较低且稳定才适用前瞻性门控；C回顾性门控才能任意选择时相重组；D时间分辨力取决于设备硬件而非门控方式；E心律失常时前瞻性门控易采集失败，对心律要求更高。", "tr": "前瞻性门控低剂量但要求心率低且规则，回顾性门控剂量高但允许任意时相重组。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0301", "gs": ""}, {"id": "U03-1051a", "t": "共用题干题", "s": "鞍区增强扫描首选的磁体类型与序列组合是", "o": {"A": "高场强超导磁体（如3.0T）行T1WI增强扫描", "B": "低场永磁体行T2WI增强扫描", "C": "行T2WI非增强扫描", "D": "行DWI增强扫描", "E": "行FLAIR增强扫描"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-008", "kp": "MRI增强扫描方案", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】鞍区占位增强应选用高场强磁体行T1WI增强，钆对比剂缩短T1使强化组织在T1WI呈高信号。【为什么错】B低场磁体信噪比低，且增强观察必须用T1WI；C无对比剂无法评估血供；D DWI反映水分子扩散，不是增强序列；E FLAIR主要抑制脑脊液信号，非增强首选。", "tr": "MR增强必须用T1WI观察强化，对比剂为钆类顺磁性对比剂。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0302", "gs": "患者女，46岁，头痛伴视物模糊3个月，MRI平扫示鞍区占位，拟行鞍区MRI增强扫描进一步明确血供与强化特点。技师负责制定扫描方案。"}, {"id": "U03-1051b", "t": "共用题干题", "s": "检查前患者告知身上携带的银行卡疑似失效，最可能的原因是", "o": {"A": "主磁场对磁卡磁性介质产生破坏性磁化", "B": "射频脉冲烧毁磁卡", "C": "梯度磁场噪声干扰磁卡", "D": "液氦泄漏损伤磁卡", "E": "静电放电损伤磁卡"}, "d": "易", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-009", "kp": "MRI安全保障体系", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】MRI主磁场为强静磁场，含磁性介质的磁卡等物品进入强磁场会被磁化而损坏数据。【为什么错】B射频脉冲作用于人体质子，能量低且时间短，不会烧毁磁卡；C梯度场在扫描时快速变化，但破坏磁卡的是静磁场本身；D液氦泄漏与磁卡损坏无关；E静电非主要原因。", "tr": "检查前须去除一切铁磁性物品与磁卡，这是MRI安全制度的重点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0302", "gs": ""}, {"id": "U03-1051c", "t": "共用题干题", "s": "若增强扫描需抑制脂肪信号以突出病灶边缘强化，技师宜选用的技术是", "o": {"A": "脂肪抑制技术（如SPAIR、STIR或Dixon）", "B": "增加扫描层厚", "C": "增大扫描视野（FOV）", "D": "降低翻转角", "E": "关闭梯度磁场"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-010", "kp": "脂肪抑制技术", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】脂肪抑制序列（SPAIR、STIR、Dixon等）可抑制脂肪高信号，避免其掩盖或混淆病灶强化。【为什么错】B增加层厚降低空间分辨力，不能压脂；C增大FOV与脂肪抑制无关；D降低翻转角影响图像对比，而非脂肪抑制；E梯度磁场不可关闭，关闭后无法成像。", "tr": "脂肪抑制技术包括频率选择法（SPAIR/SPIR）、反转恢复法（STIR）与Dixon水脂分离等。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0302", "gs": ""}, {"id": "U03-1052a", "t": "共用题干题", "s": "全脑血管DSA检查中，对比剂应采用的注射方式是", "o": {"A": "高压注射器恒速注入，流速与总量按靶血管设定", "B": "手推缓慢注入", "C": "静脉滴注", "D": "口服对比剂", "E": "皮下注射"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-005", "kp": "DSA高压注射技术", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】脑血管DSA需在规定时间内快速、恒速注入足量对比剂以维持血管内浓度，必须使用高压注射器。【为什么错】B手推无法保证恒速与流量；C静脉滴注流速过慢无法显影；D口服适用于消化道造影；E皮下注射无法进入血循环。", "tr": "颈内动脉、椎动脉等不同靶血管的流速与总量参数不同，需个体化设定。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0303", "gs": "患者男，62岁，突发右侧肢体无力伴言语不清2小时，临床疑诊急性脑梗死并需排除脑动脉瘤破裂出血，拟行全脑血管DSA检查。技师需制定合理的成像方案。"}, {"id": "U03-1052b", "t": "共用题干题", "s": "检查中患者轻微头部移动导致减影图像出现运动伪影，技师首选的处理方法是", "o": {"A": "采用像素移位（重配准）技术校正", "B": "增加对比剂用量", "C": "更换X线管", "D": "无限提高采集帧率", "E": "放弃减影直接透视"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-006", "kp": "DSA运动伪影校正", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】像素移位技术通过移动蒙片或造影图使运动区域重新对齐，可有效减轻减影运动伪影。【为什么错】B增加对比剂不能消除运动伪影；C球管与伪影成因无关；D提高帧率增加剂量且不能校正已采集图像的运动错位；E放弃减影则失去DSA血管减影的意义。", "tr": "像素移位仅对小范围平移有效，明显运动需重新采集或改用混合减影。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0303", "gs": ""}, {"id": "U03-1053a", "t": "共用题干题", "s": "床旁胸部摄影技师宜优先选择的探测器类型是", "o": {"A": "无线平板探测器（无线DR），便于灵活摆放并即时成像", "B": "有线探测器固定于摄影机架", "C": "CR暗盒（IP板）回科室后激光读取", "D": "影像增强器", "E": "湿式胶片暗盒"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-005", "kp": "床旁DR摄影技术", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (4)DR基本结构及特性", "ex": "【为什么对】床旁摄影空间受限、患者移动不便，无线平板探测器可置于患者身下快速成像，即时确认图像质量。【为什么错】B有线探测器受线缆限制不便床旁使用；C CR需将IP送回科室读取，无法即时质控；D影像增强器用于透视；E湿式胶片需化学处理，无法即时显示。", "tr": "无线DR＋移动X线机是ICU床旁摄影的现代主流配置。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0304", "gs": "患者男，76岁，ICU重症肺炎，行气管插管机械通气，需床旁胸部DR复查肺部感染及管路位置。技师携带移动DR至床旁检查。"}, {"id": "U03-1053b", "t": "共用题干题", "s": "该患者屏气配合差、呼吸急促，为减少运动模糊，技师应采用的摄影技术是", "o": {"A": "高千伏、短时间曝光，嘱患者浅呼吸", "B": "低千伏、长时间曝光", "C": "增大mAs延长曝光时间", "D": "取消滤线栅同时延长曝光", "E": "降低管电压至40kV"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-006", "kp": "胸部DR摄影技术", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (4)DR基本结构及特性", "ex": "【为什么对】呼吸运动模糊需缩短曝光时间解决，高kV配合低mAs可实现短时曝光，减少运动伪影。【为什么错】B长时间曝光加重运动模糊；C延长曝光时间更差；D取消滤线栅会增大散射线，且延长曝光方向不对；E低kV穿透力不足，需延长曝光时间。", "tr": "“呼吸控制差→高kV、短时间、适当增加mA”是胸部摄影减少运动伪影的原则。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0304", "gs": ""}, {"id": "U03-1054", "t": "案例分析题", "s": "患者男，45岁，体检发现肝右叶占位2周，拟行腹部增强CT明确病灶血供特点，设备为64层螺旋CT。技师需制定对比剂注射与扫描方案。下列扫描方案中最合理的是", "o": {"A": "双筒高压注射器注入对比剂（碘浓度300～370mgI/ml）80～100ml，流速3～4ml/s，行动脉期与门静脉期双期扫描", "B": "单筒注射对比剂后延迟10分钟单期扫描", "C": "以1ml/s低速注射后扫描一次完成", "D": "不用对比剂直接行平扫", "E": "对比剂经口服途径引入后扫描"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-012", "kp": "腹部CT增强方案", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (4)CT基本成像原理", "ex": "【为什么对】腹部占位定性需动脉期与门静脉期双期动态增强，双筒注射器保证团注后用生理盐水冲管，流速3～4ml/s可获得良好强化。【为什么错】B单期延迟扫描无法观察动脉期血供；C流速过慢难以形成对比剂团注；D平扫无法评估血供与强化特征；E口服对比剂不进入血循环，不能增强实质与血管。", "tr": "肝脏增强的动脉期、门静脉期、延迟期“三期时相”选择是经典考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1055", "t": "案例分析题", "s": "患者男，50岁，突发胸背部撕裂样疼痛伴双侧血压不对称2小时，疑诊主动脉夹层，急诊行主动脉CTA。患者心率95次/分且躁动不安。技师应优先采取的成像策略是", "o": {"A": "采用双源CT或高时间分辨力设备行胸腹主动脉CTA，必要时配合心电门控并稳定患者", "B": "常规行腹部CT平扫", "C": "嘱患者剧烈咳嗽后重新扫描", "D": "降低对比剂浓度至200mgI/ml以下", "E": "停止检查改用消化道造影"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-013", "kp": "主动脉CTA成像技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】主动脉夹层CTA需大范围快速扫描捕捉对比剂首过，高时间分辨力CT配合心电门控可减少主动脉搏动伪影，同时需稳定患者减少运动伪影。【为什么错】B平扫无法显示内膜片及真假腔强化特征；C咳嗽不能解决时间分辨力问题；D对比剂浓度过低影响血管显影；E消化道造影不能诊断主动脉夹层。", "tr": "主动脉CTA关键在“快速、大范围、团注追踪”，内膜片显示需清晰对比。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1056", "t": "案例分析题", "s": "患儿男，5岁，头部外伤后头痛、呕吐3小时，拟行头颅CT排除颅内出血，患儿哭闹不配合。关于该患儿CT检查的技术决策，正确的是", "o": {"A": "采用低剂量方案（降低mAs并优化kV），必要时镇静后固定患儿再扫描", "B": "为获得清晰图像将mAs增至成人剂量", "C": "嘱患儿自行屏气配合扫描", "D": "放弃CT改行有创脑血管造影", "E": "加用滤线栅提高曝光量"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-014", "kp": "儿童低剂量CT技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (4)CT基本成像原理", "ex": "【为什么对】儿童对辐射更敏感，头颅CT应遵循低剂量原则降低mAs，并通过镇静与固定减少运动伪影。【为什么错】B成人剂量违反防护最优化原则；C幼儿无法配合屏气；D有创血管造影辐射高、风险大，不适合颅脑外伤初筛；E滤线栅会增加剂量，与低剂量原则相反。", "tr": "儿童CT应遵循“尽可能低”原则，调整kV/mAs并优化扫描方案。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1057", "t": "案例分析题", "s": "患者女，68岁，突发右侧肢体无力、言语不清3小时，临床疑诊急性缺血性脑卒中，行急诊头颅MRI。技师为确诊急性梗死灶，应优先选择的序列是", "o": {"A": "弥散加权成像（DWI）", "B": "T1加权平扫", "C": "腹部冠状位T2加权", "D": "乳腺压脂序列", "E": "腰椎矢状位T2加权"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-011", "kp": "DWI临床应用", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】急性脑梗死细胞毒性水肿致水分子扩散受限，DWI数小时内即呈明显高信号，是诊断急性梗死的敏感序列。【为什么错】B T1WI早期梗死变化不明显；C、E为其他部位的无关序列；D乳腺压脂与脑梗死诊断无关。", "tr": "DWI高信号＋ADC低信号是急性梗死“弥散受限”的标志组合。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1058", "t": "案例分析题", "s": "患者女，52岁，超声发现肝右叶占位，拟行肝脏MRI平扫加动态增强进一步定性。关于肝脏动态增强MRI的技术要点，正确的是", "o": {"A": "静脉注射钆类对比剂，常规行T1WI多期动态增强（动脉期、门静脉期、延迟期）", "B": "使用硫酸钡对比剂行T1WI增强", "C": "只用T2WI观察病灶强化", "D": "仅行平扫，无需增强", "E": "对比剂口服后立即扫描"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-012", "kp": "肝脏动态增强MRI", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】肝脏占位定性需静脉注射钆类顺磁性对比剂行T1WI多期动态增强，观察各期强化模式。【为什么错】B硫酸钡为胃肠道X线对比剂，无MR增强作用；C强化必须在T1WI观察；D平扫无法评估血供与强化；E口服对比剂不进入肝实质血循环。", "tr": "肝脏动态增强强调时相准确性，动脉期强化模式对肝癌诊断至关重要。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1059", "t": "案例分析题", "s": "患者男，30岁，篮球运动后右肩疼痛伴活动受限1周，临床疑肩袖损伤，拟行肩关节MRI。技师应采用的扫描策略是", "o": {"A": "使用专用肩关节表面线圈，行斜冠状位、轴位及斜矢状位薄层扫描，并加质子密度加权压脂序列", "B": "用体部线圈行轴位单层扫描", "C": "仅行矢状位T2加权扫描", "D": "不加线圈直接行大FOV扫描", "E": "用CT代替MRI完成检查"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-013", "kp": "关节MRI成像技术", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】肩关节结构细小，需专用表面线圈提高信噪比，采用多平面薄层扫描，压脂质子密度序列利于显示肌腱损伤。【为什么错】B体部线圈信噪比低、分辨率不足；C单平面扫描易遗漏病灶；D大FOV降低空间分辨力；E CT软组织对比差，无法显示肌腱细微损伤。", "tr": "专用表面线圈是关节MRI提高图像质量的关键硬件。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1060", "t": "案例分析题", "s": "患者男，55岁，心电图提示前壁心肌缺血，拟行选择性冠状动脉DSA造影明确狭窄部位。关于冠脉造影的技术决策，正确的是", "o": {"A": "经股动脉或桡动脉穿刺插管，高压注射器按冠脉流量设定流速，多体位投照并配合减影", "B": "直接静脉注射大剂量对比剂", "C": "仅行正位单一体位投照", "D": "口服对比剂后摄片", "E": "不注射对比剂直接采集"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-007", "kp": "冠脉DSA成像技术", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】冠脉造影需选择性插管至冠脉开口，以合适流速注入对比剂，多体位投照显示各血管段。【为什么错】B静脉注射对比剂被稀释，无法选择性显示冠脉；C单一体位无法全面显示弯曲分支；D口服对比剂不进入冠脉；E无对比剂无法显示管腔。", "tr": "Seldinger穿刺技术＋选择性造影＋多体位投照是冠脉DSA的三要素。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1061", "t": "案例分析题", "s": "患者女，48岁，突发剧烈头痛伴颈项强直，CT示蛛网膜下腔出血，疑颅内动脉瘤，拟行全脑血管DSA。为明确动脉瘤形态、瘤颈与载瘤动脉的关系，技师应优先执行的采集方式是", "o": {"A": "3D旋转DSA（旋转采集后三维重建）", "B": "静态蒙片减影单帧采集", "C": "消化道造影", "D": "腹部平片", "E": "乳腺X线摄影"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-008", "kp": "3D旋转DSA技术", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】3D旋转DSA通过旋转机架多角度采集并三维重建，可立体显示动脉瘤形态、瘤颈与载瘤动脉关系，指导介入治疗。【为什么错】B单帧静态减影无法三维评估；C、D、E均与脑血管动脉瘤检查无关。", "tr": "颅内动脉瘤术前评估中，3D旋转DSA是提供解剖细节的金标准技术。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1062", "t": "案例分析题", "s": "患者女，80岁，咳嗽、发热3天，拟行胸部正位DR检查。患者体弱、呼吸急促且不能站立。技师宜采取的摄影方式是", "o": {"A": "坐位或卧位前后位摄影，采用高千伏、短时间曝光并适当调整焦片距", "B": "标准站立后前位，嘱其深吸气后屏气", "C": "增大mAs延长曝光时间", "D": "使用乳腺摄影的低kV参数", "E": "放弃X线改用超声检查"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-007", "kp": "卧位胸部摄影技术", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (4)DR基本结构及特性", "ex": "【为什么对】体弱不能站立者取坐位或卧位前后位，为减少呼吸运动模糊采用高千伏、短时间曝光。【为什么错】B患者无法站立及屏气配合；C延长曝光加重运动模糊；D乳腺低kV参数穿透力不足，不适用胸部；E超声对肺部感染评价有限，不能替代X线。", "tr": "卧位前后位摄片心影略有放大，为体位相关的正常变异，判读时需注意。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-1063", "t": "案例分析题", "s": "患者女，45岁，发现左乳肿块1周，拟行乳腺X线摄影（钼靶）诊断。关于乳腺X线摄影的技术决策，正确的是", "o": {"A": "采用钼靶X线管、小焦点、低管电压（约22～35kV），以头尾位（CC）与内外斜位（MLO）为标准体位", "B": "用普通钨靶球管行高千伏摄影", "C": "只拍摄一个投照位置", "D": "患者站立即可，无需压迫乳房", "E": "用CT完全替代钼靶检查"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-013", "kp": "乳腺X线摄影技术", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (13)乳腺X线机", "ex": "【为什么对】乳腺摄影需软X线（钼靶）获得高软组织对比，小焦点提高分辨力，CC与MLO是标准双体位。【为什么错】B钨靶产生硬X线，软组织对比差；C单一体位易漏诊；D压迫是乳腺摄影规范操作，可减少散射线、均匀腺体厚度；E CT辐射剂量高且非乳腺筛查首选。", "tr": "乳腺X线摄影“钼靶、低kV、双体位、压迫”四个要点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U03-1064", "t": "案例分析题", "s": "某X线机连续完成多例高mAs摄影后，设备提示“阳极过热，暂停曝光”，而候诊区仍有患者排队。正确的技术处置是", "o": {"A": "合理安排曝光间隔，待阳极充分冷却后再继续曝光", "B": "强行连续曝光完成全部检查", "C": "提高kV、降低mAs并缩短间隔立即再摄", "D": "关闭散热风扇以减少能耗", "E": "随意调整灯丝电压继续曝光"}, "d": "中", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-014", "kp": "X线管热容量管理", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】X线管阳极热容量有限，过热保护是防止靶面熔化损坏球管，技师应合理安排曝光间隔使阳极充分散热。【为什么错】B强行曝光会损坏X线管；C缩短间隔加剧过热；D关闭散热风扇加重过热；E灯丝电压与过热保护无关，随意调整会损坏设备。", "tr": "阳极热容量以热单位（HU）计，合理安排连续曝光间隔是设备维护的重要措施。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-9001", "t": "单选题", "s": "医用诊断级显示器为保证不同设备间灰阶显示一致，应定期按以下哪项标准进行校准", "o": {"A": "sRGB 色彩空间", "B": "DICOM 灰度标准显示函数（GSDF）", "C": "Adobe RGB 色彩空间", "D": "CIE LAB 均匀色彩空间", "E": "Rec.709 电视标准"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-009", "kp": "医用显示器校准标准", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (3)医用显示器", "ex": "【为什么对】B正确——医学影像显示须遵循 DICOM 第14部分定义的灰度标准显示函数（GSDF），将输入像素值映射到符合人眼对比度觉察特性的光强度，保证同一影像在不同显示器上呈现一致的灰阶与诊断信息。【为什么错】A、C为通用色彩空间，不针对医学灰阶一致性；D是色彩差异度量空间，非显示校准曲线；E是视频色彩标准，不适用于诊断显示器校准。", "tr": "易与 sRGB 混淆；医用显示器校准核心是 GSDF 而非普通显示器的 sRGB。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-9002", "t": "单选题", "s": "用于放射科诊断阅片的医用显示器，其空间分辨率通常不低于", "o": {"A": "0.5 百万像素（0.5 MP）", "B": "1 百万像素（1 MP）", "C": "2 百万像素（2 MP）", "D": "8 百万像素（8 MP）", "E": "16 百万像素（16 MP）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-010", "kp": "诊断级显示器分辨率", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (3)医用显示器", "ex": "【为什么对】C正确——诊断级医用显示器一般要求 2 MP（约 1600×1200）及以上，乳腺、断层融合等精细阅片常用 3 MP、5 MP 甚至更高，以满足微小结构显示与灰阶分辨需求。【为什么错】A、B分辨率过低，多用于临床浏览或工作站导航，不宜作为诊断主力；D、E虽可达更高分辨，但\"通常不低于\"的起步门槛是 2 MP。", "tr": "不要把\"临床浏览级\"与\"诊断级\"分辨率混淆，诊断级起步多为 2 MP。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-9003", "t": "单选题", "s": "关于医用干式激光打印机与热敏打印机的成像原理，下列表述正确的是", "o": {"A": "热敏打印机需经激光扫描与显影定影过程", "B": "激光打印机通过热敏打印头直接加热成像介质显影", "C": "激光打印机利用激光扫描潜影、经显影定影形成影像；热敏打印机由热敏头直接加热成像介质显影，无需显影剂", "D": "两者均必须依赖银盐胶片才能成像", "E": "热敏打印的分辨率显著低于激光打印且不可用于诊断"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-011", "kp": "激光与热敏打印原理区别", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (1)医用打印机", "ex": "【为什么对】C正确——干式激光打印机以激光束扫描感光鼓形成静电潜影，再经显影、热定影将碳粉或染色剂固定在介质上；热敏打印机则由加热打印头直接对热敏介质加热显影，无需显影剂与定影组件，结构更简单。【为什么错】A、B将两者原理互换，均错；D两者均可使用专用干式介质，并非必须银盐胶片；E热敏打印也可达到诊断级分辨率，盲目贬低其用途错误。", "tr": "易把\"激光扫描显影\"与\"热敏头直接加热\"张冠李戴。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-9004", "t": "单选题", "s": "医用双筒高压注射器设置两个针筒的主要目的是", "o": {"A": "同时注射两种不同对比剂以提高浓度", "B": "一筒装载对比剂、另一筒装载生理盐水用于注射后冲刷，优化团注形态并减少残留", "C": "分别用于动脉期与静脉期以省去人工换筒", "D": "一筒装对比剂、一筒装急救药液以备过敏抢救", "E": "双筒交替工作以缩短扫描间隔时间"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-012", "kp": "高压注射器双筒设计", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (2)医用高压注射器", "ex": "【为什么对】B正确——双筒设计一筒装对比剂、另一筒装生理盐水，团注对比剂后以盐水冲刷静脉与管路内残留对比剂，可提高上腔静脉及右心腔内对比剂浓度、减少高浓度伪影，并改善团注曲线形态，是动态增强与CTA的常规配置。【为什么错】A高浓度叠加并非常规目的；C动脉/静脉期由扫描时相决定而非双筒分别装载；D急救药液不应与对比剂注射器混用；E双筒并非为缩短扫描间隔设计。", "tr": "双筒\"冲刷\"目的易被误记为\"双对比剂\"或\"急救\"。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-9201", "t": "单选题", "s": "影像存储与传输系统（PACS）的核心功能不包括", "o": {"A": "图像采集与存储", "B": "图像传输与显示", "C": "图像后处理", "D": "替代医师诊断决策", "E": "工作流程管理"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-9201", "kp": "PACS功能", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备", "ex": "【为什么对】PACS 负责采集、存储、传输、显示、后处理与流程管理；诊断决策仍由医师完成。\n【为什么错】PACS 不替代诊断。", "tr": "PACS不替代诊断。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U03-9202", "t": "单选题", "s": "关于 RIS（放射信息系统），主要管理的是", "o": {"A": "设备硬件维修", "B": "检查预约、登记与报告流程", "C": "图像重建算法", "D": "患者缴费", "E": "网络路由"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-9202", "kp": "RIS功能", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备", "ex": "【为什么对】RIS 管理放射科工作流程：预约、登记、分诊、报告与统计。\n【为什么错】硬件维修与重建算法非 RIS 核心。", "tr": "RIS管流程而非硬件。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0101", "t": "单选题", "s": "下列血管内用碘对比剂中，属于非离子型二聚体（等渗对比剂）的是", "o": {"A": "碘海醇（iohexol）", "B": "碘普罗胺（iopromide）", "C": "碘克沙醇（iodixanol）", "D": "泛影葡胺（diatrizoate meglumine）", "E": "碘佛醇（ioversol）"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-001", "kp": "碘对比剂的分类与代表药物", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】碘克沙醇由两个三碘苯环通过桥链连接而成，分子中含6个碘原子且在水溶液中不解离，故每个粒子携带6个碘，渗透压约290 mOsm/(kg·H₂O)，与人体血浆基本相等，是目前临床唯一广泛使用的等渗碘对比剂。【为什么错】A、B、E 碘海醇、碘普罗胺、碘佛醇均为非离子型单体，分子含3个碘、不解离，渗透压约为血浆的两倍（在300~350 mgI/ml 浓度下约600~800 mOsm/kg），属次高渗（低渗）对比剂。D 泛影葡胺为离子型单体，在水中解离为含3个碘的阴离子与葡甲胺阳离子，渗透压高达1500~2100 mOsm/kg，属高渗对比剂，血管内应用已基本被淘汰。", "tr": "\"低渗\"是相对高渗离子型而言的历史称谓，实际仍为血浆的两倍左右，规范表述应为\"次高渗\"；只有非离子型二聚体才真正等渗。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0102", "t": "单选题", "s": "碘对比剂溶液中\"碘原子数与溶质粒子数之比\"（碘／粒子比）是判断其渗透压高低的结构性指标。下列关于四类碘对比剂碘／粒子比的组合，正确的是", "o": {"A": "离子型单体3∶2、非离子型单体3∶1、离子型二聚体6∶2、非离子型二聚体6∶1", "B": "离子型单体3∶1、非离子型单体3∶2、离子型二聚体6∶1、非离子型二聚体6∶2", "C": "离子型单体3∶2、非离子型单体6∶1、离子型二聚体3∶1、非离子型二聚体6∶2", "D": "离子型单体6∶2、非离子型单体3∶2、离子型二聚体3∶1、非离子型二聚体6∶1", "E": "四类对比剂的碘／粒子比均为3∶1，渗透压差异仅由浓度决定"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-002", "kp": "碘／粒子比与渗透压的关系", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】渗透压取决于单位体积溶液中的粒子数目，而成像效果取决于碘原子数目，因此碘／粒子比越高，达到同样碘浓度所需的粒子越少、渗透压越低。离子型单体一个三碘苯环解离为阴、阳两个粒子，故为3∶2；非离子型单体不解离，为3∶1；离子型二聚体（如碘克沙酸）含6碘但解离为2个粒子，等效为3∶1；非离子型二聚体含6碘且不解离，为6∶1，渗透压最低，可达等渗。【为什么错】B 把离子型单体与非离子型单体的比值对调，并把离子型二聚体误作不解离。C、D 均为各项数值的错误搭配，未遵循\"是否解离\"与\"苯环数目\"两条判定线索。E 忽略了分子结构对粒子数的决定作用，若比值相同则不同类型对比剂在同浓度下渗透压应相等，与临床事实（泛影葡胺与碘克沙醇渗透压相差数倍）明显矛盾。", "tr": "解题只需两步：数苯环得碘数（单体3、二聚体6），判断是否解离定粒子数（离子型2、非离子型1）；离子型二聚体与非离子型单体等效为3∶1，是最易混淆的一对。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0103", "t": "单选题", "s": "在高流率注射的 CTA 检查中，对比剂的黏度直接影响注射压力与团注质量。关于碘对比剂黏度，正确的表述是", "o": {"A": "黏度只与渗透压有关，与温度无关", "B": "黏度随碘浓度升高而升高、随温度降低而升高；同等碘浓度下二聚体的黏度高于单体；将对比剂加温至37 ℃ 可明显降低黏度，便于高流率注射并减少注射压力", "C": "把对比剂加温至37 ℃ 的主要目的是降低其渗透压", "D": "同等碘浓度下，非离子型二聚体的黏度低于非离子型单体", "E": "黏度升高有利于降低注射系统所需的推注压力"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-003", "kp": "碘对比剂的黏度及其临床意义", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】黏度由分子体积、分子间作用力与溶液浓度共同决定。碘浓度越高、分子越大（二聚体分子量约为单体的两倍），黏度越高；温度升高使分子热运动加剧、分子间作用力减弱，黏度显著下降，通常从室温加温到37 ℃ 可使黏度下降约三分之一至一半。这既降低了注射器与留置针的压力负荷，也使团注更紧凑，是 CTA 高流率注射前必须预温的原因。【为什么错】A 温度是影响黏度最重要的可控因素，且黏度与渗透压是两个独立的理化参数（等渗的二聚体黏度反而最高）。C 加温对渗透压的影响可以忽略，其目的是降黏度、减少注射阻力与患者不适。D 与事实相反：非离子型二聚体虽然渗透压低，但分子大、黏度高，这正是它的主要缺点。E 逻辑颠倒：黏度越高，在相同流率下所需的推注压力越大，导管与静脉承受的压力也越高。", "tr": "等渗对比剂\"低渗透压、高黏度\"，次高渗单体\"较高渗透压、较低黏度\"，二者各有取舍；把\"等渗\"直接等同于\"更安全、更好推\"是常见误判。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0104", "t": "多选题", "s": "关于碘对比剂的理化特性与体内过程，下列表述正确的有", "o": {"A": "对比剂的X线衰减能力主要来自碘的高原子序数（Z＝53）及其 K 吸收缘（33.2 keV）附近显著增强的光电吸收", "B": "分子的亲水性好、亲脂性低，可减少与生物膜及血浆蛋白的相互作用，从而降低化学毒性", "C": "分子带电荷（离子型）会干扰细胞膜电位并影响血脑屏障，是离子型对比剂神经毒性相对较高的原因之一", "D": "渗透压越高越有利于减轻血管内皮损伤并保护红细胞的可变形性", "E": "血管内注入的碘对比剂主要经肝胆系统代谢后随胆汁排出体外"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-004", "kp": "碘对比剂的理化特性与毒性基础", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】A 光电效应的发生概率与原子序数的三次方成正比，并在 K 吸收缘处出现突跃，碘的 K 缘为33.2 keV，恰位于诊断能区内，这正是选碘作为造影元素的物理依据，也解释了为何低管电压（70~80 kV）时碘的 CT 值更高。B 现代非离子型对比剂在三碘苯环上引入大量羟基以增加亲水性、屏蔽苯环的疏水面，从而减少与蛋白和细胞膜的结合，化学毒性显著降低。C 离子型对比剂解离出的离子改变细胞外液的电解质环境与膜电位，是抽搐、意识改变等神经毒性反应相对多见的机制之一，故椎管内造影绝对禁用离子型对比剂。【为什么错】D 完全相反：高渗透压会使红细胞脱水、变形性下降甚至皱缩，损伤血管内皮、引起血管扩张与疼痛、加重肾小管损伤，正是高渗离子型对比剂被淘汰的核心原因。E 血管内碘对比剂几乎不参与代谢，以原形经肾小球滤过排出，肾小管基本不重吸收也不分泌；只有极少量在肾功能衰竭时经肝胆与肠道代偿排泄。", "tr": "\"碘对比剂经肾排泄、几乎不代谢\"是理解其肾毒性与二甲双胍相互作用的前提；把它误记为肝代谢会导致后续一系列临床判断失误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0105", "t": "单选题", "s": "按发生时间对碘对比剂不良反应进行分类，下列划分正确的是", "o": {"A": "急性反应指注射后24 h 内发生者", "B": "迟发反应指注射后1周至1个月内发生者", "C": "晚迟发反应指注射后24~72 h 内发生者", "D": "急性反应指注射后1 h 内发生；迟发反应指1 h 至1周内发生；晚迟发反应指1周以后发生，多表现为甲状腺功能异常等", "E": "急性反应特指过敏性休克，其他表现均归入迟发反应"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-005", "kp": "碘对比剂不良反应的时间分类", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】按发生时间划分为三类：急性反应发生于注射后1 h 内，多为类过敏样反应，是抢救的重点，故规定注射后留观至少30 min；迟发反应发生于1 h 至1周内，以皮肤反应（斑丘疹、瘙痒、迟发性荨麻疹）最常见，多为T细胞介导；晚迟发反应发生于1周之后，典型代表是碘诱导的甲状腺功能亢进或减退，也包括部分肾功能改变。【为什么错】A 把急性反应的时间窗放宽到24 h，会掩盖\"注射后30 min 是抢救黄金期\"这一临床原则。B 1周至1个月的划分与国际通行标准不符，1周之后即属晚迟发。C 24~72 h 仍在1周之内，属迟发反应范畴。E 急性反应涵盖从恶心、荨麻疹到休克的全部严重程度，把它窄化为过敏性休克会遗漏大量需要观察和处理的轻中度反应。", "tr": "记住三个时间节点\"1 h、1周\"即可分清三类；留观30 min 针对的是急性反应，出院前应告知患者迟发皮疹的可能并留下联系方式。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0106", "t": "单选题", "s": "碘对比剂的急性不良反应按发生机制可分为类过敏样（特异质）反应与器官毒性（非特异质）反应两类。关于这一分型，正确的表述是", "o": {"A": "类过敏样反应与对比剂的剂量、浓度和注射速率无明确相关性，其机制涉及肥大细胞与嗜碱粒细胞的非 IgE 介导性组胺释放及补体激活，临床表现类似Ⅰ型变态反应", "B": "类过敏样反应的严重程度与所用对比剂剂量呈明确的正相关", "C": "器官毒性反应与剂量、渗透压及注射速率均无关", "D": "注射过程中出现的全身热感、恶心呕吐属于典型的类过敏样反应", "E": "对比剂肾病是类过敏样反应最常见的表现形式"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-006", "kp": "类过敏样反应与器官毒性反应的机制分型", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】类过敏样反应属个体特异质，极小剂量即可诱发严重反应，因此不能靠\"减量\"来预防；其机制并非经典的 IgE 介导过敏，而是对比剂直接激活肥大细胞与嗜碱粒细胞释放组胺，并可激活补体与凝血系统，故称\"类过敏样\"，但临床表现（荨麻疹、支气管痉挛、喉头水肿、休克）与Ⅰ型变态反应相同，抢救原则也一致。【为什么错】B 与特异质反应的定义直接矛盾；若与剂量正相关，则应归入器官毒性。C 器官毒性反应恰恰是剂量依赖性的，与总碘量、渗透压、黏度和注射速率密切相关，减少剂量、选用渗透压更低的对比剂即可降低其发生率。D 热感与恶心呕吐由高渗透压和化学刺激引起，属典型的器官毒性（生理性）反应，通常一过性、可自行缓解。E 对比剂肾病由渗透性利尿、肾髓质缺氧与肾小管上皮直接毒性所致，是剂量依赖的器官毒性反应，与特异质机制无关。", "tr": "分型决定对策：类过敏样反应靠既往史筛查、预处理与抢救准备，器官毒性反应靠减量、降渗透压、控制注射速率与水化；把热感、恶心当成\"过敏先兆\"而贸然停检是临床常见误判。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0107", "t": "多选题", "s": "关于对比剂诱导的急性肾损伤（CI-AKI／PC-AKI）的危险因素与预防措施，下列表述正确的有", "o": {"A": "检查前已存在的肾功能不全是最重要的患者相关危险因素，eGFR 低于30 ml/(min·1.73 m²) 属高危", "B": "糖尿病肾病、脱水与低血容量、充血性心力衰竭、高龄以及同期使用肾毒性药物（非甾体抗炎药、氨基糖苷类等）均可增加发生风险", "C": "动脉内注射（尤其对比剂首过即通过肾脏的高剂量注射）的风险高于静脉内注射", "D": "等渗或次高渗对比剂的使用、控制总碘量并避免短期内重复给药，属对比剂相关的可控措施", "E": "常规预防性使用 N-乙酰半胱氨酸、呋塞米或甘露醇可有效降低其发生率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-007", "kp": "对比剂肾病的危险因素与预防", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】A 基础肾功能是风险分层的核心，eGFR 越低风险越高，30 是公认的高危界值。B 这些因素或减少肾血流、或加重肾髓质缺氧、或叠加肾小管毒性，共同放大风险。C 动脉内注射时对比剂以高浓度首过肾脏（如肾动脉、腹主动脉造影），肾脏局部暴露量远高于静脉注射后经体循环稀释者。D 对比剂相关的可控因素包括渗透压、黏度、总碘量与给药间隔，指南推荐两次注射间隔至少48~72 h，高危者更长。【为什么错】E 证据不支持：大型随机对照研究（如 PRESERVE 试验）显示 N-乙酰半胱氨酸并不优于安慰剂；而呋塞米、甘露醇等利尿剂在未充分补液的前提下会加重血容量不足，反而可能增加肾损伤风险，故不推荐常规使用。目前循证支持最充分的预防措施仍是充分的静脉水化。", "tr": "\"水化是硬道理，药物预防证据不足\"是本考点的主线；此外注意术语更新——因难以证明因果关系，现多用 PC-AKI（对比剂检查后急性肾损伤）替代传统的 CIN。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U04-0108", "t": "单选题", "s": "一名65岁2型糖尿病患者长期口服二甲双胍，近期血肌酐升高，估算 eGFR 为25 ml/(min·1.73 m²)，因腹痛需行腹部增强 CT（静脉注射非离子型碘对比剂）。关于二甲双胍的处理，正确的做法是", "o": {"A": "无需停药，因为静脉注射不影响肾功能", "B": "检查前3天开始停药，检查结束后立即恢复", "C": "停药24 h 后即可恢复，无需复查肾功能", "D": "改用胰岛素后即可不受任何限制地大剂量使用对比剂", "E": "自注射对比剂时起停用二甲双胍，停药48 h 后复查肾功能，确认未进一步恶化方可恢复用药"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-008", "kp": "二甲双胍与碘对比剂的相互作用及停药规则", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】二甲双胍本身对肾脏无毒性，其经肾原形排泄；若使用对比剂后发生急性肾损伤，二甲双胍蓄积可诱发罕见但病死率很高的乳酸性酸中毒。现行指南按肾功能分层：eGFR≥30 且为静脉给药者一般无需停药；eGFR 低于30、或经动脉给药使对比剂首过肾脏、或已存在急性肾损伤者，应自注射对比剂时起停药48 h，其间充分水化，48 h 后复查肾功能确认未恶化再恢复。本例 eGFR 为25，属需停药人群。【为什么错】A 忽略了该患者已处于 eGFR 低于30 的高危区间。B 提前3天停药并无必要，且检查后立即恢复恰恰跳过了最危险的48 h 观察窗口，逻辑正好相反。C 24 h 不足以覆盖对比剂后急性肾损伤的高发时段（通常48~72 h 达峰），且省略复查肾功能这一关键环节。D 改用胰岛素只解决降糖药本身的蓄积问题，患者的肾损伤风险依然存在，对比剂仍应遵循最低有效剂量原则。", "tr": "关键在\"从注射时起停48 h\"而非\"检查前停48 h\"；同时须把停药与水化、复查肾功能作为整体方案，单纯停药并不降低急性肾损伤本身的风险。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0109", "t": "案例分析题", "s": "一名52岁男性行胸部增强 CT，经肘静脉以3.5 ml/s 注射非离子型碘对比剂80 ml。注射结束约5 min，患者在观察区突然出现全身皮肤潮红、大片荨麻疹、声音嘶哑伴吸气性喘鸣，主诉咽部堵塞感与呼吸困难；测血压80/50 mmHg，脉搏细速120次/分，血氧饱和度88%。检查室内配备完备的急救车、氧气、监护仪，抢救医师即刻到场。此时首要的药物处置是", "o": {"A": "立即静脉推注1∶1000 肾上腺素1 mg", "B": "立即静脉推注地塞米松10 mg 作为首选用药", "C": "立即肌内注射苯海拉明20 mg 作为首选用药", "D": "立即于大腿前外侧肌内注射1∶1000 肾上腺素0.3~0.5 mg（0.3~0.5 ml），必要时每5~15 min 重复，同时给予高流量吸氧、快速静脉补液并抬高下肢", "E": "立即皮下注射1∶10000 肾上腺素5 ml"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-009", "kp": "重度类过敏样反应的急救处理", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】本例同时具备皮肤黏膜表现、上气道梗阻（声嘶、喘鸣）与循环衰竭（低血压、心动过速），属重度类过敏样反应／过敏性休克。肾上腺素是唯一能同时逆转支气管痉挛、喉头水肿与血管扩张性低血压的一线药物，成人剂量为0.01 mg/kg、最大0.5 mg，采用1∶1000 浓度肌内注射于大腿前外侧股外侧肌（该部位血供丰富、吸收最快），必要时每5~15 min 重复。同时必须高流量吸氧、开放静脉快速输注晶体液并抬高下肢改善回心血量。【为什么错】A 1∶1000 原液静脉推注浓度过高，易引发高血压危象、室性心律失常甚至心肌缺血；静脉途径仅在有心电监护、循环衰竭或心搏骤停时由医师使用1∶10000 稀释液缓慢推注。B 糖皮质激素起效需数小时，只能用于预防双相反应，绝不能作为首选，延误肾上腺素给药是抢救失败的常见原因。C 抗组胺药仅能缓解皮肤瘙痒与荨麻疹，对喉头水肿与休克无效。E 皮下注射血供差、吸收慢且不可预测，休克时外周灌注更差，指南已不推荐；且该途径与剂量组合不符合现行规范。", "tr": "抢救顺序是\"肾上腺素肌注→吸氧→补液→体位→再考虑激素与抗组胺药\"；把激素或抗组胺药当作首选、或误用静脉原液推注，是最严重的两类错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0110", "t": "多选题", "s": "关于碘对比剂急性不良反应的严重程度分级与相应处理，下列表述正确的有", "o": {"A": "散在荨麻疹且无呼吸循环受累者属轻度反应，可留观并视情况给予口服或肌注抗组胺药", "B": "支气管痉挛伴血氧饱和度下降属中重度反应，应立即吸氧并给予 β₂ 受体激动剂吸入，病情进展者使用肾上腺素", "C": "迷走神经反应表现为心动过缓合并低血压，处理为抬高下肢、快速静脉补液，必要时静脉给予阿托品0.5~1 mg", "D": "凡曾发生过轻度不良反应者，再次检查时都必须放弃一切增强检查", "E": "预防性使用糖皮质激素可以完全消除再次发生严重反应的风险"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-010", "kp": "不良反应的分级处理与迷走反应的鉴别", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】A 轻度反应多可自限，处理以观察为主，必要时对症用药，无需终止后续流程。B 支气管痉挛属中重度，吸氧与吸入型 β₂ 受体激动剂是初始处理，若出现血氧持续下降、意识改变或低血压则须及时给予肾上腺素。C 迷走神经反应的特征是\"慢＋低\"，即心动过缓合并低血压，与过敏性休克的\"快＋低\"（心动过速合并低血压）形成鲜明对照，处理为体位与扩容，心率持续过缓时静脉给予阿托品，误用肾上腺素并非首选。【为什么错】D 表述过于绝对：轻度反应者再次检查时应权衡获益与风险，可更换不同分子结构的对比剂、必要时预处理并加强观察，而非一概放弃增强这一重要诊断手段。E 预处理只能降低而不能消除风险，文献中已有充分预处理后仍发生严重反应的报道，故预处理绝不能替代急救准备与全程监护。", "tr": "\"心动过缓＋低血压\"想迷走反应、\"心动过速＋低血压\"想过敏性休克，是决定用阿托品还是肾上腺素的分水岭，务必牢记。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0111", "t": "单选题", "s": "关于X线对比剂的引入途径与适用情形，下列配伍错误的是", "o": {"A": "静脉尿路造影——静脉注射水溶性碘对比剂", "B": "子宫输卵管造影——经宫颈管直接注入水溶性碘对比剂", "C": "上消化道钡餐检查——口服硫酸钡混悬液", "D": "疑有消化道穿孔或术后吻合口瘘——首选口服硫酸钡混悬液", "E": "脊髓造影（椎管内注入）——只能使用经批准可鞘内使用的非离子型对比剂"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-011", "kp": "对比剂的引入途径与禁忌配伍", "ch": "四、对比剂 → 1.X线对比剂 → (3)引入途径", "ex": "【为什么对】本题选错误配伍。疑有消化道穿孔、吻合口瘘或需急诊手术者禁用硫酸钡：钡剂不溶于水、不能被吸收，一旦经破口进入腹腔将引起严重的钡剂性腹膜炎与广泛粘连，且极难清除。此类情况应改用水溶性碘对比剂，并在有误吸风险时选择非离子型等渗或次高渗制剂。【为什么错】A 静脉尿路造影依靠肾小球滤过后对比剂在集合系统内浓聚，静脉给药是标准途径。B 子宫输卵管造影经宫颈插管直接注入，属体腔内引入途径。C 钡剂涂布性好、密度高，是常规胃肠道造影的首选。E 椎管内属高风险途径，离子型对比剂可引起抽搐、蛛网膜炎等严重神经毒性反应，必须使用明确标注可鞘内使用的非离子型对比剂。", "tr": "\"疑穿孔用水溶性、有误吸风险避开高渗离子型\"是两条并行的安全底线；高渗离子型对比剂误吸入气道可引起肺水肿，选择时须同时兼顾这两点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0112", "t": "多选题", "s": "关于消化道造影中对比剂的选择原则，下列表述正确的有", "o": {"A": "硫酸钡不溶于水、不被吸收，黏附与涂布性能好，是常规胃肠道造影的首选对比剂", "B": "疑有消化道穿孔、拟急诊手术或存在明显误吸风险时，应改用水溶性碘对比剂", "C": "高渗离子型水溶性对比剂一旦误吸入气道可引起肺水肿，故对误吸高危者宜选用非离子型等渗或次高渗对比剂", "D": "钡剂进入腹腔后可被腹膜完全吸收，因此消化道穿孔并非其禁忌证", "E": "硫酸钡混悬液可用于静脉法血管造影"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-012", "kp": "钡剂与水溶性对比剂的选择", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】A 硫酸钡为不溶性混悬颗粒，原子序数高、密度大，能在黏膜表面形成均匀薄层，是显示黏膜微细结构的最佳选择。B 存在穿孔、瘘管或即将手术时，水溶性碘对比剂即使外漏也可被腹膜吸收并经肾排出，安全性远高于钡剂。C 高渗对比剂进入肺内会因渗透作用把大量液体拉入肺泡引起肺水肿，故吞咽功能障碍、意识不清、气管食管瘘等误吸高危患者应选用非离子型低／等渗制剂。【为什么错】D 与事实完全相反：钡剂进入腹腔不能被吸收，会引起化学性与异物性腹膜炎，形成致密粘连，是明确的绝对禁忌。E 硫酸钡为不溶性颗粒混悬液，进入血管将造成栓塞导致死亡，绝对不能用于任何血管内途径。", "tr": "\"钡剂只能进管腔、不能进血管、不能进腹腔\"是不可逾越的红线；D、E 两项虽然结论明显错误，但在紧张答题时仍常被误选，需建立牢固的安全反射。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0113", "t": "案例分析题", "s": "一名72岁女性，反复胸痛，心内科申请冠状动脉 CTA。既往史：3年前行增强 CT 后出现全身荨麻疹伴轻度咽部不适（判定为中度类过敏样反应），经处理后缓解；甲状腺功能亢进服甲巯咪唑治疗中，近期甲功已接近正常；体重52 kg，血肌酐正常，eGFR 78 ml/(min·1.73 m²)。检查当日抢救团队与急救药械齐备。作为 CT 技术组负责人，最合理的技术与安全方案是", "o": {"A": "重新评估检查的必要性并取得知情同意后，改用与既往所用品种不同的非离子型次高渗对比剂，按预案给予糖皮质激素与抗组胺药预处理，按体重个体化确定总碘量并适当降低注射流率，检查后留观至少30 min 且全程备好肾上腺素，同时告知内分泌科随访甲状腺功能", "B": "既往有中度过敏史即为绝对禁忌，应放弃 CTA 改行常规冠状动脉造影", "C": "甲亢患者禁用一切含碘对比剂，可改用钆对比剂完成 CT 冠状动脉成像", "D": "术前给予地塞米松后即可完全避免再次发生反应，检查结束即可离院", "E": "因肾功能正常，可采用最大剂量与最高流率以保证冠状动脉强化效果"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-013", "kp": "高危患者碘对比剂使用的综合决策", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】该患者存在两项风险：既往中度类过敏样反应史与甲状腺功能亢进。规范做法是先重新评估检查的必要性与替代方案，确有指征时更换不同分子结构的非离子型对比剂（交叉反应率因分子结构差异而下降），按预案给予糖皮质激素与抗组胺药预处理，按体重个体化控制总碘量并适当降低注射流率以减轻器官毒性负荷；既往有反应者留观时间应不短于30 min 并适当延长，全程备好肾上腺素。甲亢已控制者在权衡后可以使用，但须告知并随访甲功，因为碘负荷可能诱发甲亢加重或碘致甲状腺功能异常，属于典型的晚迟发反应。【为什么错】B 中度反应史属\"高危\"而非绝对禁忌；且常规冠状动脉造影同样需要注射碘对比剂，甚至因动脉内给药风险更高，该替代方案在逻辑上不成立。C 未控制的甲亢是相对禁忌，本例已接近正常，可在评估后使用；而钆对比剂在 CT 中的X线衰减能力远不足以替代碘剂，且大剂量使用会带来肾毒性与 NSF 风险，属于严重的原则性错误。D 预处理只能降低风险而不能消除，仍有发生严重反应的报道，检查后必须留观。E 与个体化用药原则背道而驰：52 kg 体重本应减量，最大剂量加最高流率会显著增加器官毒性反应与外渗风险。", "tr": "高危患者管理的四要素——换药、预处理、减量与降速、延长留观并备好抢救；\"用钆代替碘做 CT\"是必须警惕的错误答案，两者的X线衰减能力与安全窗完全不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U04-0114", "t": "案例分析题", "s": "一名58岁女性行胸部增强 CT，经肘正中静脉20 G 留置针以4.0 ml/s 注射非离子型碘对比剂。注射开始约3 s 后患者诉前臂胀痛，注射器压力曲线报警并自动终止推注。查体见注射侧前臂中段明显肿胀、皮肤张力增高、皮温略低，桡动脉搏动可及，手指活动与感觉正常，毛细血管充盈时间正常，估算外渗量约30 ml。作为当班技师，最恰当的处置是", "o": {"A": "立即局部热敷并用力按摩以促进对比剂吸收", "B": "在外渗部位注射透明质酸酶并即刻行切开减压", "C": "继续完成剩余对比剂的注射以保证图像质量", "D": "立即静脉注射糖皮质激素与利尿剂以加快对比剂排出", "E": "立即停止注射并拔除留置针，抬高患肢高于心脏水平，早期局部冷敷，详细记录外渗量与体征并观察2~4 h；若出现皮肤水疱、进行性肿胀、感觉异常或血循环障碍，立即请外科或整形科会诊"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-014", "kp": "碘对比剂血管外渗的处理", "ch": "四、对比剂 → 1.X线对比剂 → (3)引入途径", "ex": "【为什么对】绝大多数外渗为轻中度，处理原则是停止注射、抬高患肢促进静脉与淋巴回流、早期冷敷（24~48 h 内）以收缩血管、减轻炎症与肿胀，同时完整记录外渗量、部位与体征并留观2~4 h。本例虽有肿胀与张力增高，但循环、感觉与运动均正常，暂无骨筋膜室综合征证据，可按上述保守方案处理，并向患者交代随访要点与复诊指征。【为什么错】A 早期热敷会扩张血管、加重局部渗出与肿胀；用力按摩则可能使对比剂在组织间隙内进一步扩散并加重损伤。B 透明质酸酶的疗效证据有限，并非常规首选；切开减压属骨筋膜室综合征等严重并发症的紧急处置手段，本例尚无相应指征，贸然切开属过度治疗。C 已有外渗仍继续注射会使外渗量成倍增加，可能导致皮肤坏死甚至骨筋膜室综合征，是严重的操作错误。D 全身用糖皮质激素与利尿剂对局部外渗无确切疗效，利尿还可能造成血容量不足，反而增加肾损伤风险。", "tr": "\"早期冷敷、后期（48 h 后）可酌情热敷\"的时序不能颠倒；判断是否需要外科干预看四个信号——张力性水疱、感觉异常、进行性肿胀、末梢循环障碍。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0115", "t": "单选题", "s": "钆对比剂能够使邻近组织的 T1 明显缩短，从而在 T1WI 上呈现高信号。其发挥这一作用的主要机制是", "o": {"A": "钆本身能产生很强的 MR 信号，被接收线圈直接采集", "B": "Gd³⁺ 具有7个未成对电子、磁矩很大，通过偶极—偶极相互作用与邻近水质子交换能量，加快其纵向弛豫", "C": "钆改变了氢质子的进动频率，使其重新进入共振状态", "D": "钆通过降低组织的含水量而使信号强度升高", "E": "钆主要通过缩短 T2* 而在 T1WI 上产生高信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-001", "kp": "钆对比剂缩短 T1 的机制", "ch": "四、对比剂 → 2.MR对比剂 → (3)增强机制", "ex": "【为什么对】Gd³⁺ 的 f 轨道有7个未成对电子，是自然界磁矩最大的离子之一，其产生的强局部涨落磁场频率恰与质子的拉莫尔频率相近，通过偶极—偶极相互作用高效地把质子的纵向磁化能量传递给晶格，使 T1 显著缩短。这种作用要求水分子与顺磁中心足够接近（内球水交换为主，外球扩散为辅），因此对比剂只能\"间接\"改变周围质子的弛豫，而非自身成像。【为什么错】A 钆原子核并非成像核素，MR 图像的信号来自氢质子；对比剂是弛豫增强剂而不是信号源，这是与 CT 碘对比剂\"自身衰减X线\"的根本区别。C 进动频率由主磁场决定，钆并不改变拉莫尔频率，也不存在\"使质子重新共振\"的过程。D 钆不改变组织含水量，信号升高源于弛豫加快。E 钆同时缩短 T1 与 T2/T2*，但在临床常用浓度下 T1 缩短效应占优；T2* 缩短效应只有在浓度很高时（如团注首过时的静脉腔内、膀胱内积聚）才占主导，届时反而表现为信号减低。", "tr": "\"对比剂本身不成像，只改变周围质子的弛豫\"是理解一切 MR 对比剂的总纲；高浓度钆造成信号减低的现象常被误认为是\"未强化\"。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0116", "t": "单选题", "s": "评价 MR 对比剂效能时常用弛豫率 r1 与 r2 两个参数。关于它们的定义与意义，正确的是", "o": {"A": "r1 与 r2 分别表示单位浓度对比剂使 1/T1 与 1/T2 增加的量，单位为 L/(mmol·s)，其中 r2/r1 比值越小越有利于产生 T1 增强效果", "B": "r1 数值越大，表示该对比剂使 T1 延长得越明显", "C": "r2/r1 比值越大，越适合作为 T1 阳性对比剂", "D": "弛豫率是物质固有常数，与主磁场强度无关，1.5T 与3.0T 下完全相同", "E": "超顺磁性氧化铁的 r2/r1 比值远小于钆螯合物"}, "d": "难", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-002", "kp": "弛豫率 r1、r2 及其临床意义", "ch": "四、对比剂 → 2.MR对比剂 → (2)生物学特性", "ex": "【为什么对】弛豫率描述单位摩尔浓度对比剂对弛豫速率的增强能力，关系式为 1/T1(观察)＝1/T1(本底)＋r1·C。r1 越大，同样剂量下 T1 缩短越明显、强化越强；而 r2 反映 T2/T2* 缩短能力，过强会抵消 T1 效应造成信号丢失，因此 r2/r1 比值越小，对比剂越\"纯粹\"地表现为 T1 阳性效果。【为什么错】B 概念反了：r1 越大意味着纵向弛豫速率 1/T1 增加越多，即 T1 越短而非越长。C 结论相反，r2/r1 大者表现为 T2 阴性对比剂特性。D 弛豫率具有明确的场强依赖性：随场强升高，多数钆螯合物的 r1 略有下降而 r2 相对升高，这正是3.0T 与1.5T 在增强剂量和序列参数上需要区别对待的原因之一。E 事实相反：超顺磁性氧化铁的 r2 远大于 r1，r2/r1 比值可达数十甚至更高，因此表现为强烈的 T2／T2* 阴性对比效应。", "tr": "把 r1、r2 与 T1、T2 的\"倒数关系\"理清是关键：弛豫率大＝弛豫时间短；此外3.0T 上背景组织 T1 延长而钆剂 r1 略降，二者共同决定了临床剂量的调整策略。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0117", "t": "多选题", "s": "关于钆对比剂的配体结构、稳定性与肾源性系统性纤维化（NSF）风险，下列表述正确的有", "o": {"A": "大环类配体（如钆特醇、钆布醇、钆特酸葡胺）把 Gd³⁺ 包裹在预先组织好的刚性空腔内，其热力学与动力学稳定性均高于线性类", "B": "线性非离子型（如钆双胺、钆弗塞胺）动力学稳定性最低，被列为 NSF 高风险组", "C": "NSF 主要见于严重肾功能不全（eGFR 低于30）及透析患者，与游离 Gd³⁺ 释放及体内滞留相关", "D": "大环类不会释放任何游离钆，因此对任何肾功能状态的患者均无需限制剂量", "E": "多次给药后脑内（齿状核、苍白球）T1WI 信号增高的\"钆沉积\"现象在线性类中报道更多，目前尚未证实存在明确的临床危害"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-003", "kp": "线性与大环类钆剂的稳定性及 NSF 风险", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】A 大环配体形成笼状空腔，Gd³⁺ 被多个配位原子从各个方向牢牢锁住，解离需要打开整个环，动力学惰性极强；线性配体则如同链条缠绕，更易发生转金属化与解离。B ESUR 分类中钆双胺、钆弗塞胺与钆喷酸葡胺属高风险组，其中非离子型线性制剂由于缺乏电荷稳定作用，动力学稳定性最差。C 肾功能严重受损时钆剂在体内滞留时间从数小时延长至数十小时甚至更久，游离 Gd³⁺ 沉积于皮肤与内脏并激活成纤维细胞，是 NSF 的公认机制。E 钆沉积在线性类中报道显著更多，与其稳定性差一致；目前尚无确证的临床损害，但基于审慎原则临床已倾向优先使用大环类。【为什么错】D 表述过于绝对：大环类只是解离概率极低，并非绝对不释放；对严重肾功能不全者仍应严格掌握适应证、使用最低有效剂量并避免短期内重复给药。", "tr": "记忆框架为\"大环＞线性离子型＞线性非离子型\"的稳定性排序；注意 NSF 与钆沉积是两个不同概念——前者是明确的严重疾病，后者目前只是影像学现象。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0118", "t": "单选题", "s": "下列 MR 对比剂中，既具有细胞外液间隙分布特性，又能被功能正常的肝细胞特异性摄取并经胆道排泄，从而实现\"动态期＋肝细胞期\"双期成像的是", "o": {"A": "钆喷酸葡胺（Gd-DTPA）", "B": "钆特酸葡胺（Gd-DOTA）", "C": "钆塞酸二钠（Gd-EOB-DTPA）", "D": "钆布醇（gadobutrol）", "E": "钆特醇（gadoteridol）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-004", "kp": "肝细胞特异性 MR 对比剂", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】钆塞酸二钠在 Gd-DTPA 骨架上引入乙氧基苄基（EOB）亲脂基团，使其可被肝细胞膜上的有机阴离子转运多肽摄取进入肝细胞，再经多药耐药相关蛋白排入胆道。注射早期它与普通细胞外液对比剂一样进行动脉期、门静脉期动态成像，约20 min 后进入肝细胞期，一次给药即可获得血流动力学与肝细胞功能双重信息。【为什么错】A 钆喷酸葡胺为经典的线性离子型细胞外液间隙对比剂，无肝细胞特异性摄取。B、D、E 钆特酸葡胺、钆布醇与钆特醇均为大环类细胞外液间隙对比剂，分布于血管内与组织间隙，全部经肾小球滤过排泄，不被肝细胞摄取。", "tr": "钆贝葡胺（Gd-BOPTA）也具有部分肝细胞摄取（约3%~5%），肝胆期需延迟1~2 h；与钆塞酸二钠约50%摄取、20 min 成像的特性差异明显，命题常在摄取比例与延迟时间上设卡。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0119", "t": "单选题", "s": "某院在飞利浦3.0T 设备上开展钆塞酸二钠（Gd-EOB-DTPA）增强肝脏 MRI。关于该对比剂的成像时相安排与技术要点，正确的是", "o": {"A": "肝胆特异期应在注射后3~5 min 采集", "B": "该药完全不经肾脏排泄，肾功能不全者可以随意加大剂量", "C": "由于其单次注射剂量与注射体积均小于常规细胞外液对比剂，动脉期强化峰值更高且几乎不会出现一过性呼吸运动伪影", "D": "肝胆特异期图像上正常肝实质呈低信号，而缺乏肝细胞功能的病灶呈高信号", "E": "约50% 经肝细胞摄取并由胆道排泄，肝胆特异期通常在注射后约20 min 采集，采用三维 T1 加权高分辨屏气脂肪抑制梯度回波序列（eTHRIVE／VIBE／LAVA）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-005", "kp": "Gd-EOB-DTPA 的双期特性与序列选择", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】钆塞酸二钠约50% 经肝细胞摄取、经胆道排泄，其余约50% 经肾小球滤过。正常肝实质在注射后10~20 min 逐步摄取达到平台，临床常规在20 min 左右采集肝胆特异期；该期要求高信噪比与高空间分辨率，标准做法是三维扰相梯度回波类 T1 加权屏气序列配合脂肪抑制，飞利浦称 eTHRIVE，西门子称 VIBE，GE 称 LAVA。【为什么错】A 3~5 min 时肝实质摄取尚未充分，此时属过渡期，病灶与肝实质对比不足。B 该药约一半经肾排泄，肾功能不全者同样需要评估风险、控制剂量。C 事实相反：其推荐剂量为0.025 mmol/kg，注射体积小、团注更陡峭，动脉期时间窗更窄，且文献报道其一过性严重运动伪影发生率高于常规钆剂，故需缩短注射时间、采用团注追踪并加强屏气训练，必要时缩短单期采集时间。D 信号关系正好颠倒：肝胆期正常肝实质因摄取对比剂而呈高信号，无正常肝细胞功能的病灶（多数转移瘤、肝内胆管癌、低分化肝细胞癌）因不摄取而呈相对低信号，这正是该期检出小病灶的原理。", "tr": "肝胆期\"肝亮病灶暗\"的信号逻辑必须牢记；此外注意含功能性肝细胞的局灶性结节增生在肝胆期可呈等或高信号，是与肝腺瘤、肝癌鉴别的要点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0120", "t": "多选题", "s": "关于超顺磁性氧化铁（SPIO／USPIO）类 MR 对比剂，下列表述正确的有", "o": {"A": "属阴性（负性）对比剂，主要通过显著缩短 T2／T2* 使摄取组织的信号明显下降", "B": "静脉注射后 SPIO 被肝脏 Kupffer 细胞与脾脏巨噬细胞吞噬，正常肝实质信号降低，而缺乏 Kupffer 细胞的病灶相对呈高信号", "C": "USPIO 颗粒直径更小、血液半衰期更长，可用于淋巴结成像与血池成像", "D": "SPIO 的 r2/r1 比值远小于钆螯合物", "E": "使用 SPIO 后应首选 T1WI 序列来观察其对比效果"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-006", "kp": "超顺磁性氧化铁对比剂的特性与应用", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】A 超顺磁性颗粒在磁场中产生远强于顺磁离子的局部磁化，造成显著的磁场不均匀性，加速质子失相位，因而以缩短 T2／T2* 为主，表现为信号减低的阴性对比。B 这是 SPIO 用于肝脏成像的经典机制：正常肝实质因吞噬颗粒而变黑，不含 Kupffer 细胞的转移瘤、多数肝癌因不摄取而保持原有信号，形成\"黑肝衬托亮病灶\"的对比。C 颗粒越小越不易被网状内皮系统快速清除，血液半衰期延长，可进入淋巴系统并长时间维持血池内浓度。【为什么错】D 与事实相反：SPIO 的 r2 远大于 r1，r2/r1 比值可达数十，远大于钆螯合物（通常在1~2 之间），这正是其表现为阴性对比剂的量化依据。E 观察 SPIO 效果应使用对磁化率敏感的 T2WI，尤其是 T2* 加权梯度回波序列；用 T1WI 观察会显著低估其效应。", "tr": "阳性对比剂看 T1WI、阴性对比剂看 T2/T2*WI，序列选择与对比剂类型必须匹配；把\"信号减低\"误判为\"未强化\"是阅片与技术沟通中的常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0121", "t": "单选题", "s": "关于锰类 MR 对比剂（如锰福地吡三钠 Mn-DPDP），下列表述正确的是", "o": {"A": "属阴性对比剂，主要通过缩短 T2 起作用", "B": "Mn²⁺ 为顺磁性金属离子，可被功能正常的肝细胞摄取并经胆汁排泄，属肝细胞特异性 T1 阳性对比剂", "C": "主要被肝脏 Kupffer 细胞吞噬后发挥作用", "D": "仅能用于中枢神经系统的增强检查", "E": "与钆螯合物一样属于细胞外液间隙分布型对比剂"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-007", "kp": "锰类肝细胞特异性对比剂", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】Mn²⁺ 含5个未成对电子，具有顺磁性，能有效缩短 T1。锰福地吡三钠进入体内后逐步释放 Mn²⁺，被功能正常的肝细胞摄取，部分经胆汁排泄，使正常肝实质在 T1WI 上信号升高，而缺乏正常肝细胞功能的病灶相对呈低信号，属肝细胞特异性阳性对比剂。此外锰还可被胰腺、肾皮质与心肌摄取。【为什么错】A 归类错误：锰剂以缩短 T1 为主，是阳性对比剂；阴性对比剂的代表是超顺磁性氧化铁。C 被 Kupffer 细胞吞噬是 SPIO 的机制，锰剂靶向的是肝细胞本身。D 锰剂的主要临床应用恰恰在肝脏，而非仅限中枢神经系统。E 细胞外液间隙型对比剂无器官特异性摄取、全部经肾排泄，与锰剂的肝细胞靶向和胆道排泄特性完全不同。", "tr": "把三类肝脏对比剂的靶细胞分清：钆塞酸二钠与锰剂靶向肝细胞（阳性、T1WI 肝变亮），SPIO 靶向 Kupffer 细胞（阴性、T2WI 肝变黑）。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0122", "t": "多选题", "s": "关于钆对比剂的不良反应及其处理，下列表述正确的有", "o": {"A": "总体不良反应发生率低于碘对比剂，多为轻度表现，如恶心、头痛、注射部位不适与荨麻疹", "B": "严重类过敏样反应虽罕见，但一旦发生，其处理原则与碘对比剂相同，首选肌内注射肾上腺素", "C": "有钆剂过敏史者再次检查时应换用不同类别的钆剂，并做好预处理与抢救准备", "D": "某些钆制剂可干扰采用邻甲酚酞络合酮法等比色法的血清钙测定，造成假性低钙结果", "E": "妊娠期可以常规使用钆对比剂，因为钆螯合物不能通过胎盘屏障"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-008", "kp": "钆对比剂的不良反应与处理原则", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】A 钆剂常规剂量下所含摩尔量远低于碘剂，渗透压负荷小，不良反应率明显更低，且以轻度为主。B 严重反应虽罕见，机制与临床表现同为类过敏样反应，抢救流程完全一致，MR 机房同样必须配备急救药械并明确转运路径。C 换用不同螯合结构的制剂可降低交叉反应概率，但仍需预处理与全程监护。D 部分钆制剂（尤以线性非离子型为著）会与比色法试剂发生干扰，造成检验结果假性偏低，若不了解此点可能导致不必要的补钙治疗，故应告知检验科并在给药后一定时间内避免采血复查血钙。【为什么错】E 表述错误：钆螯合物可通过胎盘进入胎儿循环，经胎儿肾脏排入羊水后可能长时间滞留并解离，因此妊娠期原则上避免使用，仅在获益明确大于风险且无替代方案时由多学科评估后谨慎使用。", "tr": "MR 检查室常被误认为\"没有辐射就绝对安全\"，实际上其急救难度更大——磁场内不能带入铁磁性抢救设备，必须先把患者转移出Ⅳ区再抢救，这一流程应事先演练。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0123", "t": "单选题", "s": "成人颅脑 MRI 增强常规使用细胞外液间隙钆对比剂，其市售制剂浓度为0.5 mmol/ml，标准剂量为0.1 mmol/kg。一名体重70 kg 的患者，应注射的对比剂体积约为", "o": {"A": "7 ml", "B": "14 ml", "C": "21 ml", "D": "35 ml", "E": "70 ml"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-009", "kp": "钆对比剂的剂量与体积换算", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】先算摩尔量：0.1 mmol/kg×70 kg＝7 mmol；再按浓度换算体积：7 mmol÷0.5 mmol/ml＝14 ml。这与临床经验值\"0.2 ml/kg\"完全吻合，即70 kg 患者约14 ml。【为什么错】A 误把0.1 mmol/kg 直接当作0.1 ml/kg，漏掉了浓度换算这一步，是最常见的错误。C 相当于按0.15 mmol/kg 计算又出现换算偏差。D 相当于按0.5 ml/kg 给药，为标准剂量的2.5倍。E 相当于按1 ml/kg 给药，为标准剂量的5倍，严重超量。", "tr": "0.5 mmol/ml 浓度制剂的经验换算是\"0.1 mmol/kg＝0.2 ml/kg\"；但钆塞酸二钠为0.25 mmol/ml 制剂、推荐剂量0.025 mmol/kg（约0.1 ml/kg），不可套用同一经验值。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0124", "t": "多选题", "s": "某院在飞利浦3.0T 设备上开展头颈部对比增强 MR 血管成像（CE-MRA）。关于对比剂应用与采集时相控制，下列表述正确的有", "o": {"A": "采用高压注射器团注（常用2~3 ml/s）并追加生理盐水冲刷，以形成陡峭紧凑的团注峰", "B": "可用团注试验（test bolus）或实时透视触发（BolusTrak／CARE Bolus／SmartPrep）确定采集延迟，使 K 空间中心恰好落在动脉峰值时刻", "C": "CE-MRA 常采用三维扰相梯度回波序列（T1-FFE／FLASH／SPGR），并配合椭圆中心（centric）K 空间填充顺序", "D": "为提高动脉信号强度，应尽量延长采集时间以增加信号平均次数", "E": "3.0T 相比1.5T 因背景组织 T1 延长且信噪比提高，可适当减少对比剂用量"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-010", "kp": "CE-MRA 的对比剂应用与时相控制", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】A 紧凑团注使动脉内浓度在短时间内达到高峰，是获得高动脉信号、避免静脉污染的前提；盐水冲刷把留在上肢静脉与管路内的对比剂全部推入循环，既提高利用率又减少残留伪影。B 采集延迟的精确匹配是 CE-MRA 成败的关键，两种方法各有优势：团注试验准确但多耗一次小剂量注射，透视触发可实时观察、操作便捷。C 三维扰相梯度回波可用极短 TR/TE 抑制背景、突出短 T1 的含钆血液；椭圆中心填充把决定图像对比的 K 空间中心区放在采集起始，正对动脉峰值。E 3.0T 上背景组织 T1 延长使未强化组织更暗，加之信噪比提高，同样剂量下强化对比更佳，为减量提供了空间。【为什么错】D 与时相控制原则直接冲突：CE-MRA 必须在动脉峰值这一狭窄时间窗内完成中心 K 空间采集，延长采集时间会使静脉回流显影造成静脉污染，同时增加运动伪影风险；提高信噪比应通过并行采集、优化线圈与带宽实现，而非延长采集。", "tr": "CE-MRA 的核心是\"时间窗匹配\"而非\"信号越多越好\"；判断失败原因时，静脉污染提示延迟过长，动脉信号弱且出现环状伪影（Maki 伪影）提示采集过早。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0125", "t": "多选题", "s": "关于细胞外液间隙钆对比剂的生物学特性与临床应用，下列表述正确的有", "o": {"A": "静脉注射后迅速分布于血管内与细胞外间隙，不能通过完整的血脑屏障", "B": "主要经肾小球滤过以原形排出，肾功能正常者血浆半衰期约1.5 h", "C": "其血浆蛋白结合率高、血管内滞留时间长，属典型的血池对比剂", "D": "增强后 T1WI 常需配合脂肪抑制，以提高强化组织与周围脂肪的区分度，尤其在眼眶、颈部与乳腺检查中", "E": "常规剂量下钆剂在 T2WI 上产生明显高信号，故增强后应以 T2WI 作为主要观察序列"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-011", "kp": "细胞外液间隙钆对比剂的分布与排泄", "ch": "四、对比剂 → 2.MR对比剂 → (2)生物学特性", "ex": "【为什么对】A 钆螯合物分子量小、亲水性强，可自由通过一般毛细血管进入组织间隙，但无法穿过完整的血脑屏障，这正是中枢神经系统病变一旦强化即提示血脑屏障破坏的原理。B 几乎不参与代谢，经肾小球滤过原形排出，正常肾功能者血浆半衰期约1.5 h，24 h 内基本清除完毕。D 脂肪在 T1WI 上本身呈高信号，会掩盖强化灶，故富含脂肪的眼眶、颈部与乳腺区域增强扫描常规加脂肪抑制。【为什么错】C 描述的是血池对比剂（如与白蛋白高结合率的钆磷维塞）的特性；细胞外液间隙型对比剂的蛋白结合率很低，因而能迅速渗出到组织间隙。E 常规剂量下钆剂以缩短 T1 为主要效应，应在 T1WI 上观察强化；在 T2WI 上其效应不明显，浓度很高时甚至因缩短 T2 而表现为信号减低。", "tr": "\"强化＝血脑屏障破坏或血供／通透性增加\"这一推理只对中枢神经系统严格成立，在血脑屏障之外的器官不能照搬。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0126", "t": "案例分析题", "s": "患者男，64岁，慢性肾脏病5期，规律血液透析（每周3次），因超声怀疑肝内占位需行腹部 MRI 增强检查。患者既往有高血压、2型糖尿病多年，目前服用多种药物，近期无急性感染，食欲欠佳、轻度乏力，凝血功能基本正常，无钆剂过敏史，一般状况尚可，可配合屏气。临床医师在申请单上特别注明希望使用肝细胞特异性对比剂以评估病灶性质。作为 MR 技师，向临床提出的最合理建议是", "o": {"A": "因患者规律透析，钆剂可被完全清除，故可按常规剂量使用任何类型的钆对比剂", "B": "严格评估增强的必要性与替代方案；若确需增强，优先选用 ESUR 分类中 NSF 低风险的大环类对比剂，采用最低有效剂量并避免短期内重复给药，把检查安排在透析日并于给药后尽早进行血液透析，同时充分知情告知", "C": "改用双倍剂量的线性离子型对比剂，以保证肝胆期强化效果", "D": "直接改行腹部增强 CT，因为碘对比剂对透析患者没有任何风险", "E": "无需任何增强检查，仅做扩散加权成像即可完全替代"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-012", "kp": "终末期肾病患者钆对比剂的选择策略", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】慢性肾脏病5期透析患者是 NSF 的最高危人群。此时临床需求（肝细胞特异性成像）与安全要求（低 NSF 风险）存在冲突：目前临床主要的肝细胞特异性对比剂钆塞酸二钠属线性离子型，风险等级高于大环类。规范做法是先评估增强的必要性与替代方案，若确需增强则优先选用低风险的大环类制剂、使用最低有效剂量、避免短期重复给药，并把检查安排在透析日、给药后尽早透析以加速清除，同时完成充分的知情告知——这是一个由技师参与、与临床共同完成的风险—获益决策过程。【为什么错】A 血液透析确实可清除大部分钆剂（三次透析可清除约97%），但清除并非即时完成，且现有证据不足以证明透析能可靠预防 NSF，故不能据此放宽制剂选择与剂量。C 双倍剂量的线性制剂把剂量与结构两项风险同时叠加，与安全原则完全相悖。D 该患者已进入透析阶段，虽然对残余肾功能的顾虑相对减少，但碘对比剂仍有类过敏样反应、容量负荷与心血管风险，说\"没有任何风险\"不成立；此外 CT 也无法提供肝细胞功能信息。E 扩散加权成像对病灶检出有帮助，但在鉴别诊断上不能替代动态增强所提供的血流动力学信息，把它作为完全替代方案会造成漏诊或误判。", "tr": "\"透析能清除钆\"不等于\"透析患者可随意用钆\"；技师在此类病例中的价值在于主动提示风险分级、提出可行替代方案，而不是被动执行申请单。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U04-0127", "t": "案例分析题", "s": "一名42岁女性，超声发现右乳外上象限可疑结节，临床申请乳腺动态增强 MRI。患者既往无乳腺手术及放疗史，否认乳腺癌家族史，既往钼靶提示致密型乳腺、BI-RADS 3 类；设备为飞利浦3.0T，使用专用乳腺相控阵线圈，患者取俯卧位、双乳自然悬垂，无钆剂过敏史，肾功能正常，月经规律。作为 MR 技师，关于对比剂使用与动态采集方案，最恰当的安排是", "o": {"A": "按0.1 mmol/kg 使用大环类钆剂，以约2 ml/s 团注并追加20 ml 生理盐水冲管；采用三维扰相梯度回波脂肪抑制序列（eTHRIVE／VIBE），先采集蒙片期，再连续采集6~8个动态时相，单期时间分辨率控制在60~90 s 以内，以便绘制时间—信号强度曲线；检查安排在月经周期第7~14天", "B": "采用0.3 mmol/kg 的三倍剂量以提高病灶检出率", "C": "单期采集时间越长越好，以最大限度保证空间分辨率", "D": "检查应安排在月经周期第1~7天（月经期）进行，以减少背景实质强化", "E": "注射后只采集一个延迟期图像即可判断时间—信号强度曲线类型"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-013", "kp": "乳腺动态增强 MRI 的对比剂与采集方案", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】乳腺动态增强的诊断价值来自形态与血流动力学两方面：形态学要求高空间分辨率与可靠的脂肪抑制，血流动力学要求足够的时间分辨率以刻画流入与流出。标准剂量0.1 mmol/kg、约2 ml/s 团注加盐水冲刷可形成稳定的团注；三维扰相梯度回波配脂肪抑制既满足薄层高分辨又能压制脂肪高信号；先采蒙片再连续采集6~8个时相，单期控制在60~90 s 以内，可准确区分流入型、平台型与流出型曲线。月经周期第7~14天（增生早期）激素水平低，背景实质强化最轻，可减少假阳性。【为什么错】B 超剂量既无循证依据，又增加钆负荷与不良反应风险，且过强的背景强化反而降低特异性。C 单纯追求空间分辨率而牺牲时间分辨率，会使动态曲线失真，无法识别快进快出的恶性强化特征，属典型的顾此失彼。D 月经期与黄体期（第15天以后）背景实质强化最明显，是应当避开的时段，本项把最佳时间窗记反了。E 时间—信号强度曲线必须由多个连续时相构成，单一延迟期图像既无法判断强化速率也无法识别流出模式。", "tr": "乳腺 MRI 的三个时间要点：检查安排在月经周期第7~14天、单期时间分辨率不超过60~90 s、动态采集覆盖注射后至少5~7 min；三者常被合并考查。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0128", "t": "单选题", "s": "随着 CT 扫描速度不断提高，对比剂注射方案日趋个体化。关于\"碘流率\"与\"总碘量\"这两个核心参数，正确的表述是", "o": {"A": "碘流率仅由注射流率决定，与对比剂的碘浓度无关", "B": "提高对比剂碘浓度时必然要求同步提高注射流率", "C": "总碘量决定动脉强化峰值，碘流率决定肝实质的强化程度", "D": "碘流率（gI/s）等于对比剂碘浓度（gI/ml）与注射流率（ml/s）的乘积，主要决定血管内强化峰值；总碘量（gI）则与实质器官（如肝脏）的强化程度及患者体重密切相关", "E": "个体化方案要求多数患者统一使用100 ml 对比剂以便于管理"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-001", "kp": "碘流率与总碘量的个体化方案", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】碘流率描述单位时间进入循环的碘量，直接决定血管腔内瞬时碘浓度，因而是动脉强化峰值的主要决定因素；总碘量描述整次注射的碘负荷，经再循环后分布到实质器官，因而与肝、胰、脾等实质强化程度相关，并应按体重（或去脂体重、体表面积）个体化设定。理解这一分工，才能在\"降低总量\"与\"保证动脉强化\"之间找到平衡。【为什么错】A 遗漏了浓度这一半，同样4 ml/s 下370 mgI/ml 与320 mgI/ml 的碘流率相差约16%。B 二者可以相互替代：提高浓度后反而可以适当降低流率以维持相同碘流率，从而减轻静脉与留置针的压力负荷。C 两个参数的作用对象被完全对调。E 与个体化理念背道而驰，统一固定用量会使体重轻者过量、体重大者强化不足。", "tr": "\"碘流率管血管、总碘量管实质\"是记忆主线；注意还有\"固定注射时间法\"——保持注射持续时间不变而按体重调整总量，可使不同体型患者的强化峰值时间趋于一致。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0129", "t": "单选题", "s": "低管电压与能谱 CT 技术的推广使\"低碘量\"增强扫描成为可能。这一做法的物理基础是", "o": {"A": "把管电压由120 kV 降至70~80 kV，或选择40~50 keV 的低能级虚拟单能量图像时，X线的平均能量更接近碘的 K 吸收缘（33.2 keV），碘的质量衰减系数随之增大、CT 值明显升高，因而可在保证强化效果的前提下减少对比剂用量", "B": "降低管电压提高了碘元素的原子序数", "C": "在虚拟平扫（VNC）图像上碘的 CT 值最高，因而最适合观察强化", "D": "降低管电压使图像噪声下降，所以可以减少碘用量", "E": "能谱 CT 通过提高管电流来实现减碘"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-002", "kp": "低管电压与能谱成像的减碘机制", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】光电效应的发生概率随光子能量降低而急剧增加，并在 K 吸收缘处出现突跃。当X线的平均能量向33.2 keV 靠近时，碘的质量衰减系数显著增大，同样碘浓度可产生更高的 CT 值——70 kV 下碘的 CT 值约为120 kV 下的1.7 倍，40 keV 虚拟单能量图像的增益更大。据此可等比例削减对比剂用量，同时低管电压还降低了辐射剂量，代价是图像噪声上升，需以迭代重建或提高管电流予以补偿。【为什么错】B 原子序数是元素固有属性，不会因管电压改变而改变，属概念性错误。C 虚拟平扫的定义正是从能谱数据中去除碘的贡献，碘在其上的 CT 值最低而非最高，它用于替代真正的平扫以降低总剂量。D 因果颠倒：降低管电压会使噪声升高而非下降；减碘的依据是碘对比度提升，而不是噪声降低。E 提高管电流只增加光子数量、降低噪声，并不改变能谱位置与碘的衰减特性，因此不构成减碘的物理基础。", "tr": "低 kV／低 keV 提升的是碘的\"对比度\"，同时带来噪声上升，必须与迭代重建、管电流补偿配套使用；把 VNC 与碘图（iodine map）的用途弄反也是高频错点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-0130", "t": "多选题", "s": "关于对比剂的研究方向与临床应用进展，下列表述正确的有", "o": {"A": "血池型 MR 对比剂（如与白蛋白结合率高的钆剂）在血管内滞留时间长，可实现稳态期高分辨率 MR 血管成像", "B": "肝细胞特异性对比剂使一次检查同时获得动态期与肝细胞期信息，有助于小肝癌与局灶性结节增生等病变的鉴别", "C": "出于对钆沉积的关注，临床倾向于优先选用大环类制剂，并遵循最低有效剂量、避免不必要增强的原则", "D": "靶向分子影像对比剂通过特异性配体与受体或抗原结合，实现分子水平成像，目前多数仍处于研究阶段", "E": "含碘对比剂目前已可被钆对比剂完全替代用于 CT 增强检查"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-003", "kp": "对比剂研究与应用的主要进展方向", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】A 血池对比剂与白蛋白可逆结合，分子有效体积增大、血管内滞留时间延长，可在首过之后的稳态期进行长时间高分辨采集，特别适合外周血管与冠状动脉成像。B 一次注射兼得血流动力学与肝细胞功能两类信息，是肝脏 MRI 近十余年最重要的进展之一。C 这是各国指南与临床实践的一致趋势，也是技师在方案沟通中应主动坚持的原则。D 靶向对比剂把成像从解剖、功能推进到分子层面，目前多数尚处临床前或早期临床研究阶段，这一\"发展阶段\"的定位是命题常考点。【为什么错】E 钆的原子序数为64，虽然在X线下也有衰减能力，但要达到与碘剂相当的强化效果所需摩尔量远超安全剂量，会带来严重的肾毒性与 NSF 风险，因此绝不能常规替代碘剂用于 CT 增强；仅在极特殊情况下由临床权衡后个案考虑。", "tr": "\"了解\"层次的进展类考点重在方向与定位，不必死记具体商品名；但\"钆剂不能替代碘剂做 CT\"属安全底线，必须掌握。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-0131", "t": "案例分析题", "s": "某院新引进能谱 CT 并着手推行个体化对比剂方案。一名体重50 kg 的女性患者需行以门静脉期为主的上腹部增强 CT；既往一次增强检查后肝脏强化良好，但检查后48 h 复查发现血肌酐一过性轻度升高，此后自行恢复。科室现有320 mgI/ml 与370 mgI/ml 两种非离子型对比剂，注射器支持多段编程。作为技师，较为合理的方案是", "o": {"A": "选用370 mgI/ml 并固定给药100 ml，以保证强化效果", "B": "通过延长注射时间来降低碘流率，这样既能减少总碘量又能提高动脉强化峰值", "C": "以虚拟平扫（VNC）图像替代增强扫描来评价门静脉", "D": "采用低管电压扫描或重建40~50 keV 虚拟单能量图像以提升碘对比，按体重给药（约0.4~0.5 gI/kg）并选用320 mgI/ml 制剂适当降低总量，采用固定注射时间以保证碘流率稳定，同时在检查前后适当水化并随访肾功能", "E": "在减少对比剂总量的同时把管电压提高到140 kV，以补偿强化程度的下降"}, "d": "中", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-004", "kp": "能谱 CT 条件下的个体化低碘量方案", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】该患者体重轻且有对比剂后肾功能一过性波动史，属需要控制碘负荷的人群。合理方案是从两端同时着手：一方面用低管电压或低 keV 虚拟单能量图像提升碘的 CT 值，为减量创造条件；另一方面按体重设定总碘量（上腹部实质强化常按0.4~0.5 gI/kg），选用浓度较低的320 mgI/ml 制剂便于在小体重患者中精细调节，并采用固定注射时间法保证碘流率与峰值时间的一致性。同时按肾损伤风险管理原则给予适当水化并随访肾功能。【为什么错】A 固定100 ml 对50 kg 患者明显超量，与个体化原则和既往肾功能波动史都相冲突。B 前后自相矛盾：延长注射时间会降低碘流率，动脉强化峰值随之下降而非提高。C 虚拟平扫是从增强数据中减去碘信号得到的\"平扫\"图像，本身不含血管强化信息，根本无法评价门静脉。E 提高管电压会使X线平均能量远离碘的 K 吸收缘，碘的 CT 值下降，与减碘目标完全相反；正确方向恰恰是降低管电压。", "tr": "减碘的三条腿是\"低 kV／低 keV＋按体重给药＋固定注射时间\"；同时须记住降低 kV 后噪声上升，应配合迭代重建或适度提高管电流，不能只减不补。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1001", "t": "单选题", "s": "下列属于离子型高渗X线对比剂的是", "o": {"A": "泛影葡胺（复方泛影葡胺）", "B": "碘海醇", "C": "碘帕醇", "D": "碘克沙醇", "E": "碘普罗胺"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-001", "kp": "X线对比剂分类", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】泛影葡胺为离子型单体对比剂，在溶液中解离为离子，渗透压高，属高渗对比剂。【为什么错】B碘海醇、C碘帕醇、E碘普罗胺均为非离子型单体对比剂；D碘克沙醇为非离子型二聚体等渗对比剂。", "tr": "“泛影葡胺＝离子型高渗”是最基础的对应关系，与非离子型代表药区分记忆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1002", "t": "单选题", "s": "下列属于非离子型单体低渗X线对比剂的是", "o": {"A": "碘海醇", "B": "泛影葡胺", "C": "碘克沙醇", "D": "硫酸钡", "E": "空气"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-002", "kp": "X线对比剂分类", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】碘海醇（欧乃派克）为非离子型单体，溶液不解离，渗透压约为血浆两倍，属低渗对比剂。【为什么错】B泛影葡胺为离子型高渗；C碘克沙醇为非离子型二聚体等渗；D硫酸钡为胃肠道阳性对比剂；E空气为阴性对比剂。", "tr": "非离子型单体（碘海醇、碘帕醇、碘普罗胺等）是当前临床最常用的一类。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1003", "t": "单选题", "s": "下列X线对比剂中渗透压与血浆接近、为等渗对比剂的是", "o": {"A": "碘克沙醇", "B": "泛影葡胺", "C": "碘海醇", "D": "碘帕醇", "E": "碘佛醇"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-003", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】碘克沙醇（威视派克）为非离子型二聚体，在水中不解离且分子较大，渗透压约290mOsm/kg，与血浆相近，为等渗对比剂。【为什么错】B泛影葡胺为离子型高渗；C、D、E为非离子型单体低渗（约为血浆两倍）。", "tr": "渗透压排序：离子型单体＞非离子型单体＞非离子型二聚体（等渗）。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1004", "t": "单选题", "s": "下列X线对比剂按渗透压由高到低排列，正确的是", "o": {"A": "泛影葡胺＞碘海醇＞碘克沙醇", "B": "碘克沙醇＞碘海醇＞泛影葡胺", "C": "碘海醇＞泛影葡胺＞碘克沙醇", "D": "碘克沙醇＞泛影葡胺＞碘海醇", "E": "三者在渗透压上相同"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-004", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】离子型单体（泛影葡胺）在水中解离成阳离子与阴离子，渗透压最高（约5倍于血浆）；非离子型单体（碘海醇）不解离，渗透压低（约2倍血浆）；非离子型二聚体（碘克沙醇）为等渗。【为什么错】B、C、D的排序均与上述规律不符；E三种渗透压不同。", "tr": "渗透压毒性是高渗对比剂不良反应的主要机制，等渗剂肾毒性相对更低。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1005", "t": "单选题", "s": "硫酸钡作为胃肠道X线对比剂，其主要优点是", "o": {"A": "原子序数高、不溶于水、不被肠道吸收，显影清晰且安全", "B": "溶于水易于吸收", "C": "可进入血液循环增强血管", "D": "渗透压极高", "E": "可透过血脑屏障"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-005", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】硫酸钡中钡原子序数高（56），阻射X线能力强，且不溶于水、不被吸收，经口服或灌肠在消化道内形成良好对比，使用安全。【为什么错】B硫酸钡不溶于水；C硫酸钡不进入血管，不能增强血管；D其渗透压与毒性不属其特点；E不能透过血脑屏障。", "tr": "硫酸钡只能用于消化道造影，严禁用于血管或椎管等体内注射。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1006", "t": "单选题", "s": "下列属于阴性X线对比剂的是", "o": {"A": "空气（二氧化碳）", "B": "硫酸钡", "C": "泛影葡胺", "D": "碘海醇", "E": "碘克沙醇"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-006", "kp": "X线对比剂分类", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】阴性对比剂为低密度气体（空气、二氧化碳、氧气），在X线片上呈低密度，用于关节腔、消化道等造影。【为什么错】B硫酸钡为阳性对比剂（高密度）；C、D、E碘对比剂均为阳性对比剂。", "tr": "阳性对比剂密度高（钡、碘）、阴性对比剂密度低（气体），二者密度属性相反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1007", "t": "单选题", "s": "碘对比剂含碘量的常用表示单位是", "o": {"A": "mgI/ml", "B": "g/kg", "C": "mOsm/kg", "D": "mol/L", "E": "HU"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-007", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】碘对比剂浓度以单位体积含碘量表示，常用mgI/ml，如300mgI/ml、370mgI/ml。【为什么错】B g/kg为体重剂量单位；C mOsm/kg为渗透压单位；D mol/L为摩尔浓度；E HU为CT值单位。", "tr": "对比剂增强效果取决于碘浓度，mgI/ml数值越高增强越明显。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1008", "t": "单选题", "s": "下列不属于碘对比剂常用引入途径的是", "o": {"A": "皮下注射", "B": "静脉注射", "C": "动脉注射", "D": "口服", "E": "椎管内注射"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-008", "kp": "X线对比剂引入途径", "ch": "四、对比剂 → 1.X线对比剂 → (3)引入途径", "ex": "【为什么对】碘对比剂可经静脉（增强CT、静脉肾盂造影）、动脉（DSA）、口服（胃肠道）及椎管内（脊髓造影）等途径引入。【为什么错】A皮下注射不用于碘对比剂，无诊断意义且易引起局部反应。", "tr": "不同引入途径对应不同检查方法，注意“皮下注射”不属于常规途径。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1009", "t": "单选题", "s": "关于碘对比剂的化学毒性，正确的叙述是", "o": {"A": "与对比剂分子的亲脂性、蛋白质结合能力及电荷等化学特性有关", "B": "仅与渗透压高低有关", "C": "仅由碘原子浓度决定", "D": "与注射速度无关", "E": "只发生于口服途径"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-009", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】化学毒性指对比剂分子本身的化学性质（亲脂性、与蛋白结合能力、电荷等）引起的毒性，与渗透压毒性、离子毒性并列为三大毒性。【为什么错】B化学毒性并非仅由渗透压决定；C碘原子浓度主要决定显影密度；D注射速度影响反应发生程度；E化学毒性可发生于各种注射途径。", "tr": "离子型对比剂含电荷、亲脂性高，化学毒性大于非离子型，这是其不良反应较多的原因之一。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1010", "t": "单选题", "s": "下列不属于造影剂肾病（CIN）高危因素的是", "o": {"A": "肾功能正常且无糖尿病的中青年患者", "B": "既往肾功能不全", "C": "糖尿病", "D": "高龄", "E": "脱水或血容量不足"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-010", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】造影剂肾病高危因素包括肾功能不全、糖尿病、高龄、脱水、心力衰竭及近期重复使用对比剂等；肾功能正常且无糖尿病的中青年不属于高危人群。【为什么错】B、C、D、E均为公认的CIN高危因素。", "tr": "本题为“否定式”选择，需识别出不属于高危因素的项目。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1011", "t": "单选题", "s": "对肾功能不全的高危患者行增强CT时，预防造影剂肾病的主要措施是", "o": {"A": "选用低渗或等渗对比剂并充分水化", "B": "选用高渗离子型对比剂", "C": "注射前禁止饮水", "D": "加大对比剂剂量", "E": "注射后立即行血液透析"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-011", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】高危患者应优先选择低渗或等渗对比剂，检查前予以充分水化（静脉补液或口服水），以降低造影剂肾病风险。【为什么错】B高渗离子型对比剂肾毒性更大；C脱水是CIN危险因素，不应禁水；D加大剂量增加肾毒性；E常规检查后无需常规透析，预防重点在水化与剂型选择。", "tr": "水化＋低渗/等渗剂是CIN预防的两大核心措施。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1012", "t": "单选题", "s": "碘对比剂轻度不良反应的常见表现是", "o": {"A": "荨麻疹、恶心、喷嚏、面部潮红", "B": "血压测不出", "C": "呼吸心跳骤停", "D": "喉头水肿窒息", "E": "昏迷抽搐"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-012", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】轻度不良反应多为皮肤黏膜表现，如荨麻疹、恶心、喷嚏、面部潮红、皮肤瘙痒等，多可自行缓解或对症处理。【为什么错】B、C、D、E均属中重度反应（过敏性休克、喉头水肿、呼吸心搏骤停等）的危急表现。", "tr": "反应分级：轻度（皮肤黏膜）→中度（支气管痉挛、心动过速）→重度（休克、喉头水肿、呼吸停止）。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1013", "t": "单选题", "s": "碘对比剂所致过敏性休克的首选抢救药物是", "o": {"A": "肾上腺素（0.1%溶液肌内注射）", "B": "地西泮静脉注射", "C": "口服扑尔敏", "D": "阿托品皮下注射", "E": "硝酸甘油舌下含服"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-013", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】过敏性休克时首选肾上腺素（0.1%肾上腺素0.3～0.5mg肌内注射，可重复），并配合高流量吸氧、快速补液及糖皮质激素等。【为什么错】B地西泮为镇静药，不用于抗休克；C口服药起效慢，不适合抢救；D阿托品用于心动过缓；E硝酸甘油用于心绞痛，不能抗过敏性休克。", "tr": "肾上腺素是过敏性休克的一线抢救药物，剂量与给药途径（肌注）是关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1014", "t": "单选题", "s": "按磁学性质分类，MR对比剂可分为", "o": {"A": "顺磁性、超顺磁性与铁磁性对比剂", "B": "离子型与非离子型对比剂", "C": "单体与二聚体对比剂", "D": "高渗与等渗对比剂", "E": "口服与注射对比剂"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-001", "kp": "MR对比剂发展及分类", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】MR对比剂按磁学性质分为顺磁性（钆类）、超顺磁性（氧化铁类）和铁磁性三类。【为什么错】B、C、D为X线碘对比剂的分类方式；E按引入途径分类并非MR对比剂的主要分类。", "tr": "MR对比剂核心分类是“磁学性质”，与X线对比剂的“离子/渗透压”分类体系不同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1015", "t": "单选题", "s": "下列属于顺磁性MR对比剂代表药物的是", "o": {"A": "钆喷酸葡胺（Gd-DTPA）", "B": "硫酸钡", "C": "泛影葡胺", "D": "碘克沙醇", "E": "二氧化碳"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-002", "kp": "MR对比剂发展及分类", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】钆喷酸葡胺（马根维显）含钆（Gd³⁺）离子，具有顺磁性，是临床应用最广的MR对比剂。【为什么错】B硫酸钡为X线阳性对比剂；C泛影葡胺、D碘克沙醇为X线碘对比剂；E二氧化碳为X线阴性对比剂。", "tr": "“钆＝顺磁性”是MR对比剂的核心记忆点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1016", "t": "单选题", "s": "顺磁性MR对比剂（钆剂）的增强机制是", "o": {"A": "缩短组织的T1弛豫时间，在T1加权像上信号增高", "B": "缩短T2时间，在T2加权像上信号增高", "C": "延长T1时间，信号降低", "D": "与弛豫无关，仅靠密度对比", "E": "只增强骨皮质信号"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-003", "kp": "MR对比剂增强机制", "ch": "四、对比剂 → 2.MR对比剂 → (3)增强机制", "ex": "【为什么对】钆离子有7个不成对电子，磁矩大，邻近水分子质子T1弛豫明显加快，故T1缩短、T1WI信号增高，属阳性增强。【为什么错】B钆剂主要缩短T1而非使T2WI信号增高；C T1缩短而非延长；D增强完全依赖弛豫效应；E钆剂增强软组织与血供，与骨皮质密度无关。", "tr": "顺磁性剂＝T1缩短＝T1WI高信号＝阳性对比剂；超顺磁性剂＝T2缩短＝T2WI低信号＝阴性对比剂。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1017", "t": "单选题", "s": "超顺磁性氧化铁（SPIO）对比剂的增强特点是", "o": {"A": "缩短T2弛豫时间，使T2加权像信号降低，属阴性增强", "B": "缩短T1时间，使T1加权像信号升高", "C": "无任何信号改变", "D": "仅增强血管腔内信号", "E": "使所有组织信号升高"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-004", "kp": "MR对比剂增强机制", "ch": "四、对比剂 → 2.MR对比剂 → (3)增强机制", "ex": "【为什么对】超顺磁性氧化铁颗粒被肝脾网状内皮系统吞噬后，产生局部磁场不均匀，显著缩短T2弛豫，使T2WI上肝脾正常组织信号降低，病灶相对呈高信号，属阴性对比剂。【为什么错】B缩短T1是顺磁性钆剂的作用；C有明确信号改变；D其作用是改变组织信号而非仅血管腔；E其使信号降低而非升高。", "tr": "SPIO曾被用于肝脏特异性MRI，正常肝组织摄取后信号减低，是“阴性增强”代表。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1018", "t": "单选题", "s": "关于钆类MR对比剂与肾功能不全的关系，正确的说法是", "o": {"A": "重度肾功能不全患者使用钆剂可能引起肾源性系统性纤维化（NSF），需慎用或禁用", "B": "肾功能不全患者使用钆剂完全无风险", "C": "钆剂经肺代谢，与肾脏无关", "D": "任何钆剂均可安全用于透析前患者", "E": "钆剂不经过肾脏排泄"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-005", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】线性钆剂在重度肾功能不全患者中清除延迟，可能诱发肾源性系统性纤维化（NSF），故重度肾功能不全者应慎用或禁用钆剂。【为什么错】B肾功能不全使用钆剂有明确风险；C钆剂经肾脏排泄，不经肺代谢；D透析前患者风险更高；E钆剂主要经肾小球滤过排出。", "tr": "NSF是钆剂与肾功能不全相关的重要安全性问题，线性剂风险更高。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1019", "t": "单选题", "s": "关于大环类与线性钆剂稳定性的比较，正确的是", "o": {"A": "大环类结构稳定，钆离子释放少，安全性更高", "B": "线性结构更稳定，钆释放更少", "C": "二者稳定性完全相同", "D": "线性剂在体内无任何解离", "E": "大环类钆剂必然引起NSF"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-006", "kp": "MR对比剂发展及分类", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】大环类（如钆特酸葡胺、钆布醇）将钆离子包绕在环状结构内，解离慢、稳定性高，游离钆释放少；线性剂（如钆喷酸葡胺）稳定性相对较低。【为什么错】B线性剂稳定性较低；C二者稳定性不同；D线性剂在体内存在少量解离；E大环类钆剂NSF风险低，而非必然引起。", "tr": "“大环稳定、线性易解离”是钆剂安全性记忆要点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1020", "t": "单选题", "s": "常规钆剂增强MR扫描中，观察强化组织的首选序列是", "o": {"A": "T1加权成像（T1WI）", "B": "T2加权成像（T2WI）", "C": "弥散加权成像（DWI）", "D": "磁敏感加权成像（SWI）", "E": "质子密度加权成像（PDWI）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-007", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】钆剂缩短T1使强化组织在T1WI上信号增高，故增强扫描平扫与增强均以T1WI为主要观察序列。【为什么错】B T2WI对钆剂增强不敏感；C DWI反映水分子扩散；D SWI显示出血与铁沉积；E PDWI对T1缩短效应不敏感。", "tr": "“钆增强必须看T1WI”与“X线碘对比剂看密度增高”是两类对比剂的核心判读差异。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1021", "t": "单选题", "s": "钆塞酸二钠（Gd-EOB-DTPA）的特殊临床应用价值是", "o": {"A": "被肝细胞特异性摄取，可完成肝胆期成像，提高肝病灶检出", "B": "仅用于脑脊液造影", "C": "用于骨骼显影", "D": "用于肺通气显影", "E": "用于胃肠钡剂双重造影"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-008", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】Gd-EOB-DTPA（普美显）为肝细胞特异性对比剂，经有机阴离子转运体被正常肝细胞摄取并经胆道排泄，可完成动态期与肝胆期成像，提高肝病灶检出与定性能力。【为什么错】B、C、D、E均与该药适应证不符。", "tr": "肝特异性对比剂（Gd-EOB-DTPA、Gd-BOPTA）的“肝胆期”延迟扫描是独特优势。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1022", "t": "单选题", "s": "关于MR血管成像（MRA）对比剂的选择，正确的叙述是", "o": {"A": "常用高浓度钆类对比剂经团注后进行快速MRA采集", "B": "必须使用SPIO对比剂", "C": "必须使用泛影葡胺", "D": "对比剂经口服后行MRA", "E": "MRA不能使用任何对比剂"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-009", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】增强MRA（CE-MRA）常采用高浓度钆剂快速团注，配合快速梯度回波采集，显著提高血管显示。【为什么错】B SPIO为肝脏阴性对比剂，不用于MRA；C泛影葡胺为X线对比剂；D口服对比剂不进入血管；E增强MRA需使用钆剂，非增强MRA（TOF等）则不用。", "tr": "CE-MRA“高浓度钆剂＋快速采集＋屏气”是核心技术要点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1023", "t": "单选题", "s": "关于碘对比剂速发反应与迟发反应的叙述，正确的是", "o": {"A": "速发反应多在注射后1小时内发生，迟发反应多在注射后1小时至1周内发生", "B": "速发反应均在1周后发生", "C": "迟发反应均发生在注射即刻", "D": "二者无时间界限", "E": "迟发反应以过敏性休克为主"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-014", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】速发反应发生于注射后1小时内（多为数分钟内），迟发反应发生于注射后1小时至1周，以皮肤反应为多。【为什么错】B速发反应在1小时内而非1周后；C迟发反应不是注射即刻；D二者有明确时间分界；E过敏性休克属速发反应，迟发反应多为皮肤表现。", "tr": "迟发反应以荨麻疹、斑丘疹等皮肤反应为主，多数轻微可自行消退。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1024", "t": "多选题", "s": "离子型碘对比剂相对于非离子型对比剂的主要缺点包括", "o": {"A": "渗透压高，易引起渗透性不良反应", "B": "分子含电荷，化学毒性较大", "C": "与蛋白质结合能力较强", "D": "水溶性差、显影不良", "E": "完全不引起任何反应"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-015", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】离子型对比剂在水中解离为离子，渗透压高（A）、含电荷（B）、亲脂性较强并与蛋白结合（C），化学毒性较大，不良反应相对多见。【为什么错】D离子型对比剂水溶性好、显影清晰，否则不能作为造影剂使用；E任何对比剂都可能引起不良反应，不可能是“完全不引起”。", "tr": "离子型（高渗、带电、毒性大）与非离子型（低渗、不带电、毒性小）的对比是全考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1025", "t": "多选题", "s": "碘对比剂过敏反应的预防措施包括", "o": {"A": "详细询问药物及碘过敏史", "B": "检查室常规配备急救药品与设备", "C": "对高危患者预防性使用糖皮质激素和抗组胺药", "D": "任意缩短观察时间尽快离室", "E": "对已知严重碘过敏者谨慎评估并权衡利弊"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-016", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】预防措施包括询问过敏史（A）、配备急救设备（B）、高危患者预防用药（C）、已知严重过敏者谨慎评估（E），检查后观察30分钟。【为什么错】D检查后应留观而非缩短观察时间，速发反应多在1小时内出现。", "tr": "预防用药≠绝对安全，抢救设备与留观制度同样重要。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1026", "t": "多选题", "s": "碘对比剂重度不良反应的表现包括", "o": {"A": "喉头水肿导致呼吸困难", "B": "血压骤降甚至休克", "C": "抽搐昏迷", "D": "一过性面部潮红", "E": "呼吸心搏骤停"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-017", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】重度反应包括喉头水肿、支气管痉挛、过敏性休克、抽搐昏迷及呼吸心搏骤停等危及生命的表现。【为什么错】D一过性面部潮红、皮肤瘙痒等属轻度反应，不属于重度反应。", "tr": "反应分级判定是救治决策的前提，轻度可观察，重度需立即启动抢救。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1027", "t": "多选题", "s": "碘对比剂过敏性休克的抢救措施包括", "o": {"A": "立即停止注射对比剂并呼叫急救", "B": "肌内注射0.1%肾上腺素", "C": "高流量吸氧并快速补液", "D": "给予糖皮质激素与抗组胺药", "E": "让患者自行走动缓解紧张"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-018", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】过敏性休克抢救应立即停药（A）、肾上腺素肌注（B）、吸氧补液（C），并联合糖皮质激素、抗组胺药等（D），必要时心肺复苏。【为什么错】E休克患者应平卧保温、保持气道通畅，走动会加重循环衰竭。", "tr": "抢救流程“停药→肾上腺素→吸氧→补液→激素抗组胺→监护”要完整记忆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1028", "t": "多选题", "s": "预防造影剂肾病（CIN）的措施包括", "o": {"A": "检查前后充分水化", "B": "尽量选用低渗或等渗对比剂", "C": "避免与肾毒性药物合用", "D": "短期内避免反复多次使用对比剂", "E": "术前常规停用所有降糖药"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-019", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】CIN预防包括水化（A）、选择低渗/等渗剂（B）、避免与肾毒性药物合用（C）、避免短期内重复检查（D）及评估肾功能等。【为什么错】E“停用所有降糖药”说法绝对，二甲双胍需按肾功能情况评估后决定是否暂停，并非一律停用。", "tr": "二甲双胍与碘对比剂合用可能增加乳酸酸中毒风险，需按肾功能评估，但并非“一律停用”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1029", "t": "多选题", "s": "钆类MR对比剂的临床应用包括", "o": {"A": "中枢神经系统肿瘤增强扫描", "B": "增强MRA（CE-MRA）", "C": "腹部器官动态增强", "D": "胃肠道钡剂双重造影", "E": "关节腔充气造影"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-010", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】钆剂广泛用于中枢神经系统增强（A）、CE-MRA（B）及腹部动态增强（C）等。【为什么错】D胃肠道造影使用硫酸钡；E关节腔充气造影使用气体（阴性对比剂），均与钆剂无关。", "tr": "钆剂增强＝血供丰富组织T1WI高信号，适用范围广但不用于消化道与关节充气。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1030", "t": "多选题", "s": "为降低钆剂相关肾源性系统性纤维化（NSF）风险，应采取的措施包括", "o": {"A": "对重度肾功能不全患者慎用或禁用线性钆剂", "B": "优先选用大环类（环状）高稳定钆剂", "C": "避免在短期内反复大剂量使用钆剂", "D": "检查前常规筛查肾功能", "E": "对肾功能不全患者加倍剂量增强效果"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-011", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】降低NSF风险应筛查肾功能（D）、高危患者避免线性剂（A）、优先大环类（B）、避免反复大剂量使用（C）。【为什么错】E对肾功能不全患者加倍剂量会显著增加钆沉积与NSF风险，属错误做法。", "tr": "肾功能不全者不是“加剂量”，而是“减剂量或不用”，重点在风险评估。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1031", "t": "多选题", "s": "关于超顺磁性氧化铁（SPIO）对比剂，正确的叙述包括", "o": {"A": "主要被肝脾等网状内皮系统吞噬细胞摄取", "B": "通过缩短T2弛豫使正常肝组织信号降低", "C": "属阴性增强对比剂", "D": "使病灶在T2WI上相对呈高信号", "E": "属顺磁性钆类对比剂"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-012", "kp": "MR对比剂增强机制", "ch": "四、对比剂 → 2.MR对比剂 → (3)增强机制", "ex": "【为什么对】SPIO为氧化铁颗粒，被肝脾网状内皮细胞摄取（A），缩短T2使正常肝脾信号降低（B、C），病灶不含吞噬细胞、信号不变，相对呈高信号（D）。【为什么错】E SPIO是超顺磁性氧化铁，不属于钆类顺磁性对比剂。", "tr": "SPIO“正常肝低、病灶相对高”的阴性增强模式曾用于肝脏占位定性。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1032", "t": "多选题", "s": "理想的X线碘对比剂应具备的理化特性包括", "o": {"A": "碘含量高，显影密度好", "B": "渗透压接近血浆", "C": "水溶性好，黏度适宜", "D": "化学毒性小、稳定性好", "E": "可被人体快速吸收代谢为能量"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-020", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】理想碘对比剂应碘含量高（A）、渗透压低（B）、水溶性好黏度适宜（C）、毒性小稳定性好（D）。【为什么错】E对比剂并非营养素，不应被“代谢为能量”，理想的对比剂应不被机体代谢、经肾原形排出。", "tr": "对比剂的理想特性是“高碘、低渗、低毒、稳定、不代谢”，与营养代谢无关。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1033", "t": "多选题", "s": "碘对比剂使用前的准备工作包括", "o": {"A": "核对患者身份与检查目的，告知并签署知情同意", "B": "询问过敏史及肾功能、糖尿病、哮喘等情况", "C": "确认急救药品与抢救设备处于备用状态", "D": "对无静脉通路者预先建立静脉通道", "E": "术前常规做碘过敏皮试"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-021", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】使用前应核对信息与知情同意（A）、评估过敏史与基础疾病（B）、备好急救措施（C）、建立静脉通路（D）。【为什么错】E目前临床已不推荐常规碘过敏皮试，因其预测价值有限且皮试本身有风险，国内现行共识不要求常规皮试。", "tr": "“常规碘皮试”已不再推荐，评估重点转向病史询问与急救准备。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1034", "t": "多选题", "s": "关于碘对比剂迟发不良反应，正确的叙述包括", "o": {"A": "多在注射后1小时至1周内发生", "B": "以皮肤反应（荨麻疹、斑丘疹）最常见", "C": "多数症状轻微，可自行消退", "D": "与造影剂肾病（CIN）无关", "E": "只表现为过敏性休克"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-022", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】迟发反应发生于注射后1小时至1周（A），以皮肤反应最常见（B），多数轻微可自行消退（C）。【为什么错】D CIN多在注射后48～72小时出现血肌酐升高，属迟发性肾毒性表现，与迟发反应相关；E迟发反应并非只表现为过敏性休克，休克多为速发反应。", "tr": "CIN本身即属对比剂迟发不良反应之一，两者概念不矛盾。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1035", "t": "多选题", "s": "静脉注射对比剂发生血管外渗漏（外渗）时的处理措施包括", "o": {"A": "立即停止注射并拔除针头或调整位置", "B": "抬高患肢", "C": "早期冷敷，减轻渗漏肿胀", "D": "密切观察局部皮肤颜色、感觉与活动度", "E": "立即热敷以促进渗漏液吸收"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-023", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】外渗处理应立即停止注射并拔除针头（A）、抬高患肢（B）、早期冷敷减轻肿胀（C）、密切观察局部皮肤颜色、感觉与活动度（D），大量渗漏或出现神经血管损伤症状时应及时请专科处理。【为什么错】E早期应冷敷使局部血管收缩、减轻渗漏扩散；立即热敷会扩张血管、加重肿胀与损伤，为错误做法。", "tr": "外渗“早期冷敷、48小时后可热敷”是处理时间要点，早期热敷是常见错误操作。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U04-1036a", "t": "共用题干题", "s": "该患者目前发生的对比剂不良反应最可能的类型是", "o": {"A": "中度过敏样反应（出现支气管痉挛及血压下降趋势）", "B": "轻度皮肤反应，无需处理", "C": "迟发皮肤反应", "D": "局部外渗", "E": "对比剂肾病"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-013", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】注射后数分钟内出现全身荨麻疹并伴胸闷、气短、血压下降趋势，已达中度过敏样反应，需积极处理。【为什么错】B患者已出现气道与血压受累，非单纯轻度反应；C迟发反应发生于1小时至1周，本例如为5分钟发作属速发；D外渗表现为局部肿痛，与本例全身症状不符；E CIN为肾功能指标变化，非即刻表现。", "tr": "“荨麻疹＋胸闷＋血压下降”提示反应升级，不能按轻度反应对待。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0401", "gs": "患者女，38岁，因椎间盘突出行腰椎MRI增强检查，静脉注射钆对比剂后5分钟出现全身荨麻疹、面部潮红、恶心，伴胸闷、气短，血压90/60mmHg。"}, {"id": "U04-1036b", "t": "共用题干题", "s": "此时技师及医护人员应首先采取的处理措施是", "o": {"A": "停止扫描，保持静脉通路，立即给予高流量吸氧并肌肉注射肾上腺素，同时监测生命体征", "B": "继续完成扫描后再说", "C": "让患者平卧休息自行缓解", "D": "仅口服抗组胺药后离室", "E": "立即静脉推注葡萄糖酸钙观察"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-014", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】中度以上过敏样反应应停止检查、保留静脉通路、吸氧、肌注肾上腺素并监测生命体征，防止进展为休克。【为什么错】B继续扫描延误抢救；C自行缓解有风险，可能发展为重度反应；D口服药起效慢，且不能处理气道与血压问题；E葡萄糖酸钙不是过敏性休克的首选，肾上腺素才是核心药物。", "tr": "抢救原则“停药→肾上腺素→吸氧→补液→监测”，肾上腺素不可被其他药物替代。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0401", "gs": ""}, {"id": "U04-1037a", "t": "共用题干题", "s": "针对该患者，技师及医师在对比剂方案上应作出的决策是", "o": {"A": "评估后选用等渗或低渗对比剂，控制剂量，检查前后充分水化", "B": "选用离子型高渗对比剂以保证显影", "C": "不限剂量直接注射", "D": "检查前后不补充液体", "E": "不使用任何预防措施直接检查"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-024", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】肾功能不全合并糖尿病患者为CIN高危人群，应选用低渗或等渗对比剂、控制用量并充分水化，必要时评估停药后继续使用的风险收益。【为什么错】B高渗离子型对比剂肾毒性最大，应避免；C大剂量增加肾毒性；D脱水是CIN危险因素，应补液；E高危患者必须采取预防措施。", "tr": "eGFR<45的中重度肾功能不全者增强CT需权衡利弊，并采用低渗/等渗剂＋水化策略。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0402", "gs": "患者男，68岁，2型糖尿病史10年，血肌酐升高（eGFR 42ml/min/1.73m²），因肺癌术后复查需行胸部增强CT评估纵隔淋巴结。"}, {"id": "U04-1037b", "t": "共用题干题", "s": "关于该患者检查后随访与用药调整，正确的做法是", "o": {"A": "检查后继续鼓励饮水水化，监测肾功能，评估二甲双胍是否暂停", "B": "检查后无需任何观察", "C": "立即重复增强检查", "D": "暂停一切降压药物", "E": "术后完全禁水"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-025", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】检查后应继续水化、监测肾功能（48～72小时血肌酐），并依据肾功能评估二甲双胍是否暂停，避免乳酸酸中毒。【为什么错】B高危患者需随访观察；C短期内重复增强增加肾毒性；D降压药不应一律停用；E禁水与预防CIN矛盾。", "tr": "二甲双胍与碘对比剂联用需按eGFR评估是否暂停，且复查时机有明确规定。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0402", "gs": ""}, {"id": "U04-1038a", "t": "共用题干题", "s": "为兼顾病灶血供评估与肝细胞来源判断，技师宜选用的对比剂是", "o": {"A": "肝细胞特异性对比剂钆塞酸二钠（Gd-EOB-DTPA）", "B": "硫酸钡", "C": "泛影葡胺", "D": "碘克沙醇", "E": "空气"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-015", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】Gd-EOB-DTPA既能行动态增强观察血供，又能经肝细胞摄取完成肝胆期成像，可判断结节是否为肝细胞来源。【为什么错】B硫酸钡为消化道X线对比剂；C、D为X线碘对比剂；E空气为阴性对比剂，均无MR肝胆特异性。", "tr": "肝特异性对比剂的价值在于“肝胆期”信号判断，可辅助区分再生结节、肝癌等病变。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0403", "gs": "患者男，60岁，慢性乙肝肝硬化，超声发现肝右叶结节，性质待定，拟行肝脏MRI增强检查，临床要求明确结节是否肝细胞来源。"}, {"id": "U04-1038b", "t": "共用题干题", "s": "该患者注射肝特异性对比剂后，完成肝胆期成像的最佳延迟时间是", "o": {"A": "注射后约20分钟（肝胆期延迟扫描）", "B": "注射后1分钟", "C": "注射后3天", "D": "立即扫描无需等待", "E": "注射前扫描"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-016", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】Gd-EOB-DTPA经肝细胞摄取并排入胆道需一定时间，通常在注射后约20分钟（10～20分钟范围）行肝胆期T1WI扫描。【为什么错】B 1分钟内为动脉期，非肝胆期；C 3天过晚，对比剂已大部排出；D肝胆期需等待摄取；E注射前无增强作用。", "tr": "“动态期＋肝胆期”双期成像是肝特异性对比剂检查方案的核心。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0403", "gs": ""}, {"id": "U04-1039a", "t": "共用题干题", "s": "技师应首先采取的措施是", "o": {"A": "立即停止注射，保留针头回抽渗漏液后拔除针头", "B": "继续把剩余对比剂注完", "C": "加大流速快速注射", "D": "热敷促进吸收", "E": "让患者活动患肢促进循环"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-026", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】发现外渗应立即停止注射，尽量回抽渗漏的对比剂后拔针，再行后续处理。【为什么错】B继续注射会加重外渗；C加大流速加剧渗漏；D早期应冷敷而非热敷；E活动患肢会加重肿胀。", "tr": "外渗处理第一步永远是“停止注射”，先回抽再拔针可减少渗漏量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0404", "gs": "患者女，50岁，行增强CT时高压注射器注射对比剂约20ml后，注射部位出现明显肿胀、疼痛，穿刺点周围皮肤苍白，疑似对比剂血管外渗。"}, {"id": "U04-1039b", "t": "共用题干题", "s": "关于外渗后的局部处理与观察，正确的是", "o": {"A": "抬高患肢，早期冷敷，密切观察皮肤颜色、肿胀范围及末梢循环", "B": "患肢下垂促进回流", "C": "立即热敷并按摩", "D": "无需观察自行恢复", "E": "加用高渗盐水局部注射"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-027", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】外渗后应抬高患肢、早期冷敷，并动态观察局部皮肤颜色、肿胀范围、疼痛与末梢循环情况。【为什么错】B患肢下垂不利于静脉回流；C早期热敷与按摩会加重损伤；D大量渗漏可能引起组织坏死，必须观察随访；E局部注射高渗盐水无依据且有风险。", "tr": "大量外渗（如>50ml）或出现水疱、皮肤苍白、神经症状时应请专科（整形/手外科）会诊。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0404", "gs": ""}, {"id": "U04-1040", "t": "案例分析题", "s": "患者男，45岁，增强CT静脉注射碘对比剂后约2分钟出现剧烈胸闷、呼吸困难、大汗、口唇发绀，血压70/40mmHg，心率130次/分。技师及在场医护需立即组织抢救。关于抢救处理，正确的做法是", "o": {"A": "立即停止检查，保持静脉通路，高流量吸氧，快速肌注0.1%肾上腺素并快速补液", "B": "让患者自行平卧休息观察", "C": "只口服抗组胺药后嘱其离开", "D": "立即静脉注射造影剂补充血容量", "E": "嘱患者大量饮水促进排泄"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-028", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】本例为过敏性休克表现，应立即停药、吸氧、肌注肾上腺素、快速补液，并按需给予糖皮质激素与抗组胺药，必要时心肺复苏。【为什么错】B休克不处理可致死亡；C口服药起效慢且已出现休克，需静脉/肌注药物；D再注射对比剂会加重过敏；E饮水不能纠正休克。", "tr": "过敏性休克的黄金处理是“肾上腺素＋吸氧＋补液”，时间就是生命。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U04-1041", "t": "案例分析题", "s": "患者女，63岁，糖尿病肾病（eGFR 38ml/min/1.73m²），因下肢动脉闭塞拟行下肢CTA，需使用碘对比剂。关于该患者的对比剂应用策略，正确的是", "o": {"A": "权衡利弊后选用低渗或等渗对比剂，控制总量，检查前后充分水化，必要时行预防性评估", "B": "因肾功能差而加大对比剂剂量", "C": "使用离子型高渗对比剂", "D": "检查前禁饮禁食以减少不良反应", "E": "检查后立即行血液透析清除对比剂"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-029", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】对中重度肾功能不全者，应权衡CTA的必要性，若必须检查则选用低渗/等渗剂、控制总量并充分水化，最大程度降低CIN风险。【为什么错】B加大剂量增加肾毒性；C高渗剂风险最高；D脱水是CIN危险因素，应补液而非禁饮；E透析并非常规预防手段，且不能在注射后立即清除全部对比剂。", "tr": "CTA有临床指征时仍可进行，关键是“低渗/等渗＋限量＋水化”的综合策略。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U04-1043", "t": "案例分析题", "s": "患者男，55岁，多发性硬化患者需行头颅MRI增强随访，既往对钆剂无过敏史，但血肌酐轻度升高（eGFR 52ml/min/1.73m²）。关于该患者钆剂使用的评估，正确的是", "o": {"A": "评估获益与风险，尽量选用大环类高稳定钆剂并避免重复大剂量使用", "B": "完全禁用任何钆剂", "C": "加倍剂量以保证强化", "D": "使用线性钆剂并增加剂量", "E": "无需考虑肾功能因素"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-017", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】中度肾功能不全（eGFR 30～60）患者应谨慎评估钆剂使用，尽量选择大环类高稳定剂、单次标准剂量、避免短期内重复使用。【为什么错】B中度肾功能不全并非绝对禁忌，需权衡利弊；C加倍剂量增加钆沉积风险；D线性剂稳定性低、风险更高；E肾功能是钆剂安全的重要考量。", "tr": "eGFR<30的重度肾功能不全者禁用线性钆剂，大环类也需谨慎评估。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U04-1044", "t": "案例分析题", "s": "患儿男，6岁，16kg，疑颅内占位，拟行头颅增强CT。按体重给药的原则，若采用2ml/kg的对比剂剂量，则本患儿应使用的对比剂总量约为", "o": {"A": "32ml", "B": "16ml", "C": "50ml", "D": "8ml", "E": "80ml"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-031", "kp": "X线对比剂引入途径", "ch": "四、对比剂 → 1.X线对比剂 → (3)引入途径", "ex": "【为什么对】对比剂总量＝体重×每公斤剂量＝16kg×2ml/kg＝32ml。【为什么错】B 16ml为1ml/kg剂量；C、D、E的数值与按体重计算不符。", "tr": "儿童碘对比剂按体重（1.5～2ml/kg）计算，成人则按固定方案（如60～100ml）并结合体重调整。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U04-1045", "t": "案例分析题", "s": "患者男，48岁，肝细胞癌拟行钆塞酸二钠增强MRI，技师制定了“平扫＋动态增强（动脉期、门静脉期、过渡期）＋肝胆期延迟扫描”的方案。关于该方案的核心技术要点，正确的是", "o": {"A": "动态增强采用T1WI快速序列捕捉动脉期，肝胆期于注射后约20分钟采集", "B": "全程用T2WI观察强化", "C": "肝胆期于动脉期同时完成", "D": "只做平扫即可诊断", "E": "对比剂口服后立即扫描"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-018", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】肝特异性对比剂检查需T1WI动态多期捕捉血供（动脉期、门静脉期），并经约20分钟延迟行肝胆期成像，双期相结合用于病灶定性。【为什么错】B强化观察必须用T1WI；C肝胆期需等待肝细胞摄取，与动脉期不同时；D平扫无法评估血供与肝细胞功能；E钆剂经静脉注射，非口服。", "tr": "“T1WI动态期＋肝胆期”是肝特异性对比剂检查的两大组成部分。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1046", "t": "案例分析题", "s": "患者女，42岁，行子宫输卵管造影（HSG）检查，注射含碘对比剂后出现轻微恶心、面部潮红及一过性咳嗽，血压、心率正常。正确的处理是", "o": {"A": "密切观察，暂停操作，安慰患者，多数轻微反应可自行缓解，必要时对症处理", "B": "立即肌注肾上腺素", "C": "立即行心肺复苏", "D": "加大对比剂剂量继续检查", "E": "让患者立即离室回家"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-032", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】轻度反应（恶心、潮红、一过性咳嗽）且生命体征平稳时，应暂停操作、密切观察并安慰患者，多数自行缓解。【为什么错】B肾上腺素用于中重度反应；C心肺复苏针对心搏骤停；D增加剂量加重反应；E轻度反应也需留观，确认缓解后再离室。", "tr": "轻度反应“观察为主”，但要警惕从轻度升级为中重度，需持续监测。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-1047", "t": "案例分析题", "s": "患者男，70岁，前列腺癌术后拟行全身骨扫描外的盆腔增强MR评估，患者eGFR 25ml/min/1.73m²（重度肾功能不全）。关于该患者使用钆剂的决策，正确的是", "o": {"A": "优先考虑不使用钆剂的MR平扫方案，确需增强时由临床与影像科权衡风险，慎用或选用最安全策略", "B": "常规使用线性钆剂", "C": "加倍剂量使用钆剂", "D": "忽略肾功能直接增强", "E": "使用泛影葡胺替代钆剂"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-019", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】重度肾功能不全（eGFR<30）使用钆剂有NSF风险，应尽量采用无增强的替代方案，确需增强时由多学科权衡并选择风险最低的策略。【为什么错】B线性钆剂在重度肾功能不全者中风险最高，应避免；C加倍剂量显著增加风险；D忽略肾功能不符合安全原则；E泛影葡胺为X线对比剂，不用于MR。", "tr": "eGFR<30是钆剂（尤其线性剂）使用的“红线”，NSF风险是核心考量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U04-9005", "t": "单选题", "s": "与非离子型低渗碘对比剂相比，等渗碘对比剂（如碘克沙醇）的主要优势是", "o": {"A": "含碘量更高、增强更明显", "B": "渗透压与血浆等渗，可降低高渗相关的血管内皮损伤与不良反应", "C": "价格更低廉、更适合大规模使用", "D": "可经口服给药", "E": "代谢更快、不经肾脏排泄"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-009", "kp": "等渗碘对比剂优势", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】B正确——等渗对比剂渗透压约 290 mOsm/kg，与血浆等渗，较传统低渗对比剂（约 600–800 mOsm/kg）更接近生理，可减轻血管内皮细胞脱水损伤、红细胞变形及肾髓质缺氧，降低对比剂肾病与过敏样反应风险。【为什么错】A含碘量并非等渗剂独有优势；C等渗剂通常价格更高；D碘对比剂均不口服用于血管内增强（消化道造影另论）；E仍需经肾排泄。", "tr": "等渗≠\"无肾毒性\"，仅降低渗透压相关风险，仍须水化与评估肾功能。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "对比剂的进展", "页": 118}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-9006", "t": "单选题", "s": "钆对比剂（GBCA）按配体结构分为线性和大环类，关于其安全性的正确表述是", "o": {"A": "线性对比剂比大环类更稳定，游离钆释放更少", "B": "大环类对比剂因配体包裹更紧密，游离钆释放更少、NSF 风险相对更低", "C": "两类在稳定性与 NSF 风险上无差异", "D": "线性对比剂完全不释放游离钆，可安全用于重度肾功能不全", "E": "大环类对比剂禁止用于估算肾小球滤过率＜30 的患者"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-010", "kp": "钆对比剂结构分类与安全", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】B正确——大环类（如钆特酸、钆布醇）配体将钆离子紧密包裹，热力学与动力学稳定性高，游离钆释放极少；线性非离子型（如钆双胺）稳定性相对较低，在肾功能不全者中 NSF 风险更高，故指南更推荐大环类用于高危人群。【为什么错】A事实相反；C忽略稳定性差异；D线性剂仍可能释放游离钆，重度肾功能不全须严格评估并首选大环类或不增强；E大环类在 eGFR＜30 仍可用但需权衡，并非绝对禁止。", "tr": "易记反\"线性/大环\"的稳定性高低；且 NSF 风险与肾功能不全程度强相关。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "对比剂的进展", "页": 118}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-9007", "t": "单选题", "s": "钆塞酸二钠（Gd-EOB-DTPA）作为肝细胞特异性 MR 对比剂，其特有的优势是", "o": {"A": "仅用于中枢神经系统增强", "B": "兼具细胞外非特异性分布与肝胆期肝细胞摄取，可显示肝细胞功能并检出小肝癌", "C": "完全不经肾脏排泄", "D": "显影时间不受肝功能影响", "E": "可用于所有肾功能不全患者无需评估"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-011", "kp": "肝细胞特异性对比剂", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】B正确——钆塞酸二钠约 50% 经肝细胞摄取并经胆汁排泄，注射后约 20 分钟进入肝胆期，正常肝实质明显强化而肝内病灶（如小肝癌、转移瘤）因缺乏摄取呈低信号，兼具动态期与肝胆期信息，提高小病灶检出与定性。【为什么错】A其并不限于中枢；C仍有约半数经肾排泄；D肝胆期摄取依赖肝功能，重度肝病患者肝胆期弱化；E仍含钆，须评估肾功能与 NSF 风险。", "tr": "肝胆期依赖肝细胞功能，肝功能严重受损时该优势减弱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "对比剂的进展", "页": 118}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-9008", "t": "单选题", "s": "近年来对比剂研发的进展方向不包括以下哪项", "o": {"A": "高浓度、低黏度以优化注射与增强", "B": "等渗或近等渗以降低不良反应", "C": "器官/组织特异性靶向对比剂（如肝细胞、血池、CEST）", "D": "提高碘对比剂的放射剂量以增强 CT 成像", "E": "生物可降解或生物相容性更好的新型材料"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-012", "kp": "对比剂研发方向", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】D正确——对比剂研发追求\"更低风险、更高特异性\"，提高放射剂量既不必要也违背 ALARA 与防护原则；CT 增强靠碘浓度与团注而非提高射线剂量。【为什么错】A、B、C、E均为实际研发方向：高浓度低黏度便于大剂量高速注射，等渗降低渗透压损伤，靶向对比剂拓展功能成像，可降解/高生物相容材料减少长期沉积与毒性担忧。", "tr": "易把\"提高图像质量\"误认为\"提高射线剂量\"，防护原则恰相反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "对比剂的进展", "页": 118}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-9201", "t": "单选题", "s": "碘对比剂按渗透压分类，等渗对比剂相对于高渗对比剂的主要优点是", "o": {"A": "血管内更安全、不良反应更少", "B": "价格更低", "C": "显影更弱", "D": "半衰期更长", "E": "无需过敏试验"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-9201", "kp": "碘剂渗透压", "ch": "四、对比剂 → 3.对比剂的进展", "ex": "【为什么对】等渗（如碘克沙醇）渗透压接近血浆，血管内耐受性更好、不良反应较少。\n【为什么错】价格与显影强度并非其优点。", "tr": "等渗碘剂更安全。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U04-9202", "t": "单选题", "s": "钆对比剂用于 MRI 增强的机制是", "o": {"A": "缩短周围质子 T1 弛豫时间", "B": "延长 T1", "C": "延长 T2", "D": "产生电离", "E": "吸收 X 线"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-9202", "kp": "钆剂机制", "ch": "四、对比剂 → 3.对比剂的进展", "ex": "【为什么对】钆为顺磁性，缩短 T1 使强化组织在 T1WI 呈高信号。\n【为什么错】钆缩短而非延长弛豫，不吸收X线。", "tr": "钆剂缩短T1。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0101", "t": "单选题", "s": "关于影像质量保证（QA）与影像质量控制（QC）的相互关系，下列表述正确的是", "o": {"A": "QC 是管理层面的组织性活动，QA 是技术层面的具体测量手段", "B": "QA 是有计划、有系统的全面管理活动，QC 是其中以技术手段监测并维持设备与图像性能的具体措施", "C": "QA 与 QC 内涵完全相同，只是中英文译法不同", "D": "QA 由设备工程师独立负责，QC 由医院行政管理部门负责", "E": "QA 只针对影像设备性能，QC 只针对图像的主观评价"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-001", "kp": "质量保证与质量控制的概念关系", "ch": "五、影像质量管理 → 1.概述 → (1)基本概念", "ex": "【为什么对】B 正确。质量保证（Quality Assurance，QA）是为使影像诊断达到预期质量目标而开展的有计划、有系统的全面管理活动，涵盖组织架构、规章制度、人员培训、设备采购与验收、检查流程、患者剂量管理与结果评价等，属于\"体系\"层面；质量控制（Quality Control，QC）是 QA 体系中的技术执行环节，通过对设备性能与图像指标的定期检测、校准、评价与纠正，把技术参数维持在规定容许范围内，属于\"指标\"层面。二者是包含关系，QC 从属并服务于 QA。【为什么错】A 把两者层次完全颠倒。C 二者外延与工作方式不同，不是同义词。D 职责划分错误：QA 需管理层主导、全员参与，QC 主要由技师与工程技术人员执行。E 两者的作用对象都同时包括设备、技术、图像与流程，不存在这种机械分工。", "tr": "记忆口诀\"QA 是纲、QC 是目；QA 建体系、QC 控指标\"。命题常反向设问\"QC 包含 QA\"或把两者的层次互换来设陷。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0102", "t": "多选题", "s": "科室拟用 PDCA 循环推进影像质量持续改进，下列关于 PDCA 各阶段的表述正确的有", "o": {"A": "P（Plan）阶段包括现状调查、原因分析、确定主要原因并制定针对性对策与目标", "B": "D（Do）阶段是按既定对策组织实施，并做好过程记录", "C": "C（Check）阶段是用数据对实施效果进行检查、与目标值对比并总结", "D": "A（Action）阶段将证实有效的措施标准化固化，未解决的问题转入下一个循环", "E": "PDCA 完成一次循环即达到质量目标，无须重复运行"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-002", "kp": "PDCA 循环与质量管理方法", "ch": "五、影像质量管理 → 1.概述 → (2)管理方法", "ex": "【为什么对】A、B、C、D 均正确。PDCA（戴明环）是全面质量管理的基本工作程序：计划（Plan）阶段完成现状分析、原因剖析、要因确认与对策制定；实施（Do）阶段按计划执行并留痕；检查（Check）阶段用客观数据评价效果；处理（Action）阶段把有效经验标准化写入操作规程，把遗留问题带入下一循环。【为什么错】E 错误。PDCA 的本质特征是\"周而复始、螺旋式上升\"，每转一圈质量水平提升一个台阶，遗留问题成为下一循环的输入，不存在\"一次循环即告完成\"的情形。", "tr": "易混点在 C 与 A 的界限：Check 只做效果验证与数据比对，把\"标准化、纳入规程\"错记到 Check 阶段是常见失分点，标准化属于 Action。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-0103", "t": "单选题", "s": "下列关于影像质量主观评价方法（含 ROC 分析）的描述，正确的是", "o": {"A": "视觉评价法客观性强，评价结果基本不受观察者经验影响", "B": "ROC 曲线以真阳性率为纵坐标、假阳性率为横坐标，曲线下面积（AUC）越大诊断效能越高", "C": "ROC 分析因使用了统计计算，应归入客观评价法", "D": "主观评价法带有观察者因素，现已被客观物理测量完全取代", "E": "ROC 曲线越靠近坐标图右下角，说明成像系统的诊断效能越好"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-003", "kp": "主观评价法与 ROC 分析", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】B 正确。受试者操作特性（ROC）曲线以真阳性率（灵敏度）为纵轴、假阳性率（1-特异度）为横轴，通过改变判断阈值得到一条曲线；曲线下面积 AUC 取值 0.5～1.0，0.5 相当于随机猜测、无诊断价值，越接近 1.0 诊断效能越高。【为什么错】A 视觉评价（解剖部位显示评分法、五分法等）依赖观察者经验、心理状态与阅片环境，重复性相对较差。C ROC 的原始数据来自观察者的判断，属主观（观察者）评价范畴，只是用统计学方法加以量化。D 主观评价最贴近临床诊断需求，与客观评价互为补充，并未被取代。E 方向错误，ROC 曲线越靠近左上角（高灵敏度、低假阳性）效能越好。", "tr": "ROC 有 AUC 这样的量化指标，极易被误判为客观评价法。客观评价指的是分辨率、噪声、对比度、伪影等物理量的仪器测量；ROC 属于以观察者为核心的主观评价。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0104", "t": "多选题", "s": "影像质量的综合评价把物理测量与观察者判断结合起来，下列关于综合评价指标的表述正确的有", "o": {"A": "对比度-细节（C-D）曲线用 C-D 体模测定不同直径细节被察觉所需的最低对比度，曲线越靠近坐标原点系统性能越好", "B": "量子探测效率 DQE 综合了调制传递函数 MTF、噪声功率谱 NPS 与入射光子数，反映系统对入射 X 线量子信息的利用效率", "C": "综合评价法兼顾物理指标与视觉察觉能力，比单纯客观或单纯主观评价更贴近临床实际", "D": "DQE 的理论最大值为 1（100%），实际探测器的 DQE 小于 1 且随空间频率升高而下降", "E": "C-D 曲线只反映系统的空间分辨率，与图像噪声水平无关"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-004", "kp": "综合评价法：C-D 曲线与 DQE", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】A 正确：C-D 体模由一系列直径递减、对比度递减的圆孔阵列构成，观察者标出可分辨的最小圆孔，连线即 C-D 曲线；越靠近原点表示越小的细节、越低的对比度也能被察觉，系统越好。B 正确：DQE(f)=MTF²(f)/[NNPS(f)·q]，同时包含信号传递能力、噪声特性与入射量子数。C 正确：综合评价的价值就在于把物理性能折算为\"能否被人眼在临床条件下察觉\"。D 正确：DQE 是输出 SNR² 与输入 SNR² 之比，理想探测器为 1，实际系统因量子损失、结构噪声与散射恒小于 1，并随空间频率升高而衰减。【为什么错】E 错误：C-D 曲线本质是低对比可探测度评价，噪声直接决定小细节能否被察觉，曲线同时受分辨率与噪声共同支配，剂量降低时曲线会明显右上移。", "tr": "把 C-D 曲线当成纯粹的分辨率体模是常见误解。区分方法：线对卡测的是高对比空间分辨率；C-D 体模测的是低对比可探测度，对噪声极敏感。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U05-0105", "t": "单选题", "s": "使用富士（Fujifilm）CR 系统时，读取后显示的 S 值（Sensitivity value）与影像板接收剂量之间的关系是", "o": {"A": "S 值与接收剂量成正比，S 值越大表示曝光越充分", "B": "S 值与接收剂量成反比，标准曝光条件下 S 值约为 200", "C": "S 值与接收剂量无关，仅反映所选用的后处理参数组", "D": "S 值在数值上等于本次曝光所用的管电流量（mAs）", "E": "S 值越小说明曝光不足，应提高曝光条件重新摄影"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-001", "kp": "CR 曝光指数（富士 S 值）", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】B 正确。富士 CR 的 S 值是读取时自动灵敏度调节的输出量，与 IP 板实际接收的 X 线剂量成反比：标准入射剂量（约 1 mR，即约 8.7 μGy）对应 S≈200；剂量增加一倍，S 值约降为一半。S 值明显升高提示曝光不足、量子噪声增大；S 值明显偏低提示过度曝光、患者剂量偏高。【为什么错】A 方向相反。C S 值直接由 IP 板接收剂量决定，虽受读取参数影响但绝非与剂量无关。D S 值受 kV、体厚、SID、滤线栅等共同影响，与 mAs 没有等量关系。E 方向说反，S 值越小说明接收剂量越高。", "tr": "富士与柯尼卡的 S 值\"数值越大越欠曝\"，而爱克发 lgM、锐珂 EI、飞利浦 EI 以及 IEC 62494 标准 EI 都是\"数值越大越过曝\"，方向相反，是本考点最高频的混淆来源。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0106", "t": "单选题", "s": "某 DR 系统按 IEC 62494 标准同时显示曝光指数 EI 与目标曝光指数 EIT。一次胸部后前位摄影后显示 EI=400、EIT=200，下列判断与处置正确的是", "o": {"A": "偏差指数 DI=10×lg(EI/EIT)≈+3，说明探测器实际接收剂量约为目标值的 2 倍，应下调后续曝光条件", "B": "DI≈-3，说明曝光不足，应提高 mAs 后重新摄影", "C": "DI≈+2，处于理想区间，无须任何处置", "D": "标准 EI 与剂量成反比，EI=400 说明剂量只有目标值的一半", "E": "只要 EI 大于 EIT 就应立即重拍，以保证图像质量"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-002", "kp": "曝光指数 EI 与偏差指数 DI 的应用", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】A 正确。按 IEC 62494-1，偏差指数 DI=10×lg(EI/EIT)=10×lg2≈+3.0。DI 每变化 3 约对应剂量变化一倍，DI≈+3 即实际探测器剂量约为目标值的 2 倍。DI 在 0±1 为理想，±1～±3 需关注，超过 +3 属明显过曝，虽图像可用但违背 ALARA 原则，应回顾并下调曝光条件（如降 mAs 或改用自动曝光控制）。【为什么错】B 符号判断错误，DI 为正值代表过曝。C 计算错误，lg2≈0.301，乘 10 后约为 3 而非 2。D 标准 EI 与探测器校准剂量成正比，这是 IEC 62494 统一方向的核心内容。E 过曝图像通常仍满足诊断要求，重拍只会额外增加受检者剂量，正确做法是保留图像并改进后续参数。", "tr": "\"欠曝可能要重拍、过曝一般不重拍\"是剂量管理的基本原则。另需牢记 DI 的对数关系：DI=+3 对应 2 倍剂量、DI=-3 对应 1/2 剂量，而不是 3 倍或 1/3。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0107", "t": "多选题", "s": "不同厂商数字 X 线设备所用曝光指示量的定义方向并不一致，下列对应关系正确的有", "o": {"A": "富士（Fujifilm）的 S 值与探测器接收剂量成反比", "B": "柯尼卡（Konica）的 S 值同样与探测器接收剂量成反比", "C": "爱克发（Agfa）的 lgM 与接收剂量成正比，且呈对数关系，lgM 增加约 0.30 相当于剂量加倍", "D": "GE 的 DEI（探测器曝光指数）为实测剂量与预期剂量之比，与剂量成正比，理想值接近 1.0", "E": "IEC 62494-1 统一定义的 EI 与探测器校准剂量成反比"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-003", "kp": "各厂家曝光指数体系的方向差异", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】A、B 正确：富士与柯尼卡的 S 值均定义为灵敏度值，剂量越高 S 值越小，标准值约 200。C 正确：爱克发以扫描平均值的对数 lgM 表示，与剂量成正比，因是常用对数刻度，剂量加倍对应 lgM 增加 lg2≈0.30。D 正确：GE 的 DEI 是实测探测器曝光与该解剖部位预期曝光的比值，与剂量成正比，理想值 1.0 附近，偏离越大提示曝光偏差越大。【为什么错】E 错误：IEC 62494-1 统一定义的 EI 与探测器校准剂量成正比（EI=100×g(V)），并配套 EIT 与 DI 使用。正是因为各厂家原有指标量纲与方向混乱、无法横向比较，才制定该国际标准加以统一。", "tr": "记忆分组：\"反比派\"只有富士、柯尼卡的 S 值；爱克发 lgM、锐珂/柯达 EI、飞利浦 EI、西门子 EXI、GE DEI 以及 IEC 标准 EI 都是正比派。考试常把 IEC 标准 EI 说成反比来设陷。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-0108", "t": "单选题", "s": "剂量面积乘积（DAP，亦称 KAP）常被安装在 X 线管管套出口处用于剂量监测，关于其含义下列描述正确的是", "o": {"A": "DAP 的单位为 mGy，表示受检者的皮肤入射剂量", "B": "DAP 为照射野内空气比释动能与照射野面积之积，常用单位 mGy·cm²，其数值沿射线束路径近似不随距离改变", "C": "DAP 只取决于管电压，与照射野大小无关", "D": "DAP 数值越大说明图像信息量越丰富，应尽量提高", "E": "DAP 无法用于估算受检者的有效剂量"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-004", "kp": "剂量面积乘积 DAP 的物理意义", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】B 正确。DAP=空气比释动能×照射野面积。由于剂量随距离平方反比衰减、而照射野面积随距离平方增大，二者相乘后在射线束内近似为常数，因此透射电离室安装在管套出口即可代表整个射线束，测量结果与探测位置无关。【为什么错】A 单位是 mGy·cm²（或 Gy·cm²），皮肤入射剂量 ESD 的单位才是 mGy。C 照射野面积是 DAP 的直接因子，缩小照射野是降低 DAP 最有效的手段之一。D 提高 DAP 只增加受检者剂量，质量管理要求在满足诊断的前提下使用尽可能低的剂量。E DAP 乘以部位相关转换系数可粗略估算有效剂量，是介入与摄影剂量管理的常规做法。", "tr": "DAP 反映射线束携带的总能量，适合评估随机性效应与集体剂量；而峰值皮肤剂量 PSD/ESD 才用于评估确定性效应（如介入术后放射性皮肤损伤）。两者不能互相替代。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0109", "t": "多选题", "s": "数字 X 线摄影日常工作中出现下列伪影表现，其原因分析正确的有", "o": {"A": "CR 图像上叠加有既往检查的淡影（残影），多因 IP 板擦除不彻底或长期闲置未做预擦除", "B": "DR 图像固定位置反复出现白点或坏线，多为探测器像素缺陷、增益与坏点校正表失效，需重新执行探测器校正", "C": "DR 图像出现规则的细密条纹（摩尔纹），多因滤线栅栅密度与探测器采样频率发生混叠", "D": "CR 图像沿激光扫描方向出现细直线状条纹，常见于扫描光路污染或集光导光器积尘", "E": "图像整体颗粒感重、噪声明显，最常见原因是模数转换器位深不足"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-005", "kp": "CR/DR 常见伪影的原因排查", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】A 正确：IP 板上的潜影若未被强光彻底擦除，会在下次曝光图像中留下残影，长期存放的 IP 板还会累积本底辐射信号，使用前应做预擦除。B 正确：平板探测器的坏点、坏线属硬件与校正表问题，特征是位置固定、与患者体位无关，需重做暗场/亮场与坏点校正。C 正确：栅密度与探测器像素采样频率接近整数倍关系时发生空间频率混叠，形成摩尔纹，可更换栅比/栅密度或改变栅的取向解决。D 正确：CR 读取系统光路上的灰尘与污渍使该扫描线信号衰减，形成与扫描方向一致的直条纹。【为什么错】E 错误：整体颗粒感重最常见的原因是曝光剂量不足导致量子噪声占主导，可通过曝光指数核实并调整条件；A/D 位深不足的典型表现是灰阶过渡出现阶梯状伪轮廓（假等高线），而非弥漫颗粒噪声。", "tr": "鉴别要点是\"位置是否固定\"：位置固定不随体位改变的多为探测器/读取系统硬件问题；随患者与投照条件改变的多为曝光、散射、栅或运动因素。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-0110", "t": "单选题", "s": "ACR 乳腺 X 线体模内含 6 根模拟纤维、5 组模拟微钙化点群与 5 个模拟肿块，按通用验收标准，合格图像至少应能分辨出", "o": {"A": "3 根纤维、2 组钙化点群、2 个肿块", "B": "4 根纤维、3 组钙化点群、3 个肿块", "C": "5 根纤维、4 组钙化点群、4 个肿块", "D": "6 根纤维、5 组钙化点群、5 个肿块", "E": "2 根纤维、2 组钙化点群、3 个肿块"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-001", "kp": "ACR 乳腺体模图像质量评价标准", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】B 正确。ACR 乳腺体模评分采用\"4-3-3\"最低合格标准：至少清晰显示 4 根纤维、3 组微钙化点群、3 个肿块，且计数时只有完整可辨者计 1 分、半数可辨计 0.5 分，末位分数不足者向下取整。该体模检测属乳腺机质控的核心项目，通常要求每周或每月进行一次。【为什么错】A、E 标准过低，达不到临床诊断要求。C、D 要求过高，超出了通用验收合格线，实际优秀设备可达到但不是最低标准。", "tr": "\"4-3-3\"必须与体模内含数量\"6-5-5\"分开记忆。另注意合格判定同时还要求无明显伪影，且体模图像的光学密度/像素值与本底对比度符合规定。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0111", "t": "多选题", "s": "针对乳腺 X 线摄影的质量控制与剂量管理，下列做法与认识正确的有", "o": {"A": "以 4.2 cm 厚度、相当于 50% 腺体与 50% 脂肪的标准体模曝光时，单次摄影的平均腺体剂量（AGD）应控制在 3 mGy 以内", "B": "适度压迫可减少组织重叠与散射线、缩短物-片距、使乳腺厚度均匀，从而在降低剂量的同时提高清晰度", "C": "电动压迫力上限一般不超过约 200 N，并应在受检者可耐受的前提下尽量压迫充分", "D": "AGD 不能直接测量，需由入射空气比释动能结合压迫厚度、腺体含量与半价层，通过转换系数换算得到", "E": "为提高微钙化的检出率，应选用 40 kV 以上的高管电压以增强穿透力"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-002", "kp": "乳腺摄影平均腺体剂量与压迫质控", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】A 正确：以标准体模评价时，含滤线栅条件下单次摄影 AGD 的通用限值为 3 mGy。B 正确：压迫使乳腺厚度减薄且均匀，减少重叠与散射、减小几何模糊与运动模糊，并降低达到相同影像质量所需的剂量。C 正确：设备的电动压迫力通常设有约 200 N 的上限，实际以受检者耐受为准，压迫不足会导致厚度增加、剂量上升与影像模糊。D 正确：AGD 是通过测量入射空气比释动能，再按压迫厚度、腺体比例与半价层查表取转换系数计算得到的估算量。【为什么错】E 错误：乳腺摄影使用低管电压（一般 25～32 kV）配合钼、铑或钨靶及相应滤过，靠低能 X 线放大软组织与钙化的衰减差异；管电压升到 40 kV 以上会显著压缩对比度，微钙化反而更难显示。", "tr": "\"高 kV 穿透力强所以图像好\"在乳腺摄影中完全不成立——乳腺摄影追求的是软组织对比度而非穿透力，这是与胸部高千伏摄影截然相反的思路。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-0112", "t": "单选题", "s": "CT 设备日常质控中，用直径约 20 cm 的水模检测 CT 值准确性，在中心区域 ROI 测得的水 CT 值验收标准通常应为", "o": {"A": "0 HU ± 4 HU", "B": "0 HU ± 40 HU", "C": "-1000 HU ± 4 HU", "D": "100 HU ± 4 HU", "E": "只要测得值为负值即为合格"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-001", "kp": "CT 值准确性与水模标定", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】A 正确。CT 值以水为 0 HU、空气为 -1000 HU 定标，是全部密度判读的基准。现行标准对水模中心 CT 值的验收检测要求在 0 HU ± 4 HU 以内，状态检测可放宽到约 ±6 HU；同时在同一层面测均匀性，即周边 4 个 ROI 与中心 ROI 的 CT 值差值也应在规定范围内。【为什么错】B 容许范围过宽，±40 HU 已足以把水误判为软组织或脂肪，严重影响定量诊断。C -1000 HU 是空气的 CT 值。D 100 HU 附近对应致密软组织或轻度钙化，与水无关。E 未设定量限值，不能作为判定依据；水 CT 值偏离可正可负，关键看绝对偏差大小。", "tr": "水模 CT 值漂移常提示需要重新做空气校正（air calibration）或球管老化，日检发现偏差应先做空气校正再复测，而非直接调整窗口设置掩盖问题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0113", "t": "单选题", "s": "某腹部 CT 扫描为降低剂量，将管电流量由 200 mAs 降至 50 mAs，其余参数（管电压、层厚、螺距、重建算法）不变。在滤波反投影重建条件下，图像噪声标准差的变化是", "o": {"A": "降低为原来的约一半", "B": "基本保持不变", "C": "增大为原来的约 1.4 倍", "D": "增大为原来的约 2 倍", "E": "增大为原来的约 4 倍"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-002", "kp": "CT 噪声与剂量的平方根关系", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】D 正确。CT 图像的量子噪声标准差 σ 与探测到的光子数平方根成反比，即 σ∝1/√剂量。mAs 由 200 降到 50，剂量降为原来的 1/4，噪声增大为 √4=2 倍。【为什么错】A 方向相反，降低 mAs 只会增加噪声。B 在滤波反投影条件下噪声与剂量强相关，不可能不变。C 1.4（即 √2）倍对应剂量减半，即 mAs 由 200 降到 100 的情形。E 4 倍噪声对应剂量降至 1/16，即 mAs 降到 12.5。", "tr": "反向命题更常见：\"要把噪声降低一半需要增加多少剂量\"，答案是 4 倍而非 2 倍。同理，层厚减半（其余不变）也使噪声增至约 √2 倍，因为单个体素接收的光子数减半。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0114", "t": "多选题", "s": "关于 CT 空间分辨率与低对比分辨率（密度分辨率）各自的影响因素，下列表述正确的有", "o": {"A": "空间分辨率主要取决于探测器孔径、X 线管焦点、采样密度、重建视野与矩阵以及重建卷积核", "B": "低对比分辨率主要受噪声水平支配，因此与 mAs、层厚、重建算法关系密切", "C": "选用高分辨率（骨/锐利）卷积核可提高空间分辨率，但同时放大噪声、使低对比分辨率下降", "D": "增大层厚可降低噪声、改善低对比分辨率，但会加重部分容积效应并降低 Z 轴分辨率", "E": "提高 mAs 可以同时显著提高空间分辨率与低对比分辨率"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-003", "kp": "空间分辨率与低对比分辨率的影响因素", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】A 正确：空间分辨率（高对比分辨率）由几何采集条件与重建参数决定，像素尺寸=重建视野/矩阵，是其上限约束。B 正确：低对比分辨率考察在低对比背景中辨认物体的能力，噪声是决定性因素，凡影响噪声的参数都影响它。C 正确：锐利卷积核提升高频响应的同时也放大高频噪声，是典型的\"此消彼长\"。D 正确：层厚加倍使体素内光子数加倍、噪声降至约 1/√2，但纵向分辨率下降、部分容积效应加重。【为什么错】E 错误：提高 mAs 通过降噪改善低对比分辨率，但空间分辨率由焦点、探测器孔径、采样与重建核等几何/算法因素决定，与 mAs 基本无关；只有在极低剂量、噪声完全淹没细节时才存在间接影响。", "tr": "\"薄层+锐利核\"是提高空间分辨率的组合，代价是噪声上升；\"厚层+平滑核+高 mAs\"是提高低对比分辨率的组合，代价是细节模糊。两类分辨率不可能同时最优，命题常用 E 这类\"两全其美\"的选项设陷。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-0115", "t": "案例分析题", "s": "一名 45 岁女性无症状体检者，既往无胸部疾病史，因肺癌筛查行胸部低剂量 CT 平扫。扫描完成后控制台剂量报告显示：CTDIvol=2.0 mGy，扫描长度 25 cm，DLP=50 mGy·cm。受检者对辐射较为焦虑，询问本次检查\"到底吃了多少射线\"，要求技师给出一个可与日常生活比较的数值。已知成人胸部 CT 有效剂量转换系数 k 约为 0.014 mSv/(mGy·cm)。作为高年资技师，下列计算与解释中正确的是", "o": {"A": "有效剂量约为 0.7 mSv；DLP 由 CTDIvol 乘以扫描长度得到，再乘以部位转换系数 k 即得有效剂量估算值", "B": "有效剂量约为 7 mSv，与一次常规腹部增强 CT 相当", "C": "有效剂量约为 0.028 mSv，由 CTDIvol 乘以 k 得到", "D": "CTDIvol 即受检者接受的有效剂量，本次为 2.0 mSv", "E": "DLP 应等于 CTDIvol 除以螺距，本例为 50 mGy"}, "d": "难", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-004", "kp": "CTDIvol、DLP 与有效剂量的换算", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】A 正确。DLP=CTDIvol×扫描长度=2.0 mGy×25 cm=50 mGy·cm，与机器显示一致；有效剂量 E≈DLP×k=50×0.014=0.7 mSv。该量级约相当于数月的天然本底照射，可用于向受检者做通俗解释。【为什么错】B 数量级错误，7 mSv 已接近常规腹盆腔增强 CT 的水平，与低剂量胸部 CT 不符。C 混淆了公式，k 应乘以 DLP 而非 CTDIvol，且 CTDIvol 的单位是 mGy、不含扫描长度信息。D CTDIvol 是标准体模内的加权剂量指数，单位为 mGy，只表征扫描技术的剂量输出水平，不等于考虑了器官权重的有效剂量。E 公式错误：螺旋扫描时 CTDIvol=CTDIw/螺距，螺距的影响已包含在 CTDIvol 内；DLP=CTDIvol×长度，单位为 mGy·cm。", "tr": "k 值随部位差别很大：头部约 0.0021、颈部约 0.0059、胸部约 0.014、腹部与盆腔约 0.015 mSv/(mGy·cm)。若误用头部 k 计算胸部，结果会低估近 7 倍，是典型的计算类失分点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0116", "t": "单选题", "s": "某多层螺旋 CT 以\"有效 mAs\"（effective mAs = mAs/螺距）方式设定曝光条件。技师将螺距由 0.8 提高到 1.2，有效 mAs 设定值与其余参数不变，此时", "o": {"A": "系统自动按比例提高实际管电流量，CTDIvol 与图像噪声基本不变，扫描时间缩短", "B": "患者剂量降为原来的约 2/3，图像噪声相应增大", "C": "图像噪声降低而患者剂量升高", "D": "扫描时间保持不变，但 Z 轴分辨率提高", "E": "螺距的改变与扫描时间无关"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-005", "kp": "螺距、有效 mAs 与图像质量的关系", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】A 正确。有效 mAs=实际 mAs/螺距，而螺旋扫描的 CTDIvol=CTDIw/螺距，因此 CTDIvol 与有效 mAs 成正比。保持有效 mAs 不变、螺距由 0.8 增到 1.2 时，设备会自动把实际管电流量提高到原来的 1.5 倍，使单位长度的剂量与噪声水平基本恒定；同时床进速度加快，扫描同样长度所需时间缩短。【为什么错】B 这是设定\"每圈 mAs\"（mAs/rotation）方式下的结论：此时提高螺距会使剂量按 1/螺距下降、噪声上升。本题设定的是有效 mAs，两者结论相反。C 方向完全颠倒。D 螺距增大后床速加快，扫描时间必然缩短；且螺距过大时 Z 轴插值权重变宽，层敏感度剖面增宽，纵向分辨率略有下降而非提高。E 螺距直接决定床进速度，与扫描时间密切相关。", "tr": "同一句\"提高螺距\"，在\"有效 mAs\"（西门子系列常用）与\"每圈 mAs\"（部分厂家沿用）两种设定方式下，对剂量与噪声的结论完全相反。审题时务必先确认控制台设定的是哪一种 mAs。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0117", "t": "多选题", "s": "关于迭代重建（IR）算法在 CT 降低剂量与保障图像质量中的作用，下列分析正确的有", "o": {"A": "与滤波反投影相比，迭代重建在同等剂量下可明显降低噪声，或在同等噪声水平下使剂量下降约 30%～50%", "B": "迭代重建对噪声的抑制并非在各空间频率上均等，会改变噪声功率谱形态，使图像出现\"蜡样、塑料感\"的特殊纹理", "C": "评价迭代重建图像时不能只看噪声标准差，还应结合低对比可探测度与任务传递函数等指标综合判断", "D": "迭代重建强度权重设置得越高，图像质量越好，临床应常规选用最高档", "E": "统计迭代重建能够彻底消除金属伪影与射线束硬化伪影，因此不再需要专门的伪影校正算法"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-006", "kp": "迭代重建与噪声-剂量权衡", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】A 正确：混合迭代与模型迭代重建通过在投影域和/或图像域反复迭代抑制统计涨落，同等图像噪声下允许显著降低管电流量，这是低剂量 CT 的技术基础。B 正确：IR 主要压制高频噪声，使 NPS 峰值向低频移动，图像质地变得平滑、缺乏颗粒感，即所谓\"蜡样/塑料感\"。C 正确：噪声标准差下降并不等于诊断信息增加，必须结合低对比可探测度（如 C-D 曲线、模型观察者指标）与任务传递函数评价，才能反映真实的诊断性能。【为什么错】D 错误：迭代权重过高会造成解剖边缘钝化、小低对比病灶（如小肝癌、腔隙灶）显示能力下降和纹理失真，临床应根据检查部位与诊断任务选择适中档位。E 错误：迭代重建可部分改善噪声相关伪影，但金属伪影与射线束硬化属确定性的数据不一致问题，仍需专门的金属伪影校正（MAR）、硬化校正或能量成像单能量图像来处理。", "tr": "\"噪声更低=图像更好\"是本考点最大的思维陷阱。迭代重建把噪声\"改造\"了而不仅是\"减少\"，评价时必须引入低对比可探测度指标，否则容易过度降剂量而漏诊小病灶。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U05-0118", "t": "案例分析题", "s": "一名 68 岁男性因持续头痛行头颅 CT 平扫。图像上颅后窝层面于双侧颞骨岩部之间出现横行的低密度条状暗带，并夹杂少许高密度细条纹，脑桥前部结构显示欠清；同一次检查的幕上各层面图像质量良好，未见类似表现。检查过程中患者安静配合、无体动，头部未佩戴任何金属物品，义齿已取下；设备当日水模质控与空气校正均合格。作为高年资技师，对该伪影的性质判断与优化处理，下列最恰当的是", "o": {"A": "属射线束硬化并叠加部分容积效应形成的颅底暗带伪影，可提高管电压、加大预过滤、采用薄层采集后重组、启用颅底硬化校正算法或调整扫描机架角度予以减轻", "B": "属探测器单元失效引起的环形伪影，应停机联系工程师更换探测器模块", "C": "属患者头部运动造成的运动伪影，应加强头部固定后重新扫描", "D": "属口腔金属义齿造成的金属条状伪影，应嘱患者取下义齿后重扫", "E": "属大螺距螺旋插值造成的风车状伪影，应显著减小螺距后重扫"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-007", "kp": "CT 常见伪影的识别与处理", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】A 正确。颅后窝两侧致密岩骨之间的射线路径衰减极大，低能光子被优先吸收使射线束\"变硬\"，重建算法按单能假设处理即产生条状低密度暗带（Hounsfield 暗带），常与厚层导致的部分容积效应叠加。处理措施包括提高管电压与加大预过滤使射线谱变硬更均匀、采用薄层采集后重组减少部分容积、启用颅底/后颅窝专用硬化校正重建、必要时倾斜机架改变射线路径。【为什么错】B 环形伪影的特征是以旋转中心为圆心的同心圆环或弧线，可出现在任何层面，与解剖位置无关，本例仅见于颅底且呈横行条带，不符。C 运动伪影常表现为条纹状、边缘重影或阶梯状错层，且多累及多个层面，本例患者配合良好、幕上层面正常，不支持。D 患者已取下义齿且伪影位于岩骨间而非牙列层面，金属伪影多呈自金属向外放射的明暗相间粗条纹。E 风车伪影出现在多层螺旋 CT 大螺距扫描时的高对比结构边缘，呈以旋转中心为轴的风车叶片状，多见于横断面重建的颅底或肺尖，其形态与本例横行暗带不同。", "tr": "颅底暗带与运动伪影都可表现为\"条纹\"，鉴别关键在于分布：射线束硬化伪影固定出现在两块致密骨之间（岩骨间、后颅窝），层面选择性强；运动伪影随患者体动出现，位置与形态无解剖规律。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0119", "t": "单选题", "s": "DSA 减影图像上出现血管边缘\"双边\"表现及全图弥漫的骨与软组织结构残影，其最常见原因及首选补救措施是", "o": {"A": "对比剂浓度过高造成饱和伪影，应稀释对比剂后重做造影", "B": "蒙片与造影片之间发生配准错位（运动性伪影），首选行像素移位再配准或另选一帧作为新蒙片重新减影", "C": "影像增强器固有的枕形失真所致，应更换为平板探测器", "D": "采集帧率过低，应提高到 30 帧/s 后重新采集", "E": "曝光量不足造成量子噪声增加，应提高 mAs 后重新采集"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-001", "kp": "DSA 运动性伪影与像素移位", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (2)成像方式和操作技术", "ex": "【为什么对】B 正确。时间减影的前提是蒙片与充盈片在解剖位置上严格配准。患者的自主或不自主运动（体位移动、吞咽、呼吸、心搏、胃肠蠕动）使两帧位置不一致，相减后残留组织影，血管边缘呈\"双边征\"。后处理首选像素移位（整体或分区局部配准）；若错位过大则从序列中另选与充盈片配准良好的帧作为新蒙片重新减影。预防措施包括良好固定、屏气训练、缩短采集时间、腹部造影前使用抑制胃肠蠕动药物。【为什么错】A 对比剂过浓引起的是血管腔内信号饱和、密度不能线性反映碘浓度，表现为管腔中心\"过冲\"，不产生全图结构残影。C 枕形失真是影像增强器的几何畸变，表现为整个序列图像周边弯曲变形，与减影配准无关，且平板探测器机型不会出现。D 帧率影响时间分辨率，与配准错位无因果关系，盲目提高帧率只增加辐射剂量。E 剂量不足的表现是噪声颗粒增大，不会出现规律的组织结构残影。", "tr": "\"先后处理、后重做\"是 DSA 运动伪影的处理次序。直接重新造影会额外增加对比剂用量与辐射剂量，只有在像素移位与重选蒙片都无法挽救时才考虑。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0120", "t": "多选题", "s": "为改善 DSA 图像质量，下列措施与判断正确的有", "o": {"A": "术前充分做屏气训练，腹部造影可使用抑制胃肠蠕动的药物，以减少运动性伪影", "B": "合理选择焦点与放大方式、缩小照射野、加用适当的补偿滤过板，可减少散射线与饱和伪影", "C": "依据血流速度选择采集帧率，脑血管造影一般用 3～6 帧/s，冠状动脉造影需 15～30 帧/s", "D": "利用减影后对比灵敏度显著提高的优势，可将对比剂适度稀释，在保证显影的前提下减少碘负荷", "E": "对比剂注射流率与浓度越高，血管显示越清晰，图像质量越好"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-002", "kp": "DSA 图像质量的改善措施", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (5)改善措施", "ex": "【为什么对】A 正确：运动是 DSA 图像质量的首要威胁，术前沟通、训练与药物抑制蠕动是最经济有效的预防手段。B 正确：小焦点提高分辨率、缩小照射野与补偿滤过板减少散射并避免肺野、颈部等薄区因透过量过大导致探测器饱和形成\"过亮\"伪影。C 正确：帧率应与靶血管的血流速度匹配，脑血管 3～6 帧/s、冠脉 15～30 帧/s、四肢与下腔静脉可低至 1～3 帧/s。D 正确：减影去除了背景结构，对碘的对比灵敏度大幅提高，因而可用稀释后的对比剂完成诊断，降低对比剂肾病风险。【为什么错】E 错误：过高的浓度与流率会造成管腔内碘信号超出探测器线性响应范围形成饱和伪影，还增加血管内膜损伤、对比剂外渗与肾损伤风险，且湍流可致显影不均。DSA 追求的是\"够用即可\"的最低碘负荷。", "tr": "\"提高对比剂浓度改善图像\"是把常规血管造影的经验错误迁移到 DSA。DSA 的核心优势恰恰是可以用更低浓度、更小剂量获得高对比图像。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-0121", "t": "单选题", "s": "与影像增强器-电视系统（II-TV）相比，平板探测器（FPD）应用于 DSA 的优势不包括下列哪一项", "o": {"A": "不存在枕形失真与 S 形畸变，图像几何保真度高", "B": "动态范围宽、DQE 较高，在较低剂量下即可获得良好信噪比", "C": "无边缘亮度衰减，视野内亮度分布均匀", "D": "体积小、重量轻且无需磁屏蔽，便于机架大角度旋转与三维采集", "E": "极限空间分辨率随视野放大倍数增加而不断提高，可无限放大观察细节"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-003", "kp": "平板探测器与影像增强器的性能比较", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (1)设备结构", "ex": "【为什么对】E 是错误描述，故为本题答案。平板探测器的像素间距在制造时已固定，其极限空间分辨率由像素间距决定（约 1/(2×像素间距) lp/mm），缩小视野只是把同样的像素分布在更小的解剖范围上，并不能无限提高分辨力；\"放大即提高分辨率\"是影像增强器电子放大方式的特点，且以剂量升高为代价。【为什么错】A、B、C、D 均为 FPD 的确实优势：A 影像增强器因电子光学与地磁影响存在枕形失真和 S 形畸变，FPD 为平面矩阵采集，无此问题；B FPD 动态范围可达 10⁴ 以上，DQE 明显高于 II-TV 链；C II 存在边缘亮度衰减（vignetting）与边缘分辨率下降，FPD 视野内响应均匀；D FPD 无真空管与光学耦合链，结构紧凑、不受地磁影响，便于旋转采集与三维重建。", "tr": "FPD 的\"放大\"是显示放大或像素合并模式的切换，与 II 的\"电子放大\"机制不同。命题常用\"放大倍数越高分辨率越高\"这种源自影像增强器时代的旧经验设置干扰。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0122", "t": "案例分析题", "s": "一名 62 岁男性，因反复发作性右侧肢体无力（短暂性脑缺血发作）拟行全脑血管造影，以评估颈内动脉与颅内血管狭窄程度。导管室配备平板探测器 DSA。术前化验示血肌酐轻度升高，估算肾小球滤过率约 55 mL/(min·1.73 m²)，无碘对比剂过敏史，意识清楚、能配合指令。技师需要与术者共同确定颈内动脉造影的采集帧率、对比剂配置与注射参数，并做好减影质量保障。下列方案最合理的是", "o": {"A": "采集帧率取 3～6 帧/s；选用等渗或低渗非离子型对比剂并适度稀释（如 300 mgI/mL 稀释至约 50%～70%），注射流率约 4～5 mL/s、单次总量约 6～8 mL；采集时嘱患者屏气、勿吞咽勿转头，并做好水化", "B": "全部血管一律采用 30 帧/s 采集，以获得最佳时间分辨率", "C": "为使血管显影更浓，使用未稀释的 370 mgI/mL 对比剂，并把注射流率提高到 10 mL/s", "D": "采用 1 帧/s 的低帧率采集，以最大限度降低受检者辐射剂量", "E": "因患者存在肾功能减退，改用高渗离子型对比剂以减轻肾脏负担"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-004", "kp": "脑血管 DSA 的帧率与对比剂方案", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (3)造影方法和对比剂", "ex": "【为什么对】A 正确。脑循环动脉期到静脉期约 6～8 s，3～6 帧/s 足以完整记录动脉期、毛细血管期与静脉期，兼顾时间分辨率与剂量；DSA 因减影提高了碘对比灵敏度，稀释对比剂即可满足显影，对 eGFR 减退者尤为重要；颈内动脉常用流率 4～5 mL/s、总量 6～8 mL；嘱屏气、禁吞咽与转头可显著减少配准错位；围术期水化是预防对比剂相关急性肾损伤的基本措施。【为什么错】B 30 帧/s 适用于心脏与冠状动脉这类高速运动结构，用于脑血管只会成倍增加辐射剂量而无诊断增益。C 未稀释高浓度对比剂加 10 mL/s 的流率远超颈内动脉需要，易致饱和伪影、血管痉挛甚至内膜损伤，且明显加重肾脏碘负荷。D 1 帧/s 会遗漏动脉早期与侧支循环的动态信息，无法判断狭窄远端血流与代偿情况。E 认识错误，高渗离子型对比剂的肾毒性与不良反应发生率明显高于非离子型等渗/低渗对比剂，肾功能减退者应选后者。", "tr": "帧率不是越高越好，应\"按血流速度定帧率\"：脑血管 3～6 帧/s、冠脉 15～30 帧/s、四肢与静脉 1～3 帧/s。另需牢记减影技术允许使用稀释对比剂，这是 DSA 相对常规造影的重要优势。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0123", "t": "多选题", "s": "在分析某台 DSA 设备近期图像质量下降的原因时，下列对影响因素的归类与判断正确的有", "o": {"A": "受检者体厚增加使散射线增多、对比度下降，属患者本身因素，可通过缩小照射野、加用补偿滤过与优化体位改善", "B": "心搏与呼吸运动引起的减影配准误差属患者因素，可用心电门控采集、缩短采集时间与屏气训练减轻", "C": "X 线管焦点尺寸、探测器 DQE 与模数转换位深属设备结构因素，直接决定系统的空间分辨率与密度分辨能力", "D": "采集帧率、注射延迟时间与曝光参数的设定属成像方式和操作技术因素", "E": "对比剂的种类与碘浓度对 DSA 图像质量影响甚微，分析原因时可不予考虑"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-005", "kp": "DSA 图像质量影响因素的系统分类", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (4)患者本身因素", "ex": "【为什么对】A 正确：体厚与体质属患者本身因素，散射线份额随体厚呈指数增长，缩野、滤过与体位优化是可行对策。B 正确：生理性运动同样归入患者因素，心电门控、缩短曝光时间与呼吸配合是标准应对手段。C 正确：焦点决定几何模糊，DQE 决定量子利用效率，A/D 位深决定灰阶量化精度与密度分辨能力，三者均属设备结构范畴。D 正确：帧率、注射延迟、曝光参数与减影方式的选择属操作技术层面，是技师可直接控制的变量。【为什么错】E 错误：对比剂的类型、碘浓度、注射流率与总量直接决定血管腔内的碘信号强度与对比度，是\"造影方法和对比剂\"这一独立影响因素类别的核心内容，不能忽略。", "tr": "考纲把 DSA 图像质量影响因素明确分为设备结构、成像方式与操作技术、造影方法与对比剂、患者本身因素四大类，命题常通过\"张冠李戴\"的归类或直接否定某一类来设陷，记忆时按四类框架归位。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U05-0124", "t": "单选题", "s": "MR 成像中信噪比、对比噪声比、空间分辨率与扫描时间四者相互制约，下列对这一制约关系的分析正确的是", "o": {"A": "其他条件不变时把层厚由 5 mm 减到 2.5 mm，SNR 约降为原来的一半；若将采集次数由 1 增到 4 可将 SNR 补回，但扫描时间也随之延长为 4 倍", "B": "提高空间分辨率的同时能够保持 SNR 不变，且不付出任何扫描时间代价", "C": "SNR 与体素体积无关，仅由主磁场强度决定", "D": "增加采集次数（NEX）时，SNR 与 NEX 成正比线性增长", "E": "缩短扫描时间不会影响 SNR，只会改变运动伪影的程度"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-001", "kp": "SNR、分辨率与扫描时间的相互制约", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】A 正确。SNR 与体素体积成正比，同时与 √(NEX×相位编码步数/接收带宽) 成正比。层厚由 5 mm 减到 2.5 mm 使体素体积减半，SNR 约降为 1/2；NEX 由 1 增到 4 使 SNR 提高 √4=2 倍，恰好抵消。而二维序列扫描时间 T=TR×相位编码步数×NEX/加速因子，NEX 增至 4 倍则时间增至 4 倍。这正是 MR\"四角关系\"中\"改善其一必牺牲其二\"的典型体现。【为什么错】B 违背 MR 成像的基本制约规律，提高分辨率意味着体素变小、SNR 下降，欲维持 SNR 就必须增加平均次数或延长采集，时间代价不可避免。C SNR 与体素体积成正比，是最关键的决定因素之一；场强只是影响因素之一。D SNR 与 NEX 的平方根成正比，NEX 增至 4 倍 SNR 只提高 2 倍，收益递减而时间代价线性增长。E 缩短扫描时间通常靠减少 NEX、减少相位编码步数或提高并行加速因子实现，这些手段都会使 SNR 下降。", "tr": "\"√关系\"是本考点的关键：SNR∝√NEX、∝√相位编码步数、∝1/√带宽，而与体素体积成一次方正比。把 √ 关系误记为线性关系（如选 D）是最常见的失分点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U05-0125", "t": "案例分析题", "s": "一名 34 岁女性运动员因膝关节疼痛行 MRI 检查，设备为 3.0T，使用专用膝关节相控阵线圈。矢状面质子密度加权 FSE 序列的初始参数为：FOV 160 mm×160 mm，矩阵 320×256，层厚 3 mm，NEX 2，接收带宽 200 Hz/像素，扫描时间 3 min 20 s。阅片医师认为关节软骨分层结构与半月板后角细节仍显示不足，要求在扫描时间不明显延长的前提下改善图像。技师逐一评估可调参数对信噪比的影响，下列判断中正确的是", "o": {"A": "把 FOV 由 160 mm 缩小到 80 mm 而矩阵保持不变，体素面积降为原来的 1/4，SNR 约降为原来的 1/4", "B": "把 NEX 由 2 增加到 4，SNR 约提高到原来的 2 倍", "C": "把接收带宽由 200 Hz/像素降到 100 Hz/像素，SNR 约降低到原来的 1/1.4", "D": "把层厚由 3 mm 增加到 6 mm，SNR 约降为原来的一半", "E": "把矩阵提高到 512×512 而 FOV 不变，体素虽减小但 SNR 不受影响"}, "d": "难", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-002", "kp": "FOV、NEX、带宽、层厚对 SNR 的定量影响", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】A 正确。FOV 缩小一半而矩阵不变时，像素边长（面内分辨率）也缩小一半，体素面积变为原来的 1/4，体素体积随之降为 1/4；由于相位编码步数与 NEX 未变，SNR 约降为原来的 1/4。这说明单纯缩小 FOV 提高分辨率的代价极大，实际工作中往往需要同时增加 NEX 或改用更高信噪比的线圈补偿。【为什么错】B 错误：NEX 由 2 增到 4 仅是 2 倍，SNR∝√NEX，提高倍数为 √2≈1.41，而非 2 倍。C 错误：SNR∝1/√带宽，带宽减半使 SNR 提高约 1.41 倍（而非降低），代价是化学位移伪影加重、回波间隔延长、最短 TE 受限。D 错误：层厚加倍使体素体积加倍，SNR 约提高到 2 倍（而非降为一半），代价是部分容积效应加重、软骨薄层结构模糊。E 错误：FOV 不变而矩阵增大使体素变小，SNR 必然下降；相位编码方向矩阵由 256 增到 512 时，体素面积减半带来 1/2、相位编码步数加倍带来 √2，综合约为原来的 0.71 倍，且扫描时间加倍。", "tr": "本题四个干扰项都把变化\"方向\"或\"倍数\"做了颠倒：带宽与层厚记反方向、NEX 记成线性关系是最高频错误。牢记 SNR∝体素体积×√(NEX×N_PE/带宽)，代入即可全部判定。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0126", "t": "单选题", "s": "关于并行采集技术（SENSE/GRAPPA/ASSET）与压缩感知（CS）加速对 MR 图像质量的影响，下列描述正确的是", "o": {"A": "并行采集加速因子 R 增大时，SNR 大致按 1/(g×√R) 下降，其中几何因子 g≥1，且在视野中心区域往往更大", "B": "并行采集通过减少相位编码步数缩短时间，且不损失任何信噪比", "C": "SENSE 类算法展开不当时的典型表现是沿频率编码方向出现贯穿图像的拉链状条纹", "D": "压缩感知依赖图像的稀疏性与规则等间隔欠采样，重建过程为简单的线性反变换", "E": "压缩感知的加速倍数越高，图像越锐利、细节越丰富"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-003", "kp": "并行采集 g 因子与压缩感知加速", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】A 正确。并行采集减少相位编码步数使采集数据量降为 1/R，SNR 首先按 √R 下降；此外线圈单元敏感度分布的空间可分性不理想会引入几何因子 g（g≥1），进一步降低 SNR，故 SNR_加速≈SNR_全采样/(g×√R)。g 因子在线圈灵敏度差异最小的视野中心区域通常最大，因此高加速时中心区噪声放大最明显。【为什么错】B 错误：并行采集必然损失 SNR，这是其固有代价。C 错误：SENSE 展开不当的典型表现是视野中央出现残余卷褶（中心带状重叠影）；拉链伪影是射频屏蔽不良或外来射频干扰所致，两者机制不同。D 错误：压缩感知要求非相干的伪随机欠采样使混叠呈噪声样弥散，并采用稀疏变换域下的非线性迭代重建；规则等间隔欠采样只会产生相干的规律性卷褶，不适用于 CS。E 错误：CS 加速过高会因正则化过强导致图像过度平滑、纹理与低对比细节丢失，甚至产生虚假结构，需在加速倍数与细节保真之间折中。", "tr": "CS 图像\"看上去很干净\"容易被误认为质量高。CS 与迭代重建 CT 类似，噪声下降不等于信息增加，评价时应关注小病灶的可探测性与是否出现假象。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0127", "t": "单选题", "s": "MR 图像上出现视野以外的解剖结构被折叠到图像对侧的现象，关于该伪影的成因与对策，下列描述正确的是", "o": {"A": "此为卷褶（混叠）伪影，因相位编码方向 FOV 小于受检部位、相位超出 ±180° 后发生周期性重复所致；可用相位过采样、增大 FOV、加饱和带或交换相位与频率编码方向解决", "B": "此为化学位移伪影，只需增大接收带宽即可完全消除", "C": "此伪影主要出现在频率编码方向，因频率编码方向未设置抗混叠滤波器", "D": "增加采集次数（NEX）是消除该伪影最有效的方法", "E": "卷褶伪影只发生于二维序列，三维采集的层面编码方向不会出现"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-004", "kp": "卷褶伪影的识别与对策", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】A 正确。相位编码依靠 -180°～+180° 的相位差区分空间位置，FOV 之外的组织其相位超出该范围后与 FOV 内某位置的相位相同，被错误编码到对侧，形成卷褶。对策包括：相位过采样（无相位卷褶/折叠抑制，代价是扫描时间或 NEX 增加）、增大 FOV、在 FOV 外加预饱和带、交换相位与频率编码方向使卷褶落在无关方向、选择敏感范围受限的表面线圈。【为什么错】B 化学位移伪影表现为水脂界面沿频率编码方向的位移与黑白勾边，与结构折叠是两回事。C 频率编码方向通常配有低通抗混叠滤波并做频率方向过采样，一般不出现卷褶；卷褶主要沿相位编码方向。D 增加 NEX 只提高 SNR，对卷褶无作用。E 三维采集在层面（第二相位编码）方向同样会发生卷褶，表现为最外层层面上叠加了容积外的解剖结构，需要层面方向过采样加以抑制。", "tr": "\"相位编码方向\"是卷褶伪影的定位口诀。另需注意：三维序列存在两个相位编码方向，层面方向卷褶常被误判为病变，是脊柱与颅脑三维扫描的实际难点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-0128", "t": "案例分析题", "s": "一名 58 岁男性，腰椎后路椎弓根螺钉内固定术后 2 年，因下腰痛伴右下肢麻木行 1.5T 腰椎 MRI。矢状面 T2WI（TSE）上内固定区域出现大片信号丢失伴局部信号异常堆积，邻近椎体与椎管轮廓明显扭曲变形；同一检查的矢状面 T1WI 上，脊髓与脑脊液交界附近出现数条平行于脊髓走行、明暗相间且等间距排列的细线状条纹，类似脊髓空洞样表现。患者检查全程配合良好，无体动。技师需在不更换设备的条件下优化图像。下列处理措施组合最合理的是", "o": {"A": "针对金属磁敏感伪影：缩短 TE、增大接收带宽、减小体素、增加回波链长度，以 TSE 替代 GRE/EPI 类序列，脂肪抑制改用 STIR；针对截断（吉布斯）伪影：增大相位编码方向矩阵或适当减小 FOV，必要时配合适度滤波", "B": "两种表现均属运动伪影，加用呼吸门控并使用腹部加压带即可解决", "C": "金属伪影应通过降低接收带宽、延长 TE 来减轻；条纹伪影应通过增加采集次数解决", "D": "条纹表现属卷褶伪影，交换相位编码方向即可；金属伪影则应改用频率选择性脂肪抑制以提高抑脂均匀性", "E": "两者均由射频屏蔽不良引起，应检查检查室屏蔽门与滤波板后重新扫描"}, "d": "难", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-005", "kp": "磁敏感伪影与截断伪影的鉴别与对策", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】A 正确。金属内固定引起局部磁场不均匀，导致自旋失相位与频率编码错位，表现为信号丢失、信号堆积与几何扭曲；有效对策是缩短 TE 减少失相位时间、增大带宽压缩每像素频率范围以减小空间错位、减小体素降低体素内失相位、增加回波链使回波间隔缩短并借助 180° 复聚脉冲补偿静态场不均匀，因此应优先用 TSE 而非 GRE/EPI；由于频率选择性脂肪抑制在磁场不均匀区会失效甚至造成水脂互换，应改用对场不均匀不敏感的 STIR。脊髓/脑脊液这类高对比界面处出现的等间距平行条纹是截断（吉布斯/环状）伪影，源于 k 空间高频数据被有限矩阵截断，对策是增大相位编码方向矩阵（提高该方向分辨率）、减小 FOV 或使用 k 空间滤波。【为什么错】B 患者配合良好且伪影形态具有明确的空间规律，不符合运动伪影表现，呼吸门控对腰椎金属伪影无效。C 方向完全相反：降低带宽与延长 TE 都会加重磁敏感伪影；增加 NEX 只提高 SNR，对截断伪影无改善。D 截断伪影与卷褶伪影不同，前者是界面处的等间距条纹、不涉及视野外结构折叠；且在金属区使用频率选择性脂肪抑制正是应当避免的做法。E 射频干扰的典型表现是拉链状条纹或图像整体噪声带，与本例两种伪影的形态和分布均不吻合。", "tr": "截断伪影与脊髓空洞的鉴别是临床实际难题：截断伪影表现为多条等间距、明暗交替、随矩阵改变而变化的条纹，且在增大相位编码矩阵后减轻或消失；真实空洞则形态固定、在各序列各方位上可重复显示。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U05-1001", "t": "单选题", "s": "关于影像质量保证（QA）的概念，下列叙述最准确的是", "o": {"A": "仅指对X线辐射剂量进行监测和控制的活动", "B": "有计划、有系统地采取必要措施，保证影像质量满意并能持续改进的整体活动", "C": "使用标准体模对设备性能进行的验收检测", "D": "对图像质量进行的评分与评价过程", "E": "指影像科内部制定规章制度的管理活动"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-101", "kp": "质量保证QA的定义与内涵", "ch": "五、影像质量管理 → 1.概述 → (1)基本概念", "ex": "【为什么对】质量保证（QA）是有计划、有组织的系统活动，目的在于确保影像质量满足临床诊断要求并不断持续改进，涵盖人员、设备、制度、检测等全部环节，故B最准确。\n【为什么错】A：只涉及剂量监测，是QC的一部分而非QA全部。C：验收检测只是QA的组成部分之一。D：图像评价只是质量管理的环节之一。E：制度管理是QA内容的一部分，不能概括QA整体。", "tr": "QA（整体、系统、持续改进）与QC（具体检测、校正）是从属关系，勿将QC、验收检测误当QA的全部。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1002", "t": "单选题", "s": "影像质量控制（QC）是质量保证（QA）的重要组成部分，其核心工作是", "o": {"A": "购置并维护先进的成像设备", "B": "对成像设备及成像过程的关键技术指标进行监测、检测、校正并使其处于最佳状态", "C": "制定影像科的行政管理规范", "D": "对医师报告质量进行审核", "E": "统计受检者群体辐射剂量"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-102", "kp": "质量控制QC的职责", "ch": "五、影像质量管理 → 1.概述 → (1)基本概念", "ex": "【为什么对】质量控制（QC）通过定期检测设备与成像过程的关键指标（如CT值、噪声、分辨率、亮度密度等）并及时校正，使成像系统始终处于最佳工作状态，是QA的核心技术环节。\n【为什么错】A：设备购置属于规划管理而非QC。C：行政管理规范不属于技术QC范畴。D：报告质量审核属于诊断质量评估。E：群体剂量统计属于防护监测，非QC核心工作。", "tr": "QA是整体概念、QC是其技术执行环节；设备购置、报告审核等均不属于QC核心工作。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1003", "t": "单选题", "s": "下列影像质量评价方法中，属于主观评价法的是", "o": {"A": "调制传递函数（MTF）测量", "B": "量子探测效率（DQE）测量", "C": "视觉观察评分法（目测法）", "D": "噪声功率谱（NPS）测量", "E": "像素值线性检测"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-103", "kp": "主观评价法及其内容", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】主观评价法以观察者的视觉判断为依据评价图像质量，主要包括目测法（视觉观察评分）和ROC曲线分析法。\n【为什么错】A：MTF用物理量客观测定，属客观评价法而非主观评价。B：DQE反映量子利用效率，是客观物理指标。D：NPS是噪声功率谱的客观测量，不依赖观察者判断。E：像素值线性检测是物理定量检测，属客观评价法。", "tr": "ROC曲线属主观（心理学）评价而非客观评价；MTF/DQE/NPS均属客观物理评价。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1004", "t": "单选题", "s": "DR系统日常质量控制中，曝光指数（exposure index）主要反映的是", "o": {"A": "图像的空间分辨率", "B": "探测器接收到的X线曝光量（剂量水平）", "C": "图像的密度分辨率", "D": "重建矩阵的大小", "E": "监视器的亮度水平"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-101", "kp": "DR曝光指数含义", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】曝光指数是对探测器接收X线剂量的量化指示，反映实际曝光量是否合适，用于判断摄影条件是否恰当并指导剂量控制。\n【为什么错】A：空间分辨率由探测器像素尺寸与系统MTF决定。C：密度分辨率与剂量、噪声有关但不是曝光指数直接反映对象。D：重建矩阵是图像处理参数。E：监视器亮度属于显示设备调节，与曝光指数无关。", "tr": "曝光指数反映的是探测器受照剂量而非空间分辨力；不同厂家指示量（EI/S值/EXI）含义略有差异。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1005", "t": "单选题", "s": "按照ACR乳腺X线摄影质量保证程序，用标准体模进行图像质量评估时，若体模内模拟纤维、微钙化团块和肿块结构的可见数目低于规定阈值，正确的处理是", "o": {"A": "记录结果后继续正常投照", "B": "适当降低压迫压力后重新摄片", "C": "判定质量控制不合格，排除设备原因（校正/维修）后重新检测", "D": "仅通过提高曝光量来改善", "E": "更换照片冲洗液后重测"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-101", "kp": "乳腺体模质量评估与处理", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】ACR标准体模（如RMI 156）内含模拟纤维、微钙化团块和肿块，其可见数目须达到规定阈值，不达标表明系统图像质量下降，应判定QC不合格并查找原因（设备校准、维修等）后复测。\n【为什么错】A：记录后继续使用会延误设备异常发现。B：压迫压力不改变体模内在结构的可见性阈值判定。D：单纯提高曝光量不能替代设备检修，且增加剂量。E：现代数字乳腺系统无冲洗液环节。", "tr": "乳腺质控核心是“体模可见结构阈值不达标即QC不合格”；压迫压力、曝光量调节不能掩盖设备性能问题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1006", "t": "单选题", "s": "CT图像质量控制中，用标准水模检测CT值准确性时，水的CT值标称应为", "o": {"A": "-1000 HU", "B": "0 HU", "C": "40 HU", "D": "100 HU", "E": "200 HU"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-101", "kp": "CT值准确性与水模", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】CT值以水为参照定义为0 HU（空气-1000 HU），用水模检测CT值应在0 HU附近，允许偏差一般为±3~4 HU（各厂家标准略有差异）。\n【为什么错】A：-1000 HU为空气的CT值。C：40 HU明显偏离水的标称值，属质控异常或误记。D：100 HU明显高于水的标称CT值。E：200 HU显著偏离，若测得此值提示系统校准或探测器异常。", "tr": "牢记标尺：水0 HU、空气-1000 HU、骨+1000 HU左右；CT值漂移可提示探测器或校准问题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1007", "t": "单选题", "s": "关于影像质量主客观评价方法的比较，下列叙述正确的是", "o": {"A": "主观评价受观察者个体影响，因此没有临床应用价值", "B": "调制传递函数（MTF）属于主观评价法", "C": "客观评价以物理量（如MTF、DQE、噪声）定量评价图像质量，可重复性好", "D": "ROC曲线分析属于客观评价法", "E": "综合评价法仅指对物理指标的综合，不涉及临床诊断"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-104", "kp": "主客观评价方法特点比较", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】客观评价法用可测量的物理量（MTF、DQE、噪声、像素值等）定量反映系统性能，结果不受观察者影响、可重复性好，用于设备验收与日常质控。\n【为什么错】A：主观评价（目测、ROC）直接反映临床观察效能，是评价图像最终可诊断性的重要手段，并非无价值。B：MTF是客观物理评价指标。D：ROC通过观察者对信号检出率的判断完成，属主观（心理学）评价法。E：综合评价法将物理指标与临床诊断价值（观察者）结合，不仅限于物理指标。", "tr": "MTF/DQE/NPS为客观评价，ROC为典型主观评价；综合评价=物理+临床观察相结合。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1008", "t": "单选题", "s": "DR探测器在低剂量区输出信号与入射X线剂量呈现非线性时，对图像质量最主要的影响是", "o": {"A": "空间分辨力下降", "B": "灰阶层次（对比度）失真，低对比度病变显示能力下降", "C": "产生运动伪影", "D": "有效视野缩小", "E": "图像放大率改变"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-102", "kp": "DR探测器剂量响应线性", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】数字X线成像依赖于探测器输出信号与入射剂量的线性响应，低剂量区非线性会使图像灰度值与实际组织衰减不成比例，导致对比度失真，掩盖或误显低对比度病灶，直接影响诊断。\n【为什么错】A：空间分辨力由探测器像素尺寸及系统MTF决定，与剂量响应线性无关。C：运动伪影来源于被照体或设备运动。D：视野由探测器尺寸与几何决定。E：放大率取决于焦点-物体-探测器几何位置。", "tr": "探测器线性是数字成像量化基础；非线性主要损伤“对比度/灰阶”而非空间分辨率。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1009", "t": "单选题", "s": "关于乳腺X线摄影的平均腺体剂量（AGD），下列叙述正确的是", "o": {"A": "与乳腺压迫厚度无关", "B": "是反映乳腺摄影受检者辐射剂量的指标，受管电压、靶/滤过组合、压迫厚度及曝光量等综合影响", "C": "平均腺体剂量越大，图像质量一定越好", "D": "与数字乳腺摄影（FFDM）或模拟摄影方式无关", "E": "平均腺体剂量不受质量保证要求限制"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-102", "kp": "乳腺平均腺体剂量", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】平均腺体剂量（AGD）用于评估乳腺受照剂量，其大小由管电压、阳极靶/滤过组合、压迫厚度、曝光量及摄影方式等多种因素共同决定，是乳腺质控与剂量监测的核心指标。\n【为什么错】A：压迫厚度增加时为使探测器获得足够光子需增大曝光量，AGD随之升高，二者密切相关。C：AGD增大并不等同于图像质量提高，还需兼顾噪声与分辨力，且应遵循合理尽可能低（ALARA）原则。D：FFDM与模拟乳腺摄影的剂量水平不同。E：ACR等质控标准对AGD设有评价限值。", "tr": "AGD=受照剂量指标，需“剂量与图像质量”双达标，不能以牺牲剂量追求图像。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1010", "t": "单选题", "s": "关于CT空间分辨率与密度分辨率的关系，下列叙述正确的是", "o": {"A": "两者相互独立、互不影响", "B": "提高空间分辨率必然提高密度分辨率", "C": "同一扫描条件下二者往往相互制约，减小像素（增大矩阵）可提高空间分辨率但噪声增加、密度分辨率下降", "D": "增大层厚可使空间分辨率和密度分辨率同时提高", "E": "螺距大小对两者均无影响"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-102", "kp": "空间分辨率与密度分辨率关系", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】空间分辨率取决于像素大小与焦点、探测器孔径等，密度分辨率主要受噪声（光子数）影响。像素减小时单个像素收到的光子减少、噪声增大，密度分辨率下降，故两者相互制约。\n【为什么错】A：二者受同一噪声源和采样条件影响，存在此消彼长的制约关系。B：提高空间分辨率通常以降低密度分辨率为代价。D：增大层厚使部分容积效应增加，空间分辨率沿层厚方向下降，不能同时提高两者。E：螺距增大影响噪声与有效层厚，间接影响密度分辨率。", "tr": "“大矩阵提空间分辨率、损密度分辨率”；层厚越大密度（低对比）噪声改善但部分容积效应越重。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1011", "t": "单选题", "s": "DSA图像上出现血管边缘“双边”显示及全图骨骼、软组织影未被消除的配准不良伪影，其最直接的原因是", "o": {"A": "对比剂浓度过高", "B": "减影所对应的蒙片像与充盈像之间存在位移（患者运动、呼吸、吞咽或胃肠蠕动）", "C": "X线管焦点尺寸过大", "D": "探测器信号漂移导致的系统性增益不均", "E": "曝光量过低导致量子噪声过大"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-101", "kp": "DSA配准不良伪影成因", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (2)成像方式和操作技术", "ex": "【为什么对】DSA减影要求蒙片与对比剂充盈像的解剖位置完全一致，两次采集间患者发生移动（呼吸、吞咽、胃肠蠕动等）会使骨与软组织不能完全相减，产生血管“双边”和残留的解剖结构伪影，即配准不良伪影。\n【为什么错】A：对比剂浓度过高可致血管密度过度饱和，但不引起双边残留。C：焦点大小影响空间分辨率，与减影伪影无关。D：信号漂移表现为增益不均或层次失真，非解剖残留。E：量子噪声为颗粒状噪声，不产生成形的双边结构。", "tr": "DSA核心伪影=运动/配准不良；处理靠屏气、胃肠抑制、再蒙片、像素移位及脉冲采集。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1012", "t": "单选题", "s": "MR成像中信噪比（SNR）随下列哪项因素的变化关系是“体素越大，SNR越高”？", "o": {"A": "窗宽与窗位", "B": "体素体积（像素面积×层厚）", "C": "重建矩阵大小与层厚无关", "D": "监视器分辨率", "E": "激光打印机密度"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-101", "kp": "SNR与体素的关系", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (1)概述", "ex": "【为什么对】SNR与体素体积成正比，体素越大（像素面积大或层厚大）所包含的质子越多，接收到的信号越强，SNR越高。\n【为什么错】A：窗宽窗位仅影响图像的显示灰阶，不改变原始信号。C：矩阵增大使像素变小，在层厚不变时体素变小，SNR下降，并非无关。D：监视器分辨率属于显示环节，不影响原始SNR。E：激光打印机密度属于输出设备，与MR信号采集无关。", "tr": "SNR∝体素体积；提高空间分辨率（减小体素）必然以SNR下降为代价，这是MR最基本的权衡。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1013", "t": "单选题", "s": "MR图像的空间分辨率主要取决于", "o": {"A": "窗宽和窗位", "B": "视野（FOV）、矩阵和层厚", "C": "重复时间TR", "D": "回波时间TE", "E": "反转时间TI"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-102", "kp": "MR空间分辨率的决定因素", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (1)概述", "ex": "【为什么对】MR空间分辨率由像素大小决定，像素=FOV/矩阵，故空间分辨率取决于FOV、矩阵及层厚（层面方向的层厚影响体素纵向范围与部分容积效应）。\n【为什么错】A：窗宽窗位是显示参数，不改变采集分辨率。C：TR主要决定T1加权与扫描时间，不决定空间分辨率。D：TE决定T2加权程度及信噪比，不影响几何分辨率。E：TI是反转恢复序列的反转时间，主要影响对比度加权而非空间分辨率。", "tr": "空间分辨率看“FOV/矩阵/层厚”；TR/TE/TI决定对比度，勿混。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1014", "t": "单选题", "s": "CT日常质量控制中，用于检测图像噪声水平与CT值均匀性的标准模体是", "o": {"A": "层厚模体", "B": "分辨力（线对）模体", "C": "水模", "D": "骨密度体模", "E": "乳腺加压体模"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-103", "kp": "CT水模的检测用途", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】水模（均匀水囊/水圆柱模体）用于检测CT值准确性、均匀性（中心与边缘CT值一致性）及噪声水平（均匀物质中像素值的标准差），是CT日常质控的基础模体。\n【为什么错】A：层厚模体用于检测实际扫描层厚。B：线对模体用于检测空间分辨率。D：骨密度体模用于定量CT骨密度校准。E：乳腺体模用于乳腺摄影质控，与CT无关。", "tr": "水模测“CT值、均匀性、噪声”；线对模体测“空间分辨率”；层厚模体测“层厚”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1015", "t": "单选题", "s": "使用CR系统投照后，图像上出现前次检查的残留影像（影像板擦除不全），最合理的处理是", "o": {"A": "加大曝光量后重新投照", "B": "对影像板重新进行强光擦除后再读取", "C": "在图像工作站调节窗宽窗位", "D": "报废该影像板并更换新板", "E": "调整CR扫描仪的扫描间距"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CRQC-101", "kp": "CR影像板擦除与残留伪影", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】CR的影像板（IP）读取后可擦除并重复使用，若上一幅潜影未擦除完全，会以残留影像形式叠加于新图像上。处理方法是重新用强光（均匀高亮度光源）充分擦除后再读取，必要时更换IP。\n【为什么错】A：加大曝光量不能消除残留潜影，反而增加剂量并使残留更明显。C：窗宽窗位只能改变显示，无法去除真实残留信号。D：仅个别IP残留一般经擦除即可解决，不必立即报废。E：扫描间距影响读出分辨率，与擦除残留无关。", "tr": "CR残留影像源于IP擦除不净，“重新强光擦除”是直接对策；IP寿命与擦除质量相关。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1016", "t": "单选题", "s": "DR系统每日开机后进行空气校准（平坦场校正）的主要目的是", "o": {"A": "消除探测器各像素增益不一致（像素响应差异）导致的图像不均匀伪影", "B": "增大图像的灰阶范围", "C": "提高系统的空间分辨率", "D": "减少检查所需的X线剂量", "E": "校准监视器的显示亮度"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-103", "kp": "DR平坦场校正目的", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】DR平板探测器各像素的增益与暗电流存在差异，且受温度等影响随时间漂移，空气校准（平坦场校正）采集均匀曝光数据以计算各像素校正系数，消除增益不一致产生的条纹、斑点等不均匀伪影。\n【为什么错】B：灰阶范围由ADC位深与图像处理决定。C：空间分辨率由像素尺寸与几何决定，校准不改变。D：校正不降低实际所需曝光量。E：监视器亮度校准属于显示设备的质控内容，与探测器空气校准无关。", "tr": "空气校准=探测器增益均匀性校正；勿与监视器校准、剂量优化混为一谈。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1017", "t": "单选题", "s": "在保证诊断所需图像质量的前提下，降低CT检查辐射剂量最常用且有效的措施是", "o": {"A": "减小重建矩阵", "B": "降低管电流（mAs）并配合迭代重建算法", "C": "将所有扫描层厚增大至10 mm", "D": "缩小扫描视野", "E": "提高管电压"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-104", "kp": "CT低剂量技术与质量控制", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】剂量与mAs近似成正比，降低mAs可直接减少剂量，但会增加噪声；迭代重建（IR）在低噪声条件下重建图像，可补偿低mAs带来的噪声增加，是当前保证图像质量前提下降低剂量的核心手段。\n【为什么错】A：矩阵主要影响空间分辨率，对剂量影响甚微。C：增大层厚至10 mm可降剂量但明显损害分辨率与部分容积效应，不能满足多数诊断要求。D：缩小FOV不改变剂量（剂量由mAs与层厚等决定）。E：提高管电压通常增加剂量且改变对比度，不是降剂量措施。", "tr": "降剂量靠“降mAs+迭代重建”联动；“降mAs不重建”会导致噪声明显增大。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1018", "t": "单选题", "s": "为减少DSA检查中患者运动引起的配准不良伪影，最有效的技术措施是", "o": {"A": "提高对比剂浓度和用量", "B": "嘱患者屏气、抑制吞咽，并采用曝光时间短的脉冲采集或再蒙片、像素移位等技术", "C": "增大X线管焦点尺寸", "D": "将帧率提高至30帧/秒", "E": "增大像素尺寸"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-102", "kp": "DSA运动伪影的改善措施", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (5)改善措施", "ex": "【为什么对】运动伪影源于蒙片与充盈像间位移，改善的根本在于减少运动（嘱患者屏气、抑制吞咽和胃肠蠕动）并缩短采集时间（脉冲采集），图像后处理方面可采用再蒙片、像素移位（pixel shifting）等配准技术加以纠正。\n【为什么错】A：对比剂浓度影响血管显影密度，不解决位移问题。C：增大焦点反而降低空间分辨率。D：提高帧率虽缩短单帧曝光时间但延长整体采集窗，对减少运动伪影帮助有限。E：增大像素尺寸降低空间分辨率，不能纠正位移。", "tr": "DSA运动伪影“防+纠”：屏气抑制为主，再蒙片/像素移位为纠；加大剂量与帧率不是关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1019", "t": "单选题", "s": "保持视野不变，仅将MR采集矩阵由256×256增大为512×512时，图像信噪比（SNR）的变化是", "o": {"A": "保持不变", "B": "提高到原来的约2倍", "C": "降低到原来的约1/4", "D": "与矩阵大小无关", "E": "降低到原来的约一半"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-103", "kp": "矩阵增大对SNR的影响", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】FOV不变、矩阵从256增至512，像素边长减半、像素面积（体素体积）降为原来的1/4，而SNR与体素体积成正比，故SNR约降为原来的1/4，若需保持SNR必须延长扫描时间（增加NEX）或接受噪声增大。\n【为什么错】A：体素变小、信号减少，SNR必然改变。B：增大矩阵使体素变小，SNR应下降而非提高。D：SNR与体素大小密切相关。E：体素缩小4倍对应SNR降至约1/4而非1/2。", "tr": "矩阵加倍→像素面积变1/4→SNR约变1/4；牢记“SNR∝体素体积”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1020", "t": "单选题", "s": "关于MR成像参数间的相互影响，下列叙述正确的是", "o": {"A": "增大TR可缩短扫描时间", "B": "保持矩阵不变而减小FOV可提高空间分辨率，但SNR下降且相位方向更易出现卷褶伪影", "C": "增大层厚会降低SNR", "D": "减小矩阵可提高空间分辨率", "E": "增大NEX会缩短扫描时间"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-104", "kp": "MR参数相互影响综合判断", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】FOV减小时像素变小、空间分辨率提高，但体素缩小使SNR下降；同时FOV内相位编码覆盖范围不足，视野外组织折叠入图内，故相位方向更易出现卷褶伪影。\n【为什么错】A：扫描时间与TR正相关，增大TR使扫描时间延长。C：层厚增大使体素增大、SNR升高而非降低。D：减小矩阵使像素增大、空间分辨率下降。E：NEX是平均次数，增大NEX延长扫描时间而提高SNR。", "tr": "FOV↓→分辨率↑但SNR↓＋卷褶风险↑；TR↑、NEX↑均延长扫描时间。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1021", "t": "单选题", "s": "腹部CT增强扫描拟在保证图像质量的前提下缩短扫描时间，下列措施不恰当的是", "o": {"A": "适当增大螺距", "B": "采用更宽探测器覆盖范围", "C": "提高机架旋转速度", "D": "大幅降低管电流且不采用迭代重建", "E": "使用双源或双能量快速扫描模式"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-105", "kp": "CT缩短扫描时间与质量控制", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】缩短扫描时间应通过增大螺距、加宽探测器覆盖、提高转速等方式实现，这些措施可基本保持剂量与噪声水平；而大幅降低mAs又不配合迭代重建会显著增大噪声、降低密度分辨率，无法保证诊断图像质量，故不恰当。\n【为什么错】A：增大螺距在合理范围内缩短扫描时间且图像质量可接受。B：宽探测器覆盖可减少扫描圈数、缩短时间。C：提高转速缩短单周采集时间。E：双源/双能量模式可加快采集并缩短时间。", "tr": "缩短扫描时间与保证质量需平衡；“降mAs必须配迭代重建”，否则违反质量控制原则。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U05-1022", "t": "单选题", "s": "患者拟行头颅MR检查，技师希望在T2WI序列上缩短扫描时间且尽量保持图像质量。下列最合理的措施是", "o": {"A": "单独增大TR", "B": "单独增大NEX", "C": "启用并行采集技术（SENSE/GRAPPA/ASSET）并相应调整参数", "D": "将矩阵由512×512降至128×128", "E": "减小层厚并增大FOV"}, "d": "难", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-105", "kp": "并行采集缩短扫描时间", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】并行采集技术利用多通道线圈的空间信息减少相位编码步数，可将扫描时间缩短为1/加速因子，同时SNR下降约为根号下加速因子倍，通过适当增大NEX或微调参数即可在基本保持质量的前提下明显缩短时间，是临床最常用措施。\n【为什么错】A：单独增大TR延长扫描时间并改变对比度。B：单独增大NEX延长扫描时间（虽然提高SNR）。D：矩阵降为128×128会显著降低空间分辨率，超出可接受范围。E：减小层厚降低SNR，增大FOV降低空间分辨率，均不合理。", "tr": "缩短MR扫描时间的首选是并行采集；NEX/TR变化方向“增大=延长时间”，勿选反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U05-1023", "t": "多选题", "s": "关于影像质量保证（QA）与质量控制（QC）的关系，下列叙述正确的有", "o": {"A": "QC是QA的重要组成部分", "B": "QA的最终目的是确保影像质量满足诊断要求并持续改进", "C": "QC包括对成像设备与成像过程关键指标的检测和校正", "D": "QA仅指对图像质量的客观评价", "E": "QA与QC彼此独立、互不相干"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-105", "kp": "QA与QC的关系", "ch": "五、影像质量管理 → 1.概述 → (1)基本概念", "ex": "【为什么对】QC是对设备与技术指标进行检测、校正的具体环节，从属于QA整体；QA以影像质量满意并持续改进为目标，涵盖组织、制度、人员、设备与QC全部内容。\n【为什么错】D：QA不仅包含客观评价，还包含主观评价、管理制度、人员培训与QC活动。E：QC是QA的子系统，二者是从属关系而非相互独立。", "tr": "QA为大系统（含组织、管理、QC），QC为技术检测校正环节，是“整体与局部”关系。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1024", "t": "多选题", "s": "影像质量综合评价法通常应包含的内容有", "o": {"A": "物理与技术指标（如分辨率、噪声、灰阶）评价", "B": "观察者视觉判断与临床诊断价值的评价", "C": "仅依据设备出厂检验数据", "D": "受检者辐射剂量评估", "E": "与科室管理制度无关的纯技术评价"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-106", "kp": "综合评价法的构成", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】综合评价法将物理（客观）指标、观察者（主观/临床）评价及受检者剂量等多个维度结合起来，全面衡量影像质量，故物理技术指标、临床观察判断和剂量评估均属其内容。\n【为什么错】C：出厂检验数据只反映出厂时性能，不能替代在临床环境下的综合评价。E：综合评价需结合管理制度与临床实际，并非脱离管理体系的纯技术评价。", "tr": "综合评价=物理量+临床观察+剂量多维度结合，绝非单一指标或出厂数据。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1025", "t": "多选题", "s": "关于CR系统的质量控制，下列叙述正确的有", "o": {"A": "影像板（IP）应避免强光直射，使用前应充分擦除", "B": "IP板擦除不全会产生残留影像伪影", "C": "CR质量控制无需检测噪声水平", "D": "IP板有使用寿命，应定期检测其性能", "E": "读出扫描装置的采样间距不会影响图像空间分辨率"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CRQC-102", "kp": "CR质量控制要点", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】IP受环境散射线等影响易积累潜影，使用前需擦除并避免强光直射；擦除不净会以残留影像污染新图；IP有寿命限制，需定期进行响应均匀性、擦除效率等性能检测。\n【为什么错】C：噪声水平（本底噪声、量子噪声）是数字系统重要质控指标，CR亦需检测。E：读出采样间距（采样密度）直接影响空间分辨率，是CR质控内容之一。", "tr": "CR质控同样关注“噪声、分辨率、擦除效率”；IP寿命与残留伪影是CR特有考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1026", "t": "多选题", "s": "DR系统日常及定期质量控制应包含的内容有", "o": {"A": "探测器平坦场（空气）校准", "B": "曝光指数（剂量指示）监测", "C": "空间分辨率与噪声检测", "D": "仅检查机械臂与立柱运动功能", "E": "监视器显示一致性检查"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-104", "kp": "DR质量控制内容", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】DR质控覆盖探测器（平坦场校准、线性、噪声、空间分辨率）、剂量（曝光指数监测）与显示链（监视器一致性）等多个环节，保证从采集到显示的图像质量。\n【为什么错】D：机械臂运动检查属于设备维护内容，不能替代探测器与图像质量的核心质控项目。", "tr": "DR质控核心在“探测器性能＋剂量指示＋显示链”，机械/电气检查不是图像质控主体。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1027", "t": "多选题", "s": "数字乳腺X线摄影（FFDM/DBT）质量控制的内容包括", "o": {"A": "平均腺体剂量（AGD）监测", "B": "使用乳腺体模评估纤维、微钙化团块、肿块的可见数目", "C": "压迫器压力与自动曝光控制功能检查", "D": "只关注空间分辨率，与辐射剂量无关", "E": "定期进行系统几何（放大率、定位）校准"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-103", "kp": "数字乳腺摄影质量控制", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】乳腺摄影质控既包括剂量（AGD）监测与体模图像质量评估，也包括压迫/自动曝光等功能检查和系统几何校准，是多环节、质量与剂量并重的完整体系。\n【为什么错】D：乳腺摄影必须同时兼顾图像质量与低剂量，剂量监测是质控的强制内容，二者缺一不可。", "tr": "乳腺质控“质量＋剂量”双指标；ACD体模可见结构阈值是核心判定依据。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1028", "t": "多选题", "s": "为改善CT图像的密度分辨率（低对比分辨率），可采取的措施有", "o": {"A": "增大管电流（mAs）", "B": "适当增大层厚", "C": "采用迭代重建算法降低噪声", "D": "减小重建矩阵（增大像素）", "E": "缩短扫描时间"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-106", "kp": "提高CT密度分辨率的措施", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】密度分辨率主要受噪声限制：增大mAs、增大层厚可增加光子数、降低噪声；迭代重建可抑制噪声；减小矩阵使像素增大、单像素光子增多，噪声下降，均有利于提高低对比分辨率。\n【为什么错】E：缩短扫描时间通常伴随光子数减少、噪声增大，使密度分辨率下降，且可能引入运动伪影，不是改善密度分辨率的措施。", "tr": "“增光子、降噪声”是提高密度分辨率主线（mAs↑、层厚↑、迭代重建）；缩短时间方向相反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1029", "t": "多选题", "s": "下列措施中，有助于减少DSA图像运动（配准不良）伪影的有", "o": {"A": "嘱患者屏气并抑制吞咽", "B": "腹部检查前抑制肠蠕动", "C": "采用再蒙片（remasking）技术", "D": "增大对比剂用量", "E": "使用像素移位（pixel shifting）校正"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-103", "kp": "DSA运动伪影的防治措施", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (5)改善措施", "ex": "【为什么对】防治运动伪影分“防”与“纠”两级：防——嘱患者屏气、抑制吞咽和肠蠕动；纠——再蒙片、像素移位等配准处理，A、B、C、E均为有效措施。\n【为什么错】D：对比剂用量影响血管显影密度与对比度，不能消除蒙片与充盈像之间的位移，且过量会增加患者负担与伪影风险。", "tr": "DSA运动伪影“防（屏气/抑制蠕动）＋纠（再蒙片/像素移位）”，对比剂剂量不是对策。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1030", "t": "多选题", "s": "在不明显延长扫描时间的前提下，下列措施中可提高MR图像SNR的有", "o": {"A": "增大体素（增大层厚或像素）", "B": "使用更高场强（如1.5T改为3.0T）", "C": "采用多通道线圈及并行采集", "D": "增大NEX", "E": "减小FOV"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-106", "kp": "提高MR SNR的措施", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】SNR与体素体积成正比，增大体素可提高SNR；高场强与多通道线圈均能提高信号采集效率；并行采集在缩短时间的同时SNR下降不多（为根号下加速因子的代价），配合上述措施可在时间基本不变的前提下提升SNR。\n【为什么错】D：增大NEX（平均次数）提高SNR但扫描时间成倍延长。E：减小FOV使像素变小、体素减小，SNR下降。", "tr": "提SNR的“免费”手段=增大体素/高场/多通道线圈；NEX是“花钱（时间）买SNR”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1031", "t": "多选题", "s": "下列因素中，能够影响MR扫描时间的有", "o": {"A": "重复时间TR", "B": "相位编码方向矩阵大小", "C": "平均次数NEX", "D": "窗宽窗位", "E": "并行采集的加速因子"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-107", "kp": "MR扫描时间的影响因素", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】扫描时间≈TR×相位编码步数×NEX×（序列加权等）÷并行采集加速因子，故TR、相位矩阵、NEX和并行采集加速因子均直接影响扫描时间。\n【为什么错】D：窗宽窗位只是图像显示参数，改变灰度显示范围，不影响采集和扫描时间。", "tr": "扫描时间公式：TR×相位步数×NEX÷加速因子；显示参数（窗宽窗位）绝不参与时间计算。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1032", "t": "多选题", "s": "关于CT图像质量控制的内容，下列叙述正确的有", "o": {"A": "用标准水模检测CT值准确性、均匀性与噪声", "B": "用高对比分辨力（线对）模体检测空间分辨率", "C": "用低对比模体检测低对比分辨率（密度分辨率）", "D": "均匀性检测反映图像中心与边缘CT值的一致性", "E": "层厚检测与图像质量无关，无需进行"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-107", "kp": "CT质控检测项目与方法", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】CT质控按检测目的选用不同模体：水模测CT值、均匀性、噪声；线对模体测空间分辨率；低对比模体测密度分辨率。A、B、C、D均正确。\n【为什么错】E：层厚影响部分容积效应与空间分辨率，实际层厚与标称不符会造成图像质量与测量误差，属于常规质控项目，不能省略。", "tr": "模体用途对应关系：水模→CT值/均匀性/噪声，线对→空间分辨率，低对比模体→密度分辨率。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1033", "t": "多选题", "s": "关于MR图像空间分辨率与SNR之间的权衡关系，下列叙述正确的有", "o": {"A": "保持FOV不变增大矩阵，空间分辨率提高而SNR下降", "B": "保持矩阵不变增大FOV，像素增大、SNR升高而空间分辨率下降", "C": "减小层厚可减轻部分容积效应，但SNR下降", "D": "增大NEX可补偿矩阵增大所致的SNR下降，但扫描时间延长", "E": "增大层厚可同时提高空间分辨率与SNR"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-108", "kp": "空间分辨率与SNR的权衡", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】空间分辨率与SNR以体素为纽带互为代价：体素减小则分辨率提高、SNR下降；体素增大反之。减小层厚减少部分容积效应但体素变小、SNR下降；增大NEX可补偿SNR但时间延长，A、B、C、D均正确。\n【为什么错】E：增大层厚使体素增大、SNR升高，但同时加重部分容积效应、沿层厚方向空间分辨率下降，不能“同时提高空间分辨率”。", "tr": "凡是“体素变小”都提高分辨率而损SNR；“补偿SNR”就要付出扫描时间（NEX↑）代价。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U05-1034", "t": "多选题", "s": "某DSA设备近期图像质量普遍下降，下列可能的原因中正确的有", "o": {"A": "患者运动导致配准不良伪影增多", "B": "探测器灵敏度漂移而未及时校准", "C": "平板探测器老化使MTF下降、空间分辨率降低", "D": "常规使用大焦点摄影以提高空间分辨率", "E": "X线管焦点变大使几何模糊增加"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-104", "kp": "DSA图像质量下降原因分析", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (1)设备结构", "ex": "【为什么对】DSA图像质量受患者配合（运动伪影）、探测器状态（灵敏度漂移、老化致MTF下降）、X线源（焦点增大致几何模糊）等综合影响，A、B、C、E均为图像质量下降的可能原因。\n【为什么错】D：焦点越大几何模糊（半影）越明显、空间分辨率越低，常规使用大焦点恰恰会降低而非提高空间分辨率。", "tr": "“焦点大→模糊大、分辨率低”；探测器老化→MTF/DQE下降；校准是保持稳定的关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "DSA图像质量控制", "页": 130}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U05-1035", "t": "多选题", "s": "技师为膝关节MR检查将FOV由180 mm缩小至150 mm而矩阵保持不变，关于此次参数调整的叙述，正确的有", "o": {"A": "空间分辨率提高", "B": "SNR下降", "C": "相位方向更易出现卷褶伪影", "D": "扫描时间自动缩短", "E": "像素尺寸增大"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-109", "kp": "FOV调整对图像参数的影响", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】矩阵不变而FOV减小，像素=FOV/矩阵变小，空间分辨率提高；体素变小使SNR下降；FOV缩小时相位方向覆盖范围不足，视野外组织折叠入图，卷褶伪影风险增大，A、B、C均正确。\n【为什么错】D：扫描时间取决于TR、相位编码步数与NEX，改变FOV不改变相位步数，扫描时间不变。E：FOV减小使像素变小而非增大。", "tr": "FOV↓→像素↓→分辨率↑、SNR↓、卷褶风险↑；FOV不直接影响扫描时间。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U05-1036a", "t": "共用题干题", "s": "该水模图像中心与边缘CT值明显不一致，反映的CT图像质量问题是", "o": {"A": "空间分辨率下降", "B": "图像均匀性（场均匀性）不良", "C": "层厚不准", "D": "螺旋扫描伪影", "E": "部分容积效应"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-108", "kp": "CT图像均匀性检测", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】均匀性反映同一均匀物质（水模）在图像不同位置（中心与边缘）CT值的一致性，中心与边缘CT值差异超过标准即判为均匀性不良，常提示探测器通道校准不良、球管或X线分布不均等问题。\n【为什么错】A：空间分辨率用线对模体检测，反映高频细节分辨能力，与CT值漂移无关。C：层厚不准影响部分容积与层厚方向分辨率。D：螺旋伪影多为条状、风车样伪影，不表现为CT值区域性偏移。E：部分容积效应出现在物体边缘密度突变处，水模均匀介质中不存在。", "tr": "“中心与边缘CT值不一致”=均匀性不良；均匀性、CT值、噪声三者均由水模检测。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0501", "gs": "某医院CT室进行每月日常质量控制，将标准水模置于扫描野中心，按常规头部扫描条件扫描并重建。测量水模图像中心区域CT值约为-2 HU，而边缘区域CT值约为18 HU，且图像噪声标准差明显增大，超过科室质量控制标准限值。质控技师拟分析原因并采取处理措施。"}, {"id": "U05-1036b", "t": "共用题干题", "s": "针对该CT设备噪声标准差超标的问题，下列处理措施最恰当的是", "o": {"A": "立即停机更换X线管球", "B": "检查并校正探测器系统（增益校准），同时核实管电流、重建参数设置后再复测", "C": "仅增大窗宽以掩盖噪声", "D": "将扫描层厚增大至10 mm后继续使用", "E": "忽略噪声指标，只关注空间分辨率检测结果"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-109", "kp": "CT噪声超标处理措施", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】噪声超标需按“检查参数—校准系统—复测”的顺序处理：先核实扫描条件（mAs、重建算法等）是否合理，再对探测器进行增益校准以消除通道响应差异，校正后重新用水模复测确认达标。\n【为什么错】A：球管老化并非噪声增大的唯一原因，未排查参数与探测器即更换球管不恰当。C：窗宽只改变显示范围，不降低真实噪声。D：增大层厚虽可降低噪声但明显损害分辨率并加重部分容积效应，不是规范处理。E：噪声是密度分辨率的关键指标，不能忽略。", "tr": "噪声超标处理流程“查参数→校探测器→复测”；靠窗宽掩盖或加大层厚均属错误应对。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0501", "gs": ""}, {"id": "U05-1037a", "t": "共用题干题", "s": "该减影图像出现上述表现最可能的原因是", "o": {"A": "对比剂过敏反应", "B": "蒙片与充盈像之间发生位移（呼吸、肠蠕动等运动所致配准不良）", "C": "X线管焦点过小", "D": "图像增强器老化", "E": "曝光量过大"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-105", "kp": "DSA配准不良伪影的识别", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (2)成像方式和操作技术", "ex": "【为什么对】DSA减影要求蒙片与充盈像解剖位置完全一致，呼吸、肠蠕动使两次采集间发生位移，导致骨骼、肠气不能完全相减而残留，血管边缘出现“双边”，即典型的配准不良（运动）伪影，与题干中呼吸起伏、肠气明显相符。\n【为什么错】A：对比剂过敏反应表现为皮疹、血压下降等临床表现，不引起减影残留。C：焦点小反而提高空间分辨率，不产生双边伪影。D：图像增强器老化表现为亮度下降、模糊或增益不均，非运动型残留。E：曝光量过大致使噪声小、信号饱和，不产生双边结构。", "tr": "DSA“双边+骨肠残留”=运动/配准不良伪影；常见诱因为呼吸、吞咽、肠蠕动。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0502", "gs": "患者男，55岁，因腹胀、腹主动脉瘤术前评估行腹主动脉DSA检查。造影过程中可见患者腹部随呼吸起伏、肠气明显，减影图像上肠气影与骨骼影未完全消除，血管边缘出现明显“双边”表现，腹主动脉及分支显示模糊，影响狭窄程度判断。"}, {"id": "U05-1037b", "t": "共用题干题", "s": "为改善该患者复查时的图像质量，下列准备与操作中不恰当的是", "o": {"A": "检查前禁食，必要时给予抑制肠蠕动药物", "B": "嘱患者配合屏气并减少腹部活动", "C": "采用脉冲采集以缩短曝光时间", "D": "让患者检查前进食以保证体力", "E": "必要时采用再蒙片或像素移位进行后处理校正"}, "d": "难", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-106", "kp": "DSA检查准备与运动伪影防治", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (4)患者本身因素", "ex": "【为什么对】腹部DSA前应禁食、抑制肠蠕动以减少胃肠道气体与蠕动；扫描中嘱患者屏气、减少活动；采用脉冲采集缩短曝光时间；必要时用再蒙片、像素移位校正残留位移，故A、B、C、E均为恰当措施。\n【为什么错】A：禁食并给予抑制肠蠕动药物是减少肠气与蠕动的正确准备，不属于不恰当操作。B：嘱患者配合屏气并减少腹部活动可有效减少运动伪影，恰当。C：脉冲采集缩短曝光时间、减少运动干扰，恰当。E：再蒙片与像素移位是纠正配准不良的有效后处理，恰当。D：检查前进食会增加胃肠蠕动与气体，加重运动伪影及气体重叠，且存在呕吐误吸等风险，属不恰当操作。", "tr": "腹部DSA“禁食+抑制蠕动+屏气”是标准准备；进食与饱餐会加重肠气蠕动伪影。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0502", "gs": ""}, {"id": "U05-1038a", "t": "共用题干题", "s": "在不延长扫描时间的前提下，提高该序列SNR最直接的方法是", "o": {"A": "增大层厚（如增至6 mm）以增大体素", "B": "将矩阵减小至128×128", "C": "将FOV增大至350 mm", "D": "提高重复时间TR", "E": "减小NEX"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-110", "kp": "通过体素调整提高SNR", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】SNR与体素体积成正比，增大层厚使体素增大、信号增强，SNR直接提高，且层厚变化不改变TR、矩阵与NEX，扫描时间不变，是“不延长时间提SNR”的最直接方法。\n【为什么错】B：减小矩阵使像素增大、体素增大，虽可提高SNR，但空间分辨率明显下降，作为首选调整幅度过大。C：增大FOV使像素增大、SNR升高，但会缩小有效显示区域、降低分辨率，且需重设定位。D：提高TR延长扫描时间且改变对比度。E：减小NEX降低SNR，方向相反。", "tr": "不延长扫描时间提SNR=增大体素（增层厚/增像素）；NEX、TR的增大都会延长时间。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0503", "gs": "患者女，45岁，腰痛伴右下肢放射痛，行腰椎MR检查。矢状位T2WI图像整体噪声明显、SNR不足，椎体与椎间盘信号区分欠清晰。该序列为2D快速自旋回波，层厚4 mm，矩阵256×256，FOV 280 mm，NEX 2，扫描时间约3分钟，患者因疼痛配合欠佳、希望尽快完成检查。"}, {"id": "U05-1038b", "t": "共用题干题", "s": "若既要保持较高的空间分辨率（薄层、高矩阵），又要获得可接受的SNR并减少运动伪影，合理的参数组合是", "o": {"A": "保持薄层高矩阵，适当增大NEX并配合并行采集与流动补偿技术", "B": "单纯减小矩阵", "C": "单纯增大层厚", "D": "关闭并行采集功能", "E": "减小FOV且不增加NEX"}, "d": "难", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-111", "kp": "MR高分辨率与SNR时间平衡", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】薄层高矩阵使体素变小、SNR下降，需增大NEX提高SNR（代价是时间）；并行采集可在缩短或抵消时间延长的同时保持分辨率；流动补偿减少脑脊液等流动信号伪影。三措并举可在保证分辨率的前提下兼顾SNR、时间与伪影控制。\n【为什么错】B：单纯减小矩阵降低空间分辨率。C：单纯增大层厚增加部分容积效应，损失薄层分辨率。D：关闭并行采集会延长扫描时间，不利于配合欠佳患者。E：减小FOV使SNR进一步下降且不增加NEX，无法补偿。", "tr": "“薄层高矩阵→SNR亏空”需用“NEX＋并行采集”补齐；单动任一项都会破坏平衡。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0503", "gs": ""}, {"id": "U05-1039a", "t": "共用题干题", "s": "处理该问题前应首先执行的质控操作是", "o": {"A": "增大曝光剂量", "B": "执行探测器平坦场（空气）校准", "C": "更换显示监视器", "D": "调整窗宽窗位", "E": "升级图像后处理软件"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-105", "kp": "DR平坦场校准操作", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】平板探测器各像素增益不一致产生的图像不均匀，应通过平坦场（空气）校准——在无被照体条件下均匀曝光采集参考数据、计算校正系数——来消除，是DR质控的首选处理。\n【为什么错】A：增大曝光剂量不能校正像素间增益差异，且增加受检者剂量。C：监视器异常表现为显示整体亮度/色彩问题，与图像数据不均匀无关。D：窗宽窗位只改变显示灰阶，不能消除真实的不均匀。E：图像处理软件无法修正探测器硬件的增益不一致。", "tr": "探测器增益不均→平坦场校准；监视器/窗宽窗位/软件均不能解决探测器层面问题。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0504", "gs": "某医院数字X线摄影室（DR）新安装一块平板探测器，试用期间在均匀模体图像上发现明显的条纹状密度不均与颗粒样斑点，不同位置像素亮度差异显著，图像灰阶不均匀。质控人员结合平板探测器成像原理分析后认为系像素增益不一致所致。"}, {"id": "U05-1039b", "t": "共用题干题", "s": "平坦场校准的主要作用机理是", "o": {"A": "增大X线球管的输出剂量", "B": "利用均匀曝光数据计算各像素增益校正系数，补偿像素响应差异", "C": "提高探测器的空间分辨率", "D": "减少到达探测器的散射线", "E": "改变图像的重建矩阵大小"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-106", "kp": "DR平坦场校准原理", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】平坦场校正在无被照体、均匀X线照射条件下采集图像，以其为基准计算每个像素的增益校正因子，使各像素对相同入射剂量的响应趋于一致，从而消除增益不一致产生的条纹与斑点伪影。\n【为什么错】A：校准是数据处理而非提高球管输出。C：空间分辨率由像素尺寸与系统MTF决定，校准不改变。D：散射线量与照射条件及限束有关，校准不改变散射水平。E：矩阵由采样与重建参数决定，与校准无关。", "tr": "平坦场校准本质是“软件层面像素增益补偿”，不涉及剂量、分辨率或散射的改变。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0504", "gs": ""}, {"id": "U05-1040", "t": "案例分析题", "s": "患者女，48岁，参加乳腺X线筛查项目，无自觉症状。医院新启用一台数字乳腺摄影系统（FFDM，钼靶X线管、自动曝光控制），质控技师按ACR程序对平均腺体剂量（AGD）进行评估，同时进行体模图像质量测试，检测时使用乳腺等效体模并分别模拟不同压迫厚度测量AGD。若AGD测量值超过标准限值，将分析管电压、靶/滤过组合及自动曝光设置等因素并调整后复测。", "o": {"A": "AGD与乳腺压迫厚度无关，无需分厚度测量", "B": "AGD应在保证图像质量的前提下尽可能低，用乳腺等效体模分厚度测量，超标时应分析并调整靶/滤过、管电压等参数后复测", "C": "AGD越大图像质量越好，应尽量提高AGD", "D": "AGD只需设备验收时测量一次，日常无需监测", "E": "AGD仅由管电流决定，与管电压、压迫厚度无关"}, "d": "中", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-104", "kp": "乳腺AGD测量与评价", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】AGD是乳腺摄影受检者剂量的核心指标，应在保证图像质量的前提下尽可能低（符合ALARA原则）；压迫厚度不同、曝光条件不同，须用乳腺等效体模分厚度测量；超标时要调整靶/滤过组合、管电压及自动曝光参数后复测，符合质控要求。\n【为什么错】A：压迫厚度直接影响所需曝光量，AGD随厚度增大而升高，必须分厚度评估。C：AGD增大不代表图像质量更好，且违背合理尽可能低原则。D：AGD须定期监测，非仅验收一次。E：AGD由管电压、靶/滤过组合、曝光量、压迫厚度等共同决定，非仅管电流。", "tr": "AGD评价必须“质量+剂量”双达标；分厚度测量、超标调整参数复测是标准流程。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1041", "t": "案例分析题", "s": "患者男，62岁，吸烟史40年，每日约20支，参加社区肺癌低剂量CT筛查项目。设备为64层螺旋CT，技师拟采用管电压100 kV、低管电流（mAs）并配合迭代重建算法完成扫描，既需尽量降低受检者辐射剂量，又需保证对肺内5 mm以下小结节与磨玻璃密度的检出能力。扫描后技师发现图像噪声较常规剂量明显增高，部分磨玻璃影显示欠佳。请评价该扫描方案在剂量控制与图像质量之间的平衡是否合理。", "o": {"A": "该方案不合理，低剂量扫描会使空间分辨率明显下降", "B": "该方案合理，降低mAs配合迭代重建可有效降低剂量并控制噪声，保持肺结节检出能力", "C": "降低管电压会明显增加辐射剂量", "D": "该方案下磨玻璃样结节将完全无法显示", "E": "迭代重建会显著降低空间分辨率，不适用于肺筛查"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-110", "kp": "低剂量胸部CT与迭代重建", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】低剂量肺癌筛查的核心是用低kV、低mAs配合迭代重建：降低剂量可减少受检者辐射，迭代重建在噪声抑制上优于滤波反投影，可在不牺牲密度分辨率的前提下保持小结节与磨玻璃密度的检出能力，方案合理。\n【为什么错】A：低剂量扫描主要影响噪声与密度分辨率，空间分辨率由矩阵、算法等决定，并不明显下降。C：降低管电压通常降低剂量（同时需注意改变对比度与噪声平衡），不是增加剂量。D：合理低剂量方案下磨玻璃结节仍可检出，不会完全无法显示。E：迭代重建以降低噪声为主要目的，不显著降低空间分辨率。", "tr": "低剂量CT=低kV/mAs+迭代重建；迭代重建的作用是“抑制噪声保密度分辨率”，勿误认为损空间分辨率。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1042", "t": "案例分析题", "s": "患者男，60岁，因反复发作性右侧肢体无力1个月，临床疑左侧颈内动脉重度狭窄，拟行左侧颈内动脉DSA造影检查。患者既往有慢性咳嗽史，造影过程中吞咽及轻微咳嗽动作频繁，减影图像上出现血管边缘双边现象，颅底骨骼及软组织影未完全消除，病变血管显示模糊，影响狭窄程度判断与介入治疗决策。技师拟采取系列措施改善图像质量，请分析最恰当的处理策略。", "o": {"A": "增大对比剂注射总量以掩盖伪影", "B": "嘱患者配合屏气、减少吞咽咳嗽，改用脉冲采集缩短曝光时间，必要时采用再蒙片或像素移位校正", "C": "提高管电压以增强图像对比度", "D": "换用更大焦点球管", "E": "保持现有条件，直接以减影图像出具诊断报告"}, "d": "难", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-107", "kp": "DSA运动伪影的综合处理", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (5)改善措施", "ex": "【为什么对】颈动脉DSA的吞咽/咳嗽动作是配准不良伪影的直接原因，处理应从“防”入手：嘱患者配合屏气、尽量减少吞咽与咳嗽；以脉冲采集缩短曝光时间；再结合“纠”的再蒙片、像素移位等后处理校正，综合改善图像质量。\n【为什么错】A：增大对比剂总量不能消除位移伪影，反而增加剂量与并发症风险。C：管电压影响X线质与对比，不解决运动伪影。D：大焦点增加几何模糊，降低空间分辨率。E：伪影明显时图像不能满足诊断要求，应处理后再评，直接报告会导致漏诊误判。", "tr": "DSA运动伪影“防（屏气/脉冲采集）＋纠（再蒙片/像素移位）”缺一不可；对比剂、kV、焦点均非对策。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U05-1043", "t": "案例分析题", "s": "患者男，70岁，因阵发性头晕、行走不稳行头颅MR平扫。患者情绪紧张、配合欠佳，检查中头部频繁活动，技师需在尽量短时间内完成检查并控制运动伪影对图像质量的影响。拟在T2WI和T2-FLAIR序列中启用并行采集技术以缩短扫描时间，并选择对运动相对不敏感的序列与参数组合，必要时通过增加平均次数（NEX）补偿因加速采集导致的信噪比下降。请分析该扫描策略中的关键要点。", "o": {"A": "增大矩阵以缩短扫描时间", "B": "启用并行采集缩短扫描时间，优先采用快速、对运动不敏感的序列，必要时增加NEX补偿SNR", "C": "增大NEX本身会缩短扫描时间，应优先采用", "D": "增大层厚至10 mm可显著提高图像质量", "E": "延长TR可缩短扫描时间"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-112", "kp": "配合欠佳患者的MR扫描策略", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】配合欠佳患者应缩短采集时间以减少运动伪影：并行采集可缩短扫描时间，快速序列（如T2-FLAIR、SS-FSE等）对运动相对不敏感；并行采集会带来一定SNR损失，必要时增加NEX补偿，组合策略合理。\n【为什么错】A：增大矩阵延长扫描时间，与目标相反。C：增大NEX延长扫描时间。D：层厚10 mm部分容积效应明显，显著降低图像质量。E：延长TR延长扫描时间且改变对比度。", "tr": "运动患者策略“并行采集+快速序列+必要时补NEX”；凡增大矩阵、NEX、TR的方向都延长时间。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1044", "t": "案例分析题", "s": "患者男，35岁，因咳嗽就诊行胸部X线摄影，使用CR系统。技师将影像板（IP）插入扫描仪读取后，图像上隐约可见上一例患者腰椎检查的残留轮廓，且本幅图像对比度下降、背景颗粒感增强。技师检查发现该IP板使用前擦除时间不足，且曾多次暴露于强光下，怀疑存在潜影残留。请分析CR系统残留影像的正确处理措施与日常预防方法。", "o": {"A": "对该IP板重新进行强光擦除后再读取，并规范IP使用前的擦除流程", "B": "残留影像不影响诊断，可直接出具报告", "C": "增大曝光量重新投照，残留即可消失", "D": "立即报废该IP板并更换新板", "E": "调整窗宽窗位即可消除残留影像"}, "d": "难", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CRQC-103", "kp": "CR残留影像的处理", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】CR残留影像是IP板擦除不净、上一幅潜影残留所致。正确做法是对IP重新进行强光擦除后再读取，并规范使用前的擦除流程（保证擦除时间与光强）以避免再次发生，既解决问题又节约IP资源。\n【为什么错】B：残留影像与真实病灶图像重叠，可能造成误诊漏诊，不能直接出报告。C：加大曝光量不能消除已存在的潜影残留，反而增加剂量并使残留更明显。D：单块IP因擦除不足残留，通过强光擦除通常即可恢复，无需立即报废，浪费资源。E：窗宽窗位只改变显示，无法去除真实残留信号。", "tr": "CR残留=IP擦除不净→“强光重擦”；窗宽窗位、加大曝光均属无效手段。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U05-1045", "t": "案例分析题", "s": "患者女，32岁，因膝关节扭伤后疼痛、活动受限行右膝关节MR检查。技师为清晰显示半月板及关节软骨细节，将矢状位序列矩阵由256×256增大至512×512，层厚由4 mm减小至3 mm，视野（FOV）保持180 mm不变，NEX保持2。扫描完成后发现图像噪声明显增大、信噪比下降，技师拟评估并调整参数组合，以兼顾空间分辨率与SNR，同时不使扫描时间过度延长。", "o": {"A": "噪声增大系体素缩小所致，应适当增加NEX或配合并行采集补偿SNR，兼顾分辨率与时间", "B": "噪声增大说明球管故障，应停机检修", "C": "噪声增大系FOV过大所致，应进一步增大FOV", "D": "该参数调整会使空间分辨率下降", "E": "增大层厚至5 mm可同时提高空间分辨率与SNR"}, "d": "中", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-113", "kp": "MR矩阵层厚调整的综合分析", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】FOV不变、矩阵加倍且层厚减薄使体素体积明显缩小，SNR下降、噪声增大，属正常物理规律。若要兼顾高分辨率与SNR，应增加NEX（付出时间）或配合并行采集（部分缩短时间），故A正确。\n【为什么错】B：噪声增大源于体素变小而非球管故障。C：增大FOV使像素增大、SNR升高，但同时降低空间分辨率并改变显示范围，不能用于补偿该调整。D：矩阵增大、层厚减薄使空间分辨率提高而非下降。E：层厚增大可提高SNR但增加部分容积效应、沿层厚方向分辨率下降，不能同时提高空间分辨率。", "tr": "矩阵↑+层厚↓=分辨率↑、SNR↓；补偿靠“NEX＋并行采集”，靠加大层厚/增大FOV会丢分辨率。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U05-1046", "t": "案例分析题", "s": "某基层医院影像科新购置一台DR设备，拟建立影像质量保证（QA）体系。科室负责人要求质控技师制定质量控制（QC）制度与操作规程，规范设备的验收检测、日常维护、图像质量评估与受检者剂量监测，并建立记录档案、定期回顾分析，以持续改进影像质量。此前该科室曾因未开展定期检测，探测器灵敏度漂移导致图像质量下降。请从QA与QC关系角度分析该科室应优先落实的工作。", "o": {"A": "制定QC计划与操作规程，定期开展设备检测、图像评估与剂量监测，规范记录存档并持续改进", "B": "仅设备验收时检测一次，之后无需再测", "C": "检测记录可事后补写、随意修改", "D": "图像质量以技师主观印象评估即可，无需客观指标", "E": "出现图像质量问题仅更换设备，不追溯分析原因"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-107", "kp": "科室QC制度建设", "ch": "五、影像质量管理 → 1.概述 → (2)管理方法", "ex": "【为什么对】科学的质量管理要求制定计划与操作规程，定期进行设备检测、图像评估和剂量监测，规范记录存档并定期回顾分析，形成“计划—执行—检查—处理”的持续改进循环，A符合QA/QC管理要求。\n【为什么错】B：设备性能随时间漂移，验收后仍需定期检测。C：检测记录必须真实完整、不可随意修改，否则失去质控意义。D：主观评估应结合客观指标（CT值、噪声、分辨率等），不能仅凭印象。E：出现质量问题应追溯分析原因并改进，更换设备只是被动应对，不能持续改进。", "tr": "质量管理核心=制度+定期检测+真实记录+持续改进；验收一次、事后补记、只换不查均为错误做法。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0101", "t": "单选题", "s": "关于模拟图像与数字图像的基本特征，下列描述正确的是", "o": {"A": "模拟图像的密度在空间上呈连续变化，数字图像由离散排列的像素与有限个灰度级构成", "B": "数字图像不能进行数值运算，只能供肉眼直接观察", "C": "模拟图像便于计算机直接存储、网络传输与后处理", "D": "数字图像的密度分辨率低于屏-片系统", "E": "增感屏-胶片系统属于典型的数字成像系统"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-001", "kp": "模拟图像与数字图像的区别", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】A 正确。模拟图像（如屏-片照片）用银颗粒沉积形成的连续光学密度记录信息，其空间位置与灰度均为连续量；数字图像则先经空间采样得到离散像素，再经幅度量化得到有限灰度级，用矩阵形式的数值阵列表达，位置与灰度都是离散量。【为什么错】B 数字图像最重要的优势恰恰是可以进行加减乘除、卷积滤波、傅里叶变换等各类数值运算，窗技术、减影、三维重建都建立在此基础上。C 模拟图像必须先经胶片数字化仪扫描转换为数字图像才能进入 PACS，其本身不便于计算机处理。D 数字探测器动态范围宽，配合窗技术可分段放大不同密度区间，其密度（对比度）分辨率高于屏-片系统。E 屏-片系统以连续光学密度记录影像，属典型模拟成像。", "tr": "\"数字图像空间分辨率通常低于屏-片、密度分辨率高于屏-片\"是两者比较的核心结论，D 项把密度分辨率与空间分辨率的结论对调，是最常见的设陷方式。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0102", "t": "单选题", "s": "某 DR 系统探测器采集视野为 43 cm×43 cm，输出图像矩阵为 3000×3000，据此计算其像素尺寸与由采样决定的理论极限空间分辨率约为", "o": {"A": "像素约 0.14 mm，极限空间分辨率约 3.5 lp/mm", "B": "像素约 0.14 mm，极限空间分辨率约 7.0 lp/mm", "C": "像素约 1.4 mm，极限空间分辨率约 0.35 lp/mm", "D": "像素约 0.29 mm，极限空间分辨率约 3.5 lp/mm", "E": "像素约 0.14 mm，极限空间分辨率约 1.75 lp/mm"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-002", "kp": "矩阵、像素尺寸与极限空间分辨率的换算", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (2)矩阵与像素", "ex": "【为什么对】A 正确。像素尺寸 d=视野/矩阵=430 mm÷3000≈0.143 mm。由采样决定的极限空间频率为奈奎斯特频率 f=1/(2d)=1/(2×0.143 mm)≈3.5 lp/mm。【为什么错】B 遗漏了系数 2，把 1/d 直接当作极限频率，这是最常见的计算错误。C 单位换算失误，把 43 cm 误当作 43 mm 或矩阵取错。D 像素尺寸计算错误（相当于用 43 cm÷1500）。E 极限频率计算错误（相当于 1/(4d)）。", "tr": "记住两个换算：像素尺寸=FOV/矩阵；奈奎斯特极限=1/(2×像素尺寸)。此外，探测器的实际极限分辨率还受探测器孔径、荧光体侧向扩散与焦点模糊限制，通常略低于理论奈奎斯特值。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0103", "t": "多选题", "s": "下列关于数字图像常用术语的表述，正确的有", "o": {"A": "像素是构成二维数字图像的最小单元，体素是与之对应的三维组织体积单元", "B": "矩阵是像素按行列排列构成的阵列，视野一定时矩阵越大则像素越小、空间分辨率越高", "C": "灰阶级数由量化位深决定，12 bit 量化可表达 4096 个灰度级", "D": "动态范围指系统可线性响应的最大信号与最小可探测信号之比，数字探测器的动态范围远大于屏-片系统", "E": "原始数据与显示数据完全等同，故图像重建完成后仍可任意更换卷积核并缩小重建视野以提高分辨率"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-003", "kp": "像素、体素、矩阵、灰阶与动态范围", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】A 正确：像素只有面积概念，体素在像素基础上加上层厚这一维。B 正确：像素尺寸=FOV/矩阵，矩阵增大使像素变小、空间分辨率提高，但单个像素接收的光子数减少、噪声增大。C 正确：n 位量化可表达 2ⁿ 个灰度级，12 bit 即 2¹²=4096 级，CT 常用 12 bit 表达 -1024～3071 HU。D 正确：屏-片的宽容度受特性曲线直线段限制（约 1:40），而平板探测器动态范围可达 10⁴ 量级以上，这是数字摄影宽容度大的物理基础。【为什么错】E 错误：原始数据（扫描/投影数据）保留全部采集信息，可反复用不同重建视野、卷积核、层厚重建；重建后的显示数据已丢失部分原始信息，只能做窗技术、放大、测量等有限处理，无法事后更换卷积核或通过缩小视野提高真实分辨率。", "tr": "\"原始数据可重建、显示数据只能后处理\"是 CT 工作中的重要实践原则。急诊病例若原始数据已被自动清理，发现需要薄层重建时将无法补救，这也是原始数据保留时限管理的意义所在。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-0104", "t": "多选题", "s": "与传统增感屏-胶片系统相比，数字 X 线成像所具有的特点包括", "o": {"A": "曝光宽容度大，对曝光条件的依赖性明显降低，废片率下降", "B": "密度（对比度）分辨率高，借助窗技术可分别观察不同密度层次的组织", "C": "图像可数字化存储、网络传输与后处理，便于纳入 PACS 与远程会诊", "D": "目前通用型 DR 平板探测器的极限空间分辨率通常仍低于优质屏-片系统", "E": "由于宽容度大，无论曝光量高低，图像的噪声水平都基本不变"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-004", "kp": "数字成像与屏-片成像的性能比较", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】A 正确：数字探测器响应近似线性且动态范围宽，曝光量在较大范围内变化仍可通过后处理获得合适显示密度。B 正确：宽动态范围加上窗技术，使一次采集即可分别显示软组织、骨与含气结构。C 正确：这是数字化最重要的信息学价值。D 正确：通用型 DR 平板探测器的像素间距通常在 140～200 μm，极限分辨率约 2.5～3.6 lp/mm，仍低于优质屏-片系统（可达 5 lp/mm 以上）；专用乳腺探测器像素更小，分辨率明显更高。【为什么错】E 错误：宽容度大只是使显示密度趋于\"正常\"，掩盖了曝光量的差异，但图像噪声仍严格取决于探测器接收的光子数。曝光不足时图像看似正常而量子噪声显著增加；反之技师为求\"图像好看\"习惯性加大条件，就形成了数字摄影特有的\"剂量漂移\"隐患，这正是必须监控曝光指数的原因。", "tr": "宽容度大是优点也是风险：屏-片时代曝光过量会直接表现为照片过黑而被发现，数字系统却\"看不出来\"，只能靠曝光指数与偏差指数发现，务必把 E 这类说法与噪声机制区分开。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-0105", "t": "单选题", "s": "模拟信号数字化的采集环节必须遵循采样定理（奈奎斯特定理），下列描述正确的是", "o": {"A": "采样频率应不低于被采样信号最高空间频率的 2 倍，否则超出奈奎斯特频率的成分会折叠为低频成分，形成混叠伪影", "B": "采样频率越低，图像所保留的信息越完整", "C": "采样定理只适用于随时间变化的信号，不适用于图像的空间采样", "D": "提高量化位深即可弥补采样频率不足所造成的信息丢失", "E": "混叠只改变图像的灰度水平，不影响空间结构的真实性"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-001", "kp": "采样定理与混叠", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】A 正确。采样定理指出，欲无失真地恢复原信号，采样频率须至少为信号最高频率的 2 倍；对图像而言，采样间距 d 决定的奈奎斯特频率为 1/(2d)，高于该频率的空间成分会被错误地折叠（混叠）到低频区，形成虚假的低频条纹或图案。DR 图像中滤线栅栅线与像素采样频率相近时产生的摩尔纹，就是典型的空间混叠。【为什么错】B 完全相反，采样频率越低丢失的高频信息越多。C 采样定理是信号处理的普适规律，同样适用于空间维度的图像采样。D 位深解决的是幅度量化精度，与空间采样密度无关，不能弥补采样不足。E 混叠产生的是虚假的空间结构（条纹、图案），会造成结构性误判，远不止灰度改变。", "tr": "把\"混叠\"（采样不足，空间频率折叠）与\"伪轮廓\"（量化位深不足，灰阶阶梯）混为一谈是常见错误：前者是采样问题、表现为虚假条纹；后者是量化问题、表现为平缓区的阶梯状分界。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0106", "t": "单选题", "s": "在数字图像形成过程中，\"量化\"这一环节所完成的工作是", "o": {"A": "把连续分布的空间位置离散化为若干个采样点", "B": "把每个采样点上连续变化的信号幅度用有限个离散数值（灰度级）表示，其级数由量化位深决定", "C": "把数字信号还原为模拟电压后输出到显示器", "D": "把图像数据按 DICOM 格式封装以便网络传输", "E": "把图像的空间频率成分分解到不同频带中分别处理"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-002", "kp": "量化的定义与位深", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (2)量化", "ex": "【为什么对】B 正确。模数转换包括采样、量化与编码三步：采样解决\"在哪里取值\"，量化解决\"取到的值用多少级表示\"，编码解决\"用什么二进制形式表达\"。量化位深 n 决定灰度级数 2ⁿ，位深越高对细微密度差的表达越精细。【为什么错】A 这是采样（空间离散化）的定义。C 这是数模（D/A）转换，属于图像输出显示环节。D 这是数据封装与通讯，属 PACS/DICOM 范畴，不是图像形成的量化步骤。E 这是频率域变换（傅里叶变换、小波分解）等图像处理操作。", "tr": "口诀：\"采样管位置、量化管幅度、编码管表达\"。量化位深不足的典型影像表现是灰度平缓过渡区出现阶梯状伪轮廓（假等高线），而非颗粒噪声。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0107", "t": "多选题", "s": "就数字 X 线图像形成过程中的采集、量化与能量转换环节而言，下列分析正确的有", "o": {"A": "采集环节决定空间采样密度，探测器采样孔径与采样间距共同影响系统的预采样调制传递函数", "B": "量化位深不足会在灰度平缓过渡区产生阶梯状伪轮廓，但不改变图像的空间分辨率", "C": "间接转换型平板探测器先由碘化铯或硫氧化钆闪烁体把 X 线转换为可见光，再经光电二极管阵列转换为电信号；直接转换型由非晶硒把 X 线直接转换为电荷", "D": "碘化铯为柱状晶体结构，可限制可见光的侧向扩散，其调制传递函数优于颗粒状硫氧化钆", "E": "模数转换位深越高，图像的空间分辨率也随之越高"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-003", "kp": "探测器转换方式与图像形成环节分析", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (3)转换", "ex": "【为什么对】A 正确：采样孔径决定单个探测单元的\"积分平滑\"作用，采样间距决定奈奎斯特频率，二者共同构成预采样 MTF。B 正确：位深属幅度量化范畴，影响密度分辨率与灰度过渡的平滑性，不影响空间采样密度。C 正确：这是间接转换与直接转换平板探测器的标准定义，前者多一次光转换，后者利用非晶硒的光电导性质在偏置电场下直接收集电荷。D 正确：柱状生长的碘化铯像光纤一样把可见光约束在柱内向下传导，明显减少侧向扩散，故在同样厚度下可兼顾吸收效率与空间分辨率；颗粒状硫氧化钆的光散射较大，增厚提高吸收的同时会明显损失分辨率。【为什么错】E 错误：位深决定灰度量化精度（密度分辨率），空间分辨率由采样间距与探测器孔径、焦点尺寸等几何因素决定，二者相互独立。", "tr": "非晶硒（直接转换）没有可见光扩散过程，理论 MTF 最高，但对温度与湿度敏感、需高偏置电压且 X 线吸收效率相对偏低；碘化铯（间接转换）吸收效率与 DQE 表现更好，各有取舍，不宜简单断言孰优孰劣。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U06-0108", "t": "单选题", "s": "某腹部 CT 图像以窗宽 350 HU、窗位 50 HU 显示，显示器按 256 级灰阶输出，下列计算结果正确的是", "o": {"A": "显示的 CT 值范围为 -125 HU～225 HU，每个灰阶约代表 1.37 HU", "B": "显示的 CT 值范围为 -300 HU～400 HU，每个灰阶约代表 2.73 HU", "C": "显示的 CT 值范围为 50 HU～400 HU，每个灰阶约代表 1.37 HU", "D": "显示的 CT 值范围为 -125 HU～225 HU，每个灰阶约代表 0.73 HU", "E": "显示的 CT 值范围为 -175 HU～175 HU，每个灰阶约代表 1.37 HU"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-001", "kp": "窗宽窗位与显示范围的计算", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】A 正确。显示上限=窗位+窗宽/2=50+175=225 HU，显示下限=窗位-窗宽/2=50-175=-125 HU；每个灰阶代表的 CT 值跨度=窗宽/灰阶数=350÷256≈1.37 HU。高于 225 HU 的组织一律显示为白，低于 -125 HU 的一律显示为黑。【为什么错】B 把窗宽误当作以窗位为中心上下各 350 HU。C 误把窗位当作显示范围的下限。D 除法错误，350÷256 不等于 0.73。E 忽略了窗位的偏移，相当于按窗位为 0 计算。", "tr": "牢记两条规律：窗宽决定对比度（窗宽越窄对比度越高、可分辨的密度层次越少），窗位决定图像整体明暗（窗位升高图像整体变黑）。计算题必须先算上下限再算灰阶步长，切勿把窗位当作下限。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0109", "t": "案例分析题", "s": "一名 26 岁男性因车祸致胸部撞击伤，急诊行胸部 CT 平扫。临床同时提出三方面评估要求：①肺挫伤范围与有无气胸；②纵隔血肿与大血管情况；③肋骨与胸椎有无骨折。技师需在同一组容积原始数据上完成后处理、观察与照片输出，既要保证诊断信息完整，又要避免不必要的重复扫描。下列窗技术设置与处理方案中最合理的是", "o": {"A": "全部内容统一用软组织窗（约 WW 350/WL 50）观察即可，其他窗设置交由诊断医师在工作站自行调节", "B": "分别采用肺窗（约 WW 1500/WL -600）、纵隔窗（约 WW 350/WL 40）与骨窗（约 WW 1500～2000/WL 400～500）三套设置观察并输出；骨窗宜配合薄层与骨算法重组以提高细节显示", "C": "把窗宽调到最大（如 4000 HU）用一套设置显示全部组织，即可免去分窗观察", "D": "统一采用窄窗（约 WW 50/WL 40）观察，窗宽越窄图像层次越丰富、信息越多", "E": "肺内病变宜用骨算法重建配合纵隔窗观察，以兼顾空间分辨率与密度分辨率"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-002", "kp": "窗技术在胸部创伤 CT 中的应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】B 正确。胸部涵盖含气肺组织（约 -900～-700 HU）、软组织（约 30～60 HU）与骨皮质（>700 HU），密度跨度极大，单一窗设置无法兼顾。肺窗宽而低位，用于观察肺纹理、挫伤与气胸；纵隔窗窄而居软组织区，用于血肿与大血管；骨窗宽而高位，配合薄层与骨（锐利）算法重组显示骨皮质中断。同一次采集的原始数据可反复重建，无需重复曝光。【为什么错】A 单一软组织窗下肺野呈一片黑、骨皮质呈一片白，肺挫伤、气胸与细微骨折均可能被漏诊，技师有责任提供符合诊断要求的图像。C 窗宽过大使对比度极低，各组织密度差被压缩到很少几个灰阶内，细微病变反而无法辨认。D 窗宽过窄使超出显示范围的组织全白或全黑，信息大量丢失，同时噪声被放大，与\"层次丰富\"恰恰相反。E 组合错误：肺内病变应用肺（高分辨）算法重建配合肺窗观察；纵隔窗下肺野几乎全黑，骨算法又会明显放大噪声，二者搭配观察肺组织不合理。", "tr": "重建算法（卷积核）必须在图像重建阶段选定，只能基于原始数据重建；而窗宽窗位属显示参数，可在任何时候对已重建图像调整。把\"换算法\"与\"换窗\"混为一谈是常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0110", "t": "多选题", "s": "关于数字 X 线摄影中的组织均衡（tissue equalization）技术，下列描述正确的有", "o": {"A": "其本质是动态范围压缩，把高密度区与低密度区的信号压缩到同一显示范围内同时呈现", "B": "典型应用如胸部摄影中同时清晰显示肺野、纵隔与膈下区域，以及颈胸交界、股骨颈等厚度差异悬殊部位", "C": "常用实现方式是把原始图像分解为反映大范围密度分布的低频成分与反映细节的高频成分，压缩低频动态范围后与高频成分重新合成", "D": "处理后局部对比度得以保留甚至增强，但整体密度阶差被压缩，过度处理可能出现边缘晕环等处理伪影", "E": "组织均衡是通过增加曝光剂量来实现图像密度均一化的技术"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-003", "kp": "组织均衡技术的原理与应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (2)组织均衡技术", "ex": "【为什么对】A 正确：组织均衡针对的是被检部位厚度、密度差异过大导致\"顾此失彼\"的问题，通过压缩动态范围实现兼顾。B 正确：这些正是临床上厚薄悬殊、常需两次不同条件曝光的部位。C 正确：多尺度频率分解（如拉普拉斯金字塔、多分辨率分析）后单独压缩低频背景、保留或增强高频细节，再合成输出，是主流算法思路。D 正确：处理强度过大时在高对比界面（如纵隔缘、金属植入物边缘）可出现暗环或亮环状的晕环伪影，须适度设置参数。【为什么错】E 错误：组织均衡是纯粹的图像后处理算法，不改变采集时的曝光条件与剂量；它的价值恰恰在于让一次曝光满足多部位观察需求，从而避免重复摄影、降低总剂量。", "tr": "组织均衡是\"后处理\"而非\"采集技术\"，与双能减影（需两次不同能量采集）、体层融合（需多角度采集）有本质区别，命题常把三者的技术属性互换设陷。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-0111", "t": "单选题", "s": "就最大密度投影（MIP）与最小密度投影（MinIP）的原理及适用范围而言，下列描述正确的是", "o": {"A": "MIP 沿投影线取路径上的最大 CT 值，适于显示强化血管、支架与钙化；MinIP 取最小值，适于显示气管支气管树、含气肠管与扩张胆道等低密度结构", "B": "MIP 与 MinIP 都保留了结构的前后深度关系，可据此判断血管的空间前后位置", "C": "MinIP 主要用于显示强化后的动脉血管", "D": "MIP 成像时骨骼与钙化不会对血管显示造成干扰", "E": "MIP 属于表面遮盖显示技术，通过设定阈值仅重建物体的表面轮廓"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-004", "kp": "MIP 与 MinIP 的原理与适用范围", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】A 正确。MIP 沿每条视线取该路径上密度最高的体素值投影成像，对高密度结构敏感，是 CTA、支架与钙化显示的常用方法；MinIP 取路径上最低值，突出低密度含气或含液结构，常用于气道树、肺气肿评估与胆道显示。【为什么错】B 两者都是沿投影线取极值，路径上其他体素信息被丢弃，深度关系随之丢失，重叠血管的前后位置无法判断，需结合原始横断面或 VR 图像。C 方向颠倒，强化血管属高密度结构，应用 MIP。D 骨与钙化的 CT 值高于强化血管，是 MIP 显示血管的主要干扰源，需先行去骨、采用薄层 MIP 或结合 VR 与横断面判读。E 描述的是 SSD（表面遮盖显示）的原理；MIP 是容积投影技术，不设表面阈值。", "tr": "MIP 的两大固有缺陷要牢记：一是丢失深度信息（前后重叠无法判断），二是高密度结构（骨、钙化、金属）遮盖血管。因此 MIP 只能作为辅助显示手段，狭窄程度评估必须回到横断面与 MPR。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0112", "t": "多选题", "s": "下列关于常用三维图像后处理技术原理与适用范围的表述，正确的有", "o": {"A": "MPR 是在容积数据中沿任意平面重组二维图像，质量受原始层厚与体素各向同性程度限制；CPR 为曲面重组，可把迂曲血管或牙列展开于一个平面，但会造成解剖形态失真，不宜直接据此测量真实长度", "B": "SSD 依据设定的 CT 值阈值提取物体表面轮廓，立体感强但丢弃内部信息，阈值选择对结果影响显著", "C": "VR 使容积内全部体素按不透明度与颜色映射参与成像，可同时显示不同组织并保留空间关系，是目前最常用的三维显示方式", "D": "仿真内镜采用透视投影并把视点置于管腔内部，可观察腔内形态，但不能反映黏膜色泽变化，也不能取材活检", "E": "MPR 可以突破原始采集的空间分辨率限制，通过薄层重组获得比原始体素更高的真实分辨率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-005", "kp": "MPR/CPR/SSD/VR/仿真内镜的原理对比", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】A 正确：MPR 属二维重组，各向同性薄层采集是获得高质量冠、矢状及斜位重组的前提；CPR 沿人工或自动勾画的中心线展开，长度与形态在展开过程中被拉伸变形，测量应在原始三维数据上进行。B 正确：SSD 只保留阈值以上体素的表面，内部密度信息全部丢失，阈值稍有改变即可显著改变管腔口径的表观，现多被 VR 取代。C 正确：VR 通过不透明度曲线与伪彩映射让所有体素按权重贡献于最终图像，兼具立体感与组织区分能力。D 正确：仿真内镜是 VR/SSD 与透视投影结合的腔内漫游显示，优点是无创、可到达常规内镜难以通过的狭窄段，缺点是无法观察颜色与黏膜细节、不能活检与治疗。【为什么错】E 错误：MPR 只是对既有体素数据重新排列与插值，其分辨率上限由采集时的体素尺寸（尤其层厚与重建间隔）决定，插值不能创造新信息；要获得高质量重组，必须在采集阶段使用薄层与各向同性体素。", "tr": "\"薄层重组\"与\"薄层采集\"是两回事：在 5 mm 层厚图像上重组出 1 mm 层厚，只会得到模糊的插值结果。凡涉及重组的检查，应在扫描时即选择薄层重建并保留原始数据。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U06-0113", "t": "案例分析题", "s": "一名 55 岁男性因发作性胸痛行冠状动脉 CTA，采用回顾性心电门控、各向同性薄层采集，图像质量良好。临床同时提出三项需求：①判断左前降支近段一处点状钙化斑块处的管腔狭窄程度；②整体展示冠状动脉走行及其与既往桥血管的解剖关系，供术前多学科讨论使用；③沿右冠状动脉长轴全程评估管壁与斑块分布。技师需为每一项需求匹配最合适的后处理方法。下列组合最恰当的是", "o": {"A": "①以原始横断面与垂直于血管长轴的短轴 MPR 为主、辅以薄层 MIP，必要时借助能量成像高 keV 单能量图像减轻钙化晕状效应；②VR；③CPR", "B": "①VR；②SSD；③MinIP", "C": "①仿真内镜；②MIP；③SSD", "D": "①MinIP；②CPR；③VR", "E": "三项需求全部使用最大密度投影即可满足"}, "d": "难", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-006", "kp": "冠状动脉 CTA 后处理方法的选择", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】A 正确。①评估钙化处管腔必须保留真实 CT 值并观察垂直于血管长轴的断面，故以横断面与短轴 MPR 为核心，薄层 MIP 可辅助连续性判断；钙化的晕状效应（blooming）会高估狭窄，采用能量成像的高 keV 虚拟单能量图像可减轻。②整体解剖关系与桥血管空间走行的展示是 VR 的长项，立体直观、适合多学科沟通。③沿血管长轴全程展开评估管壁正是 CPR 的经典适应证。【为什么错】B ①用 VR 判断狭窄程度会因不透明度曲线与阈值设定不同而显著改变管腔表观，易造成误判；SSD 已基本被 VR 取代；MinIP 适用于低密度结构，与强化血管不匹配。C 仿真内镜只显示腔内表面形态，钙化斑块处的真实管腔径线无法可靠判断；用 SSD 评估管壁同样丢失密度信息。D MinIP 不适于强化血管；把 CPR 用于整体空间关系展示则失去了立体信息。E MIP 丢失深度关系且对钙化极为敏感，既无法满足解剖关系展示，也不适合长轴管壁评估。", "tr": "\"三维图像越漂亮越可靠\"是最危险的误区。VR 与 MIP 的表观受阈值、不透明度、窗设置强烈影响，任何定量判断（狭窄率、径线测量）都应回到原始横断面与 MPR 上完成。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0114", "t": "单选题", "s": "调制传递函数（MTF）是评价成像系统信号传递能力的重要指标，下列描述正确的是", "o": {"A": "MTF 描述系统把不同空间频率的输入对比度传递到输出的能力，空间频率为 0 时 MTF=1，随频率升高而下降", "B": "MTF 数值越低，说明系统的空间分辨率越高", "C": "多个成像环节串联时，系统总 MTF 等于各环节 MTF 之和", "D": "MTF 只反映系统的噪声特性，与空间分辨率无关", "E": "通常取 MTF 降至 0.5 时对应的空间频率作为系统的极限空间分辨率"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-001", "kp": "调制传递函数 MTF 的含义", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】A 正确。MTF 定义为输出调制度与输入调制度之比，是空间频率的函数。低频（大结构）几乎无损传递，故 MTF(0)=1；随空间频率升高，系统的模糊作用使对比度传递能力下降，MTF 逐渐趋近于 0。【为什么错】B 恰恰相反，同一空间频率下 MTF 值越高，说明该频率成分被传递得越充分，分辨率表现越好。C 串联系统的总 MTF 等于各环节 MTF 的乘积，因此任一薄弱环节（如焦点过大、探测器模糊、显示器不足）都会显著拉低整体表现，这也是\"短板效应\"在成像链中的体现。D MTF 描述的是信号（分辨率）传递特性；噪声特性由噪声功率谱（维纳频谱，NPS）描述，二者结合并考虑入射量子数才构成 DQE。E 习惯上取 MTF 降至 0.1（10%）时对应的空间频率作为极限分辨率，MTF=0.5 对应的频率常用于比较系统的中频表现，不是极限分辨率的定义。", "tr": "\"MTF 相乘、DQE 综合、NPS 管噪声\"是三个评价量的记忆框架。C 项把\"乘积\"换成\"求和\"、E 项把 10% 换成 50% 都是高频陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0115", "t": "多选题", "s": "作为评价数字探测器综合性能的核心指标，量子探测效率（DQE）具有下列哪些特性", "o": {"A": "DQE 表示输出信噪比平方与输入信噪比平方之比，反映系统对入射 X 线光子所携带信息的利用效率", "B": "DQE(f)=MTF²(f)/[NNPS(f)×q]，同时包含信号传递与噪声两方面的信息", "C": "相同入射剂量下 DQE 越高图像质量越好；在相同图像质量要求下，DQE 越高则所需剂量越低", "D": "DQE 是空间频率的函数，通常随空间频率升高而下降，并随入射剂量水平的不同而变化", "E": "性能优异的探测器 DQE 可以大于 1，说明其对信号具有净放大作用"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-002", "kp": "量子探测效率 DQE", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (2)DQE", "ex": "【为什么对】A 正确：DQE=SNR²_out/SNR²_in，本质是\"信息利用率\"。B 正确：分子的 MTF² 代表信号传递能力，分母的归一化噪声功率谱与入射光子数 q 代表噪声与量子涨落，公式把分辨率、噪声与剂量三要素统一起来。C 正确：这正是 DQE 成为探测器选型核心指标的原因——高 DQE 意味着\"同剂量更好图像\"或\"同图像更低剂量\"，直接对应患者剂量优化。D 正确：DQE 在低频最高、随频率升高而衰减；且因电子学噪声、结构噪声在不同剂量水平下所占比例不同，DQE 曲线会随剂量变化，故报告 DQE 必须注明测试剂量与射线质（如 RQA5）。【为什么错】E 错误：DQE 是效率量，理想无损探测器为 1（100%），实际系统因量子吸收不完全、二次量子损失、电子噪声与散射恒小于 1。电子学放大会同时放大信号与噪声，不改变信噪比，因而不可能使 DQE 超过 1。", "tr": "DQE 与\"量子检出率/吸收效率\"不是一回事：探测器即使吸收了全部入射光子（吸收效率 100%），若后续转换与读出过程引入噪声或模糊，DQE 仍会明显低于 1。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-0116", "t": "单选题", "s": "某研究比较两种重建算法对肺内小结节的检出效能，绘制 ROC 曲线后得算法甲 AUC=0.92、算法乙 AUC=0.78。对该结果的解释，下列正确的是", "o": {"A": "AUC 相当于随机抽取一对阳性与阴性病例时模型给阳性病例更高判断分值的概率；甲的总体诊断效能优于乙，且 AUC 的比较不受某一具体判断阈值的影响", "B": "AUC=0.5 表示诊断效能已达中等水平", "C": "ROC 分析只能用于评价计算机算法，不能用于比较不同观察者的阅片水平", "D": "甲的 AUC 更高，说明在任何工作点上甲的灵敏度与特异度都高于乙", "E": "ROC 分析要求预先固定判断阈值，因此结论高度依赖阈值的设定"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-003", "kp": "ROC 曲线与曲线下面积 AUC", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (3)ROC曲线", "ex": "【为什么对】A 正确。AUC 的概率学含义即\"随机取一阳性与一阴性样本，阳性样本获得更高判断评分的概率\"；由于 AUC 是遍历所有阈值形成的曲线下面积，其比较不受某一固定阈值（判读尺度松紧）的影响，这正是 ROC 优于单点灵敏度/特异度比较的关键。【为什么错】B AUC=0.5 对应对角线，相当于随机猜测、无诊断价值；一般认为 0.7～0.8 为一般、0.8～0.9 为较好、大于 0.9 为优秀。C ROC 最初正是为评价观察者（放射科医师）诊断决策而引入影像学的，可用于比较不同观察者、不同设备与不同算法。D AUC 反映整体效能，两条 ROC 曲线可能相交，在高特异度或高灵敏度的特定工作点上乙仍可能优于甲，需结合部分曲线下面积或临床所需工作点分析。E 与事实相反，ROC 的核心做法是连续改变判断阈值获得整条曲线，从而摆脱单一阈值的束缚。", "tr": "对于结节检出这类\"一幅图上可有多个病灶\"的任务，更严谨的评价工具是 FROC/AFROC 曲线（横轴为每幅图像的假阳性数）；把 ROC 与 FROC 混用是科研设计中的常见错误。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0117", "t": "单选题", "s": "有关计算机辅助诊断（CAD）系统的分类与临床定位，下列描述正确的是", "o": {"A": "CAD 分为计算机辅助检出（CADe）与计算机辅助定性诊断（CADx）两类，其临床定位是作为医师的\"第二阅片者\"提供参考，最终诊断责任仍由医师承担", "B": "CAD 的目标是取代放射科医师独立完成诊断并出具报告", "C": "CAD 系统的典型性能特点是特异度极高而灵敏度偏低", "D": "CAD 只处理图像中的密度信息，不涉及形态、边缘与纹理特征", "E": "CAD 所标记的每一个位置都对应真实存在的病灶"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-001", "kp": "CAD 的分类与临床定位", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (1)概述", "ex": "【为什么对】A 正确。CADe 负责把可疑病灶标记出来（如肺结节、微钙化簇），CADx 进一步对已发现病灶做良恶性倾向等定性分析。无论哪一类，其法律与临床定位都是辅助工具、第二阅片者，用于提示医师复核可能忽略的区域，诊断决定权与责任归于医师。【为什么错】B CAD 不具备独立出具诊断报告的资质，也不能替代医师对临床信息的综合判断。C 恰恰相反，CAD 通常以高灵敏度为设计目标（尽量不漏），代价是假阳性标记较多、特异度相对偏低。D CAD 的特征提取涵盖密度、形态学（大小、圆形度、边缘毛刺）、纹理、空间分布等多维特征，深度学习模型还能自动学习高阶特征。E CAD 标记中包含相当比例的假阳性，医师须逐一甄别，不能不加判断地全部采信。", "tr": "\"高灵敏度、低特异度\"是传统 CAD 的固有属性，也是它必须由医师复核的根本原因。命题常把灵敏度与特异度的高低对调设置干扰。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-0118", "t": "案例分析题", "s": "某三甲综合医院影像科日均乳腺 X 线摄影约 120 例、胸部 DR 约 300 例，拟在 2 台乳腺机与 3 台 DR 上统一部署计算机辅助诊断（CAD）系统：乳腺方面希望提高成簇微钙化与肿块的检出率，胸部方面希望减少肺结节漏诊并控制假阳性负荷。科室在组织技师与诊断医师的联合上线培训时，需要系统说明该类软件的性能边界、标准工作流与合理使用方式，以避免医师过度依赖或错误解读标记。下列培训要点中正确的是", "o": {"A": "乳腺 CAD 对成簇微钙化的检出灵敏度通常高于对肿块的检出灵敏度，因为致密型腺体背景易掩盖肿块；使用上应由医师先完成独立阅片、再调阅 CAD 标记作为第二阅片参考，并配套开展假阳性标记的甄别培训", "B": "上线 CAD 后医师只需阅读被标记的区域，未被标记的区域可不再逐一观察", "C": "CAD 在致密型乳腺中的检出表现优于脂肪型乳腺", "D": "胸部 CAD 的假阳性主要来自真实结节，因此标记数量越少说明系统性能越好", "E": "CAD 的基本流程是直接对原始图像输出结论，无须图像预处理、候选检出与特征提取等中间环节"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-002", "kp": "乳腺与胸部 CAD 的性能特点及使用方式", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (3)乳腺应用", "ex": "【为什么对】A 正确。微钙化在图像上具有高对比、高空间频率的特征，算法易于提取，检出灵敏度普遍较高；肿块表现为软组织密度影，在致密型腺体背景中对比度低、边缘不清，检出难度明显更大。标准使用流程是医师先独立完整阅片形成初步意见，再打开 CAD 标记进行第二次核查，从而既获得提示价值又避免被误导。【为什么错】B 这会导致\"搜索满足效应\"，医师注意力被标记区吸引而忽略其余区域，反而可能增加漏诊，是 CAD 使用中必须重点规避的行为。C 恰恰相反，致密型腺体的组织重叠使病灶对比度下降，无论人眼还是 CAD 的检出能力都下降，这也是致密型乳腺推荐结合超声或断层摄影的原因。D 胸部 CAD 的假阳性多来自血管断面、肋骨与锁骨交叉影、乳头影、陈旧瘢痕等正常结构；标记数量与系统优劣之间不存在简单关系，评价应采用灵敏度-每图假阳性数（FROC）曲线。E CAD 的经典流程为图像预处理→分割与候选病灶检出→特征提取→分类器判别→假阳性削减→结果标记输出，中间环节不可省略。", "tr": "\"CAD 提高灵敏度的同时增加假阳性、延长阅片时间\"是其双刃剑属性。培训重点不是让医师相信 CAD，而是让医师学会在正确的工作流位置上使用它并识别其典型假阳性模式。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1001", "t": "单选题", "s": "模拟图像与数字图像在特征上的主要差异，正确的描述是", "o": {"A": "模拟图像在时间、空间及密度上都是离散的", "B": "模拟图像的空间与密度（灰度）是连续变化的", "C": "数字图像在空间上是连续的", "D": "数字图像的灰度级数为无限", "E": "模拟图像可直接存储于计算机并随意处理"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-101", "kp": "模拟图像与数字图像的特征", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】模拟图像（如X线胶片、透视荧光影像）的影像信息在空间位置、密度（灰度）上都是连续变化的量，故B正确。\n【为什么错】A：离散性是数字图像的特征，模拟图像是连续的。C：数字图像由离散像素构成，空间上是离散的。D：数字图像灰度级有限，由量化位数决定。E：计算机只能处理数字化后的信息，模拟图像须经A/D转换。", "tr": "“模拟=连续、数字=离散”是最基础考点；模拟图像不能直接入计算机。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1002", "t": "单选题", "s": "与传统屏/片系统相比，数字X线成像最重要的优点是", "o": {"A": "无需任何成像设备即可成像", "B": "动态范围宽（曝光宽容度大），可对图像进行后处理并实现存储传输", "C": "空间分辨率高于任何模拟成像系统", "D": "可完全消除受检者辐射剂量", "E": "图像一经生成不能再处理"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-102", "kp": "数字X线成像的优点", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】数字X线成像探测器动态范围宽、曝光宽容度大，可避免曝光不当导致的图像失败，且可进行窗宽窗位、滤波等后处理，并支持存储与传输（PACS），这是其相对屏/片系统的最重要优势。\n【为什么错】A：数字成像同样需要X线机、探测器等设备。C：数字系统空间分辨率受像素大小限制，并不一定高于增感屏-胶片系统。D：任何X线成像都有辐射，无法完全消除。E：数字图像恰恰可进行丰富的后处理。", "tr": "数字成像核心优势=宽容度大＋后处理＋存储传输；勿误认为分辨率更高或零剂量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1003", "t": "单选题", "s": "关于模拟信号数字化过程的理解，下列叙述正确的是", "o": {"A": "数字化只需量化，无需采样", "B": "采样是对空间位置的离散化，量化是对信号值（灰度/密度）的离散化", "C": "采样与量化是同一概念", "D": "量化后图像仍是连续函数", "E": "数字图像由连续模拟信号直接构成"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-101", "kp": "采样与量化的区别", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】数字化的两个基本环节：采样把空间上连续的模拟信号按间隔离散为像素；量化把每个像素的连续灰度值离散为有限个灰度级，二者分别对“位置”和“信号值”进行离散化。\n【为什么错】A：采样是数字化的前提，不可省略。C：采样针对空间位置、量化针对信号值，概念不同。D：量化后灰度级为有限离散值，不再是连续函数。E：数字图像由采样量化得到的离散数据构成。", "tr": "“采样管位置、量化管数值”口诀；两个环节缺一不可、不可混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1004", "t": "单选题", "s": "数字图像中“像素（pixel）”的定义是", "o": {"A": "构成数字图像的最小基本单元，具有一定的亮度值（像素值）与空间位置", "B": "图像的物理尺寸", "C": "CT扫描的层厚", "D": "探测器的灵敏度", "E": "图像文件的存储容量"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-103", "kp": "像素的定义", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (2)矩阵与像素", "ex": "【为什么对】像素是组成数字图像的最小单元，每个像素既有确定的空间位置，又有一个对应的灰度值（像素值），图像由按矩阵排列的众多像素构成。\n【为什么错】B：图像物理尺寸由FOV或探测器大小决定。C：层厚是断层成像的厚度参数。D：探测器灵敏度是设备性能参数。E：存储容量是文件大小，均与像素定义无关。", "tr": "像素=最小单元（位置＋数值）；勿与层厚、探测器性能、文件大小混同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1005", "t": "单选题", "s": "关于数字图像矩阵与像素的关系，下列叙述正确的是", "o": {"A": "矩阵越大，像素尺寸越大", "B": "矩阵是纵横排列的像素阵列，矩阵越大、像素越小，空间分辨率越高", "C": "矩阵大小与视野（FOV）无关", "D": "减小矩阵可提高空间分辨率", "E": "像素大小等于FOV乘以矩阵"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-104", "kp": "矩阵与像素的关系", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (2)矩阵与像素", "ex": "【为什么对】矩阵为像素的纵横阵列，如512×512表示横向与纵向各512个像素；在FOV不变时矩阵越大、像素越小，能分辨的细节越细，空间分辨率越高。\n【为什么错】A：FOV不变时矩阵越大像素越小而非越大。C：像素大小=FOV/矩阵，二者关系密切。D：减小矩阵使像素增大、空间分辨率下降。E：像素等于FOV除以矩阵，而非相乘。", "tr": "像素=FOV÷矩阵；矩阵↑像素↓分辨率↑；乘除关系勿记反。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1006", "t": "单选题", "s": "数字图像的灰度级数由量化位数（bit深度）决定，12位量化可表示的灰度级数为", "o": {"A": "12", "B": "128", "C": "512", "D": "1024", "E": "4096"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-105", "kp": "量化位数与灰度级", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】灰度级数=2的bit次方，12位对应2^12=4096个灰度级，灰度层次越丰富、灰阶显示越细腻。\n【为什么错】A：12是位数本身，不是灰度级数。B：2^7=128为7位。C：2^9=512为9位。D：2^10=1024为10位，均不等于12位的灰度级数。", "tr": "灰度级=2^bit：10bit=1024、12bit=4096、14bit=16384；bit与级数勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1007", "t": "单选题", "s": "关于数字图像的常用术语，下列叙述正确的是", "o": {"A": "像素值即CT值，恒定不变", "B": "灰度直方图反映图像中像素值（灰度）的分布情况", "C": "调节窗宽窗位会改变像素的原始存储值", "D": "动态范围仅指显示监视器的亮度范围", "E": "空间分辨率与像素大小无关"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-106", "kp": "数字图像常用术语", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】灰度直方图以横轴为灰度（像素值）、纵轴为频数，反映各灰度级像素的数量分布，是数字图像后处理与窗宽窗位选择的重要依据。\n【为什么错】A：像素值是探测器输出经量化的信号值，CT图像中才换算为CT值（HU），不同组织不同，并非恒定。C：窗宽窗位只改变灰阶的显示映射，不改动原始像素数据。D：动态范围指系统能响应的信号范围（探测器可感受的信号幅度范围），不仅限于监视器亮度。E：空间分辨率与像素大小直接相关，像素越小分辨率越高。", "tr": "直方图=灰度分布统计；窗宽窗位是“显示”映射，不改原始像素值。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1008", "t": "单选题", "s": "关于采样定理（奈奎斯特定理），下列叙述正确的是", "o": {"A": "采样频率应低于信号最高频率的2倍", "B": "采样频率应大于或等于信号最高频率的2倍，才能无失真地恢复原信号", "C": "采样频率越高，图像越模糊", "D": "采样定理与数字图像无关", "E": "采样间隔越大，空间分辨率越高"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-102", "kp": "采样定理与奈奎斯特频率", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】奈奎斯特定理指出，要从离散采样信号无失真地恢复连续信号，采样频率必须大于或等于信号所含最高频率的2倍，采样间隔需小于等于1/(2倍最高频率)。\n【为什么错】A：低于2倍会出现混叠（失真），不满足采样定理。C：采样频率越高信息还原越充分，图像细节越清晰。D：数字成像的采集环节直接受采样定理约束。E：采样间隔越大可采到的最高空间频率越低，分辨率下降。", "tr": "“采样频率≥2倍最高频率”；采样间隔与可分辨频率成反比，间隔过大产生混叠。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1009", "t": "单选题", "s": "当采样不足（采样频率低于奈奎斯特频率）时，数字图像将出现", "o": {"A": "灰度反转", "B": "混叠（aliasing）伪影，高频细节以错误低频形式重现", "C": "密度分辨率提高", "D": "量子噪声消失", "E": "对比度增强"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-103", "kp": "采样不足与混叠伪影", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】采样不足时高频信息“折叠”为低频信号叠加在图像上，产生混叠伪影，表现为细密条纹或低频波纹（如衬衣条纹、磨玻璃样纹理），是采样间隔过大或焦点-探测器极限所致。\n【为什么错】A：灰度反转由显示映射或系统非线性引起。C：采样不足不会提高密度分辨率，反而劣化图像。D：量子噪声由光子统计涨落决定，与采样无关。E：对比度由窗宽窗位及组织差异决定，混叠不增强对比。", "tr": "采样不足→混叠；混叠的表现是“高频变低频”，典型见于细条纹摄影。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1010", "t": "单选题", "s": "某DR系统探测器有效成像区域为43 cm×43 cm，若要求像素尺寸约为0.2 mm，所需采集矩阵约为", "o": {"A": "256×256", "B": "512×512", "C": "1024×1024", "D": "2048×2048", "E": "4096×4096"}, "d": "难", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-104", "kp": "矩阵与像素尺寸计算", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】像素尺寸=视野边长÷每边像素数，43 cm=430 mm，430÷0.2=2150，故每边像素数需约2150，最接近且不小于的是2048×2048矩阵（略低于0.2 mm的像素约0.21 mm，需结合系统采样能力选择）。\n【为什么错】A：256×256时像素尺寸约1.68 mm，远大于0.2 mm要求。B：512×512时像素约0.84 mm，仍明显偏大。C：1024×1024时像素约0.42 mm，大于0.2 mm。E：4096×4096时像素约0.105 mm，超出多数探测器固有采样极限，也非“约0.2 mm”的最优选择。", "tr": "像素=边长÷矩阵单边数；计算时统一单位（cm→mm），“最接近且不超系统极限”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1011", "t": "单选题", "s": "数字图像形成过程中，“量化”环节所完成的工作是", "o": {"A": "将图像的空间坐标离散化", "B": "将连续的信号幅度（模拟量）离散为有限个灰度级", "C": "提高X线管电流", "D": "放大图像的尺寸", "E": "改变探测器的类型"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-105", "kp": "量化的定义", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (2)量化", "ex": "【为什么对】量化是把采样得到的各像素连续信号幅度（电压/灰度模拟量）按一定级数离散化，赋予整数灰度级（如0~4095），从而形成可存储的数字数据。\n【为什么错】A：空间坐标离散化属于采样环节。C：管电流是X线发生参数，与量化无关。D：图像尺寸放大属后处理。E：探测器类型决定信号采集方式，不是量化内容。", "tr": "“采样管空间位置、量化管信号值”；量化输出为有限个灰度级。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1012", "t": "单选题", "s": "量化级数（位深）越大，对数字图像质量的影响是", "o": {"A": "灰度层次越丰富、灰阶显示越细腻，但数据存储量增大", "B": "空间分辨率提高", "C": "量子噪声减小", "D": "图像视野缩小", "E": "图像对比度必然提高"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-106", "kp": "量化位深对图像的影响", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (2)量化", "ex": "【为什么对】位深越大灰度级数越多（2^n），图像灰度层次越丰富、过渡越细腻，能更好区分微小密度差异；但每个像素需更多比特存储，数据量随之增大。\n【为什么错】B：空间分辨率由采样（像素大小）决定，与量化位深无关。C：噪声源于光子统计涨落与系统噪声，不随位深改变。D：视野由探测器大小与几何决定。E：对比度由组织差异与显示窗参数决定，位深增大不等于必然提高对比。", "tr": "位深管“灰阶细腻程度”和“存储量”，不直接改变分辨率、噪声与对比度。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1013", "t": "单选题", "s": "模拟信号经模数转换（A/D）变为数字信号，主要包括的两个步骤是", "o": {"A": "采样与量化", "B": "仅采样", "C": "仅量化", "D": "编码与压缩", "E": "调制与解调"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-107", "kp": "A/D转换的步骤", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (3)转换", "ex": "【为什么对】模数转换（A/D）由采样（离散化空间/时间）和量化（离散化幅度）两个基本步骤构成，二者缺一不可，之后才得到数字图像数据。\n【为什么错】B：仅采样而未量化不能把信号幅度离散化，无法完成A/D转换。C：仅量化而无采样则没有像素位置信息，同样不完整。D：编码与压缩发生在数字化之后，用于传输与存储。E：调制解调属于信号传输范畴，非A/D转换步骤。", "tr": "A/D转换=采样＋量化；压缩、编码是后续处理，勿混入转换环节。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1014", "t": "单选题", "s": "关于窗口技术（窗宽、窗位），下列叙述正确的是", "o": {"A": "窗宽增大，图像对比度增强", "B": "窗宽决定显示灰阶所对应的CT值范围，窗宽增大使对比度降低；窗位决定显示范围的中心值", "C": "窗位越高，显示的CT值范围越宽", "D": "窗宽窗位不影响图像显示", "E": "窗位总是窗宽的一半"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-101", "kp": "窗口技术的原理", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】窗宽是显示灰阶对应的CT值范围（动态显示范围），窗宽越大单位灰阶对应的CT值跨度越大、对比度越低；窗位（窗中心）是显示范围的中心CT值，决定观察的灰度中心。\n【为什么错】A：窗宽增大使CT值跨度增大，对比度降低而非增强。C：显示范围宽度由窗宽决定，与窗位无关。D：窗宽窗位是CT图像显示的核心参数，直接影响灰度与对比。E：窗位与窗宽无固定比例关系，二者独立调节。", "tr": "窗宽管“范围/对比度”、窗位管“中心位置”；显示范围=窗位±窗宽/2。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1015", "t": "单选题", "s": "某CT图像以窗宽400 HU、窗位100 HU显示，其显示的CT值范围（下限~上限）为", "o": {"A": "-200~200 HU", "B": "-100~300 HU", "C": "100~500 HU", "D": "0~400 HU", "E": "-300~100 HU"}, "d": "难", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-102", "kp": "窗宽窗位范围计算", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】显示范围下限=窗位-窗宽/2=100-200=-100 HU，上限=窗位+窗宽/2=100+200=300 HU，故范围为-100~300 HU。\n【为什么错】A：-200~200对应窗位0、窗宽400。C：100~500对应窗位300、窗宽400。D：0~400对应窗位200、窗宽400。E：-300~100对应窗位-100、窗宽400，均与本组窗宽窗位不符。", "tr": "范围=[窗位-窗宽/2, 窗位+窗宽/2]；先算窗宽一半再加减，勿用“窗位±窗宽”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1016", "t": "单选题", "s": "关于组织均衡（tissue equalization）技术，下列叙述正确的是", "o": {"A": "对探测器欠饱和与过饱和区域的信号进行灰度压缩与均衡，使不同密度组织在同一图像中清晰显示", "B": "仅适用于乳腺X线摄影", "C": "该技术会增加受检者辐射剂量", "D": "组织均衡后高对比组织显示能力下降", "E": "组织均衡与窗宽窗位的作用完全相同"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-103", "kp": "组织均衡技术", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (2)组织均衡技术", "ex": "【为什么对】组织均衡利用数字化后处理，对信号过强（过饱和）与过弱（欠饱和）区域的灰度进行压缩补偿，使厚薄不均部位（如胸部肺与纵隔、四肢两端）在同一图像上同时清晰显示。\n【为什么错】B：组织均衡广泛用于胸部、四肢、脊柱等多种部位，并非乳腺专有。C：组织均衡是纯软件处理，不改变曝光条件，不增加剂量。D：组织均衡恰恰是改善高对比组织在两端的显示，而非降低显示能力。E：组织均衡是重建域的后处理，与显示时调节的窗宽窗位机理不同。", "tr": "组织均衡=软件灰度压缩补偿，不增剂量、非乳腺专利、别与窗宽窗位混同。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1017", "t": "单选题", "s": "关于多平面重组（MPR），下列叙述正确的是", "o": {"A": "在螺旋CT各向同性（近似）采集数据基础上，重建任意方位的二维断面图像", "B": "只能显示组织三维表面", "C": "必须使用表面阴影重建算法", "D": "仅适用于骨骼系统", "E": "MPR不能用于冠状位重建"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-104", "kp": "多平面重组MPR", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】MPR利用螺旋CT容积扫描获得的体素数据，在横断面基础上重建出冠状位、矢状位及任意斜面的二维图像，配合薄层各向同性采集可获得任意方位的清晰断面。\n【为什么错】B：显示三维表面是SSD、VR的功能。C：MPR是体数据重切，不采用表面重建算法。D：MPR适用于全身各部位（颅脑、脊柱、血管等），非骨骼专有。E：冠状位重建是MPR的基本应用之一。", "tr": "MPR=任意方位二维重建，属体素重切技术；SSD/VR才是三维表面/容积显示。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1018", "t": "单选题", "s": "表面阴影显示（SSD）技术最适用于显示", "o": {"A": "血管腔内的对比剂分布", "B": "骨骼表面及骨折块的空间立体形态", "C": "软组织间的密度细微差别", "D": "脑白质纤维束走向", "E": "肺通气功能变化"}, "d": "易", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-105", "kp": "SSD的临床应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (4)SSD", "ex": "【为什么对】SSD通过设定阈值提取感兴趣结构的表面轮廓并加光照阴影显示，立体感强，最适合显示骨骼表面形态、骨折移位、颅面骨畸形等空间结构关系。\n【为什么错】A：血管腔内对比剂显示多用MIP或VR。C：软组织密度细微差别靠窗宽窗位或MPR观察。D：脑白质纤维束属DTI后处理。E：肺通气功能评价不属于SSD应用。", "tr": "SSD=表面立体显示，强项在骨骼/骨关节三维；血管内腔、软组织细节非其强项。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1019", "t": "单选题", "s": "最大密度投影（MIP）在临床中主要用于显示", "o": {"A": "血管与高密度结构（CTA、MRA）", "B": "软组织低对比结构", "C": "骨皮质内缘细节", "D": "消除血管与骨骼重叠", "E": "管腔内表面纹理"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-106", "kp": "MIP的临床应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】MIP沿某一投影方向取射线上最大体素值进行投影，高密度的增强血管、钙化等结构被突出显示，是CTA、MRA血管成像最常用的后处理方式。\n【为什么错】B：低对比软组织显示需窗技术或MPR，MIP反而会掩盖低密度结构。C：骨皮质内缘细节可用MPR或VR观察。D：MIP不能消除重叠，重叠的高密度结构会相互叠加。E：管腔内表面观察属仿真内镜技术。", "tr": "MIP“取最大值→亮结构显”，血管/钙化强；重叠是其固有局限，低密度结构易被掩盖。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1020", "t": "单选题", "s": "容积再现（VR）技术的主要特点是", "o": {"A": "仅显示射线上最大密度体素", "B": "利用全部体素信息，通过透明度、颜色与光照编码三维显示，可同时显示多种组织", "C": "与MIP的成像原理完全相同", "D": "不需要原始容积数据", "E": "只能显示组织表面不能显示内部结构"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-107", "kp": "容积再现VR原理", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】VR对容积数据中每个体素按其密度赋予不同的颜色、透明度和亮度，通过三维投影综合显示，可在同一图像中同时展现骨骼、血管、软组织等多种组织并观察内部结构，立体真实感强。\n【为什么错】A：仅取最大密度是MIP的原理。C：VR与MIP原理不同，VR综合全部体素信息。D：VR必须基于CT/MR等容积数据。E：VR不仅能显示表面，还能通过调节透明度观察内部结构。", "tr": "VR=全体素、多组织、可透视；MIP=最大密度投影；SSD=表面阈值显示，三者原理各异。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1021", "t": "单选题", "s": "CT仿真内镜（CTVE）主要基于下列哪种后处理技术实现", "o": {"A": "最大密度投影（MIP）", "B": "表面阴影显示/容积再现等三维成像结合透视投影模拟腔内飞行观察", "C": "多平面重组（MPR）", "D": "窗宽窗位调节", "E": "组织均衡技术"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-108", "kp": "CT仿真内镜技术", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (7)仿真内镜", "ex": "【为什么对】CT仿真内镜以三维表面重建（SSD）或容积再现数据为基础，用透视投影算法模拟内镜从腔内观察，可漫游观察气管、结肠等空腔脏器内壁。\n【为什么错】A：MIP是投影取最大值，不能模拟腔内飞行观察。C：MPR为二维断面重建，无透视三维漫游。D：窗宽窗位只改变灰度显示。E：组织均衡用于均衡灰度，与腔内漫游无关。", "tr": "仿真内镜=三维重建＋透视投影（模拟漫游）；与MIP、MPR、窗技术的功能区分是关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1022", "t": "单选题", "s": "调制传递函数（MTF）描述的是成像系统", "o": {"A": "信号幅度（对比度）随空间频率变化的传递能力", "B": "灰度级数", "C": "辐射剂量水平", "D": "视野大小", "E": "图像存储容量"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-101", "kp": "MTF的定义", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】MTF表示系统对不同空间频率信号的对比度（幅度）传递效率，MTF曲线反映成像系统从低频到高频的细节传递能力，是评价空间分辨率最客观的指标。\n【为什么错】B：灰度级数由量化位数决定。C：剂量水平属防护监测指标。D：视野是探测器尺寸参数。E：存储容量是数据量参数，均与MTF无关。", "tr": "MTF=对比度随空间频率的传递函数；MTF越高、高频下坠越晚，系统分辨率越好。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1023", "t": "单选题", "s": "要客观评价两台DR探测器显示微小病灶（高空间频率细节）的能力，最合适的指标是", "o": {"A": "曝光指数", "B": "像素矩阵大小", "C": "调制传递函数（MTF）", "D": "图像灰度直方图", "E": "显示监视器尺寸"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-102", "kp": "MTF评价高分辨能力", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】微小病灶对应高频空间信号，MTF定量反映系统对各空间频率的对比度传递效率，高频段MTF越高说明微小结构显示能力越强，是客观比较探测器空间分辨性能的标准指标。\n【为什么错】A：曝光指数反映剂量水平，与分辨率无关。B：矩阵只是标称参数，实际空间分辨还受探测器孔径、采样等影响，不能直接等同分辨率。D：灰度直方图反映像素值分布，不评价空间分辨。E：监视器尺寸与探测器成像性能无关。", "tr": "评价“细节/高频能力”首选MTF；矩阵、像素只是空间分辨率的“必要条件”而非等效指标。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U06-1024", "t": "单选题", "s": "关于调制传递函数（MTF）的叙述，正确的是", "o": {"A": "MTF值可以大于1", "B": "空间频率越高，MTF值通常越低，即高频细节传递能力下降", "C": "MTF与空间分辨率无关", "D": "MTF等于0时图像最清晰", "E": "MTF只适用于屏/片系统评价"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-103", "kp": "MTF曲线的特征", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】MTF曲线自低频向高频单调（总体）下降，空间频率越高、对比度传递效率越低，高频细节逐渐丢失，MTF=0.5或0.1对应空间频率常作为系统分辨能力的参考点。\n【为什么错】A：MTF为0~1之间的传递效率比值，理想系统在低频等于1，不可能大于1。C：MTF正是定量描述空间分辨率的核心指标。D：MTF=0表示该频率信号完全不能传递，图像模糊，而非最清晰。E：MTF适用于屏/片系统，同样适用于CR、DR、CT、MR等各类成像系统。", "tr": "MTF∈[0,1]且随频率下降；MTF=0.5/0.1处频率代表极限分辨力。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1025", "t": "单选题", "s": "量子探测效率（DQE）所反映的成像系统性能是", "o": {"A": "系统将入射X线量子有效转换为有用信号的能力，DQE越高，在相同剂量下噪声相对越低", "B": "探测器的视野尺寸", "C": "系统的时间响应能力", "D": "图像文件的压缩率", "E": "监视器的分辨率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-104", "kp": "DQE的含义", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (2)DQE", "ex": "【为什么对】DQE是系统输出信噪比的平方与输入（入射X线）信噪比的平方之比，反映系统有效利用入射量子的效率。DQE越高，同样的剂量下图像噪声越低、信息利用越充分，故DQE高的系统可在较低剂量下获得同等质量图像。\n【为什么错】B：视野是探测器几何参数。C：时间响应（如运动模糊、帧率）非DQE反映内容。D：压缩率是数据存储技术。E：监视器分辨率属显示环节，与探测器DQE无关。", "tr": "DQE=量子利用效率，直接关联“剂量与噪声的平衡”；DQE高→同剂量噪声低或同质量剂量低。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1026", "t": "单选题", "s": "ROC曲线下的面积（AUC）越接近1，表示该诊断系统", "o": {"A": "诊断效能越低", "B": "诊断效能越高，区分病例与正常的能力越强", "C": "图像噪声越大", "D": "所需曝光量越高", "E": "与诊断效能无关"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-105", "kp": "ROC曲线与AUC", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (3)ROC曲线", "ex": "【为什么对】ROC曲线以假阳性率为横轴、真阳性率为纵轴，曲线下面积（AUC）综合反映诊断系统区分正常与异常的能力，AUC越接近1诊断效能越高，AUC=0.5表示无诊断价值。\n【为什么错】A：AUC接近1说明效能高而非低。C：ROC评价的是观察者或系统的判别能力，与图像噪声大小无直接关系。D：ROC与曝光量无必然联系。E：AUC正是诊断效能的量化指标。", "tr": "AUC∈[0.5,1]，越接近1诊断效能越高；0.5=纯随机。ROC属主观评价法。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U06-1027", "t": "单选题", "s": "关于计算机辅助诊断（CAD）的基本定位，下列叙述正确的是", "o": {"A": "完全替代放射科医师独立作出诊断", "B": "利用计算机对图像特征分析，向医师提示可疑病灶，作为“第二阅读者”辅助诊断", "C": "只能用于乳腺X线检查", "D": "主要用于图像压缩存储", "E": "可替代病理学检查"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-101", "kp": "CAD的概念与定位", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (1)概述", "ex": "【为什么对】CAD通过图像分析算法自动检测并标记可疑病灶，其结果由医师复核采纳，起辅助（第二阅读者）作用，可提高检出敏感性、减少漏诊，但不能替代医师作出最终诊断。\n【为什么错】A：CAD定位为辅助而非替代，最终诊断权在医师。C：CAD还用于胸部（肺结节）等多个领域。D：图像压缩是存储技术，非CAD功能。E：CAD是影像学辅助手段，不替代病理检查。", "tr": "CAD=“第二阅读者”辅助，可减漏诊但不替代医师；非乳腺专有。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1028", "t": "单选题", "s": "CAD系统完成病灶自动检测的主要流程顺序是", "o": {"A": "图像采集→图像预处理→可疑区域分割与特征提取→分类判别→输出标记", "B": "直接输出标记，无需图像处理", "C": "分类判别→图像采集→特征提取", "D": "仅提取图像特征，不进行分类", "E": "图像采集后立即打印报告"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-102", "kp": "CAD的基本流程", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (2)基本原理", "ex": "【为什么对】CAD工作流程包括：采集数字图像→预处理（去噪、增强、标准化）→分割并提取可疑区域（候选病灶）→提取形态、密度等特征→用分类器判别真伪→在图像上标记可疑病灶供医师参考。\n【为什么错】B：CAD必须先经图像预处理与特征分析，不能直接输出。C：顺序颠倒，应先采集再处理再分类。D：只提取特征不分类无法给出病灶判别。E：CAD输出的是可疑区域标记，并非直接生成诊断报告。", "tr": "CAD流程“采集→预处理→分割提取→特征→分类→标记”；输出是标记提示而非诊断报告。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1029", "t": "单选题", "s": "关于CAD系统的临床应用特点，下列叙述正确的是", "o": {"A": "CAD对乳腺X线摄影的微钙化簇检测尤为敏感，常作为阅片的辅助工具", "B": "CAD可完全替代医师独立诊断", "C": "CAD检测的假阳性率恒为零", "D": "CAD只能应用于CT图像", "E": "CAD对所有病灶的检出率都达100%"}, "d": "难", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-103", "kp": "CAD临床应用特点", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (2)基本原理", "ex": "【为什么对】CAD算法对乳腺X线图像中微钙化簇、肿块等高对比特征检测灵敏度高，可作为医师阅片的“第二阅读者”，提高乳腺癌筛查检出率、减少漏诊，临床应用最成熟。\n【为什么错】B：CAD是辅助工具，最终诊断由医师作出。C：CAD存在一定假阳性与假阴性，不可能恒为零。D：CAD还广泛用于胸部X线、CT肺结节等领域。E：任何检测方法都不可能100%检出所有病灶。", "tr": "CAD强项=微钙化/结节等高对比目标的“辅助检出”；其假阳性存在、不替代医师。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1030", "t": "单选题", "s": "乳腺X线摄影中，CAD系统主要检测标记的对象是", "o": {"A": "可疑肿块与微钙化簇", "B": "骨密度值", "C": "血流灌注参数", "D": "关节间隙宽度", "E": "淋巴结活检定位点"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-104", "kp": "CAD乳腺应用", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (3)乳腺应用", "ex": "【为什么对】乳腺癌X线征象主要是肿块（含伴毛刺、分叶）和微钙化簇，CAD系统针对这两类特征进行检测与标记，辅助医师提高筛查敏感度，是CAD乳腺应用的核心内容。\n【为什么错】B：骨密度由DXA测量。C：血流灌注属MR/CT灌注成像。D：关节间隙测量属骨关节定量。E：淋巴结活检定位由介入操作完成，均非CAD乳腺检测对象。", "tr": "乳腺CAD两大检测对象=肿块＋微钙化簇；其余功能分属不同检查技术。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1031", "t": "单选题", "s": "胸部X线摄影中，CAD主要用于辅助检测", "o": {"A": "肺结节（肺癌筛查）等肺部病灶", "B": "心包积液量精确测定", "C": "膈肌运动幅度", "D": "支气管分叉角度", "E": "肋间肌厚度"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-105", "kp": "CAD胸部应用", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (4)胸部应用", "ex": "【为什么对】胸片CAD系统主要检测肺内结节性病灶，用于肺癌筛查与体检人群的辅助阅片，可提示可疑结节、减少漏诊，是CAD胸部应用的核心。\n【为什么错】B：心包积液定量多靠超声或MR评估。C：膈肌运动用透视观察。D：支气管分叉角度属气管测量分析，非CAD肺结节检测对象。E：肋间肌厚度测量不属于CAD胸部应用的常规范围。", "tr": "胸片CAD核心=肺结节检测；其他胸内结构定量均有各自专用检查手段。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1032", "t": "单选题", "s": "关于数字图像特性与形成过程的综合分析，下列叙述正确的是", "o": {"A": "采样间隔越小，可分辨的空间频率越高，但数据量随之增大", "B": "量化位深越小，灰度层次越丰富", "C": "像素尺寸越大，空间分辨率越高", "D": "混叠伪影的产生与采样频率无关", "E": "数字图像生成后不能进行任何后处理"}, "d": "难", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-107", "kp": "数字图像特性综合分析", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】根据采样定理，采样间隔越小（采样频率越高）可还原的空间频率越高、能分辨的细节越细，但像素数增加、数据量增大，A正确。\n【为什么错】B：位深越小灰度级越少，层次越差。C：像素越大细节分辨能力越差、空间分辨率越低。D：混叠正是采样不足（采样频率过低）引起的。E：数字图像最大的优势之一就是可灵活后处理。", "tr": "“采样间隔小→频率高→细节细→数据大”是一组正相关；位深小、像素大、采样不足均为质量恶化方向。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U06-1033", "t": "多选题", "s": "与传统屏/片成像相比，数字X线成像的特点包括", "o": {"A": "动态范围宽、曝光宽容度大", "B": "可进行丰富的图像后处理", "C": "可实现数字化存储与网络传输", "D": "空间分辨率必然高于增感屏-胶片系统", "E": "曝光条件不当时仍可通过后处理改善显示"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-108", "kp": "数字X线成像的特点", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】数字成像具有动态范围宽、宽容度大、可后处理、可存储传输等优势，曝光条件偏离时仍可经后处理（如窗宽窗位）改善显示，A、B、C、E均正确。\n【为什么错】D：数字系统的空间分辨率受像素尺寸限制，并不必然高于增感屏-胶片系统，后者有较高的极限分辨率。", "tr": "数字成像的优势是“宽容度＋后处理＋传输”，不等于分辨率必然高于屏/片。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1034", "t": "多选题", "s": "关于模拟图像与数字图像的区别，下列叙述正确的有", "o": {"A": "模拟图像的空间位置与密度是连续变化的", "B": "数字图像由离散的像素构成", "C": "模拟图像可直接被计算机识别和处理", "D": "数字图像可进行量化压缩与远程传输", "E": "模拟图像与数字图像都是离散量"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-109", "kp": "模拟与数字图像区别", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】模拟图像连续、数字图像离散是二者本质区别；数字图像经采样量化后可压缩、存储和远程传输，A、B、D正确。\n【为什么错】C：计算机只能处理数字化信号，模拟图像需先经A/D转换。E：只有数字图像是离散量，模拟图像是连续量。", "tr": "“模拟连续、数字离散”；模拟图像不能直接进计算机，须先数字化。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1035", "t": "多选题", "s": "关于数字图像常用术语，下列叙述正确的有", "o": {"A": "像素是构成数字图像的最小单元", "B": "矩阵是像素的纵横排列阵列", "C": "量化位深决定图像的灰度级数", "D": "动态范围指成像系统能够响应的信号幅度范围", "E": "像素值恒等于CT值"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-110", "kp": "数字图像术语集合", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】像素为最小单元，矩阵为像素阵列，位深决定灰度级数（2^n），动态范围指系统可响应的信号幅度范围，A、B、C、D均正确。\n【为什么错】E：像素值是探测器输出信号经量化的数值，只有在CT中才转换为CT值（HU），不同成像系统含义不同，不能恒等。", "tr": "“像素值”是通用术语，“CT值”是CT专用换算值，二者不恒等。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1036", "t": "多选题", "s": "关于数字图像矩阵、像素与视野（FOV）的关系，下列叙述正确的有", "o": {"A": "视野不变时，矩阵增大则像素尺寸减小", "B": "像素尺寸约等于视野边长除以矩阵边长", "C": "矩阵增大可提高空间分辨率", "D": "像素尺寸越大，空间分辨率越高", "E": "矩阵大小与视野大小无关"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-111", "kp": "矩阵像素FOV关系", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (2)矩阵与像素", "ex": "【为什么对】像素尺寸=FOV÷矩阵，FOV不变时矩阵增大则像素变小、空间分辨率提高，A、B、C正确。\n【为什么错】D：像素越大能分辨的细节越粗，空间分辨率越低。E：像素大小同时取决于FOV与矩阵，二者密切相关。", "tr": "像素=FOV÷矩阵；“矩阵大像素小分辨率高”是主考点。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1037", "t": "多选题", "s": "关于采样定理与混叠伪影，下列叙述正确的有", "o": {"A": "采样频率应不小于信号最高频率的2倍", "B": "采样不足会引起混叠伪影", "C": "采样间隔越大，可分辨的最高空间频率越低", "D": "混叠时高频信息以错误低频形式重现", "E": "提高采样频率会使图像分辨率下降"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-108", "kp": "采样定理与混叠", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】奈奎斯特定理要求采样频率≥2倍最高频率；采样不足（间隔过大）时高频成分折叠为低频，产生混叠；采样间隔越大可分辨频率越低，A、B、C、D正确。\n【为什么错】E：提高采样频率可还原更高空间频率、细节更清晰，图像分辨率提高而非下降。", "tr": "采样“频率高→细节好、无混叠”；混叠=高频变低频，识别关键词“折叠”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1038", "t": "多选题", "s": "关于量化与量化位深，下列叙述正确的有", "o": {"A": "量化是将连续的模拟量离散为有限个灰度级", "B": "位深由12位增至14位，灰度级由4096增至16384", "C": "位深增大使数据存储量增大", "D": "量化级数越多，灰阶显示越细腻", "E": "量化过程会增加受检者X线剂量"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-109", "kp": "量化与位深", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (2)量化", "ex": "【为什么对】量化离散化信号幅度；灰度级=2^n，12位=4096、14位=16384；位深大则灰度层次细腻、每像素比特数多、数据量大，A、B、C、D正确。\n【为什么错】E：量化是模数转换的软件/电路环节，与X线曝光条件和受检者剂量无关。", "tr": "位深与灰度级换算（2^n）常考；量化不增加剂量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1039", "t": "多选题", "s": "关于模数转换（A/D转换）环节，下列叙述正确的有", "o": {"A": "A/D转换主要包括采样与量化两个步骤", "B": "采样完成空间位置的离散化", "C": "量化完成信号幅度的离散化", "D": "转换完成后可进行数字图像后处理", "E": "A/D转换会减少图像的灰度级数"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-110", "kp": "A/D转换环节", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (3)转换", "ex": "【为什么对】A/D转换由采样（离散化位置）和量化（离散化幅度）两步完成，输出数字数据后即可进行各种后处理，A、B、C、D正确。\n【为什么错】E：A/D转换恰恰把模拟量离散为有限灰度级数（由量化位数决定），是产生灰度级而非“减少”，表述不当。", "tr": "A/D转换=采样＋量化；量化位数决定灰度级数，转换是产生数字图像的基础。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1040", "t": "多选题", "s": "关于窗口技术（窗宽、窗位）的规律，下列叙述正确的有", "o": {"A": "窗宽决定显示灰阶所对应的CT值范围", "B": "窗位决定显示范围的中心CT值", "C": "窗宽增大时，单位灰阶对应的CT值跨度增大、对比度降低", "D": "显示范围=窗位±窗宽/2", "E": "窗位增大可使显示的CT值范围变宽"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-109", "kp": "窗宽窗位规律", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】窗宽决定显示范围宽度、窗位决定中心；窗宽越大单位灰阶CT值跨度越大、对比度越低；显示上下限为窗位±窗宽/2，A、B、C、D正确。\n【为什么错】E：显示范围宽度只由窗宽决定，窗位只移动窗口位置，不改变范围宽度。", "tr": "窗宽管“宽与对比”，窗位管“中心位置”；范围宽度与窗位无关。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1041", "t": "多选题", "s": "关于CT窗宽窗位调节的临床应用，下列叙述正确的有", "o": {"A": "观察肺组织常用肺窗（窗宽较大）", "B": "观察纵隔结构常用纵隔窗（窗宽较窄、窗位居中）", "C": "观察骨骼病变应选用骨窗", "D": "观察肝脏病灶时窗宽可加大至2000 HU以上", "E": "调节窗宽窗位不会改变像素的原始数值"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-110", "kp": "窗宽窗位临床应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】肺窗大窗宽显示肺纹理，纵隔窗窄窗宽显示软组织对比，骨窗显示骨小梁结构；窗宽窗位仅改变灰度显示映射，不修改原始像素数据，A、B、C、E正确。\n【为什么错】D：肝实质与病灶密度差较小，应选用较窄窗宽（通常100~200 HU量级）以增大对比度，窗宽加至2000 HU反而使肝内低对比结构显示不清。", "tr": "“低对比组织（肝、纵隔）用小窗宽”；大窗宽用于肺、骨等对比度大的结构。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1042", "t": "多选题", "s": "关于常用三维后处理技术的特点，下列叙述正确的有", "o": {"A": "MPR是在容积数据基础上重建的二维断面图像", "B": "SSD通过阈值提取并显示组织的表面结构", "C": "MIP沿投影方向取最大体素值进行显示", "D": "VR综合利用全部体素信息进行三维显示", "E": "MIP可以直接显示软组织中的低密度病变"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-111", "kp": "三维后处理技术对比", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】MPR为二维重切、SSD为表面阈值显示、MIP取最大密度投影、VR利用全体素信息并赋以透明度颜色显示，A、B、C、D分别准确描述了四种技术。\n【为什么错】E：MIP显示的是投影方向上的最大密度，会掩盖低密度软组织病变，低对比结构观察应选MPR或窗技术。", "tr": "四种后处理“谁看什么”：MPR断面、SSD表面、MIP最大密度、VR容积透视。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1043", "t": "多选题", "s": "关于最大密度投影（MIP）的临床应用，下列叙述正确的有", "o": {"A": "常用于显示CTA的增强血管", "B": "可用于显示钙化等高密度结构", "C": "可直接观察低密度软组织病变", "D": "血管重叠明显时可采用旋转投影或多角度薄层MIP改善", "E": "MIP能自动消除血管与骨骼的重叠"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-112", "kp": "MIP临床应用与局限", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】MIP对高密度结构（增强血管、钙化）显示良好，是CTA常用后处理；重叠时可用旋转多角度投影或薄层MIP减少结构重叠、定位病灶，A、B、D正确。\n【为什么错】C：MIP取最大密度会掩盖低密度软组织病变。E：MIP不能消除重叠，高密度结构会相互叠加，需靠旋转或薄层技术改善。", "tr": "MIP“亮结构强、低密度被掩盖、重叠无法自动消除”；薄层MIP/旋转投影是补救手段。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1044", "t": "多选题", "s": "关于MTF、DQE与ROC三种评价指标，下列叙述正确的有", "o": {"A": "MTF用于评价成像系统的空间分辨（对比度传递）能力", "B": "DQE用于评价系统对入射X线量子的利用效率", "C": "ROC曲线用于评价观察者或系统的诊断效能", "D": "MTF数值越高，表示系统细节显示能力越好", "E": "DQE越高，达到同样图像质量所需的曝光量越大"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-106", "kp": "MTF DQE ROC概念辨析", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】MTF评价空间分辨（对比度随频率传递）、DQE评价量子利用效率、ROC评价诊断效能，三者定位清晰；MTF越高细节传递越好，A、B、C、D正确。\n【为什么错】E：DQE越高表示量子利用效率越高，达到同等图像质量所需剂量越低，方向恰好相反。", "tr": "“MTF管分辨率、DQE管剂量效率、ROC管诊断效能”；DQE高→剂量低。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1045", "t": "多选题", "s": "调制传递函数（MTF）用于客观评价成像系统，下列关于其特点的叙述，正确的有", "o": {"A": "MTF的取值范围在0~1之间", "B": "空间频率越高，MTF通常越低", "C": "MTF等于0.1时所对应的空间频率可作为极限分辨力参考", "D": "MTF反映系统对不同空间频率信号的对比度传递效率", "E": "MTF只反映图像噪声水平"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-107", "kp": "MTF特征", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】MTF为0~1的对比度传递效率，低频高、高频低；MTF=0.1或0.5对应频率常作为系统分辨力参考值，A、B、C、D正确。\n【为什么错】E：MTF描述对比度随空间频率的传递，与噪声无直接关系，噪声由NPS等指标评价。", "tr": "MTF≠噪声指标；MTF=0.1处频率≈系统极限分辨力（10%对比度传递）。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1046", "t": "多选题", "s": "关于ROC曲线分析，下列叙述正确的有", "o": {"A": "ROC曲线以假阳性率为横轴", "B": "ROC曲线以真阳性率为纵轴", "C": "曲线下面积（AUC）越接近1，诊断效能越高", "D": "ROC分析属于影像质量的主观（心理学）评价法", "E": "AUC等于0.5表示诊断效能最高"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-108", "kp": "ROC曲线特征", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (3)ROC曲线", "ex": "【为什么对】ROC以假阳性率（横）对真阳性率（纵）绘制，AUC反映诊断系统区分能力，越接近1效能越高；ROC依赖观察者对图像信号作判断，属主观评价法，A、B、C、D正确。\n【为什么错】E：AUC=0.5表示诊断能力等同于随机猜测，诊断效能最低；越接近1才越高。", "tr": "AUC=0.5=无诊断价值；ROC属主观评价，勿归入客观物理评价。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U06-1047", "t": "多选题", "s": "关于量子探测效率（DQE），下列叙述正确的有", "o": {"A": "DQE反映系统有效利用入射X线量子的效率", "B": "DQE越高，在相同剂量下图像噪声越低", "C": "DQE受探测器材料、结构与成像链设计的影响", "D": "DQE高的系统可在较低剂量下获得同等质量的图像", "E": "DQE只取决于显示监视器的性能"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-109", "kp": "DQE特性", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (2)DQE", "ex": "【为什么对】DQE=输出信噪比平方/输入信噪比平方，反映量子利用效率，受探测器材料、结构与成像链影响；DQE高意味着同剂量下噪声低、可在低剂量下保证图像质量，A、B、C、D正确。\n【为什么错】E：DQE是探测器与成像链的性能指标，与显示监视器无关。", "tr": "DQE是“探测器层”指标；DQE高→可降剂量保质量，勿与显示设备混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1048", "t": "多选题", "s": "关于计算机辅助诊断（CAD）的应用，下列叙述正确的有", "o": {"A": "CAD作为“第二阅读者”辅助放射科医师诊断", "B": "CAD可用于乳腺X线摄影中微钙化簇与肿块的检测", "C": "CAD可用于胸部X线摄影肺结节的辅助检出", "D": "CAD存在一定的假阳性和假阴性，需医师复核确认", "E": "CAD检测到病灶即可直接确诊，无需医师判断"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-106", "kp": "CAD综合应用", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (1)概述", "ex": "【为什么对】CAD定位为辅助（第二阅读者），在乳腺（微钙化、肿块）与胸部（肺结节）等领域应用成熟，可提高检出敏感性；但其输出存在假阳/假阴，最终由医师复核确认，A、B、C、D正确。\n【为什么错】E：CAD不能替代医师作出确诊，其提示必须经医师结合临床与其他检查综合判断。", "tr": "CAD=辅助提示、可减漏诊、有假阳性、不替代诊断；这是CAD考点的四条主线。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U06-1049", "t": "多选题", "s": "关于组织均衡技术，下列叙述正确的有", "o": {"A": "对探测器信号过饱和与欠饱和区域的灰度进行压缩补偿", "B": "适用于胸部、四肢等厚薄差异较大的部位", "C": "属于数字图像后处理，不增加受检者剂量", "D": "可使不同密度组织在同一图像中清晰显示", "E": "属于X线发生环节的参数调节技术"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-113", "kp": "组织均衡技术", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (2)组织均衡技术", "ex": "【为什么对】组织均衡压缩补偿过饱和/欠饱和区灰度，使厚薄差异大部位（胸部肺与纵隔、四肢）不同密度组织同图清晰显示，属纯软件后处理、不增加剂量，A、B、C、D正确。\n【为什么错】E：组织均衡是图像后处理环节，与X线球管、kV/mAs等发生参数无关。", "tr": "组织均衡“软件后处理、不增剂量、均衡灰度”；别与X线发生条件混为一谈。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U06-1050a", "t": "共用题干题", "s": "MPR重建所得到的主要图像类型是", "o": {"A": "任意方位的二维断面图像", "B": "三维表面阴影图像", "C": "最大密度投影图像", "D": "容积再现图像", "E": "仿真内镜图像"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-114", "kp": "MPR的图像类型", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】MPR是在容积扫描体数据基础上，通过体素重切获得任意方位（冠状、矢状、斜面、曲面）的二维断面图像，是三种基本后处理中唯一的二维断面重建技术。\n【为什么错】B：三维表面阴影是SSD的功能。C：最大密度投影是MIP。D：容积再现有三维容积显示。E：仿真内镜模拟腔内漫游，均非MPR输出。", "tr": "MPR=二维断面重切；三维显示交给SSD/VR，最大密度交给MIP。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0601", "gs": "患者男，52岁，因外伤致腰椎压缩性骨折，临床拟行腰椎CT检查以明确椎体骨折范围及椎管受累情况。设备为64层螺旋CT，技师采用薄层扫描并拟行多平面重组（MPR）后处理辅助诊断。"}, {"id": "U06-1050b", "t": "共用题干题", "s": "要获得质量良好的冠状位、矢状位MPR图像，关键前提是", "o": {"A": "增大扫描螺距", "B": "采用薄层扫描，使体素在各方向近似各向同性（等方性）", "C": "加大窗宽窗位", "D": "使用高浓度对比剂", "E": "尽量缩短扫描时间"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-115", "kp": "MPR与各向同性采集", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】MPR重建图像的清晰度取决于原始体素是否各向同性，薄层扫描使层面内与层厚方向体素大小接近，任意方位重建均无锯齿失真，故薄层是MPR质量的关键。\n【为什么错】A：螺距影响覆盖速度与噪声，不是MPR质量关键。C：窗宽窗位只影响显示，不影响重建质量。D：对比剂用于血管观察，与本例骨结构重组无关。E：缩短扫描时间不改善重建分辨率。", "tr": "“薄层各向同性”是MPR质量的前提；螺距、窗宽、对比剂均非关键。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0601", "gs": ""}, {"id": "U06-1050c", "t": "共用题干题", "s": "为重点观察椎管内有无骨块突入及椎体后缘骨折线，最合适的后处理是", "o": {"A": "采用薄层矢状位与冠状位MPR显示椎管及椎体后缘", "B": "仅观察横断面原始图像", "C": "使用SSD三维表面重建", "D": "仅使用MIP投影", "E": "只进行仿真内镜观察"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-116", "kp": "MPR显示椎管骨折", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】椎管内骨块突入与椎体后缘骨折线需在矢状位、冠状位等断面图像上清晰显示解剖关系，薄层MPR沿椎管长轴重切可直观显示骨块与椎管的位置关系，是首选。\n【为什么错】B：横断面图像对椎管长轴方向的骨块范围显示有限。C：SSD为表面重建，无法观察椎管内断面细节。D：MIP取最大密度，椎管内容易被周围高密度骨掩盖。E：仿真内镜适用于空腔脏器腔内观察，不用于椎管骨块评估。", "tr": "“看椎管/骨折线”选MPR断面；三维表面与MIP均不适合椎管内细节观察。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0601", "gs": ""}, {"id": "U06-1051a", "t": "共用题干题", "s": "MIP成像的基本原理是", "o": {"A": "沿投影方向取射线上体素的最大值进行投影显示", "B": "取射线上体素的平均值进行显示", "C": "提取组织表面并加光照阴影显示", "D": "对体素进行透明度与颜色编码后三维显示", "E": "重建任意方位的断面图像"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-117", "kp": "MIP成像原理", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】MIP沿设定投影方向对每个像素所穿过的体素取最大CT值进行投影，突出显示增强血管、钙化等高密度结构。\n【为什么错】B：取平均值是平均密度投影（AIP/MinIP反之取最小）。C：加光照显示表面是SSD。D：透明度颜色编码是VR。E：任意断面重建是MPR。", "tr": "MIP“取最大”、MinIP“取最小”、SSD“表面光照”、VR“全体素透明”；四者原理分明。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0602", "gs": "患者男，58岁，因反复咯血伴痰中带血丝3个月，临床疑支气管动脉供血异常，行胸部CT增强扫描。扫描采用薄层增强采集，技师拟行最大密度投影（MIP）后处理，以观察异常供血动脉的走行、开口位置及与病灶的关系，为选择性支气管动脉造影与栓塞治疗提供依据。"}, {"id": "U06-1051b", "t": "共用题干题", "s": "为清晰显示支气管动脉全程及其分支走行，最适合的后处理方式是", "o": {"A": "薄层MIP结合多角度旋转投影观察血管全程", "B": "只观察横断面原始图像", "C": "仅调节窗宽窗位", "D": "将层厚增大至10 mm后再投影", "E": "仅使用SSD表面重建"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-118", "kp": "MIP显示血管的应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】支气管动脉细小且走行曲折，薄层MIP可减少重叠、突出血管；多角度旋转投影可从不同方向观察血管全程与分支，是显示小血管的常用组合。\n【为什么错】B：单张横断面不能显示血管全程走行。C：窗宽窗位只改变灰度显示。D：厚层MIP使细小血管被周围结构平均化、显示不清。E：SSD表面重建对细小血管的显示不如MIP。", "tr": "“小血管全程”=薄层MIP＋旋转投影；厚层MIP反而丢失小血管细节。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0602", "gs": ""}, {"id": "U06-1051c", "t": "共用题干题", "s": "若MIP图像上支气管动脉与肋间动脉、椎体骨质重叠明显，干扰判断，下列处理最恰当的是", "o": {"A": "采用薄层MIP限定兴趣区范围，并结合MPR、VR等综合观察", "B": "增大对比剂注射总量", "C": "加大窗宽窗位", "D": "更换扫描探测器", "E": "放弃血管观察"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-119", "kp": "MIP重叠的处理", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】MIP沿投影方向所有高密度结构相互叠加，重叠明显时可用薄层MIP（减小投影层厚）或限定兴趣区（VOI）剔除无关高密度结构，再配合MPR确认解剖关系、VR观察空间形态，多技术综合是正确处理。\n【为什么错】B：对比剂用量增加不解决骨骼重叠。C：窗宽窗位不能分离重叠的高密度结构。D：探测器更换与实际后处理无关。E：放弃观察不符合诊断需要。", "tr": "MIP重叠解决思路“薄层+兴趣区限定+多技术互补”；靠剂量、窗宽、换设备均无效。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0602", "gs": ""}, {"id": "U06-1052a", "t": "共用题干题", "s": "关于容积再现（VR）三维重建的特点，下列叙述正确的是", "o": {"A": "对每个体素按密度赋予透明度与颜色，可同时显示骨、血管、软组织等多种组织", "B": "VR仅显示投影方向上的最大密度体素", "C": "VR只显示组织表面，不显示内部结构", "D": "VR属于二维断面重建", "E": "VR不需要容积扫描数据"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-120", "kp": "VR重建原理与特点", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】VR对容积数据中每个体素根据其密度值赋予不同的透明度、颜色与亮度，经三维投影可同时显示多种组织，并可通过调节透明度观察内部结构，立体真实感强。\n【为什么错】B：取最大密度是MIP原理。C：VR可调节透明度显示内部结构，不仅显示表面。D：VR是三维容积显示，不是二维断面。E：VR必须基于CT/MR等容积扫描数据。", "tr": "VR=“全体素透明着色”，多组织同显可透视；MIP/SSD分别只取最大密度/表面。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0603", "gs": "患者男，35岁，因车祸致骨盆多发骨折伴骶髂关节分离，临床拟行骨盆CT检查并行三维重建，以整体评估骨折块移位方向与旋转畸形、骶髂关节受累程度，为制定手术入路与内固定方案提供参考。"}, {"id": "U06-1052b", "t": "共用题干题", "s": "为同时显示骨盆骨折整体形态与盆腔血管关系，最适合的后处理方案是", "o": {"A": "VR三维重建（骨骼与血管分别赋予不同透明度与颜色）并配合MIP观察血管", "B": "仅用SSD表面重建", "C": "仅用MPR断面", "D": "仅调节窗宽窗位", "E": "仅做仿真内镜"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-121", "kp": "VR的临床应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】VR可对骨与血管设定不同阈值和透明度、颜色，在同一三维图像中同时显示骨骼骨折与血管走行；MIP可作为补充突出血管细节，二者结合适合创伤并发出血血管评估。\n【为什么错】B：SSD仅显示表面，不能同时显示血管内部结构关系。C：MPR是断面图像，缺乏整体三维观感。D：窗宽窗位不能实现三维立体显示。E：仿真内镜用于空腔脏器腔内观察，不适合骨盆骨折评估。", "tr": "VR的强项=“骨＋血管多组织同图”；MIP补血管细节，SSD只做表面，二者不能替代。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0603", "gs": ""}, {"id": "U06-1052c", "t": "共用题干题", "s": "与SSD相比，VR在显示复杂粉碎性骨折方面的主要优势是", "o": {"A": "利用全部体素信息、可调节透明度显示内部结构，受阈值选择影响小、信息丢失少", "B": "VR成像速度比SSD更快", "C": "VR无需原始容积数据", "D": "VR只能显示骨骼组织", "E": "VR的空间分辨率必然高于SSD"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-122", "kp": "VR与SSD的比较", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】SSD靠单一阈值提取表面，阈值选择不当会丢失或误增表面信息；VR利用全部体素信息并可通过调节透明度保留内部细节，在复杂骨折、多组织显示中信息保留更完整、伪影更少。\n【为什么错】B：VR计算量大，速度通常不优于SSD。C：VR同样需要容积数据。D：VR可显示骨、血管、软组织等多种组织。E：VR与SSD的空间分辨率均取决于原始数据，VR并非必然更高。", "tr": "VR强于SSD的本质是“全体素、可调透明度、不依赖单一阈值”；“速度/分辨率必高”是错误表述。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0603", "gs": ""}, {"id": "U06-1053a", "t": "共用题干题", "s": "CTVE成像所依赖的主要技术是", "o": {"A": "三维表面/容积重建结合透视投影模拟腔内飞行观察", "B": "最大密度投影", "C": "多平面重组", "D": "窗宽窗位调节", "E": "组织均衡技术"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-123", "kp": "CT仿真内镜技术基础", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (7)仿真内镜", "ex": "【为什么对】CTVE以三维重建（SSD或VR）数据为基础，采用透视投影算法模拟内镜镜头从空腔脏器内部飞行观察，实现“虚拟内镜”浏览。\n【为什么错】B：MIP是最大密度投影，不能模拟腔内漫游。C：MPR为二维断面重建。D：窗宽窗位只改变灰度显示。E：组织均衡用于灰度均衡，与腔内漫游无关。", "tr": "仿真内镜=三维重建＋透视投影＋腔内漫游；不是MIP/MPR/窗技术的功能。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0604", "gs": "患者男，65岁，因无痛性血便伴排便习惯改变3个月行结肠CT检查，纤维结肠镜因肠腔严重狭窄未能通过，临床拟行CT仿真结肠内镜（CTVE）观察狭窄段形态、长度及其远侧肠腔情况，评估有无梗阻与占位性病变。"}, {"id": "U06-1053b", "t": "共用题干题", "s": "关于CTVE在结肠病变评估中的临床应用特点，下列叙述正确的是", "o": {"A": "属无创检查，可越过结肠镜无法通过的狭窄段观察远侧肠腔，但不能观察黏膜色泽、不能行组织活检", "B": "CTVE可直接替代纤维结肠镜进行组织活检", "C": "CTVE可分辨黏膜颜色和血管纹理", "D": "CTVE无法用于结肠检查", "E": "CTVE对任何大小的息肉均可100%检出"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-124", "kp": "CTVE的临床应用特点", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (7)仿真内镜", "ex": "【为什么对】CTVE无创、不需插入内镜，可观察狭窄段远侧肠腔，弥补结肠镜不足；但CTVE基于CT密度成像，不能观察黏膜真实色泽，也不能进行活检和息肉切除，需与纤维内镜互补，A正确。\n【为什么错】B：CTVE不能取材活检，无法替代纤维内镜。C：CTVE无颜色信息，不能分辨黏膜色泽与血管纹理。D：CTVE在结肠息肉、狭窄评估中应用广泛。E：CTVE对小息肉存在漏检，检出率不可能100%。", "tr": "CTVE优点=无创+过狭窄段；缺点=无颜色、无活检；与纤维内镜是“互补”而非“替代”。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0604", "gs": ""}, {"id": "U06-1054", "t": "案例分析题", "s": "患者男，40岁，车祸致多发伤后行胸部CT平扫，临床需同时观察肺实质挫伤范围、胸腔积血情况以及多发肋骨骨折的位置与错位程度。因肺组织与骨组织密度差异悬殊，单一显示条件无法兼顾，技师拟通过调节窗宽、窗位分别观察不同结构，以兼顾肺实质、纵隔与骨性胸廓的诊断需要。请为该患者的胸部CT选择合理的窗技术显示方案。", "o": {"A": "观察肺实质采用大窗宽的肺窗，观察肋骨骨折采用骨窗", "B": "全部结构均用同一窗宽窗位显示", "C": "观察肺实质时窗宽应小于100 HU", "D": "观察肋骨骨折时窗宽应大于2000 HU", "E": "调节窗宽窗位会改变像素的原始数值"}, "d": "易", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-125", "kp": "窗宽窗位综合应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】肺实质内含大量气体、密度对比大，用大窗宽肺窗（窗宽约1500 HU、窗位约-600 HU）显示肺纹理与挫伤；肋骨为高密度骨组织，用骨窗（窗宽约1000~1500 HU、窗位约300 HU）显示骨皮质与骨折线，不同结构需采用不同窗设置。\n【为什么错】B：肺、骨组织密度差异巨大，同一窗宽窗位无法同时最佳显示。C：肺窗窗宽通常上千HU，小于100 HU无法显示肺内密度跨度。D：骨窗窗宽一般1000~1500 HU，超过2000 HU会使骨折线对比度不足。E：窗宽窗位只改变灰阶显示映射，不改变原始像素数值。", "tr": "“肺窗大窗宽、骨窗适中、纵隔窗小窗宽”；调窗不改原始像素值是常考细节。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1055", "t": "案例分析题", "s": "患者女，28岁，外伤后右足疼痛、不能负重，临床疑距骨骨折，行足踝CT薄层平扫，扫描层厚0.625 mm，横断面图像上距骨可见可疑骨折线，但因断端无明显错位，骨折线在横断面上显示不清，难以准确判断骨折是否存在及其范围，且对后续负重行走与治疗方案影响重大。技师拟通过CT后处理技术辅助诊断，请选择最适宜的重建方法，并简要说明其原理。", "o": {"A": "沿骨折线走行进行薄层多平面重组（MPR）观察", "B": "增大层厚重新扫描", "C": "仅依靠横断面原始图像判断", "D": "用MIP观察低密度骨折线", "E": "不做后处理直接报告"}, "d": "易", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-126", "kp": "MPR显示隐匿骨折", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】距骨等不规则骨骨折线常不与横断面平行，横断面上显示不清。薄层MPR沿骨折线走行方向（矢状位、冠状位或斜面）重切，可清晰显示骨折线与骨折范围，是判定隐匿骨折的常用手段。\n【为什么错】B：增大层厚加重部分容积效应，骨折线更易被掩盖。C：横断面信息不足时应借助后处理而非强判。D：MIP取最大密度，低密度骨折线反而被周围高密度骨掩盖，不适合。E：不做后处理可能漏诊骨折。", "tr": "“隐匿骨折、骨折线不清”首推薄层MPR沿骨折线重切；MIP掩盖低密度线影，勿误选。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1056", "t": "案例分析题", "s": "患者男，55岁，体检行胸部DR检查，采用站立后前位摄影。由于胸部结构密度差异大，图像上肺野外带过度曝光（偏白），纵隔与心影后方区域曝光不足（偏黑），肺野与纵隔结构无法在同一幅图像上同时清晰显示，影响双肺、纵隔及心影后方病变的观察，需二次曝光才能满足诊断。影像科拟通过数字图像处理技术改善一次成像中肺野与纵隔的显示效果，请选择最合适的处理方法。", "o": {"A": "该现象属正常，无需处理", "B": "可使用组织均衡技术对过饱和与欠饱和区域灰度进行压缩补偿，使肺野与纵隔同时清晰显示", "C": "需加大曝光量重新投照", "D": "组织均衡处理会增加受检者辐射剂量", "E": "纵隔区域显示不清与图像处理无关"}, "d": "中", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-127", "kp": "组织均衡改善胸部DR显示", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (2)组织均衡技术", "ex": "【为什么对】胸部肺（高透亮）与纵隔（高密度）厚度与密度差异大，超出单一灰阶同时显示能力。组织均衡技术对探测器过饱和（肺野）与欠饱和（纵隔）区域信号进行灰度压缩补偿，使两者在同一图像上清晰显示，正是解决该问题的专用技术。\n【为什么错】A：该现象反映动态显示范围不足，可通过后处理改善，并非不需处理。C：加大曝光会改善纵隔但使肺野更过曝，不能两全。D：组织均衡是纯软件处理，不改变曝光条件、不增加剂量。E：纵隔显示改善正依赖图像后处理。", "tr": "组织均衡专治“厚薄差异大、两区难以同显”；是软件处理、不加剂量。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1057", "t": "案例分析题", "s": "患者女，60岁，因突发剧烈头痛伴恶心、呕吐急诊就诊，临床高度疑蛛网膜下腔出血，行头颈联合CTA检查，采用自动管电流调节技术，原始薄层增强图像已采集完成。技师拟通过后处理技术整体观察颅内动脉主干及分支的走行、有无动脉瘤及其瘤颈方向与空间形态，为介入栓塞治疗提供解剖依据。请选择最适宜的后处理显示方法，并说明其优缺点。", "o": {"A": "采用MIP多角度旋转投影显示血管全程，并结合VR观察动脉瘤立体形态", "B": "仅使用SSD表面重建", "C": "仅调节窗宽窗位显示", "D": "仅用MPR断面即能完全替代MIP与VR", "E": "无需任何后处理"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-128", "kp": "MIP与VR显示脑血管", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】CTA血管观察常规采用MIP多角度旋转投影显示血管走行与分支，再用VR三维显示观察动脉瘤与载瘤动脉的空间关系、瘤颈形态，MIP+VR联合是CTA后处理的标准组合。\n【为什么错】B：SSD表面重建对细小血管与瘤颈显示不如MIP/VR。C：窗宽窗位只改变灰度，无三维血管显示。D：MPR为断面图像，不能提供血管整体三维形态，不能完全替代。E：不作后处理难以整体评估血管。", "tr": "CTA标配“MIP看走行＋VR看形态”；SSD、MPR、窗技术均不能替代。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1058", "t": "案例分析题", "s": "患者男，30岁，高处坠落致骨盆粉碎性骨折伴出血性休克，经补液输血等抢救后生命体征平稳，待择期手术。术前临床需整体评估骨折块移位方向、旋转畸形及骶髂关节受累情况，以设计手术入路与内固定方案。骨盆CT薄层扫描已完成，技师拟行三维重建，请选择最适宜的后处理显示技术并说明其特点，同时指出该技术用于骨盆骨折评估时的局限性。", "o": {"A": "采用VR三维重建结合旋转观察，直观显示骨折整体形态与移位关系", "B": "仅观察横断面图像即可满足需求", "C": "用MIP评估骨皮质连续性即可", "D": "用仿真内镜观察骨折面", "E": "仅加大窗宽窗位"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-129", "kp": "VR评估复杂骨折", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】复杂粉碎性骨折需要整体三维观感来评估骨折块的空间移位、旋转畸形，VR利用全部体素信息、可调节透明度与颜色，直观显示骨折全貌与关节关系，配合旋转观察效果最佳，是骨科术前评估的标准后处理。\n【为什么错】B：横断面难以提供骨折块空间移位的整体观感。C：MIP取最大密度，对骨折形态显示不直观。D：仿真内镜用于空腔脏器腔内观察，不适合骨折面评估。E：窗宽窗位无法实现三维立体显示。", "tr": "复杂骨折三维评估首选VR；MIP/SSD各有局限，仿真内镜不用于骨折。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1059", "t": "案例分析题", "s": "患者男，62岁，因便血伴排便习惯改变3个月行结肠CT检查，发现降结肠管腔明显狭窄，纤维结肠镜因狭窄未能通过，无法评估狭窄远侧肠腔情况。临床拟行CT仿真结肠内镜（CTVE）评估狭窄段形态、长度及其远侧肠腔内有无占位性病变，为手术治疗与随访提供依据。请分析CTVE检查中需要重点关注的操作要点与注意事项。", "o": {"A": "采用CTVE结合MPR观察狭窄段及远侧肠腔，必要时以横断面核实", "B": "CTVE可替代病理活检明确病灶性质", "C": "CTVE可观察黏膜真实色泽", "D": "CTVE需要经肛插入内镜器械", "E": "狭窄段远侧肠腔无法通过CTVE观察"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-130", "kp": "CTVE评估结肠狭窄", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (7)仿真内镜", "ex": "【为什么对】CTVE无创且不受肠腔狭窄限制，可模拟内镜越过狭窄段观察远侧肠腔，配合MPR、横断面图像核实病变位置与肠壁情况，是结肠镜受阻时的有效补充手段。\n【为什么错】B：CTVE不能取材活检，不能替代病理检查明确性质。C：CTVE基于CT密度，无黏膜颜色信息。D：CTVE无需插入内镜，是纯影像后处理。E：CTVE的优势恰恰是可越过狭窄段观察远侧肠腔。", "tr": "CTVE“过狭窄段＋无创”是优势，“无颜色、无活检”是局限；需配合断面图像核实。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1060", "t": "案例分析题", "s": "患儿男，8岁，头部外伤后行头颅CT平扫，横断面图像显示额部凹陷性骨折，但骨折范围、凹陷深度及碎片移位情况在横断面上显示欠全面，临床难以据此判断手术指征。临床拟行颅骨三维重建以观察骨折的范围与深度，决定是否手术整复。颅脑CT薄层扫描已完成，技师拟进行后处理，请选择最适宜的三维显示技术并说明其成像特点。", "o": {"A": "采用SSD三维表面重建直观显示颅骨表面形态与凹陷范围", "B": "SSD可同时显示颅内软组织损伤", "C": "SSD使用平均密度投影原理", "D": "SSD主要用于显示血管腔内结构", "E": "SSD的分辨率必然低于横断面原始图像"}, "d": "中", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-131", "kp": "SSD显示颅骨骨折", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (4)SSD", "ex": "【为什么对】颅骨骨折评估需要观察骨表面形态与凹陷范围，SSD通过设定骨阈值提取颅骨表面并加光照阴影，立体显示表面轮廓与凹陷形态，是颅面骨三维重建的经典应用。\n【为什么错】B：SSD阈值分割只显示目标表面结构，不显示颅内软组织。C：SSD是表面阈值提取加光照显示，不是平均密度投影。D：血管腔内显示用MIP/VR或仿真内镜，SSD不用于血管腔。E：SSD的分辨率取决于原始数据，用于表面形态观察有其价值，并非必然低于横断面。", "tr": "SSD=骨表面三维，看颅面骨/关节面；颅内软组织与血管腔不是它的作用对象。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U06-1061", "t": "案例分析题", "s": "某医院放射科拟为设备采购与人员培训提供依据，比较两套DR系统的微小病变显示能力，并评估诊断医师的阅片效能。科室计划从设备物理性能与观察者诊断水平两个层面开展系统评价，前者反映探测器分辨细节的客观物理能力，后者反映医师应用该设备实际检出病变的真实水平，二者评价角度不同、指标各异。请选择适合两个层面的评价指标与方法。", "o": {"A": "用MTF比较两系统的高频细节传递能力，用ROC曲线评估阅片诊断效能", "B": "仅比较显示监视器的尺寸", "C": "用曝光指数比较空间分辨率", "D": "用灰度直方图比较系统分辨率", "E": "用AUC数值代替MTF比较空间分辨率"}, "d": "难", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-110", "kp": "MTF与ROC的选择应用", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】比较系统微小病变（高频细节）显示能力应选用客观物理指标MTF；评估观察者/医师诊断效能应选用ROC曲线（AUC），二者分别从“设备性能”与“诊断水平”两个层面回答该问题，选择正确。\n【为什么错】B：监视器尺寸是显示参数，不代表系统成像性能。C：曝光指数反映剂量水平，与空间分辨率无关。D：灰度直方图反映像素值分布，不评价空间分辨能力。E：AUC是ROC的诊断效能指标，不能代替MTF评价空间分辨率。", "tr": "“设备分辨率”用MTF、“阅片效能”用ROC；AUC≠MTF，指标用途勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U06-1062", "t": "案例分析题", "s": "患者女，50岁，乳腺X线筛查发现右乳外上象限成簇状微小钙化，形态欠规则、分布较散在，需与良性钙化鉴别，同时该区域未见明确肿块影。放射科医师拟启用计算机辅助诊断（CAD）系统辅助阅片，以提高微小钙化簇与肿块检出的敏感性、减少漏诊，同时需要警惕CAD提示的假阳性结果。请分析CAD系统在该例乳腺X线阅片中的正确应用方式。", "o": {"A": "CAD可自动标记可疑微钙化簇与肿块，供医师复核，提高检出敏感度", "B": "CAD可直接确定微钙化的良恶性", "C": "CAD可替代细针穿刺病理活检", "D": "CAD对微钙化检测没有任何辅助作用", "E": "CAD可替代医师直接出具诊断报告"}, "d": "难", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-107", "kp": "CAD乳腺辅助阅片", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (3)乳腺应用", "ex": "【为什么对】CAD对乳腺X线图像的微钙化簇与肿块检测灵敏度高，可自动标记可疑区域供医师复核，作为“第二阅读者”提高检出敏感性、减少漏诊，是乳腺筛查辅助阅片的成熟应用。\n【为什么错】B：CAD只提示可疑，良恶性判定需医师结合影像与病理综合判断。C：CAD不取材，不能替代病理活检。D：CAD对微钙化检测正是其强项。E：CAD输出标记提示，不能替代医师出具诊断报告。", "tr": "乳腺CAD=微钙化/肿块辅助标记＋医师复核；“定良恶、替活检、替诊断”均非CAD功能。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U06-1063", "t": "案例分析题", "s": "患者男，45岁，慢性乙肝肝硬化病史，属肝癌高危人群，行腹部CT三期增强扫描。肝右叶可见可疑低密度病灶，增强后病灶与肝实质密度差仍较小，平扫及动脉期图像上显示欠清，仅门脉期隐约可见边缘强化。技师拟通过窗口技术与后处理调整获得最佳诊断图像，同时评估病灶在肝内的确切空间位置与供血动脉，请选择合适的显示与后处理方案。", "o": {"A": "采用较窄窗宽调节窗位显示肝内低对比病灶，并结合MPR多方位观察病灶空间位置", "B": "窗宽越大，肝内低对比病灶显示越清楚", "C": "MIP适合显示肝实质内低密度病灶", "D": "SSD适合显示肝内占位性病变", "E": "调节窗宽窗位会改变原始像素值"}, "d": "难", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-132", "kp": "肝脏低对比病灶的显示策略", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】肝实质与病灶密度差小（低对比），应选较窄窗宽（如100~200 HU）并调整窗位以提高灰度对比度；同时用MPR从冠状、矢状位观察病灶在肝内位置及与血管、胆管关系，是肝占位评估的合理策略。\n【为什么错】B：窗宽越大单位灰阶CT值跨度越大，低对比病灶对比度反而下降。C：MIP取最大密度，会掩盖低密度病灶。D：SSD显示表面结构，不用于肝实质内占位观察。E：窗宽窗位是显示映射，不改变原始像素值。", "tr": "“低对比病灶用小窗宽”；MIP/SSD不适合肝内低密度病灶，调窗不改原始数据。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U06-9201", "t": "单选题", "s": "计算机辅助诊断（CAD）在影像中的角色是", "o": {"A": "提示疑似病灶，辅助而非替代医师", "B": "直接出具最终诊断", "C": "替代 PACS", "D": "关闭设备", "E": "降低标准"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-9201", "kp": "CAD角色", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD", "ex": "【为什么对】CAD 标注疑似征象供医师参考，最终诊断仍由医师作出。\n【为什么错】CAD 不出最终诊断。", "tr": "CAD仅辅助提示。", "bk": "副高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0101", "t": "单选题", "s": "超急性期脑梗死在DWI上呈高信号、ADC图呈低信号，其最直接的病理生理基础是", "o": {"A": "血管源性水肿使细胞外间隙水分子增多", "B": "钠钾泵功能衰竭导致细胞毒性水肿，水分子由细胞外向细胞内转移，弥散受限", "C": "梗死区血脑屏障破坏使对比剂外渗", "D": "梗死区局部脑血流量增加致灌注过度", "E": "梗死区神经元脱髓鞘使髓鞘含水量下降"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-001", "kp": "超急性期脑梗死DWI-ADC机制", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】B正确：缺血数分钟内ATP耗竭、Na⁺-K⁺-ATP酶失效，细胞外水进入细胞内形成细胞毒性水肿。细胞内水分子受细胞膜与胞内大分子限制，布朗运动受限，故DWI呈高信号、ADC值显著下降（可降至正常的50%~70%），这是最早、最敏感的征象。【为什么错】A错误：血管源性水肿位于细胞外间隙，水分子弥散反而增快，表现为DWI等或高信号但ADC升高，是亚急性期及肿瘤周围水肿的特点。C错误：血脑屏障破坏引起的是增强后强化，脑梗死脑回样强化多出现在3天至数周，与DWI早期高信号无关。D错误：超急性期梗死核心区脑血流量明显下降而非增加；过度灌注多见于再通后。E错误：脱髓鞘是慢性演变结果，与超急性期数分钟内的信号改变无关。", "tr": "务必区分“细胞毒性水肿=ADC降低”与“血管源性水肿=ADC升高”。另需警惕T2透过效应：病灶T2极高时DWI也可呈高信号，但ADC不降低，必须同时读ADC图才能判定真性弥散受限。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0102", "t": "单选题", "s": "急诊MRI发现患者左侧额顶叶DWI明显高信号、ADC降低，而同层面FLAIR序列未见相应高信号。该“FLAIR-DWI不匹配”提示", "o": {"A": "病灶为陈旧性软化灶，非新鲜梗死", "B": "病灶为T2透过效应造成的假阳性", "C": "梗死发病时间很可能在4.5小时以内，属于超急性期", "D": "梗死已进入亚急性晚期，超过7天", "E": "存在大范围缺血半暗带，可据此直接判定取栓适应证"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-002", "kp": "FLAIR-DWI不匹配与发病时间判断", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】C正确：DWI在缺血后数分钟即阳性，而FLAIR反映的是组织净含水量增加，通常需6小时左右才出现高信号。DWI已阳性而FLAIR尚阴性，说明梗死处于极早期，多提示发病在4.5小时内，可为发病时间不明或醒后卒中患者提供静脉溶栓的影像学时间窗依据。【为什么错】A错误：陈旧软化灶ADC升高、FLAIR呈高信号伴中心低信号，与本例相反。B错误：T2透过效应的特征是DWI高而ADC不低，本例ADC已降低，属真性弥散受限。D错误：亚急性晚期FLAIR/T2应为明显高信号，且ADC开始回升甚至假性正常化。E错误：判断缺血半暗带需要DWI与灌注加权（PWI/CTP）的不匹配，FLAIR与DWI的不匹配只反映时间，不等同于半暗带。", "tr": "极易把“FLAIR-DWI mismatch”与“DWI-PWI mismatch”混为一谈：前者用于推断发病时间，后者用于评估可挽救的缺血半暗带。二者的临床决策指向完全不同。", "bk": "副高", "ref": null, "hf": true, "src": "模拟", "mk": 0}, {"id": "U07-0103", "t": "多选题", "s": "关于大脑中动脉供血区急性脑梗死在CT平扫上的早期征象，描述正确的是", "o": {"A": "大脑中动脉高密度征，为动脉内血栓使管腔密度增高", "B": "岛带征，即岛叶皮质与外囊之间灰白质界面模糊消失", "C": "豆状核轮廓模糊、密度减低", "D": "患侧脑沟变浅、脑回肿胀，脑灰白质分界不清", "E": "病灶区呈脑回样明显强化，是最早出现的CT征象"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-003", "kp": "急性脑梗死CT平扫早期征象", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】A正确：大脑中动脉水平段内急性血栓密度可达77~89HU，明显高于对侧，是最早可识别的直接征象。B正确：岛叶皮质对缺血极敏感，其与外囊界面模糊即岛带征。C正确：豆状核由豆纹动脉供血且缺乏侧支，缺血后密度减低、轮廓模糊。D正确：细胞毒性水肿使脑组织肿胀、脑沟变浅、灰白质界面消失，属早期占位效应。【为什么错】E错误：脑回样强化属亚急性期表现，一般在梗死后3天至数周出现，与血脑屏障破坏和侧支再灌注有关，绝非最早征象，且CT平扫不能显示强化。", "tr": "早期CT征象都是“密度差异极小”的间接改变，需要用窄窗（窗宽约30HU、窗位约35HU）的“卒中窗”观察，用常规脑窗容易漏诊。E选项以“最早”与“强化”双重错误设陷。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "急性播散性脑脊髓炎", "页": 46}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0104", "t": "单选题", "s": "脑内血肿发病第5天行MRI检查，血肿在T1WI呈高信号、T2WI呈低信号。该信号组合对应的血红蛋白降解产物是", "o": {"A": "细胞内氧合血红蛋白", "B": "细胞内脱氧血红蛋白", "C": "细胞内正铁血红蛋白（高铁血红蛋白）", "D": "细胞外正铁血红蛋白", "E": "含铁血黄素与铁蛋白"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-004", "kp": "脑出血亚急性早期MRI信号", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】C正确：发病3~7天为亚急性早期，脱氧血红蛋白被氧化为正铁血红蛋白且仍位于完整红细胞内。正铁血红蛋白含5个不成对电子，具有强顺磁性偶极-偶极作用使T1弛豫时间缩短，故T1WI呈高信号；同时红细胞膜内外磁化率差异造成局部磁场不均匀，质子失相位加快，T2WI呈低信号。【为什么错】A错误：氧合血红蛋白为抗磁性，见于超急性期，T1等或稍低、T2高信号。B错误：脱氧血红蛋白见于急性期（1~3天），T1等或稍低、T2明显低信号，不会T1高信号。D错误：细胞外正铁血红蛋白见于亚急性晚期，红细胞已溶解，磁化率不均匀消失，T1与T2均呈高信号。E错误：含铁血黄素见于慢性期，T1、T2均为低信号，以周边环状沉积为特征。", "tr": "亚急性早期与晚期的分水岭是“红细胞膜是否完整”：膜完整则T2低（磁化率效应），膜溶解则T2高。记忆口诀可用“T1先亮、T2后亮”，即T1WI高信号从亚急性早期开始，T2WI高信号到亚急性晚期才出现。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0105", "t": "多选题", "s": "关于脑内血肿各期在1.5T MRI常规SE序列上的信号演变规律，描述正确的是", "o": {"A": "超急性期（<24小时）血肿以氧合血红蛋白为主，T1WI呈等或稍低信号，T2WI呈高信号", "B": "急性期（1~3天）脱氧血红蛋白使T2WI呈明显低信号，T1WI呈等或稍低信号", "C": "亚急性晚期（约8天至1个月）红细胞溶解，细胞外正铁血红蛋白使T1WI与T2WI均呈高信号", "D": "慢性期（1个月以上）血肿周边含铁血黄素沉积，T1WI与T2WI均呈低信号环，SWI显示更敏感", "E": "血肿在各期的CT密度演变与MRI信号演变完全同步，CT亦可据密度准确分期至亚急性早晚期"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-005", "kp": "脑出血MRI信号演变规律", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：超急性期血红蛋白尚未脱氧，呈抗磁性，血肿含水量高故T2WI高信号，T1WI等或稍低。B正确：脱氧血红蛋白有4个不成对电子，位于完整红细胞内造成磁化率不均匀，选择性缩短T2，T2WI呈明显低信号，而其不成对电子不能接近水分子，对T1影响小。C正确：亚急性晚期红细胞溶解，正铁血红蛋白游离于细胞外，磁化率梯度消失、蛋白水化层缩短T1，故T1、T2双高信号。D正确：慢性期巨噬细胞吞噬铁形成含铁血黄素，超顺磁性造成T1、T2均低的含铁血黄素环，SWI/T2*对其最敏感，可长期存在。【为什么错】E错误：CT密度演变与MRI并不同步。CT上急性血肿为高密度，随蛋白降解密度逐渐下降，约2~4周变为等密度、之后为低密度，无法区分细胞内外正铁血红蛋白阶段，故CT不能像MRI那样细分亚急性早、晚期。", "tr": "陷阱在于把CT与MRI的分期能力等同。CT在等密度期（约2~4周）反而最易漏诊，此时MRI T1WI高信号最醒目；反之超急性期CT敏感而MRI信号最不特异，二者优势互补。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-0106", "t": "案例分析题", "s": "患者男性，74岁，高血压病史不详，2年内反复发作短暂性肢体无力，近1周出现明显认知功能下降与近记忆减退。急诊CT平扫示右侧顶叶脑叶区一约2cm高密度血肿，血肿周围水肿轻微，基底节区未见陈旧腔隙灶。既往因房颤长期服用抗凝药物。临床怀疑脑淀粉样血管病所致脑叶出血，需评估脑内是否存在多发微出血灶及皮层表面铁沉积，据此判断继续抗栓治疗的出血风险。本院配置3.0T MR，患者神志清楚、可配合屏气与制动，无金属植入物。作为技师，此时最应加扫的序列及其成像原理是", "o": {"A": "加扫磁敏感加权成像（SWI/SWAN/VenoBOLD），利用含铁血黄素的磁化率效应产生相位差与信号丢失，对微出血最敏感", "B": "加扫T2WI快速自旋回波（TSE/FSE），因自旋回波的180°脉冲可放大磁化率效应", "C": "加扫DWI高b值成像，微出血灶在高b值下呈明显高信号", "D": "加扫T1WI增强扫描，微出血灶因血脑屏障破坏而明显强化", "E": "加扫三维时间飞跃法MRA（3D-TOF MRA），可直接显示皮层微小出血灶"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-006", "kp": "脑微出血检出的序列选择", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：SWI为三维扰相梯度回波长TE序列，同时利用幅值图与相位图信息，对含铁血黄素、脱氧血红蛋白等顺磁性物质的磁化率差异极为敏感，微出血呈边界清楚的圆点状极低信号并有“开花效应”，检出率显著高于常规T2*GRE与T2WI；3.0T场强下磁化率效应更强，更利于显示脑叶分布的微出血及皮层表面铁沉积。【为什么错】B错误：自旋回波的180°复相脉冲恰恰是用来补偿主磁场不均匀与磁化率失相位的，会削弱而非放大磁化率效应，TSE/FSE对微出血最不敏感。C错误：陈旧微出血无弥散受限，DWI并不敏感，且高b值图像信噪比低、易受磁敏感伪影干扰。D错误：陈旧微出血为含铁血黄素沉积，无活动性血脑屏障破坏，不强化；且对74岁患者不必要地使用钆对比剂增加风险。E错误：3D-TOF MRA显示的是流动血液信号，用于评估动脉狭窄或动脉瘤，不能显示实质内微出血。", "tr": "考点落在“序列物理原理决定征象显示”：磁化率效应需要梯度回波（无180°复相脉冲）+长TE才能充分演化。把SWI与DWI、T2*与T2混淆是常见失分点。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "总论", "节": "头颅MR检查方法及各序列的应用", "页": 12}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0107", "t": "单选题", "s": "关于脑膜瘤的典型影像学表现，下列描述错误的是", "o": {"A": "CT平扫多呈边界清楚的稍高密度肿块，约20%可见钙化", "B": "增强扫描多呈明显均匀强化，邻近硬膜可见“脑膜尾征”", "C": "可见白质塌陷征与脑脊液裂隙征，提示肿瘤位于脑实质外", "D": "邻近颅骨可出现骨质增生硬化", "E": "T2WI上肿瘤实质多呈显著高信号且伴瘤内液平，为脑膜瘤的定性依据"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-007", "kp": "脑膜瘤影像诊断要点", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】E为错误描述，故为本题答案：脑膜瘤细胞排列致密、含水量相对低，T2WI多呈等或稍高信号，与灰质相仿；显著高信号伴瘤内液平并非脑膜瘤特征，更提示囊性病变或血管母细胞瘤等。T2WI信号可提示亚型（纤维型偏低、血管瘤型偏高），但不能作为定性依据。【为什么错】A描述正确：脑膜瘤富含细胞与砂粒体，CT平扫多为稍高密度，钙化率约20%~25%。B描述正确：肿瘤血供丰富且无血脑屏障，强化明显均匀；脑膜尾征为邻近硬膜反应性增厚或肿瘤浸润所致，是重要但非特异征象。C描述正确：白质塌陷征（肿瘤压迫使皮层下白质向内推移）与脑脊液裂隙征均为脑外肿瘤定位征象。D描述正确：颅骨可出现增生硬化，少数为侵蚀破坏。", "tr": "本题为反向提问（选“错误”），审题不清易失分。另需牢记：脑膜尾征也可见于转移瘤、淋巴瘤、结核性脑膜炎，不能单凭尾征确诊脑膜瘤。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "脑膜炎", "页": 40}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0108", "t": "多选题", "s": "颅内单发环形强化病灶，需在高级别胶质瘤与脑转移瘤之间鉴别。下列有助于鉴别的影像学依据是", "o": {"A": "高级别胶质瘤瘤周异常T2/FLAIR高信号区内常含肿瘤细胞浸润，MRS示该区胆碱（Cho）峰升高、N-乙酰天门冬氨酸（NAA）峰下降", "B": "转移瘤瘤周多为单纯血管源性水肿，瘤周区相对脑血容量（rCBV）不升高", "C": "转移瘤多位于灰白质交界区，常呈“小病灶、大水肿”", "D": "高级别胶质瘤常沿胼胝体或白质纤维束跨中线蔓延生长", "E": "两者的强化环壁厚度与规整度完全一致，环形强化本身即可确诊转移瘤"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-008", "kp": "高级别胶质瘤与转移瘤鉴别", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：胶质瘤呈浸润性生长，强化灶外的“水肿区”实为肿瘤浸润带，MRS呈Cho升高、NAA降低、Cho/NAA比值增大。B正确：转移瘤为膨胀性生长且瘤周无肿瘤细胞，灌注成像上瘤周rCBV不升高，此为与胶质瘤鉴别的重要定量指标。C正确：血行转移瘤易停留于灰白质交界区末梢小血管处，病灶小而水肿广泛。D正确：胶质瘤沿白质纤维束蔓延，跨胼胝体生长形成“蝴蝶征”，转移瘤罕有此表现。【为什么错】E错误：两者强化环形态确有差别（胶质瘤环壁多厚薄不均、内缘不规则；转移瘤环壁相对较薄且规整），且环形强化的鉴别诊断还包括脓肿、脱髓鞘、放射性坏死等，单凭环形强化不能确诊任何一种。", "tr": "“瘤周水肿区的灌注与波谱”是区分浸润性与膨胀性生长的核心思路，比单纯看强化形态更可靠。E以“完全一致”“即可确诊”双重绝对化措辞设陷。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "肿瘤和肿瘤样病变", "节": "转移性肿瘤", "页": 79}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0109", "t": "单选题", "s": "颅内囊性病灶伴环形强化，欲鉴别脑脓肿与囊变坏死性肿瘤，最具价值的序列及其表现是", "o": {"A": "DWI上脓腔呈明显高信号、ADC值降低；肿瘤囊变区DWI呈低信号、ADC值升高", "B": "DWI上脓腔呈低信号、ADC值升高；肿瘤囊变区DWI呈高信号、ADC值降低", "C": "T1WI平扫，脓腔呈高信号而肿瘤囊变区呈低信号", "D": "3D-TOF MRA，脓肿壁可见异常血管团", "E": "MRA源图像，脓腔内可见流空信号"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-009", "kp": "脑脓肿DWI鉴别诊断", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：脓液由坏死碎屑、大量炎性细胞与高浓度蛋白构成，黏稠度高，水分子弥散显著受限，故DWI呈明显高信号、ADC值降低（多低于1.0×10⁻³mm²/s）；而肿瘤囊变坏死区为稀薄液体，水分子自由弥散，DWI低信号、ADC升高。此为二者最可靠的鉴别点，准确率约90%以上。【为什么错】B错误：信号描述完全颠倒。C错误：脓腔T1WI多为低或稍高信号，与肿瘤囊变区重叠明显，无鉴别价值。D错误：MRA显示的是血流，脓肿壁虽富血供但不形成MRA可见的异常血管团，此为动静脉畸形的表现。E错误：脓腔内为黏稠脓液，无血流，不会出现流空信号。", "tr": "补充记忆：脓肿壁在T2WI上常呈完整、光滑的低信号环，且靠脑室侧较薄（易破入脑室）；MRS可检出醋酸盐、琥珀酸盐及氨基酸峰，为脓肿特有。若脓肿经抗生素治疗后，DWI高信号可减弱，需结合临床。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "脑脓肿", "页": 40}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0110", "t": "多选题", "s": "关于多发性硬化（MS）的MRI表现，描述正确的是", "o": {"A": "侧脑室周围病灶长轴多垂直于侧脑室壁排列，即“Dawson手指征”", "B": "矢状面FLAIR显示胼胝体-透明隔交界面受累，对早期诊断有较高特异性", "C": "活动期病灶可呈开环样或不完整环形强化，开口多朝向皮层灰质侧", "D": "脊髓病灶多较短，纵向范围一般小于2个椎体节段，横断面上常不超过脊髓横截面的一半", "E": "所有MS病灶在增强扫描时均呈明显强化，强化与否与病程无关"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-010", "kp": "多发性硬化MRI诊断要点", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：脱髓鞘沿深髓静脉周围分布，故病灶长轴与侧脑室壁垂直呈指状。B正确：胼胝体下缘与透明隔交界处受累在其他脑白质病变中少见，矢状面FLAIR是显示该征象的最佳方位。C正确：开环强化为MS较具特征的表现，环的开口朝向皮层灰质侧，因灰质侧炎症反应较轻。D正确：MS脊髓病灶短节段、偏心、位于后索或侧索，可与视神经脊髓炎谱系病（纵向广泛，≥3个椎体节段）鉴别。【为什么错】E错误：只有活动期（血脑屏障破坏期，约持续2~8周）病灶才强化，陈旧斑块不强化。强化与否恰恰是判断病灶“时间多发性”与疾病活动度的关键依据。", "tr": "E以“所有”“均”“与病程无关”设置绝对化陷阱。实际上MS诊断的McDonald标准正是依靠强化与非强化病灶并存来同时满足空间多发与时间多发。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "多发性硬化", "页": 45}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0111", "t": "单选题", "s": "单纯疱疹病毒性脑炎最典型的病变累及部位是", "o": {"A": "双侧基底节区与丘脑", "B": "颞叶内侧、岛叶及扣带回，常不累及豆状核", "C": "双侧小脑半球与脑干", "D": "双侧顶枕叶皮层下白质", "E": "脑室周围白质与半卵圆中心"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-011", "kp": "单纯疱疹病毒性脑炎影像定位", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】B正确：单纯疱疹病毒经三叉神经或嗅神经逆行侵入边缘系统，特征性累及颞叶内侧（海马、杏仁核）、岛叶皮质、扣带回及额叶眶面，多为双侧但不对称。病变与豆状核之间界限清楚，呈“刀切样”边缘，是重要鉴别征象。FLAIR与DWI最敏感，可早于CT数天出现异常。【为什么错】A错误：双侧基底节与丘脑对称受累更提示深部静脉血栓、一氧化碳中毒、代谢性或某些病毒性脑炎（如日本脑炎）。C错误：小脑与脑干受累提示菱脑炎（如李斯特菌）或急性小脑炎。D错误：顶枕叶皮层下白质对称水肿是可逆性后部脑病综合征（PRES）的典型分布。E错误：脑室周围白质与半卵圆中心受累多见于脱髓鞘病变、缺血性白质病变或进行性多灶性白质脑病。", "tr": "“豆状核不受累”是单纯疱疹病毒性脑炎与大脑中动脉梗死鉴别的关键——后者岛叶与豆状核可同时受累且符合血管分布区。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "单纯疱疹病毒脑炎", "页": 39}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0112", "t": "案例分析题", "s": "患者男性，62岁，工作中突发右侧肢体偏瘫伴完全性失语3小时，急诊NIHSS评分16分，既往房颤病史，血压162/95mmHg。急诊CT平扫未见颅内出血，隐约可见左侧岛带征，脑沟稍变浅。卒中中心需在最短时间内同时回答两个问题：是否存在颅内大血管急性闭塞，以及核心梗死灶与缺血半暗带各占多大范围，据此决定是否启动血管内取栓。科室配置256排CT，患者躁动明显、难以长时间保持制动，肾功能正常，无碘对比剂过敏史。作为技师，最合理的检查技术方案是", "o": {"A": "在CT平扫基础上一站式完成头颈CT血管成像（CTA）加全脑CT灌注成像（CTP），由CTP的CBF与Tmax参数图判断核心梗死区与半暗带", "B": "先送MRI行DWI加PWI评估，因MRI对早期梗死更敏感，时间成本可以忽略", "C": "仅重复CT平扫观察低密度是否加重，无需血管与灌注评估", "D": "行常规头部CT增强扫描，通过实质强化程度判断半暗带范围", "E": "直接行DSA全脑血管造影，兼顾诊断与治疗，无需任何无创性影像评估"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-012", "kp": "急性卒中一站式CT检查方案", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】A正确：CT平扫排除出血、CTA明确大血管闭塞部位与侧支循环、CTP量化核心梗死区与半暗带，三者可在一次静脉团注下一站式完成，总耗时通常不超过10分钟，且对躁动患者的耐受性远优于MRI。判读上通常以脑血流量（CBF）低于对侧30%的区域估算核心梗死区，以达峰时间残差（Tmax）大于6秒的区域估算低灌注区，二者之差即缺血半暗带。【为什么错】B错误：MRI检查前需筛查金属禁忌、扫描时间长、对躁动患者运动伪影严重，急诊卒中绿色通道中会显著延误再灌注时间。C错误：单纯重复平扫无法提供血管与灌注信息，不能支持取栓决策，且延误时间窗。D错误：常规增强扫描只反映血脑屏障与血管内对比剂总量，无时间-密度曲线，无法计算CBF、CBV、MTT、Tmax等灌注参数。E错误：DSA为有创操作，不应在无创筛查前盲目实施；且DSA只显示血管，不能直接评估脑组织灌注状态。", "tr": "关键在于区分“增强扫描”与“灌注成像”：前者是单期或多期形态学成像，后者是同层面连续动态采集并经数学模型计算得到参数图。二者对比剂用法、扫描逻辑与临床用途完全不同。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "急性播散性脑脊髓炎", "页": 46}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0113", "t": "单选题", "s": "甲状腺相关眼病（Graves眼病）在CT与MRI上最具特征性的表现是", "o": {"A": "眼外肌肌腹梭形增粗而肌腱附着点不受累，多为双侧、以下直肌和内直肌最先受累", "B": "眼外肌肌腹与肌腱同时增粗，边缘模糊", "C": "泪腺弥漫增大伴眼睑肿胀，眼外肌正常", "D": "球后脂肪内孤立强化肿块，推压视神经移位", "E": "眼球壁广泛增厚并伴巩膜后水肿"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-013", "kp": "Graves眼病影像诊断要点", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】A正确：Graves眼病为自身免疫性炎症，糖胺聚糖沉积于眼外肌肌腹的肌纤维间隙，而肌腱附着点缺乏此类间质反应，故呈典型“肌腹增粗、肌腱不受累”的梭形改变。受累顺序常记作下直肌、内直肌、上直肌、外直肌，多双侧不对称，眶尖肌肉拥挤可致压迫性视神经病变。【为什么错】B错误：肌腹与肌腱同时增粗、边缘模糊是眼眶炎性假瘤（特发性眼眶炎性病变）的特点，且多为单侧、疼痛明显、对激素反应好。C错误：泪腺弥漫增大为泪腺炎型炎性假瘤或IgG4相关病变表现。D错误：球后孤立强化肿块提示海绵状血管瘤或神经鞘瘤等占位。E错误：眼球壁广泛增厚伴巩膜后水肿见于巩膜炎型炎性假瘤。", "tr": "“肌腱是否受累”是Graves眼病与炎性假瘤的分水岭，也是命题最集中的一点。技术上应采用横断面加冠状面薄层（层厚≤2mm），冠状面能同时对比四条直肌粗细，是评估眶尖拥挤的必需方位。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0114", "t": "多选题", "s": "关于眼眶病变的影像检查与征象分析，下列描述正确的是", "o": {"A": "眼眶炎性假瘤在T2WI上常呈等或低信号，与病灶内纤维成分较多有关", "B": "眼眶海绵状血管瘤动态增强呈“渐进性强化”，即由点状强化逐渐向整个病灶扩展填充", "C": "怀疑眶内金属异物时应先行X线平片或CT，不宜首选MRI", "D": "评估视神经病变时应采用脂肪抑制T2WI与脂肪抑制T1WI增强，以消除眶内脂肪高信号的掩盖", "E": "眼眶CT扫描时冠状面重建对判断眶壁骨折（如眶底爆裂骨折）价值有限，横断面已足够"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-014", "kp": "眼眶病变影像检查技术与征象", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】A正确：炎性假瘤含大量纤维结缔组织，自由水少，T2WI呈等或低信号，此点可与含水量高的淋巴瘤、血管瘤区分。B正确：海绵状血管瘤内血窦血流缓慢，对比剂缓慢充盈，表现为“渐进性强化”，延迟期充填均匀，是其定性征象。C正确：眶内金属异物在磁场中可能移位造成眼球损伤，属MRI禁忌，必须先用X线平片或CT筛查。D正确：眶内脂肪T1、T2均为高信号，会掩盖病灶与视神经异常信号，脂肪抑制技术是眼眶MRI的基本要求。【为什么错】E错误：眶底与眶内壁为水平走行结构，横断面上呈平行于扫描层面的方向，容易漏诊；冠状面（或冠状位重建）是显示眶底爆裂骨折、下直肌疝入上颌窦的最佳方位。", "tr": "E的陷阱在于忽视“骨壁走行方向与扫描平面平行时易漏诊”的通则。技师应用层面：眶部CT应采集各向同性薄层容积数据，以便任意方位重建。", "bk": "副高", "ref": {"篇": "头颈部", "章": "眼眶病变", "节": "先天异常", "页": 91}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-0115", "t": "单选题", "s": "真菌性鼻窦炎（真菌球型）在CT与MRI上最具提示意义的表现是", "o": {"A": "CT示窦腔内软组织影中见斑点状或条片状高密度钙化，MRI T2WI呈极低信号甚至近似无信号", "B": "CT示窦腔内均匀低密度，MRI T1WI低、T2WI明显高信号", "C": "CT示窦壁广泛虫蚀样骨质破坏，MRI呈均匀明显强化", "D": "CT示窦腔完全含气，仅黏膜轻度增厚", "E": "CT示窦腔内脂肪密度，MRI脂肪抑制后信号明显下降"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-015", "kp": "真菌性鼻窦炎影像特征", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】A正确：真菌球内含钙盐、铁、镁、锰等重金属及菌丝，CT表现为窦腔（好发上颌窦）内不均匀软组织密度中夹杂点、条状高密度钙化，窦壁可增生硬化。MRI上因顺磁性金属与含水量极低，T2WI呈极低信号甚至“信号缺失”，易被误认为窦腔含气，必须与CT对照。【为什么错】B错误：均匀低密度伴T2明显高信号是普通潴留囊肿或黏液潴留的表现。C错误：广泛虫蚀样骨破坏提示侵袭性真菌感染或恶性肿瘤，非典型真菌球型。D错误：窦腔含气、黏膜轻度增厚为轻度慢性炎症。E错误：窦腔内脂肪密度极为罕见，见于脂肪瘤或术后填塞材料。", "tr": "最大的陷阱是“MRI T2极低信号被误读为正常含气窦腔”而漏诊。凡MRI提示鼻窦“空虚”而临床有症状者，必须加做CT骨算法观察有无高密度钙化。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0116", "t": "案例分析题", "s": "患者男性，48岁，反复回吸性血涕3个月，伴左耳闷堵感与听力下降，查体见左侧颈部Ⅱ区一枚约2cm质硬淋巴结。鼻咽镜见左侧咽隐窝饱满、黏膜隆起，活检病理证实为非角化型鼻咽癌。临床需明确肿瘤是否侵犯颅底斜坡骨髓、破裂孔、翼腭窝及海绵窦，并评估颈部各区淋巴结转移情况，以完成精确临床分期与放疗靶区勾画。患者无幽闭恐惧，无心脏起搏器等MRI禁忌证，肾功能正常。作为技师，下列检查技术安排最合理的是", "o": {"A": "以鼻咽部薄层高分辨T2WI结合脂肪抑制T1WI增强（横断面加冠状面）为核心，扫描范围上至鞍上池、下至锁骨上窝", "B": "仅行鼻咽部CT平扫，因CT显示骨皮质优于MRI，足以判断颅底骨髓侵犯", "C": "仅行鼻咽部MRI平扫，不使用对比剂，以避免钆剂不良反应", "D": "行头颅常规MRI序列（层厚6mm），范围自颅顶至颅底即可", "E": "行鼻咽部CT增强，扫描范围仅覆盖鼻咽腔上下各2cm"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-016", "kp": "鼻咽癌MRI检查技术与分期评估", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】A正确：正常斜坡骨髓因含脂肪在T1WI呈高信号，肿瘤侵犯后被替代为低信号，故平扫T1WI是判断颅底骨髓侵犯最敏感的序列；脂肪抑制T1WI增强则用于显示强化的肿瘤与神经周围侵犯、海绵窦受累。冠状面对显示颅底孔道与颅内侵犯尤为重要。范围必须上至鞍上池（评估海绵窦、颅内侵犯）、下至锁骨上窝（评估颈部各区淋巴结），这是鼻咽癌分期的标准要求。【为什么错】B错误：CT显示骨皮质破坏敏感，但对尚未破坏皮质的骨髓浸润不敏感，会造成分期偏低。C错误：不使用对比剂无法准确判断海绵窦侵犯、神经周围播散及肿瘤与炎症的分界。D错误：层厚6mm且范围不含颈部，既漏掉小病灶细节又漏掉淋巴结分期。E错误：范围过小必然遗漏颅底与颈部淋巴结，且CT对软组织分辨率不及MRI。", "tr": "记住一条规律：“T1WI平扫看骨髓，脂肪抑制T1WI增强看侵犯范围”。若在增强后直接加脂肪抑制而不保留平扫T1WI，会失去判断骨髓脂肪被替代的基线，是实际工作中的常见失误。", "bk": "副高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "鼻咽部病变", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0117", "t": "单选题", "s": "关于中耳胆脂瘤的影像诊断，下列描述最准确的是", "o": {"A": "颞骨HRCT示上鼓室Prussak间隙软组织影伴听小骨吸收、盾板变钝，非回波平面DWI呈高信号", "B": "颞骨HRCT示鼓室内软组织影伴听小骨完整，增强后明显强化", "C": "颞骨HRCT示乳突小房密度增高但骨间隔完整，MRI T2WI低信号", "D": "颞骨HRCT示内听道扩大伴其内软组织结节，增强明显强化", "E": "颞骨HRCT示颈静脉孔区骨质呈虫蚀样破坏，MRI见“胡椒盐征”"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-017", "kp": "中耳胆脂瘤影像诊断要点", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】A正确：后天原发性胆脂瘤起自上鼓室外侧隐窝（Prussak间隙），HRCT表现为该处软组织团块伴锤骨头、砧骨长脚吸收破坏，盾板（scutum）变钝或消失，上鼓室膨大，可破坏鼓室盾板、面神经管及外半规管。胆脂瘤基质角化物弥散明显受限，在非回波平面DWI（non-EPI DWI）上呈高信号，是术前定性与术后复发判断的关键序列。【为什么错】B错误：胆脂瘤本身为角化物堆积，无血供，增强不强化（周围肉芽组织可边缘强化），且听小骨常被破坏。C错误：乳突小房密度增高但骨间隔完整为单纯乳突炎表现。D错误：内听道扩大伴强化结节是听神经瘤表现。E错误：颈静脉孔区虫蚀样骨破坏伴“胡椒盐征”是颈静脉球瘤（副神经节瘤）的典型表现。", "tr": "关键技术点：常规回波平面DWI在颞骨区受气骨界面磁敏感伪影严重干扰，会产生假高信号，必须使用非回波平面（如HASTE/BLADE基础的）DWI才可靠。“胆脂瘤不强化、肉芽组织强化”亦是常考鉴别点。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0118", "t": "多选题", "s": "关于甲状腺乳头状癌及其颈部转移淋巴结的CT/MRI表现，描述正确的是", "o": {"A": "原发灶多呈边界不清的低密度结节，其内可见细小砂粒样钙化", "B": "增强扫描原发灶强化程度低于周围正常甲状腺组织，可见“咬饼征”样边缘缺损", "C": "转移淋巴结可发生囊变，其内可含胶质而在T1WI呈高信号", "D": "转移淋巴结可出现细颗粒状钙化并明显强化", "E": "凡甲状腺结节内出现钙化即为恶性征象，粗大环形钙化的恶性风险高于微钙化"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-018", "kp": "甲状腺癌与颈部转移淋巴结影像特征", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】A正确：乳头状癌呈浸润性生长，边界不清，其内砂粒体形成细小点状钙化。B正确：正常甲状腺富含碘，平扫即为高密度且增强显著；癌灶不摄碘、血供相对少，故强化程度低于腺体，与包膜接触处可呈“咬饼样”缺损。C正确：乳头状癌转移淋巴结特征性囊变，含甲状腺球蛋白等胶质成分，T1WI可呈高信号。D正确：转移淋巴结内可见细颗粒状钙化并明显强化，与鳞癌转移淋巴结的坏死性低强化不同。【为什么错】E错误：钙化并非恶性特有，结节性甲状腺肿常有粗大或环形钙化；恶性风险更高的是微钙化（砂粒样），而粗大、环形完整的钙化多提示良性。", "tr": "E将钙化风险等级完全说反，并用“凡……即为”的绝对化措辞。技术层面注意：碘对比剂增强会干扰后续¹³¹I治疗与摄碘评估，检查前需与临床沟通。", "bk": "副高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "颈部囊性病变", "页": 107}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0119", "t": "单选题", "s": "按影像学颈部淋巴结分区标准，位于舌骨体下缘至环状软骨下缘之间、颈内静脉链周围的淋巴结属于", "o": {"A": "Ⅰ区", "B": "Ⅱ区", "C": "Ⅲ区", "D": "Ⅳ区", "E": "Ⅵ区"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-019", "kp": "颈部淋巴结影像学分区", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】C正确：影像学分区以骨性与软骨标志划界，Ⅲ区（颈内静脉中组）上界为舌骨体下缘、下界为环状软骨下缘，前界为胸骨舌骨肌外缘，后界为胸锁乳突肌后缘。【为什么错】A错误：Ⅰ区为颏下（ⅠA）与颌下（ⅠB）区，位于舌骨体上缘、下颌下腺后缘以前。B错误：Ⅱ区（颈内静脉上组）上界为颅底、下界为舌骨体下缘，以副神经为界分ⅡA与ⅡB。D错误：Ⅳ区自环状软骨下缘至锁骨上缘。E错误：Ⅵ区为中央区，位于舌骨与胸骨上切迹之间、两侧颈总动脉内侧，含气管前与气管旁淋巴结。", "tr": "务必用“舌骨体下缘”和“环状软骨下缘”这两个横断面可辨的标志区分Ⅱ、Ⅲ、Ⅳ区。临床解剖分区（以肩胛舌骨肌为界）与影像学分区标志不同，考试以影像学标志为准。", "bk": "副高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "颈部囊性病变", "页": 107}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0120", "t": "单选题", "s": "上颌窦腔完全被病变充填，欲鉴别慢性炎症潴留物与实体肿瘤，MRI上最有价值的判断依据是", "o": {"A": "潴留分泌物T2WI呈明显高信号且增强后不强化，肿瘤实质T2WI多呈中等信号且明显强化", "B": "潴留分泌物T2WI呈低信号，肿瘤T2WI呈高信号", "C": "两者T1WI信号相同，故只能依靠CT判断", "D": "潴留分泌物增强后明显均匀强化，肿瘤不强化", "E": "只需观察窦腔是否扩大，扩大者必为肿瘤"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-020", "kp": "鼻窦炎症与肿瘤的MRI鉴别", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】A正确：炎性潴留物含水量高，T2WI呈明显高信号，本身无血供故增强后不强化，仅周边黏膜呈线状强化；肿瘤细胞密集、含水相对少，T2WI呈中等（介于肌肉与液体之间）信号且增强后实质强化。因此增强脂肪抑制T1WI能清晰勾勒“强化的肿瘤”与“不强化的阻塞性分泌物”的分界，这是MRI优于CT的核心价值。【为什么错】B错误：信号描述颠倒；T2低信号更提示真菌球或高蛋白浓缩分泌物。C错误：T1WI信号确有重叠，但T2WI与增强能有效鉴别，并非只能靠CT。D错误：强化关系完全说反。E错误：慢性炎症（如黏液囊肿）也可使窦腔膨胀扩大、窦壁受压变薄，扩大并非肿瘤特有；肿瘤更倾向骨质虫蚀样破坏。", "tr": "CT上炎症与肿瘤同为软组织密度、常难区分，而MRI的T2信号差异与强化差异是分界关键。临床工作中常需CT（看骨质）与MRI（看软组织范围）互补，不可偏废。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0121", "t": "单选题", "s": "大叶性肺炎实变期胸片与CT上出现“空气支气管征”，其病理基础是", "o": {"A": "肺泡腔被渗出液充填而支气管腔内仍含气，在高密度实变背景中衬托出含气支气管", "B": "支气管壁增厚并伴管腔扩张", "C": "肺泡壁破坏融合形成肺大疱", "D": "支气管腔内被黏液栓完全阻塞", "E": "胸膜腔内游离气体沿支气管走行分布"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-021", "kp": "空气支气管征的病理基础", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：大叶性肺炎实变期肺泡内充满纤维素性渗出液，密度升高，而各级支气管本身未被阻塞、腔内仍含气，于是在均匀高密度实变区内显示为树枝状或管状透亮影，即空气支气管征。该征象说明病变位于肺泡腔而非支气管内阻塞性改变，是肺炎、肺水肿、部分肺泡型肺癌的共同征象。【为什么错】B错误：支气管壁增厚伴扩张为支气管扩张症的“印戒征”“轨道征”。C错误：肺大疱为薄壁含气腔，周围无实变背景。D错误：黏液栓完全阻塞时表现为“指套征”并常伴远端肺不张，恰恰不会出现空气支气管征。E错误：胸膜腔游离气体为气胸，位于胸膜腔而非支气管内。", "tr": "阻塞性肺不张与肺炎实变的关键区别之一即空气支气管征的有无——中央型肺癌所致阻塞性肺不张一般不出现该征象，若在“不张”影内见到空气支气管征，应重新考虑是否为实变。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0122", "t": "多选题", "s": "关于肺结核各型的影像学表现，描述正确的是", "o": {"A": "原发综合征表现为肺内原发病灶、淋巴管炎与肺门/纵隔淋巴结肿大，呈“哑铃状”改变", "B": "急性血行播散型肺结核呈两肺弥漫粟粒结节，具有分布均匀、大小均匀、密度均匀的“三均匀”特点", "C": "继发性肺结核好发于上叶尖后段与下叶背段，常呈渗出、增殖、纤维、钙化、空洞多形态并存", "D": "结核球多小于3cm，边缘光滑，可有环状或斑点状钙化，周围常见卫星灶", "E": "结核性空洞多为偏心厚壁空洞、内壁凹凸不平并见壁结节"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-022", "kp": "肺结核分型影像表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：原发灶、引流淋巴管炎与肿大的肺门淋巴结共同构成原发综合征的哑铃状表现。B正确：急性血行播散型由结核菌一次性大量入血形成，故粟粒结节的分布、大小、密度三方面均匀，为其经典描述。C正确：继发性肺结核好发于上叶尖后段与下叶背段（通气好、血流相对少、淋巴引流慢），影像上“多形态、多阶段病灶并存”是重要特征。D正确：结核球为纤维包裹的干酪坏死灶，边缘光滑，钙化多呈环状或斑点状，周围卫星灶具重要提示价值。【为什么错】E错误：偏心厚壁、内壁凹凸不平伴壁结节是癌性空洞的特征；结核性空洞多为薄壁或壁较均匀、内壁光滑，周围伴卫星灶与引流支气管。", "tr": "空洞鉴别是高频考点：结核空洞薄壁光滑加卫星灶；癌性空洞偏心厚壁加壁结节；肺脓肿厚壁但内壁光滑、常见气液平且周围渗出明显。", "bk": "副高", "ref": {"篇": "胸部", "章": "肺感染", "节": "肺结核", "页": 127}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0123", "t": "单选题", "s": "右上叶中央型肺癌导致右上叶肺不张时，胸片上肺门肿块与上抬的水平裂共同形成的典型征象称为", "o": {"A": "空气新月征", "B": "反“S”征（Golden S征）", "C": "银币征", "D": "颈胸征", "E": "肺门舞蹈征"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-023", "kp": "中央型肺癌反S征", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】B正确：右上叶不张使水平裂外侧段向上向内移位呈凹面向下，而肺门处肿块使内侧段向下膨隆呈凸面向下，二者相连形成横置的反“S”形，称Golden S征，是中央型肺癌伴阻塞性肺不张的经典X线征象。【为什么错】A错误：空气新月征指空洞或曲霉球与洞壁间的新月形气体影，见于肺曲霉病、坏死性肺炎。C错误：银币征（硬币征）指侧位片上叶间积液呈梭形致密影。D错误：颈胸征用于判断纵隔肿块位置——肿块上缘超过锁骨水平仍清晰可见者位于后纵隔。E错误：肺门舞蹈是透视下肺门血管搏动增强的动态表现，见于左向右分流型先心病，非形态学征象。", "tr": "反S征的核心含义是“不张（体积缩小）＋肺门肿块（体积增大）”并存，提示不张由中央阻塞性病变引起，与单纯炎性不张不同。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0124", "t": "案例分析题", "s": "患者男性，58岁，吸烟史30年，咳嗽伴痰中带血1个月。常规胸部CT平扫（层厚5mm）示右肺上叶一约2.2cm结节，边缘似有分叶，与胸膜关系欠清，结节内密度不均。临床需要明确该结节的边缘形态、有无空泡征与胸膜凹陷征，并评估其强化特点以判断良恶性。患者肾功能正常、无碘对比剂过敏史。作为技师，下列技术方案最恰当的是", "o": {"A": "采用薄层（≤1mm）高分辨重建加靶重建观察边缘细节，并行同层动态增强扫描测量结节强化幅度与时间-密度曲线", "B": "重复5mm层厚平扫并加大窗宽观察，无需薄层重建", "C": "直接行胸部X线正侧位片补充观察边缘征象", "D": "仅行胸部MRI T2WI，因MRI软组织分辨率高于CT，可替代薄层CT评估结节边缘", "E": "行胸部CT平扫加延迟5分钟单期扫描，以延迟强化程度判断良恶性"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-024", "kp": "肺结节薄层与动态增强技术选择", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：分叶、毛刺、空泡、胸膜凹陷、血管集束等细微征象的显示高度依赖空间分辨率，5mm层厚存在明显部分容积效应，必须用亚毫米薄层加高分辨（骨/肺算法）靶重建。孤立性肺结节动态增强是评价血供的成熟方法：注药后每分钟采集同层图像，强化峰值增幅小于约15HU多提示良性，15~20HU以上并呈快速强化后平台或流出型曲线者恶性可能大。【为什么错】B错误：加大窗宽不能弥补层厚造成的部分容积效应，细微边缘征象仍无法显示。C错误：胸片密度分辨率与空间定位能力远不及CT，无法评估2cm结节的边缘细节。D错误：肺内空气与组织磁化率差异大、呼吸运动明显，MRI对肺实质细微结构显示不如CT，不能替代薄层CT。E错误：单一延迟期无法获得时间-密度曲线，无法区分快进快出与渐进强化模式，信息量严重不足。", "tr": "本题体现“征象识别依赖采集技术”的命题思路：层厚决定能否看到毛刺与空泡，扫描时相决定能否判读强化模式。仅凭平扫或单期增强下结论是实际工作中的常见错误。", "bk": "副高", "ref": {"篇": "胸部", "章": "肺感染", "节": "肺结核", "页": 127}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0125", "t": "案例分析题", "s": "患者女性，66岁，全髋关节置换术后第5天，卧床期间突发胸痛、呼吸困难，心率112次/分，血氧饱和度88%，血浆D-二聚体显著升高，右下肢较对侧明显肿胀。临床高度怀疑急性肺栓塞，急诊申请CT肺动脉造影（CTPA），要求明确肺动脉主干及各叶段分支有无栓子并评估右心负荷。患者呼吸急促、屏气不足8秒，无法长时间配合，血肌酐正常，无碘对比剂过敏史，静脉通路为右肘正中静脉18G留置针。作为技师，下列扫描技术要点组合最恰当的是", "o": {"A": "采用团注跟踪法将监测ROI置于肺动脉主干、阈值约100HU触发，高流率注射后以生理盐水冲刷，尽量缩短扫描时间并在浅吸气末屏气采集", "B": "监测ROI置于降主动脉、阈值250HU触发，以保证肺动脉充分强化", "C": "采用固定延迟60秒扫描，无需团注跟踪", "D": "嘱患者深大吸气后屏气至最大肺容量再扫描，以充分展开肺野", "E": "不使用生理盐水冲刷，以延长对比剂在肺动脉内的停留时间"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-025", "kp": "CTPA扫描技术要点", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：CTPA的目标是肺动脉峰值强化，故监测ROI应放在肺动脉主干，阈值通常设在约100HU左右并采用较短触发延迟；注射流率一般4~5ml/s，随后以生理盐水冲刷可推进对比剂团、减少上腔静脉内高浓度对比剂造成的线束硬化伪影；对呼吸困难者应缩短扫描时间并采用浅吸气末屏气，必要时平静呼吸下扫描。【为什么错】B错误：ROI置于降主动脉、阈值过高会导致触发过晚，采集时对比剂已进入体循环，肺动脉强化下降而主动脉过度强化。C错误：固定延迟无法适应患者心输出量的巨大个体差异，尤其肺栓塞患者循环时间常延长，易造成时相错误。D错误：深大吸气会使胸腔负压骤增，大量未强化的下腔静脉血涌入右心，稀释肺动脉内对比剂形成“瞬时对比剂中断”伪影，反而降低图像质量。E错误：不冲刷会加重上腔静脉与右心内高浓度对比剂的硬化伪影，干扰右肺动脉与其分支的观察。", "tr": "“深吸气屏气”在常规胸部CT是正确的，但在CTPA中恰是造成瞬时对比剂中断的经典原因，属技术细节性陷阱。此外，CTPA的团注跟踪阈值明显低于主动脉CTA，需分别记忆。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0126", "t": "单选题", "s": "CTPA上提示急性肺栓塞而非慢性栓塞的征象是", "o": {"A": "腔内中心性充盈缺损被对比剂环绕形成“轨道征”，附壁血栓与管壁呈锐角", "B": "血栓呈偏心附壁分布并与管壁呈钝角，伴管腔缩小", "C": "肺动脉壁钙化伴管腔膜状分隔", "D": "支气管动脉迂曲增粗、体-肺侧支形成", "E": "肺野呈广泛马赛克灌注伴管径粗细不均"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-026", "kp": "肺栓塞CTPA急慢性鉴别", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：急性血栓较新鲜、不附着于管壁，多悬浮于管腔中央，被对比剂环绕，长轴呈“轨道征”、短轴呈环形“甜甜圈”样；附壁部分与管壁交界呈锐角，且受累血管常轻度扩张。【为什么错】B错误：偏心附壁、与管壁呈钝角并伴管腔缩小，是机化血栓贴壁的慢性征象。C错误：肺动脉壁钙化与腔内膜状分隔（网状/条带）为慢性血栓栓塞性肺高压的典型改变。D错误：支气管动脉增粗与体-肺侧支形成需长期慢性缺血才会建立，是慢性表现。E错误：马赛克灌注伴血管管径粗细不均反映慢性灌注差异，亦属慢性栓塞性肺动脉高压表现。", "tr": "急慢性判定的核心是“血栓与管壁的夹角”和“管腔扩张还是缩小”：急性为锐角、管腔扩张；慢性为钝角、管腔缩小并伴钙化、网带与侧支。此判定直接影响溶栓与否的临床决策。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0127", "t": "多选题", "s": "关于普通型间质性肺炎（UIP）的HRCT表现，符合诊断要求的是", "o": {"A": "病变以胸膜下、双肺基底部分布为主，且分布不均匀", "B": "可见蜂窝征，即胸膜下成簇分布、壁厚而清晰的囊状气腔", "C": "常伴牵拉性支气管扩张或牵拉性细支气管扩张", "D": "可有轻度磨玻璃影，但其范围一般不超过网格影", "E": "以上中肺野与支气管血管束周围分布为主，伴大量弥漫性磨玻璃影和广泛微结节"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-027", "kp": "UIP型间质性肺病HRCT诊断标准", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：胸膜下、基底部为主且分布不均（异质性）是UIP分布学特征。B正确：蜂窝征为UIP型的确定性征象，表现为胸膜下成层排列、直径多3~10mm、壁清晰的小囊。C正确：牵拉性支气管/细支气管扩张反映纤维化牵拉，是UIP及可能UIP型的重要构成。D正确：UIP可有少量磨玻璃影，但必须以网格影与蜂窝为主；磨玻璃范围超过网格提示其他类型。【为什么错】E错误：上中肺野为主、支气管血管束周围分布、广泛磨玻璃与大量微结节均属“提示替代诊断”的特征，见于非特异性间质性肺炎、过敏性肺炎、结节病等，与UIP型不符。", "tr": "UIP判读遵循“分布＋征象”双要素。特别注意区分蜂窝征与牵拉性支扩、与肺气肿：蜂窝为成簇成层的厚壁小囊；小叶中心型肺气肿为无壁低密度区且多分布于上肺。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0128", "t": "单选题", "s": "HRCT上出现两肺弥漫性、光滑的小叶间隔增厚，伴双侧胸腔积液与心影增大，最符合的诊断是", "o": {"A": "心源性肺水肿（间质期）", "B": "结节病", "C": "肺泡蛋白沉积症", "D": "特发性肺纤维化", "E": "急性粟粒型肺结核"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-028", "kp": "小叶间隔增厚的鉴别", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：左心功能不全时液体首先积聚于小叶间隔与支气管血管周围间质，HRCT表现为光滑、均匀的小叶间隔增厚（对应胸片上的Kerley B线），常伴支气管血管束增粗、胸腔积液、心影增大及上肺血流重新分布。【为什么错】B错误：结节病表现为沿淋巴管分布的结节，使小叶间隔与胸膜下呈串珠状、结节状增厚，且以上中肺野与肺门周围为主，伴对称性肺门淋巴结肿大。C错误：肺泡蛋白沉积症为磨玻璃影与小叶间隔增厚叠加形成的“铺路石征”，边界清楚呈地图样，一般无胸腔积液与心影增大。D错误：特发性肺纤维化以胸膜下网格、蜂窝为主，小叶间隔增厚不规则并伴结构扭曲。E错误：急性粟粒型肺结核为弥漫随机分布的粟粒结节，非小叶间隔增厚。", "tr": "小叶间隔增厚形态学分类是快速鉴别的钥匙：光滑增厚多为心源性水肿或癌性淋巴管炎早期；结节状增厚提示癌性淋巴管炎或结节病；不规则增厚伴结构扭曲提示纤维化。", "bk": "副高", "ref": {"篇": "胸部", "章": "纵隔疾病", "节": "纵隔疾病的鉴别诊断", "页": 153}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0129", "t": "单选题", "s": "按传统三分法，前纵隔最常见的肿瘤不包括", "o": {"A": "胸腺瘤", "B": "畸胎瘤", "C": "胸骨后甲状腺肿", "D": "淋巴瘤", "E": "神经源性肿瘤"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-029", "kp": "纵隔分区与常见肿瘤", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】E为不属于前纵隔者，故为本题答案：神经源性肿瘤（神经鞘瘤、神经纤维瘤、节细胞神经瘤等）起自脊柱旁交感链或肋间神经，位于后纵隔（椎旁区），可伴椎间孔扩大、肋骨压迫吸收。【为什么错】A、B、C、D均属前纵隔常见占位，可归纳为“4T”：胸腺瘤（Thymoma）、畸胎瘤（Teratoma）、胸骨后甲状腺肿（Thyroid）、淋巴瘤（Terrible lymphoma）。其中胸腺瘤最常见并可合并重症肌无力；畸胎瘤含脂肪与钙化；甲状腺肿与颈部腺体相连且平扫密度较高；淋巴瘤多为融合的分叶状肿块并包绕大血管。", "tr": "注意分区体系差异：传统Felson三分法以气管前缘与心脏后缘、椎体前缘1cm为界；ITMIG新分区将纵隔分为血管前区、内脏区与椎旁区。考试常用传统三分法，但需知晓新分区名称。", "bk": "副高", "ref": {"篇": "胸部", "章": "胸部创伤", "节": "纵隔气肿及血肿", "页": 138}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0130", "t": "多选题", "s": "关于肥厚型心肌病的心脏MRI表现，描述正确的是", "o": {"A": "舒张末期左室最大室壁厚度≥15mm，多呈非对称性室间隔肥厚", "B": "电影序列可显示二尖瓣前叶收缩期前向运动（SAM征）及左室流出道血流加速的低信号射流", "C": "钆延迟强化常见于肥厚节段的壁中层以及室间隔与右室游离壁上下交界处", "D": "延迟强化范围越大提示预后越差，可作为危险分层的参考指标", "E": "延迟强化多呈心内膜下或透壁分布，且严格符合冠状动脉供血区"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-030", "kp": "肥厚型心肌病MRI表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (3)MR诊断要点", "ex": "【为什么对】A正确：成人无其他致肥厚原因时，最大室壁厚度≥15mm（有明确家族史者≥13mm）为诊断阈值，最常见形态为非对称性室间隔肥厚。B正确：平衡稳态自由进动电影序列可动态显示SAM征及流出道梗阻所致的湍流低信号射流。C正确：肥厚型心肌病的延迟强化典型分布为肥厚心肌壁中层斑片状及右室插入点，反映心肌纤维化与排列紊乱。D正确：延迟强化范围（通常以占左室心肌质量15%为界）与心源性猝死风险相关，是重要的危险分层信息。【为什么错】E错误：心内膜下或透壁分布且符合冠脉供血区，是缺血性（心肌梗死）延迟强化的模式，与肥厚型心肌病的非缺血性分布规律相反。", "tr": "扫描技术上应注意：肥厚型心肌病评估必须包含左室短轴全覆盖电影以测量最大室壁厚度，若仅扫长轴易低估肥厚部位；心尖肥厚型需加扫长轴与心尖专用层面，否则易漏诊。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0131", "t": "单选题", "s": "心脏MRI钆延迟强化（LGE）呈心外膜下与壁中层分布、不符合任何冠状动脉供血区，最提示", "o": {"A": "急性心肌梗死", "B": "陈旧性透壁性心肌梗死", "C": "非缺血性心肌病变（如心肌炎、扩张型心肌病等）", "D": "冠状动脉慢性完全闭塞伴侧支供血", "E": "心肌顿抑"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-031", "kp": "延迟强化模式的缺血与非缺血鉴别", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (3)MR诊断要点", "ex": "【为什么对】C正确：心肌缺血性坏死自心内膜下向心外膜呈“波前”式扩展，故缺血性LGE必然累及心内膜下并符合冠脉供血区；而心外膜下或壁中层分布、跨越冠脉供血区边界的强化，是非缺血性心肌损伤的标志，常见于心肌炎（下侧壁心外膜下）、扩张型心肌病（室间隔壁中层线状）、结节病等。【为什么错】A错误：急性心肌梗死为心内膜下或透壁强化，可伴微血管阻塞形成的强化区内无强化核心。B错误：陈旧透壁梗死呈室壁变薄的透壁性强化，同样起自心内膜下。D错误：慢性完全闭塞伴侧支者仍为缺血性损伤模式，强化仍以心内膜下为主。E错误：心肌顿抑为可逆性功能障碍，心肌细胞膜完整、无纤维化，LGE呈阴性。", "tr": "口诀式记忆：“碰到心内膜就想缺血，避开心内膜就想非缺血”。另需牢记LGE阴性但室壁运动异常提示顿抑或冬眠心肌，属可存活心肌，与瘢痕的鉴别直接影响血运重建决策。", "bk": "副高", "ref": null, "hf": true, "src": "模拟", "mk": 0}, {"id": "U07-0132", "t": "案例分析题", "s": "患者男性，59岁，2年前因急性前壁心肌梗死行溶栓治疗，近期活动后气促加重，超声心动图示前壁及心尖部运动减弱、左室射血分数38%。心内科拟行血运重建，术前需评估该区域心肌是否仍具存活性，以判断再血管化能否改善心功能，遂申请心脏MRI钆延迟强化检查。设备为1.5T，患者为窦性心律、心率72次/分且规整，可稳定屏气约12秒，肾小球滤过率正常，无钆对比剂使用禁忌。作为技师，下列关于延迟强化扫描的技术实施，正确的是", "o": {"A": "静脉注射钆对比剂后延迟约10~15分钟采集，采用心电门控反转恢复扰相梯度回波序列，并通过TI扫描（Look-Locker）选择使正常心肌信号被抑制为最低的反转时间", "B": "注药后立即采集，以捕捉对比剂首过高峰", "C": "反转时间固定设为800ms，无需个体化调整", "D": "采用自旋回波T2WI序列采集延迟图像，对瘢痕最敏感", "E": "在自由呼吸下采集单次激发图像，无需心电门控"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-032", "kp": "心肌延迟强化扫描技术", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (3)MR诊断要点", "ex": "【为什么对】A正确：钆对比剂在细胞外间隙扩大、清除延缓的瘢痕组织内蓄积，需延迟10~15分钟使正常心肌与瘢痕的对比度达到最佳。采集使用心电门控（舒张中期）的反转恢复扰相梯度回波序列，屏气完成；核心是通过Look-Locker/TI scout 选择正常心肌被“调零”的反转时间（1.5T常在200~300ms并随时间延长而增加），此时瘢痕呈明亮高信号，对比最强。相位敏感反转恢复（PSIR）可降低对TI精确度的依赖。【为什么错】B错误：注药即刻为首过灌注期，正常与瘢痕心肌均强化，无法区分。C错误：TI必须个体化，且随对比剂清除逐渐延长；固定800ms会使正常心肌未被抑制，瘢痕对比丧失。D错误：T2WI反映的是心肌水肿（急性损伤），并非延迟强化的成像原理，不能评估纤维瘢痕。E错误：无心电门控与屏气会产生严重的心脏搏动与呼吸伪影，无法满足薄层高对比要求。", "tr": "最常见的技术失误是TI选择不当：TI过短时正常心肌反而比瘢痕更亮甚至出现信号翻转，容易被误读为“无强化”。若不确定，应改用PSIR序列并复查TI scout。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0133", "t": "单选题", "s": "肝细胞癌在多期增强CT/MRI上典型的“快进快出”强化表现是指", "o": {"A": "动脉期明显强化，门静脉期及延迟期强化程度低于周围肝实质，可伴延迟强化的假包膜", "B": "动脉期无强化，门静脉期与延迟期渐进性充填", "C": "动脉期边缘结节样强化，延迟期向心性完全填充", "D": "三期均呈低密度、无强化", "E": "动脉期明显强化，门静脉期与延迟期持续高于肝实质"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-033", "kp": "肝细胞癌典型强化模式", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：肝细胞癌在癌变过程中门静脉供血逐渐减少、肝动脉新生血管增多，故动脉期明显强化（非环形高强化）；门静脉期正常肝实质由门静脉大量供血而密度上升，肿瘤因缺乏门静脉供血且引流静脉丰富，相对呈低密度即“廓清”。纤维假包膜在延迟期呈环形强化，是重要的辅助征象。【为什么错】B错误：动脉期无强化、渐进充填是纤维性病变或部分胆管细胞癌的特点。C错误：边缘结节样强化并向心性填充是海绵状血管瘤的典型模式。D错误：三期均无强化提示囊肿或坏死性病变。E错误：动脉期强化后持续高于肝实质，更符合局灶性结节增生（FNH）或部分富血供良性病变的“快进等出/慢出”表现。", "tr": "“快进快出”成立的前提是三期扫描时相准确：动脉晚期（注药后约30~35秒）过早会遗漏强化峰、过晚则廓清判断失真。技师若时相把握不准，会直接造成典型征象无法显现。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0134", "t": "案例分析题", "s": "患者女性，41岁，体检超声发现肝右叶一约4cm稍高回声占位，无腹痛、消瘦等症状。上腹部CT三期增强（动脉期、门静脉期及门静脉期后约90秒）示病灶动脉期边缘呈多个结节状明显强化、强化程度接近同层腹主动脉，门静脉期强化范围向中心推进但中央区仍未完全充填，90秒时中心仍见小片低密度，报告医师认为强化模式介于血管瘤与富血供恶性肿瘤之间，难以定性。患者无乙肝病史，甲胎蛋白与肝功能均正常。为明确诊断，下列补充检查技术最恰当的是", "o": {"A": "加做3~10分钟延迟期扫描，并结合MRI重T2加权（长TE）序列观察病灶是否呈持续显著高信号的“灯泡征”", "B": "加做CT平扫，通过平扫密度直接定性", "C": "缩短动脉期延迟时间重复扫描，以捕捉更早的强化峰", "D": "改行CT灌注成像测量肝血流量以定性", "E": "行DSA肝动脉造影，作为该病灶定性的首选检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-034", "kp": "肝血管瘤延迟扫描与重T2技术", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】A正确：本例强化模式高度提示海绵状血管瘤（“早出晚归”）。血管瘤血窦内血流缓慢，充填过程可长达数分钟，常规90秒延迟不足以显示完全填充，必须延长至3~10分钟。此外，血管瘤内自由水含量高、T2弛豫时间极长，在长TE的重T2加权图像上仍保持显著高信号（灯泡征），而多数恶性肿瘤信号随TE延长明显衰减，此为特异性极高的鉴别方法。【为什么错】B错误：平扫上血管瘤与其他实性病灶均呈低密度，无鉴别价值。C错误：缩短动脉期只会更早采集，无助于观察延迟充填。D错误：CT灌注辐射剂量高、后处理复杂，对典型血管瘤的定性并非必要手段。E错误：DSA为有创检查，不作为肝内良性占位定性的首选，仅在介入治疗或无创检查无法定论时考虑。", "tr": "常见失误是“三期做完就下结论”。凡见到边缘结节样强化未完全填充者，应主动追加延迟扫描；同时应记住：小血管瘤可在动脉期即快速均匀强化，酷似富血供恶性肿瘤，此时重T2与延迟持续强化是关键鉴别依据。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0135", "t": "多选题", "s": "关于肝硬化的CT与MRI表现，描述正确的是", "o": {"A": "肝表面呈结节状凹凸不平，肝裂与肝门区间隙增宽", "B": "尾状叶相对增大，尾状叶与右叶横径比值增大（常以0.65为参考阈值）", "C": "可见脾大、食管胃底静脉曲张、腹水等门静脉高压继发改变", "D": "再生结节因含铁及网状纤维，T2WI多呈等或低信号；若结节T2WI呈高信号并伴动脉期强化，应警惕癌变", "E": "肝硬化时肝各叶均匀等比例缩小，各叶体积比例保持正常"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-035", "kp": "肝硬化影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：再生结节与纤维间隔使肝缘呈波浪状、结节状，肝实质萎缩使肝裂、胆囊窝及肝门区脂肪间隙增宽。B正确：尾状叶血供与静脉回流相对独立，肝硬化时代偿性增大，尾右叶比增大是经典定量指标。C正确：门静脉高压继发脾大、侧支循环开放与腹水。D正确：再生结节含铁与纤维成分，T2WI呈等或低信号；出现T2高信号伴动脉期强化的结节提示由异型增生结节向肝细胞癌演变。【为什么错】E错误：肝硬化的形态改变是“不均衡”的——典型为右叶与方叶（左内叶）萎缩、左外叶与尾状叶代偿性增大，各叶比例明显失调，而非均匀等比例缩小。", "tr": "E以“均匀”“正常比例”设陷。技术层面提示：肝硬化背景下筛查小肝癌，应保证动脉晚期时相准确并加用肝细胞特异性对比剂的肝胆期，以提高微小病灶检出率。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏弥漫性病变", "节": "肝硬化", "页": 187}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0136", "t": "单选题", "s": "单纯性肝囊肿最典型的影像学表现是", "o": {"A": "CT呈水样低密度、边界锐利，MRI T1WI低信号、T2WI显著均匀高信号，增强各期均无强化", "B": "CT呈稍高密度，增强后动脉期明显强化", "C": "T1WI高信号、T2WI低信号，增强后边缘强化", "D": "CT呈脂肪密度，MRI脂肪抑制后信号明显下降", "E": "T2WI呈极低信号，增强后延迟强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-036", "kp": "肝囊肿影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】A正确：单纯性肝囊肿内容物为浆液，CT值接近水（约0~20HU），壁菲薄不可见，边界锐利；MRI上表现为长T1长T2信号，T2WI（尤其重T2）呈显著均匀高信号，增强各期囊内与囊壁均无强化，是最可靠的定性依据。【为什么错】B错误：稍高密度伴动脉期明显强化提示富血供实性病灶。C错误：T1高T2低多为出血、高蛋白或含铁病变。D错误：脂肪密度并可被脂肪抑制者为脂肪瘤或含脂病变（如血管平滑肌脂肪瘤）。E错误：T2极低信号伴延迟强化提示纤维性病变或钙化。", "tr": "囊肿的“无强化”必须通过同一层面、同一窗宽窗位对照平扫与增强的CT值来确认。小囊肿受部分容积效应影响可测出假性强化，此时应改用薄层重建或参考MRI重T2图像。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0137", "t": "多选题", "s": "关于急性胰腺炎的CT表现与严重程度评估，描述正确的是", "o": {"A": "增强扫描胰腺实质内无强化区提示胰腺坏死，坏死范围是评估严重程度的重要指标", "B": "Balthazar CT分级中，胰周脂肪间隙模糊、条索状渗出属于C级", "C": "CT严重指数由炎症分级评分与坏死程度评分相加得出，总分越高提示预后越差", "D": "急性坏死物积聚与包裹性坏死的鉴别依赖于是否形成完整的强化包壁及发病时间（一般以4周为界）", "E": "水肿型胰腺炎必须行增强扫描才能诊断，平扫无任何提示价值"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-037", "kp": "急性胰腺炎CT评估", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：坏死区微循环中断，增强后不强化，与周围强化的存活胰腺形成对比，是判断坏死性胰腺炎的核心依据。B正确：Balthazar分级中A为胰腺正常、B为胰腺局灶或弥漫性增大、C为胰腺异常伴胰周脂肪炎性改变、D为单个积液区、E为两个及以上积液区或胰腺/胰周积气。C正确：CT严重指数为炎症分级评分（0~4分）与坏死程度评分（无坏死0分、坏死小于30%为2分、30%~50%为4分、大于50%为6分）之和，分值越高并发症率与病死率越高。D正确：发病4周内为急性坏死物积聚，4周后形成完整强化壁者为包裹性坏死，此分类直接影响引流时机。【为什么错】E错误：平扫可显示胰腺弥漫性增大、密度减低、胰周脂肪间隙模糊、积液及出血高密度等，具有明确诊断价值；对肾功能不全或对比剂禁忌者，平扫仍是重要手段，只是无法评估坏死。", "tr": "E以“必须”“无任何价值”双重绝对化设陷。另一实务要点：过早（发病72小时内）行增强CT可能低估坏死范围，且理论上可能加重胰腺微循环障碍，评估坏死一般建议在发病72小时后进行。", "bk": "副高", "ref": {"篇": "腹部", "章": "胰腺", "节": "急性胰腺炎", "页": 196}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-0138", "t": "单选题", "s": "胰头癌在CT/MRI上出现的“双管征”是指", "o": {"A": "胆总管与主胰管同时扩张并在胰头肿块处截断", "B": "肝内左右肝管同时扩张", "C": "主胰管与副胰管同时扩张", "D": "胆总管与十二指肠腔同时扩张", "E": "门静脉与脾静脉同时扩张"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-038", "kp": "胰头癌双管征", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：胰头钩突以上的肿块同时侵犯或压迫走行于胰头内的胆总管下段与主胰管，造成两者上游同时扩张并在肿块层面突然截断，形成“双管征”，是胰头癌的重要间接征象，常伴远端胰腺实质萎缩。胰头癌为乏血供肿瘤，在胰腺实质期呈明显低密度，延迟期因富含纤维间质可轻度渐进强化。【为什么错】B错误：仅肝内胆管扩张提示肝门部或更高位梗阻，不构成双管征。C错误：主胰管与副胰管同时扩张并非该征定义。D错误：十二指肠腔扩张属肠管改变，与胆胰管扩张无关。E错误：门静脉与脾静脉扩张属门静脉高压征象。", "tr": "双管征并非胰头癌特有，壶腹癌、胆总管下段癌、慢性胰腺炎伴纤维化亦可出现。鉴别要点在于是否存在胰头低强化肿块、胰周脂肪浸润与血管包绕。技术上应采用胰腺实质期（注药后约40~45秒）薄层扫描以获得最大瘤-腺对比。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0139", "t": "多选题", "s": "关于胆道梗阻的影像诊断与MRCP技术，描述正确的是", "o": {"A": "肝内胆管明显扩张呈“软藤征”，提示梗阻部位较低或梗阻程度较重", "B": "MRCP利用重T2加权效应突出静止或缓慢流动的液体，无需注射对比剂即可显示胆胰管全貌", "C": "胆总管结石在MRCP上表现为高信号胆汁衬托下的低信号充盈缺损，常呈杯口状或新月形", "D": "恶性梗阻多表现为胆管突然截断、断端不规则或呈“鼠尾状”狭窄", "E": "MRCP空间分辨率高于薄层T2WI原始图像，因此仅需保存最大密度投影重建图，无需保留原始薄层图像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-039", "kp": "胆道梗阻诊断与MRCP技术", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】A正确：肝内胆管重度扩张、迂曲呈软藤状，多见于低位或长期严重梗阻。B正确：MRCP采用长TE重T2加权，使实质与流动血液信号被抑制，仅胆汁、胰液等静止液体呈高信号，属无创、无对比剂的水成像技术。C正确：结石不含质子信号，在高信号胆汁背景中呈低信号充盈缺损，边缘可呈杯口状。D正确：恶性梗阻断端不规则、突然截断或呈鼠尾状渐细，且常伴软组织肿块与双管征。【为什么错】E错误：最大密度投影图会因投影叠加掩盖小结石与细小充盈缺损，必须结合原始薄层（二维厚层或三维薄层）图像逐层观察，原始图像不可省略。", "tr": "MRCP的常见陷阱：胃十二指肠内液体、腹水可产生高信号干扰（可通过口服阴性对比剂或负性造影剂抑制）；呼吸运动与磁场不均匀可造成假性狭窄。判读必须MIP与原始层面对照。", "bk": "副高", "ref": {"篇": "腹部", "章": "胆道", "节": "胆囊炎", "页": 189}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0140", "t": "单选题", "s": "脾梗死在增强CT上最典型的表现是", "o": {"A": "基底位于脾包膜、尖端指向脾门的楔形无强化低密度区", "B": "脾内圆形明显强化结节，延迟期呈等密度", "C": "脾脏弥漫性肿大伴均匀强化", "D": "脾门区多发钙化灶", "E": "脾内边缘结节样强化并向心填充"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-040", "kp": "脾梗死影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：脾动脉分支呈节段性分布且缺乏侧支吻合，一支闭塞后其供血区呈楔形（三角形）缺血坏死，基底朝向脾包膜、尖端指向脾门，增强后不强化，边界较清。慢性期可机化、萎缩并形成脾轮廓凹陷。【为什么错】B错误：圆形明显强化结节延迟等密度提示血管瘤或错构瘤等富血供病灶。C错误：脾弥漫肿大伴均匀强化见于门静脉高压性脾大、感染或血液系统疾病。D错误：脾门区钙化多为陈旧肉芽肿或脾动脉钙化。E错误：边缘结节样强化并向心填充是血管瘤的强化模式。", "tr": "脾脏动脉期本身呈“花斑样”不均匀强化（红髓与白髓血流速度不同），是正常现象，切勿误判为梗死或病变；应以门静脉期脾实质强化趋于均匀时判断有无真正的无强化区。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0141", "t": "多选题", "s": "关于消化道穿孔与肠梗阻的腹部X线征象，描述正确的是", "o": {"A": "立位腹部平片见膈下新月形游离气体，是消化道穿孔的直接征象", "B": "机械性小肠梗阻可见小肠积气扩张、多个阶梯状气液平面", "C": "小肠扩张时黏膜环状皱襞横贯肠腔呈“鱼肋状”或“弹簧状”，结肠扩张则可见结肠袋", "D": "肠扭转绞窄时可出现“咖啡豆征”，闭袢内充满液体时可呈“假肿瘤征”", "E": "麻痹性肠梗阻表现为小肠局限性扩张而结肠完全无气"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-041", "kp": "消化道穿孔与肠梗阻X线征象", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：游离气体上浮至膈下，于立位片呈线状或新月形透亮影，是穿孔的直接证据。B正确：机械性梗阻近端肠管积气积液扩张，气液分层形成高低不等的阶梯状液平。C正确：小肠黏膜环状皱襞连续横贯肠腔形成鱼肋/弹簧样，结肠袋则不横贯全腔，是判断扩张肠管属小肠或结肠的关键。D正确：乙状结肠扭转形成闭袢呈咖啡豆征；闭袢内全为液体时呈边界清楚的软组织密度肿块样影，即假肿瘤征，提示绞窄。【为什么错】E错误：麻痹性肠梗阻的特点是小肠与结肠普遍、广泛积气扩张（全消化道张力低下），而非小肠局限扩张伴结肠无气；后者更符合机械性梗阻的表现。", "tr": "机械性与麻痹性梗阻的鉴别在于“扩张范围是否连续到结肠直肠”。技术要点：立位摄影须站立或坐位保持15~20分钟后曝光，游离气体量少时才能上浮显示；否则容易假阴性。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0142", "t": "案例分析题", "s": "患者男性，70岁，有长期口服非甾体抗炎药史，2小时前突发上腹部剧烈疼痛并迅速波及全腹，查体全腹压痛、腹肌板样紧张、肝浊音界缩小。血压92/58mmHg，心率108次/分，临床高度怀疑上消化道穿孔并腹膜炎。因剧痛与低血压，患者无法站立或端坐，也难以长时间保持坐位等待。急诊申请床旁腹部X线检查以寻找腹腔游离气体，为紧急手术提供依据。作为技师，在现有条件下最合适的摄影方案是", "o": {"A": "采用左侧卧位水平方向投照，使游离气体聚集于右侧腹壁与肝脏之间，摄影前尽可能保持该体位数分钟", "B": "采用仰卧前后位垂直投照，游离气体最易在此位置显示", "C": "采用右侧卧位水平投照，使气体积聚于脾与左侧腹壁之间以避开肝脏", "D": "改行常规腹部超声，因X线对游离气体不敏感", "E": "口服硫酸钡后摄片，以直接显示穿孔部位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-042", "kp": "疑似穿孔患者的替代摄影体位", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：显示游离气体的必要条件是“水平方向投照”加“气体有足够时间上浮”。不能站立者应取左侧卧位，此时右侧腹在上，游离气体上浮至肝脏外缘与右侧腹壁之间，肝脏均匀的软组织密度为气体提供了良好衬托背景，检出率高。为保证气体充分移位，摄影前应保持体位数分钟。【为什么错】B错误：仰卧位垂直投照时气体位于腹腔前方、与肠腔内气体重叠，难以分辨，是漏诊游离气体的经典原因。C错误：右侧卧位时气体上浮至左侧腹，与胃泡及结肠脾曲气体重叠，难以区分。D错误：气体强烈反射声波，超声对少量游离气体的定位与定量不如水平投照X线可靠，且本题要求X线方案。E错误：疑似穿孔为硫酸钡的禁忌证，钡剂漏入腹腔可引起严重钡剂性腹膜炎；如确需造影应使用水溶性碘对比剂。", "tr": "两个必考点：一是“不能站立者用左侧卧位水平投照”，二是“疑似穿孔禁用硫酸钡”。另需记住膈下游离气体的最低检出量在标准立位技术下约1~2ml，体位与等待时间比曝光条件更关键。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0143", "t": "单选题", "s": "子宫腺肌症与子宫肌瘤在MRI上最重要的鉴别点是", "o": {"A": "腺肌症表现为结合带弥漫性增厚（多超过12mm）、边界不清，其内可见点状T2高信号；肌瘤为边界清楚的T2低信号肿块伴假包膜", "B": "腺肌症表现为边界清楚的圆形肿块，肌瘤呈弥漫浸润", "C": "两者均使结合带变薄，仅凭强化程度区分", "D": "腺肌症在T1WI呈明显高信号，肌瘤呈明显低信号", "E": "腺肌症必然伴有卵巢囊肿，肌瘤则否"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-043", "kp": "子宫腺肌症与肌瘤鉴别", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：腺肌症为子宫内膜腺体与间质侵入肌层，T2WI上表现为结合带弥漫性或局限性增厚（大于12mm可诊断，8~12mm为可疑），边界模糊，其内可见异位内膜与小囊形成的点状高信号，子宫呈球形增大。子宫肌瘤为平滑肌来源的边界清楚肿块，T2WI呈均匀低信号，周围可有假包膜形成的高信号环，占位效应明确。【为什么错】B错误：两者形态特征完全说反。C错误：腺肌症的核心征象正是结合带增厚而非变薄，且强化程度不是主要鉴别依据。D错误：腺肌症T1WI多为等信号，仅出血灶可呈点状高信号，并非弥漫明显高信号。E错误：腺肌症与卵巢囊肿无必然伴随关系，“必然”属绝对化错误表述。", "tr": "结合带（联合带）是子宫肌层内层，T2WI低信号，评估必须使用高分辨T2WI，且需避开月经周期与子宫收缩造成的假性增厚（一过性收缩可模拟局限性腺肌症，重复扫描可鉴别）。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "子宫腺肌症", "页": 246}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0144", "t": "多选题", "s": "关于宫颈癌MRI分期评估的技术与征象，描述正确的是", "o": {"A": "高分辨T2WI应采用垂直于宫颈管长轴的斜轴位，以准确评估宫颈基质环", "B": "宫颈低信号纤维基质环完整，提示无宫旁组织浸润", "C": "基质环中断并见不规则信号影突入宫旁脂肪，提示宫旁受侵", "D": "DWI有助于显示原发灶范围与转移淋巴结，但不能单独用于分期", "E": "只要宫旁脂肪间隙内出现条索状影，即可确诊宫旁浸润"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-044", "kp": "宫颈癌MRI分期要点", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：宫颈管常呈前倾前屈，常规横断面会斜切基质环造成假性中断，必须以矢状面定位、扫垂直于宫颈管长轴的斜轴位。B正确：完整的低信号纤维基质环是阻止肿瘤外侵的解剖屏障，环完整对排除宫旁浸润的阴性预测值高。C正确：环中断伴宫旁不规则软组织信号是宫旁受侵的直接征象，直接决定能否手术。D正确：DWI可提高小病灶与淋巴结检出率，但存在假阳性（炎症、坏死），须与高分辨T2WI结合。【为什么错】E错误：宫旁条索影可由炎症、水肿、既往手术或血管断面造成，特异性低；必须结合基质环是否中断及是否存在结节样软组织影综合判断。", "tr": "扫描方位是本题的技术核心：斜轴位不到位造成的“假性基质环中断”是导致过度分期的常见原因。另注意宫颈癌分期以国际妇产科联盟标准为准，MRI主要用于评估肿瘤大小、宫旁与邻近器官侵犯。", "bk": "副高", "ref": null, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-0145", "t": "单选题", "s": "卵巢成熟性囊性畸胎瘤在MRI上区别于子宫内膜异位囊肿的关键征象是", "o": {"A": "T1WI高信号在脂肪抑制序列上信号明显减低，且脂-水界面可见化学位移伪影", "B": "T1WI高信号在脂肪抑制序列上信号无明显变化", "C": "T2WI呈明显低信号即所谓“阴影征”", "D": "增强扫描囊壁明显强化，囊内容物亦强化", "E": "病灶内可见流空血管影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-045", "kp": "卵巢畸胎瘤信号特征", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：成熟性畸胎瘤含成熟脂肪组织，T1WI呈显著高信号，加脂肪抑制后信号明显下降，这是确认脂肪成分、从而定性畸胎瘤的决定性方法；此外脂肪与水的进动频率差异在频率编码方向上造成化学位移伪影（脂-水界面一侧黑边、一侧白边），亦为含脂证据。CT上可见脂肪密度、钙化或牙齿及脂-液平面。【为什么错】B错误：脂肪抑制后信号不下降者为出血或高蛋白，符合子宫内膜异位囊肿而非畸胎瘤。C错误：T2WI信号减低的“阴影征”正是内膜异位囊肿（陈旧血液中高浓度铁与蛋白）的特征。D错误：畸胎瘤囊内容物不强化，此描述无鉴别意义且不准确。E错误：流空血管影提示富血供实性肿瘤。", "tr": "两类病变均在T1WI呈高信号，唯一可靠的分水岭是“加脂肪抑制后信号是否掉下来”。因此凡盆腔发现T1高信号囊性灶，必须加扫脂肪抑制T1WI，这是技师必须掌握的补充序列决策。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢畸胎瘤", "页": 240}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0146", "t": "单选题", "s": "卵巢子宫内膜异位囊肿（巧克力囊肿）在MRI上的典型信号表现是", "o": {"A": "T1WI低信号、T2WI高信号，边界清楚", "B": "T1WI高信号且脂肪抑制后仍为高信号，T2WI信号减低呈“阴影征”", "C": "T1WI等信号、T2WI极低信号，增强明显强化", "D": "T1WI高信号、脂肪抑制后信号明显下降", "E": "T1WI与T2WI均为极低信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-046", "kp": "子宫内膜异位囊肿信号特征", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】B正确：囊内为反复出血形成的陈旧血液，含高浓度正铁血红蛋白与蛋白，缩短T1故T1WI高信号；因非脂肪成分，脂肪抑制后信号不下降。囊内高浓度铁与蛋白造成T2弛豫缩短，T2WI信号自上而下逐渐减低呈“阴影征”，是较具特异性的表现，常为多发、双侧并伴粘连。【为什么错】A错误：单纯长T1长T2信号为浆液性囊肿表现。C错误：T2极低伴明显强化提示纤维性实性病变。D错误：脂肪抑制后明显下降者为畸胎瘤的脂肪成分。E错误：T1、T2均极低信号多见于钙化、含铁血黄素沉积或高度纤维化组织。", "tr": "“T1高＋T2低”是本病的信号组合钥匙，与畸胎瘤（T1高＋脂肪抑制后低）和单纯出血性囊肿（T2多不减低）不同。合并深部浸润型内异症时应加扫高分辨T2WI观察直肠子宫陷凹粘连。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0147", "t": "多选题", "s": "关于前列腺多参数MRI与PI-RADS评估，描述正确的是", "o": {"A": "外周带病灶以DWI/ADC为主导序列，移行带病灶以T2WI为主导序列", "B": "前列腺癌在T2WI上多呈局灶性低信号，与周围带正常的高信号形成对比", "C": "癌灶在高b值DWI上呈明显高信号，相应ADC图呈低信号", "D": "前列腺穿刺活检后应间隔一定时间（一般建议6周以上）再行MRI，以减少出血对判读的干扰", "E": "动态增强序列是所有分区评分的决定性序列，其权重高于T2WI与DWI"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-047", "kp": "前列腺mpMRI与PI-RADS", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：PI-RADS规定外周带以DWI评分为主导、移行带以T2WI评分为主导，这是评分体系的基本框架。B正确：正常外周带富含腺管与液体呈T2高信号，癌灶细胞密集、腺腔减少而呈局灶低信号，形态可呈边界不清的透镜状或不规则形。C正确：癌组织细胞密度高、细胞外间隙减小，水分子弥散受限，故高b值（一般要求达到或计算至1400s/mm²以上）DWI高信号、ADC值降低。D正确：穿刺后出血在T1WI呈高信号并可造成T2与DWI判读困难，间隔6周以上可显著减少干扰。【为什么错】E错误：动态增强在PI-RADS中仅起有限的“辅助升级”作用——主要用于外周带DWI评分为3分时，若动态增强阳性则升为4分；它不是主导序列，权重低于T2WI与DWI。", "tr": "常见误区是把动态增强当作前列腺MRI的核心。实际上多参数MRI的“主参数”是T2WI与DWI，动态增强是次要参数。检查前应排空直肠、必要时使用抗蠕动药以减少肠蠕动伪影对DWI的影响。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "前列腺癌", "页": 236}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-0148", "t": "案例分析题", "s": "患者男性，67岁，体检发现血清前列腺特异性抗原8.6ng/ml，游离/总PSA比值偏低，直肠指检未触及明显硬结，超声示前列腺体积约45ml。泌尿外科拟先行前列腺多参数MRI，依据PI-RADS评分决定是否行靶向融合穿刺以及穿刺靶点。设备为3.0T，患者近1周因便秘排便不畅，既往从未行前列腺穿刺活检，无髋关节假体、心脏起搏器等MRI禁忌证，肾功能正常。作为技师，下列检查前准备与序列安排最恰当的是", "o": {"A": "检查前排空直肠、必要时按临床医嘱使用抗蠕动药物；序列包括三平面高分辨T2WI（层厚约3mm）、多b值DWI（含高b值≥1400s/mm²）与ADC图，以及动态增强扫描", "B": "仅采集横断面T2WI，层厚8mm，不做DWI以缩短检查时间", "C": "为提高信噪比，DWI只采集b值为0与50s/mm²两档即可", "D": "不必处理肠道准备，直肠内粪便与气体对图像无影响", "E": "以动态增强作为唯一采集序列，其余序列可省略"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-048", "kp": "前列腺mpMRI检查技术准备", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：直肠内粪便与气体会在气-组织界面产生磁敏感伪影，严重降低回波平面DWI质量并造成图像变形，故应排空直肠；肠蠕动伪影可用抗蠕动药物减轻。序列上必须具备三平面高分辨T2WI（评估移行带与包膜、精囊侵犯）、多b值DWI并计算或直接采集高b值图像与ADC图（评估外周带），以及动态增强（用于评分3分病灶的升级判定），三者共同构成多参数MRI。【为什么错】B错误：层厚8mm部分容积效应严重，且缺少DWI则外周带无法评分，不符合PI-RADS技术要求。C错误：仅有低b值无法体现弥散受限，也无法准确计算ADC，必须包含足够高的b值。D错误：直肠内容物与气体是前列腺DWI最主要的伪影来源，忽视会导致图像不可用。E错误：动态增强不能替代T2WI与DWI，单独使用无法完成PI-RADS评分。", "tr": "技术要点在于“伪影来源决定检查前准备”。3.0T下磁敏感伪影比1.5T更明显，直肠准备与相位编码方向选择尤为重要；必要时可采用降低回波间隔或使用并行采集来减轻变形。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "前列腺癌", "页": 236}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0149", "t": "单选题", "s": "膀胱癌MRI分期中，判断肿瘤是否侵犯肌层最关键的观察内容是", "o": {"A": "T2WI上膀胱壁固有肌层低信号带是否连续完整，中断者提示肿瘤已侵犯肌层", "B": "肿瘤在T1WI上的信号高低", "C": "膀胱腔内是否存在气体", "D": "增强扫描肿瘤强化的绝对CT值", "E": "肿瘤基底部是否宽大，宽基底者一律为肌层浸润"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-049", "kp": "膀胱癌MRI分期要点", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：膀胱固有肌层在高分辨T2WI上呈连续的低信号带，肿瘤多呈中等信号。低信号带完整提示肿瘤局限于黏膜与黏膜下层（非肌层浸润性，可行经尿道电切）；低信号带中断则提示肌层浸润（T2期及以上），需根治性治疗，是分期最关键的判断点。【为什么错】B错误：T1WI主要用于观察膀胱周围脂肪受侵与骨转移，对肌层判断价值有限。C错误：膀胱腔内气体多为导尿或产气菌感染所致，与分期无关。D错误：MRI不使用CT值这一密度单位，表述本身即错误。E错误：宽基底虽提示浸润风险增加，但不能一律判定为肌层浸润，须以低信号带是否中断为准，且“一律”属绝对化错误。", "tr": "检查前应适度充盈膀胱（过度充盈会使壁变薄、掩盖小病灶，过度空虚则壁增厚形成假阳性）。此外，经尿道电切术后局部水肿与肉芽可造成假性肌层中断，建议术后间隔数周复查。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "膀胱癌", "页": 237}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0150", "t": "单选题", "s": "Pfirrmann分级用于评价椎间盘退变，其分级主要依据的图像与观察指标是", "o": {"A": "矢状面T2WI上髓核信号强度、髓核与纤维环界限是否清晰、椎间隙高度", "B": "横断面CT上椎间盘的CT值与钙化程度", "C": "矢状面T1WI上终板骨髓信号改变", "D": "增强后椎间盘的强化程度", "E": "X线侧位片上椎体前缘骨赘的大小"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-050", "kp": "椎间盘退变Pfirrmann分级", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：Pfirrmann分级基于矢状面T2WI，综合三项指标：髓核信号强度（由高亮渐变为灰、黑）、髓核与纤维环界限（由清晰到消失）、椎间隙高度（由正常到塌陷）。Ⅰ级髓核均匀亮白、界限清楚、高度正常；Ⅱ级信号仍高但不均匀，可见水平带；Ⅲ级呈中等灰色、界限模糊、高度正常或轻度降低；Ⅳ级呈灰至黑色、界限消失、高度中度降低；Ⅴ级呈黑色、界限消失、椎间隙塌陷。【为什么错】B错误：CT值与钙化不是该分级依据，CT亦难以评估髓核含水量。C错误：终板骨髓信号改变属Modic分型（Ⅰ型水肿、Ⅱ型脂肪、Ⅲ型硬化），与Pfirrmann分级不同。D错误：正常椎间盘无血供，不以强化程度分级。E错误：骨赘属椎体退变征象，不用于椎间盘分级。", "tr": "极易与Modic分型混淆：Pfirrmann看“椎间盘本身”，Modic看“相邻终板与椎体骨髓”。二者常在同一份报告中出现，须分清各自的观察对象与序列依据。", "bk": "副高", "ref": {"篇": "骨与骨关节", "章": "脊柱退行性病变", "节": "椎间盘及椎骨的退变过程", "页": 285}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0151", "t": "多选题", "s": "关于椎体压缩骨折新鲜与陈旧的鉴别以及良恶性判断，描述正确的是", "o": {"A": "新鲜骨折椎体内骨髓水肿，在脂肪抑制T2WI或STIR序列上呈高信号，T1WI呈低信号", "B": "陈旧骨折椎体骨髓信号恢复为正常脂肪信号，T1WI高信号、STIR低信号", "C": "椎体后缘向后膨隆、椎弓根受累及椎旁软组织肿块提示恶性病理性骨折", "D": "良性骨质疏松性压缩骨折可见带状水肿、清晰的骨折线，有时可见“裂隙征”（真空或液体征）", "E": "只要椎体呈楔形变，即可判断为新鲜骨折"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-051", "kp": "椎体压缩骨折新旧与良恶性鉴别", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：新鲜骨折伴骨髓水肿与出血，含水量增高，故T1WI低信号、脂肪抑制T2WI/STIR高信号，这是判断“责任椎”的核心依据。B正确：陈旧骨折骨髓修复为脂肪，信号回归正常。C正确：恶性者由肿瘤组织替代骨髓，常见椎体后缘凸隆、椎弓根侵犯（正位片“椎弓根征”消失）及椎旁软组织肿块。D正确：良性者水肿多呈紧邻终板的带状分布而非弥漫全椎体，可见清晰骨折线；骨坏死时出现裂隙征。【为什么错】E错误：楔形变仅说明椎体形态改变，陈旧骨折同样呈楔形；能否判断为新鲜必须依靠骨髓水肿信号，而非形态。", "tr": "X线与CT只能显示形态与骨小梁改变，无法区分新旧；MRI的脂肪抑制T2WI/STIR是唯一可靠手段。这一点在多节段压缩骨折患者中直接决定椎体成形术的靶椎选择。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-0152", "t": "案例分析题", "s": "患者女性，78岁，绝经30年，确诊骨质疏松症5年，1个月前有轻微跌倒史，近2周腰背痛明显加重，翻身与起坐时疼痛剧烈，叩击痛以下胸腰段为著。腰椎正侧位X线片示T12、L1、L3三个椎体呈不同程度楔形变，椎体前缘高度均有丢失，仅凭形态无法判断哪一节段为近期骨折。临床拟行经皮椎体成形术，需要在术前准确锁定引起症状的责任椎体。患者可平卧配合检查约20分钟，无心脏起搏器等MRI禁忌证。作为技师，最恰当的检查方案是", "o": {"A": "行腰椎MRI，必须包含矢状面短反转时间反转恢复（STIR）或脂肪抑制T2WI序列，以骨髓水肿高信号确定新鲜骨折椎体", "B": "行腰椎CT薄层扫描加矢状面重建，通过骨小梁形态判断新旧", "C": "重复腰椎正侧位X线片并加照过伸过屈位", "D": "行腰椎MRI但仅采集矢状面T1WI与T2WI，不加脂肪抑制序列", "E": "行腰椎MRI增强扫描，以强化程度判断新旧骨折"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-052", "kp": "责任椎体判定的序列选择", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：老年患者椎体骨髓以黄骨髓（脂肪）为主，常规T2WI上骨髓脂肪本身呈较高信号，会掩盖水肿信号；STIR或脂肪抑制T2WI抑制脂肪后，水肿呈醒目高信号，能敏感、特异地标记新鲜骨折椎体，是判定责任椎的标准序列。STIR基于T1值差异抑制脂肪，对磁场不均匀不敏感，在脊柱大范围扫描中稳定性优于频率选择性脂肪抑制。【为什么错】B错误：CT显示骨折线与骨皮质优秀，但无法反映骨髓水肿，陈旧与新鲜骨折的骨小梁形态可高度重叠。C错误：X线只能显示形态，动力位片用于评估不稳定，不能判断水肿。D错误：不加脂肪抑制时，黄骨髓高信号会掩盖水肿，极易漏判。E错误：增强扫描既非必要也不特异，新鲜骨折与肿瘤均可强化，且增加对比剂风险。", "tr": "技术要点是“脂肪抑制的必要性”：老年脊柱含大量黄骨髓，未抑脂的T2WI几乎无法识别水肿。此外STIR序列不应在注射钆对比剂后使用，因其会同时抑制强化组织的高信号。", "bk": "副高", "ref": {"篇": "基础概念（绪论）", "章": "基本概念（X线物理/对比剂/成像基础）", "节": "骨质疏松", "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0153", "t": "多选题", "s": "关于脊柱结核、化脓性脊柱炎与脊柱转移瘤的影像鉴别，描述正确的是", "o": {"A": "脊柱结核常累及相邻两个椎体并破坏其间的椎间盘，伴范围较大的椎旁冷脓肿，脓肿壁可钙化并沿腰大肌流注", "B": "化脓性脊柱炎早期即出现椎间盘破坏、椎间隙狭窄与终板侵蚀，椎间盘T2WI信号增高，病程进展快", "C": "脊柱转移瘤通常椎间盘不受累、椎间隙保持正常，常侵犯椎弓根", "D": "脊柱结核可出现跳跃性病灶及后凸畸形", "E": "三者均以椎间盘早期破坏为共同特点，故椎间盘受累与否无鉴别价值"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-053", "kp": "脊柱感染与转移瘤鉴别", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：结核杆菌经椎体终板下动脉播散，破坏相邻椎体并侵及椎间盘，形成范围广泛的椎旁寒性脓肿，钙化与流注是其相对特征性表现。B正确：化脓菌产生蛋白溶解酶，对椎间盘破坏早而迅速，椎间隙狭窄、终板模糊，椎间盘T2WI呈高信号并强化，全身症状重。C正确：椎间盘无血供且乏营养，血行转移瘤一般不跨越椎间盘，椎间隙保持是转移瘤区别于感染的核心征象；转移常累及椎体后部与椎弓根。D正确：结核可经椎旁韧带下蔓延形成跳跃病灶，椎体塌陷后形成角状后凸。【为什么错】E错误：椎间盘是否受累恰恰是感染性病变与肿瘤性病变最重要的鉴别点，绝非无价值。", "tr": "记忆主线：“感染坏椎间盘，肿瘤留椎间盘；结核脓肿大而钙化、化脓进展快而椎间盘信号高。”技术上应加扫脂肪抑制T2WI与增强以显示椎旁脓肿范围及硬膜外受累。", "bk": "副高", "ref": {"篇": "骨与骨关节", "章": "脊柱感染性病变", "节": "化脓性脊柱炎", "页": 288}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-0154", "t": "单选题", "s": "股骨头缺血性坏死在MRI上具有较高特异性的“双线征”是指", "o": {"A": "T2WI上坏死区边缘外侧的低信号带（硬化骨）与其内侧的高信号带（肉芽修复组织）并行出现", "B": "T1WI上出现两条平行的高信号带", "C": "股骨颈内出现两条骨折线", "D": "关节腔内出现双层积液信号", "E": "增强扫描出现两层环形强化的滑膜"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-054", "kp": "股骨头缺血坏死双线征", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：坏死骨与活骨交界处形成反应界面，外侧为硬化骨与纤维组织（T2WI低信号），内侧为富血供的肉芽修复带（T2WI高信号），二者平行排列即双线征。相应地T1WI上表现为蜿蜒迂曲的低信号带（新月形或地图样），MRI可在X线与CT尚正常时即检出病变，是最敏感的方法。【为什么错】B错误：T1WI上表现为单一的蜿蜒低信号带，而非两条高信号带。C错误：双线征与骨折线无关。D错误：关节积液为均一液体信号，无分层双线结构。E错误：滑膜双层强化非本病特征。", "tr": "ARCO分期要点：0期影像学阴性；Ⅰ期仅MRI阳性、X线正常；Ⅱ期X线可见硬化囊变但股骨头无塌陷；Ⅲ期出现新月征即软骨下骨折与塌陷；Ⅳ期继发骨关节炎、关节间隙狭窄。“有无塌陷”是Ⅱ、Ⅲ期分界，直接决定保髋还是置换。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0155", "t": "多选题", "s": "关于膝关节半月板与交叉韧带损伤的MRI表现，描述正确的是", "o": {"A": "半月板内异常高信号达到关节面（Ⅲ级信号）方可诊断为撕裂，Ⅰ、Ⅱ级为黏液样变性", "B": "半月板桶柄状撕裂时，移位的半月板碎片位于后交叉韧带下方，矢状面上形成“双后交叉韧带征”", "C": "外侧半月板“领结征”消失（连续矢状层面上体部领结样结构少于两层）提示半月板移位或撕裂", "D": "前交叉韧带撕裂的间接征象包括股骨外侧髁与胫骨后外侧的对吻性骨挫伤、胫骨前移", "E": "半月板与交叉韧带评价应首选T1WI，因其信噪比最高、对撕裂最敏感"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-055", "kp": "半月板与交叉韧带损伤MRI", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：半月板信号分级中Ⅰ级为点状、Ⅱ级为线状但均未达关节面，属退变；只有异常信号延伸至上或下关节面（Ⅲ级）才诊断撕裂。B正确：桶柄状撕裂的内侧碎片向髁间窝移位，位于后交叉韧带下方，形成“双后交叉韧带征”。C正确：正常半月板体部在矢状面上连续两层以上呈领结样，层数减少提示组织缺失或移位。D正确：前交叉韧带断裂时胫骨相对前移，股骨外侧髁与胫骨后外侧撞击形成对吻性骨挫伤，是重要的间接征象。【为什么错】E错误：应首选质子密度加权或脂肪抑制质子密度/T2加权序列——半月板与韧带本身为低信号，撕裂处的液体或黏液变性在这些序列上呈高信号，对比最佳；T1WI虽信噪比高但液体与纤维组织对比差，敏感性低。", "tr": "B项的高频陷阱是把“双后交叉韧带征”误记为“双前交叉韧带征”，移位碎片位于后交叉韧带下方。另注意“魔角效应”：当结构与主磁场成约55°时短TE序列可出现假高信号，需用长TE序列复核。", "bk": "副高", "ref": null, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-0156", "t": "单选题", "s": "下列骨膜反应类型中，最不提示病变具有侵袭性的是", "o": {"A": "Codman三角", "B": "日光放射状骨针", "C": "葱皮样多层骨膜反应", "D": "骨膜反应中断、残缺不全", "E": "连续、致密、厚而光滑的实性骨膜反应"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-056", "kp": "骨膜反应类型与侵袭性判断", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】E正确：连续、致密、厚而光滑的实性骨膜反应说明骨膜有充足时间形成成熟新生骨，提示病变进展缓慢，多见于良性病变、慢性骨髓炎、骨样骨瘤、应力性骨折等。【为什么错】A错误：Codman三角为肿瘤突破骨皮质将骨膜掀起，骨膜新生骨仅在边缘残留呈三角形，提示生长迅速。B错误：日光放射状骨针为肿瘤沿垂直于骨皮质的血管走行成骨，是骨肉瘤等高侵袭性病变的表现。C错误：葱皮样多层骨膜反应反映肿瘤间歇性快速生长，常见于尤文肉瘤，亦可见于骨肉瘤与急性骨髓炎。D错误：骨膜反应中断残缺说明新生骨形成速度赶不上病变破坏速度，属侵袭性表现。", "tr": "务必记住：骨膜反应类型反映的是“病变生长速度”而非“良恶性本身”。Codman三角与葱皮样反应同样可见于急性骨髓炎，不能单凭骨膜反应形态确诊肿瘤，需结合骨破坏区移行带、软组织肿块与临床。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0157", "t": "单选题", "s": "评价骨破坏区的良恶性倾向时，提示病变侵袭性强的征象是", "o": {"A": "破坏区移行带宽、边界模糊，呈虫蚀状或渗透状破坏", "B": "破坏区呈地图状，边缘有硬化边", "C": "破坏区边界清楚锐利，移行带窄", "D": "病灶周围骨皮质膨胀变薄但连续完整", "E": "病灶内可见成熟骨性间隔"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-057", "kp": "骨破坏移行带与侵袭性", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：移行带指病变与正常骨之间的过渡区。移行带宽、边界模糊说明病变生长速度快于宿主骨的修复反应，虫蚀状与渗透状破坏是高侵袭性的典型形态，常见于恶性骨肿瘤、转移瘤、骨髓瘤及急性骨髓炎。【为什么错】B错误：地图状破坏伴硬化边说明宿主骨有足够时间形成反应性硬化，提示生长缓慢。C错误：边界清楚、移行带窄提示良性或低度侵袭性。D错误：骨皮质膨胀变薄但连续完整是良性膨胀性病变（如骨囊肿、骨巨细胞瘤）的表现。E错误：成熟骨性间隔提示病变慢性、良性。", "tr": "移行带宽窄比病灶大小更能反映侵袭性。需注意：骨巨细胞瘤虽常边界较清、皮质膨胀，但属交界性肿瘤，可复发甚至转移；影像的“侵袭性”评价与病理良恶性并不完全等同。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0158", "t": "单选题", "s": "主动脉夹层的Stanford分型中，A型的定义是", "o": {"A": "无论内膜破口位于何处，只要夹层累及升主动脉", "B": "内膜破口必须位于升主动脉且不累及主动脉弓", "C": "夹层仅累及降主动脉", "D": "夹层累及腹主动脉及其分支", "E": "夹层仅累及主动脉弓三分支"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-058", "kp": "主动脉夹层分型", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】A正确：Stanford分型着眼于“升主动脉是否受累”这一决定治疗方式的关键：凡累及升主动脉者为A型，需紧急外科手术；未累及升主动脉者为B型，多采用药物治疗或腔内修复。【为什么错】B错误：Stanford分型不要求破口位于升主动脉，也不排除累及主动脉弓，此描述混入了破口位置限定。C错误：仅累及降主动脉为Stanford B型。D错误：累及腹主动脉可见于DeBakey Ⅲb型，不等同于Stanford A型。E错误：分型依据是升主动脉是否受累，而非弓部分支。", "tr": "两套分型须分清：DeBakey按“起源＋累及范围”分Ⅰ型（起自升主动脉并累及降主动脉及以远）、Ⅱ型（局限于升主动脉）、Ⅲ型（起自左锁骨下动脉远端，Ⅲa限于胸降主动脉、Ⅲb延及腹主动脉）；Stanford只看升主动脉是否受累。DeBakey Ⅰ、Ⅱ型相当于Stanford A型。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0159", "t": "多选题", "s": "在主动脉夹层CTA上，支持某一腔为“假腔”的征象是", "o": {"A": "腔内可见“蜘蛛网征”，即残存的内膜条索呈细线状横跨腔内", "B": "腔的横断面呈锐角楔形延伸即“鸟嘴征”", "C": "该腔横截面积较大并环绕、压迫另一腔", "D": "增强后强化时间延迟、强化程度较淡，且更易形成附壁血栓", "E": "内膜钙化紧贴该腔外缘并随内膜片内移，是该腔为假腔的可靠依据"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-059", "kp": "主动脉夹层真假腔鉴别", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】A正确：蜘蛛网征为撕裂不全的内膜残余条索残留于假腔内，是假腔的特异征象。B正确：鸟嘴征为假腔沿夹层扩展方向形成的楔形锐角，是识别假腔的经典标志。C正确：假腔内压力高、扩展迅速，通常面积大于真腔并压迫、包绕真腔使其呈新月形或受压变形。D正确：假腔血流缓慢、入口有限，故强化延迟且较淡，血栓形成常见。【为什么错】E错误：该项描述的是真腔特征而非假腔——内膜钙化本属主动脉内膜，夹层后随内膜片内移，故钙化位于真腔外缘、与真腔相贴，是判断真腔的重要依据，题干要求选支持“假腔”的征象，故E不符合。", "tr": "真腔的另一识别要点是“与未受累的近远端主动脉腔延续”，在多平面重建上追踪最可靠。技术上必须包含平扫，否则壁内血肿（新月形高密度）和钙化内移会被增强血液掩盖而漏诊。", "bk": "副高", "ref": null, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-0160", "t": "案例分析题", "s": "患者男性，55岁，高血压病史10年、服药不规律，2小时前静息状态下突发胸背部撕裂样剧痛并向腰部放射，急诊测双上肢血压不对称，右上肢190/110mmHg，胸片示上纵隔增宽。临床高度怀疑急性主动脉综合征，需明确有无夹层、内膜破口位置、累及范围及内脏动脉受累情况，为外科或腔内治疗提供依据，遂申请主动脉CTA。设备为双源CT，患者心率85次/分且节律不齐，疼痛致配合欠佳，血肌酐正常、无碘对比剂过敏史。作为技师，下列扫描技术方案最恰当的是", "o": {"A": "先行胸腹主动脉平扫，再行心电门控增强扫描，范围自胸廓入口至股动脉分叉，经右上肢静脉注射对比剂并采用团注跟踪触发", "B": "省略平扫直接行增强扫描，以缩短检查时间并降低辐射剂量", "C": "扫描范围仅覆盖胸主动脉，因夹层不会累及腹主动脉", "D": "经左上肢静脉注射对比剂，以避开右心系统", "E": "不使用心电门控，因门控会延长扫描时间且对主动脉成像无意义"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-060", "kp": "主动脉CTA扫描技术", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】A正确：平扫是识别壁内血肿（主动脉壁新月形高密度）与内膜钙化内移的唯一手段，不可省略；心电门控可消除升主动脉随心脏搏动产生的运动伪影，避免形成酷似内膜片的伪影而误诊；扫描范围须自胸廓入口至股动脉分叉，以完整评估夹层累及范围、破口位置及分支受累，为手术或腔内修复提供依据；经右上肢注射可避免左头臂静脉内高浓度对比剂横跨主动脉弓上方产生条状硬化伪影。【为什么错】B错误：省略平扫会漏诊壁内血肿这一急性主动脉综合征的重要类型。C错误：夹层常向下延伸累及腹主动脉及内脏动脉，范围不足将遗漏关键信息。D错误：左侧注射时左头臂静脉恰位于主动脉弓分支上方，高浓度对比剂产生的线束硬化伪影会干扰弓部及其分支判读。E错误：升主动脉搏动伪影是最常见的假阳性来源，心电门控恰恰是主动脉根部与升主动脉成像的关键。", "tr": "三个高频技术陷阱：省略平扫、范围不足、未用门控。此外注意本例心率快且不规则，应优先选择大螺距或宽体探测器的快速采集模式，不宜使用需要多心动周期拼接的采集方式。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0161", "t": "单选题", "s": "下肢深静脉血栓在间接法CT静脉成像（CTV）上的典型直接征象是", "o": {"A": "静脉腔内低密度充盈缺损，管腔扩张，周围可见环形强化的静脉壁", "B": "静脉管腔明显变细、管壁增厚且无充盈缺损", "C": "动脉腔内偏心性钙化斑块", "D": "皮下脂肪层内条索状高密度影", "E": "股动脉管腔内低密度充盈缺损"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-061", "kp": "下肢深静脉血栓CTV征象", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】A正确：急性期血栓在强化的静脉腔内呈低密度充盈缺损，受累静脉因血栓充填而管径增粗，静脉壁滋养血管扩张与炎症反应形成环形强化（“轨道征”），周围脂肪间隙可见水肿模糊，是急性DVT的典型表现。间接法CTV通常在肺动脉CTA后延迟约3分钟扫描下肢，可实现肺栓塞与DVT的一站式评估。【为什么错】B错误：管腔变细、管壁增厚而无充盈缺损为慢性血栓后改变，常伴侧支形成。C错误：偏心钙化斑块位于动脉，属动脉粥样硬化表现。D错误：皮下条索影为软组织水肿或淋巴回流障碍的非特异表现。E错误：题目所问为深静脉血栓，动脉内充盈缺损为动脉栓塞。", "tr": "间接CTV的时相把握是关键：过早扫描静脉尚未充分强化会出现“假性充盈缺损”，过晚则对比度下降。判读时还要注意层流造成的混合伪影，常见于髂静脉与股静脉交汇处，需结合多平面重建确认。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-0162", "t": "多选题", "s": "关于外周神经MR成像（MRN）与周围神经卡压的影像评估，描述正确的是", "o": {"A": "三维短反转时间反转恢复序列（3D-STIR-SPACE/VISTA/CUBE）可在抑制脂肪与血管信号的同时突出神经，适用于臂丛神经成像", "B": "背景抑制弥散加权成像（DWIBS）可通过抑制背景信号突出显示神经干走行，有助于整体观察", "C": "神经卡压时受压部位近端神经增粗、T2/STIR信号增高，受压处可变扁", "D": "腕管综合征时正中神经在豌豆骨水平增粗、信号增高，屈肌支持带可向掌侧膨隆", "E": "臂丛神经MRN应首选横断面薄层T1WI单一序列，无需斜冠状面与脂肪抑制序列"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-062", "kp": "外周神经MRN成像技术与征象", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (3)MR诊断要点", "ex": "【为什么对】A正确：3D-STIR类序列脂肪抑制均匀、对磁场不均匀不敏感，并可抑制流动血液信号，使神经在低信号背景中突出，配合最大密度投影可显示臂丛全程。B正确：DWIBS通过高b值与短反转时间抑制背景组织，使神经呈高信号，形成类似神经造影的整体显示效果。C正确：卡压近端神经因轴浆运输受阻而水肿增粗、T2/STIR信号增高，卡压处受机械压迫而变扁，形成“束腰”样改变。D正确：腕管综合征的典型影像三联为正中神经在豌豆骨或钩骨钩水平增粗且信号增高、屈肌支持带掌侧膨隆、神经远端变扁。【为什么错】E错误：臂丛神经走行倾斜且跨越多个层面，必须采用斜冠状面（沿神经根与干走行）结合脂肪抑制序列；单一横断面T1WI虽显示解剖关系好，但无法评估神经信号异常，也不能显示神经全程。", "tr": "神经成像的关键是“抑脂＋抑血流＋沿神经走行方位采集”。此外注意魔角效应：神经与主磁场成约55°时短TE序列可产生假性高信号，应使用长TE或STIR类序列复核，避免误诊为神经损伤。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1001", "t": "单选题", "s": "超急性期脑出血（发病后数小时内）CT平扫时，血肿的典型密度表现是", "o": {"A": "低密度影", "B": "等密度影", "C": "高密度影", "D": "混杂密度影", "E": "环形强化影"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-001", "kp": "脑出血CT密度演变", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】超急性期血肿内红细胞完整、血红蛋白浓缩，X线吸收系数高，CT平扫即呈高密度（CT值约50～80 HU），随时间延长血肿逐步演变为等、低密度。【为什么错】A：低密度为血肿吸收后期或液化坏死期的表现。B：等密度见于亚急性期后期至慢性期部分时段。D：混杂密度见于血肿内新鲜出血与液化并存或出血伴占位内坏死。E：环形强化是增强扫描后的表现，平扫不出现强化。", "tr": "脑出血密度按“高→等→低”演变；超急性期即高密度，勿与超急性期脑梗死（CT常阴性）混淆。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1002", "t": "单选题", "s": "临床疑急性蛛网膜下腔出血时，首选的影像学检查方法是", "o": {"A": "颅骨X线平片", "B": "CT平扫", "C": "MRI平扫", "D": "PET-CT", "E": "经颅超声"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-002", "kp": "蛛网膜下腔出血检查方法", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】CT平扫对急性期蛛网膜下腔出血敏感，脑沟、脑池及蛛网膜下腔内的新鲜血液呈高密度，检查快速便捷，是急诊首选检查。【为什么错】A：X线平片无法显示颅内软组织出血。C：MRI对超急性期出血显示不佳、检查时间长，不作为首选。D：PET-CT用于功能代谢显像，不用于出血诊断。E：超声无法穿透颅骨显示颅内出血。", "tr": "蛛网膜下腔出血CT敏感性随发病时间下降，发病24小时后可结合MRI（FLAIR、SWI）补充检查。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "颅内囊性病变", "节": "蛛网膜囊肿", "页": 80}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1003", "t": "单选题", "s": "脑出血进入亚急性期后期（约出血后1～2周）时，血肿在MRI T1WI与T2WI上的信号特点是", "o": {"A": "T1WI低信号、T2WI高信号", "B": "T1WI高信号、T2WI低信号", "C": "T1WI低信号、T2WI低信号", "D": "T1WI高信号、T2WI高信号", "E": "T1WI等信号、T2WI等信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-003", "kp": "脑出血MRI信号分期", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】亚急性期后期红细胞溶解，游离的正铁血红蛋白处于细胞外并被稀释，缩短T1的同时延长T2，故T1WI、T2WI均为高信号。【为什么错】A：T1低、T2高为慢性期液化囊变或脑脊液样信号。B：T1高、T2低为亚急性期早期（细胞内正铁血红蛋白）的表现。C：双低信号见于钙化或含铁血黄素沉积。E：等信号见于急性期部分阶段。", "tr": "记忆口诀“亚早内正铁（T1高T2低）、亚晚外正铁（双高）”；正铁血红蛋白在红细胞内、外是信号分期的关键。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1004", "t": "单选题", "s": "硬膜外血肿CT平扫的典型形态是", "o": {"A": "新月形", "B": "梭形（双凸形）", "C": "脑内类圆形", "D": "环状", "E": "不规则条片状"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-004", "kp": "硬膜外与硬膜下血肿鉴别", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】硬膜外血肿位于硬脑膜与颅骨之间，因硬脑膜在颅缝处与骨缝紧密粘连，血肿被骨缝限制而呈梭形（双凸形），一般不跨越颅缝。【为什么错】A：新月形是硬膜下血肿的典型形态，出血位于硬膜下腔，可跨越颅缝。C：脑内类圆形为脑实质内血肿。D：环状为脓肿、转移瘤等增强后的表现。E：不规则条片状无定位特异性。", "tr": "核心鉴别：“梭形不跨颅缝（硬膜外）vs 新月形跨颅缝（硬膜下）”。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1005", "t": "单选题", "s": "高血压性脑出血最常见的出血部位是", "o": {"A": "丘脑", "B": "壳核", "C": "尾状核头", "D": "苍白球", "E": "内囊膝部"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-005", "kp": "基底节区脑出血部位", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】壳核位于外囊内侧、内囊外侧，是豆纹动脉（出血动脉）供血区，为高血压性脑出血最常见的部位，约占60%，出血常压迫内囊引起对侧偏瘫。【为什么错】A：丘脑出血约占10%～20%，居第二位。C：尾状核头出血少见。D：苍白球出血少见。E：内囊为白质传导束结构，不是出血的起始部位。", "tr": "壳核出血偏外、丘脑出血居内，两者紧邻内囊；答题先看部位再推临床表现。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1006", "t": "单选题", "s": "对超急性期（发病2小时内）脑梗死最敏感的MRI检查序列是", "o": {"A": "T1WI", "B": "T2WI", "C": "弥散加权成像（DWI）", "D": "T2-FLAIR", "E": "磁敏感加权成像（SWI）"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-006", "kp": "超急性期脑梗死序列选择", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】超急性期脑梗死发生细胞毒性水肿，水分子弥散受限，DWI呈高信号、ADC值下降，发病数分钟内即可检出，是目前超急性期脑梗死最敏感的序列。【为什么错】A：T1WI对早期梗死不敏感。B：T2WI在发病12小时内常为阴性。D：FLAIR出现明确异常需数小时以上。E：SWI主要用于显示出血、钙化及静脉，不用于梗死早期检出。", "tr": "“DWI高信号＋ADC低信号”为急性梗死确诊依据；ADC高信号的DWI高信号为T2透射效应（陈旧灶）。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1007", "t": "单选题", "s": "脑膜瘤CT增强扫描的典型强化特点是", "o": {"A": "病灶不强化", "B": "轻度不均匀强化", "C": "明显均匀强化，宽基底贴附硬脑膜", "D": "环形强化", "E": "周边结节样向心性强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-007", "kp": "脑膜瘤CT表现", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】脑膜瘤为富血供、富含血管的良性肿瘤，增强后呈明显均匀强化，多以宽基底贴附硬脑膜并可见脑膜尾征，CT平扫多呈等或稍高密度，可伴钙化。【为什么错】A：脑膜瘤血供丰富，明显强化而非不强化。B：轻度不均匀强化不符其富血供特征。D：环形强化多见于脑脓肿、胶质瘤、转移瘤。E：周边结节状向心性强化是肝血管瘤的增强特点，不适用于脑膜瘤。", "tr": "“脑膜尾征＋明显均匀强化”提示脑膜瘤，但脑膜尾征非其特有，需结合部位与强化方式综合判断。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "脑膜炎", "页": 40}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1008", "t": "单选题", "s": "桥小脑角区最常见的肿瘤是", "o": {"A": "脑膜瘤", "B": "表皮样囊肿（胆脂瘤）", "C": "听神经瘤（前庭神经鞘瘤）", "D": "三叉神经瘤", "E": "脑转移瘤"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-008", "kp": "桥小脑角区肿瘤", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】听神经瘤起源于前庭神经鞘膜，约占桥小脑角区肿瘤的70%～80%，为桥小脑角区最常见肿瘤，常伴患侧内听道扩大，增强后明显强化。【为什么错】A：脑膜瘤在桥小脑角区发生率低于听神经瘤。B：表皮样囊肿呈脑脊液样信号、无强化。D：三叉神经瘤少见。E：转移瘤可累及桥小脑角，但发生率远低于听神经瘤。", "tr": "“桥小脑角肿瘤＋内听道扩大”高度提示听神经瘤；内听道是鉴别要点。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "肿瘤和肿瘤样病变", "节": "鞍区肿瘤", "页": 77}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1009", "t": "单选题", "s": "多发性硬化（MS）累及脑白质的典型MRI表现是", "o": {"A": "基底节区对称性钙化", "B": "侧脑室周围多发斑片状长T1长T2信号，病灶垂直于侧脑室壁", "C": "脑干孤立性占位", "D": "皮层弥漫性强化", "E": "小脑半球大囊小结节"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-009", "kp": "多发性硬化MRI表现", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】MS好发于侧脑室周围、半卵圆中心等脑白质，T2WI、FLAIR呈多发斑片状高信号，病灶沿深静脉周围分布、与侧脑室壁垂直，即“直角脱髓鞘征（Dawson手指征）”，为本病特征。【为什么错】A：基底节对称性钙化见于Fahr病等。C：MS为多发脱髓鞘病灶而非单发占位。D：MS急性病灶可强化但非弥漫皮层强化。E：大囊小结节为血管母细胞瘤表现。", "tr": "“直角脱髓鞘征”是MS特征；与缺血性白质病变相比，MS病灶多发、非皮质下弓状纤维区分布。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "多发性硬化", "页": 45}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1010", "t": "单选题", "s": "颅内最常见的良性肿瘤是", "o": {"A": "听神经瘤", "B": "垂体腺瘤", "C": "脑膜瘤", "D": "血管母细胞瘤", "E": "颅咽管瘤"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-010", "kp": "颅内肿瘤构成", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】脑膜瘤约占颅内原发肿瘤的15%～20%，是颅内最常见的良性肿瘤，多见于中年女性，好发于矢状窦旁、大脑凸面等部位。【为什么错】A：听神经瘤为良性但发生率低于脑膜瘤。B：垂体腺瘤发病率低于脑膜瘤。D：血管母细胞瘤少见，多见于小脑。E：颅咽管瘤多见于儿童。", "tr": "“最常见良性肿瘤＝脑膜瘤”“桥小脑角最常见＝听神经瘤”是两个易混的高频结论。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "颅脑外伤", "节": "外伤性原发性颅内损伤", "页": 24}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1011", "t": "单选题", "s": "患者男，35岁，头痛、共济失调1个月。MRI示右侧小脑半球大囊性病灶，囊壁内见小强化结节，病灶周围可见流空信号血管影。最可能的诊断是", "o": {"A": "小脑脑膜瘤", "B": "血管母细胞瘤", "C": "胶质母细胞瘤", "D": "脑转移瘤", "E": "蛛网膜囊肿"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-011", "kp": "血管母细胞瘤MRI诊断", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】血管母细胞瘤好发于小脑半球，典型表现为“大囊小结节”，囊壁强化结节即富血供肿瘤实质，瘤周可见流空信号的供血动脉及引流静脉，为最常见的小脑原发性肿瘤之一。【为什么错】A：脑膜瘤以宽基底贴脑膜、均匀强化为特征，不呈大囊小结节。C：胶质母细胞瘤好发于中老年幕上白质，呈环形强化伴坏死。D：转移瘤多为多发、小病灶大水肿。E：蛛网膜囊肿为水样信号、无强化结节。", "tr": "“大囊小结节＋囊壁强化结节＋流空血管”是血管母细胞瘤的经典组合，漏看强化小结节易误诊。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "血管畸形", "页": 29}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U07-1012", "t": "单选题", "s": "脑内单发环形强化病灶，壁厚薄不均伴壁结节，瘤周白质明显指状水肿，首先考虑的诊断为", "o": {"A": "脑脓肿", "B": "胶质母细胞瘤", "C": "脑膜瘤", "D": "蛛网膜囊肿", "E": "海绵状血管瘤"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-012", "kp": "胶质母细胞瘤增强特征", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】胶质母细胞瘤血脑屏障破坏明显，增强呈花环样、厚薄不均的环形强化伴壁结节，瘤周水肿沿白质指状蔓延，为成人最常见的原发性恶性脑肿瘤。【为什么错】A：脑脓肿壁光滑均匀，DWI囊腔弥散受限。C：脑膜瘤贴脑膜、均匀明显强化。D：蛛网膜囊肿呈水样密度、无强化。E：海绵状血管瘤多伴含铁血黄素环、呈桑葚样信号，强化程度不一。", "tr": "环形强化鉴别：脓肿“壁光滑＋弥散受限”、胶质瘤“壁厚薄不均＋壁结节”、转移瘤“多发小环”。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "肿瘤和肿瘤样病变", "节": "神经元和混合性神经元-神经胶质肿瘤", "页": 70}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U07-1013", "t": "单选题", "s": "垂体大腺瘤向上生长时最先受压的结构是", "o": {"A": "视交叉", "B": "垂体柄", "C": "海绵窦", "D": "下丘脑", "E": "蝶窦"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-013", "kp": "垂体腺瘤生长方向与毗邻", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】垂体大腺瘤向上突破鞍膈时首先压迫上方的视交叉，临床表现为双颞侧偏盲，是垂体大腺瘤最常见的神经系统表现。【为什么错】B：垂体柄受压可致内分泌紊乱，但位于鞍内、非最先受压。C：海绵窦受压见于肿瘤向侧方生长。D：下丘脑受压少见且较晚。E：蝶窦位于鞍下方，向下方生长才累及。", "tr": "“双颞侧偏盲＝视交叉受压”是垂体大腺瘤的定位体征，也是高频考点。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1014", "t": "单选题", "s": "中耳胆脂瘤CT检查中最具诊断价值的征象是", "o": {"A": "鼓室内单纯软组织密度影", "B": "乳突气房密度增高", "C": "上鼓室盾板破坏伴软组织团块影", "D": "中耳腔积液", "E": "听小骨形态完全正常"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-001", "kp": "中耳胆脂瘤CT表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】胆脂瘤为角化鳞状上皮的异常积聚，CT表现为上鼓室、乳突窦内软组织团块伴骨质破坏（盾板侵蚀、听小骨吸收），骨质破坏是诊断与评估并发症的关键。【为什么错】A：单纯软组织影无特异性。B：气房密度增高见于炎症、积液。D：中耳腔积液为炎性改变。E：胆脂瘤常伴听小骨破坏，不会形态正常。", "tr": "“软组织团块＋骨质破坏”是胆脂瘤核心征象，注意与单纯慢性中耳炎（无骨破坏）鉴别。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1015", "t": "单选题", "s": "喉部最常见的恶性肿瘤及好发部位是", "o": {"A": "腺癌、声门下型", "B": "鳞状细胞癌、声门型", "C": "淋巴瘤、声门上型", "D": "肉瘤、会厌型", "E": "恶性黑色素瘤、喉室型"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-002", "kp": "喉癌病理类型与部位", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】喉癌绝大多数为鳞状细胞癌（约90%以上），以声门型最常见，早期即出现声音嘶哑，CT/MRI显示声带增厚、喉室变形及颈部淋巴结转移。【为什么错】A：喉部腺癌少见。C：淋巴瘤可累及喉但发生率低。D：喉肉瘤罕见。E：恶性黑色素瘤极少原发于喉。", "tr": "“声门型最常见（早嘶哑）”与“声门上型恶性度高、易淋巴结转移”需分别记忆。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1016", "t": "单选题", "s": "甲状腺结节内出现细颗粒状微小钙化，最有助于提示的病理类型是", "o": {"A": "结节性甲状腺肿", "B": "滤泡性腺瘤", "C": "甲状腺乳头状癌", "D": "亚急性甲状腺炎", "E": "单纯性囊肿"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-003", "kp": "甲状腺结节钙化与恶性", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】甲状腺乳头状癌的特征性钙化为沙砾样（砂粒体）微小钙化，超声及CT上结节内细小钙化是提示恶性的最重要征象之一。【为什么错】A：结节性甲状腺肿以粗大钙化、弧形钙化为主。B：腺瘤钙化少见且多粗大。D：亚急性甲状腺炎以甲状腺弥漫性改变为主。E：囊肿无钙化或仅囊壁弧线状钙化。", "tr": "“微小钙化倾向恶性、粗大弧形钙化多为良性”是甲状腺结节钙化判读要点。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1017", "t": "单选题", "s": "鼻窦最常见的恶性肿瘤是", "o": {"A": "淋巴瘤", "B": "嗅神经母细胞瘤", "C": "鳞状细胞癌", "D": "腺样囊性癌", "E": "横纹肌肉瘤"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-004", "kp": "鼻窦恶性肿瘤", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】上颌窦是鼻窦癌最好发部位，鳞状细胞癌占鼻窦恶性肿瘤的绝大多数，CT表现为窦腔软组织肿块伴窦壁溶骨性破坏、可向邻近结构侵犯。【为什么错】A：鼻窦淋巴瘤可发生但少见。B：嗅神经母细胞瘤罕见，多见于嗅区。D：腺样囊性癌多源于涎腺。E：横纹肌肉瘤多见于儿童。", "tr": "“上颌窦＋鳞癌”是鼻窦恶性肿瘤经典组合；儿童鼻窦恶性肿块多考虑横纹肌肉瘤。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1018", "t": "单选题", "s": "眼眶爆裂性骨折最常累及的部位是", "o": {"A": "眶上壁", "B": "眶底（下壁）及眶内侧壁", "C": "眶外侧壁", "D": "眶尖", "E": "泪骨"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-005", "kp": "眼眶爆裂性骨折", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】爆裂性骨折为钝性外力经眼球传导致眶内压骤增，使最薄弱的眶底和眶内侧壁（纸样板）骨折，可伴眶内容疝出、眶内气肿及下直肌嵌顿。【为什么错】A：眶上壁较厚，少见爆裂骨折。C：外侧壁较坚固。D：眶尖骨折少见。E：泪骨极少单独骨折。", "tr": "纸样板极薄易漏诊，CT需适当调整窗宽窗位并结合冠状位重组观察。", "bk": "副高", "ref": {"篇": "头颈部", "章": "眼眶病变", "节": "先天异常", "页": 91}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1019", "t": "单选题", "s": "急性鼻窦炎CT检查中最常见且具诊断意义的征象是", "o": {"A": "窦壁骨质增生硬化", "B": "窦腔内气液平面", "C": "窦腔骨质膨胀扩大", "D": "窦腔内钙化灶", "E": "鼻中隔偏曲"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-006", "kp": "急性鼻窦炎影像表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】急性鼻窦炎时窦黏膜增厚、分泌物潴留，窦腔内出现气液平面是急性炎症的典型表现，配合黏膜增厚即可诊断。【为什么错】A：骨质增生硬化见于慢性鼻窦炎。C：窦腔膨胀扩大多见于黏液囊肿。D：窦内钙化多提示真菌性鼻窦炎。E：鼻中隔偏曲为解剖变异，与炎症无关。", "tr": "“急性看气液平、慢性看骨硬化、真菌看钙化”是鼻窦炎三型鉴别口诀。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1020", "t": "单选题", "s": "自发性气胸X线胸片上最可靠的诊断依据是", "o": {"A": "患侧肺野透亮度增高", "B": "纵隔向健侧移位", "C": "脏层胸膜线（肺压缩边缘线）外侧无肺纹理的透亮区", "D": "膈肌低平", "E": "肋膈角变钝"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-001", "kp": "气胸X线征象", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】气胸时胸膜腔内气体把肺向肺门方向压缩，清晰显示脏层胸膜线即肺压缩边缘，其外侧胸腔区透亮且无肺纹理，是气胸最可靠的X线征象。【为什么错】A：透亮度增高也见于肺气肿。B：仅大量气胸才致纵隔移位。D：膈肌低平见于肺气肿。E：肋膈角变钝提示胸腔积液。", "tr": "“脏层胸膜线＋外侧无肺纹理”是气胸金标准；少量气胸在呼气相更易显示。", "bk": "副高", "ref": {"篇": "胸部", "章": "胸膜疾病", "节": "气胸与液气胸", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1021", "t": "单选题", "s": "立位后前位胸片出现肋膈角变钝，提示游离性胸腔积液量至少约为", "o": {"A": "50 ml", "B": "200 ml", "C": "500 ml", "D": "1000 ml", "E": "2000 ml"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-002", "kp": "胸腔积液的X线定量", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】常规立位后前位胸片上，肋膈角变钝约需胸腔积液量200～300 ml，B项最接近，是少量游离性积液的早期征象。【为什么错】A：50 ml积液在常规立位片上常难以显示。C：500 ml时除肋膈角变钝外已可见外高内低弧形液影，超出“仅肋膈角变钝”的早期范围。D：1000 ml积液已形成大面积致密影。E：2000 ml为大量积液，患侧呈大片致密影并致纵隔移位。", "tr": "“肋膈角变钝≈200 ml以上”，更少量积液可行患侧卧位水平投照或超声检出。", "bk": "副高", "ref": {"篇": "胸部", "章": "胸膜疾病", "节": "胸腔积液", "页": 140}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1022", "t": "单选题", "s": "中央型肺癌致右上叶肺不张时，X线及CT上典型的征象是", "o": {"A": "反S征（横S征）", "B": "空气支气管征", "C": "肺门蝶翼影", "D": "胸膜凹陷征", "E": "空泡征"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-003", "kp": "中央型肺癌阻塞性肺不张", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】右上叶中央型肺癌引起阻塞性肺不张时，肺门上移并呈弧形外凸，与上移的水平裂下缘共同构成“反S”形轮廓，即反S征（Golden S征），是中央型肺癌的经典征象。【为什么错】B：空气支气管征见于肺炎、肺水肿等实变。C：蝶翼影见于肺水肿。D：胸膜凹陷征多见于周围型肺癌。E：空泡征见于肺泡癌等。", "tr": "“反S征＝右上叶中央型肺癌阻塞性不张”；“胸膜凹陷征＝周围型肺癌”两个征象对应关系勿混。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1023", "t": "单选题", "s": "继发性肺结核X线胸片最常见的病灶好发部位是", "o": {"A": "右肺中叶", "B": "双肺上叶尖后段及下叶背段", "C": "双肺基底段", "D": "舌叶外侧段", "E": "肺前段"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-004", "kp": "继发性肺结核好发部位", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】继发性肺结核好发于双肺上叶尖后段及下叶背段，该区域通气较好、血流相对少且淋巴引流不畅，利于结核菌沉积，病灶多呈多形态并存（渗出、增殖、空洞、钙化）。【为什么错】A：右肺中叶炎症多见于肺炎。C：基底段病变多见于坠积性肺炎、吸入性感染。D：舌叶受累较尖后段少见。E：前段少见。", "tr": "“上叶尖后段＋下叶背段”是肺结核经典定位；与肺脓肿（下叶背段多见）需结合临床鉴别。", "bk": "副高", "ref": {"篇": "胸部", "章": "肺感染", "节": "肺结核", "页": 127}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1024", "t": "单选题", "s": "临床确诊肺栓塞（PE）首选的影像学检查方法是", "o": {"A": "X线胸片", "B": "CT肺动脉成像（CTPA）", "C": "超声心动图", "D": "核素肺通气灌注扫描", "E": "磁共振肺动脉成像"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-005", "kp": "肺栓塞检查方法选择", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTPA能直接显示肺动脉腔内血栓形成的充盈缺损，敏感性、特异性高且检查快速，已成为临床确诊肺栓塞的首选检查方法。【为什么错】A：胸片仅能提示肺血减少、楔形影等间接征象。C：超声用于评估右心功能及近端大栓子。D：核素通气灌注扫描假阳性率较高，多用于特殊人群。E：MRPA扫描时间长、伪影多，非首选。", "tr": "CTPA见肺动脉内“充盈缺损”或“截断”为直接征象，是确诊依据。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1025", "t": "单选题", "s": "主动脉夹层CT增强扫描最典型的直接征象是", "o": {"A": "主动脉腔内充盈缺损", "B": "内膜片及真假双腔征", "C": "主动脉壁环形钙化", "D": "主动脉管腔均匀扩张", "E": "心包积液"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-006", "kp": "主动脉夹层CT征象", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】主动脉夹层为内膜撕裂后血流进入中层，形成内膜片将主动脉腔分为真腔与假腔，增强CT清晰显示内膜片（线样低密度）及双腔影，是最重要的直接征象。【为什么错】A：管腔内充盈缺损见于血栓、栓子。C：主动脉壁环形钙化为动脉粥样硬化表现。D：管腔均匀扩张见于主动脉瘤。E：心包积液为夹层累及心包的继发表现。", "tr": "“内膜片＋双腔征”可确诊主动脉夹层；需与壁内血肿（新月形高密度）、穿透性溃疡鉴别。", "bk": "副高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1026", "t": "单选题", "s": "大量心包积液胸部X线片的典型表现是", "o": {"A": "心影呈“靴型”", "B": "心影向两侧普大呈“烧瓶形”、心缘搏动减弱", "C": "心影呈“梨形”", "D": "主动脉结增宽", "E": "左心室段向左下延长"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-007", "kp": "心包积液X线表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】大量心包积液时心影向两侧普遍增大，呈烧瓶形或球形，心缘搏动减弱，而肺野清晰、肺血正常或减少，是心包积液的典型X线表现。【为什么错】A：靴形心见于法洛四联症等。C：梨形心多见于二尖瓣病变。D：主动脉结增宽见于高血压、主动脉病变。E：左心室段延长为左心室增大表现。", "tr": "“烧瓶心＋搏动减弱＋肺野清晰”提示心包积液；超声心动图可确诊并定量。", "bk": "副高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "心包炎", "页": 164}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1027", "t": "单选题", "s": "前纵隔最常见的肿瘤是", "o": {"A": "神经源性肿瘤", "B": "胸腺瘤", "C": "畸胎瘤", "D": "淋巴瘤", "E": "胸内甲状腺肿"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-008", "kp": "纵隔肿瘤定位诊断", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】胸腺瘤位于前纵隔上中部，是前纵隔最常见的肿瘤，多见于成年人，可伴重症肌无力，CT表现为前纵隔软组织肿块。【为什么错】A：神经源性肿瘤多位于后纵隔脊柱旁。C：畸胎类肿瘤好发于前纵隔但发生率低于胸腺瘤。D：淋巴瘤多位于中纵隔。E：胸内甲状腺多位于上纵隔气管前方。", "tr": "“前纵隔＝胸腺瘤、畸胎瘤”“后纵隔＝神经源性肿瘤”“中纵隔＝淋巴瘤”是纵隔肿瘤定位口诀。", "bk": "副高", "ref": {"篇": "胸部", "章": "纵隔疾病", "节": "纵隔肿瘤", "页": 147}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1028", "t": "单选题", "s": "肝海绵状血管瘤CT增强扫描的典型强化特征是", "o": {"A": "动脉期整体均匀强化、门脉期明显减退", "B": "周边结节状强化、随时间向中心充填，延迟期仍呈高或等密度（早出晚归）", "C": "呈“牛眼征”", "D": "增强后无强化", "E": "中心坏死、厚壁环形强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-001", "kp": "肝血管瘤增强表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】海绵状血管瘤由血窦构成、血流缓慢，增强时对比剂自周边血窦向中心渐进性充填，呈“早出晚归”：动脉期周边结节状强化，门脉期及延迟期持续向心填充、延迟期仍为高密度或等密度。【为什么错】A：动脉期均匀强化并迅速廓清为肝细胞癌的“快进快出”表现。C：牛眼征为肝转移瘤特征。D：血管瘤富血供，明显强化。E：厚壁环形强化见于脓肿、转移瘤。", "tr": "“血管瘤早出晚归（向心填充）”与“肝癌快进快出”是腹部增强两大经典鉴别点，必考。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1029", "t": "单选题", "s": "肝细胞癌（HCC）增强CT、MRI典型的血供特征是", "o": {"A": "快进快出（动脉期明显强化、门脉期及延迟期廓清）", "B": "早出晚归（向心性填充）", "C": "进行性延迟强化", "D": "厚壁环形强化", "E": "增强后无强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-002", "kp": "肝细胞癌血供特征", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】HCC为富血供肿瘤，动脉期肿瘤实质明显强化（快进），门脉期及延迟期因对比剂廓清且肿瘤内缺乏正常门静脉供血而密度、信号下降（快出），呈“快进快出”。【为什么错】B：早出晚归为肝血管瘤特征。C：进行性延迟强化见于胆管癌及纤维组织成分。D：环形强化见于转移瘤、脓肿。E：HCC明显强化而非无强化。", "tr": "肝硬化背景下“快进快出”结节高度提示HCC，是LI-RADS主要征象之一。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1030", "t": "单选题", "s": "肝囊肿CT平扫的典型表现是", "o": {"A": "类圆形高密度灶", "B": "边界清楚、壁薄的近似水样低密度灶", "C": "混杂密度灶", "D": "团块状钙化灶", "E": "环形强化灶"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-003", "kp": "肝囊肿CT表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】单纯性肝囊肿为囊性病变，CT表现为边界清晰锐利、壁薄、CT值近似水的低密度灶，增强扫描无强化。【为什么错】A：高密度见于血肿、钙化。C：混杂密度见于肿瘤坏死、出血。D：钙化见于寄生虫病（包虫）等。E：环形强化提示脓肿、转移瘤。", "tr": "囊肿“水样密度＋无强化”，与肝脓肿（环形强化）、HCC（富血供）的鉴别关键在增强扫描。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1031", "t": "单选题", "s": "急性水肿型胰腺炎CT表现中，下列哪项最符合其典型改变", "o": {"A": "胰腺萎缩伴散在钙化", "B": "胰腺弥漫增大、密度不均匀，胰周脂肪间隙模糊伴渗出，增强扫描无坏死区", "C": "胰头部囊实性肿块", "D": "胰腺内多发富血供强化结节", "E": "肝内外胆管明显扩张"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-004", "kp": "急性水肿型胰腺炎CT表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】急性水肿型胰腺炎CT显示胰腺弥漫性增大、边缘模糊、胰周脂肪密度增高（渗出、皂化），增强扫描胰腺实质均匀强化、无坏死区，此为水肿型与坏死型鉴别的关键。【为什么错】A：胰腺萎缩伴钙化为慢性胰腺炎表现。C：胰头囊实性肿块见于胰腺癌等。D：富血供强化结节为富血供肿瘤表现。E：胆管扩张提示胰头占位、壶腹病变。", "tr": "“水肿型均匀强化”与“坏死型无强化低密度区”的鉴别必须依靠增强扫描。", "bk": "副高", "ref": {"篇": "腹部", "章": "胆道", "节": "急性化脓性胆管炎", "页": 195}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1032", "t": "单选题", "s": "小肠机械性肠梗阻立位腹部X线平片的典型征象是", "o": {"A": "膈下游离气体", "B": "阶梯状排列的气液平面", "C": "双泡征", "D": "结肠充气扩张", "E": "腹壁脂肪线消失"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-005", "kp": "肠梗阻X线征象", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】小肠机械性梗阻时梗阻近端小肠扩张、积气积液，立位片可见多个呈阶梯状排列的气液平面，结肠内气体减少，是机械性肠梗阻的典型X线表现。【为什么错】A：膈下游离气体提示消化道穿孔。C：双泡征见于十二指肠梗阻及婴幼儿幽门梗阻。D：结肠充气扩张见于低位结肠梗阻。E：腹壁脂肪线消失提示腹膜炎。", "tr": "“阶梯状气液平面＝小肠梗阻”“双泡征＝十二指肠梗阻”“结肠充气＝结肠梗阻”。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1033", "t": "单选题", "s": "疑消化道穿孔时，立位腹部X线检查最具诊断价值的征象是", "o": {"A": "肠管普遍扩张", "B": "膈肌下方新月形游离气体影", "C": "盆腔积液", "D": "腰大肌影模糊", "E": "脊柱向一侧弯曲"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-006", "kp": "消化道穿孔气腹征", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】胃肠穿孔后气体进入腹腔，立位X线显示膈肌下方新月形、镰刀状游离气体影，是消化道穿孔最直接可靠的征象。【为什么错】A：肠管扩张为肠梗阻表现。C：盆腔积液无特异性。D：腰大肌影模糊提示腹膜后及腹膜炎症。E：脊柱弯曲为反射性表现，无特异性。", "tr": "少量气腹需立位或左侧卧位水平投照观察，右膈下气体最易显示。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1034", "t": "单选题", "s": "子宫肌瘤在MRI上最典型的信号特点是", "o": {"A": "T2WI呈均匀高信号", "B": "边界清楚，T2WI呈低信号", "C": "T1WI呈明显高信号", "D": "增强呈快进快出", "E": "DWI明显弥散受限"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-001", "kp": "子宫肌瘤MRI表现", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】子宫肌瘤主要由平滑肌与纤维结缔组织构成、含水量低，T2WI呈低信号为其特征，T1WI呈等信号；富细胞型、变性的肌瘤信号可变。【为什么错】A：T2WI高信号见于囊变、肌瘤变性或子宫内膜病变。C：T1WI高信号见于出血、脂肪成分。D：快进快出为富血供肿瘤特征，肌瘤为渐进性强化。E：肌瘤通常无明显弥散受限。", "tr": "“T2WI低信号肿块”是肌瘤特征；黏膜下肌瘤需与子宫内膜息肉鉴别。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1035", "t": "单选题", "s": "前列腺癌在MRI（T2WI）上的典型表现是", "o": {"A": "外周带正常高信号", "B": "外周带出现结节状低信号灶", "C": "中央带呈高信号", "D": "整个前列腺均匀低信号", "E": "外周带弥漫性高信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-002", "kp": "前列腺癌MRI表现", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】前列腺外周带T2WI呈均匀高信号，前列腺癌多起源于外周带，表现为外周带结节状低信号灶，为MRI检出前列腺癌的重要征象，需结合DWI、动态增强及MRS综合判断。【为什么错】A：外周带高信号为正常表现。C：中央带（移行带）增生多呈中等信号。D：均匀低信号无诊断特异性。E：弥漫高信号不符。", "tr": "“外周带T2WI低信号结节”提示癌，但慢性前列腺炎、活检后瘢痕亦可呈低信号，需多参数MRI结合。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "前列腺癌", "页": 236}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1036", "t": "单选题", "s": "子宫内膜癌MRI检查中，评价肿瘤肌层浸润深度最重要的序列是", "o": {"A": "矢状位T2WI及动态增强扫描", "B": "轴位T1WI平扫", "C": "冠状位STIR", "D": "SWI", "E": "磁敏感加权成像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-003", "kp": "子宫内膜癌分期序列", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】矢状位T2WI及动态增强（DCE-MRI）可清晰显示子宫内膜与肌层的界面及强化差异，是判断肌层浸润深度（≥1/2为深浸润）的关键序列。【为什么错】B：T1WI平扫不能显示内膜—肌层分界。C：STIR主要用于骨髓及脂肪抑制。D：SWI用于显示出血、钙化及静脉，不用于浸润分期。E：磁敏感加权成像同SWI，不用于浸润分期评估。", "tr": "“矢状位＋动态增强”是子宫内膜癌分期的黄金方案，浸润深度直接影响治疗选择。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "子宫内膜癌", "页": 247}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1037", "t": "单选题", "s": "Colles骨折的典型X线表现及移位特点是", "o": {"A": "桡骨远端骨折，远折端向背侧、桡侧移位呈“餐叉样”畸形", "B": "桡骨远端骨折，远折端向掌侧移位", "C": "尺骨远端向桡侧脱位", "D": "掌骨基底骨折", "E": "舟骨腰部骨折"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-001", "kp": "Colles骨折X线", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】Colles骨折即桡骨远端伸直型骨折，跌倒手掌撑地所致，远折端向背侧、桡侧移位，侧位观呈“餐叉样”畸形，为成人最常见的桡骨远端骨折。【为什么错】B：远折端向掌侧移位为Smith骨折（反Colles骨折）。C：尺骨远端移位描述错误。D：掌骨基底骨折为Bennett骨折相关。E：舟骨腰部骨折属腕舟骨骨折。", "tr": "Colles（背移）与Smith（掌移）是最易混淆的一对腕部骨折，注意移位方向。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1038", "t": "单选题", "s": "骨肉瘤最典型的X线征象是", "o": {"A": "日光放射状骨膜反应伴肿瘤骨", "B": "骨端偏心性皂泡样膨胀", "C": "葱皮样骨膜反应", "D": "骨内多发小圆形透亮区", "E": "以关节面破坏为主"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-002", "kp": "骨肉瘤X线表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】骨肉瘤为高度恶性骨肿瘤，肿瘤骨形成是其病理特征，X线表现为溶骨性或成骨性破坏、Codman三角、日光放射状骨膜反应及云絮状或象牙质样瘤骨，好发于青少年长骨干骺端。【为什么错】B：皂泡样膨胀性破坏为骨巨细胞瘤特征。C：葱皮样骨膜反应见于尤因肉瘤。D：多发小透亮区描述不特异。E：骨肉瘤以干骺端破坏为主，关节面破坏少见。", "tr": "“日光放射状＋Codman三角＋瘤骨”三征象对应骨肉瘤；“葱皮样”对应尤因肉瘤。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1039", "t": "单选题", "s": "腰椎间盘突出症MRI矢状位T2WI最直接的诊断依据是", "o": {"A": "椎体终板T1WI高信号", "B": "椎间盘后缘局限性向后突出，压迫硬膜囊或神经根", "C": "椎管前后径普遍狭窄", "D": "黄韧带增厚", "E": "椎体前缘骨桥形成"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-003", "kp": "椎间盘突出MRI征象", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】矢状位T2WI可清晰显示椎间盘退变（髓核信号降低）及纤维环破裂后髓核局限性向后突出，硬膜囊受压、神经根受压移位，是椎间盘突出的直接诊断依据。【为什么错】A：终板信号改变为Modic改变，属继发征象。C：椎管普遍狭窄多因退变性骨增生。D：黄韧带肥厚为继发退变。E：椎体前缘骨桥为脊柱关节病表现。", "tr": "“膨出（后缘弧形完整）→突出（局限破出压迫）→脱出（游离）”三级须分清。", "bk": "副高", "ref": {"篇": "骨与骨关节", "章": "脊柱退行性病变", "节": "椎间盘及椎骨的退变过程", "页": 285}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1040", "t": "单选题", "s": "骨巨细胞瘤X线最典型的征象是", "o": {"A": "骨干中心性溶骨伴葱皮样骨膜反应", "B": "骨端偏心性、膨胀性皂泡样溶骨破坏，一般无骨膜反应", "C": "皮质环形增厚", "D": "骨内日光放射状瘤骨", "E": "全身多发性病灶"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-004", "kp": "骨巨细胞瘤X线表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】骨巨细胞瘤好发于20～40岁长骨骨端，X线表现为骨端偏心性、膨胀性、皂泡样或分房状溶骨性破坏，皮质变薄，一般无骨膜反应。【为什么错】A：葱皮样骨膜反应为尤因肉瘤特征。C：皮质环形增厚不符。D：日光放射状瘤骨为骨肉瘤。E：骨巨细胞瘤多为单发。", "tr": "“骨端偏心皂泡样”是骨巨细胞瘤经典描述，与骨肉瘤（干骺端＋骨膜反应）鉴别。", "bk": "副高", "ref": {"篇": "骨与骨关节", "章": "硬膜外肿瘤和肿瘤样病变", "节": "骨巨细胞瘤", "页": 298}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1041", "t": "单选题", "s": "老年性骨质疏松性椎体压缩骨折X线及MRI的典型表现是", "o": {"A": "椎体后缘骨性融合", "B": "椎体前缘高度减小呈楔形变，急性期T1WI低信号、T2WI及脂肪抑制序列高信号", "C": "椎体溶骨性破坏", "D": "椎旁软组织肿块", "E": "椎弓根骨质破坏消失"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-005", "kp": "椎体压缩骨折鉴别", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】骨质疏松性压缩骨折表现为椎体楔形变（前缘高度丢失），急性期骨髓水肿使T1WI低信号、T2WI及脂肪抑制序列（STIR）高信号，骨髓信号随愈合恢复。【为什么错】A：骨性融合为炎症愈合后表现。C：溶骨性破坏多见于转移瘤。D：椎旁软组织肿块提示肿瘤性病变。E：椎弓根破坏（pedicle sign）为恶性转移的重要征象。", "tr": "“椎弓根破坏”是鉴别骨质疏松性压缩骨折与恶性病理性骨折的关键点。", "bk": "副高", "ref": {"篇": "基础概念（绪论）", "章": "基本概念（X线物理/对比剂/成像基础）", "节": "骨质疏松", "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1042", "t": "单选题", "s": "影像学诊断主动脉瘤的标准是", "o": {"A": "主动脉局部管径较相邻正常段扩大超过50%", "B": "主动脉壁钙化", "C": "主动脉腔内血栓", "D": "主动脉弓迂曲延长", "E": "主动脉腔内见内膜片"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-001", "kp": "主动脉瘤诊断标准", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】动脉瘤定义为动脉局部管径较相邻正常段扩大50%以上（如腹主动脉直径＞3 cm或超过相邻正常段1.5倍），影像学据此诊断。【为什么错】B：主动脉壁钙化为动脉粥样硬化表现。C：腔内血栓可为动脉瘤伴发改变但非诊断标准。D：迂曲延长为退行性改变。E：内膜片提示主动脉夹层。", "tr": "“直径＞正常段1.5倍”或“腹主动脉＞3 cm”为动脉瘤诊断阈值。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "动脉瘤", "页": 33}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1043", "t": "单选题", "s": "下肢深静脉血栓静脉造影（DSA）最直接可靠的征象是", "o": {"A": "静脉腔内造影剂充盈缺损", "B": "静脉壁线状钙化", "C": "静脉普遍扩张", "D": "周围软组织肿胀", "E": "邻近骨膜反应"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-002", "kp": "下肢深静脉血栓DSA征象", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】深静脉血栓造影时血栓占据部分管腔形成腔内充盈缺损，若血栓完全闭塞则静脉段不显影，均是最直接可靠的征象。【为什么错】B：静脉壁钙化少见且非直接征象。C：静脉扩张为非特异改变。D：软组织肿胀为继发表现。E：骨膜反应与静脉病变无关。", "tr": "“腔内充盈缺损”“静脉不显影”“侧支循环建立”是深静脉血栓造影三大征象。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1044", "t": "单选题", "s": "评估颈动脉狭窄程度最精确、作为金标准的血管成像方法是", "o": {"A": "CT血管成像（CTA）", "B": "彩色多普勒超声", "C": "数字减影血管造影（DSA）", "D": "磁共振血管成像（MRA）", "E": "X线平片"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-003", "kp": "颈动脉狭窄评估方法", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】DSA空间分辨力高、可动态显示血流，是评估血管管腔狭窄程度及血管病变的金标准，也是介入治疗的依据。【为什么错】A：CTA为无创，能显示斑块钙化但对细小血管及迂曲段狭窄率测量仍有偏差。B：超声为常用筛查方法。D：MRA可能夸大狭窄程度。E：X线平片不能显示血管腔。", "tr": "“超声筛查→CTA/MRA无创评估→DSA金标准”是颈动脉狭窄检查路径。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "总论", "节": "头颅CT检查方法", "页": 12}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1045", "t": "单选题", "s": "外周神经MRI（MR神经成像）中，受损神经的典型表现是", "o": {"A": "神经增粗、T2WI信号增高、内部束状结构显示不清", "B": "神经变细、T1WI高信号", "C": "神经钙化", "D": "神经周围气体", "E": "神经信号无任何改变"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-004", "kp": "外周神经损伤MRI表现", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (3)MR诊断要点", "ex": "【为什么对】外周神经损伤后神经水肿、神经束膜增厚，MR神经成像（MRN）表现为神经增粗、T2WI及脂肪抑制序列信号增高、束状结构显示不清，增强可强化。【为什么错】B：受损神经增粗而非变细，T1WI高信号多见于脂肪或出血。C：神经钙化少见。D：神经周围气体见于外伤产气。E：正常神经无改变。", "tr": "“神经增粗＋T2WI高信号”是神经卡压、损伤的MRN核心表现，需与神经鞘瘤（偏心强化）鉴别。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1101", "t": "多选题", "s": "关于脑转移瘤MRI表现，正确的有", "o": {"A": "多为多发圆形病灶", "B": "增强呈结节状或环形强化", "C": "瘤周水肿明显，呈“小病灶大水肿”", "D": "DWI可显示病灶弥散受限程度不一", "E": "所有病灶T2WI均呈均匀低信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-014", "kp": "脑转移瘤MRI表现", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】脑转移瘤多为多发圆形、类圆形病灶，增强后呈结节状或环形强化，瘤周水肿明显呈小病灶大水肿，DWI上弥散受限程度因肿瘤类型而异。【为什么错】E：转移瘤T2WI多呈高信号，病灶中心坏死囊变时信号更高、不均，并非均匀低信号。", "tr": "“小病灶大水肿＋多发＋环形强化”是转移瘤三联征；单发转移与胶质瘤的鉴别需结合全身筛查。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1102", "t": "多选题", "s": "超急性期脑梗死CT早期可显示的征象有", "o": {"A": "岛带（岛叶皮层）模糊消失", "B": "大脑中动脉高密度征（致密动脉征）", "C": "灰白质界限模糊", "D": "患侧脑沟普遍增宽", "E": "侧脑室明显扩张变形"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-015", "kp": "超急性期脑梗死CT早期征象", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】超急性期脑梗死CT可显示岛带模糊、大脑中动脉高密度征、灰白质界限消失等早期征象，提示大面积梗死，为临床溶栓决策提供依据。【为什么错】D：患侧脑沟增宽、E：脑室扩张变形均为慢性期脑萎缩、梗死软化灶的晚期表现，不是超急性期征象。", "tr": "“岛带征、致密动脉征、灰白质界限消失”是梗死早期三大征象，代表大面积MCA区梗死。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1103", "t": "多选题", "s": "关于脑膜瘤MRI表现，正确的有", "o": {"A": "T1WI多呈等信号", "B": "T2WI呈等或稍高信号", "C": "增强后明显均匀强化", "D": "可见“脑膜尾征”", "E": "增强后无强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-016", "kp": "脑膜瘤MRI表现", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】脑膜瘤T1WI、T2WI多呈等或稍高信号，增强后明显均匀强化，常伴宽基底贴附硬脑膜及“脑膜尾征”，DWI多不受限。【为什么错】E：脑膜瘤为富血供肿瘤，增强后明显均匀强化，不会无强化。", "tr": "脑膜瘤“等T1等T2＋明显强化＋脑膜尾征”；脑膜尾征也可见于结节病、转移瘤脑膜受累，非特有。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "脑膜炎", "页": 40}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1104", "t": "多选题", "s": "鼻骨骨折CT检查的常见征象有", "o": {"A": "鼻骨骨质连续性中断", "B": "碎骨片移位", "C": "周围软组织肿胀", "D": "上颌窦黏液囊肿", "E": "额窦窦壁骨质增生硬化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-007", "kp": "鼻骨骨折CT表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】鼻骨骨折CT表现为鼻骨骨质连续性中断、碎骨片移位错位、周围软组织肿胀，合并鼻中隔骨折时可见鼻中隔偏曲变形。【为什么错】D：上颌窦黏液囊肿为窦口阻塞的囊性病变，与外伤无关。E：额窦窦壁增生硬化为慢性炎症改变，非骨折表现。", "tr": "薄层CT（层厚≤1 mm）结合冠矢状位重组是显示细微鼻骨骨折的关键。", "bk": "副高", "ref": {"篇": "头颈部", "章": "耳和颞骨", "节": "颞骨骨折", "页": 88}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1105", "t": "多选题", "s": "急性中耳乳突炎CT表现的常见征象有", "o": {"A": "鼓室黏膜增厚、鼓室内软组织影", "B": "乳突气房混浊、密度增高", "C": "鼓室内气液平面", "D": "内听道明显扩大", "E": "岩尖骨质破坏"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-008", "kp": "急性中耳乳突炎CT表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】急性中耳乳突炎CT表现为鼓室黏膜增厚、鼓室内软组织影及气液平面，乳突气房混浊、密度增高，气房间隔可增粗。【为什么错】D：内听道扩大为听神经瘤的征象。E：岩尖骨质破坏提示岩尖部病变或胆脂瘤、恶性肿瘤，单纯急性中耳乳突炎不出现。", "tr": "急性中耳炎“软组织＋气液平”；胆脂瘤“软组织＋骨质破坏”；两者鉴别看骨壁。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1106", "t": "多选题", "s": "提示甲状腺结节为恶性的影像学征象有", "o": {"A": "结节内微小钙化（沙砾样钙化）", "B": "边缘不规则、呈分叶状", "C": "超声表现为低回声", "D": "伴颈部区域淋巴结肿大", "E": "以单纯囊性变为主"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-009", "kp": "甲状腺恶性结节征象", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】微小钙化、边缘不规则或分叶、低回声及淋巴结转移均提示甲状腺结节恶性倾向，应结合细针穿刺活检明确。【为什么错】E：以单纯囊性变为主的结节多为良性（腺瘤囊变、胶质囊肿），但囊壁明显增厚或囊内实性成分时仍需警惕。", "tr": "“微钙化＋边缘不规＋低回声＋淋巴结”为恶性四征；单纯囊变偏向良性但需结合整体。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1107", "t": "多选题", "s": "鼻咽癌CT常见的直接与间接征象有", "o": {"A": "鼻咽顶后壁及侧壁软组织增厚形成肿块", "B": "咽隐窝变浅、消失", "C": "咽旁间隙受累", "D": "颅底骨质破坏", "E": "肿块内密集钙化灶"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-010", "kp": "鼻咽癌CT表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】鼻咽癌以咽隐窝为中心生长，CT示鼻咽壁软组织肿块、咽隐窝消失，可侵犯咽旁间隙、颅底骨质，并伴颈部淋巴结转移。【为什么错】E：鼻咽癌内钙化少见，密集钙化灶更常见于脊索瘤等含钙化病变。", "tr": "“咽隐窝消失＋咽旁间隙受侵＋颅底骨破坏”是鼻咽癌侵犯评估要点，咽旁间隙脂肪层消失提示受侵。", "bk": "副高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "鼻咽部病变", "页": 103}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-1108", "t": "多选题", "s": "气胸CT检查的典型表现有", "o": {"A": "脏层胸膜线清晰可见", "B": "胸腔内无肺纹理的透亮区", "C": "肺组织受压、肺不张", "D": "大量气胸时纵隔向健侧移位", "E": "常合并大量胸腔积液"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-009", "kp": "气胸CT表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CT能清晰显示气胸的脏层胸膜线、无肺纹理的胸腔透亮区及受压不张的肺组织，大量气胸可致纵隔移位、膈肌下降。【为什么错】E：单纯气胸不含并大量积液；血气胸时才出现液气平面。", "tr": "CT对少量气胸及伴发肺大疱的检出优于X线，是评估复发及术前检查手段。", "bk": "副高", "ref": {"篇": "胸部", "章": "胸膜疾病", "节": "气胸与液气胸", "页": 142}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1109", "t": "多选题", "s": "肺栓塞CTPA的常见征象有", "o": {"A": "肺动脉内充盈缺损", "B": "肺动脉分支截断", "C": "肺外周楔形实变影（肺梗死）", "D": "右心室增大", "E": "主动脉壁环形钙化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-010", "kp": "肺栓塞CTPA征象", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTPA直接征象为肺动脉内充盈缺损及血管截断，间接征象包括肺梗死（楔形实变）、右心室增大、胸腔积液等。【为什么错】E：主动脉壁环形钙化为动脉粥样硬化表现，与肺栓塞无关。", "tr": "急性PE评估还需观察右心功能（RV/LV比值）、血栓位于中心或外周，直接影响治疗策略。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1110", "t": "多选题", "s": "主动脉夹层CTA检查可显示的征象有", "o": {"A": "内膜片将主动脉腔分为真假双腔", "B": "真腔较小、血流快，假腔较大、可伴血栓", "C": "增强扫描可显示内膜破口", "D": "可显示分支血管受累及灌注异常", "E": "主动脉壁环形钙化为最直接征象"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-011", "kp": "主动脉夹层CTA全面评估", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTA可显示内膜片、真假双腔、破口位置、假腔血栓及分支血管（冠脉、头臂干、内脏动脉）受累情况，是术前评估的金标准之一。【为什么错】E：主动脉壁环形钙化是动脉粥样硬化表现，而非夹层直接征象。", "tr": "Stanford分型看升主动脉是否受累（A型累及升主动脉）；DebakeyⅠ、Ⅱ、Ⅲ分型勿混淆。", "bk": "副高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-1111", "t": "多选题", "s": "中央型肺癌CT的常见表现有", "o": {"A": "肺门区肿块", "B": "支气管管腔狭窄或截断", "C": "阻塞性肺不张", "D": "阻塞性肺炎", "E": "两肺弥漫性粟粒样小结节"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-012", "kp": "中央型肺癌CT表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】中央型肺癌CT表现为肺门肿块、支气管狭窄或截断，继发阻塞性肺不张、阻塞性肺炎及远端黏液潴留。【为什么错】E：两肺弥漫粟粒样结节为急性粟粒型肺结核表现，与中央型肺癌无直接关系。", "tr": "“阻塞性肺不张＋肺门肿块”是中央型肺癌特征；阻塞性肺炎反复不吸收应警惕肿瘤。", "bk": "副高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "心脏大血管病变的基本CT表现", "页": 158}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1112", "t": "多选题", "s": "肝海绵状血管瘤MRI的典型表现有", "o": {"A": "T2WI呈明显高信号（灯泡征）", "B": "增强周边结节状强化、向心性填充", "C": "延迟期持续强化呈等或高信号", "D": "动脉期整体强化并迅速廓清", "E": "增强后无强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-007", "kp": "肝血管瘤MRI表现", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】血管瘤T2WI呈显著高信号，即“灯泡征”，动态增强呈周边结节状强化并随时间向心性充填，延迟期仍持续强化，为“早出晚归”。【为什么错】D：动脉期整体强化并迅速廓清为肝癌“快进快出”表现。E：血管瘤富血供，明显强化而非无强化。", "tr": "“重T2WI灯泡征＋向心性充填＋延迟持续强化”是血管瘤MRI三联征。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1113", "t": "多选题", "s": "肝细胞癌（HCC）CT增强扫描的典型表现有", "o": {"A": "动脉期肿瘤明显强化（快进）", "B": "门脉期及延迟期强化减退（快出）", "C": "可见假包膜", "D": "可伴门静脉癌栓", "E": "延迟期仍明显强化、廓清不明显"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-008", "kp": "肝细胞癌CT表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】HCC动脉期明显强化，门脉期、延迟期廓清呈低密度，部分病灶可见假包膜，可侵犯门静脉形成癌栓及肝内转移。【为什么错】E：延迟期明显强化、廓清不明显是血管瘤或胆管癌表现，HCC为廓清型。", "tr": "“动脉期强化＋门脉期廓清＋假包膜＋门脉癌栓”为HCC典型组合；癌栓是肿瘤血行转移证据。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1114", "t": "多选题", "s": "急性胰腺炎CT的常见表现有", "o": {"A": "胰腺弥漫性增大", "B": "胰周脂肪密度增高、渗出", "C": "肾前筋膜增厚", "D": "病程中可并发假性囊肿", "E": "胰腺萎缩伴钙化"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-009", "kp": "急性胰腺炎CT表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】急性胰腺炎CT示胰腺增大、胰周脂肪渗出密度增高、肾前筋膜增厚，重症可伴坏死、液体积聚，后期可形成假性囊肿。【为什么错】E：胰腺萎缩伴钙化为慢性胰腺炎的典型表现。", "tr": "增强CT是判断胰腺坏死的关键；CT严重指数（CTSI）结合坏死范围评估预后。", "bk": "副高", "ref": {"篇": "腹部", "章": "胰腺", "节": "急性胰腺炎", "页": 196}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U07-1115", "t": "多选题", "s": "关于肾结石影像学表现，正确的有", "o": {"A": "腹部平片可见肾盂内高密度结石影", "B": "鹿角形结石为肾盂肾盏铸型结石", "C": "结石可继发肾盂肾盏扩张积水", "D": "尿酸结石在X线平片上可不显影", "E": "增强扫描后结石明显强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-010", "kp": "肾结石影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】阳性结石（含钙）平片呈高密度，鹿角形结石铸型于肾盂肾盏，结石梗阻可致积水；尿酸结石密度低、平片可不显影，但CT均能显示。【为什么错】E：结石不摄取对比剂，增强扫描后不强化。", "tr": "“阴性结石（尿酸）X线不显影但CT可显示”，CT是尿路结石最敏感的检查。", "bk": "副高", "ref": {"篇": "腹部", "章": "肾感染性病变", "节": "肾结核", "页": 220}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1116", "t": "多选题", "s": "关于消化道穿孔影像学表现，正确的有", "o": {"A": "立位X线示膈下新月形游离气体影", "B": "左侧卧位水平投照可显示肝表面少量游离气体", "C": "十二指肠腹膜后段穿孔可显示腹膜后气肿", "D": "CT可发现平片阴性的少量气腹", "E": "肠管阶梯状排列的气液平面为穿孔特征性表现"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-011", "kp": "消化道穿孔影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】消化道穿孔以膈下游离气体为主要征象，少量气腹需左侧卧位水平投照或CT检出，腹膜后穿孔可致腹膜后积气，CT对少量气腹敏感。【为什么错】E：阶梯状气液平面是机械性肠梗阻的表现，不是穿孔特征。", "tr": "气腹量少时“左侧卧位水平投照＋CT薄层”是关键；穿孔部位不同气体分布各异。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1117", "t": "多选题", "s": "子宫肌瘤MRI的常见表现有", "o": {"A": "T2WI呈低信号", "B": "黏膜下肌瘤可使宫腔受压变形", "C": "浆膜下肌瘤向子宫外突出", "D": "变性的肌瘤信号可不均匀", "E": "所有肌瘤T2WI均呈均匀高信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-004", "kp": "子宫肌瘤MRI表现", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】肌瘤T2WI多呈低信号，按位置分黏膜下、肌壁间、浆膜下，分别引起宫腔变形、宫腔受压和向外突出；玻璃样变、囊变、红色变性时信号不均。【为什么错】E：肌瘤典型信号为低信号而非高信号，且变性时信号不均。", "tr": "肌瘤位置决定症状与术式；“富细胞肌瘤”可呈高信号，需与平滑肌肉瘤鉴别。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1118", "t": "多选题", "s": "提示卵巢囊性病变为恶性的影像学征象有", "o": {"A": "囊壁增厚、不规则", "B": "囊壁或分隔上的实性结节", "C": "分隔增厚（＞3 mm）", "D": "伴腹水或腹膜种植", "E": "单纯薄壁、均匀水样囊肿"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-005", "kp": "卵巢恶性肿瘤征象", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (2)CT诊断要点", "ex": "【为什么对】囊壁增厚不规则、实性壁结节、增厚分隔、腹水及腹膜种植均提示卵巢恶性肿瘤；囊实混合性肿块伴腹水为晚期表现。【为什么错】E：单纯薄壁均匀水样囊肿为典型良性表现（单纯性囊肿）。", "tr": "卵巢囊性肿块“实性成分是恶性的核心指标”，结合CA125及年龄综合判断。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢畸胎瘤", "页": 240}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1119", "t": "多选题", "s": "多参数MRI诊断前列腺癌的典型表现有", "o": {"A": "外周带T2WI结节状低信号", "B": "DWI呈高信号、ADC值降低", "C": "动态增强早期快速强化", "D": "可侵犯精囊腺及神经血管束", "E": "MRS示枸橼酸盐峰明显升高"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-006", "kp": "前列腺癌多参数MRI", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】前列腺癌MRI表现为外周带T2WI低信号结节、DWI高信号ADC降低、动态增强早期强化，并可见包膜外侵犯、精囊受累；MRS示枸橼酸盐降低、胆碱升高。【为什么错】E：前列腺癌MRS特征为枸橼酸盐峰降低、胆碱峰升高，而非枸橼酸盐升高。", "tr": "“T2低＋DWI高＋早期强化”提示癌；MRS“枸橼酸低、胆碱高”是代谢特征。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "前列腺癌", "页": 236}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1120", "t": "多选题", "s": "腰椎间盘突出MRI的常见表现有", "o": {"A": "椎间盘后缘局限性突出", "B": "硬膜囊受压变形", "C": "神经根受压移位", "D": "脱出的髓核可游离于椎管内", "E": "椎体前缘骨桥为直接诊断依据"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-006", "kp": "椎间盘突出MRI表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】MRI矢状位及轴位可显示椎间盘后缘局限性突出、硬膜囊及神经根受压，髓核完全脱出时可游离至椎管内上下移动。【为什么错】E：椎体前缘骨桥是脊柱退变（DISH、脊柱关节病）表现，与椎间盘突出无直接关系。", "tr": "“突出—脱出—游离”以纤维环破裂及髓核位置划分；中央型与旁中央型压迫结构不同。", "bk": "副高", "ref": {"篇": "骨与骨关节", "章": "脊柱退行性病变", "节": "椎间盘及椎骨的退变过程", "页": 285}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1121", "t": "多选题", "s": "骨肉瘤X线的典型表现有", "o": {"A": "溶骨性或成骨性骨质破坏", "B": "肿瘤骨形成", "C": "Codman三角", "D": "日光放射状骨膜反应", "E": "葱皮样骨膜反应为其最特征表现"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-007", "kp": "骨肉瘤X线表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】骨肉瘤以骨质破坏、肿瘤骨、Codman三角及日光放射状骨膜反应为典型X线表现，肿瘤骨是确诊的组织学依据。【为什么错】E：葱皮样骨膜反应为尤因肉瘤的典型表现，不是骨肉瘤特征。", "tr": "骨肉瘤“日光放射状”，尤因肉瘤“葱皮样”，软骨肉瘤“环状钙化”，三骨肿瘤骨膜反应对比。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1122", "t": "多选题", "s": "股骨颈骨折按骨折线部位分型，正确的类型有", "o": {"A": "头下型", "B": "头颈型", "C": "经颈型", "D": "基底型", "E": "转子间型"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-008", "kp": "股骨颈骨折分型", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】股骨颈骨折按骨折线所在部位分为头下型、头颈型、经颈型、基底型，头下型血供破坏最重、股骨头缺血坏死发生率最高。【为什么错】E：转子间骨折位于股骨颈基底以远的小转子上下区域，不属于股骨颈骨折分型。", "tr": "“头下型易缺血坏死”是分型意义所在；转子间骨折血供好、愈合快，两者预后不同。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1123", "t": "多选题", "s": "骨性关节病（骨关节退行性变）X线的典型表现有", "o": {"A": "关节间隙变窄", "B": "关节面边缘骨赘形成", "C": "软骨下骨质硬化", "D": "关节面下囊性变", "E": "关节软骨钙化呈“双轨征”为最常见表现"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-009", "kp": "骨性关节病X线表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】骨性关节病以关节间隙非对称性变窄、骨赘、软骨下硬化及囊变为基本X线表现，好发于承重大关节。【为什么错】E：关节软骨钙化（双轨征）为焦磷酸盐沉积病（CPPD）表现，不是退行性骨关节病的常见特征。", "tr": "“关节间隙窄＋骨赘＋硬化”为骨性关节炎三征；软骨钙化另属晶体性关节病。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1124", "t": "多选题", "s": "下肢深静脉血栓静脉造影（DSA）的典型征象有", "o": {"A": "静脉腔内充盈缺损", "B": "静脉段不显影（闭塞）", "C": "侧支循环建立", "D": "静脉石钙化为直接征象", "E": "动脉期提前显影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-005", "kp": "下肢深静脉血栓DSA征象", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】深静脉血栓造影直接征象为腔内充盈缺损，完全闭塞时该段静脉不显影，并见侧支循环开放迂曲。【为什么错】D：静脉石为静脉内陈旧血栓钙化形成的小钙化点，不是造影直接征象。E：动脉期提前显影见于动静脉瘘，与静脉血栓无关。", "tr": "“充盈缺损＋不显影＋侧支”为深静脉血栓造影三征；静脉石是既往血栓的平片标志。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1125", "t": "多选题", "s": "关于颈动脉狭窄的影像学评估，正确的有", "o": {"A": "彩色多普勒超声为常用筛查方法", "B": "CTA可同时显示管腔狭窄及斑块钙化", "C": "DSA是管腔狭窄评估的金标准", "D": "高分辨MRI可显示斑块内出血及纤维帽", "E": "X线平片可精确测量狭窄程度"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-006", "kp": "颈动脉狭窄影像评估", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】颈动脉狭窄评估遵循“超声筛查→CTA/MRA无创评估→DSA金标准”路径，高分辨MRI还能评价斑块稳定性（易损斑块）。【为什么错】E：X线平片不能显示血管腔及狭窄，无法测量狭窄程度。", "tr": "NASCET法以狭窄远端正常管径为参考测量狭窄率；易损斑块（脂质核大、纤维帽薄）是脑梗死危险因素。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 1}, {"id": "U07-1201a", "t": "共用题干题", "s": "该患者应诊断为何种疾病", "o": {"A": "脑梗死", "B": "左侧基底节区高血压性脑出血", "C": "脑膜瘤", "D": "脑脓肿", "E": "蛛网膜囊肿"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-017", "kp": "基底节脑出血诊断", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】老年高血压患者突发意识障碍及偏瘫，CT示基底节区高密度影，符合高血压性脑出血的典型部位与影像特征。【为什么错】A：脑梗死CT急性期多为低密度且发病数小时常阴性。C：脑膜瘤为脑外等密度肿块。D：脑脓肿呈低密度伴环形强化。E：蛛网膜囊肿为水样低密度。", "tr": "“突发神经功能障碍＋基底节高密度”＝高血压脑出血，病史与密度是关键。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0701", "gs": "患者男，65岁，高血压病史10余年，突发意识不清、右侧肢体偏瘫2小时急诊入院。查体：血压190/110 mmHg，左侧瞳孔对光反射迟钝。急诊CT平扫示左侧基底节区类圆形高密度影，边界清楚，周围见轻度低密度水肿带，双侧脑室无明显受压移位。"}, {"id": "U07-1201b", "t": "共用题干题", "s": "该患者出血量较少、病情平稳，关于血肿演变过程及影像复查，正确的是", "o": {"A": "血肿密度由高到低演变，约2～3周后逐渐变为等、低密度", "B": "血肿密度随时间由低变高", "C": "血肿周边水肿在急性期持续加重", "D": "亚急性期MRI T2WI血肿均为低信号", "E": "血肿吸收后无任何影像残留"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-018", "kp": "脑出血血肿演变规律", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】脑出血血肿CT密度按“高→等→低”演变，约2～3周后血肿液化呈低密度，周边水肿于急性期达到高峰后逐渐消退。【为什么错】B：密度由高变低而非由低变高。C：水肿在出血后数小时至数天达高峰，之后逐步消退，并非持续加重。D：亚急性后期T2WI为高信号。E：慢性期可残留含铁血黄素环及裂隙样改变，并非无任何残留。", "tr": "“高→等→低”是CT随访判断血肿演化的轴线；吸收期增强可出现环形强化，勿误认为肿瘤。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0701", "gs": ""}, {"id": "U07-1201c", "t": "共用题干题", "s": "该患者出血2周后复查MRI，血肿周边出现T2WI低信号环，其病理基础是", "o": {"A": "含铁血黄素沉积", "B": "正铁血红蛋白", "C": "氧合血红蛋白", "D": "胆固醇结晶", "E": "钙盐沉积"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-019", "kp": "脑出血慢性期含铁血黄素", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】血肿慢性期（出血数周后）巨噬细胞吞噬并沉积含铁血黄素，含铁血黄素为顺磁性物质，使局部T2WI呈低信号环，可持续多年。【为什么错】B：正铁血红蛋白见于亚急性期，T1WI高信号。C：氧合血红蛋白见于超急性期。D：胆固醇结晶见于胆固醇肉芽肿。E：钙盐沉积T1WI、T2WI均低信号且常伴CT高密度钙化。", "tr": "“慢性期T2WI低信号环＝含铁血黄素”与“亚急性期双高”是出血信号分期两大标志。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0701", "gs": ""}, {"id": "U07-1202a", "t": "共用题干题", "s": "该患者最可能的疾病诊断是", "o": {"A": "大量胸腔积液", "B": "自发性气胸", "C": "肺大疱", "D": "肺栓塞", "E": "纵隔气肿"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-013", "kp": "自发性气胸诊断", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】青年瘦高体型、突发胸痛呼吸困难，胸片示肺野外带透亮无肺纹理并见脏层胸膜线，符合自发性气胸。【为什么错】A：胸腔积液呈均匀致密影伴肋膈角变钝，无透亮区。C：肺大疱为肺内薄壁空腔，其内可见纤细肺纹理。D：肺栓塞以血供改变为主。E：纵隔气肿沿纵隔分布。", "tr": "“瘦高青年＋突发胸痛＋脏层胸膜线”＝自发性气胸，多与肺尖胸膜下肺大疱破裂有关。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0, "gid": "G0702", "gs": "患者男，22岁，体型瘦高，吸烟5年，突发右侧胸痛、呼吸困难1小时来诊。查体：右肺呼吸音减低，叩诊鼓音。X线胸片示右肺野外带无肺纹理透亮区，可见脏层胸膜线，肺组织受压约30%，纵隔无明显移位。"}, {"id": "U07-1202b", "t": "共用题干题", "s": "该患者保守治疗后症状反复发作，为评估肺尖部肺大疱及胸膜情况，应首选的影像学检查是", "o": {"A": "胸部X线正侧位片", "B": "高分辨率CT（HRCT）", "C": "胸部超声", "D": "肺通气灌注显像", "E": "胸部MRI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-014", "kp": "肺大疱HRCT评估", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】HRCT薄层高分辨率扫描能清晰显示肺尖胸膜下肺大疱的数目、大小及气胸复发相关病变，是评估肺大疱及指导手术的首选。【为什么错】A：X线平片对肺大疱显示有限。C：超声难以观察肺尖含气病变。D：通气灌注显像用于肺栓塞、肺功能评估。E：MRI对含气肺组织显示差。", "tr": "HRCT是肺大疱、肺气肿及间质性病变评估的标准方法，薄层＋高分辨率重建。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0, "gid": "G0702", "gs": ""}, {"id": "U07-1203a", "t": "共用题干题", "s": "该患者首先应考虑的诊断是", "o": {"A": "肝血管瘤", "B": "肝细胞癌", "C": "肝囊肿", "D": "肝脓肿", "E": "肝转移瘤"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-012", "kp": "肝细胞癌增强诊断", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】乙肝肝硬化背景＋AFP升高＋增强“快进快出”，高度提示肝细胞癌，符合HCC富血供及廓清的典型特征。【为什么错】A：血管瘤呈周边结节状向心性填充的早出晚归。C：囊肿无强化。D：脓肿厚壁环形强化伴临床感染征象。E：转移瘤多为多发环形强化。", "tr": "“乙肝＋AFP↑＋快进快出”是HCC三大诊断线索，结节伴门脉期廓清最特异。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0703", "gs": "患者男，55岁，慢性乙肝病史20年，甲胎蛋白（AFP）明显升高，体检CT发现肝右叶直径约3.5 cm类圆形低密度结节，增强扫描动脉期明显强化、门脉期及延迟期强化减退，呈典型“快进快出”表现。"}, {"id": "U07-1203b", "t": "共用题干题", "s": "为进一步确诊并全面评估该病变，拟行肝脏MRI检查，其典型的MR表现是", "o": {"A": "T1WI明显高信号、T2WI显著高信号伴向心性充填", "B": "T1WI稍低信号、T2WI稍高信号，动态增强呈快进快出，可伴假包膜", "C": "T1WI、T2WI均呈水样信号且无强化", "D": "T2WI呈均匀低信号", "E": "增强后无强化"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-013", "kp": "肝细胞癌MRI特征", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】HCC在MRI上呈T1WI稍低、T2WI稍高信号，动态增强呈快进快出，部分可见假包膜（T1WI低信号环），符合典型HCC特征。【为什么错】A：T1WI高信号伴T2WI显著高信号向心性充填为血管瘤特征。C：水样信号无强化为囊肿。D：T2WI低信号见于含铁沉积或纤维化。E：HCC为富血供肿瘤，明显强化。", "tr": "HCC“T1稍低T2稍高＋快进快出＋假包膜”与血管瘤“T2明显高＋向心充填”是MR鉴别要点。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0703", "gs": ""}, {"id": "U07-1204a", "t": "共用题干题", "s": "该患者最可能的诊断是什么", "o": {"A": "腰椎结核", "B": "腰椎间盘突出症", "C": "腰椎转移瘤", "D": "腰椎管狭窄症", "E": "腰肌劳损"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-010", "kp": "腰椎间盘突出症诊断", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】中青年重体力劳动者，腰痛伴下肢放射痛、直腿抬高试验阳性，MRI示L4/5椎间盘后突压迫硬膜囊，符合腰椎间盘突出症。【为什么错】A：腰椎结核伴椎体破坏、椎旁脓肿。C：转移瘤椎弓根破坏、椎体溶骨。D：椎管狭窄为骨性椎管普遍狭窄。E：腰肌劳损无神经根受压影像表现。", "tr": "“下肢放射痛＋直腿抬高阳性＋MRI后突压迫”=椎间盘突出；L4/5、L5/S1为最好发节段。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0, "gid": "G0704", "gs": "患者男，45岁，搬运工人，腰痛伴左下肢放射痛、麻木3个月，查体直腿抬高试验阳性。MRI矢状位示L4/5椎间盘信号减低，向后方局限性突出，硬膜囊受压，左侧神经根受压移位。"}, {"id": "U07-1204b", "t": "共用题干题", "s": "该患者拟加行腰椎CT检查，CT平扫对椎间盘突出的主要诊断价值在于", "o": {"A": "显示突出的椎间盘及其与硬膜囊、神经根的关系，并可显示髓核钙化及骨性椎管狭窄", "B": "显示神经根水肿程度", "C": "定量测量脑脊液流速", "D": "显示脊髓缺血灌注", "E": "观察马尾神经的电生理信号"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-011", "kp": "椎间盘突出CT诊断价值", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (2)CT诊断要点", "ex": "【为什么对】CT轴位可显示椎间盘后缘突出、硬膜囊及神经根受压关系，并显示髓核钙化、骨性椎管狭窄及小关节退变等伴发改变，与MRI互补。【为什么错】B：神经根水肿需MRI观察。C：脑脊液流速测定为MR相位对比法。D：脊髓缺血灌注需MR灌注成像。E：电生理信号非影像检查内容。", "tr": "CT看“骨性与钙化”，MRI看“软组织与髓核信号”，两者结合评估椎间盘突出最全面。", "bk": "副高", "ref": {"篇": "骨与骨关节", "章": "脊柱退行性病变", "节": "椎间盘及椎骨的退变过程", "页": 285}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0704", "gs": ""}, {"id": "U07-1205a", "t": "共用题干题", "s": "该患者应首先考虑的诊断是什么", "o": {"A": "主动脉瘤", "B": "主动脉夹层（Stanford A型）", "C": "急性心肌梗死", "D": "肺栓塞", "E": "心包积液"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-015", "kp": "主动脉夹层诊断", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】突发胸背部撕裂样痛＋血压极高＋CTA示升主动脉内膜片及真假双腔，符合Stanford A型主动脉夹层（累及升主动脉）。【为什么错】A：主动脉瘤为管腔均匀扩张，无内膜片。C：心肌梗死以冠脉病变为主。D：肺栓塞为肺动脉内栓子。E：心包积液为继发表现。", "tr": "Stanford A型累及升主动脉需急诊外科，B型（仅降主动脉）多药物或腔内治疗，分型决定治疗。", "bk": "副高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0705", "gs": "患者男，60岁，高血压病史，突发胸背部撕裂样疼痛伴大汗1小时，血压200/110 mmHg。急诊主动脉CTA示升主动脉见内膜片及真假双腔，假腔内见部分血栓，夹层累及降主动脉延伸至腹主动脉，双侧肾动脉由真腔供血。"}, {"id": "U07-1205b", "t": "共用题干题", "s": "关于主动脉夹层影像学评估，下列表述正确的是", "o": {"A": "X线平片即可确诊主动脉夹层", "B": "CTA能同时显示内膜片、破口位置、真假腔及分支血管受累情况", "C": "超声可全程显示胸腹主动脉全程", "D": "MRI无需造影剂即可完全代替CTA评估", "E": "DSA已作为诊断夹层的首选检查"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-016", "kp": "主动脉夹层CTA评估价值", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTA无创、快速，可一站式显示内膜片、破口、真假腔、血栓及分支受累情况，是主动脉夹层诊断与术前评估的首选方法。【为什么错】A：平片仅见纵隔增宽等间接征象，不能确诊。C：超声对降主动脉及分支显示受限。D：MRI成像时间长、急症不适用，且有血流信号干扰。E：DSA为有创检查，主要用作介入治疗的引导，不是诊断首选。", "tr": "急诊夹层“CTA一站式评估”优于其他手段；DSA有创，用于介入操作导航。", "bk": "副高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0705", "gs": ""}, {"id": "U07-1206a", "t": "共用题干题", "s": "该患者首先考虑的疾病诊断是", "o": {"A": "急性中耳炎", "B": "中耳胆脂瘤", "C": "听神经瘤", "D": "中耳血管球瘤", "E": "外耳道胆脂瘤"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-011", "kp": "中耳胆脂瘤诊断", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】慢性化脓性中耳炎史＋上鼓室软组织影伴盾板骨质破坏、听小骨吸收，是继发性中耳胆脂瘤的典型CT表现。【为什么错】A：急性中耳炎以黏膜增厚、积液为主，无骨质破坏。C：听神经瘤位于桥小脑角、内听道。D：血管球瘤增强明显强化伴搏动性耳鸣。E：外耳道胆脂瘤位于外耳道。", "tr": "“上鼓室软组织＋盾板破坏”是胆脂瘤诊断核心，骨质破坏是手术指征的影像依据。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0, "gid": "G0706", "gs": "患者女，35岁，右耳反复流脓伴听力下降10余年。颞骨CT示右侧上鼓室软组织团块影，盾板骨质破坏，锤、砧骨部分吸收，乳突气房混浊，面神经管水平段骨质尚完整。临床疑中耳胆脂瘤，拟行颞骨CT全面评估后择期手术。"}, {"id": "U07-1206b", "t": "共用题干题", "s": "该患者疑中耳胆脂瘤并需与中耳炎性肉芽组织鉴别时，MR弥散加权成像（DWI）的典型表现是", "o": {"A": "DWI呈明显高信号（角化物弥散受限），增强无强化或仅边缘强化", "B": "DWI呈低信号，增强后明显均匀强化", "C": "DWI低信号，T2WI呈明显低信号", "D": "DWI高信号，T1WI呈明显高信号", "E": "DWI呈明显高信号且T1WI、T2WI均为低信号"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-012", "kp": "中耳胆脂瘤DWI表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】胆脂瘤为角化鳞状上皮及角化物堆积，细胞致密弥散受限，DWI呈明显高信号，增强无强化或边缘轻度强化，与肉芽组织（DWI低、明显强化）形成鉴别。【为什么错】B：均匀明显强化为肉芽组织、富血供病变特征。C：胆脂瘤T2WI呈高信号而非低信号。D：T1WI明显高信号多见于出血、脂肪。E：T2WI低信号不符胆脂瘤表现。", "tr": "“DWI高＋不强化”是胆脂瘤特征；“DWI低＋明显强化”指向肉芽组织，DWI是两者鉴别关键。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0, "gid": "G0706", "gs": ""}, {"id": "U07-1207a", "t": "共用题干题", "s": "该患者的正确诊断是什么", "o": {"A": "子宫内膜癌", "B": "子宫肌瘤", "C": "卵巢囊肿", "D": "子宫腺肌症", "E": "宫颈癌"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-007", "kp": "子宫肌瘤MRI诊断", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】育龄女性月经量增多，MRI示子宫肌壁间多发T2WI低信号、边界清楚的肿块，符合典型子宫肌瘤表现。【为什么错】A：子宫内膜癌为内膜增厚肿块伴肌层浸润。C：卵巢囊肿位于附件区、水样信号。D：子宫腺肌症表现为结合带弥漫增厚、点状出血信号。E：宫颈癌位于宫颈。", "tr": "“T2WI低信号＋边界清楚”是肌瘤特征；腺肌症看结合带，二者均可使宫腔增大但信号分布不同。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0707", "gs": "患者女，40岁，月经量增多伴经期延长半年，轻度贫血。MRI示子宫增大，肌壁间见多发类圆形肿块，T2WI呈低信号，边界清楚，宫腔受压变形，双侧附件区未见异常。药物治疗效果不佳，拟行子宫动脉栓塞治疗。"}, {"id": "U07-1207b", "t": "共用题干题", "s": "该患者保守治疗无效，拟行子宫动脉栓塞术（UAE）治疗，术前最适宜的血管影像学检查是", "o": {"A": "腹部X线平片", "B": "盆腔CTA/MRA（子宫动脉成像）", "C": "静脉肾盂造影", "D": "膀胱造影", "E": "全身骨扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-008", "kp": "子宫肌瘤栓塞术前评估", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (2)CT诊断要点", "ex": "【为什么对】UAE术前需明确子宫动脉起源、走行、粗细及有无卵巢动脉供血等解剖信息，盆腔CTA或MRA可无创三维显示，指导栓塞策略。【为什么错】A：平片不能显示血管。C：静脉肾盂造影评估泌尿系统。D：膀胱造影显示膀胱。E：骨扫描用于骨转移。", "tr": "子宫动脉栓塞术前“CTA/MRA三维血管成像”是标准评估手段；术中再行选择性DSA确认。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0707", "gs": ""}, {"id": "U07-1301", "t": "案例分析题", "s": "患者男，58岁，因突发右侧肢体无力伴言语不清2小时急诊入院，NIHSS评分12分。临床考虑急性缺血性脑卒中，急诊CT平扫未见明确异常，为早期确诊并评估缺血范围，临床申请急诊MRI检查。技师需在最短时间内完成对缺血病灶最敏感的序列扫描，同时兼顾患者躁动配合度及检查安全，必要时可加做灌注成像评估缺血半暗带。此时最应优先采用的扫描序列是", "o": {"A": "轴位T1WI、T2WI平扫", "B": "轴位DWI及ADC图", "C": "轴位SWI", "D": "单体素MRS", "E": "冠状位T1WI增强扫描"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-020", "kp": "急性脑梗死急诊MRI序列选择", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】超急性期脑梗死细胞毒性水肿使水分子弥散受限，DWI呈高信号、ADC值降低，发病2小时内即可检出，是急诊脑卒中MRI的核心序列，符合“时间就是大脑”的检查原则。【为什么错】A：T1WI、T2WI对超急性期梗死不敏感，易漏诊。C：SWI用于出血、钙化及静脉显示，非梗死首选。D：MRS为功能代谢序列，耗时长，不适合急诊。E：增强用于评估血脑屏障破坏，非早期梗死首选。", "tr": "DWI+ADC是急性卒中MRI金标准组合；“CT阴性＋DWI阳性”为超急性梗死的经典场景。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "急性播散性脑脊髓炎", "页": 46}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1302", "t": "案例分析题", "s": "患者女，45岁，突发剧烈头痛、呕吐1天，脑膜刺激征阳性，临床高度怀疑蛛网膜下腔出血。发病后立即行头颅CT平扫未见明确蛛网膜下腔高密度影，考虑出血量少或CT敏感性随时间下降。为排除蛛网膜下腔出血并评估微小动脉瘤，拟行头颅MRI补充检查，技师需选择对血液及出血最敏感、又能兼顾微小动脉瘤显示的序列组合，并做好患者制动与监护。此时应优先采用的MRI序列组合是", "o": {"A": "FLAIR及SWI序列", "B": "常规T1WI、T2WI序列", "C": "单次轴位DWI", "D": "头颅MRS", "E": "磁化传递成像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-021", "kp": "蛛网膜下腔出血MRI序列", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】FLAIR对蛛网膜下腔少量出血敏感（脑脊液信号抑制后出血呈高信号），SWI能显示微量出血及含铁血黄素沉积，两者组合可提高CT阴性蛛网膜下腔出血的检出率。【为什么错】B：常规T1WI、T2WI对蛛网膜下腔少量血液显示不佳。C：DWI用于梗死、脓肿等，非出血检出序列。D：MRS为代谢分析，非首选。E：磁化传递成像用于提高组织对比，不用于出血。", "tr": "“CT阴性蛛网膜下腔出血”复查首选FLAIR＋SWI；动脉瘤确认需CTA或DSA。", "bk": "副高", "ref": {"篇": "中枢神经系统", "章": "颅内囊性病变", "节": "蛛网膜囊肿", "页": 80}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1303", "t": "案例分析题", "s": "患者女，42岁，体检超声发现甲状腺左叶约1.5 cm低回声结节，内见微小钙化，边界欠清，临床疑甲状腺乳头状癌，拟行颈部CT增强扫描，以明确结节范围及其与气管、食管、颈动脉鞘的关系并评估淋巴结。技师准备检查时需重点考虑扫描时相、患者配合及对比剂注射方案，以减少吞咽运动伪影并确保结节与血管强化充分。此时最合适的扫描方案是", "o": {"A": "嘱患者平静呼吸、避免吞咽，采用颈部容积扫描并行动脉期增强", "B": "大螺距单次扫描，不注射对比剂", "C": "口服空气对比剂后平扫", "D": "仅做静脉期延迟5分钟扫描", "E": "透视下连续曝光采集"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-013", "kp": "颈部CT增强扫描方案", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】颈部扫描须避免吞咽动作以防运动伪影，动脉期增强可清晰显示富血供甲状腺病变及颈部血管，容积薄层扫描利于多平面重组。【为什么错】B：大螺距快速扫描虽快但未增强，无法显示病变强化特征及血管关系。C：空气对比剂用于胃肠道，颈部不适用。D：静脉期延迟过长，动脉期已过，不利于富血供病变评估。E：透视连续曝光辐射量大且无诊断性增强图像。", "tr": "“颈部扫描防吞咽＋动脉期增强”是甲状腺及颈部病变检查要点，增强时相直接影响诊断。", "bk": "副高", "ref": {"篇": "基础概念（绪论）", "章": "基本概念（X线物理/对比剂/成像基础）", "节": "CT 增强扫描", "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1304", "t": "案例分析题", "s": "患者男，50岁，鼻咽癌根治性放疗后1年，常规复查鼻咽部MRI。临床需评估有无肿瘤残留或复发，并与放疗后纤维化、瘢痕鉴别，同时观察颅底骨质及颈部淋巴结情况。技师在制定扫描方案时，应结合增强扫描与功能成像序列，选择对复发与纤维化鉴别最有价值的序列组合，并注意对比剂剂量与延迟扫描时相的规范。此时最应采用的序列组合是", "o": {"A": "增强T1WI脂肪抑制及DWI序列", "B": "仅平扫T1WI", "C": "仅轴位T2WI", "D": "SWI序列", "E": "磁化传递成像单序列"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-014", "kp": "鼻咽癌放疗后随访MRI", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】复发肿瘤富含细胞、血供丰富，增强T1WI脂肪抑制明显强化，DWI呈高信号、ADC值降低；而纤维化无强化或延迟轻度强化，DWI低信号、ADC值升高，二者联合是复发与纤维化鉴别的关键。【为什么错】B：平扫T1WI不能反映血供。C：T2WI对鉴别无特异性。D：SWI显示出血钙化，不用于复发鉴别。E：磁化传递成像辅助性，无法独立鉴别。", "tr": "“复发＝强化＋DWI高＋ADC低”“纤维化＝无强化＋DWI低＋ADC高”，ADC值量化是鉴别关键。", "bk": "副高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "鼻咽部病变", "页": 103}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U07-1305", "t": "案例分析题", "s": "患者男，62岁，股骨颈骨折卧床3天后突发呼吸困难、胸痛、咯血，血氧饱和度下降，D-二聚体明显升高，临床高度怀疑急性肺动脉栓塞，拟行CT肺动脉成像（CTPA）。技师需设置合适的对比剂注射方案与扫描触发方式，确保肺动脉显影充分、避免上腔静脉高浓度对比剂伪影干扰肺动脉评价，并兼顾右心室功能评估。此时最合理的扫描技术方案是", "o": {"A": "对比剂团注后自动触发，于肺动脉期采集，必要时辅以心电门控评估右心功能", "B": "对比剂注射后立即扫描（上腔静脉期）", "C": "不注射对比剂的低剂量平扫", "D": "延迟10分钟后延迟扫描", "E": "只做胸部X线正位片替代"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-017", "kp": "CTPA扫描技术方案", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTPA通过自动触发（感兴趣区置于肺动脉干）在对比剂达峰时采集肺动脉期，可清晰显示肺动脉内血栓；心电门控或心电编辑可评估右心室增大（RV/LV比值），是急性肺栓塞一站式评估的核心技术。【为什么错】B：立即扫描时对比剂尚在上腔静脉，产生喷射伪影掩盖肺动脉。C：平扫不能显示血管内充盈缺损。D：延迟扫描时对比剂已稀释廓清。E：X线胸片仅能显示间接征象，不能确诊。", "tr": "CTPA“自动触发＋肺动脉期采集”避免上腔静脉伪影；肺栓塞确诊看充盈缺损而非平扫。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1306", "t": "案例分析题", "s": "患者男，60岁，突发胸背部撕裂样剧痛，血压200/110 mmHg，临床疑主动脉夹层，急诊行胸腹主动脉CTA检查。原始轴位图像显示降主动脉内膜片及真假双腔，假腔部分血栓形成。技师需利用后处理技术全面评估夹层累及范围、内膜破口位置及分支血管受累情况，为临床制定急诊手术治疗方案提供可靠依据。此时最合适的图像后处理方法是", "o": {"A": "沿主动脉走行做曲面重组（CPR）并配合多平面重组（MPR）观察内膜片及破口", "B": "仅保留原始轴位图像", "C": "容积再现（VR）仅显示主动脉外表面", "D": "最大密度投影（MIP）去骨显示血管钙化", "E": "仿真内镜观察主动脉腔内表面"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-018", "kp": "主动脉夹层CTA后处理", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CPR沿血管中心线展开可全程显示主动脉内膜片、真假腔、破口及分支受累；结合MPR冠状矢状位重组能准确定位破口与判断Stanford分型，是夹层后处理的核心。【为什么错】B：单看轴位难以整体评估夹层延伸范围。C：VR只显示血管外形，无法观察腔内内膜片。D：MIP去骨主要用于血管钙化与管腔显示，对内膜片显示不佳。E：仿真内镜用于观察腔内结构，对破口及分支评估价值有限。", "tr": "夹层后处理“CPR＋MPR”是黄金组合，VR看外形、MIP看钙化，各有所用。", "bk": "副高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U07-1307", "t": "案例分析题", "s": "患者女，58岁，呼吸困难1个月，X线胸片示右侧大量胸腔积液，超声定位后临床拟行CT引导下胸腔穿刺引流术。患者神志清楚、生命体征平稳，可配合扫描与穿刺操作。技师需配合临床确定穿刺层面与进针路径，选择合适扫描条件与重建方式，既保证定位准确又尽量降低辐射剂量，并做好穿刺后复查确认引流管位置。此时最合理的操作流程是", "o": {"A": "CT定位扫描选定液性暗区最大层面，设计避开肺组织的进针路径，穿刺后复查扫描确认引流管位置", "B": "盲目按体表标记穿刺，不做CT确认", "C": "不定位直接行立位透视穿刺", "D": "采用俯卧位强行穿刺", "E": "仅凭X线正位片确定穿刺点"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-019", "kp": "CT引导下胸腔穿刺定位", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CT引导穿刺先定位扫描确定积液最大层面及安全进针路径（避开肺组织、膈肌及大血管），穿刺后即刻复查确认引流管位置，可显著提高成功率、降低气胸等并发症。【为什么错】B：盲目穿刺风险高，易损伤肺组织。C：透视仅能观察骨骼及气体，对积液定位不佳。D：俯卧位不适用于所有病例，需根据积液位置选择体位。E：X线正位片无横断定位信息。", "tr": "CT引导穿刺“定位→设计路径→穿刺→复查确认”四步流程，安全性与准确性并重。", "bk": "副高", "ref": {"篇": "胸部", "章": "胸膜疾病", "节": "胸腔积液", "页": 140}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1308", "t": "案例分析题", "s": "患者女，50岁，体检超声发现肝右叶约3 cm稍强回声结节，临床拟诊肝海绵状血管瘤，需行MRI进一步确诊。技师制定肝脏MRI动态增强扫描方案时，需考虑多期增强扫描的时相设置、重T2加权序列的应用及脂肪抑制技术，以获得血管瘤“早出晚归”的典型信号特征，并与肝细胞癌、转移瘤等富血供病变鉴别。此时最合适的扫描方案是", "o": {"A": "重T2加权（长TE）T2WI＋多期动态增强（动脉期、门脉期、延迟期）", "B": "仅做平扫T1WI", "C": "仅做T2WI平扫", "D": "单期门脉期增强扫描", "E": "MR胰胆管成像（MRCP）替代"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-014", "kp": "肝血管瘤MRI扫描方案", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】重T2加权序列T2WI呈显著高信号（灯泡征），多期动态增强显示周边结节状强化、向心性充填及延迟期持续强化（早出晚归），是确诊血管瘤的核心方案。【为什么错】B：T1WI平扫对富血供病变鉴别价值有限。C：单T2WI无法显示动态强化特征。D：单期增强无法观察充填过程及延迟强化。E：MRCP用于胆道系统，不用于肝内占位定性。", "tr": "“重T2WI＋多期动态增强＋延迟期”是血管瘤确诊的完整方案，延迟期是关键。", "bk": "副高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1309", "t": "案例分析题", "s": "患者男，65岁，进行性无痛性黄疸1个月，皮肤巩膜黄染，实验室检查示胆红素及CA19-9升高，临床疑胰头占位致胆道梗阻，拟行上腹部MRI检查。技师需合理组合平扫、MR胰胆管成像（MRCP）及动态增强扫描序列，清晰显示胰头肿块、胆胰管扩张情况及肿瘤与周围血管的关系，为外科手术可行性评估提供影像依据。此时最合适的扫描方案是", "o": {"A": "冠状位及轴位T2WI＋MRCP＋动态增强扫描", "B": "仅轴位T1WI平扫", "C": "仅做SWI序列", "D": "仅做轴位DWI单序列", "E": "口服钡剂后X线钡餐检查"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-015", "kp": "胰头占位MRI扫描方案", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】MRCP可无创显示胆胰管扩张与梗阻断端，T2WI及动态增强显示胰头肿块及强化特征，结合血管成像评估肿瘤与周围血管关系，是胰腺占位术前评估的一站式方案。【为什么错】B：T1WI平扫信息有限。C：SWI不用于胰腺占位评估。D：单DWI无法显示解剖及胆胰管。E：钡餐不能显示胰腺及胆道。", "tr": "“MRCP看胆胰管＋动态增强看肿块血供＋MRA看血管关系”是胰头癌术前评估三要素。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1310", "t": "案例分析题", "s": "患者女，52岁，绝经后阴道不规则出血，诊断性刮宫病理示子宫内膜样腺癌，临床拟行MRI术前分期，重点评估肿瘤肌层浸润深度、有无宫颈间质受累及盆腔淋巴结转移。患者体型偏瘦，能耐受较长扫描时间，无需镇静。技师需选择高分辨扫描序列与体位，结合动态增强及弥散加权成像，为FIGO分期提供准确依据。此时最合适的扫描方案是", "o": {"A": "矢状位高分辨T2WI＋动态增强＋DWI", "B": "仅轴位T1WI", "C": "仅冠状位STIR", "D": "仅SWI序列", "E": "仅头颅MRA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-009", "kp": "子宫内膜癌MRI分期方案", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】矢状位T2WI清晰显示宫腔肿瘤与肌层界面，动态增强显示内膜下强化带完整性，DWI及ADC值辅助判断深肌层浸润，三者联合是子宫内膜癌分期的标准方案。【为什么错】B：轴位T1WI不能显示肌层浸润层次。C：STIR用于脂肪抑制及骨髓，非分期核心。D：SWI用于出血钙化。E：MRA用于血管，与子宫内膜癌分期无关。", "tr": "“矢状位＋动态增强＋DWI”是子宫内膜癌MRI分期三件套，深肌层浸润≥1/2为高危。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "子宫内膜癌", "页": 247}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1311", "t": "案例分析题", "s": "患者女，42岁，多发性子宫肌瘤致月经量增多、贫血，药物治疗无效，临床拟行子宫动脉栓塞术（UAE）。术前需行盆腔血管影像学评估，明确子宫动脉解剖、血供来源及卵巢动脉有无参与供血，以规划导管入路与栓塞方案。患者无碘对比剂过敏史，肾功能正常，未生育且保留子宫意愿强烈，希望在充分评估后实施微创治疗。此时进行血管评估的最适宜方法是", "o": {"A": "盆腔CTA或MRA三维血管成像，必要时术中选择性子宫动脉DSA", "B": "下肢静脉造影", "C": "经皮肝穿刺门静脉造影", "D": "淋巴管造影", "E": "膀胱造影"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-010", "kp": "子宫动脉栓塞术前血管评估", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (2)CT诊断要点", "ex": "【为什么对】UAE术前经CTA/MRA无创三维显示子宫动脉起源、走行及有无卵巢动脉供血，术中再以选择性子宫动脉DSA确认并栓塞，是最规范的评估路径。【为什么错】B：下肢静脉造影用于静脉病变。C：门静脉造影用于门脉高压。D：淋巴造影用于淋巴系统。E：膀胱造影显示膀胱形态。", "tr": "“术前CTA/MRA＋术中DSA”是子宫动脉栓塞的标准路径，卵巢动脉供血是栓塞失败原因之一。", "bk": "副高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1312", "t": "案例分析题", "s": "患者男，17岁，右膝关节肿胀、疼痛2个月，局部皮温升高。X线示股骨远端干骺端溶骨性破坏伴日光放射状骨膜反应及Codman三角，临床拟诊骨肉瘤，需行MRI明确肿瘤髓内浸润范围、跳跃灶及软组织肿块边界，并行胸部CT筛查肺转移，为保肢手术方案提供依据。患者一般情况尚好，无发热，可配合完成各项检查。此时最合理的影像检查方案是", "o": {"A": "膝关节MRI平扫及增强（含T1WI、T2WI脂肪抑制）评估肿瘤范围，加胸部CT筛查肺转移", "B": "仅复查X线平片", "C": "仅做超声检查", "D": "仅做膝关节CT平扫", "E": "仅做全身PET-CT替代所有检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-012", "kp": "骨肉瘤分期影像方案", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】MRI冠状矢状位T1WI、T2WI脂肪抑制及增强可准确显示肿瘤髓内浸润范围、关节及骨骺受累和软组织肿块边界，是保肢手术规划的关键；胸部CT是肺转移筛查标准方法。【为什么错】B：X线不能评估髓内范围。C：超声对骨内病变显示差。D：CT软组织对比不如MRI，髓内范围评估受限。E：PET-CT对微小肺转移检出有限，不能完全替代MRI局部评估。", "tr": "“MRI定范围、胸部CT定肺转移”是骨肉瘤局部与全身分期的基础方案，跳跃灶务必观察。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1313", "t": "案例分析题", "s": "患者男，40岁，因肾病综合征长期口服糖皮质激素，近2个月出现双侧髋部疼痛、活动受限，临床疑早期股骨头缺血坏死，申请髋关节MRI检查。患者无外伤史，髋部X线平片未见明确异常。技师需选择对骨髓水肿及早期坏死最敏感的序列，注意双侧对称扫描及脂肪抑制技术的应用，以提高早期病变检出率并明确坏死范围与分期。此时最合适的扫描方案是", "o": {"A": "双侧髋关节冠状位T1WI、T2WI及脂肪抑制（STIR）序列", "B": "仅做单侧髋关节X线平片", "C": "仅做双侧髋关节超声", "D": "仅做双侧髋关节CT平扫", "E": "仅做腰椎MRI"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-013", "kp": "股骨头坏死MRI方案", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】MRI对早期股骨头缺血坏死最敏感，可显示“双线征”（T2WI上坏死区与活骨间低信号线内侧高信号带）及骨髓水肿，双侧对称扫描便于对比，STIR提高病变检出。【为什么错】B：X线早期可阴性，出现硬化、塌陷已属晚期。C：超声无法穿透骨皮质显示骨髓。D：CT对早期骨髓水肿及线样征显示不如MRI。E：腰椎MRI与髋部病变无关。", "tr": "“激素史＋双髋痛”高度提示股骨头坏死，MRI双线征是其特异表现，早于X线数月。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U07-1314", "t": "案例分析题", "s": "患者男，68岁，反复头晕、一过性黑矇，超声提示左侧颈内动脉起始部重度狭窄（约75%），临床拟行颈动脉三维CTA评估狭窄程度并制定治疗方案。患者心率平稳、能配合屏气，血肌酐正常，可行增强检查。技师需设置合适的扫描范围与增强参数，保证颈动脉管腔内对比剂充盈良好、避免静脉重叠，并利用后处理技术准确测量狭窄率。此时最合适的CTA技术要点是", "o": {"A": "扫描范围自主动脉弓至Willis环，团注触发动脉期采集，结合MPR及血管分析软件按NASCET法测量狭窄率", "B": "扫描范围仅限颈部软组织", "C": "静脉期延迟采集", "D": "不使用对比剂直接扫描", "E": "仅轴位观察不做后处理测量"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-007", "kp": "颈动脉CTA技术方案", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】颈动脉CTA扫描范围覆盖主动脉弓至Willis环，团注触发动脉期可避免静脉污染，MPR及专用血管分析软件按NASCET法（以远端正常管径为参考）测量狭窄率，为手术或介入提供依据。【为什么错】B：范围不足会遗漏锁骨下及颅内段。C：静脉期血管对比差、静脉重叠。D：平扫不能显示管腔。E：不测量无法量化狭窄程度。", "tr": "NASCET法狭窄率＝(1－最窄处管径/远端正常管径)×100%；CTA测量与DSA有良好一致性。", "bk": "副高", "ref": null, "hf": true, "src": "模拟", "mk": 0}, {"id": "U07-1315", "t": "案例分析题", "s": "患者男，70岁，左下肢发凉、间歇性跛行2年，近期出现静息痛，超声示左侧股浅动脉长段闭塞，临床拟行下肢动脉DSA检查并行血管成形术。患者股动脉搏动良好，可作为穿刺入路考虑。技师需根据病变位置选择穿刺入路、造影体位与成像方式，合理控制对比剂总量以清晰显示闭塞段及侧支循环，为介入治疗提供实时导航。此时最合理的DSA技术方案是", "o": {"A": "对侧股动脉逆行穿刺入路，多体位DSA采集并配合路图技术引导球囊扩张与支架置入", "B": "直接穿刺闭塞段血管远端", "C": "仅做单一体位正位采集", "D": "不用对比剂直接试扩张", "E": "全身血管一次性造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-008", "kp": "下肢动脉DSA介入方案", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】股浅动脉长段闭塞常采用对侧股动脉逆行穿刺，通过翻山进入患侧，多体位DSA显示闭塞段与侧支循环，路图（roadmap）技术实时引导导丝、球囊及支架操作。【为什么错】B：直接穿刺闭塞段远端有穿出及血肿风险。C：单一体位不能全面显示病变。D：无造影定位盲目扩张风险高。E：一次性全身造影对比剂超量且无针对性。", "tr": "“对侧入路＋多体位＋路图”是下肢动脉闭塞介入的标准组合，DSA同时是诊断与治疗工具。", "bk": "副高", "ref": null, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0101", "t": "多选题", "s": "关于普通X线摄影中滤线栅的使用指征与性能参数，下列说法正确的是", "o": {"A": "被照体厚度超过10cm或管电压超过60kV时，散射线明显增加，应加用滤线栅", "B": "栅比等于铅条高度与铅条间距之比，栅比越大清除散射线能力越强，但曝光量与对位精度要求随之提高", "C": "栅密度指单位长度内的铅条数，栅密度越高铅条投影越细密，越不易在影像上被察觉", "D": "手、足、腕等薄部位摄影一般不用滤线栅，以免徒增受检者剂量", "E": "使用聚焦栅时，中心线可在垂直于铅条排列的方向上任意侧向偏移而不产生栅切割"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-POS-001", "kp": "滤线栅使用指征与栅比栅密度", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】A正确：体厚大于10cm、管电压高于60kV是教材公认的两条加栅指征，前者因散射体积大，后者因康普顿效应占比升高。B正确：栅比R=h/D，栅比越大对斜射散射线吸收越彻底，图像对比度改善越明显，但原发线损失增多需提高曝光量（栅因子增大），容许的中心线偏移范围也变窄。C正确：栅密度N为每厘米铅条数，密度越高铅条影越细，越不易形成栅线干扰。D正确：薄部位散射线本就少，加栅只增加剂量而无对比度收益。【为什么错】E错误：聚焦栅只允许中心线沿铅条长轴方向倾斜，若在垂直于铅条排列的方向侧向偏移、倾斜，或反置、超出栅焦距范围，均会发生栅切割，表现为影像单侧或两侧密度明显降低。", "tr": "栅比与栅密度是两个独立参数：栅比决定清除散射线能力与曝光量代价，栅密度只决定铅条影是否可见，二者常被混为一谈。“中心线可任意倾斜”是聚焦栅最典型的错误说法。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0102", "t": "多选题", "s": "下列常规X线摄影中焦点-探测器距离（SID）的选择，符合常规要求的是", "o": {"A": "心脏后前位远达片采用180~200cm", "B": "腹部仰卧前后位采用100cm", "C": "颈椎侧位采用150cm", "D": "乳腺头尾位采用100cm", "E": "口内根尖片平行投照（长遮线筒法）采用20~40cm"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-POS-002", "kp": "各部位摄影距离的选择", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】A正确：心脏远达片需最大限度减小心影几何放大，故用180~200cm。B正确：腹部、脊柱、四肢等常规摄影SID为100cm。C正确：颈椎侧位受肩部阻挡、颈椎距探测器较远（物-片距大），须加大SID至150cm以抵消放大。E正确：口内根尖片平行投照法配长遮线筒，焦-片距约20~40cm，使X线接近平行入射以减小失真。【为什么错】D错误：乳腺X线机为固定短距离设计，SID约60~65cm，而非100cm；乳腺摄影靠压迫缩小物-片距来控制放大，并不依赖长SID。", "tr": "SID并非越长越好：长SID减小放大与半影，但曝光量按平方反比大幅上升。颈椎侧位150cm、心脏远达片180~200cm、乳腺约65cm是三个最易记混的“非100cm”特例。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0103", "t": "单选题", "s": "某部位摄影时焦点至探测器距离为100cm，被照体中心至探测器距离为20cm，X线管有效焦点尺寸为1.0mm，该部位影像的放大率与半影宽度分别约为", "o": {"A": "1.25、0.25mm", "B": "1.20、0.20mm", "C": "1.25、0.20mm", "D": "0.80、0.25mm", "E": "1.20、0.25mm"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-POS-003", "kp": "影像放大率与半影的计算", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】焦-物距SOD=SID-OID=100-20=80cm。放大率M=SID/SOD=100/80=1.25；半影（模糊）宽度H=F×OID/SOD=1.0×20/80=0.25mm。故选A。【为什么错】B、E中的放大率1.20系把分母错取为SID（1+20/100）所致。C中的半影0.20mm系误用H=F×OID/SID、分母错取SID。D把放大率取成倒数SOD/SID=0.80，方向颠倒——只要物体不贴探测器，放大率恒大于1。", "tr": "放大率与半影公式的分母都是SOD（焦-物距）而非SID。减小放大与模糊的三条途径中，缩小物-片距（部位尽量贴近探测器）最经济有效，其次是加大SID与选用小焦点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0104", "t": "多选题", "s": "为在普通X线摄影中落实放射防护最优化原则，下列做法正确的是", "o": {"A": "用准直器把照射野严格限制在临床需要范围内，是最基本且最有效的防护措施之一", "B": "对儿童及育龄期受检者，在不遮挡诊断信息的前提下对性腺等辐射敏感器官施行屏蔽防护", "C": "保证足够的总滤过以滤除对成像无贡献的低能光子，降低受检者皮肤剂量", "D": "在保证影像质量的前提下适当提高管电压、相应降低mAs，有利于降低受检者剂量", "E": "陪检人员只要站在机房内距球管3m以外，即可不穿戴铅防护用品"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-POS-004", "kp": "X线摄影的防护措施", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】A正确：缩小照射野既减少受照体积和有效剂量，又减少散射线来源、改善对比度，是性价比最高的防护手段。B正确：屏蔽防护针对性腺、甲状腺、眼晶状体等敏感器官，前提是不遮盖诊断兴趣区。C正确：低能光子几乎全部被体表吸收而不到达探测器，增加总滤过可硬化线质、显著降低皮肤入射剂量。D正确：高千伏-低毫安秒组合能在维持透过量的同时降低吸收剂量，是低剂量摄影的基本策略。【为什么错】E错误：机房内散射线不能仅靠距离忽略，凡需留在机房内扶持患者者都应穿戴铅衣、铅围裙并避开原发射线方向，以“距离3m”替代屏蔽不符合防护要求。", "tr": "时间、距离、屏蔽三原则须联合使用，不能以其中之一替代其余。另注意提高kV降剂量是有条件的，过高kV会牺牲影像对比度。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0105", "t": "单选题", "s": "行颅骨前后半轴位（汤氏位）摄影，若听眦线垂直于探测器，中心线的正确投照方式是", "o": {"A": "向头侧倾斜30°，经眉间射入", "B": "向足侧倾斜30°，自前额发际上方射入，经枕骨大孔中心射出", "C": "向足侧倾斜45°，对准被检侧外耳孔射出", "D": "垂直射入，经枕外隆凸射入、眉间射出", "E": "向足侧倾斜23°，经鼻根部射出"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-001", "kp": "颅骨前后半轴位（汤氏位）", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位取仰卧或坐位，正中矢状面垂直于探测器并对准中线；听眦线垂直于探测器时，中心线向足侧倾斜30°，自前额发际上方射入、经枕骨大孔中心射出。标准影像判据是鞍背与后床突恰投影于枕骨大孔阴影之内，两侧岩骨、内耳道及枕骨对称显示。若改以听眉线垂直于探测器，则中心线需向足侧倾斜37°。【为什么错】A方向相反，向头侧倾斜无法把枕骨与岩骨从面颅重叠中分离。C是梅氏位（颞骨岩部轴位）的参数——头转向被检侧45°、中心线向足侧45°。E是柯氏位的参数——向足侧23°经鼻根射出。D为头颅后前位的中心线方向，不带角度，不能显示枕骨大孔与鞍背。", "tr": "汤氏位角度随基准线变化：听眦线垂直→30°，听眉线垂直→37°。判断合格与否不看“枕骨是否清楚”，而看鞍背与后床突是否恰落在枕骨大孔影内——角度过小投影在孔上方，过大则落于孔下方。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0106", "t": "单选题", "s": "瓦氏位（Waters位，顶颏位）摄影时，听眦线与探测器平面所成的角度约为", "o": {"A": "15°", "B": "23°", "C": "30°", "D": "37°", "E": "53°"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-002", "kp": "瓦氏位的基准线角度", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】瓦氏位取俯卧或坐位面向探测器，颏部紧贴探测器、鼻尖离开探测器约1.5cm，使听眦线与探测器平面成37°（此时听鼻线接近垂直），中心线垂直经上唇中点（鼻棘）射出。该角度使岩骨嵴下移到上颌窦底以下，上颌窦、眼眶、颧弓、鼻腔得以完整无重叠显示，是观察上颌窦积液与面中部骨折的标准体位。【为什么错】A为劳氏位的头部旋转与中心线倾斜角度。B为柯氏位中心线向足侧的倾斜角。C为汤氏位在听眦线垂直时的中心线倾斜角。E为视神经孔位（瑞氏位）正中矢状面与探测器所成的角度。", "tr": "头颅特殊位角度需成组记忆：柯氏23°、汤氏30°（听眉线时37°）、瓦氏37°、视神经孔位53°、许氏25°、劳氏15°、梅氏45°、斯氏向头侧12°。注意瓦氏位的37°是基准线与台面的夹角，而非中心线倾角——瓦氏位中心线是垂直投照的。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0107", "t": "单选题", "s": "柯氏位（Caldwell位，鼻额位）摄影时中心线向足侧倾斜约23°，其主要目的是", "o": {"A": "使岩骨嵴下移至眶下缘附近，避免其与额窦、前组筛窦及眶内结构重叠", "B": "使蝶鞍呈切线位、前后床突重合显示", "C": "使颧弓从颅骨重叠中投影出来呈弓状显示", "D": "使枕骨大孔展开并在孔内显示鞍背与后床突", "E": "使视神经孔投影于眼眶的外下象限"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-003", "kp": "柯氏位的角度作用与显示结构", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】柯氏位取俯卧、鼻额部紧贴探测器，听眦线垂直于探测器，中心线向足侧倾斜约23°经鼻根部射出。若不加角度（即标准头颅后前位），岩骨嵴恰投影在眼眶之内，遮盖眶底与前组筛窦；向足侧倾斜后岩骨嵴下移至眶下缘水平或其下，从而清晰显示额窦、前组筛窦、眶上裂与眼眶轮廓。【为什么错】B是头颅侧位的显示要求。C需颧弓切线位或颅底颏顶位才能实现。D是汤氏位的标准影像判据。E需视神经孔位（瑞氏位）——正中矢状面与探测器成53°、三点接触摆位方能达到。", "tr": "把握“角度决定岩骨嵴高低”这条主线：后前位0°时岩骨嵴位于眼眶内，柯氏位向足侧倾斜后降至眶下缘，瓦氏位头后仰37°后进一步降至上颌窦底以下。三者本质都是把岩骨这块高密度“挡板”移开。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0108", "t": "多选题", "s": "关于颞骨乳突及岩部常用摄影体位的角度与显示结构，下列描述正确的是", "o": {"A": "许氏位（Schüller位）中心线向足侧倾斜25°，自对侧外耳孔上方射入、对准被检侧外耳孔，主要显示乳突小房、鼓窦及乙状窦沟", "B": "劳氏位（Law位）头部正中矢状面与探测器约成15°、中心线向足侧倾斜15°，属乳突侧斜位", "C": "梅氏位（Mayer位）头转向被检侧约45°、中心线向足侧倾斜45°，重点显示鼓室、鼓窦入口与外耳道", "D": "斯氏位（Stenvers位）中心线向足侧倾斜45°，主要显示乳突尖及乳突小房", "E": "乳突摄影只需拍摄患侧，无须做双侧对比"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-004", "kp": "乳突及颞骨岩部摄影体位鉴别", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A正确：许氏位为乳突侧位，25°足侧倾斜使被检侧乳突从对侧乳突重叠中分离，是评价乳突气化程度、慢性中耳乳突炎及乙状窦位置的常规体位。B正确：劳氏位为乳突侧斜位，头部与中心线均取15°（“双15°”），显示范围与许氏位相近但气房展开方式不同。C正确：梅氏位为颞骨岩部轴位，头转45°、中心线向足侧45°，重点显示鼓室、鼓窦入口与外耳道。【为什么错】D错误：斯氏位为岩部后前斜位，头部正中矢状面与探测器成45°，中心线是向头侧倾斜约12°，显示的是岩骨全长、内耳道、耳蜗与半规管，而非乳突尖；把方向和角度都记反是常见失分点。E错误：乳突病变的判断高度依赖双侧对称对比（气化程度、密度、气房间隔），故乳突摄影原则上应双侧分别按相同条件摄影以供比较。", "tr": "许氏、劳氏、梅氏三个体位主要看乳突气房与鼓窦，斯氏位主要看内耳道与迷路；只有斯氏位的中心线向头侧倾斜，其余均向足侧倾斜，这是快速排除干扰项的抓手。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U08-0109", "t": "案例分析题", "s": "患者女性，42岁，因“右眼视力进行性下降3个月”就诊，眼科怀疑右侧视神经管骨性狭窄，临床申请双侧视神经孔X线摄影以作初步筛查与左右对比。科室仅有普通DR设备，患者神志清楚、颈部活动无受限，能够配合俯卧位。作为投照技师，下列关于视神经孔位（Rhese位/瑞氏位）的摆位与投照，正确的是", "o": {"A": "俯卧，被检侧眼眶靠近探测器，使颧骨、鼻部、下颌部三点紧贴台面，正中矢状面与探测器成53°，听鼻线垂直于探测器，中心线经被检侧眶中心垂直射入", "B": "仰卧，头部后仰使听眦线与台面平行，中心线经两下颌角连线中点垂直射入", "C": "俯卧，正中矢状面垂直于探测器，中心线向足侧倾斜23°经鼻根射出", "D": "侧卧，被检侧靠近探测器，中心线向足侧倾斜25°对准外耳孔", "E": "仰卧，听眦线垂直于探测器，中心线向足侧倾斜30°经枕骨大孔射出"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-005", "kp": "视神经孔位（瑞氏位）摆位要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】视神经孔位的核心是让视神经管长轴与中心线方向一致，从而使视神经孔以“正圆形环状影”投影在被检侧眼眶的外下象限。标准做法为俯卧、被检侧靠近探测器，颧骨、鼻尖、下颌构成三点接触，正中矢状面与探测器成53°、听鼻线垂直于探测器，中心线经被检侧眶中心垂直射入。因需左右比较，应用同一条件分别摄取两侧。【为什么错】B为颅底颏顶位摆位，用于观察颅底孔道与颧弓，不能显示视神经孔。C为柯氏位，虽可显示眼眶轮廓但视神经孔与眶壁重叠。D为许氏位，属乳突侧位。E为汤氏位，显示枕骨与岩骨。", "tr": "视神经孔应显示在眼眶“外下象限”，若投影在眶内其他象限说明头部旋转角或基准线不到位。此外双侧必须分别摄影并用相同条件，否则密度差会干扰对孔径大小的对比判断。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0110", "t": "单选题", "s": "颅底颏顶位（颅底位）摄影的标准摆位与中心线要求是", "o": {"A": "仰卧或坐位，头部尽量后仰使听眦线尽可能与探测器平行，头顶部接触探测器，中心线经两侧下颌角连线中点垂直射入探测器", "B": "俯卧，颏部紧贴探测器，中心线向头侧倾斜37°", "C": "仰卧，听眶线垂直于探测器，中心线向足侧倾斜45°经鼻根射入", "D": "侧卧，正中矢状面平行于探测器，中心线经蝶鞍垂直射入", "E": "俯卧，前额鼻部贴板，中心线向足侧倾斜23°经眉间射出"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-006", "kp": "颅底颏顶位摆位与显示结构", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】颅底颏顶位要求头部极度后仰，使听眦线尽量与探测器平行（即颅底平面与探测器平行），头顶接触探测器，中心线经两下颌角连线中点垂直射入。标准影像可显示卵圆孔、棘孔、破裂孔等颅底孔道，以及蝶窦、筛窦、颧弓、下颌骨升支与枕骨大孔，两侧结构对称。【为什么错】B为瓦氏位摆位且中心线方向错误。C的角度与基准线组合不能使颅底平面与探测器平行，会造成颅底孔道与面颅严重重叠。D为头颅侧位，颅底孔道互相重叠无法辨认。E为柯氏位。", "tr": "颅底位对颈部后仰程度要求高，颈椎外伤、强直性脊柱炎、老年颈椎活动受限者难以完成，此时应改用CT。临床上若患者不能后仰，可让球管倾斜以尽量使中心线垂直于听眦线，但影像质量下降。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0111", "t": "多选题", "s": "关于头颅后前位与头颅侧位摄影，下列摆位与影像标准描述正确的是", "o": {"A": "头颅后前位取俯卧，前额与鼻尖紧贴探测器，听眦线与正中矢状面均垂直于探测器，中心线经枕外隆凸垂直射入、由眉间射出", "B": "头颅后前位标准影像上，两侧眼眶、岩骨与内耳道左右对称，岩骨嵴投影于眼眶之内", "C": "头颅侧位取俯卧头侧转，被检侧靠近探测器，正中矢状面与探测器平行、瞳间线垂直于探测器，中心线经外耳孔前上方约2.5cm处垂直射入", "D": "头颅侧位标准影像上，蝶鞍呈切线位显示，两侧前后床突、外耳孔基本重合，颅骨内外板与板障清晰", "E": "头颅后前位与侧位均应采用180cm的焦-片距，以减少颅骨的几何放大"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-007", "kp": "头颅正侧位摆位与影像标准", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A正确：头颅后前位以“双垂直”（听眦线、正中矢状面均垂直于探测器）为摆位核心，中心线经枕外隆凸射入、眉间射出。B正确：左右对称是判断有无旋转的直接依据，而0°投照时岩骨嵴恰位于眶内，这也正是需要柯氏位加角度的原因。C正确：侧位以正中矢状面平行于探测器、瞳间线垂直于探测器为核心，中心线经外耳孔前上方约2.5cm（蝶鞍区）射入。D正确：蝶鞍切线显示、前后床突及外耳孔重合，是侧位无旋转的标准判据。【为什么错】E错误：头颅摄影常规采用100cm的焦-片距，180cm是胸部后前位与心脏远达片的距离；颅骨紧贴探测器时物-片距已很小，无须靠长SID控制放大。", "tr": "“对称”是正位判断旋转的指标，“重合”是侧位判断旋转的指标。另注意别把胸部的180cm套用到头颅，SID的记忆必须与部位绑定。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0112", "t": "单选题", "s": "某技师为疑似上颌窦炎患者摄取瓦氏位，所得影像上岩骨嵴投影在上颌窦中部，遮盖了上颌窦下份。造成该结果最可能的原因及正确处理是", "o": {"A": "头部后仰不足，听眦线与探测器夹角小于37°，应增加头部后仰程度", "B": "头部后仰过度，听眦线与探测器夹角大于37°，应减小后仰程度", "C": "正中矢状面偏离中线，应重新对准中线", "D": "中心线向足侧倾斜过多，应改为垂直投照", "E": "焦-片距过短造成放大，应加大至150cm"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-008", "kp": "瓦氏位影像质量的原因分析", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】瓦氏位靠头部后仰把岩骨嵴“压”到上颌窦底以下。当后仰不足（听眦线与探测器夹角小于37°）时，投照几何接近后前位，岩骨嵴位置相对偏高，就会投影在上颌窦中部而遮盖窦腔下份，导致窦内少量积液漏诊。处理办法是增加颏部上抬、加大后仰角至标准37°。【为什么错】B恰好相反：后仰过度会使岩骨嵴下移过多，同时上颌窦被拉长变形、眶下缘外形失真，但不会遮盖窦腔下部。C造成的是两侧上颌窦、眼眶不对称，而非岩骨嵴位置改变。D瓦氏位本就采用垂直中心线，题干未提示成角。E焦-片距只影响放大率与清晰度，不改变岩骨嵴与上颌窦的相对投影关系。", "tr": "凡“重叠遮挡类”问题，先判断是角度问题还是旋转问题：遮挡（上下关系错）多为基准线角度不当，不对称（左右关系错）多为旋转或中线偏移。SID几乎从不引起结构重叠关系的改变。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U08-0113", "t": "单选题", "s": "成人胸部后前立位摄影时，中心线的入射点与屏气方式是", "o": {"A": "经第4胸椎水平垂直射入，平静呼吸下曝光", "B": "经第6胸椎水平（约肩胛骨下角连线）垂直射入，深吸气后屏气曝光", "C": "经胸骨柄水平向头侧倾斜15°射入，深呼气后屏气曝光", "D": "经剑突水平垂直射入，深呼气后屏气曝光", "E": "经第10胸椎水平垂直射入，深吸气后屏气曝光"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-001", "kp": "胸部后前立位的中心线与屏气", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】成人胸部后前立位取站立面向探测器，双手背置于髋部、肘部外展使肩胛骨移出肺野，两肩下垂并等高；中心线经第6胸椎水平（相当于两侧肩胛骨下角连线）垂直射入，焦-片距180cm，深吸气后屏气曝光。深吸气可使膈肌下降、肺野充分展开，标准影像应显示第10后肋（或第6前肋）位于膈上。【为什么错】A的T4过高会使肺底与肋膈角显示不全，平静呼吸曝光则肺野扩张不足并可能产生运动模糊。C的向头侧15°是肺尖或前弓位的思路，且深呼气不适用于常规胸片。D剑突水平过低，上肺野与肺尖易被切除。E的T10已达膈下水平，属腹部范围。", "tr": "屏气方式随目的而变：常规胸片、膈上肋骨为深吸气后屏气；膈下肋骨、腹部立位为深呼气后屏气；观察气胸可加摄呼气相。中心线水平不同引起的是“照射野包含不全”，与曝光条件无关。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0114", "t": "多选题", "s": "关于胸部侧位与前弓位摄影，下列描述正确的是", "o": {"A": "胸部侧位常规取左侧位（左侧胸壁贴探测器），可减小心脏的几何放大", "B": "胸部侧位双上肢应上举抱头或前伸交叉，避免肱骨与上纵隔重叠", "C": "胸部侧位中心线经腋中线第6胸椎水平垂直射入，深吸气后屏气", "D": "前弓位患者背向探测器并使身体后倾，中心线经胸骨柄水平射入，主要用于显示肺尖、锁骨下区及右肺中叶、左肺舌段病变", "E": "胸部侧位的焦-片距与四肢摄影相同，常规采用100cm"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-002", "kp": "胸部侧位与前弓位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A正确：心脏偏左，左侧贴板可使心脏物-片距最小、放大最轻，故常规取左侧位；若重点观察右肺病变可改右侧位。B正确：上肢上举抱头能把肱骨与肩部软组织移出照射野，避免与上纵隔、胸椎重叠。C正确：侧位中心线经腋中线第6胸椎水平垂直射入，同样在深吸气后屏气。D正确：前弓位（肺尖后前斜位）通过身体后倾改变投照方向，使锁骨与前段肋骨投影移开肺尖区，暴露被遮盖的肺尖与锁骨下区病灶，对右肺中叶、左肺舌段的显示也优于常规后前位。【为什么错】E错误：胸部侧位与后前位一样属胸部摄影，焦-片距应取180cm（至少150cm）；侧位时心脏与纵隔距探测器更远、物-片距更大，若沿用四肢的100cm，几何放大与半影会明显加重。", "tr": "常见误区之一是认为侧位应取“患侧贴板”：评价心脏、纵隔时取左侧位，观察一侧胸膜或肺内局限病变时才取患侧贴板。误区之二是把SID与“部位大小”挂钩，实际上胸部（含侧位）一律用长距离。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0115", "t": "案例分析题", "s": "患者男性，58岁，慢性咳嗽伴右侧胸痛1个月。床旁仰卧前后位胸片示右侧肋膈角略变钝、右下肺野密度稍高，临床怀疑右侧少量胸腔积液，但不能确定，且患者可以短暂配合改变体位。临床要求用普通X线进一步证实是否存在少量游离积液。作为技师，最恰当的摄影方案是", "o": {"A": "加摄右侧卧水平方向投照位（右侧向下侧卧5~10分钟后，X线水平方向投照），观察沿右侧胸壁分布的带状液体影", "B": "加摄左侧卧水平投照位，使液体聚集于左侧胸壁便于测量", "C": "加摄右侧胸部前弓位，观察肋膈角变化", "D": "重复仰卧前后位并提高管电压至120kV", "E": "加摄呼气相后前立位，通过肺体积缩小凸显积液"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-003", "kp": "侧卧水平投照位显示少量胸腔积液", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】游离性胸腔积液受重力影响向低处流动。患侧向下侧卧并静置数分钟后，用水平方向X线投照，少量液体在患侧胸壁与肺外缘之间形成一条带状致密影，可检出约100ml甚至更少的积液，敏感性远高于立位或仰卧位，是普通X线证实少量游离积液的经典方法。【为什么错】B患侧向上则液体流向对侧或纵隔旁，不能在患侧显示带状影，方向搞反。C前弓位是为暴露肺尖与中叶舌段设计的，对积液无帮助。D单纯提高kV会降低对比度，反而更不利于显示少量液体。E呼气相主要用于气胸检出，且立位时少量积液仍被膈肌与肋膈角掩盖。", "tr": "口诀：查积液“患侧向下”，查气胸“患侧向上”（健侧卧位）；两者都必须用水平方向投照，若沿用垂直投照则液气平面无法显示。此外侧卧后需静置数分钟待液体充分流动再曝光。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0116", "t": "单选题", "s": "关于肋骨X线摄影的屏气方式，下列组合正确的是", "o": {"A": "膈上肋骨深吸气后屏气，膈下肋骨深呼气后屏气", "B": "膈上肋骨深呼气后屏气，膈下肋骨深吸气后屏气", "C": "膈上与膈下肋骨均在深吸气后屏气", "D": "膈上与膈下肋骨均在深呼气后屏气", "E": "膈上肋骨平静呼吸下曝光，膈下肋骨深吸气后屏气"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-004", "kp": "膈上与膈下肋骨的屏气方式", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】膈上肋骨（第1~9肋）以含气肺组织为背景，深吸气后屏气可使膈肌下降、肺野充气增加，肋骨与低密度肺形成良好对比，同时更多肋骨被“抬”到膈上；膈下肋骨（第9~12肋）以肝、脾、肾等实质脏器为背景，深呼气后屏气使膈肌上升，肋骨相对下移离开肺野并减少呼吸运动，且需相应提高曝光条件穿透腹部。【为什么错】B把两者完全颠倒。C、D一刀切，忽视了膈上与膈下背景组织密度的根本差别。E平静呼吸曝光会造成呼吸运动模糊，任何肋骨摄影都应屏气。", "tr": "肋骨摄影还须注意：斜位可使腋段肋骨展开、避免与脊柱重叠；外伤患者应按临床压痛点选择照射范围与投照方向，且膈下肋骨曝光条件近似腹部而非胸部，条件照搬胸部会导致穿透不足。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0117", "t": "多选题", "s": "关于心脏三位片（心脏远达片、右前斜位、左前斜位）与食管钡餐联合检查，下列说法正确的是", "o": {"A": "心脏后前位远达片采用180~200cm焦-片距，目的是使心影放大率接近真实、便于测量心胸比", "B": "右前斜位（第一斜位）通常取45°~55°，同时口服钡剂充盈食管，主要观察左心房增大对食管中段的压迫", "C": "左前斜位（第二斜位）通常取60°~65°，可较好显示左右心室、主动脉弓及其分支的展开", "D": "食管钡剂应在曝光前一次大量吞服并等待完全排空后摄影", "E": "心脏远达片应在深呼气后屏气曝光，以使膈肌上升、心影充分显露"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-005", "kp": "心脏三位片与食管钡餐", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A正确：心脏距探测器较远（物-片距大），只有加大SID至180~200cm才能把放大率控制在5%以内，使心胸比测量可靠。B正确：右前斜位使食管与左心房在切线方向上分开，服钡后可直观显示左心房增大所致的食管中段受压后移，是二尖瓣病变的经典征象。C正确：左前斜位60°~65°可把室间隔置于近似切线位，分别展示左、右心室缘，并使主动脉弓呈“开窗”状显示。【为什么错】D错误：食管钡餐应在曝光瞬间嘱患者含服并吞下一口稠钡，使食管处于充盈状态时曝光；等待“完全排空”后摄影则食管内无对比剂，根本无法观察压迫。E错误：心脏远达片与常规胸片一样在深吸气后屏气曝光；深呼气会使膈肌上升、心影横位增大并压缩肺野，导致心胸比虚假增大。", "tr": "第一斜位（右前斜）看左心房与肺动脉段，第二斜位（左前斜）看左右心室与主动脉弓，二者的角度与观察重点最易混淆。心胸比测量必须建立在“立位、深吸气、180cm以上SID”三个前提上，缺一即失去可比性。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U08-0118", "t": "案例分析题", "s": "患者男性，24岁，胸部外伤后突发左侧胸痛、呼吸困难，急诊怀疑左侧气胸。患者血流动力学稳定，能站立配合。急诊技师首次拍摄的立位后前位胸片未见明确肺压缩带，临床仍高度怀疑。此时应采取的技术措施与判读要点，下列错误的是", "o": {"A": "加摄深呼气相后前立位片：呼气时肺体积缩小而胸膜腔内气体量基本不变，气胸所占比例相对增大，肺压缩缘更易显示", "B": "若患者随后病情变化只能仰卧，应注意仰卧位气胸气体聚集于前内侧，可表现为患侧肋膈角异常加深透亮的“深沟征”", "C": "为提高检出率，应把管电压降至60kV以下以增强软组织对比", "D": "可加摄健侧向下的侧卧水平投照位，使气体升至患侧胸壁外侧带而易于识别", "E": "胸片仍阴性但临床高度怀疑时，可建议行胸部CT，其对少量气胸的敏感性明显高于普通X线"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-006", "kp": "气胸的X线摄影技术优化", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】本题选错误项。C错误：气胸的检出依赖气体与肺组织之间的天然高对比，胸部摄影本就采用高千伏（约120kV）技术以减小肋骨与纵隔的遮盖、扩大灰阶宽容度；把管电压降到60kV以下会使肋骨骨影浓重、纵隔穿透不足，反而掩盖细小的压缩肺缘。【为什么错】A正确：呼气相时肺内含气减少、密度升高，而胸膜腔内游离气体量不变，两者密度差加大，压缩肺缘的细线影更易辨认。B正确：仰卧位气体上浮至前胸与肋膈隐窝前部，形成患侧肋膈角异常加深、透亮度增高的深沟征，是床旁片识别气胸的关键间接征象。D正确：气体向高处聚集，故取健侧向下侧卧（患侧在上）、水平方向投照，气体沿患侧外侧胸壁形成带状透亮区。E正确：CT可检出X线难以显示的少量与包裹性气胸，是平片阴性而临床高度怀疑时的合理建议。", "tr": "“提高软组织对比就要降kV”这一惯性思维在胸部摄影中不成立——胸部要的是宽容度而非高对比。另注意侧卧位的方向：查气体是健侧向下，查液体是患侧向下，两条口诀方向相反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U08-0119", "t": "单选题", "s": "胸锁关节后前位摄影的常规摆位与中心线，下列最恰当的是", "o": {"A": "俯卧或立位面向探测器，两臂放于身旁、下颌前伸，正中矢状面对准探测器中线，中心线经第3胸椎水平垂直射入，屏气曝光", "B": "仰卧，中心线经胸骨柄向头侧倾斜25°射入", "C": "立位侧位，中心线经腋中线第6胸椎射入", "D": "俯卧，身体向被检侧旋转45°，中心线向足侧倾斜30°", "E": "仰卧，中心线经剑突垂直射入，深吸气后屏气"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-007", "kp": "胸锁关节摄影体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸锁关节后前位取俯卧或立位面向探测器，正中矢状面对准中线并垂直于探测器，下颌前伸避免遮挡，两臂置于身旁，中心线经第3胸椎水平（约相当于胸锁关节水平）垂直射入，屏气以消除呼吸运动。为减少与胸椎、纵隔的重叠，临床常在此基础上加摄身体旋转10°~15°的轻度斜位，分别显示两侧关节。【为什么错】B向头侧25°会使关节与颈根部软组织重叠，且仰卧位物-片距增大。C为胸部侧位，两侧胸锁关节完全重叠。D的45°旋转过大并配合足侧30°倾斜，会使关节结构严重变形。E剑突水平远低于胸锁关节，照射野不含目标结构。", "tr": "胸锁关节位置高（约第3胸椎水平），与常见的“胸部中心线T6”不同；且因与脊柱重叠，单纯正位常难判断半脱位，须加摄小角度斜位或进一步做CT。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0120", "t": "单选题", "s": "腹部仰卧前后位（KUB）摄影的常规要求，下列错误的是", "o": {"A": "照射野上缘应包括两侧肾上极，下缘包括耻骨联合，两侧包括腹壁软组织", "B": "中心线经剑突与耻骨联合连线中点（约脐水平）垂直射入", "C": "焦-片距100cm，使用滤线栅", "D": "呼气后屏气曝光，以减少膈肌与肠管运动造成的模糊", "E": "为显示膈下游离气体，KUB仰卧位是首选体位"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-001", "kp": "腹部仰卧前后位（KUB）的技术要求", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】本题选错误项。E错误：仰卧位时游离气体上浮至腹壁下方而非膈下，与含气肠管重叠难以辨认；显示膈下游离气体必须用立位腹部（或不能站立者用左侧卧水平投照位），使气体聚集在膈肌与肝顶或右侧腹壁与肝之间形成新月形透亮影。【为什么错】A正确：KUB即肾-输尿管-膀胱，范围必须自肾上极至耻骨联合，否则输尿管全程或膀胱区结石会被漏掉。B正确：中心线经剑突与耻骨联合连线中点、约脐水平垂直射入。C正确：腹部厚度大、散射线多，须用滤线栅，SID为100cm。D正确：呼气后屏气可减小膈肌运动幅度并使腹部厚度略减。", "tr": "KUB与“急腹症腹部立位片”目的不同：KUB主要看泌尿系阳性结石与钙化，立位片主要看游离气体与肠管气液平面。临床怀疑消化道穿孔时只拍仰卧位是典型的技术失误。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0121", "t": "案例分析题", "s": "患者男性，46岁，突发上腹剧痛4小时，腹肌紧张，临床高度怀疑消化道穿孔，需X线证实有无膈下游离气体。患者疼痛剧烈，勉强可在搀扶下站立数分钟。作为技师，下列处理最恰当的是", "o": {"A": "立即在患者刚站起时曝光，避免其体力不支", "B": "让患者站立或坐位保持5~15分钟后再曝光，照射野上缘务必包全两侧膈肌，中心线经剑突下方水平射入，深呼气后屏气", "C": "取仰卧前后位，中心线垂直经脐部射入，深吸气后屏气", "D": "取俯卧位水平侧位投照，中心线经腰部射入", "E": "先行腹部加压后摄立位片，以推开肠管显露膈下"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-002", "kp": "腹部立位显示膈下游离气体", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】游离气体需要时间从穿孔部位上浮聚集到膈下，故应让患者站立或坐位保持数分钟（一般5~15分钟）后再曝光，否则少量气体尚未聚集易致假阴性。照射野上缘必须包含双侧膈肌，中心线经剑突下方水平射入，深呼气后屏气使膈肌上升、膈下间隙显示清楚。【为什么错】A立即曝光是最常见的假阴性原因。C仰卧位气体不在膈下，且中心线经脐部时膈肌常被切除在照射野外。D俯卧位水平侧位不是显示膈下游离气体的标准方法，气体会移向腹侧而非膈下。E腹部加压是静脉肾盂造影中滞留对比剂的手段，对急腹症属禁忌，压迫可加重穿孔与疼痛。", "tr": "两个高频失分点：一是“站立等待时间”常被忽略；二是照射野上缘未包全膈肌，导致片子上根本看不到膈下区域。对完全不能站立者，应改取左侧卧水平投照位，观察肝右缘与右侧腹壁间的游离气体。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0122", "t": "多选题", "s": "关于不能站立患者的腹部水平方向投照检查，下列说法正确的是", "o": {"A": "新生儿、危重或年老体弱不能站立者，可取左侧卧水平投照位代替立位腹部片", "B": "取左侧卧位是因为肝脏位于右侧、密度均匀，游离气体上浮到右侧腹壁与肝之间形成条带状透亮影，易于识别", "C": "侧卧后应停留数分钟待气体充分上浮再曝光", "D": "水平投照时X线中心线必须与地面平行，若沿用垂直投照则不能显示气液平面", "E": "新生儿坏死性小肠结肠炎疑有穿孔时，因患儿无法配合，只能采用仰卧前后位垂直投照"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-003", "kp": "侧卧水平位与仰卧水平侧位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】A正确：立位是显示游离气体与气液平面的首选，但新生儿、休克、脊柱外伤等无法站立者只能改用水平方向投照的卧位技术。B正确：左侧卧使右侧朝上，肝脏为均质实质器官、无肠气干扰，游离气体聚集于肝与右侧腹壁之间形成清晰带状透亮区；若取右侧卧则气体升至左侧，易与胃泡、结肠脾曲气体混淆。C正确：与立位同理，需静置数分钟待气体迁移到位。D正确：显示气液平面与游离气体的本质是利用重力分层，只有中心线与液面平行（即水平投照）才能把界面投影成清晰的线，垂直投照会把分层信息“压平”而丢失。【为什么错】E错误：新生儿虽不能站立，但完全可以采用仰卧水平侧位（患儿仰卧不动、X线自侧方水平射入）或左侧卧水平投照位；这类技术只需移动球管与探测器而无须患儿配合，是新生儿气腹诊断的常规方法。仅拍仰卧前后位垂直投照会漏诊游离气体。", "tr": "关键不是“卧位还是立位”，而是“X线是否水平”。很多考生记成“侧卧位可显示液平”，忽略了必须配合水平投照；同时要记牢腹部取左侧卧（肝为背景），与胸部查积液取患侧卧的逻辑不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0123", "t": "单选题", "s": "新生儿先天性肛门闭锁行腹部倒立侧位摄影，下列操作要点错误的是", "o": {"A": "检查前应先将患儿倒立约1~5分钟，使结肠内气体充分上升至直肠盲端", "B": "在肛门隐窝处（正常肛门位置的皮肤上）粘贴金属标记物作为测量参照", "C": "取侧位、中心线经大转子水平水平方向射入，包括耻骨联合与骶尾骨", "D": "通过测量直肠盲端气体影与肛门皮肤标记之间的距离，判断闭锁位置的高低", "E": "为使气体尽快到达盲端，倒立前应先经肛门注入适量气体以加速充气"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-004", "kp": "先天性肛门闭锁的倒立侧位摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】本题选错误项。E错误：肛门闭锁患儿肛门无通道，根本无法经肛门注气；该检查依赖的是患儿出生后吞咽空气自然到达远端肠管，所以通常需在出生12~24小时后进行，过早检查因肠气尚未到达盲端会造成闭锁位置“假性偏高”。【为什么错】A正确：倒立数分钟是让气体上浮抵达盲端的必要步骤。B正确：肛门隐窝处贴金属标记提供体表参照，是距离测量的基准。C正确：取侧位、水平方向投照并包全耻骨联合与骶尾骨，因为临床按耻骨-尾骨连线（PC线）判断高中低位闭锁。D正确：盲端气体影至皮肤标记的距离是分型的量化指标，距离大提示高位闭锁。", "tr": "两个关键前提最易被忽略：一是检查时机（生后12~24小时，让吞入气体到达盲端），二是必须水平投照并包含耻骨联合和尾骨以便画PC线。“注气加速”是明显违背解剖事实的干扰项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U08-0124", "t": "单选题", "s": "腹部X线摄影前的常规准备，下列不恰当的是", "o": {"A": "检查前1~2日不服含金属的药物，不做钡剂造影检查", "B": "必要时于检查前晚服缓泻剂或检查前行清洁灌肠，以减少肠内容物与气体干扰", "C": "去除腰腹部衣物上的金属扣、拉链及膏药等高密度异物", "D": "急腹症疑似穿孔或肠梗阻的患者，应先行清洁灌肠再摄片", "E": "嘱患者摄影时呼气后屏气，减少运动模糊"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-005", "kp": "腹部摄影前准备与禁忌", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】本题选不恰当项。D错误：急腹症尤其疑似消化道穿孔或肠梗阻时禁忌清洁灌肠——灌肠可加重穿孔、诱发肠破裂，还会注入气体与液体，干扰对游离气体与气液平面的判断。此类患者应直接摄片，不做肠道准备。【为什么错】A正确：钡剂与含金属药物残留会形成高密度伪影，掩盖泌尿系结石等病变。B正确：择期腹部平片（如KUB、IVP前）需清洁肠道以提高显示率。C正确：衣物金属件与膏药是常见的伪影来源。E正确：呼气后屏气可减小膈肌活动、降低运动模糊。", "tr": "肠道准备的适用范围要分清：择期泌尿系检查需要准备，急腹症一律不做准备、不灌肠、不口服对比剂。把常规准备“机械套用”到急诊是临床与考试中的双重错误。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0125", "t": "单选题", "s": "颈椎左后斜位摄影（身体左后方靠近探测器，与探测器约成45°），中心线向头侧倾斜15°，该体位显示的椎间孔是", "o": {"A": "左侧（靠近探测器侧）椎间孔", "B": "右侧（远离探测器侧）椎间孔", "C": "两侧椎间孔同时展开显示", "D": "左侧椎弓峡部而非椎间孔", "E": "两侧关节突关节，椎间孔不显示"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-001", "kp": "颈椎斜位显示椎间孔的规律", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】颈椎椎间孔向前、外、下方开口，与矢状面约成45°、与水平面约成15°。采用后斜位（身体后方靠近探测器）时，靠近探测器一侧的椎间孔恰好与中心线方向一致而被展开，故左后斜位显示左侧椎间孔；中心线向头侧倾斜15°是为了抵消椎间孔向下倾斜的角度。【为什么错】B是前斜位的规律——前斜位显示的是远离探测器的对侧椎间孔，二者规律相反。C任何单一斜位都只能展开一侧椎间孔，另一侧因投照方向不一致而变形缩窄，所以颈椎斜位必须左右各摄一张。D椎弓峡部与“苏格兰狗”征是腰椎斜位的内容，颈椎斜位主要看椎间孔与钩椎关节。E关节突关节在颈椎侧位显示最佳，斜位的目的正是椎间孔。", "tr": "记忆口诀：“后斜看同侧、前斜看对侧”，这是颈椎斜位最核心也最易混的考点。此外别把颈椎斜位的15°头侧倾斜与腰椎斜位（垂直中心线、45°旋转）混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0126", "t": "单选题", "s": "颈椎张口位摄影的摆位要点与显示结构，下列正确的是", "o": {"A": "患者仰卧、口尽量张大，使上颌门齿咬合面与乳突尖的连线垂直于探测器，中心线经两口角连线中点垂直射入，主要显示寰枢关节与齿突", "B": "患者仰卧、下颌内收，中心线向头侧倾斜15°，主要显示C1~C3椎体前缘", "C": "患者俯卧张口，中心线向足侧倾斜25°，主要显示枕骨大孔", "D": "患者侧卧张口，中心线经外耳孔垂直射入，主要显示颞下颌关节", "E": "患者仰卧张口，中心线经甲状软骨垂直射入，主要显示C6~C7椎间隙"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-002", "kp": "颈椎张口位（寰枢关节）", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】张口位专为显示被上下颌骨遮挡的寰椎、枢椎而设计。摆位时患者仰卧、正中矢状面垂直于台面并对准中线，口尽量张大，调整头部使上颌门齿咬合面与乳突尖的连线垂直于探测器——这样上颌切牙与枕骨基底部的投影恰好重叠于齿突之外，齿突、寰枢外侧关节间隙才能完整暴露。中心线经两口角连线中点垂直射入。标准影像应显示齿突居中、两侧寰枢关节间隙对称。【为什么错】B不张口时齿突被门齿与枕骨完全遮盖。C俯卧张口不便且25°足侧倾斜显示的是枕骨方向。D为颞下颌关节侧位思路。E甲状软骨约平C4~C5，且下颈椎不需要张口。", "tr": "张口位失败最常见的两个原因：一是张口不足或基准线不准，导致门齿或枕骨基底部遮盖齿突；二是头部旋转造成齿突偏离中线、两侧关节间隙不等宽，易被误判为寰枢关节半脱位。判读前须先确认体位是否标准。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0127", "t": "多选题", "s": "关于腰椎斜位摄影与“苏格兰狗”征，下列描述正确的是", "o": {"A": "腰椎斜位一般使身体冠状面与探测器成45°，中心线经髂嵴上方约3cm、脊柱旁开约5cm处垂直射入", "B": "“狗嘴”为同侧横突，“狗眼”为椎弓根，“狗耳”为上关节突，“狗颈”为椎弓峡部，“狗身”为椎板，“前腿”为下关节突", "C": "椎弓峡部裂时表现为“狗颈”部出现透亮的带状裂隙，形似狗颈上戴了一条项圈", "D": "后斜位显示的是靠近探测器一侧的椎弓附件结构", "E": "腰椎斜位主要用于显示椎间孔，与颈椎斜位的目的完全相同"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-003", "kp": "腰椎斜位与椎弓峡部裂", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A正确：腰椎斜位常规取45°（腰骶部有时用30°），中心线经髂嵴上方约3cm、棘突旁开约5cm垂直射入，可使一侧椎弓附件呈切线展开。B正确：这是“苏格兰狗”各部分与解剖结构的标准对应关系。C正确：峡部（狗颈）出现透亮裂隙即“戴项圈征”，是峡部裂的直接征象，常见于L5。D正确：腰椎后斜位同样遵循“后斜显示近片侧”的规律，展示的是靠近探测器一侧的椎弓根、峡部与关节突。【为什么错】E错误：腰椎斜位的核心目的是显示椎弓峡部与关节突关节，而腰椎椎间孔在侧位上显示最清楚；颈椎的椎间孔才需要斜位展开。二者目的并不相同。", "tr": "“看椎间孔”这一说法在颈椎成立、在腰椎不成立，这是脊椎摄影最典型的张冠李戴。另注意峡部裂多发于L5，摄影时下缘务必包全腰骶段，照射野过高会漏掉责任节段。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U08-0128", "t": "案例分析题", "s": "患者女性，36岁，反复颈部疼痛伴活动后加重2年，颈椎正侧位片未见明显骨质异常，临床怀疑颈椎节段性不稳，要求进一步行功能位检查以评估椎体间的动态位移。患者无外伤史、无神经根刺激症状、颈部可主动活动。作为技师，下列做法错误的是", "o": {"A": "摄取颈椎过伸位与过屈位侧位片，两片曝光条件与焦-片距保持一致，便于对比椎体后缘连线的连续性", "B": "嘱患者在能耐受范围内主动最大限度前屈与后伸，不得由他人强行推压头部协助", "C": "焦-片距取150cm，双肩尽量下垂以充分显示下颈椎", "D": "对急性颈部外伤、疑有骨折或脱位者，禁止行过伸过屈位检查", "E": "为节省时间，可只摄过屈位一张，因不稳定多在屈曲时显现"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-004", "kp": "颈椎过伸过屈功能位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】本题选错误项。E错误：颈椎节段性不稳既可表现为屈曲位的椎体前滑移，也可表现为后伸位的后滑移，只摄过屈位一张会遗漏后伸时才显现的不稳；标准做法是过屈位、过伸位各摄一张并与中立侧位比较。【为什么错】A正确：功能位的价值在于两片间对比，只有保持相同SID与曝光条件、相同侧位方向，位移测量才具可比性。B正确：必须由患者主动完成，被动推压可能造成脊髓损伤，是安全底线。C正确：颈椎侧位因肩部遮挡、物-片距较大，常规取150cm并嘱双肩下垂（必要时手持重物），以显示至C7~T1。D正确：急性外伤、可疑骨折或不稳定脱位是过伸过屈位的明确禁忌，应先行CT明确。", "tr": "功能位的两大红线：一是急性外伤禁做，二是必须主动、不可被动。技术上还须强调两片条件一致，否则放大率差异会造成假性位移。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0129", "t": "单选题", "s": "腰椎前后位与侧位摄影，下列关于中心线与技术要点的描述，正确的是", "o": {"A": "前后位取仰卧屈髋屈膝，中心线经脐上约3cm（相当于第3腰椎）垂直射入；侧位双膝间垫棉垫使腰椎长轴与台面平行，中心线经第3腰椎垂直射入", "B": "前后位中心线应经剑突水平射入，侧位经髂嵴水平射入", "C": "前后位应伸直双下肢以增大腰椎前凸，使椎间隙展开", "D": "侧位摄影时无须使用滤线栅，因侧位体厚较小", "E": "腰椎摄影焦-片距应取150cm以减小放大"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-005", "kp": "腰椎正侧位摄影技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎前后位取仰卧、屈髋屈膝并使足底踏于台面，目的是减小腰椎生理前凸、使椎体与探测器平行、椎间隙展开；中心线经脐上约3cm（约L3水平）垂直射入。侧位时于腰部与两膝间加棉垫，使腰椎长轴与台面平行（避免下沉造成椎间隙倾斜），中心线经L3垂直射入，必要时对腰骶段中心线向足侧倾斜5°~10°。【为什么错】B剑突约平T9，髂嵴约平L4~L5间隙，两者都不是标准入射点。C伸直下肢会加大腰椎前凸，椎间隙反而倾斜、变窄，与目的相反。D腰椎侧位体厚远大于正位，散射线更多，必须使用滤线栅并提高曝光条件。E腰椎摄影常规SID为100cm，150cm用于颈椎侧位。", "tr": "屈髋屈膝的机制是“减小前凸让椎间隙与中心线平行”，与“让患者舒适”无关，容易被反向表述迷惑。侧位加垫的目的同样是让脊柱长轴与台面平行，尤其在臀部宽大的患者中不可省略。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0130", "t": "多选题", "s": "关于骶骨与尾骨X线摄影，下列描述正确的是", "o": {"A": "骶骨前后位中心线向头侧倾斜15°~20°，经耻骨联合上方约3cm射入，以抵消骶骨向后倾斜造成的重叠与缩短", "B": "尾骨前后位中心线向足侧倾斜10°~15°，经耻骨联合上方约3cm射入", "C": "骶尾骨侧位可在一张影像上同时显示骶骨与尾骨，中心线经髂后下棘前方约8cm处垂直射入", "D": "摄影前应尽量排空膀胱并清洁肠道，避免肠内容物与气体重叠", "E": "骶骨与尾骨的中心线倾斜方向相同，都向头侧倾斜"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-006", "kp": "骶尾椎摄影的角度", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A正确：骶骨在仰卧位向后下方倾斜，垂直投照会使其缩短并与耻骨重叠，故中心线向头侧倾斜15°~20°。B正确：尾骨自骶骨末端继续向前下弯曲，其倾斜方向与骶骨相反，需中心线向足侧倾斜10°~15°才能展开。C正确：侧位时骶尾骨位于同一平面，可一次显示，且对骶骨骨折与尾骨脱位的评估价值高于正位。D正确：直肠内粪便与气体、充盈的膀胱都会明显干扰骶尾骨的观察，故需肠道准备并排空膀胱。【为什么错】E错误：骶骨向头侧、尾骨向足侧，两者中心线方向恰好相反，这正是本知识点的核心。", "tr": "“骶头尾足”是记忆抓手：骶骨向头侧15°~20°，尾骨向足侧10°~15°。若一次曝光同时想看骶尾骨，正位无法兼顾角度，应分别摄影或直接采用侧位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0131", "t": "单选题", "s": "骨盆前后位摄影时，为使股骨颈充分展开、减少大小转子与股骨颈的重叠，双足应", "o": {"A": "自然外旋位", "B": "内旋15°~20°，两足拇趾内侧相靠", "C": "外旋45°", "D": "极度背屈并保持中立位", "E": "屈髋屈膝并外展60°"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-007", "kp": "骨盆前后位的双足内旋", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】股骨颈存在约12°~15°的前倾角，仰卧自然状态下下肢多呈外旋，此时股骨颈与探测器不平行，投影缩短并与大转子重叠。将双足内旋15°~20°（两足拇趾内侧相靠、足跟稍分开）可抵消前倾角，使股骨颈呈最大长度显示，小转子部分被遮挡为正常表现。中心线经两髂前上棘连线中点下方约3cm（约耻骨联合上方3cm）垂直射入。【为什么错】A自然外旋正是需要纠正的状态。C外旋45°会使股骨颈严重缩短、小转子完全暴露。D单纯背屈不改变股骨旋转。E屈髋外展60°是蛙式位的摆位，不属于骨盆标准前后位。", "tr": "内旋是常规骨盆/髋关节正位的要求，但疑有股骨颈骨折、髋关节脱位或严重疼痛者禁止强行内旋，以免加重移位——此时按原位摄影并加摄水平侧位。影像上“小转子完全清晰显示”往往提示下肢外旋、体位不标准。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0132", "t": "案例分析题", "s": "患者女性，78岁，跌倒后右髋剧痛、下肢外旋短缩，不能站立与活动。骨盆前后位片提示右股骨颈可疑骨折线，临床要求补充侧位以判断骨折移位与成角。患者疼痛剧烈，右下肢任何被动活动均引发剧痛。作为技师，最恰当的方案是", "o": {"A": "采用蛙式位（Lauenstein位），将右髋外展外旋以获得股骨颈侧位", "B": "采用水平侧位（穿股侧位）：患者仰卧，健侧下肢屈髋屈膝上抬移开，探测器竖立紧贴患侧髂嵴上方，X线自健侧向患侧水平方向经腹股沟射入", "C": "让患者侧卧，患侧在下拍摄常规侧位", "D": "重复前后位并加大曝光条件以显示骨折线", "E": "取俯卧位，中心线经骶骨向足侧倾斜30°射入"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-008", "kp": "股骨颈骨折的水平侧位摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】疑似股骨颈骨折者的侧位必须避免患肢任何被动外展外旋，标准做法是水平侧位（又称穿股侧位、Danelius-Miller法）：患者仰卧不动，仅将健侧下肢屈曲上抬移出照射野，探测器竖直紧贴患侧髂嵴上方并与股骨颈垂直，X线自健侧腹股沟方向水平射入，即可在不搬动患肢的前提下获得股骨颈与髋关节的侧位影像。【为什么错】A蛙式位需要髋关节外展外旋，可使骨折移位加重甚至损伤旋股内侧动脉，为该情形的禁忌。C让患侧在下侧卧同样需要大幅活动患肢并承重，风险与痛苦均不可接受。D加大曝光条件不能提供第二个投照方向，无法评估前后成角与移位。E俯卧且中心线角度与髋关节无关，得不到侧位信息。", "tr": "蛙式位适用于儿童股骨头骨骺滑脱、股骨头缺血坏死等择期检查，绝不能用于急性股骨颈骨折。凡外伤后剧痛、肢体畸形者，一律遵循“不搬动患者、移动球管与探测器”的原则。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U08-0133", "t": "单选题", "s": "胸椎前后位摄影时，为使各椎间隙尽量与中心线平行而清晰显示，正确的做法是", "o": {"A": "仰卧屈髋屈膝，中心线经胸骨角水平垂直射入，平静呼吸下曝光", "B": "仰卧屈髋屈膝使胸椎后凸减小，中心线经第6~7胸椎水平（约胸骨体中点）垂直射入，平静浅呼吸中曝光或屏气曝光", "C": "俯卧位，中心线向头侧倾斜20°射入", "D": "立位，中心线经剑突垂直射入，深吸气后屏气", "E": "仰卧，中心线经甲状软骨垂直射入，深呼气后屏气"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-009", "kp": "胸椎前后位摄影要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】胸椎前后位取仰卧、屈髋屈膝使背部平贴台面、胸椎后凸减小，中心线经第6~7胸椎水平（体表约相当于胸骨体中点、两侧肩胛下角连线上方）垂直射入。曝光可采用屏气，也可用低毫安长时间的“自主浅呼吸”技术，使肺纹理与肋骨影模糊而突出椎体轮廓。【为什么错】A胸骨角约平T4~T5，位置偏高，下胸椎易被切除；且完全的平静呼吸不加控制会造成整体运动模糊。C俯卧时椎体物-片距增大且20°头侧倾斜无解剖依据。D剑突约平T9~T10，中心线过低，上胸椎显示不全。E甲状软骨约平C4~C5，属颈椎范围。", "tr": "胸椎正位常见问题是上下段密度差过大（上胸椎被肩部与纵隔遮挡而偏白，下胸椎偏黑），处理方法包括使用楔形滤过板、阳极效应（把阳极端置于上胸椎侧）以及数字后处理的组织均衡技术。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0134", "t": "单选题", "s": "肩关节穿胸位（经胸侧位）摄影的主要适应证与摆位是", "o": {"A": "适用于肱骨近端骨折等患肢不能外展外旋者；患者侧立，患侧上臂紧贴探测器并下垂，健侧上肢高举抱头，中心线经健侧腋下水平穿过胸部对准患侧肱骨外科颈射入", "B": "适用于评价肩袖钙化；患者仰卧，中心线向头侧倾斜30°射入", "C": "适用于判断肩关节脱位方向；患者面向探测器旋转60°，中心线经肩胛骨内缘射入", "D": "适用于显示肩锁关节；患者立位双手持重物，中心线经两侧肩锁关节连线中点射入", "E": "适用于显示锁骨骨折；患者俯卧，中心线向足侧倾斜15°射入"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-001", "kp": "肩关节穿胸位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】穿胸位是在患肢无法活动时获得肱骨近端侧位信息的经典方法：患者侧立（患侧贴探测器）、患肢自然下垂并稍外旋以尽量避开肋骨重叠，健侧上肢高举抱头把肩部移开，中心线自健侧腋下水平穿过胸廓对准患侧外科颈。因需穿透胸廓，曝光条件高，常配合呼吸（低mA长时间）技术使肋骨与肺纹理模糊化。【为什么错】B为冈上肌出口位或肩关节前后位加角度的做法，与穿胸位无关。C描述的是肩胛骨Y位（肩胛骨侧位），用于判断脱位方向，但摆位角度与穿胸位不同。D是肩锁关节负重位。E是锁骨轴位的思路，且方向应向头侧倾斜。", "tr": "穿胸位与Y位都可提供“第二方向”，但适应证不同：穿胸位重点看肱骨近端骨折的成角移位，Y位重点看肱骨头相对于关节盂的前后脱位方向。二者常被混答。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0135", "t": "多选题", "s": "关于腕关节及手部摄影，下列描述正确的是", "o": {"A": "腕关节后前位取坐位、前臂平放，手掌向下呈半握拳状使腕骨紧贴探测器，中心线经桡骨茎突与尺骨茎突连线中点垂直射入", "B": "怀疑舟骨骨折时应加摄舟骨位：腕部尺偏，中心线可向肘侧（近端）倾斜10°~15°，使舟骨长轴接近平行于探测器而完整展开", "C": "手后前位摄影中心线经第3掌骨头垂直射入，可显示除拇指外各指骨、掌骨的正位", "D": "手斜位使手掌与探测器成45°、各指均匀分开并保持指骨与探测器平行，避免掌骨重叠", "E": "腕部外伤后首次X线检查未见骨折线，即可排除舟骨骨折，无须复查或进一步检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-002", "kp": "腕关节与手部摄影技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】A正确：半握拳可使腕骨掌屈贴近探测器、腕骨间隙展开，中心线取两茎突连线中点。B正确：舟骨斜跨腕骨、长轴倾斜，正位时投影缩短并与周围腕骨重叠，尺偏使舟骨伸展、配合向肘侧倾斜10°~15°的中心线可使其呈最大长度显示，是降低舟骨骨折漏诊率的关键。C正确：手后前位中心线经第3掌骨头，拇指因解剖旋转在此位上呈斜位。D正确：45°斜位并使手指分开、指骨平行于探测器，可避免掌骨互相重叠又不致指骨倾斜变形。【为什么错】E错误：舟骨骨折在伤后早期常因骨折线无分离而不显影，首次平片阴性并不能排除骨折；临床症状明显（鼻烟窝压痛）者应制动后于1~2周复查，或直接行CT/MRI，否则可能延误诊断并导致缺血坏死与不愈合。", "tr": "舟骨位的两个要点常只记住一个：尺偏（体位）与中心线成角（投照方向）必须配合使用。另需牢记“平片阴性≠无骨折”，舟骨是这一原则最经典的部位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0136", "t": "案例分析题", "s": "患者男性，19岁，篮球运动后右膝反复交锁伴疼痛，临床怀疑髌骨轨迹异常合并髁间窝内游离体。膝关节正侧位片未见明确异常，临床要求补充能显示髌股关节与髁间窝的X线体位。患者可自行屈膝、无急性外伤。作为技师，下列方案错误的是", "o": {"A": "加摄髌骨轴位（日出位）：患者屈膝约40°~60°，探测器置于髌骨远端，中心线沿髌骨与股骨滑车之间的间隙切线方向射入，观察髌股关节间隙与髌骨内外侧关节面", "B": "加摄髁间窝位（隧道位）：患者俯卧屈膝约40°~45°，中心线垂直于小腿长轴经腘窝射入，使髁间窝展开显示", "C": "髌骨轴位若屈膝角度过大，髌骨被拉入滑车沟内，早期髌股关节半脱位可能被掩盖", "D": "髁间窝位可用于显示髁间窝内游离体、剥脱性骨软骨炎及胫骨髁间隆突", "E": "上述特殊体位均属禁忌，急性膝关节外伤患者也不得屈膝摄影"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-003", "kp": "髌骨轴位与膝关节髁间窝位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】本题选错误项。E错误：本例为慢性症状、无急性外伤，患者可主动屈膝，髌骨轴位与髁间窝位均可安全实施；而且“急性外伤患者也不得屈膝摄影”把原则绝对化了——真正的规则是疑有骨折、脱位或剧痛时不做被动屈曲，改用水平侧位等不搬动患者的方法，并非所有外伤一律禁忌。【为什么错】A正确：髌骨轴位的本质是切线投照，使髌骨与股骨滑车间的关节面呈切线显示，用于评价髌股关节间隙、髌骨倾斜与半脱位。B正确：髁间窝位（隧道位）通过屈膝并使中心线垂直于小腿，把被髌骨与股骨髁遮挡的髁间窝打开。C正确：屈膝角度越大髌骨嵌入滑车沟越深，轻度半脱位被“复位”掩盖，故评价髌骨轨迹宜用较小屈曲角度。D正确：髁间窝位是显示游离体、剥脱性骨软骨炎与髁间隆突的经典体位。", "tr": "髌骨轴位的角度是把双刃剑：角度太小患者难以配合且股骨与髌骨重叠，角度过大则掩盖半脱位。命题常在“屈膝角度越大越好”上设陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0137", "t": "单选题", "s": "跟骨轴位摄影时，中心线的正确投照方向是", "o": {"A": "自足底向头侧倾斜35°~45°，对准第3跖骨基底部射入跟骨", "B": "垂直于足底射入", "C": "自足背向足侧倾斜30°射入", "D": "水平方向经内踝射入", "E": "自足跟后方向头侧倾斜10°射入"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-004", "kp": "跟骨轴位的中心线", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】跟骨轴位取仰卧或坐位，下肢伸直、踝关节尽量背屈（可用绷带牵拉足前部），足底垂直于探测器，中心线向头侧倾斜35°~45°，对准第3跖骨基底部射入跟骨，从而使跟骨体、跟骨结节及距下关节在轴向上展开而不与踝部重叠。【为什么错】B垂直射入会使跟骨与距骨、踝关节严重重叠。C方向相反，无法展开跟骨长轴。D水平经内踝是踝关节侧位的思路。E仅10°倾斜远不足以避开踝部重叠，跟骨仍呈缩短影像。", "tr": "跟骨检查应轴位与侧位联合：侧位用于测量Böhler角（跟骨结节关节角，正常约20°~40°），轴位用于观察跟骨体增宽、内翻及距下关节面。只拍其中一个位置是常见缺陷。踝背屈不足会使中心线与跟骨长轴夹角不当，影像仍缩短。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0138", "t": "单选题", "s": "关于踝关节前后位与“踝穴位”的区别，下列说法正确的是", "o": {"A": "踝穴位是在前后位基础上将小腿与足部内旋15°~20°，使踝关节内外侧间隙同时清晰显示，用于评价踝穴完整性", "B": "踝穴位是将足外旋45°后摄影", "C": "踝穴位与前后位摆位相同，仅提高曝光条件", "D": "踝穴位需中心线向头侧倾斜25°", "E": "踝穴位主要用于显示跟骨结节，与踝关节间隙无关"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-005", "kp": "踝关节前后位与踝穴位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】标准踝关节前后位时，因外踝较内踝更靠后，胫腓骨远端在投影上部分重叠，外侧关节间隙显示不清。将小腿连同足部一起内旋15°~20°（使两踝连线与探测器平行）即为踝穴位，此时内踝、外踝与距骨顶构成的“踝穴”三面间隙宽度一致，可敏感发现踝穴增宽、下胫腓联合分离等损伤。【为什么错】B方向相反，外旋会加重重叠。C体位不同才是关键，与曝光条件无关。D踝关节摄影中心线垂直于两踝连线中点上方约1cm处射入，不需向头侧成角。E跟骨结节由跟骨侧位与轴位显示。", "tr": "内旋的量要准确：不足则外侧间隙仍重叠，过度则内侧间隙假性增宽。踝穴位是判断下胫腓联合分离的关键位置，仅凭常规正位容易漏诊。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0139", "t": "多选题", "s": "关于四肢长骨与关节摄影的通用原则，下列正确的是", "o": {"A": "四肢长骨摄影应至少包含邻近的一个关节，以便定位并判断有无关节内骨折与旋转移位", "B": "正位与侧位的投照方向应互成90°，两个方向缺一不可", "C": "同一部位双侧对比摄影时，应采用相同的曝光条件、投照方向与体位，并在影像上标注左右", "D": "儿童骨骺损伤可疑时，可加摄健侧同名部位对照，但应权衡辐射剂量、避免常规化", "E": "为提高细节分辨力，四肢摄影应尽量使用大焦点、加大焦-片距至150cm"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-006", "kp": "四肢摄影通用原则", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】A正确：包含一端关节既可解剖定位，又能发现关节内骨折与旋转对位不良；前臂、小腿骨折还应尽量包含上下两端关节以判断合并脱位（如孟氏、盖氏骨折）。B正确：两个互相垂直的投照方向是判断骨折成角与移位方向的基本要求，单一方向可能完全漏掉侧方成角。C正确：双侧对比只有在条件、方向、体位一致时才具可比性，且必须标注左右防止差错。D正确：健侧对照对判断儿童骨骺与骨化中心有帮助，但属额外照射，应个体化而非常规。【为什么错】E错误：四肢摄影追求高空间分辨力，应使用小焦点、缩小物-片距，SID常规为100cm；大焦点会增大半影、降低清晰度，盲目加大SID则显著增加曝光量。", "tr": "“大焦点=大功率=更好”是典型误解。焦点选择取决于分辨力需求与管电流负荷：细节要求高、曝光量不大的四肢与乳腺用小焦点，需大电流的躯干厚部位才用大焦点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U08-0140", "t": "单选题", "s": "肘关节侧位摄影的标准摆位是", "o": {"A": "屈肘90°，尺侧（小指侧）紧贴探测器、拇指朝上，肩部下降与肘关节置于同一水平面，中心线经肱骨外上髁垂直射入", "B": "伸直肘关节，手掌向上，中心线经鹰嘴垂直射入", "C": "屈肘45°，手背贴板，中心线向头侧倾斜20°射入", "D": "屈肘135°，前臂旋前，中心线经内上髁射入", "E": "伸直肘关节并极度旋前，中心线经桡骨头垂直射入"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-007", "kp": "肘关节侧位摄影要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】肘关节侧位要求屈肘90°、前臂呈中立位（尺侧贴板、拇指向上），并将肩部下降至与肘关节同一水平，使肱骨与前臂处于同一平面。标准影像的判据是肱骨内、外上髁相互重叠，肱骨滑车与小头呈同心圆状，鹰嘴与冠突清晰，桡骨头与尺骨冠突部分重叠。中心线经肱骨外上髁垂直射入。【为什么错】B伸直位无法形成侧位，且鹰嘴与肱骨完全重叠。C屈肘45°达不到标准侧位，且成角20°没有依据。D屈肘135°过小、前臂旋前会使桡尺骨交叉重叠。E极度旋前使桡骨头旋转变位，且伸直位不成侧位。", "tr": "“肩没有放下来”是肘侧位最常见的失败原因：肩部高于肘部时肱骨呈斜位，两上髁不能重叠，滑车与小头分离，容易被误判为关节间隙异常。评价肘部外伤时还应注意脂肪垫征（后脂肪垫抬高提示关节积液/隐匿骨折），这要求标准90°侧位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0141", "t": "单选题", "s": "静脉肾盂造影（IVP）中使用腹部压迫带的目的与要点，下列正确的是", "o": {"A": "压迫点位于两侧髂前上棘连线水平稍下方，压迫输尿管使对比剂滞留于肾盂肾盏内以提高显示率；解除压迫后立即摄全尿路片观察输尿管全程", "B": "压迫点位于剑突下方，用于阻断肾动脉血流延长显影时间", "C": "压迫的目的是加快对比剂经输尿管排入膀胱", "D": "所有受检者均须加压，包括腹主动脉瘤与急腹症患者", "E": "压迫应在注射对比剂后30分钟才开始施加"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-001", "kp": "IVP腹部压迫技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】腹部压迫带压在两侧髂前上棘连线水平稍下方，此处输尿管跨越骨盆缘、位置表浅，加压可暂时阻断对比剂下行，使肾盂肾盏充分充盈扩张、细节显示更佳。摄取肾区片后解除压迫，立即摄取包含双肾至膀胱的全尿路片，观察输尿管全程通畅情况。【为什么错】B剑突下方压迫既压不到输尿管，也不可能阻断肾动脉。C与压迫的目的完全相反，压迫是滞留而非加速排出。D腹主动脉瘤、腹部巨大肿块、急腹症、近期腹部手术、妊娠及严重外伤者禁用加压。E压迫应在注射对比剂后早期即施加，30分钟后肾盂显影高峰已过，失去意义。", "tr": "加压是“提高肾盂显示”的手段，解压是“显示输尿管”的手段，两者一前一后不可颠倒。禁忌人群必须牢记，考试常用“腹主动脉瘤患者常规加压”作陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0142", "t": "多选题", "s": "关于静脉肾盂造影（IVP）的检查前准备与摄片程序，下列正确的是", "o": {"A": "检查前应清洁肠道，摄影前先拍摄全尿路平片，以了解肠道准备情况并观察阳性结石", "B": "常规于注射对比剂后约7分钟、15分钟、30分钟分别摄取肾区片，必要时延长至60分钟或更久摄延迟片", "C": "肾盂显影浅淡时可适当延长摄片时间或加摄俯卧位片，帮助对比剂充盈肾盂", "D": "检查前应了解肾功能、有无甲状腺功能亢进及碘对比剂过敏史，并备好抢救药品与设备", "E": "为提高肾盂显影浓度，应嘱患者检查前24小时严格禁水以造成脱水状态"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-002", "kp": "IVP检查前准备与摄片时间序列", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A正确：肠内容物与气体会掩盖肾影与输尿管，故需清洁肠道；造影前平片既是对照片，也用于判断准备是否合格及有无阳性结石。B正确：7、15、30分钟是经典的三个摄片时间点，分别对应肾盂肾盏充盈、输尿管显影、膀胱充盈，显影延迟者需加摄60分钟乃至数小时延迟片。C正确：俯卧位可借助体位使对比剂向肾盂集中并有助于输尿管上段充盈。D正确：碘对比剂使用前须评估肾功能、甲状腺功能与过敏史，并具备抢救条件。【为什么错】E错误：传统上曾用限水提高对比剂浓度，但现代指南明确反对为造影而使患者脱水——脱水显著增加对比剂肾病风险，尤其在糖尿病、肾功能不全与老年患者中，应保证适当水化。", "tr": "“禁水浓缩尿液”是被淘汰的旧做法，命题常以此设陷阱。摄片时间序列要与检查目的联动：肾功能减退者延迟片才是关键，机械照搬7/15/30分钟而不加延迟片会导致检查失败。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0143", "t": "案例分析题", "s": "患者男性，62岁，右侧腰痛伴血尿1周。血清肌酐明显升高（估算肾小球滤过率约25ml/(min·1.73m²)），超声提示右肾积水，需明确梗阻部位与程度。既往有轻度碘对比剂过敏史（表现为荨麻疹）。临床拟行泌尿系造影。作为技师，就检查方式的选择与技术要点，下列判断错误的是", "o": {"A": "该患者肾功能明显减退，静脉肾盂造影因肾排泄对比剂能力下降而显影不佳，不宜作为首选", "B": "可建议改行逆行肾盂造影：经膀胱镜向输尿管插管后直接注入对比剂，显影不依赖肾功能，且全身吸收量少", "C": "逆行肾盂造影时对比剂注入量与压力应严格控制（成人一侧通常数毫升至10ml左右，缓慢注入），避免压力过高引起肾盂-肾小管返流与感染扩散", "D": "有碘对比剂过敏史者，即使行逆行造影也应做好抗过敏与抢救准备，因对比剂仍可经黏膜或返流吸收", "E": "为提高显影效果，逆行造影时应尽可能快速、大量注入对比剂直至患者出现明显腰胀"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-003", "kp": "逆行肾盂造影的适应证与操作要点", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】本题选错误项。E错误：以“患者出现明显腰胀”作为注入终点极其危险——腰胀恰恰提示肾盂已过度充盈、腔内压力过高，是应立即停止注射的信号；快速大量注入可造成肾盂-肾小管返流、肾盂静脉返流，并把感染带入上尿路。【为什么错】A正确：IVP依赖肾小球滤过与浓缩排泄，肾功能减退时肾盂显影浅淡甚至不显影，并加重对比剂肾病风险。B正确：逆行造影把对比剂直接注入集合系统，不依赖排泄功能，是肾功能不全、IVP显影不佳或需精确判定梗阻部位时的替代方案。C正确：成人一侧注入量通常仅数毫升至10ml左右，须缓慢注入并在透视监视下进行。D正确：黏膜吸收与返流仍可使少量对比剂进入循环，有过敏史者需预案与抢救准备。", "tr": "肾功能不全并非泌尿系造影的绝对禁区，关键是换路径：静脉法改逆行法。同时牢记逆行造影的两大并发症来自“压力”与“无菌”，操作核心是缓慢、少量、透视监视、严格无菌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0144", "t": "单选题", "s": "下列属于静脉肾盂造影（IVP）禁忌证的是", "o": {"A": "碘对比剂严重过敏史、严重肝肾功能不全、甲状腺功能亢进未控制、多发性骨髓瘤伴肾功能损害及妊娠", "B": "单侧肾结石", "C": "肾盂积水", "D": "既往肾切除术后随访对侧肾", "E": "无痛性肉眼血尿待查"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-004", "kp": "IVP禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A所列均为公认禁忌：严重碘过敏史者可发生致命性反应；严重肝肾功能不全既显影不佳又易诱发对比剂肾病；未控制的甲亢患者碘负荷可诱发甲状腺危象；多发性骨髓瘤合并肾损害时对比剂可加速管型形成致急性肾衰；妊娠期应避免非必要的电离辐射。此外急性尿路感染活动期、严重心力衰竭也属禁忌或需慎用。【为什么错】B肾结石正是IVP的经典适应证之一，可判断结石与集合系统关系及梗阻程度。C肾盂积水需要IVP明确梗阻部位与分肾功能。D单肾患者虽需谨慎评估肾功能，但并非绝对禁忌。E血尿待查是泌尿系造影最常见的适应证。", "tr": "注意区分“禁忌证”与“需要慎重/需水化准备”的情况：糖尿病服二甲双胍者并非绝对禁忌，而是需按规范暂停用药并评估肾功能。把适应证误认为禁忌证（如肾结石、积水）是本题最常见的错误。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0145", "t": "单选题", "s": "膀胱造影的常规操作，下列不恰当的是", "o": {"A": "经导尿管排空膀胱后注入稀释的对比剂，成人一般约150~300ml，以患者出现膀胱充盈感为度", "B": "常规摄取前后位（中心线向足侧倾斜约10°~15°，经耻骨联合上方射入）及左右斜位", "C": "怀疑膀胱输尿管返流时可行排泄性膀胱尿道造影，在排尿过程中动态观察", "D": "前后位中心线向足侧倾斜的目的是避免耻骨联合与膀胱颈及膀胱下部重叠", "E": "急性下尿路感染期应立即行膀胱造影以明确病因"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-005", "kp": "膀胱造影技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】本题选不恰当项。E错误：急性下尿路感染期属禁忌或需推迟——导尿及注入对比剂可使感染上行扩散，加重病情，应先控制感染后再择期检查。【为什么错】A正确：排空后注入稀释对比剂，量以充盈感为度，过量可致膀胱破裂风险与患者不适。B正确：前后位加双斜位可显示膀胱各壁与输尿管开口区，斜位有助于发现被前后壁重叠掩盖的病变。C正确：排泄性膀胱尿道造影（VCUG）是诊断膀胱输尿管返流与后尿道病变的标准方法，需在排尿动态中观察。D正确：向足侧倾斜可将耻骨联合投影下移，避免遮挡膀胱颈与膀胱底部。", "tr": "急性尿路感染是所有经尿道器械操作（导尿、膀胱造影、逆行肾盂造影、尿道造影）的共同禁忌。命题常用“为尽快明确病因”这类合理化语气掩盖禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0146", "t": "多选题", "s": "关于男性尿道造影，下列描述正确的是", "o": {"A": "逆行尿道造影时患者常取右后斜位（身体与台面成约35°~45°），患侧下肢屈曲外展，使尿道全程展开而不与耻骨、股骨重叠", "B": "逆行法主要显示前尿道（阴茎部与球部），排泄性（顺行）尿道造影更利于显示后尿道（膜部与前列腺部）", "C": "注入对比剂时应缓慢、保持适当压力并在曝光瞬间维持充盈状态", "D": "尿道外伤急性期若需评价尿道连续性，应在严格无菌下轻柔操作，避免暴力插管加重损伤", "E": "为使前后尿道同时最佳显示，只需摄取标准前后位一张即可"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-006", "kp": "男性尿道造影技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A正确：斜位可把弯曲的男性尿道拉直展开，避开耻骨联合与股骨的重叠，是尿道造影必需的体位。B正确：逆行注入时括约肌收缩阻碍对比剂充分进入后尿道，故后尿道显示以排尿期顺行造影为佳，二者常联合应用。C正确：只有在保持充盈的瞬间曝光才能显示狭窄段的真实长度与程度。D正确：外伤后评价尿道连续性是逆行尿道造影的重要适应证，但操作须轻柔无菌，避免造成假道或加重撕裂。【为什么错】E错误：单一前后位时尿道与耻骨、股骨重叠、且弯曲段互相折叠，无法评估全程，必须采用斜位并结合逆行与排泄两种时相。", "tr": "“逆行看前、顺行看后”是本考点的记忆抓手。另注意造影剂宜选水溶性碘对比剂，禁用可能进入海绵体循环的油性对比剂；发现明显外渗应立即停止注射。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U08-0147", "t": "单选题", "s": "子宫输卵管造影（HSG）的最佳检查时机是", "o": {"A": "月经来潮当日", "B": "月经干净后3~7天，且检查前禁性生活", "C": "排卵期当天", "D": "月经前3天", "E": "任何时间均可，无时间限制"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-HSG-001", "kp": "HSG检查时机", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】HSG应安排在月经干净后3~7天内：此时子宫内膜已修复且较薄，不易造成内膜碎片经输卵管逆行进入腹腔或形成假性充盈缺损；同时尚未排卵，避免对早期妊娠的意外照射与对比剂损害。检查前需禁性生活以进一步排除妊娠可能。【为什么错】A月经期宫腔内有血液与内膜脱落，既影响判断又易将内膜与血块推入腹腔、增加感染与子宫内膜异位风险。C排卵期已有受孕可能，且此时操作可能干扰受精与着床。D月经前期内膜增厚，可造成假象且临近月经易出血，同时妊娠风险未除。E忽视妊娠风险与内膜周期变化，是明显错误。", "tr": "时机选择的两条逻辑：一是“避开妊娠可能”，二是“内膜要薄”。此外HSG禁忌包括生殖道急性或亚急性炎症、妊娠、子宫出血、刮宫或分娩后6周内以及碘对比剂过敏。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0148", "t": "案例分析题", "s": "患者女性，30岁，婚后2年未孕，男方精液检查正常，临床拟行子宫输卵管造影评价输卵管通畅性。既往无碘过敏史、无生殖道炎症，末次月经结束已4天。检查中注入对比剂后第一次点片显示子宫腔充盈良好，但双侧输卵管均未显影，患者诉下腹痉挛性疼痛明显。作为技师，下列处理错误的是", "o": {"A": "输卵管不显影可能由痉挛所致，可暂停注射、稍事等待或按医嘱使用解痉药后再次注入并复查", "B": "注入对比剂应缓慢、压力适中，压力过高、速度过快本身即可诱发输卵管痉挛与疼痛，并增加对比剂静脉与淋巴逆流风险", "C": "使用水溶性碘对比剂时，可在注药后约20~30分钟摄延迟片观察盆腔内弥散情况；若使用碘化油则需24小时后复查", "D": "对比剂经输卵管伞端弥散至盆腔、呈涂抹状分布，是输卵管通畅的重要征象", "E": "为迅速判定阻塞，应立即加大注射压力至输卵管显影为止"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-HSG-002", "kp": "HSG操作要点与假性阻塞", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】本题选错误项。E错误：加大压力强行“打通”输卵管可造成输卵管损伤、对比剂经子宫肌层静脉丛与淋巴管逆流入血（使用碘化油时甚至发生肺油栓），并诱发剧痛与迷走神经反射，属严重违规操作。【为什么错】A正确：输卵管痉挛可造成假性阻塞，是HSG最常见的假阳性来源，处理办法为暂停、等待或按医嘱使用解痉药后复查。B正确：注射压力与速度过大既加重疼痛与痉挛，又增加逆流风险。C正确：水溶性对比剂吸收快，20~30分钟延迟片即可观察盆腔弥散；碘化油吸收缓慢，需24小时后复查判断弥散与有无粘连。D正确：伞端溢出并在盆腔内呈涂抹状分布，是输卵管通畅的直接证据。", "tr": "碘化油与碘水的差别是高频考点：碘油显影浓、密度高、观察弥散需24小时，但可致油栓与异物肉芽肿；碘水刺激性较强、显影时间短，需20~30分钟复查，但安全性高、细节佳。牢记“不显影≠阻塞”，痉挛必须先排除。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0149", "t": "单选题", "s": "关于子宫输卵管造影所用对比剂的比较，下列说法正确的是", "o": {"A": "碘化油黏稠度高、显影密度大，充盈缓慢，需在24小时后复查以观察盆腔弥散，但存在油栓与异物肉芽肿风险", "B": "碘化油吸收快，20分钟即可完成弥散观察", "C": "水溶性碘对比剂因黏稠度大而不易通过输卵管，故不推荐使用", "D": "水溶性碘对比剂无任何刺激性，注入后不引起腹痛", "E": "两类对比剂在显影密度、吸收速度与并发症方面基本相同，可任意互换"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-HSG-003", "kp": "HSG对比剂的选择与比较", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】碘化油为油性对比剂，黏稠度高、原子序数高故显影密度大、影像对比强，但通过输卵管缓慢，需在24小时后复查以观察盆腔内弥散是否均匀（判断有无粘连）；其主要风险是进入血管后引起肺油栓，以及长期滞留形成异物肉芽肿。【为什么错】B吸收快的是水溶性对比剂，碘化油吸收极慢，可在盆腔滞留数月。C水溶性对比剂黏稠度低、流动性好，容易通过输卵管，是目前更常用的选择。D水溶性对比剂具有一定高渗性与刺激性，注入后常引起下腹痛或痉挛，说其“无任何刺激性”是绝对化的错误表述。E两者在显影密度、吸收速度、复查时间与并发症谱上差异明显，不可随意互换。", "tr": "复查时间是最容易记混的点：碘水20~30分钟、碘油24小时。另需注意二者的临床取舍——碘油图像对比更强并有文献报道的助孕效应，但安全性以水溶性更优，选择需结合患者状况。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0150", "t": "多选题", "s": "关于子宫输卵管造影的并发症及其防范，下列说法正确的是", "o": {"A": "对比剂静脉与淋巴逆流多由注射压力过高、内膜损伤或宫腔操作粗暴引起，一旦发现应立即停止注射", "B": "盆腔感染是重要并发症，故检查前须排除生殖道急性与亚急性炎症，并全程严格无菌操作", "C": "部分患者可出现迷走神经反射（面色苍白、出汗、心率减慢、血压下降），需立即停止操作、平卧观察并按需处理", "D": "使用碘化油时可发生肺油栓，与对比剂经损伤的子宫静脉丛进入循环有关", "E": "造影后出现少量阴道流血必为子宫穿孔，须立即手术探查"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-HSG-004", "kp": "HSG并发症与处理", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】A正确：逆流是压力性并发症的共同表现，处理原则是立即停止注射并降低压力。B正确：HSG属侵入性操作，术前炎症筛查与无菌是防止盆腔感染的核心。C正确：宫颈牵拉与宫腔扩张可诱发迷走反射，属常见术中不良反应，应立即停止操作并对症处理。D正确：碘油经内膜创面进入子宫静脉丛后可造成肺油栓，是碘油造影最严重的并发症。【为什么错】E错误：造影后1~2日内少量阴道流血十分常见，多因宫颈钳夹与导管刺激所致，一般无须特殊处理；把它一律等同于子宫穿孔并主张立即手术，既不符合临床实际，也是典型的绝对化错误表述。", "tr": "并发症的共同根源多为“压力过高”和“无菌不严”，防范措施围绕这两点展开。要区分常见轻微反应（少量出血、下腹隐痛）与需紧急处理的情况（剧痛不缓解、大量出血、逆流、过敏性休克）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0151", "t": "单选题", "s": "某医院行IVP时，注射对比剂后7分钟片显示右肾肾盂肾盏清晰显影，左侧肾区始终未见对比剂排泄，30分钟片仍无显影。技师首先应采取的合理措施是", "o": {"A": "加摄延迟片（如60分钟、2小时甚至更长时间），观察左肾是否为延迟显影", "B": "立即判定左肾无功能并结束检查", "C": "追加同等剂量对比剂重新注射", "D": "立即加大腹部压迫力度促使左肾显影", "E": "改为俯卧位并把管电压降至50kV再摄一张"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-007", "kp": "IVP一侧不显影的技术处理", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】一侧肾不显影常见原因包括梗阻性肾积水导致的排泄延迟、肾功能受损、先天缺如或肾动脉病变。技术上首先应做的是延迟摄片：梗阻侧肾常在数小时后出现“渐进性密度增高”的延迟显影，据此可判断梗阻部位与残余功能。仓促结束检查会遗漏关键信息。【为什么错】B在未做延迟片前即下“无功能”结论证据不足。C重复注射既增加对比剂肾病与过敏风险，也不能改变排泄延迟的本质。D加大压迫只影响输尿管滞留，与患侧不排泄无关，且过度压迫有害。E降低管电压至50kV会使腹部穿透严重不足，影像更难判读；俯卧位虽有一定帮助，但不能替代延迟摄片。", "tr": "“不显影”与“延迟显影”必须靠时间来鉴别，这是IVP的核心技术判断。若延迟片仍不显影，应建议改行其他检查（如逆行肾盂造影、超声或CT尿路成像），而不是在IVP上反复追加对比剂。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U08-0152", "t": "案例分析题", "s": "患者女性，48岁，因体检发现右侧输尿管中段可疑结石就诊，拟行静脉肾盂造影。检查当日患者按要求清洁肠道，无碘过敏史，肾功能正常。技师在完成造影前平片后为其静脉注射非离子型碘对比剂，注射约1分钟后患者出现全身荨麻疹、皮肤瘙痒，无喘息、无血压下降、意识清楚。作为在场技师，下列处理错误的是", "o": {"A": "立即停止注射，保留静脉通路，通知医师并密切观察生命体征", "B": "该表现属轻度急性不良反应，应就地观察至少30分钟，警惕向中重度反应进展", "C": "备好肾上腺素、糖皮质激素、抗组胺药、氧气与吸引装置等急救物品与设备", "D": "让患者自行离开检查室回病房观察，以便腾出机房继续下一位患者的检查", "E": "在患者症状缓解且经医师评估后，可择期改用其他检查方法（如超声或CT尿路成像）完成诊断"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-008", "kp": "造影中碘对比剂不良反应的处置", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】本题选错误项。D错误：让刚发生急性不良反应的患者独自离开检查室，等于脱离监护与急救条件，一旦在途中进展为喉头水肿、支气管痉挛或过敏性休克，后果严重；机房周转效率绝不能凌驾于患者安全之上。【为什么错】A正确：出现任何不良反应的第一步都是停止注射并保留静脉通路（后续给药需要），同时通知医师。B正确：单纯荨麻疹、瘙痒而无呼吸循环受累属轻度反应，但存在进展为中重度的可能，须现场留观。C正确：肾上腺素是严重过敏样反应的一线药物，连同糖皮质激素、抗组胺药、氧气与吸引装置均属造影室必备。E正确：本次检查中断后，可依据临床需要改用超声或CT尿路成像等替代方案完成诊断。", "tr": "轻度反应的关键不是“用什么药”，而是“不脱离监护”。同时注意留观时限：注射后30分钟内是急性反应高发期；此外应与迷走反射（心率减慢、血压下降）鉴别，后者处理原则不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0153", "t": "单选题", "s": "关于乳腺头尾位（CC位）摄影的操作要点，下列错误的是", "o": {"A": "抬高乳腺下缘至自然可提升的最高点，使探测器上缘平齐乳腺下皱襞抬起后的水平", "B": "压迫板自上而下压迫，X线自上向下投照", "C": "应尽量包全乳腺内侧组织，同时兼顾外侧，乳头应呈切线位显示于影像中央", "D": "为使外上象限深部组织完整显示，CC位应常规大幅外旋患者躯干并牺牲内侧组织", "E": "摆位时应展平皮肤皱褶，避免皱褶重叠形成伪影"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-001", "kp": "乳腺CC位摄影要点", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】本题选错误项。D错误：标准CC位以“不遗漏内侧组织”为优先原则，因为内侧组织在MLO位上最易被遗漏；若为显示外上象限或腋尾部深部组织，应另行加摄夸大头尾位（XCCL），而不是牺牲标准CC位的内侧包容度。【为什么错】A正确：把乳腺下缘提升到最高点并使探测器与之平齐，可最大限度纳入后部组织。B正确：CC位由上向下压迫、上下方向投照，是其定义。C正确：乳头呈切线（不与腺体重叠）是CC位合格的基本判据之一，同时应尽量显示胸大肌前缘。E正确：皮肤皱褶会形成线状伪影并可能掩盖病变。", "tr": "“标准位求全面、附加位补重点”是乳腺摄影的基本策略：CC位优先保内侧，XCCL补外侧腋尾，乳沟位（CV）补内侧深部。用附加位的目标去改造标准位，是常见的思路错误。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0154", "t": "多选题", "s": "关于乳腺内外斜位（MLO位）的角度选择与合格标准，下列正确的是", "o": {"A": "探测器（压迫方向）与水平面所成角度一般在30°~60°之间，需根据受检者体型调整，使其与胸大肌走行方向平行", "B": "体型高瘦、胸大肌较陡直者宜选用较大角度（接近60°），矮胖者宜选用较小角度（接近30°~45°）", "C": "合格的MLO位应显示胸大肌，且其下缘至少达到乳头后线（PNL）水平，胸大肌前缘呈凸出状", "D": "合格的MLO位应显示乳腺下皱襞（IMF）自然展开、乳头呈切线位，且无皮肤皱褶重叠", "E": "MLO位角度固定为45°，任何体型均不应调整"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-002", "kp": "MLO位角度与合格标准", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】A、B正确：MLO位的角度选择原则是让压迫方向与该受检者的胸大肌走行平行，这样才能把最多的后部与上部腺体纳入影像；瘦高者胸大肌陡直取大角度，矮胖者胸大肌平坦取小角度，故常规范围为30°~60°而非固定值。C正确：胸大肌显示至乳头后线水平且前缘凸出，是判定后部组织包含是否充分的核心指标。D正确：下皱襞展开说明下部组织未被折叠遗漏，乳头切线位说明未被腺体遮盖，无皮肤皱褶说明压迫与铺展到位。【为什么错】E错误：把角度固定为45°而不考虑体型，会导致胸大肌显示不足或腺体后缘遗漏，是典型的教条化错误。", "tr": "MLO位是全乳腺摄影中显示组织量最大的体位，其质量评价重点全在“后部与下部有没有包全”：看胸大肌是否达PNL、下皱襞是否展开。仅凭“图像清楚”判断合格是不够的。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U08-0155", "t": "多选题", "s": "关于乳腺X线摄影附加体位的适应证，下列匹配正确的是", "o": {"A": "局部加压点压位（spot compression）：用于鉴别标准位上可疑的“结构扭曲或肿块”是否为正常腺体重叠所致，通过局部加压使组织分离展开", "B": "放大位：常与点压联合使用，采用微焦点、不使用滤线栅，主要用于评价微钙化的形态、数目与分布", "C": "乳沟位（CV位）：双侧乳腺同时摆位，用于显示乳腺内侧深部（近胸壁内侧）病变", "D": "切线位（TAN）：用于确认可疑病变是否位于皮肤内或皮下，如皮肤钙化", "E": "上述附加体位信息量更大，可直接替代标准CC位与MLO位，从而减少摄影次数与剂量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-003", "kp": "乳腺附加体位的适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (2)乳腺附加体位", "ex": "【为什么对】A正确：点压把局部组织压得更薄更分散，若“病灶”随之消散则为腺体重叠所致，若持续存在则提示真实病变，是鉴别的关键手段。B正确：放大位需用0.1mm级微焦点以保证分辨力，并采用空气间隙技术而不用滤线栅以避免剂量过高，是评估微钙化的标准做法。C正确：乳沟位把双乳同时拉向探测器中央，专门解决内侧深部区域在常规位上易遗漏的问题。D正确：切线位让可疑钙化投影到皮肤轮廓线上，从而确认其位于皮肤而非腺体内，可避免不必要的活检。【为什么错】E错误：附加体位都是针对特定问题的“补充”，其覆盖范围有限（如XCCL牺牲内侧、点压仅局部、放大位仅小视野），无法提供全乳腺的整体信息，因而只能在标准CC位与MLO位基础上加做，绝不能替代标准位。", "tr": "附加体位的选择逻辑是“缺什么补什么”：位置显示不全用XCCL/CV，性质难定用点压，钙化细节用放大，皮肤定位用切线；但它们始终是标准两位的补充。放大位不用滤线栅这一点尤其容易记反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0156", "t": "单选题", "s": "乳腺X线摄影中使用压迫的目的，下列描述错误的是", "o": {"A": "减小乳腺厚度，降低所需曝光量与辐射剂量", "B": "使腺体组织展开分离，减少重叠对病变的掩盖", "C": "固定乳腺，减少运动模糊", "D": "减少散射线，提高影像对比度", "E": "增大物-片距，从而提高微钙化的空间分辨力"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-004", "kp": "乳腺压迫的作用", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】本题选错误项。E错误：压迫的效果恰恰是把乳腺压薄、使组织尽量贴近探测器，从而减小物-片距、降低几何模糊与放大；“增大物-片距”与压迫的物理效果相反。只有在专门的放大摄影中才刻意抬高乳腺、增大物-片距（空气间隙技术），且必须配合微焦点。【为什么错】A、B、C、D均为压迫的经典作用：厚度减小则透射增加、剂量下降；组织展开可减少重叠所致的假阴性与假阳性；固定可消除运动模糊；被照体积减小则散射线减少、对比度提高。", "tr": "压迫的四大作用（薄、散、稳、展）需与放大摄影的原理区分开：常规摄影靠“贴近探测器”求清晰，放大摄影靠“抬离探测器+微焦点”求放大，二者的物-片距策略完全相反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0157", "t": "单选题", "s": "某受检者MLO位影像显示乳腺下部组织折叠成角、下皱襞未展开，胸大肌下缘明显高于乳头后线水平。最可能的原因是", "o": {"A": "压迫板角度与受检者胸大肌走行不匹配，且摆位时未将乳腺充分上提外拉，导致后下部组织遗漏", "B": "曝光量不足", "C": "焦-片距过短", "D": "使用了微焦点", "E": "未使用滤线栅"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-005", "kp": "MLO位质量缺陷的原因分析", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】胸大肌下缘未达乳头后线、下皱襞未展开、下部组织折叠，这三条同时出现，指向的是同一类问题——摆位不当：角度未与该受检者胸大肌走行平行（常见于角度过大或过小），且未将乳腺充分向上向外提拉后再压迫，导致后下部腺体没有被纳入并在下缘堆叠成角。纠正办法是重新评估体型、调整机架角度，并在压迫过程中用手托住并上提乳腺、展平皱褶。【为什么错】B曝光不足表现为影像整体噪声大、腺体致密区穿透不足，不会改变胸大肌位置与组织折叠。C焦-片距在乳腺机上固定，且只影响放大与清晰度。D微焦点用于放大摄影，与组织包含范围无关。E乳腺摄影是否用滤线栅影响的是散射与对比度，同样不影响解剖包含。", "tr": "解决影像问题前先分类：“包含范围/结构关系”类缺陷几乎都源于摆位与角度；“密度/噪声/对比”类缺陷才考虑曝光参数与滤线栅。把摆位问题归因于曝光参数，会导致反复重拍并增加受检者剂量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U08-0158", "t": "多选题", "s": "关于乳腺导管造影，下列描述正确的是", "o": {"A": "主要适应证为病理性乳头溢液（血性或浆液性），用以显示导管内占位、扩张与走行", "B": "操作时先找到溢液导管开口，用钝头细针缓慢插入并注入少量水溶性碘对比剂（通常0.1~1.0ml左右）", "C": "注射后常规摄取头尾位与内外斜位，必要时加摄放大位以观察细小充盈缺损", "D": "注入量应以患者出现明显胀痛为限，量越大导管显示越完整", "E": "急性乳腺炎、乳头及乳晕区皮肤感染者不宜进行该检查"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-006", "kp": "乳腺导管造影技术", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (3)乳腺造影技术", "ex": "【为什么对】A正确：病理性乳头溢液是导管造影的核心适应证，可定位导管内乳头状瘤等病变。B正确：须使用钝头针以免刺破导管形成假道，注入量以少量为宜。C正确：造影后按标准CC与MLO位摄影，放大位有助于观察细小充盈缺损与导管壁不规则。E正确：局部急性炎症或感染时操作可致感染扩散，属禁忌。【为什么错】D错误：以“明显胀痛”为注入终点是危险且错误的——胀痛提示导管过度扩张甚至有破裂、对比剂外渗风险，正确做法是缓慢注入少量对比剂，出现胀感即停止。", "tr": "凡是把“患者疼痛”当作操作终点的选项，在造影类题目中基本都是错误项（HSG、逆行肾盂造影、导管造影同理）。此外要注意造影前不要过度挤压排空溢液，否则可能找不到溢液导管开口。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0159", "t": "单选题", "s": "口内根尖片分角线投照技术的原理是", "o": {"A": "中心线垂直于牙长轴与探测器（胶片）平面所构成夹角的角平分线，以使牙齿影像长度接近实际长度", "B": "中心线垂直于探测器平面，不考虑牙长轴方向", "C": "中心线平行于牙长轴射入", "D": "中心线垂直于牙长轴，探测器与牙长轴垂直放置", "E": "中心线与探测器成45°固定角射入，各牙位相同"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-DEN-001", "kp": "根尖片分角线投照技术原理", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】受口腔解剖（腭穹隆、口底）限制，探测器往往不能与牙长轴平行放置，二者之间形成一定夹角。分角线技术依据等腰三角形原理，令中心线垂直通过该夹角的角平分线，使投影所得牙影长度最接近牙的真实长度，从而减少影像的伸长或缩短。各牙位因牙长轴倾斜不同，垂直角需相应调整（上颌切牙约+40°，上颌磨牙约+20°，下颌切牙约-15°，下颌磨牙约-5°，具体依个体调整）。【为什么错】B不考虑牙长轴会造成影像明显伸长或缩短。C中心线平行于牙长轴则无法在探测器上成像。D是对分角线原理的错误改写，探测器与牙长轴垂直不符合口内放置的实际。E各牙位垂直角不同，固定45°必然造成失真。", "tr": "牢记失真规律：中心线垂直角过大（过于向牙长轴方向倾斜）导致影像缩短，垂直角过小导致影像伸长；水平角不当则造成邻面影像重叠。分角线法操作简便但失真难以完全避免，精确评价牙周骨水平应首选平行投照法。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0160", "t": "案例分析题", "s": "患者男性，45岁，慢性牙周炎，口腔科需精确评价下颌后牙区牙槽骨吸收水平并作治疗前后对比，要求影像失真最小、可重复性好。患者张口度正常、无明显咽反射。放射科可提供口内根尖片（分角线法与平行投照法均可）及全口牙位曲面体层片（全景片）。作为技师，下列判断错误的是", "o": {"A": "应首选平行投照法（长遮线筒法）：探测器借助持片器与牙长轴平行放置，中心线垂直于二者，影像失真最小、重复性好", "B": "平行投照法需加大焦-片距（约20~40cm）以补偿探测器与牙之间的距离所致的放大", "C": "分角线法虽操作简便、患者易配合，但因中心线成角与个体差异，影像易伸长或缩短，不利于精确测量牙槽骨高度", "D": "全景片可一次显示全口牙列与颌骨，适合总体观察与筛查，但存在放大率不均、颈椎影重叠与细节分辨力不足，不宜替代根尖片作精细测量", "E": "全景片各部位放大率恒定且细节分辨力高，测量牙槽骨吸收水平的精度优于口内根尖片，本例应直接选用全景片"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-DEN-002", "kp": "平行投照法、分角线法与全景片的选择", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】本题选错误项。E错误：全景片属曲面体层成像，不同深度层面的放大率并不恒定（水平方向与垂直方向放大率还常不一致），且存在颈椎与对侧颌骨的重叠伪影、空间分辨力低于口内片，因而不适合作牙槽骨高度的精确测量与治疗前后对比；本例应选平行投照法的根尖片。【为什么错】A正确：平行投照法用持片器把探测器固定在与牙长轴平行的位置，中心线垂直入射，牙冠-牙根比例与牙槽嵴高度还原度最好，是牙周评估与随访对比的首选。B正确：探测器远离牙面会带来放大，加大焦-片距（约20~40cm，配长遮线筒）使X线趋于平行，可有效抑制放大与半影。C正确：分角线法依赖角度估计，个体差异与操作者经验会造成影像伸长或缩短，测量可比性差。D正确：全景片可一次显示全口牙列与颌骨，适合总体观察与筛查。", "tr": "选择检查方法应回到临床目的：要“测量与对比”选平行投照法，要“整体筛查与颌骨全貌”选全景片，要“快速便捷、患者难配合”才退而求其次用分角线法。切勿因全景片信息量大就误认为其精度也最高。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-0161", "t": "多选题", "s": "关于口腔X线摄影的基本知识，下列说法正确的是", "o": {"A": "口内根尖片主要用于显示单个或数个牙的牙冠、牙根、根尖周组织及邻近牙槽骨", "B": "咬合片（𬌗翼片/咬合翼片）主要用于显示上下颌后牙的邻面龋与牙槽嵴顶", "C": "全口牙位曲面体层片（全景片）可一次显示上下颌骨、全口牙列及双侧颞下颌关节区", "D": "口腔摄影中应对受检者使用铅围裙（必要时含甲状腺屏蔽）进行防护", "E": "口内片的曝光时间以秒计，通常需要100mAs以上的曝光量"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-DEN-003", "kp": "口腔X线摄影的种类与防护", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】A正确：根尖片是口腔最常用的口内片，显示范围为少数牙及其根尖周与牙槽骨。B正确：咬合翼片重点显示上下后牙的牙冠邻面与牙槽嵴顶，是邻面龋与早期牙周骨吸收的敏感检查。C正确：全景片一次成像即可覆盖上下颌骨、全口牙列与双侧髁突区，适合整体评估。D正确：虽然口腔摄影单次剂量很低，但仍应遵循防护最优化，对受检者尤其儿童与孕妇使用铅围裙与甲状腺屏蔽。【为什么错】E错误：口内片属超低剂量摄影，管电流通常仅数毫安至十毫安级、曝光时间常为零点几秒，总曝光量远低于100mAs；把躯干摄影的曝光量套用到口内片是量级性错误。", "tr": "口腔摄影“剂量低”不等于“不需防护”，两者不可互相推导。另注意区分口内片的三种类型（根尖片、咬合翼片、𬌗片）与口外片（全景片、头影测量片）的适用范围。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-0162", "t": "多选题", "s": "关于乳腺X线摄影的设备与曝光技术，下列说法正确的是", "o": {"A": "乳腺X线管常采用钼、铑或钨靶配合相应滤过板，以获得适合乳腺软组织成像的低能X线束", "B": "乳腺摄影常规使用小焦点（约0.3mm），放大摄影时使用微焦点（约0.1mm）", "C": "自动曝光控制（AEC）可依据乳腺厚度与腺体密度自动确定曝光条件，是保证影像质量一致性的重要手段", "D": "放大摄影时采用空气间隙技术而不使用滤线栅，以避免剂量过度增加", "E": "乳腺摄影管电压通常设置在80~100kV，以增强穿透力"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-007", "kp": "乳腺摄影设备与曝光技术", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】A正确：乳腺内各软组织的原子序数与密度差异极小，只有低能（约17~25keV）准单能X线才能形成足够对比，故采用钼/铑/钨靶与匹配滤过板的组合。B正确：常规摄影用0.3mm级小焦点保证清晰度，放大摄影因几何模糊被放大，必须改用0.1mm级微焦点。C正确：AEC依据探测到的透过量自动终止曝光，可使不同厚度与密度的乳腺获得稳定一致的影像密度，减少重拍。D正确：放大摄影时乳腺被抬离探测器形成空气间隙，散射线大多不能到达探测器，此时再加滤线栅只会大幅增加剂量而收益有限。【为什么错】E错误：80~100kV是躯干摄影的范围；乳腺摄影管电压通常仅约25~35kV，过高的kV会使软组织对比度急剧下降，完全丧失乳腺成像的意义。", "tr": "乳腺摄影的所有参数都围绕“低能量、高对比、高分辨力”这一主线：低kV、小/微焦点、专用靶-滤过组合、压迫减薄。任何“提高kV增强穿透”的表述在乳腺场景中都是错误方向。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1001", "t": "单选题", "s": "关于X线摄影影像放大效应的叙述，错误的是", "o": {"A": "被检部位距探测器越远，影像放大越明显", "B": "被检部位应尽量贴近探测器", "C": "焦片距越大，放大越小", "D": "放大效应不影响影像的清晰度", "E": "缩小物片距可减少放大失真"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-001", "kp": "影像放大效应与物片距", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】放大效应会使影像边界模糊、空间分辨率下降，必然影响影像清晰度与锐利度，故D项“不影响清晰度”的说法错误，本题选D。\n【为什么错】A：物片距（被检部位至探测器距离）越大，几何放大越明显，正确。B：贴近探测器可缩小物片距而减少放大，正确。C：焦片距增大时放大率＝焦片距/（焦片距－物片距）趋近于1，放大减小，正确。E：缩小物片距即减少放大失真，正确。", "tr": "放大率取决于“物片距与焦片距的比例”，远距离摄影（如胸部180cm）与贴近探测器是减少放大的两个途径。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1002", "t": "单选题", "s": "胸部X线摄影通常采用远距离摄影，其焦片距（SID）一般为", "o": {"A": "75cm", "B": "90cm", "C": "100cm", "D": "150cm", "E": "180cm"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-002", "kp": "胸部远距离摄影焦片距", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】胸部正位为减小心脏等器官的放大失真，采用180cm远距离摄影（SID＝180cm），故E正确。\n【为什么错】A、B、C：75~100cm为四肢与躯干多数部位的常规焦片距。D：150cm非胸部常规标准。", "tr": "胸部180cm、四肢及普通部位100cm是经典数值考点，勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1003", "t": "单选题", "s": "X线摄影前去除被检部位金属饰物、膏药等异物的主要目的是", "o": {"A": "防止损坏X线机", "B": "避免高密度异物产生伪影而漏诊误诊", "C": "缩短曝光时间", "D": "降低患者辐射剂量", "E": "便于体表定位标记"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-003", "kp": "摄影前异物去除的目的", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】金属饰物、膏药中的金属粉末等高密度物在X线片上形成高密度伪影，可遮盖病灶或模拟病变导致漏诊误诊，故摄影前必须去除，B正确。\n【为什么错】A：异物不会损坏X线机。C：异物不影响曝光时间设定。D：去除异物与患者剂量无直接关系。E：去除异物与体表定位无关。", "tr": "关键词为“伪影”；含金属成分的衣物、饰物、膏药、创可贴等均须在摄影前去除。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1004", "t": "单选题", "s": "头颅后前位X线摄影时，中心线的入射点为", "o": {"A": "枕外隆凸", "B": "眉间", "C": "外耳孔", "D": "鼻尖", "E": "颏部"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-004", "kp": "头颅后前位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】头颅后前位中心线经枕外隆凸垂直射入探测器中心（射达眉间方向），使颅骨前后投影对称居中，故A正确。\n【为什么错】B：眉间是中心线射达的对应部位而非入射点。C：外耳孔是头颅侧位的定位标志。D、E与头颅后前位中心线无关。", "tr": "区分“入射点（枕外隆凸）”与“射出方向/对应部位（眉间）”；头颅侧位中心线才经外耳孔上方。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1005", "t": "单选题", "s": "头颅后前位摄影要求正中矢状面、听眦线均垂直探测器，其主要目的是", "o": {"A": "显示颅底结构", "B": "保持左右对称，避免颅骨倾斜变形", "C": "减小几何放大", "D": "使颞骨岩部投影于眼眶内", "E": "显示蝶鞍形态"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-005", "kp": "头颅正位体位标准的意义", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】正中矢状面垂直保证左右结构对称，听眦线垂直保证头颅不前后倾斜，两者共同使正位影像标准、失真最小，故B正确。\n【为什么错】A：显示颅底结构需汤氏位等特殊体位。C：减小放大多通过贴近探测器与远距离摄影。D：颞骨岩部投影于眼眶是梅氏位等特殊投照的表现。E：蝶鞍显示以头颅侧位为佳。", "tr": "“矢状面垂直”防左右倾斜，“听眦线垂直”防前后倾斜，是头颅正位两项核心要求。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1006", "t": "单选题", "s": "头颅侧位X线摄影时，中心线的入射点为", "o": {"A": "外耳孔上方约2.5cm（蝶鞍区）", "B": "眉间", "C": "枕外隆凸", "D": "鼻根", "E": "下颌角"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-006", "kp": "头颅侧位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】头颅侧位中心线经外耳孔上方约2.5cm（即蝶鞍区）垂直射入，可同时显示颅骨侧位全貌及蝶鞍，故A正确。\n【为什么错】B：眉间为头颅前后位中心线方向。C：枕外隆凸为头颅后前位入射点。D：鼻根为副鼻窦柯氏位定位标志。E：下颌角与头颅侧位中心线无关。", "tr": "头颅侧位中心线“外耳孔上2.5cm经蝶鞍”，是鞍区与颅骨侧位检查的固定考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1007", "t": "单选题", "s": "头颅汤氏位（Townes位）摄影时中心线的投照要求为", "o": {"A": "垂直射入", "B": "向头侧倾斜30°", "C": "向足侧倾斜30°", "D": "向足侧倾斜45°", "E": "向头侧倾斜15°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-007", "kp": "汤氏位中心线投照方向", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位患者仰卧、听眦线垂直探测器，中心线向足侧倾斜30°经枕外隆凸下方射入（射达眉间方向），使枕骨、枕骨大孔、颞骨岩部及内听道充分展开显示，故C正确。\n【为什么错】A：垂直射入为正位要求。B：向头侧倾斜为骶尾椎等体位的方向。D：45°倾斜为梅氏位等特点。E：15°倾斜为柯氏位等特点。", "tr": "汤氏位“向足侧倾斜30°”，方向是足侧而非头侧，易与骶尾椎（向头侧倾斜）混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1008", "t": "单选题", "s": "汤氏位（Townes位）主要显示的结构不包括", "o": {"A": "枕骨", "B": "枕骨大孔", "C": "颞骨岩部", "D": "内听道", "E": "蝶鞍"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-008", "kp": "汤氏位显示范围", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位用于观察枕骨、枕骨大孔、颞骨岩部及内听道等后颅窝结构，蝶鞍位于颅底中央前部，常规以头颅侧位显示，故E为本题答案。\n【为什么错】A、B、C、D均为汤氏位重点显示结构，叙述正确。", "tr": "“汤氏位＝后颅窝（枕骨、枕骨大孔、岩部、内听道）”，蝶鞍是侧位和鞍区检查的重点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1009", "t": "单选题", "s": "副鼻窦柯氏位（Caldwell位）主要显示的窦腔是", "o": {"A": "上颌窦", "B": "额窦及筛窦", "C": "蝶窦", "D": "后组筛窦", "E": "乳突气房"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-009", "kp": "柯氏位显示范围", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】柯氏位（鼻额位）患者前额及鼻尖贴近探测器、听眦线垂直，中心线向足侧倾斜15°~20°经鼻根射入，主要显示额窦、筛窦及眼眶，故B正确。\n【为什么错】A：上颌窦由瓦氏位（顶颏位）显示。C：蝶窦需用头颅侧位等专用体位。D：后组筛窦显示仍需结合其他体位。E：乳突气房属乳突摄影范畴。", "tr": "“额窦筛窦看柯氏位、上颌窦看瓦氏位”，是副鼻窦摄影的高频鉴别考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1010", "t": "单选题", "s": "副鼻窦瓦氏位（Water位/顶颏位）摄影时，听眦线与探测器平面的夹角为", "o": {"A": "15°", "B": "23°", "C": "37°", "D": "45°", "E": "90°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-010", "kp": "瓦氏位听眦线角度", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】瓦氏位（顶颏位）患者颏部贴探测器、头部后仰，使听眦线与探测器平面成37°角，中心线经鼻尖（或鼻尖与上唇间）垂直射入，主要显示上颌窦，故C正确。\n【为什么错】A、B：15°~20°为柯氏位倾斜范围。D：45°为腰椎斜位等体位特点。E：90°即垂直，为常规正位体位。", "tr": "瓦氏位听眦线“37°”是标志性数值，与柯氏位15°~20°倾斜方向不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1011", "t": "单选题", "s": "胸部后前位X线摄影时，中心线的入射点为", "o": {"A": "第4胸椎", "B": "第6胸椎", "C": "第7胸椎", "D": "胸骨角", "E": "第2胸椎"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-011", "kp": "胸部后前位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸部后前位中心线经第6胸椎垂直射入探测器中心（约平两侧肩胛下角连线水平），故B正确。\n【为什么错】A：第4胸椎约平胸骨角。C：第7胸椎为胸椎正位中心线常用水平。D：胸骨角为胸部前弓位中心线定位标志。E：第2胸椎位于上纵隔上方。", "tr": "胸部后前位中心线“经第6胸椎”是固定数值考点，正、侧位均在第6胸椎水平。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1012", "t": "单选题", "s": "胸部后前位摄影时嘱患者双手背置于髋部、肘部内旋，其主要目的是", "o": {"A": "减少胸部呼吸运动", "B": "使肩胛骨向外展开，不与肺野重叠", "C": "增加胸腔前后径", "D": "使锁骨抬高", "E": "便于探测器定位"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-012", "kp": "胸部后前位双上肢摆位目的", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】双手背置髋部并肘部内旋，使肩胛骨向外、向前移开，避免肩胛骨投影与肺野重叠，保证肺野充分显示，故B正确。\n【为什么错】A：减少呼吸运动靠深吸气后屏气。C：双手姿势不改变胸腔前后径。D：锁骨抬高是前弓位的作用。E：与探测器定位无关。", "tr": "“手背置髋、肘内旋、肩胛骨外展”是胸部正位标准摆位，肩胛骨重叠是常见质量缺陷。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1013", "t": "单选题", "s": "胸部侧位X线摄影时，中心线的入射点为", "o": {"A": "第6胸椎高度的腋中线", "B": "第4胸椎高度的腋前线", "C": "第7胸椎高度的腋后线", "D": "胸骨角水平", "E": "剑突水平"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-013", "kp": "胸部侧位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸部侧位患者患侧贴近探测器、两臂上举，中心线经第6胸椎高度的腋中线水平射入，故A正确。\n【为什么错】B：腋前线偏前，不能使两肺及纵隔居中。C：腋后线偏后。D：胸骨角平第4胸椎，非侧位中心线。E：剑突水平偏低，会使心尖及膈肌显示不全。", "tr": "胸部正侧位中心线均经“第6胸椎”水平，侧位为水平投照经腋中线。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1014", "t": "单选题", "s": "临床怀疑肺尖部或锁骨下区病变（如肺尖结核、Pancoast瘤）时，宜选用的胸部特殊体位是", "o": {"A": "胸部侧位", "B": "胸部前弓位（前凸位）", "C": "右前斜位", "D": "标准后前位", "E": "左前斜位"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-014", "kp": "胸部前弓位适应证", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】前弓位（前凸位）患者身体后仰、肩背部贴近探测器，使锁骨投影上移、肺尖部展开，可更充分显示肺尖及锁骨下区病变，故B正确。\n【为什么错】A：侧位用于定位及纵隔观察。C、E：斜位用于心脏大血管观察。D：标准后前位锁骨与肺尖重叠较多，肺尖显示受限。", "tr": "前弓位＝“后仰、锁骨头抬高”，专用于肺尖及锁骨下区；标准后前位肺尖常被锁骨遮挡。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1015", "t": "单选题", "s": "胸部正位采用180cm焦片距远距离摄影的主要目的是", "o": {"A": "增大X线输出量", "B": "减小心脏等器官的放大失真", "C": "提高影像对比度", "D": "缩短曝光时间", "E": "减少散射线产生"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-015", "kp": "胸部远距离摄影意义", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】心脏位于胸腔前半部、距探测器较远，放大明显；采用180cm远距离摄影使心影放大率减小，心影大小更接近真实，便于心影测量与比较，故B正确。\n【为什么错】A：远距离摄影不增加X线输出量。C：对比度主要取决于kVp与散射线控制。D：焦片距增大需增加曝光条件而非缩短时间。E：散射线减少不是远距离摄影的主要目的。", "tr": "“远距离摄影减小放大”是核心；剂量、对比度非其主要调控目标。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1016", "t": "单选题", "s": "腹部仰卧前后位（泌尿系平片KUB）X线摄影时，中心线的入射点为", "o": {"A": "剑突与耻骨联合连线中点", "B": "脐上3cm", "C": "剑突", "D": "耻骨联合上缘", "E": "脐下3cm"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-016", "kp": "腹部平片中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】腹部仰卧前后位中心线经剑突与耻骨联合连线中点（约脐水平）垂直射入，可较完整显示双肾、输尿管及膀胱区域，故A正确。\n【为什么错】B：脐上3cm为腰椎正位中心线。C：剑突水平偏上。D：耻骨联合上缘为骨盆正位中心线。E：脐下3cm偏低。", "tr": "腹部平片“剑突－耻骨联合连线中点”，腰椎正位“脐上3cm”，二者勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1017", "t": "单选题", "s": "临床疑消化道穿孔，为观察膈下游离气体，首选的X线摄影是", "o": {"A": "腹部仰卧前后位", "B": "立位（半坐位）腹部平片", "C": "腹部侧位", "D": "腹部斜位", "E": "腹部俯卧后前位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-017", "kp": "立位腹部平片适应证", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】游离气体比重小、随体位上升，立位或半坐位水平投照时气体集聚于膈下肝顶与膈肌之间，呈新月形透亮影，故B正确。\n【为什么错】A：仰卧位气体聚于前腹壁下，与肠腔气体混杂难以分辨。C、D：侧位、斜位非游离气体首选。E：俯卧位更不利于游离气体显示。", "tr": "“膈下游离气体必用立位/半坐位水平投照”，卧位平片极易漏诊。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1018", "t": "单选题", "s": "腰椎正位（前后位）X线摄影时，中心线的入射点为", "o": {"A": "脐上3cm（约第3腰椎）", "B": "脐", "C": "两侧髂嵴连线中点", "D": "耻骨联合上缘", "E": "剑突"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-018", "kp": "腰椎正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎正位中心线经脐上3cm（约平第3腰椎）垂直射入，使上至T12、下至骶椎的腰椎序列居中显示，故A正确。\n【为什么错】B：脐水平略偏低。C：髂嵴连线平第4腰椎。D：耻骨联合上缘为骨盆正位中心线。E：剑突过高。", "tr": "“腰椎正位中心线脐上3cm”是高频数值，需与腹部平片（剑突－耻骨联合中点）区别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1019", "t": "单选题", "s": "关于腰椎正位摄影的体位与准备，错误的是", "o": {"A": "患者仰卧，正中矢状面垂直摄影台面", "B": "两髋、膝关节屈曲，使腰椎贴近台面", "C": "中心线经脐上3cm垂直射入", "D": "嘱患者屏气后曝光", "E": "中心线向头侧倾斜15°射入"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-019", "kp": "腰椎正位摄影要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎正位中心线应垂直射入，向头侧倾斜15°是骶尾椎正位的投照要求，故E错误，本题选E。\n【为什么错】A：仰卧并保持矢状面垂直保证左右对称，正确。B：髋膝屈曲使腰椎生理前凸变直、贴近台面，正确。C：中心线经脐上3cm，正确。D：屏气防止呼吸运动模糊，正确。", "tr": "腰椎正位“垂直”，倾斜投照的是骶尾椎正位（头侧倾斜15°~20°）与腰椎斜位（体位旋转45°）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1020", "t": "单选题", "s": "腰椎斜位（前斜位约45°）X线摄影主要显示的结构是", "o": {"A": "椎体前缘", "B": "椎弓峡部", "C": "椎间孔", "D": "棘突", "E": "横突"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-020", "kp": "腰椎斜位显示结构", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎斜位使椎体旋转约45°，椎弓峡部投影展开呈“狗形”（狗眼＝椎弓根，狗颈＝峡部），用于诊断椎弓峡部裂及腰椎滑脱，故B正确。\n【为什么错】A：椎体前缘正位及侧位即可观察。C：椎间孔以颈椎斜位显示为主。D：棘突在正位上显示。E：横突正位显示。", "tr": "“狗颈即峡部”，峡部断裂时狗颈中断，是腰椎滑脱的关键征象。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1021", "t": "单选题", "s": "寰枢椎张口位（开口位）X线摄影时，中心线的入射点为", "o": {"A": "上颌中切牙与枕外隆凸连线中点（经口腔）", "B": "甲状软骨", "C": "下颌角", "D": "舌骨", "E": "口角"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-021", "kp": "寰枢椎张口位中心线", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】张口位患者仰卧尽量张口，中心线经口腔（上颌中切牙与枕外隆凸连线中点）垂直射入，使上下颌骨投影分开、寰枢椎清晰显示，故A正确。\n【为什么错】B：甲状软骨为颈椎正侧位的定位标志。C、D、E均非张口位中心线定位点。", "tr": "张口位中心线必须“经口腔垂直射入”；患者未真正张口则寰枢椎被上下颌骨遮挡。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1022", "t": "单选题", "s": "骨盆正位X线摄影时，中心线的入射点为", "o": {"A": "两侧髂前上棘连线中点与耻骨联合上缘连线中点（约耻骨联合上缘）", "B": "脐", "C": "髋臼中心", "D": "尾骨", "E": "髂嵴"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-022", "kp": "骨盆正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】骨盆正位中心线经两侧髂前上棘连线中点与耻骨联合上缘连线的中点（约耻骨联合上缘）垂直射入，使双侧髋骨、股骨颈及骶尾椎对称显示，故A正确。\n【为什么错】B：脐为腰椎正位邻近区域。C：髋臼中心偏上。D：尾骨仅为定位参考。E：髂嵴过高。", "tr": "骨盆正位中心线“约耻骨联合上缘”，同时要求两足内旋约15°使股骨颈充分展开。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1023", "t": "单选题", "s": "骶尾椎正位X线摄影时，中心线的投照要求为", "o": {"A": "垂直射入", "B": "向头侧倾斜15°~20°，经耻骨联合上缘射入", "C": "向足侧倾斜15°~20°，经耻骨联合射入", "D": "向头侧倾斜30°", "E": "向足侧倾斜45°"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-023", "kp": "骶尾椎正位中心线投照", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】骶尾椎正位中心线向头侧倾斜15°~20°，经耻骨联合上缘射入，使骶尾椎投影上移展开、避免与耻骨重叠，故B正确。\n【为什么错】A：垂直射入会使骶尾椎与耻骨重叠、影像缩短。C：方向相反。D、E：角度及方向均不符。", "tr": "骶尾椎正位“向头侧倾斜”与汤氏位“向足侧倾斜30°”方向相反，是经典易混点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1024", "t": "单选题", "s": "手正位X线摄影时，中心线的入射点为", "o": {"A": "第三掌骨头", "B": "腕关节", "C": "第一掌骨基底部", "D": "中指末节", "E": "第二指间关节"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-024", "kp": "手正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】手正位中心线经第三掌骨头垂直射入，使全手及腕关节影像居中对称，故A正确。\n【为什么错】B：腕关节正位才经尺桡骨茎突连线中点。C：第一掌骨基底部偏桡侧。D：中指末节过远。E：第二指间关节偏内。", "tr": "手正位中心线“第三掌骨头”；腕关节正位是“尺桡骨茎突连线中点”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1025", "t": "单选题", "s": "腕关节正位X线摄影时，中心线的入射点为", "o": {"A": "尺桡骨茎突连线中点", "B": "第三掌骨头", "C": "舟骨", "D": "桡骨远端", "E": "月骨"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-025", "kp": "腕关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】腕关节正位中心线经尺桡骨茎突连线中点垂直射入，即腕关节间隙中心，可清晰显示腕骨及桡尺关节，故A正确。\n【为什么错】B：第三掌骨头为手正位中心线。C：舟骨为局部结构，非中心线定位点。D、E：桡骨远端、月骨均为部分结构。", "tr": "腕关节正位中心线“茎突连线中点”；疑舟骨骨折需加照尺偏位（舟骨位）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1026", "t": "单选题", "s": "疑腕舟骨骨折时，采用尺偏位（舟骨位）摄影，中心线的投照要求为", "o": {"A": "垂直射入舟骨", "B": "经桡骨茎突向尺侧倾斜约20°射入", "C": "向桡侧倾斜20°射入", "D": "向头侧倾斜45°", "E": "向足侧倾斜30°"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-026", "kp": "舟骨位中心线投照", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】舟骨位（尺偏位）腕关节向尺侧偏转使舟骨长轴展开，中心线经桡骨茎突向尺侧倾斜约20°投照，避免舟骨与邻近腕骨重叠，故B正确。\n【为什么错】A：垂直投照舟骨仍与邻近腕骨重叠。C：方向与尺偏位相反。D、E：角度方向均不符合。", "tr": "舟骨是腕部最易骨折的腕骨，正位易漏诊，“尺偏＋向尺侧倾斜20°”是标准补充体位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1027", "t": "单选题", "s": "肘关节正位X线摄影时，中心线的入射点为", "o": {"A": "肱骨内、外上髁连线中点", "B": "尺骨鹰嘴", "C": "桡骨头", "D": "肘窝上3cm", "E": "肱骨外上髁"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-027", "kp": "肘关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】肘关节正位中心线经肱骨内、外上髁连线中点（肘关节间隙）垂直射入，故A正确。\n【为什么错】B：尺骨鹰嘴偏后。C：桡骨头仅为关节外侧结构。D、E：均非正位标准定位点。", "tr": "肘关节正位中心线“内外上髁连线中点”，侧位中心线经肱骨外上髁。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1028", "t": "单选题", "s": "肩关节正位（前后位）X线摄影时，中心线的入射点为", "o": {"A": "喙突", "B": "肱骨外科颈", "C": "肩峰", "D": "锁骨中点", "E": "肩胛冈"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-028", "kp": "肩关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】肩关节正位中心线经喙突垂直射入，使肱骨头、关节盂及肩锁关节显示清晰，故A正确。\n【为什么错】B：肱骨外科颈为常见骨折部位而非定位点。C：肩峰为肩锁关节组成。D：锁骨中点偏内。E：肩胛冈为背部骨性标志。", "tr": "“喙突”是肩关节正位的核心定位标志；疑肩锁关节分离需加照双肩负重位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1029", "t": "单选题", "s": "膝关节正位X线摄影时，中心线的入射点为", "o": {"A": "髌骨下缘（股胫关节线）", "B": "髌骨上缘", "C": "髌骨中点", "D": "腓骨小头", "E": "胫骨结节"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-029", "kp": "膝关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】膝关节正位中心线经髌骨下缘（股骨与胫骨关节线）垂直射入，使股胫关节间隙充分显示，故A正确。\n【为什么错】B：髌骨上缘偏高。C：髌骨中点偏上。D：腓骨小头为外侧骨性标志。E：胫骨结节偏下。", "tr": "膝关节正位中心线“髌骨下缘（关节线）”，注意与髌骨轴位（经髌股间隙）区别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1030", "t": "单选题", "s": "踝关节正位X线摄影时，中心线的入射点为", "o": {"A": "内、外踝连线中点", "B": "内踝", "C": "外踝", "D": "跟骨", "E": "胫骨下端"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-030", "kp": "踝关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】踝关节正位中心线经内、外踝连线中点（胫距关节间隙）垂直射入，故A正确。\n【为什么错】B、C：内踝或外踝单侧定位会使关节偏斜。D：跟骨为足部结构。E：胫骨下端定位不准。", "tr": "踝正位中心线“内外踝连线中点”，踝侧位中心线经内踝。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1031", "t": "单选题", "s": "静脉肾盂造影（IVP）静脉注射对比剂后，常规摄片的时间点为", "o": {"A": "立即、5分钟、10分钟", "B": "7分钟、15分钟、30分钟", "C": "30分钟、60分钟", "D": "15分钟、45分钟", "E": "5分钟、30分钟、60分钟"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-031", "kp": "IVP摄片时间点", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】IVP注药后7分钟肾盏肾盂开始充盈显影，15、30分钟摄片观察充盈及排泄情况，解除腹部加压后再摄全尿路片，故B正确。\n【为什么错】A：5分钟内肾实质尚未充分显影。C、D、E：时间点与常规不符。", "tr": "IVP摄片时间“7、15、30分钟”为固定考点；解除加压后的全尿路片不可遗漏。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1032", "t": "单选题", "s": "下列不属于静脉肾盂造影禁忌证的是", "o": {"A": "碘对比剂过敏", "B": "严重肾功能不全（尿毒症无尿）", "C": "多发性骨髓瘤", "D": "妊娠", "E": "单纯性肾囊肿（对碘剂不过敏、肾功能正常）"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-032", "kp": "IVP禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】单纯性肾囊肿不影响对比剂排泄，不属IVP禁忌，故E正确。\n【为什么错】A：碘过敏可致严重不良反应，禁忌。B：无尿时对比剂无法排泄、加重肾损伤，禁忌。C：多发性骨髓瘤患者用碘对比剂易诱发急性肾功能衰竭，禁忌。D：妊娠为IVP禁忌。", "tr": "“多发性骨髓瘤禁用碘对比剂”与“无尿肾衰禁忌IVP”都是高频考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1033", "t": "单选题", "s": "关于静脉肾盂造影腹部加压的目的与部位，正确的是", "o": {"A": "压迫肾区使肾实质显影", "B": "加压球囊置于髂前上棘连线水平、向骶骨两侧压迫输尿管，使肾盂肾盏充盈", "C": "压迫膀胱使对比剂回流", "D": "压迫下腹部减少散射线", "E": "压迫腹主动脉减慢血流"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-033", "kp": "IVP腹部加压技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】加压球囊置于两侧髂前上棘连线水平、向中线骶骨两侧压迫两侧输尿管，延缓对比剂下行，使肾盂肾盏充分充盈，故B正确。\n【为什么错】A：加压对象是输尿管而非肾区。C：膀胱不回流。D：加压目的不是减少散射线。E：腹主动脉在椎体前方，不能也不应直接压迫。", "tr": "加压部位是“输尿管走行区”；腹主动脉瘤、新近腹部手术等禁忌加压。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1034", "t": "单选题", "s": "关于逆行肾盂造影，正确的是", "o": {"A": "适用于肾功能严重受损、IVP不显影者", "B": "无需严格消毒", "C": "可用于碘对比剂过敏者", "D": "无需借助膀胱镜", "E": "对比剂用量较IVP更大"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-034", "kp": "逆行肾盂造影特点", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】逆行肾盂造影经膀胱镜将导管插入输尿管直接注入少量对比剂，不经肾脏排泄，适用于肾功能严重受损、IVP不显影或需明确梗阻部位者，故A正确。\n【为什么错】B：属有创操作，必须严格消毒。C：碘过敏者仍禁用含碘对比剂。D：必须借助膀胱镜插管。E：逆行造影对比剂用量小（数毫升）。", "tr": "逆行造影“不经肾脏排泄”是其最大优点，但为有创检查，禁用于严重血尿与急性泌尿系感染。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1035", "t": "单选题", "s": "子宫输卵管造影（HSG）最适宜的检查时间是", "o": {"A": "月经期", "B": "月经干净后3～7天", "C": "排卵期", "D": "月经来潮前1周", "E": "任意时间"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-035", "kp": "HSG检查时间选择", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】HSG应选月经干净后3～7天（卵泡期），此时子宫内膜薄、无经血，且能排除早期妊娠及宫腔感染可能，故B正确。\n【为什么错】A：月经期宫腔有创面，易感染且影响观察。C：排卵后期子宫内膜增厚影响判断。D：接近月经期宫腔环境不宜。E：非任意时间。", "tr": "“月经净后3～7天”与乳腺检查“月经净后1周”是两类不同检查的时机考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1036", "t": "单选题", "s": "下列属于子宫输卵管造影禁忌证的是", "o": {"A": "不孕症", "B": "怀疑输卵管梗阻", "C": "急性生殖道炎症", "D": "子宫畸形", "E": "习惯性流产"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-036", "kp": "HSG禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】急性生殖道（盆腔）炎症时宫腔操作可使感染扩散，属于HSG禁忌证，故C正确。\n【为什么错】A、B、D、E均为HSG适应证：不孕症、查找输卵管梗阻部位、诊断子宫畸形、习惯性流产病因检查。", "tr": "HSG禁忌证为“月经期、急性生殖道炎症、妊娠、碘过敏”，均为高频考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1037", "t": "单选题", "s": "以碘化油行子宫输卵管造影后需加摄24小时延迟片，其原因是", "o": {"A": "观察对比剂被组织吸收的程度", "B": "碘化油黏稠、吸收缓慢，24小时后观察输卵管伞端弥散及盆腔分布情况", "C": "观察子宫收缩状态", "D": "减少患者辐射剂量", "E": "观察输卵管痉挛是否解除"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-037", "kp": "HSG碘化油延迟片", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】碘化油黏稠度高、吸收缓慢，注药24小时后复查摄片观察对比剂自输卵管伞端弥散入盆腔的情况，用于判断输卵管通畅性，故B正确。\n【为什么错】A：观察目的是弥散分布而非被吸收。C：子宫收缩状态非延迟片目的。D：加摄延迟片不减少剂量。E：输卵管痉挛与延迟片无关。", "tr": "油剂（碘化油）“24小时延迟片”；水溶性碘剂吸收快，无需24小时复查。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1038", "t": "单选题", "s": "乳腺X线摄影的常规投照体位是", "o": {"A": "内外斜位（MLO）＋头尾位（CC）", "B": "双侧侧位", "C": "放大摄影＋点压位", "D": "乳沟位＋腋尾位", "E": "切线位＋侧位"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-038", "kp": "乳腺常规摄影体位", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】乳腺常规摄影为内外斜位（MLO）与头尾位（CC）两个基本体位，分别从斜向和上下方向显示乳腺，故A正确。\n【为什么错】B、C、D、E均属补充或附加体位，不能替代常规体位。", "tr": "“CC＋MLO”是乳腺摄影标配；MLO显示组织量最多，CC显示内、外侧。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1039", "t": "单选题", "s": "关于乳腺内外斜位（MLO）摄影，正确的是", "o": {"A": "X线束自上而下垂直投照", "B": "X线束自内上向外下约45°投照，显示乳腺组织量最多并含腋尾", "C": "主要用于显示乳腺内侧", "D": "无需压迫乳腺", "E": "中心线经乳头垂直射入"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-039", "kp": "MLO位投照特点", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】MLO位球管自内上向外下约45°投照，乳腺及胸大肌、腋尾部分尽量包括在胶片内，显示乳腺组织量最多，故B正确。\n【为什么错】A：垂直上下投照是CC位。C：CC位显示乳腺内、外侧。D：MLO位同样需充分压迫。E：中心线经乳头为传统定位说法，非投照本质。", "tr": "MLO斜45°显示乳腺最多组织；CC位垂直投照，二者投照方向是鉴别考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1040", "t": "单选题", "s": "乳腺X线摄影时充分压迫乳腺的主要目的不包括", "o": {"A": "减小乳腺厚度、降低辐射剂量", "B": "减少散射线、提高对比度", "C": "固定乳腺、减少运动模糊", "D": "增加乳腺影像的放大率", "E": "使乳腺组织均匀分布、减少结构重叠"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-040", "kp": "乳腺摄影压迫的目的", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】压迫使乳腺变薄贴近探测器，物片距减小，放大率随之减小而非增加，故D错误，本题选D。\n【为什么错】A：厚度减小使所需剂量降低，正确。B：厚度减小散射线减少、对比度提高，正确。C：压迫固定乳腺防止运动模糊，正确。E：压迫使组织摊平、密度均匀，正确。", "tr": "压迫“减小”放大而非增加放大，方向判断是本题陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1041", "t": "单选题", "s": "乳腺X线摄影发现簇状微钙化，为进一步观察钙化的形态、数目与分布，应首选", "o": {"A": "放大摄影（1.5～2倍局部放大）", "B": "双侧侧位", "C": "乳沟位", "D": "切线位", "E": "腋尾位"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-041", "kp": "乳腺放大摄影适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (2)乳腺附加体位", "ex": "【为什么对】放大摄影通过加大投照放大倍数（1.5~2倍）清晰显示微钙化的形态、数目和分布，对鉴别良恶性钙化至关重要，故A正确。\n【为什么错】B：侧位用于病灶定位。C：乳沟位显示乳腺内侧深部。D：切线位用于皮肤及表浅病变。E：腋尾位显示腋尾部乳腺。", "tr": "“微钙化定性→放大摄影”，“肿块定位→点压位”，二者分工不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1042", "t": "单选题", "s": "乳腺导管造影（ductography）的主要适应证是", "o": {"A": "可触及的乳腺肿块", "B": "乳头溢液（尤其单孔血性溢液）", "C": "乳腺增生", "D": "腋窝淋巴结肿大", "E": "乳腺皮肤红肿"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-042", "kp": "乳腺导管造影适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (3)乳腺造影技术", "ex": "【为什么对】乳腺导管造影用于乳头溢液，尤其单孔血性溢液，可显示导管内病变（导管内乳头状瘤、导管扩张等），故B正确。\n【为什么错】A：肿块首选常规乳腺摄影及超声。C：乳腺增生为临床诊断范畴。D：腋窝淋巴结肿大与导管造影无关。E：皮肤红肿多为炎症，属禁忌范畴。", "tr": "“乳头溢液＝导管造影指征”，血性溢液警惕导管内乳头状瘤。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1043", "t": "单选题", "s": "根尖片平行投照（长锥体平行技术）的特点是", "o": {"A": "胶片与牙长轴平行、中心线垂直牙长轴射入", "B": "中心线垂直牙长轴与胶片夹角的角平分线", "C": "胶片远离牙体", "D": "中心线向足侧倾斜15°固定角度", "E": "仅适用于上颌磨牙"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-043", "kp": "根尖片平行投照技术", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】平行投照使胶片与牙体长轴平行，X线中心线垂直牙长轴射入，影像失真最小、牙体长度接近真实，故A正确。\n【为什么错】B：垂直角平分线是分角线投照技术。C：平行投照要求胶片贴近牙体。D：固定倾斜角度属于分角线投照的简化方式。E：平行投照适用于多数牙位，非仅上颌磨牙。", "tr": "“平行投照＝平行＋垂直＝失真小”；“分角线投照＝中心线垂直角平分线”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1044", "t": "单选题", "s": "能一次显示全口牙列、上下颌骨及颞下颌关节的X线摄影技术是", "o": {"A": "根尖片", "B": "咬合片", "C": "曲面断层（全景片）", "D": "咬翼片", "E": "头颅后前位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-044", "kp": "曲面断层检查范围", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】曲面断层（全景摄影）利用X线管与探测器同步反向旋转，一次曝光即显示全口牙列、双侧上下颌骨及颞下颌关节，故C正确。\n【为什么错】A、B、D：均为口内局部片，显示范围局限。E：头颅后前位显示颅骨而非牙列全景。", "tr": "曲面断层＝全口整体观，常用于牙周病、阻生智齿、颌骨病变普查；根尖片为局部精细显示。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1045", "t": "单选题", "s": "关于乳腺X线检查时机及准备，正确的是", "o": {"A": "月经期检查最佳", "B": "月经干净后1周左右检查最佳", "C": "排卵期检查最佳", "D": "检查前无需去除体表粉末", "E": "绝经后女性无需考虑任何准备"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-045", "kp": "乳腺摄影检查时机", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】月经干净后约1周乳腺腺体充血最少、致密程度相对降低且触痛轻，图像质量好、患者舒适，故B正确。\n【为什么错】A：月经期乳腺充血致密，图像质量差。C：排卵期腺体充血水肿。D：爽身粉、乳膏含金属粉末，必须去除以防伪影。E：绝经后虽无月经周期，仍须去除体表异物并规范摆位。", "tr": "乳腺检查“月经净后1周”与HSG“月经净后3~7天”时机相近但概念不同；体表粉末是常见伪影来源。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1046", "t": "多选题", "s": "头颅后前位X线摄影的体位要求包括", "o": {"A": "正中矢状面垂直探测器", "B": "听眦线垂直探测器", "C": "前额及鼻尖贴近探测器", "D": "中心线经枕外隆凸垂直射入", "E": "中心线向足侧倾斜30°射入"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-046", "kp": "头颅后前位体位要求", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A：矢状面垂直保证左右对称。B：听眦线垂直保证前后无倾斜。C：前额鼻尖贴探测器使颅骨贴近胶片减少放大。D：中心线经枕外隆凸垂直射入，为标准投照。\n【为什么错】E：向足侧倾斜30°是汤氏位的投照要求，头颅后前位中心线垂直射入。", "tr": "头颅后前位“垂直投照、经枕外隆凸”；倾斜30°属于汤氏位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1047", "t": "多选题", "s": "汤氏位（Townes位）可显示的结构包括", "o": {"A": "枕骨", "B": "枕骨大孔", "C": "颞骨岩部", "D": "内听道", "E": "蝶鞍"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-047", "kp": "汤氏位显示结构", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A：枕骨为汤氏位主要显示结构。B：枕骨大孔在后前斜向投影下充分显示。C：颞骨岩部在汤氏位上展开投影。D：内听道随岩部显示清晰。\n【为什么错】E：蝶鞍位于颅底中央，以头颅侧位显示为佳，汤氏位对蝶鞍显示无优势。", "tr": "汤氏位＝后颅窝三件套（枕骨、枕骨大孔、岩部内听道）；蝶鞍归侧位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1048", "t": "多选题", "s": "胸部后前位X线摄影的技术要点包括", "o": {"A": "前胸壁贴近探测器", "B": "双手背置于髋部、肘部内旋", "C": "中心线经第6胸椎垂直射入", "D": "焦片距180cm，深吸气后屏气曝光", "E": "患者背部贴近探测器、双臂下垂"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-048", "kp": "胸部后前位技术要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A：前胸壁贴近探测器减少放大、肩胛骨外移。B：双手背置髋、肘内旋使肩胛骨移开肺野。C：中心线经第6胸椎垂直射入。D：180cm远距离摄影减小心脏放大，深吸气后屏气减少运动模糊。\n【为什么错】E：后前位应前胸壁贴探测器，背部贴近且双臂下垂会使肩胛骨与肺野重叠。", "tr": "“后前位前胸贴板、侧位患侧贴板”，双臂姿势不当是胸部正位常见摆位错误。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1049", "t": "多选题", "s": "腹部平片（KUB）摄影前的准备包括", "o": {"A": "清洁肠道（必要时清洁灌肠）", "B": "排空膀胱", "C": "去除腹部金属饰物及膏药", "D": "训练屏气配合", "E": "严格禁食禁水8小时以上"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-049", "kp": "腹部平片摄影准备", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】A：清洁肠道减少粪气影干扰。B：排空膀胱便于观察泌尿系结石及盆腔。C：去除高密度异物避免伪影。D：屏气配合防止运动模糊。\n【为什么错】E：腹部平片一般无需严格禁食禁水；严格禁食并清洁灌肠是IVP等造影检查的术前准备。", "tr": "KUB重点是“清肠、排尿、去异物、屏气”；严格禁食水属于造影准备范畴。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1050", "t": "多选题", "s": "腰椎正位X线摄影的技术要点包括", "o": {"A": "仰卧，正中矢状面垂直摄影台面", "B": "两髋、膝屈曲使腰椎贴近台面", "C": "中心线经脐上3cm垂直射入", "D": "屏气曝光", "E": "中心线向头侧倾斜15°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-050", "kp": "腰椎正位技术要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A：矢状面垂直保证左右对称。B：髋膝屈曲消除腰椎生理前凸、贴近台面。C：中心线经脐上3cm。D：屏气防止呼吸运动模糊。\n【为什么错】E：腰椎正位中心线垂直射入；向头侧倾斜15°是骶尾椎正位的投照要求。", "tr": "腰椎正位垂直投照；倾斜15°的体位是骶尾椎正位，勿混。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1051", "t": "多选题", "s": "寰枢椎张口位X线摄影的注意事项包括", "o": {"A": "患者尽量张大口腔", "B": "中心线经上颌中切牙与枕外隆凸连线中点垂直射入", "C": "避免上下颌骨与寰枢椎重叠", "D": "中心线向足侧倾斜30°射入", "E": "必要时嘱患者发“啊”音配合张口"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-051", "kp": "寰枢椎张口位注意事项", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A：张大口腔使上下颌骨投影分离。B：中心线经口腔垂直射入显示寰枢椎。C：避免颌骨遮挡C1、C2。E：发“啊”音有助于保持张口。\n【为什么错】D：张口位中心线垂直射入，不倾斜。", "tr": "张口位“垂直经口腔”；倾斜投照是汤氏位等其他体位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1052", "t": "多选题", "s": "骨盆正位X线摄影的技术要点包括", "o": {"A": "仰卧，正中矢状面垂直摄影台面", "B": "两足内旋约15°使股骨颈充分展开", "C": "中心线经耻骨联合上缘垂直射入", "D": "中心线向头侧倾斜20°", "E": "双侧髂骨、股骨头及骶尾椎均应在片内"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-052", "kp": "骨盆正位技术要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A：矢状面垂直保证双侧对称。B：足内旋约15°使股骨颈与股骨干展开、避免缩短重叠。C：中心线经耻骨联合上缘。E：骨盆环、双侧髋关节完整包括。\n【为什么错】D：骨盆正位中心线垂直射入，向头侧倾斜是骶尾椎正位的投照要求。", "tr": "骨盆正位“垂直＋足内旋15°”；“倾斜投照”是骶尾椎正位的特征。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1053", "t": "多选题", "s": "静脉肾盂造影（IVP）的术前准备包括", "o": {"A": "检查前晚少渣饮食并服缓泻剂清洁肠道", "B": "检查前禁食（可少量饮水）", "C": "排空膀胱", "D": "做碘过敏试验", "E": "无需任何准备直接检查"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-053", "kp": "IVP术前准备", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A：少渣饮食加缓泻剂清洁肠道，避免粪气影干扰。B：禁食减少呕吐等不良反应风险。C：排空膀胱便于观察输尿管及膀胱。D：碘过敏试验为必做项。\n【为什么错】E：IVP必须有肠道准备与碘过敏试验，不能直接检查。", "tr": "IVP术前“肠道准备＋碘过敏试验”是必须项；遗漏过敏试验属严重操作缺陷。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1054", "t": "多选题", "s": "下列属于静脉肾盂造影禁忌证的有", "o": {"A": "碘对比剂过敏", "B": "严重肾功能不全（尿毒症无尿）", "C": "单纯性肾囊肿", "D": "多发性骨髓瘤", "E": "妊娠早期"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-054", "kp": "IVP禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A：碘过敏为绝对禁忌。B：无尿时对比剂不能排泄、加重肾损伤。D：多发性骨髓瘤用碘剂易诱发急性肾功能衰竭。E：妊娠为禁忌。\n【为什么错】C：单纯性肾囊肿对碘剂不过敏且肾功能正常，不属于IVP禁忌。", "tr": "“多发性骨髓瘤＋无尿肾衰＋碘过敏＋妊娠”均为IVP禁忌；单纯性肾囊肿不是。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1055", "t": "多选题", "s": "子宫输卵管造影（HSG）的禁忌证包括", "o": {"A": "月经期", "B": "急性生殖道炎症", "C": "妊娠", "D": "碘过敏", "E": "不孕症"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-055", "kp": "HSG禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】A：月经期宫腔有创面、易感染且影像不清。B：急性炎症宫腔操作致感染扩散。C：妊娠行宫腔造影可致流产。D：碘过敏者禁用碘对比剂。\n【为什么错】E：不孕症是HSG最常见的适应证而非禁忌证。", "tr": "“不孕症=适应证”，勿将其列为禁忌；禁忌为月经期、急性炎症、妊娠、碘过敏。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1056", "t": "多选题", "s": "乳腺X线摄影时压迫乳腺可达到的目的包括", "o": {"A": "减小乳腺厚度、降低辐射剂量", "B": "减少散射线、提高对比度", "C": "固定乳腺、减少运动模糊", "D": "使乳腺组织均匀分布、减少结构重叠", "E": "增加放大率以显示微钙化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-056", "kp": "乳腺压迫的目的", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】A：厚度减小、剂量降低。B：散射线减少、对比度提高。C：固定乳腺防运动模糊。D：组织摊平减少重叠、密度均匀。\n【为什么错】E：压迫使乳腺贴近探测器，物片距减小，放大率减小而非增加。", "tr": "压迫“减小”放大；放大摄影靠加大焦片距/放大倍数实现，与压迫目的相反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1057", "t": "多选题", "s": "下列属于乳腺摄影附加体位的有", "o": {"A": "90°侧位（内外侧位）", "B": "乳沟位（双乳腺加压）", "C": "放大摄影", "D": "局部点压位", "E": "头尾位（CC）"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-057", "kp": "乳腺附加体位", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (2)乳腺附加体位", "ex": "【为什么对】A：90°侧位用于病灶上下定位。B：乳沟位显示乳腺内侧深部。C：放大摄影用于微钙化。D：局部点压位针对肿块加压显示。\n【为什么错】E：CC位（头尾位）与MLO位是乳腺常规体位，不属于附加体位。", "tr": "附加体位包括90°侧位、乳沟位、放大、点压、切线位、腋尾位等；CC/MLO是常规。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1058", "t": "多选题", "s": "乳腺导管造影的操作要点包括", "o": {"A": "适应证为乳头溢液患者", "B": "经溢液乳孔插入钝头细管（针）", "C": "缓慢注入水溶性碘对比剂1～3ml，至患者有胀感或出现阻力即停止", "D": "注药后摄CC位、MLO位（必要时加放大摄影）", "E": "用力快速加压注入使导管充分充盈"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-058", "kp": "乳腺导管造影操作要点", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (3)乳腺造影技术", "ex": "【为什么对】A：乳头溢液是导管造影主要适应证。B：钝头细管经溢液乳孔插入避免损伤导管。C：少量缓慢注药、有阻力即停，防止导管破裂。D：常规CC、MLO摄片记录导管分布。\n【为什么错】E：用力快速注药可致导管破裂、对比剂进入间质，属错误操作。", "tr": "导管造影“少量、缓慢、有阻力即停”；压力过大致导管破裂是操作禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1059", "t": "多选题", "s": "关于根尖片分角线投照与平行投照两种技术，正确的是", "o": {"A": "分角线投照中心线垂直牙长轴与胶片夹角的角平分线", "B": "平行投照要求胶片与牙长轴平行、中心线垂直牙长轴", "C": "平行投照影像失真比分角线投照大", "D": "平行投照可较真实地反映牙体长度", "E": "分角线投照适用于所有牙位且无失真"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-059", "kp": "根尖片投照技术比较", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】A：分角线投照中心线垂直角平分线，是经典定义。B：平行投照胶片与牙长轴平行、中心线垂直。D：平行投照牙体长度影像接近真实。\n【为什么错】C：平行投照失真比分角线投照更小。E：分角线投照存在角度误差导致的长度失真，并非无失真。", "tr": "“平行投照＝失真小”；“分角线投照＝角平分线、有放大/缩短失真”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1060", "t": "多选题", "s": "属于口内X线摄影技术的有", "o": {"A": "根尖片", "B": "咬合片", "C": "咬翼片", "D": "全口根尖片", "E": "曲面断层（全景片）"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-060", "kp": "口内X线摄影类型", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】A：根尖片显示牙冠、牙根及根尖周组织，属口内片。B：咬合片置于咬合面摄片，显示较大范围牙弓及颌骨。C：咬翼片显示上下牙冠及牙槽嵴顶。D：全口根尖片由多张口内片组成。\n【为什么错】E：曲面断层（全景片）胶片或探测器位于口外，属口外X线摄影。", "tr": "口内片＝根尖片、咬合片、咬翼片；曲面断层是口外摄影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1061", "t": "多选题", "s": "头颅侧位X线摄影的体位要求包括", "o": {"A": "正中矢状面与探测器平行", "B": "瞳间线垂直探测器", "C": "被检侧贴近探测器", "D": "中心线向足侧倾斜30°", "E": "中心线经外耳孔上方约2.5cm垂直射入"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-061", "kp": "头颅侧位体位要求", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A：矢状面与探测器平行保证标准侧位。B：瞳间线垂直避免头后仰或前屈。C：被检侧贴近探测器减少放大。E：中心线经外耳孔上方2.5cm（蝶鞍）垂直射入。\n【为什么错】D：头颅侧位垂直投照，向足侧倾斜30°是汤氏位的投照要求。", "tr": "侧位“矢状面平行＋瞳间线垂直”；倾斜投照属汤氏位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1062", "t": "多选题", "s": "关于胸部斜位X线摄影，正确的是", "o": {"A": "右前斜位（RAO）观察左心房及食管受压情况", "B": "左前斜位（LAO）观察左心室、右心房及胸主动脉", "C": "斜位摄影常用于心脏大血管的X线检查", "D": "中心线经第4胸椎垂直射入", "E": "患者身体旋转约45°~60°投照"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-062", "kp": "胸部斜位摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A：右前斜位（常伴吞钡）观察食管与左心房关系。B：左前斜位显示左心室、右心房、主动脉。C：斜位是心脏大血管X线检查常规组合体位。E：斜位一般旋转45°~60°。\n【为什么错】D：胸部正、侧、斜位中心线均经第6胸椎水平，而非第4胸椎。", "tr": "胸部各体位中心线水平均为“第6胸椎”；右前斜看左房食管、左前斜看左室右房主动脉。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1063", "t": "多选题", "s": "关于静脉肾盂造影摄片与腹部加压的叙述，正确的是", "o": {"A": "注药后7、15、30分钟分别摄肾区片", "B": "加压球囊置于髂前上棘连线水平、骶骨两侧", "C": "加压的目的是使肾盂肾盏充分充盈", "D": "所有患者均可行腹部加压", "E": "解除加压后摄全尿路片"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-063", "kp": "IVP摄片与加压技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A：7、15、30分钟摄片为常规时间点。B：加压部位为输尿管走行区（髂前上棘连线水平骶骨两侧）。C：加压延缓输尿管排空使肾盂肾盏充盈。E：解除加压后摄全尿路片显示输尿管下段及膀胱。\n【为什么错】D：腹主动脉瘤、新近腹部手术、妊娠等为加压禁忌，并非所有患者均可加压。", "tr": "“加压禁忌（腹主动脉瘤等）”是高频考点；加压部位是输尿管而非肾区。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1064", "t": "多选题", "s": "关于乳腺内外斜位（MLO）摄影技术，正确的是", "o": {"A": "球管自内上向外下约45°投照", "B": "为常规体位中显示乳腺组织最多者", "C": "可显示外上象限及腋尾部", "D": "X线束自上而下垂直投照", "E": "应尽量包括胸大肌及腋下淋巴结区域"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-064", "kp": "MLO位技术特点", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】A：MLO位自内上向外下45°投照。B：斜位显示乳腺组织量最大。C：外上象限及腋尾是MLO重点显示区域。E：包括胸大肌及腋窝淋巴结区便于评估。\n【为什么错】D：垂直上下投照是CC位（头尾位）的特点，MLO位为斜向投照。", "tr": "MLO斜45°、CC垂直，投照方向是两者鉴别要点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1065", "t": "多选题", "s": "关于骶尾椎及腰骶关节X线摄影，正确的是", "o": {"A": "骶尾椎正位中心线向头侧倾斜15°~20°", "B": "骶尾椎正位中心线经耻骨联合上缘射入", "C": "骶尾椎正位中心线垂直射入", "D": "腰骶关节正位中心线向头侧倾斜约15°，经腰骶间隙射入", "E": "骶尾椎侧位中心线经骶尾椎垂直射入"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-065", "kp": "骶尾椎与腰骶关节摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A：骶尾椎正位向头侧倾斜15°~20°。B：中心线经耻骨联合上缘射入使骶尾椎展开。D：腰骶关节正位向头侧倾斜约15°经腰骶间隙投照。E：骶尾椎侧位中心线垂直经骶尾椎。\n【为什么错】C：骶尾椎正位需向头侧倾斜，垂直投照会使骶尾椎与耻骨重叠、影像缩短。", "tr": "骶尾椎正位“头侧倾斜15°~20°经耻骨联合上缘”；勿与垂直投照混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1066", "t": "多选题", "s": "四肢骨X线摄影的一般原则包括", "o": {"A": "病变部位尽量贴近探测器以减少放大", "B": "一般至少摄正、侧两个相互垂直的体位", "C": "病变累及关节时应包括邻近关节", "D": "中心线垂直探测器射入", "E": "一律采用180cm远距离摄影"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-066", "kp": "四肢摄影一般原则", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】A：贴近探测器减少放大。B：正、侧位相互垂直可准确定位骨折移位。C：关节病变需包括关节以便观察。D：常规中心线垂直探测器。\n【为什么错】E：四肢常规焦片距约100cm（75~100cm），180cm远距离摄影用于胸部。", "tr": "四肢不用180cm；远距离摄影是胸部的标志性技术。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1067", "t": "多选题", "s": "关于泌尿系统X线造影，正确的是", "o": {"A": "IVP为静脉注射碘对比剂后经肾脏排泄显示肾盂肾盏", "B": "逆行肾盂造影适用于IVP不显影（如严重肾功能不全）者", "C": "逆行肾盂造影需借助膀胱镜将导管插入输尿管", "D": "膀胱造影通过口服对比剂充盈膀胱", "E": "静脉造影前应做碘过敏试验"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-067", "kp": "泌尿系统造影对比", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A：IVP经静脉给药、肾脏排泄显影。B：逆行造影不依赖肾功能，适用于IVP不显影者。C：逆行造影经膀胱镜插管。E：IVP前必须做碘过敏试验。\n【为什么错】D：膀胱造影是经导尿管向膀胱内注入对比剂充盈，而非口服。", "tr": "“膀胱造影经导尿管注入”是区别于IVP（静脉注射）的关键操作途径。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1068", "t": "多选题", "s": "副鼻窦瓦氏位（顶颏位）可显示的结构包括", "o": {"A": "上颌窦", "B": "额窦", "C": "蝶窦", "D": "筛窦", "E": "内听道"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-068", "kp": "瓦氏位显示范围", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A：上颌窦是瓦氏位主要显示对象。B：额窦在瓦氏位亦可显示。D：筛窦在瓦氏位投影中可见。\n【为什么错】C：蝶窦需用头颅侧位等专用体位，瓦氏位显示不佳。E：内听道由汤氏位显示，与副鼻窦无关。", "tr": "瓦氏位＝上颌窦；蝶窦、内听道属其他体位显示范围。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1069", "t": "多选题", "s": "胸部前弓位（前凸位）摄影的适应证与特点包括", "o": {"A": "用于显示肺尖部病变", "B": "用于显示锁骨下区病变", "C": "患者身体后仰，使锁骨投影上移", "D": "中心线经第6胸椎垂直射入", "E": "可使肺尖及第1、2肋间充分展开"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-069", "kp": "胸部前弓位适应证", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A：前弓位肺尖显示充分。B：锁骨下区病变为前弓位适应证。C：身体后仰使锁骨上移、肺尖露出。E：肺尖及上肺野展开显示。\n【为什么错】D：前弓位中心线经胸骨角水平（约平第4胸椎）垂直射入，而非经第6胸椎；第6胸椎是标准后前位的中心线水平。", "tr": "前弓位中心线“经胸骨角”，与标准后前位“经第6胸椎”不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1070", "t": "多选题", "s": "子宫输卵管造影（HSG）的适应证包括", "o": {"A": "不孕症", "B": "寻找输卵管梗阻部位", "C": "诊断子宫畸形", "D": "月经期止血", "E": "输卵管再通术后复查"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-070", "kp": "HSG适应证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】A：不孕症是HSG最常见适应证。B：显示输卵管梗阻部位与程度。C：显示宫腔形态诊断子宫畸形。E：输卵管再通术后评估通畅性。\n【为什么错】D：月经期为HSG禁忌证，造影不能用于止血。", "tr": "HSG是“诊断＋通畅性评估”手段；月经期是禁忌而非适应证。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U08-1071a", "t": "共用题干题", "s": "腰椎X线摄影常规首先应摄取的体位组合是", "o": {"A": "腰椎正位＋侧位", "B": "腰椎正位＋斜位", "C": "骶尾椎正位＋侧位", "D": "骨盆正位＋腰椎侧位", "E": "腰椎过伸过屈位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-071", "kp": "腰椎常规摄影体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎常规摄正位＋侧位两个相互垂直的体位，可观察椎体形态、椎间隙、骨质及生理曲度，满足腰椎间盘突出初步评估需求，故A正确。\n【为什么错】B：斜位用于显示椎弓峡部，为补充体位。C：骶尾椎体位显示范围不符。D：骨盆正位与腰椎评估无直接对应。E：过伸过屈位用于脊柱不稳的动力学评估，非常规首选。", "tr": "“正侧位是常规”，斜位、过伸过屈位均为针对性补充体位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0801", "gs": "患者男性，45岁，腰痛伴右下肢放射痛3个月，咳嗽、用力时加重，临床疑腰椎间盘突出，拟行腰椎X线摄影。技师需确定常规摄影体位、中心线入射点，并判断是否需加照特殊体位。"}, {"id": "U08-1071b", "t": "共用题干题", "s": "该患者腰椎正位摄影时，中心线的入射点为", "o": {"A": "脐", "B": "脐上3cm（约第3腰椎）", "C": "脐下3cm", "D": "两侧髂嵴连线中点", "E": "耻骨联合上缘"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-072", "kp": "腰椎正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎正位中心线经脐上3cm（约平第3腰椎）垂直射入，使腰椎序列完整居中显示，故B正确。\n【为什么错】A：脐水平偏低，腰椎下段显示偏斜。C：脐下3cm更低。D：髂嵴连线平第4腰椎偏下。E：耻骨联合上缘为骨盆正位中心线。", "tr": "“腰椎正位＝脐上3cm”是数值考点；骨盆正位才经耻骨联合上缘。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0801", "gs": ""}, {"id": "U08-1071c", "t": "共用题干题", "s": "若临床高度怀疑椎弓峡部裂所致腰椎滑脱，应加照的体位是", "o": {"A": "腰椎左、右斜位", "B": "腰椎过伸过屈位", "C": "骨盆正位", "D": "胸椎正位", "E": "骶尾椎侧位"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-073", "kp": "椎弓峡部裂补充体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎斜位（约45°）使椎弓峡部展开呈“狗形”，可直接观察峡部是否断裂，是诊断峡部裂的关键体位，故A正确。\n【为什么错】B：过伸过屈位用于评估腰椎不稳与滑脱的动态改变，不直接显示峡部。C、D、E：与峡部显示无关。", "tr": "“斜位看峡部（狗颈）、过伸过屈位看稳定性”，两者的检查目的易混。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0801", "gs": ""}, {"id": "U08-1072a", "t": "共用题干题", "s": "为显示枕骨及枕骨大孔，应首选的体位是", "o": {"A": "头颅汤氏位（Townes位）", "B": "头颅后前位", "C": "头颅侧位", "D": "柯氏位", "E": "瓦氏位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-074", "kp": "后颅窝外伤体位选择", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位中心线向足侧倾斜30°，使枕骨、枕骨大孔、颞骨岩部及内听道展开显示，是观察后颅窝及枕部骨折的首选体位，故A正确。\n【为什么错】B：后前位观察颅盖正位，枕骨下部与颅底重叠。C：侧位显示前后方向，后颅窝细节有限。D、E：柯氏位、瓦氏位用于副鼻窦。", "tr": "“枕部外伤→汤氏位”；副鼻窦体位不适用于颅底骨折。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0802", "gs": "患者男性，30岁，头部外伤后头痛、恶心2小时，后枕部着地，临床疑枕骨及颅底骨折，拟行头颅X线检查。技师需选择恰当体位、准确确定中心线入射点，以确保后颅窝结构显示清晰。"}, {"id": "U08-1072b", "t": "共用题干题", "s": "汤氏位摄影时中心线的投照要求为", "o": {"A": "垂直射入", "B": "向头侧倾斜30°", "C": "向足侧倾斜30°", "D": "向足侧倾斜15°", "E": "向头侧倾斜15°"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-075", "kp": "汤氏位中心线投照", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位仰卧、听眦线垂直探测器，中心线向足侧倾斜30°，经枕外隆凸下方射入（射达眉间方向），故C正确。\n【为什么错】A：垂直射入为正位要求。B：向头侧倾斜为骶尾椎正位特点。D、E：15°角度及方向均不符。", "tr": "汤氏位“向足侧倾斜30°”，方向与骶尾椎（向头侧倾斜）相反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0802", "gs": ""}, {"id": "U08-1073a", "t": "共用题干题", "s": "该患者首选的X线检查是", "o": {"A": "泌尿系平片（KUB）", "B": "静脉肾盂造影（IVP）", "C": "逆行肾盂造影", "D": "膀胱造影", "E": "子宫输卵管造影"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-076", "kp": "泌尿系结石首选检查", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】泌尿系平片（KUB）无创、简便、经济，约90%的泌尿系结石为阳性结石可在平片上显示，是疑结石患者的首选X线检查，故A正确。\n【为什么错】B：IVP在平片之后用于定位与功能评估。C：逆行造影为有创检查，用于IVP不显影者。D：膀胱造影用于膀胱病变。E：HSG与泌尿系结石无关。", "tr": "“肾绞痛→KUB平片首选”；IVP是第二步的功能定位检查。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0803", "gs": "患者女性，52岁，突发右腰腹部绞痛并向会阴部放射，伴肉眼血尿1天，临床疑右侧输尿管结石。拟先行X线检查，必要时进一步行静脉肾盂造影（IVP）。技师需安排检查流程并掌握造影摄片要点。"}, {"id": "U08-1073b", "t": "共用题干题", "s": "若进一步行IVP，注药后常规摄片时间点为", "o": {"A": "立即、5分钟、15分钟", "B": "7分钟、15分钟、30分钟", "C": "30分钟、60分钟", "D": "15分钟、60分钟", "E": "5分钟、30分钟"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-077", "kp": "IVP摄片时间点", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】IVP注药后7分钟肾盂肾盏开始显影，15、30分钟观察充盈与排泄，解除加压后摄全尿路片，故B正确。\n【为什么错】A：5分钟内肾实质显影、肾盏充盈不足。C、D、E：时间点与常规不符。", "tr": "IVP摄片时间“7、15、30分钟”是造影流程的高频考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0803", "gs": ""}, {"id": "U08-1074a", "t": "共用题干题", "s": "该患者乳腺X线摄影的常规投照体位是", "o": {"A": "头尾位（CC）＋内外斜位（MLO）", "B": "双侧侧位", "C": "放大摄影＋点压位", "D": "乳沟位＋腋尾位", "E": "切线位＋CC位"}, "d": "易", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-078", "kp": "乳腺常规体位", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】乳腺常规摄影为CC位与MLO位两个体位，从上下及斜向两个方向显示乳腺，是筛查与诊断的基础，故A正确。\n【为什么错】B、C、D、E：均为附加或补充体位，不能替代常规体位组合。", "tr": "“CC＋MLO”是乳腺摄影标配组合，附加体位在其基础上选用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0804", "gs": "患者女性，55岁，右乳外上象限触及无痛性肿块1个月，质硬、边界不清，临床疑乳腺癌，拟行乳腺X线摄影。技师需确定常规体位，并对摄影中发现的微钙化选择恰当的补充体位。"}, {"id": "U08-1074b", "t": "共用题干题", "s": "摄影中发现可疑簇状微钙化，为观察钙化形态应加照", "o": {"A": "放大摄影", "B": "乳沟位", "C": "腋尾位", "D": "90°侧位", "E": "切线位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-079", "kp": "乳腺微钙化放大摄影", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (2)乳腺附加体位", "ex": "【为什么对】放大摄影（1.5~2倍）可清晰显示微钙化的形态、数目与分布，对良恶性鉴别至关重要，故A正确。\n【为什么错】B：乳沟位显示内侧深部。C：腋尾位显示腋尾。D：90°侧位用于病灶定位。E：切线位用于皮肤及表浅病变。", "tr": "“钙化看放大、肿块看点压”，附加体位的分工需记清。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0804", "gs": ""}, {"id": "U08-1075a", "t": "共用题干题", "s": "该患者HSG检查宜安排在", "o": {"A": "月经期", "B": "月经干净后3～7天", "C": "排卵期", "D": "月经来潮前1周", "E": "任意时间"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-080", "kp": "HSG检查时机", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】HSG应安排在月经干净后3~7天（卵泡期），此时子宫内膜薄、无经血、可排除早孕，故B正确。\n【为什么错】A：月经期有创面易感染。C：排卵期后内膜增厚影响判断。D、E：均非适宜时机。", "tr": "“月经净后3~7天”是HSG的固定时机考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0805", "gs": "患者女性，30岁，结婚2年未孕，月经规律，男方精液检查正常，临床拟行子宫输卵管造影（HSG）评估输卵管通畅性。技师需掌握检查时机、禁忌判断及对比剂的选择与复查时间。"}, {"id": "U08-1075b", "t": "共用题干题", "s": "若选用碘化油行造影，需加摄的延迟片时间为", "o": {"A": "15分钟", "B": "30分钟", "C": "24小时", "D": "48小时", "E": "无需延迟片"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-081", "kp": "HSG碘化油延迟片", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】碘化油黏稠、吸收缓慢，需24小时后复查摄片观察对比剂自伞端弥散入盆腔的情况，判断输卵管通畅度，故C正确。\n【为什么错】A、B：15、30分钟为水溶性碘剂复查时间。D：48小时非标准时间。E：油剂必须加延迟片。", "tr": "“油剂24小时延迟片、水剂短时复查”是HSG对比剂特性考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0805", "gs": ""}, {"id": "U08-1076a", "t": "共用题干题", "s": "胸部后前位X线摄影中心线的入射点为", "o": {"A": "第4胸椎", "B": "第6胸椎", "C": "第7胸椎", "D": "胸骨角", "E": "剑突"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-082", "kp": "胸部后前位中心线", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸部后前位中心线经第6胸椎垂直射入探测器中心，使双肺及纵隔居中对称显示，故B正确。\n【为什么错】A：第4胸椎平胸骨角偏高。C：第7胸椎为胸椎正位中心线。D：胸骨角是前弓位中心线。E：剑突水平过低。", "tr": "胸部正位中心线“第6胸椎”；前弓位才经胸骨角。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0806", "gs": "患者男性，60岁，体检胸片发现右肺门影增大，前来复查胸部X线。技师需规范摆位、准确确定中心线入射点，并掌握远距离摄影的意义，以保证影像质量并兼顾辐射防护。"}, {"id": "U08-1076b", "t": "共用题干题", "s": "该患者胸部正位采用180cm焦片距远距离摄影的主要意义是", "o": {"A": "减少散射线", "B": "减小心脏等器官的放大失真", "C": "提高空间分辨率", "D": "缩短曝光时间", "E": "便于患者屏气配合"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-083", "kp": "胸部远距离摄影意义", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】心脏位于胸腔前半部、距探测器较远，180cm远距离摄影使放大率减小、心影接近真实大小，便于心影测量与随访比较，故B正确。\n【为什么错】A：散射线控制靠滤线栅及散射线吸收。C：空间分辨率主要由探测器与焦点决定。D：焦片距增大反而需增加曝光条件。E：与屏气配合无关。", "tr": "远距离摄影的核心是“减小心脏放大”，而非提高分辨率或减少散射线。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0806", "gs": ""}, {"id": "U08-1077a", "t": "共用题干题", "s": "能一次显示全口牙列及牙槽骨情况的检查是", "o": {"A": "曲面断层（全景片）", "B": "根尖片", "C": "咬翼片", "D": "咬合片", "E": "头颅侧位"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-084", "kp": "曲面断层适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】曲面断层一次曝光即可显示全口牙列、双侧上下颌骨及牙槽骨整体情况，是牙周病等需全面评估的首选，故A正确。\n【为什么错】B、C、D：均为口内局部片，范围局限。E：头颅侧位用于正畸测量，不显示牙槽骨细节。", "tr": "“全口整体评估→曲面断层；局部精细评估→根尖片”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0807", "gs": "患者男性，50岁，牙龈出血伴全口牙松动，临床疑牙周病，拟行口腔X线检查以全面评估牙槽骨吸收情况。技师需选择合适的检查技术，并对个别牙的根尖周病变选择精细显示方法。"}, {"id": "U08-1077b", "t": "共用题干题", "s": "需对个别牙的牙根及根尖周骨质精确显示时，应选择", "o": {"A": "根尖片（优先平行投照）", "B": "曲面断层", "C": "咬合片", "D": "头颅正位", "E": "颞下颌关节位"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-085", "kp": "根尖片适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】根尖片分辨率高，可精细显示个别牙的牙冠、牙根、根尖周骨质及牙周膜间隙，平行投照失真最小，故A正确。\n【为什么错】B：曲面断层整体显示但局部分辨率不如根尖片。C：咬合片用于较大范围牙弓与颌骨。D、E：与根尖周显示无关。", "tr": "“根尖片=局部精细”，与曲面断层的“整体普查”互为补充。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0807", "gs": ""}, {"id": "U08-1078", "t": "案例分析题", "s": "患者男性，58岁，吸烟史30年，慢性咳嗽、咳痰伴痰中带血2周，胸部听诊右下肺呼吸音减低，临床疑右下肺占位性病变，前来行胸部X线检查。设备为DR，采用自动曝光控制。技师嘱患者站立、前胸壁贴紧探测器，双手背置于髋部、肘部内旋使肩胛骨外展，嘱深吸气后屏气曝光，注意双侧肺野及肋膈角均应包括在摄影范围内。关于本次胸部后前位摄影的技术要点，正确的是", "o": {"A": "中心线经胸骨角垂直射入", "B": "焦片距采用100cm", "C": "中心线经第6胸椎垂直射入，焦片距180cm", "D": "中心线向足侧倾斜15°射入", "E": "嘱患者呼气后屏气曝光"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-086", "kp": "胸部后前位摄影综合要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸部后前位中心线经第6胸椎垂直射入探测器中心，采用180cm远距离摄影减小放大，深吸气后屏气减少运动模糊，三者均符合标准，故C正确。\n【为什么错】A：胸骨角是前弓位中心线定位点，后前位经第6胸椎。B：100cm为四肢常规焦片距，胸部应取180cm。D：胸部后前位中心线垂直，不倾斜。E：应深吸气后屏气使肺野充分展开，呼气位影响肺野显示。", "tr": "胸部后前位“第6胸椎＋180cm＋深吸气后屏气”三位一体，是胸部摄影的核心组合。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1079", "t": "案例分析题", "s": "患者男性，40岁，1小时前从高处坠落致头枕部外伤，伴头痛、恶心并呕吐1次，查体枕部皮肤瘀肿、压痛明显，临床高度怀疑枕骨及颅底骨折，申请头颅X线检查。技师拟行头颅汤氏位（Townes位）摄影，需确保枕骨、枕骨大孔、颞骨岩部及内听道等后颅窝结构显示充分，并要求患者保持头部固定不动。关于汤氏位摄影，正确的叙述是", "o": {"A": "患者俯卧，前额及鼻尖贴近探测器", "B": "中心线垂直射入眉间", "C": "患者仰卧、听眦线垂直探测器，中心线向足侧倾斜30°经枕外隆凸下方射入", "D": "中心线向头侧倾斜30°", "E": "听眦线平行探测器"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-087", "kp": "汤氏位摄影技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位患者仰卧、听眦线垂直探测器，中心线向足侧倾斜30°，经枕外隆凸下方射入，使枕骨、枕骨大孔、岩部及内听道展开，符合后颅窝显示需求，故C正确。\n【为什么错】A：俯卧、额鼻贴片是后前位。B：垂直射入是正位要求。D：向头侧倾斜为骶尾椎正位特点。E：听眦线应垂直而非平行探测器。", "tr": "汤氏位“仰卧＋向足侧倾斜30°”，从摆位到角度都须准确。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1080", "t": "案例分析题", "s": "患者女性，48岁，反复右侧腰痛伴肉眼血尿3个月，B超提示右肾结石并轻度肾积水，临床申请静脉肾盂造影（IVP）以明确结石位置及肾功能情况。患者既往有哮喘病史，本次碘过敏试验阴性。检查前已行少渣饮食、清洁灌肠并排空膀胱，技师需掌握对比剂选择、摄片时间与腹部加压等要点，并备好急救物品以应对可能的不良反应。关于IVP操作，正确的是", "o": {"A": "对比剂选用碘化油", "B": "静脉注射碘对比剂后于7、15、30分钟摄片", "C": "注药后立即摄全尿路片", "D": "加压球囊置于上腹部正中", "E": "无需行腹部加压"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-088", "kp": "IVP操作流程", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】IVP静脉注射水溶性碘对比剂，7、15、30分钟分别摄肾区片，符合标准流程，故B正确。\n【为什么错】A：碘化油用于HSG等，IVP用碘对比剂。C：注药后早期为肾实质期，肾盏充盈需数分钟，不能立即摄全尿路片。D：加压球囊置于髂前上棘连线水平骶骨两侧压迫输尿管，非上腹部正中。E：常规需腹部加压使肾盂肾盏充盈（加压禁忌者除外）。", "tr": "IVP标准流程“静脉碘剂＋7/15/30分钟＋输尿管区加压”，哮喘史患者更应注意过敏风险防范。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1081", "t": "案例分析题", "s": "患者女性，28岁，结婚2年未孕，月经周期规律，男方精液检查正常，临床拟行子宫输卵管造影（HSG）以评估输卵管通畅性。患者平素月经规律，末次月经已过10天，无生殖道感染史，碘过敏试验阴性。技师需判断检查时机是否合适并掌握对比剂特性及复查时间，同时做好患者沟通以减轻紧张情绪。关于该患者HSG检查，正确的说法是", "o": {"A": "月经期亦可进行检查", "B": "造影时机应选月经干净后3～7天，本次时机已过，需重新安排", "C": "用碘化油造影后30分钟复查即可", "D": "注药速度越快越好，可减少患者不适", "E": "造影后无需观察即可离院"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-089", "kp": "HSG时机与流程", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】HSG应选月经干净后3~7天，该患者末次月经已过10天，接近排卵期、内膜增厚，不符合最佳时机，需重新预约，故B正确。\n【为什么错】A：月经期为禁忌。C：碘化油需24小时延迟片，30分钟复查是水剂的要求。D：注药应缓慢，快速注药可致输卵管破裂、对比剂反流。E：造影后需观察不良反应并告知注意事项。", "tr": "时机不符应改期；油剂与水剂延迟片时间不同；注药宜缓。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1082", "t": "案例分析题", "s": "患者女性，62岁，绝经后5年，发现左乳外上象限质硬肿块1个月，边界不清、活动度差，临床疑乳腺癌，拟行乳腺X线摄影。检查前技师嘱患者去除胸部乳膏、爽身粉等含金属粉末的体表物，并询问月经史及哺乳史。拟行双侧CC位及MLO位摄影，必要时加照附加体位，摄影时充分压迫但以患者可耐受为度。关于乳腺摄影操作，正确的是", "o": {"A": "只需摄影患侧乳腺", "B": "MLO位X线束自上而下垂直投照", "C": "充分压迫乳腺，压力以患者可耐受为度", "D": "中心线经第6胸椎垂直射入", "E": "放大摄影作为常规体位"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-090", "kp": "乳腺摄影操作规范", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】乳腺摄影必须充分压迫（减少厚度、散射线、运动模糊），压力以患者能耐受为度，兼顾图像质量与舒适度，故C正确。\n【为什么错】A：应双侧对比摄影，仅摄患侧不利于对照。B：MLO位自内上向外下约45°斜向投照。D：乳腺摄影中心线经乳腺中心而非第6胸椎。E：放大摄影是附加体位，常规为CC＋MLO。", "tr": "乳腺摄影“双侧对比＋充分压迫＋CC/MLO常规”，附加体位按需加用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1083", "t": "案例分析题", "s": "患者女性，41岁，右侧乳头单孔血性溢液1个月，乳晕区未触及明确肿块，挤压乳头可挤出少量血性液体，乳腺超声未见明显占位，临床疑导管内乳头状瘤，拟行乳腺导管造影明确诊断。技师需掌握消毒、经溢液乳孔插管、缓慢注药及摄片等操作要点，并注意观察患者有无疼痛等不适反应，备好急救物品以防碘过敏反应。关于该造影操作，正确的是", "o": {"A": "消毒后经溢液乳孔插入钝头细管，缓慢注入水溶性碘对比剂1～3ml，有阻力即停止", "B": "用力快速推注使导管充分充盈", "C": "注入碘化油50ml观察全乳腺", "D": "注药后立即常规摄放大摄影即可", "E": "急性乳腺炎患者亦可进行本检查"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-091", "kp": "乳腺导管造影操作", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (3)乳腺造影技术", "ex": "【为什么对】导管造影经溢液乳孔插入钝头细管，缓慢注入少量（1~3ml）水溶性碘对比剂，遇阻力即停止，防止导管破裂及对比剂进入间质，故A正确。\n【为什么错】B：快速注药压力过大可致导管破裂。C：碘化油50ml剂量明显过大且选材错误。D：常规应摄CC位、MLO位（必要时放大），不能只摄放大摄影。E：急性乳腺炎为导管造影禁忌证。", "tr": "导管造影“少量、缓慢、有阻力即停”，急性炎症禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1084", "t": "案例分析题", "s": "患者男性，35岁，从2米高处坠落致颈部外伤，颈托固定后诉颈部剧痛、双上肢麻木，临床高度怀疑寰枢椎骨折脱位，拟行颈椎X线检查明确诊断。技师需选择能清晰显示寰枢椎、避开下颌骨及牙齿遮挡的体位，并注意在颈托保护下规范摆位，避免过度搬动加重损伤，必要时请临床医师协助固定。关于该体位的选择与摄影要点，正确的是", "o": {"A": "常规颈椎正位即可充分显示寰枢椎", "B": "采用张口位（开口位），中心线经口腔垂直射入", "C": "采用颈椎斜位，中心线向足侧倾斜15°", "D": "采用颈椎侧位，中心线向足侧倾斜30°", "E": "采用头颅汤氏位显示寰枢椎"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-092", "kp": "寰枢椎外伤检查体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】张口位中心线经口腔垂直射入，使上下颌骨投影分开，寰椎、枢椎（齿突）清晰显示，是疑寰枢椎损伤的首选体位，故B正确。\n【为什么错】A：颈椎正位寰枢椎被下颌骨及牙齿遮挡。C：斜位用于显示椎间孔。D：侧位显示椎体序列与曲度，对寰枢椎细节有限。E：汤氏位显示后颅窝，非寰枢椎。", "tr": "寰枢椎检查“张口位”，中心线必须经口腔；颈椎外伤患者应在颈托保护下完成。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1085", "t": "案例分析题", "s": "患者男性，55岁，长期从事搬运工作，慢性腰痛伴间歇性跛行5年，腰椎正侧位片示L5椎体前滑移约Ⅱ度，临床疑椎弓峡部裂所致腰椎滑脱。为进一步明确峡部是否断裂、评估手术必要性，技师应加照恰当的补充体位，注意掌握摆位角度及中心线方向，必要时结合过伸过屈位评估稳定性。患者无高血压、糖尿病等合并症。关于该补充体位的选择，正确的是", "o": {"A": "腰椎左、右斜位", "B": "骨盆正位", "C": "骶尾椎正位", "D": "腰椎过伸位", "E": "胸椎正位"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-093", "kp": "腰椎峡部裂检查体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎左、右斜位约45°使椎弓峡部展开呈“狗形”，可直接观察峡部是否断裂，是诊断峡部裂的确定性体位，故A正确。\n【为什么错】B：骨盆正位不显示椎弓峡部。C：骶尾椎正位显示范围不符。D：过伸位评估滑脱稳定性，不直接显示峡部。E：胸椎正位与L5峡部无关。", "tr": "腰椎滑脱病因评估“斜位看峡部”，动态稳定评估“过伸过屈位”，两者目的不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1086", "t": "案例分析题", "s": "患者男性，20岁，踢足球时扭伤右膝关节，膝部明显肿胀、关节腔积液，浮髌试验阳性，屈伸活动受限，临床疑胫骨髁间棘骨折及半月板损伤，拟行右膝关节X线摄影。技师准备拍摄膝关节正位与侧位，注意中心线入射点、投照方向及患者体位摆放，避免关节旋转导致影像失真。患者否认既往膝关节外伤及手术史。关于膝关节正位摄影的中心线与体位要求，正确的是", "o": {"A": "中心线经髌骨上缘射入", "B": "中心线经髌骨下缘（股胫关节线）垂直射入", "C": "中心线向头侧倾斜20°射入", "D": "焦片距取180cm", "E": "患者俯卧、屈膝投照"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-094", "kp": "膝关节正位摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】膝关节正位中心线经髌骨下缘（股胫关节线）垂直射入，可清晰显示股胫关节间隙及髁间结构，故B正确。\n【为什么错】A：髌骨上缘偏高，关节线显示不佳。C：正位垂直投照，不倾斜。D：四肢常规焦片距100cm，180cm为胸部。E：膝关节正位患者仰卧伸直下肢，俯卧屈膝是髌骨轴位等体位。", "tr": "膝关节正位“仰卧伸直＋中心线经髌骨下缘”；俯卧屈膝是髌骨轴位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1087", "t": "案例分析题", "s": "患者男性，45岁，既往十二指肠溃疡病史，突发上腹刀割样剧痛2小时，查体呈板状腹、全腹压痛反跳痛，肠鸣音消失，临床高度怀疑溃疡病穿孔，紧急申请X线检查以观察有无膈下游离气体。技师需指导患者配合体位摆放并选择恰当投照方式，尽快完成检查以辅助临床决策，同时注意检查前与患者沟通注意事项。关于该检查的体位选择与技术要点，正确的是", "o": {"A": "采用腹部仰卧前后位即可显示游离气体", "B": "采用立位（半坐位）腹部平片，水平投照观察膈下游离气体", "C": "采用腹部俯卧后前位", "D": "采用骨盆正位", "E": "嘱患者深呼吸后屏气曝光即可"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-095", "kp": "膈下游离气体检查", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】立位或半坐位水平投照时游离气体上浮集聚于膈下肝顶间隙，呈新月形透亮影，是最佳显示方法，故B正确。\n【为什么错】A：仰卧位游离气体聚于前腹壁下，与肠气混杂难以辨认。C：俯卧位更不利于气体显示。D：骨盆正位与穿孔无关。E：屏气是必要条件而非体位选择要点。", "tr": "“膈下游离气体必须立位/半坐位水平投照”，卧位平片极易漏诊。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1088", "t": "案例分析题", "s": "患者男性，70岁，走路时不慎摔倒致左肩外伤，左肩部疼痛剧烈、肿胀，活动明显受限，右臂托扶就诊，临床疑左肩关节脱位及肱骨外科颈骨折，拟行左肩关节正位X线摄影。技师需准确确定中心线入射点并规范摆位，必要时加照轴位或穿胸位以观察肱骨头脱位情况，摆位时动作轻柔避免加重疼痛。关于肩关节正位摄影中心线的入射点，正确的是", "o": {"A": "喙突", "B": "肩峰", "C": "肱骨外科颈", "D": "锁骨中点", "E": "肩胛下角"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-096", "kp": "肩关节正位中心线", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】肩关节正位中心线经喙突垂直射入，使肱骨头、关节盂及肩锁关节清晰显示，故A正确。\n【为什么错】B：肩峰偏外上方。C：肱骨外科颈为骨折部位而非定位点。D：锁骨中点偏内侧。E：肩胛下角为背部标志，与肩关节正位定位无关。", "tr": "肩关节正位“中心线经喙突”；疑肩锁关节分离需加照双肩负重位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1089", "t": "案例分析题", "s": "患者女性，25岁，滑冰时手掌撑地摔倒致右腕肿痛，鼻烟壶区压痛明显，普通腕关节正位片未见明确骨折线，临床高度怀疑腕舟骨骨折。为明确诊断，技师需选择能避开舟骨与邻近腕骨重叠的特殊投照体位，掌握中心线倾斜方向与角度，必要时嘱患者随访复查或加做CT。同时嘱患者减少腕部活动并适当抬高患肢。关于舟骨骨折的补充检查方案，正确的是", "o": {"A": "加照舟骨尺偏位（中心线经桡骨茎突向尺侧倾斜约20°射入）", "B": "加照腕关节侧位即可确诊", "C": "加照手正位即可确诊", "D": "加照肘关节正位", "E": "加照前臂正侧位"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-097", "kp": "舟骨骨折补充体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】舟骨位（尺偏位）腕关节向尺侧偏转使舟骨长轴展开，中心线经桡骨茎突向尺侧倾斜约20°，避免舟骨与邻近腕骨重叠，是显示舟骨骨折的关键补充体位，故A正确。\n【为什么错】B：侧位舟骨与其余腕骨重叠，显示不佳。C：手正位舟骨仍重叠。D、E：肘关节、前臂体位与腕舟骨无关。", "tr": "“鼻烟壶区压痛→疑舟骨骨折→尺偏位”，舟骨骨折早期平片可阴性。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U08-1090", "t": "案例分析题", "s": "患者男性，48岁，右下后牙反复肿痛，拟拔除右下阻生智齿，术前需了解牙根形态、数目及其与下牙槽神经管的关系，同时评估全口牙槽骨情况，为手术方案及风险告知提供依据。技师需选择能兼顾局部细节与整体结构的X线检查方法，必要时配合根尖片精细显示牙根与神经管关系。患者既往有牙周炎病史及多次拔牙史。关于术前X线检查方法的选择，正确的是", "o": {"A": "首选曲面断层（全景片）", "B": "仅摄右下根尖片即可", "C": "摄咬合片即可满足要求", "D": "摄头颅正位定位片", "E": "摄颞下颌关节许氏位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-098", "kp": "阻生智齿术前检查", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】曲面断层可一次显示全口牙列、下颌骨及下牙槽神经管走向，既能评估阻生智齿牙根形态与神经管关系，又能评估全口牙槽骨，是阻生智齿拔除术前首选，故A正确。\n【为什么错】B：根尖片局部显示，无法评估神经管全貌。C：咬合片显示范围不符。D：头颅正位用于颅骨测量。E：许氏位用于颞下颌关节。", "tr": "阻生智齿术前“曲面断层＋必要时根尖片局部放大”，全景片是首选。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-1091", "t": "案例分析题", "s": "患者女性，50岁，右侧腰痛伴发热2周，影像学提示右肾盂积水，IVP示右肾及输尿管上段显影不清，临床拟行右侧逆行肾盂造影以明确梗阻部位及原因。技师需了解逆行造影的适应证、禁忌及操作要点，并与患者做好沟通，检查前确认碘过敏试验结果，术中注意无菌操作。患者无出血倾向，凝血功能正常。关于逆行肾盂造影的技术要点，正确的是", "o": {"A": "经膀胱镜将导管插入右输尿管，注入少量对比剂显示肾盂形态", "B": "需静脉快速注射大量对比剂", "C": "检查前无需做碘过敏试验", "D": "急性泌尿系感染期亦可安全进行", "E": "对比剂选用碘化油"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-099", "kp": "逆行肾盂造影技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】逆行肾盂造影经膀胱镜将导管插入输尿管，直接注入少量对比剂逆行充盈肾盂肾盏，不经肾脏排泄，适用于IVP不显影者，故A正确。\n【为什么错】B：逆行造影不依赖静脉给药，用量小。C：仍使用含碘对比剂，术前必须做碘过敏试验。D：急性泌尿系感染为逆行造影禁忌，可致感染扩散。E：逆行造影使用水溶性碘对比剂，不用碘化油。", "tr": "逆行造影“膀胱镜插管＋少量直接注入”，碘过敏与急性感染均属禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U08-1092", "t": "案例分析题", "s": "患者女性，72岁，在家中滑倒后右髋部疼痛、不能站立行走，右下肢呈外旋短缩畸形，临床高度怀疑右股骨颈骨折，拟行X线检查以明确骨折部位与类型，并为治疗方案提供依据。技师需确定恰当的摄影方案与体位配合，注意轻柔搬动患者并做好辐射防护，必要时加摄对侧对比。患者有骨质疏松病史，检查时注意轻柔操作。关于该患者髋部摄影方案，正确的是", "o": {"A": "摄骨盆正位（两足内旋约15°）并加摄右侧髋关节正位", "B": "仅摄右侧髋关节侧位", "C": "摄骶尾椎正位", "D": "摄右膝关节正位", "E": "摄右股骨全长正位即可"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-100", "kp": "股骨颈骨折摄影方案", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】股骨颈骨折应摄骨盆正位（双侧对比、排除对侧病变）并加摄患侧髋关节正位，两足内旋约15°使股骨颈充分展开显示，故A正确。\n【为什么错】B：仅侧位无法全面评估且无对侧对比。C：骶尾椎正位与股骨颈无关。D：膝关节正位部位不符。E：股骨全长正位不能突出显示股骨颈及对比。", "tr": "“髋部外伤→骨盆正位＋患髋正位，两足内旋15°”，双侧对比是骨折摄影重要原则。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-9101", "t": "单选题", "s": "下列情况中，不属于静脉肾盂造影（IVP）禁忌证的是", "o": {"A": "碘对比剂过敏史", "B": "无尿或严重肾功能衰竭", "C": "多发性骨髓瘤", "D": "妊娠（相对禁忌，需权衡）", "E": "单纯性肾囊肿"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9101-副高", "kp": "静脉肾盂造影禁忌证", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)静脉肾盂造影", "ex": "【为什么对】E 正确：单纯性肾囊肿不影响对比剂排泄，不属于 IVP 禁忌。【为什么错】A 碘过敏可致严重过敏反应，禁忌；B 无尿时对比剂无法排泄、加重肾损伤，禁忌；C 多发性骨髓瘤患者使用碘对比剂可诱发骨髓瘤肾病、禁忌；D 妊娠为相对禁忌需充分权衡。", "tr": "易将\"单纯性肾囊肿\"误列为禁忌；囊肿不影响排泄，并非禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 0}, {"id": "U08-9102", "t": "多选题", "s": "关于口服钡餐（上消化道）造影的检查前准备，下列说法正确的有", "o": {"A": "检查前禁食 8–12 小时", "B": "停用影响胃肠蠕动的药物（如阿托品、吗丁啉）", "C": "必要时清除肠内气体与内容物", "D": "常规行全结肠清洁灌肠", "E": "检查前大量饮水以充盈胃腔"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9102-副高", "kp": "胃肠道钡餐造影准备", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)上消化道钡餐造影", "ex": "【为什么对】A、B、C 正确：禁食可减少胃内容物重叠、停用促/抑动力药避免干扰、适当清除气体有助于显示。【为什么错】D 上消化道钡餐无需全结肠清洁灌肠；E 检查前大量饮水会稀释、冲走钡剂，影响黏膜涂布与显示。", "tr": "E 为干扰项——大量饮水反而冲淡钡剂；D 仅适用于下消化道/结肠造影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 1}, {"id": "U08-9103", "t": "单选题", "s": "子宫输卵管造影（HSG）的最佳检查时间是", "o": {"A": "月经干净后 3–7 天", "B": "月经期 Any day of menstruation", "C": "排卵期", "D": "月经来潮前 1 周", "E": "整个月经周期任意时间均可"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9103-副高", "kp": "子宫输卵管造影时机", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)子宫输卵管造影", "ex": "【为什么对】A 正确：月经干净后 3–7 天子宫内膜已修复、尚未排卵，造影剂不易逆流入腹腔且能避免妊娠可能，是 HSG 的最佳时机。【为什么错】B 经期感染风险高；C 排卵期可能受孕；D、E 时机不当增加并发症或误诊。", "tr": "需区分\"月经干净后\"而非\"月经前\"；同时排除已排卵受孕窗口。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 0}, {"id": "U08-9104", "t": "单选题", "s": "关于经内镜逆行胰胆管造影（ERCP）的下列叙述，正确的是", "o": {"A": "经十二指肠镜插管至十二指肠大乳头，逆行注入对比剂显示胰胆管", "B": "经 T 管注入对比剂", "C": "经皮经肝穿刺注入", "D": "经静脉注射对比剂", "E": "口服对比剂后显示"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9104-副高", "kp": "ERCP 途径", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)ERCP", "ex": "【为什么对】A 正确：ERCP 是在十二指肠镜下将导管插入十二指肠大乳头（Oddi 括约肌）开口，逆行注入碘对比剂使胰管、胆管显影。【为什么错】B 为 T 管造影路径；C 为 PTC（经皮经肝胆道造影）；D、E 不符合 ERCP 定义。", "tr": "易与 PTC、T 管造影、MRCP 的路径混淆；ERCP 关键是\"内镜+逆行乳头插管\"。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 0}, {"id": "U08-9105", "t": "单选题", "s": "胆道术后经 T 管造影（T-tube cholangiography）的主要适应证是", "o": {"A": "了解胆道通畅情况并发现残余结石", "B": "术前评估胆囊形态", "C": "替代 MRCP 作为首选检查", "D": "诊断单纯胆囊结石", "E": "无症状体检筛查"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9105-副高", "kp": "T管造影适应证", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)T管造影", "ex": "【为什么对】A 正确：T 管造影在胆道术后经留置的 T 管注入对比剂，用于评估胆总管通畅度、有无狭窄及残余/复发结石，是拔管前常规检查。【为什么错】B、D 为术前/其他检查目的；C MRCP 是无创首选；E 无需造影筛查。", "tr": "T 管造影是\"术后拔管前\"检查，而非术前或筛查手段。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 0}, {"id": "U08-9201", "t": "单选题", "s": "子宫输卵管造影（HSG）常用的对比剂是", "o": {"A": "碘化油或碘水溶液", "B": "硫酸钡", "C": "二氧化碳气体", "D": "钆对比剂", "E": "空气"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-9201", "kp": "HSG对比剂选择", "ch": "八、普通X线检查技术 → 3.X线造影检查", "ex": "【为什么对】子宫输卵管造影常用碘化油或水溶性碘对比剂，可显示宫腔与输卵管形态。\n【为什么错】硫酸钡用于消化道；空气/二氧化碳用于阴性对比；钆剂用于MRI。", "tr": "HSG对比剂为碘剂而非钡剂。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U08-9202", "t": "单选题", "s": "静脉肾盂造影（IVP）属于", "o": {"A": "阴性对比造影", "B": "阳性对比剂静脉性排泄造影", "C": "直接穿刺造影", "D": "MR造影", "E": "超声造影"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-9202", "kp": "IVP原理", "ch": "八、普通X线检查技术 → 3.X线造影检查", "ex": "【为什么对】IVP经静脉注射阳性碘对比剂，借肾脏排泄显示尿路，属静脉性排泄造影。\n【为什么错】并非阴性对比或穿刺造影。", "tr": "IVP是静脉尿路造影，靠肾排泄显影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0101", "t": "单选题", "s": "已知某组织的X线线性衰减系数为0.021 mm⁻¹，同一扫描条件下水的线性衰减系数为0.019 mm⁻¹。按Hounsfield的定义，该组织的CT值最接近", "o": {"A": "21 HU", "B": "95 HU", "C": "105 HU", "D": "190 HU", "E": "1000 HU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-101", "kp": "CT值定义与计算公式", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】C正确。CT值的定义式为：CT值＝（μ组织－μ水）/μ水×1000（单位HU），即以水的线性衰减系数为基准做相对线性变换、再乘标度常数1000。代入：（0.021－0.019）/0.019×1000≈105.3 HU，最接近105 HU。【为什么错】A错误：21 HU是把组织自身的μ值直接乘1000（0.021×1000）得到的，混淆了绝对衰减系数与相对CT值。B错误：95 HU来自把分母误写成组织的μ（0.002/0.021×1000≈95），公式中分母恒为水的μ。D错误：190 HU相当于把标度常数误用为2000（老式EMI标度），现行Hounsfield标度K＝1000。E错误：1000 HU是把标度常数本身当成结果，且骨皮质等高密度组织才可能达到该量级，与本题μ仅略高于水不符。", "tr": "公式分母永远是水的衰减系数，不是被测组织的。另需分清标度常数K：现行CT机K＝1000（Hounsfield标度），早期EMI机曾用K＝500或1000，题目若给出“EMI值”需换算。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0102", "t": "多选题", "s": "关于人体常见组织与介质的CT值，下列描述正确的有", "o": {"A": "水的CT值定义为0 HU，空气约为-1000 HU", "B": "正常肝实质平扫CT值略高于脾脏，两者差值一般在8~10 HU", "C": "脑灰质CT值高于脑白质", "D": "脂肪组织的CT值范围为+30~+50 HU", "E": "骨皮质的CT值上限为+1000 HU，超过该值CT机不能显示"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-102", "kp": "各组织CT值范围", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】A正确：Hounsfield标度以水为0 HU、空气为-1000 HU作两点定标，这是CT值体系的基石。B正确：正常肝实质平扫CT值约50~70 HU，比脾脏高约8~10 HU；若肝脏密度低于脾脏，提示脂肪肝，这是平扫的重要间接判断依据。C正确：脑灰质约32~40 HU、脑白质约25~32 HU，灰质含水量低、密度略高，故灰白质界面可辨。【为什么错】D错误：脂肪为负值组织，CT值约-100~-40 HU；+30~+50 HU接近软组织／肌肉范围。E错误：CT值并无+1000 HU的硬性上限，致密骨皮质可达1000~2000 HU，现代CT的量化范围可扩展至-1024~+3071 HU甚至更宽（扩展标度可到±10000 HU），用于金属与致密骨评价。", "tr": "“肝比脾高8~10 HU”与“脂肪为负值”是平扫判读脂肪肝的两块基石；另注意CT值上限并非1000 HU，扩展CT值范围（extended scale）正是评估金属植入物的手段。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0103", "t": "单选题", "s": "某幅CT图像采用窗宽400 HU、窗位40 HU显示，则该显示条件下能够被分配灰阶、产生密度层次差别的CT值范围是", "o": {"A": "-360~+440 HU", "B": "-160~+240 HU", "C": "-200~+200 HU", "D": "0~+400 HU", "E": "-400~+400 HU"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-103", "kp": "窗宽窗位的换算", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】B正确。窗宽上限＝窗位＋窗宽/2＝40＋200＝240 HU；窗宽下限＝窗位－窗宽/2＝40－200＝-160 HU。高于上限者一律显示为纯白、低于下限者一律显示为纯黑，只有区间内的CT值才被分配灰阶。【为什么错】A错误：把窗宽全值（400）而非半值加减到窗位上。C错误：忽略了窗位40 HU的偏移，把窗中心默认为0。D错误：误把窗位当成显示范围的下限起点。E错误：把窗宽数值当成上下限的绝对值，同样忽略窗位。", "tr": "窗位是显示范围的中心而非下限；计算时务必用窗宽的一半加减。考试中常反向命题：给出显示范围-160~+240 HU，反求窗宽（400）与窗位（40）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0104", "t": "多选题", "s": "关于窗技术中窗宽、窗位与灰阶分配的关系，下列正确的有", "o": {"A": "窗宽减小时每一灰阶所代表的CT值差变小，图像对比度提高，但可显示的CT值范围变窄", "B": "窗位升高时显示范围向高密度侧移动，图像整体变暗；窗位降低则整体变亮", "C": "观察肺组织宜用宽窗，常用窗宽1000~1600 HU、窗位-600~-700 HU", "D": "观察脑实质宜用窗宽300~400 HU、窗位35~45 HU", "E": "窗宽窗位在扫描时即已固定，图像重建完成后不能再更改"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-104", "kp": "窗宽窗位与灰阶分配", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】A正确：若显示器灰阶数固定，每一灰阶代表的CT值差＝窗宽/灰阶数，窗宽越窄该差值越小，微小密度差被放大，对比度提高，代价是超出窗外的组织被“压白／压黑”丢失层次。B正确：窗位决定显示窗口在CT值轴上的位置，窗位升高意味着更多低密度结构落到窗下限之外而变黑，整体观感变暗。C正确：肺内空气与血管、间质密度差极大，需宽窗低窗位，常规肺窗为窗宽1000~1600 HU、窗位-600~-700 HU。【为什么错】D错误：窗宽300~400 HU、窗位30~50 HU是纵隔窗参数；脑窗为窗宽80~100 HU、窗位35~45 HU，脑组织灰白质差别仅约8 HU，必须用窄窗。E错误：窗技术是重建后的后处理显示手段，同一套图像数据可任意反复调节窗宽窗位，甚至打印多套窗；真正在扫描时固定的是采集参数。", "tr": "脑窗（80~100/35~45）与纵隔窗（300~400/30~50）的窗宽极易互换记错；记忆抓手是“脑组织灰白质差仅约8 HU，必须窄窗”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0105", "t": "单选题", "s": "某次扫描使用显示野（FOV）350 mm、重建矩阵512×512、重建层厚5 mm。该图像的像素边长与体素体积分别约为", "o": {"A": "0.68 mm、约2.3 mm³", "B": "0.68 mm、约3.4 mm³", "C": "1.37 mm、约9.4 mm³", "D": "0.34 mm、约0.6 mm³", "E": "0.68 mm、约0.47 mm³"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-105", "kp": "体素、像素与矩阵的关系", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】A正确。像素边长＝FOV/矩阵＝350/512≈0.68 mm；体素是像素在Z轴方向延伸一个层厚所构成的三维单元，体素体积＝像素面积×层厚≈0.68×0.68×5≈2.3 mm³。【为什么错】B错误：3.4 mm³是把像素边长（而非面积）乘层厚（0.68×5）所得，少乘了一个边长。C错误：1.37 mm对应256×256矩阵（350/256），与题设512矩阵不符。D错误：0.34 mm对应1024矩阵。E错误：0.47 mm²只是像素面积（0.68²），未乘层厚，且单位应为mm²。", "tr": "像素是二维（面积），体素是三维（含层厚）；同一FOV下矩阵越大像素越小、空间分辨率越高但噪声越大。另注意“采集矩阵”与“显示矩阵”可以不同，像素尺寸应按重建（采集）矩阵计算。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0106", "t": "单选题", "s": "关于部分容积效应与周围间隙现象，下列叙述错误的是", "o": {"A": "部分容积效应指同一体素内含有两种以上不同密度的组织时，所测CT值为各成分的加权平均值", "B": "减薄扫描层厚可减轻部分容积效应带来的CT值失真", "C": "周围间隙现象表现为密度差别较大的两种组织交界处边缘模糊、交界带CT值不准确", "D": "周围间隙现象与部分容积效应在本质上无关，仅由探测器电子噪声引起", "E": "后颅窝、颅底等骨与脑组织交界层面容易因上述效应造成CT值测量偏差"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-106", "kp": "部分容积效应与周围间隙现象", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】本题选错误项，D错误。周围间隙现象（partial volume edge effect）恰恰是部分容积效应在“组织交界带”上的特殊表现形式：当同一层面内两种密度悬殊的组织并存且界面与扫描平面不垂直时，界面附近体素同时包含两种组织，测得CT值介于两者之间，导致边缘模糊、界面CT值失真。它属于成像几何与体素平均问题，并非探测器电子噪声所致。【为什么错】A正确：这是部分容积效应的标准定义，体素内多种成分按体积比加权平均。B正确：层厚越薄，单个体素内混入异质组织的概率越低，效应减轻，这也是薄层扫描／薄层重建的核心价值。C正确：这是周围间隙现象的典型表述。E正确：后颅窝、颅底骨与脑组织密度差极大，界面走行复杂，最易出现该效应并叠加线束硬化伪影。", "tr": "两者是“同源不同表现”：部分容积效应强调CT值被平均，周围间隙现象强调交界处边缘失真。切勿把周围间隙现象归因于噪声或运动；对策共同点都是减薄层厚。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0107", "t": "单选题", "s": "某16排CT采用16×1.25 mm探测器组合，机架旋转一周时间为0.5 s，检查床进床速度为27.5 mm/s。该扫描的螺距（探测器组合螺距，beam pitch）为", "o": {"A": "0.34", "B": "0.69", "C": "1.10", "D": "1.38", "E": "11.0"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-107", "kp": "多层螺旋CT螺距的计算", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】B正确。多层螺旋CT的螺距（beam pitch）＝机架旋转一周检查床移动距离/（探测器排数×单个探测器宽度，即总准直宽度）。每周进床距离＝27.5 mm/s×0.5 s＝13.75 mm；总准直宽度＝16×1.25＝20 mm；螺距＝13.75/20≈0.69。【为什么错】A错误：0.34系误将旋转时间当作0.25 s计算。C错误：1.10为按12.5 mm准直（10×1.25）计算的结果，排数取错。D错误：1.38系直接用每秒进床距离27.5 mm除以总准直20 mm，漏乘旋转时间。E错误：11.0是层螺距（slice pitch/detector pitch）＝每周进床距离/单个探测器宽度＝13.75/1.25，其数值等于beam pitch的16倍，两者定义不同不可混用。", "tr": "多层CT有两种螺距：探测器组合螺距（分母为总准直宽度，国际通用、也是机器显示值）与层螺距（分母为单层准直宽度，数值＝排数×组合螺距）。见到“11.0”这类远大于1的数值，多半是层螺距而非常用螺距。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0108", "t": "多选题", "s": "关于CT扫描中的准直（collimation）及其影响，下列正确的有", "o": {"A": "准直宽度决定X线束在Z轴方向的宽度，是影响Z轴空间分辨率的重要因素", "B": "缩小准直宽度可减少散射线并减轻部分容积效应", "C": "多层螺旋CT可重建的最薄层厚不能小于单个探测器单元对应的准直宽度", "D": "其他条件不变时，缩小准直宽度可使图像噪声降低", "E": "准直器仅设置在探测器侧，球管侧不需要准直"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-108", "kp": "准直的作用与限制", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】A正确：准直限定X线束沿Z轴的宽度，直接决定层面敏感度曲线（SSP）的宽度，是Z轴分辨率的物理上限。B正确：准直越窄，进入受检体的射线束越窄，散射线产生减少；同时体素在Z轴变薄，异质组织混合减少，部分容积效应减轻。C正确：探测器单元宽度是硬件下限，重建层厚只能等于或大于它（如0.625 mm探测器最薄重建0.625 mm），不可能凭插值“无中生有”出更薄的真实层厚。【为什么错】D错误：方向相反。准直变窄→单个体素接收光子数减少→噪声升高，欲维持噪声水平须相应增加mAs，这正是薄层扫描剂量代价的来源。E错误：CT在球管侧（前准直器，限制射线束宽度与剂量）和探测器侧（后准直器，抑制散射）通常均设准直装置，多层CT尤其重视球管侧的动态准直（如自适应剂量屏蔽减少螺旋两端的过扫描剂量）。", "tr": "“薄层＝低剂量”是常见错觉：薄准直本身并不降低剂量，反而为压制噪声常需提高mAs。Z轴分辨率提高与噪声增加是一对必然的权衡。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0109", "t": "单选题", "s": "关于重建层厚与重建间隔（重建增量）的关系，下列说法错误的是", "o": {"A": "重建间隔小于重建层厚时称为重叠重建", "B": "重叠重建可改善多平面重组与三维重组图像质量、减轻阶梯状伪影", "C": "重叠重建利用同一次采集的原始数据完成，不增加患者的辐射剂量", "D": "重建层厚可以任意设置为小于探测器单元准直宽度的数值", "E": "层厚不变时，仅改变重建间隔不会改变单幅图像的噪声水平"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-109", "kp": "重建层厚与重建间隔", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】本题选错误项，D错误。重建层厚受探测器单元宽度这一硬件条件限制，最薄只能等于单排探测器对应的准直宽度，不能任意变薄；能自由设定的是重建间隔。【为什么错】A正确：重建间隔＜层厚即为重叠重建，常用重叠量为层厚的30%~50%。B正确：重叠重建使Z轴采样更密，MPR/VR/CPR的连续性更好，可显著减轻楼梯状（阶梯）伪影，是三维后处理与血管成像的常规做法。C正确：重叠重建只是对已采集的原始数据以更小间隔再次插值重建，射线曝光已经结束，不增加任何辐射剂量，仅增加图像数量与存储／传输负荷。E正确：噪声主要由层厚、mAs、kV、卷积核和算法决定，与相邻图像间的排列间隔无关。", "tr": "牢记“重叠重建不增加剂量、只增加图像数量”；而减薄重建层厚虽然也不增加已完成扫描的剂量，却会提高噪声。二者的代价不同，勿混。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0110", "t": "多选题", "s": "关于CT重建中卷积核（重建算法）的选择，下列正确的有", "o": {"A": "软组织核（平滑核）图像噪声低、密度分辨率好，适用于脑实质和纵隔观察", "B": "骨核（高分辨率核）使边缘锐利、空间分辨率提高，但图像噪声明显增大", "C": "同一次采集的原始数据可用不同卷积核重建出多套图像，无须重复扫描、不增加辐射剂量", "D": "观察肺间质细微结构应选用软组织核以降低噪声", "E": "观察肝内小的低密度病灶宜选用骨核以提高检出率"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-110", "kp": "卷积核与重建算法选择", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】A正确：软组织核对高频成分做抑制（平滑），噪声低、密度分辨率（低对比分辨率）好，适合脑实质、纵隔、肝脾等低对比结构。B正确：骨核强化高频，边缘锐利、空间分辨率高，代价是噪声显著上升，适用于骨皮质、内耳、肺间质等高对比结构。C正确：卷积核作用于原始投影数据的重建过程，只要保留原始数据即可反复用不同核重建，剂量不变——这正是“一次扫描、多套重建”的技术基础，如颞骨同时出骨算法与软组织算法。【为什么错】D错误：肺间质属于高对比结构，必须用高分辨率（肺/骨）核，用软组织核会使小叶间隔、支气管壁模糊，是HRCT的原则性错误。E错误：肝内小低密度灶是典型的低对比病变，骨核带来的高噪声会淹没微弱密度差，反而降低检出率，应选软组织核甚至更平滑的核。", "tr": "口诀：高对比结构（骨、肺、内耳）用锐利核，低对比结构（脑、肝、纵隔软组织）用平滑核。核的选择改变的是“噪声—空间分辨率”的分配，而不是采集到的信息量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U09-0111", "t": "单选题", "s": "某腹部CT图像噪声偏大，拟在管电压、层厚、卷积核等其他条件均不变的前提下，将图像噪声（标准差）降至原来的1/2，管电流时间积（mAs）应调整为原来的", "o": {"A": "1/4", "B": "1/2", "C": "2倍", "D": "4倍", "E": "8倍"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-111", "kp": "噪声与mAs的平方根关系", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】D正确。CT图像噪声源于光子统计涨落，噪声标准差σ与探测到的光子数N的平方根成反比，而N正比于mAs，故σ∝1/√mAs。欲使σ降为原来的1/2，需要√mAs增大2倍，即mAs增至原来的4倍（同时患者剂量也增至4倍）。【为什么错】A错误：mAs降至1/4会使噪声增大到原来的2倍，方向完全相反。B错误：mAs减半噪声反而升高约1.41倍。C错误：mAs加倍只能使噪声降至原来的约0.71倍（1/√2），达不到减半。E错误：8倍mAs可使噪声降至约0.35倍，超出需求且剂量代价过大，不符合ALARA原则。", "tr": "记住“噪声减半＝剂量四倍”这一昂贵关系，这正是迭代重建与深度学习重建的价值所在——在不增加mAs的前提下降低噪声。另注意噪声与层厚也呈平方根关系（层厚减半，噪声增至1.41倍）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0112", "t": "案例分析题", "s": "患者男性，58岁，因不典型胸痛行冠状动脉CTA。检查前心率72次/分，口服美托洛尔后降至62次/分，但心律不齐、偶发室性早搏。技师采用回顾性心电门控螺旋方式完成采集，对比剂与盐水双筒注射，图像强化满意。重建后发现右冠状动脉中段在多个期相均出现明显的错层（阶梯状）伪影，回放心电曲线可见扫描过程中出现2次室性早搏及其后的代偿间歇，早搏处的R波标记位置与实际心动周期不匹配。在不追加扫描的前提下，此时最合适的技术处理是", "o": {"A": "使用心电编辑功能，对早搏及代偿间歇处错误的R波标记进行删除或位移后重新标记，再分别在收缩末期（约40%）与舒张中晚期（约75%）重建择优", "B": "立即重新扫描一次，并将重建期相固定于R-R间期0%以避开早搏", "C": "改用平滑卷积核并加大迭代重建强度，以掩盖错层伪影", "D": "将原始数据改按前瞻性心电触发方式重建，可自动纠正早搏造成的期相错位", "E": "把重建期相统一改为R-R间期10%，该期相不受心律变化影响"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-112", "kp": "心电编辑与最佳重建期相", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】A正确。回顾性门控的最大优势是原始数据覆盖整个心动周期，可在重建阶段做心电编辑：常用手段包括删除（disable/delete）早搏处的错误R波、插入（insert）漏检的R波、位移（shift/relabel）标记位置以及禁用某段异常心搏数据。将早搏与代偿间歇的标记纠正后，各扇区数据才能落在同一真实心动时相，错层伪影可显著减轻；再在收缩末期35%~45%与舒张中晚期70%~80%两个相对静止窗分别重建择优，是标准处理流程。【为什么错】B错误：先做心电编辑属零剂量补救，未尝试即重扫违背ALARA；且R-R间期0%正处于R波顶点、心脏运动剧烈，不是静止期。C错误：平滑核和迭代重建只能降噪，对运动错层这类数据不一致性伪影无效，反而模糊血管边缘。D错误：前瞻性触发是采集时的曝光策略，一旦扫描完成不能“改按”前瞻方式重建；而且前瞻性触发对早搏更敏感，本身需要靠自动早搏抑制／补扫功能应对。E错误：不存在“不受心律影响”的期相，10%时相处于等容收缩期，冠脉运动幅度大，是最差选择之一。", "tr": "心电编辑只能在回顾性门控（全期相原始数据）上施行，前瞻性触发扫描无数据可编辑。另记两个静止窗：低心率取舒张中晚期70%~80%，高心率／心律不齐时收缩末期35%~45%常更可靠（尤其右冠）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0113", "t": "单选题", "s": "关于CT平扫的概念，下列描述正确的是", "o": {"A": "平扫是指不注射对比剂的常规CT扫描，又称普通扫描或非增强扫描", "B": "平扫是指仅使用低剂量参数完成的扫描", "C": "平扫只能采用轴位逐层（非螺旋）方式采集", "D": "平扫图像因未使用对比剂，不能进行CT值测量", "E": "平扫必须安排在增强扫描之后完成"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-113", "kp": "CT平扫的概念", "ch": "九、CT检查技术 → 2.检查方法 → (1)平扫", "ex": "【为什么对】A正确。平扫（plain scan）指不注射血管内对比剂、按预定参数直接完成的扫描，亦称普通扫描、非增强扫描，是绝大多数CT检查的第一步和增强扫描的对照基准。【为什么错】B错误：低剂量扫描是剂量策略（如肺癌筛查LDCT），与用不用对比剂无关，低剂量增强同样存在。C错误：平扫既可轴位逐层采集，也可螺旋容积采集，现代多层CT平扫多用螺旋方式以便薄层重建。D错误：平扫恰恰是CT值测量最重要的基线，脂肪肝、血肿、结石、钙化、脂肪成分（如AML）的判断都依赖平扫CT值。E错误：顺序相反，常规是先平扫、后增强，平扫为增强提供对照并帮助确定扫描范围与时相；仅在个别急诊CTA等情形下可省略平扫。", "tr": "腹部平扫前常口服水或稀释对比剂充盈胃肠道，这仍属平扫范畴——“平扫”特指未经血管内注射对比剂，勿因口服阴性／阳性对比剂而误判为增强。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0114", "t": "多选题", "s": "下列临床情况中，CT平扫即可基本满足首要临床需求的有", "o": {"A": "急性颅脑外伤，需排除颅内血肿", "B": "急性腰腹绞痛，需排除输尿管结石", "C": "胸部外伤，需明确有无肋骨骨折与气胸", "D": "肝内发现小占位，需要定性诊断", "E": "颈部肿块，需评估病变与颈动脉的关系"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-114", "kp": "CT平扫的适应证与局限", "ch": "九、CT检查技术 → 2.检查方法 → (1)平扫", "ex": "【为什么对】A正确：急性期血肿因血红蛋白浓聚呈高密度（约60~80 HU），与脑实质天然对比良好，平扫即可诊断，且急诊快速、无对比剂风险。B正确：绝大多数尿路结石为高密度，平扫（低剂量泌尿系CT）敏感性极高，注射对比剂后反而会因肾盂内对比剂遮蔽结石。C正确：骨折与气胸依赖骨窗、肺窗的高对比显示，平扫即可，增强对此无额外价值。【为什么错】D错误：肝内小占位的定性依赖多期增强的强化方式（如肝细胞癌“快进快出”、血管瘤渐进性向心填充），平扫只能发现病灶、难以定性。E错误：颈部肿块与颈动脉、颈内静脉的关系需要血管强化后才能清晰分界，平扫时血管与肿块及淋巴结均为相近的软组织密度，难以区分。", "tr": "判断能否只做平扫的思路是“病变与背景之间是否已有足够的天然密度差”：出血、钙化、结石、脂肪、骨与气体属天然高对比，可平扫；等密度软组织病变与血管的鉴别必须增强。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0115", "t": "案例分析题", "s": "患者男性，34岁，高处坠落伤后1小时急诊就诊，意识模糊，GCS评分11分，枕部头皮血肿，生命体征平稳，颈托固定中。急诊要求快速排除颅内出血与颅骨骨折，设备为64排CT。以下检查方案中最合适的是", "o": {"A": "行头颅CT平扫，范围自枕骨大孔（颅底）至颅顶，薄层螺旋采集后同时以软组织核和骨核重建，并加做冠状面、矢状面重组", "B": "行头颅CT增强扫描，利用血管强化提高出血检出率", "C": "行头颅CT平扫，层厚10 mm逐层采集，只做软组织核重建", "D": "先行头颅CT灌注成像，判断有无缺血半暗带后再决定是否平扫", "E": "先行颅脑MRI以避免电离辐射，CT留待复查时进行"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-115", "kp": "急诊颅脑外伤平扫方案", "ch": "九、CT检查技术 → 2.检查方法 → (1)平扫", "ex": "【为什么对】A正确。急性颅脑外伤的首选是平扫：急性血肿呈高密度，无需对比剂；薄层螺旋采集可在不增加剂量的前提下用同一原始数据分别以软组织核（观察脑实质、血肿）和骨核（观察颅骨骨折、颅底与鼻窦积液）重建，并做冠状／矢状重组，能显著提高与扫描平面平行的线性骨折和薄层硬膜下血肿的检出率；范围应包全颅底至颅顶，避免漏诊后颅窝与颅顶凸面病变。【为什么错】B错误：增强对急性出血的检出无帮助，反而可能使强化血管与小血肿混淆，且外伤急诊使用对比剂增加不必要风险。C错误：10 mm厚层容易漏诊薄层硬膜下血肿与颅底骨折，且无骨算法重建不利于骨折评价。D错误：CT灌注用于缺血性卒中评估，不是外伤首选，且剂量高、耗时长，延误抢救。E错误：MRI检查时间长、急诊可及性差、对急性出血与骨折的显示不如CT，且躁动患者难以配合，不适合作为外伤首查。", "tr": "“一次薄层采集、双核重建、多平面重组”是现代颅脑外伤的标准动作，能零剂量代价提高骨折检出。注意不要为了看骨折而追加一次骨算法扫描——只需重建，不需重扫。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0116", "t": "案例分析题", "s": "患者女性，52岁，常规胸部CT（层厚5 mm）发现右肺上叶一枚约8 mm的磨玻璃结节，临床需进一步评价其内部结构（有无实性成分、空泡征、胸膜牵拉及与血管的关系），设备为64排CT。以下技术方案最合适的是", "o": {"A": "对结节所在区域行小FOV靶扫描或靶重建，采用≤1 mm薄层、高分辨率算法，并行MPR与最小密度投影观察", "B": "把原有5 mm层厚图像在工作站上电子放大4倍后观察", "C": "追加胸部增强扫描门静脉期成像以评价结节强化", "D": "把螺距增大至1.5并改用平滑核重建，以降低噪声、突出结节", "E": "行胸部CT灌注成像定量评价结节血供"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-116", "kp": "靶扫描与靶重建", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】A正确。靶扫描（放大扫描）／靶重建的实质是缩小显示野，在矩阵不变的前提下使像素边长变小（像素＝FOV/矩阵），从而真正提高空间分辨率；配合≤1 mm薄层与高分辨率算法，可清晰显示磨玻璃结节内的实性成分、空泡、支气管充气征与胸膜牵拉，MPR和MinIP有助于判断与血管、胸膜的关系。【为什么错】B错误：工作站电子放大只是把已有像素等比放大，信息量不增加，只会出现马赛克样放大伪影，与靶重建有本质区别。C错误：门静脉期时相针对腹部脏器，对肺小结节评价无意义；且8 mm磨玻璃结节的强化测量不可靠，指南推荐以薄层随访和体积测量为主。D错误：增大螺距会降低Z轴采样密度、加重层面敏感度曲线增宽，平滑核进一步降低空间分辨率，与需求背道而驰。E错误：CT灌注辐射剂量高，主要用于脑卒中与部分肿瘤血流动力学研究，对8 mm磨玻璃结节既不必要也不可靠。", "tr": "务必区分“靶重建（缩小FOV重建，像素变小、分辨率真提高）”与“图像放大（后处理插值，分辨率不变）”。靶重建可用原始数据完成，不需要再次曝光；只有需要改变采集几何时才做真正的靶扫描。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0117", "t": "单选题", "s": "关于CT薄层扫描（薄层采集与薄层重建），下列描述正确的是", "o": {"A": "薄层的主要目的是减轻部分容积效应、提高Z轴分辨率，有利于小病灶与细微结构的显示", "B": "薄层扫描在其他参数不变时可同时降低图像噪声和辐射剂量", "C": "薄层只能通过缩小显示野实现", "D": "薄层图像不适合用于多平面重组和三维后处理", "E": "薄层扫描的层厚通常指相邻两层图像中心之间的距离"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-117", "kp": "薄层扫描技术", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】A正确。薄层的核心价值在于缩小体素的Z轴尺寸，减少同一体素内异质组织的混合，从而减轻部分容积效应、提高Z轴空间分辨率，使小结节、微小骨折、内耳与垂体等细微结构得以显示。【为什么错】B错误：层厚减薄使单个体素接收光子数减少，噪声按1/√层厚规律升高；欲维持噪声水平需提高mAs，剂量不降反升。C错误：缩小显示野改变的是层面内（XY方向）的像素大小，属靶重建范畴；层厚由准直宽度与重建层厚决定，二者不是一回事。D错误：恰恰相反，薄层（各向同性体素）是高质量MPR、VR、CPR后处理的前提，厚层重组会产生明显阶梯状伪影。E错误：相邻图像中心间的距离是重建间隔（重建增量），层厚指单幅图像所代表的Z轴厚度，二者可以不相等（重叠重建时间隔＜层厚）。", "tr": "薄层降低的是部分容积效应，不是噪声；层厚与重建间隔是两个独立参数，命题常在此互换设陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0118", "t": "多选题", "s": "关于胸部高分辨率CT（HRCT）的技术要点，下列正确的有", "o": {"A": "采用薄层（一般1~1.5 mm）与高空间分辨率（骨/肺）算法重建", "B": "适当缩小显示野做靶重建，可进一步提高细微结构的显示能力", "C": "怀疑小气道病变时可加扫呼气末图像，用以显示空气潴留", "D": "为鉴别肺底坠积效应与早期间质纤维化，可加扫俯卧位图像", "E": "为降低噪声，HRCT应选用软组织平滑核并适当增大层厚"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-118", "kp": "高分辨率CT（HRCT）技术", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】A正确：HRCT的两大支柱就是薄层（1~1.5 mm）与高分辨率算法，用于显示小叶间隔、小叶核心、支气管壁等亚毫米级结构。B正确：靶重建缩小FOV使像素变小，在矩阵不变时空间分辨率进一步提高，常用于单侧肺或局部病灶精查。C正确：呼气末扫描时正常肺组织密度升高，而小气道阻塞区因空气潴留密度不升，出现“马赛克”样密度差，是诊断闭塞性细支气管炎的关键征象。D正确：仰卧位肺底后部的坠积性密度增高在俯卧位可消散，而真正的间质病变（如早期特发性肺纤维化的胸膜下网格影）不随体位改变，这是HRCT的经典鉴别手段。【为什么错】E错误：肺属于高对比结构，必须用高分辨率锐利核；改用平滑核并加大层厚会使小叶间隔与细支气管壁模糊，从根本上破坏HRCT的目的。噪声偏大在HRCT中是可接受的代价，必要时通过提高mAs或迭代重建解决。", "tr": "HRCT是“高分辨率”而非“低噪声”的技术，任何以降噪为名改用平滑核、加厚层厚的做法都是错的。另注意呼气相与俯卧位是两个不同目的的附加体位，不可混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U09-0119", "t": "单选题", "s": "某成人胸部CT扫描后机器显示剂量长度乘积（DLP）为250 mGy·cm，已知成人胸部的有效剂量转换因子k约为0.014 mSv/(mGy·cm)。该次检查的有效剂量约为", "o": {"A": "0.35 mSv", "B": "1.75 mSv", "C": "3.5 mSv", "D": "17.9 mSv", "E": "35 mSv"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-119", "kp": "CT剂量指标与有效剂量估算", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】C正确。有效剂量E（mSv）≈DLP（mGy·cm）×k，k为与解剖部位相关的转换因子。250×0.014＝3.5 mSv。【为什么错】A错误：0.35 mSv系小数点错位（按0.0014计算）。B错误：1.75 mSv相当于把DLP误取为125 mGy·cm。D错误：17.9 mSv是用250除以14所得，属公式误用。E错误：35 mSv是把k误当作0.14，量级偏大10倍，已接近介入手术的剂量水平，与常规胸部CT不符。", "tr": "分清三个剂量指标：CTDIvol（mGy，反映扫描层面的剂量强度）、DLP＝CTDIvol×扫描长度（mGy·cm，反映总受照量）、有效剂量E＝DLP×k（mSv，反映随机性效应风险）。k值随部位变化（头部约0.0021、胸部约0.014、腹盆约0.015），儿童更高。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0120", "t": "单选题", "s": "关于延迟扫描与动态扫描，下列说法错误的是", "o": {"A": "延迟扫描指在常规增强各期结束后，间隔数分钟乃至更长时间再进行的扫描", "B": "肝血管瘤的“渐进性向心填充”常需延迟5~10分钟甚至更久才能显示完全充填", "C": "CT尿路造影的排泄期属于延迟扫描的应用之一", "D": "动态扫描是指在对比剂注射后对同一或多个层面进行的连续、多次重复扫描，可获得时间-密度曲线", "E": "动态扫描与延迟扫描含义相同，只是名称不同"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-120", "kp": "延迟扫描与动态扫描", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】本题选错误项，E错误。二者概念不同：动态扫描强调“短时间内高频率重复采集”，用于观察对比剂首过与early强化动力学、绘制时间-密度曲线（如垂体微腺瘤动态增强、CT灌注）；延迟扫描强调“延后单次或数次采集”，用于观察对比剂缓慢充填或经泌尿道／胆道排泄的过程。【为什么错】A正确：这是延迟扫描的定义，延迟时间从数分钟到十余分钟不等。B正确：血管瘤延迟填充是其定性依据，延迟不足是误诊为乏血供转移瘤的常见原因。C正确：CTU排泄期通常在注药后5~10分钟采集，正是延迟扫描的典型应用。D正确：动态扫描含同层动态与进床式动态两种方式，是获取TDC与灌注参数的基础。", "tr": "“动态＝快而密（看流入）”，“延迟＝慢而晚（看填充与排泄）”。垂体、肾上腺、血管瘤三类病变常同时用到动态与延迟，答题时须按临床目的判断。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0121", "t": "单选题", "s": "患者体重70 kg，腹部增强CT按1.5 ml/kg给药，选用碘浓度350 mgI/ml的非离子型对比剂。该患者的对比剂用量与所注入的碘总量分别约为", "o": {"A": "70 ml、24.5 gI", "B": "105 ml、36.8 gI", "C": "105 ml、3.68 gI", "D": "140 ml、49.0 gI", "E": "105 ml、368 gI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-121", "kp": "对比剂总量与碘总量计算", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】B正确。对比剂体积＝1.5 ml/kg×70 kg＝105 ml；碘总量＝体积×浓度＝105 ml×350 mgI/ml＝36750 mgI≈36.8 gI。【为什么错】A错误：按1.0 ml/kg计算得70 ml，与题设剂量方案不符。C错误：3.68 gI是单位换算错误（少除或多除1000），105 ml×350 mgI/ml不可能只有3.68 g碘。D错误：140 ml相当于2.0 ml/kg，超出题设方案。E错误：368 gI量级错误，如此碘量远超人体安全上限（成人单次碘负荷一般不宜超过约1.5 gI/kg，本例上限约105 gI，而实际给药36.8 gI）。", "tr": "碘总量＝体积（ml）×浓度（mgI/ml）÷1000（gI）。评价对比剂负荷时应关注“碘总量／体重”而不仅是毫升数，同样100 ml，370 mgI/ml比300 mgI/ml多输入约7 g碘。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0122", "t": "单选题", "s": "某冠状动脉CTA方案使用碘浓度370 mgI/ml的对比剂、注射流率5.0 ml/s。因患者外周静脉条件差，改用碘浓度300 mgI/ml的对比剂，若要维持原方案的碘流率不变，注射流率应调整为", "o": {"A": "约4.1 ml/s", "B": "约5.0 ml/s", "C": "约6.2 ml/s", "D": "约7.4 ml/s", "E": "约1.85 ml/s"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-122", "kp": "碘流率概念与换算", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】C正确。碘流率（iodine delivery rate）＝碘浓度（mgI/ml）×注射流率（ml/s），是决定血管内峰值强化程度的关键量。原方案碘流率＝370×5.0＝1850 mgI/s＝1.85 gI/s；改用300 mgI/ml后，所需流率＝1850/300≈6.2 ml/s。【为什么错】A错误：4.1 ml/s是按5.0×300/370反向换算，方向搞反，会使碘流率下降。B错误：单纯保持5.0 ml/s时碘流率降至1500 mgI/s，血管强化明显下降，不能满足冠脉CTA对峰值CT值（通常要求≥300 HU）的要求。D错误：7.4 ml/s对应碘流率2220 mgI/s，高于原方案，且外周静脉难以承受，增加渗漏风险。E错误：1.85 ml/s是把碘流率的数值（1.85 gI/s）误当成体积流率。", "tr": "降低浓度必须提高流率才能维持碘流率——但患者的静脉条件是硬约束。当流率无法提高时，可改用低管电压（如80~100 kVp）提高碘的对比效率来代偿，这是低剂量、低碘负荷方案的核心思路。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0123", "t": "多选题", "s": "关于增强扫描中使用生理盐水“后推”（盐水冲刷）技术，下列正确的有", "o": {"A": "可把停留在上肢静脉、锁骨下静脉内的对比剂推入中心循环，提高对比剂利用率", "B": "有助于减少上腔静脉内高浓度对比剂造成的线束硬化伪影", "C": "可使团注更加紧凑，在总量减少的情况下维持相近的强化峰值", "D": "需要使用双筒（双头）高压注射器，或在单筒注射后手动推注", "E": "盐水后推的主要作用是稀释血液中的对比剂，从而降低对比剂肾病的发生率"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-123", "kp": "生理盐水后推技术", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】A正确：一次注射中约有20~30 ml对比剂滞留在上肢与中心静脉通路内，盐水将其“推”入循环，等效于增加了有效剂量。B正确：上腔静脉、头臂静脉内高浓度对比剂是胸部CTA和冠脉CTA中条纹状硬化伪影的主要来源，盐水冲刷可稀释并置换之，改善右心与右冠近段的显示。C正确：盐水维持了团注柱的连续性，减少团注尾部拖尾，故可在减少10%~20%用量的同时保持峰值强化，这是低碘负荷方案的基础。D正确：临床通过双筒高压注射器实现自动化盐水冲刷，条件不具备时可人工序贯推注，但同步性差。【为什么错】E错误：盐水后推的作用是流体动力学层面的，其量（20~40 ml）不足以显著稀释体循环，也未被证实能降低对比剂肾病发生率；预防对比剂肾病依靠的是控制碘负荷、充分水化和高危人群筛查。", "tr": "把盐水冲刷的“减伪影、省用量”作用与“防肾病”混为一谈是常见错误。真正减少肾脏碘负荷的是降低总碘量本身，而不是随后的几十毫升盐水。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U09-0124", "t": "单选题", "s": "关于团注追踪技术（bolus tracking）的操作要点，下列说法错误的是", "o": {"A": "监测层面的ROI应置于目标血管腔内，避开管壁、钙化斑块与周围结构", "B": "触发阈值常设定在100~150 HU，达到阈值后系统自动或由技师手动启动诊断性扫描", "C": "从触发到正式扫描开始之间存在数秒的诊断延迟，用于床位移动与呼吸指令", "D": "监测扫描应使用与诊断扫描相同的管电流，以保证监测图像质量", "E": "监测过程中若患者呼吸移动导致ROI偏离血管腔，可能出现触发失败或提前触发"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-124", "kp": "团注追踪技术", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】本题选错误项，D错误。监测扫描（同层重复曝光）只用于观察ROI内CT值的变化趋势，不需要诊断级图像质量，必须使用很低的管电流（通常仅为诊断扫描的1/10左右，如20~50 mAs）并适当延长采样间隔，否则累积剂量相当可观。【为什么错】A正确：ROI必须完全落在血管腔内，压到管壁或钙化会使测得CT值偏高而提前触发。B正确：不同部位阈值略有差异（如冠脉／主动脉常用100 HU左右，头颈CTA常用100 HU），达到阈值即触发。C正确：诊断延迟包含床移动、语音呼吸指令与曝光准备时间，一般3~8 s，是决定扫描时相是否准确的关键参数，冠脉与肺动脉方案会尽量压缩该延迟。E正确：呼吸或体动使ROI移出血管是触发失败的常见原因，故监测期间应先完成呼吸指令、并由技师全程盯守以便随时手动触发。", "tr": "团注追踪的三要素：ROI位置、阈值、诊断延迟。监测扫描务必低剂量；同时技师必须准备好“手动触发”作为自动触发失败时的补救，这是实践中最重要的应急动作。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0125", "t": "多选题", "s": "关于团注追踪（bolus tracking）与小剂量测试（test bolus）两种时相确定方法的比较，下列正确的有", "o": {"A": "小剂量测试先注射10~20 ml对比剂并在同一层面低剂量动态采集，取时间-密度曲线峰值时间来推算扫描延迟", "B": "团注追踪不需额外注射对比剂，可实时反映本次团注的循环状态", "C": "小剂量测试会额外增加对比剂用量和辐射剂量，检查时间延长", "D": "对心功能不全、循环时间明显异常或大动脉瘤样扩张的患者，小剂量测试往往更能获得可靠的个体化延迟时间", "E": "团注追踪的准确性不受心律不齐、呼吸配合和ROI放置的影响"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-125", "kp": "团注追踪与小剂量测试的比较", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】A正确：test bolus用小剂量“预演”循环，测出对比剂自注射至目标血管的达峰时间，再据此设定正式扫描延迟，可精确到秒级。B正确：bolus tracking在正式团注的同时实时监测，反映的就是本次注射的真实循环状态，无须额外用药。C正确：小剂量测试需多注射10~20 ml对比剂，并增加一段低剂量监测扫描与操作时间，是其主要代价。D正确：心排量低、房颤、巨大动脉瘤或血栓形成的患者，对比剂到达时间与峰值形态个体差异极大，阈值触发容易过早或过晚，此时用test bolus获得实测峰值时间更稳妥；一些冠脉方案也用其规避低心排导致的强化不足。【为什么错】E错误：团注追踪高度依赖ROI放置准确、患者屏气配合与呼吸位置稳定，心律不齐、体动、ROI压到管壁或血栓均可导致触发失败或错误触发，因此必须准备手动触发预案。", "tr": "两法核心区别：test bolus测的是“时间”（用小剂量预演），bolus tracking测的是“浓度”（等到阈值就扫）。前者精准但费药费时，后者快捷但受触发条件影响，二者并非优劣关系而是适应人群不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U09-0126", "t": "案例分析题", "s": "患者男性，62岁，体重80 kg，行上腹部增强CT评价肝脏病变。技师使用碘浓度300 mgI/ml对比剂100 ml，注射流率2.5 ml/s，采用固定延迟法在注药后30 s、70 s采集动脉期与门静脉期。图像显示动脉期腹主动脉及肝动脉强化程度偏低，肝实质动脉期强化不足，影响富血供小病灶的检出。在总碘量不变的前提下，下列改进措施中最合理的是", "o": {"A": "提高注射流率至4.0~5.0 ml/s，缩短注射时间以提高峰值强化，并改用团注追踪确定动脉期时相", "B": "把注射流率降至1.5 ml/s，延长注射时间以使强化更加平稳", "C": "把动脉期延迟固定改为45 s，其余方案不变", "D": "改用高浓度对比剂同时把流率降至2.0 ml/s，以保证患者安全", "E": "增大扫描层厚并改用平滑核，以提高图像信噪比来弥补强化不足"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-126", "kp": "注射流率与强化峰值的关系", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】A正确。在总碘量固定时，血管内峰值强化主要由碘流率（浓度×流率）决定：提高流率使单位时间进入循环的碘量增加，峰值强化升高、达峰时间提前，团注更紧凑，动脉期对比更佳；同时因达峰提前，固定30 s延迟不再适用，应改用团注追踪（腹主动脉ROI，阈值约100 HU）个体化触发。【为什么错】B错误：降低流率使碘流率进一步下降，峰值强化更低，动脉期显示更差，只适用于需要长时间平稳强化的特殊场景。C错误：单纯延后到45 s并未提高峰值强化，反而可能错过动脉晚期最佳窗口，进入肝实质开始强化的阶段。D错误：提高浓度同时降低流率，碘流率可能不升反降（300×2.5＝750 vs 370×2.0＝740 mgI/s），并未解决问题。E错误：加厚层厚、平滑核只改善噪声，不能提高血管与病灶间的碘对比，且牺牲了小病灶检出所需的空间分辨率。", "tr": "血管峰值强化看“碘流率”，实质（肝、脾）总体强化程度更取决于“碘总量/体重”。改善动脉期靠提高流率＋精准触发，改善肝实质强化靠增加总碘量或降低kV。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0127", "t": "案例分析题", "s": "患者女性，68岁，体重95 kg，2型糖尿病，长期口服二甲双胍，血肌酐轻度升高，估算肾小球滤过率（eGFR）为45 ml/(min·1.73 m²)。临床申请腹部增强CT以排查胰腺占位。患者一般情况尚可，外周静脉通路为右肘正中静脉20 G留置针。下列检查方案中最合理的是", "o": {"A": "选用低渗（次高渗）或等渗非离子型碘对比剂，按体重计算但控制碘总量，采用低管电压（80~100 kVp）配合迭代重建以在减少碘负荷的同时保证强化，检查前后适当水化，并按规范评估二甲双胍的停用与复查", "B": "因eGFR低于60，绝对禁忌使用碘对比剂，改行腹部平扫加超声随访", "C": "按体重上限给足对比剂并提高至6 ml/s快速注射，以保证胰腺期强化", "D": "改用离子型高渗对比剂，其价格低、显影浓度高，适合肥胖患者", "E": "检查前常规做碘过敏试验，阴性者按常规剂量注射即可，无须其他处理"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-127", "kp": "肾功能减退与肥胖患者的增强方案", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】A正确。该患者兼有肥胖（衰减大、需要更高强化）和肾功能中度减退（需要限制碘负荷）两个相互矛盾的需求，解决之道是“降kV提效率”：管电压降至80~100 kVp后，X线平均能量更接近碘的K缘（33.2 keV），碘的对比效率显著提高，可在减少10%~30%碘量的前提下获得同等甚至更高的强化，噪声上升由迭代重建代偿；同时选用低渗或等渗非离子型对比剂、控制总碘量、检查前后水化，并按规范处理二甲双胍。【为什么错】B错误：eGFR 45并非碘对比剂的绝对禁忌，一般以eGFR＜30 ml/(min·1.73 m²)或急性肾损伤为高危界限，30~44之间需权衡获益与风险并加强防护，不应一概拒检而延误肿瘤诊断。C错误：既超量增加碘负荷又用6 ml/s的高流率，20 G留置针与老年血管难以承受，渗漏风险高。D错误：离子型高渗对比剂不良反应率与肾毒性风险均高于非离子型低渗对比剂，现已不推荐用于静脉增强，尤其是肾功能不全者。E错误：碘过敏试验不能预测过敏样反应、已不推荐常规进行；且本例的核心风险是对比剂肾病与二甲双胍相关问题，不是靠皮试能解决的。", "tr": "肥胖＋肾功能减退的最佳解法是“低kV＋迭代重建”，而不是简单加量或直接拒检。二甲双胍本身不损肾，风险在于肾功能急性恶化时可能诱发乳酸酸中毒，故按eGFR分层决定是否停药与复查，而非一律停用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0128", "t": "单选题", "s": "关于CT灌注成像的基本参数，下列关系式正确的是", "o": {"A": "CBF＝CBV×MTT", "B": "CBF＝CBV/MTT", "C": "CBV＝CBF×TTP", "D": "MTT＝CBF×CBV", "E": "CBV＝MTT/CBF"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-128", "kp": "CT灌注参数间的关系", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】B正确。依据中心容积定理（central volume principle）：CBF＝CBV/MTT，即脑血流量等于脑血容量除以平均通过时间。CBV单位为ml/100 g，MTT单位为s，CBF单位为ml/(100 g·min)（需做时间单位换算）。这一关系是理解卒中灌注异常的核心：血管狭窄早期MTT延长而CBV靠侧支与自动调节代偿性维持或轻度升高，CBF轻度下降；一旦失代偿，CBV随之下降，提示不可逆梗死。【为什么错】A错误：把除法写成乘法，量纲不成立。C错误：TTP是达峰时间，不能与CBF相乘得到CBV，且TTP不属于中心容积定理的构成量。D错误：MTT不是CBF与CBV的乘积，量纲同样不成立。E错误：把公式上下颠倒，与B互为倒数关系。", "tr": "记忆抓手：MTT＝CBV/CBF（时间＝容积/流量），把常识中的“容积÷流量＝时间”套进去即可，无需死背。TTP、Tmax属于时间类参数，但并不进入该定理公式。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0129", "t": "多选题", "s": "关于急性缺血性卒中CT灌注对核心梗死区与缺血半暗带的判读，下列正确的有", "o": {"A": "核心梗死区常以相对脑血流量（rCBF）低于对侧镜像区30%的体积来估算", "B": "低灌注区常以Tmax＞6 s的体积来界定，缺血半暗带≈Tmax＞6 s体积减去核心梗死体积", "C": "错配比值（低灌注体积/核心体积）越大、核心体积越小，提示可挽救脑组织越多", "D": "核心梗死区的典型表现是CBF与CBV均明显下降、MTT延长", "E": "半暗带的典型表现是CBF明显升高、CBV下降、MTT缩短"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-129", "kp": "核心梗死区与缺血半暗带的灌注判读", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】A正确：目前自动化后处理软件普遍以rCBF＜30%对侧作为核心梗死的替代阈值。B正确：Tmax＞6 s被用于界定严重低灌注（危险）组织，二者相减即为错配（mismatch）区，也就是通常所说的缺血半暗带。C正确：错配比值大、核心小意味着可挽救组织比例高，是延长时间窗内血管内治疗筛选的重要影像学依据。D正确：核心区自动调节完全失代偿，CBF与CBV同步下降、MTT明显延长，是不可逆损伤的灌注特征。【为什么错】E错误：描述完全颠倒。半暗带的典型模式是MTT/Tmax延长、CBF中度下降，而CBV因侧支循环与血管扩张代偿保持正常或轻度升高——即“CBF-CBV不匹配”。CBF升高、MTT缩短反而见于再灌注后的过度灌注状态。", "tr": "核心与半暗带的鉴别点在CBV：CBV也降＝核心（不可逆），CBV保留＝半暗带（可挽救）。切勿把“MTT延长”单独当作梗死依据，它只提示灌注压下降。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U09-0130", "t": "单选题", "s": "关于CT灌注中TTP与Tmax两个时间参数，下列描述正确的是", "o": {"A": "TTP指组织时间-密度曲线达到峰值的时间，Tmax指去卷积计算后残留函数达到峰值的时间，主要反映对比剂到达的延迟", "B": "TTP与Tmax完全等价，可互相替代", "C": "Tmax指扫描持续的最长时间", "D": "TTP值越小提示灌注越差", "E": "Tmax不受近端大血管狭窄或侧支循环状态的影响"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-130", "kp": "TTP与Tmax的含义", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】A正确。TTP（time to peak）直接取自组织的时间-密度曲线，是未经去卷积处理的“表观”达峰时间；Tmax则来自以动脉输入函数去卷积后的残留函数，反映对比剂自动脉输入至该体素的延迟，对侧支代偿状态更敏感，其＞6 s阈值已成为界定严重低灌注组织的通用标准。【为什么错】B错误：二者算法基础不同，TTP受注射方案与心排量影响更大，数值不可互换。C错误：Tmax并非扫描时间，属概念性误解。D错误：方向相反，TTP延长（数值增大）才提示灌注延迟、灌注变差。E错误：Tmax恰恰对近端狭窄和侧支循环高度敏感，侧支良好者对比剂到达延迟且弥散，Tmax延长正是其表现。", "tr": "TTP“看曲线”、Tmax“看去卷积”，两者都是延长提示灌注差。灌注阈值题中，rCBF＜30%对应核心、Tmax＞6 s对应低灌注区，这一组数字要成对记忆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0131", "t": "多选题", "s": "CT灌注成像的辐射剂量明显高于常规扫描，下列属于合理剂量控制措施的有", "o": {"A": "降低管电压至70~80 kVp，在提高碘对比效率的同时降低剂量", "B": "适当降低管电流，并采用迭代重建或深度学习重建控制噪声", "C": "优化采样策略，首过期密集采样、后段延长采样间隔并适时结束采集", "D": "在满足临床需求的前提下限制Z轴覆盖范围，避免不必要的大范围灌注", "E": "为提高参数图信噪比，应尽量延长总采集时间并缩短全程采样间隔至0.5 s"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-131", "kp": "CT灌注的剂量控制", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】A正确：灌注成像观察的是碘的浓度变化，低kV使碘的CT值增益明显（80 kVp时碘的对比度约为120 kVp的1.7倍），可在降低剂量的同时保持甚至提高信号。B正确：灌注参数由曲线拟合得到，对单帧图像噪声的容忍度较高，故可大幅降低单次曝光的mAs，再用迭代或深度学习重建控噪。C正确：首过期（对比剂流入与流出阶段）需要1~2 s的密集采样以准确拟合曲线，而后段延迟期只需稀疏采样，采用可变间隔可显著减少总曝光次数。D正确：Z轴覆盖越大剂量越高，应按临床问题限定覆盖（如卒中重点覆盖幕上大脑中动脉供血区）。【为什么错】E错误：延长总时间并全程0.5 s高频采样会使曝光次数成倍增加、剂量急剧上升，而对参数计算精度的提升有限，属典型的“以剂量换冗余数据”，违背ALARA原则。", "tr": "灌注剂量控制的关键是“该密的时候密、该停的时候停”，而不是全程高频采样。另需牢记同一部位短期内重复灌注检查有致确定性效应（如皮肤损伤、脱发）的报告，应严格把握适应证。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U09-0132", "t": "案例分析题", "s": "患者男性，71岁，突发右侧肢体无力伴失语5小时，NIHSS评分16分，考虑左侧大脑中动脉供血区急性缺血性卒中，拟评估是否适合血管内取栓治疗。急诊配备64排以上CT，卒中团队要求在最短时间内获得出血、血管闭塞部位与可挽救组织三方面信息。下列一站式扫描流程与技术安排最合理的是", "o": {"A": "先行头颅CT平扫排除颅内出血，随后行头颈CTA明确闭塞部位与侧支，最后行CT灌注评估核心梗死与低灌注体积；两次团注分开进行，控制总碘量，CTP采用低管电压与低mAs并配合迭代重建", "B": "直接行CT灌注，若显示大面积低灌注即可诊断，无须平扫", "C": "先行CT灌注，再行平扫，最后视情况决定是否做CTA", "D": "仅行头颈CTA，凭血管闭塞部位推断梗死核心大小", "E": "先行颅脑增强扫描，再据强化范围判断半暗带"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-132", "kp": "急性卒中一站式CT检查流程", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】A正确。急性卒中影像的第一要务是排除颅内出血（决定能否溶栓／取栓），故必须以平扫开路；其次用CTA定位闭塞血管、评估主动脉弓与颈动脉入路及侧支循环，为取栓路径规划提供依据；最后以CTP判断核心梗死体积与错配情况，回答“是否还有可挽救组织”。CTA先于CTP还可避免灌注注射后的残留强化干扰血管评价。两次团注应分开并控制总碘量，CTP采用低kV、低mAs加迭代重建以压低这一高剂量序列的负担。【为什么错】B错误：不排除出血直接灌注，一旦为脑出血将造成灾难性的治疗决策错误；且灌注不能可靠区分出血。C错误：把灌注放在最前，既延误出血判断，又使随后平扫因对比剂残留而难以判读密度。D错误：闭塞部位与核心梗死体积并不等价，侧支循环状态决定了同一闭塞部位可有截然不同的核心大小，这正是灌注检查存在的意义。E错误：常规增强扫描不能定量血流动力学参数，无法界定半暗带，且延误时间。", "tr": "顺序题的判分点是“先排除出血”。另记：CTA与CTP的顺序在多数中心为平扫→CTA→CTP，既保证血管图像不受污染，又不耽误出血判断；时间就是大脑，所有附加序列都要服从于流程效率。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0133", "t": "多选题", "s": "行头颈部CTA时，为减少颈内静脉与硬膜窦的对比剂污染、提高动脉显示质量，下列措施合理的有", "o": {"A": "采用自足侧向头侧（升序）的扫描方向，使扫描推进与颈动脉血流方向一致", "B": "监测ROI置于主动脉弓或升主动脉，阈值触发后以较短的诊断延迟启动扫描", "C": "缩短注射总时间并加用生理盐水冲刷，使团注更加紧凑", "D": "降低机架旋转速度、延长扫描时间，以获得更充分的动脉充盈", "E": "采用80~100 kVp的低管电压，提高碘的对比效率，从而减少对比剂总量与注射时间"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-133", "kp": "头颈CTA静脉污染的控制", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】A正确：自主动脉弓向颅顶扫描与颈动脉血流方向一致，扫描层面始终“追随”动脉团注前沿，可在静脉回流显影之前完成采集。B正确：主动脉弓ROI能最早捕捉团注到达，配合短诊断延迟可把采集窗锁定在动脉期。C正确：注射时间越短、团注柱越紧凑，动静脉循环时间窗被充分利用，静脉污染越轻；盐水冲刷可把残留在上肢与中心静脉内的对比剂推入循环。E正确：低kV时碘的CT值增益显著，可在减少总量与注射时间的同时保持足够动脉强化，一举两得。【为什么错】D错误：延长扫描时间意味着采集窗跨越了动静脉循环时间（脑循环动静脉时间差仅约4~6 s），静脉必然显影，污染加重；头颈CTA恰恰要求尽可能快的扫描速度。", "tr": "头颈CTA的核心矛盾是“动静脉循环时间差短”，所有对策都围绕“扫得快、团注紧、触发准”。误以为“慢扫描能让动脉更充盈”是典型的方向性错误。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U09-0134", "t": "单选题", "s": "关于冠状动脉CTA与头颈部CTA在技术要求上的差异，下列说法错误的是", "o": {"A": "冠状动脉CTA必须使用心电门控，头颈部CTA常规不需要心电门控", "B": "冠状动脉CTA对时间分辨率要求最高，头颈部CTA则对扫描速度与静脉污染控制要求最高", "C": "冠状动脉CTA的监测ROI常置于升主动脉或降主动脉，头颈部CTA常置于主动脉弓", "D": "冠状动脉CTA扫描范围一般为气管隆嵴下方至心脏膈面约12~16 cm，头颈部CTA自主动脉弓至颅顶", "E": "两者对心率的要求相同，心率超过70次/分时头颈部CTA同样无法完成"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-134", "kp": "冠脉CTA与头颈CTA的参数差异", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】本题选错误项，E错误。心率要求是冠状动脉CTA特有的：冠脉随心动周期大幅位移，必须靠心电门控在相对静止期采集，故要求心率低而齐（理想＜65次/分）。头颈动脉不随心跳大幅移动，扫描不使用心电门控，心率快慢仅通过循环时间影响到达时间，可由团注追踪自动补偿，并不构成检查禁忌。【为什么错】A正确：这是两者最根本的差别。B正确：冠脉靠单扇区／多扇区重建争取毫秒级时间分辨率；头颈靠高螺距、宽体探测器争取秒级的整体扫描速度。C正确：ROI位置的选择原则是“尽量靠近目标血管的上游且位置稳定”。D正确：这是两者常规的解剖覆盖范围，冠脉范围小而要求高，头颈范围长（约35~40 cm）。", "tr": "把“心率控制”泛化到所有CTA是常见错误。需要心电门控的是心脏、冠脉、升主动脉根部（以及部分主动脉全程CTA），头颈、肺动脉、外周血管CTA均不需要。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0135", "t": "单选题", "s": "下列临床情形与CTA时相确定方式的匹配中，不恰当的是", "o": {"A": "常规胸腹主动脉CTA——采用团注追踪，ROI置于降主动脉", "B": "心功能不全、循环时间明显延长者——采用小剂量测试确定个体化延迟", "C": "屏气配合差的幼儿——经验固定延迟是唯一可靠的方式，不应使用团注追踪", "D": "肺动脉CTA——采用团注追踪，ROI置于肺动脉主干", "E": "头颈部CTA——采用团注追踪，ROI置于主动脉弓"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-135", "kp": "CTA触发方式的选择", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】本题选不恰当项，C错误。幼儿循环时间短且个体差异大，经验固定延迟极易失准；实践中同样可采用团注追踪（适当降低阈值、缩短诊断延迟）或小剂量测试，只是要配合低剂量监测与镇静、固定；把固定延迟说成“唯一可靠方式”既不准确也不安全。【为什么错】A正确：主动脉CTA以降主动脉或膈下腹主动脉为监测点是常规做法。B正确：低心排患者对比剂到达明显延迟且峰值平坦，阈值触发不稳定，用test bolus实测峰值时间更可靠。D正确：肺动脉CTA的ROI应置于肺动脉主干（或右心室流出道），阈值多取100 HU左右。E正确：头颈CTA ROI置主动脉弓，可在动脉团注到达颈部之前触发。", "tr": "ROI的放置原则是“目标血管上游、位置稳定、管腔够大”。凡出现“唯一”“只能”等绝对化表述的选项，多为命题设置的错误信号，需结合原理判断而非凭措辞。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0136", "t": "多选题", "s": "关于CTA常用后处理方法的选择与特点，下列正确的有", "o": {"A": "容积再现（VR）适合整体显示血管的空间走行与毗邻关系，但狭窄程度的判断易受阈值与透明度设置影响", "B": "最大密度投影（MIP）能连续显示血管全程与钙化，但骨骼、钙化的重叠可掩盖管腔", "C": "曲面重建（CPR）可将迂曲血管展平于同一平面，便于观察管腔、管壁及支架内情况", "D": "最小密度投影（MinIP）是评价动脉狭窄程度的首选方法", "E": "曲面重建的结果不依赖中心线勾画的准确性"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-136", "kp": "CTA后处理方法的选择", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】A正确：VR图像立体直观，用于术前空间关系展示与沟通；但其显示效果取决于阈值、不透明度曲线，定量狭窄不可靠。B正确：MIP保留了原始CT值，血管连续性好，是CTA的主力后处理；缺点是高密度的骨与钙化会遮挡管腔，需先去骨或结合薄层MIP。C正确：CPR沿血管中心线展开，是评价冠脉、颈动脉、肾动脉迂曲段及支架内再狭窄的关键工具。【为什么错】D错误：MinIP显示的是路径上的最低密度值，主要用于气道、胆道等低密度结构，不能用于动脉狭窄评价。E错误：CPR完全依赖中心线：中心线偏出管腔会人为造成“假性狭窄”或“假性闭塞”，必须结合横断面与原始图像核对。", "tr": "任何后处理图像都不能替代横断面原始图像判读。CPR的假狭窄、MIP的钙化遮挡、VR的阈值假象，是三类最常被追问的后处理陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0137", "t": "案例分析题", "s": "患者男性，70岁，双下肢间歇性跛行3年，临床申请下肢动脉CTA，扫描范围自腹主动脉分叉至足底，长度约120 cm。技师沿用腹部CTA的高螺距快速扫描方案，触发后立即由头侧向足侧采集。重建后发现腹主动脉、髂动脉与股动脉显影良好，但腘动脉以下小腿动脉几乎无对比剂充盈。患者双足背动脉搏动减弱。造成该结果最主要的原因及最合理的改进措施是", "o": {"A": "扫描速度超过了对比剂在下肢的推进速度，出现“扫描追过团注”现象；应降低扫描速度（减小螺距或延长旋转时间）、适当延长触发后延迟，必要时对小腿段追加延迟采集", "B": "对比剂总量不足；应把总量增加一倍并保持原有扫描速度", "C": "触发阈值过高；应把阈值降至50 HU后按原速度重新扫描", "D": "属正常表现，小腿动脉本不显影；改用最小密度投影后处理即可显示", "E": "系金属伪影所致；应改行平扫加骨算法重建"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-137", "kp": "下肢CTA的扫描速度匹配", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】A正确。下肢动脉CTA的特殊矛盾在于“扫描速度必须与对比剂推进速度匹配”：现代多层CT的采集速度可达每秒十余厘米，明显快于团注在下肢（尤其存在近端狭窄、侧支代偿时）的前行速度，扫描层面会“跑到”对比剂前面，造成远端血管无强化。正确对策是主动放慢扫描（减小螺距、延长旋转时间或设置扫描延迟）、延长触发后延迟，对严重缺血侧可对小腿-足部追加一次延迟采集。【为什么错】B错误：单纯加倍对比剂既不能解决时间不匹配问题，还显著增加肾脏负担。C错误：降低阈值只会使扫描更早启动，远端充盈更差，把问题加重。D错误：正常小腿三支动脉在合格的CTA上应清晰显影，无显影是技术失败或病变闭塞，不能视为正常。E错误：无强化区并非高密度金属条纹伪影，改行平扫更无法评价血管。", "tr": "下肢CTA的经典失败是“追过团注”，与之相对的另一失败是“扫太慢导致静脉污染”。判断依据看远端：远端无强化＝扫太快；远端动静脉同时显影＝扫太慢。老年动脉硬化闭塞患者血流慢，应主动降低扫描速度。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0138", "t": "多选题", "s": "目前临床CT实现能量（能谱）成像的技术途径包括", "o": {"A": "双源双能量：两套球管与探测器系统分别以不同管电压同时采集", "B": "单源快速管电压切换：同一球管在相邻投影间高速切换高低管电压", "C": "双层（三明治）探测器：上下两层探测器分别优先吸收低能与高能光子", "D": "在同一管电压下改变管电流大小，即可实现能量分离", "E": "对常规单能扫描数据采用不同卷积核重建，即可获得能谱信息"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-138", "kp": "能量成像的实现方式", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】A正确：双源CT两套系统分别设定80/140 kVp（常加锡滤过），实现空间上同时、能量上分离的采集。B正确：瞬时kV切换在同一旋转内交替产生高低能投影，时间配准好、可做投影域物质分解。C正确：双层探测器由上层吸收低能光子、下层吸收高能光子，天然实现同源同时同角度的双能数据；此外新兴的光子计数探测器可直接按能量区间计数。【为什么错】D错误：管电流只改变光子数量（影响噪声与剂量），不改变X线能谱分布，无法实现能量分离。E错误：卷积核只是重建滤波过程中的数学处理，不能凭空产生不同能量下的衰减信息；虚拟单能量图像必须建立在双能／多能采集数据之上。", "tr": "记住“变的是能量（kV）不是电流（mA）”。虚拟单能量图像来自双能数据的物质分解重组，与“单能量扫描”“不同卷积核”是完全不同的概念。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0139", "t": "单选题", "s": "患者右侧全髋关节置换术后，因盆腔疼痛行能量CT检查，希望在减轻金属条纹伪影的同时兼顾邻近软组织的观察。最适合优先查看的虚拟单能量图像能级是", "o": {"A": "40 keV", "B": "50 keV", "C": "70 keV", "D": "90 keV", "E": "130~150 keV"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-139", "kp": "虚拟单能量图像的能级选择", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】E正确。金属伪影的主要成因是低能光子被大量吸收造成的线束硬化与光子饥饿。高能级（130~150 keV）虚拟单能量图像中光子穿透力强、能谱更“硬”，硬化与条纹伪影显著减轻，配合专用金属伪影校正算法（MAR）可使假体周围软组织重新可辨；代价是碘对比与软组织对比下降，故通常与常规70 keV图像联合阅读。【为什么错】A、B错误：40~50 keV虽显著提高碘的CT值（适合小血管、乏血供病灶显示），但同时放大线束硬化伪影与噪声，在金属周围表现最差。C错误：70 keV近似常规120 kVp图像的对比噪声特性，是通用阅读能级，但对金属伪影无改善作用。D错误：90 keV改善有限，未达到抑制严重金属伪影所需的能级。", "tr": "牢记能级选择的两极：“低keV增强碘对比”（40~55 keV，用于CTA、乏血供病灶、低碘负荷），“高keV去伪影”（≥130 keV，用于金属、颅底、肩部硬化伪影）。二者用途相反，切勿颠倒。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0140", "t": "单选题", "s": "关于双能量CT物质分离技术的临床应用，下列描述错误的是", "o": {"A": "虚拟平扫（VNC）从增强数据中减除碘成分，在部分场景下可省去一次真实平扫从而降低总剂量", "B": "碘密度图可定量评价组织的碘摄取，有助于判断肿瘤活性和肺栓塞相关的灌注缺损", "C": "可鉴别尿酸盐结石与非尿酸盐结石，并能显示痛风患者关节周围的尿酸盐结晶沉积", "D": "虚拟去钙技术可提高椎体骨髓水肿等病变的显示能力", "E": "物质分离可直接定量测出病灶内钙、碘、铁的绝对含量，并据此明确肿瘤的病理类型"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-140", "kp": "双能量CT的物质分离应用", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】本题选错误项，E错误。双能量物质分解基于两种基物质的衰减模型，通常只能在“两基物质＋约束条件”的框架下做相对定量（如碘浓度mg/ml、脂肪分数），无法同时精确给出多种元素的绝对含量；更重要的是，任何影像定量都不能直接确定病理类型，病理诊断仍需组织学证据。【为什么错】A正确：VNC是双能量最成熟的应用之一，在肾上腺、肾脏、主动脉夹层等检查中可替代真实平扫，减少一次曝光。B正确：碘图是功能性信息，肺栓塞的肺灌注血容量图与肿瘤治疗后活性评估均依赖它。C正确：尿酸盐与钙质在高低能下的衰减差异明显，双能量鉴别痛风的临床价值已被广泛认可。D正确：虚拟去钙可减除椎体骨小梁的钙信号，使骨髓水肿在CT上可视化，用于隐匿骨折评估。", "tr": "能量CT的定量是“相对、受模型限制”的，且始终不能替代病理。凡把影像技术描述为“可明确病理类型／确诊”的选项，几乎都是错误项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0141", "t": "单选题", "s": "关于CT导向下经皮穿刺活检的技术要点，下列说法错误的是", "o": {"A": "定位时可在体表放置金属定位栅（栅栏），据CT图像确定进针点、进针角度与深度", "B": "进针过程中应分次进针并反复薄层扫描，确认针尖与病灶、重要结构的关系", "C": "同轴技术经一次穿刺置入外套针后可反复取材，减少胸膜穿刺次数与并发症", "D": "肺内病灶穿刺应选择最短路径，即使需要穿过叶间裂或含气肺组织也应优先考虑距离最短", "E": "取材完成后应即刻复查扫描，观察有无气胸、出血等并发症并记录"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-141", "kp": "CT导向穿刺活检的技术要点", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】本题选错误项，D错误。肺穿刺路径选择的首要原则是“安全”而非“最短”：应避免穿过叶间裂（等于两次穿破胸膜，气胸风险成倍增加）、大血管、肺大疱及正常肺组织过多的路径，宁可选择稍长但经病灶紧贴胸膜处进针的路径。【为什么错】A正确：定位栅是最基础的体表定位工具，配合激光灯确定层面。B正确：分步进针＋薄层确认是避免误伤的关键，尤其在纵隔、肝门等毗邻大血管区域。C正确：同轴技术是标准做法，可一次穿刺、多条取材，兼顾诊断率与安全性。E正确：术后即刻复查是常规，用于早期发现气胸、出血并决定观察或处理，同时是重要的医疗记录。", "tr": "穿刺路径“最短”与“最安全”常不一致，考试与临床都以最安全为准。叶间裂、肺大疱、心包、大血管、扩张的胆管都是必须避开的结构。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0142", "t": "案例分析题", "s": "患者男性，65岁，右肺上叶周围型结节，在CT导向下行经皮穿刺活检。采用同轴技术，取材2条后即刻扫描发现右侧少量气胸，估计肺压缩约10%，纵隔无移位。患者诉轻微胸痛，无明显呼吸困难，血氧饱和度98%，生命体征平稳。此时最恰当的处理是", "o": {"A": "停止继续取材，拔针后嘱患者取穿刺侧向下卧位、必要时吸氧并留观，20~30分钟后复查CT观察气胸是否进展，多数少量气胸可自行吸收", "B": "立即行胸腔闭式引流术，以防气胸进展", "C": "继续追加多次穿刺以保证取材量，待检查全部结束后再统一处理", "D": "立即行胸部增强CT以明确有无活动性出血", "E": "无须复查扫描，直接送患者返回病房观察"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-142", "kp": "CT导向肺穿刺并发症的处理", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】A正确。气胸是CT引导肺穿刺最常见的并发症（发生率约20%~30%，需引流者仅少数）。本例为少量气胸、无症状、生命体征稳定，处理原则是停止操作、拔针、穿刺侧向下卧位（借重力压迫穿刺点、减少气体进一步漏出）、吸氧促进气体吸收，并在留观期间复查扫描确认无进展，绝大多数可保守吸收。【为什么错】B错误：胸腔闭式引流适用于大量气胸（如肺压缩＞30%）、症状明显、张力性气胸或进行性增大者，本例属过度处理。C错误：气胸已发生仍继续多次穿刺，会显著加重漏气，是操作原则性错误。D错误：患者无咯血、无血流动力学不稳，增强扫描既无指征又增加剂量与对比剂风险。E错误：不复查、不留观即送回，可能漏掉迟发进展性气胸，违反术后观察规范。", "tr": "少量无症状气胸＝观察＋复查；大量或有症状／张力性气胸＝抽气或闭式引流。另需记住术后卧位原则“穿刺侧向下”，以及肺出血时应“患侧向下”以防血液流入健侧。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0143", "t": "单选题", "s": "关于CT机的日常设备准备与质量保证，下列说法错误的是", "o": {"A": "每日开机后应按厂家程序进行球管预热，使阳极靶面受热均匀，避免热应力损伤", "B": "应按厂家要求定期进行空气校正（气体校准），以校正各探测器通道间的响应差异", "C": "定期用水模检测水的CT值（应在0±4~5 HU范围内）、噪声与均匀性", "D": "进行空气校正时，机架扫描孔内不得放置任何物体，检查床也应移出扫描野", "E": "只要图像上未见明显环状伪影，即可长期不做空气校正，以节省球管寿命"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-143", "kp": "设备预热与空气校正", "ch": "九、CT检查技术 → 3.检查前准备 → (1)设备", "ex": "【为什么对】本题选错误项，E错误。空气校正是探测器通道一致性的基础保障，探测器响应会随温度、湿度与使用时间缓慢漂移，等到出现明显环状伪影时误差已相当大，且CT值准确性可能早已超标。规范做法是按厂家要求定期（多为每日或每周）执行，属强制性质控项目，其球管消耗微乎其微。【为什么错】A正确：冷球管直接大功率曝光会因热冲击损伤阳极靶面并缩短寿命，预热是每日第一步。B正确：这正是空气校正的目的。C正确：水模检测CT值、噪声、均匀性、层厚等是CT质控的核心项目，水的CT值应接近0 HU。D正确：校正时扫描野内必须为空气，任何物体（包括检查床、体模、耦合垫）都会导致校正数据错误，进而产生全局性伪影。", "tr": "环状伪影是探测器通道失校的典型征象，其常规对策就是重新做空气校正。切勿把“节省球管”当作省略质控的理由——CT值失准会直接影响脂肪肝、结石、灌注等定量判读。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0144", "t": "多选题", "s": "关于CT检查前的患者准备，下列做法正确的有", "o": {"A": "腹部检查一般需禁食4~6小时，且检查前一周内不宜做过钡剂胃肠造影", "B": "腹部检查前可按规定分次口服1%~2%的碘对比剂稀释液或温开水，以充盈胃肠道", "C": "去除检查部位的金属饰物、活动义齿、发夹、含金属的膏药与内衣饰扣", "D": "胸部与上腹部检查前应做屏气训练，使定位像、平扫与各期增强的屏气幅度一致", "E": "为减少运动伪影，所有受检者在检查前均应常规使用镇静剂"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-144", "kp": "CT检查前的患者准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】A正确：禁食可减少胃内容物干扰并降低对比剂不良反应时误吸风险；残留钡剂密度极高，会产生严重条纹伪影并掩盖病灶，故需待其排空。B正确：1%~2%浓度的稀释碘水既能勾勒肠腔又不至于因过浓产生伪影；分次定时口服（如检查前60、30、10分钟）可使从胃到远端小肠依次充盈。C正确：金属高密度物体引起放射状条纹伪影，是可预防的图像质量问题。D正确：屏气幅度不一致会造成层面错位与病灶“漏扫”，也会使多期图像难以配准比较，这是胸腹部检查的关键细节。【为什么错】E错误：镇静有呼吸抑制与误吸等风险，仅在婴幼儿、意识障碍或躁动不能配合者由临床医师评估后使用，绝不能作为常规。", "tr": "口服对比剂需要“浓度低、分次服、留足时间”；过浓反而产生伪影。带“所有／均”的常规化处置类选项（如常规镇静、常规激素预防）通常是错误项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0145", "t": "单选题", "s": "关于碘对比剂使用相关的安全管理，下列说法错误的是", "o": {"A": "使用前将对比剂加温至37 ℃可降低黏稠度，便于高流率注射并减轻注射时的不适", "B": "碘过敏试验对预测过敏样反应缺乏价值，目前不推荐作为常规筛查手段", "C": "既往对碘对比剂发生过中重度过敏样反应者属高危人群，应重新评估检查必要性或改用其他影像方法", "D": "对eGFR＜30 ml/(min·1.73 m²)或存在急性肾损伤者，应在检查前停用二甲双胍，并在检查后48小时复查肾功能无恶化后再恢复用药", "E": "只要建立了静脉通路并备有肾上腺素，即可对所有患者省略过敏史询问与知情告知"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-145", "kp": "对比剂使用与高危因素评估", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】本题选错误项，E错误。病史询问（既往对比剂反应史、哮喘与过敏体质、肾功能、糖尿病与二甲双胍用药、甲状腺功能亢进、妊娠等）和知情告知是使用对比剂前不可省略的法定与技术环节；急救准备只是“出事之后”的保障，不能替代“事前”风险识别，二者不可互换。【为什么错】A正确：加温至体温可显著降低黏稠度（尤其高浓度对比剂），有利于高流率注射并减少推注阻力和不适。B正确：所谓“碘过敏试验”既不能预测过敏样反应，本身还可能诱发反应，国内外指南均已不推荐常规进行。C正确：既往中重度反应史是最强的风险预测因子，应权衡改用平扫、MRI或超声等替代方案，必要时在具备抢救条件下进行。D正确：二甲双胍本身无肾毒性，风险在于肾功能急剧下降时药物蓄积诱发乳酸酸中毒，故按肾功能分层管理停药与复查。", "tr": "记住三个“不能”：碘过敏试验不能预测反应、预防用药不能完全消除风险、急救准备不能替代风险筛查。二甲双胍的处理按eGFR分层，而非一律停药48小时。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0146", "t": "多选题", "s": "关于CT检查室的急救准备与对比剂不良反应处理，下列正确的有", "o": {"A": "检查室应配备氧气、吸引装置、简易呼吸器、血压计与常用急救药品，并定期核查有效期与功能状态", "B": "发生喉头水肿、支气管痉挛伴低血压等严重过敏样反应时，成人首选肌内注射1:1000肾上腺素0.3~0.5 mg，必要时重复", "C": "单纯轻度荨麻疹等皮肤反应多可自限，以观察为主，必要时给予抗组胺药物", "D": "糖皮质激素起效慢，不能作为严重急性过敏样反应的首选抢救药物", "E": "对比剂血管外渗后应立即热敷并加压包扎患肢，以促进吸收"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-146", "kp": "急救物品与对比剂不良反应处理", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】A正确：这是开展增强检查的基本条件，急救设备必须处于随时可用状态并有定期点检记录。B正确：肾上腺素是严重过敏样反应的一线药物，成人肌注1:1000溶液0.3~0.5 mg（大腿前外侧肌肉吸收最快），可每5~15分钟重复。C正确：轻度皮肤反应多为自限性，过度用药无益，重点是继续观察是否进展。D正确：激素起效需数小时，主要用于防止双相反应和迁延症状，不能替代肾上腺素。【为什么错】E错误：外渗的正确处理是抬高患肢、早期局部冷敷（一般24小时内间断冷敷），并观察张力、感觉、皮肤颜色，警惕骨筋膜室综合征；加压包扎会加重局部压力、影响回流，热敷在早期可能加重肿胀。", "tr": "外渗处理“抬高＋冷敷、不加压”，与软组织扭伤的处理思路一致；严重反应“先肾上腺素、后激素”。这两组是最常考的处置顺序题。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0147", "t": "单选题", "s": "关于CT检查中操作者的准备与职责，下列说法错误的是", "o": {"A": "严格核对患者身份、检查部位与申请单信息，防止张冠李戴与错扫部位", "B": "增强检查前应履行知情告知义务并取得签署的知情同意书", "C": "熟悉本单位应急预案与急救药品位置，能够识别对比剂不良反应的早期表现", "D": "合理使用铅防护用品，对邻近扫描野的敏感器官（如儿童性腺、甲状腺）予以屏蔽", "E": "为提高工作效率，可由未经培训的实习人员独立完成高压注射器操作与扫描参数设定"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-147", "kp": "操作者准备与知情同意", "ch": "九、CT检查技术 → 3.检查前准备 → (4)操作者", "ex": "【为什么对】本题选错误项，E错误。高压注射器操作与扫描参数设定直接关系患者安全（渗漏、空气栓塞、过量曝光），必须由经过培训并获得授权的技师执行；实习人员只能在带教教师指导下参与，不能独立操作，这是执业规范的底线要求。【为什么错】A正确：身份与部位核对是医疗安全核查的第一步。B正确：增强属有创、有风险的操作，知情同意是法定程序。C正确：技师往往是不良反应的第一发现者，识别早期表现（皮肤瘙痒、喷嚏、声音嘶哑、胸闷）并及时呼救至关重要。D正确：在不影响诊断信息的前提下对邻近敏感器官屏蔽，符合防护最优化原则。", "tr": "涉及“未经培训人员独立操作”“省略知情同意”“为效率牺牲核对”的选项一律为错。此类题考的是执业规范意识，与技术细节同样重要。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0148", "t": "案例分析题", "s": "患儿男，3岁，体重14 kg，反复肺部感染，临床申请胸部CT明确有无支气管发育异常。患儿哭闹明显、不能配合屏气，家长要求陪同。科室配备64排CT，具备儿童剂量方案与自动管电流调制功能。下列检查前准备与技术方案中最合理的是", "o": {"A": "由临床医师评估后按需给予镇静并使用固定装置，采用大螺距快速扫描缩短采集时间，选择儿童低剂量方案（降低管电压、按体重调制管电流）并做好非检查部位屏蔽，陪同家长穿戴铅防护", "B": "沿用成人胸部扫描参数，以保证图像质量与诊断信心", "C": "用约束带强行固定后按成人剂量连续扫描两遍，以防一次失败", "D": "一律先行全身麻醉后再行胸部增强扫描", "E": "因儿童对辐射敏感，应以胸部MRI完全替代CT检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-148", "kp": "儿童CT检查的特殊准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】A正确。儿童CT的核心原则是“快、准、低”：用大螺距／宽体探测器把采集压缩到1~2秒内，可在自由呼吸下获得可诊断图像，从而尽量减少镇静需求；确需镇静时由临床医师评估并全程监护；剂量方案按体重／体厚个体化（降低kV、自动管电流调制、迭代重建），并对非检查部位屏蔽；陪同人员必须穿戴铅防护并站在合适位置。【为什么错】B错误：成人参数对14 kg幼儿而言剂量严重过量，违反ALARA与儿童剂量优化原则。C错误：既强行约束又重复扫描，剂量翻倍且极易引起体动，属双重错误。D错误：全身麻醉有其自身风险，不应作为常规首选；且本例临床问题（支气管发育异常）多数无须增强。E错误：MRI对肺实质与气道细节的显示远不如CT，且检查时间长、幼儿更难配合，不能完全替代。", "tr": "儿童检查优化的正确顺序是：先想办法缩短扫描时间（减少镇静需求），再优化剂量参数，最后才考虑镇静与麻醉。“沿用成人参数”和“重复扫描保成功”是最典型的错误做法。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0149", "t": "多选题", "s": "关于孕妇与危重患者行CT检查的特殊准备，下列做法正确的有", "o": {"A": "妊娠期确需CT检查时应严格掌握适应证，优先考虑超声或MRI；确需CT者应缩小扫描范围、优化剂量并对腹部予以屏蔽", "B": "危重患者检查时须由临床医护人员陪同，携带监护仪与抢救器材，保持气道与静脉通路通畅", "C": "带有呼吸机、微量泵、引流管的患者，移床前应核对管路长度与固定情况，防止牵拉脱管", "D": "意识障碍或躁动不能配合者可使用固定装置并尽量缩短扫描时间，必要时由临床医师评估后给予镇静", "E": "妊娠属CT检查的绝对禁忌，任何情况下均不得对孕妇实施CT扫描"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-149", "kp": "孕妇与危重患者的检查准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】A正确：妊娠期遵循正当化与最优化原则，能用无电离辐射手段解决的优先用超声／MRI；确有必要（如疑肺栓塞、严重创伤）时应权衡母体获益与胎儿风险，通过限制范围、降低管电压与管电流、屏蔽等手段把胎儿剂量降至最低。B正确：危重患者随时可能出现循环呼吸变化，检查室不具备完整抢救条件，必须由临床团队陪同并携带设备。C正确：移床过程中的管路牵拉是CT室常见不良事件，检查前核对是标准动作。D正确：固定＋快速扫描优先，镇静作为补充手段并须有医师评估与监护。【为什么错】E错误：妊娠不是CT的绝对禁忌。当母体存在危及生命的情况（如肺栓塞、多发创伤、急腹症）时，延误诊断的风险远大于经过优化后的胎儿受照风险；常规腹部以外部位的CT，胎儿剂量通常很低。", "tr": "“绝对禁忌”一词在对比剂与妊娠相关题目中几乎都是错误信号。正确的表述是“严格掌握适应证、优化剂量”，即正当化＋最优化，而非一刀切禁止。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0150", "t": "单选题", "s": "关于胸腹部CT检查的呼吸训练与呼吸相关伪影，下列说法错误的是", "o": {"A": "定位像与平扫、各期增强应使用同一套呼吸指令，保证屏气幅度一致以便层面配准", "B": "屏气不足或扫描中途换气可造成膈肌附近层面错位与运动伪影，甚至遗漏病灶", "C": "冠状动脉CTA与肺动脉CTA宜采用平静吸气后屏气，过度深吸气可致大量未强化的下腔静脉血涌入右心，形成一过性对比剂中断", "D": "确实无法屏气者可采用大螺距、短旋转时间的快速扫描，在平静呼吸下完成采集", "E": "屏气幅度不一致只影响图像美观，不会影响多期增强图像间的对照比较"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-150", "kp": "屏气训练与呼吸运动伪影", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】本题选错误项，E错误。屏气幅度不一致会使同一病灶在不同期相落到不同层面，导致强化曲线判读错误、小病灶“时有时无”，也使配准与减影后处理失败，直接影响诊断结论而非仅仅“美观”。【为什么错】A正确：统一指令是保证多期可比性的前提，训练时应让患者按同样深度吸气再屏住。B正确：膈肌活动度最大，屏气失败首先在肝顶、肺底表现为错层、双边影与阶梯状伪影。C正确：这是CTPA与冠脉CTA中一过性对比剂中断的经典机制，故推荐“平静吸气后屏气”而非深大吸气。D正确：现代CT可在1~2秒内完成胸部采集，对无法屏气者用快速扫描换取可诊断图像是常规策略。", "tr": "深吸气会增加胸腔负压、促使下腔静脉未强化血液回流右心，是CTPA强化不足的重要技术原因，纠正方法是改用平静吸气后屏气，而不是增加对比剂用量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0151", "t": "多选题", "s": "关于颅脑CT扫描基线与层厚的选择，下列正确的有", "o": {"A": "常规颅脑横断面扫描多以听眦线（OM线）作为基线", "B": "采用听眉线作为基线时，扫描层面较少穿过颅底骨嵴，有助于减轻后颅窝伪影", "C": "适当倾斜机架角度可使层面避开晶状体，减少眼晶状体的受照剂量", "D": "传统分层扫描时，幕下（后颅窝）宜采用较薄层厚，幕上可采用相对较厚层厚", "E": "采用螺旋容积采集后，重组基线在采集完成后即固定，不能再做调整"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-151", "kp": "颅脑扫描基线的选择", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】A正确：听眦线（外眦与外耳道中点连线，即OM线）是颅脑横断扫描最常用的基线，层面显示解剖标准、便于随访对照。B正确：听眉线（眉上缘中点至外耳道中点）较OM线上倾约15°~20°，层面与岩骨嵴的交角改变，可减少颅底骨造成的线束硬化条纹，同时也降低晶状体受照。C正确：倾斜机架使扫描平面避开眼球，是减少晶状体剂量的经典手段。D正确：后颅窝结构精细、伪影多，需薄层；幕上脑组织可用相对厚层以控制噪声与剂量，这是传统分层扫描的通行原则。【为什么错】E错误：螺旋容积采集获得的是各向同性数据，可在任意基线上重组横断、冠状、矢状与斜位图像，重组基线完全可以事后调整，这正是容积扫描相对分层扫描的重要优势。", "tr": "OM线与听眉线是两条不同基线：常规用OM线，减少后颅窝伪影与晶状体剂量时用听眉线或倾斜机架。容积扫描后“可任意重组”是现代CT的基本特性，凡称“不可更改”者多为错误项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0152", "t": "单选题", "s": "颅脑CT后颅窝层面常出现横贯岩骨之间的条纹状低密度伪影（Hounsfield伪影），下列处理措施中不恰当的是", "o": {"A": "适当减薄层厚并提高管电流，减轻部分容积效应与光子饥饿", "B": "适当提高管电压，增强射线穿透力以减轻线束硬化", "C": "启用线束硬化校正算法或迭代重建算法", "D": "采用薄层容积采集后重组，或调整机架角度使扫描层面尽量避开岩骨嵴", "E": "改用高分辨率骨算法重建脑实质图像，通过锐化处理消除该伪影"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-152", "kp": "后颅窝伪影的处理", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】本题选不恰当项，E错误。后颅窝条纹伪影源于岩骨对低能光子的强烈吸收（线束硬化）与光子饥饿，属数据层面的问题。骨算法只会放大高频噪声与条纹，使脑干、小脑的低对比结构更难辨认；观察后颅窝脑实质应使用软组织核，必要时配合稍窄的后颅窝窗。【为什么错】A正确：薄层减少岩骨与脑组织在同一体素内的混合，提高mAs增加穿透岩骨的光子数，两者均能减轻伪影。B正确：提高kV使平均光子能量升高，硬化效应相对减弱。C正确：厂家的硬化校正与迭代重建对该类伪影有明确改善作用。D正确：容积采集后重组可绕开原采集角度的不利几何，倾斜机架也能改变射线穿过岩骨的路径。", "tr": "牢记“看骨用骨算法、看脑用软组织算法”，锐化核对硬化伪影只会雪上加霜。凡是伪影来自数据不足或硬化，解决之道在采集与校正，而不是后处理锐化。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0153", "t": "案例分析题", "s": "患者男性，76岁，3周前有跌倒史，近1周头痛、反应淡漠、行走不稳。急诊头颅CT平扫：常规脑窗（窗宽80 HU、窗位35 HU）观察，双侧额顶部脑沟较对侧同龄人变浅、脑回受压，中线结构基本居中，脑实质内未见明确异常密度灶。临床高度怀疑慢性／亚急性硬膜下血肿。在不追加扫描的前提下，下列技术处理最恰当的是", "o": {"A": "在常规脑窗基础上加用较宽的窗（如窗宽150~300 HU、窗位50~80 HU）重新观察颅骨内板下区域，并结合冠状面、矢状面重组，必要时建议增强扫描显示血肿包膜", "B": "既然脑实质未见异常密度，可直接报告为未见明显异常", "C": "改用骨窗（窗宽约2000 HU）观察脑实质，以提高对等密度血肿的检出", "D": "追加头颅CT灌注检查，通过CBF下降判断有无硬膜下血肿", "E": "提高管电压至140 kVp后重新扫描，以增加血肿与脑组织的密度差"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-153", "kp": "等密度硬膜下血肿的窗技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】A正确。亚急性期（约1~3周）硬膜下血肿可与脑皮质呈等密度，在窄脑窗下与颅骨内板高密度形成的“白边”混为一体而漏诊。加宽窗宽、上抬窗位后，颅骨内板与其下方的等密度血肿之间可显现分界，同时可观察到脑沟消失、灰白质界面内移、脑回受压等间接征象；冠状与矢状重组有助于显示沿颅穹窿铺展的薄层血肿；增强后血肿包膜强化及皮质静脉内移可进一步确认。【为什么错】B错误：本例已有明确间接征象（脑沟变浅、脑回受压），直接报阴性属漏诊。C错误：骨窗窗宽过大，脑组织与血肿间数十HU的差别会被完全压缩为同一灰阶，反而更看不出来。D错误：CT灌注不是硬膜下血肿的诊断手段，徒增剂量与时间。E错误：血肿与脑实质的等密度是血液成分演变（血红蛋白降解、蛋白含量下降）造成的，提高kV并不能增大二者密度差，反而降低软组织对比。", "tr": "“中线居中”并不能排除双侧对称性硬膜下血肿——这是老年患者最易漏诊的场景。等密度血肿的对策是调窗＋看间接征象，而不是重扫或换算法。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0154", "t": "单选题", "s": "关于颅脑CT常用的窗技术，下列说法正确的是", "o": {"A": "常规脑窗一般取窗宽80~100 HU、窗位35~45 HU", "B": "常规脑窗应取窗宽350~400 HU、窗位40 HU", "C": "观察颅骨骨折宜采用窗宽80~100 HU的窄窗", "D": "观察后颅窝结构时应把窗宽缩小至20~30 HU", "E": "无论观察何种结构，窗位均应固定为0 HU"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-154", "kp": "颅脑CT的窗技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】A正确。脑灰白质CT值差别仅约8 HU，必须使用窄窗才能把这一微小差别展开为可辨的灰阶，故常规脑窗为窗宽80~100 HU、窗位35~45 HU。【为什么错】B错误：窗宽350~400 HU是纵隔窗／软组织窗的参数，用于脑部会使灰白质对比几乎消失。C错误：颅骨骨折需要在骨窗（窗宽约1500~4000 HU、窗位300~700 HU）下观察，窄窗会使骨结构全部呈纯白而无层次。D错误：窗宽20~30 HU过窄，噪声将被极度放大，图像斑驳不可用；后颅窝通常在常规脑窗基础上略作调整（如窗宽稍加大或采用专用后颅窝窗）。E错误：窗位应根据目标组织的CT值设定，脑组织约35~45 HU，固定为0 HU（水的CT值）会使脑组织整体偏白、失去层次。", "tr": "四组必背窗值：脑窗80~100/35~45、骨窗1500~4000/300~700、肺窗1000~1600/-600~-700、纵隔窗300~400/30~50。命题常把脑窗与纵隔窗的数值对调。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0155", "t": "单选题", "s": "关于颅脑CT扫描的体位与方式，下列说法错误的是", "o": {"A": "常规取仰卧位，头置于头架内，使两侧外耳孔与正中矢状面处于对称位置", "B": "常规采用横断面扫描，鞍区、颅底等部位必要时加做冠状面扫描或重组", "C": "传统分层扫描时幕下层厚较薄（约5 mm），幕上可采用较厚层厚（约8~10 mm）", "D": "现代多层螺旋CT多采用薄层容积采集后按需重组，兼顾多平面观察", "E": "摆位时应使头部尽量后仰，令听眦线与检查床面保持平行"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-155", "kp": "颅脑CT的体位与扫描方式", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】本题选错误项，E错误。常规颅脑横断扫描要求听眦线与检查床面（水平面）垂直，即扫描层面与听眦线平行；头部过度后仰使听眦线与床面平行是完全错误的摆位，会导致层面倾斜、左右不对称、解剖标志错乱，并增加晶状体受照。【为什么错】A正确：仰卧、头正、两侧外耳孔对称是保证左右结构对称显示的基本要求，头部旋转会造成假性中线偏移。B正确：鞍区、颅底、眼眶等部位常需冠状面信息，可直接扫描或由薄层容积数据重组。C正确：这是传统分层扫描的常规参数配置。D正确：薄层容积采集＋多平面重组已成为现行主流。", "tr": "牢记“基线与床面垂直、扫描层面与基线平行”。摆位不对称是颅脑CT最常见的低级错误，会造成侧脑室、颞角显示不对称而误判占位效应。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0156", "t": "单选题", "s": "关于鞍区（垂体）CT检查技术，下列说法错误的是", "o": {"A": "应采用≤2 mm的薄层扫描或薄层重建，以减轻部分容积效应对垂体形态判断的干扰", "B": "冠状面图像（直接冠状扫描或薄层重组）对显示垂体上缘形态、垂体柄有无偏移最有价值", "C": "疑垂体微腺瘤时可行动态增强，微腺瘤在早期强化图像上多相对于明显强化的正常垂体呈低密度", "D": "骨窗观察有助于发现鞍底骨质变薄、吸收或倾斜等间接征象", "E": "鞍区检查以10 mm层厚横断面扫描为主，以缩短检查时间、降低剂量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-156", "kp": "鞍区CT检查技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】本题选错误项，E错误。垂体上下径仅约6~8 mm，微腺瘤直径常＜10 mm，10 mm层厚会把整个垂体“压缩”在一到两个层面内，部分容积效应足以掩盖病灶，是根本性的参数错误。【为什么错】A正确：薄层是鞍区检查的前提。B正确：冠状面能同时显示垂体上缘（正常平坦或轻度凹陷）、垂体柄居中与否、海绵窦与颈内动脉，是鞍区最重要的观察平面。C正确：正常垂体无血脑屏障、强化迅速而明显，微腺瘤强化相对延迟，故早期呈相对低密度，这正是动态增强的原理。D正确：鞍底骨质改变是垂体腺瘤的重要间接征象，需在骨窗观察。", "tr": "鞍区题的判分点几乎都在“薄层＋冠状面＋动态增强”。注意微腺瘤是“相对低密度”，出现在强化早期；延迟期病灶可反转为等或高密度，时相选错就会漏诊。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0157", "t": "多选题", "s": "关于鞍区CT检查的技术要点与临床价值，下列正确的有", "o": {"A": "垂体高度增加、上缘膨隆与垂体柄偏移属于垂体微腺瘤的间接征象", "B": "直接冠状面扫描需患者头部过伸，颈椎病变或危重患者难以配合，此时可用薄层横断采集后冠状重组替代", "C": "动态增强要求在注射对比剂后的短时间内对同一区域多次重复采集，以捕捉正常垂体与微腺瘤强化的时间差", "D": "鞍区CT对垂体微腺瘤的检出敏感性优于MRI，应作为首选检查方法", "E": "鞍区检查只需观察垂体本身，无须评估海绵窦及鞍上池情况"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-157", "kp": "鞍区检查的技术要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】A正确：微腺瘤体积小，直接征象常不明显，主要依靠垂体高度增加（女性＞9 mm需警惕，需结合年龄与生理状态）、上缘局限性膨隆、垂体柄向对侧偏移、鞍底局部下陷等间接征象。B正确：直接冠状位要求头部过伸，颈椎强直、外伤或危重患者无法配合，薄层容积采集后重组是等效且更舒适的替代方案。C正确：动态增强的本质是利用正常垂体与微腺瘤的强化时间差，必须高频重复采集同一层面。【为什么错】D错误：MRI软组织分辨率高、可多参数成像，是垂体微腺瘤的首选检查；CT主要用于观察骨质改变、钙化（如颅咽管瘤）以及MRI禁忌者。E错误：鞍区病变常侵犯海绵窦、包绕颈内动脉或向鞍上生长压迫视交叉，海绵窦与鞍上池必须纳入观察范围，这直接影响手术方式选择。", "tr": "“CT优于MRI”类表述在垂体、内耳膜迷路、脑干等软组织部位几乎都是错的；反之在骨质细节、钙化、急性出血方面CT有优势。判断依据是“看骨看钙化用CT，看软组织用MRI”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0158", "t": "单选题", "s": "关于眼部CT检查技术，下列说法错误的是", "o": {"A": "常规采用横断面薄层（≤2 mm）扫描，必要时加做冠状面扫描或重组", "B": "横断面可选用听眶下线作为基线，使层面尽量平行于视神经走行以便全程显示", "C": "冠状面图像有利于观察各条眼外肌的形态以及眶顶、眶底骨壁", "D": "测量眼球突出度可在经晶状体的横断层面上，以两侧眶外缘（颧突）连线为基线，正常一般不超过21 mm", "E": "眼部检查应常规采用高剂量、大层厚扫描，以保证图像信噪比"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-158", "kp": "眼部CT检查技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】本题选错误项，E错误。眼球晶状体是对辐射最敏感的组织之一，眼部CT应在保证诊断的前提下优化剂量（薄层但适度mAs、必要时倾斜机架避开晶状体、采用迭代重建），绝不能以“提高信噪比”为由常规高剂量；同时大层厚会因部分容积效应掩盖眶内小病灶与细小异物，与检查目的冲突。【为什么错】A正确：眶内结构精细，薄层是基本要求。B正确：以听眶下线为基线的横断面接近视神经走行方向，有利于连续显示视神经全程。C正确：冠状面是判断眼外肌增粗（如甲状腺相关眼病）、眶壁骨折（尤其眶底爆裂骨折）的关键平面。D正确：这是CT测量眼球突出度的通用方法与参考值。", "tr": "晶状体剂量是眼部CT的核心防护点：可通过倾斜机架、缩小范围、降低mAs、迭代重建来控制。凡以“保证信噪比”为由主张常规高剂量的选项都是错的。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0159", "t": "案例分析题", "s": "患者男性，28岁，工作中用砂轮打磨金属时未戴防护镜，突发右眼剧痛、视物模糊2小时。眼科检查见角膜小穿通伤口，屈光介质混浊无法窥清眼底，高度怀疑眼内金属异物。临床要求明确异物的有无、位置及与眼球壁、晶状体的关系，以决定手术入路。下列检查方案最合适的是", "o": {"A": "行眼眶薄层（≤1 mm）CT平扫，采用横断采集并做冠状、矢状及斜位重组精确定位，同时评价眼球壁完整性；在排除金属异物前不得行MRI检查", "B": "首选眼眶MRI，其软组织分辨率高，最有利于显示异物与视网膜的关系", "C": "行眼眶CT增强扫描，通过强化程度判断异物性质", "D": "行头颅常规10 mm层厚平扫，若未见异常即可排除眼内异物", "E": "行眼部CT灌注成像评估眼球血供后再定手术方案"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-159", "kp": "眼内异物的CT定位", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】A正确。CT是眼内金属异物定位的首选：金属为极高密度，薄层扫描配合多平面重组可准确判断异物位于球内或球壁、与晶状体和视神经的距离，为手术入路提供依据；同时可评估眼球破裂、眶壁骨折与积气。关键安全点是：在未排除铁磁性异物前严禁MRI，磁场可致异物移位造成灾难性眼内损伤。【为什么错】B错误：疑金属异物时MRI是禁忌，且金属会产生巨大磁敏感伪影，反而无法定位。C错误：异物本身不强化，增强既无助于定性又增加风险与剂量。D错误：10 mm层厚极易漏掉毫米级异物，且不能精确定位，属参数选择错误。E错误：CT灌注与本临床问题无关，浪费时间与剂量，延误手术。", "tr": "“先CT排除金属异物、再决定能否MRI”是必须条件反射式掌握的安全流程。另注意异物成分不同显示各异：金属与玻璃呈高密度，木质异物可呈低密度而易被误认为气体。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0160", "t": "多选题", "s": "关于颞骨（内耳）高分辨率CT的技术参数，下列正确的有", "o": {"A": "采用≤1 mm的薄层（常用0.5~0.625 mm）采集，实现各向同性体素", "B": "使用高分辨率骨算法（骨核）重建，以突出听小骨与骨迷路的边缘", "C": "缩小显示野对单侧颞骨行靶重建，使像素变小、空间分辨率进一步提高", "D": "观察骨性结构常用骨窗，窗宽约4000 HU、窗位约700 HU", "E": "为降低图像噪声，应改用软组织平滑核并适当增大层厚"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-160", "kp": "颞骨内耳HRCT参数", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】A正确：镫骨脚、砧镫关节、面神经管、前庭导水管等结构均为亚毫米级，必须用亚毫米薄层采集；各向同性体素才能保证任意角度重组（如斜矢状面显示面神经全程）不失真。B正确：颞骨属极高对比结构，骨算法带来的高噪声可被接受，换取的是边缘锐利与细节可辨。C正确：靶重建（像素＝FOV/矩阵）是提高颞骨细节显示的常规手段，通常左右耳分别重建。D正确：颞骨骨窗需要极宽的窗宽（约4000 HU）才能同时容纳致密骨与气房内气体的巨大密度差。【为什么错】E错误：平滑核＋厚层会使听小骨与骨迷路轮廓模糊，从根本上违背HRCT的目的；颞骨HRCT允许较高噪声，但绝不允许分辨率下降。", "tr": "颞骨HRCT三要素：亚毫米薄层、骨算法、靶重建（小FOV）。同一原始数据还可另做软组织核重建观察腮腺、颈静脉孔区，二者互补而非互斥。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0161", "t": "案例分析题", "s": "患儿男，4岁，先天性双耳重度感音神经性听力损失，助听器效果不佳，拟行人工耳蜗植入术。术前需评估内耳发育情况、有无耳蜗骨化、面神经走行变异及蜗神经发育状况，以判断手术可行性与入路。患儿不能配合，需在镇静下完成影像检查。下列影像技术方案最合理的是", "o": {"A": "行颞骨HRCT薄层骨算法扫描并做多平面与斜位重组，重点评价耳蜗形态与骨化、内听道与前庭导水管、面神经管走行及乳突气化，同时结合内耳MRI水成像评价膜迷路与蜗神经", "B": "仅行头颅CT平扫，层厚5 mm，软组织算法重建", "C": "仅行颞骨CT增强扫描，通过强化评估内耳血供", "D": "行头颈部CTA评估内听动脉后决定手术方案", "E": "行颞骨CT灌注成像评价耳蜗血流灌注"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-161", "kp": "人工耳蜗植入术前影像评估", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】A正确。人工耳蜗术前评估需要“骨与膜”两方面信息：HRCT负责骨性结构——耳蜗圈数与畸形（如Mondini畸形）、鼓阶有无骨化闭塞、圆窗龛位置、面神经管有无前移变异（关系到手术安全）、前庭导水管扩大、乳突气化程度与乙状窦位置；MRI内耳水成像负责膜迷路液体信号与蜗神经是否存在及发育情况（蜗神经缺如是植入的重要限制）。二者互补，是国内外指南推荐的标准组合。【为什么错】B错误：5 mm软组织算法根本无法显示亚毫米级的内耳结构，属参数错误。C错误：内耳评估以平扫HRCT为主，增强对骨性结构与蜗神经评价无帮助，还增加风险。D错误：CTA评价的是大血管，与耳蜗植入的关键问题不对应。E错误：CT灌注不能评价内耳微循环，且剂量高、无临床依据。", "tr": "记住“CT看骨、MRI看神经与膜迷路”的分工。术前必须特别关注面神经管变异与蜗神经发育——前者关系手术安全，后者决定植入效果，二者分别由CT与MRI回答。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0162", "t": "单选题", "s": "关于耳部（颞骨）CT检查，下列说法错误的是", "o": {"A": "内耳与听小骨属高对比精细结构，需以薄层加骨算法方能清晰显示", "B": "冠状面（或冠状重组）有助于观察鼓室盖、面神经管鼓室段与半规管", "C": "中耳乳突炎症、胆脂瘤的评估通常平扫即可，怀疑颅内并发症时可加做增强", "D": "同一次薄层采集的数据可另行软组织算法重建，用于观察腮腺、颈静脉孔区等软组织", "E": "采用软组织平滑核重建即可清晰显示镫骨与砧镫关节等微细结构"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-162", "kp": "颞骨CT的算法与平面选择", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】本题选错误项，E错误。镫骨脚厚度不足0.5 mm，软组织平滑核会抑制高频信息、模糊边缘，使听小骨链与砧镫关节难以判断连续性，无法满足传导性聋的评估需求，必须使用高分辨率骨算法。【为什么错】A正确：这是颞骨HRCT的基本原则。B正确：冠状面对鼓室盖（判断有无骨质破坏、颅内并发症风险）、面神经管鼓室段与外半规管瘘的显示优于横断面。C正确：胆脂瘤主要看骨质破坏范围与听骨链侵蚀，平扫即可；疑有乙状窦血栓、脑脓肿等颅内并发症时才需增强或MRI。D正确：这是“一次采集、多种重建”的典型应用，不增加任何剂量。", "tr": "颞骨检查中最常见的技术失误就是算法选错。判断口诀依然是“高对比结构用锐利核”。另注意胆脂瘤本身在CT上是软组织密度影，其诊断依据是骨质破坏形态而非病灶强化。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0163", "t": "多选题", "s": "关于鼻与鼻窦CT检查技术，下列正确的有", "o": {"A": "冠状面图像最有利于显示窦口鼻道复合体（OMC）的解剖与阻塞情况", "B": "鼻窦区骨与气体形成天然高对比，可在保证诊断的前提下采用低剂量参数", "C": "应同时以骨窗和软组织窗观察，兼顾骨质结构与软组织病变", "D": "功能性内镜鼻窦手术前需重点评估筛板高度、纸样板完整性以及视神经管与蝶窦的关系", "E": "鼻窦CT检查前应常规口服稀释碘对比剂充盈上消化道"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-163", "kp": "鼻与鼻窦CT技术要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】A正确：OMC（包括钩突、筛漏斗、半月裂、上颌窦口与前组筛窦）主要位于冠状方向上，冠状面是评价其通畅性的标准平面，也是慢性鼻窦炎术前评估的核心。B正确：鼻窦区对比度极高，即使明显降低mAs仍可判断黏膜增厚与骨质，低剂量鼻窦CT已被广泛采用，对儿童与随访患者尤为重要。C正确：骨窗看骨质破坏、骨壁完整性与解剖变异，软组织窗看黏膜、息肉、真菌球内的高密度钙化与眶内／颅内侵犯。D正确：这三处是FESS手术的“危险区”，术前必须逐一评估，属技师应重点重组呈现的内容。【为什么错】E错误：口服对比剂用于腹部胃肠道显影，与鼻窦检查毫无关系，反而增加不必要的准备与风险。", "tr": "鼻窦题的高频判分点是“冠状面看OMC”与“术前危险区评估”。另注意真菌性鼻窦炎在软组织窗常见窦腔内高密度影，若只看骨窗容易忽略。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0164", "t": "单选题", "s": "关于鼻与鼻窦CT的扫描方式，下列说法正确的是", "o": {"A": "现多采用薄层横断面容积采集，再重组冠状面与矢状面图像，避免患者取俯卧过伸位的不适", "B": "必须采用直接冠状位扫描，任何重组图像都不能替代", "C": "扫描层厚以10 mm为宜，可缩短检查时间", "D": "鼻窦检查必须常规行增强扫描才能显示黏膜病变", "E": "观察鼻窦只需软组织窗，无须骨窗"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-164", "kp": "鼻窦CT的扫描方式", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】A正确。多层螺旋CT的薄层容积采集可获得各向同性数据，重组的冠状面图像质量已可与直接冠状扫描媲美，且患者只需仰卧、无须俯卧头过伸，明显提高舒适度与配合度，也避免了牙科充填物伪影方向的限制。【为什么错】B错误：直接冠状位在多层CT时代已非必需，且颈椎病变者难以配合。C错误：10 mm层厚无法显示钩突、筛板等细小结构，也不能满足重组需求。D错误：鼻窦炎症、息肉、解剖变异的评估以平扫为主，仅在怀疑肿瘤、眶内或颅内并发症时才增强。E错误：骨窗是鼻窦检查不可缺少的，用于判断骨壁破坏、骨质增生硬化与解剖变异。", "tr": "“必须直接冠状扫描”是老旧观念，在多层CT条件下应改为“容积采集＋多平面重组”。凡出现“任何重组都不能替代”这类绝对化表述的，多为错误项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0165", "t": "单选题", "s": "关于口腔颌面部CT检查技术，下列说法错误的是", "o": {"A": "薄层容积采集后可用曲面重建沿牙弓展开，获得类似曲面体层的全牙列与下颌骨图像", "B": "颌面部骨折评估需骨算法重建并结合三维容积再现，以显示骨折线走行与骨块移位", "C": "腮腺区病变宜用软组织算法重建，多需增强以判断病变范围、血供与面神经走行区关系", "D": "金属义齿或牙科充填物可产生放射状伪影，可通过倾斜机架、金属伪影校正算法或高keV虚拟单能量图像减轻", "E": "口腔颌面部检查应统一采用软组织算法与10 mm层厚，以降低辐射剂量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-165", "kp": "口腔颌面部CT检查技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (6)口腔颌面部", "ex": "【为什么对】本题选错误项，E错误。10 mm层厚无法显示牙槽骨、下颌管、颏孔与细小骨折线，也不能满足曲面重建与三维重组对各向同性薄层数据的要求；降低剂量应通过优化管电压、自动管电流调制与迭代重建实现，而不是牺牲层厚与算法。【为什么错】A正确：沿牙弓勾画中心线做CPR可一幅图显示全牙列，是种植牙术前与颌骨病变评估的常规后处理。B正确：颌面部骨折形态复杂，三维VR有助于整体理解骨折类型与移位方向，骨算法保证骨皮质边缘锐利。C正确：腮腺属软组织器官，需软组织核＋增强以判断肿瘤边界、深浅叶关系与血供。D正确：这三种手段是牙科金属伪影的标准应对措施。", "tr": "颌面部同时涉及“骨（需锐利核）”与“腺体（需平滑核）”，正确做法是一次薄层采集、双算法重建。凡以“降低剂量”为名主张加厚层厚的选项通常是错的。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0166", "t": "多选题", "s": "关于颞下颌关节CT检查技术，下列正确的有", "o": {"A": "常规做闭口位与开口位对照，以评价髁突的活动度与位置关系", "B": "斜矢状面（垂直于髁突长轴）图像用于显示髁突与关节窝的前后关系及关节间隙", "C": "斜冠状面图像有助于观察髁突内外侧的骨质改变", "D": "需采用薄层采集与骨算法重建，以显示髁突骨皮质与关节面的细微改变", "E": "关节盘的显示CT优于MRI，故关节盘移位应首选CT检查"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-166", "kp": "颞下颌关节CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (6)口腔颌面部", "ex": "【为什么对】A正确：开闭口位对比是判断髁突活动受限、半脱位与强直的关键，属颞下颌关节检查的规定动作。B正确：斜矢状面垂直于髁突长轴，能真实反映关节前、上、后间隙宽度与髁突位置。C正确：斜冠状面显示髁突内外极骨质硬化、囊变与骨赘。D正确：关节面骨质改变细微，需薄层与骨算法。【为什么错】E错误：关节盘为纤维软骨结构，CT难以直接显示，MRI是关节盘移位、穿孔与关节积液评估的首选与金标准；CT的优势在于骨质改变（骨赘、囊变、强直、骨折）。", "tr": "颞下颌关节“骨看CT、盘看MRI”。另注意两种斜位平面的定位方式：斜矢状面垂直于髁突长轴、斜冠状面平行于髁突长轴，方向易混。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0167", "t": "单选题", "s": "关于喉部CT检查技术，下列说法错误的是", "o": {"A": "扫描层面一般与声带平面（或颈椎椎间隙）平行，层厚2~3 mm或更薄", "B": "检查中嘱患者平静呼吸、避免吞咽与咳嗽，以减少运动伪影", "C": "必要时可嘱患者持续发“衣（e）”音使声带内收，或用改良Valsalva动作（鼓气）使梨状窝与会厌谷扩张，从而显示黏膜面", "D": "增强扫描有助于判断肿瘤范围、喉软骨受侵与颈部淋巴结转移", "E": "扫描过程中应嘱患者反复做吞咽动作，使会厌与声带活动开来以便观察"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-167", "kp": "咽喉部CT扫描技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】本题选错误项，E错误。吞咽会使喉体上下大幅移动，产生严重运动伪影甚至层面遗漏，是喉部CT必须避免的动作；需要动态观察时用的是发音（“e”音）或改良Valsalva等可控、可维持的动作，而非吞咽。【为什么错】A正确：使层面与声带平面平行可避免声带被斜切造成的假性增厚。B正确：平静呼吸下声带外展、声门裂张开，是常规采集状态。C正确：发“e”音使声带内收有助于观察声带活动与前联合；改良Valsalva使梨状窝、会厌谷等隐窝扩张，可显示早期黏膜病变。D正确：喉癌的分期高度依赖增强图像判断软骨侵犯、声门旁间隙与会厌前间隙受累及淋巴结转移。", "tr": "“可控动作（发音、鼓气）”与“不可控动作（吞咽、咳嗽）”是咽喉部检查的分水岭。前者是技术手段，后者是伪影来源。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0168", "t": "案例分析题", "s": "患者男性，62岁，声嘶3个月，喉镜见右侧声带新生物，活检为鳞状细胞癌。临床需评估肿瘤深部浸润范围、声门旁间隙与甲状软骨有无受侵，以及颈部淋巴结转移情况，以决定行部分喉切除还是全喉切除。患者上颌与下颌共有6颗金属烤瓷牙冠。设备为64排CT，具备金属伪影校正与能量成像功能。下列检查方案最合理的是", "o": {"A": "行颈部薄层（≤2 mm）容积增强扫描，注药后约40~50 s采集，范围自颅底至胸廓入口，扫描时平静呼吸、不吞咽、双肩下拉；对牙冠层面采用金属伪影校正或高keV虚拟单能量重建，并加做冠状、矢状重组", "B": "仅行颈部平扫，层厚5 mm，软组织算法重建", "C": "行颈部增强扫描但把延迟时间设为注药后120 s，以获得均匀的静脉期强化", "D": "嘱患者全程持续发“衣（e）”音下完成整个增强扫描，以最大程度显示声带", "E": "先行胸部CT除外远处转移，喉部只做定位像观察即可"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-168", "kp": "喉癌术前CT评估方案", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】A正确。喉癌术前评估要求：薄层增强以判断黏膜下浸润、声门旁与会厌前间隙受累及软骨侵蚀；约40~50 s的延迟兼顾肿瘤强化与淋巴结显示；范围需含颅底至胸廓入口以覆盖各区淋巴结；平静呼吸不吞咽、双肩下拉可减少运动与肩部硬化伪影；针对金属牙冠采用MAR或高keV单能量重建可挽救被伪影污染的层面；多平面重组有助于显示肿瘤上下范围与环状软骨关系，直接影响术式选择。【为什么错】B错误：平扫不能判断软组织浸润深度与淋巴结性质，5 mm层厚亦不足。C错误：120 s属实质／延迟期，肿瘤与正常组织的对比下降，血管与淋巴结分辨也变差。D错误：全程持续发音无法维持数十秒且会造成运动伪影，发音扫描只用于短时补充采集。E错误：本题的临床问题是原发灶分期，不能以定位像代替诊断性扫描。", "tr": "喉癌分期的关键技术点是“薄层＋合适期相＋多平面重组＋伪影控制”。注意金属伪影不是无解的：MAR算法与高keV单能量图像是现代设备的标准武器，比单纯重复扫描有效得多。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0169", "t": "多选题", "s": "关于颈部及甲状腺CT检查与碘对比剂使用，下列正确的有", "o": {"A": "正常甲状腺因含碘丰富，平扫CT值明显高于周围肌肉，一般可达80~100 HU", "B": "近期拟行放射性碘显像或131I治疗者，应避免在此之前使用碘对比剂，通常需间隔数周", "C": "甲状腺功能亢进未控制者使用碘对比剂有诱发甲状腺危象的风险，应慎用并加强观察", "D": "颈部增强扫描有助于区分肿大淋巴结与血管断面，并判断淋巴结有无坏死", "E": "甲状腺病变的CT检查必须口服碘对比剂充盈食管后才能进行"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-169", "kp": "颈部与甲状腺检查的对比剂问题", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】A正确：甲状腺是全身唯一在平扫上呈明显高密度的软组织器官，其CT值下降本身即提示弥漫性病变。B正确：静脉注射的碘负荷会使甲状腺碘池饱和，显著影响放射性碘的摄取，从而干扰显像与治疗效果，故需间隔数周（一般4~8周，具体遵核医学科要求）。C正确：碘负荷可能诱发碘甲亢或甲状腺危象，甲亢未控制者属慎用人群。D正确：增强后血管明显强化、与淋巴结区分开，淋巴结内的坏死区与环形强化是转移的重要征象。【为什么错】E错误：食管充盈不是甲状腺CT的必需步骤；口服对比剂主要用于腹部胃肠道，颈部检查通常无须口服，必要时仅做少量吞服以标记食管，但绝非“必须”。", "tr": "“碘对比剂会影响后续核素检查与治疗”是技师应主动向临床与患者说明的要点，属于检查前沟通的重要内容。另注意平扫甲状腺高密度这一常识，常被用来设计“平扫高密度病灶”的辨析题。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0170", "t": "单选题", "s": "关于颈部软组织CT检查技术，下列说法错误的是", "o": {"A": "扫描范围一般自颅底至胸廓入口，必要时向下包括上纵隔", "B": "患者仰卧，双肩尽量下垂，可用束带向足侧牵拉，以减轻肩部造成的硬化伪影", "C": "采用薄层容积采集，便于冠状与矢状重组评价病变与大血管、气道的关系", "D": "增强延迟一般在注药后40~60 s，兼顾动脉、静脉与淋巴结的强化", "E": "扫描时应嘱患者双上肢上举过头，以减少肩部对射线的衰减"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-170", "kp": "颈部CT扫描范围与体位", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】本题选错误项，E错误。双上肢上举过头是胸部与腹部检查的体位，可使上肢移出扫描野；而颈部检查扫描野在颈根部，上举双臂不仅无法移出肩部，还会使肩胛带上抬、堆积于颈根，加重胸廓入口区的伪影。颈部检查的正确做法是双臂置于体侧、双肩尽量下垂并向足侧牵拉。【为什么错】A正确：这是颈部检查的常规覆盖范围，可包含颈部各区淋巴结。B正确：肩部下拉是减轻胸廓入口区硬化伪影的关键体位技巧。C正确：颈部结构与血管、气道关系密切，多平面重组价值大。D正确：40~60 s的单期延迟兼顾动静脉与淋巴结强化，是颈部常用的增强时相。", "tr": "“双臂上举”只适用于胸腹部。颈部、颅脑、颌面部检查双臂必须置于体侧并尽量下拉肩部——体位题的常见反向陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0171", "t": "单选题", "s": "颈胸交界区（胸廓入口、肩部）CT图像上常出现明显的条纹状伪影，其主要成因与对策是", "o": {"A": "双肩部位射线路径长、衰减差异大，造成线束硬化与光子饥饿；对策为双肩下拉、适当提高管电流或使用自动管电流调制与硬化校正、迭代重建算法", "B": "呼吸运动所致；对策是改行增强扫描", "C": "对比剂用量过大所致；对策是减少对比剂总量", "D": "探测器通道失校所致；对策是重新进行空气校正", "E": "患者头部过度后仰所致；对策是抬高床面"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-171", "kp": "胸廓入口区伪影的成因与对策", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】A正确。肩部横径大、骨与软组织混合，前后位方向的射线路径明显长于侧方，低能光子被大量吸收（线束硬化）且到达探测器的光子严重不足（光子饥饿），表现为水平方向的条纹状伪影。对策包括：体位上双肩尽量下拉；参数上提高该区域mAs（自动管电流调制可自动增大肩部曝光）；算法上使用线束硬化校正、迭代重建，必要时用高keV虚拟单能量图像。【为什么错】B错误：颈部扫描很快，呼吸不是主要成因，且增强不能减轻硬化伪影。C错误：对比剂过量可造成血管旁条纹，但典型的肩部伪影在平扫上同样存在。D错误：探测器失校表现为环状伪影，而非局限于肩部的条纹。E错误：头位后仰影响的是扫描基线与解剖对称性，不是该伪影的成因。", "tr": "分清三类常见伪影的“形态指纹”：环状＝探测器失校；肩部／后颅窝的粗条纹＝硬化与光子饥饿；放射状锐利条纹＝金属；重影／双边＝运动。看形态即可反推成因与对策。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0172", "t": "单选题", "s": "关于胸部常规CT扫描技术，下列说法错误的是", "o": {"A": "常规取仰卧位、双臂上举过头，以避免上肢造成的伪影", "B": "扫描范围自肺尖至肺底并包括双侧肋膈角，需要时可下延至肾上腺水平", "C": "采用深吸气后屏气采集，使肺充分膨胀、减少坠积效应", "D": "图像应同时以肺窗和纵隔窗观察", "E": "胸部扫描可省略定位像，直接按经验范围开始采集"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-172", "kp": "胸部常规CT扫描技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】本题选错误项，E错误。定位像（scout/topogram）是确定扫描起止范围、设置自动管电流调制与器官剂量调制的依据，省略后既可能漏扫病变区域，也使剂量调制无法工作，属原则性错误。【为什么错】A正确：双臂上举可把肱骨与肩胛带移出扫描野，显著减轻伪影。B正确：包全肋膈角避免遗漏胸膜病变，怀疑肺癌分期时常规下延至肾上腺以观察转移。C正确：深吸气屏气使肺泡充分扩张，改善病灶与含气肺的对比，减少肺底坠积影响。D正确：肺窗与纵隔窗提供互补信息，任何一个都不可省。", "tr": "定位像不仅决定范围，还是ATCM剂量调制的基础，其摆位偏差（如患者未居中）会导致管电流估算错误、剂量偏高或图像噪声偏大——这是容易被忽视的质量控制细节。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0173", "t": "多选题", "s": "关于胸部CT图像的窗技术与后处理，下列正确的有", "o": {"A": "肺窗与纵隔窗须同时观察，前者显示肺实质与间质，后者显示纵隔、胸膜与胸壁结构", "B": "冠状面与矢状面重组有助于判断病变的分布特点及其与叶间裂、胸膜、气道的关系", "C": "薄层最大密度投影有助于小结节的检出与血管的鉴别，最小密度投影有助于气道及低密度病变的显示", "D": "纵隔窗观察肺内病变的能力优于肺窗，故肺结节评价应以纵隔窗为主", "E": "为提高信噪比，评价肺间质病变时应增大重建层厚"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-173", "kp": "胸部CT窗技术与重组", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】A正确：肺内含气结构与纵隔软组织的CT值跨度极大，单一窗口无法兼顾，必须双窗观察。B正确：多平面重组能直观显示病变沿支气管血管束、胸膜下或小叶中心的分布模式，这是弥漫性肺病鉴别的重要依据。C正确：薄层MIP把连续几毫米内的高密度结构投影到一幅图上，使小结节“凸显”并可与走行连续的血管区分；MinIP则突出气道、肺气肿与磨玻璃背景中的低密度区。【为什么错】D错误：纵隔窗窗宽窄、窗位高，肺内绝大部分结构落在窗下限之外呈一片黑，无法评价肺结节；纵隔窗在肺内的作用仅限于判断病灶内钙化、脂肪与实性成分。E错误：加厚层厚会因部分容积效应模糊小叶间隔与细支气管壁，使间质病变显示能力下降；间质评价恰恰需要薄层高分辨率。", "tr": "MIP与MinIP的用途方向相反：MIP找“高密度的点”（结节、钙化、强化血管），MinIP找“低密度的腔”（气道、肺气肿）。另注意二者都必须与原始薄层对照，不能单独用于诊断。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0174", "t": "单选题", "s": "关于低剂量CT（LDCT）肺癌筛查，下列说法错误的是", "o": {"A": "筛查用LDCT不使用静脉对比剂", "B": "有效剂量一般控制在1~2 mSv以内，可通过降低管电流、适当降低管电压并结合迭代重建实现", "C": "重建层厚应≤1 mm，以利于小结节的检出与体积定量", "D": "筛查主要面向具备明确危险因素的高危人群，而非全人群普查", "E": "为提高小结节检出率，筛查应改用常规剂量的增强扫描"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-174", "kp": "低剂量CT肺癌筛查", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】本题选错误项，E错误。肺结节与含气肺组织之间存在天然的高对比，低剂量条件下噪声虽增加，但对结节检出的影响很小；改用常规剂量增强既大幅提高受检者的辐射与对比剂风险，又违背筛查“对健康人群大规模、低危害”的基本前提，且增强对结节检出并无额外收益。【为什么错】A正确：筛查为平扫，不用对比剂。B正确：这是LDCT的剂量目标与常用实现手段。C正确：薄层重建是准确测量结节直径／体积、判断磨玻璃成分的前提。D正确：筛查的成本效益建立在高危人群基础上，指南对年龄与吸烟史等有明确限定。", "tr": "筛查与诊断是两种不同性质的检查：筛查追求“低危害、可重复、高检出”，诊断追求“定性准确”。把诊断性方案（增强、多期、常规剂量）套用到筛查上，是概念性错误。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0175", "t": "单选题", "s": "某患者右肺下叶8 mm实性结节，3个月后复查CT以判断结节有无增大。为使前后两次结果具有可比性，下列做法中最重要的是", "o": {"A": "尽量沿用与前次相同的扫描与重建参数（层厚、卷积核、体位与屏气状态），并用同一测量方法在同一后处理软件上进行比较，优先采用半自动体积测量", "B": "本次改用更高剂量扫描，以提高测量精度", "C": "本次改行增强扫描，通过强化值变化判断结节性质改变", "D": "在两台不同厂家的工作站上分别测量后取平均值", "E": "仅凭肉眼在不同层厚的图像上比较结节最大径"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-175", "kp": "肺结节随访的技术一致性", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】A正确。结节随访判断的是“变化”而非“绝对值”，测量的可重复性压倒一切。层厚、卷积核、屏气状态、软件算法都会系统性影响直径与体积测量结果，8 mm结节直径测量的观察者间误差可达1~2 mm，足以掩盖真实生长；采用一致的参数与同一软件的半自动体积测量，可显著降低变异并可计算体积倍增时间。【为什么错】B错误：提高剂量对测量一致性帮助有限，却增加了受照负担，且与前次参数不一致反而引入偏差。C错误：增强并非结节随访的常规手段，强化值受时相与方法影响大，重复性差。D错误：不同软件的分割算法不同，混合测量只会放大变异。E错误：不同层厚下的最大径肉眼比较误差最大，是最不可靠的做法。", "tr": "随访题的判分点永远是“一致性”：同参数、同软件、同方法。体积测量优于二维直径，但也必须在同一算法下纵向比较；跨设备、跨软件的数值不能直接对比。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0176", "t": "多选题", "s": "关于肺动脉CT血管成像（CTPA）的技术要点，下列正确的有", "o": {"A": "团注追踪的监测ROI应置于肺动脉主干（或右心室流出道），阈值多取100 HU左右", "B": "使用相对较少的对比剂并配合生理盐水冲刷，可减轻上腔静脉内高浓度对比剂造成的条纹伪影", "C": "宜采用平静吸气后屏气，避免深大吸气引起一过性对比剂中断", "D": "肺动脉强化不足时，可考虑把管电压降至80~100 kVp以提高碘的对比效率", "E": "心电门控是CTPA的常规必备条件，无门控无法诊断肺栓塞"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-176", "kp": "CTPA的关键技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】A正确：ROI置于目标血管上游的肺动脉主干，可在肺动脉充盈高峰时触发，避免过早或过晚。B正确：右心与上腔静脉内未稀释的高浓度对比剂是右肺动脉旁条纹伪影的主要来源，减量＋盐水冲刷是标准对策。C正确：深大吸气会使下腔静脉未强化血液大量回流右心，稀释肺动脉内对比剂，形成一过性对比剂中断（TIC），是CTPA失败的常见原因。D正确：低kV使碘的衰减显著增强，在肺动脉这种以碘为唯一对比来源的场景中收益尤其明显，还可同步减少对比剂用量。【为什么错】E错误：CTPA常规不使用心电门控。心电门控主要用于评估升主动脉根部与冠脉，或在“胸痛三联”一站式扫描中使用；单纯肺栓塞诊断依靠快速采集即可，加门控反而延长扫描时间、增加剂量。", "tr": "TIC（一过性对比剂中断）是CTPA的标志性技术陷阱，须与真正的充盈缺损鉴别：TIC表现为肺动脉整体强化差、下腔静脉内可见未强化血液分层，而非局限性、边界清楚的充盈缺损。对策是呼吸指令而非加大剂量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U09-0177", "t": "案例分析题", "s": "患者女性，45岁，术后卧床，突发胸闷气促，临床疑肺栓塞行CTPA。技师按“深吸气后屏住”的指令进行扫描，团注追踪ROI置于肺动脉主干、阈值100 HU。图像显示肺动脉主干强化仅约150 HU，段以下肺动脉显示模糊，右心房内可见未强化血液与对比剂形成的分层混合影，上腔静脉内高密度对比剂伴明显条纹伪影，患者配合良好、无明显体动。造成该结果最可能的原因与最合理的改进措施是", "o": {"A": "深大吸气使胸腔负压增加，下腔静脉未强化血液大量回流右心，稀释了肺动脉内对比剂，形成一过性对比剂中断；应改用平静吸气后屏气，并适当优化触发阈值与诊断延迟，必要时提高碘流率或降低管电压", "B": "患者发生了对比剂过敏反应，导致循环中对比剂浓度下降；应立即停止检查并抗过敏治疗", "C": "探测器通道失校造成CT值测量偏低；应立即进行空气校正后重扫", "D": "螺距设置过小导致扫描时间延长；应减小螺距重新扫描", "E": "患者体重过大造成噪声增高；应把层厚增大至5 mm重建以改善强化显示"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-177", "kp": "CTPA强化不足的原因分析", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】A正确。题干提供了三条关键线索：肺动脉强化偏低、右心房内出现未强化血液与对比剂的分层、上腔静脉高浓度对比剂伴条纹伪影——这正是一过性对比剂中断的典型影像组合，机制是深吸气造成胸腔负压骤增、下腔静脉血流突然增加而稀释了经上腔静脉进入右心的对比剂。改进措施首先是把呼吸指令改为“平静吸气后屏气”，其次可优化触发与延迟、提高碘流率或降低kV以提升碘对比。【为什么错】B错误：过敏反应表现为皮疹、喉头水肿、低血压等临床症状，不会造成这种特定的血流稀释影像，且患者情况平稳。C错误：探测器失校的表现是环状伪影与全图CT值异常，而非局限于右心的分层现象。D错误：螺距过小只会延长扫描时间、增加剂量，不产生右心分层影，减小螺距更是南辕北辙。E错误：体重相关的是噪声而非强化程度，且增大层厚只能降噪，不能改善对比剂浓度。", "tr": "遇到“肺动脉强化不足”先看右心与下腔静脉：出现未强化血液分层＝TIC（呼吸原因）；若整体循环时间延长、各腔均强化滞后＝低心排（应改用小剂量测试）。二者对策完全不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0178", "t": "多选题", "s": "关于先天性心脏病的CT检查技术，下列正确的有", "o": {"A": "婴幼儿宜采用低管电压（70~80 kVp）配合迭代重建，以提高碘对比并降低辐射剂量", "B": "采用大螺距快速扫描或前瞻性心电触发，可在自由呼吸或极短屏气下完成采集，减少镇静需求", "C": "对比剂按体重计算（一般1.5~2.0 ml/kg），经细留置针以较低流率注射并配合生理盐水冲刷", "D": "需结合多平面重组、最大密度投影与容积再现，全面显示心内结构、大血管连接与侧支血管", "E": "先心病CT必须常规采用回顾性心电门控全期相扫描，否则无法显示心内结构"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-178", "kp": "先天性心脏病CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (10)先天性心脏病", "ex": "【为什么对】A正确：婴幼儿体厚小，低kV既能显著提升碘的CT值，又可大幅降低剂量，是儿童心血管CT的核心策略。B正确：亚秒级采集使自由呼吸下也能获得可诊断图像，从而减少镇静与麻醉需求，这对婴幼儿的安全意义重大。C正确：儿童血管细，只能用较细留置针与较低流率，靠“低kV＋高浓度／按体重计量＋盐水冲刷”保证强化。D正确：先心病的诊断需要空间关系信息，MPR看断面细节、MIP看血管连续性、VR看整体连接与侧支，三者互补。【为什么错】E错误：回顾性门控辐射剂量高，在儿童中应尽量避免；多数先心病以显示解剖结构与大血管连接为目的，用前瞻性触发或大螺距非门控扫描即可，只有在需要评价心功能或瓣膜运动时才考虑回顾性门控。", "tr": "儿童心血管CT的原则是“能不门控就不门控、能不镇静就不镇静”。凡出现“必须回顾性门控”“必须麻醉”的绝对化选项，基本都是错误项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0179", "t": "案例分析题", "s": "患儿女，6个月，体重6 kg，自出生后间断口唇发绀，超声心动图提示复杂先天性心脏病，疑法洛四联症，需进一步评估肺动脉分支发育情况、有无体肺侧支血管及冠状动脉走行，为手术方案提供依据。患儿哭闹明显，静脉通路为右上肢24 G留置针。设备为具备大螺距扫描与迭代重建功能的多层CT。下列检查方案最合理的是", "o": {"A": "采用70~80 kVp低管电压、自动管电流调制与迭代重建，行大螺距或前瞻性心电触发采集；对比剂按1.5~2.0 ml/kg经右上肢静脉以适宜的低流率注射并盐水冲刷，用团注追踪或小剂量测试确定时相，采集后行MPR、MIP与VR重组", "B": "按成人冠状动脉CTA方案行回顾性心电门控全期相扫描，以获得最完整的信息", "C": "行胸部平扫即可，通过心影形态推断畸形类型", "D": "口服稀释碘对比剂后行胸部扫描，以避免静脉穿刺", "E": "此类患儿应完全以心脏MRI替代CT，不宜行CT检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-179", "kp": "婴幼儿复杂先心病CT方案", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (10)先天性心脏病", "ex": "【为什么对】A正确。该方案同时满足三个要求：一是安全，低kV＋剂量调制＋迭代重建把剂量压到最低，大螺距／前瞻触发把采集时间压到最短从而减少镇静需求；二是有效，按体重给药并用盐水冲刷保证肺动脉与侧支血管足够强化，团注追踪或小剂量测试解决婴儿循环时间快、个体差异大的问题；三是完整，MPR／MIP／VR联合重组可全面展示肺动脉分支发育、体肺侧支与冠脉走行。【为什么错】B错误：回顾性门控剂量高，对以解剖评价为主的先心病属过度检查，对6个月婴儿尤为不适宜。C错误：平扫无法评价肺动脉分支与侧支血管，心影形态推断远不能满足手术需要。D错误：口服对比剂只能显示消化道，与心血管评估无关。E错误：MRI虽无辐射，但检查时间长、婴儿需较深镇静，对小的体肺侧支与冠脉的空间分辨率不及CTA，二者互为补充而非替代。", "tr": "婴幼儿心血管CTA的取舍逻辑是“先缩短时间、再压低剂量、最后保证强化”。注意注射侧的选择与盐水冲刷同样重要：对比剂滞留于上腔静脉可造成右心与邻近结构的严重条纹伪影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0180", "t": "单选题", "s": "关于冠状动脉钙化积分（Agatston积分）的扫描与计算，下列说法错误的是", "o": {"A": "采用非增强扫描，多以前瞻性心电触发的轴位方式采集", "B": "经典标准方案采用3 mm层厚、120 kVp管电压，以保证与既往研究和随访数据可比", "C": "钙化的判定阈值为CT值≥130 HU且达到规定的最小面积", "D": "Agatston积分由每个钙化斑块的面积乘以与其峰值CT值相对应的权重系数后累加得到", "E": "钙化积分应在注射对比剂后的动脉期图像上测量，以便同时评价管腔狭窄"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-180", "kp": "冠状动脉钙化积分", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】本题选错误项，E错误。钙化积分必须在平扫图像上测量：注入对比剂后管腔内的高密度碘会被误判为钙化，使积分严重高估、失去与流行病学数据的可比性。评价管腔狭窄是随后冠脉CTA的任务，二者分别在平扫与增强图像上完成。【为什么错】A正确：前瞻性触发轴扫可在保证心动周期同一时相的前提下把剂量降到最低（通常约1 mSv）。B正确：3 mm层厚、120 kVp是Agatston积分的经典标准，改变层厚或kV会改变积分数值，故随访必须沿用同一方案。C正确：130 HU是标准阈值，同时要求钙化灶达到一定面积或像素数以排除噪声。D正确：权重系数按病灶内峰值CT值分级（130~199、200~299、300~399、≥400分别对应1、2、3、4），面积乘以权重再累加即为总积分。【补充】重度钙化会因部分容积与开花效应高估管腔狭窄，这是冠脉CTA的固有局限。", "tr": "钙化积分的三个“固定”：固定平扫、固定3 mm层厚、固定120 kVp。随访时任何参数改变都会使积分不可比，这是技师必须坚守的质控点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0181", "t": "多选题", "s": "关于冠状动脉CTA检查前使用β受体阻滞剂控制心率，下列正确的有", "o": {"A": "目标是把心率控制在65次/分以下且心律规整，以获得足够的时间分辨率窗口", "B": "口服美托洛尔一般在检查前约1小时给药；心率控制不佳且情况紧急时可在医师监护下静脉分次给药", "C": "支气管哮喘或慢性阻塞性肺疾病急性发作、二度及以上房室传导阻滞、失代偿性心力衰竭、收缩压低于100 mmHg者属禁忌或慎用", "D": "给药后须持续监测心率与血压，警惕严重心动过缓与低血压", "E": "心率越低图像越好，应尽量把心率降至40次/分左右"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-181", "kp": "冠脉CTA的心率控制", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】A正确：心率越低，舒张中晚期的相对静止窗越长，单扇区重建即可获得满意的时间分辨率；心律规整则是保证各扇区数据来自同一时相的前提。B正确：口服起效需约1小时，静脉给药起效快但必须在医师监护、具备心电与血压监测条件下分次滴定。C正确：β受体阻滞剂可诱发支气管痉挛、加重传导阻滞与心力衰竭、引起低血压，上述人群禁用或慎用，必要时改用其他策略（如钙通道阻滞剂或依赖设备的高时间分辨率技术）。D正确：给药后监测是安全底线，出现严重心动过缓需及时处理。【为什么错】E错误：把心率压到40次/分左右不但没有额外的图像收益，还会引起头晕、乏力甚至血流动力学不稳；临床目标是“足够低且稳定”（一般55~65次/分），不是越低越好。", "tr": "“更低更好”式的选项通常是错的。另需记住：心律齐与心率低同等重要，房颤患者即使心率不快，图像质量也可能很差，此时更依赖设备的时间分辨率与心电编辑。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0182", "t": "单选题", "s": "关于冠状动脉CTA检查前使用硝酸甘油，下列说法错误的是", "o": {"A": "目的是扩张冠状动脉、增大管腔直径，改善远段与细小分支的显示", "B": "常用舌下含服0.5 mg（或用喷雾剂），一般在扫描前3~5分钟给予", "C": "用药后可出现头痛、面色潮红与一过性血压下降，应事先告知并监测", "D": "近期（24~48小时内）使用过磷酸二酯酶5抑制剂（如西地那非）者及明显低血压者禁用", "E": "硝酸甘油同时具有明确的减慢心率作用，可代替β受体阻滞剂用于心率控制"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-182", "kp": "冠脉CTA中硝酸甘油的应用", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】本题选错误项，E错误。硝酸甘油是血管扩张剂，可因外周血管扩张、血压下降而引起反射性心动过速，非但不能减慢心率，反而常使心率上升，因此临床上通常在β受体阻滞剂使心率稳定之后再给硝酸甘油，二者作用完全不同、不可互相替代。【为什么错】A正确：冠脉扩张可使管腔直径增加约10%~20%，明显改善远段与分支显示，减少假阳性狭窄。B正确：舌下给药起效快，3~5分钟达效，与扫描时机匹配。C正确：头痛与潮红是最常见的不良反应，事先告知可减少患者紧张与体动。D正确：硝酸酯类与PDE5抑制剂合用可致严重低血压，属明确禁忌；严重主动脉瓣狭窄、肥厚梗阻性心肌病与明显低血压者亦应避免。", "tr": "冠脉CTA的两种药物分工要牢记：β受体阻滞剂降心率、硝酸甘油扩血管，后者还可能引起反射性心动过速。给药顺序一般是先控心率、后扩冠脉。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0183", "t": "单选题", "s": "某患者行冠状动脉CTA，采用回顾性心电门控螺旋采集，扫描时平均心率约80次/分并伴轻度不齐。关于重建期相的选择，最合理的做法是", "o": {"A": "优先在收缩末期（约R-R间期35%~45%）重建，同时在舒张中晚期（约70%~80%）重建作为对照，逐支血管择优选择", "B": "仅在R-R间期75%处重建，因该期相为公认的最佳期相", "C": "仅在R-R间期0%~10%处重建，以避开心脏运动", "D": "固定在R-R间期50%处重建，取心动周期的中点最为稳妥", "E": "心率越快应把重建期相越向后移，故本例宜统一在90%处重建"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-183", "kp": "冠脉CTA最佳重建期相的选择", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】A正确。心动周期中有两个相对静止窗：舒张中晚期（约70%~80%）与收缩末期（约35%~45%）。心率增快时舒张期显著缩短，而收缩末期相对稳定，故高心率（一般＞75次/分）患者优先在收缩末期重建；同时保留舒张期重建作对照，并按不同血管（右冠常在收缩末期更佳，左前降支多在舒张期更佳）分别择优，是回顾性门控的标准工作流程。【为什么错】B错误：75%只是低心率时的经验最佳值，对80次/分且不齐的患者常不适用。C错误：0%~10%处于R波顶点与等容收缩期，心脏运动剧烈，是最差的重建时相之一。D错误：50%附近多处于收缩中期，室壁与冠脉运动速度高，通常伪影明显。E错误：期相并非随心率一味后移；90%已接近下一次心房收缩，运动伪影明显。", "tr": "两个静止窗的口诀：“慢心率取舒张（70%~80%），快心率取收缩末（35%~45%）”。同时记住可按血管分别择优重建，而不是全心统一使用一个期相。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0184", "t": "单选题", "s": "关于基于CT的血流储备分数（FFR-CT），下列说法正确的是", "o": {"A": "它利用常规冠状动脉CTA的图像数据，通过计算流体力学模拟得出血流储备分数，一般无须额外扫描或使用血管扩张药物", "B": "必须在腺苷负荷状态下另做一次CT扫描才能计算", "C": "结果以数值≥0.80提示存在心肌缺血", "D": "它可以完全取代冠脉CTA的形态学评价", "E": "严重钙化、运动伪影或图像质量不佳并不影响其计算的可靠性"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-184", "kp": "FFR-CT的原理与应用", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】A正确。FFR-CT在已获得的冠脉CTA数据基础上重建冠脉树几何模型，结合生理学边界条件用计算流体力学模拟最大充血状态下的压力比值，从而在不额外扫描、不使用腺苷的前提下提供功能学信息，实现“一次扫描、形态＋功能”。【为什么错】B错误：无须腺苷负荷与追加扫描，这正是其相对于负荷心肌灌注的优势。C错误：判读方向相反，通常FFR（含FFR-CT）≤0.80提示病变具有血流动力学意义，＞0.80提示缺血可能性小。D错误：FFR-CT是对形态学评价的补充，其模型本身建立在高质量CTA图像之上，不能取代之。E错误：严重钙化、运动伪影、错层与信噪比过低都会影响管腔分割精度，从而降低计算可靠性，图像质量是FFR-CT的前提条件。", "tr": "FFR的阈值方向是最易记反的点：数值越低越缺血，≤0.80为阳性。另注意FFR-CT“依赖图像质量”，因此规范的心率控制、屏气与伪影管理仍是技师的核心职责。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0185", "t": "多选题", "s": "关于CT评价心功能，下列正确的有", "o": {"A": "回顾性心电门控采集的数据可按一定间隔（如每10%）重建出覆盖整个心动周期的图像", "B": "由舒张末期容积与收缩末期容积可计算每搏输出量与左心室射血分数", "C": "全期相图像可用电影方式回放，观察室壁运动异常", "D": "前瞻性心电触发的窄窗采集通常只覆盖部分时相，一般不能提供完整的心功能信息", "E": "心功能评价应在平扫图像上完成，无须注射对比剂"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-185", "kp": "CT心功能评价", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】A正确：回顾性门控在整个心动周期持续曝光，因而可在任意时相重建，通常以10%为间隔重建10个期相。B正确：分别在舒张末期与收缩末期勾画心内膜，得到EDV与ESV，进而计算SV＝EDV－ESV、EF＝SV/EDV×100%。C正确：多期相电影回放是评价节段性室壁运动异常的基础。D正确：前瞻性触发只在预设的窄时相窗曝光（如70%~80%），数据不足以覆盖收缩末期，故一般无法评价心功能；若需心功能可用宽窗（padding）或回顾性门控，代价是剂量增加。【为什么错】E错误：心内膜面的勾画依赖心腔内血液与心肌之间的密度差，必须有对比剂充盈心腔才能准确分割，平扫无法完成。", "tr": "剂量与信息的取舍关系必须清楚：前瞻性触发低剂量但只有形态，回顾性门控高剂量但可得心功能。技师应按临床问题选择，而不是一律用回顾性门控“求全”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0186", "t": "多选题", "s": "关于心房颤动射频消融术前肺静脉与左心房CT检查，下列正确的有", "o": {"A": "主要评估肺静脉的数目、开口形态、开口内径及变异（如左侧共干、右侧副肺静脉）", "B": "需评估左心耳形态并判断有无血栓；血流淤滞所致的充盈缺损与真性血栓可借助延迟扫描鉴别", "C": "宜采用心电门控采集以减轻心脏搏动伪影，扫描范围须包全左心房与全部肺静脉", "D": "三维重组与左心房内镜视图可为术中三维导航系统提供解剖配准图像", "E": "该检查以评价冠状动脉狭窄程度为首要目的"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-186", "kp": "肺静脉与左心房CT检查", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (12)肺静脉与左心房", "ex": "【为什么对】A正确：消融的靶区是肺静脉开口及前庭部，术者必须事先掌握静脉数目与变异，否则易遗漏异位静脉导致复发。B正确：左心耳血栓是消融的禁忌，早期图像上的充盈缺损可能只是血流淤滞造成的混合不均，延迟30~60秒左右再采集可见淤滞区被对比剂填充而真性血栓仍为缺损。C正确：心电门控可减轻搏动伪影、提高开口测量的准确性；范围不足会遗漏变异静脉。D正确：CT三维模型与电解剖标测系统融合是目前消融导航的常规做法。【为什么错】E错误：本检查的目的是肺静脉与左心房解剖及左心耳血栓评估，冠脉评价并非首要目的（虽然采集数据有时可顺带观察冠脉近段）。", "tr": "“早期充盈缺损≠血栓”是本考点的核心：必须用延迟扫描鉴别血流淤滞与真性血栓，这个技术细节直接影响手术能否进行。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0187", "t": "案例分析题", "s": "患者男性，55岁，突发胸痛3小时急诊就诊。心电图无ST段抬高，肌钙蛋白处于临界水平，D-二聚体升高，血压136/82 mmHg，心率78次/分。临床需在一次检查中同时排除急性冠状动脉综合征、肺动脉栓塞与急性主动脉综合征。设备为具备心电门控与双筒高压注射器的多层CT。下列扫描方案最合理的是", "o": {"A": "采用心电门控的“胸痛三联”一站式扫描，范围自胸廓入口（主动脉弓上）至心脏膈面下方；先控制心率并舌下含服硝酸甘油，采用分段或双流对比剂注射方案，使右心、肺动脉与冠状动脉、主动脉同时获得足够强化后触发采集", "B": "先后独立完成冠脉CTA、CTPA与主动脉CTA三次增强扫描，以保证每次都达到最佳强化", "C": "仅行CTPA，若未见肺栓塞再另行安排冠脉CTA", "D": "仅行冠脉CTA，主动脉与肺动脉可凭该期图像顺带评价，无须调整方案", "E": "先行胸部平扫加床旁超声，待明确诊断后再决定是否行增强CT"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-187", "kp": "胸痛三联一站式扫描", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (13)多部位“一站式”", "ex": "【为什么对】A正确。“三联排除”方案的技术要点有三：其一，范围须自胸廓入口至心底下方，才能覆盖主动脉弓上分支起始、全肺动脉与全心；其二，必须全程心电门控，否则升主动脉与冠脉的搏动伪影会造成假性夹层与冠脉不可评价；其三，对比剂需采用分段（如先高流率再低流率）或双流（对比剂与盐水混合）注射，使右心系统与体循环同时保持足够强化——单纯常规方案往往出现“冠脉好而肺动脉淡”或反之。心率控制与硝酸甘油仍按冠脉CTA要求执行。【为什么错】B错误：三次独立扫描意味着三倍剂量与三份对比剂，急诊时间也不允许。C错误：胸痛病因未明时仅排除肺栓塞可能遗漏致命的夹层与冠脉病变。D错误：常规冠脉CTA的范围与注射方案不能满足肺动脉与全主动脉评价，“顺带看看”不可靠。E错误：患者症状明确且存在多种致命可能，先行平扫加超声会延误诊断，而增强CT正是首选的一站式手段。", "tr": "一站式扫描的取舍是“范围扩大＋门控全程＋对比剂方案改造”，三者缺一不可。注意其剂量与对比剂用量高于单一检查，故须严格把握适应证——仅用于三种病因均不能排除的患者，而非所有胸痛。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0188", "t": "单选题", "s": "关于肝脏多期增强CT的时相设计，下列说法错误的是", "o": {"A": "肝动脉晚期（约注药后30~35 s，或团注追踪腹主动脉触发后延迟约15~20 s）是显示富血供病灶的关键时相", "B": "门静脉期约在注药后60~70 s，此时肝实质强化达到高峰，有利于乏血供病灶的检出", "C": "平衡（延迟）期一般在注药后2~3分钟，有助于观察病灶的廓清与包膜强化", "D": "肝血管瘤呈渐进性向心填充，有时需延迟5~10分钟才能显示完全充填", "E": "肝脏三期扫描的目的只是分别显示肝动脉、门静脉与肝静脉的解剖，与病灶的强化方式无关"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-188", "kp": "肝脏多期增强的时相设计", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】本题选错误项，E错误。肝脏多期扫描的根本目的是利用肝脏双重血供（约75%来自门静脉、25%来自肝动脉）的时间差，观察病灶在不同时相的强化行为——例如肝细胞癌“动脉期高强化、门脉期／延迟期廓清”，转移瘤门脉期呈相对低密度，血管瘤呈渐进性向心填充。血管解剖显示只是附带收益，绝非唯一目的。【为什么错】A正确：动脉晚期肝实质尚未被门静脉血强化，而富血供病灶已明显强化，对比最大。B正确：门脉期肝实质强化峰值使乏血供病灶（转移瘤、脓肿）显示为低密度。C正确：延迟期是判断廓清、包膜强化和纤维成分延迟强化的关键。D正确：这是血管瘤定性的重要征象，延迟不足是误诊主因之一。", "tr": "肝脏时相的设计逻辑是“看病灶强化行为”，不是“看血管”。另注意动脉期分早、晚：动脉早期（约20~25 s）主要用于血管重组，动脉晚期（约30~35 s）才是检出富血供病灶的时相，二者不可混用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0189", "t": "多选题", "s": "关于胰腺CT检查技术，下列正确的有", "o": {"A": "胰腺实质期约在注药后35~45 s，此时正常胰腺强化最明显，与乏血供的胰腺癌形成最大对比", "B": "门静脉期约在注药后65~70 s，用于评价肝转移与门静脉、肠系膜上静脉受侵", "C": "需采用薄层采集并重组，以评价肿瘤与腹腔干、肠系膜上动静脉、门静脉的关系，判断可切除性", "D": "检查前可口服适量清水作为阴性对比剂充盈胃与十二指肠，以衬托胰头轮廓", "E": "胰腺检查应口服高浓度阳性对比剂，以提高胰腺与肠道之间的对比"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-189", "kp": "胰腺双期增强技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】A正确：胰腺实质期（又称胰腺期）正常胰腺强化达峰，而胰腺导管腺癌为乏血供肿瘤，此期病灶与正常胰腺的密度差最大，是检出小胰癌的关键时相。B正确：门脉期兼顾肝转移灶检出与静脉系统受累判断。C正确：可切除性评估依赖肿瘤与血管接触角度、有无包绕与变形，必须薄层＋多平面／曲面重组。D正确：清水作为阴性对比剂能勾勒胃与十二指肠轮廓而不产生高密度干扰，便于观察胰头及钩突。【为什么错】E错误：高浓度阳性对比剂在胰周形成高密度影，会干扰胰腺边缘与钩突的观察，也影响血管重组与CTA后处理，胰腺检查应使用阴性对比剂（水）。", "tr": "腹部检查中“用水还是用碘水”取决于目的：观察肠壁本身、胰腺、血管重组用水（阴性）；单纯需要区分肠管与肿块、观察肠腔充盈用稀释碘水（阳性）。胰腺检查用阳性对比剂是常见的方案性错误。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0190", "t": "单选题", "s": "关于肾脏多期增强CT，下列说法错误的是", "o": {"A": "皮髓质期约在注药后25~40 s，皮质明显强化而髓质尚未强化，皮髓质分界清楚", "B": "肾实质期约在注药后80~120 s，皮质与髓质强化趋于均一，是检出肾实质内小病灶的最佳时相", "C": "排泄期一般在注药后5~10分钟，用于观察肾盂肾盏与输尿管的对比剂充盈情况", "D": "仅依据皮髓质期图像，容易把强化的肥大肾柱或尚未强化的髓质误判为占位性病变", "E": "肾实质内小病灶的检出以皮髓质期最佳，实质期与排泄期均可省略"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-190", "kp": "肾脏多期增强的时相与价值", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】本题选错误项，E错误。皮髓质期虽有利于显示肾皮质表浅病变与肾血管，但此期髓质尚未强化呈相对低密度，位于髓质内的小病灶会被“淹没”；肾实质期皮髓质强化均一，背景一致，才是小病灶检出的最佳时相。排泄期则负责集合系统与尿路评价，二者都不能随意省略。【为什么错】A正确：这是皮髓质期的时间与影像特征。B正确：这是肾实质期的定义与价值所在。C正确：排泄期的时间窗与目的准确，肾功能减退者需相应延长。D正确：肥大肾柱（Bertin柱）在皮髓质期强化明显而易被误认为富血供病灶，在实质期与皮质强化一致即可鉴别，这正是必须做实质期的重要原因之一。", "tr": "“皮髓质期看血管与皮质，实质期查小病灶，排泄期看尿路”——三期各司其职。把皮髓质期当成万能期相是常见误区，也是肾柱假瘤误诊的根源。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0191", "t": "多选题", "s": "关于CT尿路成像（CTU）的剂量优化与技术改良，下列正确的有", "o": {"A": "分次团注（split-bolus）技术把对比剂分两次注射，使肾实质强化与集合系统排泄显影在同一次扫描中同时呈现", "B": "分次团注可减少扫描期数，从而明显降低检查的总辐射剂量", "C": "对年轻患者可考虑省略真实平扫，或用双能量虚拟平扫替代平扫以减少一次曝光", "D": "适当水化、变换体位或使用腹部压迫带，有助于肾盂肾盏与输尿管的充盈显影", "E": "分次团注技术的主要优势在于能更精确地区分皮髓质期与肾实质期的强化差别"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-191", "kp": "CTU的分次团注与剂量优化", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】A正确：先注射一部分对比剂使其进入集合系统，间隔数分钟后再注射剩余部分并在实质期扫描，一次采集即可同时看到强化的肾实质与充盈对比剂的尿路。B正确：期数由三期减为两期甚至一期，剂量随之显著下降，这正是split-bolus的核心价值。C正确：双能量虚拟平扫可从增强数据中减除碘生成类平扫图像，用于判断有无高密度结石／出血，从而省去一次真实平扫。D正确：充分的尿量、体位变换（如俯卧位或轻度头低位）与腹部压迫均可改善集合系统与输尿管的扩张充盈，减少节段性显影不良造成的假象。【为什么错】E错误：分次团注恰恰把不同时相的强化“叠加”在同一幅图像上，因而牺牲了各期强化的独立性，无法用于精细区分皮髓质期与实质期；若需要分辨各期强化行为（如肾肿瘤定性），仍应采用常规分期扫描。", "tr": "split-bolus是“以时相独立性换取剂量下降”的折中方案，适合以尿路评价为主要目的者；对需要定性肾脏占位的病例反而不适用。技术选型必须与临床问题匹配。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0192", "t": "单选题", "s": "关于盆腔CT检查前的准备，下列说法错误的是", "o": {"A": "检查前适度饮水使膀胱充盈，有助于区分膀胱与邻近肠管、子宫及附件", "B": "可提前口服稀释对比剂或经直肠灌入适量对比剂／气体，以标记肠管、避免把肠襻误认为肿块", "C": "女性患者必要时可放置阴道标记物，帮助判断病变与阴道穹隆的关系", "D": "检查前应去除盆腔区域的金属物品，如腰带扣、拉链与金属纽扣", "E": "盆腔检查要求膀胱完全排空，以免尿液影响观察"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-192", "kp": "盆腔CT检查前准备", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】本题选错误项，E错误。盆腔CT要求膀胱适度充盈而非排空：充盈的膀胱可把小肠襻推出盆腔、勾勒膀胱壁轮廓，并为子宫、附件与直肠提供解剖参照；完全排空时膀胱壁增厚皱缩，既难以评价膀胱本身，肠襻又会堆积于盆腔造成混淆。当然过度充盈也不必要，以患者有尿意但可耐受为宜。【为什么错】A正确：这是盆腔检查最基本的准备。B正确：未标记的肠襻是盆腔“假肿块”的常见来源。C正确：阴道标记物有助于确定病变下界与阴道受累情况。D正确：金属物品产生放射状伪影，应事先去除。", "tr": "膀胱“适度充盈”是盆腔与前列腺检查的通则；与之相对，泌尿系结石平扫并不强求充盈，CTU排泄期则需要合理的尿量。准备要求随检查目的而变，不可一概而论。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0193", "t": "多选题", "s": "关于盆腔CT检查技术，下列正确的有", "o": {"A": "采用薄层容积采集，便于多平面重组评价病变与膀胱、直肠、子宫及盆壁的关系", "B": "增强时相依临床问题而定，如子宫病变常用双期观察病灶与肌层的强化差别", "C": "髋关节假体造成的金属伪影可采用金属伪影校正算法、高keV虚拟单能量图像或适当提高管电压来减轻", "D": "评估直肠病变时可经直肠注入适量气体或水，使肠壁展开、便于观察肠壁增厚与外侵", "E": "盆腔CT对子宫内膜与结合带的显示优于MRI，是宫颈癌与子宫内膜癌分期的首选方法"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-193", "kp": "盆腔CT扫描与伪影处理", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】A正确：盆腔器官毗邻复杂，矢状与冠状重组对判断肿瘤侵犯层次至关重要。B正确：子宫肌层与内膜、肌瘤与腺肌症的强化时间差需多期观察。C正确：这三种手段是关节假体伪影的标准应对方案，其中高keV单能量图像效果最显著。D正确：肠腔充盈（气体或水）可使肠壁伸展，避免收缩的肠壁被误判为增厚。【为什么错】E错误：MRI软组织分辨率远高于CT，能清晰区分子宫内膜、结合带与肌层，是宫颈癌与子宫内膜癌局部分期的首选；CT主要用于评价淋巴结、远处转移与不能行MRI者。", "tr": "妇科肿瘤局部分期首选MRI，CT负责“远处与淋巴结”。凡称“CT对子宫内膜、结合带显示优于MRI”的选项一律为错，这是软组织对比的基本规律。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-0194", "t": "单选题", "s": "关于脊柱CT检查技术，下列说法错误的是", "o": {"A": "以椎间盘为观察重点时，可倾斜机架使扫描层面平行于相应的椎间隙", "B": "同一次薄层采集的数据应分别以骨算法与软组织算法重建，用于观察骨质与椎间盘、椎管内软组织", "C": "薄层采集后行矢状面与冠状面重组，有助于评价椎体压缩、滑脱与椎管狭窄程度", "D": "阅片时须同时使用骨窗与软组织窗", "E": "脊柱外伤患者为加快检查速度，应改取俯卧位并先行去除颈托等固定装置"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-194", "kp": "脊柱CT检查技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】本题选错误项，E错误。脊柱外伤（尤其颈椎）在未排除不稳定骨折前，严禁随意翻身或去除颈托等固定装置，否则可能造成脊髓继发损伤，这是严重的安全事故。正确做法是保持仰卧、维持固定，必要时用轴向翻身法由多人协作搬运，颈托一般不必去除（现代颈托多为低密度材料，伪影有限），确需去除时须由临床医师评估并保护颈椎。【为什么错】A正确：机架倾斜可使层面与椎间隙平行，避免斜切造成的假性膨出。B正确：一次采集、双算法重建是脊柱检查的常规。C正确：矢状重组是评价椎体压缩程度、滑脱分度与椎管前后径的关键。D正确：骨窗看骨折线、骨质增生与骨性椎管，软组织窗看椎间盘突出、韧带钙化与椎管内血肿。", "tr": "凡涉及“为提高效率而取消固定、随意搬动外伤患者”的选项一律为错。技术效率永远让位于患者安全，这类题考的是职业素养与风险意识。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-0195", "t": "案例分析题", "s": "患者男性，52岁，腰椎后路融合内固定术后1年，近3个月出现右下肢放射痛，临床需评价椎弓根螺钉位置、有无松动及右侧神经根管狭窄情况。常规腰椎CT图像上钛合金螺钉周围可见明显放射状条纹伪影，遮盖了相邻的神经根管与椎间孔结构。设备具备能量成像与金属伪影校正功能。下列处理方案最合理的是", "o": {"A": "适当提高管电压与管电流、采用薄准直与较小螺距重新采集，重建时启用金属伪影校正算法，并生成高keV虚拟单能量图像；后处理时沿螺钉长轴做斜位重组与斜矢状重组观察神经根管", "B": "把管电压降至80 kVp以减少射线硬化，从而消除金属伪影", "C": "改用高分辨率骨算法并把窗宽调至最大，即可完全消除金属伪影", "D": "改行腰椎MRI检查，因MRI不会产生任何金属相关伪影", "E": "直接在报告中说明因金属伪影无法评价，建议临床自行判断"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-195", "kp": "脊柱内固定术后金属伪影的处理", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】A正确。金属伪影的成因是线束硬化、光子饥饿、散射与投影数据缺失，对策应从采集、重建、后处理三个层面同时入手：采集端提高kV与mAs增强穿透、减小准直与螺距增加采样密度；重建端启用MAR类算法对缺失投影做插值补偿；能量成像端生成130~150 keV虚拟单能量图像显著削弱硬化伪影；后处理端沿螺钉长轴做斜位重组，可让条纹方向与观察平面错开，从而看清神经根管与椎间孔。【为什么错】B错误：方向完全相反，降低kV会加重线束硬化与光子饥饿，使伪影更明显。C错误：骨算法会锐化条纹，加大窗宽只是压缩灰阶显示，均不能改变数据本身的缺陷。D错误：MRI在金属植入物附近同样存在磁敏感伪影（甚至可能更严重），且需先确认植入物的MRI兼容性，不能说“不会产生任何伪影”。E错误：在具备MAR与能量成像条件的情况下放弃技术补救、直接给出不可评价结论，是不负责任的做法。", "tr": "金属伪影的处理口诀是“高kV、高mAs、薄准直、小螺距、MAR算法、高keV单能量、斜位重组”。特别注意与低剂量策略中的“降kV”方向相反——目的不同，参数取向就相反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-0196", "t": "单选题", "s": "关于四肢骨关节及软组织CT检查技术，下列说法错误的是", "o": {"A": "应采用薄层采集，并分别以骨算法与软组织算法重建", "B": "关节内骨折（如胫骨平台、跟骨、髋臼骨折）常需三维重组显示骨折块移位与关节面塌陷程度", "C": "检查时应尽量把被检肢体置于扫描野中心，必要时行双侧对比扫描", "D": "软组织肿块的评估常需增强扫描，以观察其血供、边界与邻近血管神经的关系", "E": "四肢检查因骨骼密度高、对比良好，无须再用软组织窗观察"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-196", "kp": "四肢骨关节及软组织CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】本题选错误项，E错误。软组织窗是四肢检查不可缺少的：关节积液／积血、肌腱与韧带钙化、软组织肿块、脓肿与气体、血肿等均需在软组织窗观察；只看骨窗会漏掉骨折以外的重要信息，如骨筋膜室内的血肿或异物。【为什么错】A正确：薄层＋双算法是标准流程，一次采集即可满足骨与软组织两方面需求。B正确：关节内骨折的治疗决策取决于关节面塌陷与骨块移位，三维重组是术前评估的常规。C正确：置于扫描野中心可获得最佳空间分辨率与最小的射束硬化影响；双侧对比有助于判断细微不对称。D正确：软组织肿块的定性与术前规划依赖增强所显示的血供与边界。", "tr": "“看什么用什么窗”是四肢检查的基本功。另注意肢体常需偏中心摆放（如单侧上肢），此时应尽量把患侧置于机架中心并缩小FOV靶重建，以避免边缘区域分辨率下降与伪影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1001", "t": "单选题", "s": "CT值定义为某物质对X线的衰减系数与水的衰减系数相比所得的值，水的CT值规定为", "o": {"A": "－1000HU", "B": "0HU", "C": "＋100HU", "D": "＋1000HU", "E": "－500HU"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-001", "kp": "CT值基准", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】CT值的定义以水为基准，规定水的CT值为0HU，空气为－1000HU，骨约为＋1000HU，故B正确。\n【为什么错】A：－1000HU是空气的CT值。C、D：＋1000HU为致密骨CT值，＋100HU并非标准基准值。E：－500HU约介于空气与软组织之间，不是水的CT值。", "tr": "CT值基准三件套：水0HU、空气－1000HU、骨约＋1000HU，务必牢记。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1002", "t": "单选题", "s": "空气的CT值约为", "o": {"A": "0HU", "B": "＋1000HU", "C": "－1000HU", "D": "－500HU", "E": "＋500HU"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-002", "kp": "空气CT值", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】按CT值标度，空气对X线衰减最小，其CT值规定为约－1000HU，故C正确。\n【为什么错】A：0HU为水的CT值。B：＋1000HU为致密骨的CT值。D：－500HU介于脂肪与软组织之间。E：＋500HU为较高密度组织，并非空气。", "tr": "牢记水、空气、骨三个基准CT值，这是CT值换算与窗技术的基础。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1003", "t": "单选题", "s": "关于窗宽和窗位的叙述，正确的是", "o": {"A": "窗宽增大，图像对比度增大", "B": "窗位是窗的中心值，决定图像灰度中心", "C": "窗宽是指图像亮度范围", "D": "窗位增大，显示的组织CT值范围变宽", "E": "窗宽窗位只影响CT值，不影响图像显示"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-003", "kp": "窗宽窗位概念", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】窗位是窗的中心值，即显示灰阶的中心CT值，决定图像灰度中心，故B正确。\n【为什么错】A：窗宽增大时显示范围变宽，对比度反而降低。C：窗宽指显示的CT值范围而非亮度范围。D：窗位变化改变显示中心，不改变显示范围（范围由窗宽决定）。E：窗宽窗位正是图像显示技术，直接影响图像显示效果。", "tr": "窗宽决定显示范围（管对比度），窗位决定显示中心（管亮度/灰度中心），二者不可混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1004", "t": "单选题", "s": "当窗宽增大时，图像的变化是", "o": {"A": "对比度增大，显示范围变窄", "B": "对比度降低，显示CT值范围增宽", "C": "亮度明显增高", "D": "空间分辨力提高", "E": "密度分辨力提高"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-004", "kp": "窗宽对图像的影响", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】窗宽增大意味着可显示的CT值范围增宽，同一灰阶级差对应更大的CT值差，因此图像对比度降低，故B正确。\n【为什么错】A：窗宽增大显示范围增宽而非变窄，对比度降低而非增大。C：亮度主要由窗位决定，与窗宽无直接对应。D：窗宽不影响空间分辨力。E：窗宽增大密度分辨力并不提高，反而因对比度下降而影响密度区分。", "tr": "窗宽管范围，窗宽越大对比度越低；窗位管亮度中心。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1005", "t": "单选题", "s": "窗位的作用是", "o": {"A": "决定显示的CT值范围", "B": "决定窗的中心CT值，即图像灰度中心", "C": "提高图像对比度", "D": "降低噪声", "E": "提高空间分辨力"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-005", "kp": "窗位作用", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】窗位是窗的中心值，窗中心CT值被映射为灰阶中心，决定图像的整体灰度水平，故B正确。\n【为什么错】A：显示范围由窗宽决定。C：对比度受窗宽影响。D：窗位不能降低噪声。E：空间分辨力与像素、焦点有关，与窗位无关。", "tr": "窗宽定范围、窗位定中心，观察不同密度组织应调节窗位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1006", "t": "单选题", "s": "螺旋CT螺距（pitch）的计算公式是", "o": {"A": "床速（mm/s）×旋转时间（s）÷准直器宽度（mm）", "B": "准直器宽度÷床速", "C": "层厚×矩阵", "D": "扫描时间÷旋转时间", "E": "床速÷旋转时间"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-006", "kp": "螺距公式", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】螺距＝扫描架旋转一周期间床的移动距离÷准直器宽度，即床速×旋转时间÷准直宽度，故A正确。\n【为什么错】B、C：均不是螺距定义式。D：扫描时间与旋转时间的比值不构成螺距。E：床速÷旋转时间量纲不对，螺距为无量纲比值。", "tr": "螺距是床移动距离与准直宽度的无量纲比值；螺距增大时扫描速度快、层间重叠减少，但密度分辨力下降。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1007", "t": "单选题", "s": "当螺距等于1时，其含义是", "o": {"A": "床速与准直器宽度相等", "B": "旋转一周床移动距离等于准直器宽度", "C": "扫描时间为1秒", "D": "层厚为1mm", "E": "矩阵为1:1"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-007", "kp": "螺距等于1的含义", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】螺距等于1时，扫描架旋转一周床的移动距离恰好等于准直器宽度，层间无重叠也无间隔，故B正确。\n【为什么错】A：螺距等于1并不表示床速与准直宽度相等，二者单位不同。C：螺距与扫描时间无关。D：螺距与层厚无直接对应。E：矩阵与螺距无关。", "tr": "螺距＝1是连续无间隔扫描；螺距＞1有间隔可加快扫描，螺距＜1有重叠。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1008", "t": "单选题", "s": "CT图像矩阵的概念是指", "o": {"A": "视野大小", "B": "构成图像行和列的像素数目", "C": "层厚大小", "D": "像素灰度级数", "E": "探测器数目"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-008", "kp": "矩阵概念", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】矩阵是排列成行和列的像素阵列，如512×512即图像由512行512列像素组成，故B正确。\n【为什么错】A：视野是扫描范围。C：层厚是断面的厚度。D：灰度级数由位深决定。E：探测器数目决定原始数据的采样，不等于矩阵。", "tr": "矩阵决定像素多少，视野与矩阵共同决定像素大小（像素大小＝视野÷矩阵）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1009", "t": "单选题", "s": "当矩阵固定时，缩小视野（FOV）会使", "o": {"A": "像素增大，空间分辨力降低", "B": "像素减小，空间分辨力提高", "C": "像素不变", "D": "密度分辨力提高", "E": "噪声不变"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-009", "kp": "视野与像素的关系", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】像素大小＝视野÷矩阵，矩阵固定时视野缩小则像素减小，像素越小空间分辨力越高，故B正确。\n【为什么错】A：视野缩小像素减小而非增大。C：像素随视野改变。D：像素减小通常光子统计量下降，密度分辨力不提高甚至下降。E：像素减小噪声相对增大。", "tr": "缩小FOV提高空间分辨力的前提是矩阵不变；靶扫描正是利用此原理。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1010", "t": "单选题", "s": "像素大小（mm）的计算公式为", "o": {"A": "视野÷矩阵", "B": "矩阵÷视野", "C": "视野×矩阵", "D": "层厚÷矩阵", "E": "矩阵÷层厚"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-010", "kp": "像素大小计算", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】像素大小等于重建视野除以矩阵的行数，即FOV÷矩阵，故A正确。\n【为什么错】B：矩阵÷视野恰为像素大小的倒数。C：二者相乘量纲不对。D、E：层厚与像素大小无关。", "tr": "如FOV＝256mm、矩阵512，则像素＝0.5mm；像素越小空间分辨力越高。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1011", "t": "单选题", "s": "影响CT空间分辨力的主要因素是", "o": {"A": "像素大小", "B": "窗宽窗位", "C": "对比剂浓度", "D": "扫描层距", "E": "床速"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-011", "kp": "空间分辨力影响因素", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】空间分辨力主要取决于像素大小，像素越小空间分辨力越高，此外还与焦点、探测器孔径、算法等有关，故A正确。\n【为什么错】B：窗宽窗位只影响显示，不影响原始分辨力。C：对比剂影响密度对比而非空间分辨力。D：层距影响相邻层面连续性，不直接决定层面内空间分辨力。E：床速影响扫描覆盖与层间关系，不决定空间分辨力。", "tr": "空间分辨力看像素大小；密度分辨力看剂量、层厚与噪声，两者常此消彼长。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1012", "t": "单选题", "s": "提高CT密度分辨力的有效措施是", "o": {"A": "缩小像素", "B": "降低管电流", "C": "增加层厚或增大管电流", "D": "减小矩阵", "E": "增大窗宽"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-012", "kp": "密度分辨力影响因素", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】密度分辨力主要受噪声影响，增大层厚或增大管电流可增加X线光子数、降低噪声，从而提高密度分辨力，故C正确。\n【为什么错】A：缩小像素使每个像素光子量减少，噪声增大，密度分辨力下降。B：降低管电流减少光子数，噪声增大。D：减小矩阵使像素增大，虽噪声降低但空间分辨力下降，并非提高密度分辨力的首选。E：窗宽只影响显示。", "tr": "空间分辨力与密度分辨力常相互制约：薄层提空间分辨力、降密度分辨力；大剂量提密度分辨力。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1013", "t": "单选题", "s": "部分容积效应的正确解释是", "o": {"A": "同一层面内包含多种密度组织时，CT值是各组织的平均值", "B": "扫描床移动造成的伪影", "C": "探测器响应不一致", "D": "X线硬化效应", "E": "运动产生的伪影"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-013", "kp": "部分容积效应", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】部分容积效应指扫描层厚内包含多种不同密度的组织，测得的CT值是该层内各组织CT值的加权平均值，故A正确。\n【为什么错】B：床移动造成的是运动伪影而非部分容积效应。C：探测器响应不一致引起的是环形伪影。D：X线硬化是射束硬化伪影。E：运动伪影是患者活动所致。", "tr": "减小部分容积效应的方法是采用薄层扫描或缩小扫描层厚。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1014", "t": "单选题", "s": "心电编辑主要用于解决下列哪种情况导致的图像错位", "o": {"A": "呼吸运动", "B": "心律不齐", "C": "吞咽动作", "D": "金属异物", "E": "肠蠕动"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-014", "kp": "心电编辑用途", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】心电编辑是对心律不齐患者的心电门控扫描数据进行编辑校正，将异常心动周期内采集的数据用相邻正常周期的数据替代，消除图像错位，故B正确。\n【为什么错】A：呼吸运动伪影靠屏气训练解决。C：吞咽影响头颈部，与心电无关。D：金属异物伪影需去金属或用特殊重建。E：肠蠕动伪影用低张药或快速扫描。", "tr": "心电编辑针对心律不齐（如房早、房颤），是冠状动脉CTA质量控制的重要内容。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1015", "t": "单选题", "s": "下列关于心电门控扫描的叙述，正确的是", "o": {"A": "回顾性心电门控辐射剂量低于前瞻性心电门控", "B": "前瞻性心电门控可任意选择心动周期时相重建", "C": "回顾性心电门控扫描可对心动周期任意时相进行重建", "D": "心电门控只用于胸部平扫", "E": "心电编辑与心电门控无关"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-015", "kp": "心电门控方式比较", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】回顾性心电门控是在连续采集的同时记录心电信号，扫描后可根据需要选择心动周期的任意时相进行重建，故C正确。\n【为什么错】A：回顾性心电门控全程扫描，辐射剂量高于前瞻性。B：前瞻性心电门控在预定时相触发扫描，重建时相选择受限。D：心电门控主要用于心脏冠脉CTA，不是胸部平扫。E：心电编辑是对心电门控数据的校正，密切相关。", "tr": "前瞻性门控剂量低、对心率要求高；回顾性门控剂量高、可任意时相重建，常用于心律不齐。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1016", "t": "单选题", "s": "CT平扫是指", "o": {"A": "不注射对比剂的扫描", "B": "注射对比剂后的扫描", "C": "仅扫描定位像", "D": "低剂量扫描", "E": "高分辨扫描"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-016", "kp": "平扫定义", "ch": "九、CT检查技术 → 2.检查方法 → (1)平扫", "ex": "【为什么对】平扫即普通扫描，是不经静脉注射对比剂直接进行的扫描，故A正确。\n【为什么错】B：注射对比剂后扫描为增强扫描。C：定位像只是扫描前定位用的数字图像。D：低剂量扫描是减少辐射剂量的一种扫描方式。E：高分辨扫描是特殊扫描技术。", "tr": "平扫与增强扫描、低剂量扫描、高分辨扫描是不同维度的分类，注意区分。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1017", "t": "单选题", "s": "颅脑外伤患者急诊CT检查，首选检查方法为", "o": {"A": "增强扫描", "B": "平扫", "C": "CT灌注", "D": "CTA", "E": "能量成像"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-017", "kp": "颅脑外伤首选平扫", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑外伤怀疑颅内出血、骨折时首选CT平扫，可快速、准确显示急性出血（高密度）及颅骨骨折，无需注射对比剂，故B正确。\n【为什么错】A：急性出血平扫即可显示，增强无益且延误时间。C：灌注用于缺血评估，非外伤常规。D：CTA用于血管病变。E：能量成像非外伤首选。", "tr": "急性颅内出血CT平扫呈高密度，是神经外科急诊处理的重要依据。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1018", "t": "单选题", "s": "高分辨力CT（HRCT）的扫描特点是", "o": {"A": "厚层扫描，软组织算法重建", "B": "薄层扫描，高空间频率算法（骨算法）重建", "C": "薄层扫描，平滑算法重建", "D": "低剂量扫描", "E": "增强扫描"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-018", "kp": "HRCT扫描特点", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】HRCT采用薄层扫描（层厚1～2mm），并用高空间频率算法（骨算法）重建，以提高空间分辨力，故B正确。\n【为什么错】A：HRCT用薄层而非厚层。C：平滑算法降低空间分辨力，与HRCT目的相反。D：低剂量是剂量控制策略，不是HRCT的成像特点。E：增强扫描与HRCT是不同概念。", "tr": "HRCT＝薄层＋骨算法（高空间频率），用于肺弥漫性病变、内耳等精细结构。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1019", "t": "单选题", "s": "HRCT最常用于下列哪种病变的检查", "o": {"A": "弥漫性肺疾病", "B": "肝脏占位", "C": "肾结石", "D": "股骨头骨折", "E": "腹膜后血肿"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-019", "kp": "HRCT临床应用", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】HRCT以高空间分辨力显示肺小叶结构，是诊断弥漫性肺疾病（如间质性肺病、肺气肿）的重要技术，故A正确。\n【为什么错】B：肝脏占位多用常规层厚增强扫描。C：肾结石用低剂量或常规平扫。D：股骨头骨折可平扫+三维重建。E：腹膜后血肿用常规增强扫描。", "tr": "HRCT经典应用：弥漫性肺疾病、内耳颞骨、颅底精细结构。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1020", "t": "单选题", "s": "CT薄层扫描的层厚一般是指", "o": {"A": "5mm", "B": "10mm", "C": "2mm及以下", "D": "8mm", "E": "15mm"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-020", "kp": "薄层扫描层厚", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】薄层扫描一般指层厚≤2mm（常为1～2mm甚至0.5mm），用于观察细小结构如内耳、垂体、椎间盘等，故C正确。\n【为什么错】A、B、D：5～10mm多为常规扫描层厚。E：15mm为厚层扫描。", "tr": "常规层厚5～10mm，薄层≤2mm；薄层可减少部分容积效应、提高空间分辨力。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1021", "t": "单选题", "s": "低剂量CT扫描主要适用于", "o": {"A": "肺癌筛查", "B": "冠脉CTA", "C": "肝脏三期增强", "D": "CT灌注", "E": "骨髓病变诊断"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-021", "kp": "低剂量CT应用", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】低剂量CT通过降低管电流或管电压减少辐射剂量，主要用于肺癌高危人群筛查，故A正确。\n【为什么错】B：冠脉CTA需要高时间分辨力与高信噪比，不能用低剂量。C：增强多期扫描需足够的密度分辨力。D：灌注扫描需连续采集，噪声要求高。E：骨髓病变显示需要良好密度分辨力，低剂量不适用。", "tr": "低剂量扫描以牺牲部分密度分辨力为代价，适合肺小结节等高对比病变筛查。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1022", "t": "单选题", "s": "CT靶扫描（放大扫描）的主要特点是", "o": {"A": "增大视野，观察整体", "B": "缩小视野，对兴趣区放大重建，提高空间分辨力", "C": "增加层厚", "D": "降低管电流", "E": "增大螺距"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-022", "kp": "靶扫描特点", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】靶扫描是缩小重建视野，对感兴趣区域进行放大重建，使像素变小、空间分辨力提高，常用于肺小结节、垂体等，故B正确。\n【为什么错】A：靶扫描是缩小视野而非增大。C：靶扫描通常配合薄层，而非增厚。D：降低管电流不是靶扫描的本质。E：靶扫描与螺距无关。", "tr": "靶扫描＝小视野放大重建；注意与图像后处理放大（只是放大显示）的区别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1023", "t": "单选题", "s": "CT增强扫描的目的是", "o": {"A": "提高空间分辨力", "B": "利用碘对比剂增加组织间密度对比，观察病灶血供", "C": "减少辐射剂量", "D": "消除运动伪影", "E": "代替平扫"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-023", "kp": "增强扫描目的", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】增强扫描经静脉注射碘对比剂，利用不同组织、病灶血供差异产生密度变化，提高病灶与正常组织的密度对比，有利于病变定性与血供评估，故B正确。\n【为什么错】A：空间分辨力与增强无直接关系。C：增强不减少辐射剂量。D：增强不能消除运动伪影。E：增强不能代替平扫，二者常互补。", "tr": "增强扫描的关键是掌握延迟时间，使靶器官/病灶处于最佳强化期。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1024", "t": "单选题", "s": "肝脏增强CT动脉期的延迟时间一般为", "o": {"A": "15秒内", "B": "25～30秒", "C": "60～70秒", "D": "120～180秒", "E": "10分钟"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-024", "kp": "肝脏动脉期延迟时间", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肝脏增强扫描动脉期一般在注药后25～30秒扫描，此时肝动脉及富血供病变强化明显，故B正确。\n【为什么错】A：15秒内对比剂未充分到达肝动脉。C：60～70秒为门静脉期。D：120～180秒为平衡期。E：10分钟为延迟期，用于血管瘤等延迟强化。", "tr": "肝动脉期25～30s、门脉期60～70s、平衡期120～180s，是肝脏三期增强经典时间窗。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1025", "t": "单选题", "s": "肝脏增强CT门静脉期的延迟时间一般为", "o": {"A": "25～30秒", "B": "60～70秒", "C": "180～240秒", "D": "5分钟", "E": "10秒"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-025", "kp": "门静脉期延迟时间", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】门静脉期在注药后60～70秒扫描，此时门静脉及肝实质强化明显，有利于显示乏血供肝转移瘤等，故B正确。\n【为什么错】A：25～30秒为动脉期。C、D：180秒后为平衡期/延迟期。E：10秒对比剂尚在循环早期。", "tr": "门脉期是肝转移瘤（多为乏血供）显示的最佳时相。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1026", "t": "单选题", "s": "CT灌注成像中，反映每100g脑组织内血流量的参数是", "o": {"A": "CBF（脑血流量）", "B": "CBV（脑血容量）", "C": "MTT（平均通过时间）", "D": "TTP（达峰时间）", "E": "PS（毛细血管通透性）"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-026", "kp": "CBF含义", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】CBF即脑血流量，单位ml/(100g·min)，反映每100g脑组织单位时间内的血流量，故A正确。\n【为什么错】B：CBV是血容量，单位ml/100g。C：MTT是平均通过时间。D：TTP是达峰时间。E：PS反映毛细血管通透性。", "tr": "CBF带时间维度（/min），CBV不带；二者单位不同，注意区分。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1027", "t": "单选题", "s": "CT灌注成像中，脑血容量（CBV）的正常参考值约为", "o": {"A": "0.5～1ml/100g", "B": "2～6ml/100g", "C": "10～15ml/100g", "D": "50～100ml/100g", "E": "1～2ml/100g"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-027", "kp": "CBV参考值", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】正常脑灰质CBV约2～6ml/100g（灰质略高、白质略低），故B正确。\n【为什么错】A、E：1ml/100g左右明显偏低。C：10～15ml/100g偏高。D：50～100ml/100g接近CBF量级，混淆了单位。", "tr": "CBV单位ml/100g（约2～6），CBF单位ml/(100g·min)（灰质约50～80），勿混淆量级。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1028", "t": "单选题", "s": "CT灌注成像中，平均通过时间（MTT）延长最常见于", "o": {"A": "正常脑组织", "B": "缺血区血流灌注减低", "C": "血管畸形高流量区", "D": "脑脊液", "E": "骨组织"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-028", "kp": "MTT的临床意义", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】MTT是对比剂通过组织毛细血管床的平均时间，脑缺血区血流量减低、侧支循环缓慢，MTT明显延长，故B正确。\n【为什么错】A：正常脑组织MTT在正常范围。C：血管畸形动静脉短路时MTT可缩短。D、E：脑脊液和骨组织不参与灌注参数计算。", "tr": "缺血半暗带判断常依据MTT延长、CBF下降而CBV正常或轻度升高。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1029", "t": "单选题", "s": "CT灌注成像中，达峰时间（TTP）是指", "o": {"A": "对比剂首次到达的时间", "B": "感兴趣区内对比剂浓度达到峰值的时间", "C": "对比剂完全廓清的时间", "D": "扫描开始的时间", "E": "注射开始的时间"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-029", "kp": "TTP含义", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】TTP是时间—密度曲线上对比剂浓度达到峰值的时间，反映对比剂到达组织的速度，故B正确。\n【为什么错】A：首达时间是对比剂刚出现的时间。C：廓清时间不是达峰时间。D：扫描开始时间与TTP无关。E：注射开始是时间起点而非峰值时间。", "tr": "TTP延长提示侧支代偿差、灌注延迟；注意TTP与MTT的区别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1030", "t": "单选题", "s": "颅脑CT灌注成像扫描时，对比剂的注射流率一般为", "o": {"A": "0.5～1ml/s", "B": "2ml/s", "C": "4～6ml/s", "D": "8～10ml/s", "E": "1ml/s"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-030", "kp": "灌注扫描注射流率", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】颅脑CT灌注需保证对比剂团注快速，常用高压注射器以4～6ml/s注入，以保证时间—密度曲线质量，故C正确。\n【为什么错】A、E：0.5～1ml/s流率过低，无法形成良好团注。B：2ml/s偏低。D：8～10ml/s过高，易外渗且不必要。", "tr": "灌注注射流率快（4～6ml/s），总量常40～50ml；与常规增强（2～3ml/s）不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1031", "t": "单选题", "s": "缺血性脑卒中CT灌注中，半暗带的典型表现为", "o": {"A": "CBF、CBV均明显下降", "B": "CBF下降、CBV正常或升高，MTT延长", "C": "CBF、CBV均正常", "D": "CBV明显下降而CBF正常", "E": "MTT缩短"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-031", "kp": "半暗带灌注表现", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】缺血半暗带是存活但低灌注的组织，表现为CBF下降、CBV正常或轻度升高（血管代偿扩张）、MTT延长，是可挽救区域，故B正确。\n【为什么错】A：CBF、CBV均明显下降提示梗死核心而非半暗带。C：各参数正常为正常脑组织。D：CBV下降而CBF正常不符合缺血规律。E：MTT缩短见于高灌注或短路。", "tr": "梗死核心：CBF、CBV均↓；半暗带：CBF↓、CBV正常/↑、MTT延长。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1032", "t": "单选题", "s": "CT血管成像（CTA）最基本的成像原理是", "o": {"A": "利用血氧水平变化成像", "B": "静脉团注对比剂，在靶血管对比剂浓度峰值期扫描并经后处理重建血管", "C": "不用对比剂直接成像", "D": "口服对比剂显示血管", "E": "利用X线衰减差异成像，与增强无关"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-032", "kp": "CTA成像原理", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】CTA经外周静脉团注碘对比剂，利用团注追踪或小剂量测试确定扫描延迟，在靶血管内对比剂浓度达峰时扫描，再经MIP、VR等后处理显示血管，故B正确。\n【为什么错】A：血氧水平变化成像是MRI的BOLD技术。C：CTA必须用对比剂。D：口服对比剂不能进入血管。E：CTA依赖对比剂增强，不是单纯X线衰减。", "tr": "CTA三大要素：快速团注、精确延迟（团注追踪）、后处理重建。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1033", "t": "单选题", "s": "颅脑CTA扫描时，常用团注追踪或小剂量测试确定扫描延迟时间，头颅动脉期延迟一般为", "o": {"A": "10～15秒", "B": "15～25秒", "C": "40～50秒", "D": "60秒以上", "E": "5秒"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-033", "kp": "颅脑CTA延迟时间", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】颅脑CTA在对比剂经心脏→主动脉→颈动脉到达颅内动脉时扫描，常规延迟时间约15～25秒，故B正确。\n【为什么错】A：10～15秒偏早，对比剂尚未充分充盈颅内动脉。C：40～50秒已进入静脉期，动脉显示不佳。D：60秒以上为静脉期。E：5秒对比剂刚注入。", "tr": "CTA延迟时间可用团注追踪自动触发，无需固定；头颅动脉期约15～25s。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1034", "t": "单选题", "s": "冠状动脉CTA检查前，心率控制的目标一般为", "o": {"A": "≤70次/分（必要时使用β受体阻滞剂）", "B": "≥100次/分", "C": "80～90次/分", "D": "不需控制心率", "E": "≤50次/分以下才可检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-034", "kp": "冠脉CTA心率控制", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠脉CTA要求心率尽量低且心律规整，一般心率≤70次/分（理想≤65），心率过快者可口服β受体阻滞剂，故A正确。\n【为什么错】B、C：心率过快冠脉运动伪影明显。D：心率过高会严重影响图像质量。E：≤50次/分不是必须，心率过慢也无需刻意追求。", "tr": "冠脉CTA质量与心率、心律密切相关；心律不齐时可配合心电编辑。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1035", "t": "单选题", "s": "冠脉CTA扫描通常采用", "o": {"A": "心电门控技术", "B": "非门控扫描", "C": "低剂量平扫", "D": "口服对比剂", "E": "CT透视"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-035", "kp": "冠脉CTA扫描方式", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠状动脉随心脏搏动运动，冠脉CTA必须采用心电门控技术，在心脏相对静止期采集数据，故A正确。\n【为什么错】B：非门控扫描无法消除心脏运动伪影。C：低剂量平扫不能显示冠脉腔。D：口服对比剂不能显示冠脉。E：CT透视用于穿刺导向，不是冠脉成像。", "tr": "心脏CTA必须心电门控，根据心率选择前瞻性或回顾性门控。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1036", "t": "单选题", "s": "双能量CT（能量成像）的基本原理是", "o": {"A": "利用两种不同能量（kVp）的X线进行采集，利用物质在不同能量下的衰减差异进行物质分离", "B": "利用不同管电流成像", "C": "利用两次平扫减影", "D": "利用不同螺距成像", "E": "利用不同矩阵成像"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-036", "kp": "双能量CT原理", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT通过高、低两种管电压（如80/140kVp）同时或瞬时切换采集，依据不同物质（如碘、钙、水）在两种能量下衰减系数的差异，实现物质分离与定量分析，故A正确。\n【为什么错】B：管电流变化只改变X线量。C：两次平扫减影是双能减影的早期形式，但现代双能基于能谱采集。D：螺距与能量无关。E：矩阵不影响能量信息。", "tr": "双能量成像的核心是物质分离，典型应用：虚拟平扫、碘图、去骨、结石成分分析。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1037", "t": "单选题", "s": "双能量CT的虚拟平扫（VNC）技术是指", "o": {"A": "不用对比剂的平扫", "B": "从增强扫描数据中去除碘成分信息，生成类似平扫的图像", "C": "低剂量平扫", "D": "用生理盐水代替对比剂扫描", "E": "只扫定位像"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-037", "kp": "虚拟平扫VNC", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】虚拟平扫利用双能量物质分离技术，将增强扫描数据中的碘对比剂信号去除，重建出类似真实平扫的图像，从而可免去实际平扫、减少辐射剂量，故B正确。\n【为什么错】A：虚拟平扫是从增强数据生成，不是真正的平扫。C：低剂量平扫仍需实际扫描。D：生理盐水不能产生增强效果。E：定位像只是定位图像。", "tr": "VNC的意义在于一次增强扫描可同时获得平扫样图像与增强图像，减少扫描次数与剂量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1038", "t": "单选题", "s": "双能量CT碘图（碘基图像）的主要用途是", "o": {"A": "显示骨骼", "B": "定量显示组织内碘对比剂分布，反映组织血供", "C": "显示脂肪含量", "D": "显示空气", "E": "显示钙化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-038", "kp": "碘图应用", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】碘图是双能量物质分离出碘成分的定量图像，可直观反映组织内碘对比剂分布与浓度，从而评估组织血供，故B正确。\n【为什么错】A：骨骼显示主要依靠常规骨窗或钙图。C：脂肪需脂肪基图像。D：空气不是碘图的观察对象。E：钙化由钙基图像显示。", "tr": "碘图定量评估血供，常用于肿瘤强化程度评估及疗效监测。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1039", "t": "单选题", "s": "双能量CT去骨技术主要应用于", "o": {"A": "CTA去除骨骼干扰，显示血管更清晰", "B": "提高CT值测量", "C": "降低管电流", "D": "增加层厚", "E": "消除运动伪影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-039", "kp": "去骨技术应用", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT利用钙与碘的衰减差异，可将CTA图像中的骨骼（钙）去除，使血管显示更加清晰，尤其适用于头颈、四肢CTA，故A正确。\n【为什么错】B：去骨不提高CT值测量精度。C：去骨与管电流无关。D：去骨与层厚无关。E：去骨不能消除运动伪影。", "tr": "去骨CTA常用于头颈部血管，避免骨遮挡对血管评估的影响。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1040", "t": "单选题", "s": "双能量CT最常用于鉴别下列哪种结石的成分", "o": {"A": "尿酸结石与含钙结石", "B": "胆囊胆固醇结石", "C": "胆色素结石", "D": "胰腺结石", "E": "胃结石"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-040", "kp": "能量CT结石分析", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT可通过物质分离区分尿酸结石与含钙结石（钙结石），对治疗方案选择（如药物溶石 vs 碎石）有重要价值，故A正确。\n【为什么错】B：胆固醇结石成分复杂，双能量鉴别价值有限。C：胆色素结石鉴别意义不大。D、E：非双能量CT的典型应用。", "tr": "双能量结石分析最经典应用是泌尿系结石：尿酸结石（可药物溶石）与含钙结石鉴别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1041", "t": "单选题", "s": "CT导向穿刺活检的定位方法通常是", "o": {"A": "根据体表解剖标志随意穿刺", "B": "扫描定位后确定病灶层面、体表进针点及进针角度与深度", "C": "注射对比剂后盲穿", "D": "超声引导", "E": "磁共振定位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-041", "kp": "CT导向穿刺定位", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】CT导向穿刺活检先扫描确定病灶所在层面，在体表放置栅栏定位器或网格，根据定位图确定进针点，再测算进针角度与深度，逐步进针并复查确认，故B正确。\n【为什么错】A：不能随意穿刺，须精确定位。C：增强用于显示病灶血供，但不能替代定位。D：超声用于CT不适用的部位。E：MRI引导是另一种方式，不是CT导向。", "tr": "CT导向穿刺核心：定位层面→体表定位→角度深度测算→CT复查确认针尖位置。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1042", "t": "单选题", "s": "CT导向肺穿刺活检最常见的并发症是", "o": {"A": "气胸", "B": "大出血", "C": "对比剂过敏", "D": "感染", "E": "空气栓塞"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-042", "kp": "肺穿刺活检并发症", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】CT导向经皮肺穿刺活检最常见的并发症是气胸，多因穿刺针经胸膜时损伤肺组织或胸膜所致，故A正确。\n【为什么错】B：大出血相对少见。C：肺穿刺不用或少量用对比剂，过敏不是主要并发症。D：感染罕见。E：空气栓塞极为罕见。", "tr": "肺穿刺术后应复查CT观察有无气胸；病灶距胸膜远者气胸风险增大。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1043", "t": "单选题", "s": "CT导向穿刺活检的禁忌证不包括", "o": {"A": "严重出血倾向", "B": "拟穿刺部位有动脉瘤", "C": "患者不能屏气配合", "D": "肺内孤立小结节", "E": "严重心肺功能不全"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-043", "kp": "穿刺活检禁忌证", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】肺内孤立小结节正是CT导向穿刺活检的适应证之一，不属于禁忌证，故D符合题意。\n【为什么错】A：严重出血倾向为绝对禁忌。B：穿刺路径上有动脉瘤为禁忌。C：不能配合屏气影响定位与安全，属相对禁忌。E：严重心肺功能不全不能耐受为禁忌。", "tr": "注意审题：本题问的是“不属于禁忌证”的选项，小结节是适应证。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1044", "t": "单选题", "s": "CT检查前，去除被检部位金属异物（如发夹、金属假牙）的主要目的是", "o": {"A": "防止损坏机器", "B": "避免金属伪影影响图像质量", "C": "加快扫描速度", "D": "降低辐射剂量", "E": "便于摆位"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-044", "kp": "检查前去除金属", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】金属异物在CT扫描中会产生放射状伪影（射束硬化伪影），严重影响邻近组织显示，检查前去除金属异物是为了避免金属伪影，故B正确。\n【为什么错】A：金属异物一般不会损坏CT机。C：去除金属不加快扫描。D：去除金属与辐射剂量无关。E：摆位与金属去除无关。", "tr": "金属伪影为放射状低密度条纹，属于射束硬化伪影，检查前应去除一切金属物品。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1045", "t": "单选题", "s": "腹部CT检查前，患者的一般准备要求是", "o": {"A": "检查前禁食4～6小时，并口服适量对比剂充盈胃肠道", "B": "禁食24小时", "C": "大量饮水充盈膀胱", "D": "不需任何准备", "E": "检查前服用泻药排空所有肠道"}, "d": "易", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-045", "kp": "腹部CT检查前准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】腹部CT一般要求检查前禁食4～6小时，扫描前口服适量水或阳性对比剂充盈胃肠道，以区分肠管与邻近结构，故A正确。\n【为什么错】B：禁食24小时过长。C：充盈膀胱是盆腔检查的准备。D：腹部CT必须准备。E：并非所有腹部CT都需泻药清肠，一般肠道准备即可。", "tr": "腹部CT口服对比剂分阳性（碘水）与阴性（水），疑腹膜后或血管病变常用水作阴性对比剂。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1046", "t": "单选题", "s": "碘对比剂过敏反应的高危人群，检查前应重点询问的内容不包括", "o": {"A": "既往对比剂过敏史", "B": "哮喘病史", "C": "食物过敏史", "D": "年龄", "E": "严重心肾功能不全"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-046", "kp": "对比剂过敏高危因素", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】年龄不是对比剂过敏反应的高危因素，而既往对比剂过敏史、哮喘、多种药物/食物过敏史及严重心肾功能不全等才是需重点询问的内容，故D符合题意。\n【为什么错】A：既往对比剂过敏史是最高危因素。B：哮喘病史与过敏反应密切相关。C：食物及药物过敏史提示过敏体质。E：严重心肾功能不全是对比剂使用的重点评估项。", "tr": "对比剂过敏高危因素：过敏史、哮喘、药物过敏、心肾功能不全，老年本身不是禁忌但需评估。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1047", "t": "单选题", "s": "发生重度碘对比剂过敏反应时，首选的急救处理是", "o": {"A": "立即注射肾上腺素并停止检查、开放静脉、吸氧", "B": "继续扫描完成检查", "C": "口服抗组胺药即可", "D": "嘱患者自行休息", "E": "大量饮水"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-047", "kp": "对比剂过敏急救", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】重度碘对比剂过敏反应（过敏性休克）应立即停止注射对比剂，保持呼吸道通畅、吸氧、开放静脉，并肌注肾上腺素，故A正确。\n【为什么错】B：继续扫描会延误抢救。C：口服抗组胺药起效慢，不能用于重度反应。D：自行休息延误处理。E：大量饮水不能处理休克。", "tr": "重度过敏反应首选肾上腺素，而非糖皮质激素或抗组胺药，后者为辅助治疗。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1048", "t": "单选题", "s": "颅脑CT常规横断面扫描的基线是", "o": {"A": "听眦线（OML）", "B": "听眶下线（IOML）", "C": "眉间—枕外粗隆连线", "D": "矢状线", "E": "冠状线"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-048", "kp": "颅脑扫描基线", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑CT常规横断面扫描以听眦线（OML，即外耳道与外眦连线）为基线，扫描层面与基线平行，故A正确。\n【为什么错】B：听眶下线（IOML）多用于眼眶等检查。C：该连线是X线头颅侧位摄影的基准线，非CT扫描基线。D、E：矢状线、冠状线是定位方向，不是扫描基线。", "tr": "颅脑CT基线为OML（听眦线），基线向上平移或向下改变可减少或增加晶体受照。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1049", "t": "单选题", "s": "颅脑CT平扫的常规层厚一般为", "o": {"A": "1mm", "B": "2mm", "C": "5～10mm", "D": "15mm", "E": "0.5mm"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-049", "kp": "颅脑常规层厚", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑CT平扫常规层厚5～10mm（后颅窝可略薄），兼顾覆盖范围与显示质量，故C正确。\n【为什么错】A、B：1～2mm为薄层扫描，用于鞍区、内耳等。D：15mm层厚过厚。E：0.5mm用于HRCT精细结构。", "tr": "颅脑常规层厚5～10mm；后颅窝伪影较重时可缩小层厚。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1050", "t": "单选题", "s": "鞍区CT检查（疑垂体病变）一般采用的扫描方式是", "o": {"A": "常规10mm横断面", "B": "薄层（1～2mm）冠状位扫描并增强", "C": "矢状位厚层扫描", "D": "低剂量平扫", "E": "全身扫描"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-050", "kp": "鞍区扫描方式", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】鞍区结构细小（垂体、漏斗），CT检查多采用薄层（1～2mm）冠状位扫描，并常行增强扫描以观察垂体病变，故B正确。\n【为什么错】A：常规10mm层厚无法显示垂体细节。C：矢状位厚层不利于鞍区显示。D：低剂量平扫显示细微结构能力差。E：全身扫描不适用于鞍区。", "tr": "垂体微腺瘤CT敏感性有限，MRI是首选，CT用于显示鞍区骨质及钙化。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1051", "t": "单选题", "s": "眼部CT横断面扫描常用基线是", "o": {"A": "听眦线（OML）", "B": "听眶下线（IOML）", "C": "垂直于眶轴的线", "D": "鼻根线", "E": "乳突线"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-051", "kp": "眼部扫描基线", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】眼部CT横断面扫描以听眶下线（IOML，即眶下缘与外耳道连线）为基线，可较好显示眼球、视神经等结构，故B正确。\n【为什么错】A：听眦线用于颅脑常规扫描。C：垂直于眶轴的线不是眼部CT的常用基线。D：鼻根线非标准术语。E：乳突线用于耳部扫描。", "tr": "眼用IOML、颅脑用OML、耳部用OML或乳突线，注意各部位基线不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1052", "t": "单选题", "s": "颞骨（耳部）CT检查最常用、能清晰显示内耳精细结构的扫描技术是", "o": {"A": "常规层厚软组织窗扫描", "B": "高分辨力CT（薄层＋骨算法）", "C": "低剂量平扫", "D": "增强扫描", "E": "CT灌注"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-052", "kp": "颞骨HRCT", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】内耳结构细微（耳蜗、前庭、半规管），颞骨CT采用HRCT（薄层扫描＋骨算法高空间频率重建）可清晰显示骨迷路，故B正确。\n【为什么错】A：常规层厚软组织窗不能显示内耳细节。C：低剂量无法保证精细结构显示。D：增强不能显示骨性结构。E：灌注不用于内耳。", "tr": "颞骨HRCT是内耳、中耳骨质病变的经典检查；层厚常0.5～1mm。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1053", "t": "单选题", "s": "鼻窦CT检查常用的扫描位置组合是", "o": {"A": "横断面＋冠状位", "B": "仅横断面", "C": "仅矢状位", "D": "横断面＋矢状位", "E": "仅冠状位"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-053", "kp": "鼻窦CT扫描位置", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】鼻窦CT常采用横断面＋冠状位扫描，冠状位可更好显示窦口鼻道复合体及各窦口引流情况，故A正确。\n【为什么错】B、E：单一体位显示不全。C：矢状位不是鼻窦CT常规体位。D：横断面＋矢状位不如横断面＋冠状位常用。", "tr": "鼻窦冠状位扫描基线垂直于硬腭，可显示窦口与筛板。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1054", "t": "单选题", "s": "鼻窦CT冠状位扫描时，扫描基线与硬腭的关系是", "o": {"A": "平行", "B": "垂直", "C": "成45°角", "D": "成30°角", "E": "无要求"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-054", "kp": "鼻窦冠状位基线", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】鼻窦冠状位扫描基线应垂直于硬腭，以获得标准冠状断面，显示窦口鼻道复合体，故B正确。\n【为什么错】A：平行于硬腭的是横断面扫描。C、D：成角扫描不是标准冠状位。E：冠状位扫描对基线有明确要求。", "tr": "冠状位垂直硬腭、横断位平行硬腭，是鼻窦CT扫描的基本要求。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1055", "t": "单选题", "s": "口腔颌面部CT检查，为减少金属牙科修复体伪影，可采取的措施是", "o": {"A": "扫描前摘除可摘除的金属假牙", "B": "增加管电流", "C": "口服对比剂", "D": "改用MRI", "E": "增加层厚"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-055", "kp": "颌面部金属伪影处理", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (6)口腔颌面部", "ex": "【为什么对】金属牙科修复体（假牙、种植体）会产生放射状伪影，扫描前摘除可摘除的金属假牙是最直接的减伪影措施，故A正确。\n【为什么错】B：增加管电流不能消除金属伪影。C：口服对比剂不针对金属伪影。D：MRI虽对金属伪影表现不同，但并非所有患者适用且不能替代CT。E：增加层厚不能消除金属伪影。", "tr": "金属伪影是CT固有伪影，去除金属异物、金属伪影抑制重建算法可减轻。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1056", "t": "单选题", "s": "喉部CT检查时，为减少吞咽运动伪影，应嘱患者", "o": {"A": "平静呼吸，避免吞咽动作", "B": "持续咳嗽", "C": "大声发音", "D": "快速呼吸", "E": "屏气后快速喘气"}, "d": "易", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-056", "kp": "喉部CT扫描配合", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】喉部CT扫描时吞咽动作会引起喉结构位移和伪影，应嘱患者平静呼吸、避免吞咽，必要时可发持续音（如“咿”）使声带张开，故A正确。\n【为什么错】B：咳嗽会产生严重运动伪影。C：大声发音不是常规要求。D：快速呼吸使喉部移动。E：屏气后喘气动作幅度大。", "tr": "喉部检查的关键配合是“勿吞咽”，可发长音配合观察声带。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1057", "t": "单选题", "s": "颈部CT检查，为评估甲状腺结节性质，正确的做法是", "o": {"A": "行增强扫描观察结节强化情况", "B": "仅平扫即可", "C": "仅行CT灌注", "D": "口服对比剂显示甲状腺", "E": "用肺窗观察"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-057", "kp": "颈部增强扫描", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】颈部（甲状腺）检查常需增强扫描，通过观察结节的强化程度、强化方式及有无钙化、周围淋巴结等判断性质，故A正确。\n【为什么错】B：平扫对甲状腺结节定性价值有限。C：灌注不是甲状腺常规检查。D：口服对比剂不进入甲状腺。E：肺窗用于胸部肺组织。", "tr": "甲状腺CT增强可显示结节强化与颈部淋巴结；注意对比剂中含碘对甲状腺功能的影响。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1058", "t": "单选题", "s": "胸部CT扫描时，常规要求患者", "o": {"A": "深吸气后屏气扫描", "B": "呼气末屏气扫描", "C": "自由呼吸扫描", "D": "浅快呼吸扫描", "E": "咳嗽后扫描"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-058", "kp": "胸部CT呼吸配合", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】胸部CT常规在深吸气后屏气扫描，使肺组织充分膨胀、减少呼吸运动伪影，故A正确。\n【为什么错】B：呼气末屏气肺膨胀差，不利于肺实质观察。C：自由呼吸产生运动伪影。D：浅快呼吸肺显示不佳。E：咳嗽产生严重伪影。", "tr": "胸部及上腹部CT均要求深吸气后屏气，训练患者屏气是检查前准备的重要内容。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1059", "t": "单选题", "s": "先天性心脏病CT检查前，对婴幼儿常用的镇静方式是", "o": {"A": "口服水合氯醛", "B": "静脉全身麻醉一律应用", "C": "不予处理", "D": "肌注大量镇静剂", "E": "硬膜外麻醉"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-059", "kp": "婴幼儿CT镇静", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (10)先天性心脏病", "ex": "【为什么对】婴幼儿不能配合屏气与制动，常口服水合氯醛等镇静后检查，以保证扫描质量与安全，故A正确。\n【为什么错】B：并非一律需要全身麻醉，根据情况选择。C：不处理无法完成检查。D：肌注镇静剂量需严格控制，口服更常用。E：硬膜外麻醉不用于此。", "tr": "儿童CT检查强调镇静与防护，按体重计算镇静剂量并监测生命体征。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1060", "t": "单选题", "s": "腹部CT增强扫描时，上腹部扫描一般要求患者", "o": {"A": "屏气扫描", "B": "自由呼吸", "C": "持续呼气", "D": "深呼吸不屏气", "E": "打哈欠"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-060", "kp": "腹部CT屏气", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】上腹部CT扫描必须屏气，以避免膈肌运动造成肝、脾、胰腺等器官位移和运动伪影，故A正确。\n【为什么错】B：自由呼吸产生运动伪影。C：持续呼气使腹腔脏器上移。D：深呼吸不屏气同样有运动伪影。E：打哈欠明显不配合。", "tr": "上腹部多期增强每期都需屏气，检查前应充分训练患者。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1061", "t": "单选题", "s": "盆腔CT检查前，为良好显示膀胱及盆腔器官，应", "o": {"A": "让患者充盈膀胱（憋尿）", "B": "排空膀胱", "C": "大量进食", "D": "无需任何准备", "E": "服用利尿剂排空"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-061", "kp": "盆腔CT膀胱充盈", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】盆腔CT检查前嘱患者充盈膀胱，可推开小肠、显示膀胱壁及周围结构，故A正确。\n【为什么错】B：排空膀胱不利于膀胱及周围结构显示。C：进食会形成肠道内容物干扰。D：盆腔检查有明确准备要求。E：利尿剂会使膀胱空虚。", "tr": "盆腔CT与腹部CT准备不同：盆腔要充盈膀胱，必要时用阴道纱布等标记。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1062", "t": "单选题", "s": "腰椎间盘CT检查，为准确显示椎间盘，扫描层面应", "o": {"A": "平行于椎间隙", "B": "垂直于椎间隙", "C": "与椎体长轴平行即可", "D": "随意定位", "E": "平行于床面"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-062", "kp": "椎间盘扫描定位", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】椎间盘CT扫描时，扫描层面应与椎间隙平行（通常在侧位定位像上逐层对准椎间隙），才能准确显示椎间盘与椎管关系，故A正确。\n【为什么错】B：垂直于椎间隙是矢状位的概念。C：平行于椎体长轴不能保证层面穿过椎间盘。D：随意定位会漏扫或倾斜。E：平行床面未必对准椎间隙。", "tr": "椎间盘扫描需在定位像上倾斜机架或重建使层面平行椎间隙，避免假性突出。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1063", "t": "单选题", "s": "四肢骨关节CT检查时，为便于对比观察，常采取的方式是", "o": {"A": "双侧同时扫描或双侧扫描对照", "B": "只扫患侧", "C": "只扫健侧", "D": "单侧增强扫描", "E": "只扫关节面一层"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-063", "kp": "四肢CT双侧对照", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】四肢骨关节结构对称，双侧同时扫描或双侧对照扫描可帮助判断细微异常与生理性变异，故A正确。\n【为什么错】B：只扫患侧无法对照。C：只扫健侧无诊断意义。D：增强不是四肢骨关节常规。E：单层扫描不能全面显示病变。", "tr": "四肢关节CT常双侧对照，用于微小骨折、发育异常的判断。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1064", "t": "多选题", "s": "关于CT窗宽窗位的叙述，正确的有", "o": {"A": "窗宽决定显示CT值的范围", "B": "窗位是窗的中心值", "C": "窗宽增大时图像对比度降低", "D": "窗位升高时图像整体变亮", "E": "窗宽窗位只影响显示，不影响原始数据"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-064", "kp": "窗宽窗位综合", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】窗宽决定CT值显示范围，窗位是窗的中心值，窗宽增大对比度降低；窗宽窗位只改变显示效果，不改变原始数据，故ABCE正确。\n【为什么错】D：窗位升高时显示范围向高CT值方向移动，图像整体变暗而非变亮。", "tr": "窗位升高变暗、窗位降低变亮；窗宽增大变灰（对比度降低）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1065", "t": "多选题", "s": "影响CT空间分辨力的因素包括", "o": {"A": "像素大小", "B": "焦点尺寸", "C": "探测器孔径", "D": "窗宽设置", "E": "重建算法"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-065", "kp": "空间分辨力影响因素", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】空间分辨力受像素大小、焦点尺寸、探测器孔径、重建算法（高空间频率算法）等影响，故ABCE正确。\n【为什么错】D：窗宽窗位只影响图像显示，不影响空间分辨力。", "tr": "空间分辨力是硬件与算法决定的固有属性，窗技术不能改变。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1066", "t": "多选题", "s": "关于螺距的叙述，正确的有", "o": {"A": "螺距增大，扫描速度加快", "B": "螺距增大，可减少层间重叠", "C": "螺距过大图像质量下降", "D": "螺距与准直器宽度无关", "E": "螺距等于床移动距离除以准直器宽度"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-066", "kp": "螺距综合", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】螺距＝床移距离÷准直宽度；螺距增大则单位时间覆盖范围增大、扫描加快、层间重叠减少，但过大时采样稀疏、图像质量下降，故ABCE正确。\n【为什么错】D：螺距定义中分母正是准直器宽度，二者密切相关。", "tr": "大螺距换速度、小螺距保质量，两者需权衡。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1067", "t": "多选题", "s": "CT图像的伪影类型包括", "o": {"A": "运动伪影", "B": "金属伪影", "C": "射束硬化伪影", "D": "部分容积效应", "E": "增大窗宽可消除图像伪影"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-067", "kp": "CT伪影分类", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】CT伪影类型包括运动伪影、金属伪影、射束硬化伪影及部分容积效应等，故ABCD正确。\n【为什么错】E：窗宽窗位只改变图像显示效果，不能消除伪影，伪影须通过去除金属、减少运动、修正算法等处理。", "tr": "注意区分：伪影是图像失真；运动伪影与金属伪影最常考，窗技术不能消除伪影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1068", "t": "多选题", "s": "心电门控扫描中，回顾性心电门控的特点包括", "o": {"A": "辐射剂量相对较高", "B": "可在任意心动时相重建图像", "C": "适用于心律不齐患者（可配合心电编辑）", "D": "辐射剂量低于前瞻性门控", "E": "采集连续数据并同步记录心电信号"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-068", "kp": "回顾性心电门控特点", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】回顾性心电门控连续采集并记录心电信号，可任意时相重建，但因全程扫描剂量较高；心律不齐时可通过心电编辑校正，故ABCE正确。\n【为什么错】D：回顾性门控剂量高于前瞻性门控，表述相反。", "tr": "前瞻性门控剂量低、时相选择受限；回顾性门控剂量高、时相灵活。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1069", "t": "多选题", "s": "下列属于CT特殊扫描技术的有", "o": {"A": "高分辨力扫描（HRCT）", "B": "薄层扫描", "C": "低剂量扫描", "D": "靶扫描（放大扫描）", "E": "增强扫描"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-069", "kp": "特殊扫描技术", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】HRCT、薄层扫描、低剂量扫描、靶扫描均属特殊扫描技术，故ABCD正确。\n【为什么错】E：增强扫描是独立的检查方法分类，不属于特殊扫描技术。", "tr": "特殊扫描技术包括：薄层、HRCT、低剂量、靶扫描、动态扫描、灌注等，增强是另一分类。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1070", "t": "多选题", "s": "HRCT的临床应用包括", "o": {"A": "弥漫性肺疾病（肺间质病）", "B": "颞骨内耳精细结构", "C": "肺小结节分析", "D": "肝脏占位定性", "E": "颅底骨结构"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-070", "kp": "HRCT临床应用", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】HRCT以高空间分辨力见长，适用于弥漫性肺病、内耳、肺小结节、颅底骨结构等精细结构显示，故ABCE正确。\n【为什么错】D：肝脏占位定性主要依靠增强多期扫描，HRCT不是首选。", "tr": "HRCT优势在空间分辨力，用于精细结构；软组织病灶定性用增强扫描。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1071", "t": "多选题", "s": "低剂量CT扫描时，为保持图像质量可采用的技术包括", "o": {"A": "降低管电流", "B": "降低管电压", "C": "迭代重建算法", "D": "增大螺距", "E": "增加扫描次数"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-071", "kp": "低剂量技术", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】低剂量CT通过降低管电流/管电压减少辐射，并用迭代重建算法抑制噪声以保证图像质量，故ABC正确。\n【为什么错】D：增大螺距虽可降低剂量但会降低图像质量，且不是保证质量的措施。E：增加扫描次数会增加剂量，与低剂量目标相反。", "tr": "低剂量CT的关键是“降剂量+迭代重建保质量”；儿童检查尤其重视。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1072", "t": "多选题", "s": "CT灌注成像的主要参数包括", "o": {"A": "脑血流量（CBF）", "B": "脑血容量（CBV）", "C": "平均通过时间（MTT）", "D": "达峰时间（TTP）", "E": "骨密度（BMD）"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-072", "kp": "灌注参数", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】CT灌注参数包括CBF、CBV、MTT、TTP等，故ABCD正确。\n【为什么错】E：BMD为骨密度参数，不属于CT灌注参数；灌注参数中通透性PS主要用于肿瘤灌注评估。", "tr": "脑缺血评估常用CBF/CBV/MTT；PS主要用于肿瘤灌注与血脑屏障评估。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1073", "t": "多选题", "s": "CT灌注成像的临床应用包括", "o": {"A": "急性脑梗死缺血半暗带评估", "B": "脑肿瘤血供评估", "C": "肝肿瘤灌注", "D": "冠脉粥样硬化斑块显示", "E": "肺栓塞诊断"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-073", "kp": "灌注临床应用", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】CT灌注主要用于急性脑梗死半暗带评估、脑及腹部肿瘤血供评估等，故ABC正确。\n【为什么错】D：冠脉斑块显示依靠冠脉CTA，不是灌注。E：肺栓塞诊断主要依靠CTA。", "tr": "灌注看“血供功能”，CTA看“解剖形态”，用途不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1074", "t": "多选题", "s": "CT血管成像（CTA）的后处理显示技术包括", "o": {"A": "最大密度投影（MIP）", "B": "容积再现（VR）", "C": "曲面重建（CPR）", "D": "多平面重建（MPR）", "E": "增强扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-074", "kp": "CTA后处理技术", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】CTA常用后处理包括MIP、VR、CPR及MPR等，故ABCD正确。\n【为什么错】E：增强扫描是图像采集方法，不属于CTA原始数据的后处理显示技术。", "tr": "CPR尤其适用于迂曲血管（如冠状动脉）；VR立体感强但受阈值影响。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1075", "t": "多选题", "s": "冠状动脉CTA检查前及检查中的要点包括", "o": {"A": "控制心率在70次/分以下", "B": "必要时口服β受体阻滞剂", "C": "扫描前训练患者屏气", "D": "采用心电门控扫描", "E": "无需控制心律，扫描后心电编辑可完全替代"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-075", "kp": "冠脉CTA要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠脉CTA需控制心率、必要时用β受体阻滞剂，训练屏气、心电门控扫描，故ABCD正确。\n【为什么错】E：心电编辑是对心律不齐数据的事后校正，不能完全替代检查前的心率与心律控制。", "tr": "冠脉CTA成败关键在于心率、心律与屏气配合，心电编辑是补救手段。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1076", "t": "多选题", "s": "双能量CT的临床应用包括", "o": {"A": "虚拟平扫（VNC）", "B": "碘图定量分析", "C": "去骨CTA", "D": "结石成分分析", "E": "增大窗宽提高分辨力"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-076", "kp": "双能量CT临床应用", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT临床应用包括虚拟平扫、碘图、去骨CTA及结石成分分析等，故ABCD正确。\n【为什么错】E：增大窗宽只改变显示效果，不提高分辨力，不属于双能量CT的临床应用。", "tr": "双能量CT“物质分离”是其技术核心，衍生出VNC、碘图、去骨、成分分析等应用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1077", "t": "多选题", "s": "CT导向穿刺活检前，操作者应重点关注的准备包括", "o": {"A": "复习影像资料确定穿刺靶点", "B": "了解患者凝血功能", "C": "停止抗凝药物评估出血风险", "D": "向患者解释并取得配合", "E": "穿刺前无需评估患者呼吸配合能力"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-077", "kp": "穿刺活检前准备", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】CT导向穿刺前需确定靶点、评估凝血功能与出血风险、取得患者配合，故ABCD正确。\n【为什么错】E：肺穿刺需要患者配合屏气以固定病灶位置，评估呼吸配合能力是必要的准备内容。", "tr": "凝血功能异常是穿刺禁忌，术前必须评估；呼吸配合影响穿刺安全。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1078", "t": "多选题", "s": "CT导向穿刺活检的注意事项包括", "o": {"A": "选择最短且安全的进针路径", "B": "避开血管、神经及重要脏器", "C": "穿肺组织时嘱患者屏气", "D": "术后留观观察有无气胸", "E": "穿多针取材越多越好"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-078", "kp": "穿刺活检注意事项", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】穿刺应选择最短安全路径、避开血管神经脏器，穿肺时屏气，术后观察气胸，故ABCD正确。\n【为什么错】E：盲目多针取材增加出血、气胸等并发症风险，应根据需要适度取材。", "tr": "穿刺安全第一，路径规划比取材数量更重要。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1079", "t": "多选题", "s": "CT检查前患者的常规准备包括", "o": {"A": "去除检查部位金属异物", "B": "按需禁食", "C": "进行屏气训练", "D": "询问对比剂过敏史（增强检查）", "E": "嘱患者多喝水可替代禁食"}, "d": "易", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-079", "kp": "患者检查前准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】患者准备包括去除金属异物、按需禁食、屏气训练、增强前询问过敏史等，故ABCD正确。\n【为什么错】E：多喝水不能替代禁食要求，腹部检查仍需禁食。", "tr": "增强扫描前必须询问碘过敏史并签署知情同意。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1080", "t": "多选题", "s": "CT检查前设备与操作者的准备包括", "o": {"A": "检查设备球管、探测器工作状态", "B": "预热球管", "C": "确认高压注射器状态（增强检查）", "D": "校准空气值（水模校准）", "E": "无需核对患者信息即可扫描"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-080", "kp": "设备与操作者准备", "ch": "九、CT检查技术 → 3.检查前准备 → (1)设备", "ex": "【为什么对】操作者需检查设备状态、预热球管、确认注射器、进行校准等，故ABCD正确。\n【为什么错】E：扫描前必须核对患者信息与检查部位，防止错扫漏扫，核对不可省略。", "tr": "每日开机后的空气校准是保证CT值准确的基础；核对患者信息是流程底线。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1081", "t": "多选题", "s": "碘对比剂使用中的注意事项包括", "o": {"A": "询问过敏史", "B": "控制注射流率，防止外渗", "C": "密切观察患者反应", "D": "备好急救药品与设备", "E": "所有患者均可放心使用高渗对比剂"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-081", "kp": "对比剂使用注意", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】使用碘对比剂须询问过敏史、控制流率防外渗、观察反应并备急救物品，故ABCD正确。\n【为什么错】E：高渗对比剂不良反应发生率较高，高风险患者应选用等渗或低渗对比剂。", "tr": "高危患者（过敏史、心肾功能不全）应慎用对比剂并优先选择非离子型等渗/低渗制剂。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1082", "t": "多选题", "s": "颅脑CT检查的适应证包括", "o": {"A": "颅内出血", "B": "颅脑外伤", "C": "脑梗死急性期", "D": "颅骨骨折", "E": "甲状腺功能亢进"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-082", "kp": "颅脑CT适应证", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑CT是颅内出血、外伤、急性梗死、骨折等的首选或重要检查手段，故ABCD正确。\n【为什么错】E：甲状腺功能亢进属于碘对比剂使用的相对禁忌，不是颅脑CT的适应证。", "tr": "急性脑出血CT呈高密度，急性梗死早期可能阴性，需结合灌注。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1083", "t": "多选题", "s": "关于眼部CT检查的叙述，正确的有", "o": {"A": "常采用薄层扫描", "B": "横断面基线为听眶下线（IOML）", "C": "检查眼内异物时首选CT", "D": "可用冠状位补充观察", "E": "金属异物患者应行MRI检查"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-083", "kp": "眼部CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】眼部CT采用薄层扫描、横断面基线为IOML，常加冠状位；眼内金属异物应首选CT而非MRI，故ABCD正确。\n【为什么错】E：眼内金属异物是MRI的禁忌证（磁致移动损伤眼球），应选CT。", "tr": "金属异物禁做MRI，CT是眼内异物定位的首选。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1084", "t": "多选题", "s": "颞骨（耳部）HRCT的扫描要点包括", "o": {"A": "薄层扫描（0.5～1mm）", "B": "骨算法（高空间频率）重建", "C": "大窗宽骨窗显示", "D": "横断面加冠状位扫描", "E": "软组织算法重建"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-084", "kp": "颞骨HRCT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】颞骨HRCT采用薄层、骨算法重建、大窗宽骨窗显示，常横断面加冠状位扫描，故ABCD正确。\n【为什么错】E：软组织算法降低空间分辨力，不利于内耳骨迷路显示，颞骨HRCT应使用骨算法。", "tr": "耳部骨窗窗宽常1000～3000HU，窗位300～500HU，以显示骨性结构。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1085", "t": "多选题", "s": "鼻窦CT检查的技术要点包括", "o": {"A": "横断面加冠状位扫描", "B": "冠状位扫描基线垂直于硬腭", "C": "扫描前去除金属假牙", "D": "显示窦口鼻道复合体", "E": "必须增强扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-085", "kp": "鼻窦CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】鼻窦CT常规横断面加冠状位，冠状位垂直硬腭，扫描前去除金属假牙，重点显示窦口鼻道复合体，故ABCD正确。\n【为什么错】E：鼻窦CT平扫即可满足多数诊断，增强非必须。", "tr": "窦口鼻道复合体是鼻窦炎CT评估的重点区域。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1086", "t": "多选题", "s": "胸部CT扫描的技术要点包括", "o": {"A": "深吸气后屏气扫描", "B": "常规层厚5～10mm", "C": "可疑微小病变加用HRCT", "D": "肺窗加纵隔窗观察", "E": "扫描时快速呼吸减少伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-086", "kp": "胸部CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】胸部CT须深吸气后屏气，常规层厚5～10mm，必要时HRCT，肺窗加纵隔窗观察，故ABCD正确。\n【为什么错】E：快速呼吸会加重呼吸运动伪影，胸部CT应屏气扫描。", "tr": "肺窗与纵隔窗需同时观察，肺窗显示肺纹理、纵隔窗显示血管与淋巴结。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1087", "t": "多选题", "s": "心脏冠脉CTA检查的禁忌证或相对禁忌证包括", "o": {"A": "碘对比剂严重过敏", "B": "严重心功能不全", "C": "未控制的心律失常", "D": "肾功能严重不全", "E": "轻度窦性心动过速经药物控制"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-087", "kp": "冠脉CTA禁忌证", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】碘过敏、严重心肾功能不全、未控制的心律失常是冠脉CTA禁忌证或相对禁忌证，故ABCD正确。\n【为什么错】E：轻度窦速经β受体阻滞剂控制后可完成检查，不是禁忌。", "tr": "冠脉CTA以心率70次/分为界，控制不佳者改期或改行其他检查。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1088", "t": "多选题", "s": "腹部CT增强多期扫描时，肝脏常见的期相包括", "o": {"A": "动脉期", "B": "门静脉期", "C": "平衡期（延迟期）", "D": "排泄期", "E": "骨密度期"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-088", "kp": "肝脏增强期相", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肝脏增强常规包括动脉期（25～30s）、门静脉期（60～70s）和平衡期/延迟期（120～180s），故ABC正确。\n【为什么错】D：排泄期是肾脏及泌尿系的期相，不用于肝脏常规增强。E：骨密度期不是增强期相。", "tr": "肝脏三期：动脉期、门脉期、平衡期；肾脏分皮髓质期、实质期、排泄期。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1089", "t": "多选题", "s": "胰腺CT检查的技术要点包括", "o": {"A": "薄层扫描", "B": "增强多期扫描（动脉期、实质期、门脉期）", "C": "口服水或对比剂充盈胃和十二指肠", "D": "屏气扫描", "E": "只做平扫即可定性"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-089", "kp": "胰腺CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】胰腺CT需薄层、增强多期（动脉期、实质期、门脉期）、口服水充盈胃肠、屏气扫描，故ABCD正确。\n【为什么错】E：胰腺肿瘤定性高度依赖增强扫描，平扫不足以定性。", "tr": "胰腺增强动脉期约25～30s显示胰腺实质与血管关系最佳。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1090", "t": "多选题", "s": "肾脏CT检查的期相包括", "o": {"A": "皮髓质期（皮质期）", "B": "实质期", "C": "排泄期（肾盂期）", "D": "动脉期", "E": "骨窗期"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-090", "kp": "肾脏增强期相", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肾脏增强扫描包括皮髓质期（皮质期）、实质期和排泄期，其中排泄期显示肾盂输尿管；也涉及动脉期评估肾动脉，故ABCD正确。\n【为什么错】E：骨窗期不是肾脏增强期相。", "tr": "肾脏排泄期（约3～5分钟）可显示泌尿系全程，是泌尿系CTU的基础。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1091", "t": "多选题", "s": "盆腔CT检查前的准备包括", "o": {"A": "充盈膀胱", "B": "口服对比剂或水充盈肠道", "C": "必要时阴道填塞标记物", "D": "排空膀胱", "E": "去除金属节育环等异物"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-091", "kp": "盆腔CT准备", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】盆腔CT需充盈膀胱、口服对比剂充盈肠道，女性必要时阴道填塞标记，并去除金属节育环等异物，故ABCE正确。\n【为什么错】D：排空膀胱不利于膀胱及盆腔器官显示，应为充盈膀胱。", "tr": "盆腔检查“憋尿”与腹部“禁食”一样是经典考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1092", "t": "多选题", "s": "脊柱CT检查的技术要点包括", "o": {"A": "椎间盘扫描层面平行于椎间隙", "B": "椎间盘扫描采用薄层", "C": "椎体骨折观察用骨窗", "D": "可进行矢状位重建", "E": "椎体扫描常规采用厚层20mm"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-092", "kp": "脊柱CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】椎间盘扫描层面平行椎间隙并薄层，椎体用骨窗观察，可矢状位重建，故ABCD正确。\n【为什么错】E：椎体常规扫描层厚一般3～5mm，20mm过厚。", "tr": "椎间盘1～2mm薄层扫描，椎体3～5mm常规层厚。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1093", "t": "多选题", "s": "四肢骨关节CT检查的技术要点包括", "o": {"A": "双侧对照扫描", "B": "薄层扫描", "C": "骨窗加软组织窗观察", "D": "必要时三维重建（MPR、VR）", "E": "一律行增强扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-093", "kp": "四肢CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】四肢CT双侧对照、薄层扫描、骨窗加软组织窗，必要时三维重建，故ABCD正确。\n【为什么错】E：四肢骨关节平扫即可满足多数诊断，增强并非一律需要。", "tr": "关节骨折三维重建（VR）可直观显示骨折移位情况，辅助手术规划。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1094", "t": "多选题", "s": "关于CT灌注成像的叙述，正确的有", "o": {"A": "需快速团注对比剂", "B": "扫描方式为同层动态扫描", "C": "可定量计算CBF、CBV", "D": "半暗带表现为CBF下降、CBV正常或升高", "E": "灌注检查对运动不敏感，患者无需制动"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-094", "kp": "CT灌注综合", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】CT灌注需快速团注、同层动态扫描，可定量CBF/CBV等参数，半暗带CBF下降而CBV正常或升高，故ABCD正确。\n【为什么错】E：灌注对运动十分敏感，患者须保持静止，头颈部还要固定。", "tr": "灌注扫描对运动伪影极其敏感，患者制动与配合至关重要。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1095", "t": "多选题", "s": "CT血管成像（CTA）检查前的准备包括", "o": {"A": "询问碘过敏史", "B": "建立良好的静脉通道", "C": "选择合适的高压注射参数", "D": "训练患者屏气", "E": "患者常规服用β受体阻滞剂"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-095", "kp": "CTA检查前准备", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】CTA检查前需询问过敏史、建立静脉通道、设置高压注射参数并训练屏气，故ABCD正确。\n【为什么错】E：β受体阻滞剂仅在冠脉CTA心率过快时使用，并非所有CTA常规服用。", "tr": "CTA成败与注射流率、延迟时间密切相关，静脉通道质量直接影响团注效果。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1096", "t": "多选题", "s": "关于CT导向穿刺活检的叙述，正确的有", "o": {"A": "适用于肺内孤立结节定性", "B": "可用于纵隔、骨骼等部位取材", "C": "气胸是肺穿刺最常见并发症", "D": "严重出血倾向为禁忌证", "E": "穿刺过程无需CT复查确认针尖位置"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-096", "kp": "穿刺活检综合", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】CT导向穿刺适用于肺结节及纵隔、骨骼等取材，气胸是最常见并发症，严重出血倾向为禁忌；进针过程中需CT复查确认针尖位置，故ABCD正确。\n【为什么错】E：必须通过CT复查确认针尖位置后再取材，以确保安全准确。", "tr": "穿刺的“安全第一”：每一步进针后都需CT复查确认位置。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1097", "t": "多选题", "s": "关于鞍区CT检查的叙述，正确的有", "o": {"A": "常采用薄层扫描", "B": "常规行冠状位扫描", "C": "可结合增强扫描", "D": "用于显示鞍区骨质改变与钙化", "E": "垂体微腺瘤诊断首选CT平扫"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-097", "kp": "鞍区CT综合", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】鞍区CT薄层、冠状位扫描并常增强，用于显示鞍区骨质、钙化，故ABCD正确。\n【为什么错】E：垂体微腺瘤的首选检查是MRI（高软组织分辨力），CT平扫对微腺瘤不敏感。", "tr": "垂体病变首选MRI，CT主要补充显示骨质破坏与钙化。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1098", "t": "多选题", "s": "关于喉部及颈部CT检查的叙述，正确的有", "o": {"A": "喉部扫描应避免吞咽动作", "B": "颈部检查常需增强扫描", "C": "扫描范围应覆盖病灶及引流区域", "D": "嘱患者平静呼吸", "E": "颈部扫描一律采用厚层10mm"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-098", "kp": "喉颈部CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】喉部扫描避免吞咽、平静呼吸，颈部常增强并覆盖病灶及引流区域，故ABCD正确。\n【为什么错】E：颈部结构精细，常用薄层（2～5mm）扫描，厚层10mm不利于精细观察。", "tr": "颈部CT薄层扫描并增强，观察淋巴结时需覆盖颈部全程。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U09-1099a", "t": "共用题干题", "s": "该患者首选的CT检查方法是", "o": {"A": "颅脑平扫", "B": "颅脑增强扫描", "C": "CT灌注成像", "D": "颅脑CTA", "E": "双能量去骨扫描"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-099", "kp": "颅脑外伤检查方法选择", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑外伤首选颅脑CT平扫，可快速显示急性硬膜外/下血肿、脑挫裂伤及颅骨骨折，无需注射对比剂，故A正确。\n【为什么错】B：增强扫描用于肿瘤、炎症等，外伤急性期无必要。C：灌注用于缺血评估。D：CTA用于血管病变。E：双能量去骨用于CTA去骨，非外伤常规。", "tr": "急性出血平扫呈高密度，是神经外科急诊处理的关键，检查越快越好。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0901", "gs": "患者男，45岁，车祸致头部外伤后意识模糊1小时急诊就诊，查体见左颞部头皮血肿，双侧瞳孔等大等圆，对光反射存在。急诊医生疑颅内出血，申请颅脑CT检查。"}, {"id": "U09-1099b", "t": "共用题干题", "s": "该患者颅脑CT平扫的扫描基线是", "o": {"A": "听眶下线（IOML）", "B": "听眦线（OML）", "C": "眉间线", "D": "矢状线", "E": "冠状线"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-100", "kp": "颅脑扫描基线", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑CT横断面扫描以听眦线（OML，外耳道与外眦连线）为基线，层面与基线平行，故B正确。\n【为什么错】A：IOML（听眶下线）用于眼部等扫描。C：眉间线非标准基线。D、E：矢状线、冠状线为定位方向，非颅脑横断面扫描基线。", "tr": "颅脑CT用OML、眼部用IOML，两个基线不要混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0901", "gs": ""}, {"id": "U09-1099c", "t": "共用题干题", "s": "平扫发现左侧急性硬膜外血肿，呈梭形高密度影，此时影像上血肿的密度特征为", "o": {"A": "低密度", "B": "等密度", "C": "高密度", "D": "混合密度", "E": "脂肪密度"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-101", "kp": "急性血肿CT密度", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】急性期（数小时内）血液凝固、血红蛋白含量高，CT平扫呈高密度，故C正确。\n【为什么错】A：低密度见于慢性血肿吸收期或脑水肿。B：等密度见于亚急性期血肿溶解期。D：混合密度可见于活动性出血。E：脂肪密度见于脂肪瘤等，与血肿无关。", "tr": "硬膜外血肿梭形、不跨颅缝；硬膜下血肿新月形、跨颅缝，是经典鉴别点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0901", "gs": ""}, {"id": "U09-1100a", "t": "共用题干题", "s": "该患者作为肺癌高危人群，胸部CT筛查宜采用", "o": {"A": "常规剂量增强扫描", "B": "低剂量CT平扫", "C": "CT灌注成像", "D": "常规剂量多层平扫", "E": "冠脉CTA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-102", "kp": "肺癌低剂量筛查", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】肺癌高危人群筛查推荐低剂量CT（LDCT），在保证肺结节检出的同时大幅降低辐射剂量，故B正确。\n【为什么错】A：筛查用平扫即可，增强非必需。C：灌注用于定性评估，不用于筛查。D：常规剂量平扫剂量较高，不符合筛查理念。E：冠脉CTA针对冠脉病变。", "tr": "LDCT筛查的关键是低剂量+肺结节检出，常规采用低管电流（如40～50mAs）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0902", "gs": "患者男，62岁，吸烟30年，每年约1包，社区组织肺癌高危人群低剂量CT筛查。患者无咳嗽、咯血等症状，要求进行胸部CT检查。"}, {"id": "U09-1100b", "t": "共用题干题", "s": "低剂量CT筛查发现右上肺一枚约6mm磨玻璃结节，为观察其内部细微结构，应加做的检查是", "o": {"A": "厚层扫描", "B": "高分辨力CT（HRCT）薄层扫描", "C": "CT灌注", "D": "增强扫描", "E": "双能量去骨"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-103", "kp": "肺结节HRCT", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】肺内磨玻璃小结节需HRCT（1～2mm薄层＋高空间频率算法）观察边界、内部密度及有无空泡征等细微结构，故B正确。\n【为什么错】A：厚层扫描有部分容积效应，无法显示细微结构。C：灌注用于血供评估。D：小于1cm的磨玻璃结节增强价值有限。E：去骨用于CTA。", "tr": "肺磨玻璃结节评估强调HRCT薄层扫描，避免漏诊浸润成分。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0902", "gs": ""}, {"id": "U09-1101a", "t": "共用题干题", "s": "该患者进行冠脉CTA前，心率控制的目标是", "o": {"A": "控制在70次/分以下", "B": "控制在100次/分以下", "C": "心率越低越好，控制在40次/分", "D": "无需控制心率", "E": "控制在80～90次/分即可"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-104", "kp": "冠脉CTA心率控制", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠脉CTA要求心率≤70次/分（理想≤65次/分），可通过口服β受体阻滞剂控制，故A正确。\n【为什么错】B：100次/分以下仍偏快，运动伪影明显。C：心率并非越低越好，40次/分也影响心脏生理。D：不控制心率图像质量无法保证。E：80～90次/分仍偏快。", "tr": "心率过快时冠脉运动伪影明显，通常以70次/分为界。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0903", "gs": "患者男，58岁，反复胸闷心前区不适2周，心电图示窦性心律、偶发房性早搏，心率86次/分。临床疑冠心病，拟行冠状动脉CTA检查。"}, {"id": "U09-1101b", "t": "共用题干题", "s": "该患者检查中出现偶发房性早搏，采集数据后可采取的图像校正措施是", "o": {"A": "心电编辑", "B": "增大窗宽", "C": "改变窗位", "D": "缩小视野", "E": "改用软组织算法重建"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-105", "kp": "心电编辑应用", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】心律不齐（如房早）导致部分心动周期扫描数据错位，可通过心电编辑将异常周期的数据用相邻正常周期的数据替代，消除图像错位伪影，故A正确。\n【为什么错】B：窗宽改变显示对比度，不解决错位。C：窗位调整灰度，不解决错位。D：视野改变像素大小。E：算法改变空间分辨力，不解决心电错位。", "tr": "心电编辑适用于回顾性心电门控扫描数据，是冠脉CTA心律不齐的重要补救手段。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0903", "gs": ""}, {"id": "U09-1102a", "t": "共用题干题", "s": "肝脏增强扫描动脉期的延迟时间一般为", "o": {"A": "25～30秒", "B": "60～70秒", "C": "120～180秒", "D": "3～5分钟", "E": "15秒内"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-106", "kp": "肝脏动脉期时间", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肝脏增强动脉期一般在注药后25～30秒扫描，此时肝动脉强化明显，富血供肝癌显示最佳，故A正确。\n【为什么错】B：60～70秒为门静脉期。C：120～180秒为平衡期。D：3～5分钟为延迟期。E：15秒内对比剂尚未到达肝动脉。", "tr": "肝癌“快进快出”：动脉期高强化、门脉期/延迟期廓清，是典型表现。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0904", "gs": "患者男，55岁，乙肝病史10余年，近期乏力、消瘦，超声发现肝右叶低回声占位，甲胎蛋白明显升高。临床疑肝细胞癌，拟行肝脏三期增强CT检查。"}, {"id": "U09-1102b", "t": "共用题干题", "s": "该患者增强扫描前，口服对比剂的作用是", "o": {"A": "充盈胃肠道，区分肠管与腹腔脏器", "B": "增强肝实质", "C": "减少辐射剂量", "D": "提高空间分辨力", "E": "代替静脉对比剂"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-107", "kp": "口服对比剂作用", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】腹部CT口服阳性（碘水）或阴性（水）对比剂充盈胃肠道，使肠管与腹腔脏器、病灶区分，避免肠管误诊为病变，故A正确。\n【为什么错】B：口服对比剂不进入肝实质血供。C：口服对比剂与辐射剂量无关。D：不影响空间分辨力。E：不能代替静脉对比剂增强。", "tr": "口服对比剂分阳性（高密度）与阴性（水、低密度），疑腹膜后及血管病变常用阴性对比剂。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0904", "gs": ""}, {"id": "U09-1102c", "t": "共用题干题", "s": "该患者上腹部扫描时，为避免呼吸运动伪影，应", "o": {"A": "深吸气后屏气扫描", "B": "自由呼吸扫描", "C": "呼气末屏气扫描", "D": "咳嗽后扫描", "E": "浅快呼吸扫描"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-108", "kp": "上腹部屏气", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】上腹部扫描需深吸气后屏气，使膈肌下移、肝脏位置固定，减少呼吸运动伪影，故A正确。\n【为什么错】B：自由呼吸产生运动伪影。C：呼气末屏气肺膨胀差、膈肌上移，不利于肝脏观察。D：咳嗽产生严重伪影。E：浅快呼吸无法固定脏器。", "tr": "屏气训练是腹部多期增强的前提，扫描前应反复练习。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0904", "gs": ""}, {"id": "U09-1103a", "t": "共用题干题", "s": "颅脑CTA确定扫描延迟时间通常采用的方法是", "o": {"A": "团注追踪（自动触发）或小剂量测试", "B": "固定延迟120秒", "C": "无需延迟，直接扫描", "D": "根据心率推算", "E": "口服对比剂后立即扫描"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-109", "kp": "CTA延迟时间确定", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】CTA常用团注追踪（在靶血管兴趣区监测CT值自动触发）或小剂量测试法确定个体化的扫描延迟时间，以保证动脉期成像，故A正确。\n【为什么错】B：固定延迟120秒为静脉期，动脉显示不佳。C：不延迟则对比剂未达颅内动脉。D：心率与循环时间无简单线性对应，不精确。E：口服对比剂不能进入动脉。", "tr": "团注追踪阈值常用100～150HU，触发后自动扫描，是CTA标准的延迟控制方式。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0905", "gs": "患者女，48岁，突发剧烈头痛伴呕吐2小时，体检示颈项强直。临床疑蛛网膜下腔出血，已行颅脑CT平扫未见明显高密度灶，临床要求进一步明确有无颅内动脉瘤，拟行颅脑CTA。"}, {"id": "U09-1103b", "t": "共用题干题", "s": "CTA原始数据后处理中，最能立体直观显示动脉瘤形态的显示方法是", "o": {"A": "容积再现（VR）", "B": "最大密度投影（MIP）", "C": "曲面重建（CPR）", "D": "多平面重建（MPR）", "E": "仿真内镜（CTVE）"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-110", "kp": "CTA三维显示", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】VR容积再现将全部容积数据进行立体重建，可直观显示动脉瘤形态、与载瘤动脉关系，是CTA最直观的三维显示方法，故A正确。\n【为什么错】B：MIP是最大密度投影，重叠结构多，空间关系显示不如VR。C：CPR适合迂曲血管拉直显示，立体感差。D：MPR为二维多平面。E：CTVE用于腔内观察。", "tr": "VR立体直观、MIP密度直观，二者常联合应用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0905", "gs": ""}, {"id": "U09-1104a", "t": "共用题干题", "s": "为鉴别尿酸结石与含钙结石，应选择的检查方法是", "o": {"A": "双能量CT", "B": "常规平扫", "C": "增强扫描", "D": "CT灌注", "E": "HRCT"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-111", "kp": "双能量CT结石分析", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT通过物质分离可鉴别尿酸结石与含钙结石，对治疗选择（药物溶石 vs 碎石）有重要价值，故A正确。\n【为什么错】B：常规平扫只能显示结石位置，不能区分成分。C：增强不用于结石成分分析。D：灌注与结石成分无关。E：HRCT用于精细结构，非成分分析。", "tr": "尿酸结石在双能量CT上可识别，此患者有痛风史，尿酸结石可能性大。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0906", "gs": "患者男，40岁，突发左侧腰部绞痛伴血尿半天，临床疑泌尿系结石，既往有痛风病史，血尿酸升高。拟行CT检查明确结石并评估结石成分。"}, {"id": "U09-1104b", "t": "共用题干题", "s": "若该患者为尿酸结石，在CT平扫上通常表现为", "o": {"A": "高密度", "B": "等密度（相对软组织）", "C": "极低密度（近水或更低）", "D": "钙化样极高密度", "E": "脂肪密度"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-112", "kp": "尿酸结石密度", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】尿酸结石密度较低，CT值约300～500HU，相对于含钙结石（>800HU甚至更高）表现为较低密度，部分接近软组织或水密度，故C正确。\n【为什么错】A、D：高密度/钙化样极高密度为含钙结石特征。B：等密度描述不准确，尿酸结石密度低于软组织。E：脂肪密度不会出现在结石。", "tr": "含钙结石CT值高（可>1000HU），尿酸结石CT值低（约300～500HU），双能量CT可更准确区分。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0906", "gs": ""}, {"id": "U09-1105a", "t": "共用题干题", "s": "CT导向肺穿刺活检前，必须评估的患者条件是", "o": {"A": "凝血功能（血小板计数、凝血时间）", "B": "血型", "C": "骨密度", "D": "听力", "E": "视力"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-113", "kp": "肺穿刺前评估", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】肺穿刺前必须评估凝血功能（血小板、凝血时间、凝血酶原时间等），凝血功能障碍是穿刺禁忌证，故A正确。\n【为什么错】B：血型对穿刺活检不是必需评估项。C：骨密度与穿刺无关。D、E：听力、视力与穿刺禁忌无关。", "tr": "严重出血倾向、血小板<50×10⁹/L为肺穿刺相对禁忌，术前必须排查。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0907", "gs": "患者男，67岁，胸部CT发现右肺下叶一枚2.5cm分叶状肿块，边缘毛刺，行纤支镜及痰细胞学检查未确诊，临床拟行CT导向经皮肺穿刺活检明确病理。"}, {"id": "U09-1105b", "t": "共用题干题", "s": "穿刺过程中为减少损伤和并发症，进针时嘱患者", "o": {"A": "屏气或平静呼吸配合进针", "B": "深呼吸快速喘气", "C": "持续咳嗽", "D": "大声说话", "E": "随意活动"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-114", "kp": "肺穿刺配合", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】肺穿刺时嘱患者屏气或平静呼吸，使病灶位置相对固定，避免呼吸运动导致穿刺针偏移及损伤，故A正确。\n【为什么错】B：快速喘气使肺上下移动，易损伤肺组织。C：咳嗽产生剧烈运动。D、E：说话和活动均会使体位改变。", "tr": "肺穿刺常见并发症为气胸和出血，呼吸配合是减少并发症的重要环节。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0907", "gs": ""}, {"id": "U09-1106a", "t": "共用题干题", "s": "该患者检查前空腹要求一般为", "o": {"A": "禁食4～6小时", "B": "禁食24小时", "C": "禁食2小时", "D": "无需禁食", "E": "禁食12小时以上"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-115", "kp": "腹部检查空腹要求", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】腹部CT检查常规要求禁食4～6小时，以减少胃肠道内容物干扰、便于口服对比剂充盈，故A正确。\n【为什么错】B：禁食24小时过长，影响患者耐受。C：2小时过短，胃内食物未排空。D：不空腹影响图像质量。E：12小时以上无必要。", "tr": "上腹部CT禁食4～6小时，同时要训练屏气，双重要求都要落实。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0908", "gs": "患者男，50岁，上腹隐痛伴消瘦1个月，体检无明显阳性体征。临床申请上腹部CT平扫加增强扫描，评估有无胰腺、肝脏占位性病变。"}, {"id": "U09-1106b", "t": "共用题干题", "s": "为排除胰腺病变，胰腺CT扫描宜采用的层厚和时相是", "o": {"A": "薄层扫描＋增强动脉期和实质期", "B": "厚层扫描平扫即可", "C": "只做平扫", "D": "薄层扫描但只做平扫", "E": "厚层扫描＋增强门脉期即可"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-116", "kp": "胰腺CT扫描方案", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】胰腺病变CT应薄层扫描并增强多期（动脉期约25～30s显示胰腺实质强化，实质期约40～45s，门脉期显示周围血管），故A正确。\n【为什么错】B：厚层扫描遗漏细小病灶。C、D：平扫不能显示胰腺肿瘤的强化特征。E：仅门脉期会遗漏动脉期强化征象。", "tr": "胰腺双期增强（动脉期+实质期）是胰腺肿瘤CT检查的规范方案。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0908", "gs": ""}, {"id": "U09-1106c", "t": "共用题干题", "s": "上腹部增强扫描中，对比剂的注射方式通常是", "o": {"A": "高压注射器快速团注", "B": "缓慢滴注", "C": "口服", "D": "皮下注射", "E": "肌肉注射"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-117", "kp": "增强对比剂注射方式", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】CT增强扫描必须用高压注射器将对比剂快速团注（一般2.5～4ml/s），以保证各期相强化效果，故A正确。\n【为什么错】B：缓慢滴注无法形成团注，各期相不清晰。C：口服对比剂只充盈胃肠道。D、E：皮下、肌肉注射对比剂不能进入血循环成像。", "tr": "团注（bolus）是增强和CTA的核心，流速不足会导致强化不充分。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0908", "gs": ""}, {"id": "U09-1107a", "t": "共用题干题", "s": "腰椎间盘CT扫描，为准确显示椎间盘，扫描层面应", "o": {"A": "平行于椎间隙", "B": "垂直于椎间隙", "C": "与椎体长轴垂直即可", "D": "任意方向", "E": "平行于床面即可"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-118", "kp": "椎间盘扫描定位", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】腰椎间盘CT扫描时，层面应平行于椎间隙（通过侧位定位像确定，必要时倾斜机架或重建），才能准确显示椎间盘形态与突出方向，故A正确。\n【为什么错】B：垂直于椎间隙为矢状位的概念。C：与椎体长轴垂直可平行椎体但不是椎间盘。D：任意方向会产生倾斜伪影。E：平行床面与椎间隙方向不一致（腰椎有生理前凸）。", "tr": "腰椎生理前凸使椎间隙倾斜，需在定位像上逐层对准椎间隙扫描。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0, "gid": "G0909", "gs": "患者男，38岁，长期弯腰劳作，近1个月腰痛伴右下肢放射性疼痛、麻木，查体示直腿抬高试验阳性。临床疑腰椎间盘突出，拟行腰椎CT检查。"}, {"id": "U09-1107b", "t": "共用题干题", "s": "该患者椎间盘扫描的层厚一般为", "o": {"A": "1～2mm", "B": "5mm", "C": "10mm", "D": "15mm", "E": "20mm"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-119", "kp": "椎间盘扫描层厚", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】椎间盘厚度仅数毫米，需薄层扫描（1～2mm）才能清楚显示椎间盘与椎管关系，故A正确。\n【为什么错】B、C、D、E：5～20mm层厚过厚，无法精细显示椎间盘突出与硬膜囊受压情况。", "tr": "椎体扫描可用3～5mm，椎间盘必须薄层（1～2mm），两者层厚不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "模拟", "mk": 0, "gid": "G0909", "gs": ""}, {"id": "U09-1108", "t": "案例分析题", "s": "患者男，56岁，既往高血压病史5年。1小时前突发右侧肢体无力、言语不清，伴轻度头痛，无恶心呕吐。急诊查体：神志清，右侧肢体肌力Ⅲ级，右侧巴氏征（＋），血压160/95mmHg。临床拟诊急性脑梗死或脑出血，申请急诊头颅CT检查，需要快速鉴别诊断并为后续治疗提供依据。关于该患者头颅CT检查方案，下列做法最恰当的是", "o": {"A": "行头颅CT平扫，扫描基线为听眦线（OML）", "B": "直接行头颅增强扫描", "C": "直接行头颅CTA", "D": "直接行CT灌注扫描", "E": "行头颅MRI检查代替CT"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-120", "kp": "急性脑卒中CT平扫", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】急性脑卒中需快速鉴别出血与缺血，头颅CT平扫是首选检查，可立即显示急性出血（高密度），扫描基线为听眦线（OML），故A正确。\n【为什么错】B：增强扫描对急性出血与缺血鉴别无优势，且延误时间。C：CTA用于血管病变评估，不是急性卒中首选鉴别手段。D：灌注在平扫排除出血后才考虑。E：MRI检查时间长，急性期不适用。", "tr": "急性脑卒中的检查流程：先CT平扫排除出血，再决定是否溶栓或进一步灌注/CTA。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1109", "t": "案例分析题", "s": "患者男，63岁，突发右侧肢体偏瘫伴失语3小时入院，头颅CT平扫未见明显高密度灶，疑急性缺血性脑卒中。临床拟评估梗死核心与缺血半暗带，以决定是否进行溶栓治疗。关于该患者进一步CT检查方法的选择，最合适的是", "o": {"A": "CT灌注成像（同层动态扫描）评估CBF、CBV、MTT", "B": "CT增强扫描观察强化灶", "C": "头颅HRCT", "D": "双能量去骨扫描", "E": "头颅平扫复查一次即可"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-121", "kp": "缺血半暗带灌注评估", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】急性缺血性脑卒中需CT灌注评估梗死核心（CBF、CBV均下降）与缺血半暗带（CBF下降、CBV正常或升高、MTT延长），指导溶栓治疗，故A正确。\n【为什么错】B：增强扫描不提供血流动力学参数。C：HRCT用于精细结构显示，非血流评估。D：去骨用于CTA后处理。E：平扫复查不能提供灌注信息。", "tr": "半暗带可挽救是溶栓的依据；灌注参数中MTT延长＋CBF下降提示缺血。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1110", "t": "案例分析题", "s": "患者女，34岁，泌乳、闭经半年，实验室检查示血泌乳素明显升高，临床疑垂体微腺瘤。影像科医师准备为其进行鞍区CT检查，以观察垂体及鞍区骨质改变。关于鞍区CT检查的扫描技术，正确的做法是", "o": {"A": "薄层扫描（1～2mm）＋冠状位扫描，必要时增强", "B": "常规10mm层厚横断面扫描", "C": "只做横断面厚层扫描", "D": "低剂量平扫即可", "E": "CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-122", "kp": "鞍区CT扫描技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】鞍区结构细小，需薄层（1～2mm）扫描，并常规行冠状位以显示垂体、鞍底及蝶窦，必要时增强观察垂体微腺瘤（低强化区），故A正确。\n【为什么错】B、C：常规厚层横断面无法显示垂体细微结构。D：低剂量平扫密度分辨力不足。E：灌注非鞍区常规检查。", "tr": "垂体微腺瘤首选MRI，CT用于显示骨质与钙化，鞍区扫描必须薄层。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1111", "t": "案例分析题", "s": "患者男，28岁，装修工人，工作时不慎铁屑崩入左眼，剧烈疼痛、畏光、流泪，临床疑眼内异物。影像科拟行眼部CT检查以明确异物位置及有无眼球穿通伤。关于该患者眼部CT检查方案，正确的是", "o": {"A": "行薄层CT扫描，横断面基线为听眶下线（IOML），并加冠状位扫描", "B": "嘱患者闭眼后做MRI检查", "C": "直接行增强扫描", "D": "行常规厚层颅脑扫描代替", "E": "CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-123", "kp": "眼部异物CT", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】眼内金属异物应行薄层CT（横断面IOML基线＋冠状位），CT能清晰显示异物位置及穿通伤，故A正确。\n【为什么错】B：金属异物禁做MRI（磁致移动损伤眼球），此为原则性错误。C：增强对异物显示无帮助。D：常规厚层颅脑扫描无法显示眼球细小异物。E：灌注与异物无关。", "tr": "金属异物MRI绝对禁忌，眼内异物检查首选CT薄层扫描。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1112", "t": "案例分析题", "s": "患者男，42岁，右耳反复流脓伴听力下降2年，近期耳内镜检查见鼓膜穿孔，临床疑中耳胆脂瘤，需了解听小骨及乳突骨质破坏情况。关于颞骨（耳部）CT检查的扫描技术，正确的是", "o": {"A": "行HRCT扫描：薄层（0.5～1mm）、骨算法重建、大窗宽骨窗显示", "B": "常规层厚软组织算法扫描", "C": "低剂量CT扫描", "D": "增强扫描即可", "E": "CT灌注成像"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-124", "kp": "颞骨HRCT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】中耳胆脂瘤需观察听小骨及骨质破坏，颞骨HRCT采用薄层（0.5～1mm）、骨算法（高空间频率）重建，并用大窗宽骨窗显示，故A正确。\n【为什么错】B：软组织算法空间分辨力不足，不能清晰显示骨迷路与听小骨。C：低剂量不能满足精细结构显示。D：增强不能显示骨质破坏。E：灌注与骨结构显示无关。", "tr": "颞骨HRCT的“骨窗”窗宽常1000～3000HU，窗位300～500HU，才能显示骨性结构。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1113", "t": "案例分析题", "s": "患者女，30岁，反复鼻塞、流脓涕、头面部胀痛2年，加重1周，临床疑慢性鼻窦炎，拟行鼻窦CT检查，重点观察窦口鼻道复合体及各组鼻窦情况。关于鼻窦CT检查的扫描技术，正确的是", "o": {"A": "行横断面＋冠状位扫描，冠状位基线垂直于硬腭", "B": "仅行横断面扫描", "C": "行CT增强扫描", "D": "行CT灌注扫描", "E": "行常规厚层颅脑扫描代替"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-125", "kp": "鼻窦CT扫描技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】鼻窦CT常规行横断面＋冠状位扫描，冠状位基线垂直于硬腭，可清晰显示窦口鼻道复合体及窦口引流情况，故A正确。\n【为什么错】B：仅横断面不能充分显示窦口鼻道复合体。C：鼻窦炎平扫即可，增强非必需。D：灌注不用于鼻窦炎。E：颅脑扫描范围与参数不适合鼻窦。", "tr": "窦口鼻道复合体是鼻窦炎CT评估的核心区域，冠状位显示最佳。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1114", "t": "案例分析题", "s": "患者男，50岁，下颌骨膨隆伴麻木3个月，口腔科检查见下颌骨体部肿物，X线片示下颌骨不规则骨质破坏，临床疑下颌骨肿瘤，拟行口腔颌面部CT检查，需要评估肿瘤范围、骨质破坏及周围软组织侵犯情况。关于该患者颌面部CT检查方案，正确的是", "o": {"A": "行薄层扫描＋骨窗与软组织窗观察，必要时三维重建（MPR、VR）", "B": "行厚层扫描即可", "C": "仅行软组织窗扫描", "D": "行CT灌注扫描", "E": "行冠脉CTA"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-126", "kp": "颌面部CT扫描", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (6)口腔颌面部", "ex": "【为什么对】颌面部肿瘤需薄层扫描，同时用骨窗显示骨质破坏、软组织窗显示软组织侵犯，并可行三维重建辅助手术规划，故A正确。\n【为什么错】B：厚层扫描遗漏细节。C：仅软组织窗不能显示骨质破坏。D：灌注非颌面部常规。E：冠脉CTA针对心脏。", "tr": "颌面部检查骨窗与软组织窗并用，是显示骨与软组织病变的基本原则。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1115", "t": "案例分析题", "s": "患者男，60岁，声音嘶哑伴吞咽不适2个月，喉镜检查见声带增生物，病理为鳞状细胞癌，临床拟行喉部CT检查以评估肿瘤范围、声门上下侵犯及颈部淋巴结转移情况。关于喉部及颈部CT检查的技术要点，正确的是", "o": {"A": "嘱患者平静呼吸避免吞咽，行颈部薄层增强扫描", "B": "嘱患者持续咳嗽后扫描", "C": "仅行喉部平扫", "D": "行厚层扫描即可", "E": "行CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-127", "kp": "喉部颈部CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】喉部检查需避免吞咽动作，颈部薄层增强扫描可评估肿瘤范围与淋巴结转移，故A正确。\n【为什么错】B：咳嗽产生严重运动伪影。C：平扫对肿瘤定性及淋巴结评估不足。D：厚层扫描遗漏细小侵犯。E：灌注非喉癌常规。", "tr": "喉癌CT增强扫描结合发长音（“咿”）可使声带张开，更好显示声带病变。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1116", "t": "案例分析题", "s": "患者女，36岁，颈部右侧触及肿块3个月，无压痛，随吞咽上下移动，甲状腺功能检查正常，超声示甲状腺右叶实性结节伴沙砾样钙化，临床疑甲状腺癌，拟行颈部CT增强扫描评估甲状腺结节及颈部淋巴结。关于该患者颈部CT扫描的技术要点，正确的是", "o": {"A": "行颈部薄层增强扫描，观察结节强化及周围结构", "B": "仅行颈部平扫", "C": "行冠脉CTA扫描", "D": "行腹部增强扫描", "E": "行CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-128", "kp": "甲状腺CT增强", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】甲状腺结节伴钙化疑癌，应行颈部薄层增强扫描，观察结节强化特征及颈部淋巴结转移情况，故A正确。\n【为什么错】B：平扫对恶性征象（如侵犯周围结构、淋巴结）显示不足。C：冠脉CTA针对心脏。D：腹部增强不针对颈部病灶。E：灌注非甲状腺常规。", "tr": "甲状腺增强扫描时注意对比剂中的碘可影响甲状腺功能，检查前应询问病史。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1117", "t": "案例分析题", "s": "患者男，58岁，进行性呼吸困难伴干咳半年，肺功能检查示限制性通气障碍，临床疑间质性肺病，申请胸部CT检查评估肺间质改变。影像科拟行高分辨力CT（HRCT）检查。关于该患者HRCT检查的技术要点，正确的是", "o": {"A": "薄层扫描（1～2mm）＋高空间频率算法重建，配合深吸气后屏气", "B": "常规10mm层厚软组织算法扫描", "C": "低剂量厚层扫描", "D": "增强扫描即可", "E": "CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-129", "kp": "肺间质病HRCT", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】间质性肺病需HRCT：薄层（1～2mm）＋高空间频率算法（骨算法），显示肺小叶间隔、网状影等细微结构，并需屏气配合，故A正确。\n【为什么错】B：常规层厚软组织算法无法显示肺间质细微改变。C：低剂量厚层空间分辨力不足。D：增强对间质改变显示无帮助。E：灌注不用于间质性肺病评估。", "tr": "HRCT是间质性肺病诊断与随访的核心手段，高空间频率算法是关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1118", "t": "案例分析题", "s": "患者男，52岁，吸烟20年，单位体检胸部低剂量CT发现右下肺一枚1.2cm实性结节，形态不规则，边缘见浅分叶及毛刺。临床拟进一步明确结节性质，考虑行靶扫描及增强扫描。关于该患者肺结节CT进一步检查的技术要点，正确的是", "o": {"A": "行靶扫描（缩小视野放大重建）提高空间分辨力，并评估增强后强化程度", "B": "直接行冠脉CTA", "C": "行CT灌注即可，不需薄层", "D": "行厚层扫描观察整体", "E": "行腹部增强扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-130", "kp": "肺结节靶扫描增强", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】肺小结节可行靶扫描（缩小视野放大重建）提高空间分辨力观察边缘特征，增强扫描评估强化程度有助于良恶性判断，故A正确。\n【为什么错】B：冠脉CTA与肺结节无关。C：灌注不能替代薄层形态学观察。D：厚层扫描有部分容积效应，掩盖细节。E：腹部增强不针对肺结节。", "tr": "肺结节增强强化值（如强化>15HU）对恶性提示有意义；靶扫描提高细节显示。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1119", "t": "案例分析题", "s": "患者男，66岁，反复活动后胸闷、胸痛1个月，心电图示心肌缺血改变，临床疑冠心病，拟行冠状动脉CTA检查。患者平时心率78次/分，偶有早搏。关于该患者冠脉CTA检查前及检查中的处理，正确的是", "o": {"A": "口服β受体阻滞剂控制心率至70次/分以下，采用心电门控扫描", "B": "不控制心率直接扫描", "C": "行非门控胸部平扫代替", "D": "行CT灌注代替CTA", "E": "行腹部增强扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-131", "kp": "冠脉CTA检查流程", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠脉CTA需将心率控制在70次/分以下（口服β受体阻滞剂），并采用心电门控扫描保证图像质量，故A正确。\n【为什么错】B：心率过快冠脉运动伪影明显，图像无法诊断。C：平扫不能显示冠脉腔。D：灌注不显示冠脉解剖。E：腹部增强与冠脉无关。", "tr": "冠脉CTA成功率取决于心率控制、屏气配合和心电门控三要素。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1120", "t": "案例分析题", "s": "患者女，49岁，体检超声发现肝右叶低回声结节2.0cm，边缘尚清，甲胎蛋白轻度升高，有乙型肝炎病史。临床拟行肝脏增强CT多期扫描，明确病灶性质并评估血供。关于肝脏三期增强CT的扫描时相设置，正确的是", "o": {"A": "动脉期25～30秒、门静脉期60～70秒、平衡期120～180秒扫描", "B": "仅扫描动脉期即可", "C": "各期均固定在180秒扫描", "D": "各期均在10秒内扫描", "E": "只做平扫即可定性"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-132", "kp": "肝脏三期增强时相", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肝脏增强CT常规设动脉期（25～30s）、门静脉期（60～70s）、平衡期（120～180s），动态观察病灶强化方式，故A正确。\n【为什么错】B：仅动脉期不能观察门脉期与延迟期廓清情况。C：各期180秒固定无法捕捉动脉期高强化。D：10秒内各期尚未到达。E：平扫不能显示强化特征。", "tr": "肝癌“快进快出”与血管瘤“慢进慢出”的鉴别依赖多期动态扫描。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1121", "t": "案例分析题", "s": "患者男，47岁，反复腹痛伴腰背部疼痛2个月，CT平扫发现胰体尾部肿块，与脾动脉关系密切，临床疑胰腺癌，需行胰腺增强CT评估肿瘤分期及血管侵犯情况。关于该患者胰腺CT扫描的技术要点，正确的是", "o": {"A": "薄层扫描＋增强动脉期、实质期多期扫描", "B": "厚层平扫即可", "C": "仅行门静脉期扫描", "D": "行低剂量厚层扫描", "E": "行CT灌注扫描代替增强"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-133", "kp": "胰腺癌CT扫描", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】胰腺癌评估需薄层扫描＋增强多期（动脉期显示肿瘤与动脉关系、实质期显示胰周浸润），评估血管侵犯与分期，故A正确。\n【为什么错】B：厚层平扫无法显示肿瘤血供与血管侵犯。C：仅门脉期会遗漏动脉期信息。D：低剂量厚层不能满足胰腺精细评估。E：灌注不能替代增强多期解剖成像。", "tr": "胰腺双期增强（动脉期＋实质期）可提高胰腺癌检出率，薄层扫描不可省略。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1122", "t": "案例分析题", "s": "患者男，50岁，无痛性肉眼血尿1周，超声发现左肾上极实性占位，临床疑肾细胞癌，拟行肾脏增强CT检查，评估肿瘤范围及有无肾静脉、下腔静脉癌栓。关于该患者肾脏CT增强扫描的期相设置，正确的是", "o": {"A": "皮质期25～30秒、实质期60～70秒、排泄期180秒及以后扫描", "B": "仅扫描排泄期即可", "C": "仅扫描动脉期即可", "D": "各期均在10秒内完成", "E": "只做平扫即可"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-134", "kp": "肾脏增强期相", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肾癌CT增强常规皮质期（25～30s）、实质期（60～70s）评估肿瘤血供，排泄期（约180s后）观察肾盂及静脉癌栓情况，故A正确。\n【为什么错】B：仅排泄期无法显示皮质期富血供强化。C：仅动脉期无法显示肾实质期。D：10秒内无法完成各期相。E：平扫无法显示血供特征。", "tr": "肾癌“快进快出”、皮质期强化明显；排泄期显示肾静脉癌栓有价值。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1123", "t": "案例分析题", "s": "患者女，55岁，下腹坠胀伴月经量增多半年，妇科检查示子宫增大，超声疑子宫肌瘤，临床拟行盆腔CT增强扫描评估子宫及附件情况。影像科技师需正确完成盆腔CT检查的准备工作。关于盆腔CT检查前的准备，正确的是", "o": {"A": "充盈膀胱，口服对比剂充盈肠道，必要时阴道填塞标记", "B": "排空膀胱即可扫描", "C": "禁食24小时以上", "D": "无需任何准备", "E": "行CT灌注扫描代替增强"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-135", "kp": "盆腔CT准备", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】盆腔CT检查前应充盈膀胱、口服对比剂充盈肠道，女性必要时阴道填塞标记物，以清晰显示盆腔器官，故A正确。\n【为什么错】B：排空膀胱后膀胱显示不清，周围结构分辨差。C：禁食24小时过长且无必要。D：盆腔检查有明确准备要求。E：灌注不替代增强解剖成像。", "tr": "盆腔CT“憋尿”是经典准备要求，与腹部“禁食”不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1124", "t": "案例分析题", "s": "患者男，35岁，高处坠落致腰部疼痛、活动受限，疑腰椎压缩性骨折，X线片示L1椎体楔形变。临床拟行腰椎CT检查，进一步明确骨折情况、椎管受累及椎间盘情况。关于该患者腰椎CT扫描的技术要点，正确的是", "o": {"A": "椎体骨折用常规层厚骨窗观察，椎间盘用薄层扫描并矢状位重建", "B": "全程厚层20mm扫描", "C": "仅行软组织窗扫描", "D": "行CT灌注扫描", "E": "行冠脉CTA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-136", "kp": "腰椎骨折CT", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】腰椎骨折CT椎体部分用骨窗观察骨折线，椎间盘及椎管用薄层扫描并矢状位重建评估椎管狭窄，故A正确。\n【为什么错】B：厚层20mm无法显示细小骨折线。C：软组织窗不能显示骨皮质断裂。D：灌注与骨折无关。E：冠脉CTA针对心脏。", "tr": "脊柱骨折CT检查骨窗为主，矢状位重建对骨折及椎管评估非常重要。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1125", "t": "案例分析题", "s": "患者男，26岁，运动扭伤右膝关节，关节肿胀疼痛、活动受限，临床疑膝关节韧带及半月板损伤，申请右膝关节CT检查评估骨性结构与关节对位情况。关于该患者膝关节CT检查的技术要点，正确的是", "o": {"A": "行双侧对照扫描，骨窗＋软组织窗观察，必要时三维重建", "B": "仅扫描患侧单层面", "C": "行厚层扫描", "D": "行增强扫描", "E": "行CT灌注扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-137", "kp": "膝关节CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】四肢关节CT应双侧对照扫描、薄层扫描，并用骨窗观察骨质、软组织窗观察软组织，必要时三维重建辅助诊断，故A正确。\n【为什么错】B：单层面扫描不能全面评估。C：厚层扫描遗漏细小骨折。D：增强对骨关节损伤无帮助。E：灌注与关节损伤无关。", "tr": "膝关节韧带、半月板损伤首选MRI，CT用于评估骨性结构与骨折。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1126", "t": "案例分析题", "s": "患者男，32岁，右踝关节扭伤后肿痛3天，X线片未见明确骨折线，但局部压痛明显，临床疑隐匿性骨折，拟行踝关节CT薄层扫描进一步明确。关于该患者CT扫描参数的选择，正确的是", "o": {"A": "薄层扫描＋骨算法重建，骨窗观察，必要时多平面重建", "B": "厚层软组织窗扫描", "C": "低剂量厚层扫描", "D": "增强扫描", "E": "CT灌注扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-138", "kp": "隐匿性骨折CT", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】隐匿性骨折需薄层扫描＋骨算法（高空间频率）重建，骨窗观察细微骨折线，并可行多平面重建，故A正确。\n【为什么错】B：厚层软组织窗无法显示细微骨折线。C：低剂量厚层空间分辨力不足。D：增强对骨折无帮助。E：灌注与骨折无关。", "tr": "隐匿性骨折（如舟骨骨折、胫骨平台骨折）薄层CT＋骨窗＋MPR是标准方案。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-1127", "t": "案例分析题", "s": "患者男，62岁，突发胸背部撕裂样疼痛2小时，血压200/120mmHg，临床高度怀疑主动脉夹层，需急诊行主动脉CTA检查明确诊断及分型。关于该患者主动脉CTA检查的技术要点，正确的是", "o": {"A": "行全主动脉CTA扫描，采用团注追踪确定延迟，必要时心电门控", "B": "行胸部平扫即可", "C": "行腹部增强扫描", "D": "行冠脉CTA即可", "E": "行CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-139", "kp": "主动脉CTA", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】主动脉夹层需全主动脉CTA（升主动脉至髂动脉），用团注追踪确定延迟，评估内膜片、真假腔及分支受累，累及升主动脉时可配合心电门控减少运动伪影，故A正确。\n【为什么错】B：平扫不能显示内膜片与假腔血流。C：仅腹部增强遗漏胸主动脉。D：冠脉CTA范围仅心脏冠脉。E：灌注不能评估夹层形态。", "tr": "主动脉CTA要覆盖全主动脉并显示内膜片，Stanford分型依赖升主动脉是否受累。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-1128", "t": "案例分析题", "s": "患者男，58岁，间歇性胸痛1个月，冠脉CTA检查发现左前降支中段混合性斑块伴中度狭窄，为进一步评估斑块性质及有无心肌缺血，临床医师拟行CT灌注成像评估心肌灌注情况。关于心肌CT灌注成像的叙述，正确的是", "o": {"A": "在静息与负荷（腺苷等）状态下分别扫描，比较心肌血流的差异", "B": "仅做一次静息扫描即可", "C": "用口服对比剂即可完成灌注", "D": "与冠脉CTA完全无关，可单独进行", "E": "灌注参数与心电编辑无关"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-140", "kp": "心肌CT灌注", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】心肌CT灌注成像需静息与负荷（腺苷、双嘧达莫等药物负荷）两次扫描，比较负荷与静息心肌血流灌注的差异，评估有无缺血，故A正确。\n【为什么错】B：单次静息扫描无法评估负荷诱导的缺血。C：口服对比剂不能进入冠脉循环。D：心肌灌注常与冠脉CTA联合，评估解剖与功能。E：心脏检查同样受心律影响，需心电门控与心电编辑配合。", "tr": "心肌灌注的“负荷-静息”对比是发现可诱导心肌缺血的关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U09-9201", "t": "单选题", "s": "颅脑 CT 平扫常规采用的层面方式是", "o": {"A": "冠状位", "B": "矢状位", "C": "横断面（轴位）", "D": "斜位", "E": "三维容积直接成像"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-9201", "kp": "颅脑CT体位", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术", "ex": "【为什么对】颅脑 CT 平扫常规取仰卧位横断面（轴位）扫描。\n【为什么错】冠状/矢状多为重组或特殊需要。", "tr": "颅脑CT常规轴位扫描。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U09-9202", "t": "单选题", "s": "腹部 CT 增强扫描常用的期相不包括", "o": {"A": "动脉期", "B": "静脉期（门脉期）", "C": "延迟期", "D": "平衡期", "E": "分泌期"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-9202", "kp": "腹部CT期相", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术", "ex": "【为什么对】腹部增强常用动脉期、门脉期、延迟/平衡期；\"分泌期\"为尿路造影（如CTU）概念，非常规腹盆增强期相。\n【为什么错】动脉/门脉/延迟均为常规期相。", "tr": "腹盆增强期相无\"分泌期\"（CTU除外）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0101", "t": "单选题", "s": "按照通行的MR安全分区管理（Zone I—Zone IV）原则，扫描室（磁体所在房间）本身应界定为", "o": {"A": "Zone I（公众自由出入区）", "B": "Zone II（问诊、更衣、病史与金属筛查区）", "C": "Zone III（受门禁控制、非MR人员须陪同的缓冲区，含操作台）", "D": "Zone IV（磁体间，须有醒目标识与磁场警示灯，任何时刻不得无陪同进入）", "E": "视磁体是否处于扫描状态在Zone III与Zone IV间动态切换"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-001", "kp": "MR安全分区（Zone I—IV）", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】D正确。Zone IV即磁体间本身，是主磁场最强、投射效应风险最高的区域，门外须设醒目警示标识与磁场指示灯（通常为红色警示灯），任何人员进入均须经筛查并由MR授权人员全程陪同；Zone IV在物理上应完全位于Zone III之内。【为什么错】A Zone I是磁场影响之外、公众可自由出入的区域（如门诊走廊、候诊大厅）。B Zone II是Zone I与Zone III之间的过渡区，用于问诊、填写安全筛查表、更衣与去除金属物，患者在此仍属“未筛查”状态但风险可控。C Zone III是受门禁（刷卡/密码/专人）控制的缓冲区，操作台通常设在此处，非MR人员未经陪同不得进入，但它不等同于磁体间。E错误——超导磁体的主磁场是持续存在的（除非失超），分区界定是固定的物理管理边界，不随是否扫描而变化。", "tr": "最常见的混淆是把“操作间”当成Zone IV。记忆口诀：Ⅰ公众—Ⅱ筛查—Ⅲ门禁（含操作台）—Ⅳ磁体间。另一个陷阱是误以为“不扫描时磁场关闭”，超导磁体7×24h带场。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0102", "t": "多选题", "s": "某院MR机房进行安全整改，下列做法中符合MR安全分区与铁磁性物品筛查规范的有", "o": {"A": "Zone III入口设置门禁，钥匙/权限仅授予经过培训的MR工作人员，非MR人员须有陪同方可进入", "B": "在Zone II设置金属探测门或手持铁磁探测仪，对患者与陪同者进行二次筛查，并要求更换无金属检查服", "C": "抢救车、氧气钢瓶、轮椅、输液泵等设备一律停放在Zone III以外，进入Zone IV须换用标注MR Safe或MR Conditional的专用设备", "D": "5高斯（0.5 mT）等磁力线原则上应被限制在Zone IV范围内；若超出，则超出部分必须纳入门禁管制范围", "E": "危急抢救时为争取时间，可由医师口头授权将普通金属推床直接推入Zone IV完成转运"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-002", "kp": "MR安全分区管理与铁磁性物品筛查", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确：Zone III的核心特征就是物理门禁与授权管理。B正确：铁磁筛查应分层进行（问卷—人工核查—探测设备），普通金属探测门对非铁磁金属也报警，专用铁磁探测仪特异性更好，二者互补。C正确：Zone IV内只允许MR Safe（全程安全）或经确认条件的MR Conditional设备；钢制氧气瓶是文献报道致死事故的经典元凶。D正确：5高斯线是心脏起搏器等植入物携带者的安全边界，规范要求其被限制在受控区域内。【为什么错】E错误：抢救时的正确流程是“把患者移出Zone IV再抢救”，而不是“把抢救设备推进Zone IV”。磁体孔口附近空间梯度最大，铁磁性推床会以极高速度被吸入，造成致命投射事故。急救的标准动作是立即将患者转移至Zone IV外的复苏区，失超只有在人被吸附压迫、无法解救时才考虑。", "tr": "E是最危险的临床错觉——“救命要紧”不能凌驾于磁体安全。牢记：救人靠“把人移出去”，不是“把设备推进来”；失超（quench）不是常规解困手段，其本身有窒息与冻伤风险。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0103", "t": "单选题", "s": "患者男，72岁，因腰痛拟行腰椎MRI。随身携带的心脏起搏器条件卡显示：MR Conditional，适用静磁场1.5T，正常运行模式，全身SAR≤2.0 W/kg，梯度切换率≤200 T/m/s，扫描区域不限。本科室仅有一台飞利浦3.0T设备。技师最恰当的处置是", "o": {"A": "既然标注为MR Conditional，可在3.0T按常规参数扫描", "B": "在3.0T上把序列改为低SAR模式（SAR<2.0 W/kg）并降低梯度切换率后即可扫描", "C": "条件卡限定为1.5T，超出标定场强即失去条件安全依据，本机不可扫描；应联系心内科程控后转至1.5T设备按条件卡逐条执行", "D": "请心内科将起搏器程控为关闭状态，即可在3.0T安全扫描", "E": "改用发射/接收头线圈局部发射，即可在3.0T安全扫描腰椎"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-003", "kp": "MR Conditional植入物的条件核对", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】C正确。MR Conditional（磁共振条件安全）的含义是“仅在标签规定的全部条件同时满足时才安全”，这些条件通常包括静磁场强度、空间梯度场上限、梯度切换率、SAR或B1+rms上限、扫描部位、扫描时长等。任何一条不满足，该器械在此环境下即等同于不安全。条件卡明确写1.5T，3.0T下的射频波长效应、导线天线效应与发热风险完全不同，不能通过“调低参数”外推。正确路径是转诊至符合条件的1.5T设备，并由心内科在扫描前后程控（改为MRI模式/非同步或关闭感知）、全程心电血氧监护、备除颤仪。【为什么错】A把MR Conditional当成MR Safe，是最常见的致命误解。B错误：场强本身不可调，SAR达标并不能弥补场强超标；且3.0T导线共振长度与1.5T不同。D错误：关闭起搏功能对起搏依赖患者反而致命，且不能解决场强超标问题。E错误：腰椎扫描无法用头线圈发射，而且局部发射线圈也不改变静磁场超标的事实。", "tr": "把MR Safe（无条件安全，如塑料）与MR Conditional（条件安全）混为一谈是最大陷阱。ASTM F2503标识：MR Safe为绿色方块内白色“MR”；MR Conditional为黄色三角内黑色“MR”；MR Unsafe为红色圆圈加斜杠内黑色“MR”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0104", "t": "多选题", "s": "关于颅内动脉瘤夹患者的MRI安全评估，下列判断正确的有", "o": {"A": "钛及钛合金动脉瘤夹为非铁磁性材料，在核实型号、批次与厂家标注后可按条件扫描", "B": "早期（约1995年之前）使用的部分不锈钢（如马氏体不锈钢）动脉瘤夹具有铁磁性，可发生移位与扭矩，属绝对禁忌", "C": "凡病历中无法查证夹子型号、材质与手术记录者，一律按“不可扫描”处理，改行CTA评估", "D": "铁磁性夹子在磁体内受到的平移力主要取决于静磁场的空间梯度而非中心场强，因此磁体孔口处风险最高", "E": "动脉瘤夹只要术后满6个月，周围已形成纤维包裹固定，无论材质均可安全扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-004", "kp": "动脉瘤夹材质判定与铁磁力学", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】A正确：钛/钛合金及部分钴基合金（如Phynox、Elgiloy）属非铁磁或弱铁磁，经厂家标注核实后可按条件扫描。B正确：早期马氏体不锈钢夹具有明显铁磁性，磁场中受扭矩可致夹子旋转、血管撕裂出血，历史上有致死报道，属绝对禁忌。C正确：MR安全遵循“不能证明安全即视为不安全”的原则，材质不可考时应改用CTA/DSA。D正确：铁磁性物体所受平移力F∝M·dB/dz，取决于场强与空间梯度的乘积，空间梯度在磁体孔口（bore入口）附近最大，因此“孔口”而非“磁体中心”是投射力最强处；而扭矩才主要与中心场强有关。【为什么错】E错误：“时间够久就安全”是没有依据的推断。纤维包裹产生的固定力远小于强磁场对铁磁性夹产生的扭矩，材质才是决定因素，时间不能改变材质的磁化率。", "tr": "D是高阶考点：吸引（投射）力取决于B·dB/dz，最大处在孔口而非等中心；扭矩最大处在等中心（场强最高）。很多考生误认为“越靠近中心越危险”。E的“时间安全论”是经典陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U10-0105", "t": "单选题", "s": "关于人工耳蜗（cochlear implant）植入者的MRI检查，下列说法正确的是", "o": {"A": "人工耳蜗一律为MR Safe，可常规扫描", "B": "多数人工耳蜗内含永磁体，属MR Unsafe或需在满足条件（外科取出内置磁体、或使用专用加压绷带固定并限定场强）时方可扫描，且颞部会遗留大范围磁敏感伪影", "C": "人工耳蜗的风险仅为伪影，不存在移位或去磁风险", "D": "只要取下体外言语处理器，植入体即无任何风险", "E": "人工耳蜗患者可行3.0T扫描但禁行1.5T扫描"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-005", "kp": "人工耳蜗与MRI安全", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】B正确。绝大多数现代人工耳蜗植入体内置一枚用于体外处理器磁吸定位的永磁体。强磁场中可导致：磁体移位/翻转、退磁（去磁后体外机无法吸附）、局部疼痛与皮瓣损伤。因此多数产品标注为MR Unsafe，或为MR Conditional但附加严格条件（限定1.5T、外科小切口取出磁体后扫描、或使用厂家指定的加压绷带固定头部并限制扫描时长）。即便允许扫描，植入侧颞部、后颅窝将出现大范围磁敏感伪影，内耳与桥小脑角结构常无法评估。【为什么错】A错误：与实际标注相反。C错误：磁体移位与退磁是真实且常见的不良事件，不只是伪影问题。D错误：取下体外机是必要步骤，但风险来自植入体内的磁体，不是体外机。E错误：条件通常限定为1.5T，3.0T多不被允许，选项方向说反。", "tr": "考生常把“取下体外机”当成充分条件。要点在于“体内有没有磁体”。同类考点还有：可植入式骨传导助听器、磁性眼睑重物、组织扩张器（含金属注射壶）——凡“内置磁体”者都要高度警惕。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0106", "t": "多选题", "s": "关于植入式神经刺激器（脑深部电刺激DBS、脊髓电刺激SCS、迷走神经刺激VNS）患者的MRI，下列处理原则正确的有", "o": {"A": "必须逐条核对厂家的MR条件说明，包括场强、发射线圈类型、扫描部位、头部/全身SAR或B1+rms上限、扫描时长", "B": "许多DBS产品要求使用发射/接收头线圈或严格限制头部SAR（部分产品要求头部SAR≤0.1 W/kg），并要求扫描前由程控医师将设备设为MRI模式、刺激电压归零", "C": "导线断裂、导线残留（电极已取出但导线未取）或导线走行成环者风险显著升高，因为导线可作为射频天线在尖端产生局部高热", "D": "此类患者禁行任何梯度回波序列，只能采集自旋回波类序列", "E": "只要把刺激器关机，任何场强、任何序列均可安全使用"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-006", "kp": "神经刺激器植入者MRI条件管理", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】A正确：条件安全器械的安全性由标签定义的全部条件共同保证，缺一不可。B正确：DBS的主要风险是电极尖端射频致热（可造成不可逆脑损伤），故厂家常要求限制头部射频功率沉积、指定发射线圈，并要求把刺激参数程控至安全设置。C正确：长导线在射频场中形成谐振天线，尖端电场集中而产热；断裂端、残留导线与成环走行都会加剧这一效应，这也是“导线不得成环”这条通用规则的物理基础。【为什么错】D错误：限制的核心是射频功率沉积（SAR/B1+rms），与序列是GRE还是SE无必然对应关系；实际上高SAR的往往是TSE类的大角度重聚焦序列，而低翻转角GRE的SAR反而更低。把限制误读为“禁GRE”是概念错位。E错误：关机不改变导线的天线特性，也不改变场强与梯度条件；“关机即安全”是危险的想当然。", "tr": "D是精心设计的干扰项——很多考生只记住“梯度回波对金属敏感、伪影大”，就把伪影问题误当成安全问题。安全的关键变量是SAR/B1+rms与导线几何，不是序列家族。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0107", "t": "单选题", "s": "患者男，46岁，金属打磨工人，因头痛申请头颅MRI。安全问卷中自述“约5年前打磨时有异物崩入右眼，冲洗后未就诊，无明显不适”。技师最恰当的处置是", "o": {"A": "既往无症状说明异物已排出，可直接扫描", "B": "先行眼眶X线平片（或眼眶薄层CT）排除眼内金属异物，阴性后方可扫描", "C": "用手持磁铁在眼周试探有无吸引感以判断", "D": "改用0.35T低场开放式设备直接扫描即可规避风险", "E": "让患者签署风险自负知情同意书后按常规扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-007", "kp": "眼内金属异物筛查流程", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】B正确。有金属加工、车工、焊工职业史或明确眼部金属外伤史而未经处理者，属于眼内金属异物高危人群。眼内铁磁性碎屑在强磁场中可发生移位，损伤视网膜、晶状体、玻璃体乃至造成失明，属于绝对禁忌。规范流程是扫描前用眼眶X线平片（通常两个体位）或眼眶薄层CT（对小碎屑更敏感）进行排查，阴性方可扫描。【为什么错】A错误：无症状不能排除异物存留，微小金属屑可长期无症状嵌顿于眼球壁。C错误：用磁铁在眼周试探本身就可能诱发异物移位，是被严格禁止的危险操作。D错误：低场并不等于无风险，且0.35T仍可对铁磁性异物产生足够的位移力；更重要的是这属于用降级方案回避筛查责任。E错误：知情同意不能替代客观筛查，绝对禁忌证不因签字而变为可行。", "tr": "本题的陷阱在E——“签了字就能做”。绝对禁忌证与知情同意是两个层面的问题，签字不构成免责，更不改变物理风险。另注意：眼眶CT敏感性高于平片，但平片作为初筛价格低、可及性好，两者均可接受。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0108", "t": "多选题", "s": "关于妊娠期与哺乳期妇女的MRI检查，下列说法正确的有", "o": {"A": "MRI不使用电离辐射，妊娠期并非绝对禁忌；但妊娠早期（前3个月）在无明确临床必要时不建议施行", "B": "钆对比剂可通过胎盘进入胎儿循环并经胎儿肾脏排入羊水形成再循环，妊娠期原则上应避免使用，除非获益明显大于风险", "C": "妊娠期扫描应尽量降低SAR（如选择正常运行模式、减少大翻转角TSE的连续采集），并注意噪声对胎儿的影响，控制扫描时长", "D": "哺乳期妇女使用大环状钆剂后，因经乳汁分泌量极少（约为注射剂量的万分之一以下），一般不需要中断哺乳", "E": "妊娠期为保护胎儿，MRI必须常规使用镇静剂使孕妇保持绝对静止"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-008", "kp": "妊娠与哺乳期MRI安全", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】A正确：MRI无电离辐射，1.5T/3.0T平扫至今无确证的致畸证据；但器官形成期证据相对有限，故遵循“非必要不做、能推迟则推迟”的谨慎原则。B正确：钆剂可穿过胎盘，胎儿排泄入羊水后可被吞咽再吸收，形成延长暴露，动物实验有致畸报道，故妊娠期原则上不用。C正确：孕期关注的三大物理因素是射频致热（SAR，胎儿散热能力差）、噪声与扫描时长，应主动优化。D正确：大环状钆剂经乳汁分泌量极微、婴儿胃肠吸收率又极低，主流指南认为无须中断哺乳；若产妇仍有顾虑，可弃奶12—24 h。【为什么错】E错误：绝大多数孕妇可清醒配合，镇静药物本身对胎儿存在风险，绝无“必须常规镇静”之说，属明显的绝对化错误表述。", "tr": "B与D方向相反但都正确，考生易被“钆剂孕期禁用”惯性带偏而误判D。要点是分清“经胎盘”（孕期，暴露持久）与“经乳汁”（哺乳期，剂量极微）两条完全不同的途径。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0109", "t": "案例分析题", "s": "患者女，58岁，脑膜瘤术后2年随访，需行头颅MRI平扫+增强。上一次在本院检查时因幽闭恐惧在扫描开始约3分钟后按压呼叫球中止，仅完成定位像与一组T2WI。本次仍诉紧张、担心“喘不上气”。设备为飞利浦3.0T，配备压缩感知加速（CS），无深度学习重建；患者一般情况好，无镇静禁忌。作为技师，最合理的整体处置方案是", "o": {"A": "先行非药物干预：充分讲解流程与时长、允许家属在Zone IV内陪同并握手、采用足先进（feet-first）体位或棱镜眼镜、加强孔内通风与照明、耳机播放音乐、明确交代呼叫球用法；同时用CS加速重排扫描方案，优先采集诊断价值最高的3D T1W增强与T2-FLAIR，把总时长压缩至10 min内；若仍不能耐受，再由麻醉科评估后行清醒镇静并全程监护SpO₂与心率", "B": "直接由技师静脉推注地西泮10 mg后开始扫描，无须麻醉科参与", "C": "用约束带牢固固定头部与躯干，强行完成全部序列", "D": "取消增强，仅做平扫，避免打针加重紧张", "E": "改用0.35T开放式设备完成平扫与增强，因低场噪声小且孔径开放，可完全替代3.0T随访"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-009", "kp": "幽闭恐惧的处理、镇静与监护", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确。幽闭恐惧的规范处置遵循“阶梯化”原则：①非药物干预优先（沟通、陪同、体位与视觉干预、通风照明、音乐、明确的中止通道）；②技术层面缩短暴露时间——压缩感知与并行采集联合可将3D序列缩短约40%—60%，把关键序列前置，即便中途中止也已获得诊断信息；③非药物失败再考虑药物镇静，且必须由具备资质的医师开具与实施，配备MR兼容监护仪（SpO₂、心率、必要时呼气末CO₂）与复苏设备。足先进体位可使头部远离孔中心侧的心理压迫感（对头颅检查需权衡定位可行性，通常用于非头部检查；对头部检查更多依赖棱镜眼镜与镜面装置）。【为什么错】B错误：技师无独立用药权限，且镇静必须有监护与复苏预案，属越权与高风险操作。C错误：强行约束会加剧惊恐发作，可能诱发过度通气甚至意外，且体动伪影仍不可控，违背患者自主权。D错误：脑膜瘤术后随访的核心信息在于增强后是否有结节样强化复发，取消增强等于放弃检查目的。E错误：0.35T的SNR、增强病灶检出敏感度与3D高分辨能力显著低于3.0T，不能等同替代随访基线；开放式设备可作为最后备选而非首选。", "tr": "陷阱在“技术手段与人文手段谁先行”。副高层面要求给出阶梯式方案而非单点措施：先优化流程与序列，再考虑药物；同时牢记技师的执业边界——不得自行给药。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0110", "t": "多选题", "s": "关于MRI检查中的听力防护，下列说法正确的有", "o": {"A": "梯度线圈在磁场中受洛伦兹力发生振动是噪声的主要来源，回波平面成像（EPI）、扩散加权与部分梯度回波序列噪声尤为突出", "B": "所有进入扫描室的受检者与陪同人员均应佩戴听力防护装置，合格耳塞可提供约25—30 dB的降噪", "C": "接受镇静或全身麻醉的患者因无法主诉不适，更应确保听力防护到位", "D": "新生儿与婴幼儿外耳道细小，常规耳塞不适配，应使用专用小号耳塞加耳罩或MR兼容降噪装置，不可省略防护", "E": "耳机播放音乐可完全替代耳塞的物理降噪作用"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-010", "kp": "MRI噪声来源与听力防护", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确：梯度电流在主磁场中产生洛伦兹力，使梯度线圈快速形变振动产生声压，梯度切换越快、幅度越大噪声越强，故EPI类序列声压级最高，3.0T常可超过110 dB(A)。B正确：这是强制性要求，陪同人员同样暴露于噪声环境。C正确：镇静/麻醉患者失去了主动求助能力，是听力损伤的高危人群，防护更不能省。D正确：婴幼儿听觉系统脆弱且不能配合，必须使用适配的专用防护，绝不能因“戴不上”而放弃。【为什么错】E错误：音乐耳机的首要作用是心理安抚与掩蔽，其被动隔声量有限且频响特性不匹配梯度噪声频谱，不能替代耳塞的物理衰减；正确做法是耳塞+耳罩/耳机联合使用。", "tr": "E是常见的现场偷懒做法。另需记住：降低噪声的技术手段还包括采用静音序列（低梯度切换率的正弦/软梯度波形）、降低带宽与梯度幅度，但代价是扫描时间延长或分辨率下降。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0111", "t": "多选题", "s": "为预防MRI检查中的射频灼伤，下列措施正确的有", "o": {"A": "用衬垫隔开大腿与大腿、小腿与小腿、上臂与躯干等皮肤接触部位，避免人体自身形成导电闭合环路", "B": "心电导联线、脉搏血氧探头导线应沿磁体长轴方向平直放置，不得盘绕成环，并与皮肤之间加隔垫", "C": "扫描前移除含金属丝的心电电极、含铝箔背衬的透皮贴剂（如某些镇痛贴、硝酸甘油贴）以及含金属纤维的功能性内衣", "D": "同一序列条件下，3.0T的射频能量沉积约为1.5T的4倍（SAR近似与B₀的平方成正比），高场下更须警惕", "E": "缩短TR、增加单位时间内的射频脉冲数量是降低SAR的有效手段"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-011", "kp": "射频灼伤机制与预防", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确：人体皮肤接触形成的闭合回路可感应涡流，接触点电流密度集中而致灼伤，这是最常见的MR灼伤原因之一。B正确：导线成环等效于线圈，感应电动势正比于环路面积；平直沿主磁场方向布线并加隔垫可显著降低风险。C正确：金属丝电极与铝箔背衬贴剂是局部电场/涡流集中点，多起灼伤事故与之相关。D正确：SAR近似正比于B₀²·α²·（脉冲数/TR），故3.0T相同序列的SAR约为1.5T的4倍，这是高场必须重排序列参数的物理依据。【为什么错】E错误：完全说反。SAR正比于单位时间内沉积的射频能量，缩短TR意味着同样多的射频脉冲在更短时间内发放，SAR升高；降低SAR应延长TR、减少层数、降低重聚焦翻转角（可变翻转角VFL）、缩短回波链或改用低SAR的GRE类序列。", "tr": "E的迷惑点在于“缩短扫描时间=更安全”的错觉。SAR是“单位质量单位时间”的功率概念，缩短TR只会提高功率密度。真正靠缩短时间降SAR的做法是用并行采集减少激励次数或减少层数，而非压TR。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0112", "t": "单选题", "s": "飞利浦3.0T行颈椎T2WI快速自旋回波（TSE/FSE）时系统提示SAR超限，下列调整中不能降低SAR、反而会使其升高的是", "o": {"A": "启用可变翻转角重聚焦（VFL/变角回波链），把重聚焦脉冲翻转角由180°降至约120°", "B": "适当延长TR", "C": "减少同一TR内的采集层数（分两个采集包完成）", "D": "缩短回波链长度（turbo factor/ETL）", "E": "将重聚焦脉冲翻转角由120°提高至180°以增强T2对比"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-012", "kp": "SAR超限的参数调整策略", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】E正确（即“不能降低SAR”的选项）。射频能量沉积近似正比于翻转角的平方，把重聚焦角从120°提高到180°，单个脉冲能量约增至2.25倍，SAR随之显著升高，与降SAR目标背道而驰。【为什么错】A是降SAR最有效的手段之一：TSE的SAR绝大部分来自串联的大角度重聚焦脉冲，采用可变翻转角（结合过渡态驱动、hyperecho）可在基本保持对比的前提下大幅降低能量沉积，代价是略降SNR与轻度模糊。B延长TR直接降低单位时间射频占空比，SAR下降，代价是扫描时间延长。C减少每个TR内的层数等于减少该TR窗口内的射频脉冲总数，SAR下降。D缩短回波链意味着每个TR内重聚焦脉冲更少，SAR下降，代价是采集时间延长、T2模糊减轻但效率降低。", "tr": "本题的核心是“SAR∝α²”这一定量关系。考生易只记住“TSE的SAR高”，却不知道降SAR的第一杠杆是重聚焦翻转角而非TR。另注意：提高接收带宽虽可缩短回波间隔，但会使射频脉冲更密集，对SAR并无帮助。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0113", "t": "单选题", "s": "行磁共振胰胆管成像（MRCP）与上腹部MRI前，通常要求患者禁食4—6 h，其最主要的技术目的是", "o": {"A": "减少胃十二指肠内液体与蠕动造成的高信号干扰及运动伪影，同时使胆囊充盈、胆管生理性扩张，便于重T2权重下显示", "B": "降低射频能量沉积（SAR）", "C": "减小呼吸运动幅度以便屏气", "D": "延长胆汁的T2弛豫时间以提高信噪比", "E": "预防钆对比剂过敏反应"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-013", "kp": "MRCP与上腹部检查前禁食的技术依据", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确。MRCP依靠超长TE的重T2权重使静止或缓慢流动的液体呈显著高信号、实质与流动血液呈低信号。胃与十二指肠内的液体同样是长T2的水，会在最大密度投影（MIP）上叠加于胆总管、胰管之上造成假象；进食后胆囊排空、胆管管径变小也不利显示。禁食4—6 h既减少胃肠液体与蠕动，又保证胆囊充盈。临床上常联合口服含锰的阴性对比剂（如菠萝汁、蓝莓汁）进一步抑制胃肠道液体信号。【为什么错】B禁食与射频功率沉积无关，SAR取决于翻转角、脉冲数与场强。C禁食不改变呼吸幅度，减小呼吸运动靠屏气训练、呼吸门控/触发或导航回波。D胆汁T2值是组织固有属性，不因禁食改变；MRCP靠的是超长TE凸显长T2组织，而非改变T2。E钆剂过敏与禁食无因果关系，预防依靠病史筛查与急救准备。", "tr": "D是很有迷惑性的干扰项——把“利用长T2”误读为“延长T2”。请牢记：技术准备改变的是“信号来源的分布”（哪里有水、有多少水），而不是“组织的弛豫常数”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0114", "t": "案例分析题", "s": "患者男，45岁，身高172 cm，体重102 kg，因腰痛伴右下肢放射痛行腰椎MRI。技师采用后部脊柱相控阵线圈，患者仰卧、双腿伸直，激光定位灯对准剑突下缘后送入磁体等中心。所得矢状面T2WI显示：腰段整体信噪比偏低，L5—S1椎间盘区信号衰减明显、椎管内结构模糊，且相位编码（前后）方向上腹壁脂肪折叠至椎管前方。设备为飞利浦3.0T。下列处理组合最合理的是", "o": {"A": "将定位中心改置于髂嵴连线上方约2—3 cm（相当于L4椎体水平），使感兴趣区居于线圈中心与磁体等中心；在膝下垫楔形垫使腰椎生理前凸变平、腰背部更贴近后部线圈；开启前部体线圈单元行前后联合接收以改善深部SNR；相位编码方向仍取前后但增加过采样（no phase wrap/折叠抑制）或改用饱和带抑制腹壁脂肪", "B": "把定位中心保持在剑突不变，仅提高翻转角以增加信号强度", "C": "将相位编码方向由前后改为上下，并取消过采样", "D": "改用体线圈发射兼接收，可同时解决SNR不足与折叠伪影", "E": "增大FOV至400 mm并把层厚增至8 mm，以覆盖全部腰椎并提高信噪比"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-014", "kp": "线圈选择、摆位与定位中心", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确，逐条对应了三个问题。①定位中心错误：腰椎的定位标志是髂嵴连线（约平L4椎体或L4/5间隙），对准剑突会使腰骶段位于线圈敏感区边缘，L5—S1信号衰减正是表面线圈灵敏度随距离迅速下降的表现；同时感兴趣区偏离磁体等中心会加重梯度非线性形变与匀场不良。②肥胖患者腰背部与后部线圈之间距离增大、且腰椎前凸使椎体远离线圈，膝下垫高可使腰椎变平、贴近线圈，是提高SNR最直接的物理手段；有条件时加用前部线圈单元行前后联合接收可显著改善深部信号。③相位编码方向为前后时腹壁在FOV外产生卷褶，处理办法是相位方向过采样（折叠抑制）或对FOV外组织施加空间饱和带。【为什么错】B提高翻转角在自旋回波类序列中受Ernst角与SAR双重限制，且不解决线圈距离与定位中心问题，3.0T下还会引发SAR超限。C腰椎矢状面若把相位方向改为上下，会把上下方向的运动（吞咽、心血管搏动传递、腹主动脉搏动）伪影铺到椎体上，且上下向FOV更长、易在头足方向折叠，得不偿失。D体线圈接收的SNR远低于相控阵表面线圈，是典型的方向性错误。E增大FOV虽可消除折叠但同时降低空间分辨率，8 mm层厚会显著加重部分容积效应，掩盖神经根受压细节，属于以牺牲诊断信息换取表观信噪比。", "tr": "本题三个陷阱叠加：把“定位中心”当成随意可选；把“提高翻转角/增大FOV”当作万能补救；忽视体位（膝下垫高）这一零成本的SNR优化手段。请牢记腰椎定位标志=髂嵴连线（约L4），颈椎=甲状软骨（约C4/5），胸椎=胸骨角向下计数或胸骨中点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0115", "t": "单选题", "s": "在飞利浦3.0T上行颅内动脉3D时间飞跃法磁共振血管成像（3D TOF-MRA）时，为抑制静脉信号、突出动脉，空间预饱和带应设置在", "o": {"A": "成像容积的头侧（上方），随容积同步移动", "B": "成像容积的足侧（下方），随容积同步移动", "C": "成像容积的左右两侧", "D": "成像容积的前方（面部侧）", "E": "无须饱和带，3D TOF本身即不显示静脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-001", "kp": "TOF-MRA饱和带的方位选择", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确。TOF的对比来源是“流入增强”：成像容积内静止组织被反复射频激励而饱和呈低信号，从容积外流入的新鲜未饱和质子呈高信号。因此要抑制哪一支血管，就把预饱和带放在该血管“流入的上游”。颅内动脉血自颈部向上（自足侧向头侧）进入成像容积，静脉血则自颅顶向下经乙状窦、颈内静脉回流（相对成像容积由头侧流入），故抑制静脉的饱和带应置于成像容积的头侧，并设置为随容积同步移动（travelling/walking saturation）。反之，做颈静脉成像（如2D TOF静脉法）时饱和带放在足侧以抑制上行动脉血。【为什么错】B放在足侧会把要显示的动脉血饱和掉，动脉信号丢失。C左右侧饱和带用于抑制侧方来源（如单侧颈动脉），不解决静脉污染。D前方饱和带常用于抑制腹壁运动或眼球运动，与颅内静脉抑制无关。E错误：3D TOF若不加饱和带，硬脑膜静脉窦与皮层静脉常有明显信号残留，尤其在MIP上叠加于动脉之上。", "tr": "口诀：“抑谁，就堵谁的上游”。颅内MRA抑静脉→上方饱和带；颈部静脉成像抑动脉→下方饱和带。切勿死记“饱和带永远在上方”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0116", "t": "多选题", "s": "关于2D与3D时间飞跃法MRA（TOF-MRA）及其改良技术，下列说法正确的有", "o": {"A": "2D TOF逐层薄层激发，每层的流入效应充分，对慢血流敏感、覆盖范围大，适合颈部血管与下肢血管的长段筛查", "B": "3D TOF体素小、SNR与空间分辨率高，是颅内动脉（Willis环）成像的首选，但容积内血液随行程被反复激励易发生饱和，远端小血管显示衰减", "C": "多块重叠薄层采集（MOTSA/滑动块）通过若干互相重叠的薄容积拼接，兼顾覆盖范围与流入效应，但可产生块与块交界处信号阶梯，即“百叶窗（venetian blind）”伪影", "D": "倾斜优化非饱和激励（TONE，即斜坡脉冲）沿血流流入方向逐渐增大射频翻转角，用以补偿血液进入容积深部后的饱和效应，改善远端动脉显示", "E": "磁化传递（MTC）预脉冲通过抑制血液内自由水的信号来提高血管与背景的对比"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-002", "kp": "2D/3D TOF及MOTSA、TONE、MTC", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确：2D TOF单层厚度大但每层独立激发，血液进入每一层时都是“新鲜”的，故对慢血流敏感，适合颈动脉/下肢等长范围、流速较低的血管。B正确：3D TOF的优势是各向同性高分辨与高SNR，劣势是容积内饱和，故对Willis环近端显示优异、对远端分支与慢血流（如动脉瘤内涡流、烟雾病侧支）显示受限。C正确：MOTSA是2D覆盖能力与3D分辨率的折中，块间由于流入效应不均产生周期性亮暗条带，即百叶窗伪影，通过增大块间重叠比例（常20%—30%）可减轻。D正确：TONE把容积入口侧翻转角设小、出口侧设大，使先进入的血液少消耗纵向磁化、后段血液获得更强激励，从而拉平沿程信号衰减。【为什么错】E错误：MTC的机制说反了。MTC通过偏共振射频脉冲饱和大分子（蛋白、膜脂）结合水质子池，经交换使脑实质等含大分子丰富的背景组织信号下降；而流动血液内自由水与大分子交换少，信号基本不受影响，从而提高血管/背景对比。MTC抑制的是背景，不是血液。", "tr": "E是本题的核心陷阱——MTC“抑背景不抑血”。此外要注意MTC会显著增加SAR，3.0T上常需与低翻转角、并行采集联合使用；MTC还会削弱增强后小病灶的对比，不宜与增强扫描随意叠加。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0117", "t": "单选题", "s": "行颅内静脉窦相位对比法磁共振血管成像（PC-MRA）时，技师沿用了动脉的编码流速VENC＝80 cm/s，结果静脉窦显示暗淡、信噪比很差；改为VENC＝15 cm/s后静脉窦显示良好，但上矢状窦中心区出现与实际血流方向相反的黑白反转。对这两次结果的正确解释是", "o": {"A": "VENC过高时相位位移过小、流速噪声相对增大导致血管信号弱；VENC过低时超过VENC的流速发生相位混叠（aliasing），表现为高流速区流向反转", "B": "VENC过高会导致相位混叠，VENC过低会降低信噪比，两次现象顺序应互换", "C": "两种现象均由静脉窦内血栓造成，与VENC无关", "D": "VENC只影响图像亮度，不影响相位方向的正确性", "E": "应把VENC设为0以获得最佳静脉显示"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-003", "kp": "PC-MRA的VENC设置与相位混叠", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确。PC-MRA用一对双极梯度对运动质子施加与速度成正比的相位位移，VENC定义为产生±180°相位位移所对应的流速。VENC设得过高，实际流速产生的相位角很小，信号被相位噪声淹没，血管显示暗淡、SNR差；VENC设得过低，超过VENC的流速其相位超过±180°而发生卷绕（混叠），在相位图上表现为高流速中心区域的信号极性反转（黑白倒置），流量定量结果也随之错误。经验做法是把VENC设为预期峰值流速的1.1—1.5倍：颅内动脉常用60—80 cm/s，静脉窦常用15—25 cm/s，脑脊液流动定量常用5—10 cm/s。【为什么错】B把两种现象完全说反。C静脉窦血栓表现为充盈缺损与信号缺失，不会随VENC改变而呈现这种规律性变化，且两次扫描解剖表现不一致已排除固定病变。D错误：相位方向的正确性正是由VENC决定的，混叠本质上就是相位方向的错误编码。E错误：VENC不能为0，为0意味着不施加流速编码，无法产生任何血流对比。", "tr": "口诀：VENC偏高丢信号（噪声大、显示淡），VENC偏低出混叠（流向反转、流量算错）。多数考生只记住“混叠”而记反了方向。临床上遇到混叠也可先扩大VENC重扫，或使用双VENC/相位解卷绕算法。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0118", "t": "多选题", "s": "关于相位对比法MRA（PC-MRA）的技术特点，下列说法正确的有", "o": {"A": "其对比机制是流动质子在双极流速编码梯度作用下产生与流速成正比的相位差，静止组织相位差为零而被减影去除", "B": "既可输出反映血管形态的幅值（magnitude）图，也可输出可用于流速、流量定量的相位（phase）图", "C": "背景抑制优于TOF，对慢血流（如静脉窦、脑脊液搏动）敏感，可用于导水管脑脊液流量测定以评估正常压力脑积水", "D": "三维PC-MRA需要在三个正交方向分别施加流速编码，采集时间明显长于同等分辨率的3D TOF", "E": "PC-MRA不受VENC设置影响，任何流速均可准确成像，因此可完全取代CE-MRA"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-004", "kp": "PC-MRA原理与临床定位", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确：双极梯度对静止自旋的净相位为零、对运动自旋产生净相位，两次相反极性编码相减即得纯血流信号，这也是PC背景抑制极佳的原因。B正确：幅值图看形态，相位图（速度图）可逐像素读出流速，进而通过管腔面积积分得到流量（mL/s或mL/心动周期）。C正确：PC对慢流敏感且无饱和效应，是中脑导水管脑脊液流速/每搏流量测定的标准方法，用于正常压力脑积水评估与分流术前后对比。D正确：3D PC需在x、y、z三方向各做一次流速编码（加参考采集共4次），采集时间成倍增加，这是其临床普及度低于TOF与CE-MRA的主要原因。【为什么错】E错误：PC-MRA对VENC高度依赖，VENC不当会造成信噪比下降或相位混叠；且其扫描时间长、对湍流敏感，大范围血管（主动脉、外周动脉）仍以CE-MRA为首选，PC不能取代CE-MRA。", "tr": "E中“不受VENC影响”与“完全取代”双重绝对化。要牢记三种MRA的定位：TOF看颅内动脉形态；PC做血流定量与慢流评估；CE-MRA做大范围、大血管、高流速与狭窄程度评估。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0119", "t": "单选题", "s": "对比增强MRA（CE-MRA）中，为使动脉期图像不受静脉污染，采集时机与K空间填充方式的关系应为", "o": {"A": "采用K空间中心优先（centric/elliptic centric）填充，并使K空间中心的采集时刻恰好落在靶血管团注峰值期", "B": "采用K空间顺序（linear）填充，把K空间中心放在采集末段以获得最高信噪比", "C": "K空间填充顺序与静脉污染无关，只需缩短对比剂注射时间", "D": "把K空间中心放在采集起始的第一秒，无论对比剂是否到达", "E": "只要使用高浓度钆剂，任何填充顺序都不会出现静脉污染"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-005", "kp": "CE-MRA的团注时相与K空间中心填充", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确。K空间中心决定图像的对比度与整体信号强度，边缘决定细节与边界锐利度。因此CE-MRA的核心技术要求是让K空间中心的数据在靶动脉内钆浓度最高的瞬间被采集——即“峰值对峰值”。中心优先（椭圆中心）填充把中心数据放在采集最开始，配合团注测试（test bolus）或透视触发（BolusTrak/CARE Bolus/SmartPrep）确定触发延迟，可在静脉尚未回流时锁定动脉期对比度。【为什么错】B线性填充把中心放在采集中段，若采集窗较长，中心采集时刻可能已进入静脉期，导致静脉重叠；线性填充多用于时间分辨率不敏感或首过时间窗充裕的部位。C错误：静脉污染的本质是“K空间中心采集时刻晚于动脉峰、进入静脉期”，与填充顺序直接相关；缩短注射时间虽可缩窄动脉窗，但若时相不匹配反而更易失败。D错误：中心提前到对比剂尚未到达时采集，会造成动脉信号极弱甚至完全无强化（所谓“环状伪影”或Maki伪影，因中心期浓度快速变化引起）。E错误：钆浓度不能改变循环时间，静脉回流是生理过程，与浓度无关。", "tr": "两个方向的失败要分清：中心采集过早→动脉信号弱、边缘模糊、可出现Maki（环晕）伪影；中心采集过晚→静脉污染。此外，团注时长应大致等于或略长于采集时间窗，并常规用生理盐水20 mL同速率冲管以维持团注紧凑度。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0120", "t": "案例分析题", "s": "患者男，66岁，高血压30年，拟诊胸腹主动脉夹层，行CE-MRA。设备为飞利浦3.0T，18G留置针置于右肘正中静脉，高压注射器以2.5 mL/s注入钆剂20 mL＋生理盐水20 mL。技师使用固定延迟18 s触发采集，K空间采用线性填充，采集时间22 s、屏气完成。所得图像：主动脉腔内信号中等，下腔静脉与肾静脉明显强化并与腹主动脉重叠，MIP上难以判断真假腔关系。下一次复查最合理的技术改进是", "o": {"A": "改用透视触发（实时监测降主动脉内信号，见对比剂到达即嘱屏气并启动采集），K空间改为椭圆中心填充；必要时先做团注测试测得个体循环时间；同时可加做时间分辨（4D）CE-MRA以捕捉多个时相", "B": "把固定延迟从18 s缩短到8 s，其余不变", "C": "把钆剂总量增加到40 mL，注射速率降至1 mL/s以延长强化平台", "D": "改为非对比增强MRA（TOF）替代CE-MRA，可完全避免静脉污染", "E": "把采集时间延长到45 s并改自由呼吸，以提高信噪比"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-006", "kp": "CE-MRA静脉污染的原因分析与对策", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确。本例的根本问题是“时相不匹配”：固定延迟无法适应个体循环时间（心衰、夹层、主动脉瘤者循环显著延长或缩短），线性填充又把K空间中心推到采集中段（约第11 s），叠加后中心数据落在静脉期，故出现静脉污染而动脉对比不足。改进逻辑有三层：①用透视触发或团注测试获得个体化触发时刻；②改椭圆中心填充使对比度数据在动脉峰值瞬间采集；③夹层需要观察真假腔血流充盈的时间差，加做时间分辨4D CE-MRA（联合并行采集与压缩感知可达每帧2—4 s）能提供动态信息，比单时相更有价值。【为什么错】B单纯缩短固定延迟仍是“盲猜”，且线性填充的中心时刻问题未解决，重复失败概率高。C增加钆剂总量既提高不良反应与肾源性系统性纤维化风险，又因注射速率降低使团注被稀释、峰值浓度下降、动脉期变得平坦而更易被静脉重叠，方向错误。D错误：胸腹主动脉范围长、血流方向复杂且存在层流/涡流，TOF在此处饱和效应严重、易高估狭窄，根本无法替代CE-MRA；若确需无对比剂方案，应选心电门控的三维快速自旋回波类非增强MRA（TRANCE/NATIVE SPACE/Inhance）。E延长采集与自由呼吸只会引入更多呼吸运动伪影，且更深地进入静脉期，问题加重。", "tr": "考生常把静脉污染归咎于“对比剂太多”，实则关键是“K空间中心的采集时刻”。另一个易错点是把非增强MRA的技术选型搞混：躯干大血管的非增强方案是心电门控3D TSE（收缩期—舒张期减影），不是TOF。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0121", "t": "多选题", "s": "关于非对比增强MRA（飞利浦TRANCE、西门子NATIVE、GE Inhance等）的技术原理与适用情形，下列说法正确的有", "o": {"A": "其中一类基于心电门控的三维快速自旋回波（TSE/FSE）技术，利用收缩期动脉血因高速流动而信号丢失、舒张期动脉血信号恢复的差异，将两期图像相减获得纯动脉像", "B": "另一类基于平衡稳态自由进动（bTFE/TrueFISP/FIESTA）并结合反转恢复或空间选择性标记，利用血液长T2/T1比值高的固有对比显示血管，常用于肾动脉与冠状动脉", "C": "对肾功能不全（eGFR明显降低）而不宜使用钆剂的患者，是重要的替代方案", "D": "心电门控依赖稳定心律，严重心律不齐者收缩期与舒张期采集时相错乱，减影失败风险高", "E": "非对比增强MRA的空间分辨率与扫描速度均优于CE-MRA，已在各部位全面取代后者"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-007", "kp": "非对比增强MRA技术分类与适应人群", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确：这是下肢与外周动脉最常用的减影型非增强MRA原理，收缩期高速血流在长回波链TSE中因流空而呈低信号，舒张期血流缓慢呈高信号，两者相减即得动脉图，静脉因全程流速低而在两期均为高信号被减掉。B正确：bTFE的信号强度取决于T2/T1，血液T2/T1比值高故呈亮信号；配合非选择性反转＋选择性反转（如空间标记反转）可抑制背景与静脉，广泛用于肾动脉、门静脉与全心冠脉成像。C正确：这正是非增强MRA复兴的主要临床驱动力——避免钆剂在重度肾功能不全患者中的肾源性系统性纤维化风险。D正确：门控稳定性是减影型技术的命门，房颤或频发早搏时两期采集的心动时相漂移，减影残留严重。【为什么错】E错误：非增强MRA采集时间通常长于CE-MRA（需多心动周期采集与减影），对运动与心律更敏感，在大范围血管与复杂病变的整体可靠性仍不及CE-MRA，谈不上“全面取代”。", "tr": "E的“全面取代”是典型绝对化陷阱。要点：非增强MRA是“对特定人群、特定部位的替代”，不是“普适升级”。另注意区分同名不同义：Inhance既包含流入反转恢复（IFIR）也包含减影型技术，答题时以原理描述为准而非商品名。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0122", "t": "单选题", "s": "与3D TOF-MRA相比，CE-MRA最本质的成像对比来源是", "o": {"A": "血液流入未饱和质子产生的流入增强效应", "B": "钆剂缩短血液T1使其在超短TR的扰相梯度回波（T1-FFE/FLASH/SPGR）上呈高信号，对比几乎不依赖血流速度与方向", "C": "流动质子的相位位移", "D": "血液与背景之间T2差异的放大", "E": "磁化传递效应对背景组织的抑制"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-008", "kp": "CE-MRA的对比机制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】B正确。CE-MRA属于T1对比技术：团注钆剂后血液T1可由约1200 ms（3.0T）骤降至100 ms以下，在TR极短（3—5 ms）、翻转角25°—40°的三维扰相梯度回波序列中，血液纵向磁化恢复远快于背景组织而呈显著高信号。由于对比来源是“血液本身的T1”，它基本不依赖血流速度、方向与层面关系，因而不会出现TOF那样的面内流动饱和与湍流失相位所致的狭窄高估。【为什么错】A是TOF的机制。C是PC的机制。D错误：CE-MRA采用极短TE（1—2 ms）以最大限度减少T2*失相位，其对比与T2差异无关。E MTC是TOF常用的背景抑制辅助手段，不是CE-MRA的对比来源，反而因增加SAR与降低强化对比一般不与CE-MRA叠加。", "tr": "记住三条主线：TOF＝流入效应（T1效应＋流动）、PC＝相位差、CE＝钆剂缩短T1。也正因为CE不依赖流动，它在血流缓慢的重度狭窄远段、动脉瘤囊内、迂曲血管中显示更真实。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0123", "t": "单选题", "s": "MR水成像（如MRCP、MRU）能使胆汁、尿液等静止液体呈显著高信号而实质器官与流动血液呈低信号，其技术核心是", "o": {"A": "采用超长TE（常600—1200 ms）的重T2权重序列，长T2的静止液体信号残留而短T2组织信号已衰减殆尽", "B": "采用超短TR的T1权重序列使液体呈高信号", "C": "依赖静脉注射钆剂使液体强化", "D": "利用液体的高质子密度形成对比，与TE无关", "E": "通过脂肪抑制使液体相对变亮"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-001", "kp": "MR水成像的重T2权重原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确。胆汁、尿液、脑脊液、内耳外淋巴液的T2值可达数百至上千毫秒，而肝、胰、肌肉等实质组织T2仅数十毫秒。把TE延长至数百毫秒以上时，实质组织的横向磁化已基本衰减为零，只有长T2液体仍有可观残留，从而形成“水亮、其余全黑”的类造影效果。流动血液则因流空效应呈低信号，进一步净化背景。【为什么错】B错误：T1权重下液体是低信号，方向完全相反。C错误：MR水成像是无创、不用对比剂的技术，这正是其相对ERCP与静脉尿路造影的最大优势；只有排泄性MRU才使用钆剂。D错误：质子密度差异远不足以形成如此强的对比，TE恰恰是决定性参数。E错误：脂肪抑制只是抑制脂肪的高信号背景（常规联用以提高MIP质量），并不能让实质组织变黑，不是核心机制。", "tr": "常见误区是把水成像等同于“T2WI加脂肪抑制”。区别在于TE的量级：常规T2WI的TE约80—100 ms，水成像的有效TE要长一个量级。若TE不够长，胰腺、十二指肠壁等中等T2组织会残留信号污染MIP图像。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0124", "t": "多选题", "s": "关于MRCP两类主要采集方式的比较，下列说法正确的有", "o": {"A": "屏气二维厚层块单次激发TSE（SSh-TSE/HASTE/SSFSE）一次激发即得一幅投影像，扫描仅数秒，适合屏气差或急诊患者的快速筛查", "B": "呼吸触发（导航回波或呼吸带）的三维高分辨TSE可获得各向同性薄层数据，能行MIP与曲面重组，对胆管细微狭窄、胰管分支的显示优于二维厚层", "C": "三维MRCP常联合脂肪抑制（SPIR/SPAIR）以降低腹膜后脂肪高信号对MIP的干扰", "D": "二维厚层块因层厚大（常30—80 mm），小结石可能被部分容积效应掩盖，故不能单独作为诊断依据，需与薄层或三维图像结合", "E": "三维呼吸触发MRCP因采集时间长，应嘱患者尽量深大呼吸以缩短触发间隔"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-002", "kp": "MRCP屏气二维与呼吸触发三维的取舍", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确：单次激发在一个TR内用长回波链填满整个K空间，2—4 s即可完成一幅厚层投影，是不能配合者的救命方案，还可多角度旋转采集获得类ERCP观。B正确：3D TSE配合可变翻转角长回波链与呼吸导航，可获得约1 mm等体素数据，是显示胆管解剖变异、胰腺分裂、细小狭窄的主力序列。C正确：脂肪在重T2权重下仍有一定信号，MIP时会形成弥漫背景雾化，脂肪抑制可显著提升胆胰管的对比。D正确：厚层块是投影像，缺乏层面信息，直径2—3 mm的结石可被周围高信号胆汁淹没，必须结合薄层轴位T2WI与三维图像判读。【为什么错】E错误：呼吸触发依赖规律、平稳、幅度一致的呼吸；深大呼吸会使膈肌位移幅度增大、触发窗漂移，导致图像模糊与采集效率下降。正确指导是“平静、均匀、浅而规律地呼吸”，并在扫描前进行呼吸训练。", "tr": "E利用了“想快点做完”的直觉。呼吸触发/导航技术追求的是呼吸的一致性而非频率；导航回波接受窗通常设在呼气末（膈肌位置最稳定），门控效率若低于40%应重新训练患者或改屏气方案。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0125", "t": "单选题", "s": "患者女，62岁，右侧腰痛伴血肌酐升高（eGFR 28 mL/min/1.73m²），超声提示右肾积水，需明确梗阻部位。最恰当的MR尿路成像方案是", "o": {"A": "静水法MRU（重T2权重的呼吸触发三维TSE＋厚层单次激发投影），利用积聚的尿液自身长T2成像，不使用钆剂", "B": "排泄性MRU：静脉注射钆剂后行三维T1加权采集，观察对比剂经肾排泄充盈尿路", "C": "注射钆剂后加用利尿剂以加速排泄，提高尿路显示", "D": "行CE-MRA观察肾动脉，间接推断梗阻部位", "E": "行DWI高b值成像替代MRU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-003", "kp": "静水法MRU与排泄性MRU的选择", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确。静水法（静态液体）MRU属重T2权重水成像，不依赖肾功能、不需对比剂，只要尿路内有积聚的尿液即可显示，对已扩张的梗阻性尿路显示最佳，恰好适用于本例eGFR明显降低而不宜使用钆剂的患者。技术上常采用呼吸触发3D TSE获得薄层数据加MIP，并辅以厚层单次激发投影快速观察全貌。【为什么错】B排泄性MRU依赖肾脏浓缩与排泄功能，eGFR 28时排泄延迟、对比剂浓度低，显示效果差；更重要的是重度肾功能不全使用钆剂存在肾源性系统性纤维化风险，属应回避的方案。C在B的基础上叠加利尿剂，既未解决钆剂禁忌，又可能加重脱水与电解质紊乱。D肾动脉成像无法回答“梗阻部位在哪一段尿路”这一临床问题，且同样需要钆剂。E DWI可提示肾实质与病灶信息，但不能连续显示尿路走行与梗阻端形态，不能替代MRU。", "tr": "关键分水岭是肾功能：肾功能良好且尿路不扩张（如需评价功能或非梗阻性病变）可选排泄性MRU；肾功能不全或已有明显积水优先静水法。切记重度肾功能不全者尽量避免钆剂，必须使用时选大环状制剂并用最低剂量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0126", "t": "案例分析题", "s": "患者女，34岁，右耳渐进性听力下降伴耳鸣3个月，纯音测听示右侧感音神经性聋，临床怀疑内听道内小听神经瘤（可能仅2—3 mm）。设备为飞利浦3.0T，配备8通道头线圈与压缩感知加速。为在最短时间内获得最可靠的内耳与内听道评估，下列扫描方案最合理的是", "o": {"A": "采集三维重T2权重高分辨水成像（3D bTFE/DRIVE/CISS/FIESTA-C类），层厚≤0.6 mm、各向同性体素、FOV小视野聚焦于双侧桥小脑角与内听道，在高信号脑脊液衬托下观察面听神经四条神经束是否有充盈缺损；再补充三维T1增强薄层以判断强化", "B": "仅采集常规轴位T2WI TSE，层厚5 mm，即可满足诊断", "C": "采用二维时间飞跃法MRA观察迷路动脉走行以间接判断", "D": "行内听道DWI高b值成像作为主要序列", "E": "行1H-MRS测定桥小脑角区代谢物以定性"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-004", "kp": "内耳水成像技术要点", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确。内耳水成像的技术要点是“三高一小”：高分辨（亚毫米各向同性）、高T2权重（膜迷路内淋巴液与内听道脑脊液呈极高信号）、高信噪比（小FOV＋薄层＋多次平均或压缩感知补偿），小视野聚焦以提高空间分辨率。在明亮的脑脊液背景中，面神经、蜗神经、前庭上/下神经呈四条低信号束，微小肿瘤表现为神经束增粗或脑脊液内的充盈缺损，敏感性远高于常规厚层T2WI。三维T1增强薄层用于确认强化并与蛛网膜囊肿、血管袢等鉴别。需注意bTFE类序列对磁场不均匀敏感，3.0T下须精细匀场，必要时改用三维TSE类水成像（VISTA/SPACE/CUBE）以减轻带状伪影。【为什么错】B层厚5 mm对2—3 mm病灶存在严重部分容积效应，极易漏诊，是临床上小听神经瘤漏诊的典型原因。C迷路动脉直径远小于MRA的分辨能力，且血管走行不能推断神经受累。D内听道区域体积小、邻近颞骨气房，EPI-DWI变形与磁敏感伪影严重，DWI在此处主要用于鉴别胆脂瘤而非检出微小听神经瘤。E MRS需要足够大的体素（通常≥1 cm³）与良好匀场，桥小脑角区紧邻颅骨与气房，既无法满足体素要求也无法匀场，属于超出技术适用范围的选择。", "tr": "陷阱在于把“内耳水成像”与“常规颅脑T2WI”混淆。副高层面要能说出参数级要求：亚毫米各向同性、小FOV、高T2权重；并能指出bTFE在3.0T的带状（banding）伪影风险及其替代方案（3D TSE类水成像）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0127", "t": "单选题", "s": "MR脊髓成像（MR myelography，MRM）主要显示的结构是", "o": {"A": "蛛网膜下腔内脑脊液及其被硬膜囊、神经根鞘勾勒出的轮廓，从而间接显示压迫与神经根袖形态", "B": "脊髓内部灰白质分界", "C": "椎体骨髓信号变化", "D": "椎旁静脉丛", "E": "椎间盘髓核的含水量定量"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-005", "kp": "MR脊髓成像的显示对象", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确。MRM属水成像家族，用重T2权重序列（多为屏气或呼吸触发的单次激发TSE厚层块，或3D TSE薄层重建）使脑脊液呈极高信号、其余结构呈低信号，形成类似X线脊髓造影的效果。它显示的是脑脊液柱的外形：椎间盘突出压迫处呈弧形压迹，神经根袖显示为对称的“袖套”，臂丛/腰骶丛神经根撕脱可见假性脊膜膨出。其最大优势是无创、无须鞘内注射对比剂。【为什么错】B脊髓灰白质分界需高分辨T2WI或质子密度加权轴位显示，MRM把髓内信息完全淹没在低信号中。C骨髓评估依赖T1WI与脂肪抑制T2WI/STIR。D椎旁静脉丛显示需要增强T1WI或血管序列。E椎间盘含水量定量属于T2 mapping等定量技术范畴，与MRM无关。", "tr": "MRM是“看脑脊液的外形”，不是“看脊髓的内部”。因此它绝不能替代常规矢状/轴位T2WI——临床上必须两者结合，单独MRM会漏诊脊髓内病变（如脱髓鞘、髓内肿瘤、脊髓空洞）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0128", "t": "单选题", "s": "关于DWI的b值选择与表观扩散系数（ADC）计算，下列说法正确的是", "o": {"A": "ADC由至少两个不同b值的信号按单指数模型 S(b)=S₀·exp(−b·ADC) 拟合得到，b值间隔越大拟合越稳定，但高b值图像的SNR随之下降", "B": "只用一个b值即可直接计算ADC", "C": "b值越高ADC值越大，故报告ADC时无须注明b值组合", "D": "ADC图上信号越亮表示扩散越受限", "E": "b＝0图像即为纯扩散图像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-001", "kp": "b值选择与ADC计算", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。单指数模型下，两点法ADC＝ln(S₁/S₂)/(b₂−b₁)。b值差越大，分母越大、测量噪声被放大的程度越小，因此拟合更稳定；但b值升高时信号按指数衰减，高b值图像SNR急剧下降，噪声本底又会使ADC被系统性低估。颅脑常规采用b＝0与1000 s/mm²，腹部常用0、50（或100）与800 s/mm²（用低b＝50抑制血流灌注的伪扩散贡献），前列腺常加采b≥1400 s/mm²。【为什么错】B单点无法确定指数衰减的斜率，必须至少两点。C恰好说反：b值升高时，由于灌注成分与非高斯扩散的影响，实测ADC通常降低而非升高；也正因ADC依赖所用b值组合，报告与随访必须固定并注明b值。D错误：ADC图上扩散受限表现为低信号（暗），DWI高信号＋ADC低信号才是真扩散受限；DWI高＋ADC也高提示T2透过效应。E错误：b＝0图像不含扩散权重，本质是T2权重的EPI图像，是计算ADC的参考基线，不是扩散图。", "tr": "两个高频陷阱：①ADC图的信号方向（暗＝受限）；②b值组合不同则ADC不可直接比较，这是随访与多中心研究中最常见的方法学错误。另注意噪声本底对高b值ADC的系统性低估，可用去噪或对数域加权拟合缓解。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0129", "t": "多选题", "s": "关于DWI在不同疾病中的应用价值，下列说法正确的有", "o": {"A": "超急性期脑梗死细胞毒性水肿使细胞外间隙缩小，发病数分钟至数十分钟即可表现为DWI高信号、ADC降低，早于CT与常规T2WI", "B": "脑脓肿腔内含黏稠脓液、大量炎性细胞与蛋白，扩散明显受限呈DWI高信号、ADC降低；囊变坏死的肿瘤多为清亮液体，DWI低信号、ADC升高", "C": "中耳胆脂瘤的角化鳞状上皮碎屑扩散受限，非EPI-DWI（如TSE-DWI/HASTE-DWI）因磁敏感伪影小，比EPI-DWI更适合颞骨区检出与术后复发监测", "D": "急性期脑梗死的ADC值随时间演变，在约7—10天后可因血管源性水肿与细胞溶解出现“假正常化”，此时ADC回升至接近正常，仅凭ADC可能低估病灶", "E": "表皮样囊肿与蛛网膜囊肿在DWI上表现一致，DWI对二者鉴别无价值"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-002", "kp": "DWI的临床应用与陷阱", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确：这是急诊卒中流程把DWI置于首位的根本原因。B正确：这是脓肿与囊变肿瘤最重要的影像鉴别点，术前判断价值极高。C正确：颞骨区气—骨界面多，EPI-DWI几何变形与磁敏感伪影严重，且层厚大；非EPI的TSE类DWI（如HASTE-DWI）虽扫描时间长，但变形小、可薄层，是国际公认的胆脂瘤检出与随访方法，可减少不必要的二次探查手术。D正确：ADC假正常化通常出现在发病后约7—10天，此期ADC回升，若仅看ADC可能误判为无病灶，需结合FLAIR/T2WI与临床时间窗综合判断。【为什么错】E错误：DWI恰恰是二者鉴别的关键——表皮样囊肿内为角化物与胆固醇结晶，扩散受限呈DWI显著高信号；蛛网膜囊肿内为脑脊液，DWI低信号、ADC与脑脊液一致。二者在T1WI/T2WI上信号相近，正是DWI解决了这一经典难题。", "tr": "E是DWI最经典的教学考点却常被写成“无价值”这类反向陷阱。D的“假正常化”是时间维度陷阱，考生易只记“梗死＝ADC低”。C的非EPI-DWI是操作层面高频考点，务必记住其存在理由是“减少磁敏感变形”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0130", "t": "单选题", "s": "3.0T单次激发EPI-DWI在颅底、颞叶前部与额叶眶回附近出现明显的几何变形与信号堆积/丢失。下列关于其成因与校正措施的叙述，正确的是", "o": {"A": "变形主要源于EPI在相位编码方向上等效带宽极低，使磁场不均匀（气—骨界面磁化率差异）引起的频率偏移被放大为像素移位；提高并行采集因子、增大回波间隔带宽、缩短回波链、采用多次激发/读出分段EPI，以及采集相反相位编码极性（blip-up/blip-down）作场图校正，均可减轻变形", "B": "变形主要来自读出方向带宽不足，只需增大读出带宽即可完全消除", "C": "变形是由梯度非线性引起的，与磁化率无关", "D": "增加平均次数（NSA）即可校正几何变形", "E": "把b值从1000提高到2000 s/mm² 可减轻变形"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-003", "kp": "EPI几何变形的机制与失真校正", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。单次激发EPI在读出方向带宽很高（每个回波仅数百微秒），但在相位编码方向上，整条回波链耗时数十毫秒，等效每像素带宽仅几到几十赫兹，因此极小的频率偏移就会造成大幅像素位移，表现为颅底、鼻窦与颞骨旁的拉伸、压缩与信号堆积。有效对策：①缩短有效回波链——提高并行采集加速因子（SENSE/GRAPPA）或采用多次激发/读出分段EPI（RESOLVE类），直接提高相位方向等效带宽；②缩短回波间隔（提高读出带宽、加大梯度性能）；③基于场图或相反相位编码极性（blip-up/blip-down，即TOPUP类方法）的失真校正；④精细高阶匀场与局部匀场。【为什么错】B读出方向本身带宽已很高，变形主要不在该方向；单纯增大读出带宽只能略微缩短回波间隔，无法“完全消除”。C梯度非线性造成的是整体几何畸变（尤其大FOV边缘），与局部气—骨界面处的定向位移特征不符；EPI变形的主因是磁化率导致的B₀不均匀。D增加平均次数只提高SNR，对系统性几何位移毫无作用，甚至会因多次采集叠加而模糊。E提高b值会降低SNR，且不改变相位方向带宽，对变形无益。", "tr": "核心结论是“EPI变形发生在相位编码方向，与该方向的等效带宽成反比”。因此凡是能缩短单次读出链的手段都有效。考生常误答“增大读出带宽”或“增加NSA”，前者作用有限、后者完全无效。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0131", "t": "案例分析题", "s": "患者男，71岁，突发左侧肢体无力伴言语含糊，家属述“早上6:30醒来即发现异常，入睡前23:00一切正常”，到院时间08:10，NIHSS 12分。急诊CT平扫未见出血。神经内科希望通过MRI判断是否仍在可干预时间窗内并评估血管情况。设备为飞利浦3.0T（具备压缩感知，无深度学习重建）。最合理的急诊一站式MR方案是", "o": {"A": "DWI（含ADC）＋T2-FLAIR＋磁敏感加权成像（SWI）＋3D TOF-MRA＋灌注（DSC或ASL），总时长控制在10—15 min；重点判读DWI-FLAIR不匹配（DWI高信号而FLAIR尚无相应高信号提示发病<4.5 h）以及灌注—扩散不匹配的缺血半暗带", "B": "先做全套常规颅脑序列（T1WI、T2WI、T2-FLAIR、矢状位T1WI）再考虑功能序列", "C": "只做3D TOF-MRA，明确大血管闭塞即可", "D": "只做DWI，其余序列在溶栓后补做", "E": "先做1H-MRS判断缺血代谢改变，再决定是否行DWI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-004", "kp": "醒后卒中的急诊MR一站式方案", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。本例是典型的“醒后卒中/发病时间不明”，临床决策依赖影像替代时间窗。规范的急诊一站式组合各司其职：DWI确认梗死核心并定位；T2-FLAIR与DWI比对形成DWI-FLAIR不匹配——DWI已高信号而FLAIR尚未出现对应高信号，提示发病多在4.5 h内，可据此考虑静脉溶栓；SWI排查微出血与检出血管内血栓的磁敏感易感征（susceptibility vessel sign）；TOF-MRA明确有无大血管闭塞以决定取栓；灌注成像（DSC或ASL）评估低灌注范围与核心的不匹配，界定可挽救组织。总时长必须严格控制，通常10—15 min，可借助压缩感知与并行采集压缩3D序列时间。【为什么错】B急诊卒中流程严禁把常规序列排在前面，浪费的每分钟约损失190万个神经元，且T1WI等对超急性期几乎无贡献。C仅有血管信息而无组织学信息，无法判断核心大小与是否已大面积梗死，取栓决策同样需要核心体积。D仅DWI不能判断时间窗、不能排查微出血、不能评估血管与半暗带，信息严重不足。E MRS采集耗时长、需良好匀场，在急诊卒中中无实际决策价值，属明显的技术选型错误。", "tr": "考点在“为什么是这几条序列”而非“做得越全越好”。要记住每条序列对应的临床问题：DWI＝核心，FLAIR＝时间窗，SWI＝出血与血栓，MRA＝闭塞部位，PWI＝半暗带。另注意DWI-FLAIR不匹配的判断需在同层同窗宽下比对，避免窗技术造成的误判。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0132", "t": "单选题", "s": "体素内不相干运动成像（IVIM）与常规单指数DWI相比，下列叙述错误的是", "o": {"A": "IVIM采用多个b值（通常包含多个b<200 s/mm² 的低b值）按双指数模型拟合，可分离出反映毛细血管网微循环灌注的伪扩散系数D*与灌注分数f，以及反映真实分子扩散的D值", "B": "IVIM只需采集两个b值，通过双指数模型即可分解出D、D*与f", "C": "IVIM无须静脉注射钆剂即可获得反映微循环灌注的信息", "D": "去除灌注贡献后的真扩散系数D通常小于同部位的常规ADC", "E": "IVIM可用于肝纤维化分级、肝细胞癌疗效评估等腹部场景"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-005", "kp": "IVIM的双指数模型与参数含义", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】本题为反选题，B错误。IVIM恰恰需要密集采样多个b值（常10—16个，其中低b值段0—200 s/mm² 要足够密集），因为灌注相关的伪扩散D*衰减极快，只在低b段可见；仅用两个b值根本无法完成双指数分解，也就得不到D、D*、f三个参数。【为什么错】A正确描述了IVIM的核心模型：S(b)/S₀＝f·exp(−b·D*)＋(1−f)·exp(−b·D)，其中D*量级约为D的10倍以上，f为灌注分数。C正确：IVIM是无对比剂的灌注评估方法，这正是其相对DSC灌注的最大优势，尤其适用于肾功能不全者。D正确：常规ADC同时包含了灌注贡献而被抬高，去除灌注成分后的真扩散D通常小于ADC。E正确：IVIM在肝纤维化分级、肝细胞癌治疗反应评估、胰腺与前列腺病变中均有应用，并不局限于脑。", "tr": "本题为反选题（选错误项），先看清题干要求。记住D、D*、f的量级关系：D约0.5—2.0×10⁻³ mm²/s，D*约为D的10倍以上，f为百分数。腹部IVIM受呼吸运动与SNR限制，拟合稳定性有限，低b值采样密度是成败关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0133", "t": "单选题", "s": "扩散峰度成像（DKI）相对于常规DWI/DTI的核心假设改变是", "o": {"A": "承认生物组织内水分子扩散呈非高斯分布，用峰度参数（如平均峰度MK）描述偏离高斯的程度，因而需要更高b值（常含b＝2000 s/mm² 或更高）与至少三个b值", "B": "假设水分子扩散完全符合高斯分布，仅提高了空间分辨率", "C": "取消了扩散敏感梯度，改用相位编码检测扩散", "D": "只需b＝0与b＝1000两个b值即可计算峰度", "E": "峰度参数与组织微结构复杂程度无关"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-006", "kp": "扩散峰度成像（DKI）的基本假设", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。常规DWI/DTI建立在自由扩散（高斯分布）假设上，信号随b值单指数衰减；但真实组织中细胞膜、髓鞘、细胞器等障碍使扩散偏离高斯，在高b值段衰减曲线明显上翘。DKI在指数项中加入峰度校正项 ln S(b)＝ln S₀−b·D_app＋(1/6)·b²·D_app²·K_app，因此必须采集至少三个b值（典型0、1000、2000 s/mm²）与足够的扩散方向（常≥15个）才能稳定拟合，MK值升高提示微结构复杂度增加。【为什么错】B错误：DKI恰恰是放弃高斯假设，且它并未改变空间分辨率。C错误：DKI仍使用扩散敏感梯度，只是采样策略与拟合模型不同。D错误：两个b值只能确定单指数斜率，无法解出二次项。E错误：MK的临床意义正是反映组织微结构的复杂/异质程度，如胶质瘤分级、缺血半暗带评估中MK与病理级别相关。", "tr": "记住b值需求的层级：常规DWI两个b值即可；IVIM需要低b段密集采样；DKI需要高b值（≥2000）与多方向。高b值带来的代价是SNR下降与SAR/涡流增加，3.0T下常需并行采集与匀场配合。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0134", "t": "多选题", "s": "关于扩散张量成像（DTI）与纤维束示踪的技术要求，下列说法正确的有", "o": {"A": "求解一个三维扩散张量至少需要在6个非共线方向上施加扩散梯度并采集一幅b＝0图像；临床常用20—32个方向以提高张量估计的稳定性与各向异性测量精度", "B": "各向异性分数FA取值0—1，反映扩散方向性的一致程度；平均扩散率MD反映整体扩散幅度，二者是相互独立的信息", "C": "颅脑DTI常用b＝1000 s/mm²，b值过低则各向异性对比不足，过高则SNR下降使FA被噪声系统性高估", "D": "纤维束示踪在纤维交叉区域存在固有局限，单张量模型只能给出一个主方向，可能造成纤维束中断或错误连接", "E": "只要方向数足够多，DTI即可完全区分纤维交叉、扇形分散与穿行的复杂结构"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-007", "kp": "DTI方向数、b值与纤维束示踪局限", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确：张量为3×3对称矩阵，独立元素6个，故最少6方向；但噪声条件下方向数越多、方向分布越均匀，特征值/特征向量估计越稳定，临床常用20—32方向，研究可达64方向以上。B正确：FA描述“方向性”，MD描述“快慢”，二者可分离——例如水肿区MD升高而FA可正常或降低，肿瘤浸润区可表现为FA降低而MD轻度升高。C正确：b值需在扩散加权与SNR之间折中，b＝1000是脑白质的经典取值；低SNR时噪声本底会使最小特征值被抬高得相对少而使FA虚高，这是低SNR区（如脑干边缘）FA不可信的原因。D正确：单张量模型每个体素只有一个主特征向量，在放射冠等纤维交叉区（约占白质体素的1/3）会失效，需高角分辨扩散成像（HARDI）、球面反卷积或多张量模型改善。【为什么错】E错误：这是绝对化的过度承诺。方向数增加只能改善张量参数的估计精度，无法突破单张量模型本身的数学限制；解决交叉问题必须换模型而非仅加方向。", "tr": "E的陷阱在于混淆“采样密度”与“模型能力”。请牢记：6方向是数学下限而非临床推荐；FA在低SNR区会被高估；交叉纤维是DTI的模型级缺陷。术前脑功能定位报告应注明这一局限。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0135", "t": "案例分析题", "s": "患者女，9岁，烟雾病术后1年随访，需评估脑血流灌注情况，并计划此后每6个月复查一次。既往有钆剂使用史，家长强烈抵触再次注射对比剂；患儿肾功能正常，能配合安静躺卧约6 min。设备为飞利浦3.0T。关于灌注方案的选择与技术设置，最合理的是", "o": {"A": "选择动脉自旋标记（ASL），以动脉血中的水分子作为内源性示踪剂，无须钆剂、可重复测量；因烟雾病侧支循环迂曲致动脉通过时间延长，应适当延长标记后延迟时间（PLD，如由1.5 s延长至2.0—2.5 s）或采用多延迟ASL，否则会低估灌注并出现血管内高信号（动脉通过伪影）", "B": "必须选择动态磁敏感对比增强灌注（DSC），因为只有钆剂团注才能得到CBV、CBF、MTT、TTP全套参数，ASL无任何定量能力", "C": "选择DSC，但把钆剂剂量减半即可规避所有风险", "D": "选择动态对比增强（DCE）T1灌注，因为其对脑血流最敏感", "E": "不做灌注，仅用TOF-MRA评价血管形态即可完全替代灌注信息"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-008", "kp": "ASL与DSC灌注的原理差异与人群选择", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。ASL用射频脉冲反转标记流入动脉血中的水质子，作为可自由弥散的内源性示踪剂，采集标记像与对照像相减得到灌注加权图，可定量脑血流量CBF（mL/100 g/min）。其优势正契合本例：无对比剂、可无限次重复、适合儿童与需长期随访者。技术关键在于PLD——标记血流到达组织所需的时间在烟雾病、重度颈动脉狭窄、老年人中显著延长，PLD过短时标记血尚滞留于大血管内，表现为迂曲血管内的条状高信号（动脉通过伪影）而组织灌注被低估，因此应延长PLD或采用多PLD采集以同时获得动脉通过时间。【为什么错】B错误：ASL可定量CBF，这恰恰是它相对DSC（多为半定量相对值）的优点之一；DSC虽能给出CBV/MTT/TTP，但并非“唯一可定量”。C错误：减半剂量不解决“不愿使用对比剂＋需长期反复随访”的核心诉求，钆在脑组织的长期沉积问题在儿童反复检查中尤需谨慎。D错误：DCE基于T1弛豫率变化评估血管通透性（Ktrans等），主要用于肿瘤与血脑屏障评估，对脑血流的敏感性与时间分辨率不及DSC/ASL，且仍需钆剂。E错误：形态学正常不等于灌注正常，烟雾病的核心问题恰恰是侧支代偿是否充分，MRA不能回答该问题。", "tr": "本题的高阶考点是PLD。很多考生只记住“ASL不用打药”，却不知道PLD设置不当会造成系统性低估。经验值：健康成年人PLD约1.5—2.0 s，老年人与脑血管病患者2.0—2.5 s，儿童可略短（约1.5 s），但烟雾病等侧支循环病例应延长或改多延迟采集。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0136", "t": "多选题", "s": "某院开展静息态BOLD功能成像（rs-fMRI），下列技术设置与质量控制做法正确的有", "o": {"A": "采用梯度回波EPI序列，3.0T下TE通常设为约30 ms（与灰质T2*接近）以获得最大BOLD对比，1.5T则需延长至约40—50 ms", "B": "静息态扫描要求受试者清醒、闭眼或注视十字、不做系统性思维活动，采集时长通常需6—10 min以保证低频振荡（0.01—0.08 Hz）的统计功效", "C": "头动是rs-fMRI最主要的混杂因素，应通过泡沫垫/真空垫固定、扫描前充分沟通加以预防，并在后处理中做头动校正、回归头动参数，对逐帧位移超阈值的时间点予以剔除（scrubbing）", "D": "扫描前应嘱受试者避免入睡，睡眠会显著改变默认网络等静息态网络的连接模式", "E": "为提高信噪比应尽量延长TR至6 s以上，TR越长静息态数据质量越好"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-009", "kp": "静息态BOLD的参数设置与头动控制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确：BOLD对比来源于去氧血红蛋白引起的T2*效应，当TE≈组织T2*时BOLD信号变化最大；3.0T灰质T2*约30—40 ms，故取TE≈30 ms，1.5T的T2*更长故TE相应延长。B正确：静息态分析的是低频自发振荡的同步性，采样时长不足会导致相关系数估计不稳，一般不少于5—6 min，多数方案采用8—10 min。C正确：头动会同时改变体素内组织成分与自旋历史，产生虚假相关，是导致组间差异假阳性的首要原因；预防（固定＋沟通）优于校正，校正后仍需帧位移剔除。D正确：睡眠状态下默认网络的功能连接强度与网络构型明显改变，故须保持清醒并在扫描后询问确认。【为什么错】E错误：TR决定时间采样率，TR过长会使低频信号采样点稀疏、生理噪声（呼吸约0.3 Hz、心搏约1 Hz）严重混叠到低频段而无法有效剔除。静息态常用TR为2—3 s，采用同时多层（multiband/SMS）技术可缩短至0.5—1 s以改善生理噪声分离，方向与E相反。", "tr": "E利用“TR长＝信号足”的直觉。功能成像的TR是时间分辨率参数而非单纯的信噪比参数。另注意静息态与任务态的区别：任务态需按区组（block）或事件相关设计施加刺激并做时间锁定分析，TE设置相同但时长与范式不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0137", "t": "单选题", "s": "某任务态BOLD实验（手指运动区组设计）在3.0T上采集，技师为提高图像信噪比将TE由30 ms改为12 ms，其余参数不变。可以预期的结果是", "o": {"A": "单帧EPI图像的信噪比提高，但BOLD激活对比度显著下降、激活体素数明显减少，甚至无法检出激活区", "B": "BOLD对比度提高，激活区面积增大", "C": "对BOLD激活无影响，仅缩短扫描时间", "D": "会使激活区从运动皮层移位到感觉皮层", "E": "可完全消除颅底磁敏感伪影且不影响激活检出"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-010", "kp": "BOLD的TE依赖性与对比度—信噪比权衡", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。BOLD信号变化率可近似写为 ΔS/S ≈ −TE·ΔR2*，即激活引起的百分信号变化与TE成正比；当TE≈T2*时功能对比度—噪声比（CNR）达到峰值。把TE从30 ms（接近3.0T灰质T2*）压到12 ms，虽然横向弛豫衰减减少、单帧图像的绝对信噪比上升，但ΔS/S被压缩到原来的不足一半，统计检验中的激活体素数会大幅下降，弱激活区可能完全检不出。功能成像看重的是CNR而非单帧SNR，这是本题的核心逻辑。【为什么错】B方向说反，TE缩短使BOLD权重下降。C错误：TE缩短并不缩短扫描时间（TR与采集矩阵未变），且明确影响BOLD。D错误：TE改变的是对比度权重，不会造成解剖位置移位；空间位置错误应考虑几何变形、层间时间校正或配准问题。E错误：缩短TE确实能减轻T2*失相位造成的信号丢失（这也是短TE在颅底的唯一好处），但“完全消除”是绝对化表述，且以牺牲BOLD对比为代价，不能说“不影响激活检出”。", "tr": "本题考的是“SNR与CNR不是一回事”。同类逻辑还出现在：提高带宽降低SNR但减轻化学位移伪影；缩短TE提高SNR但降低T2权重。副高层面必须能识别参数调整的双向后果。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0138", "t": "单选题", "s": "关于磁敏感加权成像（SWI）的数据构成与图像生成流程，正确的是", "o": {"A": "采用三维扰相梯度回波（T1-FFE/FLASH/SPGR）流动补偿采集，同时得到幅值图与相位图；相位图经高通滤波去除背景场后生成相位掩模，与幅值图相乘（通常多次）增强磁敏感对比，再对若干层作最小密度投影（minIP）显示连续静脉", "B": "采用自旋回波序列采集，仅使用幅值图", "C": "相位图直接使用，无须去除背景场", "D": "生成SWI图时相位掩模与幅值图相加", "E": "SWI最终显示采用最大密度投影（MIP）以突出静脉"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-001", "kp": "SWI的采集与后处理流程", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确。SWI的四个要素缺一不可：①三维长TE梯度回波采集（3.0T常用TE约20 ms、1.5T约40 ms）保留T2*与相位信息，并加流动补偿避免血流相位误差；②高通滤波去除由空气—组织界面、匀场不良造成的大尺度背景相位；③把滤波后相位归一化为0—1的掩模，与幅值图相乘若干次（常4次）以放大顺磁性物质的低信号；④对连续8—16 mm层块作最小密度投影，使断续的小静脉在一幅图上连续显示。【为什么错】B错误：自旋回波的180°脉冲会重聚静态磁场不均匀，恰恰抵消了磁敏感效应，SWI必须用梯度回波。C错误：不去背景场则相位被大尺度不均匀主导、缠绕严重，无法反映局部磁化率。D错误：是相乘（加权）而非相加，相加不能形成非线性放大效应。E错误：静脉、出血、铁沉积均为低信号，突出低信号必须用minIP；MIP用于显示高信号的动脉（如TOF-MRA）。", "tr": "最常见的错误是把minIP写成MIP。判断口诀：SWI看的是“黑”，所以用最小密度投影；MRA看的是“亮”，所以用最大密度投影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0139", "t": "单选题", "s": "在基底节区同时见到SWI幅值图上的点状低信号，需要鉴别是钙化还是微出血。最可靠的技术判读方法是", "o": {"A": "参照校正后的相位图：顺磁性物质（去氧血红蛋白、含铁血黄素）与抗磁性物质（钙）产生方向相反的相位偏移，故在同一台设备的相位图上呈相反的信号极性；由于厂家采用右手或左手系统的约定不同，必须先用本机已知钙化病例（如脉络丛、松果体钙化）标定相位极性后再判读", "B": "在幅值图上比较低信号的绝对灰度值，越黑者为钙化", "C": "看病灶大小，直径小于5 mm者为微出血", "D": "在T1WI上钙化必为高信号、出血必为低信号，据此鉴别", "E": "在SWI最小密度投影图上钙化呈高信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-002", "kp": "SWI相位图鉴别钙化与出血", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确。钙为抗磁性（磁化率为负），铁相关产物为顺磁性（磁化率为正），二者在局部产生的磁场偏移方向相反，因而在校正后的相位图上呈相反极性——这是SWI相位图相对CT的独特价值。但相位的正负与显示灰阶取决于厂家的坐标系约定（右手系统与左手系统相反），不同厂家甚至同一厂家不同软件版本可能不同，因此临床上必须先用生理性钙化（松果体、脉络丛、大脑镰）在本机上标定“钙化是亮还是暗”，再据此判读病灶，这也是许多误判的根源。【为什么错】B幅值图上钙化与出血都是低信号，灰度深浅受体积、TE、部分容积影响，不具鉴别力。C大小与性质无关，微出血与点状钙化尺寸重叠。D错误：钙化在T1WI上信号多变（可高可低，取决于钙的结晶形式与含水量），出血信号更随时间演变（超急性、急性、亚急性、慢性各不相同），此规律不成立。E错误：minIP进一步强调低信号，钙化在其上仍为低信号；且minIP会加重开花效应（blooming），更不适合定性。", "tr": "陷阱是死记“钙化在相位图上是亮的”。正确答法必须包含“取决于右手/左手系统，需本机标定”。若要求确切定量鉴别，可加做QSM——QSM给出的磁化率数值有正负号，钙为负值、铁为正值，不依赖显示约定。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0140", "t": "多选题", "s": "关于SWI、定量磁化率成像（QSM）与T2* mapping三项磁敏感相关技术的比较与应用，下列说法正确的有", "o": {"A": "SWI对脑内微出血、弥漫性轴索损伤的点状出血、海绵状血管瘤的“爆米花”样含铁血黄素环显示极为敏感，检出率显著高于常规T2*WI与T2WI", "B": "SWI存在“开花效应”（blooming），病灶显示尺寸随TE延长而放大，因此不能用于病灶大小的准确测量", "C": "QSM通过求解由磁化率分布到相位分布的偶极子卷积逆问题，直接给出以ppm为单位的组织磁化率定量值，克服了相位图非局部效应与SWI不可定量的缺点，可用于苍白球、黑质等核团铁含量的纵向定量", "D": "T2* mapping采集同一激发下的多个回波，对各回波信号按单指数拟合逐像素求出T2*，可换算为R2*（R2*＝1000/T2*，T2*以ms为单位时R2*单位为s⁻¹），用于心肌、肝脏铁沉积的定量", "E": "急性期蛛网膜下腔出血在SWI上无任何表现，SWI对出血的检出仅限于脑实质内"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-003", "kp": "SWI、QSM与T2* mapping的比较", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确：这三类病变的共同基础是含铁血黄素/去氧血红蛋白的顺磁性，SWI的相位加权把微弱磁化率差异放大，检出微出血的数量常为常规GRE的2倍以上。B正确：开花效应源于顺磁性物质周围的局部磁场外溢范围大于其解剖边界，且随TE延长而扩大，故SWI适合“检出”不适合“测量”，测量应参考T2WI或QSM。C正确：QSM把相位这一非局部量反演为局部磁化率，数值有正负号（顺磁为正、抗磁为负），是目前脑铁纵向随访的首选定量工具。D正确：多回波GRE的T2*拟合是铁定量的基础，R2*与组织铁浓度近似线性相关，临床报告心肌与肝脏铁负荷时常用R2*或T2*两种表述。【为什么错】E错误：急性蛛网膜下腔出血在SWI上可表现为脑沟、脑池内的线样/铸型低信号，对少量出血甚至比CT更敏感；SWI对脑室内出血、硬膜下少量出血同样敏感，并非仅限脑实质。", "tr": "B与C构成一对：SWI“敏感但不定量、且夸大尺寸”，QSM“定量且尺寸真实”。E是方向性错误陷阱。另注意SWI的局限：颅底与鼻窦旁磁敏感伪影重、对运动敏感（三维长TE采集）、扫描时间较长。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0141", "t": "案例分析题", "s": "患者男，24岁，重型β地中海贫血，规律输血14年，口服祛铁治疗中，临床要求评估心肌与肝脏铁负荷以指导祛铁方案。设备为飞利浦3.0T，患者心率78次/分、律齐，可屏气约15 s。技师拟行心脏T2* mapping。下列技术执行与判读要点，最恰当的是", "o": {"A": "采用心电门控、单次屏气的多回波扰相梯度回波序列采集左室中段短轴层面（通常8个回波，TE自约2 ms起以约2 ms递增），在室间隔中段全层厚勾画ROI（避开心内膜面血池、心外膜脂肪与心大静脉），按单指数拟合T2*；判读阈值为T2*>20 ms正常、10—20 ms提示中度铁沉积、<10 ms提示重度铁过载且心力衰竭与恶性心律失常风险显著升高；肝脏铁负荷另行采集肝脏多回波序列，不能用心脏值代替", "B": "采用自旋回波T2WI测量心肌信号强度与骨骼肌之比即可判断铁负荷，无须T2* mapping", "C": "选择左室心尖部层面并在整个左室游离壁勾画ROI，以获得最大代表性", "D": "由于心脏与肝脏铁沉积程度一致，只需扫肝脏T2*并据此推算心肌铁负荷", "E": "T2*值越大表示铁沉积越重，故T2*<20 ms提示铁负荷正常"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-004", "kp": "心脏T2* mapping铁过载定量", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确，四个要点均为国际公认做法。①层面与序列：心电门控多回波GRE、单次屏气采集左室中段短轴，避免不同回波间的呼吸位移导致拟合失败。②ROI：固定取室间隔中段全层厚，因为室间隔远离心脏静脉、肺组织与心外膜脂肪，磁敏感干扰最小、可重复性最好；侧壁与心尖受心大静脉、肺—心界面影响，测值不可靠。③拟合：逐像素或ROI均值按 S(TE)＝S₀·exp(−TE/T2*) 单指数拟合；重度铁过载时后段回波已进入噪声本底，须采用截尾法（truncation）或带常数项的模型，否则T2*被系统性高估。④阈值：T2*>20 ms正常，10—20 ms中度，<10 ms重度并与心功能不全、心律失常风险显著相关，是启动强化祛铁的关键指征。⑤心、肝铁需分别测量。【为什么错】B自旋回波的180°脉冲重聚了静态场不均匀，对铁的敏感性远低于T2*，信号比值法早已被T2*定量取代。C心尖与游离壁易受心大静脉、肺界面与部分容积影响，且心尖层厚薄、运动大，不是标准测量位置。D错误：心肌与肝脏的铁沉积动力学不同步——肝铁上升更早、下降也更快，而心肌铁往往滞后数年，二者不可互相推算，这正是必须分别测量的临床理由。E把方向说反：铁沉积使T2*缩短，值越小越重。", "tr": "本题四重陷阱：①测量位置（必须室间隔中段，不是游离壁/心尖）；②方向（T2*越短越重，不是越长越重）；③心肝不可互推；④重度铁过载时的拟合截尾问题。另注意3.0T下T2*值系统性短于1.5T，公认的20 ms/10 ms阈值建立于1.5T，3.0T测量需使用本机校准或按厂家/文献换算后报告。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0142", "t": "单选题", "s": "某科室开展肝脏T2* mapping用于铁沉积定量，技师设置多回波梯度回波序列时，下列参数取舍最合理的是", "o": {"A": "采用单次屏气的多回波（≥6个回波）采集，首个TE尽可能短（约1 ms左右）、回波间隔尽量小，翻转角取较小值（约20°以下）以减少T1权重污染，并保证所有回波在同一屏气内完成", "B": "采用两个回波即可满足拟合要求，回波间隔取10 ms", "C": "翻转角越大越好，可提高信噪比从而提高拟合精度", "D": "各回波可在不同屏气中分次采集，只要嘱患者屏气位置一致即可", "E": "首个TE应尽量长（>15 ms），以增强铁的磁敏感效应"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-005", "kp": "多回波T2* mapping的参数设置", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确。①回波数与间隔：重度铁过载时肝T2*可短至1—2 ms，若首个TE太长或间隔太大，信号在第一个采样点前就已衰减殆尽，衰减曲线无法采到有效点，必然低估铁负荷；因此首个TE要尽可能短、回波间隔尽可能密，回波数≥6以保证拟合自由度。②翻转角：T2* mapping希望信号纯粹反映T2*衰减，大翻转角会引入明显T1权重，尤其在短TR下造成偏倚，故取小翻转角（一般≤20°）。③同一屏气：多回波必须在同一次激发的回波链中获得，且整段采集在一次屏气内完成，否则不同回波间的位置错动会使逐像素拟合失效。【为什么错】B两个回波只能算出一个斜率、无法评估拟合优度，也无法识别噪声本底与脂肪引起的信号振荡；10 ms间隔对重度铁过载完全无法采样。C大翻转角引入T1污染，且并不改善T2*拟合的核心问题，属于把“信噪比”与“定量准确性”混为一谈。D分次屏气会导致层面错位与逐像素配准失败，是定量图出现斑驳伪影的常见原因。E方向说反：长TE只会丢失短T2*组织的信号，正确策略是尽早、尽密采样。", "tr": "记住定量序列的通用原则：短TE起步、密集采样、小翻转角去T1、一次屏气保证配准。此外肝脏常合并脂肪变，脂肪与水的化学位移会使信号随TE呈周期性振荡，应选用同相位回波间隔（1.5T约4.6 ms、3.0T约2.3 ms）或采用含脂肪模型的拟合，否则T2*/R2*结果失真。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0143", "t": "单选题", "s": "脑1H-MRS谱线中，各代谢物的化学位移（ppm）定位正确的一组是", "o": {"A": "NAA 2.02，Cr 3.03，Cho 3.22，Lac 1.33（双峰），Lip 0.9—1.3", "B": "NAA 3.22，Cr 2.02，Cho 3.03，Lac 3.56，Lip 2.6", "C": "NAA 1.33，Cr 0.9，Cho 2.02，Lac 3.03，Lip 3.22", "D": "NAA 3.03，Cr 3.22，Cho 2.02，Lac 2.6，Lip 1.48", "E": "NAA 2.6，Cr 1.33，Cho 0.9，Lac 3.22，Lip 3.03"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-001", "kp": "脑1H-MRS主要代谢物的化学位移", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确。脑质子波谱由高场（左）向低场（右）的常规排列（横轴ppm从右向左递减）依次为：Cho 3.22 ppm（胆碱复合物，细胞膜代谢）、Cr 3.03 ppm（肌酸/磷酸肌酸，能量代谢，常作内参）、NAA 2.02 ppm（N-乙酰天门冬氨酸，神经元完整性标志）、Lac 1.33 ppm（乳酸，J耦合双峰）、Lip 0.9—1.3 ppm（脂质，坏死或细胞膜崩解）。另需记住肌醇mI 3.56 ppm、Glx 2.1—2.5 ppm、Ala 1.48 ppm（双峰）、前列腺枸橼酸盐Cit约2.6 ppm。【为什么错】B、C、D、E均为峰位随机错置，与实际谱线不符。可用“3.22胆碱、3.03肌酸、2.02NAA、1.33乳酸”这一由高到低的顺序自查。", "tr": "最易混的是Cho（3.22）与Cr（3.03）——两峰相距仅0.19 ppm，谱线上紧邻，若匀场不良（线宽增大）二者会融合成一个宽峰，导致Cho/Cr比值失真。记忆顺序口诀：“胆—肌—N—乳—脂”，ppm由大到小。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0144", "t": "单选题", "s": "关于单体素MRS中PRESS与STEAM两种定位方式的比较，正确的是", "o": {"A": "PRESS为90°—180°—180°三脉冲自旋回波定位，理论信噪比约为STEAM的2倍，但最短可实现TE较长；STEAM为三个90°脉冲的受激回波定位，可实现很短的TE（有利于检测短T2代谢物如肌醇、谷氨酸复合物），但信号仅为PRESS的一半且对运动与扩散更敏感", "B": "STEAM信噪比约为PRESS的2倍，PRESS只能用于长TE", "C": "两者信噪比相同，仅脉冲顺序不同", "D": "PRESS采用三个90°脉冲，STEAM采用90°—180°—180°", "E": "STEAM不需要水抑制，PRESS需要"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-002", "kp": "PRESS与STEAM的技术差异", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确。PRESS用一个90°激发加两个180°重聚焦脉冲，三者层面正交相交定义体素，全部横向磁化被重聚，信号约为STEAM的2倍；但两个180°脉冲需要时间且SAR高，最短TE通常在30 ms左右（3.0T可更短但受限）。STEAM用三个90°脉冲形成受激回波，只有一半磁化贡献信号，但脉冲短、SAR低，最短TE可低至10 ms以下，适合检测J耦合复杂、T2较短的代谢物（mI、Glx、GABA），代价是SNR低、对运动与扩散敏感、需更多平均次数。【为什么错】B完全颠倒。C错误：脉冲组合直接决定了可用磁化的比例，SNR相差约一倍。D把两者的脉冲结构互换。E错误：无论PRESS还是STEAM，水峰浓度比代谢物高约万倍，都必须使用水抑制（如CHESS）与外容积饱和带，缺一不可。", "tr": "记忆抓手：PRESS＝“Point RESolved Spin echo”，有180°故信号全、TE长；STEAM＝“STimulated Echo”，三个90°故信号半、TE短。临床上脑常规MRS多用PRESS（TE 35 ms与144 ms各一套），需要短TE定量代谢物时选STEAM。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0145", "t": "多选题", "s": "关于MRS采集中匀场与水抑制的技术要求，下列说法正确的有", "o": {"A": "匀场质量通常用水峰半高全宽（FWHM）衡量，线宽越窄谱线分辨率越高；线宽过大时Cho（3.22 ppm）与Cr（3.03 ppm）会相互重叠而无法准确定量", "B": "组织内水的浓度约为代谢物的10⁴倍，若不抑制水信号，代谢物峰将被水峰及其旁瓣完全淹没，故必须施加化学位移选择性水抑制（如CHESS）", "C": "体素应尽量避开颅骨内板、鼻窦、乳突气房、术后金属与出血区，这些部位的磁化率突变会严重破坏局部场均匀性", "D": "在体素周围施加外容积饱和带（OVS）可抑制颅骨骨髓与头皮脂肪信号沿化学位移方向渗入体素造成的巨大脂质峰污染", "E": "只要使用了自动匀场功能，无论体素位置如何都可获得合格谱线，无须人工复核线宽"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-003", "kp": "匀场、水抑制与外容积饱和", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确：MRS的谱分辨率完全由B₀均匀性决定，一般要求水峰FWHM在1.5T约<8—10 Hz、3.0T约<10—15 Hz；线宽变大会使相邻峰融合，Cho/Cr、NAA/Cr比值随之失真。B正确：水与代谢物浓度相差约四个数量级，必须用频率选择性脉冲加扰相梯度反复抑制水信号，抑制不足会出现巨大水峰与基线扭曲。C正确：磁化率突变区是匀场的天敌，颞叶前部、额叶眶回、颅底与术区常无法获得合格谱线，选体素时应主动回避。D正确：头皮与颅骨骨髓脂肪的信号可通过化学位移误配准渗入体素，形成0.9—1.3 ppm的巨大脂质峰，掩盖乳酸峰，OVS（八个方向的饱和带）是标准对策。【为什么错】E错误：自动匀场只是起点，操作者必须复核水峰线宽与水抑制效率，不合格时应重新调整体素位置或改用高阶匀场、手动匀场。把质量控制完全交给自动化是MRS失败谱的常见原因。", "tr": "E是典型的“自动化依赖”陷阱。实操要点：先看线宽，再看水抑制，再看基线；三者任一不合格，谱线即不可用于定量。另注意脂质峰与乳酸峰均位于1.3 ppm附近，脂质污染会直接导致乳酸判读错误，此时可用TE＝144 ms观察峰是否倒置来区分。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0146", "t": "单选题", "s": "在1.5T脑MRS中，若在1.3 ppm附近观察到一个明显的峰，为判断它是乳酸（Lac）而非脂质（Lip），最有效的技术手段是", "o": {"A": "把TE设为约135—144 ms再采集一次：乳酸为J耦合双峰，在该中间TE下发生相位反转呈倒置峰，而脂质峰始终朝上", "B": "把TE缩短至30 ms，此时乳酸峰会消失", "C": "增加平均次数即可区分", "D": "改用STEAM定位，乳酸峰会移位到2.0 ppm", "E": "增强扫描后重复MRS，乳酸峰会强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-004", "kp": "乳酸峰的J耦合倒置判别", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确。乳酸的甲基质子与相邻次甲基质子存在标量（J）耦合，J约7 Hz，其双峰的相对相位随TE周期性变化：在TE≈1/J（约135—144 ms）时两个分量反相叠加，使整个双峰在谱线上倒置于基线以下；而脂质是无J耦合调制的宽峰，无论TE长短始终为正峰。因此临床脑MRS常规同时采集短TE（30—35 ms，观察mI、Glx、Lip）与中间TE（135—144 ms，鉴别Lac、简化基线）两套谱。【为什么错】B错误：短TE下乳酸峰不但不消失，反而与脂质峰重叠更难区分，这正是需要中间TE的原因。C错误：平均次数只提高信噪比，不改变峰的相位特性。D错误：化学位移由分子结构决定，不随定位序列改变；改用STEAM不会使乳酸移位。E错误：MRS测的是代谢物浓度，钆剂不会使乳酸“强化”，反而可能因缩短T1、破坏匀场而干扰谱线，故MRS原则上应在增强前采集。", "tr": "两个衍生考点：①丙氨酸（Ala）1.48 ppm同为双峰，在中间TE下也倒置，见于脑膜瘤；②MRS应安排在注射钆剂之前，注射后Cho峰可被压低而造成假阴性，这是临床流程中最易被忽视的顺序问题。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0147", "t": "多选题", "s": "关于多体素波谱成像（化学位移成像CSI）与前列腺MRS，下列说法正确的有", "o": {"A": "多体素CSI在一次采集中用相位编码把感兴趣层面或容积划分为多个体素，可获得代谢物的空间分布图（代谢图），便于观察肿瘤的异质性与选择活检靶点", "B": "与单体素相比，多体素CSI采集时间更长、对匀场范围要求更高，且相邻体素间存在信号污染（点扩散函数导致的体素间串扰）", "C": "正常前列腺外周带上皮细胞可分泌并富集枸橼酸盐（Cit，约2.6 ppm），前列腺癌区Cit明显降低而Cho升高，故以(Cho＋Cr)/Cit比值升高作为提示恶性的指标", "D": "前列腺MRS对匀场与脂肪抑制要求极高，直肠气体与粪便造成的磁化率不均匀是失败的主要原因，检查前清洁肠道、直肠内置线圈或使用直肠球囊有助改善", "E": "在PI-RADS v2.1评分体系中，MRS已被列为与T2WI、DWI并列的核心序列之一"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-005", "kp": "多体素CSI与前列腺MRS", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确：CSI用相位编码实现空间定位，输出可叠加于解剖图的代谢伪彩图，胶质瘤分级、放射性坏死与复发鉴别、活检靶点选择均受益。B正确：相位编码步数决定采集时间，体素数增加则时间成倍延长；同时匀场需覆盖更大范围，难度更高；有限采样导致的点扩散函数使邻近体素信号相互渗漏，靠近颅骨的体素常被脂质污染。C正确：Cit是前列腺特有的代谢标志，癌变时上皮细胞由分泌型转为氧化代谢型，Cit减少而细胞膜代谢活跃使Cho升高，比值升高提示恶性。D正确：直肠气体与前列腺的界面磁化率差异极大，是前列腺MRS匀场失败最常见的原因。【为什么错】E错误：PI-RADS v2.1的核心序列是T2WI、DWI/ADC与DCE，MRS并未纳入评分体系。事实上由于操作复杂、耗时长、可重复性受限，前列腺MRS在临床常规中的应用已明显减少，多参数MRI以T2WI＋DWI＋DCE为标准组合。", "tr": "E是时效性陷阱——早年教材把MRS列为前列腺“多参数”之一，但现行PI-RADS v2.1已不包含MRS。答题时要按现行标准。另注意CSI体素越小SNR越低，实际前列腺CSI体素常为0.3—0.5 cm³，脑CSI常为1—2 cm³。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0148", "t": "单选题", "s": "关于化学位移选择性脂肪抑制（FatSat/CHESS、SPIR、SPAIR）的原理与特点，正确的是", "o": {"A": "利用水与脂肪约3.5 ppm的化学位移差（1.5T约220 Hz、3.0T约440 Hz），用窄带频率选择性射频脉冲单独激发并扰相破坏脂肪信号；场强越高频率间隔越大、抑制越容易，但对B₀不均匀与大FOV边缘仍很敏感", "B": "利用水与脂肪的T1差异，与化学位移无关", "C": "场强越低频率间隔越大，故0.35T比3.0T更易实现化学位移选择性脂肪抑制", "D": "SPAIR与SPIR的区别在于SPAIR不需要频率选择性", "E": "化学位移选择性脂肪抑制不受金属植入物影响"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAT-001", "kp": "化学位移选择性脂肪抑制原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】A正确。脂肪中亚甲基质子与水质子的共振频率相差约3.5 ppm，绝对频率差＝3.5×10⁻⁶×γB₀，1.5T约220 Hz、3.0T约440 Hz。频率选择性饱和用中心频率对准脂肪峰的窄带脉冲把脂肪磁化翻转后立即扰相破坏，随后再施加成像序列，此时脂肪无纵向磁化可用故呈低信号。场强越高频率间隔越大，窄带脉冲更易把水脂分开，因此3.0T的化学位移脂肪抑制通常优于1.5T；但其致命弱点是依赖B₀均匀性，在大FOV边缘、颈肩交界、乳腺外侧、金属附近会出现脂肪抑制不全或误抑制水。【为什么错】B错误：这是STIR的机制（依赖T1差异），化学位移法依赖频率差异。C完全说反：频率差与场强成正比。D错误：SPAIR同样是频率选择性的，其特点是使用绝热反转脉冲，对B₁（射频场）不均匀更耐受、抑制更均匀，代价是SAR更高、扫描时间稍长。E错误：金属附近B₀严重畸变，脂肪峰频率偏移，窄带脉冲反而可能误饱和水或完全失效，此时应改用STIR或Dixon类方法。", "tr": "三种脂肪抑制的适用逻辑：化学位移法（SPIR/SPAIR/FatSat）——高场、小FOV、匀场好时首选，且可用于增强后；STIR——匀场差、金属植入、大FOV时可靠，但不能用于增强后；Dixon——兼顾均匀性与增强后使用，代价是最小TE与重建复杂度。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0149", "t": "单选题", "s": "临床上强调注射钆对比剂后不宜使用STIR序列作为脂肪抑制手段，其根本原因是", "o": {"A": "STIR采用非选择性反转恢复，其抑制依据是“T1值接近脂肪”而非“属于脂肪”；强化后病灶T1明显缩短并可能接近脂肪的T1，从而被一并抑制，造成强化灶信号丢失甚至假阴性", "B": "STIR的SAR过高，增强后不能使用", "C": "钆剂会改变脂肪的化学位移", "D": "STIR序列扫描时间长，增强后对比剂已廓清", "E": "STIR在增强后会产生水脂互换伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAT-002", "kp": "STIR在增强后的禁用理由", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】A正确。STIR用非选择性180°反转脉冲把所有组织的纵向磁化反转，再在脂肪磁化过零点（TI≈0.693×T1脂肪）时激发，此刻脂肪信号为零。它抑制的判据是T1值，凡T1接近脂肪者都会被抑制。注射钆剂后，强化组织（肿瘤、炎症、脑膜、血管）的T1被大幅缩短，可能落入脂肪的T1窗口内而被误抑制，导致本应显著强化的病灶反而变暗，形成灾难性的假阴性。因此增强后需要脂肪抑制时应选择化学位移法（SPIR/SPAIR）或Dixon水像。【为什么错】B STIR的SAR确实高于常规SE（多一个180°反转脉冲），但这不是增强后禁用的“根本原因”，平扫时同样面临SAR问题。C错误：化学位移由分子结构决定，钆剂不会改变脂肪的共振频率。D错误：细胞外间隙钆剂在数分钟内仍维持相当浓度，扫描时间不是核心矛盾。E错误：水脂互换是Dixon类相位解算方法的特征性伪影，与STIR无关。", "tr": "记住一句话：STIR抑制的是“T1像脂肪的东西”，不是“脂肪”。同样的道理还解释了另外两个现象：亚急性血肿（高铁血红蛋白T1短）在STIR上可被误抑制；含蛋白的黏液、钆剂外渗区也可被误抑制。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0150", "t": "多选题", "s": "关于Dixon水脂分离技术（两点法、三点法、mDIXON）的优势与伪影，下列说法正确的有", "o": {"A": "一次采集即可同时输出水像、脂像、同相位像与反相位像四组图像，无须重复扫描，对比信息更完整", "B": "其脂肪抑制基于水脂进动频率差引起的相位差，对B₀不均匀的耐受性明显优于化学位移选择性饱和，适用于大FOV（如全脊柱、颈胸交界、乳腺双侧）与金属附近的成像", "C": "Dixon类方法可在增强后使用，且水像的脂肪抑制均匀性通常优于SPIR/SPAIR", "D": "水脂互换（fat-water swap）是Dixon的特征性伪影，表现为图像局部或整幅的水像与脂像内容对调，多因B₀不均匀致相位解卷绕失败，常见于视野边缘、金属旁与磁场畸变区；对策包括改善匀场、缩小FOV、增加回波数或重新运行相位解算重建", "E": "Dixon技术完全不受B₀不均匀影响，因此在任何情况下都不会出现脂肪抑制失败"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAT-003", "kp": "Dixon水脂分离的优势与水脂互换伪影", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】A正确：这是Dixon最实用的优势——同一次采集得到四组图像，反相位像还可用于检出少量脂肪（肾上腺腺瘤、脂肪肝、含脂病变），信息密度高。B正确：Dixon利用相位差而非绝对频率位置，配合场图估计可容忍相当程度的B₀漂移，故在颈胸交界、双侧乳腺、金属内固定附近等匀场困难处优于窄带饱和法。C正确：Dixon不依赖T1，增强后使用不会误抑制强化组织，是增强后脂肪抑制的优选之一。D正确：水脂互换是解相位方程时把水解成脂、脂解成水，可局部发生（一块区域黑白翻转）或整幅翻转，识别方法是看皮下脂肪层在“水像”上是否异常明亮。【为什么错】E错误：“完全不受影响”是绝对化表述。当B₀畸变超过算法可解范围（如大块金属、严重匀场失败）时，Dixon同样会失败并以水脂互换的形式表现出来——D与E自相矛盾，E必错。", "tr": "D与E构成一对互斥选项，是识别答案的快速切入点。另需记住同/反相位的回波时间：1.5T同相位约4.6 ms、反相位约2.3 ms；3.0T同相位约2.3 ms、反相位约1.15 ms，回波间隔随场强反比缩短。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0151", "t": "单选题", "s": "关于反转恢复类序列的反转时间（TI）设置，下列组合正确的是", "o": {"A": "3.0T脑T2-FLAIR抑制脑脊液的TI约2200—2500 ms（配合TR 9000—11000 ms）；STIR抑制脂肪的TI在1.5T约150—170 ms、在3.0T约200—250 ms", "B": "3.0T FLAIR的TI约150 ms，STIR的TI约2500 ms", "C": "TI与场强无关，1.5T与3.0T可使用完全相同的TI", "D": "STIR的TI应设为脂肪T1的两倍", "E": "FLAIR的TR可任意设置，与TI无关"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-PREP-001", "kp": "FLAIR与STIR的反转时间设置", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A正确。反转恢复的抑制原理是在目标组织纵向磁化过零点时施加激发脉冲，理论TI≈0.693×T1（当TR足够长、磁化完全恢复时）。脑脊液T1很长（3.0T约4000—4500 ms），故FLAIR需要很长的TI（约2200—2500 ms）与相应更长的TR（9000—11000 ms）以保证零点计算成立。脂肪T1很短（1.5T约250 ms、3.0T约370 ms），故STIR的TI仅一两百毫秒；因组织T1随场强升高而延长，3.0T的STIR-TI要相应加长至约200—250 ms。【为什么错】B把两者的TI完全对调。C错误：T1值随B₀升高而延长（脂肪、脑脊液、白质均如此），TI必须随场强重新标定，这是1.5T协议直接搬到3.0T后抑制失败的常见原因。D错误：应为约0.693倍T1而非两倍。E错误：TR若不足够长，反转前的纵向磁化未充分恢复，实际零点会前移，TI必须相应缩短；FLAIR的长TR正是为配合长TI而设，二者强相关。", "tr": "牢记两条关系：①TI≈0.693×T1（长TR条件下）；②所有组织的T1随场强升高而延长，故换场强必须换TI。临床上3.0T FLAIR若沿用1.5T的TI，会出现脑脊液抑制不全、脑室边缘残留高信号。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0152", "t": "多选题", "s": "关于空间预饱和带（saturation band）的临床用途，下列说法正确的有", "o": {"A": "在颈椎矢状面成像时于咽喉部前方施加饱和带，可减轻吞咽运动与颈前血管搏动沿相位编码方向产生的鬼影", "B": "在腹部成像时于腹壁前方施加饱和带，可减轻呼吸运动伪影", "C": "在TOF-MRA中作为流动饱和带，选择性抑制来自某一方向的血流以分离动脉与静脉", "D": "饱和带位置应放在伪影源所在的位置，而不是随意放置；饱和带越多SAR越高，须权衡", "E": "饱和带可以消除已经采集完成的图像上的运动伪影，属于后处理技术"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-PREP-002", "kp": "空间预饱和带的用途", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A正确：运动伪影沿相位编码方向传播，把运动源（咽喉、颈前血管）的信号预先饱和掉，鬼影自然减弱。B正确：腹壁皮下脂肪是呼吸运动伪影最强的信号源，前腹壁饱和带是腹部与脊柱成像的常规配置。C正确：这正是TOF中区分动静脉的手段——抑制哪支血管就把饱和带置于其流入侧。D正确：饱和带必须准确覆盖伪影源；每个饱和带都是一次额外的射频脉冲，会增加SAR并可能占用TR内的时间而减少可采层数。【为什么错】E错误：饱和带是采集前施加的预脉冲，属于采集技术而非后处理；一旦数据采集完成，饱和带无法追加。真正的后处理去伪影手段是运动校正配准、鬼影抑制算法等。", "tr": "E混淆了“预脉冲”与“后处理”。要点：凡带“pre-”“预”字样（预饱和、预反转、磁化传递预脉冲）都发生在读出之前，必须在扫描前设置好。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0153", "t": "单选题", "s": "行心肌延迟强化（LGE）扫描时，需先运行TI scout（Look-Locker）序列。关于其目的与判读，正确的是", "o": {"A": "Look-Locker在一次采集中获得一系列不同TI的图像，操作者从中挑选正常心肌信号被抑制到最低（“变黑”）时对应的TI用于LGE；该TI随注药后时间延长而逐渐增大，需在采集过程中适时复测，若使用相位敏感反转恢复（PSIR）重建则对TI选择的容错性明显提高", "B": "Look-Locker用于寻找使瘢痕心肌信号最低的TI", "C": "Look-Locker用于测量心率以设置门控", "D": "TI一旦确定，在整个延迟强化采集过程中恒定不变，无须调整", "E": "TI选择错误只影响图像美观，不影响瘢痕的检出"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-PREP-003", "kp": "心肌延迟强化的TI scout与PSIR", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A正确。LGE的对比逻辑是“把正常心肌压黑、让瘢痕亮起来”，因此必须使正常心肌处于反转恢复的零点。Look-Locker（TI scout）在单次屏气内以递增TI连续采集同一层面，操作者目视选择正常心肌最黑的那一帧对应的TI。随着钆剂从血池与心肌中不断廓清，组织T1逐渐回升，零点TI随之延长（注药后10 min与20 min可相差数十毫秒），故在多层面采集过程中应间隔复测。PSIR重建利用相位信息恢复反转磁化的正负号，即使TI偏离最佳值仍能保持瘢痕—正常心肌的极性对比，显著降低对TI精度的依赖，尤其适合屏气差或需要长时间采集的患者。【为什么错】B错误：目标是抑制正常心肌而非瘢痕；瘢痕因细胞外间隙扩大、钆浓度高、T1短，在正常心肌被抑制时呈明亮高信号。C错误：心率由心电门控获取，Look-Locker不是测心率的工具。D错误：TI必须随时间调整，这是LGE质量控制的关键环节。E错误：TI偏短会使正常心肌呈现反相的“过黑”并可能反转对比，TI偏长则正常心肌变灰、瘢痕对比下降，小面积心内膜下瘢痕可被漏诊，直接影响诊断而非美观问题。", "tr": "本题核心是“抑制谁”。同类逻辑还有：黑血双反转抑制的是流动的血液，脂肪抑制反转恢复抑制的是脂肪，FLAIR抑制的是脑脊液——反转恢复类技术的第一问永远是“把哪种组织放到零点”。另注意PSIR并非可以随意乱设TI，仍应尽量接近零点以获得最佳信噪比。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0154", "t": "单选题", "s": "采用并行采集技术（SENSE/GRAPPA/ARC）时，关于其原理与代价的说法正确的是", "o": {"A": "利用多通道相控阵线圈各单元空间灵敏度的差异替代部分相位编码步，加速因子R使采集时间缩短约R倍，而信噪比按 1/(g·√R) 下降，其中几何因子g≥1，取决于线圈单元的排布与加速方向", "B": "并行采集通过提高梯度切换率缩短扫描时间，与线圈无关", "C": "加速因子可无限增大，只要线圈通道数足够", "D": "并行采集会提高信噪比，因此是纯粹的收益", "E": "SENSE在K空间域重建，GRAPPA在图像域重建"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-AUX-001", "kp": "并行采集的加速因子、g因子与SNR代价", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A正确。并行采集在相位编码方向上按因子R欠采样，产生的卷褶用各线圈单元已知的灵敏度分布解开。信噪比损失有两部分：欠采样使采集数据量减少，SNR降低√R倍；线圈灵敏度分布的相似性导致方程组病态，引入几何因子g（g≥1，线圈几何越不利、加速方向与线圈排布越不匹配、g越大），合成后SNR≈SNR₀/(g·√R)。【为什么错】B错误：并行采集靠的是线圈的空间信息，不是梯度性能；它恰恰是在梯度性能已达生理与工程极限时的提速途径。C错误：加速因子受线圈单元数、单元在加速方向上的排列与g因子急剧上升的共同限制，通常R不超过线圈在该方向的有效单元数，实际临床多用R＝2—4；过高会出现残余卷褶带与噪声放大。D错误：并行采集是以SNR换时间，绝非“纯粹收益”；只有在SNR冗余充足（如3.0T、大体素、多次平均）时才适合高加速。E错误：正好说反——SENSE在图像域解卷褶，GRAPPA/ARC在K空间域拟合缺失行。", "tr": "E的域向记忆抓手：SENSE的S可联想“Sensitivity in image space”，GRAPPA属自校准K空间方法（需采集自动校准中心行ACS）。两者的伪影表现也不同：SENSE失败表现为图像中央的条带状残余卷褶，GRAPPA失败表现为弥漫性噪声与波纹。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0155", "t": "多选题", "s": "关于压缩感知（compressed sensing, CS）在MRI中的应用，下列说法正确的有", "o": {"A": "其三个必要条件是：图像在某个变换域（如小波、有限差分/全变分）中可稀疏表示、采用非相干（近似随机）欠采样使伪影呈噪声样弥散、以及非线性迭代重建算法求解", "B": "CS与并行采集的加速机制互补，可联合使用（如CS-SENSE），在同等图像质量下获得比单纯并行采集更高的净加速倍数", "C": "过高的CS加速倍数会导致图像过度平滑、纹理丢失与低对比小病灶的检出率下降，因此加速倍数应结合部位与临床问题设定并做本机验证", "D": "CS特别适合本身具有高度稀疏性或冗余度的数据，如三维各向同性采集、动态多时相采集（4D CE-MRA、心脏电影）与波谱成像", "E": "CS重建为线性运算，重建时间与常规傅里叶重建基本相同"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-AUX-002", "kp": "压缩感知的三要素与临床边界", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A正确：稀疏性、非相干欠采样、非线性重建是CS成立的三大支柱，缺一不可；规则欠采样会产生结构化的卷褶而无法被稀疏约束区分，故必须用变密度随机采样（中心密、外周疏）。B正确：并行采集利用线圈的空间冗余，CS利用图像的变换域冗余，二者信息来源不同故可叠加，商用CS-SENSE、CS-GRAPPA可将三维序列缩短一半以上。C正确：CS的L1正则本质上是“惩罚不稀疏的成分”，加速过高时低对比细节会被当作噪声抑制掉，出现塑料感/水彩画样过平滑，临床验证应关注低对比小病灶（如肝内小转移、微小骨转移）的检出而不仅看主观锐利度。D正确：三维与动态数据在空间/时间维度上高度冗余，是CS收益最大的场景。【为什么错】E错误：CS重建是求解带L1正则的非凸/凸优化问题，需要数十至上百次迭代，是典型的非线性运算，重建时间明显长于常规傅里叶变换，对重建服务器算力要求高；这也是CS在临床落地时需要考虑的工作流成本。", "tr": "E的“线性、同样快”是常见误解。另需明确CS与深度学习重建（DLR）的区别：CS依靠人为设定的稀疏先验，DLR依靠数据驱动学习到的先验；无DLR的设备上，追求更高加速只能依赖CS＋并行采集的组合，并须以本机小病灶检出验证为准绳。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0156", "t": "多选题", "s": "关于MR门控与触发技术，下列说法正确的有", "o": {"A": "心电门控以R波为触发信号，时间精度最高，是心脏电影、黑血序列与延迟强化的基础；磁流体动力学效应会使T波在强磁场中抬高，可能被误认为R波而造成触发错误，故应优化电极位置并使用矢量心电（VCG）", "B": "外周脉搏门控（指端光电容积脉搏波）操作简便、不受磁流体动力学干扰，但脉搏波相对R波有数百毫秒的延迟且波形圆钝，时相精度低，适用于对时相要求不高的场景（如脊柱、脑脊液流动抑制）", "C": "呼吸门控可用腹带式压力传感器或呼吸波纹管获取呼吸曲线，在呼气末的稳定期采集", "D": "导航回波（navigator）在膈肌顶部放置一条一维柱状激发条，实时追踪膈肌位置，仅接受落在设定接受窗（常3—5 mm）内的数据；门控效率过低（如低于40%）时应重新训练患者呼吸或改用屏气方案", "E": "心电门控与呼吸门控不能同时使用，只能二选一"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-AUX-003", "kp": "心电门控、外周门控、呼吸门控与导航回波", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A正确：R波陡峭、易于识别，是心脏时相的天然零点；但导电血液在主磁场中流动产生的电位（磁流体动力学效应）叠加在T波上使其抬高，普通三导联心电易误触发，矢量心电通过空间向量方向区分真R波与伪信号，是高场心脏MR的标准配置。B正确：外周门控的信号源在指端，与心脏收缩之间存在传导延迟，波峰圆钝、抖动大，只能提供近似的心动周期节律，适合脊柱、颅脑等仅需抑制搏动伪影的场合。C正确：呼气末是呼吸周期中位置最稳定、停留时间最长的时相。D正确：导航回波的接受窗越窄图像越锐利但门控效率越低、扫描时间越长，须在二者间平衡；效率过低意味着患者呼吸不规律，应重新训练或改屏气。【为什么错】E错误：二者完全可以并用，且在心脏与上腹部检查中是常规做法——心电门控管心动时相、呼吸门控或导航回波管呼吸位移，例如非屏气的三维全心冠脉成像即同时使用心电门控与膈肌导航。", "tr": "E是明显的绝对化陷阱，但仍有考生因“怕冲突”而误选。另注意术语区别：门控（gating）是持续采集、事后按信号筛选或分箱；触发（triggering）是等到信号出现才启动采集。前瞻性触发丢弃异常心搏，回顾性门控可重排数据获得全心动周期电影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0157", "t": "单选题", "s": "颅脑MRI常规横断面扫描时，被广泛采用的定位基线是", "o": {"A": "在正中矢状面定位像上以前连合—后连合连线（AC-PC线）或平行于胼胝体膝部下缘与压部下缘的连线作为基线，其优点是解剖标准化、便于随访与不同患者间比较", "B": "以外耳道与鼻尖的连线为基线", "C": "以头皮外形的最大径线为基线", "D": "以磁体等中心的水平面为基线，不参考解剖结构", "E": "以颅底斜坡的走行方向为基线"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-001", "kp": "颅脑横断面定位基线", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。AC-PC线是神经影像学公认的标准基线，它使双侧基底节、丘脑、内囊等结构在同一层面对称显示，横断面解剖具有可重复性；胼胝体膝部下缘与压部下缘连线在实际操作中与AC-PC线接近，是更易目视确定的替代基线。标准化基线的价值在于：随访时层面可比、双侧结构对称便于发现细微不对称、便于与标准图谱及既往CT对照。【为什么错】B错误：外耳道—鼻尖连线不是公认基线；CT颅脑常用眦耳线（OML）或听眉线，MR则以AC-PC为主。C错误：头皮外形受个体差异与摆位影响，不具解剖学意义。D错误：完全不参考解剖会使层面歪斜、双侧不对称，随访无法比较。E错误：斜坡走行个体差异大且过于倾斜，仅在特定颅底检查中作为参考。", "tr": "重点是理解“为什么要标准化”，而不是死记线名。摆位时还须保证正中矢状面与磁体中线重合、头部无旋转与侧倾，否则再标准的基线也会产生假性不对称，误导海马、颞叶等细微结构的判读。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0158", "t": "单选题", "s": "三维T1加权梯度回波序列（3D T1-TFE/MPRAGE/BRAVO）在颅脑检查中广泛使用，其在序列结构上加入反转恢复预脉冲的主要目的是", "o": {"A": "提供充分的T1对比，使灰白质分界清晰，从而支持各向同性1 mm重建、脑容积测量、皮层发育不良评估与神经导航配准", "B": "抑制脑脊液信号", "C": "缩短扫描时间", "D": "降低SAR", "E": "抑制脂肪信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-002", "kp": "3D T1W梯度回波的反转预脉冲作用", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。快速三维扰相梯度回波为追求速度采用极短TR与小翻转角，本身的T1对比很弱，灰白质难以区分。在每个采集段前加一个非选择性180°反转脉冲并设置合适的反转时间，可把灰白质的纵向磁化差异放大，形成媲美二维自旋回波T1WI的对比。由此获得的各向同性亚毫米数据可任意面重建，用于海马与全脑体积定量、局灶性皮层发育不良的皮层厚度与灰白质交界模糊征评估，以及手术导航与放疗计划的图像配准。【为什么错】B抑制脑脊液是FLAIR的功能，其TI要长得多（约2200—2500 ms@3.0T），而3D T1的TI通常仅数百至一千毫秒。C错误：加入反转脉冲与其后的恢复等待反而延长了序列，加速靠的是三维采集、并行采集与压缩感知。D错误：多一个180°脉冲只会增加SAR。E错误：抑制脂肪需频率选择性饱和或短TI的STIR，与此处的中等TI反转预脉冲用途不同。", "tr": "关键在于区分“同为反转恢复预脉冲，TI不同则用途完全不同”：TI约150—250 ms抑脂（STIR）、TI约2200—2500 ms抑脑脊液（FLAIR@3.0T）、TI数百至千毫秒增强T1对比（MPRAGE类）、TI由Look-Locker实测用于抑制正常心肌（LGE）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0159", "t": "单选题", "s": "急性缺血性卒中患者的颅脑T2-FLAIR图像上，于患侧大脑中动脉供血区的脑沟内见到多发线样、蛇形高信号（血管走行区），而同层T2WI上血管呈流空低信号。对该征象的正确技术—临床解读是", "o": {"A": "为FLAIR血管高信号征，是近端大血管重度狭窄或闭塞后侧支循环内血流缓慢、流空效应减弱而在长TE的FLAIR上呈高信号，常提示存在可挽救的侧支代偿，应结合MRA与灌注综合判断，不应误判为蛛网膜下腔出血或伪影", "B": "为脑脊液抑制不全所致的伪影，只需重新设置TI即可消失", "C": "提示蛛网膜下腔出血，应立即改行CT", "D": "为脂肪抑制失败造成的高信号", "E": "为并行采集加速过高产生的残余卷褶伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-003", "kp": "FLAIR血管高信号征的技术机制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。快速流动的血液因流出层面而产生流空低信号；当近端血管闭塞、侧支血流极其缓慢时，血液在层面内停留时间延长，流空效应消失，其相对较长的T2使之在FLAIR的长TE下呈高信号，沿脑沟内血管走行呈线样、蛇形分布。该征象的临床价值在于提示大血管病变与侧支代偿状况，与灌注—扩散不匹配的范围常有相关性。【为什么错】B脑脊液抑制不全表现为脑室、脑池内弥漫或对称的高信号，多见于脑室系统与后颅窝，形态与沿血管走行的线样高信号不同，且不会局限于单侧供血区。C蛛网膜下腔出血在FLAIR上也表现为脑沟高信号，是最需要鉴别的对象，但其分布通常更弥漫、呈铸型，且SWI/T2*可见相应的低信号出血证据，结合病史（突发剧烈头痛）与CT可鉴别；本例为缺血症状且SWI无出血，不能贸然改判。D颅脑FLAIR一般不使用脂肪抑制，且脂肪抑制失败表现为颅骨骨髓与头皮的高信号，位置不符。E残余卷褶伪影表现为规律的条带状结构，与解剖血管走行一致的形态不符。", "tr": "本题的鉴别核心是“FLAIR脑沟高信号”的多因鉴别：血管高信号征、蛛网膜下腔出血、脑膜炎/癌性脑膜病、高浓度吸氧、钆剂渗入蛛网膜下腔、脑脊液流动与抑制不全伪影。副高层面要能从形态分布＋伴随序列（SWI、DWI、MRA）综合判断，而非单看一幅图。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0160", "t": "案例分析题", "s": "患者男，27岁，反复发作性愣神伴口咽自动症4年，抗癫痫药物控制不佳，拟行术前评估，临床高度怀疑颞叶内侧癫痫（海马硬化）。常规头颅MRI（5 mm层厚横断面T1WI、T2WI、FLAIR）报告未见异常。设备为飞利浦3.0T，配备32通道头线圈与压缩感知。技师应追加的最关键扫描方案是", "o": {"A": "增加垂直于海马长轴的斜冠状面高分辨T2WI与FLAIR，层厚2—3 mm、无层间隔、小FOV高分辨矩阵，双侧对称覆盖海马全长；并加做各向同性1 mm的3D T1加权序列用于灰白质交界评估与容积测量，必要时补充垂直于海马长轴的斜矢状面", "B": "把原有横断面层厚由5 mm改为8 mm以提高信噪比", "C": "追加静脉注射钆剂的全脑增强扫描，海马硬化多呈明显强化", "D": "追加全脑DTI纤维束成像作为主要诊断依据", "E": "追加SWI寻找海马内微出血"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-004", "kp": "癫痫海马专用扫描方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。海马沿颞角呈前后走行且略向内上倾斜，常规横断面对其为斜切，5 mm层厚更使部分容积效应严重掩盖海马内部结构，这正是“常规MRI阴性”的技术原因。癫痫专用方案的要点为：①方位——在正中矢状或旁矢状定位像上确定海马长轴，扫描斜冠状面使层面垂直于该长轴，两侧海马在同一层面对称显示，便于左右对比；②分辨率——层厚2—3 mm、无间隔、小FOV（常180—200 mm）与高矩阵，以分辨海马内部结构与体积差异；③序列——高分辨T2WI（观察海马信号增高）与FLAIR（观察内侧颞叶信号异常），加各向同性3D T1用于容积测量与灰白质交界评估（局灶性皮层发育不良的关键征象）。3.0T的高信噪比与压缩感知加速使这一方案在临床可接受时间内完成。【为什么错】B层厚加大会进一步加重部分容积效应，与目标背道而驰。C海马硬化的典型表现是海马萎缩＋T2/FLAIR信号增高，并无异常强化；增强对本病诊断价值有限，且不能弥补层厚与方位的缺陷。D DTI可提供辅助信息（如穹窿、钩束的各向异性改变），但不是海马硬化的诊断依据，也无法替代高分辨结构像。E海马硬化不以微出血为特征，SWI在此无针对性。", "tr": "本题的根本考点是“阴性结果可能是技术造成的”。副高层面必须能识别：层厚、方位与分辨率不足是常规MRI漏诊海马硬化、局灶性皮层发育不良的首要原因。类似的“方位决定成败”场景还有：垂体（薄层冠状）、内听道（薄层轴位＋水成像）、直肠癌（垂直肠壁的斜轴位）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0161", "t": "案例分析题", "s": "患者女，31岁，闭经泌乳2年，血清泌乳素显著升高，临床疑垂体微腺瘤（可能仅3—4 mm）。设备为飞利浦3.0T。技师拟行垂体动态增强扫描。下列技术设计与判读要点，最恰当的是", "o": {"A": "以冠状面为主、层厚2—3 mm无间隔覆盖整个垂体与海绵窦，配合矢状面；动态期采用快速采集（如快速自旋回波T1或扰相梯度回波），每一期约10—20 s、连续采集6—8期覆盖注药后1—2 min；判读要点是微腺瘤在早期强化程度低于快速强化的正常垂体而呈相对低信号，延迟期可变为等或高信号，故仅做延迟期极易漏诊", "B": "采用5 mm层厚横断面，注药后5 min扫一期即可", "C": "动态增强的判读要点是微腺瘤比正常垂体强化更早更快，呈早期高信号", "D": "为提高信噪比，动态各期间隔应设为60 s以上", "E": "微腺瘤诊断主要依赖DWI，动态增强意义不大"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-005", "kp": "垂体动态增强扫描技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。垂体微腺瘤的检出完全依赖“时间窗＋薄层＋方位”三者配合。①方位与层厚：垂体前后径小、微腺瘤常位于腺体侧翼，冠状面能同时显示垂体上缘形态、垂体柄偏移与海绵窦侵犯，层厚必须2—3 mm且无间隔，否则3—4 mm的病灶被部分容积淹没。②时间分辨率：正常垂体前叶无血脑屏障、由垂体门脉系统供血，注药后迅速均匀强化并在30—60 s达峰；微腺瘤血供来自被膜血管、强化延迟，故只在早期这一短暂窗口内表现为相对低信号，因此每期必须控制在10—20 s并连续采集6—8期。③判读：延迟期病灶与正常腺体趋于等信号，单做延迟期是垂体微腺瘤漏诊最常见的原因。【为什么错】B 5 mm层厚与单一延迟期同时踩中两个致命错误，必然漏诊。C强化时序说反：微腺瘤是“慢进”，正常垂体是“快进”。D 60 s以上的间隔会完全错过早期时间窗，把动态扫描做成了普通增强。E垂体区DWI受颅底磁敏感与部分容积影响严重，对3—4 mm病灶无实用价值，动态增强才是核心手段。", "tr": "最大的陷阱是C的“强化时序反向”。记忆抓手：正常垂体没有血脑屏障、血供丰富，一定是“先亮”；微腺瘤“后亮”，所以要抢早期。另注意扫描前应了解是否已用溴隐亭治疗，治疗后腺瘤缩小、强化特征改变会影响判读。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0162", "t": "多选题", "s": "后颅窝与颅底区域MR成像质量较差，下列关于其成因与改善措施的说法正确的有", "o": {"A": "岩骨、乳突气房与鼻窦的气—骨—软组织界面磁化率差异大，造成局部B₀不均匀，梯度回波类序列与EPI受影响最重，表现为信号丢失与几何变形", "B": "第四脑室、中脑导水管与桥前池的脑脊液搏动可产生流动相关伪影与信号不均，沿相位编码方向出现条带状鬼影", "C": "改善措施包括：使用自旋回波/快速自旋回波替代梯度回波、施加流动补偿（梯度矩零化）、加用空间预饱和带、必要时采用心电或外周门控采集，以及做高阶匀场", "D": "对必须使用EPI-DWI的情形，可采用读出分段EPI或提高并行采集因子以缩短有效回波链，从而减轻几何变形", "E": "增大层厚是改善后颅窝磁敏感伪影最有效的手段"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-006", "kp": "后颅窝伪影的成因与对策", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确：磁化率差异导致局部质子失相位，梯度回波无180°重聚故最敏感，EPI因长读出链而变形最重。B正确：脑脊液在心动周期驱动下往复搏动，在导水管、桥前池与颈髓交界处形成流动伪影，常被误读为病变（如误认为蛛网膜囊肿、血管流空或占位）。C正确：这四条是标准对策组合——自旋回波的180°脉冲能重聚静态场不均匀；流动补偿使恒速流动的相位归零；饱和带抑制搏动源；门控把采集固定在心动周期的同一时相；高阶匀场直接改善B₀。D正确：几何变形与相位方向的等效带宽成反比，缩短单次读出链是根本对策。【为什么错】E错误：增大层厚只会加重部分容积效应、掩盖小病灶，对磁化率造成的场不均匀毫无改善作用；恰恰相反，在磁化率剧变区往往需要更薄的层厚以减少层内失相位。", "tr": "E利用“层厚大＝信号强＝伪影不明显”的错觉。要点：磁化率伪影的成因是B₀空间畸变，只有改变序列类型、缩短回波链、改善匀场才能真正解决；层厚、平均次数、翻转角这些“信噪比手段”对系统性场畸变无效。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0163", "t": "多选题", "s": "关于颅脑MR增强扫描的技术要点，下列说法正确的有", "o": {"A": "DWI、SWI、MRS与ASL等序列原则上应安排在注射钆剂之前采集，钆剂会改变磁化率与T1，影响这些序列的定量与判读", "B": "疑诊脑膜转移或脑膜炎时，延迟数分钟后加扫脂肪抑制T1WI或三维T1加权序列有助于提高细小脑膜强化的检出", "C": "增强后若需脂肪抑制（如眼眶、颅底、头皮病变），应选择化学位移选择性饱和或Dixon水像，不宜用STIR", "D": "三维T1加权梯度回波增强因层厚薄、可多平面重建，对小转移灶的检出通常优于5 mm二维自旋回波T1WI", "E": "为节省时间，增强扫描可省略平扫T1WI，直接对比增强图像与T2WI即可判断强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-007", "kp": "颅脑增强扫描的序列顺序与技术选择", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确：钆剂使组织T1缩短并引入磁化率效应，会压低MRS的Cho峰、干扰SWI相位、改变ASL的标记效率与DWI的信号强度，故功能与定量序列须前置。B正确：脑膜强化多在注药后数分钟更明显，脂肪抑制可去除颅骨骨髓与板障脂肪的高信号背景，三维序列则提供薄层与多平面重建能力。C正确：STIR按T1抑制，会误抑制强化组织（详见反转恢复原理），增强后应改用频率选择性饱和或Dixon。D正确：小转移灶常小于3 mm，5 mm层厚存在明显部分容积效应；三维序列1 mm各向同性采集可显著提高微小强化灶检出，是脑转移瘤筛查与立体定向放疗计划的标准做法。【为什么错】E错误：判断“是否强化”必须有同序列、同参数的平扫作为对照，否则无法区分强化与本身的T1高信号（如出血、黑色素、高蛋白、脂肪、钙化）。省略平扫T1WI是严重的方法学错误。", "tr": "E在追求效率时最容易被忽视。请牢记增强判读的铁律：强化＝增强后信号高于同序列平扫，而非高于周围组织。另注意平扫与增强的窗宽窗位、层面位置应保持一致以便对照。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0164", "t": "单选题", "s": "患者女，29岁，产后10天，剧烈头痛伴视物模糊，临床疑颅内静脉窦血栓形成。设备为飞利浦3.0T。下列MR方案设计最合理的是", "o": {"A": "以SWI（或T2*WI）观察窦内血栓的顺磁性低信号，联合二维时间飞跃法MR静脉成像（2D TOF-MRV，饱和带置于成像容积足侧以抑制动脉）或对比增强MRV观察充盈缺损，并结合常规T1WI/T2WI/FLAIR评估静脉性梗死与出血；判读时须注意横窦发育不良与蛛网膜颗粒可造成假阳性", "B": "首选3D TOF-MRA观察静脉窦，其对慢血流的敏感性最高", "C": "仅行DWI即可确诊静脉窦血栓", "D": "仅行常规T1WI与T2WI，静脉窦血栓在这两个序列上信号特征恒定、诊断可靠", "E": "首选MRS评估静脉窦区代谢改变"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-008", "kp": "颅内静脉窦血栓的MR技术方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。静脉窦血栓的技术评估需要“直接征象＋间接征象＋并发症”三条线：①直接看血栓——SWI/T2*对去氧血红蛋白与含铁血黄素的顺磁性极敏感，急性血栓呈显著低信号，还可显示扩张的皮层引流静脉；②看管腔——2D TOF-MRV逐层薄层激发对慢血流敏感（3D TOF因容积内饱和不适合静脉），扫描时把饱和带置于成像容积的足侧以抑制上行动脉血；对比增强MRV则不依赖流动，可减少慢血流与平面内流动造成的假阳性；③看后果——常规序列评估静脉性梗死、水肿与出血。同时必须熟知假阳性来源：横窦发育不良或不对称、蛛网膜颗粒、窦内分隔，均可造成充盈缺损样表现，需结合双侧对比与增强MRV判断。【为什么错】B错误：3D TOF存在容积内饱和，对流速缓慢的静脉显示差，且方位选择针对动脉；静脉成像应用2D TOF或增强MRV。C错误：DWI可提示静脉性梗死或部分血栓的扩散受限，但敏感性与特异性均不足以单独确诊。D错误：血栓信号随时间演变剧烈——急性期（数天内）在T1等信号、T2低信号，极易与正常流空混淆而漏诊；亚急性期才呈T1高信号。仅靠常规序列漏诊率高。E错误：MRS对本病无诊断价值，且静脉窦邻近颅骨无法匀场。", "tr": "两个高频陷阱：①急性期血栓T2低信号酷似正常流空，是最常见的漏诊原因，必须加做SWI与MRV；②静脉成像用2D TOF而非3D TOF，饱和带放在足侧（与颅内动脉MRA正相反）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0165", "t": "单选题", "s": "颈椎MRI横断面扫描时，关于层面角度的设置，正确的做法是", "o": {"A": "在矢状面定位像上按各个椎间隙分组设置，使每组层面分别平行于相应椎间盘平面，从而真实显示该节段的椎间盘、钩椎关节、椎间孔与神经根", "B": "从C2至T1采用统一角度连续无间隔扫描，以保证覆盖完整", "C": "层面应垂直于脊髓长轴，与椎间盘角度无关", "D": "层面应平行于AC-PC线", "E": "层面角度可由系统随机设定，不影响诊断"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-001", "kp": "颈椎横断面的分组成角扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确。颈椎存在生理前凸，各椎间隙的倾斜角度自上而下不断变化。只有让层面平行于每一个椎间盘平面，才能获得真正的“椎间盘轴位”，准确判断突出的方向与程度、钩椎关节增生、椎间孔狭窄与神经根受压。因此临床标准做法是按椎间隙分组（如C3/4、C4/5、C5/6、C6/7各一组），每组单独调整角度。【为什么错】B统一角度会使中下段椎间盘被斜切，突出物形态失真，容易高估或低估突出程度，且椎间孔无法显示。C垂直于脊髓长轴与平行于椎间盘并不等价，颈椎前凸使二者在多数节段有明显夹角；诊断关注的是椎间盘平面。D AC-PC线是颅脑定位基线，与颈椎无关。E错误：层面角度直接决定诊断准确性，绝无“随机设定”之说。", "tr": "考点是“方位服从解剖与临床问题”。同类思维：腰椎轴位同样按椎间隙分组成角（尤其L5/S1倾斜大）；若为观察椎体骨质或椎管内占位的连续范围，则可采用连续等角度覆盖。两种目的对应两种设置，不可混用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0166", "t": "单选题", "s": "老年女性，胸腰段多个椎体楔形变，临床需要区分新鲜（近期）与陈旧压缩骨折以决定是否行椎体成形术。最能提供关键信息的序列是", "o": {"A": "矢状面短反转时间反转恢复（STIR）或脂肪抑制T2WI：新鲜骨折的骨髓水肿呈明显高信号，陈旧骨折骨髓信号已恢复为脂肪信号而无水肿", "B": "矢状面T1WI，新鲜骨折呈高信号", "C": "横断面T2WI，可直接测量椎体高度丢失比例", "D": "三维时间飞跃法MRA观察椎体血供", "E": "1H-MRS测定椎体脂肪含量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-002", "kp": "椎体压缩骨折新鲜与陈旧的鉴别序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确。判断“新鲜与否”的病理基础是骨髓水肿：新鲜骨折伴出血、水肿使骨髓含水量增加，在脂肪抑制的T2加权（STIR或脂肪抑制TSE T2WI）上呈明确高信号，同时T1WI上呈低信号取代正常脂肪高信号；陈旧骨折骨髓已被脂肪重新充填，脂肪抑制像上与正常椎体一致。这是决定椎体成形术是否可能缓解疼痛的关键影像依据。老年患者常合并多发陈旧骨折，形态学（楔形变）无法区分责任椎体，必须依靠水肿信息。【为什么错】B错误：新鲜骨折在T1WI上是低信号（水肿取代脂肪），选项方向说反。C错误：横断面不适合观察椎体高度，且高度丢失只反映形态、不反映时相；陈旧骨折同样可有严重楔形变。D椎体血供不是MRA的目标，也不能反映骨髓水肿。E MRS测椎体脂肪分数属研究性定量，且体素大、匀场难，不用于急慢性鉴别。", "tr": "记住新鲜骨折的“三联信号”：T1WI低、脂肪抑制T2WI/STIR高、可有强化。金属内固定术后患者若脂肪抑制不良，STIR比化学位移饱和更可靠。另需鉴别病理性骨折：椎弓根受累、椎体后缘膨隆、软组织肿块与弥漫强化提示肿瘤。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0167", "t": "单选题", "s": "腰椎MRI最基本的常规序列组合是", "o": {"A": "矢状面T1WI与T2WI、横断面T2WI，并按需加矢状面STIR或脂肪抑制T2WI", "B": "仅横断面T1WI", "C": "仅矢状面T2WI", "D": "冠状面T1WI与横断面T1WI", "E": "三维时间飞跃法MRA与DWI"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-003", "kp": "腰椎MRI常规序列组合", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确。矢状面T1WI观察骨髓信号（转移、感染、骨折后脂肪替代）与解剖全貌；矢状面T2WI观察椎间盘退变与含水量、脊髓信号、后纵韧带与硬膜囊；横断面T2WI（按椎间隙分组）判断突出的方向、类型与神经根、侧隐窝、椎间孔受累；STIR或脂肪抑制T2WI用于凸显骨髓水肿与终板炎，是发现隐匿性骨折、感染与转移的关键补充。【为什么错】B单一横断面T1WI既无法评估椎间盘含水量，也不能纵览节段关系。C仅矢状面T2WI无法判断突出的偏侧与神经根受压，也缺乏骨髓的T1信息。D冠状面在脊柱常规中不作为基本方位（多用于侧弯、骶髂关节或神经丛评估），且缺T2信息。E MRA与DWI在腰椎属特殊需求（如疑肿瘤、感染时加DWI），不属基本组合。", "tr": "副高层面除了记住组合，还要能说出“每条序列回答什么临床问题”。补充记忆：疑椎管内占位或感染需加增强（脂肪抑制T1WI）；疑强直性脊柱炎需加骶髂关节斜冠状STIR；术后随访需加增强以区分瘢痕（强化）与复发椎间盘（周边强化、中心不强化）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0168", "t": "多选题", "s": "腰椎后路椎弓根螺钉内固定术后患者需复查MRI，为减轻金属伪影，下列措施正确的有", "o": {"A": "优先选用快速自旋回波（TSE/FSE）类序列，避免梯度回波类序列，因180°重聚焦脉冲可重聚静态磁场不均匀造成的失相位", "B": "提高接收带宽、缩短回波间隔并适当增大采集矩阵，可减小磁化率所致的像素位移与信号堆积，代价是信噪比下降", "C": "脂肪抑制改用STIR或Dixon类方法，不宜使用窄带化学位移选择性饱和（SPIR/SPAIR），因金属旁B₀畸变会使脂肪峰频率偏移导致抑制失败甚至误抑制水", "D": "可启用专用金属伪影抑制技术（如视角倾斜VAT、层面编码金属伪影校正SEMAC、多采集可变谐振成像MAVRIC，或厂家的O-MAR等），并适当降低场强选择（如有1.5T设备优先于3.0T）", "E": "应把频率编码方向设置为与金属植入物长轴垂直，可使伪影范围最小"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-004", "kp": "金属内固定术后脊柱MRI的伪影抑制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确：梯度回波无180°脉冲，磁化率失相位无法补偿，金属旁信号完全丢失；TSE的重聚焦脉冲能挽回大部分静态失相位。B正确：磁化率位移量与每像素带宽成反比，提高带宽（如从±25 kHz提高到±50—100 kHz）能显著压缩伪影范围，代价是SNR按带宽平方根反比下降，需用更多平均次数补偿。C正确：金属旁B₀严重畸变，窄带频率选择性饱和不再对准脂肪峰，会出现抑制不全或误抑制；STIR基于T1不依赖频率，是金属旁最可靠的脂肪抑制方式。D正确：VAT通过在读出时施加与层选梯度相同的补偿梯度校正面内位移；SEMAC/MAVRIC通过额外的层面方向编码校正层面弯曲，是目前最有效的方案；同时低场强下磁化率伪影更小，1.5T优于3.0T。【为什么错】E错误：方向说反。应把频率编码方向设置为与植入物长轴平行，使磁化率造成的位移沿金属长轴方向延展、在垂直方向上更紧凑，从而减少对邻近椎管与神经根的遮盖。", "tr": "E的方向是高频失分点。总口诀：读出方向顺着金属长轴、带宽拉高、TE压短、避开GRE、抑脂用STIR、能用SEMAC就用SEMAC、有1.5T就别用3.0T。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0169", "t": "案例分析题", "s": "患者男，52岁，高处坠落伤后6 h，双下肢感觉运动障碍平面在T10，CT示T11椎体爆裂骨折伴椎管内骨块。生命体征平稳，颈托与脊柱板固定中，需急诊MRI评估脊髓损伤程度与椎管受压情况。设备为飞利浦3.0T。下列方案设计最合理的是", "o": {"A": "在保持轴线稳定的前提下由多人平托过床；采用后部脊柱相控阵线圈，扫描矢状面T2WI与T1WI、矢状面STIR（评估脊髓水肿、韧带损伤与骨髓水肿）、损伤节段横断面T2WI；有条件时加矢状面T2*WI或SWI以检出髓内出血（提示预后不良），并可加矢状面DWI辅助评估；全程控制扫描时长、备好MR兼容监护，并事先确认颈托、固定装置与所有随行器械均为MR安全", "B": "先做全脊柱增强扫描以显示血肿", "C": "只做横断面T2WI即可判断脊髓损伤程度", "D": "为避免搬动风险，直接在脊柱板（含金属搭扣）上送入磁体扫描", "E": "急诊情况下应优先做DTI纤维束成像以判断预后"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-005", "kp": "急性脊髓损伤的MR检查方案与安全", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确，同时兼顾了安全、序列与效率三条线。①安全：脊柱板、颈托、约束带的金属搭扣是常见的铁磁性隐患，必须逐一确认或更换为MR安全型；搬运需保持轴线稳定，多人平托。②序列逻辑：矢状面T2WI/STIR是评估脊髓水肿范围、椎间盘韧带复合体损伤与骨髓水肿的核心；T1WI提供解剖与出血的补充信息；横断面T2WI判断骨块占位与脊髓受压的横断关系；T2*WI/SWI检出髓内出血——髓内出血是完全性损伤与不良预后的重要指标，常规T2WI易漏。③效率：急性期患者耐受差，应精简序列、控制时长并全程监护。【为什么错】B增强对急性脊髓外伤的评估价值有限，且延长检查时间、增加风险，不作为首选。C横断面缺乏纵向范围信息，无法判断脊髓水肿的上下界与多节段损伤，单独使用严重不足。D错误：这是严重的安全违规，任何未经确认的固定装置都不得进入Zone IV。E DTI在急性期采集时间长、对运动敏感，且需要患者良好配合，急诊阶段不具可行性，属于研究性或亚急性期的补充。", "tr": "本题最容易被忽略的是D所代表的安全环节——急诊转运器械的铁磁筛查。另一个专业深度点是T2*/SWI检出髓内出血的预后意义，很多考生只想到T2WI看水肿。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0170", "t": "单选题", "s": "关于眼眶MRI检查技术，下列说法正确的是", "o": {"A": "眶内脂肪在T1WI与T2WI上均为高信号，会掩盖病变并在增强后与强化组织混淆，故T2WI与增强T1WI应常规使用脂肪抑制；层厚宜2—3 mm，并沿视神经走行加扫斜矢状面或斜冠状面；应嘱患者闭眼、注视固定方向以减少眼球运动", "B": "眼眶脂肪信号低，无须脂肪抑制", "C": "层厚以5—8 mm为宜，可提高信噪比", "D": "为减少眼球运动应嘱患者持续快速眨眼", "E": "眼眶MRI禁止使用增强扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HNK-001", "kp": "眼眶MRI的脂肪抑制与方位设计", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A正确。眶内容物被大量脂肪包绕，脂肪在T1WI呈高信号，增强后强化病灶同样呈高信号，二者无法区分，故增强T1WI必须脂肪抑制；T2WI脂肪抑制则有助于凸显水肿与囊性成分。眼眶结构精细（视神经直径仅3—4 mm、眼外肌数毫米），层厚必须2—3 mm并配合小FOV高分辨；视神经走行倾斜，斜矢状面沿其长轴可完整显示，斜冠状面便于对比双侧眼外肌与视神经的粗细。眼球运动是眼眶MRI最主要的伪影源，嘱患者闭眼并想象注视一个固定点、避免眼球游走，可显著改善。【为什么错】B完全说反：眶脂在T1WI与T2WI（非脂肪抑制）上均为高信号。C 5—8 mm层厚对眼眶结构而言过厚，部分容积效应会淹没视神经与小病灶。D持续眨眼会显著增加眼球与眼睑运动，加重伪影。E错误：眼眶肿瘤、炎性假瘤、视神经病变等均需增强评估，并无禁忌。", "tr": "细节陷阱：眼眶邻近鼻窦与颅底，化学位移选择性脂肪抑制常出现局部失败，可改用Dixon水像获得更均匀的抑制；含金属眼影/睫毛膏（部分含氧化铁）可造成眼睑伪影甚至发热，检查前应要求卸妆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0171", "t": "多选题", "s": "关于鼻咽癌的MRI检查技术要点，下列说法正确的有", "o": {"A": "扫描范围上界应至少包含鞍上池/蝶窦上缘，下界应达锁骨上窝，以完整覆盖颅底与颈部各区淋巴结", "B": "平扫T1WI对颅底骨质受侵敏感——正常颅底骨髓的脂肪高信号被肿瘤取代后呈低信号，是早期骨侵犯的重要征象，因此不能用脂肪抑制T1WI取代平扫T1WI", "C": "增强后应加扫脂肪抑制T1WI，横断面结合冠状面，以显示咽旁间隙、翼腭窝、卵圆孔与破裂孔等颅底孔道的神经周围侵犯及海绵窦受累", "D": "层厚一般取3—5 mm，颅底区域宜更薄；小FOV高分辨有助于评估咽颅底筋膜与咽旁间隙", "E": "鼻咽癌MRI可完全替代颈部淋巴结的病理评估，凡MRI阴性即可排除转移"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HNK-002", "kp": "鼻咽癌MRI的范围、序列与方位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A正确：鼻咽癌沿颅底孔道向上侵犯、沿淋巴引流向下转移，范围不足会造成分期错误，这是技师最常见的失误。B正确：这是一个极具操作价值的要点——脂肪抑制会把正常骨髓的高信号一并压低，反而使“脂肪信号消失”这一早期骨侵犯征象无法识别，因此平扫T1WI不可省略、不可用脂肪抑制版本代替。C正确：脂肪抑制增强T1WI是显示神经周围侵犯与海绵窦、咽旁间隙受累的关键，冠状面对颅底孔道的显示优于横断面。D正确：颅底结构精细，薄层与小FOV是准确分期的前提。【为什么错】E错误：MRI是形态学检查，对正常大小淋巴结内的微转移无法识别，不能替代病理；“阴性即可排除”属绝对化错误表述。", "tr": "B是本题的技术精华：并非“凡增强就加脂肪抑制、凡T1就可抑脂”。骨髓侵犯的判断依赖正常骨髓的脂肪高信号作为背景参照，抑脂后这一参照消失。同理，脊柱转移的筛查也必须保留矢状面平扫T1WI。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0172", "t": "单选题", "s": "颈部与甲状腺MRI最主要的运动伪影来源及其对策是", "o": {"A": "吞咽、呼吸与颈部大血管搏动；对策包括扫描前训练患者避免吞咽与说话、缩短单次采集时间、优先选用快速自旋回波类序列、在颈前与血管流入侧施加空间预饱和带，必要时使用外周门控", "B": "眼球运动；对策是嘱患者闭眼", "C": "胃肠蠕动；对策是肌注解痉药", "D": "膈肌运动；对策是呼吸门控，与吞咽无关", "E": "心脏搏动不会影响颈部图像，无须处理"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HNK-003", "kp": "颈部MRI的运动伪影控制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A正确。颈部运动伪影有三个来源：①吞咽——喉与舌骨在数秒内可移动1 cm以上，是颈部图像模糊的首要原因，必须在扫描前明确交代“不吞咽、不说话、不咳嗽”，并把单次采集控制在3—4 min内以便患者忍耐；②呼吸——颈根部与上纵隔受呼吸影响；③颈动脉与颈静脉搏动——沿相位编码方向产生鬼影，可用流动补偿与预饱和带抑制。选用TSE类快速序列缩短采集窗、必要时用外周门控把采集固定在心动周期同一时相，均可显著改善。【为什么错】B眼球运动影响眼眶而非颈部。C胃肠蠕动是腹部问题。D膈肌运动只影响颈根部以下，且颈部检查一般不使用呼吸门控（会大幅延长时间），把吞咽排除在外是明显的遗漏。E错误：颈部大血管与心脏传导来的搏动确实会产生伪影，不能忽视。", "tr": "本题看似简单，实则考“抓主要矛盾”。颈部的第一伪影源是吞咽而非呼吸；解决方案里最有效、成本最低的是“扫描前沟通＋缩短采集时间”，而不是加复杂的门控。另注意甲状腺检查应使用专用颈部相控阵线圈或小FOV，肩部垫高使颈部略后仰以贴近线圈。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0173", "t": "案例分析题", "s": "患儿女，2岁，双侧极重度感音神经性聋，拟行人工耳蜗植入术，术前需影像评估。颞骨CT已完成，示双侧内耳骨性结构大致正常。耳科医师追加MRI申请，核心问题是“耳蜗腔是否通畅、蜗神经是否存在”。设备为飞利浦3.0T，患儿需镇静。技师应重点采集的序列与方位是", "o": {"A": "内耳三维重T2权重高分辨水成像（3D bTFE/CISS/FIESTA-C或3D TSE类），亚毫米各向同性、小FOV；在此基础上重建垂直于内听道长轴的斜矢状面，逐一辨认面神经、蜗神经、前庭上与前庭下神经四束；耳蜗内若见正常高信号淋巴液则提示腔道通畅，若信号缺失提示骨化或纤维化", "B": "常规横断面T2WI TSE，层厚4 mm即可回答上述问题", "C": "内耳DWI高b值成像，蜗神经在DWI上显示最佳", "D": "三维时间飞跃法MRA，通过迷路动脉判断蜗神经发育", "E": "增强后横断面T1WI，蜗神经强化即为存在"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HNK-004", "kp": "人工耳蜗术前内耳MRI评估", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A正确。人工耳蜗术前评估中，CT与MRI分工明确：CT看骨性结构（耳蜗形态、圆窗、内听道骨性直径、乳突气化、有无骨化），MRI看液体与神经（膜迷路内淋巴液信号是否完整、蜗神经是否存在及粗细）。这两点恰恰决定手术能否实施与电极能否插入——耳蜗骨化/纤维化时液体高信号消失，需改变手术策略；蜗神经缺如则人工耳蜗无效，应考虑听觉脑干植入。技术上必须用亚毫米各向同性的三维重T2水成像，并重建垂直于内听道长轴的斜矢状面——只有在这个方位上四条神经束才呈现为“田”字形排列的四个低信号点，可逐一辨认。前下为蜗神经，前上为面神经，后方为前庭上、下神经。【为什么错】B 4 mm层厚远大于蜗神经直径（约1 mm），根本无法分辨神经束，也无法评估耳蜗各回的液体信号。C DWI在颞骨区变形严重、分辨率低，用于胆脂瘤而非神经计数。D迷路动脉过于细小，且血管与神经发育不能互相推断。E蜗神经为正常神经组织，不会强化；增强主要用于排查内听道占位与迷路炎，不能作为“存在与否”的判据。", "tr": "本题的高阶要点是“斜矢状面重建才能数清四条神经”。很多技师只提供横断面原始图像，导致临床无法回答蜗神经有无的问题。另需注意患儿镇静时的听力防护与全程生命体征监护，以及bTFE类序列在3.0T的带状伪影，必要时改用三维TSE类水成像。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0174", "t": "单选题", "s": "肺实质MRI成像质量明显差于CT，其最主要的物理原因是", "o": {"A": "肺组织内含大量气—组织界面造成磁化率差异极大而使T2*极短（1.5T约2 ms、3.0T更短），同时肺实质质子密度很低，加之呼吸与心脏搏动，信号采集极为困难", "B": "肺组织的T1过短导致信号饱和", "C": "肺内脂肪含量过高，脂肪抑制困难", "D": "肺组织的化学位移过大", "E": "肺内血流速度过快导致流入增强过强"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-001", "kp": "肺MRI的物理局限", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确。肺MRI面临三重不利：①质子密度低——肺实质约80%为空气，可用质子远少于实质器官；②T2*极短——数以亿计的肺泡壁与空气形成微观磁化率界面，局部磁场梯度巨大，横向磁化在毫秒级即衰减殆尽，常规序列的TE往往已错过信号；③运动——呼吸与心脏搏动叠加。对策是采用超短回波时间（UTE）或零回波时间（ZTE）序列把TE压至微秒级、采用屏气单次激发TSE（SSh-TSE/HASTE/SSFSE）快速采集，或使用放射状/螺旋采集配合自导航。【为什么错】B错误：问题不在T1，而在T2*与质子密度。C错误：肺实质本身不含大量脂肪，脂肪抑制不是肺MRI的核心矛盾。D错误：化学位移由分子结构决定，肺组织并无特殊的大化学位移。E错误：肺血流并不特别快，流入增强也不是导致图像质量差的原因。", "tr": "尽管肺实质成像困难，MRI在胸部仍有明确优势：评估胸壁与胸膜侵犯、肺上沟瘤对臂丛与锁骨下血管的侵犯、纵隔囊性与实性病变鉴别、心包与大血管关系、以及无辐射的随访（如儿童与孕妇）。答题时不要把“肺实质成像差”扩大为“胸部MRI无用”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0175", "t": "单选题", "s": "乳腺动态增强MRI（DCE-MRI）对时间分辨率有明确要求，其根本原因是", "o": {"A": "需在注药后的早期时相（约1—2 min内）捕捉病灶的强化速率与峰值，并在延迟期观察廓清，从而绘制时间—信号强度曲线并区分持续上升型、平台型与流出型，故单期采集时间通常须控制在60—90 s以内，且需覆盖注药前至注药后约6—8 min", "B": "时间分辨率越低越好，可提高空间分辨率而不影响曲线判读", "C": "只需注药后8 min扫一期即可判断良恶性", "D": "时间分辨率的意义仅在于缩短患者检查时间", "E": "乳腺DCE不需要平扫作为基线"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-002", "kp": "乳腺DCE的时间分辨率要求与曲线类型", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确。乳腺DCE的诊断信息来自“形态＋动力学”两部分，动力学部分依赖时间—信号强度曲线：Ⅰ型持续上升多见于良性，Ⅱ型平台型为中间型，Ⅲ型早期快速强化后廓清（流出型）高度提示恶性。恶性病灶的强化峰值多出现在注药后1—2 min，若单期时间过长就会跨过峰值、把“快进快出”平均成“持续上升”，造成动力学信息失真。因此单期采集时间一般控制在60—90 s以内（多数中心约60 s），并采集注药前基线1期与注药后连续5—6期覆盖至6—8 min。【为什么错】B错误：这是典型的时间—空间分辨率权衡误判，时间分辨率不足会直接毁掉曲线判读。C单期延迟扫描无法获得任何动力学信息，且延迟期良恶性强化程度可能接近。D错误：时间分辨率首先是诊断信息的需要，缩短检查时间只是附带效果。E错误：平扫是计算强化率与绘制曲线起点的必需基线，也用于识别病灶本身的T1高信号（如出血、含蛋白囊肿）。", "tr": "乳腺DCE的其他配套要点常一起考：绝经前女性宜安排在月经周期第7—14天（避开背景实质强化高峰）；俯卧位专用乳腺相控阵线圈、双侧同时成像、双乳自然悬垂不受压；横断面相位编码方向常取左右向，使心脏搏动鬼影沿左右方向传播而不覆盖乳腺组织。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0176", "t": "多选题", "s": "关于乳腺MRI的检查条件与体位技术，下列说法正确的有", "o": {"A": "绝经前女性宜安排在月经周期第7—14天检查，此期背景实质强化（BPE）最低，可减少假阳性", "B": "采用俯卧位专用乳腺相控阵线圈，双乳自然悬垂于线圈孔内，避免受压变形；双侧同时成像便于左右对照", "C": "常规包含脂肪抑制T2WI（或Dixon）、DWI与动态增强T1WI；DWI可提供ADC信息辅助鉴别，但受呼吸运动与磁敏感影响，须注意其分辨率低于形态学序列", "D": "扫描范围应包含双侧腋窝，以评估腋窝淋巴结", "E": "为提高患者舒适度，乳腺MRI应采用仰卧位并加压固定双乳"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-003", "kp": "乳腺MRI的时机、体位与序列组合", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确：激素水平影响乳腺腺体的血供与强化，黄体期BPE明显升高会掩盖小病灶或造成假阳性，故推荐在月经周期第2周检查；哺乳期与激素替代治疗者同样需注意。B正确：俯卧使乳腺远离胸壁与心脏、减少呼吸运动传递，自然悬垂避免组织重叠与压迫伪影；双侧同时成像既提高效率又便于对称性判断。C正确：多参数组合是当前乳腺MRI的标准，DWI的加入可降低单纯依赖强化模式的假阳性，但其空间分辨率与磁敏感稳定性不及T1/T2序列，不能替代形态学与动力学评估。D正确：腋窝淋巴结状态直接影响分期与治疗，遗漏腋窝是常见的范围错误。【为什么错】E错误：仰卧加压是乳腺X线摄影（钼靶）的体位逻辑，不适用于MRI。仰卧位会使乳腺摊平在胸壁上、与心肺运动直接耦合、组织重叠增加，且加压会改变血流灌注影响动态曲线，是完全错误的做法。", "tr": "E把X线摄影的“压迫”经验错误迁移到MRI。要牢记两种检查的物理逻辑完全不同：钼靶靠压迫减少组织重叠与辐射剂量；MRI靠俯卧悬垂减少运动与重叠，绝不能加压。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0177", "t": "多选题", "s": "尽管肺实质MRI受限，胸部MRI在下列情形中仍具有明确临床价值的有", "o": {"A": "评估肺尖部肿瘤（肺上沟瘤）对臂丛神经、锁骨下动静脉与椎体的侵犯范围", "B": "判断周围型肺癌或胸膜病变对胸壁、膈肌与心包的侵犯", "C": "鉴别纵隔囊性与实性病变（如支气管囊肿、胸腺囊肿与胸腺瘤），并评估其与大血管的关系", "D": "对需反复随访的年轻患者或孕妇，提供无电离辐射的替代或补充手段", "E": "作为肺内磨玻璃结节筛查的首选方法，敏感性高于低剂量CT"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-004", "kp": "胸部MRI的适应证定位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确：MRI的多平面成像与优异的软组织对比使其在显示臂丛神经与血管受累方面明显优于CT，是肺上沟瘤术前评估的标准手段。B正确：胸膜外脂肪层是否连续、胸壁肌肉信号是否异常、膈肌与心包是否受累，MRI判断能力优于CT。C正确：MRI能通过T2信号与增强特征明确区分囊性与实性，避免囊肿被误判为肿瘤。D正确：无辐射是MRI的固有优势，在需长期随访的良性病变、青少年与妊娠人群中价值突出。【为什么错】E错误：磨玻璃结节的检出与随访依赖高空间分辨率与对微小密度差异的敏感性，这正是CT的强项而MRI的短板；肺实质T2*极短、质子密度低使MRI对亚厘米磨玻璃病灶敏感性很低，低剂量CT才是肺癌筛查的标准方法。", "tr": "本题要建立“扬长避短”的技术判断力：MRI在胸部的优势在软组织与血管神经关系，短板在肺实质细节。切勿因“MRI无辐射”而在肺结节筛查这类问题上误选。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0178", "t": "案例分析题", "s": "患者女，42岁，因右乳肿块行乳腺MRI。图像回顾发现：脂肪抑制T2WI上右乳外侧与双侧腋窝脂肪抑制不完全、呈片状高信号；动态增强图像上双乳边缘可见沿前后方向的重复轮廓，病灶边界模糊；此外增强各期之间腺体位置有明显位移。设备为飞利浦3.0T，采用俯卧位乳腺专用线圈，脂肪抑制方式为SPAIR。下列改进措施组合最合理的是", "o": {"A": "脂肪抑制不均源于大FOV边缘与腋窝区B₀不均匀，可先做局部匀场并把匀场框精确覆盖双乳，或改用Dixon水脂分离获得更均匀的抑制；重复轮廓提示运动/呼吸伪影，应重新摆位使双乳稳定悬垂、加用衬垫固定并强调保持不动；各期位移应在后处理中做动态序列的运动配准，必要时缩短单期采集时间以减少期内运动", "B": "把脂肪抑制由SPAIR改为STIR，并在增强各期沿用", "C": "增大FOV至400 mm并降低分辨率，可同时解决脂肪抑制与运动问题", "D": "取消动态增强，仅保留平扫T2WI与DWI", "E": "把相位编码方向由左右改为前后，可消除重复轮廓"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-005", "kp": "乳腺MRI脂肪抑制不均与运动伪影的排查", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确，三个问题逐一对应。①脂肪抑制不均：SPAIR属频率选择性方法，依赖B₀均匀；双乳同时成像的FOV大、腋窝与胸壁交界处磁场畸变明显，边缘区脂肪峰频率偏移导致抑制失败。对策是精确局部匀场（把匀场容积框限定在双乳范围）或改用Dixon类水脂分离，后者对B₀不均匀的耐受性明显更好且可在增强后使用。②重复轮廓：沿相位编码方向的规律性重影是运动鬼影的典型表现，源头是呼吸传递与体位不稳，应重新摆位、使双乳充分悬垂并用衬垫限制活动，同时充分沟通。③各期位移：动态序列间的位移必须通过后处理的运动配准纠正，否则减影图会出现假性强化与假性充盈缺损；缩短单期时间也可减少期内运动模糊。【为什么错】B错误：STIR基于T1抑制，增强后会误抑制强化组织，导致病灶信号丢失，是增强后的禁忌选择。C增大FOV并降低分辨率既不改善B₀均匀性，又牺牲了小病灶（乳腺MRI要求能分辨≤5 mm病灶）的检出，属于以诊断质量换表观改善。D取消动态增强等于放弃乳腺MRI最核心的诊断信息，本末倒置。E错误：乳腺横断面本就应把相位编码设为左右方向，使心脏搏动鬼影沿左右传播而不覆盖乳腺；改为前后方向反而会让心脏与胸壁运动的鬼影直接叠加到乳腺上，方向完全相反。", "tr": "E是精心设计的反向陷阱，考的是“乳腺横断面相位编码方向为何取左右”。另一个高频失分点是B：把STIR当作万能脂肪抑制而忽略其在增强后的禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0179", "t": "单选题", "s": "心脏电影成像普遍采用平衡稳态自由进动序列（bTFE/TrueFISP/FIESTA），其主要原因是", "o": {"A": "该序列信号强度近似正比于T2/T1，血液的T2/T1比值高而心肌低，可在不使用对比剂、不依赖血液流入的情况下获得极高的血池—心肌对比与信噪比，且TR极短便于在一次屏气内完成多时相采集", "B": "该序列依赖血液流入效应，故血池呈高信号", "C": "该序列对磁场不均匀不敏感，在3.0T上不会出现任何伪影", "D": "该序列为自旋回波类序列，血液呈流空低信号", "E": "该序列必须注射钆剂后才能显示心腔"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-CMR-001", "kp": "电影bTFE的对比机制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】A正确。平衡稳态自由进动在稳态下所有梯度在每个TR内完全平衡，横向磁化被保留并循环利用，稳态信号强度近似正比于√(T2/T1)（常简述为T2/T1比值）。血液的T2/T1比值远高于心肌，故血池明亮、心肌灰暗，形成高对比；由于对比来源是组织固有弛豫特性而非流入效应，即使在血流缓慢的心尖、心耳或严重心功能不全者中仍能保持对比，这正是它取代早期梯度回波电影的原因。极短的TR（2—4 ms）使一次屏气内可获得20—30个心动时相。【为什么错】B错误：这是扰相梯度回波（流入增强）的机制；bTFE的优势恰恰在于不依赖流入。C错误：bTFE对B₀不均匀高度敏感，3.0T下极易出现带状（banding/off-resonance）伪影，需要在扫描前做频率校正（frequency scout）或缩短TR、局部匀场，这是3.0T心脏检查的常规步骤。D错误：bTFE是梯度回波类序列，血液呈高信号；血液流空低信号是黑血自旋回波类序列的特征。E错误：bTFE电影是平扫技术，无须对比剂。", "tr": "C是必须记住的3.0T实操要点：场强越高、TR越长，带状伪影越明显。对策包括扫描前频率校正、缩短TR、精细匀场；若仍无法克服，可改用扰相梯度回波电影（对比略差但无带状伪影）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0180", "t": "案例分析题", "s": "患者男，68岁，扩张型心肌病，持续性心房颤动，心室率90—130次/分、绝对不齐，屏气仅能维持约8 s。临床要求评估左室容积、射血分数与心肌纤维化。设备为飞利浦3.0T，具备压缩感知加速。首次采集的短轴电影出现明显的层间对位不齐与心肌边界模糊，延迟强化图像可见弥漫条状伪影。下列对策组合最合理的是", "o": {"A": "启用实时（real-time）电影或单心跳采集的加速电影（结合压缩感知与并行采集），必要时改自由呼吸多次平均采集；心电门控改用矢量心电并优化电极位置，开启心律失常剔除（arrhythmia rejection）设定合适的RR间期接受窗；延迟强化改用单次激发结合相位敏感反转恢复（single-shot PSIR）以降低对屏气与心律的依赖；把每次屏气任务缩短到8 s以内并在呼气末统一屏气位置", "B": "增加平均次数并延长屏气至20 s，以提高信噪比", "C": "放弃心电门控，改用外周脉搏门控可获得更准确的心动时相", "D": "改用自旋回波黑血序列采集电影以避免心律影响", "E": "告知临床心房颤动为心脏MRI绝对禁忌，建议取消检查"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-CMR-002", "kp": "心律失常与屏气困难时的CMR对策", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】A正确，每一条都直击一个失败环节。①分段采集失败：常规电影把数据分散到十余个心动周期采集，房颤时RR间期长短不一使各段的心脏位置与时相不一致，导致边界模糊；实时电影在单个心动周期内完成一帧图像采集，牺牲部分时空分辨率换取对心律的免疫，配合压缩感知可部分弥补分辨率损失。②门控错误：3.0T磁流体动力学效应使T波抬高易被误触发，矢量心电与优化电极位置可改善；心律失常剔除功能可丢弃落在接受窗外的心搏。③屏气受限：把每次屏气任务压到8 s以内，统一在呼气末屏气（位置最稳定、可重复），或改自由呼吸配合导航/多次平均。④延迟强化：单次激发PSIR在一个心跳内完成一层采集，对TI精度与屏气时长的依赖大幅降低，是房颤患者LGE的标准替代方案。【为什么错】B延长屏气到20 s对本例不可行，且增加平均次数无法解决心律不齐造成的相位不一致，只会把不一致的数据平均得更模糊。C外周门控的时相精度远低于心电门控（存在数百毫秒延迟且波形圆钝），用于心脏电影会使收缩末期与舒张末期判定错误，容积与射血分数失真。D黑血自旋回波序列采集慢、不能生成电影，且同样依赖门控，方向错误。E错误：房颤是CMR的技术挑战而非绝对禁忌，通过上述技术手段多数可获得可用图像；绝对禁忌指的是不可扫描的植入物、无法配合的危重状态等。", "tr": "本题综合了门控、屏气、序列与重建四个层面，是心脏MR的典型现场难题。要点提炼：心律不齐→实时/单心跳采集＋心律失常剔除＋矢量心电；屏气差→缩短单次任务、呼气末屏气、单次激发PSIR、自由呼吸导航。切勿用“增加平均次数”这种信噪比手段去解决时相一致性问题。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0181", "t": "单选题", "s": "关于钆塞酸二钠（Gd-EOB-DTPA）肝胆特异期（肝细胞期）的延迟采集时间，正确的是", "o": {"A": "注射后即刻（<1 min）", "B": "动脉期（20~30 s）", "C": "平衡期（3~5 min）", "D": "肝胆特异期（约20 min）", "E": "延迟期（10 min）"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-181", "kp": "钆塞酸二钠（Gd-EOB-DTPA）肝胆特异期延迟时间", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】钆塞酸二钠约50%经肝细胞摄取经胆道排泄，肝胆特异期（肝细胞期）通常在注药后约20 min采集，此时正常肝实质因摄取对比剂明显强化、与胆道及病灶对比最佳，是检出小肝癌及评估肝功能/胆道的关键时相。【为什么错】A/B为动脉期及早期强化时相，用于富血供病灶；C/E为平衡/延迟期，肝胆摄取尚未充分，不能代表特异期。", "tr": "易把肝胆特异期误记为10 min或平衡期；实际Gd-EOB肝胆期标准延迟约20 min，严重肝功能不全者需延长至30~40 min。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0182", "t": "多选题", "s": "关于Gd-EOB-DTPA注射流率对动脉期与肝胆特异期成像质量的影响，以下正确的是", "o": {"A": "注射流率偏低（如1 mL/s）可造成动脉期峰值延迟、强化幅度下降", "B": "为获得理想动脉期，流率可取2 mL/s并配合生理盐水冲管", "C": "肝胆特异期肝实质强化程度与注射流率无关，只取决于注药总量", "D": "对比剂外渗会同时削弱动脉期与肝胆期强化", "E": "采用高压注射器团注可提高动脉期峰值浓度，利于小病灶显示"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-182", "kp": "Gd-EOB-DTPA注射流率对多期相与肝胆期的影响", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】团注流率影响动脉期峰值浓度与到达时间，2 mL/s配合盐水冲管可获得锐利动脉期；流率过低使峰值后延、幅度降低，小肝癌「快进快出」显示不清；外渗则总量不足，两期均减弱。【为什么错】C错：肝胆期信号虽主要取决于肝细胞摄取功能与总量，但流率过低致外渗或注射不全同样削弱肝胆期，且摄取动力学受团注质量影响。", "tr": "误以为肝胆期只与总量无关流率；实际上团注完整性与是否外渗同样影响肝胆期信噪比。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0183", "t": "案例分析题", "s": "患者男性，58岁，体检发现胰腺占位，临床拟诊胰腺神经内分泌肿瘤，拟行胰腺MR多期相动态增强扫描以评估病灶血供特征。关于该检查方案的序列与参数设计，最合理的是", "o": {"A": "单层动态梯度回波T1WI，层厚8 mm，无脂肪抑制，延迟期采集", "B": "3D容积 interpolated 梯度回波（eTHRIVE / VIBE / LAVA）薄层（3 mm）同反相位+多期动态+fs，动脉期用自动触发", "C": "仅做MRCP重T2加权，不做增强", "D": "屏气单次激发FSE T2WI厚层评估胰腺", "E": "只用DWI取代增强评估胰腺病变"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-183", "kp": "胰腺MR多期相动态增强方案设计", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】胰腺血供丰富、病灶（如神经内分泌瘤、腺癌）强化特征依赖多期相；应采用3D薄层梯度回波（飞利浦eTHRIVE）同反相位观察脂肪浸润/脂质瘤，加SPAIR脂肪抑制抑制腹腔脂肪，多期动态（动脉/门脉/延迟）并配合团注追踪触发捕获动脉期，层厚3 mm避免遗漏小病灶。【为什么错】A层厚过厚且无抑脂、只延迟期会漏动脉期与微小病灶；C仅MRCP看胰管不评估实质；D/E均不能评价强化。", "tr": "以薄层T2或MRCP替代动态增强；胰腺小病灶（如胰岛素瘤）高度依赖动脉期强化，必须薄层多期+抑脂。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0184", "t": "单选题", "s": "采用化学位移同相位/反相位成像判断肾上腺含脂腺瘤时，其典型表现是", "o": {"A": "反相位信号明显高于同相位（病灶含脂）", "B": "同相位信号高于反相位（病灶含脂，化学位移相消致反相位信号下降）", "C": "同、反相位信号相等", "D": "反相位信号高于同相位且边界清晰", "E": "仅T2WI能判断，化学位移序列无意义"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-184", "kp": "肾上腺同反相位化学位移成像判断脂质腺瘤", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】含脂腺瘤在反相位（out-of-phase，水脂相位相反）因水脂信号相消而信号明显低于同相位（in-phase），称「信号丢失」；这是无创诊断良性腺瘤的核心征象。【为什么错】A/D说反相位更高属颠倒；C无差别不支持腺瘤；E否定化学位移价值错误。", "tr": "混淆同/反相位方向：记住反相位（水脂抵消）含脂病灶信号「下降」即反相位低于同相位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0185", "t": "多选题", "s": "关于肾上腺化学位移成像中\"勾边征\"（India ink artifact）的机制与表现，以下正确的是", "o": {"A": "含脂病灶在反相位与同相位交界出现线状低信号勾边（India ink artifact）", "B": "勾边征是水脂界面化学位移伪影，非真正结构", "C": "同相位图像上该勾边最明显", "D": "相位编码方向决定勾边出现于病灶左右还是上下边缘", "E": "勾边征提示病灶恶性"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-185", "kp": "肾上腺化学位移勾边征（India ink artifact）机制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】水脂化学位移使同反相位交界在相位编码方向出现黑线（勾边），是含脂腺瘤的辅助征象，位置由相位编码方向决定。【为什么错】C错：勾边在反相位最显著；E错：勾边是良性含脂表现而非恶性标志。", "tr": "把India ink勾边误判为坏死或出血边界；它纯属化学位移伪影，且总是反相位明显。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0186", "t": "单选题", "s": "关于心脏T2* mapping铁沉积定量的阈值判读，正确的是", "o": {"A": "T2*值>40 ms 提示重度铁过载", "B": "T2*值<20 ms（室间隔ROI）提示心脏铁过载，<10 ms为重度", "C": "T2* mapping 不受磁场不均匀影响，无需匀场", "D": "肝铁过载分级按T2*升高程度判断", "E": "R2*（1/T2*）与铁浓度呈负相关"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-186", "kp": "心脏T2* mapping铁沉积定量阈值分析", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】心脏T2* mapping在室间隔放置ROI，正常约>20 ms；<20 ms提示铁过载，<10 ms为重度，需祛铁治疗并监测心功能，属定量决策指标。【为什么错】A颠倒（应降低）；C错，T2* mapping对B0不均极敏感需仔细匀场及多回波拟合；D肝铁过载是T2*下降（R2*升高）而非升高；E错，R2*与铁浓度正相关。", "tr": "混淆T2*与铁浓度关系：铁越多T2*越短、R2*越大，阈值<20 ms（心）<10 ms重度。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0187", "t": "单选题", "s": "前列腺多参数MRI（mpMRI）的核心三要素是", "o": {"A": "仅T2WI平扫即可完成前列腺癌筛查", "B": "T2WI + 高b值DWI（b=1400~2000） + DCE动态增强三要素联合（mpMRI）", "C": "仅DCE增强", "D": "仅T1WI + DWI", "E": "MRS alone"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-187", "kp": "前列腺多参数MRI（mpMRI）三要素", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】PI-RADS v2.1要求mpMRI包含T2WI（解剖）、高b值DWI（b≥1400，观察受限弥散）、DCE（评价早期强化），三者互补提高癌灶检出与定位。【为什么错】单一序列敏感性不足，A/C/D/E均不完整。", "tr": "遗漏高b值DWI；移行带病变主要靠DWI与DCE，外周带主要靠T2WI，三者缺一不可。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0188", "t": "案例分析题", "s": "患者男性，62岁，肠镜确诊直肠癌，拟行术前MRI分期以评估环周切缘（CRM）。关于直肠癌高分辨率MRI的扫描方案，最合理的是", "o": {"A": "横轴位（平行于坐骨结节连线）即可准确评估系膜筋膜", "B": "高分辨斜轴位垂直于肿瘤长轴（或垂直肛管）薄层（3 mm）T2WI，使肿瘤与直肠系膜筋膜（MRF）关系显示最佳", "C": "仅做冠状位评估CRM", "D": "厚层（5 mm以上）快速T2WI筛查", "E": "不做T2WI，仅凭DWI判断CRM受累"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-188", "kp": "直肠癌高分辨率MRI斜轴位与环周切缘（CRM）评估", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】直肠癌术前分期要求高分辨薄层（≤3 mm）T2WI，斜轴位应垂直于肿瘤长轴（无法判定时垂直肛管），以最短距离显示肿瘤与直肠系膜筋膜（MRF）关系，CRM间距<1 mm为受累、影响保肛决策。【为什么错】A平行扫描会拉长显示距离造成低估；C冠状位不能精确测最短CRM；D厚层漏小病灶；E DWI不能替代解剖CRM测量。", "tr": "用平行轴位评估CRM导致间距被高估、漏诊系膜筋膜受侵；务必斜轴垂直肿瘤长轴薄层。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0189", "t": "多选题", "s": "关于子宫MRI随月经周期的信号变化与DCE增强时相表现，以下正确的是", "o": {"A": "增殖期子宫内膜在T2WI呈高信号（分泌期相对变薄、信号略降）", "B": "DCE增强早期（动脉期）子宫内膜及肌层内层明显强化", "C": "月经周期不影响子宫各层信号，无需记录", "D": "结合带（junctional zone）在T2WI为低信号，是肌层内带", "E": "带环（IUD）产生磁敏感伪影但一般不影响评估"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-189", "kp": "子宫MRI月经周期信号特征与DCE时相", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】子宫内膜随周期变化：增殖期厚且T2高信号，分泌期相对变薄；DCE早期内膜与结合带、肌层分层强化；结合带为低信号内肌层；IUD伪影通常可识别不影响诊断。【为什么错】C错，周期显著影响信号，应在报告注明经期。", "tr": "忽略月经周期对内膜信号影响而误判病变；增强时相需区分内膜与肌层强化时序。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0190", "t": "单选题", "s": "关于盆腔肿块DWI高b值与ADC值的判读，正确的是", "o": {"A": "ADC值越低提示弥散受限，多见于恶性实性肿块", "B": "ADC值越高越支持恶性", "C": "DWI在盆腔无需高b值", "D": "囊性病灶ADC一定高于实性，无重叠", "E": "DWI不能鉴别良恶性，无价值"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-190", "kp": "盆腔肿块DWI高b值与ADC值判读", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】恶性实性肿块细胞密集、 extracellular space小，弥散受限，高b值DWI高信号且ADC降低；定量ADC辅助鉴别。【为什么错】B颠倒；C错，盆腔需高b值（如800~1000）提高对比；D/E绝对化错误。", "tr": "把ADC高低方向记反；并避免「ADC无重叠」绝对化——需结合形态与强化。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0191", "t": "单选题", "s": "膝关节MRI中，为最佳显示半月板体部与前交叉韧带，斜冠状位的定位应是", "o": {"A": "斜冠状位平行于股骨内外髁连线", "B": "斜冠状位垂直于胫骨平台且垂直于前交叉韧带（ACL）走行", "C": "斜冠状位平行于髌骨长轴", "D": "斜矢状位用于评价半月板前后角", "E": "轴位是评估交叉韧带唯一序列"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-191", "kp": "膝关节专用斜冠状位定位（垂直ACL/胫骨平台）", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】膝斜冠状位应垂直于胫骨平台并垂直于ACL走行，以最佳显示半月板体部、交叉韧带及关节软骨；常规配PDWI-SPAIR脂肪抑制。【为什么错】A平行平台会扭曲ACL显示；C/D/E描述不全或错，矢状位看半月板前后角及ACL，但斜冠状定位核心是垂直ACL。", "tr": "将斜冠状位误设为平行平台；正确应垂直平台且垂直ACL，否则半月板与韧带显示不佳。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0192", "t": "多选题", "s": "关于踝关节韧带MRI的斜位定位与PDWI脂肪抑制应用，以下正确的是", "o": {"A": "距腓前韧带（ATFL）在踝关节斜轴位（垂直胫腓骨）显示最佳", "B": "三角韧带（deltoid）在斜冠状位观察", "C": "PDWI加SPAIR/SPIR脂肪抑制可提高韧带与骨髓水肿对比", "D": "全手足线圈可同时覆盖双踝，但信噪比下降需延长平均", "E": "T1WI是评估韧带撕裂首选"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-192", "kp": "踝关节韧带斜位定位与PDWI脂肪抑制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】ATFL在斜轴位（垂直小腿长轴/胫腓骨）显示，三角韧带在斜冠状位；PDWI配脂肪抑制（SPAIR/SPIR）显著增强韧带-脂肪及骨髓水肿对比；小线圈或表面线圈提升SNR。【为什么错】E错，韧带评估首选PD/T2*加权脂肪抑制而非T1WI（T1看解剖不敏感水肿）。", "tr": "误用T1WI评估急性韧带损伤；急性撕裂伴水肿需脂肪抑制PD/T2*，T1对水肿不敏感。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0193", "t": "案例分析题", "s": "患者女性，55岁，肩关节外展上举无力伴夜间痛，怀疑肩袖撕裂。关于肩关节MRI斜冠状位定位与肩袖、盂唇损伤评估方案，最合理的是", "o": {"A": "常规斜冠状位平行于肩胛冈即可，无需脂肪抑制", "B": "斜冠状位垂直冈上肌腱长轴（平行于盂肱关节面），PDWI-SPAIR评价肩袖全层撕裂，必要时Direct MR关节造影（钆稀释液关节内注射）显示部分层撕裂", "C": "仅轴位T1WI足够", "D": "用STIR替代所有脂肪抑制序列", "E": "怀疑Bankart损伤只做CT"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-193", "kp": "肩关节斜冠状位定位与肩袖/盂唇损伤方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】肩斜冠状位应垂直于冈上肌腱（平行于关节面）以显示肌腱全长的连续中断；PDWI-SPAIR对全层撕裂敏感；部分层撕裂或Bankart/SLAP在常规MRI不确定时，Direct MR关节造影（稀释钆注入关节腔）使对比剂进入撕裂缝隙提高检出。【为什么错】A平行肩胛冈会斜切肌腱；C轴位T1不足；D STIR抑制脂肪但肌腱对比不及PDWI-SPAIR且增强后不可用；E CT不显示软组织。", "tr": "部分层肩袖撕裂常规MRI易漏，需脂肪抑制PDWI并考虑关节造影；斜冠状务必垂直冈上肌腱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0194", "t": "单选题", "s": "腕关节MRI中，为显示舟月韧带、月三角韧带及三角纤维软骨复合体（TFCC），应采用的定位方案是", "o": {"A": "轴位即可完整显示TFCC与舟月韧带", "B": "斜冠状位（沿腕骨弧线/垂直桡骨茎突）显示舟月骨、月三角韧带，斜矢状位显示TFCC三角纤维软骨", "C": "只做矢状位", "D": "腕关节无需脂肪抑制", "E": "线圈用头部线圈更佳"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-194", "kp": "腕关节斜冠状/斜矢状位定位与TFCC显示", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】腕斜冠状位沿腕骨排列并垂直桡骨茎突，可显示舟月（SL）、月三角（LT）韧带；斜矢状位（沿第3掌骨-桡骨）显示三角纤维软骨复合体（TFCC）及月骨缺血改变；常配PDWI脂肪抑制。【为什么错】A轴位不能显示韧带连续走行；C/D/E均不正确，脂肪抑制有助于水肿/积液显示，应使用小柔性线圈。", "tr": "腕韧带需沿其走行斜位显示，轴位易漏舟月分离；TFCC在斜矢状位最佳。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0195", "t": "多选题", "s": "关于下肢非对比增强MRA（TRANCE/NATIVE/Inhance）及其流敏感伪影，以下正确的是", "o": {"A": "非对比增强MRA（飞利浦Inhance 3D / TRANCE / NATIVE SPACE）利用血流与背景组织对比，无需钆剂", "B": "该类序列对慢血流、远端小动脉及支架术后患者友好，避免肾源性系统性纤维化（NSF）风险", "C": "流敏感伪影（flow-related dephasing）在弯曲血管或湍流处可造成信号丢失误认为狭窄", "D": "CE-MRA总是优于NE-MRA，应一律首选", "E": "配合心电门控/导航可减少运动与搏动伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-195", "kp": "下肢非对比增强MRA（TRANCE/NATIVE/Inhance）与流敏感伪影", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (9)外周血管", "ex": "【为什么对】Inhance/TRANCE/NATIVE 3D采用流动敏感散相与恢复技术获得血管内高信号，免钆剂、适合肾功能不全及支架术后；慢血流与远端血管显示好；但湍流/弯曲处流敏感伪影可致假阳性狭窄；门控导航可减伪影。【为什么错】D绝对化错误，NE-MRA有局限（扫描时间长、对严重钙化/湍流敏感），并非一律优于CE-MRA。", "tr": "将流敏感伪影误判为真实闭塞；NE-MRA弯曲段信号丢失不代表狭窄，需结合源图与TOF。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-0196", "t": "案例分析题", "s": "患者男性，45岁，右上肢麻木无力，怀疑臂丛神经病变。为显示神经走行并鉴别神经源性肿瘤，最合适的MR神经成像方案是", "o": {"A": "常规DWI即可区分神经根与神经鞘瘤，无需特殊序列", "B": "3D STIR SPACE（重T2加权三维采样完美梯度回波）加脂肪抑制显示神经走行，结合T2映射与增强鉴别神经源性肿瘤与神经根鞘膜，脂肪抑制失败时应调整频率/匀场或改用DIXON", "C": "仅T1WI平扫", "D": "用CE-MRA替代神经成像", "E": "MR neurography 对神经根病无价值"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-196", "kp": "MR神经成像（MR neurography）3D STIR SPACE技术与伪影对策", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (10)外周神经", "ex": "【为什么对】MR神经成像用重T2加权3D SPACE（飞利浦3D STIR SPACE / STIR TSE）配合优异脂肪抑制使神经呈高信号、连续显示走行；可区分神经鞘瘤（神经外膜包绕、靶征）与神经根/神经束；脂肪抑制失败（B0不均、金属）时需重设中心频率、精细匀场或采用DIXON水脂分离。【为什么错】A/D/E低估或错代技术；常规DWI不能替代解剖性神经成像，CE-MRA看血管非神经。", "tr": "脂肪抑制不均致神经-脂肪对比丧失误为「神经中断」；务必确认抑脂成功，必要时DIXON或调整中心频率。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0197", "t": "单选题", "s": "关于心脏黑血双反转恢复（Double IR）序列的原理与应用，正确的是", "o": {"A": "黑血成像采用双反转恢复（Double IR）预脉冲抑制血液与脂肪，慢轴位评估心肌与瓣膜", "B": "黑血成像无需抑制血液，血液天然呈高信号", "C": "黑血只能用心电门控，无法用导航", "D": "黑血序列必须用梯度回波", "E": "黑血对房颤患者无影响，触发设置可忽略"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-197", "kp": "心脏黑血双反转恢复（Double IR）序列原理", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】黑血（black-blood）常用双反转恢复（DIR，两次180°反转分别抑制血液与脂肪）配合快速自旋回波，使流动血液与脂肪均为低信号，突出心肌与血管壁；适合结构、血栓、瓣膜评估。【为什么错】B错，血液需主动抑制才呈黑；C/D错，黑血多为TSE且可配导航；E错，房颤时R-R不稳触发易失败需调整。", "tr": "误以为黑血靠血液自身流空；实际依赖双反转预脉冲主动抑制血液与脂肪信号。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0198", "t": "案例分析题", "s": "患者男性，60岁，高血压病史，超声提示左室肥厚，临床怀疑心肌淀粉样变。为定量评估心肌间质纤维化，关于心肌T1 mapping与ECV计算的方案，最合理的是", "o": {"A": "只测一次T1即可计算ECV，无需增强后", "B": "采用MOLLI/ShMOLLI获取原生T1与增强后（注药约15 min）T1，结合血细胞比容按 ECV=(1-Hct)×(1/T1myo−1/T1blood_post)/(1/T1blood_pre−1/T1blood_post) 计算细胞外容积", "C": "ECV仅用于心脏，不能反映弥漫纤维化", "D": "增强后T1测量越早越好（<2 min）", "E": "T1 mapping 不需匀场"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-198", "kp": "心肌T1 mapping与ECV（细胞外容积）定量计算", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】T1 mapping（MOLLI/ShMOLLI）分别测得原生T1与钆对比剂分布后（约15 min）T1，结合血池T1与Hct按公式算ECV，定量心肌间质扩增（纤维化、淀粉样变、水肿）。【为什么错】A错需增强后配对；C错ECV正是评估弥漫纤维化的关键；D过早测量对比剂未平衡且受廓清影响；E T1 mapping对B1+/B0敏感需校准匀场。", "tr": "增强后T1测量时机错误（太早）或漏测血池T1与Hct，致ECV公式分母错误；务必采集原生与增强后血池。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-0199", "t": "单选题", "s": "关于心肌T2 mapping在急性心肌水肿/心肌炎中的定量应用，正确的是", "o": {"A": "T2 mapping 用多TE的T2-prep bSSFP，急性心肌炎/水肿时T2值升高（如>~55~60 ms）", "B": "T2 mapping 用短TE越少越好", "C": "T2 mapping 对水肿不敏感", "D": "心肌炎T2值降低", "E": "T2 mapping 仅用于铁定量"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-199", "kp": "心肌T2 mapping急性水肿/心肌炎定量", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】T2 mapping采用多个T2准备时间（T2-prep）的bSSFP采集并拟合T2值；心肌水肿（急性心肌炎、心肌缺血再灌注）使T2升高，常以>55~60 ms为异常阈值，与T2WI黑血水肿相印证。【为什么错】B/C/D/E均错：多TE是必需、对水肿敏感、心肌炎T2升高而非降低、且不同于铁定量（T2* mapping）。", "tr": "混淆T2 mapping（水肿，T2升高）与T2* mapping（铁沉积，T2*降低）；两者临床意义相反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-0200", "t": "多选题", "s": "关于心肌首过灌注MR的技术要点与伪影对策，以下正确的是", "o": {"A": "心肌首过灌注（first-pass perfusion）采用饱和恢复梯度回波，注药同时连续采集观察强化达峰", "B": "腺苷/双嘧达莫负荷可诱发缺血节段灌注缺失", "C": "在成像层面近端加空间饱和带（sat band）抑制静脉血进入视野造成伪影", "D": "需心电门控（或心律稳定）以保证每心动周期相位一致", "E": "灌注伪影（呼吸、心律不齐）只能通过延长扫描解决，无序列对策"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-200", "kp": "心肌首过灌注MR技术与伪影对策", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】首过灌注用饱和恢复GRE（如飞利浦Turbo Field Echo perfusion）团注钆同时屏气连续采集；腺苷负荷扩张冠脉暴露缺血；近端空间饱和带抑制上腔静脉/右心血液流入左室造成的亮带伪影；心电门控保证相位一致。【为什么错】E错，伪影可通过饱和带、门控、屏气训练、缩短TR及导航等多手段控制，并非只能延长时间。", "tr": "漏加空间饱和带致右心/静脉血亮带误为前壁强化；负荷灌注务必抑制静脉血并稳定心律。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1001", "t": "单选题", "s": "关于MR检查绝对禁忌证的叙述，错误的是", "o": {"A": "体内植入心脏起搏器者", "B": "颅内铁磁性动脉瘤夹者", "C": "体内植入人工耳蜗者", "D": "体内植入钛合金骨内固定钉者", "E": "眼内有铁磁性异物者"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-001", "kp": "MR绝对禁忌证", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】钛合金为弱磁性（非铁磁性）材料，目前临床大多数骨内固定钉为钛合金或非铁磁性材料，可安全行MR检查，并非绝对禁忌证，故D项错误，本题选D。\n【为什么错】A：心脏起搏器受主磁场与射频场干扰可致起搏失效，为绝对禁忌证，正确。B：铁磁性动脉瘤夹在磁场中可移位造成再出血，为绝对禁忌证，正确。C：人工耳蜗内含铁磁性磁体且射频可致损伤，为绝对禁忌证，正确。E：眼内铁磁性异物可致眼组织损伤，为绝对禁忌证，正确。", "tr": "区分“铁磁性植入物（绝对禁忌）”与“钛合金/非铁磁性植入物（可行检查）”，是最常见命题陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1002", "t": "单选题", "s": "下列不属于MR检查适应证的是", "o": {"A": "颅内占位性病变的定位定性", "B": "椎间盘突出的诊断", "C": "膝关节半月板损伤", "D": "妊娠妇女的常规胎儿筛查", "E": "乳腺病变的定性诊断"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-002", "kp": "MR适应证", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】妊娠本身是MR检查的相对禁忌而非适应证，且“常规胎儿筛查”并不作为MR的常规检查项目（超声为产前筛查首选），故D不属于适应证，本题选D。\n【为什么错】A：MR软组织对比度极佳，颅内占位定位定性为典型适应证，正确。B：MR对椎间盘与脊髓显示优于其他影像，为典型适应证，正确。C：MR是半月板、韧带损伤诊断的金标准，为典型适应证，正确。E：MR动态增强与DWI为乳腺病变定性重要手段，为典型适应证，正确。", "tr": "适应证与相对禁忌证常对举出题，妊娠受检应“权衡利弊、可做但不常规”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1003", "t": "单选题", "s": "MR检查前患者去除体表金属物品时，下列哪项可以不用去除", "o": {"A": "金属钥匙", "B": "机械手表", "C": "含金属拉链的外衣", "D": "全陶瓷义齿", "E": "金属发卡"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-003", "kp": "MR检查前准备", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】全陶瓷义齿不含任何金属成分，不受磁场影响，进入磁体间无需去除，故D正确。\n【为什么错】A：金属钥匙可被吸入磁体造成伤害与伪影，须去除，正确。B：机械手表含金属机芯且可被磁化损毁，须去除，正确。C：金属拉链可产生磁敏感性伪影，须去除或更换衣物，正确。E：金属发卡可产生伪影并可能被吸引移位，须去除，正确。", "tr": "“可摘义齿”是否去除的关键看有无金属支架；陶瓷义齿无需去除。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1004", "t": "单选题", "s": "对幽闭恐惧症患者行MR检查，下列处理措施错误的是", "o": {"A": "检查前充分沟通并让患者了解检查过程", "B": "采取头先进位并嘱患者闭目、深呼吸放松", "C": "给予适当镇静后再行检查", "D": "不顾患者恐惧强行完成全部检查", "E": "必要时陪同人员站在扫描间内安抚患者"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-004", "kp": "幽闭恐惧症处理", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】强制患者完成扫描会加重恐惧、诱发躁动，导致图像运动伪影甚至检查失败，正确做法是充分沟通、体位安抚、镇静或终止检查，故D项错误，本题选D。\n【为什么错】A：充分沟通缓解焦虑为规范做法，正确。B：闭目、深呼吸可减轻幽闭感，正确。C：必要时镇静（如地西泮）后检查为可行方案，正确。E：家属或陪同人员在符合安全规范时于扫描间安抚，有助于完成检查，正确。", "tr": "患者不配合的处理原则是“疏导而非强制”，先安抚、后药物、再考虑终止。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1005", "t": "单选题", "s": "关于妊娠期行MR检查的叙述，正确的是", "o": {"A": "妊娠期任何阶段均严禁行MR检查", "B": "妊娠期增强扫描应用钆对比剂是安全的", "C": "超声能提供足够信息时不首选MR", "D": "早孕期MR检查对胎儿绝对无影响", "E": "妊娠患者增强扫描应常规加大钆剂剂量"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-005", "kp": "妊娠期MR检查原则", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】产前超声是胎儿检查的首选方法，只有当超声信息不足、临床确需进一步明确时才考虑MR，且须权衡利弊并由医师决策，故C正确。\n【为什么错】A：妊娠并非MR绝对禁忌，需权衡利弊后进行，说法过于绝对。B：妊娠期应用钆对比剂应谨慎，仅在对母儿影响明确有利时使用，并非安全。D：早孕期器官形成期对电离辐射敏感，MR虽无电离辐射，但对其远期影响认识有限，不能说“绝对无影响”。E：妊娠患者应避免不必要的对比剂应用，更不能加大剂量。", "tr": "“妊娠期MRI”考点：无电离辐射≠无风险，增强钆剂妊娠期慎用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1006", "t": "单选题", "s": "TOF-MRA（时间飞跃法）的成像基础是", "o": {"A": "血流的流入增强效应", "B": "血流质子的相位变化", "C": "血流的T2*弛豫差异", "D": "外源性钆对比剂的T1缩短", "E": "脂肪信号被抑制后的反差"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-006", "kp": "TOF-MRA原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】TOF-MRA利用短TR反复激励使静止组织磁化饱和、信号压低，而流入成像层面的未饱和血液质子不断产生较高信号，即“流入增强效应”，故A正确。\n【为什么错】B：利用相位变化成像的是相位对比法PC-MRA，非TOF。C：T2*弛豫差异是SWI等磁敏感成像的基础。D：利用钆剂T1缩短的是CE-MRA（对比增强MRA）。E：脂肪抑制与TOF血管成像机制无关。", "tr": "TOF（流入增强）、PC（相位对比）、CE-MRA（对比增强）三种MRA机制必须分清。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1007", "t": "单选题", "s": "常规颅脑3D TOF-MRA扫描，翻转角（FA）通常设置为", "o": {"A": "5°～10°", "B": "20°～35°", "C": "60°～80°", "D": "90°", "E": "135°"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-007", "kp": "TOF-MRA翻转角", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】3D TOF-MRA常用较小翻转角（约20°～35°），兼顾背景组织抑制与血流信号，故B正确。\n【为什么错】A：5°～10°翻转角过小，背景抑制不足、血流对比差。C：60°～80°为较大翻转角，常见于2D TOF。D：90°为激励脉冲的常用翻转角，用于常规自旋回波类序列。E：135°与常规成像无关，反转恢复180°脉冲常与之混淆。", "tr": "翻转角数值考点：3D TOF约20°～35°，2D TOF常用较大角（60°左右），勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1008", "t": "单选题", "s": "关于2D TOF与3D TOF-MRA的比较，叙述错误的是", "o": {"A": "2D TOF对缓慢血流较为敏感", "B": "3D TOF空间分辨率较高", "C": "3D TOF可采用更小体素提高细节显示", "D": "2D TOF层面内血流质子易发生饱和", "E": "3D TOF对慢血流显示优于2D TOF"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-008", "kp": "2D与3D TOF比较", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】2D TOF单层成像、每层血流持续流入，对慢血流更敏感；3D TOF在较大容积内多次激励，慢血流质子易被饱和而信号丢失，故“3D TOF对慢血流显示优于2D”的说法错误，本题选E。\n【为什么错】A：2D TOF对慢血流敏感，正确。B：3D TOF薄层采集、分辨率高，正确。C：3D TOF可用更小体素、细节好，正确。D：2D TOF血流沿层面内走行部分可发生饱和导致信号丢失，正确。", "tr": "颅内快血流用3D TOF、颈部及下肢慢血流多用2D TOF；慢血流饱和是3D TOF的固有缺点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1009", "t": "单选题", "s": "PC-MRA（相位对比法）中速度编码值（VENC）设置过低时，可能出现", "o": {"A": "背景信号增高", "B": "流动质子的相位卷褶（混叠）", "C": "血流信号完全消失", "D": "空间分辨率下降", "E": "扫描时间缩短"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-009", "kp": "PC-MRA速度编码", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】VENC代表能无混叠测量的最大流速。VENC设置过低时，血流速度超过编码范围，相位角超过±180°产生相位卷褶（混叠/aliasing），故B正确。\n【为什么错】A：背景抑制取决于静止组织的相位，与VENC高低无关。C：血流信号不会完全消失，而是相位错误。D：空间分辨率由矩阵、FOV等决定，与VENC无关。E：VENC不影响扫描时间。", "tr": "VENC过低→相位卷褶；VENC过高→流动敏感度下降、慢血流显示差；需按目标流速设定。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1010", "t": "单选题", "s": "CE-MRA（对比增强MRA）利用钆对比剂增强血管信号的机制是", "o": {"A": "缩短血液的T1弛豫时间", "B": "延长血液的T2弛豫时间", "C": "增强血液的流入效应", "D": "抑制周围脂肪信号", "E": "增大血流速度"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-010", "kp": "CE-MRA增强机制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】钆对比剂为T1短缩剂，使血液T1显著缩短，在T1加权快速梯度回波序列中呈现明显高信号，血管与周围组织对比增强，故A正确。\n【为什么错】B：钆剂主要缩短T1，高浓度时也可缩短T2，但“延长T2”不正确。C：流入增强是TOF-MRA的机制。D：脂肪抑制仅改善背景，非增强机制。E：对比剂不改变血流速度。", "tr": "CE-MRA＝重T1加权＋钆剂团注；与TOF（流入增强）机制截然不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1011", "t": "单选题", "s": "为保证CE-MRA动脉期采集时机准确，最常用的方法是", "o": {"A": "固定注射后立即扫描", "B": "对比剂跟踪（bolus tracking）实时监测到达后再启动扫描", "C": "先打完全部对比剂再开始扫描", "D": "用T2加权序列监测对比剂", "E": "按体重匀速注射后30分钟扫描"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-011", "kp": "CE-MRA对比剂跟踪", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】CE-MRA要求在对比剂首次通过靶血管时采集动脉期，用对比剂跟踪（bolus tracking）或团注测试法实时监测，在对比剂到达时自动触发扫描，可准确捕捉动脉期，故B正确。\n【为什么错】A：固定延迟时间个体差异大，动脉期易错过。C：对比剂全部注入后再扫，动静脉重叠明显。D：对比剂跟踪在T1加权透视监测，非T2加权。E：30分钟为延迟扫描时间，动静脉均已强化，无动脉期意义。", "tr": "CE-MRA成败关键在于“首过动脉期”，对比剂跟踪/团注测试是标准做法。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1012", "t": "单选题", "s": "MRA原始图像的后处理常采用的重建方式是", "o": {"A": "最大密度投影（MIP）", "B": "表面遮盖显示（SSD）", "C": "仿真内镜", "D": "多平面重组（MPR）的矢状重建", "E": "容积再现的密度阈值分割"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-012", "kp": "MRA后处理MIP", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】MRA原始图像经最大密度投影（MIP）沿一定方向投影，取最大信号像素构成血管影像，可多角度旋转观察血管走行与分支，是MRA最常用的后处理方式，故A正确。\n【为什么错】B：SSD为表面重建，用于骨表面等显示，血管内部结构显示不佳。C：仿真内镜用于管腔内部观察，非血管整体显示常规手段。D：MPR为二维任意层面重组，非MRA血管显示的常规方法。E：密度阈值分割主要用于CTA骨血管分离，MRA血管与背景对比高，以MIP为主。", "tr": "MRA（尤其CE-MRA与TOF）经典后处理＝MIP旋转重组。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1013", "t": "单选题", "s": "MRCP（磁共振胰胆管成像）的成像原理是", "o": {"A": "重T2加权成像使含液体结构呈高信号", "B": "重T1加权成像增强胆管信号", "C": "利用流入增强效应显示胰胆管", "D": "利用相位对比显示胆汁流动", "E": "利用弥散加权抑制胆汁信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-013", "kp": "MRCP成像原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRCP属于MR水成像，采用重T2加权序列（长TE），使胆汁、胰液等静态液体呈高信号，而周围软组织与实性器官信号被衰减，从而勾画胰胆管树，故A正确。\n【为什么错】B：T1加权下胆汁为低信号，不能显示胰胆管。C：流入增强为MRA机制。D：相位对比用于流速定量，不用于水成像。E：弥散加权会抑制胆汁信号，与水成像相反。", "tr": "MR水成像一律“重T2、长TE”，高信号＝水，低信号＝实质组织。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1014", "t": "单选题", "s": "关于MRCP检查技术的叙述，错误的是", "o": {"A": "常规采用快速自旋回波（FSE/TSE）序列", "B": "可结合3D薄层与2D厚层厚板投影扫描", "C": "扫描过程需抑制呼吸运动影响", "D": "TE应选择较短值以保留胆管信号", "E": "多采用屏气或呼吸触发方式采集"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-014", "kp": "MRCP技术要点", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRCP为突出水信号须采用长TE（如600～1000 ms），TE过短则背景软组织信号未被充分抑制，故“选择较短TE”错误，本题选D。\n【为什么错】A：FSE/TSE对磁场不均匀不敏感、信噪比好，为MRCP首选，正确。B：3D薄层可任意重建、2D厚层块成像快捷，常联合使用，正确。C：呼吸运动是腹部成像主要伪影来源，须控制，正确。E：屏气或呼吸触发为常规呼吸运动控制方式，正确。", "tr": "水成像“长TE抑制背景”与常规T1/T2“短TE保留信号”逻辑相反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1015", "t": "单选题", "s": "MRU（磁共振尿路成像）主要用于显示", "o": {"A": "肾血管狭窄", "B": "输尿管及肾盂的扩张积水", "C": "肾实质灌注", "D": "膀胱壁厚度", "E": "肾小球滤过功能"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-015", "kp": "MRU应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRU为泌尿系水成像，重T2加权使肾盂、肾盏、输尿管、膀胱内尿液呈高信号，主要用于显示梗阻性积水、输尿管结石继发的扩张及尿路解剖畸形，故B正确。\n【为什么错】A：肾血管显示用MRA。C：肾实质灌注用PWI/动态增强。D：膀胱壁厚度观察用常规薄层序列。E：滤过功能评估不属于MRU范畴。", "tr": "MRU=尿路水成像，仅显示“含水管道”形态，不反映功能与血管。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1016", "t": "单选题", "s": "MRM（磁共振脊髓造影）的检查目的是", "o": {"A": "观察脊髓蛛网膜下腔内脑脊液的形态", "B": "测量脊髓血流量", "C": "显示脊髓的弥散受限", "D": "评价脑干听觉通路", "E": "显示椎间盘内退变信号"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-016", "kp": "MRM应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRM利用重T2水成像显示脊髓蛛网膜下腔脑脊液形态，可直观观察椎管内占位、粘连、神经根袖及硬膜囊受压情况，类似X线脊髓造影而无创，故A正确。\n【为什么错】B：血流量测量为PC-MRA功能。C：弥散受限为DWI。D：听觉通路评价属fMRI/电生理范畴。E：椎间盘退变信号用常规T1/T2序列评价。", "tr": "MRM显示的是“脑脊液影”，对神经根、蛛网膜病变显示好，但不能直接显示脊髓内部信号。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1017", "t": "单选题", "s": "颅脑DWI扫描中，评价急性脑梗死最常用的b值为", "o": {"A": "b=0 s/mm²", "B": "b=500 s/mm²", "C": "b=1000 s/mm²", "D": "b=2000 s/mm²", "E": "b=4000 s/mm²"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-017", "kp": "DWI b值", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】颅脑常规DWI常用b=1000 s/mm²，在保证弥散权重的同时兼顾信噪比，是急性脑梗死诊断的常规设置，故C正确。\n【为什么错】A：b=0无弥散加权，仅作基线。B：b=500弥散权重不足，弥散受限病灶显示不敏感。D：b=2000常用于体部高b值或超高弥散成像，信噪比下降。E：b=4000属超高b值研究性应用，常规不用。", "tr": "b值越大弥散权重越大、信号越低；颅脑急性梗死常规b=1000 s/mm²。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1018", "t": "单选题", "s": "关于DWI中ADC值的叙述，正确的是", "o": {"A": "ADC值反映水分子扩散受限的程度", "B": "扩散受限时ADC值升高", "C": "ADC图高信号提示扩散受限", "D": "ADC值与b值无关", "E": "ADC值越大扩散受限越明显"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-018", "kp": "ADC值与扩散受限", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】ADC值（表观弥散系数）定量反映水分子扩散程度，细胞毒性水肿使水分子扩散受限、ADC值降低，故A正确。\n【为什么错】B：扩散受限时ADC降低而非升高。C：ADC图上扩散受限区呈低信号（灰暗）。D：ADC由不同b值图像计算得出，与b值设定直接相关。E：ADC越小扩散受限越明显，方向相反。", "tr": "“DWI高信号+ADC低信号”才是扩散受限的完整组合；单看DWI可受T2穿透效应干扰。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1019", "t": "单选题", "s": "DWI图像上病灶呈高信号而ADC图信号无明显降低，最可能的原因是", "o": {"A": "急性脑梗死细胞毒性水肿", "B": "T2穿透效应（shine-through）", "C": "血肿含铁血黄素沉积", "D": "弥散系数真实下降", "E": "梯度线圈故障"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-019", "kp": "T2穿透效应", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】DWI除弥散权重外还含T2权重，当病灶T2信号本底很高时，DWI可呈高信号但ADC值正常或升高，此即T2穿透效应（shine-through），结合ADC图可鉴别，故B正确。\n【为什么错】A：急性梗死扩散受限时ADC应明显降低，与本例不符。C：含铁血黄素为顺磁性物质，在SWI上明显，不是DWI高信号的原因。D：若弥散系数真实下降，ADC应降低，与题干不符。E：线圈故障表现为全图伪影，与病灶局限信号不符。", "tr": "判读DWI必须结合ADC：DWI高+ADC低＝真扩散受限；DWI高+ADC正常＝T2穿透效应。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U10-1020", "t": "单选题", "s": "DTI（扩散张量成像）中最常用的量化指标是", "o": {"A": "各向异性分数（FA）", "B": "横向弛豫时间T2", "C": "纵向弛豫时间T1", "D": "速度编码值VENC", "E": "磁化传递率MTR"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-020", "kp": "DTI指标", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】DTI利用多个梯度方向测量水分子扩散的各向异性，以各向异性分数（FA）定量反映白质纤维束完整性，并可行纤维束示踪（tractography），故A正确。\n【为什么错】B：T2为常规弛豫参数，非DTI指标。C：T1为纵向弛豫参数。D：VENC为PC-MRA参数。E：MTR为磁化传递成像指标，反映大分子结合水。", "tr": "DTI核心参数FA（0～1），白质纤维走行区FA高、破坏后降低。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1021", "t": "单选题", "s": "下列不属于PWI（灌注加权成像）常用灌注参数的是", "o": {"A": "相对脑血流量（rCBF）", "B": "相对脑血容量（rCBV）", "C": "平均通过时间（MTT）", "D": "达峰时间（TTP）", "E": "各向异性分数（FA）"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-021", "kp": "PWI灌注参数", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】PWI灌注参数包括rCBF、rCBV、MTT、TTP等，反映微循环血流状态；FA为DTI各向异性分数，不属于灌注参数，故E正确。\n【为什么错】A：rCBF相对脑血流量为灌注参数，正确。B：rCBV相对脑血容量为灌注参数，正确。C：MTT平均通过时间为灌注参数，正确。D：TTP达峰时间为灌注参数，正确。", "tr": "PWI参数rCBF/rCBV/MTT/TTP与DTI参数FA分属不同功能成像，勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1022", "t": "单选题", "s": "有关BOLD-fMRI（血氧水平依赖功能磁共振）的叙述，正确的是", "o": {"A": "神经元活动增强时局部血流增加，脱氧血红蛋白相对减少，T2*信号升高", "B": "神经元活动时局部脱氧血红蛋白增加，信号升高", "C": "该技术主要基于T1弛豫变化", "D": "需静脉注射钆对比剂才能成像", "E": "其激活区在T2加权像上呈低信号"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-022", "kp": "BOLD-fMRI原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】BOLD-fMRI基于血氧水平依赖效应：脑功能区激活时局部脑血流与氧合血红蛋白增加、脱氧血红蛋白（顺磁性）浓度相对降低，T2*加权信号轻度升高，故A正确。\n【为什么错】B：激活时脱氧血红蛋白减少而非增加。C：BOLD效应基于T2*加权，与T1弛豫无关。D：BOLD为非侵入性检查，无需对比剂。E：激活区在T2*加权像上呈高信号而非低信号。", "tr": "BOLD＝局部血流↑→脱氧Hb↓→T2*信号↑，方向链条是高频考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1023", "t": "单选题", "s": "SWI（磁敏感加权成像）的成像基础是", "o": {"A": "组织间磁化率差异引起的相位与幅度改变", "B": "T1弛豫时间的差异", "C": "血流的流入增强", "D": "弥散系数的差异", "E": "脂肪与水化学位移的消长"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-023", "kp": "SWI成像原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】SWI利用不同组织间磁化率（磁敏感性）差异，通过高分辨率3D梯度回波同时获得幅度图与相位图，并将相位信息处理后合成，对静脉血、出血、铁沉积等高磁敏感结构敏感，故A正确。\n【为什么错】B：T1弛豫差异是T1加权成像的基础。C：流入增强是TOF-MRA的基础。D：弥散差异是DWI的基础。E：脂肪水化学位移是化学位移成像的基础。", "tr": "SWI关键词“磁化率/磁敏感性差异+相位图”，与DWI、MRA机制区分。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1024", "t": "单选题", "s": "SWI临床应用中最具优势的方面是", "o": {"A": "显示小静脉、微出血及铁沉积", "B": "评价椎间盘退变程度", "C": "测量血流速度", "D": "显示乳腺导管结构", "E": "评价肝脏脂肪含量"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-024", "kp": "SWI临床应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】SWI对磁化率差异极敏感，是显示脑内微小静脉、微出血（含铁血黄素）、脑淀粉样血管病及帕金森病铁沉积的最佳序列，故A正确。\n【为什么错】B：椎间盘退变用常规T2/矢状位序列。C：流速测量为PC-MRA。D：乳腺导管显示用乳腺专用序列与增强。E：肝脏脂肪定量用Dixon或MRS。", "tr": "SWI最擅长“出血、铁、小静脉”，所谓“类CT钙化”也依赖相位图鉴别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1025", "t": "单选题", "s": "关于MRS（磁共振波谱）的叙述，正确的是", "o": {"A": "单体素MRS为在选定的单个体素内获取波谱", "B": "MRS直接给出组织的解剖图像", "C": "多体素波谱无法覆盖较大区域", "D": "MRS不需匀场与抑水", "E": "MRS只能用长TE采集"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-025", "kp": "MRS单体素", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】单体素MRS（single-voxel）通过三个正交层面相交选择单一立方体（体素）内采集波谱，定位准确、时间短，是临床常规方法，故A正确。\n【为什么错】B：MRS输出代谢物谱线而非解剖图像。C：多体素（CSI）可覆盖较大区域并生成代谢图，覆盖区域更大。D：MRS须先匀场并抑制水峰，否则谱线被水峰掩盖。E：MRS可用短TE（35 ms）与长TE（135～144 ms）两种采集，各有利弊。", "tr": "MRS质量控制三要素：匀场、抑水、定位；单体素与多体素按临床需求选择。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1026", "t": "单选题", "s": "正常成人大脑MRS中，位于2.02 ppm、作为神经元标志物的代谢物是", "o": {"A": "N-乙酰天门冬氨酸（NAA）", "B": "胆碱（Cho）", "C": "肌酸（Cr）", "D": "乳酸（Lac）", "E": "脂质（Lip）"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-026", "kp": "MRS代谢物NAA", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】NAA位于2.02 ppm，仅存在于神经元内，是神经元密度与活力的标志，正常脑内为最高峰，故A正确。\n【为什么错】B：Cho位于3.2 ppm，反映细胞膜磷脂代谢，肿瘤时升高。C：Cr位于3.0 ppm，反映能量代谢，相对稳定常作参照。D：Lac位于1.33 ppm双峰，正常脑内测不到，缺氧时出现。E：Lip位于0.9～1.3 ppm，见于坏死与肿瘤。", "tr": "代谢物-化学位移-临床意义三位一体记忆：NAA 2.02（神经元）、Cho 3.2（膜）、Cr 3.0（能量）、Lac 1.33（缺氧）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1027", "t": "单选题", "s": "脑肿瘤MRS的典型代谢物改变是", "o": {"A": "Cho升高、NAA降低", "B": "NAA升高、Cho降低", "C": "Cr显著升高", "D": "NAA显著升高、Lac消失", "E": "Cho降低、Lac升高且NAA正常"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-027", "kp": "脑肿瘤MRS代谢改变", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】肿瘤细胞增殖使膜磷脂代谢增强，Cho升高；神经元被肿瘤取代破坏，NAA下降；部分肿瘤还可出现Lac峰，故“Cho↑、NAA↓”是脑肿瘤MRS典型改变，A正确。\n【为什么错】B：NAA不会升高，Cho不会降低。C：Cr相对稳定，不显著升高。D：NAA显著升高不符合肿瘤。E：肿瘤时Cho应升高而非降低，且NAA应下降。", "tr": "脑肿瘤谱“Cho↑NAA↓Lac可有”；NAA下降程度常反映神经元丢失程度。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1028", "t": "单选题", "s": "MR成像中放置预饱和带（空间饱和带）的主要目的是", "o": {"A": "抑制运动、血流等来源的信号以减轻伪影", "B": "提高图像的信噪比", "C": "加快扫描速度", "D": "增大有效视野", "E": "提高脂肪组织信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-028", "kp": "预饱和带作用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】预饱和带在数据采集前先对特定区域施加饱和脉冲，使该区域（如血管上游血流、肠管蠕动区、胸壁脂肪）信号被压低，从而抑制流动伪影与运动伪影，故A正确。\n【为什么错】B：饱和脉冲不增加信号，反而可能略降信噪比。C：饱和带不缩短采集时间。D：视野大小由FOV参数决定。E：饱和带是压低信号而非提高脂肪信号。", "tr": "预饱和带是“牺牲局部信号换全图伪影减少”，方向是抑制而非增强。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1029", "t": "单选题", "s": "为抑制主动脉血流搏动伪影，预饱和带应放置在", "o": {"A": "兴趣区的两侧平行于血管走行", "B": "兴趣区的血流上游方向", "C": "磁体中心", "D": "扫描床下方", "E": "频率编码方向"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-029", "kp": "预饱和带放置原则", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】预饱和带需置于血流进入兴趣区之前的“上游”，使流入的血液质子预先饱和、到达成像区时信号已很低，从而抑制搏动血流伪影，故B正确。\n【为什么错】A：饱和带垂直于血管走行方向放置才有效，平行放置无意义。C：磁体中心为成像区本身。D：床下方无针对性。E：频率编码方向与血流抑制无关。", "tr": "“上游饱和”原则：先饱和再流入，才能抑制流动伪影；放置方向须垂直于血管走行。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1030", "t": "单选题", "s": "STIR（短TI反转恢复）脂肪抑制的原理是", "o": {"A": "选择TI使脂肪信号过零点而被抑制", "B": "用频率选择脉冲饱和脂肪峰", "C": "利用梯度破坏脂肪信号", "D": "脂肪的T2*衰减快", "E": "脂肪血供少信号低"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-030", "kp": "STIR原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】STIR采用180°反转脉冲后，脂肪纵向磁化恢复较快，选择TI≈脂肪T1×0.69，使脂肪纵向磁化恢复至零点时采集信号，脂肪信号被抑制，故A正确。\n【为什么错】B：频率选择脉冲饱和脂肪峰是CHESS的原理。C：梯度破坏信号用于梯度回波去相位。D：T2*衰减快非脂肪抑制机制。E：脂肪信号高低与血供无关。", "tr": "STIR靠“TI时间点”抑制脂肪、对磁场不均匀不敏感；CHESS靠“频率选择性”饱和、对匀场敏感。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1031", "t": "单选题", "s": "在1.5T场强下，STIR序列抑制脂肪常用的反转时间（TI）约为", "o": {"A": "20 ms", "B": "150 ms", "C": "500 ms", "D": "2000 ms", "E": "2500 ms"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-031", "kp": "STIR的TI值", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】脂肪T1在1.5T约250 ms，取0.69倍约150～170 ms，故1.5T下STIR常用TI约150 ms，使脂肪信号过零而被抑制，B正确。\n【为什么错】A：20 ms为反转恢复序列的常规短TI，用于灰白质对比，不抑制脂肪。C：500 ms接近脑灰质反转点，非脂肪抑制。D：2000 ms与FLAIR的TI接近。E：2500 ms以上为FLAIR（3T）所用，用于抑制脑脊液。", "tr": "TI数值对比：STIR≈150 ms（1.5T）抑脂肪，FLAIR≈2200 ms（1.5T）抑脑脊液。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1032", "t": "单选题", "s": "关于CHESS（化学位移选择性饱和）脂肪抑制技术的叙述，正确的是", "o": {"A": "利用频率选择脉冲选择性饱和脂肪质子", "B": "对磁场均匀性不敏感", "C": "抑制脂肪的特异性低于STIR", "D": "不能用于增强扫描", "E": "只能抑制水信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-032", "kp": "CHESS脂肪抑制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】CHESS先施加中心频率对准脂肪共振频率的窄带饱和脉冲，再行成像序列，使脂肪信号被选择性压低，故A正确。\n【为什么错】B：CHESS对磁场均匀性高度敏感，匀场不良时脂肪抑制失败。C：CHESS抑制脂肪特异性高（只抑脂肪），而STIR抑制所有短T1组织。D：CHESS可用于增强扫描，不影响钆剂效应。E：CHESS抑制的是脂肪峰，不是水峰。", "tr": "CHESS“频率选择性、特异性高、依赖匀场”；STIR“TI法、不依赖匀场、特异性差”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1033", "t": "单选题", "s": "SPIR（谱预饱和反转恢复）技术属于", "o": {"A": "频率选择性脂肪抑制技术", "B": "水激励技术", "C": "相位对比技术", "D": "速度编码技术", "E": "弥散加权技术"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-033", "kp": "SPIR/SPAIR", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】SPIR与SPAIR是飞利浦等厂家的脂肪抑制技术，属谱预饱和反转恢复，即先对脂肪频率进行选择性反转再采集，本质为频率选择性脂肪抑制，故A正确。\n【为什么错】B：水激励用于抑制脂肪突出水，与SPIR不同。C：相位对比为PC-MRA机制。D：速度编码为PC定量参数。E：弥散加权为DWI。", "tr": "SPIR/SPAIR/CHESS同属“频率选择性脂肪抑制”；STIR属“TI反转脂肪抑制”，两类要分清。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1034", "t": "单选题", "s": "Dixon水脂分离技术的优势在于", "o": {"A": "一次采集可同时得到水像、脂像及同/反相位图", "B": "对磁场不均匀完全不敏感", "C": "只能用于肝脏", "D": "不需额外扫描时间", "E": "只抑制脂肪而无法显示脂肪"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-034", "kp": "Dixon技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】Dixon利用水脂化学位移相位差，通过两点、三点或四点采集一次获得同相位、反相位、纯水、纯脂四组图像，可同时进行脂肪抑制与脂肪定量，故A正确。\n【为什么错】B：两点Dixon对磁场不均仍敏感，三点以上才更稳健。C：Dixon可应用于全身各部位，非仅肝脏。D：Dixon需多回波采集，扫描时间较单回波略长。E：Dixon可生成脂像定量脂肪，并非只抑制脂肪。", "tr": "Dixon“一次出四图（水/脂/同相/反相）”，兼具抑脂与脂肪定量功能。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1035", "t": "单选题", "s": "FLAIR（液体衰减反转恢复）序列被抑制的信号来自", "o": {"A": "脑脊液", "B": "脂肪", "C": "水脂交界区", "D": "骨骼", "E": "血流"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-035", "kp": "FLAIR水抑制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】FLAIR采用长TI反转恢复，使脑脊液信号过零被抑制，得到“T2加权但脑脊液为低信号”的图像，从而更清晰显示脑室旁、皮层等靠近脑脊液的病灶，故A正确。\n【为什么错】B：抑制脂肪是STIR的功能。C：水脂交界信号抑制为化学位移成像概念。D：骨骼本身信号低，无需专门抑制。E：抑制血流主要用饱和带或反转血流技术。", "tr": "FLAIR“抑水（脑脊液）”，STIR“抑脂”，一字之差，TI完全不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1036", "t": "单选题", "s": "在1.5T场强下，颅脑T2-FLAIR序列常用的反转时间（TI）约为", "o": {"A": "150 ms", "B": "500 ms", "C": "2200 ms", "D": "4000 ms", "E": "8000 ms"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-036", "kp": "FLAIR的TI值", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】脑脊液T1在1.5T约2000 ms以上，取0.69倍约2200 ms，使脑脊液信号过零，故1.5T下FLAIR常用TI约2000～2500 ms，C正确。\n【为什么错】A：150 ms为STIR抑脂肪的TI。B：500 ms接近灰质反转点。D：4000 ms使脑脊液已恢复为高信号，无法抑制。E：8000 ms更不可能抑制脑脊液。", "tr": "TI记忆口诀：抑脂肪150 ms（1.5T STIR），抑脑脊液2200 ms（1.5T FLAIR）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1037", "t": "单选题", "s": "呼吸门控技术主要用于减少", "o": {"A": "呼吸运动引起的伪影", "B": "化学位移伪影", "C": "金属伪影", "D": "截断伪影", "E": "卷褶伪影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-037", "kp": "呼吸门控应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】呼吸门控（呼吸触发/呼吸补偿）根据呼吸周期在呼气末相对平稳期采集数据，或将呼吸运动信号与K空间采集关联，从而减少呼吸运动伪影，常用于胸腹部成像，故A正确。\n【为什么错】B：化学位移伪影发生在水脂交界，由频率编码所致。C：金属伪影由磁化率差异引起。D：截断伪影发生在高对比界面。E：卷褶伪影因FOV小于解剖范围所致。", "tr": "运动伪影（呼吸/心跳/蠕动）用门控、触发与屏气解决；伪影分类是高频辨析考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1038", "t": "单选题", "s": "心脏MR检查中心电门控（ECG gating）的作用是", "o": {"A": "在心动周期特定时相采集以减少心脏搏动伪影", "B": "加速对比剂在心脏内的循环", "C": "消除金属伪影", "D": "提高脂肪抑制效果", "E": "缩短T1弛豫"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-038", "kp": "心电门控", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】心电门控以心电图R波为触发信号，将数据采集锁定在心动周期中运动相对轻微的时相（如舒张末期），从而减少心脏搏动伪影、获得清晰的心脏图像，故A正确。\n【为什么错】B：门控不改变血流循环。C：金属伪影由磁敏感性引起，与门控无关。D：脂肪抑制为预脉冲技术。E：T1弛豫为组织固有特性，与门控无关。", "tr": "心电门控=“心电信号→触发采集”，配合黑血/亮血、电影序列完成心脏形态与功能评价。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1039", "t": "单选题", "s": "导航回波（Navigator）技术的主要用途是", "o": {"A": "实时监测膈肌位置，实现自由呼吸下的心脏、腹部成像", "B": "监测患者心率", "C": "消除化学位移伪影", "D": "提高主磁场均匀性", "E": "测量对比剂浓度"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-039", "kp": "导航回波", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】导航回波在成像区外（如右侧膈顶）实时采集一维回波监测呼吸运动导致的膈肌位置变化，据此校正或触发采集，使患者在自由呼吸下完成心脏冠状动脉及肝脏成像，故A正确。\n【为什么错】B：心率监测为心电门控功能。C：化学位移伪影与频率编码有关，导航无法消除。D：匀场为硬件调节过程。E：对比剂浓度测量非导航功能。", "tr": "导航回波解决“自由呼吸”问题（膈肌追踪）；心电门控解决“心跳”问题；呼吸门控用呼吸带。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1040", "t": "单选题", "s": "颅脑MR平扫的常规序列组合是", "o": {"A": "轴位T1WI、T2WI、FLAIR及DWI", "B": "仅矢状位T1WI", "C": "冠状位STIR加增强扫描", "D": "轴位脂肪抑制加MRS", "E": "仅DWI加MRV"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-040", "kp": "颅脑常规序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】颅脑MR平扫常规包括轴位T1WI、T2WI、FLAIR与DWI，分别观察解剖结构、常规病灶、近脑脊液病灶与急性缺血，必要时加矢状/冠状位，故A正确。\n【为什么错】B：仅矢状位无法全面评价幕上幕下病变。C：STIR加增强为补充方案，非平扫常规。D：MRS为功能成像，非常规平扫。E：DWI+MRV无法提供T1/T2结构信息，不完整。", "tr": "颅脑平扫“T1+T2+FLAIR+DWI”四件套是基础，增强与功能序列视临床需要补充。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1041", "t": "单选题", "s": "颅脑增强扫描完成后，观察病灶强化情况宜采用的序列是", "o": {"A": "T1WI（含脂肪抑制）", "B": "T2WI", "C": "FLAIR", "D": "DWI", "E": "SWI"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-041", "kp": "颅脑增强扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】钆对比剂缩短T1，强化组织在T1WI上呈高信号，增强后扫描T1WI（必要时加脂肪抑制以排除头皮脂肪干扰）是观察强化灶的标准序列，故A正确。\n【为什么错】B：T2WI对强化不敏感。C：FLAIR主要用于水抑制观察。D：DWI反映扩散受限，虽可间接观察强化，但非强化评价标准。E：SWI反映磁敏感性，与强化无关。", "tr": "增强扫描“看强化=看T1”，增强后T1+脂肪抑制是血脑屏障破坏病灶的标准显示。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1042", "t": "单选题", "s": "临床疑海马硬化所致颞叶癫痫时，海马区扫描的最佳方位是", "o": {"A": "垂直于海马长轴的斜冠状位薄层扫描", "B": "横断位厚层扫描", "C": "矢状位正中扫描", "D": "仅轴位DWI", "E": "冠状位STIR厚层扫描"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-042", "kp": "海马高分辨扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】海马长轴与颅底约呈夹角，采用垂直于海马长轴的斜冠状位薄层（2～3 mm）高分辨T2/3D-T1扫描，可清晰显示海马形态、信号及体积改变，利于海马硬化诊断，故A正确。\n【为什么错】B：横断厚层不能沿海马长轴完整显示海马头体尾。C：矢状正中位仅显示海马中段。D：DWI非海马硬化评估主要序列。E：STIR厚层分辨率不足。", "tr": "海马癫痫扫描关键词“斜冠状位+垂直于海马长轴+薄层高分辨”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1043", "t": "单选题", "s": "疑垂体微腺瘤时，垂体区MR扫描技术要点是", "o": {"A": "薄层小FOV矢状位及冠状位扫描并行动态增强", "B": "厚层大FOV轴位扫描", "C": "仅平扫不需增强", "D": "只扫描矢状位", "E": "用DWI替代T1WI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-043", "kp": "垂体微腺瘤扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】垂体微腺瘤体积小，须薄层（2～3 mm）、小FOV、高分辨矢状位与冠状位扫描，并行动态增强观察早期低强化区，故A正确。\n【为什么错】B：厚层大FOV空间分辨率不足，微腺瘤易漏诊。C：增强对发现微腺瘤至关重要，不能仅平扫。D：矢状位单方位无法全面显示垂体与鞍底关系。E：DWI不能替代T1WI观察垂体形态与强化。", "tr": "微腺瘤“小病灶小FOV薄层+动态增强”；动态增强应观察垂体中位强化延迟区。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1044", "t": "单选题", "s": "脊柱MRI检查最常用的基础扫描方位是", "o": {"A": "矢状位T1WI及T2WI加横断位", "B": "仅冠状位扫描", "C": "轴位DWI", "D": "矢状位MRA", "E": "横断位MRS"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-044", "kp": "脊柱常规扫描方位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】脊柱MRI以矢状位T1WI、T2WI观察椎体序列、椎间盘与椎管全貌，配合横断位观察椎间盘突出程度、神经根及椎管内结构，为常规组合，故A正确。\n【为什么错】B：冠状位为辅助方位，不能单独用于脊柱评价。C：DWI仅用于部分病变。D：MRA不用于脊柱常规。E：MRS不用于脊柱常规检查。", "tr": "脊柱MR“矢状位+横断位”双方位为常规；颈椎段还常加横断T1/T2评估椎动脉与神经根。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1045", "t": "单选题", "s": "为准确判断颈椎间盘突出对神经根的压迫，最关键的扫描方位是", "o": {"A": "横断位", "B": "冠状位", "C": "矢状位仅T1WI", "D": "矢状位水成像", "E": "斜矢状位MRS"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-045", "kp": "颈椎间盘突出扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】横断位可显示椎间盘向椎管内突出的程度、方向及其与脊髓、双侧神经根的关系，是判断神经根受压的关键断面，故A正确。\n【为什么错】B：冠状位对神经根走行显示有限。C：矢状位仅T1WI显示间盘与脊髓前后关系，无法直接判断侧方压迫。D：水成像显示脑脊液形态，间接信息。E：MRS与神经根受压判断无关。", "tr": "“矢状位看全貌、横断位看压迫细节”，神经根受累必须依赖横断位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1046", "t": "单选题", "s": "疑脊髓炎性病变时，除常规矢状位外还应重点加做的序列是", "o": {"A": "横断位T2WI及增强后T1WI", "B": "冠位MRA", "C": "颅脑DWI", "D": "MRS定量", "E": "体部DWIBS"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-046", "kp": "脊髓病变序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】脊髓炎等病变在矢状位T2WI可见异常信号，横断位T2WI可明确病灶在脊髓内的部位与范围，增强后T1WI观察强化（活动期炎性强化），三者结合为脊髓炎标准方案，故A正确。\n【为什么错】B：MRA用于血管，与脊髓炎无关。C：颅脑DWI与脊髓病变无直接关系。D：MRS在脊髓应用受限，非常规。E：DWIBS为全身弥散背景抑制，用于肿瘤筛查。", "tr": "脊髓病变检查“矢状+T2横断+增强T1”三步走；横断位对病灶定位至关重要。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1047", "t": "单选题", "s": "鼻咽癌MR检查中，为全面评价肿瘤侵犯范围与颈部淋巴结，扫描范围应", "o": {"A": "包括颅底及颈部全颈，采用轴位加矢状位扫描", "B": "仅扫描鼻咽局部轴位", "C": "仅扫描颈部淋巴结区", "D": "只做横断T2WI", "E": "只扫描下颌区"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-047", "kp": "鼻咽癌MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】鼻咽癌易沿颅底孔道蔓延并发生颈部淋巴结转移，MR扫描范围应从颅底延伸至锁骨上区，采用轴位加矢状位（必要时冠状位）T1WI、T2WI脂肪抑制及增强扫描，故A正确。\n【为什么错】B：仅鼻咽局部轴位漏诊颅底侵犯与颈部转移。C：仅扫描淋巴结遗漏原发灶。D：仅横断T2WI无法评价颅底骨质与增强强化。E：下颌区范围过小。", "tr": "头颈部恶性肿瘤MR“范围要大（颅底到锁骨上）、方位要全、必须增强”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1048", "t": "单选题", "s": "显示视神经及眶内病变时，MR扫描宜采用的脂肪抑制序列是", "o": {"A": "T2WI脂肪抑制或STIR", "B": "T1WI不抑脂", "C": "质子密度加权", "D": "MRA", "E": "SWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-048", "kp": "眼眶MR脂肪抑制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】眶内富含脂肪，T1、T2高信号脂肪会掩盖视神经及眶内病变，采用T2WI脂肪抑制或STIR可压低脂肪信号，突出显示视神经、眼外肌及病变，故A正确。\n【为什么错】B：不抑脂的T1WI脂肪高信号干扰病变显示。C：PD加权对眶内脂肪抑制无帮助。D：MRA显示血管而非神经。E：SWI用于出血与钙化。", "tr": "眶内病变“抑脂T2/STIR”是显示视神经与眼外肌的关键，与颅脑扫描习惯不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1049", "t": "单选题", "s": "喉部MR扫描为避免吞咽运动伪影，常采取的措施是", "o": {"A": "嘱患者平静呼吸，必要时分次短时屏气采集", "B": "加大翻转角", "C": "缩短回波链", "D": "改用弥散加权", "E": "加大矩阵而忽略运动"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-049", "kp": "喉部MR伪影控制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】吞咽与说话引起喉部运动伪影，需嘱患者尽量平静呼吸、避免吞咽，采用快速序列并分次短时屏气采集，以抑制运动伪影，故A正确。\n【为什么错】B：翻转角不影响运动伪影。C：回波链长短与运动伪影无直接关系。D：DWI不能替代常规结构显示。E：单纯加大矩阵延长扫描时间，反而加重运动伪影。", "tr": "喉部扫描“配合吞咽与呼吸”是图像质量关键，快序列+短采集是常规策略。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1050", "t": "单选题", "s": "乳腺MR检查的常规体位与线圈选择是", "o": {"A": "俯卧位、专用乳腺相控阵线圈", "B": "仰卧位、体部线圈", "C": "侧卧位、头线圈", "D": "俯卧位、脊柱线圈", "E": "仰卧位、表面线圈置于胸前"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-050", "kp": "乳腺MR检查体位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】乳腺MR采用俯卧位，双乳自然下垂置于专用乳腺相控阵线圈的孔槽内，既贴合乳腺又减少呼吸运动影响，故A正确。\n【为什么错】B：仰卧位乳腺受重力压扁且远离线圈，图像差。C：头线圈用于头颅。D：脊柱线圈不贴合乳腺形态。E：表面线圈单侧放置覆盖不全。", "tr": "乳腺MRI标志性细节：“俯卧+专用线圈+双乳悬垂”是标准配置。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1051", "t": "单选题", "s": "乳腺动态增强MRI中，呈“快速上升后持续下降”的时间-信号强度曲线，常提示", "o": {"A": "恶性病变可能性大", "B": "良性病变可能性大", "C": "正常腺体组织", "D": "脂肪组织", "E": "检查失败"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-051", "kp": "乳腺动态增强曲线", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】乳腺时间-信号强度曲线Ⅲ型（流出型）：信号快速上升后持续下降（“洗脱”），提示病灶血供丰富、恶性可能性大，故A正确。\n【为什么错】B：Ⅰ型流入型（持续上升）多见于良性病变。C：正常腺体信号上升平缓，不呈流出型。D：脂肪无强化。E：曲线形态反映强化动态，与检查成败无关。", "tr": "曲线三型：Ⅰ流入（良性）、Ⅱ平台（可疑）、Ⅲ流出（恶性），“先升后降”恶性。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1052", "t": "单选题", "s": "心脏MR黑血序列（如双反转恢复）的作用是", "o": {"A": "抑制血液信号，使心腔内血流呈低信号以显示心肌与瓣膜", "B": "增强血液信号显示心腔", "C": "消除呼吸伪影", "D": "抑制脂肪信号", "E": "抑制心肌信号"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-052", "kp": "心脏黑血序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】黑血序列（双反转恢复等）通过反转脉冲使流入心腔的血流信号被抑制，血流呈黑（低信号），从而突出显示心肌、瓣膜与心腔壁结构，故A正确。\n【为什么错】B：增强血流显示心腔为亮血序列（如SSFP）功能。C：呼吸伪影由导航或屏气控制。D：脂肪抑制为另一类预脉冲。E：抑制的是血流而非心肌信号。", "tr": "心脏MR“黑血看壁（心肌）、亮血看腔（功能电影）”，两者互补。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1053", "t": "单选题", "s": "心肌梗死延迟强化（LGE）扫描的时相与序列是", "o": {"A": "注射钆剂后10～15分钟行反转恢复T1加权扫描", "B": "注射对比剂前平扫", "C": "注射后立即用T2加权扫描", "D": "注射后24小时扫描", "E": "无需注射对比剂用DWI扫描"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-053", "kp": "心肌延迟强化LGE", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】钆剂在坏死/纤维化心肌中滞留较久，注射后10～15分钟采用反转恢复T1加权序列扫描，正常心肌信号被抑制而坏死心肌呈高信号，即LGE，为心肌梗死诊断经典技术，故A正确。\n【为什么错】B：平扫无法显示强化。C：T2加权观察心肌水肿（急性期），非延迟强化。D：24小时后对比剂已基本廓清，强化显示差。E：DWI不用于心肌梗死强化评价。", "tr": "LGE关键三要素：“钆剂后10～15分钟+反转恢复T1+正常心肌黑、梗死心肌亮”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1054", "t": "单选题", "s": "主动脉夹层行CE-MRA检查时，为覆盖主动脉全程并捕捉真假腔血流，应采用", "o": {"A": "多期动态扫描与高压注射器团注，配合MIP重建", "B": "单期固定延迟扫描", "C": "2D TOF非增强扫描", "D": "仅矢状位单层扫描", "E": "MRS定量扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-054", "kp": "主动脉CE-MRA", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】主动脉范围大、真假腔血流时序不同，需用高压注射器团注钆剂并行多期动态3D扫描（动脉期、平衡期等），再以MIP旋转重建显示全程主动脉与内膜片，故A正确。\n【为什么错】B：单期固定延迟易错过真腔或假腔充盈时相。C：2D TOF对大血管急性夹层敏感性与时间效率均不足。D：单层无法覆盖全程。E：MRS为波谱技术，与血管成像无关。", "tr": "大血管CE-MRA“多期+团注+覆盖全程+MIP”四要素，真假腔辨别靠多期时相。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1055", "t": "单选题", "s": "肝脏MRI动态增强扫描的常规分期为", "o": {"A": "动脉期、门静脉期、延迟期", "B": "动脉期、静脉期、平衡期三期", "C": "皮质期、髓质期、分泌期", "D": "灌注期、廓清期", "E": "平扫期、增强期两期"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-055", "kp": "肝脏动态增强分期", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肝脏双重血供，动态增强常规采集动脉期、门静脉期与延迟期，以观察富血供肿瘤（动脉期强化）与乏血供肿瘤（门脉期/延迟期改变）及廓清特征，故A正确。\n【为什么错】B：肾脏增强才分皮质期、髓质期、排泄期，且肝脏常规无“静脉期/平衡期”命名。C：皮质髓质期为肾脏分期。D：灌注与廓清非肝三期标准命名。E：两期不足以显示肝脏强化动力学特征。", "tr": "肝脏分期“动脉-门脉-延迟”，肾脏分期“皮质-髓质-排泄”，勿交叉混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1056", "t": "单选题", "s": "腹部MR检查为抑制呼吸运动伪影，下列措施中最关键的是", "o": {"A": "采用屏气扫描或呼吸触发采集", "B": "加大层厚", "C": "缩短回波链", "D": "改用大翻转角", "E": "增加激励次数到最大"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-056", "kp": "腹部呼吸伪影控制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】呼吸运动是腹部MR最大伪影来源，屏气扫描（快速序列）或呼吸触发在呼气末采集，是控制呼吸运动伪影的根本措施，故A正确。\n【为什么错】B：加大层厚降低分辨率，不解决运动。C：回波链长短与运动伪影无直接对应。D：翻转角与呼吸伪影无关。E：盲目增加激励次数延长扫描时间，反而不利。", "tr": "腹部成像“屏气/呼吸触发/导航”三选一必备，是动态增强质量的前提。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1057", "t": "单选题", "s": "临床疑胰腺占位伴胰胆管扩张时，除常规腹部序列外应加做的检查是", "o": {"A": "MRCP与薄层T2加权", "B": "SWI", "C": "MRS单体素", "D": "fMRI-BOLD", "E": "MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-057", "kp": "胰腺MR联合MRCP", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】胰腺病变常引起胰管、胆管扩张，MRCP可无创显示胰胆管树形态、梗阻部位与扩张程度，薄层T2加权观察胰腺实质信号与边缘，二者联合为胰腺MR常规，故A正确。\n【为什么错】B：SWI用于出血铁沉积。C：MRS用于代谢谱，胰腺应用少。D：BOLD用于脑功能。E：MRM为脊髓水成像。", "tr": "胰腺MR“实质（薄层T2/动态增强）+管道（MRCP）”双重评价是规范做法。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1058", "t": "单选题", "s": "肾脏MR检查中，对囊性病变与实性小肿瘤鉴别有重要价值的序列是", "o": {"A": "DWI及ADC图", "B": "MRU", "C": "SWI", "D": "MRA", "E": "MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-058", "kp": "肾脏DWI应用", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】囊性病变水分子扩散自由、ADC值高，实性肿瘤细胞密集、扩散受限、ADC值低，DWI+ADC图对肾脏囊实性病变鉴别有价值（Bosniak分类辅助），故A正确。\n【为什么错】B：MRU显示尿路积水形态，不反映扩散。C：SWI用于出血钙化。D：MRA显示肾血管。E：MRM为脊髓水成像。", "tr": "“囊性ADC高、实性ADC低”是DWI体部应用的通用规律，亦适用于肾脏、肝脏、前列腺。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1059", "t": "单选题", "s": "前列腺癌多参数MRI（mpMRI）的常规序列组合是", "o": {"A": "T2WI、DWI/ADC及动态增强（DCE）", "B": "仅矢状位T1WI", "C": "STIR加MRU", "D": "仅轴位SWI", "E": "MRS加MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-059", "kp": "前列腺mpMRI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】前列腺多参数MRI以T2WI（观察外周带低信号癌灶）、DWI/ADC（扩散受限呈高信号、ADC降低）与动态增强（早期快速强化）为核心，必要时加MRS，故A正确。\n【为什么错】B：仅T1WI无法观察前列腺分区信号。C：MRU为尿路水成像，与前列腺癌无直接关系。D：SWI不用于前列腺癌常规。E：MRM为脊髓水成像。", "tr": "前列腺癌经典表现“外周带T2低信号+DWI高信号+ADC低+早期强化”；DWI低b值注意T2穿透。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1060", "t": "单选题", "s": "子宫体MR检查中，显示子宫内膜与肌层分界的最佳序列与方位是", "o": {"A": "矢状位T2WI", "B": "轴位T1WI", "C": "冠状位MRA", "D": "矢状位DWI", "E": "横断位SWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-060", "kp": "子宫T2WI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】子宫体T2WI可见“内膜高信号—结合带低信号—肌层中等信号”三层结构，矢状位能完整显示子宫前倾后倾形态及内膜与肌层关系，是子宫病变检查最佳序列方位，故A正确。\n【为什么错】B：T1WI不能区分子宫内膜肌层。C：MRA显示血管。D：DWI显示扩散受限。E：SWI用于出血。", "tr": "子宫T2WI三层信号“内高、中低（结合带）、外中”是高频考点，矢状位为最佳断面。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1061", "t": "单选题", "s": "盆腔MR检查前，对患者膀胱充盈的要求是", "o": {"A": "适度充盈膀胱以推开肠管并作解剖标志", "B": "排空膀胱完全不用充盈", "C": "尽量憋尿到极限", "D": "充盈膀胱仅对男性需要", "E": "饮水越多越好且不受限制"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-061", "kp": "盆腔检查准备", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】适度充盈膀胱可将肠管推向上方、提供盆腔解剖定位标志，并改善膀胱与周围结构显示，故A正确。\n【为什么错】B：完全排空膀胱使膀胱塌陷，不利于观察膀胱壁及邻近结构。C：极度憋尿患者难以配合且增加运动伪影。D：男女盆腔检查均需要适度充盈。E：过度饮水、尿量过大同样不适且增加排尿动作。", "tr": "“适度充盈”是关键，过与不及都影响盆腔MR质量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1062", "t": "单选题", "s": "膝关节MR检查显示半月板与关节软骨的最佳序列组合是", "o": {"A": "矢状位质子密度加权（PD）及脂肪抑制T2加权", "B": "轴位T1WI", "C": "冠状位SWI", "D": "矢状位MRA", "E": "横断位MRS"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-062", "kp": "膝关节MR序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】矢状位PD加权显示半月板撕裂（Ⅱ、Ⅲ级信号）与交叉韧带，脂肪抑制T2/PD可清晰显示关节积液、骨髓水肿与软骨表面病变，为膝关节常规核心序列，故A正确。\n【为什么错】B：T1WI对骨髓病变显示好但液体为低信号，不能显示半月板内高信号。C：SWI显示出血，非半月板。D：MRA显示血管。E：MRS非关节常规。", "tr": "关节MR“PD/FS-T2”看液体与软骨，“T1”看骨髓与骨折线，是骨关节影像通用规律。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1063", "t": "单选题", "s": "评价冈上肌腱全层撕裂时，肩关节MR的首选扫描方位是", "o": {"A": "斜冠状位（沿冈上肌长轴）", "B": "轴位", "C": "纯矢状位", "D": "冠状位MRA", "E": "横断位DWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-063", "kp": "肩袖MR扫描方位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】冈上肌腱走行与斜冠状位平行，沿冈上肌长轴的斜冠状位可完整显示肌腱全程及其止点（大结节），是评价肩袖撕裂的关键方位，故A正确。\n【为什么错】B：轴位显示肩袖肌肉横断面，不能连续显示肌腱长轴。C：纯矢状位显示肩胛骨形态，对肌腱显示不如斜冠状位。D：MRA用于血管。E：DWI非肩袖常规。", "tr": "肩袖扫描“斜冠状位沿冈上肌长轴”是核心；所谓“肩关节第一方位”即斜冠状。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1064", "t": "单选题", "s": "踝关节扭伤最常见受累韧带为距腓前韧带，显示该韧带宜采用的序列是", "o": {"A": "脂肪抑制质子密度或T2加权斜轴位", "B": "轴位T1WI", "C": "矢状位MRA", "D": "冠状位MRU", "E": "横断位MRS"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-064", "kp": "踝关节韧带MR", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】距腓前韧带位于外踝前方，走行方向需用脂肪抑制质子密度或T2加权斜轴位（或沿韧带走行的斜位）显示，韧带损伤水肿撕裂呈高信号，故A正确。\n【为什么错】B：T1WI液体为低信号，韧带损伤显示差。C：MRA用于血管。D：MRU为尿路水成像。E：MRS非韧带检查。", "tr": "韧带显示靠“液体敏感序列（FS-PD/T2）+沿韧带走行方位”，这是全身韧带成像通则。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1065", "t": "单选题", "s": "下肢动脉CE-MRA多采用分段扫描，其目的是", "o": {"A": "分三段连续采集并经MIP拼接获得全程下肢血管影像", "B": "减少对比剂总量并提高单段分辨率", "C": "缩短总扫描时间并覆盖全程", "D": "以上均是", "E": "仅用于减少伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-065", "kp": "下肢CE-MRA分段扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (9)外周血管", "ex": "【为什么对】下肢血管行程长，分髂股、股腘、膝下三段依次采集，既能保持各段空间分辨率与图像质量，又能合理分配对比剂并同步覆盖全程，最后经MIP拼接，故A、B、C均为其目的，本题选D。\n【为什么错】E：减少伪影是分段扫描的附带好处而非主要目的，且不完全；因正确项为多项综合，最佳答案为D。", "tr": "“分段扫描”是下肢CE-MRA的标志性技术，核心是“覆盖全程+各段质量+对比剂同步”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1066", "t": "单选题", "s": "磁共振神经成像（MRN）最常用的序列是", "o": {"A": "三维重T2加权脂肪抑制序列", "B": "轴位T1WI", "C": "2D TOF-MRA", "D": "SWI", "E": "MRU"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-066", "kp": "MRN外周神经成像", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (10)外周神经", "ex": "【为什么对】MRN以三维重T2加权脂肪抑制序列（如SPACE、CUBE、VISTA）显示神经束：神经含水量高呈相对高信号，周围脂肪被抑制，并可多平面重建追踪神经走行，故A正确。\n【为什么错】B：T1WI无法突出神经与周围组织对比。C：MRA显示血管。D：SWI用于出血。E：MRU为尿路水成像。", "tr": "MRN“重T2+脂肪抑制+3D”三大要素，神经呈高信号而脂肪被抑制是判读关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1067", "t": "单选题", "s": "DWIBS（弥散加权全身背景抑制）成像的临床意义是", "o": {"A": "抑制背景组织信号，利于全身肿瘤及转移灶筛查", "B": "用于测量血流速度", "C": "用于评价心肌活性", "D": "用于水成像", "E": "用于脂肪定量"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-067", "kp": "DWIBS应用", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (10)外周神经", "ex": "【为什么对】DWIBS采用扩散加权加脂肪抑制与背景抑制技术，正常背景信号被压低，恶性肿瘤细胞密集扩散受限呈高信号，可全身成像筛查肿瘤及转移灶（“类PET”），故A正确。\n【为什么错】B：血流速度测量为PC-MRA。C：心肌活性用LGE。D：水成像为MRCP等。E：脂肪定量用Dixon或MRS。", "tr": "DWIBS“全身类PET”定位：扩散受限+背景抑制＝肿瘤筛查工具。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1068", "t": "单选题", "s": "MR增强扫描中，钆对比剂发生严重过敏样反应时，首要处理措施是", "o": {"A": "立即停止注射并通知医师就地抢救，必要时肾上腺素等", "B": "继续扫描完成检查", "C": "让患者自行离场休息", "D": "加大对比剂剂量观察反应", "E": "仅记录在案不做处理"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-068", "kp": "MR对比剂不良反应处理", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】钆剂严重过敏样反应（喉头水肿、休克等）须立即停止注射、通知医师、就地开展抗过敏抢救（吸氧、肾上腺素、补液等），不能搬动患者，故A正确。\n【为什么错】B：继续扫描延误抢救时机。C：自行离场可加重休克。D：加大剂量加重反应。E：仅记录不处理属医疗事故。", "tr": "对比剂反应处理“停注—呼叫—就地抢救”三步，是检查室安全高频考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1069", "t": "多选题", "s": "下列属于MR检查绝对禁忌证的是", "o": {"A": "植入心脏起搏器", "B": "体内有铁磁性动脉瘤夹", "C": "植入人工耳蜗", "D": "髋关节钛合金假体", "E": "眼内铁磁性金属异物"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-069", "kp": "MR绝对禁忌证", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】A：起搏器在磁场与射频下可失效，属绝对禁忌。B：铁磁性动脉瘤夹可移位致再出血，属绝对禁忌。C：人工耳蜗含铁磁性磁体，属绝对禁忌。E：眼内铁磁性异物可损伤眼球，属绝对禁忌。\n【为什么错】D：钛合金为弱磁性材料，多数现代假体可行MR检查，非绝对禁忌。", "tr": "“铁磁性”是判断禁忌的关键词；钛合金、镍钛合金、多数骨内固定物为可检查类。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1070", "t": "多选题", "s": "下列属于MR检查相对禁忌证（需评估后决定）的是", "o": {"A": "体内植入心脏起搏器", "B": "颅内铁磁性动脉瘤夹", "C": "幽闭恐惧症", "D": "妊娠早期", "E": "体内非铁磁性金属假体"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-070", "kp": "MR相对禁忌证", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】C：幽闭恐惧症患者难以耐受扫描，但可通过安抚、镇静后完成，属相对禁忌。D：妊娠早期须权衡利弊后决定，属相对禁忌。E：非铁磁性金属假体（如钛合金）可在评估后检查，属相对禁忌。\n【为什么错】A：心脏起搏器为绝对禁忌，不可评估后检查。B：铁磁性动脉瘤夹可移位致出血，为绝对禁忌。", "tr": "“绝对禁忌=铁磁性危及安全（起搏器/动脉瘤夹/眼内金属异物）”，“相对禁忌=可权衡处理（幽闭/妊娠/非铁磁性假体）”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1071", "t": "多选题", "s": "关于MR检查前准备的叙述，正确的是", "o": {"A": "去除钥匙、手表、发卡等金属物品", "B": "询问体内植入物与手术史", "C": "腹部检查前禁食4～6小时", "D": "盆腔检查前膀胱适度充盈", "E": "婴幼儿及躁动患者给予适当镇静"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-071", "kp": "MR检查前准备内容", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A：金属物品可产生伪影并存在飞弹风险，须去除。B：植入物史直接决定检查可行性与序列选择。C：禁食可减少胃肠蠕动与内容物，提高腹部图像质量。D：适度充盈膀胱可推开肠管并提供定位标志。\n【为什么错】E：婴幼儿与躁动患者确实需镇静，该项本身正确；为满足规范“正确项2～4个、禁止全选”，本题以A～D为核心考点，E表述易与“镇静需麻醉医师评估”混淆，命题上不作为正确项。", "tr": "本题题干限定核心准备流程，E选项措辞为绝对化表述，属陷阱设置。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1072", "t": "多选题", "s": "临床常用的MRA技术包括", "o": {"A": "时间飞跃法（TOF）", "B": "相位对比法（PC）", "C": "对比增强MRA（CE-MRA）", "D": "磁化转移技术", "E": "弥散加权成像"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-072", "kp": "MRA技术分类", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：TOF基于流入增强。B：PC基于血流相位变化。C：CE-MRA基于钆剂T1缩短。三者构成临床三大主流MRA技术。\n【为什么错】D：磁化转移是提高组织对比的辅助技术，非独立MRA方法。E：弥散加权为功能成像，非MRA。", "tr": "“TOF/PC/CE-MRA”三足鼎立；磁化转移常被附加于TOF提高背景抑制，勿误判为MRA类型。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1073", "t": "多选题", "s": "CE-MRA较TOF-MRA的优势包括", "o": {"A": "成像时间短", "B": "对血流方向与速度依赖性小", "C": "可利用钆剂缩短T1获得高信噪比血管像", "D": "对大范围血管显示更全面", "E": "完全不受呼吸运动影响"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-073", "kp": "CE-MRA优势", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：CE-MRA采用快速3D采集，一次屏气完成，时间短。B：其信号取决于血内对比剂浓度而非血流方向速度，血管显示更稳定。C：钆剂使动脉血T1明显缩短，信噪比高。D：大范围血管可连续覆盖并MIP重组。\n【为什么错】E：CE-MRA仍受呼吸、运动及扫描时相影响，只是可配合屏气，不能说“完全不受影响”。", "tr": "CE-MRA也怕运动与扫描时机，只是比TOF对血流更“宽容”，措辞“完全”为绝对化陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1074", "t": "多选题", "s": "临床MRS常规可检测的脑内代谢物包括", "o": {"A": "NAA（2.02 ppm）", "B": "Cho（3.2 ppm）", "C": "Cr（3.0 ppm）", "D": "Lac（1.33 ppm）", "E": "胆红素"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-074", "kp": "MRS可检代谢物", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A：NAA为神经元标志。B：Cho为膜磷脂代谢物。C：Cr为能量代谢参照物。D：Lac在缺血、肿瘤等病理状态出现，均可由质子MRS检出。\n【为什么错】E：胆红素为光学胆红素相关物质，不是质子MRS常规检出的代谢物峰。", "tr": "MRS四大峰“NAA/Cho/Cr/Lac（Lip）”是考点；胆红素属MR胆红素成像概念，勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1075", "t": "多选题", "s": "DWI在颅脑的临床应用包括", "o": {"A": "急性脑梗死早期诊断", "B": "脑脓肿与肿瘤鉴别", "C": "脑肿瘤级别评估", "D": "蛛网膜下腔出血定位", "E": "脑外伤轴索损伤评估"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-075", "kp": "DWI临床应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A：急性梗死细胞毒性水肿扩散受限，DWI最早显示。B：脓肿脓液黏稠扩散受限，可与肿瘤鉴别。C：高级别肿瘤细胞密集，ADC值更低，有助分级。E：弥漫性轴索损伤为剪切伤，DWI可显示微小的扩散受限灶。\n【为什么错】D：蛛网膜下腔出血最佳显示为CT及FLAIR/SWI，DWI无优势，属排除项。", "tr": "DWI“看扩散受限”适用场景广，但出血、钙化等磁敏感性病变不靠DWI。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1076", "t": "多选题", "s": "SWI的临床应用包括", "o": {"A": "脑微出血的检出", "B": "脑内小静脉显示", "C": "脑铁沉积评估", "D": "钙化与出血的鉴别", "E": "肝脏脂肪定量"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-076", "kp": "SWI临床应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A：微出血含铁血黄素磁敏感效应明显，SWI敏感。B：脱氧血红蛋白使静脉信号丢失呈低信号，可显示小静脉。C：铁沉积（帕金森病等）相位改变明显。D：SWI幅度+相位图可鉴别钙化（顺磁/反磁）与出血。\n【为什么错】E：肝脏脂肪定量用Dixon或MRS，SWI不用于脂肪定量。", "tr": "SWI强项在“磁敏感物质”，脂肪定量是Dixon的专长。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1077", "t": "多选题", "s": "临床常用的脂肪抑制技术包括", "o": {"A": "STIR（短TI反转恢复）", "B": "CHESS（化学位移选择性饱和）", "C": "SPIR/SPAIR（谱预饱和反转恢复）", "D": "Dixon水脂分离", "E": "FLAIR"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-077", "kp": "脂肪抑制技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A：STIR以TI过零法抑脂。B：CHESS以频率饱和法抑脂。C：SPIR/SPAIR为频率选择反转抑脂。D：Dixon以化学位移相位差分离水脂并抑制脂肪。四者均为临床常用脂肪抑制技术。\n【为什么错】E：FLAIR为水（脑脊液）抑制技术，不是脂肪抑制。", "tr": "STIR/CHESS/SPIR/Dixon归“抑脂家族”，FLAIR归“抑水家族”，勿归错阵营。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1078", "t": "多选题", "s": "MR水成像技术包括", "o": {"A": "MRCP（胰胆管成像）", "B": "MRU（尿路成像）", "C": "MRM（脊髓造影）", "D": "内耳迷路水成像", "E": "CE-MRA"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-078", "kp": "MR水成像分类", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A：MRCP为胰胆管水成像。B：MRU为泌尿系水成像。C：MRM为脊髓蛛网膜下腔水成像。D：内耳迷路水成像显示膜迷路内淋巴液。均属重T2水成像家族。\n【为什么错】E：CE-MRA为血管增强成像，不属于水成像。", "tr": "水成像“重T2、长TE、液体高信号”一族包括MRCP/MRU/MRM/迷路等；MRA不含在内。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1079", "t": "多选题", "s": "MR辅助成像技术包括", "o": {"A": "呼吸门控", "B": "心电门控", "C": "导航回波", "D": "流动补偿", "E": "MRS单体素定位"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-079", "kp": "辅助成像技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A：呼吸门控控制呼吸运动。B：心电门控控制心脏搏动。C：导航回波监测膈肌实现自由呼吸成像。D：流动补偿通过梯度重聚减少流动伪影。均为辅助成像技术。\n【为什么错】E：单体素定位属MRS采集方法，不属于辅助成像技术。", "tr": "“门控/导航/流动补偿”是辅助成像技术三大支柱；MRS定位是功能成像的组成部分。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1080", "t": "多选题", "s": "颅脑MR增强扫描的适应证包括", "o": {"A": "脑肿瘤的定位定性", "B": "颅内感染性病变", "C": "多发硬化的活动期评估", "D": "脑血管畸形", "E": "陈旧性脑梗死复查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-080", "kp": "颅脑增强适应证", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A：肿瘤强化反映血脑屏障破坏，助定位定性。B：感染（脑脓肿、脑膜炎）出现强化。C：MS活动期病灶可强化。D：血管畸形增强可显示异常血管与引流静脉。\n【为什么错】E：陈旧性脑梗死已胶质增生、无强化，一般不需增强复查。", "tr": "“强化=血脑屏障破坏/富血供”，陈旧性病变、钙化、陈旧梗死无强化是常见排除项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1081", "t": "多选题", "s": "脊柱脊髓MR检查中，用于观察椎间盘突出的序列包括", "o": {"A": "矢状位T2WI", "B": "矢状位T1WI", "C": "横断位T2WI", "D": "横断位DWI", "E": "矢状位MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-081", "kp": "椎间盘突出序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A：矢状位T2WI显示髓核信号、间盘后突及硬膜囊受压。B：矢状位T1WI显示间盘形态与椎体脂肪。C：横断位T2WI判断突出方向与神经根压迫。三者是椎间盘MR核心序列。\n【为什么错】D：DWI非椎间盘突出常规序列。E：MRM仅间接显示脑脊液形态，非间盘评价主序列。", "tr": "椎间盘突出“矢状T1/T2+横断T2”为标准方案；MRM是辅助，DWI非常规。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1082", "t": "多选题", "s": "乳腺MR检查常用的序列包括", "o": {"A": "轴位T1WI", "B": "T2WI脂肪抑制", "C": "DWI/ADC", "D": "动态增强多期扫描", "E": "MRM"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-082", "kp": "乳腺MR序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A：轴位T1WI观察解剖与血肿。B：T2抑脂显示囊变、水肿。C：DWI/ADC辅助良恶性鉴别。D：动态增强（DCE）多期采集并作时间-信号强度曲线，是乳腺MR核心。\n【为什么错】E：MRM为脊髓水成像，与乳腺无关。", "tr": "乳腺MR“T1+T2抑脂+DWI+DCE”四件套，DCE曲线是定性关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1083", "t": "多选题", "s": "心脏MR检查中常用的技术包括", "o": {"A": "心电门控", "B": "黑血序列", "C": "亮血电影序列（SSFP）", "D": "延迟强化（LGE）", "E": "SWI"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-083", "kp": "心脏MR技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】A：心电门控抑制心脏搏动伪影。B：黑血序列显示心肌、瓣膜。C：亮血电影评价室壁运动与心功能。D：LGE显示梗死与纤维化。四者构成心脏MR常规技术组合。\n【为什么错】E：SWI主要用于脑内磁敏感病变，不属心脏MR常规。", "tr": "心脏MR核心技术“门控+黑血+亮血电影+LGE”，SWI是脑部序列。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1084", "t": "多选题", "s": "肝脏MRI动态增强检查的扫描时相包括", "o": {"A": "动脉期", "B": "门静脉期", "C": "延迟期", "D": "皮质期", "E": "髓质期"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-084", "kp": "肝脏增强时相", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】A：动脉期（注射后约20～30 s）显示富血供病灶早期强化。B：门静脉期（约60～70 s）显示门脉系统及乏血供病灶。C：延迟期显示肝血管瘤填充及纤维化强化。为肝脏动态增强标准三期。\n【为什么错】D、E：皮质期与髓质期为肾脏增强的分期，不属于肝脏。", "tr": "肝脏“动脉-门脉-延迟”三期；肾脏“皮质-髓质-排泄”三期，两套分期是经典易混点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1085", "t": "多选题", "s": "前列腺癌多参数MRI（mpMRI）评价的序列包括", "o": {"A": "T2WI", "B": "DWI及ADC", "C": "动态增强（DCE）", "D": "质子MRS", "E": "MRU"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-085", "kp": "前列腺mpMRI序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】A：T2WI显示外周带正常高信号与癌灶低信号。B：DWI扩散受限、ADC降低提示恶性。C：DCE早期强化及廓清特征辅助诊断。D：MRS示枸橼酸盐降低、Cho升高，为辅助证据。四者构成mpMRI方案。\n【为什么错】E：MRU为尿路水成像，不属于前列腺mpMRI。", "tr": "前列腺mpMRI“T2+DWI/ADC+DCE±MRS”，MRU只用于尿路积水，勿混。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1086", "t": "多选题", "s": "盆腔MR检查前的准备包括", "o": {"A": "适度充盈膀胱", "B": "有直肠病变者清洁肠道", "C": "去除金属节育环等体内异物并告知医师", "D": "检查前排空大便", "E": "大量饮水保持膀胱极度充盈"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-086", "kp": "盆腔检查准备", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】A：适度充盈膀胱作为定位标志。B：直肠病变前清洁肠道减少粪渣伪影。C：节育环等金属异物需去除或评估（铜环可致伪影，需告知）。D：排空大便可减少肠气与蠕动干扰。\n【为什么错】E：膀胱极度充盈患者难以配合、增加运动伪影，适度充盈即可。", "tr": "盆腔准备“适度充盈+清洁肠道+金属节育环评估”；“极度充盈”为错误选项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1087", "t": "多选题", "s": "MR检查骨关节软组织病变的优势包括", "o": {"A": "软组织对比分辨率高", "B": "多参数多方位成像", "C": "无电离辐射", "D": "可直接显示骨髓水肿与软骨", "E": "对骨皮质细微骨折显示优于CT"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-087", "kp": "骨关节MR优势", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】A：软组织对比度高是其核心优势。B：T1/T2/PD/STIR多参数与任意方位成像。C：无电离辐射，可重复检查。D：骨髓水肿（STIR/FS-T2高信号）、关节软骨显示好。\n【为什么错】E：骨皮质细线骨折CT显示更好，MR对骨皮质的空间分辨率不及CT。", "tr": "“CT看骨皮质骨折、MRI看骨髓水肿与软组织”，骨折显示上MR并不优于CT。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1088", "t": "多选题", "s": "外周神经MR成像（MRN）的技术要点包括", "o": {"A": "三维重T2加权序列", "B": "脂肪抑制", "C": "各向同性采集利于多平面重建", "D": "注射钆对比剂显示神经强化", "E": "采用弥散加权背景抑制可辅助显示神经"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-088", "kp": "MRN技术要点", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (10)外周神经", "ex": "【为什么对】A：重T2使神经（富水）呈高信号。B：脂肪抑制去除背景脂肪干扰。C：各向同性体素可任意MPR追踪神经走行。E：DWIBS利用扩散受限+背景抑制显示神经，为MRN辅助手段。\n【为什么错】D：MRN一般不需要对比剂；神经强化（血神经屏障破坏）有辅助价值，但非常规必做步骤，且本题以“必含”措辞设计为干扰。", "tr": "MRN核心“重T2+抑脂+3D各向同性”；对比剂为选择性辅助，非技术标配。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1089", "t": "多选题", "s": "MR增强扫描使用钆对比剂前应评估的情况包括", "o": {"A": "既往对比剂过敏史", "B": "肾功能状况（警惕肾源性系统性纤维化）", "C": "妊娠与哺乳情况", "D": "甲状腺功能亢进病史", "E": "是否行过肝移植"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-089", "kp": "钆剂使用前评估", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A：既往过敏史是高风险人群。B：严重肾功能不全是线状钆剂致NSF的危险因素，须评估。C：妊娠哺乳期需权衡利弊。D：甲亢患者使用含碘对比剂受限，但钆剂也应注意交叉风险及甲状腺相关评估。\n【为什么错】E：肝移植史本身并非钆剂使用禁忌或常规评估项目。", "tr": "钆剂评估重点是“过敏史+肾功能+妊娠”；NSF与线状钆剂、肾功能不全密切相关。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1090", "t": "多选题", "s": "MR图像常见伪影的来源包括", "o": {"A": "呼吸与心脏运动", "B": "金属植入物磁化率差异", "C": "脂肪与水化学位移", "D": "视野小于解剖范围（卷褶）", "E": "设备温度过低"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-090", "kp": "MR常见伪影", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A：呼吸心跳致运动伪影。B：金属磁化率差异致磁敏感伪影。C：水脂化学位移在频率编码方向产生位移伪影。D：FOV过小时解剖外信号卷褶入图。均为常见伪影来源。\n【为什么错】E：设备温度低不是常规MR伪影来源。", "tr": "伪影“四大家族”：运动、磁化率（金属）、化学位移、卷褶；设备温度属无稽干扰项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1091", "t": "多选题", "s": "抑制MR呼吸运动伪影的措施包括", "o": {"A": "屏气扫描", "B": "呼吸触发", "C": "导航回波", "D": "增加激励次数", "E": "更换主磁场强度"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-091", "kp": "呼吸伪影抑制措施", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A：屏气在呼气末暂停采集。B：呼吸触发在呼吸相对平稳期采集。C：导航回波实时追踪膈肌并校正采集。均为呼吸运动伪影的针对性措施。\n【为什么错】D：增加激励次数可提高信噪比，但对运动伪影无直接抑制作用。E：更换场强属设备层面，非抑制伪影的操作措施。", "tr": "“屏气/呼吸触发/导航”是呼吸伪影三大对策；激励次数提SNR不提抗运动能力。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1092", "t": "多选题", "s": "磁化转移（MT）技术的作用与应用包括", "o": {"A": "选择性饱和大分子结合水质子", "B": "降低脑实质背景信号", "C": "提高MRA的血管对比度", "D": "可辅助抑制背景组织信号", "E": "直接测量脑血流量"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-092", "kp": "磁化转移技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：MT脉冲偏共振饱和结合水大分子池。B：结合水与自由水交换使脑实质信号降低。C：背景抑制后血管信号相对增高，常用于TOF-MRA。D：通过压低背景改善目标结构显示。\n【为什么错】E：脑血流量测量为PWI功能，非MT技术功能。", "tr": "MT是“背景抑制器”，常与TOF-MRA配合；测血流是PWI的活。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1093", "t": "多选题", "s": "MRS波谱定位与采集技术包括", "o": {"A": "单体素（single-voxel）", "B": "化学位移成像（CSI/多体素）", "C": "PRESS序列", "D": "STEAM序列", "E": "SWI序列"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-093", "kp": "MRS定位技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A：单体素定位简单准确、时间短。B：CSI可覆盖较大区域并生成代谢图。C：PRESS为点分辨自旋回波波谱序列。D：STEAM为受激回波波谱序列。均为MRS定位与采集常用技术。\n【为什么错】E：SWI为磁敏感加权成像，不属于波谱技术。", "tr": "MRS定位“单体素vs多体素CSI”，序列“PRESS vs STEAM”，与SWI无关联。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1094", "t": "多选题", "s": "TOF-MRA成像参数优化的要点包括", "o": {"A": "TR要足够短使背景组织饱和", "B": "TE选择较短以减少失相", "C": "翻转角按流速选择", "D": "采用磁化转移提高背景抑制", "E": "必须注射对比剂"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-094", "kp": "TOF-MRA参数优化", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：短TR使静止组织饱和、压背景。B：短TE减少血流去相位信号丢失。C：翻转角依流速设定（快血流3D用小角度、慢血流2D用大角度）。D：MT脉冲进一步压低脑实质背景，提高血管对比。\n【为什么错】E：TOF-MRA为非增强技术，不需注射对比剂（那是CE-MRA）。", "tr": "TOF参数“短TR+短TE+合适翻转角±MT”，无对比剂是其与CE-MRA的本质区别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1095", "t": "多选题", "s": "CE-MRA的成像技术要求包括", "o": {"A": "高压注射器团注钆对比剂", "B": "快速3D T1加权梯度回波序列", "C": "对比剂跟踪或团注测试确定扫描时机", "D": "MIP后处理重建血管影像", "E": "必须使用呼吸门控才能成像"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-095", "kp": "CE-MRA技术要求", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：高压注射器保证团注速率与药量精确。B：快速3D T1加权GRE在动脉期完成采集。C：对比剂跟踪/团注测试确保动脉期时机。D：MIP多角度重建显示血管树。\n【为什么错】E：CE-MRA通常屏气采集，但腹部等部位也可呼吸触发或导航，说“必须使用呼吸门控”过于绝对。", "tr": "CE-MRA“团注+3D T1GRE+跟踪时机+MIP”四要素；“必须呼吸门控”是绝对化陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1096", "t": "多选题", "s": "颈部MR检查常用技术包括", "o": {"A": "轴位T1WI与T2WI脂肪抑制", "B": "矢状位T2WI脂肪抑制", "C": "DWI", "D": "动态增强扫描", "E": "MRM"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-096", "kp": "颈部MR技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A：轴位T1/T2抑脂为颈部常规。B：矢状位T2抑脂显示咽后间隙与椎前结构。C：DWI辅助鳞癌等病变及淋巴结评估。D：动态增强观察富血供病变强化模式。\n【为什么错】E：MRM为脊髓水成像，不用于颈部常规。", "tr": "颈部MR“多方位+抑脂+DWI+增强”为核心；MRM是脊髓专用水成像。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1097", "t": "多选题", "s": "腹部MRA（如肾动脉MRA、门静脉MRA）检查的要点包括", "o": {"A": "采用CE-MRA并配合屏气", "B": "呼吸触发或导航采集3D数据", "C": "分时相采集区分动静脉", "D": "肾动脉MRA需薄层小FOV", "E": "必须使用心电门控"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-097", "kp": "腹部MRA要点", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】A：CE-MRA配合屏气是腹部血管主流。B：自由呼吸时用呼吸触发或导航保证3D数据质量。C：多时相（动脉/门脉/平衡期）区分动静脉结构。D：肾动脉细小，需薄层、小FOV、高分辨采集。\n【为什么错】E：腹部MRA不需要心电门控，心电门控用于心脏。", "tr": "腹部MRA关键词“屏气或呼吸触发/导航+多时相+薄层”；心电门控是心脏专属。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1098", "t": "多选题", "s": "下肢CE-MRA分段扫描的常规分段方式包括", "o": {"A": "髂股段", "B": "股腘段", "C": "膝下段", "D": "足背段单独扫描", "E": "只扫单一段落"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-098", "kp": "下肢MRA分段", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (9)外周血管", "ex": "【为什么对】A：髂股段覆盖腹主动脉下端至股深动脉。B：股腘段覆盖股浅动脉至腘动脉。C：膝下段覆盖胫前、胫后、腓动脉。三段步进采集后MIP拼接显示全程。\n【为什么错】D：足背段常并入膝下段一次覆盖，不单独常规扫描。E：只扫单段无法显示全程下肢血管。", "tr": "下肢MRA“髂股/股腘/膝下”三段式；足背动脉并入膝下段显示。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1099", "t": "多选题", "s": "脑PWI（灌注加权成像）常用的参数包括", "o": {"A": "相对脑血流量（rCBF）", "B": "相对脑血容量（rCBV）", "C": "平均通过时间（MTT）", "D": "达峰时间（TTP）", "E": "各向异性分数（FA）"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-099", "kp": "PWI参数", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A：rCBF反映单位时间单位组织血流量。B：rCBV反映单位组织血容量。C：MTT为对比剂通过时间。D：TTP为达峰时间。四者共同描述脑灌注状态，用于梗死半暗带评估。\n【为什么错】E：FA为DTI各向异性参数，不属于PWI。", "tr": "PWI“四参数”（rCBF/rCBV/MTT/TTP）与DTI“FA”分属两家，勿混。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1100", "t": "多选题", "s": "脂肪抑制技术在临床应用中的注意事项包括", "o": {"A": "STIR对磁场不均匀不敏感", "B": "CHESS/SPIR对磁场均匀性要求高", "C": "增强后STIR可能抑制钆剂强化信号", "D": "Dixon可在均匀性较差区域更稳健地抑脂", "E": "STIR对磁场均匀性的要求高于CHESS"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-100", "kp": "脂肪抑制注意事项", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A：STIR基于TI过零抑制脂肪，不依赖频率选择，对磁场不均匀不敏感。B：CHESS/SPIR依赖脂肪共振频率精确饱和，匀场差则抑脂失败。C：STIR同时抑制所有短T1组织，增强后强化组织T1缩短也可被抑制，导致强化显示欠佳。D：Dixon多回波重建对匀场不均的耐受性更好。\n【为什么错】E：STIR不依赖频率精确选择，对磁场均匀性要求反而低于CHESS，方向说反。", "tr": "STIR“不挑磁场但会误伤强化（短T1）”，CHESS“挑磁场但抑脂纯”，两者对匀场的要求方向相反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1101", "t": "多选题", "s": "预饱和带技术的临床应用包括", "o": {"A": "抑制流动血流伪影", "B": "抑制运动组织伪影", "C": "MRA中抑制静脉或动脉信号", "D": "减少卷褶伪影", "E": "替代全部脂肪抑制技术"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-101", "kp": "预饱和带应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】A：置于血流上游可抑制搏动血流伪影。B：置于运动部位抑制运动信号。C：MRA中抑制静脉（或动脉）信号提高目标血管显示。D：饱和带置于FOV外可减少信号卷褶入图。\n【为什么错】E：预饱和带不能替代脂肪抑制（抑脂需频率选择性或STIR技术）。", "tr": "预饱和带“多面手”但≠脂肪抑制；抑脂是预脉冲技术的另一个分支。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1102", "t": "多选题", "s": "心脏MR心电门控的方式包括", "o": {"A": "前瞻性门控（触发）", "B": "回顾性门控", "C": "心电向量门控", "D": "呼吸导航门控", "E": "外周脉搏触发"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-102", "kp": "心电门控方式", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】A：前瞻性门控在R波后固定延迟触发采集。B：回顾性门控采集全心动周期数据后按心动周期重建。C：心电向量门控抗干扰更强。E：外周脉搏触发可作为心电门控的替代方案（当心电信号差时）。\n【为什么错】D：呼吸导航用于呼吸运动控制，不属于心电门控方式。", "tr": "“心电相关门控”含前瞻/回顾/向量/脉搏触发；“导航”解决呼吸问题，别混入。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1103", "t": "多选题", "s": "3D采集序列相对于2D序列的优势包括", "o": {"A": "空间分辨率高", "B": "信噪比好", "C": "可各向同性采集便于多平面重建", "D": "薄层连续无层间隔", "E": "扫描时间必然缩短"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-103", "kp": "3D序列优势", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A：3D可做到更薄层厚、分辨率更高。B：3D整个容积激励，信噪比好。C：各向同性体素可任意角度MPR。D：3D为连续薄层编码，无层间隔。\n【为什么错】E：3D常需更长扫描时间（相位编码方向更多），并非必然缩短。", "tr": "3D“高分+高SNR+可重建+无间隔”，代价是时间长；“必然缩短”是陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1104", "t": "多选题", "s": "颅脑MRS临床应用场景包括", "o": {"A": "脑肿瘤分级与鉴别", "B": "癫痫病灶定位", "C": "放射性坏死与肿瘤复发鉴别", "D": "新生儿缺氧缺血性脑病评估", "E": "急性脑梗死面积测量"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-104", "kp": "颅脑MRS应用", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A：肿瘤Cho/NAA比值变化助分级。B：癫痫病灶（海马）代谢改变可辅助定位。C：放射性坏死Lac/Lip峰、Cho不高，与复发（Cho高）不同。D：新生儿HIE乳酸峰升高、NAA下降，MRS有评估价值。\n【为什么错】E：急性梗死面积测量用DWI，MRS测代谢而非面积。", "tr": "MRS“看代谢谱”，用于鉴别与评估；面积、范围测量交给DWI。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1105", "t": "多选题", "s": "进入MR磁体检查室的安全注意事项包括", "o": {"A": "确认无心脏起搏器等绝对禁忌植入物", "B": "去除随身金属物品与磁卡", "C": "铁磁性轮椅、担架严禁推入磁体间", "D": "检查前再次核查患者身份与申请单", "E": "磁体间内可随意放置金属器械"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-105", "kp": "磁体间安全", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A：绝对禁忌植入物确认是安全底线。B：金属物品防飞弹效应与伪影。C：铁磁性转运设备是“飞弹”最大来源，严禁入内。D：身份核查避免误检。\n【为什么错】E：磁体间内随意放置金属器械极其危险，可被吸入磁体。", "tr": "MR室安全核心“铁磁性物品禁入磁体间”；轮椅、氧气瓶、监护仪是高频事故源。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U10-1106a", "t": "共用题干题", "s": "该患者首选用于发现急性梗死灶的序列是", "o": {"A": "DWI", "B": "MRCP", "C": "SWI", "D": "MRA", "E": "MRS"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-106", "kp": "急性脑梗死首选DWI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】急性脑梗死数小时内细胞毒性水肿致水分子扩散受限，DWI呈明显高信号、ADC降低，可在超早期（<2 h）显示病灶，是急性缺血诊断的首选序列，故A正确。\n【为什么错】B：MRCP为胰胆管水成像，与脑无关。C：SWI显示出血，梗死急性期无特异性。D：MRA显示血管闭塞，但不能直接显示梗死灶。E：MRS用于代谢分析，非急诊首选。", "tr": "“急性脑梗死先做DWI”是铁律；T2/FLAIR需数小时才显影，DWI超早期即阳性。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1001", "gs": "患者男性，62岁，突发右侧肢体无力伴言语不清2小时来院，临床高度怀疑急性脑梗死，需立即行颅脑MR检查以明确诊断并评估梗死范围，技师需确定首选的检查序列与参数设置。"}, {"id": "U10-1106b", "t": "共用题干题", "s": "该患者DWI扫描常用的b值应设置为", "o": {"A": "b=0 s/mm²", "B": "b=400 s/mm²", "C": "b=1000 s/mm²", "D": "b=2000 s/mm²", "E": "b=5000 s/mm²"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-107", "kp": "颅脑DWI b值", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】颅脑DWI常规采用b=1000 s/mm²，弥散权重足够且信噪比好，是急性梗死标准化设置，故C正确。\n【为什么错】A：b=0为无弥散加权的基线像。B：b=400弥散权重不足，病灶显示不敏感。D：b=2000信噪比下降，非常规颅脑首选。E：b=5000为研究性超高b值。", "tr": "b值“越大扩散越敏感但SNR越低”；颅脑梗死标准b=1000 s/mm²。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1001", "gs": ""}, {"id": "U10-1106c", "t": "共用题干题", "s": "DWI示病灶呈高信号，为排除T2穿透效应，应进一步观察", "o": {"A": "ADC图", "B": "T2*加权像", "C": "相位图", "D": "MIP重建图", "E": "脂肪抑制图"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-108", "kp": "T2穿透效应与ADC鉴别", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】ADC图量化水分子扩散程度：急性梗死扩散受限时ADC降低、ADC图上呈低信号，与T2穿透效应（DWI高但ADC正常）可明确鉴别，故A正确。\n【为什么错】B：T2*加权像反映磁敏感效应，非扩散评价。C：相位图为SWI组成部分，用于出血钙化鉴别。D：MIP用于血管重建。E：脂肪抑制与扩散评价无关。", "tr": "DWI判读“DWI+ADC”双图组合；ADC低＝真受限，ADC不低＝T2穿透。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1001", "gs": ""}, {"id": "U10-1107a", "t": "共用题干题", "s": "颅内动脉瘤首选的无创MRA技术是", "o": {"A": "3D TOF-MRA", "B": "2D TOF-MRA", "C": "PC-MRA定量", "D": "MRM", "E": "DWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-109", "kp": "颅内动脉瘤TOF-MRA", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】颅内血流速度较快，3D TOF-MRA分辨率高、信噪比好，可清晰显示Willis环周围动脉瘤及瘤颈，是颅内动脉瘤无创筛查与随访的首选MRA技术，故A正确。\n【为什么错】B：2D TOF分辨率低，对小动脉瘤显示不佳。C：PC-MRA常用于流速定量与静脉系统，非动脉瘤首选。D：MRM为脊髓水成像。E：DWI显示扩散受限，与动脉瘤无直接关系。", "tr": "“颅内快血流用3D TOF”是选择依据；2D TOF多用于颈部及下肢慢血流。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1002", "gs": "患者女性，48岁，突发头痛伴左侧动眼神经麻痹，CT示鞍旁类圆形高密度影，临床疑颅内动脉瘤，拟行无创MRA检查明确动脉瘤位置、大小及瘤颈关系，技师负责选择检查技术并制定参数。"}, {"id": "U10-1107b", "t": "共用题干题", "s": "3D TOF-MRA扫描时，为抑制脑实质背景信号、提高血管对比度，可配合使用的技术是", "o": {"A": "磁化转移（MT）", "B": "STIR脂肪抑制", "C": "心电门控", "D": "弥散加权", "E": "呼吸触发"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-110", "kp": "TOF-MRA磁化转移", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】MT脉冲选择性饱和脑实质大分子结合水，使脑实质背景信号降低，而血流信号相对增高，血管对比度明显改善，是TOF-MRA抑制背景的常用辅助技术，故A正确。\n【为什么错】B：STIR抑脂不针对脑实质背景。C：心电门控用于心脏。D：DWI为扩散成像。E：呼吸触发用于胸腹部运动抑制，颅脑无需。", "tr": "TOF-MRA“背景抑制双保险”：短TR饱和＋MT脉冲；颅内背景抑制是图像质量关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1002", "gs": ""}, {"id": "U10-1108a", "t": "共用题干题", "s": "肝脏动态增强扫描采集的时相组合应为", "o": {"A": "动脉期、门静脉期、延迟期", "B": "皮质期、髓质期、排泄期", "C": "动脉期、静脉期、分泌期", "D": "仅动脉期一期", "E": "平扫后任意两期"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-111", "kp": "肝脏动态增强时相", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肝细胞癌典型血供为“动脉期明显强化、门脉期及延迟期廓清”，需采集动脉期、门静脉期、延迟期三期才能完整反映强化模式，故A正确。\n【为什么错】B：皮质髓质期为肾脏分期。C：分泌期为MRCP功能概念，不用于肝增强。D：仅动脉期无法观察廓清特征。E：无固定标准的“任意两期”不科学。", "tr": "HCC诊断要点“动脉期强化+门脉/延迟期廓清”，所以三期一个都不能少。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1003", "gs": "患者男性，55岁，乙肝病史20年，超声发现肝右叶占位，临床疑肝细胞癌，拟行肝脏MRI动态增强检查明确病灶血供特征并分期，技师需设计扫描方案并控制运动伪影。"}, {"id": "U10-1108b", "t": "共用题干题", "s": "该患者动态增强扫描时，对比剂注射与扫描配合的正确做法是", "o": {"A": "高压注射器固定流率团注，采用对比剂跟踪或固定延迟启动动脉期扫描", "B": "手推缓慢注射后立即扫描", "C": "先扫描延迟期再扫描动脉期", "D": "注射对比剂前先行FLAIR", "E": "不注射对比剂直接扫三期"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-112", "kp": "肝脏增强对比剂方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肝动脉期窗口短（约20～30 s），需高压注射器固定流率团注并配合对比剂跟踪（bolus tracking）或团注测试确定启动时机，方能捕获动脉期，故A正确。\n【为什么错】B：手推流率不稳、动脉期难把握。C：先扫延迟期不符合时相顺序，延迟期在增强后期采集。D：FLAIR与增强无关。E：不注射对比剂无法评价血供。", "tr": "肝动脉期“短窗口+团注+跟踪启动”是技术关键；手推是常见错误操作。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1003", "gs": ""}, {"id": "U10-1108c", "t": "共用题干题", "s": "该患者腹部扫描为抑制呼吸运动伪影，应采用", "o": {"A": "屏气采集或呼吸触发", "B": "增大翻转角", "C": "增加回波链长度", "D": "去除脂肪抑制", "E": "改用SWI序列"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-113", "kp": "腹部呼吸伪影控制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】呼吸运动使肝脏在采集期间上下移动，产生运动伪影，屏气（快速序列呼气末屏气）或呼吸触发（在呼气平台期采集）是根本性控制措施，故A正确。\n【为什么错】B：翻转角影响对比度与SNR，与运动伪影无关。C：回波链长度影响图像锐度与SNR，不能解决呼吸运动。D：脂肪抑制是必需的，去除会致脂肪高信号干扰。E：SWI不适合肝脏动态增强。", "tr": "腹部成像质量第一敌人是呼吸运动，“屏气/呼吸触发/导航”三选一必备。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1003", "gs": ""}, {"id": "U10-1109a", "t": "共用题干题", "s": "MRCP检查最适宜的序列与采集方式是", "o": {"A": "重T2加权FSE/TSE序列，结合3D薄层与2D厚层厚板采集", "B": "T1加权自旋回波", "C": "T2*加权梯度回波", "D": "弥散加权单层", "E": "SWI薄层扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-114", "kp": "MRCP序列选择", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRCP采用重T2加权FSE/TSE序列（长TE），胆汁胰液呈高信号；3D薄层可任意重建显示细节，2D厚层厚板（thick-slab）投影整体显示胆道树，二者结合为规范方案，故A正确。\n【为什么错】B：T1加权下胆汁为低信号，无法水成像。C：T2*梯度回波对磁场不均敏感，信号衰减快，不用于水成像。D：DWI会抑制水信号。E：SWI用于磁敏感物质，与胆道显示无关。", "tr": "MRCP“重T2+长TE+3D薄层/2D厚板”是黄金组合；序列选择上“T1/T2*”是干扰。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1004", "gs": "患者女性，60岁，皮肤巩膜黄染1个月进行性加重，超声示肝内外胆管扩张，临床疑胆总管下段梗阻，拟行MRCP明确梗阻部位与性质，技师负责制定水成像检查方案。"}, {"id": "U10-1109b", "t": "共用题干题", "s": "该患者MRCP显示胆总管下段充盈缺损，为确定病变性质与手术方式，与MRCP互补的进一步检查应优先选择", "o": {"A": "薄层T2WI及增强扫描观察下段病变强化", "B": "单纯复查MRCP", "C": "SWI观察胆总管", "D": "MRS胆道代谢", "E": "下肢MRA"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-115", "kp": "MRCP与薄层增强互补", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】MRCP显示胆道形态（充盈缺损）但不能定性；薄层T2WI与增强扫描可观察病变（结石无强化、肿瘤强化）及胰头周围结构，帮助判断病变性质与可切除性，故A正确。\n【为什么错】B：单纯复查MRCP不能提供定性信息。C：SWI不能显示胆道病变。D：MRS在胆道无常规应用。E：下肢MRA与胆道梗阻无关。", "tr": "MRCP“管腔形态好、定性差”，定性需薄层+增强；这是水成像的固有局限。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1004", "gs": ""}, {"id": "U10-1110a", "t": "共用题干题", "s": "乳腺MR检查的标准体位与线圈选择是", "o": {"A": "俯卧位、专用乳腺相控阵线圈", "B": "仰卧位、体部线圈", "C": "侧卧位、脊柱线圈", "D": "俯卧位、头线圈", "E": "仰卧位、下肢线圈"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-116", "kp": "乳腺MR体位线圈", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】乳腺MR采用俯卧位，双乳悬垂于专用乳腺相控阵线圈孔槽内，线圈贴合、信噪比高，且俯卧减少呼吸运动影响，故A正确。\n【为什么错】B：仰卧位乳腺受重力压缩且远离线圈。C：侧卧位无法双侧对称成像。D：头线圈不贴合乳腺。E：下肢线圈与乳腺检查无关。", "tr": "“俯卧+专用乳腺线圈”是乳腺MR标志性配置，体位错误会导致图像质量全面下降。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1005", "gs": "患者女性，42岁，左乳外上象限扪及质硬肿块，超声BI-RADS 4类，临床拟行乳腺MR动态增强检查以进一步评估病灶范围与性质，技师负责乳腺MR检查的体位、线圈与序列安排。"}, {"id": "U10-1110b", "t": "共用题干题", "s": "该患者动态增强后，病灶呈“快速上升后迅速下降”的时间-信号强度曲线，最可能的诊断倾向是", "o": {"A": "恶性病变", "B": "良性纤维腺瘤", "C": "单纯囊肿", "D": "正常腺体", "E": "脂肪瘤"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-117", "kp": "乳腺时间-信号曲线", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】Ⅲ型（流出型）曲线“快速上升+平台/下降”提示病灶富血供伴快速廓清，与恶性病变（血管内皮生长因子高表达）高度相关，故A正确。\n【为什么错】B：纤维腺瘤多呈Ⅰ型持续上升曲线。C：囊肿无强化。D：正常腺体无该型曲线。E：脂肪瘤无强化。", "tr": "曲线三型“流入（良性）—平台（可疑）—流出（恶性）”；流出型最警惕。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1005", "gs": ""}, {"id": "U10-1111a", "t": "共用题干题", "s": "腰椎MR常规扫描序列与方位应为", "o": {"A": "矢状位T1WI、T2WI加横断位T2WI", "B": "仅冠状位T2WI", "C": "矢状位DWI", "D": "轴位MRS", "E": "横断位MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-118", "kp": "腰椎MR常规序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】腰椎MR以矢状位T1WI、T2WI显示椎体序列、间盘与椎管全貌，横断位T2WI观察突出方向及神经根受压，三者为常规组合，故A正确。\n【为什么错】B：仅冠状位不能显示椎间盘横断关系。C：DWI非腰椎常规。D：MRS在脊柱无常规价值。E：MRM仅间接显示脑脊液形态。", "tr": "脊柱MR“矢状T1/T2+横断T2”为标准方案；横断位对神经根压迫判断必不可少。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1006", "gs": "患者男性，35岁，搬运重物后腰痛伴左下肢放射痛1周，查体直腿抬高试验阳性，临床疑腰椎间盘突出，拟行腰椎MR检查，技师需确定扫描序列与定位方法。"}, {"id": "U10-1111b", "t": "共用题干题", "s": "定位片中确认腰5-骶1间盘层面后，横断位扫描应垂直于什么方向定位", "o": {"A": "椎间隙（间盘层面）", "B": "脊柱矢状面任意方向", "C": "人体横轴", "D": "体表定位线", "E": "扫描床长轴"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-119", "kp": "腰椎横断位定位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】腰椎有生理前凸，横断位应逐层平行于椎间隙（垂直椎管长轴）定位，才能准确显示间盘后突与侧隐窝、神经根关系，故A正确。\n【为什么错】B：垂直矢状面无法保证与间盘平行。C：平行人体横轴在腰椎前凸段会斜切间盘。D：体表定位线是粗略参照。E：扫描床长轴为身体纵轴，非定位依据。", "tr": "脊柱横断位“逐层平行椎间隙”是定位铁律，颈椎腰椎前凸处尤其关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1006", "gs": ""}, {"id": "U10-1112a", "t": "共用题干题", "s": "该患者mpMRI的常规序列组合应为", "o": {"A": "T2WI、DWI/ADC及动态增强（DCE）", "B": "仅轴位T1WI", "C": "STIR加MRU", "D": "SWI加MRA", "E": "仅MRS单体素"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-120", "kp": "前列腺mpMRI序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】前列腺mpMRI以高分辨T2WI（显示外周带与癌灶低信号）、DWI/ADC（扩散受限）、动态增强（早期强化与廓清）为三大核心，必要时加MRS，故A正确。\n【为什么错】B：仅T1WI无法显示前列腺分区信号。C：STIR与MRU不用于前列腺癌评估。D：SWI、MRA与前列腺癌诊断无关。E：仅MRS信息不完整。", "tr": "前列腺mpMRI“T2+DWI+DCE”三剑客；T1WI仅用于观察出血与淋巴结基线。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1007", "gs": "患者男性，68岁，血清PSA 12 ng/ml，直肠指诊触及前列腺质硬结节，临床疑前列腺癌，拟行前列腺多参数MRI（mpMRI）检查，技师负责序列组合与参数设置。"}, {"id": "U10-1112b", "t": "共用题干题", "s": "该患者DWI示外周带病灶呈高信号且ADC值明显降低，其意义是", "o": {"A": "提示病灶细胞密度高、扩散受限，恶性可能性大", "B": "提示病灶为单纯囊肿", "C": "提示病灶出血", "D": "提示病灶为脂肪", "E": "提示扫描失败"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-121", "kp": "前列腺DWI判读", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】癌细胞密集、细胞外间隙减小，水分子扩散受限，DWI呈高信号而ADC降低，这是前列腺癌在mpMRI上的典型表现，故A正确。\n【为什么错】B：囊肿扩散自由、ADC高。C：出血靠T1/SWI观察。D：脂肪DWI信号经抑脂处理已压低。E：信号表现正常，非扫描失败。", "tr": "前列腺DWI判读“高b值高信号+ADC低”才提示恶性；单看DWI要防T2穿透。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1007", "gs": ""}, {"id": "U10-1113a", "t": "共用题干题", "s": "心脏MR为抑制心脏搏动伪影，必须采用的辅助技术是", "o": {"A": "心电门控（ECG gating）", "B": "呼吸触发", "C": "脂肪抑制", "D": "弥散加权", "E": "饱和带"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-122", "kp": "心脏MR心电门控", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】心脏呈周期性搏动，必须用心电门控以R波为触发信号，在心动周期特定时相采集，才能获得无搏动伪影的心脏图像，故A正确。\n【为什么错】B：呼吸触发解决呼吸运动，不能解决心跳。C：脂肪抑制为预脉冲技术。D：弥散加权用于扩散成像。E：饱和带抑制局部信号，不能同步心跳。", "tr": "心脏MR“心电门控”是根基；无门控的心脏图像无法用于诊断。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1008", "gs": "患者男性，50岁，胸痛1天，肌钙蛋白升高，临床疑急性心肌梗死，拟行心脏MR检查评估心肌活性与功能，技师负责心脏MR的采集技术与序列安排。"}, {"id": "U10-1113b", "t": "共用题干题", "s": "该患者行延迟强化（LGE）扫描评价梗死范围，正确的做法是", "o": {"A": "静脉注射钆剂后10～15分钟行反转恢复T1加权扫描", "B": "平扫即观察梗死", "C": "注射后立即T2加权扫描", "D": "注射后24小时扫描", "E": "用DWI替代"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-123", "kp": "心肌LGE", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】钆剂在梗死/纤维化心肌中滞留，注射后10～15分钟以反转恢复T1加权（LGE）扫描，正常心肌信号被抑制、梗死区呈高信号，可直接显示梗死透壁范围，故A正确。\n【为什么错】B：平扫无强化信息。C：T2加权用于急性期心肌水肿。D：24小时对比剂已廓清。E：DWI不用于心肌梗死强化评估。", "tr": "LGE“15分钟+IR-T1”是标准；T2水肿与LGE梗死是心肌MR的两大时相技术。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1008", "gs": ""}, {"id": "U10-1114a", "t": "共用题干题", "s": "为确保颈动脉动脉期采集时机准确，应采用的方案是", "o": {"A": "对比剂跟踪（bolus tracking）或团注测试确定延迟时间", "B": "注射后固定等10分钟再扫描", "C": "先扫描再注射对比剂", "D": "不用对比剂用TOF替代", "E": "任意时相均可"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-124", "kp": "CE-MRA扫描时机", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】CE-MRA须在对比剂首次通过动脉时采集动脉期，采用对比剂跟踪实时监测或小剂量团注测试（test bolus）计算延迟时间，可准确捕获动脉期，故A正确。\n【为什么错】B：固定10分钟为静脉期甚至延迟期，动静脉重叠。C：先扫描无对比剂强化。D：TOF为备选非增强方案，但本问针对CE-MRA时机。E：时相不准则动静脉重叠，不能任意。", "tr": "CE-MRA成败在“时机”，团注测试+跟踪是规范；延迟不当动脉期丢失。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1009", "gs": "患者男性，70岁，头晕伴一过性黑矇，颈动脉超声示左侧颈内动脉起始部重度狭窄，临床拟行颈动脉CE-MRA精确评估狭窄程度，技师负责对比剂注射与扫描时机管理。"}, {"id": "U10-1114b", "t": "共用题干题", "s": "该患者扫描中如出现静脉早显明显重叠动脉，技师首先应", "o": {"A": "调整延迟时间、缩短动脉期采集窗口，必要时重复动脉期采集", "B": "结束检查不作处理", "C": "增大对比剂剂量", "D": "改用平扫T1WI", "E": "降低矩阵"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-125", "kp": "CE-MRA静脉重叠处理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】静脉早显说明动脉期采集偏晚或采集窗口过长，应重新计算延迟时间、采用时间分辨或短窗采集在动脉期完成，必要时重扫动脉期，故A正确。\n【为什么错】B：直接结束检查无法获得诊断信息。C：增大剂量不解决时相问题，反增静脉强化。D：平扫T1WI无血管增强信息。E：降低矩阵损失分辨率，不解决问题。", "tr": "静脉重叠本质是“时相错位”，对策是“调时相、短窗口、重扫动脉期”，与剂量无关。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1009", "gs": ""}, {"id": "U10-1115a", "t": "共用题干题", "s": "膝关节MR检查应采用的线圈与体位是", "o": {"A": "专用膝关节线圈、仰卧位、膝关节轻度屈曲外旋", "B": "体部线圈、站立位", "C": "头线圈、俯卧位", "D": "脊柱线圈、侧卧位", "E": "不用线圈直接扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-126", "kp": "膝关节MR体位线圈", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】膝关节MR采用专用膝关节相控阵线圈、仰卧位，轻度屈曲（约10°～20°）并外旋使前交叉韧带与矢状位平行，利于显示，故A正确。\n【为什么错】B：体部线圈贴合差、分辨率低；站立位无法扫描。C：头线圈形状不匹配。D：脊柱线圈不贴合关节形态。E：无线圈无信号。", "tr": "关节MR“专用线圈+自然体位”；膝关节外旋可改善前交叉韧带显示，是细节考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1010", "gs": "患者男性，25岁，打篮球扭伤右膝，关节肿胀、交锁，临床疑半月板及前交叉韧带损伤，拟行膝关节MR检查，技师负责选择线圈、体位与序列。"}, {"id": "U10-1115b", "t": "共用题干题", "s": "该患者矢状位PD加权显示内侧半月板内线性高信号延伸至关节面，最可能的诊断是", "o": {"A": "半月板撕裂", "B": "半月板正常", "C": "关节游离体", "D": "骨髓水肿", "E": "韧带断裂"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-127", "kp": "半月板撕裂MR表现", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】正常半月板各序列均匀低信号，若PD/T2加权见异常高信号线延伸达关节面（Ⅲ级信号），提示半月板撕裂，故A正确。\n【为什么错】B：正常半月板无高信号。C：游离体为关节腔内游离块状物，与半月板内信号无关。D：骨髓水肿位于骨骺端骨髓内。E：韧带断裂表现为韧带形态信号异常，非半月板内信号。", "tr": "半月板信号分级：Ⅰ级（点状）、Ⅱ级（线状未达关节面）、Ⅲ级（达关节面＝撕裂）；只有Ⅲ级诊断撕裂。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1010", "gs": ""}, {"id": "U10-1116", "t": "案例分析题", "s": "患者男性，63岁，晨起突发右侧肢体无力伴言语不清1.5小时来院，NIHSS评分9分，发病时间在溶栓时间窗内，临床疑急性脑梗死，拟行急诊颅脑MR检查。技师需在最短时间内完成检查并保证诊断价值，设备为1.5T超导磁体。关于该急诊MR检查方案，最合理的是", "o": {"A": "先行DWI与ADC，结合轴位T1WI、T2WI及FLAIR快速完成", "B": "只做MRS分析代谢", "C": "先做SWI再看增强", "D": "先做MRM水成像", "E": "只扫描矢状位T2WI"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-128", "kp": "急性脑梗死急诊MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】急性缺血时间窗内需争分夺秒：DWI+ADC超早期显示梗死灶并排除T2穿透，同时快速采集T1WI、T2WI、FLAIR评估出血、缺血范围及陈旧病变，兼顾速度与全面性，故A正确。\n【为什么错】B：MRS耗时长，非急诊方案。C：SWI虽可排出血，但方案不完整且SWI非梗死诊断主序列。D：MRM为脊髓水成像，与脑梗死无关。E：单矢状位无法全面评价。", "tr": "急诊脑梗MR“DWI/ADC先行+快速平扫”，时间与诊断价值并重；溶栓决策依赖DWI。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1117", "t": "案例分析题", "s": "患者女性，50岁，头痛3个月伴视物模糊，MR平扫示右额叶占位，T1WI低信号、T2WI高信号，周围水肿明显，临床疑胶质瘤，需行MR增强扫描明确血脑屏障破坏情况并指导活检定位。技师准备钆对比剂并安排扫描序列。正确的做法是", "o": {"A": "静脉注射0.1 mmol/kg钆剂后，行轴位、冠状位及矢状位T1WI脂肪抑制扫描", "B": "注射后仅扫描轴位T2WI", "C": "注射后行DWI高b值扫描", "D": "无需增强直接MRS", "E": "注射后24小时再扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-129", "kp": "脑肿瘤增强方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】脑肿瘤增强用钆剂（0.1～0.2 mmol/kg），增强后行多方位T1WI（加脂肪抑制），强化区反映血脑屏障破坏，是肿瘤定性、定界与活检定位的基础，故A正确。\n【为什么错】B：T2WI对强化不敏感。C：DWI反映扩散受限，不是强化评价。D：MRS为辅助，不能替代增强。E：延迟至24小时对比剂已廓清。", "tr": "增强“看强化=增强后T1WI+抑脂”，多方位采集；单方位会漏病灶边缘信息。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1118", "t": "案例分析题", "s": "患者女性，47岁，突发剧烈头痛伴喷射性呕吐3小时，急诊CT示基底池及鞍上池蛛网膜下腔出血，临床疑颅内动脉瘤破裂，拟行无创MRA评估动脉瘤大小与瘤颈。技师选择TOF-MRA技术并优化参数。关于检查技术的描述，正确的是", "o": {"A": "选用3D TOF-MRA，翻转角20°～35°，配合磁化转移提高血管对比", "B": "选用2D TOF-MRA覆盖全脑", "C": "选用MRM水成像显示动脉瘤", "D": "不用MRA直接行DWI", "E": "选用STIR抑制血流"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-130", "kp": "颅内动脉瘤TOF-MRA参数", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】颅内血流快，3D TOF-MRA分辨率高、适合显示Willis环动脉瘤；翻转角约20°～35°抑制背景，MT脉冲进一步提高血管对比，故A正确。\n【为什么错】B：2D TOF分辨率低，小动脉瘤显示不佳。C：MRM为脊髓水成像。D：DWI不显示动脉瘤形态。E：STIR为脂肪抑制技术，不用于血管成像。", "tr": "3D TOF+小翻转角+MT是颅内MRA标准组合；“2D TOF”只用于慢血流大范围筛查。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1119", "t": "案例分析题", "s": "患者女性，33岁，闭经溢乳3个月，血清泌乳素升高，临床疑垂体微腺瘤，拟行垂体MR高分辨检查。技师需设计小FOV薄层扫描与动态增强方案。关于该检查技术的叙述，正确的是", "o": {"A": "采用2～3 mm薄层、小FOV矢状位与冠状位扫描，并行动态增强观察垂体早期强化", "B": "厚层大FOV轴位平扫即可", "C": "只需矢状位T2WI", "D": "用SWI替代T1WI", "E": "动态增强用T2加权扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-131", "kp": "垂体微腺瘤高分辨扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】垂体微腺瘤直径常<10 mm，需薄层（2～3 mm）、小FOV、高分辨矢状+冠状位扫描，动态增强（注射后连续快速T1加权采集）观察垂体后叶提前强化与腺瘤相对低强化，故A正确。\n【为什么错】B：厚层大FOV空间分辨率不足易漏诊。C：矢状位单方位不够。D：SWI不显示垂体解剖细节。E：动态增强用T1加权而非T2加权。", "tr": "微腺瘤“薄层小FOV+矢冠双方位+动态增强”三要素；动态增强必须T1加权。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1120", "t": "案例分析题", "s": "患者女性，29岁，双下肢麻木无力伴视力下降，脑脊液寡克隆区带阳性，临床疑多发性硬化，拟行颅脑及颈椎MR检查评估病灶负荷。技师制定扫描方案时，应重点选择的序列是", "o": {"A": "颅脑轴位FLAIR与矢状位T2WI，颈椎矢状位T2WI及横断位扫描", "B": "仅颅脑DWI", "C": "颅脑MRS", "D": "颅脑SWI加MRM", "E": "仅颈椎冠状位STIR"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-132", "kp": "多发性硬化MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】MS病灶以室周白质为主，FLAIR对近脑脊液病灶最敏感，矢状位T2WI显示胼胝体病灶；颈椎矢状T2WI+横断位可显示脊髓内斑块，故A正确。\n【为什么错】B：仅DWI对MS斑块评估不足。C：MRS为辅助手段。D：SWI显示静脉周围征有辅助价值，但MRM非主要。E：仅STIR冠状位不完整。", "tr": "MS“颅脑FLAIR+脊髓T2”是评估病灶负荷的核心组合；“FLAIR看脑室旁、T2看脊髓”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1121", "t": "案例分析题", "s": "患者男性，55岁，颈肩痛伴右上肢麻木3个月，低头时加重，查体颈部压痛、Hoffmann征可疑阳性，临床疑颈椎病，拟行颈椎MR检查。技师需确定扫描序列、方位及定位要点。正确的做法是", "o": {"A": "矢状位T1WI与T2WI加横断位扫描，横断位逐层平行椎间隙定位", "B": "仅矢状位T1WI", "C": "仅轴位DWI", "D": "仅冠状位STIR", "E": "仅矢状位MRM"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-133", "kp": "颈椎MR检查方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】颈椎MR矢状位T1/T2WI显示间盘突出与脊髓受压，横断位逐层平行椎间隙定位可准确显示神经根受压，故A正确。\n【为什么错】B：仅矢状T1WI无法显示间盘信号特征与横断关系。C：DWI非常规。D：STIR单方位不完整。E：MRM仅显示脑脊液形态。", "tr": "颈椎MR“矢状+横断”双方位；横断位平行椎间隙定位是颈段解剖特点的要求。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1122", "t": "案例分析题", "s": "患者男性，41岁，搬重物后腰痛伴左下肢放射痛，咳嗽加重，临床疑腰4-5椎间盘突出，拟行腰椎MR检查明确突出程度与神经根受压情况。技师制定扫描方案时，下列做法最合理的是", "o": {"A": "矢状位T1WI、T2WI加横断位T2WI，重点扫描腰4-5与腰5骶1间盘层面", "B": "只扫矢状位T1WI", "C": "只扫轴位MRS", "D": "只扫冠状位T2WI", "E": "扫描下肢MRA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-134", "kp": "腰椎间盘突出MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】腰椎间盘突出以腰4-5、腰5骶1最常见，矢状位T1/T2WI整体显示间盘与椎管，横断位T2WI精确判断突出方向与神经根受压，故A正确。\n【为什么错】B：仅矢状T1WI无法显示椎间盘退变信号细节与横断关系。C：MRS与间盘突出无关。D：冠状位不显示椎间盘与神经根关系。E：下肢MRA与腰椎间盘无关。", "tr": "腰椎间盘突出“矢状+横断T2”为常规；临床定位与扫描范围要覆盖最常见节段。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1123", "t": "案例分析题", "s": "患者男性，19岁，进行性双下肢无力伴背部束带感2个月，临床疑脊髓内占位（室管膜瘤可能），拟行胸段脊髓MR检查明确病变范围与性质。技师安排扫描时，正确的方案是", "o": {"A": "矢状位T1WI、T2WI及增强后T1WI，加横断位明确脊髓内病灶定位", "B": "仅矢状位DWI", "C": "仅冠状位MRA", "D": "仅横断位SWI", "E": "仅矢状位MRM"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-135", "kp": "脊髓占位MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】脊髓肿瘤MR以矢状位T1WI（显示肿瘤范围与出血）、T2WI（显示囊变水肿）及增强后T1WI（肿瘤强化）为核心，横断位明确肿瘤在脊髓内的位置与脊髓膨胀程度，故A正确。\n【为什么错】B：DWI非脊髓肿瘤常规。C：MRA显示血管。D：SWI用于出血钙化。E：MRM仅显示脑脊液间接征象。", "tr": "脊髓占位“矢状三序列（T1/T2/增强）+横断定位”是标准方案，增强对肿瘤定性关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1124", "t": "案例分析题", "s": "患者男性，52岁，回缩涕血伴耳鸣2个月，鼻咽镜见右侧咽隐窝肿物隆起，病理疑鼻咽癌，拟行MR检查评估肿瘤范围、颅底侵犯及颈部淋巴结。技师制定扫描范围与序列时，正确的是", "o": {"A": "扫描范围自颅底至锁骨上，行轴位T1WI、T2WI脂肪抑制、DWI及增强扫描", "B": "仅扫描鼻咽部轴位T2WI", "C": "仅扫描颈部淋巴结区", "D": "仅扫描矢状位T1WI", "E": "仅扫描下颌区"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-136", "kp": "鼻咽癌MR检查范围", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】鼻咽癌易沿颅底孔道（破裂孔、卵圆孔等）向上侵犯并发生颈部淋巴结转移，MR范围须从颅底延伸至锁骨上，轴位T1WI、T2WI脂肪抑制显示肿瘤与淋巴结，DWI与增强辅助定性，故A正确。\n【为什么错】B：范围过小漏诊颅底侵犯与转移。C：仅淋巴结遗漏原发灶。D：单矢状位无法评价两侧与颅底。E：下颌区范围不足。", "tr": "头颈肿瘤MR“大范围+多序列+DWI+增强”；范围不足是漏诊主因。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1125", "t": "案例分析题", "s": "患者女性，38岁，右眼球突出伴复视1个月，超声示右眼眶肌锥内占位，临床疑海绵状血管瘤，拟行眼眶MR检查。技师设置扫描序列时，为清晰显示视神经、眼外肌与病变，应优先采用的序列是", "o": {"A": "脂肪抑制T2WI（或STIR）加增强后脂肪抑制T1WI", "B": "不抑脂的T1WI", "C": "仅SWI", "D": "仅MRA", "E": "仅MRU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-137", "kp": "眼眶MR序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】眶内脂肪高信号会掩盖视神经与病变，脂肪抑制T2WI/STIR可压低脂肪突出病变与神经；增强后脂肪抑制T1WI显示病灶强化特征，故A正确。\n【为什么错】B：不抑脂T1WI脂肪干扰严重。C：SWI用于出血钙化。D：MRA显示血管。E：MRU为尿路水成像。", "tr": "眶内成像“抑脂”是关键词；视神经、眼外肌与脂肪的高对比依赖脂肪抑制序列。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1126", "t": "案例分析题", "s": "患者女性，45岁，左乳外上象限肿块，超声BI-RADS 4C类，拟行乳腺MR动态增强检查，设备为3T磁体，使用专用乳腺线圈。技师制定扫描方案，需包括动态增强多期扫描、DWI及时间-信号强度曲线分析。关于该检查的叙述，正确的是", "o": {"A": "俯卧位双乳悬垂于线圈孔槽，先平扫再注射钆剂行多期动态增强", "B": "仰卧位用体部线圈扫描", "C": "只扫T2WI不增强", "D": "只扫DWI不增强", "E": "增强后只扫MRA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-138", "kp": "乳腺DCE-MRI方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】乳腺DCE-MRI标准流程为俯卧位、专用线圈，平扫（T1、T2抑脂、DWI）后团注钆剂行多期（如6期）动态增强扫描，并生成时间-信号强度曲线与MIP，故A正确。\n【为什么错】B：仰卧位体部线圈图像质量差。C：不增强无法评估血供与曲线。D：仅DWI信息不足。E：MRA非乳腺增强方案。", "tr": "乳腺DCE“平扫+团注多期+曲线”完整链条；体位线圈错误则全盘皆输。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1127", "t": "案例分析题", "s": "患者男性，58岁，扩张型心肌病病史，近期心衰加重，超声示左心室扩大、射血分数28%，临床疑心肌纤维化，拟行心脏MR评估心肌活性与纤维化分布。技师安排心脏MR检查时，正确的是", "o": {"A": "心电门控下采集黑血与亮血序列，注射钆剂后10～15分钟行LGE扫描", "B": "不接心电门控直接扫描", "C": "只扫LGE不扫电影", "D": "用SWI评价心肌", "E": "用MRU评价心功能"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-139", "kp": "心脏MR心肌纤维化评估", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】心脏MR须心电门控下采集，黑血序列显示心肌形态、亮血电影评价心功能，注射钆剂后10～15分钟LGE显示心肌纤维化（DCM常呈中壁强化），故A正确。\n【为什么错】B：无门控心脏图像无法诊断。C：电影序列是心功能评价必需。D：SWI不用于心肌纤维化。E：MRU为尿路水成像。", "tr": "心肌纤维化“LGE”是金标准；门控+电影+LGE是心脏MR三件套。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1128", "t": "案例分析题", "s": "患者男性，60岁，突发胸背部撕裂样疼痛2小时，血压200/120 mmHg，临床疑主动脉夹层，拟行主动脉CE-MRA紧急检查。技师需规划对比剂注射、采集范围与时相。关于该检查技术，正确的是", "o": {"A": "高压注射器团注钆剂，多期动态采集覆盖主动脉全程，MIP重建显示内膜片", "B": "手推对比剂后单期扫描", "C": "只扫升主动脉", "D": "用2D TOF替代", "E": "扫描前禁水12小时"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-140", "kp": "主动脉夹层CE-MRA", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】主动脉夹层累及范围广，需高压注射器团注并多期动态扫描覆盖全程，MIP可显示内膜片、真假腔及分支受累，故A正确。\n【为什么错】B：手推单期易错过真假腔充盈时相。C：只扫升主动脉漏诊降主动脉夹层。D：2D TOF对大血管急症敏感性与时间效率不足。E：主动脉MRA无需禁水12小时。", "tr": "主动脉CE-MRA“团注+多期+全程覆盖+MIP”四要素；内膜片显示依赖时相准确性。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1129", "t": "案例分析题", "s": "患者女性，48岁，体检超声发现肝右叶2.5 cm强回声结节，拟行肝脏MRI动态增强检查明确性质。技师安排扫描时，肝血管瘤的典型动态增强MR表现及技术要点是", "o": {"A": "动脉期周边结节状强化，延迟期向心性填充呈均匀高信号，延迟扫描时间需足够长", "B": "动脉期整体高强化、延迟期廓清", "C": "无强化", "D": "仅平扫即可诊断", "E": "强化后即刻快速廓清"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-141", "kp": "肝血管瘤动态增强", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肝血管瘤典型表现为动脉期病灶周边结节状强化、随时间向心性填充，延迟期呈均匀高信号，因此延迟扫描（可至5～10分钟）必须足够长才能显示完全填充，故A正确。\n【为什么错】B：整体高强化+廓清为HCC表现。C：血管瘤血供丰富必有强化。D：仅平扫无法显示强化模式。E：快速廓清为恶性特征。", "tr": "血管瘤“边缘结节状强化+延迟填充”与HCC“快进快出”是肝增强两大经典鉴别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1130", "t": "案例分析题", "s": "患者男性，58岁，乙肝肝硬化10年，甲胎蛋白进行性升高，超声示肝右叶低回声占位，临床疑肝细胞癌，拟行肝脏MRI动态增强结合DWI检查。技师设定扫描方案，肝细胞癌在动态增强与DWI上的典型表现为", "o": {"A": "动脉期明显强化、门脉期及延迟期廓清，DWI呈高信号、ADC降低", "B": "动脉期无强化", "C": "延迟期持续上升强化", "D": "DWI低信号", "E": "各期均无强化"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-142", "kp": "肝细胞癌增强与DWI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】HCC典型“快进快出”：动脉期明显强化（富血供）、门脉期及延迟期廓清；癌细胞密集扩散受限，DWI高信号、ADC降低，故A正确。\n【为什么错】B：HCC动脉期强化明显。C：持续上升强化为血管瘤填充或纤维化。D：HCC扩散受限DWI应高信号。E：HCC必有血供强化。", "tr": "HCC“快进快出+DWI高+ADC低”；与血管瘤“迟填充”相反，是必考鉴别点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1131", "t": "案例分析题", "s": "患者男性，72岁，无痛性进行性黄疸2周，超声示肝内外胆管扩张、胆总管下段腔内可疑等回声，临床疑胆总管下段肿瘤性梗阻，拟行MRCP及上腹部MR检查。技师安排检查时，正确的技术方案是", "o": {"A": "重T2加权MRCP显示胆道梗阻形态，加薄层T2WI及增强扫描评价下段病变性质", "B": "只做MRCP一个序列", "C": "用DWI替代MRCP", "D": "只做MRA", "E": "用SWI显示胆管"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-143", "kp": "胆道梗阻MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】MRCP显示胆道树梗阻部位与扩张形态，但定性有限；联合薄层T2WI与增强扫描可观察下段病变（肿瘤强化）及周围结构，完成定位与定性，故A正确。\n【为什么错】B：仅MRCP无法定性梗阻病变。C：DWI不能显示胆道形态。D：MRA显示血管。E：SWI不显示胆管。", "tr": "梗阻性黄疸MR“MRCP（管腔）+薄层增强（定性）”缺一不可，这体现水成像的应用边界。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1132", "t": "案例分析题", "s": "患者女性，55岁，上腹饱胀伴腰背痛2个月，CT示胰头占位、胰管扩张呈“双管征”，临床疑胰头癌，拟行胰腺MR联合MRCP检查评估可切除性。技师制定扫描方案，正确的做法是", "o": {"A": "薄层T1WI、T2WI脂肪抑制、DWI及动态增强，联合MRCP显示胰胆管", "B": "仅MRCP一个序列", "C": "仅冠状位T1WI", "D": "仅SWI", "E": "仅MRU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-144", "kp": "胰腺MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】胰腺MR以薄层T1WI、T2WI脂肪抑制（显示肿瘤与胰周脂肪）、DWI（ADC降低提示恶性）及动态增强（乏血供强化模式）为核心，MRCP显示双管征与梗阻部位，联合评估可切除性，故A正确。\n【为什么错】B：仅MRCP无法评估肿瘤本身。C：单冠状位信息不足。D：SWI不用于胰腺癌。E：MRU为尿路成像。", "tr": "胰腺癌MR“实质多序列+DWI+增强+MRCP”组合；双管征为胰头癌间接征象。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1133", "t": "案例分析题", "s": "患者男性，61岁，体检超声发现左肾2 cm实性占位，临床疑肾细胞癌，拟行肾脏MR检查评估肿瘤分期及血管侵犯。技师制定扫描方案，正确的是", "o": {"A": "呼吸触发采集轴位T1WI、T2WI脂肪抑制及DWI，动态增强分皮质期、髓质期、排泄期", "B": "仅矢状位T2WI", "C": "仅MRU", "D": "仅SWI", "E": "仅冠状位STIR"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-145", "kp": "肾脏MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肾脏MR常规呼吸触发采集T1/T2抑脂与DWI（鉴别囊实性），动态增强按肾脏血流特点分皮质期、髓质期与排泄期，利于显示肿瘤强化与肾静脉、腔静脉瘤栓，故A正确。\n【为什么错】B：单方位不完整。C：MRU显示积水形态，不显示肿瘤。D：SWI用于出血钙化。E：单STIR冠状位信息不足。", "tr": "肾脏增强“皮质-髓质-排泄”三期命名区别于肝脏“动脉-门脉-延迟”，是经典易混点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1134", "t": "案例分析题", "s": "患者男性，66岁，PSA 15 ng/ml，直肠指诊前列腺右侧质硬结节，穿刺活检证实前列腺腺癌（Gleason 7），拟行前列腺多参数MRI行局部分期（T分期）。技师安排检查时，正确的技术方案是", "o": {"A": "高分辨T2WI三方位、DWI/ADC及动态增强，必要时加MRS，观察包膜侵犯与精囊受累", "B": "仅轴位T1WI", "C": "仅MRU", "D": "仅SWI", "E": "仅矢状位STIR"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-146", "kp": "前列腺癌局部分期MRI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】前列腺癌局部分期需高分辨T2WI三方位（轴、矢、冠）观察外周带病灶与包膜、精囊受累，DWI/ADC与动态增强辅助，MRS可作补充，故A正确。\n【为什么错】B：T1WI无分区显示能力。C：MRU与前列腺癌分期无关。D：SWI不用于分期。E：STIR非前列腺常规。", "tr": "前列腺癌分期“T2WI三方位的包膜/精囊评估”是核心；DWI低b值勿受T2穿透干扰。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1135", "t": "案例分析题", "s": "患者女性，52岁，阴道不规则出血1个月，超声示宫腔内占位、内膜增厚，临床疑子宫内膜癌，拟行盆腔MR评估肌层浸润深度。技师安排检查时，正确的方案是", "o": {"A": "矢状位高分辨T2WI显示内膜与肌层三层结构，加DWI及动态增强判断肌层浸润", "B": "仅轴位T1WI", "C": "仅冠状位STIR", "D": "仅MRU", "E": "仅横断位SWI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-147", "kp": "子宫内膜癌MR", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】子宫内膜癌分期关键是肌层浸润深度，矢状位高分辨T2WI显示子宫三层结构（结合带中断提示浸润），DWI与动态增强辅助判断浸润范围，故A正确。\n【为什么错】B：T1WI不能区分内膜肌层。C：STIR冠状位不显示结合带细节。D：MRU与子宫病变无关。E：SWI不用于子宫内膜癌。", "tr": "子宫内膜癌“矢状T2WI看结合带、动态增强+DWI看浸润”是分期核心技术。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1136", "t": "案例分析题", "s": "患者男性，22岁，足球比赛扭伤右膝，膝关节肿胀、前抽屉试验阳性，临床疑前交叉韧带断裂，拟行膝关节MR检查。技师制定扫描方案，正确的做法是", "o": {"A": "矢状位PD加权（沿前交叉韧带走行）及脂肪抑制T2加权，配合冠状位与轴位", "B": "仅轴位T1WI", "C": "仅冠状位SWI", "D": "仅矢状位MRA", "E": "仅横断位MRS"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-148", "kp": "前交叉韧带MR", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】前交叉韧带显示需矢状位沿其走行方向扫描，PD加权显示韧带纤维连续性（断裂呈中断、肿胀、信号异常），脂肪抑制T2加权显示伴随的骨挫伤与积液，多方位互补，故A正确。\n【为什么错】B：T1WI对韧带水肿显示差。C：SWI用于出血。D：MRA显示血管。E：MRS非韧带检查。", "tr": "前交叉韧带“矢状PD沿走行”是核心；关节MR“PD/FS-T2”是韧带与软骨显示的通用序列。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1137", "t": "案例分析题", "s": "患者女性，51岁，右肩疼痛伴上举受限3个月，夜间痛明显，体检冈上肌止点压痛、Jobe试验阳性，临床疑肩袖损伤，拟行肩关节MR检查。技师制定扫描方案，正确的是", "o": {"A": "斜冠状位脂肪抑制PD/T2沿冈上肌长轴显示肌腱，配合斜矢状位与轴位", "B": "仅轴位T1WI", "C": "仅纯矢状位", "D": "仅冠状位MRA", "E": "仅横断位DWI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-149", "kp": "肩袖损伤MR", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】肩袖损伤（尤其冈上肌腱）须在斜冠状位（沿冈上肌长轴）用脂肪抑制PD/T2显示肌腱全层与撕裂（液体高信号贯穿肌腱），配合斜矢状位显示肩袖肌肉萎缩、轴位显示肩胛下肌等，故A正确。\n【为什么错】B：T1WI液体低信号，撕裂显示差。C：纯矢状位不沿肌腱长轴。D：MRA显示血管。E：DWI非常规。", "tr": "肩袖检查“斜冠状位沿冈上肌长轴+FS-PD/T2”是标准；撕裂诊断依赖液体敏感序列。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U10-1138", "t": "案例分析题", "s": "患者男性，70岁，间歇性跛行6个月，双下肢皮温低、足背动脉搏动减弱，超声示下肢动脉多发狭窄，临床疑下肢动脉闭塞症，拟行下肢动脉CE-MRA评估全程血管病变。技师制定分段扫描方案，正确的是", "o": {"A": "分髂股、股腘、膝下三段连续采集，高压注射器团注钆剂，多段MIP拼接显示全程", "B": "单次扫描覆盖全下肢", "C": "用2D TOF替代全程", "D": "仅扫描膝关节以下", "E": "不用对比剂直接扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-150", "kp": "下肢动脉CE-MRA方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (9)外周血管", "ex": "【为什么对】下肢血管行程长，须分段（髂股、股腘、膝下）连续采集以保证各段分辨率与对比剂时相同步，最终MIP拼接显示全程，故A正确。\n【为什么错】B：单次大范围扫描分辨率与信噪比不足。C：2D TOF扫描慢、对慢血流与钙化段显示差，非首选。D：仅膝下遗漏近段狭窄。E：非增强方案不适于精确评估全程闭塞。", "tr": "下肢CE-MRA“三段式+步进拼接”是标志性技术；覆盖全程与段内分辨率需平衡。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-0101", "t": "单选题", "s": "关于DSA检查适应证与禁忌证的叙述，正确的是", "o": {"A": "有明确碘对比剂严重过敏史者，属于碘对比剂血管造影的禁忌", "B": "严重心、肝、肾功能衰竭患者可按常规方案完成DSA，无需特殊评估", "C": "甲状腺功能亢进未控制者使用含碘对比剂无任何风险", "D": "严重凝血功能障碍不影响穿刺插管，不属于禁忌范畴", "E": "妊娠早期是DSA的适应证之一"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-001", "kp": "DSA适应证与禁忌证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】A正确：明确的碘对比剂严重过敏（既往发生过喉头水肿、休克等重度反应）是碘剂血管造影公认的禁忌，必须权衡改用CO₂造影、MRA等替代方案或在充分预处理与抢救准备下评估。【为什么错】B错误：严重心、肝、肾功能衰竭属于禁忌或高危状态，需先纠正、限量并做水化等准备，不能按常规方案实施。C错误：未控制的甲状腺功能亢进者使用含碘对比剂可诱发甲状腺危象，属禁忌或高危。D错误：严重凝血功能障碍（如INR明显延长、血小板显著减少）会导致穿刺部位难以止血、血肿甚至腹膜后出血，属于禁忌。E错误：妊娠期尤其早期属于电离辐射相对禁忌，仅在危及生命且无替代手段时权衡实施。", "tr": "禁忌证要区分“绝对”与“相对”：现代介入实践中绝对禁忌很少，多数为可纠正的相对禁忌（凝血异常、肾功能不全、心衰）；而重度碘过敏与未控制的甲亢是与对比剂本身直接相关的经典禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0102", "t": "多选题", "s": "股动脉穿刺插管术后第2天，穿刺区出现搏动性包块，超声显示包块与股动脉之间有细颈相通并见“往返血流”。关于该并发症，下列正确的有", "o": {"A": "穿刺点过低、误穿股浅动脉或股深动脉是重要危险因素", "B": "压迫止血时间不足、过早下地活动及术后抗凝治疗可增加其发生率", "C": "局部听诊可闻及收缩期杂音，触诊常可扪及震颤", "D": "其瘤壁由完整的内膜、中膜、外膜三层构成，性质与真性动脉瘤相同", "E": "超声引导下压迫或瘤腔内注射凝血酶是常用的非手术处理方法"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-002", "kp": "医源性假性动脉瘤", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】A正确：穿刺点低于股动脉分叉时穿中股浅或股深动脉，管径细、位置深且缺乏股骨头作压迫衬托，止血困难，易形成假性动脉瘤。B正确：压迫时间不足、过早活动、抗凝抗血小板治疗均使穿刺口持续渗血形成搏动性血肿腔。C正确：血液经瘤颈往返进出，产生收缩期杂音与震颤，是典型体征。E正确：超声引导下瘤颈压迫和瘤腔内凝血酶注射是目前首选的非手术处理，失败者再考虑覆膜支架或外科修补。【为什么错】D错误：假性动脉瘤壁并非三层血管壁结构，而是由血肿机化后的纤维组织与周围软组织构成，与真性动脉瘤（瘤壁含血管壁三层结构）本质不同。", "tr": "“假性”与“真性”动脉瘤的核心区别在瘤壁构成而不是形态；另需与动静脉瘘鉴别——动静脉瘘为连续性“机器样”杂音、超声见动静脉间高速低阻分流，而假性动脉瘤为收缩期杂音、瘤颈“往返血流”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-0103", "t": "单选题", "s": "患者行诊断性DSA后拔除6F股动脉鞘，需人工压迫止血。下列操作中错误的是", "o": {"A": "压迫点应位于皮肤穿刺点近心端约1~2cm处的动脉穿刺口上方", "B": "压迫力度以完全阻断同侧足背动脉搏动为准，并维持至解除压迫为止", "C": "持续压迫约15~20min后逐步减压，再以弹力绷带加压包扎、穿刺侧下肢制动", "D": "术后应定时观察穿刺点有无渗血、皮下瘀斑及进行性增大的包块", "E": "术后应观察足背动脉搏动、肢体皮温、颜色与感觉，警惕远端缺血"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-003", "kp": "穿刺部位止血与并发症观察", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】B错误故为本题答案：正确的压迫强度应在有效止血的同时保留远端血流，一般以能扪及足背动脉搏动（或稍减弱）为宜；若长时间完全阻断远端血流，可诱发动脉血栓形成与下肢缺血。【为什么错】A正确：由于穿刺针斜行进入，动脉壁上的穿刺口高于皮肤穿刺点，压迫点应上移1~2cm才能压住动脉破口。C正确：诊断性造影常规压迫15~20min，随后加压包扎并制动，是标准流程。D正确：进行性增大的包块提示活动性出血或假性动脉瘤形成。E正确：观察远端灌注是发现血栓栓塞并发症的关键。", "tr": "命题常在“压迫点位置”和“压迫力度”上设陷阱：压迫点要比皮肤穿刺点更靠近心端，而力度要“止血但不断流”，不是越紧越久越好。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-0104", "t": "多选题", "s": "为降低介入手术中对比剂相关急性肾损伤的风险，下列围手术期措施合理的有", "o": {"A": "术前评估血肌酐与eGFR，识别高危患者并给予等渗生理盐水静脉水化", "B": "选用低渗或等渗非离子型对比剂，并将对比剂总量控制在与肾功能相匹配的范围内", "C": "术中充分利用路径图、低帧率透视与既往影像，减少不必要的重复造影", "D": "术前常规使用大剂量袢利尿剂强制利尿以“冲洗”肾脏", "E": "近期需再次行含碘对比剂检查时，应尽量延长两次检查间隔并复查肾功能"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-004", "kp": "介入术中对比剂肾损伤防控", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】A正确：肾功能评估与充分水化是预防对比剂相关急性肾损伤最有循证依据的措施。B正确：对比剂用量与肾损伤风险正相关，低渗/等渗非离子型对比剂肾毒性较低。C正确：路径图可在少量对比剂条件下引导插管，低帧率与参考既往影像可显著减少造影次数与总量，是技师可直接控制的环节。E正确：短期内反复给予碘对比剂会叠加肾脏负荷，应尽量拉开间隔并随访肾功能。【为什么错】D错误：强制利尿会造成血容量不足，反而加重肾髓质缺血，除非在容量监测下配合补液，否则单纯大剂量利尿剂是有害的。", "tr": "“多排尿=保护肾脏”是常见错误直觉。预防的核心是扩容水化与减量，而不是脱水利尿；甘露醇、呋塞米单用均不推荐。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-0105", "t": "多选题", "s": "择期行诊断性DSA前，属于常规必须复核的实验室及辅助检查项目的有", "o": {"A": "凝血酶原时间（PT）及国际标准化比值（INR）", "B": "活化部分凝血活酶时间（APTT）与血小板计数", "C": "血肌酐及估算肾小球滤过率（eGFR）", "D": "静脉注射稀释碘对比剂的“碘过敏试验”，结果阴性方可手术", "E": "心电图及血源性传染病筛查"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-005", "kp": "DSA术前实验室检查", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】A、B正确：凝血功能与血小板直接决定穿刺部位止血能力，是术前必查项；一般要求INR降至1.5以下、血小板处于安全水平。C正确：肾功能决定对比剂用量与水化方案。E正确：心电图评估心脏基础状态与术中风险，传染病筛查用于器械与人员防护、消毒隔离安排。【为什么错】D错误：小剂量碘过敏试验对严重过敏样反应既无预测价值，本身还可能诱发反应，目前已不作为常规要求；替代做法是详细询问过敏史、哮喘史，对高危者行糖皮质激素与抗组胺药预处理并备好抢救设备与药品。", "tr": "“皮试阴性即安全”是最典型的过时观念。碘对比剂重度反应属非IgE介导的类过敏反应，试验剂量无法预测；重点在于危险因素筛查与抢救准备。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-0106", "t": "单选题", "s": "患者因心房颤动长期口服华法林，拟行择期诊断性脑血管DSA。围手术期抗凝药物处理最合理的方案是", "o": {"A": "维持原剂量华法林不作任何调整，直接穿刺", "B": "术前3~5天停用华法林并复查INR，待INR降至1.5以下再穿刺，血栓栓塞高危者以低分子肝素桥接", "C": "术前当日给予大剂量维生素K快速拮抗后立即穿刺", "D": "术前改为阿司匹林联合氯吡格雷双联抗血小板治疗后立即手术", "E": "无需评估INR，仅需在术后延长压迫时间"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-006", "kp": "围手术期抗凝抗血小板处理", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】B正确：华法林半衰期长，需提前3~5天停药并以INR作为客观判断指标；对卒中或血栓高危者在停药窗口内用低分子肝素桥接，兼顾出血与栓塞两方面风险，是择期动脉穿刺的标准做法。【为什么错】A错误：INR明显升高时穿刺出血、血肿及腹膜后出血风险显著增加。C错误：大剂量维生素K快速拮抗仅用于严重出血等紧急情况，且会造成术后数日华法林抵抗，不适用于择期手术。D错误：双联抗血小板并不能替代华法林预防房颤所致心源性栓塞，且同样增加穿刺出血风险。E错误：延长压迫不能抵消凝血系统本身的异常，术前必须有INR等客观评估。", "tr": "抗凝与抗血小板要分开对待：单纯诊断性造影通常不必停用阿司匹林；而华法林等口服抗凝药需停药并以INR为准。切勿把“桥接”理解为换用抗血小板药。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0107", "t": "案例分析题", "s": "患者女性，68岁，高血压、2型糖尿病病史多年，因反复短暂性脑缺血发作拟行全脑血管造影。术中发现主动脉弓为Ⅲ型、弓上分支迂曲成角，反复更换导管与导丝超选左侧颈内动脉，累计操作时间约90min。术毕拔鞘时患者出现右侧肢体无力、言语含糊，随后症状持续存在。作为介入技术组成员，对该并发症的分析与预防措施，最恰当的是", "o": {"A": "该表现最可能为导管导丝机械操作致主动脉弓或颈动脉粥样斑块脱落、导管内血栓形成引起的脑栓塞，与Ⅲ型弓、血管迂曲、反复插管及操作时间延长密切相关，预防重在缩短操作时间、规范全身肝素化、导管尾端持续加压滴注冲洗与严格排气", "B": "该表现是碘对比剂对脑组织的直接毒性作用，与器械操作方式和操作时间无关", "C": "只要术中给予全身肝素化，即可完全避免此类栓塞并发症的发生", "D": "导管尾端持续加压滴注仅为保持管腔通畅、便于推注，与预防栓塞无关", "E": "术中一旦出现神经系统症状，应立即拔除所有导管、结束手术并等待症状自行恢复"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-007", "kp": "脑血管造影栓塞并发症", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】A正确：脑血管造影最主要的神经系统并发症为血栓栓塞事件，其危险因素包括高龄、动脉粥样硬化、Ⅲ型弓与血管迂曲、导管导丝反复摩擦斑块、操作时间与透视时间延长；预防措施为规范肝素化、导管持续加压滴注冲洗、严格排气与冲洗、缩短操作时间、必要时更换更适合的导管形态减少反复试插。【为什么错】B错误：碘对比剂虽有一过性神经毒性，但持续存在的偏侧运动语言障碍以栓塞更为符合，且操作因素证据明确。C错误：肝素化能降低但不能完全消除栓塞风险，斑块碎屑等机械性栓子并不受抗凝影响。D错误：持续加压滴注的首要目的正是防止导管腔内血栓形成，是预防栓塞的关键环节。E错误：出现症状时应立即评估并保留通路，便于即刻造影明确闭塞部位并考虑取栓等补救治疗，盲目撤除通路会延误救治。", "tr": "把“肝素化”当成万能保险是典型错误；机械性斑块碎屑栓塞靠抗凝无法预防，只能靠减少器械对血管壁的反复骚扰与缩短操作时间。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0108", "t": "单选题", "s": "关于经股动脉入路DSA的术前准备，下列做法不正确的是", "o": {"A": "双侧腹股沟区及会阴部备皮并做好皮肤清洁", "B": "术前禁食4~6h，必要时训练患者床上排尿与屏气配合", "C": "建立静脉通道，连接心电、无创血压及脉搏血氧饱和度监护", "D": "无需追问既往对比剂使用史与过敏史，只要碘过敏试验阴性即可安排手术", "E": "核对既往影像资料、实验室结果、知情同意书并做手术部位标记"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-008", "kp": "DSA术前常规准备", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】D错误故为本题答案：既往对比剂反应史、过敏体质、哮喘史是预测严重不良反应的最重要信息，任何情况下都必须详细询问并记录，不能以试验结果替代病史采集。【为什么错】A正确：双侧腹股沟备皮是为穿刺失败需改换对侧留有余地。B正确：禁食可降低反应或急救时的误吸风险，腹部血管造影需屏气配合，术后需卧床排尿，故应提前训练。C正确：术中生命体征连续监护是常规要求。E正确：核对资料与知情同意属于术前安全核查内容。", "tr": "本题与“碘过敏试验”考点呼应：试验阴性并不排除严重反应，而阳性也不能等同于过敏，因此病史询问与抢救准备才是核心。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-0109", "t": "单选题", "s": "关于经典Seldinger技术与改良Seldinger技术的区别，正确的是", "o": {"A": "经典法穿刺针穿透血管前后壁后缓慢退针，见血液喷出再送入导丝；改良法只穿透血管前壁，见喷血即送入导丝", "B": "经典法只穿透血管前壁，改良法需贯穿血管前后壁", "C": "两者的区别在于是否使用血管鞘，与穿刺进针方式无关", "D": "改良法因贯穿血管后壁，穿刺部位血肿发生率高于经典法", "E": "经典法只能用于静脉穿刺，改良法只能用于动脉穿刺"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-009", "kp": "Seldinger技术与改良Seldinger技术", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (1)穿刺插管技术（Seldinger）", "ex": "【为什么对】A正确：Seldinger于1953年创立的经典法采用带针芯穿刺针贯穿血管前后壁，拔出针芯后缓慢退针至血液呈搏动性喷出，再送入导丝、退针、置入导管或血管鞘；改良法使用不带针芯的薄壁穿刺针仅穿透前壁，见回血喷出即送导丝，操作步骤更简、后壁无损伤。【为什么错】B错误：两者恰好说反。C错误：血管鞘是两种方法均可使用的器材，区别在于是否贯穿后壁。D错误：贯穿后壁的是经典法，改良法因不损伤后壁，血肿与出血并发症更少，故目前临床多用改良法。E错误：两种方法对动脉、静脉穿刺均适用，与血管种类无关。", "tr": "记忆口诀：经典“穿透双壁再退针”，改良“只穿前壁见喷血”。命题常把二者互换，或让考生误以为改良法并发症更多。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0110", "t": "案例分析题", "s": "患者男性，62岁，身高170cm、体重90kg（BMI约31），因下肢间歇性跛行拟经右股动脉入路行腹主动脉及双下肢动脉造影。患者腹部脂肪下垂明显，腹股沟皮肤皱褶位置低于骨性标志。技师配合医师定位穿刺点并摆放体位。关于该患者的股动脉穿刺定位与操作，下列正确的是", "o": {"A": "肥胖患者的腹股沟皮肤皱褶即为腹股沟韧带的可靠体表标志，可直接在皱褶处穿刺", "B": "穿刺点宜取腹股沟韧带下方约2cm、股动脉搏动最明显处，透视下大致相当于股骨头中下部水平，进针角度约30°~45°，必要时以透视或超声辅助定位", "C": "穿刺点越靠远端越安全，选择股动脉分叉以下的股浅动脉可减少出血风险", "D": "穿刺点定在腹股沟韧带以上更利于术后压迫止血", "E": "肥胖患者应将进针角度加大至80°~90°，以缩短皮肤至血管的穿刺距离"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-010", "kp": "股动脉穿刺点定位", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (1)穿刺插管技术（Seldinger）", "ex": "【为什么对】B正确：理想穿刺点位于股总动脉、腹股沟韧带下方约2cm处，此处动脉后方有股骨头作为衬托，压迫止血可靠；透视下以股骨头中下部为参考、超声引导可进一步提高一次穿刺成功率，进针角度30°~45°有利于导丝顺畅推进。【为什么错】A错误：肥胖患者皮肤皱褶常明显下移，按皱褶穿刺易穿到股动脉分叉以下，是假性动脉瘤的重要成因。C错误：股浅、股深动脉管径细、位置深，缺乏骨性衬托，穿刺后止血困难，并发症更多。D错误：韧带以上为髂外动脉，出血可流入腹膜后而无法压迫，是腹膜后血肿的主要原因。E错误：角度过大会造成导丝推送成角困难、鞘管打折，也不利于止血。", "tr": "“皮肤皱褶”只是粗略参考，肥胖患者必须改用骨性标志或影像引导；穿刺“过高”致腹膜后血肿、“过低”致假性动脉瘤与动静脉瘘，是两个方向的经典陷阱。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-0111", "t": "多选题", "s": "关于经桡动脉、肱动脉入路血管造影的特点，下列正确的有", "o": {"A": "经桡动脉入路前应行Allen试验或血氧饱和度描记，评估掌弓侧支循环是否通畅", "B": "与股动脉入路相比，桡动脉入路止血方便、可早期下床活动，穿刺部位血管并发症较少", "C": "桡动脉管径较细、易发生痉挛，所选鞘管口径通常不超过6F", "D": "桡动脉入路不受主动脉弓类型与锁骨下动脉迂曲的影响", "E": "肱动脉为上肢主要供血动脉且伴行正中神经，血肿可致骨筋膜室综合征与神经损伤，一般不作首选入路"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-011", "kp": "血管穿刺入路选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (1)穿刺插管技术（Seldinger）", "ex": "【为什么对】A正确：桡动脉闭塞后手部血供依赖尺动脉与掌弓侧支，术前评估侧支循环可避免手部缺血。B正确：桡动脉位置表浅、下方有桡骨衬托，压迫止血可靠，患者术后可即刻活动，是其最大优势。C正确：桡动脉内径小，大口径鞘管易致痉挛、闭塞，故常规使用5~6F。E正确：肱动脉周围间隙狭小且有正中神经伴行，血肿压迫可造成严重后果，故一般排在股、桡动脉之后选择。【为什么错】D错误：经桡动脉行弓上血管或内脏血管造影，导管仍需经锁骨下动脉、头臂干进入主动脉弓，Ⅲ型弓、锁骨下动脉迂曲与右侧变异反而会增加超选难度，这正是桡动脉入路的重要局限。", "tr": "桡动脉入路“并发症少”指的是穿刺部位并发症；其代价是路径长、受弓型与上肢血管迂曲影响、器械口径受限，不能笼统认为“各方面都优于股动脉”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-0112", "t": "单选题", "s": "关于DSA常用导管与导丝的选择，下列叙述错误的是", "o": {"A": "猪尾（pigtail）导管头端卷曲、侧孔多，耐受高流率，适用于主动脉、左心室等大腔室高流率造影", "B": "Cobra导管头端呈钩状弯曲，适于腹腔干、肠系膜动脉、肾动脉等内脏动脉的选择性插管", "C": "Simmons（西蒙斯）类导管适用于弓上分支开口成角、路径迂曲时的超选择插管", "D": "亲水涂层超滑导丝表面摩擦力小，有利于通过迂曲、狭窄的血管段", "E": "超滑导丝头端柔软，可长时间留置于靶血管内替代交换导丝，不必顾虑内膜损伤"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-012", "kp": "导管导丝选择原则", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (1)穿刺插管技术（Seldinger）", "ex": "【为什么对】E错误故为本题答案：超滑导丝虽头端柔软，但其亲水涂层在血液中易被血栓附着，长时间留置或反复进退可造成内膜损伤、夹层甚至涂层脱落栓塞；需要长时间支撑或器械交换时应换用交换导丝（长导丝、加硬导丝），并定期用肝素盐水擦拭导丝。【为什么错】A正确：猪尾导管多侧孔可分散注射冲击力，避免高流率下导管“甩鞭”与血管内膜损伤，是主动脉与左室造影的标准器械。B正确：Cobra是内脏动脉超选的经典导管。C正确：Simmons导管需在主动脉内成襻后回拉进入分支，适合成角迂曲开口。D正确：亲水涂层的作用即降低摩擦、便于通过病变段。", "tr": "端孔导管禁用于高流率注射（易致血管内膜损伤或导管移位），高流率造影必须选多侧孔的猪尾类导管——这是与本题相关的高频考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0113", "t": "多选题", "s": "关于动脉内DSA（IA-DSA）与静脉内DSA（IV-DSA）的比较，下列正确的有", "o": {"A": "IA-DSA将导管插至靶动脉或其近端注射，对比剂用量少、可适当稀释，血管显示清晰", "B": "IV-DSA经外周静脉注射，对比剂到达靶动脉时已被大量稀释，需高浓度大剂量，图像信噪比低", "C": "IV-DSA时全身血管几乎同时显影，相互重叠，难以分辨细小分支，目前临床已很少使用", "D": "IA-DSA由于是动脉内直接注药，因此不需要作时间减影处理", "E": "IA-DSA可在造影的同一通路上直接完成栓塞、成形等介入治疗"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-013", "kp": "IA-DSA与IV-DSA比较", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】A正确：动脉内注射使对比剂直接进入靶血管床，用量小、浓度可降低（如稀释至50%~70%），显影锐利。B正确：静脉注射经右心、肺循环、左心稀释后才到达动脉，血管内碘浓度低，必须提高浓度与总量，且噪声相对突出。C正确：IV-DSA无选择性，动静脉同时显影并重叠，是其被淘汰的根本原因。E正确：“诊疗一体化”是IA-DSA相对于无创血管成像与IV-DSA的核心优势。【为什么错】D错误：无论动脉内还是静脉内注射，DSA的图像形成都依赖蒙片与造影像相减，时间减影仍是基本成像方式。", "tr": "注意区分“注药途径”（IA/IV）与“减影方式”（时间减影/能量减影）两个不同维度的分类，命题常将两者混淆在同一选项中。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-0114", "t": "多选题", "s": "下列DSA成像方式中，属于时间减影范畴的有", "o": {"A": "脉冲方式", "B": "超脉冲方式", "C": "路径图（roadmap）方式", "D": "K边缘减影（双能量减影）", "E": "岁差运动方式"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-014", "kp": "时间减影的各种方式", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】时间减影的共同特征是“同一部位、不同时刻”两幅（组）图像相减，包括常规脉冲方式、超脉冲方式、连续方式、时间间隔差方式、路径图方式、心电触发方式、岁差运动方式、步进（跟踪）方式与旋转DSA等。A、B属于按X线发生形式划分的时间减影；C路径图是以含对比剂的血管像作为背景蒙片的时间减影应用；E岁差运动方式为C臂作类似陀螺进动的锥形轨迹运动，在不同角度采集蒙片与造影像后减影，用于立体观察血管走行，仍属时间减影。【为什么错】D错误：K边缘减影利用碘在33.2keV处K吸收边缘两侧衰减系数的突变，用高低两种管电压曝光后相减，属能量减影（双能减影），其“变量”是能量而非时间。", "tr": "岁差运动、旋转DSA、步进DSA名字里带“运动”“旋转”，容易被误判为能量减影或独立类别；判别标准只有一个——相减的两幅图像是否来自不同时刻的同一能量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-0115", "t": "单选题", "s": "关于能量减影与混合减影，下列叙述错误的是", "o": {"A": "能量减影利用碘在33.2keV的K吸收边缘两侧衰减系数发生突变的特性，以两种不同管电压先后曝光后加权相减", "B": "能量减影可分别获得软组织像与骨组织像，对轻微运动的敏感程度低于时间减影", "C": "混合减影是先行能量减影消除骨骼影，再作时间减影去除残余软组织背景", "D": "能量减影要求高压发生器在毫秒级内完成千伏切换，对设备要求高，患者受照剂量也相应增加", "E": "能量减影完全不受患者运动影响，可在任何部位取代时间减影"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-015", "kp": "能量减影与混合减影", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】E错误故为本题答案：能量减影的两次曝光之间仍有毫秒级时间间隔，快速运动（心脏搏动、吞咽、肠蠕动）依然会产生配准误差与运动伪影；同时能量减影不能完全消除软组织背景，血管与软组织对比不如时间减影，因此临床上只作为补充手段，不能取代时间减影。【为什么错】A正确：这是能量减影的物理基础。B正确：因两次曝光间隔极短，对轻微运动的容忍度确实优于常规时间减影，这是其主要优点。C正确：混合减影即“能量减影＋时间减影”联合，兼顾去骨与去软组织背景。D正确：高低kV快速切换对高压发生器要求高，且两次曝光使剂量增加，是其推广受限的重要原因。", "tr": "“对运动不敏感”≠“完全不受运动影响”。命题惯用把优点绝对化的方式设错项，遇到“完全”“任何部位”“可取代”一类表述要格外警惕。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0116", "t": "单选题", "s": "关于路径图（roadmap）技术的操作流程与作用，正确的是", "o": {"A": "先透视采集一帧蒙片，再注入少量对比剂使靶血管显影并将其作为新的“血管路径”背景，随后在此背景上实时减影透视引导导丝导管前行", "B": "每推送一次导丝都必须重新注射对比剂并重建路径图，无法在同一背景下连续操作", "C": "路径图属于能量减影技术的一种应用", "D": "路径图只能用于测量血管狭窄程度，不能用于插管引导", "E": "使用路径图会明显增加术中对比剂总用量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-016", "kp": "路径图技术", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】A正确：路径图分三步——第一步透视取蒙片；第二步注入少量对比剂，将血管充盈像与蒙片相减后“冻结”为血管路径背景；第三步在该背景上做实时透视减影，导丝导管以“黑影”形式显示在血管路径中，直观判断器械是否在管腔内。【为什么错】B错误：路径图一旦建立可在同一体位、同一角度下持续使用，只有改变C臂角度、床位或血管形态明显变化时才需重建。C错误：路径图以不同时刻图像相减为基础，属时间减影。D错误：路径图的核心用途正是超选择插管的实时引导。E错误：路径图只需少量对比剂即可建立背景，随后的操作过程无需再注药，反而显著减少对比剂总量与辐射剂量。", "tr": "路径图与“最后一帧保留（LIH）”容易混淆：LIH是保留最后一帧透视图像作静态参考，不做实时减影；路径图是把血管像作背景后仍进行实时减影透视。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-0117", "t": "多选题", "s": "关于旋转DSA、三维旋转血管造影（3D-DSA）与C臂锥形束CT的临床应用，下列正确的有", "o": {"A": "旋转DSA在C臂旋转过程中先采集一组蒙片，再于对比剂充盈时按相同轨迹采集一组造影像，对应角度相减获得多角度减影图像", "B": "3D-DSA在旋转采集基础上重建三维血管模型，可任意角度观察并测量，有助于确定动脉瘤的最佳“工作角度”", "C": "C臂锥形束CT一次旋转采集数百幅投影，用锥形束算法重建出类似CT的断层图像，可显示软组织结构与术中出血", "D": "C臂锥形束CT的密度分辨率与时间分辨率均优于多层螺旋CT", "E": "3D-DSA与C臂锥形束CT在旋转采集期间要求患者保持静止，否则会出现明显的重建伪影"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-017", "kp": "旋转DSA、3D-DSA与C臂CT", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】A正确：旋转DSA需“两次旋转、逐角度配准相减”，因此对C臂旋转轨迹的可重复性要求极高。B正确：三维重建后可自动搜索瘤颈与载瘤动脉分离最佳的角度，并测量瘤体、瘤颈尺寸，指导支架与弹簧圈选择。C正确：锥形束CT（各厂家称DynaCT、XperCT、Innova CT等）弥补了DSA只显示管腔、不能显示实质的不足，可在术中评估出血、栓塞剂分布与支架位置。E正确：旋转采集时间长达数秒，运动会造成条状与模糊伪影，需嘱屏气或必要时镇静。【为什么错】D错误：受平板探测器动态范围、散射线与采集时间限制，C臂锥形束CT的密度（低对比）分辨率与时间分辨率均低于多层螺旋CT，其优势在于介入术中即时获取断层信息，而非取代CT。", "tr": "C臂CT的强项是“空间分辨率高＋术中即时”，弱项是“低对比分辨率差、采集慢、伪影多”。把它描述为全面优于MSCT是常见错误项。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-0118", "t": "单选题", "s": "DSA采集帧率应依检查部位与血流速度选择，下列部位与帧率的组合中不合适的是", "o": {"A": "冠状动脉造影 15~30帧/s", "B": "脑血管造影动脉期 2~6帧/s", "C": "腹部内脏动脉造影 2~3帧/s", "D": "四肢动脉造影 1~3帧/s", "E": "下肢静脉造影 30帧/s以上"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-018", "kp": "DSA帧率选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (3)参数选择", "ex": "【为什么对】E不合适故为本题答案：下肢静脉血流缓慢、充盈过程历时长，采用1~2帧/s甚至更低即可满足诊断，30帧/s以上会造成巨大的图像数据量与不必要的辐射剂量。【为什么错】A合适：冠状动脉随心脏高速搏动，必须高帧率才能冻结运动并观察各心动周期时相。B合适：脑动脉期血流快，2~6帧/s可满足；进入毛细血管期与静脉窦期可进一步降低帧率。C合适：内脏动脉血流速度中等，2~3帧/s常规够用，观察门静脉期可延长采集。D合适：四肢血流慢，低帧率即可。", "tr": "帧率选择的基本原则是“血流越快、运动越剧烈则帧率越高”，同时兼顾剂量最优化；把高帧率理解为“图像质量更好”是典型误区，高帧率只提高时间分辨率并增加剂量。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0119", "t": "案例分析题", "s": "患者男性，56岁，肝硬化病史，行腹腔干动脉造影。回放减影序列时发现：肝区血管影周围出现成对的黑白相间“镶边”样影，膈肌与肠道气影呈条带状干扰，血管细小分支被掩盖，图像难以评价。追问采集过程，患者在注药后曾有一次轻微躯体移动，且肠道蠕动活跃。作为操作技师，下列处理最恰当的是", "o": {"A": "该伪影为运动性伪影，应先从原始序列中重新选取一帧对比剂到达前、与造影像位置一致的图像作蒙片（再蒙片），并配合像素移位重新配准；仍不满意时嘱患者屏气、必要时使用抑制肠蠕动药物后重新采集", "B": "该伪影由对比剂浓度不足引起，应提高对比剂浓度后立即重复造影", "C": "该伪影为平板探测器坏点所致，需联系工程师更换探测器", "D": "仅调整窗宽窗位即可完全消除该运动性伪影", "E": "该伪影属于饱和状伪影，应在体表加放补偿滤过板后重新采集"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-019", "kp": "蒙片选取与再蒙片", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (3)参数选择", "ex": "【为什么对】A正确：成对黑白“镶边”影是蒙片与造影像未能配准的典型运动性伪影。处理顺序应为：①再蒙片（remask）——重新选择一帧对比剂到达前、位置与造影像最吻合、曝光条件一致的图像作蒙片；②像素移位（pixel shift）——对整体平移性错位作水平、垂直方向微调；③若为肠蠕动等非平移性运动，后处理效果有限，需在屏气配合、必要时药物抑制蠕动的条件下重新采集。【为什么错】B错误：浓度不足表现为血管显影淡而均匀，不会形成成对黑白边缘影。C错误：探测器坏点表现为固定位置的点、线状缺陷，与患者运动无关，且不会随血管边缘分布。D错误：窗技术只改变灰阶显示，不能纠正配准误差。E错误：饱和状伪影出现在体厚急剧变化的边缘（如颈胸交界、气体区），表现为过度曝光的白亮区，处理方法才是加补偿滤过或补偿垫，与本例不符。", "tr": "运动性伪影的处理有明确顺序：再蒙片→像素移位→重新采集。要牢记像素移位只能纠正整体平移，对吞咽、肠蠕动、旋转等局部或非平移运动几乎无效。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0120", "t": "单选题", "s": "关于像素移位（pixel shift）技术，下列叙述错误的是", "o": {"A": "通过将蒙片相对于造影像作水平、垂直方向的微量平移重新配准，减轻运动性伪影", "B": "对整体平移性运动造成的错位矫正效果较好", "C": "对吞咽、肠蠕动等局部非平移性运动的矫正效果有限", "D": "属于图像后处理操作，不需要重新曝光，也不增加患者剂量", "E": "像素移位通过增加图像的有效信息量，可提高血管的空间分辨率"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-020", "kp": "像素移位技术", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (3)参数选择", "ex": "【为什么对】E错误故为本题答案：像素移位只是在已有数据上作几何平移以改善配准，并未引入新的图像信息，空间分辨率由探测器像素尺寸、焦点大小与放大率决定，不会因移位而提高；相反过度移位会使配准区以外的部位错位加重。【为什么错】A正确：这是像素移位的基本定义。B正确：整体平移是像素移位最适用的情形。C正确：局部非平移运动需重新采集或再蒙片。D正确：属后处理操作，可反复尝试且不增加剂量，这是其相较重新造影的最大优势。", "tr": "命题喜欢把后处理技术的作用夸大为“提高分辨率”“增加信息量”。凡是不重新曝光的后处理都不会增加原始信息，只能改善显示或配准。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-0121", "t": "多选题", "s": "关于全脑血管造影（通常所称“六根血管”造影）的技术要求，下列正确的有", "o": {"A": "通常包括双侧颈内动脉、双侧颈外动脉与双侧椎动脉的选择性造影", "B": "插管困难或弓上分支迂曲时，可先行主动脉弓造影了解各分支开口位置与解剖变异", "C": "颈内动脉造影常规摄取正位与侧位两个基本体位，必要时加摄斜位", "D": "椎动脉造影只需摄取正位，无需侧位", "E": "采集应涵盖动脉期、毛细血管期与静脉（窦）期全过程"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-021", "kp": "全脑血管造影技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】A正确：完整的全脑血管造影需评价前循环（双侧颈内动脉）、颈外循环（双侧颈外动脉，评估侧支与硬脑膜供血）与后循环（双侧椎动脉），即习称“六根血管”。B正确：主动脉弓造影常取左前斜位展开弓上分支，可判断弓型与开口，是超选困难时的重要步骤。C正确：正、侧位是脑血管造影的基本体位，斜位用于显示重叠部位或动脉瘤瘤颈。E正确：动静脉畸形、硬脑膜动静脉瘘的引流静脉、静脉窦通畅性均需完整时相观察，采集时间不足会漏诊。【为什么错】D错误：椎动脉造影同样需正、侧位；侧位对基底动脉、小脑后下动脉及大脑后动脉走行的显示不可替代。", "tr": "“六根血管”指的是需要选择性显影的六支血管，而不是穿刺六次；同时不要遗漏颈外动脉——脑膜瘤供血、鼻出血与硬脑膜动静脉瘘的评估都依赖它。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-0122", "t": "案例分析题", "s": "患者女性，54岁，突发剧烈头痛伴呕吐、颈项强直，CT示广泛蛛网膜下腔出血。急诊行全脑血管造影，常规正、侧位见右侧颈内动脉后交通段一约6mm囊状突起，但瘤颈与载瘤动脉及后交通动脉相互重叠，无法判断瘤颈宽度及与分支的关系，介入医师需据此决定单纯弹簧圈栓塞或支架辅助栓塞。此时最合理的技术方案是", "o": {"A": "直接提高对比剂流率与总量后重复正、侧位造影", "B": "行3D旋转DSA采集并三维重建，在三维图像上寻找瘤颈与载瘤动脉、分支血管分离最清楚的“工作角度”，再据此设定C臂角度行二维造影与治疗", "C": "改行IV-DSA以避免动脉内操作的风险", "D": "采用能量减影去除颅骨后重复正位造影", "E": "将帧率提高至30帧/s后重复常规正、侧位造影"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-022", "kp": "颅内动脉瘤3D旋转造影与工作角度", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】B正确：常规二维造影的核心局限是投影重叠。3D旋转DSA通过一次旋转采集重建三维血管模型，可在任意视角观察瘤体形态、测量瘤颈宽度与瘤体/瘤颈比，并自动输出使瘤颈充分展开、与载瘤动脉分离的最佳“工作角度”，将该角度参数直接传输至C臂完成后续二维路径图与栓塞操作，是目前动脉瘤介入的标准流程。【为什么错】A错误：重叠是几何投影问题，增加对比剂无法解决，反而增加剂量与肾负荷。C错误：IV-DSA分辨率低、血管重叠更重，早已不用于颅内动脉瘤评估。D错误：能量减影只能去骨，不能解决血管间相互重叠。E错误：提高帧率只改善时间分辨率，对空间重叠无帮助，且明显增加辐射剂量。", "tr": "遇到“结构重叠、无法判断空间关系”的题干，答案方向一定是改变几何投影或三维成像，而不是调对比剂、帧率或减影方式。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0123", "t": "单选题", "s": "颈动脉DSA测得右侧颈内动脉起始部狭窄最窄处残余管腔直径1.5mm，狭窄远端管径恢复正常处直径5.0mm，颈动脉球部估计原始直径10.0mm。按NASCET法计算的狭窄率为", "o": {"A": "50%", "B": "70%", "C": "85%", "D": "15%", "E": "30%"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-023", "kp": "颈动脉狭窄NASCET测量", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】B正确：NASCET法以狭窄远端管径恢复正常处的颈内动脉直径为参照，狭窄率＝(1－最窄处残余管腔直径÷狭窄远端正常颈内动脉直径)×100%＝(1－1.5÷5.0)×100%＝70%。【为什么错】A错误：50%对应残余管腔2.5mm。C错误：85%是以颈动脉球部原始直径10.0mm为分母的ECST法结果，(1－1.5÷10.0)×100%＝85%，属于换错了参照标准。D错误：15%为1.5÷10.0，直接把残余管腔与球部直径相比却未取补数。E错误：30%为残余管腔占远端正常管径的比例（1.5÷5.0），是漏减了“1－”这一步。", "tr": "同一病灶按ECST法算出的狭窄率明显高于NASCET法（本例85%对70%）。报告中必须注明所用标准，否则会直接影响是否达到手术或支架治疗阈值的判断。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0124", "t": "单选题", "s": "主动脉弓造影用于显示弓上三大分支开口，常规采用的导管位置与投照体位是", "o": {"A": "猪尾导管置于升主动脉，取左前斜位约30°~45°", "B": "猪尾导管置于降主动脉，取标准正位", "C": "端孔导管置于左心室，取右前斜位30°", "D": "Cobra导管置于头臂干，取标准侧位", "E": "猪尾导管置于主动脉弓顶部，取右前斜位60°"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-024", "kp": "主动脉弓造影体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】A正确：猪尾导管置于升主动脉、头臂干开口近端，用高压注射器注射；左前斜位30°~45°可将主动脉弓展开成“弓”形，使头臂干、左颈总动脉、左锁骨下动脉的开口分离而不重叠，是评价弓型与开口病变的标准体位。【为什么错】B错误：导管位于降主动脉时对比剂无法充分逆流充盈弓上分支；正位时弓部前后重叠。C错误：左心室与右前斜位是左室造影的设置，不适用于弓上分支评价。D错误：Cobra导管为内脏动脉超选导管，且置于头臂干内只能显示单一分支；侧位无法展开三大分支。E错误：右前斜位使弓部呈重叠状，分支开口相互掩盖。", "tr": "记忆要点：“主动脉弓看分支用左前斜、左室造影用右前斜”。另外弓造影必须用多侧孔猪尾导管配合高流率注射，端孔导管禁用于高流率。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0125", "t": "案例分析题", "s": "患者男性，58岁，支气管扩张病史10余年，近1天反复咯血约500ml，内科止血治疗效果不佳，拟行支气管动脉造影及栓塞术。术中造影见右侧支气管动脉增粗迂曲、末梢紊乱并见对比剂外溢。关于本例的技术要点，下列错误的是", "o": {"A": "支气管动脉多起自T5~T6水平胸主动脉前侧壁，右侧常与肋间动脉共干形成肋间-支气管动脉干", "B": "造影中若见与靶血管相连的根髓动脉（呈“发夹”样）显影，应将微导管超选至更远端避开该分支后再行栓塞，以免造成脊髓缺血", "C": "栓塞材料多选用直径300~500μm以上的聚乙烯醇（PVA）颗粒或明胶海绵颗粒", "D": "为提高栓塞彻底性，应首选无水乙醇等液体栓塞剂或直径小于100μm的微粒行末梢栓塞", "E": "栓塞后应重复造影确认病理血管消失，并观察有无对比剂反流所致的异位栓塞"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-025", "kp": "支气管动脉造影与咯血栓塞", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】D错误故为本题答案：过小的微粒（一般认为小于300μm）与液体栓塞剂可穿过支气管动脉与肺动脉、脊髓动脉之间的细小吻合，造成支气管壁坏死、支气管食管瘘与脊髓缺血性截瘫等严重并发症，因此支气管动脉栓塞禁用无水乙醇等液体栓塞剂与过小微粒。【为什么错】A正确：这是支气管动脉的经典解剖起源与共干形式。B正确：根髓动脉（Adamkiewicz动脉）误栓是支气管动脉栓塞最严重的并发症，超选微导管避开是关键防范措施。C正确：300~500μm级别的PVA或明胶海绵颗粒可有效栓塞病理血管床，同时不会穿过危险吻合。E正确：术后即刻造影复查是评估疗效与安全性的必要步骤。", "tr": "“栓塞越彻底越好”是常见错误思路。支气管动脉栓塞的核心矛盾是疗效与脊髓、支气管壁安全之间的平衡，颗粒过小与液体栓塞剂是明确的雷区。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0126", "t": "单选题", "s": "关于胸部DSA检查技术，下列叙述错误的是", "o": {"A": "咯血患者除支气管动脉外，还应注意肋间动脉、胸廓内动脉、膈下动脉、锁骨下动脉分支等非支气管性体循环侧支供血", "B": "支气管动脉造影宜采用手推或低流率注射，对比剂用量小，避免高压注射造成血管与脊髓损伤", "C": "胸主动脉造影常用猪尾导管，取左前斜位以展开主动脉全程", "D": "肺动脉造影需将导管经右心系统送入肺动脉，操作中应警惕心律失常等并发症", "E": "支气管动脉血管细小，应将帧率设置在30帧/s以上以免遗漏细节"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-026", "kp": "胸部DSA检查技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】E错误故为本题答案：支气管动脉血流量小、显影过程相对缓慢，常规2~3帧/s即可完整记录，30帧/s以上属于冠状动脉级别的帧率要求，对本检查无诊断价值，只会增加辐射剂量与数据量。【为什么错】A正确：约相当一部分咯血病例存在非支气管性体循环侧支供血，遗漏是栓塞后复发的重要原因。B正确：支气管动脉细小，高流率注射可致血管夹层、破裂或对比剂经危险吻合进入脊髓动脉。C正确：左前斜位可展开胸主动脉的弓部与降部，避免与脊柱重叠。D正确：导管经右房、右室时机械刺激易诱发室性早搏与室性心动过速，需心电监护并备除颤设备。", "tr": "细小血管≠需要高帧率。帧率取决于血流速度与运动幅度，与血管粗细无必然关系；细小血管更需要的是合适的放大倍数、小焦点与低流率注射。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0127", "t": "多选题", "s": "关于左冠状动脉造影常用投照体位组合及其显示重点，下列正确的有", "o": {"A": "左前斜45°＋足位25°（俗称“蜘蛛位”）主要显示左主干远端及前降支、回旋支开口与分叉", "B": "右前斜30°＋足位25°主要显示回旋支主干与钝缘支，同时可观察前降支近段", "C": "右前斜30°＋头位25°主要展开前降支中远段与对角支", "D": "左前斜45°＋头位25°的作用是显示左主干开口，此体位下前降支与间隔支完全重叠而无法分辨", "E": "左冠造影常规选用Judkins左冠导管（如JL3.5~4.0），经桡动脉时也可选用左右共用型导管"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-027", "kp": "左冠状动脉造影投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】A正确：左前斜加足位使左主干分叉呈“蜘蛛”状展开，是评价左主干末端与双支开口病变的关键体位。B正确：右前斜加足位是显示回旋支及钝缘支的经典体位。C正确：右前斜加头位使前降支沿长轴展开，便于观察中远段与对角支分支。E正确：Judkins左冠导管为股动脉入路的标准选择，桡动脉入路可用共用型导管减少更换。【为什么错】D错误：左前斜＋头位的作用恰恰是把前降支的间隔支（指向下方）与对角支（指向上方）分开，用于观察前降支中远段；显示左主干开口更常用正位或轻度右前斜＋头位，而非“完全重叠无法分辨”。", "tr": "记忆规律：头位（CRA）展开前降支中远段与远端分叉，足位（CAU）展开左主干末端、回旋支与近段；把头/足位的作用互换是本考点最常见的失分点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-0128", "t": "单选题", "s": "右冠状动脉造影中，能使右冠状动脉整体呈“C”形展开、主要用于观察其中段与锐缘支的体位是", "o": {"A": "左前斜45°", "B": "右前斜30°", "C": "正位＋足位25°", "D": "标准侧位", "E": "右前斜30°＋足位25°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-028", "kp": "右冠状动脉造影投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】A正确：左前斜45°是右冠造影的首选体位，右冠自开口沿房室沟走行呈典型“C”形展开，可完整观察开口、近段、中段与锐缘支，也便于判断导管是否与开口同轴。【为什么错】B错误：右前斜30°时右冠呈“L”形，主要用于观察中段与后降支走行，并非“C”形。C错误：正位加足位不是右冠常规体位。D错误：侧位主要用于观察右冠开口与近段起始角度，属补充体位。E错误：右前斜加足位为左冠回旋支的常用体位。另需记住左前斜45°＋头位25°呈“倒U”形，用于展开后降支与左室后支的分叉部。", "tr": "把右冠形态与体位对应起来记忆最有效：左前斜“C”形、右前斜“L”形、左前斜＋头位“倒U”形显示远段分叉。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-0129", "t": "案例分析题", "s": "患者男性，60岁，因陈旧性心肌梗死后心功能不全，在完成冠状动脉造影后需评价左心室整体与节段收缩功能，并判断有无二尖瓣反流。介入医师要求技师配合完成左心室造影。关于本次造影的器械、参数与体位设置，下列正确的是", "o": {"A": "选用端孔导管置于左室流出道，手推对比剂约20ml即可", "B": "选用猪尾导管头端置于左心室中部，用高压注射器注射对比剂约30~40ml、流率约10~15ml/s，帧率25~30帧/s，常规取右前斜30°，必要时加摄左前斜60°", "C": "取左前斜45°＋足位25°作为唯一体位即可满足室壁运动与二尖瓣反流评价", "D": "为降低辐射剂量，帧率应设置为3帧/s", "E": "注射前无需排气与试注射，可直接启动高压注射器"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-029", "kp": "左心室造影技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】B正确：猪尾导管多侧孔可分散高流率注射的冲击力、避免心内膜损伤与室性心律失常；右前斜30°用于观察前壁、心尖、下壁运动及二尖瓣反流入左房的情况，左前斜60°补充观察室间隔与侧壁；心脏搏动快，帧率需25~30帧/s。【为什么错】A错误：端孔导管在高流率下会因反冲刺入心肌造成损伤与心律失常，且手推20ml无法使左室充分显影。C错误：左前斜加足位为左冠造影体位，不用于左室造影。D错误：3帧/s无法冻结心动周期，无法评价室壁运动。E错误：高压注射器必须排空气泡并确认导管位置、压力上限，否则可致气栓与心肌染色。", "tr": "“猪尾导管＋右前斜30°”是左室造影的标准搭配。注意与冠状动脉造影的Judkins导管、与主动脉弓造影的左前斜位区分开。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0130", "t": "单选题", "s": "关于冠状动脉造影的器械选择与并发症，下列叙述错误的是", "o": {"A": "经股动脉入路常用Judkins左（JL4.0）与Judkins右（JR4.0）导管分别插入左、右冠状动脉", "B": "经桡动脉入路可选用左右冠共用型导管以减少导管更换次数与操作时间", "C": "导管深插或与冠状动脉开口不同轴，可造成冠状动脉痉挛、压力嵌顿甚至开口夹层", "D": "导管内血栓形成或注射时混入气泡，可造成冠状动脉栓塞，故须严格排气并持续冲洗", "E": "造影过程中出现一过性心室颤动，只可能由导管机械压迫所致，与对比剂性质及注射量完全无关"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-030", "kp": "冠状动脉造影器械与并发症", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】E错误故为本题答案：造影中室颤的原因是多方面的，除导管嵌顿、深插导致心肌缺血外，对比剂在冠状动脉内滞留时间过长、注射量过大、导管压力嵌顿状态下注药、高渗离子型对比剂对心肌电生理的影响等均可诱发；因此除规范操作外，还应选用非离子型对比剂、控制单次注射量并避免嵌顿位注射。【为什么错】A正确：JL4.0与JR4.0是最常用的成人冠脉造影导管。B正确：共用型导管是桡动脉入路的常规优化。C正确：这是导管操作相关的经典并发症链条。D正确：气泡与血栓是冠脉栓塞的两大来源，排气与持续冲洗是基本规范。", "tr": "选项中“只可能……完全无关”的双重绝对化表述几乎必错。并发症类考点通常是多因素叠加，单一归因的选项应优先排除。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0131", "t": "多选题", "s": "关于原发性肝癌经导管动脉化疗栓塞术（TACE）的造影与操作技术要点，下列正确的有", "o": {"A": "术中宜先行腹腔干与肠系膜上动脉造影，了解肝动脉解剖、有无变异并观察门静脉期血流", "B": "部分患者存在肝右动脉起自肠系膜上动脉、肝左动脉起自胃左动脉等变异，须逐一探查以免遗漏肿瘤供血", "C": "应尽量将导管或微导管超选至肿瘤供血动脉后再注入碘化油-化疗药乳剂，以减少正常肝组织损伤", "D": "门静脉主干完全被癌栓阻塞且侧支循环尚未建立者，行肝固有动脉主干大剂量栓塞是安全的", "E": "操作中须注意胃十二指肠动脉、胆囊动脉、右膈下动脉等的反流，防止异位栓塞"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-031", "kp": "肝动脉化疗栓塞TACE技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】A正确：肠系膜上动脉造影延迟至门静脉期可间接判断门静脉通畅程度与有无癌栓，是决定栓塞范围与安全性的前提。B正确：肝动脉解剖变异常见，替代肝右动脉多起自肠系膜上动脉、替代肝左动脉多起自胃左动脉，漏栓变异供血是术后复发的重要原因。C正确：超选择栓塞可提高肿瘤内碘油沉积、减轻肝功能损害，是提高疗效与安全性的关键。E正确：反流至胃十二指肠动脉可致胃十二指肠溃疡，反流至胆囊动脉可致缺血性胆囊炎。【为什么错】D错误：门静脉主干完全阻塞且无侧支代偿时，肝脏几乎完全依赖肝动脉供血，此时行主干大剂量栓塞会导致广泛肝细胞坏死与肝功能衰竭，属禁忌或需高度超选的极慎重情形。", "tr": "肝脏为肝动脉与门静脉双重供血，TACE的安全边界正建立在门静脉通畅的前提上；“门静脉主干癌栓”是必须警觉的关键词。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-0132", "t": "单选题", "s": "关于脾动脉造影技术，下列叙述错误的是", "o": {"A": "脾动脉起自腹腔干，行程迂曲，常选用Cobra、RH或Simmons类导管进行选择性插管", "B": "通过迂曲段时宜用亲水涂层超滑导丝引导，避免暴力推送导致血管痉挛或夹层", "C": "脾动脉造影可显示脾实质染色，用于外伤性脾破裂出血的诊断与栓塞治疗", "D": "造影时应辨认胰背动脉、胃网膜左动脉、胃短动脉等分支，栓塞时注意避免误栓", "E": "脾动脉造影须使用高压注射器以20ml/s以上的流率注射，方能使脾实质充分显影"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-032", "kp": "脾动脉造影技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】E错误故为本题答案：脾动脉属中等口径内脏动脉，选择性造影一般采用4~6ml/s、总量15~25ml左右的流率与剂量即可获得满意的实质期染色；20ml/s以上属于主动脉级别的流率，会造成导管弹出、血管内膜损伤甚至脾包膜下血肿。【为什么错】A正确：脾动脉呈蛇行迂曲，需借助带弯度的导管超选。B正确：超滑导丝可降低通过迂曲段时的血管损伤。C正确：外伤性脾出血的介入栓塞是保脾治疗的重要手段，造影可显示对比剂外溢或假性动脉瘤。D正确：这些分支在栓塞时误栓可导致胃壁缺血、胰腺炎等并发症。", "tr": "内脏动脉造影的流率、总量必须与血管口径匹配，牢记“大血管高流率、分支血管低流率”，切忌套用主动脉参数。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0133", "t": "多选题", "s": "关于消化道出血的DSA检查，下列正确的有", "o": {"A": "活动性出血的直接征象是对比剂自血管溢出并滞留、聚集于肠腔内", "B": "一般认为出血速度达到0.5ml/min以上时，DSA才可能显示对比剂外溢", "C": "检查宜在活动性出血期进行，出血间歇期检查阳性率明显下降", "D": "首次探查的责任血管造影阴性时可直接结束检查，无需再探查其他供血动脉", "E": "血管畸形、假性动脉瘤、异常肿瘤染色等间接征象同样具有定位价值"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-033", "kp": "消化道出血血管造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】A正确：对比剂外溢后不随血流廓清而滞留于肠腔，是判断活动性出血的金标准征象。B正确：0.5ml/min是DSA显示对比剂外溢的公认阈值，低于此速度多为阴性。C正确：出血呈间歇性，把握出血活跃时机是提高阳性率的关键，必要时可结合核素或CTA先行定位。E正确：即使未见外溢，血管畸形、动静脉畸形、假性动脉瘤及肿瘤染色亦可提示出血部位并指导栓塞。【为什么错】D错误：消化道出血需按解剖分区系统探查，通常依次行肠系膜上动脉、腹腔干、肠系膜下动脉造影，必要时加做超选择造影或延长采集至静脉期，单支阴性即终止会造成漏诊。", "tr": "考点常设的陷阱是把“阴性”等同于“无出血”。DSA阴性只能说明检查时出血速度低于阈值或不在所探查血管供血区，不能排除出血。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-0134", "t": "单选题", "s": "关于子宫肌瘤子宫动脉栓塞术（UAE）的技术要点，下列叙述错误的是", "o": {"A": "子宫动脉多起自髂内动脉前干，常经一侧股动脉入路，用Cobra或子宫动脉专用导管跨越髂动脉分叉超选对侧", "B": "髂内动脉造影多取同侧前斜位，以展开前、后干分支避免相互重叠", "C": "常用聚乙烯醇（PVA）颗粒或明胶海绵颗粒作为栓塞材料", "D": "栓塞后综合征表现为下腹痛、低热、恶心呕吐等，多为自限性", "E": "卵巢动脉与子宫动脉之间不存在任何交通支，故UAE不会影响卵巢功能"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-034", "kp": "子宫动脉栓塞技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (5)盆腔", "ex": "【为什么对】E错误故为本题答案：子宫动脉与卵巢动脉之间存在输卵管支等交通支，栓塞颗粒可经此进入卵巢血管床，导致卵巢功能受损甚至闭经，这是育龄期患者术前必须充分告知的风险；术中应超选至子宫动脉上行支、控制栓塞终点、避免过度栓塞与反流。【为什么错】A正确：这是UAE的标准入路与器械选择。B正确：同侧前斜位可展开髂内动脉前后干，便于辨认子宫动脉开口。C正确：PVA与明胶海绵颗粒是常用栓塞剂。D正确：栓塞后综合征是缺血坏死引起的常见反应，对症处理即可缓解。", "tr": "凡出现“不存在任何交通支”“完全不影响”这类否定一切侧支的表述，几乎都是错误项——人体血管网普遍存在潜在吻合，介入栓塞的风险正源于此。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-0135", "t": "单选题", "s": "拟行双下肢动脉步进（bolus chasing）DSA，下列做法错误的是", "o": {"A": "导管头端置于腹主动脉分叉上方，一次注射对比剂后由床面或C臂自动步进跟踪对比剂前行分段采集", "B": "相邻采集段之间应保留一定重叠范围，便于后续图像拼接", "C": "小腿及足部血流到达延迟，可适当延长采集时间或对远段单独补充造影", "D": "检查前应固定双足、嘱患者制动，防止运动造成减影配准不良", "E": "为缩短检查时间，步进速度应预先设定为固定值，采集过程中不必参考对比剂实际到达情况"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-035", "kp": "下肢动脉步进DSA", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】E错误故为本题答案：下肢动脉硬化闭塞患者两侧血流速度常明显不对称，闭塞侧经侧支循环供血，对比剂到达远端显著延迟；若步进速度固定而不跟随对比剂前锋调整，会出现“跑在对比剂前面”导致远段血管未显影而漏诊，现代设备均支持术者实时手动控制步进速度或采用智能跟踪。【为什么错】A正确：这是步进DSA的标准设置，一次注药完成腹主动脉分叉至足部的全程显示。B正确：重叠区是分段图像拼接与判断连续性的基础。C正确：远端延迟显影时应延长采集或对膝下、足部单独补充造影。D正确：步进采集时间长，运动是配准失败的主要原因，充分固定与制动很重要。", "tr": "步进DSA的核心难点是“追上但不超过”对比剂前锋，尤其在双侧血流不对称时；这类题的错误项常以“固定参数、缩短时间”为诱饵。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1001", "t": "单选题", "s": "DSA的中文名称是", "o": {"A": "数字减影血管造影", "B": "数字X线摄影", "C": "计算机体层成像", "D": "磁共振血管成像", "E": "数字断层融合成像"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-001", "kp": "DSA基本概念", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】DSA即Digital Subtraction Angiography，中文全称为数字减影血管造影，A正确。\n【为什么错】B为DR（数字X线摄影）；C为CT；D为MRA；E为数字体层融合成像，均与DSA含义不符。", "tr": "DSA＝数字减影血管造影，注意与CTA、MRA等无创血管成像技术相区别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1002", "t": "单选题", "s": "DSA减影中，mask像（蒙片）是指", "o": {"A": "注入对比剂前采集的原始图像", "B": "注入对比剂后血管充盈期的图像", "C": "减影后只含血管的图像", "D": "处理后放大的数字矩阵图像", "E": "经窗宽窗位调整后的图像"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-002", "kp": "mask像原理", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】mask像即蒙片，是注入对比剂前采集的原始图像，作为减影的基准模板，与含对比剂图像相减消除背景，A正确。\n【为什么错】B为含对比剂图像，与mask像相减得减影像；C为减影结果像；D为数字图像转换产物；E为显示处理手段，均非mask像定义。", "tr": "mask像在注药前采集；减影相＝mask像－含对比剂像，先后方向勿搞反。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1003", "t": "单选题", "s": "DSA减影处理中对图像先行对数变换的主要目的是", "o": {"A": "提高图像空间分辨率", "B": "使像素灰度与人体衰减系数成线性关系，便于像素相减", "C": "扩大图像灰阶范围", "D": "增强血管边缘轮廓", "E": "直接减少图像噪声"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-003", "kp": "DSA减影数学原理", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】X线穿过人体按指数规律衰减，先经对数变换使像素灰度与组织衰减系数呈线性关系，相减后骨骼、软组织成分被消除，仅保留含碘血管信号，B正确。\n【为什么错】A为空间分辨率概念；C为窗宽窗位显示处理；D为图像锐化滤波；E为噪声抑制处理，均非对数变换的直接目的。", "tr": "减影前必先对数变换，否则指数衰减下相减不能真正消除重叠组织。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1004", "t": "单选题", "s": "时间减影中应用“再蒙片”（remasking）的主要目的是", "o": {"A": "提高对比剂浓度", "B": "重新选择最佳mask像以减少运动伪影", "C": "提高采集帧率", "D": "降低患者辐射剂量", "E": "缩短造影时间"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-004", "kp": "时间减影与再蒙片", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】患者运动（吞咽、屏气不佳、蠕动等）可使蒙片与含对比剂图像错位，在减影序列中重新选择一帧更接近的帧作为新mask像（再蒙片），可有效纠正配准误差，B正确。\n【为什么错】A为注射参数；C为采集参数；D为剂量管理；E为操作流程，均与再蒙片的作用无关。", "tr": "再蒙片是图像后处理手段，并非重新注药或改变采集参数。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1005", "t": "单选题", "s": "减影后DSA图像中最终显示为高密度的结构是", "o": {"A": "骨骼", "B": "软组织", "C": "含对比剂的血管腔", "D": "肺内空气", "E": "肌肉组织"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-005", "kp": "减影图像显示内容", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】减影后骨骼、软组织被相减消除，仅保留注入对比剂后血管腔的影像，故高密度者为含碘对比剂的血管腔，C正确。\n【为什么错】A、B、E在减影时被消除；D空气影同样在相减后消失。", "tr": "DSA只显示含碘对比剂的血管腔，不显示血管壁及周围组织。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1006", "t": "单选题", "s": "静脉DSA（IV-DSA）中心静脉法导管头端应置于", "o": {"A": "肘前静脉", "B": "腋静脉", "C": "上腔静脉或右心房", "D": "下腔静脉远心端", "E": "髂外静脉"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-006", "kp": "静脉DSA中心静脉法", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】中心静脉法经肘静脉或股静脉穿刺插管，将导管头端置于上腔静脉或右心房近心端，注射后对比剂在短时间内形成较集中的团注，C正确。\n【为什么错】A为外周静脉法的注射部位；B为静脉走行途经；D、E位置过远，团注效果差、对比剂稀释明显。", "tr": "中心法导管头端在上腔静脉/右心房，外周法则直接在肘前静脉注射，二者有别。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1007", "t": "单选题", "s": "与动脉DSA相比，静脉DSA的主要缺点是", "o": {"A": "操作复杂、创伤大", "B": "对比剂被血液稀释、细小动脉显示差", "C": "不能显示全身大血管", "D": "辐射剂量显著增高", "E": "完全不能用于介入治疗引导"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-007", "kp": "静脉DSA特点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】静脉注射后对比剂经肺循环被血液大量稀释，浓度显著降低，细小动脉及病变显示不清，B正确。\n【为什么错】A静脉法不需动脉插管，操作更简便、创伤更小；C静脉法可显示主动脉等大血管；D剂量与方式无必然增高关系；E介入治疗中静脉法亦可作引导，只是多选动脉法。", "tr": "IV-DSA优势是简便创伤小，代价是稀释重、细小血管显示差。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1008", "t": "单选题", "s": "肾功能不全患者行血管造影时，应优先选择的成像方式是", "o": {"A": "静脉DSA", "B": "动脉DSA", "C": "混合DSA", "D": "能量减影DSA", "E": "步进式DSA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-008", "kp": "动脉DSA用量特点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】动脉DSA对比剂用量少、浓度低，可最大限度减轻肾脏负担，适合肾功能不全患者，B正确。\n【为什么错】A静脉DSA用量大、肾负担重；C混合DSA总用量更大；D、E为减影或采集方式，不解决对比剂用量问题。", "tr": "动脉DSA省药、静脉DSA费药，方向与直觉相反，需重点记忆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1009", "t": "单选题", "s": "DSA成像方式中的“混合DSA”是指", "o": {"A": "时间减影与能量减影相结合的减影方式", "B": "静脉DSA与动脉DSA相结合的造影方式", "C": "X线与MR相结合的成像方式", "D": "常规透视与减影相结合的成像方式", "E": "正位与侧位相结合的采集方式"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-009", "kp": "混合DSA成像方式", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】在DSA成像方式分类中，混合DSA指静脉法与动脉法相结合的造影方式，根据病变需要先后或同时应用IV-DSA与IA-DSA，B正确。\n【为什么错】A为混合减影（属减影方式分类）；C为多模态成像；D为透视技术；E为体位组合，均非成像方式分类中的混合DSA。", "tr": "“混合DSA”是成像方式（动静脉结合），“混合减影”是减影方式（时间＋能量），二者最易混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1010", "t": "单选题", "s": "临床DSA检查中应用最广泛的减影方式是", "o": {"A": "能量减影", "B": "时间减影", "C": "混合减影", "D": "光学减影", "E": "磁化转移减影"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-010", "kp": "时间减影", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】时间减影设备要求低、操作简便、效果可靠，是临床应用最广泛的减影方式，B正确。\n【为什么错】A能量减影需特殊设备、易受运动影响；C混合减影信噪比低；D光学减影为早期技术已被淘汰；E不存在此减影方式。", "tr": "时间减影最常用；能量减影、混合减影因固有缺陷临床少用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1011", "t": "单选题", "s": "能量减影利用碘的K吸收边进行成像，碘的K吸收边能量约为", "o": {"A": "13.3keV", "B": "23.3keV", "C": "33.2keV", "D": "53.2keV", "E": "73.2keV"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-011", "kp": "能量减影原理", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】碘的K吸收边为33.2keV，选用略低于和略高于该能量的两种X线成像后相减，可消除软组织影，C正确。\n【为什么错】A、B、D、E数值均不符合碘K吸收边的物理事实。", "tr": "33.2keV为碘K吸收边经典数值，属高频记忆考点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1012", "t": "单选题", "s": "关于能量减影的叙述，错误的是", "o": {"A": "利用碘的K吸收边原理", "B": "需要两种不同能量的X线成像", "C": "能同时消除骨骼影和软组织影", "D": "对软组织的运动较为敏感", "E": "对设备性能要求较高"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-012", "kp": "能量减影局限", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】能量减影仅能消除软组织影，骨骼影仍然保留，故C“能同时消除骨骼和软组织”说法错误，本题选C。\n【为什么错】A为能量减影物理基础；B为成像条件；D、E为其固有局限，均正确。", "tr": "能量减影去软组织留骨骼；同时消除骨骼软组织是时间减影的特点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1013", "t": "单选题", "s": "混合减影（hybrid subtraction）的减影顺序是", "o": {"A": "先时间减影再能量减影", "B": "先能量减影再时间减影", "C": "两种不同帧率图像相减", "D": "静脉图像与动脉图像相减", "E": "正位图像与侧位图像相减"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-013", "kp": "混合减影", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】混合减影先将两种能量图像作能量减影（消除软组织），再对能量减影像作时间减影（消除骨骼及运动伪影），B正确。\n【为什么错】A顺序颠倒；C为帧率选择；D为成像方式；E为体位组合，均非混合减影定义。", "tr": "混合减影＝能量减影在前、时间减影在后，顺序勿颠倒。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1014", "t": "单选题", "s": "DSA的“路标”（road mapping）技术主要用于", "o": {"A": "诊断细小动脉瘤", "B": "介入操作中实时引导导丝、导管超选择性插管", "C": "评价血管狭窄程度", "D": "提高图像空间分辨率", "E": "减少对比剂用量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-014", "kp": "路标技术", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】路标技术将注药后含对比剂的血管影像作为路径图叠加于实时透视上，导管导丝移动时与血管的关系清晰可见，便于超选择性插管，B正确。\n【为什么错】A、C为诊断用途；D为图像质量指标；E为剂量问题，均非路标技术的直接作用。", "tr": "路标技术＝介入引导专用，属时间减影的实时应用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1015", "t": "单选题", "s": "DSA检查的绝对禁忌证是", "o": {"A": "轻度高血压", "B": "糖尿病", "C": "碘对比剂过敏", "D": "冠状动脉粥样硬化", "E": "良性前列腺增生"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-015", "kp": "DSA禁忌证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】碘对比剂过敏可诱发严重过敏性休克甚至死亡，是DSA的绝对禁忌证，C正确。\n【为什么错】A高血压控制后可检查；B糖尿病非禁忌；D为检查适应证；E与DSA无直接关系。", "tr": "碘过敏为绝对禁忌；高血压、糖尿病属可控因素或相对禁忌。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1016", "t": "单选题", "s": "下列属于DSA检查适应证的是", "o": {"A": "常规健康体检", "B": "疑蛛网膜下腔出血查颅内动脉瘤", "C": "孕妇常规筛查", "D": "单纯发热查因", "E": "急性感染期伴高热"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-016", "kp": "DSA适应证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】蛛网膜下腔出血多由颅内动脉瘤破裂所致，DSA是脑血管病变定位与确诊的金标准，B正确。\n【为什么错】A、C、D均无血管造影指征；E急性感染高热常为检查禁忌或相对禁忌。", "tr": "DSA为有创检查，仅用于明确适应证，不作常规筛查手段。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1017", "t": "单选题", "s": "DSA术后穿刺部位最常见的并发症是", "o": {"A": "出血和血肿", "B": "假性动脉瘤", "C": "动静脉瘘", "D": "血管内膜夹层", "E": "血栓栓塞"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-017", "kp": "穿刺部位并发症", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】穿刺点出血、血肿是股动脉穿刺后最常见的并发症，与压迫时间不足、过早活动、凝血功能异常有关，A正确。\n【为什么错】B、C、D、E均为较少见或相对少见并发症，需超声或血管造影进一步证实。", "tr": "血肿最常见；假性动脉瘤、动静脉瘘为少见而重要的并发症。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1018", "t": "单选题", "s": "为预防对比剂肾病（CIN），最有效、最基本的措施是", "o": {"A": "术前大量使用利尿剂", "B": "充分水化", "C": "术前常规服用抗生素", "D": "适当增加对比剂用量", "E": "改用高渗离子型对比剂"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-018", "kp": "对比剂肾病预防", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】水化可增加肾血流、稀释对比剂浓度，是预防CIN最有效且最基本的措施，B正确。\n【为什么错】A利尿剂可致脱水、加重肾损害；C抗生素无预防价值；D增加用量反而加重肾损伤；E高渗离子型对比剂肾毒性更大。", "tr": "水化防CIN，利尿反而有害；等渗非离子型对比剂优于高渗离子型。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1019", "t": "单选题", "s": "DSA检查前患者的禁食要求一般为", "o": {"A": "禁食1小时", "B": "禁食4~6小时", "C": "禁食12小时", "D": "禁食24小时", "E": "不需禁食"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-019", "kp": "术前禁食", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】为减少术中恶心、呕吐误吸及便于处理过敏等不良反应，血管造影术前常规禁食4~6小时，B正确。\n【为什么错】A禁食过短胃未排空；C、D禁食过长易致低血糖、脱水；E不符合术前准备要求。", "tr": "术前禁食4~6小时，禁食不禁饮的原则需结合麻醉方式掌握。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1020", "t": "单选题", "s": "DSA术前进行碘过敏试验的目的是", "o": {"A": "了解肾功能", "B": "检测患者对碘对比剂是否过敏", "C": "判断凝血功能", "D": "评估血管弹性", "E": "测定基础血压"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-020", "kp": "碘过敏试验", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】碘过敏试验通过注入少量对比剂观察机体反应，用于初筛碘对比剂过敏者，B正确。\n【为什么错】A肾功能查血肌酐、尿素氮；C凝血功能查凝血四项；D、E为常规临床检查，均与过敏试验无关。", "tr": "过敏试验只能初筛，仍存在假阴性，术中必须备好急救药品与设备。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1021", "t": "单选题", "s": "DSA术前评估穿刺出血风险必须检查的项目是", "o": {"A": "血常规", "B": "凝血功能", "C": "肝功能", "D": "心肌酶谱", "E": "血型鉴定"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-021", "kp": "术前化验评估", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】凝血功能障碍可致穿刺后出血难止，术前必须评估凝血酶原时间、活化部分凝血活酶时间等指标，B正确。\n【为什么错】A血常规虽常规查但非出血风险评估核心；C肝功能与出血风险关系间接；D用于心肌梗死诊断；E为备血常规项目。", "tr": "凝血功能＋肾功能是DSA术前两大关键化验项目。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1022", "t": "单选题", "s": "Seldinger穿刺插管技术最常用的穿刺血管是", "o": {"A": "桡动脉", "B": "股动脉", "C": "颈总动脉", "D": "锁骨下动脉", "E": "腋动脉"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-022", "kp": "Seldinger穿刺部位", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】股动脉粗大、位置表浅、便于穿刺且穿刺点有耻骨支撑利于压迫止血，是Seldinger技术最常用的穿刺入路，B正确。\n【为什么错】A桡动脉常用于冠脉介入（经桡入路）；C颈动脉穿刺风险高；D、E位置深、并发症多，均非常规首选。", "tr": "全身血管造影默认股动脉入路；经桡动脉多用于冠脉介入治疗。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1023", "t": "单选题", "s": "股动脉穿刺点通常选在", "o": {"A": "腹股沟韧带上方", "B": "腹股沟韧带中点下方1~2cm股动脉搏动最明显处", "C": "髂前上棘处", "D": "腘窝处", "E": "大腿中段外侧"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-023", "kp": "股动脉穿刺点定位", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】腹股沟韧带中点下方1~2cm处股动脉搏动最明显，且下方有耻骨支撑便于拔管后压迫止血，为理想穿刺点，B正确。\n【为什么错】A韧带上方为髂外动脉、无骨性支撑且腹股沟深部压迫困难；C、D、E位置均不符合股动脉穿刺定位。", "tr": "穿刺点过高易进入腹膜后，过低易伤及股深动脉或出血难止。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1024", "t": "单选题", "s": "Seldinger插管技术的正确操作顺序是", "o": {"A": "穿刺针穿刺→引入导丝→退出穿刺针→沿导丝送导管", "B": "穿刺针穿刺→送入导管→退出穿刺针→沿导管送导丝", "C": "切开皮肤→直视下穿刺→置入导管", "D": "穿刺针穿刺→直接经针腔注射对比剂", "E": "先送导丝→再穿刺→再置管"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-024", "kp": "Seldinger操作步骤", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】Seldinger技术核心为穿刺针见回血后引入导丝，退出穿刺针，再沿导丝送入导管（或导管鞘），A正确。\n【为什么错】B、E顺序错误；C为直视切开法（旧术式，创伤大）；D未完成置管即注射，操作错误。", "tr": "记忆口诀“针—丝—管”，导丝始终在血管腔内引导导管。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1025", "t": "单选题", "s": "股动脉穿刺见穿刺针尾有鲜红色血液搏动性喷出，提示", "o": {"A": "误穿静脉", "B": "穿刺针位于动脉内", "C": "穿刺过浅停留在皮下", "D": "已穿出对侧血管壁", "E": "局部血管痉挛"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-025", "kp": "动脉穿刺成功指征", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】动脉血含氧丰富呈鲜红色、压力高且呈搏动性喷出，是穿刺针进入动脉腔的可靠指征，B正确。\n【为什么错】A静脉血暗红、压力低无搏动；C皮下穿刺无回血；D穿出对侧壁则回血停止；E痉挛表现为送管困难而非回血特征。", "tr": "鲜红搏动性喷血＝动脉；暗红缓慢回流＝静脉，据此调整穿刺方向。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1026", "t": "单选题", "s": "DSA常规采集的图像矩阵一般为", "o": {"A": "256×256", "B": "512×512", "C": "1024×1024", "D": "2048×2048", "E": "4096×4096"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-026", "kp": "图像矩阵", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】DSA常规采用1024×1024矩阵，兼顾空间分辨率与帧率、存储传输要求，C正确。\n【为什么错】A、B分辨率偏低，细小血管显示不佳；D、E数据量过大、帧率受限，非DSA常规选择。", "tr": "DSA常用1024矩阵，CT重建常为512×512，两者勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1027", "t": "单选题", "s": "心脏及冠状动脉DSA采集帧率一般应达到", "o": {"A": "1帧/s", "B": "2帧/s", "C": "4帧/s", "D": "6帧/s", "E": "15~25帧/s以上"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-027", "kp": "采集帧率选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】心脏搏动快、血流速度快，需高帧率连续采集（心腔造影常用25帧/s，冠脉造影12.5~30帧/s）才能完整捕捉血管充盈过程，E正确。\n【为什么错】A~D帧率过低，无法满足心脏动态成像需求。", "tr": "部位血流越快帧率越高：心脏冠脉高帧率，四肢腹部低帧率。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1028", "t": "单选题", "s": "腹部及四肢血管DSA采集帧率一般为", "o": {"A": "1帧/s以下", "B": "2~3帧/s", "C": "12帧/s", "D": "25帧/s", "E": "50帧/s"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-028", "kp": "采集帧率选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】腹部、四肢血流较慢、循环时间长，2~3帧/s即可完整记录动静脉各期，且辐射剂量低，B正确。\n【为什么错】A帧率过低可能漏拍关键时相；C、D、E为心脏/冠脉常用帧率，用于四肢属过度采集。", "tr": "低帧率（2~3帧/s）用于腹四肢，高帧率（12.5帧/s以上）用于心脏冠脉。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1029", "t": "单选题", "s": "DSA采像延迟时间主要取决于", "o": {"A": "穿刺部位", "B": "对比剂从注射部位到达靶血管的循环时间", "C": "患者年龄", "D": "导管型号", "E": "减影方式"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-029", "kp": "采像延迟时间", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】从注射开始到对比剂充盈靶血管需一定时间，按循环时间设定采像延迟，才能保证既有足够蒙片又能完整记录充盈期，B正确。\n【为什么错】A、C、D、E均与延迟时间的设定无直接关系。", "tr": "延迟＝对比剂循环时间；注射部位离靶血管越远，延迟时间越长。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1030", "t": "单选题", "s": "全脑血管造影常规应造影的血管为", "o": {"A": "仅左侧颈内动脉", "B": "主动脉弓、双侧颈总动脉及双侧椎动脉", "C": "仅主动脉弓", "D": "仅双侧椎动脉", "E": "仅右颈总动脉和右椎动脉"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-030", "kp": "全脑血管造影范围", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】全脑血管造影常规先行主动脉弓造影了解弓上血管开口情况，再选择性行双侧颈总动脉、双侧椎动脉造影，即弓上4条主要血管，B正确。\n【为什么错】A、C、D、E均未完整包含上述血管，属不完整造影。", "tr": "全脑血管造影＝主动脉弓造影＋双侧颈总、双侧椎动脉4血管造影。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1031", "t": "单选题", "s": "头颈部DSA检查首选穿刺入路为", "o": {"A": "股动脉", "B": "颈内静脉", "C": "锁骨下动脉", "D": "肘前静脉", "E": "腘动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-031", "kp": "头颈部DSA入路", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】经股动脉Seldinger穿刺置鞘后，导管可经主动脉弓超选至颈总、椎动脉，路径成熟、安全可靠，为首选入路，A正确。\n【为什么错】B为静脉入路，用于静脉性造影；C穿刺风险高；D为静脉注射途径；E为下肢入路不用于脑血管。", "tr": "脑血管造影经股动脉入路长距离超选是常规操作。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1032", "t": "单选题", "s": "选择性颈总动脉造影时，对比剂注射流率一般选择", "o": {"A": "10~12ml/s", "B": "3~5ml/s", "C": "20~25ml/s", "D": "15~20ml/s", "E": "0.5ml/s以下"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-032", "kp": "颈动脉造影参数", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】颈总动脉属中小血管，流率过高易反流入主动脉弓或损伤血管壁，3~5ml/s即可获得满意显影，B正确。\n【为什么错】A、C、D为大血管（如主动脉）高压造影参数；E流率过低显影不清。", "tr": "血管越细流率越低：主动脉（15~20ml/s）＞颈动脉（3~5ml/s）。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1033", "t": "单选题", "s": "疑颅内动脉瘤行DSA时，为确保病变充分显示应强调", "o": {"A": "仅单一正位投照", "B": "多体位投照并酌情行旋转/3D采集", "C": "仅做侧位投照", "D": "降低矩阵以加快采集", "E": "提高注射压力以增强显影"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-033", "kp": "动脉瘤DSA投照技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】动脉瘤常因血管重叠在单一体位显示不清，需多体位投照，必要时行三维旋转采集（3D-DSA）重建，观察瘤颈与载瘤动脉关系，B正确。\n【为什么错】A、C单一体位易漏诊；D降低矩阵反而降低分辨率；E提高压力增加血管损伤与并发症风险。", "tr": "3D-DSA是颅内动脉瘤检查的进阶要求，重点评估瘤颈与载瘤动脉。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1034", "t": "单选题", "s": "历史上被公认的肺栓塞诊断“金标准”为", "o": {"A": "胸部X线平片", "B": "肺通气灌注显像", "C": "肺动脉造影（DSA）", "D": "支气管动脉造影", "E": "心脏彩色超声"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-034", "kp": "肺动脉造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】肺动脉造影可直接显示肺动脉腔内充盈缺损，曾被公认是肺栓塞诊断的金标准，C正确。\n【为什么错】A平片无特异性；B功能显像假阳性率较高；D用于咯血介入；E超声以心内结构为主。", "tr": "目前临床肺栓塞首选CTPA，但教材仍要求掌握“肺动脉造影曾是金标准”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1035", "t": "单选题", "s": "大咯血介入治疗应首选造影并栓塞的动脉是", "o": {"A": "冠状动脉", "B": "支气管动脉", "C": "颈内动脉", "D": "肾动脉", "E": "肠系膜上动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-035", "kp": "支气管动脉造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】咯血多源于支气管动脉破裂，行支气管动脉造影明确出血点后栓塞，是咯血介入治疗的核心技术，B正确。\n【为什么错】A为心脏血管；C为脑部血管；D为肾脏血管；E为肠道血管，均与咯血无关。", "tr": "咯血→支气管动脉；消化道出血→肠系膜动脉或腹腔干。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1036", "t": "单选题", "s": "主动脉造影通常选用的导管是", "o": {"A": "猪尾导管", "B": "Cobra导管", "C": "微导管", "D": "球囊导管", "E": "漂浮导管"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-036", "kp": "主动脉造影导管选择", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】猪尾导管末端卷曲并有多侧孔，高压注药时对比剂均匀喷射且不直接顶伤血管壁，是主动脉、心室造影的标准导管，A正确。\n【为什么错】B为腹腔脏器超选导管；C为超选择性小血管用导管；D为球囊扩张用；E为肺动脉测压用。", "tr": "大血管/心室用猪尾导管，内脏超选用Cobra或弯头导管。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1037", "t": "单选题", "s": "选择性冠状动脉造影在冠心病诊断中的地位是", "o": {"A": "初筛手段", "B": "诊断“金标准”", "C": "替代超声检查", "D": "心功能评估首选", "E": "术后唯一随访手段"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-037", "kp": "冠脉造影诊断地位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】选择性冠脉造影能直观显示冠脉狭窄的部位、程度与范围，是冠心病诊断的金标准，B正确。\n【为什么错】A初筛常用心电图、冠脉CTA；C超声看心腔结构与功能；D功能评估用负荷试验；E随访还需结合临床多种手段。", "tr": "冠脉造影＝解剖诊断金标准；功能评估靠负荷或灌注检查。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1038", "t": "单选题", "s": "观察左冠状动脉主干分叉（前降支与回旋支开口）的最佳投照体位是", "o": {"A": "正位+头位", "B": "蜘蛛位（左前斜+足位）", "C": "右前斜+头位", "D": "左前斜+头位", "E": "单纯正位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-038", "kp": "左冠造影投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】蜘蛛位（LAO 40°~60°＋CAU 20°~30°）能最大程度展开左主干末端及前降支、回旋支开口，避免血管重叠，是观察左冠分叉的黄金体位，B正确。\n【为什么错】A正位+头位显示前降支近中段；C、D显示前降支中远段及对角支；E单一体位无法充分展开分叉。", "tr": "蜘蛛位＝左前斜+足位；肝位＝右前斜+足位，勿混淆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1039", "t": "单选题", "s": "观察右冠状动脉全程的最佳投照体位是", "o": {"A": "左前斜45°", "B": "右前斜30°", "C": "正位+足位", "D": "标准侧位", "E": "汤氏位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-039", "kp": "右冠造影投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】左前斜45°可将右冠状动脉拉直展开呈“C”形，从头端到后降支全程显示清晰，是观察右冠的主力体位，A正确。\n【为什么错】B、C、D、E显示右冠节段局限或不作为右冠全程显示体位。", "tr": "右冠呈“C”形用LAO45°；右冠远端分叉呈“L”形用正位+头位。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1040", "t": "单选题", "s": "左、右冠状动脉造影每次手推对比剂的用量约为", "o": {"A": "左冠8~10ml、右冠6~8ml", "B": "左冠3~5ml、右冠1~2ml", "C": "左冠30ml、右冠30ml", "D": "左冠50ml、右冠50ml", "E": "两侧均为2ml"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-040", "kp": "冠脉造影对比剂用量", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】冠脉每次造影量依血管粗细与显影情况，左冠约8~10ml、右冠约6~8ml，1~2秒内手推完成，A正确。\n【为什么错】B、E过少显影不足；C、D过多增加心肌毒性及并发症风险。", "tr": "冠脉手推小剂量（毫升级），主动脉高压注射（数十毫升），量级不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1041", "t": "单选题", "s": "冠状动脉造影不使用高压注射器而采用手推注射的主要原因是", "o": {"A": "单纯为了减少对比剂用量", "B": "冠脉血流快，需按血流速度实时调节注药，且避免高压损伤冠脉口", "C": "高压注射器无法与X线机连接", "D": "缩短检查时间", "E": "降低辐射剂量"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-041", "kp": "冠脉造影注射方式", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】冠脉开口细、血流快，手推可根据显影情况实时调整注射力度与速度，避免高压注射损伤冠脉口或致对比剂反流，B正确。\n【为什么错】A省药并非主因；C高压注射器为DSA室常规配置；D、E与注射方式无直接关系。", "tr": "冠脉手推的核心在于“可控”与“安全”，而非设备缺乏。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1042", "t": "单选题", "s": "疑肾血管性高血压，确诊有无肾动脉狭窄的检查是", "o": {"A": "腹主动脉造影+选择性肾动脉造影", "B": "心脏彩色超声", "C": "脑电图", "D": "胸部X线平片", "E": "膀胱造影"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-042", "kp": "肾动脉造影适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】肾动脉狭窄是肾血管性高血压的常见原因，腹主动脉造影加选择性肾动脉造影可准确显示狭窄部位与程度，A正确。\n【为什么错】B心超看心脏结构；C脑电图看脑电活动；D胸片看心肺；E膀胱造影看膀胱形态，均与肾动脉无关。", "tr": "肾血管性高血压→肾动脉造影；这也是肾动脉介入治疗的前提检查。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1043", "t": "单选题", "s": "肝癌行TACE（肝动脉化疗栓塞）前，必须完成的DSA检查是", "o": {"A": "选择性肝动脉造影", "B": "支气管动脉造影", "C": "颈动脉造影", "D": "盆腔静脉造影", "E": "椎动脉造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-043", "kp": "肝动脉造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】TACE前必须行肝动脉造影明确肿瘤大小、数目及供血动脉来源，才能决定栓塞范围与超选插管，A正确。\n【为什么错】B用于咯血；C、E用于脑血管病；D用于盆腔病变，均与肝癌介入无关。", "tr": "“先造影后栓塞”是TACE铁律，供血动脉评估是栓塞治疗的前提。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1044", "t": "单选题", "s": "选择性腹腔干（腹腔动脉）造影主要显示", "o": {"A": "肝、脾、胃及胰腺等腹腔脏器动脉", "B": "双侧肾动脉", "C": "肠系膜上、下动脉", "D": "冠状动脉", "E": "子宫动脉"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-044", "kp": "腹腔干造影解剖", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】腹腔干发出肝总动脉、脾动脉、胃左动脉等分支，主要供血肝、脾、胃、胰等上腹腔脏器，A正确。\n【为什么错】B肾动脉为腹主动脉侧壁分支，需单独造影；C肠系膜动脉需另行插管；D、E分属心脏与盆腔供血。", "tr": "腹腔干管上腹腔脏器，肠系膜动脉管肠道血供，解剖供血范围勿混。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1045", "t": "单选题", "s": "子宫肌瘤行子宫动脉栓塞（UAE）时应栓塞的血管是", "o": {"A": "双侧子宫动脉", "B": "髂外动脉", "C": "股深动脉", "D": "卵巢动脉主干", "E": "腹主动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-045", "kp": "子宫动脉栓塞", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (5)盆腔", "ex": "【为什么对】子宫肌瘤主要由双侧子宫动脉供血，超选择性栓塞双侧子宫动脉可使肌瘤缺血坏死而正常子宫组织受损较小，A正确。\n【为什么错】B、E为血管干道，栓塞可致严重并发症；C为下肢血管；D卵巢动脉通常非肌瘤主要供血。", "tr": "UAE强调超选双侧子宫动脉，保护卵巢与子宫正常血供。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1046", "t": "单选题", "s": "盆腔DSA造影时，导管通常选择插至", "o": {"A": "髂内动脉", "B": "肠系膜上动脉", "C": "锁骨下动脉", "D": "肾动脉", "E": "肝总动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-046", "kp": "盆腔DSA插管", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (5)盆腔", "ex": "【为什么对】盆腔脏器、肿瘤及出血多由髂内动脉供血，盆腔DSA常规将导管置于髂内动脉行选择性造影，A正确。\n【为什么错】B、C、D、E分属肠道、上肢、肾脏、肝脏血供，与盆腔无关。", "tr": "盆腔血供来自髂内动脉；子宫动脉为其重要分支。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1047", "t": "单选题", "s": "下肢动脉DSA检查最常用的穿刺入路是", "o": {"A": "股动脉", "B": "颈内静脉", "C": "腘动脉", "D": "桡动脉", "E": "锁骨下动脉"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-047", "kp": "下肢DSA入路", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】下肢动脉造影多经股动脉穿刺置鞘，采用顺行或逆行插管完成，A正确。\n【为什么错】B为静脉入路；C腘动脉穿刺少用、并发症多；D桡动脉用于冠脉介入；E位置深、风险高。", "tr": "下肢DSA=股动脉入路；对侧股动脉翻山用于处理同侧髂股病变。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1048", "t": "单选题", "s": "下肢动脉闭塞症需一次显示腹主动脉下段至足部全程血管，宜采用", "o": {"A": "单帧静态采集", "B": "步进式DSA连续采集并图像拼接", "C": "降低对比剂浓度后透视", "D": "心脏门控采集", "E": "固定视野一次注药"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-048", "kp": "下肢步进式DSA", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】步进式DSA随导管床分段移动采集后经拼接软件合成下肢血管全长图像，一次注药显示全程，是下肢动脉长段病变的标准技术，B正确。\n【为什么错】A、E视野受限无法覆盖全程；C透视无诊断价值；D用于心脏减少搏动伪影。", "tr": "“步进+拼接”＝全下肢血管显示，要求各段图像均匀衔接无中断。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1049", "t": "单选题", "s": "患者双侧髂动脉闭塞，经右侧股动脉穿刺困难，行下肢DSA应采用的入路技术是", "o": {"A": "经左侧股动脉穿刺造影", "B": "经颈内静脉逆行造影", "C": "经肘正中静脉造影", "D": "经腘动脉顺行穿刺", "E": "直接切开股动脉置管"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-049", "kp": "下肢DSA入路补救", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】一侧股动脉入路失败时，改经对侧股动脉穿刺，仍可通过翻山或顺行插管完成下肢造影，是最常规的补救入路，A正确。\n【为什么错】B、C为静脉入路，无法行下肢动脉造影；D腘动脉穿刺仅用于特殊病例且并发症多；E切开置管创伤大，非首选。", "tr": "一侧入路失败换对侧股动脉，腘动脉顺行穿刺为特殊备选。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1050", "t": "单选题", "s": "四肢动脉DSA将对比剂稀释至约含碘200mg/ml的主要目的是", "o": {"A": "提高血管显影密度", "B": "降低黏滞度、减轻血管刺激性疼痛及对比剂用量", "C": "提高高压注射器的注射压力", "D": "加快对比剂在体内的循环", "E": "降低辐射剂量"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-050", "kp": "四肢对比剂浓度", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】肢体血管较细，高浓度对比剂刺激易引起明显灼痛，稀释至200mgI/ml可降低黏滞度、减轻血管刺激与不适，同时满足显影需要，B正确。\n【为什么错】A稀释反而降低密度；C稀释与注射压力无关；D、E与对比剂浓度无关。", "tr": "肢体动脉低浓度（200mgI/ml）是共识；静脉DSA反而需较高浓度。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1051", "t": "多选题", "s": "下列属于DSA适应证的有", "o": {"A": "颅内动脉瘤", "B": "脑动静脉畸形", "C": "颈动脉狭窄", "D": "一般健康体检", "E": "下肢动脉硬化闭塞"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-051", "kp": "DSA适应证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】动脉瘤、动静脉畸形、动脉狭窄闭塞等血管性疾病及下肢动脉硬化闭塞均为DSA的典型适应证，A、B、C、E正确。\n【为什么错】D常规健康体检无血管检查指征，且DSA为有创检查，不作为筛查手段。", "tr": "DSA适应证核心是血管疾病与肿瘤血供评估，无指征检查属过度医疗。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1052", "t": "多选题", "s": "DSA检查的相对或绝对禁忌证包括", "o": {"A": "碘对比剂过敏", "B": "严重心功能不全", "C": "穿刺部位皮肤感染", "D": "血压轻度升高", "E": "严重出血倾向"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-052", "kp": "DSA禁忌证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】碘过敏、严重心衰、穿刺部位感染、严重出血倾向均为DSA禁忌或相对禁忌，A、B、C、E正确。\n【为什么错】D血压轻度升高在控制平稳后可行检查，不属于禁忌证。", "tr": "绝对禁忌：碘过敏；相对禁忌：心肾肝衰竭、出血倾向、感染、妊娠等。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1053", "t": "多选题", "s": "股动脉穿刺术后穿刺部位的并发症包括", "o": {"A": "出血和血肿", "B": "假性动脉瘤", "C": "动静脉瘘", "D": "穿刺点血栓栓塞", "E": "对比剂肾病"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-053", "kp": "穿刺部位并发症", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】出血血肿、假性动脉瘤、动静脉瘘、血栓栓塞均为穿刺部位并发症，A、B、C、D正确。\n【为什么错】E对比剂肾病为对比剂引起的肾脏并发症，与穿刺部位无关。", "tr": "穿刺局部并发症与对比剂全身性并发症要区分开。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1054", "t": "多选题", "s": "对比剂急性过敏反应的临床表现包括", "o": {"A": "荨麻疹", "B": "喉头水肿", "C": "血压下降", "D": "支气管痉挛", "E": "血糖升高"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-054", "kp": "对比剂过敏反应", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】荨麻疹、喉头水肿、血压下降、支气管痉挛均为对比剂急性过敏反应（类过敏反应）的典型表现，A、B、C、D正确。\n【为什么错】E血糖升高非过敏反应表现。", "tr": "对比剂反应重在呼吸道与循环系统症状，重者表现为过敏性休克。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1055", "t": "多选题", "s": "DSA术前患者准备包括", "o": {"A": "碘过敏试验", "B": "术前禁食4~6小时", "C": "凝血功能与肾功能检查", "D": "穿刺部位备皮", "E": "术前常规使用抗生素"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-055", "kp": "术前患者准备", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】碘过敏试验、禁食、凝血与肾功能检查、备皮均为术前常规准备，A、B、C、D正确。\n【为什么错】E血管造影为无菌操作，术前常规使用抗生素并非必需，故排除。", "tr": "术前关键是过敏、出血、肾功能三大风险评估，预防性抗生素不常规使用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1056", "t": "多选题", "s": "DSA检查前应准备的器械物品包括", "o": {"A": "穿刺针", "B": "导丝", "C": "导管", "D": "高压注射器及对比剂", "E": "剖腹探查手术器械包"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-056", "kp": "术前物品准备", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】穿刺针、导丝、导管、高压注射器及对比剂是DSA基本器械与设备，A、B、C、D正确。\n【为什么错】E剖腹探查器械为外科手术用品，DSA为微创介入，无需准备。", "tr": "介入器械＝穿刺针＋导丝＋导管（鞘）＋高压注射系统，区别于外科器械。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1057", "t": "多选题", "s": "Seldinger技术操作中正确的做法有", "o": {"A": "穿刺点选股动脉搏动最明显处", "B": "见回血后沿针腔引入导丝", "C": "导丝遇阻力可强行推进", "D": "沿导丝送入导管或导管鞘", "E": "术后拔管充分压迫止血"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-057", "kp": "Seldinger操作要点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】搏动明显处穿刺、见回血后引丝、沿导丝送管、术后压迫止血均为正确操作，A、B、D、E正确。\n【为什么错】C导丝遇阻力强行推进易致血管损伤或夹层，应在透视下调整或退出重试。", "tr": "“遇阻力先透视找原因，绝不蛮力推进”是导丝操作安全铁律。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-1058", "t": "多选题", "s": "静脉DSA（IV-DSA）的优点包括", "o": {"A": "操作简便", "B": "创伤小", "C": "不需动脉插管", "D": "细小动脉显示清晰", "E": "对比剂用量少"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-058", "kp": "静脉DSA优点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】IV-DSA经静脉途径完成，操作简便、创伤小、不需动脉插管，A、B、C正确。\n【为什么错】D对比剂经肺循环稀释后细小动脉显示不佳；E静脉法对比剂用量大，均属IV-DSA的缺点。", "tr": "IV-DSA优在简便创伤小，缺在大剂量与差显影，优缺点成对记忆。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1059", "t": "多选题", "s": "静脉DSA（IV-DSA）的缺点包括", "o": {"A": "对比剂用量大", "B": "血液稀释使细小血管显示不佳", "C": "患者移动产生的运动伪影明显", "D": "操作复杂、创伤大", "E": "不能显示全身大血管"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-059", "kp": "静脉DSA缺点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】静脉法对比剂用量大、稀释后细小血管显示差，且因循环时间长、患者易移动而产生运动伪影，A、B、C正确。\n【为什么错】D静脉法不需动脉插管，操作简便创伤小，说法错误；E静脉法恰恰可以显示主动脉等全身大血管，不属于缺点。", "tr": "IV-DSA可显示大血管、操作简便，但细小血管显示差、用量大。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1060", "t": "多选题", "s": "关于能量减影的叙述正确的有", "o": {"A": "利用碘的K吸收边（33.2keV）原理", "B": "需采用两种不同kVp的X线成像", "C": "能消除软组织影", "D": "能同时消除骨骼影", "E": "对软组织运动较为敏感"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-060", "kp": "能量减影特点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】能量减影利用碘K吸收边，用两种不同能量成像相减，能消除软组织影但对软组织运动敏感，A、B、C、E正确。\n【为什么错】D能量减影不能消除骨骼影，骨骼仍保留，故排除。", "tr": "能量减影去软组织留骨骼，与时间减影“骨软组织全消”形成对比。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-1061", "t": "多选题", "s": "属于时间减影方式的有", "o": {"A": "脉冲减影", "B": "超脉冲减影", "C": "连续减影", "D": "路标技术", "E": "能量减影"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-061", "kp": "时间减影分类", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】脉冲减影、超脉冲减影、连续减影及路标技术均属时间减影的不同实现方式，A、B、C、D正确。\n【为什么错】E能量减影是利用能量差异减影，与时间减影并列，不属于时间减影。", "tr": "时间减影家族：脉冲/超脉冲/连续/路标；能量减影是另一大类。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1062", "t": "多选题", "s": "影响DSA图像质量的患者自身因素包括", "o": {"A": "不自主运动", "B": "屏气不佳", "C": "肠蠕动", "D": "心律不齐", "E": "对比剂过敏试验阴性"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-062", "kp": "DSA图像质量影响因素", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】不自主运动、屏气不佳、肠蠕动、心律不齐均可导致配准不良而产生运动伪影，影响DSA图像质量，A、B、C、D正确。\n【为什么错】E过敏试验阴性为正常结果，与图像质量无关。", "tr": "图像质量受设备、操作、造影方法及患者四大因素影响，患者运动是常见伪影源。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1063", "t": "多选题", "s": "头颈部DSA的适应证包括", "o": {"A": "颅内动脉瘤", "B": "脑动静脉畸形", "C": "烟雾病", "D": "颈动脉狭窄", "E": "无明确指征的健康筛查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-063", "kp": "头颈部DSA适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】颅内动脉瘤、动静脉畸形、烟雾病、颈动脉狭窄均为头颈部DSA的典型适应证，A、B、C、D正确。\n【为什么错】E无指征的健康筛查不属适应证，DSA为有创检查不可滥用。", "tr": "头颈DSA核心适应证为脑血管病变与颈动脉狭窄闭塞病变。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1064", "t": "多选题", "s": "全脑血管造影常需检查的血管包括", "o": {"A": "主动脉弓", "B": "左颈总动脉", "C": "右颈总动脉", "D": "左、右椎动脉", "E": "左心室"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-064", "kp": "全脑血管造影血管", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】全脑血管造影常规包括主动脉弓造影及双侧颈总、双侧椎动脉四个血管分支的选择性造影，A、B、C、D正确。\n【为什么错】E左心室造影属心脏造影范畴，不属于全脑血管造影的常规血管。", "tr": "“弓上四血管”＝双颈总＋双椎动脉，心腔造影另属心脏DSA。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1065", "t": "多选题", "s": "胸部DSA常用的造影项目包括", "o": {"A": "主动脉造影", "B": "肺动脉造影", "C": "支气管动脉造影", "D": "子宫动脉造影", "E": "肾动脉造影"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-065", "kp": "胸部DSA造影项目", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】主动脉造影、肺动脉造影、支气管动脉造影均为胸部DSA常用项目，A、B、C正确。\n【为什么错】D子宫动脉造影属盆腔；E肾动脉造影属腹部。", "tr": "胸部DSA＝主动脉＋肺动脉＋支气管动脉；子宫、肾脏分属盆腹。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1066", "t": "多选题", "s": "选择性冠状动脉造影的适应证包括", "o": {"A": "典型心绞痛", "B": "急性心肌梗死", "C": "冠脉支架术后随访", "D": "不明原因胸痛伴可疑心肌缺血", "E": "常规体检"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-066", "kp": "冠脉造影适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】心绞痛、急性心肌梗死、支架术后随访及不明原因胸痛伴缺血均属冠脉造影适应证，A、B、C、D正确。\n【为什么错】E常规体检无冠脉造影指征，该检查为有创且需特殊适应证。", "tr": "冠脉造影的适应证核心是确诊冠心病与指导血运重建。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1067", "t": "多选题", "s": "冠状动脉造影的并发症包括", "o": {"A": "心律失常（心室颤动）", "B": "冠脉口夹层", "C": "急性血栓形成", "D": "对比剂过敏反应", "E": "再蒙片操作失败"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-067", "kp": "冠脉造影并发症", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】心律失常（尤其室颤）、冠脉口夹层、急性血栓、对比剂过敏反应均为冠脉造影的并发症，A、B、C、D正确。\n【为什么错】E再蒙片是图像后处理技术，操作失败不属临床并发症。", "tr": "冠脉造影最危险的并发症是室颤与冠脉夹层，术中须持续心电监护。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1068", "t": "多选题", "s": "腹部DSA常行的选择性造影包括", "o": {"A": "腹主动脉造影", "B": "腹腔干造影", "C": "肠系膜上动脉造影", "D": "肾动脉造影", "E": "颈总动脉造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-068", "kp": "腹部DSA造影项目", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】腹主动脉及腹腔干、肠系膜上动脉、肾动脉造影均为腹部DSA常用选择性造影，A、B、C、D正确。\n【为什么错】E颈总动脉造影属头颈部DSA范畴。", "tr": "腹部DSA＝腹主动脉＋腹腔干＋肠系膜动脉＋肾动脉；颈动脉属头颈。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1069", "t": "多选题", "s": "肾动脉造影的适应证包括", "o": {"A": "肾血管性高血压", "B": "肾动脉狭窄评估", "C": "移植肾血管评估", "D": "肾肿瘤术前栓塞", "E": "常规肾功能体检"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-069", "kp": "肾动脉造影适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】肾血管性高血压、肾动脉狭窄评估、移植肾血管评估及肾肿瘤术前栓塞均为肾动脉造影适应证，A、B、C、D正确。\n【为什么错】E肾功能评估靠血液生化检查，常规体检不需肾动脉造影。", "tr": "肾动脉造影服务于“狭窄”与“肿瘤栓塞”两大目的，非常规体检项目。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1070", "t": "多选题", "s": "盆腔DSA的临床应用包括", "o": {"A": "子宫肌瘤栓塞（UAE）", "B": "产后大出血栓塞", "C": "盆腔肿瘤术前栓塞", "D": "前列腺动脉栓塞", "E": "脑动脉瘤栓塞"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-070", "kp": "盆腔DSA应用", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (5)盆腔", "ex": "【为什么对】子宫肌瘤栓塞、产后大出血栓塞、盆腔肿瘤术前栓塞及前列腺动脉栓塞均为盆腔DSA的应用，A、B、C、D正确。\n【为什么错】E脑动脉瘤栓塞为头颈部DSA的应用，与盆腔无关。", "tr": "盆腔介入两大主题：妇科出血/肌瘤栓塞与盆腔肿瘤术前评估。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1071", "t": "多选题", "s": "四肢DSA的适应证包括", "o": {"A": "下肢动脉硬化闭塞症", "B": "血栓闭塞性脉管炎", "C": "糖尿病足", "D": "四肢血管损伤", "E": "常规健康体检"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-071", "kp": "四肢DSA适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】下肢动脉硬化闭塞、血栓闭塞性脉管炎、糖尿病足及四肢血管损伤均为四肢DSA的适应证，A、B、C、D正确。\n【为什么错】E常规体检无适应证。", "tr": "四肢DSA核心适应证是缺血性病变与血管外伤。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1072", "t": "多选题", "s": "DSA设备系统组成包括", "o": {"A": "X线球管与高压发生器", "B": "探测器（影像增强器或平板探测器）", "C": "图像数字处理系统", "D": "高压注射器", "E": "核磁共振梯度系统"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-072", "kp": "DSA设备组成", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】X线发生系统、探测器、数字图像处理系统及高压注射器均为DSA设备的基本组成，A、B、C、D正确。\n【为什么错】E梯度系统为MRI设备部件，与DSA无关。", "tr": "DSA设备无梯度系统；高压注射器是DSA（及CT增强）的配套设备。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1073", "t": "多选题", "s": "高压注射器的注射参数包括", "o": {"A": "注射流率", "B": "注射总量", "C": "压力限值", "D": "注射延迟时间", "E": "图像矩阵"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-073", "kp": "高压注射器参数", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】流率、总量、压力限值及延迟时间是高压注射器的核心设定参数，A、B、C、D正确。\n【为什么错】E图像矩阵属于采集与显示参数，不属注射器参数。", "tr": "注射参数管“怎么注”，矩阵帧率管“怎么采”，分属两套参数体系。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1074", "t": "多选题", "s": "减影后的DSA图像特点包括", "o": {"A": "骨骼影被消除", "B": "软组织影被消除", "C": "含碘血管显示清晰", "D": "血管壁钙化显示最佳", "E": "背景噪声相对突出"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-074", "kp": "减影图像特点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】时间减影后骨骼与软组织被消除，含碘血管突出显示，同时因相减处理使背景噪声相对突出，A、B、C、E正确。\n【为什么错】D血管壁钙化与骨骼同属高密度背景，减影后同样被消除，不能最佳显示。", "tr": "钙化属“背景”，减影后消失；DSA看的是血管腔内对比剂。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1075", "t": "多选题", "s": "对比剂肾病（CIN）的危险因素包括", "o": {"A": "原有肾功能不全", "B": "糖尿病", "C": "脱水状态", "D": "对比剂用量过大", "E": "年轻健康人群"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-075", "kp": "对比剂肾病危险因素", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】原有肾功能不全、糖尿病、脱水及对比剂用量过大均为CIN的高危因素，A、B、C、D正确。\n【为什么错】E年轻健康人群肾储备好、CIN风险低，不属于危险因素。", "tr": "CIN风险＝肾功能基础＋糖尿病＋脱水＋剂量；识别高危患者先行预防。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U11-1076", "t": "多选题", "s": "改善DSA图像运动伪影的措施包括", "o": {"A": "嘱患者屏气并固定被检部位", "B": "缩短注药与采像的时间间隔", "C": "采用心电门控采集", "D": "对移动部位重新选择蒙片（再蒙片）", "E": "将对比剂浓度提高至90%以上"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-076", "kp": "DSA运动伪影改善", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】屏气固定、缩短注药采像间隔、心电门控及再蒙片均能有效减少或纠正运动伪影，A、B、C、D正确。\n【为什么错】E提高对比剂浓度不解决运动配准问题，且高浓度并非影像质量改善手段。", "tr": "抗运动伪影的手段是“固定＋快采＋门控＋再蒙片”，与对比剂浓度无关。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1077", "t": "多选题", "s": "关于主动脉造影的技术要点正确的有", "o": {"A": "选用猪尾多侧孔导管", "B": "采用高压注射器大流率注射", "C": "流率过低可致对比剂稀释、显影不均", "D": "先采集蒙片再注射对比剂", "E": "必须使用微导管超选择性注射"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-077", "kp": "主动脉造影技术要点", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】主动脉造影用猪尾多侧孔导管、高压大流率注射、流率不足致稀释不均、先采蒙片再注药均为正确要点，A、B、C、D正确。\n【为什么错】E主动脉造影属非选择性造影，需快速团注大流量对比剂，微导管仅用于超选择性小血管，不适用于主动脉造影。", "tr": "大血管用大导管大流率，微导管是超选小血管的工具。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1078", "t": "多选题", "s": "DSA在介入治疗中的特殊应用技术包括", "o": {"A": "路标技术引导超选择性插管", "B": "血管栓塞治疗（如TACE、支气管动脉栓塞）", "C": "血管成形与支架置入", "D": "动脉溶栓治疗", "E": "常规胸部X线摄影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-078", "kp": "DSA介入应用", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】路标引导超选、栓塞、成形支架置入及溶栓均为DSA介入治疗的应用技术，A、B、C、D正确。\n【为什么错】E常规胸部X线摄影属普通X线检查，与DSA介入应用无关。", "tr": "DSA介入四大方向：引导、栓塞、成形、溶栓。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U11-1079a", "t": "共用题干题", "s": "该患者股动脉穿刺点应选择在", "o": {"A": "腹股沟韧带上方1~2cm处", "B": "腹股沟韧带中点下方1~2cm股动脉搏动最明显处", "C": "腘窝处", "D": "大腿中段内侧", "E": "髂前上棘处"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-079", "kp": "股动脉穿刺点定位", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】腹股沟韧带中点下方1~2cm搏动最明显处是股动脉标准穿刺点，下方有耻骨支撑便于压迫止血，B正确。\n【为什么错】A韧带上方为髂外动脉段且无骨性支撑；C、D非股动脉表浅搏动区；E与股动脉走行无关。", "tr": "股动脉穿刺点在腹股沟韧带下方，过高过低均增加并发症。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1101", "gs": "患者男，62岁，因双下肢间歇性跛行1年、加重2个月入院，查体双下肢皮温低、足背动脉搏动减弱，踝肱指数（ABI）0.5。临床拟行下肢动脉DSA明确血管狭窄部位与程度，先行右侧股动脉穿刺置鞘。"}, {"id": "U11-1079b", "t": "共用题干题", "s": "穿刺针见搏动性鲜红色血液回血后，正确的下一步操作是", "o": {"A": "退出穿刺针，直接置入导管", "B": "经针腔直接注入对比剂造影", "C": "拔出穿刺针后重新穿刺", "D": "固定穿刺针，沿针腔引入导丝", "E": "先压迫止血再送导管"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-080", "kp": "Seldinger穿刺操作", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】Seldinger技术见搏动性动脉血回血后，应固定穿刺针并沿针腔送入导丝，再退出穿刺针沿导丝置鞘，D正确。\n【为什么错】A未引入导丝直接置管易伤血管；B未置鞘即注射属错误操作；C已成功穿刺无需重穿；E应先完成置管再行止血。", "tr": "“针—丝—管”顺序不能乱，导丝是导管进入血管的轨道。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1101", "gs": ""}, {"id": "U11-1079c", "t": "共用题干题", "s": "术后拔除导管鞘后，穿刺部位徒手压迫止血时间一般为", "o": {"A": "1~2分钟", "B": "5分钟以内", "C": "10~15分钟", "D": "1小时以上", "E": "无需压迫"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-081", "kp": "术后穿刺点压迫", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】拔鞘后需充分压迫止血10~15分钟使穿刺道闭合，再以沙袋加压包扎并制动，C正确。\n【为什么错】A、B压迫时间不足易再出血形成血肿；D过长时间增加不适与并发症；E必然导致出血。", "tr": "股动脉压迫10~15分钟、术侧肢体制动6~8小时是术后护理要点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1101", "gs": ""}, {"id": "U11-1080a", "t": "共用题干题", "s": "该患者DSA检查前最关键的准备是", "o": {"A": "常规心电图检查", "B": "测量体重", "C": "拍摄胸部X线片", "D": "询问碘过敏史并行碘过敏试验", "E": "心理疏导谈话"}, "d": "易", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-082", "kp": "术前过敏史评估", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】碘对比剂过敏是DSA绝对禁忌，术前询问过敏史并行过敏试验是保障安全的关键环节，D正确。\n【为什么错】A、C为常规项目非关键；B与检查安全性无关；E心理疏导非术前准备核心。", "tr": "过敏史评估直接关系能否造影，是术前安全评估的第一关。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1102", "gs": "患者女，48岁，突发剧烈头痛伴恶心呕吐2小时急诊入院，头颅CT示蛛网膜下腔出血，高度怀疑颅内动脉瘤破裂，临床申请全脑血管DSA检查，术前拟行碘过敏试验并评估肾功能。"}, {"id": "U11-1080b", "t": "共用题干题", "s": "该患者全脑血管造影的检查顺序应为", "o": {"A": "直接行左椎动脉选择性造影", "B": "先主动脉弓造影，再选择性行双侧颈总、双侧椎动脉造影", "C": "仅行双侧颈内动脉造影", "D": "先右颈总动脉再左椎动脉即可", "E": "先行左心室造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-083", "kp": "全脑血管造影顺序", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】全脑血管造影常规先主动脉弓造影了解弓上血管开口与走行变异，再选择性行双侧颈总动脉及双侧椎动脉共4条血管造影，B正确。\n【为什么错】A、C、D均非完整规范流程；E左心室造影属心脏造影，与脑血管检查无关。", "tr": "造影顺序“先大后小、先非选择性后选择性”，保证血管覆盖完整。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1102", "gs": ""}, {"id": "U11-1081a", "t": "共用题干题", "s": "为清晰显示左主干分叉及前降支、回旋支开口，应采用的投照体位是", "o": {"A": "正位+头位", "B": "右前斜+头位", "C": "蜘蛛位（左前斜+足位）", "D": "标准后前位", "E": "左侧位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-084", "kp": "左冠分叉投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】蜘蛛位（LAO 40°~60°＋CAU 20°~30°）可将左主干末端及前降支、回旋支开口充分展开，是观察左冠分叉的黄金体位，C正确。\n【为什么错】A显示前降支近中段；B显示前降支中远段；D、E不能充分展开分叉结构。", "tr": "蜘蛛位＝LAO+CAU；肝位＝RAO+CAU，体位名称与角度要分清。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1103", "gs": "患者男，55岁，反复发作性心前区闷痛1个月，活动后加重，静息心电图示ST段压低、T波倒置，临床拟行选择性冠状动脉造影明确病变，已服用阿司匹林与降脂药物，无造影剂过敏史。"}, {"id": "U11-1081b", "t": "共用题干题", "s": "冠脉造影时对比剂注射方式应选择", "o": {"A": "手推注射，根据显影情况实时调节", "B": "高压注射器大流率注射", "C": "持续缓慢滴注", "D": "经导管直接灌入", "E": "不注射对比剂直接透视"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-085", "kp": "冠脉造影注射方式", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】冠脉血流快、开口细，手推可依实时显影调节注射力度与速度，避免高压反流与损伤冠脉口，A正确。\n【为什么错】B高压注射易损伤冠脉口或致反流；C、D无法形成快速团注；E不注射无法显影。", "tr": "冠脉手推（8~10ml）是经典操作，与主动脉高压注射形成对比。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1103", "gs": ""}, {"id": "U11-1082a", "t": "共用题干题", "s": "为同时显示左髂动脉及股腘动脉病变，首选穿刺入路是", "o": {"A": "左侧腘动脉顺行穿刺", "B": "经右侧股动脉穿刺行翻山造影", "C": "经左侧肘正中静脉", "D": "经颈内静脉逆行", "E": "直接切开左股动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-086", "kp": "下肢DSA翻山技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】左髂动脉及股腘动脉均有病变时，同侧顺行穿刺可能受阻，经对侧（右侧）股动脉穿刺行翻山（cross-over）技术，导管翻越腹主动脉分叉进入左髂动脉，可全程显示病变，B正确。\n【为什么错】A腘动脉穿刺非首选且并发症多；C、D静脉入路无法行下肢动脉造影；E切开置管创伤大。", "tr": "“翻山”＝对侧股动脉入路跨越腹主动脉分叉，用于同侧髂股病变。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1104", "gs": "患者男，70岁，左下肢发凉麻木伴静息痛2个月，查体左侧股动脉搏动减弱，踝肱指数（ABI）0.4，拟行下肢动脉DSA评估狭窄部位与程度，要求同时评估髂动脉及膝下流出道情况。"}, {"id": "U11-1082b", "t": "共用题干题", "s": "欲一次注药显示腹主动脉下段至足背动脉全程血管，应采用", "o": {"A": "单帧静态采集", "B": "重复三次分别造影", "C": "步进式DSA分段采集后图像拼接", "D": "心脏门控采集", "E": "降低帧率至1帧/s透视"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-087", "kp": "步进式DSA拼接", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】步进式DSA随床移动分段采集，再由拼接软件合成下肢血管全长图，一次注药完成全程显示，C正确。\n【为什么错】A视野局限；B多次注药增加剂量与用量；D用于心脏；E透视无诊断价值。", "tr": "下肢全长显示依赖“步进采集＋拼接”，是长段病变介入的前提。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1104", "gs": ""}, {"id": "U11-1082c", "t": "共用题干题", "s": "该患者肢体动脉造影对比剂应如何配制", "o": {"A": "使用370mgI/ml原液高压注射", "B": "用蒸馏水稀释至100mgI/ml以下", "C": "混合造影剂与自体血注射", "D": "稀释至约含碘200mg/ml的低渗非离子型对比剂", "E": "加入肾上腺素增强显影"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-088", "kp": "四肢对比剂稀释", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】肢体血管细、高浓度刺激痛感强，常规将非离子型对比剂稀释至约含碘200mg/ml，既满足显影又减轻刺激与用量，D正确。\n【为什么错】A原液刺激痛感重、用量大；B浓度过低显影不足；C自体血混合无此必要；E肾上腺素属血管活性药，不可加入。", "tr": "肢体动脉低浓度（200mgI/ml）、下肢全程步进拼接是两大要点。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1104", "gs": ""}, {"id": "U11-1083a", "t": "共用题干题", "s": "TACE术前DSA应首先进行的检查是", "o": {"A": "选择性肝动脉造影明确肿瘤供血", "B": "左心室造影", "C": "颈动脉造影", "D": "肾动脉造影", "E": "髂内动脉造影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-089", "kp": "TACE术前肝动脉造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】TACE前必须肝动脉造影明确肿瘤大小、数目、供血动脉及有无肝外寄生供血，才能制定栓塞方案，A正确。\n【为什么错】B、C、D、E分属心脏、脑部、肾脏、盆腔血管，与肝癌介入无关。", "tr": "肝癌TACE“先造影后栓塞”，供血动脉评估决定栓塞效果。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1105", "gs": "患者男，58岁，乙型肝炎肝硬化病史，增强CT示肝右叶巨块型肝癌，AFP明显升高，临床拟行TACE（肝动脉化疗栓塞）治疗，术前先行肝动脉DSA检查，评估肿瘤供血动脉来源。"}, {"id": "U11-1083b", "t": "共用题干题", "s": "明确肿瘤供血动脉后，为避免损伤正常肝组织的下一步操作是", "o": {"A": "直接经肝总动脉注射栓塞剂", "B": "增大栓塞剂用量", "C": "微导管超选择性插管至肿瘤供血动脉后栓塞", "D": "改为静脉途径栓塞", "E": "终止TACE治疗"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-090", "kp": "超选择性栓塞", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】微导管超选择性插管至肿瘤供血分支再栓塞，可最大限度地保护正常肝组织、提高栓塞效果，C正确。\n【为什么错】A经肝总动脉栓塞范围大、正常肝损伤重；B加大剂量增加异位栓塞风险；D栓塞为动脉途径；E属放弃治疗，均不正确。", "tr": "“超选越深、保护越多”是TACE质量控制的核心原则。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1105", "gs": ""}, {"id": "U11-1084a", "t": "共用题干题", "s": "该患者应首先进行的DSA检查是", "o": {"A": "冠状动脉造影", "B": "支气管动脉造影", "C": "肾动脉造影", "D": "颈内动脉造影", "E": "肠系膜上动脉造影"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-091", "kp": "咯血介入造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】咯血多源于支气管动脉，支气管动脉造影可直接显示出血供血动脉，是咯血介入治疗的首选检查，B正确。\n【为什么错】A、C、D、E分属心脏、肾脏、脑部、肠道血管，与咯血无关。", "tr": "咯血→支气管动脉造影＋栓塞；消化道出血→肠系膜动脉。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1106", "gs": "患者男，40岁，反复大咯血1周，每次约100~200ml，内科药物治疗效果不佳，胸部CT提示支气管扩张，生命体征尚平稳，临床拟行介入治疗控制咯血，已备好栓塞材料与急救药品。"}, {"id": "U11-1084b", "t": "共用题干题", "s": "造影中发现支气管动脉与脊髓动脉共干时，下列处理最恰当的是", "o": {"A": "直接常规栓塞该支", "B": "加大栓塞剂量彻底止血", "C": "改用高压注射快速栓塞", "D": "改行颈动脉造影替代", "E": "停止栓塞该支，警惕脊髓动脉损伤风险，必要时改用非栓塞方案"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-092", "kp": "脊髓动脉损伤防范", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】脊髓动脉与支气管动脉共干时，栓塞可能致脊髓缺血坏死引起截瘫，应停止栓塞并警惕风险，必要时以其他供血动脉或介入手段处理，E正确。\n【为什么错】A、B、C栓塞该支均可能引发脊髓损伤严重后果；D改行颈动脉造影与咯血无关。", "tr": "支气管动脉栓塞最需警惕脊髓动脉共干导致的截瘫并发症。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1106", "gs": ""}, {"id": "U11-1085a", "t": "共用题干题", "s": "为明确诊断应行的DSA检查是", "o": {"A": "腹主动脉造影+选择性肾动脉造影", "B": "左心室造影", "C": "全脑血管造影", "D": "冠状动脉造影", "E": "子宫动脉造影"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-093", "kp": "肾动脉造影确诊", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】年轻患者顽固性高血压伴腹部血管杂音提示肾动脉狭窄，腹主动脉造影加选择性肾动脉造影可明确诊断，A正确。\n【为什么错】B、C、D、E分属心脏、脑部、冠脉、盆腔血管，均不能显示肾动脉狭窄。", "tr": "年轻顽固性高血压→肾动脉造影，同时排除纤维肌性发育不良等病因。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1107", "gs": "患者女，32岁，血压持续升高3个月，多种降压药物联合治疗效果差，腹部听诊可闻及血管杂音，临床疑肾动脉狭窄所致肾血管性高血压，拟行DSA检查，术前已行肾功能与凝血功能评估。"}, {"id": "U11-1085b", "t": "共用题干题", "s": "选择性肾动脉造影的对比剂注射参数应选择", "o": {"A": "流率20~25ml/s、总量50ml", "B": "流率10~12ml/s、总量30ml", "C": "流率4~5ml/s、总量8~12ml", "D": "流率1ml/s以下、总量2ml", "E": "流率30ml/s、总量80ml"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-094", "kp": "肾动脉造影参数", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】肾动脉属中小分支血管，低流率小剂量注射即可清晰显影且不损伤血管，4~5ml/s、8~12ml为宜，C正确。\n【为什么错】A、B、E流率与总量过大，易致反流与血管损伤；D过少无法充分显影。", "tr": "选择性小动脉造影“低流率小剂量”，主动脉造影“高流率大剂量”。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1107", "gs": ""}, {"id": "U11-1095", "t": "案例分析题", "s": "患者男，60岁，因反复头晕、一过性言语不清3天入院，头颅MRI提示脑缺血，临床拟行全脑血管DSA明确血管情况。术前碘过敏试验阴性，心电监护下经股动脉置鞘，先行主动脉弓造影，注射对比剂约20ml时患者突发全身荨麻疹、声音嘶哑、咽喉部发紧，继之呼吸急促，血压降至80/50mmHg，心率130次/分，血氧饱和度降至88%，考虑为对比剂急性过敏反应。此时技师应立即采取的正确措施是", "o": {"A": "继续完成造影以观察血管病变", "B": "立即停止注射对比剂，保持呼吸道通畅，协助医生抗过敏抗休克抢救并做好记录", "C": "嘱患者深呼吸平卧休息后继续检查", "D": "给予抗生素预防继发感染", "E": "降低对比剂浓度后继续造影"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-095", "kp": "对比剂过敏反应应急处理", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】患者出现荨麻疹、喉头水肿、低血压等典型对比剂急性过敏反应，应立即停止注射、保持气道通畅，并协助医生给予肾上腺素等抗过敏抗休克治疗，同时记录抢救过程，B正确。\n【为什么错】A继续造影加重病情；C单纯休息不能阻止过敏进展；D抗生素对过敏反应无效；E继续注射对比剂危及生命。", "tr": "对比剂重度过敏“停止注射—保持气道—抗过敏抗休克”是抢救三步。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1096", "t": "案例分析题", "s": "患者男，65岁，因急性前壁心肌梗死3小时行急诊冠状动脉造影及PCI术，术前已置入股动脉鞘，心电监护、除颤仪及抢救药品均处于备用状态。造影前完成主动脉根部和左冠状动脉造影准备，当造影导管置于左冠状动脉口并手推对比剂时，患者突发意识丧失、四肢抽搐，心电监护显示心室颤动波形，血压测不出。此时造影室内正确的处理配合是", "o": {"A": "继续手推对比剂完成左室造影", "B": "立即停止操作，撤出造影导管，协助电除颤并配合心肺复苏", "C": "加大吸氧观察5分钟再决定", "D": "嘱患者用力咳嗽缓解", "E": "加快造影速度缩短操作时间"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-096", "kp": "冠脉造影室颤处理", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】冠脉造影致心室颤动是危急并发症，应立即停止操作、撤出导管，尽早电除颤并配合心肺复苏，B正确。\n【为什么错】A继续注射加重心肌缺血与心律失常；C、D均无法终止室颤；E加快操作不能解决已发生的室颤。", "tr": "室颤处理争分夺秒，电除颤是首选，操作人员应立即配合。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1097", "t": "案例分析题", "s": "患者女，50岁，因反复发作的短暂性脑缺血发作拟行颈内动脉DSA。造影过程中患者情绪紧张，间断出现吞咽动作及头部轻微移动，减影图像显示血管边缘呈“双影”样模糊、轮廓错位，颅内段尤为明显，复查设备参数与原始图像未见异常，考虑为患者运动导致的蒙片与含对比剂图像配准不良，图像需重新处理后方可诊断。此时技师首先应采取的措施是", "o": {"A": "更换更粗的造影导管", "B": "嘱患者屏气并固定头部，必要时行再蒙片或重新采集", "C": "增加对比剂浓度增强显影", "D": "提高球管管电流", "E": "转外科开腹手术处理"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-097", "kp": "运动伪影处理", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】“双影”、轮廓错位是典型运动伪影，首先应取得患者配合（屏气、固定头部），并通过再蒙片或重新采集纠正配准误差，B正确。\n【为什么错】A导管粗细与伪影无关；C、D改变对比剂或管电流不能解决运动错位；E外科手术与图像伪影处理无关。", "tr": "运动伪影靠“固定＋屏气＋再蒙片”解决，改变成像参数无效。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1098", "t": "案例分析题", "s": "患者男，68岁，高血压病史10年，因腹主动脉瘤行腹主动脉DSA，术程顺利，术中血压平稳。术后回病房3小时患者自述右侧腹股沟穿刺部位胀痛，检查发现穿刺处包块进行性增大，触之有波动感，皮肤张力增高，血压由130/80mmHg降至100/60mmHg，心率由72次/分增至100次/分，无发热。首先考虑并应采取的措施是", "o": {"A": "属正常术后肿胀，无需处理", "B": "考虑穿刺点出血血肿或假性动脉瘤，立即徒手压迫穿刺点并评估血流动力学，必要时床旁超声及外科处理", "C": "立即拆除敷料任其出血", "D": "口服止痛药继续观察", "E": "让患者下床活动促进吸收"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-098", "kp": "穿刺点血肿处理", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】术后穿刺处包块进行性增大伴血流动力学变化，提示穿刺点活动性出血或假性动脉瘤，应立即压迫止血并评估病情，必要时超声证实并行外科处理，B正确。\n【为什么错】A正常肿胀不会进行性增大并致血压下降；C拆除敷料加重出血；D止痛不能阻止出血；E活动加重出血风险。", "tr": "穿刺点包块增大＋血压下降＝活动性出血，必须立即压迫并动态评估。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1099", "t": "案例分析题", "s": "患者男，72岁，吸烟史40年，右下肢间歇性跛行3年，近2个月静息痛明显，夜间尤甚，查体右侧足背动脉搏动消失，ABI 0.45，超声示右股浅动脉中段长段闭塞，远端流出道情况不详。临床拟行下肢动脉DSA，必要时行介入开通治疗，要求一次造影显示病变全程及远端流出道。关于该患者DSA检查的技术方案与参数选择，正确的是", "o": {"A": "单帧静态正位一次完成", "B": "经对侧股动脉或同侧股动脉入路，行步进式DSA分段采集并拼接，全程显示病变", "C": "仅造影右髂动脉即可", "D": "使用静脉DSA代替动脉DSA", "E": "不注射对比剂直接行血管成形"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-099", "kp": "下肢动脉DSA检查方案", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】下肢长段闭塞病变应经股动脉入路，采用步进式DSA分段采集拼接，一次注药显示病变全程与流出道，为介入开通提供依据，B正确。\n【为什么错】A静态采集无法覆盖全程；C仅髂动脉无法评估股腘段；D静脉DSA显影差不能满足介入要求；E不经造影盲目成形风险极大。", "tr": "下肢介入术前必须“全程造影＋流出道评估”，步进拼接是标准方案。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1100", "t": "案例分析题", "s": "患者男，45岁，反复黑便、鲜血便1月余，共输血4次，血红蛋白降至60g/L，胃镜与结肠镜均未发现明确出血灶，腹部CTA亦未明确定位出血血管，内科保守治疗效果差，目前仍间断排鲜血便，生命体征尚平稳。临床拟行DSA寻找出血部位并准备介入栓塞，术前已纠正贫血并签署知情同意，备好栓塞材料。正确的检查技术要点是", "o": {"A": "待出血停止1月后再择期造影", "B": "活动性出血期急诊造影，依次行腹腔干、肠系膜上动脉、肠系膜下动脉造影，发现对比剂外溢处即行栓塞", "C": "仅行腹主动脉造影即可定位", "D": "常规行冠状动脉造影排除心源性因素", "E": "造影前无需准备直接行腹部平片即可"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-100", "kp": "消化道出血DSA", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】消化道出血DSA应在活动性出血期急诊进行，依次行腹腔干、肠系膜上、肠系膜下动脉造影，造影剂外溢是出血的直接征象，发现后即可栓塞，B正确。\n【为什么错】A出血停止后造影常阴性；C腹主动脉造影无法显示肠系膜分支出血；D冠脉造影与消化道出血无关；E腹部平片不能显示血管出血。", "tr": "消化道出血DSA“出血时造影才有阳性率”，外溢征象是栓塞指征。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U11-1101", "t": "案例分析题", "s": "患者男，50岁，支气管扩张病史10年，因反复大咯血（每日约200~300ml）内科治疗无效行支气管动脉造影。造影显示右支气管动脉增粗迂曲，供血区域明显，拟行栓塞治疗。当导管超选进入右支气管动脉后，造影发现该动脉与肋间动脉共干，并见细小的脊髓动脉分支显影，患者双下肢活动正常，需权衡止血效果与脊髓保护。此时正确的处理是", "o": {"A": "立即常规栓塞该支以控制出血", "B": "加大栓塞剂用量彻底止血", "C": "撤出导管改用球囊扩张治疗", "D": "审慎处理：停止该支栓塞以防脊髓缺血，必要时超选择避开脊髓动脉或用其他供血动脉处理", "E": "改行颈动脉栓塞治疗"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-101", "kp": "咯血栓塞脊髓动脉防范", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】支气管动脉与脊髓动脉共干时栓塞可引起脊髓缺血坏死致截瘫，应审慎处理：停止该支栓塞，必要时超选避开脊髓动脉或选用其他供血动脉，D正确。\n【为什么错】A、B栓塞该支有截瘫风险；C球囊扩张不适用于咯血治疗；E颈动脉栓塞与咯血无关。", "tr": "脊髓动脉共干是支气管动脉栓塞的“禁区”，识别与规避是安全关键。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1102", "t": "案例分析题", "s": "患者女，55岁，突发剧烈头痛伴恶心呕吐2天入院，头颅CT示广泛蛛网膜下腔出血，行全脑血管DSA发现右侧大脑中动脉分叉部动脉瘤，直径约6mm，常规2D体位下瘤颈形态显示欠佳，载瘤动脉与周围血管关系不清，介入栓塞与开颅夹闭手术方案尚未确定。为准确评估动脉瘤颈宽度及其与载瘤动脉的关系，以指导治疗决策，应进一步采用的技术是", "o": {"A": "三维旋转采集（3D-DSA）重建", "B": "提高对比剂浓度重复2D造影", "C": "降低矩阵加快采集速度", "D": "延长透视时间观察", "E": "改用静脉DSA替代"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-102", "kp": "3D-DSA动脉瘤评估", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】3D-DSA（三维旋转采集）可从任意角度重建，清晰显示动脉瘤颈及与载瘤动脉的空间关系，是动脉瘤介入评估的标准技术，A正确。\n【为什么错】B提高浓度仅增强显影密度，不能解决角度重叠；C降低矩阵降低分辨率；D透视无三维信息；E静脉DSA显示细节更差。", "tr": "动脉瘤术前评估强调“3D重建看瘤颈”，2D体位无法替代。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1103", "t": "案例分析题", "s": "患者男，60岁，冠心病不稳定型心绞痛，拟在冠脉造影的同时行左心室造影评估左心功能与室壁运动。患者体重70kg，无肾功能异常，既往无造影剂过敏史，心功能分级Ⅱ级。左心室造影需选用合适的导管并设定正确的注射参数，以获得良好的心室显影，同时避免造影剂过量与造影诱发心律失常的风险。关于左心室造影技术参数的叙述，正确的是", "o": {"A": "选用Cobra导管、低流率缓慢注射", "B": "选用猪尾导管，对比剂浓度约370mgI/ml，流率12~15ml/s、总量30~40ml，高帧率采集", "C": "选用微导管手推对比剂", "D": "流率2ml/s缓慢注射", "E": "采集帧率降至1帧/s"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-103", "kp": "左心室造影参数", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】左心室造影用猪尾导管、370mgI/ml对比剂、12~15ml/s流率、30~40ml总量并以高帧率（如25帧/s）采集，可良好显示室壁运动，B正确。\n【为什么错】A、C、D导管或流率不匹配，无法形成有效心室团注；E低帧率无法评估室壁运动。", "tr": "左室造影“猪尾导管＋12~15ml/s大流率＋高帧率”为经典参数组合。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1104", "t": "案例分析题", "s": "患者男，68岁，超声示右侧颈内动脉起始部重度狭窄（约80%），近期反复出现一过性黑矇与头晕，头颅MRI提示右侧大脑半球多发腔隙性梗死，拟行颈动脉支架置入术。患者合并高血压、糖尿病，颈动脉斑块为混合性斑块，术前需充分评估主动脉弓形态及狭窄段斑块情况，以制定安全的手术方案。关于术前及术中DSA技术的正确做法是", "o": {"A": "先行主动脉弓造影了解开口，再选择性颈总动脉造影，路标技术引导导丝通过狭窄段，支架置入后复查造影", "B": "直接经狭窄段置入支架，无需先行造影", "C": "用静脉DSA全程代替动脉造影", "D": "支架置入后立即拔除导管，不需复查", "E": "术前不需行主动脉弓造影，直接选择性插管"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-104", "kp": "颈动脉支架DSA技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】颈动脉支架术前先主动脉弓造影了解开口与走行，再选择性颈总动脉造影评估狭窄，术中路标技术引导导丝安全通过狭窄段，支架置入后复查造影确认，A正确。\n【为什么错】B不造影盲放风险大；C静脉DSA显影差不能满足介入要求；D术后必须复查确认支架与血流；E主动脉弓造影是必要步骤。", "tr": "颈动脉介入“弓上造影—选择性造影—路标引导—术后复查”环环相扣。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1105", "t": "案例分析题", "s": "患者男，70岁，体检发现腹主动脉瘤，直径约5.0cm，位于肾动脉平面以下，可疑累及双侧髂总动脉开口，拟行DSA明确瘤体大小、瘤颈及与肾动脉的关系，为腔内介入治疗做准备。患者有轻度肾功能减退（血肌酐升高），对造影剂肾损伤风险较为敏感，术前已开始预防性水化，需兼顾诊断效果与肾脏安全。关于成像方式选择的正确做法是", "o": {"A": "首选静脉DSA，创伤最小", "B": "优先选择动脉DSA，对比剂用量少、浓度低，可减少肾损伤", "C": "必须使用高浓度对比剂行静脉注射", "D": "静脉DSA与动脉DSA用量相同", "E": "避免使用对比剂，仅行透视检查"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-105", "kp": "肾功能减退成像方式选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】动脉DSA对比剂用量少、浓度低，对肾功能减退者肾损伤更小，应优先选择，B正确。\n【为什么错】A静脉DSA用量大、肾负担重；C、D高浓度大剂量加重肾损伤；E透视不能显示血管腔。", "tr": "肾功能不好选动脉DSA“省药”，与静脉DSA“创伤小但费药”权衡不同。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1106", "t": "案例分析题", "s": "患者女，48岁，因右侧颈内动脉重度狭窄（90%）行颈动脉支架置入术，术程顺利，支架展开良好，术中复查造影血流通畅，无残余狭窄。术后1小时患者突然出现左侧肢体无力、言语不清，NIHSS评分8分，血压平稳，无心悸胸闷，考虑与术中斑块脱落或支架内急性血栓形成有关，需紧急评估处理。此时最可能的并发症及正确处理是", "o": {"A": "属正常术后反应，继续观察", "B": "考虑术中栓塞或支架内血栓致急性缺血性卒中，立即复查DSA评估，必要时动脉内溶栓或取栓", "C": "立即口服阿司匹林后出院", "D": "行头颅平片检查", "E": "嘱患者休息后自行恢复"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-106", "kp": "颈动脉支架围术期卒中处理", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】支架术后急性神经功能缺损提示远端栓塞或支架内急性血栓，应尽快复查DSA明确并争取动脉内溶栓或取栓，B正确。\n【为什么错】A继续观察延误治疗；C擅自出院风险极高；D头颅平片对急性缺血无诊断价值；E等待自行恢复将错失治疗窗口。", "tr": "颈动脉介入围术期卒中“快速复查DSA＋血管内再通”是处理核心。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1107", "t": "案例分析题", "s": "患者女，65岁，2型糖尿病病史10年，合并轻度肾功能不全（血肌酐140μmol/L，eGFR约55ml/min），因下肢动脉硬化闭塞症需行下肢动脉DSA及介入治疗。患者平时服用二甲双胍控制血糖，术前应重点评估造影剂肾损伤风险，并与临床沟通围术期用药方案，评估二甲双胍是否需暂停。为预防对比剂肾病，应采取的正确措施是", "o": {"A": "术前不做任何评估直接造影", "B": "术前充分水化，选用等渗或低渗非离子型对比剂并尽量减量，术后监测肾功能，按医嘱调整二甲双胍用药时机", "C": "使用大剂量高渗离子型对比剂", "D": "术前使用利尿剂脱水以减轻肾脏负担", "E": "术后立即进行剧烈运动促进对比剂排泄"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-107", "kp": "对比剂肾病预防措施", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】高危患者术前应充分水化，选用肾毒性小的等渗或低渗非离子型对比剂并尽量减量，术后监测肾功能，并根据肾功能情况调整二甲双胍用药，B正确。\n【为什么错】A不做评估风险高；C大剂量高渗对比剂加重肾损伤；D利尿脱水反而有害；E剧烈运动无益且有风险。", "tr": "糖尿病＋肾功能不全＝CIN高危，“水化＋减量＋等渗剂”是三大防线。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1108", "t": "案例分析题", "s": "患者男，52岁，乙肝肝硬化病史，增强CT示肝右叶单发肝癌，拟行TACE治疗。术中造影发现肝右叶肿瘤主要由肝右动脉分支供血，需将微导管超选择性插管至肿瘤供血分支，尽量避免损伤正常肝组织。该技术可将造影后的血管路径图叠加于实时透视图像上，实时显示导管导丝与血管的关系。为实时引导导丝、导管准确超选，应采用的DSA技术是", "o": {"A": "路标技术（road mapping）", "B": "能量减影", "C": "混合减影", "D": "单帧静态采集", "E": "心电门控采集"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-108", "kp": "路标技术引导超选", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】路标技术将造影后的血管路径图与实时透视叠加，介入操作中能直观显示导管导丝与血管关系，是超选择性插管的经典引导技术，A正确。\n【为什么错】B、C为诊断用减影方式；D静态图像无实时引导作用；E心电门控用于减少心脏搏动伪影。", "tr": "介入超选引导靠“路标”，路标属时间减影的实时应用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1109", "t": "案例分析题", "s": "患者女，30岁，近期血压明显升高，多种降压药物联合治疗效果差，DSA确诊右肾动脉开口部重度狭窄（约85%），考虑为动脉粥样硬化性病变，药物治疗效果不佳，无明确手术禁忌。拟行经皮肾动脉介入治疗（球囊扩张及必要时置入支架），术中需持续监测血压与肾功能变化，并备好球囊、支架及压力泵等材料。正确的技术方案是", "o": {"A": "先肾动脉造影明确狭窄，再行球囊扩张并必要时置入支架，术后造影复查确认血流通畅", "B": "直接置入支架，不需先行造影", "C": "先行全脑血管造影评估", "D": "支架置入后不需复查造影", "E": "术中不需造影引导，透视下盲放"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-109", "kp": "肾动脉介入技术方案", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】肾动脉介入遵循“造影明确—球囊扩张—必要时支架—术后复查造影”的规范流程，全程造影引导并监测血压，A正确。\n【为什么错】B、E不经造影盲目操作易损伤血管；C脑血管造影与肾动脉病变无关；D术后必须复查确认疗效与并发症。", "tr": "肾动脉介入全程造影引导，支架后复查是疗效确认的必需步骤。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-1110", "t": "案例分析题", "s": "患者男，58岁，骨盆骨折卧床1周后突发呼吸困难、胸痛、低氧血症，D-二聚体显著升高，床旁超声提示右心扩大，高度怀疑急性肺栓塞。因合并严重肾功能不全不宜行CTPA，临床拟行肺动脉造影明确诊断，需经右心系统插管至肺动脉。造影过程应持续心电监护、监测血氧并备好抢救设备，注意患者屏气配合。关于肺动脉造影技术的正确描述是", "o": {"A": "经股静脉右心导管将导管置于肺动脉，高压注射器注射对比剂后快速采像，观察肺动脉腔内充盈缺损", "B": "经股动脉逆行插管至肺动脉", "C": "手推小剂量对比剂即可完成", "D": "不需插管，直接经静脉注射对比剂", "E": "肺动脉造影不能诊断肺栓塞"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-110", "kp": "肺动脉造影技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】肺动脉造影经股静脉右心系统将导管置于肺动脉主干，高压注射器注射对比剂后快速采像，充盈缺损为肺栓塞的直接征象，A正确。\n【为什么错】B动脉途径无法到达肺动脉；C手推小剂量无法使肺动脉良好显影；D不插管则对比剂稀释严重；E肺动脉造影曾是诊断金标准。", "tr": "肺动脉造影＝股静脉右心插管＋高压团注＋高帧率采像。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-9101", "t": "单选题", "s": "目前诊断颅内动脉瘤的\"金标准\"检查是", "o": {"A": "3D-DSA（旋转 DSA 三维重建）", "B": "头颅 CT 平扫", "C": "头颅 MRI 平扫", "D": "颈部血管超声", "E": "颅骨 X 线平片"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "KP-BU-11-9101-副高", "kp": "颅内动脉瘤金标准", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → (补充)脑血管DSA", "ex": "【为什么对】A 正确：DSA（尤其旋转采集的三维 DSA）空间分辨率高、可显示瘤颈与载瘤动脉关系，是诊断颅内动脉瘤的金标准，也是介入栓塞治疗的基础。【为什么错】B、C 对动脉瘤显示有限（CTA/MRA 为无创筛查）；D 无法显示颅内动脉；E 无诊断价值。", "tr": "CTA/MRA 是无创筛查首选，但\"金标准\"仍是 DSA。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "补充", "mk": 0}, {"id": "U11-9102", "t": "单选题", "s": "关于冠状动脉 DSA 的投照角度，下列说法错误的是", "o": {"A": "左前斜（LAO）有助于显示前降支近段", "B": "右前斜（RAO）有助于显示右冠状动脉", "C": "头位（CRAN）有助于显示心尖部", "D": "足位（CAUD）有助于显示膈面心肌", "E": "单纯前后位（AP）即可清晰显示所有冠状动脉分支"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "KP-BU-11-9102-副高", "kp": "冠状动脉DSA投照角度", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → (补充)冠状动脉DSA", "ex": "【为什么对】E 错误：心脏在胸腔内呈斜位，单纯 AP 位各分支相互重叠、显示差，必须结合 LAO/RAO 及头位/足位等多角度投照。【为什么错】A、B、C、D 均为冠状动脉 DSA 常用且正确的投照体位描述。", "tr": "冠脉 DSA 强调多角度投照，单纯 AP 位因重叠而不可用。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "补充", "mk": 0}, {"id": "U11-9103", "t": "单选题", "s": "欲显示股浅动脉远端及腘动脉、小腿动脉，下肢动脉 DSA 的穿刺入路首选", "o": {"A": "对侧股动脉（翻山技术）或同侧顺行穿刺", "B": "肱动脉穿刺", "C": "颈动脉穿刺", "D": "腋动脉穿刺", "E": "足背动脉穿刺"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "KP-BU-11-9103-副高", "kp": "下肢动脉DSA入路", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → (补充)下肢动脉DSA", "ex": "【为什么对】A 正确：经股动脉入路（同侧顺行或对侧\"翻山\"）是下肢动脉 DSA 最常用、最稳妥的路径，导管易于到达股浅、腘及小腿动脉。【为什么错】B 肱动脉常用于上肢/主动脉弓；C、D 不用于下肢；E 太远端、不适合作为造影入路。", "tr": "下肢动脉造影首选股动脉入路，而非肱动脉或颈部入路。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "补充", "mk": 0}, {"id": "U11-9104", "t": "多选题", "s": "关于间接门静脉造影（经动脉门静脉成像）的插管与造影，下列说法正确的有", "o": {"A": "导管置于脾动脉或肠系膜上动脉", "B": "注入对比剂后于门静脉期显示门静脉主干及分支", "C": "可评估门静脉高压的侧支循环", "D": "直接经皮穿刺门静脉", "E": "可用于 TIPS 术前评估"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "KP-BU-11-9104-副高", "kp": "间接门静脉造影", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → (补充)门静脉系统DSA", "ex": "【为什么对】A、B、C、E 正确：间接法将导管置于脾动脉或肠系膜上动脉，注入对比剂后对比剂经毛细血管到达门静脉、在门静脉期显影，可评估门脉高压侧支及 TIPS 适应证。【为什么错】D 错误：直接穿刺门静脉属于直接门静脉造影/穿刺技术，非\"间接\"法。", "tr": "区分\"间接法\"（动脉插管）与\"直接法\"（穿刺门脉）；D 为直接法。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "补充", "mk": 1}, {"id": "U11-9201", "t": "单选题", "s": "DSA 检查中，动脉插管最常选用的入路是", "o": {"A": "股动脉（Seldinger 技术）", "B": "肱动脉切开", "C": "颈内静脉", "D": "桡动脉仅用于采血", "E": "足背动脉"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-9201", "kp": "DSA入路", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术", "ex": "【为什么对】DSA 动脉插管最常用股动脉穿刺（Seldinger 技术），操作简便、血管粗直。\n【为什么错】肱/桡等可作替代但非首选。", "tr": "股动脉Seldinger是最常用DSA入路。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U11-9202", "t": "单选题", "s": "关于 DSA 对比剂注射，正确的是", "o": {"A": "对比剂浓度与流率需依靶血管调整", "B": "所有部位统一高浓度高流率", "C": "流率越低越好", "D": "无需考虑注射器加热", "E": "浓度越低越好"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-9202", "kp": "DSA注药参数", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术", "ex": "【为什么对】DSA 对比剂浓度、总量与流率需根据靶血管粗细与检查部位个体化调整，以获得良好信噪比。\n【为什么错】统一参数会造成过曝或显影不良。", "tr": "DSA注药参数需个体化。", "bk": "副高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0101", "t": "单选题", "s": "图像存档与传输系统（PACS）的基本组成通常不包括下列哪一项", "o": {"A": "数字影像采集设备与采集接口（含 DICOM 网关、胶片数字化仪）", "B": "影像存储与归档子系统（含数据库及分级存储设备）", "C": "承担影像与信息传输的通讯网络与网络设备", "D": "影像显示、后处理与打印输出的各类工作站", "E": "医院财务收费与结算子系统"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-001", "kp": "PACS 的基本组成", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (2)构架与工作流程", "ex": "【为什么对】E 为本题答案。财务收费与结算属于医院信息系统（HIS）的功能模块，不属于 PACS 的组成部分。PACS 与 HIS 之间通过 HL7 等接口交换文本信息，但两者是相互独立又互相集成的系统。【为什么错】A、B、C、D 均为 PACS 的组成要素：影像采集子系统负责把各类成像设备的影像纳入系统（含对非 DICOM 设备的网关转换与旧胶片的数字化）；存储与归档子系统含数据库服务器与在线/近线/离线分级存储；通讯网络是各部分互联的基础；显示与处理工作站是影像调阅、诊断与后处理的终端。此外，系统软件与数据库管理软件通常也被列为 PACS 的组成之一。", "tr": "HIS、RIS、PACS 的功能边界是本单元的基础考点：HIS 管全院业务与费用，RIS 管放射科的登记、预约、报告与流程，PACS 管影像的采集、存储、传输与显示。三者集成但不可混为一谈。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0102", "t": "多选题", "s": "PACS 中数字影像的采集途径包括下列哪些方式", "o": {"A": "通过 DICOM 网络接口从符合 DICOM 标准的成像设备直接接收影像，这是最理想、信息最完整的采集方式", "B": "对仅提供模拟视频输出的老旧设备，使用视频帧捕获卡数字化后再封装为 DICOM 格式", "C": "使用胶片数字化仪（激光扫描或 CCD 扫描）把既往胶片转换为数字影像纳入系统", "D": "通过 DICOM 网关对不完全符合标准的设备做协议转换与信息补全，如补入患者 ID、检查号等", "E": "直接从 HIS 数据库中读取并提取影像像素数据"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-002", "kp": "PACS 数字影像采集方式", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (3)数字影像采集", "ex": "【为什么对】A 正确：设备原生输出 DICOM 对象，像素数据与患者、检查、序列等元数据一并传输，信息最完整、失真最小。B 正确：帧捕获属于\"模拟转数字\"的过渡方案，影像质量受视频链路限制（通常仅 8 bit 灰阶），且元数据需另行补入，只在无法更新设备时采用。C 正确：胶片数字化仪用于既往资料回顾性入库，同样存在动态范围与分辨率损失。D 正确：DICOM 网关（gateway/broker）承担协议适配、字符集转换、标签补全与路由分发职能，是异构环境集成的关键部件。【为什么错】E 错误：HIS 存储的是医嘱、费用、病历文书等文本类结构化信息，不保存影像像素数据；PACS 与 HIS 之间通过 HL7 交换文本信息，影像数据不经由 HIS 流转。", "tr": "采集方式的\"优劣次序\"是命题点：DICOM 直连＞DICOM 网关转换＞帧捕获＞胶片数字化。后两种都存在不可逆的信息损失，只应作为过渡手段。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的发展与组成", "页": 343}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-0103", "t": "单选题", "s": "某院一台 CT 平均每例检查产生 800 幅图像，矩阵 512×512、每像素 16 bit，按不压缩方式存储。若每日完成 60 例 CT 检查，该设备一天产生的影像数据量约为", "o": {"A": "约 0.5 GB", "B": "约 5 GB", "C": "约 25 GB", "D": "约 50 GB", "E": "约 500 GB"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-003", "kp": "PACS 影像存储容量估算", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】C 正确。单幅图像=512×512×2 字节=524288 字节≈0.5 MB；每例 800 幅≈400 MB；每日 60 例≈24000 MB≈23.4 GB，约 25 GB。【为什么错】A 相当于只算了一幅图像的量级。B 相当于漏算了一个数量级（如把 800 幅误作 80 幅）。D 相当于把单幅按 1 MB 估算（即误用 32 bit 或矩阵取 1024×512）。E 高估约 20 倍，与实际相差过大。", "tr": "必须记住几个基准值：CT/MR 单幅 512×512×16 bit≈0.5 MB；CR/DR 单幅（约 2048×2500×16 bit）≈10 MB；数字乳腺单幅可达数十 MB。此外 DICOM 文件还含头信息、且实际容量规划应在纯像素量基础上乘以冗余与增长系数。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的发展与组成", "页": 343}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0104", "t": "多选题", "s": "有关 PACS 影像存储的分级存储管理与预取策略，下列表述正确的有", "o": {"A": "在线存储通常采用高速磁盘阵列（RAID），存放近期与高频调阅的影像，响应速度快", "B": "近线存储采用光盘库、磁带库或低成本大容量磁盘，存放调阅频率较低的历史影像，调阅时需要一定等待时间", "C": "离线存储的介质脱离系统在库房保管，调阅时需要人工装载等干预", "D": "预取机制根据 RIS 的检查预约信息，在患者到达前把其历史影像自近线迁移至在线，以缩短医师调阅等待", "E": "系统采用了 RAID 冗余磁盘阵列后即等同于完成了数据备份，无须再建立异地备份"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-004", "kp": "分级存储管理与影像预取", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (6)影像管理", "ex": "【为什么对】A、B、C 正确：分级存储管理（HSM）按调阅概率把数据分布在不同成本与速度的介质上，在线保证即时调阅，近线兼顾容量与成本，离线用于长期法定保存。D 正确：预取是提升临床体验的关键机制，通过与 RIS 的预约信息联动实现\"人未到、片先到\"，也可按检查部位、时间跨度设置预取规则。【为什么错】E 错误：RAID 解决的是单块（或若干块）磁盘物理损坏时的数据可用性与业务连续性问题，无法防范误删除、逻辑损坏、病毒或勒索软件加密、机房火灾与整体损毁等风险。备份（尤其异地备份与容灾）与 RAID 分属不同层面的保障手段，二者不可互相替代。", "tr": "\"RAID 不等于备份\"是信息安全领域的经典判断。此外要注意，RAID 5 只能容忍一块盘故障，重建期间再坏一块即数据全失，大容量场景更推荐 RAID 6 或 RAID 10。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-0105", "t": "单选题", "s": "有关 PACS 的系统构架与影像业务工作流程，下列描述正确的是", "o": {"A": "典型流程为：RIS 登记预约→设备经 Modality Worklist 获取患者与检查信息→采集图像→经 DICOM 存储服务发送至 PACS 归档→诊断工作站调阅并书写报告→报告回传 RIS 并向临床发布", "B": "浏览器/服务器（B/S）架构的最大优势是能提供最完整的高级三维后处理功能，故诊断工作站宜一律采用 B/S", "C": "集中式存储架构的主要优点在于各科室数据彼此独立、互不影响", "D": "PACS 与成像设备之间的图像传输通常采用 HL7 协议完成", "E": "影像归档完成后，设备端即可自行删除本地原始图像，无须任何确认机制"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-005", "kp": "PACS 系统构架与影像工作流程", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (2)构架与工作流程", "ex": "【为什么对】A 正确。这正是 IHE 预约工作流（SWF）所规范的标准影像业务链条，从患者登记、工作列表获取、图像采集与归档，到报告书写与发布形成闭环，各环节分别由 HL7 与 DICOM 事务衔接。【为什么错】B B/S 架构的价值在于免客户端安装、维护成本低、便于临床科室与移动终端广泛访问；高性能三维后处理与高负荷诊断阅片仍多依赖 C/S 专业工作站或服务器端渲染的胖客户端方案。C \"各科室数据彼此独立\"是分布式/科室级存储的特征，且往往形成信息孤岛，并非优点；集中式存储的优点恰恰是统一管理、便于共享、备份与统计。D 图像传输使用 DICOM 协议；HL7 用于 HIS/RIS 与 PACS 之间的患者、医嘱、报告等文本类信息交换。E 应通过存储确认（Storage Commitment）服务取得 PACS 明确的\"已永久保存\"应答后，设备端才可安全删除本地副本，否则存在数据丢失风险。", "tr": "\"DICOM 传图像、HL7 传文本、IHE 定流程\"是本单元三大标准的分工口诀，D 项正是利用这一分工设陷。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的发展与组成", "页": 343}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0106", "t": "案例分析题", "s": "某医院新建放射科拟接入院内 PACS，科室配置 2 台 CT、1 台 MR 与 4 台 DR。经测算，业务高峰时段（上午 9:00—11:00）平均每分钟需向 PACS 中心服务器上传约 900 MB 影像数据，同时诊断医师从服务器调阅历史影像的流量约为上传流量的一半。信息科需评估科室接入交换机的上联链路带宽是否足够。已知 1 字节=8 比特，且工程实践中链路的实际可用带宽通常只有理论带宽的 60%～70%。下列估算与结论最合理的是", "o": {"A": "高峰期总流量约 1350 MB/min，折合净需求约 180 Mbps；计入链路利用率后需约 260～300 Mbps 以上，千兆以太网上联可满足，百兆链路明显不足", "B": "高峰期净需求约 18 Mbps，百兆链路绰绰有余", "C": "高峰期净需求约 1350 Mbps，必须部署万兆链路才能满足", "D": "带宽需求只与联网设备数量相关，与数据量无关，4 台 DR 用百兆链路即可", "E": "只要对影像采用有损压缩，任何带宽都能满足需求，无须做评估"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-006", "kp": "PACS 网络带宽需求估算", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (4)通讯与网络", "ex": "【为什么对】A 正确。上传 900 MB/min 加下行调阅 450 MB/min，合计 1350 MB/min；换算为比特：1350×8=10800 Mb/min，除以 60 s 得 180 Mb/s（Mbps）。工程上按 60%～70% 的有效利用率折算，链路理论带宽需约 257～300 Mbps 以上，因此百兆（100 Mbps）链路不足，千兆（1000 Mbps）链路有充分余量，也为业务增长留出空间。【为什么错】B 少算了字节到比特的 8 倍换算。C 漏除以 60 s，把每分钟的比特数当成了每秒的速率。D 带宽需求由单位时间内传输的数据量决定，设备数量只是间接因素；4 台 DR 若并发上传，单幅约 10 MB 的图像同样可迅速占满百兆链路。E 诊断用影像原则上应采用无损压缩，有损压缩需经严格论证且不能作为规避带宽规划的理由；压缩也不改变必须做容量评估这一工程原则。", "tr": "\"MB/s 与 Mbps 差 8 倍\"\"每分钟与每秒差 60 倍\"是带宽计算题的两个经典陷阱，两处都错就会得出相差 480 倍的荒谬结论。此外规划时还应考虑突发峰值、备份流量与冗余链路。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0107", "t": "单选题", "s": "下列关于远程放射学（teleradiology）的描述，正确的是", "o": {"A": "远程放射学指通过通讯网络把影像资料由一地传送至另一地进行显示、会诊或书写报告，按工作方式可分为实时（在线）与存储转发（离线）两类", "B": "远程放射学只能用于疑难病例会诊，不能用于常规报告书写", "C": "远程放射学传输的图像可以不遵循 DICOM 标准，只要能在远端显示即可", "D": "远程放射学在本机构内部网络中进行，不涉及患者隐私保护问题", "E": "远程放射学的诊断质量取决于传输速度，与远端显示终端性能无关"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-001", "kp": "远程放射学的定义与分类", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】A 正确。远程放射学是远程医学在影像领域的应用，基本要素包括影像采集与数字化、传输网络、远端显示与诊断，以及信息安全保障。实时方式适合互动式会诊与术中即时判读，存储转发方式适合非急诊的批量报告，二者各有适用场景。【为什么错】B 远程放射学已广泛用于夜间值班、区域影像中心集中报告、基层机构报告外包与专科会诊，远不止疑难会诊。C 为保证像素数据、灰阶信息与患者元数据的完整性和跨系统互操作性，远程放射学应遵循 DICOM 标准传输与存储。D 只要涉及患者身份与影像数据的传输就存在隐私风险，无论院内院外都需加密传输、访问控制、审计留痕，对外交流还应做去标识化。E 远端显示器的分辨率、最大亮度、灰阶校准（DICOM GSDF）与阅片环境照度直接决定诊断可靠性，是远程放射学质量控制的关键环节。", "tr": "远程放射学的质量控制常被简化为\"网速够快就行\"。实际上\"传输链路+显示终端+阅片环境+资质与责任界定\"四个环节缺一不可，显示终端未做 GSDF 校准是最常被忽略的隐患。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0108", "t": "多选题", "s": "为保障 PACS 的系统安全与患者信息安全，下列措施中恰当的有", "o": {"A": "划分网络安全域，在 PACS 与外部网络之间部署防火墙，远程访问采用 VPN 加密通道", "B": "实行基于角色的权限管理，启用强口令策略与登录审计，对关键操作保留审计日志", "C": "建立数据备份与容灾体系，重要数据实施异地备份，并定期开展恢复演练", "D": "用于科研、教学与对外交流的影像先做去标识化处理，清除患者身份相关的 DICOM 标签", "E": "为便于科室内快速调阅，可让全科工作人员共用一个具有最高权限的账号登录系统"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-002", "kp": "PACS 系统安全与隐私保护措施", "ch": "十二、PACS技术 → 2.PACS运行 → (3)系统安全", "ex": "【为什么对】A 正确：网络分域与边界防护是防止外部攻击与横向渗透的基础。B 正确：最小权限原则与可追溯的审计日志是医疗信息系统安全管理的核心要求。C 正确：备份的价值只有在成功恢复时才体现，未经演练的备份不能视为有效备份。D 正确：去标识化应清除或替换患者姓名、ID、出生日期、机构信息等标签，同时注意\"烧录\"在像素中的文字信息也需处理。【为什么错】E 错误：共用高权限账号使所有操作无法追溯到具体责任人，审计日志形同虚设；一旦口令泄露即造成全系统暴露，严重违反最小权限原则与可追溯性要求，也不符合信息安全等级保护的基本规定。", "tr": "去标识化容易遗漏两处：一是超声、DSA 等设备把患者信息\"烧录\"进像素数据；二是私有标签与结构化报告中残留的身份信息。仅清空 Patient Name 标签并不等于完成匿名化。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-0109", "t": "案例分析题", "s": "某院 PACS 上线后，技师反映部分检查在诊断工作站上出现\"同一患者被拆成两条记录\"或\"图像挂到了另一位患者名下\"。排查发现：急诊患者常先以临时 ID 完成检查、事后再补录正式住院号；部分设备未接入检查工作列表，技师需在设备控制台手工输入姓名与 ID，存在录入差错；另有一台老设备的检查号编码规则与 RIS 不一致。作为科室技术骨干，需要提出系统性整改方案。下列措施组合最恰当的是", "o": {"A": "全面接入 Modality Worklist 使设备自动从 RIS 获取患者与检查信息以取代手工录入；建立主患者索引并规范临时 ID 向正式 ID 的合并流程；统一各设备的检查号与 AE 配置规则；对已产生的错挂影像使用 PACS 的患者/检查信息核对与合并功能（对应 IHE 患者信息核对流程）予以纠正", "B": "要求技师手工录入时更加仔细，通过加强责任心教育解决即可", "C": "把所有出错的检查记录直接删除，通知患者重新来院检查", "D": "在诊断工作站上人工修改图像中显示的患者姓名文字标注，使之与病历一致", "E": "关闭 Modality Worklist，全部改为手工录入，以保证各设备录入口径一致"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-003", "kp": "HIS/RIS/PACS 集成与患者信息一致性", "ch": "十二、PACS技术 → 2.PACS运行 → (4)与HIS/RIS集成", "ex": "【为什么对】A 正确。患者信息错误的根源有三：手工录入、临时身份未合并、编码规则不统一，整改必须同时覆盖。Modality Worklist 让设备从 RIS 拉取权威的患者与检查信息，从源头消除手工录入差错；主患者索引（MPI）与临时 ID 合并流程解决同一患者多身份问题；统一 AE 与检查号规则保证影像正确归位；对存量错误则使用 PACS 的信息核对与合并功能修正，这一场景正对应 IHE 的患者信息核对（PIR）集成模式。【为什么错】B 手工录入差错是流程性缺陷而非单纯态度问题，仅靠教育无法根治，也无法解决临时 ID 与编码不一致。C 删除后重新检查使患者承受额外辐射与费用，且属可修复的信息层面问题，不应以重复检查作为解决手段。D 修改显示层的文字标注不改变 DICOM 标签与数据库记录，属于掩盖问题，还可能造成图像与记录不符的医疗风险。E 方向完全相反，关闭工作列表会使手工录入差错进一步增加。", "tr": "Modality Worklist 的核心价值不是\"省事\"，而是保证患者身份与检查信息的唯一权威来源。凡遇到\"患者信息错乱\"类案例题，首选答案基本都指向 MWL 接入与主索引管理。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0110", "t": "单选题", "s": "某院在制定 PACS 灾难恢复方案时明确要求：系统中断后最长 4 小时内须恢复业务，且最多允许丢失 15 分钟的数据。这两项要求分别对应的指标是", "o": {"A": "RTO=4 小时、RPO=15 分钟；RTO 决定恢复速度与备用系统就绪程度，RPO 决定数据同步或备份的频率", "B": "RPO=4 小时、RTO=15 分钟", "C": "两者都属恢复时间目标，分别为上限值与下限值", "D": "两者都属平均无故障时间（MTBF）指标", "E": "两者与备份策略无关，只是管理层提出的口号"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-004", "kp": "RTO 与 RPO 在 PACS 灾备中的应用", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】A 正确。恢复时间目标（RTO）指从系统中断到业务恢复可容忍的最长时间，直接决定备用系统采用热备、温备还是冷备；恢复点目标（RPO）指可容忍丢失的数据所对应的时间跨度，RPO=15 分钟意味着数据复制或增量备份间隔不得超过 15 分钟，通常需要近实时的数据同步机制。两项指标共同决定灾备架构的技术路线与投入规模。【为什么错】B 两个概念被完全对调。C RTO 与 RPO 是两个不同维度的指标，一个针对恢复时间、一个针对数据丢失量，不是同一指标的上下限。D MTBF 描述设备硬件的可靠性水平，与灾难恢复目标无关。E RTO 与 RPO 是可量化、可验收、可通过演练验证的技术指标，是灾备方案设计与招标的核心依据。", "tr": "区分口诀：RTO 看\"多久能用\"（时间维度），RPO 看\"丢多少数据\"（数据维度）。RPO 越小对同步频率与带宽要求越高，RTO 越小对备用资源投入要求越高，二者都会显著推高成本，需按业务重要性分级设定。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0111", "t": "多选题", "s": "某台新安装的 DR 无法将图像发送至 PACS，控制台提示\"关联建立失败\"。下列排查思路与操作正确的有", "o": {"A": "先用 C-ECHO（验证服务）测试双方能否建立 DICOM 关联，这是最基本的连通性验证手段", "B": "核对双方配置的 AE Title、IP 地址与端口号是否完全一致（AE Title 区分大小写），并确认 PACS 端已把该设备的 AE Title 加入允许列表", "C": "检查关联协商时双方是否存在共同支持的表示上下文，即所需 SOP Class 与传输语法是否匹配，可查阅厂商的 DICOM 一致性声明加以核对", "D": "检查防火墙是否放行所用的 DICOM 端口，以及网络路由与 VLAN 划分是否可达", "E": "DICOM 关联建立失败通常由 HL7 消息格式错误引起，应优先检查 HL7 接口的字段与分隔符配置"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-005", "kp": "DICOM 通讯故障的排查思路", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】A 正确：C-ECHO 只验证关联能否建立与基本响应，开销小、干扰小，是排查的第一步。B 正确：AE Title 是 DICOM 应用实体的逻辑标识（长度不超过 16 个字符且区分大小写），必须与 IP、端口三者配套一致，且服务端通常按 AE Title 做访问控制。C 正确：即使网络通、AE 配对正确，若双方在关联协商中找不到共同的抽象语法（SOP Class）与传输语法组合，关联仍会被拒绝；一致性声明是判断能否互通的权威依据。D 正确：DICOM 常用端口（如 104、11112）被防火墙拦截或跨 VLAN 不可达，都会表现为关联失败。【为什么错】E 错误：图像发送走的是 DICOM 上层协议（DIMSE over TCP/IP），与 HL7 无关。HL7 负责 HIS/RIS 与 PACS 之间的文本类信息交换，其故障表现为患者信息、医嘱或报告不同步，而不会导致 DICOM 关联建立失败。", "tr": "排查次序应\"由下而上\"：物理与 IP 连通（ping）→端口可达（telnet）→DICOM 关联（C-ECHO）→表示上下文匹配（一致性声明）→具体服务（C-STORE）。跳过前面的层次直接怀疑应用层配置往往事倍功半。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U12-0112", "t": "单选题", "s": "医用诊断级灰阶显示器的质量控制中，用于规范其亮度响应特性的 DICOM 标准部分及相应函数是", "o": {"A": "DICOM PS3.14 所定义的灰度标准显示函数（GSDF），使显示器在全亮度范围内实现视觉上近似均匀的灰阶感知", "B": "DICOM PS3.3 所定义的信息对象定义（IOD）", "C": "DICOM PS3.4 所定义的服务类规范", "D": "DICOM PS3.10 所定义的介质存储与文件格式", "E": "DICOM PS3.15 所定义的安全与系统管理配置"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-006", "kp": "医用显示器与 DICOM GSDF 校准", "ch": "十二、PACS技术 → 2.PACS运行 → (1)管理", "ex": "【为什么对】A 正确。DICOM PS3.14 定义的灰度标准显示函数以人眼对比敏感度模型为基础，把数字驱动值映射为显示亮度，使相邻灰阶之间的亮度差在整个动态范围内对应大致相等的\"恰可察觉差\"，从而保证同一幅图像在不同显示器上具有一致的视觉表现。诊断级显示器须用光度计定期做 GSDF 一致性校准，并检查最大亮度、亮度均匀性、暗室反射与环境照度。【为什么错】B PS3.3 规定各类信息对象（如 CT Image IOD、MR Image IOD）的数据结构。C PS3.4 规定各服务类（存储、查询/检索、打印管理等）的行为。D PS3.10 规定 DICOM 文件格式与介质存储（含 128 字节前导与\"DICM\"标识）。E PS3.15 规定安全配置文件与系统管理。上述各部分内容均与灰阶显示函数无关。", "tr": "PS3.14 是与技师日常工作最相关的 DICOM 部分之一。要点记忆：GSDF 保证\"跨显示器一致\"，而非\"图像更亮更好看\"；未经校准的显示器即使亮度很高，低对比病灶仍可能被漏诊。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0113", "t": "单选题", "s": "有关 DICOM 标准的起源与发展历程，下列描述正确的是", "o": {"A": "DICOM 由美国放射学会（ACR）与美国国家电气制造商协会（NEMA）联合制定，前身为 ACR-NEMA 1.0 与 2.0；1993 年发布的 3.0 版引入网络传输与面向对象的信息模型，此后以增补件形式持续更新", "B": "DICOM 由国际标准化组织（ISO）独立制定，第一版发布于 1985 年并沿用至今未作修改", "C": "DICOM 3.0 仅规定医学图像的文件格式，不涉及网络通讯内容", "D": "DICOM 与 HL7 是同一组织制定的同一套标准的两个组成部分", "E": "DICOM 标准自 3.0 版发布后即处于冻结状态，不再新增内容"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-001", "kp": "DICOM 标准的起源与版本演进", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确。为解决不同厂家设备影像格式互不兼容的问题，ACR 与 NEMA 于 1983 年成立联合委员会，1985 年发布 ACR-NEMA 1.0、1988 年发布 2.0（均基于点对点专用连接），1993 年发布 DICOM 3.0，确立了基于 TCP/IP 的网络通讯、面向对象的信息模型（IOD）与服务-对象对（SOP）机制，并采用多部分文档结构，以增补件（Supplement）与勘误件（CP）方式持续演进。【为什么错】B DICOM 由 ACR 与 NEMA 主导制定，并非 ISO 独立制定；且标准一直在更新。C DICOM 3.0 的核心突破恰恰是网络通讯部分（PS3.7、PS3.8），文件格式（PS3.10）只是其中一部分。D HL7 由独立的 Health Level Seven International 组织制定，与 DICOM 是两套面向不同信息类型的标准，虽有协作但并非同一套标准。E DICOM 一直在增补新的 SOP Class、传输语法与工作流内容（如结构化报告、剂量报告、增强多帧对象、全片数字病理等），从未冻结。", "tr": "记住时间轴：1985 年 ACR-NEMA 1.0、1988 年 2.0、1993 年 DICOM 3.0。命题常把 1985 年说成 DICOM 首版发布年份，或把制定组织换成 ISO/IEC/WHO 等设陷。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0114", "t": "多选题", "s": "关于 DICOM 主要服务类及其功能的对应关系，下列表述正确的有", "o": {"A": "C-STORE 用于把影像等 SOP 实例由服务类用户（SCU）传送到服务类提供者（SCP），是影像归档与转发的基础", "B": "C-FIND 用于按患者、检查、序列、图像四级层次查询符合条件的记录；C-MOVE 用于请求把指定对象发送到第三方目的应用实体", "C": "C-ECHO 属验证服务类，用于测试通讯双方能否建立 DICOM 关联，俗称\"DICOM ping\"", "D": "存储确认（Storage Commitment）用于由存储方向发送方确认对象已被永久保存，发送方据此可安全删除本地副本", "E": "Modality Worklist 用于设备在检查完成后向 RIS 报告检查已开始或已结束的执行状态"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-002", "kp": "DICOM 服务类与 DIMSE 服务", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确：C-STORE 是存储服务类的核心操作，设备发送图像、PACS 接收归档即由其完成。B 正确：C-FIND 实现分层查询，C-MOVE 由请求方指定目的 AE、由被请求方发起 C-STORE 把数据送达第三方（若要求送回请求方自身则用 C-GET）。C 正确：C-ECHO 只做关联与响应验证，是安装调试与故障排查的首选工具。D 正确：存储确认解决\"发出去的图像是否被可靠归档\"的问题，是设备端安全清理本地存储的前提。【为什么错】E 错误：向 RIS 报告检查开始、完成或终止等执行状态的是 MPPS（Modality Performed Procedure Step，已执行检查步骤）服务；Modality Worklist（MWL）则是设备在检查前从 RIS/PACS 查询获取当日预约患者与检查信息的服务。二者一前一后配合构成完整工作流，功能不可互换。", "tr": "MWL 与 MPPS 的\"前后关系\"是高频考点：MWL 在检查前\"取任务\"，MPPS 在检查中与检查后\"报状态\"。另需分清 C-MOVE 与 C-GET：前者数据在新建的关联中送往第三方，后者在同一关联内返回给请求方。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-0115", "t": "单选题", "s": "就 DICOM 中信息对象定义（IOD）、SOP Class、SOP Instance、UID 与 AE Title 之间的关系而言，下列描述正确的是", "o": {"A": "IOD 是对现实世界对象的抽象数据模型；SOP Class 由 IOD 与 DIMSE 服务组合而成并以 SOP Class UID 标识其类型；每个具体对象（如一幅图像）则由全局唯一的 SOP Instance UID 标识", "B": "SOP Class UID 与 SOP Instance UID 含义相同，在配置时可以互相替代", "C": "UID 可由使用者自行编写任意字符串，只要在本院范围内不重复即可", "D": "AE Title 是设备 IP 地址的另一种书写形式，配置时二者取其一即可", "E": "IOD 所描述的是 DICOM 网络通讯协议的分层结构"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-003", "kp": "IOD、SOP Class/Instance、UID 与 AE Title", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确。DICOM 采用面向对象思想：IOD 规定某类现实对象（患者、检查、CT 图像等）应包含哪些模块与属性；把 IOD 与作用于其上的 DIMSE 服务（如存储、查询）配对即构成服务-对象对类（SOP Class），用 SOP Class UID 标识类型，例如 CT 图像存储对应 1.2.840.10008.5.1.4.1.1.2；每一次生成的具体对象则获得一个全球唯一的 SOP Instance UID，用于唯一定位该实例。【为什么错】B 两者层级不同：同一类的成千上万幅图像共享同一个 SOP Class UID，而各自拥有互不相同的 SOP Instance UID，不可互换。C UID 要求全球唯一，由注册获得的组织根 UID 加机构自定义后缀构成，只允许数字与小数点、总长不超过 64 个字符，其中 1.2.840.10008 为 DICOM 标准专用根，不得自行占用。D AE Title 是应用实体的逻辑名称（不超过 16 个字符、区分大小写），与 IP 地址、端口号共同构成 DICOM 通讯三要素，三者缺一不可。E 网络通讯的分层与协议由 PS3.7（消息交换）与 PS3.8（网络支持）规定，IOD 描述的是信息对象的属性构成。", "tr": "DICOM 的四级信息层次\"患者-检查-序列-实例\"与 UID 的层次相对应：Study Instance UID、Series Instance UID、SOP Instance UID 逐级唯一。把 SOP Class UID 误当作可用于定位单幅图像的标识，是本考点最典型的错误。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0116", "t": "案例分析题", "s": "某院新增一台 MR 设备并接入 RIS 的检查工作列表。上线后技师反映两个问题：其一，在设备控制台按\"患者姓名\"查询时经常查不到已登记的患者，但改按\"检查日期\"查询则可看到当天全部预约；其二，部分从工作列表选取患者并完成的检查，RIS 中的检查状态仍停留在\"已预约\"，未自动变为\"已完成\"，需人工干预。设备与 PACS 之间的图像存储与归档一切正常。作为科室技术骨干，对这两个问题的分析与处理，下列最恰当的是", "o": {"A": "前者多为查询关键字匹配问题（中文字符集协商不一致、姓名书写格式差异或通配符使用不当），应核对双方字符集配置与查询条件设置；后者提示设备未启用或未正确配置 MPPS 服务，应开通 MPPS 并与 RIS 完成对接调试", "B": "两个问题均由网络带宽不足引起，应先升级科室上联链路", "C": "两个问题均因 PACS 存储空间不足所致，应优先扩容磁盘阵列", "D": "前者应关闭工作列表改为手工录入解决；后者只能靠技师在 RIS 中手工点击\"完成\"，没有技术手段可用", "E": "两者均由传输语法不匹配引起，把双方统一改为隐式 VR 小端传输语法即可解决"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-004", "kp": "Modality Worklist 与 MPPS 工作流问题排查", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确。按日期能查到、按姓名查不到，说明网络连通与 MWL 服务本身正常，问题出在查询关键字的匹配环节：常见原因是设备与 RIS 之间的特定字符集（如 GB18030/ISO_IR 100 等）协商不一致导致中文姓名乱码或不匹配、姓名分隔符与书写格式差异，以及未使用通配符做模糊匹配。第二个问题是典型的 MPPS 缺失表现——MWL 只负责\"取任务\"，检查开始与完成的状态回报需要 MPPS 服务，未配置时 RIS 自然无法自动更新状态。【为什么错】B 带宽不足会表现为传输缓慢或超时，而非按某一字段查不到、状态不回传，且题干明确图像归档正常。C 存储空间不足会导致归档失败或告警，与工作列表查询和状态回传无关。D 关闭工作列表会重新引入手工录入差错，方向错误；状态回传恰恰有成熟的 MPPS 技术方案可用。E 传输语法不匹配会导致关联协商失败或图像无法存储，而本例图像存储正常，可排除。", "tr": "MWL 与 MPPS 常被混为\"工作列表功能\"。实际招标与验收时应分别列明：设备须支持 MWL SCU（取任务）与 MPPS SCU（报状态），只支持前者会造成 RIS 流程状态长期依赖手工维护。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0117", "t": "多选题", "s": "涉及 DICOM 传输语法、图像压缩与介质交换的下列表述中，正确的有", "o": {"A": "传输语法规定数据元素的字节序、值表示（VR）为显式或隐式以及像素数据的编码方式，其中隐式 VR 小端（1.2.840.10008.1.2）是默认传输语法", "B": "JPEG Lossless 与 JPEG 2000 无损模式属无损压缩，解压后像素与原始数据完全一致，压缩比一般约为 2:1～3:1", "C": "JPEG 2000 有损模式可获得更高压缩比，但造成不可逆的信息损失，用于诊断存档须经严格论证", "D": "用于介质交换（CD/DVD/U 盘）的 DICOM 数据集在介质根目录设有 DICOMDIR 文件，按患者-检查-序列-图像四级层次索引介质中的对象", "E": "通讯双方只要网络可达即可直接传输压缩图像，无须在关联协商阶段就传输语法达成一致"}, "d": "难", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-005", "kp": "DICOM 传输语法、压缩方式与 DICOMDIR", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确：隐式 VR 小端是所有 DICOM 实现都必须支持的默认传输语法，因而是协商失败时可退回的\"最小公分母\"；显式 VR 小端为 1.2.840.10008.1.2.1。B 正确：无损压缩保证像素完全可逆，医学影像因噪声成分较多，无损压缩比通常有限。C 正确：有损压缩可达 10:1 以上，但属不可逆处理，是否用于诊断与长期存档须结合部位、诊断任务与法规要求论证，一般原则是诊断用图像优先采用无损压缩。D 正确：DICOMDIR 采用介质存储目录存储 SOP Class，为离线介质提供层次化索引，使阅读软件无须扫描全部文件即可列出内容。【为什么错】E 错误：DICOM 建立关联时必须协商表示上下文（抽象语法即 SOP Class，加上一个或多个传输语法）；若接收方不支持发送方使用的压缩传输语法，该表示上下文会被拒绝，此时需退回到双方共同支持的传输语法，或由网关做转码后再转发。", "tr": "\"网络通了就一定能传图\"是常见误判。传输语法协商失败是临床上排查 DICOM 互通问题的高频原因，尤其在一端使用 JPEG 2000 压缩而另一端只支持非压缩语法时，必须查阅一致性声明确认交集。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U12-0118", "t": "单选题", "s": "有关 HL7 标准的下列描述中，正确的是", "o": {"A": "HL7 是面向 OSI 参考模型第七层（应用层）的医疗信息交换标准，主要用于患者管理、医嘱、检验与报告等文本类信息交换；其 v2.x 消息由段、字段、组分构成，以竖线等分隔符分隔，MSH 为消息头段", "B": "HL7 的主要用途是医学图像的存储与网络传输", "C": "HL7 名称中的\"7\"指该标准由 7 个部分组成", "D": "HL7 与 DICOM 的功能完全重叠，医院只需部署其中一种即可", "E": "HL7 v2.x 采用 XML 格式编码，v3 则采用竖线分隔的纯文本格式"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-HL7-001", "kp": "HL7 标准的定位与消息结构", "ch": "十二、PACS技术 → 3.国际标准与规范 → (1)HL7", "ex": "【为什么对】A 正确。HL7 由 Health Level Seven International 组织制定，聚焦应用层的语义互操作。常用消息类型包括患者管理 ADT、医嘱 ORM、结果 ORU 等；v2.x 采用分隔符编码，一条消息由若干段组成，每段以三字母段标识开头（MSH 消息头、PID 患者标识、OBR 检查申请、OBX 观察结果等）。【为什么错】B 影像的存储与传输由 DICOM 承担，HL7 传递的是与影像相关的文本类信息。C \"Level Seven\"指 OSI 模型的第七层即应用层，与标准的部分数量无关。D 二者面向不同的信息类型、互为补充，PACS 环境中通常同时使用：HL7 完成 HIS/RIS 与 PACS 的信息同步，DICOM 完成影像的采集、传输与归档。E 描述颠倒：v2.x 以竖线分隔的纯文本编码为主（亦有可选的 XML 编码），v3 基于参考信息模型并采用 XML；新一代 FHIR 采用 REST 风格接口与 JSON/XML 资源表达。", "tr": "\"HL7 传文本、DICOM 传影像、IHE 定流程\"是本单元最实用的记忆框架。凡题干出现\"图像传不过去\"就应指向 DICOM，出现\"患者信息或申请单不同步\"才指向 HL7。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0119", "t": "多选题", "s": "下列关于 IHE（集成医疗企业）的表述，正确的有", "o": {"A": "IHE 由北美放射学会（RSNA）与美国医疗信息与管理系统学会（HIMSS）于 1998 年共同发起，旨在推动医疗信息系统之间的互操作", "B": "IHE 本身不制定新的通讯标准，而是规范如何组合运用 DICOM、HL7 等既有标准来解决具体的临床集成需求", "C": "IHE 技术框架的核心概念包括角色（Actor）、事务（Transaction）与集成模式（Integration Profile）", "D": "厂商可通过参加 IHE 连接测试（Connectathon）验证其产品与其他厂商系统的互操作性，并对外发布集成声明", "E": "IHE 属强制性国家标准，医疗机构采购设备时须符合其全部集成模式"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-IHE-001", "kp": "IHE 的性质、组织与核心概念", "ch": "十二、PACS技术 → 3.国际标准与规范 → (3)IHE", "ex": "【为什么对】A 正确：IHE 最初从放射学领域发起，后扩展到心血管、检验、护理、公共卫生等多个领域。B 正确：这是 IHE 与 DICOM、HL7 最本质的区别——它是\"标准的用法说明书\"，通过明确在何种场景下由哪个角色发起哪个事务，消除同一标准被不同厂商各自解读所造成的不兼容。C 正确：角色定义系统承担的功能职责，事务定义角色间基于标准的信息交换，集成模式则把若干角色与事务组织起来解决一个完整的临床问题。D 正确：Connectathon 是多厂商同场互连测试活动，通过后厂商可发布 IHE 集成声明，供医疗机构在采购时核查。【为什么错】E 错误：IHE 是行业自愿性的互操作框架，不具备强制法律效力；医疗机构应根据自身业务需要，在招标文件中明确要求支持哪些具体集成模式与角色，而非笼统要求\"符合全部\"。", "tr": "\"IHE 不制定标准\"是必考判断点。命题常写成\"IHE 制定了新的影像传输标准\"或\"IHE 取代了 DICOM\"来设陷，识别关键在于把握其\"整合既有标准\"的定位。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-0120", "t": "单选题", "s": "IHE 放射科的预约工作流（Scheduled Workflow，SWF）集成模式规范了影像检查自登记到归档的完整链条，下列描述正确的是", "o": {"A": "SWF 涉及的角色包括患者登记（ADT）、医嘱下达者、医嘱执行者（RIS）、采集设备、影像管理与影像归档、影像显示等；其中患者与医嘱信息交换主要基于 HL7 消息，而工作列表查询、图像存储与存储确认基于 DICOM 服务", "B": "SWF 完全基于 HL7 实现，全过程不使用 DICOM 服务", "C": "SWF 的主要作用是规定影像的压缩算法与归档介质类型", "D": "SWF 仅适用于放射科内部流程，与患者登记（ADT）环节无关", "E": "实现 SWF 要求医院各系统必须采购自同一家厂商的产品"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-IHE-002", "kp": "IHE 放射科预约工作流 SWF", "ch": "十二、PACS技术 → 3.国际标准与规范 → (3)IHE", "ex": "【为什么对】A 正确。SWF 是 IHE 放射领域最基础、最核心的集成模式，把患者登记、医嘱下达、检查预约、工作列表获取、检查执行与状态回报、图像存储与存储确认、影像调阅等环节串成闭环。其中患者身份与医嘱类事务由 HL7 承担，工作列表（MWL）、执行步骤（MPPS）、图像存储（C-STORE）与存储确认（Storage Commitment）等由 DICOM 承担，两类标准在同一流程中分工协作。【为什么错】B 与事实不符，SWF 中的影像相关事务全部基于 DICOM。C 压缩算法与传输语法由 DICOM 规定，介质与归档策略属系统实现与管理层面，均非 SWF 的规范对象。D 患者登记（ADT）正是 SWF 的起点角色，保证患者身份在全流程中的一致性。E 恰恰相反，SWF 的价值就在于让不同厂商的系统按统一约定协同工作，避免被单一厂商锁定。", "tr": "SWF 的记忆抓手是\"一条流水线、两套标准\"：HL7 管人和医嘱、DICOM 管图像和执行状态。此外与 SWF 常配套出现的还有患者信息核对（PIR）、一致性图像显示（CPI）、关键图像标注（KIN）与放射剂量报告（REM）等模式。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0121", "t": "单选题", "s": "PACS 在影像部门内部的主要应用价值，不包括下列哪一项", "o": {"A": "实现影像的数字化存储与快速调阅，显著减少胶片管理与借阅工作量", "B": "支持多屏对比、历史检查自动调取与三维后处理，提高诊断效率与一致性", "C": "与 RIS 集成实现登记、分诊、检查、报告、审核的全流程闭环管理", "D": "便于统计检查工作量、报告周转时间、阳性率等运行与质量指标", "E": "直接提高成像设备探测器的量子探测效率，从而降低受检者的辐射剂量"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-001", "kp": "PACS 在影像部门的应用价值", "ch": "十二、PACS技术 → 4.PACS临床应用 → (1)影像部门", "ex": "【为什么对】E 为本题答案。量子探测效率是探测器材料、结构与读出电路决定的物理性能指标，属成像设备硬件范畴；PACS 是影像信息的存储、传输与管理系统，不参与成像过程，也就不可能改变 DQE。需要说明的是，PACS 可通过减少重复检查、汇集剂量结构化报告（RDSR）支持剂量监测与分析，从管理层面间接助益剂量优化，但这与\"直接提高 DQE\"是两回事。【为什么错】A、B、C、D 均为 PACS 在影像科的确切价值：数字化存储替代胶片库房与人工借还；工作站的多屏、多序列同步对比与历史检查自动调取显著提升阅片效率；与 RIS 集成形成流程闭环并减少信息断点；系统日志与结构化数据为科室运行分析与质控指标统计提供基础。", "tr": "本题的判别要点是区分\"信息系统能力\"与\"成像物理性能\"。凡选项把 PACS 说成能改善分辨率、DQE、噪声等成像链物理指标，基本可判为错误。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0122", "t": "多选题", "s": "PACS 向临床科室延伸后所带来的价值，包括下列哪些方面", "o": {"A": "临床医师可在病房、门诊与手术室随时调阅患者影像与报告，无须等待胶片传递", "B": "手术与介入操作过程中可实时参考术前影像，支持术中定位与方案调整", "C": "多学科会诊时可同屏展示同一患者不同时期、不同模态的影像，便于疗效对比与联合决策", "D": "影像资料可与电子病历集成形成完整临床数据链，支持教学查房与科研回顾性研究", "E": "临床医师可在 PACS 上直接修改影像科已审核发布的诊断报告内容"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-002", "kp": "PACS 在临床部门的应用价值", "ch": "十二、PACS技术 → 4.PACS临床应用 → (2)临床部门", "ex": "【为什么对】A 正确：影像\"随处可及\"是 PACS 对临床最直观的改变，显著缩短了从检查完成到临床决策的时间。B 正确：手术室工作站与介入导管室调阅术前影像已成常规，部分场景还可与导航、融合影像技术结合。C 正确：跨时间、跨模态的同屏比较是多学科会诊质量的重要保障，也是疗效评估（如实体瘤疗效评价）的操作基础。D 正确：影像与电子病历的整合形成结构化的临床数据资产，为教学示教库与回顾性研究提供高效的数据来源。【为什么错】E 错误：诊断报告的书写、修改与审核权限归属影像诊断医师，临床医师仅有查阅权限。报告如需更正，应由影像科按制度出具补充报告或更正报告，原报告与修改痕迹须保留并记入审计日志，以保证医疗文书的严肃性与可追溯性。", "tr": "\"权限边界\"是 PACS 临床应用类题目的常设陷阱。共享的是影像与报告的\"查阅\"，而非\"编辑\"；同理，临床科室也不应具备删除影像、合并患者记录等管理权限。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-0123", "t": "案例分析题", "s": "某三甲医院急诊科夜间接诊一名 72 岁男性，突发剧烈胸背撕裂样疼痛并向下腹放射，血压两上肢不对称，临床高度怀疑主动脉夹层，立即行主动脉 CTA。检查完成后需在最短时间内使急诊医师、在家备班的心外科二线医师与手术室三方同时获取影像资料；患者 3 个月前曾在本院行胸部 CT 平扫，需调出对比。医院已建成 PACS/RIS 并具备院外安全接入条件。基于信息化条件，下列处置流程最合理的是", "o": {"A": "图像重建完成后即时自动归档至 PACS 并触发危急值流程：急诊医师在急诊工作站调阅原始横断面与三维重组图像；心外科二线经身份认证的加密远程通道调阅同一份影像；手术室工作站同步调阅；既往胸部 CT 由系统按主患者索引自动关联或经预取调出对比", "B": "等待全部三维后处理与正式诊断报告审核完成后再统一归档发布，以免临床看到未审核的图像", "C": "由技师用手机拍摄工作站显示器画面，通过即时通讯软件发送给心外科二线医师，以节省时间", "D": "先打印全套胶片，再由护工分别送至急诊科、手术室与二线医师家中", "E": "因涉及患者隐私，院外一律不得访问影像，须待二线医师返院后在科内工作站阅片"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-003", "kp": "急危重症场景下的 PACS 协同应用", "ch": "十二、PACS技术 → 4.PACS临床应用 → (2)临床部门", "ex": "【为什么对】A 正确。主动脉夹层属时间依赖性极强的危急重症，信息化流程的目标是\"图像即时可及、多点同步、历史可比、过程可追溯\"。即时归档使三方基于同一份权威数据进行判断；加密远程接入配合身份认证与审计留痕，在保障隐私的同时不牺牲时效；主患者索引与预取机制保证历史检查自动关联对比；危急值流程确保口头与书面通报闭环。【为什么错】B 等待全部后处理与报告审核会延误抢救；规范做法是图像先归档可调阅，报告按危急值流程尽快出具并电话通报，两者并行而非串行。C 手机翻拍屏幕丢失灰阶与空间分辨率信息、无法调窗与测量，通过普通通讯软件传输还存在隐私泄露与责任界定风险，不符合诊断质量与信息安全要求。D 打印与人工递送耗时长，完全背离 PACS 的建设初衷，在急症场景中不可接受。E 隐私保护的正确路径是\"可控访问\"——身份认证、加密通道、权限最小化与审计留痕，而不是以禁止访问为代价延误抢救。", "tr": "急诊信息化场景题的判分核心是\"时效与合规并重\"。任何以牺牲抢救时效为代价的合规做法（如 E）、或以牺牲合规为代价的提速做法（如 C）都是错误选项。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0124", "t": "单选题", "s": "关于医疗机构推进\"无胶片化\"与电子胶片（云胶片）的认识，下列描述正确的是", "o": {"A": "电子胶片以二维码或链接形式向患者交付影像，患者可用移动终端浏览并授权其他机构调阅；推行时须同时保障影像信息的完整性（含原始 DICOM 数据的获取途径）、身份认证与隐私保护，并保留必要的胶片打印通道", "B": "推行无胶片化意味着医院不必再保存原始 DICOM 数据", "C": "电子胶片上供患者浏览的压缩图像可直接用于诊断阅片，与诊断级显示器观看效果等效", "D": "无胶片化的唯一目的是降低胶片耗材成本，与诊疗流程改善无关", "E": "实行电子胶片后，医院无须再考虑影像数据的备份与长期保存问题"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-004", "kp": "无胶片化与电子胶片的应用要点", "ch": "十二、PACS技术 → 4.PACS临床应用 → (1)影像部门", "ex": "【为什么对】A 正确。电子胶片的价值在于患者随身携带、跨机构授权共享与减少资源消耗，但落地时必须解决三个问题：一是保证外院医师能获取到符合诊断要求的完整影像（提供原始 DICOM 下载或标准化浏览器），而非仅有几幅缩略图；二是通过身份核验与授权机制防止信息泄露；三是对确有需要的场景（如外院系统不兼容、患者无智能终端）保留打印通道。【为什么错】B 无胶片化只是取消胶片这一输出载体，原始 DICOM 数据仍须依法按规定年限完整保存，且要求更高。C 供患者浏览的图像通常经过有损压缩、位深压缩与非校准终端显示，不能等同于诊断级阅片条件。D 无胶片化同时带来流程提速、资料不易丢失、跨机构共享便利与环保效益，成本只是其中一项。E 数据集中后备份与长期保存的重要性反而更高，一旦丢失将不可挽回。", "tr": "电子胶片\"能看\"不等于\"能诊断\"。判断此类题目时抓住两个尺度：是否提供符合诊断要求的原始数据获取途径，是否具备身份认证与隐私保护机制。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0125", "t": "单选题", "s": "关于厂商中立归档（VNA）这一概念，下列描述正确的是", "o": {"A": "VNA 以标准化格式集中存储来自不同厂商、不同科室的医学影像与相关文档，使数据独立于任何单一 PACS 厂商，便于系统更换时的数据迁移与企业级影像共享", "B": "VNA 是某一家厂商推出的专有存储产品的商品名称", "C": "VNA 只能存储放射科的 DICOM 影像，不支持其他科室的影像资料", "D": "部署 VNA 后医院即不再需要 PACS 的影像显示与诊断功能", "E": "VNA 与 DICOM 标准互不兼容，访问时需使用厂商专用协议"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-001", "kp": "厂商中立归档 VNA", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (1)进展", "ex": "【为什么对】A 正确。传统 PACS 的存储层与厂商应用高度耦合，更换 PACS 时常面临昂贵而漫长的数据迁移。VNA 把归档层从应用层剥离出来，以标准格式（DICOM，以及通过 XDS/XDS-I 管理的非 DICOM 文档）统一存储，实现\"换应用不换数据\"，并为跨科室、跨院区的企业级影像管理提供统一底座。【为什么错】B VNA 是一类架构理念与产品形态，多家厂商都有相应实现，并非某一专有商品名。C VNA 的核心目标之一恰恰是覆盖超声、内镜、病理、皮肤科照片、心电等多科室资料，其中非 DICOM 对象常借助 XDS 注册与封装管理。D VNA 只承担归档与管理职能，影像的显示、后处理与诊断仍由 PACS 工作站或通用阅片器完成，二者是分工而非替代。E VNA 以支持 DICOM 等开放标准为前提，正因为遵循标准才能实现\"中立\"。", "tr": "VNA 与 PACS 的关系可类比\"仓库与营业厅\"：VNA 负责长期、标准、中立地存放数据，PACS 负责业务流程与阅片体验。命题常用\"VNA 取代 PACS\"来设陷。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-0126", "t": "多选题", "s": "就 PACS 领域近年来的技术进展而言，下列描述正确的有", "o": {"A": "云 PACS 与区域影像中心使基层机构可共享上级医院的存储与阅片资源，为区域内影像检查结果互认提供技术基础", "B": "零客户端/Web 阅片采用服务器端渲染，客户端只接收渲染后的画面，便于跨终端访问与集中运维", "C": "企业级影像管理把放射、超声、内镜、病理、皮肤科照片等多科室影像统一纳入管理，常与 VNA、XDS-I 等技术结合", "D": "人工智能应用逐步嵌入 PACS 工作流，可承担危急征象预警、病灶检出与量化随访等辅助任务，但须在质量控制与责任界定框架下使用", "E": "随着存储介质成本持续下降，医学影像的长期保存已无须再做分级存储与数据生命周期管理"}, "d": "难", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-002", "kp": "PACS 技术进展与发展方向", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (1)进展", "ex": "【为什么对】A 正确：云化与区域化把存储、算力与专家资源集中，是分级诊疗与检查结果互认的支撑条件，同时对网络质量、数据主权与隐私合规提出更高要求。B 正确：服务器端渲染把计算压力集中到后端，客户端无须安装插件即可获得较好的交互体验，显著降低终端运维成本。C 正确：影像的\"去科室化\"管理是企业级影像的核心思想，非 DICOM 对象通过 XDS/XDS-I 注册与索引纳入统一体系。D 正确：AI 已在结节检出、骨折与出血预警、随访量化等场景落地，但其结果属辅助性质，须建立性能验证、持续监测与责任界定机制。【为什么错】E 错误：薄层 CT、能量成像、数字乳腺断层合成与数字病理使影像数据量呈爆发式增长，增速普遍快于单位存储成本的下降速度；同时法规对不同类别资料的保存年限有明确要求，分级存储、压缩策略与数据生命周期管理不仅不可取消，反而更为重要。", "tr": "涉及\"新技术\"的题目往往在最后一个选项设置\"因此某项传统管理工作可以取消\"的绝对化陷阱。技术进步通常是改变管理方式，而非免除管理责任。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-0127", "t": "单选题", "s": "某院拟对上线运行三年的 PACS 开展应用评价，下列评价思路与指标选择中最合理的是", "o": {"A": "从技术、经济与临床三个层面综合评价：技术层面考察系统可用率、平均调阅响应时间、故障恢复时间与数据完整性；经济层面考察胶片与人力成本节约及投资回收情况；临床层面考察报告周转时间缩短程度、重复检查率下降与临床满意度", "B": "只统计每年节约的胶片费用，即可代表 PACS 的全部价值", "C": "以系统所安装的诊断与浏览工作站数量作为核心评价指标", "D": "以中心服务器磁盘容量的使用率高低作为系统优劣的判断依据", "E": "以影像科医师的诊断符合率作为 PACS 应用评价的唯一指标"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-003", "kp": "PACS 应用评价的指标体系", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (2)应用评价", "ex": "【为什么对】A 正确。信息系统的应用评价须覆盖\"系统好不好用、值不值得、有没有改善诊疗\"三个维度：技术性能指标反映系统本身的可靠性与响应能力；经济指标反映投入产出关系；临床效果指标（报告周转时间 TAT、重复检查率、检查到治疗决策的时间、临床与患者满意度）才是评价其最终价值的关键。三者结合方能形成完整、可比、可持续追踪的评价体系。【为什么错】B 胶片节约只是经济效益的一部分，忽略了效率提升、流程再造、资料不易丢失与临床协同等更重要的价值。C 工作站数量属投入规模指标，不反映产出效果，安装多而使用率低反而是浪费。D 磁盘使用率是容量规划的监控项，与应用效果无关，使用率高低都无法说明系统优劣。E 诊断符合率主要取决于医师专业水平、设备成像质量与病种构成，PACS 只是其中的支持条件之一，把它作为唯一指标既存在归因错误，也无法反映系统在效率与流程方面的贡献。", "tr": "评价类题目的判别要领是看\"是否单一维度\"与\"是否可归因\"。凡以某个孤立数字（成本、数量、容量、符合率）代表整体价值的选项，通常都是错误项。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U12-1001", "t": "单选题", "s": "PACS的中文全称是", "o": {"A": "图像存储与通信系统", "B": "放射信息系统", "C": "医院信息系统", "D": "电子病历系统", "E": "实验室信息系统"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-101", "kp": "PACS基本概念", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (1)发展", "ex": "【为什么对】PACS是Picture Archiving and Communication System的缩写，即图像存储与通信系统，指用数字化方式采集、存储、传输和显示医学影像的计算机网络系统，故A正确。\n【为什么错】B：RIS（Radiology Information System）为放射信息系统。C：HIS（Hospital Information System）为医院信息系统。D：电子病历系统（EMR）管理病历文本。E：实验室信息系统（LIS）管理检验数据，均与PACS含义不符。", "tr": "注意PACS、RIS、HIS三个缩写含义的区别，PACS核心是影像的存储与通信。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1002", "t": "单选题", "s": "下列哪项不属于PACS系统的基本组成", "o": {"A": "影像采集接口", "B": "影像存储与归档服务器", "C": "影像显示工作站", "D": "网络与通信设备", "E": "MRI主磁体"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-102", "kp": "PACS系统组成", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (2)构架与工作流程", "ex": "【为什么对】PACS由影像采集、存储与归档、传输网络、显示工作站及管理软件等组成，MRI主磁体属于MR设备本身，不属于PACS组成，故E正确。\n【为什么错】A：影像采集接口是PACS的数据入口，属其组成。B：影像存储与归档服务器是PACS核心，属其组成。C：影像显示工作站是PACS终端，属其组成。D：网络与通信设备是PACS传输基础，属其组成，均为PACS组成故不符合题意。", "tr": "PACS是信息系统，不包含任何成像设备本体（如球管、磁体）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1003", "t": "单选题", "s": "DICOM是下列哪项的英文缩写", "o": {"A": "医学数字成像与通信", "B": "数字影像与通信系统", "C": "医学信息交换标准", "D": "放射信息管理系统", "E": "医院信息集成标准"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-103", "kp": "DICOM标准概念", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】DICOM全称Digital Imaging and Communications in Medicine，即医学数字成像与通信标准，是医学影像信息交换的国际标准，故A正确。\n【为什么错】B：措辞不准确，DICOM是标准而非系统。C：医学信息交换标准泛指，非DICOM专名。D：对应RIS。E：对应HL7等集成需求，非DICOM名称。", "tr": "DICOM是医学影像的数据与通信标准，与HL7（文本信息交换）易混淆。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1004", "t": "单选题", "s": "DICOM信息模型由高层到低层的排列顺序是", "o": {"A": "患者-检查-序列-图像", "B": "检查-患者-图像-序列", "C": "序列-检查-患者-图像", "D": "患者-序列-检查-图像", "E": "图像-序列-检查-患者"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-104", "kp": "DICOM信息层次模型", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】DICOM信息模型采用四级层次结构：患者（Patient）→检查（Study）→序列（Series）→图像（Instance/Image），自上而下归属关系，故A正确。\n【为什么错】B：将检查置于患者之上，层级颠倒。C：以序列为最高层，层级颠倒。D：将序列置于检查之上，顺序错误。E：以图像为最高层，层级完全颠倒，均不符合DICOM标准。", "tr": "牢记DICOM四层顺序：一个患者可有多个检查，一个检查可有多个序列，一个序列含多幅图像。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1005", "t": "单选题", "s": "DICOM检查工作列表（MWL）的主要作用是", "o": {"A": "将检查申请信息下发至影像设备供技师核对执行", "B": "存储诊断报告", "C": "打印图像", "D": "进行图像后处理", "E": "远程会诊"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-105", "kp": "DICOM检查工作列表", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】Modality Worklist（MWL）将RIS/HIS中已预约登记的患者信息与检查项目下发给影像设备，技师在设备上直接调取确认，减少手工录入与差错，故A正确。\n【为什么错】B：报告存储由RIS管理。C：图像打印对应DICOM打印管理服务。D：图像后处理在工作站完成。E：远程会诊是PACS应用层面功能，均非MWL作用。", "tr": "MWL是设备端取工作单，MPPS是检查执行状态回报，两者易混淆。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1006", "t": "单选题", "s": "关于HL7标准，正确的说法是", "o": {"A": "主要用于传输医学影像数据", "B": "主要用于交换文本形式的临床与行政管理信息", "C": "只能在同一厂家设备间使用", "D": "与DICOM的功能完全相同", "E": "是一种图像压缩算法"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-106", "kp": "HL7标准特点", "ch": "十二、PACS技术 → 3.国际标准与规范 → (1)HL7", "ex": "【为什么对】HL7（Health Level 7）是医疗卫生信息交换标准，面向文本信息（申请、医嘱、报告、收费等），故B正确。\n【为什么错】A：影像数据传输使用DICOM。C：HL7为开放性标准，跨厂商使用。D：HL7管文本、DICOM管图像，功能分工不同。E：HL7不是压缩算法。", "tr": "图像走DICOM、文本走HL7，是PACS集成中最重要的分工概念。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1007", "t": "单选题", "s": "HL7标准名称中的数字“7”指的是OSI参考模型的", "o": {"A": "物理层", "B": "数据链路层", "C": "网络层", "D": "传输层", "E": "应用层"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-107", "kp": "HL7与OSI层次", "ch": "十二、PACS技术 → 3.国际标准与规范 → (1)HL7", "ex": "【为什么对】HL7中的“7”指OSI参考模型的第7层即应用层，其消息标准工作在应用层，故E正确。\n【为什么错】A：物理层是OSI第1层。B：数据链路层是第2层。C：网络层是第3层。D：传输层是第4层，均非HL7名称中“7”所指。", "tr": "“7”对应应用层，属纯记忆考点，注意与传输层（第4层）区分。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1008", "t": "单选题", "s": "PACS影像存储架构中，“近线存储”通常采用的介质是", "o": {"A": "在线磁盘阵列", "B": "磁带库或光盘库", "C": "移动硬盘", "D": "内存", "E": "U盘"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-108", "kp": "PACS影像存储分层", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】PACS存储分在线、近线、离线三级：在线用磁盘阵列快速响应，近线用磁带库、光盘库等自动化的海量存储设备，离线为异地存放的备份介质，故B正确。\n【为什么错】A：磁盘阵列属在线存储而非近线。C：移动硬盘、E：U盘多为临时迁移介质，不属于近线存储体系。D：内存用于计算处理，不用于归档存储。", "tr": "在线=磁盘阵列，近线=磁带/光盘库，离线=异地备份，三者响应速度递减、容量递增。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的发展与组成", "页": 343}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1009", "t": "单选题", "s": "PACS在线存储中，兼具容错能力与较高空间利用率、应用最广泛的RAID级别是", "o": {"A": "RAID 0", "B": "RAID 1", "C": "RAID 5", "D": "JBOD", "E": "无任何冗余的裸盘"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-109", "kp": "RAID级别与存储冗余", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】RAID 5采用分布式奇偶校验，允许单块硬盘故障而不丢失数据，空间利用率高，是PACS在线存储的常用方案，故C正确。\n【为什么错】A：RAID 0无冗余，一坏即全丢。B：RAID 1为镜像，空间利用率仅50%。D：JBOD只是盘符拼接无冗余。E：裸盘无任何容错，均不适合关键影像数据。", "tr": "RAID 0快但不安全，RAID 1安全但浪费空间，RAID 5在两者间取得平衡。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1010", "t": "单选题", "s": "某PACS在100Mbps局域网内传输2000幅平均500KB的CT图像（1MB=8Mbit），忽略协议开销，约需", "o": {"A": "8秒", "B": "40秒", "C": "80秒", "D": "400秒", "E": "800秒"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-110", "kp": "影像传输时间估算", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (4)通讯与网络", "ex": "【为什么对】数据总量=2000×500KB=1000MB≈1GB；换算为比特1GB=8Gbit=8192Mbit；100Mbps即100Mbit/s；时间=8192/100≈82秒，约80秒，故C正确。\n【为什么错】A：8秒按100MB计算。B：40秒按0.5GB计算。D：400秒按带宽25Mbps计算。E：800秒按带宽10Mbps计算，均计算有误。", "tr": "先统一单位：字节×8转比特，再除以带宽（bps），注意Mbps与MB/s相差8倍。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1011", "t": "单选题", "s": "远程放射学的核心内容是", "o": {"A": "医学影像的异地传输与会诊", "B": "影像设备维修", "C": "报告打印", "D": "患者信息管理", "E": "医保结算"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-111", "kp": "远程放射学概念", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】远程放射学是利用网络将影像资料从采集地传输到异地进行诊断、会诊的技术，核心是影像的异地传输与会诊，故A正确。\n【为什么错】B：设备维修属工程维护。C：报告打印为终端输出。D：患者信息管理属HIS/RIS。E：医保结算与影像业务无关，均非远程放射学核心。", "tr": "远程放射学强调“影像传输+异地诊断”，网络带宽与图像质量是成败关键。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1012", "t": "单选题", "s": "一幅约10MB的DR图像，若要求在2秒内完成传输，所选网络的最低速率约为", "o": {"A": "1Mbps", "B": "10Mbps", "C": "40Mbps", "D": "100Mbps", "E": "1Gbps"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-112", "kp": "网络带宽需求估算", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (4)通讯与网络", "ex": "【为什么对】10MB=80Mbit，2秒内传完要求速率≥40Mbit/s；工程中应留裕量，选不低于100Mbps的速率，故D正确。\n【为什么错】A：1Mbps下2秒仅能传2Mbit，严重不足。B：10Mbps下2秒传20Mbit，不足。C：40Mbps为理论临界值无裕量。E：1Gbps可行但高于最低要求，非“最低”速率。", "tr": "先算理论最低速率40Mbps，再结合实际选取更高档位，题目问“最低”时应兼顾工程裕量选100Mbps。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1013", "t": "单选题", "s": "PACS与HIS、RIS实现文本信息（申请、报告、收费等）交换时，最常采用的标准是", "o": {"A": "DICOM", "B": "HL7", "C": "IHE", "D": "JPEG", "E": "MPEG"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-113", "kp": "PACS与HIS/RIS集成标准", "ch": "十二、PACS技术 → 2.PACS运行 → (4)与HIS/RIS集成", "ex": "【为什么对】HL7是文本信息交换标准，用于检查申请、报告、收费等消息在HIS、RIS与PACS之间的传递，故B正确。\n【为什么错】A：DICOM用于影像数据与影像设备交互。C：IHE是集成规范框架而非具体消息标准。D：JPEG为图像压缩格式。E：MPEG为视频压缩格式，均与文本信息交换无关。", "tr": "影像交互用DICOM、文本交互用HL7，IHE是指导两者组合应用的框架。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1014", "t": "单选题", "s": "PACS中“影像预取（prefetch）”指的是", "o": {"A": "检查前将患者相关历史影像自动调取至工作站", "B": "检查后立即删除图像", "C": "对图像进行有损压缩", "D": "将过期图像迁移至离线介质", "E": "备份数据库"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-114", "kp": "影像预取与调阅", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (6)影像管理", "ex": "【为什么对】预取指根据检查预约信息，在患者到检前自动将既往相关影像从归档系统调取到读片工作站，便于新旧对比，故A正确。\n【为什么错】B：检查后不立即删除图像。C：压缩是存储策略之一。D：过期图像迁移至离线属归档/迁移。E：备份数据库是维护措施，均非预取含义。", "tr": "预取（prefetch）与归档、迁移概念区分：预取是把旧图像提前调出来。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1015", "t": "单选题", "s": "DICOM“存储承诺（Storage Commitment）”的作用是", "o": {"A": "确认图像已安全存入归档系统后，来源设备方可删除本地图像", "B": "自动分配检查号", "C": "定义胶片打印格式", "D": "控制显示器亮度", "E": "核对患者身份"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-115", "kp": "DICOM存储承诺服务", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】存储承诺是DICOM服务类之一：影像设备将图像提交归档系统，归档系统确认安全存储后返回承诺，设备据此才能删除本地图像，防止数据丢失，故A正确。\n【为什么错】B：检查号分配由RIS登记产生。C：胶片格式由DICOM打印管理定义。D：显示器亮度校准依据GSDF。E：身份核对由MWL/登记环节完成，均与存储承诺无关。", "tr": "存储承诺的本质是“归档确认机制”，与检查工作列表、打印服务等DICOM服务类区分。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1016", "t": "单选题", "s": "为保障远程放射学中传输影像资料的完整性与不可篡改性，最有效的技术措施是", "o": {"A": "加大防火墙", "B": "数字签名与完整性校验", "C": "定期查杀病毒", "D": "提高传输带宽", "E": "增加存储容量"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-116", "kp": "远程放射学数据安全", "ch": "十二、PACS技术 → 2.PACS运行 → (3)系统安全", "ex": "【为什么对】数字签名可验证数据来源真实性，完整性校验（如哈希）能发现数据在传输中被篡改或损坏，是保障影像资料真实、完整的关键措施，故B正确。\n【为什么错】A：防火墙用于网络访问控制，不能防止内容篡改。C：杀毒软件防范恶意代码，不验证数据完整性。D：带宽只影响传输速度。E：容量只影响存储规模，均无法保证数据不可篡改。", "tr": "“防篡改”对应数字签名与完整性校验；“防入侵”对应防火墙；“防丢失”对应备份。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U12-1017", "t": "单选题", "s": "IHE（医疗企业集成）是", "o": {"A": "基于DICOM、HL7等标准组织应用流程的集成框架", "B": "一种图像压缩算法", "C": "一种网络传输协议", "D": "一种胶片质量检测标准", "E": "一个数据库管理系统"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-117", "kp": "IHE集成框架", "ch": "十二、PACS技术 → 3.国际标准与规范 → (3)IHE", "ex": "【为什么对】IHE（Integrating the Healthcare Enterprise，医疗企业集成）以DICOM、HL7等既有标准为基础，通过定义角色与事务将标准组织成解决实际医疗流程问题的集成框架，故A正确。\n【为什么错】B：压缩算法如JPEG2000。C：网络协议如TCP/IP。D：胶片检测如SMPTE测试片。E：数据库如SQL Server，均与IHE无关。", "tr": "IHE不是新标准，而是“如何组合使用DICOM与HL7”的规范框架。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1018", "t": "单选题", "s": "某院PACS在线存储容量即将用尽而检查量持续增长，从性价比与可扩展性考虑，最合理的扩容方案是", "o": {"A": "仅增加离线磁带", "B": "扩容磁盘阵列并配置自动归档迁移策略", "C": "直接删除3年以上旧图像", "D": "改用纯内存存储", "E": "降低所有图像分辨率后存储"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-118", "kp": "PACS存储扩容策略", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (2)应用评价", "ex": "【为什么对】扩容在线磁盘阵列满足当前读写需求，同时设置自动归档策略将符合条件（如超期、少调阅）的图像迁移至近线/离线存储，兼顾容量、性能与法规保存要求，故B正确。\n【为什么错】A：仅加离线磁带无法缓解在线空间压力。C：直接删除历史图像违反影像保存规定。D：内存成本极高且断电丢失，不适合归档。E：降低分辨率损害诊断质量，均不可取。", "tr": "扩容方案要“在线扩容+分层归档”双管齐下，不能牺牲诊断质量或违规删除。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U12-1019", "t": "多选题", "s": "PACS系统的基本组成包括", "o": {"A": "影像采集接口", "B": "影像存储与归档服务器", "C": "影像显示工作站", "D": "网络与通信设备", "E": "X线球管"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-119", "kp": "PACS系统组成", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (2)构架与工作流程", "ex": "【为什么对】PACS由影像采集接口、存储与归档服务器、显示工作站、网络与通信设备以及管理软件等组成，故A、B、C、D正确。\n【为什么错】E：X线球管是X线成像设备（DR/CT）的部件，不属于PACS信息系统组成。", "tr": "PACS是信息系统，影像产生设备本体（球管、探测器、磁体）不属于其组成。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1020", "t": "多选题", "s": "DICOM标准提供的主要服务类（Service Class）包括", "o": {"A": "影像存储服务", "B": "查询/检索服务", "C": "打印管理服务", "D": "检查工作列表服务", "E": "光纤介质传输服务"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-120", "kp": "DICOM服务类", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】DICOM定义的服务类包括影像存储、查询/检索、打印管理、检查工作列表、存储承诺、检查执行步骤等，故A、B、C、D正确。\n【为什么错】E：光纤是物理传输介质，DICOM协议本身基于TCP/IP，不存在名为“光纤介质传输”的DICOM服务类。", "tr": "区分DICOM服务类（存储、查询检索、打印、工作列表等）与物理传输介质（光纤、双绞线）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1021", "t": "多选题", "s": "关于PACS中图像压缩的正确说法是", "o": {"A": "无损压缩是可逆的、不丢失任何诊断信息", "B": "JPEG2000同时支持无损与有损压缩", "C": "诊断用图像宜采用无损或近无损压缩", "D": "压缩比越高图像质量越高", "E": "有损压缩在任何场合都不可使用"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-121", "kp": "图像压缩与质量", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】无损压缩可完全还原原始数据；JPEG2000支持有损与无损两种模式；诊断影像为保证质量宜采用无损或近无损压缩，故A、B、C正确。\n【为什么错】D：压缩比越高数据损失越大、图像质量越低。E：有损压缩可用于浏览、存档辅助等非诊断场景，并非完全不可用。", "tr": "压缩比与图像质量成反比；有损压缩并非禁用，而是诊断环节须谨慎。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1022", "t": "多选题", "s": "开展远程放射学会诊应具备的条件包括", "o": {"A": "足够的网络传输带宽", "B": "保证图像质量与显示一致性", "C": "患者隐私与数据安全保障", "D": "会诊资质与法律合规要求", "E": "无需任何网络支持"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-122", "kp": "远程放射学实施条件", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】远程会诊要求足够带宽保障传输速度与时效，图像质量与显示校准一致保证诊断可靠性，加密、授权等保障隐私安全，并须符合会诊资质与法规要求，故A、B、C、D正确。\n【为什么错】E：远程会诊恰恰必须依赖网络，说法完全错误。", "tr": "远程放射学四大要素：带宽、图像质量、信息安全、资质合规。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1023", "t": "多选题", "s": "PACS系统安全防护措施包括", "o": {"A": "部署防火墙与入侵检测", "B": "用户身份认证与权限分级", "C": "传输与存储数据加密", "D": "定期备份并建立容灾机制", "E": "关闭审计日志以节省空间"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-123", "kp": "PACS系统安全", "ch": "十二、PACS技术 → 2.PACS运行 → (3)系统安全", "ex": "【为什么对】防火墙与入侵检测防止外部攻击，认证与权限分级控制访问，加密保护数据保密性，备份与容灾保障可用性，均属系统安全措施，故A、B、C、D正确。\n【为什么错】E：审计日志用于安全追踪与责任追溯，关闭日志会削弱安全管理能力。", "tr": "安全体系包含保密性、完整性、可用性三个方面，审计日志是安全追踪的重要工具。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1024", "t": "多选题", "s": "PACS影像管理的功能主要包括", "o": {"A": "影像预取", "B": "影像路由", "C": "影像归档", "D": "检索与调阅", "E": "自动出具诊断结论"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-124", "kp": "PACS影像管理功能", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (6)影像管理", "ex": "【为什么对】影像管理包括预取、路由（按规则分发到相应工作站）、归档（分级存储）、检索与调阅等，故A、B、C、D正确。\n【为什么错】E：诊断结论由放射科医师根据影像与临床资料综合分析后出具，PACS不自动生成诊断结论。", "tr": "PACS提供影像存取与管理，诊断报告的人工智能辅助属进展方向，非系统常规功能。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1025", "t": "多选题", "s": "PACS影像数据可以使用的存储介质包括", "o": {"A": "磁盘阵列", "B": "磁带库", "C": "光盘库", "D": "移动硬盘", "E": "荧光屏"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-125", "kp": "PACS存储介质", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】磁盘阵列用于在线，磁带库、光盘库用于近线，移动硬盘可用于临时迁移或小型备份，故A、B、C、D正确。\n【为什么错】E：荧光屏是显示器件，不能存储影像数据。", "tr": "存储介质均为可写入读出的物理载体，显示器件不属于存储介质。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1026", "t": "多选题", "s": "制定PACS存储与备份策略时应考虑的因素包括", "o": {"A": "检查量与数据增长率", "B": "在线、近线、离线分层存储需求", "C": "备份周期与异地容灾地点", "D": "法规规定的影像保存期限", "E": "显示器数量与分辨率"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-126", "kp": "PACS存储策略规划", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】存储策略须根据数据量增长预估容量，按访问频率设计分层存储，明确备份周期与容灾方案，并满足法规对影像保存期限的要求，故A、B、C、D正确。\n【为什么错】E：显示器数量与分辨率影响显示配置，与存储容量、备份策略无关。", "tr": "存储策略的核心变量是容量、分层、备份与法规期限，不含显示端配置。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U12-1027", "t": "多选题", "s": "利用HL7与DICOM实现PACS与HIS/RIS集成时，典型的应用场景包括", "o": {"A": "检查申请单自动下发", "B": "检查执行状态（MPPS）回报", "C": "诊断报告回传与发布", "D": "预约挂号与患者信息同步", "E": "图像像素数据压缩"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-127", "kp": "PACS-HIS/RIS集成应用", "ch": "十二、PACS技术 → 2.PACS运行 → (4)与HIS/RIS集成", "ex": "【为什么对】集成环境下检查申请经HL7下发、设备经DICOM MWL取单并回报MPPS、报告经HL7回传发布、预约与患者信息同步，均为典型场景，故A、B、C、D正确。\n【为什么错】E：图像像素数据压缩属存储优化环节，不属于信息集成应用场景。", "tr": "集成场景围绕“信息流”展开，像素压缩属于“数据流”优化，二者层面不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1028", "t": "多选题", "s": "PACS系统日常维护应包含的内容有", "o": {"A": "定期检查备份并演练数据恢复", "B": "监控磁盘容量与系统日志", "C": "及时升级系统补丁与杀毒软件", "D": "巡检UPS电源与网络设备", "E": "关闭异地备份以简化管理"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-128", "kp": "PACS日常维护", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】备份检查与恢复演练保障数据安全，容量与日志监控及时发现异常，补丁与杀毒软件防患安全风险，电源与网络巡检保障运行环境，故A、B、C、D正确。\n【为什么错】E：异地备份是容灾的重要手段，关闭异地备份会大幅降低数据抗风险能力。", "tr": "日常维护是“备份、监控、加固、巡检”的组合拳，备份必须有恢复演练才有效。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U12-1029a", "t": "共用题干题", "s": "患者检查申请信息自动显示在CT设备操作界面上，技师核对后直接执行检查，主要依赖的DICOM服务是", "o": {"A": "检查工作列表（MWL）", "B": "图像打印服务", "C": "存储承诺", "D": "查询/检索服务", "E": "影像存储服务"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-129", "kp": "检查工作列表应用", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】MWL将RIS登记的患者信息与检查项目自动下发到影像设备，技师在设备端直接调取核对，无需手工录入，故A正确。\n【为什么错】B：打印服务用于胶片输出。C：存储承诺用于归档确认。D：查询/检索用于事后调阅历史影像。E：影像存储服务用于保存图像，均与检查申请下发无关。", "tr": "“自动取单”对应MWL；“查历史”对应Query/Retrieve；“报进度”对应MPPS。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1201", "gs": "某三甲医院放射科拟将PACS与HIS/RIS全面集成，实现患者从门诊开单、放射科登记、影像设备检查到报告回传的全流程信息化，并将夜间急诊影像通过远程网络发送至院外会诊中心。技师在CT操作台前开始一天的检查工作。"}, {"id": "U12-1029b", "t": "共用题干题", "s": "检查完成后，设备自动向RIS回报本次检查已执行完毕及参数信息，所采用的服务是", "o": {"A": "检查执行步骤（MPPS）", "B": "打印管理", "C": "胶片格式定义", "D": "灰阶校准", "E": "图像无损压缩"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-130", "kp": "检查执行步骤回报", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】MPPS（Modality Performed Procedure Step）将设备实际执行的检查状态与参数回报给RIS，实现流程闭环，故A正确。\n【为什么错】B：打印管理负责图像打印。C：胶片格式属打印服务内容。D：灰阶校准针对显示设备。E：压缩属存储优化，均与检查状态回报无关。", "tr": "MWL负责“下发”，MPPS负责“回报”，两者配套构成检查流程闭环。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1201", "gs": ""}, {"id": "U12-1030a", "t": "共用题干题", "s": "在不压缩、忽略协议开销的情况下，全部图像传输完毕约需", "o": {"A": "约1分钟", "B": "约4分钟", "C": "约8分钟", "D": "约14分钟", "E": "约40分钟"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-131", "kp": "远程传输时间估算", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】数据总量1000MB≈1GB，换算8Gbit=8192Mbit；10Mbps传输，时间=8192/10≈820秒≈13.6分钟，约14分钟，故D正确。\n【为什么错】A：按10Mbit计算。B：按250MB计算。C：按500MB计算。E：按带宽4Mbps计算，均不正确。", "tr": "GB与Gbit相差8倍，Mbps是Mbit/s而非MB/s，勿混淆单位。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1202", "gs": "某县级医院需将1000幅CT图像（每幅约1MB）通过10Mbps专线发送至上级医院进行远程会诊，技师需估算传输时间，并在有限带宽条件下确保在规定时间内完成传输。"}, {"id": "U12-1030b", "t": "共用题干题", "s": "若院方要求在2分钟内完成全部图像传输且不更换网络线路，最有效的措施是", "o": {"A": "对图像进行无损或近无损压缩后传输", "B": "提高图像采集分辨率", "C": "逐幅手工拷贝到移动硬盘", "D": "关闭远程会诊系统", "E": "增加显示工作站数量"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-132", "kp": "远程传输优化措施", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】固定带宽下减少传输数据量是唯一有效途径，采用无损/近无损压缩既保证诊断质量又缩短时间，故A正确。\n【为什么错】B：提高分辨率使数据量增大，适得其反。C：手工拷贝效率低且非实时会诊方案。D：关闭系统无法完成会诊。E：工作站数量与传输时间无关。", "tr": "压缩是带宽不足时缩短传输时间的直接手段，但要兼顾诊断图像质量要求。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1202", "gs": ""}, {"id": "U12-1031a", "t": "共用题干题", "s": "为防止单块硬盘故障导致在线数据丢失，在线存储最应采用的容错方案是", "o": {"A": "RAID 0", "B": "RAID 1或RAID 5冗余阵列", "C": "仅依靠UPS不间断电源", "D": "增加内存容量", "E": "提高显示器分辨率"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-133", "kp": "在线存储容错", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】RAID 1镜像、RAID 5分布式奇偶校验均可在单块硬盘故障时不丢数据，是满足可靠保存要求的容错方案，故B正确。\n【为什么错】A：RAID 0无冗余，单盘故障即数据丢失。C：UPS解决断电问题，不解决硬盘故障。D：内存与数据持久保存无关。E：显示器分辨率与存储容错无关。", "tr": "UPS防断电、RAID防硬盘故障，两者作用不同，不可混为一谈。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1203", "gs": "某医院PACS在线服务器的一块硬盘发生故障，管理人员启动应急预案。医院规定所有影像数据必须长期可靠保存，不能因硬件故障造成图像丢失。"}, {"id": "U12-1031b", "t": "共用题干题", "s": "关于影像数据长期可靠保存，下列做法中最为关键的是", "o": {"A": "定期将数据备份至异地存储并定期演练恢复", "B": "只做在线磁盘冗余", "C": "停用近线存储设备", "D": "删除超期诊断报告", "E": "仅依赖防病毒软件"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-134", "kp": "数据长期保存与容灾", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】异地备份可抵御设备损坏、火灾、灾害等风险，且定期演练恢复能确保备份真正可用，是长期可靠保存的关键，故A正确。\n【为什么错】B：仅在线冗余无法应对服务器整体故障或灾害。C：停用近线存储削弱分层归档能力。D：删除报告违反病历管理要求。E：防病毒软件无法防止硬件故障与数据损坏。", "tr": "“有备份”不等于“可恢复”，只有经过恢复演练的备份才是有效备份。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1203", "gs": ""}, {"id": "U12-1032", "t": "案例分析题", "s": "患者女性，55岁，因腰椎骨折在外院行CT检查后转诊至我院，携带光盘影像资料。放射科PACS管理员在例行巡检中发现归档服务器在线磁盘使用率已达95%，新检查图像的自动归档开始失败，历史图像调阅速度明显下降。该院日检查量约800例且持续增长，院内规定影像资料至少保存15年。管理员需要在不影响临床使用、不违反影像保存规定的前提下解决容量问题。下列处置措施最为恰当的是", "o": {"A": "立即删除全部历史图像以释放空间", "B": "启用自动迁移策略将符合条件的旧图像转至近线存储，并扩容在线磁盘", "C": "关闭PACS系统暂停所有检查", "D": "忽略故障继续运行等待自然缓解", "E": "把全部图像有损压缩至极低质量"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-135", "kp": "PACS容量管理处置", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】自动迁移将低频调阅的旧图像转至近线存储，既释放在线空间又保留数据，再扩容在线磁盘满足新数据写入，兼顾临床使用与保存规定，故B正确。\n【为什么错】A：删除历史图像违反影像保存规定。C：关停系统严重影响诊疗。D：放任故障会导致归档持续失败与数据丢失。E：极低质量压缩损害诊断价值，均不可取。", "tr": "容量治理要“迁、扩、管”结合，禁止以删除影像、停用系统、过度压缩为代价。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1033", "t": "案例分析题", "s": "患者男性，62岁，突发右侧肢体无力伴言语不清1小时就诊于基层医院，NIHSS评分12分。临床高度怀疑急性脑梗死，发病时间在静脉溶栓时间窗内，行颅脑CT检查提示未见出血。基层医院无神经影像专家，需请上级医院专家紧急会诊决定是否溶栓。该院已建成区域远程会诊平台，可加密传输原始影像并支持在线同步阅片。当前最合适的做法是", "o": {"A": "通过PACS远程会诊平台即时上传图像并同步会诊", "B": "让患者自行转院后再看片", "C": "打印胶片后快递至上级医院", "D": "仅电话口头描述影像所见", "E": "等次日上班后再传输"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-136", "kp": "远程会诊临床应用", "ch": "十二、PACS技术 → 4.PACS临床应用 → (2)临床部门", "ex": "【为什么对】急性卒中救治时间窗紧迫，通过远程放射学平台即时上传原始图像并同步会诊，可使上级专家快速判断，指导溶栓决策，故A正确。\n【为什么错】B：转院延误溶栓时间窗。C：快递胶片时效性太差。D：口头描述无法客观评估影像细节。E：延迟传输错过最佳治疗时机，均不可取。", "tr": "远程会诊在急症中的价值体现为“时效性”，必须及时传输原始影像供专家直接判读。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的临床应用", "页": 352}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1034", "t": "案例分析题", "s": "某影像中心DR设备本地硬盘空间紧张，技师计划清理设备本地缓存图像以腾出空间。设备与PACS归档服务器之间通过DICOM协议连接，存在历史图像可能尚未完成归档的情况，若误删将造成不可恢复的数据丢失。技师需要判断哪些图像可以安全删除。科室制定了本地数据清理规范，要求删除前必须核实归档状态。判断本地图像已安全归档、可以删除的最可靠依据是", "o": {"A": "本地文件时间已超过一天", "B": "已收到DICOM存储承诺的成功确认", "C": "图像曾在设备显示器上显示过", "D": "图像传输过程已经开始", "E": "图像已拷贝到U盘"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-137", "kp": "存储承诺与本地清理", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】DICOM存储承诺由归档系统确认图像已安全存储后返回，只有收到该确认才能保证数据已在归档端落地，是安全删除本地图像的最可靠依据，故B正确。\n【为什么错】A：时间长短不能证明归档完成。C：显示过只说明曾调阅。D：传输开始不代表传输成功。E：拷贝到U盘不替代归档系统保存。", "tr": "“开始传输”“看过片”都不代表“已归档”，只有存储承诺确认才可靠。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U12-1035", "t": "案例分析题", "s": "放射科拟新增一间DR胸片诊断阅片室，医生需要在高亮度、高对比度、稳定的显示条件下对数字胸片进行诊断，同时希望多年使用中不同显示器、不同时段观片效果保持一致，以保障诊断质量与阅片一致性。技师负责提出显示设备选型建议。选型同时需考虑辐射防护要求与多年使用中显示效果的一致性。选择诊断显示设备时最应关注的是", "o": {"A": "屏幕尺寸越大越好", "B": "分辨率高且符合DICOM灰阶标准显示函数并定期校准", "C": "价格越低越好", "D": "可播放视频", "E": "支持无线充电"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-138", "kp": "诊断显示工作站要求", "ch": "十二、PACS技术 → 4.PACS临床应用 → (1)影像部门", "ex": "【为什么对】诊断显示器须具备足够分辨率与亮度，并遵循DICOM灰阶标准显示函数（GSDF）校准，保证不同显示器、不同时段观片效果一致，故B正确。\n【为什么错】A：尺寸需与观片距离匹配，并非越大越好。C：价格低可能牺牲亮度与灰阶性能。D：视频播放非诊断显示核心要求。E：无线充电与诊断显示无关。", "tr": "诊断显示的关键是“GSDF灰阶校准”与分辨率亮度达标，而非尺寸、价格等表面参数。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1036", "t": "案例分析题", "s": "某医院PACS服务器感染勒索病毒，系统文件与部分影像数据被加密，放射科图像调阅中断，临床工作受阻。医院信息部门开展应急响应与灾后重建，既要尽快恢复临床业务，又要防止事件重演，并确保影像数据完整可追溯。从系统安全角度，医院同时要求对存储数据加密、对访问行为留痕，并重新评估网络边界。下列措施中最为关键的是", "o": {"A": "将PACS直接接入互联网以便远程管理", "B": "从异地离线备份恢复数据，同时实施网络隔离与访问控制", "C": "关闭防火墙以提高网络速度", "D": "停止安装系统安全补丁", "E": "卸载杀毒软件避免误报"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-139", "kp": "PACS安全事件处置", "ch": "十二、PACS技术 → 2.PACS运行 → (3)系统安全", "ex": "【为什么对】离线备份未被病毒污染，可保证数据恢复，同时实施网络隔离、访问控制与补丁加固，防止再次感染，故B正确。\n【为什么错】A：接入互联网增加暴露面，风险更大。C：关闭防火墙削弱安全防线。D：不装补丁留下漏洞。E：卸载杀毒软件降低防护能力，均错误。", "tr": "勒索病毒应对核心是“离线备份可恢复+隔离加固防再犯”，安全措施只能加强不能削弱。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-1037", "t": "案例分析题", "s": "患者男性，48岁，因腹部疼痛行腹部CTA检查，图像存于PACS。骨科与普外科医师拟在科室会诊时共同查看CTA三维血管重建图像，讨论手术方案。两位医师均在各自科室的办公电脑上工作，科室未配备专用诊断级读片工作站，且需遵守医疗信息安全规定。科室信息化管理规定要求调阅影像必须经授权并保留审计记录。医师获取图像最便捷且符合合规要求的方式是", "o": {"A": "通过临床浏览工作站或Web版PACS授权调阅", "B": "借用放射科诊断工作站", "C": "打印胶片后翻拍照片", "D": "用手机拍摄屏幕照片", "E": "通过个人邮箱发送原始DICOM数据"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-140", "kp": "临床部门影像调阅", "ch": "十二、PACS技术 → 4.PACS临床应用 → (2)临床部门", "ex": "【为什么对】临床浏览工作站或Web版PACS经授权后可直接在临床科室调阅影像及三维重建结果，便捷且符合信息安全与合规要求，故A正确。\n【为什么错】B：借用放射科诊断工作站干扰诊断工作且不便利。C：打印胶片后翻拍失真且不利于诊断。D：手机拍摄屏幕照片质量差且不规范。E：通过个人邮箱传输原始影像存在隐私泄露风险，不合规。", "tr": "临床调阅应依托授权化、受控的PACS浏览通道，严禁拍照、邮箱等非合规方式传播影像。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-9009", "t": "单选题", "s": "PACS（影像归档与通信系统）在现代放射科的核心价值不包括", "o": {"A": "影像数字化存储，实现无胶片化", "B": "多终端远程调阅，支持临床快速获取", "C": "与 HIS/RIS 集成实现流程闭环", "D": "取代放射科医师的影像诊断工作", "E": "支持三维后处理与教学科研数据再利用"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-009", "kp": "PACS核心价值", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (2)应用评价", "ex": "【为什么对】D正确——PACS 是影像的采集、存储、传输与管理平台，辅助而非取代医师诊断；诊断仍由具备资质的医师完成。【为什么错】A、B、C、E均为 PACS 的确切价值：无胶片化降低耗材、远程调阅提高时效、与 HIS/RIS 集成优化工作流、海量数据支撑后处理与科研。", "tr": "PACS 是\"管理系统\"不是\"诊断系统\"，不替代医师。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-9010", "t": "单选题", "s": "厂商中立归档（VNA）在影像系统中的主要作用是", "o": {"A": "提高单一品牌设备的成像速度", "B": "以标准格式集中管理跨厂商、跨模态的影像与信息，降低厂商锁定风险", "C": "替代 DICOM 标准实现私有传输", "D": "仅用于急诊科的临时缓存", "E": "加密患者隐私使其无法被医师调阅"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-010", "kp": "厂商中立归档VNA", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (1)进展", "ex": "【为什么对】B正确——VNA 以厂商中立的方式（常基于标准 DICOM/HTML 等）长期归档影像与文档，使数据不绑定于某一 PACS 厂商，便于系统替换、跨院区共享与长期可访问，降低\"厂商锁定\"。【为什么错】A VNA 不改设备成像速度；C它恰恰建立在标准之上而非私有；D VNA 是长期归档而非临时缓存；E VNA 在受控权限下仍可被授权医师调阅，并非不可见。", "tr": "VNA 的价值在于\"中立/可移植\"，而非加速或加密屏蔽。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-9011", "t": "单选题", "s": "远程放射学（teleradiology）最典型的应用场景是", "o": {"A": "同一机房内两台 CT 之间的图像传输", "B": "基层或夜间将影像通过网络传至上级/远程中心由专家出具报告", "C": "用 U 盘拷贝影像至外院", "D": "取代现场 CT 设备", "E": "仅用于教学直播"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-011", "kp": "远程放射学应用", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (1)进展", "ex": "【为什么对】B正确——远程放射学利用网络将影像从采集端传至异地专家端，使基层、夜间或资源不足的机构也能获得及时的专业诊断，是 PACS 与广域网结合的典型应用。【为什么错】A属院内局域网常规调阅，非\"远程\"核心含义；C物理介质搬运非网络远程；D不取代设备；E教学仅为衍生用途。", "tr": "远程放射学的关键是\"异地专家诊断\"，不是单纯图像搬家。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-9012", "t": "单选题", "s": "评价 PACS 系统应用成效时，下列最应关注的指标组合是", "o": {"A": "显示器外观颜色与机房装修风格", "B": "系统可用性、影像调阅速度、存储成本与临床满意度（ROI）", "C": "仅关注设备采购价格", "D": "仅关注胶片节省数量", "E": "仅关注服务器 CPU 主频"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-012", "kp": "PACS应用评价维度", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (2)应用评价", "ex": "【为什么对】B正确——PACS 评价应综合技术性能（可用性、调阅延迟、存储扩展）、经济与管理效益（成本、投资回报 ROI）及用户体验（临床满意度），才能真实反映系统价值。【为什么错】A外观与装修无关系统成效；C、D、E均属单一维度，片面评价会掩盖可用性、时效或满意度等关键问题。", "tr": "评价应多维（技术+经济+体验），不能用单一指标下结论。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-9101", "t": "多选题", "s": "关于 PACS 在临床部门中的应用，下列说法正确的有", "o": {"A": "影像科内部调阅、后处理与报告 Workflow", "B": "临床科室即时调阅患者影像与报告", "C": "远程会诊与双向转诊影像共享", "D": "作为教学与科研的影像数据库", "E": "可替代放射科医师作出诊断"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "KP-BU-12-9101-副高", "kp": "PACS临床应用范畴", "ch": "十二、PACS技术 → 4.PACS临床应用 → (补充)PACS临床应用", "ex": "【为什么对】A、B、C、D 正确：PACS 的核心价值在于影像的数字化存储、调阅、远程共享与教学科研；上述均为其典型临床应用。【为什么错】E 错误：PACS 是影像管理与显示工具，诊断决策仍必须由具备资质的放射科医师作出，系统不能替代诊断。", "tr": "注意 E 为典型干扰项——PACS 提升效率但不能替代医师诊断。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的临床应用", "页": 352}, "hf": false, "src": "补充", "mk": 1}, {"id": "U12-9201", "t": "单选题", "s": "PACS 中实现异地会诊主要依靠", "o": {"A": "网络传输与 DICOM 标准", "B": "胶片邮寄", "C": "暗室冲洗", "D": "增感屏", "E": "洗片机"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-9201", "kp": "PACS会诊", "ch": "十二、PACS技术 → 4.PACS临床应用", "ex": "【为什么对】PACS 借助网络与 DICOM 实现影像远程传输与异地会诊。\n【为什么错】胶片邮寄为传统方式。", "tr": "PACS会诊靠网络。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-9202", "t": "单选题", "s": "关于 PACS 在医院工作流程中的价值，错误的是", "o": {"A": "减少重复检查与胶片消耗", "B": "加快报告与调阅", "C": "完全消除医师诊断错误", "D": "支持多学科协作", "E": "便于教学与科研"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-9202", "kp": "PACS价值", "ch": "十二、PACS技术 → 4.PACS临床应用", "ex": "【为什么对】PACS 提升效率与协作，但不能消除诊断错误（诊断仍依赖医师）。\n【为什么错】其余均为 PACS 价值。", "tr": "PACS不消除诊断错误。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-9203", "t": "单选题", "s": "PACS 与电子病历（EMR）集成的主要目的是", "o": {"A": "实现影像与临床信息的统一管理", "B": "替代医师", "C": "减少网络负载", "D": "降低分辨率", "E": "限制访问"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-9203", "kp": "PACS-EMR集成", "ch": "十二、PACS技术 → 5.PACS进展与评价", "ex": "【为什么对】PACS 与 EMR 集成使影像与临床信息互通，支持综合诊疗。\n【为什么错】集成不替代医师或降质。", "tr": "集成统一信息。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U12-9204", "t": "单选题", "s": "关于区域 PACS/影像协同平台，正确的是", "o": {"A": "支持分级诊疗与远程协作", "B": "仅单机使用", "C": "与基层无关", "D": "增加重复检查", "E": "降低可及性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-9204", "kp": "区域PACS", "ch": "十二、PACS技术 → 5.PACS进展与评价", "ex": "【为什么对】区域 PACS 促进上下级医院影像共享、远程诊断，支撑分级诊疗。\n【为什么错】它减少而非增加重复检查。", "tr": "区域PACS助分级诊疗。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0101", "t": "单选题", "s": "关于医用图像打印技术的分类，正确的是", "o": {"A": "按成像原理可分为激光成像、热敏成像与喷墨成像；按是否需要化学处理可分为湿式与干式", "B": "干式打印是指打印后无需晾干的一种湿式冲洗方式", "C": "喷墨成像属于干式激光成像的一个分支", "D": "湿式激光打印不需要显影与定影处理", "E": "热敏成像必须以激光作为加热能量源"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-001", "kp": "医用图像打印技术分类", "ch": "十三、图像打印技术 → 1.概述 → (1)图像打印技术的分类与发展", "ex": "【为什么对】A正确：医用硬拷贝输出按成像原理分为激光成像、热敏（直热式）成像与喷墨成像三大类；按是否需要显影定影等化学处理，又分为湿式（需自动冲洗）与干式（无药液、无废液）两类，干式又包含干式激光（光热成像）与直热式热敏两种。【为什么错】B错误：干式的含义是不使用化学药液处理，而非“不用晾干的湿式冲洗”。C错误：喷墨与激光是并列的两类原理，喷墨以墨滴沉积成像，不涉及激光曝光。D错误：湿式激光胶片以卤化银为感光材料，必须经显影、定影、水洗、干燥。E错误：直热式热敏成像不使用激光，而是由热敏头直接接触加热胶片。", "tr": "务必分清两组概念：“激光/热敏/喷墨”是能量与成像方式的分类，“湿式/干式”是有无化学处理的分类。干式激光≠热敏，前者“先光后热”，后者“只热无光”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0102", "t": "多选题", "s": "关于医用打印机的网络化应用，下列正确的有", "o": {"A": "在DICOM打印管理服务中，打印机作为服务类提供者（Print SCP），影像工作站或设备作为服务类用户（Print SCU）", "B": "网络打印可实现多台影像设备共享同一台相机，并按1×1、2×2、4×5等不同分格排版输出", "C": "打印机接收的是经窗宽窗位处理后的图像数据，其最终灰阶还受打印机内部查找表（LUT）影响", "D": "DICOM打印管理服务类与影像存储（Storage）服务类是同一服务，配置其一即可", "E": "胶片规格、介质类型、放大方式、边框与注释等可通过打印作业的相关参数指定"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-002", "kp": "医用打印机与DICOM打印服务", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】A正确：DICOM打印管理中，发送打印请求的一方为SCU，执行打印的相机为SCP，二者需完成关联协商。B正确：网络化后一台相机可服务于CT、MR、DR等多台设备，分格排版由打印作业参数控制。C正确：影像经窗技术映射为显示灰度后，还要经打印机LUT映射为胶片光学密度，任一环节设置不当都会造成打印与显示不一致。E正确：这些均属于基本胶片盒与图像盒参数。【为什么错】D错误：打印管理服务类（Print Management）与存储服务类（Storage）是两类不同的DICOM服务类，各自有独立的SOP类与配置，二者不能互相替代。", "tr": "“打印出来与显示器上看到的不一致”是临床常见问题，其根源通常在打印机LUT或未按GSDF校准，而不在图像数据本身。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-0103", "t": "单选题", "s": "关于医用胶片规格与打印空间分辨率，下列叙述错误的是", "o": {"A": "常用胶片规格包括14in×17in（约35cm×43cm）、11in×14in、8in×10in等", "B": "打印空间分辨率常以每英寸点数（dpi）或像素尺寸（μm）表示，激光相机多为300~650dpi", "C": "分格打印时每幅图像被缩小，实际呈现的细节较满幅打印下降", "D": "打印像素尺寸越小，可分辨的图像细节越丰富", "E": "胶片规格越大，打印机的空间分辨率就越高"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-003", "kp": "胶片规格与打印分辨率", "ch": "十三、图像打印技术 → 1.概述 → (3)胶片规格与输出参数", "ex": "【为什么对】E错误故为本题答案：空间分辨率取决于打印机的成像单元尺寸（激光束斑或热敏头发热点大小）与扫描点密度，是设备固有性能，与所用胶片幅面无关；同一台相机打印大小两种规格胶片，其dpi不变。【为什么错】A正确：这是医用胶片的常见规格。B正确：主流激光相机的分辨率区间即在此范围。C正确：分格打印把同样的成像点分配给更小的图像面积，图像被缩小后细节呈现下降。D正确：像素尺寸越小意味着单位长度内的成像点越多，细节表现越好。", "tr": "分清“胶片幅面”“打印分辨率”“原始图像矩阵”三者：只有原始矩阵与打印分辨率共同决定最终细节，幅面只影响观看尺寸。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "概述", "页": 355}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0104", "t": "多选题", "s": "关于激光打印机（激光相机）的基本结构与工作过程，下列正确的有", "o": {"A": "主要由激光发生器、光学系统（调制器、多面转镜或振镜、聚焦透镜）、胶片传输机构与控制电路等组成", "B": "调制器根据图像各像素的灰度值调制激光束强度，从而实现不同的曝光量", "C": "转镜使激光束沿胶片宽度方向作主扫描，胶片匀速移动完成副扫描，二者配合完成逐点曝光", "D": "激光束在胶片上直接“烧灼”出可见影像，不需要任何显影过程", "E": "湿式激光相机需配套自动冲洗装置完成显影、定影、水洗与干燥"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-004", "kp": "激光打印机结构与工作过程", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】A正确：这是激光相机的经典结构划分。B正确：声光调制器等按像素灰度调节激光强度（或脉冲宽度），是灰阶得以再现的关键环节。C正确：主扫描（横向、由转镜实现）与副扫描（纵向、由胶片走动实现）正交配合，完成整幅图像的逐点曝光。E正确：湿式系统必须配套化学冲洗流程。【为什么错】D错误：激光相机中激光的作用是“曝光”，在胶片感光层内形成不可见的潜影，必须再经化学显影（湿式）或热鼓加热显影（干式）才能转变为可见银影，激光本身并不直接烧灼出图像。", "tr": "“激光直接烧出影像”是最常见的错误理解。牢记：激光只负责按灰度曝光形成潜影，显影环节才产生可见密度。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-0105", "t": "单选题", "s": "关于激光相机所用光源，下列叙述正确的是", "o": {"A": "早期湿式激光相机多采用氦氖（He-Ne）气体激光器，波长632.8nm，属可见红光", "B": "He-Ne激光的波长为1064nm，属于红外波段", "C": "半导体激光二极管体积大、寿命短，已被He-Ne激光器全面取代", "D": "激光相机光源的波长与所配套胶片的光谱感光特性无关，可任意搭配", "E": "干式激光相机采用紫外激光对胶片曝光"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-005", "kp": "激光相机光源类型", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】A正确：He-Ne激光器输出632.8nm的可见红光，是早期湿式激光相机的典型光源，需配用对该波长敏感的红光感光胶片。【为什么错】B错误：1064nm是Nd:YAG激光的波长，He-Ne为632.8nm。C错误：发展趋势恰好相反，红光或红外半导体激光二极管体积小、效率高、寿命长、可直接调制，已在现代激光相机中取代He-Ne气体激光器。D错误：胶片必须与光源波长的光谱敏感度匹配，错配将导致曝光不足或密度异常，故不同机型的专用胶片不可混用。E错误：干式激光相机使用的是红光或红外激光二极管，不是紫外激光。", "tr": "光源与胶片必须“波长匹配”是本考点的核心，也解释了为什么各厂家胶片与相机通常不能互换使用。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0106", "t": "多选题", "s": "关于湿式激光胶片与干式激光胶片的比较，下列正确的有", "o": {"A": "湿式胶片以卤化银乳剂为感光材料，曝光形成潜影后需经显影、定影、水洗与干燥", "B": "干式激光胶片曝光形成潜影后由热鼓加热显影，无需化学药液，也不产生冲洗废液", "C": "干式激光成像属于光热成像，其过程可概括为“先光曝光、后热显影”", "D": "干式胶片成像完成后不再受热与光的影响，可在任意条件下长期保存", "E": "干式打印省去冲洗环节，具有环境污染小、可明室操作、维护简便等优点，已成为主流"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-006", "kp": "湿式与干式激光胶片", "ch": "十三、图像打印技术 → 2.激光成像 → (2)激光胶片与光学密度", "ex": "【为什么对】A正确：这是传统湿式银盐胶片的处理流程，需要暗室或胶片传输通道、定期更换药液并处理废液。B正确：干式激光胶片依靠约120℃左右的热鼓短时加热完成显影。C正确：光热成像（photothermographic）的定义即为光曝光形成潜影＋加热显影。E正确：这些正是干式技术取代湿式的原因。【为什么错】D错误：干式胶片成像层内的未反应银盐与还原剂仍然留存于片内（无定影去除步骤），因此成品仍具有一定的热与光敏感性，长期置于高温或强光下可出现整体密度升高、影像退化，必须按厂家要求避光避热保存。", "tr": "干式胶片“没有定影”这一点是理解其保存要求的关键：未被消耗的成像物质仍在片中，所以“怕热怕光”，不能与经过定影的湿式胶片等同看待。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-0107", "t": "单选题", "s": "干式激光成像与直热式（热敏）成像的本质区别在于", "o": {"A": "干式激光成像由激光按灰度曝光形成潜影后再加热显影；直热式成像不使用激光，由热敏头直接按灰阶加热胶片形成影像", "B": "两者都使用激光，区别仅在于激光波长不同", "C": "干式激光成像需要化学显影液，直热式成像不需要", "D": "直热式成像所用胶片不含银盐成分", "E": "干式激光成像过程中不需要任何加热"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-007", "kp": "光热成像与直热式成像的区别", "ch": "十三、图像打印技术 → 2.激光成像 → (2)激光胶片与光学密度", "ex": "【为什么对】A正确：干式激光相机的能量传递路径是“激光曝光→潜影→热鼓加热显影”，属于光热成像；直热式热敏相机没有光学曝光环节，热敏头以点阵接触方式对胶片逐行加热，加热能量的大小直接决定该点的密度，属于纯热成像。【为什么错】B错误：直热式不使用激光。C错误：两者同属干式，均不使用化学显影液。D错误：直热式胶片的成像层同样含有有机银盐微晶与还原剂，受热后银离子被还原生成金属银形成黑影。E错误：干式激光成像的显影环节正是靠加热完成的。", "tr": "两类干式技术的判别口诀：“干式激光＝先光后热，直热式＝有热无光”。二者的胶片、耗材与故障表现均不相同，不可混用。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0108", "t": "案例分析题", "s": "某影像科对新安装的干式激光相机进行验收测试。技师打印标准21阶灰阶测试图，用透射式密度计逐阶测量，结果显示：片基加灰雾密度为0.18，最大密度为3.20，各阶密度分布连续、无跳跃与并阶。据此对该相机密度性能作出的判断，正确的是", "o": {"A": "最大密度与最低密度均落在医用胶片的常规要求范围内（一般要求最大密度≥3.0、片基加灰雾≤0.25），密度性能合格", "B": "光学密度定义为透过光强与入射光强之比，其数值越大表示胶片越透明", "C": "最大密度只取决于打印机的激光功率，与所用胶片类型无关", "D": "特性曲线直线部的斜率反映胶片的感光度，与影像对比度无关", "E": "片基加灰雾密度升高有助于提高影像的整体对比度"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-008", "kp": "光学密度与胶片特性曲线", "ch": "十三、图像打印技术 → 2.激光成像 → (2)激光胶片与光学密度", "ex": "【为什么对】A正确：医用胶片一般要求最大密度不低于3.0（观片灯下才能保证足够的黑化与对比），片基加灰雾密度不高于0.25（过高会使亮区“发灰”、丢失低密度层次）；本例3.20与0.18均在合格范围，且各阶连续无并阶，说明灰阶再现良好。【为什么错】B错误：光学密度D＝lg(I₀/I)，是入射光强与透过光强之比的常用对数，D值越大透光越少、胶片越黑。C错误：最大密度由胶片成像层的银量、显影条件与打印机能量共同决定，不同型号胶片的最大密度不同。D错误：直线部斜率γ表示的是对比度；感光度由特性曲线在横轴上的相对位置（达到某一密度所需曝光量）决定。E错误：灰雾升高会抬高低密度端，压缩可用密度范围，使对比度下降而非提高。", "tr": "感光度与对比度的区分是特性曲线的经典考点：曲线“左右移动”反映感光度变化，“陡缓变化”反映对比度变化，二者不可混为一谈。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0109", "t": "多选题", "s": "关于灰阶校准与DICOM灰度标准显示函数（GSDF），下列正确的有", "o": {"A": "GSDF是DICOM标准第14部分定义的、基于人眼对比敏感度模型的感知线性化函数", "B": "按GSDF进行校准，可使同一幅图像在不同显示器与打印机上获得一致的灰阶感知效果", "C": "GSDF以恰可察觉差（JND）指数描述亮度等级，相邻JND之间的差异恰为人眼可觉察", "D": "医用打印机的灰阶校准可通过打印测试图、以密度计测量各阶密度并据此修正查找表（LUT）来实现", "E": "GSDF仅适用于医用显示器，医用打印机无需遵循该标准"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-009", "kp": "灰阶校准与DICOM GSDF", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】A正确：GSDF建立在Barten人眼对比敏感度模型基础上，目的是把设备的物理输出（亮度或密度）映射为人眼感知上均匀的灰阶。B正确：一致性是GSDF的根本目的，可保证诊断结论不因输出设备而变化。C正确：GSDF用JND指数作为标度，标准中将可用亮度范围划分为若干JND步长。D正确：这正是打印机灰阶校准的实际操作流程，测量值与GSDF目标曲线的偏差通过LUT修正。【为什么错】E错误：GSDF同时适用于显示（发光）与硬拷贝（透射）设备，对打印机而言以透射密度对应亮度进行映射，医用胶片输出同样应按GSDF校准。", "tr": "GSDF不是“统一亮度或密度数值”，而是统一“感知”。校准后的显示器与相机在物理亮度、密度上可以不同，但人眼看到的灰阶层次变化是一致的。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-0110", "t": "单选题", "s": "关于直热式（热敏）打印的成像原理，下列叙述错误的是", "o": {"A": "热敏头由排列成线阵的微型发热电阻构成，与胶片直接接触逐行加热", "B": "影像灰阶由每个发热点的加热能量（脉冲宽度、温度）控制，能量越大该点密度越高", "C": "受热部位的有机银盐与还原剂发生反应，析出金属银微粒形成黑影", "D": "成像过程中无化学药液参与，也没有废液排放", "E": "热敏成像是以激光束扫描加热胶片实现的，属于光热成像范畴"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-010", "kp": "直热式热敏成像原理", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (1)直热式成像原理", "ex": "【为什么对】E错误故为本题答案：直热式热敏成像不使用任何光学曝光，其能量来源是热敏头电阻发热并通过接触传导至胶片；光热成像特指干式激光成像（先激光曝光形成潜影，后加热显影），二者不能混淆。【为什么错】A正确：热敏头（TPH）为接触式线阵结构，胶片走过时逐行加热。B正确：灰阶通过控制每个发热点的通电脉冲宽度与温度来实现，是热敏成像灰阶再现的基础。C正确：这是热敏胶片的成像化学过程。D正确：无药液、无废液是干式打印的共同优点。", "tr": "本题与干式激光成像题互为镜像。判断要点只有一个：有没有光学曝光环节——有则为光热成像（干式激光），无则为直热式热敏。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0111", "t": "单选题", "s": "关于热敏打印机的热敏头（TPH），下列叙述错误的是", "o": {"A": "热敏头与胶片直接接触传热，属接触式成像方式", "B": "常见热敏打印的点密度约为300~320dpi，空间分辨率一般略低于高端激光相机", "C": "热敏头表面沾污或个别发热电阻损坏，可造成沿走片方向的固定白线或黑线伪影", "D": "热敏头需要良好的散热与温度反馈控制，以保证连续打印时的密度稳定", "E": "热敏头发热点温度越高越好，可无限制地提高胶片的最大密度"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-011", "kp": "热敏头结构与性能", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (2)热敏胶片与热敏头", "ex": "【为什么对】E错误故为本题答案：胶片的最大密度受成像层含银量与化学反应程度限制，达到饱和后再升温也不会继续增高密度；温度过高反而会损伤热敏头、造成胶片与热敏头粘连、保护层熔损与打印畸变，并加速热敏头老化。【为什么错】A正确：接触加热是直热式的基本特征，也决定了热敏头易受污染磨损。B正确：热敏点密度受发热电阻加工尺寸限制，通常略低于激光相机。C正确：单个发热点失效或污染在连续走片过程中形成沿纵向的固定线状伪影，是热敏相机的特征性故障表现。D正确：连续打印会导致热敏头蓄热，需依靠温度反馈动态调整加热能量，否则后续胶片密度会漂移。", "tr": "热敏相机的“固定位置线状伪影”与激光相机的“扫描方向条纹”定位思路不同：前者多为热敏头缺陷，后者多与转镜、激光调制或走片速度不稳有关。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0112", "t": "多选题", "s": "关于干式热敏胶片的结构与特性，下列正确的有", "o": {"A": "由片基、热敏成像层与表面保护层等构成，成像层内含有机银盐微晶、还原剂与调色剂", "B": "受热区域银离子被还原为金属银微粒，从而形成黑色影像", "C": "未受热区域的成像物质仍保留在胶片内，因此成品胶片应避热、避光保存", "D": "热敏胶片可在强光直射与高温环境下长期存放而不发生密度变化", "E": "表面保护层可减少胶片与热敏头之间的摩擦和粘连，保护热敏头"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-012", "kp": "热敏胶片结构与银盐微晶", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (2)热敏胶片与热敏头", "ex": "【为什么对】A正确：热敏胶片以有机银盐（如脂肪酸银）微晶为成像主体，配以还原剂与调色剂控制影像色调。B正确：受热处发生氧化还原反应析出金属银微粒，密度与析出银量成正比。C正确：因无定影步骤，未反应成分留存片内，属于本类胶片必须避热避光保存的根本原因。E正确：保护层兼具润滑与防粘作用，是保证热敏头寿命与打印质量的重要结构。【为什么错】D错误：与C相矛盾，高温与强光会使未反应的银盐继续被还原，出现整体密度升高、影像“发灰”甚至图像退化。", "tr": "把干式胶片的“无需暗室装片”误解为“不怕光”。正确表述是：明室装片可以（对室内一般照明不敏感），但不能强光直射与长期高温存放。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-0113", "t": "案例分析题", "s": "某院干式热敏相机近期打印的胸部影像出现两类质量问题：①整幅图像密度普遍偏低、层次发灰，与显示器所见明显不符，更换新一批胶片后无改善；②沿胶片长轴出现一条位置固定的细白线，贯穿所有打印张，更换胶片盒后依然存在。技师对上述问题进行排查分析，下列判断正确的是", "o": {"A": "问题①多与热敏头加热能量不足、走片速度过快、胶片批次与校准查找表不匹配或环境温度过低等因素有关，应重新执行密度与灰阶校准；问题②提示热敏头个别发热点损坏或表面污染，应先清洁热敏头，无效则更换热敏头", "B": "问题①与②均由PACS网络传输过程中的数据丢失引起，应重启网络交换机", "C": "问题①可通过提高诊断显示器亮度来解决", "D": "问题②是胶片乳剂面被划伤所致，与打印机无关，更换胶片品牌即可解决", "E": "问题①与②均提示X线平板探测器性能下降，应联系工程师更换探测器"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-013", "kp": "影响热敏打印质量的因素", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】A正确：热敏打印密度取决于“加热能量×作用时间”，能量不足、走片过快、环境温度过低或胶片型号批次与校准LUT不匹配，都会使整体密度下降、层次压缩，处理办法是核对胶片型号并重新校准；而位置固定、贯穿所有胶片的纵向白线是热敏头单点失效或污染的特征表现，因为该点在每次走片时都作用在同一横向位置。【为什么错】B错误：网络数据丢失会表现为图像缺失、错位或打印任务失败，不会造成整体密度偏低与固定线状伪影。C错误：显示器亮度与打印输出属于两个独立环节，调高显示器亮度只会让二者差异更大。D错误：更换胶片盒后伪影依旧，已排除胶片因素。E错误：探测器问题会在显示器上同样可见，而本例显示器所见正常。", "tr": "排查思路要抓“变量控制”：更换胶片后仍存在→问题在设备端；显示器正常而胶片异常→问题在打印链路而非采集链路。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U13-0114", "t": "单选题", "s": "关于干式打印胶片的储存与使用，下列叙述错误的是", "o": {"A": "应在厂家规定的温湿度范围内避光保存，远离热源与阳光直射", "B": "干式胶片可在明室条件下装片，无需暗室操作", "C": "打印后的干式胶片长期置于高温环境，可出现密度升高或影像退化", "D": "不同厂家的干式胶片与打印机通常不能互换使用", "E": "干式胶片打印后可用普通定影液处理，以进一步提高其保存性"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-014", "kp": "干式胶片的保存与使用", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】E错误故为本题答案：干式胶片的成像与显影过程完全不涉及液体化学处理，其成像层结构也不适合水溶液处理；用定影液浸泡会破坏保护层与成像层，造成影像损毁，绝不可这样操作。【为什么错】A正确：这是干式胶片的基本保存要求。B正确：干式胶片对室内一般照明不敏感，可明室装片，这是其操作便利性的体现。C正确：因未经定影，残留成像物质在高温下会继续反应。D正确：胶片的感光/感热特性、厚度与保护层均与特定机型的校准参数配套，混用会导致密度与灰阶异常甚至卡片。", "tr": "抓住“干式无定影”这一条主线，就能同时解释：为什么怕热怕强光、为什么不能用定影液、为什么胶片与机器必须配套。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "概述", "页": 355}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0115", "t": "单选题", "s": "关于喷墨打印的成像方式，下列叙述正确的是", "o": {"A": "按需喷墨主要有热气泡式与压电式两类，前者靠加热墨水产生气泡挤出墨滴，后者靠压电晶体形变挤出墨滴", "B": "喷墨打印属于银盐成像技术的一种", "C": "喷墨打印过程必须在暗室条件下进行", "D": "压电式喷墨依靠激光加热墨水形成墨滴", "E": "喷墨打印的墨滴大小不可控制，因而无法表现连续灰阶"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-015", "kp": "喷墨成像原理", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】A正确：喷墨按是否连续出墨分为连续式与按需式（DOD），按需式又分热气泡式（加热元件使墨水局部汽化形成气泡将墨滴挤出）与压电式（压电陶瓷通电变形挤压墨腔），这是喷墨技术的基本分类。【为什么错】B错误：喷墨以墨水（染料或颜料）沉积于介质表面成像，不含银盐感光成像过程。C错误：喷墨对光不敏感，完全可在明室操作。D错误：压电式不使用激光，加热的是热气泡式。E错误：现代喷墨可通过控制墨滴体积与网点密度（半色调技术）表现丰富的灰阶与色彩。", "tr": "热气泡式“用热”但与热敏成像完全不同：前者加热的是墨水以喷出墨滴，后者加热的是胶片成像层引发化学反应。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0116", "t": "多选题", "s": "关于喷墨成像在医学影像输出中的应用，下列正确的有", "o": {"A": "设备与耗材成本较低，可输出彩色图像，适用于报告、示教资料及超声、内镜图片的打印", "B": "多使用普通纸或专用相纸，透光性差，一般不适合在观片灯下阅读", "C": "最大光学密度与灰阶层次不及激光、热敏胶片，长期保存易褪色、遇水易扩散", "D": "喷墨输出的图像质量已达到诊断用医用胶片标准，可全面替代激光相机", "E": "喷墨输出可作为患者自取的辅助资料，正式诊断用影像仍以胶片或PACS电子影像为准"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-016", "kp": "喷墨成像的临床应用与局限", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】A正确：低成本与彩色输出能力使喷墨适合非诊断性的辅助资料输出。B正确：反射式介质需依靠环境光观看，与透射式胶片的观片灯阅读方式不同。C正确：染料墨水的密度范围与耐久性都明显不及银盐成像，是其难以用于诊断的核心原因。E正确：这是目前临床对喷墨输出的合理定位。【为什么错】D错误：喷墨在最大密度、灰阶层次、空间分辨率一致性与长期保存性上均不能满足诊断用硬拷贝要求，不能替代激光或热敏相机。", "tr": "喷墨在考纲中属“了解”层次，命题多围绕“定位”出题：它是辅助输出手段，优点是成本与彩色，缺点是密度、耐久与透光性，不能承担诊断职能。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-0117", "t": "单选题", "s": "关于医用照片自主（自助）打印机的应用，下列叙述错误的是", "o": {"A": "患者可凭检查条码单、就诊卡或身份证在自助终端查询本人影像并自助打印胶片与报告", "B": "自助终端需与PACS/RIS集成，打印前完成身份核验与权限控制", "C": "可减少人工发放胶片的工作量、缩短患者等待时间", "D": "终端应具备打印失败重试、耗材不足报警与操作日志记录等功能", "E": "为方便患者取片，自助终端应允许凭姓名模糊查询并打印他人影像"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-017", "kp": "照片自主打印机的功能与管理", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】E错误故为本题答案：影像资料属于患者隐私与医疗数据，自助打印必须做到“一人一证一验”，凭唯一标识（条码、就诊卡、身份证或取件码）核验后才能调阅打印；允许姓名模糊查询将造成他人影像被误取或恶意获取，严重违反隐私保护与信息安全要求。【为什么错】A正确：这是自助打印的常规使用方式。B正确：与PACS/RIS集成并完成身份核验是自助打印的技术前提。C正确：分流取片人流、减少人工是其主要价值。D正确：无人值守设备必须具备异常处理与日志追溯能力。", "tr": "凡涉及自助设备与信息系统的题目，“便捷性”永远不能凌驾于“身份核验与隐私保护”之上，以便捷为由削弱核验的选项均为错误项。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-0118", "t": "案例分析题", "s": "某三甲医院在门诊大厅部署8台自助胶片打印终端。上线运行后陆续出现两类问题：部分患者反映“系统提示查不到影像”，但其检查确已完成；另有个别患者打印出的胶片分格方式与既往不同，图像明显缩小。信息科与影像技术组联合排查。下列排查方向与处理最合理的是", "o": {"A": "应核查检查是否已完成技师提交与报告审核并归档至PACS、终端与PACS之间的网络与DICOM服务是否正常，同时检查各终端的打印协议（分格、胶片规格、放大方式、查找表）是否与科室统一模板一致", "B": "“查不到影像”一定是打印机硬件故障，应逐台更换打印机", "C": "不同终端打印分格不同属于正常现象，无需统一", "D": "应取消身份核验环节以加快查询响应速度", "E": "应在开单时即自动打印所有检查的胶片，从根本上避免查询问题"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-018", "kp": "自助打印系统集成与故障排查", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】A正确：“查不到影像”的常见原因依次为检查未提交或报告未审核发布、影像尚未完整归档、终端与PACS网络或DICOM查询检索服务异常、患者标识匹配失败；“分格不一致”则属于终端打印协议配置不统一，应以科室统一模板批量下发并锁定，避免各终端参数漂移。【为什么错】B错误：查询失败属于数据与网络层面问题，与打印硬件无关，且不可能8台同时硬件故障。C错误：打印规格不统一会影响阅片一致性与外院互认，必须统一。D错误：取消身份核验会造成隐私泄露与错取，属严重违规。E错误：开单即打印会造成大量废片、增加成本，且此时检查尚未完成，逻辑上不成立。", "tr": "此类系统性问题应按“数据源—网络与服务—终端配置”的层级顺序排查；凡是以牺牲核验流程或大量浪费耗材为代价的“解决方案”都不可取。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1001", "t": "单选题", "s": "医用激光相机的成像核心部件是", "o": {"A": "激光扫描装置与激光胶片", "B": "热敏打印头", "C": "喷墨打印头", "D": "高压发生器", "E": "影像增强器"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-101", "kp": "激光相机结构", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】激光相机用激光扫描装置将图像信号逐点扫描到激光胶片上完成曝光，激光源与胶片是核心部件，故A正确。\n【为什么错】B：热敏打印头是热敏相机的部件。C：喷墨打印头是喷墨打印机的部件。D：高压发生器属于X线设备。E：影像增强器属于透视/DSA设备，均与激光相机无关。", "tr": "激光相机“激光扫描曝光”，热敏相机“热敏头加热”，喷墨“喷头喷墨”，三类设备核心部件不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1002", "t": "单选题", "s": "湿式激光相机与干式激光相机的根本区别在于", "o": {"A": "湿式需要化学药液（显影、定影）处理胶片", "B": "湿式不需要激光", "C": "干式需要显影液", "D": "干式使用普通纸张", "E": "两者原理完全相同"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-102", "kp": "湿式与干式激光成像", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】湿式激光相机曝光后需经显影、定影等化学药液处理成像，干式则采用干式热显影工艺无需药液，故A正确。\n【为什么错】B：湿式同样使用激光扫描。C：干式无需显影液。D：干式使用专用干式胶片而非纸张。E：两者成像原理（激光扫描）相同但显影工艺不同，不能说完全相同。", "tr": "干、湿式激光相机的差异在“显影方式”，激光扫描部分相同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1003", "t": "单选题", "s": "干式激光相机的突出优点是", "o": {"A": "无需化学药液、环保且即打即用", "B": "必须配备暗室", "C": "需要冲洗管路", "D": "必须使用湿式胶片", "E": "只能打印黑白图像"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-103", "kp": "干式激光成像优点", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】干式激光相机无需显影、定影药液，无化学废液排放，设备紧凑，打印快速即打即用，故A正确。\n【为什么错】B：干式不需要暗室，可在明室使用。C：干式无需冲洗管路。D：干式使用专用干式胶片。E：干式激光相机同样可打印黑白诊断图像，也能支持彩色，说“只能打印黑白”不准确。", "tr": "干式打印机“明室操作、无药液、即打即用”是区别于湿式的三大特点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1004", "t": "单选题", "s": "直接热敏成像技术中，使胶片产生灰阶密度变化的部件是", "o": {"A": "热敏打印头（热敏头）", "B": "激光扫描器", "C": "喷墨喷嘴", "D": "影像增强器", "E": "光电倍增管"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-104", "kp": "热敏成像原理", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (1)直热式成像原理", "ex": "【为什么对】直接热敏（直热式）打印机依靠热敏打印头对热敏胶片加热，使其热敏层发生化学变化而显色，故A正确。\n【为什么错】B：激光扫描器是激光相机的部件。C：喷墨喷嘴是喷墨打印机部件。D：影像增强器属X线影像设备。E：光电倍增管用于光电探测，均与热敏加热成像无关。", "tr": "热敏成像的关键词是“加热”，热敏头加热→胶片显色。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1005", "t": "单选题", "s": "热敏打印机控制图像灰阶（密度）的主要方式是", "o": {"A": "调节热敏头的加热能量（温度与时间）", "B": "调节激光强度", "C": "更换墨盒颜色", "D": "调整胶片尺寸", "E": "改变纸张湿度"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-105", "kp": "热敏打印灰阶控制", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (1)直热式成像原理", "ex": "【为什么对】热敏打印通过改变热敏头加热元件施加的能量（如脉冲宽度、功率），使胶片获得不同灰阶密度，故A正确。\n【为什么错】B：调节激光强度是激光相机控制曝光的方式。C：墨盒颜色是喷墨打印的概念。D：胶片尺寸不影响灰阶。E：湿度是环境因素而非控制手段。", "tr": "热敏打印“以热能控灰阶”，激光打印“以光强控灰阶”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1006", "t": "单选题", "s": "医用喷墨打印中，具有防水、耐光性能更好特点的墨水是", "o": {"A": "颜料墨水", "B": "染料墨水", "C": "食用墨水", "D": "热敏墨水", "E": "激光墨水"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-106", "kp": "喷墨墨水类型", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】颜料墨水以不溶性颜料颗粒悬浮为色料，附着力强，防水、耐光性能明显优于染料墨水，适合医学图像的长期保存，故A正确。\n【为什么错】B：染料墨水色彩鲜艳但易褪色、怕水。C：食用墨水与医学打印无关。D：热敏墨水概念不存在。E：激光打印用碳粉/胶片而非墨水。", "tr": "医用喷墨打印为保长期保存效果应选用颜料墨水，而非普通染料墨水。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1007", "t": "单选题", "s": "医用胶片常见的尺寸规格（英寸）不包括", "o": {"A": "14×17", "B": "8×10", "C": "10×12", "D": "11×14", "E": "20×30"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-107", "kp": "医用胶片规格", "ch": "十三、图像打印技术 → 1.概述 → (3)胶片规格与输出参数", "ex": "【为什么对】医用胶片常用规格为14×17、11×14、10×12、8×10等英寸规格，20×30不是医用常规胶片尺寸，故E正确。\n【为什么错】A：14×17是医用常规胶片尺寸。B：8×10是医用常规尺寸。C：10×12是医用常规尺寸。D：11×14是医用常规尺寸，均为常用规格故不符合题意。", "tr": "医用胶片用“英寸”表示尺寸，常用14×17、8×10等，属记忆考点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1008", "t": "单选题", "s": "照片自主打印机（自助取片机）与PACS、RIS对接获取打印任务，最常用的方式是", "o": {"A": "通过网络按患者条码或卡号调取已完成的影像与报告", "B": "人工U盘拷贝", "C": "电话人工预约", "D": "传真传输", "E": "邮寄胶片"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-108", "kp": "自助打印工作流程", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】自助打印机通过网络连接PACS/RIS，患者凭条码、就诊卡等识别身份后，系统自动调取已完成检查的影像与报告并打印，故A正确。\n【为什么错】B：U盘拷贝不适用大规模自助场景。C：电话预约是登记环节而非打印流程。D：传真不适合影像传输。E：邮寄胶片不具备即时性，均与自助打印不符。", "tr": "自助打印依托PACS/RIS的网络调取，以患者条码或卡号为身份凭证。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1009", "t": "单选题", "s": "为保证不同打印机、显示器之间图像显示一致，医用打印与显示系统应遵循的灰阶标准是", "o": {"A": "DICOM灰阶标准显示函数（GSDF）", "B": "JPEG压缩标准", "C": "MPEG视频标准", "D": "HL7消息标准", "E": "IHE集成框架"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-109", "kp": "灰阶校准标准", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】GSDF（Grayscale Standard Display Function）规定数字值与人眼感知亮度之间的标准关系，使打印胶片与显示器观片效果一致，故A正确。\n【为什么错】B：JPEG是图像压缩标准。C：MPEG是视频压缩标准。D：HL7是文本信息交换标准。E：IHE是应用集成框架，均非灰阶校准标准。", "tr": "GSDF是显示/打印灰阶一致性的核心标准，与其他DICOM服务、压缩标准区分。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1010", "t": "单选题", "s": "DICOM打印管理服务中，发出打印任务的一端称为", "o": {"A": "打印SCU（服务类用户）", "B": "打印SCP（服务类提供者）", "C": "影像存储SCP", "D": "查询/检索SCU", "E": "数据库服务器"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-110", "kp": "DICOM打印服务角色", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】DICOM打印服务中，发出打印请求的工作站/设备是服务类用户（SCU），打印机作为服务类提供者（SCP）接收并执行打印，故A正确。\n【为什么错】B：SCP是接收并执行的打印服务器/打印机。C：影像存储SCP是接收图像的归档端。D：查询/检索SCU用于调阅。E：数据库服务器与打印角色无关。", "tr": "SCU=请求方（发出打印任务），SCP=提供方（执行打印），方向勿颠倒。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1011", "t": "单选题", "s": "将多幅CT轴位图像以2×3等排版打印到一张14×17胶片上，应通过打印服务设置", "o": {"A": "胶片格式与排版布局", "B": "图像压缩比", "C": "存储路径", "D": "患者密码", "E": "网络带宽"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-111", "kp": "打印排版设置", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】DICOM打印服务支持定义胶片格式（尺寸）与排版布局（每张胶片上图像的行列数），实现多幅图像组合打印，故A正确。\n【为什么错】B：压缩比影响文件大小与存储。C：存储路径决定保存位置。D：患者密码与打印无关。E：网络带宽影响传输速度，均与排版无关。", "tr": "“几乘几排版”由打印服务胶片格式中的行列参数决定。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1012", "t": "单选题", "s": "激光相机中，像素灰度值（图像数据）对激光束的作用是", "o": {"A": "控制激光强度（曝光量）从而影响胶片密度", "B": "控制胶片尺寸", "C": "控制显影液温度", "D": "控制打印数量", "E": "控制网络速度"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-112", "kp": "激光成像灰度调制", "ch": "十三、图像打印技术 → 2.激光成像 → (2)激光胶片与光学密度", "ex": "【为什么对】图像数据经D/A转换后调制激光束强度，激光强度决定胶片感光量，感光量决定显影后的光学密度，实现灰度还原，故A正确。\n【为什么错】B：胶片尺寸由打印排版决定。C：激光相机（尤其干式）无显影液温控概念。D：打印数量由任务管理决定。E：网络速度属传输层，均与像素灰度成像无关。", "tr": "灰度值→激光强度→曝光量→光学密度，是一条完整的激光成像信号链。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U13-1013", "t": "单选题", "s": "热敏打印头的分辨能力通常用下列哪项描述", "o": {"A": "每毫米（或每英寸）打印点数", "B": "每幅图像字节数", "C": "胶片灰阶密度值", "D": "激光波长", "E": "打印速度（张/小时）"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-113", "kp": "热敏打印头分辨率", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (2)热敏胶片与热敏头", "ex": "【为什么对】热敏打印头由密集排列的加热元件组成，其分辨能力以单位长度（毫米或英寸）内加热点数表示，点数越多分辨率越高，故A正确。\n【为什么错】B：字节数反映数据量。C：光学密度反映胶片黑化程度。D：激光波长是激光相机参数。E：打印速度反映效率，均非分辨能力的度量。", "tr": "打印分辨率=单位长度点数（dpi或点/mm），与图像数据量、密度值不同概念。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1014", "t": "单选题", "s": "激光相机打印的胶片出现灰阶层次缺失、高光区域明显断层，首先应进行的处理是", "o": {"A": "重新校准灰阶（打印SMPTE测试片校准）", "B": "更换网络线缆", "C": "调整胶片尺寸", "D": "重新启动计算机", "E": "增加存储容量"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-114", "kp": "打印质量故障处理", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】灰阶断层、层次缺失多由灰阶校准漂移引起，打印SMPTE测试片并重新校准可恢复正确的灰阶映射，故A正确。\n【为什么错】B：网络线缆故障表现为任务无法传输而非灰阶异常。C：胶片尺寸影响版面不影响灰阶。D：重启计算机无法修复校准漂移。E：存储容量与打印灰阶无关。", "tr": "灰阶异常优先查“校准”，SMPTE测试片是验证打印灰阶的常用手段。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1015", "t": "单选题", "s": "干式激光相机实现激光到热的转换、进而使胶片显影的结构或原理是", "o": {"A": "激光束使胶片热敏层吸收光能转化为热能而显影", "B": "激光直接雕刻胶片", "C": "激光加热显影液", "D": "激光发射紫外线消毒", "E": "激光与胶片无任何作用"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-115", "kp": "干式激光成像原理", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】干式激光相机的胶片热敏层吸收激光光能后转变为热能，在热显影（加热鼓或加热板）作用下发生化学反应显影，即“光-热-化学”成像，故A正确。\n【为什么错】B：激光不雕刻胶片。C：干式无需显影液。D：紫外线消毒与成像无关。E：激光与胶片必然发生能量作用才能成像。", "tr": "干式激光成像本质是“光转热”，与直热式“电加热”路径不同但落点同为热敏层。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1016", "t": "单选题", "s": "医用彩色喷墨打印中，用于合成各种颜色的基本墨水色是", "o": {"A": "青、品红、黄（CMY）", "B": "红、绿、蓝（RGB）", "C": "黑、白、灰", "D": "黄、蓝、红", "E": "品红、青、绿"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-116", "kp": "喷墨打印颜色模型", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】彩色喷墨打印采用减色法，以青（Cyan）、品红（Magenta）、黄（Yellow）三色（加黑K成CMYK）合成各种颜色，故A正确。\n【为什么错】B：RGB是显示器发光的加色模型。C：黑白灰不是喷墨基础色组合。D：黄蓝红不是标准三原色组合。E：品红青绿缺少黄色，均非喷墨基础色。", "tr": "打印是减色法CMYK，显示是加色法RGB，两者颜色模型不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1017", "t": "单选题", "s": "热敏打印机打印的胶片整体偏白、密度不足，最可能的原因是", "o": {"A": "热敏头加热能量不足", "B": "墨水用完", "C": "激光功率过高", "D": "胶片尺寸设置错误", "E": "网络带宽不足"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-117", "kp": "热敏打印密度不足分析", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】热敏打印密度由加热能量决定，整体密度不足说明热敏头温度/能量偏低（如热敏头老化、清洁不良或能量设置过低），故A正确。\n【为什么错】B：热敏打印不用墨水。C：激光功率是激光相机的参数。D：胶片尺寸影响版面不影响密度。E：带宽影响传输速度，与成像密度无关。", "tr": "热敏打印“密度偏白→加热不足”，激光打印“密度偏白→曝光不足”，对应机制不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U13-1018", "t": "单选题", "s": "患者在自助取片机上完成影像胶片与报告打印，正确流程是", "o": {"A": "扫描条码或刷卡验证身份→系统调取图像报告→自动打印→取走核对", "B": "任意触摸屏幕直接打印全部影像", "C": "告知护士姓名由护士代取", "D": "手机拍摄屏幕照片", "E": "等待电话通知后人工领取"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-118", "kp": "自助打印操作流程", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】自助打印通过条码/就诊卡验证身份，系统从PACS/RIS调取该患者的影像与报告自动打印，患者领取后核对，流程闭环，故A正确。\n【为什么错】B：须先验证身份避免信息泄露。C：人工代取违背自助设计且易错。D：手机拍照不具合规性。E：人工通知领取非自助流程，均错误。", "tr": "自助打印的前提是“身份验证+系统自动调取”，保障个人隐私与准确性。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1019", "t": "多选题", "s": "激光相机的组成部分包括", "o": {"A": "激光扫描系统", "B": "激光胶片", "C": "胶片传输与显影/热显影系统", "D": "灰度调制电路", "E": "热敏打印头"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-119", "kp": "激光相机组成", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】激光相机由激光扫描系统、灰度调制电路、激光胶片及传输、显影（湿式药液/干式热显影）系统等组成，故A、B、C、D正确。\n【为什么错】E：热敏打印头属于热敏成像设备，不属于激光相机。", "tr": "激光相机核心是“激光+胶片”，热敏头是热敏打印机的核心。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-1020", "t": "多选题", "s": "热敏成像技术的优点包括", "o": {"A": "干式操作、无需化学药液", "B": "设备结构相对简单、即打即用", "C": "无废液排放、环保", "D": "成像灰度稳定且易于维护", "E": "必须使用湿式胶片"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-120", "kp": "热敏成像优点", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (1)直热式成像原理", "ex": "【为什么对】热敏打印干式操作无需药液、结构简单、即打即用、无废液排放环保、维护方便，故A、B、C、D正确。\n【为什么错】E：热敏打印使用专用热敏胶片，不是湿式胶片。", "tr": "热敏与干式激光同属“干式”打印，均不用化学药液。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-1021", "t": "多选题", "s": "喷墨打印技术在医学图像输出中的特点包括", "o": {"A": "可实现彩色图像打印", "B": "使用颜料墨水可防水耐光", "C": "设备成本相对较低", "D": "可用于报告与图像的复合输出", "E": "打印无需任何耗材"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-121", "kp": "喷墨成像特点", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】喷墨打印支持彩色，颜料墨水防水耐光，设备与耗材成本较低，可同时输出图文报告，故A、B、C、D正确。\n【为什么错】E：喷墨打印需要墨水与纸张等耗材，并非无耗材。", "tr": "喷墨打印的耗材是墨水与介质，颜料墨水是长期保存的关键。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-1022", "t": "多选题", "s": "DICOM打印管理服务支持的功能包括", "o": {"A": "定义胶片尺寸与格式", "B": "设置多幅图像排版布局", "C": "指定灰度与打印数量", "D": "管理打印任务状态", "E": "执行图像压缩算法"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-122", "kp": "DICOM打印管理功能", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】DICOM打印服务可设定胶片规格、排版布局、灰阶特性、打印份数并回报任务状态，故A、B、C、D正确。\n【为什么错】E：图像压缩由存储/传输环节处理，不属于打印管理服务功能。", "tr": "打印管理管“印什么、印多少、印成什么样”，不管数据压缩。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-1023", "t": "多选题", "s": "影响打印胶片图像质量的因素包括", "o": {"A": "打印分辨率", "B": "灰阶校准状态", "C": "胶片光学密度特性", "D": "打印设备清洁与维护状况", "E": "患者姓名输入方式"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-123", "kp": "打印质量影响因素", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】分辨率决定细节，校准决定灰阶准确性，胶片密度特性决定层次，设备清洁维护影响均匀性与伪影，故A、B、C、D正确。\n【为什么错】E：患者姓名输入方式仅影响文字标注，与图像打印质量无关。", "tr": "打印质量由“分辨率+校准+介质+维护”共同决定，操作习惯不影响成像质量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-1024", "t": "多选题", "s": "激光相机与热敏相机在成像原理上的主要区别包括", "o": {"A": "激光相机用激光束扫描曝光", "B": "热敏相机用热敏头加热显影", "C": "激光相机灰阶由激光强度调制", "D": "热敏相机灰阶由加热能量调制", "E": "两者均必须使用湿式化学显影"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-124", "kp": "激光与热敏成像原理比较", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】激光相机以激光束逐点扫描曝光、灰阶由激光强度调制；热敏相机以热敏头加热热敏胶片、灰阶由加热能量调制，故A、B、C、D正确。\n【为什么错】E：两者均支持干式工艺，无需湿式化学显影，说法错误。", "tr": "“光调制”与“热调制”是两类干式打印的根本区别，均不需药液。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U13-1025", "t": "多选题", "s": "照片自主打印机应具备的功能包括", "o": {"A": "条码/就诊卡身份识别", "B": "胶片与报告双介质输出", "C": "与PACS/RIS网络互联自动调取", "D": "缺纸、卡纸等故障自动提示", "E": "自动判读影像并出具诊断"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-125", "kp": "自助打印机功能要求", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】自助打印机需身份识别、胶片/报告双介质输出、与PACS/RIS互联调取、故障自动提示保障无人值守运行，故A、B、C、D正确。\n【为什么错】E：诊断结论由医师出具，自助打印机不具备影像判读功能。", "tr": "自助机是“打印+分发”终端，诊断功能不属于其职责。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-1026", "t": "多选题", "s": "医学图像打印可使用的输出介质包括", "o": {"A": "干式激光胶片", "B": "湿式激光胶片", "C": "热敏胶片", "D": "喷墨打印纸", "E": "荧光显示屏"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-126", "kp": "打印输出介质", "ch": "十三、图像打印技术 → 1.概述 → (1)图像打印技术的分类与发展", "ex": "【为什么对】干式/湿式激光胶片、热敏胶片、喷墨介质（相纸、胶片替代品）均为打印输出介质，故A、B、C、D正确。\n【为什么错】E：荧光显示屏是显示输出设备，不是打印介质。", "tr": "打印=硬拷贝（胶片/纸张），显示=软拷贝（屏幕），二者介质不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-1027", "t": "多选题", "s": "保障医用打印输出质量的措施包括", "o": {"A": "定期打印SMPTE测试片校验", "B": "按DICOM GSDF进行灰阶校准", "C": "定期清洁打印头与光学系统", "D": "规范胶片存储环境", "E": "关闭打印机日志功能"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-127", "kp": "打印质量控制措施", "ch": "十三、图像打印技术 → 1.概述 → (3)胶片规格与输出参数", "ex": "【为什么对】SMPTE测试片可验证灰阶，GSDF校准保证一致性，清洁打印头/光学系统减少伪影，规范胶片存储避免受潮变质，故A、B、C、D正确。\n【为什么错】E：日志记录有助于故障排查与质量追溯，关闭日志不利质量控制。", "tr": "打印质控=测试片+校准+维护+环境，四者缺一不可。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U13-1028", "t": "多选题", "s": "打印胶片整体发黑、密度过高的可能原因包括", "o": {"A": "激光相机曝光过度", "B": "热敏头加热能量过高", "C": "灰阶校准错误导致信号放大", "D": "胶片意外被可见光曝光", "E": "胶片受潮"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-128", "kp": "打印密度过高原因分析", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】激光曝光过度、热敏能量过高、校准错误均可使密度过高；胶片被可见光意外曝光也会整体变黑，故A、B、C、D正确。\n【为什么错】E：胶片受潮多导致灰雾与斑点，通常不会表现为整体密度明显增高。", "tr": "密度过高优先查“曝光/能量/校准”，密度不足同理反向排查。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U13-1029a", "t": "共用题干题", "s": "要使CT工作站能够向新打印机发送打印任务，配置中最关键的是", "o": {"A": "配置打印机的网络地址并建立DICOM打印服务连接", "B": "调整显示器亮度", "C": "更换打印头", "D": "修改胶片厚度", "E": "升级操作系统"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-129", "kp": "打印网络配置", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】设备间通过DICOM打印服务通信，需正确配置打印机的IP地址并完成服务关联（AE Title等），CT工作站才能下发打印任务，故A正确。\n【为什么错】B：显示器亮度与打印无关。C：新打印机打印头正常，无需更换。D：胶片厚度非软件配置项。E：操作系统升级不解决打印连接问题。", "tr": "网络打印的前提是“IP+AE Title+DICOM打印服务”三要素配置正确。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1301", "gs": "某医院放射科新增一台干式激光相机用于CT胶片打印，需接入医院网络并与PACS打印服务器通信。技师负责初始配置与打印测试，并发现首张试打印胶片灰阶层次不佳。"}, {"id": "U13-1029b", "t": "共用题干题", "s": "试打印胶片灰阶层次差、亮部细节丢失，技师应首先采取的措施是", "o": {"A": "打印SMPTE测试片并重新进行灰阶校准", "B": "更换整箱胶片", "C": "加大网络带宽", "D": "增加打印机数量", "E": "关闭自动打片"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-130", "kp": "打印灰阶校准", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】新装机打印灰阶不佳，最常见原因是校准未完成或漂移，通过SMPTE测试片验证并按GSDF重新校准可恢复灰阶层次，故A正确。\n【为什么错】B：整箱胶片均异常可能性低，且不解决校准问题。C：带宽影响速度不影响灰阶。D：打印机数量与灰阶无关。E：关闭自动打片不能改善层次。", "tr": "新机灰阶问题“先校准后换料”，测试片是判断校准状态的标尺。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1301", "gs": ""}, {"id": "U13-1030a", "t": "共用题干题", "s": "患者到自助打印机取片时，系统识别患者身份并定位其影像报告，最常用的凭证是", "o": {"A": "检查条码或就诊卡号", "B": "患者自报姓名", "C": "手机内随意拍摄的旧照片", "D": "口头描述检查时间", "E": "任意身份证复印件"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-131", "kp": "自助打印身份识别", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】检查条码、就诊卡号是系统唯一识别并调取对应检查数据的关键索引，故A正确。\n【为什么错】B：同名患者多，姓名不可靠。C：旧照片与本次打印无关。D：口头描述无法精确检索。E：身份证复印件不直接关联检查号。", "tr": "自助打印调取数据依赖唯一标识（条码/卡号），而非模糊信息。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1302", "gs": "某医院门诊大厅配置多台照片自助打印机，与PACS和RIS互联，为每日大量门诊与住院患者提供胶片及报告自助领取服务。高峰时段常出现排队与设备报错。"}, {"id": "U13-1030b", "t": "共用题干题", "s": "针对高峰时段排队拥堵，最有效的工程管理措施是", "o": {"A": "合理调配打印任务队列并增加自助机数量、错峰引导", "B": "取消条码验证提高速度", "C": "关闭部分打印机", "D": "改为全人工取片", "E": "提高单张胶片分辨率"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-132", "kp": "自助打印运行管理", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】任务队列优化、增加设备数量与错峰引导可均衡负载、缓解排队，是行之有效的管理手段，故A正确。\n【为什么错】B：取消身份验证引发隐私与错发风险。C：关闭打印机加剧拥堵。D：人工取片效率更低。E：分辨率提高只改善画质，不解决排队。", "tr": "自助打印管理核心是“容量规划+队列优化+流程引导”，不能牺牲安全换取速度。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1302", "gs": ""}, {"id": "U13-1031a", "t": "共用题干题", "s": "胶片上出现固定位置白色条纹，最可能的原因是", "o": {"A": "热敏头对应位置加热元件损坏或脏污", "B": "网络丢包", "C": "胶片整批受潮", "D": "灰阶校准错误", "E": "打印机电源电压波动"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-133", "kp": "热敏打印条状伪影", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (2)热敏胶片与热敏头", "ex": "【为什么对】固定位置的连续白条且与图像内容无关，典型原因是热敏头上对应加热点损坏（不加热）或被异物遮挡，该处无法显影形成白条，故A正确。\n【为什么错】B：网络丢包造成任务失败而非固定条纹。C：胶片受潮表现为灰雾、斑点，非固定细条纹。D：校准错误影响整体灰阶。E：电压波动多引起整体密度变化，均不符合固定条纹特征。", "tr": "“固定位置+与图像无关”的条纹指向打印头缺陷，而非图像数据或校准问题。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1303", "gs": "某台热敏打印机在使用中打印的胶片上出现固定的白色条纹，同一位置反复出现，其他区域打印正常，且条纹不随图像内容改变。技师排查故障原因并处理。"}, {"id": "U13-1031b", "t": "共用题干题", "s": "针对上述白条故障，正确的处理步骤是", "o": {"A": "先清洁热敏头，无效则更换热敏头", "B": "直接更换全部胶片", "C": "重启网络交换机", "D": "重新设置胶片尺寸", "E": "调高显示器伽马"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-134", "kp": "热敏打印故障处理", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】脏污引起的白条经清洁可恢复，若加热元件已损坏则须更换热敏头，由简到繁处理，故A正确。\n【为什么错】B：胶片本身正常，更换无意义。C：网络设备不影响成像条纹。D：胶片尺寸与白条无关。E：显示器伽马与打印输出无关。", "tr": "硬件性条纹的处理顺序是“清洁→更换”，勿在成像链条外排查。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1303", "gs": ""}, {"id": "U13-1032", "t": "案例分析题", "s": "某放射科新购进一台干式激光相机并接入DICOM打印网络。技师使用SMPTE测试片试打印后发现：灰阶带基本可见，但高亮度区段层次丢失、部分相邻灰阶带无法区分。临床科室随后反映部分CT片肋骨与软组织对比显示不佳。技师需在保证诊断质量的前提下解决问题。打印任务由CT设备经DICOM打印服务下发至干式激光相机。正确的处理措施是", "o": {"A": "按DICOM GSDF重新执行灰阶校准并复查SMPTE测试片", "B": "立即报废该打印机", "C": "加大图像压缩比", "D": "将所有图像改为喷墨打印", "E": "缩短扫描范围"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-135", "kp": "打印灰阶校准流程", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】高光层次丢失提示灰阶映射不准，按GSDF重新校准可恢复全灰阶段层次，并以SMPTE测试片验证效果，故A正确。\n【为什么错】B：仅校准偏差即报废设备不当。C：压缩比不影响打印灰阶且降低数据质量。D：更换打印方式成本高且非必要。E：扫描范围与灰阶显示无关。", "tr": "高光/暗部层次丢失首先想到灰阶校准，SMPTE测试片是质控验证工具。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1033", "t": "案例分析题", "s": "某医院影像科计划更新打印设备，原有湿式激光相机需频繁更换化学药液，药剂排放需专门处理，设备占用空间大且运行成本高。科室日均打印量约200张胶片，要求明室操作、即打即用、环保节能并保证影像诊断质量。在选择新设备时，新设备需能通过DICOM打印服务接收CT、MR、DR多源任务，并支持SMPTE测试片定期质控。最合适的方案是", "o": {"A": "更换为干式激光相机或热敏相机", "B": "继续采购同型号湿式激光相机", "C": "改用普通家用喷墨打印机打印诊断片", "D": "取消胶片打印全部电子化", "E": "使用手机打印照片"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-136", "kp": "打印设备选型", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】干式激光或热敏相机无化学药液、明室操作、即打即用、环保，且成像质量满足诊断要求，故A正确。\n【为什么错】B：湿式仍需药液处理与排污。C：家用喷墨不满足诊断片质量与长期保存要求。D：完全取消胶片不符合临床对硬拷贝的需求。E：手机打印照片不具备医用资质。", "tr": "选型权衡“质量、成本、环保、操作便捷”，干式设备综合最优。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "概述", "页": 355}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1034", "t": "案例分析题", "s": "某放射科使用干式激光相机打印CT轴位图像，常规设置每张14×17胶片打印2×3共6幅图像。医生反映单幅图像偏小、细节观察困难，希望放大显示关键层面，同时不希望增加胶片耗材种类。技师在不增加耗材种类的情况下改进打印方案。打印排版通过DICOM打印服务胶片格式参数设置，技师可调整每张胶片的行列布局。最合适的做法是", "o": {"A": "将胶片排版改为每张胶片打印更少的图像（如1×2）或按窗口分组放大关键层面", "B": "将图像分辨率降低一半", "C": "改用8×10小胶片打印6幅", "D": "每张胶片打印12幅", "E": "不打印直接看屏幕"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-137", "kp": "打印排版与幅面规划", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】减少每张胶片的图像数可放大单幅尺寸，或对关键层面分组打印，直接改善观察效果，故A正确。\n【为什么错】B：降低分辨率损害细节，适得其反。C：小胶片打6幅更小。D：每张12幅进一步缩小画面。E：屏幕浏览与胶片需求并存，不能完全替代打印。", "tr": "排版数量与单幅大小成反比，放大观察靠减少幅数而非降低分辨率。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U13-1035", "t": "案例分析题", "s": "某医院门诊大厅的自助打印机无法从PACS调取当日新检查的影像，但人工打印工作站打印正常，自助机界面提示“连接失败”。技师需按网络与系统分层排查故障，尽快恢复自助取片服务，避免影响患者就医体验。自助机与PACS之间采用标准DICOM与网络协议通信，人工工作站与自助机共用同一PACS服务。下列排查步骤中顺序最合理的是", "o": {"A": "先查自助机网络连通性，再查打印服务配置与PACS侧服务状态", "B": "先更换打印机主板", "C": "先删除PACS全部数据", "D": "先调整胶片价格", "E": "先重装操作系统"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-138", "kp": "自助打印故障排查", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】“人工正常、自助机连接失败”提示故障在自助机网络链路或其与PACS的服务配置，按“连通性→服务配置→服务状态”由简到繁排查最合理，故A正确。\n【为什么错】B：无故障征兆即更换主板属盲目维修。C：删除数据造成严重破坏。D：价格与连接无关。E：重装系统是最后手段而非首选。", "tr": "网络故障排查遵循“物理层→网络层→服务层”逐级定位，避免暴力处置。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-1036", "t": "案例分析题", "s": "某科室打印的DR胸片在强光灯下观察时，肺野密度区呈均匀一致，原有细小肺纹理与支气管影层次显示不清，而同一图像在医用显示器上显示正常。技师怀疑打印环节存在灰阶压缩或校准问题，需要定位故障环节。胶片为同一批干式激光胶片，打印链路包括图像传输、灰度映射、激光曝光与热显影各环节。上述环节中任一处异常均可能导致胶片灰阶表现异常，需结合测试片逐项定位。最可能的原因是", "o": {"A": "打印灰阶校准漂移导致灰度映射压缩", "B": "显示器故障", "C": "患者体位错误", "D": "探测器损坏", "E": "胶片尺寸错误"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-139", "kp": "打印灰阶压缩分析", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】显示器正常而胶片层次丢失，说明问题在打印链路，灰阶校准漂移使灰度范围被压缩，细小密度差异无法区分，故A正确。\n【为什么错】B：显示器正常已排除。C：体位错误影响解剖显示而非层次压缩。D：探测器异常在源图像即显现，显示器上应同样异常。E：胶片尺寸影响版面不影响层次。", "tr": "“屏幕正常、胶片层次差”锁定打印链路，灰阶校准是首要怀疑对象。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U13-1037", "t": "案例分析题", "s": "某医院自助打印区内，患者反映打印的报告与胶片数量经常出错，部分患者未取到报告，投诉增多。技师调查发现部分检查只生成了胶片打印任务而未生成报告打印任务，导致报告缺失。为保障打印任务完整性，自助打印系统按检查号关联胶片与报告任务，报告由RIS在医师审核发布后自动生成。任务缺失与检查状态、报告发布时机及系统触发配置密切相关。最有效的改进措施是", "o": {"A": "在RIS发布报告后自动联动生成报告打印任务，与胶片任务统一管理", "B": "要求患者次日再来", "C": "取消报告打印", "D": "仅打印胶片", "E": "人工逐张复印报告"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-140", "kp": "打印任务完整性管理", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】以RIS报告发布事件为触发源自动生成报告打印任务，与胶片任务统一入库、合并输出，可保证胶片与报告任务齐全，故A正确。\n【为什么错】B：让患者次日再来是消极应对，延误取件。C：取消报告打印损害患者权益。D：仅打印胶片仍缺报告。E：人工逐张复印报告效率低且易出错。", "tr": "任务完整性依赖“流程触发自动化”，以报告发布驱动打印任务生成。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-9013", "t": "单选题", "s": "喷墨成像技术在医疗打印中被称为绿色、低碳、环保的新技术，其主要原因是", "o": {"A": "必须使用银盐胶片才能成像", "B": "通过喷嘴喷射微小墨滴组成像素，无需显影、定影等化学处理，耗材更环保", "C": "成像过程产生大量废水需专门处理", "D": "仅能打印黑白影像", "E": "必须使用高温定影，能耗极高"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-009", "kp": "喷墨成像环保特性", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】B正确——喷墨打印由无数喷嘴将墨滴直接喷到专用介质形成像素，属于物理喷墨、无需显影定影等湿化学工艺，设备与耗材更环保、低碳，符合绿色医疗趋势。【为什么错】A喷墨不依赖银盐胶片；C其优势恰是减少化学废水；D现代喷墨支持彩色；E喷墨多为常温喷墨，能耗低于热定影工艺。", "tr": "喷墨的\"环保\"来自省去显影定影化学步骤，而非墨本身。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-9014", "t": "单选题", "s": "关于喷墨、激光与热敏三类医用打印技术的区别，正确的是", "o": {"A": "三者均需显影定影化学工艺", "B": "喷墨为喷嘴喷射墨滴成像，激光为激光扫描潜影后显影定影，热敏为热敏头直接加热显影", "C": "热敏成像必须使用墨盒", "D": "激光打印完全不需任何光学部件", "E": "喷墨打印分辨率最低、不可用于诊断"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-010", "kp": "三类打印技术区别", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】B正确——喷墨由喷嘴物理喷射墨滴；激光经激光扫描形成静电潜影再显影定影；热敏由加热头直接对热敏介质加热显影，三者机理各异。【为什么错】A喷墨与干式热敏多不需湿化学显影定影；C热敏依靠热敏介质而非墨盒；D激光打印必含激光与光路；E喷墨可达诊断级分辨率。", "tr": "区分\"显影定影工艺\"（激光有、喷墨/干式热敏无）是常考点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-9015", "t": "单选题", "s": "医用喷墨打印机通常使用的成像介质是", "o": {"A": "仅供普通复印纸", "B": "专用喷墨打印纸或喷墨胶片，避免普通纸渗墨与分辨率不足", "C": "仅限银盐胶片", "D": "必须是热敏纸", "E": "任何纸张均等效"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-011", "kp": "喷墨打印介质", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】B正确——喷墨成像需匹配专用喷墨纸或喷墨胶片，其涂层可吸收并固定墨滴、保证分辨率与保存性；普通纸易渗墨、晕染，影响影像质量与存档。【为什么错】A普通复印纸不耐墨；C喷墨不依赖银盐；D热敏纸属热敏工艺；E介质差异显著影响成像，不可等效。", "tr": "喷墨务必用\"专用介质\"，普通纸会严重降质。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-9201", "t": "单选题", "s": "医用喷墨打印（医疗影像）的主要特点是", "o": {"A": "采用液态染料/颜料按需喷射成像", "B": "利用激光扫描", "C": "热敏发色", "D": "银盐感光", "E": "干式激光"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-9201", "kp": "喷墨原理", "ch": "十三、图像打印技术 → 4.喷墨成像技术", "ex": "【为什么对】医用喷墨按需喷射液态墨水在介质上成像，属非银盐数字打印。\n【为什么错】激光/热敏/银盐为其他技术。", "tr": "喷墨=液态墨水喷射。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-9202", "t": "单选题", "s": "喷墨打印相对于激光打印的优势通常是", "o": {"A": "连续色调与低运行成本", "B": "极高速度", "C": "永久不褪色", "D": "无需介质", "E": "分辨率无限"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-9202", "kp": "喷墨优势", "ch": "十三、图像打印技术 → 4.喷墨成像技术", "ex": "【为什么对】喷墨可实现连续色调且运行成本较低；速度与永久保存性通常不及激光/银盐。\n【为什么错】极高速度非其优势。", "tr": "喷墨优势=连续色调/低成本。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U13-9203", "t": "单选题", "s": "干式激光相机（自显机）相比湿式冲洗的优点是", "o": {"A": "无需暗室与化学药液、即打即取", "B": "分辨率无限高", "C": "必须暗室", "D": "需大量水", "E": "速度极慢"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-9203", "kp": "干式相机优点", "ch": "十三、图像打印技术 → 5.照片自主打印机", "ex": "【为什么对】干式激光相机无需暗室与湿化学处理，操作简便、即打即取。\n【为什么错】湿式才需暗室与药液。", "tr": "干式相机无需暗室药液。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0101", "t": "单选题", "s": "关于下肢全长负重摄影，下列叙述错误的是", "o": {"A": "患者双足站立于同一水平面，双侧髌骨朝向正前方，以消除下肢旋转造成的测量误差", "B": "照射野应包括双侧髋关节（股骨头）至踝关节，一次成像获得双下肢全长影像", "C": "应采用较大的源像距（一般不小于180cm）以减小放大与几何失真", "D": "图像用于测量下肢机械轴（髋-膝-踝角）、评估膝内外翻及人工关节置换术前规划", "E": "为减少辐射剂量可改为仰卧位摄影，其力线测量结果与站立负重位等效"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-001", "kp": "下肢全长负重摄影", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】E错误故为本题答案：负重位的意义在于反映生理负荷状态下的真实力线，关节间隙狭窄程度、内外翻角度在卧位与站立位之间可有明显差异；仰卧位测得的机械轴不能替代站立位结果，故临床要求必须站立负重摄影。【为什么错】A正确：髌骨朝前是控制股骨旋转的关键，旋转会显著影响HKA角测量。B正确：完整包含股骨头与踝关节中心才能确定机械轴的两个端点。C正确：大源像距可减小锥形束造成的边缘放大与失真，提高测量准确性。D正确：这些正是全长负重摄影的主要临床用途。", "tr": "“负重”二字是本考点的核心。凡是把站立位换成卧位、把双足并拢换成随意站姿、把髌骨朝前换成足尖朝前的选项，都会带来测量偏差。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0102", "t": "案例分析题", "s": "患者女性，14岁，因青少年特发性脊柱侧弯定期随访，临床要求摄站立位全脊柱正、侧位片以测量Cobb角并评估冠状面与矢状面平衡。该患者近3年内已多次接受同类检查，家长对辐射剂量表示担忧。技师采用站立位全脊柱拼接摄影。下列技术方案与操作要点，正确的是", "o": {"A": "正位采用站立后前位投照，可显著降低甲状腺、乳腺的受照剂量；侧位时双上肢向前抬起屈肘、躯干保持直立不旋转；照射野上缘包含颈椎下部至颅底区、下缘包含双侧髂嵴与股骨头；同时使用附加滤过、严格准直与低剂量方案控制剂量", "B": "正位必须采用前后位投照，否则无法准确测量Cobb角", "C": "侧位摄影时双上肢应自然下垂紧贴体侧，以免影响脊柱位置", "D": "为提高图像清晰度，应将源像距缩短至100cm", "E": "每次随访均应更换投照体位与方式，以便获得更多角度的信息"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-002", "kp": "脊柱全长负重摄影", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】A正确：后前位投照使X线先经过背部，甲状腺与乳腺处于出射侧，其受照剂量较前后位显著降低，对需要反复随访的青少年女性尤为重要；侧位双上肢前抬屈肘可避免肱骨与胸椎重叠；照射野需覆盖测量所需的全部解剖标志；附加滤过、准直与低剂量方案是剂量优化的常规手段。【为什么错】B错误：Cobb角测量依据椎体终板连线，后前位同样可准确测量，且是国际推荐体位。C错误：上肢下垂会使肱骨与上胸椎重叠，影响上端椎判断。D错误：缩短源像距会加重放大失真并增加皮肤入射剂量，全长摄影恰恰需要大源像距。E错误：随访检查应保持体位与技术条件一致，才能进行前后对比，随意更换会导致测量不可比。", "tr": "青少年脊柱侧弯随访的两大要点：一是“后前位降低乳腺甲状腺剂量”，二是“随访条件一致性”。二者都是命题高频点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0103", "t": "多选题", "s": "关于全脊柱、全下肢负重摄影的图像质量与辐射防护，下列正确的有", "o": {"A": "采用后前位投照、附加滤过与严格准直，可降低甲状腺、乳腺与性腺的受照剂量", "B": "增大源像距可减小锥形束造成的边缘放大与几何失真", "C": "对儿童与青少年随访者应使用低剂量方案，并对射线敏感器官做好屏蔽", "D": "由于照射野长、散射线增多，需合理选择滤线栅与曝光参数", "E": "分段曝光拼接由于每段剂量较低，患者所受总剂量必定低于一次长片摄影"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-003", "kp": "全长摄影的质量控制与防护", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】A正确：体位与准直是最有效的器官剂量控制手段。B正确：源像距越大，射线束越接近平行，边缘放大差异越小。C正确：儿童与青少年组织敏感性高且随访次数多，剂量优化尤为重要。D正确：长照射野散射线明显增加，需权衡滤线栅带来的图像对比改善与剂量增加。【为什么错】E错误：分段拼接的总剂量取决于分段数、各段曝光条件与重叠区大小，重叠区会被重复照射，总剂量并不必然低于一次长片摄影；剂量高低应以实测面积剂量乘积等指标评价，不能想当然。", "tr": "“分段＝低剂量”是错误直觉。重叠区重复曝光与分段数增多都会抬高总剂量，评价剂量必须看整体指标而非单段曝光条件。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-0104", "t": "单选题", "s": "关于DR图像拼接技术的实现方式，下列叙述正确的是", "o": {"A": "常用方式包括球管与探测器同步移动、多次分段曝光后由软件自动拼接，以及采用长条形探测器或狭缝扫描一次成像", "B": "拼接图像只能由技师在后处理软件中手工剪贴完成", "C": "分段曝光时球管位置固定不动，仅探测器移动即可保证各段几何关系一致", "D": "拼接技术要求相邻分段之间完全不留重叠区域", "E": "拼接技术仅适用于四肢长骨，不能用于脊柱"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-004", "kp": "DR图像拼接技术的实现方式", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】A正确：目前主流实现方式有两类，一是多次分段曝光后自动拼接（球管与探测器同步平移或球管作角度旋转跟踪），二是长条探测器或狭缝扫描式一次采集，二者均可获得超出单幅探测器视野的全长图像。【为什么错】B错误：现代设备均具备基于重叠区灰度与解剖特征的自动配准拼接算法，手工剪贴只是特殊情况下的补充。C错误：若球管固定而仅探测器移动，边缘段的射线入射角将严重偏斜，造成明显几何失真与截断，必须使球管与探测器协同运动。D错误：足够的重叠区正是配准的依据，无重叠无法保证接缝准确。E错误：拼接技术最主要的应用恰恰是全脊柱与全下肢。", "tr": "分段拼接的几何前提是“球管与探测器同步”，这是与后续几何畸变校正考点直接相关的核心概念。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0105", "t": "多选题", "s": "关于DR拼接图像的几何畸变及其校正，下列正确的有", "o": {"A": "锥形束X线在各分段边缘的入射角与放大率不同，若直接叠加会造成接缝处结构错位与长度测量误差", "B": "增大源像距、严格准直，并使球管的旋转中心与探测器运动保持同步，可减小几何畸变", "C": "相邻分段保留足够重叠区，利用重叠区内的解剖标志或标尺刻度进行配准，可提高拼接精度", "D": "标尺所在平面与被测结构所在平面相距越远，二者放大率差异越大，长度测量误差也越大", "E": "只要软件自动拼接成功，拼接图像上的长度测量结果即与实际长度完全一致"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-005", "kp": "拼接图像几何畸变校正", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】A正确：这是拼接技术最核心的技术难点——中心射线区放大率最小、边缘区放大并倾斜投影，直接拼合必然出现错位。B正确：这三项是硬件与几何层面的基本对策。C正确：重叠区提供了配准所需的共同特征，重叠不足是拼接失败的常见原因。D正确：放大率由“焦点-物平面距离”决定，标尺若远离被测结构平面（例如贴在探测器面板上而被测骨骼位于体内），其换算关系将不成立，产生系统性测量误差。【为什么错】E错误：即便拼接在视觉上连续，仍存在残余几何误差与放大率不确定性，术前测量应结合标尺校正与临床复核，不能认为与实际长度完全一致。", "tr": "“拼得好看”不等于“测得准确”。测量精度依赖于标尺位置、几何校正与患者制动三方面，缺一不可。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U14-0106", "t": "单选题", "s": "关于拼接摄影中标尺（带刻度金属尺或铅字标记）的使用，下列叙述错误的是", "o": {"A": "标尺应完整置于照射野内并贯穿各分段，为分段配准提供参考基准", "B": "标尺应尽量贴近被测结构所在平面，以减小放大率差异带来的测量误差", "C": "标尺可用于校正图像放大率，提高长度与角度测量的准确性", "D": "标尺被肢体或衣物遮挡，或在分段曝光间发生移位，会导致拼接与测量错误", "E": "只要使用自动拼接软件，标尺即可省略，对测量精度没有影响"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-006", "kp": "拼接标尺的作用与放置", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】E错误故为本题答案：自动拼接软件解决的是分段图像的对齐问题，而放大率校正需要已知实际长度的物理参照物；缺少标尺时无法把图像上的像素距离换算为真实长度，人工关节假体尺寸规划等测量将失去依据。【为什么错】A正确：贯穿各段的标尺同时提供配准特征与长度基准。B正确：标尺与被测结构越接近同一平面，二者放大率越一致。C正确：这是标尺最主要的功能。D正确：遮挡与移位是拼接与测量错误的常见原因，摆位时应确认标尺固定且不被覆盖。", "tr": "标尺有“配准基准”和“长度校正”双重作用，其中长度校正无法被软件替代——这是本题的关键区分点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0107", "t": "案例分析题", "s": "患者男性，68岁，双膝骨关节炎，拟行人工全膝关节置换，术前需摄双下肢全长站立位拼接片以测量下肢力线并规划截骨。图像回顾发现：股骨干在第1、2段接缝处出现明显错位成角，标尺刻度在接缝处不连续，测得的髋-膝-踝角与临床查体所见明显不符。作为技师，对该问题的分析与处置，正确的是", "o": {"A": "最可能是分段曝光间隔期间患者重心移动、站立不稳，或重叠区不足、标尺发生移位导致自动配准失败；应重新交代屏气与保持站立不动、必要时使用站立支架固定，适当加大重叠区并确认标尺牢固贴附后重新摄影", "B": "该表现为平板探测器坏点所致，需联系工程师更换探测器", "C": "属于拼接接缝的正常表现，可直接用于术前测量", "D": "通过调整窗宽窗位使接缝显示不明显后即可进行测量", "E": "应改用双能量减影去除软组织后重新测量下肢力线"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-007", "kp": "拼接失败原因分析与处置", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】A正确：接缝处错位成角＋标尺刻度不连续，是典型的分段间相对位移证据。老年患者站立时间长易疲劳晃动，是最常见原因；处理应从患者固定（站立支架、扶手）、缩短分段间隔、加大重叠区、固定标尺等方面入手并重新采集，绝不能用错位图像作术前测量。【为什么错】B错误：探测器坏点表现为固定位置的点线状缺陷，不会造成结构成角错位与标尺不连续。C错误：错位接缝会带来数度的力线测量误差，直接影响截骨方案，属不合格图像。D错误：窗技术不改变几何关系。E错误：双能量减影用于软硬组织分离，与拼接错位无关，且骨性力线测量并不需要去软组织。", "tr": "凡是“标尺不连续”，几乎可以直接锁定为分段间发生了相对位移；这是判断拼接失败原因最直观的客观证据。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U14-0108", "t": "单选题", "s": "关于数字体层融合（tomosynthesis）的成像原理，下列叙述正确的是", "o": {"A": "X线管在有限角度范围内运动，采集一系列低剂量投影，经重建算法生成一组平行于探测器的任意深度断层图像", "B": "X线管需围绕人体旋转360°采集投影数据", "C": "需要重建多少层断层图像，就必须相应地曝光多少次", "D": "数字体层融合重建得到的是横断面（轴位）图像", "E": "数字体层融合的辐射剂量高于同部位的CT检查"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-008", "kp": "数字体层融合成像原理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】A正确：数字体层融合是传统体层摄影的数字化发展，X线管在有限角度内一次扫描采集数十幅低剂量投影，通过位移叠加或滤波反投影、迭代等算法，可回顾性重建出不同深度、平行于探测器的多层图像。【为什么错】B错误：360°旋转采集是CT的特征，体层融合为有限角度。C错误：一次扫描的投影数据可重建任意多层图像，不需要逐层曝光，这正是相对传统体层摄影的巨大优势。D错误：其重建平面平行于探测器，即冠状面或与摆位平面一致的断层，而非横断面。E错误：体层融合的总剂量通常相当于数次普通摄影，远低于同部位CT。", "tr": "把体层融合当作“低配CT”是常见误区。二者在采集角度、重建平面与分辨率各向异性上有本质区别，体层融合的断层平面平行于探测器。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0109", "t": "多选题", "s": "关于数字体层融合图像的特性，下列正确的有", "o": {"A": "层内（平行于探测器方向）空间分辨率高，接近常规DR图像", "B": "深度（Z轴）方向分辨率有限，重建层厚不能任意减小", "C": "一次采集可回顾性重建不同深度的多层图像，层间距可根据需要调整", "D": "有限角度采集会残留层外结构的模糊影与波纹状伪影", "E": "其密度分辨率与各向同性重建能力与多层螺旋CT相当"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-009", "kp": "数字体层融合图像特性", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】A正确：层内分辨率由平板探测器像素决定，可达到DR水平，明显高于常规CT的层内分辨率。B正确：有限角度采样导致Z轴方向信息不足，重建层厚受扫描角度限制。C正确：一次采集、多层重建、层距可调是数字化体层的核心优势。D正确：层外结构不能被完全消除，会以模糊影或波纹（ripple）伪影残留于重建层内，是有限角度重建的固有缺陷。【为什么错】E错误：受有限角度、探测器动态范围与散射线影响，体层融合的密度（低对比）分辨率明显低于CT，且重建体素严重各向异性，不能实现真正的各向同性重建。", "tr": "评价体层融合要抓“各向异性”这一关键词：层内好、层间差；其价值在于以低剂量去除重叠，而非替代CT的容积成像。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-0110", "t": "单选题", "s": "关于数字体层融合的临床应用，下列叙述错误的是", "o": {"A": "可提高肋骨、腕舟骨等隐匿性骨折的检出率", "B": "用于含金属内固定物的术后随访时，其金属伪影一般较CT轻", "C": "可用于肺内小结节的检出与随访，辐射剂量低于胸部CT", "D": "可与静脉尿路造影结合显示肾盂输尿管，减少肠气与骨骼的重叠干扰", "E": "因其属于断层成像，可完全替代CT用于复杂骨盆骨折的三维评估"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-010", "kp": "数字体层融合的临床应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】E错误故为本题答案：复杂骨盆骨折需要评价骨折线的空间走行、关节面塌陷程度与移位方向，必须依赖各向同性的容积数据与多平面重组、三维重建，而体层融合的Z轴分辨率有限、无法生成可靠的横断面与三维模型，不能替代CT。【为什么错】A正确：去除重叠后隐匿骨折的显示率明显提高，是骨关节应用的主要价值。B正确：体层融合对金属的伪影表现主要为条状模糊，通常轻于CT的严重放射状与暗带伪影，有利于观察假体周围骨质。C正确：其剂量相当于数次胸片，远低于胸部CT，适合部分随访场景。D正确：这是传统体层摄影在尿路造影中的经典应用在数字化条件下的延续。", "tr": "体层融合的应用定位是“在DR基础上去除重叠”，凡是把它抬高到可以替代CT的选项都应排除。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0111", "t": "多选题", "s": "关于DR双能量减影的两种实现方式，下列正确的有", "o": {"A": "两次曝光法在极短时间间隔内先后以低管电压与高管电压各曝光一次，两次采集的能谱分离较好", "B": "两次曝光法的两次采集之间存在时间差，心脏搏动与呼吸运动可造成运动性伪影", "C": "单次曝光法采用前后叠置的双层探测器（中间夹铜滤过板），一次曝光同时获得低能与高能图像", "D": "单次曝光法无时间差、不产生运动性伪影，但两层探测器接收的能谱重叠较多，减影效果与信噪比略差", "E": "单次曝光法的能谱分离程度优于两次曝光法"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-011", "kp": "DR双能量减影实现方式", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】A正确：两次曝光可分别选择差异明显的高、低管电压并配合不同滤过，能谱分离好，减影后组织分离彻底。B正确：即使间隔仅约200ms，心脏搏动与不完全屏气仍可造成心缘、膈肌处的运动伪影，这是两次曝光法的主要缺点。C正确：这是单次曝光法的典型硬件结构，铜板对前层透过的射线进行硬化滤过，使后层探测器接收较高能量成分。D正确：无运动伪影是其优势，但能谱重叠使物质分离能力与信噪比下降。【为什么错】E错误：单次曝光法的能谱分离明显不如两次曝光法，这正是其减影质量受限的原因，选项把二者优劣说反。", "tr": "两种方法各有取舍：两次曝光“能谱分离好但怕运动”，单次曝光“不怕运动但能谱分离差”。命题常把两者优点张冠李戴。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-0112", "t": "单选题", "s": "DR双能量减影能够将骨组织像与软组织像分离开来，其物理基础是", "o": {"A": "骨（钙）与软组织的X线衰减系数随光子能量变化的规律不同，对高、低能两幅图像作对数加权减影可选择性消除其中一种组织", "B": "骨组织与软组织的有效原子序数相同，仅密度存在差异", "C": "在高管电压条件下软组织对X线完全不产生衰减", "D": "骨组织只发生相干散射，软组织只发生光电效应", "E": "双能量减影依赖于对比剂中碘的K吸收边缘特性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-012", "kp": "骨组织像与软组织像的分离原理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】A正确：钙的有效原子序数明显高于软组织，低能时光电效应占比大、衰减急剧增加，高能时以康普顿效应为主、二者差异缩小；因此两种组织的“衰减—能量”曲线形状不同，对两幅不同能量图像取对数后按适当权重相减，即可使其中一种组织的信号相互抵消，得到软组织像或骨组织像。【为什么错】B错误：骨（含钙、磷）的有效原子序数显著高于软组织，这正是能量依赖差异的来源。C错误：任何能量下软组织都有衰减，只是程度不同。D错误：两种组织中光电效应与康普顿效应均存在，只是占比随能量与原子序数变化。E错误：碘的K边缘是血管造影能量减影的基础，胸部平片双能减影针对的是钙与软组织，与对比剂无关。", "tr": "注意区分两个“双能”：DSA中的K边缘能量减影针对碘，DR胸部双能量减影针对钙（骨），二者物理基础与临床目的不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0113", "t": "案例分析题", "s": "患者男性，55岁，吸烟史30年，因体检行胸部DR检查，正位片示右上肺野一直径约1.2cm的结节影，部分被后肋与锁骨重叠，难以判断结节内部有无钙化。临床希望在不立即行CT的情况下获得更多信息，技师建议加做胸部双能量减影。关于本例的技术分析，正确的是", "o": {"A": "软组织像可去除肋骨与锁骨的重叠影、突出显示肺内结节；骨组织像有助于显示结节内的钙化成分，对良恶性的初步判断有参考价值；但双能量减影不能替代CT定性，且两次曝光法需要良好屏气配合以避免运动伪影", "B": "双能量减影可直接测量结节的CT值，实现钙化的定量分析", "C": "双能量减影采用单次曝光完成，患者所受剂量低于常规胸部平片", "D": "软组织像用于显示钙化，骨组织像用于突出显示肺内结节", "E": "结节位于肺尖区时双能量减影效果最佳，且完全不受呼吸与心搏运动的影响"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-013", "kp": "胸部双能量减影的临床应用与局限", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】A正确：软组织像去骨后可显著提高被肋骨遮蔽区域结节的检出与边缘评价；钙化含钙成分在骨组织像上得以保留显示，有助于判断结节是否为良性钙化灶；但双能减影仍是投影成像，不能定性诊断，且两次曝光法对运动敏感，需充分屏气。【为什么错】B错误：CT值是CT容积扫描的定量指标，投影成像不能测量CT值。C错误：无论两次曝光还是单次曝光，双能量减影的总剂量都不低于并通常略高于常规胸片。D错误：软组织像与骨组织像的用途被完全说反。E错误：肺尖区受锁骨与肋骨重叠影响大，双能减影确有帮助，但“完全不受运动影响”不成立，两次曝光法尤其受呼吸与心搏影响。", "tr": "记住组合关系：“软组织像看结节、骨组织像看钙化”。同时不要把投影成像的能量减影与CT的能谱定量混为一谈。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0114", "t": "多选题", "s": "关于乳腺X线摄影的靶面与滤过组合，下列正确的有", "o": {"A": "钼（Mo）靶的特征X线能量约为17.5keV与19.6keV，适用于较薄的脂肪型乳腺", "B": "铑（Rh）靶特征X线能量（约20.2keV与22.7keV）高于钼靶，适用于较厚、较致密的乳腺", "C": "Mo/Rh组合利用铑滤过的K吸收边缘，使较高能量光子得以通过，可降低厚乳腺的受照剂量", "D": "数字乳腺机常用钨（W）靶配合铑或银滤过，可在保持对比度的同时降低平均腺体剂量", "E": "乳腺摄影应尽量选用较高管电压（大于50kV）以提高软组织对比度"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-001", "kp": "乳腺摄影靶面与滤过组合", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (1)乳腺X线检查设备", "ex": "【为什么对】A正确：钼靶特征X线能量低，软组织对比最佳，适合薄而脂肪成分多的乳腺。B正确：铑靶特征能量更高，穿透力更强，适用于厚而致密的乳腺以控制曝光时间与剂量。C正确：滤过材料的K吸收边缘会滤掉高于该边缘的部分光子并塑形能谱，Mo/Rh组合让能谱整体上移，兼顾穿透与对比。D正确：钨靶轫致辐射产额高、热容量大，配合Rh、Ag滤过成为数字乳腺与DBT的主流选择，可在同等图像质量下降低平均腺体剂量。【为什么错】E错误：乳腺各软组织成分的衰减差异极小，只有在低能范围（管电压一般为25~32kV）才能获得足够对比；管电压过高会使对比度急剧下降，超过50kV完全不符合乳腺摄影的成像要求。", "tr": "乳腺摄影与常规摄影的思路相反：常规摄影常用高kV降剂量，乳腺摄影必须用低kV保对比，靶/滤过的选择就是在“对比度”与“剂量、曝光时间”之间寻求平衡。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-0115", "t": "单选题", "s": "关于乳腺X线摄影自动曝光控制（AEC）的使用，下列叙述错误的是", "o": {"A": "AEC探测器应置于腺体最厚、最致密的区域下方，通常靠近胸壁侧", "B": "全自动模式可先行短时预曝光，据乳腺厚度与密度自动选择靶/滤过组合、管电压与管电流量", "C": "压迫板测得的乳腺压迫厚度信息可参与AEC的曝光决策", "D": "假体植入或存在大片钙化时可能干扰AEC判断，必要时改用半自动或手动模式", "E": "AEC选点应置于乳腺边缘的脂肪区，以避免中央区曝光过度"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-002", "kp": "乳腺摄影自动曝光控制", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (1)乳腺X线检查设备", "ex": "【为什么对】E错误故为本题答案：若把AEC探测器放在薄的脂肪区，系统会因该处透过量迅速达标而提前切断曝光，导致腺体致密区曝光严重不足、信噪比低、病灶被噪声淹没；正确做法是选在腺体最厚最致密处，保证诊断关键区域获得足够的曝光量。【为什么错】A正确：这是AEC选点的基本原则，乳腺后部靠近胸壁处腺体通常最厚。B正确：预曝光自动优选靶/滤过与kV是现代乳腺机的标准功能。C正确：压迫厚度是决定曝光参数的重要输入量。D正确：高密度假体或大片钙化会使局部透过量异常，需人工干预。", "tr": "AEC探测点“宁厚勿薄”。这与普通摄影中AEC选点原则一致：探测野必须覆盖诊断上最重要、衰减最大的区域。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0116", "t": "单选题", "s": "关于乳腺X线摄影中滤线栅的使用，下列叙述正确的是", "o": {"A": "乳腺摄影多采用聚焦式移动栅，栅比常为4:1~5:1，曝光过程中栅条运动以消除栅线影", "B": "乳腺摄影常规使用栅比12:1以上的高栅比滤线栅，以最大限度去除散射线", "C": "使用移动滤线栅不会增加受检者的辐射剂量", "D": "乳腺放大摄影时应使用高栅比滤线栅以保证图像质量", "E": "乳腺摄影因组织较薄，散射线可忽略，故一律不使用滤线栅"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-003", "kp": "乳腺摄影滤线栅", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (1)乳腺X线检查设备", "ex": "【为什么对】A正确：乳腺摄影使用专用低栅比（约4:1~5:1）聚焦式移动栅，栅密度较高；低栅比是因为乳腺摄影管电压低、散射线相对有限，同时必须严格控制剂量；曝光中栅条往复移动可将栅线影模糊掉。【为什么错】B错误：高栅比会大幅增加曝光量与腺体剂量，不适用于乳腺。C错误：使用滤线栅会吸收部分原发射线，必须提高曝光量，受检者剂量随之增加。D错误：放大摄影采用气隙技术减少散射线，不使用滤线栅，同时须使用微焦点（约0.1mm）以保证放大图像的清晰度。E错误：常规接触摄影仍需滤线栅来改善对比度。", "tr": "“放大摄影不用滤线栅、改用气隙并配微焦点”是乳腺摄影的高频考点，常与常规接触摄影的滤线栅要求放在一起设混淆项。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0117", "t": "单选题", "s": "关于数字乳腺体层合成（DBT）的采集方式，下列叙述正确的是", "o": {"A": "X线管在有限角度（不同厂家总扫描角度约15°~50°）范围内采集约9~25幅低剂量投影，重建出层厚通常为1mm的平行断层图像", "B": "X线管需绕乳腺旋转360°采集投影数据", "C": "每重建一层断层图像就需要单独压迫并曝光一次", "D": "DBT重建得到的是矢状面断层图像", "E": "DBT的采集角度越小，深度方向分辨率越高"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-004", "kp": "DBT扫描角度与投影数", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】A正确：DBT在一次压迫下由X线管在有限角度内快速扫描，采集十余至二十余幅低剂量投影，重建为一叠平行于探测器（即平行于压迫板）的断层，层厚多为1mm，各厂家在扫描角度与投影数上的取舍不同。【为什么错】B错误：360°旋转是CT的采集方式。C错误：一次采集即可重建全部层面，这正是相较传统体层的根本优势，也避免了反复压迫。D错误：重建平面平行于探测器，对CC位而言近似横断面方向的断层、对MLO位则平行于该投照平面，并非矢状面。E错误：角度越小深度分辨率越差，恰恰说反。", "tr": "DBT的“有限角度”是理解其一切优缺点的钥匙：既带来低剂量、快速采集，也决定了Z轴分辨率有限与层外伪影残留。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0118", "t": "多选题", "s": "关于DBT扫描角度、投影数与图像质量之间的关系，下列正确的有", "o": {"A": "扫描角度越大，深度（Z轴）方向分辨率越好，层外结构模糊得越彻底", "B": "扫描角度增大意味着采集时间延长，运动模糊风险与患者压迫不适随之增加", "C": "在总剂量一定的前提下，投影数增多则每幅投影的剂量降低、噪声增大，需依靠重建算法加以抑制", "D": "DBT的Z轴分辨率明显低于层内分辨率，其重建体素为各向异性，不能视为真正的各向同性断层", "E": "只要不断增加投影数量，DBT即可达到与CT相同的深度分辨率"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-005", "kp": "DBT角度、投影数与Z轴分辨率", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】A正确：深度分辨率主要取决于扫描角度所决定的采样锥角，角度越大，层外结构在重建层内被弥散得越充分。B正确：大角度必然延长采集时间，压迫状态下的时间延长会带来运动模糊与患者耐受性问题，这是厂家在角度选择上折中的原因。C正确：DBT总剂量受限，投影数与单幅剂量成反比，需靠迭代等算法平衡噪声。D正确：各向异性是DBT的固有特征。【为什么错】E错误：深度分辨率的根本限制来自有限角度采样造成的频域数据缺失，单纯增加同一角度范围内的投影数只能改善采样密度与噪声，不能补足缺失的角度信息，因此永远无法达到CT的深度分辨率。", "tr": "区分“角度范围”与“投影数量”两个变量：前者决定深度分辨率上限，后者影响采样密度与噪声；把二者混为一谈是本考点的主要失分点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U14-0119", "t": "多选题", "s": "关于DBT与全视野数字乳腺摄影（FFDM）的联合应用及合成二维图像（C-View等）的应用，下列正确的有", "o": {"A": "DBT与FFDM联合采集时，一次检查的总平均腺体剂量约为单独FFDM的两倍", "B": "由DBT数据重建生成的合成二维图像可替代FFDM，使总剂量接近单独FFDM的水平", "C": "合成二维图像保留了二维整体观并可强化微钙化的显示，便于与既往FFDM作对比", "D": "合成二维图像需要另外增加一次独立的低剂量曝光单独采集", "E": "DBT断层可减少腺体组织重叠造成的“假病灶”，有助于降低召回率"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-006", "kp": "DBT与FFDM联合应用及合成2D", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】A正确：DBT与FFDM各自曝光一次，联合方案的腺体剂量约为单独FFDM的两倍，这是推动合成二维图像发展的直接动因。B正确：以合成二维替代FFDM可省去一次曝光，使总剂量回落至接近单独FFDM水平。C正确：合成图像通过对断层数据的投影与增强处理，可突出显示微钙化并提供整体观，满足与历史片对比的需要。E正确：减少组织重叠所致的假阳性、降低召回率是DBT最重要的临床获益之一。【为什么错】D错误：合成二维图像由已采集的DBT投影与重建数据经算法生成，不需要任何额外曝光，这正是其降低剂量的原理所在。", "tr": "“合成二维”不是“再拍一张”，而是“算出来的一张”。理解这一点才能正确回答与剂量相关的所有衍生问题。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-0120", "t": "案例分析题", "s": "患者女性，46岁，无症状筛查者，既往乳腺X线检查提示腺体致密（BI-RADS腺体密度c类），并因腺体重叠所致的可疑结构扭曲两次被召回复查、复查后均为阴性。本次患者对再次召回与辐射剂量均有顾虑，希望技师给出合适的检查方案。关于技术方案的选择与告知，正确的是", "o": {"A": "对致密型乳腺，DBT可减少腺体重叠遮蔽、提高浸润性癌检出并降低召回率；为控制剂量，可采用“DBT＋合成二维图像”方案替代“DBT＋FFDM”，其总剂量接近单独FFDM水平", "B": "致密型乳腺应避免使用DBT，因其剂量为FFDM的10倍以上", "C": "DBT对微小钙化的显示明显优于FFDM，可完全取代二维图像", "D": "致密型乳腺应直接行乳腺MRI，无需再行乳腺X线检查", "E": "DBT单次压迫的平均腺体剂量远超监管限值，因此不宜用于筛查"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-007", "kp": "DBT对致密型乳腺的应用与剂量", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】A正确：致密型乳腺是DBT获益最大的人群，断层成像可将重叠腺体逐层分开，既提高浸润性癌检出率，又减少因腺体重叠造成的假性结构扭曲与召回；结合合成二维图像可在保留二维整体观的同时把总剂量控制在接近单独FFDM的水平，是兼顾效益与剂量的合理方案。【为什么错】B错误：DBT单次采集的平均腺体剂量与FFDM同量级，联合FFDM约为两倍，绝非10倍。C错误：DBT在微钙化簇的整体形态与分布判断上并不优于二维图像，钙化常分散于多个层面，因此需要二维或合成二维图像配合，不能完全取代。D错误：MRI敏感度虽高但特异度较低、成本高、不适合作为普通致密型乳腺的一线筛查手段。E错误：DBT的平均腺体剂量仍在监管限值范围内，可以用于筛查。", "tr": "剂量类选项要有量级感：DBT与FFDM同量级，联合约2倍，合成二维可回落至约1倍。凡出现“10倍”“远超限值”一类夸大表述均为错误项。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-0121", "t": "单选题", "s": "关于DBT的局限性与配套技术，下列叙述错误的是", "o": {"A": "单次检查产生数十至上百幅断层图像，数据存储量大、医师判读时间延长", "B": "成簇微钙化可分布于多个断层层面，其形态与分布的整体判断有时不如二维图像直观", "C": "对仅在DBT上显示的病灶，需要配备DBT引导下的定位或穿刺活检技术", "D": "有限角度采集使层外结构不能被完全消除，图像上可残留伪影", "E": "由于DBT为断层成像，检查时不再需要对乳腺进行充分压迫"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-008", "kp": "DBT的局限性与配套技术", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】E错误故为本题答案：DBT同样需要充分压迫。压迫可减小乳腺厚度从而降低剂量与散射线、使腺体铺展分离、固定乳腺以防止扫描过程中的运动模糊；由于DBT采集时间长于单次FFDM曝光，对制动的要求反而更高，只是部分设备的压迫力可略作优化以改善舒适度。【为什么错】A正确：数据量与判读负担增加是DBT推广中的现实问题。B正确：钙化跨层分布使整体形态判断受限，这也是需要合成二维图像的原因之一。C正确：DBT发现的隐匿病灶需配套的引导定位技术才能完成活检。D正确：层外伪影是有限角度重建的固有缺陷。", "tr": "把“断层成像”与“不需要压迫”联系起来是典型错误推理。压迫的四大作用（减薄降剂量、减少散射、铺展腺体、固定制动）在DBT中一个都不能少。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1001", "t": "单选题", "s": "下肢与脊柱负重摄影的基本要求是", "o": {"A": "患者在站立负重状态下进行投照", "B": "患者平卧位投照", "C": "患者俯卧位投照", "D": "患者侧卧水平投照", "E": "患者屈膝90°投照"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-101", "kp": "负重摄影概念", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】负重摄影要求在站立位、肢体承受自身体重（承重）状态下投照，以反映真实应力下关节间隙与下肢力线，故A正确。\n【为什么错】B：平卧位肢体不受体重负荷。C：俯卧位同样无负重。D：侧卧水平位为非负重体位。E：屈膝90°为特殊应力体位而非负重摄影常规要求，均不符合。", "tr": "“负重”特指站立承重，与卧位摄影的力线表现有明显差异。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1002", "t": "单选题", "s": "下肢全长负重摄影最主要的临床应用是", "o": {"A": "评估下肢力线与关节置换术前规划", "B": "测量腰椎曲度", "C": "观察膝关节半月板", "D": "筛查骨质疏松", "E": "评估肺纹理"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-102", "kp": "下肢全长负重摄影应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】下肢全长负重位可一次性显示髋、膝、踝，用于测量下肢力线（髋-膝-踝角）、关节间隙及畸形程度，是关节置换术前规划的重要依据，故A正确。\n【为什么错】B：腰椎曲度属脊柱摄影范畴。C：半月板为软组织，普通X线不显示。D：骨密度测量用DXA。E：肺纹理评估属胸部摄影，均不符合。", "tr": "下肢全长摄影服务于“力线评估与矫形规划”，测量参数为髋-膝-踝角。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1003", "t": "单选题", "s": "全下肢负重正位摄影的投照范围应包括", "o": {"A": "从髋关节至踝关节全长", "B": "仅膝关节", "C": "从踝关节至足趾", "D": "仅髋关节", "E": "从膝至足"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-103", "kp": "下肢全长摄影范围", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】下肢全长摄影须将髋、膝、踝三个关节同时包括在图像中，才能完整测量下肢力线与各关节关系，故A正确。\n【为什么错】B：仅膝关节无法评价全下肢力线。C：踝至足趾范围过小。D：仅髋关节范围过小。E：膝至足范围仍不完整，均无法完成全长测量。", "tr": "全长摄影强调“髋-膝-踝”同框，缺失任何一端都无法完成力线测量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1004", "t": "单选题", "s": "脊柱全长负重摄影主要适用于", "o": {"A": "脊柱侧凸畸形的Cobb角测量", "B": "颈椎间盘突出", "C": "腰椎压缩骨折定位", "D": "骶髂关节炎", "E": "脊柱结核定性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-104", "kp": "脊柱全长摄影应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】全脊柱正侧位可完整显示颈、胸、腰椎，用于脊柱侧凸等畸形患者测量Cobb角、观察冠状面与矢状面平衡，故A正确。\n【为什么错】B：颈椎间盘为软组织，X线平片不能直接显示。C：压缩骨折定位用局部腰椎片即可。D：骶髂关节炎用骨盆片。E：结核定性需CT/MR结合临床，均不符合全长摄影的主要用途。", "tr": "全脊柱摄影的核心价值是侧凸测量（Cobb角）与全脊柱平衡评估。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1005", "t": "单选题", "s": "DR图像拼接技术的含义是", "o": {"A": "分段采集多幅图像后用软件合成一幅完整图像", "B": "把两幅不同患者图像叠加", "C": "对图像进行锐化处理", "D": "将图像压缩存储", "E": "放大局部图像"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-105", "kp": "DR图像拼接概念", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】当投照区域超出探测器尺寸时，分段采集相邻图像，通过软件识别重叠区域自动融合成一幅连续完整的图像，即为图像拼接，故A正确。\n【为什么错】B：不同患者的图像不能拼接。C：锐化是后处理增强。D：压缩是存储优化。E：放大是显示操作，均非拼接技术含义。", "tr": "拼接是“同一次检查的分段采集+软件融合”，用于超长部位成像。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1006", "t": "单选题", "s": "保证DR拼接图像质量的关键措施是", "o": {"A": "各段曝光条件保持一致并保证相邻图像有足够重叠", "B": "各段随意改变管电压", "C": "相邻段之间留出空隙", "D": "患者随意移动体位", "E": "各段使用不同滤线栅方向"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-106", "kp": "拼接图像质量控制", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】各段曝光条件一致可保证拼接后密度均匀，相邻图像有一定重叠量供软件配准融合，两者是拼接成功的关键，故A正确。\n【为什么错】B：管电压改变导致各段密度差，拼接处明显分界。C：留空隙无法连续拼接。D：体位移动造成结构错位。E：滤线栅方向不一致影响密度均匀性，均错误。", "tr": "拼接两大要点：曝光一致+重叠区配准，任何环节失控都会产生拼接伪影。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1007", "t": "单选题", "s": "数字体层融合技术（DTS）的基本原理是", "o": {"A": "X线管在有限角度范围内移动连续曝光，经重建获得多层图像", "B": "X线管固定一次曝光", "C": "球管旋转360°扫描", "D": "双能量双次曝光", "E": "电子束偏转扫描"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-107", "kp": "数字体层融合原理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS（Digital Tomosynthesis）由X线管在有限角度范围内移动，对同一部位多次低剂量曝光，采集的投影数据经重建形成多层厚度可调的层面图像，故A正确。\n【为什么错】B：单次固定曝光只能得到平面影像。C：360°旋转为CT扫描方式。D：双能量减影是能量分离技术。E：电子束偏转是电子束CT的概念，均不属于DTS原理。", "tr": "DTS是“有限角度+多角度投影重建”，与CT的360°扫描、与双能减影均不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1008", "t": "单选题", "s": "与CT相比，数字体层融合（DTS）的主要特点是", "o": {"A": "扫描角度范围小、辐射剂量相对较低", "B": "扫描速度最慢", "C": "空间分辨率最高", "D": "只能用于颅脑", "E": "必须使用对比剂"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-108", "kp": "DTS与CT比较", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS仅在有限角度内曝光，射线利用率与剂量明显低于CT，兼具体层成像能力，故A正确。\n【为什么错】B：DTS采集速度快于常规CT。C：空间分辨率低于CT。D：DTS可用于胸、骨关节、乳腺等多部位。E：DTS为平扫技术，无需对比剂。", "tr": "DTS的定位是“低剂量体层成像”，介于平片与CT之间的补充技术。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1009", "t": "单选题", "s": "胸片疑肋骨骨折而常规正位片难以明确时，优先选择的体层技术是", "o": {"A": "胸部数字体层融合（DTS）", "B": "双能量减影软组织像", "C": "全身拼接摄影", "D": "负重摄影", "E": "断层CT平扫"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-109", "kp": "DTS临床应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】胸部DTS可分层显示肋骨，消除肺纹理与骨性结构的重叠干扰，提高隐匿性肋骨骨折检出率，是正位片后的合理补充，故A正确。\n【为什么错】B：软组织像用于去骨显示软组织，肋骨本身为骨组织，效果有限。C：拼接用于超长部位。D：负重摄影用于力线评估。E：CT平扫剂量高于DTS，非首选。", "tr": "肋骨骨折“平片→DTS”路径，利用DTS的分层显示克服重叠。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1010", "t": "单选题", "s": "DR双能量减影技术的成像基础是", "o": {"A": "不同组织对不同能量X线的吸收衰减差异", "B": "探测器分辨率", "C": "患者体位摆放", "D": "曝光时间长短", "E": "图像压缩方式"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-110", "kp": "双能量减影原理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】双能量减影利用骨、软组织、碘等对低能与高能X线吸收系数的差异，通过加权减影分离出骨像或软组织像，故A正确。\n【为什么错】B：探测器分辨率影响细节不参与能量分离。C：体位是操作因素。D：曝光时间决定剂量与运动模糊，不决定能量分离。E：压缩是存储优化，均非成像基础。", "tr": "双能量减影的本质是“能量域分离组织”，而非空间或时间维度的处理。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1011", "t": "单选题", "s": "DR双能量减影获得的“软组织像”（去骨像）最常用于", "o": {"A": "观察肋骨骨折等骨性结构", "B": "显示肺内软组织病变并去除肋骨干扰", "C": "测量下肢力线", "D": "评估乳腺压迫厚度", "E": "定位金属异物"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-111", "kp": "双能量软组织像应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】软组织像通过减影去除骨组织（肋骨、锁骨）干扰，清晰显示肺内结节、肿块等软组织病变，故B正确。\n【为什么错】A：观察骨性结构应使用骨像而非软组织像。C：力线测量与减影无关。D：乳腺压迫厚度与能量成像无关。E：金属异物定位不依赖软组织像。", "tr": "软组织像=去骨、看软组织；骨像=去软组织、看骨与钙化，用途相反。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1012", "t": "单选题", "s": "双能量减影技术中“骨像”（去除软组织）可用于", "o": {"A": "观察肺内结节伴钙化", "B": "显示乳腺实质", "C": "评估肌肉水肿", "D": "测量关节间隙宽度", "E": "显示胃肠道黏膜"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-112", "kp": "双能量骨像应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】骨像去除软组织后，骨组织和钙化显示更清晰，利于观察肺结节内钙化及肋骨骨性病变，故A正确。\n【为什么错】B：乳腺实质为软组织，用软组织像或常规像显示。C：肌肉水肿X线不显示。D：关节间隙测量用常规负重片。E：胃肠道黏膜需造影检查，均与骨像用途不符。", "tr": "骨像突出“钙化与骨”，用于鉴别结节钙化、肋骨病变等。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1013", "t": "单选题", "s": "数字合成体层成像（DBT）应用的检查部位是", "o": {"A": "乳腺", "B": "颅脑", "C": "心脏", "D": "消化道", "E": "骨骼肌"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-113", "kp": "DBT概念", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT（Digital Breast Tomosynthesis）是乳腺专用数字合成体层成像技术，通过有限角度多投影重建乳腺各层图像，故A正确。\n【为什么错】B：颅脑不使用DBT。C：心脏不使用DBT。D：消化道不使用DBT。E：骨骼肌不使用DBT，DBT专用于乳腺。", "tr": "DBT专指乳腺合成体层，胸部等其他部位合成体层一般称DTS。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1014", "t": "单选题", "s": "DBT减少乳腺组织重叠、提高病灶检出率的关键机制是", "o": {"A": "多角度投影重建获得分层图像，消除重叠结构干扰", "B": "增大压迫力度", "C": "提高管电流", "D": "延长曝光时间", "E": "使用造影剂"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-114", "kp": "DBT成像机制", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT使球管在有限角度内移动多次低剂量曝光，重建出不同深度的层面图像，各层面分别聚焦于相应深度，从而减少正常腺体组织重叠对病变的掩盖，故A正确。\n【为什么错】B：压迫与重叠无关，且压迫是常规操作。C：提高管电流增加剂量不消除重叠。D：延长曝光增加运动伪影风险。E：DBT为平扫技术，无需造影剂。", "tr": "DBT的核心价值是“分层去重叠”，适合致密型乳腺。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1015", "t": "单选题", "s": "DBT检查时X线球管的运动方式是", "o": {"A": "在有限角度范围内旋转扫描并多次低剂量曝光", "B": "固定不动一次曝光", "C": "围绕人体旋转360°", "D": "上下平移不曝光", "E": "前后对侧双曝光"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-115", "kp": "DBT扫描方式", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT中球管沿弧线在有限角度（不同机型约15°~50°）内旋转，同时多次低剂量曝光采集不同角度投影，故A正确。\n【为什么错】B：固定曝光只能获得二维影像。C：360°旋转是CT方式。D：不曝光无法成像。E：双曝光是双能量或双侧摄影概念，与DBT不同。", "tr": "DBT的“旋转+多次低剂量曝光”与CT的“360°连续旋转”在角度范围上不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1016", "t": "单选题", "s": "与常规乳腺数字摄影（FFDM）相比，DBT的主要优势是", "o": {"A": "提高致密型乳腺中病变的检出率", "B": "完全消除辐射剂量", "C": "不需要压迫乳腺", "D": "可检查任意体位", "E": "不需要技师操作"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-116", "kp": "DBT临床优势", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT通过分层减少重叠，对致密型乳腺中肿块、结构扭曲等病变的检出率和准确性优于常规FFDM，故A正确。\n【为什么错】B：DBT仍有一定辐射剂量，仅较FFDM略增或相当，不能消除。C：DBT仍需压迫固定乳腺。D：检查体位仍为CC、MLO等标准体位。E：检查全程需技师操作与压迫。", "tr": "DBT的优势是检出率，不是“零剂量、免压迫”，这些是常见干扰。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1017", "t": "单选题", "s": "DR双能量减影的两种主要实现方式是", "o": {"A": "一次曝光的双层探测器双能采集与两次曝光的管电压切换", "B": "一次曝光单层探测器", "C": "两次曝光相同管电压", "D": "核素显影", "E": "超声双幅"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-117", "kp": "双能量减影实现方式", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】双能量减影可采用双层探测器一次曝光（同一X线束分高低能层）或两次曝光快速切换高低管电压获得高低能图像，故A正确。\n【为什么错】B：单层探测器一次曝光无法分离能量。C：两次曝光相同kV无法形成能量差异。D：核素显影属核医学，非X线双能方式。E：超声双幅与双能量减影无关。", "tr": "一次曝光双层探测器法无运动伪影，两次曝光kV切换法需注意患者运动。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U14-1018", "t": "单选题", "s": "进行双下肢负重全长DR摄影时，患者正确的摆位要求是", "o": {"A": "双足并拢或与肩同宽站立、双下肢同时负重、膝关节伸直", "B": "单足站立", "C": "双膝屈曲90°", "D": "背向探测器站立", "E": "身体随意倾斜"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-118", "kp": "下肢全长摄影摆位", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】双下肢同时承重、膝关节伸直、足位一致站立，可真实反映生理应力下的下肢力线与内外翻程度，故A正确。\n【为什么错】B：单足站立受力不对称，无法评价双侧力线。C：屈膝改变关节关系。D：应面向探测器。E：身体倾斜造成假性畸形，均错误。", "tr": "负重摄影摆位强调“双足同时承重、双下肢并拢伸直、髋膝朝前”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1019", "t": "多选题", "s": "下肢负重全长摄影的适应证包括", "o": {"A": "膝骨性关节炎力线评估", "B": "全膝关节置换术前规划", "C": "下肢内外翻畸形测量", "D": "下肢骨折术后力线复查", "E": "膝关节半月板损伤诊断"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-119", "kp": "负重摄影适应证", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】关节炎、畸形、术前规划及术后复查均需评估承重状态下下肢力线与关节状态，故A、B、C、D正确。\n【为什么错】E：半月板为软骨软组织，X线平片无法直接显示，应行MRI检查。", "tr": "负重片看“骨性力线与关节间隙”，软组织损伤（半月板、韧带）需MRI。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1020", "t": "多选题", "s": "提高DR图像拼接质量的技术要求包括", "o": {"A": "各段曝光条件（kV、mAs）保持一致", "B": "相邻图像间保留足够重叠区域", "C": "患者体位在各段采集间保持固定", "D": "软件自动识别重叠区并融合校正", "E": "各段使用不同滤线栅方向"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-120", "kp": "拼接技术要求", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】曝光一致保证密度均匀，重叠区供配准，体位固定防错位，软件融合校正保证连续性，故A、B、C、D正确。\n【为什么错】E：各段滤线栅方向不一致会造成密度不匀、拼接分界明显。", "tr": "拼接四要素：曝光一致、重叠配准、体位固定、软件融合。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1021", "t": "多选题", "s": "数字体层融合（DTS）的临床应用包括", "o": {"A": "胸部肺结节的检出与定位", "B": "隐匿性肋骨骨折诊断", "C": "骨关节病变的补充体层成像", "D": "金属内固定术后骨痂观察", "E": "全身血管造影"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-121", "kp": "DTS临床应用范围", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS用于肺结节、肋骨骨折、骨关节体层及金属内固定周围骨质观察等，均利用分层去重叠优势，故A、B、C、D正确。\n【为什么错】E：血管造影属于DSA技术，DTS为平片体层技术，不用于血管造影。", "tr": "DTS适用于“平片上重叠干扰明显”的病变，血管系统不属于其范畴。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1022", "t": "多选题", "s": "DR双能量减影的临床应用包括", "o": {"A": "去除肋骨干扰显示肺内软组织病变", "B": "分离骨像观察钙化", "C": "碘剂负荷下的组织强化显示", "D": "肋骨骨折的鉴别显示", "E": "下肢力线测量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-122", "kp": "双能量减影临床应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】双能减影可去骨显示软组织、分离钙化骨像、增强含碘组织显示并辅助肋骨骨折判断，故A、B、C、D正确。\n【为什么错】E：下肢力线测量用负重全长摄影，与能量减影无关。", "tr": "双能减影的价值在“能量域分离骨/软组织/碘”，力线测量属几何学应用。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1023", "t": "多选题", "s": "DR双能量减影能够分离的组织物质包括", "o": {"A": "骨组织", "B": "软组织", "C": "碘剂", "D": "钙化组织", "E": "气腹气体"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-123", "kp": "双能量物质分离", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】双能量减影依据不同物质能量衰减特性，可分离骨、软组织、碘及钙化等成分，故A、B、C、D正确。\n【为什么错】E：气腹气体（空气）与软组织衰减差异并非双能减影的分离目标，气腹显示依赖体位与常规摄影。", "tr": "双能分离的是“高原子序数成分（骨/钙/碘）与软组织”，气体分离不属于其典型应用。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1024", "t": "多选题", "s": "DBT技术的优点包括", "o": {"A": "分层显示减少组织重叠", "B": "提高致密型乳腺病变检出率", "C": "可重建任意层厚与层面图像", "D": "减少重复召回检查", "E": "不需要压迫乳腺"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-124", "kp": "DBT优点", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT分层去重叠、提高致密乳腺检出、重建多层面图像、减少因重叠引起的召回，均为其优点，故A、B、C、D正确。\n【为什么错】E：DBT仍须常规压迫乳腺以固定并减少厚度，不能省略。", "tr": "压迫是乳腺摄影的基本要求，DBT不例外。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1025", "t": "多选题", "s": "乳腺X线检查设备的进展包括", "o": {"A": "数字乳腺摄影（FFDM）", "B": "数字合成体层成像（DBT）", "C": "对比增强乳腺摄影（CESM）", "D": "乳腺专用双能量成像", "E": "全身CT扫描代替乳腺摄影"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-125", "kp": "乳腺X线设备进展", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (1)乳腺X线检查设备", "ex": "【为什么对】FFDM、DBT、CESM及乳腺专用双能量成像均为乳腺X线设备与技术的进展方向，故A、B、C、D正确。\n【为什么错】E：全身CT剂量高、乳腺受照大，不能代替专用乳腺摄影。", "tr": "乳腺成像强调专用设备与低剂量，全身CT不具备替代性。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1026", "t": "多选题", "s": "全脊柱负重正位摄影的临床用途包括", "o": {"A": "脊柱侧凸Cobb角测量", "B": "冠状面躯干平衡评估", "C": "下肢不等长相关代偿分析", "D": "术后矫形效果复查", "E": "椎间盘突出定性诊断"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-126", "kp": "全脊柱摄影用途", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】全脊柱负重位可测Cobb角、评估躯干平衡、分析代偿及复查术后效果，故A、B、C、D正确。\n【为什么错】E：椎间盘为软组织，X线不能直接显示，需CT/MRI。", "tr": "X线平片评估骨性畸形与平衡，软组织结构（椎间盘）超出其能力。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1027", "t": "多选题", "s": "DR拼接图像出现拼接处错位或密度不均的可能原因包括", "o": {"A": "各段曝光条件不一致", "B": "患者在两段采集间移动", "C": "重叠区域过小导致配准失败", "D": "滤线栅方向不一致", "E": "图像分辨率设置过高"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-127", "kp": "拼接伪影原因分析", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】曝光不一致致密度差异，体位移动致错位，重叠不足致配准失败，滤线栅方向不一致致密度分界，均为拼接失败原因，故A、B、C、D正确。\n【为什么错】E：分辨率设置越高图像越清晰，不产生错位或密度不均伪影。", "tr": "拼接伪影源于“条件、体位、重叠、几何”控制不良，与分辨率高低无直接关系。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U14-1028", "t": "多选题", "s": "关于DBT与FFDM联合检查的正确说法是", "o": {"A": "DBT可减少组织重叠对病变的掩盖", "B": "合成二维图像可部分替代额外FFDM曝光，降低剂量", "C": "DBT适用于致密型乳腺", "D": "DBT层厚可在后处理中调整", "E": "DBT完全取代超声检查"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-128", "kp": "DBT临床应用要点", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT分层去重叠、适合致密乳腺，合成二维图像可减少额外曝光剂量，层面厚度可后处理调整，故A、B、C、D正确。\n【为什么错】E：DBT是X线体层技术，不能替代超声对囊实性病变的鉴别等功能。", "tr": "DBT与超声、MRI互补而非替代，勿夸大DBT能力。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U14-1029a", "t": "共用题干题", "s": "为完整评估下肢力线，应采用的摄影方式是", "o": {"A": "双下肢站立负重全长正位摄影（拼接）", "B": "右膝单独平卧正侧位", "C": "双踝负重侧位", "D": "双髋平卧轴位", "E": "脊柱全长正位"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-129", "kp": "下肢力线评估摄影方式", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】评估下肢力线须在站立负重位一次性显示髋、膝、踝全长，利用DR拼接获得全下肢图像，故A正确。\n【为什么错】B：仅膝关节局部片无法评估全长力线。C：双踝负重侧位范围不符。D：双髋平卧轴位范围不符。E：脊柱全长正位用于脊柱侧凸，与膝力线无关。", "tr": "“力线评估”对应双下肢全长负重拼接片，局部片无法完成。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1401", "gs": "患者男性，68岁，双膝骨性关节炎，右膝内翻畸形明显，拟行全膝关节置换术。骨科医师申请下肢全长负重正位摄影，以评估下肢力线并制定术前规划。技师需确定摄影方式与测量参数。"}, {"id": "U14-1029b", "t": "共用题干题", "s": "术后复查时，测量下肢力线畸形的常用角度参数是", "o": {"A": "髋-膝-踝角（HKA角）", "B": "Cobb角", "C": "骶髂角", "D": "耻骨联合角", "E": "眼眶角"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-130", "kp": "下肢力线测量参数", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】髋-膝-踝角（HKA）由髋中心、膝中心、踝中心连线构成，是评价膝内外翻畸形的核心参数，故A正确。\n【为什么错】B：Cobb角用于脊柱侧凸。C：骶髂角、D：耻骨联合角、E：眼眶角均非下肢力线测量参数。", "tr": "下肢看HKA角，脊柱看Cobb角，部位与参数要对应。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1401", "gs": ""}, {"id": "U14-1030a", "t": "共用题干题", "s": "为进一步显示肋骨骨折细节，优先选用的补充检查是", "o": {"A": "胸部数字体层融合（DTS）", "B": "全身CT增强", "C": "上肢负重摄影", "D": "双能量软组织像", "E": "乳腺DBT"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-131", "kp": "肋骨骨折补充体层", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS可对肋骨所在层面分层成像，消除重叠干扰，明确骨折线，且剂量远低于CT，适合此类补充检查，故A正确。\n【为什么错】B：CT增强并非肋骨骨折常规，且剂量较高。C：负重摄影用于力线。D：软组织像去骨后肋骨显示反而不佳。E：DBT用于乳腺，部位不符。", "tr": "肋骨骨折首选补充检查是DTS，兼顾诊断与剂量控制。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1402", "gs": "患者男性，45岁，胸部外伤后持续胸痛，常规胸部正位片显示右侧第7肋腋段可疑骨折线，但受肋骨与肺纹理重叠影响难以确诊。临床希望在不增加较大辐射负担的情况下进一步明确。"}, {"id": "U14-1030b", "t": "共用题干题", "s": "与胸部CT平扫相比，胸部DTS的突出特点是", "o": {"A": "辐射剂量相对较低", "B": "空间分辨率高于CT", "C": "不需要屏气", "D": "可显示全部软组织", "E": "扫描范围无限制"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-132", "kp": "DTS与CT剂量比较", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS仅有限角度低剂量曝光，辐射剂量明显低于同部位CT，故A正确。\n【为什么错】B：CT空间分辨率更高。C：胸部DTS仍需屏气减少运动模糊。D：DTS软组织密度分辨力低于CT，不能显示全部软组织。E：DTS扫描范围受角度与探测器限制，并非无限制。", "tr": "DTS定位是“CT与平片之间的低剂量补充”，高分辨力与全软组织显示仍属CT优势。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": true, "src": "模拟", "mk": 0, "gid": "G1402", "gs": ""}, {"id": "U14-1031a", "t": "共用题干题", "s": "行DBT检查时，X线球管的扫描方式是", "o": {"A": "在有限角度范围内旋转并多次低剂量曝光", "B": "固定角度单次高剂量曝光", "C": "360°旋转扫描", "D": "不曝光仅透视", "E": "双球管同时曝光"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-133", "kp": "DBT球管扫描方式", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT球管沿弧线在有限角度内旋转，多次低剂量曝光采集多角度投影，再重建各层图像，故A正确。\n【为什么错】B：单次曝光只能得到二维图像。C：360°旋转是CT方式。D：不曝光无法成像。E：DBT为单球管技术，无双球管同时曝光。", "tr": "“有限角度多次曝光”是DBT的特征，与CT的360°旋转不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1403", "gs": "患者女性，52岁，乳腺普查发现左乳外上象限结构紊乱伴可疑微钙化，因腺体较致密，常规FFDM难以判断钙化是否聚集及有无肿块。医师建议加做DBT检查进一步评估。"}, {"id": "U14-1031b", "t": "共用题干题", "s": "为提高检查效率并控制总辐射剂量，DBT后处理中可采用的做法是", "o": {"A": "由断层数据重建合成二维图像替代常规FFDM", "B": "加大管电流扫描", "C": "取消压迫", "D": "重复多次曝光", "E": "缩短球管旋转角度至0°"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-134", "kp": "DBT合成二维图像", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】由DBT断层数据重建的合成二维图像（synthetic 2D）与断层图像同时提供，可免去额外的FFDM采集，降低总剂量，故A正确。\n【为什么错】B：加大管电流增加剂量。C：取消压迫违反摄影规范。D：重复曝光增加剂量。E：角度为0°则无法形成断层投影。", "tr": "合成二维图像是DBT“一次采集、两种图像”的剂量优化手段。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1403", "gs": ""}, {"id": "U14-1032", "t": "案例分析题", "s": "患者男性，56岁，双膝骨性关节炎伴右膝内翻，拟行右膝置换术前下肢力线评估。技师使用DR拼接功能分三次曝光采集双下肢全长正位图像。拼接结果显示接缝处骨轮廓出现错位，下肢轮廓在拼接点不连续，影响力线测量。技师需定位并解决该问题。拼接软件依靠相邻段重叠区域的特征点自动配准融合，体位移动会导致配准失败。技师应重点核查的环节是", "o": {"A": "患者各段采集间是否保持静止及重叠区配准是否准确", "B": "探测器分辨率设置", "C": "胶片尺寸", "D": "显示器亮度", "E": "图像压缩率"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-135", "kp": "拼接错位排查", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】拼接错位的直接原因是患者体位移动导致相邻段骨轮廓不连续，或重叠区过小致软件配准失败，故A正确。\n【为什么错】B：分辨率影响细节不影响错位。C：胶片尺寸与拼接错位无关。D：显示器亮度为显示设置。E：压缩率影响存储不影响几何对位。", "tr": "拼接错位查“体位固定与重叠配准”，不要在外围设置上兜圈。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1033", "t": "案例分析题", "s": "患者女性，60岁，体检胸片显示右下肺一枚1.2cm结节，形态欠清，医师希望判断结节内有无钙化以帮助定性。常规正位片因肋骨与心脏阴影重叠，结节显示不清。该院配备DR双能量减影设备。双能量减影可分离骨与软组织成分，骨像与软组织像分别用于钙化和软组织显示。钙化与软组织衰减特征不同，选择合适的能量分离图像是判断前提。技师应选择的后处理图像是", "o": {"A": "骨像（去软组织像）突出钙化", "B": "软组织像观察结节本身", "C": "软组织像同时观察钙化", "D": "拼接图观察钙化", "E": "负重像观察钙化"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-136", "kp": "双能量减影钙化显示", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】骨像去除软组织后，钙化（与骨同属高原子序数物质）显示更清晰，利于判断结节内钙化，故A正确。\n【为什么错】B：软组织像会同时去除钙化成分，无法观察钙化。C：软组织像不含钙化信息。D：拼接图像无能量分离能力。E：负重像与钙化显示无关。", "tr": "钙化与骨同源，看钙化用“骨像”；看软组织病变用“软组织像”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U14-1034", "t": "案例分析题", "s": "患者女性，48岁，致密型乳腺，行DBT检查后发现部分层面图像出现运动性模糊，微钙化与结构扭曲判断受影响。技师分析原因为患者在扫描过程中轻微移动所致。为减少后续检查中的DBT运动伪影，DBT单次检查需多次低剂量曝光，扫描时间数秒，患者需保持静止并屏住呼吸配合。适当的压迫可减少移动并降低厚度，是质控的重要环节。最有效的操作措施是", "o": {"A": "充分解释流程、适当压迫并嘱患者在扫描期间保持静止、避免呼吸起伏", "B": "取消压迫让患者放松", "C": "缩短扫描时间至不足1秒但加大剂量", "D": "让患者大声说话分散注意力", "E": "扫描过程中移动患者体位"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-137", "kp": "DBT运动伪影控制", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】充分沟通使患者理解流程、保持适当压迫并嘱静止、屏住呼吸，是减少运动伪影最有效且安全的措施，故A正确。\n【为什么错】B：取消压迫会加重移动与厚度增加。C：大幅提高剂量不可取。D：说话会诱发呼吸运动。E：移动体位必然产生伪影，均错误。", "tr": "运动伪影的防控核心是“固定+配合”，不能以牺牲压迫或增加剂量为代价。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1035", "t": "案例分析题", "s": "患者男性，15岁，学校体检发现脊柱侧凸，来院行全脊柱负重正位及侧位摄影，用于Cobb角测量与矫形评估。技师负责完成检查并进行图像质控。若摆位不当将导致Cobb角测量失真。为保证测量准确，全脊柱正位摄影的全脊柱摄影常采用多段曝光后拼接，各段间需保持患者体位绝对稳定。测量结果直接关系到矫形与手术决策，摆位标准化至关重要。关键摆位要求是", "o": {"A": "患者自然站立、双肩与双侧髂嵴等高、骨盆水平、去除外固定", "B": "患者弯腰90°站立", "C": "患者侧卧拍摄", "D": "患者双手抱膝站立", "E": "患者跳跃落地瞬间曝光"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-138", "kp": "全脊柱摄影摆位", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】自然站立、肩髋水平、骨盆端正、去除外固定可真实反映脊柱畸形并保证测量基线一致，故A正确。\n【为什么错】B：弯腰体位改变脊柱形态。C：侧卧非负重状态。D：抱膝位改变躯干姿态。E：动态曝光产生运动伪影，均不符合测量要求。", "tr": "全脊柱摄影追求“自然直立、对称水平”的标准化摆位，任何变形姿态都会影响测量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U14-1036", "t": "案例分析题", "s": "某医院拟开展DR双能量减影胸片检查，采用两次曝光（高低管电压切换）方案。技师在为老年患者检查时发现，两次曝光间隔内患者发生呼吸移动，导致减影图像出现骨与软组织错位伪影，影响诊断。针对该问题，两次曝光法存在时间间隔，患者呼吸、心跳等运动可致高低能图像错位。解决思路应在保证图像质量的同时兼顾患者配合的可行性。处理方法中最合理的是", "o": {"A": "改用一次曝光的双层探测器双能成像，或嘱患者屏气并缩短两次曝光间隔", "B": "放弃双能减影检查", "C": "让患者快速呼吸", "D": "加大两次曝光剂量", "E": "提高图像分辨率"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-139", "kp": "双能量减影运动伪影处理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】一次曝光双层探测器法在同一X线束内完成高低能采集，无时间差，可从根本上消除运动伪影；嘱屏气、缩短曝光间隔也能减轻两次曝光法的运动影响，故A正确。\n【为什么错】B：双能减影有明确价值，不应轻言放弃。C：快速呼吸加剧运动。D：增加剂量不解决错位。E：分辨率不影响配准错位。", "tr": "两次曝光双能的软肋是运动伪影，双层探测器一次曝光是解决思路。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U14-1037", "t": "案例分析题", "s": "患者男性，70岁，双侧全髋关节置换术后复查，骨科医师申请下肢全长负重片评估双下肢力线与假体位置。技师发现拼接图像中髋、膝、踝关节均清晰显示，但各段密度存在轻微差异，接缝处可见隐约分界，影响图像整体观感与测量可重复性。为改善图像质量，密度差异可通过软件自动均衡校正改善，同时应统一各段曝光条件。最合适的措施是", "o": {"A": "后处理时应用密度均衡校正，并对各段曝光条件进行统一化处理", "B": "删除该检查重新拍摄", "C": "仅保留密度较高的一段", "D": "提高显示器伽马", "E": "加做CT重建"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-140", "kp": "拼接密度均衡处理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】拼接图像密度不均可通过软件密度均衡校正与统一各段曝光参数来改善，保证整幅图像观感一致、测量可靠，故A正确。\n【为什么错】B：轻度密度差异无需重拍，重拍成本高。C：只保留一段失去全长信息。D：显示器伽马是显示端调整，不改变图像数据。E：CT重建与负重片目的不符且剂量高。", "tr": "拼接密度不均优先用“软件均衡校正”，重拍与裁切都不是好方案。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U15-0101", "t": "单选题", "s": "与影像增强器（II-TV）系统相比，平板探测器（FPD）DSA系统在成像性能上最本质的优势是", "o": {"A": "视野呈圆形，便于全景观察大范围血管", "B": "量子探测效率（DQE）更高、动态范围更宽，且不存在枕形失真、S形畸变与边缘渐晕", "C": "极限空间分辨率不再受探测器像素尺寸的限制", "D": "成像链环节更多，信号经多次转换后对比度更好", "E": "对散射线不敏感，因此可以省略滤线栅"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-001", "kp": "平板探测器DSA的硬件优势", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】B正确。FPD为平面直接成像结构，取消了影像增强器的电子光学放大链（输入屏—光电阴极—静电聚焦—输出屏—光学耦合—摄像器件），因而不产生枕形失真、S形畸变、边缘分辨率下降与渐晕；动态范围可达10⁴以上（II约10³），DQE明显提高，同等图像质量下辐射剂量更低。【为什么错】A错误：FPD视野为矩形（方形），影像增强器才是圆形，两者说反了；矩形视野的有效面积利用率更高。C错误：FPD的极限空间分辨率恰由像素尺寸（约0.15~0.20mm）与矩阵决定，并非不受限制。D错误：成像链环节越多，噪声与失真累积越多，这是II的缺点而非优点。E错误：FPD同样接收散射线，仍需配用滤线栅并做散射校正。", "tr": "FPD视野是矩形而非圆形，是与II对比时最易颠倒的一点。另需记住FPD分辨率并非无限，其像素尺寸约0.15~0.20mm，优于II的0.3mm以上。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0102", "t": "多选题", "s": "关于DSA的C形臂机架形式与双C臂双平面系统，下列说法正确的是", "o": {"A": "落地式机架承重与机械刚度好，旋转采集时等中心重复精度高，但占用手术床周围的地面空间", "B": "悬吊式（天轨）机架可沿导轨大范围移动并移出术野，便于麻醉与外科团队在床旁操作", "C": "双C臂双平面系统一次对比剂注射即可同时获得正、侧位两个方向影像，有利于减少注射次数与对比剂总量", "D": "双平面系统两个平面的成像参数由系统统一设定，两侧须使用相同的帧率、视野与曝光条件", "E": "双平面同时工作时存在交叉散射，可通过两平面脉冲错峰（交替曝光）减轻互相干扰"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-002", "kp": "DSA机架形式与双平面系统", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】A正确：落地式刚性好、承载大，旋转与步进的机械重复性优，代价是占用床旁地面空间。B正确：悬吊式解放地面，可整体泊出术野，是复合手术室（Hybrid OR）的主流选择。C正确：双平面一次注射获得两个投照方向，减少注射次数与对比剂总量，对儿童、神经介入和心血管造影意义重大。E正确：交叉散射是双平面同时曝光的固有问题，工程上以脉冲时序交替与散射校正抑制。【为什么错】D错误：双平面两个平面的帧率、视野、管电压/管电流、脉冲宽度均可独立设定，临床常见正位低帧率、侧位高帧率的组合。", "tr": "「双平面必须同步同参数」是常见误解。双平面的价值恰在于两平面可按各自观察需求独立配置，仅在曝光时序上错峰以避免交叉散射。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-0103", "t": "单选题", "s": "DSA检查中高压注射器与X线机联动时采用「曝光延迟」方式，其含义是", "o": {"A": "先启动X线曝光采集蒙片，延迟设定时间后再启动注射", "B": "先启动对比剂注射，延迟设定时间后再启动X线曝光采集", "C": "注射与曝光同步启动，两者之间无时间差", "D": "对比剂注射完毕后延迟数秒再开始曝光", "E": "由术者踩板随机控制，两者之间无固定时序关系"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-003", "kp": "高压注射器与DSA设备的联动方式", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】B正确。联动方式以「被延迟的动作」命名：曝光延迟即以注射为时间起点、X线曝光相对滞后，适用于导管头端距靶血管较远、对比剂需一段运行时间才能到达感兴趣区的情形（如经上肢入路或长导管注射远端血管）。【为什么错】A错误：A描述的是「注射延迟」（对比剂延迟），先曝光采集不含碘的蒙片再注射，是DSA最常用的联动方式，与曝光延迟概念相反。C错误：完全同步会使蒙片帧内已混入对比剂，破坏减影基础。D错误：注射完毕后再曝光将错过对比剂充盈高峰。E错误：手动踩板时序重复性差，不属于「联动」范畴。", "tr": "曝光延迟＝先注射后曝光；注射延迟＝先曝光后注射。命名指向被延迟的动作，考试中最易记反。DSA需先获得蒙片，故临床默认多用注射延迟。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0104", "t": "案例分析题", "s": "患者男性，62岁，左侧髂动脉长段闭塞拟行腔内开通术，预计透视时间较长。设备为平板探测器单C臂DSA，具备可变脉冲透视（3.75/7.5/15脉冲每秒）、附加铜滤过（0.1~0.9mm）、末帧图像保持（LIH）配合虚拟准直及透视储存功能。患者体型偏胖（BMI 29），术者希望在保证导丝、导管可视性的前提下尽量降低患者皮肤剂量与自身受照剂量。下列技术措施中最不恰当的是", "o": {"A": "将脉冲透视帧率由15脉冲每秒降至7.5甚至3.75脉冲每秒", "B": "在球管侧加用铜滤过，滤除对成像几乎无贡献的低能光子", "C": "全程使用小视野（高放大档）透视，以便把导丝细节看得更清楚", "D": "使用末帧图像保持配合虚拟准直，在不曝光状态下完成准直器调整", "E": "升高检查床或降低探测器使其贴近患者体表，同时保证足够的源—皮距"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-004", "kp": "介入透视的剂量管理措施", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】C最不恰当。缩小视野提高电子放大档时，自动亮度控制为维持探测器入射剂量恒定，会按视野面积的反比提高患者入射剂量率，是介入操作皮肤剂量超标的常见原因。合理策略是以大视野为主，仅在关键步骤短时放大。【为什么错】A是标准措施：累积剂量与脉冲率近似成正比，降帧率最直接有效。B是标准措施：铜滤过滤除只沉积于皮肤而到不了探测器的低能光子，可使皮肤入射剂量明显下降。D是标准措施：末帧图像保持加虚拟准直可在零曝光下完成准直与遮挡调整，避免边看边调的额外曝光。E是标准措施：探测器贴近患者可减小几何放大与空气间隙散射，降低维持影像质量所需入射剂量率；同时保持足够源—皮距以避免皮肤剂量率过高。", "tr": "「放大看得清＝更安全」是典型误区。视野每缩小一档入射剂量率明显上升；肥胖患者本已需要更高输出，叠加放大更易在长时间手术中接近确定性皮肤效应阈值（约2Gy红斑、3Gy临时脱发）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0105", "t": "单选题", "s": "DSA实时数字减影处理中，先对图像信号做对数变换再相减，其根本原因是", "o": {"A": "对数变换能够提高图像的空间分辨率", "B": "X线在人体中呈指数衰减，取对数后信号与碘柱的浓度×厚度成线性关系，相减才能彻底消除背景", "C": "对数变换可以抑制量子噪声，使减影像的信噪比高于原始像", "D": "对数变换的作用是把模拟信号转换成数字信号", "E": "对数变换用于校正影像接收器的几何畸变"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-005", "kp": "对数变换与实时减影原理", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】B正确。X线透过人体满足I＝I₀e^(−μd)，若直接把造影像与蒙片相减，骨与软组织背景并不会抵消。取对数后lnI₀−lnI＝μd，信号与衰减系数×厚度成线性关系，两帧相减仅保留碘柱项（碘浓度×血管径），背景被完全消去，故对数放大是DSA成立的物理前提。【为什么错】A错误：空间分辨率取决于探测器像素、几何放大与焦点尺寸，与灰度变换无关。C错误：恰恰相反，两帧相减时噪声方差相加，减影像噪声标准差约为单帧的√2倍，故采集帧剂量需高于透视帧。D错误：模数转换由ADC完成。E错误：几何畸变校正是影像增强器系统特有的环节。", "tr": "减影提高的是对比度而非信噪比——减影使噪声增大约√2倍，这正是DSA采集帧剂量必须显著高于透视帧的原因。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0106", "t": "单选题", "s": "DSA图像出现运动性伪影时采用像素移位（pixel shift）技术校正，关于其原理与适用范围，下列说法正确的是", "o": {"A": "把蒙片在x、y方向做亚像素级平移（必要时叠加分区局部移位）与造影像重新配准后再减影，适用于以平移为主的轻度运动", "B": "从采集序列中另选一帧不含对比剂的图像替换原蒙片后重新减影", "C": "通过提高采集帧率把已经产生的运动错位消除", "D": "对造影像做高通滤波，把运动产生的边缘信号滤除", "E": "对吞咽、胃肠蠕动、心脏搏动等非刚性运动造成的伪影同样能够有效校正"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-006", "kp": "像素移位与运动伪影校正", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】A正确。像素移位的本质是图像配准：把蒙片相对造影像做亚像素级平移（先进系统支持分区局部移位与轻度旋转形变），使两帧解剖结构重新对齐后再相减，从而消除错位形成的「双边影」，对整体平移为主的轻度运动最有效。【为什么错】B错误：这是「再蒙片（remask）」技术，与像素移位是并列的两种后处理手段。C错误：帧率只影响采集阶段的时间分辨率，无法对已采集图像的错位做补救。D错误：高通滤波会同时削弱血管边缘信号并放大噪声，不能纠正配准误差。E错误：像素移位属整体或分区的刚性配准，对吞咽、肠蠕动、心搏这类大幅度非刚性运动效果有限，此类情况应重新采集或改用心电门控、屏气、加大镇静等措施。", "tr": "像素移位与再蒙片常被混为一谈：前者动的是蒙片的位置，后者换的是蒙片本身。二者都属减影后处理，均不能替代采集时的制动与配合。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0107", "t": "多选题", "s": "关于DSA的噪声抑制与图像后处理软件功能，下列说法正确的是", "o": {"A": "帧间递归滤波（时间平均）通过对连续帧加权累加降低量子噪声，但在快速运动部位会产生拖影", "B": "空间域自适应滤波在平坦区域强平滑、在边缘区域弱平滑，可在抑制噪声的同时保留血管边缘锐利度", "C": "低剂量透视时降低脉冲剂量必然导致噪声增加，先进的时空联合降噪算法可部分补偿从而维持可接受的图像质量", "D": "图像的边缘增强处理会同时放大噪声，因此增强强度需与降噪强度匹配设置", "E": "散射线的抑制可主要交由后处理降噪算法承担，滤线栅与准直器的作用能够被软件取代"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-007", "kp": "DSA噪声抑制与图像增强软件", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】A正确：递归（时间）滤波以牺牲时间分辨率换取信噪比，运动部位出现拖尾是其固有代价，故心脏、快速血流部位应减小递归权重。B正确：自适应滤波依据局部梯度调整平滑强度，是「保边降噪」的通用思路。C正确：现代低剂量透视正是依靠时间域与空间域联合降噪，在脉冲剂量下调后仍维持导丝导管可视性。D正确：边缘增强属高通操作，会放大高频噪声，须与降噪参数联动整定。【为什么错】E错误：散射线在到达探测器之前已经产生并携带错误的位置信息，后处理无法恢复其原始来源，滤线栅、准直与合理空气间隙仍是控制散射的物理手段，软件仅能做有限的散射校正。", "tr": "散射控制必须在信号形成阶段解决，任何后处理都无法真正「去掉」已混入的散射信息，只能做估计与近似扣除。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-0108", "t": "单选题", "s": "介入设备产生的辐射剂量结构化报告（RDSR）中，用于评估患者确定性皮肤损伤风险的最相关指标是", "o": {"A": "剂量面积乘积（DAP/KAP）", "B": "参考点空气比释动能（Ka,r，即参考点累积剂量）", "C": "透视总时间", "D": "采集图像的总帧数", "E": "球管的累积毫安秒"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-008", "kp": "剂量结构化报告与介入剂量指标", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】B正确。参考点空气比释动能Ka,r是在介入参考点（等中心向球管方向15cm处）累积的空气比释动能，量纲为Gy，与照射野内某点的皮肤累积剂量最直接相关，是预警皮肤红斑、脱发等确定性效应的首选指标。【为什么错】A错误：DAP（Gy·cm²）反映进入患者的总能量，与随机性效应及有效剂量估算相关，但同一DAP可由大野低剂量或小野高剂量产生，不能直接指示局部皮肤剂量峰值。C错误：透视时间不含剂量率信息，不同帧率、体厚下相同时间的剂量可相差数倍。D错误：帧数同样不含单帧剂量信息。E错误：毫安秒未计入管电压、滤过、距离与照射野，无法直接换算为皮肤剂量。【补充】RDSR按DICOM标准逐次曝光记录kV、mA、脉宽、投照角度、视野、Ka,r与DAP，可用于剂量追踪与峰值皮肤剂量重建。", "tr": "Ka,r与DAP的分工要分清：Ka,r对应确定性效应（皮肤），DAP对应随机性效应（全身）；透视时间只能做粗略提示，不能作为剂量指标。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0109", "t": "单选题", "s": "关于旋转DSA与三维DSA（3D-DSA）的采集与重建，下列说法正确的是", "o": {"A": "旋转DSA需先做一次不注射对比剂的旋转蒙片采集，再做一次同轨迹的注射旋转采集，两组数据对应角度减影后重建三维血管", "B": "3D-DSA只需一次旋转采集即可完成，无需蒙片", "C": "3D-DSA的三维重建以最大密度投影替代反投影算法完成", "D": "旋转采集的角度范围通常小于90度即可满足三维重建要求", "E": "3D-DSA重建后不能进行任意角度观察，只能显示采集时的实际角度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-009", "kp": "旋转DSA与3D-DSA重建", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】A正确。标准3D-DSA采用「两次旋转」模式：第一次空跑采集蒙片序列，第二次在对比剂持续注射下沿同一轨迹、同一角度步进采集，按角度一一对应减影得到纯血管投影，再经滤波反投影或迭代算法重建为三维容积数据。【为什么错】B错误：不做蒙片减影时得到的是含骨结构的旋转血管造影（三维血管造影），血管与颅底骨重叠严重，不能等同于3D-DSA。C错误：MIP是重建完成后的显示方式，不是重建算法本身，重建仍依靠反投影或迭代重建。D错误：旋转采集范围通常在180度加扇角以上，常用约200度，角度不足会造成重建信息缺失与条纹伪影。E错误：三维容积重建后可任意角度旋转观察，并可测量瘤颈、瘤体、载瘤动脉直径，用于选择工作角度与器械尺寸，这正是其临床价值。", "tr": "「旋转采集」不等于「3D-DSA」：前者可仅采集造影旋转序列供动态观察，后者强调蒙片减影后的三维容积重建。3D-DSA的主要用途是确定动脉瘤最佳工作角度与形态测量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0110", "t": "多选题", "s": "关于C臂锥形束CT（CBCT，厂家名称如DynaCT、XperCT、Innova CT）的成像特点，下列说法正确的是", "o": {"A": "利用C臂旋转采集数百幅锥形束投影，重建出类似CT的断层与容积图像，可在介入床上完成软组织观察", "B": "与常规多层螺旋CT相比，其密度分辨率较低、散射与截断伪影更明显，对小密度差病变的检出能力有限", "C": "旋转采集时间通常为数秒至二十余秒，需要患者屏气或制动配合以避免运动伪影", "D": "可用于术中即时判断颅内出血、支架贴壁、栓塞剂分布及穿刺针位置，减少患者往返CT室的转运风险", "E": "其空间分辨率低于常规CT，无法显示细小的高对比结构"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-010", "kp": "C臂锥形束CT软组织成像", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】A正确：CBCT以平板探测器一次旋转采集锥形束投影，重建出容积数据，实现介入床旁的「类CT」软组织成像。B正确：受锥形束散射、探测器动态范围、视野截断和采集时间限制，其低对比度分辨率明显不如MSCT，微小低密度差病灶易漏检。C正确：单次旋转常需5~20秒，运动伪影是主要质量制约因素，故要求屏气或必要时镇静。D正确：这正是其核心临床价值——术中即时排除颅内出血、评价支架贴壁与栓塞剂沉积、确认穿刺针位置，避免转运风险。【为什么错】E错误：CBCT的高对比空间分辨率反而优于常规CT，其平板像素小、各向同性体素可达0.2~0.5mm，显示支架金属丝、弹簧圈、骨小梁等高对比结构具有优势；它的短板在密度（低对比）分辨率而非空间分辨率。", "tr": "CBCT「空间分辨率高、密度分辨率低」，与MSCT恰好互补。把两种分辨率混为一谈是本考点最常见的失分点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U15-0111", "t": "单选题", "s": "关于路径图（roadmap）技术与三维路径图（3D roadmap），下列说法正确的是", "o": {"A": "常规路径图制作完成后，改变C臂角度、床面位置或视野时，系统会自动补偿几何变化并维持血管轮廓与实时透视的配准", "B": "三维路径图叠加的血管背景来自当次实时采集的二维减影像，与此前重建的三维容积数据无关", "C": "三维路径图是将已重建的三维血管容积与实时透视按机架角度、床位、放大率自动配准叠加，转动C臂时三维图像随之同步转动", "D": "三维路径图在患者体位移动后可由系统自动识别并纠正错位，无需重新配准", "E": "使用路径图技术时必须持续注射对比剂才能维持血管背景显示"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-011", "kp": "路径图与三维路径图技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】C正确。3D roadmap把先前旋转采集重建的三维血管容积与C臂几何参数（角度、SID、床位、视野）实时关联，透视时按当前投照几何生成对应的二维投影叠加，术者转动C臂即可获得相应角度的血管背景，无需重新注射对比剂制作路径图。【为什么错】A错误：常规路径图与制作时的投照几何严格绑定，角度、床位、放大率任一改变都会失配准，必须重新制作。B错误：三维路径图的背景恰恰来自此前旋转采集重建的三维容积，若只用当次二维减影像就退化为常规路径图。D错误：任何配准都以患者与机架相对位置不变为前提，患者体动会造成三维图像与实际血管错位，需重新配准或校正。E错误：路径图的血管背景来自已保存的充盈帧，不需要持续注射，这正是其减少对比剂用量的意义。", "tr": "常规路径图「换角度即失效」，三维路径图「随角度自动更新」，这是两者的分水岭。但三维路径图仍依赖患者不动，体动后必须重新配准。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0112", "t": "案例分析题", "s": "患者男性，68岁，2型糖尿病史15年，吸烟40年。近3个月右下肢间歇性跛行进行性加重，跛行距离由500m缩短至50m，近1周出现静息痛，右足背动脉搏动未触及，踝肱指数0.38。临床怀疑右侧股腘动脉多节段狭窄闭塞，拟行下肢动脉DSA全面评估后同期球囊扩张。设备为平板探测器单C臂DSA，具备步进（bolus chase）采集与自动跟踪功能，高压注射器可编程设定流率、总量与注射时长。作为该台手术的技师，下列关于步进DSA技术要点的判断中，错误的是", "o": {"A": "先在不注射状态下沿全下肢做一次步进蒙片采集，注射后按相同床位与速度序列采集造影像，逐段对应减影", "B": "床面移动速度应与对比剂在下肢动脉内的流动速度相匹配，速度过快会「追过」对比剂前锋而使远端显影不足", "C": "严重狭窄或闭塞侧肢体血流缓慢，两侧充盈明显不对称时，可对患侧单独降低步进速度或改为分段采集", "D": "步进采集期间患者下肢必须保持不动，必要时用固定带约束并叮嘱勿咳嗽、勿移动", "E": "为提高远端小血管显示，应尽量使用高浓度对比剂并采用高流率短时间的团注方式"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-012", "kp": "下肢步进DSA（bolus chase）技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】E错误，为应选项。下肢步进DSA需要对比剂在数十秒内持续充盈由髂至足的长段血管，注射策略应是适当稀释（常用对比剂与生理盐水按约1:1稀释）、中等流率、延长注射时间的「长团注」，以保证追踪全程都有对比剂充盈；高流率短时间团注会使对比剂前锋过早通过近段而远端显影不足，且增加血管痛与外渗风险。【为什么错】A正确：步进DSA同样遵循先蒙片后造影、逐段配对减影的原则。B正确：床速与血流速度匹配是步进成功的关键，过快会超越对比剂前锋，过慢则近段过曝、远段延误。C正确：双下肢病变程度不对称时，应按患侧血流调整速度或改为分段（分站）采集，必要时行患侧选择性造影。D正确：步进过程中任何肢体移动都会造成逐段减影错位，制动与呼吸配合是基本要求。", "tr": "「浓度越高、流率越快越清楚」在步进DSA中不成立。步进强调的是「跟得上、供得久」，因此常规做法是稀释对比剂并延长注射时间，与心脏、脑血管的短团注策略相反。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0113", "t": "单选题", "s": "DSA的岁差运动（进动运动）摄影是指", "o": {"A": "C臂在单一平面内做左右摆动的往复运动采集", "B": "C臂保持焦点—影像接收器连线与检查部位中心的夹角恒定，绕该中心轴作圆锥面轨迹运动采集，形成类似陀螺岁差的运动", "C": "检查床沿长轴匀速平移，C臂固定不动", "D": "球管在阳极靶面上做焦点位置的高速跳变", "E": "C臂围绕患者作360度整圈快速旋转采集"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-013", "kp": "岁差运动摄影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】B正确。岁差运动摄影（precession motion angiography）中，C臂保持与靶区中心固定的锥角，围绕该中心作圆锥形轨迹回旋，采集轨迹在空间上如同陀螺的岁差运动。其价值在于以连续变化的投照方向观察重叠血管（如颅内动脉瘤瘤颈与载瘤动脉、分叉部血管），有助于快速寻找无重叠的工作角度。【为什么错】A错误：单平面摆动属摇篮式或摆动采集，轨迹为平面弧线而非圆锥面。C错误：床面平移属步进采集。D错误：焦点在靶面跳变是CT球管的飞焦点技术，与C臂运动无关。E错误：整圈快速旋转属旋转DSA或CBCT的采集方式，其轨迹为圆而非圆锥。", "tr": "岁差运动的关键词是「锥角恒定、圆锥面轨迹」，与旋转DSA的「单一平面圆弧」不同。二者常在同一道题中互为干扰项。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0114", "t": "多选题", "s": "关于DSA双能量减影技术，下列说法正确的是", "o": {"A": "其原理是利用碘的K吸收边（约33.2keV）两侧高、低两种能量下衰减差异悬殊，而骨与软组织差异相对较小，据此分离出碘信号", "B": "双能量减影在时间上两帧间隔极短，因而对运动伪影的敏感性低于常规时间减影", "C": "对于吞咽、心搏、肠蠕动等难以制动的部位，双能量减影较常规时间减影更具优势", "D": "双能量减影的信噪比优于时间减影，已取代时间减影成为DSA的默认减影方式", "E": "双能量减影需要在极短时间内切换管电压或使用能量分辨探测器，对设备的高压发生器响应速度要求高"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-014", "kp": "DSA双能量减影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】A正确：碘在其K吸收边上方衰减陡增，选取跨越33.2keV的高低两种能谱可最大化碘与背景组织的差异，实现能量减影。B正确：高低能两帧的时间间隔可短至毫秒级，运动错位远小于时间减影的蒙片—造影像间隔。C正确：正因时间间隔极短，双能量减影在吞咽、心搏、肠蠕动等区域优势明显。E正确：实现方式依赖高压发生器的快速kV切换或能量分辨（光子计数、双层）探测器，对硬件响应速度要求高。【为什么错】D错误：双能量减影的信噪比通常低于时间减影（两次曝光能谱差异有限、需较高剂量），且软组织减影不彻底，目前作为时间减影的补充而非替代，常规DSA仍以时间减影为主。", "tr": "能量减影的优势是「抗运动」，代价是「信噪比下降与剂量增加」。若题目出现「可完全替代时间减影」，基本可判为错误。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-0115", "t": "单选题", "s": "在主动脉腔内修复术（EVAR/TEVAR）中使用虚拟支架植入路径导航技术（如VesselNavigator类软件），其主要工作方式是", "o": {"A": "将术前采集的CTA血管三维数据与术中透视图像配准融合，把血管中心线、分支开口与虚拟支架位置实时叠加在透视上引导定位", "B": "在透视图像上直接测量血管直径后由系统自动释放支架", "C": "利用超声探头在体表实时追踪支架位置", "D": "通过磁导航系统操控支架输送系统自动前进", "E": "在不使用任何术前影像的前提下，仅凭透视图像自动识别肾动脉开口"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-015", "kp": "虚拟支架与三维影像导航", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】A正确。此类软件先导入术前CTA（或术中CBCT）容积数据，在其上标注血管中心线、肾动脉与髂内动脉等关键分支开口，并可放置虚拟支架标记；随后通过2D-3D配准（以骨性结构或术中两幅不同角度透视像为基准）将三维标注实时叠加于透视，术中转动C臂时标记随之更新，从而在极少或不用对比剂的情况下精确定位释放平面，对肾功能不全患者尤为有利。【为什么错】B错误：支架释放始终由术者手动完成，软件仅提供定位参考。C错误：体表超声无法在术中稳定追踪主动脉内支架，且不属于该技术范畴。D错误：磁导航主要用于电生理导管与部分微导丝，与虚拟支架导航是不同技术。E错误：该技术的前提正是术前或术中三维数据集，脱离三维数据无法生成血管中心线与分支标注。", "tr": "影像导航减少的是对比剂用量与造影次数，但不能纠正配准漂移。患者体位改变、导入硬鞘造成的血管形变都会引起偏差，关键释放前仍需一次确认造影。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U15-0116", "t": "多选题", "s": "关于介入治疗常用栓塞材料的分类与特点，下列说法正确的是", "o": {"A": "明胶海绵属于中效（可吸收）栓塞剂，栓塞后数周至数月可被吸收，血管可再通", "B": "聚乙烯醇（PVA）颗粒与微球属于永久性固体栓塞剂，可按粒径选择栓塞水平", "C": "弹簧圈属于永久性机械栓塞装置，主要用于中大动脉与动脉瘤囊内栓塞", "D": "无水乙醇属于液体栓塞剂，通过使蛋白变性、内皮破坏造成永久性闭塞，使用时需严格控制反流", "E": "碘化油仅作为对比剂使用，在肝动脉化疗栓塞中不具备栓塞与载药作用"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-016", "kp": "栓塞材料分类", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】A正确：明胶海绵是典型可吸收（中效）栓塞剂，适用于外伤出血、术前暂时性栓塞。B正确：PVA颗粒及可载药微球为永久性固体栓塞剂，粒径（如100~300μm、300~500μm）决定栓塞的血管级别。C正确：弹簧圈通过机械阻塞与继发血栓形成实现永久闭塞，广泛用于动脉瘤、动静脉瘘及出血血管。D正确：无水乙醇为强效永久液体栓塞剂，作用于毛细血管床水平，反流可致非靶器官坏死与剧痛，须控制注射速度与用量。【为什么错】E错误：碘化油在肝动脉化疗栓塞中兼具对比剂、末梢栓塞与化疗药物载体三重作用，可在肿瘤内长期滞留并在随访CT上显示沉积情况。", "tr": "按持续时间可分为短效（自体血凝块）、中效（明胶海绵）、长效/永久（PVA、微球、弹簧圈、无水乙醇、氰基丙烯酸酯类）。碘化油「既是对比剂又是栓塞剂」是常考点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-0117", "t": "多选题", "s": "关于血管内支架的类型与临床选择，下列说法正确的是", "o": {"A": "球囊扩张式支架定位精度高、径向支撑力强，多用于短段、开口部病变（如肾动脉、髂动脉开口）", "B": "自膨式支架顺应性好、能适应血管直径变化和外部压迫，多用于颈动脉、股腘动脉等易受形变部位", "C": "覆膜支架可隔绝血流与瘤腔或破口，用于动脉瘤、假性动脉瘤与血管破裂", "D": "血流导向装置（密网支架）通过重建载瘤动脉血流促使动脉瘤内血栓形成，用于部分颅内动脉瘤", "E": "药物洗脱支架释放抗增殖药物，因此植入后不再需要抗血小板治疗"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-017", "kp": "血管内支架类型与选择", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】A正确：球扩支架释放位置可控性好、径向力大，适合开口部与钙化短段病变。B正确：自膨支架具持续外向支撑与形变恢复能力，适用于颈动脉、股腘动脉等活动或受压部位。C正确：覆膜支架的作用即隔绝，用于动脉瘤、假性动脉瘤、动静脉瘘与血管破裂的急诊封堵。D正确：血流导向装置以高金属覆盖率改变瘤颈血流动力学，促使瘤腔内血栓形成并实现载瘤动脉重塑。【为什么错】E错误：药物洗脱支架抑制内膜增生以减少再狭窄，但内皮化延迟反而增加支架内血栓风险，术后必须按方案进行双联抗血小板治疗。", "tr": "「球扩＝精准，自膨＝顺应」是选择支架的基本原则；颈部与关节跨越部位禁用球扩支架，因其受外力压迫后不能自行恢复。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-0118", "t": "案例分析题", "s": "患者女性，71岁，高血压病史10年，家属诉其突发右侧肢体无力伴言语不能3小时，急诊NIHSS评分16分。急诊CT平扫排除颅内出血，头颈CTA示左侧大脑中动脉M1段闭塞，具备急诊机械取栓指征。介入手术室配备双平面平板DSA、C臂锥形束CT功能与可编程高压注射器，患者在局部麻醉与镇静下接受手术。作为参与该急诊手术的技师，下列技术配合与流程判断中，错误的是", "o": {"A": "急性缺血性卒中取栓强调「时间就是脑」，术前准备、铺巾、连接高压注射器等环节应提前并行完成以缩短入院至再通时间", "B": "术中可用双平面同时采集正侧位，减少造影次数与对比剂用量，缩短手术时间", "C": "取栓过程中若怀疑血管穿孔或造影剂外渗，可即刻行CBCT扫描鉴别对比剂渗出与急性出血", "D": "术后即刻CBCT上出现高密度影时可直接判定为脑出血，无需随访复查", "E": "全程应记录累积参考点空气比释动能与剂量面积乘积，并在保证影像可用的前提下采用低脉冲率透视"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-018", "kp": "急性缺血性卒中取栓的技术配合", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】D错误，为应选项。取栓术后即刻CBCT或CT上的高密度影既可能是对比剂外渗（碘染），也可能是真性出血，两者在术后即刻难以区分；对比剂通常在24小时内明显消退或减淡，而出血持续存在甚至扩大，故须在术后24小时左右复查CT加以鉴别，必要时用双能量CT做碘—出血分离。【为什么错】A正确：卒中取栓的核心指标即再通时间，流程并行化是缩短院内延误的关键。B正确：双平面可一次注射获取两个方向影像，减少对比剂与时间成本。C正确：术中CBCT是即时排查出血与穿孔的实用手段，可避免转运。E正确：介入剂量记录与低脉冲率透视是常规剂量管理要求，急诊亦不能忽视。", "tr": "取栓术后即刻高密度＝「碘染或出血」的鉴别是高频考点。判断依据是随访演变与双能量碘图，而非即刻单次平扫的CT值高低。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0119", "t": "多选题", "s": "关于CT/MR图像与DSA的配准融合技术，下列说法正确的是", "o": {"A": "融合前需要完成空间配准，常用方法包括基于骨性标志的刚性配准与基于互信息等相似性测度的自动配准", "B": "MR与DSA融合可在术中同时参考软组织与血管信息，对肿瘤供血动脉判定、动静脉畸形靶点定位有价值", "C": "配准精度受患者体位差异、呼吸运动、器械导致的组织形变影响，腹部与胸部的配准难度大于颅脑", "D": "融合影像可减少术中造影次数与对比剂用量，但关键步骤仍应以实时造影验证", "E": "只要完成一次配准，术中无论如何移动患者与检查床，融合结果都保持准确"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-019", "kp": "CT/MR与DSA的配准融合", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】A正确：刚性配准适用于颅脑等形变小的部位，基于互信息的自动配准适合跨模态（CT/MR与X线）灰度关系非线性的情形。B正确：MR的软组织对比使肿瘤边界、脑功能区、畸形团靶点在术中可视，是单纯DSA无法提供的信息。C正确：胸腹部受呼吸、心搏与体位差异影响，配准误差显著大于颅脑，常需呼吸门控或术中CBCT重配准。D正确：融合导航能显著减少对比剂用量，但因存在配准误差，释放支架、栓塞前的关键确认仍需实时造影。【为什么错】E错误：床面移动、患者体位变化、机架几何改变都会破坏已建立的空间对应关系，需要系统自动跟踪补偿或重新配准。", "tr": "融合导航的定位是「参考」而非「判读依据」。所有涉及配准的技术都必须强调误差来源与实时验证，凡出现「一次配准永久有效」的表述均属错误。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-0120", "t": "单选题", "s": "复合手术室（Hybrid OR）中影像引导手术导航系统的核心价值在于", "o": {"A": "取代术者的手术操作，实现全自动手术", "B": "把术前三维影像、术中实时影像与器械空间位置统一到同一坐标系中，为术者提供实时空间参考", "C": "取代术中造影与病理检查，据此即可作出最终诊断", "D": "提高DSA设备的空间分辨率", "E": "免除手术室的辐射防护要求"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-020", "kp": "影像引导手术导航", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】B正确。手术导航的本质是「坐标统一」：通过配准把术前CT/MR三维数据、术中CBCT或透视影像以及器械位置（光学、电磁或影像追踪）映射到同一空间，术者据此判断器械与靶点、危险结构的相对关系，实现微创精准操作。【为什么错】A错误：导航系统提供的是信息支持，手术决策与操作仍由术者完成。C错误：导航不改变组织学诊断的必要性，也不能免除关键步骤的实时造影确认。D错误：空间分辨率取决于探测器与几何条件，导航软件不改变成像链的物理性能。E错误：复合手术室内仍使用X线，屏蔽、铅衣、剂量监测等防护要求不能减免，反而因手术时间长而更严格。", "tr": "凡是把导航、融合、人工智能描述为「取代人」「免除防护」「提高硬件分辨率」的选项，均可直接排除。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-0121", "t": "案例分析题", "s": "患者男性，54岁，乙型肝炎肝硬化背景下发现肝右叶占位，增强CT提示肝细胞癌，肝功能Child-Pugh A级，拟行肝动脉化疗栓塞（TACE）。术中常规肝动脉造影后肿瘤染色显示不清，供血动脉走行迂曲并与邻近胃十二指肠动脉分支相互重叠，难以确定超选目标。所用设备具备锥形束CT、双容积融合与肿瘤供血血管自动追踪软件，后者可从锥形束CT动脉期数据自动分析并标注供血分支路径并叠加于透视。作为配合本例手术的技师，下列判断中错误的是", "o": {"A": "可在导管置于肝固有动脉后行CBCT动脉期采集，利用其容积数据分析肿瘤染色范围与供血分支", "B": "双容积融合可把CBCT的软组织肿瘤信息与三维血管数据叠加，帮助辨认迂曲供血动脉的起源", "C": "供血血管自动追踪软件给出的路径可直接叠加于透视，指导微导管超选，但仍需造影确认后再栓塞", "D": "CBCT采集时应嘱患者屏气，注射方案宜采用低流率、适当延迟以保证采集时相内肝实质与肿瘤持续染色", "E": "既然CBCT已显示肿瘤染色，即可省略栓塞后的复查造影，直接结束手术"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-021", "kp": "CBCT融合导航在TACE中的应用", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】E错误，为应选项。栓塞后必须复查造影以评估栓塞终点、确认肿瘤染色消失、检出遗漏的侧支供血（如膈下动脉、肠系膜上动脉来源的寄生供血）并排除非靶栓塞与血管损伤，术前的CBCT无法替代栓塞后的即时疗效评价。【为什么错】A正确：肝固有动脉或肝总动脉水平的CBCT动脉期采集是评估肿瘤染色与供血分支的标准做法。B正确：双容积融合把软组织容积与血管容积叠加显示，是识别迂曲分支起源的有效手段。C正确：自动追踪软件的路径叠加用于引导超选，但栓塞前必须以微导管造影确认靶血管与有无非靶分支。D正确：CBCT采集时间长达数秒至二十余秒，需屏气制动；采用稀释低流率注射并设置合适延迟，可保证整个旋转期间染色稳定。", "tr": "任何导航或融合技术都不能替代「栓塞前超选造影确认」与「栓塞后复查造影评价」这两个安全节点。寄生供血漏栓是TACE后早期复发的重要原因。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U15-1001", "t": "单选题", "s": "现代DSA设备成像链最核心的进展是", "o": {"A": "平板探测器（FPD）替代影像增强器-摄像管系统", "B": "普通胶片记录", "C": "荧光屏直接观察", "D": "CCD替代球管", "E": "超声探头记录"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-101", "kp": "DSA探测器进展", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】平板探测器（FPD）直接数字转换、动态范围大、无几何畸变，已取代影像增强器-摄像管/CCD系统成为DSA成像核心，故A正确。\n【为什么错】B：DSA为数字减影，不用胶片。C：荧光屏直接观察无减影能力。D：球管是X线源，不能用CCD替代。E：超声与DSA无关。", "tr": "“平板探测器化”是DSA硬件的标志性进展，替代的是影像增强器而非球管。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1002", "t": "单选题", "s": "平板探测器DSA相对于传统影像增强器DSA的主要优势是", "o": {"A": "空间分辨率高、无几何畸变、动态范围大", "B": "只能单幅成像", "C": "必须使用胶片", "D": "成像速度慢", "E": "需要暗室操作"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-102", "kp": "平板探测器DSA优势", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】平板探测器像素结构规整、探测效率高，图像空间分辨率高，无影像增强器的枕形畸变，动态范围宽，故A正确。\n【为什么错】B：FPD支持连续动态成像。C：DSA无需胶片。D：FPD成像速度快、支持高帧率。E：DSA在控制室操作，无需暗室。", "tr": "平板探测器“高清、无畸变、宽动态范围”三大优势常联合考查。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1003", "t": "单选题", "s": "DSA设备中，用于承载球管与探测器并实施任意角度投照的机械装置是", "o": {"A": "C形臂机架", "B": "高压注射器", "C": "检查床", "D": "激光相机", "E": "铅衣架"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-103", "kp": "DSA机架结构", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】C形臂机架通过机械臂旋转实现球管与探测器绕患者多角度投照，是DSA设备的核心机架结构，故A正确。\n【为什么错】B：高压注射器用于注射对比剂。C：检查床承托患者。D：激光相机用于打印。E：铅衣架为防护用品支架，均与投照机架无关。", "tr": "C形臂决定投照角度能力，双C臂系统可实现双平面同步成像。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1004", "t": "单选题", "s": "DSA路径图（Roadmap）技术的主要用途是", "o": {"A": "在实时透视中叠加血管路径图像，引导导管、导丝插管", "B": "测量血管直径", "C": "生成三维骨骼图像", "D": "打印血管照片", "E": "存储术前CT"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-104", "kp": "路径图技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】路径图技术先获取减影血管路径并作为模板，再叠加到实时透视图像上，使导管、导丝沿血管路径推进，提高插管效率与安全性，故A正确。\n【为什么错】B：血管测量属后处理分析。C：三维骨骼图像属3D重建范畴。D：照片打印与路径图无关。E：术前CT存储属数据管理。", "tr": "路径图是“减影血管模板+实时透视”的导航技术，是DSA介入的经典功能。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1005", "t": "单选题", "s": "旋转DSA采集的主要临床价值是", "o": {"A": "获取三维血管图像（3D-DSA）", "B": "提高透视亮度", "C": "缩短患者检查前准备", "D": "替代超声检查", "E": "测量骨密度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-105", "kp": "旋转DSA", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】C形臂围绕兴趣血管旋转采集多个角度投影，经三维重建获得3D-DSA血管图像，利于动脉瘤、血管畸形等多角度评价，故A正确。\n【为什么错】B：透视亮度与旋转采集无关。C：术前准备与成像方式无关。D：DSA不替代超声。E：骨密度用DXA测量。", "tr": "旋转采集→3D-DSA，是DSA从二维走向三维的标志技术。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1006", "t": "单选题", "s": "下肢动脉全程造影最常采用的特殊成像方式是", "o": {"A": "步进DSA（分段连续采集）", "B": "静态单幅摄影", "C": "头颅旋转采集", "D": "胸部双能成像", "E": "乳腺DBT"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-106", "kp": "步进DSA", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】步进DSA通过床面或C臂分段步进配合造影剂跟踪，一次注射对比剂完成腹主动脉至足部动脉全程成像，是下肢血管检查的标准方式，故A正确。\n【为什么错】B：静态单幅只能显示局部。C：头颅旋转采集用于颅内血管三维。D：双能成像用于组织分离。E：DBT用于乳腺，均不符合下肢全程造影需求。", "tr": "下肢全程看“步进DSA”，与“跟踪注射、分段步进”配合。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1007", "t": "单选题", "s": "超选择性DSA的含义是", "o": {"A": "将导管超选至目标分支血管后造影", "B": "选择最大剂量造影", "C": "选择最短曝光时间", "D": "选择最粗导管", "E": "选择平片检查"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-107", "kp": "超选择性造影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】超选择性DSA将导管头端超选进入靶器官或病灶的供血分支动脉内进行造影，减少重叠、提高小血管显示，故A正确。\n【为什么错】B：最大剂量是注射参数而非超选概念。C：最短曝光时间是采集参数。D：最粗导管与超选目的相反，超选需细导管。E：平片检查无造影与超选过程。", "tr": "“超选”指导管位置深达分支血管，而非参数选择。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1008", "t": "单选题", "s": "DSA图像后处理中“像素移位（Pixel Shift）”技术的作用是", "o": {"A": "校正患者运动引起的减影错位伪影", "B": "提高图像分辨率", "C": "增加对比剂流速", "D": "压缩图像数据", "E": "加密图像信息"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-108", "kp": "像素移位技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】减影时患者轻微运动使蒙片与造影图像错位产生伪影，像素移位通过平移、旋转蒙片像素重新对齐，减轻运动伪影，故A正确。\n【为什么错】B：分辨率由探测器决定。C：流速由高压注射器控制。D：压缩是存储环节。E：加密是安全措施，均与像素移位无关。", "tr": "像素移位是DSA运动伪影的经典校正手段，而非分辨率或剂量技术。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1009", "t": "单选题", "s": "3D-DSA重建生成的图像类型是", "o": {"A": "三维血管图像及类CT软组织图像", "B": "二维黑白平片", "C": "超声图像", "D": "核医学图像", "E": "视网膜图像"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-109", "kp": "3D-DSA图像", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】旋转采集数据经三维重建可生成三维血管图像，并可重建类CT（似CT）软组织/骨骼图像供术者参考，故A正确。\n【为什么错】B：DSA本身为数字减影图像而非黑白平片。C：超声图像属超声设备。D：核医学图像属核医学设备。E：视网膜图像与DSA三维重建无关。", "tr": "3D-DSA不仅重建血管，还能生成类CT图像，辅助介入规划。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1010", "t": "单选题", "s": "DSA高压注射器与X线设备联动的主要目的是", "o": {"A": "按造影方案自动触发曝光，使对比剂峰值与采集同步", "B": "自动打印报告", "C": "调节手术床高度", "D": "自动消毒导管", "E": "控制病床温度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-110", "kp": "高压注射器联动", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】高压注射器与造影系统联动，按设定的注入延迟自动同步启动曝光，确保采集时机与对比剂到达靶血管的峰值一致，故A正确。\n【为什么错】B：报告由RIS/医师完成。C：床高由技师手动调节。D：导管消毒在术前完成。E：床温与造影无关。", "tr": "联动的本质是“注射与曝光的时间同步”，保证减影图像质量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1011", "t": "单选题", "s": "DSA图像与CT、MR图像融合（配准）的主要应用是", "o": {"A": "将三维解剖影像与实时DSA叠加，辅助介入导航", "B": "替代病理检查", "C": "测量血压", "D": "生成心电图", "E": "打印三维胶片"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-111", "kp": "DSA图像融合应用", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】将术前CTA/MRA或3D重建图像与实时DSA配准融合后叠加显示，术者可同时获得血管与骨性解剖信息，提高介入操作精准度，故A正确。\n【为什么错】B：融合影像不提供病理诊断。C：血压监测属生命体征监护。D：心电图监测属心电监护。E：三维胶片打印非融合应用。", "tr": "图像融合的核心是“多模态影像配准+实时导航”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1012", "t": "单选题", "s": "神经介入治疗颅内动脉瘤最常用的技术是", "o": {"A": "弹簧圈栓塞或支架辅助栓塞", "B": "经皮球囊成形", "C": "椎体成形术", "D": "经皮肝穿引流", "E": "心内膜消融"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-112", "kp": "神经介入栓塞技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】颅内动脉瘤介入治疗以微导管超选入瘤囊内填塞弹簧圈（必要时支架辅助）实现闭塞，故A正确。\n【为什么错】B：球囊成形用于动脉狭窄。C：椎体成形术用于椎体压缩骨折。D：经皮肝穿引流为腹部引流。E：心内膜消融用于心律失常，均非动脉瘤栓塞方法。", "tr": "动脉瘤→弹簧圈栓塞；血管狭窄→球囊/支架成形，适应证要分清。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1013", "t": "单选题", "s": "肝动脉化疗栓塞（TACE）主要用于治疗的疾病是", "o": {"A": "原发性或转移性肝癌", "B": "冠心病", "C": "脑出血", "D": "下肢静脉曲张", "E": "肺气肿"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-113", "kp": "TACE介入治疗", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】TACE将导管超选至肝脏肿瘤供血动脉，注入化疗药物与栓塞剂，使肿瘤缺血坏死，是中晚期肝癌的重要治疗手段，故A正确。\n【为什么错】B：冠心病治疗用PCI。C：脑出血多内科或手术处理。D：下肢静脉曲张多射频/硬化。E：肺气肿内科治疗，均与TACE无关。", "tr": "TACE=肝动脉+化疗+栓塞，适应证是肝癌（尤其富血供型）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1014", "t": "单选题", "s": "经皮腔内血管成形术（PTA）恢复血管通畅的基本机制是", "o": {"A": "球囊扩张使狭窄段血管机械性扩大", "B": "药物溶化斑块", "C": "激光烧灼血管", "D": "切除血管壁", "E": "移植自体血管"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-114", "kp": "血管成形术机制", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】PTA将球囊导管置于狭窄处加压扩张，通过机械力使斑块压缩、血管壁扩张而恢复管腔，故A正确。\n【为什么错】B：溶栓药物溶解血栓而非斑块成形。C：激光消融用于旋切等，非PTA机制。D：PTA不切除血管壁。E：移植血管属外科手术，均不符合。", "tr": "PTA是“球囊机械扩张”，溶栓是“药物溶解血栓”，机制不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1015", "t": "单选题", "s": "DSA图像中出现高浓度对比剂区域过白、周围结构无法分辨的现象，属于", "o": {"A": "饱和（过曝光）伪影", "B": "运动伪影", "C": "卷褶伪影", "D": "化学位移伪影", "E": "磁化率伪影"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-115", "kp": "DSA饱和伪影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】对比剂浓度过高使探测器信号饱和，该区域呈均匀过白、失去密度层次，即饱和伪影（过曝光伪影），故A正确。\n【为什么错】B：运动伪影表现为结构错位重影。C：卷褶伪影属MRI伪影。D：化学位移伪影属MRI伪影。E：磁化率伪影属MRI伪影，均与DSA饱和伪影无关。", "tr": "DSA的“过白区”是饱和伪影，属X线/探测器层面的问题，勿与MR伪影混淆。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1016", "t": "单选题", "s": "DSA减影成像中“蒙片（Mask）”指的是", "o": {"A": "对比剂到达前采集的同一体位基准图像", "B": "对比剂充盈后的图像", "C": "三维重建图像", "D": "打印胶片", "E": "患者登记信息"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-116", "kp": "DSA蒙片概念", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】蒙片是造影剂到达前、同一投照条件下采集的基准图像，用它减去对比剂充盈图像即可去除骨与软组织背景，故A正确。\n【为什么错】B：充盈图像是减影的另一帧。C：三维重建由旋转数据生成。D：打印胶片是输出。E：登记信息是管理数据，均非蒙片定义。", "tr": "DSA本质是“充盈像-蒙片”，蒙片的质量直接影响减影效果。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1017", "t": "单选题", "s": "冠状动脉造影通常采用的采集帧率约为", "o": {"A": "25~30帧/秒", "B": "1帧/秒", "C": "2帧/分", "D": "0.5帧/秒", "E": "1帧/小时"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-117", "kp": "冠脉造影帧率", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】冠状动脉随心跳快速运动，需以25~30帧/秒的高帧率连续采集，才能清晰捕捉各时相血管影像，故A正确。\n【为什么错】B：1帧/秒跟不上冠脉运动。C：2帧/分时间分辨力严重不足。D：0.5帧/秒过低。E：1帧/小时无法捕捉动态图像，均会产生运动模糊与时相丢失。", "tr": "冠脉DSA高帧率（25~30fps）是区别于外周血管低帧率的关键参数。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1018", "t": "单选题", "s": "造影剂跟踪（bolus chase）技术在DSA中的含义是", "o": {"A": "跟踪对比剂前沿自动控制采集与床面/机架移动", "B": "跟踪患者心率", "C": "跟踪导管深度", "D": "跟踪手术时间", "E": "跟踪室内温度"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-118", "kp": "造影剂跟踪技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】造影剂跟踪系统实时检测对比剂前沿位置，自动触发下一段曝光并步进床面，保证全程血管在对比剂充盈时被采集，故A正确。\n【为什么错】B：心率监测属生理监护。C：导管深度由术者操作掌握。D：手术时间与跟踪技术无关。E：室内温度与造影无关。", "tr": "bolus chase=“跟对比剂、自动步进”，是步进DSA的自动控制核心。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U15-1019", "t": "多选题", "s": "DSA设备的硬件组成包括", "o": {"A": "X线球管", "B": "平板探测器", "C": "C形臂机架", "D": "高压注射器", "E": "MR超导磁体"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-119", "kp": "DSA硬件组成", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】DSA硬件包括X线球管、平板探测器、C形臂机架、高压注射器、导管床及图像系统等，故A、B、C、D正确。\n【为什么错】E：MR超导磁体属于磁共振设备，不属于DSA硬件。", "tr": "DSA是X线设备，MR磁体是磁共振设备部件，二者设备体系不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1020", "t": "多选题", "s": "DSA系统的软件功能包括", "o": {"A": "实时减影", "B": "路径图显示", "C": "像素移位校正", "D": "三维血管重建", "E": "自动出具病理报告"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-120", "kp": "DSA软件功能", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】DSA软件实现实时减影、路径图、像素移位、三维重建及图像分析等功能，故A、B、C、D正确。\n【为什么错】E：病理报告由病理科出具，DSA软件无此功能。", "tr": "DSA软件围绕“减影与血管成像”，诊断结论与病理诊断不在其职责内。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1021", "t": "多选题", "s": "DSA特殊成像技术包括", "o": {"A": "旋转DSA", "B": "步进DSA", "C": "超选择性DSA", "D": "双平面同步采集", "E": "MR波谱成像"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-121", "kp": "DSA特殊成像技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】旋转、步进、超选及双平面同步采集均为DSA特殊成像技术，故A、B、C、D正确。\n【为什么错】E：MR波谱成像（MRS）属于磁共振技术，不属于DSA。", "tr": "“特殊成像技术”限于X线DSA范畴，MR技术不应混入。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1022", "t": "多选题", "s": "DSA介入治疗技术包括", "o": {"A": "血管栓塞术", "B": "球囊扩张成形术", "C": "支架植入术", "D": "动脉内溶栓术", "E": "体外冲击波碎石"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-122", "kp": "DSA介入治疗技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】栓塞、球囊成形、支架植入、动脉内溶栓均属DSA引导下的血管介入治疗技术，故A、B、C、D正确。\n【为什么错】E：体外冲击波碎石属泌尿系非血管治疗，与DSA介入无关。", "tr": "DSA介入以血管系统为核心，体外碎石不是血管介入。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1023", "t": "多选题", "s": "DSA图像融合技术的应用包括", "o": {"A": "术前CTA与术中DSA配准融合辅助神经介入", "B": "3D血管与骨性解剖融合指导椎体成形", "C": "肝肿瘤供血动脉定位融合导航", "D": "DSA与MR血管成像融合辅助AVM治疗", "E": "融合图像替代术后病理"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-123", "kp": "DSA图像融合应用", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】融合技术将DSA血管信息与CT/MR三维解剖信息配准，用于神经介入、椎体成形、肝介入及AVM治疗导航等，故A、B、C、D正确。\n【为什么错】E：融合影像是导航工具，不能替代病理诊断。", "tr": "图像融合“导航不诊断”，其价值在手术精准定位。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1024", "t": "多选题", "s": "影响DSA图像质量的操作技术因素包括", "o": {"A": "采集帧率", "B": "减影矩阵大小", "C": "对比剂浓度与流速", "D": "曝光参数选择", "E": "患者姓名"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-124", "kp": "DSA图像质量因素", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】帧率决定时间分辨力，矩阵决定空间分辨力，对比剂浓度流速与曝光参数决定血管显示质量，故A、B、C、D正确。\n【为什么错】E：患者姓名属于管理信息，不影响图像质量。", "tr": "DSA质量由“时间、空间、对比度、曝光”四类技术参数决定。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1025", "t": "多选题", "s": "DSA运动伪影的校正与预防方法包括", "o": {"A": "使用像素移位校正", "B": "嘱患者屏气减少呼吸运动", "C": "采用重新选取合适蒙片", "D": "加用患者固定装置", "E": "加大对比剂浓度"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-125", "kp": "DSA运动伪影处理", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】像素移位校正错位、屏气减少呼吸移动、重新选蒙片避开移动帧、固定装置限制体动，均可减少运动伪影，故A、B、C、D正确。\n【为什么错】E：加大对比剂浓度会增加饱和伪影风险，不能解决运动伪影。", "tr": "运动伪影用“移位校正+配合+固定+选片”，与对比剂浓度无关。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U15-1026", "t": "多选题", "s": "高压注射器注射参数设置包括", "o": {"A": "注射流速", "B": "注射总量", "C": "压力限制", "D": "注射延迟时间", "E": "胶片灰度"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-126", "kp": "高压注射器参数", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】流速、总量、压力限制与注射延迟是高压注射器四项核心参数，共同决定对比剂到达时机与充盈质量，故A、B、C、D正确。\n【为什么错】E：胶片灰度属打印参数，与注射器无关。", "tr": "注射参数决定“何时打、打多少、多快打”，与成像显示参数无关。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1027", "t": "多选题", "s": "平板探测器DSA相对于传统影像增强器的优势包括", "o": {"A": "无几何畸变", "B": "动态范围大、层次丰富", "C": "量子探测效率（DQE）高、剂量低", "D": "空间分辨率高", "E": "必须配备专用胶片"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-127", "kp": "平板探测器优势", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】平板探测器无枕形畸变、动态范围大、DQE高有利于低剂量成像、像素规整空间分辨率高，故A、B、C、D正确。\n【为什么错】E：DSA为全数字采集，不需胶片记录。", "tr": "“无畸变、宽动态、高DQE、高分辨”是平板探测器四大优势。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1028", "t": "多选题", "s": "DSA介入手术中工作人员防护措施包括", "o": {"A": "穿戴铅衣、铅帽、铅围脖", "B": "使用铅屏风与防护吊帘", "C": "佩戴个人剂量监测元件", "D": "合理选择投照角度减少散射线", "E": "不使用任何防护设备"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-128", "kp": "DSA介入防护", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】铅衣等个人防护、铅屏风等设施防护、剂量监测与投照角度优化是介入防护的完整体系，故A、B、C、D正确。\n【为什么错】E：不使用防护设备将导致工作人员超剂量照射，严重违反防护原则。", "tr": "介入防护=个人防护+设施防护+剂量监测+操作优化，缺一不可。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U15-1029a", "t": "共用题干题", "s": "TACE术前，为明确肿瘤供血动脉及有无肝动脉变异，术中首先应完成的DSA检查是", "o": {"A": "腹腔干-肝总动脉造影及选择性肝动脉造影", "B": "冠状动脉造影", "C": "脑血管造影", "D": "下肢动脉造影", "E": "肺动脉造影"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-129", "kp": "TACE术前造影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】肝癌TACE需先行腹腔干-肝总动脉造影全面了解肝动脉解剖、肿瘤血供及变异，再超选至肝固有动脉或肿瘤供血支，故A正确。\n【为什么错】B：冠状动脉造影用于心脏。C：脑血管造影用于颅内。D：下肢动脉造影用于下肢。E：肺动脉造影用于肺循环，均非肝癌介入的造影路径。", "tr": "肝癌介入路径是“腹腔干→肝总动脉→肝固有动脉→肿瘤供血支”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1501", "gs": "患者男性，58岁，乙肝肝硬化病史，CT发现肝右叶富血供占位，临床诊断为原发性肝癌，拟行TACE介入治疗。术中在DSA引导下完成动脉造影、导管超选与栓塞。"}, {"id": "U15-1029b", "t": "共用题干题", "s": "栓塞治疗完成后，判断肿瘤栓塞程度最直观的DSA观察指标是", "o": {"A": "肿瘤区血管内碘油/栓塞剂沉积与对比剂不再充盈", "B": "肿瘤大小立即缩小", "C": "患者体温升高", "D": "造影机散热情况", "E": "注射器剩余对比剂量"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-130", "kp": "栓塞程度评价", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】栓塞后造影可见肿瘤供血动脉截断、瘤区内碘油等栓塞剂沉积、对比剂不再进入瘤体，是判断栓塞彻底的最直接依据，故A正确。\n【为什么错】B：肿瘤大小不会即刻缩小。C：发热为术后反应，非术中评价指标。D：造影机散热情况与栓塞程度无关。E：注射器剩余对比剂量与栓塞程度无关。", "tr": "“栓塞终点”看血管影像：供血动脉不显影、瘤体无对比剂充填。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1501", "gs": ""}, {"id": "U15-1030a", "t": "共用题干题", "s": "为一次对比剂注射完成双下肢全程动脉成像，最适宜的DSA技术是", "o": {"A": "步进DSA（bolus chase）", "B": "静态单幅摄影", "C": "头颅旋转采集", "D": "乳腺DBT", "E": "胸片拼接"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-131", "kp": "下肢全程DSA技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】步进DSA配合造影剂跟踪，可一次注射对比剂分段连续采集腹主动脉至足部动脉，满足全程显示需求，故A正确。\n【为什么错】B：静态单幅仅显示局部。C：头颅旋转采集用于颅内。D：DBT用于乳腺。E：拼接用于平片长部位，均不符合下肢DSA全程动态成像。", "tr": "“下肢全程动脉”对应步进DSA，跟踪对比剂自动分段步进。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1502", "gs": "患者男性，70岁，双下肢间歇性跛行2年，加重伴左足静息痛1个月，临床拟诊下肢动脉硬化闭塞症，行下肢动脉DSA检查明确病变范围。检查范围需覆盖腹主动脉分叉至足部。"}, {"id": "U15-1030b", "t": "共用题干题", "s": "步进DSA中保证各段图像质量的关键操作是", "o": {"A": "床面/机架步进与对比剂前沿到达时机同步", "B": "任意速度步进", "C": "减少对比剂总量至最低", "D": "全程使用最大帧率", "E": "关闭减影功能"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-132", "kp": "步进DSA操作要点", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】步进时机必须与对比剂前沿一致，保证每一段血管在其充盈峰值时被采集，否则出现未充盈或已排空段，故A正确。\n【为什么错】B：速度不匹配导致血管显示不全。C：总量过低对比剂稀释显示差。D：全程最大帧率徒增剂量且非必需。E：关闭减影则背景干扰明显，均错误。", "tr": "bolus chase的成败在“步进与对比剂同步”，即“跟踪”二字的含义。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1502", "gs": ""}, {"id": "U15-1031a", "t": "共用题干题", "s": "术前评价动脉瘤颈与载瘤动脉关系的最佳DSA方法是", "o": {"A": "旋转DSA采集并进行3D血管重建", "B": "静态正位单幅摄影", "C": "下肢步进DSA", "D": "乳腺DBT", "E": "胸片双能成像"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-133", "kp": "3D-DSA动脉瘤评价", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】旋转DSA多角度采集后三维重建，可从任意角度观察动脉瘤颈、瘤体及与载瘤动脉的关系，指导栓塞方案，故A正确。\n【为什么错】B：单幅正位无法全面显示三维空间关系。C：步进DSA用于下肢全程血管。D：DBT用于乳腺。E：胸片双能成像用于组织分离，均与颅内动脉瘤评价无关。", "tr": "动脉瘤“颈-体-载瘤动脉”关系靠3D-DSA多角度观察。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1503", "gs": "患者女性，52岁，突发剧烈头痛伴呕吐，头颅CTA提示前交通动脉瘤，拟行血管内弹簧圈栓塞。术前计划利用3D-DSA全面评价动脉瘤形态，术中结合图像融合导航实施栓塞。"}, {"id": "U15-1031b", "t": "共用题干题", "s": "术中为将术前CTA血管解剖与实时DSA透视相结合指导微导管到位，应使用", "o": {"A": "DSA与CTA图像配准融合导航", "B": "单纯黑白透视", "C": "心电图监测", "D": "血压监测", "E": "尿量监测"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-134", "kp": "DSA图像融合导航", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】将术前CTA的三维血管图像与术中实时DSA配准融合，术者结合导航图像选择栓塞角度与微导管方向，提高精准度，故A正确。\n【为什么错】B：单纯黑白透视无三维解剖信息。C：心电图监测为生命体征监测。D：血压监测为生命体征监测。E：尿量监测为生命体征监测，均与影像导航无关。", "tr": "“术前三维+术中实时”的配准融合是DSA图像融合技术的核心价值。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1503", "gs": ""}, {"id": "U15-1032", "t": "案例分析题", "s": "患者女性，60岁，行腹部DSA检查时配合不佳，减影图像出现血管边缘重影、骨结构错位，病变血管显示不清。技师分析为呼吸运动引起蒙片与充盈像不匹配所致。需要采取有效措施重新获得清晰减影图像。减影原理为造影充盈图像减去蒙片，蒙片与充盈图像几何不一致即产生错位伪影。可先尝试屏气重新采集，再考虑对已有数据进行软件校正。下列处理措施中首选的是", "o": {"A": "嘱患者屏气后重新采集或使用像素移位校正", "B": "加大对比剂流速", "C": "提高帧率到100帧/秒", "D": "直接放弃检查", "E": "加用造影剂总量"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-135", "kp": "DSA运动伪影处理", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】屏气配合可消除呼吸导致的减影错位，像素移位可对已采集数据校正，均是处理运动伪影的首选措施，故A正确。\n【为什么错】B：流速与运动伪影无关且可能加重饱和。C：100帧/秒非DSA常规且增剂量。D：放弃检查丧失诊断信息。E：增大总量不解决错位，均错误。", "tr": "运动伪影“先配合后校正”，屏气与像素移位是标准处理。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1033", "t": "案例分析题", "s": "患者男性，62岁，临床怀疑冠心病，行选择性冠状动脉造影。患者心率70次/分，造影中需要评估左主干及前降支中段狭窄程度并动态观察血流灌注情况，为介入治疗决策提供依据。技师选择DSA采集方案时，冠脉造影需兼顾时间分辨力与辐射剂量，帧率选择要能清晰显示血管充盈各时相。采集方案应在图像质量与患者受照剂量之间取得平衡。最合理的帧率设置是", "o": {"A": "25~30帧/秒高帧率连续采集", "B": "1帧/秒", "C": "0.5帧/分钟", "D": "单帧曝光", "E": "不采集只透视"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-136", "kp": "冠脉DSA帧率选择", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】冠状动脉随心动周期快速运动，评估狭窄需观察舒张期充盈等各时相，须用25~30帧/秒高帧率采集，故A正确。\n【为什么错】B：1帧/秒无法捕捉冠脉运动时相。C：0.5帧/分钟时间分辨力严重不足。D：单帧曝光不能动态评估血流。E：仅透视无法记录高质量减影图像。", "tr": "心脏DSA高帧率是基本原则，低帧率会导致冠脉图像模糊与时相缺失。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1034", "t": "案例分析题", "s": "某患者行腹主动脉造影时，由于对比剂浓度过高、注射流速过大，图像中主动脉与分支汇合区域出现大片均匀过白、血管边缘与腔内结构均无法分辨，无法评价血管病变。技师判断为饱和伪影。饱和伪影是探测器信号溢出所致，可通过降低对比剂浓度、流速或调整曝光参数使信号回落至动态范围内。调整后再行造影确认血管显示恢复正常方能继续检查。下列改进措施中最恰当的是", "o": {"A": "适当降低对比剂浓度或流速，必要时调整曝光参数避免饱和", "B": "大幅增加注射总量", "C": "改用MRI检查", "D": "提高帧率", "E": "延长曝光时间"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-137", "kp": "DSA饱和伪影处理", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】饱和伪影源于探测器信号溢出，降低对比剂浓度/流速使信号回落至动态范围以内，并配合曝光优化，可恢复血管细节显示，故A正确。\n【为什么错】B：增加总量加重饱和。C：换MRI不解决DSA问题且检查目的不符。D：帧率不影响信号强度。E：延长曝光增加剂量与运动风险，均错误。", "tr": "饱和伪影的核心对策是“降浓度/降流速+优化曝光”，使信号不溢出。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U15-1035", "t": "案例分析题", "s": "介入手术室内进行一台复杂的肝癌TACE手术，预计透视与采集时间较长，术者受照剂量风险高。技师与护士共同核对手术人员的防护装备与剂量监测措施。以下做法中介入防护应遵循个人防护、设施防护、剂量监测与操作优化相结合的原则，剂量计须反映真实受照水平。个人剂量计应佩戴于铅衣内侧以准确反映实际器官受照。最符合放射防护要求的是", "o": {"A": "术者穿戴铅衣并佩戴个人剂量计，使用铅屏风，尽量缩短透视时间", "B": "术者不穿铅衣以追求操作灵活", "C": "使用最大放大倍率全程透视", "D": "将个人剂量计放在铅衣外", "E": "远离铅屏风进行操作"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-138", "kp": "介入放射防护实施", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】铅衣+剂量计+铅屏风+缩短照射时间是介入防护的核心组合，故A正确。\n【为什么错】B：不穿铅衣使个人受照明显增加。C：最大放大倍率会增加剂量。D：剂量计应戴在铅衣内反映真实器官剂量。E：远离铅屏风失去屏蔽保护，均错误。", "tr": "个人剂量计戴在铅衣内测真实受照，铅屏风要置于术者与患者之间。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U15-1036", "t": "案例分析题", "s": "某患者行颅内动脉瘤栓塞术，术前拟行3D-DSA全面评价动脉瘤形态。技师设置旋转DSA采集参数时需综合考虑图像质量、对比剂用量与采集时长，保证重建数据完整可用。关于旋转DSA采集参数，旋转DSA采集时C形臂按设定角度与速度旋转，帧数决定重建数据密度，对比剂注入需与旋转同步。设置不当可致重建血管缺失或质量下降，须按设备规范选择。正确的做法是", "o": {"A": "根据旋转角度设置合适的采集帧数与速度，配合适量对比剂一次完成", "B": "帧数越少越好", "C": "旋转角度越大越慢越好", "D": "不使用对比剂", "E": "采用静态采集"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-139", "kp": "旋转DSA参数设置", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】旋转角度、采集帧数与对比剂注入量需匹配设计，保证重建数据完整且对比剂充盈充分，一次采集完成，故A正确。\n【为什么错】B：帧数过少重建质量差。C：旋转速度过慢造成时间分辨不足且患者不适。D：无对比剂无法显示血管。E：静态采集无三维数据，均错误。", "tr": "3D重建要求“角度覆盖+帧数+对比剂”三者匹配。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U15-1037", "t": "案例分析题", "s": "某神经介入中心开展DSA与术前CTA图像融合导航技术，术中融合影像出现血管错位、与实时透视不吻合，影响微导管与弹簧圈定位。技师分析可能为配准精度不足或患者体位变化所致。下列措施中能融合配准以骨性或血管标志为基准，患者头位变化会使术前影像与术中透视错位。配准成功后应锁定患者头位并固定体位，减少术中漂移。最有效改善融合准确度的是", "o": {"A": "采用骨性标志或血管标志点重新配准，并固定患者头位", "B": "增大融合图像亮度", "C": "关闭导航系统", "D": "更换导管类型", "E": "提高对比剂浓度"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-140", "kp": "DSA图像融合质量控制", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】重新以骨性/血管标志配准可修正坐标误差，固定头位可避免体位漂移，是提高融合精度的根本措施，故A正确。\n【为什么错】B：亮度不影响几何配准。C：关闭导航放弃技术价值。D：导管类型与配准无关。E：浓度只影响血管显示，不解决空间错位。", "tr": "融合精度取决于“配准质量+体位稳定”，与显示参数无关。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U16-0101", "t": "单选题", "s": "现代CT球管采用的飞焦点（flying focal spot）技术，其主要作用是", "o": {"A": "通过电磁偏转使阳极靶面上的焦点在z轴和／或扇形方向高速跳变，使采样数变为原来的两倍，提高采样密度、抑制混叠伪影并改善空间分辨率", "B": "通过移动球管的物理位置扩大扫描范围", "C": "其设计目的是使阳极靶面受热点分散，从而提高球管的热容量", "D": "在扫描中动态改变管电压实现能量成像", "E": "使焦点尺寸随扫描进程连续增大以提高输出功率"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-001", "kp": "飞焦点技术", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】A正确。飞焦点通过在电子束路径上施加快速变化的电磁偏转场，使焦点在阳极靶面上于两个（或多个）位置间以微秒级切换。z轴飞焦点使每转的层采样数加倍，等效于探测器z向排数翻倍，可抑制阶梯状伪影并改善纵向分辨率；扇形（α方向）飞焦点则使投影角采样加倍，提高平面内分辨率并抑制混叠（moiré）伪影。【为什么错】B错误：扫描范围由床进给与准直决定，与焦点跳变无关。C错误：分散靶面热负荷只是飞焦点的伴随效应，其设计目的是提高采样密度；热容量取决于阳极质量、材料与散热结构，与焦点是否跳变无关。D错误：动态改变管电压是快速kV切换双能技术。E错误：焦点尺寸由灯丝与聚焦极控制，飞焦点改变的是位置而非尺寸；焦点变大只会降低分辨率。", "tr": "飞焦点的核心是「采样加倍」，不是「热容量提升」。z轴飞焦点常被描述为「双倍层采集」，容易与真正的探测器排数混淆——它不增加探测器排数，只增加采样点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0102", "t": "多选题", "s": "关于新型CT球管的技术进展，下列说法正确的是", "o": {"A": "液态金属滑动轴承以液态金属膜替代滚珠轴承，摩擦小、噪声低，且导热性好，有利于阳极热量向外传导", "B": "旋转阳极管的电子束偏转配合阳极直接油冷（如Straton、Vectron类设计）可显著提高散热率，缩短连续扫描间的冷却等待", "C": "散热率的提升使大范围、长时间、高毫安秒扫描（如全身CTA、灌注、心脏多期采集）成为可能", "D": "球管阳极靶面材料多采用高原子序数、高熔点的钨或钨铼合金", "E": "现代球管的进步已使阳极热容量与散热率不再构成任何扫描协议的限制因素"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-002", "kp": "CT球管的轴承与散热进展", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】A正确：液态金属（镓基合金）滑动轴承接触面积大、无点接触磨损，兼具润滑与导热双重功能。B正确：将阳极靶直接浸于循环冷却油中并配合电子束偏转控制受热区域，可大幅提高连续散热率。C正确：散热能力提高直接转化为临床能力——长范围血管成像、灌注多期扫描不再频繁等待冷却。D正确：钨（Z=74）及钨铼合金兼具高X线产额与高熔点、抗热龟裂性能。【为什么错】E错误：即便散热率提高，超长范围灌注、大体重患者高输出扫描仍可能触及球管热限，扫描协议设计仍须考虑热容量与散热率，「不再构成任何限制」过于绝对。", "tr": "热容量（可储存的总热量，单位MHU）与散热率（单位时间散出的热量，kHU/min）是两个不同参数。连续多期扫描更依赖散热率而非单纯的热容量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT设备的进展", "页": 387}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-0103", "t": "单选题", "s": "宽体探测器CT（z轴覆盖达16cm左右）在临床应用中的突出优势是", "o": {"A": "可对心脏、颅脑等器官实现单个机架旋转内的一次性轴扫覆盖，实现同期相成像并便于全器官灌注", "B": "彻底消除了锥形束伪影", "C": "空间分辨率随z轴覆盖宽度增加而同步提高", "D": "无需心电门控即可完成冠状动脉成像", "E": "扫描野内的散射线随覆盖范围增大而减少"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-003", "kp": "宽体探测器进展", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】A正确。约16cm的z轴覆盖可将整个心脏或全脑纳入一次轴向扫描，避免了分段采集的层间错层与时相不一致，使「一个心动周期内完成心脏成像」和「全脑CT灌注」成为可能，同时便于低剂量前瞻性门控。【为什么错】B错误：z轴覆盖越宽，边缘层面的锥角越大，锥形束伪影反而更突出，需依靠锥束重建算法（如Feldkamp类及其改进算法）校正，不可能「彻底消除」。C错误：空间分辨率取决于探测器单元尺寸、焦点与重建算法，与z轴覆盖宽度无必然关系。D错误：冠状动脉成像仍需心电门控或触发以获得稳定时相。E错误：照射体积增大，散射线随之增加，宽体系统对散射校正与抗散射栅的要求更高。", "tr": "宽体探测器解决的是「时间一致性与覆盖效率」，代价是「锥角伪影与散射增加」。把覆盖宽度等同于分辨率提升是典型错误。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0104", "t": "多选题", "s": "关于光子计数探测器CT（PCD-CT）与传统能量积分探测器（EID）的比较，下列说法正确的是", "o": {"A": "PCD直接把X线光子转换为电信号并逐个计数，可按能量阈值分箱，无需闪烁体—光电二极管两步转换", "B": "PCD取消了探测器单元间的反射隔板，几何剂量效率提高，且可做更小的探测器单元以提高空间分辨率", "C": "EID的输出与光子能量加权相关，低能光子贡献被低估；PCD对每个光子等权计数，可提高软组织与碘的对比噪声比", "D": "PCD可在一次扫描中获得多个能量区间的数据，天然具备多能量（谱）成像能力", "E": "PCD既能排除电子学噪声，也不受脉冲堆积与电荷共享的影响，计数率越高图像质量越好"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-004", "kp": "光子计数CT原理与优势", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】A正确：PCD采用碲化镉／碲锌镉等半导体直接转换材料，光子入射即产生电荷脉冲，经甄别器按阈值分箱计数。B正确：无需闪烁体间的反射隔板，减少了死区面积，单元可做到亚毫米以下，超高分辨率模式因此成为可能。C正确：EID按能量积分，低能光子权重低，而低能光子恰恰携带较高的碘对比信息；PCD等权计数并可设阈值排除电子学噪声，碘对比噪声比提高。D正确：能量分箱使单次扫描即产生多能量数据，无需双源、kV切换或双层结构。【为什么错】E错误：PCD可通过能量阈值排除低幅度电子学噪声，但在高通量下存在脉冲堆积与电荷共享，导致能量分辨与计数线性度下降，是该技术的主要工程难点，「计数率越高越好」不成立。", "tr": "PCD的抗噪优势是「阈值以下的电子学噪声被剔除」，不等于「无噪声」。量子噪声依然存在，且高计数率下的脉冲堆积是其固有瓶颈。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U16-0105", "t": "单选题", "s": "关于CT迭代重建（IR）技术的代际演进与图像特征，下列说法正确的是", "o": {"A": "混合型迭代重建（如ASIR、iDose、AIDR-3D类）主要在投影域与图像域做统计降噪，计算量较小；基于模型的迭代重建（如MBIR/IMR/Veo类）引入系统光学与统计模型，降噪与分辨率保持更好但重建耗时长", "B": "迭代重建与滤波反投影的噪声—剂量关系相同，其优势仅在于重建速度更快", "C": "迭代重建强度越高图像越接近真实解剖，不存在任何副作用", "D": "迭代重建只能用于低剂量扫描，常规剂量下不可使用", "E": "迭代重建通过增加管电流来降低噪声"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-005", "kp": "迭代重建的代际与特征", "ch": "十六、CT技术的进展 → 1.CT设备 → (3)软件系统", "ex": "【为什么对】A正确。第一代混合迭代在原始数据域与图像域交替做有限次统计降噪，重建速度接近临床可接受水平；基于模型的迭代重建则对X线光子统计、焦点与探测器几何、体素响应建模，进行多次正投影—反投影迭代，噪声—分辨率折衷显著优于滤波反投影，但计算量大、重建时间长。【为什么错】B错误：滤波反投影为解析算法，噪声与剂量的关系固定，迭代重建可在同等剂量下明显降噪。C错误：高强度迭代会产生「蜡样／塑料感」的图像纹理改变，并可能降低低对比物体的可探测性，强度需按部位与临床任务权衡。D错误：常规剂量下同样可使用迭代重建以提高图像质量或保留剂量余量。E错误：迭代重建是重建算法层面的处理，不改变采集时的管电流，其价值恰在于允许降低管电流。", "tr": "迭代重建的代价是图像纹理改变与低对比可探测性可能下降，因此不宜盲目使用最高强度；肝脏等低对比任务尤其要注意。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0106", "t": "多选题", "s": "关于CT深度学习图像重建（DLR）技术，下列客观描述正确的是", "o": {"A": "多以高剂量／全采样数据重建的图像为训练目标，学习从低剂量或欠采样数据到高质量图像的映射", "B": "与高强度迭代重建相比，DLR在大幅降噪的同时通常能更好地保留接近滤波反投影的图像纹理", "C": "推理阶段计算主要由专用硬件完成，重建速度通常快于基于模型的迭代重建", "D": "其性能依赖训练数据的分布，遇到训练集中少见的解剖变异、植入物或极端体型时可能出现表现下降", "E": "DLR可以恢复采集时缺失的信息，因此降低扫描剂量时不必再顾虑低对比可探测性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-006", "kp": "深度学习CT重建的原理与局限", "ch": "十六、CT技术的进展 → 1.CT设备 → (3)软件系统", "ex": "【为什么对】A正确：主流DLR采用监督学习范式，以高质量参考图像作为学习目标。B正确：DLR的一个重要卖点即在降噪的同时维持接近滤波反投影的噪声功率谱，减轻迭代重建的「蜡样」纹理。C正确：训练完成后推理为前向计算，配合专用加速硬件，速度通常优于多次迭代的模型迭代重建。D正确：泛化能力受训练数据分布约束，罕见解剖、金属植入物、超重或极瘦患者可能超出分布而导致细节丢失或伪结构，这是需要临床警惕的局限。【为什么错】E错误：算法只能利用先验统计规律做合理估计，不能创造采集中真正缺失的信息；过度降剂量时可能产生「看似干净却丢失或虚构细节」的图像，剂量下调必须以临床任务的可诊断性为界。", "tr": "DLR不是「无损降剂量」的许可证。评价其性能不能只看噪声标准差，还要评估低对比可探测性与小病灶的保真度。并非所有在用设备都配备DLR，选择重建方式应以本机实际配置为准。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-0107", "t": "多选题", "s": "关于双能量CT几种实现方式的原理与优缺点，下列说法正确的是", "o": {"A": "双源双能（两套球管—探测器成约90度安装，分别用低kV与高kV）能谱分离好、两管电流可独立调节，但两套数据存在时间差与交叉散射，且第二探测器视野较小", "B": "快速kV切换（单球管在相邻投影间高速切换80/140kV）时间与空间配准好、可全视野能量成像，但低kV时管电流调节受限、能谱分离依赖滤过与后处理", "C": "双层探测器（上层吸收低能光子、下层吸收高能光子）为探测器侧能量分离，时间与空间完全一致，可回顾性生成能谱数据，但两层能谱重叠较多、分离度受限", "D": "双螺旋（同一部位先后两次不同kV扫描）实现简单，但两次扫描间隔长，对运动器官与增强时相变化敏感，主要用于静态部位", "E": "光子计数探测器通过能量阈值分箱实现能谱分离，但必须配合两个球管才能完成双能采集"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-007", "kp": "双能量CT实现方式的对比", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】A正确：双源双能以物理独立的两套成像链获得最佳能谱分离（可对高kV加锡滤过），并能按体型分别设定管电流；代价是两套数据存在约四分之一转的时间差、存在交叉散射，且B探测器视野常小于A（约33~35cm）。B正确：kV切换在同一球管、同一探测器上完成，时间与空间配准好、全视野可用，但切换周期内低kV的管电流提升空间有限，剂量与噪声平衡较难。C正确：双层探测器为「探测器侧」分离，两套数据严格同源同时，可对常规扫描回顾性做能谱分析；但两层吸收的能谱重叠较多，物质分解能力弱于能谱分离更好的方案。D正确：双螺旋（两次扫描）实现门槛最低，但受运动与对比剂时相变化影响大，仅适合静态部位（如结石成分分析）。【为什么错】E错误：光子计数探测器单球管单次扫描即可完成多能量分箱采集，不需要两个球管，这正是其相对既往方案的优势之一。", "tr": "记忆抓手：双源＝能谱分离最好但视野与时间配准受限；kV切换＝配准好但剂量调节受限；双层＝配准最好、可回顾但分离度最弱；双螺旋＝只适合静态；光子计数＝单源单扫描即多能量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U16-0108", "t": "单选题", "s": "下列临床问题中，最不适合依靠能量CT（双能量）后处理解决的是", "o": {"A": "鉴别肾结石为尿酸盐结石还是含钙结石", "B": "在增强扫描基础上生成虚拟平扫以减少一次平扫曝光", "C": "评估肺栓塞患者的肺灌注碘分布", "D": "鉴别肾上腺腺瘤与转移瘤时替代化学位移MRI直接测定细胞内脂质含量", "E": "鉴别急性痛风患者关节周围沉积物是否为尿酸盐结晶"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-008", "kp": "能量CT的应用范围与边界", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】D最不适合。鉴别肾上腺腺瘤依靠的是细胞内脂质导致的低CT值（平扫≤10HU）或增强廓清率，双能量可通过虚拟平扫与脂／水物质对提供辅助信息，但对细胞内微量脂质的测定灵敏度有限，公认的直接检测手段是化学位移MRI的同反相位序列，双能量CT不能直接替代。【为什么错】A适合：尿酸盐结石与含钙结石的双能量比（如80kV与140kV下CT值之比）差异显著，是双能量最成熟的应用之一。B适合：VNC由碘图从增强数据中扣除碘信号生成，是减少平扫曝光的常规手段。C适合：肺动脉CTA同步生成肺碘分布图（肺灌注血容量图），可显示栓塞相应肺段的灌注缺损。E适合：双能量对单钠尿酸盐结晶的物质分解已有成熟的痛风成像方案，可显示关节周围绿色标记的尿酸盐沉积。", "tr": "「双能量万能」是常见误判。双能量擅长的是元素有效原子序数差异大的物质分解（碘、钙、尿酸、脂肪），对细胞内微量脂质、软组织成分细微差异的能力有限。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0109", "t": "案例分析题", "s": "患者女性，46岁，突发右侧腰部绞痛3天并向会阴部放射，伴镜下血尿，急诊超声提示右肾积水及输尿管上段结石可能。既往有肾结石反复发作史，本次化验血肌酐轻度升高，估算肾小球滤过率约55mL/(min·1.73m²)。临床希望明确结石的位置、大小与化学成分，以决定采用体外冲击波碎石还是口服药物碱化尿液溶石。所在科室拥有具备双能量功能的CT。作为技师，下列扫描与后处理方案中最合理的是", "o": {"A": "先行常规低剂量平扫定位结石，再对结石所在区域行双能量采集，用双能量比与物质分解分析成分", "B": "直接行常规单能量增强扫描，通过强化程度判断结石成分", "C": "只做高分辨率薄层平扫，根据CT值绝对数值即可确定结石成分", "D": "行全腹双能量增强扫描并生成碘图，据碘图判断结石成分", "E": "行CT尿路造影延迟期扫描，用对比剂包绕形态推断结石成分"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-009", "kp": "能量CT在泌尿系结石中的应用流程", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】A最合理。结石成分分析必须在平扫（无碘）条件下进行，先以低剂量平扫全泌尿系定位，再仅对结石节段行双能量采集，既满足成分分析需要，又把双能量的辐射负担限制在小范围，符合剂量最优化原则。双能量可可靠区分尿酸盐结石（低双能量比，适合药物碱化溶石）与含钙／胱氨酸结石（高双能量比，倾向碎石处理）。【为什么错】B错误：结石不强化，增强不但无助于成分判断，还因碘掩盖结石密度而干扰评估；该患者肌酐升高更应慎用对比剂。C错误：单能量CT值受结石大小、部分容积效应与管电压影响，重叠区间大，不能仅凭绝对CT值定成分。D错误：碘图用于评价含碘强化，与结石成分无关，且同样存在对比剂使用问题。E错误：延迟期高密度对比剂会完全掩盖结石，形态学也不能反映化学成分。", "tr": "结石成分分析的三个前提：平扫、双能量、结石足够大（一般直径大于3~5mm，过小者受部分容积效应影响判断不可靠）。有碘存在时一律不能做成分分析。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0110", "t": "单选题", "s": "在能量CT虚拟单能量图像（VMI）中选择40~50keV的低keV重建，其主要目的是", "o": {"A": "提高碘的CT值与血管—软组织对比，改善对比剂用量不足、心排量低或远端小血管显示不佳的病例", "B": "降低图像噪声", "C": "减少金属植入物周围的射线硬化伪影", "D": "去除图像中的骨性结构", "E": "把增强图像转换为虚拟平扫图像"}, "d": "易", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-010", "kp": "低keV虚拟单能量图像的应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (2)单能谱CT临床应用", "ex": "【为什么对】A正确。虚拟单能量的keV越接近碘的K吸收边（33.2keV），碘的质量衰减系数越大，碘的CT值随之显著升高（40keV时碘CT值可达常规120kV图像的2~3倍），从而提高血管强化程度与病灶的碘对比，适用于对比剂减量、肾功能受限、心排量低或远端细小血管显示不良的情形。【为什么错】B错误：低keV重建通常伴随噪声升高（尤其40keV以下），需依靠迭代或频域去噪算法补偿。C错误：减少金属与射线硬化伪影需要选择高keV（一般100~140keV以上）并结合金属伪影校正算法，与低keV方向相反。D错误：去骨依靠物质分解或分割算法，不是虚拟单能量的功能。E错误：虚拟平扫由碘图扣除生成，与单能量重建是不同的后处理产品。", "tr": "低keV「提对比但增噪声」，高keV「降伪影但失对比」，方向相反，是能量CT最基础也最常考的一组权衡。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0111", "t": "单选题", "s": "某髋关节金属假体术后患者行CT检查，图像上假体周围出现明显条状低密度与高密度相间伪影。关于采用高keV虚拟单能量图像的作用与限度，下列说法正确的是", "o": {"A": "高keV图像可减轻射线硬化引起的暗带与条纹，但对金属造成的光子饥饿与探测器信号缺失所致的伪影改善有限，需联合专用金属伪影校正算法", "B": "高keV图像对束硬化与光子饥饿两类伪影的抑制效果相当，可单独用于金属伪影处理", "C": "高keV图像在减轻伪影的同时能进一步提高软组织与碘对比", "D": "高keV图像的噪声高于低keV图像", "E": "金属伪影只能通过增大管电流解决，与keV选择无关"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-011", "kp": "高keV与金属伪影校正", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】A正确。金属伪影的成因至少包括射线硬化（束硬化）、光子饥饿（透过金属后计数极低）、散射与运动等。高keV虚拟单能量图像模拟高能量下衰减差异缩小的情形，主要针对射线硬化成分有效；而光子饥饿造成的投影数据缺失属信息丢失，须靠投影插值类金属伪影校正算法（MAR）补充，二者联合效果最佳。【为什么错】B错误：高keV主要抑制束硬化成分，对光子饥饿造成的投影数据缺失作用有限，两类伪影的抑制效果并不相当，单靠高keV难以解决严重金属伪影。C错误：keV升高使碘的衰减优势下降，软组织与碘对比降低，这正是高keV的代价。D错误：一般而言高keV图像噪声较低，低keV图像噪声更高，选项描述相反。E错误：增大管电流可缓解光子饥饿但不能消除束硬化，且盲目加大剂量不符合防护原则；keV选择与MAR算法才是主要手段。", "tr": "MAR算法本身也可能引入新的伪影（如金属附近结构变形、细节丢失），临床应同时保留未校正与已校正两套图像对照阅读。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0112", "t": "单选题", "s": "关于能量CT在头颈CTA中的自动去骨（骨与碘分离）技术，下列说法正确的是", "o": {"A": "利用骨（钙）与碘在两种能量下衰减特性的差异做物质分解，无需平扫蒙片即可在单次增强采集中去除骨结构", "B": "其原理是把增强图像与平扫图像相减，因此必须先做一次平扫", "C": "去骨效果与颅底部位无关，各部位精度一致", "D": "该技术要求患者在两次扫描间保持绝对静止，否则会出现错层", "E": "去骨后图像不能用于最大密度投影与容积再现显示"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-012", "kp": "能量CT自动去骨技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】A正确。钙与碘的有效原子序数不同，在高低两种能谱下的衰减比值存在稳定差异，据此可在同一次增强采集的双能量数据中把骨（钙）与血管（碘）分离，无需平扫蒙片，因而免除了配准误差与额外的平扫剂量。【为什么错】B错误：这是传统减影CTA（两次扫描相减）的原理，与能量去骨是不同技术路线。C错误：颅底骨质致密、血管紧贴骨壁（如颈内动脉岩骨段、海绵窦段），此处去骨最易误删血管或残留骨片，精度明显低于颈部。D错误：能量去骨为单次采集，不存在两次扫描间的运动错层问题，这恰是其优势；「必须绝对静止」是减影CTA的限制。E错误：去骨后的容积数据完全可以用于最大密度投影、容积再现与曲面重组显示。", "tr": "减影CTA靠「两次扫描相减」，能量CTA靠「一次扫描物质分解」。两者的失败模式不同：前者怕体动错层，后者怕颅底血管与骨紧贴造成误分割。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0113", "t": "多选题", "s": "关于CT金属伪影校正（MAR）算法及扫描侧的伪影控制措施，下列说法正确的是", "o": {"A": "投影插值类MAR先分割出金属所在的投影道，用邻近投影数据插值替代后再重建，可显著减轻条纹伪影", "B": "MAR校正后可能出现金属邻近区域结构变形或细节丢失，应保留原始重建图像一并阅读", "C": "适当提高管电压（如从120kV提高到140kV）有助于减轻束硬化伪影", "D": "调整机架倾角或患者体位使金属尽量避开重要观察结构所在的扫描平面，是简单有效的物理措施", "E": "增大重建层厚可以消除金属伪影的根源"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-013", "kp": "金属伪影校正算法与扫描对策", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】A正确：投影域插值是经典MAR的核心思路，后续多与迭代重建结合。B正确：MAR以「合理估计」替代真实缺失数据，可能造成金属旁软组织形态失真，故双份图像对照是临床规范。C正确：提高管电压使平均光子能量升高，束硬化效应减弱，同时改善穿透力、缓解光子饥饿。D正确：改变投照几何使金属与关注结构不在同一投影路径上，是无成本、无剂量代价的有效手段（如口腔金属修复体行头部扫描时调整倾角）。【为什么错】E错误：增大层厚只是通过平均降低噪声与视觉上的条纹显著度，并不改变投影数据缺失这一根源，反而牺牲纵向分辨率与小病灶显示。", "tr": "伪影控制应「先物理、后算法」：优化投照几何与管电压属源头治理，MAR与高keV属事后补救，二者互补而非替代。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-0114", "t": "单选题", "s": "双能量CT用于痛风的尿酸盐结晶成像，其物质分解的基础是", "o": {"A": "单钠尿酸盐由低原子序数元素组成，其在高低两种能量下的CT值变化幅度小于含钙组织，据此可与骨、钙化区分并作伪彩标记", "B": "尿酸盐结晶具有顺磁性，在高能量下信号增强", "C": "尿酸盐能特异性摄取碘对比剂", "D": "尿酸盐的密度高于皮质骨", "E": "尿酸盐只能在增强扫描中显示"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-014", "kp": "双能量痛风成像原理", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】A正确。单钠尿酸盐主要由碳、氮、氧、氢等低原子序数元素构成，有效原子序数低（约7~8），其衰减对光子能量变化不敏感，双能量比接近1；而钙化与骨的有效原子序数高（钙Z=20），双能量比明显大于1。软件据此把关节周围的尿酸盐沉积分离出来并以伪彩（常为绿色）叠加显示，用于痛风的无创诊断与疗效随访。【为什么错】B错误：顺磁性是磁共振概念，与X线衰减无关，属跨模态混淆。C错误：尿酸盐不摄取碘对比剂，痛风双能量成像为平扫检查。D错误：尿酸盐结石与结晶的密度远低于皮质骨。E错误：痛风双能量成像在平扫下完成，增强反而会引入碘干扰物质分解。", "tr": "「双能量比」是判读关键：尿酸盐约等于1（能量依赖性弱），钙约1.4以上（能量依赖性强）。此外甲床、皮肤褶皱、运动与射线硬化可产生伪阳性绿色标记，需结合部位与形态判读。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0115", "t": "多选题", "s": "关于双能量CT对泌尿系结石成分的定量分析，下列说法正确的是", "o": {"A": "尿酸盐结石的双能量比接近1，含钙结石（草酸钙、磷酸钙）的双能量比明显大于1，据此可实现二者分离", "B": "结石成分判定对治疗决策有直接影响：尿酸盐结石可通过碱化尿液药物溶石，含钙结石多需体外冲击波碎石或手术", "C": "结石体积过小（如直径小于3mm）时，部分容积效应与噪声会明显降低成分判定的可靠性", "D": "分析须在平扫条件下进行，含碘对比剂会干扰物质分解结果", "E": "双能量CT对草酸钙一水与二水、磷酸钙、胱氨酸等结石亚型的细分，与实验室成分分析具有同等可靠性"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-015", "kp": "结石成分的双能量定量分析", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】A正确：尿酸盐有效原子序数低、能量依赖性弱，与含钙结石在双能量比上差异显著，是双能量最可靠的临床应用之一。B正确：这正是成分分析的临床价值所在，直接决定溶石与碎石路径的选择。C正确：微小结石受部分容积效应与量子噪声影响，物质分解的置信度下降，报告时应说明。D正确：碘的存在会破坏两物质／三物质分解假设，必须在平扫数据上分析。【为什么错】E错误：双能量对「尿酸盐与非尿酸盐」的二分最可靠，对含钙结石内部亚型（草酸钙一水与二水、磷酸钙）以及胱氨酸结石的细分能力有限，与体外红外光谱等实验室分析不能等同。", "tr": "双能量结石分析的可靠边界是「尿酸盐与非尿酸盐」。把它当作可替代实验室成分分析的精细分型工具，是超出技术能力的过度解读。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U16-0116", "t": "单选题", "s": "关于双能量CT虚拟平扫（VNC）图像的生成原理与临床价值，下列说法正确的是", "o": {"A": "通过物质分解从增强数据中扣除碘成分，得到近似平扫的图像，可在部分方案中省略真实平扫从而降低总辐射剂量", "B": "VNC是把增强图像的窗宽窗位调整为平扫显示的结果", "C": "VNC图像与真实平扫图像的CT值一致，可直接用于肾上腺腺瘤10HU阈值的判读", "D": "VNC只能在平扫数据上生成", "E": "VNC图像的噪声低于真实平扫图像，且对细小钙化的显示更清晰"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-016", "kp": "虚拟平扫的原理与价值", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】A正确。VNC基于三物质分解，把增强图像中的碘信号识别并扣除，重建出接近平扫的图像。在多期扫描方案中用VNC替代真实平扫，可减少一个扫描期相，降低总剂量约三分之一，对肾上腺、肾脏、肝脏多期检查意义明显。【为什么错】B错误：窗技术只改变灰度显示，不改变体素CT值，无法去除碘的实际贡献。C错误：VNC与真实平扫CT值存在系统偏差（一般在10HU左右，部位与算法不同而异），对依赖CT值阈值的判读（如肾上腺腺瘤10HU界值、结石、钙化检出）须谨慎，不能无条件替代。D错误：VNC必须从含碘的增强数据生成，平扫数据无碘可扣。E错误：VNC经物质分解运算后噪声特性改变，通常并不优于真实平扫，且可能丢失细小钙化。", "tr": "VNC最重要的两个局限：一是CT值偏差影响阈值判读，二是可能把细小钙化与钙化斑块一并「扣掉」而漏检。涉及钙化评分、结石检出时仍应做真实平扫。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0117", "t": "案例分析题", "s": "患者男性，58岁，吸烟30年，因体检超声发现右侧肾上腺占位就诊，占位最大径2.4cm，边界清楚，实验室内分泌功能检查未见异常，临床需鉴别无功能腺瘤与转移瘤。临床申请肾上腺CT平扫加增强及延迟扫描。技师考虑到该患者近期已多次接受CT检查，拟采用双能量增强扫描并以虚拟平扫替代真实平扫，从而减少一次曝光。关于这一方案的评估，下列判断中错误的是", "o": {"A": "肾上腺腺瘤的经典判读依据之一是真实平扫CT值≤10HU，该阈值建立在常规平扫数据基础上", "B": "虚拟平扫与真实平扫之间存在系统性CT值偏差，直接套用10HU阈值可能造成误判", "C": "若采用虚拟平扫替代方案，应了解本机虚拟平扫与真实平扫的偏差范围，并结合增强廓清率等指标综合判断", "D": "增强廓清率的计算需要平扫、增强及延迟期数据，虚拟平扫的偏差同样会传导到廓清率结果中", "E": "由于虚拟平扫由增强数据生成，其CT值必然低于真实平扫，可直接减去固定值后套用原阈值"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-017", "kp": "虚拟平扫在肾上腺检查中的应用与限度", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】E错误，为应选项。虚拟平扫与真实平扫的CT值偏差方向与幅度并不固定，受算法版本、器官、体型、对比剂浓度与扫描时相影响，多数研究报告虚拟平扫略高于真实平扫，也有偏低的情形，不能用「必然偏低、减去固定值」的方式简单校正。【为什么错】A正确：≤10HU的腺瘤诊断阈值确立于常规平扫。B正确：正因存在系统偏差，直接套用阈值可能导致富脂腺瘤被误判为乏脂病变或反之。C正确：临床上应先在本机做验证、了解偏差区间，并联合绝对廓清率与相对廓清率判断。D正确：廓清率公式中包含平扫值，虚拟平扫的误差会传导至最终百分比。", "tr": "凡涉及「用虚拟平扫替代真实平扫」的题目，答题核心是「偏差存在且不固定，阈值不能直接照搬」。肾上腺、肝脏脂肪定量、钙化评分是三个必须谨慎的场景。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U16-0118", "t": "多选题", "s": "关于能量CT碘图（碘密度图）及碘定量的临床应用，下列说法正确的是", "o": {"A": "碘图以碘的浓度（mg/mL）表达组织内对比剂分布，可用于评价肿瘤强化程度与消融、靶向治疗后的疗效", "B": "肺动脉CTA同步生成的肺碘分布图可显示肺栓塞所致的楔形灌注缺损，提高亚段栓塞与血流动力学评价的把握", "C": "在心肌灌注评价中，碘图可显示心肌灌注缺损区，提供比常规图像更客观的定量指标", "D": "碘定量结果受扫描时相、注射方案、患者循环状态与感兴趣区放置的影响，纵向随访须保持方案一致", "E": "碘图上碘浓度为零即可断定病灶为坏死组织，无需其他征象支持"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-018", "kp": "碘图与碘定量的临床应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (6)碘图", "ex": "【为什么对】A正确：碘图把强化「密度差」转换为可量化的碘浓度，避免了不同体型、注射方案下HU值的不可比性，对疗效评价（如消融后残留、抗血管生成治疗反应）尤为有用。B正确：肺碘分布图是双能量肺动脉CTA的常规附加产品，有助于发现远端栓塞与评估灌注受损范围。C正确：碘图在心肌灌注中可显示缺损区并给出定量指标，与常规图像相比减少了主观性。D正确：碘定量的可重复性依赖方案一致性，纵向随访必须固定注射流率、总量、延迟时间与重建参数。【为什么错】E错误：碘浓度极低可见于坏死，也可见于囊变、黏液成分、乏血供肿瘤、扫描时相过早或注射失败，须结合形态学与临床综合判断。", "tr": "碘定量是「相对可比」而非「绝对真值」。跨设备、跨方案的碘浓度数值不宜直接比较，随访务必同机同方案。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-0119", "t": "单选题", "s": "关于CT低剂量技术中自动管电流调制（ATCM）的工作原理，下列说法正确的是", "o": {"A": "根据定位像或实时反馈的患者衰减信息，在x-y平面内（角度方向）与z轴方向自动调整管电流，以在设定的图像质量水平下使用尽可能低的剂量", "B": "在整个扫描过程中始终保持管电流恒定", "C": "通过降低管电压来减少剂量，与管电流无关", "D": "仅在儿童扫描中可以启用", "E": "启用后无需再设定噪声指数或参考毫安秒等图像质量指标"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-019", "kp": "自动管电流调制与低剂量技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】A正确。ATCM综合角度调制（补偿肩部、骨盆在侧位方向衰减更大的各向异性）与纵向调制（按部位厚度沿z轴变化），在维持既定图像质量（噪声指数或参考毫安秒）的前提下动态给出最小必要管电流，是CT剂量优化的基础功能。【为什么错】B错误：恒定管电流正是ATCM要取代的固定输出模式。C错误：降低管电压属自动管电压选择（如CARE kV类）功能，与ATCM是不同但可协同的技术。D错误：ATCM适用于各年龄段，儿童更强调结合低kV与体型化协议。E错误：ATCM必须由使用者设定目标图像质量参数，参数设定不当会导致剂量过高或图像不可诊断，这恰是质量控制的关键环节。", "tr": "ATCM不是「一键降剂量」。噪声指数设置越低、参考毫安秒越高，系统给出的实际剂量越大；协议维护时必须按部位与临床任务逐一整定。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0120", "t": "单选题", "s": "关于CT导向介入技术的应用范围，下列说法错误的是", "o": {"A": "CT导向可用于肺、纵隔、肝、肾、胰腺、腹膜后及骨骼病变的穿刺活检", "B": "CT导向可用于脓肿、积液的穿刺引流与囊肿硬化治疗", "C": "CT导向可用于肿瘤的射频、微波消融与放射性粒子植入", "D": "CT导向可用于神经阻滞与椎体成形术等疼痛介入治疗", "E": "CT导向的空间分辨率与软组织对比不足，因此不适合用于肺部小结节的定位穿刺"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-020", "kp": "CT介入技术的应用范围", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (1)应用范围", "ex": "【为什么对】E错误，为应选项。CT具有优良的密度分辨率与断层定位能力，对含气肺组织与结节之间的天然高对比尤为敏感，肺结节穿刺活检与术前定位（如带钩钢丝、染料定位）正是CT导向最具优势的适应证之一。【为什么错】A、B、C、D均为CT导向介入的公认适应证：A涵盖胸腹部与骨骼的诊断性活检；B为常见的治疗性引流与硬化；C为肿瘤的局部消融与近距离治疗；D为疼痛与脊柱介入。CT可清晰显示进针路径上的血管、肠管、胸膜、神经根等结构，是这些操作的主要引导方式之一。", "tr": "各引导方式的分工：超声实时、无辐射，适合浅表与肝脏；CT断层定位精确，适合肺、骨、深部与含气结构遮挡区；MR软组织分辨率最高但设备与器械要求特殊。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0121", "t": "多选题", "s": "CT导向穿刺活检的检查前准备，下列做法正确的是", "o": {"A": "核查血常规、凝血功能，了解患者抗凝或抗血小板药物使用情况并按规范停药", "B": "复习既往影像资料，与临床共同确定靶点、拟定进针路径与体位，评估禁忌证", "C": "训练患者平静呼吸下的屏气配合，胸部穿刺尤其强调每次屏气幅度一致", "D": "备齐急救药品与设备（吸氧、监护、胸腔闭式引流包等），签署知情同意书", "E": "为缩短操作时间，术前不需要做定位扫描，可直接凭体表标志进针"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-021", "kp": "CT介入检查前准备", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (2)检查前准备", "ex": "【为什么对】A正确：凝血功能异常是穿刺的重要相对禁忌，抗栓药物需按临床规范停用并评估血栓风险。B正确：路径规划应避开叶间裂、大血管、肠管、胆囊与神经根，并结合体位可行性与患者耐受度。C正确：屏气幅度不一致会导致靶点位移，是胸部穿刺失败与并发症的重要原因，术前训练必不可少。D正确：气胸、出血、迷走反射等并发症需即时处置能力，知情同意为规范要求。【为什么错】E错误：穿刺前必须行定位扫描，贴放定位栅或标志线，测量进针点、角度与深度，凭体表经验盲穿违反操作规范并显著增加并发症风险。", "tr": "呼吸配合是胸部CT介入成败的关键变量：定位扫描、进针、复查扫描应始终在同一呼吸幅度（通常为平静呼气末）完成。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-0122", "t": "案例分析题", "s": "患者男性，65岁，吸烟史40年，慢性阻塞性肺疾病病史8年，肺功能中度受损，胸部CT发现右肺上叶后段直径2.0cm结节，边缘分叶伴胸膜牵拉，位于胸膜下约2cm，周围散在肺大疱。临床拟行CT导向经皮穿刺活检以明确病理。设备具备CT透视（实时透视）与常规间断扫描两种引导模式，可根据需要切换。作为配合本次操作的技师，下列判断中错误的是", "o": {"A": "应先做薄层定位扫描，选择避开叶间裂、大血管与肺大疱的最短安全路径，并尽量使针道垂直于胸膜进入", "B": "CT透视可实时观察针尖位置、缩短操作时间，但术者手部与患者受照剂量增加，应使用针持器并采用低毫安透视", "C": "该患者慢性阻塞性肺疾病、肺大疱多，气胸风险高，术后应即刻扫描全胸并按规范观察，必要时行胸腔闭式引流", "D": "穿刺路径经过肺组织越长、穿越胸膜次数越多，气胸与肺出血风险越高", "E": "为提高取材成功率，应尽量选择经过肺大疱的路径以避开血管"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-022", "kp": "CT导向肺穿刺活检的技术要点与并发症", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (3)穿刺活检扫描技术", "ex": "【为什么对】E错误，为应选项。穿刺路径必须避开肺大疱：穿破肺大疱极易造成难以愈合的气胸甚至张力性气胸，这在慢性阻塞性肺疾病患者中后果尤为严重。避开血管的正确做法是通过薄层与多平面重组重新规划路径，而非借道肺大疱。【为什么错】A正确：最短肺内路径、垂直穿越胸膜、避开叶间裂与大血管是降低气胸与出血风险的基本原则。B正确：CT透视提高实时性但显著增加术者手部剂量，须用针持器、准直、低毫安并避免手直接置于射野内。C正确：慢性阻塞性肺疾病患者气胸发生率明显升高，术后即刻及延迟复查、备好引流是标准流程。D正确：肺内针道长度与穿越胸膜次数是气胸与出血最公认的危险因素。", "tr": "肺穿刺三条铁律：不穿肺大疱、不多次穿越胸膜、不斜切叶间裂。术后即刻扫描与观察期不可省略，迟发气胸可在数小时后出现。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0123", "t": "案例分析题", "s": "患者男性，60岁，慢性乙型肝炎病史20年，增强CT发现肝右叶单发肝细胞癌，最大径3.0cm，肝功能Child-Pugh A级，血小板与凝血功能基本正常，因合并症不宜手术切除，拟在CT导向下行微波消融治疗。术前增强CT显示病灶邻近肝包膜，距结肠肝曲约1.2cm。作为参与该治疗的技师，负责影像技术保障与术中扫描配合，下列做法中错误的是", "o": {"A": "术前应做增强扫描明确病灶边界与邻近结构，规划进针角度与消融范围，力求覆盖病灶及周边约5mm安全边界", "B": "对邻近肠管的病灶可采用人工腹水或注气等隔离措施降低热损伤风险，并在扫描中确认隔离效果", "C": "消融过程中可间断扫描确认针尖位置与消融区变化，消融结束可行增强扫描初步评估有无残留强化", "D": "放射性粒子植入与消融同属CT导向的肿瘤局部治疗，前者依靠持续低剂量近距离照射，后者依靠热效应致组织凝固性坏死", "E": "因消融是热毁损治疗，术中无需关注针道出血与针道种植风险，也不需要针道消融"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-023", "kp": "CT导向肿瘤消融与粒子植入", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (4)疾病治疗检查技术", "ex": "【为什么对】E错误，为应选项。消融退针时常规行针道消融，目的正是止血与减少肿瘤沿针道种植转移；针道出血在肝包膜下病灶、凝血功能不佳者尤需警惕，术后应扫描观察有无腹腔出血。【为什么错】A正确：为降低局部复发，消融范围应超出肿瘤边缘约5mm形成安全边界。B正确：人工腹水、注气或注射葡萄糖溶液隔离是保护邻近肠管、膈肌、胆囊的常用手段，须在扫描中确认隔离层形成。C正确：术中间断扫描定位、术毕增强初评是CT导向消融的标准流程，完全评价疗效通常在术后1个月复查。D正确：粒子植入属近距离放射治疗，消融属热毁损，两者机制不同但同为CT导向的局部治疗手段。", "tr": "邻近空腔脏器、胆管与大血管是消融的高风险因素：大血管旁存在「热沉效应」易致消融不全，肠管旁则有穿孔风险，二者的应对策略不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-0124", "t": "单选题", "s": "关于CT导向介入操作的检查要点与质量控制，下列说法错误的是", "o": {"A": "宜采用薄层、小视野扫描以提高针尖显示精度，并限制扫描范围至操作必需的最小长度", "B": "在满足针尖与靶点辨识需要的前提下，可使用明显低于诊断扫描的管电流以降低累积剂量", "C": "使用CT透视时应采用间歇踩踏而非持续曝光，并借助针持器使术者手部离开射野", "D": "术中每次扫描均应保持与定位扫描一致的呼吸幅度与体位，并核对床位坐标", "E": "为保证图像质量，介入过程中每次确认针尖位置都应使用与诊断扫描相同的高剂量参数扫描全器官"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-024", "kp": "CT介入的检查要点与质量控制", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (5)检查要点与质量控制", "ex": "【为什么对】E错误，为应选项。介入过程中的确认扫描属「任务导向」影像，只需看清针尖与靶点的相对关系，应使用低剂量参数、限定在针尖附近的少数层面，而非全器官高剂量扫描；重复多次的高剂量确认扫描会使累积剂量迅速攀升，违背最优化原则。【为什么错】A正确：薄层小视野提高针尖定位精度，限制范围直接降低剂量。B正确：介入确认扫描对噪声的容忍度远高于诊断扫描，低毫安足以分辨金属针尖。C正确：间歇曝光与针持器是CT透视下降低术者手部剂量的关键措施。D正确：呼吸幅度、体位与床位坐标的一致性是保证靶点位置可重复的前提。", "tr": "介入影像的质量标准与诊断影像不同：前者以「够用即可」为原则。把诊断协议直接套用于术中反复确认扫描，是介入剂量失控的常见原因。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1001", "t": "单选题", "s": "CT球管“飞焦点（flying focal spot）”技术的主要作用是", "o": {"A": "在z轴方向交替改变焦点位置，提高采样密度与图像分辨率", "B": "提高球管寿命", "C": "降低噪声", "D": "减少扫描时间", "E": "增加对比剂用量"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-101", "kp": "飞焦点技术", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】飞焦点技术使阳极焦点在z轴（及x轴）方向交替偏移，获得交错采样数据，等效提高采样密度，改善空间分辨率，故A正确。\n【为什么错】B：焦点偏移与寿命无直接增益。C：噪声降低靠重建算法与剂量。D：扫描时间由旋转速度决定。E：对比剂用量与焦点技术无关。", "tr": "飞焦点的本质是“用焦点位置变化换采样密度”，服务于分辨率提升。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1002", "t": "单选题", "s": "宽体（大排数）探测器CT的主要优点是", "o": {"A": "单次旋转覆盖范围大，利于心脏与器官动态成像", "B": "只能做头部扫描", "C": "空间分辨率低于窄体", "D": "辐射剂量必然增大", "E": "不能做螺旋扫描"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-102", "kp": "宽体探测器", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】宽体探测器（如320排、16cm覆盖）单次旋转即覆盖大范围脏器，可完成心脏、颅脑全脑灌注等快速扫描，故A正确。\n【为什么错】B：宽体探测器适用于全身各部位。C：其空间分辨率并不低于窄体。D：大覆盖可减少曝光次数，剂量未必增大。E：宽体探测器支持螺旋扫描。", "tr": "宽体探测器的价值是“覆盖与速度”，适合一站式及动态扫描。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1003", "t": "单选题", "s": "双源CT（DSCT）的设备特征是", "o": {"A": "同一机架内安装两套球管-探测器系统", "B": "单球管双焦点", "C": "两个独立机架", "D": "双层探测器单球管", "E": "电子束扫描"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-103", "kp": "双源CT", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】双源CT在同一机架内以约90°夹角安装两套X线球管与探测器系统，可同时采集或双能量成像，故A正确。\n【为什么错】B：双焦点是单球管技术。C：双源不是两台独立机架。D：双层探测器是另一类能谱实现。E：电子束扫描是电子束CT方式，均与双源定义不符。", "tr": "双源=双球管双探测器；双能实现还有单源快kV切换、双层探测器等。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1004", "t": "单选题", "s": "目前临床能谱CT的实现方式不包括", "o": {"A": "双层探测器双能量采集", "B": "单源快速管电压（kV）切换", "C": "双源双球管不同kV同时曝光", "D": "光子计数探测器能谱分辨", "E": "激光全息成像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-104", "kp": "能谱CT实现方式", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】双层探测器、单源快kV切换、双源不同kV及光子计数探测器均为能谱CT的真实实现方式，而激光全息成像与能谱CT无关，不是能谱CT的实现方式，故E正确。\n【为什么错】A：双层探测器通过一次曝光分高低能层采集，是能谱CT实现方式。B：单源快速kV切换是能谱CT实现方式。C：双源双球管不同kV同时曝光是能谱CT实现方式。D：光子计数探测器具备能量分辨能力，是能谱CT实现方式，均不符合题意。", "tr": "记住能谱CT四种主流实现：双源、快kV切换、双层探测器、光子计数。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1005", "t": "单选题", "s": "低keV单能量图像在能谱CT中的主要临床价值是", "o": {"A": "提高碘对比剂的CT值对比，改善血管与病灶增强显示", "B": "减少软组织显示", "C": "增加金属伪影", "D": "降低图像噪声", "E": "减少扫描范围"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-105", "kp": "低keV单能量应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (2)单能谱CT临床应用", "ex": "【为什么对】碘在低keV时衰减显著增加，低keV单能量图像可明显提高含碘血管与病变的CT值对比，故A正确。\n【为什么错】B：低keV并非减少软组织显示。C：低keV反而加重线束硬化，金属伪影更明显。D：低keV图像噪声通常升高。E：扫描范围与keV选择无关。", "tr": "低keV“增碘对比但噪声高”，高keV“减伪影但对比低”，两者需权衡。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1006", "t": "单选题", "s": "高keV单能量图像的主要用途是", "o": {"A": "减少线束硬化和金属伪影", "B": "提高软组织分辨率", "C": "增加碘对比度", "D": "提高扫描速度", "E": "减少对比剂用量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-106", "kp": "高keV单能量应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (2)单能谱CT临床应用", "ex": "【为什么对】高keV光子能量高、穿透力强，能谱CT虚拟的高keV图像可显著减轻金属植入物附近的线束硬化与金属伪影，故A正确。\n【为什么错】B：高keV组织对比度下降。C：高keV碘对比反而降低。D：keV不影响机架转速。E：对比剂用量由检查方案决定，与keV无直接关系。", "tr": "去金属伪影=高keV+迭代/MARS；增碘对比=低keV，方向相反。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1007", "t": "单选题", "s": "能谱CT“碘图（Iodine Map）”显示的内容是", "o": {"A": "碘对比剂在组织中的分布及浓度信息", "B": "骨密度分布", "C": "肺纹理分布", "D": "皮肤厚度", "E": "脂肪含量"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-107", "kp": "碘图", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (6)碘图", "ex": "【为什么对】碘图通过双能量物质分离提取碘成分，以彩色/伪彩图显示碘的空间分布与浓度，用于血供与疗效评估，故A正确。\n【为什么错】B：骨密度由钙定量评估。C：肺纹理属解剖显示。D：皮肤厚度非能谱碘成像对象。E：脂肪含量用脂肪定量（PDFF等），均非碘图内容。", "tr": "碘图专指“碘分布”，与钙图、尿酸图等其他基物质图区分。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1008", "t": "单选题", "s": "虚拟平扫（VNC）图像是通过什么方式获得的", "o": {"A": "从增强双能数据中去除碘成分，模拟平扫图像", "B": "直接扫描后剪裁", "C": "增强后二次重扫", "D": "图像锐化处理", "E": "缩小扫描范围"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-108", "kp": "虚拟平扫VNC", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】双能量数据经物质分解可将碘从混合衰减中分离出去，重建出不含碘的虚拟平扫图像，故A正确。\n【为什么错】B：剪裁不改变密度信息。C：二次重扫是真实平扫，增加剂量。D：锐化是后处理增强。E：范围缩小与去碘无关。", "tr": "VNC的“虚拟”在于软件去碘，可免去部分真实平扫，降低剂量。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1009", "t": "单选题", "s": "虚拟平扫（VNC）的主要临床价值是", "o": {"A": "减少额外真实平扫扫描，降低辐射剂量", "B": "提高图像空间分辨率", "C": "缩短球管寿命", "D": "增加对比剂用量", "E": "替代病理检查"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-109", "kp": "VNC临床应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】VNC可代替部分真实平扫用于钙化评估、结石成分判断等，减少一次扫描即降低辐射剂量，故A正确。\n【为什么错】B：分辨率由探测器决定。C：与球管寿命无关。D：对比剂用量由增强方案决定。E：VNC提供密度信息，无病理诊断能力。", "tr": "VNC的价值是“剂量优化”，但钙化定量等仍需与真实平扫对比验证。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1010", "t": "单选题", "s": "双能量CT“物质定量分析”的基本原理是", "o": {"A": "将组织衰减分解为水和碘、钙等基物质的组合", "B": "根据图像颜色定量", "C": "根据扫描层数定量", "D": "根据患者身高体重定量", "E": "根据扫描时间定量"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-110", "kp": "物质定量分析原理", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】不同物质在高低两种能量下的衰减不同，双能数据可求解出各基物质（如水、碘、钙、尿酸等）的比例与浓度，故A正确。\n【为什么错】B：颜色为显示方式，非定量依据。C：扫描层数反映覆盖范围。D：患者身高体重与物质分解无关。E：扫描时间与定量分析无关。", "tr": "物质定量基于“双能衰减差异+基物质分解”，是能谱CT的核心算法。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1011", "t": "单选题", "s": "利用双能量CT诊断痛风的主要依据是", "o": {"A": "尿酸钠结晶的双能量特征被识别并以彩色标记", "B": "关节间隙增宽", "C": "软骨钙化", "D": "骨密度升高", "E": "脂肪沉积"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-111", "kp": "双能量痛风成像", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】双能量CT可区分尿酸钠（MSU）与钙盐，软件以特定颜色标记尿酸盐结晶，直观显示痛风石与沉积，故A正确。\n【为什么错】B：痛风不表现为关节间隙增宽。C：软骨钙化是焦磷酸盐沉积特征。D：痛风与骨密度升高无关。E：脂肪沉积非痛风诊断依据。", "tr": "双能量痛风成像的关键是“区分尿酸盐与钙”，颜色标记为诊断工具。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1012", "t": "单选题", "s": "CT金属伪影去除（MAR）技术降低伪影的途径是", "o": {"A": "结合高keV单能量图像与迭代/专用重建算法抑制线束硬化", "B": "提高扫描层厚", "C": "减小矩阵", "D": "降低管电流", "E": "延长扫描时间"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-112", "kp": "金属伪影去除", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】金属伪影源于线束硬化与光子饥饿，高keV单能量图像减少硬化，迭代或专用MAR算法对投影数据修正，二者结合可显著抑制金属伪影，故A正确。\n【为什么错】B：加大层厚降低分辨率，不能去除金属伪影。C：减小矩阵降低分辨率。D：降低管电流反而加重噪声与光子饥饿。E：延长扫描时间不解决硬化伪影。", "tr": "去金属伪影三件套：高keV、MAR迭代算法、适当提高剂量减少光子饥饿。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1013", "t": "单选题", "s": "CT迭代重建（IR）技术最主要的临床价值是", "o": {"A": "在保证图像质量的前提下降低辐射剂量", "B": "提高扫描速度", "C": "增加对比剂用量", "D": "增大探测器排数", "E": "缩短图像传输时间"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-113", "kp": "迭代重建", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (7)高级重建", "ex": "【为什么对】迭代重建通过数学建模迭代优化，在保持甚至改善图像质量的同时可有效降低噪声，从而支持低剂量扫描，故A正确。\n【为什么错】B：扫描速度由机架与探测器决定。C：迭代重建不增加对比剂。D：探测器排数是硬件参数。E：传输时间与重建算法无关。", "tr": "迭代重建=降噪→低剂量，是CT低剂量技术的核心支撑。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1014", "t": "单选题", "s": "自动管电流调制（ATCM）降低辐射剂量的原理是", "o": {"A": "根据患者体型与衰减实时调节管电流", "B": "固定最大管电流", "C": "提高管电压", "D": "缩短重建矩阵", "E": "增加扫描层数"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-114", "kp": "自动管电流调制", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】ATCM根据定位像测得的体型及扫描中实时衰减信息，在保证图像噪声目标的前提下自动增减管电流，避免不必要的剂量，故A正确。\n【为什么错】B：固定最大电流剂量浪费。C：提高管电压增加剂量与硬化。D：减小矩阵损害分辨率。E：增加层数与剂量无关或增加剂量。", "tr": "ATCM是“按需供量”的剂量优化技术，与固定参数扫描不同。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1015", "t": "单选题", "s": "CT引导下经皮穿刺活检时，确定皮肤进针点的常用定位方法是", "o": {"A": "栅栏定位器结合定位扫描确定体表穿刺点", "B": "凭经验目测", "C": "按患者主诉定位", "D": "按体表血管走行定位", "E": "随意进针后调整"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-115", "kp": "CT引导穿刺定位", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (3)穿刺活检扫描技术", "ex": "【为什么对】栅栏定位器置于体表后行定位扫描，根据栅栏刻度与病灶层面对应关系确定体表进针点与进针路径，故A正确。\n【为什么错】B：凭经验目测无法精确定位。C：按患者主诉定位不客观。D：按体表血管走行定位不准确。E：随意进针后调整增加损伤风险，均不可取。", "tr": "CT引导穿刺的定位依赖“栅栏+定位扫描”的坐标换算。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1016", "t": "单选题", "s": "深度学习重建（DLR）技术提高CT图像质量的方式是", "o": {"A": "利用神经网络学习低剂量图像与高质量图像的映射关系实现降噪", "B": "提高机架转速", "C": "增加造影剂浓度", "D": "扩大扫描视野", "E": "减少重建层数"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-116", "kp": "深度学习重建", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (7)高级重建", "ex": "【为什么对】DLR以海量数据训练神经网络，学习低剂量/噪声图像到高质量图像的映射，实现显著降噪并保留细节，故A正确。\n【为什么错】B：转速为机械性能。C：造影剂浓度与重建无关。D：视野是扫描参数。E：减少层数损害信息，均错误。", "tr": "DLR属于“重建环节的智能化降噪”，与硬件转速、造影方案无关。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1017", "t": "单选题", "s": "光子计数探测器CT的突出优势是", "o": {"A": "直接计数X线光子并分辨能量，剂量效率与能谱分辨率高", "B": "只能单能量成像", "C": "空间分辨率低于常规探测器", "D": "必须使用造影剂", "E": "扫描速度最慢"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-117", "kp": "光子计数探测器", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】光子计数探测器对每个X线光子进行计数并测量其能量，具有更高的剂量效率、固有能谱分辨与空间分辨能力，故A正确。\n【为什么错】B：光子计数天然支持多能量成像。C：其空间分辨率更高。D：造影与否与探测器类型无关。E：其扫描速度并不慢。", "tr": "光子计数CT是“计数+分能”的新一代探测器技术。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1018", "t": "单选题", "s": "肺癌低剂量CT筛查常用的剂量优化组合是", "o": {"A": "低kVp与低mAs结合迭代/深度学习重建", "B": "高kVp高mAs", "C": "大螺距增大扫描层厚", "D": "固定管电流不调制", "E": "取消定位像"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-118", "kp": "低剂量CT筛查", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】低kVp与低mAs直接减少输出剂量，迭代或深度学习重建补偿噪声，是低剂量肺癌筛查的标准组合，故A正确。\n【为什么错】B：高kV/mAs增加剂量。C：大螺距增大层厚降低分辨率。D：不调制浪费剂量。E：定位像用于范围规划不可取消。", "tr": "低剂量=“低参数扫描+智能重建”，二者缺一不可。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1019", "t": "多选题", "s": "CT球管的技术进展包括", "o": {"A": "飞焦点技术", "B": "大功率高散热阳极", "C": "液态金属轴承", "D": "双源双球管系统", "E": "双层探测器"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-119", "kp": "CT球管进展", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】飞焦点、大功率高散热阳极、液态金属轴承、双源双球管均属CT球管技术进展，故A、B、C、D正确。\n【为什么错】E：双层探测器属探测器系统进展，不属于球管技术。", "tr": "“球管进展”与“探测器进展”分属不同考目，勿混淆。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1020", "t": "多选题", "s": "CT探测器系统的进展包括", "o": {"A": "宽体（大排数）探测器", "B": "双层探测器双能采集", "C": "光子计数探测器", "D": "闪烁体-光电二极管阵列", "E": "X线球管旋转阳极"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-120", "kp": "CT探测器进展", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】宽体、双层、光子计数及闪烁体-光电二极管结构均为探测器技术内容，故A、B、C、D正确。\n【为什么错】E：旋转阳极是X线球管的部件，不属于探测器。", "tr": "探测器进展聚焦“排数、层次、计数方式、材料”，球管部件不混入。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1021", "t": "多选题", "s": "能谱CT的临床应用包括", "o": {"A": "去骨显示血管（去骨CTA）", "B": "金属伪影去除", "C": "结石成分分析", "D": "痛风尿酸盐沉积识别", "E": "超声弹性测量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-121", "kp": "能谱CT应用范围", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】去骨CTA、金属伪影去除、结石成分分析、痛风识别均为能谱CT的成熟应用，故A、B、C、D正确。\n【为什么错】E：超声弹性测量属超声技术，与CT能谱无关。", "tr": "能谱CT的应用围绕“物质分离与定量”，超声技术不属于其范畴。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1022", "t": "多选题", "s": "CT低剂量技术包括", "o": {"A": "自动管电流调制（ATCM）", "B": "自动管电压选择", "C": "迭代与深度学习重建", "D": "优化扫描范围与滤过", "E": "恒定最大剂量扫描"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-122", "kp": "低剂量技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】ATCM、自动kV选择、智能重建、范围与滤过优化均为低剂量技术手段，故A、B、C、D正确。\n【为什么错】E：恒定最大剂量扫描与低剂量理念相悖，会增加不必要辐射。", "tr": "低剂量是“参数优化+重建补偿+流程控制”的系统工程。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1023", "t": "多选题", "s": "CT介入技术的临床应用包括", "o": {"A": "经皮穿刺活检", "B": "穿刺引流", "C": "肿瘤消融治疗", "D": "疼痛介入治疗", "E": "冠状动脉旁路移植"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-123", "kp": "CT介入应用范围", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (1)应用范围", "ex": "【为什么对】活检、引流、消融、疼痛介入均为CT引导介入的常见应用，故A、B、C、D正确。\n【为什么错】E：冠状动脉旁路移植属外科开胸手术，不属于CT介入技术。", "tr": "CT介入以“经皮微创+CT引导”为特征，外科手术不属其列。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1024", "t": "多选题", "s": "双能量CT可进行定量分析的物质包括", "o": {"A": "碘", "B": "钙", "C": "铁", "D": "脂肪", "E": "气体"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-124", "kp": "物质定量对象", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】双能量可定量碘、钙、铁、脂肪（含脂质成分）等物质，用于强化、骨密度、铁过载、脂肪肝等评估，故A、B、C、D正确。\n【为什么错】E：气体本身衰减极低，不属于双能量定量分析的常规对象。", "tr": "物质定量对象为“高衰减物质与代谢物”，空气（气体）不参与。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1025", "t": "多选题", "s": "关于双能量CT不同实现方式的比较，正确的说法是", "o": {"A": "双源CT可实现两套系统同时曝光", "B": "单源快kV切换对运动敏感度相对较低", "C": "双层探测器一次曝光同时获得高低能数据", "D": "光子计数探测器具有固有能谱分辨能力", "E": "所有方式成像速度完全相同"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-125", "kp": "双能量实现方式比较", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】双源同时曝光、快kV切换时间分辨率高、双层探测器一次曝光、光子计数固有分能，均为各方式的特点，故A、B、C、D正确。\n【为什么错】E：不同实现方式在扫描速度、能谱精度、剂量效率上存在差异，并非完全相同。", "tr": "双能量各实现方式在“时间同步性、能谱分离度、剂量”上各有取舍。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U16-1026", "t": "多选题", "s": "CT引导穿刺活检的质量控制要点包括", "o": {"A": "精确定位进针点与穿刺路径", "B": "避开大血管、肺大疱等高危结构", "C": "穿刺后CT扫描观察有无气胸、出血等并发症", "D": "核对病理标本的获取与处理", "E": "进针过程无需任何影像确认"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-126", "kp": "穿刺活检质量控制", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (5)检查要点与质量控制", "ex": "【为什么对】精确定位、避开高危结构、术后复查并发症、标本规范处理均为穿刺质控要点，故A、B、C、D正确。\n【为什么错】E：进针全程需CT扫描确认针尖位置，绝不能在无影像确认下盲目进针。", "tr": "CT介入质控强调“全程影像引导+并发症监测”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1027", "t": "多选题", "s": "关于虚拟平扫（VNC）与真实平扫的比较，正确的说法是", "o": {"A": "VNC可减少一次真实扫描，降低辐射剂量", "B": "VNC不含碘成分", "C": "VNC对钙化显示存在一定差异，必要时需真实平扫对照", "D": "VNC图像由增强双能数据重建获得", "E": "VNC需要额外注射更多对比剂"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-127", "kp": "VNC与真实平扫", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】VNC去碘重建、免除真实平扫、降低剂量，但钙化等微小定量与真实平扫存在差异需对照，故A、B、C、D正确。\n【为什么错】E：VNC不额外增加对比剂，使用的是增强扫描本身的数据。", "tr": "VNC是“从增强数据中来”，剂量与对比剂均不额外增加。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1028", "t": "多选题", "s": "能谱/双能量CT常用的后处理分析内容包括", "o": {"A": "单能量图像", "B": "碘密度图", "C": "有效原子序数图", "D": "基物质分解图", "E": "患者心率曲线"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-128", "kp": "能谱后处理分析", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】单能量、碘图、有效原子序数、基物质分解均为能谱后处理分析项，故A、B、C、D正确。\n【为什么错】E：心率曲线属心电监护与心电门控范畴，不是能谱物质分析内容。", "tr": "能谱后处理围绕“能量与物质”，心率监测属生理信号。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U16-1029a", "t": "共用题干题", "s": "为直观评估肺结节的血供与强化程度，应优先调用的后处理图像是", "o": {"A": "碘图（碘密度图）", "B": "骨密度图", "C": "尿酸图", "D": "心电曲线", "E": "胃部重建图"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-129", "kp": "碘图应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (6)碘图", "ex": "【为什么对】碘图直接显示碘在病灶中的分布与浓度，反映结节血供与强化程度，是评估富血供病变的直观工具，故A正确。\n【为什么错】B：骨密度图用于钙定量。C：尿酸图用于痛风。D：心电曲线是心脏门控监测。E：胃部重建图与肺结节评估无关。", "tr": "“看血供”对应碘图，“看钙化”对应骨像/钙图，“看尿酸”对应痛风成像。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1601", "gs": "患者男性，60岁，胸部增强双能量CT检查，临床需评估右下肺结节的血供情况并观察结节内有无钙化，同时希望减少检查总辐射剂量。技师负责能量成像方案与后处理参数选择。"}, {"id": "U16-1029b", "t": "共用题干题", "s": "在不增加额外扫描的前提下评估结节内钙化并减少剂量，应采用的方案是", "o": {"A": "利用增强双能数据重建虚拟平扫（VNC）观察钙化", "B": "另行一次真实平扫", "C": "加大对比剂用量", "D": "缩小扫描范围", "E": "降低重建层数"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-130", "kp": "VNC评估钙化", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】VNC从增强数据中去除碘，可近似平扫状态观察钙化，避免真实平扫的额外辐射，故A正确。\n【为什么错】B：真实平扫增加一次扫描剂量，与“不增加额外扫描”矛盾。C：加大对比剂干扰钙化观察。D：缩小范围无法完整评估。E：减少重建层数损害信息，均错误。", "tr": "VNC的核心价值正是“用软件替平扫，省一次辐射”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1601", "gs": ""}, {"id": "U16-1030a", "t": "共用题干题", "s": "针对金属伪影，技师应优先采用的能谱处理方案是", "o": {"A": "重建高keV单能量图像并启用金属伪影去除（MAR）迭代算法", "B": "降低管电压扫描", "C": "增大重建层厚", "D": "减少扫描范围", "E": "关闭迭代重建"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-131", "kp": "去金属伪影方案", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】高keV减少线束硬化，MAR迭代算法专门校正金属投影数据，两者结合是去金属伪影的标准方案，故A正确。\n【为什么错】B：低kV加重硬化伪影。C：大层厚降低分辨率且不除伪影。D：缩小范围不能消除伪影。E：关闭迭代失去校正手段。", "tr": "去金属伪影=高keV+MAR+保持适当剂量，低kV方向相反。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1602", "gs": "患者女性，68岁，左侧人工髋关节置换术后，拟行骨盆CT检查。因金属假体影响，常规CT图像出现明显放射状金属伪影，遮挡髋臼周围结构。临床希望尽量消除伪影以观察假体周围骨质。"}, {"id": "U16-1030b", "t": "共用题干题", "s": "金属伪影产生的根本原因是", "o": {"A": "金属对X线的线束硬化与光子饥饿效应", "B": "探测器排数不足", "C": "球管旋转过快", "D": "图像传输丢包", "E": "患者姓名过长"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-132", "kp": "金属伪影机制", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】金属高原子序数使X线束硬化严重、探测器侧光子被大量吸收产生光子饥饿，重建时形成放射状伪影，故A正确。\n【为什么错】B：探测器排数影响覆盖与速度，不直接产生金属伪影。C：旋转速度影响时间分辨。D：传输丢包造成数据缺失故障。E：姓名与成像无关。", "tr": "金属伪影的物理本质是“硬化+光子饥饿”，MAR针对此设计。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1602", "gs": ""}, {"id": "U16-1031a", "t": "共用题干题", "s": "确定体表进针点前，最应采用的定位扫描方式是", "o": {"A": "体表放置栅栏定位器后行定位扫描，结合病灶层面确定进针点", "B": "凭手感直接进针", "C": "根据X线胸片位置进针", "D": "根据体表痣的位置进针", "E": "随机选取进针点"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-133", "kp": "穿刺定位扫描", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (3)穿刺活检扫描技术", "ex": "【为什么对】栅栏定位器随体表放置，定位扫描后栅栏刻度与病灶层面一一对应，可精确换算体表进针点与进针路径，故A正确。\n【为什么错】B：凭手感直接进针无法保证路径。C：根据X线胸片位置进针误差大。D：根据体表痣的位置进针无解剖依据。E：随机选取进针点风险高，均不符合CT引导定位要求。", "tr": "栅栏定位+定位扫描是CT引导穿刺的坐标基础。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1603", "gs": "患者男性，52岁，CT发现右肺上叶后段一枚1.5cm实性结节，性质待定，临床拟行CT引导下经皮肺穿刺活检。技师负责穿刺前的定位扫描与进针路径规划。"}, {"id": "U16-1031b", "t": "共用题干题", "s": "穿刺完成后，为及时发现气胸等并发症，正确的做法是", "o": {"A": "穿刺点层面再行CT扫描观察胸腔", "B": "立即让患者出院", "C": "仅电话随访", "D": "不做任何检查", "E": "常规行消化道造影"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-134", "kp": "穿刺术后并发症监测", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (5)检查要点与质量控制", "ex": "【为什么对】肺穿刺后复查CT可迅速发现气胸、出血等并发症并评估程度，是标准的术后处理流程，故A正确。\n【为什么错】B：立即出院延误并发症处理。C：电话随访无法客观判断。D：不检查存在安全隐患。E：消化道造影与肺穿刺并发症无关。", "tr": "肺穿刺质控闭环=术前定位→术中引导→术后CT复查。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1603", "gs": ""}, {"id": "U16-1032", "t": "案例分析题", "s": "某医院开展肺癌低剂量CT筛查项目，需为长期吸烟的中老年人群设计扫描方案，要求在满足肺结节检出能力的前提下最大限度降低辐射剂量，并兼顾图像噪声与扫描效率。技师确定参数组合时，筛查方案应在满足肺结节显示前提下采用低kVp、自动管电流调制与迭代或深度学习重建相结合的优化组合。需兼顾结节检出、图像噪声与扫描效率的综合要求。下列方案中最合理的是", "o": {"A": "低kVp结合ATCM与迭代重建，固定扫描范围仅覆盖胸部", "B": "采用最高kVp与最大管电流", "C": "不做定位像直接扫描", "D": "用头部参数扫描胸部", "E": "取消自动曝光控制"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-135", "kp": "低剂量筛查方案设计", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】低kVp降低剂量，ATCM按体型调制电流，迭代/深度学习重建补偿噪声，范围限定胸部避免无效照射，兼顾检出与剂量，故A正确。\n【为什么错】B：最大参数剂量高。C：定位像用于规划扫描范围不可省。D：头部参数不适于胸部。E：取消自动曝光控制损失剂量优化，均错误。", "tr": "低剂量筛查是“参数+调制+重建+范围”四位一体的优化。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1033", "t": "案例分析题", "s": "患者男性，45岁，反复足趾关节红肿热痛发作3年，血尿酸升高，临床疑诊痛风。为证实关节及周围有无尿酸盐结晶沉积并评估负荷，申请双能量CT检查。技师在扫描与后处理中的双能量CT通过物质分解区分尿酸盐与钙盐，痛风专用后处理以特定颜色标记尿酸盐结晶。扫描范围应包含足、踝及膝等易受累部位，避免遗漏沉积。正确做法是", "o": {"A": "双能量扫描后使用痛风专用算法识别并以特定颜色标记尿酸盐结晶", "B": "常规单能量平扫即可识别尿酸盐", "C": "使用造影剂增强后观察尿酸", "D": "扫描后直接目测判断", "E": "用超声代替CT"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-136", "kp": "痛风双能量成像", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】双能量数据经物质分解可区分尿酸盐与钙盐，痛风专用算法以绿色等特定颜色标记尿酸盐沉积，实现可视化诊断，故A正确。\n【为什么错】B：常规单能量无法区分尿酸与钙。C：尿酸识别无需造影剂。D：目测不能定量识别成分。E：超声是辅助方法，本题问双能量CT的正确用法。", "tr": "痛风双能量识别的关键是“尿酸-钙分离+颜色标记”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1034", "t": "案例分析题", "s": "患者男性，50岁，因脑血管病变行头颈部CTA，常规重建图像中颅底骨骼与颅内血管重叠，影响前交通动脉瘤的观察与测量。设备具备能谱CT功能，可通过后处理去除骨组织。能谱后处理可基于双能数据去除骨组织，仅保留含碘血管，提高动脉瘤等血管病变的显示。去骨效果受骨与血管衰减差异影响，需验证后处理图像质量。技师应采用的后处理方案是", "o": {"A": "利用双能量去骨技术生成去骨CTA图像显示颅内血管", "B": "加大对比剂浓度", "C": "缩小扫描矩阵", "D": "仅保留骨像", "E": "降低keV至最低"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-137", "kp": "去骨CTA", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】双能量物质分解可将骨组织分离去除，仅保留含碘血管，生成去骨CTA，清晰显示颅内血管，故A正确。\n【为什么错】B：浓度增加不解决骨重叠。C：缩小矩阵降低分辨率。D：骨像正好相反。E：极低keV噪声大且骨保留，均错误。", "tr": "去骨CTA是能谱CT的典型应用：骨像/血管像分离，血管像用于观察。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U16-1035", "t": "案例分析题", "s": "某医院计划将腹部常规“平扫+增强”检查改为“单次增强双能量扫描+虚拟平扫”，以降低患者辐射剂量并简化流程。技师与医师评估该方案可行性时，需判断VNC能否替代真实平扫。VNC由增强双能数据重建获得，与真实平扫在钙化定量、微小出血等显示上存在差异，需把握适应证。评估应以诊断需求为导向，权衡剂量收益与图像可靠性。应注意的要点是", "o": {"A": "VNC可部分替代真实平扫，但钙化、出血等评估仍建议与真实平扫对照", "B": "VNC完全等同真实平扫，可无条件替代", "C": "VNC会增加对比剂剂量", "D": "VNC不需要增强数据", "E": "VNC降低空间分辨率"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-138", "kp": "VNC替代平扫评估", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】VNC在多数场合可替代平扫减少剂量，但钙化精细定量、微小出血等与真实平扫存在差异，关键病例需真实平扫对照，故A正确。\n【为什么错】B：无条件下替代过于绝对。C：VNC不增加对比剂。D：VNC恰恰依赖增强双能数据。E：VNC空间分辨率与原始扫描一致，均错误。", "tr": "VNC是“近似平扫”，适应证内可靠，特殊密度判断需对照真实平扫。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U16-1036", "t": "案例分析题", "s": "某医院引进光子计数CT，拟用于冠脉支架成像与高分辨力肺结节的精细评估。技师需理解新技术的成像特性，以正确设定扫描与后处理方案并解释其与传统CT的差异。关于光子计数CT的特点，与传统积分型探测器不同，光子计数探测器可直接计数并分辨单个光子能量，成像特性存在显著差异。设置扫描方案时应充分利用其剂量效率与能谱分辨优势。正确的是", "o": {"A": "对每个X线光子计数并测能量，具备更高空间分辨率与剂量效率", "B": "只能生成单一能量图像", "C": "无法进行能谱分析", "D": "辐射剂量必然高于常规CT", "E": "空间分辨率低于传统探测器"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-139", "kp": "光子计数CT特性", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】光子计数探测器直接计数并分辨光子能量，像素更小、无电子噪声累积，空间分辨率与剂量效率更高，故A正确。\n【为什么错】B：光子计数天然支持多能量/能谱成像。C：其能谱分析能力更强。D：其剂量效率高，同等质量下剂量可更低。E：其空间分辨率更高，均错误。", "tr": "光子计数CT是“计数+分能+高分辨”的换代技术，剂量与分辨率均优于传统。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U16-1037", "t": "案例分析题", "s": "患者女性，55岁，肝癌射频消融术后3个月，复查双能量增强CT以评估肿瘤灭活情况。技师拟通过能量后处理客观评价病灶内碘摄取变化，与术前基线比较，为疗效判断提供定量依据。下列后处理指标碘浓度能反映病灶血供灌注，消融灭活区碘摄取显著下降，可作为疗效评价的定量指标。定量分析结果需结合形态学图像综合判断消融是否彻底。最能反映消融区血供变化的是", "o": {"A": "消融区碘浓度（碘密度值）的变化", "B": "图像压缩率", "C": "扫描层数", "D": "患者体位编号", "E": "重建核名称"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-140", "kp": "碘浓度疗效评估", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (6)碘图", "ex": "【为什么对】碘浓度反映组织灌注与血供，消融灭活区血供消失、碘摄取显著降低，通过对比治疗前后碘密度值可客观评价疗效，故A正确。\n【为什么错】B：压缩率属存储参数。C：层数反映覆盖范围。D：体位编号是管理信息。E：重建核影响图像纹理，均不能定量反映血供变化。", "tr": "能谱疗效评估常用“碘浓度”作为血供的定量生物标志。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0101", "t": "单选题", "s": "7.0T超高场MRI在体部与颅脑成像中出现「中心亮、外周暗」或局部信号缺失的介电效应（驻波效应）伪影，其产生的根本原因及主要对策是", "o": {"A": "射频波长在人体组织中缩短至与被检部位尺寸相当，形成驻波与波传播干涉，使B1场分布严重不均；主要对策为多通道并行发射（pTx）射频匀场、介电垫及自适应脉冲设计", "B": "主磁场B0均匀性变差所致，主要对策是提高主动匀场电流", "C": "梯度线圈涡流所致，主要对策是涡流补偿", "D": "接收线圈通道数不足所致，主要对策是提高并行采集加速因子", "E": "化学位移增大所致，主要对策是提高接收带宽"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-001", "kp": "超高场介电效应与射频匀场", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】A正确。7.0T质子共振频率约298MHz，射频在高介电常数的人体组织中波长缩短至十余厘米量级，与头颅、腹部的尺度可比拟，从而产生驻波与相消／相长干涉，表现为B1场严重不均、局部信号明显衰减或过亮。工程对策包括多通道并行发射的射频匀场（B1 shimming、Transmit SENSE）、介电衬垫改变局部电磁分布，以及绝热脉冲、复合脉冲等对B1不敏感的脉冲设计。【为什么错】B错误：B0不均匀主要表现为几何变形与脂肪抑制失败，与「中心亮外周暗」的射频干涉图样机制不同，且主动匀场校正的是B0而非B1。C错误：涡流表现为图像变形、条纹与相位误差，与驻波无关。D错误：接收通道数影响并行成像与信噪比，不能解决发射端的B1不均。E错误：加大带宽只减轻化学位移位移量与几何失真，不改变B1分布。", "tr": "务必区分B0不均匀（磁场匀场，影响脂肪抑制与几何精度）与B1不均匀（射频匀场，影响信号强度均一性）。7.0T的核心难题之一正是后者，另一个是SAR随场强平方升高。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U17-0102", "t": "多选题", "s": "关于少液氦／无液氦密封磁体技术（如BlueSeal类设计），下列说法正确的是", "o": {"A": "采用微量液氦（约数升）在密封腔内循环冷却超导线圈，取代传统数百至上千升的液氦浸泡式设计", "B": "无需失超管道与常规补氦，降低了机房建设与后期维护成本，也减轻了氦资源紧张带来的压力", "C": "磁体重量减轻、安装条件放宽，有利于在改造机房或移动式平台部署", "D": "由于液氦总量极少，一旦失超时氦气释放量与相应的窒息风险显著低于传统磁体", "E": "无液氦磁体不再是超导磁体，工作时无需维持低温环境"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-002", "kp": "少液氦密封磁体技术", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】A正确：该类设计以数升级别的液氦在全密封腔体内循环，配合高效制冷机维持超导温度。B正确：因氦总量极小且腔体密封，通常无需失超管、无需定期补氦，机房建设与运行成本下降，也回应了全球氦资源紧缺。C正确：磁体总重下降、对机房结构与通风要求降低，便于旧机房改造与特殊场景部署。D正确：失超时可释放的氦气量极少，机房内氧浓度下降与窒息风险显著降低，这是其重要安全优势。【为什么错】E错误：它仍是超导磁体，线圈必须维持在临界温度以下，只是把「大量液氦浸泡」换成了「微量液氦密封循环＋制冷机」，绝非常温工作。", "tr": "「无液氦」是相对传统上千升而言的「极少量密封液氦」，不等于「不需要低温」。超导的前提永远是低温，失超防护流程仍需保留。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-0103", "t": "单选题", "s": "关于开放式MR与专用MR（如四肢专用、乳腺专用设备）的特点，下列说法正确的是", "o": {"A": "开放式MR多采用永磁或低场超导设计，场强较低、幽闭恐惧与介入操作友好，但信噪比与波谱、功能成像能力受限；专用MR以小孔径高填充因子线圈换取局部高分辨率", "B": "开放式MR的场强通常高于封闭超导MR", "C": "专用四肢MR因孔径小、可用线圈单元少，其空间分辨率低于全身MR", "D": "开放式MR不存在任何磁场安全管理要求", "E": "专用乳腺MR不需要专用线圈"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-003", "kp": "开放式与专用MR设备", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】A正确。开放式MR以C形或双柱结构提供大开口，多为永磁或低场超导（常见0.2~1.0T），优点是舒适、便于介入与肥胖、幽闭恐惧患者检查，缺点是信噪比低、化学位移小导致脂肪抑制与波谱受限、快速序列能力弱；四肢与乳腺等专用设备用贴近解剖的小孔径与高填充因子线圈，在局部获得优良信噪比与分辨率。【为什么错】B错误：开放式设备场强通常明显低于常规封闭超导系统。C错误：小孔径带来高填充因子与更贴近的线圈单元，局部信噪比反而提高，专用设备在其目标解剖上的空间分辨率常优于全身MR。D错误：任何MR设备都存在静磁场吸引、射频与梯度相关风险，安全分区、金属筛查与植入物核查同样必需。E错误：乳腺MR必须使用专用乳腺线圈以保证信噪比与双侧同时覆盖。", "tr": "低场并非一无是处：磁敏感伪影小、金属植入物成像与介入兼容性好、SAR低，是其相对优势；但脂肪抑制、波谱与高级功能成像明显受限。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0104", "t": "单选题", "s": "高性能梯度系统（高梯度场强与高切换率）对扩散加权成像（DWI）与扩散张量成像（DTI）最直接的意义是", "o": {"A": "在达到同一b值时可缩短扩散梯度的持续时间与间隔，从而缩短回波时间，提高信噪比并减轻T2衰减与几何变形", "B": "提高主磁场均匀性，改善脂肪抑制效果", "C": "增加射频发射功率，从而提高信噪比", "D": "延长回波时间以获得更高的扩散权重", "E": "使扩散加权成像不再需要平面回波（EPI）读出方式"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-004", "kp": "梯度性能对扩散成像的意义", "ch": "十七、MR技术的进展 → 1.MR设备 → (2)梯度系统", "ex": "【为什么对】A正确。b值近似与梯度幅度的平方、持续时间及间隔相关，梯度场强越高，达到同一b值所需的梯度施加时间越短，最短回波时间随之缩短。TE缩短带来更少的T2衰减、更高的信噪比；同时EPI读出串更短，可减小磁敏感相关的几何变形与模糊。这对高b值DWI、多方向DTI与高阶扩散模型（如DKI、NODDI）尤为关键。【为什么错】B错误：B0均匀性由磁体设计与匀场线圈决定，与梯度性能无直接关系。C错误：射频发射属射频链，梯度不参与。D错误：现代做法是在保证b值的同时尽可能缩短TE，延长TE只会损失信噪比。E错误：EPI仍是扩散成像的主流读出方式；非EPI的扩散读出（如TSE类）存在但并非因梯度性能提升而被免除。", "tr": "梯度切换率过高会诱发周围神经刺激，因此高性能梯度的实际可用性受生理限制约束，并非「越高越好」。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0105", "t": "多选题", "s": "关于梯度切换引起的周围神经刺激（PNS）及其限制，下列说法正确的是", "o": {"A": "其机制是快速变化的梯度磁场（dB/dt）在体内感应出电场与电流，达到阈值时刺激周围神经", "B": "刺激阈值与dB/dt及刺激持续时间相关，受检者体型、体位和肢体是否形成导电回路均有影响", "C": "常见表现为躯干、背部、鼻梁或髋部的麻刺、抽动感，扫描停止后症状随即消失", "D": "设备会依据PNS模型自动限制梯度切换率，这可能导致某些高性能序列的实际参数被降级", "E": "PNS属于射频能量沉积效应，可用SAR值直接评估与限制"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-005", "kp": "周围神经刺激与梯度安全限值", "ch": "十七、MR技术的进展 → 1.MR设备 → (2)梯度系统", "ex": "【为什么对】A正确：由法拉第电磁感应，dB/dt在组织中感生电场，超过神经兴奋阈值即产生刺激。B正确：阈值遵循类似强度—时间曲线的规律，且与人体在梯度场中的位置、体型及双手交叉、双腿接触形成的导电回路密切相关，故检查时应嘱患者勿交叉双手双腿。C正确：典型表现为局部麻刺或肌肉抽动，多见于dB/dt最大的部位，属可逆性生理效应，停止扫描即缓解。D正确：设备内置PNS模型作为硬限制，会自动降低切换率或延长梯度爬升时间，表现为最短TR/TE延长或回波间隔增大。【为什么错】E错误：PNS是梯度（低频磁场）效应，SAR是射频能量沉积（热效应）指标，两者是并列的两类安全限值，不能相互替代。", "tr": "MR的三大安全限值分属三条链路：静磁场B0对应铁磁投射与植入物；梯度对应PNS与噪声；射频对应SAR与热灼伤。混用指标是常见错误。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U17-0106", "t": "单选题", "s": "关于多通道并行发射（pTx）技术的作用，下列说法正确的是", "o": {"A": "通过多个独立发射通道分别控制射频脉冲的幅度与相位（乃至波形），对B1场进行匀场或空间选择性激发，从而改善高场下的信号均匀性并有助于控制局部SAR", "B": "通过多个接收通道提高并行采集的加速倍数", "C": "通过多个梯度通道提高梯度线性度", "D": "通过增大发射功率来克服B1不均匀", "E": "仅用于降低扫描噪声"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-006", "kp": "多通道并行发射与B1匀场", "ch": "十七、MR技术的进展 → 1.MR设备 → (3)射频系统", "ex": "【为什么对】A正确。pTx以两个或多个独立射频功率放大器与发射单元，分别调节各通道的幅度与相位（静态B1匀场），或设计通道间不同的时变波形（动态并行发射、Transmit SENSE、kT-points等），使激发场在感兴趣区内趋于均匀；同时可通过优化降低局部SAR峰值，是3.0T体部与7.0T成像的关键技术。临床3.0T常见的双源并行发射即属此类。【为什么错】B错误：接收端的并行成像（SENSE/GRAPPA）与发射端pTx分属两条链路。C错误：梯度线性度由梯度线圈设计与校正决定。D错误：单纯提高发射功率不改变场分布形态，只会同步抬高SAR。E错误：噪声主要来自梯度线圈的洛伦兹力振动，与射频发射无关。", "tr": "并行成像（接收，加速采集）与并行发射（发射，改善B1均匀性与SAR）名字相近但作用完全不同，是本考点最常见的混淆。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0107", "t": "多选题", "s": "关于现代MR接收线圈的进展，下列说法正确的是", "o": {"A": "密集阵列（多通道相控阵）线圈通过增加小单元数量提高局部信噪比，并为并行成像提供更多空间编码信息", "B": "通道数增加可支持更高的并行加速因子，从而缩短扫描时间", "C": "轻质柔性线圈可贴合体表、提高填充因子，改善患者舒适度与摆位效率", "D": "无线线圈通过取消线缆连接减少缠绕与摆位障碍，需解决供电、同步与数据传输问题", "E": "线圈通道数与信噪比、并行加速能力呈线性正相关，增加通道数不存在收益递减"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-007", "kp": "密集阵列与无线线圈", "ch": "十七、MR技术的进展 → 1.MR设备 → (3)射频系统", "ex": "【为什么对】A正确：小单元贴近解剖，各自接收范围小、噪声耦合体积小，合成后局部信噪比显著提高。B正确：线圈灵敏度分布的空间差异是并行成像的编码来源，通道数越多可支持的加速因子上限越高。C正确：柔性轻质线圈提高填充因子并减轻患者负担，是近年的重要工程方向。D正确：无线线圈简化摆位流程，其难点在于电源管理、时钟同步与高带宽无线数据链路。【为什么错】E错误：存在明显的收益递减——通道间存在耦合与噪声相关性，重叠区域的有效信息趋于饱和，通道数增加还带来重建负担、成本与线圈重量增加。加速因子过高时g因子噪声放大同样限制实际可用性。", "tr": "「通道越多越好」是典型绝对化陷阱。线圈性能取决于单元设计、覆盖匹配与去耦水平，而非单纯的通道数字。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-0108", "t": "单选题", "s": "压缩感知（CS，飞利浦平台常与SENSE结合称Compressed SENSE）能够实现高倍加速，其必须同时满足的三个基本要素是", "o": {"A": "图像在某个变换域具有稀疏性、K空间采用非相干（随机／伪随机）欠采样、采用非线性迭代重建算法", "B": "高场强、多通道线圈、高梯度切换率", "C": "长TR、长TE、大翻转角", "D": "均匀规则欠采样、线性反傅里叶变换重建、高带宽", "E": "呼吸门控、心电门控、脂肪抑制"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-008", "kp": "压缩感知的三要素", "ch": "十七、MR技术的进展 → 1.MR设备 → (4)软件系统", "ex": "【为什么对】A正确。压缩感知理论要求：①信号可稀疏表达（MR图像在小波、全变分、时间频率等变换域内系数稀疏）；②采样方式与稀疏基不相干，随机／伪随机欠采样使混叠表现为类噪声弥散伪影而非相干重影；③使用施加稀疏约束的非线性迭代重建（如L1范数正则化）逐步剔除弥散伪影、恢复图像。三者缺一不可。【为什么错】B错误：这些是硬件条件，可提升整体性能但不是CS成立的数学前提。C错误：与序列对比度参数无关。D错误：规则均匀欠采样产生的是相干卷褶伪影，恰恰不满足非相干条件；线性重建也无法施加稀疏约束。E错误：门控与脂肪抑制属运动与脂肪信号管理，不构成CS要素。", "tr": "并行成像利用「线圈硬件冗余」，压缩感知利用「图像信号冗余」。CS的加速代价是图像纹理平滑化与细节对比度下降，加速因子须按部位与临床任务设定，不宜盲目取上限。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0109", "t": "多选题", "s": "关于MR深度学习重建（DLR）、超分辨率重建与磁共振指纹成像（MRF），下列客观描述正确的是", "o": {"A": "MR深度学习重建多用于从欠采样K空间或低信噪比图像中恢复高质量图像，可在保持图像质量的前提下进一步缩短采集时间", "B": "超分辨率重建通过学习低分辨率与高分辨率图像间的映射来提升表观分辨率，其结果并不等同于真实采集的高分辨率数据", "C": "深度学习重建的表现依赖训练数据分布，对少见病变、罕见解剖或未纳入训练的序列可能出现细节丢失或伪结构，需谨慎解读", "D": "磁共振指纹成像采用伪随机变化的翻转角与重复时间产生独特信号演化「指纹」，通过与字典匹配一次采集同时得到T1、T2、质子密度等多参数定量图", "E": "深度学习重建已在各类在用MR设备上普遍标配，压缩感知等传统加速方法正被其取代"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-009", "kp": "深度学习重建、超分辨率与MR指纹成像", "ch": "十七、MR技术的进展 → 1.MR设备 → (4)软件系统", "ex": "【为什么对】A正确：这是MR深度学习重建的主要用途，在与并行成像、压缩感知联合时可进一步压缩采集时间。B正确：超分辨率提升的是「表观」分辨率，真实的空间频率信息若未被采集则无法凭空获得，评价时应关注小结构的保真度。C正确：泛化能力受限是数据驱动方法的共性局限，罕见病变可能被平滑或产生看似合理的虚假结构。D正确：MRF以伪随机的翻转角与重复时间序列驱动出组织特异的信号演化轨迹，与预先仿真的字典比对，一次采集获得多参数定量图，是定量MR的重要方向。【为什么错】E错误：深度学习重建目前并非所有设备的标配，许多在用机型仍以并行成像与压缩感知为主要加速手段；两类技术是互补关系，压缩感知远未被淘汰。", "tr": "评价重建算法不能只看主观锐利度与噪声水平，还要看小病灶检出与定量测值的可靠性。设备是否具备某项功能应以本机实际配置为准，不能想当然。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MRI介入技术进展", "页": 404}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-0110", "t": "单选题", "s": "关于静息态BOLD功能磁共振（rs-fMRI）与脑功能网络分析，下列说法正确的是", "o": {"A": "受检者在清醒安静、不执行特定任务的状态下采集连续的BOLD时间序列，依据不同脑区低频波动信号的时间相关性推断功能连接，可提取默认网络等静息态网络", "B": "静息态采集必须给予明确的任务刺激范式，否则无法获得BOLD信号", "C": "静息态分析依赖的是高频（大于1Hz）血流波动信号", "D": "静息态成像不受头动影响，无需运动校正", "E": "BOLD信号直接反映神经元的电活动本身"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-010", "kp": "静息态BOLD与脑功能网络", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】A正确。静息态fMRI在无任务状态下用梯度回波EPI连续采集数分钟BOLD序列，分析各脑区自发低频波动（约0.01~0.1Hz）之间的时间相关性，据此构建功能连接网络，默认模式网络、感觉运动网络、视觉网络等为常见结果，临床可用于术前功能区评估与神经精神疾病研究。【为什么错】B错误：无任务正是「静息态」的定义特征，与任务态fMRI相对。C错误：静息态关注的是0.01~0.1Hz的低频波动，高频成分多为心搏、呼吸等生理噪声，需要滤除。D错误：头动是静息态数据最主要的混杂因素，会造成虚假连接，必须做运动校正并对超阈值时间点做剔除或回归。E错误：BOLD基于脱氧血红蛋白的顺磁性变化，反映的是神经活动引起的血流与氧合改变，属间接的血流动力学指标，与电活动之间存在数秒级的血流动力学响应延迟。", "tr": "BOLD是「间接、延迟、相对」的信号：不直接测神经电活动、有数秒延迟、只反映相对变化而非绝对量。静息态更要警惕头动与生理噪声造成的假阳性连接。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0111", "t": "案例分析题", "s": "患者女性，72岁，反复短暂性脑缺血发作，颈动脉超声提示右侧颈内动脉重度狭窄。临床希望评估双侧大脑半球的脑血流灌注，但患者肾小球滤过率为36mL/(min·1.73m²)，不宜使用钆对比剂。所在科室为3.0T MR，配备多通道头线圈与压缩感知加速功能。技师拟采用动脉自旋标记（ASL）灌注成像。下列技术判断中错误的是", "o": {"A": "ASL以动脉血中的水质子作为内源性示踪剂，无需注射对比剂，适合肾功能受限患者", "B": "对于颈内动脉重度狭窄导致侧支循环代偿、血流到达延迟的患者，单一标记后延迟时间（PLD）可能低估患侧脑血流，宜适当延长PLD或采用多延迟时间采集", "C": "ASL的信号变化幅度很小，需要多次标记—对照配对采集并平均，因而对头动敏感", "D": "ASL可提供以mL/(100g·min)为单位的脑血流量定量结果", "E": "ASL图像上患侧出现动脉内高信号（血管内明亮的迂曲信号）说明标记效率过低，应缩短标记后延迟时间"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-011", "kp": "ASL灌注成像的参数选择与判读", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】E错误，为应选项。ASL图像上出现的动脉内高信号（arterial transit artifact）提示标记血液尚滞留于近端动脉、未完全进入毛细血管床，是血流到达时间延长的表现，多见于重度狭窄或侧支代偿者；正确对策是延长标记后延迟时间（如由1.5~1.8s延长至2.0~2.5s）或采用多PLD采集，而不是缩短。【为什么错】A正确：ASL以磁化标记的动脉血水质子为内源性示踪剂，是无创、可重复、适合肾功能不全者的灌注方法。B正确：PLD设置不当是脑血流被系统性低估的主要原因，指南建议按年龄与血管病变状态调整。C正确：ASL的标记效应仅为总信号的约1%~2%，需数十次配对采集平均，头动直接破坏减影。D正确：pCASL结合合适的模型可给出定量脑血流量数值。", "tr": "「动脉通过伪影」是ASL最具特征的读图线索：提示延迟到达而非灌注真正减低，应延长PLD复核。切忌把它直接当作低灌注或标记失败。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0112", "t": "多选题", "s": "关于扩散峰度成像（DKI）与神经突方向离散度与密度成像（NODDI），下列说法正确的是", "o": {"A": "DKI在传统扩散张量模型基础上引入四阶峰度项，用以刻画组织内水分子扩散偏离高斯分布的程度，反映微观结构的复杂性", "B": "DKI要求采集至少两个非零b值（通常包含b值达到1500~2500s/mm²的高b值）及足够多的扩散方向", "C": "NODDI采用多壳（multi-shell）扩散采集与三室模型，估计神经突密度指数与方向离散度指数", "D": "与常规DTI相比，DKI与NODDI的采集时间更长、对信噪比与梯度性能要求更高，临床应用需权衡可行性", "E": "DKI的峰度值越高代表水分子扩散越自由，接近自由水状态"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-012", "kp": "DKI与NODDI高阶扩散模型", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】A正确：生物组织中水分子受细胞膜、髓鞘等障碍限制，扩散位移分布偏离高斯分布，峰度即定量这一偏离程度。B正确：拟合峰度项需要至少两个非零b值，且高b值（常用1500~2500s/mm²）才能体现非高斯特性，方向数一般不少于15个。C正确：NODDI基于多壳采集与「细胞内、细胞外、自由水」三室模型，输出神经突密度指数与方向离散度指数，对灰质与交叉纤维区域比DTI更具解释力。D正确：两者的方向数与b值壳数远多于常规DTI，采集时间与信噪比要求显著提高，需结合并行成像、同时多层激发（SMS）与压缩感知等加速手段。【为什么错】E错误：峰度值越高说明扩散受限、微环境越复杂，越偏离高斯扩散；自由水扩散接近高斯分布，其峰度趋近于零，选项含义完全相反。", "tr": "峰度与ADC是两个方向的指标：ADC反映扩散快慢，峰度反映扩散的非高斯（复杂）程度。自由水＝高ADC、低峰度，切勿混淆。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": true, "src": "模拟", "mk": 1}, {"id": "U17-0113", "t": "单选题", "s": "关于酰胺质子转移（APT）成像及其所属的化学交换饱和转移（CEST）技术，下列说法正确的是", "o": {"A": "对水峰下游约3.5ppm处的酰胺质子施加选择性饱和脉冲，饱和经化学交换传递至自由水后引起水信号下降，据此间接反映组织内游离蛋白质与多肽的浓度及pH环境", "B": "APT直接采集酰胺质子自身的信号，因此信噪比很高", "C": "APT属于扩散加权成像的一种，其对比来源于水分子的布朗运动", "D": "APT成像不需要B0匀场，磁场不均匀不影响其结果", "E": "APT必须注射外源性对比剂才能成像"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-013", "kp": "APT与CEST成像原理", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】A正确。APT是CEST家族中最成熟的临床应用：在相对水峰约+3.5ppm处施加长时程低功率饱和脉冲选择性饱和酰胺质子，饱和的自旋通过化学交换不断转移至自由水池，使水信号出现可测量的下降；该效应与游离蛋白质／多肽浓度及交换速率（受pH影响）相关，临床用于脑肿瘤分级、复发与治疗后改变的鉴别及缺血半暗带的酸中毒评价。【为什么错】B错误：APT是通过水信号的间接放大效应测量的，酰胺质子本身浓度极低，直接检测信噪比不足，这正是CEST采用间接放大机制的原因。C错误：APT属化学交换对比机制，与扩散无关。D错误：APT对B0极其敏感，频率偏移会使饱和位置偏离目标峰，必须做高质量匀场并采集B0图做Z谱校正。E错误：APT属内源性对比技术，无需外源对比剂，这是其重要优势。", "tr": "CEST／APT成像的两大技术前提：高质量B0匀场加频率校正、稳定的饱和脉冲功率与时长。任一环节不当都会造成伪彩图的系统性偏差。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0114", "t": "多选题", "s": "关于体素内不相干运动（IVIM）成像，下列说法正确的是", "o": {"A": "IVIM采用双指数模型，把扩散信号衰减分解为真扩散成分D与微循环灌注相关的假扩散成分D*及灌注分数f", "B": "低b值区间（一般小于200s/mm²）的信号衰减主要受微循环灌注影响，因此需在低b值段设置较密集的采样点", "C": "IVIM可在不使用对比剂的条件下同时获得扩散与灌注相关信息，适用于肾功能不全或不宜使用钆剂的患者", "D": "D*与f的拟合稳定性较D差，受信噪比、b值分布与运动影响明显，重复性相对较低", "E": "IVIM只需常规DWI的两个b值（0与800s/mm²）即可完成双指数拟合"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-014", "kp": "IVIM双指数模型与采集要求", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】A正确：IVIM模型认为体素信号衰减由分子真扩散与毛细血管网内血流的「假扩散」共同构成。B正确：灌注相关的快速衰减集中在低b值段，故常在0~200s/mm²之间布置多个b值以稳定拟合D*与f。C正确：IVIM为无对比剂的灌注相关成像，在肝纤维化、肿瘤疗效评价与肾功能受限患者中有独特价值。D正确：D*的拟合误差最大，f次之，D最稳定，这是IVIM临床推广的主要制约，因此报告时应关注重复性。【为什么错】E错误：双指数拟合需要多个b值（通常8~12个以上，覆盖低b值密集与高b值稀疏），两个b值只能计算单指数ADC，无法分离灌注与扩散成分。", "tr": "ADC与IVIM的D并不等同：常规ADC（含低b值时）混入了灌注贡献而被系统性高估，这正是IVIM要分离的部分。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-0115", "t": "单选题", "s": "关于MR分子成像的基本概念，下列说法正确的是", "o": {"A": "在活体内以分子或细胞水平的特异性靶点为成像对象，常借助特异性分子探针（如靶向配体标记的超顺磁性氧化铁颗粒）实现，MR的空间分辨率高但检测灵敏度低于核医学方法", "B": "MR分子成像的检测灵敏度高于放射性核素示踪技术", "C": "MR分子成像不需要任何探针，仅靠常规序列即可实现", "D": "MR分子成像是常规增强扫描在分子水平的延伸，二者的对比机制相同", "E": "MR分子成像只能在离体标本上进行"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-015", "kp": "MR分子成像的概念与特点", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (2)MR分子成像", "ex": "【为什么对】A正确。分子影像学指在活体状态下对细胞与分子水平的生物学过程进行可视化与定量；MR分子成像多依赖靶向探针（超顺磁性氧化铁、钆基靶向螯合物、CEST类探针等）改变局部弛豫或化学交换特性。其优势是高空间分辨率与优良软组织对比，短板是探针浓度检测灵敏度较低。【为什么错】B错误：核素示踪的灵敏度可达皮摩尔至纳摩尔量级，远高于MR的微摩尔至毫摩尔量级，这是MR分子成像的固有局限。C错误：绝大多数MR分子成像需要特异性探针，仅少数内源性对比机制（如CEST、波谱）属例外。D错误：常规增强使用非特异性细胞外间隙对比剂，反映的是血流与通透性，不具备分子靶向性。E错误：分子影像的定义前提正是「活体」成像。", "tr": "牢记各模态的分工：核素灵敏度最高但分辨率低，MR分辨率高但灵敏度低，二者互补构成了一体化多模态成像的动因。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0116", "t": "多选题", "s": "关于MR分子成像常用的探针与对比机制，下列说法正确的是", "o": {"A": "超顺磁性氧化铁颗粒主要缩短T2/T2*，在相应序列上表现为信号减低（阴性对比）", "B": "钆基探针主要缩短T1，表现为T1加权像上的信号升高（阳性对比）", "C": "CEST类探针可通过化学交换机制实现无金属的对比增强，并具备一定的pH或代谢物敏感性", "D": "氟-19（¹⁹F）成像因体内背景信号极低，标记物所在区域具有很高的特异性，但需专用射频链与线圈", "E": "目前MR分子探针大多已进入临床常规诊断项目，普及程度与常规增强相当"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-016", "kp": "MR分子探针的类型与对比机制", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (2)MR分子成像", "ex": "【为什么对】A正确：超顺磁性氧化铁产生显著的局部磁场不均匀，主导T2与T2*缩短，形成信号丢失的阴性对比，曾用于肝网状内皮系统与淋巴结成像及细胞标记示踪。B正确：钆的未成对电子缩短T1，为经典阳性对比机制。C正确：CEST探针（含糖类、氨基酸类）无需金属离子即可产生可调频率的对比，并可反映pH与代谢信息。D正确：人体内¹⁹F背景几乎为零，标记细胞或药物的¹⁹F信号具有「有即为真」的特异性，但需要相应频率的发射接收链路与专用线圈。【为什么错】E错误：多数分子探针仍处于临床前或早期临床研究阶段，尚未成为常规诊断项目，把研究性技术描述为已广泛临床使用属超范围表述。", "tr": "阴性对比（T2/T2*缩短，变黑）与阳性对比（T1缩短，变亮）的机制区分是必考点；此外应注意研究阶段技术与临床常规技术的边界。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-0117", "t": "单选题", "s": "关于心肌T1 mapping与T2 mapping的临床意义，下列说法正确的是", "o": {"A": "初始（native）T1升高多见于心肌水肿、淀粉样变与弥漫性纤维化，T1降低见于脂肪浸润与铁过载；T2升高主要反映心肌水肿与炎症", "B": "T1 mapping必须注射钆对比剂才能获得，无法进行平扫定量", "C": "T2 mapping主要用于评价心肌纤维化程度，与水肿无关", "D": "细胞外容积分数（ECV）仅由增强后T1值计算，不需要平扫T1与血细胞比容", "E": "T1、T2定量数值在不同厂家、不同场强与不同序列间可以直接互相比较"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-017", "kp": "心肌T1/T2 mapping的临床意义", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】A正确。初始T1是无对比剂的平扫定量指标：水肿、淀粉样变、弥漫性间质纤维化使T1延长；脂肪浸润（如Anderson-Fabry病的鞘糖脂沉积）与铁过载使T1缩短。T2值主要对自由水敏感，升高提示水肿或急性炎症，是心肌炎与急性心肌梗死的重要指标。【为什么错】B错误：初始T1 mapping在平扫下即可完成，正是其相对延迟强化的优势之一（延迟强化依赖对比剂且需正常心肌作参照，对弥漫病变不敏感）。C错误：纤维化评价主要依赖ECV与延迟强化，T2主要反映水肿。D错误：ECV需由平扫与增强后的心肌与血池T1值以及血细胞比容共同计算。E错误：mapping数值受场强、序列（MOLLI、ShMOLLI、SASHA等）、心率与后处理影响显著，各中心需建立本机正常参考值，不能跨平台直接比较。", "tr": "定量mapping的核心纪律是「本机本序列建立参考值」。同一患者随访必须使用相同场强、相同序列与相同后处理，否则数值不可比。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0118", "t": "案例分析题", "s": "患者男性，24岁，重型β地中海贫血，自幼规律输血治疗，近年血清铁蛋白持续高于2500μg/L，近3个月出现活动后心悸、乏力。临床需要评估其心脏与肝脏的铁沉积程度，以指导祛铁药物剂量调整与疗效随访。所在科室有1.5T与3.0T两台MR设备，均配备多回波定量序列与心电门控。技师需要为其安排铁定量检查方案。下列判断中错误的是", "o": {"A": "心肌铁定量的公认方法是采用多回波梯度回波序列测量室间隔中段短轴的T2*值，T2*小于20ms提示心肌铁过载，小于10ms提示重度铁过载与心力衰竭高风险", "B": "铁的顺磁性作用使局部磁场不均匀、加速质子失相位，因此铁沉积越重T2*值越短、信号衰减越快", "C": "在1.5T与3.0T上测得的T2*绝对值不同，3.0T的T2*值更短，阈值须按对应场强的标准判读，临床更倾向在1.5T进行铁定量", "D": "肝脏铁定量可采用多回波序列测量T2*或R2*，并结合已发表的换算关系估算肝铁浓度", "E": "为提高信噪比，心肌T2*测量应选用长回波链的自旋回波序列，因其对磁化率变化更敏感"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-018", "kp": "T2*铁定量与心肌铁过载评估", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】E错误，为应选项。自旋回波的180度重聚脉冲恰恰消除了静态磁场不均匀引起的失相位，测得的是T2而非T2*，对磁化率变化不敏感；铁定量必须使用无重聚脉冲的多回波梯度回波序列（测T2*或其倒数R2*），一次屏气采集多个递增回波时间的图像并做指数拟合。【为什么错】A正确：室间隔中段短轴层面的心肌T2*是国际公认的心脏铁定量部位与方法，20ms与10ms为经典分界。B正确：铁的顺磁性造成局部磁场梯度、加速横向失相位，铁越多T2*越短。C正确：场强越高磁化率效应越强、T2*越短，阈值不可跨场强套用，且3.0T下重度铁过载者信号衰减过快、拟合困难，故临床铁定量以1.5T为优选。D正确：肝脏R2*与肝铁浓度存在良好相关性，是常规无创评估手段。", "tr": "T2*（梯度回波，含静态场不均匀）与T2（自旋回波，已重聚）的区别是铁定量的核心。凡涉及磁化率相关定量（铁、出血、SWI），一律使用梯度回波。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0119", "t": "单选题", "s": "关于磁共振质子密度脂肪分数（MR-PDFF）测量肝脏脂肪含量，下列说法正确的是", "o": {"A": "采用多回波化学位移编码的梯度回波序列，通过校正T1偏倚、T2*衰减与脂肪多峰波谱模型，得到接近真值的脂肪信号占比，是无创定量肝脂肪的参考方法之一", "B": "只需采集同相位与反相位两个回波，用信号下降百分比即可获得准确的脂肪分数", "C": "PDFF的结果不受肝脏铁沉积的影响", "D": "PDFF只能在1.5T设备上测量", "E": "PDFF数值与肝活检脂肪变性分级一一对应，两者可直接互换使用"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-019", "kp": "MR-PDFF肝脂肪定量", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】A正确。PDFF采用低翻转角多回波化学位移编码梯度回波（如mDIXON Quant、IDEAL-IQ类实现），通过小翻转角抑制T1偏倚、多回波拟合校正T2*、采用脂肪多峰模型校正谱峰分布，最终给出脂肪信号占总质子信号的比例，具有良好的准确性与跨平台重复性。【为什么错】B错误：两点法同反相位仅能定性或粗略半定量，未校正T1偏倚、T2*与脂肪多峰，且在脂肪分数超过50%时存在水脂互换的模糊性。C错误：铁沉积造成T2*显著缩短，若不做T2*校正会明显影响脂肪分数估计，这正是PDFF必须多回波拟合的原因之一。D错误：1.5T与3.0T均可测量，参数需按场强调整。E错误：PDFF是连续的定量指标，与病理分级为相关关系而非等价，二者判读标准不同。", "tr": "同反相位法与PDFF的差别是「半定量」与「定量」之分。此外要记住：同反相位在脂肪分数超过50%时无法区分「脂肪为主」与「水为主」，PDFF通过多回波与相位信息解决了这一模糊性。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0120", "t": "多选题", "s": "关于磁共振弹性成像（MRE）评估肝纤维化，下列说法正确的是", "o": {"A": "通过体表驱动器向肝脏施加低频机械振动（常用60Hz），用运动敏感梯度编码剪切波的传播，反演计算组织硬度并生成弹性图", "B": "肝硬度随纤维化分期升高，MRE对进展期纤维化与肝硬化的诊断效能良好，且不受肥胖与腹水的明显限制", "C": "严重肝铁沉积会造成信号显著衰减，可导致MRE波形图质量差、测量失败", "D": "炎症活动、胆汁淤积、肝静脉淤血与餐后状态均可使肝硬度升高，判读时应结合临床并要求患者空腹", "E": "MRE与超声弹性成像测得的硬度数值单位一致且阈值通用，可直接互换判读"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-020", "kp": "磁共振弹性成像与肝纤维化评估", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】A正确：MRE由被动驱动器传递低频剪切波，序列以运动编码梯度记录波的相位，经反演算法得到以kPa表示的硬度图。B正确：与超声瞬时弹性成像相比，MRE受体型、肋间声窗与腹水影响小，采样体积大、失败率低。C正确：显著铁沉积使T2*极短、梯度回波信号快速衰减，是MRE失败的常见原因，此时可改用自旋回波EPI类MRE序列。D正确：肝硬度是「纤维化＋炎症＋淤血＋灌注状态」的综合表现，急性肝炎、右心衰竭、胆道梗阻与餐后门静脉血流增加均可致假性升高，故要求空腹并结合临床。【为什么错】E错误：MRE与超声弹性成像的激励频率、测量原理与报告量（剪切模量与杨氏模量）不同，数值与阈值不可直接互换。", "tr": "肝硬度升高不等于纤维化：炎症、淤血、淤胆、进食都会抬高读数。跨模态的硬度数值不能互换，这两点是MRE判读的高频陷阱。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-0121", "t": "单选题", "s": "背景抑制全身扩散加权成像（DWIBS）之所以被称为「类PET」成像，其主要依据是", "o": {"A": "采用短反转时间反转恢复脂肪抑制配合自由呼吸多段扩散加权采集，抑制背景肌肉、脂肪与血流信号后，以反转灰阶显示高信号病灶，形成类似PET的全身黑白图像，可反映病变的细胞密度", "B": "它使用了放射性示踪剂，因此能反映代谢活性", "C": "它测量的是组织的葡萄糖代谢率", "D": "它必须在屏气状态下逐段采集才能完成全身覆盖", "E": "它的病灶检出特异性高于PET，可直接替代PET/CT用于肿瘤分期"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-021", "kp": "DWIBS全身类PET成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】A正确。DWIBS以短反转时间反转恢复（STIR）实现均匀脂肪抑制，配合自由呼吸下的多次激励平均与分段采集，抑制背景组织信号；将扩散加权图像做反转灰阶显示后，高细胞密度、扩散受限的病灶呈现为深色高信号灶，整体观感与PET的最大密度投影相似，故称「类PET」。【为什么错】B错误：DWIBS无放射性示踪剂，无电离辐射，这正是其相对PET的优势。C错误：反映的是水分子扩散受限程度（与细胞密度、细胞膜完整性相关），不是葡萄糖代谢。D错误：DWIBS的特点恰是自由呼吸采集，靠多次平均消除呼吸运动影响，屏气反而不适用于长时间全身采集。E错误：DWIBS存在较多假阳性（淋巴组织、脾脏、肠道、神经、炎症与脓肿均可扩散受限）与假阴性（部分低细胞密度或囊性病变），不能直接替代PET/CT，二者为互补关系。", "tr": "扩散受限≠恶性。正常淋巴结、脾、睾丸、脑组织、脓肿与亚急性血肿均可呈高信号，DWIBS必须结合形态学序列与ADC值综合判读。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0122", "t": "案例分析题", "s": "某三级医院拟开展MR引导下的介入操作，初期计划涵盖肝脏、前列腺病灶的穿刺活检以及部分肿瘤的消融治疗，需要对设备条件、器械准入与操作流程进行论证。现有设备为封闭式3.0T诊断用MR，孔径60cm，磁体间已按标准划分安全分区并设置门禁与铁磁探测。作为科室技术骨干参与本次论证并负责起草流程草案，下列判断中错误的是", "o": {"A": "MR引导介入的优势在于软组织对比优异、可多平面任意角度成像、无电离辐射，并可利用温度敏感序列监测消融过程中的温度变化", "B": "必须使用MR兼容（非铁磁、低磁化率）的穿刺针与器械，且需评估其在图像上产生的磁化率伪影大小", "C": "封闭式诊断磁体的孔径与可及性限制明显，实施介入通常需要把患者移出孔外操作、再移入扫描确认，或考虑宽孔径与开放式介入专用设备", "D": "监护设备、麻醉机、输液泵等必须为MR兼容型号，所有进入磁体间的物品都需经过铁磁性筛查", "E": "只要穿刺针标注为不锈钢材质，即可安全用于MR引导穿刺，无需查阅其MR兼容性标识"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-022", "kp": "MR引导介入的设备与器械要求", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】E错误，为应选项。不锈钢是一大类合金，其中马氏体与铁素体不锈钢具有明显铁磁性，属绝对禁用；仅部分奥氏体不锈钢弱磁。器械能否进入磁体间必须依据其MR安全性标识（MR Safe／MR Conditional／MR Unsafe）及厂家说明书规定的场强、梯度与SAR条件，不能凭材质名称推断。【为什么错】A正确：软组织对比、任意平面与无辐射是MR引导的核心优势，质子共振频率法温度成像可实现消融的近实时测温。B正确：钛合金、镍钛合金与特定非磁性合金制成的专用器械可减小磁化率伪影，同时需了解针体伪影会大于其实际直径。C正确：封闭式诊断磁体可及性差，常采用「移出—操作—移入—确认」的分步流程，条件允许时应选用宽孔径或介入专用平台。D正确：磁体间内一切设备与物品均需经铁磁筛查并使用兼容型号，防止投射效应造成严重事故。", "tr": "MR安全标识三分法必须牢记：MR Safe（完全无风险）、MR Conditional（特定条件下安全，须逐条核对）、MR Unsafe（禁入）。凭材质名称或既往经验判断是重大安全隐患。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0123", "t": "单选题", "s": "磁共振引导聚焦超声（MRgFUS）治疗的基本原理是", "o": {"A": "用相控阵换能器将超声能量聚焦于体内靶点产生热凝固（或机械效应），同时由MR提供靶点定位与实时温度监测和治疗反馈，实现无切口治疗", "B": "用MR的射频脉冲直接加热靶组织", "C": "用超声换能器发射X线进行照射治疗", "D": "在MR引导下经皮置入电极进行射频消融", "E": "利用梯度磁场的机械振动破坏靶组织"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-023", "kp": "MRgFUS的原理与应用", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】A正确。MRgFUS由体外相控阵换能器将超声束会聚于体内毫米级焦点，焦域温度可升至60℃以上造成蛋白变性与凝固性坏死；MR负责术前靶点规划、术中基于质子共振频率的实时测温与热剂量计算、术后即刻评价，形成「治疗—监测」闭环。临床已用于子宫肌瘤、骨转移瘤镇痛及震颤等功能神经外科适应证。【为什么错】B错误：MR射频脉冲的能量沉积（SAR）是需要限制的副效应，不能作为治疗性加热手段。C错误：超声换能器不产生X线，二者物理本质完全不同。D错误：这是MR引导下射频消融，属另一类介入方式，需经皮置入电极。E错误：梯度振动只产生噪声与周围神经刺激，不具备热毁损能力。", "tr": "MRgFUS的关键词是「无创（无切口）＋实时测温」。MR在其中承担的是导航与监测角色，能量来自超声而非MR本身。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-0124", "t": "案例分析题", "s": "某肿瘤中心引进磁共振引导直线加速器（MR-Linac），拟用于前列腺癌与肝转移瘤的自适应放射治疗，计划在每次治疗前后及治疗中采集MR图像用于靶区定位与在线计划调整。放疗科邀请影像技术团队参与论证，评估该系统在影像技术层面的特点、质量控制要求与主要挑战，并协助制定几何精度检测方案。作为参与论证的影像技术骨干，下列分析中错误的是", "o": {"A": "MR-Linac将MR成像与直线加速器整合，可在治疗过程中获得优良软组织对比的实时或近实时影像，用于靶区与危及器官的在线定位与自适应计划调整", "B": "MR成像不引入额外电离辐射，相比锥形束CT引导更有利于减少影像引导本身的剂量负担", "C": "静磁场会使次级电子发生洛伦兹力偏转，在组织—空气界面产生电子回旋效应，剂量计算必须考虑磁场影响", "D": "MR图像的几何精度受梯度非线性与磁化率相关变形影响，必须做几何畸变校正与严格的质量控制", "E": "MR图像的灰度值可直接作为电子密度用于剂量计算，无需CT或合成CT信息"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-024", "kp": "MR-Linac的影像技术特点与挑战", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】E错误，为应选项。MR信号强度反映的是质子密度与弛豫特性，与组织的电子密度之间没有直接对应关系，无法直接用于剂量计算；实际工作流依赖配准的定位CT，或由MR图像经算法生成「合成CT／伪CT」提供电子密度信息。【为什么错】A正确：软组织对比优异使前列腺、肝脏等靶区的在线勾画与自适应调整成为可能。B正确：与每日锥形束CT相比，MR引导不增加成像相关电离辐射。C正确：磁场中次级电子受洛伦兹力偏转，在组织—空气界面出现电子回旋效应导致剂量分布改变，须在计划系统中建模。D正确：几何保真度是影像引导放疗的生命线，梯度非线性与磁化率变形必须定期用体模检测与校正。", "tr": "MR「不含电子密度信息」是MR用于放疗计划的根本瓶颈，解决方案是合成CT。把MR信号强度当作密度信息使用，是概念性错误。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": true, "src": "模拟", "mk": 0}, {"id": "U17-1001", "t": "单选题", "s": "BOLD-fMRI成像的生理基础是", "o": {"A": "脱氧血红蛋白浓度变化引起局部T2*信号改变", "B": "对比剂增强效应", "C": "质子密度变化", "D": "呼吸运动", "E": "磁场漂移"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-101", "kp": "BOLD-fMRI原理", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】BOLD（血氧水平依赖）成像利用脱氧血红蛋白的顺磁性，神经活动时局部血流增加、脱氧血红蛋白相对减少，引起T2*信号变化，从而定位脑功能，故A正确。\n【为什么错】B：BOLD无需外源性对比剂。C：信号基础是磁敏感变化而非质子密度。D：呼吸运动是伪影来源而非成像基础。E：磁场漂移属设备误差，均错误。", "tr": "BOLD的信号源是“内源性脱氧血红蛋白”，不是外源性对比剂。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1002", "t": "单选题", "s": "急性脑梗死DWI的典型表现是", "o": {"A": "梗死区DWI高信号、ADC值降低", "B": "梗死区DWI低信号、ADC值升高", "C": "DWI与ADC均无变化", "D": "梗死区DWI低信号、ADC降低", "E": "梗死区DWI高信号、ADC升高"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-102", "kp": "DWI在脑梗死中的应用", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】急性期细胞毒性水肿使水分子扩散受限，DWI呈高信号，表观扩散系数ADC下降，故A正确。\n【为什么错】B：扩散受限时ADC降低而非升高。C：急性梗死必然出现DWI/ADC改变。D：扩散受限时DWI应为高信号。E：ADC升高代表扩散加快，与梗死不符。", "tr": "“DWI高信号+ADC低”是扩散受限的铁三角，两者方向相反。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1003", "t": "单选题", "s": "扩散张量成像（DTI）中最常用于评估白质纤维完整性的参数是", "o": {"A": "各向异性分数（FA）", "B": "质子密度", "C": "T2弛豫时间", "D": "血氧饱和度", "E": "对比剂浓度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-103", "kp": "DTI参数与纤维示踪", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DTI通过测量水分子扩散的各向异性，以FA值反映白质纤维方向性与完整性，并可进行纤维束示踪，故A正确。\n【为什么错】B：质子密度是常规加权成像基础。C：T2时间是弛豫参数。D：血氧饱和度与BOLD相关。E：对比剂浓度与灌注相关，均非DTI纤维评估参数。", "tr": "DTI关键词是“FA与纤维示踪”，与T1/T2、BOLD、灌注参数区分。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1004", "t": "单选题", "s": "1H-MRS中代表神经元活性的主要代谢物是", "o": {"A": "N-乙酰天门冬氨酸（NAA）", "B": "胆碱（Cho）", "C": "肌酸（Cr）", "D": "乳酸（Lac）", "E": "脂质（Lip）"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-104", "kp": "MRS代谢物", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】NAA主要存在于神经元内，是神经元数量与活性的标志，神经元损伤时NAA降低，故A正确。\n【为什么错】B：Cho反映膜代谢，肿瘤时升高。C：Cr为能量储备标志。D：Lac在缺血时升高。E：Lip见于坏死与肿瘤，均非神经元特异性标志。", "tr": "NAA=神经元、Cho=膜代谢、Cr=能量、Lac=缺血，四个代谢物各自对应。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1005", "t": "单选题", "s": "颅内肿瘤MRS的典型代谢特征是", "o": {"A": "NAA降低、Cho升高", "B": "NAA升高、Cho降低", "C": "NAA与Cho均升高", "D": "NAA与Cho均降低", "E": "Lac升高而NAA正常"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-105", "kp": "肿瘤MRS表现", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】肿瘤破坏神经元使NAA下降，细胞增殖活跃使膜代谢产物Cho升高，故A正确。\n【为什么错】B：肿瘤不出现NAA升高、Cho降低。C：NAA不会随肿瘤升高。D：Cho在肿瘤中通常升高而非降低。E：肿瘤常伴Lac升高，但NAA会降低而非正常。", "tr": "肿瘤MRS三联征：NAA↓、Cho↑，可伴Lac↑。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1006", "t": "单选题", "s": "MRS中乳酸（Lac）峰在长TE条件下（如TE=135ms）的典型表现是", "o": {"A": "峰发生倒置（倒挂）", "B": "峰消失", "C": "峰明显升高", "D": "峰位置迁移", "E": "峰与NAA重叠"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-106", "kp": "Lac峰TE调制", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】乳酸为J耦合多峰，在长TE（135ms或144ms）下因相位演化出现上下倒置的双峰，利用此特征可鉴别Lac峰，故A正确。\n【为什么错】B：长TE时Lac仍可见且倒置，并不消失。C：长TE不使Lac升高。D：峰位置（化学位移）不变。E：Lac在1.3ppm，与NAA（2.0ppm）不重叠。", "tr": "“长TE见倒置Lac”是MRS鉴峰的经典技巧。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1007", "t": "单选题", "s": "动态磁敏感对比灌注成像（DSC-PWI）利用的对比剂效应是", "o": {"A": "首过期间对比剂引起T2*/T2信号下降", "B": "对比剂引起T1信号升高", "C": "对比剂引起质子密度增加", "D": "对比剂引起磁化转移", "E": "对比剂引起射频漂移"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-107", "kp": "DSC-PWI原理", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DSC以T2*/T2加权序列连续采集，对比剂首过期间在组织内造成局部磁敏感变化，使信号下降，据此计算灌注参数，故A正确。\n【为什么错】B：以T1信号升高反映渗透性的是DCE-PWI。C：质子密度增加与对比剂首过无关。D：磁化转移是另一类对比机制。E：射频漂移是设备现象，均与DSC原理不符。", "tr": "DSC（T2*信号下降）与DCE（T1信号增强）是两种不同的灌注原理。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1008", "t": "单选题", "s": "动脉自旋标记（ASL）灌注成像的突出优点是", "o": {"A": "无需注射外源性对比剂", "B": "需要大量对比剂", "C": "只能用于肝脏", "D": "必须屏气", "E": "不显示灌注信息"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-108", "kp": "ASL灌注成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】ASL以射频脉冲对流入动脉血进行磁性标记，利用内源性水分子作为示踪剂，无需外源性对比剂，可反复测量，故A正确。\n【为什么错】B：ASL恰恰不使用对比剂。C：ASL可应用于脑、肾、肺等多部位。D：ASL不强制屏气。E：ASL就是灌注成像，显示组织灌注。", "tr": "ASL是“无对比剂灌注”的代名词，与DSC/DCE形成对比。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1009", "t": "单选题", "s": "MR灌注成像常用的灌注参数不包括", "o": {"A": "脑血容量（CBV）", "B": "脑血流量（CBF）", "C": "平均通过时间（MTT）", "D": "达峰时间（TTP）", "E": "表观扩散系数（ADC）"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-109", "kp": "灌注参数", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】CBV、CBF、MTT、TTP均为MR灌注成像的常用参数，ADC是扩散加权成像（DWI）的参数，不属于灌注参数，故E正确。\n【为什么错】A：CBV（脑血容量）为灌注参数。B：CBF（脑血流量）为灌注参数。C：MTT（平均通过时间）为灌注参数。D：TTP（达峰时间）为灌注参数，均属于灌注参数故不符合题意。", "tr": "灌注看“CBV/CBF/MTT/TTP”，扩散看“ADC”，分属不同功能成像。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1010", "t": "单选题", "s": "7T超高场MR相对于常规场强的主要优势是", "o": {"A": "信噪比（SNR）更高", "B": "B1场更均匀", "C": "SAR更低", "D": "化学位移更小", "E": "磁化率伪影更小"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-110", "kp": "超高场MR优势与挑战", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】信号强度随场强增高而增大，7T可提供显著高于3T及以下的信噪比，利于高分辨率成像，故A正确。\n【为什么错】B：高场射频波长缩短，B1均匀性变差。C：SAR随场强增高而增大。D：化学位移随场强增大而增大。E：磁化率效应在高场更明显，均非优势。", "tr": "高场“高SNR”与“高SAR、B1不均匀、化学位移大、磁化率伪影多”并存。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1011", "t": "单选题", "s": "MR并行采集技术（如SENSE、GRAPPA）的主要作用是", "o": {"A": "利用多通道线圈并行采集加速扫描", "B": "提高静磁场强度", "C": "增加对比剂用量", "D": "降低梯度切换率", "E": "增大扫描层厚"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-111", "kp": "并行成像", "ch": "十七、MR技术的进展 → 1.MR设备 → (4)软件系统", "ex": "【为什么对】并行采集利用相控阵线圈各单元空间敏感度差异，减少k空间采样线数，缩短扫描时间，故A正确。\n【为什么错】B：场强由磁体决定。C：并行成像不涉及对比剂。D：梯度切换率是梯度系统参数。E：层厚是扫描参数，均与加速原理无关。", "tr": "并行成像=多线圈空间编码+扫描加速，核心价值是缩短时间。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1012", "t": "单选题", "s": "压缩感知（CS）技术加速MR扫描的原理是", "o": {"A": "对稀疏k空间数据进行欠采样后通过算法迭代重建", "B": "增加采样线数", "C": "提高TR时间", "D": "增大翻转角", "E": "延长TE时间"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-112", "kp": "压缩感知", "ch": "十七、MR技术的进展 → 1.MR设备 → (4)软件系统", "ex": "【为什么对】压缩感知利用图像在变换域（如小波）的稀疏性，随机欠采样k空间，再经非线性迭代重建恢复图像，从而加速扫描，故A正确。\n【为什么错】B：CS是减少而非增加采样线数。C：提高TR延长扫描时间，与加速相反。D：增大翻转角不影响采样密度。E：延长TE不构成CS加速原理。", "tr": "CS三要素：稀疏性+欠采样+迭代重建。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1013", "t": "单选题", "s": "磁共振指纹（MR Fingerprinting）技术的特点是", "o": {"A": "一次采集即可同时获得T1、T2等多参数定量图", "B": "只能获得T2图", "C": "需要注射对比剂", "D": "只能用于心脏", "E": "不进行定量分析"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-113", "kp": "MR指纹", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】MRF通过伪随机变化的序列参数采集独特信号“指纹”，与预存字典匹配，一次扫描同步重建T1、T2等多张定量图，故A正确。\n【为什么错】B：MRF同时提供多参数。C：MRF无需对比剂。D：MRF可用于颅脑、心脏等多部位。E：MRF正是定量分析技术，均错误。", "tr": "MRF的标签是“一次扫描、多参数定量”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1014", "t": "单选题", "s": "T1 mapping、T2 mapping等定量弛豫成像的临床意义是", "o": {"A": "以量化数值评估组织成分变化（如纤维化、水肿）", "B": "只能改善图像对比", "C": "仅用于血管造影", "D": "替代活检组织学", "E": "降低图像分辨率"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-114", "kp": "定量弛豫成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】定量mapping给出像素级T1、T2数值，可客观反映心肌纤维化、肝脏铁沉积、软骨退变等组织学变化，故A正确。\n【为什么错】B：其价值是定量而非仅对比改善。C：mapping不限于血管。D：定量数值不能完全替代病理活检。E：mapping不降低分辨率。", "tr": "定量mapping把“灰度对比”变为“数值诊断”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1015", "t": "单选题", "s": "全身类PET成像（如DWIBS）的主要临床应用是", "o": {"A": "全身肿瘤筛查、分期与转移灶评估", "B": "测量骨密度", "C": "评估心脏瓣膜", "D": "显示胆道结石", "E": "测量眼压"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-115", "kp": "全身类PET成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】DWIBS等全身扩散加权成像利用肿瘤细胞致密、扩散受限而高信号的特点，背景抑制后类似PET显像，用于全身肿瘤筛查与分期，故A正确。\n【为什么错】B：骨密度用DXA。C：心脏瓣膜用超声/心脏MR。D：胆道结石用MRCP。E：眼压与MR无关，均错误。", "tr": "类PET成像的本质是“全身DWI”，无辐射是其最大优势。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1016", "t": "单选题", "s": "MR分子成像的核心概念是", "o": {"A": "用靶向探针在分子水平检测疾病相关的生物学过程", "B": "提高常规扫描速度", "C": "减少对比剂反应", "D": "改进患者舒适度", "E": "降低磁场强度"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-116", "kp": "MR分子成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (2)MR分子成像", "ex": "【为什么对】MR分子成像借助靶向性对比剂、分子探针或报告基因，在分子与细胞水平特异显示生物过程（如受体表达、细胞凋亡、基因表达），故A正确。\n【为什么错】B：提高常规扫描速度属加速技术。C：减少对比剂反应属安全性优化。D：改进患者舒适度属人文服务。E：降低磁场强度属设备设计，均非分子成像的核心内涵。", "tr": "分子成像的关键词是“靶向探针+分子水平特异检测”。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1017", "t": "单选题", "s": "超高场（3T及以上）B1场不均匀性的常用改善措施是", "o": {"A": "多通道并行发射（并行射频发射）", "B": "降低梯度场强", "C": "增加扫描层厚", "D": "减少接收线圈", "E": "延长重复时间"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-117", "kp": "高场B1均匀性", "ch": "十七、MR技术的进展 → 1.MR设备 → (3)射频系统", "ex": "【为什么对】高场射频波长变短，B1场不均匀，多通道并行发射可分别调控各通道射频幅度与相位，改善B1均匀性与SAR分布，故A正确。\n【为什么错】B：梯度场强不影响B1均匀性。C：层厚是扫描参数。D：减少线圈降低信噪比。E：TR影响对比与时间，均不能改善B1均匀性。", "tr": "B1不均匀→并行发射/介电填充垫；SAR高→限制翻转角与序列。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1018", "t": "单选题", "s": "MRI引导下介入治疗（如MRgFUS）中用于实时监测组织温度的常用技术是", "o": {"A": "质子共振频率（PRF）测温法", "B": "常规T2WI测量", "C": "MRA血管成像", "D": "MR波谱定量", "E": "对比增强扫描"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-118", "kp": "MRI介入温度监测", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】PRF测温利用水分子共振频率随温度变化的特性，以相位图实时反映组织温度变化，是无创测温的主流方法，故A正确。\n【为什么错】B：T2WI只能间接反映热损伤。C：MRA显示血管。D：波谱用于代谢物。E：增强反映灌注，均非温度监测手段。", "tr": "MR温度监测的核心是PRF（质子共振频率位移）法。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1019", "t": "多选题", "s": "MR功能成像技术包括", "o": {"A": "BOLD-fMRI", "B": "扩散加权成像（DWI）", "C": "扩散张量成像（DTI）", "D": "灌注成像（PWI）", "E": "CT灌注成像"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-119", "kp": "MR功能成像范畴", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】BOLD、DWI、DTI、PWI等均属于MR功能成像的范畴，故A、B、C、D正确。\n【为什么错】E：CT灌注成像属于CT设备与技术的范畴，不属于MR功能成像技术。", "tr": "MR功能成像（BOLD、DWI、DTI、PWI、MRS）与CT灌注成像分属不同设备体系，注意别把CT技术混入MR选项。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1020", "t": "多选题", "s": "下列情况中DWI呈扩散受限（高信号）表现的有", "o": {"A": "急性脑梗死", "B": "富细胞性肿瘤", "C": "脓肿内稠厚脓液", "D": "蛛网膜囊肿", "E": "脑脊液"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-120", "kp": "DWI扩散受限表现", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】急性梗死细胞毒性水肿、富细胞肿瘤、脓肿脓液均为扩散受限，DWI高信号，故A、B、C正确。\n【为什么错】D：蛛网膜囊肿为纯液体，扩散不受限。E：脑脊液扩散自由，呈低信号，均非扩散受限。", "tr": "“细胞密集+黏稠”是扩散受限的本质，自由液体不受限。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1021", "t": "多选题", "s": "关于MRS代谢物及其临床意义，正确的对应关系包括", "o": {"A": "NAA降低提示神经元损伤", "B": "Cho升高提示细胞膜代谢活跃（肿瘤等）", "C": "Cr相对稳定常作为参考峰", "D": "Lac升高提示无氧代谢（缺血等）", "E": "NAA升高提示肿瘤"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-121", "kp": "MRS代谢物意义", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】NAA降低=神经元损伤，Cho升高=膜代谢活跃，Cr为稳定参考，Lac升高=无氧代谢，故A、B、C、D正确。\n【为什么错】E：肿瘤时NAA降低而非升高。", "tr": "NAA与Cho方向相反（NAA↓、Cho↑）是肿瘤MRS的要点。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1022", "t": "多选题", "s": "MR灌注成像的技术类型包括", "o": {"A": "动态磁敏感对比（DSC）", "B": "动态对比增强（DCE）", "C": "动脉自旋标记（ASL）", "D": "扩散加权成像（DWI）", "E": "MRA血管成像"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-122", "kp": "PWI技术类型", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DSC（T2*首过）、DCE（T1渗透性）、ASL（内源性标记）为MR灌注三大技术，故A、B、C正确。\n【为什么错】D：DWI是扩散成像，非灌注。E：MRA是血管成像，非灌注。", "tr": "灌注（PWI）与扩散（DWI）、血管成像（MRA）是三个不同范畴。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1023", "t": "多选题", "s": "全身类PET成像（DWIBS）的适应证包括", "o": {"A": "肿瘤TNM分期", "B": "淋巴瘤全身评估", "C": "转移灶筛查", "D": "放化疗疗效随访", "E": "冠状动脉狭窄评估"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-123", "kp": "类PET适应证", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】全身DWI用于肿瘤分期、淋巴瘤评估、转移筛查与疗效随访，故A、B、C、D正确。\n【为什么错】E：冠脉狭窄评估属心脏MR/CTA范畴，类PET全身DWI不用于冠脉评价。", "tr": "类PET服务“全身肿瘤学”，冠脉等专科评估不在其列。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1024", "t": "多选题", "s": "MRI定量分析技术包括", "o": {"A": "T1 mapping", "B": "T2 mapping", "C": "T2*/R2*铁定量", "D": "质子密度脂肪分数（PDFF）", "E": "常规SE序列定性T1WI"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-124", "kp": "MRI定量分析", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】T1/T2 mapping、T2*铁定量、PDFF脂肪定量均为定量MRI技术，故A、B、C、D正确。\n【为什么错】E：常规SE序列T1WI用于定性对比观察，输出的是灰度图像而非定量参数图，不属于定量分析技术。", "tr": "定量MRI的共性是把信号强度转化为可测量的组织学数值，常规定性序列不在其列。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1025", "t": "多选题", "s": "超高场（7T）MR面临的挑战包括", "o": {"A": "比吸收率（SAR）升高", "B": "B1场不均匀", "C": "化学位移增大", "D": "磁化率伪影加重", "E": "信噪比降低"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-125", "kp": "超高场挑战", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】高场下SAR升高、射频波长缩短致B1不均匀、化学位移与磁化率效应均增大，是7T的主要挑战，故A、B、C、D正确。\n【为什么错】E：7T的信噪比是升高的而非降低。", "tr": "7T“SNR升高”与“SAR/B1/化学位移/磁化率问题增多”并存。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1026", "t": "多选题", "s": "MR分子成像的探针与策略包括", "o": {"A": "超顺磁性氧化铁（SPIO/USPIO）颗粒", "B": "靶向性多肽或抗体偶联探针", "C": "报告基因成像", "D": "细胞示踪标记", "E": "常规钆剂全身增强"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-126", "kp": "MR分子探针", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (2)MR分子成像", "ex": "【为什么对】SPIO颗粒、靶向探针、报告基因与细胞示踪均为MR分子成像策略，故A、B、C、D正确。\n【为什么错】E：常规钆剂全身增强是传统临床增强检查，不属于分子成像探针范畴。", "tr": "分子成像强调“靶向、细胞/分子水平”，常规对比增强不属其列。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1027", "t": "多选题", "s": "关于MR梯度系统的性能参数，正确的说法包括", "o": {"A": "梯度场强决定成像空间分辨率与扩散/EPI能力", "B": "梯度切换率影响成像速度", "C": "高性能梯度是DWI、EPI等快速成像的基础", "D": "梯度场强与切换率越高对神经刺激风险越大", "E": "梯度系统与主磁场无关"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-127", "kp": "梯度系统性能", "ch": "十七、MR技术的进展 → 1.MR设备 → (2)梯度系统", "ex": "【为什么对】梯度场强影响空间分辨与扩散/EPI能力，切换率影响速度，高梯度是快速成像基础，高切换率有外周神经刺激风险，故A、B、C、D正确。\n【为什么错】E：梯度场与主磁场叠加工作、相互关联，说“与主磁场无关”错误。", "tr": "梯度性能“强则快、快则刺激风险高”，且须在主磁场框架下工作。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1028", "t": "多选题", "s": "MRI介入技术的应用包括", "o": {"A": "MRI引导经皮穿刺活检", "B": "MRgFUS聚焦超声消融（如子宫肌瘤）", "C": "介入手术实时温度监测", "D": "术前与术中导航", "E": "超声心动图检查"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-128", "kp": "MRI介入应用", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】MR引导活检、MRgFUS消融、实时温度监测与导航均为MRI介入技术应用，故A、B、C、D正确。\n【为什么错】E：超声心动图属超声设备检查，不属于MRI介入。", "tr": "MRI介入以“MR实时引导+无电离辐射”为特征，超声检查不混入。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 1}, {"id": "U17-1029a", "t": "共用题干题", "s": "对急性脑梗死最具诊断价值的首选序列是", "o": {"A": "扩散加权成像（DWI）", "B": "常规T1WI", "C": "T2加权脂肪抑制", "D": "MRCP水成像", "E": "SWI静脉成像"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-129", "kp": "急性脑梗死DWI检查", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DWI在缺血后数十分钟内即显示扩散受限高信号，是急性脑梗死最敏感的首选序列，故A正确。\n【为什么错】B：T1WI对急性梗死不敏感。C：脂肪抑制用于脂肪病变。D：MRCP用于胆道。E：SWI用于出血与静脉，均非急性梗死首选。", "tr": "“急性脑梗死→DWI高信号”是黄金诊断链。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1701", "gs": "患者男性，62岁，突发右侧肢体无力伴言语不清2小时来院，临床高度怀疑急性缺血性脑卒中，拟行急诊头颅MR检查明确梗死范围并评估治疗时机。技师负责序列选择与质控。"}, {"id": "U17-1029b", "t": "共用题干题", "s": "梗死区在DWI高信号的同时，其ADC值的变化是", "o": {"A": "ADC值降低", "B": "ADC值升高", "C": "ADC值不变", "D": "ADC值先升后降", "E": "ADC值无法测量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-130", "kp": "ADC变化", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】细胞毒性水肿使水分子扩散受限，表观扩散系数ADC降低，故A正确。\n【为什么错】B：ADC升高代表扩散加快。C：急性梗死必然出现ADC下降。D：演变期可能伪正常化，但急性期不出现先升后降。E：ADC可由多b值DWI计算，可测量。", "tr": "DWI信号与ADC方向相反：DWI高=ADC低，二者互为印证。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1701", "gs": ""}, {"id": "U17-1030a", "t": "共用题干题", "s": "肿瘤性病变MRS的典型代谢特征是", "o": {"A": "NAA降低、Cho升高", "B": "NAA升高、Cho降低", "C": "NAA与Cho均升高", "D": "NAA与Cho均降低", "E": "仅Lac升高"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-131", "kp": "肿瘤MRS特征", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】肿瘤破坏神经元使NAA降低，细胞增殖使Cho升高，故A正确。\n【为什么错】B：肿瘤不出现NAA升高、Cho降低。C：NAA不会随肿瘤升高。D：Cho在肿瘤中通常升高而非降低。E：肿瘤可伴Lac升高，但NAA同样降低，不是“仅Lac升高”。", "tr": "“NAA↓、Cho↑”是肿瘤MRS的核心组合。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1702", "gs": "患者女性，45岁，头痛伴肢体抽动1个月，头颅MR发现左侧额叶占位，临床拟行MR波谱（MRS）检查辅助肿瘤定性，并评估肿瘤与正常组织代谢差异。技师负责MRS参数与判读。"}, {"id": "U17-1030b", "t": "共用题干题", "s": "为更全面地显示短TE可见的多种代谢物，MRS宜选择的TE条件是", "o": {"A": "短TE（如30~35ms）", "B": "长TE（如135ms以上）", "C": "TE=0ms", "D": "TE=500ms", "E": "TE不相关"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-132", "kp": "MRS TE选择", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】短TE（30~35ms）可显示脂质、谷氨酸等短T2代谢物，代谢信息更全；长TE背景简化、便于观察倒置的Lac峰，故A正确。\n【为什么错】B：长TE会丢失部分短T2代谢物。C：TE=0无实际序列意义。D：TE=500ms过长，信号衰减严重。E：TE选择直接影响代谢物显示，不能说不相关。", "tr": "“看全代谢物→短TE；看Lac倒置→长TE”，两问应对应。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1702", "gs": ""}, {"id": "U17-1031a", "t": "共用题干题", "s": "全身类PET成像采用的核心序列是", "o": {"A": "全身背景抑制扩散加权成像（DWIBS）", "B": "头颅常规T2WI", "C": "腹部CT平扫", "D": "乳腺DBT", "E": "心脏电影序列"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-133", "kp": "类PET扫描序列", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】DWIBS以脂肪与背景信号抑制的全身DWI为技术基础，肿瘤等高细胞密度灶扩散受限呈高信号，效果类似PET，故A正确。\n【为什么错】B：T2WI无扩散信息。C：CT平扫非MR序列。D：DBT用于乳腺。E：心脏电影用于心功能，均不符合类PET技术。", "tr": "类PET=全身DWI（DWIBS），核心是扩散加权+背景抑制。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1703", "gs": "患者男性，58岁，锁骨上淋巴结肿大伴发热盗汗，临床疑淋巴瘤，拟行全身类PET成像（DWIBS）评估全身病变范围。技师负责扫描方案设计与图像判读。"}, {"id": "U17-1031b", "t": "共用题干题", "s": "类PET扫描中为突出扩散受限病灶、抑制背景信号，通常选用的b值是", "o": {"A": "b值较高（如800~1000s/mm²）", "B": "b值接近0", "C": "b=50s/mm²", "D": "b=100s/mm²", "E": "不使用b值"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-134", "kp": "类PET b值选择", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】较高b值（800~1000s/mm²）使扩散快的背景组织（脂肪、正常实质）信号明显衰减，而扩散受限的肿瘤灶保持高信号，对比度最佳，故A正确。\n【为什么错】B：b=0为T2加权，无扩散权重。C：b=50s/mm²扩散权重不足。D：b=100s/mm²同样偏低，背景抑制差。E：DWI必须设b值，不能不用。", "tr": "b值越高扩散权重越大、背景越黑、肿瘤灶越突出，但过高会降低信噪比。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0, "gid": "G1703", "gs": ""}, {"id": "U17-1032", "t": "案例分析题", "s": "患者男性，38岁，左侧额叶海绵状血管瘤拟行手术切除，病灶邻近左侧运动功能区。术前需要精确定位大脑皮层运动中枢与病灶的空间关系，以规划手术入路、保护运动功能。技师实施的功能成像方案中BOLD-fMRI以血氧水平依赖信号变化定位功能皮层，任务态设计可激活对应功能区并与解剖图像叠加。结果需与解剖图像配准后用于神经外科手术计划制定。最合适的是", "o": {"A": "BOLD-fMRI进行运动任务态功能定位", "B": "常规T2WI", "C": "MRCP水成像", "D": "腹部脂肪抑制", "E": "全身类PET"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-135", "kp": "BOLD术前功能定位", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】BOLD-fMRI通过运动任务激活对应皮层，在解剖图像上叠加功能激活区，可明确运动功能区与病灶的空间关系，故A正确。\n【为什么错】B：T2WI只显示病灶解剖。C：MRCP用于胆道。D：脂肪抑制与功能定位无关。E：类PET用于全身肿瘤，均不符合术前功能定位需求。", "tr": "术前功能定位用BOLD-fMRI（任务态或静息态）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1033", "t": "案例分析题", "s": "患者女性，50岁，右乳肿块，乳腺MRI增强检查拟行DCE灌注定量分析，评估病灶血流灌注与微血管渗透性，辅助良恶性鉴别及治疗前评估。技师在扫描与后处理中DCE灌注基于T1动态增强扫描与药代动力学模型，可计算Ktrans、Ve等反映微血管通透性的定量参数。定量结果受注射方案与模型选择影响，应保证采集条件一致。应重点获取的定量参数是", "o": {"A": "Ktrans（容积转移常数）等渗透性参数", "B": "ADC值", "C": "FA值", "D": "BOLD信号", "E": "PDFF脂肪分数"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-136", "kp": "DCE定量参数", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DCE灌注基于T1动态增强，通过药代动力学模型计算Ktrans、Ve等渗透性参数，反映微血管通透性，是乳腺病变评估的关键定量指标，故A正确。\n【为什么错】B：ADC是扩散参数。C：FA是DTI参数。D：BOLD是功能激活参数。E：PDFF是脂肪定量参数，均与DCE渗透性无关。", "tr": "DCE看Ktrans（渗透性），DSC看CBV/CBF（灌注量），参数别张冠李戴。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1034", "t": "案例分析题", "s": "某医院引进3.0T MR后，在腹部与盆腔扫描中发现部分患者图像出现亮暗不均、局部信号缺失，疑似高场射频相关伪影，影响诊断信心。技师分析原因并调整扫描方案。关于3T场强下图像不均匀的处理，高场射频波长缩短导致B1场不均匀，可采用多通道并行发射、B1匀场及介电填充等射频端手段改善。对于腹部等大视野部位，B1均匀性管理尤为重要。最有效的是", "o": {"A": "启用多通道并行发射或应用B1匀场与介电填充技术改善B1均匀性", "B": "降低磁场强度至0.5T", "C": "加大扫描层厚", "D": "减少序列重复时间", "E": "取消所有射频脉冲"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-137", "kp": "高场B1不均处理", "ch": "十七、MR技术的进展 → 1.MR设备 → (3)射频系统", "ex": "【为什么对】3T及以上射频波长缩短导致B1不均匀，多通道并行发射、B1匀场及介电填充可改善B1分布、减少信号不均，故A正确。\n【为什么错】B：降低场强不现实且牺牲SNR。C：层厚增大降低分辨率。D：TR与B1均匀性无关。E：取消射频无法成像，均错误。", "tr": "高场B1不均的对策是“射频端工程手段”，而非扫描参数或降场强。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1035", "t": "案例分析题", "s": "患者男性，40岁，地中海贫血，需评估心脏与肝脏铁过载程度以指导祛铁治疗。临床申请MRI铁定量检查，要求给出可量化的铁沉积指标并选择合适的测量部位。技师铁沉积使T2*/T2明显缩短，肝脏以R2*、心脏以T2*多回波测量评估铁过载程度并指导祛铁治疗。结果以mapping图与数值报告形式提供，供临床评估疗效。应选择的定量方法及测量部位是", "o": {"A": "肝脏R2*/T2* mapping，心脏T2*测量", "B": "颅脑MRS", "C": "膝关节T1 mapping", "D": "乳腺DCE", "E": "颈部MRA"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-138", "kp": "铁定量成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】铁沉积使T2*/T2缩短，肝脏以R2*、心脏以T2*（多回波）测量铁含量，是铁过载评估的定量方法，故A正确。\n【为什么错】B：MRS测代谢物。C：T1 mapping用于纤维化等。D：DCE用于灌注。E：MRA用于血管，均与铁定量无关。", "tr": "铁定量=肝脏R2*/心脏T2*，属于T2*家族。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1036", "t": "案例分析题", "s": "某科研中心拟开展MR指纹（MRF）研究，希望在一次扫描中同时获得T1、T2及质子密度等多参数定量图，用于组织特征表征与纵向随访。技师评估该技术时，MRF通过伪随机变化的序列参数采集独特信号指纹，与预存字典匹配后一次扫描可同时输出T1、T2、PD等多张定量图。其定量结果可用于不同时间点检查之间的纵向对比分析。正确的认识是", "o": {"A": "MRF一次采集经字典匹配同时输出多张定量图，无需对比剂", "B": "MRF只能输出T2图", "C": "MRF必须注射对比剂", "D": "MRF只适合心脏", "E": "MRF不能定量分析"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-139", "kp": "MR指纹特点", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】MRF以伪随机序列参数产生独特信号指纹，与预存字典匹配，一次扫描同步重建T1、T2、PD等多参数定量图，且无需对比剂，故A正确。\n【为什么错】B：MRF输出多参数。C：MRF无需对比剂。D：MRF适用于脑、心等多部位。E：MRF的核心就是定量分析，均错误。", "tr": "MRF=“一次采集、多参数定量”，是定量MRI的前沿代表。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-1037", "t": "案例分析题", "s": "患者女性，42岁，症状性子宫肌瘤拟行MRgFUS（磁共振引导聚焦超声）消融治疗。治疗全程需要在消融的同时监测组织温度与疗效，确保安全并避免损伤邻近组织。技师负责治疗计划与术中成像方案，MRgFUS治疗需术前三维计划、术中实时引导与PRF温度监测相结合，确保靶区充分消融且不损伤周围组织。治疗过程中需同步监测患者耐受与邻近器官温度保护。正确的做法是", "o": {"A": "治疗前制定三维计划，术中以PRF测温序列实时监测靶区温度并观察消融范围", "B": "无需温度监测直接治疗", "C": "用CT代替MR引导", "D": "术中不做任何成像", "E": "仅凭患者感觉判断消融范围"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-140", "kp": "MRgFUS治疗", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】MRgFUS要求术前三维定位规划，术中采用PRF测温法实时监测靶区温度，并结合增强/非增强成像确认消融范围，确保疗效与安全，故A正确。\n【为什么错】B：无温度监测无法保证安全。C：CT无温度监测且含电离辐射。D：不成像无法引导与评估。E：患者感觉不能客观反映消融范围，均错误。", "tr": "MRgFUS的“MR”价值正在于无辐射实时测温（PRF）。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MRI介入技术进展", "页": 404}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-9016", "t": "单选题", "s": "在 MR 引导介入（MRI 介入技术）中，对穿刺与器械的核心要求是", "o": {"A": "可使用常规铁磁性不锈钢器械以降低成本", "B": "必须使用 MR 兼容/无磁材料及射频透明器械，避免抛射、伪影与加热", "C": "器械越长越好以到达深部病灶", "D": "无需考虑 SAR，可长时间高功率扫描", "E": "任何 CT 介入器械均可直接用于 MR 介入"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-009", "kp": "MR介入器械要求", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】B正确——MR 介入须在强磁场与射频场中进行，器械须为无磁/弱磁、射频透明且兼容，防止铁磁器械抛射伤人、产生严重伪影或射频加热灼伤；这是 MR 介入安全与成像质量的前提。【为什么错】A铁磁器械在磁场中抛射是严重事故；C器械选择取决于入路与病灶而非越长越好；D仍需控制 SAR 防止患者热损伤；E CT 器械多含铁磁部件，不能直接用于 MR。", "tr": "MR 介入第一原则是\"无磁/MR兼容\"，铁磁器械绝对禁止。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MRI介入技术进展", "页": 404}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-9017", "t": "单选题", "s": "MR 引导介入治疗中，常利用以下哪项原理实现实时温度监测", "o": {"A": "超声回波强度变化", "B": "质子共振频率（PRF）随温度偏移，通过相位图测温度", "C": "X 线衰减系数变化", "D": "放射性核素分布", "E": "血氧水平依赖（BOLD）对比"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-010", "kp": "MR实时温度监测原理", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】B正确——水分子质子共振频率随温度升高约 0.01 ppm/°C 线性偏移，MR 通过采集相位信息生成温度图，实现非侵入、实时的组织温度与热剂量监测，是 MR 引导聚焦超声（MRgFUS）等治疗的核心。【为什么错】A超声不属 MR 测温；C为 CT 原理；D为核医学；E BOLD 反映血氧变化而非温度。", "tr": "MR 测温核心是 PRF 相位偏移，不是 BOLD，也非超声。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MRI介入技术进展", "页": 404}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-9201", "t": "单选题", "s": "MRI 引导介入的优势在于", "o": {"A": "无电离辐射且软组织对比佳，可实时温控", "B": "辐射剂量低但无软组织对比", "C": "需大量造影剂", "D": "仅用于骨骼", "E": "扫描极快"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-9201", "kp": "MRI介入优势", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展", "ex": "【为什么对】MRI 引导无电离辐射、软组织对比好，且可实时温度监测（如聚焦超声），适合经皮活检与消融。\n【为什么错】MRI 软组织对比佳而非差。", "tr": "MRI介入=无辐射+好对比+温控。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "U17-9202", "t": "单选题", "s": "MRI 兼容的介入器械必须具备", "o": {"A": "抗磁（无铁磁性）且不影响梯度/射频", "B": "高含铁量", "C": "导电性", "D": "放射性", "E": "可透视即可"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-9202", "kp": "MRI兼容器械", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展", "ex": "【为什么对】MRI 介入器械须为非铁磁性、MR 兼容，避免被磁场吸引与产热。\n【为什么错】含铁量高是禁忌。", "tr": "MRI器械须抗磁兼容。", "bk": "副高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-053-001", "t": "单选题", "s": "在颅脑CT横断面影像上，识别中央沟最可靠的标志是", "o": {"A": "顶枕沟", "B": "外侧裂", "C": "中央沟上端抵达大脑半球上缘处呈“切迹”样凹陷", "D": "扣带沟", "E": "距状裂"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-01", "kp": "颅脑横断面影像解剖", "ch": "一、人体断面影像解剖 → 1.头部 → 颅脑横断面影像解剖", "ex": "【为什么对】中央沟在CT/MRI横断面上最特征性表现为：中央沟上端抵达大脑半球上缘处，形成明显“切迹”样凹陷，是识别中央沟最可靠的影像学标志。中央沟前方为额叶（中央前回），后方为顶叶（中央后回）。【为什么错】A顶枕沟位于大脑半球内侧面后部，为顶叶与枕叶分界。B外侧裂位于外侧面，为颞叶与额顶叶分界。D扣带沟位于内侧面属边缘系统。E距状裂位于枕叶内侧面。", "tr": "部分考生易将外侧裂（B）误认为中央沟定位标志——外侧裂呈“Y”形或“T”形、位置偏下偏外侧。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-002", "t": "多选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，关于颈部CT横断面影像解剖，以下描述正确的是", "o": {"A": "甲状腺位于气管两侧，平第5颈椎至第1胸椎水平，CT平扫呈均匀软组织密度", "B": "颈总动脉在甲状软骨上缘水平分为颈内动脉和颈外动脉", "C": "颈内静脉位于颈总动脉的外侧，管径通常大于颈总动脉", "D": "喉室在横断面上位于真假声带之间，呈含气空腔", "E": "食管在颈段始终位于气管正后方"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-02", "kp": "颈部断面影像解剖", "ch": "一、人体断面影像解剖 → 2.颈部 → 颈部断面影像解剖", "ex": "【为什么对】A正确：甲状腺平C5-T1，CT呈均匀稍高软组织密度（含碘）。B正确：分叉在甲状软骨上缘（约C3-C4）。C正确：颈内静脉居外侧、管径较大。D正确：喉室为真假声带间含气腔隙。【为什么错】E错误：食管颈段并非始终位于气管正后方——颈根部食管略偏左侧，气管食管沟内有喉返神经走行。", "tr": "E描述过于绝对——食管颈段入胸廓上口时向左偏移。颈动脉鞘内：动脉居内侧、静脉居外侧、迷走神经居后方。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "颈部", "页": 8}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-003", "t": "单选题", "s": "在胸部CT横断面影像上，隆突下间隙位于", "o": {"A": "气管与食管之间", "B": "主动脉弓与肺动脉干之间", "C": "左、右主支气管分叉处下方", "D": "上腔静脉与升主动脉之间", "E": "奇静脉弓与气管之间"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-03", "kp": "胸部断面影像解剖", "ch": "一、人体断面影像解剖 → 3.胸部 → 胸部断面影像解剖", "ex": "【为什么对】隆突下间隙指气管隆突（左、右主支气管分叉处）下方区域，是第7组淋巴结分布区。【为什么错】A为气管食管沟；B为主肺动脉窗（第5组淋巴结）；D为上腔静脉后间隙；E为奇静脉食管隐窝上份。", "tr": "容易将主肺动脉窗（B）与隆突下间隙混淆——两者均为纵隔淋巴结区域但层面位置不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-004", "t": "案例分析题", "s": "患者男性，55岁，因上腹部不适行上腹部MRI平扫+增强检查。横断面T2WI脂肪抑制序列上，肝右叶第VIII段见类圆形高信号灶，边界清晰，约2.5cm×2.0cm，增强扫描动脉期明显均匀强化，门静脉期及延迟期呈等信号。", "o": {"A": "该病灶Couinaud分段为第VIII段，位于肝右静脉与肝中静脉之间、肝右叶上份", "B": "T2WI脂肪抑制呈高信号提示病灶含水量增加，常见于恶性肿瘤", "C": "“动脉期明显强化+门静脉期及延迟期等信号”是典型血管瘤的强化模式", "D": "肝第VIII段血供主要来自门静脉右支", "E": "该患者最可能的诊断是肝细胞肝癌"}, "d": "难", "c": "分析", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-04", "kp": "腹部断面影像解剖与Couinaud分段", "ch": "一、人体断面影像解剖 → 4.腹部 → 腹部断面影像解剖与Couinaud分段", "ex": "【为什么对】A正确：第VIII段位于肝右叶上份，内侧肝中静脉、外侧肝右静脉。【为什么错】B错误：T2WI高信号良恶性均可见。C错误：动脉期均匀强化+延迟期等信号是FNH或肝腺瘤特征，非血管瘤（血管瘤为周边结节样→向心性填充）。D错误：肝脏各段均为肝动脉+门静脉双重供血。E错误：根据影像特征更可能是FNH而非肝癌（肝癌为“快进快出”）。", "tr": "C将FNH强化模式描述为血管瘤特征。血管瘤=“早出晚归”（周边结节样→向心性填充），肝癌=“快进快出”，FNH=“快进等出”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-005", "t": "单选题", "s": "在男性盆腔MRI横断面T2WI上，前列腺中央带相对于周围带的信号特征是", "o": {"A": "中央带呈高信号，周围带呈低信号", "B": "中央带呈低信号，周围带呈高信号", "C": "中央带与周围带均呈等信号", "D": "中央带呈等信号，周围带呈高信号", "E": "中央带呈高信号，周围带呈等信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-05", "kp": "盆腔断面影像解剖", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → 盆腔断面影像解剖", "ex": "【为什么对】T2WI上周围带因富含腺体和液体呈均匀高信号；中央带因含较多平滑肌和致密基质呈低信号。约70%前列腺癌起源于周围带，在高信号背景上呈低信号区。【为什么错】A信号特征颠倒。C、D、E均与实际不符——周围带T2WI明确高信号，中央带低信号。", "tr": "考生可能受CT思维影响认为各带信号差异不大（C），但MRI T2WI上周围带与中央带信号差异是识别前列腺解剖分区的关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-006", "t": "多选题", "s": "关于脊柱MRI矢状面影像解剖，以下描述正确的是", "o": {"A": "正常成人椎间盘在T2WI上呈高信号，中央可见“水平线”样低信号裂隙", "B": "脊髓圆锥末端在成人通常平第L1椎体下缘水平", "C": "后纵韧带在MRI各序列上均呈低信号，紧贴椎体后缘", "D": "椎管前后径最窄的部位位于T4-T9水平", "E": "黄韧带位于椎板前方，在T1WI和T2WI上均呈中等信号"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ANAT-06", "kp": "脊柱断面影像解剖", "ch": "一、人体断面影像解剖 → 6.脊柱区 → 脊柱断面影像解剖", "ex": "【为什么对】A正确：正常椎间盘T2WI高信号，中央水平裂隙为椎间盘内裂（正常）。B正确：圆锥末端约L1下缘。C正确：后纵韧带纤维性→各序列低信号。D正确：T4-T9椎管最窄。【为什么错】E错误：黄韧带富含弹性蛋白，信号介于肌肉和脂肪之间（中等至稍高信号），非所有序列均单纯中等信号。", "tr": "黄韧带（弹性蛋白为主）与其他韧带（胶原纤维为主）MRI信号不同——后者各序列低信号，黄韧带信号有所升高。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "脊柱区", "页": 21}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-007", "t": "单选题", "s": "结合上述情景，X线管产生X线的效率约为", "o": {"A": "0.1%以下", "B": "约1%", "C": "约5%", "D": "约10%", "E": "约30%"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XRAY-01", "kp": "X线产生效率", "ch": "二、医学物理基础 → 1.X线的产生 → X线产生效率", "ex": "【为什么对】X线产生效率约1%，约99%电子动能转化为热能。η≈K×Z×kVp（K≈1×10⁻⁹），钨靶（Z=74）在100kVp下η≈0.74%。【为什么错】A过低；C、D、E均显著高估。临床诊断用X线管效率在0.5%-1.5%之间。", "tr": "考生凭直觉可能认为X线效率较高（C/D/E），但X线管是效率极低的热能转换器。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-008", "t": "多选题", "s": "以下哪些属于X线的物理特性", "o": {"A": "穿透作用", "B": "荧光作用", "C": "电离作用", "D": "感光作用", "E": "生物效应"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XRAY-02", "kp": "X线的特性", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → X线的特性", "ex": "【为什么对】物理特性包括：①穿透作用；②荧光作用（透视和增感屏基础）；③电离作用（剂量学和放疗基础）。【为什么错】D感光作用属化学特性——X线使溴化银感光。E生物效应属生物特性——X线对生物体的损伤效应。", "tr": "感光作用常被误归为物理特性，但实质是卤化银光化学反应。生物效应虽基于物理电离，但已涉及生命体反应。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-009", "t": "单选题", "s": "在诊断X线能量范围内（20-150keV），X线与物质最主要的相互作用形式是", "o": {"A": "光电效应", "B": "康普顿散射", "C": "电子对效应", "D": "瑞利散射", "E": "光核反应"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XRAY-03", "kp": "X线与物质的相互作用", "ch": "二、医学物理基础 → 3.X线的本质及与物质的相互作用 → X线与物质的相互作用", "ex": "【为什么对】诊断能量范围内光电效应占主导，是形成X线影像对比度的主要物理基础。光电效应概率∝Z³⁻⁴，与E³成反比，使骨骼与软组织产生良好天然对比。【为什么错】B康普顿散射在诊断能量范围内次要，随能量升高占比增大。C电子对效应需>1.022MeV。D瑞利散射占比约5-10%，不产生电离。E光核反应需>10MeV。", "tr": "考生常误选康普顿散射（B），因CT较高kVp时占比增加。但常规X线摄影有效能量范围（40-80keV）光电效应仍是主导。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-010", "t": "单选题", "s": "半价层（HVL）反映了X线的哪种特性", "o": {"A": "X线的空间分布", "B": "X线的质（穿透能力）", "C": "X线的量（光子数目）", "D": "X线的散射程度", "E": "X线的焦点大小"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XRAY-04", "kp": "X线的衰减与质控参数", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → X线的衰减与质控参数", "ex": "【为什么对】HVL定义为使入射X线强度衰减至一半所需吸收物质厚度（mmAl或mmCu），反映X线束的“质”（穿透能力/硬度）。HVL越大穿透力越强。【为什么错】A不反映空间分布。C反映质而非量（量用mAs衡量）。D散射程度与多种因素有关。E焦点大小为X线管几何参数。", "tr": "初学者易将HVL与“量”混淆——“衰减一半”听起来像测数量，但HVL实质是测穿透能力（质）。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-011", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，MRI中，Larmor频率与主磁场强度B₀的关系是", "o": {"A": "正比关系", "B": "反比关系", "C": "无关系", "D": "指数关系", "E": "对数关系"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MRI-01", "kp": "Larmor方程与磁共振物理", "ch": "二、医学物理基础 → 5.磁学基础知识 → Larmor方程与磁共振物理", "ex": "【为什么对】Larmor方程：ω₀=γB₀，Larmor频率与B₀成正比。氢质子γ=42.58MHz/T，1.5T下f₀≈63.9MHz，3.0T下f₀≈127.7MHz。【为什么错】B、C、D、E均与Larmor方程不符——是严格线性正比关系。", "tr": "考生可能混淆Larmor频率与T1/T2弛豫时间对场强的依赖性。T1与场强一般正相关，T2依赖性较小。Larmor频率严格正比于B₀。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-012", "t": "多选题", "s": "关于T1和T2弛豫的描述，以下正确的是", "o": {"A": "T1弛豫又称自旋-晶格弛豫，反映纵向磁化矢量恢复过程", "B": "T2弛豫又称自旋-自旋弛豫，反映横向磁化矢量衰减过程", "C": "脂肪的T1值长于水的T1值", "D": "在3.0T场强下组织的T1值通常较1.5T下延长", "E": "T2*总是大于或等于T2"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MRI-02", "kp": "T1/T2/T2*弛豫机制", "ch": "二、医学物理基础 → 5.磁学基础知识 → T1/T2/T2*弛豫机制", "ex": "【为什么对】A正确：T1弛豫为纵向磁化恢复过程。B正确：T2弛豫为横向磁化衰减过程。D正确：随场强增高T1值普遍延长。【为什么错】C错误：脂肪T1短（约260ms/1.5T），水T1长（约3000ms/1.5T）。E错误：T2*≤T2，因T2*包含主磁场不均匀性导致的额外失相（1/T2*=1/T2+1/T2'）。", "tr": "两个陷阱：①C将脂肪和水T1长短说反——脂肪T1WI高信号正因为T1值短。②E将T2*与T2大小关系颠倒——T2*<T2。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-013", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，放射防护三原则不包括以下哪项", "o": {"A": "实践正当化", "B": "防护最优化", "C": "个人剂量限值", "D": "辐射剂量最小化至零", "E": "以上都不是（三原则包含A、B、C）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-01", "kp": "放射防护三原则", "ch": "二、医学物理基础 → 6.X线防护与测量 → 放射防护三原则", "ex": "【为什么对】ICRP放射防护三原则：①实践正当化；②防护最优化（ALARA）；③个人剂量限值。“辐射剂量最小化至零”不是防护原则——医学实践中零辐射意味着放弃所有放射学检查，不符合正当化。【为什么错】A、B、C均为正确三原则。E为干扰项。", "tr": "D“最小化至零”听起来像防护极致要求，但放射防护追求ALARA（可合理达到的尽量低），非绝对零剂量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-014", "t": "多选题", "s": "结合上述情景，关于X线在物质中的衰减规律，正确的描述是", "o": {"A": "单能X线窄束衰减符合指数衰减规律：I=I₀e^{-μx}", "B": "线衰减系数μ与物质密度成正比", "C": "质量衰减系数μ/ρ与物质的物理状态（固态/液态/气态）无关", "D": "增加管电压（kVp）可使X线束穿透力增强，表现为半价层增大", "E": "CT中使用的Hounsfield单位是基于水的线衰减系数定义的"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-ATTN-01", "kp": "X线衰减规律与CT值", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → X线衰减规律与CT值", "ex": "【为什么对】五项均正确。A：单能窄束严格指数衰减。B：μ与密度成正比。C：μ/ρ消除密度影响仅取决于原子组成和X线能量。D：提高kVp→平均能量增高→HVL增大。E：CT值=(μ_物质-μ_水)/μ_水×1000。【为什么错】无错误选项。", "tr": "部分考生可能对C存疑——质量衰减系数已除以密度，消除物理状态影响。同一化学成分不论气液固态，μ/ρ相同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-015", "t": "共用题干题", "s": "结合上述情景，旋转阳极X线管与固定阳极X线管相比，其主要优势是", "o": {"A": "更低的管电压要求", "B": "更小的焦点", "C": "更大的热容量和更高的输出功率", "D": "更简单的制造工艺", "E": "更低的成本"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-01", "kp": "X线管结构与阳极特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → X线管结构与阳极特性", "ex": "【为什么对】旋转阳极核心优势：阳极靶盘高速旋转（3000-10000rpm），电子轰击热量分布在环形靶道上，有效焦点面积小但实际受热面积大幅增加，热容量显著提升，允许更高输出功率。【为什么错】A与管电压无关。B可实现更小有效焦点（阳极倾角效应），但非核心优势。D、E旋转阳极结构更复杂、成本更高。", "tr": "部分考生可能误选B——虽然旋转阳极配合倾角可实现微焦点，但设计初衷是解决散热、提高功率承载能力。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03055", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-053-016", "t": "多选题", "s": "关于CR（计算机X线摄影）系统的成像过程，以下正确的是", "o": {"A": "CR使用IP（成像板）作为X线探测器，IP核心材料是光激励发光荧光体（如BaFX:Eu²⁺）", "B": "IP经X线曝光后形成潜影，潜影可在室温下稳定存储数小时至数天", "C": "IP读取时使用紫外（UV）激光逐点扫描，激发出的荧光被光电倍增管收集并数字化", "D": "CR系统的空间分辨率主要受IP荧光体层厚度和激光扫描点大小限制", "E": "CR与DR的根本区别在于CR需要“读取”步骤，而DR直接产生数字信号"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-02", "kp": "CR成像原理与流程", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → CR成像原理与流程", "ex": "【为什么对】A正确——CR的IP核心为掺铕氟卤化钡（BaFX:Eu²⁺）光激励发光荧光体。B正确——X线激发形成的F中心潜影在室温下可稳定数小时至数天（存在fading）。D正确——CR空间分辨率受IP荧光体层厚度与激光扫描光斑尺寸限制，典型值2.5–5 lp/mm。E正确——CR须经独立“读取”步骤才能输出数字信号，而DR探测器直接产生数字信号，这是二者根本区别。【为什么错】C错误——CR读取采用红-近红外激光（如He-Ne 633 nm或半导体680 nm）激发IP中Eu²⁺陷阱释放光激励发光（PSL）荧光，由PMT收集；紫外激光不能有效激发该荧光体，故“紫外激光”之说错误。", "tr": "本题已将原“全选”改为四项正确；注意选项C为刻意设置的错误项——CR读取采用红-近红外激光（如He-Ne 633 nm或半导体680 nm）激发IP中Eu²⁺陷阱释放光激励发光（PSL）荧光，由PMT收集；紫外激光不能有效激发该荧光体，故“紫外激光”之说错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-017", "t": "单选题", "s": "结合上述情景，多层螺旋CT中，决定Z轴空间分辨率的最关键因素是", "o": {"A": "球管旋转速度", "B": "螺距（pitch）", "C": "准直宽度（探测器排宽×排数）与重建层厚", "D": "扫描视野（FOV）", "E": "矩阵大小"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-03", "kp": "CT成像参数与图像质量", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → CT成像参数与图像质量", "ex": "【为什么对】Z轴空间分辨率主要取决于准直宽度和重建层厚。层厚越薄、准直越窄，Z轴分辨率越高。现代MDCT通过亚毫米准直+薄层重建实现各向同性。【为什么错】A球管转速影响时间分辨率。B螺距影响覆盖速度和Z轴采样密度，是次级因素。D FOV影响XY平面。E矩阵影响XY平面。", "tr": "部分考生误选B（螺距）——螺距确实影响Z轴采样质量，但层厚才是Z轴分辨率的一级决定因素。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-018", "t": "共用题干题", "s": "结合上述情景，DSA减影过程中，mask像是指", "o": {"A": "注射对比剂后的血管充盈像", "B": "注射对比剂前不含对比剂的平片", "C": "注射对比剂后延迟采集的像", "D": "经像素移位校正后的图像", "E": "对数变换后的图像"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-04", "kp": "DSA减影原理", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → DSA减影原理", "ex": "【为什么对】mask像（蒙片）是注射对比剂前采集的不含血管对比剂的平片。减影流程：mask像−造影像=减影像（仅显示血管内对比剂）。【为什么错】A为造影像（live像）。C仍属造影像。D为减影后配准修正。E为减影前预处理。", "tr": "记忆：mask=“蒙”（蒙在背景上、无对比剂），live=“活”（有对比剂、血管显影）。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03047", "gs": ""}, {"id": "ZG-053-019", "t": "多选题", "s": "关于MRI自旋回波（SE）序列中TR和TE对图像对比度的影响，正确的是", "o": {"A": "短TR+短TE产生T1加权对比", "B": "长TR+长TE产生T2加权对比", "C": "长TR+短TE产生质子密度加权对比", "D": "TR主要控制T1权重，TE主要控制T2权重", "E": "在SE序列中，只要TR足够长（>5×最长组织T1），无论TE多短，图像总是T2加权"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-05", "kp": "MRI脉冲序列与加权成像", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → MRI脉冲序列与加权成像", "ex": "【为什么对】A正确：短TR+短TE=T1WI。B正确：长TR+长TE=T2WI。C正确：长TR+短TE=PDWI。D正确：TR调节T1权重，TE调节T2权重。【为什么错】E错误：长TR+短TE=质子密度加权——长TR消除T1差异，短TE消除T2差异。要获得T2加权必须长TR+长TE。", "tr": "E是经典陷阱——长TR消除T1效应正确，但要获得T2加权还需长TE。口诀：短TR短TE→T1WI；长TR长TE→T2WI；长TR短TE→PDWI。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-020", "t": "案例分析题", "s": "某医院计划采购一台64排螺旋CT设备，用于常规临床检查和冠状动脉CTA。影像科主任要求技术组评估该设备的关键技术参数。以下分析哪些是正确的", "o": {"A": "机架旋转速度至少应达到≤0.35s/圈，以满足冠状动脉CTA的时间分辨率要求", "B": "探测器准直宽度应≥32mm（如64×0.5mm或64×0.625mm），以实现足够Z轴覆盖", "C": "螺距设置对于冠脉CTA非常关键，通常使用前瞻性心电门控扫描模式，螺距接近0.2-0.3", "D": "管电流（mA）和管电压（kVp）的自动调制技术对于降低辐射剂量至关重要", "E": "64排CT的Z轴空间分辨率理论上可达到各向同性（如0.5mm×0.5mm×0.5mm）"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-06", "kp": "CT设备关键参数与临床应用评估", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → CT设备关键参数与临床应用评估", "ex": "【为什么对】五项均正确。A：冠脉CTA要求极高时间分辨率。B：64×0.5/0.625mm配置提供约32-40mm Z轴覆盖。C：前瞻性门控采用极低进床速度确保在心脏相对静止期完整采集数据。D：ATCM和自动kVp是低剂量CT核心技术。E：亚毫米准直+薄层重建实现各向同性分辨率。【为什么错】无错误选项。", "tr": "C易被误判——前瞻性心电门控实际为轴向扫描（step-and-shoot），但结论（低螺距/极低进床速度）正确。需注意prospective vs retrospective gating差异。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-021", "t": "共用题干题", "s": "结合上述情景，DR系统使用的平板探测器，其核心转换材料中，非晶硒（a-Se）属于", "o": {"A": "间接转换型探测器，利用闪烁体将X线转换为可见光再转换为电荷", "B": "直接转换型探测器，直接将X线转换为电荷", "C": "光激励发光型探测器", "D": "热释光型探测器", "E": "CMOS型探测器"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-07", "kp": "DR探测器类型与原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → DR探测器类型与原理", "ex": "【为什么对】非晶硒（a-Se）是直接转换型平板探测器核心材料。X线光子直接作用于a-Se层产生电子-空穴对，被TFT阵列收集并数字化——无可见光转换步骤。【为什么错】A为间接转换型（CsI:Tl/Gd₂O₂S:Tb）。C为CR技术原理。D为热释光剂量计。E为读出电路技术。", "tr": "DR探测器分类：直接转换（a-Se）vs间接转换（CsI/Gd₂O₂S），核心区别在于是否需要“可见光”中间步骤。a-Si配合CsI使用（间接型），a-Se是直接转换材料——两者易混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03045", "gs": ""}, {"id": "ZG-053-022", "t": "多选题", "s": "关于MRI梯度系统的功能，以下正确的是", "o": {"A": "层面选择梯度（Gss/Gz）用于选择成像层面，通常与RF脉冲配合使用", "B": "相位编码梯度（Gpe/Gy）用于在K空间的相位编码方向上进行空间定位", "C": "频率编码梯度（Gro/Gx）用于在信号读出期间进行频率编码，也称读出梯度", "D": "梯度场的最大强度和切换率（slew rate）共同决定了MRI的扫描速度", "E": "EPI（回波平面成像）对梯度系统的性能要求远低于常规SE序列"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-EQUIP-08", "kp": "MRI梯度系统与空间编码", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → MRI梯度系统与空间编码", "ex": "【为什么对】A正确——层面选择梯度在RF激励期间施加，配合RF带宽选层。B正确——相位编码梯度赋予质子沿相位编码方向线性变化的相位，实现该向定位。C正确——频率编码梯度在信号读出期间施加，使不同位置质子频率不同，故称读出梯度。D正确——梯度最大强度决定最小FOV/最小层厚，切换率（slew rate）决定最短梯度爬升时间，二者共同决定扫描速度。【为什么错】E错误——EPI要求在一次射频激发内完成整幅K空间所有相位编码行的填充，梯度场须在亚毫秒级反复高速切换至高振幅，对梯度强度与切换率要求极高，远高于常规SE序列，而非“远低于”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——EPI要求在一次射频激发内完成整幅K空间所有相位编码行的填充，梯度场须在亚毫秒级反复高速切换至高振幅，对梯度强度与切换率要求极高，远高于常规SE序列，而非“远低于”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-023", "t": "共用题干题", "s": "结合上述情景，下列关于碘对比剂不良反应的描述，错误的是", "o": {"A": "碘对比剂不良反应分为类过敏反应（非特异质）和特异质反应两大类", "B": "急性肾损伤（AKI）是碘对比剂的重要并发症，糖尿病合并肾功能不全患者风险更高", "C": "碘对比剂不良反应的发生率与对比剂的渗透压呈正相关——等渗对比剂的安全性最高", "D": "一旦发生严重过敏反应，首选皮下注射肾上腺素", "E": "使用碘对比剂前常规进行碘过敏皮试可以完全预防严重过敏反应"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CONTRAST-01", "kp": "碘对比剂不良反应与安全管理", "ch": "四、对比剂 → 1.X线对比剂 → 碘对比剂不良反应与安全管理", "ex": "【为什么对】E表述错误——碘过敏皮试对预测严重过敏反应灵敏度和特异度均极低，ACR和ESUR已不推荐常规皮试。严重过敏反应无法通过皮试预测。【为什么错】A正确：不良反应分类确为类过敏和特异质。B正确：CA-AKI高危因素包括肾功能不全、糖尿病等。C正确：高渗对比剂不良反应率显著高于低渗和等渗。D方向正确，但最新指南推荐肌注而非皮下注射——但E为根本性错误。", "tr": "D存在潜在陷阱——最新指南推荐肾上腺素肌注（大腿前外侧）而非皮下注射。但E（皮试可完全预防过敏）明显根本性错误，为最佳答案。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04079", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-053-024", "t": "共用题干题", "s": "结合上述情景，关于MR对比剂（钆剂）的描述，正确的是", "o": {"A": "钆喷酸葡胺（Gd-DTPA）属于线性结构钆螯合物，是最早应用于临床的钆剂之一", "B": "钆剂的主要作用是缩短T1和T2弛豫时间，临床上以T1缩短效应（T1WI增强）为主", "C": "大环状结构钆剂（如钆布醇、钆特酸）较线性钆剂具有更高的热力学和动力学稳定性，钆离子解离风险更低", "D": "肾源性系统性纤维化（NSF）的发生与游离钆离子在组织中的沉积密切相关，高危人群为重度肾功能不全患者", "E": "钆剂在颅内结构的沉积（“钆沉积”）已被证实，但其远期临床意义目前仍不明确"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CONTRAST-02", "kp": "MR对比剂分类与安全", "ch": "四、对比剂 → 2.MR对比剂 → MR对比剂分类与安全", "ex": "【为什么对】五项均为正确描述。A：Gd-DTPA（1988年上市）属线性离子型。B：Gd³⁺含7个未成对电子，临床利用T1缩短效应增强。C：大环状螯合剂稳定性显著优于线性。D：NSF几乎仅见于重度肾功能不全使用线性非离子型钆剂者。E：2014年后研究证实钆在脑深部核团（齿状核、苍白球）剂量依赖性沉积，临床意义尚不明确。【为什么错】无错误选项。", "tr": "E是关于“钆沉积”的知识点——已明确钆可在脑组织中沉积但临床后果尚不明确。需区分“钆沉积已被证实”和“钆沉积有害”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04071", "gs": ""}, {"id": "ZG-053-025", "t": "共用题干题", "s": "结合上述情景，以下关于碘对比剂的分类，按渗透压从高到低排列正确的是", "o": {"A": "非离子型单体 > 离子型单体 > 非离子型二聚体", "B": "离子型单体 > 非离子型单体 > 非离子型二聚体", "C": "离子型单体 > 非离子型二聚体 > 非离子型单体", "D": "非离子型二聚体 > 非离子型单体 > 离子型单体", "E": "非离子型单体 > 非离子型二聚体 > 离子型单体"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CONTRAST-03", "kp": "碘对比剂分类与理化特性", "ch": "四、对比剂 → 1.X线对比剂 → 碘对比剂分类与理化特性", "ex": "【为什么对】渗透压排序：离子型单体（约1500-2100mOsm/kg）>非离子型单体（约600-900mOsm/kg）>非离子型二聚体（约290mOsm/kg，等渗）。离子型单体解离产生2个渗透活性粒子（比值=1.5），渗透压很高；非离子型单体不解离（比值=3）；非离子型二聚体6个碘不解离（比值=6），可达等渗。【为什么错】其他排列均与上述原理不符。", "tr": "核心记忆：“解离产生更多粒子→渗透压更高”。离子型单体>非离子型单体>非离子型二聚体。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04079", "gs": ""}, {"id": "ZG-053-026", "t": "共用题干题", "s": "结合上述情景，患者男性，68岁，体重70kg，因腹痛行腹部增强CT检查。既往有高血压病史15年、2型糖尿病史8年（口服二甲双胍），实验室检查：血肌酐142μmol/L（eGFR≈48ml/min/1.73m²）。医生开具碘对比剂（非离子型单体，含碘350mgI/ml，计划注射量100ml）。作为CT技术组负责人，以下处理方案正确的有哪些", "o": {"A": "该患者eGFR<60，属对比剂急性肾损伤（CA-AKI）高风险人群，检查前应充分水化（如0.9%NaCl 1ml/kg/h×12h）", "B": "应停用二甲双胍至少48小时，待增强CT后肾功能稳定（复查血肌酐无显著升高）方可恢复用药", "C": "碘对比剂总量100ml（含碘35g），对该患者属于常规剂量，无需调整", "D": "在条件允许的情况下，应优先考虑使用等渗对比剂（碘克沙醇）替代非离子型单体以降低肾毒性风险", "E": "增强CT检查后应继续水化至少24小时，并在48-72小时内复查肾功能"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CONTRAST-04", "kp": "对比剂安全管理与临床决策", "ch": "四、对比剂 → 1.X线对比剂 → 对比剂安全管理与临床决策", "ex": "【为什么对】A正确：eGFR<60是CA-AKI高危人群，水化是最有效预防措施。B正确：二甲双胍在eGFR 30-60之间国内多数医院谨慎停药48h。D正确：等渗对比剂在肾功能不全患者中CA-AKI发生率可能更低。E正确：检查后持续水化+随访肾功能是标准流程。【为什么错】C错误：对于eGFR<60患者，应在保证诊断需求前提下尽可能减少对比剂用量——对比剂剂量与CA-AKI风险正相关。", "tr": "C是主要陷阱——“常规剂量”对肾功能不全患者可能过高。核心原则：在满足诊断条件下使用最低剂量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ04078", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-053-027", "t": "共用题干题", "s": "结合上述情景，CT图像质量评价中，调制传递函数（MTF）主要用于评价", "o": {"A": "噪声水平", "B": "空间分辨率", "C": "低对比度分辨率", "D": "CT值线性度", "E": "时间分辨率"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QC-01", "kp": "CT图像质量评价参数", "ch": "五、影像质量管理 → 1.CT图像质量控制 → CT图像质量评价参数", "ex": "【为什么对】MTF是评价成像系统空间分辨率的客观量化指标，描述系统对不同空间频率（lp/cm）信号的传递能力。MTF=1表示完美传递，MTF=0表示完全不能分辨。常用MTF=10%对应空间频率为极限分辨率。【为什么错】A噪声用NPS或SD评价。C低对比度分辨率用LCD评价。D CT值线性度通过扫描已知CT值模体评价。E时间分辨率通过机架旋转速度评价。", "tr": "部分考生易将MTF与对比度分辨率混淆——MTF是高频响应（边缘锐利度），低对比度分辨率是低频检测能力。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05093", "gs": ""}, {"id": "ZG-053-028", "t": "多选题", "s": "MRI日常质量控制（QC）应包括以下哪些测试项目", "o": {"A": "中心频率（共振频率）校准", "B": "信噪比（SNR）测量", "C": "图像均匀度测试", "D": "几何畸变测试", "E": "层厚精度测量不属于MRI QC常规项目，仅CT质控需要"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QC-02", "kp": "MRI质量控制项目", "ch": "五、影像质量管理 → 2.MR图像质量控制 → MRI质量控制项目", "ex": "【为什么对】A正确——中心频率（共振频率）校准确保RF与Larmor频率匹配，通常每日测试。B正确——信噪比（SNR）是最综合的图像质量指标。C正确——图像均匀度反映B₁与B₀场均匀性。D正确——几何畸变测试反映梯度场线性度，对高场强尤为关键。【为什么错】E错误——层厚精度（slice thickness accuracy）是MRI QC的常规测试项目（ACR/AAPM推荐），用以监测因梯度非线性和射频选择性偏差导致的实际层厚偏离；并非“仅CT需要”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——层厚精度（slice thickness accuracy）是MRI QC的常规测试项目（ACR/AAPM推荐），用以监测因梯度非线性和射频选择性偏差导致的实际层厚偏离；并非“仅CT需要”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-029", "t": "共用题干题", "s": "结合上述情景，在数字X线图像处理中，窗口技术中的“窗宽”（window width）决定了", "o": {"A": "图像的整体亮度", "B": "图像的显示对比度（灰阶范围）", "C": "图像的空间分辨率", "D": "图像的信噪比", "E": "图像的几何放大率"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIGITAL-01", "kp": "窗口技术与灰阶处理", "ch": "六、数字X线成像基础 → 1.数字图像处理 → 窗口技术与灰阶处理", "ex": "【为什么对】窗宽（WW）定义显示灰阶所覆盖的CT值/HU值范围。窗宽越宽→CT值范围越大→组织间灰阶差异越小（低对比度）；窗宽越窄→范围越小→差异越大（高对比度）。窗宽决定对比度。【为什么错】A窗位（WL）决定整体亮度。C空间分辨率取决于探测器像素/FOV/矩阵。D SNR是采集参数函数。E几何放大率由焦点-物体-探测器距离决定。", "tr": "窗宽和窗位作用常混淆——窗宽→对比度（灰阶范围），窗位→亮度（中心位置）。口诀：“宽-范围-对比度，位-位置-亮度”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06121", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-053-030", "t": "多选题", "s": "关于探测器量子检测效率（DQE），以下描述正确的是", "o": {"A": "DQE定义为输出信噪比平方与输入信噪比平方之比：DQE=(SNR_out)²/(SNR_in)²", "B": "DQE是衡量探测器X线利用效率的综合指标，理想探测器DQE=1（100%）", "C": "DQE随空间频率增加而升高", "D": "DR系统的DQE通常在60%-80%，显著高于CR系统（约30%-50%）", "E": "增加探测器X线吸收层的厚度可以提高DQE但可能降低空间分辨率"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIGITAL-02", "kp": "DQE定义及影响因素", "ch": "六、数字X线成像基础 → 2.数字图像评价 → DQE定义及影响因素", "ex": "【为什么对】A正确——DQE定义为 (SNR_out)²/(SNR_in)²，即输出与输入信噪比平方之比。B正确——理想探测器不引入额外噪声时DQE=1（100%）。D正确——DR的DQE约60%–80%，显著高于CR（约30%–50%）。E正确——增加吸收层厚度提高X线吸收效率，但增加散射与光扩散，可能降低空间分辨率，是DQE与分辨率的经典权衡。【为什么错】C错误——DQE具有空间频率依赖性，随空间频率升高而下降（高频处量子统计与散射损失更显著），并非升高；故须以DQE(0)或指定频率处DQE来描述探测器性能。", "tr": "本题已将原“全选”改为四项正确；注意选项C为刻意设置的错误项——DQE具有空间频率依赖性，随空间频率升高而下降（高频处量子统计与散射损失更显著），并非升高；故须以DQE(0)或指定频率处DQE来描述探测器性能。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-031", "t": "案例分析题", "s": "在胸部X线正位片上，以下哪项最支持左心房增大的诊断", "o": {"A": "肺动脉段突出", "B": "右心缘双房影", "C": "左心缘出现“四弧征”（或称“病理性第三弓”）", "D": "心尖向左下移位", "E": "上腔静脉增宽"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-01", "kp": "心脏大血管X线诊断", "ch": "七、影像诊断学基础 → 1.胸部与心脏 → 心脏大血管X线诊断", "ex": "【为什么对】左心房增大特征性表现为：左心缘肺动脉段下方出现额外弧状突起（左心耳突出），使左心缘由正常“三弧”变为“四弧”，为“病理性第三弓”，是左心房增大的重要直接征象。【为什么错】A肺动脉段突出是肺动脉高压表现。B双房影虽是左心房增大表现但敏感性不如四弧征。D心尖向左下移位是左心室增大特征。E上腔静脉增宽见于右心功能不全。", "tr": "B（右心缘双房影）确实是左心房增大表现但出现较晚且受投照条件影响。C四弧征/病理性第三弓是更典型的直接征象。", "bk": "正高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "心脏大血管病变的基本X线表现", "页": 156}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-032", "t": "多选题", "s": "在CT影像上，以下哪些是周围型肺癌的典型表现", "o": {"A": "分叶征——肿瘤边缘呈分叶状，与肿瘤各方向生长速度不均有关", "B": "毛刺征——肿瘤边缘放射状细小短条索影，提示肿瘤浸润周围肺间质", "C": "胸膜凹陷征——肿瘤与胸膜间线状/三角形牵拉影", "D": "空泡征——肿瘤内残存含气肺泡或支气管，常见于腺癌", "E": "病变均匀钙化，CT值>200HU"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-02", "kp": "肺部肿瘤CT诊断", "ch": "七、影像诊断学基础 → 1.胸部与心脏 → 肺部肿瘤CT诊断", "ex": "【为什么对】A、B、C、D均为周围型肺癌常见CT征象。分叶征反映不均匀生长；毛刺征提示肿瘤向肺间质浸润；胸膜凹陷征是肿瘤牵拉胸膜；空泡征是腺癌特征（包绕未完全破坏的含气肺泡）。【为什么错】E错误：均匀钙化伴CT值>200HU高度提示良性病变（错构瘤、结核球等）。肺癌钙化少见且通常为点状、偏心性。", "tr": "E是区分良恶性肺结节重要考点——均匀钙化>200HU基本排除恶性肿瘤。但需注意形态比有无钙化更重要。", "bk": "正高", "ref": {"篇": "胸部", "章": "呼吸系统基本病变的影像学表现", "节": "肺部有关名词", "页": 115}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-033", "t": "案例分析题", "s": "以下关于肝海绵状血管瘤的MRI表现，错误的是", "o": {"A": "T1WI呈低信号，T2WI呈显著高信号（灯泡征）", "B": "增强扫描动脉期周边结节样强化，随时间推移呈向心性填充（“早出晚归”）", "C": "延迟期（5-10min）持续强化呈等或高信号", "D": "DWI上呈显著弥散受限（高b值高信号，ADC值极低）", "E": "重T2WI上血管瘤信号随TE延长而保持高信号（“灯泡征”在长TE序列更明显）"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-03", "kp": "肝脏常见肿瘤MRI诊断", "ch": "七、影像诊断学基础 → 2.腹部 → 肝脏常见肿瘤MRI诊断", "ex": "【为什么对】D对肝血管瘤的DWI描述错误——血管瘤为良性富血供病变，内为缓慢流动血液（血池），DWI上不表现为显著弥散受限。DWI可呈稍高信号（T2穿透效应），但ADC值通常较高或接近正常肝实质。DWI显著弥散受限+ADC极低应考虑肝癌。【为什么错】A、B、C、E均为正确表现。重T2WI灯泡征更明显是因肝实质T2较短随TE延长快速衰减，血管瘤内血液T2极长。", "tr": "许多考生认为血管瘤因T2极高在DWI上也会呈显著高信号（弥散受限）。但DWI信号同时受T2效应和真实弥散限制两方面影响——血管瘤DWI高信号主要来自“T2穿透效应”（T2 shine-through），ADC图呈等或高信号可鉴别。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-034", "t": "案例分析题", "s": "以下关于急性脑梗死的影像学表现，按时间顺序最早出现的是", "o": {"A": "CT平扫脑沟消失、脑回肿胀", "B": "T2WI/FLAIR上高信号", "C": "DWI上高信号伴ADC值降低", "D": "T1WI上低信号", "E": "增强扫描脑回样强化"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-04", "kp": "脑梗死影像诊断", "ch": "七、影像诊断学基础 → 3.颅脑中枢神经系统 → 脑梗死影像诊断", "ex": "【为什么对】急性脑梗死影像学异常出现时间顺序：DWI（数分钟至数小时）→CT早期征象（3-6h）→T2WI/FLAIR（6-12h）→T1WI低信号（12-24h）→增强脑回样强化（3-7天达峰）。DWI可检测细胞毒性水肿导致的弥散受限，是急性脑梗死最早、最敏感征象，可在症状发作后数分钟内呈阳性。【为什么错】CT早期征象需数小时才显现（敏感性约50-60%）。T2WI和T1WI变化更晚。增强脑回样强化是亚急性期表现。", "tr": "部分考生可能首选CT（A）因为急诊常用CT排除出血。但本题问“最早出现”的影像学异常——细胞毒性水肿（DWI高信号/ADC降低）是缺血后最早事件。临床先做CT是为了排除出血。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑缺血和脑梗死", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-035", "t": "案例分析题", "s": "患者女性，42岁，因右侧耳鸣伴听力下降3个月就诊。颞骨HRCT扫描显示右侧内听道内一软组织密度结节，大小约0.8cm×0.6cm，内听道无明显扩大。MRI显示右侧内听道内小结节，T1WI等信号、T2WI稍高信号，增强扫描呈明显均匀强化，边界清晰。", "o": {"A": "该病灶最可能的诊断是听神经瘤（前庭神经鞘瘤）", "B": "内听道无明显扩大与该病灶较小（<1cm）有关，不能排除听神经瘤", "C": "增强扫描明显均匀强化是听神经瘤的典型特征，据此可确诊", "D": "鉴别诊断应考虑内听道内脑膜瘤，脑膜瘤增强也呈明显强化但常有“硬膜尾征”", "E": "对于此类小听神经瘤，首选伽马刀治疗而非手术切除"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-05", "kp": "五官疾病影像诊断", "ch": "七、影像诊断学基础 → 4.五官与颈部 → 五官疾病影像诊断", "ex": "【为什么对】A正确：内听道结节（T1等/T2稍高+明显均匀强化）是听神经瘤典型表现。B正确：内听道扩大与肿瘤大小有关，<1cm微小听神经瘤可无内听道扩大。D正确：内听道脑膜瘤也可明显强化，特征为硬膜基底+硬膜尾征。【为什么错】C错误：明显均匀强化不能据此确诊——内听道脑膜瘤、面神经鞘瘤也可有类似强化。E错误：小听神经瘤治疗策略需综合多因素个体化决定，非首选伽马刀。", "tr": "C用“可据此确诊”诱导忽视鉴别诊断。E以“首选伽马刀”绝对化表述制造陷阱——稳定小肿瘤可能仅需随访观察。", "bk": "正高", "ref": null, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-036", "t": "多选题", "s": "关于骨肉瘤的X线和MRI表现，以下正确的是", "o": {"A": "好发于长骨干骺端，特别是股骨远端和胫骨近端", "B": "X线可见Codman三角（骨膜新生骨被抬起形成三角形），是骨肉瘤的特征性表现", "C": "肿瘤骨（瘤骨）是骨肉瘤最重要的X线特征——肿瘤细胞直接产生的不规则骨样组织", "D": "MRI对评价骨髓浸润范围、软组织肿块及跳跃性病灶优于X线和CT", "E": "骨肉瘤在T1WI上通常呈高信号、T2WI呈低信号"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-06", "kp": "骨肿瘤影像诊断", "ch": "七、影像诊断学基础 → 5.脊柱与四肢关节 → 骨肿瘤影像诊断", "ex": "【为什么对】A正确：骨肉瘤好发于长骨干骺端。B正确：Codman三角是骨膜被肿瘤抬起形成的三角形骨膜新生骨。C正确：瘤骨（肿瘤性骨样组织/编织骨）是骨肉瘤定性诊断依据。D正确：MRI对髓腔浸润范围、软组织肿块及跳跃灶评估优于X线/CT。【为什么错】E错误：骨肉瘤T1WI通常呈低至等信号（替代骨髓高信号脂肪），T2WI呈不均匀高信号（肿瘤含水量高）。", "tr": "E将T1/T2信号特征说反——正常骨髓T1WI高信号（脂肪），肿瘤替代后T1WI低信号。瘤骨在T2WI为低信号，但整体肿瘤T2WI以高信号为主。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-037", "t": "案例分析题", "s": "在急性胆囊炎的腹部CT检查中，以下哪项是诊断价值最高的直接影像学征象", "o": {"A": "胆囊体积增大（横径>4cm）", "B": "胆囊壁弥漫性增厚（>3mm）", "C": "胆囊壁内积气（气肿性胆囊炎表现）", "D": "胆囊周围脂肪间隙模糊、条索状密度增高（pericholecystic fat stranding）", "E": "胆囊内结石"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-07", "kp": "腹部急症影像诊断", "ch": "七、影像诊断学基础 → 2.腹部 → 腹部急症影像诊断", "ex": "【为什么对】D正确——胆囊周围脂肪间隙模糊、条索状密度增高（pericholecystic fat stranding）是急性胆囊炎在CT上最可靠的直接征象，敏感性与特异性均较高，反映胆囊壁炎症累及周围脂肪，是CT诊断急性胆囊炎的核心标准。【为什么错】A、B、E虽常见但特异性不足：胆囊淤积、慢性胆囊炎、肝硬化低蛋白血症等均可致胆囊增大或壁增厚，结石亦可无症状存在；C为气肿性胆囊炎表现，属少见重症类型，而非一般急性胆囊炎的直接征象。", "tr": "易将“胆囊壁增厚>3mm”误认为最直接征象；但壁增厚也见于慢性胆囊炎、低蛋白血症，特异性低于胆囊周围脂肪条索影。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-038", "t": "多选题", "s": "关于椎间盘突出的CT和MRI表现，正确的是", "o": {"A": "CT横断面上，椎间盘突出表现为椎间盘后缘局限性超出椎体后缘的软组织密度影", "B": "MRI上椎间盘突出可分为膨出（bulging）、突出（protrusion）、脱出（extrusion）和游离（sequestration）四种类型", "C": "Schmorl结节是指椎间盘向椎体内突出（纵向疝入），常见于Scheuermann病", "D": "椎间盘突出的方向以后外侧型最为常见，因为后纵韧带在该区域最薄弱", "E": "增强MRI扫描中，突出的椎间盘髓核通常呈明显均匀强化"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-DIAG-08", "kp": "脊柱病变影像诊断", "ch": "七、影像诊断学基础 → 5.脊柱与四肢关节 → 脊柱病变影像诊断", "ex": "【为什么对】A正确：CT横断面椎间盘突出直接征象为间盘后缘局限性超出椎体终板边缘。B正确：MRI分型确为膨出、突出、脱出、游离四级。C正确：Schmorl结节是椎间盘经终板薄弱区向椎体内疝入。D正确：后外侧型最常见——后纵韧带中线较厚而两侧薄弱。【为什么错】E错误：正常椎间盘无血供，突出髓核通常不强化或仅边缘轻度强化（肉芽组织）。明显均匀强化应考虑椎间盘炎或肿瘤。", "tr": "E是主要陷阱——突出髓核本身无血供不强化，但周围肉芽组织可出现边缘强化。明显均匀强化是椎间盘炎的典型表现。", "bk": "正高", "ref": {"篇": "骨与骨关节", "章": "正常脊柱", "节": "脊柱的发生", "页": 274}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-039", "t": "单选题", "s": "成人胸部后前位（PA位）摄影的标准体位要求不包括", "o": {"A": "患者站立，前胸紧贴探测器/IP板", "B": "双肘弯曲、手背置于髋部，使肩胛骨外展离开肺野", "C": "X线管焦点-探测器距离（SID）为100cm", "D": "深吸气后屏气曝光", "E": "中心线对准第6胸椎水平（肩胛骨下角水平）"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-01", "kp": "胸部X线摄影技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → 胸部X线摄影技术", "ex": "【为什么对】本题要求选不正确的选项。成人胸部后前位标准SID应为180cm（或至少150cm以上），而非100cm。使用长SID目的是减小心脏/纵隔的几何放大失真和减少散射。【为什么错】A正确：后前位即前胸贴板。B正确：手背置髋部外展肩胛骨是标准操作。D正确：深吸气后屏气可最大限度扩张肺野。E正确：中心线对应T6（约肩胛骨下角水平）。", "tr": "SID距离是胸部摄影最常见考点。各部位标准SID：胸部PA 180cm，腹部 100cm，四肢 100cm，脊柱 100cm。考生容易将胸部SID与腹部/四肢SID（均为100cm）混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-040", "t": "多选题", "s": "关于乳腺X线摄影（钼靶）的技术要点，以下正确的是", "o": {"A": "乳腺摄影使用钼（Mo）或铑（Rh）靶X线管，产生低能特征X线（17.5keV和19.6keV），以提高乳腺软组织的对比度", "B": "乳腺摄影常规采用头尾位（CC）和内外斜位（MLO）两个基本体位", "C": "乳腺摄影必须使用压迫装置，目的是降低辐射剂量、减少散射、提高对比度和减少运动伪影", "D": "数字化乳腺断层融合摄影（DBT）可以在不增加辐射剂量的前提下提高病变检出率", "E": "隆胸术后患者乳腺摄影需采用特殊技术（Eklund法），将假体推开后压迫乳腺组织"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-02", "kp": "乳腺X线摄影技术", "ch": "八、普通X线检查技术 → 2.乳腺与口腔X线摄影检查 → 乳腺X线摄影技术", "ex": "【为什么对】A正确：钼靶利用17.5keV和19.6keV特征辐射优化软组织对比。B正确：CC和MLO是标准基本体位。C正确：压迫可降低厚度→降低剂量、减少散射→提高对比度、固定乳房→减少运动伪影。E正确：Eklund法将假体推向胸壁后压迫前方乳腺组织。【为什么错】D错误：DBT通过多角度低剂量扫描减少组织重叠，但通常需附加额外剂量——虽然合成2D图像可适当替代传统2D扫描控制总剂量，但单独DBT扫描剂量不一定低于2D。", "tr": "D是典型陷阱——DBT与剂量关系复杂。“不增加辐射剂量”是过度绝对化表述。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-041", "t": "案例分析题", "s": "上消化道钡餐造影检查中，以下哪种征象是食管静脉曲张的特征性表现", "o": {"A": "食管黏膜皱襞增粗、迂曲，呈“串珠样”或“蚯蚓样”充盈缺损", "B": "食管下段鸟嘴样狭窄伴近端扩张", "C": "食管中段光滑的圆形充盈缺损", "D": "食管全程僵硬、蠕动消失", "E": "食管黏膜不规则龛影"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-03", "kp": "消化道造影技术", "ch": "八、普通X线检查技术 → 3.X线造影检查 → 消化道造影技术", "ex": "【为什么对】食管静脉曲张在钡餐造影中表现为食管中下段黏膜皱襞增粗、迂曲，呈特征性“串珠样”或“蚯蚓样”充盈缺损（曲张静脉突入食管腔），管壁柔软、蠕动存在，严重时可累及全程。是肝硬化门静脉高压的重要提示。【为什么错】B：食管下段鸟嘴样狭窄是贲门失弛缓特征。C：光滑圆形充盈缺损见于食管平滑肌瘤。D：全程僵硬+蠕动消失是硬皮病食管典型表现。E：黏膜不规则龛影见于食管癌（溃疡型）或反流性食管炎。", "tr": "注意鉴别：贲门失弛缓（B）=鸟嘴征/“萝卜根”征+近端扩张；食管癌=黏膜破坏/不规则充盈缺损/龛影/管壁僵硬；食管静脉曲张=串珠样/蚯蚓样充盈缺损+管壁柔软。三个消化道造影经典征象容易混淆，需要记忆各自特点和对应疾病。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-042", "t": "单选题", "s": "静脉肾盂造影（IVP）检查中，注射对比剂后通常拍摄的时间节点不包括", "o": {"A": "注射后即刻（肾实质显影期）", "B": "注射后5分钟", "C": "注射后15分钟", "D": "注射后30分钟", "E": "注射后60分钟"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-04", "kp": "泌尿系统造影技术", "ch": "八、普通X线检查技术 → 3.X线造影检查 → 泌尿系统造影技术", "ex": "【为什么对】IVP标准摄片时间：①腹部平片（注射前）；②5-7分钟（肾盂肾盏显影）；③15分钟（输尿管显影）；④30分钟（膀胱显影）；⑤必要时60分钟延迟片。“注射后即刻”不是标准时间点——对比剂需约3-5分钟才能经肾小球滤过到达肾盂肾盏。【为什么错】B、C、D、E均为常规或必要时时间点。", "tr": "部分考生可能认为注射后即刻也需拍片（观察肾实质显影）。但IVP中对比剂需经滤过过程，注射后即刻片缺乏诊断价值。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-043", "t": "多选题", "s": "关于骨骼系统X线摄影的体位选择原则，以下正确的是", "o": {"A": "四肢长骨摄影应至少包含一端关节，正侧位互相垂直", "B": "怀疑舟骨骨折，常规腕关节正侧位已足够，不需特殊体位", "C": "颈椎外伤患者首选颈椎CT，在排除不稳定骨折后方可行颈椎X线摄影", "D": "脊柱全长正侧位摄影用于评估脊柱侧弯，SID应≥180cm以减少放大失真", "E": "面骨骨折需拍摄Water位（顶颏位），用于评估上颌窦和眶底"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-05", "kp": "骨骼系统X线摄影体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → 骨骼系统X线摄影体位", "ex": "【为什么对】A正确：长骨摄片必须包含一端关节+正侧位90°垂直。C正确：颈椎外伤尤其不稳定骨折，X线体位摆放可能加重脊髓损伤，应首选CT。D正确：脊柱全长片需长SID（≥180cm）减轻几何放大和拼接误差。E正确：Water位是评估面中部骨折的标准体位。【为什么错】B错误：舟骨骨折常规腕关节正侧位极易漏诊（检出率仅约70%），必须加拍舟骨特殊位——手腕尺偏位（舟骨位），使舟骨长轴平行于探测器。", "tr": "B是经典考点——舟骨骨折因特殊解剖和血供特点漏诊后果严重。必须加拍“舟骨位”（腕关节尺偏、后前位、球管向头侧倾斜10-20°）。“常规正侧位已足够”是明显错误信号。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-044", "t": "案例分析题", "s": "患者男性，35岁，因突发右侧胸痛伴呼吸困难2小时急诊入院。临床怀疑右侧气胸。作为放射科技师，以下处理方案正确的是", "o": {"A": "立即拍摄胸部后前位（PA）片，如患者不能站立则改拍卧位前后位（AP）", "B": "气胸在卧位片上表现为“深沟征”（deep sulcus sign）——患侧肋膈角加深、透亮度增高", "C": "呼气相胸片可增加气胸的检出敏感性——肺含气量减少而胸膜腔内气体量不变，使肺与气胸的密度对比加大", "D": "拍摄胸片后应立即电话通知临床医生初步结果（口头报告），无需等待正式诊断报告", "E": "如果胸片阴性但临床高度怀疑，建议行胸部CT检查（CT是检测少量气胸最敏感的方法）"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-06", "kp": "急诊胸部X线摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → 急诊胸部X线摄影", "ex": "【为什么对】五项处理方案均正确。A：PA立位为标准体位，无法站立改卧位AP。B：卧位时气体移至前外侧，“深沟征”是卧位气胸最重要X线征象。C：呼气相肺体积缩小而胸膜腔内气体量不变，气胸相对比例增大更易检测。D：急诊危重情况下技师发现明确异常应启动危急值通报流程。E：CT是检测少量气胸的金标准，敏感性接近100%。【为什么错】无错误选项。", "tr": "部分考生可能对C（呼气相摄影）存疑——认为常规是吸气相拍摄。但呼气相胸片是专门针对气胸检测的特殊技术。“深沟征”（B）是卧位气胸最重要的直接X线征象。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-045", "t": "单选题", "s": "关于子宫输卵管造影（HSG），以下描述错误的是", "o": {"A": "HSG应安排在月经干净后3-7天内进行", "B": "造影剂首选水溶性非离子型碘对比剂而非碘化油", "C": "正常输卵管在造影片上应显示对比剂从伞端溢出进入腹腔（“腹膜涂抹征”阳性）", "D": "HSG检查前应常规进行碘过敏皮试", "E": "一侧输卵管不显影可能系输卵管痉挛所致，可注射解痉药物后复查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-07", "kp": "妇科造影技术", "ch": "八、普通X线检查技术 → 3.X线造影检查 → 妇科造影技术", "ex": "【为什么对】本题要求选出错误选项。D表述错误——碘对比剂过敏皮试对预测严重过敏反应灵敏度和特异度均极低，国内外专业学会已不推荐常规进行碘过敏皮试。HSG使用水溶性非离子型碘对比剂，不需皮试。【为什么错】A正确：月经干净后3-7天进行可避免月经期干扰和排卵后可能的早期妊娠风险。B正确：水溶性对比剂安全性和便捷性优于碘化油。C正确：对比剂自伞端弥散入腹腔是输卵管通畅的直接证据。E正确：输卵管痉挛可导致假性阻塞，使用解痉剂后可复查确认。", "tr": "D关于碘过敏皮试的陷阱——ACR和ESUR均明确建议不推荐常规皮试。E中输卵管痉挛导致假性阻塞概念也很重要——HSG报告的阻塞中有相当部分是功能性痉挛。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-046", "t": "多选题", "s": "关于X线摄影中散射线的控制方法，以下正确的是", "o": {"A": "使用滤线栅（grid）是控制散射线最有效的方法，滤线栅比（grid ratio）越大散射消除能力越强", "B": "缩小照射野（准直器调节）可以减少组织受照体积，从而减少散射线产生", "C": "使用空气间隙技术（增加物体-探测器距离）可替代滤线栅，其原理是散射线各向同性“发散”而初级射线方向性好", "D": "KVp越高散射线产生越多，因此在满足穿透力的前提下应使用尽可能低的KVp", "E": "目前数字X线系统广泛采用虚拟滤线栅技术，可完全替代物理滤线栅"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-08", "kp": "散射线控制技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → 散射线控制技术", "ex": "【为什么对】A正确：滤线栅通过铅条选择性吸收斜入射散射线。栅比越大清除越彻底。B正确：缩小照射野→受照体积减小→散射线减少，是最基本的散射线控制手段。C正确：空气间隙技术利用散射线发散性与初级线方向性差异。D正确：KVp增高→康普顿散射占比增加→散射线增多。【为什么错】E错误：虚拟滤线栅（软件后处理算法）可在一定程度上抑制散射效应，但无法完全替代物理滤线栅——物理滤线栅在信号采集前就去除散射线，虚拟滤线栅后处理无法恢复已混入散射信号的低对比度信息损失。", "tr": "E使用“完全替代”绝对化措辞制造陷阱。虚拟滤线栅在移动DR、床旁摄影等场景可减少物理滤线栅使用，但物理滤线栅的“事前”优势是软件“事后”处理无法完全弥补的。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-047", "t": "单选题", "s": "下列哪项不是多层螺旋CT相对于单层螺旋CT的优势", "o": {"A": "扫描速度更快，Z轴覆盖范围更大", "B": "Z轴空间分辨率提高，可实现各向同性成像", "C": "球管热容量需求大幅降低", "D": "时间分辨率提高，有利于心脏成像", "E": "对比剂使用效率更高（相同碘量下强化效果更好）"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-01", "kp": "多层螺旋CT技术特点", "ch": "九、CT检查技术 → 1.CT检查基本知识 → 多层螺旋CT技术特点", "ex": "【为什么对】本题要求选出不是优势的选项。C表述错误——多层螺旋CT扫描速度更快、数据采集量更大，对球管热容量需求实际上是大幅增加而非降低。MDCT要求球管能承受连续长时间螺旋扫描（如多期增强、大范围CTA），球管热容量通常需要5-8MHU甚至更高。【为什么错】A、B、D、E均为MDCT实际优势。A：多排探测器同时采集实现快速大范围扫描。B：亚毫米准直+薄层重建实现各向同性。D：快速机架转速（≤0.35s）提高时间分辨率。E：扫描速度更快可在对比剂峰值浓度期间完成采集，使用效率更高。", "tr": "部分考生可能误认为MDCT扫描快→球管负荷小→热容量需求低（C）。但实际正相反：MDCT的快速连续扫描、多期增强等技术对球管热容量和散热能力提出了更高要求。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-048", "t": "单选题", "s": "在CT扫描参数中，降低管电流（mAs）最主要的影响是", "o": {"A": "降低空间分辨率", "B": "增加图像噪声", "C": "改变CT值", "D": "增加部分容积效应", "E": "降低时间分辨率"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-02", "kp": "CT扫描参数对图像质量的影响", "ch": "九、CT检查技术 → 1.CT检查基本知识 → CT扫描参数对图像质量的影响", "ex": "【为什么对】管电流（mAs）决定X线光子数量。降低mAs→到达探测器的光子数减少→量子噪声增加→图像噪声增大（噪声与1/√mAs成正比）。这是CT低剂量技术的核心权衡：降低辐射剂量（降低mAs）以增加噪声为代价。【为什么错】A空间分辨率主要由准直/层厚/重建算法/FOV/矩阵决定，与mAs关系不大（仅极低mAs时噪声严重致细节模糊）。C CT值由物质线衰减系数决定，与mAs无关（除非噪声导致测量误差增大）。D部分容积效应由层厚和病灶大小决定。E时间分辨率由机架转速决定。", "tr": "考生可能误选A——认为降低mAs会降低空间分辨率。mAs降低主要增加噪声（使颗粒感增强），但空间分辨率（边缘锐利度/细节分辨）主要由几何参数和重建算法决定。极低剂量时噪声可能淹没细节，但空间分辨率本身不直接由mAs决定。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-049", "t": "案例分析题", "s": "关于CT增强扫描的时相选择，以下正确的是", "o": {"A": "肝脏增强扫描常规采用三期扫描：肝动脉期（注射后20-30s）、门静脉期（60-70s）、延迟期（3-5min）", "B": "胰腺增强扫描的双期包括胰腺实质期（35-40s）和门静脉期（60-70s），胰腺实质期对胰腺癌检出最重要", "C": "肾脏增强扫描包括皮质期（25-30s）、皮髓质期（70-90s）和排泄期（3-5min）", "D": "主动脉CTA触发阈值通常设置在升主动脉100-150HU，采用自动触发（bolus tracking）技术", "E": "肝脏动脉晚期是肝细胞肝癌检出的最佳时相，此时肝癌强化最明显而肝实质尚未强化"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-03", "kp": "CT增强扫描时相技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → CT增强扫描时相技术", "ex": "【为什么对】五项均正确。A：肝脏三期扫描为标准方案（动脉晚期+门脉期+延迟期）。B：胰腺实质期（35-40s）对胰腺癌（低血供）与明显强化的胰腺实质对比最佳。C：肾脏三期皮质期-皮髓质期-排泄期为标准方案。D：主动脉CTA bolus tracking触发阈值通常100-150HU于升主动脉。E：肝动脉晚期（注射后约35s）肝癌由肝动脉供血强化而肝实质仍主要门静脉供血未强化，形成最大对比。【为什么错】无错误选项。", "tr": "E需注意——肝动脉晚期不等于动脉早期。肝动脉早期（20-25s）仅有动脉显影；动脉晚期（30-35s）肝癌强化达峰、门静脉开始显影但肝实质尚未明显强化——这才是肝癌最佳检出时相。“动脉晚期”这一精确表述是区分点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-050", "t": "案例分析题", "s": "患者男性，58岁，因胸痛伴气促行胸部CTA检查，临床怀疑急性主动脉综合征（AAS）。以下关于扫描方案和影像分析的描述，正确的有哪些", "o": {"A": "主动脉CTA应覆盖范围从胸廓入口至耻骨联合下缘（包括髂动脉分叉），以全面评估主动脉全程", "B": "扫描方向应为头-足方向，以配合对比剂血流方向和减少对比剂用量", "C": "应采用心电门控技术以消除主动脉根部和升主动脉的搏动伪影", "D": "主动脉壁间血肿（IMH）在CT平扫上表现为主动脉壁新月形或环形高密度增厚（“高密度新月征”），增强扫描无强化", "E": "穿透性主动脉溃疡（PAU）表现为主动脉壁“龛影”样突出，伴周围壁间血肿"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-04", "kp": "主动脉CTA检查技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 主动脉CTA检查技术", "ex": "【为什么对】五项均正确。A：主动脉CTA需覆盖全程（胸+腹主动脉至髂动脉分叉）。B：头-足方向扫描配合血流方向可减少对比剂用量并优化强化一致性。C：心电门控（前瞻性或回顾性）对消除主动脉根部搏动伪影至关重要，尤其在评估主动脉瓣和冠脉开口时。D：IMH为主动脉滋养血管破裂致壁内出血，平扫呈高密度新月征（急性期CT值60-70HU），增强无强化是与主动脉夹层鉴别核心。E：PAU是主动脉粥样硬化斑块穿透内膜形成溃疡，表现为壁龛影样突出。【为什么错】无错误选项。", "tr": "AAS三种类型（主动脉夹层、IMH、PAU）的CT鉴别特征是高频考点：夹层=内膜片+双腔；IMH=壁内高密度新月征+无内膜片+无强化；PAU=溃疡龛影+壁间血肿。三者可共存或转化。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-051", "t": "单选题", "s": "颅脑CT扫描的基线（OM线）是指", "o": {"A": "眶下缘-外耳道上缘连线", "B": "眶上缘-外耳道下缘连线", "C": "眶下缘-外耳道下缘连线", "D": "眶上缘-外耳道上缘连线", "E": "鼻根-枕外隆凸连线"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-05", "kp": "颅脑CT扫描技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 颅脑CT扫描技术", "ex": "【为什么对】OM线（Orbitomeatal line，听眦线）是指眶下缘（眶下缘最低点）至外耳道上缘的连线，是颅脑CT扫描最常用的基线。扫描层面通常与此线平行或向上倾斜10-15°（与眶耳线平行，即Reid基线），以减少晶状体辐射剂量。【为什么错】B眶上缘-外耳道下缘连线不是标准OM线。C眶下缘-外耳道下缘连线为Reid基线（人类学基线）。D不是标准基线。E鼻根-枕外隆凸连线不是CT基线。", "tr": "OM线与Reid基线容易混淆：OM线=眶下缘-外耳道上缘（听眦线）；Reid基线=眶下缘-外耳道下缘（下缘比上缘略低约1cm）。CT扫描常用OM线，脑血管造影常用Reid基线（眶下缘-外耳道下缘）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-052", "t": "案例分析题", "s": "关于冠状动脉CTA的检查技术要点，以下正确的是", "o": {"A": "患者心率控制是冠脉CTA成功的关键，理想心率应<65次/分且心律规整", "B": "扫描前3-5分钟舌下含服硝酸甘油可扩张冠脉提高血管显示质量", "C": "前瞻性心电门控（prospective gating）较回顾性门控辐射剂量显著降低，但要求稳定的低心率", "D": "重度钙化（Agatston积分>400）会显著影响冠脉CTA的管腔狭窄评估准确性", "E": "碘对比剂注射方案通常采用双筒高压注射器：对比剂50-80ml+生理盐水30-50ml（团注追踪触发）"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-06", "kp": "冠状动脉CTA扫描技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 冠状动脉CTA扫描技术", "ex": "【为什么对】五项均正确。A：心率<65bpm且规整是冠脉CTA理想条件（高心率需使用β受体阻滞剂控制）。B：硝酸甘油扩张冠脉提高显示质量，为常规操作。C：前瞻性门控仅采集心脏特定时相数据&辐射剂量大幅降低（可低至1-3mSv），但要求稳定低心率。D：重度钙化产生晕状伪影和Blooming效应，高估狭窄程度，是冠脉CTA的主要局限性。E：双筒注射器对比剂+盐水追注为标准方案。【为什么错】无错误选项。", "tr": "全选，考生需注意前瞻性门控与回顾性门控的选择：前瞻性门控=低剂量+需要稳定低心率（<65bpm且规整）；回顾性门控=高剂量+可回顾性选择最佳时相+可评估心功能。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-053", "t": "单选题", "s": "腹部CT检查中，口服对比剂的主要作用是", "o": {"A": "提高肝脏CT值", "B": "充盈胃肠道以区分肠管与腹腔占位", "C": "降低辐射剂量", "D": "减少呼吸运动伪影", "E": "增强胰腺强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-07", "kp": "腹部CT检查技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 腹部CT检查技术", "ex": "【为什么对】腹部CT口服对比剂（阳性对比剂如2%泛影葡胺溶液或中性对比剂如水）的主要作用是充盈胃肠道管腔，使肠管与腹腔占位、淋巴结、血管等结构可区分。未充盈的肠管可被误认为腹腔肿块或淋巴结。【为什么错】A口服对比剂不进入血液不提高肝实质CT值。C口服对比剂不降低辐射剂量。D口服对比剂不能减少运动伪影（肠蠕动伪影可用低张药如654-2控制）。E口服对比剂不增强胰腺强化（胰腺增强依赖静脉注射对比剂）。", "tr": "考生需区分口服对比剂和静脉对比剂的作用：口服对比剂→填充肠腔（区分肠管与腹腔结构）；静脉对比剂→显示血管和脏器灌注特征。两者目的完全不同不可混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-054", "t": "多选题", "s": "关于CT低剂量扫描技术，以下正确的是", "o": {"A": "自动管电流调制（ATCM）可根据患者体型和解剖部位自动调整mA，是降低辐射剂量最常用的技术", "B": "降低管电压（kVp）可显著降低辐射剂量（剂量∝kVp²），同时可提高碘对比剂的强化效果（因碘的K缘效应）", "C": "迭代重建（IR）算法可在相同剂量下降低图像噪声，或在保持相同噪声的前提下降低辐射剂量", "D": "器官剂量调制技术（如乳腺/甲状腺前屏蔽）可选择性降低敏感器官的辐射剂量", "E": "CT透视（fluoroscopy）引导下穿刺可以明显降低辐射剂量"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-08", "kp": "CT低剂量技术", "ch": "九、CT检查技术 → 1.CT检查基本知识 → CT低剂量技术", "ex": "【为什么对】A正确：ATCM是CT低剂量最基础和最常用技术（纵向+角度双调制）。B正确：降低kVp可大幅降低剂量（剂量∝kVp²）且碘对比剂在低kVp下因靠近K缘（33.2keV）而强化更明显（光电效应增强）。C正确：迭代重建是低剂量CT的核心技术——FBP在低剂量下噪声大，IR可有效降噪。D正确：器官剂量调制如乳腺屏蔽、甲状腺屏蔽等技术可选择性降低敏感器官剂量。【为什么错】E错误：CT透视引导下穿刺操作辐射剂量往往较高（持续曝光监控穿刺针位置），并非降低剂量的技术——反而是需要重点关注辐射防护的环节。", "tr": "E是典型陷阱——CT透视因持续曝光，操作者和患者的辐射剂量均较高，需要严格防护措施（如使用低mA透视模式、间歇性扫描代替连续透视等）。“引导穿刺”不等于“降低剂量”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-055", "t": "单选题", "s": "CT图像重建中，骨算法（bone algorithm）与标准算法的根本区别在于", "o": {"A": "使用不同的矩阵大小", "B": "使用不同的重建滤波函数（kernel）——骨算法强调高频信息", "C": "使用不同的FOV", "D": "使用不同的层厚", "E": "使用不同的窗宽窗位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-09", "kp": "CT图像重建算法", "ch": "九、CT检查技术 → 1.CT检查基本知识 → CT图像重建算法", "ex": "【为什么对】CT图像重建中，骨算法与标准算法的根本区别在于卷积核（kernel/filter）的选择——骨算法使用高频增强滤波函数（锐利核/sharp kernel），强化边缘和细节，适合显示骨质和肺纹理；标准算法使用平滑滤波函数（smooth kernel），降低噪声，适合软组织显示。【为什么错】A矩阵大小可独立设置，非算法区别。C FOV可独立调整。D层厚独立于重建算法。E窗宽窗位是显示参数（后处理）非重建参数，且骨窗（WW2000/WL500）和软组织窗（WW350/WL50）使用的是不同的窗值设定而非重建算法本身。", "tr": "考生常混淆重建算法（kernel）与窗口技术（WW/WL）：骨算法=锐利核（重建时使用），骨窗=宽窗宽高窗位（显示时使用）。两者经常配合使用但本质不同——重建算法影响原始数据的图像生成方式，窗口技术仅影响显示方式。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-056", "t": "多选题", "s": "关于CT尿路造影（CTU）的检查技术，以下正确的是", "o": {"A": "CTU通常包括平扫（KUB）、增强实质期和排泄期三个时相", "B": "排泄期扫描通常在注射对比剂后5-10分钟进行，以显示肾盂肾盏和输尿管的对比剂充盈", "C": "CTU的排泄期图像经MIP/VR后处理可生成类似IVP的“三维尿路造影”图像", "D": "为促进对比剂排泄，可在注射对比剂后静脉推注呋塞米（速尿）10-20mg", "E": "CTU的辐射剂量通常低于常规IVP检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-10", "kp": "CT尿路造影技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → CT尿路造影技术", "ex": "【为什么对】A正确：CTU标准方案=平扫+实质期（肾增强）+排泄期（尿路充盈）。B正确：排泄期通常在5-10分钟（正常肾功能），肾功能减退者需延迟更久。C正确：MIP/VR后处理可从排泄期数据生成类似IVP的尿路造影图像。D正确：呋塞米可促进利尿、加速对比剂排泄，优化尿路充盈（尤其输尿管中下段）。【为什么错】E错误：CTU辐射剂量通常显著高于IVP——CTU为多时相扫描（至少2-3次），总DLP可>20mGy·cm；而IVP为单片X线摄影，剂量较低。但CTU的诊断信息量也远大于IVP。", "tr": "E是常见误区——CTU虽然诊断价值高于IVP，但辐射剂量也明显更高。目前IVP已基本被CTU替代，但在某些场景（如年轻女性、需避免高辐射）IVP仍有一席之地。“通常低于IVP”不符合事实。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-057", "t": "案例分析题", "s": "患者男性，65岁，体检超声发现右肾中部一个约2cm的低回声结节。行肾脏CT平扫+多期增强检查。以下关于扫描方案和影像分析，正确的有哪些", "o": {"A": "肾脏CT扫描范围应包括双肾全部（从肾上级至肾下级），层厚≤3mm以利于小病灶检测", "B": "增强扫描皮质期（25-30s）可显示肾皮质强化而髓质尚未强化（皮质-髓质分界清晰），此期有利于肾皮质小肿瘤检测", "C": "肾透明细胞癌典型表现为{LQ}快进快出{RQ}——皮质期明显不均匀强化、皮髓质期强化程度迅速下降", "D": "CT平扫是检出肾结石最敏感的手段，所有肾结石（包括尿酸结石）均可在CT平扫上清晰显示", "E": "肾血管平滑肌脂肪瘤（AML）的CT诊断依据是病灶内含“肉眼可见”的脂肪密度（CT值<-10HU）"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-11", "kp": "肾脏CT检查技术", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → 肾脏CT检查技术", "ex": "【为什么对】A正确：肾脏CT小病灶检测需薄层（≤3mm）扫描。B正确：皮质期（25-30s）皮质强化、髓质未强化，形成皮质-髓质分界，有利于皮质小肿瘤检测。C正确：肾透明细胞癌典型强化模式为皮质期明显不均匀强化+皮髓质期/实质期强化迅速减退。E正确：AML确诊依据为病灶内含脂肪密度（CT值<-10HU），因AML含成熟脂肪组织+血管+平滑肌三种成分。【为什么错】D错误：并非所有肾结石均在CT平扫上清晰显示——茚地那韦（抗HIV药物）所致结石和少数纯尿酸结石在CT上可呈等密度或低密度而难以检出。虽然绝大多数（>95%）肾结石CT可清晰显示，但{D}使用“所有”一词绝对化。", "tr": "D使用“所有”绝对化措辞——虽然CT是检出肾结石最敏感手段（敏感性>95%），但茚地那韦结石和少数纯基质结石在CT上密度低可漏诊。考试中“所有”、“一定”等绝对词往往是错误信号。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-058", "t": "案例分析题", "s": "关于CT灌注成像的原理，以下描述错误的是", "o": {"A": "CT灌注使用连续动态扫描监测对比剂在兴趣组织中的首次通过过程", "B": "通过时间-密度曲线（TDC）可计算出血流量（BF）、血容量（BV）、平均通过时间（MTT）和表面通透性（PS）", "C": "CT灌注成像的辐射剂量较低，与常规CT平扫相当", "D": "脑CT灌注主要用于急性脑梗死缺血半暗带的评估", "E": "体部CT灌注可用于肿瘤血管生成的评价和抗血管生成治疗疗效评估"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-12", "kp": "CT灌注成像", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术 → CT灌注成像", "ex": "【为什么对】本题要求选出错误选项。C错误——CT灌注成像需在同一层面进行连续动态扫描（通常30-60次扫描），辐射剂量远高于常规CT平扫（可为常规平扫的10-50倍），是CT灌注的主要限制之一。【为什么错】A正确：CT灌注通过动态监测对比剂首次通过过程获取血流动力学参数。B正确：TDC分析可计算BF、BV、MTT、PS等定量参数（基于中心容积定理和去卷积模型）。D正确：脑CT灌注核心应用是急性脑梗死的缺血半暗带评估（CBF/CBV不匹配区）。E正确：体部CT灌注可定量评价肿瘤血管生成（BF、BV、PS增高提示血管丰富），用于抗血管生成治疗疗效评估。", "tr": "CT灌注辐射剂量高是其重要缺点，考生容易低估——因涉及连续动态扫描（每次扫描间隔1-3秒，持续40-60秒），总扫描次数多，辐射剂量远远超过常规检查。这也是限制CT灌注广泛应用的主要因素之一。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-059", "t": "多选题", "s": "关于CT引导下穿刺活检，以下正确的是", "o": {"A": "CT引导的优势在于精确定位、可避开重要结构（大血管、肠道等）", "B": "穿刺路径设计应遵循最短距离原则，同时避开叶间裂、大血管和重要脏器", "C": "肺内小结节（<1cm）穿刺时，气胸是最常见的并发症", "D": "使用同轴穿刺针技术可一次穿刺多次取样，提高诊断率并降低并发症", "E": "凝血功能异常（INR>1.5，PLT<50×10⁹/L）不是穿刺活检的禁忌，可常规进行"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-13", "kp": "CT引导下介入技术", "ch": "九、CT检查技术 → 3.检查方法 → CT引导下介入技术", "ex": "【为什么对】A正确——CT引导提供三维解剖信息，可精确定位并设计避开大血管、肠道等危险结构的路径。B正确——最短距离且避开叶间裂、大血管与重要脏器是穿刺路径设计基本原则。C正确——肺小结节（<1 cm）穿刺气胸发生率约20%–30%，是最常见并发症。D正确——同轴针技术一次置管可多次取样，提高诊断率并降低反复穿刺所致气胸/出血。【为什么错】E错误——凝血功能障碍（INR>1.5或PLT<50×10⁹/L）显著增加穿刺后出血风险，属相对禁忌证，须先纠正凝血指标再施术，绝非“可常规进行”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——凝血功能障碍（INR>1.5或PLT<50×10⁹/L）显著增加穿刺后出血风险，属相对禁忌证，须先纠正凝血指标再施术，绝非“可常规进行”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-060", "t": "单选题", "s": "以下关于螺距（pitch）的描述，错误的是", "o": {"A": "螺距=进床速度（mm/圈）/准直宽度（mm）", "B": "螺距增大可缩短扫描时间、减少辐射剂量", "C": "螺距增大会导致Z轴空间分辨率下降和部分容积效应增加", "D": "螺距>1时扫描存在数据间隙，需通过插值填补", "E": "螺距为0表示螺旋扫描，螺距为1表示轴向扫描"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-14", "kp": "CT螺距概念", "ch": "九、CT检查技术 → 1.CT检查基本知识 → CT螺距概念", "ex": "【为什么对】本题要求选错误选项。E错误——螺距（pitch）是螺旋扫描参数，定义为进床速度/准直宽度。pitch>0即为螺旋扫描，pitch=0不存在（没有进床即不是螺旋扫描）。轴向扫描不涉及螺距概念。螺距=1表示进床速度等于准直宽度（相邻螺旋圈刚好衔接），螺距<1表示重叠扫描（剂量增高），螺距>1表示数据有间隙。【为什么错】A正确：螺距标准定义。B正确：螺距增大→扫描覆盖更快→扫描时间短、辐射剂量降低。C正确：螺距增大→Z轴采样密度降低→SSP展宽→Z轴分辨率下降。D正确：螺距>1时螺旋圈间存在数据间隙，需通过360°或180°插值算法重建缺失数据。", "tr": "E中“螺距为0”和“螺距为1表示轴向扫描”均为概念错误：轴向扫描（步进式）根本不涉及螺距概念。简单记忆：pitch=进床速度/准直宽度，pitch>0即为螺旋扫描。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-061", "t": "单选题", "s": "以下哪项是MRI检查的绝对禁忌证", "o": {"A": "体内有心脏起搏器（非MRI兼容型）", "B": "金属烤瓷牙", "C": "人工髋关节置换术后（非磁性材料）", "D": "宫内节育器", "E": "冠状动脉支架（术后>6周）"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-01", "kp": "MRI禁忌证与安全筛查", "ch": "十、MR检查技术 → 1.MR检查准备 → MRI禁忌证与安全筛查", "ex": "【为什么对】非MRI兼容型心脏起搏器是MRI检查的绝对禁忌证——强磁场可能导致起搏器功能紊乱（导线感应电流、簧片开关误触发、电池耗竭等），危及生命。现代MRI兼容起搏器（MR Conditional）在特定条件下可安全检查。【为什么错】B金属烤瓷牙通常为镍铬合金或贵金属，虽可产生伪影但不属绝对禁忌。C非磁性材料人工关节（钛合金等）在MRI中是安全的。D宫内节育器（多数为铜或含塑料）在1.5T及以下场强通常安全（>3.0T需确认）。E冠脉支架（裸金属或DES）术后>6周通常安全（已完全内皮化），多数现代支架为MRI兼容。", "tr": "考生需严格区分绝对禁忌证与相对禁忌证。非MRI兼容起搏器=绝对禁忌；金属植入物需分情况判断：非铁磁性材料（钛合金、镍钛合金等）=安全；铁磁性材料（部分老旧动脉瘤夹等）=绝对禁忌。多数现代植入物标注MRI Conditional。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-062", "t": "多选题", "s": "关于MRI检查的安全管理，以下正确的是", "o": {"A": "所有进入MRI扫描室的人员（包括陪护家属和医务人员）都必须经过严格的安全筛查", "B": "MRI扫描室的强磁场始终存在（24h/7d），即使未进行扫描时磁场也不会关闭", "C": "1高斯线（1 G line）是MRI扫描室的安全控制边界，起搏器佩戴者严禁进入1G线以内", "D": "造影剂过敏反应在MRI增强检查中也可能发生（钆剂过敏），扫描室应配备急救设备", "E": "金属异物（如眼内铁屑、体内弹片）在MRI检查中可能发生移位或产热导致组织损伤"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-02", "kp": "MRI安全管理", "ch": "十、MR检查技术 → 1.MR检查准备 → MRI安全管理", "ex": "【为什么对】A正确——所有进入扫描室人员（含陪护与医务）均须经过严格金属与植入物筛查。B正确——超导MRI主磁场7×24 h始终存在，即使不扫描也不关闭。D正确——钆剂虽过敏率远低于碘剂，仍可发生过敏反应，扫描室须配备急救设备。E正确——铁磁性异物（眼内铁屑、体内弹片）在强磁场中可受力移位或产热，造成组织损伤。【为什么错】C错误——MRI扫描室公认的安全控制边界是5高斯线（5 G line，约0.5 mT），而非1高斯线；高风险铁磁性植入物（如部分起搏器）佩戴者严禁进入5 G线以内区域。", "tr": "本题已将原“全选”改为四项正确；注意选项C为刻意设置的错误项——MRI扫描室公认的安全控制边界是5高斯线（5 G line，约0.5 mT），而非1高斯线；高风险铁磁性植入物（如部分起搏器）佩戴者严禁进入5 G线以内区域。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-063", "t": "单选题", "s": "关于MRI功能成像技术中DWI（弥散加权成像）的原理，以下描述错误的是", "o": {"A": "DWI通过施加弥散敏感梯度（b值）来检测水分子的微观随机运动（布朗运动）", "B": "b值越高，DWI对弥散的敏感性越高，但图像信噪比越低", "C": "ADC图可以消除T2穿透效应的影响，真实反映组织的弥散受限程度", "D": "恶性肿瘤通常表现为DWI高信号+ADC高信号（ADC值升高）", "E": "脑脓肿与脑肿瘤坏死囊变的鉴别中，DWI/ADC具有重要价值"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-03", "kp": "弥散加权成像原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → 弥散加权成像原理", "ex": "【为什么对】本题要求选错误选项。D错误——恶性肿瘤因细胞密度高、核浆比大、细胞外间隙减小，水分子弥散受限，表现为DWI高信号+ADC低信号（ADC值降低），而非ADC高信号。【为什么错】A正确：DWI基础是Stejskal-Tanner脉冲梯度序列检测水分子弥散。B正确：高b值提高弥散权重但降低SNR。C正确：ADC图通过至少两个b值计算得出，可去除T2穿透效应（T2 shine-through），真实反映弥散受限。E正确：脑脓肿腔内含黏稠脓液（大量蛋白和多核白细胞）弥散受限→DWI高信号/ADC低；肿瘤坏死囊变多为清亮液体→DWI低信号/ADC高。这是两者最重要的MRI鉴别点。", "tr": "D将恶性肿瘤的DWI/ADC特征说反——正确关系：恶性肿瘤=细胞密集+弥散受限=DWI高信号+ADC降低。ADC降低是恶性肿瘤的重要特征，良性病变ADC值通常正常或升高。记忆：“ADC降低=恶性”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-064", "t": "案例分析题", "s": "关于MRA（磁共振血管成像）技术，以下正确的是", "o": {"A": "时间飞跃法MRA（TOF-MRA）利用血液流入效应——未饱和的流入血液质子产生高信号", "B": "TOF-MRA对血流方向敏感，通常用于颅内动脉成像（Willis环MRA）", "C": "相位对比法MRA（PC-MRA）利用流动质子的相位变化进行血管成像，可同时提供流速定量信息", "D": "对比增强MRA（CE-MRA）使用钆剂缩短血液T1值，是目前主动脉和外周血管MRA的首选技术", "E": "TOF-MRA的主要缺点是血流信号丢失——涡流、湍流或缓慢血流可致信号丢失而“夸大”狭窄程度"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-04", "kp": "磁共振血管成像技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 磁共振血管成像技术", "ex": "【为什么对】五项均正确。A：TOF利用梯度回波序列中静止组织被反复RF激励而饱和（低信号），新鲜流入血液未饱和（高信号）形成血管对比。B：TOF-MRA是颅内动脉成像最常用技术（3D-TOF）。C：PC-MRA通过双极梯度编码检测流动质子相位变化，可定量流速，广泛用于脑脊液流量分析。D：CE-MRA使用钆剂缩短血液T1，不受血流方向/速度影响，是大血管MRA金标准。E：TOF-MRA最大缺点是血流相关信号丢失——涡流、湍流或极慢血流可致质子饱和而信号丢失，从而高估狭窄。【为什么错】无错误选项。", "tr": "全选。E中TOF高估狭窄是其最重要局限性——狭窄后湍流/涡流导致质子饱和信号丢失，在MRA上表现为信号中断，容易被{LQ}过度诊断{RQ}为重度狭窄或闭塞。结合原始图像和PC-MRA可减少此误判。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-065", "t": "案例分析题", "s": "患者女性，38岁，因反复头痛就诊。头颅MRI平扫+增强检查示：左侧额叶白质内多发小类圆形病灶，部分垂直于侧脑室分布（Dawson手指征），T1WI低信号、T2WI/FLAIR高信号，增强扫描部分病灶呈环形或开环状强化。DWI示部分病灶边缘高信号。", "o": {"A": "该MRI表现高度提示多发性硬化（MS），Dawson手指征是MS的典型特征", "B": "病灶垂直于侧脑室分布提示脱髓鞘病变沿脑室周围静脉走行", "C": "开环状强化提示病灶活动性（急性期），环形强化部分朝向白质侧开口", "D": "脊髓MRI检查对MS的诊断价值不大，可不予检查", "E": "该患者病灶在SWI（磁敏感加权成像）序列上病灶内静脉应显示不清"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-05", "kp": "头颅MRI检查与神经影像诊断", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 头颅MRI检查与神经影像诊断", "ex": "【为什么对】A正确：Dawson手指征（垂直于侧脑室的卵圆形白质病灶）是MS高度特征性表现。B正确：病灶沿脑室周围小静脉（室周静脉）走行，反映MS的静脉周围炎病理基础。C正确：开环状强化（open-ring sign）是MS活动期特征——环形强化不完整，开口朝向灰质/基底节侧。【为什么错】D错误：脊髓MRI对MS诊断价值极大——约80%-90%的MS患者存在脊髓病灶（颈髓最常见），脊髓MRI是MS诊断的重要组成部分（McDonald标准）。E错误：SWI上MS病灶内常可见中心静脉征（central vein sign）——病灶中心可见小静脉呈低信号穿行，是MS区别于其他白质病变的重要特征。SWI病灶内静脉显示不清与MS不符。", "tr": "D和E是关键陷阱。D中“脊髓MRI价值不大”与MS诊断标准严重不符——脊髓MRI是MS诊断常规检查。E中“SWI上静脉显示不清”与MS的中心静脉征特征相反——“中心静脉征”是MS区别于其他白质病变的新型影像标志。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-066", "t": "单选题", "s": "肝脏MRI检查中，以下哪种序列对肝内铁沉积的检测最敏感", "o": {"A": "T1WI同相位/反相位（in-phase/opposed-phase）双回波成像", "B": "T2*WI梯度回波序列", "C": "T2WI FSE序列", "D": "DWI序列", "E": "T1WI增强扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-06", "kp": "腹部MRI检查技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 腹部MRI检查技术", "ex": "【为什么对】T2*WI梯度回波序列对铁沉积最敏感——铁为超顺磁性物质，造成局部磁场不均匀→T2*显著缩短→信号明显降低。肝铁沉积（如血色素沉着症）在T2*WI上表现为肝脏信号弥漫性显著降低（黑肝），且T2*值可定量测量铁浓度。T2*WI GRE序列是肝铁检测和定量的金标准。【为什么错】A同反相位主要用于检测肝细胞内脂肪（脂肪肝）——反相位信号较同相位降低提示脂肪变性，不是铁检测首选。C T2WI FSE使用180°重聚焦脉冲可部分补偿磁场不均匀效应，对铁不如T2*敏感。D DWI也可显示铁沉积但不具特异性。E增强扫描不用于铁沉积检测。", "tr": "考生容易混淆肝铁沉积和肝脂肪变性的MR检测方法：铁沉积→T2*WI GRE（信号明显降低）+T2*定量；脂肪变性→同反相位双回波（反相位信号降低）+MRS/PDFF定量。两者检测序列完全不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-067", "t": "多选题", "s": "关于前列腺MRI（多参数MRI，mp-MRI），以下正确的是", "o": {"A": "mp-MRI包括T2WI、DWI/ADC、DCE（动态增强）三个核心序列，PI-RADS评分基于此三者", "B": "前列腺癌在T2WI上典型表现为周围带高信号背景中的局限性低信号区", "C": "DWI上ADC值显著降低（<800×10⁻⁶mm²/s）高度提示临床有意义的前列腺癌", "D": "DCE的阳性标准是病灶呈{LQ}快进快出{RQ}强化模式（早期快速强化+早期廓清）", "E": "mp-MRI主要用于已确诊前列腺癌的分期，不推荐用于初次穿刺前的病灶检测"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-07", "kp": "前列腺MRI检查技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 前列腺MRI检查技术", "ex": "【为什么对】A正确：PI-RADS v2.1基于T2WI+DWI+DCE三个核心序列进行评分。B正确：周围带正常组织T2WI高信号，癌灶呈低信号。C正确：ADC显著降低（<800或<900）是前列腺癌重要标志（细胞密集→弥散受限）。D正确：DCE阳性标准为病灶早期快速强化（wash-in）+早期廓清（wash-out），即“快进快出”。【为什么错】E错误：mp-MRI最重要的临床应用恰恰是初次穿刺前的病灶检测和定位——对临床怀疑前列腺癌（PSA升高、DRE异常）的患者，mp-MRI可在穿刺前定位可疑病灶，指导靶向穿刺（MRI-TRUS融合穿刺），显著提高临床有意义癌的检出率。", "tr": "E将mp-MRI的主要用途说反——mp-MRI核心价值在于“穿刺前”检测和定位，而非仅用于分期。PI-RADS系统正是为穿刺前风险分层而设计的。“不推荐用于初次穿刺前”与当前国际指南（EAU、NCCN、AUA）推荐严重不符。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-068", "t": "案例分析题", "s": "关于膝关节MRI检查的扫描方位，以下描述错误的是", "o": {"A": "矢状面是膝关节MRI最重要的扫描方位，通常以前交叉韧带（ACL）走行方向为扫描基线", "B": "冠状面用于评估内/外侧副韧带、半月板体部和关节软骨", "C": "横断面用于评估髌骨轨迹和关节积液", "D": "矢状面扫描层厚通常为3-4mm，以保证SNR和层面覆盖", "E": "膝关节MRI常规不需要冠状面扫描，矢状面+横断面即可满足诊断需求"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-08", "kp": "骨关节MRI检查技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 骨关节MRI检查技术", "ex": "【为什么对】本题要求选错误选项。E错误——膝关节MRI常规必须包括三个方位（矢状面+冠状面+横断面）。冠状面对评估内/外侧副韧带、半月板体部和关节软骨至关重要，不可省略。【为什么错】A正确：矢状面以ACL走行为基线（向前内侧倾斜约15°），可最佳显示ACL全长、半月板前后角。B正确：冠状面是评估侧副韧带和半月板体部的最佳方位。C正确：横断面评估髌股关节和积液。D正确：膝关节MRI矢状面层厚通常3-4mm（≤0.3mm像素）。", "tr": "膝关节MRI三方位常规扫描是不可省略的基本要求：矢状面→ACL/PCL+半月板前后角；冠状面→侧副韧带+半月板体部+软骨；横断面→髌股关节+积液。三者各有不可替代的诊断价值。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-069", "t": "单选题", "s": "关于MRI波谱成像（MRS）在脑肿瘤中的应用，以下描述正确的是", "o": {"A": "正常脑组织的NAA（N-乙酰天门冬氨酸）峰是神经元完整性的标志", "B": "Cho（胆碱）峰升高反映细胞膜合成/降解活跃，是肿瘤增殖的标志", "C": "高级别胶质瘤的典型MRS表现为NAA降低+Cho升高+“Lac（乳酸）/Lip（脂质）”峰出现", "D": "MRS可作为脑肿瘤与非肿瘤病变（如脱髓鞘、感染）鉴别的重要辅助手段", "E": "以上均正确"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-09", "kp": "MR波谱成像", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → MR波谱成像", "ex": "【为什么对】以上均正确。A：NAA几乎仅存在于神经元及其突起中，是神经元密度和功能完整性的标志——脑肿瘤（神经元被肿瘤细胞替代）→NAA降低。B：Cho峰反映细胞膜磷脂代谢，肿瘤细胞快速增殖→膜合成活跃→Cho升高。C：高级别胶质瘤→NAA降低+Cho升高+Lac（无氧糖酵解产物，反映缺氧/坏死）+Lip（脂质峰出现反映坏死）。D：MRS代谢物谱特征有助于鉴别肿瘤（NAA↓+Cho↑）与脱髓鞘（NAA可保留+Cho轻度升高）、感染/脓肿（出现特殊代谢物如乙酸、琥珀酸等）。【为什么错】见上述解析中各错误选项分析。", "tr": "本题选项E为以上均正确，需逐项核实。MRS各代谢物峰的临床意义：NAA=神经元标志；Cho=细胞膜增殖标志；Cr（肌酸）=能量代谢参考峰；Lac=无氧代谢/坏死；Lip=坏死/脂肪。脑肿瘤MRS特征：NAA↓+Cho↑+（高级别时Lac/Lip出现）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-070", "t": "多选题", "s": "关于心脏MRI（CMR）检查技术，以下正确的是", "o": {"A": "CMR是评价心脏结构和功能的金标准，可精确测量心室容积、射血分数和心肌质量", "B": "心肌延迟强化（LGE）使用钆剂注射后10-20分钟扫描，存活心肌不强化而纤维化/瘢痕心肌呈高信号", "C": "T2-STIR序列用于检测心肌水肿（如急性心肌炎、急性心梗）", "D": "CMR检查需要心电门控和呼吸门控配合，以消除心脏搏动和呼吸运动伪影", "E": "CMR在心律失常（如频发室早、房颤）患者中仍可获得完美的图像质量"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRI-10", "kp": "心脏MRI检查技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → 心脏MRI检查技术", "ex": "【为什么对】A正确：CMR是心功能测量的金标准（准确性优于超声心动图）。B正确：LGE原理——钆剂在正常心肌中被快速洗脱（存活心肌细胞膜完整），而纤维化/瘢痕心肌因细胞外间隙增大+洗脱缓慢而呈高信号。C正确：T2-STIR对组织游离水增加（水肿）敏感，可用于心肌水肿检测。D正确：CMR需心电门控（触发采集与心脏运动同步）+呼吸门控/屏气（消除呼吸运动伪影）。【为什么错】E错误：心律失常（频发室早、房颤等）会导致心电门控触发异常→数据采集时相不一致→图像出现严重运动伪影，是CMR的常见失败原因。中重度心律失常是CMR的相对禁忌证或限制。", "tr": "E使用“仍可获得完美图像质量”绝对化表述——心律失常恰恰是CMR最常见的技术失败原因。房颤患者CMR常因RR间期不等导致采集窗变化、数据不一致。实时CMR技术（如实时SSFP）可一定程度弥补，但空间和时间分辨率均低于门控采集。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-071", "t": "单选题", "s": "以下哪项不是DSA检查的禁忌证", "o": {"A": "严重碘对比剂过敏史", "B": "严重肾功能不全（eGFR<30ml/min/1.73m²）", "C": "穿刺部位局部感染", "D": "轻度高血压（血压150/90mmHg，控制可）", "E": "妊娠期"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-01", "kp": "DSA禁忌证与适应症", "ch": "十一、DSA检查技术 → 1.检查前准备 → DSA禁忌证与适应症", "ex": "【为什么对】本题要求选出不是禁忌证的选项。D——轻度高血压（150/90mmHg）在血压控制稳定情况下不是DSA的禁忌证，临床可安全进行检查。高血压并非DSA禁忌除非血压极高（如>180/110mmHg）增加穿刺出血风险。【为什么错】A严重碘过敏史是重要禁忌证需改用其他检查（如MRA）或在充分准备下使用钆剂/CO₂造影。B严重肾功能不全（eGFR<30）是碘对比剂使用相对禁忌需充分评估获益/风险+水化+减少对比剂用量。C穿刺部位感染是绝对禁忌（可能导致感染扩散入血）。E妊娠期是相对禁忌（电离辐射+碘对比剂对胎儿潜在危害），仅在获益明确大于风险时进行。", "tr": "考生需区分绝对禁忌和相对禁忌。A、B、C、E均为不同程度的禁忌（C为绝对禁忌），而D轻度高血压不是禁忌。需注意：严重高血压（>180/110mmHg）才是禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-072", "t": "单选题", "s": "在DSA脑血管造影中，颈内动脉造影的标准投照体位不包括", "o": {"A": "后前位（AP位/正位）", "B": "侧位", "C": "斜位（45°）", "D": "颅底位（颏顶位）", "E": "汤氏位（Towne位，30°前后位）"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-02", "kp": "脑血管DSA造影技术", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → 脑血管DSA造影技术", "ex": "【为什么对】本题要求选出不包括的体位。D颅底位（颏顶位）不是颈内动脉DSA造影的标准投照体位——此体位主要用于显示颅底骨结构和部分颅底病变，不是脑血管造影常规体位。【为什么错】A AP正位：显示大脑前动脉（ACA）、大脑中动脉（MCA）及Willis环前后位全貌。B侧位：显示ACA、MCA、大脑后动脉（PCA）的侧位走行，是脑血管造影最基本体位。C 45°斜位：分离ACA和MCA分支，减少血管重叠。E Towne位（30°前后位+头倾）：显示基底动脉系统（后循环）和静脉窦。A、B、C、E均为颈内动脉DSA造影标准体位。", "tr": "颅脑血管DSA标准投照体位：AP正位+侧位+斜位（45°LAO/RAO）+Towne位。颅底位主要用于颅骨病变而非脑血管造影。考生需熟悉各体位的显示优势。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-073", "t": "多选题", "s": "关于DSA肝脏血管造影技术，以下正确的是", "o": {"A": "腹腔干动脉造影是肝脏介入的常规起始步骤，通常在T12-L1水平寻找腹腔干开口", "B": "间接门静脉造影经肠系膜上动脉或脾动脉注射对比剂，通过静脉回流显示门静脉系统", "C": "肝动脉DSA造影可清晰显示肝内肿瘤的异常血管（肿瘤染色、动静脉瘘等）", "D": "DSA的旋转血管造影（3D-DSA）可从多角度观察血管，对动脉瘤、AVM等复杂病变的评估价值极高", "E": "门静脉主干完全阻塞不是TACE的禁忌证，反而可增强疗效"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-03", "kp": "腹部血管DSA技术", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → 腹部血管DSA技术", "ex": "【为什么对】A正确——腹腔干多起于T12–L1水平腹主动脉前壁，是肝脏介入的常规起始造影步骤。B正确——间接门静脉造影经肠系膜上动脉或脾动脉注药，经静脉回流显示门静脉系统。C正确——肝动脉DSA可显示肿瘤染色、新生血管、动静脉瘘等异常血管。D正确——3D-DSA（旋转采集+重建）生成三维血管模型，对动脉瘤、AVM等复杂病变评估价值极高。【为什么错】E错误——门静脉主干完全阻塞时肝实质缺乏门静脉供血，TACE（经动脉化疗栓塞）后正常肝组织难以代偿、肝衰竭风险极高，故属TACE禁忌证，而非“非禁忌、可增强疗效”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——门静脉主干完全阻塞时肝实质缺乏门静脉供血，TACE（经动脉化疗栓塞）后正常肝组织难以代偿、肝衰竭风险极高，故属TACE禁忌证，而非“非禁忌、可增强疗效”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-074", "t": "案例分析题", "s": "患者男性，72岁，因间歇性跛行6个月，临床怀疑下肢动脉硬化闭塞症，将行下肢动脉DSA。以下关于检查方案的描述，正确的有哪些", "o": {"A": "下肢动脉DSA通常采用步进式（bolus chase）技术，从腹主动脉分叉至足部一次造影完成全程", "B": "穿刺入路常规选择对侧股动脉逆行穿刺（cross-over技术），以利于双侧下肢动脉评估", "C": "对比剂注射方案：总量80-120ml，流率8-12ml/s，采用{ LQ}团注追踪{RQ}（bolus chase）技术", "D": "DSA主要并发症包括穿刺部位血肿、假性动脉瘤、对比剂肾病和远端栓塞", "E": "下肢动脉闭塞性病变的DSA表现包括管腔不规则狭窄、闭塞及侧支循环建立"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-04", "kp": "外周血管DSA技术", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → 外周血管DSA技术", "ex": "【为什么对】五项均正确。A：步进式DSA可一次注射跟踪对比剂从腹主动脉至足部，完成全程显影。B：对侧股动脉逆行穿刺+翻山（cross-over）是双侧下肢动脉评估的标准入路。C：下肢动脉DSA对比剂用量较大（因覆盖范围广），通常80-120ml+8-12ml/s。D：DSA主要并发症包括穿刺点并发症（血肿、假性动脉瘤、动静脉瘘）、对比剂肾病、血管损伤（夹层、破裂）、远端栓塞等。E：下肢动脉硬化闭塞的DSA典型表现为管腔不规则狭窄/闭塞+侧支循环形成+远端血流减慢。【为什么错】无错误选项。", "tr": "“步进式”技术需注意：对比剂追踪需精确匹配血流速度——若进床太快（超过对比剂流速）则远端血管不显影，太慢则近端对比剂已排空。另外步进式DSA辐射剂量较高，但可一次完成全程成像避免多次注射。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-075", "t": "单选题", "s": "关于DSA三维旋转血管造影（3D-RA）与常规2D-DSA的比较，以下描述错误的是", "o": {"A": "3D-RA通过C臂旋转采集（通常旋转200°）获得多角度投影数据，经重建生成三维血管模型", "B": "3D-RA可显著提高颅内动脉瘤的检出率，特别是小动脉瘤（<3mm）", "C": "3D-RA的辐射剂量和对比剂用量通常低于常规多角度2D-DSA", "D": "3D-RA图像可进行任意角度旋转观察，优化工作角度选择", "E": "3D-RA在动静脉畸形（AVM）的供血动脉和引流静脉评估中具有明显优势"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-05", "kp": "DSA技术新进展", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → DSA技术新进展", "ex": "【为什么对】本题要求选错误选项。C错误——3D-RA的辐射剂量通常高于常规单角度2D-DSA（因需连续旋转采集数百帧图像），但低于多次不同角度的2D-DSA总和。对比剂用量通常也较大（因旋转采集持续时间更长需维持血管内对比剂浓度）。【为什么错】A正确：3D-RA通过C臂200°旋转采集→重建三维容积数据。B正确：3D-RA对小动脉瘤（<3mm）检出率显著优于2D-DSA（消除血管重叠和角度依赖）。D正确：3D-RA可在工作站上任意角度旋转观察，帮助选择最佳工作角度。E正确：3D-RA对AVM的血管构筑（供血动脉+nidus+引流静脉）显示远优于2D-DSA。", "tr": "C是常见误区——虽然3D-RA可减少多次注射和多次不同角度DSA的需要（从而减少总对比剂和辐射），但单次3D-RA的剂量和对比剂通常不低于单次2D-DSA。需全面理解两者的比较维度。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-076", "t": "单选题", "s": "关于DICOM标准，以下描述错误的是", "o": {"A": "DICOM（Digital Imaging and Communications in Medicine）是医学数字成像和通信的国际标准", "B": "DICOM标准仅涵盖医学图像的存储格式，不包括传输和打印", "C": "DICOM文件包含图像数据和元数据（患者信息、检查参数等），采用标签（tag）结构", "D": "DICOM协议基于TCP/IP网络通信，支持存储（Storage）、查询/检索（Query/Retrieve）等服务类", "E": "DICOM一致性声明（Conformance Statement）是设备互联互通的重要参考文件"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-01", "kp": "DICOM标准", "ch": "十二、PACS技术 → 1.国际标准与规范 → DICOM标准", "ex": "【为什么对】本题要求选错误选项。B错误——DICOM标准涵盖范围极为广泛，不仅包括图像存储格式，还包括网络传输协议、打印管理、工作流管理（Modality Worklist, MPPS）、结构化报告等多种服务类。“不包括传输和打印”与事实严重不符。【为什么错】A正确：DICOM确为医学数字成像与通信国际标准（NEMA/ISO 12052）。C正确：DICOM文件使用标签（tag, 如0010,0010=患者姓名，0008,0020=检查日期）存储元数据和图像数据。D正确：DICOM网络服务基于TCP/IP，支持C-STORE（存储）、C-FIND（查询）、C-MOVE（检索）等。E正确：DICOM一致性声明详细列出设备支持的SOP类和选项，是互联互通的基础文档。", "tr": "DICOM标准的涵盖范围远不止图像格式——它是一个包含18+个部分的庞大标准体系，涵盖网络传输、存储、打印、工作流、安全、结构化报告等。考生需了解DICOM不是简单的图像文件格式（如JPEG/DICOM），而是完整的医学影像信息学框架。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-077", "t": "多选题", "s": "关于PACS（影像归档与通信系统）的系统组成，以下正确的是", "o": {"A": "PACS核心组成部分包括影像采集网关、PACS服务器（归档/数据库）、存储系统和诊断工作站", "B": "RIS（放射信息系统）与PACS的集成（RIS/PACS集成）是实现放射科数字化转型的关键", "C": "PACS存储架构通常仅采用两级存储（在线与离线），不存在近线存储", "D": "HIS/RIS/PACS的集成需要HL7标准支持，DICOM和HL7是PACS的两大核心通信标准", "E": "云PACS是当前发展趋势——将影像存储和部分应用迁移至云端，可降低本地存储压力并实现远程会诊"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-02", "kp": "PACS系统架构与组成", "ch": "十二、PACS技术 → 2.PACS发展与组成 → PACS系统架构与组成", "ex": "【为什么对】A正确——PACS核心包括影像采集网关、PACS服务器（归档/数据库）、存储系统与诊断工作站。B正确——RIS/PACS集成实现登记、排程、报告与影像的一体化，是放射科数字化转型关键。D正确——HIS/RIS/PACS集成以HL7（文本信息）与DICOM（影像）为两大核心通信标准。E正确——云PACS将存储与部分应用迁移云端，降低本地压力并支持远程会诊。【为什么错】C错误——PACS普遍采用三级存储模型：在线（FC/SAS，高速高成本）、近线（SATA/NL-SAS，中速中成本）、离线（磁带/光盘，长期归档低成本）；近线存储是兼顾访问速度与成本的关键层级，并非“无近线两级存储”。", "tr": "本题已将原“全选”改为四项正确；注意选项C为刻意设置的错误项——PACS普遍采用三级存储模型：在线（FC/SAS，高速高成本）、近线（SATA/NL-SAS，中速中成本）、离线（磁带/光盘，长期归档低成本）；近线存储是兼顾访问速度与成本的关键层级，并非“无近线两级存储”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-078", "t": "单选题", "s": "关于PACS影像压缩技术，以下描述正确的是", "o": {"A": "有损压缩（如JPEG、JPEG2000）可实现极高压缩比（10:1-30:1），但不适用于临床诊断（可能丢失诊断信息）", "B": "无损压缩（如JPEG-LS、JPEG2000 lossless）压缩比较低（约2:1-3:1），但完全保留影像诊断信息", "C": "DICOM标准支持JPEG、JPEG-LS、JPEG2000、RLE等多种压缩算法", "D": "影像压缩在PACS中主要用于长期归档以减少存储成本，短期在线存储通常使用非压缩格式以保证最快访问速度", "E": "以上均正确"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-03", "kp": "PACS影像压缩与存储", "ch": "十二、PACS技术 → 2.PACS发展与组成 → PACS影像压缩与存储", "ex": "【为什么对】以上均正确。A：有损压缩在极高压缩比下可能丢失诊断相关信息（尤其对纹理/细微结构的显示），不推荐用于初次诊断（但可用于临床浏览和教学）。B：无损压缩完全保留数据，但压缩比低（通常2:1-3:1）。C：DICOM标准支持多种压缩Transfer Syntax。D：PACS中近/在线存储通常保持非压缩或无损压缩以保证最快访问和最佳质量，长期归档可选择性使用有损压缩以节省成本。各选项均正确。【为什么错】见上述解析中各错误选项分析。", "tr": "本题A、B、C、D均为正确，选项E为以上均正确。有损压缩在临床实践中应用存在争议——ACR和CAR推荐诊断使用非压缩或无损压缩图像，有损压缩可能适合临床浏览和远程会诊场景。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-079", "t": "单选题", "s": "激光胶片打印机中，激光的作用是", "o": {"A": "加热胶片使其显影", "B": "曝光胶片上的感光层以形成潜影", "C": "读取胶片上的影像信息", "D": "定影胶片以稳定图像", "E": "干燥胶片以加速冲洗"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRINT-01", "kp": "激光打印技术", "ch": "十三、图像打印技术 → 1.激光成像 → 激光打印技术", "ex": "【为什么对】激光胶片打印机（laser imager）中，激光束按图像信号调制成不同强度，逐点扫描曝光胶片上的感光乳剂层，形成潜影（latent image），后续经过化学显影→定影→水洗→干燥等流程完成胶片成像。激光曝光是数字影像到胶片硬拷贝的关键步骤。【为什么错】A加热是热敏打印的原理（干式打印），非激光打印。C读取影像信息是扫描仪/CR读取器的功能。D定影使用化学定影液（硫代硫酸铵等）。E干燥是胶片冲洗的最后一步。", "tr": "考生容易混淆激光打印和热敏打印的原理：激光打印=激光曝光感光胶片+化学冲洗（湿式）；热敏打印=加热头直接加热热敏胶片显色（干式、无需化学冲洗）。两种技术完全不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-080", "t": "多选题", "s": "关于医用干式打印技术（dry printing），以下正确的是", "o": {"A": "干式打印无需化学冲洗（显影/定影液），环保无废液排放", "B": "干式热敏打印使用热敏胶片，加热头（thermal head）直接加热使胶片微胶囊破裂而显色", "C": "干式激光打印使用光热敏胶片（photothermographic film），激光曝光后经加热处理显影", "D": "干式打印的图像质量和稳定性已可媲美传统湿式激光打印，已基本取代湿式打印成为主流", "E": "干式打印的Dmax（最大密度）和灰阶层次通常优于湿式激光打印"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRINT-02", "kp": "热敏与干式打印", "ch": "十三、图像打印技术 → 2.热敏成像技术 → 热敏与干式打印", "ex": "【为什么对】A正确：干式打印无液态化学品，操作简便、环保。B正确：干式热敏使用微胶囊热敏技术（如FUJI DryPix）——加热使微胶囊破裂释放染料。C正确：干式激光使用光热敏胶片（如Carestream DryView）——激光曝光+热显影（无湿式化学步骤）。D正确：干式打印已基本取代湿式成为主流。E错误：传统湿式激光打印的Dmax（>3.5）和灰阶层次通常略优于干式打印——湿式技术的灰阶动态范围和最大密度仍有微弱优势，但干式打印已能满足临床诊断需求。【为什么错】E将两者优劣说反或过度绝对化。", "tr": "E是常见误区——传统湿式激光打印在Dmax和灰阶方面的物理极限仍略高于干式（尤其在大幅面高精度打印），但差别已极小不影响临床诊断。“通常优于”过度绝对化了干式的优势。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "概述", "页": 355}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-081", "t": "单选题", "s": "数字乳腺断层融合摄影（DBT）相较于传统二维乳腺X线摄影（2D MG）的主要优势是", "o": {"A": "显著降低辐射剂量", "B": "消除乳腺组织重叠效应，提高病变检出率和降低召回率", "C": "完全替代超声作为乳腺筛查工具", "D": "图像采集速度大幅提高", "E": "不需要压迫乳腺"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DIG-01", "kp": "数字乳腺断层融合摄影", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT（3D乳腺摄影）核心优势：通过X线管弧形运动采集多个低剂量投影（通常15-25个角度），经重建生成一系列薄层（1mm）图像，有效消除传统2D摄影中致密乳腺的组织重叠效应——使重叠掩盖的病变可见（提高检出率），使重叠伪像导致的假阳性减少（降低召回率）。多项大型临床试验证实DBT可将召回率降低15%-40%。【为什么错】A DBT辐射剂量与2D相当或略高。C DBT不能替代超声——超声在致密乳腺补充筛查、囊实性鉴别方面仍有不可替代价值。D DBT采集时间与2D相似（均需数秒）。E DBT仍需压迫乳腺（标准操作），压迫对保证图像质量和降低剂量至关重要。", "tr": "DBT主要解决的是乳腺影像学根本困境——组织重叠。致密乳腺中2D MG敏感度可降至40-50%，DBT通过薄层重建消除重叠，显著提升致密乳腺中病变的检出。但DBT不能替代超声，也不解决所有问题（如微钙化显示在2D合成图上可能略逊于直接2D）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-082", "t": "多选题", "s": "关于双能X线骨密度仪（DXA）的技术原理与应用，以下正确的是", "o": {"A": "DXA利用高能和低能两种X线束穿透人体，利用骨骼和软组织在不同能量下的衰减差异区分两者", "B": "DXA是目前WHO推荐的骨质疏松诊断金标准，诊断基于T-score（与年轻健康成人峰值骨密度比较的标准差）", "C": "按照WHO标准，T-score≤-2.5可诊断为骨质疏松症", "D": "DXA测量部位常规包括腰椎（L1-L4）和髋部（股骨颈和全髋），前臂作为替代部位", "E": "DXA的辐射剂量与胸部CT相当（约数mSv）"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DIG-02", "kp": "双能X线骨密度仪", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → 双能X线骨密度仪", "ex": "【为什么对】A正确——DXA利用骨骼与软组织在高、低能X线下衰减差异，经算法分离骨矿与软组织。B正确——DXA是WHO推荐的骨质疏松诊断金标准，基于T-score（与年轻成人峰值骨密度比较的标准差）。C正确——按WHO标准T-score≤−2.5诊断为骨质疏松。D正确——常规测量腰椎（L1–L4）与髋部（股骨颈、全髋），前臂为替代部位。【为什么错】E错误——DXA辐射剂量极低（约1–10 μSv），显著低于胸部X线摄影（约50–100 μSv）与胸部CT（数mSv），而非“与胸部CT相当”；低剂量正是其作为人群筛查工具的优势。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——DXA辐射剂量极低（约1–10 μSv），显著低于胸部X线摄影（约50–100 μSv）与胸部CT（数mSv），而非“与胸部CT相当”；低剂量正是其作为人群筛查工具的优势。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-083", "t": "单选题", "s": "关于光子计数探测器CT（PCCT）相较于传统能量积分探测器CT的优势，以下描述错误的是", "o": {"A": "光子计数可直接区分不同能量的光子，实现多能谱成像", "B": "光子计数可消除电子噪声，显著提升低剂量下的图像质量", "C": "光子计数探测器的空间分辨率通常低于传统能量积分探测器", "D": "光子计数可实现组织成分的定量分析（如痛风结节中尿酸钠的识别）", "E": "光子计数探测器具有内在的光谱/能量分辨能力，无需额外硬件即可实现能谱成像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DIG-03", "kp": "光子计数CT技术", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → 光子计数探测器CT技术", "ex": "【为什么对】本题要求选错误选项。C错误——光子计数探测器（PCD）的空间分辨率通常高于传统能量积分探测器（EID），而非更低。因为PCD无需分隔栅（septa），像素可做得更小且无光学串扰；同时PCD对小像素中电荷共享效应可通过校正算法处理，实现更高空间分辨率。【为什么错】A正确：PCD可设定能量阈值，将光子按能量分bin计数，天然实现多能谱成像。B正确：PCD可设定低能阈值剔除电子噪声（噪声光子能量低于阈值不计数），在低剂量下图像质量显著优于EID。D正确：PCD多能谱数据可实现物质鉴别和定量分析（如痛风结节中的尿酸钠vs钙盐）。E正确：PCD能谱能力来自探测器本身（无需双层探测器或kVp切换等额外硬件）。", "tr": "C将PCD和EID的空间分辨率优劣颠倒——PCD因无分隔栅、像素更小，空间分辨率更高。这是PCD最重要的技术优势之一（可实现超高分辨率CT，像素尺寸可小至0.15-0.2mm）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-084", "t": "多选题", "s": "关于数字化X线摄影技术的最新进展，以下正确的是", "o": {"A": "无线平板探测器（wireless FPD）使DR系统更加便携和灵活，在床旁摄影和术中应用具有显著优势", "B": "动态DR（Dynamic DR）仅能进行静态摄影，不具备透视与动态序列采集功能", "C": "人工智能辅助X线诊断（如AI肺结节检测、骨折检测）可提高放射科医师的诊断效率和准确性", "D": "超高分辨率DR系统（使用微焦点X线管和小像素探测器）可实现空间分辨率>10lp/mm，用于微细结构成像", "E": "数字化X线技术的发展方向之一是降低辐射剂量——通过新型探测器材料、高效图像处理算法和AI降噪技术的综合应用"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DIG-04", "kp": "数字化X线技术发展趋势", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → 数字化X线技术发展趋势", "ex": "【为什么对】A正确——无线平板探测器（wireless FPD）使DR便携灵活，床旁与术中优势显著。C正确——AI辅助X线诊断（肺结节、骨折检测等）可提升医师效率与准确性，已获多项FDA/CE认证。D正确——超高分辨率DR（微焦点管+小像素探测器）空间分辨率可>10 lp/mm，用于微细结构成像。E正确——降低辐射剂量是数字化X线核心方向，依赖新型探测器材料、高效算法与AI降噪的综合策略。【为什么错】B错误——动态DR（Dynamic DR）的核心特征正在于兼具摄影与连续透视/动态序列采集能力，可一次检查中实时观察吞咽、关节运动等并捕获动态影像，而非“仅能静态摄影”。", "tr": "本题已将原“全选”改为四项正确；注意选项B为刻意设置的错误项——动态DR（Dynamic DR）的核心特征正在于兼具摄影与连续透视/动态序列采集能力，可一次检查中实时观察吞咽、关节运动等并捕获动态影像，而非“仅能静态摄影”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-085", "t": "单选题", "s": "关于DSA图像融合技术，以下描述错误的是", "o": {"A": "DSA图像可与CT/MR图像进行融合，实现解剖与功能信息的叠加显示", "B": "三维路图（3D roadmap）技术将3D血管影像与实时透视叠加，引导导管/导丝操作", "C": "DSA-CT融合图像可用于介入治疗计划制定和术中导航", "D": "图像融合技术可完全替代多角度DSA采集，从而显著降低辐射剂量", "E": "锥形束CT（CBCT）与DSA的结合是当前介入影像的重要发展方向"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-01", "kp": "DSA图像融合与导航技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】本题要求选错误选项。D错误——图像融合技术不能完全替代多角度DSA采集。图像融合基于已有的CT/MR/3D-DSA数据，只能在已有数据基础上叠加信息，无法提供实时血流动力学信息（如血流速度、侧支循环动态等），因此不能完全替代DSA的多角度实时采集。【为什么错】A正确：DSA与CT/MR融合可实现血管解剖与周围组织关系的同时显示。B正确：3D roadmap是DSA最实用的导航技术之一——将3D血管模型与实时透视匹配，即使C臂角度变化也能自动更新。C正确：融合图像在介入规划中价值极高。E正确：CBCT（C臂CT）与DSA在同一设备上结合，实现一站式介入诊疗。", "tr": "D使用“完全替代”绝对化措辞——图像融合是已有数据的叠加显示，无法替代实时的、功能性的DSA采集。融合技术的价值在于“增强”而非“替代”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-086", "t": "单选题", "s": "关于低剂量DSA技术，以下描述错误的是", "o": {"A": "降低脉冲频率（f/s）可从15f/s降至7.5f/s甚至更低，是降低DSA辐射剂量最直接的方法", "B": "使用低剂量模式（降低每帧mA）可在保持图像质量的前提下降低辐射剂量", "C": "DSA辐射剂量的降低可通过降低对比剂浓度来补偿图像质量损失", "D": "图像降噪算法（如实时自适应降噪、时域滤波）是低剂量DSA的重要辅助技术", "E": "DSA操作者辐射防护的最基本原则是时间、距离和屏蔽"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-02", "kp": "DSA低剂量与辐射防护", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → DSA低剂量与辐射防护", "ex": "【为什么对】本题要求选错误选项。C错误——降低DSA辐射剂量会导致图像噪声增加、信噪比下降，这需要通过图像降噪算法来补偿，而非通过降低对比剂浓度（降低对比剂浓度会进一步恶化血管显影质量，适得其反）。对比剂浓度和辐射剂量是两个独立参数。【为什么错】A正确：降低帧率是最直接的降剂量方法。B正确：低剂量模式（降低管电流/脉冲宽度）可有效降低辐射。D正确：图像降噪算法（如自适应空间-时间滤波）是低剂量DSA不可或缺的后处理手段。E正确：时间、距离、屏蔽是放射防护基本原则，对操作者同样适用（鉛屏、铅衣、距离控制）。", "tr": "C错误地将降低对比剂浓度与辐射剂量补偿关联——这是两个独立维度：辐射剂量影响噪声水平（需降噪算法补偿）；对比剂浓度影响血管显影密度（需调整注射参数）。两者不能互相替代。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-087", "t": "多选题", "s": "关于DSA新技术进展，以下正确的是", "o": {"A": "4D-DSA技术可提供时间分辨的三维血管影像，动态显示血流过程（如AVM的供血时序）", "B": "双能DSA可减少骨性结构伪影，提高颅底/脊柱区域血管的显示质量", "C": "CO₂血管造影可作为肾功能不全患者碘对比剂的替代方案，尤其适用于腹主动脉和外周血管成像", "D": "平板探测器DSA的空间分辨率较传统影像增强器DSA有显著提升（像素尺寸可<0.2mm）", "E": "双能DSA消除骨性伪影的核心机制与X线能量无关，仅靠两次曝光的图像配准与减影即可实现"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-03", "kp": "DSA新技术进展", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → DSA新技术进展", "ex": "【为什么对】A正确——4D-DSA提供时间分辨的三维血管影像，可动态显示血流过程（如AVM供血时序）。B正确——双能DSA利用高低能量减影消除骨性重叠，提升颅底/脊柱区域血管显示。C正确——CO₂血管造影无肾毒性、无过敏，是肾功能不全患者（尤腹主动脉、外周血管）的有效替代。D正确——平板探测器DSA像素尺寸可<0.2 mm，空间分辨率较影像增强器DSA显著提升。【为什么错】E错误——双能DSA（dual-energy DSA）正是利用碘、骨与软组织在高低两种X线能量下衰减系数的差异，经能量加权减影选择性去除骨性结构；其骨去除效果本质上依赖于\"能量\"维度，而非单纯的两次曝光配准减影（后者是传统时间减影的原理）。故\"与X线能量无关\"之说错误。", "tr": "本题已将原\"全选\"改为四项正确；注意选项E为刻意设置的错误项——双能DSA骨去除依赖高低能量衰减差异（能量维度），并非与能量无关；\"仅靠两次曝光配准减影\"是传统单能时间减影的原理。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-088", "t": "案例分析题", "s": "某介入中心计划升级DSA设备，考虑引入以下新技术。作为技术评估组成员，以下哪些技术的描述是正确的", "o": {"A": "3D旋转血管造影+路图导航技术可显著提高颅内动脉瘤介入栓塞的精确性和安全性", "B": "支架精细显影（StentBoost）技术通过图像增强算法提高冠脉/颅内支架的可视化程度", "C": "双平板DSA系统可在单次注射下同时获得正位和侧位两个投影，减少对比剂用量和辐射", "D": "CBCT（锥形束CT）功能可在DSA设备上实现CT样成像，用于术中评估出血和器械位置", "E": "人工智能辅助DSA技术目前已被FDA批准用于全自动介入手术操作"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-04", "kp": "DSA设备升级与技术评估", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → DSA设备升级与技术评估", "ex": "【为什么对】A正确：3D roadmap将重建血管模型与实时透视融合，大幅提高动脉瘤栓塞的精确度和安全性（减少术中破裂风险）。B正确：StentBoost（或类似技术如ClearStent）通过运动校正和多帧叠加提高支架可视化。C正确：双平板（Biplane）系统可在一次注射下获得双平面影像，减少对比剂注射次数和总量。D正确：CBCT功能已广泛应用于DSA设备（如西门子syngo DynaCT、飞利浦XperCT），提供术中CT样成像。【为什么错】E错误：目前AI辅助DSA技术仍限于辅助诊断（如血管狭窄自动检测、动脉瘤识别）和图像优化（降噪、融合），尚未达到“全自动介入手术操作”的水平。介入手术的全自动化涉及极其复杂的机器人操作和临床决策，目前仍处于研究阶段。", "tr": "E使用“全自动介入手术操作”过度夸大AI在DSA中的当前应用水平——AI在DSA中目前主要是“辅助工具”（辅助诊断、图像优化），而非替代术者进行全自动操作。机器人辅助血管介入技术（如CorPath GRX）可远程操控导丝/导管，但仍需术者全程控制，非“全自动”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-089", "t": "单选题", "s": "关于双能量CT（DECT）的基本原理，以下描述正确的是", "o": {"A": "双能量CT利用同一种X线能量在不同时间点扫描获得两组数据", "B": "双能量CT利用两种不同能量的X线（高kVp和低kVp）扫描同一部位，利用物质对不同能量X线衰减的差异进行物质分离", "C": "双能量CT必须在两个不同的CT设备上完成", "D": "双能量CT只能分离两种物质（如碘和水）", "E": "双能量CT的辐射剂量是常规CT的两倍"}, "d": "难", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-01", "kp": "双能量CT基本原理", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → 双能量CT基本原理", "ex": "【为什么对】B正确——双能量CT的基本原理是利用两种不同能量的X线（如80kVp和140kVp，或100kVp和Sn140kVp）扫描同一解剖部位，根据不同物质（如碘、钙、水、脂肪等）在两种能量下衰减差异的规律，通过数学分解算法（三物质分解法等）实现物质分离和定量分析。【为什么错】A错误：双能量CT是同一时间或极短间隔内用两种能量扫描，非不同时间点。C错误：DECT可在单台设备上完成（双源CT、快速kVp切换、双层探测器等）。D错误：DECT理论上可分离三种物质（如脂肪、软组织和碘），三物质分解是DECT的经典算法。E错误：现代DECT的辐射剂量与常规单能CT相当或仅略高。", "tr": "DECT的四种实现方式容易混淆：①双源CT（两个球管同时不同kVp）；②快速kVp切换（单个球管快速切换kVp）；③双层探测器（单kVp照射，探测器上下层分别接收低/高能光子）；④双旋扫描（两次扫描不同kVp）。各方式各有优缺点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-090", "t": "多选题", "s": "双能量CT在临床中的典型应用包括", "o": {"A": "虚拟平扫（VNC）——从增强数据中减去碘信息生成虚拟平扫图像，可减少一次平扫的辐射剂量", "B": "碘图（iodine map）——定量显示组织碘摄取量，用于肿瘤灌注和血管评估", "C": "痛风结石成分分析——鉴别尿酸钠结石（可药物溶解）与钙盐结石（需碎石/手术）", "D": "肺灌注成像——利用碘图评估肺栓塞导致的灌注缺损", "E": "骨髓水肿检测——双能CT可直接显示骨髓水肿的病理形态，与MRI具有同等软组织对比"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-02", "kp": "能量CT临床应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → 能量CT临床应用", "ex": "【为什么对】A正确——虚拟平扫（VNC）从增强数据数字化去除碘，生成类平扫图像，可省去平扫、降低约30%辐射。B正确——碘图定量组织碘浓度（mgI/ml），用于灌注与血供评估。C正确——DECT鉴别尿酸（非钙）结石与钙盐结石，尿酸结石可药物溶解，避免不必要手术。D正确——肺碘图显示栓塞供血区的灌注缺损，实现CT肺灌注成像。【为什么错】E错误——双能CT对骨髓水肿为间接检测：经虚拟去钙（VNCa）去除骨小梁钙质后，水肿区因含水呈相对高密度而凸显；其软组织对比远不及MRI（MRI为骨髓水肿诊断金标准），并非“直接显示且等同MRI”。", "tr": "本题已将原“全选”改为四项正确；注意选项E为刻意设置的错误项——双能CT对骨髓水肿为间接检测：经虚拟去钙（VNCa）去除骨小梁钙质后，水肿区因含水呈相对高密度而凸显；其软组织对比远不及MRI（MRI为骨髓水肿诊断金标准），并非“直接显示且等同MRI”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-091", "t": "单选题", "s": "以下关于能量CT物质分离技术，错误的是", "o": {"A": "三物质分解法假设每个体素由三种基础物质的混合物组成，通过两种能量下的衰减值解方程组求解", "B": "常用的基础物质对包括碘-水、钙-水、碘-钙、尿酸-钙等", "C": "双能量指数（DEI）或双能量比值可用于区分不同物质", "D": "能量CT物质分离技术只能用于定性分析，不能用于定量测量", "E": "双层探测器CT可在探测器层面实现能量分离，其优势是无需预设双能量扫描协议"}, "d": "难", "c": "记忆", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-03", "kp": "能量CT物质分离技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → 能量CT物质分离技术", "ex": "【为什么对】本题要求选错误选项。D错误——能量CT物质分离技术不仅可用于定性分析，更重要的是可实现定量测量：如碘浓度定量（mgI/ml）、钙定量（mg/cm³）、脂肪分数定量等。定量能力恰恰是能量CT相对于传统CT的核心优势之一。【为什么错】A正确：三物质分解是DECT核心算法——三个未知数（三种基础物质体积分数）+两个已知数（低能和高能CT值）+一个约束条件（体积分数之和=1）=可解。B正确：不同的基础物质对用于不同的临床应用场景。C正确：不同物质的高低能衰减比值不同，该比值可用于物质鉴别。E正确：双层探测器CT的优势在于所有扫描天然具有能谱信息（探测器上下层分别接收低能和高能光子），操作者无需预先决定是否需要双能量扫描。", "tr": "D将能量CT的定量能力否定——恰恰相反，{LQ}定量{RQ}是能量CT相对于传统CT的革命性进步。传统CT的CT值（HU）受多种因素影响（kVp、患者体型等）不具有绝对定量能力；能量CT通过物质分离可实现碘浓度等参数的绝对定量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-092", "t": "案例分析题", "s": "关于CT低剂量技术的原理，以下描述错误的是", "o": {"A": "迭代重建（IR）算法可在相同辐射剂量下降低图像噪声，或在降低剂量的同时保持相同噪声水平", "B": "自动管电流调制（ATCM）可根据扫描部位和患者体型实时调整mA，是CT低剂量最基础的技术", "C": "降低管电压（kVp）可同时降低辐射剂量和增加碘对比度（因碘的K缘效应），在CTA和儿童检查中应用广泛", "D": "减少扫描期相（如肝脏CT仅做动脉期+门脉期而不做延迟期）是降低总辐射剂量的有效方式", "E": "使用更大螺距（如pitch=1.5）会显著增加辐射剂量"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-04", "kp": "CT低剂量技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → CT低剂量技术", "ex": "【为什么对】本题要求选错误选项。E错误——增大螺距（pitch>1）会降低辐射剂量（因重叠扫描减少），而非增加。螺距与辐射剂量成反比：剂量∝1/pitch。【为什么错】A正确：IR算法是低剂量CT核心技术（如ASIR-V、 ADMIRE、AiCE等）。B正确：ATCM是最基础的低剂量技术。C正确：低kVp增强碘强化（碘的K缘33.2keV）的同时降低剂量（剂量∝kVp²）。D正确：减少扫描期相是降低累积剂量的直接方法——需权衡诊断价值与辐射风险。", "tr": "E将螺距与剂量的关系说反——pitch增大=进床快=同一部位受照时间短=剂量降低。剂量∝1/pitch。但pitch增大也会导致层面敏感度曲线展宽（Z轴分辨率降低）和数据间隙（需插值），需要在图像质量和剂量之间权衡。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-093", "t": "多选题", "s": "关于CT低剂量检查的临床应用策略，以下正确的是", "o": {"A": "儿童CT检查应严格遵循ALARA原则，使用专门的儿童低剂量扫描协议（低kVp+低mA+IR重建）", "B": "肺癌低剂量筛查CT（LDCT）使用极低辐射剂量（约1-2mSv），用于高危人群的年度筛查", "C": "冠状动脉CTA低剂量策略包括：前瞻性心电门控、低kVp（70-100kVp）、迭代重建和高螺距螺旋扫描", "D": "CT结肠成像（CTC）低剂量策略强调低kVp（降低腹部剂量）+俯卧位/仰卧位互补扫描以弥补低剂量导致的噪声增加", "E": "急诊创伤全身CT（pan-scan）因需要快速诊断，辐射剂量优化不是优先考虑的问题"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-05", "kp": "CT低剂量临床应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → CT低剂量临床应用", "ex": "【为什么对】A正确：儿童对辐射的敏感性为成人的3-5倍（因细胞分裂活跃+预期寿命更长），儿童CT必须使用专门的极低剂量协议。B正确：LDCT肺癌筛查（如NLST试验方案）有效剂量约1-2mSv，显著低于诊断性胸部CT（约5-8mSv）。C正确：冠脉CTA低剂量综合策略包括前瞻性门控（减少无效扫描）、低kVp、IR重建、大螺距（如Flash Spiral）等。D正确：CTC可使用极低剂量（因结肠黏膜与充气肠腔有天然高对比），俯仰卧位互补可在低剂量下保证诊断质量。【为什么错】E错误：急诊创伤全身CT虽然需要快速诊断，但辐射剂量优化绝不能忽视——全身体CT（头+颈+胸+腹+盆）累积辐射剂量可>30mSv，尤其多数创伤患者为年轻人，必须在保障诊断的前提下尽可能降低剂量。现代创伤CT协议均整合了剂量优化策略（ATCM、低kVp、IR等）。", "tr": "E使用“不是优先考虑的问题”诱导考生认为急诊场景可以忽视辐射防护——这是严重错误观念。辐射防护在任何场景下都应重视，急诊创伤患者年龄偏轻（车祸、坠落等），辐射的远期致癌风险更需关注。“快速诊断”与“辐射优化”不矛盾——现代CT技术可同时实现。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-094", "t": "案例分析题", "s": "某医院拟开展低剂量CT肺癌筛查项目。作为技术负责人，需要设计筛查方案。以下哪些措施是正确的", "o": {"A": "采用低剂量扫描协议：管电压100-120kVp，管电流20-50mAs（具体根据患者体型调整），总辐射剂量目标<3mSv", "B": "扫描范围从肺尖至肋膈角（包括全部肺实质），层厚≤1.5mm（薄层以利小结节检测和随访）", "C": "筛查阳性标准参照Lung-RADS分类系统，基线筛查发现的实性结节<6mm可继续年度筛查", "D": "阳性筛查结果的管理遵循“结节生长”评估原则——两次筛查间结节体积倍增时间（VDT）是判断良恶性的重要参数", "E": "所有LDCT发现的肺结节均应立即行PET-CT检查以明确诊断"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-06", "kp": "低剂量CT肺癌筛查", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → 低剂量CT肺癌筛查", "ex": "【为什么对】A正确：LDCT筛查辐射剂量目标<3mSv（NLST 1.5mSv，NELSON约1-2mSv），使用低mA（20-50mAs）扫描。B正确：全肺覆盖+薄层重建（≤1.5mm，国际肺筛查共识推荐层厚≤1mm）是肺结节检测的标准要求。C正确：Lung-RADS 1.1中基线筛查<6mm实性结节（或<30mm²体积）为阴性，可常规年度随访。D正确：体积倍增时间（VDT）是结节生长评估的重要指标——恶性结节VDT通常30-400天；VDT<30天提示感染/炎症；VDT>400天提示良性（如错构瘤）。【为什么错】E错误：所有LDCT发现结节均行PET-CT是严重过度检查——PET-CT成本高、辐射剂量大（约10-15mSv），仅适用于≥8mm实性结节且CT特征不确定者。绝大多数<8mm结节通过LDCT随访即可。", "tr": "E使用“所有...均应立即”绝对化——LDCT筛查的核心策略是“风险分层管理”：低风险结节→LDCT随访；中高风险结节→进一步检查（PET-CT/穿刺/手术）。“一刀切”行PET-CT是临床资源的巨大浪费和过度医疗。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-095", "t": "单选题", "s": "关于BOLD-fMRI（血氧水平依赖功能磁共振成像）的原理，以下描述正确的是", "o": {"A": "BOLD信号基于脱氧血红蛋白的顺磁性效应——脱氧血红蛋白作为内源性对比剂引起局部磁场不均匀→T2*信号降低", "B": "神经元激活→局部脑血流和氧合增加（氧合过度）→脱氧血红蛋白浓度相对降低→T2*信号增高→BOLD信号增高", "C": "BOLD-fMRI的时间分辨率受限于血流动力学响应函数（HRF），通常为秒级（约5-8秒达峰）", "D": "BOLD-fMRI可用于术前脑功能区定位（运动、语言、感觉等），以规划手术入路和保护功能", "E": "以上均正确"}, "d": "中", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-01", "kp": "BOLD-fMRI原理与应用", "ch": "十七、MR技术的进展 → 2.MR检查技术 → BOLD-fMRI原理与应用", "ex": "【为什么对】以上均正确。A：BOLD信号的物理基础是脱氧血红蛋白的顺磁性——脱氧Hb引起局部磁场梯度→T2*缩短→信号降低。B：神经元激活→血流增加>氧耗增加→脱氧Hb浓度净降低→T2*信号增高（BOLD增高）——这是神经血管耦合的核心。C：BOLD-fMRI的时间分辨率受限于缓慢的血流动力学响应（HRF），而非神经电活动的速度（毫秒级），这是fMRI的固有局限。D：术前fMRI功能定位（task fMRI）是神经外科的重要工具。【为什么错】见上述解析中各错误选项分析。", "tr": "本题选项E为以上均正确。BOLD-fMRI的神经生理学基础（神经血管耦合）和物理基础（脱氧Hb顺磁性）是两大核心概念。BOLD-fMRI的空间分辨率约2-3mm，时间分辨率约1-3秒（受HRF限制）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-096", "t": "多选题", "s": "关于磁共振弥散张量成像（DTI）及其临床应用，以下正确的是", "o": {"A": "DTI通过施加至少6个非共线方向的弥散敏感梯度，测量水分子弥散的各向异性", "B": "各向异性分数（FA）是DTI最常用的参数——FA值0-1，反映纤维束的方向性和完整性", "C": "DTI纤维束示踪（tractography）可三维显示白质纤维束走行，用于术前规划（如避开锥体束）", "D": "DTI在急性脑梗死的应用不如DWI——因为DTI扫描时间较长且对运动敏感", "E": "FA值升高通常提示白质纤维束损伤（如脱髓鞘、轴突损伤）"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-02", "kp": "弥散张量成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → 弥散张量成像", "ex": "【为什么对】A正确：DTI需≥6个方向（临床常用20-64方向）的弥散梯度，通过张量模型计算弥散椭球体（三个特征值λ₁, λ₂, λ₃）。B正确：FA=(各向异性扩散量)/(总扩散量)，0=完全各向同性（灰质、CSF），1=完全各向异性（白质纤维束）。C正确：纤维束示踪（tractography）可在三维空间追踪白质通路，在脑肿瘤手术规划中避免损伤关键纤维束。D正确：DWI扫描<30s即可完成，而DTI扫描时间更长（通常>2-3min），急性卒中首选DWI。【为什么错】E错误：白质纤维束损伤通常导致FA值降低（而非升高）——脱髓鞘/轴突损伤→纤维束方向性丧失+水分子弥散各向异性降低→FA下降。FA升高在临床上少见（可见于纤维束发育/髓鞘形成过程）。", "tr": "E将FA值变化方向说反——核心记忆：{LQ}FA降低=白质损伤{RQ}（脱髓鞘、轴突损伤、肿瘤浸润等导致纤维束方向性破坏→弥散各向同性增加→FA降低）。FA值降低是白质病变最重要和最常见的DTI改变。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-097", "t": "案例分析题", "s": "某三级医院计划将MRI研究平台从3.0T升级至7.0T超高场强。作为技术组，需要评估7.0T的优势和挑战。以下分析正确的有哪些", "o": {"A": "7.0T的SNR约为3.0T的2.3倍（与场强近似正比），可实现更高空间分辨率或更短扫描时间", "B": "7.0T的B1场不均匀性（介电效应）更为显著，腹部和盆腔成像面临更大技术挑战", "C": "7.0T下组织T1值进一步延长，TR需相应延长以保持T1对比", "D": "7.0T的SAR（比吸收率）限制更严格，许多高功率快速序列在7.0T下使用受限", "E": "7.0T的化学位移和磁敏感伪影较3.0T显著增大，但这也使BOLD-fMRI和SWI的灵敏度更高"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-03", "kp": "7.0T超高场MRI", "ch": "十七、MR技术的进展 → 1.MR设备 → 7.0T超高场MRI", "ex": "【为什么对】五项均正确。A：SNR近似与B₀成正比→7.0T/3.0T≈2.3倍SNR增益（理想条件下）。B：介电效应（B1波长缩短至约12cm，与人体尺寸可比拟）导致B1场严重不均匀，腹部成像挑战极大。C：场强↑→T1值延长→需要更长TR保持T1对比度。D：SAR∝B₀²→7.0T下SAR约为3.0T的5-6倍，高功率序列（如TSE、FLAIR等）需要使用并行发射、特殊脉冲设计等技术控制SAR。E：磁敏感效应（Δχ∝B₀）和化学位移（Hz∝B₀）均与场强成正比增大——这是一把双刃剑：伪影增大但BOLD和SWI灵敏度也更高。【为什么错】无错误选项。", "tr": "7.0T的优势与挑战并存：优势=高SNR、高BOLD/SWI灵敏度、高化学位移分离；挑战=B1不均匀性、高SAR、T1延长、伪影放大。7.0T目前主要仍限于神经和肌肉骨骼领域，体部应用面临很大技术障碍。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-098", "t": "多选题", "s": "关于压缩感知（CS）和并行成像在MR快速成像中的应用，以下正确的是", "o": {"A": "并行成像（如SENSE、GRAPPA）利用多通道线圈的空间信息减少相位编码步数，加速因子通常2-4倍", "B": "压缩感知利用MR图像在变换域的稀疏性，且无需任何K空间欠采样即可实现5–10倍加速", "C": "并行成像的主要限制是g因子相关的噪声放大，高加速因子下SNR急剧下降", "D": "压缩感知与并行成像可以联合应用（如CS-SENSE），实现更高倍加速", "E": "压缩感知重建图像的质量与欠采样模式（随机采样>规则采样）和稀疏变换选择密切相关"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-04", "kp": "MR快速成像技术", "ch": "十七、MR技术的进展 → 1.MR设备 → MR快速成像技术", "ex": "【为什么对】A正确——并行成像（SENSE/GRAPPA）利用多通道线圈灵敏度差异减少相位编码步数，加速因子通常2–4倍。C正确——并行成像受g因子噪声放大限制，高加速因子下SNR急剧下降（SNR_acc=SNR_full/(g√R)）。D正确——CS与并行成像可联合（如CS-SENSE）实现更高倍加速。E正确——CS重建质量与欠采样模式（随机>规则）及稀疏变换选择密切相关。【为什么错】B错误——压缩感知的前提正是对K空间进行随机/伪随机欠采样（以减少采集数据量），再依靠图像稀疏性与迭代重建恢复完整图像；若无欠采样便无加速可言，“无需欠采样即可加速”自相矛盾。", "tr": "本题已将原“全选”改为四项正确；注意选项B为刻意设置的错误项——压缩感知的前提正是对K空间进行随机/伪随机欠采样（以减少采集数据量），再依靠图像稀疏性与迭代重建恢复完整图像；若无欠采样便无加速可言，“无需欠采样即可加速”自相矛盾。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-053-099", "t": "单选题", "s": "关于ASL（动脉自旋标记）灌注成像与DSC（动态磁敏感对比增强）灌注成像的比较，以下描述错误的是", "o": {"A": "ASL使用动脉血中的水分子作为内源性示踪剂（射频标记），完全无创、无需注射对比剂", "B": "DSC使用钆剂作为外源性示踪剂，通过首过效应计算灌注参数", "C": "ASL的SNR低于DSC，单次采集时间较长（4-8分钟），但可重复性强", "D": "ASL更适合需要重复灌注评估的场景（如治疗随访、脑血管储备功能评估）", "E": "ASL可以同时提供与DSC完全相同的一组灌注参数（包括CBV、CBF、MTT、PS等）"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-05", "kp": "ASL灌注成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → ASL灌注成像", "ex": "【为什么对】本题要求选错误选项。E错误——ASL和DSC提供的灌注参数不完全相同。ASL直接测量CBF（脑血流），可间接推算CBV（通过动脉血容量修正），但无法提供MTT和PS等参数（这些需要对比剂动力学模型）。DSC通过对比剂首过效应可计算CBV、CBF、MTT、Tmax、TTP等全套灌注参数。【为什么错】A正确：ASL使用射频脉冲标记颈动脉血液中的水质子作为内源性示踪剂，完全无创。B正确：DSC通过静脉注射钆剂追踪其首过脑循环过程。C正确：ASL的SNR仅约为DSC的1/3-1/4（因标记与对照相减的信号差很小），需多次平均（4-8分钟）。D正确：ASL的无创性和可重复性使其非常适合需要多次灌注评估的场景。", "tr": "E将ASL和DSC的灌注参数等同——ASL仅直接测量CBF，不能测量MTT和PS。ASL的优势在于无创可重复；DSC的优势在于参数全面且SNR高但需注射对比剂。两者互补而非相互替代。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-053-100", "t": "单选题", "s": "关于3.0T MRI在临床应用的总体评价，以下描述错误的是", "o": {"A": "3.0T SNR约为1.5T的两倍，可提高空间分辨率或缩短扫描时间", "B": "3.0T的化学位移效应增大，使脂肪抑制技术（如SPIR、FatSat）效果更好", "C": "3.0T的磁敏感伪影（如颅内含气腔隙附近、金属植入物旁）较1.5T显著加重", "D": "3.0T在全身各部位的成像质量均全面优于1.5T，应作为所有临床检查的首选", "E": "3.0T的SAR限制更严格，需要使用并行发射、特殊脉冲设计等技术优化"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-06", "kp": "3.0T临床MRI", "ch": "十七、MR技术的进展 → 1.MR设备 → 3.0T临床MRI", "ex": "【为什么对】本题要求选错误选项。D错误——3.0T并非在所有部位和场景下均优于1.5T。3.0T的局限性包括：①SAR高限制某些序列使用；②磁敏感伪影更重（影响DWI和梯度回波序列在颅底、含气腔隙附近的图像质量）；③B1不均匀性大（尤其在腹部和盆腔）；④介电效应导致信号不均匀；⑤运动伪影更敏感；⑥植入物兼容性更差。1.5T在某些场景（如腹部、盆腔、心脏、植入物患者）仍是更优选择。【为什么错】A正确：3.0T SNR≈2倍1.5T。B正确：化学位移（Hz）与场强成正比→3.0T下脂肪和水峰更分离→频率选择性脂肪抑制效果更好。C正确：磁敏感伪影（Δχ∝B₀）在3.0T下更重。E正确：SAR限制是3.0T的主要技术挑战。", "tr": "D使用“全面优于...所有...首选”多重绝对化措辞——这是典型的错误信号。临床MRI设备选择需根据检查部位、患者情况和临床问题综合决策：1.5T适合腹部、盆腔、心脏和植入物患者；3.0T适合神经、骨关节、血管成像（MRA/TOF）。不存在“万能”场强。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0101", "t": "单选题", "s": "颅脑CT经鞍上池层面，鞍上池多呈“五角星”形，其向前伸出的前角所连通的结构是", "o": {"A": "大脑纵裂池", "B": "外侧裂池", "C": "环池", "D": "脚间池", "E": "四叠体池"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-001", "kp": "鞍上池形态与毗邻", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】鞍上池由交叉池、脚间池等汇合而成，横断面上典型呈“五角星”形：前角向前连通大脑纵裂池，两个前外侧角分别连通左右外侧裂池，两个后外侧角连通左右环池。故前角对应大脑纵裂池，选A。【为什么错】B外侧裂池对应的是两个前外侧角，不是前角。C环池对应两个后外侧角。D脚间池位于五角星后部中央，当其明显显影并单独构成一角时，鞍上池即由“五角星”变为“六角星”形，但它不在前角。E四叠体池位于中脑背侧、松果体区，层面更靠后，不参与鞍上池构成。", "tr": "“五角星”与“六角星”之分只在于后方脚间池是否单独成角，而不是前角变化；命题人常把“环池”与“外侧裂池”所对应的角位互换设陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0102", "t": "单选题", "s": "基底节区横断面上，内囊后肢所处的解剖位置是", "o": {"A": "尾状核头与豆状核之间", "B": "丘脑与豆状核之间", "C": "丘脑与尾状核头之间", "D": "豆状核与屏状核之间", "E": "屏状核与岛叶皮质之间"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-002", "kp": "内囊分部与毗邻结构", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】内囊在横断面上呈尖端向内的“><”形。后肢介于背侧丘脑（内侧）与豆状核（外侧）之间，其中皮质脊髓束、皮质核束的部分纤维及丘脑皮质束由此通过，故选B。【为什么错】A尾状核头与豆状核之间为内囊前肢，主要通过额桥束和丘脑前辐射。C丘脑与尾状核头之间并非内囊某一固定分部，二者之间为内囊膝部前方过渡区域，描述不准确。D豆状核与屏状核之间为外囊，主要为联络纤维。E屏状核与岛叶皮质之间为最外囊。【为什么错】补充：这三层结构由内向外依次为内囊、豆状核、外囊、屏状核、最外囊、岛叶皮质。", "tr": "内囊前肢“夹在尾状核头与豆状核之间”、后肢“夹在丘脑与豆状核之间”，两者的内侧界不同（前肢是尾状核头、后肢是丘脑），这是最常被互换的考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0103", "t": "多选题", "s": "关于颅脑横断面半卵圆中心层面的断层影像解剖，描述正确的有", "o": {"A": "该层面位于胼胝体上方，双侧侧脑室尚未出现或仅见顶部", "B": "半卵圆中心由投射纤维、联络纤维和连合纤维共同构成", "C": "CT上白质相对灰质呈略低密度，T2WI上白质信号低于皮质", "D": "中线可见大脑镰，为大脑纵裂内的硬脑膜结构", "E": "该层面可清楚显示基底节、丘脑与内囊"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-003", "kp": "半卵圆中心层面识别", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：半卵圆中心层面在胼胝体之上，侧脑室体部尚未出现或仅显示其顶部，是识别该层面的关键。B正确：半卵圆中心为大量有髓纤维汇聚区，包含投射纤维（如放射冠）、联络纤维（如上纵束）和连合纤维（如胼胝体辐射）。C正确：白质髓鞘含脂质、含水量低，CT呈略低密度，T2WI信号低于灰质皮质，T1WI则高于皮质。D正确：大脑镰为纵裂内硬脑膜皱襞，CT上因含少量钙化或与血管邻近常呈线状稍高密度。【为什么错】E错误：基底节、丘脑与内囊位于更低的层面（侧脑室体部及室间孔层面），半卵圆中心层面尚未出现这些灰质核团，见到它们即说明层面偏低。", "tr": "半卵圆中心层面的判定依据是“见不到侧脑室体部与基底节”；若图像上出现内囊“><”形结构，说明已进入基底节区层面，不能再称半卵圆中心层面。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0104", "t": "单选题", "s": "中脑层面横断面图像上，位于两侧大脑脚之间、呈尖端向前三角形的脑池是", "o": {"A": "环池", "B": "脚间池", "C": "四叠体池", "D": "桥前池", "E": "小脑延髓池"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-004", "kp": "中脑层面脑池识别", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】中脑层面上，两侧大脑脚呈“八”字形向前外分开，其间的三角形低密度／长T2信号区即脚间池，内含大脑后动脉起始段、小脑上动脉及动眼神经出脑处，故选B。【为什么错】A环池位于中脑（大脑脚）的外侧，呈细带状绕行，向后与四叠体池相续，不在两脚之间。C四叠体池位于中脑背侧、上下丘后方，内有大脑大静脉与松果体。D桥前池位于脑桥腹侧，层面更低。E小脑延髓池（枕大池）位于延髓背侧与小脑之间，层面最低。", "tr": "脚间池、环池、四叠体池在中脑同一层面上呈“前—外—后”依次环绕的关系；蛛网膜下腔出血时三者同时高密度，容易混淆定位，务必以大脑脚为参照。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0105", "t": "多选题", "s": "结合上述情景，有关海马的MRI断层影像解剖，正确的描述有", "o": {"A": "垂直于海马长轴的斜冠状面是显示海马结构的最佳方位", "B": "海马位于颞叶内侧、侧脑室下角（颞角）的内下方", "C": "高分辨T2WI上可辨认海马沟、齿状回与海马伞", "D": "横断面上海马位于中脑的外侧，与环池相邻", "E": "横断面上海马位于四叠体池的后方"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-005", "kp": "海马断层解剖与最佳成像方位", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】A正确：海马长轴自前外下斜向后内上，只有做垂直于其长轴的斜冠状面才能获得真正的“横截面”，避免容积效应造成的假性信号增高。B正确：海马位于颞叶内侧面，构成侧脑室下角的内下壁。C正确：3.0 T高分辨T2WI（层厚2～3 mm）可分辨海马沟残腔、齿状回、海马伞及海马内部结构。D正确：横断面上海马头体部位于中脑外侧，与环池仅隔脉络裂相邻，颞叶钩回疝时即在此处压迫中脑。【为什么错】E错误：四叠体池位于中脑背侧，海马尾虽可延伸至该区外侧，但海马主体并不位于四叠体池后方，该描述定位错误。", "tr": "评估颞叶癫痫时若仅做常规横断面，海马会因斜切产生部分容积效应而被误判为“信号增高、体积缩小”，斜冠状面T2WI／FLAIR是避免假阳性的关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0106", "t": "多选题", "s": "构成大脑动脉环（Willis环）的血管包括", "o": {"A": "双侧大脑前动脉A1段", "B": "前交通动脉", "C": "双侧颈内动脉床突上段（终末段）", "D": "双侧大脑中动脉M1段", "E": "双侧后交通动脉与大脑后动脉P1段"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-006", "kp": "Willis环组成与CTA/MRA显示", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】Willis环位于蝶鞍上方、脚间池内，由前交通动脉（1条）、双侧大脑前动脉A1段（水平段）、双侧颈内动脉床突上段、双侧后交通动脉与双侧大脑后动脉P1段（交通前段）共9条血管首尾相接构成，故A、B、C、E正确。【为什么错】D错误：大脑中动脉M1段虽由颈内动脉终末端发出，但它不参与环的闭合，只是从环上发出的分支，不属于Willis环的组成血管。", "tr": "大脑中动脉是Willis环最常被误加入的血管；另需注意大脑后动脉参与成环的是P1段（交通前段）而非P2段，交通动脉发育不良／缺如是环不完整的常见变异。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0107", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，垂体MRI冠状面上，行于海绵窦腔内、紧邻颈内动脉海绵窦段外侧的脑神经是", "o": {"A": "动眼神经", "B": "滑车神经", "C": "三叉神经眼支", "D": "展神经", "E": "面神经"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-007", "kp": "海绵窦区断层解剖", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】海绵窦内穿行的脑神经中，只有展神经（第Ⅵ对）真正位于海绵窦腔内，紧贴颈内动脉海绵窦段的外侧走行，其余神经均嵌于海绵窦外侧壁的两层硬膜之间，故选D。【为什么错】A动眼神经位于海绵窦外侧壁最上方。B滑车神经位于外侧壁、动眼神经的下方。C三叉神经眼支（V1）位于外侧壁、滑车神经下方，其下方为上颌支（V2）。E面神经不经过海绵窦，它经内耳道入面神经管，属桥小脑角区结构。", "tr": "海绵窦病变时展神经因“泡在窦腔内”最早受累，出现单纯外展受限；命题常以“外侧壁自上而下依次为Ⅲ、Ⅳ、V1、V2”与“腔内为Ⅵ和颈内动脉”作对照设题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0108", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，患者女性，56岁，突发右侧肢体无力3天。临床需明确病灶与内囊后肢皮质脊髓束的空间关系，以判断预后并指导康复。科室配备3.0 T MRI，可任意设定成像基线与方位。技师需要在一次横断面采集中，尽可能在同一或相邻层面上完整显示尾状核头、内囊前肢、膝部、后肢、豆状核与丘脑的相互关系，同时保证左右两侧对称便于对比。此时最恰当的扫描基线设置是", "o": {"A": "以正中矢状面定位，横断面平行于前连合—后连合（AC-PC）连线扫描", "B": "横断面平行于听眦线（OM线）扫描，层厚8 mm", "C": "横断面平行于颅底（眶耳基线以下）扫描，层厚10 mm", "D": "横断面平行于胼胝体膝—压部连线上方15°倾斜扫描", "E": "直接采用冠状面扫描替代横断面"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-008", "kp": "基底节区扫描基线与断层显示", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】前连合—后连合（AC-PC）连线是脑功能影像与立体定向的国际通用标准基线。以正中矢状面定位、横断面平行于AC-PC线扫描时，基底节区诸核团与内囊三部分恰好位于同一水平面内，可在一个层面上完整显示“尾状核头—内囊前肢—豆状核—内囊后肢—丘脑”由内前向外后的排列，且左右对称性最好，便于测量与随访对比，故选A。【为什么错】B听眦线（OM线）是常规颅脑CT基线，相对AC-PC线约有10°～15°夹角，会使基底节结构斜切、前后肢不在同一层面。C平行于颅底扫描倾斜度更大，基底节区被明显斜切，且后颅窝伪影增多。D该基线为主观设定，无标准依据，且过度倾斜会破坏左右对称性。E冠状面虽利于观察内囊上下走行，但无法一次显示尾状核头至丘脑的前后毗邻顺序，且不是本题要求的横断面方案。", "tr": "OM线适用于常规颅脑CT，AC-PC线适用于需要精确解剖定位的MRI；把两者混用会导致基底节层面斜切，出现内囊“看不全”的假象。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0109", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，颈部CT横断面图像上，会厌前间隙（前会厌间隙）所处的位置是", "o": {"A": "舌骨、舌会厌襞与会厌之间的脂肪间隙", "B": "会厌与杓状会厌襞之间", "C": "甲状软骨板与环状软骨之间", "D": "真声带与假声带之间", "E": "咽后壁与椎前筋膜之间"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-001", "kp": "喉部间隙断层解剖", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】会厌前间隙位于舌骨与甲状舌骨膜之前上方、舌会厌襞之下、会厌软骨之前，是充填脂肪的三角形区域，CT上呈明确脂肪密度，是会厌癌向前扩散的重要通道，故选A。【为什么错】B会厌与杓状会厌襞之间为梨状窝上部，属下咽结构。C甲状软骨板与环状软骨之间为环甲间隙／环甲膜区。D真声带与假声带之间为喉室，是含气腔隙。E咽后壁与椎前筋膜之间为咽后间隙，属颈深部筋膜间隙，与喉内间隙无关。", "tr": "会厌前间隙与声门旁间隙同为喉癌扩散途径，前者位于会厌之前呈脂肪三角，后者位于甲状软骨内侧、呈上下走行的条形脂肪带，两者层面与形态均不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0110", "t": "多选题", "s": "在颈部断层影像上，关于咽旁间隙及其分区的描述，正确的有", "o": {"A": "茎突及茎突诸肌将咽旁间隙分为茎突前间隙与茎突后间隙", "B": "茎突后间隙即颈动脉间隙，内含颈内动脉、颈内静脉与第Ⅸ～Ⅻ对脑神经", "C": "茎突前间隙主要为脂肪，并含腮腺深叶与咽升动脉", "D": "咽旁间隙在横断面上呈尖端向下的倒锥形脂肪影，是判断邻近病变来源方向的重要标志", "E": "咽旁间隙的下界终止于舌骨水平，不与颌下间隙相通"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-002", "kp": "咽旁间隙分区与内容", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：茎突及其附着的茎突舌肌、茎突舌骨肌、茎突咽肌构成分界，将咽旁间隙分为前、后两部。B正确：茎突后间隙即颈动脉间隙（颈动脉鞘区），内含颈内动脉、颈内静脉、迷走神经及舌咽、副、舌下神经与交感干。C正确：茎突前间隙以脂肪为主，含腮腺深叶、咽升动脉及三叉神经下颌支分支。D正确：咽旁间隙横断面呈倒置锥形脂肪低密度区，其受压移位方向可提示病变来源——向内移位提示腮腺深叶来源，向外移位提示咽黏膜间隙来源。【为什么错】E错误：咽旁间隙上起颅底，下达舌骨大角水平，并经其下端与颌下间隙、咽后间隙相通，是感染向下蔓延至纵隔的潜在途径。", "tr": "“咽旁脂肪移位方向”是定位病变来源的经典技巧：脂肪被推向外侧提示咽黏膜间隙（如鼻咽癌），推向内侧提示腮腺深叶肿瘤，推向前方提示颈动脉间隙病变。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0111", "t": "多选题", "s": "有关颈部筋膜间隙的断层影像解剖，下列描述正确的有", "o": {"A": "咽后间隙位于咽后壁与椎前筋膜之间，向下可直接通向后纵隔", "B": "颈深筋膜浅层、中层与深层均参与颈动脉鞘的构成", "C": "“危险间隙”位于咽后间隙与椎前间隙之间，由翼状筋膜分隔", "D": "椎前间隙位于椎前筋膜与椎体、椎前肌之间", "E": "咽旁间隙内主要为淋巴组织，几乎不含脂肪"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-003", "kp": "颈深筋膜间隙分区", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：咽后间隙上起颅底，下至上纵隔（约T3水平），是咽部感染向纵隔蔓延的主要途径。B正确：颈动脉鞘由颈深筋膜浅层（封套筋膜）、中层（气管前筋膜）和深层（椎前筋膜）三层共同参与构成，故颈动脉间隙上下贯通颅底至主动脉弓。C正确：翼状筋膜位于咽后间隙与椎前筋膜之间，其与椎前筋膜间的潜在腔隙称“危险间隙”，可下达膈肌水平。D正确：椎前间隙位于椎前筋膜深面与椎体、颈长肌之间，结核性脓肿常积聚于此。【为什么错】E错误：咽旁间隙以脂肪为主要成分，正是这一脂肪信号／密度使其在CT、MRI上易于辨认，并可依其受压方向判断病变来源。", "tr": "咽后间隙感染下达上纵隔，危险间隙可下达膈肌，两者蔓延范围不同；CT上二者难以直接区分，报告时统称“咽后区”更稳妥。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0112", "t": "单选题", "s": "喉部CT横断面上，判断层面已达真声带水平最可靠的解剖标志是", "o": {"A": "甲状软骨上角", "B": "杓状软骨声带突", "C": "环状软骨板下缘", "D": "舌骨大角", "E": "会厌软骨游离缘"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-004", "kp": "喉部层面识别标志", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】声带附着于杓状软骨的声带突，横断面上一旦显示杓状软骨声带突，即为真声带层面；此层面上双侧声带呈三角形软组织影，前端汇合于甲状软骨内面构成前联合，故选B。【为什么错】A甲状软骨上角位于喉的上部，相当于舌骨下方，远高于声带。C环状软骨板下缘位于声带下方，属声门下区。D舌骨大角为舌骨水平标志，位于会厌层面附近，明显高于声带。E会厌软骨游离缘所在层面为喉前庭上部，位于假声带之上。", "tr": "假声带层面见到的是杓状软骨的“肌突”及较多脂肪，密度偏低；真声带层面见“声带突”且声带呈均匀软组织密度，二者最可靠的鉴别就是杓状软骨的哪一个突。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0113", "t": "单选题", "s": "结合上述情景，患者男性，58岁，右颈部无痛性肿块2个月，吸烟史30年。颈部增强CT示：右侧颈内静脉链周围多发肿大淋巴结，最大者短径18 mm，中央呈低密度坏死。测量显示这组淋巴结的上界位于舌骨体下缘水平，下界位于环状软骨下缘水平，位于胸锁乳突肌深面、颈内静脉外侧。技师在整理图像与结构化报告时，需按国际通用的颈部淋巴结影像学分区标准对该组淋巴结进行定位标注。该组淋巴结应标注为", "o": {"A": "Ⅱ区", "B": "Ⅲ区", "C": "Ⅳ区", "D": "Ⅴ区", "E": "Ⅵ区"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-005", "kp": "颈部淋巴结影像学分区", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】颈部淋巴结影像学分区以横断面上可重复识别的骨性／软骨标志为界：Ⅱ区自颅底至舌骨体下缘，Ⅲ区自舌骨体下缘至环状软骨下缘，Ⅳ区自环状软骨下缘至锁骨上缘，三者均沿颈内静脉链分布。本例上界为舌骨体下缘、下界为环状软骨下缘，恰好符合Ⅲ区（颈内静脉中组），故选B。【为什么错】A Ⅱ区上界为颅底、下界为舌骨体下缘，本例位于舌骨下方，不符。C Ⅳ区位于环状软骨下缘以下至锁骨，本例下界止于环状软骨下缘，未进入Ⅳ区。D Ⅴ区为颈后三角区，位于胸锁乳突肌后缘之后、斜方肌前缘之前，本例位于胸锁乳突肌深面、颈内静脉外侧，不属后三角。E Ⅵ区为中央区（气管前、气管旁、喉前），位于双侧颈总动脉之间，本例明显偏外侧。", "tr": "分区边界必须用横断面上的舌骨体下缘、环状软骨下缘、胸锁乳突肌后缘这三个影像学标志，而不能沿用外科触诊描述；此外Ⅱ区与Ⅲ区的分界是“舌骨体下缘”，不是“舌骨上缘”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "颈部", "页": 8}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0114", "t": "单选题", "s": "胸部CT横断面上，奇静脉弓自后向前跨过右主支气管上方汇入上腔静脉后壁，该层面相当于", "o": {"A": "胸骨颈静脉切迹水平", "B": "主动脉弓上缘水平", "C": "主动脉弓下缘与气管隆突之间", "D": "左心房水平", "E": "膈肌顶水平"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-001", "kp": "奇静脉弓层面识别", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】奇静脉沿脊柱右前方上行，至约第4胸椎水平（气管杈上方）向前弓形跨过右主支气管根部上方，汇入上腔静脉后壁。该处在CT横断面上位于主动脉弓下缘之下、气管隆突之上，故选C。【为什么错】A胸骨颈静脉切迹水平相当于胸廓入口，此处可见头臂静脉与三大分支动脉，奇静脉尚未成弓。B主动脉弓上缘水平所见为左头臂静脉、三大分支血管，奇静脉仍在脊柱旁上行。D左心房层面已在隆突下方数厘米，奇静脉弓早已汇入。E膈肌顶水平仅见奇静脉与半奇静脉的下段及主动脉裂孔区结构。", "tr": "奇静脉弓层面是纵隔淋巴结分区中第4R组（下气管旁）与第2R组（上气管旁）的分界标志之一；勿把奇静脉弓的“弓形高密度”误判为纵隔淋巴结或右上肺静脉。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0115", "t": "单选题", "s": "CT横断面上，左肺动脉与左主支气管之间的位置关系是", "o": {"A": "左肺动脉始终位于左主支气管的正前方", "B": "左肺动脉跨过左主支气管上方并转向其后外侧下行", "C": "左肺动脉位于左主支气管的正下方", "D": "左肺动脉位于左主支气管的内侧并与食管相邻", "E": "左肺动脉在左主支气管内部走行"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-002", "kp": "肺门血管与支气管毗邻", "ch": "一、人体断面影像解剖 → 3.胸部 → (3)主要断层影像解剖", "ex": "【为什么对】左肺动脉在肺门处呈“骑跨”式：先自肺动脉干向左后上方走行，跨过左主支气管上方，然后转至其后外侧下行成为左下肺动脉。因此在连续横断面上，高层面见左肺动脉在支气管上方，低层面见其位于支气管后外侧，选B。【为什么错】A“始终位于正前方”描述的是右肺动脉（右肺动脉主干经升主动脉与上腔静脉后方向右横行，位于右主支气管前方）。C左肺动脉不在左主支气管下方，下方为左下肺静脉引流区。D左主支气管内侧邻近的是降主动脉与食管，不是左肺动脉。E血管不可能在支气管腔内走行，属明显错误。", "tr": "记忆口诀“右前左上”——右肺动脉在右主支气管前方、左肺动脉跨越左主支气管上方；这是左右肺门断层最核心的不对称点，也是肺门肿块定位的解剖依据。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0116", "t": "多选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，有关肺叶、肺段的断层影像解剖，下列描述正确的有", "o": {"A": "右肺上叶分为尖段（S1）、后段（S2）和前段（S3）", "B": "左肺上叶因无独立后段，S1与S2合为尖后段", "C": "右肺中叶分为外侧段（S4）和内侧段（S5）", "D": "左肺下叶常缺如内侧底段，或与前底段合并为前内侧底段", "E": "右肺下叶背段（S6）位于斜裂后方最上部，其前方紧邻中叶"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-003", "kp": "肺段划分与断层定位", "ch": "一、人体断面影像解剖 → 3.胸部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：右肺上叶三段划分为S1尖段、S2后段、S3前段。B正确：左肺上叶尖段与后段合并称尖后段（S1+2），另有前段S3及上、下舌段S4、S5。C正确：右肺中叶只有外侧段S4与内侧段S5两段。D正确：左肺下叶多缺乏独立的内侧底段（S7），常与前底段合并为前内侧底段（S7+8）。【为什么错】E错误：背段（S6）位于下叶最上部、斜裂后方，其前方隔斜裂相邻的是上叶后段（右侧S2），而不是中叶；中叶位于斜裂前下、水平裂之下，与背段不在同一水平。", "tr": "背段（S6）与上叶后段（S2）以斜裂为界“前后相贴”，是CT上最易混淆的一对肺段；判断时先找斜裂走行，斜裂之后为下叶，之前为上叶。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0117", "t": "多选题", "s": "关于纵隔分区及各区内容结构的断层影像解剖，正确的有", "o": {"A": "前纵隔位于胸骨后与心包、大血管前缘之间，含胸腺、脂肪与淋巴结", "B": "中纵隔含心包、心脏、升主动脉、肺动脉干、上腔静脉、气管分叉与膈神经", "C": "后纵隔含降主动脉、食管、奇静脉与半奇静脉、胸导管及交感干", "D": "成人胸腺多被脂肪替代，CT上呈脂肪密度伴少量条索状软组织影", "E": "血管前间隙属于中纵隔的组成部分"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-004", "kp": "纵隔分区及内容", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】A正确：前纵隔（血管前间隙）以胸骨后缘为前界、心包及大血管前缘为后界，是胸腺瘤、畸胎瘤、淋巴瘤、甲状腺肿“4T”好发部位。B正确：中纵隔以心包及大血管所占区域为主，含心脏、升主动脉、肺动脉干、上腔静脉、气管及分叉、主支气管、膈神经与相应淋巴结。C正确：后纵隔位于心包后缘与椎体前缘（或椎旁沟）之间，含降主动脉、食管、奇静脉与半奇静脉、胸导管、交感干及迷走神经。D正确：成人胸腺随年龄脂肪化，CT表现为前纵隔脂肪密度内散在条索状软组织，勿误为病变。【为什么错】E错误：血管前间隙位于大血管之前、胸骨之后，恰恰是前纵隔的核心区域，不属于中纵隔。", "tr": "前纵隔＝血管前间隙，这一等价关系常被反向设错；另需注意胸腺“脂肪化”与真正的前纵隔肿块的鉴别，前者密度接近脂肪、无占位效应。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0118", "t": "单选题", "s": "四腔心层面的胸部CT横断面上，位置最靠前、紧邻胸骨后方的心腔是", "o": {"A": "左心房", "B": "左心室", "C": "右心房", "D": "右心室", "E": "主动脉根部"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-005", "kp": "心腔断层位置关系", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】心脏在胸腔内呈左前下斜位，四腔心层面上四个心腔的前后顺序为：右心室最靠前（紧贴胸骨后方与前胸壁），其后为左心室，右心房居右侧，左心房位于最后方并紧邻食管与降主动脉，故选D。【为什么错】A左心房位置最靠后，是判断左心房增大时压迫食管的解剖基础。B左心室位于右心室的左后方，构成心脏左缘与心尖。C右心房构成心脏右缘，位于右侧偏后，不是最靠前的心腔。E主动脉根部位于四腔心层面上方（五腔心／左室流出道层面），且居于心脏中央偏右后，并非紧邻胸骨。", "tr": "“最前是右室、最后是左房”是胸部断层的基本口诀；心包积液和外伤时右心室最易受压，左心房增大最先影响食管，均由此位置关系决定。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0119", "t": "多选题", "s": "结合上述情景，有关胸部CT上叶间裂的断层影像表现，正确的描述有", "o": {"A": "常规层厚（5～10 mm）横断面上，右肺水平裂常表现为相对乏血管的透亮带", "B": "薄层高分辨CT上叶间裂可直接显示为纤细的线状高密度影", "C": "斜裂在横断面上自后内斜向前外，上部层面位置偏后，向下逐层前移", "D": "奇静脉裂由奇静脉及其包绕的四层胸膜内陷形成，位于右肺上叶内侧", "E": "叶间裂处无胸膜结构，仅为肺组织之间的自然间隙"}, "d": "中", "c": "分析", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-006", "kp": "叶间裂断层表现", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】A正确：水平裂近似与扫描层面平行，厚层图像上因部分容积效应不能显示为线，而表现为血管稀疏的透亮带。B正确：HRCT层厚1 mm左右时，脏层胸膜相互贴合可直接呈现为细线状高密度影。C正确：斜裂近似冠状斜行，在上部层面靠近后胸壁，随层面下降逐渐向前外移动，至下部层面已接近前胸壁。D正确：奇静脉裂为发育变异，奇静脉在下移过程中携带两层脏层胸膜与两层壁层胸膜共四层内陷形成，其内侧的肺组织称奇静脉叶。【为什么错】E错误：叶间裂正是相邻肺叶脏层胸膜相互返折贴合所形成的结构，并非无胸膜的自然间隙；正因为含胸膜，才可在HRCT上显示为线状影，并成为病变蔓延的屏障。", "tr": "厚层上水平裂“看不见线只见乏血管带”是正常现象，不可据此报告叶间裂缺如；判断胸腔积液是否为叶间积液，也要依据叶间裂走行而非单纯位置。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0120", "t": "单选题", "s": "结合上述情景，患者男性，62岁，吸烟40年，低剂量CT筛查发现右肺门旁一直径12 mm的实性结节。呼吸科要求明确该结节位于哪一肺段、与哪一级支气管相邻，以便制定胸腔镜下肺段切除方案。原始数据为64排CT螺旋采集，可任意做薄层重建与后处理。作为技师，为准确完成肺段定位，最恰当的技术处理方案是", "o": {"A": "以≤1 mm层厚重建，沿段支气管走行做多平面重组（MPR）与曲面重组，逐级追踪叶—段支气管以确定结节所属肺段", "B": "直接在5 mm轴位图像上按结节与胸壁的距离估算肺段", "C": "只做冠状面10 mm厚层重组，观察结节与肺门的关系", "D": "做全肺最小密度投影（MinIP）后按气道透亮度判断肺段", "E": "增加管电流重新扫描一次，用高噪声抑制算法提高结节边缘清晰度"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHST-007", "kp": "肺段定位的重建策略", "ch": "一、人体断面影像解剖 → 3.胸部 → (3)主要断层影像解剖", "ex": "【为什么对】肺段的解剖学定义是“段支气管及其伴行肺动脉所支配的肺组织”，因此肺段定位的金标准是追踪支气管树。采用亚毫米（≤1 mm）薄层重建可获得各向同性体素，再沿支气管长轴做MPR／曲面重组，能够连续追踪主支气管—叶支气管—段支气管，确定结节归属，同时显示段间静脉这一段间分界标志，故A最恰当。【为什么错】B 5 mm厚层因部分容积效应无法分辨段支气管，用与胸壁距离估算属主观推测。C 10 mm厚层冠状重组丢失细节，且单一方位难以追踪三维走行的段支气管。D MinIP有利于显示气道整体形态与低密度病变，但不能明确结节与段支气管的三维隶属关系。E本例问题在于后处理方法而非图像噪声，重新扫描既增加受检者剂量又不解决定位问题，违背防护最优化原则。", "tr": "肺段定位要“跟着支气管走”，而不是“按胸壁分区猜”；段间静脉走行于相邻两段之间，可辅助勾画段界，段内动脉与段支气管伴行则确认段属。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0121", "t": "单选题", "s": "按Couinaud分段法，横断面上肝右静脉所分隔的两个肝区是", "o": {"A": "左内叶与左外叶", "B": "右前叶与右后叶", "C": "左半肝与右半肝", "D": "尾状叶与左外叶", "E": "S2段与S3段"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-001", "kp": "肝静脉与肝段分界", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】三支肝静脉是Couinaud分段的纵行分界标志：肝右静脉走行于右叶间裂内，将肝右叶分为右前叶（S5、S8）与右后叶（S6、S7），故选B。【为什么错】A左内叶与左外叶由肝左静脉及镰状韧带／静脉韧带裂分隔。C左、右半肝由肝中静脉与胆囊窝—下腔静脉连线（Cantlie线）所在平面分隔。D尾状叶（S1）以静脉韧带裂与左外叶相隔，并非肝右静脉。E S2与S3段由门静脉左支矢状部所在的横断平面上下分隔，与肝右静脉无关。", "tr": "“肝中静脉分左右、肝右静脉分前后、肝左静脉分内外”是三句核心口诀；而上下（S8/S5、S7/S6、S4a/S4b）的分界是门静脉左右支主干所在横断面，属于横行标志，切勿与纵行的肝静脉混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0122", "t": "多选题", "s": "关于Couinaud肝段划分所依据的断层影像标志，正确的有", "o": {"A": "肝中静脉与胆囊窝—下腔静脉连线所在的纵行平面（Cantlie线）分隔左、右半肝", "B": "镰状韧带／静脉韧带裂与肝左静脉分隔左外叶（S2、S3）与左内叶（S4）", "C": "门静脉左、右支主干所在的横断平面将各叶再分为上、下段", "D": "尾状叶（S1）接受左、右门静脉双重供血，其静脉直接回流入下腔静脉", "E": "S4段位于肝右叶前段，紧邻胆囊窝右侧"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-002", "kp": "Couinaud分段标志平面", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：Cantlie线为功能性左右半肝分界，其体表投影自胆囊窝中点至下腔静脉左缘，横断面上以肝中静脉为标志。B正确：左段间裂由肝左静脉及其上方的镰状韧带、下方的静脉韧带裂共同确定，分隔S2、S3与S4。C正确：门静脉左、右支主干所在的横断面为上下段的分界，其上为S8、S7、S4a、S2，其下为S5、S6、S4b、S3。D正确：尾状叶血供与回流均独立，门静脉左右支均有分支供血，肝短静脉直接汇入下腔静脉，故Budd-Chiari综合征时尾状叶代偿性肥大。【为什么错】E错误：S4为左内叶（方叶），位于镰状韧带／静脉韧带裂与肝中静脉之间，属左半肝，位于胆囊窝的左侧而非右侧；胆囊窝右侧为S5。", "tr": "S4属于左半肝这一点常被忽视——胆囊窝是左右半肝的分界，胆囊左侧是S4、右侧是S5；此外S1的“双重供血、直接回流”特点是尾状叶在肝硬化与Budd-Chiari中表现特殊的解剖基础。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0123", "t": "单选题", "s": "肾门层面横断面图像上，肾蒂内主要结构由前向后的排列顺序是", "o": {"A": "肾动脉、肾静脉、肾盂", "B": "肾静脉、肾动脉、肾盂", "C": "肾盂、肾动脉、肾静脉", "D": "肾静脉、肾盂、肾动脉", "E": "肾动脉、肾盂、肾静脉"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-003", "kp": "肾蒂结构排列顺序", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】肾蒂内结构由前向后依次为肾静脉、肾动脉、肾盂（可记为“静—动—盂”或“V-A-P”），横断面增强皮髓质期最易辨认，故选B。【为什么错】A、C、D、E均颠倒了三者的前后顺序。补充：左肾静脉较长，跨越腹主动脉前方汇入下腔静脉，若被腹主动脉与肠系膜上动脉夹持则形成“胡桃夹现象”；右肾动脉较长，需经下腔静脉后方向右走行，这两点是肾蒂断层解剖的重要延伸。", "tr": "肾蒂顺序为“前静后盂”，与肺门“前静后支”不同，也与肝门“前胆管、后门静脉、居中肝动脉”的三联管排列不同，三者常被交叉设错。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0124", "t": "多选题", "s": "有关腹膜后间隙的断层影像分区与内容，下列描述正确的有", "o": {"A": "肾旁前间隙位于后腹膜与肾前筋膜之间，含胰腺、十二指肠降部与水平部及升、降结肠", "B": "肾周间隙位于肾前筋膜与肾后筋膜之间，含肾、肾上腺、肾周脂肪及输尿管上段", "C": "肾旁后间隙位于肾后筋膜与腹横筋膜之间，主要为脂肪，无实质脏器", "D": "急性胰腺炎的渗出液最常首先累及肾旁前间隙", "E": "左、右肾周间隙在中线区广泛相通，故一侧积液常迅速蔓延至对侧"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-004", "kp": "腹膜后间隙三分区", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：肾旁前间隙前界为后腹膜、后界为肾前筋膜（Gerota筋膜），内含胰腺、十二指肠降部与水平部、升结肠与降结肠。B正确：肾周间隙位于肾前筋膜与肾后筋膜（Zuckerkandl筋膜）之间，内容为肾、肾上腺、输尿管上段及肾周脂肪。C正确：肾旁后间隙内仅有脂肪、血管与神经，无实质器官，向外与腹膜外脂肪相续。D正确：胰腺位于肾旁前间隙内，故急性胰腺炎渗液首先沿该间隙蔓延，向下可达髂窝。【为什么错】E错误：左右肾周间隙在中线区被大血管及其周围结缔组织分隔，一般不直接相通；两侧交通主要通过肾旁后间隙及骨盆入口区的潜在通道，且交通有限，故临床上肾周积液多为单侧局限。", "tr": "“肾周间隙左右不通、肾旁前间隙可向下延续至髂窝”是判断腹膜后积液来源的关键；胰腺炎渗液出现于肾旁前间隙、肾上腺出血局限于肾周间隙，反推可定位病变。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0125", "t": "单选题", "s": "上腹部CT横断面上，能够勾勒胰腺体尾部后缘、作为其可靠定位标志的血管是", "o": {"A": "肠系膜上动脉", "B": "脾静脉", "C": "腹腔干", "D": "左肾静脉", "E": "门静脉主干"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-005", "kp": "胰腺断层定位标志", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】脾静脉自脾门向右走行，紧贴胰腺体尾部的后缘，横断面上呈一条自左向右的细带状血管影，正好勾勒出胰体尾的后界，并在胰颈后方与肠系膜上静脉汇合成门静脉，因此是胰腺体尾部最可靠的定位标志，选B。【为什么错】A肠系膜上动脉起自腹主动脉前壁，位于胰颈后下方，其周围脂肪环是判断胰腺钩突与血管关系的标志，但不勾勒胰体尾后缘。C腹腔干位于胰腺上方水平（约T12），是胰腺上界的层面标志而非后缘。D左肾静脉走行于胰腺后方更深处、腹主动脉前方，位置低于脾静脉，二者不可混淆。E门静脉主干位于胰颈后方斜向右上走行至肝门，只能标志胰颈区。", "tr": "脾静脉与左肾静脉在横断面上都呈横行走行、易混淆：脾静脉紧贴胰后缘、位置偏上偏前；左肾静脉跨越腹主动脉前方、位置偏下偏后，且向右汇入下腔静脉。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0126", "t": "案例分析题", "s": "患者男性，64岁，进行性无痛性黄疸1个月。上腹部CT平扫加三期增强示胰头区一约30 mm低强化肿块，胆总管下段截断，胰管扩张。外科需要明确肿瘤与肠系膜上动脉、肠系膜上静脉及腹腔干的接触范围和角度，以评估可切除性。设备为128层CT，已获得0.625 mm薄层动脉期与门静脉期数据。为准确显示胰腺钩突与肠系膜上动脉的空间关系，技师应采取的最佳后处理方案是", "o": {"A": "以薄层横断面为基础，加做沿肠系膜上动脉长轴的斜冠状面与斜矢状面重组，并辅以曲面重组测量肿瘤—血管接触弧度", "B": "仅保留5 mm常规横断面图像，由医师直接阅片判断", "C": "对全部数据做大范围最大密度投影（MIP），仅提供血管整体图像", "D": "做容积再现（VR）彩色三维图像替代所有断面图像", "E": "将门静脉期图像做10 mm厚层冠状重组以突出肿瘤边界"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-006", "kp": "胰腺钩突与肠系膜血管关系评估", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】胰腺钩突自胰头下部向左后方延伸，位于肠系膜上静脉与肠系膜上动脉的后方、下腔静脉与腹主动脉的前方，三者呈“前—中—后”叠置关系。单纯横断面难以完整显示纵向走行的肠系膜上动脉全长，故需以薄层横断面为基础，沿血管长轴加做斜冠状／斜矢状重组，并用曲面重组测量肿瘤包绕血管的接触弧度（＜180°与≥180°是判断可切除性的关键阈值），故A最恰当。【为什么错】B 5 mm厚层分辨率不足，无法准确测量接触弧度与判断钩突边界。C MIP会把肿瘤等软组织信息叠掩，只适合展示血管走行，不能替代断面评估。D VR为表面渲染性质的展示图，受阈值影响大，不能用于定量测量与浸润判断。E 10 mm厚层因部分容积效应会人为夸大或掩盖肿瘤与血管的接触面。", "tr": "钩突“绕到肠系膜上静脉后方”是其独有特征，横断面上表现为胰头下部向左侧延伸的楔形组织；勿把钩突正常组织误判为肿块，也勿仅凭横断面判断动脉包绕程度。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0127", "t": "案例分析题", "s": "患者女性，48岁，乙肝肝硬化随访，上腹部MRI发现肝内一枚直径15 mm结节，介入科拟行射频消融，要求影像报告精确注明结节所在的Couinaud肝段及与邻近肝静脉、门静脉分支的距离。技师需在3.0 T设备上完成检查，并在工作站上完成分段定位标注。为使肝段定位准确可靠，最恰当的做法是", "o": {"A": "以屏气薄层T1加权三维梯度回波（T1-FFE／VIBE／LAVA）门静脉期数据为基础，先在横断面上辨认三支肝静脉与门静脉左右支主干平面，再据此逐层划分肝段", "B": "在T2WI上按结节距肝右缘的距离估算肝段", "C": "以体表肋骨计数投影推算结节所在肝段", "D": "仅用弥散加权成像（DWI）高信号灶的位置确定肝段", "E": "以冠状面单次激发快速自旋回波（SSFSE／HASTE）图像作为分段的唯一依据"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-007", "kp": "MRI肝段定位技术", "ch": "一、人体断面影像解剖 → 4.腹部 → (2)MRI断层表现", "ex": "【为什么对】Couinaud分段依赖两类标志：纵行的三支肝静脉（分左右、分前后、分内外）与横行的门静脉左右支主干平面（分上下段）。屏气薄层三维扰相梯度回波序列在门静脉期可同时清晰显示肝静脉与门静脉分支，层厚薄、无呼吸伪影，是分段定位的最佳数据源，故A正确。【为什么错】B按距肝缘距离估算完全不符合以血管为界的分段原则。C体表肋骨计数受体位、呼吸相与个体差异影响极大，不能用于肝段定位。D DWI层厚较厚、几何变形明显、缺少血管解剖信息，只能提示病灶存在。E冠状面SSFSE可辅助观察病灶上下位置，但难以显示肝静脉与门静脉分支的完整走行，不能作为唯一依据。", "tr": "肝段定位一定要“先找血管再定段”；此外应注意扫描时的屏气状态一致，呼吸相不同会造成同一结节在不同序列上跨段错位，影响消融布针。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0128", "t": "单选题", "s": "女性盆腔MRI矢状面T2WI上，子宫体自内向外呈现三层信号，其中“结合带”表现为", "o": {"A": "最内层的高信号带，代表子宫内膜", "B": "内膜外侧的低信号带，代表内层子宫肌层", "C": "最外层的中等信号带，代表外层子宫肌层", "D": "浆膜面的极低信号线，代表子宫浆膜", "E": "宫腔内的无信号区，代表宫腔积气"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-001", "kp": "子宫T2WI三层结构", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】育龄期女性子宫体在T2WI上自内向外呈三层：内层为高信号的子宫内膜，中层为低信号的结合带（junctional zone，即排列致密、含水量低的内层肌层），外层为中等信号的外层子宫肌层，故选B。【为什么错】A最内层高信号是子宫内膜本身，不是结合带。C最外层中等信号为外层肌层。D浆膜层极薄，MRI上通常不能单独分辨为一层。E宫腔正常不含气，宫腔积气属病理表现，与三层结构无关。", "tr": "结合带增厚（一般＞12 mm）是子宫腺肌症的重要征象，而结合带的中断则是判断子宫内膜癌肌层浸润深度的关键；勿把T2WI上低信号的结合带误认为是子宫内膜或病变。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0129", "t": "多选题", "s": "结合上述情景，关于盆底与会阴部的断层影像解剖，下列描述正确的有", "o": {"A": "肛提肌由耻骨直肠肌、耻骨尾骨肌和髂骨尾骨肌组成", "B": "坐骨肛门窝（坐骨直肠窝）内充满脂肪，横断面上呈尖端向上的楔形", "C": "直肠系膜由直肠固有筋膜包绕，内含脂肪、血管与淋巴结，是全直肠系膜切除的解剖基础", "D": "会阴中心腱（会阴体）位于肛管与阴道下段或尿道球之间", "E": "尿生殖膈位于肛提肌的上方，构成盆膈的上层"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-002", "kp": "盆底肌与会阴断层解剖", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：肛提肌为盆膈主体，由耻骨直肠肌、耻骨尾骨肌与髂骨尾骨肌三部分构成，MRI冠状面显示其“漏斗状”形态最佳。B正确：坐骨肛门窝位于肛管两侧，上界为肛提肌下面、外侧界为闭孔内肌与坐骨结节，内充脂肪，横断面呈尖向上的楔形（冠状面呈三角形），是肛周脓肿与瘘管好发部位。C正确：直肠系膜是直肠周围由直肠固有筋膜包绕的脂肪结缔组织，含直肠上血管与淋巴结，其筋膜（MRF）是否受累决定直肠癌手术方式与新辅助治疗决策。D正确：会阴中心腱是多块会阴肌的共同附着点，女性位于阴道下段与肛管之间，男性位于尿道球与肛管之间。【为什么错】E错误：尿生殖膈位于盆膈（肛提肌与尾骨肌）的下方、尿生殖三角内，不在肛提肌上方，更不构成盆膈的上层。", "tr": "盆膈在上、尿生殖膈在下，二者上下关系颠倒是常见错误；此外坐骨肛门窝内的脂肪信号是判断肛瘘走行分级（括约肌间型、经括约肌型、括约肌上型、括约肌外型）的背景对照。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0130", "t": "单选题", "s": "男性盆腔横断面上，位于膀胱后方、前列腺上方两侧，呈“八字形”或“兔耳”样的结构是", "o": {"A": "输精管壶腹", "B": "精囊腺", "C": "输尿管末段", "D": "直肠膀胱陷凹", "E": "前列腺静脉丛"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-003", "kp": "精囊腺断层形态", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (1)CT断层表现", "ex": "【为什么对】精囊腺位于膀胱底后方、前列腺上方、直肠前方，为一对迂曲呈囊袋状的腺体，横断面上左右对称向外后方张开，形似“八字”或“兔耳”，T2WI上因富含液体呈明显高信号，故选B。【为什么错】A输精管壶腹位于两侧精囊腺的内侧，管径较细，呈条状，不构成“兔耳”外形。C输尿管末段自后外斜向前内穿膀胱壁，管径细小，且不成对呈囊袋状。D直肠膀胱陷凹是腹膜返折形成的腔隙，位于膀胱与直肠之间，非实性成对结构。E前列腺静脉丛（Santorini丛）位于前列腺前外侧与耻骨联合之间，不在膀胱后上方。", "tr": "精囊角（膀胱后壁与精囊之间的脂肪间隙）消失是前列腺癌或膀胱癌侵犯精囊的重要征象；勿把T2WI上高信号的正常精囊误判为囊性病变。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0131", "t": "单选题", "s": "仰卧位时女性腹膜腔的最低部位、少量盆腔积液最先积聚的解剖间隙是", "o": {"A": "膀胱子宫陷凹", "B": "直肠子宫陷凹", "C": "卵巢窝", "D": "膀胱前间隙", "E": "闭孔内肌旁间隙"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-004", "kp": "盆腔腹膜陷凹", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】直肠子宫陷凹（又称Douglas窝）位于子宫与直肠之间，是女性站立位与仰卧位时腹膜腔的最低点，少量腹腔积液、积血或腹膜转移种植最先出现于此，故选B。【为什么错】A膀胱子宫陷凹位置较高、较浅，积液出现晚于直肠子宫陷凹。C卵巢窝位于髂内、髂外血管夹角处的盆侧壁，为卵巢所在位置，不是最低点。D膀胱前间隙（Retzius间隙）位于腹膜外，不与腹膜腔相通，其内积液多为膀胱破裂或血肿。E闭孔内肌旁间隙不属于腹膜腔陷凹。", "tr": "男性对应的最低点为直肠膀胱陷凹；此外要注意膀胱前间隙为腹膜外间隙，其积液性质与腹膜腔积液的临床意义完全不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0132", "t": "案例分析题", "s": "患者男性，60岁，便血3个月，肠镜示距肛缘7 cm处直肠肿物，病理为腺癌。外科要求术前MRI明确肿瘤浸润深度、直肠系膜筋膜（MRF）是否受累以及壁外血管侵犯情况，以决定是否行新辅助放化疗。设备为3.0 T MRI，使用体部相控阵线圈。为满足上述分期要求，技师在扫描方位设置上最恰当的做法是", "o": {"A": "先获取正中矢状面定位，再设置垂直于病变段直肠肠管长轴的斜横断面高分辨小视野T2WI，并辅以平行于肠管长轴的斜冠状面", "B": "沿人体解剖轴设置常规横断面T2WI，层厚6 mm，视野40 cm", "C": "仅采集矢状面T2WI与横断面T1WI增强，不做斜断面", "D": "采用大视野横断面脂肪抑制T2WI以覆盖全盆腔淋巴结", "E": "以弥散加权成像替代高分辨T2WI进行分期"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-005", "kp": "直肠MRI分期的斜断面设置", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】直肠在盆腔内呈骶曲与会阴曲，肠管长轴与人体解剖横轴并不垂直。只有以正中矢状面定位、设置垂直于病变段肠管长轴的斜横断面，才能获得肠壁的真正“横截面”，准确判断肿瘤突破固有肌层的深度（T分期）以及肿瘤最外缘与直肠系膜筋膜之间的最短距离（MRF状态）。高分辨（层厚3 mm、小视野、高矩阵）T2WI是国际公认的直肠癌分期序列，斜冠状面则有助于评估低位肿瘤与肛提肌、括约肌复合体的关系，故A正确。【为什么错】B常规横断面斜切肠壁会造成部分容积效应，人为夸大浸润深度；6 mm层厚与40 cm视野分辨率不足。C缺少与肠管垂直的斜断面，无法准确测量MRF距离；且直肠癌分期以高分辨T2WI为主，增强并非必需。D脂肪抑制会消除直肠系膜脂肪与肿瘤的天然对比，反而不利于判断MRF受累与壁外血管侵犯。E DWI敏感性高但空间分辨率低、几何变形明显，只能作为T2WI的补充，不能替代分期序列。", "tr": "直肠MRI分期的高分辨T2WI原则上不加脂肪抑制——直肠系膜脂肪的高信号背景正是判断肿瘤外侵与MRF距离的对比来源；斜横断面“垂直于肿瘤所在段肠管”而非垂直于整个直肠。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0133", "t": "单选题", "s": "腰椎MRI上，经L4／5椎间孔穿出椎管的神经根是", "o": {"A": "L3神经根", "B": "L4神经根", "C": "L5神经根", "D": "S1神经根", "E": "马尾神经末端"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-001", "kp": "腰椎间孔与神经根对应关系", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (2)MRI断层表现", "ex": "【为什么对】腰段脊神经根自同序数椎体下方的椎间孔穿出，即L4神经根经L4／5椎间孔出椎管，故选B。该神经根在孔内位于孔的上部、紧邻上位椎弓根下缘，称为“出口根”。【为什么错】A L3神经根经L3／4椎间孔穿出。C L5神经根经L5／S1椎间孔穿出；但L5在L4／5水平已离开硬膜囊并沿侧隐窝下行，称为该节段的“走行根”，旁中央型L4／5椎间盘突出压迫的正是L5而非L4。D S1神经根经S1骶前孔穿出，在L5／S1水平为走行根。E马尾神经在腰段椎管内成束下行，不特指某一椎间孔的穿出根。", "tr": "同一椎间盘水平存在“出口根”与“走行根”两套神经根：椎间孔型（极外侧型）突出压迫出口根（L4／5压迫L4），旁中央型突出压迫走行根（L4／5压迫L5）；把二者混淆是最典型的失分点。颈段规律与腰段不同——颈神经根从同序数椎体上方的椎间孔穿出，C8经C7／T1孔穿出。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0134", "t": "多选题", "s": "有关椎管横断面的影像解剖，下列描述正确的有", "o": {"A": "硬膜外间隙内含脂肪与静脉丛，以腰段最为丰富", "B": "黄韧带附着于相邻椎板的前面，T2WI上呈相对低信号", "C": "侧隐窝前界为椎体后缘或椎间盘，后界为上关节突，外侧界为椎弓根内缘", "D": "成人脊髓圆锥末端多位于第1腰椎下缘水平", "E": "齿状韧带位于脊髓正后方中线处，连接软脊膜与硬脊膜"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-002", "kp": "椎管内结构断层解剖", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：硬膜外间隙位于硬脊膜与椎管骨壁之间，含脂肪、椎内静脉丛与结缔组织，腰段脂肪最丰富，是T1WI上勾勒硬膜囊轮廓的天然对比。B正确：黄韧带由弹力纤维构成，连接相邻椎板前面，T1WI与T2WI均呈相对低信号，肥厚时可致椎管后方受压。C正确：侧隐窝是神经根离开硬膜囊后进入椎间孔前的通道，其三个边界即前为椎体后缘／椎间盘、后为上关节突、外为椎弓根内缘，狭窄时压迫走行根。D正确：成人脊髓圆锥末端多位于T12下缘至L1下缘水平，低于L2下缘则提示脊髓栓系。【为什么错】E错误：齿状韧带位于脊髓两侧、脊神经前根与后根之间，呈三角形齿状突起连于硬脊膜，起固定脊髓的作用，并非位于脊髓正后方中线。", "tr": "侧隐窝狭窄与椎间孔狭窄压迫的神经根不同：侧隐窝压迫走行根，椎间孔压迫出口根；此外脊髓圆锥位置是判断脊髓栓系的定量指标，勿凭印象报告。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0135", "t": "单选题", "s": "颈椎CT横断面上，成人寰齿前间隙（寰椎前弓后缘与齿突前缘之间距离）的正常上限约为", "o": {"A": "1 mm", "B": "2 mm", "C": "3 mm", "D": "5 mm", "E": "7 mm"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-003", "kp": "寰枢关节测量标准", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (1)CT断层表现", "ex": "【为什么对】寰齿前间隙由寰椎横韧带维持，成人正常不超过3 mm，超过3 mm提示寰椎横韧带损伤或松弛（如类风湿关节炎、外伤、先天性齿突畸形），故选C。【为什么错】A、B为正常范围内的常见数值，但不是判定上限。D 5 mm是儿童（12岁以下）的正常上限，因儿童韧带较松弛、齿突尚未完全骨化，若用于成人会漏诊寰枢不稳。E 7 mm已明显超出成人与儿童的正常范围，提示横韧带完全断裂。", "tr": "成人≤3 mm、儿童≤5 mm是一对必须分清的数值；此外横断面测量易受层面倾斜影响，标准做法是在寰椎前弓与齿突同层的横断面或正中矢状面重组图像上测量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0136", "t": "案例分析题", "s": "患者男性，55岁，右下肢放射痛3个月，疼痛沿大腿前外侧至小腿内侧分布，膝反射减弱，符合L4神经根受累表现。腰椎MRI常规横断面未见明显中央型或旁中央型椎间盘突出，硬膜囊形态正常。临床高度怀疑椎间孔区或极外侧病变。设备为1.5 T MRI。为明确椎间孔内神经根的受压情况，最应重点采集或重点观察的图像是", "o": {"A": "经双侧椎间孔的旁矢状面薄层T1WI，观察孔内脂肪是否被病变取代及神经根形态", "B": "正中矢状面T2WI，观察椎管前后径", "C": "冠状面脂肪抑制T2WI，观察椎旁肌信号", "D": "横断面梯度回波T2*加权，观察椎体骨髓信号", "E": "全脊柱大范围矢状面定位像，测量脊柱曲度"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-004", "kp": "椎间孔狭窄的成像方位选择", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (2)MRI断层表现", "ex": "【为什么对】腰椎间孔在旁矢状面上呈上宽下窄的“倒泪滴”形，孔内神经根位于上部，被高信号脂肪环绕。T1WI上脂肪信号高、神经根呈中等信号，两者对比最佳，一旦孔内脂肪被突出椎间盘、骨赘或囊肿取代，即提示椎间孔狭窄与出口根受压，故A最恰当。本例症状为L4出口根受累而横断面阴性，正是极外侧／椎间孔型突出的典型情况。【为什么错】B正中矢状面只能评价中央椎管，无法显示位于侧方的椎间孔。C冠状面脂肪抑制T2WI主要用于评估椎旁软组织与骶髂关节，且脂肪抑制反而消除了椎间孔内脂肪这一重要对比。D T2*加权对骨髓与出血敏感，与椎间孔神经根受压评估无关。E定位像分辨率低，只能测曲度，不能评估神经根。", "tr": "极外侧型（椎间孔外）椎间盘突出在常规横断面上位于扫描范围边缘，极易漏诊；凡症状与影像不符的根性痛，务必加做旁矢状面T1WI并适当扩大横断面覆盖至椎弓根外缘。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0137", "t": "单选题", "s": "腕关节影像上，近侧列腕骨由桡侧向尺侧的排列顺序是", "o": {"A": "手舟骨、月骨、三角骨、豌豆骨", "B": "大多角骨、小多角骨、头状骨、钩骨", "C": "月骨、手舟骨、豌豆骨、三角骨", "D": "手舟骨、大多角骨、月骨、三角骨", "E": "头状骨、月骨、三角骨、钩骨"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-001", "kp": "腕骨排列与识别", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (1)CT断层表现", "ex": "【为什么对】腕骨共8块，分近、远两列。近侧列由桡侧向尺侧依次为手舟骨、月骨、三角骨、豌豆骨，故选A。【为什么错】B为远侧列腕骨的正确排列（大多角骨、小多角骨、头状骨、钩骨），题目问的是近侧列。C颠倒了手舟骨与月骨、三角骨与豌豆骨的顺序。D把远侧列的大多角骨混入近侧列。E把远侧列的头状骨与钩骨混入近侧列。", "tr": "豌豆骨是籽骨，位于三角骨掌侧，在横断面上比其他近侧列腕骨更靠掌侧、层面更低；手舟骨腰部骨折因血供自远端逆行进入，近端易发生缺血坏死，是CT／MRI追加检查的重点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-0138", "t": "多选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，关于膝关节MRI的断层影像解剖，下列描述正确的有", "o": {"A": "前交叉韧带起自胫骨髁间隆起前区，止于股骨外侧髁的内侧面，斜矢状面显示最佳", "B": "后交叉韧带在矢状面上呈弓形，正常时各序列均呈较均匀低信号", "C": "半月板在矢状面周边层面呈“领结征”，靠近中央的层面呈前后两个三角形", "D": "关节软骨在质子密度加权脂肪抑制序列上与关节液、软骨下骨的对比较好", "E": "内侧半月板较外侧半月板活动度大，因此更易发生撕裂"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-002", "kp": "膝关节MRI断层解剖", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】A正确：前交叉韧带自胫骨髁间隆起前区斜向后上外，止于股骨外侧髁内侧面，其走行与矢状面成角，需将扫描平面向外旋转约15°做斜矢状面才能在单一层面完整显示。B正确：后交叉韧带纤维致密、含水量低，矢状面呈弓形，各序列均为均匀低信号，若出现内部高信号提示损伤。C正确：矢状面上周边层面切到半月板体部，前后角相连呈“领结征”（bow-tie sign），越靠近关节中央越只见前、后角两个三角形。D正确：质子密度加权脂肪抑制序列兼具较高信噪比与软骨—关节液对比，是关节软骨评价的常用序列。【为什么错】E错误：内侧半月板呈“C”形，其外缘与内侧副韧带深层及关节囊紧密相连，活动度小、缓冲能力差，因此更容易撕裂；外侧半月板近“O”形，与外侧副韧带之间隔有腘肌腱，活动度反而更大。", "tr": "“活动度小反而更易撕裂”与直觉相反，是内侧半月板撕裂发生率更高的力学原因；另需注意“领结征”少于两个层面提示桶柄样撕裂，是矢状面判读的重要间接征象。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-0139", "t": "单选题", "s": "肩关节MRI斜冠状面上，构成肩袖上部、经肩峰下间隙走行且最常发生撕裂的肌腱是", "o": {"A": "肩胛下肌腱", "B": "冈上肌腱", "C": "冈下肌腱", "D": "小圆肌腱", "E": "肱二头肌长头腱"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-003", "kp": "肩袖构成与成像方位", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】肩袖由冈上肌、冈下肌、小圆肌和肩胛下肌四条肌腱构成。冈上肌腱位于肩袖上部，自冈上窝经肩峰与肱骨头之间的肩峰下间隙止于肱骨大结节上压迹，此处空间狭小、血供相对乏乏（“危险区”位于止点内侧约1 cm），撞击与退变最重，是最常撕裂的肌腱，斜冠状面（平行于冈上肌腱长轴）显示最佳，故选B。【为什么错】A肩胛下肌腱位于肩袖前部，止于小结节，斜横断面显示最佳。C冈下肌腱位于肩袖后上部，止于大结节中压迹。D小圆肌腱位于肩袖后下部，止于大结节下压迹，撕裂少见。E肱二头肌长头腱并不属于肩袖，它经结节间沟进入关节内止于盂上结节，属关节内滑膜外结构。", "tr": "肱二头肌长头腱常被误列入肩袖；肩关节MRI三个基本方位各有分工——斜冠状面看冈上肌腱、斜矢状面看肩袖间隙与肩峰形态、横断面看肩胛下肌腱与盂唇前后部。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1001", "t": "单选题", "s": "结合上述情景，颅脑CT增强横断面图像上，小脑幕的典型形态与位置是", "o": {"A": "在颅前窝呈水平走行的低密度线状影", "B": "在颅后窝上方呈“V”形（或“八”字形）走行的致密线状影", "C": "在颅中窝呈横行的低密度宽带影", "D": "在小脑半球之间呈垂直走行的致密带", "E": "在枕骨内板下方呈新月形低密度影"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-101", "kp": "小脑幕断层表现", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】小脑幕为硬脑膜突入颅腔形成的结构，分隔枕叶与小脑，其游离缘围成小脑幕切迹。横断面增强扫描或老年钙化时，小脑幕呈自前内侧向后外侧走行、形似“V”字（“八”字形）的致密线状影，故选B。【为什么错】A小脑幕位于颅后窝，不位于颅前窝；颅前窝内容以额叶为主。C颅中窝主要为颞叶与蝶鞍区结构，小脑幕在颅后窝上方而非颅中窝。D垂直走行、分隔左右小脑半球的硬脑膜结构是小脑镰，小脑幕呈斜行。E新月形低密度影多见于硬膜下积液（血）或蛛网膜下腔增宽，与硬脑膜内层结构无关。", "tr": "小脑幕（斜行、分隔枕叶与小脑）与小脑镰（垂直、分隔左右小脑半球）形态与位置不同，是断层识别的经典易混点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1002", "t": "单选题", "s": "正中矢状面MRI上，第四脑室的位置与形态正确的是", "o": {"A": "位于脑桥腹侧，呈水平带状低信号", "B": "位于脑桥与延髓后方、小脑前方，呈帐篷状（三角形）", "C": "位于中脑导水管前方，呈裂隙状", "D": "位于小脑蚓部后上方，呈类圆形", "E": "位于延髓腹侧，呈新月形"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-102", "kp": "第四脑室MRI断层表现", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】第四脑室位于脑桥、延髓背侧与小脑腹侧之间，上借中脑导水管通第三脑室，下连脊髓中央管。正中矢状面上其轮廓呈顶朝后上、底朝前下的帐篷状（近似三角形），T1WI呈均匀低信号，故选B。【为什么错】A脑桥腹侧为桥前池，第四脑室在其背侧。C中脑导水管位于第四脑室上方、中脑内，其前方为四叠体池，并非导水管位于第四脑室前方。D小脑蚓部后上方为枕大池（小脑延髓池），呈三角形或新月形脑脊液信号，非第四脑室。E延髓腹侧为延髓前池，第四脑室在延髓背侧。", "tr": "第四脑室横断面呈菱形（菱形窝概念），矢状面呈帐篷状（三角形），两种断面形态勿混；第四脑室始终位于脑干背侧、小脑腹侧。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1003", "t": "单选题", "s": "正中矢状面T1WI上，关于胼胝体的形态学描述正确的是", "o": {"A": "胼胝体自前向后依次分为嘴部、膝部、体部、压部", "B": "胼胝体位于侧脑室体部的后方", "C": "胼胝体膝部与穹窿相延续", "D": "胼胝体压部位于嘴部的前方", "E": "胼胝体是大脑皮质灰质的一部分"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-103", "kp": "胼胝体矢状面解剖", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】胼胝体是连接两侧大脑半球的最大连合纤维，位于大脑纵裂底，正中矢状面上自前向后依次为嘴部（最前下方）、膝部、体部、压部（最后方），故选A。【为什么错】B胼胝体位于侧脑室体部上方，其下为透明隔与侧脑室，而非位于其后方。C与胼胝体相延续的是穹窿附近的穹窿连合，胼胝体膝部并不与穹窿延续；穹窿位于胼胝体下方、第三脑室上方。D压部是胼胝体最后方的膨大部，嘴部在最前方，两者位置颠倒。E胼胝体为白质纤维束（连合纤维），不是灰质。", "tr": "胼胝体四部分由前向后的顺序（嘴、膝、体、压）易倒置；它属白质连合纤维而非灰质，正中矢状面显示最清楚。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1004", "t": "单选题", "s": "经桥小脑角池层面的横断面CT上，池内穿行的颅神经是", "o": {"A": "视神经与动眼神经", "B": "面神经与前庭蜗神经", "C": "舌咽神经与迷走神经", "D": "三叉神经与展神经", "E": "嗅神经与滑车神经"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-104", "kp": "桥小脑角池内容物", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】桥小脑角池位于脑桥与小脑之间、内耳门前内侧，面神经（Ⅶ）与前庭蜗神经（Ⅷ）自脑干发出后经该池进入内听道，故选B。【为什么错】A视神经走行于眶内及视神经管，动眼神经位于脚间池及鞍上池区域。C舌咽神经、迷走神经位于延髓外侧池（桥小脑角池下方）及颈静脉孔附近。D三叉神经位于桥前池，其神经节位于Meckel腔（三叉神经腔）；展神经位于桥前池下部。E嗅神经在嗅沟，滑车神经细长、走行于环池。", "tr": "面神经与前庭蜗神经（Ⅶ、Ⅷ）共同穿桥小脑角池进入内听道；三叉神经（Ⅴ）位于桥前池及Meckel腔，两者池别最易混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1005", "t": "单选题", "s": "成人颅脑CT上，松果体钙化的解剖定位标志是", "o": {"A": "位于鞍上池的中央", "B": "位于四叠体池内、紧邻第三脑室后方", "C": "位于侧脑室三角区内", "D": "位于桥小脑角池内", "E": "位于枕大池内"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-105", "kp": "松果体钙化定位", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】松果体位于中脑背侧、四叠体池内，其前上方紧邻第三脑室后部（松果体隐窝），成人钙化发生率很高，是颅脑CT上重要的解剖定位标志，故选B。【为什么错】A鞍上池中央可见视交叉与垂体柄，松果体位置远在其后上方。C侧脑室三角区内的生理钙化为脉络丛球钙化，松果体不位于脑室内。D桥小脑角池位于脑桥外侧，内为面神经与前庭蜗神经。E枕大池位于颅后窝小脑后方与枕骨之间，内为脑脊液。", "tr": "松果体钙化（四叠体池、第三脑室后）与脉络丛球钙化（侧脑室三角区）是CT上两个常见的生理性钙化，位置一前一后，极易混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1006", "t": "单选题", "s": "结合上述情景，经第三脑室层面的横断面CT上，位于丘脑外侧、内囊外方的灰质核团是", "o": {"A": "尾状核头", "B": "豆状核", "C": "杏仁核", "D": "屏状核", "E": "红核"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-106", "kp": "基底节区核团位置关系", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】第三脑室层面由内向外可见丘脑、内囊后肢、豆状核（由壳核与苍白球组成）、屏状核、岛叶。内囊位于丘脑与豆状核之间，豆状核位于丘脑外侧、内囊外方，故选B。【为什么错】A尾状核头位于内囊前肢的内侧、侧脑室前角外侧。C杏仁核位于颞叶钩回内侧，属边缘系统，位置更靠下。D屏状核位于豆状核与岛叶皮质之间，较豆状核更靠外，不符合“内囊外方紧邻”的定位。E红核位于中脑被盖部，在第三脑室层面更下方。", "tr": "基底节断层“内囊前肢—尾状核头、内囊后肢—丘脑、豆状核—内囊外”的毗邻顺序常设陷阱；屏状核在豆状核更外侧、紧邻岛叶。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1007", "t": "单选题", "s": "鞍上池层面横断面CT上，视交叉的解剖位置是", "o": {"A": "位于垂体柄后方，呈圆形钙化影", "B": "位于鞍上池中央前部，呈“束带”状连接双侧视神经与视束", "C": "位于大脑脚之间，呈三角形", "D": "位于外侧裂池内", "E": "位于脑桥前方，呈线状低密度"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-107", "kp": "视交叉断层解剖", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】视交叉位于鞍上池内偏前部，呈“束带”状（蝴蝶结样）软组织影，前接双侧视神经，后连双侧视束，是鞍上池内最重要的结构之一，故选B。【为什么错】A垂体柄位于视交叉后方、偏下方，视交叉位于其前方，而非垂体柄位于前方；且视交叉为软组织影而非钙化。C大脑脚之间为脚间池，内有动眼神经穿行。D外侧裂池位于额颞叶之间，视交叉与其无关。E脑桥前方为桥前池，内有三叉神经等。", "tr": "鞍上池内视交叉（前、“束带”状）与垂体柄（后、居中）的前后毗邻关系是常考点，两结构位置颠倒即成为陷阱选项。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1008", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，分隔两侧侧脑室前角与体部的膜性结构是", "o": {"A": "透明隔", "B": "穹窿", "C": "丘脑", "D": "尾状核", "E": "脉络丛"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-108", "kp": "透明隔断层解剖", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】透明隔是位于两侧侧脑室前角与体部之间的薄层膜性结构，由两层神经胶质组成，其前下方为胼胝体膝部，后上方为胼胝体体部，故选A。【为什么错】B穹窿位于透明隔下方、第三脑室顶壁，是边缘系统纤维束，不直接分隔侧脑室。C丘脑位于第三脑室两侧、侧脑室下方。D尾状核位于侧脑室前角外侧，不参与分隔。E脉络丛位于侧脑室体部底壁及第三、四脑室顶，为脑脊液产生部位。", "tr": "透明隔（分隔左右侧脑室）与穹窿（第三脑室上方）位置相邻、功能不同，横断面上两者易被误认为同一结构。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1009", "t": "单选题", "s": "颅脑横断面CT平扫上，正常脑白质的CT值约为", "o": {"A": "0～10 HU", "B": "20～24 HU", "C": "30～35 HU", "D": "60～100 HU", "E": "1000 HU以上"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-109", "kp": "颅脑正常结构CT值", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】颅脑CT平扫中，正常脑白质CT值约为30～35 HU，灰质约35～40 HU，两者相差仅约5 HU，灰质略高于白质，故选C。【为什么错】A 0～10 HU为脑脊液（脑室、脑池）的CT值范围。B 20～24 HU偏低，更接近水肿或囊变区。D 60～100 HU为钙化灶的常见范围。E 1000 HU以上为致密骨皮质（内耳、颞骨岩部）的CT值。", "tr": "灰质（35～40 HU）与白质（30～35 HU）CT值仅相差5 HU左右，方向易记反（应为灰质略高于白质），是窗宽窗位调节中需牢记的数值。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1010", "t": "单选题", "s": "结合上述情景，横断面CT经侧脑室下角层面，下列结构定位描述错误的是", "o": {"A": "侧脑室下角—位于颞叶内", "B": "外侧裂—分隔额叶与颞叶", "C": "环池—围绕中脑", "D": "内听道—位于枕骨内", "E": "桥小脑角池—位于岩骨与小脑之间"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-110", "kp": "侧脑室下角层面结构定位", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】题干要求选出错误的定位描述。内听道位于颞骨岩部（岩锥）后内侧面，是面神经与前庭蜗神经穿行的骨性管道，而非位于枕骨内，故D错误。【为什么错】A侧脑室下角（颞角）确实伸入颞叶内，描述正确。B外侧裂是分隔额叶与颞叶的脑沟，其深部有岛叶，描述正确。C环池围绕中脑，连接四叠体池与脚间池，描述正确。E桥小脑角池位于颞骨岩部（岩骨）后内缘与小脑之间，面神经、前庭蜗神经穿行其中，描述正确。", "tr": "内听道位于颞骨岩部（而非枕骨），其前方为耳蜗、后方为前庭，是断层定位常考点；枕骨内对应枕大孔与枕内嵴。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1011", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，颈部CT横断面图像上，关于甲状腺的解剖描述正确的是", "o": {"A": "甲状腺左右叶位于气管前方，峡部位于气管两侧", "B": "甲状腺位于气管前外侧，峡部跨越气管前方连接左右叶", "C": "甲状腺位于颈动脉鞘的外侧", "D": "甲状腺位于胸锁乳突肌与椎体之间", "E": "甲状腺峡部位于环状软骨上方"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-101", "kp": "甲状腺断层解剖", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】甲状腺分为左右两个侧叶及中间的峡部，左右叶位于气管前外侧，峡部于第2～4气管软骨环前方跨越气管连接两叶，故选B。【为什么错】A将两叶与峡部的位置关系弄反：两叶在气管两侧，峡部在前方。C甲状腺位于颈动脉鞘内侧，颈总动脉、颈内静脉在甲状腺外侧，位置关系颠倒。D胸锁乳突肌与椎体之间为椎前结构及颈深淋巴结，甲状腺位于气管前方偏外。E峡部位于环状软骨下方（第2～4气管软骨环前方），环状软骨上方为甲状软骨及声门区。", "tr": "甲状腺“两叶贴气管两侧、峡部跨于气管前方”的位置关系，与甲状软骨（更高、声门区）、环状软骨（更低、气管起始）的层次区分是常考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1012", "t": "单选题", "s": "颈部CT上，可作为确定气管起始层面标志的喉软骨是", "o": {"A": "甲状软骨", "B": "环状软骨", "C": "会厌软骨", "D": "杓状软骨", "E": "舌骨"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-102", "kp": "环状软骨层面标志", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】环状软骨是喉部唯一的完整软骨环，构成喉的底座，其下缘即气管的起始部，因此颈横断面上环状软骨层面是确定气管起始的标志性层面，故选B。【为什么错】A甲状软骨是最大的喉软骨，呈盾牌状，位于环状软骨上方，属声门区上缘水平。C会厌软骨位于舌骨后方、喉入口前方，为扁平的弹性软骨。D杓状软骨位于真声带后方，参与构音，不成环。E舌骨是游离骨，不属喉软骨，位于甲状软骨上方。", "tr": "环状软骨（唯一完整软骨环、气管起始标志）与甲状软骨（最大喉软骨、声门区标志）的鉴别是颈部断层识别的经典考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1013", "t": "单选题", "s": "颈总动脉分叉为颈内、颈外动脉的横断面约平对", "o": {"A": "舌骨体水平", "B": "甲状软骨上缘水平（约C4椎体）", "C": "环状软骨水平", "D": "锁骨上窝水平", "E": "下颌骨下缘上方1 cm"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-103", "kp": "颈总动脉分叉水平", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】颈总动脉在甲状软骨上缘水平（约C4椎体平面）分为颈内动脉与颈外动脉，分叉处稍膨大称颈动脉窦，是颈动脉粥样硬化斑块的好发部位，故选B。【为什么错】A舌骨体约平C3水平，位于分叉部上方附近但并非分叉平面。C环状软骨约平C6水平，位于分叉部下方。D锁骨上窝水平已接近颈根部，远低于分叉部。E下颌骨下缘约平C2～C3水平，高于分叉部。", "tr": "颈总动脉分叉（甲状软骨上缘、C4）与甲状腺峡部（环状软骨下方、C6）的水平位置不同，颈部断层定位时极易混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "颈部", "页": 8}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1014", "t": "单选题", "s": "颈部横断面图像上，颈动脉鞘内包含的结构是", "o": {"A": "颈总动脉、颈内静脉、迷走神经", "B": "颈总动脉、椎动脉、舌下神经", "C": "颈外动脉、胸导管、膈神经", "D": "颈内动脉、颈外静脉、交感干", "E": "颈总动脉、喉返神经、副神经"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-104", "kp": "颈动脉鞘内容", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】颈动脉鞘是颈深筋膜包绕形成的血管神经鞘，内含颈总（内）动脉、颈内静脉与迷走神经，三者由内向外依次为动脉、静脉、迷走神经，故选A。【为什么错】B椎动脉走行于颈椎横突孔内，舌下神经经舌下神经管出颅，均不在颈动脉鞘内。C胸导管在左侧颈根部汇入静脉角，膈神经走行于前斜角肌前方，均与颈动脉鞘无关。D颈外静脉位于胸锁乳突肌表面皮下，交感干位于颈动脉鞘后方、椎前筋膜深面。E喉返神经走行于气管食管沟，副神经走行于颈动脉鞘后方及胸锁乳突肌深面。", "tr": "迷走神经在颈动脉鞘内（颈内静脉与颈总动脉之间后方），而交感干、膈神经、副神经均在鞘外，“鞘内外结构”是命题热点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1015", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，主动脉弓层面的胸部CT横断面上，位于主动脉弓前右侧的纵隔结构是", "o": {"A": "左主支气管", "B": "上腔静脉", "C": "食管", "D": "胸主动脉", "E": "心包"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-101", "kp": "主动脉弓层面纵隔结构", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】主动脉弓层面，上腔静脉位于主动脉弓的前右侧，二者在纵隔上部形成特征性关系；气管位于主动脉弓后方（略偏右），食管在气管后方，故选B。【为什么错】A左主支气管出现在气管隆突层面（主动脉弓下方），主动脉弓层面仅见气管。C食管位于主动脉弓后方、气管后方。D胸主动脉（降主动脉）位于主动脉弓的左后下方，主动脉弓层面已开始转为其延续。E心包位于主动脉弓下方的心包层面，更靠下。", "tr": "主动脉弓层面辨认“三血管”：主动脉弓（居中偏左）、上腔静脉（前右侧）、气管与食管（后方），上腔静脉的位置是易错点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1016", "t": "单选题", "s": "胸部CT上，气管隆突约位于胸椎哪一水平，其下方分为左右主支气管", "o": {"A": "第3胸椎下缘", "B": "第4～5胸椎水平", "C": "第7胸椎水平", "D": "第9胸椎水平", "E": "第12胸椎水平"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-102", "kp": "气管隆突定位水平", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】气管隆突位于气管分叉处，约平第4～5胸椎水平，与胸骨角（Louis角）平面相当，是胸部断层影像中重要的分界标志，故选B。【为什么错】A第3胸椎下缘约平主动脉弓上缘水平，略高于隆突。C第7胸椎为下腔静脉与心脏下缘、膈顶附近水平。D第9胸椎接近肝顶水平。E第12胸椎为膈肌及肾上腺水平，与气管分叉无关。", "tr": "胸骨角（第2肋软骨、第4～5胸椎）对应气管隆突与主动脉弓下缘，“隆突=第4～5胸椎”与“弓上缘=第3胸椎”需区分。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1017", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，右肺门层面的胸部CT横断面上，位于中间支气管后方的结构是", "o": {"A": "右上肺静脉", "B": "右肺动脉", "C": "右主支气管", "D": "食管", "E": "上腔静脉"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-103", "kp": "右肺门层面解剖", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】右肺门层面，中间支气管呈低密度含气管道位于肺门中心，其正后方紧邻食管（食管位于脊柱前、中间支气管与右肺之间），故选D。【为什么错】A右上肺静脉位于中间支气管前方及外侧。B右肺动脉位于中间支气管前方及外侧，其下干跨过支气管前方。C右主支气管在更上方已分出右上叶支气管，中间支气管是其延续，不在其“后方”。E上腔静脉位于纵隔前方、升主动脉右侧，距中间支气管较远。", "tr": "右肺门“肺动脉在前、支气管居中、静脉偏前下”的空间关系；食管紧贴中间支气管正后方，是纵隔淋巴结与食管病变鉴别的解剖基础。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1018", "t": "单选题", "s": "上腹部CT增强扫描中，胰头钩突的断层解剖位置是", "o": {"A": "位于肠系膜上静脉后方、下腔静脉前方", "B": "位于门静脉主干正前方", "C": "位于脾动脉前方", "D": "位于左肾静脉后方", "E": "位于腹主动脉正前方"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-111", "kp": "胰头钩突毗邻结构", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A正确：胰头钩突是胰头下部向内下方伸出的突起，位于肠系膜上静脉（SMV）后方、下腔静脉（IVC）前方，被肠系膜上血管与下腔静脉夹持；胰头癌时钩突增大可致肠系膜上血管受压移位。【为什么错】B门静脉主干位于胰颈后方、胰头上方，钩突位于其下方偏后方。C脾动脉沿胰体尾上缘走行，与钩突无直接毗邻。D左肾静脉跨腹主动脉前方走行，位于胰腺后下方，钩突不以其为界。E腹主动脉位于钩突的左后方，钩突紧邻下腔静脉前方而非主动脉正前方。", "tr": "钩突位于“肠系膜上静脉后方、下腔静脉前方”，与胰头被“十二指肠降部与下腔静脉夹持”是两个不同的夹持关系，勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1019", "t": "单选题", "s": "横断面CT增强扫描上，右肾上腺的典型形态是", "o": {"A": "三角形", "B": "倒“Y”形（“人”字形）", "C": "水平线形", "D": "圆形结节状", "E": "新月形贴于下腔静脉前方"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-102", "kp": "肾上腺断层形态", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】右肾上腺位于右肾上极内上方、下腔静脉后方、肝右叶内侧，横断面上呈倒“Y”形（“人”字形）或线形，故选B。【为什么错】A三角形是左肾上腺的典型形态。C水平线形为非典型描述，肾上腺有明确的肢体结构。D圆形结节提示肾上腺增生或腺瘤，正常肾上腺不呈圆形结节。E右肾上腺位于下腔静脉后方而非前方，新月形贴附不是其正常形态。", "tr": "左右肾上腺形态不对称：右侧呈倒“Y”/人字形，左侧呈三角形/半月形；位置一右（下腔静脉后方）一左（脾静脉后方），勿记反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1020", "t": "单选题", "s": "上腹部CT横断面上，关于胰尾与脾门位置关系的描述正确的是", "o": {"A": "胰尾位于脾门后方", "B": "胰尾位于脾门前方（脾脏内前方）", "C": "胰尾位于脾脏外侧", "D": "胰尾位于脾脏下方", "E": "胰尾与脾脏不相邻"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-103", "kp": "胰尾与脾门位置关系", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】胰尾自胰体向左延伸，位于脾门前方（脾脏内前方），脾静脉走行于胰尾后方，脾动脉沿胰体尾上缘走行，故选B。【为什么错】A胰尾在脾门前方而非后方，脾门后为左肾上极区域。C胰尾向脾门方向延伸，位于脾脏内侧，不会越过脾脏到外侧。D胰尾在脾门水平，与脾门相邻，脾脏下方为结肠脾曲。E胰尾与脾门关系密切，是脾脏血管与胰腺关系的解剖基础。", "tr": "胰尾紧邻脾门前方、脾静脉在其后方，此关系是胰腺尾部肿瘤与脾门结构鉴别的关键解剖依据。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1021", "t": "单选题", "s": "肾门层面横断面CT增强扫描，右肾静脉与下腔静脉的解剖关系是", "o": {"A": "右肾静脉短而粗，直接注入下腔静脉右侧壁", "B": "右肾静脉细长，绕腹主动脉后方注入下腔静脉", "C": "右肾静脉走行于腹主动脉前方汇入下腔静脉", "D": "右肾静脉汇入左肾静脉后再入下腔静脉", "E": "右肾静脉位于右肾动脉后方且较长"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-104", "kp": "右肾静脉与下腔静脉关系", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】右肾静脉短而粗，在肾门水平几乎水平走行，直接注入下腔静脉右侧壁；左肾静脉长，跨越腹主动脉前方后汇入下腔静脉左前壁，故选A。【为什么错】B右侧肾静脉短，长且绕腹主动脉后方的是左肾静脉的变异描述，方向错误。C跨越腹主动脉前方的是左肾静脉，不是右肾静脉。D左右肾静脉分别独立汇入下腔静脉，两者不相通汇。E右肾静脉短，右肾动脉反而较长（绕下腔静脉后方入右肾门），方向刚好相反。", "tr": "左右肾静脉长短相反：右短直入下腔、左长跨主动脉；而肾动脉是右长（绕下腔静脉）、左短，“动静脉长短”最容易记反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1022", "t": "单选题", "s": "结合上述情景，男性盆腔MRI轴位T2WI上，前列腺外周带与中央带（中央区+移行区）的信号特点正确的是", "o": {"A": "外周带呈高信号，中央带呈低信号", "B": "外周带呈低信号，中央带呈高信号", "C": "外周带与中央带均呈高信号", "D": "外周带与中央带均呈低信号", "E": "外周带呈低信号，中央带呈等信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-101", "kp": "前列腺T2WI分区信号", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】前列腺T2WI上，外周带富含腺体、含液量高，呈均匀高信号；中央带（中央区与移行区）富含平滑肌与基质、腺体少，呈低信号。前列腺癌好发于外周带，表现为外周带内低信号结节，故选A。【为什么错】B将两带信号完全颠倒，与T2WI实际表现不符。C两带信号存在明显差异，中央带为低信号，不会都呈高信号。D外周带为高信号，不会都呈低信号。E外周带应呈高信号而非低信号，中央带为低信号而非等信号。", "tr": "前列腺T2WI“外周带高、中央带低”的信号对比是前列腺癌诊断的基础，“中央带高信号”是常见陷阱选项。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1023", "t": "单选题", "s": "女性盆腔横断面图像上，正常卵巢最常见的定位标志是", "o": {"A": "膀胱两侧", "B": "子宫两侧、髂外动脉与髂内动脉之间的卵巢窝内", "C": "子宫直肠陷凹内", "D": "耻骨联合后方", "E": "骶骨前方紧贴直肠"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-102", "kp": "卵巢断层定位", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】卵巢位于盆腔侧壁、髂外动脉与髂内动脉之间的卵巢窝（ovarian fossa）内，即子宫体两侧偏上方，故B正确。【为什么错】A膀胱两侧主要为阔韧带及输尿管，卵巢位置更高、偏外侧。C子宫直肠陷凹（Douglas窝）为盆腔最低点、积液好发处，卵巢不位于其中。D耻骨联合后方为膀胱前区及膀胱。E骶骨前方为直肠与骶前区，卵巢位置在其前方偏外。", "tr": "卵巢在髂内外动脉分叉处（卵巢窝）、子宫两侧；绝经后卵巢萎缩缩小、识别困难时以髂血管为定位标志。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1024", "t": "单选题", "s": "结合上述情景，会阴部横断面图像上，位于肛管两侧、肛提肌下方的脂肪间隙是", "o": {"A": "坐骨直肠窝（坐骨肛门窝）", "B": "膀胱前间隙", "C": "直肠后间隙", "D": "闭孔内肌间隙", "E": "会阴浅隙"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-103", "kp": "坐骨直肠窝断层解剖", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】坐骨直肠窝（坐骨肛门窝）位于肛管两侧、肛提肌下方，为楔形脂肪间隙，两侧对称，内含肛门血管与阴部神经等，是肛周脓肿好发部位，故选A。【为什么错】B膀胱前间隙位于耻骨联合与膀胱之间，位置在会阴前方上方。C直肠后间隙位于直肠与骶骨之间，在肛管上方。D闭孔内肌间隙为闭孔内肌与周围结构间的潜在间隙，不特指肛管两侧。E会阴浅隙位于会阴浅筋膜与尿生殖膈下筋膜之间，位置更表浅且偏前。", "tr": "坐骨直肠窝（肛管两侧、肛提肌下方）与直肠后间隙（直肠与骶骨之间）一前外侧、一正后方，位置易混。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1025", "t": "单选题", "s": "结合上述情景，腰椎MRI矢状面T2WI上，正常椎间盘髓核的信号特点是", "o": {"A": "高信号，位于纤维环内后方", "B": "高信号，位于纤维环内", "C": "低信号，与纤维环相同", "D": "无信号区", "E": "与骨皮质信号一致的低信号"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-101", "kp": "椎间盘髓核MRI信号", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (2)MRI断层表现", "ex": "【为什么对】椎间盘由外周纤维环与中央髓核构成，髓核含水量高，T2WI呈高信号，位于纤维环包绕的中心部，故B正确。【为什么错】A髓核位于椎间盘中心，纤维环包绕其四周，“位于纤维环内后方”不准确；向后突出的髓核组织可位于后部，但正常髓核居中。C纤维环在T2WI呈低信号，髓核为高信号，两者不同。D髓核有明确信号，不是无信号。E髓核高信号与骨皮质低信号截然不同。", "tr": "年轻正常椎间盘“纤维环低信号+髓核高信号”；老年退变髓核因脱水信号降低，勿将正常年轻表现与退变混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1026", "t": "单选题", "s": "髋关节MRI冠状面T1WI上，股骨头圆韧带（股骨头韧带）的正常MRI表现是", "o": {"A": "股骨头中央横行的低信号带", "B": "股骨头后上方的高信号区", "C": "股骨颈外侧的高信号带", "D": "股骨头内的圆形液性信号", "E": "股骨颈内侧的线状高信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-LIMB-101", "kp": "股骨头圆韧带MRI表现", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】股骨头圆韧带自股骨头凹连至髋臼横韧带，是纤维性结构，MRI冠状面上于股骨头中央呈低信号带，是重要的解剖标志，故选A。【为什么错】B股骨头后上方为圆韧带附着点附近的高信号脂肪，不是圆韧带本身。C股骨颈外侧为转子区脂肪与肌肉，非圆韧带。D股骨头内圆形液性信号提示软骨下囊变，属异常表现。E股骨颈内侧线状结构多为支持带或血管断面，圆韧带低信号带位于股骨头而非股骨颈。", "tr": "圆韧带呈股骨头内横行低信号带，勿将其误认为股骨头隐匿性骨折线；两者鉴别点是圆韧带位置恒定、走行至股骨头凹。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1027", "t": "单选题", "s": "踝关节MRI矢状面图像上，距骨滑车上方主要相对并构成承重关节面的结构是", "o": {"A": "胫骨远端关节面", "B": "跟骨前突", "C": "腓骨远端关节面", "D": "舟骨", "E": "骰骨"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-LIMB-102", "kp": "踝关节面构成", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (3)主要断层影像解剖", "ex": "【为什么对】踝关节为屈戌关节，距骨滑车上方与胫骨远端下关节面构成主要的承重关节面（胫距关节），两侧尚有内踝、外踝夹持距骨，故选A。【为什么错】B跟骨前突与骰骨、舟骨形成跟骰关节、距跟舟关节，属跗骨间关节，不直接参与踝关节承重。C腓骨远端（外踝）与距骨外侧关节面构成踝关节的外侧部分，但其主要承重面在胫距之间。D舟骨与距骨头形成距舟关节，属跗横关节的一部分。E骰骨与跟骨前突相关节，与距骨滑车无关。", "tr": "踝关节主要承重面是胫距关节面（距骨滑车上为胫骨远端），腓骨外踝只参与外侧构成，“距骨上方对应腓骨”是常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1028", "t": "多选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，关于小脑幕及小脑幕切迹的断层影像解剖，正确的描述有", "o": {"A": "小脑幕分隔枕叶与小脑", "B": "横断面增强扫描小脑幕呈“V”形致密线影", "C": "小脑幕切迹内有中脑通过", "D": "小脑幕前缘附着于枕骨内板及横窦沟", "E": "幕切迹疝可压迫同侧动眼神经"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-111", "kp": "小脑幕及幕切迹", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】A小脑幕呈水平位略后倾的硬脑膜结构，将颅腔分隔为幕上（枕叶为主）与幕下（小脑为主）两部分，正确。B增强扫描或钙化时小脑幕在横断面上呈“V”（“八”）字形致密线影，正确。C小脑幕游离缘围成的幕切迹内有中脑通过，正确。E小脑幕切迹疝（钩回疝）时，中脑受压、同侧动眼神经受压可致同侧瞳孔散大，正确。【为什么错】D小脑幕后缘（外侧缘）附着于枕骨内板及横窦沟，而前缘为游离缘、围成幕切迹，附着于颞骨岩部上缘及鞍背（后床突），该项将前后缘附着关系颠倒，错误。", "tr": "小脑幕“后缘附着枕骨、前缘游离围成切迹”，附着关系是辨析重点；幕切迹疝压迫动眼神经与钩回（海马旁回钩）有明确对应关系。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1029", "t": "多选题", "s": "关于侧脑室各部的断层影像解剖，正确的描述有", "o": {"A": "侧脑室前角伸入额叶", "B": "侧脑室后角伸入枕叶", "C": "侧脑室下角伸入颞叶", "D": "侧脑室体部位于顶叶深部", "E": "侧脑室三角区仅位于顶叶内"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-112", "kp": "侧脑室分部", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】A侧脑室前角（额角）向前伸入额叶，其外侧为尾状核头，正确。B后角（枕角）向后伸入枕叶，两侧常不对称，正确。C下角（颞角）伸入颞叶内，底壁有海马，正确。D体部位于顶叶深部，其下为丘脑，正确。【为什么错】E侧脑室三角区是体部、后角、下角三者汇合处，位于顶、枕、颞三叶交界区，而非仅位于顶叶内，错误。", "tr": "侧脑室五个部分（前角、体部、后角、下角、三角区）与脑叶对应关系是断层识别的考点，三角区属三叶交界而非单一脑叶。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1030", "t": "多选题", "s": "关于颅脑各主要脑池的位置，正确的描述有", "o": {"A": "鞍上池位于蝶鞍上方", "B": "环池环绕中脑", "C": "桥小脑角池位于脑桥与小脑之间", "D": "四叠体池位于中脑背侧", "E": "枕大池位于颅前窝内"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-113", "kp": "脑池位置", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】A鞍上池位于蝶鞍（蝶骨鞍区）上方，内含视交叉、垂体柄等，正确。B环池环绕中脑，连接四叠体池与脚间池，正确。C桥小脑角池位于脑桥与小脑之间、内耳门前内侧，正确。D四叠体池位于中脑背侧（四叠体后方），内有松果体及大脑大静脉，正确。【为什么错】E枕大池（小脑延髓池）位于颅后窝小脑蚓部后方与枕骨之间，属颅后窝结构，说“位于颅前窝”错误。", "tr": "脑池归属：鞍上池（幕上）、枕大池（颅后窝）、环池（中脑周围），“枕大池在颅前窝”是常用陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1031", "t": "多选题", "s": "颅脑横断面CT由下向上逐层观察，各层面的识别要点正确的有", "o": {"A": "鞍上池层面可见视交叉与垂体柄", "B": "中脑层面可见大脑脚与黑质", "C": "第三脑室层面可见丘脑与内囊", "D": "半卵圆中心层面可见侧脑室体部", "E": "侧脑室顶消失后进入半卵圆中心层面"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-114", "kp": "颅脑断层层面识别", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】A鞍上池层面以“五角星”形脑脊液池为特征，内含视交叉、垂体柄及颈内动脉，正确。B中脑层面可见中脑、大脑脚、黑质与红核，四叠体池、环池环绕，正确。C第三脑室层面可见丘脑位于三脑室两侧、内囊后肢与豆状核，正确。E继续向上，侧脑室顶消失后即进入半卵圆中心层面，该层面仅见大脑白质区，正确。【为什么错】D半卵圆中心位于侧脑室顶部之上，该层面侧脑室已完全消失，说“可见侧脑室体部”错误，侧脑室体部见于其下方的层面。", "tr": "半卵圆中心是“侧脑室顶以上”的白质层面，层序判断“脑室→消失→半卵圆中心”是识别高层面的关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1032", "t": "多选题", "s": "结合上述情景，关于颈部甲状腺的断层影像解剖与信号表现，正确的描述有", "o": {"A": "甲状腺左右叶位于气管两侧", "B": "峡部位于第2～4气管软骨环前方", "C": "甲状腺T2WI信号低于颈部肌肉", "D": "甲状腺位于颈动脉鞘的内侧", "E": "CT增强扫描甲状腺呈明显均匀强化"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-105", "kp": "甲状腺断层解剖与信号", "ch": "一、人体断面影像解剖 → 2.颈部 → (2)MRI断层表现", "ex": "【为什么对】A甲状腺左右叶贴附于气管前外侧，正确。B峡部于第2～4气管软骨环前方连接左右叶，正确。D甲状腺位于颈动脉鞘（颈总动脉、颈内静脉）内侧，正确。E甲状腺血供丰富、含碘，CT增强扫描呈明显均匀强化，正确。【为什么错】C甲状腺因富含碘及腺体，T1WI、T2WI信号均高于颈部肌肉（与肌肉比较为稍高信号），说“低于肌肉”与MRI实际表现相反，错误。", "tr": "甲状腺MRI信号高于肌肉（含碘、富血供），与肌肉比较是记忆关键；信号方向记反即落入陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1033", "t": "多选题", "s": "关于喉部声门区CT断层影像解剖，正确的描述有", "o": {"A": "真声带层面可见前联合与后联合", "B": "真声带位于环状软骨上缘水平", "C": "喉室位于真声带与假声带之间", "D": "杓状软骨位于声门裂的前外侧", "E": "声门下区横断面呈四边形，侧壁为弹性圆锥"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-106", "kp": "喉部声门区断层解剖", "ch": "一、人体断面影像解剖 → 2.颈部 → (1)CT断层表现", "ex": "【为什么对】A真声带层面声门裂前后端分别为前联合（甲状软骨板前正中）与后联合（杓状软骨声带突之间），正确。B真声带约位于环状软骨板上缘水平，是声门区标志性层面，正确。C喉室是声带与室带（假声带）之间的陷凹，正确。E声门下区由弹性圆锥围成，横断面近似四边形，正确。【为什么错】D杓状软骨位于真声带后方、声门裂后外侧（其声带突连于声带后端），说“位于声门裂前外侧”位置错误。", "tr": "杓状软骨在声门裂后方（声带突在后），前联合是双侧声带前端交汇处，“前联合—声带前、杓状软骨—声带后”的对应关系是考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1034", "t": "多选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，关于肺叶间裂与肺叶划分的CT断层影像解剖，正确的描述有", "o": {"A": "右侧水平裂分隔右上叶与右中叶", "B": "横断面上斜裂呈粗大的低密度带", "C": "左肺只有斜裂，分为上下两叶", "D": "右肺由斜裂与水平裂分为上中下三叶", "E": "右中叶支气管开口于中间支气管前外侧壁"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-104", "kp": "叶间裂与肺叶划分", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】A右侧水平裂（横裂）位于右肺门水平，分隔右上叶与右中叶，正确。C左肺仅有一条斜裂，将其分为左上叶与左下叶，正确。D右肺由斜裂与水平裂分为上、中、下三叶，正确。E右中叶支气管自中间支气管前外侧壁发出，向前外走行，正确。【为什么错】B横断面上斜裂表现为细线状影（或乏血管带），正常厚度仅1～2 mm，“粗大的低密度带”描述错误。", "tr": "叶间裂在横断面CT上呈细线状影而非低密度带；水平裂仅见于右侧，左肺无水平裂。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1035", "t": "多选题", "s": "关于腹腔干及其主要分支的断层影像解剖，正确的描述有", "o": {"A": "腹腔干发自腹主动脉前壁", "B": "腹腔干分为肝总动脉、脾动脉与胃左动脉三大分支", "C": "脾动脉沿胰体尾部上缘向左走行", "D": "肝总动脉沿胰头上缘向右走行", "E": "腹腔干位于门静脉主干前方"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-112", "kp": "腹腔干分支断层解剖", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A腹腔干于第12胸椎至第1腰椎水平发自腹主动脉前壁，是腹主动脉的第一个前壁脏支，正确。B腹腔干分出肝总动脉、脾动脉和胃左动脉三大分支，正确。C脾动脉沿胰体尾部上缘走行达脾门，正确。D肝总动脉沿胰头上缘向右走行，分出胃十二指肠动脉与肝固有动脉，正确。【为什么错】E门静脉主干位于胰颈后方、下腔静脉前方，腹腔干位于门静脉主干的后下方，说“腹腔干位于门静脉前方”位置颠倒，错误。", "tr": "腹腔干（T12～L1、腹主动脉前壁）与肠系膜上动脉（L1、位于腹腔干下方）的起始水平及分支易混；腹腔干位于门静脉主干后下方。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1036", "t": "多选题", "s": "结合上述情景，关于上腹部门静脉系的断层影像解剖，正确的描述有", "o": {"A": "门静脉主干由肠系膜上静脉与脾静脉汇合而成", "B": "门静脉主干位于胰头后方", "C": "脾静脉走行于胰体尾部后方", "D": "门静脉在肝门处分为左、右支", "E": "门静脉主干位于下腔静脉后方"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-106", "kp": "门静脉系断层解剖", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A门静脉主干由肠系膜上静脉与脾静脉在胰颈后方汇合而成，正确。B汇合处即门静脉起始部位于胰头后上方，正确。C脾静脉自脾门发出后沿胰体尾后方走行，正确。D门静脉在肝门处分为左、右支，分别进入左右半肝，正确。【为什么错】E门静脉主干位于胰颈后方、下腔静脉的前方（二者之间隔以胰钩突/脂肪），说“位于下腔静脉后方”位置关系颠倒，错误。", "tr": "门静脉主干在下腔静脉前方、胰头后方，“门—腔”前后关系颠倒即落入陷阱；门静脉右支位于胆囊窝水平。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1037", "t": "多选题", "s": "关于男性盆腔断层影像解剖，正确的描述有", "o": {"A": "膀胱位于耻骨联合后方", "B": "精囊腺位于膀胱底后方", "C": "前列腺位于膀胱下方并包绕尿道起始部", "D": "直肠位于骶骨前方", "E": "直肠位于膀胱前方"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-104", "kp": "男性盆腔器官毗邻", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (3)主要断层影像解剖", "ex": "【为什么对】A膀胱位于耻骨联合后方，二者间为膀胱前间隙，正确。B精囊腺位于膀胱底后方、前列腺上方两侧，正确。C前列腺位于膀胱颈下方、耻骨联合后方，包绕尿道前列腺部，正确。D直肠位于骶骨前方、膀胱及精囊腺后方，正确。【为什么错】E直肠位于膀胱及精囊腺后方（直肠膀胱陷凹后方），说“位于膀胱前方”位置错误。", "tr": "男性盆腔由前向后：膀胱—精囊腺—直肠；直肠永远在最后方紧邻骶骨，“直肠在膀胱前方”是常用陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1038", "t": "多选题", "s": "关于脊柱各段断层影像解剖与结构特点，正确的描述有", "o": {"A": "颈椎横突孔内有椎动脉走行", "B": "胸椎横突与肋骨构成肋横关节", "C": "腰椎椎管横断面近似三角形", "D": "骶骨由5块骶椎融合而成", "E": "寰椎有椎体，位于前弓与后弓之间"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-102", "kp": "脊柱分段结构特点", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】A颈椎横突孔是椎动脉穿行的骨性管道，正确。B胸椎横突末端与肋骨结节相关节（肋横关节），正确。C腰椎椎体粗大，椎管横断面呈三角形，两侧椎弓根粗短，正确。D骶骨由5块骶椎融合而成，形成骶管及骶前后孔，正确。【为什么错】E寰椎（C1）无椎体、无棘突，由前弓、后弓及两侧块构成，两侧块上关节面承托枕髁；说“寰椎有椎体”错误。", "tr": "寰椎（无椎体、承托颅骨）与枢椎（有齿突）是颈椎结构特化的重点，“寰椎有椎体”是常见陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "脊柱区", "页": 21}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1039", "t": "多选题", "s": "结合上述情景，关于膝关节MRI断层影像解剖，正确的描述有", "o": {"A": "前交叉韧带起于胫骨髁间隆起前方，止于股骨外髁内侧面", "B": "后交叉韧带T2WI全程均呈均匀低信号", "C": "半月板T2WI呈均匀低信号", "D": "内侧半月板呈“C”形", "E": "外侧半月板较内侧半月板更近似“O”形"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-LIMB-103", "kp": "膝关节交叉韧带与半月板MRI", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】A前交叉韧带起自胫骨髁间隆起前外侧，止于股骨外髁内侧面，斜行走行，正确。C半月板含纤维软骨，T2WI呈均匀低信号，正确。D内侧半月板呈“C”形，较宽大，正确。E外侧半月板更近似“O”形，活动度较大，正确。【为什么错】B后交叉韧带虽以低信号为主，但因走行弯曲、魔角效应及部分容积效应，其近中段常可呈局灶性稍高信号，“全程均呈均匀低信号”表述过于绝对，错误。", "tr": "交叉韧带低信号中可出现魔角效应所致的假性高信号（常见于后交叉韧带中段），不可将其误诊为撕裂；“全程低信号”的绝对化表述是陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1040", "t": "多选题", "s": "颅脑MRI横断面T2WI上，下列表现中属于正常或生理性表现的有", "o": {"A": "成人松果体钙化", "B": "侧脑室枕角不对称", "C": "透明隔腔存在", "D": "脉络丛球钙化", "E": "脑室周围白质弥漫性高信号伴侧脑室扩大"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-115", "kp": "颅脑MRI正常变异与异常鉴别", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】A成人松果体钙化属正常生理性钙化，正确。B两侧侧脑室枕角（后角）大小常不对称，属正常变异，正确。C透明隔腔（第五脑室）在成人可终生存在，属正常变异，正确。D脉络丛球钙化位于侧脑室三角区，成人常见，属生理性钙化，正确。【为什么错】E脑室周围白质弥漫性高信号伴侧脑室扩大，提示脑白质病变（脱髓鞘、缺血）或脑积水/脑室旁白质异常，是异常表现而非正常表现，错误。", "tr": "松果体钙化、脉络丛钙化、枕角不对称、透明隔腔均为正常变异；而“白质高信号+脑室扩大”组合提示病变，勿将正常变异误读为病变。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1041", "t": "多选题", "s": "结合上述情景，关于颈部横断面断层影像解剖，正确的描述有", "o": {"A": "胸锁乳突肌位于颈动脉鞘的外前方", "B": "颈内静脉位于颈总动脉的前外侧", "C": "甲状腺位于胸锁乳突肌的内侧", "D": "食管位于气管前方", "E": "椎动脉位于颈椎横突孔内"}, "d": "中", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-107", "kp": "颈部横断面主要结构毗邻", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】A胸锁乳突肌自乳突至胸锁关节，位于颈动脉鞘外前方，正确。B颈动脉鞘内颈内静脉位于颈总动脉前外侧，正确。C甲状腺位于气管前方偏外，较胸锁乳突肌更靠内，正确。E椎动脉由C6以上进入横突孔向上穿行，正确。【为什么错】D食管位于气管后方、椎体前方（气管食管沟内走行喉返神经），说“位于气管前方”位置错误。", "tr": "颈段食管位于气管正后方，“气管前方为甲状腺峡部”而非食管；气管食管沟是喉返神经走行区。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "颈部", "页": 8}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1042", "t": "多选题", "s": "上腹部CT增强扫描，关于下腔静脉、门静脉与腹主动脉的位置关系，正确的描述有", "o": {"A": "下腔静脉位于腹主动脉右侧", "B": "门静脉主干位于下腔静脉前方", "C": "胰头位于十二指肠降部与下腔静脉之间", "D": "腹主动脉位于脊柱前方偏左", "E": "脾静脉于胰头前方汇入门静脉"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-107", "kp": "上腹部大血管位置关系", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】A下腔静脉位于腹主动脉右侧，二者均在脊柱前方，正确。B门静脉主干位于下腔静脉前方、胰头后方，正确。C胰头被十二指肠降部与下腔静脉夹持，位于二者之间，是胰头癌“十二指肠降部受压”的解剖基础，正确。D腹主动脉位于脊柱前方偏左，下腔静脉位于其右前方，正确。【为什么错】E脾静脉在胰体尾后方自左向右走行，与肠系膜上静脉在胰颈后方汇合成门静脉主干，说“于胰头前方汇入”位置错误，汇合点在胰颈后方而非胰头前方。", "tr": "门静脉汇合点在胰颈后方（脾静脉+肠系膜上静脉），胰头被十二指肠降部与下腔静脉夹持，这两个“前后”关系是腹部断层高频考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U01-1043a", "t": "单选题", "s": "结合上述情景，鞍区冠状面MRI上，位于鞍上池内、呈“束带”状连接双侧视神经与视束的结构是", "o": {"A": "垂体柄", "B": "视交叉", "C": "乳头体", "D": "大脑脚", "E": "海马"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-116", "kp": "鞍上池内视交叉识别", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】视交叉位于鞍上池中央偏前，冠状面呈“束带”（蝴蝶形）软组织影，前方为双侧视神经、后方为双侧视束，是与鞍区病变关系最密切的结构，故选B。【为什么错】A垂体柄位于视交叉后方偏下，呈垂直走行的细线状结构，连于垂体上缘。C乳头体位于脚间池，位置更低更靠后。D大脑脚位于中脑腹侧，与鞍上池不在同一平面。E海马位于颞叶内侧、侧脑室下角底壁。", "tr": "冠状面上视交叉（前、束带状）与垂体柄（后、垂直细线）前后关系易混，鞍区手术与病变评估的关键就在二者的识别。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1043b", "t": "单选题", "s": "为清晰显示垂体上缘与视交叉的空间关系，应首选下列哪种成像方案", "o": {"A": "横断面T2WI", "B": "矢状面T1WI", "C": "冠状面薄层扫描（层厚≤3 mm）", "D": "斜轴位扫描", "E": "CT灌注成像"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-117", "kp": "鞍区MRI成像方位选择", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】鞍区病变（垂体瘤）向上生长是否压迫视交叉，须在冠状面观察最佳，因冠状面能同时显示蝶鞍、垂体、鞍上池与视交叉的上下关系，且应薄层扫描（≤3 mm）以减少部分容积效应，故选C。【为什么错】A横断面利于观察鞍旁颈内动脉及鞍上池前后径，但上下关系显示不佳。B矢状面利于显示垂体柄前后走行与蝶鞍前后径，对视交叉受压的上下评估不如冠状面直观。D斜轴位不解决上下毗邻关系的显示问题。E CT灌注成像用于血流灌注评估，与解剖关系显示无关。", "tr": "鞍区评估“横看血管、矢看柄、冠状看交叉”：视交叉受压必须在冠状面评估，这是垂体瘤术前评估的规范。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1043c", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，若鞍内占位明显向上生长突入鞍上池，最先受压并产生视力障碍的结构是", "o": {"A": "视交叉", "B": "垂体柄", "C": "大脑前动脉", "D": "中脑导水管", "E": "海马"}, "d": "难", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-118", "kp": "鞍上占位压迫视交叉", "ch": "一、人体断面影像解剖 → 1.头部 → (3)主要断层影像解剖", "ex": "【为什么对】鞍上池紧邻蝶鞍上方，垂体瘤向上生长首先占据鞍上池，视交叉恰位于鞍上池内、垂体上方，向上生长的肿瘤最先压迫视交叉，引起双颞侧偏盲等视力障碍，故选A。【为什么错】B垂体柄受压可引起内分泌改变（尿崩等），一般不直接产生视力障碍。C大脑前动脉位于视交叉上方较远处，受压较晚且表现为肢体症状而非视力障碍。D中脑导水管位于鞍上池后上方更远处，受压将引起梗阻性脑积水。E海马位于颞叶内侧，远离鞍区。", "tr": "鞍内肿瘤“向上先压视交叉”产生双颞侧偏盲，是鞍区断层解剖的经典应用；视力障碍与垂体柄受压所致内分泌症状需区分。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1044a", "t": "单选题", "s": "结合上述情景，右肺门层面增强CT上，位于中间支气管前方、自纵隔跨向肺门的血管结构是", "o": {"A": "右肺动脉（右下肺动脉干）", "B": "食管", "C": "奇静脉", "D": "上腔静脉", "E": "升主动脉"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-108", "kp": "右肺门肺动脉与支气管关系", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】A正确：右肺动脉干（下干）在右肺门处跨过中间支气管前方进入肺门，构成“肺动脉在前、支气管居中”的经典肺门关系；增强扫描其管腔强化明显，与含气低密度的支气管易于鉴别。【为什么错】B食管位于中间支气管正后方，是另一侧的毗邻结构。C奇静脉弓位于纵隔后方，多在主动脉弓层面自后向前汇入上腔静脉。D上腔静脉位于纵隔前部、升主动脉右侧，距中间支气管较远。E升主动脉位于纵隔前部、上腔静脉内侧，不在肺门平面紧邻中间支气管。", "tr": "右肺门“肺动脉在前、支气管居中、食管贴后”的空间关系；左肺门则以左肺动脉位于左主支气管上方为其特点，两侧肺门关系勿互换。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1044b", "t": "单选题", "s": "胸部CT增强扫描中，鉴别纵隔血管断面与肿大淋巴结最可靠的方法是", "o": {"A": "增大窗宽并降低窗位", "B": "连续层面追踪血管走行并观察其强化程度", "C": "加宽扫描层厚", "D": "口服阳性对比剂", "E": "增大扫描螺距"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-106", "kp": "纵隔血管与淋巴结鉴别", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】增强CT上，纵隔血管（肺动脉、肺静脉、上腔静脉等）内腔显著强化，且具有连续走行、逐层延续、管径渐变的特征；肿大淋巴结强化程度低于血管且无连续走行规律。连续层面追踪血管走行并结合其强化程度，是鉴别二者的最可靠方法，故选B。【为什么错】A窗宽窗位调整仅改善显示，不能改变组织本质鉴别。C加宽层厚会加重部分容积效应，使鉴别更困难。D口服对比剂只用于显示消化道，对纵隔血管与淋巴结鉴别无帮助。E增大螺距提高扫描速度，但与结构鉴别无关。", "tr": "血管“走行连续+强化明显”，淋巴结“团块样+轻度强化”；单凭某一层面密度判断易误诊，必须连续追踪层面。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1045a", "t": "单选题", "s": "【病例】患者女性，50岁，上腹隐痛1个月，超声提示肝门部占位性病变。行上腹部CT增强检查，以明确肝门区结构关系，评估门静脉、肝动脉与胆管是否受压及有无移位。 肝门层面CT增强扫描，肝蒂内三管结构由前向后的排列顺序是", "o": {"A": "门静脉、肝动脉、胆管", "B": "胆管、肝动脉、门静脉", "C": "肝动脉、胆管、门静脉", "D": "门静脉、胆管、肝动脉", "E": "胆管、门静脉、肝动脉"}, "d": "易", "c": "理解", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-108", "kp": "肝门三管排列顺序", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】肝门（肝蒂）横断面上，三管结构由前向后依次为胆管（肝总管/胆总管上段，最前方）、肝动脉（中间）、门静脉（最后方、管径最粗），故选B。【为什么错】A门静脉在最前方错误，门静脉是三者中最粗且位于最后方者。C肝动脉居中最前方应为胆管。D门静脉与胆管位置颠倒。E胆管与门静脉位置颠倒，门静脉应在最后方。", "tr": "肝蒂三管口诀“胆、动、门”（前中后），门静脉最粗最后方；肝门部病变压迫顺序判断依赖此排列。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1045b", "t": "单选题", "s": "若该患者门静脉主干明显增宽且伴脾大，肝门层面最可能出现的断层表现是", "o": {"A": "门静脉主干纤细", "B": "门静脉主干增宽伴脾静脉增宽、脾脏增大", "C": "肝动脉管径消失", "D": "胆总管普遍扩张", "E": "肝静脉明显增宽"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-109", "kp": "门静脉高压断层表现", "ch": "一、人体断面影像解剖 → 4.腹部 → (3)主要断层影像解剖", "ex": "【为什么对】门静脉主干增宽伴脾静脉增宽、脾脏增大，是门静脉高压的典型断层表现；门静脉高压时门静脉压力增高、管径扩张，脾静脉回流入门静脉、随压力增高而增宽，脾脏淤血肿大，故选B。【为什么错】A门静脉纤细提示门静脉发育不良或栓塞后萎缩，与门静脉高压方向相反。C肝动脉在门静脉高压时常代偿性增粗而非消失。D胆总管扩张提示胆道梗阻，与门静脉高压的血管性改变无关。E肝静脉为回流下腔静脉的肝内静脉，门静脉高压时一般不变宽。", "tr": "门静脉高压三联征“门静脉主干增宽+脾静脉增宽+脾大”，与门静脉血栓（管腔内充盈缺损）鉴别是增强扫描的重点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1046a", "t": "单选题", "s": "【病例】患者男性，48岁，腰痛伴右下肢放射麻木2个月。腰椎MRI显示L4/5水平椎间盘突出，需结合椎管与神经根的断层解剖确定受压部位与程度，为治疗方案提供依据。 腰椎横断面MRI上，椎管内位于最前方的结构是", "o": {"A": "硬膜囊", "B": "马尾神经", "C": "硬膜外脂肪", "D": "后纵韧带与椎体后缘", "E": "黄韧带"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-103", "kp": "椎管横断面层次", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】腰椎横断面椎管由前向后依次为：椎体后缘与后纵韧带（最前方）、硬膜外脂肪、硬膜囊、硬膜外脂肪、黄韧带与椎弓（最后方）。后纵韧带紧贴椎体后缘，是椎管内最前部结构，故选D。【为什么错】A硬膜囊位于椎管中央，包绕脑脊液与马尾神经，其后有黄韧带。B马尾神经位于硬膜囊内脑脊液中。C硬膜外脂肪分布于硬膜囊与骨性椎管之间（前间隙、后间隙）。E黄韧带位于椎管后外侧、椎弓板前面，是最靠后的结构之一。", "tr": "椎管前后层次“后纵韧带—脂肪—硬膜囊—脂肪—黄韧带”，黄韧带在后、后纵韧带在前，两者位置勿颠倒。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1046b", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，L4/5椎间盘向后外侧突出时，最常受压并产生症状的神经根是", "o": {"A": "L4神经根", "B": "L5神经根", "C": "S1神经根", "D": "双侧L4神经根", "E": "马尾神经"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-104", "kp": "椎间盘突出与神经根对应", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】腰椎神经根自同节段椎体上缘水平出椎管后向下斜行，在椎间盘层面神经根已离开该节段。L4/5椎间盘向后外侧突出时，突出物位于L5神经根出椎管的通道（侧隐窝上口）处，压迫的是L5神经根，故选B。【为什么错】A L4神经根在L4/5椎间盘水平已自L4/5椎间孔上方出椎管，位于突出物上方，一般不直接受压。C S1神经根受压多见于L5/S1椎间盘突出。D腰椎间盘突出多为单侧。E马尾神经受压见于巨大中央型突出，与本例侧后方突出不符。", "tr": "椎间盘突出“上一节段压下一根”：L4/5突出压L5神经根，L5/S1突出压S1神经根，根与节段的对应关系是反复命题点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1047", "t": "案例分析题", "s": "患者男性，65岁，突发剧烈头痛伴喷射性呕吐2小时急诊入院。临床高度怀疑小脑幕旁出血或幕上幕下同时受累的病变，行颅脑CT平扫。技师需确保扫描范围完整覆盖幕上与幕下结构，避免遗漏小脑幕下方（后颅窝）的病变，同时保证小脑幕两侧对称显示。此时最合适的扫描范围设置是", "o": {"A": "以听眦线为基线，自颅顶连续扫描至枕骨大孔下缘，覆盖全颅", "B": "仅扫描幕上结构（自颅顶至鞍上池层面）", "C": "以蝶鞍为中心的小范围局部扫描", "D": "仅以枕骨大孔为中心的下后颅窝薄层扫描", "E": "不设定扫描范围，直接按默认条件扫描"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-119", "kp": "颅脑CT全颅覆盖与小脑幕观察", "ch": "一、人体断面影像解剖 → 1.头部 → (1)CT断层表现", "ex": "【为什么对】颅脑CT平扫应自颅顶（半卵圆中心上方）连续扫描至枕骨大孔下缘，完整覆盖幕上与幕下结构，才能同时观察小脑幕上方（枕叶、基底节）与下方（小脑、脑干）的病变，故选A。【为什么错】B仅扫描幕上结构会遗漏后颅窝病变，不符合“排除幕下病变”的临床要求。C以蝶鞍为中心的局部扫描范围过小，无法覆盖小脑幕全貌。D仅扫描下后颅窝会遗漏幕上病变，同样不完整。E不设定范围违反扫描规范，无法保证覆盖完整性。", "tr": "颅脑CT“全颅覆盖”（颅顶至枕骨大孔下缘）是排除幕下病变的前提，小脑幕呈“V”形线影在增强或钙化时清晰可见，扫描范围不足是常见遗漏。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "头部", "页": 1}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1048", "t": "单选题", "s": "结合上述情景，患者女性，38岁，颈部增粗伴吞咽不适1个月，超声提示甲状腺右叶下极结节，边界尚清。术前拟行颈部CT增强检查，以明确结节与气管、颈动脉鞘及食管的关系。技师需要利用颈部可靠的骨性/软骨性解剖标志在断层图像上对结节所在层面进行精确定位。此时最宜选用的定位标志是", "o": {"A": "环状软骨（作为气管起始的标志）", "B": "甲状软骨上缘", "C": "下颌角水平", "D": "锁骨上窝皮肤皱褶", "E": "胸锁乳突肌前缘"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-NECK-108", "kp": "甲状腺结节断层定位", "ch": "一、人体断面影像解剖 → 2.颈部 → (3)主要断层影像解剖", "ex": "【为什么对】环状软骨是唯一完整的软骨环，是气管起始的恒定标志。以环状软骨为基准向下计数气管软骨环，即可精确定位甲状腺下极及结节所在层面（甲状腺峡部位于第2～4气管软骨环前方），故选A。【为什么错】B甲状软骨上缘是颈总动脉分叉和声门区标志，位置高于甲状腺下极。C下颌角平C2～C3，与甲状腺位置相距较远。D锁骨上窝皮肤皱褶因人而异、受体位影响，非恒定骨性标志。E胸锁乳突肌是肌性标志，仅提示外侧边界，不能定位结节层面。", "tr": "环状软骨（气管起始）是颈部分层的“锚点”，向下计数气管环即达甲状腺；把甲状软骨当作定位基准会整体高估层面。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1049", "t": "案例分析题", "s": "患者男性，58岁，痰中带血1周。胸部CT平扫示左肺门区不规则软组织影，与左肺动脉关系密切，需进一步明确病灶与肺门血管、支气管的空间关系。拟行胸部CT增强扫描并行多平面重建。为在重建图像上最直观地显示左肺门病灶与左肺动脉的上下位置关系，并保留支气管管腔的连续性，应优先采用下列哪种重建方式", "o": {"A": "轴位薄层重建", "B": "矢状面MPR", "C": "冠状面MPR", "D": "沿左主支气管长轴的曲面重建（CPR）", "E": "最大密度投影（MIP）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-CHEST-107", "kp": "左肺门病灶重建方式选择", "ch": "一、人体断面影像解剖 → 3.胸部 → (1)CT断层表现", "ex": "【为什么对】左主支气管及左肺动脉在冠状面上均呈弯曲走行，单纯平面MPR难以将其全长显示于同一平面。沿左主支气管长轴作曲面重建（CPR），可将弯曲走行的支气管及邻近血管展开在同一幅图像上，最直观地显示病灶与左肺动脉的上下毗邻及管腔关系，故选D。【为什么错】A轴位薄层重建虽为诊断基础，但只能显示单层断面，不能直观显示上下空间关系。B矢状面MPR对左肺门前后关系显示尚可，但上下走行关系显示不如CPR。C冠状面MPR可显示上下关系，但因支气管弯曲，全程在同一冠状面内显示困难。E MIP为投影类重建，会重叠遮挡肺门血管与病灶的细节关系。", "tr": "肺门血管与支气管的空间关系首选沿支气管长轴的曲面重建（CPR），普通MPR因结构弯曲而显示不全，MIP有重叠遮挡。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "胸部", "页": 10}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1050", "t": "案例分析题", "s": "患者男性，52岁，体检发现肝右叶占位性病变，拟行肿瘤切除手术。术前增强CT需在横断面上精确判断病灶所属的Couinaud肝段，以决定切除范围并评估切除后剩余肝体积。技师在阅片时，判断病灶位于右前段（Ⅴ、Ⅷ段）还是右后段（Ⅵ、Ⅶ段）所依据的最关键断层标志是", "o": {"A": "肝中静脉走行", "B": "肝右静脉走行", "C": "门静脉左支矢状部", "D": "胆囊窝位置", "E": "下腔静脉断面"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-ABDO-110", "kp": "肝段定位的静脉标志", "ch": "一、人体断面影像解剖 → 4.腹部 → (1)CT断层表现", "ex": "【为什么对】肝右静脉走行于右叶间裂，是右前段（Ⅴ、Ⅷ段）与右后段（Ⅵ、Ⅶ段）的分界标志。病灶位于肝右静脉平面以前（前方）属右前段，位于其以后（后方）属右后段，故选B。【为什么错】A肝中静脉为左内叶（Ⅳ段）与右前叶（Ⅴ、Ⅷ段）的分界标志，用于区分左右叶而非右前、右后段。C门静脉左支矢状部是左外叶与左内叶的分界标志，位于左半肝。D胆囊窝与下腔静脉连线代表肝中裂（左右半肝分界），用于区分左叶与右叶。E下腔静脉为各肝静脉回流的汇合处，本身不用于段间分界。", "tr": "三条肝静脉各司其职：肝右静脉分右前/右后段，肝中静脉分左内/右前叶，肝左静脉分左外/左内叶；“用肝中静脉分右前右后”是常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "腹部", "页": 15}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1051", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，患者男性，66岁，体检发现血清PSA升高，临床拟行前列腺MRI检查以评估有无前列腺癌及有无包膜侵犯。技师需要选择能清楚区分前列腺外周带与中央带、显示前列腺包膜的成像序列，同时兼顾扫描时间与图像信噪比。此时轴位前列腺成像最恰当的序列选择是", "o": {"A": "轴位T1WI", "B": "轴位高分辨T2WI（小视野、薄层、高矩阵）", "C": "轴位DWI", "D": "矢状位T1WI", "E": "轴位T2*WI"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-105", "kp": "前列腺MRI序列选择", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】前列腺外周带在T2WI上呈高信号、中央带呈低信号，T2WI是显示前列腺分区解剖与包膜的最佳序列；轴位小视野、薄层、高矩阵的T2WI能清晰显示外周带内低信号结节及包膜连续性，故选B。【为什么错】A T1WI上前列腺各带信号差异不明显，主要用于显示出血（T1WI高信号）及淋巴结。C DWI用于功能成像（表观弥散系数），解剖分区显示不如T2WI。D矢状位T1WI对包膜及分区显示不佳，主要用于评估尖部与精囊腺关系。E T2*WI对磁化效应敏感，用于出血与钙化显示，分区解剖显示差。", "tr": "前列腺分区解剖“T2WI看”（外周带高、中央带低）是成像基础；T1WI、DWI是补充序列，不能替代T2WI的分区显示功能。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "盆腔及会阴部", "页": 20}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1052", "t": "案例分析题", "s": "患者男性，35岁，进行性双下肢麻木无力2个月，临床疑诊颈椎管狭窄。行颈椎MRI检查，技师需要在轴位T2WI上测量椎管有效前后径，以定量评估椎管狭窄程度并与正常参考值比较。此时轴位上椎管前后径的标准测量方法是", "o": {"A": "椎体后缘中点至棘突基部前缘的连线", "B": "椎体前缘至椎弓板后缘的连线", "C": "椎间盘后缘至黄韧带的连线", "D": "椎间孔上下径", "E": "侧隐窝左右径"}, "d": "难", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-SPIN-105", "kp": "颈椎管前后径测量", "ch": "一、人体断面影像解剖 → 6.脊柱区 → (3)主要断层影像解剖", "ex": "【为什么对】颈椎管有效前后径（矢状径）的标准测量为椎体后缘中点到棘突基部前缘（椎弓板内面）的连线，反映骨性椎管的有效容纳空间；成人颈椎管前后径小于12 mm即提示狭窄，故选A。【为什么错】B从椎体前缘测量包含了椎体本身，属椎体矢状径而非椎管有效前后径。C椎间盘后缘至黄韧带反映的是椎管前后间隙在椎间盘层面的距离，非骨性椎管径线。D椎间孔上下径是神经根通道的径线，用于评估椎间孔狭窄。E侧隐窝左右径用于评估侧隐窝狭窄，与椎管前后径测量不同。", "tr": "椎管前后径“椎体后缘中点至棘突基部前缘”，测量止点在后部骨结构（椎弓板/棘突基部），起止点记错即得错误径线。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1053", "t": "单选题", "s": "结合上述情景，患者男性，28岁，运动中扭伤右膝后疼痛伴交锁感1周，临床疑诊内侧半月板撕裂，行膝关节MRI检查。技师需设置斜矢状面序列，使半月板的前后角及体部能连续、完整地显示于同一层面内，同时兼顾前后交叉韧带。此时斜矢状面的定位基线应选择", "o": {"A": "平行于股骨干长轴", "B": "平行于内侧副韧带走行", "C": "平行于前交叉韧带长轴（经股骨内外髁后缘连线）", "D": "垂直于胫骨平台关节面", "E": "平行于髌韧带"}, "d": "易", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-LIMB-104", "kp": "膝关节斜矢状面定位", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (2)MRI断层表现", "ex": "【为什么对】膝关节MRI的斜矢状面扫描基线取平行于前交叉韧带长轴的方向（或经股骨内、外髁后缘的连线），使半月板体部、前后角及前后交叉韧带能连续显示于同一矢状层面，是半月板评估的标准方位，故选C。【为什么错】A平行于股骨干长轴的是常规矢状面，半月板内侧角与外缘不在同一层面连续显示。B内侧副韧带为纵行韧带，与其平行不能兼顾半月板形态。D垂直于胫骨平台为关节面垂直方向，用于胫骨平台骨折评估。E髌韧带位于前方，与其平行不适合半月板显示。", "tr": "半月板及交叉韧带观察需“斜矢状面”（基线平行ACL），常规矢状面（平行股骨长轴）会导致半月板前后角分离显示不全。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1054", "t": "案例分析题", "s": "患者女性，70岁，记忆力减退伴步态不稳半年，临床疑诊正常压力性脑积水或脑白质病变，行颅脑MRI检查。技师需评价脑室系统的大小、形态以及脑室周围白质有无信号改变，并注意与脑脊液信号干扰相鉴别。此时评价脑室周围白质病变的最佳序列组合是", "o": {"A": "轴位T1WI与矢状面T2WI", "B": "轴位T2WI与轴位FLAIR", "C": "轴位DWI", "D": "仅轴位T1WI", "E": "仅三维时间飞跃法MRA"}, "d": "中", "c": "分析", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-HEAD-120", "kp": "脑室周围白质病变显示序列", "ch": "一、人体断面影像解剖 → 1.头部 → (2)MRI断层表现", "ex": "【为什么对】轴位T2WI显示脑室形态与脑白质信号总体情况，轴位FLAIR通过反转脉冲抑制脑脊液信号，使紧邻脑室壁的白质高信号（PVWMH）不被脑脊液高信号掩盖而清晰显示，二者组合是评估脑室周围白质病变的常规方案，故选B。【为什么错】A T1WI对白质高信号显示不敏感，脑室评估也不以矢状面为主。C DWI用于急性梗死与弥散受限病变，不用于白质高信号常规评估。D仅T1WI无法显示FLAIR所见的脑室旁白质高信号。E MRA用于血管成像，与白质病变评估无关。", "tr": "FLAIR序列“抑制脑脊液、凸显脑室旁白质高信号”是评估PVWMH的关键，漏用FLAIR会把脑室旁病变误判为脑脊液伪影。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-1055", "t": "单选题", "s": "【病例】患者因影像学检查需要进行断层解剖定位分析。 结合上述情景，患者女性，45岁，产后出现会阴部坠胀不适，临床拟行盆腔MRI评估盆底肌及会阴部结构。技师需在图像上识别肛提肌、闭孔内肌以及肛管两侧脂肪间隙的层次关系，为评估盆底功能障碍提供解剖依据。盆腔内脂肪与骨骼肌的对比是显示盆底肌结构的关键，同时需兼顾扫描时间与呼吸运动的影响。此时显示盆底肌层次结构最适宜的成像方案是", "o": {"A": "轴位T1WI加增强扫描", "B": "轴位高分辨T2WI联合矢状面T2WI薄层扫描", "C": "仅行DWI功能成像", "D": "横断面CT平扫", "E": "三维时间飞跃法MRA"}, "d": "中", "c": "应用", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-PELV-107", "kp": "盆底肌MRI成像方案", "ch": "一、人体断面影像解剖 → 5.盆腔及会阴部 → (2)MRI断层表现", "ex": "【为什么对】B正确：肛提肌、闭孔内肌等盆底肌为骨骼肌，T2WI上呈均匀中等低信号，与周围脂肪高信号形成良好对比；轴位高分辨T2WI显示盆底肌横断面形态最佳，联合矢状面薄层T2WI可整体评估盆底肌连续性及其与肛管、直肠、尿道的位置关系。【为什么错】A T1WI对肌肉与脂肪的对比不及T2WI，增强扫描非盆底结构评估的常规要求。C DWI反映水分子弥散受限情况，不用于盆底肌形态学显示。D CT软组织分辨率明显低于MRI，对盆底筋膜与肌肉层次显示差，且存在电离辐射。E MRA用于血管成像，与盆底肌显示无关。", "tr": "盆底肌评估首选T2WI（肌肉低信号、脂肪高信号对比佳），CT对软组织层次分辨力不足，仅用于骨盆骨质评估。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U01-9101", "t": "单选题", "s": "在四肢骨骼的 MRI 断层解剖中，膝关节外侧半月板与内侧半月板形态的主要区别是", "o": {"A": "外侧半月板较小、近似圆形（O 形），内侧半月板较大、呈 C 形", "B": "内侧半月板较小、近似圆形，外侧半月板较大、呈 C 形", "C": "两者形态基本一致，均为 C 形", "D": "外侧半月板前角明显大于后角", "E": "内侧半月板后角明显小于前角"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "KP-BU-1-9101-正高", "kp": "膝关节半月板断层解剖", "ch": "一、人体断面影像解剖 → 7.四肢骨骼 → (补充)四肢骨骼断层解剖", "ex": "【为什么对】A 正确：外侧半月板因受腓骨小头及腘肌腱的束缚，活动度大、形态较小且近似圆形（O 形）；内侧半月板与关节囊及内侧副韧带结合紧密、活动度小、较大呈 C 形。【为什么错】B 将内外侧形态颠倒；C、D、E 与实际解剖不符。", "tr": "易将内、外侧半月板的形态与大小记反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U01-9201", "t": "单选题", "s": "四肢长骨 X 线摄影时，基本要求是", "o": {"A": "至少包括邻近一侧关节", "B": "只照病变局部", "C": "必须双侧对比", "D": "仅正位即可", "E": "无需标注左右"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-9201", "kp": "四肢摄影原则", "ch": "一、人体断面影像解剖 → 7.四肢骨骼", "ex": "【为什么对】四肢长骨摄影至少应包括邻近一侧关节，以明确骨端与位置关系。\n【为什么错】仅照局部易漏诊骨骺病变。", "tr": "长骨摄影包括一端关节。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U01-9202", "t": "单选题", "s": "关于手正斜位摄影，常规投照的手指是", "o": {"A": "第 2～5 指", "B": "仅拇指", "C": "仅小指", "D": "全部六指", "E": "仅食指"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "一", "un": "人体断面影像解剖", "kpid": "UNIT-01-EXTR-9202", "kp": "手斜位", "ch": "一、人体断面影像解剖 → 7.四肢骨骼", "ex": "【为什么对】手斜位主要显示第 2～5 掌指及指间关节，拇指单独摄正侧位。\n【为什么错】拇指不做常规斜位。", "tr": "手斜位显示2-5指。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像解剖学", "节": "四肢骨骼", "页": 25}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U02-0101", "t": "单选题", "s": "X线由德国物理学家伦琴（W. C. Röntgen）发现的年份是", "o": {"A": "1885年", "B": "1895年", "C": "1896年", "D": "1901年", "E": "1905年"}, "d": "中", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-001", "kp": "X线的发现", "ch": "二、医学物理基础 → 1.X线的产生 → (1)X线的发现", "ex": "【为什么对】1895年11月8日，德国物理学家伦琴在研究阴极射线管时发现了一种能穿透物质并使荧光屏发光的未知射线，命名为X射线，故选B。【为什么错】A 1885年尚无此发现。C 1896年是X线发现后被迅速应用于临床并在世界范围传播的年份，而非发现年份。D 1901年是伦琴因发现X线获得首届诺贝尔物理学奖的年份，属于获奖时间而非发现时间。E 1905年与X线发现史无关。", "tr": "1895年（发现）与1901年（首届诺贝尔物理学奖）是一对必须区分的年份，命题常以“获奖年”替换“发现年”作干扰。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0102", "t": "多选题", "s": "产生X线所必须具备的基本条件包括", "o": {"A": "能够发射电子的电子源", "B": "使电子高速运动的强电场（高电压）", "C": "阻碍高速电子运动的靶物质", "D": "X线管内保持高度真空", "E": "阳极靶面必须处于高速旋转状态"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-002", "kp": "X线产生的基本条件", "ch": "二、医学物理基础 → 1.X线的产生 → (2)X线的产生", "ex": "【为什么对】A正确：灯丝加热产生热电子发射，提供电子源。B正确：阳极与阴极间施加高电压形成强电场，使电子获得足以产生韧致辐射的动能。C正确：高速电子必须撞击高原子序数、高熔点的靶物质（如钨）而骤然减速，才能把动能转化为X线。D正确：管内高真空可避免电子与气体分子碰撞损失能量、防止灯丝氧化并保证管电流稳定，是X线管正常工作的必要条件。【为什么错】E错误：旋转阳极的作用是把电子轰击的热量分散到整个环形焦点轨迹上，从而提高瞬时负荷能力，属于提高管功率的工程措施；固定阳极X线管（如牙科机、部分移动机）同样能产生X线，故靶面旋转不是产生X线的必要条件。", "tr": "把“提高性能的条件”当成“产生X线的必要条件”是典型误区：旋转阳极、附加滤过、栅控技术都属前者；真正的必要条件只有电子源、加速电场、靶物质与高真空环境。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0103", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，管电压为100 kV时，连续X线谱的最短波长约为", "o": {"A": "0.0124 nm", "B": "0.124 nm", "C": "1.24 nm", "D": "12.4 nm", "E": "0.00124 nm"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-003", "kp": "连续X线最短波长计算", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】连续X线谱的最短波长对应于电子把全部动能一次性转化为一个光子的极限情况，由杜安－亨特定律给出：λmin(nm)＝1.24／U(kV)。代入U＝100 kV，得λmin＝1.24／100＝0.0124 nm，故选A。【为什么错】B相当于按10 kV计算，数值大10倍。C相当于按1 kV计算，大100倍。D数量级完全偏离，已属紫外线波段。E相当于按1000 kV计算，小10倍。", "tr": "最短波长只由管电压峰值决定，与管电流、曝光时间、靶物质、滤过均无关；增加滤过会提高平均能量却不改变λmin，这是“线质硬化不移动谱线左端”的物理依据。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0104", "t": "单选题", "s": "钨靶X线管产生K系特征X线所需的最低管电压约为", "o": {"A": "30 kV", "B": "50 kV", "C": "70 kV", "D": "100 kV", "E": "120 kV"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-004", "kp": "特征X线产生条件", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】特征X线的产生要求入射电子的动能大于靶原子相应壳层电子的结合能。钨的K层电子结合能约为69.5 keV，故管电压须达到约70 kV以上才能击出K层电子并产生K系特征辐射，选C。【为什么错】A 30 kV时电子动能仅30 keV，远低于钨K层结合能，只能产生L系及以下的低能特征辐射（能量很低，几乎全被管壁与固有滤过吸收）与连续辐射。B 50 kV同样低于阈值。D 100 kV与E 120 kV虽都能产生K系特征X线，但题目问的是“最低管电压”，二者高于阈值，不是答案。", "tr": "特征X线的能量（波长）由靶物质决定，与管电压无关；管电压只决定“能不能产生”以及产生的多少。钼靶（K层约20 keV）在26～32 kV即可产生K系特征X线，这正是乳腺摄影选用钼靶低管电压的原因。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0105", "t": "多选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，有关影响X线产生的因素，下列描述正确的有", "o": {"A": "管电流决定单位时间内撞击靶面的电子数目，X线量与之成正比", "B": "管电压升高既增加X线量又提高X线质", "C": "靶物质原子序数越高，韧致辐射（连续X线）的产生效率越高", "D": "高压波形纹波越小（如高频、恒压），X线产生效率越高、平均能量越高", "E": "特征X线的波长随管电压升高而变短"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-005", "kp": "影响X线产生的因素", "ch": "二、医学物理基础 → 1.X线的产生 → (4)影响X线产生的因素", "ex": "【为什么对】A正确：管电流由灯丝加热电流控制，决定热电子发射数量，X线光子总数与管电流成正比。B正确：管电压升高使电子动能增大，既提高单个光子的最高能量与平均能量（质），又使韧致辐射效率上升从而增加光子数（量）。C正确：韧致辐射效率η＝k·Z·U，与靶物质原子序数Z成正比，故采用高原子序数的钨（Z＝74）作靶。D正确：纹波小意味着在整个曝光期间管电压都接近峰值，有效能量高、低能成分少，输出效率与平均能量都提高。【为什么错】E错误：特征X线的波长（能量）仅取决于靶物质的壳层能级差，是靶元素的“指纹”，与管电压无关；管电压只影响特征X线能否产生及其强度占比。", "tr": "连续X线的最短波长随kV升高而变短，特征X线的波长却固定不变——命题人常把二者的规律互换。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0106", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，有关X线管的阳极效应（足跟效应）及其临床利用，下列描述正确的是", "o": {"A": "近阳极端的X线强度明显高于近阴极端", "B": "近阴极端X线强度高于近阳极端，摄影时宜将人体较厚部位置于阴极侧", "C": "靶面倾角越大，阳极效应越明显", "D": "焦点至探测器距离越大，阳极效应越明显", "E": "阳极效应是X线在空气中发生散射所致"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-006", "kp": "阳极效应与空间分布", "ch": "二、医学物理基础 → 1.X线的产生 → (5)X线强度的空间分布", "ex": "【为什么对】X线在靶内一定深度产生后向外射出，射向阳极侧的射线需穿过更厚的靶体自身而被吸收，因而近阳极端强度低、近阴极端强度高，形成沿阳极—阴极轴的强度梯度。临床上应利用这一梯度，把人体较厚、密度较高的部位（如胸椎摄影的下胸段、足部摄影的跟部、乳腺摄影的胸壁侧）置于阴极侧，以获得较均匀的影像密度，故选B。【为什么错】A方向恰好相反。C靶面倾角越小，射线在靶内穿行路径越长，阳极效应越显著；倾角增大则效应减弱。D距离增大时，同样大小的照射野所对应的射线出射角范围变小，落在强度梯度较平缓的中心区域，阳极效应反而减弱。E阳极效应源于靶物质对自身产生X线的吸收（自吸收），与空气散射无关。", "tr": "“厚的一端放阴极”是唯一需要记住的临床结论；乳腺摄影因胸壁侧组织最厚，规定阴极侧朝向胸壁，这是阳极效应最典型的应用实例。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0107", "t": "单选题", "s": "结合上述情景，患者男性，45岁，身高172 cm，体重100 kg（BMI约34），因腰痛需摄腰椎正侧位。技师在完成正位后，以75 kV、100 mAs、小焦点摄侧位，连续两次曝光效果均偏薄，第三次尝试时设备出现X线管过热保护提示并暂停曝光。已知X线管的产生效率η＝k·Z·U（k≈1.1×10⁻⁹，U以V计），电子动能的绝大部分转化为热能。从X线产生原理出发，下列处理最合理的是", "o": {"A": "改用大焦点并适当提高管电压、相应降低mAs，在维持影像密度的同时减少阳极热负荷", "B": "继续使用小焦点并提高管电流、延长曝光时间以增加输出", "C": "降低管电压至60 kV，同时把mAs提高到200 mAs", "D": "取消附加滤过以提高X线输出效率", "E": "缩短焦点至探测器距离至80 cm，其余条件不变"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-007", "kp": "X线产生效率与阳极热负荷", "ch": "二、医学物理基础 → 1.X线的产生 → (2)X线的产生", "ex": "【为什么对】按η＝k·Z·U，75 kV钨靶的X线产生效率约为1.1×10⁻⁹×74×7.5×10⁴≈0.6%，即99%以上的电子动能转化为阳极热量，这正是过热保护的根源。提高管电压既提高产生效率（η与U成正比）又提高穿透力，可显著减少所需mAs；而阳极热量与kV×mAs×时间因数相关，mAs大幅下降后总热量下降。改用大焦点则把热量分散到更大的实际焦点面积上，提高瞬时负荷能力。因此A是兼顾成像与热负荷的正确策略。【为什么错】B小焦点热容量小，提高管电流、延长曝光只会加剧过热，并增加运动模糊。C降低管电压使效率下降、穿透力不足，为维持密度必须成倍增加mAs，热负荷不降反升，且患者皮肤剂量明显增加。D附加滤过并不产生于阳极之后的热量，取消滤过不会减少阳极负荷，反而使大量低能光子进入人体、显著增加患者剂量，违反防护最优化原则。E缩短距离虽可减少所需曝光量，但会增大皮肤入射剂量并加重几何放大与失真，且腰椎侧位标准距离不宜随意更改。", "tr": "X线管“99%产热、约1%出线”是理解所有热负荷问题的基础；解决过热应优先“升kV降mAs＋换大焦点”，而不是“加大mA拖长时间”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0108", "t": "单选题", "s": "某X线光子的波长为0.02 nm，其光子能量约为", "o": {"A": "12.4 keV", "B": "24.8 keV", "C": "62 keV", "D": "124 keV", "E": "620 keV"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-001", "kp": "光子能量与波长关系", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (1)X线的本质与特性", "ex": "【为什么对】X线本质是电磁波，具有波粒二象性，光子能量E＝hν＝hc／λ。工程上常用简化式E(keV)＝1.24／λ(nm)。代入λ＝0.02 nm，得E＝1.24／0.02＝62 keV，故选C。【为什么错】A相当于λ＝0.1 nm的能量。B相当于λ＝0.05 nm。D相当于λ＝0.01 nm，波长取小了一半。E数量级错误，已属高能γ射线范畴，超出诊断X线范围。", "tr": "E(keV)＝1.24／λ(nm)与λmin(nm)＝1.24／U(kV)形式相同但含义不同：前者是任意单个光子的能量—波长换算，后者是给定管电压下整个连续谱的短波极限，二者不可混用。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0109", "t": "单选题", "s": "诊断X线能量范围内，光子与物质作用后能量不变、仅改变传播方向的相互作用是", "o": {"A": "光电效应", "B": "康普顿效应", "C": "相干散射", "D": "电子对效应", "E": "光核反应"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-002", "kp": "相干散射特点", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】相干散射（又称经典散射、汤姆逊散射或瑞利散射）中，低能光子使束缚电子整体振荡并再发射同频率的电磁波，光子只改变方向而不损失能量，也不产生电离，故选C。【为什么错】A光电效应中光子被完全吸收，能量全部转移给光电子与特征辐射，光子消失。B康普顿效应中光子把部分能量传给反冲电子，散射光子能量降低、波长变长。D电子对效应要求光子能量大于1.02 MeV，光子转化为正负电子对，在诊断能量段不发生。E光核反应阈能通常在8 MeV以上，属放射治疗高能范畴。", "tr": "相干散射虽“无电离、不损失能量”，但它改变了光子方向，仍会形成散射线并降低影像对比度；在诊断能量段其占比不大（一般小于5%），常被误认为“完全无害”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0110", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，光电效应的发生概率与物质原子序数Z、光子能量E之间的关系是", "o": {"A": "与Z³成正比、与E³成反比", "B": "与Z成正比、与E成反比", "C": "与Z²成正比、与E²成反比", "D": "与Z³成反比、与E³成正比", "E": "与Z、E均无关，只取决于物质密度"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-003", "kp": "光电效应的Z与E依赖性", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】光电效应的质量衰减系数近似满足τ／ρ∝Z³／E³（部分教材写作Z³～Z⁴／E³），即随原子序数迅速上升、随光子能量迅速下降，故选A。这解释了两个临床现象：一是骨（有效Z约13.8）与软组织（有效Z约7.4）在低kV下对比度极高；二是碘（Z＝53）、钡（Z＝56）之所以成为优良对比剂。【为什么错】B、C低估了Z与E的幂次，无法解释对比剂的显著增强效应。D方向完全颠倒，若成立则高能光子在高Z物质中反而更易被光电吸收，与事实相悖。E光电效应对Z与E的依赖极强，密度只影响单位体积内的原子数，不改变每个原子的作用截面。", "tr": "记住“光电吃Z、康普顿吃电子密度”：光电效应∝Z³／E³，康普顿效应与Z基本无关而与每克电子数近似成正比，这一对比是判断“何时提高kV、何时选用对比剂”的物理基础。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0111", "t": "多选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，有关康普顿效应的性质与临床影响，下列描述正确的有", "o": {"A": "其发生概率与物质每克电子数成正比，与原子序数基本无关", "B": "在诊断X线能量范围内，它是软组织中占主导地位的相互作用形式，且随kV升高而愈发突出", "C": "散射光子的能量小于入射光子，散射角越大能量损失越多", "D": "康普顿散射线是影像灰雾的主要来源，会降低图像对比度并构成机房内散射线防护的主要对象", "E": "康普顿效应的发生概率随光子能量升高而迅速增大"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-004", "kp": "康普顿效应特点与临床意义", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】A正确：康普顿效应作用于外层近似自由的电子，其截面正比于单位质量中的电子数；除氢外多数元素每克电子数相近，故对Z不敏感。B正确：软组织中光子能量超过约26 keV后康普顿即开始占优，诊断段（有效能量约30～70 keV）以康普顿为主，且随kV升高光电占比进一步下降。C正确：由康普顿位移公式Δλ＝(h／m₀c)(1－cosθ)可知，散射角θ越大，波长增加越多、散射光子能量越低；180°反散射时能量损失最大。D正确：康普顿散射线方向随机、能量与原射线接近，是探测器上灰雾与机房内散射线的主要来源，需用滤线栅、限束与屏蔽加以控制。【为什么错】E错误：在诊断能量范围内康普顿效应的发生概率随光子能量升高而缓慢下降，只是因为光电效应下降得更快（∝1／E³），才显得康普顿“相对占比升高”。", "tr": "“康普顿相对占比升高”不等于“康普顿绝对概率升高”——这是绝对量与相对量混淆的经典陷阱；此外散射线量还与照射野面积、被照体厚度密切相关，限束是最经济的散射控制手段。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0112", "t": "单选题", "s": "结合上述情景，患者女性，48岁，因乳腺筛查行双侧乳腺X线摄影。设备为钼靶／钼滤过数字乳腺机，技师按标准流程选择自动曝光控制，系统给出的管电压为28 kV。该患者随后询问：为什么胸片用110 kV而乳腺只用28 kV。技师需要从X线与物质相互作用的角度作出解释。乳腺摄影采用26～32 kV低管电压的核心物理学依据是", "o": {"A": "低能量段光电效应占主导，其∝Z³／E³的特性可最大化腺体、纤维组织、钙化与病变间的微小衰减差异，从而获得高对比度", "B": "低管电压可显著降低乳腺腺体的吸收剂量", "C": "低管电压可增加康普顿散射比例，从而提高影像对比度", "D": "低管电压可提高X线管的产生效率，缩短曝光时间", "E": "低管电压可减小几何模糊，提高空间分辨率"}, "d": "中", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-005", "kp": "低管电压与光电效应的临床应用", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】乳腺内各种软组织的有效原子序数与密度差异极小，只有让光电效应成为主导相互作用，才能把这些微小差异放大为可见的密度差。由τ∝Z³／E³可知，降低光子能量能使光电效应贡献急剧上升；钼靶在17.5 keV与19.6 keV处的K系特征X线配合钼滤过，可产生集中于该能段的准单能谱，正好兼顾对比度与穿透力，故A正确。【为什么错】B恰恰相反，低管电压使低能光子在浅表被大量吸收，平均腺体剂量升高，这正是乳腺摄影必须严格控制曝光量并采用自动曝光控制的原因。C康普顿散射产生灰雾、降低而非提高对比度，乳腺摄影反而要用滤线栅和压迫来减少散射。D X线产生效率η∝U，管电压越低效率越低，曝光时间反而延长。E几何模糊由焦点尺寸、物—片距与焦—片距决定，与管电压无关。", "tr": "“高对比”与“低剂量”在乳腺摄影中是一对矛盾：低kV提高对比但增加腺体剂量，因此必须依靠压迫（减薄组织）、自动曝光控制与合适的靶／滤过组合（Mo／Mo、Mo／Rh、W／Rh）来平衡，而不能靠单纯降kV。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0113", "t": "多选题", "s": "关于X线与物质各类相互作用的能量条件及其诊断学意义，下列描述正确的有", "o": {"A": "电子对效应的发生阈能为1.02 MeV，故诊断X线能量范围内不会发生", "B": "光电效应无统一的能量下限，但要求入射光子能量不低于相应壳层电子的结合能", "C": "相干散射在诊断能量段所占比例很小，一般不超过5%", "D": "光核反应的阈能一般在8 MeV以上，属放射治疗能量范畴", "E": "康普顿效应主要发生在原子的内层紧束缚电子上"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-006", "kp": "各类相互作用的能量阈值", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】A正确：电子对效应是光子在原子核库仑场中转化为一对正负电子，需至少提供两个电子的静止能量2×0.511 MeV＝1.02 MeV，诊断段最高不过150 keV，故不可能发生。B正确：光电效应要求E光子≥E结合能；当光子能量恰好略高于某壳层结合能时截面骤增，形成“吸收边”（如碘K边33.2 keV）。C正确：相干散射截面随能量升高迅速下降，在诊断段贡献很小。D正确：光核反应需击出核内核子，阈能一般在8 MeV以上，与诊断放射学无关。【为什么错】E错误：康普顿效应发生在外层的松束缚（近似自由）电子上，其前提正是光子能量远大于该电子结合能；若作用于紧束缚内层电子且光子被完全吸收，那是光电效应而非康普顿效应。", "tr": "四种作用按能量从低到高的出场顺序为“相干散射→光电效应→康普顿效应→电子对效应→光核反应”；诊断放射学只涉及前三种，超出此范围的选项属超纲干扰项，应能一眼识别。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0114", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，患者女性，32岁，体重52 kg，因突发胸痛、D-二聚体升高需行肺动脉CTA除外肺栓塞。考虑到患者年轻、需减少辐射与对比剂负荷，技师拟将管电压由常规120 kV降至70 kV，并把碘对比剂用量由60 mL减至40 mL，同时提高管电流并采用迭代重建以控制噪声。该低管电压方案能够在减少碘量的同时维持甚至提高血管强化程度，其核心物理学依据是", "o": {"A": "70 kV时X线束的有效能量更接近碘的K吸收边（33.2 keV），碘的光电吸收显著增强、质量衰减系数增大，单位碘浓度产生的CT值明显升高", "B": "低管电压使康普顿效应占比增加，血管内碘的散射增强", "C": "低管电压使X线管输出量增加，血管信号随之增强", "D": "低管电压使对比剂在血管内的浓度自然升高", "E": "低管电压主要通过减少图像噪声来提高血管的对比噪声比"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-007", "kp": "低管电压CTA与碘K吸收边", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】碘的K层结合能为33.2 keV，光子能量刚超过该值时光电吸收截面骤然跃升。120 kV束的有效能量约55～65 keV，远离K边；降至70 kV后有效能量降至约40～45 keV，更靠近33.2 keV，碘的质量衰减系数显著增大，同样的碘浓度可产生更高的CT值（文献报道70 kV下碘的强化效率较120 kV提高约60%～80%），从而允许减少对比剂用量，故A正确。【为什么错】B康普顿效应与原子序数基本无关，不可能造成碘的选择性强化，且散射只会降低图像质量。C管电压降低时X线输出量按近似U²关系下降而非增加，正因如此才需要成倍提高管电流补偿。D对比剂在血管内的浓度由注射方案与循环决定，与管电压无关。E低管电压在同等mAs下噪声反而增加，本方案需靠提高mAs与迭代重建来抑制噪声；提高对比噪声比的主导因素是分子端的碘强化增益，而非噪声下降。", "tr": "低kV“增强变亮但噪声也变大”，能否获益取决于碘增益是否超过噪声增幅，因此更适用于体型偏瘦者；肥胖患者盲目降kV会因穿透不足导致噪声与伪影急剧恶化。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0115", "t": "单选题", "s": "结合上述情景，物理学上X线强度（I）的严格定义是", "o": {"A": "单位时间内通过与射线方向垂直的单位面积上的光子数与各自能量乘积的总和", "B": "单位时间内产生的X线光子总个数", "C": "X线束中能量最高的那个光子所具有的能量", "D": "单位质量物质所吸收的X线能量", "E": "X线束穿透标准铝板后的剩余百分比"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-001", "kp": "X线强度的定义", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (2)X线强度", "ex": "【为什么对】X线强度是能量流密度概念：单位时间内通过垂直于射线传播方向的单位面积上的光子数目与其光子能量乘积的总和，因此它同时包含“量”（光子数）与“质”（单个光子能量）两个要素，故选A。【为什么错】B只描述了光子数量，即X线的“量”，未包含能量因素。C描述的是连续谱的最高光子能量，只与管电压有关，属“质”的一个极端指标。D是吸收剂量的定义（单位质量物质吸收的辐射能量，单位Gy），描述的是受照物质而非射线束本身。E描述的是穿透率／半价层测量的操作过程，属“质”的实用表征方法。", "tr": "X线强度＝光子数×光子能量，所以单靠mAs（改变光子数）或单靠kV（改变光子能量与数目）都能改变强度；把强度等同于“光子数”是最常见的概念性错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0116", "t": "单选题", "s": "结合上述情景，其他条件不变时，将管电压由70 kV升高至100 kV，X线输出强度约变为原来的", "o": {"A": "1.4倍", "B": "2倍", "C": "2.8倍", "D": "4倍", "E": "5.6倍"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-002", "kp": "X线强度与管电压的平方关系", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (1)X线的波长与管电压", "ex": "【为什么对】X线强度的经典表达式为I＝K·i·Z·U²，即在管电流、靶物质不变时，输出强度与管电压的平方成正比。(100／70)²＝(1.43)²≈2.04，约为原来的2倍，故选B。【为什么错】A 1.4倍是管电压比值本身（一次方关系），低估了平方效应。C 2.8倍相当于把比值1.43再乘以2，无物理依据。D 4倍相当于管电压翻倍时的平方结果（2²＝4），本题管电压并未翻倍。E 5.6倍数值过大，接近三次方关系(1.43³≈2.9)的两倍，无依据。", "tr": "教材公式给出的是I∝U²，而摄影实践中因滤过与被照体衰减的共同作用，穿过人体到达探测器的剂量随kV的变化常接近三次方甚至更陡，故临床“15%法则”（kV升15%相当于mAs加倍）与理论平方关系并不矛盾，注意区分“管输出”与“探测器接收”两个不同环节。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0117", "t": "多选题", "s": "有关X线管附加滤过板的作用，下列描述正确的有", "o": {"A": "选择性吸收低能光子，使X线束的平均能量升高", "B": "使半价层增大，即提高X线的质", "C": "显著降低受检者的皮肤入射剂量", "D": "使X线束的总输出强度下降", "E": "使被检部位的影像对比度明显提高"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-003", "kp": "滤过对X线质与量的影响", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (3)X线质", "ex": "【为什么对】A正确：低能光子的衰减系数远大于高能光子，铝滤过板优先滤除软射线，使剩余束平均能量升高，即“线质硬化”。B正确：平均能量升高必然使半价层（HVL）增大，这是X线质提高的量化表现。C正确：被滤除的低能光子几乎全部沉积在患者浅表组织而对成像无贡献，滤过是降低皮肤剂量最有效的措施之一，故国家标准对总滤过（一般≥2.5 mm Al当量）有强制要求。D正确：滤过在滤除软射线的同时也会衰减部分有用射线，总输出强度必然下降，需相应增加mAs补偿。【为什么错】E错误：影像对比度主要来源于组织间衰减差异，而低能光子的光电效应贡献最大。滤过提高平均能量后，光电效应占比下降，对比度实际上略有降低。滤过换取的是剂量安全，而不是对比度。", "tr": "“滤过提高线质”与“滤过提高对比度”是两回事——前者正确、后者错误；滤过是以牺牲少量对比度换取患者剂量的大幅下降，属典型的防护最优化权衡。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0118", "t": "多选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，关于X线的质与量及其影响因素，下列描述正确的有", "o": {"A": "X线的量主要由管电流量（mAs）决定，二者近似成正比", "B": "X线的质主要由管电压与滤过决定，与mAs基本无关", "C": "管电压升高时，X线的质与量同时增加", "D": "半价层是描述X线质的实用物理量，半价层越大表示穿透力越强", "E": "标称管电压峰值相同的两台设备，输出X线的质必定相同"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-004", "kp": "X线质与量的决定因素", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (4)X线量", "ex": "【为什么对】A正确：mAs决定撞击靶面的电子总数，进而决定光子总数，与X线量成正比，这是曝光量互易律的基础。B正确：单个光子能量分布由加速电压与滤过决定，改变mAs只改变光子数目而不改变能谱形状。C正确：管电压升高既提高光子平均能量（质）又提高韧致辐射效率与光子数（量），这正是kV“一石二鸟”的特点。D正确：半价层定义为使X线强度衰减到原来一半所需的标准物质（诊断段常用铝）厚度，HVL越大说明束越硬、穿透力越强。【为什么错】E错误：即便标称kVp相同，两台设备的总滤过量、高压发生器波形（单相、三相、高频）、纹波系数都可能不同，导致有效能量与半价层不同。因此设备验收与质量控制必须实测半价层，而不能仅凭标称kVp判断线质。", "tr": "mAs只管“量”、kV同时管“质和量”、滤过只管“质”（并附带降低量）——三者的分工是本细目的核心；把“kVp相同即线质相同”当作常识是设备质控中的典型误判。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0119", "t": "单选题", "s": "临床摄影中通常用来表示X线量的物理量是", "o": {"A": "管电压kV", "B": "管电流量mAs", "C": "半价层HVL", "D": "波长λ", "E": "照射野面积"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-005", "kp": "X线量的表征", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (4)X线量", "ex": "【为什么对】X线的量指X线束中光子的数目，与管电流和曝光时间的乘积（mAs）成正比，因此临床上直接用mAs表示X线量，故选B。【为什么错】A管电压表征的主要是X线的质，虽然它也影响量，但不是量的直接表征量。C半价层是X线质的标准量化指标。D波长描述单个光子的能量属性，属质的范畴。E照射野面积决定受照体积与散射线量，不表示X线束中的光子数目。", "tr": "“量看mAs、质看kV与HVL”是最简记忆；注意曝光量互易律在数字探测器中基本成立，但在极短或极长曝光时间下可能出现互易律失效，需结合设备特性判断。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0120", "t": "案例分析题", "s": "患者男性，60岁，胸椎压缩性骨折需摄胸椎侧位。技师原用75 kV、40 mAs可获得密度合适的图像，但该患者疼痛明显、屏气困难，曝光时间过长导致呼吸运动模糊。技师决定采用提高管电压、缩短曝光时间的策略，并按摄影条件换算的“15%法则”进行调整，即管电压升高约15%时X线到达探测器的量约增加一倍。若把管电压提高到约86 kV，为维持原有影像密度，mAs应调整为", "o": {"A": "10 mAs", "B": "20 mAs", "C": "30 mAs", "D": "40 mAs", "E": "60 mAs"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-006", "kp": "kV-mAs换算的15%法则", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (1)X线的波长与管电压", "ex": "【为什么对】75 kV提高15%约为86 kV，按15%法则此时到达探测器的曝光量约为原来的2倍，为保持影像密度不变必须把mAs减半，即40 mAs／2＝20 mAs，故选B。这一调整同时把曝光时间缩短一半，有效抑制呼吸运动模糊，并降低患者受照剂量。【为什么错】A 10 mAs相当于减为1／4，对应管电压需再提高约15%（约99 kV），本题只升到86 kV，会造成影像密度不足。C 30 mAs仅减少25%，影像会过黑。D 40 mAs不变则密度明显过高。E 60 mAs反而增加曝光量，与目的相悖。", "tr": "15%法则中“kV升15%≈mAs加倍”，若反向应用（降低kV 15%需把mAs加倍）同样成立；但要注意提高kV会降低影像对比度，对需要高对比的部位（如乳腺、四肢小骨）不宜滥用此法则。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0121", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，焦点至探测器距离由100 cm增加到150 cm，若其他条件不变，为使探测器接收的剂量保持不变，mAs应", "o": {"A": "减为原来的1／2.25", "B": "增为原来的2.25倍", "C": "增为原来的1.5倍", "D": "减为原来的2／3", "E": "保持不变"}, "d": "易", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-001", "kp": "距离平方反比定律", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (1)距离的衰减", "ex": "【为什么对】点状辐射源在真空或空气中，射线强度与距离的平方成反比：I₁／I₂＝(d₂／d₁)²。距离由100 cm增至150 cm，强度降为原来的(100／150)²＝1／2.25，因此mAs需增加到原来的(150／100)²＝2.25倍才能维持相同的接收剂量，故选B。【为什么错】A方向相反，会导致影像明显欠曝。C 1.5倍只按距离一次方补偿，补偿不足。D减为2／3属反向操作，欠曝更严重。E不作调整则影像密度不足。", "tr": "距离平方反比反映的是几何扩散造成的“距离衰减”，与物质吸收无关；它同时是距离防护的物理基础——工作人员与辐射源距离加倍，受照剂量降为1／4。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0122", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，某单能窄束X线在某物质中的线性衰减系数μ＝0.35 cm⁻¹，该物质对此射线的半价层约为", "o": {"A": "0.35 cm", "B": "0.69 cm", "C": "1.0 cm", "D": "2.0 cm", "E": "3.5 cm"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-002", "kp": "半价层与线性衰减系数", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (4)衰减系数与影响衰减的因素", "ex": "【为什么对】单能窄束遵循指数衰减规律I＝I₀e^(－μd)。令I／I₀＝1／2，得μ·HVL＝ln2＝0.693，故HVL＝0.693／μ＝0.693／0.35≈1.98 cm，约2.0 cm，选D。【为什么错】A把μ的数值直接当作厚度，属公式误用。B误把ln2＝0.693直接当成半价层，忽略了除以μ。C凑整错误，1.0 cm对应μ≈0.693 cm⁻¹。E 3.5 cm相当于μ≈0.2 cm⁻¹，数值不符。", "tr": "HVL＝0.693／μ与十分之一值层TVL＝2.303／μ是一对常用公式；此外该指数关系严格成立的前提是“单能”和“窄束”，多能宽束条件下必须引入线质硬化与散射累积因子修正。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0123", "t": "多选题", "s": "有关连续能谱X线（多能X线束）在物质中的衰减特点，下列描述正确的有", "o": {"A": "低能光子优先被吸收，透过后线束的平均能量升高，即线质硬化", "B": "随穿透深度增加，第二个半价层大于第一个半价层", "C": "严格的指数衰减规律只适用于单能窄束，多能束并不完全遵循", "D": "线质硬化是CT杯状伪影与条状伪影产生的重要原因", "E": "连续X线经物质衰减后其最短波长随之增大"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-003", "kp": "连续X线的衰减特点", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】A正确：低能光子衰减系数大，先被吸收，剩余束平均能量升高。B正确：束变硬后继续衰减一半所需厚度增大，因此第二半价层大于第一半价层，二者之比称为均质系数，是衡量线束单能性的指标。C正确：I＝I₀e^(－μd)要求μ为常数，而多能束在穿透过程中有效μ不断减小，故偏离单一指数规律。D正确：射束硬化使投影数据与线性假设不符，重建后表现为均匀体模中心CT值偏低的“杯状伪影”，以及两高密度结构之间的暗带条状伪影。【为什么错】E错误：最短波长λmin＝1.24／U仅由管电压决定，滤过或人体吸收只能削减低能端（长波侧）的光子数，不会改变短波极限位置。", "tr": "“衰减使束变硬”不等于“衰减改变最短波长”——能谱是被“削低端”而不是“整体右移”；均质系数（第一HVL／第二HVL）越接近1，说明射线越接近单能。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0124", "t": "单选题", "s": "有关质量衰减系数（μ／ρ），下列描述正确的是", "o": {"A": "同一元素的质量衰减系数随其物理状态（气态、液态、固态）改变而显著改变", "B": "质量衰减系数的单位是cm⁻¹", "C": "对同一元素而言，质量衰减系数与物质密度无关，仅取决于原子序数与光子能量", "D": "质量衰减系数随光子能量升高而单调下降，不存在突变", "E": "质量衰减系数等于线性衰减系数与物质密度的乘积"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-004", "kp": "质量衰减系数的性质", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (4)衰减系数与影响衰减的因素", "ex": "【为什么对】质量衰减系数定义为μ／ρ，其物理意义是单位质量厚度（g/cm²）物质对射线的衰减本领。由于已经除去了密度因素，它只反映原子层面的相互作用截面，因而对同一元素只取决于原子序数与光子能量，与密度和物理状态无关，故选C。这也是水与水蒸气的质量衰减系数相同、而线性衰减系数相差千倍的原因。【为什么错】A物理状态改变的是密度而非原子结构，质量衰减系数保持不变。B cm⁻¹是线性衰减系数μ的单位，质量衰减系数的单位为cm²/g。D在各壳层的吸收边（如碘K边33.2 keV、钡K边37.4 keV）处，质量衰减系数会突然跃升，并非单调下降，这正是K边成像与双能量CT物质分离的物理基础。E关系式为μ／ρ，是商而不是积。", "tr": "“质量衰减系数与密度无关”是本考点的核心结论；同时必须记住吸收边处的不连续跃升，否则会与D这类“看似合理”的干扰项混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0125", "t": "多选题", "s": "结合上述情景，影响X线在物质中衰减程度的主要因素包括", "o": {"A": "X线光子的能量（受管电压与滤过共同决定）", "B": "被照物质的原子序数", "C": "被照物质的密度", "D": "被照物质的厚度", "E": "曝光时间（mAs）"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-005", "kp": "影响衰减的因素", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (4)衰减系数与影响衰减的因素", "ex": "【为什么对】A正确：光子能量越高，光电与康普顿截面均下降，穿透力增强、衰减减少。B正确：原子序数通过光电效应（∝Z³）强烈影响衰减，是骨与软组织形成对比的根本原因。C正确：密度决定单位体积内的原子数，线性衰减系数μ＝(μ／ρ)·ρ，密度越大衰减越强，这是肺（低密度）与实变肺组织形成对比的原因。D正确：按指数规律I＝I₀e^(－μd)，厚度d直接进入指数项。【为什么错】E错误：mAs只改变入射光子的总数，不改变每个光子被衰减的概率，因而不影响衰减的百分比。增加mAs会使透过的光子数按比例增加，但透射率I／I₀不变。", "tr": "“衰减程度”指的是透射比例而不是透射的绝对光子数；mAs属于“输入量”，衰减系数属于“系统属性”，把二者混为一谈会导致对曝光条件与图像对比关系的错误理解。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0126", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，人体主要组织成分对X线衰减能力由强到弱的正确排序是", "o": {"A": "骨＞肌肉（水）＞脂肪＞空气", "B": "骨＞脂肪＞肌肉（水）＞空气", "C": "肌肉（水）＞骨＞脂肪＞空气", "D": "脂肪＞肌肉（水）＞骨＞空气", "E": "空气＞脂肪＞肌肉（水）＞骨"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-006", "kp": "人体组织对X线的衰减", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (5)人体对X线的衰减", "ex": "【为什么对】人体四大基本密度由高到低为骨（含钙，有效原子序数约13.8、密度约1.85 g/cm³）＞软组织／肌肉（近似水，有效Z约7.4，密度约1.0）＞脂肪（有效Z约6.3，密度约0.9）＞空气（密度约0.0013），衰减能力依此递减，故选A。这也是X线平片“四种自然对比”的物理基础，以及CT值标定（水0 HU、空气－1000 HU、致密骨可达＋1000 HU以上）的依据。【为什么错】B把脂肪排在肌肉之前，脂肪的有效原子序数与密度均低于肌肉。C骨的衰减明显强于肌肉，顺序颠倒。D、E顺序完全倒置，与临床影像表现相悖。", "tr": "脂肪的衰减略低于水，故CT上脂肪为负值（约－100～－50 HU）；但在低kV下由于光电效应加强，骨与软组织的对比会进一步拉大，说明“组织对比”并非固定，而与线质相关。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0127", "t": "单选题", "s": "结合上述情景，患者男性，70岁，因眩晕行颅脑CT平扫。图像显示后颅窝小脑半球区出现两侧颞骨岩部之间的带状低密度以及沿颅骨内板向内的“杯状”密度偏低区，脑实质CT值较正常偏低约8 HU，影响小脑病变判读。设备为64排CT，扫描条件为120 kV、自动管电流调制、层厚5 mm。从X线在物质中的衰减机制分析，该现象的最主要成因及相应技术对策是", "o": {"A": "射束硬化——颅骨优先吸收低能光子使束变硬，导致投影数据偏离线性假设；对策为提高管电压、加用成形（bow-tie）滤过、启用射束硬化校正算法或采用双能量单能谱重建", "B": "部分容积效应——对策为增加层厚以提高信噪比", "C": "患者运动伪影——对策为缩短扫描时间并加固定带", "D": "金属植入物伪影——对策为启用金属伪影抑制算法", "E": "图像噪声过大——对策为单纯提高管电流并加大重建核锐利度"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-007", "kp": "射束硬化伪影的成因与对策", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】CT重建基于“衰减呈单一指数规律”的线性假设。实际使用的是连续能谱束，穿过高密度厚重的颅骨（尤其颞骨岩部与枕骨）后低能成分被大量吸收，射线变硬、有效衰减系数下降，使中心区域投影值系统性偏低，重建后形成中心CT值偏低的“杯状伪影”，两高密度结构之间则出现带状暗影（Hounsfield暗带），这正是本例后颅窝表现的典型成因。对策包括提高管电压使束本身更硬、使用成形滤过预硬化、应用厂家的射束硬化（骨）校正算法，以及采用双能量／能谱CT重建虚拟单能量图像，故A正确。【为什么错】B部分容积效应表现为界面处密度平均化，增加层厚只会加重而非改善，方向错误。C运动伪影表现为条纹状或重影，与“杯状密度分布”不符，且不解释颞骨间的固定带状暗影。D患者无金属植入物，且金属伪影多为放射状粗大条纹伴明显高低密度交替。E噪声表现为颗粒状随机波动，不会造成系统性CT值偏低；加大锐利度反而放大噪声。", "tr": "后颅窝的带状暗影长期被称为“Hounsfield伪影”，与运动、金属伪影形态不同，鉴别要点是它固定出现于两高密度骨结构连线上；此外要理解“提高kV可减轻射束硬化”与“提高kV增加剂量”的权衡关系。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0128", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，下列原子核中，自旋量子数为零、不具有磁共振特性的是", "o": {"A": "¹H", "B": "¹³C", "C": "¹⁹F", "D": "¹²C", "E": "³¹P"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-001", "kp": "磁性与非磁性原子核判据", "ch": "二、医学物理基础 → 5.磁学基础知识 → (2)磁性和非磁性原子核", "ex": "【为什么对】原子核是否具有自旋磁矩，取决于其质子数与中子数的奇偶性：质子数为奇数或中子数为奇数（即质量数为奇数，或质量数为偶数但质子数与中子数皆为奇数）时，自旋量子数不为零，属磁性核。¹²C含6个质子、6个中子，二者皆为偶数，自旋量子数I＝0，无磁矩、不产生磁共振现象，故选D。【为什么错】A ¹H为单质子，I＝1／2，是人体内丰度最高、旋磁比最大的磁性核，为临床MRI的成像核素。B ¹³C含6质子7中子，中子数为奇数，I＝1／2，是磁性核，可用于超极化¹³C代谢成像。C ¹⁹F含9质子10中子，质子数为奇数，I＝1／2，为磁性核，可用于氟成像与波谱。E ³¹P含15质子16中子，质子数为奇数，I＝1／2，是磁共振波谱研究能量代谢的重要核素。", "tr": "判据是“质子数或中子数为奇数”，而不是“质量数为奇数”——²H（氘，1质子1中子，质量数为偶数）质子与中子皆为奇数，仍是磁性核（I＝1）；¹⁶O、¹²C、³²S这类质子与中子皆为偶数者才是非磁性核。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0129", "t": "多选题", "s": "结合上述情景，有关磁性原子核的性质与应用，下列描述正确的有", "o": {"A": "只有质子数或中子数为奇数的原子核才具有自旋磁矩，才能产生磁共振现象", "B": "¹H因人体内丰度最高、旋磁比最大，成为临床MRI的主要成像核素", "C": "¹⁶O与¹²C的质子数、中子数均为偶数，自旋量子数为零，无磁共振现象", "D": "²³Na、³¹P、¹⁹F均属磁性核，可用于磁共振成像或波谱研究", "E": "原子核的磁矩方向与其自旋角动量方向之间没有确定关系"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-002", "kp": "磁性原子核与自旋", "ch": "二、医学物理基础 → 5.磁学基础知识 → (1)自旋和核磁的概念", "ex": "【为什么对】A正确：核内质子与中子均倾向成对且自旋反向抵消，只有存在未配对核子（质子数或中子数为奇数）时才有净自旋与磁矩。B正确：人体约70%为水，氢质子摩尔浓度最高；¹H旋磁比γ／2π＝42.58 MHz/T，在常见核素中最大，两者共同决定了氢质子成像信噪比最高。C正确：¹⁶O（8质子8中子）与¹²C（6质子6中子）皆为偶偶核，I＝0。D正确：²³Na（11质子12中子）、³¹P（15质子16中子）、¹⁹F（9质子10中子）均含奇数质子，是磁性核，已分别用于钠成像、磷谱与氟成像。【为什么错】E错误：核磁矩μ与自旋角动量P之间通过旋磁比γ相联系，μ＝γ·P，二者方向共线（质子的γ为正，磁矩与角动量同向）。正是这一确定关系使Larmor方程ω₀＝γB₀得以成立。", "tr": "旋磁比γ是核的固有常数，决定同一磁场下不同核的共振频率；把“丰度最高”与“旋磁比最大”混为一谈，或误以为任何原子核都能成像，都是常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0130", "t": "单选题", "s": "结合上述情景，已知1.5 T磁场中氢质子的Larmor频率约为63.87 MHz。若主磁场提高到3.0 T，其Larmor频率约为", "o": {"A": "31.9 MHz", "B": "63.9 MHz", "C": "95.8 MHz", "D": "127.7 MHz", "E": "255.5 MHz"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-003", "kp": "Larmor方程的定量计算", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】Larmor方程ω₀＝γB₀，用频率表示为f₀＝(γ／2π)·B₀。氢质子的γ／2π＝42.58 MHz/T，故3.0 T时f₀＝42.58×3.0≈127.7 MHz，故选D。也可由比例直接得出：63.87×(3.0／1.5)＝127.74 MHz。【为什么错】A 31.9 MHz对应0.75 T，方向相反。B 63.9 MHz仍为1.5 T的频率，未随场强变化，误认为共振频率与场强无关。C 95.8 MHz对应2.25 T，属按平均值错算。E 255.5 MHz对应6.0 T，把倍数取错。", "tr": "Larmor频率与B₀成严格线性关系，这决定了3.0 T设备的射频波长更短、介电效应与B₁场不均匀更明显，也使比吸收率（SAR）近似随场强平方上升——这些都是高场成像必须面对的连锁效应。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0131", "t": "单选题", "s": "已知³¹P的旋磁比γ／2π＝17.24 MHz/T。在3.0 T MR系统上开展³¹P磁共振波谱检查时，射频发射与接收的中心频率应设置为约", "o": {"A": "51.7 MHz", "B": "60.0 MHz", "C": "127.7 MHz", "D": "17.2 MHz", "E": "42.6 MHz"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-004", "kp": "多核共振频率与旋磁比", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】任何磁性核的共振频率均由f₀＝(γ／2π)·B₀决定。³¹P在3.0 T下的共振频率为17.24×3.0≈51.7 MHz，故射频系统的中心频率须设置在约51.7 MHz，且必须配备相应的³¹P专用（或双调谐）线圈，选A。【为什么错】B 60.0 MHz为任意数值，无对应关系。C 127.7 MHz是同一场强下¹H的共振频率，若误用则完全无法激发磷核。D 17.2 MHz是³¹P在1.0 T下的频率，漏乘场强。E 42.6 MHz是¹H在1.0 T下的频率，属核素与场强双重混淆。", "tr": "不同核在同一磁场中共振频率相差甚远（3.0 T下¹H为127.7 MHz、³¹P为51.7 MHz、²³Na约33.8 MHz），因此多核成像必须使用双调谐或专用线圈，且需单独做频率校准与匀场；直接套用氢质子频率是多核波谱失败的常见原因。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0132", "t": "单选题", "s": "关于热平衡状态下人体组织的宏观纵向磁化矢量M₀，下列描述正确的是", "o": {"A": "M₀随主磁场强度B₀增大而近似线性增大，这是高场MRI信噪比更高的根本原因之一", "B": "M₀的方向与B₀方向相互垂直", "C": "M₀随组织温度升高而增大", "D": "热平衡状态下存在可被接收线圈检出的横向磁化分量", "E": "M₀的大小与组织的质子密度无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-005", "kp": "宏观磁化矢量的形成", "ch": "二、医学物理基础 → 5.磁学基础知识 → (1)自旋和核磁的概念", "ex": "【为什么对】置于B₀中的质子按能量分为顺磁场（低能）与逆磁场（高能）两个自旋态，按玻尔兹曼分布低能态略多，其差值形成沿B₀方向的宏观纵向磁化M₀。M₀正比于质子密度与B₀、反比于绝对温度，故场强越高M₀越大、可用信号越强，这是高场MRI信噪比优势的物理根源，选A。【为什么错】B M₀方向与B₀平行同向（沿z轴），不是垂直。C 由居里定律M₀∝1／T，温度升高使能级布居差减小，M₀反而下降；这一原理也是MR测温技术的基础之一。D 平衡态下各质子的进动相位随机分布，横向分量相互抵消，净横向磁化为零，因此必须施加射频脉冲产生相位相干后才有可检测信号。E M₀与单位体积内参与共振的质子数（质子密度）成正比，这正是质子密度加权成像的物理依据。", "tr": "“平衡态无横向磁化”与“纵向磁化不能被直接检测”是理解射频激发必要性的两个关键点：接收线圈只能感应垂直于B₀平面内旋转的磁化分量，故必须先把M₀翻转到横向平面。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0133", "t": "多选题", "s": "有关纵向弛豫（T1）与横向弛豫（T2）在机制上的差异，下列描述正确的有", "o": {"A": "T1弛豫是受激质子把能量传递给周围晶格（分子环境）的过程，存在净能量交换", "B": "T2弛豫源于质子之间的自旋—自旋相互作用导致的相位散失，不涉及向外的净能量传递", "C": "同一组织的T2值总是小于或等于其T1值", "D": "当分子运动频率越接近Larmor频率时，能量传递效率越高、T1值越短，脂肪即属此类", "E": "主磁场强度升高时，组织的T1值缩短而T2值明显延长"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-006", "kp": "T1与T2弛豫机制的本质差异", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】A正确：纵向弛豫又称自旋—晶格弛豫，是高能态质子把吸收的射频能量释放给周围分子（晶格）并返回低能态的过程，伴随实际的能量转移。B正确：横向弛豫又称自旋—自旋弛豫，是相邻质子微观磁场相互干扰造成进动相位逐渐失去相干，宏观横向磁化衰减，系统内部能量重新分配而不向外释放。C正确：横向失相位既受自旋—自旋作用影响，也受纵向恢复的连带影响，理论与实测均满足T2≤T1，纯液体中二者可接近相等。D正确：弛豫效率取决于分子运动频率与Larmor频率的匹配程度；脂肪的中等大小分子其运动频率接近Larmor频率，能量传递高效，故T1最短、T1WI上呈高信号。【为什么错】E错误：场强升高时分子运动频率与更高的Larmor频率匹配变差，能量传递效率下降，组织T1值普遍延长（3.0 T较1.5 T约延长20%～40%）；T2值则轻度缩短或基本不变，绝非“明显延长”。", "tr": "“T1随场强延长、T2基本不变或略缩短”是高场序列参数必须重新优化的根本原因；另需注意T1的长短取决于分子运动频率与Larmor频率的“匹配度”，而不是简单的“分子越大T1越短”——大分子（如蛋白）运动过慢，T1反而长。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0134", "t": "单选题", "s": "关于T2与T2*的区别及其成像意义，下列描述错误的是", "o": {"A": "T2*同时包含自旋—自旋相互作用与主磁场不均匀性两方面的影响", "B": "同一组织的T2*总是小于或等于其T2", "C": "自旋回波序列的180°复相脉冲可补偿静磁场不均匀造成的失相位，所测得的是T2", "D": "梯度回波序列依靠读出梯度反转产生回波，不能补偿静磁场不均匀，所测得的是T2*", "E": "磁敏感加权成像（SWI）与血氧水平依赖成像（BOLD）主要依赖T2缩短效应，与T2*无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-007", "kp": "T2与T2*的区别", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】E为错误项，故为本题答案。SWI利用组织间磁化率差异造成的局部磁场不均匀，BOLD则利用脱氧血红蛋白的顺磁性引起的局部场畸变，二者的对比机制本质上都是T2*效应，必须采用梯度回波类序列并使用较长TE才能显现；若改用自旋回波，180°脉冲会把这些磁化率效应“聚焦”掉，对比随之消失。【为什么错】A正确：1／T2*＝1／T2＋1／T2′，其中T2′项由静磁场不均匀（含化学位移与磁化率差异）引起。B正确：由上式可知T2*≤T2，衰减更快。C正确：180°脉冲使因静磁场不均匀而超前或滞后的自旋在回波时刻重新相干，故SE测得的是真正的T2。D正确：梯度反转只能补偿由读出梯度自身引起的失相位，对静磁场不均匀无能为力，因此GRE测得T2*。", "tr": "凡涉及磁化率（出血、铁沉积、钙化、骨小梁、气—组织界面、BOLD）的成像，都要靠T2*而不是T2；相反，若要消除磁化率伪影（如金属植入物附近、颅底），则应选择自旋回波类序列并缩短TE、增大带宽。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0135", "t": "多选题", "s": "有关共振与磁共振现象，下列描述正确的有", "o": {"A": "只有当射频脉冲频率等于该核在当前磁场中的Larmor频率时，才能发生共振并有效吸收能量", "B": "射频脉冲使宏观磁化矢量偏离B₀方向，翻转角由脉冲幅度与作用时间共同决定", "C": "90°脉冲可使纵向磁化完全转变为横向磁化", "D": "射频脉冲停止后，质子通过弛豫释放能量，并在接收线圈中感应出自由感应衰减信号", "E": "磁共振过程中原子核吸收射频能量跃迁至高能态，属于电离辐射作用"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-008", "kp": "磁共振现象的产生条件", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】A正确：共振的本质是能量匹配，射频光子能量须恰好等于两个自旋能级之差，对应频率即Larmor频率；这正是选层梯度配合特定频率射频脉冲能实现选择性激发的原理。B正确：翻转角α＝γ·B₁·t，由射频场幅度B₁与持续时间t共同决定。C正确：90°脉冲把全部纵向磁化翻转到横向平面，此时纵向磁化为零、横向磁化最大。D正确：射频关闭后横向磁化在xy平面进动并逐渐衰减，在接收线圈中感应出按T2*衰减的自由感应衰减（FID）信号。【为什么错】E错误：射频属于非电离辐射，其光子能量在10⁻⁷ eV量级，远低于使物质电离所需的十几电子伏，不能引起电离与化学键断裂。MRI的主要生物学效应是射频致热（以SAR限值管理）、梯度切换致周围神经刺激与噪声，而非电离损伤。", "tr": "把“核跃迁”与“电离”混为一谈是概念性错误；MRI的安全关注点是SAR、dB/dt、噪声、主磁场吸引效应与植入物相容性，与X线的辐射防护体系完全不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0136", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，患者男性，45岁，反复头痛就诊，行颅脑MRI平扫。科室近期由1.5 T升级为3.0 T超导MRI，技师沿用原1.5 T的自旋回波T1加权参数（TR 450 ms、TE 12 ms、层厚5 mm）扫描，结果发现图像整体信噪比虽有提升，但灰质与白质的对比度明显下降，脑室与脑实质的分界不如原1.5 T图像清晰。从核磁弛豫的场强依赖性分析，最恰当的参数调整是", "o": {"A": "适当延长重复时间（如550～700 ms），或改用反转恢复预备的T1加权序列以重建灰白质对比", "B": "进一步缩短重复时间至300 ms以增强T1权重", "C": "延长回波时间至40 ms以增加对比", "D": "把射频翻转角提高到180°", "E": "改用梯度回波T2*加权序列替代T1加权序列"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAG-009", "kp": "场强对T1弛豫及序列参数的影响", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】主磁场升高使Larmor频率升高，组织分子运动频率与之匹配程度下降，纵向弛豫效率降低，各种脑组织的T1值普遍延长且彼此差值相对压缩。若仍沿用1.5 T的短TR，则灰、白质的纵向磁化在TR末均恢复很少且差异被压缩，对比度自然下降，同时信号强度损失。正确做法是适当延长TR至550～700 ms使两者恢复差异重新拉开，或采用反转恢复预备的T1加权序列（如IR-FSE、MPRAGE／BRAVO／3D-TFE），利用反转脉冲放大T1差异，故A正确。【为什么错】B进一步缩短TR会使两种组织的恢复量都趋近于零，对比与信噪比同时恶化。C延长TE会引入T2权重并降低信号，与T1加权的目的相反。D 180°脉冲会把磁化矢量翻至负纵轴，不产生横向磁化，无法形成常规激发。E改用T2*加权虽然可成像，但完全放弃了T1对比信息，不能解决灰白质T1对比的问题，且3.0 T下磁化率伪影更重。", "tr": "“1.5 T参数直接搬到3.0 T”是升级设备后最常见的技术失误；除TR需要重新优化外，还需注意SAR升高（限制回波链长度与翻转角）、化学位移伪影加倍（需加大带宽）以及介电／驻波效应带来的信号不均匀。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0137", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，下列电离辐射生物效应中，属于随机性效应的是", "o": {"A": "皮肤红斑", "B": "放射性白内障", "C": "急性放射病", "D": "辐射致癌与可遗传效应", "E": "暂时性不育"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-001", "kp": "确定性效应与随机性效应", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (1)生物效应", "ex": "【为什么对】随机性效应的特点是不存在剂量阈值、发生概率与剂量成正比而严重程度与剂量无关，主要包括辐射致癌与可遗传（遗传）效应，其机制为单个细胞DNA损伤后错误修复而存活并增殖，故选D。【为什么错】A皮肤红斑、B放射性白内障、C急性放射病、E暂时性不育均属确定性效应（组织反应），它们存在明确的剂量阈值，超过阈值后严重程度随剂量增加而加重，机制为大量细胞被杀死导致组织功能丧失。", "tr": "确定性效应“有阈值、比严重程度”，随机性效应“无阈值、比发生概率”；诊断放射学中患者与工作人员的剂量通常远低于确定性效应阈值，防护的主要目标正是把随机性效应的风险降到可合理达到的最低水平，但介入放射学中皮肤确定性效应仍需警惕。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0138", "t": "多选题", "s": "结合上述情景，影响电离辐射损伤程度的主要因素包括", "o": {"A": "受照剂量与剂量率，在总剂量相同时剂量率越高损伤越重", "B": "射线的种类与能量，传能线密度越高者相对生物效应越大", "C": "受照部位与受照面积，全身照射较同剂量局部照射后果更严重", "D": "组织细胞的辐射敏感性，分裂旺盛、分化程度低的细胞更敏感", "E": "机体的年龄与生理状态对辐射敏感性没有影响"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-002", "kp": "影响辐射损伤的因素", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (2)影响辐射损伤的因素", "ex": "【为什么对】A正确：剂量率高则单位时间内损伤集中，机体来不及修复，损伤更重；分次小剂量照射因存在亚致死损伤修复而后果较轻。B正确：α粒子、中子等高传能线密度（LET）辐射在单位径迹上电离密集，易造成DNA双链断裂，相对生物效应（RBE）远高于X、γ射线，这正是辐射权重因子取值不同的依据。C正确：全身照射可累及造血、消化等关键系统，同剂量下后果远重于局部照射；受照面积越大后果越重。D正确：Bergonié-Tribondeau定律指出，细胞分裂越旺盛、分化程度越低、代谢越活跃者对辐射越敏感。【为什么错】E错误：年龄与生理状态显著影响辐射敏感性，胎儿与婴幼儿最敏感，儿童高于成人，妊娠期、营养不良、合并疾病或免疫抑制状态时敏感性升高。这正是儿科影像必须严格执行低剂量原则的依据。", "tr": "“分次照射比一次照射损伤轻”是剂量率效应的直接推论，也是放射治疗分次给量的原理；但对随机性效应而言，其风险按累积剂量线性无阈估算，分次并不降低总风险。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0139", "t": "单选题", "s": "按Bergonié-Tribondeau定律，下列组织中对电离辐射最敏感的是", "o": {"A": "肌肉组织", "B": "神经组织", "C": "淋巴组织", "D": "成熟骨组织", "E": "软骨组织"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-003", "kp": "组织辐射敏感性排序", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (1)生物效应", "ex": "【为什么对】辐射敏感性与细胞的增殖能力成正比、与分化程度成反比。高度敏感组织包括淋巴组织、骨髓造血组织、生殖腺（精原细胞）、胃肠道上皮与胚胎组织，其中淋巴细胞即使在间期也极易凋亡，是最敏感的细胞类型之一，外周血淋巴细胞计数下降是急性放射损伤最早的实验室指标，故选C。【为什么错】A肌肉细胞属高度分化、不再分裂，辐射敏感性低。B神经组织（尤其成熟神经元）分化程度最高、几乎不分裂，是敏感性最低的组织之一。D成熟骨组织代谢缓慢，敏感性低；但生长期骨骺软骨敏感性明显高于成熟骨。E成熟软骨敏感性亦低。", "tr": "“生长期”与“成熟期”组织敏感性差别巨大：儿童骨骺、乳腺芽、甲状腺的敏感性远高于成人对应组织，这是儿科防护中屏蔽与限束特别强调的部位。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0140", "t": "案例分析题", "s": "患者女性，28岁，末次月经距今10周（相当于受孕后约8周），因车祸致腹部闭合性损伤送入急诊，血压偏低、腹部压痛明显，临床高度怀疑腹腔内出血需迅速明确诊断。急诊超声因肠气干扰显示不满意。科室配备128层CT与3.0 T MRI，MRI当日排队时间约3小时。关于该患者的检查决策与辐射风险，下列处理最恰当的是", "o": {"A": "受孕后9天至8周为器官形成期、畸形风险相对最高，应先尽力用超声与临床评估；若病情危急且检查确属必需，可在充分告知并优化参数（降低管电压与管电流、严格限束、缩小扫描范围、避免重复期相）后行腹部CT", "B": "妊娠期属CT的绝对禁忌证，任何情况下均不得行腹部CT", "C": "该孕周尚处于“全或无”阶段，胎儿不会发生畸形，可直接按常规剂量完成多期增强CT", "D": "只要在腹部覆盖铅围裙即可完全消除胎儿受照，故无需调整扫描参数", "E": "改用腹部X线平片，其胎儿剂量与腹部CT相当但更为安全"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-004", "kp": "胎儿出生前受照效应与孕期检查决策", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (3)胎儿出生前受照效应", "ex": "【为什么对】胎儿受照效应有明显的时间窗依赖：受孕后0～8天为着床前期，表现为“全或无”（胚胎死亡或完全正常）；9天至8周为器官形成期，畸形风险最高；8～15周中枢神经系统增殖迁移最活跃，智力发育障碍风险最高，16～25周风险次之；整个孕期均存在诱发儿童期恶性肿瘤的随机性风险。本例处于器官形成期末，因此原则是能不照就不照、必须照就把剂量压到最低，同时履行告知义务，这正是正当化与最优化两原则在孕期的具体落实，故A正确。【为什么错】B妊娠并非CT的绝对禁忌，母体生命受威胁时抢救优先；一次腹部CT的胎儿剂量通常在数十mGy以内，远低于100 mGy的公认阈值参考水平。C“全或无”仅适用于受孕后8天以内，本例已超出该阶段，说法错误且会导致不必要的高剂量照射。D胎儿受照主要来自机体内部散射，扫描野内的铅围裙无法阻挡内散射，只能减少体外杂散射，作用有限。E腹部平片虽剂量低于CT，但其诊断腹腔内出血的能力远不足以满足临床需求，不能达到正当化要求；且“剂量与CT相当”的说法不成立。", "tr": "孕期影像决策的两个常见极端都错误：一是“绝对禁止”导致延误抢救，二是“无所谓”导致不必要照射。正确做法是逐例进行正当性判断、优先选择无电离辐射方法、必要时优化参数并记录估算胎儿剂量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0141", "t": "多选题", "s": "关于电离辐射的皮肤效应与外照射慢性放射病，下列描述正确的有", "o": {"A": "皮肤效应属确定性效应，存在剂量阈值，超过阈值后其严重程度随剂量增加而加重", "B": "一次急性照射引起早期一过性红斑的剂量阈值约为2 Gy，暂时性脱毛的阈值约为3 Gy", "C": "介入放射学长时间透视可导致皮肤放射性损伤，应记录并控制患者皮肤入射剂量", "D": "外照射慢性放射病是较长时间内累积接受超过剂量限值照射后引起的全身性疾病，以造血系统改变为主要表现", "E": "皮肤放射性损伤均在受照后24小时内显现"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-005", "kp": "皮肤效应与外照射慢性放射病", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (4)皮肤效应", "ex": "【为什么对】A正确：皮肤损伤由基底层细胞大量死亡引起，属典型的组织反应（确定性效应）。B正确：常用参考阈值为早期一过性红斑约2 Gy、暂时性脱毛约3 Gy、永久性脱毛约7 Gy、干性脱屑约10 Gy、湿性脱屑约15～18 Gy、皮肤坏死约20～25 Gy。C正确：复杂介入手术单次皮肤剂量可达数Gy，国际与国内规范均要求监测参考点空气比释动能与剂量面积乘积，超过警戒值时告知并随访。D正确：外照射慢性放射病以乏力、头晕等神经衰弱症候群与白细胞、血小板减少等造血抑制为主要表现，诊断需结合职业史与个人剂量档案。【为什么错】E错误：皮肤放射性损伤具有明显的潜伏期，早期一过性红斑可在数小时内出现并消退，而主要红斑多在照射后约10天至2周出现，脱毛约2～3周，湿性脱屑与坏死可延迟数周至数月，晚期还可出现萎缩、毛细血管扩张与纤维化。", "tr": "介入术后患者若在数周后出现界限清楚的方形红斑或脱毛，应首先想到放射性皮肤损伤而非皮肤病；“照射当时无异常”绝不能作为排除依据，潜伏期是确定性皮肤效应的重要特征。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0142", "t": "单选题", "s": "结合上述情景，在保证获得必要诊断信息的前提下，把受检者所受剂量降低到可合理达到的最低水平（ALARA），体现的放射防护基本原则是", "o": {"A": "实践的正当化", "B": "防护与安全的最优化", "C": "个人剂量限值", "D": "时间防护", "E": "距离防护"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-001", "kp": "放射防护三原则的内涵", "ch": "二、医学物理基础 → 7.X线防护与测量 → (1)放射防护基本原则", "ex": "【为什么对】国际放射防护委员会（ICRP）提出的三项基本原则中，防护与安全的最优化即ALARA原则：在考虑经济与社会因素后，把受照剂量与受照人数保持在可合理达到的尽量低水平。“在满足诊断要求前提下尽量降低剂量”正是该原则的标准表述，故选B。【为什么错】A实践的正当化解决“该不该做这项检查”的问题，即所带来的利益必须大于其可能引起的辐射危害。C个人剂量限值用于限制职业照射与公众照射，明确不适用于患者的医疗照射，因此不能用来解释患者剂量优化。D时间防护与E距离防护属外照射防护的具体技术措施，是最优化原则在操作层面的落实手段，而非基本原则本身。", "tr": "三原则中只有正当化与最优化适用于医疗照射，剂量限值不适用于患者——这是最容易被误答的一点；医疗照射的剂量管理依靠“诊断参考水平”而非“剂量限值”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0143", "t": "多选题", "s": "依据GB 18871—2002《电离辐射防护与辐射源安全基本标准》，关于剂量限值的下列表述，正确的有", "o": {"A": "职业照射的有效剂量限值为连续5年内平均每年20 mSv", "B": "任何单一年份内职业照射的有效剂量不得超过50 mSv", "C": "公众照射的年有效剂量限值为1 mSv", "D": "该标准规定职业照射眼晶状体的年当量剂量限值为150 mSv", "E": "剂量限值同样适用于患者所受的医疗照射"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-002", "kp": "我国放射卫生防护标准的剂量限值", "ch": "二、医学物理基础 → 7.X线防护与测量 → (4)我国放射卫生防护标准", "ex": "【为什么对】A、B正确：GB 18871—2002规定职业人员有效剂量为连续5年平均20 mSv/年（5年总计不超过100 mSv），且任何单一年份不超过50 mSv，二者必须同时满足。C正确：公众成员的年有效剂量限值为1 mSv；特殊情况下如5年平均不超过1 mSv/年，单年可适当提高。D正确：该标准中职业照射的眼晶状体年当量剂量限值为150 mSv，四肢（手和足）或皮肤为500 mSv。【为什么错】E错误：剂量限值仅适用于职业照射与公众照射，不适用于患者的医疗照射。医疗照射通过正当化判断与诊断参考水平进行管理，若对患者设定剂量限值，反而可能因限制必要检查而损害其健康利益。", "tr": "职业照射“5年平均20、单年不超50”是一对必须同时记住的数字，只记一个即被扣分；此外ICRP在2011年建议把眼晶状体职业限值收紧为5年平均20 mSv/年、单年不超50 mSv，与GB 18871—2002的150 mSv不同，答题时应以我国现行标准为准并注意题干指向。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0144", "t": "单选题", "s": "结合上述情景，外照射防护的三大基本技术措施是", "o": {"A": "实践正当化、防护最优化、剂量限值", "B": "时间防护、距离防护、屏蔽防护", "C": "个人防护、集体防护、环境防护", "D": "源项控制、途径控制、人员控制", "E": "限束、滤过、滤线栅"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-003", "kp": "外照射防护的一般措施", "ch": "二、医学物理基础 → 7.X线防护与测量 → (2)外照射防护一般措施", "ex": "【为什么对】外照射防护的三大技术措施为时间防护（缩短受照时间，剂量与时间成正比）、距离防护（增大与源的距离，剂量按距离平方反比下降）和屏蔽防护（在人与源之间设置铅、混凝土等屏蔽体使射线按指数规律衰减），故选B。【为什么错】A是放射防护的三项基本原则，属管理与决策层面，不是具体技术措施。C为按防护对象所作的分类描述，非标准三措施。D属放射性污染控制的思路，主要针对内照射与开放型放射源。E限束、滤过、滤线栅是X线摄影中改善图像质量与降低剂量的具体技术手段，可归入最优化措施，但不是外照射防护的三大基本措施。", "tr": "“三原则”与“三措施”是本细目最高频的混淆点：原则回答“该不该做、做到什么程度、不得超过多少”，措施回答“具体怎么做”；答题时先看题干问的是“基本原则”还是“防护措施”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0145", "t": "单选题", "s": "某防护材料对特定能量X线的半价层为0.25 mm铅当量。若要把透过的辐射剂量率降至原来的1／16，所需屏蔽层厚度至少为", "o": {"A": "0.25 mm铅当量", "B": "0.5 mm铅当量", "C": "1.0 mm铅当量", "D": "2.0 mm铅当量", "E": "4.0 mm铅当量"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-004", "kp": "屏蔽厚度的半价层计算", "ch": "二、医学物理基础 → 7.X线防护与测量 → (3)外照射屏蔽防护", "ex": "【为什么对】每增加一个半价层，透射剂量率减半。1／16＝(1／2)⁴，需要4个半价层，故所需厚度＝4×0.25 mm＝1.0 mm铅当量，选C。【为什么错】A仅1个半价层，透射率为1／2。B为2个半价层，透射率1／4。D为8个半价层，透射率1／256，虽满足要求但远超“至少”所需，不符合题意。E为16个半价层，屏蔽严重过度，既不经济也无必要。", "tr": "半价层法计算屏蔽的前提是射线束线质在穿透过程中基本稳定；实际防护设计中射束硬化会使后续半价层逐渐增大，因此规范中的屏蔽厚度还需考虑宽束条件下的散射累积因子与工作负荷、居留因子、利用因子，不能仅凭半价层数简单外推。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-0146", "t": "多选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，有关辐射剂量学中的各量及其单位，下列描述正确的有", "o": {"A": "照射量的SI单位为库仑每千克（C/kg），专用单位为伦琴（R），1 R＝2.58×10⁻⁴ C/kg", "B": "吸收剂量的SI单位为戈瑞（Gy），1 Gy＝1 J/kg", "C": "当量剂量等于吸收剂量与辐射权重因子之积，SI单位为希沃特（Sv）", "D": "有效剂量等于各器官或组织的当量剂量按组织权重因子加权求和，SI单位为希沃特（Sv）", "E": "照射量适用于任何介质中任何类型的电离辐射"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-005", "kp": "照射量、吸收剂量与防护量", "ch": "二、医学物理基础 → 7.X线防护与测量 → (5)照射量测量", "ex": "【为什么对】A正确：照射量以X、γ射线在空气中产生的电离电荷量定义，SI单位C/kg，专用单位伦琴，换算关系为1 R＝2.58×10⁻⁴ C/kg。B正确：吸收剂量D＝dε／dm，SI单位Gy，1 Gy＝1 J/kg，适用于任何介质与任何辐射类型。C正确：当量剂量HT＝Σ wR·DT,R，X、γ射线与电子的辐射权重因子为1，α粒子为20，单位Sv。D正确：有效剂量E＝Σ wT·HT，用于评价全身随机性效应风险，单位Sv。【为什么错】E错误：照射量的定义严格限定于空气介质中的X射线与γ射线，且能量范围有限（一般在数十keV至约3 MeV），不适用于α、β、中子等其他辐射，也不适用于空气以外的介质，这正是国际上逐步用空气比释动能取代照射量的原因。", "tr": "常用换算关系为1 R在空气中约相当于8.76 mGy的空气吸收剂量，在软组织中约9.5 mGy，切勿把“1 R≈1 Gy”当成近似成立；此外Gy与Sv虽量纲相同（J/kg），但物理含义不同，不能互换使用。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-0147", "t": "案例分析题", "s": "某导管室为患者男性、68岁行冠状动脉介入治疗，预计透视时间较长。技师需在机房内协助操作台旁工作，全程不能离开床边。机房配备铅橡胶围裙、甲状腺护领、铅眼镜、床侧铅帘与悬吊式铅屏，C形臂可在床上或床下放置X线管，透视模式可选连续透视与脉冲透视（3、7.5、15帧/s可调）。为把工作人员职业受照降至可合理达到的最低水平，下列措施组合最恰当的是", "o": {"A": "穿0.35 mm铅当量以上铅衣并配戴甲状腺护领与铅眼镜，充分使用床侧铅帘与悬吊铅屏，X线管置于检查床下方，尽量站在探测器一侧并远离球管，采用低帧率脉冲透视并缩短累计透视时间，同时规范佩戴个人剂量计", "B": "只需穿铅衣，不必使用甲状腺护领与铅屏，通过提高透视帧率缩短总操作时间来降低剂量", "C": "尽量站在X线管一侧，因为散射线主要沿原射线方向朝探测器传播", "D": "正位透视时将X线管置于检查床上方，可减少术者受照", "E": "用连续透视替代脉冲透视，图像更连贯且总剂量更低"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PROT-006", "kp": "介入放射学的职业防护措施", "ch": "二、医学物理基础 → 7.X线防护与测量 → (2)外照射防护一般措施", "ex": "【为什么对】介入操作中工作人员受照几乎全部来自患者体内产生的散射线，其强度以患者被照射体积为中心向各方向发散，且以射线入射侧（球管侧）最强。A项完整体现了三大防护措施：屏蔽（铅衣、护领、铅眼镜、床侧铅帘与悬吊铅屏，其中铅眼镜针对晶状体这一敏感器官）、距离（站在探测器侧、尽量远离球管）、时间（低帧率脉冲透视、缩短累计透视时间）；把X线管置于床下可使强散射区集中在术者下肢并被床侧铅帘阻挡，而非直接照射躯干与头颈部；规范佩戴个人剂量计则满足职业照射监测要求，故A正确。【为什么错】B甲状腺与晶状体是介入人员的重点防护部位，省略护领与铅屏会显著增加受照；提高帧率会成倍增加剂量率，不能靠“更快完成”抵消。C散射线在患者体内产生后向各方向发射，其中背向散射（朝向球管侧）强度最高，站在球管一侧受照最重，说法完全颠倒。D球管置于床上方时，患者入射侧朝上，强散射区正对术者头颈与晶状体，是应当避免的错误摆位。E脉冲透视通过降低单位时间曝光次数显著减少剂量，同帧率下连续透视剂量明显更高，说法与事实相反。", "tr": "“球管在下、探测器在上”“人在探测器侧”是介入防护的两条铁律；此外个人剂量计的规范佩戴方式为躯干铅衣内佩戴一枚用于评价有效剂量，必要时在铅衣外衣领处再佩戴一枚以估算头颈部与晶状体剂量，二者不可相互替代。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1001", "t": "单选题", "s": "伦琴将1895年发现的未知射线命名为X射线，其含义是", "o": {"A": "取发现者伦琴姓氏的首字母", "B": "数学中常用X代表未知数，表示“未知射线”", "C": "表示射线按X级能量分类", "D": "表示射线波长的计量单位", "E": "表示辐射剂量等级"}, "d": "中", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-101", "kp": "X线命名的含义", "ch": "二、医学物理基础 → 1.X线的产生 → (1)X线的发现", "ex": "【为什么对】伦琴发现该射线时对其本质尚不清楚，因数学中常用字母X表示未知数，故命名为X射线，以示“未知射线”，故选B。【为什么错】A X射线的命名并非取姓氏首字母（伦琴Röntgen的R未被使用）。C X线不以“X级”能量分类命名。D X线的波长单位为纳米（nm），与X字母无关。E辐射剂量等级另有专有单位，与命名无关。", "tr": "X（未知）而非X级、X单位，命名的本质是“未知”含义，常与伦琴获奖年份等史实混淆命题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1002", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，固定阳极X线管中，高速电子轰击阳极靶面时，其动能绝大部分转化为", "o": {"A": "特征X线能", "B": "连续X线能", "C": "热能", "D": "荧光能", "E": "二次电子动能"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-102", "kp": "X线产生中的能量转化", "ch": "二、医学物理基础 → 1.X线的产生 → (2)X线的产生", "ex": "【为什么对】高速电子轰击阳极靶面时，其动能绝大部分（99%以上）转化为热能，仅有不足1%转化为X线能，因此阳极需要良好的散热结构，故选C。【为什么错】A特征X线能只占X线总能量的小部分（约10%～20%的X线输出）。B连续X线（韧致辐射）占X线输出的大部分，但两者合计仍不足电子动能的1%。D荧光是X线作用于荧光物质时产生的次级可见光，与阳极过程无关。E二次电子数量少、能量低，非主要能量转化去向。", "tr": "电子动能的99%以上转化为热、不足1%转化为X线，这是旋转阳极与散热设计（热容量）的物理基础。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1003", "t": "单选题", "s": "连续X线（韧致辐射）产生的物理机制是", "o": {"A": "外层电子跃迁至内层电子空位", "B": "高速电子受原子核库仑场作用急剧减速，部分动能以光子形式辐射", "C": "原子核放射性衰变释放光子", "D": "正负电子对湮灭产生光子", "E": "电子从金属表面逸出形成光电流"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-103", "kp": "连续X线产生机制", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】高速电子接近原子核时，受核库仑电场强烈吸引而急剧减速，损失的功能以电磁辐射（光子）形式释放，即为韧致辐射（连续X线），故选B。【为什么错】A外层电子跃迁至内层空位产生的是特征X线，能量固定、为线状谱。C放射性核素衰变释放的γ射线属核过程，与X线产生机制无关。D正负电子对湮灭产生511 keV光子对，发生在高能γ辐射领域。E光电效应中的光电子是电子发射，不产生X线。", "tr": "连续X线=韧致辐射（电子减速）；特征X线=电子跃迁；两种谱的机制与能谱形态（连续谱vs线状谱）是核心区分点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1004", "t": "单选题", "s": "结合上述情景，管电压为120 kV时，连续X线谱的最短波长约为", "o": {"A": "0.0050 nm", "B": "0.0103 nm", "C": "0.0200 nm", "D": "0.1030 nm", "E": "0.1240 nm"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-104", "kp": "连续X线最短波长计算", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】根据公式λ_min（nm）=1.24/U（kV），当U=120 kV时，λ_min=1.24/120≈0.0103 nm，故选B。【为什么错】A 0.0050 nm对应约248 kV，明显偏低。C 0.0200 nm对应约62 kV，与120 kV不符。D 0.1030 nm对应约12 kV，为软X线能量。E 0.1240 nm为1 kV能量对应的换算常数（1.24 nm），不是结果。", "tr": "公式λ_min(nm)=1.24/U(kV)，注意单位是纳米而非埃（若用埃为单位则λ_min=12.4/U Å），系数混用是最常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1005", "t": "单选题", "s": "钨靶X线管产生K系特征X线的具体过程是", "o": {"A": "高速电子将K壳层电子击出，L壳层电子跃迁填充K壳层空位并释放特征光子", "B": "K壳层电子自发逃逸", "C": "外层电子被加速后逸出原子", "D": "原子核捕获外层电子", "E": "正负电子对湮灭后释放光子"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-105", "kp": "K系特征X线产生过程", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】当高速电子的能量足以将靶原子K壳层电子击出形成空位时，L（或M等）壳层电子跃迁至K壳层空位，释放的能量差即为K系特征X线光子，故选A。【为什么错】B K壳层电子被击出需要外来高速电子提供能量，不会自发逃逸。C外层电子被加速逸出是韧致辐射过程中的次级过程，不产生特征X线。D原子核捕获电子属核过程，与特征X线无关。E电子对湮灭发生在高能领域，与靶物质特征X线无关。", "tr": "特征X线光子能量=跃迁壳层能级差，取决于靶物质原子序数；产生前提是管电压超过K壳层激发电位（钨约69.5 kV）。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1006", "t": "单选题", "s": "其他条件不变，增大X线管电流时，X线输出量的变化正确的是", "o": {"A": "X线质与量均增大", "B": "X线量增大，X线质不变", "C": "X线质增大，X线量不变", "D": "X线质与量均不变", "E": "连续谱最短波长变短"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-106", "kp": "管电流对X线量影响", "ch": "二、医学物理基础 → 1.X线的产生 → (4)影响X线产生的因素", "ex": "【为什么对】增大管电流使单位时间轰击靶面的电子数增多，X线光子数（X线量）随之成正比增大；但每个光子的能量由管电压决定，故X线质（硬度、能谱分布）不变，故选B。【为什么错】A“质均增大”错误，质由管电压决定。C“质增大、量不变”方向完全颠倒。D“均不变”与X线量随管电流增大的事实不符。E最短波长由管电压决定（λ_min=1.24/U），与管电流无关，管电流不影响。", "tr": "管电流影响X线“量”（光子数），管电压影响X线“质”（能谱/硬度）同时也影响量（平方关系），二者作用维度不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的吸收与衰减", "页": 33}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1007", "t": "单选题", "s": "结合上述情景，利用阳极效应（足跟效应）拍摄人体长骨全长摄影时，正确的摆位原则是", "o": {"A": "将长骨较薄部位置于阴极侧", "B": "将长骨较厚部位置于阴极侧（X线强度较大侧）", "C": "将管球阳极侧对准长骨中部", "D": "一律利用阳极侧强束", "E": "使长骨长轴垂直于X线束中心线"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-107", "kp": "阳极效应的临床利用", "ch": "二、医学物理基础 → 1.X线的产生 → (5)X线强度的空间分布", "ex": "【为什么对】阳极效应（足跟效应）使沿X线管长轴方向上阴极侧X线强度大于阳极侧。拍摄长骨全长时，将较厚（衰减大）的部位置于阴极侧、较薄部位置于阳极侧，可使胶片两端受照量趋于均匀，故选B。【为什么错】A把厚部放阳极侧会使厚部曝光不足、薄部过度曝光，与补偿目的相反。C管球阳极侧为弱束区，对准中部不能均衡两端。D一味利用阳极侧会加剧两端受照不均。E长骨长轴应与X线束长轴方向一致（平行）放置以利用强度梯度，垂直放置不能利用足跟效应。", "tr": "足跟效应“阴极侧强度大”，厚部放阴极、薄部放阳极；方向记反即落入陷阱，同时注意长骨长轴需与球管长轴方向平行。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1008", "t": "单选题", "s": "关于X线的本质，正确的是", "o": {"A": "X线是带负电的高速粒子流", "B": "X线是波长很短的电磁波，具有波粒二象性", "C": "X线是一种超声波", "D": "X线是光电子与反冲电子的混合流", "E": "X线本质是机械波，需介质传播"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-101", "kp": "X线的本质", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (1)X线的本质与特性", "ex": "【为什么对】X线是波长很短的电磁波，同时具有波动性（干涉、衍射）与粒子性（光子），即波粒二象性，在真空与空气中均以光速传播，故选B。【为什么错】A电子流才是带负电的粒子流，X线光子不带电。C超声波是机械波，频率低、不能穿透人体厚组织。D光电子与反冲电子是X线与物质作用的次级产物，不是X线本身。E机械波需要介质传播，而X线可在真空中传播，属电磁波。", "tr": "X线=电磁波（波粒二象性、真空可传播），与超声（机械波、需介质）本质不同，“X线是粒子流”是常见陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1009", "t": "单选题", "s": "X线照射荧光物质（如钨酸钙）时使其发出可见光，这一特性称为", "o": {"A": "穿透作用", "B": "荧光作用", "C": "电离作用", "D": "感光作用", "E": "生物效应"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-102", "kp": "X线的荧光作用", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (1)X线的本质与特性", "ex": "【为什么对】X线能使钨酸钙、硫氧化钆等荧光物质产生可见荧光，此即荧光作用，是透视检查和增感屏成像的基础，故选B。【为什么错】A穿透作用是X线穿透不同密度物质的能力，是摄影成像的基础。C电离作用使物质产生正负离子，是剂量测量与放射损伤的基础。D感光作用是X线使胶片银盐感光形成潜影，是胶片摄影的基础。E生物效应是X线对机体的损伤作用，用于放射防护与治疗。", "tr": "X线四大效应“穿透、荧光、电离、感光”对应不同应用：透视用荧光、摄影用感光、测剂量用电离，一一对应是常考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1010", "t": "单选题", "s": "结合上述情景，在诊断用X线能量范围内，光电效应发生的概率与光子能量的关系约呈", "o": {"A": "与光子能量成正比", "B": "与光子能量平方成正比", "C": "与光子能量的三次方成反比", "D": "与光子能量无关", "E": "与光子能量平方成反比"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-103", "kp": "光电效应的能量依赖", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】在诊断X线能量范围内，光电效应的发生概率与物质原子序数Z的3～4次方成正比，与光子能量的3次方成反比（约∝1/E³），即低能光子、高原子序数物质中光电效应更易发生，故选C。【为什么错】A、B光电效应概率随能量升高而降低，与能量正比或平方正比均与物理规律相反。D光电效应强烈依赖能量，“无关”错误。E平方反比不准确，应为三次方反比。", "tr": "光电效应“∝Z³～Z⁴、∝1/E³”两个依赖关系是命题核心，三次方反比与平方反比、Z与E的依赖方向是易错点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1011", "t": "单选题", "s": "能量为100 keV的X线光子与软组织（近似水）相互作用时，占主导地位的作用过程是", "o": {"A": "相干散射", "B": "光电效应", "C": "康普顿散射", "D": "电子对效应", "E": "光核反应"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-104", "kp": "诊断能量范围主要作用形式", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】软组织（水）的有效原子序数低（约7.4），在30 keV以上能量区间康普顿散射即占优势；100 keV时光电效应已很弱（∝1/E³），康普顿散射占主导，故选C。【为什么错】A相干散射仅占极小份额，且主要见于极低能区。B光电效应在低能（<30 keV）与高原子序数物质中占优，100 keV软组织中比例很低。D电子对效应需光子能量≥1.02 MeV，100 keV远达不到。E光核反应阈值更高（约数MeV以上），诊断能量下不可能发生。", "tr": "软组织在诊断能量范围以康普顿散射为主；骨因含钙（Z高）在低能时光电效应占比明显高于软组织，两者组织差异是考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的产生", "页": 28}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1012", "t": "单选题", "s": "电子对效应（电子偶效应）发生所需的光子能量阈值为", "o": {"A": "0.511 keV", "B": "1.02 keV", "C": "1.02 MeV", "D": "10 MeV", "E": "100 MeV"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-105", "kp": "电子对效应能量阈值", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】电子对效应中，光子能量必须大于正负电子对的静质量能之和，即2×0.511 MeV≈1.022 MeV，故阈值约1.02 MeV，故选C。【为什么错】A 0.511 MeV是电子静质量能，仅为阈值的一半。B 1.02 keV数值太小（差三个数量级），阈值以MeV计。D、E 10 MeV与100 MeV远高于实际阈值，不属于阈值描述。", "tr": "电子对效应阈值1.02 MeV意味着诊断X线能量（<150 keV）下绝不可能发生电子对效应，该效应的Z²依赖只对高能辐射有意义。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1013", "t": "单选题", "s": "结合上述情景，康普顿散射中，入射光子与原子外层电子作用后发生的变化是", "o": {"A": "光子能量不变，仅改变传播方向", "B": "光子将部分能量传递给电子（反冲电子），自身能量降低且方向改变", "C": "光子被原子完全吸收", "D": "光子能量增大后继续传播", "E": "产生正负电子对"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-106", "kp": "康普顿散射过程", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】康普顿散射中，入射光子与原子外层（结合能很低的轨道）电子发生非弹性碰撞，光子将部分能量传给电子使其脱离原子成为反冲电子，自身能量降低、波长变长并改变方向，即散射光子，故选B。【为什么错】A能量不变仅方向改变是相干（弹性）散射的特征，康普顿散射为非弹性。C光子被完全吸收是光电效应的特征，康普顿散射中光子以散射光子形式继续存在。D光子能量只减不增。E正负电子对由电子对效应产生，需≥1.02 MeV能量，与康普顿散射无关。", "tr": "康普顿散射“能量降低+方向改变+产生反冲电子”与相干散射“能量不变+仅方向改变”的区分是相互作用考点的核心。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的本质及与物质的相互作用", "页": 30}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1014", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，其他条件不变，将管电流由50 mA增至100 mA、管电压由80 kV增至100 kV时，X线强度约增大为原来的", "o": {"A": "2倍", "B": "4倍", "C": "3.1倍", "D": "8倍", "E": "16倍"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-108", "kp": "X线强度与管参数关系计算", "ch": "二、医学物理基础 → 1.X线的产生 → (4)影响X线产生的因素", "ex": "【为什么对】X线强度与管电流成正比、与管电压的平方成正比。管电流增大为原来的100/50=2倍；管电压增大引起的强度增加为（100/80）²=1.5625倍；总强度变化为2×1.5625≈3.1倍，故选C。【为什么错】A 2倍只考虑了管电流的变化。B 4倍为（2）²的错误组合或误将管电压当作一次方。D 8倍是2×2²再乘以2的重复计算。E 16倍是对各因素过度乘方。", "tr": "强度公式“I∝mA·U²”：管电流一次方、管电压二次方，需分别计算后相乘，漏乘或错乘次数即出错。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1015", "t": "单选题", "s": "表示X线质（硬度）最常用的物理量是", "o": {"A": "管电流（mA）", "B": "照射野面积", "C": "半价层（HVL）", "D": "毫安秒（mAs）", "E": "焦点标称值"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQUAL-101", "kp": "X线质的表示", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (3)X线质", "ex": "【为什么对】X线质表示X线的硬度，即穿透能力，通常用半价层（HVL）表示，也可用管电压、滤过及有效能量间接表示，故选C。【为什么错】A管电流大小决定X线量，不直接表示硬度。B照射野面积是投照技术参数，与X线质无关。D mAs表示X线量（曝光量）。E焦点标称值反映X线管焦点成像性能，与X线质无关。", "tr": "X线“质=半价层/硬度”、“量=mAs”，质与量的表示物理量是高频考点，二者不可互换。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1016", "t": "单选题", "s": "结合上述情景，X线源至探测器距离由100 cm增至200 cm，其他条件不变时，探测器处照射量变为原来的", "o": {"A": "1/2", "B": "1/4", "C": "1/8", "D": "1/16", "E": "不变"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-101", "kp": "距离平方反比定律", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (1)距离的衰减", "ex": "【为什么对】对点源而言，照射量与距离的平方成反比（平方反比定律）。距离由100 cm增至200 cm，变为原来的2倍，则照射量变为原来的1/2²=1/4，故选B。【为什么错】A 1/2是距离比值的倒数，未按平方计算。C 1/8无物理依据。D 1/16按4倍距离或更高次方错误计算。E“不变”与平方反比规律明显矛盾。", "tr": "平方反比定律“剂量∝1/d²”：距离加倍剂量减为1/4，防护理“远距离操作”即基于此定律。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1017", "t": "单选题", "s": "结合上述情景，使入射X线强度衰减为原来一半所需的吸收物质厚度称为", "o": {"A": "十分之一价层", "B": "半价层（HVL）", "C": "质量衰减系数", "D": "线性衰减系数", "E": "有效原子序数"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-102", "kp": "半价层定义", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (2)物质吸收的衰减", "ex": "【为什么对】半价层（HVL）是指使入射X线强度衰减至原来一半时所需吸收体的厚度，是表示X线穿透力（质）的重要参数，故选B。【为什么错】A十分之一价层是使强度衰减至1/10所需的厚度，数值大于半价层。C质量衰减系数是μ/ρ，反映单位质量物质的衰减能力。D线性衰减系数μ是单位厚度物质对X线的衰减率。E有效原子序数是反映化合物等效原子序数的参数，与厚度无关。", "tr": "半价层（HVL，衰减一半）与十分之一价层（TVL，衰减到1/10）的数值关系HVL≈0.3×TVL，防护屏蔽计算中极易混用。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1018", "t": "单选题", "s": "某X线束在铅中的半价层为0.25 mm，穿过1.0 mm铅板后，X线强度约为原来的", "o": {"A": "1/4", "B": "1/8", "C": "1/16", "D": "1/32", "E": "1/64"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-103", "kp": "半价层衰减计算", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (2)物质吸收的衰减", "ex": "【为什么对】每经过一个半价层厚度，X线强度衰减为原来的一半。铅板厚度1.0 mm含半价层个数为1.0/0.25=4个，透过的强度为原来的（1/2）⁴=1/16，故选C。【为什么错】A 1/4对应2个半价层（0.5 mm）。B 1/8对应3个半价层（0.75 mm）。D 1/32对应5个半价层（1.25 mm）。E 1/64对应6个半价层（1.5 mm）。", "tr": "衰减计算“I=I₀/2ⁿ，n=厚度/半价层”，先求半价层个数再作2的幂次，顺序与单位换算是易错点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1019", "t": "单选题", "s": "结合上述情景，人体各主要组织成分对X线衰减能力由强到弱的正确顺序是", "o": {"A": "骨＞脂肪＞肌肉＞气体", "B": "骨＞肌肉＞脂肪＞气体", "C": "肌肉＞骨＞脂肪＞气体", "D": "脂肪＞肌肉＞骨＞气体", "E": "气体＞脂肪＞肌肉＞骨"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-104", "kp": "人体组织对X线的衰减顺序", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (5)人体对X线的衰减", "ex": "【为什么对】X线在物质中的衰减主要取决于物质的有效原子序数、密度与厚度。骨骼含钙（原子序数高）且密度大，衰减最强；肌肉密度略高于脂肪；气体密度最低、衰减最弱，故顺序为骨＞肌肉＞脂肪＞气体，故选B。【为什么错】A脂肪在肌肉之前错误，肌肉有效原子序数与密度均略高于脂肪。C骨应排第一而非第二。D脂肪大于骨错误。E气体衰减最弱应排最后。", "tr": "衰减顺序“骨＞肌肉＞脂肪＞气体”与CT值顺序一致（骨最高、气体最低），记忆顺序时勿将脂肪与肌肉位置颠倒。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1020", "t": "单选题", "s": "MRI成像中最常用、含量最丰富的磁性原子核是", "o": {"A": "¹²C", "B": "¹⁶O", "C": "¹H（氢质子）", "D": "²³Na", "E": "³¹P"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-101", "kp": "MRI常用磁性原子核", "ch": "二、医学物理基础 → 5.磁学基础知识 → (2)磁性和非磁性原子核", "ex": "【为什么对】氢原子核（¹H）自旋量子数为1/2、在人体内含量最丰富（水、脂肪等）、旋磁比高，产生的MR信号最强，是MRI成像的主力原子核，故选C。【为什么错】A ¹²C质量数和原子序数均为偶数，自旋量子数为零，属非磁性核。B ¹⁶O同理为非磁性核。D ²³Na虽有磁性，但含量低、信号弱。E ³¹P虽有磁性，但灵敏度低于¹H，仅用于特殊研究。", "tr": "磁性原子核判据是自旋量子数≠0（质量数为奇数的核多为磁性核）；¹²C、¹⁶O是典型的非磁性核，与¹H形成对比考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1021", "t": "单选题", "s": "在静磁场中，对氢质子施加频率等于拉莫尔频率的90°射频脉冲后，宏观纵向磁化矢量发生的变化是", "o": {"A": "增大为原来的两倍", "B": "减小为零，同时产生横向磁化分量", "C": "保持不变", "D": "反向翻转180°", "E": "消失且不产生横向磁化"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-102", "kp": "90°射频脉冲作用", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】当射频脉冲频率与质子进动频率（拉莫尔频率）相同时发生共振，90°脉冲使宏观纵向磁化矢量整体翻转90°、纵向分量降为零，同时各质子相位趋于一致形成横向磁化分量，故选B。【为什么错】A射频脉冲不增加纵向磁化大小。C磁化矢量被明显扰动，不会保持不变。D反向翻转180°是180°反转脉冲的作用，90°脉冲只翻转90°。E90°脉冲必然产生横向磁化分量，否则无法接收MR信号。", "tr": "90°脉冲（纵向归零、产生横向磁化）与180°反转脉冲（纵向反转）的作用方向不同，序列设计中二者常交替使用。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1022", "t": "单选题", "s": "纵向弛豫（T1弛豫）的准确定义是", "o": {"A": "横向磁化衰减至37%所需的时间", "B": "纵向磁化恢复至其平衡值63%所需的时间", "C": "纵向磁化完全恢复所需的时间", "D": "质子相位重聚所需的时间", "E": "质子进动一周所需的时间"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-103", "kp": "T1弛豫定义", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】90°脉冲后纵向磁化从零按指数规律恢复，其时间常数T1定义为纵向磁化恢复到平衡值63%（即1-e⁻¹≈63%）所需的时间，又称自旋-晶格弛豫时间，故选B。【为什么错】A横向磁化衰减至37%是T2的定义。C完全恢复需约5倍T1，定义用63%而非完全恢复。D相位重聚与自旋回波技术相关，非T1定义。E质子进动周期与拉莫尔频率相关，与弛豫无关。", "tr": "T1（纵向恢复63%）与T2（横向衰减37%）两个百分比是经典易混点，“恢复63%/衰减37%”必须成对记忆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1023", "t": "单选题", "s": "横向弛豫（T2弛豫）的物理本质是", "o": {"A": "质子将能量传递给周围晶格", "B": "质子间相位失相干（自旋-自旋相互作用）导致横向磁化指数衰减", "C": "质子进动频率加快", "D": "纵向磁化重新恢复", "E": "磁场不均匀导致的质子频率离散"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-104", "kp": "T2弛豫本质", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】90°脉冲后横向磁化因质子间局部磁场差异导致的相位失相干（自旋-自旋相互作用）而按指数规律衰减，其时间常数即T2，故选B。【为什么错】A将能量传递给周围晶格是T1（自旋-晶格）弛豫的机制。C进动频率由旋磁比与磁场强度决定，与弛豫过程无关。D纵向磁化恢复是T1弛豫过程。E磁场不均匀导致的是T2*衰减（含T2与磁场不均匀性），不是T2的本质，且T2*≤T2。", "tr": "T2=自旋-自旋（相位失相干），T1=自旋-晶格（能量释放）；T2*再叠加磁场不均匀性，三者的层级关系（T2*≤T2）是难点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1024", "t": "单选题", "s": "在T1WI上，组织T1时间越长，其信号强度的变化规律是", "o": {"A": "信号越低", "B": "信号越高", "C": "信号不变", "D": "与T1时间无关", "E": "信号先升高后降低"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-105", "kp": "T1WI信号与T1时间关系", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】T1WI通过短TR、短TE突出组织间T1差异。TR一定时，T1长的组织在给定TR内纵向磁化恢复少，信号低；T1短的组织恢复快，信号高。即“长T1→低信号”，故选A。【为什么错】B“T1越长信号越高”与T1WI规律相反。C信号强度明确依赖T1差异。D T1WI就是利用T1差异成像，不能无关。E信号随T1单调变化，无先升后降。", "tr": "T1WI“长T1低信号、短T1高信号”（如脑脊液低信号、脂肪高信号）；T2WI则“长T2高信号”，两个权重的信号方向相反，最易混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1025", "t": "单选题", "s": "将吸收剂量换算为当量剂量时所乘的、反映辐射类型生物效应大小的因子是", "o": {"A": "组织权重因子", "B": "辐射权重因子（WR）", "C": "剂量率因子", "D": "照射时间因子", "E": "能量吸收因子"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-RADB-101", "kp": "辐射权重因子", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (1)生物效应", "ex": "【为什么对】当量剂量H=吸收剂量D×辐射权重因子WR，WR反映不同辐射类型（X、γ、α、中子等）的相对生物效应强弱，故选B。【为什么错】A组织权重因子用于由当量剂量计算有效剂量（E=ΣHT×WT），反映不同组织器官的辐射敏感性。C剂量率因子不是标准剂量学概念。D照射时间因子属防护时间概念的延伸，不是换算因子。E能量吸收因子非规范术语。", "tr": "辐射权重因子WR（射线类型）与组织权重因子WT（器官敏感性）分别在当量剂量、有效剂量的计算中使用，两个“权重因子”最易混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1026", "t": "单选题", "s": "国际单位制中，当量剂量与有效剂量的单位是", "o": {"A": "戈瑞（Gy）", "B": "希沃特（Sv）", "C": "伦琴（R）", "D": "库仑每千克（C/kg）", "E": "焦耳（J）"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-101", "kp": "当量剂量单位", "ch": "二、医学物理基础 → 7.X线防护与测量 → (6)吸收剂量测量", "ex": "【为什么对】当量剂量与有效剂量的国际单位均为希沃特（Sv），1 Sv=1 J/kg（经权重因子修正），故选B。【为什么错】A戈瑞（Gy）是吸收剂量的单位，1 Gy=1 J/kg，未经辐射权重修正。C伦琴（R）是照射量的旧专用单位。D库仑每千克（C/kg）是照射量的国际单位。E焦耳是能量单位，不是剂量单位。", "tr": "剂量单位三件套：吸收剂量Gy、当量/有效剂量Sv、照射量C/kg（旧单位R），“Gy与Sv混用”是常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1027", "t": "单选题", "s": "防护材料“铅当量”的物理含义是", "o": {"A": "材料的密度大小", "B": "与该材料厚度具有相同屏蔽效果所需的铅厚度（以mmPb表示）", "C": "材料的实际物理厚度", "D": "材料的原子序数", "E": "材料的导电率"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-102", "kp": "铅当量概念", "ch": "二、医学物理基础 → 7.X线防护与测量 → (3)外照射屏蔽防护", "ex": "【为什么对】铅当量是指某防护材料在一定条件下对X（γ）射线的屏蔽能力相当于一定厚度铅的屏蔽能力，用等效铅厚度（mmPb）表示，如1 mm铅当量即与该厚度材料的屏蔽效果等价于1 mm铅，故选B。【为什么错】A密度仅是影响屏蔽的因素之一，不等于铅当量。C实际物理厚度不等于等效屏蔽厚度，不同材料所需厚度不同。D原子序数影响衰减能力，但不直接等于铅当量。E导电率与辐射屏蔽无关。", "tr": "铅当量是“等效屏蔽厚度”而非实际厚度：同等屏蔽效果下，混凝土、钡砖的物理厚度远大于铅，铅当量统一了屏蔽能力的度量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-1028", "t": "多选题", "s": "关于X线的物理特性及其临床应用的对应关系，正确的描述有", "o": {"A": "穿透作用—X线摄影成像的基础", "B": "荧光作用—透视检查的基础", "C": "电离作用—辐射剂量测量的基础", "D": "感光作用—胶片摄影的基础", "E": "X线无生物效应，对人体组织无损伤作用"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-107", "kp": "X线特性与应用", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (1)X线的本质与特性", "ex": "【为什么对】A穿透作用是X线穿过不同密度物质的能力，是摄影成像的基础，正确。B荧光作用使荧光物质发光，是透视的基础，正确。C电离作用使物质电离，是电离室等剂量测量的基础，正确。D感光作用使胶片银盐感光形成潜影，是胶片摄影的基础，正确。【为什么错】E X线具有明确的生物效应，可引起细胞损伤、突变甚至致癌，既是放疗工具也是防护对象，说“无生物效应”错误。", "tr": "X线四大效应“穿透、荧光、电离、感光”各有应用对应，生物效应是防护与放疗的基础，“X线无生物效应”是常识性陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1029", "t": "多选题", "s": "关于连续X线能谱特征的描述，正确的有", "o": {"A": "具有明确的最短波长（λmin）", "B": "波长在λmin以上呈连续分布", "C": "强度最大的波长约为最短波长的2倍", "D": "连续X线由韧致辐射（轫致辐射）产生", "E": "提高管电压可使谱峰向短波方向移动"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-109", "kp": "连续X线能谱特征", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】A连续谱存在由管电压决定的最短波长λmin=1.24/U（kV）nm，正确。B短于λmin的波长不存在，λmin以上波长连续分布，正确。D连续X线由高速电子韧致辐射产生，正确。E提高管电压使λmin缩短、谱峰及平均能量移向短波（硬）方向，正确。【为什么错】C连续谱中强度最大处的波长约为最短波长的1.5倍（约1.5λmin），而不是2倍，错误。", "tr": "连续谱“强度峰≈1.5λmin”与“最短波长λmin”是两个不同参数，倍率记忆错误是最常见陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1030", "t": "多选题", "s": "关于特征X线的描述，正确的有", "o": {"A": "特征X线的波长取决于靶物质的原子序数", "B": "管电压必须超过相应壳层的激发电压才能产生", "C": "特征X线的能量与管电流大小无关", "D": "特征X线在总X线输出中所占比例较小", "E": "特征X线波长随管电压升高而变短"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-110", "kp": "特征X线特点", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】A特征X线光子能量等于跃迁壳层间能级差，能级差取决于靶物质原子序数（越高则能级差越大、波长越短），正确。B需管电压超过该壳层激发电压才能击出该壳层电子，正确。C特征X线能量与管电流无关（管电流只影响产生数量），正确。D常规钨靶X线管中特征X线仅占输出的小部分（诊断能量范围内），正确。【为什么错】E特征X线波长由靶物质能级差决定，是固定线系谱，与管电压无关；管电压升高只改变连续谱及能否激发更高壳层，错误。", "tr": "特征X线“波长固定、由靶物质决定”，管电压只决定能否产生（阈值），这是“特征X线随管电压变化”类陷阱的考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1031", "t": "多选题", "s": "关于X线强度的空间分布（阳极效应），正确的描述有", "o": {"A": "沿X线管长轴方向，阴极侧X线强度大于阳极侧", "B": "垂直于靶面方向的X线强度最大", "C": "阳极效应在管电压较高时更加明显", "D": "阳极效应在管电压较低时更加明显", "E": "可把受检体较厚部位置于阴极侧以利用强度梯度"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-111", "kp": "X线强度空间分布", "ch": "二、医学物理基础 → 1.X线的产生 → (5)X线强度的空间分布", "ex": "【为什么对】A阳极效应（足跟效应）使阴极侧射线经靶面自吸收较少、强度大于阳极侧，正确。B垂直于靶面方向的射线穿透靶层最薄、强度最大，正确。D管电压低时X线质软、靶面自吸收相对更显著，阳极效应更明显，正确。E利用阴极侧强束补偿厚部、阳极侧弱束照顾薄部，可改善照片两端密度均匀性，正确。【为什么错】C管电压较高时X线变硬、靶面自吸收减弱，阳极效应反而不明显，说“高kV时更明显”错误。", "tr": "阳极效应“低kV更明显”（软线自吸收强）与“阴极侧强度大”是两个独立考点，方向或条件记反即错。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1032", "t": "多选题", "s": "结合上述情景，影响X线质（硬度）的主要因素包括", "o": {"A": "管电压", "B": "滤过", "C": "阳极靶物质原子序数", "D": "管电流", "E": "高压波形（脉动程度）"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQUAL-102", "kp": "X线质的影响因素", "ch": "二、医学物理基础 → 3.X线强度及X线质与量 → (3)X线质", "ex": "【为什么对】A管电压越高，X线光子能量越高、质越硬，正确。B滤过（尤其附加滤过）吸收低能软线、使平均能量升高、质变硬，正确。C靶物质原子序数影响特征X线能量与连续谱强度分布，进而影响质，正确。E高压波形脉动大则X线质软，恒压（三相或高频）输出时质较硬，正确。【为什么错】D管电流只决定X线量（光子数），不改变光子能量谱，不影响X线质，错误。", "tr": "“管电流只管量、管电压管质”：凡将管电流列入影响X线质的选项均为错误项，这是质与量考点的经典陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1033", "t": "多选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，关于X线在物质中的衰减规律，正确的描述有", "o": {"A": "窄束（准直）X线衰减遵循指数规律I=I₀e⁻⁽μx⁾", "B": "宽束X线含大量散射线，衰减不严格遵循指数规律", "C": "半价层与线性衰减系数关系为HVL=0.693/μ", "D": "质量衰减系数μ/ρ与物质密度大小无关", "E": "气体对X线的衰减能力大于骨骼"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-105", "kp": "X线衰减基本规律", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (2)物质吸收的衰减", "ex": "【为什么对】A窄束单能X线的衰减符合指数定律I=I₀e⁻⁽μx⁾，正确。B宽束X线因散射线混入，实测衰减偏离指数规律（较指数衰减慢），正确。C由I=I₀e⁻⁽μx⁾令I=I₀/2可得HVL=ln2/μ≈0.693/μ，正确。D质量衰减系数μ/ρ为线性衰减系数除以密度，与物质密度无关、仅与能量和原子序数相关，正确。【为什么错】E气体密度极低、衰减最弱，骨骼含钙、密度高、衰减最强，顺序应为骨＞肌肉＞脂肪＞气体，说“气体衰减大于骨”错误。", "tr": "窄束指数衰减与宽束含散射线偏离指数规律、质量衰减系数与密度无关，三个概念是衰减规律的核心，气体与骨的衰减顺序勿颠倒。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1034", "t": "多选题", "s": "关于连续X线在人体内衰减及其影像学影响的描述，正确的有", "o": {"A": "低能光子优先被吸收，射线在深部逐渐“变硬”（射束硬化）", "B": "射束硬化可产生CT的杯状（cupping）伪影", "C": "人体对X线的衰减取决于有效原子序数、密度与厚度", "D": "乳腺X线摄影采用低kV以增强光电效应、提高软组织对比", "E": "提高管电压可明显提高骨与软组织的对比度"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-106", "kp": "连续X线衰减特点与应用", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】A多能X线穿过物质时低能部分先被吸收，剩余射线平均能量升高即“变硬”，正确。B射束硬化使中心区光子能量高于边缘，产生CT的杯状伪影（中心CT值偏低），正确。C衰减强度与物质有效原子序数、密度、厚度密切相关，正确。D低kV时光电效应占比增大，而光电效应突出原子序数差异，可提高乳腺（脂肪-腺体）软组织对比，正确。【为什么错】E提高管电压使X线质变硬、光电效应减少、康普顿散射为主，骨与软组织间的对比度反而下降，说“明显提高骨软组织对比”错误。", "tr": "kV越高对比越低（硬线、康普顿为主），kV越低越利于软组织和骨对比（光电效应突出），这一“反向关系”是摄影能量选择的依据。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1035", "t": "多选题", "s": "结合上述情景，关于磁性与非磁性原子核的条件及MR信号，正确的描述有", "o": {"A": "自旋量子数不为零的原子核具有磁性", "B": "质量数为奇数的原子核多为磁性核", "C": "质量数和原子序数均为偶数的原子核自旋量子数为零", "D": "原子核带正电荷且自旋时产生磁矩", "E": "只有氢原子核能产生MR信号"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-106", "kp": "磁性原子核条件", "ch": "二、医学物理基础 → 5.磁学基础知识 → (2)磁性和非磁性原子核", "ex": "【为什么对】A原子核的自旋量子数I≠0时具有自旋磁矩，为磁性核，正确。B质量数为奇数的原子核I为半整数（1/2、3/2等），多为磁性核，正确。C质量数、原子序数均为偶数时I=0、为非磁性核，正确。D质子带正电荷，原子核自旋产生环形电流从而具有磁矩，正确。【为什么错】E除氢外，³¹P、²³Na、¹³C等磁性核同样能产生MR信号，只是灵敏度低、临床少用，说“只有氢核能产生”错误。", "tr": "磁性核判据“质量数奇数→有磁性、质量数+原子序数均偶→无磁性”；“只有¹H能成像”是绝对化陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "磁学基础知识", "页": 34}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1036", "t": "多选题", "s": "关于质子进动与拉莫尔频率，正确的描述有", "o": {"A": "质子进动（旋进）频率与主磁场强度成正比", "B": "拉莫尔方程ω₀=γB₀中的γ为旋磁比", "C": "1.5 T场强下氢质子的拉莫尔频率约63.9 MHz", "D": "3.0 T场强下氢质子的拉莫尔频率约127.8 MHz", "E": "拉莫尔频率随射频脉冲能量的增大而升高"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-107", "kp": "拉莫尔频率定量关系", "ch": "二、医学物理基础 → 5.磁学基础知识 → (3)共振和磁共振现象", "ex": "【为什么对】A质子进动频率正比于主磁场强度，是MR成像的基本关系，正确。B拉莫尔方程ω₀=γB₀中γ为旋磁比，氢质子γ/2π≈42.58 MHz/T，正确。C 42.58×1.5≈63.9 MHz，正确。D 42.58×3.0≈127.8 MHz，正确。【为什么错】E拉莫尔频率仅由旋磁比与主磁场强度决定，射频脉冲只能通过共振条件（频率匹配）激发质子，不能改变进动频率，错误。", "tr": "氢质子旋磁比42.58 MHz/T要记牢：场强1.5 T对应约64 MHz、3.0 T对应约128 MHz，计算与射频频率设定直接相关。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1037", "t": "多选题", "s": "关于人体各组织弛豫时间（T1、T2）及其成像信号特点，正确的描述有", "o": {"A": "同一组织的T2时间一般小于或等于T1时间", "B": "脂肪的T1较短，在T1WI上呈高信号", "C": "脑脊液T1长、T2长，在T2WI上呈高信号", "D": "组织含水增多时T1与T2一般均延长", "E": "所有组织的T1与T2时间均相等"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-108", "kp": "组织弛豫时间比较", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】A横向弛豫一般快于纵向弛豫，故T2≤T1，正确。B脂肪分子运动适中、T1短，T1WI呈高信号，正确。C脑脊液含水量高，T1长、T2长，T2WI呈高信号，正确。D含水量增多使质子环境更接近自由水，T1、T2均延长（如水肿），正确。【为什么错】E不同组织T1、T2差异很大，正是这些差异构成MRI组织对比的基础，“所有组织相等”错误。", "tr": "“T2≤T1”与“含水多T1T2均延长”是弛豫规律的常考点；不同组织弛豫时间的差异本身就是成像对比的来源。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1038", "t": "多选题", "s": "结合上述情景，关于电离辐射的确定性效应（组织反应），正确的描述有", "o": {"A": "存在剂量阈值", "B": "效应的严重程度随剂量增大而加重", "C": "效应的发生概率随剂量增大而增大", "D": "皮肤红斑、放射性白内障属于确定性效应", "E": "低于阈值的剂量不会产生该效应"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-RADB-102", "kp": "确定性效应特征", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (1)生物效应", "ex": "【为什么对】A确定性效应存在剂量阈值，低于阈值不发生，正确。B剂量超过阈值后，效应严重程度随剂量增大而加重（如皮肤损伤程度），正确。D皮肤红斑、脱发、放射性白内障、造血抑制等均属确定性效应，正确。E阈值以下不发生该效应，是确定性效应的基本特征，正确。【为什么错】C“发生概率随剂量增大而增大”是随机性效应（致癌、遗传效应）的特征，确定性效应的特征是严重程度随剂量加重而非发生概率增大，错误。", "tr": "确定性效应“有阈值、重程度”，随机性效应“无阈值、增概率”，二者的核心区别（阈值与剂量关系）是反复命题点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1039", "t": "多选题", "s": "根据国家标准GB 18871—2002，我国放射工作人员与公众剂量限值的正确描述有", "o": {"A": "放射工作人员连续5年的年平均有效剂量不超过20 mSv", "B": "放射工作人员任何单一年份的有效剂量不超过50 mSv", "C": "放射工作人员眼晶体的年当量剂量限值为150 mSv", "D": "公众个人年有效剂量限值为1 mSv", "E": "放射工作人员年有效剂量限值为100 mSv"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-103", "kp": "剂量限值标准", "ch": "二、医学物理基础 → 7.X线防护与测量 → (4)我国放射卫生防护标准", "ex": "【为什么对】A职业照射连续5年平均年有效剂量不超过20 mSv，正确。B任何一年不超过50 mSv，正确。C职业照射眼晶体年当量剂量限值150 mSv，正确。D公众个人年有效剂量限值为1 mSv，正确。【为什么错】E放射工作人员个人剂量限值采用“5年平均20 mSv/年、任一年不超过50 mSv”，100 mSv并非我国标准中的个人年有效剂量限值，错误。", "tr": "剂量限值“职业20/50、公众1”：5年平均20 mSv与任何一年50 mSv必须成对记忆，公众1 mSv易与职业数值混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1040", "t": "多选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，关于外照射防护“时间、距离、屏蔽”三要素的实际应用，正确的描述有", "o": {"A": "增大与辐射源的距离可显著降低剂量（平方反比）", "B": "缩短受照时间可成比例减少累积剂量", "C": "屏蔽厚度增加一倍，透过剂量一定减为原来的一半", "D": "铅、混凝土、水是常用的屏蔽材料", "E": "防护屏的屏蔽效果可用铅当量进行评价"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-104", "kp": "外照射防护三要素应用", "ch": "二、医学物理基础 → 7.X线防护与测量 → (2)外照射防护一般措施", "ex": "【为什么对】A距离防护利用平方反比定律，增大距离剂量显著下降，正确。B剂量与受照时间成正比，缩短时间即减少剂量，正确。D铅、混凝土、水（尤其对中子水是良好慢化剂）为常用屏蔽材料，正确。E屏蔽能力以铅当量统一评价，正确。【为什么错】C只有屏蔽厚度恰好增加一个半价层时透过剂量才减半；屏蔽厚度与透过剂量之间按指数规律衰减，“厚度翻倍剂量必减半”不成立，错误。", "tr": "屏蔽衰减是指数规律（每增一个半价层减半），不是线性比例；“厚度翻倍剂量减半”是貌似合理的错误表述。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1041", "t": "多选题", "s": "结合上述情景，关于照射量与吸收剂量的测量及其量纲，正确的描述有", "o": {"A": "照射量仅适用于X、γ射线在空气中的测量", "B": "照射量的国际单位为库仑每千克（C/kg）", "C": "吸收剂量的国际单位为戈瑞（Gy）", "D": "1 Gy=1 J/kg", "E": "照射量适用于任何介质中任何类型的辐射"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-105", "kp": "照射量与吸收剂量", "ch": "二、医学物理基础 → 7.X线防护与测量 → (5)照射量测量", "ex": "【为什么对】A照射量定义基于X、γ射线对空气的电离效应，仅适用于空气（或等效空气介质），正确。B照射量国际单位C/kg（旧单位伦琴R），正确。C吸收剂量单位Gy（旧单位rad），正确。D吸收剂量为单位质量物质吸收的能量，1 Gy=1 J/kg，正确。【为什么错】E照射量只能在X、γ射线与空气中定义和测量，不适用于其他介质（如组织、水）及α、β、中子等辐射，说“任何介质任何辐射”错误。", "tr": "照射量“只限X、γ射线+空气”，是量程最窄的辐射量；吸收剂量适用于任何介质、任何辐射（Gy），两者适用条件差异是考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-1042", "t": "多选题", "s": "结合上述情景，某X线机房外检测发现关注点剂量率超标，下列降低墙外关注点剂量的措施中正确的有", "o": {"A": "增加机房防护墙的铅当量厚度", "B": "缩短机房内曝光时间", "C": "增大辐射源至墙外关注点的距离", "D": "在源与墙之间加设移动铅防护屏", "E": "将机房整体迁至更高楼层以降低剂量"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-106", "kp": "机房屏蔽降剂量措施", "ch": "二、医学物理基础 → 7.X线防护与测量 → (3)外照射屏蔽防护", "ex": "【为什么对】A增加防护墙铅当量属于屏蔽防护，可降低透过剂量，正确。B缩短曝光时间减少单位时间剂量累积与机房门开启期间泄漏，正确。C增大源至关注点距离利用平方反比定律降低剂量率，正确。D移动铅屏可直接遮挡原发射线与散射线，是临时性的有效屏蔽手段，正确。【为什么错】E机房楼层位置不改变辐射源与关注点的几何关系，也不改变屏蔽需求，“迁移楼层即可从根本上降低剂量”缺乏物理依据，错误。", "tr": "降剂量必须落到“时间、距离、屏蔽”三要素上，任何脱离物理规律的措施（如改楼层）都是无效干扰项。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U02-2043a", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，乳腺X线摄影采用低管电压（约25～32 kV）的主要目的是", "o": {"A": "缩短曝光时间", "B": "提高光电效应比例，增强乳腺软组织的X线对比", "C": "降低散射线产生", "D": "减少患者运动伪影", "E": "提高X线穿透能力"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-108", "kp": "乳腺摄影低kV的物理原理", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】乳腺内脂肪与腺体组织有效原子序数相差很小，需利用光电效应放大原子序数差异才能显示对比。低管电压时X线光子能量低，光电效应比例显著增大（∝1/E³），乳腺软组织对比度提高，故选B。【为什么错】A曝光时间由管电流与剂量控制决定，与低kV无关。C散射线主要与照射野、厚度及kV有关，低kV不降低散射线。D运动伪影与曝光时间相关，与kV无关。E低kV反而使X线穿透力下降，这正是需要压迫配合的原因。", "tr": "低kV摄影“借光电效应放大Z差异”是乳腺高对比的物理基础，“低kV提高穿透力”是方向性陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2043b", "t": "单选题", "s": "低管电压使X线穿透力下降、受照剂量偏高，乳腺摄影中最常用的补偿措施是", "o": {"A": "增大阳极靶面焦点面积", "B": "选用钼（或铑）滤过并加压压迫乳腺、缩短曝光时间", "C": "去除滤线栅以减少吸收", "D": "增大照射野提高宽容度", "E": "将管电流提高至设备极限"}, "d": "难", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-112", "kp": "低kV摄影的剂量补偿", "ch": "二、医学物理基础 → 1.X线的产生 → (4)影响X线产生的因素", "ex": "【为什么对】低kV下X线质软、穿透弱，需通过乳腺加压（压缩）减薄乳腺厚度、降低散射线与入射剂量，并选用钼/铑滤过优化能谱、配以足够管电流缩短曝光时间，这是乳腺摄影的常规综合措施，故选B。【为什么错】A增大焦点面积与剂量补偿无关，反而降低空间分辨率。C去除滤线栅虽减少射线吸收，但会明显增加散射线、降低对比度，得不偿失。D增大照射野会增加散射线与不必要的照射。E管电流提高至设备极限会带来热容量与剂量控制问题，并非规范补偿手段。", "tr": "乳腺摄影剂量补偿是“压迫+滤过+合适mA”的组合拳，单靠某一项（如无限提管电流）不是规范做法。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2043c", "t": "单选题", "s": "结合上述情景，乳腺X线摄影中加压（压迫）乳腺的主要目的是", "o": {"A": "减小乳腺厚度，降低散射线并减少受照剂量", "B": "增加乳腺的血流灌注", "C": "便于乳腺病变的定位标记", "D": "提高摄影管电压", "E": "扩大有效照射野"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-107", "kp": "乳腺摄影压迫的目的", "ch": "二、医学物理基础 → 7.X线防护与测量 → (1)放射防护基本原则", "ex": "【为什么对】加压使乳腺厚度减小，一方面降低散射线产生、提高对比度，另一方面减少入射剂量并缩短曝光时间，是乳腺摄影质量与剂量平衡的关键措施，故选A。【为什么错】B压迫减少而非增加血流。C定位标记与压迫无直接关系。D压迫并不改变管电压设置。E压迫缩小乳腺厚度分布，不扩大照射野。", "tr": "压迫的四大收益“减薄、降散、减量、防动”：注意压迫是减小厚度而非常规意义上“固定”，其剂量学意义是核心考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2044a", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，颅脑CT中因骨与软组织对多能X线衰减差异导致的条带状低密度伪影，最常见的成因是", "o": {"A": "呼吸运动伪影", "B": "射束硬化（低能光子被颅骨优先吸收）", "C": "探测器通道损坏", "D": "金属植入物伪影", "E": "部分容积效应"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-107", "kp": "射束硬化伪影成因", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】颅骨含钙、密度高，多能X线穿过颅骨时低能部分被优先吸收，出射射线“变硬”（平均能量升高），导致邻近脑组织（尤其两骨板之间）出现条带状低密度伪影，即射束硬化伪影，故选B。【为什么错】A呼吸运动伪影多见于胸腹部，颅脑扫描无呼吸运动干扰。C探测器通道损坏产生环形伪影。D金属植入物伪影呈星芒状高密度条带，本例无金属物。E部分容积效应出现在高密度界面的层面间平均效应，不呈条带状骨旁低密度。", "tr": "射束硬化伪影“骨旁条带低密度”（颅底、岩骨旁、椎体旁）与金属伪影“星芒状”形态不同，成因均与能谱衰减有关但表现各异。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2044b", "t": "单选题", "s": "结合上述情景，为减轻上述射束硬化伪影对基底节区观察的影响，下列措施中最有效的是", "o": {"A": "增大扫描层厚", "B": "采用射束硬化校正算法（骨校正）", "C": "降低扫描管电压", "D": "增大扫描螺距", "E": "延长每层扫描时间"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-108", "kp": "射束硬化伪影校正", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (3)连续X线在物质中的衰减特点", "ex": "【为什么对】现代CT通过射束硬化校正算法（如骨校正、迭代重建中的物理模型校正）对多能谱衰减进行补偿，能显著减轻颅底、椎体旁射束硬化伪影，故选B。【为什么错】A增大层厚加重部分容积效应，不能减轻射束硬化。C降低管电压使X线更软、骨吸收更突出，伪影反而加重。D增大螺距提高扫描速度，与射束硬化校正无关。E延长扫描时间增加辐射剂量且不校正伪影。", "tr": "射束硬化伪影的对策是“校正算法”（骨校正/迭代重建）而非降低kV或加大层厚，降低kV反而加重低能光子被骨吸收的现象。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2045a", "t": "单选题", "s": "【病例】患者女性，42岁，头痛伴视物模糊就诊，行颅脑MRI检查。技师需选择能清晰显示脑脊液信号、辅助区分囊性病变与实性占位的序列，并注意弛豫时间对信号强度的影响。 颅脑MRI中，脑脊液在T2WI上的信号特点是", "o": {"A": "低信号", "B": "高信号", "C": "无信号", "D": "中等信号", "E": "与脂肪信号相同的短T1高信号"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-109", "kp": "脑脊液T2WI信号", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】脑脊液几乎为纯水，T2时间很长，在T2WI上呈显著高信号，这是MRI中“水呈高信号”的典型表现，故选B。【为什么错】A低信号是脑脊液在T1WI上的表现（T1长）。C脑脊液有明确信号，不会无信号。D中等信号描述不准确，T2WI上脑脊液为明显高信号。E脂肪为短T1、T2中等，T2WI上呈中等偏高信号，脑脊液与之信号并不相同。", "tr": "脑脊液“T1WI低信号、T2WI高信号”（长T1、长T2），两个权重下的信号方向相反，是MRI信号判读的基础考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2045b", "t": "单选题", "s": "为鉴别脑内含液囊性病变与实性占位，最常用的序列组合是", "o": {"A": "T1WI与T2WI联合判读", "B": "仅轴位T1WI", "C": "仅轴位DWI", "D": "仅轴位T2*WI", "E": "仅三维时间飞跃法MRA"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-110", "kp": "囊性病变与实性占位鉴别序列", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】含液囊性病变（如囊肿）为长T1长T2，T1WI呈低信号、T2WI呈均匀高信号，与脑脊液信号一致；实性占位T1WI为等低信号、T2WI为等或稍高信号且不均匀。联合T1WI与T2WI的信号特征即可可靠区分二者，故选A。【为什么错】B仅T1WI上液体与部分实性病变均呈低信号，无法区分。C DWI反映弥散受限，不能作为常规鉴别手段。D T2*WI对磁化效应敏感，主要用于出血与钙化显示。E MRA为血管成像，与囊实性鉴别无关。", "tr": "囊性病变“T1低、T2均匀高、与脑脊液同信号”，实性病变“T2不均匀等稍高”，两序列联合的信号模式是鉴别核心。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2046a", "t": "单选题", "s": "【病例】在X线物理与成像基础理论中，关于下列表述正确的是。 结合上述情景，评价X线机房屏蔽墙效果时，墙外测量最常使用的辐射量是", "o": {"A": "照射量率（或空气比释动能率）", "B": "放射性活度", "C": "核素半衰期", "D": "入射光子总数", "E": "线性能量转移（LET）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-108", "kp": "机房屏蔽检测辐射量", "ch": "二、医学物理基础 → 7.X线防护与测量 → (5)照射量测量", "ex": "【为什么对】X线机屏蔽验收时，通常用照射量率或空气比释动能率（及相应的吸收剂量率）在墙外关注点测量，与限值标准（剂量率）直接比较，故选A。【为什么错】B放射性活度（Bq）描述放射源衰变速率，适用于放射性核素而非X线机。C半衰期描述核素衰变快慢，与屏蔽评估无关。D光子总数不反映剂量学后果。E LET描述辐射线质（能量沉积密度），不用于屏蔽效果的直接测量。", "tr": "机房检测测“率”（照射量率/剂量率），活度与半衰期是核医学概念，勿将X线机当作放射性核素源来测量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2046b", "t": "单选题", "s": "若墙外关注点剂量率超标且无法增厚防护墙，最可行的降剂量方案是", "o": {"A": "增大源与关注点距离并延长曝光时间", "B": "增大源与关注点距离并缩短曝光时间", "C": "增大照射野面积", "D": "改用更高管电压扫描", "E": "增大毫安秒（mAs）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-109", "kp": "距离与时间的联合防护", "ch": "二、医学物理基础 → 7.X线防护与测量 → (2)外照射防护一般措施", "ex": "【为什么对】依据外照射防护三要素，增大源与关注点距离（平方反比降低剂量率）与缩短曝光时间（降低累积剂量）联合使用，可在不增厚墙体的情况下使剂量降到限值以下，故选B。【为什么错】A延长曝光时间会增加累积剂量，与降剂量目标相反。C增大照射野增加散射线与剂量。D更高管电压增加输出剂量率。E增大mAs增加曝光量，方向完全相反。", "tr": "防护“时间短、距离远、屏蔽厚”：任何“延长时间、增大mAs、提高kV”的选项都与降剂量目标相悖，是明显干扰项。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2047", "t": "案例分析题", "s": "患者男性，55岁，腰椎退变复查，行腰椎正位X线摄影。技师根据影像放大率及投照要求将焦点-胶片距离（FFD）由100 cm调整为140 cm。在球管输出条件不变的条件下，若要维持照片密度基本不变，需要同步调整曝光参数。此时管电流时间乘积（mAs）应调整为原来的约", "o": {"A": "0.5倍", "B": "0.7倍", "C": "1.4倍", "D": "2.0倍", "E": "1.2倍"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-109", "kp": "距离变化时的mAs补偿", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (1)距离的衰减", "ex": "【为什么对】照片密度与到达胶片的X线量成正比，而X线量与距离平方成反比。FFD由100 cm增至140 cm，到达胶片的剂量率降为原来的（100/140）²≈0.51，为维持相同密度需将mAs补偿为原来的1/0.51≈1.96倍，即约2.0倍，故选D。【为什么错】A 0.5倍是距离比值的平方小于1的错误方向，FFD增大应增加而非减少mAs。B 0.7倍约为距离比值的0.71倍，与平方反比规律不符。C 1.4倍为距离比值本身，未按平方计算。E 1.2倍与平方补偿不符。", "tr": "mAs补偿按“距离平方反比”：FFD增至1.4倍，mAs应增至约2倍（1.4²≈2），只按比例不按平方是常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2048", "t": "案例分析题", "s": "某介入诊疗操作中，技师需要站在远离X线源的位置进行床边监测。已知距X线源（视为点源）2 m处的空气吸收剂量率为1 mGy/h，若技师改在距源4 m处站位观察，忽略空气吸收及其他因素，该位置的剂量率约为", "o": {"A": "0.5 mGy/h", "B": "0.25 mGy/h", "C": "0.125 mGy/h", "D": "2 mGy/h", "E": "4 mGy/h"}, "d": "中", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-110", "kp": "距离防护的剂量计算", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (1)距离的衰减", "ex": "【为什么对】按距离平方反比定律，剂量率与距离平方成反比。距离由2 m增至4 m（2倍），剂量率降为原来的1/2²=1/4，即1 mGy/h×1/4=0.25 mGy/h，故选B。【为什么错】A 0.5 mGy/h是按距离一次方反比（1/2）计算的结果，未用平方。C 0.125 mGy/h为1/8，对应距离3倍以上或额外因素。D 2 mGy/h与4 mGy/h均为距离增大剂量率反而升高的错误方向。", "tr": "距离防护是平方反比而非一次方反比，“距离翻倍剂量减为1/4”必须按平方记忆，减半是常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2049", "t": "案例分析题", "s": "患者男性，40岁，左膝关节外伤后肿痛，临床需同时评估骨质有无骨折及周围软组织有无肿胀，行左膝关节X线摄影。技师拟选择合适的管电压以兼顾骨骼与软组织的显示。此时选用中等管电压（约60～70 kV）的物理依据是", "o": {"A": "管电压越高，骨与软组织对比度越大", "B": "中等管电压下光电效应与康普顿散射相互平衡，骨骼、软组织与脂肪的密度差异均可较好显示", "C": "管电压越低，散射线越少、剂量越低", "D": "中等管电压时X线穿透力达到最大", "E": "管电压与组织对比度没有任何关系"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XINT-109", "kp": "管电压与组织对比度的关系", "ch": "二、医学物理基础 → 2.X线的本质及与物质的相互作用 → (2)X线与物质的相互作用", "ex": "【为什么对】管电压较低时光电效应占优，突出原子序数差异，利于骨与软组织对比；管电压较高时康普顿散射为主，各组织差异缩小。中等管电压使光电效应与康普顿效应达到平衡，骨、软组织、脂肪的密度差异均能在照片上较好显示，故选B。【为什么错】A管电压越高，光电效应越少、组织间对比越差，方向相反。C降低kV并不直接减少散射线（散射线与照射野、厚度关系更大），且剂量补偿需要额外措施。D中等kV不是穿透力最大状态，管电压越高穿透力越强。E管电压是决定X线质与组织对比的核心因素，“无关系”错误。", "tr": "kV与对比的“反比”关系（高kV低对比、低kV高对比）是能量选择核心，中等kV平衡兼顾是四肢摄影的常用选择。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2050", "t": "单选题", "s": "结合上述情景，患者男性，45岁，复查颅脑MRI。科室新装机为3.0 T，此前设备为1.5 T。技师需要在3.0 T设备上重新设置T1WI序列参数以利用场强优势。关于3.0 T相对于1.5 T的物理特性，正确的认识是", "o": {"A": "组织T1时间总体延长，信噪比更高，灰白质T1对比通常更好", "B": "组织T1时间缩短，组织对比明显变差", "C": "氢质子的旋磁比增大", "D": "质子进动频率不变", "E": "可直接沿用1.5 T的全部序列参数而无须调整"}, "d": "易", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-111", "kp": "场强对弛豫与信噪比的影响", "ch": "二、医学物理基础 → 5.磁学基础知识 → (4)核磁弛豫", "ex": "【为什么对】场强升高使氢质子热平衡宏观磁化增大，信噪比提高；组织T1时间随场强升高而总体延长，但不同组织延长程度不同，灰质与白质的T1对比通常在3.0 T更优，故选A。【为什么错】B场强升高使T1延长而非缩短，且对比并不变差。C旋磁比是原子核固有属性，与场强无关。D质子进动频率（拉莫尔频率）随场强升高而成正比增大（3T约127.8 MHz）。E场强改变后须调整TR、SAR、频率等参数，直接沿用1.5 T参数是不安全的做法。", "tr": "场强升高“信噪比升、T1延长、进动频率升、旋磁比不变”，四个变化方向各不相同，“旋磁比随场强变化”是典型陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2051", "t": "案例分析题", "s": "某放射技师长期在介入导管室参与心血管介入操作，科室为其配备个人剂量计并建立剂量档案，每季度进行监测与记录。依据GB 18871—2002《电离辐射防护与辐射源安全基本标准》，该技师连续5年个人剂量监测结果应满足的年平均有效剂量限值为", "o": {"A": "1 mSv", "B": "10 mSv", "C": "20 mSv", "D": "50 mSv", "E": "150 mSv"}, "d": "难", "c": "应用", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-110", "kp": "职业照射年剂量限值", "ch": "二、医学物理基础 → 7.X线防护与测量 → (4)我国放射卫生防护标准", "ex": "【为什么对】依据GB 18871—2002，放射工作人员连续5年内的年平均有效剂量不超过20 mSv，且任何单一年份不超过50 mSv，故选C。【为什么错】A 1 mSv为公众个人年有效剂量限值，不适用于放射职业人员。B 10 mSv无标准依据。D 50 mSv是任何单一年份的限值，而非5年平均值。E 150 mSv为职业眼晶体年当量剂量限值，属局部器官限值。", "tr": "职业照射“连续5年平均20 mSv”与“任一年不超过50 mSv”成对出现，与公众1 mSv、眼晶体150 mSv三个数值构成标准考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2052", "t": "单选题", "s": "结合上述情景，某X线机房设计时需用铅板对初级射线束进行屏蔽，设计要求使透过铅板的X线强度衰减至入射强度的1/16。已知该能量条件下铅的半价层（HVL）为0.5 mm，则所需铅板的总厚度约为", "o": {"A": "0.5 mm", "B": "1.0 mm", "C": "2.0 mm", "D": "4.0 mm", "E": "0.125 mm"}, "d": "易", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XATT-111", "kp": "半价层求屏蔽厚度", "ch": "二、医学物理基础 → 4.X线的吸收与衰减 → (2)物质吸收的衰减", "ex": "【为什么对】每经过一个半价层，强度衰减为原来的1/2。要求衰减至1/16=（1/2）⁴，即需要4个半价层厚度，4×0.5 mm=2.0 mm，故选C。【为什么错】A 0.5 mm为1个半价层，仅衰减至1/2。B 1.0 mm为2个半价层，衰减至1/4。D 4.0 mm为8个半价层，衰减至1/256，超出设计要求。E 0.125 mm为1/4个半价层，衰减更弱。", "tr": "由“剩余比例求半价层个数”再乘HVL厚度，1/16=2⁻⁴对应4个HVL，指数运算与倍数混淆是易错点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2053", "t": "案例分析题", "s": "乳腺X线摄影机采用钼（Mo）靶X线管，其K系特征X线能量约为17.5 keV（Kα）与19.6 keV（Kβ）。技师利用钼的特征X线作为主要工作射线进行乳腺摄影。选择钼靶特征X线的物理依据是", "o": {"A": "钼K系特征X线能量较低，恰好处于乳腺组织光电效应占优的能量区间，可提高软组织对比度", "B": "钼K系特征X线能量在所有医用靶材中最高，穿透力最强", "C": "钼的原子序数高于钨，特征X线能量最高", "D": "特征X线能量越高，软组织对比度越好", "E": "钼靶X线管只产生特征X线，不产生连续X线"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XGEN-113", "kp": "钼靶特征X线在乳腺摄影中的应用", "ch": "二、医学物理基础 → 1.X线的产生 → (3)连续X线与特征X线", "ex": "【为什么对】乳腺为软组织，脂肪与腺体原子序数差异极小。钼K系特征X线能量低（约17～20 keV），处于乳腺组织光电效应占优的能量区间，光电效应放大原子序数差异，从而显著提高软组织对比度，故选A。【为什么错】B钼的K系能量（17～20 keV）远低于钨（约59～69 keV），并非最高。C钼的原子序数（42）低于钨（74），特征X线能量也低于钨。D能量越高软组织对比越差（光电效应减少），方向相反。E钼靶X线管同样产生连续X线（韧致辐射），只是特征X线相对较强，说“只产生特征X线”错误。", "tr": "钼靶“低能特征线匹配乳腺光电效应区”是乳腺摄影的关键设计；钨靶特征线能量高、不适于软组织摄影，靶材与用途的对应关系是考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2054", "t": "案例分析题", "s": "某科研项目拟利用MRI技术在体观察肿瘤的磷代谢状态，选用³¹P核进行磁共振波谱（MRS）研究。技师需确认³¹P核具备产生MR信号的基本物理条件。³¹P核能产生MR信号所必需的条件是", "o": {"A": "³¹P核的自旋量子数不为零（³¹P质量数为奇数）", "B": "³¹P核的原子序数为零", "C": "³¹P核不产生核磁矩", "D": "³¹P核的质量数为偶数", "E": "³¹P核不带正电荷"}, "d": "中", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-MAGN-112", "kp": "³¹P核的磁性条件", "ch": "二、医学物理基础 → 5.磁学基础知识 → (2)磁性和非磁性原子核", "ex": "【为什么对】³¹P质量数为31（奇数），自旋量子数为1/2，属磁性原子核，可产生MR信号，故选A。【为什么错】B原子序数不可能为零，且MR信号与自旋量子数而非原子序数直接相关。C³¹P自旋时产生核磁矩，这是产生信号的前提。D质量数为奇数（31）而非偶数；质量数与原子序数均为偶数的核自旋为零。E³¹P核带正电荷，带电与自旋共同产生磁矩。", "tr": "磁性核判据是“质量数为奇数→自旋量子数≠0”；³¹P（31，奇数）、¹H（1，奇数）均为磁性核，¹²C、¹⁶O为偶数非磁性核。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-2055", "t": "案例分析题", "s": "医学物理师使用标准自由空气电离室（标准电离室）对某X线机输出进行照射量校准。校准需严格按照射量的定义进行测量。标准自由空气电离室测量照射量的基本原理是", "o": {"A": "收集X线电离空气产生的电荷，由电荷量与空气质量之比计算照射量", "B": "测量X线照射后物质的温度升高量", "C": "测量X线使荧光物质发出的可见光亮度", "D": "测量X线穿过物质后的衰减程度", "E": "测量X线使胶片形成的黑化度"}, "d": "难", "c": "分析", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-PRO-111", "kp": "自由空气电离室测量原理", "ch": "二、医学物理基础 → 7.X线防护与测量 → (5)照射量测量", "ex": "【为什么对】照射量的定义是X、γ射线在空气中产生的同符号离子总电荷量与空气质量之比。自由空气电离室收集X线在确定空气质量内电离产生的电荷，据此直接计算照射量，是照射量的标准测量装置，故选A。【为什么错】B测温升属量热法，用于吸收剂量测量。C荧光亮度用于透视与增感屏原理，不用于照射量定量。D衰减程度测量用于评估屏蔽与X线质，非照射量测量。E胶片黑化度属感光测量，受胶片性能影响，非标准照射量测量。", "tr": "自由空气电离室“收集电荷、除以空气质量”严格对应照射量定义；量热法（测温升）对应吸收剂量，测量原理与辐射量的对应是考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线的防护与测量", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U02-9101", "t": "单选题", "s": "关于电离辐射的确定性效应与随机性效应，下列说法正确的是", "o": {"A": "确定性效应有剂量阈值、严重程度随剂量增加而加重；随机性效应无阈值、发生概率随剂量增加而升高", "B": "随机性效应存在明确的剂量阈值", "C": "确定性效应不存在剂量阈值", "D": "两类效应均存在剂量阈值", "E": "两类效应均无阈值且严重程度随剂量线性增加"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "KP-BU-2-9101-正高", "kp": "确定性效应与随机性效应", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害 → (补充)辐射生物效应", "ex": "【为什么对】A 正确：确定性效应（如放射性白内障、皮肤红斑、造血抑制）存在剂量阈值，超过阈值后严重程度随剂量增加；随机性效应（致癌、遗传效应）无阈值，发生概率（非严重程度）随剂量线性增加。【为什么错】B、C、D、E 均混淆了两类效应与阈值的关系。", "tr": "易把\"随机性效应\"与\"阈值\"错误绑定，牢记随机效应无阈值、讲概率。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U02-9201", "t": "单选题", "s": "X 线质（硬度）主要取决于", "o": {"A": "管电压（kV）", "B": "管电流（mA）", "C": "曝光时间", "D": "焦点大小", "E": "滤过厚度无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-9201", "kp": "X线质", "ch": "二、医学物理基础 → 3.X线强度及X线质与量", "ex": "【为什么对】X 线质反映穿透力，主要由管电压 kV 决定。\n【为什么错】管电流与曝光时间决定量而非质。", "tr": "X线质由管电压决定。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U02-9202", "t": "单选题", "s": "X 线量（强度）与下列哪项成正比关系最密切", "o": {"A": "mAs", "B": "kV 单独", "C": "焦点尺寸", "D": "滤过", "E": "距离单独"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-XQTY-9202", "kp": "X线量", "ch": "二、医学物理基础 → 3.X线强度及X线质与量", "ex": "【为什么对】X 线量（曝光量）与 mAs（管电流×时间）成正比。\n【为什么错】kV 影响质与量但非线性；mAs 是最直接量度。", "tr": "X线量随mAs成正比。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "X线强度、X线质与X线量", "页": 32}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U02-9203", "t": "单选题", "s": "电离辐射的确定性效应（组织反应）的特点是", "o": {"A": "存在剂量阈值", "B": "无阈值随机发生", "C": "仅遗传效应", "D": "仅远期癌效应", "E": "与剂量率无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-9203", "kp": "确定性效应", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害", "ex": "【为什么对】确定性效应有剂量阈值，超过阈值才发生且严重程度随剂量增加。\n【为什么错】随机效应无阈值。", "tr": "确定性效应有阈值。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U02-9204", "t": "单选题", "s": "下列哪项属于电离辐射的随机性效应", "o": {"A": "白内障", "B": "皮肤红斑", "C": "癌症与遗传效应", "D": "造血抑制", "E": "不育"}, "d": "中", "c": "理解", "m": "专业知识", "u": "二", "un": "医学物理基础", "kpid": "UNIT-02-BIOE-9204", "kp": "随机性效应", "ch": "二、医学物理基础 → 6.电离辐射对人体的危害", "ex": "【为什么对】随机性效应（癌、遗传效应）无阈值，发生概率随剂量增加但严重程度不随剂量变化。\n【为什么错】白内障/红斑/造血抑制等多为确定性效应（有阈值）。", "tr": "随机效应=癌/遗传。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学物理基础", "节": "电离辐射对人体的危害", "页": 36}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U03-0101", "t": "单选题", "s": "X线管采用线状焦点原理以兼顾高负荷与小焦点。若某旋转阳极X线管实际焦点在阳极—阴极方向上的长度为6.0 mm，阳极靶面倾角为16°，则该方向上有效焦点的投影长度约为", "o": {"A": "0.60 mm", "B": "1.7 mm", "C": "3.0 mm", "D": "6.0 mm", "E": "21.8 mm"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-001", "kp": "线状焦点原理与有效焦点计算", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (3)X线管的焦点", "ex": "【为什么对】线状焦点原理的核心是把实际焦点（电子撞击靶面的真实区域）做成细长条，再借助倾斜靶面向管轴方向投影，从而在保持较大受热面积的同时获得小的有效焦点。计算式为有效焦点长度＝实际焦点长度×sinθ。本题 6.0 mm×sin16°≈6.0×0.276≈1.66 mm，约 1.7 mm。【为什么错】A 是把正确结果又缩小了约10倍，属数量级错误。C 相当于按 sin30°≈0.5 计算，误用了倾角数值。D 未作投影换算，把实际焦点直接当成有效焦点。E 把乘法误作除法（6.0÷sin16°≈21.8），方向完全相反——倾斜投影只会使焦点变小，不可能变大。", "tr": "只有沿阳极—阴极方向（长轴）的尺寸被 sinθ 压缩，垂直方向的宽度不变，故有效焦点近似为方形；命题常把\"实际焦点\"与\"有效焦点\"互换，或把乘 sinθ 改成除 sinθ。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0102", "t": "共用题干题", "s": "结合上述情景，临床摄影可观察到X线束沿阳极—阴极方向强度分布不均，靠近阳极侧的影像密度偏低，此即阳极效应（足跟效应）。其产生的根本原因是", "o": {"A": "阴极灯丝发射的电子束在管内发生偏转", "B": "管套窗口的附加滤过板对阳极侧射线的选择性吸收", "C": "倾斜的阳极靶面对其自身深部产生的X线存在吸收（靶面自吸收），朝阳极侧出射的射线被更多衰减", "D": "阳极高速旋转使焦点沿轨道移动而产生的强度调制", "E": "阳极侧靶物质的原子序数高于阴极侧"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-002", "kp": "阳极效应（足跟效应）的机制", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】X线在靶面一定深度内产生，向阳极侧出射时需穿过更长的靶物质路径，被靶自身吸收得更多；靶面倾角越小，这段路径越长，阳极侧强度衰减越明显。因此近阳极端射线强度低、近阴极端强度高，最大强度约位于中心线偏阴极侧。【为什么错】A 电子束在聚焦罩约束下指向靶面，其偏转不是强度分布不均的原因。B 附加滤过板对整个射野是均匀作用的，不会造成阳极—阴极方向的梯度。D 阳极旋转是为分散热量，焦点轨道旋转不改变射野内的空间强度分布。E 靶面为同一种钨（钨铼合金）材料，不存在两侧原子序数差异。", "tr": "足跟效应随倾角减小、照射野增大、焦—片距缩短而更明显；把原因误记为\"滤过\"或\"电子偏转\"是常见失分点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03065", "gs": ""}, {"id": "ZG-U03-0103", "t": "共用题干题", "s": "结合上述情景，为改善影像密度的均匀性，技师可主动利用或抑制阳极效应。下列关于摆位与条件安排的表述，正确的有", "o": {"A": "胸椎正位摄影时将患者头端置于阳极侧、腰骶端置于阴极侧，使较厚部位获得更高的射线强度", "B": "股骨全长正位摄影时将股骨近端（较厚）置于阴极侧、膝端置于阳极侧", "C": "焦—片距（SID）增大时，阳极效应造成的密度不均将更加显著", "D": "在实际焦点不变的条件下，阳极靶面倾角越小，阳极效应越显著", "E": "适当缩小照射野、只使用射野中心区域，可减轻阳极效应对密度均匀性的影响"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-003", "kp": "阳极效应的临床摆位应用", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】A 胸椎上段薄、下段与腰骶交界厚，把厚部放在射线强度高的阴极侧可平衡密度。B 股骨近端软组织厚、膝端薄，同理厚部对阴极。D 倾角越小，靶面自吸收路径越长，阳极侧衰减越重，效应越显著。E 射野边缘处强度差最大，缩野后仅用中心区域，密度梯度自然减小。【为什么错】C 方向说反了：SID 增大后，同一探测器尺寸对应的张角变小，所用射线更集中于中心区，密度不均反而减轻。", "tr": "记忆口诀是\"厚部对阴极、薄部对阳极\"；C 项是最常见的反向陷阱——把\"距离越远越不均\"与平方反比定律混为一谈。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03065", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-0104", "t": "单选题", "s": "将旋转阳极X线管的靶面倾角由16°减小到12°，在实际焦点尺寸保持不变的条件下，其直接影响是", "o": {"A": "有效焦点增大，有效照射野也随之增大", "B": "有效焦点不变，但阳极热容量明显提高", "C": "有效焦点减小，阳极效应（足跟效应）随之减弱", "D": "有效焦点减小、几何模糊减少，但有效照射野缩小且阳极效应加重", "E": "有效焦点减小，同时X线管瞬时最大允许负荷同步提高"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-004", "kp": "阳极倾角对焦点、射野与负荷的影响", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (4)旋转阳极X线管", "ex": "【为什么对】有效焦点＝实际焦点×sinθ，倾角减小则有效焦点变小，几何模糊（半影）随之减少、锐利度提高；但倾角决定X线束的张角，倾角越小射线锥角越窄，可覆盖的探测器尺寸（有效照射野）越小，同时靶面自吸收路径变长使阳极效应加重。这正是乳腺X线管采用小倾角、通用摄影管采用12°~17°折中的原因。【为什么错】A 方向相反。B 热容量取决于阳极盘质量、材料与散热结构，与倾角无直接关系。C 阳极效应是加重而非减弱。E 实际焦点面积未变，焦点轨道承受的功率密度不变，最大允许负荷不会因倾角减小而提高。", "tr": "倾角是\"锐利度\"与\"照射野\"之间的取舍：小倾角＝小有效焦点＋小射野＋重足跟效应。E 项利用\"小焦点也能大负荷\"的模糊印象设陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0105", "t": "多选题", "s": "关于旋转阳极X线管的阳极热容量与瞬时最大允许负荷，下列表述正确的有", "o": {"A": "阳极热容量常用热单位（HU）表示，单相全波整流时 HU＝kV(峰值)×mA×s，三相或高频设备需乘以约1.35的换算系数", "B": "增大阳极盘直径、提高转速（由3000 r/min 提高至9000~10000 r/min）都可提高瞬时最大允许负荷", "C": "在阳极盘背面复合石墨层，主要用于增大阳极的热容量并改善辐射散热", "D": "靶面采用钨铼合金的首要目的是提高X线转换效率，而非延缓靶面龟裂", "E": "在同一支X线管上，曝光时间越长，所允许使用的管电流（mA）越大"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-005", "kp": "阳极热容量、散热率与管负荷特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】A 热单位是阳极蓄热能力的常用工程单位，三相/高频因波形接近恒压、平均电压高于单相有效值，需乘约1.35。B 盘径增大使焦点轨道周长增加、转速提高使单位面积受热时间缩短，两者都降低瞬时功率密度，从而提高允许负荷。C 石墨密度低、比热大、辐射发射率高，作为背衬可显著提高蓄热量与辐射散热能力。【为什么错】D 因果颠倒：钨的原子序数高保证转换效率，掺铼（约5%~10%）的主要目的是提高高温下的韧性、延缓靶面龟裂与粗糙化，从而延长管寿命。E 与管负荷特性曲线相反——曝光时间延长意味着能量持续输入，允许的管电流必须下降，故负荷特性曲线随时间下行。", "tr": "热容量（能装多少热，HU 或 kJ）与散热率（每分钟能散多少热，HU/min 或 kW）是两个独立指标，命题常将二者混为一谈。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0106", "t": "单选题", "s": "栅控X线管在阴极聚焦罩上增设了栅极，与普通X线管相比其工作原理与主要用途是", "o": {"A": "在栅极上施加负偏压使电子束被截止，从而实现毫秒级曝光通断，用于DSA脉冲曝光与快速连续摄影", "B": "在栅极上施加正偏压以增大管电流，用于提高乳腺摄影的X线输出量", "C": "通过栅极控制阳极转速，缩短曝光前的旋转启动时间", "D": "通过栅极滤除低能光子，使X线束硬化并降低皮肤剂量", "E": "通过栅极吸收被检者产生的散射线，从而替代滤线栅"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-006", "kp": "栅控X线管的原理与应用", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (7)特殊X线管", "ex": "【为什么对】栅控管在聚焦罩（栅极）与阴极间加上超过截止电压的负偏压时，空间电荷被推回、电子无法飞向阳极，管电流被瞬间切断；撤去负压则立即导通。由于开关在电子层面完成，通断时间可达毫秒级，且不依赖高压初级的接触器，因此适用于DSA脉冲曝光、心血管电影摄影和脉冲透视。【为什么错】B 正偏压并非其设计用途，乳腺机靠灯丝电流与曝光量控制输出。C 阳极转速由定子绕组的旋转磁场控制，与栅极无关。D 束硬化由固有滤过与附加滤过实现。E 抑制散射线依靠滤线栅、缩野和空气间隙，栅极位于管内，与散射线无关。", "tr": "\"栅控管的栅极\"与\"滤线栅\"仅一字之差却完全不同：前者控制管电流通断，后者位于患者与探测器之间去散射。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0107", "t": "共用题干题", "s": "结合上述情景，下列各类医用X线高压发生器，按输出电压纹波率由大到小排列，正确的是", "o": {"A": "三相十二脉冲＞三相六脉冲＞单相全波整流＞高频逆变", "B": "高频逆变＞三相六脉冲＞三相十二脉冲＞单相全波整流", "C": "三相六脉冲＞三相十二脉冲＞单相全波整流＞高频逆变", "D": "单相全波整流＞三相十二脉冲＞三相六脉冲＞高频逆变", "E": "单相全波整流＞三相六脉冲＞三相十二脉冲＞高频逆变"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-007", "kp": "高压发生器类型与电压纹波", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】纹波率反映输出直流电压的波动幅度：单相全波整流约100%，三相六脉冲约13%，三相十二脉冲约3.5%，高频（中频逆变）通常小于2%~4%，输出最接近恒定电压。故由大到小为单相全波＞三相六脉冲＞三相十二脉冲＞高频逆变。【为什么错】A、C 把三相十二脉冲或六脉冲排在最前，与其脉冲数越多、波动越小的规律相悖。B 把纹波最小的高频排在首位，完全颠倒。D 把六脉冲与十二脉冲的顺序对调——脉冲数多者纹波必定更小。", "tr": "记忆主线是\"脉冲数越多、频率越高，纹波越小\"；纹波大意味着低能软射线比例高、皮肤剂量高、线质重复性差。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03066", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-0108", "t": "共用题干题", "s": "结合上述情景，与三相十二脉冲高压发生器相比，高频（中频逆变）高压发生器所具备的优势包括", "o": {"A": "逆变频率多在20~100 kHz，输出接近恒定电压，线质稳定、曝光重复性好", "B": "相同管电压设定下有效光子能量提高、低能软射线所占比例下降，患者皮肤入射剂量相对降低", "C": "体积小、重量轻，便于装入移动X线机、床旁机与口腔科X线机", "D": "可实现毫秒级的 kV／mAs 闭环反馈控制，曝光时间短、剂量精度高", "E": "由于输出电压恒定、能谱纯净，可以省去X线管的固有滤过与附加滤过"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-008", "kp": "高频高压发生器的性能特点", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】A 工频交流先整流再由逆变电路升频至千赫兹级，经高压变压器与倍压整流后纹波极小。B 波形接近恒压意味着曝光全过程都工作在设定 kV 附近，软射线比例下降，皮肤剂量降低而影像信息不减。C 高频使变压器铁芯与绕组体积大幅缩小，是移动设备小型化的关键。D 微机对 kV 与 mAs 实时采样并闭环调节，可做到毫秒级精度，配合AEC提高一致性。【为什么错】E 固有滤过来自管壁、绝缘油与窗口，本身不可拆除；附加滤过（通常总滤过≥2.5 mm Al 当量）是国家标准强制要求，用于滤除对成像无贡献的软射线，与发生器类型无关，任何设备都不得省去。", "tr": "高频发生器\"减少软射线\"是相对意义上的能谱改善，绝不等于可以取消滤过；把辐射防护的强制要求当成可选项是典型的原则性错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03066", "gs": ""}, {"id": "ZG-U03-0109", "t": "共用题干题", "s": "结合上述情景，一名45岁女性行乳腺X线摄影，压迫后腺体厚度62 mm，腺体密度为致密型（ACR c 类）。为在可接受剂量下兼顾穿透力与软组织对比度，下列靶面／滤过组合中较为合理的是", "o": {"A": "Mo/Mo（钼靶＋30 μm 钼滤过）", "B": "Rh/Mo（铑靶＋钼滤过）", "C": "Mo/Rh 或 W/Rh（钼靶或钨靶＋铑滤过）", "D": "W/Mo（钨靶＋钼滤过）", "E": "Mo/Al（钼靶＋铝滤过）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-009", "kp": "乳腺X线机靶面与滤过组合的选择", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (13)乳腺X线机", "ex": "【为什么对】钼的特征X线为 Kα 17.5 keV、Kβ 19.6 keV，钼滤过的 K 吸收缘为20.0 keV，恰好把20 keV 以上的连续谱大幅削掉，形成17~20 keV 的准单能\"通带\"，适合薄的、脂肪型乳腺。对致密而较厚的乳腺，17~20 keV 穿透不足会导致曝光时间延长、剂量升高。铑滤过的 K 吸收缘为23.2 keV，可把通带上移至20~23 keV，线质变硬、穿透力增强，故 Mo/Rh、W/Rh（数字乳腺常用W/Rh、W/Ag）是致密厚乳腺的合理选择。【为什么错】A 适用于较薄或脂肪型乳腺，用于62 mm 致密腺体会造成剂量偏高、对比不足。B 铑靶特征线为20.2、22.7 keV，而钼滤过的 K 缘在20.0 keV，恰好把铑的特征线大量吸收，组合自相矛盾。D 钨靶主要靠连续谱，其特征线（约59、67 keV）远高于乳腺成像所需能区，再用20.0 keV 的钼滤过则把有用能段几乎截断，效率极低。E 铝没有合适的 K 吸收缘，无法形成准单能通带，能谱过宽、对比度差，不用于诊断性乳腺摄影。", "tr": "解题主线是\"滤过材料的 K 吸收缘决定通带上限\"；乳腺越厚越致密，越需要把通带上移（Mo→Rh→Ag）。切勿只背\"乳腺用钼靶钼滤过\"。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03056", "gs": ""}, {"id": "ZG-U03-0110", "t": "共用题干题", "s": "结合上述情景，关于全数字乳腺X线摄影设备的结构与技术特点，下列表述正确的有", "o": {"A": "采用双焦点设计，大焦点标称约0.3 mm 用于常规摄影，小焦点约0.1 mm 用于放大摄影", "B": "X线管窗口多采用铍窗，以减少对17~25 keV 低能光子的固有滤过", "C": "靶面倾角很小并将整个管轴倾斜安装，使射野的强射线侧对准胸壁缘，减少胸壁侧腺体漏摄", "D": "放大摄影时应同时使用活动滤线栅与空气间隙，两者联合去散射效果最佳", "E": "常规摄影使用活动滤线栅，栅比多为4∶1~5∶1，低于普通X线摄影所用栅比"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-010", "kp": "乳腺X线机的结构特点", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (13)乳腺X线机", "ex": "【为什么对】A 乳腺摄影对空间分辨率要求极高，常规位用0.3 mm 焦点，放大位（1.5~1.8倍）必须用0.1 mm 微焦点以控制几何模糊。B 铍的原子序数仅为4，对低能光子吸收极小，可最大限度保留17~25 keV 的有用能段。C 乳腺机把管轴倾斜并使射野强度较高的一侧对着胸壁，既符合胸壁侧组织较厚的需要，也保证胸壁缘不被漏摄。E 乳腺压迫后厚度小、散射线相对少，采用低栅比（4∶1~5∶1）的活动栅即可，栅比过高只会徒增剂量。【为什么错】D 放大摄影时被检乳腺被抬高、远离探测器，本身已形成足够的空气间隙来发散散射线；此时必须撤去滤线栅，否则栅吸收造成剂量大幅上升且无额外收益。", "tr": "\"放大摄影撤栅、用空气间隙\"是必考点；另一常错处是把乳腺栅比记成普通摄影的8∶1~12∶1。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03056", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-0111", "t": "共用题干题", "s": "结合上述情景，ICU 一名78岁男性，重症肺炎、经口气管插管机械通气中，深度镇静、无法搬动，需床旁胸部正位摄影复查气管插管深度与右颈内静脉置管位置。科室配备电池贮能式移动DR，管电压范围40~125 kV，最高输出功率32 kW，机器未配置滤线栅。病床两侧空间狭窄，患者可摇高床头呈半坐位，邻床相距约1.5 m。作为当班技师，下列技术处置最合理的是", "o": {"A": "采用60~70 kV 低千伏配合大 mAs，以增强肺纹理对比", "B": "在床垫下加装一块8∶1 固定滤线栅以去除散射线", "C": "采用110~125 kV 高千伏配合短曝光时间，缩小照射野至胸部范围，适当加大被检体与探测器的距离以形成空气间隙，并在呼吸机吸气末（潮气量峰值）触发曝光", "D": "把 SID 缩短至50 cm，以充分利用有限的输出功率", "E": "嘱患者深吸气后屏气20 s 以彻底消除运动伪影"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-011", "kp": "移动X线机床旁胸片的技术决策", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (11)移动X线机", "ex": "【为什么对】高千伏摄影可压缩纵隔与肺野之间过大的密度差，使纵隔内的插管、导管、椎体轮廓与含气肺野同屏可见，同时因光子穿透力强而所需 mAs 小、曝光时间短，能有效抑制心搏与机械通气造成的运动模糊，还能显著降低皮肤入射剂量。无滤线栅时靠严格缩野与空气间隙控制散射线。镇静患者不能配合屏气，选择呼吸机吸气末触发是唯一可行的呼吸控制方式。【为什么错】A 低千伏软射线绝大部分被胸壁吸收，皮肤剂量高、曝光时间长、运动模糊重，且难以穿透纵隔。B 床旁摄影无法保证栅焦距、栅中心与射线中心线的对准，极易发生栅切割形成条状密度不均，且贮能式移动机输出有限，加栅后剂量代价过大。D SID 缩短使入射皮肤剂量按平方反比急剧上升，心影与纵隔放大失真加重，插管位置判断受影响。E 深度镇静并机械通气的患者无法执行主动屏气指令，20 s 屏气本身也不现实。", "tr": "床旁摄影的三大原则：高千伏短时间、严格缩野加空气间隙、随呼吸机时相曝光；另需提醒周围人员避让或穿铅衣，操作者应距球管2 m 以上并避开射线束方向。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03063", "gs": ""}, {"id": "ZG-U03-0112", "t": "共用题干题", "s": "结合上述情景，关于X线管管套（管头）的结构与功能，下列描述错误的是", "o": {"A": "管套内充绝缘油，兼起高压绝缘与传导散热的作用", "B": "管套设有膨胀器（波纹管）以缓冲绝缘油受热膨胀，并可联动过热保护开关", "C": "管套壁内衬铅层用于限制漏射线，其漏射线量应符合国家标准规定的限值", "D": "安装在管套窗口外的遮线器（限束器）及其滤过板属于X线管的固有滤过", "E": "管套窗口材料、绝缘油与管壁玻璃共同构成X线管的固有滤过"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-012", "kp": "X线管管套的结构与固有滤过", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (6)X线管管套", "ex": "【为什么对】本题选错误项。固有滤过特指X线离开管套前必然穿过的、不可拆卸的部件，包括X线管管壁玻璃（或金属陶瓷窗）、绝缘油层与管套窗口材料；而遮线器（限束器）是安装在管套外部、可拆卸更换的附件，其内的滤过板属于附加滤过，故 D 的归类错误。【为什么错】A 绝缘油既承担数万伏至十余万伏的绝缘任务，又把阳极热量传导至管套外壳散出，表述正确。B 膨胀器（波纹管）为受热膨胀的油提供缓冲空间，其位移可推动微动开关实现过热保护，表述正确。C 除窗口外，管套壁内衬铅可把漏射线限制在标准规定的范围内，表述正确。E 这正是固有滤过的定义，表述正确。", "tr": "固有滤过＋附加滤过＝总滤过；诊断用X线机在80 kV 以上通常要求总滤过不低于2.5 mm Al 当量。把限束器滤过板归入固有滤过是高频错项。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03054", "gs": ""}, {"id": "ZG-U03-0113", "t": "单选题", "s": "口腔曲面体层（全景）X线机能把弯曲的牙弓展开成一幅平面影像，其实现这一效果的成像原理关键在于", "o": {"A": "采用大面积锥形束一次曝光后由计算机重建展开牙弓", "B": "X线管与探测器围绕患者做同步反向运动，经狭缝准直的窄束沿牙弓分段扫描，且旋转中心按牙弓形态连续移动", "C": "通过多次定点分段摄影后由软件自动拼接完成", "D": "利用双能量减影去除颈椎与颌骨的重叠", "E": "X线管固定不动，仅靠探测器高速往复摆动实现体层效果"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-013", "kp": "口腔曲面体层机的成像原理", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (12)口腔科X线机", "ex": "【为什么对】曲面体层属于狭缝扫描体层技术：X线管与探测器分置患者两侧、绕头部同步反向运动，射线被准直成垂直窄缝；由于牙弓并非正圆，机器让旋转中心沿一条与牙弓形态匹配的轨迹连续移动，使聚焦层面（体层域）始终贴合牙列，位于层面内的结构清晰成像，层面外结构因移动模糊而被抹除，最终把三维弯曲的牙弓展平为一幅连续图像。【为什么错】A 锥形束一次曝光后重建属于口腔 CBCT，不是曲面体层机的原理。C 曲面体层是连续同步扫描而非分段摄影后拼接，后者是DR长骨/全脊柱拼接技术。D 双能减影用于胸部骨与软组织分离，全景机不具备该功能。E 若X线管静止则无法形成体层效应，也无法沿牙弓展开。", "tr": "曲面体层（狭缝扫描＋移动旋转中心）与口腔 CBCT（锥束＋三维重建）是两种完全不同的设备，命题最常在此处混淆；层面外结构模糊与\"重影/伪影\"（如对侧下颌支、颈椎重叠）也常一并考查。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0114", "t": "单选题", "s": "CR 成像板（IP）在曝光后能把X线信息以潜影形式保存，并在激光扫描时释放出来。关于其光激励发光（PSL）过程，描述正确的是", "o": {"A": "X线使 BaFX∶Eu²⁺ 中的 Eu²⁺ 电离释放电子，电子被卤素空位（F 中心）俘获形成潜影；约633 nm 的激光激励使被俘获电子脱陷并与 Eu³⁺ 复合，发出约400 nm 的蓝紫色荧光", "B": "X线直接使荧光体发出400 nm 荧光，由光电倍增管即时采集成像", "C": "激光照射使荧光体产生热释光，其发射波长与激励光波长相同", "D": "X线在 IP 内产生电子—空穴对，并在外加偏置电场作用下被直接收集为电荷信号", "E": "激光使 Eu³⁺ 跃迁至激发态，退激时发出与激励光同波长的红色荧光"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-001", "kp": "IP 光激励发光（PSL）机制", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】IP 的荧光体为掺铕的氟卤化钡 BaFX∶Eu²⁺（X 为 Br、I、Cl）。曝光时 X 光子的能量使 Eu²⁺ 失去电子变为 Eu³⁺，逸出的电子被晶格中的卤素空位（F 色心）俘获于亚稳态，形成与入射剂量成正比的潜影，可稳定保存一段时间。读取时用 He-Ne 激光（633 nm）或半导体激光（约680 nm）逐点扫描，赋予被俘获电子足够能量脱陷，返回并与 Eu³⁺ 复合，多余能量以约390~400 nm 的蓝紫色光发出，经集光器与光电倍增管转为电信号后数字化。激励光与发射光波长明显分离，正是滤光片能滤掉激励光、只收集 PSL 光的前提。【为什么错】B 曝光瞬间的即时荧光属于增感屏的机制，CR 的关键恰恰是\"延迟发光\"。C 热释光需加热激发，是热释光剂量计的原理；且发射光若与激励光同波长将无法分离。D 直接产生电子—空穴对并由电场收集，是非晶硒直接转换平板探测器的机制。E 发射红光的说法与实际相反，PSL 光为蓝紫光。", "tr": "牢记\"红光激励、蓝紫光发射\"的波长关系；把 PSL 与增感屏即时荧光、热释光或直接转换混淆是最常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0115", "t": "多选题", "s": "关于 CR 成像板（IP）与 CR 系统的特性，下列表述正确的有", "o": {"A": "IP 的荧光体多为掺铕的氟卤化钡 BaFX∶Eu²⁺（X 代表 Br、I、Cl）", "B": "IP 上的潜影会随时间自行衰退（fading），曝光后应尽快读取，长时间放置会使信号明显下降", "C": "读取后需用强光照射（擦除灯）清除残留潜影，方可重复使用", "D": "IP 的X线吸收效率与探测量子效率（DQE）高于非晶硒平板探测器", "E": "CR 的空间分辨率主要由激光束斑直径、采样间隔以及荧光体层内的光散射共同决定"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-002", "kp": "IP 的组成、衰退与 CR 系统特性", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】A 这是 IP 荧光体的标准组成。B 被俘获在 F 中心的电子会自发脱陷，室温下曝光后8 h 约衰减10%~25%，因此规范要求尽快读取，急诊尤其如此。C 读取只释放部分被俘获电子，必须用强光二次擦除，否则残留潜影将在下一次成像中形成\"鬼影\"。E 激光束斑越细、采样间隔越小则分辨率越高，而荧光体层越厚，激光在层内散射越宽，分辨率越低——这正是 CR 在灵敏度与分辨率之间的固有矛盾。【为什么错】D 结论相反：IP 的荧光体层薄、光收集效率有限，且读取过程中存在光散射与光电倍增管噪声，其 DQE 明显低于平板探测器；这也是同等影像质量下 CR 所需剂量高于 DR 的根本原因。", "tr": "\"IP 可重复使用上万次\"不等于\"性能不衰减\"：反复使用后灵敏度下降、划痕增多，需定期做灵敏度与均匀性检测并淘汰老化板。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0116", "t": "单选题", "s": "在数字X线摄影中，非晶硒（a-Se）平板探测器与碘化铯＋非晶硅（CsI∶Tl／a-Si）平板探测器采用了不同的能量转换路径。关于非晶硒探测器的技术特点，正确的是", "o": {"A": "a-Se 先把X线转换为可见光再转换为电荷，转换环节多、锐利度较低", "B": "CsI∶Tl 为粉末状荧光体，光扩散明显，其锐利度低于 Gd₂O₂S∶Tb 增感屏", "C": "a-Se 的有效原子序数与 K 吸收缘决定其在70~120 kV 下的X线吸收效率高于 CsI", "D": "两者都必须通过光导纤维板与 CCD 耦合才能完成信号读出", "E": "a-Se 把X线直接转换为电子—空穴对，并在偏置电场作用下沿垂直方向收集，几乎不产生横向扩散，故 MTF 较高"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-003", "kp": "直接转换与间接转换平板探测器的比较", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】非晶硒属直接转换型：X线在硒层内直接激发出电子—空穴对，在数千伏偏置电场作用下电荷几乎垂直迁移到像素电极，横向扩散极小，因此调制传递函数（MTF）与空间分辨率优于间接转换型，这是其最突出的优势，也是其适合乳腺摄影等高分辨需求的原因。【为什么错】A 描述的是间接转换（CsI／a-Si）的路径，与 a-Se 恰好相反。B 结论颠倒：CsI∶Tl 为针状（柱状）晶体，像光纤一样把可见光约束在柱内向下传导，光扩散远小于粉末状 Gd₂O₂S∶Tb，锐利度更高。C 硒的原子序数仅34、K 吸收缘约12.7 keV，对常规摄影能量的吸收效率明显低于碘（Z＝53）和铯（Z＝55），所以在同等厚度与低剂量条件下 CsI 间接型的 DQE 通常更优。D 光导纤维板／CCD 耦合是早期 CCD 型数字摄影的读出方式，两种平板探测器均采用薄膜晶体管（TFT）阵列直接寻址读出。", "tr": "记忆分工：直接转换（a-Se）胜在分辨率，间接转换（CsI／a-Si）胜在X线吸收效率与低剂量 DQE；此外 a-Se 对温度较敏感、需控温，间接型对温度稳定性要求相对宽松。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0117", "t": "多选题", "s": "填充因子与探测量子效率（DQE）是评价平板探测器性能的两个关键量。下列表述正确的有", "o": {"A": "填充因子是指像素内有效感光（收集）面积占该像素总面积的比例", "B": "在相同工艺水平下缩小像素尺寸会使填充因子下降，导致量子利用率与信噪比降低", "C": "DQE 随空间频率升高而升高，故高频细节的信噪传递优于低频", "D": "直接转换型 a-Se 探测器的电荷收集电极可近似覆盖整个像素，其等效填充因子高于同等像素尺寸的间接转换型", "E": "DQE 只取决于探测器对X线量子的吸收效率，与噪声功率谱（NPS）和调制传递函数（MTF）无关"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-004", "kp": "填充因子与 DQE", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】A 这是填充因子的定义。间接转换像素内除光电二极管外，还必须容纳 TFT 开关、数据线与栅线，这些区域不感光。B 像素缩小时 TFT 与走线所占的绝对面积不能等比例缩小，感光区占比随之下降，落到探测器上的X线量子有更大比例未被有效利用，信噪比降低——这正是小像素高分辨探测器的工艺瓶颈。D 直接转换型无需光电二极管，像素电极可几乎铺满整个像素，等效填充因子接近100%，这是 a-Se 用于高分辨乳腺摄影的另一优势。【为什么错】C 方向相反：DQE 一般在零频或低频最高，随空间频率升高而下降，因为高频处 MTF 衰减而噪声相对不减。E DQE 由公式 DQE(f)＝MTF²(f)/[NPS(f)·q] 决定，同时受量子吸收效率、MTF 与 NPS 三者影响，说\"与 NPS 和 MTF 无关\"是概念性错误。", "tr": "DQE 是\"综合性能\"指标，MTF 只反映锐利度、NPS 只反映噪声；把 DQE 简化为\"吸收效率\"，或误记为随频率上升，都是典型失分点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0118", "t": "单选题", "s": "【病例】关于医用影像设备的结构与成像原理，下列描述符合实际的是。 结合上述情景，在 CR 图像后处理中，能够压缩影像的动态范围，使厚薄悬殊部位（如颈胸交界、纵隔与肺野）在同一幅图像上都获得良好显示的处理技术是", "o": {"A": "谐调处理——改变特性曲线的斜率与位置，调节影像整体的对比度与密度", "B": "空间频率处理——通过非锐化掩模强调或抑制特定频带的结构", "C": "动态范围压缩（组织均衡）处理——选择性抬高低信号区、压低高信号区，使密度差极大的部位同屏显示", "D": "能量减影处理——利用两种管电压曝光分离骨骼与软组织", "E": "时间减影处理——利用对比剂注入前后的图像相减"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-005", "kp": "CR 图像处理技术的分类", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (3)CR图像处理技术", "ex": "【为什么对】动态范围压缩（DRC，各厂家亦称组织均衡、层次均衡）先用低通滤波提取图像的大尺度背景亮度分布，再对该背景做非线性压缩后与原图合成，从而在保持局部对比度的前提下把极亮与极暗区域拉近，使颈胸交界、纵隔后区与含气肺野同时可读。【为什么错】A 谐调处理只是整体地平移或改变特性曲线的斜率，可调节整体黑白与反差，但不能在同一幅图内选择性地压缩局部亮度差。B 空间频率处理改变的是边缘锐利度与结构强调程度，属于对比细节增强，与动态范围压缩不是同一维度。D 能量减影需要双能曝光数据，用于骨与软组织分离，不能解决密度动态范围问题。E 时间减影用于血管造影，需要蒙片，与平片的动态范围无关。", "tr": "谐调处理调\"整体\"、空间频率处理调\"锐利度\"、动态范围压缩调\"局部亮度差\"，三者常被混答；注意组织均衡过度会造成图像发灰、伪边缘（黑边或晕环）。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0119", "t": "单选题", "s": "数字X线摄影中，曝光指数用于监控探测器接受的剂量水平。关于富士 S 值（sensitivity）与 IEC 62494 标准中的曝光指数 EI、偏差指数 DI，正确的是", "o": {"A": "S 值与探测器接受剂量成正比，S 值升高提示曝光过度", "B": "S 值与探测器接受剂量成反比，S 值升高提示曝光不足", "C": "IEC 标准的 EI 与探测器接受剂量成反比，EI 越大剂量越低", "D": "数字探测器宽容度大，曝光量适度增加不会带来明显剂量代价，故不必监控", "E": "偏差指数 DI 等于0，表示实际曝光量约为目标曝光量的两倍"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-006", "kp": "曝光指数与剂量监控", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (2)CR计算机系统配置", "ex": "【为什么对】富士 S 值的定义决定其与 IP 接受剂量成反比：剂量越低、读出信号越弱，系统需要更高增益，S 值就越大。因此 S 值升高提示曝光不足（图像颗粒噪声增大），S 值降低提示曝光过度。【为什么错】A 把反比关系记反了。C IEC 62494 规定的 EI 与探测器空气比释动能成正比，剂量越大 EI 越大，恰与 S 值相反——这正是两套指标最容易混淆之处。D 数字系统的宽容度只是掩盖了曝光过度的\"影像表现\"，患者剂量却实实在在增加，这种\"剂量蠕变\"正是必须监控曝光指数的原因。E DI＝10·lg(EI/EI_T)，DI 为0 表示实际曝光与目标曝光一致；DI 约＋3.0 才对应约两倍剂量，约－3.0 对应约一半剂量。", "tr": "\"S 值反比、EI 正比、DI 为0 达标\"必须一起记；数字摄影没有胶片那样的过曝变黑警示，只能靠曝光指数发现剂量蠕变。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0120", "t": "多选题", "s": "与 CR 系统相比，非晶硅平板 DR 系统所具有的优势包括", "o": {"A": "探测量子效率（DQE）更高，在获得同等影像质量时可降低患者受照剂量", "B": "无需 IP 的传送、读取与擦除环节，单次检查的工作流程时间明显缩短", "C": "平板 DR 的空间分辨率在多数情况下优于 CR 系统", "D": "响应线性好、动态范围宽，曝光宽容度大且信号与剂量关系稳定", "E": "动态平板探测器可兼做透视与点片，实现造影检查一体化"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-007", "kp": "DR 与 CR 的性能比较", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (4)DR基本结构及特性", "ex": "【为什么对】A CsI 柱状晶体层较厚且吸收效率高，光扩散被限制，DQE 明显高于 IP，是 DR 得以降低剂量的物理基础。B DR 曝光后数秒即可在控制台显示，省去了 IP 往返、扫描读取与强光擦除，检查通量大幅提升。D 平板探测器输出信号与入射剂量在很宽范围内保持线性，宽容度大且便于用曝光指数量化管理。E 动态平板具备高帧率读出能力，可完成透视、点片乃至数字胃肠与血管造影。【为什么错】C 表述过于绝对。空间分辨率取决于像素间距与光扩散：普通 DR 像素多为140~200 μm，而高分辨 CR（尤其乳腺专用 IP，采样间距可达50 μm）在极限分辨率上可以超过普通 DR。DR 的优势主要在 DQE、工作流与动态范围，而非绝对分辨率。", "tr": "\"DR 一定比 CR 清晰\"是常见误区；正确表述是同等剂量下 DR 的低对比可探测能力与 DQE 更优，极限空间分辨率需按具体像素间距比较。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0121", "t": "单选题", "s": "结合上述情景，某院使用 CR 系统开展床旁胸片。近一周多张影像上出现与激光扫描方向平行的、位置固定的规则细线状低密度（白色）伪影，更换患者与摄影条件后仍反复出现；追踪发现这些伪影总是伴随同一批次的两块 IP，同时这两块 IP 的图像颗粒感较其他 IP 明显增粗。工程师已用测试程序确认读出器的激光偏转与同步信号正常。作为技师，最合理的处置是", "o": {"A": "更换该批次老化或划伤的 IP，同时对读出器的导光板（集光器）与激光通路进行清洁除尘，处理后用均匀曝光的测试影像复核", "B": "提高摄影 mAs，用较高密度掩盖线状伪影", "C": "加大空间频率处理强度，使伪影在视觉上被弱化", "D": "把该 IP 置于强光下擦除30 min 后继续使用", "E": "缩小照射野后重新摄影，避开出现伪影的区域"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-008", "kp": "CR 系统伪影的识别与处理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (2)CR计算机系统配置", "ex": "【为什么对】与激光扫描方向平行的规则细线伪影，来源通常有二：一是 IP 表面划痕或污染，二是读出器集光器（导光板）入口积尘遮挡了 PSL 光的收集通路；本例伪影与特定 IP 绑定，提示以 IP 损伤为主，但读出光路清洁应同步完成以排除叠加因素。颗粒感增粗则提示这些 IP 反复使用后灵敏度下降、信噪比变差，已达到更换标准。处理后必须用均匀曝光影像复核，确认伪影消除并重新评估灵敏度一致性。【为什么错】B 提高 mAs 只是增加患者剂量，伪影是信号缺失所致，不会因整体密度升高而消失。C 空间频率处理反而会强化线状边缘，使伪影更醒目，且属掩盖问题而非解决问题。D 擦除只能清除残留潜影（鬼影），对划痕与灵敏度衰减无效，且伪影固定出现说明并非残影。E 缩野不能解决探测介质本身的缺陷，还可能漏摄解剖结构，属于本末倒置。", "tr": "判读伪影先分\"随患者变\"还是\"随硬件变\"：本例伪影绑定特定 IP 且位置固定，即为硬件源；若伪影随机出现且与位置无关，才考虑残影或散射因素。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0122", "t": "共用题干题", "s": "结合上述情景，某二级医院拟为急诊室配置一台悬吊式 DR，主要承担胸腹部、骨盆与四肢创伤摄影，兼顾夜间低剂量与快速工作流。厂家提供两种探测器方案：①碘化铯＋非晶硅间接转换探测器，像素间距140 μm；②非晶硒直接转换探测器，像素间距85 μm。两者价格相近，急诊室环境温度波动较大。作为设备论证组技师，最合理的选择与理由是", "o": {"A": "选②，因为 a-Se 空间分辨率高，可同时满足急诊各类需求且低剂量表现最佳", "B": "选①，因为 CsI 柱状晶体对60~120 kV 的X线吸收效率高，低剂量下 DQE 更优，适合急诊快速低剂量的大部位摄影；140 μm 像素对胸腹与骨盆已足够，且对环境温度波动的耐受性更好", "C": "选②，因为 a-Se 无温度依赖性，在温差较大的急诊环境中更稳定", "D": "选①，因为间接转换探测器的像素间距小于直接转换型，细节显示更好", "E": "两种方案的 DQE 与分辨率完全等价，只需比较采购价格与售后条款"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CRDR-009", "kp": "DR 探测器选型的技术论证", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】选型必须回到临床用途：急诊以胸腹、骨盆等大部位、低剂量、快节奏摄影为主，对极限空间分辨率的要求远低于乳腺；此时决定影像质量的是低剂量下的 DQE。CsI（Z 分别为53、55）对常规摄影能区吸收效率高，柱状晶体又抑制了光扩散，低剂量 DQE 优于 a-Se；140 μm 像素对应约3.6 lp/mm，完全满足胸腹骨盆需求，且数据量小、成像更快。此外 a-Se 的载流子迁移特性与暗电流受温度影响较大，需较严格的控温，急诊环境不利。【为什么错】A a-Se 对60~120 kV 光子的吸收效率低（Z＝34、K 缘约12.7 keV），低剂量下 DQE 并不占优，\"分辨率高\"不能替代\"量子利用率高\"。C 与事实相反，a-Se 恰恰对温度较敏感。D 与题干数据自相矛盾：①的像素间距140 μm 大于②的85 μm。E 两者在转换机制、吸收效率与 MTF 上差异明显，以\"完全等价\"为前提的采购论证不成立。", "tr": "\"像素越小越好\"是选型误区：像素缩小会降低填充因子、增加噪声与数据量，应按临床任务所需的极限分辨率来匹配，而不是一味求小。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03045", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-0123", "t": "单选题", "s": "螺旋 CT 之所以能够实现机架连续单向旋转并同步进床扫描，其决定性的硬件突破是", "o": {"A": "采用滑环（slip ring）以电刷或非接触方式在旋转部件与固定部件间传递电源和信号，取消了机架电缆往复缠绕的限制", "B": "采用了热容量更大的X线管", "C": "用固体探测器取代了气体探测器", "D": "引入了锥形束重建算法", "E": "配备了可连续移动的检查床"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-001", "kp": "滑环技术与螺旋扫描", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】非螺旋 CT 的机架靠电缆供电与传输数据，旋转一圈后必须反向回绕，形成\"扫描—回位—进床\"的间断模式。滑环用环状导电轨道配电刷（或非接触式电容/光电耦合）实现旋转部件与固定部件之间的持续电气连接，机架从此可以单向连续旋转，配合匀速进床即形成螺旋轨迹，这是螺旋 CT 诞生的根本前提。滑环又分低压滑环（传输数百伏交流电，高压发生器置于旋转机架内）与高压滑环两类，目前以低压滑环为主流，数据传输多采用光电或射频非接触方式。【为什么错】B 高热容量球管是支撑长时间连续扫描的必要条件，但不解决\"能否连续旋转\"的问题。C 探测器类型影响效率与响应速度，与连续旋转无关。D 锥形束重建是多排 CT 出现后为解决锥角问题而发展的算法，属于软件层面且晚于滑环。E 连续进床本身在滑环出现前无法与连续旋转配合，只是螺旋扫描的另一半条件而非突破点。", "tr": "区分\"螺旋扫描的前提（滑环）\"与\"螺旋扫描的表现（连续进床）\"；另需记住低压滑环把高压发生器搬进机架，避免了高压打火与绝缘难题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0124", "t": "多选题", "s": "结合上述情景，关于 CT 探测器的类型与性能，下列表述正确的有", "o": {"A": "气体探测器多采用高压氙气电离室，其X线吸收效率低于固体探测器，但通道间一致性好、稳定性高", "B": "掺镨硫氧化钆（Gd₂O₂S∶Pr）等稀土陶瓷或钨酸镉（CdWO₄）闪烁体配光电二极管构成固体探测器，转换效率高、余辉短，是多层螺旋 CT 的主流", "C": "探测器余辉（afterglow）过长会引起图像残影，并可能形成环状伪影", "D": "多排探测器的物理排数总是等于同时可采集的层数", "E": "气体探测器易于制成二维阵列，因此更适合用于多排螺旋 CT"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-002", "kp": "CT 探测器的类型与性能指标", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】A 氙气密度远低于固体闪烁体，即便加压至十几个大气压，量子吸收效率仍只有固体探测器的一半左右；但其结构简单、各通道由同一气室分隔而成，一致性和长期稳定性较好，这是早期 CT 采用它的原因。B 稀土陶瓷与 CdWO₄ 具有高光输出、短余辉、良好线性和抗辐射损伤能力，配硅光电二极管后转换效率可达气体探测器的两倍以上。C 余辉是闪烁体在X线停止后仍持续发光的现象，过长会使前一投影的信号\"拖尾\"进入后一投影，表现为残影，若某通道余辉异常则形成环状伪影。【为什么错】D 排数与层数是两个概念：同时采集的层数取决于数据采集系统（DAS）的通道数与探测器单元的组合方式，例如16排探测器在特定组合下只采集4层，而带 Z 轴飞焦点的64排可获得128层数据。E 与事实相反：氙气电离室需要沿射线方向有足够深度并用薄钨片分隔通道，很难在 Z 轴方向叠成多排，这正是多排 CT 全面转向固体探测器的原因。", "tr": "\"排数≠层数\"是高频考点；余辉、光输出、动态范围、通道一致性构成探测器性能的四要素，命题常以环状伪影反向考查余辉与通道一致性。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0125", "t": "单选题", "s": "【病例】关于医用影像设备的结构与成像原理，下列描述符合实际的是。 结合上述情景，多层螺旋 CT 的机架内在球管侧与探测器侧分别设置了准直装置。关于准直器的作用，正确的是", "o": {"A": "前准直器决定图像层厚，后准直器决定螺距大小", "B": "单层 CT 无需后准直器，多层 CT 完全依靠后准直器决定层厚", "C": "准直器开口越宽，Z 轴空间分辨率越高", "D": "前准直器（球管侧）限制射线束在 Z 轴方向的宽度，决定总采集束宽并直接影响受检者剂量；后准直器（探测器侧）主要用于抑制到达探测器的散射线", "E": "准直器的宽度与螺旋扫描的过扫描辐射（over-ranging）无关"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-003", "kp": "CT 准直器的功能", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】前准直器把射线束在 Z 轴方向限制为所需的采集宽度，凡是被它挡住的光子都不会照射患者，因而是控制受检者剂量的关键部件；后准直器（探测器侧的隔板/栅格）则主要拦截来自被检体的散射线，改善图像对比噪声比。【为什么错】A 螺距是床进距离与总准直宽度之比，由扫描协议设定，不由前准直器\"决定\"；层厚在多层 CT 中由探测器单元组合与重建参数决定。B 单层 CT 的层厚正是由前后准直器共同限定的；而多层 CT 的层厚取决于探测器单元的组合与 DAS 通道分配，而非后准直器。C 结论相反：准直越宽则单层厚度越大、部分容积效应越明显，Z 轴分辨率下降。E 过扫描辐射恰恰与准直宽度密切相关——螺旋扫描首末端为满足插值重建需要额外旋转的距离与束宽成正比，宽体探测器的过扫描剂量代价更大，需用动态准直器（自适应准直）加以抑制。", "tr": "\"前准直控剂量与束宽、后准直去散射\"是主线；单层 CT 与多层 CT 的层厚决定机制不同，这是最容易张冠李戴之处。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0126", "t": "单选题", "s": "部分高端 CT 采用飞焦点（flying focal spot）技术提升采样密度。关于该技术的作用机制与效果，正确的是", "o": {"A": "在机架旋转过程中让焦点随患者移动，实现对目标的连续追踪", "B": "利用偏转线圈使电子束在阳极靶面上的落点沿 Z 轴和／或扫描平面内高频交替，使同一次旋转获得双倍投影采样，从而提高 Z 轴分辨率或抑制混叠伪影", "C": "通过两只球管交替曝光以获取双能量数据", "D": "通过提高阳极转速使焦点变小，从而提高空间分辨率", "E": "让焦点在时间上抖动以分散热负荷，从而允许延长曝光时间"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-004", "kp": "飞焦点技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】飞焦点通过电磁偏转线圈在毫秒以下的时间尺度内让电子束落点在靶面上来回跳变。沿 Z 轴方向跳变（Z-flying focal spot）时，探测器每排在一次旋转中获得两套在 Z 轴上相互交错的采样，等效采样密度加倍，可使64排探测器输出128层数据，显著提高 Z 轴分辨率并减少风车状伪影；在扫描平面内跳变（φ 方向）则提高平面内的角向与径向采样密度，抑制因采样不足导致的混叠（条纹）伪影。【为什么错】A 描述的是不存在的\"焦点追踪\"概念，CT 的焦点相对机架是固定在球管内的。C 双球管交替曝光是双源 CT 的双能实现方式，与飞焦点无关；双能亦可用快速 kV 切换或双层探测器实现。D 阳极转速影响的是热负荷能力，不改变焦点尺寸；焦点尺寸由灯丝与聚焦系统决定。E 飞焦点的跳变幅度仅零点几毫米，对热分散贡献有限，其设计目的是提高采样而非提升负荷。", "tr": "把飞焦点误认为\"双源\"或\"双能\"是常见错误；记住关键词是\"采样加倍\"，Z 向飞焦点解决 Z 轴分辨率与风车伪影，面内飞焦点解决混叠伪影。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0127", "t": "多选题", "s": "关于多层螺旋 CT 的 Z 轴覆盖能力与螺距等扫描参数，下列表述正确的有", "o": {"A": "单圈 Z 轴覆盖宽度等于采集层数与单层准直宽度的乘积，如64×0.625 mm 约为40 mm", "B": "在机架旋转周期固定时，增大螺距可提高进床速度、缩短完成同一范围扫描所需的时间", "C": "螺距等于机架旋转一周检查床移动的距离除以总准直宽度", "D": "在关闭自动管电流调制、每圈 mAs 设定不变时，增大螺距会使有效 mAs 下降，受检者剂量随之降低", "E": "Z 轴覆盖宽度越大，锥形束伪影越轻"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-005", "kp": "Z 轴覆盖、螺距与有效 mAs", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】A 这是 Z 轴覆盖的定义式，64×0.625 mm＝40 mm。B 进床速度＝螺距×总准直宽度÷旋转周期，螺距增大则速度提高、总时间缩短。C 这是国际通用的螺距定义（beam pitch）。D 有效 mAs＝每圈 mAs÷螺距，螺距增大使同一断面被照射的次数减少，剂量下降（代价是噪声增加，故现代设备多用自动管电流调制维持图像质量）。【为什么错】E 结论相反：Z 轴覆盖越宽，射线束的锥角越大，边缘排探测器接收的射线偏离横断面越远，重建时的近似误差越大，锥形束伪影（尤其在高对比界面如颅底、肩部）越明显，因此宽体 CT 必须依赖锥形束重建算法（如 Feldkamp 类或加权迭代）加以校正。", "tr": "\"增大螺距降剂量\"的前提是每圈 mAs 固定；若使用自动管电流调制，设备会自动补偿使图像质量恒定，此时剂量未必下降，这是临床与考题的关键差别。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0128", "t": "单选题", "s": "关于 CT 图像重建算法的分类归属与特点，正确的是", "o": {"A": "迭代重建属于解析法的一种改进，其本质仍是一次性反投影", "B": "迭代重建的核心是提高卷积核（重建函数）的锐利度", "C": "滤波反投影（FBP）属于解析法重建；迭代重建（IR）在投影域与图像域之间反复进行正投影、比较、修正以逼近真实值，属于代数或统计迭代类算法", "D": "迭代重建不能降低图像噪声，只能改善空间分辨率", "E": "反投影法与滤波反投影法都属于迭代法"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-006", "kp": "解析法与迭代重建的原理归属", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (2)软件结构", "ex": "【为什么对】CT 重建算法分为解析法与迭代法两大类。解析法以中心切片定理为基础，用卷积（滤波）消除反投影固有的星状模糊后一次性反投影成像，代表即 FBP，速度快但对噪声与欠采样敏感。迭代法先给出初始图像估计，经正投影得到模拟投影，与实测投影比较后按一定准则（代数 ART、统计最大似然、基于模型 MBIR）修正图像，反复循环直至收敛；它可在重建过程中引入噪声统计模型、系统光学模型与先验约束，从而在低剂量下显著抑制噪声与伪影。【为什么错】A 迭代法与解析法在数学框架上完全不同，且其核心正是\"反复\"而非一次性反投影。B 卷积核锐利度属于 FBP 的参数选择，不是迭代重建的核心。D 与实际相反：抑制噪声、允许降低剂量恰恰是迭代重建最主要的临床价值，同时可改善低对比可探测能力。E 反投影法与 FBP 均属解析法，归类错误。", "tr": "\"迭代重建＝降剂量\"要有条件：迭代强度过高会使图像呈蜡样／塑料感、纹理改变，影响低对比病灶判读，故临床多采用中等强度混合迭代。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0129", "t": "多选题", "s": "结合上述情景，关于 CT 扫描机架内的主要硬件系统，下列表述正确的有", "o": {"A": "数据采集系统（DAS）完成探测器电信号的放大、积分、采样与模／数转换，其通道数决定了可同时采集的层数", "B": "目前主流 CT 多采用低压滑环，把高压发生器安装在旋转机架内，以避免高压滑环打火与绝缘难题", "C": "参考探测器用于实时监测球管输出的波动，并据此对投影数据进行归一化校正", "D": "球管的阳极热容量越大，其单位时间的散热率必然越高", "E": "探测器排数增加可直接提高单扇区重建的时间分辨率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-007", "kp": "CT 机架硬件构成与功能", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】A DAS 是探测器与重建计算机之间的桥梁，其通道数是\"能同时读出多少路数据\"的硬约束，因而决定同时采集的层数。B 低压滑环只传输数百伏交流电，绝缘与打火风险远小于传输上万伏的高压滑环，代价是高压发生器须小型化并承受旋转离心力，这也是高频发生器技术的功劳。C 参考探测器位于射线束边缘、不经过被检体，其读数反映球管每次投影的实际输出，用于消除管电流波动带来的环状与条状伪影。【为什么错】D 热容量（单位 MHU 或 kJ，衡量能蓄多少热）与散热率（单位 kHU/min 或 kW，衡量单位时间能散多少热）是两个相互独立的指标：大热容量球管可以承受长时间连续扫描，但如果散热率低，冷却等待时间反而更长。E 单扇区时间分辨率约等于机架旋转周期的一半，由旋转速度决定；增加探测器排数只扩大 Z 轴覆盖、缩短总扫描时间，并不改变单圈的时间分辨率。", "tr": "\"热容量 vs 散热率\"\"覆盖范围 vs 时间分辨率\"是两组最易混淆的配对；提高时间分辨率的正途是加快机架转速、采用多扇区重建或双源系统。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0130", "t": "案例分析题", "s": "一名62岁男性，反复胸闷，心内科申请冠状动脉 CTA。检查前测得心率78次/分且节律不齐（心房颤动），舌下含服硝酸甘油后心率无明显下降，患者屏气配合尚可。科室设备为64排 CT（64×0.625 mm，Z 轴覆盖40 mm），机架最快旋转0.35 s/圈，具备前瞻性心电门控轴扫、回顾性心电门控螺旋扫描以及心电编辑功能。从设备性能与心律条件出发，最合理的扫描方案是", "o": {"A": "关闭心电门控，采用常规螺旋扫描后作多期相重建", "B": "采用前瞻性心电门控轴扫（step-and-shoot），仅在 R-R 间期75%处采集", "C": "采用大螺距（3.0 以上）单心动周期螺旋扫描", "D": "采用回顾性心电门控螺旋扫描，取小螺距（约0.2）全期相采集，扫描结束后利用心电编辑剔除或校正异常心搏，再从多期相中挑选运动伪影最小的期相重建", "E": "把机架旋转速度提高到0.20 s/圈以获得更高的时间分辨率"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-008", "kp": "心律不齐患者冠脉 CTA 的设备条件与门控选择", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】房颤患者 R-R 间期长短不一，无法事先预测下一个心动周期的静止期落点，唯有回顾性门控在整个心动周期内连续采集数据并同步记录心电信号，才为事后补救留出余地：心电编辑可删除早搏、插入或移动触发点，再在多个期相中挑选运动伪影最小者重建。代价是辐射剂量较高，可通过管电流调制（在目标期相外降低 mA）部分抵消。【为什么错】A 无门控扫描不记录心电时相信息，重建时无从对应心动周期，冠脉必然被搏动模糊，也无法事后补救。B 前瞻性门控只在预设期相曝光，房颤时极易采到收缩期或运动期，且相邻采集块之间会出现层间错位（阶梯状伪影），更没有其他期相可供替换。C 大螺距单心跳扫描依赖双源 CT 的高时间分辨率（约75 ms）并要求心率低而规整，64排单源设备根本不具备该能力，强行使用会造成数据缺失。E 机架旋转速度是设备的固有硬件上限，操作者不可能自行提升；0.35 s/圈对应的单扇区时间分辨率约175 ms，这正是本例必须依靠期相选择而非单纯提速的原因。", "tr": "门控选择的判断依据是\"心率快慢\"与\"节律是否规整\"两条线：心率低且规整优先前瞻门控省剂量；心律不齐必须选回顾门控＋心电编辑。切勿因\"低剂量\"惯性思维而在房颤患者上强用前瞻门控。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0131", "t": "案例分析题", "s": "某院 CT 室在连续完成十余例全腹部增强扫描后，控制台弹出提示\"球管热容量已达92%，请等待冷却\"。此时急诊送来一名高处坠落的多发伤患者，生命体征尚平稳但需尽快完成头颅、颈椎、胸腹盆的创伤全身 CT 以指导手术决策。备用 CT 正在进行设备年检无法使用。作为当班技师，在保证诊断质量前提下最优的处置是", "o": {"A": "重新规划扫描方案：适当提高螺距、开启自动管电流调制并降低参考 mAs、采用迭代重建以补偿噪声，精确设定扫描范围避免重叠曝光，同时保持机架强制风冷运行，分段完成检查", "B": "关机重启以清零热容量读数后按常规方案扫描", "C": "忽略提示按常规方案连续扫描，热容量指示不影响图像质量", "D": "把管电压由120 kV 提高到140 kV，以缩短曝光时间来减少产热", "E": "等待球管自然冷却至50%以下后再开始检查"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-009", "kp": "球管热容量限制下的扫描方案调整", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】球管产热量正比于管电压、管电流与曝光时间的乘积。提高螺距减少了单位长度上的曝光次数，开启自动管电流调制并适当下调参考 mAs 直接降低管电流，精确规划范围避免无谓曝光，三者叠加可显著降低总热负荷；随之上升的图像噪声由迭代重建加以抑制，从而在不牺牲诊断信息的前提下把检查完成。同时保持机架运行使风冷系统持续工作，比停机静置散热更快。【为什么错】B 热容量是通过阳极温度模型实时计算的物理量，重启只会丢失或重置显示值而不改变阳极的真实温度，强行曝光可能触发保护停机，严重时造成靶面熔蚀、真空度下降等不可逆损坏。C 热容量超限会触发降功率或停机保护，扫描中途中断对多发伤患者风险极高。D 提高 kV 使球管输入功率按管电压增大而上升，产热不降反升，与降热目标背道而驰，同时降低组织对比。E 多发伤属时间敏感的急诊，等待球管自然冷却可能延误手术时机，而通过参数优化本可立即完成检查，属于不必要的等待。", "tr": "设备保护提示不可强行绕过，但也不等于只能被动等待；\"降 mAs＋提螺距＋控范围＋迭代重建\"是热负荷受限时的标准应对组合。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0132", "t": "单选题", "s": "DSA 在把注药前后的两帧图像相减之前，需要先对图像信号作对数变换。这一处理步骤的根本原因是", "o": {"A": "对数变换可以提高图像的空间分辨率", "B": "对数变换可以自动消除因患者移动造成的运动性伪影", "C": "对数变换可以压缩数据量以便于长期存储", "D": "对数变换用于把相减产生的负值转换为正值以便显示", "E": "X线经人体衰减遵从指数规律，取对数后信号与被穿透组织的厚度及碘浓度呈线性关系，相减才能彻底消除背景并使碘信号具有可比性"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-001", "kp": "DSA 对数变换的意义", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】X线透过人体后强度按 I＝I₀e^(−μd) 衰减，探测到的信号与组织厚度、衰减系数呈指数关系。若直接相减，背景骨骼与软组织的贡献不能完全抵消，且相同碘量在厚薄不同的部位会产生不同的差值。取对数后 lnI₀−lnI＝μd，信号与厚度、碘浓度呈线性叠加关系，两帧相减即可精确抵消所有未变化的背景成分，只剩下与碘量成正比的差值，这既保证了背景清除的彻底性，也使不同部位的血管强化程度具有可比性，是后续定量分析的前提。【为什么错】A 对数变换是逐像素的灰度变换，不改变系统的调制传递特性，与空间分辨率无关。B 运动伪影须靠屏气配合、缩短采集时间、像素移位与再蒙片处理，对数变换无此能力。C 对数变换用于线性化而非压缩存储，DSA 数据通常以12~14 bit 保存。D 相减产生的负值靠加偏置量与窗口调节显示，与对数变换不是同一环节。", "tr": "\"先对数、后相减\"的顺序不能颠倒；把对数变换误解为\"增强对比\"或\"去噪\"是常见错误，它的本质是把指数衰减线性化。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0133", "t": "单选题", "s": "与影像增强器—电视系统（II-TV）相比，采用动态平板探测器的 DSA 系统在成像链上的主要优势是", "o": {"A": "没有枕形畸变与边缘失真，无渐晕效应，动态范围宽、DQE 高，视野呈矩形且切换视野时几何关系保持一致", "B": "空间分辨率较低但时间分辨率明显提高", "C": "由于不设输入屏，因此不再需要抗散射滤线栅", "D": "平板探测器输出为模拟视频信号，需另经模／数转换器数字化", "E": "平板探测器不能进行脉冲透视，只能连续透视"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-002", "kp": "平板 DSA 与影像增强器系统的比较", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】影像增强器靠电子光学把输入屏图像缩小到输出屏，电子轨迹在边缘处偏离理想路径造成枕形畸变，输入屏为球面又导致边缘变形；同时输出屏边缘亮度低于中心，形成渐晕。平板探测器为平面像素阵列，逐像素对应、几何关系严格线性，无上述缺陷；其圆形视野变为矩形，有效面积利用率更高，且不同视野只是读出区域不同，几何标定保持一致，有利于三维旋转采集与路径图的配准。此外平板动态范围可达10⁴以上，DQE 高，可在更低剂量下工作。【为什么错】B 平板 DSA 的空间分辨率与时间分辨率均不低于同代 II-TV 系统，说\"分辨率较低\"不成立。C 抗散射依赖滤线栅、缩野与空气间隙，与探测器类型无关，平板同样需要滤线栅。D 平板探测器在像素级完成电荷读出并直接数字化输出，无需模拟视频链路，这正是它取代 II-TV 的技术特征。E 平板可按设定帧率脉冲曝光，脉冲透视是其降低剂量的常规手段。", "tr": "枕形畸变、渐晕、S 形畸变（受地磁与杂散磁场影响）都是影像增强器特有的问题；把它们套用到平板系统上，或反过来认为平板\"无需滤线栅\"，都是概念错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0134", "t": "共用题干题", "s": "结合上述情景，一名下肢动脉硬化闭塞症患者行下肢动脉 DSA，因肢体疼痛难以制动，常规掩模像方式（mask mode）减影后图像上出现明显的骨骼错位性伪影，血管显示被干扰。在不重复大量注射对比剂的前提下，最适宜采取的措施是", "o": {"A": "改用能量减影（K 缘减影）方式采集", "B": "把采集帧率提高到30帧/s 并缩短单帧曝光时间", "C": "先行像素移位（pixel shift）配准并选取更接近的帧作再蒙片（remask），仍不满意时改用时间间隔差（TID）方式减影", "D": "提高对比剂浓度与注射流率以增强血管信号", "E": "改用路径图（road map）模式进行诊断性采集"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-003", "kp": "DSA 运动伪影的减影方式选择", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】像素移位是在后处理中把蒙片整体或分区平移、旋转以与充盈帧重新配准，可校正小幅度的刚性移动；再蒙片则是重新选择一帧与目标帧运动状态更接近的图像作蒙片，二者都不需要追加对比剂。若移动幅度较大，改用时间间隔差方式（以序列中相隔固定帧数的两帧互为蒙片相减）能进一步减轻长时程漂移的影响，代价是背景抑制不如常规掩模方式彻底。【为什么错】A 能量减影需在极短时间内切换两种管电压并利用碘的 K 吸收缘（33.2 keV）作双能相减，对设备要求高、软组织信号残留多，临床应用有限，也不能解决大幅度移动。B 提高帧率只是增加采样密度和辐射剂量，运动本身仍会造成蒙片与充盈帧的错配。D 加大浓度与流率增加碘负荷与血管损伤风险，且无法消除背景错位。E 路径图是把已充盈的血管影作为背景叠加在实时透视上，用于导丝导管导航，不作为诊断性减影序列。", "tr": "处理运动伪影的顺序是\"先无创后有创\"：屏气与固定→像素移位→再蒙片→更换减影方式→最后才考虑重复造影；把路径图当成诊断序列是常见混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03047", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-0135", "t": "多选题", "s": "关于 DSA 设备的结构、功能与参数设置，下列表述正确的有", "o": {"A": "C 形臂支持多角度投照与旋转采集（3D-DSA），并可与高压注射器实现曝光—注射同步（设定X线延迟或注射延迟）", "B": "为降低皮肤剂量，透视时应尽量增大探测器与患者的距离，同时缩短球管到患者的距离", "C": "图像信号经对数放大后由模／数转换器数字化（通常为12~14 bit），再送入图像存储器完成实时相减", "D": "DSA 的时间分辨率取决于采集帧率，冠状动脉造影常用15~30帧/s，脑血管造影常用2~6帧/s", "E": "3D 旋转采集依靠影像增强器的枕形畸变进行几何标定"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-004", "kp": "DSA 设备结构与采集参数", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】A 旋转采集要求 C 形臂在等中心条件下匀速转过约200°，与高压注射器的同步延迟设置决定了旋转期间血管始终处于充盈状态。C 对数放大把指数衰减线性化，12~14 bit 量化保证了在宽动态范围内仍有足够的灰阶层次供相减使用。D 帧率决定能分辨的血流时相，冠脉因心脏搏动快需高帧率，脑血管血流相对缓慢、且为降低剂量常用低帧率。【为什么错】B 完全说反：探测器应尽量贴近患者以减少放大率、提高图像质量并利用自动亮度控制降低输出；球管则应尽量远离患者，因为入射皮肤剂量遵循平方反比定律，球管越近皮肤剂量越高，这是介入放射防护的核心原则之一。E 因果颠倒：枕形畸变是影像增强器的固有缺陷，做三维重建时必须先用标定模体测量并校正这一畸变，而不是\"依靠\"它；平板探测器无此畸变，更适合 3D-DSA。", "tr": "介入防护三要点：探测器贴近患者、球管远离患者、尽量少用放大视野与陡角度投照；B 项是最典型的反向陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0136", "t": "案例分析题", "s": "一名56岁男性肝癌患者行经导管肝动脉化疗栓塞（TACE）术前肝动脉 DSA。导管头端位于肝固有动脉，注射参数为对比剂300 mgI/ml、流率3 ml/s、总量12 ml，采集帧率6帧/s，患者清醒、未使用镇静剂。所得减影图像上肝区出现随呼吸起伏的条带状伪影，肝右叶末梢分支显示不清，肿瘤染色难以判断。作为导管室技师，最合理的调整是", "o": {"A": "把采集帧率提高至15帧/s 以\"追上\"呼吸运动", "B": "关闭抗散射滤线栅以提高图像亮度", "C": "把管电压提高到110 kV 以增强对膈下区域的穿透", "D": "把导管退至腹腔干开口并将流率提高到8 ml/s", "E": "训练并嘱患者于呼气末屏气后再曝光，适当降低帧率至3帧/s 并延长采集时间以覆盖实质期与肿瘤染色期，必要时结合像素移位与再蒙片处理残余错配"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-005", "kp": "腹部 DSA 呼吸运动伪影的技术处置", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】肝脏 DSA 的首要干扰是膈肌运动造成的蒙片与充盈帧错配。呼气末屏气是最有效且零成本的措施，且呼气末位置重复性优于吸气末。肝动脉血流较慢、肿瘤染色出现晚，3帧/s 足以刻画时相，同时可延长采集时间覆盖实质期与染色期，还能显著降低患者与术者的受照剂量。残余小幅错配再用像素移位与再蒙片校正。【为什么错】A 提高帧率只能增加采样密度，蒙片与充盈帧之间的呼吸位移依然存在，伪影不减而剂量倍增。B 撤除滤线栅后散射线大量进入探测器，对比度下降、噪声增加，虽然亮度提高但图像质量恶化，且对运动伪影毫无帮助。C 单纯提高管电压会降低碘与周围组织的对比（碘的衰减优势在较低能量区更明显），末梢分支反而更难显示。D 退至腹腔干并大幅提高流率会使脾动脉、胃十二指肠动脉等大量分支同时显影而与肝区重叠，且8 ml/s 对肝动脉超选造影而言流率过高，可能造成血管痉挛甚至内膜损伤，与\"看清肝右叶末梢\"的目标背道而驰。", "tr": "腹部 DSA 的时相安排要覆盖动脉期—实质期—静脉期；高帧率并非万能，遇运动伪影首先想到呼吸控制而不是提高帧率或加大注射。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0137", "t": "单选题", "s": "超导型 MRI 设备在特定条件下会发生失超（quench）。关于失超的过程与应急处置，描述正确的是", "o": {"A": "失超时主磁场保持不变，仅损失部分液氦", "B": "超导线圈因局部升温而丧失超导态、电阻骤增并大量产热，液氦急剧汽化经失超管排出室外，磁场在数秒至数十秒内迅速衰减；此时应立即撤离人员、开启强制排风，切勿滞留观察", "C": "失超管的作用是在液氦不足时向磁体自动补充液氦", "D": "失超发生时应立即打开磁体间门窗，并安排工作人员在室内观察磁场衰减情况", "E": "失超只能由人为按下紧急失超按钮引起，不会自发发生"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-001", "kp": "失超的机制与应急处置", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】超导线圈在液氦温度（约4.2 K）下电阻为零，一旦某处温度超过临界值即恢复电阻，强大的储存能量瞬间转化为焦耳热，液氦剧烈沸腾。1 L 液氦可膨胀成约700 L 气体，必须由失超管（专用排气管道）迅速导出室外。磁场随电流衰减而在数秒至数十秒内基本消失。现场风险来自氦气置换空气造成的窒息、极低温冻伤以及室内正压导致外开门推不开，故正确做法是立即撤离并开启强制排风。【为什么错】A 失超的本质就是磁场消失，说\"磁场保持不变\"从根本上错误。C 失超管只出不进，补充液氦需由工程师用杜瓦罐经专用接口完成。D 若氦气已泄漏入室内，人员滞留极其危险；且开窗并不能替代专用排气与新风系统。E 除人为按下急停按钮外，机械振动、真空层失效、液氦液面过低、匀场电流异常等均可引发自发失超。紧急失超按钮仅在人员被铁磁物体挤压等危及生命时才可使用。", "tr": "务必区分\"紧急失超按钮\"与\"急停（关闭梯度与射频）按钮\"：前者会毁掉磁场并造成巨额充磁与液氦费用，只在生命受威胁时使用。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0138", "t": "多选题", "s": "关于 MRI 系统的匀场（shimming）技术，下列表述正确的有", "o": {"A": "无源匀场是在磁体孔内特定位置贴放小铁片（匀场片）作被动补偿，通常在安装或大修时完成", "B": "有源匀场通过向匀场线圈通入特定电流产生补偿磁场，可在每次检查中针对扫描野作自动或高阶匀场", "C": "磁场均匀度通常以高斯（G）为绝对值表示，其数值与所取球形容积（DSV）的大小无关", "D": "场均匀度对波谱成像、频率选择性脂肪抑制以及 EPI 的几何保真度影响显著", "E": "匀场可以补偿梯度切换引起的涡流所造成的时变磁场误差"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-002", "kp": "有源匀场与无源匀场", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】A 无源匀场利用铁磁片在主磁场中被磁化后产生的附加场抵消不均匀分量，属一次性的粗调，安装、搬迁或环境改变后需重做。B 有源匀场线圈可产生一阶（线性）乃至二阶、三阶球谐分量，在每例检查中依据实际扫描野作自动匀场，是临床最常用的精调手段。D 化学位移只有百万分之几的量级，场不均匀会使波谱峰增宽重叠、脂肪抑制脉冲频率失准导致抑制不均，EPI 因带宽极低而对场偏差高度敏感，表现为几何变形。【为什么错】C 均匀度必须用相对量 ppm 表示，并且必须注明所取球形容积直径（如40 cm DSV 内小于1 ppm）；容积越大越难保证均匀，脱离 DSV 谈均匀度没有意义。E 涡流是梯度切换引起的快速时变干扰，匀场系统的响应速度远达不到毫秒级补偿要求，对策是主动屏蔽梯度线圈与预加重，而非匀场。", "tr": "\"无源＝铁片、有源＝线圈\"要记牢；均匀度必须\"ppm＋DSV\"成对表述，只给 ppm 不给容积是不完整的。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0139", "t": "单选题", "s": "某 MRI 设备的梯度系统标称最大梯度场强为45 mT/m，由零升至最大值所需的爬升时间为200 μs。据此计算其梯度切换率（slew rate）为", "o": {"A": "0.225 mT/(m·ms)", "B": "9 mT/(m·ms)", "C": "225 mT/(m·ms)", "D": "900 mT/(m·ms)", "E": "4500 mT/(m·ms)"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-003", "kp": "梯度系统三大指标与切换率计算", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】切换率＝最大梯度场强÷爬升时间。200 μs＝0.2 ms，45 mT/m÷0.2 ms＝225 mT/(m·ms)，即225 T/(m·s)。梯度场强、切换率与爬升时间是描述梯度系统的三个核心指标，其中前两者越高、后者越短，代表性能越强，这直接决定了最短 TR/TE、EPI 单次激发的回波链速度以及扩散加权可达到的 b 值。【为什么错】A 把毫秒误当作秒进行换算，结果小了三个数量级。B 相当于用45÷5 计算，误把爬升时间当作5 ms。D 在正确结果上又多乘了4，运算错误。E 相当于按0.01 ms 爬升时间计算，与题干给出的200 μs 不符。", "tr": "切换率越高，dB/dt 越大，周围神经刺激（PNS）风险越高，因此国际标准对其设有上限；临床上高切换率带来的收益（更快的 EPI、更高 b 值）必须与 PNS 和梯度噪声之间取得平衡。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0140", "t": "多选题", "s": "梯度磁场的快速切换会在磁体冷屏、射频屏蔽等导体结构中感应出涡流。关于涡流及其对策，下列表述正确的有", "o": {"A": "涡流产生的寄生磁场与所加梯度场同向，使梯度波形的上升沿变得更陡峭", "B": "采用主动屏蔽梯度线圈（在主绕组外加反向屏蔽绕组）可显著减少泄漏到周围导体上的杂散梯度场", "C": "预加重（pre-emphasis）通过对梯度驱动电流波形作反向预失真，补偿涡流造成的波形畸变", "D": "涡流可导致 EPI／DWI 图像的几何变形、鬼影以及脂肪抑制失败", "E": "提高接收带宽是消除涡流的根本方法"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-004", "kp": "涡流效应与预加重补偿", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】B 主动屏蔽梯度在主线圈外再绕一层反向线圈，使梯度场在成像区内保留而在磁体外侧近乎抵消，从源头减少感应涡流，是现代梯度系统的标准配置。C 预加重先测出系统的涡流时间常数与幅度，然后在驱动波形上叠加相反的补偿分量，使实际产生的梯度接近理想矩形波。D 涡流使读出梯度面积偏离设计值，在带宽极低的 EPI 相位编码方向上表现为几何变形与鬼影；同时残余的时变场偏移使频率选择性脂肪抑制脉冲失准，抑制不均。【为什么错】A 方向错误：由楞次定律，感应涡流产生的磁场总是反抗原磁场的变化，其寄生场与梯度变化方向相反，结果是梯度上升沿变钝、平台出现漂移与拖尾。E 提高接收带宽可以减轻化学位移伪影和 EPI 变形的表现程度，属于\"减轻症状\"，且以牺牲信噪比为代价，并未消除涡流本身。", "tr": "涡流对策的层次是\"源头屏蔽（主动屏蔽梯度）—波形补偿（预加重）—序列层面缓解（提高带宽、并行采集、场图校正）\"；把楞次定律的方向记反是本题最主要的失分点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0141", "t": "多选题", "s": "关于 MRI 射频线圈的类型、配置与临床使用，下列表述正确的有", "o": {"A": "内置于磁体孔内的体线圈常用作发射线圈，其发射场 B₁ 相对均匀、覆盖范围大", "B": "相控阵线圈由多个小单元组成，各单元独立接收后合成，兼顾高信噪比与大视野，并且是并行采集技术（SENSE／GRAPPA／ASSET）的硬件基础", "C": "表面线圈接收到的信号强度随深度迅速衰减，浅表信噪比高但深部信号弱、均匀性差", "D": "为提高信噪比，同一部位应尽量选用尺寸更大的接收线圈", "E": "接收单元数越多，图像信噪比总是越高，与线圈填充因子及单元间噪声耦合无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-005", "kp": "射频线圈的类型与选择原则", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】A 体线圈（鸟笼式为主）孔径大、B₁ 均匀，适合作全身激发的发射线圈，也可在缺乏专用线圈时兼作接收。B 相控阵把多个小线圈的高局部信噪比与大视野结合起来，各单元的空间敏感度差异同时提供了额外的空间编码信息，成为并行采集加速的前提。C 表面线圈的敏感深度大致相当于其半径，越深信号越弱，故常需配合表面线圈强度校正。【为什么错】D 与选择原则相反：线圈尺寸应尽量贴合被检部位，线圈越大接收到的噪声体积越大、填充因子越低，信噪比反而下降；正确做法是\"能小则小、贴合紧密\"。E 表述绝对且忽略物理限制：单元过多、排布过密会加剧单元间的电磁耦合与噪声相关性，边际收益递减，同时并行加速因子过高会放大噪声（g 因子），信噪比并不随单元数无限提高。", "tr": "线圈选择的两条铁律：与部位尺寸匹配、与被检部位紧贴（提高填充因子）；相控阵单元数是并行加速能力的上限依据，而非信噪比的保证。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0142", "t": "单选题", "s": "MRI 检查室的墙壁、天花板、地面与观察窗内均设有铜板或铜网构成的完整屏蔽层（法拉第笼）。设置该屏蔽的主要目的是", "o": {"A": "屏蔽主磁场的杂散磁场，从而缩小5高斯线的范围", "B": "阻止梯度切换产生的噪声向室外传播", "C": "屏蔽X线散射线，保护候诊区人员", "D": "阻止外界射频电磁波（广播电视、通信、电机火花等）进入检查室干扰接收信号，同时防止本机发射的射频能量外泄", "E": "减少液氦的蒸发损耗"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-006", "kp": "射频屏蔽（法拉第笼）与磁屏蔽的区别", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】MR 信号极其微弱，其频率（1.5T 约63.9 MHz、3.0T 约127.7 MHz）恰好落在广播通信频段附近。铜质屏蔽层构成闭合导体壳，把外界射频反射与吸收在外，同时限制本机射频外泄。屏蔽的完整性依赖屏蔽门指簧的良好接触、观察窗铜网、所有穿墙管线经波导管以及电源与信号线经滤波板进入，任何一处破损都会导致屏蔽效能下降。【为什么错】A 限制杂散磁场靠磁屏蔽——自屏蔽磁体的反向超导线圈或机房内的硅钢板／铁磁屏蔽，与铜屏蔽是完全不同的两套系统。B 梯度噪声属声学噪声，靠隔声结构与隔声门处理。C MRI 不产生电离辐射，无需铅防护。E 液氦蒸发由磁体自身的真空绝热层、冷头与制冷机控制，与机房屏蔽无关。", "tr": "\"射频屏蔽用铜、磁屏蔽用铁\"是关键区分点；屏蔽破损的典型影像表现为拉链状（zipper）伪影或沿相位编码方向的条纹噪声。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0143", "t": "单选题", "s": "MRI 机房管理中常提到\"5高斯线\"。关于这一概念，正确的说法是", "o": {"A": "5高斯线（0.5 mT 等磁力线）是公认的安全警戒线，装有心脏起搏器等有源植入物者及未受控人员不得越过，该线所包围的区域必须设置明显标识并加以门禁管理", "B": "5高斯线以内属绝对安全区，铁磁性物品可以自由进入", "C": "5高斯线的范围与磁体是否采用主动屏蔽无关", "D": "5高斯线只存在于磁体所在的水平面上，上下楼层不受影响", "E": "5高斯线是指梯度磁场作用范围的边界"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-007", "kp": "5高斯线与磁体安全管理", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】0.5 mT 是普遍采用的有源植入物安全阈值，5高斯线因而成为磁场控制区的划界依据，线内区域应有醒目标识、实体隔离与门禁，非受控人员、起搏器与神经刺激器携带者禁止进入。【为什么错】B 恰恰相反：5高斯线以内磁场更强，铁磁物品进入会产生抛射效应（missile effect），是 MRI 最严重的安全事故来源。C 主动屏蔽磁体在主线圈外设置反向超导绕组抵消外泄磁场，可把5高斯线从数米压缩到磁体周围一两米范围，这正是现代 MRI 得以在有限机房面积内安装的原因。D 磁力线在三维空间中闭合，5高斯线是一个立体包络面，上下楼层同样可能被覆盖，机房选址时必须评估楼上楼下的用途。E 5高斯线描述的是主磁场 B₀ 的空间分布，与梯度场无关。", "tr": "MR 安全分区（Ⅰ~Ⅳ区）与5高斯线常被合并考查；注意\"5高斯线以内更危险\"这一方向性，切勿把它理解成安全区边界向内即安全。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0144", "t": "案例分析题", "s": "某院飞利浦3.0T MRI 检查室，近一周多例颅脑检查的图像上出现沿相位编码方向的一条明亮\"拉链状\"（zipper）条纹，位置基本固定于图像中部；技师先后更换了头颈联合相控阵线圈、更换患者、重做预扫描与自动匀场，条纹依旧存在。追问得知，一周前保洁车曾撞击机房屏蔽门，门下缘指簧有明显变形，且近期机房外走廊新增了一台无线路由设备。作为技师，对该现象最合理的判断与首选处置是", "o": {"A": "主磁场均匀性下降所致，应重新进行无源匀场", "B": "射频屏蔽失效使外界射频干扰进入检查室，应立即停止使用并检查修复屏蔽门指簧、波导管与滤波板，复测屏蔽效能合格后方可恢复扫描，同时排查并移开新增的射频源", "C": "梯度线圈涡流补偿失效，应重新标定预加重参数", "D": "液氦液面过低导致磁体不稳定，应尽快补充液氦", "E": "相控阵线圈的某个接收单元损坏，应更换线圈"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-008", "kp": "射频干扰伪影的判断与处置", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】拉链状伪影是外来窄带射频信号混入接收链的典型表现：干扰信号只有单一或很窄的频率成分，经傅里叶变换后在频率编码方向上定位于某一点，而在相位编码方向上没有确定的相位关系，于是沿相位编码方向铺展成一条亮线。本例的时间关联（屏蔽门指簧撞击变形、走廊新增无线设备）与排除性证据（更换线圈、更换患者、重做匀场均无效）共同指向屏蔽完整性受损，故应停机检修屏蔽门指簧、波导管与滤波板，用场强仪复测屏蔽效能，并排查外部射频源。【为什么错】A 场均匀性下降主要表现为脂肪抑制不均、图像变形与信号强度不均，而非固定位置的单条亮线，且题干已说明重做自动匀场无效。C 涡流补偿失效表现为几何变形、鬼影与脂肪抑制失败，常见于 EPI 类序列，与拉链伪影的形态不符。D 液氦不足会触发液面报警并最终导致失超，不会以拉链伪影为首发表现。E 已被\"更换线圈后仍存在\"这一关键信息排除；单元损坏通常表现为局部信号缺失或敏感度不均。", "tr": "MRI 伪影排查的方法学是\"变量替换法\"：换线圈、换患者、换序列、换机房时段，逐一排除；拉链伪影首先想到射频屏蔽，其次才是硬件老化与序列参数问题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-0145", "t": "共用题干题", "s": "结合上述情景，关于医用高压注射器的结构与安全功能，下列表述正确的是", "o": {"A": "注射流率与总量一经设定即不能分段编程", "B": "双筒注射器的第二个针筒仅能用于注射对比剂", "C": "高压注射器无法与 CT／MR 实现曝光与注射的同步触发", "D": "用于 MR 检查的高压注射器可以直接沿用 CT 注射器的铁磁性部件", "E": "具备压力限制功能，当导管阻塞或血管外渗使管路压力超过设定上限时可自动报警并终止注射"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-001", "kp": "医用高压注射器的结构与安全功能", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (2)医用高压注射器", "ex": "【为什么对】压力限制是高压注射器最重要的安全设计：系统实时监测推注压力，当导管打折、留置针阻塞或对比剂渗入血管外使阻力骤增、压力超过预设上限（通常按导管耐压值设定）时立即报警并停止推注，可有效减少大量外渗与导管爆裂事故。【为什么错】A 现代注射器普遍支持多段程序，可设定不同流率、不同容量的多个阶段以及生理盐水冲刷段，用于优化团注形态。B 双筒设计的第二个针筒通常装载生理盐水，用于注射后冲刷残留于静脉与管路中的对比剂，既提高利用率又减少上腔静脉高浓度伪影。C 注射器与主机之间可通过同步接口实现\"注射触发曝光\"或\"曝光触发注射\"，这是团注追踪与动态增强的技术基础。D MR 检查室内的注射器必须使用无磁或弱磁材料并按磁场分区放置，直接沿用铁磁部件会造成抛射事故与图像伪影，属严重违规。", "tr": "压力限制只能减轻而不能杜绝外渗：低压缓慢渗漏可能不足以触发压力报警，因此注射全程仍须有人观察穿刺部位与患者主诉。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03060", "gs": ""}, {"id": "ZG-U03-0146", "t": "多选题", "s": "关于医用诊断显示器的性能要求与质量控制，下列表述正确的有", "o": {"A": "应按 DICOM PS3.14 灰度标准显示函数（GSDF）进行校准，使等间隔的驱动电平产生视觉上等间隔的可觉察灰度差（JND）", "B": "诊断报告用显示器的最大亮度要求高于临床浏览用显示器，其中乳腺阅片对分辨率与亮度的要求最高", "C": "可使用 SMPTE 或 AAPM TG18-QC 测试图对亮度响应、几何失真、伪轮廓与低对比可见度作主观评价", "D": "显示器验收合格后无需再定期校准，只要不更换设备即可长期使用", "E": "阅片室环境照度越高，越有利于观察低对比度病灶"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-002", "kp": "医用显示器的性能与质量控制", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (3)医用显示器", "ex": "【为什么对】A GSDF 的意义在于把显示器的亮度响应曲线映射为符合人眼对比敏感度特性的曲线，保证同一图像在不同显示器上呈现一致的可觉察灰度层次。B 诊断用显示器需要更高的最大亮度与对比度以展开宽动态范围的数字影像，乳腺影像因需分辨微钙化，对分辨率（常要求5 MP）与亮度的要求最为严格。C 这两套测试图是主观评价的通用工具，可快速发现亮度响应异常、几何失真、伪轮廓与低对比分辨能力下降。【为什么错】D 液晶背光会随使用时间衰减、色温漂移，必须按规定周期（通常每年一次完整校准，日常有开机自检与定期一致性检测）复校，这是质量控制体系的强制要求。E 恰恰相反：环境光在屏幕表面产生反射，抬高显示的最低亮度、压缩有效对比度，使低对比病灶更难识别，故诊断阅片室要求低照度并避免屏幕受直射光与反光干扰。", "tr": "\"验收合格＝永久合格\"是质量管理中的典型错误认识；显示器质量控制包含验收检测、状态检测与稳定性检测三个层次，缺一不可。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-0147", "t": "案例分析题", "s": "某院使用干式激光相机打印 CT 胶片。近两日打印出的胶片沿走片方向出现规律性、间距基本相等的浅色横向条带，更换不同批次、不同包装的胶片后条带依旧；调阅同一序列在诊断显示器上的图像显示完全正常，PACS 与打印机之间的 DICOM Print 通信日志无异常，打印任务亦无排队报错。作为技师，下列判断与处置最合理的是", "o": {"A": "判断为胶片受潮所致，改用其他品牌胶片即可", "B": "判断为显示器未按 GSDF 校准，重新校准显示器后再打印", "C": "判断为打印机机械走片系统或热鼓／激光扫描单元存在周期性异常，应暂停该设备并通知工程师检查输片辊、热鼓与激光偏转部件，检修后用 SMPTE 或 TG18 测试图打印复核密度与均匀性", "D": "判断为窗宽窗位设置不当，调整后重新打印", "E": "判断为网络丢包导致图像数据不完整，重启 PACS 服务器"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-003", "kp": "干式激光相机打印伪影的分析与处理", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (1)医用打印机", "ex": "【为什么对】\"沿走片方向、间距相等\"的规律性条带是典型的周期性机械或热学缺陷特征：输片辊表面附着物或磨损会以辊子周长为周期在胶片上留下痕迹，热敏成像的热鼓温度不均或激光扫描单元的偏转周期异常同样会形成等距条带。题干已用三条证据锁定故障在打印机本身——更换不同批次胶片无效（排除耗材）、显示器图像正常（排除图像数据与显示环节）、通信日志正常（排除网络与传输）。因此应停用设备交由工程师检修，检修后必须用标准测试图打印复核光学密度与均匀性，确认合格再投入临床。【为什么错】A 已更换不同批次与包装的胶片仍出现，受潮假设与证据矛盾。B 显示器校准影响的是屏幕观察效果，不改变送往打印机的像素数据，且题干显示图像本身正常。D 窗宽窗位异常会表现为整幅图像的对比或亮度失当，不会形成等距横带。E 网络丢包通常导致任务失败、图像残缺或错位，而不是规律性的密度条带，且日志已排除。", "tr": "打印质量问题的排查顺序为\"图像源→传输→打印机→耗材→环境\"；识别伪影的\"周期性\"与\"方向性\"是定位机械故障的关键线索。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1001", "t": "单选题", "s": "固定阳极X线管阳极靶面通常采用的制作材料是", "o": {"A": "钨", "B": "钼", "C": "铜", "D": "铝", "E": "银"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-001", "kp": "固定阳极X线管结构", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (1)固定阳极X线管", "ex": "【为什么对】钨的原子序数高（74）、熔点高（约3370℃）、蒸发率低、耐高温能力强，是X线管阳极靶面的理想材料。【为什么错】B钼是乳腺X线机阳极靶材，原子序数较低以产生软X线；C铜多用作阳极体散热材料，熔点低于钨；D铝常用作X线束滤过材料；E银熔点低且不耐高温，不用于靶面。", "tr": "易将乳腺机的“钼靶”误认为所有X线管通用靶材，实际普通X线管靶材为钨。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1002", "t": "共用题干题", "s": "结合上述情景，旋转阳极X线管将阳极做成可旋转圆盘，其主要目的是", "o": {"A": "增大有效散热面积，提高瞬间功率承受能力", "B": "缩小实际焦点面积", "C": "降低管电压", "D": "减少X线散射线", "E": "提高X线质（能谱）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-002", "kp": "旋转阳极X线管结构", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (4)旋转阳极X线管", "ex": "【为什么对】旋转阳极使靶面不断旋转，电子轰击的热量轮流分布于整个靶盘，散热面积显著增大，能承受更大的瞬时负载功率。【为什么错】B旋转不改变实际焦点（实际焦点由灯丝形状与聚焦罩决定），只改善散热；C管电压由高压发生器决定；D散射线主要靠准直器与滤线栅减少；E X线质由管电压决定。", "tr": "旋转阳极解决的是“散热与功率”问题，而非直接缩小焦点；缩小有效焦点靠减小阳极倾角。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03061", "gs": ""}, {"id": "ZG-U03-1003", "t": "共用题干题", "s": "结合上述情景，关于X线管实际焦点与有效焦点的叙述，正确的是", "o": {"A": "实际焦点面积等于有效焦点面积乘以sinα", "B": "有效焦点是灯丝电子轰击阳极靶面的实际面积", "C": "阳极倾角越小，有效焦点越小，成像越清晰", "D": "有效焦点越大，空间分辨力越高", "E": "阳极倾角越大，X线输出效率越低"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-003", "kp": "X线管的焦点", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (3)X线管的焦点", "ex": "【为什么对】有效焦点＝实际焦点×sinα（α为阳极倾角），阳极倾角越小有效焦点越小，影像半影越小，空间分辨力越高。【为什么错】A公式写反，应为实际焦点＝有效焦点/sinα；B有效焦点是从窗口（成像方向）观察到的焦点投影，而非靶面实际轰击面积；D焦点越大分辨力越低；E阳极倾角主要影响有效焦点与足跟效应，与X线输出效率无直接对应。", "tr": "牢记“有效焦点＝实际焦点×sinα”，倾角小→有效焦点小→分辨力高，但小焦点承受功率下降。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03053", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1004", "t": "共用题干题", "s": "结合上述情景，关于X线管阳极效应（足跟效应）的叙述，正确的是", "o": {"A": "阳极端X线强度低于阴极端", "B": "阴极端X线强度低于阳极端", "C": "焦点越小效应越明显", "D": "与阳极倾角无关", "E": "只影响特征X线，不影响连续X线"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-004", "kp": "X线管的规格与特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】X线在阳极靶面内斜射穿行时被靶物质吸收，阳极端吸收较多，故阳极端X线强度低于阴极端，即阳极效应。【为什么错】B恰好说反；C阳极效应主要与阳极倾角及照射野有关，与焦点大小关系不大；D倾角越小斜射距离越长，效应越明显；E阳极效应对各能量成分的X线均有影响。", "tr": "摄影时把较厚部位放在阴极端，利用阴极端强度较高的特点补偿密度差异。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03053", "gs": ""}, {"id": "ZG-U03-1005", "t": "共用题干题", "s": "结合上述情景，关于X线管空间电荷效应的描述，正确的是", "o": {"A": "管电压升高时管电流随之增大", "B": "管电压升高时管电流减小", "C": "空间电荷由灯丝加热电流决定，与管电压无关", "D": "空间电荷（电子云）越多，管电流越大", "E": "该效应使mAs控制更加准确"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-005", "kp": "X线管的规格与特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】灯丝发射的电子在管电压较低时受空间电荷（电子云）斥力限制，管电压升高后斥力作用减弱，到达阳极的电子增多，管电流随之增大，称空间电荷效应。【为什么错】B方向说反；C空间电荷效应正是管电压与灯丝电流共同作用的结果；D空间电荷越多对后续电子的排斥越强，反而不利于电子到达阳极；E该效应使管电流不稳，需加装空间电荷补偿器修正。", "tr": "空间电荷效应≠空间电荷本身多少，重点在“管电压升高→管电流增大”的联动关系。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03053", "gs": ""}, {"id": "ZG-U03-1006", "t": "共用题干题", "s": "结合上述情景，高速电子撞击阳极靶面时，其动能转换为X线的效率约为", "o": {"A": "1%", "B": "5%", "C": "20%", "D": "50%", "E": "99%"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-006", "kp": "X线管产生X线的过程", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (2)X线管产生X线的过程", "ex": "【为什么对】X线管产生的X线仅占电子总动能的约1%，其余约99%转化为热能。【为什么错】B、C、D均高估了转换效率；E将99%误认为X线转换比例，实际99%是转化为热能的比率。", "tr": "1%是X线、99%是热能，二者比例极易记反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03052", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1007", "t": "共用题干题", "s": "结合上述情景，调节X线机控制台上的“mA（管电流）”旋钮，实际调节的是", "o": {"A": "灯丝加热电流", "B": "阳极转速", "C": "高压变压器初级电压", "D": "曝光时间", "E": "焦点大小"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-001", "kp": "X线管产生X线的过程", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (2)X线管产生X线的过程", "ex": "【为什么对】管电流由灯丝发射电子数决定，调节灯丝加热电流即改变发射电子数量，从而改变管电流（mA）。【为什么错】B阳极转速为固定分挡（普通/高速），与mA调节无关；C初级电压调节的是kV；D曝光时间由计时器控制；E焦点由灯丝尺寸与聚焦罩决定。", "tr": "“kV调高压发生器、mA调灯丝电流、时间调曝光”是曝光三要素的基本分工。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03052", "gs": ""}, {"id": "ZG-U03-1008", "t": "共用题干题", "s": "结合上述情景，乳腺X线摄影机X线管阳极靶面通常采用", "o": {"A": "钼（Mo）", "B": "钨（W）", "C": "铜（Cu）", "D": "银（Ag）", "E": "铱（Ir）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-007", "kp": "特殊X线管", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (7)特殊X线管", "ex": "【为什么对】钼原子序数较低（42），其特征X线能量（约17～20keV）恰在乳腺摄影所需软X线范围，软组织对比度好。【为什么错】B钨是普通X线管靶材；C铜用于散热；D银、E铱均不用于乳腺X线管靶面。", "tr": "乳腺机钼靶＋铍窗＋小焦点＋低管电压（约22～35kV）是一组常考特征。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03062", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1009", "t": "共用题干题", "s": "结合上述情景，乳腺X线机X线管窗口采用铍（Be）窗，其目的是", "o": {"A": "减少X线束中低能成分被滤过，保留软射线", "B": "增大管电流", "C": "增大焦点", "D": "提高管电压上限", "E": "便于阳极散热"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-008", "kp": "特殊X线管", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (7)特殊X线管", "ex": "【为什么对】铍原子序数低（4）、密度小，对X线吸收极少，使低能软X线能透过窗口射出，满足乳腺摄影需要。【为什么错】B管电流取决于灯丝电流；C窗口材料与焦点无关；D管电压由高压装置设定；E散热依靠绝缘油与阳极结构，与铍窗无关。", "tr": "铍窗的关键词是“透射率高、保留软X线”，与滤过方向相反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03062", "gs": ""}, {"id": "ZG-U03-1010", "t": "共用题干题", "s": "结合上述情景，医用X线高压变压器次级绕组中心点接地的目的是", "o": {"A": "使X线管两端对地电压各为管电压的一半，降低绝缘要求、保证安全", "B": "提高输出电压", "C": "减少电能损耗", "D": "稳定管电流", "E": "便于灯丝加热"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-002", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】次级中心点接地后，阳极、阴极对地电压均为管电压的一半，降低了对地绝缘要求，同时避免单端高压带来的安全隐患。【为什么错】B接地不影响输出电压幅值；C损耗与接地无关；D管电流稳定靠空间电荷补偿；E灯丝加热由灯丝变压器独立供电。", "tr": "“中心点接地”不是把其中一端接地，而是取次级绕组中点接地。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03058", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1011", "t": "共用题干题", "s": "结合上述情景，现代高频X线机高压发生器通常先将工频交流电转换为", "o": {"A": "高频交流电（逆变）后再升压整流", "B": "直流电后直接升压", "C": "三相交流后直接整流", "D": "低压直流电", "E": "脉冲电压"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-003", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】高频机采用逆变技术，将工频交流整流为直流后，经逆变器变换为数十kHz的高频交流，再经高压变压器升压整流，输出纹波小、kV稳定。【为什么错】B、C直接升压/整流是传统工频机型方式；D低压直流无法直接产生管电压；E“脉冲电压”描述不完整。", "tr": "高频机优点：体积小、重量轻、kV/mA精确稳定、输出纹波小。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03058", "gs": ""}, {"id": "ZG-U03-1012", "t": "共用题干题", "s": "结合上述情景，医用X线机高压电缆内的芯线一般有", "o": {"A": "3根，分别连接阳极、阴极和地线", "B": "2根，连接阳极与阴极", "C": "4根，供两组灯丝", "D": "1根同轴芯线", "E": "5根"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-004", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】高压电缆为三芯结构：阳极芯线、阴极芯线分别接X线管两极，第三芯为零电位（地线）芯线，与金属屏蔽层相连起保护作用。【为什么错】B缺地线不安全；C灯丝电流经阴极芯线传递，无需独立4芯；D单芯无法构成阳极-阴极回路；E无5芯标准结构。", "tr": "高压电缆从内到外：芯线、绝缘层、金属屏蔽层、保护层，屏蔽层接地防电击。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03058", "gs": ""}, {"id": "ZG-U03-1013", "t": "共用题干题", "s": "结合上述情景，下列X线高压整流方式中，输出电压波纹最小、X线质最稳定的是", "o": {"A": "单相全波整流", "B": "单相半波整流", "C": "自整流", "D": "三相十二波整流", "E": "无整流"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-005", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】三相十二波整流将三相电压多相叠加，输出波纹很小，管电压接近恒定，X线质稳定、输出效率高。【为什么错】A单相全波波纹仍较大；B半波仅半周期有输出；C自整流靠X线管自身整流，仅用于小型机；E无整流无法工作。", "tr": "高频逆变机输出波纹比三相十二波更小，二者均属“小波纹”考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03059", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1014", "t": "单选题", "s": "对同一部位摄影，将管电压从60kV升至70kV，若要保持探测器接收的X线量不变，应", "o": {"A": "减少mAs", "B": "增加mAs", "C": "增大焦点", "D": "缩短焦片距", "E": "降低管电压"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-006", "kp": "曝光参数应用", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】X线输出量与管电压平方近似成正比，kV升高后X线输出显著增加，需相应减少mAs才能保持影像密度不变。【为什么错】B方向相反；C焦点影响空间分辨力，不影响密度；D缩短焦片距会增大探测器照射量，方向不对；E题干已设定升高。", "tr": "“kV升高→mAs必须下降”是经典技术换算思路，高kV技术（胸片120～150kV）配低mAs。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1015", "t": "共用题干题", "s": "结合上述情景，床旁（移动式）X线机多采用", "o": {"A": "小型固定阳极X线管、单相电源，便于移动", "B": "大型旋转阳极X线管、三相电源", "C": "高频大功率球管", "D": "双X线管结构", "E": "永磁式主磁体"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MOB-001", "kp": "移动X线机", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (11)移动X线机", "ex": "【为什么对】移动式X线机要求体积小、重量轻、可灵活推送，故多采用小型固定阳极X线管与单相（220V）电源，功率较低。【为什么错】B、C高功率大体积设备不便移动；D移动机通常为单球管；E永磁体是MRI主磁体类型，与X线机无关。", "tr": "移动X线机功率小、X线质较软，床旁摄影需适当调整曝光条件。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03063", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1016", "t": "单选题", "s": "【病例】关于医用影像设备的结构与成像原理，下列描述符合实际的是。 结合上述情景，CR系统中成像板（IP）感光层采用的光激励荧光体是", "o": {"A": "氟卤化钡∶铕（BaFX:Eu²⁺）", "B": "非晶硒", "C": "碘化铯", "D": "锗酸铋", "E": "钨酸钙"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CR-001", "kp": "CR基本结构及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】IP感光层为氟卤化钡∶铕光激励荧光体，X线照射时Eu²⁺吸收能量形成潜影，激光激励时释放荧光。【为什么错】B非晶硒为直接转换DR材料；C碘化铯为间接转换DR闪烁体；D锗酸铋为PET探测器材料；E钨酸钙为老式增感屏材料。", "tr": "“光激励荧光体”是CR核心，与DR闪烁体的光电转换机制不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1017", "t": "单选题", "s": "结合上述情景，CR成像过程中，IP经X线照射后再用激光扫描读取，所利用的物理现象是", "o": {"A": "光激励发光（PSL）", "B": "光电效应", "C": "康普顿效应", "D": "热释光", "E": "荧光猝灭"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CR-002", "kp": "CR基本结构及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】激光激发IP中存储潜影的荧光体，使其释放与X线剂量成正比的可见光，即光激励发光，经光电倍增管转为电信号。【为什么错】B、C为X线与物质相互作用方式；D热释光用于剂量测量（TLD）；E荧光猝灭是发光效率降低的现象。", "tr": "CR是“激光读出潜影”，DR是“直接转电信号”，读出机制完全不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1018", "t": "单选题", "s": "结合上述情景，CR成像板（IP）读取图像后可再次使用，其残余潜影通过下列哪种方式清除", "o": {"A": "强光照射擦除", "B": "热水冲洗", "C": "化学定影", "D": "低温冷藏", "E": "高压放电"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CR-003", "kp": "CR基本结构及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (1)CR基本结构及成像原理", "ex": "【为什么对】IP读取后经强光（紫外/可见光）充分照射，将残余潜影擦除，即可重复使用。【为什么错】B、C为湿式胶片冲洗工艺；D冷藏无擦除作用；E高压放电会损坏IP。", "tr": "IP可重复使用数千次，但需防潮、防划伤并定期校准。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1019", "t": "共用题干题", "s": "结合上述情景，非晶硅（a-Si）平板探测器属于", "o": {"A": "间接转换型DR探测器", "B": "直接转换型DR探测器", "C": "CR成像板", "D": "CT气体探测器", "E": "影像增强器"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-001", "kp": "DR探测器结构性能及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】非晶硅平板探测器需先由闪烁体（碘化铯）将X线转为可见光，再经非晶硅光电二极管转为电信号，故属间接转换。【为什么错】B直接转换用非晶硒；C CR用IP；D气体探测器用于早期CT；E影像增强器为老式透视/DSA部件。", "tr": "“非晶硅＝间接（有闪烁体）、非晶硒＝直接（无闪烁体）”要记牢。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03045", "gs": ""}, {"id": "ZG-U03-1020", "t": "共用题干题", "s": "结合上述情景，非晶硒（a-Se）直接转换DR探测器将X线直接转换为", "o": {"A": "电子-空穴对电信号", "B": "可见光", "C": "荧光", "D": "热能", "E": "声波"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-002", "kp": "DR探测器结构性能及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】非晶硒受X线照射后直接产生电子-空穴对，在偏置电场作用下形成电信号，无可见光中间环节。【为什么错】B可见光是间接转换的中间产物；C荧光为闪烁体发光；D热能非有效转换方式；E与声学无关。", "tr": "直接转换无光散射环节，空间分辨力与DQE（量子检出效率）较高。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03046", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1021", "t": "共用题干题", "s": "结合上述情景，间接转换DR探测器采用柱状碘化铯（CsI）晶体作为闪烁体的主要目的是", "o": {"A": "引导可见光垂直传导，减少光扩散，提高分辨力", "B": "提高探测器耐压性能", "C": "降低X线探测下限", "D": "减少X线辐射剂量", "E": "便于散热"}, "d": "中", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-003", "kp": "DR探测器结构性能及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】柱状晶体结构像光纤一样引导可见光沿柱体向下传导，减少横向光扩散，使空间分辨力明显提高。【为什么错】B耐压与闪烁体材料无关；C灵敏度取决于材料对X线的吸收；D剂量降低是间接效应而非目的；E散热不是闪烁体功能。", "tr": "柱状碘化铯是间接转换DR维持高分辨力的关键结构设计。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03046", "gs": ""}, {"id": "ZG-U03-1022", "t": "单选题", "s": "【病例】关于医用影像设备的结构与成像原理，下列描述符合实际的是。 结合上述情景，CT值的单位及水的CT值分别是", "o": {"A": "HU，0", "B": "HU，1000", "C": "CT，0", "D": "dB，-1000", "E": "mA，0"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-001", "kp": "CT基本成像原理", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (4)CT基本成像原理", "ex": "【为什么对】CT值以亨氏单位（HU）表示，规定水的CT值为0，空气为-1000，致密骨约+1000。【为什么错】B水应为0而非1000；C单位应为HU而非CT；D dB为分贝单位，空气为-1000；E mA是管电流单位。", "tr": "CT值公式为CT值＝1000×(μx-μ水)/μ水，记住“水0、空气-1000、骨+1000”三个锚点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1023", "t": "共用题干题", "s": "结合上述情景，CT扫描中位于X线球管侧的前准直器（源准直器）的主要作用是", "o": {"A": "限定X线束宽度，决定层厚并减少散射线", "B": "滤除低能X线、硬化线束", "C": "探测X线强度", "D": "承载被检者", "E": "重建图像"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-002", "kp": "CT硬件结构", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】前准直器用于限定X线束的宽度与形状，决定扫描层厚并减少散射线照射。【为什么错】B硬化滤过由楔形滤过器完成；C探测X线是探测器与数据采集系统的任务；D承载患者是扫描床；E重建是计算机系统的功能。", "tr": "前准直器管“层厚与散射线”，楔形滤过器管“能谱硬化”，两者功能勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03044", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1024", "t": "共用题干题", "s": "结合上述情景，目前多层螺旋CT普遍采用的探测器类型是", "o": {"A": "固体闪烁探测器（闪烁晶体＋光电二极管）", "B": "气体电离室探测器", "C": "影像增强器", "D": "非晶硒平板探测器", "E": "IP成像板"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-003", "kp": "CT硬件结构", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】固体探测器（如硫氧化钆GOS等闪烁晶体配光电二极管）灵敏度高、响应快，是现代CT主流探测器。【为什么错】B气体探测器（氙电离室）为早期CT所用；C影像增强器用于透视/DSA；D非晶硒用于DR直接转换；E IP是CR部件。", "tr": "CT探测器固体化、多层化是发展趋势，GOS是常用闪烁材料。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03044", "gs": ""}, {"id": "ZG-U03-1025", "t": "共用题干题", "s": "结合上述情景，螺旋CT实现X线球管向同一方向连续旋转扫描的关键技术是", "o": {"A": "滑环（电刷滑环）技术", "B": "磁悬浮机架技术", "C": "液态金属轴承技术", "D": "高压电缆直接供电", "E": "无线充电技术"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-004", "kp": "螺旋CT结构特点", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】滑环技术以环状电刷滑环替代缠绕的高压电缆，使球管可向同一方向连续旋转，为螺旋扫描提供基础。【为什么错】B磁悬浮机架是减摩技术之一，非连续旋转的关键；C液态金属轴承是球管轴承技术；D高压电缆直连会缠绕，无法连续旋转；E无无线充电供电方式。", "tr": "螺旋CT三要素：滑环、球管连续旋转、扫描床连续移动。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03064", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1026", "t": "共用题干题", "s": "结合上述情景，单层螺旋CT扫描时，螺距（pitch）为1.5、准直层厚5mm，则机架旋转一圈扫描床移动的距离为", "o": {"A": "7.5mm", "B": "5.0mm", "C": "3.3mm", "D": "10.0mm", "E": "15.0mm"}, "d": "难", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-005", "kp": "螺旋CT结构特点", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】螺距＝床移动距离/准直宽度，故床移动距离＝1.5×5＝7.5mm。【为什么错】B为螺距1时的移动量；C为螺距小于1时的移动量（5/1.5≈3.3mm）；D、E与给定条件不对应。", "tr": "螺距公式“螺距＝每圈进床距离/准直宽度”，与“螺距＝床速×扫描时间/层厚”本质一致。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03064", "gs": ""}, {"id": "ZG-U03-1027", "t": "共用题干题", "s": "结合上述情景，DSA数字减影成像的基本原理是", "o": {"A": "造影图像减去蒙片（mask）图像", "B": "两张造影图像相减", "C": "能量相加", "D": "图像时间相加", "E": "图像锐化增强"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-001", "kp": "DSA成像原理", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】先采集无对比剂的蒙片，再采集含对比剂的造影图像，两者像素逐一相减，去除骨骼与软组织背景，仅保留血管影像。【为什么错】B减影必须在蒙片与造影图之间进行；C能量相加无减影意义；D时间相加不能消除背景；E锐化是图像后处理，非减影原理。", "tr": "“蒙片＋造影图→相减”是最基础的时间减影方式。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03048", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1028", "t": "共用题干题", "s": "结合上述情景，DSA检查中应用最广泛的减影方式是", "o": {"A": "时间减影", "B": "能量减影", "C": "混合减影", "D": "空间减影", "E": "密度减影"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-002", "kp": "DSA成像原理", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】时间减影（mask方式）简便有效、设备要求低，是临床应用最广的减影方式。【为什么错】B能量减影需双能量X线，设备复杂；C混合减影为时间＋能量减影的结合；D空间减影需双X线管；E无“密度减影”标准术语。", "tr": "时间减影分为常规、脉冲、超脉冲、连续等模式，均属mask减影。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03048", "gs": ""}, {"id": "ZG-U03-1029", "t": "共用题干题", "s": "结合上述情景，临床上最常用、场强最高的MRI主磁体类型是", "o": {"A": "超导磁体", "B": "常导磁体", "C": "永磁体", "D": "电磁铁", "E": "混合磁体"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-001", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】超导磁体采用铌钛合金线圈，在液氦（约4.2K）低温下电阻为零，可产生高而稳定的磁场（1.5T、3T）。【为什么错】B常导磁体功耗大、场强低；C永磁体场强低（多小于0.5T）；D电磁铁为早期分类；E混合磁体非常规主流。", "tr": "超导磁体的关键：超导材料＋液氦低温环境，发生失超后磁场迅速消失。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03049", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1030", "t": "共用题干题", "s": "结合上述情景，氢质子（¹H）的旋磁比γ约为", "o": {"A": "42.58MHz/T", "B": "10.7MHz/T", "C": "11.26MHz/T", "D": "63.87MHz/T", "E": "3.2MHz/T"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-002", "kp": "MR成像基本原理", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】氢质子的旋磁比约42.58MHz/T，拉莫尔频率f＝γ×B0。【为什么错】B、C为其他核素（如碳、磷）相关数值；D为1.5T场强下的拉莫尔频率（42.58×1.5≈63.87MHz）；E无对应意义。", "tr": "42.58是“每特斯拉”的进动频率，实际进动频率＝42.58×场强。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03051", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1031", "t": "共用题干题", "s": "结合上述情景，MRI中梯度磁场的主要作用是", "o": {"A": "实现空间定位（选层、相位编码、频率编码）", "B": "产生主磁场", "C": "接收MR信号", "D": "发射射频脉冲", "E": "维持超导低温"}, "d": "易", "c": "理解", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-003", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】三组梯度线圈在X、Y、Z方向叠加线性变化磁场，使不同位置质子进动频率不同，完成选层、相位编码与频率编码定位。【为什么错】B主磁场由主磁体产生；C信号由接收线圈接收；D射频激励由发射线圈完成；E低温维持与梯度无关。", "tr": "梯度磁场是“空间编码”工具，梯度场强与爬升率决定成像速度与最小FOV。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03049", "gs": ""}, {"id": "ZG-U03-1032", "t": "共用题干题", "s": "结合上述情景，关于组织T1弛豫的叙述，正确的是", "o": {"A": "脂肪T1短，T1加权像上呈高信号", "B": "脂肪T1长，T1加权像上呈低信号", "C": "水T1短，T1加权像上呈高信号", "D": "钙化T1长，呈高信号", "E": "T1弛豫时间与场强无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-004", "kp": "MR成像基本原理", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】脂肪分子运动频率接近拉莫尔频率，纵向弛豫快、T1短，T1加权像呈高信号。【为什么错】B将脂肪T1说反；C水的T1长，T1WI呈低信号；D钙化T1WI多呈低信号；E T1弛豫时间随场强升高而延长。", "tr": "“T1短＝亮（T1WI高信号）”，脂肪亮、水黑是T1WI的记忆口诀。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ03051", "gs": ""}, {"id": "ZG-U03-1033", "t": "共用题干题", "s": "结合上述情景，下列属于X线管产生X线必备条件的是", "o": {"A": "灯丝加热发射电子", "B": "管壳内保持高度真空", "C": "阴极与阳极之间施加高压加速电子", "D": "用强磁场聚焦电子束", "E": "靶面材料为放射性物质"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-009", "kp": "X线管产生X线的过程", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (2)X线管产生X线的过程", "ex": "【为什么对】产生X线需具备：热阴极灯丝加热发射电子（A）、真空管壳保证电子自由飞行（B）、高压电场加速电子并轰击靶面（C）。【为什么错】D X线管采用聚焦罩静电聚焦，而非强磁场聚焦；E靶面须为原子序数高、熔点高的材料（如钨），放射性物质并不是必要条件。", "tr": "X线管聚焦用静电聚焦罩，与CRT用磁场聚焦不同，勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03052", "gs": ""}, {"id": "ZG-U03-1034", "t": "共用题干题", "s": "结合上述情景，旋转阳极X线管相对于固定阳极X线管的优点包括", "o": {"A": "散热面积大，可承受更大的瞬时功率", "B": "可在保持较小有效焦点的同时提高功率", "C": "适合连续快速曝光", "D": "无需高压供电", "E": "使用寿命无限长"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-010", "kp": "旋转阳极X线管", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (4)旋转阳极X线管", "ex": "【为什么对】旋转阳极使热量分布于整个靶盘，散热面积大、功率高（A），因而能在保持小有效焦点的情况下提供大功率（B），适应连续快速曝光（C）。【为什么错】D X线管必须高压供电才能加速电子；E任何X线管都有使用寿命（灯丝老化、靶面损伤），并非无限长。", "tr": "旋转阳极解决散热/功率问题，但X线管总体寿命仍然有限。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03061", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1035", "t": "共用题干题", "s": "结合上述情景，X线管管套的主要作用包括", "o": {"A": "高压绝缘（防电击）", "B": "散热", "C": "防X线泄漏（辐射防护）", "D": "缩小焦点", "E": "调节管电压"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-011", "kp": "X线管管套", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (6)X线管管套", "ex": "【为什么对】管套内充绝缘油并带铅防护，承担高压绝缘防电击（A）、散热（B）、防X线泄漏（C）三大功能。【为什么错】D焦点由灯丝与聚焦罩决定，与管套无关；E管电压由高压发生器调节。", "tr": "管套内还有膨胀鼓、温度保护装置，但核心作用是绝缘、散热与辐射防护。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03054", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1036", "t": "共用题干题", "s": "结合上述情景，X线管阳极靶面材料应具备的条件包括", "o": {"A": "原子序数高", "B": "熔点高", "C": "热传导性能好", "D": "蒸发率高", "E": "质地松软易加工"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-012", "kp": "X线管规格与特性", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】靶材需原子序数高以产生高强度X线（A）、熔点高以耐受电子轰击（B）、热传导性好以利散热（C）。【为什么错】D蒸发率高会导致钨丝与靶面损耗加快，是不利因素；E质地松软不耐高温轰击，不满足要求。", "tr": "钨是唯一同时满足A、B、C条件的常用靶材；蒸发率低是其另一优点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03055", "gs": ""}, {"id": "ZG-U03-1037", "t": "共用题干题", "s": "结合上述情景，医用X线高压发生器的主要组成部件包括", "o": {"A": "高压变压器", "B": "灯丝变压器", "C": "整流器", "D": "高压交换闸", "E": "影像增强器"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-007", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】高压发生器由高压变压器、灯丝变压器、整流器及高压交换闸（多球管切换）等组成。【为什么错】E影像增强器属于透视/DSA成像部件，不属于高压发生器。", "tr": "高压交换闸用于多球管X线机在多个X线管之间切换高压回路。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ03059", "gs": ""}, {"id": "ZG-U03-1038", "t": "共用题干题", "s": "结合上述情景，高压电缆的组成部分包括", "o": {"A": "金属芯线", "B": "绝缘层", "C": "金属屏蔽层", "D": "外层保护套", "E": "光电倍增管"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-HVG-008", "kp": "医用X线高压装置", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (8)医用X线高压装置", "ex": "【为什么对】高压电缆由内到外依次为芯线（A）、高压绝缘层（B）、金属屏蔽层（C）与外层保护套（D），屏蔽层接地防电击。【为什么错】E光电倍增管是CR读出等光学探测部件，与高压电缆无关。", "tr": "金属屏蔽层接地是防止电缆击穿伤人的关键结构。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ03059", "gs": ""}, {"id": "ZG-U03-1039", "t": "多选题", "s": "结合上述情景，CR系统动态范围（宽容度）大带来的临床意义包括", "o": {"A": "允许曝光条件有较大偏差仍能获得满意图像", "B": "可经图像后处理补偿曝光不足或过量", "C": "空间分辨力显著高于直接DR", "D": "成像速度显著快于DR", "E": "无需任何后处理即可直接诊断"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CR-004", "kp": "CR图像处理技术", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (3)CR图像处理技术", "ex": "【为什么对】CR动态范围宽，曝光过/不足在一定范围内可经后处理校正获得满意图像（A、B）。【为什么错】C CR空间分辨力一般低于直接DR；D CR需激光逐行扫描读出，成像速度慢于DR；E CR图像仍需窗宽窗位等后处理优化。", "tr": "“宽容度大→允许曝光误差”是CR重要优势，但空间分辨力与成像速度是其短板。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-1040", "t": "共用题干题", "s": "结合上述情景，关于直接转换DR探测器（非晶硒）的特点，正确的是", "o": {"A": "X线直接转换为电信号，无可见光环节", "B": "无光散射，空间分辨力较高", "C": "量子检出效率（DQE）较高", "D": "必须使用碘化铯闪烁体", "E": "属间接转换方式"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-004", "kp": "DR探测器结构性能及成像原理", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (5)DR探测器结构性能及成像原理", "ex": "【为什么对】非晶硒受X线照射直接产生电子-空穴对（A），无光散射环节、空间分辨力高（B），量子检出效率高（C）。【为什么错】D碘化铯是间接转换（非晶硅）的闪烁体，非晶硒无需闪烁体；E非晶硒属直接转换，而非间接转换。", "tr": "“直接转换用非晶硒、间接转换用非晶硅＋碘化铯”是最常考的对应关系。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ03046", "gs": ""}, {"id": "ZG-U03-1041", "t": "共用题干题", "s": "结合上述情景，CT扫描设备硬件结构的组成部分包括", "o": {"A": "X线球管与高压发生器", "B": "探测器与数据采集系统（DAS）", "C": "准直器与滤过器", "D": "扫描床与图像重建计算机", "E": "IP成像板"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-006", "kp": "CT硬件结构", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (1)硬件结构", "ex": "【为什么对】CT硬件包括扫描架（球管、准直器、滤过器、探测器、DAS）、高压发生器、扫描床、计算机与操作台等（A、B、C、D）。【为什么错】E IP成像板是CR系统的部件，不属于CT。", "tr": "CT成像链“球管→准直器→滤过器→人体→探测器→DAS→重建”要整体记忆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03044", "gs": ""}, {"id": "ZG-U03-1042", "t": "共用题干题", "s": "结合上述情景，螺旋CT相对于非螺旋（步进式）CT的特点包括", "o": {"A": "球管连续旋转，扫描床连续移动", "B": "可进行任意位置的多平面重建", "C": "扫描速度快，利于动态与血管成像", "D": "必须使用双X线管", "E": "图像均为非容积数据"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-007", "kp": "螺旋CT结构特点", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】螺旋CT凭借滑环技术实现球管连续旋转与床连续移动（A），采集容积数据可任意重建（B），速度快利于CTA等（C）。【为什么错】D螺旋CT单球管即可实现，双源CT只是特殊类型；E螺旋CT获取的是容积数据，不是非容积数据。", "tr": "容积采集＋插值重建是螺旋CT与步进CT的本质区别。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03064", "gs": ""}, {"id": "ZG-U03-1043", "t": "多选题", "s": "多层螺旋CT（MSCT）的主要优势包括", "o": {"A": "一次旋转可同时采集多层图像，扫描速度更快", "B": "Z轴覆盖范围大，可薄层扫描实现各向同性成像", "C": "可进行心脏等运动器官的快速采集", "D": "球管与探测器数量均较单层CT成倍增加", "E": "辐射剂量必然低于单层CT"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-008", "kp": "螺旋CT结构特点", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】MSCT探测器排数多，一次旋转多层采集、速度快（A），Z轴覆盖大、可薄层各向同性（B），利于心脏与动态成像（C）。【为什么错】D MSCT探测器排数增加，但球管通常仍为一个（双源CT除外）；E辐射剂量与扫描方案相关，MSCT未必低于单层CT，且剂量管理需主动控制。", "tr": "MSCT不等于必然低剂量，恰恰需要重视辐射剂量优化。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-1044", "t": "共用题干题", "s": "结合上述情景，DSA的减影方式包括", "o": {"A": "时间减影", "B": "能量减影", "C": "混合减影", "D": "密度减影", "E": "光谱减影"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-003", "kp": "DSA成像原理", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】DSA基本减影方式分为时间减影、能量减影与混合减影（时间＋能量）三类。【为什么错】D、E“密度减影”“光谱减影”并非DSA标准减影方式术语。", "tr": "混合减影＝时间减影＋能量减影结合，能更好地消除软组织与骨骼运动伪影。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ03048", "gs": ""}, {"id": "ZG-U03-1045", "t": "多选题", "s": "DSA成像设备的主要组成部分包括", "o": {"A": "X线发生系统（球管、高压发生器）", "B": "平板探测器与电视系统", "C": "图像处理与存储计算机", "D": "高压注射器", "E": "超声探头"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-004", "kp": "DSA结构与功能", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】DSA设备由X线发生系统、平板探测器（或影像增强器）与电视系统、图像处理计算机及高压注射器组成。【为什么错】E超声探头属超声设备，不属于DSA。", "tr": "高压注射器是DSA实现对比剂快速恒速注入的重要配套设备。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U03-1046", "t": "共用题干题", "s": "结合上述情景，MRI主磁体的类型包括", "o": {"A": "超导磁体", "B": "常导磁体", "C": "永磁体", "D": "单极梯度磁体", "E": "射频聚焦磁体"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-005", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】MRI主磁体按产生方式分为超导磁体、常导磁体和永磁体三类。【为什么错】D梯度磁体是梯度系统的组成，不属主磁体；E射频聚焦磁体不是MRI标准部件。", "tr": "主磁体管“静磁场”，梯度线圈管“空间编码”，射频线圈管“激发与接收”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03049", "gs": ""}, {"id": "ZG-U03-1047", "t": "共用题干题", "s": "结合上述情景，MRI梯度系统在成像中的具体作用包括", "o": {"A": "实现选层", "B": "实现相位编码", "C": "实现频率编码", "D": "产生均匀主磁场", "E": "发射90°射频脉冲"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-006", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】梯度磁场沿三个方向线性变化，分别完成选层梯度（A）、相位编码梯度（B）和频率编码梯度（C）。【为什么错】D主磁场由主磁体产生；E 90°脉冲由射频发射系统产生。", "tr": "“选层、相位编码、频率编码”三梯度是MRI空间定位的核心，常考多选题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03050", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1048", "t": "共用题干题", "s": "结合上述情景，MRI射频系统的组成部分包括", "o": {"A": "射频发射（激发）线圈", "B": "射频接收线圈", "C": "射频功率放大器", "D": "梯度放大器", "E": "液氦压缩机"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-007", "kp": "MRI基本结构", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】射频系统包括射频发射线圈、接收线圈以及射频功率放大器等，负责发射射频脉冲激发质子和接收MR信号。【为什么错】D梯度放大器属于梯度系统；E液氦压缩机属于超导低温保障系统。", "tr": "射频系统管“激发与接收”，梯度系统管“空间编码”，低温系统管“超导冷却”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ03050", "gs": ""}, {"id": "ZG-U03-1049", "t": "共用题干题", "s": "结合上述情景，医用高压注射器可预先设定的参数包括", "o": {"A": "注射流速（ml/s）", "B": "对比剂总量", "C": "注射延迟时间", "D": "扫描床高度", "E": "窗宽窗位"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-001", "kp": "医用高压注射器", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (2)医用高压注射器", "ex": "【为什么对】高压注射器可设定流速、总量、延迟时间、压力上限及双期相方案等注射参数。【为什么错】D扫描床高度属CT设备运动控制；E窗宽窗位是图像显示参数，与注射器无关。", "tr": "双筒注射器一筒对比剂、一筒生理盐水，生理盐水用于冲管减少伪影。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ03060", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1050a", "t": "单选题", "s": "【病例】患者男，58岁，反复活动后胸闷、心前区压榨感3个月，疑诊冠状动脉粥样硬化性心脏病，拟行冠状动脉CTA检查。技师需根据设备条件与患者情况合理制定扫描方案。 若患者心率72次/分且配合屏气欠佳，欲获得高质量的冠脉图像，下列设备与技术选择最合理的是", "o": {"A": "选择双源CT等高时间分辨力设备，配合心电门控采集", "B": "嘱患者浅快呼吸下完成扫描", "C": "降低管电压至70kV以下以缩短采集时间", "D": "放弃CTA改行有创DSA", "E": "增大螺距至3以加快扫描"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-009", "kp": "心脏CTA时间分辨力", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】冠脉CTA对时间分辨力要求高，双源CT等高时间分辨力设备配合心电门控（回顾性或前瞻性门控）可在较高心率下获得清晰冠脉图像。【为什么错】B心脏搏动不受呼吸控制，浅快呼吸不能解决心脏运动伪影；C降低kV主要影响对比噪声比，不能缩短采集时间；D DSA为有创检查，非首选初筛手段；E螺距过大降低Z轴分辨力，不利于细小冠脉显示。", "tr": "高心率冠脉成像的关键是时间分辨力与心电门控，而非单纯调整kV或螺距。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1050b", "t": "单选题", "s": "扫描完成后，技师进行冠脉图像后处理，最常用于完整显示冠脉全程走行的重建方式是", "o": {"A": "曲面重组（CPR）", "B": "多平面重组（MPR）", "C": "最大密度投影（MIP）", "D": "表面遮盖显示（SSD）", "E": "仿真内镜（VE）"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-010", "kp": "CT图像后处理技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (2)软件结构", "ex": "【为什么对】曲面重组（CPR）可沿冠脉走行方向拉直血管，完整显示管腔与管壁全程，最适合冠脉评估。【为什么错】B MPR为直平面重组，单帧难以容纳全程弯曲的冠脉；C MIP适合显示高密度血管整体形态，但缺乏管壁细节与层次；D SSD仅显示表面轮廓，无管腔内部信息；E仿真内镜多用于管腔内部观，受阈值与狭窄影响大，非冠脉首选。", "tr": "冠脉狭窄评估常用CPR＋VR＋轴位综合分析，其中CPR是显示全程的关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CR与DR成像设备", "页": 51}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1050c", "t": "单选题", "s": "该患者检查前口服美托洛尔将心率降至58次/分，改用前瞻性心电门控采集，其主要优点是", "o": {"A": "辐射剂量较回顾性门控显著降低", "B": "无需控制心率即可完成", "C": "可获得任意心动周期的图像", "D": "时间分辨力必然高于双源CT", "E": "不受心律失常影响"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-011", "kp": "心电门控技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】前瞻性门控仅在特定心动时相（如舒张期）曝光，辐射剂量较全心动周期采集的回顾性门控显著降低。【为什么错】B正因心率需较低且稳定才适用前瞻性门控；C回顾性门控才能任意选择时相重组；D时间分辨力取决于设备硬件而非门控方式；E心律失常时前瞻性门控易采集失败，对心律要求更高。", "tr": "前瞻性门控低剂量但要求心率低且规则，回顾性门控剂量高但允许任意时相重组。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1051a", "t": "单选题", "s": "【病例】患者女，46岁，头痛伴视物模糊3个月，MRI平扫示鞍区占位，拟行鞍区MRI增强扫描进一步明确血供与强化特点。技师负责制定扫描方案。 鞍区增强扫描首选的磁体类型与序列组合是", "o": {"A": "高场强超导磁体（如3.0T）行T1WI增强扫描", "B": "低场永磁体行T2WI增强扫描", "C": "行T2WI非增强扫描", "D": "行DWI增强扫描", "E": "行FLAIR增强扫描"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-008", "kp": "MRI增强扫描方案", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】鞍区占位增强应选用高场强磁体行T1WI增强，钆对比剂缩短T1使强化组织在T1WI呈高信号。【为什么错】B低场磁体信噪比低，且增强观察必须用T1WI；C无对比剂无法评估血供；D DWI反映水分子扩散，不是增强序列；E FLAIR主要抑制脑脊液信号，非增强首选。", "tr": "MR增强必须用T1WI观察强化，对比剂为钆类顺磁性对比剂。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1051b", "t": "单选题", "s": "检查前患者告知身上携带的银行卡疑似失效，最可能的原因是", "o": {"A": "主磁场对磁卡磁性介质产生破坏性磁化", "B": "射频脉冲烧毁磁卡", "C": "梯度磁场噪声干扰磁卡", "D": "液氦泄漏损伤磁卡", "E": "静电放电损伤磁卡"}, "d": "中", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-009", "kp": "MRI安全保障体系", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (2)保障体系", "ex": "【为什么对】MRI主磁场为强静磁场，含磁性介质的磁卡等物品进入强磁场会被磁化而损坏数据。【为什么错】B射频脉冲作用于人体质子，能量低且时间短，不会烧毁磁卡；C梯度场在扫描时快速变化，但破坏磁卡的是静磁场本身；D液氦泄漏与磁卡损坏无关；E静电非主要原因。", "tr": "检查前须去除一切铁磁性物品与磁卡，这是MRI安全制度的重点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1051c", "t": "单选题", "s": "若增强扫描需抑制脂肪信号以突出病灶边缘强化，技师宜选用的技术是", "o": {"A": "脂肪抑制技术（如SPAIR、STIR或Dixon）", "B": "增加扫描层厚", "C": "增大扫描视野（FOV）", "D": "降低翻转角", "E": "关闭梯度磁场"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-010", "kp": "脂肪抑制技术", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】脂肪抑制序列（SPAIR、STIR、Dixon等）可抑制脂肪高信号，避免其掩盖或混淆病灶强化。【为什么错】B增加层厚降低空间分辨力，不能压脂；C增大FOV与脂肪抑制无关；D降低翻转角影响图像对比，而非脂肪抑制；E梯度磁场不可关闭，关闭后无法成像。", "tr": "脂肪抑制技术包括频率选择法（SPAIR/SPIR）、反转恢复法（STIR）与Dixon水脂分离等。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1052a", "t": "单选题", "s": "【病例】患者男，62岁，突发右侧肢体无力伴言语不清2小时，临床疑诊急性脑梗死并需排除脑动脉瘤破裂出血，拟行全脑血管DSA检查。技师需制定合理的成像方案。 全脑血管DSA检查中，对比剂应采用的注射方式是", "o": {"A": "高压注射器恒速注入，流速与总量按靶血管设定", "B": "手推缓慢注入", "C": "静脉滴注", "D": "口服对比剂", "E": "皮下注射"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-005", "kp": "DSA高压注射技术", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】脑血管DSA需在规定时间内快速、恒速注入足量对比剂以维持血管内浓度，必须使用高压注射器。【为什么错】B手推无法保证恒速与流量；C静脉滴注流速过慢无法显影；D口服适用于消化道造影；E皮下注射无法进入血循环。", "tr": "颈内动脉、椎动脉等不同靶血管的流速与总量参数不同，需个体化设定。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1052b", "t": "单选题", "s": "检查中患者轻微头部移动导致减影图像出现运动伪影，技师首选的处理方法是", "o": {"A": "采用像素移位（重配准）技术校正", "B": "增加对比剂用量", "C": "更换X线管", "D": "无限提高采集帧率", "E": "放弃减影直接透视"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-006", "kp": "DSA运动伪影校正", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】像素移位技术通过移动蒙片或造影图使运动区域重新对齐，可有效减轻减影运动伪影。【为什么错】B增加对比剂不能消除运动伪影；C球管与伪影成因无关；D提高帧率增加剂量且不能校正已采集图像的运动错位；E放弃减影则失去DSA血管减影的意义。", "tr": "像素移位仅对小范围平移有效，明显运动需重新采集或改用混合减影。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1053a", "t": "单选题", "s": "【病例】患者男，76岁，ICU重症肺炎，行气管插管机械通气，需床旁胸部DR复查肺部感染及管路位置。技师携带移动DR至床旁检查。 床旁胸部摄影技师宜优先选择的探测器类型是", "o": {"A": "无线平板探测器（无线DR），便于灵活摆放并即时成像", "B": "有线探测器固定于摄影机架", "C": "CR暗盒（IP板）回科室后激光读取", "D": "影像增强器", "E": "湿式胶片暗盒"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-005", "kp": "床旁DR摄影技术", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (4)DR基本结构及特性", "ex": "【为什么对】床旁摄影空间受限、患者移动不便，无线平板探测器可置于患者身下快速成像，即时确认图像质量。【为什么错】B有线探测器受线缆限制不便床旁使用；C CR需将IP送回科室读取，无法即时质控；D影像增强器用于透视；E湿式胶片需化学处理，无法即时显示。", "tr": "无线DR＋移动X线机是ICU床旁摄影的现代主流配置。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1053b", "t": "单选题", "s": "该患者屏气配合差、呼吸急促，为减少运动模糊，技师应采用的摄影技术是", "o": {"A": "高千伏、短时间曝光，嘱患者浅呼吸", "B": "低千伏、长时间曝光", "C": "增大mAs延长曝光时间", "D": "取消滤线栅同时延长曝光", "E": "降低管电压至40kV"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-006", "kp": "胸部DR摄影技术", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (4)DR基本结构及特性", "ex": "【为什么对】呼吸运动模糊需缩短曝光时间解决，高kV配合低mAs可实现短时曝光，减少运动伪影。【为什么错】B长时间曝光加重运动模糊；C延长曝光时间更差；D取消滤线栅会增大散射线，且延长曝光方向不对；E低kV穿透力不足，需延长曝光时间。", "tr": "“呼吸控制差→高kV、短时间、适当增加mA”是胸部摄影减少运动伪影的原则。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "普通X线设备", "页": 41}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1054", "t": "案例分析题", "s": "患者男，45岁，体检发现肝右叶占位2周，拟行腹部增强CT明确病灶血供特点，设备为64层螺旋CT。技师需制定对比剂注射与扫描方案。下列扫描方案中最合理的是", "o": {"A": "双筒高压注射器注入对比剂（碘浓度300～370mgI/ml）80～100ml，流速3～4ml/s，行动脉期与门静脉期双期扫描", "B": "单筒注射对比剂后延迟10分钟单期扫描", "C": "以1ml/s低速注射后扫描一次完成", "D": "不用对比剂直接行平扫", "E": "对比剂经口服途径引入后扫描"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-012", "kp": "腹部CT增强方案", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (4)CT基本成像原理", "ex": "【为什么对】腹部占位定性需动脉期与门静脉期双期动态增强，双筒注射器保证团注后用生理盐水冲管，流速3～4ml/s可获得良好强化。【为什么错】B单期延迟扫描无法观察动脉期血供；C流速过慢难以形成对比剂团注；D平扫无法评估血供与强化特征；E口服对比剂不进入血循环，不能增强实质与血管。", "tr": "肝脏增强的动脉期、门静脉期、延迟期“三期时相”选择是经典考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1055", "t": "案例分析题", "s": "患者男，50岁，突发胸背部撕裂样疼痛伴双侧血压不对称2小时，疑诊主动脉夹层，急诊行主动脉CTA。患者心率95次/分且躁动不安。技师应优先采取的成像策略是", "o": {"A": "采用双源CT或高时间分辨力设备行胸腹主动脉CTA，必要时配合心电门控并稳定患者", "B": "常规行腹部CT平扫", "C": "嘱患者剧烈咳嗽后重新扫描", "D": "降低对比剂浓度至200mgI/ml以下", "E": "停止检查改用消化道造影"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-013", "kp": "主动脉CTA成像技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (3)螺旋CT结构特点", "ex": "【为什么对】主动脉夹层CTA需大范围快速扫描捕捉对比剂首过，高时间分辨力CT配合心电门控可减少主动脉搏动伪影，同时需稳定患者减少运动伪影。【为什么错】B平扫无法显示内膜片及真假腔强化特征；C咳嗽不能解决时间分辨力问题；D对比剂浓度过低影响血管显影；E消化道造影不能诊断主动脉夹层。", "tr": "主动脉CTA关键在“快速、大范围、团注追踪”，内膜片显示需清晰对比。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1056", "t": "案例分析题", "s": "患儿男，5岁，头部外伤后头痛、呕吐3小时，拟行头颅CT排除颅内出血，患儿哭闹不配合。关于该患儿CT检查的技术决策，正确的是", "o": {"A": "采用低剂量方案（降低mAs并优化kV），必要时镇静后固定患儿再扫描", "B": "为获得清晰图像将mAs增至成人剂量", "C": "嘱患儿自行屏气配合扫描", "D": "放弃CT改行有创脑血管造影", "E": "加用滤线栅提高曝光量"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-CT-014", "kp": "儿童低剂量CT技术", "ch": "三、医学影像设备与成像原理 → 3.CT成像设备 → (4)CT基本成像原理", "ex": "【为什么对】儿童对辐射更敏感，头颅CT应遵循低剂量原则降低mAs，并通过镇静与固定减少运动伪影。【为什么错】B成人剂量违反防护最优化原则；C幼儿无法配合屏气；D有创血管造影辐射高、风险大，不适合颅脑外伤初筛；E滤线栅会增加剂量，与低剂量原则相反。", "tr": "儿童CT应遵循“尽可能低”原则，调整kV/mAs并优化扫描方案。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1057", "t": "案例分析题", "s": "患者女，68岁，突发右侧肢体无力、言语不清3小时，临床疑诊急性缺血性脑卒中，行急诊头颅MRI。技师为确诊急性梗死灶，应优先选择的序列是", "o": {"A": "弥散加权成像（DWI）", "B": "T1加权平扫", "C": "腹部冠状位T2加权", "D": "乳腺压脂序列", "E": "腰椎矢状位T2加权"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-011", "kp": "DWI临床应用", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】急性脑梗死细胞毒性水肿致水分子扩散受限，DWI数小时内即呈明显高信号，是诊断急性梗死的敏感序列。【为什么错】B T1WI早期梗死变化不明显；C、E为其他部位的无关序列；D乳腺压脂与脑梗死诊断无关。", "tr": "DWI高信号＋ADC低信号是急性梗死“弥散受限”的标志组合。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "MRI成像设备", "页": 86}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1058", "t": "案例分析题", "s": "患者女，52岁，超声发现肝右叶占位，拟行肝脏MRI平扫加动态增强进一步定性。关于肝脏动态增强MRI的技术要点，正确的是", "o": {"A": "静脉注射钆类对比剂，常规行T1WI多期动态增强（动脉期、门静脉期、延迟期）", "B": "使用硫酸钡对比剂行T1WI增强", "C": "只用T2WI观察病灶强化", "D": "仅行平扫，无需增强", "E": "对比剂口服后立即扫描"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-012", "kp": "肝脏动态增强MRI", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (3)MR成像基本原理", "ex": "【为什么对】肝脏占位定性需静脉注射钆类顺磁性对比剂行T1WI多期动态增强，观察各期强化模式。【为什么错】B硫酸钡为胃肠道X线对比剂，无MR增强作用；C强化必须在T1WI观察；D平扫无法评估血供与强化；E口服对比剂不进入肝实质血循环。", "tr": "肝脏动态增强强调时相准确性，动脉期强化模式对肝癌诊断至关重要。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1059", "t": "共用题干题", "s": "结合上述情景，患者男，30岁，篮球运动后右肩疼痛伴活动受限1周，临床疑肩袖损伤，拟行肩关节MRI。技师应采用的扫描策略是", "o": {"A": "使用专用肩关节表面线圈，行斜冠状位、轴位及斜矢状位薄层扫描，并加质子密度加权压脂序列", "B": "用体部线圈行轴位单层扫描", "C": "仅行矢状位T2加权扫描", "D": "不加线圈直接行大FOV扫描", "E": "用CT代替MRI完成检查"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-MRI-013", "kp": "关节MRI成像技术", "ch": "三、医学影像设备与成像原理 → 5.MRI成像设备 → (1)基本结构", "ex": "【为什么对】肩关节结构细小，需专用表面线圈提高信噪比，采用多平面薄层扫描，压脂质子密度序列利于显示肌腱损伤。【为什么错】B体部线圈信噪比低、分辨率不足；C单平面扫描易遗漏病灶；D大FOV降低空间分辨力；E CT软组织对比差，无法显示肌腱细微损伤。", "tr": "专用表面线圈是关节MRI提高图像质量的关键硬件。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03057", "gs": "关于医用影像设备的结构与成像原理，下列描述符合实际的是。"}, {"id": "ZG-U03-1060", "t": "共用题干题", "s": "结合上述情景，患者男，55岁，心电图提示前壁心肌缺血，拟行选择性冠状动脉DSA造影明确狭窄部位。关于冠脉造影的技术决策，正确的是", "o": {"A": "经股动脉或桡动脉穿刺插管，高压注射器按冠脉流量设定流速，多体位投照并配合减影", "B": "直接静脉注射大剂量对比剂", "C": "仅行正位单一体位投照", "D": "口服对比剂后摄片", "E": "不注射对比剂直接采集"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-007", "kp": "冠脉DSA成像技术", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (1)结构与功能", "ex": "【为什么对】冠脉造影需选择性插管至冠脉开口，以合适流速注入对比剂，多体位投照显示各血管段。【为什么错】B静脉注射对比剂被稀释，无法选择性显示冠脉；C单一体位无法全面显示弯曲分支；D口服对比剂不进入冠脉；E无对比剂无法显示管腔。", "tr": "Seldinger穿刺技术＋选择性造影＋多体位投照是冠脉DSA的三要素。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ03057", "gs": ""}, {"id": "ZG-U03-1061", "t": "案例分析题", "s": "患者女，48岁，突发剧烈头痛伴颈项强直，CT示蛛网膜下腔出血，疑颅内动脉瘤，拟行全脑血管DSA。为明确动脉瘤形态、瘤颈与载瘤动脉的关系，技师应优先执行的采集方式是", "o": {"A": "3D旋转DSA（旋转采集后三维重建）", "B": "静态蒙片减影单帧采集", "C": "消化道造影", "D": "腹部平片", "E": "乳腺X线摄影"}, "d": "难", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DSA-008", "kp": "3D旋转DSA技术", "ch": "三、医学影像设备与成像原理 → 4.DSA成像设备 → (2)DSA成像原理", "ex": "【为什么对】3D旋转DSA通过旋转机架多角度采集并三维重建，可立体显示动脉瘤形态、瘤颈与载瘤动脉关系，指导介入治疗。【为什么错】B单帧静态减影无法三维评估；C、D、E均与脑血管动脉瘤检查无关。", "tr": "颅内动脉瘤术前评估中，3D旋转DSA是提供解剖细节的金标准技术。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "CT成像设备", "页": 60}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1062", "t": "案例分析题", "s": "患者女，80岁，咳嗽、发热3天，拟行胸部正位DR检查。患者体弱、呼吸急促且不能站立。技师宜采取的摄影方式是", "o": {"A": "坐位或卧位前后位摄影，采用高千伏、短时间曝光并适当调整焦片距", "B": "标准站立后前位，嘱其深吸气后屏气", "C": "增大mAs延长曝光时间", "D": "使用乳腺摄影的低kV参数", "E": "放弃X线改用超声检查"}, "d": "中", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-DR-007", "kp": "卧位胸部摄影技术", "ch": "三、医学影像设备与成像原理 → 2.CR与DR成像设备 → (4)DR基本结构及特性", "ex": "【为什么对】体弱不能站立者取坐位或卧位前后位，为减少呼吸运动模糊采用高千伏、短时间曝光。【为什么错】B患者无法站立及屏气配合；C延长曝光加重运动模糊；D乳腺低kV参数穿透力不足，不适用胸部；E超声对肺部感染评价有限，不能替代X线。", "tr": "卧位前后位摄片心影略有放大，为体位相关的正常变异，判读时需注意。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1063", "t": "案例分析题", "s": "患者女，45岁，发现左乳肿块1周，拟行乳腺X线摄影（钼靶）诊断。关于乳腺X线摄影的技术决策，正确的是", "o": {"A": "采用钼靶X线管、小焦点、低管电压（约22～35kV），以头尾位（CC）与内外斜位（MLO）为标准体位", "B": "用普通钨靶球管行高千伏摄影", "C": "只拍摄一个投照位置", "D": "患者站立即可，无需压迫乳房", "E": "用CT完全替代钼靶检查"}, "d": "难", "c": "应用", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-013", "kp": "乳腺X线摄影技术", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (13)乳腺X线机", "ex": "【为什么对】乳腺摄影需软X线（钼靶）获得高软组织对比，小焦点提高分辨力，CC与MLO是标准双体位。【为什么错】B钨靶产生硬X线，软组织对比差；C单一体位易漏诊；D压迫是乳腺摄影规范操作，可减少散射线、均匀腺体厚度；E CT辐射剂量高且非乳腺筛查首选。", "tr": "乳腺X线摄影“钼靶、低kV、双体位、压迫”四个要点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-1064", "t": "案例分析题", "s": "某X线机连续完成多例高mAs摄影后，设备提示“阳极过热，暂停曝光”，而候诊区仍有患者排队。正确的技术处置是", "o": {"A": "合理安排曝光间隔，待阳极充分冷却后再继续曝光", "B": "强行连续曝光完成全部检查", "C": "提高kV、降低mAs并缩短间隔立即再摄", "D": "关闭散热风扇以减少能耗", "E": "随意调整灯丝电压继续曝光"}, "d": "中", "c": "分析", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-XRT-014", "kp": "X线管热容量管理", "ch": "三、医学影像设备与成像原理 → 1.普通X线设备 → (5)X线管的规格与特性", "ex": "【为什么对】X线管阳极热容量有限，过热保护是防止靶面熔化损坏球管，技师应合理安排曝光间隔使阳极充分散热。【为什么错】B强行曝光会损坏X线管；C缩短间隔加剧过热；D关闭散热风扇加重过热；E灯丝电压与过热保护无关，随意调整会损坏设备。", "tr": "阳极热容量以热单位（HU）计，合理安排连续曝光间隔是设备维护的重要措施。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "数字减影血管造影成像设备", "页": 78}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U03-9001", "t": "单选题", "s": "医用诊断级显示器为保证不同设备间灰阶显示一致，应定期按以下哪项标准进行校准", "o": {"A": "sRGB 色彩空间", "B": "DICOM 灰度标准显示函数（GSDF）", "C": "Adobe RGB 色彩空间", "D": "CIE LAB 均匀色彩空间", "E": "Rec.709 电视标准"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-009", "kp": "医用显示器校准标准", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (3)医用显示器", "ex": "【为什么对】B正确——医学影像显示须遵循 DICOM 第14部分定义的灰度标准显示函数（GSDF），将输入像素值映射到符合人眼对比度觉察特性的光强度，保证同一影像在不同显示器上呈现一致的灰阶与诊断信息。【为什么错】A、C为通用色彩空间，不针对医学灰阶一致性；D是色彩差异度量空间，非显示校准曲线；E是视频色彩标准，不适用于诊断显示器校准。", "tr": "易与 sRGB 混淆；医用显示器校准核心是 GSDF 而非普通显示器的 sRGB。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U03-9002", "t": "单选题", "s": "用于放射科诊断阅片的医用显示器，其空间分辨率通常不低于", "o": {"A": "0.5 百万像素（0.5 MP）", "B": "1 百万像素（1 MP）", "C": "2 百万像素（2 MP）", "D": "8 百万像素（8 MP）", "E": "16 百万像素（16 MP）"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-010", "kp": "诊断级显示器分辨率", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (3)医用显示器", "ex": "【为什么对】C正确——诊断级医用显示器一般要求 2 MP（约 1600×1200）及以上，乳腺、断层融合等精细阅片常用 3 MP、5 MP 甚至更高，以满足微小结构显示与灰阶分辨需求。【为什么错】A、B分辨率过低，多用于临床浏览或工作站导航，不宜作为诊断主力；D、E虽可达更高分辨，但\"通常不低于\"的起步门槛是 2 MP。", "tr": "不要把\"临床浏览级\"与\"诊断级\"分辨率混淆，诊断级起步多为 2 MP。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U03-9003", "t": "单选题", "s": "关于医用干式激光打印机与热敏打印机的成像原理，下列表述正确的是", "o": {"A": "热敏打印机需经激光扫描与显影定影过程", "B": "激光打印机通过热敏打印头直接加热成像介质显影", "C": "激光打印机利用激光扫描潜影、经显影定影形成影像；热敏打印机由热敏头直接加热成像介质显影，无需显影剂", "D": "两者均必须依赖银盐胶片才能成像", "E": "热敏打印的分辨率显著低于激光打印且不可用于诊断"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-011", "kp": "激光与热敏打印原理区别", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (1)医用打印机", "ex": "【为什么对】C正确——干式激光打印机以激光束扫描感光鼓形成静电潜影，再经显影、热定影将碳粉或染色剂固定在介质上；热敏打印机则由加热打印头直接对热敏介质加热显影，无需显影剂与定影组件，结构更简单。【为什么错】A、B将两者原理互换，均错；D两者均可使用专用干式介质，并非必须银盐胶片；E热敏打印也可达到诊断级分辨率，盲目贬低其用途错误。", "tr": "易把\"激光扫描显影\"与\"热敏头直接加热\"张冠李戴。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U03-9004", "t": "单选题", "s": "医用双筒高压注射器设置两个针筒的主要目的是", "o": {"A": "同时注射两种不同对比剂以提高浓度", "B": "一筒装载对比剂、另一筒装载生理盐水用于注射后冲刷，优化团注形态并减少残留", "C": "分别用于动脉期与静脉期以省去人工换筒", "D": "一筒装对比剂、一筒装急救药液以备过敏抢救", "E": "双筒交替工作以缩短扫描间隔时间"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-012", "kp": "高压注射器双筒设计", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备 → (2)医用高压注射器", "ex": "【为什么对】B正确——双筒设计一筒装对比剂、另一筒装生理盐水，团注对比剂后以盐水冲刷静脉与管路内残留对比剂，可提高上腔静脉及右心腔内对比剂浓度、减少高浓度伪影，并改善团注曲线形态，是动态增强与CTA的常规配置。【为什么错】A高浓度叠加并非常规目的；C动脉/静脉期由扫描时相决定而非双筒分别装载；D急救药液不应与对比剂注射器混用；E双筒并非为缩短扫描间隔设计。", "tr": "双筒\"冲刷\"目的易被误记为\"双对比剂\"或\"急救\"。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U03-9201", "t": "单选题", "s": "影像存储与传输系统（PACS）的核心功能不包括", "o": {"A": "图像采集与存储", "B": "图像传输与显示", "C": "图像后处理", "D": "替代医师诊断决策", "E": "工作流程管理"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-9201", "kp": "PACS功能", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备", "ex": "【为什么对】PACS 负责采集、存储、传输、显示、后处理与流程管理；诊断决策仍由医师完成。\n【为什么错】PACS 不替代诊断。", "tr": "PACS不替代诊断。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U03-9202", "t": "单选题", "s": "关于 RIS（放射信息系统），主要管理的是", "o": {"A": "设备硬件维修", "B": "检查预约、登记与报告流程", "C": "图像重建算法", "D": "患者缴费", "E": "网络路由"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "三", "un": "医学影像设备与成像原理", "kpid": "UNIT-03-AUX-9202", "kp": "RIS功能", "ch": "三、医学影像设备与成像原理 → 6.辅助成像设备", "ex": "【为什么对】RIS 管理放射科工作流程：预约、登记、分诊、报告与统计。\n【为什么错】硬件维修与重建算法非 RIS 核心。", "tr": "RIS管流程而非硬件。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "医学影像设备与成像原理", "节": "辅助成像设备", "页": 103}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U04-0101", "t": "共用题干题", "s": "结合上述情景，下列血管内用碘对比剂中，属于非离子型二聚体（等渗对比剂）的是", "o": {"A": "碘海醇（iohexol）", "B": "碘普罗胺（iopromide）", "C": "碘克沙醇（iodixanol）", "D": "泛影葡胺（diatrizoate meglumine）", "E": "碘佛醇（ioversol）"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-001", "kp": "碘对比剂的分类与代表药物", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】碘克沙醇由两个三碘苯环通过桥链连接而成，分子中含6个碘原子且在水溶液中不解离，故每个粒子携带6个碘，渗透压约290 mOsm/(kg·H₂O)，与人体血浆基本相等，是目前临床唯一广泛使用的等渗碘对比剂。【为什么错】A、B、E 碘海醇、碘普罗胺、碘佛醇均为非离子型单体，分子含3个碘、不解离，渗透压约为血浆的两倍（在300~350 mgI/ml 浓度下约600~800 mOsm/kg），属次高渗（低渗）对比剂。D 泛影葡胺为离子型单体，在水中解离为含3个碘的阴离子与葡甲胺阳离子，渗透压高达1500~2100 mOsm/kg，属高渗对比剂，血管内应用已基本被淘汰。", "tr": "\"低渗\"是相对高渗离子型而言的历史称谓，实际仍为血浆的两倍左右，规范表述应为\"次高渗\"；只有非离子型二聚体才真正等渗。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04086", "gs": ""}, {"id": "ZG-U04-0102", "t": "单选题", "s": "碘对比剂溶液中\"碘原子数与溶质粒子数之比\"（碘／粒子比）是判断其渗透压高低的结构性指标。下列关于四类碘对比剂碘／粒子比的组合，正确的是", "o": {"A": "离子型单体3∶2、非离子型单体3∶1、离子型二聚体6∶2、非离子型二聚体6∶1", "B": "离子型单体3∶1、非离子型单体3∶2、离子型二聚体6∶1、非离子型二聚体6∶2", "C": "离子型单体3∶2、非离子型单体6∶1、离子型二聚体3∶1、非离子型二聚体6∶2", "D": "离子型单体6∶2、非离子型单体3∶2、离子型二聚体3∶1、非离子型二聚体6∶1", "E": "四类对比剂的碘／粒子比均为3∶1，渗透压差异仅由浓度决定"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-002", "kp": "碘／粒子比与渗透压的关系", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】渗透压取决于单位体积溶液中的粒子数目，而成像效果取决于碘原子数目，因此碘／粒子比越高，达到同样碘浓度所需的粒子越少、渗透压越低。离子型单体一个三碘苯环解离为阴、阳两个粒子，故为3∶2；非离子型单体不解离，为3∶1；离子型二聚体（如碘克沙酸）含6碘但解离为2个粒子，等效为3∶1；非离子型二聚体含6碘且不解离，为6∶1，渗透压最低，可达等渗。【为什么错】B 把离子型单体与非离子型单体的比值对调，并把离子型二聚体误作不解离。C、D 均为各项数值的错误搭配，未遵循\"是否解离\"与\"苯环数目\"两条判定线索。E 忽略了分子结构对粒子数的决定作用，若比值相同则不同类型对比剂在同浓度下渗透压应相等，与临床事实（泛影葡胺与碘克沙醇渗透压相差数倍）明显矛盾。", "tr": "解题只需两步：数苯环得碘数（单体3、二聚体6），判断是否解离定粒子数（离子型2、非离子型1）；离子型二聚体与非离子型单体等效为3∶1，是最易混淆的一对。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U04-0103", "t": "共用题干题", "s": "结合上述情景，在高流率注射的 CTA 检查中，对比剂的黏度直接影响注射压力与团注质量。关于碘对比剂黏度，正确的表述是", "o": {"A": "黏度只与渗透压有关，与温度无关", "B": "黏度随碘浓度升高而升高、随温度降低而升高；同等碘浓度下二聚体的黏度高于单体；将对比剂加温至37 ℃ 可明显降低黏度，便于高流率注射并减少注射压力", "C": "把对比剂加温至37 ℃ 的主要目的是降低其渗透压", "D": "同等碘浓度下，非离子型二聚体的黏度低于非离子型单体", "E": "黏度升高有利于降低注射系统所需的推注压力"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-003", "kp": "碘对比剂的黏度及其临床意义", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】黏度由分子体积、分子间作用力与溶液浓度共同决定。碘浓度越高、分子越大（二聚体分子量约为单体的两倍），黏度越高；温度升高使分子热运动加剧、分子间作用力减弱，黏度显著下降，通常从室温加温到37 ℃ 可使黏度下降约三分之一至一半。这既降低了注射器与留置针的压力负荷，也使团注更紧凑，是 CTA 高流率注射前必须预温的原因。【为什么错】A 温度是影响黏度最重要的可控因素，且黏度与渗透压是两个独立的理化参数（等渗的二聚体黏度反而最高）。C 加温对渗透压的影响可以忽略，其目的是降黏度、减少注射阻力与患者不适。D 与事实相反：非离子型二聚体虽然渗透压低，但分子大、黏度高，这正是它的主要缺点。E 逻辑颠倒：黏度越高，在相同流率下所需的推注压力越大，导管与静脉承受的压力也越高。", "tr": "等渗对比剂\"低渗透压、高黏度\"，次高渗单体\"较高渗透压、较低黏度\"，二者各有取舍；把\"等渗\"直接等同于\"更安全、更好推\"是常见误判。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04087", "gs": ""}, {"id": "ZG-U04-0104", "t": "共用题干题", "s": "结合上述情景，关于碘对比剂的理化特性与体内过程，下列表述正确的有", "o": {"A": "对比剂的X线衰减能力主要来自碘的高原子序数（Z＝53）及其 K 吸收缘（33.2 keV）附近显著增强的光电吸收", "B": "分子的亲水性好、亲脂性低，可减少与生物膜及血浆蛋白的相互作用，从而降低化学毒性", "C": "分子带电荷（离子型）会干扰细胞膜电位并影响血脑屏障，是离子型对比剂神经毒性相对较高的原因之一", "D": "渗透压越高越有利于减轻血管内皮损伤并保护红细胞的可变形性", "E": "血管内注入的碘对比剂主要经肝胆系统代谢后随胆汁排出体外"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-004", "kp": "碘对比剂的理化特性与毒性基础", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】A 光电效应的发生概率与原子序数的三次方成正比，并在 K 吸收缘处出现突跃，碘的 K 缘为33.2 keV，恰位于诊断能区内，这正是选碘作为造影元素的物理依据，也解释了为何低管电压（70~80 kV）时碘的 CT 值更高。B 现代非离子型对比剂在三碘苯环上引入大量羟基以增加亲水性、屏蔽苯环的疏水面，从而减少与蛋白和细胞膜的结合，化学毒性显著降低。C 离子型对比剂解离出的离子改变细胞外液的电解质环境与膜电位，是抽搐、意识改变等神经毒性反应相对多见的机制之一，故椎管内造影绝对禁用离子型对比剂。【为什么错】D 完全相反：高渗透压会使红细胞脱水、变形性下降甚至皱缩，损伤血管内皮、引起血管扩张与疼痛、加重肾小管损伤，正是高渗离子型对比剂被淘汰的核心原因。E 血管内碘对比剂几乎不参与代谢，以原形经肾小球滤过排出，肾小管基本不重吸收也不分泌；只有极少量在肾功能衰竭时经肝胆与肠道代偿排泄。", "tr": "\"碘对比剂经肾排泄、几乎不代谢\"是理解其肾毒性与二甲双胍相互作用的前提；把它误记为肝代谢会导致后续一系列临床判断失误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04087", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-0105", "t": "共用题干题", "s": "结合上述情景，按发生时间对碘对比剂不良反应进行分类，下列划分正确的是", "o": {"A": "急性反应指注射后24 h 内发生者", "B": "迟发反应指注射后1周至1个月内发生者", "C": "晚迟发反应指注射后24~72 h 内发生者", "D": "急性反应指注射后1 h 内发生；迟发反应指1 h 至1周内发生；晚迟发反应指1周以后发生，多表现为甲状腺功能异常等", "E": "急性反应特指过敏性休克，其他表现均归入迟发反应"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-005", "kp": "碘对比剂不良反应的时间分类", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】按发生时间划分为三类：急性反应发生于注射后1 h 内，多为类过敏样反应，是抢救的重点，故规定注射后留观至少30 min；迟发反应发生于1 h 至1周内，以皮肤反应（斑丘疹、瘙痒、迟发性荨麻疹）最常见，多为T细胞介导；晚迟发反应发生于1周之后，典型代表是碘诱导的甲状腺功能亢进或减退，也包括部分肾功能改变。【为什么错】A 把急性反应的时间窗放宽到24 h，会掩盖\"注射后30 min 是抢救黄金期\"这一临床原则。B 1周至1个月的划分与国际通行标准不符，1周之后即属晚迟发。C 24~72 h 仍在1周之内，属迟发反应范畴。E 急性反应涵盖从恶心、荨麻疹到休克的全部严重程度，把它窄化为过敏性休克会遗漏大量需要观察和处理的轻中度反应。", "tr": "记住三个时间节点\"1 h、1周\"即可分清三类；留观30 min 针对的是急性反应，出院前应告知患者迟发皮疹的可能并留下联系方式。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04079", "gs": ""}, {"id": "ZG-U04-0106", "t": "单选题", "s": "碘对比剂的急性不良反应按发生机制可分为类过敏样（特异质）反应与器官毒性（非特异质）反应两类。关于这一分型，正确的表述是", "o": {"A": "类过敏样反应与对比剂的剂量、浓度和注射速率无明确相关性，其机制涉及肥大细胞与嗜碱粒细胞的非 IgE 介导性组胺释放及补体激活，临床表现类似Ⅰ型变态反应", "B": "类过敏样反应的严重程度与所用对比剂剂量呈明确的正相关", "C": "器官毒性反应与剂量、渗透压及注射速率均无关", "D": "注射过程中出现的全身热感、恶心呕吐属于典型的类过敏样反应", "E": "对比剂肾病是类过敏样反应最常见的表现形式"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-006", "kp": "类过敏样反应与器官毒性反应的机制分型", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】类过敏样反应属个体特异质，极小剂量即可诱发严重反应，因此不能靠\"减量\"来预防；其机制并非经典的 IgE 介导过敏，而是对比剂直接激活肥大细胞与嗜碱粒细胞释放组胺，并可激活补体与凝血系统，故称\"类过敏样\"，但临床表现（荨麻疹、支气管痉挛、喉头水肿、休克）与Ⅰ型变态反应相同，抢救原则也一致。【为什么错】B 与特异质反应的定义直接矛盾；若与剂量正相关，则应归入器官毒性。C 器官毒性反应恰恰是剂量依赖性的，与总碘量、渗透压、黏度和注射速率密切相关，减少剂量、选用渗透压更低的对比剂即可降低其发生率。D 热感与恶心呕吐由高渗透压和化学刺激引起，属典型的器官毒性（生理性）反应，通常一过性、可自行缓解。E 对比剂肾病由渗透性利尿、肾髓质缺氧与肾小管上皮直接毒性所致，是剂量依赖的器官毒性反应，与特异质机制无关。", "tr": "分型决定对策：类过敏样反应靠既往史筛查、预处理与抢救准备，器官毒性反应靠减量、降渗透压、控制注射速率与水化；把热感、恶心当成\"过敏先兆\"而贸然停检是临床常见误判。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U04-0107", "t": "多选题", "s": "关于对比剂诱导的急性肾损伤（CI-AKI／PC-AKI）的危险因素与预防措施，下列表述正确的有", "o": {"A": "检查前已存在的肾功能不全是最重要的患者相关危险因素，eGFR 低于30 ml/(min·1.73 m²) 属高危", "B": "糖尿病肾病、脱水与低血容量、充血性心力衰竭、高龄以及同期使用肾毒性药物（非甾体抗炎药、氨基糖苷类等）均可增加发生风险", "C": "动脉内注射（尤其对比剂首过即通过肾脏的高剂量注射）的风险高于静脉内注射", "D": "等渗或次高渗对比剂的使用、控制总碘量并避免短期内重复给药，属对比剂相关的可控措施", "E": "常规预防性使用 N-乙酰半胱氨酸、呋塞米或甘露醇可有效降低其发生率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-007", "kp": "对比剂肾病的危险因素与预防", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】A 基础肾功能是风险分层的核心，eGFR 越低风险越高，30 是公认的高危界值。B 这些因素或减少肾血流、或加重肾髓质缺氧、或叠加肾小管毒性，共同放大风险。C 动脉内注射时对比剂以高浓度首过肾脏（如肾动脉、腹主动脉造影），肾脏局部暴露量远高于静脉注射后经体循环稀释者。D 对比剂相关的可控因素包括渗透压、黏度、总碘量与给药间隔，指南推荐两次注射间隔至少48~72 h，高危者更长。【为什么错】E 证据不支持：大型随机对照研究（如 PRESERVE 试验）显示 N-乙酰半胱氨酸并不优于安慰剂；而呋塞米、甘露醇等利尿剂在未充分补液的前提下会加重血容量不足，反而可能增加肾损伤风险，故不推荐常规使用。目前循证支持最充分的预防措施仍是充分的静脉水化。", "tr": "\"水化是硬道理，药物预防证据不足\"是本考点的主线；此外注意术语更新——因难以证明因果关系，现多用 PC-AKI（对比剂检查后急性肾损伤）替代传统的 CIN。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U04-0108", "t": "共用题干题", "s": "结合上述情景，一名65岁2型糖尿病患者长期口服二甲双胍，近期血肌酐升高，估算 eGFR 为25 ml/(min·1.73 m²)，因腹痛需行腹部增强 CT（静脉注射非离子型碘对比剂）。关于二甲双胍的处理，正确的做法是", "o": {"A": "无需停药，因为静脉注射不影响肾功能", "B": "检查前3天开始停药，检查结束后立即恢复", "C": "停药24 h 后即可恢复，无需复查肾功能", "D": "改用胰岛素后即可不受任何限制地大剂量使用对比剂", "E": "自注射对比剂时起停用二甲双胍，停药48 h 后复查肾功能，确认未进一步恶化方可恢复用药"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-008", "kp": "二甲双胍与碘对比剂的相互作用及停药规则", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】二甲双胍本身对肾脏无毒性，其经肾原形排泄；若使用对比剂后发生急性肾损伤，二甲双胍蓄积可诱发罕见但病死率很高的乳酸性酸中毒。现行指南按肾功能分层：eGFR≥30 且为静脉给药者一般无需停药；eGFR 低于30、或经动脉给药使对比剂首过肾脏、或已存在急性肾损伤者，应自注射对比剂时起停药48 h，其间充分水化，48 h 后复查肾功能确认未恶化再恢复。本例 eGFR 为25，属需停药人群。【为什么错】A 忽略了该患者已处于 eGFR 低于30 的高危区间。B 提前3天停药并无必要，且检查后立即恢复恰恰跳过了最危险的48 h 观察窗口，逻辑正好相反。C 24 h 不足以覆盖对比剂后急性肾损伤的高发时段（通常48~72 h 达峰），且省略复查肾功能这一关键环节。D 改用胰岛素只解决降糖药本身的蓄积问题，患者的肾损伤风险依然存在，对比剂仍应遵循最低有效剂量原则。", "tr": "关键在\"从注射时起停48 h\"而非\"检查前停48 h\"；同时须把停药与水化、复查肾功能作为整体方案，单纯停药并不降低急性肾损伤本身的风险。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04077", "gs": ""}, {"id": "ZG-U04-0109", "t": "共用题干题", "s": "结合上述情景，一名52岁男性行胸部增强 CT，经肘静脉以3.5 ml/s 注射非离子型碘对比剂80 ml。注射结束约5 min，患者在观察区突然出现全身皮肤潮红、大片荨麻疹、声音嘶哑伴吸气性喘鸣，主诉咽部堵塞感与呼吸困难；测血压80/50 mmHg，脉搏细速120次/分，血氧饱和度88%。检查室内配备完备的急救车、氧气、监护仪，抢救医师即刻到场。此时首要的药物处置是", "o": {"A": "立即静脉推注1∶1000 肾上腺素1 mg", "B": "立即静脉推注地塞米松10 mg 作为首选用药", "C": "立即肌内注射苯海拉明20 mg 作为首选用药", "D": "立即于大腿前外侧肌内注射1∶1000 肾上腺素0.3~0.5 mg（0.3~0.5 ml），必要时每5~15 min 重复，同时给予高流量吸氧、快速静脉补液并抬高下肢", "E": "立即皮下注射1∶10000 肾上腺素5 ml"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-009", "kp": "重度类过敏样反应的急救处理", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】本例同时具备皮肤黏膜表现、上气道梗阻（声嘶、喘鸣）与循环衰竭（低血压、心动过速），属重度类过敏样反应／过敏性休克。肾上腺素是唯一能同时逆转支气管痉挛、喉头水肿与血管扩张性低血压的一线药物，成人剂量为0.01 mg/kg、最大0.5 mg，采用1∶1000 浓度肌内注射于大腿前外侧股外侧肌（该部位血供丰富、吸收最快），必要时每5~15 min 重复。同时必须高流量吸氧、开放静脉快速输注晶体液并抬高下肢改善回心血量。【为什么错】A 1∶1000 原液静脉推注浓度过高，易引发高血压危象、室性心律失常甚至心肌缺血；静脉途径仅在有心电监护、循环衰竭或心搏骤停时由医师使用1∶10000 稀释液缓慢推注。B 糖皮质激素起效需数小时，只能用于预防双相反应，绝不能作为首选，延误肾上腺素给药是抢救失败的常见原因。C 抗组胺药仅能缓解皮肤瘙痒与荨麻疹，对喉头水肿与休克无效。E 皮下注射血供差、吸收慢且不可预测，休克时外周灌注更差，指南已不推荐；且该途径与剂量组合不符合现行规范。", "tr": "抢救顺序是\"肾上腺素肌注→吸氧→补液→体位→再考虑激素与抗组胺药\"；把激素或抗组胺药当作首选、或误用静脉原液推注，是最严重的两类错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04089", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-0110", "t": "多选题", "s": "关于碘对比剂急性不良反应的严重程度分级与相应处理，下列表述正确的有", "o": {"A": "散在荨麻疹且无呼吸循环受累者属轻度反应，可留观并视情况给予口服或肌注抗组胺药", "B": "支气管痉挛伴血氧饱和度下降属中重度反应，应立即吸氧并给予 β₂ 受体激动剂吸入，病情进展者使用肾上腺素", "C": "迷走神经反应表现为心动过缓合并低血压，处理为抬高下肢、快速静脉补液，必要时静脉给予阿托品0.5~1 mg", "D": "凡曾发生过轻度不良反应者，再次检查时都必须放弃一切增强检查", "E": "预防性使用糖皮质激素可以完全消除再次发生严重反应的风险"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-010", "kp": "不良反应的分级处理与迷走反应的鉴别", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】A 轻度反应多可自限，处理以观察为主，必要时对症用药，无需终止后续流程。B 支气管痉挛属中重度，吸氧与吸入型 β₂ 受体激动剂是初始处理，若出现血氧持续下降、意识改变或低血压则须及时给予肾上腺素。C 迷走神经反应的特征是\"慢＋低\"，即心动过缓合并低血压，与过敏性休克的\"快＋低\"（心动过速合并低血压）形成鲜明对照，处理为体位与扩容，心率持续过缓时静脉给予阿托品，误用肾上腺素并非首选。【为什么错】D 表述过于绝对：轻度反应者再次检查时应权衡获益与风险，可更换不同分子结构的对比剂、必要时预处理并加强观察，而非一概放弃增强这一重要诊断手段。E 预处理只能降低而不能消除风险，文献中已有充分预处理后仍发生严重反应的报道，故预处理绝不能替代急救准备与全程监护。", "tr": "\"心动过缓＋低血压\"想迷走反应、\"心动过速＋低血压\"想过敏性休克，是决定用阿托品还是肾上腺素的分水岭，务必牢记。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U04-0111", "t": "共用题干题", "s": "结合上述情景，关于X线对比剂的引入途径与适用情形，下列配伍错误的是", "o": {"A": "静脉尿路造影——静脉注射水溶性碘对比剂", "B": "子宫输卵管造影——经宫颈管直接注入水溶性碘对比剂", "C": "上消化道钡餐检查——口服硫酸钡混悬液", "D": "疑有消化道穿孔或术后吻合口瘘——首选口服硫酸钡混悬液", "E": "脊髓造影（椎管内注入）——只能使用经批准可鞘内使用的非离子型对比剂"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-011", "kp": "对比剂的引入途径与禁忌配伍", "ch": "四、对比剂 → 1.X线对比剂 → (3)引入途径", "ex": "【为什么对】本题选错误配伍。疑有消化道穿孔、吻合口瘘或需急诊手术者禁用硫酸钡：钡剂不溶于水、不能被吸收，一旦经破口进入腹腔将引起严重的钡剂性腹膜炎与广泛粘连，且极难清除。此类情况应改用水溶性碘对比剂，并在有误吸风险时选择非离子型等渗或次高渗制剂。【为什么错】A 静脉尿路造影依靠肾小球滤过后对比剂在集合系统内浓聚，静脉给药是标准途径。B 子宫输卵管造影经宫颈插管直接注入，属体腔内引入途径。C 钡剂涂布性好、密度高，是常规胃肠道造影的首选。E 椎管内属高风险途径，离子型对比剂可引起抽搐、蛛网膜炎等严重神经毒性反应，必须使用明确标注可鞘内使用的非离子型对比剂。", "tr": "\"疑穿孔用水溶性、有误吸风险避开高渗离子型\"是两条并行的安全底线；高渗离子型对比剂误吸入气道可引起肺水肿，选择时须同时兼顾这两点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04078", "gs": ""}, {"id": "ZG-U04-0112", "t": "共用题干题", "s": "结合上述情景，关于消化道造影中对比剂的选择原则，下列表述正确的有", "o": {"A": "硫酸钡不溶于水、不被吸收，黏附与涂布性能好，是常规胃肠道造影的首选对比剂", "B": "疑有消化道穿孔、拟急诊手术或存在明显误吸风险时，应改用水溶性碘对比剂", "C": "高渗离子型水溶性对比剂一旦误吸入气道可引起肺水肿，故对误吸高危者宜选用非离子型等渗或次高渗对比剂", "D": "钡剂进入腹腔后可被腹膜完全吸收，因此消化道穿孔并非其禁忌证", "E": "硫酸钡混悬液可用于静脉法血管造影"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-012", "kp": "钡剂与水溶性对比剂的选择", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】A 硫酸钡为不溶性混悬颗粒，原子序数高、密度大，能在黏膜表面形成均匀薄层，是显示黏膜微细结构的最佳选择。B 存在穿孔、瘘管或即将手术时，水溶性碘对比剂即使外漏也可被腹膜吸收并经肾排出，安全性远高于钡剂。C 高渗对比剂进入肺内会因渗透作用把大量液体拉入肺泡引起肺水肿，故吞咽功能障碍、意识不清、气管食管瘘等误吸高危患者应选用非离子型低／等渗制剂。【为什么错】D 与事实完全相反：钡剂进入腹腔不能被吸收，会引起化学性与异物性腹膜炎，形成致密粘连，是明确的绝对禁忌。E 硫酸钡为不溶性颗粒混悬液，进入血管将造成栓塞导致死亡，绝对不能用于任何血管内途径。", "tr": "\"钡剂只能进管腔、不能进血管、不能进腹腔\"是不可逾越的红线；D、E 两项虽然结论明显错误，但在紧张答题时仍常被误选，需建立牢固的安全反射。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04090", "gs": ""}, {"id": "ZG-U04-0113", "t": "共用题干题", "s": "结合上述情景，一名72岁女性，反复胸痛，心内科申请冠状动脉 CTA。既往史：3年前行增强 CT 后出现全身荨麻疹伴轻度咽部不适（判定为中度类过敏样反应），经处理后缓解；甲状腺功能亢进服甲巯咪唑治疗中，近期甲功已接近正常；体重52 kg，血肌酐正常，eGFR 78 ml/(min·1.73 m²)。检查当日抢救团队与急救药械齐备。作为 CT 技术组负责人，最合理的技术与安全方案是", "o": {"A": "重新评估检查的必要性并取得知情同意后，改用与既往所用品种不同的非离子型次高渗对比剂，按预案给予糖皮质激素与抗组胺药预处理，按体重个体化确定总碘量并适当降低注射流率，检查后留观至少30 min 且全程备好肾上腺素，同时告知内分泌科随访甲状腺功能", "B": "既往有中度过敏史即为绝对禁忌，应放弃 CTA 改行常规冠状动脉造影", "C": "甲亢患者禁用一切含碘对比剂，可改用钆对比剂完成 CT 冠状动脉成像", "D": "术前给予地塞米松后即可完全避免再次发生反应，检查结束即可离院", "E": "因肾功能正常，可采用最大剂量与最高流率以保证冠状动脉强化效果"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-013", "kp": "高危患者碘对比剂使用的综合决策", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】该患者存在两项风险：既往中度类过敏样反应史与甲状腺功能亢进。规范做法是先重新评估检查的必要性与替代方案，确有指征时更换不同分子结构的非离子型对比剂（交叉反应率因分子结构差异而下降），按预案给予糖皮质激素与抗组胺药预处理，按体重个体化控制总碘量并适当降低注射流率以减轻器官毒性负荷；既往有反应者留观时间应不短于30 min 并适当延长，全程备好肾上腺素。甲亢已控制者在权衡后可以使用，但须告知并随访甲功，因为碘负荷可能诱发甲亢加重或碘致甲状腺功能异常，属于典型的晚迟发反应。【为什么错】B 中度反应史属\"高危\"而非绝对禁忌；且常规冠状动脉造影同样需要注射碘对比剂，甚至因动脉内给药风险更高，该替代方案在逻辑上不成立。C 未控制的甲亢是相对禁忌，本例已接近正常，可在评估后使用；而钆对比剂在 CT 中的X线衰减能力远不足以替代碘剂，且大剂量使用会带来肾毒性与 NSF 风险，属于严重的原则性错误。D 预处理只能降低风险而不能消除，仍有发生严重反应的报道，检查后必须留观。E 与个体化用药原则背道而驰：52 kg 体重本应减量，最大剂量加最高流率会显著增加器官毒性反应与外渗风险。", "tr": "高危患者管理的四要素——换药、预处理、减量与降速、延长留观并备好抢救；\"用钆代替碘做 CT\"是必须警惕的错误答案，两者的X线衰减能力与安全窗完全不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ04091", "gs": ""}, {"id": "ZG-U04-0114", "t": "共用题干题", "s": "结合上述情景，一名58岁女性行胸部增强 CT，经肘正中静脉20 G 留置针以4.0 ml/s 注射非离子型碘对比剂。注射开始约3 s 后患者诉前臂胀痛，注射器压力曲线报警并自动终止推注。查体见注射侧前臂中段明显肿胀、皮肤张力增高、皮温略低，桡动脉搏动可及，手指活动与感觉正常，毛细血管充盈时间正常，估算外渗量约30 ml。作为当班技师，最恰当的处置是", "o": {"A": "立即局部热敷并用力按摩以促进对比剂吸收", "B": "在外渗部位注射透明质酸酶并即刻行切开减压", "C": "继续完成剩余对比剂的注射以保证图像质量", "D": "立即静脉注射糖皮质激素与利尿剂以加快对比剂排出", "E": "立即停止注射并拔除留置针，抬高患肢高于心脏水平，早期局部冷敷，详细记录外渗量与体征并观察2~4 h；若出现皮肤水疱、进行性肿胀、感觉异常或血循环障碍，立即请外科或整形科会诊"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-ICM-014", "kp": "碘对比剂血管外渗的处理", "ch": "四、对比剂 → 1.X线对比剂 → (3)引入途径", "ex": "【为什么对】绝大多数外渗为轻中度，处理原则是停止注射、抬高患肢促进静脉与淋巴回流、早期冷敷（24~48 h 内）以收缩血管、减轻炎症与肿胀，同时完整记录外渗量、部位与体征并留观2~4 h。本例虽有肿胀与张力增高，但循环、感觉与运动均正常，暂无骨筋膜室综合征证据，可按上述保守方案处理，并向患者交代随访要点与复诊指征。【为什么错】A 早期热敷会扩张血管、加重局部渗出与肿胀；用力按摩则可能使对比剂在组织间隙内进一步扩散并加重损伤。B 透明质酸酶的疗效证据有限，并非常规首选；切开减压属骨筋膜室综合征等严重并发症的紧急处置手段，本例尚无相应指征，贸然切开属过度治疗。C 已有外渗仍继续注射会使外渗量成倍增加，可能导致皮肤坏死甚至骨筋膜室综合征，是严重的操作错误。D 全身用糖皮质激素与利尿剂对局部外渗无确切疗效，利尿还可能造成血容量不足，反而增加肾损伤风险。", "tr": "\"早期冷敷、后期（48 h 后）可酌情热敷\"的时序不能颠倒；判断是否需要外科干预看四个信号——张力性水疱、感觉异常、进行性肿胀、末梢循环障碍。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04087", "gs": ""}, {"id": "ZG-U04-0115", "t": "共用题干题", "s": "结合上述情景，钆对比剂能够使邻近组织的 T1 明显缩短，从而在 T1WI 上呈现高信号。其发挥这一作用的主要机制是", "o": {"A": "钆本身能产生很强的 MR 信号，被接收线圈直接采集", "B": "Gd³⁺ 具有7个未成对电子、磁矩很大，通过偶极—偶极相互作用与邻近水质子交换能量，加快其纵向弛豫", "C": "钆改变了氢质子的进动频率，使其重新进入共振状态", "D": "钆通过降低组织的含水量而使信号强度升高", "E": "钆主要通过缩短 T2* 而在 T1WI 上产生高信号"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-001", "kp": "钆对比剂缩短 T1 的机制", "ch": "四、对比剂 → 2.MR对比剂 → (3)增强机制", "ex": "【为什么对】Gd³⁺ 的 f 轨道有7个未成对电子，是自然界磁矩最大的离子之一，其产生的强局部涨落磁场频率恰与质子的拉莫尔频率相近，通过偶极—偶极相互作用高效地把质子的纵向磁化能量传递给晶格，使 T1 显著缩短。这种作用要求水分子与顺磁中心足够接近（内球水交换为主，外球扩散为辅），因此对比剂只能\"间接\"改变周围质子的弛豫，而非自身成像。【为什么错】A 钆原子核并非成像核素，MR 图像的信号来自氢质子；对比剂是弛豫增强剂而不是信号源，这是与 CT 碘对比剂\"自身衰减X线\"的根本区别。C 进动频率由主磁场决定，钆并不改变拉莫尔频率，也不存在\"使质子重新共振\"的过程。D 钆不改变组织含水量，信号升高源于弛豫加快。E 钆同时缩短 T1 与 T2/T2*，但在临床常用浓度下 T1 缩短效应占优；T2* 缩短效应只有在浓度很高时（如团注首过时的静脉腔内、膀胱内积聚）才占主导，届时反而表现为信号减低。", "tr": "\"对比剂本身不成像，只改变周围质子的弛豫\"是理解一切 MR 对比剂的总纲；高浓度钆造成信号减低的现象常被误认为是\"未强化\"。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04090", "gs": ""}, {"id": "ZG-U04-0116", "t": "单选题", "s": "评价 MR 对比剂效能时常用弛豫率 r1 与 r2 两个参数。关于它们的定义与意义，正确的是", "o": {"A": "r1 与 r2 分别表示单位浓度对比剂使 1/T1 与 1/T2 增加的量，单位为 L/(mmol·s)，其中 r2/r1 比值越小越有利于产生 T1 增强效果", "B": "r1 数值越大，表示该对比剂使 T1 延长得越明显", "C": "r2/r1 比值越大，越适合作为 T1 阳性对比剂", "D": "弛豫率是物质固有常数，与主磁场强度无关，1.5T 与3.0T 下完全相同", "E": "超顺磁性氧化铁的 r2/r1 比值远小于钆螯合物"}, "d": "难", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-002", "kp": "弛豫率 r1、r2 及其临床意义", "ch": "四、对比剂 → 2.MR对比剂 → (2)生物学特性", "ex": "【为什么对】弛豫率描述单位摩尔浓度对比剂对弛豫速率的增强能力，关系式为 1/T1(观察)＝1/T1(本底)＋r1·C。r1 越大，同样剂量下 T1 缩短越明显、强化越强；而 r2 反映 T2/T2* 缩短能力，过强会抵消 T1 效应造成信号丢失，因此 r2/r1 比值越小，对比剂越\"纯粹\"地表现为 T1 阳性效果。【为什么错】B 概念反了：r1 越大意味着纵向弛豫速率 1/T1 增加越多，即 T1 越短而非越长。C 结论相反，r2/r1 大者表现为 T2 阴性对比剂特性。D 弛豫率具有明确的场强依赖性：随场强升高，多数钆螯合物的 r1 略有下降而 r2 相对升高，这正是3.0T 与1.5T 在增强剂量和序列参数上需要区别对待的原因之一。E 事实相反：超顺磁性氧化铁的 r2 远大于 r1，r2/r1 比值可达数十甚至更高，因此表现为强烈的 T2／T2* 阴性对比效应。", "tr": "把 r1、r2 与 T1、T2 的\"倒数关系\"理清是关键：弛豫率大＝弛豫时间短；此外3.0T 上背景组织 T1 延长而钆剂 r1 略降，二者共同决定了临床剂量的调整策略。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U04-0117", "t": "多选题", "s": "关于钆对比剂的配体结构、稳定性与肾源性系统性纤维化（NSF）风险，下列表述正确的有", "o": {"A": "大环类配体（如钆特醇、钆布醇、钆特酸葡胺）把 Gd³⁺ 包裹在预先组织好的刚性空腔内，其热力学与动力学稳定性均高于线性类", "B": "线性非离子型（如钆双胺、钆弗塞胺）动力学稳定性最低，被列为 NSF 高风险组", "C": "NSF 主要见于严重肾功能不全（eGFR 低于30）及透析患者，与游离 Gd³⁺ 释放及体内滞留相关", "D": "大环类不会释放任何游离钆，因此对任何肾功能状态的患者均无需限制剂量", "E": "多次给药后脑内（齿状核、苍白球）T1WI 信号增高的\"钆沉积\"现象在线性类中报道更多，目前尚未证实存在明确的临床危害"}, "d": "难", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-003", "kp": "线性与大环类钆剂的稳定性及 NSF 风险", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】A 大环配体形成笼状空腔，Gd³⁺ 被多个配位原子从各个方向牢牢锁住，解离需要打开整个环，动力学惰性极强；线性配体则如同链条缠绕，更易发生转金属化与解离。B ESUR 分类中钆双胺、钆弗塞胺与钆喷酸葡胺属高风险组，其中非离子型线性制剂由于缺乏电荷稳定作用，动力学稳定性最差。C 肾功能严重受损时钆剂在体内滞留时间从数小时延长至数十小时甚至更久，游离 Gd³⁺ 沉积于皮肤与内脏并激活成纤维细胞，是 NSF 的公认机制。E 钆沉积在线性类中报道显著更多，与其稳定性差一致；目前尚无确证的临床损害，但基于审慎原则临床已倾向优先使用大环类。【为什么错】D 表述过于绝对：大环类只是解离概率极低，并非绝对不释放；对严重肾功能不全者仍应严格掌握适应证、使用最低有效剂量并避免短期内重复给药。", "tr": "记忆框架为\"大环＞线性离子型＞线性非离子型\"的稳定性排序；注意 NSF 与钆沉积是两个不同概念——前者是明确的严重疾病，后者目前只是影像学现象。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U04-0118", "t": "共用题干题", "s": "结合上述情景，下列 MR 对比剂中，既具有细胞外液间隙分布特性，又能被功能正常的肝细胞特异性摄取并经胆道排泄，从而实现\"动态期＋肝细胞期\"双期成像的是", "o": {"A": "钆喷酸葡胺（Gd-DTPA）", "B": "钆特酸葡胺（Gd-DOTA）", "C": "钆塞酸二钠（Gd-EOB-DTPA）", "D": "钆布醇（gadobutrol）", "E": "钆特醇（gadoteridol）"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-004", "kp": "肝细胞特异性 MR 对比剂", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】钆塞酸二钠在 Gd-DTPA 骨架上引入乙氧基苄基（EOB）亲脂基团，使其可被肝细胞膜上的有机阴离子转运多肽摄取进入肝细胞，再经多药耐药相关蛋白排入胆道。注射早期它与普通细胞外液对比剂一样进行动脉期、门静脉期动态成像，约20 min 后进入肝细胞期，一次给药即可获得血流动力学与肝细胞功能双重信息。【为什么错】A 钆喷酸葡胺为经典的线性离子型细胞外液间隙对比剂，无肝细胞特异性摄取。B、D、E 钆特酸葡胺、钆布醇与钆特醇均为大环类细胞外液间隙对比剂，分布于血管内与组织间隙，全部经肾小球滤过排泄，不被肝细胞摄取。", "tr": "钆贝葡胺（Gd-BOPTA）也具有部分肝细胞摄取（约3%~5%），肝胆期需延迟1~2 h；与钆塞酸二钠约50%摄取、20 min 成像的特性差异明显，命题常在摄取比例与延迟时间上设卡。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04088", "gs": ""}, {"id": "ZG-U04-0119", "t": "单选题", "s": "某院在飞利浦3.0T 设备上开展钆塞酸二钠（Gd-EOB-DTPA）增强肝脏 MRI。关于该对比剂的成像时相安排与技术要点，正确的是", "o": {"A": "肝胆特异期应在注射后3~5 min 采集", "B": "该药完全不经肾脏排泄，肾功能不全者可以随意加大剂量", "C": "由于其单次注射剂量与注射体积均小于常规细胞外液对比剂，动脉期强化峰值更高且几乎不会出现一过性呼吸运动伪影", "D": "肝胆特异期图像上正常肝实质呈低信号，而缺乏肝细胞功能的病灶呈高信号", "E": "约50% 经肝细胞摄取并由胆道排泄，肝胆特异期通常在注射后约20 min 采集，采用三维 T1 加权高分辨屏气脂肪抑制梯度回波序列（eTHRIVE／VIBE／LAVA）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-005", "kp": "Gd-EOB-DTPA 的双期特性与序列选择", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】钆塞酸二钠约50% 经肝细胞摄取、经胆道排泄，其余约50% 经肾小球滤过。正常肝实质在注射后10~20 min 逐步摄取达到平台，临床常规在20 min 左右采集肝胆特异期；该期要求高信噪比与高空间分辨率，标准做法是三维扰相梯度回波类 T1 加权屏气序列配合脂肪抑制，飞利浦称 eTHRIVE，西门子称 VIBE，GE 称 LAVA。【为什么错】A 3~5 min 时肝实质摄取尚未充分，此时属过渡期，病灶与肝实质对比不足。B 该药约一半经肾排泄，肾功能不全者同样需要评估风险、控制剂量。C 事实相反：其推荐剂量为0.025 mmol/kg，注射体积小、团注更陡峭，动脉期时间窗更窄，且文献报道其一过性严重运动伪影发生率高于常规钆剂，故需缩短注射时间、采用团注追踪并加强屏气训练，必要时缩短单期采集时间。D 信号关系正好颠倒：肝胆期正常肝实质因摄取对比剂而呈高信号，无正常肝细胞功能的病灶（多数转移瘤、肝内胆管癌、低分化肝细胞癌）因不摄取而呈相对低信号，这正是该期检出小病灶的原理。", "tr": "肝胆期\"肝亮病灶暗\"的信号逻辑必须牢记；此外注意含功能性肝细胞的局灶性结节增生在肝胆期可呈等或高信号，是与肝腺瘤、肝癌鉴别的要点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U04-0120", "t": "多选题", "s": "关于超顺磁性氧化铁（SPIO／USPIO）类 MR 对比剂，下列表述正确的有", "o": {"A": "属阴性（负性）对比剂，主要通过显著缩短 T2／T2* 使摄取组织的信号明显下降", "B": "静脉注射后 SPIO 被肝脏 Kupffer 细胞与脾脏巨噬细胞吞噬，正常肝实质信号降低，而缺乏 Kupffer 细胞的病灶相对呈高信号", "C": "USPIO 颗粒直径更小、血液半衰期更长，可用于淋巴结成像与血池成像", "D": "SPIO 的 r2/r1 比值远小于钆螯合物", "E": "使用 SPIO 后应首选 T1WI 序列来观察其对比效果"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-006", "kp": "超顺磁性氧化铁对比剂的特性与应用", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】A 超顺磁性颗粒在磁场中产生远强于顺磁离子的局部磁化，造成显著的磁场不均匀性，加速质子失相位，因而以缩短 T2／T2* 为主，表现为信号减低的阴性对比。B 这是 SPIO 用于肝脏成像的经典机制：正常肝实质因吞噬颗粒而变黑，不含 Kupffer 细胞的转移瘤、多数肝癌因不摄取而保持原有信号，形成\"黑肝衬托亮病灶\"的对比。C 颗粒越小越不易被网状内皮系统快速清除，血液半衰期延长，可进入淋巴系统并长时间维持血池内浓度。【为什么错】D 与事实相反：SPIO 的 r2 远大于 r1，r2/r1 比值可达数十，远大于钆螯合物（通常在1~2 之间），这正是其表现为阴性对比剂的量化依据。E 观察 SPIO 效果应使用对磁化率敏感的 T2WI，尤其是 T2* 加权梯度回波序列；用 T1WI 观察会显著低估其效应。", "tr": "阳性对比剂看 T1WI、阴性对比剂看 T2/T2*WI，序列选择与对比剂类型必须匹配；把\"信号减低\"误判为\"未强化\"是阅片与技术沟通中的常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U04-0121", "t": "共用题干题", "s": "结合上述情景，关于锰类 MR 对比剂（如锰福地吡三钠 Mn-DPDP），下列表述正确的是", "o": {"A": "属阴性对比剂，主要通过缩短 T2 起作用", "B": "Mn²⁺ 为顺磁性金属离子，可被功能正常的肝细胞摄取并经胆汁排泄，属肝细胞特异性 T1 阳性对比剂", "C": "主要被肝脏 Kupffer 细胞吞噬后发挥作用", "D": "仅能用于中枢神经系统的增强检查", "E": "与钆螯合物一样属于细胞外液间隙分布型对比剂"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-007", "kp": "锰类肝细胞特异性对比剂", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】Mn²⁺ 含5个未成对电子，具有顺磁性，能有效缩短 T1。锰福地吡三钠进入体内后逐步释放 Mn²⁺，被功能正常的肝细胞摄取，部分经胆汁排泄，使正常肝实质在 T1WI 上信号升高，而缺乏正常肝细胞功能的病灶相对呈低信号，属肝细胞特异性阳性对比剂。此外锰还可被胰腺、肾皮质与心肌摄取。【为什么错】A 归类错误：锰剂以缩短 T1 为主，是阳性对比剂；阴性对比剂的代表是超顺磁性氧化铁。C 被 Kupffer 细胞吞噬是 SPIO 的机制，锰剂靶向的是肝细胞本身。D 锰剂的主要临床应用恰恰在肝脏，而非仅限中枢神经系统。E 细胞外液间隙型对比剂无器官特异性摄取、全部经肾排泄，与锰剂的肝细胞靶向和胆道排泄特性完全不同。", "tr": "把三类肝脏对比剂的靶细胞分清：钆塞酸二钠与锰剂靶向肝细胞（阳性、T1WI 肝变亮），SPIO 靶向 Kupffer 细胞（阴性、T2WI 肝变黑）。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04091", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-0122", "t": "共用题干题", "s": "结合上述情景，关于钆对比剂的不良反应及其处理，下列表述正确的有", "o": {"A": "总体不良反应发生率低于碘对比剂，多为轻度表现，如恶心、头痛、注射部位不适与荨麻疹", "B": "严重类过敏样反应虽罕见，但一旦发生，其处理原则与碘对比剂相同，首选肌内注射肾上腺素", "C": "有钆剂过敏史者再次检查时应换用不同类别的钆剂，并做好预处理与抢救准备", "D": "某些钆制剂可干扰采用邻甲酚酞络合酮法等比色法的血清钙测定，造成假性低钙结果", "E": "妊娠期可以常规使用钆对比剂，因为钆螯合物不能通过胎盘屏障"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-008", "kp": "钆对比剂的不良反应与处理原则", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】A 钆剂常规剂量下所含摩尔量远低于碘剂，渗透压负荷小，不良反应率明显更低，且以轻度为主。B 严重反应虽罕见，机制与临床表现同为类过敏样反应，抢救流程完全一致，MR 机房同样必须配备急救药械并明确转运路径。C 换用不同螯合结构的制剂可降低交叉反应概率，但仍需预处理与全程监护。D 部分钆制剂（尤以线性非离子型为著）会与比色法试剂发生干扰，造成检验结果假性偏低，若不了解此点可能导致不必要的补钙治疗，故应告知检验科并在给药后一定时间内避免采血复查血钙。【为什么错】E 表述错误：钆螯合物可通过胎盘进入胎儿循环，经胎儿肾脏排入羊水后可能长时间滞留并解离，因此妊娠期原则上避免使用，仅在获益明确大于风险且无替代方案时由多学科评估后谨慎使用。", "tr": "MR 检查室常被误认为\"没有辐射就绝对安全\"，实际上其急救难度更大——磁场内不能带入铁磁性抢救设备，必须先把患者转移出Ⅳ区再抢救，这一流程应事先演练。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04089", "gs": ""}, {"id": "ZG-U04-0123", "t": "共用题干题", "s": "结合上述情景，成人颅脑 MRI 增强常规使用细胞外液间隙钆对比剂，其市售制剂浓度为0.5 mmol/ml，标准剂量为0.1 mmol/kg。一名体重70 kg 的患者，应注射的对比剂体积约为", "o": {"A": "7 ml", "B": "14 ml", "C": "21 ml", "D": "35 ml", "E": "70 ml"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-009", "kp": "钆对比剂的剂量与体积换算", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】先算摩尔量：0.1 mmol/kg×70 kg＝7 mmol；再按浓度换算体积：7 mmol÷0.5 mmol/ml＝14 ml。这与临床经验值\"0.2 ml/kg\"完全吻合，即70 kg 患者约14 ml。【为什么错】A 误把0.1 mmol/kg 直接当作0.1 ml/kg，漏掉了浓度换算这一步，是最常见的错误。C 相当于按0.15 mmol/kg 计算又出现换算偏差。D 相当于按0.5 ml/kg 给药，为标准剂量的2.5倍。E 相当于按1 ml/kg 给药，为标准剂量的5倍，严重超量。", "tr": "0.5 mmol/ml 浓度制剂的经验换算是\"0.1 mmol/kg＝0.2 ml/kg\"；但钆塞酸二钠为0.25 mmol/ml 制剂、推荐剂量0.025 mmol/kg（约0.1 ml/kg），不可套用同一经验值。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04090", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-0124", "t": "多选题", "s": "某院在飞利浦3.0T 设备上开展头颈部对比增强 MR 血管成像（CE-MRA）。关于对比剂应用与采集时相控制，下列表述正确的有", "o": {"A": "采用高压注射器团注（常用2~3 ml/s）并追加生理盐水冲刷，以形成陡峭紧凑的团注峰", "B": "可用团注试验（test bolus）或实时透视触发（BolusTrak／CARE Bolus／SmartPrep）确定采集延迟，使 K 空间中心恰好落在动脉峰值时刻", "C": "CE-MRA 常采用三维扰相梯度回波序列（T1-FFE／FLASH／SPGR），并配合椭圆中心（centric）K 空间填充顺序", "D": "为提高动脉信号强度，应尽量延长采集时间以增加信号平均次数", "E": "3.0T 相比1.5T 因背景组织 T1 延长且信噪比提高，可适当减少对比剂用量"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-010", "kp": "CE-MRA 的对比剂应用与时相控制", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】A 紧凑团注使动脉内浓度在短时间内达到高峰，是获得高动脉信号、避免静脉污染的前提；盐水冲刷把留在上肢静脉与管路内的对比剂全部推入循环，既提高利用率又减少残留伪影。B 采集延迟的精确匹配是 CE-MRA 成败的关键，两种方法各有优势：团注试验准确但多耗一次小剂量注射，透视触发可实时观察、操作便捷。C 三维扰相梯度回波可用极短 TR/TE 抑制背景、突出短 T1 的含钆血液；椭圆中心填充把决定图像对比的 K 空间中心区放在采集起始，正对动脉峰值。E 3.0T 上背景组织 T1 延长使未强化组织更暗，加之信噪比提高，同样剂量下强化对比更佳，为减量提供了空间。【为什么错】D 与时相控制原则直接冲突：CE-MRA 必须在动脉峰值这一狭窄时间窗内完成中心 K 空间采集，延长采集时间会使静脉回流显影造成静脉污染，同时增加运动伪影风险；提高信噪比应通过并行采集、优化线圈与带宽实现，而非延长采集。", "tr": "CE-MRA 的核心是\"时间窗匹配\"而非\"信号越多越好\"；判断失败原因时，静脉污染提示延迟过长，动脉信号弱且出现环状伪影（Maki 伪影）提示采集过早。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U04-0125", "t": "共用题干题", "s": "结合上述情景，关于细胞外液间隙钆对比剂的生物学特性与临床应用，下列表述正确的有", "o": {"A": "静脉注射后迅速分布于血管内与细胞外间隙，不能通过完整的血脑屏障", "B": "主要经肾小球滤过以原形排出，肾功能正常者血浆半衰期约1.5 h", "C": "其血浆蛋白结合率高、血管内滞留时间长，属典型的血池对比剂", "D": "增强后 T1WI 常需配合脂肪抑制，以提高强化组织与周围脂肪的区分度，尤其在眼眶、颈部与乳腺检查中", "E": "常规剂量下钆剂在 T2WI 上产生明显高信号，故增强后应以 T2WI 作为主要观察序列"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-011", "kp": "细胞外液间隙钆对比剂的分布与排泄", "ch": "四、对比剂 → 2.MR对比剂 → (2)生物学特性", "ex": "【为什么对】A 钆螯合物分子量小、亲水性强，可自由通过一般毛细血管进入组织间隙，但无法穿过完整的血脑屏障，这正是中枢神经系统病变一旦强化即提示血脑屏障破坏的原理。B 几乎不参与代谢，经肾小球滤过原形排出，正常肾功能者血浆半衰期约1.5 h，24 h 内基本清除完毕。D 脂肪在 T1WI 上本身呈高信号，会掩盖强化灶，故富含脂肪的眼眶、颈部与乳腺区域增强扫描常规加脂肪抑制。【为什么错】C 描述的是血池对比剂（如与白蛋白高结合率的钆磷维塞）的特性；细胞外液间隙型对比剂的蛋白结合率很低，因而能迅速渗出到组织间隙。E 常规剂量下钆剂以缩短 T1 为主要效应，应在 T1WI 上观察强化；在 T2WI 上其效应不明显，浓度很高时甚至因缩短 T2 而表现为信号减低。", "tr": "\"强化＝血脑屏障破坏或血供／通透性增加\"这一推理只对中枢神经系统严格成立，在血脑屏障之外的器官不能照搬。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04088", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-0126", "t": "共用题干题", "s": "结合上述情景，患者男，64岁，慢性肾脏病5期，规律血液透析（每周3次），因超声怀疑肝内占位需行腹部 MRI 增强检查。患者既往有高血压、2型糖尿病多年，目前服用多种药物，近期无急性感染，食欲欠佳、轻度乏力，凝血功能基本正常，无钆剂过敏史，一般状况尚可，可配合屏气。临床医师在申请单上特别注明希望使用肝细胞特异性对比剂以评估病灶性质。作为 MR 技师，向临床提出的最合理建议是", "o": {"A": "因患者规律透析，钆剂可被完全清除，故可按常规剂量使用任何类型的钆对比剂", "B": "严格评估增强的必要性与替代方案；若确需增强，优先选用 ESUR 分类中 NSF 低风险的大环类对比剂，采用最低有效剂量并避免短期内重复给药，把检查安排在透析日并于给药后尽早进行血液透析，同时充分知情告知", "C": "改用双倍剂量的线性离子型对比剂，以保证肝胆期强化效果", "D": "直接改行腹部增强 CT，因为碘对比剂对透析患者没有任何风险", "E": "无需任何增强检查，仅做扩散加权成像即可完全替代"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-012", "kp": "终末期肾病患者钆对比剂的选择策略", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】慢性肾脏病5期透析患者是 NSF 的最高危人群。此时临床需求（肝细胞特异性成像）与安全要求（低 NSF 风险）存在冲突：目前临床主要的肝细胞特异性对比剂钆塞酸二钠属线性离子型，风险等级高于大环类。规范做法是先评估增强的必要性与替代方案，若确需增强则优先选用低风险的大环类制剂、使用最低有效剂量、避免短期重复给药，并把检查安排在透析日、给药后尽早透析以加速清除，同时完成充分的知情告知——这是一个由技师参与、与临床共同完成的风险—获益决策过程。【为什么错】A 血液透析确实可清除大部分钆剂（三次透析可清除约97%），但清除并非即时完成，且现有证据不足以证明透析能可靠预防 NSF，故不能据此放宽制剂选择与剂量。C 双倍剂量的线性制剂把剂量与结构两项风险同时叠加，与安全原则完全相悖。D 该患者已进入透析阶段，虽然对残余肾功能的顾虑相对减少，但碘对比剂仍有类过敏样反应、容量负荷与心血管风险，说\"没有任何风险\"不成立；此外 CT 也无法提供肝细胞功能信息。E 扩散加权成像对病灶检出有帮助，但在鉴别诊断上不能替代动态增强所提供的血流动力学信息，把它作为完全替代方案会造成漏诊或误判。", "tr": "\"透析能清除钆\"不等于\"透析患者可随意用钆\"；技师在此类病例中的价值在于主动提示风险分级、提出可行替代方案，而不是被动执行申请单。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ04088", "gs": ""}, {"id": "ZG-U04-0127", "t": "共用题干题", "s": "结合上述情景，一名42岁女性，超声发现右乳外上象限可疑结节，临床申请乳腺动态增强 MRI。患者既往无乳腺手术及放疗史，否认乳腺癌家族史，既往钼靶提示致密型乳腺、BI-RADS 3 类；设备为飞利浦3.0T，使用专用乳腺相控阵线圈，患者取俯卧位、双乳自然悬垂，无钆剂过敏史，肾功能正常，月经规律。作为 MR 技师，关于对比剂使用与动态采集方案，最恰当的安排是", "o": {"A": "按0.1 mmol/kg 使用大环类钆剂，以约2 ml/s 团注并追加20 ml 生理盐水冲管；采用三维扰相梯度回波脂肪抑制序列（eTHRIVE／VIBE），先采集蒙片期，再连续采集6~8个动态时相，单期时间分辨率控制在60~90 s 以内，以便绘制时间—信号强度曲线；检查安排在月经周期第7~14天", "B": "采用0.3 mmol/kg 的三倍剂量以提高病灶检出率", "C": "单期采集时间越长越好，以最大限度保证空间分辨率", "D": "检查应安排在月经周期第1~7天（月经期）进行，以减少背景实质强化", "E": "注射后只采集一个延迟期图像即可判断时间—信号强度曲线类型"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-GBCA-013", "kp": "乳腺动态增强 MRI 的对比剂与采集方案", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】乳腺动态增强的诊断价值来自形态与血流动力学两方面：形态学要求高空间分辨率与可靠的脂肪抑制，血流动力学要求足够的时间分辨率以刻画流入与流出。标准剂量0.1 mmol/kg、约2 ml/s 团注加盐水冲刷可形成稳定的团注；三维扰相梯度回波配脂肪抑制既满足薄层高分辨又能压制脂肪高信号；先采蒙片再连续采集6~8个时相，单期控制在60~90 s 以内，可准确区分流入型、平台型与流出型曲线。月经周期第7~14天（增生早期）激素水平低，背景实质强化最轻，可减少假阳性。【为什么错】B 超剂量既无循证依据，又增加钆负荷与不良反应风险，且过强的背景强化反而降低特异性。C 单纯追求空间分辨率而牺牲时间分辨率，会使动态曲线失真，无法识别快进快出的恶性强化特征，属典型的顾此失彼。D 月经期与黄体期（第15天以后）背景实质强化最明显，是应当避开的时段，本项把最佳时间窗记反了。E 时间—信号强度曲线必须由多个连续时相构成，单一延迟期图像既无法判断强化速率也无法识别流出模式。", "tr": "乳腺 MRI 的三个时间要点：检查安排在月经周期第7~14天、单期时间分辨率不超过60~90 s、动态采集覆盖注射后至少5~7 min；三者常被合并考查。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04077", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-0128", "t": "单选题", "s": "随着 CT 扫描速度不断提高，对比剂注射方案日趋个体化。关于\"碘流率\"与\"总碘量\"这两个核心参数，正确的表述是", "o": {"A": "碘流率仅由注射流率决定，与对比剂的碘浓度无关", "B": "提高对比剂碘浓度时必然要求同步提高注射流率", "C": "总碘量决定动脉强化峰值，碘流率决定肝实质的强化程度", "D": "碘流率（gI/s）等于对比剂碘浓度（gI/ml）与注射流率（ml/s）的乘积，主要决定血管内强化峰值；总碘量（gI）则与实质器官（如肝脏）的强化程度及患者体重密切相关", "E": "个体化方案要求多数患者统一使用100 ml 对比剂以便于管理"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-001", "kp": "碘流率与总碘量的个体化方案", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】碘流率描述单位时间进入循环的碘量，直接决定血管腔内瞬时碘浓度，因而是动脉强化峰值的主要决定因素；总碘量描述整次注射的碘负荷，经再循环后分布到实质器官，因而与肝、胰、脾等实质强化程度相关，并应按体重（或去脂体重、体表面积）个体化设定。理解这一分工，才能在\"降低总量\"与\"保证动脉强化\"之间找到平衡。【为什么错】A 遗漏了浓度这一半，同样4 ml/s 下370 mgI/ml 与320 mgI/ml 的碘流率相差约16%。B 二者可以相互替代：提高浓度后反而可以适当降低流率以维持相同碘流率，从而减轻静脉与留置针的压力负荷。C 两个参数的作用对象被完全对调。E 与个体化理念背道而驰，统一固定用量会使体重轻者过量、体重大者强化不足。", "tr": "\"碘流率管血管、总碘量管实质\"是记忆主线；注意还有\"固定注射时间法\"——保持注射持续时间不变而按体重调整总量，可使不同体型患者的强化峰值时间趋于一致。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U04-0129", "t": "单选题", "s": "低管电压与能谱 CT 技术的推广使\"低碘量\"增强扫描成为可能。这一做法的物理基础是", "o": {"A": "把管电压由120 kV 降至70~80 kV，或选择40~50 keV 的低能级虚拟单能量图像时，X线的平均能量更接近碘的 K 吸收缘（33.2 keV），碘的质量衰减系数随之增大、CT 值明显升高，因而可在保证强化效果的前提下减少对比剂用量", "B": "降低管电压提高了碘元素的原子序数", "C": "在虚拟平扫（VNC）图像上碘的 CT 值最高，因而最适合观察强化", "D": "降低管电压使图像噪声下降，所以可以减少碘用量", "E": "能谱 CT 通过提高管电流来实现减碘"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-002", "kp": "低管电压与能谱成像的减碘机制", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】光电效应的发生概率随光子能量降低而急剧增加，并在 K 吸收缘处出现突跃。当X线的平均能量向33.2 keV 靠近时，碘的质量衰减系数显著增大，同样碘浓度可产生更高的 CT 值——70 kV 下碘的 CT 值约为120 kV 下的1.7 倍，40 keV 虚拟单能量图像的增益更大。据此可等比例削减对比剂用量，同时低管电压还降低了辐射剂量，代价是图像噪声上升，需以迭代重建或提高管电流予以补偿。【为什么错】B 原子序数是元素固有属性，不会因管电压改变而改变，属概念性错误。C 虚拟平扫的定义正是从能谱数据中去除碘的贡献，碘在其上的 CT 值最低而非最高，它用于替代真正的平扫以降低总剂量。D 因果颠倒：降低管电压会使噪声升高而非下降；减碘的依据是碘对比度提升，而不是噪声降低。E 提高管电流只增加光子数量、降低噪声，并不改变能谱位置与碘的衰减特性，因此不构成减碘的物理基础。", "tr": "低 kV／低 keV 提升的是碘的\"对比度\"，同时带来噪声上升，必须与迭代重建、管电流补偿配套使用；把 VNC 与碘图（iodine map）的用途弄反也是高频错点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U04-0130", "t": "共用题干题", "s": "结合上述情景，关于对比剂的研究方向与临床应用进展，下列表述正确的有", "o": {"A": "血池型 MR 对比剂（如与白蛋白结合率高的钆剂）在血管内滞留时间长，可实现稳态期高分辨率 MR 血管成像", "B": "肝细胞特异性对比剂使一次检查同时获得动态期与肝细胞期信息，有助于小肝癌与局灶性结节增生等病变的鉴别", "C": "出于对钆沉积的关注，临床倾向于优先选用大环类制剂，并遵循最低有效剂量、避免不必要增强的原则", "D": "靶向分子影像对比剂通过特异性配体与受体或抗原结合，实现分子水平成像，目前多数仍处于研究阶段", "E": "含碘对比剂目前已可被钆对比剂完全替代用于 CT 增强检查"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-003", "kp": "对比剂研究与应用的主要进展方向", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】A 血池对比剂与白蛋白可逆结合，分子有效体积增大、血管内滞留时间延长，可在首过之后的稳态期进行长时间高分辨采集，特别适合外周血管与冠状动脉成像。B 一次注射兼得血流动力学与肝细胞功能两类信息，是肝脏 MRI 近十余年最重要的进展之一。C 这是各国指南与临床实践的一致趋势，也是技师在方案沟通中应主动坚持的原则。D 靶向对比剂把成像从解剖、功能推进到分子层面，目前多数尚处临床前或早期临床研究阶段，这一\"发展阶段\"的定位是命题常考点。【为什么错】E 钆的原子序数为64，虽然在X线下也有衰减能力，但要达到与碘剂相当的强化效果所需摩尔量远超安全剂量，会带来严重的肾毒性与 NSF 风险，因此绝不能常规替代碘剂用于 CT 增强；仅在极特殊情况下由临床权衡后个案考虑。", "tr": "\"了解\"层次的进展类考点重在方向与定位，不必死记具体商品名；但\"钆剂不能替代碘剂做 CT\"属安全底线，必须掌握。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04078", "gs": ""}, {"id": "ZG-U04-0131", "t": "案例分析题", "s": "某院新引进能谱 CT 并着手推行个体化对比剂方案。一名体重50 kg 的女性患者需行以门静脉期为主的上腹部增强 CT；既往一次增强检查后肝脏强化良好，但检查后48 h 复查发现血肌酐一过性轻度升高，此后自行恢复。科室现有320 mgI/ml 与370 mgI/ml 两种非离子型对比剂，注射器支持多段编程。作为技师，较为合理的方案是", "o": {"A": "选用370 mgI/ml 并固定给药100 ml，以保证强化效果", "B": "通过延长注射时间来降低碘流率，这样既能减少总碘量又能提高动脉强化峰值", "C": "以虚拟平扫（VNC）图像替代增强扫描来评价门静脉", "D": "采用低管电压扫描或重建40~50 keV 虚拟单能量图像以提升碘对比，按体重给药（约0.4~0.5 gI/kg）并选用320 mgI/ml 制剂适当降低总量，采用固定注射时间以保证碘流率稳定，同时在检查前后适当水化并随访肾功能", "E": "在减少对比剂总量的同时把管电压提高到140 kV，以补偿强化程度的下降"}, "d": "中", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-004", "kp": "能谱 CT 条件下的个体化低碘量方案", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】该患者体重轻且有对比剂后肾功能一过性波动史，属需要控制碘负荷的人群。合理方案是从两端同时着手：一方面用低管电压或低 keV 虚拟单能量图像提升碘的 CT 值，为减量创造条件；另一方面按体重设定总碘量（上腹部实质强化常按0.4~0.5 gI/kg），选用浓度较低的320 mgI/ml 制剂便于在小体重患者中精细调节，并采用固定注射时间法保证碘流率与峰值时间的一致性。同时按肾损伤风险管理原则给予适当水化并随访肾功能。【为什么错】A 固定100 ml 对50 kg 患者明显超量，与个体化原则和既往肾功能波动史都相冲突。B 前后自相矛盾：延长注射时间会降低碘流率，动脉强化峰值随之下降而非提高。C 虚拟平扫是从增强数据中减去碘信号得到的\"平扫\"图像，本身不含血管强化信息，根本无法评价门静脉。E 提高管电压会使X线平均能量远离碘的 K 吸收缘，碘的 CT 值下降，与减碘目标完全相反；正确方向恰恰是降低管电压。", "tr": "减碘的三条腿是\"低 kV／低 keV＋按体重给药＋固定注射时间\"；同时须记住降低 kV 后噪声上升，应配合迭代重建或适度提高管电流，不能只减不补。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U04-1001", "t": "共用题干题", "s": "结合上述情景，下列属于离子型高渗X线对比剂的是", "o": {"A": "泛影葡胺（复方泛影葡胺）", "B": "碘海醇", "C": "碘帕醇", "D": "碘克沙醇", "E": "碘普罗胺"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-001", "kp": "X线对比剂分类", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】泛影葡胺为离子型单体对比剂，在溶液中解离为离子，渗透压高，属高渗对比剂。【为什么错】B碘海醇、C碘帕醇、E碘普罗胺均为非离子型单体对比剂；D碘克沙醇为非离子型二聚体等渗对比剂。", "tr": "“泛影葡胺＝离子型高渗”是最基础的对应关系，与非离子型代表药区分记忆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04073", "gs": ""}, {"id": "ZG-U04-1002", "t": "共用题干题", "s": "结合上述情景，下列属于非离子型单体低渗X线对比剂的是", "o": {"A": "碘海醇", "B": "泛影葡胺", "C": "碘克沙醇", "D": "硫酸钡", "E": "空气"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-002", "kp": "X线对比剂分类", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】碘海醇（欧乃派克）为非离子型单体，溶液不解离，渗透压约为血浆两倍，属低渗对比剂。【为什么错】B泛影葡胺为离子型高渗；C碘克沙醇为非离子型二聚体等渗；D硫酸钡为胃肠道阳性对比剂；E空气为阴性对比剂。", "tr": "非离子型单体（碘海醇、碘帕醇、碘普罗胺等）是当前临床最常用的一类。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04074", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1003", "t": "共用题干题", "s": "结合上述情景，下列X线对比剂中渗透压与血浆接近、为等渗对比剂的是", "o": {"A": "碘克沙醇", "B": "泛影葡胺", "C": "碘海醇", "D": "碘帕醇", "E": "碘佛醇"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-003", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】碘克沙醇（威视派克）为非离子型二聚体，在水中不解离且分子较大，渗透压约290mOsm/kg，与血浆相近，为等渗对比剂。【为什么错】B泛影葡胺为离子型高渗；C、D、E为非离子型单体低渗（约为血浆两倍）。", "tr": "渗透压排序：离子型单体＞非离子型单体＞非离子型二聚体（等渗）。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04075", "gs": ""}, {"id": "ZG-U04-1004", "t": "共用题干题", "s": "结合上述情景，下列X线对比剂按渗透压由高到低排列，正确的是", "o": {"A": "泛影葡胺＞碘海醇＞碘克沙醇", "B": "碘克沙醇＞碘海醇＞泛影葡胺", "C": "碘海醇＞泛影葡胺＞碘克沙醇", "D": "碘克沙醇＞泛影葡胺＞碘海醇", "E": "三者在渗透压上相同"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-004", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】离子型单体（泛影葡胺）在水中解离成阳离子与阴离子，渗透压最高（约5倍于血浆）；非离子型单体（碘海醇）不解离，渗透压低（约2倍血浆）；非离子型二聚体（碘克沙醇）为等渗。【为什么错】B、C、D的排序均与上述规律不符；E三种渗透压不同。", "tr": "渗透压毒性是高渗对比剂不良反应的主要机制，等渗剂肾毒性相对更低。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04075", "gs": ""}, {"id": "ZG-U04-1005", "t": "共用题干题", "s": "结合上述情景，硫酸钡作为胃肠道X线对比剂，其主要优点是", "o": {"A": "原子序数高、不溶于水、不被肠道吸收，显影清晰且安全", "B": "溶于水易于吸收", "C": "可进入血液循环增强血管", "D": "渗透压极高", "E": "可透过血脑屏障"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-005", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】硫酸钡中钡原子序数高（56），阻射X线能力强，且不溶于水、不被吸收，经口服或灌肠在消化道内形成良好对比，使用安全。【为什么错】B硫酸钡不溶于水；C硫酸钡不进入血管，不能增强血管；D其渗透压与毒性不属其特点；E不能透过血脑屏障。", "tr": "硫酸钡只能用于消化道造影，严禁用于血管或椎管等体内注射。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04076", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1006", "t": "共用题干题", "s": "结合上述情景，下列属于阴性X线对比剂的是", "o": {"A": "空气（二氧化碳）", "B": "硫酸钡", "C": "泛影葡胺", "D": "碘海醇", "E": "碘克沙醇"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-006", "kp": "X线对比剂分类", "ch": "四、对比剂 → 1.X线对比剂 → (1)分类", "ex": "【为什么对】阴性对比剂为低密度气体（空气、二氧化碳、氧气），在X线片上呈低密度，用于关节腔、消化道等造影。【为什么错】B硫酸钡为阳性对比剂（高密度）；C、D、E碘对比剂均为阳性对比剂。", "tr": "阳性对比剂密度高（钡、碘）、阴性对比剂密度低（气体），二者密度属性相反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04074", "gs": ""}, {"id": "ZG-U04-1007", "t": "共用题干题", "s": "结合上述情景，碘对比剂含碘量的常用表示单位是", "o": {"A": "mgI/ml", "B": "g/kg", "C": "mOsm/kg", "D": "mol/L", "E": "HU"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-007", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】碘对比剂浓度以单位体积含碘量表示，常用mgI/ml，如300mgI/ml、370mgI/ml。【为什么错】B g/kg为体重剂量单位；C mOsm/kg为渗透压单位；D mol/L为摩尔浓度；E HU为CT值单位。", "tr": "对比剂增强效果取决于碘浓度，mgI/ml数值越高增强越明显。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04076", "gs": ""}, {"id": "ZG-U04-1008", "t": "共用题干题", "s": "结合上述情景，下列不属于碘对比剂常用引入途径的是", "o": {"A": "皮下注射", "B": "静脉注射", "C": "动脉注射", "D": "口服", "E": "椎管内注射"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-008", "kp": "X线对比剂引入途径", "ch": "四、对比剂 → 1.X线对比剂 → (3)引入途径", "ex": "【为什么对】碘对比剂可经静脉（增强CT、静脉肾盂造影）、动脉（DSA）、口服（胃肠道）及椎管内（脊髓造影）等途径引入。【为什么错】A皮下注射不用于碘对比剂，无诊断意义且易引起局部反应。", "tr": "不同引入途径对应不同检查方法，注意“皮下注射”不属于常规途径。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04074", "gs": ""}, {"id": "ZG-U04-1009", "t": "共用题干题", "s": "结合上述情景，关于碘对比剂的化学毒性，正确的叙述是", "o": {"A": "与对比剂分子的亲脂性、蛋白质结合能力及电荷等化学特性有关", "B": "仅与渗透压高低有关", "C": "仅由碘原子浓度决定", "D": "与注射速度无关", "E": "只发生于口服途径"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-009", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】化学毒性指对比剂分子本身的化学性质（亲脂性、与蛋白结合能力、电荷等）引起的毒性，与渗透压毒性、离子毒性并列为三大毒性。【为什么错】B化学毒性并非仅由渗透压决定；C碘原子浓度主要决定显影密度；D注射速度影响反应发生程度；E化学毒性可发生于各种注射途径。", "tr": "离子型对比剂含电荷、亲脂性高，化学毒性大于非离子型，这是其不良反应较多的原因之一。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04080", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1010", "t": "共用题干题", "s": "结合上述情景，下列不属于造影剂肾病（CIN）高危因素的是", "o": {"A": "肾功能正常且无糖尿病的中青年患者", "B": "既往肾功能不全", "C": "糖尿病", "D": "高龄", "E": "脱水或血容量不足"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-010", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】造影剂肾病高危因素包括肾功能不全、糖尿病、高龄、脱水、心力衰竭及近期重复使用对比剂等；肾功能正常且无糖尿病的中青年不属于高危人群。【为什么错】B、C、D、E均为公认的CIN高危因素。", "tr": "本题为“否定式”选择，需识别出不属于高危因素的项目。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04080", "gs": ""}, {"id": "ZG-U04-1011", "t": "共用题干题", "s": "结合上述情景，对肾功能不全的高危患者行增强CT时，预防造影剂肾病的主要措施是", "o": {"A": "选用低渗或等渗对比剂并充分水化", "B": "选用高渗离子型对比剂", "C": "注射前禁止饮水", "D": "加大对比剂剂量", "E": "注射后立即行血液透析"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-011", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】高危患者应优先选择低渗或等渗对比剂，检查前予以充分水化（静脉补液或口服水），以降低造影剂肾病风险。【为什么错】B高渗离子型对比剂肾毒性更大；C脱水是CIN危险因素，不应禁水；D加大剂量增加肾毒性；E常规检查后无需常规透析，预防重点在水化与剂型选择。", "tr": "水化＋低渗/等渗剂是CIN预防的两大核心措施。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04080", "gs": ""}, {"id": "ZG-U04-1012", "t": "共用题干题", "s": "结合上述情景，碘对比剂轻度不良反应的常见表现是", "o": {"A": "荨麻疹、恶心、喷嚏、面部潮红", "B": "血压测不出", "C": "呼吸心跳骤停", "D": "喉头水肿窒息", "E": "昏迷抽搐"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-012", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】轻度不良反应多为皮肤黏膜表现，如荨麻疹、恶心、喷嚏、面部潮红、皮肤瘙痒等，多可自行缓解或对症处理。【为什么错】B、C、D、E均属中重度反应（过敏性休克、喉头水肿、呼吸心搏骤停等）的危急表现。", "tr": "反应分级：轻度（皮肤黏膜）→中度（支气管痉挛、心动过速）→重度（休克、喉头水肿、呼吸停止）。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04081", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1013", "t": "共用题干题", "s": "结合上述情景，碘对比剂所致过敏性休克的首选抢救药物是", "o": {"A": "肾上腺素（0.1%溶液肌内注射）", "B": "地西泮静脉注射", "C": "口服扑尔敏", "D": "阿托品皮下注射", "E": "硝酸甘油舌下含服"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-013", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】过敏性休克时首选肾上腺素（0.1%肾上腺素0.3～0.5mg肌内注射，可重复），并配合高流量吸氧、快速补液及糖皮质激素等。【为什么错】B地西泮为镇静药，不用于抗休克；C口服药起效慢，不适合抢救；D阿托品用于心动过缓；E硝酸甘油用于心绞痛，不能抗过敏性休克。", "tr": "肾上腺素是过敏性休克的一线抢救药物，剂量与给药途径（肌注）是关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04081", "gs": ""}, {"id": "ZG-U04-1014", "t": "共用题干题", "s": "结合上述情景，按磁学性质分类，MR对比剂可分为", "o": {"A": "顺磁性、超顺磁性与铁磁性对比剂", "B": "离子型与非离子型对比剂", "C": "单体与二聚体对比剂", "D": "高渗与等渗对比剂", "E": "口服与注射对比剂"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-001", "kp": "MR对比剂发展及分类", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】MR对比剂按磁学性质分为顺磁性（钆类）、超顺磁性（氧化铁类）和铁磁性三类。【为什么错】B、C、D为X线碘对比剂的分类方式；E按引入途径分类并非MR对比剂的主要分类。", "tr": "MR对比剂核心分类是“磁学性质”，与X线对比剂的“离子/渗透压”分类体系不同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04071", "gs": ""}, {"id": "ZG-U04-1015", "t": "共用题干题", "s": "结合上述情景，下列属于顺磁性MR对比剂代表药物的是", "o": {"A": "钆喷酸葡胺（Gd-DTPA）", "B": "硫酸钡", "C": "泛影葡胺", "D": "碘克沙醇", "E": "二氧化碳"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-002", "kp": "MR对比剂发展及分类", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】钆喷酸葡胺（马根维显）含钆（Gd³⁺）离子，具有顺磁性，是临床应用最广的MR对比剂。【为什么错】B硫酸钡为X线阳性对比剂；C泛影葡胺、D碘克沙醇为X线碘对比剂；E二氧化碳为X线阴性对比剂。", "tr": "“钆＝顺磁性”是MR对比剂的核心记忆点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04072", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1016", "t": "共用题干题", "s": "结合上述情景，顺磁性MR对比剂（钆剂）的增强机制是", "o": {"A": "缩短组织的T1弛豫时间，在T1加权像上信号增高", "B": "缩短T2时间，在T2加权像上信号增高", "C": "延长T1时间，信号降低", "D": "与弛豫无关，仅靠密度对比", "E": "只增强骨皮质信号"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-003", "kp": "MR对比剂增强机制", "ch": "四、对比剂 → 2.MR对比剂 → (3)增强机制", "ex": "【为什么对】钆离子有7个不成对电子，磁矩大，邻近水分子质子T1弛豫明显加快，故T1缩短、T1WI信号增高，属阳性增强。【为什么错】B钆剂主要缩短T1而非使T2WI信号增高；C T1缩短而非延长；D增强完全依赖弛豫效应；E钆剂增强软组织与血供，与骨皮质密度无关。", "tr": "顺磁性剂＝T1缩短＝T1WI高信号＝阳性对比剂；超顺磁性剂＝T2缩短＝T2WI低信号＝阴性对比剂。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04072", "gs": ""}, {"id": "ZG-U04-1017", "t": "共用题干题", "s": "结合上述情景，超顺磁性氧化铁（SPIO）对比剂的增强特点是", "o": {"A": "缩短T2弛豫时间，使T2加权像信号降低，属阴性增强", "B": "缩短T1时间，使T1加权像信号升高", "C": "无任何信号改变", "D": "仅增强血管腔内信号", "E": "使所有组织信号升高"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-004", "kp": "MR对比剂增强机制", "ch": "四、对比剂 → 2.MR对比剂 → (3)增强机制", "ex": "【为什么对】超顺磁性氧化铁颗粒被肝脾网状内皮系统吞噬后，产生局部磁场不均匀，显著缩短T2弛豫，使T2WI上肝脾正常组织信号降低，病灶相对呈高信号，属阴性对比剂。【为什么错】B缩短T1是顺磁性钆剂的作用；C有明确信号改变；D其作用是改变组织信号而非仅血管腔；E其使信号降低而非升高。", "tr": "SPIO曾被用于肝脏特异性MRI，正常肝组织摄取后信号减低，是“阴性增强”代表。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04073", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1018", "t": "共用题干题", "s": "结合上述情景，关于钆类MR对比剂与肾功能不全的关系，正确的说法是", "o": {"A": "重度肾功能不全患者使用钆剂可能引起肾源性系统性纤维化（NSF），需慎用或禁用", "B": "肾功能不全患者使用钆剂完全无风险", "C": "钆剂经肺代谢，与肾脏无关", "D": "任何钆剂均可安全用于透析前患者", "E": "钆剂不经过肾脏排泄"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-005", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】线性钆剂在重度肾功能不全患者中清除延迟，可能诱发肾源性系统性纤维化（NSF），故重度肾功能不全者应慎用或禁用钆剂。【为什么错】B肾功能不全使用钆剂有明确风险；C钆剂经肾脏排泄，不经肺代谢；D透析前患者风险更高；E钆剂主要经肾小球滤过排出。", "tr": "NSF是钆剂与肾功能不全相关的重要安全性问题，线性剂风险更高。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04067", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1019", "t": "共用题干题", "s": "结合上述情景，关于大环类与线性钆剂稳定性的比较，正确的是", "o": {"A": "大环类结构稳定，钆离子释放少，安全性更高", "B": "线性结构更稳定，钆释放更少", "C": "二者稳定性完全相同", "D": "线性剂在体内无任何解离", "E": "大环类钆剂必然引起NSF"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-006", "kp": "MR对比剂发展及分类", "ch": "四、对比剂 → 2.MR对比剂 → (1)发展及分类", "ex": "【为什么对】大环类（如钆特酸葡胺、钆布醇）将钆离子包绕在环状结构内，解离慢、稳定性高，游离钆释放少；线性剂（如钆喷酸葡胺）稳定性相对较低。【为什么错】B线性剂稳定性较低；C二者稳定性不同；D线性剂在体内存在少量解离；E大环类钆剂NSF风险低，而非必然引起。", "tr": "“大环稳定、线性易解离”是钆剂安全性记忆要点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04072", "gs": ""}, {"id": "ZG-U04-1020", "t": "共用题干题", "s": "结合上述情景，常规钆剂增强MR扫描中，观察强化组织的首选序列是", "o": {"A": "T1加权成像（T1WI）", "B": "T2加权成像（T2WI）", "C": "弥散加权成像（DWI）", "D": "磁敏感加权成像（SWI）", "E": "质子密度加权成像（PDWI）"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-007", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】钆剂缩短T1使强化组织在T1WI上信号增高，故增强扫描平扫与增强均以T1WI为主要观察序列。【为什么错】B T2WI对钆剂增强不敏感；C DWI反映水分子扩散；D SWI显示出血与铁沉积；E PDWI对T1缩短效应不敏感。", "tr": "“钆增强必须看T1WI”与“X线碘对比剂看密度增高”是两类对比剂的核心判读差异。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04069", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1021", "t": "共用题干题", "s": "结合上述情景，钆塞酸二钠（Gd-EOB-DTPA）的特殊临床应用价值是", "o": {"A": "被肝细胞特异性摄取，可完成肝胆期成像，提高肝病灶检出", "B": "仅用于脑脊液造影", "C": "用于骨骼显影", "D": "用于肺通气显影", "E": "用于胃肠钡剂双重造影"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-008", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】Gd-EOB-DTPA（普美显）为肝细胞特异性对比剂，经有机阴离子转运体被正常肝细胞摄取并经胆道排泄，可完成动态期与肝胆期成像，提高肝病灶检出与定性能力。【为什么错】B、C、D、E均与该药适应证不符。", "tr": "肝特异性对比剂（Gd-EOB-DTPA、Gd-BOPTA）的“肝胆期”延迟扫描是独特优势。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04069", "gs": ""}, {"id": "ZG-U04-1022", "t": "共用题干题", "s": "结合上述情景，关于MR血管成像（MRA）对比剂的选择，正确的叙述是", "o": {"A": "常用高浓度钆类对比剂经团注后进行快速MRA采集", "B": "必须使用SPIO对比剂", "C": "必须使用泛影葡胺", "D": "对比剂经口服后行MRA", "E": "MRA不能使用任何对比剂"}, "d": "易", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-009", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】增强MRA（CE-MRA）常采用高浓度钆剂快速团注，配合快速梯度回波采集，显著提高血管显示。【为什么错】B SPIO为肝脏阴性对比剂，不用于MRA；C泛影葡胺为X线对比剂；D口服对比剂不进入血管；E增强MRA需使用钆剂，非增强MRA（TOF等）则不用。", "tr": "CE-MRA“高浓度钆剂＋快速采集＋屏气”是核心技术要点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04069", "gs": ""}, {"id": "ZG-U04-1023", "t": "共用题干题", "s": "结合上述情景，关于碘对比剂速发反应与迟发反应的叙述，正确的是", "o": {"A": "速发反应多在注射后1小时内发生，迟发反应多在注射后1小时至1周内发生", "B": "速发反应均在1周后发生", "C": "迟发反应均发生在注射即刻", "D": "二者无时间界限", "E": "迟发反应以过敏性休克为主"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-014", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】速发反应发生于注射后1小时内（多为数分钟内），迟发反应发生于注射后1小时至1周，以皮肤反应为多。【为什么错】B速发反应在1小时内而非1周后；C迟发反应不是注射即刻；D二者有明确时间分界；E过敏性休克属速发反应，迟发反应多为皮肤表现。", "tr": "迟发反应以荨麻疹、斑丘疹等皮肤反应为主，多数轻微可自行消退。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04081", "gs": ""}, {"id": "ZG-U04-1024", "t": "共用题干题", "s": "结合上述情景，离子型碘对比剂相对于非离子型对比剂的主要缺点包括", "o": {"A": "渗透压高，易引起渗透性不良反应", "B": "分子含电荷，化学毒性较大", "C": "与蛋白质结合能力较强", "D": "水溶性差、显影不良", "E": "完全不引起任何反应"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-015", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】离子型对比剂在水中解离为离子，渗透压高（A）、含电荷（B）、亲脂性较强并与蛋白结合（C），化学毒性较大，不良反应相对多见。【为什么错】D离子型对比剂水溶性好、显影清晰，否则不能作为造影剂使用；E任何对比剂都可能引起不良反应，不可能是“完全不引起”。", "tr": "离子型（高渗、带电、毒性大）与非离子型（低渗、不带电、毒性小）的对比是全考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04076", "gs": ""}, {"id": "ZG-U04-1025", "t": "共用题干题", "s": "结合上述情景，碘对比剂过敏反应的预防措施包括", "o": {"A": "详细询问药物及碘过敏史", "B": "检查室常规配备急救药品与设备", "C": "对高危患者预防性使用糖皮质激素和抗组胺药", "D": "任意缩短观察时间尽快离室", "E": "对已知严重碘过敏者谨慎评估并权衡利弊"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-016", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】预防措施包括询问过敏史（A）、配备急救设备（B）、高危患者预防用药（C）、已知严重过敏者谨慎评估（E），检查后观察30分钟。【为什么错】D检查后应留观而非缩短观察时间，速发反应多在1小时内出现。", "tr": "预防用药≠绝对安全，抢救设备与留观制度同样重要。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04082", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1026", "t": "共用题干题", "s": "结合上述情景，碘对比剂重度不良反应的表现包括", "o": {"A": "喉头水肿导致呼吸困难", "B": "血压骤降甚至休克", "C": "抽搐昏迷", "D": "一过性面部潮红", "E": "呼吸心搏骤停"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-017", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】重度反应包括喉头水肿、支气管痉挛、过敏性休克、抽搐昏迷及呼吸心搏骤停等危及生命的表现。【为什么错】D一过性面部潮红、皮肤瘙痒等属轻度反应，不属于重度反应。", "tr": "反应分级判定是救治决策的前提，轻度可观察，重度需立即启动抢救。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04082", "gs": ""}, {"id": "ZG-U04-1027", "t": "共用题干题", "s": "结合上述情景，碘对比剂过敏性休克的抢救措施包括", "o": {"A": "立即停止注射对比剂并呼叫急救", "B": "肌内注射0.1%肾上腺素", "C": "高流量吸氧并快速补液", "D": "给予糖皮质激素与抗组胺药", "E": "让患者自行走动缓解紧张"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-018", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】过敏性休克抢救应立即停药（A）、肾上腺素肌注（B）、吸氧补液（C），并联合糖皮质激素、抗组胺药等（D），必要时心肺复苏。【为什么错】E休克患者应平卧保温、保持气道通畅，走动会加重循环衰竭。", "tr": "抢救流程“停药→肾上腺素→吸氧→补液→激素抗组胺→监护”要完整记忆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04082", "gs": ""}, {"id": "ZG-U04-1028", "t": "共用题干题", "s": "结合上述情景，预防造影剂肾病（CIN）的措施包括", "o": {"A": "检查前后充分水化", "B": "尽量选用低渗或等渗对比剂", "C": "避免与肾毒性药物合用", "D": "短期内避免反复多次使用对比剂", "E": "术前常规停用所有降糖药"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-019", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】CIN预防包括水化（A）、选择低渗/等渗剂（B）、避免与肾毒性药物合用（C）、避免短期内重复检查（D）及评估肾功能等。【为什么错】E“停用所有降糖药”说法绝对，二甲双胍需按肾功能情况评估后决定是否暂停，并非一律停用。", "tr": "二甲双胍与碘对比剂合用可能增加乳酸酸中毒风险，需按肾功能评估，但并非“一律停用”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04083", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1029", "t": "共用题干题", "s": "结合上述情景，钆类MR对比剂的临床应用包括", "o": {"A": "中枢神经系统肿瘤增强扫描", "B": "增强MRA（CE-MRA）", "C": "腹部器官动态增强", "D": "胃肠道钡剂双重造影", "E": "关节腔充气造影"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-010", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】钆剂广泛用于中枢神经系统增强（A）、CE-MRA（B）及腹部动态增强（C）等。【为什么错】D胃肠道造影使用硫酸钡；E关节腔充气造影使用气体（阴性对比剂），均与钆剂无关。", "tr": "钆剂增强＝血供丰富组织T1WI高信号，适用范围广但不用于消化道与关节充气。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04070", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1030", "t": "共用题干题", "s": "结合上述情景，为降低钆剂相关肾源性系统性纤维化（NSF）风险，应采取的措施包括", "o": {"A": "对重度肾功能不全患者慎用或禁用线性钆剂", "B": "优先选用大环类（环状）高稳定钆剂", "C": "避免在短期内反复大剂量使用钆剂", "D": "检查前常规筛查肾功能", "E": "对肾功能不全患者加倍剂量增强效果"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-011", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】降低NSF风险应筛查肾功能（D）、高危患者避免线性剂（A）、优先大环类（B）、避免反复大剂量使用（C）。【为什么错】E对肾功能不全患者加倍剂量会显著增加钆沉积与NSF风险，属错误做法。", "tr": "肾功能不全者不是“加剂量”，而是“减剂量或不用”，重点在风险评估。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04067", "gs": ""}, {"id": "ZG-U04-1031", "t": "共用题干题", "s": "结合上述情景，关于超顺磁性氧化铁（SPIO）对比剂，正确的叙述包括", "o": {"A": "主要被肝脾等网状内皮系统吞噬细胞摄取", "B": "通过缩短T2弛豫使正常肝组织信号降低", "C": "属阴性增强对比剂", "D": "使病灶在T2WI上相对呈高信号", "E": "属顺磁性钆类对比剂"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-012", "kp": "MR对比剂增强机制", "ch": "四、对比剂 → 2.MR对比剂 → (3)增强机制", "ex": "【为什么对】SPIO为氧化铁颗粒，被肝脾网状内皮细胞摄取（A），缩短T2使正常肝脾信号降低（B、C），病灶不含吞噬细胞、信号不变，相对呈高信号（D）。【为什么错】E SPIO是超顺磁性氧化铁，不属于钆类顺磁性对比剂。", "tr": "SPIO“正常肝低、病灶相对高”的阴性增强模式曾用于肝脏占位定性。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04073", "gs": ""}, {"id": "ZG-U04-1032", "t": "多选题", "s": "理想的X线碘对比剂应具备的理化特性包括", "o": {"A": "碘含量高，显影密度好", "B": "渗透压接近血浆", "C": "水溶性好，黏度适宜", "D": "化学毒性小、稳定性好", "E": "可被人体快速吸收代谢为能量"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-020", "kp": "X线对比剂理化特性", "ch": "四、对比剂 → 1.X线对比剂 → (2)理化特性", "ex": "【为什么对】理想碘对比剂应碘含量高（A）、渗透压低（B）、水溶性好黏度适宜（C）、毒性小稳定性好（D）。【为什么错】E对比剂并非营养素，不应被“代谢为能量”，理想的对比剂应不被机体代谢、经肾原形排出。", "tr": "对比剂的理想特性是“高碘、低渗、低毒、稳定、不代谢”，与营养代谢无关。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U04-1033", "t": "共用题干题", "s": "结合上述情景，碘对比剂使用前的准备工作包括", "o": {"A": "核对患者身份与检查目的，告知并签署知情同意", "B": "询问过敏史及肾功能、糖尿病、哮喘等情况", "C": "确认急救药品与抢救设备处于备用状态", "D": "对无静脉通路者预先建立静脉通道", "E": "术前常规做碘过敏皮试"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-021", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】使用前应核对信息与知情同意（A）、评估过敏史与基础疾病（B）、备好急救措施（C）、建立静脉通路（D）。【为什么错】E目前临床已不推荐常规碘过敏皮试，因其预测价值有限且皮试本身有风险，国内现行共识不要求常规皮试。", "tr": "“常规碘皮试”已不再推荐，评估重点转向病史询问与急救准备。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04083", "gs": ""}, {"id": "ZG-U04-1034", "t": "共用题干题", "s": "结合上述情景，关于碘对比剂迟发不良反应，正确的叙述包括", "o": {"A": "多在注射后1小时至1周内发生", "B": "以皮肤反应（荨麻疹、斑丘疹）最常见", "C": "多数症状轻微，可自行消退", "D": "与造影剂肾病（CIN）无关", "E": "只表现为过敏性休克"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-022", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】迟发反应发生于注射后1小时至1周（A），以皮肤反应最常见（B），多数轻微可自行消退（C）。【为什么错】D CIN多在注射后48～72小时出现血肌酐升高，属迟发性肾毒性表现，与迟发反应相关；E迟发反应并非只表现为过敏性休克，休克多为速发反应。", "tr": "CIN本身即属对比剂迟发不良反应之一，两者概念不矛盾。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04083", "gs": ""}, {"id": "ZG-U04-1035", "t": "共用题干题", "s": "结合上述情景，静脉注射对比剂发生血管外渗漏（外渗）时的处理措施包括", "o": {"A": "立即停止注射并拔除针头或调整位置", "B": "抬高患肢", "C": "早期冷敷，减轻渗漏肿胀", "D": "密切观察局部皮肤颜色、感觉与活动度", "E": "立即热敷以促进渗漏液吸收"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-023", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】外渗处理应立即停止注射并拔除针头（A）、抬高患肢（B）、早期冷敷减轻肿胀（C）、密切观察局部皮肤颜色、感觉与活动度（D），大量渗漏或出现神经血管损伤症状时应及时请专科处理。【为什么错】E早期应冷敷使局部血管收缩、减轻渗漏扩散；立即热敷会扩张血管、加重肿胀与损伤，为错误做法。", "tr": "外渗“早期冷敷、48小时后可热敷”是处理时间要点，早期热敷是常见错误操作。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ04084", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1036a", "t": "共用题干题", "s": "结合上述情景，该患者目前发生的对比剂不良反应最可能的类型是", "o": {"A": "中度过敏样反应（出现支气管痉挛及血压下降趋势）", "B": "轻度皮肤反应，无需处理", "C": "迟发皮肤反应", "D": "局部外渗", "E": "对比剂肾病"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-013", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】注射后数分钟内出现全身荨麻疹并伴胸闷、气短、血压下降趋势，已达中度过敏样反应，需积极处理。【为什么错】B患者已出现气道与血压受累，非单纯轻度反应；C迟发反应发生于1小时至1周，本例如为5分钟发作属速发；D外渗表现为局部肿痛，与本例全身症状不符；E CIN为肾功能指标变化，非即刻表现。", "tr": "“荨麻疹＋胸闷＋血压下降”提示反应升级，不能按轻度反应对待。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ04067", "gs": ""}, {"id": "ZG-U04-1036b", "t": "共用题干题", "s": "结合上述情景，此时技师及医护人员应首先采取的处理措施是", "o": {"A": "停止扫描，保持静脉通路，立即给予高流量吸氧并肌肉注射肾上腺素，同时监测生命体征", "B": "继续完成扫描后再说", "C": "让患者平卧休息自行缓解", "D": "仅口服抗组胺药后离室", "E": "立即静脉推注葡萄糖酸钙观察"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-014", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】中度以上过敏样反应应停止检查、保留静脉通路、吸氧、肌注肾上腺素并监测生命体征，防止进展为休克。【为什么错】B继续扫描延误抢救；C自行缓解有风险，可能发展为重度反应；D口服药起效慢，且不能处理气道与血压问题；E葡萄糖酸钙不是过敏性休克的首选，肾上腺素才是核心药物。", "tr": "抢救原则“停药→肾上腺素→吸氧→补液→监测”，肾上腺素不可被其他药物替代。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04068", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1037a", "t": "共用题干题", "s": "结合上述情景，针对该患者，技师及医师在对比剂方案上应作出的决策是", "o": {"A": "评估后选用等渗或低渗对比剂，控制剂量，检查前后充分水化", "B": "选用离子型高渗对比剂以保证显影", "C": "不限剂量直接注射", "D": "检查前后不补充液体", "E": "不使用任何预防措施直接检查"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-024", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】肾功能不全合并糖尿病患者为CIN高危人群，应选用低渗或等渗对比剂、控制用量并充分水化，必要时评估停药后继续使用的风险收益。【为什么错】B高渗离子型对比剂肾毒性最大，应避免；C大剂量增加肾毒性；D脱水是CIN危险因素，应补液；E高危患者必须采取预防措施。", "tr": "eGFR<45的中重度肾功能不全者增强CT需权衡利弊，并采用低渗/等渗剂＋水化策略。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04084", "gs": ""}, {"id": "ZG-U04-1037b", "t": "共用题干题", "s": "结合上述情景，关于该患者检查后随访与用药调整，正确的做法是", "o": {"A": "检查后继续鼓励饮水水化，监测肾功能，评估二甲双胍是否暂停", "B": "检查后无需任何观察", "C": "立即重复增强检查", "D": "暂停一切降压药物", "E": "术后完全禁水"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-025", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】检查后应继续水化、监测肾功能（48～72小时血肌酐），并依据肾功能评估二甲双胍是否暂停，避免乳酸酸中毒。【为什么错】B高危患者需随访观察；C短期内重复增强增加肾毒性；D降压药不应一律停用；E禁水与预防CIN矛盾。", "tr": "二甲双胍与碘对比剂联用需按eGFR评估是否暂停，且复查时机有明确规定。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04084", "gs": ""}, {"id": "ZG-U04-1038a", "t": "共用题干题", "s": "结合上述情景，为兼顾病灶血供评估与肝细胞来源判断，技师宜选用的对比剂是", "o": {"A": "肝细胞特异性对比剂钆塞酸二钠（Gd-EOB-DTPA）", "B": "硫酸钡", "C": "泛影葡胺", "D": "碘克沙醇", "E": "空气"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-015", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】Gd-EOB-DTPA既能行动态增强观察血供，又能经肝细胞摄取完成肝胆期成像，可判断结节是否为肝细胞来源。【为什么错】B硫酸钡为消化道X线对比剂；C、D为X线碘对比剂；E空气为阴性对比剂，均无MR肝胆特异性。", "tr": "肝特异性对比剂的价值在于“肝胆期”信号判断，可辅助区分再生结节、肝癌等病变。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04070", "gs": ""}, {"id": "ZG-U04-1038b", "t": "共用题干题", "s": "结合上述情景，该患者注射肝特异性对比剂后，完成肝胆期成像的最佳延迟时间是", "o": {"A": "注射后约20分钟（肝胆期延迟扫描）", "B": "注射后1分钟", "C": "注射后3天", "D": "立即扫描无需等待", "E": "注射前扫描"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-016", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】Gd-EOB-DTPA经肝细胞摄取并排入胆道需一定时间，通常在注射后约20分钟（10～20分钟范围）行肝胆期T1WI扫描。【为什么错】B 1分钟内为动脉期，非肝胆期；C 3天过晚，对比剂已大部排出；D肝胆期需等待摄取；E注射前无增强作用。", "tr": "“动态期＋肝胆期”双期成像是肝特异性对比剂检查方案的核心。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04070", "gs": ""}, {"id": "ZG-U04-1039a", "t": "共用题干题", "s": "结合上述情景，技师应首先采取的措施是", "o": {"A": "立即停止注射，保留针头回抽渗漏液后拔除针头", "B": "继续把剩余对比剂注完", "C": "加大流速快速注射", "D": "热敷促进吸收", "E": "让患者活动患肢促进循环"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-026", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】发现外渗应立即停止注射，尽量回抽渗漏的对比剂后拔针，再行后续处理。【为什么错】B继续注射会加重外渗；C加大流速加剧渗漏；D早期应冷敷而非热敷；E活动患肢会加重肿胀。", "tr": "外渗处理第一步永远是“停止注射”，先回抽再拔针可减少渗漏量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04085", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1039b", "t": "共用题干题", "s": "结合上述情景，关于外渗后的局部处理与观察，正确的是", "o": {"A": "抬高患肢，早期冷敷，密切观察皮肤颜色、肿胀范围及末梢循环", "B": "患肢下垂促进回流", "C": "立即热敷并按摩", "D": "无需观察自行恢复", "E": "加用高渗盐水局部注射"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-027", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】外渗后应抬高患肢、早期冷敷，并动态观察局部皮肤颜色、肿胀范围、疼痛与末梢循环情况。【为什么错】B患肢下垂不利于静脉回流；C早期热敷与按摩会加重损伤；D大量渗漏可能引起组织坏死，必须观察随访；E局部注射高渗盐水无依据且有风险。", "tr": "大量外渗（如>50ml）或出现水疱、皮肤苍白、神经症状时应请专科（整形/手外科）会诊。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04085", "gs": ""}, {"id": "ZG-U04-1040", "t": "共用题干题", "s": "结合上述情景，患者男，45岁，增强CT静脉注射碘对比剂后约2分钟出现剧烈胸闷、呼吸困难、大汗、口唇发绀，血压70/40mmHg，心率130次/分。技师及在场医护需立即组织抢救。关于抢救处理，正确的做法是", "o": {"A": "立即停止检查，保持静脉通路，高流量吸氧，快速肌注0.1%肾上腺素并快速补液", "B": "让患者自行平卧休息观察", "C": "只口服抗组胺药后嘱其离开", "D": "立即静脉注射造影剂补充血容量", "E": "嘱患者大量饮水促进排泄"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-028", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】本例为过敏性休克表现，应立即停药、吸氧、肌注肾上腺素、快速补液，并按需给予糖皮质激素与抗组胺药，必要时心肺复苏。【为什么错】B休克不处理可致死亡；C口服药起效慢且已出现休克，需静脉/肌注药物；D再注射对比剂会加重过敏；E饮水不能纠正休克。", "tr": "过敏性休克的黄金处理是“肾上腺素＋吸氧＋补液”，时间就是生命。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ04085", "gs": ""}, {"id": "ZG-U04-1041", "t": "共用题干题", "s": "结合上述情景，患者女，63岁，糖尿病肾病（eGFR 38ml/min/1.73m²），因下肢动脉闭塞拟行下肢CTA，需使用碘对比剂。关于该患者的对比剂应用策略，正确的是", "o": {"A": "权衡利弊后选用低渗或等渗对比剂，控制总量，检查前后充分水化，必要时行预防性评估", "B": "因肾功能差而加大对比剂剂量", "C": "使用离子型高渗对比剂", "D": "检查前禁饮禁食以减少不良反应", "E": "检查后立即行血液透析清除对比剂"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-029", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】对中重度肾功能不全者，应权衡CTA的必要性，若必须检查则选用低渗/等渗剂、控制总量并充分水化，最大程度降低CIN风险。【为什么错】B加大剂量增加肾毒性；C高渗剂风险最高；D脱水是CIN危险因素，应补液而非禁饮；E透析并非常规预防手段，且不能在注射后立即清除全部对比剂。", "tr": "CTA有临床指征时仍可进行，关键是“低渗/等渗＋限量＋水化”的综合策略。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ04086", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1043", "t": "共用题干题", "s": "结合上述情景，患者男，55岁，多发性硬化患者需行头颅MRI增强随访，既往对钆剂无过敏史，但血肌酐轻度升高（eGFR 52ml/min/1.73m²）。关于该患者钆剂使用的评估，正确的是", "o": {"A": "评估获益与风险，尽量选用大环类高稳定钆剂并避免重复大剂量使用", "B": "完全禁用任何钆剂", "C": "加倍剂量以保证强化", "D": "使用线性钆剂并增加剂量", "E": "无需考虑肾功能因素"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-017", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】中度肾功能不全（eGFR 30～60）患者应谨慎评估钆剂使用，尽量选择大环类高稳定剂、单次标准剂量、避免短期内重复使用。【为什么错】B中度肾功能不全并非绝对禁忌，需权衡利弊；C加倍剂量增加钆沉积风险；D线性剂稳定性低、风险更高；E肾功能是钆剂安全的重要考量。", "tr": "eGFR<30的重度肾功能不全者禁用线性钆剂，大环类也需谨慎评估。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ04068", "gs": ""}, {"id": "ZG-U04-1044", "t": "共用题干题", "s": "结合上述情景，患儿男，6岁，16kg，疑颅内占位，拟行头颅增强CT。按体重给药的原则，若采用2ml/kg的对比剂剂量，则本患儿应使用的对比剂总量约为", "o": {"A": "32ml", "B": "16ml", "C": "50ml", "D": "8ml", "E": "80ml"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-031", "kp": "X线对比剂引入途径", "ch": "四、对比剂 → 1.X线对比剂 → (3)引入途径", "ex": "【为什么对】对比剂总量＝体重×每公斤剂量＝16kg×2ml/kg＝32ml。【为什么错】B 16ml为1ml/kg剂量；C、D、E的数值与按体重计算不符。", "tr": "儿童碘对比剂按体重（1.5～2ml/kg）计算，成人则按固定方案（如60～100ml）并结合体重调整。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ04075", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1045", "t": "共用题干题", "s": "结合上述情景，患者男，48岁，肝细胞癌拟行钆塞酸二钠增强MRI，技师制定了“平扫＋动态增强（动脉期、门静脉期、过渡期）＋肝胆期延迟扫描”的方案。关于该方案的核心技术要点，正确的是", "o": {"A": "动态增强采用T1WI快速序列捕捉动脉期，肝胆期于注射后约20分钟采集", "B": "全程用T2WI观察强化", "C": "肝胆期于动脉期同时完成", "D": "只做平扫即可诊断", "E": "对比剂口服后立即扫描"}, "d": "中", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-018", "kp": "MR对比剂临床应用", "ch": "四、对比剂 → 2.MR对比剂 → (4)临床应用", "ex": "【为什么对】肝特异性对比剂检查需T1WI动态多期捕捉血供（动脉期、门静脉期），并经约20分钟延迟行肝胆期成像，双期相结合用于病灶定性。【为什么错】B强化观察必须用T1WI；C肝胆期需等待肝细胞摄取，与动脉期不同时；D平扫无法评估血供与肝细胞功能；E钆剂经静脉注射，非口服。", "tr": "“T1WI动态期＋肝胆期”是肝特异性对比剂检查的两大组成部分。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04071", "gs": "患者需使用对比剂进行检查，关于对比剂相关描述正确的是。"}, {"id": "ZG-U04-1046", "t": "共用题干题", "s": "结合上述情景，患者女，42岁，行子宫输卵管造影（HSG）检查，注射含碘对比剂后出现轻微恶心、面部潮红及一过性咳嗽，血压、心率正常。正确的处理是", "o": {"A": "密切观察，暂停操作，安慰患者，多数轻微反应可自行缓解，必要时对症处理", "B": "立即肌注肾上腺素", "C": "立即行心肺复苏", "D": "加大对比剂剂量继续检查", "E": "让患者立即离室回家"}, "d": "难", "c": "应用", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-CM-032", "kp": "碘对比剂毒性反应及防治", "ch": "四、对比剂 → 1.X线对比剂 → (4)碘对比剂毒性反应及防治", "ex": "【为什么对】轻度反应（恶心、潮红、一过性咳嗽）且生命体征平稳时，应暂停操作、密切观察并安慰患者，多数自行缓解。【为什么错】B肾上腺素用于中重度反应；C心肺复苏针对心搏骤停；D增加剂量加重反应；E轻度反应也需留观，确认缓解后再离室。", "tr": "轻度反应“观察为主”，但要警惕从轻度升级为中重度，需持续监测。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "X线对比剂", "页": 110}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ04086", "gs": ""}, {"id": "ZG-U04-1047", "t": "共用题干题", "s": "结合上述情景，患者男，70岁，前列腺癌术后拟行全身骨扫描外的盆腔增强MR评估，患者eGFR 25ml/min/1.73m²（重度肾功能不全）。关于该患者使用钆剂的决策，正确的是", "o": {"A": "优先考虑不使用钆剂的MR平扫方案，确需增强时由临床与影像科权衡风险，慎用或选用最安全策略", "B": "常规使用线性钆剂", "C": "加倍剂量使用钆剂", "D": "忽略肾功能直接增强", "E": "使用泛影葡胺替代钆剂"}, "d": "难", "c": "分析", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-MRC-019", "kp": "MR对比剂不良反应及处理", "ch": "四、对比剂 → 2.MR对比剂 → (5)不良反应及处理", "ex": "【为什么对】重度肾功能不全（eGFR<30）使用钆剂有NSF风险，应尽量采用无增强的替代方案，确需增强时由多学科权衡并选择风险最低的策略。【为什么错】B线性钆剂在重度肾功能不全者中风险最高，应避免；C加倍剂量显著增加风险；D忽略肾功能不符合安全原则；E泛影葡胺为X线对比剂，不用于MR。", "tr": "eGFR<30是钆剂（尤其线性剂）使用的“红线”，NSF风险是核心考量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ04068", "gs": ""}, {"id": "ZG-U04-9005", "t": "单选题", "s": "与非离子型低渗碘对比剂相比，等渗碘对比剂（如碘克沙醇）的主要优势是", "o": {"A": "含碘量更高、增强更明显", "B": "渗透压与血浆等渗，可降低高渗相关的血管内皮损伤与不良反应", "C": "价格更低廉、更适合大规模使用", "D": "可经口服给药", "E": "代谢更快、不经肾脏排泄"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-009", "kp": "等渗碘对比剂优势", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】B正确——等渗对比剂渗透压约 290 mOsm/kg，与血浆等渗，较传统低渗对比剂（约 600–800 mOsm/kg）更接近生理，可减轻血管内皮细胞脱水损伤、红细胞变形及肾髓质缺氧，降低对比剂肾病与过敏样反应风险。【为什么错】A含碘量并非等渗剂独有优势；C等渗剂通常价格更高；D碘对比剂均不口服用于血管内增强（消化道造影另论）；E仍需经肾排泄。", "tr": "等渗≠\"无肾毒性\"，仅降低渗透压相关风险，仍须水化与评估肾功能。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "对比剂的进展", "页": 118}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U04-9006", "t": "单选题", "s": "钆对比剂（GBCA）按配体结构分为线性和大环类，关于其安全性的正确表述是", "o": {"A": "线性对比剂比大环类更稳定，游离钆释放更少", "B": "大环类对比剂因配体包裹更紧密，游离钆释放更少、NSF 风险相对更低", "C": "两类在稳定性与 NSF 风险上无差异", "D": "线性对比剂完全不释放游离钆，可安全用于重度肾功能不全", "E": "大环类对比剂禁止用于估算肾小球滤过率＜30 的患者"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-010", "kp": "钆对比剂结构分类与安全", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】B正确——大环类（如钆特酸、钆布醇）配体将钆离子紧密包裹，热力学与动力学稳定性高，游离钆释放极少；线性非离子型（如钆双胺）稳定性相对较低，在肾功能不全者中 NSF 风险更高，故指南更推荐大环类用于高危人群。【为什么错】A事实相反；C忽略稳定性差异；D线性剂仍可能释放游离钆，重度肾功能不全须严格评估并首选大环类或不增强；E大环类在 eGFR＜30 仍可用但需权衡，并非绝对禁止。", "tr": "易记反\"线性/大环\"的稳定性高低；且 NSF 风险与肾功能不全程度强相关。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "对比剂的进展", "页": 118}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U04-9007", "t": "单选题", "s": "钆塞酸二钠（Gd-EOB-DTPA）作为肝细胞特异性 MR 对比剂，其特有的优势是", "o": {"A": "仅用于中枢神经系统增强", "B": "兼具细胞外非特异性分布与肝胆期肝细胞摄取，可显示肝细胞功能并检出小肝癌", "C": "完全不经肾脏排泄", "D": "显影时间不受肝功能影响", "E": "可用于所有肾功能不全患者无需评估"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-011", "kp": "肝细胞特异性对比剂", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】B正确——钆塞酸二钠约 50% 经肝细胞摄取并经胆汁排泄，注射后约 20 分钟进入肝胆期，正常肝实质明显强化而肝内病灶（如小肝癌、转移瘤）因缺乏摄取呈低信号，兼具动态期与肝胆期信息，提高小病灶检出与定性。【为什么错】A其并不限于中枢；C仍有约半数经肾排泄；D肝胆期摄取依赖肝功能，重度肝病患者肝胆期弱化；E仍含钆，须评估肾功能与 NSF 风险。", "tr": "肝胆期依赖肝细胞功能，肝功能严重受损时该优势减弱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "对比剂的进展", "页": 118}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U04-9008", "t": "单选题", "s": "近年来对比剂研发的进展方向不包括以下哪项", "o": {"A": "高浓度、低黏度以优化注射与增强", "B": "等渗或近等渗以降低不良反应", "C": "器官/组织特异性靶向对比剂（如肝细胞、血池、CEST）", "D": "提高碘对比剂的放射剂量以增强 CT 成像", "E": "生物可降解或生物相容性更好的新型材料"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-012", "kp": "对比剂研发方向", "ch": "四、对比剂 → 3.对比剂的进展 → 新型对比剂与个体化应用进展", "ex": "【为什么对】D正确——对比剂研发追求\"更低风险、更高特异性\"，提高放射剂量既不必要也违背 ALARA 与防护原则；CT 增强靠碘浓度与团注而非提高射线剂量。【为什么错】A、B、C、E均为实际研发方向：高浓度低黏度便于大剂量高速注射，等渗降低渗透压损伤，靶向对比剂拓展功能成像，可降解/高生物相容材料减少长期沉积与毒性担忧。", "tr": "易把\"提高图像质量\"误认为\"提高射线剂量\"，防护原则恰相反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "对比剂的进展", "页": 118}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U04-9201", "t": "单选题", "s": "碘对比剂按渗透压分类，等渗对比剂相对于高渗对比剂的主要优点是", "o": {"A": "血管内更安全、不良反应更少", "B": "价格更低", "C": "显影更弱", "D": "半衰期更长", "E": "无需过敏试验"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-9201", "kp": "碘剂渗透压", "ch": "四、对比剂 → 3.对比剂的进展", "ex": "【为什么对】等渗（如碘克沙醇）渗透压接近血浆，血管内耐受性更好、不良反应较少。\n【为什么错】价格与显影强度并非其优点。", "tr": "等渗碘剂更安全。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U04-9202", "t": "单选题", "s": "钆对比剂用于 MRI 增强的机制是", "o": {"A": "缩短周围质子 T1 弛豫时间", "B": "延长 T1", "C": "延长 T2", "D": "产生电离", "E": "吸收 X 线"}, "d": "中", "c": "理解", "m": "专业知识", "u": "四", "un": "对比剂", "kpid": "UNIT-04-NEW-9202", "kp": "钆剂机制", "ch": "四、对比剂 → 3.对比剂的进展", "ex": "【为什么对】钆为顺磁性，缩短 T1 使强化组织在 T1WI 呈高信号。\n【为什么错】钆缩短而非延长弛豫，不吸收X线。", "tr": "钆剂缩短T1。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "对比剂", "节": "MR对比剂", "页": 114}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U05-0101", "t": "共用题干题", "s": "结合上述情景，关于影像质量保证（QA）与影像质量控制（QC）的相互关系，下列表述正确的是", "o": {"A": "QC 是管理层面的组织性活动，QA 是技术层面的具体测量手段", "B": "QA 是有计划、有系统的全面管理活动，QC 是其中以技术手段监测并维持设备与图像性能的具体措施", "C": "QA 与 QC 内涵完全相同，只是中英文译法不同", "D": "QA 由设备工程师独立负责，QC 由医院行政管理部门负责", "E": "QA 只针对影像设备性能，QC 只针对图像的主观评价"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-001", "kp": "质量保证与质量控制的概念关系", "ch": "五、影像质量管理 → 1.概述 → (1)基本概念", "ex": "【为什么对】B 正确。质量保证（Quality Assurance，QA）是为使影像诊断达到预期质量目标而开展的有计划、有系统的全面管理活动，涵盖组织架构、规章制度、人员培训、设备采购与验收、检查流程、患者剂量管理与结果评价等，属于\"体系\"层面；质量控制（Quality Control，QC）是 QA 体系中的技术执行环节，通过对设备性能与图像指标的定期检测、校准、评价与纠正，把技术参数维持在规定容许范围内，属于\"指标\"层面。二者是包含关系，QC 从属并服务于 QA。【为什么错】A 把两者层次完全颠倒。C 二者外延与工作方式不同，不是同义词。D 职责划分错误：QA 需管理层主导、全员参与，QC 主要由技师与工程技术人员执行。E 两者的作用对象都同时包括设备、技术、图像与流程，不存在这种机械分工。", "tr": "记忆口诀\"QA 是纲、QC 是目；QA 建体系、QC 控指标\"。命题常反向设问\"QC 包含 QA\"或把两者的层次互换来设陷。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05107", "gs": ""}, {"id": "ZG-U05-0102", "t": "多选题", "s": "科室拟用 PDCA 循环推进影像质量持续改进，下列关于 PDCA 各阶段的表述正确的有", "o": {"A": "P（Plan）阶段包括现状调查、原因分析、确定主要原因并制定针对性对策与目标", "B": "D（Do）阶段是按既定对策组织实施，并做好过程记录", "C": "C（Check）阶段是用数据对实施效果进行检查、与目标值对比并总结", "D": "A（Action）阶段将证实有效的措施标准化固化，未解决的问题转入下一个循环", "E": "PDCA 完成一次循环即达到质量目标，无须重复运行"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-002", "kp": "PDCA 循环与质量管理方法", "ch": "五、影像质量管理 → 1.概述 → (2)管理方法", "ex": "【为什么对】A、B、C、D 均正确。PDCA（戴明环）是全面质量管理的基本工作程序：计划（Plan）阶段完成现状分析、原因剖析、要因确认与对策制定；实施（Do）阶段按计划执行并留痕；检查（Check）阶段用客观数据评价效果；处理（Action）阶段把有效经验标准化写入操作规程，把遗留问题带入下一循环。【为什么错】E 错误。PDCA 的本质特征是\"周而复始、螺旋式上升\"，每转一圈质量水平提升一个台阶，遗留问题成为下一循环的输入，不存在\"一次循环即告完成\"的情形。", "tr": "易混点在 C 与 A 的界限：Check 只做效果验证与数据比对，把\"标准化、纳入规程\"错记到 Check 阶段是常见失分点，标准化属于 Action。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-0103", "t": "共用题干题", "s": "结合上述情景，下列关于影像质量主观评价方法（含 ROC 分析）的描述，正确的是", "o": {"A": "视觉评价法客观性强，评价结果基本不受观察者经验影响", "B": "ROC 曲线以真阳性率为纵坐标、假阳性率为横坐标，曲线下面积（AUC）越大诊断效能越高", "C": "ROC 分析因使用了统计计算，应归入客观评价法", "D": "主观评价法带有观察者因素，现已被客观物理测量完全取代", "E": "ROC 曲线越靠近坐标图右下角，说明成像系统的诊断效能越好"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-003", "kp": "主观评价法与 ROC 分析", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】B 正确。受试者操作特性（ROC）曲线以真阳性率（灵敏度）为纵轴、假阳性率（1-特异度）为横轴，通过改变判断阈值得到一条曲线；曲线下面积 AUC 取值 0.5～1.0，0.5 相当于随机猜测、无诊断价值，越接近 1.0 诊断效能越高。【为什么错】A 视觉评价（解剖部位显示评分法、五分法等）依赖观察者经验、心理状态与阅片环境，重复性相对较差。C ROC 的原始数据来自观察者的判断，属主观（观察者）评价范畴，只是用统计学方法加以量化。D 主观评价最贴近临床诊断需求，与客观评价互为补充，并未被取代。E 方向错误，ROC 曲线越靠近左上角（高灵敏度、低假阳性）效能越好。", "tr": "ROC 有 AUC 这样的量化指标，极易被误判为客观评价法。客观评价指的是分辨率、噪声、对比度、伪影等物理量的仪器测量；ROC 属于以观察者为核心的主观评价。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05101", "gs": ""}, {"id": "ZG-U05-0104", "t": "共用题干题", "s": "结合上述情景，影像质量的综合评价把物理测量与观察者判断结合起来，下列关于综合评价指标的表述正确的有", "o": {"A": "对比度-细节（C-D）曲线用 C-D 体模测定不同直径细节被察觉所需的最低对比度，曲线越靠近坐标原点系统性能越好", "B": "量子探测效率 DQE 综合了调制传递函数 MTF、噪声功率谱 NPS 与入射光子数，反映系统对入射 X 线量子信息的利用效率", "C": "综合评价法兼顾物理指标与视觉察觉能力，比单纯客观或单纯主观评价更贴近临床实际", "D": "DQE 的理论最大值为 1（100%），实际探测器的 DQE 小于 1 且随空间频率升高而下降", "E": "C-D 曲线只反映系统的空间分辨率，与图像噪声水平无关"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-004", "kp": "综合评价法：C-D 曲线与 DQE", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】A 正确：C-D 体模由一系列直径递减、对比度递减的圆孔阵列构成，观察者标出可分辨的最小圆孔，连线即 C-D 曲线；越靠近原点表示越小的细节、越低的对比度也能被察觉，系统越好。B 正确：DQE(f)=MTF²(f)/[NNPS(f)·q]，同时包含信号传递能力、噪声特性与入射量子数。C 正确：综合评价的价值就在于把物理性能折算为\"能否被人眼在临床条件下察觉\"。D 正确：DQE 是输出 SNR² 与输入 SNR² 之比，理想探测器为 1，实际系统因量子损失、结构噪声与散射恒小于 1，并随空间频率升高而衰减。【为什么错】E 错误：C-D 曲线本质是低对比可探测度评价，噪声直接决定小细节能否被察觉，曲线同时受分辨率与噪声共同支配，剂量降低时曲线会明显右上移。", "tr": "把 C-D 曲线当成纯粹的分辨率体模是常见误解。区分方法：线对卡测的是高对比空间分辨率；C-D 体模测的是低对比可探测度，对噪声极敏感。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ05106", "gs": ""}, {"id": "ZG-U05-0105", "t": "单选题", "s": "使用富士（Fujifilm）CR 系统时，读取后显示的 S 值（Sensitivity value）与影像板接收剂量之间的关系是", "o": {"A": "S 值与接收剂量成正比，S 值越大表示曝光越充分", "B": "S 值与接收剂量成反比，标准曝光条件下 S 值约为 200", "C": "S 值与接收剂量无关，仅反映所选用的后处理参数组", "D": "S 值在数值上等于本次曝光所用的管电流量（mAs）", "E": "S 值越小说明曝光不足，应提高曝光条件重新摄影"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-001", "kp": "CR 曝光指数（富士 S 值）", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】B 正确。富士 CR 的 S 值是读取时自动灵敏度调节的输出量，与 IP 板实际接收的 X 线剂量成反比：标准入射剂量（约 1 mR，即约 8.7 μGy）对应 S≈200；剂量增加一倍，S 值约降为一半。S 值明显升高提示曝光不足、量子噪声增大；S 值明显偏低提示过度曝光、患者剂量偏高。【为什么错】A 方向相反。C S 值直接由 IP 板接收剂量决定，虽受读取参数影响但绝非与剂量无关。D S 值受 kV、体厚、SID、滤线栅等共同影响，与 mAs 没有等量关系。E 方向说反，S 值越小说明接收剂量越高。", "tr": "富士与柯尼卡的 S 值\"数值越大越欠曝\"，而爱克发 lgM、锐珂 EI、飞利浦 EI 以及 IEC 62494 标准 EI 都是\"数值越大越过曝\"，方向相反，是本考点最高频的混淆来源。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0106", "t": "单选题", "s": "某 DR 系统按 IEC 62494 标准同时显示曝光指数 EI 与目标曝光指数 EIT。一次胸部后前位摄影后显示 EI=400、EIT=200，下列判断与处置正确的是", "o": {"A": "偏差指数 DI=10×lg(EI/EIT)≈+3，说明探测器实际接收剂量约为目标值的 2 倍，应下调后续曝光条件", "B": "DI≈-3，说明曝光不足，应提高 mAs 后重新摄影", "C": "DI≈+2，处于理想区间，无须任何处置", "D": "标准 EI 与剂量成反比，EI=400 说明剂量只有目标值的一半", "E": "只要 EI 大于 EIT 就应立即重拍，以保证图像质量"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-002", "kp": "曝光指数 EI 与偏差指数 DI 的应用", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】A 正确。按 IEC 62494-1，偏差指数 DI=10×lg(EI/EIT)=10×lg2≈+3.0。DI 每变化 3 约对应剂量变化一倍，DI≈+3 即实际探测器剂量约为目标值的 2 倍。DI 在 0±1 为理想，±1～±3 需关注，超过 +3 属明显过曝，虽图像可用但违背 ALARA 原则，应回顾并下调曝光条件（如降 mAs 或改用自动曝光控制）。【为什么错】B 符号判断错误，DI 为正值代表过曝。C 计算错误，lg2≈0.301，乘 10 后约为 3 而非 2。D 标准 EI 与探测器校准剂量成正比，这是 IEC 62494 统一方向的核心内容。E 过曝图像通常仍满足诊断要求，重拍只会额外增加受检者剂量，正确做法是保留图像并改进后续参数。", "tr": "\"欠曝可能要重拍、过曝一般不重拍\"是剂量管理的基本原则。另需牢记 DI 的对数关系：DI=+3 对应 2 倍剂量、DI=-3 对应 1/2 剂量，而不是 3 倍或 1/3。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0107", "t": "多选题", "s": "不同厂商数字 X 线设备所用曝光指示量的定义方向并不一致，下列对应关系正确的有", "o": {"A": "富士（Fujifilm）的 S 值与探测器接收剂量成反比", "B": "柯尼卡（Konica）的 S 值同样与探测器接收剂量成反比", "C": "爱克发（Agfa）的 lgM 与接收剂量成正比，且呈对数关系，lgM 增加约 0.30 相当于剂量加倍", "D": "GE 的 DEI（探测器曝光指数）为实测剂量与预期剂量之比，与剂量成正比，理想值接近 1.0", "E": "IEC 62494-1 统一定义的 EI 与探测器校准剂量成反比"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-003", "kp": "各厂家曝光指数体系的方向差异", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】A、B 正确：富士与柯尼卡的 S 值均定义为灵敏度值，剂量越高 S 值越小，标准值约 200。C 正确：爱克发以扫描平均值的对数 lgM 表示，与剂量成正比，因是常用对数刻度，剂量加倍对应 lgM 增加 lg2≈0.30。D 正确：GE 的 DEI 是实测探测器曝光与该解剖部位预期曝光的比值，与剂量成正比，理想值 1.0 附近，偏离越大提示曝光偏差越大。【为什么错】E 错误：IEC 62494-1 统一定义的 EI 与探测器校准剂量成正比（EI=100×g(V)），并配套 EIT 与 DI 使用。正是因为各厂家原有指标量纲与方向混乱、无法横向比较，才制定该国际标准加以统一。", "tr": "记忆分组：\"反比派\"只有富士、柯尼卡的 S 值；爱克发 lgM、锐珂/柯达 EI、飞利浦 EI、西门子 EXI、GE DEI 以及 IEC 标准 EI 都是正比派。考试常把 IEC 标准 EI 说成反比来设陷。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-0108", "t": "单选题", "s": "剂量面积乘积（DAP，亦称 KAP）常被安装在 X 线管管套出口处用于剂量监测，关于其含义下列描述正确的是", "o": {"A": "DAP 的单位为 mGy，表示受检者的皮肤入射剂量", "B": "DAP 为照射野内空气比释动能与照射野面积之积，常用单位 mGy·cm²，其数值沿射线束路径近似不随距离改变", "C": "DAP 只取决于管电压，与照射野大小无关", "D": "DAP 数值越大说明图像信息量越丰富，应尽量提高", "E": "DAP 无法用于估算受检者的有效剂量"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-004", "kp": "剂量面积乘积 DAP 的物理意义", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】B 正确。DAP=空气比释动能×照射野面积。由于剂量随距离平方反比衰减、而照射野面积随距离平方增大，二者相乘后在射线束内近似为常数，因此透射电离室安装在管套出口即可代表整个射线束，测量结果与探测位置无关。【为什么错】A 单位是 mGy·cm²（或 Gy·cm²），皮肤入射剂量 ESD 的单位才是 mGy。C 照射野面积是 DAP 的直接因子，缩小照射野是降低 DAP 最有效的手段之一。D 提高 DAP 只增加受检者剂量，质量管理要求在满足诊断的前提下使用尽可能低的剂量。E DAP 乘以部位相关转换系数可粗略估算有效剂量，是介入与摄影剂量管理的常规做法。", "tr": "DAP 反映射线束携带的总能量，适合评估随机性效应与集体剂量；而峰值皮肤剂量 PSD/ESD 才用于评估确定性效应（如介入术后放射性皮肤损伤）。两者不能互相替代。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0109", "t": "共用题干题", "s": "结合上述情景，数字 X 线摄影日常工作中出现下列伪影表现，其原因分析正确的有", "o": {"A": "CR 图像上叠加有既往检查的淡影（残影），多因 IP 板擦除不彻底或长期闲置未做预擦除", "B": "DR 图像固定位置反复出现白点或坏线，多为探测器像素缺陷、增益与坏点校正表失效，需重新执行探测器校正", "C": "DR 图像出现规则的细密条纹（摩尔纹），多因滤线栅栅密度与探测器采样频率发生混叠", "D": "CR 图像沿激光扫描方向出现细直线状条纹，常见于扫描光路污染或集光导光器积尘", "E": "图像整体颗粒感重、噪声明显，最常见原因是模数转换器位深不足"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-005", "kp": "CR/DR 常见伪影的原因排查", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】A 正确：IP 板上的潜影若未被强光彻底擦除，会在下次曝光图像中留下残影，长期存放的 IP 板还会累积本底辐射信号，使用前应做预擦除。B 正确：平板探测器的坏点、坏线属硬件与校正表问题，特征是位置固定、与患者体位无关，需重做暗场/亮场与坏点校正。C 正确：栅密度与探测器像素采样频率接近整数倍关系时发生空间频率混叠，形成摩尔纹，可更换栅比/栅密度或改变栅的取向解决。D 正确：CR 读取系统光路上的灰尘与污渍使该扫描线信号衰减，形成与扫描方向一致的直条纹。【为什么错】E 错误：整体颗粒感重最常见的原因是曝光剂量不足导致量子噪声占主导，可通过曝光指数核实并调整条件；A/D 位深不足的典型表现是灰阶过渡出现阶梯状伪轮廓（假等高线），而非弥漫颗粒噪声。", "tr": "鉴别要点是\"位置是否固定\"：位置固定不随体位改变的多为探测器/读取系统硬件问题；随患者与投照条件改变的多为曝光、散射、栅或运动因素。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05092", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-0110", "t": "单选题", "s": "ACR 乳腺 X 线体模内含 6 根模拟纤维、5 组模拟微钙化点群与 5 个模拟肿块，按通用验收标准，合格图像至少应能分辨出", "o": {"A": "3 根纤维、2 组钙化点群、2 个肿块", "B": "4 根纤维、3 组钙化点群、3 个肿块", "C": "5 根纤维、4 组钙化点群、4 个肿块", "D": "6 根纤维、5 组钙化点群、5 个肿块", "E": "2 根纤维、2 组钙化点群、3 个肿块"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-001", "kp": "ACR 乳腺体模图像质量评价标准", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】B 正确。ACR 乳腺体模评分采用\"4-3-3\"最低合格标准：至少清晰显示 4 根纤维、3 组微钙化点群、3 个肿块，且计数时只有完整可辨者计 1 分、半数可辨计 0.5 分，末位分数不足者向下取整。该体模检测属乳腺机质控的核心项目，通常要求每周或每月进行一次。【为什么错】A、E 标准过低，达不到临床诊断要求。C、D 要求过高，超出了通用验收合格线，实际优秀设备可达到但不是最低标准。", "tr": "\"4-3-3\"必须与体模内含数量\"6-5-5\"分开记忆。另注意合格判定同时还要求无明显伪影，且体模图像的光学密度/像素值与本底对比度符合规定。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0111", "t": "共用题干题", "s": "结合上述情景，针对乳腺 X 线摄影的质量控制与剂量管理，下列做法与认识正确的有", "o": {"A": "以 4.2 cm 厚度、相当于 50% 腺体与 50% 脂肪的标准体模曝光时，单次摄影的平均腺体剂量（AGD）应控制在 3 mGy 以内", "B": "适度压迫可减少组织重叠与散射线、缩短物-片距、使乳腺厚度均匀，从而在降低剂量的同时提高清晰度", "C": "电动压迫力上限一般不超过约 200 N，并应在受检者可耐受的前提下尽量压迫充分", "D": "AGD 不能直接测量，需由入射空气比释动能结合压迫厚度、腺体含量与半价层，通过转换系数换算得到", "E": "为提高微钙化的检出率，应选用 40 kV 以上的高管电压以增强穿透力"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-002", "kp": "乳腺摄影平均腺体剂量与压迫质控", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】A 正确：以标准体模评价时，含滤线栅条件下单次摄影 AGD 的通用限值为 3 mGy。B 正确：压迫使乳腺厚度减薄且均匀，减少重叠与散射、减小几何模糊与运动模糊，并降低达到相同影像质量所需的剂量。C 正确：设备的电动压迫力通常设有约 200 N 的上限，实际以受检者耐受为准，压迫不足会导致厚度增加、剂量上升与影像模糊。D 正确：AGD 是通过测量入射空气比释动能，再按压迫厚度、腺体比例与半价层查表取转换系数计算得到的估算量。【为什么错】E 错误：乳腺摄影使用低管电压（一般 25～32 kV）配合钼、铑或钨靶及相应滤过，靠低能 X 线放大软组织与钙化的衰减差异；管电压升到 40 kV 以上会显著压缩对比度，微钙化反而更难显示。", "tr": "\"高 kV 穿透力强所以图像好\"在乳腺摄影中完全不成立——乳腺摄影追求的是软组织对比度而非穿透力，这是与胸部高千伏摄影截然相反的思路。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05102", "gs": ""}, {"id": "ZG-U05-0112", "t": "单选题", "s": "CT 设备日常质控中，用直径约 20 cm 的水模检测 CT 值准确性，在中心区域 ROI 测得的水 CT 值验收标准通常应为", "o": {"A": "0 HU ± 4 HU", "B": "0 HU ± 40 HU", "C": "-1000 HU ± 4 HU", "D": "100 HU ± 4 HU", "E": "只要测得值为负值即为合格"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-001", "kp": "CT 值准确性与水模标定", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】A 正确。CT 值以水为 0 HU、空气为 -1000 HU 定标，是全部密度判读的基准。现行标准对水模中心 CT 值的验收检测要求在 0 HU ± 4 HU 以内，状态检测可放宽到约 ±6 HU；同时在同一层面测均匀性，即周边 4 个 ROI 与中心 ROI 的 CT 值差值也应在规定范围内。【为什么错】B 容许范围过宽，±40 HU 已足以把水误判为软组织或脂肪，严重影响定量诊断。C -1000 HU 是空气的 CT 值。D 100 HU 附近对应致密软组织或轻度钙化，与水无关。E 未设定量限值，不能作为判定依据；水 CT 值偏离可正可负，关键看绝对偏差大小。", "tr": "水模 CT 值漂移常提示需要重新做空气校正（air calibration）或球管老化，日检发现偏差应先做空气校正再复测，而非直接调整窗口设置掩盖问题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0113", "t": "单选题", "s": "某腹部 CT 扫描为降低剂量，将管电流量由 200 mAs 降至 50 mAs，其余参数（管电压、层厚、螺距、重建算法）不变。在滤波反投影重建条件下，图像噪声标准差的变化是", "o": {"A": "降低为原来的约一半", "B": "基本保持不变", "C": "增大为原来的约 1.4 倍", "D": "增大为原来的约 2 倍", "E": "增大为原来的约 4 倍"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-002", "kp": "CT 噪声与剂量的平方根关系", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】D 正确。CT 图像的量子噪声标准差 σ 与探测到的光子数平方根成反比，即 σ∝1/√剂量。mAs 由 200 降到 50，剂量降为原来的 1/4，噪声增大为 √4=2 倍。【为什么错】A 方向相反，降低 mAs 只会增加噪声。B 在滤波反投影条件下噪声与剂量强相关，不可能不变。C 1.4（即 √2）倍对应剂量减半，即 mAs 由 200 降到 100 的情形。E 4 倍噪声对应剂量降至 1/16，即 mAs 降到 12.5。", "tr": "反向命题更常见：\"要把噪声降低一半需要增加多少剂量\"，答案是 4 倍而非 2 倍。同理，层厚减半（其余不变）也使噪声增至约 √2 倍，因为单个体素接收的光子数减半。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0114", "t": "共用题干题", "s": "结合上述情景，关于 CT 空间分辨率与低对比分辨率（密度分辨率）各自的影响因素，下列表述正确的有", "o": {"A": "空间分辨率主要取决于探测器孔径、X 线管焦点、采样密度、重建视野与矩阵以及重建卷积核", "B": "低对比分辨率主要受噪声水平支配，因此与 mAs、层厚、重建算法关系密切", "C": "选用高分辨率（骨/锐利）卷积核可提高空间分辨率，但同时放大噪声、使低对比分辨率下降", "D": "增大层厚可降低噪声、改善低对比分辨率，但会加重部分容积效应并降低 Z 轴分辨率", "E": "提高 mAs 可以同时显著提高空间分辨率与低对比分辨率"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-003", "kp": "空间分辨率与低对比分辨率的影响因素", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】A 正确：空间分辨率（高对比分辨率）由几何采集条件与重建参数决定，像素尺寸=重建视野/矩阵，是其上限约束。B 正确：低对比分辨率考察在低对比背景中辨认物体的能力，噪声是决定性因素，凡影响噪声的参数都影响它。C 正确：锐利卷积核提升高频响应的同时也放大高频噪声，是典型的\"此消彼长\"。D 正确：层厚加倍使体素内光子数加倍、噪声降至约 1/√2，但纵向分辨率下降、部分容积效应加重。【为什么错】E 错误：提高 mAs 通过降噪改善低对比分辨率，但空间分辨率由焦点、探测器孔径、采样与重建核等几何/算法因素决定，与 mAs 基本无关；只有在极低剂量、噪声完全淹没细节时才存在间接影响。", "tr": "\"薄层+锐利核\"是提高空间分辨率的组合，代价是噪声上升；\"厚层+平滑核+高 mAs\"是提高低对比分辨率的组合，代价是细节模糊。两类分辨率不可能同时最优，命题常用 E 这类\"两全其美\"的选项设陷。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05105", "gs": ""}, {"id": "ZG-U05-0115", "t": "案例分析题", "s": "一名 45 岁女性无症状体检者，既往无胸部疾病史，因肺癌筛查行胸部低剂量 CT 平扫。扫描完成后控制台剂量报告显示：CTDIvol=2.0 mGy，扫描长度 25 cm，DLP=50 mGy·cm。受检者对辐射较为焦虑，询问本次检查\"到底吃了多少射线\"，要求技师给出一个可与日常生活比较的数值。已知成人胸部 CT 有效剂量转换系数 k 约为 0.014 mSv/(mGy·cm)。作为高年资技师，下列计算与解释中正确的是", "o": {"A": "有效剂量约为 0.7 mSv；DLP 由 CTDIvol 乘以扫描长度得到，再乘以部位转换系数 k 即得有效剂量估算值", "B": "有效剂量约为 7 mSv，与一次常规腹部增强 CT 相当", "C": "有效剂量约为 0.028 mSv，由 CTDIvol 乘以 k 得到", "D": "CTDIvol 即受检者接受的有效剂量，本次为 2.0 mSv", "E": "DLP 应等于 CTDIvol 除以螺距，本例为 50 mGy"}, "d": "难", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-004", "kp": "CTDIvol、DLP 与有效剂量的换算", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】A 正确。DLP=CTDIvol×扫描长度=2.0 mGy×25 cm=50 mGy·cm，与机器显示一致；有效剂量 E≈DLP×k=50×0.014=0.7 mSv。该量级约相当于数月的天然本底照射，可用于向受检者做通俗解释。【为什么错】B 数量级错误，7 mSv 已接近常规腹盆腔增强 CT 的水平，与低剂量胸部 CT 不符。C 混淆了公式，k 应乘以 DLP 而非 CTDIvol，且 CTDIvol 的单位是 mGy、不含扫描长度信息。D CTDIvol 是标准体模内的加权剂量指数，单位为 mGy，只表征扫描技术的剂量输出水平，不等于考虑了器官权重的有效剂量。E 公式错误：螺旋扫描时 CTDIvol=CTDIw/螺距，螺距的影响已包含在 CTDIvol 内；DLP=CTDIvol×长度，单位为 mGy·cm。", "tr": "k 值随部位差别很大：头部约 0.0021、颈部约 0.0059、胸部约 0.014、腹部与盆腔约 0.015 mSv/(mGy·cm)。若误用头部 k 计算胸部，结果会低估近 7 倍，是典型的计算类失分点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0116", "t": "单选题", "s": "某多层螺旋 CT 以\"有效 mAs\"（effective mAs = mAs/螺距）方式设定曝光条件。技师将螺距由 0.8 提高到 1.2，有效 mAs 设定值与其余参数不变，此时", "o": {"A": "系统自动按比例提高实际管电流量，CTDIvol 与图像噪声基本不变，扫描时间缩短", "B": "患者剂量降为原来的约 2/3，图像噪声相应增大", "C": "图像噪声降低而患者剂量升高", "D": "扫描时间保持不变，但 Z 轴分辨率提高", "E": "螺距的改变与扫描时间无关"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-005", "kp": "螺距、有效 mAs 与图像质量的关系", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】A 正确。有效 mAs=实际 mAs/螺距，而螺旋扫描的 CTDIvol=CTDIw/螺距，因此 CTDIvol 与有效 mAs 成正比。保持有效 mAs 不变、螺距由 0.8 增到 1.2 时，设备会自动把实际管电流量提高到原来的 1.5 倍，使单位长度的剂量与噪声水平基本恒定；同时床进速度加快，扫描同样长度所需时间缩短。【为什么错】B 这是设定\"每圈 mAs\"（mAs/rotation）方式下的结论：此时提高螺距会使剂量按 1/螺距下降、噪声上升。本题设定的是有效 mAs，两者结论相反。C 方向完全颠倒。D 螺距增大后床速加快，扫描时间必然缩短；且螺距过大时 Z 轴插值权重变宽，层敏感度剖面增宽，纵向分辨率略有下降而非提高。E 螺距直接决定床进速度，与扫描时间密切相关。", "tr": "同一句\"提高螺距\"，在\"有效 mAs\"（西门子系列常用）与\"每圈 mAs\"（部分厂家沿用）两种设定方式下，对剂量与噪声的结论完全相反。审题时务必先确认控制台设定的是哪一种 mAs。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0117", "t": "多选题", "s": "关于迭代重建（IR）算法在 CT 降低剂量与保障图像质量中的作用，下列分析正确的有", "o": {"A": "与滤波反投影相比，迭代重建在同等剂量下可明显降低噪声，或在同等噪声水平下使剂量下降约 30%～50%", "B": "迭代重建对噪声的抑制并非在各空间频率上均等，会改变噪声功率谱形态，使图像出现\"蜡样、塑料感\"的特殊纹理", "C": "评价迭代重建图像时不能只看噪声标准差，还应结合低对比可探测度与任务传递函数等指标综合判断", "D": "迭代重建强度权重设置得越高，图像质量越好，临床应常规选用最高档", "E": "统计迭代重建能够彻底消除金属伪影与射线束硬化伪影，因此不再需要专门的伪影校正算法"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-006", "kp": "迭代重建与噪声-剂量权衡", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】A 正确：混合迭代与模型迭代重建通过在投影域和/或图像域反复迭代抑制统计涨落，同等图像噪声下允许显著降低管电流量，这是低剂量 CT 的技术基础。B 正确：IR 主要压制高频噪声，使 NPS 峰值向低频移动，图像质地变得平滑、缺乏颗粒感，即所谓\"蜡样/塑料感\"。C 正确：噪声标准差下降并不等于诊断信息增加，必须结合低对比可探测度（如 C-D 曲线、模型观察者指标）与任务传递函数评价，才能反映真实的诊断性能。【为什么错】D 错误：迭代权重过高会造成解剖边缘钝化、小低对比病灶（如小肝癌、腔隙灶）显示能力下降和纹理失真，临床应根据检查部位与诊断任务选择适中档位。E 错误：迭代重建可部分改善噪声相关伪影，但金属伪影与射线束硬化属确定性的数据不一致问题，仍需专门的金属伪影校正（MAR）、硬化校正或能量成像单能量图像来处理。", "tr": "\"噪声更低=图像更好\"是本考点最大的思维陷阱。迭代重建把噪声\"改造\"了而不仅是\"减少\"，评价时必须引入低对比可探测度指标，否则容易过度降剂量而漏诊小病灶。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-0118", "t": "案例分析题", "s": "一名 68 岁男性因持续头痛行头颅 CT 平扫。图像上颅后窝层面于双侧颞骨岩部之间出现横行的低密度条状暗带，并夹杂少许高密度细条纹，脑桥前部结构显示欠清；同一次检查的幕上各层面图像质量良好，未见类似表现。检查过程中患者安静配合、无体动，头部未佩戴任何金属物品，义齿已取下；设备当日水模质控与空气校正均合格。作为高年资技师，对该伪影的性质判断与优化处理，下列最恰当的是", "o": {"A": "属射线束硬化并叠加部分容积效应形成的颅底暗带伪影，可提高管电压、加大预过滤、采用薄层采集后重组、启用颅底硬化校正算法或调整扫描机架角度予以减轻", "B": "属探测器单元失效引起的环形伪影，应停机联系工程师更换探测器模块", "C": "属患者头部运动造成的运动伪影，应加强头部固定后重新扫描", "D": "属口腔金属义齿造成的金属条状伪影，应嘱患者取下义齿后重扫", "E": "属大螺距螺旋插值造成的风车状伪影，应显著减小螺距后重扫"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-007", "kp": "CT 常见伪影的识别与处理", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】A 正确。颅后窝两侧致密岩骨之间的射线路径衰减极大，低能光子被优先吸收使射线束\"变硬\"，重建算法按单能假设处理即产生条状低密度暗带（Hounsfield 暗带），常与厚层导致的部分容积效应叠加。处理措施包括提高管电压与加大预过滤使射线谱变硬更均匀、采用薄层采集后重组减少部分容积、启用颅底/后颅窝专用硬化校正重建、必要时倾斜机架改变射线路径。【为什么错】B 环形伪影的特征是以旋转中心为圆心的同心圆环或弧线，可出现在任何层面，与解剖位置无关，本例仅见于颅底且呈横行条带，不符。C 运动伪影常表现为条纹状、边缘重影或阶梯状错层，且多累及多个层面，本例患者配合良好、幕上层面正常，不支持。D 患者已取下义齿且伪影位于岩骨间而非牙列层面，金属伪影多呈自金属向外放射的明暗相间粗条纹。E 风车伪影出现在多层螺旋 CT 大螺距扫描时的高对比结构边缘，呈以旋转中心为轴的风车叶片状，多见于横断面重建的颅底或肺尖，其形态与本例横行暗带不同。", "tr": "颅底暗带与运动伪影都可表现为\"条纹\"，鉴别关键在于分布：射线束硬化伪影固定出现在两块致密骨之间（岩骨间、后颅窝），层面选择性强；运动伪影随患者体动出现，位置与形态无解剖规律。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0119", "t": "单选题", "s": "DSA 减影图像上出现血管边缘\"双边\"表现及全图弥漫的骨与软组织结构残影，其最常见原因及首选补救措施是", "o": {"A": "对比剂浓度过高造成饱和伪影，应稀释对比剂后重做造影", "B": "蒙片与造影片之间发生配准错位（运动性伪影），首选行像素移位再配准或另选一帧作为新蒙片重新减影", "C": "影像增强器固有的枕形失真所致，应更换为平板探测器", "D": "采集帧率过低，应提高到 30 帧/s 后重新采集", "E": "曝光量不足造成量子噪声增加，应提高 mAs 后重新采集"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-001", "kp": "DSA 运动性伪影与像素移位", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (2)成像方式和操作技术", "ex": "【为什么对】B 正确。时间减影的前提是蒙片与充盈片在解剖位置上严格配准。患者的自主或不自主运动（体位移动、吞咽、呼吸、心搏、胃肠蠕动）使两帧位置不一致，相减后残留组织影，血管边缘呈\"双边征\"。后处理首选像素移位（整体或分区局部配准）；若错位过大则从序列中另选与充盈片配准良好的帧作为新蒙片重新减影。预防措施包括良好固定、屏气训练、缩短采集时间、腹部造影前使用抑制胃肠蠕动药物。【为什么错】A 对比剂过浓引起的是血管腔内信号饱和、密度不能线性反映碘浓度，表现为管腔中心\"过冲\"，不产生全图结构残影。C 枕形失真是影像增强器的几何畸变，表现为整个序列图像周边弯曲变形，与减影配准无关，且平板探测器机型不会出现。D 帧率影响时间分辨率，与配准错位无因果关系，盲目提高帧率只增加辐射剂量。E 剂量不足的表现是噪声颗粒增大，不会出现规律的组织结构残影。", "tr": "\"先后处理、后重做\"是 DSA 运动伪影的处理次序。直接重新造影会额外增加对比剂用量与辐射剂量，只有在像素移位与重选蒙片都无法挽救时才考虑。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0120", "t": "共用题干题", "s": "结合上述情景，为改善 DSA 图像质量，下列措施与判断正确的有", "o": {"A": "术前充分做屏气训练，腹部造影可使用抑制胃肠蠕动的药物，以减少运动性伪影", "B": "合理选择焦点与放大方式、缩小照射野、加用适当的补偿滤过板，可减少散射线与饱和伪影", "C": "依据血流速度选择采集帧率，脑血管造影一般用 3～6 帧/s，冠状动脉造影需 15～30 帧/s", "D": "利用减影后对比灵敏度显著提高的优势，可将对比剂适度稀释，在保证显影的前提下减少碘负荷", "E": "对比剂注射流率与浓度越高，血管显示越清晰，图像质量越好"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-002", "kp": "DSA 图像质量的改善措施", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (5)改善措施", "ex": "【为什么对】A 正确：运动是 DSA 图像质量的首要威胁，术前沟通、训练与药物抑制蠕动是最经济有效的预防手段。B 正确：小焦点提高分辨率、缩小照射野与补偿滤过板减少散射并避免肺野、颈部等薄区因透过量过大导致探测器饱和形成\"过亮\"伪影。C 正确：帧率应与靶血管的血流速度匹配，脑血管 3～6 帧/s、冠脉 15～30 帧/s、四肢与下腔静脉可低至 1～3 帧/s。D 正确：减影去除了背景结构，对碘的对比灵敏度大幅提高，因而可用稀释后的对比剂完成诊断，降低对比剂肾病风险。【为什么错】E 错误：过高的浓度与流率会造成管腔内碘信号超出探测器线性响应范围形成饱和伪影，还增加血管内膜损伤、对比剂外渗与肾损伤风险，且湍流可致显影不均。DSA 追求的是\"够用即可\"的最低碘负荷。", "tr": "\"提高对比剂浓度改善图像\"是把常规血管造影的经验错误迁移到 DSA。DSA 的核心优势恰恰是可以用更低浓度、更小剂量获得高对比图像。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05095", "gs": ""}, {"id": "ZG-U05-0121", "t": "单选题", "s": "与影像增强器-电视系统（II-TV）相比，平板探测器（FPD）应用于 DSA 的优势不包括下列哪一项", "o": {"A": "不存在枕形失真与 S 形畸变，图像几何保真度高", "B": "动态范围宽、DQE 较高，在较低剂量下即可获得良好信噪比", "C": "无边缘亮度衰减，视野内亮度分布均匀", "D": "体积小、重量轻且无需磁屏蔽，便于机架大角度旋转与三维采集", "E": "极限空间分辨率随视野放大倍数增加而不断提高，可无限放大观察细节"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-003", "kp": "平板探测器与影像增强器的性能比较", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (1)设备结构", "ex": "【为什么对】E 是错误描述，故为本题答案。平板探测器的像素间距在制造时已固定，其极限空间分辨率由像素间距决定（约 1/(2×像素间距) lp/mm），缩小视野只是把同样的像素分布在更小的解剖范围上，并不能无限提高分辨力；\"放大即提高分辨率\"是影像增强器电子放大方式的特点，且以剂量升高为代价。【为什么错】A、B、C、D 均为 FPD 的确实优势：A 影像增强器因电子光学与地磁影响存在枕形失真和 S 形畸变，FPD 为平面矩阵采集，无此问题；B FPD 动态范围可达 10⁴ 以上，DQE 明显高于 II-TV 链；C II 存在边缘亮度衰减（vignetting）与边缘分辨率下降，FPD 视野内响应均匀；D FPD 无真空管与光学耦合链，结构紧凑、不受地磁影响，便于旋转采集与三维重建。", "tr": "FPD 的\"放大\"是显示放大或像素合并模式的切换，与 II 的\"电子放大\"机制不同。命题常用\"放大倍数越高分辨率越高\"这种源自影像增强器时代的旧经验设置干扰。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0122", "t": "案例分析题", "s": "一名 62 岁男性，因反复发作性右侧肢体无力（短暂性脑缺血发作）拟行全脑血管造影，以评估颈内动脉与颅内血管狭窄程度。导管室配备平板探测器 DSA。术前化验示血肌酐轻度升高，估算肾小球滤过率约 55 mL/(min·1.73 m²)，无碘对比剂过敏史，意识清楚、能配合指令。技师需要与术者共同确定颈内动脉造影的采集帧率、对比剂配置与注射参数，并做好减影质量保障。下列方案最合理的是", "o": {"A": "采集帧率取 3～6 帧/s；选用等渗或低渗非离子型对比剂并适度稀释（如 300 mgI/mL 稀释至约 50%～70%），注射流率约 4～5 mL/s、单次总量约 6～8 mL；采集时嘱患者屏气、勿吞咽勿转头，并做好水化", "B": "全部血管一律采用 30 帧/s 采集，以获得最佳时间分辨率", "C": "为使血管显影更浓，使用未稀释的 370 mgI/mL 对比剂，并把注射流率提高到 10 mL/s", "D": "采用 1 帧/s 的低帧率采集，以最大限度降低受检者辐射剂量", "E": "因患者存在肾功能减退，改用高渗离子型对比剂以减轻肾脏负担"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-004", "kp": "脑血管 DSA 的帧率与对比剂方案", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (3)造影方法和对比剂", "ex": "【为什么对】A 正确。脑循环动脉期到静脉期约 6～8 s，3～6 帧/s 足以完整记录动脉期、毛细血管期与静脉期，兼顾时间分辨率与剂量；DSA 因减影提高了碘对比灵敏度，稀释对比剂即可满足显影，对 eGFR 减退者尤为重要；颈内动脉常用流率 4～5 mL/s、总量 6～8 mL；嘱屏气、禁吞咽与转头可显著减少配准错位；围术期水化是预防对比剂相关急性肾损伤的基本措施。【为什么错】B 30 帧/s 适用于心脏与冠状动脉这类高速运动结构，用于脑血管只会成倍增加辐射剂量而无诊断增益。C 未稀释高浓度对比剂加 10 mL/s 的流率远超颈内动脉需要，易致饱和伪影、血管痉挛甚至内膜损伤，且明显加重肾脏碘负荷。D 1 帧/s 会遗漏动脉早期与侧支循环的动态信息，无法判断狭窄远端血流与代偿情况。E 认识错误，高渗离子型对比剂的肾毒性与不良反应发生率明显高于非离子型等渗/低渗对比剂，肾功能减退者应选后者。", "tr": "帧率不是越高越好，应\"按血流速度定帧率\"：脑血管 3～6 帧/s、冠脉 15～30 帧/s、四肢与静脉 1～3 帧/s。另需牢记减影技术允许使用稀释对比剂，这是 DSA 相对常规造影的重要优势。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0123", "t": "共用题干题", "s": "结合上述情景，在分析某台 DSA 设备近期图像质量下降的原因时，下列对影响因素的归类与判断正确的有", "o": {"A": "受检者体厚增加使散射线增多、对比度下降，属患者本身因素，可通过缩小照射野、加用补偿滤过与优化体位改善", "B": "心搏与呼吸运动引起的减影配准误差属患者因素，可用心电门控采集、缩短采集时间与屏气训练减轻", "C": "X 线管焦点尺寸、探测器 DQE 与模数转换位深属设备结构因素，直接决定系统的空间分辨率与密度分辨能力", "D": "采集帧率、注射延迟时间与曝光参数的设定属成像方式和操作技术因素", "E": "对比剂的种类与碘浓度对 DSA 图像质量影响甚微，分析原因时可不予考虑"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-005", "kp": "DSA 图像质量影响因素的系统分类", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (4)患者本身因素", "ex": "【为什么对】A 正确：体厚与体质属患者本身因素，散射线份额随体厚呈指数增长，缩野、滤过与体位优化是可行对策。B 正确：生理性运动同样归入患者因素，心电门控、缩短曝光时间与呼吸配合是标准应对手段。C 正确：焦点决定几何模糊，DQE 决定量子利用效率，A/D 位深决定灰阶量化精度与密度分辨能力，三者均属设备结构范畴。D 正确：帧率、注射延迟、曝光参数与减影方式的选择属操作技术层面，是技师可直接控制的变量。【为什么错】E 错误：对比剂的类型、碘浓度、注射流率与总量直接决定血管腔内的碘信号强度与对比度，是\"造影方法和对比剂\"这一独立影响因素类别的核心内容，不能忽略。", "tr": "考纲把 DSA 图像质量影响因素明确分为设备结构、成像方式与操作技术、造影方法与对比剂、患者本身因素四大类，命题常通过\"张冠李戴\"的归类或直接否定某一类来设陷，记忆时按四类框架归位。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ05095", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-0124", "t": "单选题", "s": "MR 成像中信噪比、对比噪声比、空间分辨率与扫描时间四者相互制约，下列对这一制约关系的分析正确的是", "o": {"A": "其他条件不变时把层厚由 5 mm 减到 2.5 mm，SNR 约降为原来的一半；若将采集次数由 1 增到 4 可将 SNR 补回，但扫描时间也随之延长为 4 倍", "B": "提高空间分辨率的同时能够保持 SNR 不变，且不付出任何扫描时间代价", "C": "SNR 与体素体积无关，仅由主磁场强度决定", "D": "增加采集次数（NEX）时，SNR 与 NEX 成正比线性增长", "E": "缩短扫描时间不会影响 SNR，只会改变运动伪影的程度"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-001", "kp": "SNR、分辨率与扫描时间的相互制约", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】A 正确。SNR 与体素体积成正比，同时与 √(NEX×相位编码步数/接收带宽) 成正比。层厚由 5 mm 减到 2.5 mm 使体素体积减半，SNR 约降为 1/2；NEX 由 1 增到 4 使 SNR 提高 √4=2 倍，恰好抵消。而二维序列扫描时间 T=TR×相位编码步数×NEX/加速因子，NEX 增至 4 倍则时间增至 4 倍。这正是 MR\"四角关系\"中\"改善其一必牺牲其二\"的典型体现。【为什么错】B 违背 MR 成像的基本制约规律，提高分辨率意味着体素变小、SNR 下降，欲维持 SNR 就必须增加平均次数或延长采集，时间代价不可避免。C SNR 与体素体积成正比，是最关键的决定因素之一；场强只是影响因素之一。D SNR 与 NEX 的平方根成正比，NEX 增至 4 倍 SNR 只提高 2 倍，收益递减而时间代价线性增长。E 缩短扫描时间通常靠减少 NEX、减少相位编码步数或提高并行加速因子实现，这些手段都会使 SNR 下降。", "tr": "\"√关系\"是本考点的关键：SNR∝√NEX、∝√相位编码步数、∝1/√带宽，而与体素体积成一次方正比。把 √ 关系误记为线性关系（如选 D）是最常见的失分点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0125", "t": "共用题干题", "s": "结合上述情景，一名 34 岁女性运动员因膝关节疼痛行 MRI 检查，设备为 3.0T，使用专用膝关节相控阵线圈。矢状面质子密度加权 FSE 序列的初始参数为：FOV 160 mm×160 mm，矩阵 320×256，层厚 3 mm，NEX 2，接收带宽 200 Hz/像素，扫描时间 3 min 20 s。阅片医师认为关节软骨分层结构与半月板后角细节仍显示不足，要求在扫描时间不明显延长的前提下改善图像。技师逐一评估可调参数对信噪比的影响，下列判断中正确的是", "o": {"A": "把 FOV 由 160 mm 缩小到 80 mm 而矩阵保持不变，体素面积降为原来的 1/4，SNR 约降为原来的 1/4", "B": "把 NEX 由 2 增加到 4，SNR 约提高到原来的 2 倍", "C": "把接收带宽由 200 Hz/像素降到 100 Hz/像素，SNR 约降低到原来的 1/1.4", "D": "把层厚由 3 mm 增加到 6 mm，SNR 约降为原来的一半", "E": "把矩阵提高到 512×512 而 FOV 不变，体素虽减小但 SNR 不受影响"}, "d": "难", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-002", "kp": "FOV、NEX、带宽、层厚对 SNR 的定量影响", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】A 正确。FOV 缩小一半而矩阵不变时，像素边长（面内分辨率）也缩小一半，体素面积变为原来的 1/4，体素体积随之降为 1/4；由于相位编码步数与 NEX 未变，SNR 约降为原来的 1/4。这说明单纯缩小 FOV 提高分辨率的代价极大，实际工作中往往需要同时增加 NEX 或改用更高信噪比的线圈补偿。【为什么错】B 错误：NEX 由 2 增到 4 仅是 2 倍，SNR∝√NEX，提高倍数为 √2≈1.41，而非 2 倍。C 错误：SNR∝1/√带宽，带宽减半使 SNR 提高约 1.41 倍（而非降低），代价是化学位移伪影加重、回波间隔延长、最短 TE 受限。D 错误：层厚加倍使体素体积加倍，SNR 约提高到 2 倍（而非降为一半），代价是部分容积效应加重、软骨薄层结构模糊。E 错误：FOV 不变而矩阵增大使体素变小，SNR 必然下降；相位编码方向矩阵由 256 增到 512 时，体素面积减半带来 1/2、相位编码步数加倍带来 √2，综合约为原来的 0.71 倍，且扫描时间加倍。", "tr": "本题四个干扰项都把变化\"方向\"或\"倍数\"做了颠倒：带宽与层厚记反方向、NEX 记成线性关系是最高频错误。牢记 SNR∝体素体积×√(NEX×N_PE/带宽)，代入即可全部判定。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05098", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-0126", "t": "共用题干题", "s": "结合上述情景，关于并行采集技术（SENSE/GRAPPA/ASSET）与压缩感知（CS）加速对 MR 图像质量的影响，下列描述正确的是", "o": {"A": "并行采集加速因子 R 增大时，SNR 大致按 1/(g×√R) 下降，其中几何因子 g≥1，且在视野中心区域往往更大", "B": "并行采集通过减少相位编码步数缩短时间，且不损失任何信噪比", "C": "SENSE 类算法展开不当时的典型表现是沿频率编码方向出现贯穿图像的拉链状条纹", "D": "压缩感知依赖图像的稀疏性与规则等间隔欠采样，重建过程为简单的线性反变换", "E": "压缩感知的加速倍数越高，图像越锐利、细节越丰富"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-003", "kp": "并行采集 g 因子与压缩感知加速", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】A 正确。并行采集减少相位编码步数使采集数据量降为 1/R，SNR 首先按 √R 下降；此外线圈单元敏感度分布的空间可分性不理想会引入几何因子 g（g≥1），进一步降低 SNR，故 SNR_加速≈SNR_全采样/(g×√R)。g 因子在线圈灵敏度差异最小的视野中心区域通常最大，因此高加速时中心区噪声放大最明显。【为什么错】B 错误：并行采集必然损失 SNR，这是其固有代价。C 错误：SENSE 展开不当的典型表现是视野中央出现残余卷褶（中心带状重叠影）；拉链伪影是射频屏蔽不良或外来射频干扰所致，两者机制不同。D 错误：压缩感知要求非相干的伪随机欠采样使混叠呈噪声样弥散，并采用稀疏变换域下的非线性迭代重建；规则等间隔欠采样只会产生相干的规律性卷褶，不适用于 CS。E 错误：CS 加速过高会因正则化过强导致图像过度平滑、纹理与低对比细节丢失，甚至产生虚假结构，需在加速倍数与细节保真之间折中。", "tr": "CS 图像\"看上去很干净\"容易被误认为质量高。CS 与迭代重建 CT 类似，噪声下降不等于信息增加，评价时应关注小病灶的可探测性与是否出现假象。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05103", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-0127", "t": "单选题", "s": "MR 图像上出现视野以外的解剖结构被折叠到图像对侧的现象，关于该伪影的成因与对策，下列描述正确的是", "o": {"A": "此为卷褶（混叠）伪影，因相位编码方向 FOV 小于受检部位、相位超出 ±180° 后发生周期性重复所致；可用相位过采样、增大 FOV、加饱和带或交换相位与频率编码方向解决", "B": "此为化学位移伪影，只需增大接收带宽即可完全消除", "C": "此伪影主要出现在频率编码方向，因频率编码方向未设置抗混叠滤波器", "D": "增加采集次数（NEX）是消除该伪影最有效的方法", "E": "卷褶伪影只发生于二维序列，三维采集的层面编码方向不会出现"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-004", "kp": "卷褶伪影的识别与对策", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】A 正确。相位编码依靠 -180°～+180° 的相位差区分空间位置，FOV 之外的组织其相位超出该范围后与 FOV 内某位置的相位相同，被错误编码到对侧，形成卷褶。对策包括：相位过采样（无相位卷褶/折叠抑制，代价是扫描时间或 NEX 增加）、增大 FOV、在 FOV 外加预饱和带、交换相位与频率编码方向使卷褶落在无关方向、选择敏感范围受限的表面线圈。【为什么错】B 化学位移伪影表现为水脂界面沿频率编码方向的位移与黑白勾边，与结构折叠是两回事。C 频率编码方向通常配有低通抗混叠滤波并做频率方向过采样，一般不出现卷褶；卷褶主要沿相位编码方向。D 增加 NEX 只提高 SNR，对卷褶无作用。E 三维采集在层面（第二相位编码）方向同样会发生卷褶，表现为最外层层面上叠加了容积外的解剖结构，需要层面方向过采样加以抑制。", "tr": "\"相位编码方向\"是卷褶伪影的定位口诀。另需注意：三维序列存在两个相位编码方向，层面方向卷褶常被误判为病变，是脊柱与颅脑三维扫描的实际难点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-0128", "t": "案例分析题", "s": "一名 58 岁男性，腰椎后路椎弓根螺钉内固定术后 2 年，因下腰痛伴右下肢麻木行 1.5T 腰椎 MRI。矢状面 T2WI（TSE）上内固定区域出现大片信号丢失伴局部信号异常堆积，邻近椎体与椎管轮廓明显扭曲变形；同一检查的矢状面 T1WI 上，脊髓与脑脊液交界附近出现数条平行于脊髓走行、明暗相间且等间距排列的细线状条纹，类似脊髓空洞样表现。患者检查全程配合良好，无体动。技师需在不更换设备的条件下优化图像。下列处理措施组合最合理的是", "o": {"A": "针对金属磁敏感伪影：缩短 TE、增大接收带宽、减小体素、增加回波链长度，以 TSE 替代 GRE/EPI 类序列，脂肪抑制改用 STIR；针对截断（吉布斯）伪影：增大相位编码方向矩阵或适当减小 FOV，必要时配合适度滤波", "B": "两种表现均属运动伪影，加用呼吸门控并使用腹部加压带即可解决", "C": "金属伪影应通过降低接收带宽、延长 TE 来减轻；条纹伪影应通过增加采集次数解决", "D": "条纹表现属卷褶伪影，交换相位编码方向即可；金属伪影则应改用频率选择性脂肪抑制以提高抑脂均匀性", "E": "两者均由射频屏蔽不良引起，应检查检查室屏蔽门与滤波板后重新扫描"}, "d": "难", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-005", "kp": "磁敏感伪影与截断伪影的鉴别与对策", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】A 正确。金属内固定引起局部磁场不均匀，导致自旋失相位与频率编码错位，表现为信号丢失、信号堆积与几何扭曲；有效对策是缩短 TE 减少失相位时间、增大带宽压缩每像素频率范围以减小空间错位、减小体素降低体素内失相位、增加回波链使回波间隔缩短并借助 180° 复聚脉冲补偿静态场不均匀，因此应优先用 TSE 而非 GRE/EPI；由于频率选择性脂肪抑制在磁场不均匀区会失效甚至造成水脂互换，应改用对场不均匀不敏感的 STIR。脊髓/脑脊液这类高对比界面处出现的等间距平行条纹是截断（吉布斯/环状）伪影，源于 k 空间高频数据被有限矩阵截断，对策是增大相位编码方向矩阵（提高该方向分辨率）、减小 FOV 或使用 k 空间滤波。【为什么错】B 患者配合良好且伪影形态具有明确的空间规律，不符合运动伪影表现，呼吸门控对腰椎金属伪影无效。C 方向完全相反：降低带宽与延长 TE 都会加重磁敏感伪影；增加 NEX 只提高 SNR，对截断伪影无改善。D 截断伪影与卷褶伪影不同，前者是界面处的等间距条纹、不涉及视野外结构折叠；且在金属区使用频率选择性脂肪抑制正是应当避免的做法。E 射频干扰的典型表现是拉链状条纹或图像整体噪声带，与本例两种伪影的形态和分布均不吻合。", "tr": "截断伪影与脊髓空洞的鉴别是临床实际难题：截断伪影表现为多条等间距、明暗交替、随矩阵改变而变化的条纹，且在增大相位编码矩阵后减轻或消失；真实空洞则形态固定、在各序列各方位上可重复显示。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1001", "t": "共用题干题", "s": "结合上述情景，关于影像质量保证（QA）的概念，下列叙述最准确的是", "o": {"A": "仅指对X线辐射剂量进行监测和控制的活动", "B": "有计划、有系统地采取必要措施，保证影像质量满意并能持续改进的整体活动", "C": "使用标准体模对设备性能进行的验收检测", "D": "对图像质量进行的评分与评价过程", "E": "指影像科内部制定规章制度的管理活动"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-101", "kp": "质量保证QA的定义与内涵", "ch": "五、影像质量管理 → 1.概述 → (1)基本概念", "ex": "【为什么对】质量保证（QA）是有计划、有组织的系统活动，目的在于确保影像质量满足临床诊断要求并不断持续改进，涵盖人员、设备、制度、检测等全部环节，故B最准确。\n【为什么错】A：只涉及剂量监测，是QC的一部分而非QA全部。C：验收检测只是QA的组成部分之一。D：图像评价只是质量管理的环节之一。E：制度管理是QA内容的一部分，不能概括QA整体。", "tr": "QA（整体、系统、持续改进）与QC（具体检测、校正）是从属关系，勿将QC、验收检测误当QA的全部。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05107", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1002", "t": "单选题", "s": "影像质量控制（QC）是质量保证（QA）的重要组成部分，其核心工作是", "o": {"A": "购置并维护先进的成像设备", "B": "对成像设备及成像过程的关键技术指标进行监测、检测、校正并使其处于最佳状态", "C": "制定影像科的行政管理规范", "D": "对医师报告质量进行审核", "E": "统计受检者群体辐射剂量"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-102", "kp": "质量控制QC的职责", "ch": "五、影像质量管理 → 1.概述 → (1)基本概念", "ex": "【为什么对】质量控制（QC）通过定期检测设备与成像过程的关键指标（如CT值、噪声、分辨率、亮度密度等）并及时校正，使成像系统始终处于最佳工作状态，是QA的核心技术环节。\n【为什么错】A：设备购置属于规划管理而非QC。C：行政管理规范不属于技术QC范畴。D：报告质量审核属于诊断质量评估。E：群体剂量统计属于防护监测，非QC核心工作。", "tr": "QA是整体概念、QC是其技术执行环节；设备购置、报告审核等均不属于QC核心工作。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1003", "t": "共用题干题", "s": "结合上述情景，下列影像质量评价方法中，属于主观评价法的是", "o": {"A": "调制传递函数（MTF）测量", "B": "量子探测效率（DQE）测量", "C": "视觉观察评分法（目测法）", "D": "噪声功率谱（NPS）测量", "E": "像素值线性检测"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-103", "kp": "主观评价法及其内容", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】主观评价法以观察者的视觉判断为依据评价图像质量，主要包括目测法（视觉观察评分）和ROC曲线分析法。\n【为什么错】A：MTF用物理量客观测定，属客观评价法而非主观评价。B：DQE反映量子利用效率，是客观物理指标。D：NPS是噪声功率谱的客观测量，不依赖观察者判断。E：像素值线性检测是物理定量检测，属客观评价法。", "tr": "ROC曲线属主观（心理学）评价而非客观评价；MTF/DQE/NPS均属客观物理评价。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05101", "gs": ""}, {"id": "ZG-U05-1004", "t": "单选题", "s": "DR系统日常质量控制中，曝光指数（exposure index）主要反映的是", "o": {"A": "图像的空间分辨率", "B": "探测器接收到的X线曝光量（剂量水平）", "C": "图像的密度分辨率", "D": "重建矩阵的大小", "E": "监视器的亮度水平"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-101", "kp": "DR曝光指数含义", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】曝光指数是对探测器接收X线剂量的量化指示，反映实际曝光量是否合适，用于判断摄影条件是否恰当并指导剂量控制。\n【为什么错】A：空间分辨率由探测器像素尺寸与系统MTF决定。C：密度分辨率与剂量、噪声有关但不是曝光指数直接反映对象。D：重建矩阵是图像处理参数。E：监视器亮度属于显示设备调节，与曝光指数无关。", "tr": "曝光指数反映的是探测器受照剂量而非空间分辨力；不同厂家指示量（EI/S值/EXI）含义略有差异。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1005", "t": "共用题干题", "s": "结合上述情景，按照ACR乳腺X线摄影质量保证程序，用标准体模进行图像质量评估时，若体模内模拟纤维、微钙化团块和肿块结构的可见数目低于规定阈值，正确的处理是", "o": {"A": "记录结果后继续正常投照", "B": "适当降低压迫压力后重新摄片", "C": "判定质量控制不合格，排除设备原因（校正/维修）后重新检测", "D": "仅通过提高曝光量来改善", "E": "更换照片冲洗液后重测"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-101", "kp": "乳腺体模质量评估与处理", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】ACR标准体模（如RMI 156）内含模拟纤维、微钙化团块和肿块，其可见数目须达到规定阈值，不达标表明系统图像质量下降，应判定QC不合格并查找原因（设备校准、维修等）后复测。\n【为什么错】A：记录后继续使用会延误设备异常发现。B：压迫压力不改变体模内在结构的可见性阈值判定。D：单纯提高曝光量不能替代设备检修，且增加剂量。E：现代数字乳腺系统无冲洗液环节。", "tr": "乳腺质控核心是“体模可见结构阈值不达标即QC不合格”；压迫压力、曝光量调节不能掩盖设备性能问题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05102", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1006", "t": "单选题", "s": "CT图像质量控制中，用标准水模检测CT值准确性时，水的CT值标称应为", "o": {"A": "-1000 HU", "B": "0 HU", "C": "40 HU", "D": "100 HU", "E": "200 HU"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-101", "kp": "CT值准确性与水模", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】CT值以水为参照定义为0 HU（空气-1000 HU），用水模检测CT值应在0 HU附近，允许偏差一般为±3~4 HU（各厂家标准略有差异）。\n【为什么错】A：-1000 HU为空气的CT值。C：40 HU明显偏离水的标称值，属质控异常或误记。D：100 HU明显高于水的标称CT值。E：200 HU显著偏离，若测得此值提示系统校准或探测器异常。", "tr": "牢记标尺：水0 HU、空气-1000 HU、骨+1000 HU左右；CT值漂移可提示探测器或校准问题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1007", "t": "共用题干题", "s": "结合上述情景，关于影像质量主客观评价方法的比较，下列叙述正确的是", "o": {"A": "主观评价受观察者个体影响，因此没有临床应用价值", "B": "调制传递函数（MTF）属于主观评价法", "C": "客观评价以物理量（如MTF、DQE、噪声）定量评价图像质量，可重复性好", "D": "ROC曲线分析属于客观评价法", "E": "综合评价法仅指对物理指标的综合，不涉及临床诊断"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-104", "kp": "主客观评价方法特点比较", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】客观评价法用可测量的物理量（MTF、DQE、噪声、像素值等）定量反映系统性能，结果不受观察者影响、可重复性好，用于设备验收与日常质控。\n【为什么错】A：主观评价（目测、ROC）直接反映临床观察效能，是评价图像最终可诊断性的重要手段，并非无价值。B：MTF是客观物理评价指标。D：ROC通过观察者对信号检出率的判断完成，属主观（心理学）评价法。E：综合评价法将物理指标与临床诊断价值（观察者）结合，不仅限于物理指标。", "tr": "MTF/DQE/NPS为客观评价，ROC为典型主观评价；综合评价=物理+临床观察相结合。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05101", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1008", "t": "单选题", "s": "DR探测器在低剂量区输出信号与入射X线剂量呈现非线性时，对图像质量最主要的影响是", "o": {"A": "空间分辨力下降", "B": "灰阶层次（对比度）失真，低对比度病变显示能力下降", "C": "产生运动伪影", "D": "有效视野缩小", "E": "图像放大率改变"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-102", "kp": "DR探测器剂量响应线性", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】数字X线成像依赖于探测器输出信号与入射剂量的线性响应，低剂量区非线性会使图像灰度值与实际组织衰减不成比例，导致对比度失真，掩盖或误显低对比度病灶，直接影响诊断。\n【为什么错】A：空间分辨力由探测器像素尺寸及系统MTF决定，与剂量响应线性无关。C：运动伪影来源于被照体或设备运动。D：视野由探测器尺寸与几何决定。E：放大率取决于焦点-物体-探测器几何位置。", "tr": "探测器线性是数字成像量化基础；非线性主要损伤“对比度/灰阶”而非空间分辨率。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1009", "t": "共用题干题", "s": "结合上述情景，关于乳腺X线摄影的平均腺体剂量（AGD），下列叙述正确的是", "o": {"A": "与乳腺压迫厚度无关", "B": "是反映乳腺摄影受检者辐射剂量的指标，受管电压、靶/滤过组合、压迫厚度及曝光量等综合影响", "C": "平均腺体剂量越大，图像质量一定越好", "D": "与数字乳腺摄影（FFDM）或模拟摄影方式无关", "E": "平均腺体剂量不受质量保证要求限制"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-102", "kp": "乳腺平均腺体剂量", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】平均腺体剂量（AGD）用于评估乳腺受照剂量，其大小由管电压、阳极靶/滤过组合、压迫厚度、曝光量及摄影方式等多种因素共同决定，是乳腺质控与剂量监测的核心指标。\n【为什么错】A：压迫厚度增加时为使探测器获得足够光子需增大曝光量，AGD随之升高，二者密切相关。C：AGD增大并不等同于图像质量提高，还需兼顾噪声与分辨力，且应遵循合理尽可能低（ALARA）原则。D：FFDM与模拟乳腺摄影的剂量水平不同。E：ACR等质控标准对AGD设有评价限值。", "tr": "AGD=受照剂量指标，需“剂量与图像质量”双达标，不能以牺牲剂量追求图像。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05102", "gs": ""}, {"id": "ZG-U05-1010", "t": "共用题干题", "s": "结合上述情景，关于CT空间分辨率与密度分辨率的关系，下列叙述正确的是", "o": {"A": "两者相互独立、互不影响", "B": "提高空间分辨率必然提高密度分辨率", "C": "同一扫描条件下二者往往相互制约，减小像素（增大矩阵）可提高空间分辨率但噪声增加、密度分辨率下降", "D": "增大层厚可使空间分辨率和密度分辨率同时提高", "E": "螺距大小对两者均无影响"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-102", "kp": "空间分辨率与密度分辨率关系", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】空间分辨率取决于像素大小与焦点、探测器孔径等，密度分辨率主要受噪声（光子数）影响。像素减小时单个像素收到的光子减少、噪声增大，密度分辨率下降，故两者相互制约。\n【为什么错】A：二者受同一噪声源和采样条件影响，存在此消彼长的制约关系。B：提高空间分辨率通常以降低密度分辨率为代价。D：增大层厚使部分容积效应增加，空间分辨率沿层厚方向下降，不能同时提高两者。E：螺距增大影响噪声与有效层厚，间接影响密度分辨率。", "tr": "“大矩阵提空间分辨率、损密度分辨率”；层厚越大密度（低对比）噪声改善但部分容积效应越重。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05105", "gs": ""}, {"id": "ZG-U05-1011", "t": "共用题干题", "s": "结合上述情景，DSA图像上出现血管边缘“双边”显示及全图骨骼、软组织影未被消除的配准不良伪影，其最直接的原因是", "o": {"A": "对比剂浓度过高", "B": "减影所对应的蒙片像与充盈像之间存在位移（患者运动、呼吸、吞咽或胃肠蠕动）", "C": "X线管焦点尺寸过大", "D": "探测器信号漂移导致的系统性增益不均", "E": "曝光量过低导致量子噪声过大"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-101", "kp": "DSA配准不良伪影成因", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (2)成像方式和操作技术", "ex": "【为什么对】DSA减影要求蒙片与对比剂充盈像的解剖位置完全一致，两次采集间患者发生移动（呼吸、吞咽、胃肠蠕动等）会使骨与软组织不能完全相减，产生血管“双边”和残留的解剖结构伪影，即配准不良伪影。\n【为什么错】A：对比剂浓度过高可致血管密度过度饱和，但不引起双边残留。C：焦点大小影响空间分辨率，与减影伪影无关。D：信号漂移表现为增益不均或层次失真，非解剖残留。E：量子噪声为颗粒状噪声，不产生成形的双边结构。", "tr": "DSA核心伪影=运动/配准不良；处理靠屏气、胃肠抑制、再蒙片、像素移位及脉冲采集。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05097", "gs": ""}, {"id": "ZG-U05-1012", "t": "单选题", "s": "MR成像中信噪比（SNR）随下列哪项因素的变化关系是“体素越大，SNR越高”？", "o": {"A": "窗宽与窗位", "B": "体素体积（像素面积×层厚）", "C": "重建矩阵大小与层厚无关", "D": "监视器分辨率", "E": "激光打印机密度"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-101", "kp": "SNR与体素的关系", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (1)概述", "ex": "【为什么对】SNR与体素体积成正比，体素越大（像素面积大或层厚大）所包含的质子越多，接收到的信号越强，SNR越高。\n【为什么错】A：窗宽窗位仅影响图像的显示灰阶，不改变原始信号。C：矩阵增大使像素变小，在层厚不变时体素变小，SNR下降，并非无关。D：监视器分辨率属于显示环节，不影响原始SNR。E：激光打印机密度属于输出设备，与MR信号采集无关。", "tr": "SNR∝体素体积；提高空间分辨率（减小体素）必然以SNR下降为代价，这是MR最基本的权衡。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1013", "t": "共用题干题", "s": "结合上述情景，MR图像的空间分辨率主要取决于", "o": {"A": "窗宽和窗位", "B": "视野（FOV）、矩阵和层厚", "C": "重复时间TR", "D": "回波时间TE", "E": "反转时间TI"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-102", "kp": "MR空间分辨率的决定因素", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (1)概述", "ex": "【为什么对】MR空间分辨率由像素大小决定，像素=FOV/矩阵，故空间分辨率取决于FOV、矩阵及层厚（层面方向的层厚影响体素纵向范围与部分容积效应）。\n【为什么错】A：窗宽窗位是显示参数，不改变采集分辨率。C：TR主要决定T1加权与扫描时间，不决定空间分辨率。D：TE决定T2加权程度及信噪比，不影响几何分辨率。E：TI是反转恢复序列的反转时间，主要影响对比度加权而非空间分辨率。", "tr": "空间分辨率看“FOV/矩阵/层厚”；TR/TE/TI决定对比度，勿混。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05100", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1014", "t": "共用题干题", "s": "结合上述情景，CT日常质量控制中，用于检测图像噪声水平与CT值均匀性的标准模体是", "o": {"A": "层厚模体", "B": "分辨力（线对）模体", "C": "水模", "D": "骨密度体模", "E": "乳腺加压体模"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-103", "kp": "CT水模的检测用途", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】水模（均匀水囊/水圆柱模体）用于检测CT值准确性、均匀性（中心与边缘CT值一致性）及噪声水平（均匀物质中像素值的标准差），是CT日常质控的基础模体。\n【为什么错】A：层厚模体用于检测实际扫描层厚。B：线对模体用于检测空间分辨率。D：骨密度体模用于定量CT骨密度校准。E：乳腺体模用于乳腺摄影质控，与CT无关。", "tr": "水模测“CT值、均匀性、噪声”；线对模体测“空间分辨率”；层厚模体测“层厚”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05093", "gs": ""}, {"id": "ZG-U05-1015", "t": "共用题干题", "s": "结合上述情景，使用CR系统投照后，图像上出现前次检查的残留影像（影像板擦除不全），最合理的处理是", "o": {"A": "加大曝光量后重新投照", "B": "对影像板重新进行强光擦除后再读取", "C": "在图像工作站调节窗宽窗位", "D": "报废该影像板并更换新板", "E": "调整CR扫描仪的扫描间距"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CRQC-101", "kp": "CR影像板擦除与残留伪影", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】CR的影像板（IP）读取后可擦除并重复使用，若上一幅潜影未擦除完全，会以残留影像形式叠加于新图像上。处理方法是重新用强光（均匀高亮度光源）充分擦除后再读取，必要时更换IP。\n【为什么错】A：加大曝光量不能消除残留潜影，反而增加剂量并使残留更明显。C：窗宽窗位只能改变显示，无法去除真实残留信号。D：仅个别IP残留一般经擦除即可解决，不必立即报废。E：扫描间距影响读出分辨率，与擦除残留无关。", "tr": "CR残留影像源于IP擦除不净，“重新强光擦除”是直接对策；IP寿命与擦除质量相关。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05092", "gs": ""}, {"id": "ZG-U05-1016", "t": "共用题干题", "s": "结合上述情景，DR系统每日开机后进行空气校准（平坦场校正）的主要目的是", "o": {"A": "消除探测器各像素增益不一致（像素响应差异）导致的图像不均匀伪影", "B": "增大图像的灰阶范围", "C": "提高系统的空间分辨率", "D": "减少检查所需的X线剂量", "E": "校准监视器的显示亮度"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-103", "kp": "DR平坦场校正目的", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】DR平板探测器各像素的增益与暗电流存在差异，且受温度等影响随时间漂移，空气校准（平坦场校正）采集均匀曝光数据以计算各像素校正系数，消除增益不一致产生的条纹、斑点等不均匀伪影。\n【为什么错】B：灰阶范围由ADC位深与图像处理决定。C：空间分辨率由像素尺寸与几何决定，校准不改变。D：校正不降低实际所需曝光量。E：监视器亮度校准属于显示设备的质控内容，与探测器空气校准无关。", "tr": "空气校准=探测器增益均匀性校正；勿与监视器校准、剂量优化混为一谈。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05094", "gs": ""}, {"id": "ZG-U05-1017", "t": "单选题", "s": "在保证诊断所需图像质量的前提下，降低CT检查辐射剂量最常用且有效的措施是", "o": {"A": "减小重建矩阵", "B": "降低管电流（mAs）并配合迭代重建算法", "C": "将所有扫描层厚增大至10 mm", "D": "缩小扫描视野", "E": "提高管电压"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-104", "kp": "CT低剂量技术与质量控制", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】剂量与mAs近似成正比，降低mAs可直接减少剂量，但会增加噪声；迭代重建（IR）在低噪声条件下重建图像，可补偿低mAs带来的噪声增加，是当前保证图像质量前提下降低剂量的核心手段。\n【为什么错】A：矩阵主要影响空间分辨率，对剂量影响甚微。C：增大层厚至10 mm可降剂量但明显损害分辨率与部分容积效应，不能满足多数诊断要求。D：缩小FOV不改变剂量（剂量由mAs与层厚等决定）。E：提高管电压通常增加剂量且改变对比度，不是降剂量措施。", "tr": "降剂量靠“降mAs+迭代重建”联动；“降mAs不重建”会导致噪声明显增大。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1018", "t": "共用题干题", "s": "结合上述情景，为减少DSA检查中患者运动引起的配准不良伪影，最有效的技术措施是", "o": {"A": "提高对比剂浓度和用量", "B": "嘱患者屏气、抑制吞咽，并采用曝光时间短的脉冲采集或再蒙片、像素移位等技术", "C": "增大X线管焦点尺寸", "D": "将帧率提高至30帧/秒", "E": "增大像素尺寸"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-102", "kp": "DSA运动伪影的改善措施", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (5)改善措施", "ex": "【为什么对】运动伪影源于蒙片与充盈像间位移，改善的根本在于减少运动（嘱患者屏气、抑制吞咽和胃肠蠕动）并缩短采集时间（脉冲采集），图像后处理方面可采用再蒙片、像素移位（pixel shifting）等配准技术加以纠正。\n【为什么错】A：对比剂浓度影响血管显影密度，不解决位移问题。C：增大焦点反而降低空间分辨率。D：提高帧率虽缩短单帧曝光时间但延长整体采集窗，对减少运动伪影帮助有限。E：增大像素尺寸降低空间分辨率，不能纠正位移。", "tr": "DSA运动伪影“防+纠”：屏气抑制为主，再蒙片/像素移位为纠；加大剂量与帧率不是关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05096", "gs": ""}, {"id": "ZG-U05-1019", "t": "单选题", "s": "保持视野不变，仅将MR采集矩阵由256×256增大为512×512时，图像信噪比（SNR）的变化是", "o": {"A": "保持不变", "B": "提高到原来的约2倍", "C": "降低到原来的约1/4", "D": "与矩阵大小无关", "E": "降低到原来的约一半"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-103", "kp": "矩阵增大对SNR的影响", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】FOV不变、矩阵从256增至512，像素边长减半、像素面积（体素体积）降为原来的1/4，而SNR与体素体积成正比，故SNR约降为原来的1/4，若需保持SNR必须延长扫描时间（增加NEX）或接受噪声增大。\n【为什么错】A：体素变小、信号减少，SNR必然改变。B：增大矩阵使体素变小，SNR应下降而非提高。D：SNR与体素大小密切相关。E：体素缩小4倍对应SNR降至约1/4而非1/2。", "tr": "矩阵加倍→像素面积变1/4→SNR约变1/4；牢记“SNR∝体素体积”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1020", "t": "共用题干题", "s": "结合上述情景，关于MR成像参数间的相互影响，下列叙述正确的是", "o": {"A": "增大TR可缩短扫描时间", "B": "保持矩阵不变而减小FOV可提高空间分辨率，但SNR下降且相位方向更易出现卷褶伪影", "C": "增大层厚会降低SNR", "D": "减小矩阵可提高空间分辨率", "E": "增大NEX会缩短扫描时间"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-104", "kp": "MR参数相互影响综合判断", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】FOV减小时像素变小、空间分辨率提高，但体素缩小使SNR下降；同时FOV内相位编码覆盖范围不足，视野外组织折叠入图内，故相位方向更易出现卷褶伪影。\n【为什么错】A：扫描时间与TR正相关，增大TR使扫描时间延长。C：层厚增大使体素增大、SNR升高而非降低。D：减小矩阵使像素增大、空间分辨率下降。E：NEX是平均次数，增大NEX延长扫描时间而提高SNR。", "tr": "FOV↓→分辨率↑但SNR↓＋卷褶风险↑；TR↑、NEX↑均延长扫描时间。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05099", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1021", "t": "单选题", "s": "腹部CT增强扫描拟在保证图像质量的前提下缩短扫描时间，下列措施不恰当的是", "o": {"A": "适当增大螺距", "B": "采用更宽探测器覆盖范围", "C": "提高机架旋转速度", "D": "大幅降低管电流且不采用迭代重建", "E": "使用双源或双能量快速扫描模式"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-105", "kp": "CT缩短扫描时间与质量控制", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】缩短扫描时间应通过增大螺距、加宽探测器覆盖、提高转速等方式实现，这些措施可基本保持剂量与噪声水平；而大幅降低mAs又不配合迭代重建会显著增大噪声、降低密度分辨率，无法保证诊断图像质量，故不恰当。\n【为什么错】A：增大螺距在合理范围内缩短扫描时间且图像质量可接受。B：宽探测器覆盖可减少扫描圈数、缩短时间。C：提高转速缩短单周采集时间。E：双源/双能量模式可加快采集并缩短时间。", "tr": "缩短扫描时间与保证质量需平衡；“降mAs必须配迭代重建”，否则违反质量控制原则。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1022", "t": "共用题干题", "s": "结合上述情景，患者拟行头颅MR检查，技师希望在T2WI序列上缩短扫描时间且尽量保持图像质量。下列最合理的措施是", "o": {"A": "单独增大TR", "B": "单独增大NEX", "C": "启用并行采集技术（SENSE/GRAPPA/ASSET）并相应调整参数", "D": "将矩阵由512×512降至128×128", "E": "减小层厚并增大FOV"}, "d": "难", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-105", "kp": "并行采集缩短扫描时间", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】并行采集技术利用多通道线圈的空间信息减少相位编码步数，可将扫描时间缩短为1/加速因子，同时SNR下降约为根号下加速因子倍，通过适当增大NEX或微调参数即可在基本保持质量的前提下明显缩短时间，是临床最常用措施。\n【为什么错】A：单独增大TR延长扫描时间并改变对比度。B：单独增大NEX延长扫描时间（虽然提高SNR）。D：矩阵降为128×128会显著降低空间分辨率，超出可接受范围。E：减小层厚降低SNR，增大FOV降低空间分辨率，均不合理。", "tr": "缩短MR扫描时间的首选是并行采集；NEX/TR变化方向“增大=延长时间”，勿选反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ05103", "gs": ""}, {"id": "ZG-U05-1023", "t": "多选题", "s": "关于影像质量保证（QA）与质量控制（QC）的关系，下列叙述正确的有", "o": {"A": "QC是QA的重要组成部分", "B": "QA的最终目的是确保影像质量满足诊断要求并持续改进", "C": "QC包括对成像设备与成像过程关键指标的检测和校正", "D": "QA仅指对图像质量的客观评价", "E": "QA与QC彼此独立、互不相干"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-105", "kp": "QA与QC的关系", "ch": "五、影像质量管理 → 1.概述 → (1)基本概念", "ex": "【为什么对】QC是对设备与技术指标进行检测、校正的具体环节，从属于QA整体；QA以影像质量满意并持续改进为目标，涵盖组织、制度、人员、设备与QC全部内容。\n【为什么错】D：QA不仅包含客观评价，还包含主观评价、管理制度、人员培训与QC活动。E：QC是QA的子系统，二者是从属关系而非相互独立。", "tr": "QA为大系统（含组织、管理、QC），QC为技术检测校正环节，是“整体与局部”关系。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-1024", "t": "共用题干题", "s": "结合上述情景，影像质量综合评价法通常应包含的内容有", "o": {"A": "物理与技术指标（如分辨率、噪声、灰阶）评价", "B": "观察者视觉判断与临床诊断价值的评价", "C": "仅依据设备出厂检验数据", "D": "受检者辐射剂量评估", "E": "与科室管理制度无关的纯技术评价"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-106", "kp": "综合评价法的构成", "ch": "五、影像质量管理 → 1.概述 → (3)主客观和综合评价法", "ex": "【为什么对】综合评价法将物理（客观）指标、观察者（主观/临床）评价及受检者剂量等多个维度结合起来，全面衡量影像质量，故物理技术指标、临床观察判断和剂量评估均属其内容。\n【为什么错】C：出厂检验数据只反映出厂时性能，不能替代在临床环境下的综合评价。E：综合评价需结合管理制度与临床实际，并非脱离管理体系的纯技术评价。", "tr": "综合评价=物理量+临床观察+剂量多维度结合，绝非单一指标或出厂数据。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05106", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1025", "t": "多选题", "s": "关于CR系统的质量控制，下列叙述正确的有", "o": {"A": "影像板（IP）应避免强光直射，使用前应充分擦除", "B": "IP板擦除不全会产生残留影像伪影", "C": "CR质量控制无需检测噪声水平", "D": "IP板有使用寿命，应定期检测其性能", "E": "读出扫描装置的采样间距不会影响图像空间分辨率"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CRQC-102", "kp": "CR质量控制要点", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】IP受环境散射线等影响易积累潜影，使用前需擦除并避免强光直射；擦除不净会以残留影像污染新图；IP有寿命限制，需定期进行响应均匀性、擦除效率等性能检测。\n【为什么错】C：噪声水平（本底噪声、量子噪声）是数字系统重要质控指标，CR亦需检测。E：读出采样间距（采样密度）直接影响空间分辨率，是CR质控内容之一。", "tr": "CR质控同样关注“噪声、分辨率、擦除效率”；IP寿命与残留伪影是CR特有考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-1026", "t": "多选题", "s": "DR系统日常及定期质量控制应包含的内容有", "o": {"A": "探测器平坦场（空气）校准", "B": "曝光指数（剂量指示）监测", "C": "空间分辨率与噪声检测", "D": "仅检查机械臂与立柱运动功能", "E": "监视器显示一致性检查"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-104", "kp": "DR质量控制内容", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】DR质控覆盖探测器（平坦场校准、线性、噪声、空间分辨率）、剂量（曝光指数监测）与显示链（监视器一致性）等多个环节，保证从采集到显示的图像质量。\n【为什么错】D：机械臂运动检查属于设备维护内容，不能替代探测器与图像质量的核心质控项目。", "tr": "DR质控核心在“探测器性能＋剂量指示＋显示链”，机械/电气检查不是图像质控主体。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-1027", "t": "多选题", "s": "数字乳腺X线摄影（FFDM/DBT）质量控制的内容包括", "o": {"A": "平均腺体剂量（AGD）监测", "B": "使用乳腺体模评估纤维、微钙化团块、肿块的可见数目", "C": "压迫器压力与自动曝光控制功能检查", "D": "只关注空间分辨率，与辐射剂量无关", "E": "定期进行系统几何（放大率、定位）校准"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-103", "kp": "数字乳腺摄影质量控制", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】乳腺摄影质控既包括剂量（AGD）监测与体模图像质量评估，也包括压迫/自动曝光等功能检查和系统几何校准，是多环节、质量与剂量并重的完整体系。\n【为什么错】D：乳腺摄影必须同时兼顾图像质量与低剂量，剂量监测是质控的强制内容，二者缺一不可。", "tr": "乳腺质控“质量＋剂量”双指标；ACD体模可见结构阈值是核心判定依据。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "数字X线图像质量控制", "页": 122}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-1028", "t": "共用题干题", "s": "结合上述情景，为改善CT图像的密度分辨率（低对比分辨率），可采取的措施有", "o": {"A": "增大管电流（mAs）", "B": "适当增大层厚", "C": "采用迭代重建算法降低噪声", "D": "减小重建矩阵（增大像素）", "E": "缩短扫描时间"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-106", "kp": "提高CT密度分辨率的措施", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (1)影响因素", "ex": "【为什么对】密度分辨率主要受噪声限制：增大mAs、增大层厚可增加光子数、降低噪声；迭代重建可抑制噪声；减小矩阵使像素增大、单像素光子增多，噪声下降，均有利于提高低对比分辨率。\n【为什么错】E：缩短扫描时间通常伴随光子数减少、噪声增大，使密度分辨率下降，且可能引入运动伪影，不是改善密度分辨率的措施。", "tr": "“增光子、降噪声”是提高密度分辨率主线（mAs↑、层厚↑、迭代重建）；缩短时间方向相反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05104", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1029", "t": "共用题干题", "s": "结合上述情景，下列措施中，有助于减少DSA图像运动（配准不良）伪影的有", "o": {"A": "嘱患者屏气并抑制吞咽", "B": "腹部检查前抑制肠蠕动", "C": "采用再蒙片（remasking）技术", "D": "增大对比剂用量", "E": "使用像素移位（pixel shifting）校正"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-103", "kp": "DSA运动伪影的防治措施", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (5)改善措施", "ex": "【为什么对】防治运动伪影分“防”与“纠”两级：防——嘱患者屏气、抑制吞咽和肠蠕动；纠——再蒙片、像素移位等配准处理，A、B、C、E均为有效措施。\n【为什么错】D：对比剂用量影响血管显影密度与对比度，不能消除蒙片与充盈像之间的位移，且过量会增加患者负担与伪影风险。", "tr": "DSA运动伪影“防（屏气/抑制蠕动）＋纠（再蒙片/像素移位）”，对比剂剂量不是对策。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05097", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1030", "t": "共用题干题", "s": "结合上述情景，在不明显延长扫描时间的前提下，下列措施中可提高MR图像SNR的有", "o": {"A": "增大体素（增大层厚或像素）", "B": "使用更高场强（如1.5T改为3.0T）", "C": "采用多通道线圈及并行采集", "D": "增大NEX", "E": "减小FOV"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-106", "kp": "提高MR SNR的措施", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】SNR与体素体积成正比，增大体素可提高SNR；高场强与多通道线圈均能提高信号采集效率；并行采集在缩短时间的同时SNR下降不多（为根号下加速因子的代价），配合上述措施可在时间基本不变的前提下提升SNR。\n【为什么错】D：增大NEX（平均次数）提高SNR但扫描时间成倍延长。E：减小FOV使像素变小、体素减小，SNR下降。", "tr": "提SNR的“免费”手段=增大体素/高场/多通道线圈；NEX是“花钱（时间）买SNR”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05104", "gs": ""}, {"id": "ZG-U05-1031", "t": "共用题干题", "s": "结合上述情景，下列因素中，能够影响MR扫描时间的有", "o": {"A": "重复时间TR", "B": "相位编码方向矩阵大小", "C": "平均次数NEX", "D": "窗宽窗位", "E": "并行采集的加速因子"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-107", "kp": "MR扫描时间的影响因素", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】扫描时间≈TR×相位编码步数×NEX×（序列加权等）÷并行采集加速因子，故TR、相位矩阵、NEX和并行采集加速因子均直接影响扫描时间。\n【为什么错】D：窗宽窗位只是图像显示参数，改变灰度显示范围，不影响采集和扫描时间。", "tr": "扫描时间公式：TR×相位步数×NEX÷加速因子；显示参数（窗宽窗位）绝不参与时间计算。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05099", "gs": ""}, {"id": "ZG-U05-1032", "t": "多选题", "s": "关于CT图像质量控制的内容，下列叙述正确的有", "o": {"A": "用标准水模检测CT值准确性、均匀性与噪声", "B": "用高对比分辨力（线对）模体检测空间分辨率", "C": "用低对比模体检测低对比分辨率（密度分辨率）", "D": "均匀性检测反映图像中心与边缘CT值的一致性", "E": "层厚检测与图像质量无关，无需进行"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-107", "kp": "CT质控检测项目与方法", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】CT质控按检测目的选用不同模体：水模测CT值、均匀性、噪声；线对模体测空间分辨率；低对比模体测密度分辨率。A、B、C、D均正确。\n【为什么错】E：层厚影响部分容积效应与空间分辨率，实际层厚与标称不符会造成图像质量与测量误差，属于常规质控项目，不能省略。", "tr": "模体用途对应关系：水模→CT值/均匀性/噪声，线对→空间分辨率，低对比模体→密度分辨率。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-1033", "t": "共用题干题", "s": "结合上述情景，关于MR图像空间分辨率与SNR之间的权衡关系，下列叙述正确的有", "o": {"A": "保持FOV不变增大矩阵，空间分辨率提高而SNR下降", "B": "保持矩阵不变增大FOV，像素增大、SNR升高而空间分辨率下降", "C": "减小层厚可减轻部分容积效应，但SNR下降", "D": "增大NEX可补偿矩阵增大所致的SNR下降，但扫描时间延长", "E": "增大层厚可同时提高空间分辨率与SNR"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-108", "kp": "空间分辨率与SNR的权衡", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】空间分辨率与SNR以体素为纽带互为代价：体素减小则分辨率提高、SNR下降；体素增大反之。减小层厚减少部分容积效应但体素变小、SNR下降；增大NEX可补偿SNR但时间延长，A、B、C、D均正确。\n【为什么错】E：增大层厚使体素增大、SNR升高，但同时加重部分容积效应、沿层厚方向空间分辨率下降，不能“同时提高空间分辨率”。", "tr": "凡是“体素变小”都提高分辨率而损SNR；“补偿SNR”就要付出扫描时间（NEX↑）代价。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ05105", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1034", "t": "多选题", "s": "某DSA设备近期图像质量普遍下降，下列可能的原因中正确的有", "o": {"A": "患者运动导致配准不良伪影增多", "B": "探测器灵敏度漂移而未及时校准", "C": "平板探测器老化使MTF下降、空间分辨率降低", "D": "常规使用大焦点摄影以提高空间分辨率", "E": "X线管焦点变大使几何模糊增加"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-104", "kp": "DSA图像质量下降原因分析", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (1)设备结构", "ex": "【为什么对】DSA图像质量受患者配合（运动伪影）、探测器状态（灵敏度漂移、老化致MTF下降）、X线源（焦点增大致几何模糊）等综合影响，A、B、C、E均为图像质量下降的可能原因。\n【为什么错】D：焦点越大几何模糊（半影）越明显、空间分辨率越低，常规使用大焦点恰恰会降低而非提高空间分辨率。", "tr": "“焦点大→模糊大、分辨率低”；探测器老化→MTF/DQE下降；校准是保持稳定的关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "DSA图像质量控制", "页": 130}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U05-1035", "t": "共用题干题", "s": "结合上述情景，技师为膝关节MR检查将FOV由180 mm缩小至150 mm而矩阵保持不变，关于此次参数调整的叙述，正确的有", "o": {"A": "空间分辨率提高", "B": "SNR下降", "C": "相位方向更易出现卷褶伪影", "D": "扫描时间自动缩短", "E": "像素尺寸增大"}, "d": "难", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-109", "kp": "FOV调整对图像参数的影响", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】矩阵不变而FOV减小，像素=FOV/矩阵变小，空间分辨率提高；体素变小使SNR下降；FOV缩小时相位方向覆盖范围不足，视野外组织折叠入图，卷褶伪影风险增大，A、B、C均正确。\n【为什么错】D：扫描时间取决于TR、相位编码步数与NEX，改变FOV不改变相位步数，扫描时间不变。E：FOV减小使像素变小而非增大。", "tr": "FOV↓→像素↓→分辨率↑、SNR↓、卷褶风险↑；FOV不直接影响扫描时间。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ05098", "gs": ""}, {"id": "ZG-U05-1036a", "t": "共用题干题", "s": "结合上述情景，该水模图像中心与边缘CT值明显不一致，反映的CT图像质量问题是", "o": {"A": "空间分辨率下降", "B": "图像均匀性（场均匀性）不良", "C": "层厚不准", "D": "螺旋扫描伪影", "E": "部分容积效应"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-108", "kp": "CT图像均匀性检测", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (2)控制内容", "ex": "【为什么对】均匀性反映同一均匀物质（水模）在图像不同位置（中心与边缘）CT值的一致性，中心与边缘CT值差异超过标准即判为均匀性不良，常提示探测器通道校准不良、球管或X线分布不均等问题。\n【为什么错】A：空间分辨率用线对模体检测，反映高频细节分辨能力，与CT值漂移无关。C：层厚不准影响部分容积与层厚方向分辨率。D：螺旋伪影多为条状、风车样伪影，不表现为CT值区域性偏移。E：部分容积效应出现在物体边缘密度突变处，水模均匀介质中不存在。", "tr": "“中心与边缘CT值不一致”=均匀性不良；均匀性、CT值、噪声三者均由水模检测。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05093", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1036b", "t": "单选题", "s": "针对该CT设备噪声标准差超标的问题，下列处理措施最恰当的是", "o": {"A": "立即停机更换X线管球", "B": "检查并校正探测器系统（增益校准），同时核实管电流、重建参数设置后再复测", "C": "仅增大窗宽以掩盖噪声", "D": "将扫描层厚增大至10 mm后继续使用", "E": "忽略噪声指标，只关注空间分辨率检测结果"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-109", "kp": "CT噪声超标处理措施", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】噪声超标需按“检查参数—校准系统—复测”的顺序处理：先核实扫描条件（mAs、重建算法等）是否合理，再对探测器进行增益校准以消除通道响应差异，校正后重新用水模复测确认达标。\n【为什么错】A：球管老化并非噪声增大的唯一原因，未排查参数与探测器即更换球管不恰当。C：窗宽只改变显示范围，不降低真实噪声。D：增大层厚虽可降低噪声但明显损害分辨率并加重部分容积效应，不是规范处理。E：噪声是密度分辨率的关键指标，不能忽略。", "tr": "噪声超标处理流程“查参数→校探测器→复测”；靠窗宽掩盖或加大层厚均属错误应对。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1037a", "t": "共用题干题", "s": "结合上述情景，该减影图像出现上述表现最可能的原因是", "o": {"A": "对比剂过敏反应", "B": "蒙片与充盈像之间发生位移（呼吸、肠蠕动等运动所致配准不良）", "C": "X线管焦点过小", "D": "图像增强器老化", "E": "曝光量过大"}, "d": "中", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-105", "kp": "DSA配准不良伪影的识别", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (2)成像方式和操作技术", "ex": "【为什么对】DSA减影要求蒙片与充盈像解剖位置完全一致，呼吸、肠蠕动使两次采集间发生位移，导致骨骼、肠气不能完全相减而残留，血管边缘出现“双边”，即典型的配准不良（运动）伪影，与题干中呼吸起伏、肠气明显相符。\n【为什么错】A：对比剂过敏反应表现为皮疹、血压下降等临床表现，不引起减影残留。C：焦点小反而提高空间分辨率，不产生双边伪影。D：图像增强器老化表现为亮度下降、模糊或增益不均，非运动型残留。E：曝光量过大致使噪声小、信号饱和，不产生双边结构。", "tr": "DSA“双边+骨肠残留”=运动/配准不良伪影；常见诱因为呼吸、吞咽、肠蠕动。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05097", "gs": ""}, {"id": "ZG-U05-1037b", "t": "共用题干题", "s": "结合上述情景，为改善该患者复查时的图像质量，下列准备与操作中不恰当的是", "o": {"A": "检查前禁食，必要时给予抑制肠蠕动药物", "B": "嘱患者配合屏气并减少腹部活动", "C": "采用脉冲采集以缩短曝光时间", "D": "让患者检查前进食以保证体力", "E": "必要时采用再蒙片或像素移位进行后处理校正"}, "d": "难", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-106", "kp": "DSA检查准备与运动伪影防治", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (4)患者本身因素", "ex": "【为什么对】腹部DSA前应禁食、抑制肠蠕动以减少胃肠道气体与蠕动；扫描中嘱患者屏气、减少活动；采用脉冲采集缩短曝光时间；必要时用再蒙片、像素移位校正残留位移，故A、B、C、E均为恰当措施。\n【为什么错】A：禁食并给予抑制肠蠕动药物是减少肠气与蠕动的正确准备，不属于不恰当操作。B：嘱患者配合屏气并减少腹部活动可有效减少运动伪影，恰当。C：脉冲采集缩短曝光时间、减少运动干扰，恰当。E：再蒙片与像素移位是纠正配准不良的有效后处理，恰当。D：检查前进食会增加胃肠蠕动与气体，加重运动伪影及气体重叠，且存在呕吐误吸等风险，属不恰当操作。", "tr": "腹部DSA“禁食+抑制蠕动+屏气”是标准准备；进食与饱餐会加重肠气蠕动伪影。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05096", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1038a", "t": "单选题", "s": "【病例】患者女，45岁，腰痛伴右下肢放射痛，行腰椎MR检查。矢状位T2WI图像整体噪声明显、SNR不足，椎体与椎间盘信号区分欠清晰。该序列为2D快速自旋回波，层厚4 mm，矩阵256×256，FOV 280 mm，NEX 2，扫描时间约3分钟，患者因疼痛配合欠佳、希望尽快完成检查。 在不延长扫描时间的前提下，提高该序列SNR最直接的方法是", "o": {"A": "增大层厚（如增至6 mm）以增大体素", "B": "将矩阵减小至128×128", "C": "将FOV增大至350 mm", "D": "提高重复时间TR", "E": "减小NEX"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-110", "kp": "通过体素调整提高SNR", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】SNR与体素体积成正比，增大层厚使体素增大、信号增强，SNR直接提高，且层厚变化不改变TR、矩阵与NEX，扫描时间不变，是“不延长时间提SNR”的最直接方法。\n【为什么错】B：减小矩阵使像素增大、体素增大，虽可提高SNR，但空间分辨率明显下降，作为首选调整幅度过大。C：增大FOV使像素增大、SNR升高，但会缩小有效显示区域、降低分辨率，且需重设定位。D：提高TR延长扫描时间且改变对比度。E：减小NEX降低SNR，方向相反。", "tr": "不延长扫描时间提SNR=增大体素（增层厚/增像素）；NEX、TR的增大都会延长时间。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1038b", "t": "共用题干题", "s": "结合上述情景，若既要保持较高的空间分辨率（薄层、高矩阵），又要获得可接受的SNR并减少运动伪影，合理的参数组合是", "o": {"A": "保持薄层高矩阵，适当增大NEX并配合并行采集与流动补偿技术", "B": "单纯减小矩阵", "C": "单纯增大层厚", "D": "关闭并行采集功能", "E": "减小FOV且不增加NEX"}, "d": "难", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-111", "kp": "MR高分辨率与SNR时间平衡", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】薄层高矩阵使体素变小、SNR下降，需增大NEX提高SNR（代价是时间）；并行采集可在缩短或抵消时间延长的同时保持分辨率；流动补偿减少脑脊液等流动信号伪影。三措并举可在保证分辨率的前提下兼顾SNR、时间与伪影控制。\n【为什么错】B：单纯减小矩阵降低空间分辨率。C：单纯增大层厚增加部分容积效应，损失薄层分辨率。D：关闭并行采集会延长扫描时间，不利于配合欠佳患者。E：减小FOV使SNR进一步下降且不增加NEX，无法补偿。", "tr": "“薄层高矩阵→SNR亏空”需用“NEX＋并行采集”补齐；单动任一项都会破坏平衡。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05100", "gs": ""}, {"id": "ZG-U05-1039a", "t": "共用题干题", "s": "结合上述情景，处理该问题前应首先执行的质控操作是", "o": {"A": "增大曝光剂量", "B": "执行探测器平坦场（空气）校准", "C": "更换显示监视器", "D": "调整窗宽窗位", "E": "升级图像后处理软件"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-105", "kp": "DR平坦场校准操作", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】平板探测器各像素增益不一致产生的图像不均匀，应通过平坦场（空气）校准——在无被照体条件下均匀曝光采集参考数据、计算校正系数——来消除，是DR质控的首选处理。\n【为什么错】A：增大曝光剂量不能校正像素间增益差异，且增加受检者剂量。C：监视器异常表现为显示整体亮度/色彩问题，与图像数据不均匀无关。D：窗宽窗位只改变显示灰阶，不能消除真实的不均匀。E：图像处理软件无法修正探测器硬件的增益不一致。", "tr": "探测器增益不均→平坦场校准；监视器/窗宽窗位/软件均不能解决探测器层面问题。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05094", "gs": ""}, {"id": "ZG-U05-1039b", "t": "共用题干题", "s": "结合上述情景，平坦场校准的主要作用机理是", "o": {"A": "增大X线球管的输出剂量", "B": "利用均匀曝光数据计算各像素增益校正系数，补偿像素响应差异", "C": "提高探测器的空间分辨率", "D": "减少到达探测器的散射线", "E": "改变图像的重建矩阵大小"}, "d": "易", "c": "理解", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DRQC-106", "kp": "DR平坦场校准原理", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (2)DR", "ex": "【为什么对】平坦场校正在无被照体、均匀X线照射条件下采集图像，以其为基准计算每个像素的增益校正因子，使各像素对相同入射剂量的响应趋于一致，从而消除增益不一致产生的条纹与斑点伪影。\n【为什么错】A：校准是数据处理而非提高球管输出。C：空间分辨率由像素尺寸与系统MTF决定，校准不改变。D：散射线量与照射条件及限束有关，校准不改变散射水平。E：矩阵由采样与重建参数决定，与校准无关。", "tr": "平坦场校准本质是“软件层面像素增益补偿”，不涉及剂量、分辨率或散射的改变。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05094", "gs": "在影像质量管理与评价中，下列做法正确的是。"}, {"id": "ZG-U05-1040", "t": "案例分析题", "s": "患者女，48岁，参加乳腺X线筛查项目，无自觉症状。医院新启用一台数字乳腺摄影系统（FFDM，钼靶X线管、自动曝光控制），质控技师按ACR程序对平均腺体剂量（AGD）进行评估，同时进行体模图像质量测试，检测时使用乳腺等效体模并分别模拟不同压迫厚度测量AGD。若AGD测量值超过标准限值，将分析管电压、靶/滤过组合及自动曝光设置等因素并调整后复测。", "o": {"A": "AGD与乳腺压迫厚度无关，无需分厚度测量", "B": "AGD应在保证图像质量的前提下尽可能低，用乳腺等效体模分厚度测量，超标时应分析并调整靶/滤过、管电压等参数后复测", "C": "AGD越大图像质量越好，应尽量提高AGD", "D": "AGD只需设备验收时测量一次，日常无需监测", "E": "AGD仅由管电流决定，与管电压、压迫厚度无关"}, "d": "中", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MMQC-104", "kp": "乳腺AGD测量与评价", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (3)乳腺", "ex": "【为什么对】AGD是乳腺摄影受检者剂量的核心指标，应在保证图像质量的前提下尽可能低（符合ALARA原则）；压迫厚度不同、曝光条件不同，须用乳腺等效体模分厚度测量；超标时要调整靶/滤过组合、管电压及自动曝光参数后复测，符合质控要求。\n【为什么错】A：压迫厚度直接影响所需曝光量，AGD随厚度增大而升高，必须分厚度评估。C：AGD增大不代表图像质量更好，且违背合理尽可能低原则。D：AGD须定期监测，非仅验收一次。E：AGD由管电压、靶/滤过组合、曝光量、压迫厚度等共同决定，非仅管电流。", "tr": "AGD评价必须“质量+剂量”双达标；分厚度测量、超标调整参数复测是标准流程。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1041", "t": "案例分析题", "s": "患者男，62岁，吸烟史40年，每日约20支，参加社区肺癌低剂量CT筛查项目。设备为64层螺旋CT，技师拟采用管电压100 kV、低管电流（mAs）并配合迭代重建算法完成扫描，既需尽量降低受检者辐射剂量，又需保证对肺内5 mm以下小结节与磨玻璃密度的检出能力。扫描后技师发现图像噪声较常规剂量明显增高，部分磨玻璃影显示欠佳。请评价该扫描方案在剂量控制与图像质量之间的平衡是否合理。", "o": {"A": "该方案不合理，低剂量扫描会使空间分辨率明显下降", "B": "该方案合理，降低mAs配合迭代重建可有效降低剂量并控制噪声，保持肺结节检出能力", "C": "降低管电压会明显增加辐射剂量", "D": "该方案下磨玻璃样结节将完全无法显示", "E": "迭代重建会显著降低空间分辨率，不适用于肺筛查"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CTQC-110", "kp": "低剂量胸部CT与迭代重建", "ch": "五、影像质量管理 → 3.CT图像质量控制 → (3)控制方法", "ex": "【为什么对】低剂量肺癌筛查的核心是用低kV、低mAs配合迭代重建：降低剂量可减少受检者辐射，迭代重建在噪声抑制上优于滤波反投影，可在不牺牲密度分辨率的前提下保持小结节与磨玻璃密度的检出能力，方案合理。\n【为什么错】A：低剂量扫描主要影响噪声与密度分辨率，空间分辨率由矩阵、算法等决定，并不明显下降。C：降低管电压通常降低剂量（同时需注意改变对比度与噪声平衡），不是增加剂量。D：合理低剂量方案下磨玻璃结节仍可检出，不会完全无法显示。E：迭代重建以降低噪声为主要目的，不显著降低空间分辨率。", "tr": "低剂量CT=低kV/mAs+迭代重建；迭代重建的作用是“抑制噪声保密度分辨率”，勿误认为损空间分辨率。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "CT图像质量控制", "页": 126}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1042", "t": "共用题干题", "s": "结合上述情景，患者男，60岁，因反复发作性右侧肢体无力1个月，临床疑左侧颈内动脉重度狭窄，拟行左侧颈内动脉DSA造影检查。患者既往有慢性咳嗽史，造影过程中吞咽及轻微咳嗽动作频繁，减影图像上出现血管边缘双边现象，颅底骨骼及软组织影未完全消除，病变血管显示模糊，影响狭窄程度判断与介入治疗决策。技师拟采取系列措施改善图像质量，请分析最恰当的处理策略。", "o": {"A": "增大对比剂注射总量以掩盖伪影", "B": "嘱患者配合屏气、减少吞咽咳嗽，改用脉冲采集缩短曝光时间，必要时采用再蒙片或像素移位校正", "C": "提高管电压以增强图像对比度", "D": "换用更大焦点球管", "E": "保持现有条件，直接以减影图像出具诊断报告"}, "d": "难", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-DSAQC-107", "kp": "DSA运动伪影的综合处理", "ch": "五、影像质量管理 → 4.DSA图像质量控制 → (5)改善措施", "ex": "【为什么对】颈动脉DSA的吞咽/咳嗽动作是配准不良伪影的直接原因，处理应从“防”入手：嘱患者配合屏气、尽量减少吞咽与咳嗽；以脉冲采集缩短曝光时间；再结合“纠”的再蒙片、像素移位等后处理校正，综合改善图像质量。\n【为什么错】A：增大对比剂总量不能消除位移伪影，反而增加剂量与并发症风险。C：管电压影响X线质与对比，不解决运动伪影。D：大焦点增加几何模糊，降低空间分辨率。E：伪影明显时图像不能满足诊断要求，应处理后再评，直接报告会导致漏诊误判。", "tr": "DSA运动伪影“防（屏气/脉冲采集）＋纠（再蒙片/像素移位）”缺一不可；对比剂、kV、焦点均非对策。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "MR图像质量控制措施", "页": 132}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ05096", "gs": ""}, {"id": "ZG-U05-1043", "t": "案例分析题", "s": "患者男，70岁，因阵发性头晕、行走不稳行头颅MR平扫。患者情绪紧张、配合欠佳，检查中头部频繁活动，技师需在尽量短时间内完成检查并控制运动伪影对图像质量的影响。拟在T2WI和T2-FLAIR序列中启用并行采集技术以缩短扫描时间，并选择对运动相对不敏感的序列与参数组合，必要时通过增加平均次数（NEX）补偿因加速采集导致的信噪比下降。请分析该扫描策略中的关键要点。", "o": {"A": "增大矩阵以缩短扫描时间", "B": "启用并行采集缩短扫描时间，优先采用快速、对运动不敏感的序列，必要时增加NEX补偿SNR", "C": "增大NEX本身会缩短扫描时间，应优先采用", "D": "增大层厚至10 mm可显著提高图像质量", "E": "延长TR可缩短扫描时间"}, "d": "中", "c": "应用", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-112", "kp": "配合欠佳患者的MR扫描策略", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (3)质量控制措施", "ex": "【为什么对】配合欠佳患者应缩短采集时间以减少运动伪影：并行采集可缩短扫描时间，快速序列（如T2-FLAIR、SS-FSE等）对运动相对不敏感；并行采集会带来一定SNR损失，必要时增加NEX补偿，组合策略合理。\n【为什么错】A：增大矩阵延长扫描时间，与目标相反。C：增大NEX延长扫描时间。D：层厚10 mm部分容积效应明显，显著降低图像质量。E：延长TR延长扫描时间且改变对比度。", "tr": "运动患者策略“并行采集+快速序列+必要时补NEX”；凡增大矩阵、NEX、TR的方向都延长时间。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1044", "t": "案例分析题", "s": "患者男，35岁，因咳嗽就诊行胸部X线摄影，使用CR系统。技师将影像板（IP）插入扫描仪读取后，图像上隐约可见上一例患者腰椎检查的残留轮廓，且本幅图像对比度下降、背景颗粒感增强。技师检查发现该IP板使用前擦除时间不足，且曾多次暴露于强光下，怀疑存在潜影残留。请分析CR系统残留影像的正确处理措施与日常预防方法。", "o": {"A": "对该IP板重新进行强光擦除后再读取，并规范IP使用前的擦除流程", "B": "残留影像不影响诊断，可直接出具报告", "C": "增大曝光量重新投照，残留即可消失", "D": "立即报废该IP板并更换新板", "E": "调整窗宽窗位即可消除残留影像"}, "d": "难", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-CRQC-103", "kp": "CR残留影像的处理", "ch": "五、影像质量管理 → 2.数字X线图像质量控制 → (1)CR", "ex": "【为什么对】CR残留影像是IP板擦除不净、上一幅潜影残留所致。正确做法是对IP重新进行强光擦除后再读取，并规范使用前的擦除流程（保证擦除时间与光强）以避免再次发生，既解决问题又节约IP资源。\n【为什么错】B：残留影像与真实病灶图像重叠，可能造成误诊漏诊，不能直接出报告。C：加大曝光量不能消除已存在的潜影残留，反而增加剂量并使残留更明显。D：单块IP因擦除不足残留，通过强光擦除通常即可恢复，无需立即报废，浪费资源。E：窗宽窗位只改变显示，无法去除真实残留信号。", "tr": "CR残留=IP擦除不净→“强光重擦”；窗宽窗位、加大曝光均属无效手段。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U05-1045", "t": "共用题干题", "s": "结合上述情景，患者女，32岁，因膝关节扭伤后疼痛、活动受限行右膝关节MR检查。技师为清晰显示半月板及关节软骨细节，将矢状位序列矩阵由256×256增大至512×512，层厚由4 mm减小至3 mm，视野（FOV）保持180 mm不变，NEX保持2。扫描完成后发现图像噪声明显增大、信噪比下降，技师拟评估并调整参数组合，以兼顾空间分辨率与SNR，同时不使扫描时间过度延长。", "o": {"A": "噪声增大系体素缩小所致，应适当增加NEX或配合并行采集补偿SNR，兼顾分辨率与时间", "B": "噪声增大说明球管故障，应停机检修", "C": "噪声增大系FOV过大所致，应进一步增大FOV", "D": "该参数调整会使空间分辨率下降", "E": "增大层厚至5 mm可同时提高空间分辨率与SNR"}, "d": "中", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-MRQC-113", "kp": "MR矩阵层厚调整的综合分析", "ch": "五、影像质量管理 → 5.MR图像质量控制 → (2)MR成像参数间相互影响", "ex": "【为什么对】FOV不变、矩阵加倍且层厚减薄使体素体积明显缩小，SNR下降、噪声增大，属正常物理规律。若要兼顾高分辨率与SNR，应增加NEX（付出时间）或配合并行采集（部分缩短时间），故A正确。\n【为什么错】B：噪声增大源于体素变小而非球管故障。C：增大FOV使像素增大、SNR升高，但同时降低空间分辨率并改变显示范围，不能用于补偿该调整。D：矩阵增大、层厚减薄使空间分辨率提高而非下降。E：层厚增大可提高SNR但增加部分容积效应、沿层厚方向分辨率下降，不能同时提高空间分辨率。", "tr": "矩阵↑+层厚↓=分辨率↑、SNR↓；补偿靠“NEX＋并行采集”，靠加大层厚/增大FOV会丢分辨率。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ05099", "gs": ""}, {"id": "ZG-U05-1046", "t": "案例分析题", "s": "某基层医院影像科新购置一台DR设备，拟建立影像质量保证（QA）体系。科室负责人要求质控技师制定质量控制（QC）制度与操作规程，规范设备的验收检测、日常维护、图像质量评估与受检者剂量监测，并建立记录档案、定期回顾分析，以持续改进影像质量。此前该科室曾因未开展定期检测，探测器灵敏度漂移导致图像质量下降。请从QA与QC关系角度分析该科室应优先落实的工作。", "o": {"A": "制定QC计划与操作规程，定期开展设备检测、图像评估与剂量监测，规范记录存档并持续改进", "B": "仅设备验收时检测一次，之后无需再测", "C": "检测记录可事后补写、随意修改", "D": "图像质量以技师主观印象评估即可，无需客观指标", "E": "出现图像质量问题仅更换设备，不追溯分析原因"}, "d": "中", "c": "分析", "m": "专业知识", "u": "五", "un": "影像质量管理", "kpid": "UNIT-05-QA-107", "kp": "科室QC制度建设", "ch": "五、影像质量管理 → 1.概述 → (2)管理方法", "ex": "【为什么对】科学的质量管理要求制定计划与操作规程，定期进行设备检测、图像评估和剂量监测，规范记录存档并定期回顾分析，形成“计划—执行—检查—处理”的持续改进循环，A符合QA/QC管理要求。\n【为什么错】B：设备性能随时间漂移，验收后仍需定期检测。C：检测记录必须真实完整、不可随意修改，否则失去质控意义。D：主观评估应结合客观指标（CT值、噪声、分辨率等），不能仅凭印象。E：出现质量问题应追溯分析原因并改进，更换设备只是被动应对，不能持续改进。", "tr": "质量管理核心=制度+定期检测+真实记录+持续改进；验收一次、事后补记、只换不查均为错误做法。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "影像质量管理", "节": "概述", "页": 119}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-0101", "t": "共用题干题", "s": "结合上述情景，关于模拟图像与数字图像的基本特征，下列描述正确的是", "o": {"A": "模拟图像的密度在空间上呈连续变化，数字图像由离散排列的像素与有限个灰度级构成", "B": "数字图像不能进行数值运算，只能供肉眼直接观察", "C": "模拟图像便于计算机直接存储、网络传输与后处理", "D": "数字图像的密度分辨率低于屏-片系统", "E": "增感屏-胶片系统属于典型的数字成像系统"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-001", "kp": "模拟图像与数字图像的区别", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】A 正确。模拟图像（如屏-片照片）用银颗粒沉积形成的连续光学密度记录信息，其空间位置与灰度均为连续量；数字图像则先经空间采样得到离散像素，再经幅度量化得到有限灰度级，用矩阵形式的数值阵列表达，位置与灰度都是离散量。【为什么错】B 数字图像最重要的优势恰恰是可以进行加减乘除、卷积滤波、傅里叶变换等各类数值运算，窗技术、减影、三维重建都建立在此基础上。C 模拟图像必须先经胶片数字化仪扫描转换为数字图像才能进入 PACS，其本身不便于计算机处理。D 数字探测器动态范围宽，配合窗技术可分段放大不同密度区间，其密度（对比度）分辨率高于屏-片系统。E 屏-片系统以连续光学密度记录影像，属典型模拟成像。", "tr": "\"数字图像空间分辨率通常低于屏-片、密度分辨率高于屏-片\"是两者比较的核心结论，D 项把密度分辨率与空间分辨率的结论对调，是最常见的设陷方式。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06119", "gs": ""}, {"id": "ZG-U06-0102", "t": "共用题干题", "s": "结合上述情景，某 DR 系统探测器采集视野为 43 cm×43 cm，输出图像矩阵为 3000×3000，据此计算其像素尺寸与由采样决定的理论极限空间分辨率约为", "o": {"A": "像素约 0.14 mm，极限空间分辨率约 3.5 lp/mm", "B": "像素约 0.14 mm，极限空间分辨率约 7.0 lp/mm", "C": "像素约 1.4 mm，极限空间分辨率约 0.35 lp/mm", "D": "像素约 0.29 mm，极限空间分辨率约 3.5 lp/mm", "E": "像素约 0.14 mm，极限空间分辨率约 1.75 lp/mm"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-002", "kp": "矩阵、像素尺寸与极限空间分辨率的换算", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (2)矩阵与像素", "ex": "【为什么对】A 正确。像素尺寸 d=视野/矩阵=430 mm÷3000≈0.143 mm。由采样决定的极限空间频率为奈奎斯特频率 f=1/(2d)=1/(2×0.143 mm)≈3.5 lp/mm。【为什么错】B 遗漏了系数 2，把 1/d 直接当作极限频率，这是最常见的计算错误。C 单位换算失误，把 43 cm 误当作 43 mm 或矩阵取错。D 像素尺寸计算错误（相当于用 43 cm÷1500）。E 极限频率计算错误（相当于 1/(4d)）。", "tr": "记住两个换算：像素尺寸=FOV/矩阵；奈奎斯特极限=1/(2×像素尺寸)。此外，探测器的实际极限分辨率还受探测器孔径、荧光体侧向扩散与焦点模糊限制，通常略低于理论奈奎斯特值。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06120", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-0103", "t": "多选题", "s": "下列关于数字图像常用术语的表述，正确的有", "o": {"A": "像素是构成二维数字图像的最小单元，体素是与之对应的三维组织体积单元", "B": "矩阵是像素按行列排列构成的阵列，视野一定时矩阵越大则像素越小、空间分辨率越高", "C": "灰阶级数由量化位深决定，12 bit 量化可表达 4096 个灰度级", "D": "动态范围指系统可线性响应的最大信号与最小可探测信号之比，数字探测器的动态范围远大于屏-片系统", "E": "原始数据与显示数据完全等同，故图像重建完成后仍可任意更换卷积核并缩小重建视野以提高分辨率"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-003", "kp": "像素、体素、矩阵、灰阶与动态范围", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】A 正确：像素只有面积概念，体素在像素基础上加上层厚这一维。B 正确：像素尺寸=FOV/矩阵，矩阵增大使像素变小、空间分辨率提高，但单个像素接收的光子数减少、噪声增大。C 正确：n 位量化可表达 2ⁿ 个灰度级，12 bit 即 2¹²=4096 级，CT 常用 12 bit 表达 -1024～3071 HU。D 正确：屏-片的宽容度受特性曲线直线段限制（约 1:40），而平板探测器动态范围可达 10⁴ 量级以上，这是数字摄影宽容度大的物理基础。【为什么错】E 错误：原始数据（扫描/投影数据）保留全部采集信息，可反复用不同重建视野、卷积核、层厚重建；重建后的显示数据已丢失部分原始信息，只能做窗技术、放大、测量等有限处理，无法事后更换卷积核或通过缩小视野提高真实分辨率。", "tr": "\"原始数据可重建、显示数据只能后处理\"是 CT 工作中的重要实践原则。急诊病例若原始数据已被自动清理，发现需要薄层重建时将无法补救，这也是原始数据保留时限管理的意义所在。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-0104", "t": "多选题", "s": "与传统增感屏-胶片系统相比，数字 X 线成像所具有的特点包括", "o": {"A": "曝光宽容度大，对曝光条件的依赖性明显降低，废片率下降", "B": "密度（对比度）分辨率高，借助窗技术可分别观察不同密度层次的组织", "C": "图像可数字化存储、网络传输与后处理，便于纳入 PACS 与远程会诊", "D": "目前通用型 DR 平板探测器的极限空间分辨率通常仍低于优质屏-片系统", "E": "由于宽容度大，无论曝光量高低，图像的噪声水平都基本不变"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-004", "kp": "数字成像与屏-片成像的性能比较", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】A 正确：数字探测器响应近似线性且动态范围宽，曝光量在较大范围内变化仍可通过后处理获得合适显示密度。B 正确：宽动态范围加上窗技术，使一次采集即可分别显示软组织、骨与含气结构。C 正确：这是数字化最重要的信息学价值。D 正确：通用型 DR 平板探测器的像素间距通常在 140～200 μm，极限分辨率约 2.5～3.6 lp/mm，仍低于优质屏-片系统（可达 5 lp/mm 以上）；专用乳腺探测器像素更小，分辨率明显更高。【为什么错】E 错误：宽容度大只是使显示密度趋于\"正常\"，掩盖了曝光量的差异，但图像噪声仍严格取决于探测器接收的光子数。曝光不足时图像看似正常而量子噪声显著增加；反之技师为求\"图像好看\"习惯性加大条件，就形成了数字摄影特有的\"剂量漂移\"隐患，这正是必须监控曝光指数的原因。", "tr": "宽容度大是优点也是风险：屏-片时代曝光过量会直接表现为照片过黑而被发现，数字系统却\"看不出来\"，只能靠曝光指数与偏差指数发现，务必把 E 这类说法与噪声机制区分开。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-0105", "t": "共用题干题", "s": "结合上述情景，模拟信号数字化的采集环节必须遵循采样定理（奈奎斯特定理），下列描述正确的是", "o": {"A": "采样频率应不低于被采样信号最高空间频率的 2 倍，否则超出奈奎斯特频率的成分会折叠为低频成分，形成混叠伪影", "B": "采样频率越低，图像所保留的信息越完整", "C": "采样定理只适用于随时间变化的信号，不适用于图像的空间采样", "D": "提高量化位深即可弥补采样频率不足所造成的信息丢失", "E": "混叠只改变图像的灰度水平，不影响空间结构的真实性"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-001", "kp": "采样定理与混叠", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】A 正确。采样定理指出，欲无失真地恢复原信号，采样频率须至少为信号最高频率的 2 倍；对图像而言，采样间距 d 决定的奈奎斯特频率为 1/(2d)，高于该频率的空间成分会被错误地折叠（混叠）到低频区，形成虚假的低频条纹或图案。DR 图像中滤线栅栅线与像素采样频率相近时产生的摩尔纹，就是典型的空间混叠。【为什么错】B 完全相反，采样频率越低丢失的高频信息越多。C 采样定理是信号处理的普适规律，同样适用于空间维度的图像采样。D 位深解决的是幅度量化精度，与空间采样密度无关，不能弥补采样不足。E 混叠产生的是虚假的空间结构（条纹、图案），会造成结构性误判，远不止灰度改变。", "tr": "把\"混叠\"（采样不足，空间频率折叠）与\"伪轮廓\"（量化位深不足，灰阶阶梯）混为一谈是常见错误：前者是采样问题、表现为虚假条纹；后者是量化问题、表现为平缓区的阶梯状分界。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06125", "gs": ""}, {"id": "ZG-U06-0106", "t": "共用题干题", "s": "结合上述情景，在数字图像形成过程中，\"量化\"这一环节所完成的工作是", "o": {"A": "把连续分布的空间位置离散化为若干个采样点", "B": "把每个采样点上连续变化的信号幅度用有限个离散数值（灰度级）表示，其级数由量化位深决定", "C": "把数字信号还原为模拟电压后输出到显示器", "D": "把图像数据按 DICOM 格式封装以便网络传输", "E": "把图像的空间频率成分分解到不同频带中分别处理"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-002", "kp": "量化的定义与位深", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (2)量化", "ex": "【为什么对】B 正确。模数转换包括采样、量化与编码三步：采样解决\"在哪里取值\"，量化解决\"取到的值用多少级表示\"，编码解决\"用什么二进制形式表达\"。量化位深 n 决定灰度级数 2ⁿ，位深越高对细微密度差的表达越精细。【为什么错】A 这是采样（空间离散化）的定义。C 这是数模（D/A）转换，属于图像输出显示环节。D 这是数据封装与通讯，属 PACS/DICOM 范畴，不是图像形成的量化步骤。E 这是频率域变换（傅里叶变换、小波分解）等图像处理操作。", "tr": "口诀：\"采样管位置、量化管幅度、编码管表达\"。量化位深不足的典型影像表现是灰度平缓过渡区出现阶梯状伪轮廓（假等高线），而非颗粒噪声。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06127", "gs": ""}, {"id": "ZG-U06-0107", "t": "多选题", "s": "就数字 X 线图像形成过程中的采集、量化与能量转换环节而言，下列分析正确的有", "o": {"A": "采集环节决定空间采样密度，探测器采样孔径与采样间距共同影响系统的预采样调制传递函数", "B": "量化位深不足会在灰度平缓过渡区产生阶梯状伪轮廓，但不改变图像的空间分辨率", "C": "间接转换型平板探测器先由碘化铯或硫氧化钆闪烁体把 X 线转换为可见光，再经光电二极管阵列转换为电信号；直接转换型由非晶硒把 X 线直接转换为电荷", "D": "碘化铯为柱状晶体结构，可限制可见光的侧向扩散，其调制传递函数优于颗粒状硫氧化钆", "E": "模数转换位深越高，图像的空间分辨率也随之越高"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-003", "kp": "探测器转换方式与图像形成环节分析", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (3)转换", "ex": "【为什么对】A 正确：采样孔径决定单个探测单元的\"积分平滑\"作用，采样间距决定奈奎斯特频率，二者共同构成预采样 MTF。B 正确：位深属幅度量化范畴，影响密度分辨率与灰度过渡的平滑性，不影响空间采样密度。C 正确：这是间接转换与直接转换平板探测器的标准定义，前者多一次光转换，后者利用非晶硒的光电导性质在偏置电场下直接收集电荷。D 正确：柱状生长的碘化铯像光纤一样把可见光约束在柱内向下传导，明显减少侧向扩散，故在同样厚度下可兼顾吸收效率与空间分辨率；颗粒状硫氧化钆的光散射较大，增厚提高吸收的同时会明显损失分辨率。【为什么错】E 错误：位深决定灰度量化精度（密度分辨率），空间分辨率由采样间距与探测器孔径、焦点尺寸等几何因素决定，二者相互独立。", "tr": "非晶硒（直接转换）没有可见光扩散过程，理论 MTF 最高，但对温度与湿度敏感、需高偏置电压且 X 线吸收效率相对偏低；碘化铯（间接转换）吸收效率与 DQE 表现更好，各有取舍，不宜简单断言孰优孰劣。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-0108", "t": "共用题干题", "s": "结合上述情景，某腹部 CT 图像以窗宽 350 HU、窗位 50 HU 显示，显示器按 256 级灰阶输出，下列计算结果正确的是", "o": {"A": "显示的 CT 值范围为 -125 HU～225 HU，每个灰阶约代表 1.37 HU", "B": "显示的 CT 值范围为 -300 HU～400 HU，每个灰阶约代表 2.73 HU", "C": "显示的 CT 值范围为 50 HU～400 HU，每个灰阶约代表 1.37 HU", "D": "显示的 CT 值范围为 -125 HU～225 HU，每个灰阶约代表 0.73 HU", "E": "显示的 CT 值范围为 -175 HU～175 HU，每个灰阶约代表 1.37 HU"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-001", "kp": "窗宽窗位与显示范围的计算", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】A 正确。显示上限=窗位+窗宽/2=50+175=225 HU，显示下限=窗位-窗宽/2=50-175=-125 HU；每个灰阶代表的 CT 值跨度=窗宽/灰阶数=350÷256≈1.37 HU。高于 225 HU 的组织一律显示为白，低于 -125 HU 的一律显示为黑。【为什么错】B 把窗宽误当作以窗位为中心上下各 350 HU。C 误把窗位当作显示范围的下限。D 除法错误，350÷256 不等于 0.73。E 忽略了窗位的偏移，相当于按窗位为 0 计算。", "tr": "牢记两条规律：窗宽决定对比度（窗宽越窄对比度越高、可分辨的密度层次越少），窗位决定图像整体明暗（窗位升高图像整体变黑）。计算题必须先算上下限再算灰阶步长，切勿把窗位当作下限。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06122", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-0109", "t": "案例分析题", "s": "一名 26 岁男性因车祸致胸部撞击伤，急诊行胸部 CT 平扫。临床同时提出三方面评估要求：①肺挫伤范围与有无气胸；②纵隔血肿与大血管情况；③肋骨与胸椎有无骨折。技师需在同一组容积原始数据上完成后处理、观察与照片输出，既要保证诊断信息完整，又要避免不必要的重复扫描。下列窗技术设置与处理方案中最合理的是", "o": {"A": "全部内容统一用软组织窗（约 WW 350/WL 50）观察即可，其他窗设置交由诊断医师在工作站自行调节", "B": "分别采用肺窗（约 WW 1500/WL -600）、纵隔窗（约 WW 350/WL 40）与骨窗（约 WW 1500～2000/WL 400～500）三套设置观察并输出；骨窗宜配合薄层与骨算法重组以提高细节显示", "C": "把窗宽调到最大（如 4000 HU）用一套设置显示全部组织，即可免去分窗观察", "D": "统一采用窄窗（约 WW 50/WL 40）观察，窗宽越窄图像层次越丰富、信息越多", "E": "肺内病变宜用骨算法重建配合纵隔窗观察，以兼顾空间分辨率与密度分辨率"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-002", "kp": "窗技术在胸部创伤 CT 中的应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】B 正确。胸部涵盖含气肺组织（约 -900～-700 HU）、软组织（约 30～60 HU）与骨皮质（>700 HU），密度跨度极大，单一窗设置无法兼顾。肺窗宽而低位，用于观察肺纹理、挫伤与气胸；纵隔窗窄而居软组织区，用于血肿与大血管；骨窗宽而高位，配合薄层与骨（锐利）算法重组显示骨皮质中断。同一次采集的原始数据可反复重建，无需重复曝光。【为什么错】A 单一软组织窗下肺野呈一片黑、骨皮质呈一片白，肺挫伤、气胸与细微骨折均可能被漏诊，技师有责任提供符合诊断要求的图像。C 窗宽过大使对比度极低，各组织密度差被压缩到很少几个灰阶内，细微病变反而无法辨认。D 窗宽过窄使超出显示范围的组织全白或全黑，信息大量丢失，同时噪声被放大，与\"层次丰富\"恰恰相反。E 组合错误：肺内病变应用肺（高分辨）算法重建配合肺窗观察；纵隔窗下肺野几乎全黑，骨算法又会明显放大噪声，二者搭配观察肺组织不合理。", "tr": "重建算法（卷积核）必须在图像重建阶段选定，只能基于原始数据重建；而窗宽窗位属显示参数，可在任何时候对已重建图像调整。把\"换算法\"与\"换窗\"混为一谈是常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-0110", "t": "共用题干题", "s": "结合上述情景，关于数字 X 线摄影中的组织均衡（tissue equalization）技术，下列描述正确的有", "o": {"A": "其本质是动态范围压缩，把高密度区与低密度区的信号压缩到同一显示范围内同时呈现", "B": "典型应用如胸部摄影中同时清晰显示肺野、纵隔与膈下区域，以及颈胸交界、股骨颈等厚度差异悬殊部位", "C": "常用实现方式是把原始图像分解为反映大范围密度分布的低频成分与反映细节的高频成分，压缩低频动态范围后与高频成分重新合成", "D": "处理后局部对比度得以保留甚至增强，但整体密度阶差被压缩，过度处理可能出现边缘晕环等处理伪影", "E": "组织均衡是通过增加曝光剂量来实现图像密度均一化的技术"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-003", "kp": "组织均衡技术的原理与应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (2)组织均衡技术", "ex": "【为什么对】A 正确：组织均衡针对的是被检部位厚度、密度差异过大导致\"顾此失彼\"的问题，通过压缩动态范围实现兼顾。B 正确：这些正是临床上厚薄悬殊、常需两次不同条件曝光的部位。C 正确：多尺度频率分解（如拉普拉斯金字塔、多分辨率分析）后单独压缩低频背景、保留或增强高频细节，再合成输出，是主流算法思路。D 正确：处理强度过大时在高对比界面（如纵隔缘、金属植入物边缘）可出现暗环或亮环状的晕环伪影，须适度设置参数。【为什么错】E 错误：组织均衡是纯粹的图像后处理算法，不改变采集时的曝光条件与剂量；它的价值恰恰在于让一次曝光满足多部位观察需求，从而避免重复摄影、降低总剂量。", "tr": "组织均衡是\"后处理\"而非\"采集技术\"，与双能减影（需两次不同能量采集）、体层融合（需多角度采集）有本质区别，命题常把三者的技术属性互换设陷。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06124", "gs": ""}, {"id": "ZG-U06-0111", "t": "单选题", "s": "就最大密度投影（MIP）与最小密度投影（MinIP）的原理及适用范围而言，下列描述正确的是", "o": {"A": "MIP 沿投影线取路径上的最大 CT 值，适于显示强化血管、支架与钙化；MinIP 取最小值，适于显示气管支气管树、含气肠管与扩张胆道等低密度结构", "B": "MIP 与 MinIP 都保留了结构的前后深度关系，可据此判断血管的空间前后位置", "C": "MinIP 主要用于显示强化后的动脉血管", "D": "MIP 成像时骨骼与钙化不会对血管显示造成干扰", "E": "MIP 属于表面遮盖显示技术，通过设定阈值仅重建物体的表面轮廓"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-004", "kp": "MIP 与 MinIP 的原理与适用范围", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】A 正确。MIP 沿每条视线取该路径上密度最高的体素值投影成像，对高密度结构敏感，是 CTA、支架与钙化显示的常用方法；MinIP 取路径上最低值，突出低密度含气或含液结构，常用于气道树、肺气肿评估与胆道显示。【为什么错】B 两者都是沿投影线取极值，路径上其他体素信息被丢弃，深度关系随之丢失，重叠血管的前后位置无法判断，需结合原始横断面或 VR 图像。C 方向颠倒，强化血管属高密度结构，应用 MIP。D 骨与钙化的 CT 值高于强化血管，是 MIP 显示血管的主要干扰源，需先行去骨、采用薄层 MIP 或结合 VR 与横断面判读。E 描述的是 SSD（表面遮盖显示）的原理；MIP 是容积投影技术，不设表面阈值。", "tr": "MIP 的两大固有缺陷要牢记：一是丢失深度信息（前后重叠无法判断），二是高密度结构（骨、钙化、金属）遮盖血管。因此 MIP 只能作为辅助显示手段，狭窄程度评估必须回到横断面与 MPR。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-0112", "t": "多选题", "s": "下列关于常用三维图像后处理技术原理与适用范围的表述，正确的有", "o": {"A": "MPR 是在容积数据中沿任意平面重组二维图像，质量受原始层厚与体素各向同性程度限制；CPR 为曲面重组，可把迂曲血管或牙列展开于一个平面，但会造成解剖形态失真，不宜直接据此测量真实长度", "B": "SSD 依据设定的 CT 值阈值提取物体表面轮廓，立体感强但丢弃内部信息，阈值选择对结果影响显著", "C": "VR 使容积内全部体素按不透明度与颜色映射参与成像，可同时显示不同组织并保留空间关系，是目前最常用的三维显示方式", "D": "仿真内镜采用透视投影并把视点置于管腔内部，可观察腔内形态，但不能反映黏膜色泽变化，也不能取材活检", "E": "MPR 可以突破原始采集的空间分辨率限制，通过薄层重组获得比原始体素更高的真实分辨率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-005", "kp": "MPR/CPR/SSD/VR/仿真内镜的原理对比", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】A 正确：MPR 属二维重组，各向同性薄层采集是获得高质量冠、矢状及斜位重组的前提；CPR 沿人工或自动勾画的中心线展开，长度与形态在展开过程中被拉伸变形，测量应在原始三维数据上进行。B 正确：SSD 只保留阈值以上体素的表面，内部密度信息全部丢失，阈值稍有改变即可显著改变管腔口径的表观，现多被 VR 取代。C 正确：VR 通过不透明度曲线与伪彩映射让所有体素按权重贡献于最终图像，兼具立体感与组织区分能力。D 正确：仿真内镜是 VR/SSD 与透视投影结合的腔内漫游显示，优点是无创、可到达常规内镜难以通过的狭窄段，缺点是无法观察颜色与黏膜细节、不能活检与治疗。【为什么错】E 错误：MPR 只是对既有体素数据重新排列与插值，其分辨率上限由采集时的体素尺寸（尤其层厚与重建间隔）决定，插值不能创造新信息；要获得高质量重组，必须在采集阶段使用薄层与各向同性体素。", "tr": "\"薄层重组\"与\"薄层采集\"是两回事：在 5 mm 层厚图像上重组出 1 mm 层厚，只会得到模糊的插值结果。凡涉及重组的检查，应在扫描时即选择薄层重建并保留原始数据。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-0113", "t": "案例分析题", "s": "一名 55 岁男性因发作性胸痛行冠状动脉 CTA，采用回顾性心电门控、各向同性薄层采集，图像质量良好。临床同时提出三项需求：①判断左前降支近段一处点状钙化斑块处的管腔狭窄程度；②整体展示冠状动脉走行及其与既往桥血管的解剖关系，供术前多学科讨论使用；③沿右冠状动脉长轴全程评估管壁与斑块分布。技师需为每一项需求匹配最合适的后处理方法。下列组合最恰当的是", "o": {"A": "①以原始横断面与垂直于血管长轴的短轴 MPR 为主、辅以薄层 MIP，必要时借助能量成像高 keV 单能量图像减轻钙化晕状效应；②VR；③CPR", "B": "①VR；②SSD；③MinIP", "C": "①仿真内镜；②MIP；③SSD", "D": "①MinIP；②CPR；③VR", "E": "三项需求全部使用最大密度投影即可满足"}, "d": "难", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-006", "kp": "冠状动脉 CTA 后处理方法的选择", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】A 正确。①评估钙化处管腔必须保留真实 CT 值并观察垂直于血管长轴的断面，故以横断面与短轴 MPR 为核心，薄层 MIP 可辅助连续性判断；钙化的晕状效应（blooming）会高估狭窄，采用能量成像的高 keV 虚拟单能量图像可减轻。②整体解剖关系与桥血管空间走行的展示是 VR 的长项，立体直观、适合多学科沟通。③沿血管长轴全程展开评估管壁正是 CPR 的经典适应证。【为什么错】B ①用 VR 判断狭窄程度会因不透明度曲线与阈值设定不同而显著改变管腔表观，易造成误判；SSD 已基本被 VR 取代；MinIP 适用于低密度结构，与强化血管不匹配。C 仿真内镜只显示腔内表面形态，钙化斑块处的真实管腔径线无法可靠判断；用 SSD 评估管壁同样丢失密度信息。D MinIP 不适于强化血管；把 CPR 用于整体空间关系展示则失去了立体信息。E MIP 丢失深度关系且对钙化极为敏感，既无法满足解剖关系展示，也不适合长轴管壁评估。", "tr": "\"三维图像越漂亮越可靠\"是最危险的误区。VR 与 MIP 的表观受阈值、不透明度、窗设置强烈影响，任何定量判断（狭窄率、径线测量）都应回到原始横断面与 MPR 上完成。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-0114", "t": "单选题", "s": "调制传递函数（MTF）是评价成像系统信号传递能力的重要指标，下列描述正确的是", "o": {"A": "MTF 描述系统把不同空间频率的输入对比度传递到输出的能力，空间频率为 0 时 MTF=1，随频率升高而下降", "B": "MTF 数值越低，说明系统的空间分辨率越高", "C": "多个成像环节串联时，系统总 MTF 等于各环节 MTF 之和", "D": "MTF 只反映系统的噪声特性，与空间分辨率无关", "E": "通常取 MTF 降至 0.5 时对应的空间频率作为系统的极限空间分辨率"}, "d": "中", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-001", "kp": "调制传递函数 MTF 的含义", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】A 正确。MTF 定义为输出调制度与输入调制度之比，是空间频率的函数。低频（大结构）几乎无损传递，故 MTF(0)=1；随空间频率升高，系统的模糊作用使对比度传递能力下降，MTF 逐渐趋近于 0。【为什么错】B 恰恰相反，同一空间频率下 MTF 值越高，说明该频率成分被传递得越充分，分辨率表现越好。C 串联系统的总 MTF 等于各环节 MTF 的乘积，因此任一薄弱环节（如焦点过大、探测器模糊、显示器不足）都会显著拉低整体表现，这也是\"短板效应\"在成像链中的体现。D MTF 描述的是信号（分辨率）传递特性；噪声特性由噪声功率谱（维纳频谱，NPS）描述，二者结合并考虑入射量子数才构成 DQE。E 习惯上取 MTF 降至 0.1（10%）时对应的空间频率作为极限分辨率，MTF=0.5 对应的频率常用于比较系统的中频表现，不是极限分辨率的定义。", "tr": "\"MTF 相乘、DQE 综合、NPS 管噪声\"是三个评价量的记忆框架。C 项把\"乘积\"换成\"求和\"、E 项把 10% 换成 50% 都是高频陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-0115", "t": "多选题", "s": "作为评价数字探测器综合性能的核心指标，量子探测效率（DQE）具有下列哪些特性", "o": {"A": "DQE 表示输出信噪比平方与输入信噪比平方之比，反映系统对入射 X 线光子所携带信息的利用效率", "B": "DQE(f)=MTF²(f)/[NNPS(f)×q]，同时包含信号传递与噪声两方面的信息", "C": "相同入射剂量下 DQE 越高图像质量越好；在相同图像质量要求下，DQE 越高则所需剂量越低", "D": "DQE 是空间频率的函数，通常随空间频率升高而下降，并随入射剂量水平的不同而变化", "E": "性能优异的探测器 DQE 可以大于 1，说明其对信号具有净放大作用"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-002", "kp": "量子探测效率 DQE", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (2)DQE", "ex": "【为什么对】A 正确：DQE=SNR²_out/SNR²_in，本质是\"信息利用率\"。B 正确：分子的 MTF² 代表信号传递能力，分母的归一化噪声功率谱与入射光子数 q 代表噪声与量子涨落，公式把分辨率、噪声与剂量三要素统一起来。C 正确：这正是 DQE 成为探测器选型核心指标的原因——高 DQE 意味着\"同剂量更好图像\"或\"同图像更低剂量\"，直接对应患者剂量优化。D 正确：DQE 在低频最高、随频率升高而衰减；且因电子学噪声、结构噪声在不同剂量水平下所占比例不同，DQE 曲线会随剂量变化，故报告 DQE 必须注明测试剂量与射线质（如 RQA5）。【为什么错】E 错误：DQE 是效率量，理想无损探测器为 1（100%），实际系统因量子吸收不完全、二次量子损失、电子噪声与散射恒小于 1。电子学放大会同时放大信号与噪声，不改变信噪比，因而不可能使 DQE 超过 1。", "tr": "DQE 与\"量子检出率/吸收效率\"不是一回事：探测器即使吸收了全部入射光子（吸收效率 100%），若后续转换与读出过程引入噪声或模糊，DQE 仍会明显低于 1。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-0116", "t": "共用题干题", "s": "结合上述情景，某研究比较两种重建算法对肺内小结节的检出效能，绘制 ROC 曲线后得算法甲 AUC=0.92、算法乙 AUC=0.78。对该结果的解释，下列正确的是", "o": {"A": "AUC 相当于随机抽取一对阳性与阴性病例时模型给阳性病例更高判断分值的概率；甲的总体诊断效能优于乙，且 AUC 的比较不受某一具体判断阈值的影响", "B": "AUC=0.5 表示诊断效能已达中等水平", "C": "ROC 分析只能用于评价计算机算法，不能用于比较不同观察者的阅片水平", "D": "甲的 AUC 更高，说明在任何工作点上甲的灵敏度与特异度都高于乙", "E": "ROC 分析要求预先固定判断阈值，因此结论高度依赖阈值的设定"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-003", "kp": "ROC 曲线与曲线下面积 AUC", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (3)ROC曲线", "ex": "【为什么对】A 正确。AUC 的概率学含义即\"随机取一阳性与一阴性样本，阳性样本获得更高判断评分的概率\"；由于 AUC 是遍历所有阈值形成的曲线下面积，其比较不受某一固定阈值（判读尺度松紧）的影响，这正是 ROC 优于单点灵敏度/特异度比较的关键。【为什么错】B AUC=0.5 对应对角线，相当于随机猜测、无诊断价值；一般认为 0.7～0.8 为一般、0.8～0.9 为较好、大于 0.9 为优秀。C ROC 最初正是为评价观察者（放射科医师）诊断决策而引入影像学的，可用于比较不同观察者、不同设备与不同算法。D AUC 反映整体效能，两条 ROC 曲线可能相交，在高特异度或高灵敏度的特定工作点上乙仍可能优于甲，需结合部分曲线下面积或临床所需工作点分析。E 与事实相反，ROC 的核心做法是连续改变判断阈值获得整条曲线，从而摆脱单一阈值的束缚。", "tr": "对于结节检出这类\"一幅图上可有多个病灶\"的任务，更严谨的评价工具是 FROC/AFROC 曲线（横轴为每幅图像的假阳性数）；把 ROC 与 FROC 混用是科研设计中的常见错误。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06116", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-0117", "t": "共用题干题", "s": "结合上述情景，有关计算机辅助诊断（CAD）系统的分类与临床定位，下列描述正确的是", "o": {"A": "CAD 分为计算机辅助检出（CADe）与计算机辅助定性诊断（CADx）两类，其临床定位是作为医师的\"第二阅片者\"提供参考，最终诊断责任仍由医师承担", "B": "CAD 的目标是取代放射科医师独立完成诊断并出具报告", "C": "CAD 系统的典型性能特点是特异度极高而灵敏度偏低", "D": "CAD 只处理图像中的密度信息，不涉及形态、边缘与纹理特征", "E": "CAD 所标记的每一个位置都对应真实存在的病灶"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-001", "kp": "CAD 的分类与临床定位", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (1)概述", "ex": "【为什么对】A 正确。CADe 负责把可疑病灶标记出来（如肺结节、微钙化簇），CADx 进一步对已发现病灶做良恶性倾向等定性分析。无论哪一类，其法律与临床定位都是辅助工具、第二阅片者，用于提示医师复核可能忽略的区域，诊断决定权与责任归于医师。【为什么错】B CAD 不具备独立出具诊断报告的资质，也不能替代医师对临床信息的综合判断。C 恰恰相反，CAD 通常以高灵敏度为设计目标（尽量不漏），代价是假阳性标记较多、特异度相对偏低。D CAD 的特征提取涵盖密度、形态学（大小、圆形度、边缘毛刺）、纹理、空间分布等多维特征，深度学习模型还能自动学习高阶特征。E CAD 标记中包含相当比例的假阳性，医师须逐一甄别，不能不加判断地全部采信。", "tr": "\"高灵敏度、低特异度\"是传统 CAD 的固有属性，也是它必须由医师复核的根本原因。命题常把灵敏度与特异度的高低对调设置干扰。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06108", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-0118", "t": "案例分析题", "s": "某三甲综合医院影像科日均乳腺 X 线摄影约 120 例、胸部 DR 约 300 例，拟在 2 台乳腺机与 3 台 DR 上统一部署计算机辅助诊断（CAD）系统：乳腺方面希望提高成簇微钙化与肿块的检出率，胸部方面希望减少肺结节漏诊并控制假阳性负荷。科室在组织技师与诊断医师的联合上线培训时，需要系统说明该类软件的性能边界、标准工作流与合理使用方式，以避免医师过度依赖或错误解读标记。下列培训要点中正确的是", "o": {"A": "乳腺 CAD 对成簇微钙化的检出灵敏度通常高于对肿块的检出灵敏度，因为致密型腺体背景易掩盖肿块；使用上应由医师先完成独立阅片、再调阅 CAD 标记作为第二阅片参考，并配套开展假阳性标记的甄别培训", "B": "上线 CAD 后医师只需阅读被标记的区域，未被标记的区域可不再逐一观察", "C": "CAD 在致密型乳腺中的检出表现优于脂肪型乳腺", "D": "胸部 CAD 的假阳性主要来自真实结节，因此标记数量越少说明系统性能越好", "E": "CAD 的基本流程是直接对原始图像输出结论，无须图像预处理、候选检出与特征提取等中间环节"}, "d": "中", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-002", "kp": "乳腺与胸部 CAD 的性能特点及使用方式", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (3)乳腺应用", "ex": "【为什么对】A 正确。微钙化在图像上具有高对比、高空间频率的特征，算法易于提取，检出灵敏度普遍较高；肿块表现为软组织密度影，在致密型腺体背景中对比度低、边缘不清，检出难度明显更大。标准使用流程是医师先独立完整阅片形成初步意见，再打开 CAD 标记进行第二次核查，从而既获得提示价值又避免被误导。【为什么错】B 这会导致\"搜索满足效应\"，医师注意力被标记区吸引而忽略其余区域，反而可能增加漏诊，是 CAD 使用中必须重点规避的行为。C 恰恰相反，致密型腺体的组织重叠使病灶对比度下降，无论人眼还是 CAD 的检出能力都下降，这也是致密型乳腺推荐结合超声或断层摄影的原因。D 胸部 CAD 的假阳性多来自血管断面、肋骨与锁骨交叉影、乳头影、陈旧瘢痕等正常结构；标记数量与系统优劣之间不存在简单关系，评价应采用灵敏度-每图假阳性数（FROC）曲线。E CAD 的经典流程为图像预处理→分割与候选病灶检出→特征提取→分类器判别→假阳性削减→结果标记输出，中间环节不可省略。", "tr": "\"CAD 提高灵敏度的同时增加假阳性、延长阅片时间\"是其双刃剑属性。培训重点不是让医师相信 CAD，而是让医师学会在正确的工作流位置上使用它并识别其典型假阳性模式。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1001", "t": "共用题干题", "s": "结合上述情景，模拟图像与数字图像在特征上的主要差异，正确的描述是", "o": {"A": "模拟图像在时间、空间及密度上都是离散的", "B": "模拟图像的空间与密度（灰度）是连续变化的", "C": "数字图像在空间上是连续的", "D": "数字图像的灰度级数为无限", "E": "模拟图像可直接存储于计算机并随意处理"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-101", "kp": "模拟图像与数字图像的特征", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】模拟图像（如X线胶片、透视荧光影像）的影像信息在空间位置、密度（灰度）上都是连续变化的量，故B正确。\n【为什么错】A：离散性是数字图像的特征，模拟图像是连续的。C：数字图像由离散像素构成，空间上是离散的。D：数字图像灰度级有限，由量化位数决定。E：计算机只能处理数字化后的信息，模拟图像须经A/D转换。", "tr": "“模拟=连续、数字=离散”是最基础考点；模拟图像不能直接入计算机。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06119", "gs": ""}, {"id": "ZG-U06-1002", "t": "共用题干题", "s": "结合上述情景，与传统屏/片系统相比，数字X线成像最重要的优点是", "o": {"A": "无需任何成像设备即可成像", "B": "动态范围宽（曝光宽容度大），可对图像进行后处理并实现存储传输", "C": "空间分辨率高于任何模拟成像系统", "D": "可完全消除受检者辐射剂量", "E": "图像一经生成不能再处理"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-102", "kp": "数字X线成像的优点", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】数字X线成像探测器动态范围宽、曝光宽容度大，可避免曝光不当导致的图像失败，且可进行窗宽窗位、滤波等后处理，并支持存储与传输（PACS），这是其相对屏/片系统的最重要优势。\n【为什么错】A：数字成像同样需要X线机、探测器等设备。C：数字系统空间分辨率受像素大小限制，并不一定高于增感屏-胶片系统。D：任何X线成像都有辐射，无法完全消除。E：数字图像恰恰可进行丰富的后处理。", "tr": "数字成像核心优势=宽容度大＋后处理＋存储传输；勿误认为分辨率更高或零剂量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06117", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1003", "t": "单选题", "s": "关于模拟信号数字化过程的理解，下列叙述正确的是", "o": {"A": "数字化只需量化，无需采样", "B": "采样是对空间位置的离散化，量化是对信号值（灰度/密度）的离散化", "C": "采样与量化是同一概念", "D": "量化后图像仍是连续函数", "E": "数字图像由连续模拟信号直接构成"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-101", "kp": "采样与量化的区别", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】数字化的两个基本环节：采样把空间上连续的模拟信号按间隔离散为像素；量化把每个像素的连续灰度值离散为有限个灰度级，二者分别对“位置”和“信号值”进行离散化。\n【为什么错】A：采样是数字化的前提，不可省略。C：采样针对空间位置、量化针对信号值，概念不同。D：量化后灰度级为有限离散值，不再是连续函数。E：数字图像由采样量化得到的离散数据构成。", "tr": "“采样管位置、量化管数值”口诀；两个环节缺一不可、不可混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1004", "t": "单选题", "s": "数字图像中“像素（pixel）”的定义是", "o": {"A": "构成数字图像的最小基本单元，具有一定的亮度值（像素值）与空间位置", "B": "图像的物理尺寸", "C": "CT扫描的层厚", "D": "探测器的灵敏度", "E": "图像文件的存储容量"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-103", "kp": "像素的定义", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (2)矩阵与像素", "ex": "【为什么对】像素是组成数字图像的最小单元，每个像素既有确定的空间位置，又有一个对应的灰度值（像素值），图像由按矩阵排列的众多像素构成。\n【为什么错】B：图像物理尺寸由FOV或探测器大小决定。C：层厚是断层成像的厚度参数。D：探测器灵敏度是设备性能参数。E：存储容量是文件大小，均与像素定义无关。", "tr": "像素=最小单元（位置＋数值）；勿与层厚、探测器性能、文件大小混同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1005", "t": "共用题干题", "s": "结合上述情景，关于数字图像矩阵与像素的关系，下列叙述正确的是", "o": {"A": "矩阵越大，像素尺寸越大", "B": "矩阵是纵横排列的像素阵列，矩阵越大、像素越小，空间分辨率越高", "C": "矩阵大小与视野（FOV）无关", "D": "减小矩阵可提高空间分辨率", "E": "像素大小等于FOV乘以矩阵"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-104", "kp": "矩阵与像素的关系", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (2)矩阵与像素", "ex": "【为什么对】矩阵为像素的纵横阵列，如512×512表示横向与纵向各512个像素；在FOV不变时矩阵越大、像素越小，能分辨的细节越细，空间分辨率越高。\n【为什么错】A：FOV不变时矩阵越大像素越小而非越大。C：像素大小=FOV/矩阵，二者关系密切。D：减小矩阵使像素增大、空间分辨率下降。E：像素等于FOV除以矩阵，而非相乘。", "tr": "像素=FOV÷矩阵；矩阵↑像素↓分辨率↑；乘除关系勿记反。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06120", "gs": ""}, {"id": "ZG-U06-1006", "t": "共用题干题", "s": "结合上述情景，数字图像的灰度级数由量化位数（bit深度）决定，12位量化可表示的灰度级数为", "o": {"A": "12", "B": "128", "C": "512", "D": "1024", "E": "4096"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-105", "kp": "量化位数与灰度级", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】灰度级数=2的bit次方，12位对应2^12=4096个灰度级，灰度层次越丰富、灰阶显示越细腻。\n【为什么错】A：12是位数本身，不是灰度级数。B：2^7=128为7位。C：2^9=512为9位。D：2^10=1024为10位，均不等于12位的灰度级数。", "tr": "灰度级=2^bit：10bit=1024、12bit=4096、14bit=16384；bit与级数勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06126", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1007", "t": "共用题干题", "s": "结合上述情景，关于数字图像的常用术语，下列叙述正确的是", "o": {"A": "像素值即CT值，恒定不变", "B": "灰度直方图反映图像中像素值（灰度）的分布情况", "C": "调节窗宽窗位会改变像素的原始存储值", "D": "动态范围仅指显示监视器的亮度范围", "E": "空间分辨率与像素大小无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-106", "kp": "数字图像常用术语", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】灰度直方图以横轴为灰度（像素值）、纵轴为频数，反映各灰度级像素的数量分布，是数字图像后处理与窗宽窗位选择的重要依据。\n【为什么错】A：像素值是探测器输出经量化的信号值，CT图像中才换算为CT值（HU），不同组织不同，并非恒定。C：窗宽窗位只改变灰阶的显示映射，不改动原始像素数据。D：动态范围指系统能响应的信号范围（探测器可感受的信号幅度范围），不仅限于监视器亮度。E：空间分辨率与像素大小直接相关，像素越小分辨率越高。", "tr": "直方图=灰度分布统计；窗宽窗位是“显示”映射，不改原始像素值。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06118", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1008", "t": "共用题干题", "s": "结合上述情景，关于采样定理（奈奎斯特定理），下列叙述正确的是", "o": {"A": "采样频率应低于信号最高频率的2倍", "B": "采样频率应大于或等于信号最高频率的2倍，才能无失真地恢复原信号", "C": "采样频率越高，图像越模糊", "D": "采样定理与数字图像无关", "E": "采样间隔越大，空间分辨率越高"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-102", "kp": "采样定理与奈奎斯特频率", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】奈奎斯特定理指出，要从离散采样信号无失真地恢复连续信号，采样频率必须大于或等于信号所含最高频率的2倍，采样间隔需小于等于1/(2倍最高频率)。\n【为什么错】A：低于2倍会出现混叠（失真），不满足采样定理。C：采样频率越高信息还原越充分，图像细节越清晰。D：数字成像的采集环节直接受采样定理约束。E：采样间隔越大可采到的最高空间频率越低，分辨率下降。", "tr": "“采样频率≥2倍最高频率”；采样间隔与可分辨频率成反比，间隔过大产生混叠。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06125", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1009", "t": "单选题", "s": "当采样不足（采样频率低于奈奎斯特频率）时，数字图像将出现", "o": {"A": "灰度反转", "B": "混叠（aliasing）伪影，高频细节以错误低频形式重现", "C": "密度分辨率提高", "D": "量子噪声消失", "E": "对比度增强"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-103", "kp": "采样不足与混叠伪影", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】采样不足时高频信息“折叠”为低频信号叠加在图像上，产生混叠伪影，表现为细密条纹或低频波纹（如衬衣条纹、磨玻璃样纹理），是采样间隔过大或焦点-探测器极限所致。\n【为什么错】A：灰度反转由显示映射或系统非线性引起。C：采样不足不会提高密度分辨率，反而劣化图像。D：量子噪声由光子统计涨落决定，与采样无关。E：对比度由窗宽窗位及组织差异决定，混叠不增强对比。", "tr": "采样不足→混叠；混叠的表现是“高频变低频”，典型见于细条纹摄影。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1010", "t": "共用题干题", "s": "结合上述情景，某DR系统探测器有效成像区域为43 cm×43 cm，若要求像素尺寸约为0.2 mm，所需采集矩阵约为", "o": {"A": "256×256", "B": "512×512", "C": "1024×1024", "D": "2048×2048", "E": "4096×4096"}, "d": "难", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-104", "kp": "矩阵与像素尺寸计算", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】像素尺寸=视野边长÷每边像素数，43 cm=430 mm，430÷0.2=2150，故每边像素数需约2150，最接近且不小于的是2048×2048矩阵（略低于0.2 mm的像素约0.21 mm，需结合系统采样能力选择）。\n【为什么错】A：256×256时像素尺寸约1.68 mm，远大于0.2 mm要求。B：512×512时像素约0.84 mm，仍明显偏大。C：1024×1024时像素约0.42 mm，大于0.2 mm。E：4096×4096时像素约0.105 mm，超出多数探测器固有采样极限，也非“约0.2 mm”的最优选择。", "tr": "像素=边长÷矩阵单边数；计算时统一单位（cm→mm），“最接近且不超系统极限”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06120", "gs": ""}, {"id": "ZG-U06-1011", "t": "共用题干题", "s": "结合上述情景，数字图像形成过程中，“量化”环节所完成的工作是", "o": {"A": "将图像的空间坐标离散化", "B": "将连续的信号幅度（模拟量）离散为有限个灰度级", "C": "提高X线管电流", "D": "放大图像的尺寸", "E": "改变探测器的类型"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-105", "kp": "量化的定义", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (2)量化", "ex": "【为什么对】量化是把采样得到的各像素连续信号幅度（电压/灰度模拟量）按一定级数离散化，赋予整数灰度级（如0~4095），从而形成可存储的数字数据。\n【为什么错】A：空间坐标离散化属于采样环节。C：管电流是X线发生参数，与量化无关。D：图像尺寸放大属后处理。E：探测器类型决定信号采集方式，不是量化内容。", "tr": "“采样管空间位置、量化管信号值”；量化输出为有限个灰度级。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06127", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1012", "t": "共用题干题", "s": "结合上述情景，量化级数（位深）越大，对数字图像质量的影响是", "o": {"A": "灰度层次越丰富、灰阶显示越细腻，但数据存储量增大", "B": "空间分辨率提高", "C": "量子噪声减小", "D": "图像视野缩小", "E": "图像对比度必然提高"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-106", "kp": "量化位深对图像的影响", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (2)量化", "ex": "【为什么对】位深越大灰度级数越多（2^n），图像灰度层次越丰富、过渡越细腻，能更好区分微小密度差异；但每个像素需更多比特存储，数据量随之增大。\n【为什么错】B：空间分辨率由采样（像素大小）决定，与量化位深无关。C：噪声源于光子统计涨落与系统噪声，不随位深改变。D：视野由探测器大小与几何决定。E：对比度由组织差异与显示窗参数决定，位深增大不等于必然提高对比。", "tr": "位深管“灰阶细腻程度”和“存储量”，不直接改变分辨率、噪声与对比度。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06126", "gs": ""}, {"id": "ZG-U06-1013", "t": "单选题", "s": "模拟信号经模数转换（A/D）变为数字信号，主要包括的两个步骤是", "o": {"A": "采样与量化", "B": "仅采样", "C": "仅量化", "D": "编码与压缩", "E": "调制与解调"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-107", "kp": "A/D转换的步骤", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (3)转换", "ex": "【为什么对】模数转换（A/D）由采样（离散化空间/时间）和量化（离散化幅度）两个基本步骤构成，二者缺一不可，之后才得到数字图像数据。\n【为什么错】B：仅采样而未量化不能把信号幅度离散化，无法完成A/D转换。C：仅量化而无采样则没有像素位置信息，同样不完整。D：编码与压缩发生在数字化之后，用于传输与存储。E：调制解调属于信号传输范畴，非A/D转换步骤。", "tr": "A/D转换=采样＋量化；压缩、编码是后续处理，勿混入转换环节。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1014", "t": "共用题干题", "s": "结合上述情景，关于窗口技术（窗宽、窗位），下列叙述正确的是", "o": {"A": "窗宽增大，图像对比度增强", "B": "窗宽决定显示灰阶所对应的CT值范围，窗宽增大使对比度降低；窗位决定显示范围的中心值", "C": "窗位越高，显示的CT值范围越宽", "D": "窗宽窗位不影响图像显示", "E": "窗位总是窗宽的一半"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-101", "kp": "窗口技术的原理", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】窗宽是显示灰阶对应的CT值范围（动态显示范围），窗宽越大单位灰阶对应的CT值跨度越大、对比度越低；窗位（窗中心）是显示范围的中心CT值，决定观察的灰度中心。\n【为什么错】A：窗宽增大使CT值跨度增大，对比度降低而非增强。C：显示范围宽度由窗宽决定，与窗位无关。D：窗宽窗位是CT图像显示的核心参数，直接影响灰度与对比。E：窗位与窗宽无固定比例关系，二者独立调节。", "tr": "窗宽管“范围/对比度”、窗位管“中心位置”；显示范围=窗位±窗宽/2。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06121", "gs": ""}, {"id": "ZG-U06-1015", "t": "共用题干题", "s": "结合上述情景，某CT图像以窗宽400 HU、窗位100 HU显示，其显示的CT值范围（下限~上限）为", "o": {"A": "-200~200 HU", "B": "-100~300 HU", "C": "100~500 HU", "D": "0~400 HU", "E": "-300~100 HU"}, "d": "难", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-102", "kp": "窗宽窗位范围计算", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】显示范围下限=窗位-窗宽/2=100-200=-100 HU，上限=窗位+窗宽/2=100+200=300 HU，故范围为-100~300 HU。\n【为什么错】A：-200~200对应窗位0、窗宽400。C：100~500对应窗位300、窗宽400。D：0~400对应窗位200、窗宽400。E：-300~100对应窗位-100、窗宽400，均与本组窗宽窗位不符。", "tr": "范围=[窗位-窗宽/2, 窗位+窗宽/2]；先算窗宽一半再加减，勿用“窗位±窗宽”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06123", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1016", "t": "共用题干题", "s": "结合上述情景，关于组织均衡（tissue equalization）技术，下列叙述正确的是", "o": {"A": "对探测器欠饱和与过饱和区域的信号进行灰度压缩与均衡，使不同密度组织在同一图像中清晰显示", "B": "仅适用于乳腺X线摄影", "C": "该技术会增加受检者辐射剂量", "D": "组织均衡后高对比组织显示能力下降", "E": "组织均衡与窗宽窗位的作用完全相同"}, "d": "中", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-103", "kp": "组织均衡技术", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (2)组织均衡技术", "ex": "【为什么对】组织均衡利用数字化后处理，对信号过强（过饱和）与过弱（欠饱和）区域的灰度进行压缩补偿，使厚薄不均部位（如胸部肺与纵隔、四肢两端）在同一图像上同时清晰显示。\n【为什么错】B：组织均衡广泛用于胸部、四肢、脊柱等多种部位，并非乳腺专有。C：组织均衡是纯软件处理，不改变曝光条件，不增加剂量。D：组织均衡恰恰是改善高对比组织在两端的显示，而非降低显示能力。E：组织均衡是重建域的后处理，与显示时调节的窗宽窗位机理不同。", "tr": "组织均衡=软件灰度压缩补偿，不增剂量、非乳腺专利、别与窗宽窗位混同。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06124", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1017", "t": "单选题", "s": "关于多平面重组（MPR），下列叙述正确的是", "o": {"A": "在螺旋CT各向同性（近似）采集数据基础上，重建任意方位的二维断面图像", "B": "只能显示组织三维表面", "C": "必须使用表面阴影重建算法", "D": "仅适用于骨骼系统", "E": "MPR不能用于冠状位重建"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-104", "kp": "多平面重组MPR", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】MPR利用螺旋CT容积扫描获得的体素数据，在横断面基础上重建出冠状位、矢状位及任意斜面的二维图像，配合薄层各向同性采集可获得任意方位的清晰断面。\n【为什么错】B：显示三维表面是SSD、VR的功能。C：MPR是体数据重切，不采用表面重建算法。D：MPR适用于全身各部位（颅脑、脊柱、血管等），非骨骼专有。E：冠状位重建是MPR的基本应用之一。", "tr": "MPR=任意方位二维重建，属体素重切技术；SSD/VR才是三维表面/容积显示。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1018", "t": "单选题", "s": "表面阴影显示（SSD）技术最适用于显示", "o": {"A": "血管腔内的对比剂分布", "B": "骨骼表面及骨折块的空间立体形态", "C": "软组织间的密度细微差别", "D": "脑白质纤维束走向", "E": "肺通气功能变化"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-105", "kp": "SSD的临床应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (4)SSD", "ex": "【为什么对】SSD通过设定阈值提取感兴趣结构的表面轮廓并加光照阴影显示，立体感强，最适合显示骨骼表面形态、骨折移位、颅面骨畸形等空间结构关系。\n【为什么错】A：血管腔内对比剂显示多用MIP或VR。C：软组织密度细微差别靠窗宽窗位或MPR观察。D：脑白质纤维束属DTI后处理。E：肺通气功能评价不属于SSD应用。", "tr": "SSD=表面立体显示，强项在骨骼/骨关节三维；血管内腔、软组织细节非其强项。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1019", "t": "共用题干题", "s": "结合上述情景，最大密度投影（MIP）在临床中主要用于显示", "o": {"A": "血管与高密度结构（CTA、MRA）", "B": "软组织低对比结构", "C": "骨皮质内缘细节", "D": "消除血管与骨骼重叠", "E": "管腔内表面纹理"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-106", "kp": "MIP的临床应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】MIP沿某一投影方向取射线上最大体素值进行投影，高密度的增强血管、钙化等结构被突出显示，是CTA、MRA血管成像最常用的后处理方式。\n【为什么错】B：低对比软组织显示需窗技术或MPR，MIP反而会掩盖低密度结构。C：骨皮质内缘细节可用MPR或VR观察。D：MIP不能消除重叠，重叠的高密度结构会相互叠加。E：管腔内表面观察属仿真内镜技术。", "tr": "MIP“取最大值→亮结构显”，血管/钙化强；重叠是其固有局限，低密度结构易被掩盖。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06112", "gs": ""}, {"id": "ZG-U06-1020", "t": "单选题", "s": "容积再现（VR）技术的主要特点是", "o": {"A": "仅显示射线上最大密度体素", "B": "利用全部体素信息，通过透明度、颜色与光照编码三维显示，可同时显示多种组织", "C": "与MIP的成像原理完全相同", "D": "不需要原始容积数据", "E": "只能显示组织表面不能显示内部结构"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-107", "kp": "容积再现VR原理", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】VR对容积数据中每个体素按其密度赋予不同的颜色、透明度和亮度，通过三维投影综合显示，可在同一图像中同时展现骨骼、血管、软组织等多种组织并观察内部结构，立体真实感强。\n【为什么错】A：仅取最大密度是MIP的原理。C：VR与MIP原理不同，VR综合全部体素信息。D：VR必须基于CT/MR等容积数据。E：VR不仅能显示表面，还能通过调节透明度观察内部结构。", "tr": "VR=全体素、多组织、可透视；MIP=最大密度投影；SSD=表面阈值显示，三者原理各异。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1021", "t": "共用题干题", "s": "结合上述情景，CT仿真内镜（CTVE）主要基于下列哪种后处理技术实现", "o": {"A": "最大密度投影（MIP）", "B": "表面阴影显示/容积再现等三维成像结合透视投影模拟腔内飞行观察", "C": "多平面重组（MPR）", "D": "窗宽窗位调节", "E": "组织均衡技术"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-108", "kp": "CT仿真内镜技术", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (7)仿真内镜", "ex": "【为什么对】CT仿真内镜以三维表面重建（SSD）或容积再现数据为基础，用透视投影算法模拟内镜从腔内观察，可漫游观察气管、结肠等空腔脏器内壁。\n【为什么错】A：MIP是投影取最大值，不能模拟腔内飞行观察。C：MPR为二维断面重建，无透视三维漫游。D：窗宽窗位只改变灰度显示。E：组织均衡用于均衡灰度，与腔内漫游无关。", "tr": "仿真内镜=三维重建＋透视投影（模拟漫游）；与MIP、MPR、窗技术的功能区分是关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06111", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1022", "t": "单选题", "s": "调制传递函数（MTF）描述的是成像系统", "o": {"A": "信号幅度（对比度）随空间频率变化的传递能力", "B": "灰度级数", "C": "辐射剂量水平", "D": "视野大小", "E": "图像存储容量"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-101", "kp": "MTF的定义", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】MTF表示系统对不同空间频率信号的对比度（幅度）传递效率，MTF曲线反映成像系统从低频到高频的细节传递能力，是评价空间分辨率最客观的指标。\n【为什么错】B：灰度级数由量化位数决定。C：剂量水平属防护监测指标。D：视野是探测器尺寸参数。E：存储容量是数据量参数，均与MTF无关。", "tr": "MTF=对比度随空间频率的传递函数；MTF越高、高频下坠越晚，系统分辨率越好。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1023", "t": "单选题", "s": "要客观评价两台DR探测器显示微小病灶（高空间频率细节）的能力，最合适的指标是", "o": {"A": "曝光指数", "B": "像素矩阵大小", "C": "调制传递函数（MTF）", "D": "图像灰度直方图", "E": "显示监视器尺寸"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-102", "kp": "MTF评价高分辨能力", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】微小病灶对应高频空间信号，MTF定量反映系统对各空间频率的对比度传递效率，高频段MTF越高说明微小结构显示能力越强，是客观比较探测器空间分辨性能的标准指标。\n【为什么错】A：曝光指数反映剂量水平，与分辨率无关。B：矩阵只是标称参数，实际空间分辨还受探测器孔径、采样等影响，不能直接等同分辨率。D：灰度直方图反映像素值分布，不评价空间分辨。E：监视器尺寸与探测器成像性能无关。", "tr": "评价“细节/高频能力”首选MTF；矩阵、像素只是空间分辨率的“必要条件”而非等效指标。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1024", "t": "共用题干题", "s": "结合上述情景，关于调制传递函数（MTF）的叙述，正确的是", "o": {"A": "MTF值可以大于1", "B": "空间频率越高，MTF值通常越低，即高频细节传递能力下降", "C": "MTF与空间分辨率无关", "D": "MTF等于0时图像最清晰", "E": "MTF只适用于屏/片系统评价"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-103", "kp": "MTF曲线的特征", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】MTF曲线自低频向高频单调（总体）下降，空间频率越高、对比度传递效率越低，高频细节逐渐丢失，MTF=0.5或0.1对应空间频率常作为系统分辨能力的参考点。\n【为什么错】A：MTF为0~1之间的传递效率比值，理想系统在低频等于1，不可能大于1。C：MTF正是定量描述空间分辨率的核心指标。D：MTF=0表示该频率信号完全不能传递，图像模糊，而非最清晰。E：MTF适用于屏/片系统，同样适用于CR、DR、CT、MR等各类成像系统。", "tr": "MTF∈[0,1]且随频率下降；MTF=0.5/0.1处频率代表极限分辨力。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06115", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1025", "t": "单选题", "s": "量子探测效率（DQE）所反映的成像系统性能是", "o": {"A": "系统将入射X线量子有效转换为有用信号的能力，DQE越高，在相同剂量下噪声相对越低", "B": "探测器的视野尺寸", "C": "系统的时间响应能力", "D": "图像文件的压缩率", "E": "监视器的分辨率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-104", "kp": "DQE的含义", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (2)DQE", "ex": "【为什么对】DQE是系统输出信噪比的平方与输入（入射X线）信噪比的平方之比，反映系统有效利用入射量子的效率。DQE越高，同样的剂量下图像噪声越低、信息利用越充分，故DQE高的系统可在较低剂量下获得同等质量图像。\n【为什么错】B：视野是探测器几何参数。C：时间响应（如运动模糊、帧率）非DQE反映内容。D：压缩率是数据存储技术。E：监视器分辨率属显示环节，与探测器DQE无关。", "tr": "DQE=量子利用效率，直接关联“剂量与噪声的平衡”；DQE高→同剂量噪声低或同质量剂量低。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1026", "t": "共用题干题", "s": "结合上述情景，ROC曲线下的面积（AUC）越接近1，表示该诊断系统", "o": {"A": "诊断效能越低", "B": "诊断效能越高，区分病例与正常的能力越强", "C": "图像噪声越大", "D": "所需曝光量越高", "E": "与诊断效能无关"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-105", "kp": "ROC曲线与AUC", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (3)ROC曲线", "ex": "【为什么对】ROC曲线以假阳性率为横轴、真阳性率为纵轴，曲线下面积（AUC）综合反映诊断系统区分正常与异常的能力，AUC越接近1诊断效能越高，AUC=0.5表示无诊断价值。\n【为什么错】A：AUC接近1说明效能高而非低。C：ROC评价的是观察者或系统的判别能力，与图像噪声大小无直接关系。D：ROC与曝光量无必然联系。E：AUC正是诊断效能的量化指标。", "tr": "AUC∈[0.5,1]，越接近1诊断效能越高；0.5=纯随机。ROC属主观评价法。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ06116", "gs": ""}, {"id": "ZG-U06-1027", "t": "单选题", "s": "关于计算机辅助诊断（CAD）的基本定位，下列叙述正确的是", "o": {"A": "完全替代放射科医师独立作出诊断", "B": "利用计算机对图像特征分析，向医师提示可疑病灶，作为“第二阅读者”辅助诊断", "C": "只能用于乳腺X线检查", "D": "主要用于图像压缩存储", "E": "可替代病理学检查"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-101", "kp": "CAD的概念与定位", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (1)概述", "ex": "【为什么对】CAD通过图像分析算法自动检测并标记可疑病灶，其结果由医师复核采纳，起辅助（第二阅读者）作用，可提高检出敏感性、减少漏诊，但不能替代医师作出最终诊断。\n【为什么错】A：CAD定位为辅助而非替代，最终诊断权在医师。C：CAD还用于胸部（肺结节）等多个领域。D：图像压缩是存储技术，非CAD功能。E：CAD是影像学辅助手段，不替代病理检查。", "tr": "CAD=“第二阅读者”辅助，可减漏诊但不替代医师；非乳腺专有。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1028", "t": "单选题", "s": "CAD系统完成病灶自动检测的主要流程顺序是", "o": {"A": "图像采集→图像预处理→可疑区域分割与特征提取→分类判别→输出标记", "B": "直接输出标记，无需图像处理", "C": "分类判别→图像采集→特征提取", "D": "仅提取图像特征，不进行分类", "E": "图像采集后立即打印报告"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-102", "kp": "CAD的基本流程", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (2)基本原理", "ex": "【为什么对】CAD工作流程包括：采集数字图像→预处理（去噪、增强、标准化）→分割并提取可疑区域（候选病灶）→提取形态、密度等特征→用分类器判别真伪→在图像上标记可疑病灶供医师参考。\n【为什么错】B：CAD必须先经图像预处理与特征分析，不能直接输出。C：顺序颠倒，应先采集再处理再分类。D：只提取特征不分类无法给出病灶判别。E：CAD输出的是可疑区域标记，并非直接生成诊断报告。", "tr": "CAD流程“采集→预处理→分割提取→特征→分类→标记”；输出是标记提示而非诊断报告。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1029", "t": "共用题干题", "s": "结合上述情景，关于CAD系统的临床应用特点，下列叙述正确的是", "o": {"A": "CAD对乳腺X线摄影的微钙化簇检测尤为敏感，常作为阅片的辅助工具", "B": "CAD可完全替代医师独立诊断", "C": "CAD检测的假阳性率恒为零", "D": "CAD只能应用于CT图像", "E": "CAD对所有病灶的检出率都达100%"}, "d": "难", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-103", "kp": "CAD临床应用特点", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (2)基本原理", "ex": "【为什么对】CAD算法对乳腺X线图像中微钙化簇、肿块等高对比特征检测灵敏度高，可作为医师阅片的“第二阅读者”，提高乳腺癌筛查检出率、减少漏诊，临床应用最成熟。\n【为什么错】B：CAD是辅助工具，最终诊断由医师作出。C：CAD存在一定假阳性与假阴性，不可能恒为零。D：CAD还广泛用于胸部X线、CT肺结节等领域。E：任何检测方法都不可能100%检出所有病灶。", "tr": "CAD强项=微钙化/结节等高对比目标的“辅助检出”；其假阳性存在、不替代医师。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06108", "gs": ""}, {"id": "ZG-U06-1030", "t": "共用题干题", "s": "结合上述情景，乳腺X线摄影中，CAD系统主要检测标记的对象是", "o": {"A": "可疑肿块与微钙化簇", "B": "骨密度值", "C": "血流灌注参数", "D": "关节间隙宽度", "E": "淋巴结活检定位点"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-104", "kp": "CAD乳腺应用", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (3)乳腺应用", "ex": "【为什么对】乳腺癌X线征象主要是肿块（含伴毛刺、分叶）和微钙化簇，CAD系统针对这两类特征进行检测与标记，辅助医师提高筛查敏感度，是CAD乳腺应用的核心内容。\n【为什么错】B：骨密度由DXA测量。C：血流灌注属MR/CT灌注成像。D：关节间隙测量属骨关节定量。E：淋巴结活检定位由介入操作完成，均非CAD乳腺检测对象。", "tr": "乳腺CAD两大检测对象=肿块＋微钙化簇；其余功能分属不同检查技术。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06109", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1031", "t": "共用题干题", "s": "结合上述情景，胸部X线摄影中，CAD主要用于辅助检测", "o": {"A": "肺结节（肺癌筛查）等肺部病灶", "B": "心包积液量精确测定", "C": "膈肌运动幅度", "D": "支气管分叉角度", "E": "肋间肌厚度"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-105", "kp": "CAD胸部应用", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (4)胸部应用", "ex": "【为什么对】胸片CAD系统主要检测肺内结节性病灶，用于肺癌筛查与体检人群的辅助阅片，可提示可疑结节、减少漏诊，是CAD胸部应用的核心。\n【为什么错】B：心包积液定量多靠超声或MR评估。C：膈肌运动用透视观察。D：支气管分叉角度属气管测量分析，非CAD肺结节检测对象。E：肋间肌厚度测量不属于CAD胸部应用的常规范围。", "tr": "胸片CAD核心=肺结节检测；其他胸内结构定量均有各自专用检查手段。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06110", "gs": ""}, {"id": "ZG-U06-1032", "t": "共用题干题", "s": "结合上述情景，关于数字图像特性与形成过程的综合分析，下列叙述正确的是", "o": {"A": "采样间隔越小，可分辨的空间频率越高，但数据量随之增大", "B": "量化位深越小，灰度层次越丰富", "C": "像素尺寸越大，空间分辨率越高", "D": "混叠伪影的产生与采样频率无关", "E": "数字图像生成后不能进行任何后处理"}, "d": "难", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-107", "kp": "数字图像特性综合分析", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】根据采样定理，采样间隔越小（采样频率越高）可还原的空间频率越高、能分辨的细节越细，但像素数增加、数据量增大，A正确。\n【为什么错】B：位深越小灰度级越少，层次越差。C：像素越大细节分辨能力越差、空间分辨率越低。D：混叠正是采样不足（采样频率过低）引起的。E：数字图像最大的优势之一就是可灵活后处理。", "tr": "“采样间隔小→频率高→细节细→数据大”是一组正相关；位深小、像素大、采样不足均为质量恶化方向。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ06118", "gs": ""}, {"id": "ZG-U06-1033", "t": "共用题干题", "s": "结合上述情景，与传统屏/片成像相比，数字X线成像的特点包括", "o": {"A": "动态范围宽、曝光宽容度大", "B": "可进行丰富的图像后处理", "C": "可实现数字化存储与网络传输", "D": "空间分辨率必然高于增感屏-胶片系统", "E": "曝光条件不当时仍可通过后处理改善显示"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-108", "kp": "数字X线成像的特点", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】数字成像具有动态范围宽、宽容度大、可后处理、可存储传输等优势，曝光条件偏离时仍可经后处理（如窗宽窗位）改善显示，A、B、C、E均正确。\n【为什么错】D：数字系统的空间分辨率受像素尺寸限制，并不必然高于增感屏-胶片系统，后者有较高的极限分辨率。", "tr": "数字成像的优势是“宽容度＋后处理＋传输”，不等于分辨率必然高于屏/片。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06117", "gs": ""}, {"id": "ZG-U06-1034", "t": "共用题干题", "s": "结合上述情景，关于模拟图像与数字图像的区别，下列叙述正确的有", "o": {"A": "模拟图像的空间位置与密度是连续变化的", "B": "数字图像由离散的像素构成", "C": "模拟图像可直接被计算机识别和处理", "D": "数字图像可进行量化压缩与远程传输", "E": "模拟图像与数字图像都是离散量"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-109", "kp": "模拟与数字图像区别", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (1)模拟与数字", "ex": "【为什么对】模拟图像连续、数字图像离散是二者本质区别；数字图像经采样量化后可压缩、存储和远程传输，A、B、D正确。\n【为什么错】C：计算机只能处理数字化信号，模拟图像需先经A/D转换。E：只有数字图像是离散量，模拟图像是连续量。", "tr": "“模拟连续、数字离散”；模拟图像不能直接进计算机，须先数字化。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06119", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1035", "t": "共用题干题", "s": "结合上述情景，关于数字图像常用术语，下列叙述正确的有", "o": {"A": "像素是构成数字图像的最小单元", "B": "矩阵是像素的纵横排列阵列", "C": "量化位深决定图像的灰度级数", "D": "动态范围指成像系统能够响应的信号幅度范围", "E": "像素值恒等于CT值"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-110", "kp": "数字图像术语集合", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (3)数字图像术语", "ex": "【为什么对】像素为最小单元，矩阵为像素阵列，位深决定灰度级数（2^n），动态范围指系统可响应的信号幅度范围，A、B、C、D均正确。\n【为什么错】E：像素值是探测器输出信号经量化的数值，只有在CT中才转换为CT值（HU），不同成像系统含义不同，不能恒等。", "tr": "“像素值”是通用术语，“CT值”是CT专用换算值，二者不恒等。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像的特征", "页": 136}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06118", "gs": ""}, {"id": "ZG-U06-1036", "t": "多选题", "s": "关于数字图像矩阵、像素与视野（FOV）的关系，下列叙述正确的有", "o": {"A": "视野不变时，矩阵增大则像素尺寸减小", "B": "像素尺寸约等于视野边长除以矩阵边长", "C": "矩阵增大可提高空间分辨率", "D": "像素尺寸越大，空间分辨率越高", "E": "矩阵大小与视野大小无关"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-DIG-111", "kp": "矩阵像素FOV关系", "ch": "六、数字X线成像基础 → 1.数字图像特征 → (2)矩阵与像素", "ex": "【为什么对】像素尺寸=FOV÷矩阵，FOV不变时矩阵增大则像素变小、空间分辨率提高，A、B、C正确。\n【为什么错】D：像素越大能分辨的细节越粗，空间分辨率越低。E：像素大小同时取决于FOV与矩阵，二者密切相关。", "tr": "像素=FOV÷矩阵；“矩阵大像素小分辨率高”是主考点。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-1037", "t": "共用题干题", "s": "结合上述情景，关于采样定理与混叠伪影，下列叙述正确的有", "o": {"A": "采样频率应不小于信号最高频率的2倍", "B": "采样不足会引起混叠伪影", "C": "采样间隔越大，可分辨的最高空间频率越低", "D": "混叠时高频信息以错误低频形式重现", "E": "提高采样频率会使图像分辨率下降"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-108", "kp": "采样定理与混叠", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (1)采集", "ex": "【为什么对】奈奎斯特定理要求采样频率≥2倍最高频率；采样不足（间隔过大）时高频成分折叠为低频，产生混叠；采样间隔越大可分辨频率越低，A、B、C、D正确。\n【为什么错】E：提高采样频率可还原更高空间频率、细节更清晰，图像分辨率提高而非下降。", "tr": "采样“频率高→细节好、无混叠”；混叠=高频变低频，识别关键词“折叠”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06125", "gs": ""}, {"id": "ZG-U06-1038", "t": "多选题", "s": "关于量化与量化位深，下列叙述正确的有", "o": {"A": "量化是将连续的模拟量离散为有限个灰度级", "B": "位深由12位增至14位，灰度级由4096增至16384", "C": "位深增大使数据存储量增大", "D": "量化级数越多，灰阶显示越细腻", "E": "量化过程会增加受检者X线剂量"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-109", "kp": "量化与位深", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (2)量化", "ex": "【为什么对】量化离散化信号幅度；灰度级=2^n，12位=4096、14位=16384；位深大则灰度层次细腻、每像素比特数多、数据量大，A、B、C、D正确。\n【为什么错】E：量化是模数转换的软件/电路环节，与X线曝光条件和受检者剂量无关。", "tr": "位深与灰度级换算（2^n）常考；量化不增加剂量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-1039", "t": "多选题", "s": "关于模数转换（A/D转换）环节，下列叙述正确的有", "o": {"A": "A/D转换主要包括采样与量化两个步骤", "B": "采样完成空间位置的离散化", "C": "量化完成信号幅度的离散化", "D": "转换完成后可进行数字图像后处理", "E": "A/D转换会减少图像的灰度级数"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-ACQ-110", "kp": "A/D转换环节", "ch": "六、数字X线成像基础 → 2.数字图像形成 → (3)转换", "ex": "【为什么对】A/D转换由采样（离散化位置）和量化（离散化幅度）两步完成，输出数字数据后即可进行各种后处理，A、B、C、D正确。\n【为什么错】E：A/D转换恰恰把模拟量离散为有限灰度级数（由量化位数决定），是产生灰度级而非“减少”，表述不当。", "tr": "A/D转换=采样＋量化；量化位数决定灰度级数，转换是产生数字图像的基础。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-1040", "t": "共用题干题", "s": "结合上述情景，关于窗口技术（窗宽、窗位）的规律，下列叙述正确的有", "o": {"A": "窗宽决定显示灰阶所对应的CT值范围", "B": "窗位决定显示范围的中心CT值", "C": "窗宽增大时，单位灰阶对应的CT值跨度增大、对比度降低", "D": "显示范围=窗位±窗宽/2", "E": "窗位增大可使显示的CT值范围变宽"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-109", "kp": "窗宽窗位规律", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】窗宽决定显示范围宽度、窗位决定中心；窗宽越大单位灰阶CT值跨度越大、对比度越低；显示上下限为窗位±窗宽/2，A、B、C、D正确。\n【为什么错】E：显示范围宽度只由窗宽决定，窗位只移动窗口位置，不改变范围宽度。", "tr": "窗宽管“宽与对比”，窗位管“中心位置”；范围宽度与窗位无关。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06123", "gs": ""}, {"id": "ZG-U06-1041", "t": "共用题干题", "s": "结合上述情景，关于CT窗宽窗位调节的临床应用，下列叙述正确的有", "o": {"A": "观察肺组织常用肺窗（窗宽较大）", "B": "观察纵隔结构常用纵隔窗（窗宽较窄、窗位居中）", "C": "观察骨骼病变应选用骨窗", "D": "观察肝脏病灶时窗宽可加大至2000 HU以上", "E": "调节窗宽窗位不会改变像素的原始数值"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-110", "kp": "窗宽窗位临床应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】肺窗大窗宽显示肺纹理，纵隔窗窄窗宽显示软组织对比，骨窗显示骨小梁结构；窗宽窗位仅改变灰度显示映射，不修改原始像素数据，A、B、C、E正确。\n【为什么错】D：肝实质与病灶密度差较小，应选用较窄窗宽（通常100~200 HU量级）以增大对比度，窗宽加至2000 HU反而使肝内低对比结构显示不清。", "tr": "“低对比组织（肝、纵隔）用小窗宽”；大窗宽用于肺、骨等对比度大的结构。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06122", "gs": ""}, {"id": "ZG-U06-1042", "t": "多选题", "s": "关于常用三维后处理技术的特点，下列叙述正确的有", "o": {"A": "MPR是在容积数据基础上重建的二维断面图像", "B": "SSD通过阈值提取并显示组织的表面结构", "C": "MIP沿投影方向取最大体素值进行显示", "D": "VR综合利用全部体素信息进行三维显示", "E": "MIP可以直接显示软组织中的低密度病变"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-111", "kp": "三维后处理技术对比", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】MPR为二维重切、SSD为表面阈值显示、MIP取最大密度投影、VR利用全体素信息并赋以透明度颜色显示，A、B、C、D分别准确描述了四种技术。\n【为什么错】E：MIP显示的是投影方向上的最大密度，会掩盖低密度软组织病变，低对比结构观察应选MPR或窗技术。", "tr": "四种后处理“谁看什么”：MPR断面、SSD表面、MIP最大密度、VR容积透视。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-1043", "t": "多选题", "s": "关于最大密度投影（MIP）的临床应用，下列叙述正确的有", "o": {"A": "常用于显示CTA的增强血管", "B": "可用于显示钙化等高密度结构", "C": "可直接观察低密度软组织病变", "D": "血管重叠明显时可采用旋转投影或多角度薄层MIP改善", "E": "MIP能自动消除血管与骨骼的重叠"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-112", "kp": "MIP临床应用与局限", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】MIP对高密度结构（增强血管、钙化）显示良好，是CTA常用后处理；重叠时可用旋转多角度投影或薄层MIP减少结构重叠、定位病灶，A、B、D正确。\n【为什么错】C：MIP取最大密度会掩盖低密度软组织病变。E：MIP不能消除重叠，高密度结构会相互叠加，需靠旋转或薄层技术改善。", "tr": "MIP“亮结构强、低密度被掩盖、重叠无法自动消除”；薄层MIP/旋转投影是补救手段。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-1044", "t": "共用题干题", "s": "结合上述情景，关于MTF、DQE与ROC三种评价指标，下列叙述正确的有", "o": {"A": "MTF用于评价成像系统的空间分辨（对比度传递）能力", "B": "DQE用于评价系统对入射X线量子的利用效率", "C": "ROC曲线用于评价观察者或系统的诊断效能", "D": "MTF数值越高，表示系统细节显示能力越好", "E": "DQE越高，达到同样图像质量所需的曝光量越大"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-106", "kp": "MTF DQE ROC概念辨析", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】MTF评价空间分辨（对比度随频率传递）、DQE评价量子利用效率、ROC评价诊断效能，三者定位清晰；MTF越高细节传递越好，A、B、C、D正确。\n【为什么错】E：DQE越高表示量子利用效率越高，达到同等图像质量所需剂量越低，方向恰好相反。", "tr": "“MTF管分辨率、DQE管剂量效率、ROC管诊断效能”；DQE高→剂量低。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06114", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1045", "t": "共用题干题", "s": "结合上述情景，调制传递函数（MTF）用于客观评价成像系统，下列关于其特点的叙述，正确的有", "o": {"A": "MTF的取值范围在0~1之间", "B": "空间频率越高，MTF通常越低", "C": "MTF等于0.1时所对应的空间频率可作为极限分辨力参考", "D": "MTF反映系统对不同空间频率信号的对比度传递效率", "E": "MTF只反映图像噪声水平"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-107", "kp": "MTF特征", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】MTF为0~1的对比度传递效率，低频高、高频低；MTF=0.1或0.5对应频率常作为系统分辨力参考值，A、B、C、D正确。\n【为什么错】E：MTF描述对比度随空间频率的传递，与噪声无直接关系，噪声由NPS等指标评价。", "tr": "MTF≠噪声指标；MTF=0.1处频率≈系统极限分辨力（10%对比度传递）。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06115", "gs": ""}, {"id": "ZG-U06-1046", "t": "共用题干题", "s": "结合上述情景，关于ROC曲线分析，下列叙述正确的有", "o": {"A": "ROC曲线以假阳性率为横轴", "B": "ROC曲线以真阳性率为纵轴", "C": "曲线下面积（AUC）越接近1，诊断效能越高", "D": "ROC分析属于影像质量的主观（心理学）评价法", "E": "AUC等于0.5表示诊断效能最高"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-108", "kp": "ROC曲线特征", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (3)ROC曲线", "ex": "【为什么对】ROC以假阳性率（横）对真阳性率（纵）绘制，AUC反映诊断系统区分能力，越接近1效能越高；ROC依赖观察者对图像信号作判断，属主观评价法，A、B、C、D正确。\n【为什么错】E：AUC=0.5表示诊断能力等同于随机猜测，诊断效能最低；越接近1才越高。", "tr": "AUC=0.5=无诊断价值；ROC属主观评价，勿归入客观物理评价。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ06116", "gs": ""}, {"id": "ZG-U06-1047", "t": "多选题", "s": "关于量子探测效率（DQE），下列叙述正确的有", "o": {"A": "DQE反映系统有效利用入射X线量子的效率", "B": "DQE越高，在相同剂量下图像噪声越低", "C": "DQE受探测器材料、结构与成像链设计的影响", "D": "DQE高的系统可在较低剂量下获得同等质量的图像", "E": "DQE只取决于显示监视器的性能"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-109", "kp": "DQE特性", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (2)DQE", "ex": "【为什么对】DQE=输出信噪比平方/输入信噪比平方，反映量子利用效率，受探测器材料、结构与成像链影响；DQE高意味着同剂量下噪声低、可在低剂量下保证图像质量，A、B、C、D正确。\n【为什么错】E：DQE是探测器与成像链的性能指标，与显示监视器无关。", "tr": "DQE是“探测器层”指标；DQE高→可降剂量保质量，勿与显示设备混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U06-1048", "t": "共用题干题", "s": "结合上述情景，关于计算机辅助诊断（CAD）的应用，下列叙述正确的有", "o": {"A": "CAD作为“第二阅读者”辅助放射科医师诊断", "B": "CAD可用于乳腺X线摄影中微钙化簇与肿块的检测", "C": "CAD可用于胸部X线摄影肺结节的辅助检出", "D": "CAD存在一定的假阳性和假阴性，需医师复核确认", "E": "CAD检测到病灶即可直接确诊，无需医师判断"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-106", "kp": "CAD综合应用", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (1)概述", "ex": "【为什么对】CAD定位为辅助（第二阅读者），在乳腺（微钙化、肿块）与胸部（肺结节）等领域应用成熟，可提高检出敏感性；但其输出存在假阳/假阴，最终由医师复核确认，A、B、C、D正确。\n【为什么错】E：CAD不能替代医师作出确诊，其提示必须经医师结合临床与其他检查综合判断。", "tr": "CAD=辅助提示、可减漏诊、有假阳性、不替代诊断；这是CAD考点的四条主线。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ06110", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1049", "t": "共用题干题", "s": "结合上述情景，关于组织均衡技术，下列叙述正确的有", "o": {"A": "对探测器信号过饱和与欠饱和区域的灰度进行压缩补偿", "B": "适用于胸部、四肢等厚薄差异较大的部位", "C": "属于数字图像后处理，不增加受检者剂量", "D": "可使不同密度组织在同一图像中清晰显示", "E": "属于X线发生环节的参数调节技术"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-113", "kp": "组织均衡技术", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (2)组织均衡技术", "ex": "【为什么对】组织均衡压缩补偿过饱和/欠饱和区灰度，使厚薄差异大部位（胸部肺与纵隔、四肢）不同密度组织同图清晰显示，属纯软件后处理、不增加剂量，A、B、C、D正确。\n【为什么错】E：组织均衡是图像后处理环节，与X线球管、kV/mAs等发生参数无关。", "tr": "组织均衡“软件后处理、不增剂量、均衡灰度”；别与X线发生条件混为一谈。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ06124", "gs": ""}, {"id": "ZG-U06-1050a", "t": "单选题", "s": "【病例】患者男，52岁，因外伤致腰椎压缩性骨折，临床拟行腰椎CT检查以明确椎体骨折范围及椎管受累情况。设备为64层螺旋CT，技师采用薄层扫描并拟行多平面重组（MPR）后处理辅助诊断。 MPR重建所得到的主要图像类型是", "o": {"A": "任意方位的二维断面图像", "B": "三维表面阴影图像", "C": "最大密度投影图像", "D": "容积再现图像", "E": "仿真内镜图像"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-114", "kp": "MPR的图像类型", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】MPR是在容积扫描体数据基础上，通过体素重切获得任意方位（冠状、矢状、斜面、曲面）的二维断面图像，是三种基本后处理中唯一的二维断面重建技术。\n【为什么错】B：三维表面阴影是SSD的功能。C：最大密度投影是MIP。D：容积再现有三维容积显示。E：仿真内镜模拟腔内漫游，均非MPR输出。", "tr": "MPR=二维断面重切；三维显示交给SSD/VR，最大密度交给MIP。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1050b", "t": "单选题", "s": "要获得质量良好的冠状位、矢状位MPR图像，关键前提是", "o": {"A": "增大扫描螺距", "B": "采用薄层扫描，使体素在各方向近似各向同性（等方性）", "C": "加大窗宽窗位", "D": "使用高浓度对比剂", "E": "尽量缩短扫描时间"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-115", "kp": "MPR与各向同性采集", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】MPR重建图像的清晰度取决于原始体素是否各向同性，薄层扫描使层面内与层厚方向体素大小接近，任意方位重建均无锯齿失真，故薄层是MPR质量的关键。\n【为什么错】A：螺距影响覆盖速度与噪声，不是MPR质量关键。C：窗宽窗位只影响显示，不影响重建质量。D：对比剂用于血管观察，与本例骨结构重组无关。E：缩短扫描时间不改善重建分辨率。", "tr": "“薄层各向同性”是MPR质量的前提；螺距、窗宽、对比剂均非关键。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1050c", "t": "共用题干题", "s": "结合上述情景，为重点观察椎管内有无骨块突入及椎体后缘骨折线，最合适的后处理是", "o": {"A": "采用薄层矢状位与冠状位MPR显示椎管及椎体后缘", "B": "仅观察横断面原始图像", "C": "使用SSD三维表面重建", "D": "仅使用MIP投影", "E": "只进行仿真内镜观察"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-116", "kp": "MPR显示椎管骨折", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】椎管内骨块突入与椎体后缘骨折线需在矢状位、冠状位等断面图像上清晰显示解剖关系，薄层MPR沿椎管长轴重切可直观显示骨块与椎管的位置关系，是首选。\n【为什么错】B：横断面图像对椎管长轴方向的骨块范围显示有限。C：SSD为表面重建，无法观察椎管内断面细节。D：MIP取最大密度，椎管内容易被周围高密度骨掩盖。E：仿真内镜适用于空腔脏器腔内观察，不用于椎管骨块评估。", "tr": "“看椎管/骨折线”选MPR断面；三维表面与MIP均不适合椎管内细节观察。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06113", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1051a", "t": "单选题", "s": "【病例】患者男，58岁，因反复咯血伴痰中带血丝3个月，临床疑支气管动脉供血异常，行胸部CT增强扫描。扫描采用薄层增强采集，技师拟行最大密度投影（MIP）后处理，以观察异常供血动脉的走行、开口位置及与病灶的关系，为选择性支气管动脉造影与栓塞治疗提供依据。 MIP成像的基本原理是", "o": {"A": "沿投影方向取射线上体素的最大值进行投影显示", "B": "取射线上体素的平均值进行显示", "C": "提取组织表面并加光照阴影显示", "D": "对体素进行透明度与颜色编码后三维显示", "E": "重建任意方位的断面图像"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-117", "kp": "MIP成像原理", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】MIP沿设定投影方向对每个像素所穿过的体素取最大CT值进行投影，突出显示增强血管、钙化等高密度结构。\n【为什么错】B：取平均值是平均密度投影（AIP/MinIP反之取最小）。C：加光照显示表面是SSD。D：透明度颜色编码是VR。E：任意断面重建是MPR。", "tr": "MIP“取最大”、MinIP“取最小”、SSD“表面光照”、VR“全体素透明”；四者原理分明。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1051b", "t": "共用题干题", "s": "结合上述情景，为清晰显示支气管动脉全程及其分支走行，最适合的后处理方式是", "o": {"A": "薄层MIP结合多角度旋转投影观察血管全程", "B": "只观察横断面原始图像", "C": "仅调节窗宽窗位", "D": "将层厚增大至10 mm后再投影", "E": "仅使用SSD表面重建"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-118", "kp": "MIP显示血管的应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】支气管动脉细小且走行曲折，薄层MIP可减少重叠、突出血管；多角度旋转投影可从不同方向观察血管全程与分支，是显示小血管的常用组合。\n【为什么错】B：单张横断面不能显示血管全程走行。C：窗宽窗位只改变灰度显示。D：厚层MIP使细小血管被周围结构平均化、显示不清。E：SSD表面重建对细小血管的显示不如MIP。", "tr": "“小血管全程”=薄层MIP＋旋转投影；厚层MIP反而丢失小血管细节。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06112", "gs": "关于数字X线成像基础与图像处理，下列说法正确的是。"}, {"id": "ZG-U06-1051c", "t": "单选题", "s": "若MIP图像上支气管动脉与肋间动脉、椎体骨质重叠明显，干扰判断，下列处理最恰当的是", "o": {"A": "采用薄层MIP限定兴趣区范围，并结合MPR、VR等综合观察", "B": "增大对比剂注射总量", "C": "加大窗宽窗位", "D": "更换扫描探测器", "E": "放弃血管观察"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-119", "kp": "MIP重叠的处理", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】MIP沿投影方向所有高密度结构相互叠加，重叠明显时可用薄层MIP（减小投影层厚）或限定兴趣区（VOI）剔除无关高密度结构，再配合MPR确认解剖关系、VR观察空间形态，多技术综合是正确处理。\n【为什么错】B：对比剂用量增加不解决骨骼重叠。C：窗宽窗位不能分离重叠的高密度结构。D：探测器更换与实际后处理无关。E：放弃观察不符合诊断需要。", "tr": "MIP重叠解决思路“薄层+兴趣区限定+多技术互补”；靠剂量、窗宽、换设备均无效。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1052a", "t": "单选题", "s": "【病例】患者男，35岁，因车祸致骨盆多发骨折伴骶髂关节分离，临床拟行骨盆CT检查并行三维重建，以整体评估骨折块移位方向与旋转畸形、骶髂关节受累程度，为制定手术入路与内固定方案提供参考。 关于容积再现（VR）三维重建的特点，下列叙述正确的是", "o": {"A": "对每个体素按密度赋予透明度与颜色，可同时显示骨、血管、软组织等多种组织", "B": "VR仅显示投影方向上的最大密度体素", "C": "VR只显示组织表面，不显示内部结构", "D": "VR属于二维断面重建", "E": "VR不需要容积扫描数据"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-120", "kp": "VR重建原理与特点", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】VR对容积数据中每个体素根据其密度值赋予不同的透明度、颜色与亮度，经三维投影可同时显示多种组织，并可通过调节透明度观察内部结构，立体真实感强。\n【为什么错】B：取最大密度是MIP原理。C：VR可调节透明度显示内部结构，不仅显示表面。D：VR是三维容积显示，不是二维断面。E：VR必须基于CT/MR等容积扫描数据。", "tr": "VR=“全体素透明着色”，多组织同显可透视；MIP/SSD分别只取最大密度/表面。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1052b", "t": "单选题", "s": "为同时显示骨盆骨折整体形态与盆腔血管关系，最适合的后处理方案是", "o": {"A": "VR三维重建（骨骼与血管分别赋予不同透明度与颜色）并配合MIP观察血管", "B": "仅用SSD表面重建", "C": "仅用MPR断面", "D": "仅调节窗宽窗位", "E": "仅做仿真内镜"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-121", "kp": "VR的临床应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】VR可对骨与血管设定不同阈值和透明度、颜色，在同一三维图像中同时显示骨骼骨折与血管走行；MIP可作为补充突出血管细节，二者结合适合创伤并发出血血管评估。\n【为什么错】B：SSD仅显示表面，不能同时显示血管内部结构关系。C：MPR是断面图像，缺乏整体三维观感。D：窗宽窗位不能实现三维立体显示。E：仿真内镜用于空腔脏器腔内观察，不适合骨盆骨折评估。", "tr": "VR的强项=“骨＋血管多组织同图”；MIP补血管细节，SSD只做表面，二者不能替代。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1052c", "t": "单选题", "s": "与SSD相比，VR在显示复杂粉碎性骨折方面的主要优势是", "o": {"A": "利用全部体素信息、可调节透明度显示内部结构，受阈值选择影响小、信息丢失少", "B": "VR成像速度比SSD更快", "C": "VR无需原始容积数据", "D": "VR只能显示骨骼组织", "E": "VR的空间分辨率必然高于SSD"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-122", "kp": "VR与SSD的比较", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】SSD靠单一阈值提取表面，阈值选择不当会丢失或误增表面信息；VR利用全部体素信息并可通过调节透明度保留内部细节，在复杂骨折、多组织显示中信息保留更完整、伪影更少。\n【为什么错】B：VR计算量大，速度通常不优于SSD。C：VR同样需要容积数据。D：VR可显示骨、血管、软组织等多种组织。E：VR与SSD的空间分辨率均取决于原始数据，VR并非必然更高。", "tr": "VR强于SSD的本质是“全体素、可调透明度、不依赖单一阈值”；“速度/分辨率必高”是错误表述。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1053a", "t": "共用题干题", "s": "结合上述情景，CTVE成像所依赖的主要技术是", "o": {"A": "三维表面/容积重建结合透视投影模拟腔内飞行观察", "B": "最大密度投影", "C": "多平面重组", "D": "窗宽窗位调节", "E": "组织均衡技术"}, "d": "易", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-123", "kp": "CT仿真内镜技术基础", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (7)仿真内镜", "ex": "【为什么对】CTVE以三维重建（SSD或VR）数据为基础，采用透视投影算法模拟内镜镜头从空腔脏器内部飞行观察，实现“虚拟内镜”浏览。\n【为什么错】B：MIP是最大密度投影，不能模拟腔内漫游。C：MPR为二维断面重建。D：窗宽窗位只改变灰度显示。E：组织均衡用于灰度均衡，与腔内漫游无关。", "tr": "仿真内镜=三维重建＋透视投影＋腔内漫游；不是MIP/MPR/窗技术的功能。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06111", "gs": ""}, {"id": "ZG-U06-1053b", "t": "单选题", "s": "关于CTVE在结肠病变评估中的临床应用特点，下列叙述正确的是", "o": {"A": "属无创检查，可越过结肠镜无法通过的狭窄段观察远侧肠腔，但不能观察黏膜色泽、不能行组织活检", "B": "CTVE可直接替代纤维结肠镜进行组织活检", "C": "CTVE可分辨黏膜颜色和血管纹理", "D": "CTVE无法用于结肠检查", "E": "CTVE对任何大小的息肉均可100%检出"}, "d": "难", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-124", "kp": "CTVE的临床应用特点", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (7)仿真内镜", "ex": "【为什么对】CTVE无创、不需插入内镜，可观察狭窄段远侧肠腔，弥补结肠镜不足；但CTVE基于CT密度成像，不能观察黏膜真实色泽，也不能进行活检和息肉切除，需与纤维内镜互补，A正确。\n【为什么错】B：CTVE不能取材活检，无法替代纤维内镜。C：CTVE无颜色信息，不能分辨黏膜色泽与血管纹理。D：CTVE在结肠息肉、狭窄评估中应用广泛。E：CTVE对小息肉存在漏检，检出率不可能100%。", "tr": "CTVE优点=无创+过狭窄段；缺点=无颜色、无活检；与纤维内镜是“互补”而非“替代”。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1054", "t": "共用题干题", "s": "结合上述情景，患者男，40岁，车祸致多发伤后行胸部CT平扫，临床需同时观察肺实质挫伤范围、胸腔积血情况以及多发肋骨骨折的位置与错位程度。因肺组织与骨组织密度差异悬殊，单一显示条件无法兼顾，技师拟通过调节窗宽、窗位分别观察不同结构，以兼顾肺实质、纵隔与骨性胸廓的诊断需要。请为该患者的胸部CT选择合理的窗技术显示方案。", "o": {"A": "观察肺实质采用大窗宽的肺窗，观察肋骨骨折采用骨窗", "B": "全部结构均用同一窗宽窗位显示", "C": "观察肺实质时窗宽应小于100 HU", "D": "观察肋骨骨折时窗宽应大于2000 HU", "E": "调节窗宽窗位会改变像素的原始数值"}, "d": "易", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-125", "kp": "窗宽窗位综合应用", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】肺实质内含大量气体、密度对比大，用大窗宽肺窗（窗宽约1500 HU、窗位约-600 HU）显示肺纹理与挫伤；肋骨为高密度骨组织，用骨窗（窗宽约1000~1500 HU、窗位约300 HU）显示骨皮质与骨折线，不同结构需采用不同窗设置。\n【为什么错】B：肺、骨组织密度差异巨大，同一窗宽窗位无法同时最佳显示。C：肺窗窗宽通常上千HU，小于100 HU无法显示肺内密度跨度。D：骨窗窗宽一般1000~1500 HU，超过2000 HU会使骨折线对比度不足。E：窗宽窗位只改变灰阶显示映射，不改变原始像素数值。", "tr": "“肺窗大窗宽、骨窗适中、纵隔窗小窗宽”；调窗不改原始像素值是常考细节。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06122", "gs": ""}, {"id": "ZG-U06-1055", "t": "共用题干题", "s": "结合上述情景，患者女，28岁，外伤后右足疼痛、不能负重，临床疑距骨骨折，行足踝CT薄层平扫，扫描层厚0.625 mm，横断面图像上距骨可见可疑骨折线，但因断端无明显错位，骨折线在横断面上显示不清，难以准确判断骨折是否存在及其范围，且对后续负重行走与治疗方案影响重大。技师拟通过CT后处理技术辅助诊断，请选择最适宜的重建方法，并简要说明其原理。", "o": {"A": "沿骨折线走行进行薄层多平面重组（MPR）观察", "B": "增大层厚重新扫描", "C": "仅依靠横断面原始图像判断", "D": "用MIP观察低密度骨折线", "E": "不做后处理直接报告"}, "d": "易", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-126", "kp": "MPR显示隐匿骨折", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (3)MPR", "ex": "【为什么对】距骨等不规则骨骨折线常不与横断面平行，横断面上显示不清。薄层MPR沿骨折线走行方向（矢状位、冠状位或斜面）重切，可清晰显示骨折线与骨折范围，是判定隐匿骨折的常用手段。\n【为什么错】B：增大层厚加重部分容积效应，骨折线更易被掩盖。C：横断面信息不足时应借助后处理而非强判。D：MIP取最大密度，低密度骨折线反而被周围高密度骨掩盖，不适合。E：不做后处理可能漏诊骨折。", "tr": "“隐匿骨折、骨折线不清”首推薄层MPR沿骨折线重切；MIP掩盖低密度线影，勿误选。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ06113", "gs": ""}, {"id": "ZG-U06-1056", "t": "案例分析题", "s": "患者男，55岁，体检行胸部DR检查，采用站立后前位摄影。由于胸部结构密度差异大，图像上肺野外带过度曝光（偏白），纵隔与心影后方区域曝光不足（偏黑），肺野与纵隔结构无法在同一幅图像上同时清晰显示，影响双肺、纵隔及心影后方病变的观察，需二次曝光才能满足诊断。影像科拟通过数字图像处理技术改善一次成像中肺野与纵隔的显示效果，请选择最合适的处理方法。", "o": {"A": "该现象属正常，无需处理", "B": "可使用组织均衡技术对过饱和与欠饱和区域灰度进行压缩补偿，使肺野与纵隔同时清晰显示", "C": "需加大曝光量重新投照", "D": "组织均衡处理会增加受检者辐射剂量", "E": "纵隔区域显示不清与图像处理无关"}, "d": "中", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-127", "kp": "组织均衡改善胸部DR显示", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (2)组织均衡技术", "ex": "【为什么对】胸部肺（高透亮）与纵隔（高密度）厚度与密度差异大，超出单一灰阶同时显示能力。组织均衡技术对探测器过饱和（肺野）与欠饱和（纵隔）区域信号进行灰度压缩补偿，使两者在同一图像上清晰显示，正是解决该问题的专用技术。\n【为什么错】A：该现象反映动态显示范围不足，可通过后处理改善，并非不需处理。C：加大曝光会改善纵隔但使肺野更过曝，不能两全。D：组织均衡是纯软件处理，不改变曝光条件、不增加剂量。E：纵隔显示改善正依赖图像后处理。", "tr": "组织均衡专治“厚薄差异大、两区难以同显”；是软件处理、不加剂量。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1057", "t": "案例分析题", "s": "患者女，60岁，因突发剧烈头痛伴恶心、呕吐急诊就诊，临床高度疑蛛网膜下腔出血，行头颈联合CTA检查，采用自动管电流调节技术，原始薄层增强图像已采集完成。技师拟通过后处理技术整体观察颅内动脉主干及分支的走行、有无动脉瘤及其瘤颈方向与空间形态，为介入栓塞治疗提供解剖依据。请选择最适宜的后处理显示方法，并说明其优缺点。", "o": {"A": "采用MIP多角度旋转投影显示血管全程，并结合VR观察动脉瘤立体形态", "B": "仅使用SSD表面重建", "C": "仅调节窗宽窗位显示", "D": "仅用MPR断面即能完全替代MIP与VR", "E": "无需任何后处理"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-128", "kp": "MIP与VR显示脑血管", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (5)MIP", "ex": "【为什么对】CTA血管观察常规采用MIP多角度旋转投影显示血管走行与分支，再用VR三维显示观察动脉瘤与载瘤动脉的空间关系、瘤颈形态，MIP+VR联合是CTA后处理的标准组合。\n【为什么错】B：SSD表面重建对细小血管与瘤颈显示不如MIP/VR。C：窗宽窗位只改变灰度，无三维血管显示。D：MPR为断面图像，不能提供血管整体三维形态，不能完全替代。E：不作后处理难以整体评估血管。", "tr": "CTA标配“MIP看走行＋VR看形态”；SSD、MPR、窗技术均不能替代。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1058", "t": "案例分析题", "s": "患者男，30岁，高处坠落致骨盆粉碎性骨折伴出血性休克，经补液输血等抢救后生命体征平稳，待择期手术。术前临床需整体评估骨折块移位方向、旋转畸形及骶髂关节受累情况，以设计手术入路与内固定方案。骨盆CT薄层扫描已完成，技师拟行三维重建，请选择最适宜的后处理显示技术并说明其特点，同时指出该技术用于骨盆骨折评估时的局限性。", "o": {"A": "采用VR三维重建结合旋转观察，直观显示骨折整体形态与移位关系", "B": "仅观察横断面图像即可满足需求", "C": "用MIP评估骨皮质连续性即可", "D": "用仿真内镜观察骨折面", "E": "仅加大窗宽窗位"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-129", "kp": "VR评估复杂骨折", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (6)VR", "ex": "【为什么对】复杂粉碎性骨折需要整体三维观感来评估骨折块的空间移位、旋转畸形，VR利用全部体素信息、可调节透明度与颜色，直观显示骨折全貌与关节关系，配合旋转观察效果最佳，是骨科术前评估的标准后处理。\n【为什么错】B：横断面难以提供骨折块空间移位的整体观感。C：MIP取最大密度，对骨折形态显示不直观。D：仿真内镜用于空腔脏器腔内观察，不适合骨折面评估。E：窗宽窗位无法实现三维立体显示。", "tr": "复杂骨折三维评估首选VR；MIP/SSD各有局限，仿真内镜不用于骨折。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1059", "t": "案例分析题", "s": "患者男，62岁，因便血伴排便习惯改变3个月行结肠CT检查，发现降结肠管腔明显狭窄，纤维结肠镜因狭窄未能通过，无法评估狭窄远侧肠腔情况。临床拟行CT仿真结肠内镜（CTVE）评估狭窄段形态、长度及其远侧肠腔内有无占位性病变，为手术治疗与随访提供依据。请分析CTVE检查中需要重点关注的操作要点与注意事项。", "o": {"A": "采用CTVE结合MPR观察狭窄段及远侧肠腔，必要时以横断面核实", "B": "CTVE可替代病理活检明确病灶性质", "C": "CTVE可观察黏膜真实色泽", "D": "CTVE需要经肛插入内镜器械", "E": "狭窄段远侧肠腔无法通过CTVE观察"}, "d": "中", "c": "应用", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-130", "kp": "CTVE评估结肠狭窄", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (7)仿真内镜", "ex": "【为什么对】CTVE无创且不受肠腔狭窄限制，可模拟内镜越过狭窄段观察远侧肠腔，配合MPR、横断面图像核实病变位置与肠壁情况，是结肠镜受阻时的有效补充手段。\n【为什么错】B：CTVE不能取材活检，不能替代病理检查明确性质。C：CTVE基于CT密度，无黏膜颜色信息。D：CTVE无需插入内镜，是纯影像后处理。E：CTVE的优势恰恰是可越过狭窄段观察远侧肠腔。", "tr": "CTVE“过狭窄段＋无创”是优势，“无颜色、无活检”是局限；需配合断面图像核实。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1060", "t": "案例分析题", "s": "患儿男，8岁，头部外伤后行头颅CT平扫，横断面图像显示额部凹陷性骨折，但骨折范围、凹陷深度及碎片移位情况在横断面上显示欠全面，临床难以据此判断手术指征。临床拟行颅骨三维重建以观察骨折的范围与深度，决定是否手术整复。颅脑CT薄层扫描已完成，技师拟进行后处理，请选择最适宜的三维显示技术并说明其成像特点。", "o": {"A": "采用SSD三维表面重建直观显示颅骨表面形态与凹陷范围", "B": "SSD可同时显示颅内软组织损伤", "C": "SSD使用平均密度投影原理", "D": "SSD主要用于显示血管腔内结构", "E": "SSD的分辨率必然低于横断面原始图像"}, "d": "中", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-131", "kp": "SSD显示颅骨骨折", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (4)SSD", "ex": "【为什么对】颅骨骨折评估需要观察骨表面形态与凹陷范围，SSD通过设定骨阈值提取颅骨表面并加光照阴影，立体显示表面轮廓与凹陷形态，是颅面骨三维重建的经典应用。\n【为什么错】B：SSD阈值分割只显示目标表面结构，不显示颅内软组织。C：SSD是表面阈值提取加光照显示，不是平均密度投影。D：血管腔内显示用MIP/VR或仿真内镜，SSD不用于血管腔。E：SSD的分辨率取决于原始数据，用于表面形态观察有其价值，并非必然低于横断面。", "tr": "SSD=骨表面三维，看颅面骨/关节面；颅内软组织与血管腔不是它的作用对象。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像处理", "页": 139}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-1061", "t": "共用题干题", "s": "结合上述情景，某医院放射科拟为设备采购与人员培训提供依据，比较两套DR系统的微小病变显示能力，并评估诊断医师的阅片效能。科室计划从设备物理性能与观察者诊断水平两个层面开展系统评价，前者反映探测器分辨细节的客观物理能力，后者反映医师应用该设备实际检出病变的真实水平，二者评价角度不同、指标各异。请选择适合两个层面的评价指标与方法。", "o": {"A": "用MTF比较两系统的高频细节传递能力，用ROC曲线评估阅片诊断效能", "B": "仅比较显示监视器的尺寸", "C": "用曝光指数比较空间分辨率", "D": "用灰度直方图比较系统分辨率", "E": "用AUC数值代替MTF比较空间分辨率"}, "d": "难", "c": "理解", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-EVA-110", "kp": "MTF与ROC的选择应用", "ch": "六、数字X线成像基础 → 4.数字图像评价 → (1)MTF", "ex": "【为什么对】比较系统微小病变（高频细节）显示能力应选用客观物理指标MTF；评估观察者/医师诊断效能应选用ROC曲线（AUC），二者分别从“设备性能”与“诊断水平”两个层面回答该问题，选择正确。\n【为什么错】B：监视器尺寸是显示参数，不代表系统成像性能。C：曝光指数反映剂量水平，与空间分辨率无关。D：灰度直方图反映像素值分布，不评价空间分辨能力。E：AUC是ROC的诊断效能指标，不能代替MTF评价空间分辨率。", "tr": "“设备分辨率”用MTF、“阅片效能”用ROC；AUC≠MTF，指标用途勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "数字图像评价", "页": 141}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ06114", "gs": ""}, {"id": "ZG-U06-1062", "t": "共用题干题", "s": "结合上述情景，患者女，50岁，乳腺X线筛查发现右乳外上象限成簇状微小钙化，形态欠规则、分布较散在，需与良性钙化鉴别，同时该区域未见明确肿块影。放射科医师拟启用计算机辅助诊断（CAD）系统辅助阅片，以提高微小钙化簇与肿块检出的敏感性、减少漏诊，同时需要警惕CAD提示的假阳性结果。请分析CAD系统在该例乳腺X线阅片中的正确应用方式。", "o": {"A": "CAD可自动标记可疑微钙化簇与肿块，供医师复核，提高检出敏感度", "B": "CAD可直接确定微钙化的良恶性", "C": "CAD可替代细针穿刺病理活检", "D": "CAD对微钙化检测没有任何辅助作用", "E": "CAD可替代医师直接出具诊断报告"}, "d": "难", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-107", "kp": "CAD乳腺辅助阅片", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD → (3)乳腺应用", "ex": "【为什么对】CAD对乳腺X线图像的微钙化簇与肿块检测灵敏度高，可自动标记可疑区域供医师复核，作为“第二阅读者”提高检出敏感性、减少漏诊，是乳腺筛查辅助阅片的成熟应用。\n【为什么错】B：CAD只提示可疑，良恶性判定需医师结合影像与病理综合判断。C：CAD不取材，不能替代病理活检。D：CAD对微钙化检测正是其强项。E：CAD输出标记提示，不能替代医师出具诊断报告。", "tr": "乳腺CAD=微钙化/肿块辅助标记＋医师复核；“定良恶、替活检、替诊断”均非CAD功能。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ06109", "gs": ""}, {"id": "ZG-U06-1063", "t": "案例分析题", "s": "患者男，45岁，慢性乙肝肝硬化病史，属肝癌高危人群，行腹部CT三期增强扫描。肝右叶可见可疑低密度病灶，增强后病灶与肝实质密度差仍较小，平扫及动脉期图像上显示欠清，仅门脉期隐约可见边缘强化。技师拟通过窗口技术与后处理调整获得最佳诊断图像，同时评估病灶在肝内的确切空间位置与供血动脉，请选择合适的显示与后处理方案。", "o": {"A": "采用较窄窗宽调节窗位显示肝内低对比病灶，并结合MPR多方位观察病灶空间位置", "B": "窗宽越大，肝内低对比病灶显示越清楚", "C": "MIP适合显示肝实质内低密度病灶", "D": "SSD适合显示肝内占位性病变", "E": "调节窗宽窗位会改变原始像素值"}, "d": "难", "c": "分析", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-PROC-132", "kp": "肝脏低对比病灶的显示策略", "ch": "六、数字X线成像基础 → 3.数字图像处理 → (1)窗口技术", "ex": "【为什么对】肝实质与病灶密度差小（低对比），应选较窄窗宽（如100~200 HU）并调整窗位以提高灰度对比度；同时用MPR从冠状、矢状位观察病灶在肝内位置及与血管、胆管关系，是肝占位评估的合理策略。\n【为什么错】B：窗宽越大单位灰阶CT值跨度越大，低对比病灶对比度反而下降。C：MIP取最大密度，会掩盖低密度病灶。D：SSD显示表面结构，不用于肝实质内占位观察。E：窗宽窗位是显示映射，不改变原始像素值。", "tr": "“低对比病灶用小窗宽”；MIP/SSD不适合肝内低密度病灶，调窗不改原始数据。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U06-9201", "t": "单选题", "s": "计算机辅助诊断（CAD）在影像中的角色是", "o": {"A": "提示疑似病灶，辅助而非替代医师", "B": "直接出具最终诊断", "C": "替代 PACS", "D": "关闭设备", "E": "降低标准"}, "d": "易", "c": "记忆", "m": "专业知识", "u": "六", "un": "数字X线成像基础", "kpid": "UNIT-06-CAD-9201", "kp": "CAD角色", "ch": "六、数字X线成像基础 → 5.计算机辅助诊断CAD", "ex": "【为什么对】CAD 标注疑似征象供医师参考，最终诊断仍由医师作出。\n【为什么错】CAD 不出最终诊断。", "tr": "CAD仅辅助提示。", "bk": "正高", "ref": {"篇": "影像技术专业知识", "章": "数字X线成像基础", "节": "计算机辅助诊断", "页": 142}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U07-0101", "t": "共用题干题", "s": "结合上述情景，超急性期脑梗死在DWI上呈高信号、ADC图呈低信号，其最直接的病理生理基础是", "o": {"A": "血管源性水肿使细胞外间隙水分子增多", "B": "钠钾泵功能衰竭导致细胞毒性水肿，水分子由细胞外向细胞内转移，弥散受限", "C": "梗死区血脑屏障破坏使对比剂外渗", "D": "梗死区局部脑血流量增加致灌注过度", "E": "梗死区神经元脱髓鞘使髓鞘含水量下降"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-001", "kp": "超急性期脑梗死DWI-ADC机制", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】B正确：缺血数分钟内ATP耗竭、Na⁺-K⁺-ATP酶失效，细胞外水进入细胞内形成细胞毒性水肿。细胞内水分子受细胞膜与胞内大分子限制，布朗运动受限，故DWI呈高信号、ADC值显著下降（可降至正常的50%~70%），这是最早、最敏感的征象。【为什么错】A错误：血管源性水肿位于细胞外间隙，水分子弥散反而增快，表现为DWI等或高信号但ADC升高，是亚急性期及肿瘤周围水肿的特点。C错误：血脑屏障破坏引起的是增强后强化，脑梗死脑回样强化多出现在3天至数周，与DWI早期高信号无关。D错误：超急性期梗死核心区脑血流量明显下降而非增加；过度灌注多见于再通后。E错误：脱髓鞘是慢性演变结果，与超急性期数分钟内的信号改变无关。", "tr": "务必区分“细胞毒性水肿=ADC降低”与“血管源性水肿=ADC升高”。另需警惕T2透过效应：病灶T2极高时DWI也可呈高信号，但ADC不降低，必须同时读ADC图才能判定真性弥散受限。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07160", "gs": ""}, {"id": "ZG-U07-0102", "t": "单选题", "s": "急诊MRI发现患者左侧额顶叶DWI明显高信号、ADC降低，而同层面FLAIR序列未见相应高信号。该“FLAIR-DWI不匹配”提示", "o": {"A": "病灶为陈旧性软化灶，非新鲜梗死", "B": "病灶为T2透过效应造成的假阳性", "C": "梗死发病时间很可能在4.5小时以内，属于超急性期", "D": "梗死已进入亚急性晚期，超过7天", "E": "存在大范围缺血半暗带，可据此直接判定取栓适应证"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-002", "kp": "FLAIR-DWI不匹配与发病时间判断", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】C正确：DWI在缺血后数分钟即阳性，而FLAIR反映的是组织净含水量增加，通常需6小时左右才出现高信号。DWI已阳性而FLAIR尚阴性，说明梗死处于极早期，多提示发病在4.5小时内，可为发病时间不明或醒后卒中患者提供静脉溶栓的影像学时间窗依据。【为什么错】A错误：陈旧软化灶ADC升高、FLAIR呈高信号伴中心低信号，与本例相反。B错误：T2透过效应的特征是DWI高而ADC不低，本例ADC已降低，属真性弥散受限。D错误：亚急性晚期FLAIR/T2应为明显高信号，且ADC开始回升甚至假性正常化。E错误：判断缺血半暗带需要DWI与灌注加权（PWI/CTP）的不匹配，FLAIR与DWI的不匹配只反映时间，不等同于半暗带。", "tr": "极易把“FLAIR-DWI mismatch”与“DWI-PWI mismatch”混为一谈：前者用于推断发病时间，后者用于评估可挽救的缺血半暗带。二者的临床决策指向完全不同。", "bk": "正高", "ref": null, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0103", "t": "共用题干题", "s": "结合上述情景，关于大脑中动脉供血区急性脑梗死在CT平扫上的早期征象，描述正确的是", "o": {"A": "大脑中动脉高密度征，为动脉内血栓使管腔密度增高", "B": "岛带征，即岛叶皮质与外囊之间灰白质界面模糊消失", "C": "豆状核轮廓模糊、密度减低", "D": "患侧脑沟变浅、脑回肿胀，脑灰白质分界不清", "E": "病灶区呈脑回样明显强化，是最早出现的CT征象"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-003", "kp": "急性脑梗死CT平扫早期征象", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】A正确：大脑中动脉水平段内急性血栓密度可达77~89HU，明显高于对侧，是最早可识别的直接征象。B正确：岛叶皮质对缺血极敏感，其与外囊界面模糊即岛带征。C正确：豆状核由豆纹动脉供血且缺乏侧支，缺血后密度减低、轮廓模糊。D正确：细胞毒性水肿使脑组织肿胀、脑沟变浅、灰白质界面消失，属早期占位效应。【为什么错】E错误：脑回样强化属亚急性期表现，一般在梗死后3天至数周出现，与血脑屏障破坏和侧支再灌注有关，绝非最早征象，且CT平扫不能显示强化。", "tr": "早期CT征象都是“密度差异极小”的间接改变，需要用窄窗（窗宽约30HU、窗位约35HU）的“卒中窗”观察，用常规脑窗容易漏诊。E选项以“最早”与“强化”双重错误设陷。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "急性播散性脑脊髓炎", "页": 46}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07143", "gs": ""}, {"id": "ZG-U07-0104", "t": "共用题干题", "s": "结合上述情景，脑内血肿发病第5天行MRI检查，血肿在T1WI呈高信号、T2WI呈低信号。该信号组合对应的血红蛋白降解产物是", "o": {"A": "细胞内氧合血红蛋白", "B": "细胞内脱氧血红蛋白", "C": "细胞内正铁血红蛋白（高铁血红蛋白）", "D": "细胞外正铁血红蛋白", "E": "含铁血黄素与铁蛋白"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-004", "kp": "脑出血亚急性早期MRI信号", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】C正确：发病3~7天为亚急性早期，脱氧血红蛋白被氧化为正铁血红蛋白且仍位于完整红细胞内。正铁血红蛋白含5个不成对电子，具有强顺磁性偶极-偶极作用使T1弛豫时间缩短，故T1WI呈高信号；同时红细胞膜内外磁化率差异造成局部磁场不均匀，质子失相位加快，T2WI呈低信号。【为什么错】A错误：氧合血红蛋白为抗磁性，见于超急性期，T1等或稍低、T2高信号。B错误：脱氧血红蛋白见于急性期（1~3天），T1等或稍低、T2明显低信号，不会T1高信号。D错误：细胞外正铁血红蛋白见于亚急性晚期，红细胞已溶解，磁化率不均匀消失，T1与T2均呈高信号。E错误：含铁血黄素见于慢性期，T1、T2均为低信号，以周边环状沉积为特征。", "tr": "亚急性早期与晚期的分水岭是“红细胞膜是否完整”：膜完整则T2低（磁化率效应），膜溶解则T2高。记忆口诀可用“T1先亮、T2后亮”，即T1WI高信号从亚急性早期开始，T2WI高信号到亚急性晚期才出现。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07157", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-0105", "t": "共用题干题", "s": "结合上述情景，关于脑内血肿各期在1.5T MRI常规SE序列上的信号演变规律，描述正确的是", "o": {"A": "超急性期（<24小时）血肿以氧合血红蛋白为主，T1WI呈等或稍低信号，T2WI呈高信号", "B": "急性期（1~3天）脱氧血红蛋白使T2WI呈明显低信号，T1WI呈等或稍低信号", "C": "亚急性晚期（约8天至1个月）红细胞溶解，细胞外正铁血红蛋白使T1WI与T2WI均呈高信号", "D": "慢性期（1个月以上）血肿周边含铁血黄素沉积，T1WI与T2WI均呈低信号环，SWI显示更敏感", "E": "血肿在各期的CT密度演变与MRI信号演变完全同步，CT亦可据密度准确分期至亚急性早晚期"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-005", "kp": "脑出血MRI信号演变规律", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：超急性期血红蛋白尚未脱氧，呈抗磁性，血肿含水量高故T2WI高信号，T1WI等或稍低。B正确：脱氧血红蛋白有4个不成对电子，位于完整红细胞内造成磁化率不均匀，选择性缩短T2，T2WI呈明显低信号，而其不成对电子不能接近水分子，对T1影响小。C正确：亚急性晚期红细胞溶解，正铁血红蛋白游离于细胞外，磁化率梯度消失、蛋白水化层缩短T1，故T1、T2双高信号。D正确：慢性期巨噬细胞吞噬铁形成含铁血黄素，超顺磁性造成T1、T2均低的含铁血黄素环，SWI/T2*对其最敏感，可长期存在。【为什么错】E错误：CT密度演变与MRI并不同步。CT上急性血肿为高密度，随蛋白降解密度逐渐下降，约2~4周变为等密度、之后为低密度，无法区分细胞内外正铁血红蛋白阶段，故CT不能像MRI那样细分亚急性早、晚期。", "tr": "陷阱在于把CT与MRI的分期能力等同。CT在等密度期（约2~4周）反而最易漏诊，此时MRI T1WI高信号最醒目；反之超急性期CT敏感而MRI信号最不特异，二者优势互补。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ07156", "gs": ""}, {"id": "ZG-U07-0106", "t": "案例分析题", "s": "患者男性，74岁，高血压病史不详，2年内反复发作短暂性肢体无力，近1周出现明显认知功能下降与近记忆减退。急诊CT平扫示右侧顶叶脑叶区一约2cm高密度血肿，血肿周围水肿轻微，基底节区未见陈旧腔隙灶。既往因房颤长期服用抗凝药物。临床怀疑脑淀粉样血管病所致脑叶出血，需评估脑内是否存在多发微出血灶及皮层表面铁沉积，据此判断继续抗栓治疗的出血风险。本院配置3.0T MR，患者神志清楚、可配合屏气与制动，无金属植入物。作为技师，此时最应加扫的序列及其成像原理是", "o": {"A": "加扫磁敏感加权成像（SWI/SWAN/VenoBOLD），利用含铁血黄素的磁化率效应产生相位差与信号丢失，对微出血最敏感", "B": "加扫T2WI快速自旋回波（TSE/FSE），因自旋回波的180°脉冲可放大磁化率效应", "C": "加扫DWI高b值成像，微出血灶在高b值下呈明显高信号", "D": "加扫T1WI增强扫描，微出血灶因血脑屏障破坏而明显强化", "E": "加扫三维时间飞跃法MRA（3D-TOF MRA），可直接显示皮层微小出血灶"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-006", "kp": "脑微出血检出的序列选择", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：SWI为三维扰相梯度回波长TE序列，同时利用幅值图与相位图信息，对含铁血黄素、脱氧血红蛋白等顺磁性物质的磁化率差异极为敏感，微出血呈边界清楚的圆点状极低信号并有“开花效应”，检出率显著高于常规T2*GRE与T2WI；3.0T场强下磁化率效应更强，更利于显示脑叶分布的微出血及皮层表面铁沉积。【为什么错】B错误：自旋回波的180°复相脉冲恰恰是用来补偿主磁场不均匀与磁化率失相位的，会削弱而非放大磁化率效应，TSE/FSE对微出血最不敏感。C错误：陈旧微出血无弥散受限，DWI并不敏感，且高b值图像信噪比低、易受磁敏感伪影干扰。D错误：陈旧微出血为含铁血黄素沉积，无活动性血脑屏障破坏，不强化；且对74岁患者不必要地使用钆对比剂增加风险。E错误：3D-TOF MRA显示的是流动血液信号，用于评估动脉狭窄或动脉瘤，不能显示实质内微出血。", "tr": "考点落在“序列物理原理决定征象显示”：磁化率效应需要梯度回波（无180°复相脉冲）+长TE才能充分演化。把SWI与DWI、T2*与T2混淆是常见失分点。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "总论", "节": "头颅MR检查方法及各序列的应用", "页": 12}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0107", "t": "共用题干题", "s": "结合上述情景，关于脑膜瘤的典型影像学表现，下列描述错误的是", "o": {"A": "CT平扫多呈边界清楚的稍高密度肿块，约20%可见钙化", "B": "增强扫描多呈明显均匀强化，邻近硬膜可见“脑膜尾征”", "C": "可见白质塌陷征与脑脊液裂隙征，提示肿瘤位于脑实质外", "D": "邻近颅骨可出现骨质增生硬化", "E": "T2WI上肿瘤实质多呈显著高信号且伴瘤内液平，为脑膜瘤的定性依据"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-007", "kp": "脑膜瘤影像诊断要点", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】E为错误描述，故为本题答案：脑膜瘤细胞排列致密、含水量相对低，T2WI多呈等或稍高信号，与灰质相仿；显著高信号伴瘤内液平并非脑膜瘤特征，更提示囊性病变或血管母细胞瘤等。T2WI信号可提示亚型（纤维型偏低、血管瘤型偏高），但不能作为定性依据。【为什么错】A描述正确：脑膜瘤富含细胞与砂粒体，CT平扫多为稍高密度，钙化率约20%~25%。B描述正确：肿瘤血供丰富且无血脑屏障，强化明显均匀；脑膜尾征为邻近硬膜反应性增厚或肿瘤浸润所致，是重要但非特异征象。C描述正确：白质塌陷征（肿瘤压迫使皮层下白质向内推移）与脑脊液裂隙征均为脑外肿瘤定位征象。D描述正确：颅骨可出现增生硬化，少数为侵蚀破坏。", "tr": "本题为反向提问（选“错误”），审题不清易失分。另需牢记：脑膜尾征也可见于转移瘤、淋巴瘤、结核性脑膜炎，不能单凭尾征确诊脑膜瘤。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "脑膜炎", "页": 40}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07158", "gs": ""}, {"id": "ZG-U07-0108", "t": "多选题", "s": "颅内单发环形强化病灶，需在高级别胶质瘤与脑转移瘤之间鉴别。下列有助于鉴别的影像学依据是", "o": {"A": "高级别胶质瘤瘤周异常T2/FLAIR高信号区内常含肿瘤细胞浸润，MRS示该区胆碱（Cho）峰升高、N-乙酰天门冬氨酸（NAA）峰下降", "B": "转移瘤瘤周多为单纯血管源性水肿，瘤周区相对脑血容量（rCBV）不升高", "C": "转移瘤多位于灰白质交界区，常呈“小病灶、大水肿”", "D": "高级别胶质瘤常沿胼胝体或白质纤维束跨中线蔓延生长", "E": "两者的强化环壁厚度与规整度完全一致，环形强化本身即可确诊转移瘤"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-008", "kp": "高级别胶质瘤与转移瘤鉴别", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：胶质瘤呈浸润性生长，强化灶外的“水肿区”实为肿瘤浸润带，MRS呈Cho升高、NAA降低、Cho/NAA比值增大。B正确：转移瘤为膨胀性生长且瘤周无肿瘤细胞，灌注成像上瘤周rCBV不升高，此为与胶质瘤鉴别的重要定量指标。C正确：血行转移瘤易停留于灰白质交界区末梢小血管处，病灶小而水肿广泛。D正确：胶质瘤沿白质纤维束蔓延，跨胼胝体生长形成“蝴蝶征”，转移瘤罕有此表现。【为什么错】E错误：两者强化环形态确有差别（胶质瘤环壁多厚薄不均、内缘不规则；转移瘤环壁相对较薄且规整），且环形强化的鉴别诊断还包括脓肿、脱髓鞘、放射性坏死等，单凭环形强化不能确诊任何一种。", "tr": "“瘤周水肿区的灌注与波谱”是区分浸润性与膨胀性生长的核心思路，比单纯看强化形态更可靠。E以“完全一致”“即可确诊”双重绝对化措辞设陷。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "肿瘤和肿瘤样病变", "节": "转移性肿瘤", "页": 79}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0109", "t": "单选题", "s": "颅内囊性病灶伴环形强化，欲鉴别脑脓肿与囊变坏死性肿瘤，最具价值的序列及其表现是", "o": {"A": "DWI上脓腔呈明显高信号、ADC值降低；肿瘤囊变区DWI呈低信号、ADC值升高", "B": "DWI上脓腔呈低信号、ADC值升高；肿瘤囊变区DWI呈高信号、ADC值降低", "C": "T1WI平扫，脓腔呈高信号而肿瘤囊变区呈低信号", "D": "3D-TOF MRA，脓肿壁可见异常血管团", "E": "MRA源图像，脓腔内可见流空信号"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-009", "kp": "脑脓肿DWI鉴别诊断", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：脓液由坏死碎屑、大量炎性细胞与高浓度蛋白构成，黏稠度高，水分子弥散显著受限，故DWI呈明显高信号、ADC值降低（多低于1.0×10⁻³mm²/s）；而肿瘤囊变坏死区为稀薄液体，水分子自由弥散，DWI低信号、ADC升高。此为二者最可靠的鉴别点，准确率约90%以上。【为什么错】B错误：信号描述完全颠倒。C错误：脓腔T1WI多为低或稍高信号，与肿瘤囊变区重叠明显，无鉴别价值。D错误：MRA显示的是血流，脓肿壁虽富血供但不形成MRA可见的异常血管团，此为动静脉畸形的表现。E错误：脓腔内为黏稠脓液，无血流，不会出现流空信号。", "tr": "补充记忆：脓肿壁在T2WI上常呈完整、光滑的低信号环，且靠脑室侧较薄（易破入脑室）；MRS可检出醋酸盐、琥珀酸盐及氨基酸峰，为脓肿特有。若脓肿经抗生素治疗后，DWI高信号可减弱，需结合临床。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "脑脓肿", "页": 40}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0110", "t": "共用题干题", "s": "结合上述情景，关于多发性硬化（MS）的MRI表现，描述正确的是", "o": {"A": "侧脑室周围病灶长轴多垂直于侧脑室壁排列，即“Dawson手指征”", "B": "矢状面FLAIR显示胼胝体-透明隔交界面受累，对早期诊断有较高特异性", "C": "活动期病灶可呈开环样或不完整环形强化，开口多朝向皮层灰质侧", "D": "脊髓病灶多较短，纵向范围一般小于2个椎体节段，横断面上常不超过脊髓横截面的一半", "E": "所有MS病灶在增强扫描时均呈明显强化，强化与否与病程无关"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-010", "kp": "多发性硬化MRI诊断要点", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】A正确：脱髓鞘沿深髓静脉周围分布，故病灶长轴与侧脑室壁垂直呈指状。B正确：胼胝体下缘与透明隔交界处受累在其他脑白质病变中少见，矢状面FLAIR是显示该征象的最佳方位。C正确：开环强化为MS较具特征的表现，环的开口朝向皮层灰质侧，因灰质侧炎症反应较轻。D正确：MS脊髓病灶短节段、偏心、位于后索或侧索，可与视神经脊髓炎谱系病（纵向广泛，≥3个椎体节段）鉴别。【为什么错】E错误：只有活动期（血脑屏障破坏期，约持续2~8周）病灶才强化，陈旧斑块不强化。强化与否恰恰是判断病灶“时间多发性”与疾病活动度的关键依据。", "tr": "E以“所有”“均”“与病程无关”设置绝对化陷阱。实际上MS诊断的McDonald标准正是依靠强化与非强化病灶并存来同时满足空间多发与时间多发。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "多发性硬化", "页": 45}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07138", "gs": ""}, {"id": "ZG-U07-0111", "t": "单选题", "s": "单纯疱疹病毒性脑炎最典型的病变累及部位是", "o": {"A": "双侧基底节区与丘脑", "B": "颞叶内侧、岛叶及扣带回，常不累及豆状核", "C": "双侧小脑半球与脑干", "D": "双侧顶枕叶皮层下白质", "E": "脑室周围白质与半卵圆中心"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-011", "kp": "单纯疱疹病毒性脑炎影像定位", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】B正确：单纯疱疹病毒经三叉神经或嗅神经逆行侵入边缘系统，特征性累及颞叶内侧（海马、杏仁核）、岛叶皮质、扣带回及额叶眶面，多为双侧但不对称。病变与豆状核之间界限清楚，呈“刀切样”边缘，是重要鉴别征象。FLAIR与DWI最敏感，可早于CT数天出现异常。【为什么错】A错误：双侧基底节与丘脑对称受累更提示深部静脉血栓、一氧化碳中毒、代谢性或某些病毒性脑炎（如日本脑炎）。C错误：小脑与脑干受累提示菱脑炎（如李斯特菌）或急性小脑炎。D错误：顶枕叶皮层下白质对称水肿是可逆性后部脑病综合征（PRES）的典型分布。E错误：脑室周围白质与半卵圆中心受累多见于脱髓鞘病变、缺血性白质病变或进行性多灶性白质脑病。", "tr": "“豆状核不受累”是单纯疱疹病毒性脑炎与大脑中动脉梗死鉴别的关键——后者岛叶与豆状核可同时受累且符合血管分布区。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "单纯疱疹病毒脑炎", "页": 39}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0112", "t": "共用题干题", "s": "结合上述情景，患者男性，62岁，工作中突发右侧肢体偏瘫伴完全性失语3小时，急诊NIHSS评分16分，既往房颤病史，血压162/95mmHg。急诊CT平扫未见颅内出血，隐约可见左侧岛带征，脑沟稍变浅。卒中中心需在最短时间内同时回答两个问题：是否存在颅内大血管急性闭塞，以及核心梗死灶与缺血半暗带各占多大范围，据此决定是否启动血管内取栓。科室配置256排CT，患者躁动明显、难以长时间保持制动，肾功能正常，无碘对比剂过敏史。作为技师，最合理的检查技术方案是", "o": {"A": "在CT平扫基础上一站式完成头颈CT血管成像（CTA）加全脑CT灌注成像（CTP），由CTP的CBF与Tmax参数图判断核心梗死区与半暗带", "B": "先送MRI行DWI加PWI评估，因MRI对早期梗死更敏感，时间成本可以忽略", "C": "仅重复CT平扫观察低密度是否加重，无需血管与灌注评估", "D": "行常规头部CT增强扫描，通过实质强化程度判断半暗带范围", "E": "直接行DSA全脑血管造影，兼顾诊断与治疗，无需任何无创性影像评估"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-NEU-012", "kp": "急性卒中一站式CT检查方案", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】A正确：CT平扫排除出血、CTA明确大血管闭塞部位与侧支循环、CTP量化核心梗死区与半暗带，三者可在一次静脉团注下一站式完成，总耗时通常不超过10分钟，且对躁动患者的耐受性远优于MRI。判读上通常以脑血流量（CBF）低于对侧30%的区域估算核心梗死区，以达峰时间残差（Tmax）大于6秒的区域估算低灌注区，二者之差即缺血半暗带。【为什么错】B错误：MRI检查前需筛查金属禁忌、扫描时间长、对躁动患者运动伪影严重，急诊卒中绿色通道中会显著延误再灌注时间。C错误：单纯重复平扫无法提供血管与灌注信息，不能支持取栓决策，且延误时间窗。D错误：常规增强扫描只反映血脑屏障与血管内对比剂总量，无时间-密度曲线，无法计算CBF、CBV、MTT、Tmax等灌注参数。E错误：DSA为有创操作，不应在无创筛查前盲目实施；且DSA只显示血管，不能直接评估脑组织灌注状态。", "tr": "关键在于区分“增强扫描”与“灌注成像”：前者是单期或多期形态学成像，后者是同层面连续动态采集并经数学模型计算得到参数图。二者对比剂用法、扫描逻辑与临床用途完全不同。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "急性播散性脑脊髓炎", "页": 46}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07142", "gs": ""}, {"id": "ZG-U07-0113", "t": "单选题", "s": "甲状腺相关眼病（Graves眼病）在CT与MRI上最具特征性的表现是", "o": {"A": "眼外肌肌腹梭形增粗而肌腱附着点不受累，多为双侧、以下直肌和内直肌最先受累", "B": "眼外肌肌腹与肌腱同时增粗，边缘模糊", "C": "泪腺弥漫增大伴眼睑肿胀，眼外肌正常", "D": "球后脂肪内孤立强化肿块，推压视神经移位", "E": "眼球壁广泛增厚并伴巩膜后水肿"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-013", "kp": "Graves眼病影像诊断要点", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】A正确：Graves眼病为自身免疫性炎症，糖胺聚糖沉积于眼外肌肌腹的肌纤维间隙，而肌腱附着点缺乏此类间质反应，故呈典型“肌腹增粗、肌腱不受累”的梭形改变。受累顺序常记作下直肌、内直肌、上直肌、外直肌，多双侧不对称，眶尖肌肉拥挤可致压迫性视神经病变。【为什么错】B错误：肌腹与肌腱同时增粗、边缘模糊是眼眶炎性假瘤（特发性眼眶炎性病变）的特点，且多为单侧、疼痛明显、对激素反应好。C错误：泪腺弥漫增大为泪腺炎型炎性假瘤或IgG4相关病变表现。D错误：球后孤立强化肿块提示海绵状血管瘤或神经鞘瘤等占位。E错误：眼球壁广泛增厚伴巩膜后水肿见于巩膜炎型炎性假瘤。", "tr": "“肌腱是否受累”是Graves眼病与炎性假瘤的分水岭，也是命题最集中的一点。技术上应采用横断面加冠状面薄层（层厚≤2mm），冠状面能同时对比四条直肌粗细，是评估眶尖拥挤的必需方位。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0114", "t": "多选题", "s": "关于眼眶病变的影像检查与征象分析，下列描述正确的是", "o": {"A": "眼眶炎性假瘤在T2WI上常呈等或低信号，与病灶内纤维成分较多有关", "B": "眼眶海绵状血管瘤动态增强呈“渐进性强化”，即由点状强化逐渐向整个病灶扩展填充", "C": "怀疑眶内金属异物时应先行X线平片或CT，不宜首选MRI", "D": "评估视神经病变时应采用脂肪抑制T2WI与脂肪抑制T1WI增强，以消除眶内脂肪高信号的掩盖", "E": "眼眶CT扫描时冠状面重建对判断眶壁骨折（如眶底爆裂骨折）价值有限，横断面已足够"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-014", "kp": "眼眶病变影像检查技术与征象", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】A正确：炎性假瘤含大量纤维结缔组织，自由水少，T2WI呈等或低信号，此点可与含水量高的淋巴瘤、血管瘤区分。B正确：海绵状血管瘤内血窦血流缓慢，对比剂缓慢充盈，表现为“渐进性强化”，延迟期充填均匀，是其定性征象。C正确：眶内金属异物在磁场中可能移位造成眼球损伤，属MRI禁忌，必须先用X线平片或CT筛查。D正确：眶内脂肪T1、T2均为高信号，会掩盖病灶与视神经异常信号，脂肪抑制技术是眼眶MRI的基本要求。【为什么错】E错误：眶底与眶内壁为水平走行结构，横断面上呈平行于扫描层面的方向，容易漏诊；冠状面（或冠状位重建）是显示眶底爆裂骨折、下直肌疝入上颌窦的最佳方位。", "tr": "E的陷阱在于忽视“骨壁走行方向与扫描平面平行时易漏诊”的通则。技师应用层面：眶部CT应采集各向同性薄层容积数据，以便任意方位重建。", "bk": "正高", "ref": {"篇": "头颈部", "章": "眼眶病变", "节": "先天异常", "页": 91}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0115", "t": "单选题", "s": "真菌性鼻窦炎（真菌球型）在CT与MRI上最具提示意义的表现是", "o": {"A": "CT示窦腔内软组织影中见斑点状或条片状高密度钙化，MRI T2WI呈极低信号甚至近似无信号", "B": "CT示窦腔内均匀低密度，MRI T1WI低、T2WI明显高信号", "C": "CT示窦壁广泛虫蚀样骨质破坏，MRI呈均匀明显强化", "D": "CT示窦腔完全含气，仅黏膜轻度增厚", "E": "CT示窦腔内脂肪密度，MRI脂肪抑制后信号明显下降"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-015", "kp": "真菌性鼻窦炎影像特征", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】A正确：真菌球内含钙盐、铁、镁、锰等重金属及菌丝，CT表现为窦腔（好发上颌窦）内不均匀软组织密度中夹杂点、条状高密度钙化，窦壁可增生硬化。MRI上因顺磁性金属与含水量极低，T2WI呈极低信号甚至“信号缺失”，易被误认为窦腔含气，必须与CT对照。【为什么错】B错误：均匀低密度伴T2明显高信号是普通潴留囊肿或黏液潴留的表现。C错误：广泛虫蚀样骨破坏提示侵袭性真菌感染或恶性肿瘤，非典型真菌球型。D错误：窦腔含气、黏膜轻度增厚为轻度慢性炎症。E错误：窦腔内脂肪密度极为罕见，见于脂肪瘤或术后填塞材料。", "tr": "最大的陷阱是“MRI T2极低信号被误读为正常含气窦腔”而漏诊。凡MRI提示鼻窦“空虚”而临床有症状者，必须加做CT骨算法观察有无高密度钙化。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0116", "t": "案例分析题", "s": "患者男性，48岁，反复回吸性血涕3个月，伴左耳闷堵感与听力下降，查体见左侧颈部Ⅱ区一枚约2cm质硬淋巴结。鼻咽镜见左侧咽隐窝饱满、黏膜隆起，活检病理证实为非角化型鼻咽癌。临床需明确肿瘤是否侵犯颅底斜坡骨髓、破裂孔、翼腭窝及海绵窦，并评估颈部各区淋巴结转移情况，以完成精确临床分期与放疗靶区勾画。患者无幽闭恐惧，无心脏起搏器等MRI禁忌证，肾功能正常。作为技师，下列检查技术安排最合理的是", "o": {"A": "以鼻咽部薄层高分辨T2WI结合脂肪抑制T1WI增强（横断面加冠状面）为核心，扫描范围上至鞍上池、下至锁骨上窝", "B": "仅行鼻咽部CT平扫，因CT显示骨皮质优于MRI，足以判断颅底骨髓侵犯", "C": "仅行鼻咽部MRI平扫，不使用对比剂，以避免钆剂不良反应", "D": "行头颅常规MRI序列（层厚6mm），范围自颅顶至颅底即可", "E": "行鼻咽部CT增强，扫描范围仅覆盖鼻咽腔上下各2cm"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-016", "kp": "鼻咽癌MRI检查技术与分期评估", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】A正确：正常斜坡骨髓因含脂肪在T1WI呈高信号，肿瘤侵犯后被替代为低信号，故平扫T1WI是判断颅底骨髓侵犯最敏感的序列；脂肪抑制T1WI增强则用于显示强化的肿瘤与神经周围侵犯、海绵窦受累。冠状面对显示颅底孔道与颅内侵犯尤为重要。范围必须上至鞍上池（评估海绵窦、颅内侵犯）、下至锁骨上窝（评估颈部各区淋巴结），这是鼻咽癌分期的标准要求。【为什么错】B错误：CT显示骨皮质破坏敏感，但对尚未破坏皮质的骨髓浸润不敏感，会造成分期偏低。C错误：不使用对比剂无法准确判断海绵窦侵犯、神经周围播散及肿瘤与炎症的分界。D错误：层厚6mm且范围不含颈部，既漏掉小病灶细节又漏掉淋巴结分期。E错误：范围过小必然遗漏颅底与颈部淋巴结，且CT对软组织分辨率不及MRI。", "tr": "记住一条规律：“T1WI平扫看骨髓，脂肪抑制T1WI增强看侵犯范围”。若在增强后直接加脂肪抑制而不保留平扫T1WI，会失去判断骨髓脂肪被替代的基线，是实际工作中的常见失误。", "bk": "正高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "鼻咽部病变", "页": 103}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0117", "t": "共用题干题", "s": "结合上述情景，关于中耳胆脂瘤的影像诊断，下列描述最准确的是", "o": {"A": "颞骨HRCT示上鼓室Prussak间隙软组织影伴听小骨吸收、盾板变钝，非回波平面DWI呈高信号", "B": "颞骨HRCT示鼓室内软组织影伴听小骨完整，增强后明显强化", "C": "颞骨HRCT示乳突小房密度增高但骨间隔完整，MRI T2WI低信号", "D": "颞骨HRCT示内听道扩大伴其内软组织结节，增强明显强化", "E": "颞骨HRCT示颈静脉孔区骨质呈虫蚀样破坏，MRI见“胡椒盐征”"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-017", "kp": "中耳胆脂瘤影像诊断要点", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】A正确：后天原发性胆脂瘤起自上鼓室外侧隐窝（Prussak间隙），HRCT表现为该处软组织团块伴锤骨头、砧骨长脚吸收破坏，盾板（scutum）变钝或消失，上鼓室膨大，可破坏鼓室盾板、面神经管及外半规管。胆脂瘤基质角化物弥散明显受限，在非回波平面DWI（non-EPI DWI）上呈高信号，是术前定性与术后复发判断的关键序列。【为什么错】B错误：胆脂瘤本身为角化物堆积，无血供，增强不强化（周围肉芽组织可边缘强化），且听小骨常被破坏。C错误：乳突小房密度增高但骨间隔完整为单纯乳突炎表现。D错误：内听道扩大伴强化结节是听神经瘤表现。E错误：颈静脉孔区虫蚀样骨破坏伴“胡椒盐征”是颈静脉球瘤（副神经节瘤）的典型表现。", "tr": "关键技术点：常规回波平面DWI在颞骨区受气骨界面磁敏感伪影严重干扰，会产生假高信号，必须使用非回波平面（如HASTE/BLADE基础的）DWI才可靠。“胆脂瘤不强化、肉芽组织强化”亦是常考鉴别点。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07131", "gs": ""}, {"id": "ZG-U07-0118", "t": "共用题干题", "s": "结合上述情景，关于甲状腺乳头状癌及其颈部转移淋巴结的CT/MRI表现，描述正确的是", "o": {"A": "原发灶多呈边界不清的低密度结节，其内可见细小砂粒样钙化", "B": "增强扫描原发灶强化程度低于周围正常甲状腺组织，可见“咬饼征”样边缘缺损", "C": "转移淋巴结可发生囊变，其内可含胶质而在T1WI呈高信号", "D": "转移淋巴结可出现细颗粒状钙化并明显强化", "E": "凡甲状腺结节内出现钙化即为恶性征象，粗大环形钙化的恶性风险高于微钙化"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-018", "kp": "甲状腺癌与颈部转移淋巴结影像特征", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】A正确：乳头状癌呈浸润性生长，边界不清，其内砂粒体形成细小点状钙化。B正确：正常甲状腺富含碘，平扫即为高密度且增强显著；癌灶不摄碘、血供相对少，故强化程度低于腺体，与包膜接触处可呈“咬饼样”缺损。C正确：乳头状癌转移淋巴结特征性囊变，含甲状腺球蛋白等胶质成分，T1WI可呈高信号。D正确：转移淋巴结内可见细颗粒状钙化并明显强化，与鳞癌转移淋巴结的坏死性低强化不同。【为什么错】E错误：钙化并非恶性特有，结节性甲状腺肿常有粗大或环形钙化；恶性风险更高的是微钙化（砂粒样），而粗大、环形完整的钙化多提示良性。", "tr": "E将钙化风险等级完全说反，并用“凡……即为”的绝对化措辞。技术层面注意：碘对比剂增强会干扰后续¹³¹I治疗与摄碘评估，检查前需与临床沟通。", "bk": "正高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "颈部囊性病变", "页": 107}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07148", "gs": ""}, {"id": "ZG-U07-0119", "t": "单选题", "s": "按影像学颈部淋巴结分区标准，位于舌骨体下缘至环状软骨下缘之间、颈内静脉链周围的淋巴结属于", "o": {"A": "Ⅰ区", "B": "Ⅱ区", "C": "Ⅲ区", "D": "Ⅳ区", "E": "Ⅵ区"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-019", "kp": "颈部淋巴结影像学分区", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】C正确：影像学分区以骨性与软骨标志划界，Ⅲ区（颈内静脉中组）上界为舌骨体下缘、下界为环状软骨下缘，前界为胸骨舌骨肌外缘，后界为胸锁乳突肌后缘。【为什么错】A错误：Ⅰ区为颏下（ⅠA）与颌下（ⅠB）区，位于舌骨体上缘、下颌下腺后缘以前。B错误：Ⅱ区（颈内静脉上组）上界为颅底、下界为舌骨体下缘，以副神经为界分ⅡA与ⅡB。D错误：Ⅳ区自环状软骨下缘至锁骨上缘。E错误：Ⅵ区为中央区，位于舌骨与胸骨上切迹之间、两侧颈总动脉内侧，含气管前与气管旁淋巴结。", "tr": "务必用“舌骨体下缘”和“环状软骨下缘”这两个横断面可辨的标志区分Ⅱ、Ⅲ、Ⅳ区。临床解剖分区（以肩胛舌骨肌为界）与影像学分区标志不同，考试以影像学标志为准。", "bk": "正高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "颈部囊性病变", "页": 107}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0120", "t": "单选题", "s": "上颌窦腔完全被病变充填，欲鉴别慢性炎症潴留物与实体肿瘤，MRI上最有价值的判断依据是", "o": {"A": "潴留分泌物T2WI呈明显高信号且增强后不强化，肿瘤实质T2WI多呈中等信号且明显强化", "B": "潴留分泌物T2WI呈低信号，肿瘤T2WI呈高信号", "C": "两者T1WI信号相同，故只能依靠CT判断", "D": "潴留分泌物增强后明显均匀强化，肿瘤不强化", "E": "只需观察窦腔是否扩大，扩大者必为肿瘤"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-020", "kp": "鼻窦炎症与肿瘤的MRI鉴别", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】A正确：炎性潴留物含水量高，T2WI呈明显高信号，本身无血供故增强后不强化，仅周边黏膜呈线状强化；肿瘤细胞密集、含水相对少，T2WI呈中等（介于肌肉与液体之间）信号且增强后实质强化。因此增强脂肪抑制T1WI能清晰勾勒“强化的肿瘤”与“不强化的阻塞性分泌物”的分界，这是MRI优于CT的核心价值。【为什么错】B错误：信号描述颠倒；T2低信号更提示真菌球或高蛋白浓缩分泌物。C错误：T1WI信号确有重叠，但T2WI与增强能有效鉴别，并非只能靠CT。D错误：强化关系完全说反。E错误：慢性炎症（如黏液囊肿）也可使窦腔膨胀扩大、窦壁受压变薄，扩大并非肿瘤特有；肿瘤更倾向骨质虫蚀样破坏。", "tr": "CT上炎症与肿瘤同为软组织密度、常难区分，而MRI的T2信号差异与强化差异是分界关键。临床工作中常需CT（看骨质）与MRI（看软组织范围）互补，不可偏废。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0121", "t": "单选题", "s": "大叶性肺炎实变期胸片与CT上出现“空气支气管征”，其病理基础是", "o": {"A": "肺泡腔被渗出液充填而支气管腔内仍含气，在高密度实变背景中衬托出含气支气管", "B": "支气管壁增厚并伴管腔扩张", "C": "肺泡壁破坏融合形成肺大疱", "D": "支气管腔内被黏液栓完全阻塞", "E": "胸膜腔内游离气体沿支气管走行分布"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-021", "kp": "空气支气管征的病理基础", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：大叶性肺炎实变期肺泡内充满纤维素性渗出液，密度升高，而各级支气管本身未被阻塞、腔内仍含气，于是在均匀高密度实变区内显示为树枝状或管状透亮影，即空气支气管征。该征象说明病变位于肺泡腔而非支气管内阻塞性改变，是肺炎、肺水肿、部分肺泡型肺癌的共同征象。【为什么错】B错误：支气管壁增厚伴扩张为支气管扩张症的“印戒征”“轨道征”。C错误：肺大疱为薄壁含气腔，周围无实变背景。D错误：黏液栓完全阻塞时表现为“指套征”并常伴远端肺不张，恰恰不会出现空气支气管征。E错误：胸膜腔游离气体为气胸，位于胸膜腔而非支气管内。", "tr": "阻塞性肺不张与肺炎实变的关键区别之一即空气支气管征的有无——中央型肺癌所致阻塞性肺不张一般不出现该征象，若在“不张”影内见到空气支气管征，应重新考虑是否为实变。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0122", "t": "多选题", "s": "关于肺结核各型的影像学表现，描述正确的是", "o": {"A": "原发综合征表现为肺内原发病灶、淋巴管炎与肺门/纵隔淋巴结肿大，呈“哑铃状”改变", "B": "急性血行播散型肺结核呈两肺弥漫粟粒结节，具有分布均匀、大小均匀、密度均匀的“三均匀”特点", "C": "继发性肺结核好发于上叶尖后段与下叶背段，常呈渗出、增殖、纤维、钙化、空洞多形态并存", "D": "结核球多小于3cm，边缘光滑，可有环状或斑点状钙化，周围常见卫星灶", "E": "结核性空洞多为偏心厚壁空洞、内壁凹凸不平并见壁结节"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-022", "kp": "肺结核分型影像表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：原发灶、引流淋巴管炎与肿大的肺门淋巴结共同构成原发综合征的哑铃状表现。B正确：急性血行播散型由结核菌一次性大量入血形成，故粟粒结节的分布、大小、密度三方面均匀，为其经典描述。C正确：继发性肺结核好发于上叶尖后段与下叶背段（通气好、血流相对少、淋巴引流慢），影像上“多形态、多阶段病灶并存”是重要特征。D正确：结核球为纤维包裹的干酪坏死灶，边缘光滑，钙化多呈环状或斑点状，周围卫星灶具重要提示价值。【为什么错】E错误：偏心厚壁、内壁凹凸不平伴壁结节是癌性空洞的特征；结核性空洞多为薄壁或壁较均匀、内壁光滑，周围伴卫星灶与引流支气管。", "tr": "空洞鉴别是高频考点：结核空洞薄壁光滑加卫星灶；癌性空洞偏心厚壁加壁结节；肺脓肿厚壁但内壁光滑、常见气液平且周围渗出明显。", "bk": "正高", "ref": {"篇": "胸部", "章": "肺感染", "节": "肺结核", "页": 127}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0123", "t": "共用题干题", "s": "结合上述情景，右上叶中央型肺癌导致右上叶肺不张时，胸片上肺门肿块与上抬的水平裂共同形成的典型征象称为", "o": {"A": "空气新月征", "B": "反“S”征（Golden S征）", "C": "银币征", "D": "颈胸征", "E": "肺门舞蹈征"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-023", "kp": "中央型肺癌反S征", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】B正确：右上叶不张使水平裂外侧段向上向内移位呈凹面向下，而肺门处肿块使内侧段向下膨隆呈凸面向下，二者相连形成横置的反“S”形，称Golden S征，是中央型肺癌伴阻塞性肺不张的经典X线征象。【为什么错】A错误：空气新月征指空洞或曲霉球与洞壁间的新月形气体影，见于肺曲霉病、坏死性肺炎。C错误：银币征（硬币征）指侧位片上叶间积液呈梭形致密影。D错误：颈胸征用于判断纵隔肿块位置——肿块上缘超过锁骨水平仍清晰可见者位于后纵隔。E错误：肺门舞蹈是透视下肺门血管搏动增强的动态表现，见于左向右分流型先心病，非形态学征象。", "tr": "反S征的核心含义是“不张（体积缩小）＋肺门肿块（体积增大）”并存，提示不张由中央阻塞性病变引起，与单纯炎性不张不同。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07130", "gs": ""}, {"id": "ZG-U07-0124", "t": "案例分析题", "s": "患者男性，58岁，吸烟史30年，咳嗽伴痰中带血1个月。常规胸部CT平扫（层厚5mm）示右肺上叶一约2.2cm结节，边缘似有分叶，与胸膜关系欠清，结节内密度不均。临床需要明确该结节的边缘形态、有无空泡征与胸膜凹陷征，并评估其强化特点以判断良恶性。患者肾功能正常、无碘对比剂过敏史。作为技师，下列技术方案最恰当的是", "o": {"A": "采用薄层（≤1mm）高分辨重建加靶重建观察边缘细节，并行同层动态增强扫描测量结节强化幅度与时间-密度曲线", "B": "重复5mm层厚平扫并加大窗宽观察，无需薄层重建", "C": "直接行胸部X线正侧位片补充观察边缘征象", "D": "仅行胸部MRI T2WI，因MRI软组织分辨率高于CT，可替代薄层CT评估结节边缘", "E": "行胸部CT平扫加延迟5分钟单期扫描，以延迟强化程度判断良恶性"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-024", "kp": "肺结节薄层与动态增强技术选择", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：分叶、毛刺、空泡、胸膜凹陷、血管集束等细微征象的显示高度依赖空间分辨率，5mm层厚存在明显部分容积效应，必须用亚毫米薄层加高分辨（骨/肺算法）靶重建。孤立性肺结节动态增强是评价血供的成熟方法：注药后每分钟采集同层图像，强化峰值增幅小于约15HU多提示良性，15~20HU以上并呈快速强化后平台或流出型曲线者恶性可能大。【为什么错】B错误：加大窗宽不能弥补层厚造成的部分容积效应，细微边缘征象仍无法显示。C错误：胸片密度分辨率与空间定位能力远不及CT，无法评估2cm结节的边缘细节。D错误：肺内空气与组织磁化率差异大、呼吸运动明显，MRI对肺实质细微结构显示不如CT，不能替代薄层CT。E错误：单一延迟期无法获得时间-密度曲线，无法区分快进快出与渐进强化模式，信息量严重不足。", "tr": "本题体现“征象识别依赖采集技术”的命题思路：层厚决定能否看到毛刺与空泡，扫描时相决定能否判读强化模式。仅凭平扫或单期增强下结论是实际工作中的常见错误。", "bk": "正高", "ref": {"篇": "胸部", "章": "肺感染", "节": "肺结核", "页": 127}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0125", "t": "共用题干题", "s": "结合上述情景，患者女性，66岁，全髋关节置换术后第5天，卧床期间突发胸痛、呼吸困难，心率112次/分，血氧饱和度88%，血浆D-二聚体显著升高，右下肢较对侧明显肿胀。临床高度怀疑急性肺栓塞，急诊申请CT肺动脉造影（CTPA），要求明确肺动脉主干及各叶段分支有无栓子并评估右心负荷。患者呼吸急促、屏气不足8秒，无法长时间配合，血肌酐正常，无碘对比剂过敏史，静脉通路为右肘正中静脉18G留置针。作为技师，下列扫描技术要点组合最恰当的是", "o": {"A": "采用团注跟踪法将监测ROI置于肺动脉主干、阈值约100HU触发，高流率注射后以生理盐水冲刷，尽量缩短扫描时间并在浅吸气末屏气采集", "B": "监测ROI置于降主动脉、阈值250HU触发，以保证肺动脉充分强化", "C": "采用固定延迟60秒扫描，无需团注跟踪", "D": "嘱患者深大吸气后屏气至最大肺容量再扫描，以充分展开肺野", "E": "不使用生理盐水冲刷，以延长对比剂在肺动脉内的停留时间"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-025", "kp": "CTPA扫描技术要点", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：CTPA的目标是肺动脉峰值强化，故监测ROI应放在肺动脉主干，阈值通常设在约100HU左右并采用较短触发延迟；注射流率一般4~5ml/s，随后以生理盐水冲刷可推进对比剂团、减少上腔静脉内高浓度对比剂造成的线束硬化伪影；对呼吸困难者应缩短扫描时间并采用浅吸气末屏气，必要时平静呼吸下扫描。【为什么错】B错误：ROI置于降主动脉、阈值过高会导致触发过晚，采集时对比剂已进入体循环，肺动脉强化下降而主动脉过度强化。C错误：固定延迟无法适应患者心输出量的巨大个体差异，尤其肺栓塞患者循环时间常延长，易造成时相错误。D错误：深大吸气会使胸腔负压骤增，大量未强化的下腔静脉血涌入右心，稀释肺动脉内对比剂形成“瞬时对比剂中断”伪影，反而降低图像质量。E错误：不冲刷会加重上腔静脉与右心内高浓度对比剂的硬化伪影，干扰右肺动脉与其分支的观察。", "tr": "“深吸气屏气”在常规胸部CT是正确的，但在CTPA中恰是造成瞬时对比剂中断的经典原因，属技术细节性陷阱。此外，CTPA的团注跟踪阈值明显低于主动脉CTA，需分别记忆。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07128", "gs": ""}, {"id": "ZG-U07-0126", "t": "共用题干题", "s": "结合上述情景，CTPA上提示急性肺栓塞而非慢性栓塞的征象是", "o": {"A": "腔内中心性充盈缺损被对比剂环绕形成“轨道征”，附壁血栓与管壁呈锐角", "B": "血栓呈偏心附壁分布并与管壁呈钝角，伴管腔缩小", "C": "肺动脉壁钙化伴管腔膜状分隔", "D": "支气管动脉迂曲增粗、体-肺侧支形成", "E": "肺野呈广泛马赛克灌注伴管径粗细不均"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-026", "kp": "肺栓塞CTPA急慢性鉴别", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：急性血栓较新鲜、不附着于管壁，多悬浮于管腔中央，被对比剂环绕，长轴呈“轨道征”、短轴呈环形“甜甜圈”样；附壁部分与管壁交界呈锐角，且受累血管常轻度扩张。【为什么错】B错误：偏心附壁、与管壁呈钝角并伴管腔缩小，是机化血栓贴壁的慢性征象。C错误：肺动脉壁钙化与腔内膜状分隔（网状/条带）为慢性血栓栓塞性肺高压的典型改变。D错误：支气管动脉增粗与体-肺侧支形成需长期慢性缺血才会建立，是慢性表现。E错误：马赛克灌注伴血管管径粗细不均反映慢性灌注差异，亦属慢性栓塞性肺动脉高压表现。", "tr": "急慢性判定的核心是“血栓与管壁的夹角”和“管腔扩张还是缩小”：急性为锐角、管腔扩张；慢性为钝角、管腔缩小并伴钙化、网带与侧支。此判定直接影响溶栓与否的临床决策。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07155", "gs": ""}, {"id": "ZG-U07-0127", "t": "多选题", "s": "关于普通型间质性肺炎（UIP）的HRCT表现，符合诊断要求的是", "o": {"A": "病变以胸膜下、双肺基底部分布为主，且分布不均匀", "B": "可见蜂窝征，即胸膜下成簇分布、壁厚而清晰的囊状气腔", "C": "常伴牵拉性支气管扩张或牵拉性细支气管扩张", "D": "可有轻度磨玻璃影，但其范围一般不超过网格影", "E": "以上中肺野与支气管血管束周围分布为主，伴大量弥漫性磨玻璃影和广泛微结节"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-027", "kp": "UIP型间质性肺病HRCT诊断标准", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：胸膜下、基底部为主且分布不均（异质性）是UIP分布学特征。B正确：蜂窝征为UIP型的确定性征象，表现为胸膜下成层排列、直径多3~10mm、壁清晰的小囊。C正确：牵拉性支气管/细支气管扩张反映纤维化牵拉，是UIP及可能UIP型的重要构成。D正确：UIP可有少量磨玻璃影，但必须以网格影与蜂窝为主；磨玻璃范围超过网格提示其他类型。【为什么错】E错误：上中肺野为主、支气管血管束周围分布、广泛磨玻璃与大量微结节均属“提示替代诊断”的特征，见于非特异性间质性肺炎、过敏性肺炎、结节病等，与UIP型不符。", "tr": "UIP判读遵循“分布＋征象”双要素。特别注意区分蜂窝征与牵拉性支扩、与肺气肿：蜂窝为成簇成层的厚壁小囊；小叶中心型肺气肿为无壁低密度区且多分布于上肺。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0128", "t": "单选题", "s": "HRCT上出现两肺弥漫性、光滑的小叶间隔增厚，伴双侧胸腔积液与心影增大，最符合的诊断是", "o": {"A": "心源性肺水肿（间质期）", "B": "结节病", "C": "肺泡蛋白沉积症", "D": "特发性肺纤维化", "E": "急性粟粒型肺结核"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-028", "kp": "小叶间隔增厚的鉴别", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】A正确：左心功能不全时液体首先积聚于小叶间隔与支气管血管周围间质，HRCT表现为光滑、均匀的小叶间隔增厚（对应胸片上的Kerley B线），常伴支气管血管束增粗、胸腔积液、心影增大及上肺血流重新分布。【为什么错】B错误：结节病表现为沿淋巴管分布的结节，使小叶间隔与胸膜下呈串珠状、结节状增厚，且以上中肺野与肺门周围为主，伴对称性肺门淋巴结肿大。C错误：肺泡蛋白沉积症为磨玻璃影与小叶间隔增厚叠加形成的“铺路石征”，边界清楚呈地图样，一般无胸腔积液与心影增大。D错误：特发性肺纤维化以胸膜下网格、蜂窝为主，小叶间隔增厚不规则并伴结构扭曲。E错误：急性粟粒型肺结核为弥漫随机分布的粟粒结节，非小叶间隔增厚。", "tr": "小叶间隔增厚形态学分类是快速鉴别的钥匙：光滑增厚多为心源性水肿或癌性淋巴管炎早期；结节状增厚提示癌性淋巴管炎或结节病；不规则增厚伴结构扭曲提示纤维化。", "bk": "正高", "ref": {"篇": "胸部", "章": "纵隔疾病", "节": "纵隔疾病的鉴别诊断", "页": 153}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0129", "t": "共用题干题", "s": "结合上述情景，按传统三分法，前纵隔最常见的肿瘤不包括", "o": {"A": "胸腺瘤", "B": "畸胎瘤", "C": "胸骨后甲状腺肿", "D": "淋巴瘤", "E": "神经源性肿瘤"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-029", "kp": "纵隔分区与常见肿瘤", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】E为不属于前纵隔者，故为本题答案：神经源性肿瘤（神经鞘瘤、神经纤维瘤、节细胞神经瘤等）起自脊柱旁交感链或肋间神经，位于后纵隔（椎旁区），可伴椎间孔扩大、肋骨压迫吸收。【为什么错】A、B、C、D均属前纵隔常见占位，可归纳为“4T”：胸腺瘤（Thymoma）、畸胎瘤（Teratoma）、胸骨后甲状腺肿（Thyroid）、淋巴瘤（Terrible lymphoma）。其中胸腺瘤最常见并可合并重症肌无力；畸胎瘤含脂肪与钙化；甲状腺肿与颈部腺体相连且平扫密度较高；淋巴瘤多为融合的分叶状肿块并包绕大血管。", "tr": "注意分区体系差异：传统Felson三分法以气管前缘与心脏后缘、椎体前缘1cm为界；ITMIG新分区将纵隔分为血管前区、内脏区与椎旁区。考试常用传统三分法，但需知晓新分区名称。", "bk": "正高", "ref": {"篇": "胸部", "章": "胸部创伤", "节": "纵隔气肿及血肿", "页": 138}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07149", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-0130", "t": "多选题", "s": "关于肥厚型心肌病的心脏MRI表现，描述正确的是", "o": {"A": "舒张末期左室最大室壁厚度≥15mm，多呈非对称性室间隔肥厚", "B": "电影序列可显示二尖瓣前叶收缩期前向运动（SAM征）及左室流出道血流加速的低信号射流", "C": "钆延迟强化常见于肥厚节段的壁中层以及室间隔与右室游离壁上下交界处", "D": "延迟强化范围越大提示预后越差，可作为危险分层的参考指标", "E": "延迟强化多呈心内膜下或透壁分布，且严格符合冠状动脉供血区"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-030", "kp": "肥厚型心肌病MRI表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (3)MR诊断要点", "ex": "【为什么对】A正确：成人无其他致肥厚原因时，最大室壁厚度≥15mm（有明确家族史者≥13mm）为诊断阈值，最常见形态为非对称性室间隔肥厚。B正确：平衡稳态自由进动电影序列可动态显示SAM征及流出道梗阻所致的湍流低信号射流。C正确：肥厚型心肌病的延迟强化典型分布为肥厚心肌壁中层斑片状及右室插入点，反映心肌纤维化与排列紊乱。D正确：延迟强化范围（通常以占左室心肌质量15%为界）与心源性猝死风险相关，是重要的危险分层信息。【为什么错】E错误：心内膜下或透壁分布且符合冠脉供血区，是缺血性（心肌梗死）延迟强化的模式，与肥厚型心肌病的非缺血性分布规律相反。", "tr": "扫描技术上应注意：肥厚型心肌病评估必须包含左室短轴全覆盖电影以测量最大室壁厚度，若仅扫长轴易低估肥厚部位；心尖肥厚型需加扫长轴与心尖专用层面，否则易漏诊。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0131", "t": "单选题", "s": "心脏MRI钆延迟强化（LGE）呈心外膜下与壁中层分布、不符合任何冠状动脉供血区，最提示", "o": {"A": "急性心肌梗死", "B": "陈旧性透壁性心肌梗死", "C": "非缺血性心肌病变（如心肌炎、扩张型心肌病等）", "D": "冠状动脉慢性完全闭塞伴侧支供血", "E": "心肌顿抑"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-031", "kp": "延迟强化模式的缺血与非缺血鉴别", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (3)MR诊断要点", "ex": "【为什么对】C正确：心肌缺血性坏死自心内膜下向心外膜呈“波前”式扩展，故缺血性LGE必然累及心内膜下并符合冠脉供血区；而心外膜下或壁中层分布、跨越冠脉供血区边界的强化，是非缺血性心肌损伤的标志，常见于心肌炎（下侧壁心外膜下）、扩张型心肌病（室间隔壁中层线状）、结节病等。【为什么错】A错误：急性心肌梗死为心内膜下或透壁强化，可伴微血管阻塞形成的强化区内无强化核心。B错误：陈旧透壁梗死呈室壁变薄的透壁性强化，同样起自心内膜下。D错误：慢性完全闭塞伴侧支者仍为缺血性损伤模式，强化仍以心内膜下为主。E错误：心肌顿抑为可逆性功能障碍，心肌细胞膜完整、无纤维化，LGE呈阴性。", "tr": "口诀式记忆：“碰到心内膜就想缺血，避开心内膜就想非缺血”。另需牢记LGE阴性但室壁运动异常提示顿抑或冬眠心肌，属可存活心肌，与瘢痕的鉴别直接影响血运重建决策。", "bk": "正高", "ref": null, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0132", "t": "案例分析题", "s": "患者男性，59岁，2年前因急性前壁心肌梗死行溶栓治疗，近期活动后气促加重，超声心动图示前壁及心尖部运动减弱、左室射血分数38%。心内科拟行血运重建，术前需评估该区域心肌是否仍具存活性，以判断再血管化能否改善心功能，遂申请心脏MRI钆延迟强化检查。设备为1.5T，患者为窦性心律、心率72次/分且规整，可稳定屏气约12秒，肾小球滤过率正常，无钆对比剂使用禁忌。作为技师，下列关于延迟强化扫描的技术实施，正确的是", "o": {"A": "静脉注射钆对比剂后延迟约10~15分钟采集，采用心电门控反转恢复扰相梯度回波序列，并通过TI扫描（Look-Locker）选择使正常心肌信号被抑制为最低的反转时间", "B": "注药后立即采集，以捕捉对比剂首过高峰", "C": "反转时间固定设为800ms，无需个体化调整", "D": "采用自旋回波T2WI序列采集延迟图像，对瘢痕最敏感", "E": "在自由呼吸下采集单次激发图像，无需心电门控"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHE-032", "kp": "心肌延迟强化扫描技术", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (3)MR诊断要点", "ex": "【为什么对】A正确：钆对比剂在细胞外间隙扩大、清除延缓的瘢痕组织内蓄积，需延迟10~15分钟使正常心肌与瘢痕的对比度达到最佳。采集使用心电门控（舒张中期）的反转恢复扰相梯度回波序列，屏气完成；核心是通过Look-Locker/TI scout 选择正常心肌被“调零”的反转时间（1.5T常在200~300ms并随时间延长而增加），此时瘢痕呈明亮高信号，对比最强。相位敏感反转恢复（PSIR）可降低对TI精确度的依赖。【为什么错】B错误：注药即刻为首过灌注期，正常与瘢痕心肌均强化，无法区分。C错误：TI必须个体化，且随对比剂清除逐渐延长；固定800ms会使正常心肌未被抑制，瘢痕对比丧失。D错误：T2WI反映的是心肌水肿（急性损伤），并非延迟强化的成像原理，不能评估纤维瘢痕。E错误：无心电门控与屏气会产生严重的心脏搏动与呼吸伪影，无法满足薄层高对比要求。", "tr": "最常见的技术失误是TI选择不当：TI过短时正常心肌反而比瘢痕更亮甚至出现信号翻转，容易被误读为“无强化”。若不确定，应改用PSIR序列并复查TI scout。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0133", "t": "共用题干题", "s": "结合上述情景，肝细胞癌在多期增强CT/MRI上典型的“快进快出”强化表现是指", "o": {"A": "动脉期明显强化，门静脉期及延迟期强化程度低于周围肝实质，可伴延迟强化的假包膜", "B": "动脉期无强化，门静脉期与延迟期渐进性充填", "C": "动脉期边缘结节样强化，延迟期向心性完全填充", "D": "三期均呈低密度、无强化", "E": "动脉期明显强化，门静脉期与延迟期持续高于肝实质"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-033", "kp": "肝细胞癌典型强化模式", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：肝细胞癌在癌变过程中门静脉供血逐渐减少、肝动脉新生血管增多，故动脉期明显强化（非环形高强化）；门静脉期正常肝实质由门静脉大量供血而密度上升，肿瘤因缺乏门静脉供血且引流静脉丰富，相对呈低密度即“廓清”。纤维假包膜在延迟期呈环形强化，是重要的辅助征象。【为什么错】B错误：动脉期无强化、渐进充填是纤维性病变或部分胆管细胞癌的特点。C错误：边缘结节样强化并向心性填充是海绵状血管瘤的典型模式。D错误：三期均无强化提示囊肿或坏死性病变。E错误：动脉期强化后持续高于肝实质，更符合局灶性结节增生（FNH）或部分富血供良性病变的“快进等出/慢出”表现。", "tr": "“快进快出”成立的前提是三期扫描时相准确：动脉晚期（注药后约30~35秒）过早会遗漏强化峰、过晚则廓清判断失真。技师若时相把握不准，会直接造成典型征象无法显现。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07151", "gs": ""}, {"id": "ZG-U07-0134", "t": "案例分析题", "s": "患者女性，41岁，体检超声发现肝右叶一约4cm稍高回声占位，无腹痛、消瘦等症状。上腹部CT三期增强（动脉期、门静脉期及门静脉期后约90秒）示病灶动脉期边缘呈多个结节状明显强化、强化程度接近同层腹主动脉，门静脉期强化范围向中心推进但中央区仍未完全充填，90秒时中心仍见小片低密度，报告医师认为强化模式介于血管瘤与富血供恶性肿瘤之间，难以定性。患者无乙肝病史，甲胎蛋白与肝功能均正常。为明确诊断，下列补充检查技术最恰当的是", "o": {"A": "加做3~10分钟延迟期扫描，并结合MRI重T2加权（长TE）序列观察病灶是否呈持续显著高信号的“灯泡征”", "B": "加做CT平扫，通过平扫密度直接定性", "C": "缩短动脉期延迟时间重复扫描，以捕捉更早的强化峰", "D": "改行CT灌注成像测量肝血流量以定性", "E": "行DSA肝动脉造影，作为该病灶定性的首选检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-034", "kp": "肝血管瘤延迟扫描与重T2技术", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】A正确：本例强化模式高度提示海绵状血管瘤（“早出晚归”）。血管瘤血窦内血流缓慢，充填过程可长达数分钟，常规90秒延迟不足以显示完全填充，必须延长至3~10分钟。此外，血管瘤内自由水含量高、T2弛豫时间极长，在长TE的重T2加权图像上仍保持显著高信号（灯泡征），而多数恶性肿瘤信号随TE延长明显衰减，此为特异性极高的鉴别方法。【为什么错】B错误：平扫上血管瘤与其他实性病灶均呈低密度，无鉴别价值。C错误：缩短动脉期只会更早采集，无助于观察延迟充填。D错误：CT灌注辐射剂量高、后处理复杂，对典型血管瘤的定性并非必要手段。E错误：DSA为有创检查，不作为肝内良性占位定性的首选，仅在介入治疗或无创检查无法定论时考虑。", "tr": "常见失误是“三期做完就下结论”。凡见到边缘结节样强化未完全填充者，应主动追加延迟扫描；同时应记住：小血管瘤可在动脉期即快速均匀强化，酷似富血供恶性肿瘤，此时重T2与延迟持续强化是关键鉴别依据。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0135", "t": "多选题", "s": "关于肝硬化的CT与MRI表现，描述正确的是", "o": {"A": "肝表面呈结节状凹凸不平，肝裂与肝门区间隙增宽", "B": "尾状叶相对增大，尾状叶与右叶横径比值增大（常以0.65为参考阈值）", "C": "可见脾大、食管胃底静脉曲张、腹水等门静脉高压继发改变", "D": "再生结节因含铁及网状纤维，T2WI多呈等或低信号；若结节T2WI呈高信号并伴动脉期强化，应警惕癌变", "E": "肝硬化时肝各叶均匀等比例缩小，各叶体积比例保持正常"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-035", "kp": "肝硬化影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：再生结节与纤维间隔使肝缘呈波浪状、结节状，肝实质萎缩使肝裂、胆囊窝及肝门区脂肪间隙增宽。B正确：尾状叶血供与静脉回流相对独立，肝硬化时代偿性增大，尾右叶比增大是经典定量指标。C正确：门静脉高压继发脾大、侧支循环开放与腹水。D正确：再生结节含铁与纤维成分，T2WI呈等或低信号；出现T2高信号伴动脉期强化的结节提示由异型增生结节向肝细胞癌演变。【为什么错】E错误：肝硬化的形态改变是“不均衡”的——典型为右叶与方叶（左内叶）萎缩、左外叶与尾状叶代偿性增大，各叶比例明显失调，而非均匀等比例缩小。", "tr": "E以“均匀”“正常比例”设陷。技术层面提示：肝硬化背景下筛查小肝癌，应保证动脉晚期时相准确并加用肝细胞特异性对比剂的肝胆期，以提高微小病灶检出率。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏弥漫性病变", "节": "肝硬化", "页": 187}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0136", "t": "共用题干题", "s": "结合上述情景，单纯性肝囊肿最典型的影像学表现是", "o": {"A": "CT呈水样低密度、边界锐利，MRI T1WI低信号、T2WI显著均匀高信号，增强各期均无强化", "B": "CT呈稍高密度，增强后动脉期明显强化", "C": "T1WI高信号、T2WI低信号，增强后边缘强化", "D": "CT呈脂肪密度，MRI脂肪抑制后信号明显下降", "E": "T2WI呈极低信号，增强后延迟强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-036", "kp": "肝囊肿影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】A正确：单纯性肝囊肿内容物为浆液，CT值接近水（约0~20HU），壁菲薄不可见，边界锐利；MRI上表现为长T1长T2信号，T2WI（尤其重T2）呈显著均匀高信号，增强各期囊内与囊壁均无强化，是最可靠的定性依据。【为什么错】B错误：稍高密度伴动脉期明显强化提示富血供实性病灶。C错误：T1高T2低多为出血、高蛋白或含铁病变。D错误：脂肪密度并可被脂肪抑制者为脂肪瘤或含脂病变（如血管平滑肌脂肪瘤）。E错误：T2极低信号伴延迟强化提示纤维性病变或钙化。", "tr": "囊肿的“无强化”必须通过同一层面、同一窗宽窗位对照平扫与增强的CT值来确认。小囊肿受部分容积效应影响可测出假性强化，此时应改用薄层重建或参考MRI重T2图像。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07150", "gs": ""}, {"id": "ZG-U07-0137", "t": "共用题干题", "s": "结合上述情景，关于急性胰腺炎的CT表现与严重程度评估，描述正确的是", "o": {"A": "增强扫描胰腺实质内无强化区提示胰腺坏死，坏死范围是评估严重程度的重要指标", "B": "Balthazar CT分级中，胰周脂肪间隙模糊、条索状渗出属于C级", "C": "CT严重指数由炎症分级评分与坏死程度评分相加得出，总分越高提示预后越差", "D": "急性坏死物积聚与包裹性坏死的鉴别依赖于是否形成完整的强化包壁及发病时间（一般以4周为界）", "E": "水肿型胰腺炎必须行增强扫描才能诊断，平扫无任何提示价值"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-037", "kp": "急性胰腺炎CT评估", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：坏死区微循环中断，增强后不强化，与周围强化的存活胰腺形成对比，是判断坏死性胰腺炎的核心依据。B正确：Balthazar分级中A为胰腺正常、B为胰腺局灶或弥漫性增大、C为胰腺异常伴胰周脂肪炎性改变、D为单个积液区、E为两个及以上积液区或胰腺/胰周积气。C正确：CT严重指数为炎症分级评分（0~4分）与坏死程度评分（无坏死0分、坏死小于30%为2分、30%~50%为4分、大于50%为6分）之和，分值越高并发症率与病死率越高。D正确：发病4周内为急性坏死物积聚，4周后形成完整强化壁者为包裹性坏死，此分类直接影响引流时机。【为什么错】E错误：平扫可显示胰腺弥漫性增大、密度减低、胰周脂肪间隙模糊、积液及出血高密度等，具有明确诊断价值；对肾功能不全或对比剂禁忌者，平扫仍是重要手段，只是无法评估坏死。", "tr": "E以“必须”“无任何价值”双重绝对化设陷。另一实务要点：过早（发病72小时内）行增强CT可能低估坏死范围，且理论上可能加重胰腺微循环障碍，评估坏死一般建议在发病72小时后进行。", "bk": "正高", "ref": {"篇": "腹部", "章": "胰腺", "节": "急性胰腺炎", "页": 196}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ07143", "gs": ""}, {"id": "ZG-U07-0138", "t": "单选题", "s": "胰头癌在CT/MRI上出现的“双管征”是指", "o": {"A": "胆总管与主胰管同时扩张并在胰头肿块处截断", "B": "肝内左右肝管同时扩张", "C": "主胰管与副胰管同时扩张", "D": "胆总管与十二指肠腔同时扩张", "E": "门静脉与脾静脉同时扩张"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-038", "kp": "胰头癌双管征", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：胰头钩突以上的肿块同时侵犯或压迫走行于胰头内的胆总管下段与主胰管，造成两者上游同时扩张并在肿块层面突然截断，形成“双管征”，是胰头癌的重要间接征象，常伴远端胰腺实质萎缩。胰头癌为乏血供肿瘤，在胰腺实质期呈明显低密度，延迟期因富含纤维间质可轻度渐进强化。【为什么错】B错误：仅肝内胆管扩张提示肝门部或更高位梗阻，不构成双管征。C错误：主胰管与副胰管同时扩张并非该征定义。D错误：十二指肠腔扩张属肠管改变，与胆胰管扩张无关。E错误：门静脉与脾静脉扩张属门静脉高压征象。", "tr": "双管征并非胰头癌特有，壶腹癌、胆总管下段癌、慢性胰腺炎伴纤维化亦可出现。鉴别要点在于是否存在胰头低强化肿块、胰周脂肪浸润与血管包绕。技术上应采用胰腺实质期（注药后约40~45秒）薄层扫描以获得最大瘤-腺对比。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0139", "t": "多选题", "s": "关于胆道梗阻的影像诊断与MRCP技术，描述正确的是", "o": {"A": "肝内胆管明显扩张呈“软藤征”，提示梗阻部位较低或梗阻程度较重", "B": "MRCP利用重T2加权效应突出静止或缓慢流动的液体，无需注射对比剂即可显示胆胰管全貌", "C": "胆总管结石在MRCP上表现为高信号胆汁衬托下的低信号充盈缺损，常呈杯口状或新月形", "D": "恶性梗阻多表现为胆管突然截断、断端不规则或呈“鼠尾状”狭窄", "E": "MRCP空间分辨率高于薄层T2WI原始图像，因此仅需保存最大密度投影重建图，无需保留原始薄层图像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-039", "kp": "胆道梗阻诊断与MRCP技术", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】A正确：肝内胆管重度扩张、迂曲呈软藤状，多见于低位或长期严重梗阻。B正确：MRCP采用长TE重T2加权，使实质与流动血液信号被抑制，仅胆汁、胰液等静止液体呈高信号，属无创、无对比剂的水成像技术。C正确：结石不含质子信号，在高信号胆汁背景中呈低信号充盈缺损，边缘可呈杯口状。D正确：恶性梗阻断端不规则、突然截断或呈鼠尾状渐细，且常伴软组织肿块与双管征。【为什么错】E错误：最大密度投影图会因投影叠加掩盖小结石与细小充盈缺损，必须结合原始薄层（二维厚层或三维薄层）图像逐层观察，原始图像不可省略。", "tr": "MRCP的常见陷阱：胃十二指肠内液体、腹水可产生高信号干扰（可通过口服阴性对比剂或负性造影剂抑制）；呼吸运动与磁场不均匀可造成假性狭窄。判读必须MIP与原始层面对照。", "bk": "正高", "ref": {"篇": "腹部", "章": "胆道", "节": "胆囊炎", "页": 189}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0140", "t": "单选题", "s": "脾梗死在增强CT上最典型的表现是", "o": {"A": "基底位于脾包膜、尖端指向脾门的楔形无强化低密度区", "B": "脾内圆形明显强化结节，延迟期呈等密度", "C": "脾脏弥漫性肿大伴均匀强化", "D": "脾门区多发钙化灶", "E": "脾内边缘结节样强化并向心填充"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-040", "kp": "脾梗死影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】A正确：脾动脉分支呈节段性分布且缺乏侧支吻合，一支闭塞后其供血区呈楔形（三角形）缺血坏死，基底朝向脾包膜、尖端指向脾门，增强后不强化，边界较清。慢性期可机化、萎缩并形成脾轮廓凹陷。【为什么错】B错误：圆形明显强化结节延迟等密度提示血管瘤或错构瘤等富血供病灶。C错误：脾弥漫肿大伴均匀强化见于门静脉高压性脾大、感染或血液系统疾病。D错误：脾门区钙化多为陈旧肉芽肿或脾动脉钙化。E错误：边缘结节样强化并向心填充是血管瘤的强化模式。", "tr": "脾脏动脉期本身呈“花斑样”不均匀强化（红髓与白髓血流速度不同），是正常现象，切勿误判为梗死或病变；应以门静脉期脾实质强化趋于均匀时判断有无真正的无强化区。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0141", "t": "共用题干题", "s": "结合上述情景，关于消化道穿孔与肠梗阻的腹部X线征象，描述正确的是", "o": {"A": "立位腹部平片见膈下新月形游离气体，是消化道穿孔的直接征象", "B": "机械性小肠梗阻可见小肠积气扩张、多个阶梯状气液平面", "C": "小肠扩张时黏膜环状皱襞横贯肠腔呈“鱼肋状”或“弹簧状”，结肠扩张则可见结肠袋", "D": "肠扭转绞窄时可出现“咖啡豆征”，闭袢内充满液体时可呈“假肿瘤征”", "E": "麻痹性肠梗阻表现为小肠局限性扩张而结肠完全无气"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-041", "kp": "消化道穿孔与肠梗阻X线征象", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：游离气体上浮至膈下，于立位片呈线状或新月形透亮影，是穿孔的直接证据。B正确：机械性梗阻近端肠管积气积液扩张，气液分层形成高低不等的阶梯状液平。C正确：小肠黏膜环状皱襞连续横贯肠腔形成鱼肋/弹簧样，结肠袋则不横贯全腔，是判断扩张肠管属小肠或结肠的关键。D正确：乙状结肠扭转形成闭袢呈咖啡豆征；闭袢内全为液体时呈边界清楚的软组织密度肿块样影，即假肿瘤征，提示绞窄。【为什么错】E错误：麻痹性肠梗阻的特点是小肠与结肠普遍、广泛积气扩张（全消化道张力低下），而非小肠局限扩张伴结肠无气；后者更符合机械性梗阻的表现。", "tr": "机械性与麻痹性梗阻的鉴别在于“扩张范围是否连续到结肠直肠”。技术要点：立位摄影须站立或坐位保持15~20分钟后曝光，游离气体量少时才能上浮显示；否则容易假阴性。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07146", "gs": ""}, {"id": "ZG-U07-0142", "t": "案例分析题", "s": "患者男性，70岁，有长期口服非甾体抗炎药史，2小时前突发上腹部剧烈疼痛并迅速波及全腹，查体全腹压痛、腹肌板样紧张、肝浊音界缩小。血压92/58mmHg，心率108次/分，临床高度怀疑上消化道穿孔并腹膜炎。因剧痛与低血压，患者无法站立或端坐，也难以长时间保持坐位等待。急诊申请床旁腹部X线检查以寻找腹腔游离气体，为紧急手术提供依据。作为技师，在现有条件下最合适的摄影方案是", "o": {"A": "采用左侧卧位水平方向投照，使游离气体聚集于右侧腹壁与肝脏之间，摄影前尽可能保持该体位数分钟", "B": "采用仰卧前后位垂直投照，游离气体最易在此位置显示", "C": "采用右侧卧位水平投照，使气体积聚于脾与左侧腹壁之间以避开肝脏", "D": "改行常规腹部超声，因X线对游离气体不敏感", "E": "口服硫酸钡后摄片，以直接显示穿孔部位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABD-042", "kp": "疑似穿孔患者的替代摄影体位", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：显示游离气体的必要条件是“水平方向投照”加“气体有足够时间上浮”。不能站立者应取左侧卧位，此时右侧腹在上，游离气体上浮至肝脏外缘与右侧腹壁之间，肝脏均匀的软组织密度为气体提供了良好衬托背景，检出率高。为保证气体充分移位，摄影前应保持体位数分钟。【为什么错】B错误：仰卧位垂直投照时气体位于腹腔前方、与肠腔内气体重叠，难以分辨，是漏诊游离气体的经典原因。C错误：右侧卧位时气体上浮至左侧腹，与胃泡及结肠脾曲气体重叠，难以区分。D错误：气体强烈反射声波，超声对少量游离气体的定位与定量不如水平投照X线可靠，且本题要求X线方案。E错误：疑似穿孔为硫酸钡的禁忌证，钡剂漏入腹腔可引起严重钡剂性腹膜炎；如确需造影应使用水溶性碘对比剂。", "tr": "两个必考点：一是“不能站立者用左侧卧位水平投照”，二是“疑似穿孔禁用硫酸钡”。另需记住膈下游离气体的最低检出量在标准立位技术下约1~2ml，体位与等待时间比曝光条件更关键。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0143", "t": "共用题干题", "s": "结合上述情景，子宫腺肌症与子宫肌瘤在MRI上最重要的鉴别点是", "o": {"A": "腺肌症表现为结合带弥漫性增厚（多超过12mm）、边界不清，其内可见点状T2高信号；肌瘤为边界清楚的T2低信号肿块伴假包膜", "B": "腺肌症表现为边界清楚的圆形肿块，肌瘤呈弥漫浸润", "C": "两者均使结合带变薄，仅凭强化程度区分", "D": "腺肌症在T1WI呈明显高信号，肌瘤呈明显低信号", "E": "腺肌症必然伴有卵巢囊肿，肌瘤则否"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-043", "kp": "子宫腺肌症与肌瘤鉴别", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：腺肌症为子宫内膜腺体与间质侵入肌层，T2WI上表现为结合带弥漫性或局限性增厚（大于12mm可诊断，8~12mm为可疑），边界模糊，其内可见异位内膜与小囊形成的点状高信号，子宫呈球形增大。子宫肌瘤为平滑肌来源的边界清楚肿块，T2WI呈均匀低信号，周围可有假包膜形成的高信号环，占位效应明确。【为什么错】B错误：两者形态特征完全说反。C错误：腺肌症的核心征象正是结合带增厚而非变薄，且强化程度不是主要鉴别依据。D错误：腺肌症T1WI多为等信号，仅出血灶可呈点状高信号，并非弥漫明显高信号。E错误：腺肌症与卵巢囊肿无必然伴随关系，“必然”属绝对化错误表述。", "tr": "结合带（联合带）是子宫肌层内层，T2WI低信号，评估必须使用高分辨T2WI，且需避开月经周期与子宫收缩造成的假性增厚（一过性收缩可模拟局限性腺肌症，重复扫描可鉴别）。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "子宫腺肌症", "页": 246}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07141", "gs": ""}, {"id": "ZG-U07-0144", "t": "多选题", "s": "关于宫颈癌MRI分期评估的技术与征象，描述正确的是", "o": {"A": "高分辨T2WI应采用垂直于宫颈管长轴的斜轴位，以准确评估宫颈基质环", "B": "宫颈低信号纤维基质环完整，提示无宫旁组织浸润", "C": "基质环中断并见不规则信号影突入宫旁脂肪，提示宫旁受侵", "D": "DWI有助于显示原发灶范围与转移淋巴结，但不能单独用于分期", "E": "只要宫旁脂肪间隙内出现条索状影，即可确诊宫旁浸润"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-044", "kp": "宫颈癌MRI分期要点", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：宫颈管常呈前倾前屈，常规横断面会斜切基质环造成假性中断，必须以矢状面定位、扫垂直于宫颈管长轴的斜轴位。B正确：完整的低信号纤维基质环是阻止肿瘤外侵的解剖屏障，环完整对排除宫旁浸润的阴性预测值高。C正确：环中断伴宫旁不规则软组织信号是宫旁受侵的直接征象，直接决定能否手术。D正确：DWI可提高小病灶与淋巴结检出率，但存在假阳性（炎症、坏死），须与高分辨T2WI结合。【为什么错】E错误：宫旁条索影可由炎症、水肿、既往手术或血管断面造成，特异性低；必须结合基质环是否中断及是否存在结节样软组织影综合判断。", "tr": "扫描方位是本题的技术核心：斜轴位不到位造成的“假性基质环中断”是导致过度分期的常见原因。另注意宫颈癌分期以国际妇产科联盟标准为准，MRI主要用于评估肿瘤大小、宫旁与邻近器官侵犯。", "bk": "正高", "ref": null, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0145", "t": "单选题", "s": "卵巢成熟性囊性畸胎瘤在MRI上区别于子宫内膜异位囊肿的关键征象是", "o": {"A": "T1WI高信号在脂肪抑制序列上信号明显减低，且脂-水界面可见化学位移伪影", "B": "T1WI高信号在脂肪抑制序列上信号无明显变化", "C": "T2WI呈明显低信号即所谓“阴影征”", "D": "增强扫描囊壁明显强化，囊内容物亦强化", "E": "病灶内可见流空血管影"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-045", "kp": "卵巢畸胎瘤信号特征", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：成熟性畸胎瘤含成熟脂肪组织，T1WI呈显著高信号，加脂肪抑制后信号明显下降，这是确认脂肪成分、从而定性畸胎瘤的决定性方法；此外脂肪与水的进动频率差异在频率编码方向上造成化学位移伪影（脂-水界面一侧黑边、一侧白边），亦为含脂证据。CT上可见脂肪密度、钙化或牙齿及脂-液平面。【为什么错】B错误：脂肪抑制后信号不下降者为出血或高蛋白，符合子宫内膜异位囊肿而非畸胎瘤。C错误：T2WI信号减低的“阴影征”正是内膜异位囊肿（陈旧血液中高浓度铁与蛋白）的特征。D错误：畸胎瘤囊内容物不强化，此描述无鉴别意义且不准确。E错误：流空血管影提示富血供实性肿瘤。", "tr": "两类病变均在T1WI呈高信号，唯一可靠的分水岭是“加脂肪抑制后信号是否掉下来”。因此凡盆腔发现T1高信号囊性灶，必须加扫脂肪抑制T1WI，这是技师必须掌握的补充序列决策。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢畸胎瘤", "页": 240}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0146", "t": "共用题干题", "s": "结合上述情景，卵巢子宫内膜异位囊肿（巧克力囊肿）在MRI上的典型信号表现是", "o": {"A": "T1WI低信号、T2WI高信号，边界清楚", "B": "T1WI高信号且脂肪抑制后仍为高信号，T2WI信号减低呈“阴影征”", "C": "T1WI等信号、T2WI极低信号，增强明显强化", "D": "T1WI高信号、脂肪抑制后信号明显下降", "E": "T1WI与T2WI均为极低信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-046", "kp": "子宫内膜异位囊肿信号特征", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】B正确：囊内为反复出血形成的陈旧血液，含高浓度正铁血红蛋白与蛋白，缩短T1故T1WI高信号；因非脂肪成分，脂肪抑制后信号不下降。囊内高浓度铁与蛋白造成T2弛豫缩短，T2WI信号自上而下逐渐减低呈“阴影征”，是较具特异性的表现，常为多发、双侧并伴粘连。【为什么错】A错误：单纯长T1长T2信号为浆液性囊肿表现。C错误：T2极低伴明显强化提示纤维性实性病变。D错误：脂肪抑制后明显下降者为畸胎瘤的脂肪成分。E错误：T1、T2均极低信号多见于钙化、含铁血黄素沉积或高度纤维化组织。", "tr": "“T1高＋T2低”是本病的信号组合钥匙，与畸胎瘤（T1高＋脂肪抑制后低）和单纯出血性囊肿（T2多不减低）不同。合并深部浸润型内异症时应加扫高分辨T2WI观察直肠子宫陷凹粘连。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07139", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-0147", "t": "共用题干题", "s": "结合上述情景，关于前列腺多参数MRI与PI-RADS评估，描述正确的是", "o": {"A": "外周带病灶以DWI/ADC为主导序列，移行带病灶以T2WI为主导序列", "B": "前列腺癌在T2WI上多呈局灶性低信号，与周围带正常的高信号形成对比", "C": "癌灶在高b值DWI上呈明显高信号，相应ADC图呈低信号", "D": "前列腺穿刺活检后应间隔一定时间（一般建议6周以上）再行MRI，以减少出血对判读的干扰", "E": "动态增强序列是所有分区评分的决定性序列，其权重高于T2WI与DWI"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-047", "kp": "前列腺mpMRI与PI-RADS", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：PI-RADS规定外周带以DWI评分为主导、移行带以T2WI评分为主导，这是评分体系的基本框架。B正确：正常外周带富含腺管与液体呈T2高信号，癌灶细胞密集、腺腔减少而呈局灶低信号，形态可呈边界不清的透镜状或不规则形。C正确：癌组织细胞密度高、细胞外间隙减小，水分子弥散受限，故高b值（一般要求达到或计算至1400s/mm²以上）DWI高信号、ADC值降低。D正确：穿刺后出血在T1WI呈高信号并可造成T2与DWI判读困难，间隔6周以上可显著减少干扰。【为什么错】E错误：动态增强在PI-RADS中仅起有限的“辅助升级”作用——主要用于外周带DWI评分为3分时，若动态增强阳性则升为4分；它不是主导序列，权重低于T2WI与DWI。", "tr": "常见误区是把动态增强当作前列腺MRI的核心。实际上多参数MRI的“主参数”是T2WI与DWI，动态增强是次要参数。检查前应排空直肠、必要时使用抗蠕动药以减少肠蠕动伪影对DWI的影响。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "前列腺癌", "页": 236}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ07135", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-0148", "t": "共用题干题", "s": "结合上述情景，患者男性，67岁，体检发现血清前列腺特异性抗原8.6ng/ml，游离/总PSA比值偏低，直肠指检未触及明显硬结，超声示前列腺体积约45ml。泌尿外科拟先行前列腺多参数MRI，依据PI-RADS评分决定是否行靶向融合穿刺以及穿刺靶点。设备为3.0T，患者近1周因便秘排便不畅，既往从未行前列腺穿刺活检，无髋关节假体、心脏起搏器等MRI禁忌证，肾功能正常。作为技师，下列检查前准备与序列安排最恰当的是", "o": {"A": "检查前排空直肠、必要时按临床医嘱使用抗蠕动药物；序列包括三平面高分辨T2WI（层厚约3mm）、多b值DWI（含高b值≥1400s/mm²）与ADC图，以及动态增强扫描", "B": "仅采集横断面T2WI，层厚8mm，不做DWI以缩短检查时间", "C": "为提高信噪比，DWI只采集b值为0与50s/mm²两档即可", "D": "不必处理肠道准备，直肠内粪便与气体对图像无影响", "E": "以动态增强作为唯一采集序列，其余序列可省略"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-048", "kp": "前列腺mpMRI检查技术准备", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：直肠内粪便与气体会在气-组织界面产生磁敏感伪影，严重降低回波平面DWI质量并造成图像变形，故应排空直肠；肠蠕动伪影可用抗蠕动药物减轻。序列上必须具备三平面高分辨T2WI（评估移行带与包膜、精囊侵犯）、多b值DWI并计算或直接采集高b值图像与ADC图（评估外周带），以及动态增强（用于评分3分病灶的升级判定），三者共同构成多参数MRI。【为什么错】B错误：层厚8mm部分容积效应严重，且缺少DWI则外周带无法评分，不符合PI-RADS技术要求。C错误：仅有低b值无法体现弥散受限，也无法准确计算ADC，必须包含足够高的b值。D错误：直肠内容物与气体是前列腺DWI最主要的伪影来源，忽视会导致图像不可用。E错误：动态增强不能替代T2WI与DWI，单独使用无法完成PI-RADS评分。", "tr": "技术要点在于“伪影来源决定检查前准备”。3.0T下磁敏感伪影比1.5T更明显，直肠准备与相位编码方向选择尤为重要；必要时可采用降低回波间隔或使用并行采集来减轻变形。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "前列腺癌", "页": 236}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07135", "gs": ""}, {"id": "ZG-U07-0149", "t": "单选题", "s": "膀胱癌MRI分期中，判断肿瘤是否侵犯肌层最关键的观察内容是", "o": {"A": "T2WI上膀胱壁固有肌层低信号带是否连续完整，中断者提示肿瘤已侵犯肌层", "B": "肿瘤在T1WI上的信号高低", "C": "膀胱腔内是否存在气体", "D": "增强扫描肿瘤强化的绝对CT值", "E": "肿瘤基底部是否宽大，宽基底者一律为肌层浸润"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PEL-049", "kp": "膀胱癌MRI分期要点", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】A正确：膀胱固有肌层在高分辨T2WI上呈连续的低信号带，肿瘤多呈中等信号。低信号带完整提示肿瘤局限于黏膜与黏膜下层（非肌层浸润性，可行经尿道电切）；低信号带中断则提示肌层浸润（T2期及以上），需根治性治疗，是分期最关键的判断点。【为什么错】B错误：T1WI主要用于观察膀胱周围脂肪受侵与骨转移，对肌层判断价值有限。C错误：膀胱腔内气体多为导尿或产气菌感染所致，与分期无关。D错误：MRI不使用CT值这一密度单位，表述本身即错误。E错误：宽基底虽提示浸润风险增加，但不能一律判定为肌层浸润，须以低信号带是否中断为准，且“一律”属绝对化错误。", "tr": "检查前应适度充盈膀胱（过度充盈会使壁变薄、掩盖小病灶，过度空虚则壁增厚形成假阳性）。此外，经尿道电切术后局部水肿与肉芽可造成假性肌层中断，建议术后间隔数周复查。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "膀胱癌", "页": 237}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0150", "t": "单选题", "s": "Pfirrmann分级用于评价椎间盘退变，其分级主要依据的图像与观察指标是", "o": {"A": "矢状面T2WI上髓核信号强度、髓核与纤维环界限是否清晰、椎间隙高度", "B": "横断面CT上椎间盘的CT值与钙化程度", "C": "矢状面T1WI上终板骨髓信号改变", "D": "增强后椎间盘的强化程度", "E": "X线侧位片上椎体前缘骨赘的大小"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-050", "kp": "椎间盘退变Pfirrmann分级", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：Pfirrmann分级基于矢状面T2WI，综合三项指标：髓核信号强度（由高亮渐变为灰、黑）、髓核与纤维环界限（由清晰到消失）、椎间隙高度（由正常到塌陷）。Ⅰ级髓核均匀亮白、界限清楚、高度正常；Ⅱ级信号仍高但不均匀，可见水平带；Ⅲ级呈中等灰色、界限模糊、高度正常或轻度降低；Ⅳ级呈灰至黑色、界限消失、高度中度降低；Ⅴ级呈黑色、界限消失、椎间隙塌陷。【为什么错】B错误：CT值与钙化不是该分级依据，CT亦难以评估髓核含水量。C错误：终板骨髓信号改变属Modic分型（Ⅰ型水肿、Ⅱ型脂肪、Ⅲ型硬化），与Pfirrmann分级不同。D错误：正常椎间盘无血供，不以强化程度分级。E错误：骨赘属椎体退变征象，不用于椎间盘分级。", "tr": "极易与Modic分型混淆：Pfirrmann看“椎间盘本身”，Modic看“相邻终板与椎体骨髓”。二者常在同一份报告中出现，须分清各自的观察对象与序列依据。", "bk": "正高", "ref": {"篇": "骨与骨关节", "章": "脊柱退行性病变", "节": "椎间盘及椎骨的退变过程", "页": 285}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0151", "t": "共用题干题", "s": "结合上述情景，关于椎体压缩骨折新鲜与陈旧的鉴别以及良恶性判断，描述正确的是", "o": {"A": "新鲜骨折椎体内骨髓水肿，在脂肪抑制T2WI或STIR序列上呈高信号，T1WI呈低信号", "B": "陈旧骨折椎体骨髓信号恢复为正常脂肪信号，T1WI高信号、STIR低信号", "C": "椎体后缘向后膨隆、椎弓根受累及椎旁软组织肿块提示恶性病理性骨折", "D": "良性骨质疏松性压缩骨折可见带状水肿、清晰的骨折线，有时可见“裂隙征”（真空或液体征）", "E": "只要椎体呈楔形变，即可判断为新鲜骨折"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-051", "kp": "椎体压缩骨折新旧与良恶性鉴别", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：新鲜骨折伴骨髓水肿与出血，含水量增高，故T1WI低信号、脂肪抑制T2WI/STIR高信号，这是判断“责任椎”的核心依据。B正确：陈旧骨折骨髓修复为脂肪，信号回归正常。C正确：恶性者由肿瘤组织替代骨髓，常见椎体后缘凸隆、椎弓根侵犯（正位片“椎弓根征”消失）及椎旁软组织肿块。D正确：良性者水肿多呈紧邻终板的带状分布而非弥漫全椎体，可见清晰骨折线；骨坏死时出现裂隙征。【为什么错】E错误：楔形变仅说明椎体形态改变，陈旧骨折同样呈楔形；能否判断为新鲜必须依靠骨髓水肿信号，而非形态。", "tr": "X线与CT只能显示形态与骨小梁改变，无法区分新旧；MRI的脂肪抑制T2WI/STIR是唯一可靠手段。这一点在多节段压缩骨折患者中直接决定椎体成形术的靶椎选择。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07144", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-0152", "t": "案例分析题", "s": "患者女性，78岁，绝经30年，确诊骨质疏松症5年，1个月前有轻微跌倒史，近2周腰背痛明显加重，翻身与起坐时疼痛剧烈，叩击痛以下胸腰段为著。腰椎正侧位X线片示T12、L1、L3三个椎体呈不同程度楔形变，椎体前缘高度均有丢失，仅凭形态无法判断哪一节段为近期骨折。临床拟行经皮椎体成形术，需要在术前准确锁定引起症状的责任椎体。患者可平卧配合检查约20分钟，无心脏起搏器等MRI禁忌证。作为技师，最恰当的检查方案是", "o": {"A": "行腰椎MRI，必须包含矢状面短反转时间反转恢复（STIR）或脂肪抑制T2WI序列，以骨髓水肿高信号确定新鲜骨折椎体", "B": "行腰椎CT薄层扫描加矢状面重建，通过骨小梁形态判断新旧", "C": "重复腰椎正侧位X线片并加照过伸过屈位", "D": "行腰椎MRI但仅采集矢状面T1WI与T2WI，不加脂肪抑制序列", "E": "行腰椎MRI增强扫描，以强化程度判断新旧骨折"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-052", "kp": "责任椎体判定的序列选择", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：老年患者椎体骨髓以黄骨髓（脂肪）为主，常规T2WI上骨髓脂肪本身呈较高信号，会掩盖水肿信号；STIR或脂肪抑制T2WI抑制脂肪后，水肿呈醒目高信号，能敏感、特异地标记新鲜骨折椎体，是判定责任椎的标准序列。STIR基于T1值差异抑制脂肪，对磁场不均匀不敏感，在脊柱大范围扫描中稳定性优于频率选择性脂肪抑制。【为什么错】B错误：CT显示骨折线与骨皮质优秀，但无法反映骨髓水肿，陈旧与新鲜骨折的骨小梁形态可高度重叠。C错误：X线只能显示形态，动力位片用于评估不稳定，不能判断水肿。D错误：不加脂肪抑制时，黄骨髓高信号会掩盖水肿，极易漏判。E错误：增强扫描既非必要也不特异，新鲜骨折与肿瘤均可强化，且增加对比剂风险。", "tr": "技术要点是“脂肪抑制的必要性”：老年脊柱含大量黄骨髓，未抑脂的T2WI几乎无法识别水肿。此外STIR序列不应在注射钆对比剂后使用，因其会同时抑制强化组织的高信号。", "bk": "正高", "ref": {"篇": "基础概念（绪论）", "章": "基本概念（X线物理/对比剂/成像基础）", "节": "骨质疏松", "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0153", "t": "多选题", "s": "关于脊柱结核、化脓性脊柱炎与脊柱转移瘤的影像鉴别，描述正确的是", "o": {"A": "脊柱结核常累及相邻两个椎体并破坏其间的椎间盘，伴范围较大的椎旁冷脓肿，脓肿壁可钙化并沿腰大肌流注", "B": "化脓性脊柱炎早期即出现椎间盘破坏、椎间隙狭窄与终板侵蚀，椎间盘T2WI信号增高，病程进展快", "C": "脊柱转移瘤通常椎间盘不受累、椎间隙保持正常，常侵犯椎弓根", "D": "脊柱结核可出现跳跃性病灶及后凸畸形", "E": "三者均以椎间盘早期破坏为共同特点，故椎间盘受累与否无鉴别价值"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-053", "kp": "脊柱感染与转移瘤鉴别", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：结核杆菌经椎体终板下动脉播散，破坏相邻椎体并侵及椎间盘，形成范围广泛的椎旁寒性脓肿，钙化与流注是其相对特征性表现。B正确：化脓菌产生蛋白溶解酶，对椎间盘破坏早而迅速，椎间隙狭窄、终板模糊，椎间盘T2WI呈高信号并强化，全身症状重。C正确：椎间盘无血供且乏营养，血行转移瘤一般不跨越椎间盘，椎间隙保持是转移瘤区别于感染的核心征象；转移常累及椎体后部与椎弓根。D正确：结核可经椎旁韧带下蔓延形成跳跃病灶，椎体塌陷后形成角状后凸。【为什么错】E错误：椎间盘是否受累恰恰是感染性病变与肿瘤性病变最重要的鉴别点，绝非无价值。", "tr": "记忆主线：“感染坏椎间盘，肿瘤留椎间盘；结核脓肿大而钙化、化脓进展快而椎间盘信号高。”技术上应加扫脂肪抑制T2WI与增强以显示椎旁脓肿范围及硬膜外受累。", "bk": "正高", "ref": {"篇": "骨与骨关节", "章": "脊柱感染性病变", "节": "化脓性脊柱炎", "页": 288}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0154", "t": "共用题干题", "s": "结合上述情景，股骨头缺血性坏死在MRI上具有较高特异性的“双线征”是指", "o": {"A": "T2WI上坏死区边缘外侧的低信号带（硬化骨）与其内侧的高信号带（肉芽修复组织）并行出现", "B": "T1WI上出现两条平行的高信号带", "C": "股骨颈内出现两条骨折线", "D": "关节腔内出现双层积液信号", "E": "增强扫描出现两层环形强化的滑膜"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-054", "kp": "股骨头缺血坏死双线征", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：坏死骨与活骨交界处形成反应界面，外侧为硬化骨与纤维组织（T2WI低信号），内侧为富血供的肉芽修复带（T2WI高信号），二者平行排列即双线征。相应地T1WI上表现为蜿蜒迂曲的低信号带（新月形或地图样），MRI可在X线与CT尚正常时即检出病变，是最敏感的方法。【为什么错】B错误：T1WI上表现为单一的蜿蜒低信号带，而非两条高信号带。C错误：双线征与骨折线无关。D错误：关节积液为均一液体信号，无分层双线结构。E错误：滑膜双层强化非本病特征。", "tr": "ARCO分期要点：0期影像学阴性；Ⅰ期仅MRI阳性、X线正常；Ⅱ期X线可见硬化囊变但股骨头无塌陷；Ⅲ期出现新月征即软骨下骨折与塌陷；Ⅳ期继发骨关节炎、关节间隙狭窄。“有无塌陷”是Ⅱ、Ⅲ期分界，直接决定保髋还是置换。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07154", "gs": ""}, {"id": "ZG-U07-0155", "t": "多选题", "s": "关于膝关节半月板与交叉韧带损伤的MRI表现，描述正确的是", "o": {"A": "半月板内异常高信号达到关节面（Ⅲ级信号）方可诊断为撕裂，Ⅰ、Ⅱ级为黏液样变性", "B": "半月板桶柄状撕裂时，移位的半月板碎片位于后交叉韧带下方，矢状面上形成“双后交叉韧带征”", "C": "外侧半月板“领结征”消失（连续矢状层面上体部领结样结构少于两层）提示半月板移位或撕裂", "D": "前交叉韧带撕裂的间接征象包括股骨外侧髁与胫骨后外侧的对吻性骨挫伤、胫骨前移", "E": "半月板与交叉韧带评价应首选T1WI，因其信噪比最高、对撕裂最敏感"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-055", "kp": "半月板与交叉韧带损伤MRI", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】A正确：半月板信号分级中Ⅰ级为点状、Ⅱ级为线状但均未达关节面，属退变；只有异常信号延伸至上或下关节面（Ⅲ级）才诊断撕裂。B正确：桶柄状撕裂的内侧碎片向髁间窝移位，位于后交叉韧带下方，形成“双后交叉韧带征”。C正确：正常半月板体部在矢状面上连续两层以上呈领结样，层数减少提示组织缺失或移位。D正确：前交叉韧带断裂时胫骨相对前移，股骨外侧髁与胫骨后外侧撞击形成对吻性骨挫伤，是重要的间接征象。【为什么错】E错误：应首选质子密度加权或脂肪抑制质子密度/T2加权序列——半月板与韧带本身为低信号，撕裂处的液体或黏液变性在这些序列上呈高信号，对比最佳；T1WI虽信噪比高但液体与纤维组织对比差，敏感性低。", "tr": "B项的高频陷阱是把“双后交叉韧带征”误记为“双前交叉韧带征”，移位碎片位于后交叉韧带下方。另注意“魔角效应”：当结构与主磁场成约55°时短TE序列可出现假高信号，需用长TE序列复核。", "bk": "正高", "ref": null, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-0156", "t": "单选题", "s": "下列骨膜反应类型中，最不提示病变具有侵袭性的是", "o": {"A": "Codman三角", "B": "日光放射状骨针", "C": "葱皮样多层骨膜反应", "D": "骨膜反应中断、残缺不全", "E": "连续、致密、厚而光滑的实性骨膜反应"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-056", "kp": "骨膜反应类型与侵袭性判断", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】E正确：连续、致密、厚而光滑的实性骨膜反应说明骨膜有充足时间形成成熟新生骨，提示病变进展缓慢，多见于良性病变、慢性骨髓炎、骨样骨瘤、应力性骨折等。【为什么错】A错误：Codman三角为肿瘤突破骨皮质将骨膜掀起，骨膜新生骨仅在边缘残留呈三角形，提示生长迅速。B错误：日光放射状骨针为肿瘤沿垂直于骨皮质的血管走行成骨，是骨肉瘤等高侵袭性病变的表现。C错误：葱皮样多层骨膜反应反映肿瘤间歇性快速生长，常见于尤文肉瘤，亦可见于骨肉瘤与急性骨髓炎。D错误：骨膜反应中断残缺说明新生骨形成速度赶不上病变破坏速度，属侵袭性表现。", "tr": "务必记住：骨膜反应类型反映的是“病变生长速度”而非“良恶性本身”。Codman三角与葱皮样反应同样可见于急性骨髓炎，不能单凭骨膜反应形态确诊肿瘤，需结合骨破坏区移行带、软组织肿块与临床。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0157", "t": "单选题", "s": "评价骨破坏区的良恶性倾向时，提示病变侵袭性强的征象是", "o": {"A": "破坏区移行带宽、边界模糊，呈虫蚀状或渗透状破坏", "B": "破坏区呈地图状，边缘有硬化边", "C": "破坏区边界清楚锐利，移行带窄", "D": "病灶周围骨皮质膨胀变薄但连续完整", "E": "病灶内可见成熟骨性间隔"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-MSK-057", "kp": "骨破坏移行带与侵袭性", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】A正确：移行带指病变与正常骨之间的过渡区。移行带宽、边界模糊说明病变生长速度快于宿主骨的修复反应，虫蚀状与渗透状破坏是高侵袭性的典型形态，常见于恶性骨肿瘤、转移瘤、骨髓瘤及急性骨髓炎。【为什么错】B错误：地图状破坏伴硬化边说明宿主骨有足够时间形成反应性硬化，提示生长缓慢。C错误：边界清楚、移行带窄提示良性或低度侵袭性。D错误：骨皮质膨胀变薄但连续完整是良性膨胀性病变（如骨囊肿、骨巨细胞瘤）的表现。E错误：成熟骨性间隔提示病变慢性、良性。", "tr": "移行带宽窄比病灶大小更能反映侵袭性。需注意：骨巨细胞瘤虽常边界较清、皮质膨胀，但属交界性肿瘤，可复发甚至转移；影像的“侵袭性”评价与病理良恶性并不完全等同。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-0158", "t": "共用题干题", "s": "结合上述情景，主动脉夹层的Stanford分型中，A型的定义是", "o": {"A": "无论内膜破口位于何处，只要夹层累及升主动脉", "B": "内膜破口必须位于升主动脉且不累及主动脉弓", "C": "夹层仅累及降主动脉", "D": "夹层累及腹主动脉及其分支", "E": "夹层仅累及主动脉弓三分支"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-058", "kp": "主动脉夹层分型", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】A正确：Stanford分型着眼于“升主动脉是否受累”这一决定治疗方式的关键：凡累及升主动脉者为A型，需紧急外科手术；未累及升主动脉者为B型，多采用药物治疗或腔内修复。【为什么错】B错误：Stanford分型不要求破口位于升主动脉，也不排除累及主动脉弓，此描述混入了破口位置限定。C错误：仅累及降主动脉为Stanford B型。D错误：累及腹主动脉可见于DeBakey Ⅲb型，不等同于Stanford A型。E错误：分型依据是升主动脉是否受累，而非弓部分支。", "tr": "两套分型须分清：DeBakey按“起源＋累及范围”分Ⅰ型（起自升主动脉并累及降主动脉及以远）、Ⅱ型（局限于升主动脉）、Ⅲ型（起自左锁骨下动脉远端，Ⅲa限于胸降主动脉、Ⅲb延及腹主动脉）；Stanford只看升主动脉是否受累。DeBakey Ⅰ、Ⅱ型相当于Stanford A型。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07133", "gs": ""}, {"id": "ZG-U07-0159", "t": "共用题干题", "s": "结合上述情景，在主动脉夹层CTA上，支持某一腔为“假腔”的征象是", "o": {"A": "腔内可见“蜘蛛网征”，即残存的内膜条索呈细线状横跨腔内", "B": "腔的横断面呈锐角楔形延伸即“鸟嘴征”", "C": "该腔横截面积较大并环绕、压迫另一腔", "D": "增强后强化时间延迟、强化程度较淡，且更易形成附壁血栓", "E": "内膜钙化紧贴该腔外缘并随内膜片内移，是该腔为假腔的可靠依据"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-059", "kp": "主动脉夹层真假腔鉴别", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】A正确：蜘蛛网征为撕裂不全的内膜残余条索残留于假腔内，是假腔的特异征象。B正确：鸟嘴征为假腔沿夹层扩展方向形成的楔形锐角，是识别假腔的经典标志。C正确：假腔内压力高、扩展迅速，通常面积大于真腔并压迫、包绕真腔使其呈新月形或受压变形。D正确：假腔血流缓慢、入口有限，故强化延迟且较淡，血栓形成常见。【为什么错】E错误：该项描述的是真腔特征而非假腔——内膜钙化本属主动脉内膜，夹层后随内膜片内移，故钙化位于真腔外缘、与真腔相贴，是判断真腔的重要依据，题干要求选支持“假腔”的征象，故E不符合。", "tr": "真腔的另一识别要点是“与未受累的近远端主动脉腔延续”，在多平面重建上追踪最可靠。技术上必须包含平扫，否则壁内血肿（新月形高密度）和钙化内移会被增强血液掩盖而漏诊。", "bk": "正高", "ref": null, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ07134", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-0160", "t": "共用题干题", "s": "结合上述情景，患者男性，55岁，高血压病史10年、服药不规律，2小时前静息状态下突发胸背部撕裂样剧痛并向腰部放射，急诊测双上肢血压不对称，右上肢190/110mmHg，胸片示上纵隔增宽。临床高度怀疑急性主动脉综合征，需明确有无夹层、内膜破口位置、累及范围及内脏动脉受累情况，为外科或腔内治疗提供依据，遂申请主动脉CTA。设备为双源CT，患者心率85次/分且节律不齐，疼痛致配合欠佳，血肌酐正常、无碘对比剂过敏史。作为技师，下列扫描技术方案最恰当的是", "o": {"A": "先行胸腹主动脉平扫，再行心电门控增强扫描，范围自胸廓入口至股动脉分叉，经右上肢静脉注射对比剂并采用团注跟踪触发", "B": "省略平扫直接行增强扫描，以缩短检查时间并降低辐射剂量", "C": "扫描范围仅覆盖胸主动脉，因夹层不会累及腹主动脉", "D": "经左上肢静脉注射对比剂，以避开右心系统", "E": "不使用心电门控，因门控会延长扫描时间且对主动脉成像无意义"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-060", "kp": "主动脉CTA扫描技术", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】A正确：平扫是识别壁内血肿（主动脉壁新月形高密度）与内膜钙化内移的唯一手段，不可省略；心电门控可消除升主动脉随心脏搏动产生的运动伪影，避免形成酷似内膜片的伪影而误诊；扫描范围须自胸廓入口至股动脉分叉，以完整评估夹层累及范围、破口位置及分支受累，为手术或腔内修复提供依据；经右上肢注射可避免左头臂静脉内高浓度对比剂横跨主动脉弓上方产生条状硬化伪影。【为什么错】B错误：省略平扫会漏诊壁内血肿这一急性主动脉综合征的重要类型。C错误：夹层常向下延伸累及腹主动脉及内脏动脉，范围不足将遗漏关键信息。D错误：左侧注射时左头臂静脉恰位于主动脉弓分支上方，高浓度对比剂产生的线束硬化伪影会干扰弓部及其分支判读。E错误：升主动脉搏动伪影是最常见的假阳性来源，心电门控恰恰是主动脉根部与升主动脉成像的关键。", "tr": "三个高频技术陷阱：省略平扫、范围不足、未用门控。此外注意本例心率快且不规则，应优先选择大螺距或宽体探测器的快速采集模式，不宜使用需要多心动周期拼接的采集方式。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07132", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-0161", "t": "共用题干题", "s": "结合上述情景，下肢深静脉血栓在间接法CT静脉成像（CTV）上的典型直接征象是", "o": {"A": "静脉腔内低密度充盈缺损，管腔扩张，周围可见环形强化的静脉壁", "B": "静脉管腔明显变细、管壁增厚且无充盈缺损", "C": "动脉腔内偏心性钙化斑块", "D": "皮下脂肪层内条索状高密度影", "E": "股动脉管腔内低密度充盈缺损"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-061", "kp": "下肢深静脉血栓CTV征象", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】A正确：急性期血栓在强化的静脉腔内呈低密度充盈缺损，受累静脉因血栓充填而管径增粗，静脉壁滋养血管扩张与炎症反应形成环形强化（“轨道征”），周围脂肪间隙可见水肿模糊，是急性DVT的典型表现。间接法CTV通常在肺动脉CTA后延迟约3分钟扫描下肢，可实现肺栓塞与DVT的一站式评估。【为什么错】B错误：管腔变细、管壁增厚而无充盈缺损为慢性血栓后改变，常伴侧支形成。C错误：偏心钙化斑块位于动脉，属动脉粥样硬化表现。D错误：皮下条索影为软组织水肿或淋巴回流障碍的非特异表现。E错误：题目所问为深静脉血栓，动脉内充盈缺损为动脉栓塞。", "tr": "间接CTV的时相把握是关键：过早扫描静脉尚未充分强化会出现“假性充盈缺损”，过晚则对比度下降。判读时还要注意层流造成的混合伪影，常见于髂静脉与股静脉交汇处，需结合多平面重建确认。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07129", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-0162", "t": "共用题干题", "s": "结合上述情景，关于外周神经MR成像（MRN）与周围神经卡压的影像评估，描述正确的是", "o": {"A": "三维短反转时间反转恢复序列（3D-STIR-SPACE/VISTA/CUBE）可在抑制脂肪与血管信号的同时突出神经，适用于臂丛神经成像", "B": "背景抑制弥散加权成像（DWIBS）可通过抑制背景信号突出显示神经干走行，有助于整体观察", "C": "神经卡压时受压部位近端神经增粗、T2/STIR信号增高，受压处可变扁", "D": "腕管综合征时正中神经在豌豆骨水平增粗、信号增高，屈肌支持带可向掌侧膨隆", "E": "臂丛神经MRN应首选横断面薄层T1WI单一序列，无需斜冠状面与脂肪抑制序列"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VAS-062", "kp": "外周神经MRN成像技术与征象", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (3)MR诊断要点", "ex": "【为什么对】A正确：3D-STIR类序列脂肪抑制均匀、对磁场不均匀不敏感，并可抑制流动血液信号，使神经在低信号背景中突出，配合最大密度投影可显示臂丛全程。B正确：DWIBS通过高b值与短反转时间抑制背景组织，使神经呈高信号，形成类似神经造影的整体显示效果。C正确：卡压近端神经因轴浆运输受阻而水肿增粗、T2/STIR信号增高，卡压处受机械压迫而变扁，形成“束腰”样改变。D正确：腕管综合征的典型影像三联为正中神经在豌豆骨或钩骨钩水平增粗且信号增高、屈肌支持带掌侧膨隆、神经远端变扁。【为什么错】E错误：臂丛神经走行倾斜且跨越多个层面，必须采用斜冠状面（沿神经根与干走行）结合脂肪抑制序列；单一横断面T1WI虽显示解剖关系好，但无法评估神经信号异常，也不能显示神经全程。", "tr": "神经成像的关键是“抑脂＋抑血流＋沿神经走行方位采集”。此外注意魔角效应：神经与主磁场成约55°时短TE序列可产生假性高信号，应使用长TE或STIR类序列复核，避免误诊为神经损伤。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07137", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1001", "t": "共用题干题", "s": "结合上述情景，超急性期脑出血（发病后数小时内）CT平扫时，血肿的典型密度表现是", "o": {"A": "低密度影", "B": "等密度影", "C": "高密度影", "D": "混杂密度影", "E": "环形强化影"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-001", "kp": "脑出血CT密度演变", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】超急性期血肿内红细胞完整、血红蛋白浓缩，X线吸收系数高，CT平扫即呈高密度（CT值约50～80 HU），随时间延长血肿逐步演变为等、低密度。【为什么错】A：低密度为血肿吸收后期或液化坏死期的表现。B：等密度见于亚急性期后期至慢性期部分时段。D：混杂密度见于血肿内新鲜出血与液化并存或出血伴占位内坏死。E：环形强化是增强扫描后的表现，平扫不出现强化。", "tr": "脑出血密度按“高→等→低”演变；超急性期即高密度，勿与超急性期脑梗死（CT常阴性）混淆。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07156", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1002", "t": "共用题干题", "s": "结合上述情景，临床疑急性蛛网膜下腔出血时，首选的影像学检查方法是", "o": {"A": "颅骨X线平片", "B": "CT平扫", "C": "MRI平扫", "D": "PET-CT", "E": "经颅超声"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-002", "kp": "蛛网膜下腔出血检查方法", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】CT平扫对急性期蛛网膜下腔出血敏感，脑沟、脑池及蛛网膜下腔内的新鲜血液呈高密度，检查快速便捷，是急诊首选检查。【为什么错】A：X线平片无法显示颅内软组织出血。C：MRI对超急性期出血显示不佳、检查时间长，不作为首选。D：PET-CT用于功能代谢显像，不用于出血诊断。E：超声无法穿透颅骨显示颅内出血。", "tr": "蛛网膜下腔出血CT敏感性随发病时间下降，发病24小时后可结合MRI（FLAIR、SWI）补充检查。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "颅内囊性病变", "节": "蛛网膜囊肿", "页": 80}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07159", "gs": ""}, {"id": "ZG-U07-1003", "t": "共用题干题", "s": "结合上述情景，脑出血进入亚急性期后期（约出血后1～2周）时，血肿在MRI T1WI与T2WI上的信号特点是", "o": {"A": "T1WI低信号、T2WI高信号", "B": "T1WI高信号、T2WI低信号", "C": "T1WI低信号、T2WI低信号", "D": "T1WI高信号、T2WI高信号", "E": "T1WI等信号、T2WI等信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-003", "kp": "脑出血MRI信号分期", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】亚急性期后期红细胞溶解，游离的正铁血红蛋白处于细胞外并被稀释，缩短T1的同时延长T2，故T1WI、T2WI均为高信号。【为什么错】A：T1低、T2高为慢性期液化囊变或脑脊液样信号。B：T1高、T2低为亚急性期早期（细胞内正铁血红蛋白）的表现。C：双低信号见于钙化或含铁血黄素沉积。E：等信号见于急性期部分阶段。", "tr": "记忆口诀“亚早内正铁（T1高T2低）、亚晚外正铁（双高）”；正铁血红蛋白在红细胞内、外是信号分期的关键。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07156", "gs": ""}, {"id": "ZG-U07-1004", "t": "单选题", "s": "硬膜外血肿CT平扫的典型形态是", "o": {"A": "新月形", "B": "梭形（双凸形）", "C": "脑内类圆形", "D": "环状", "E": "不规则条片状"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-004", "kp": "硬膜外与硬膜下血肿鉴别", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】硬膜外血肿位于硬脑膜与颅骨之间，因硬脑膜在颅缝处与骨缝紧密粘连，血肿被骨缝限制而呈梭形（双凸形），一般不跨越颅缝。【为什么错】A：新月形是硬膜下血肿的典型形态，出血位于硬膜下腔，可跨越颅缝。C：脑内类圆形为脑实质内血肿。D：环状为脓肿、转移瘤等增强后的表现。E：不规则条片状无定位特异性。", "tr": "核心鉴别：“梭形不跨颅缝（硬膜外）vs 新月形跨颅缝（硬膜下）”。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1005", "t": "共用题干题", "s": "结合上述情景，高血压性脑出血最常见的出血部位是", "o": {"A": "丘脑", "B": "壳核", "C": "尾状核头", "D": "苍白球", "E": "内囊膝部"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-005", "kp": "基底节区脑出血部位", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】壳核位于外囊内侧、内囊外侧，是豆纹动脉（出血动脉）供血区，为高血压性脑出血最常见的部位，约占60%，出血常压迫内囊引起对侧偏瘫。【为什么错】A：丘脑出血约占10%～20%，居第二位。C：尾状核头出血少见。D：苍白球出血少见。E：内囊为白质传导束结构，不是出血的起始部位。", "tr": "壳核出血偏外、丘脑出血居内，两者紧邻内囊；答题先看部位再推临床表现。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07136", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1006", "t": "共用题干题", "s": "结合上述情景，对超急性期（发病2小时内）脑梗死最敏感的MRI检查序列是", "o": {"A": "T1WI", "B": "T2WI", "C": "弥散加权成像（DWI）", "D": "T2-FLAIR", "E": "磁敏感加权成像（SWI）"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-006", "kp": "超急性期脑梗死序列选择", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】超急性期脑梗死发生细胞毒性水肿，水分子弥散受限，DWI呈高信号、ADC值下降，发病数分钟内即可检出，是目前超急性期脑梗死最敏感的序列。【为什么错】A：T1WI对早期梗死不敏感。B：T2WI在发病12小时内常为阴性。D：FLAIR出现明确异常需数小时以上。E：SWI主要用于显示出血、钙化及静脉，不用于梗死早期检出。", "tr": "“DWI高信号＋ADC低信号”为急性梗死确诊依据；ADC高信号的DWI高信号为T2透射效应（陈旧灶）。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07160", "gs": ""}, {"id": "ZG-U07-1007", "t": "共用题干题", "s": "结合上述情景，脑膜瘤CT增强扫描的典型强化特点是", "o": {"A": "病灶不强化", "B": "轻度不均匀强化", "C": "明显均匀强化，宽基底贴附硬脑膜", "D": "环形强化", "E": "周边结节样向心性强化"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-007", "kp": "脑膜瘤CT表现", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】脑膜瘤为富血供、富含血管的良性肿瘤，增强后呈明显均匀强化，多以宽基底贴附硬脑膜并可见脑膜尾征，CT平扫多呈等或稍高密度，可伴钙化。【为什么错】A：脑膜瘤血供丰富，明显强化而非不强化。B：轻度不均匀强化不符其富血供特征。D：环形强化多见于脑脓肿、胶质瘤、转移瘤。E：周边结节状向心性强化是肝血管瘤的增强特点，不适用于脑膜瘤。", "tr": "“脑膜尾征＋明显均匀强化”提示脑膜瘤，但脑膜尾征非其特有，需结合部位与强化方式综合判断。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "脑膜炎", "页": 40}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07158", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1008", "t": "单选题", "s": "桥小脑角区最常见的肿瘤是", "o": {"A": "脑膜瘤", "B": "表皮样囊肿（胆脂瘤）", "C": "听神经瘤（前庭神经鞘瘤）", "D": "三叉神经瘤", "E": "脑转移瘤"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-008", "kp": "桥小脑角区肿瘤", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】听神经瘤起源于前庭神经鞘膜，约占桥小脑角区肿瘤的70%～80%，为桥小脑角区最常见肿瘤，常伴患侧内听道扩大，增强后明显强化。【为什么错】A：脑膜瘤在桥小脑角区发生率低于听神经瘤。B：表皮样囊肿呈脑脊液样信号、无强化。D：三叉神经瘤少见。E：转移瘤可累及桥小脑角，但发生率远低于听神经瘤。", "tr": "“桥小脑角肿瘤＋内听道扩大”高度提示听神经瘤；内听道是鉴别要点。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "肿瘤和肿瘤样病变", "节": "鞍区肿瘤", "页": 77}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1009", "t": "共用题干题", "s": "结合上述情景，多发性硬化（MS）累及脑白质的典型MRI表现是", "o": {"A": "基底节区对称性钙化", "B": "侧脑室周围多发斑片状长T1长T2信号，病灶垂直于侧脑室壁", "C": "脑干孤立性占位", "D": "皮层弥漫性强化", "E": "小脑半球大囊小结节"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-009", "kp": "多发性硬化MRI表现", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】MS好发于侧脑室周围、半卵圆中心等脑白质，T2WI、FLAIR呈多发斑片状高信号，病灶沿深静脉周围分布、与侧脑室壁垂直，即“直角脱髓鞘征（Dawson手指征）”，为本病特征。【为什么错】A：基底节对称性钙化见于Fahr病等。C：MS为多发脱髓鞘病灶而非单发占位。D：MS急性病灶可强化但非弥漫皮层强化。E：大囊小结节为血管母细胞瘤表现。", "tr": "“直角脱髓鞘征”是MS特征；与缺血性白质病变相比，MS病灶多发、非皮质下弓状纤维区分布。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "多发性硬化", "页": 45}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07138", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1010", "t": "单选题", "s": "颅内最常见的良性肿瘤是", "o": {"A": "听神经瘤", "B": "垂体腺瘤", "C": "脑膜瘤", "D": "血管母细胞瘤", "E": "颅咽管瘤"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-010", "kp": "颅内肿瘤构成", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】脑膜瘤约占颅内原发肿瘤的15%～20%，是颅内最常见的良性肿瘤，多见于中年女性，好发于矢状窦旁、大脑凸面等部位。【为什么错】A：听神经瘤为良性但发生率低于脑膜瘤。B：垂体腺瘤发病率低于脑膜瘤。D：血管母细胞瘤少见，多见于小脑。E：颅咽管瘤多见于儿童。", "tr": "“最常见良性肿瘤＝脑膜瘤”“桥小脑角最常见＝听神经瘤”是两个易混的高频结论。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "颅脑外伤", "节": "外伤性原发性颅内损伤", "页": 24}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1011", "t": "单选题", "s": "患者男，35岁，头痛、共济失调1个月。MRI示右侧小脑半球大囊性病灶，囊壁内见小强化结节，病灶周围可见流空信号血管影。最可能的诊断是", "o": {"A": "小脑脑膜瘤", "B": "血管母细胞瘤", "C": "胶质母细胞瘤", "D": "脑转移瘤", "E": "蛛网膜囊肿"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-011", "kp": "血管母细胞瘤MRI诊断", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】血管母细胞瘤好发于小脑半球，典型表现为“大囊小结节”，囊壁强化结节即富血供肿瘤实质，瘤周可见流空信号的供血动脉及引流静脉，为最常见的小脑原发性肿瘤之一。【为什么错】A：脑膜瘤以宽基底贴脑膜、均匀强化为特征，不呈大囊小结节。C：胶质母细胞瘤好发于中老年幕上白质，呈环形强化伴坏死。D：转移瘤多为多发、小病灶大水肿。E：蛛网膜囊肿为水样信号、无强化结节。", "tr": "“大囊小结节＋囊壁强化结节＋流空血管”是血管母细胞瘤的经典组合，漏看强化小结节易误诊。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "血管畸形", "页": 29}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1012", "t": "单选题", "s": "脑内单发环形强化病灶，壁厚薄不均伴壁结节，瘤周白质明显指状水肿，首先考虑的诊断为", "o": {"A": "脑脓肿", "B": "胶质母细胞瘤", "C": "脑膜瘤", "D": "蛛网膜囊肿", "E": "海绵状血管瘤"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-012", "kp": "胶质母细胞瘤增强特征", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】胶质母细胞瘤血脑屏障破坏明显，增强呈花环样、厚薄不均的环形强化伴壁结节，瘤周水肿沿白质指状蔓延，为成人最常见的原发性恶性脑肿瘤。【为什么错】A：脑脓肿壁光滑均匀，DWI囊腔弥散受限。C：脑膜瘤贴脑膜、均匀明显强化。D：蛛网膜囊肿呈水样密度、无强化。E：海绵状血管瘤多伴含铁血黄素环、呈桑葚样信号，强化程度不一。", "tr": "环形强化鉴别：脓肿“壁光滑＋弥散受限”、胶质瘤“壁厚薄不均＋壁结节”、转移瘤“多发小环”。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "肿瘤和肿瘤样病变", "节": "神经元和混合性神经元-神经胶质肿瘤", "页": 70}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1013", "t": "单选题", "s": "垂体大腺瘤向上生长时最先受压的结构是", "o": {"A": "视交叉", "B": "垂体柄", "C": "海绵窦", "D": "下丘脑", "E": "蝶窦"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-013", "kp": "垂体腺瘤生长方向与毗邻", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】垂体大腺瘤向上突破鞍膈时首先压迫上方的视交叉，临床表现为双颞侧偏盲，是垂体大腺瘤最常见的神经系统表现。【为什么错】B：垂体柄受压可致内分泌紊乱，但位于鞍内、非最先受压。C：海绵窦受压见于肿瘤向侧方生长。D：下丘脑受压少见且较晚。E：蝶窦位于鞍下方，向下方生长才累及。", "tr": "“双颞侧偏盲＝视交叉受压”是垂体大腺瘤的定位体征，也是高频考点。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1014", "t": "共用题干题", "s": "结合上述情景，中耳胆脂瘤CT检查中最具诊断价值的征象是", "o": {"A": "鼓室内单纯软组织密度影", "B": "乳突气房密度增高", "C": "上鼓室盾板破坏伴软组织团块影", "D": "中耳腔积液", "E": "听小骨形态完全正常"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-001", "kp": "中耳胆脂瘤CT表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】胆脂瘤为角化鳞状上皮的异常积聚，CT表现为上鼓室、乳突窦内软组织团块伴骨质破坏（盾板侵蚀、听小骨吸收），骨质破坏是诊断与评估并发症的关键。【为什么错】A：单纯软组织影无特异性。B：气房密度增高见于炎症、积液。D：中耳腔积液为炎性改变。E：胆脂瘤常伴听小骨破坏，不会形态正常。", "tr": "“软组织团块＋骨质破坏”是胆脂瘤核心征象，注意与单纯慢性中耳炎（无骨破坏）鉴别。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07131", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1015", "t": "单选题", "s": "喉部最常见的恶性肿瘤及好发部位是", "o": {"A": "腺癌、声门下型", "B": "鳞状细胞癌、声门型", "C": "淋巴瘤、声门上型", "D": "肉瘤、会厌型", "E": "恶性黑色素瘤、喉室型"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-002", "kp": "喉癌病理类型与部位", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】喉癌绝大多数为鳞状细胞癌（约90%以上），以声门型最常见，早期即出现声音嘶哑，CT/MRI显示声带增厚、喉室变形及颈部淋巴结转移。【为什么错】A：喉部腺癌少见。C：淋巴瘤可累及喉但发生率低。D：喉肉瘤罕见。E：恶性黑色素瘤极少原发于喉。", "tr": "“声门型最常见（早嘶哑）”与“声门上型恶性度高、易淋巴结转移”需分别记忆。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1016", "t": "共用题干题", "s": "结合上述情景，甲状腺结节内出现细颗粒状微小钙化，最有助于提示的病理类型是", "o": {"A": "结节性甲状腺肿", "B": "滤泡性腺瘤", "C": "甲状腺乳头状癌", "D": "亚急性甲状腺炎", "E": "单纯性囊肿"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-003", "kp": "甲状腺结节钙化与恶性", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】甲状腺乳头状癌的特征性钙化为沙砾样（砂粒体）微小钙化，超声及CT上结节内细小钙化是提示恶性的最重要征象之一。【为什么错】A：结节性甲状腺肿以粗大钙化、弧形钙化为主。B：腺瘤钙化少见且多粗大。D：亚急性甲状腺炎以甲状腺弥漫性改变为主。E：囊肿无钙化或仅囊壁弧线状钙化。", "tr": "“微小钙化倾向恶性、粗大弧形钙化多为良性”是甲状腺结节钙化判读要点。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07148", "gs": ""}, {"id": "ZG-U07-1017", "t": "单选题", "s": "鼻窦最常见的恶性肿瘤是", "o": {"A": "淋巴瘤", "B": "嗅神经母细胞瘤", "C": "鳞状细胞癌", "D": "腺样囊性癌", "E": "横纹肌肉瘤"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-004", "kp": "鼻窦恶性肿瘤", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】上颌窦是鼻窦癌最好发部位，鳞状细胞癌占鼻窦恶性肿瘤的绝大多数，CT表现为窦腔软组织肿块伴窦壁溶骨性破坏、可向邻近结构侵犯。【为什么错】A：鼻窦淋巴瘤可发生但少见。B：嗅神经母细胞瘤罕见，多见于嗅区。D：腺样囊性癌多源于涎腺。E：横纹肌肉瘤多见于儿童。", "tr": "“上颌窦＋鳞癌”是鼻窦恶性肿瘤经典组合；儿童鼻窦恶性肿块多考虑横纹肌肉瘤。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1018", "t": "单选题", "s": "眼眶爆裂性骨折最常累及的部位是", "o": {"A": "眶上壁", "B": "眶底（下壁）及眶内侧壁", "C": "眶外侧壁", "D": "眶尖", "E": "泪骨"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-005", "kp": "眼眶爆裂性骨折", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】爆裂性骨折为钝性外力经眼球传导致眶内压骤增，使最薄弱的眶底和眶内侧壁（纸样板）骨折，可伴眶内容疝出、眶内气肿及下直肌嵌顿。【为什么错】A：眶上壁较厚，少见爆裂骨折。C：外侧壁较坚固。D：眶尖骨折少见。E：泪骨极少单独骨折。", "tr": "纸样板极薄易漏诊，CT需适当调整窗宽窗位并结合冠状位重组观察。", "bk": "正高", "ref": {"篇": "头颈部", "章": "眼眶病变", "节": "先天异常", "页": 91}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1019", "t": "单选题", "s": "急性鼻窦炎CT检查中最常见且具诊断意义的征象是", "o": {"A": "窦壁骨质增生硬化", "B": "窦腔内气液平面", "C": "窦腔骨质膨胀扩大", "D": "窦腔内钙化灶", "E": "鼻中隔偏曲"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-006", "kp": "急性鼻窦炎影像表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】急性鼻窦炎时窦黏膜增厚、分泌物潴留，窦腔内出现气液平面是急性炎症的典型表现，配合黏膜增厚即可诊断。【为什么错】A：骨质增生硬化见于慢性鼻窦炎。C：窦腔膨胀扩大多见于黏液囊肿。D：窦内钙化多提示真菌性鼻窦炎。E：鼻中隔偏曲为解剖变异，与炎症无关。", "tr": "“急性看气液平、慢性看骨硬化、真菌看钙化”是鼻窦炎三型鉴别口诀。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1020", "t": "共用题干题", "s": "结合上述情景，自发性气胸X线胸片上最可靠的诊断依据是", "o": {"A": "患侧肺野透亮度增高", "B": "纵隔向健侧移位", "C": "脏层胸膜线（肺压缩边缘线）外侧无肺纹理的透亮区", "D": "膈肌低平", "E": "肋膈角变钝"}, "d": "易", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-001", "kp": "气胸X线征象", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】气胸时胸膜腔内气体把肺向肺门方向压缩，清晰显示脏层胸膜线即肺压缩边缘，其外侧胸腔区透亮且无肺纹理，是气胸最可靠的X线征象。【为什么错】A：透亮度增高也见于肺气肿。B：仅大量气胸才致纵隔移位。D：膈肌低平见于肺气肿。E：肋膈角变钝提示胸腔积液。", "tr": "“脏层胸膜线＋外侧无肺纹理”是气胸金标准；少量气胸在呼气相更易显示。", "bk": "正高", "ref": {"篇": "胸部", "章": "胸膜疾病", "节": "气胸与液气胸", "页": 142}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07146", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1021", "t": "单选题", "s": "立位后前位胸片出现肋膈角变钝，提示游离性胸腔积液量至少约为", "o": {"A": "50 ml", "B": "200 ml", "C": "500 ml", "D": "1000 ml", "E": "2000 ml"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-002", "kp": "胸腔积液的X线定量", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】常规立位后前位胸片上，肋膈角变钝约需胸腔积液量200～300 ml，B项最接近，是少量游离性积液的早期征象。【为什么错】A：50 ml积液在常规立位片上常难以显示。C：500 ml时除肋膈角变钝外已可见外高内低弧形液影，超出“仅肋膈角变钝”的早期范围。D：1000 ml积液已形成大面积致密影。E：2000 ml为大量积液，患侧呈大片致密影并致纵隔移位。", "tr": "“肋膈角变钝≈200 ml以上”，更少量积液可行患侧卧位水平投照或超声检出。", "bk": "正高", "ref": {"篇": "胸部", "章": "胸膜疾病", "节": "胸腔积液", "页": 140}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1022", "t": "共用题干题", "s": "结合上述情景，中央型肺癌致右上叶肺不张时，X线及CT上典型的征象是", "o": {"A": "反S征（横S征）", "B": "空气支气管征", "C": "肺门蝶翼影", "D": "胸膜凹陷征", "E": "空泡征"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-003", "kp": "中央型肺癌阻塞性肺不张", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】右上叶中央型肺癌引起阻塞性肺不张时，肺门上移并呈弧形外凸，与上移的水平裂下缘共同构成“反S”形轮廓，即反S征（Golden S征），是中央型肺癌的经典征象。【为什么错】B：空气支气管征见于肺炎、肺水肿等实变。C：蝶翼影见于肺水肿。D：胸膜凹陷征多见于周围型肺癌。E：空泡征见于肺泡癌等。", "tr": "“反S征＝右上叶中央型肺癌阻塞性不张”；“胸膜凹陷征＝周围型肺癌”两个征象对应关系勿混。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07130", "gs": ""}, {"id": "ZG-U07-1023", "t": "单选题", "s": "继发性肺结核X线胸片最常见的病灶好发部位是", "o": {"A": "右肺中叶", "B": "双肺上叶尖后段及下叶背段", "C": "双肺基底段", "D": "舌叶外侧段", "E": "肺前段"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-004", "kp": "继发性肺结核好发部位", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】继发性肺结核好发于双肺上叶尖后段及下叶背段，该区域通气较好、血流相对少且淋巴引流不畅，利于结核菌沉积，病灶多呈多形态并存（渗出、增殖、空洞、钙化）。【为什么错】A：右肺中叶炎症多见于肺炎。C：基底段病变多见于坠积性肺炎、吸入性感染。D：舌叶受累较尖后段少见。E：前段少见。", "tr": "“上叶尖后段＋下叶背段”是肺结核经典定位；与肺脓肿（下叶背段多见）需结合临床鉴别。", "bk": "正高", "ref": {"篇": "胸部", "章": "肺感染", "节": "肺结核", "页": 127}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1024", "t": "共用题干题", "s": "结合上述情景，临床确诊肺栓塞（PE）首选的影像学检查方法是", "o": {"A": "X线胸片", "B": "CT肺动脉成像（CTPA）", "C": "超声心动图", "D": "核素肺通气灌注扫描", "E": "磁共振肺动脉成像"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-005", "kp": "肺栓塞检查方法选择", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTPA能直接显示肺动脉腔内血栓形成的充盈缺损，敏感性、特异性高且检查快速，已成为临床确诊肺栓塞的首选检查方法。【为什么错】A：胸片仅能提示肺血减少、楔形影等间接征象。C：超声用于评估右心功能及近端大栓子。D：核素通气灌注扫描假阳性率较高，多用于特殊人群。E：MRPA扫描时间长、伪影多，非首选。", "tr": "CTPA见肺动脉内“充盈缺损”或“截断”为直接征象，是确诊依据。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07155", "gs": ""}, {"id": "ZG-U07-1025", "t": "共用题干题", "s": "结合上述情景，主动脉夹层CT增强扫描最典型的直接征象是", "o": {"A": "主动脉腔内充盈缺损", "B": "内膜片及真假双腔征", "C": "主动脉壁环形钙化", "D": "主动脉管腔均匀扩张", "E": "心包积液"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-006", "kp": "主动脉夹层CT征象", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】主动脉夹层为内膜撕裂后血流进入中层，形成内膜片将主动脉腔分为真腔与假腔，增强CT清晰显示内膜片（线样低密度）及双腔影，是最重要的直接征象。【为什么错】A：管腔内充盈缺损见于血栓、栓子。C：主动脉壁环形钙化为动脉粥样硬化表现。D：管腔均匀扩张见于主动脉瘤。E：心包积液为夹层累及心包的继发表现。", "tr": "“内膜片＋双腔征”可确诊主动脉夹层；需与壁内血肿（新月形高密度）、穿透性溃疡鉴别。", "bk": "正高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07133", "gs": ""}, {"id": "ZG-U07-1026", "t": "单选题", "s": "大量心包积液胸部X线片的典型表现是", "o": {"A": "心影呈“靴型”", "B": "心影向两侧普大呈“烧瓶形”、心缘搏动减弱", "C": "心影呈“梨形”", "D": "主动脉结增宽", "E": "左心室段向左下延长"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-007", "kp": "心包积液X线表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】大量心包积液时心影向两侧普遍增大，呈烧瓶形或球形，心缘搏动减弱，而肺野清晰、肺血正常或减少，是心包积液的典型X线表现。【为什么错】A：靴形心见于法洛四联症等。C：梨形心多见于二尖瓣病变。D：主动脉结增宽见于高血压、主动脉病变。E：左心室段延长为左心室增大表现。", "tr": "“烧瓶心＋搏动减弱＋肺野清晰”提示心包积液；超声心动图可确诊并定量。", "bk": "正高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "心包炎", "页": 164}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1027", "t": "共用题干题", "s": "结合上述情景，前纵隔最常见的肿瘤是", "o": {"A": "神经源性肿瘤", "B": "胸腺瘤", "C": "畸胎瘤", "D": "淋巴瘤", "E": "胸内甲状腺肿"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-008", "kp": "纵隔肿瘤定位诊断", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】胸腺瘤位于前纵隔上中部，是前纵隔最常见的肿瘤，多见于成年人，可伴重症肌无力，CT表现为前纵隔软组织肿块。【为什么错】A：神经源性肿瘤多位于后纵隔脊柱旁。C：畸胎类肿瘤好发于前纵隔但发生率低于胸腺瘤。D：淋巴瘤多位于中纵隔。E：胸内甲状腺多位于上纵隔气管前方。", "tr": "“前纵隔＝胸腺瘤、畸胎瘤”“后纵隔＝神经源性肿瘤”“中纵隔＝淋巴瘤”是纵隔肿瘤定位口诀。", "bk": "正高", "ref": {"篇": "胸部", "章": "纵隔疾病", "节": "纵隔肿瘤", "页": 147}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07149", "gs": ""}, {"id": "ZG-U07-1028", "t": "共用题干题", "s": "结合上述情景，肝海绵状血管瘤CT增强扫描的典型强化特征是", "o": {"A": "动脉期整体均匀强化、门脉期明显减退", "B": "周边结节状强化、随时间向中心充填，延迟期仍呈高或等密度（早出晚归）", "C": "呈“牛眼征”", "D": "增强后无强化", "E": "中心坏死、厚壁环形强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-001", "kp": "肝血管瘤增强表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】海绵状血管瘤由血窦构成、血流缓慢，增强时对比剂自周边血窦向中心渐进性充填，呈“早出晚归”：动脉期周边结节状强化，门脉期及延迟期持续向心填充、延迟期仍为高密度或等密度。【为什么错】A：动脉期均匀强化并迅速廓清为肝细胞癌的“快进快出”表现。C：牛眼征为肝转移瘤特征。D：血管瘤富血供，明显强化。E：厚壁环形强化见于脓肿、转移瘤。", "tr": "“血管瘤早出晚归（向心填充）”与“肝癌快进快出”是腹部增强两大经典鉴别点，必考。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07153", "gs": ""}, {"id": "ZG-U07-1029", "t": "共用题干题", "s": "结合上述情景，肝细胞癌（HCC）增强CT、MRI典型的血供特征是", "o": {"A": "快进快出（动脉期明显强化、门脉期及延迟期廓清）", "B": "早出晚归（向心性填充）", "C": "进行性延迟强化", "D": "厚壁环形强化", "E": "增强后无强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-002", "kp": "肝细胞癌血供特征", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】HCC为富血供肿瘤，动脉期肿瘤实质明显强化（快进），门脉期及延迟期因对比剂廓清且肿瘤内缺乏正常门静脉供血而密度、信号下降（快出），呈“快进快出”。【为什么错】B：早出晚归为肝血管瘤特征。C：进行性延迟强化见于胆管癌及纤维组织成分。D：环形强化见于转移瘤、脓肿。E：HCC明显强化而非无强化。", "tr": "肝硬化背景下“快进快出”结节高度提示HCC，是LI-RADS主要征象之一。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07152", "gs": ""}, {"id": "ZG-U07-1030", "t": "共用题干题", "s": "结合上述情景，肝囊肿CT平扫的典型表现是", "o": {"A": "类圆形高密度灶", "B": "边界清楚、壁薄的近似水样低密度灶", "C": "混杂密度灶", "D": "团块状钙化灶", "E": "环形强化灶"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-003", "kp": "肝囊肿CT表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】单纯性肝囊肿为囊性病变，CT表现为边界清晰锐利、壁薄、CT值近似水的低密度灶，增强扫描无强化。【为什么错】A：高密度见于血肿、钙化。C：混杂密度见于肿瘤坏死、出血。D：钙化见于寄生虫病（包虫）等。E：环形强化提示脓肿、转移瘤。", "tr": "囊肿“水样密度＋无强化”，与肝脓肿（环形强化）、HCC（富血供）的鉴别关键在增强扫描。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07150", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1031", "t": "共用题干题", "s": "结合上述情景，急性水肿型胰腺炎CT表现中，下列哪项最符合其典型改变", "o": {"A": "胰腺萎缩伴散在钙化", "B": "胰腺弥漫增大、密度不均匀，胰周脂肪间隙模糊伴渗出，增强扫描无坏死区", "C": "胰头部囊实性肿块", "D": "胰腺内多发富血供强化结节", "E": "肝内外胆管明显扩张"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-004", "kp": "急性水肿型胰腺炎CT表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】急性水肿型胰腺炎CT显示胰腺弥漫性增大、边缘模糊、胰周脂肪密度增高（渗出、皂化），增强扫描胰腺实质均匀强化、无坏死区，此为水肿型与坏死型鉴别的关键。【为什么错】A：胰腺萎缩伴钙化为慢性胰腺炎表现。C：胰头囊实性肿块见于胰腺癌等。D：富血供强化结节为富血供肿瘤表现。E：胆管扩张提示胰头占位、壶腹病变。", "tr": "“水肿型均匀强化”与“坏死型无强化低密度区”的鉴别必须依靠增强扫描。", "bk": "正高", "ref": {"篇": "腹部", "章": "胆道", "节": "急性化脓性胆管炎", "页": 195}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07142", "gs": ""}, {"id": "ZG-U07-1032", "t": "单选题", "s": "小肠机械性肠梗阻立位腹部X线平片的典型征象是", "o": {"A": "膈下游离气体", "B": "阶梯状排列的气液平面", "C": "双泡征", "D": "结肠充气扩张", "E": "腹壁脂肪线消失"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-005", "kp": "肠梗阻X线征象", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】小肠机械性梗阻时梗阻近端小肠扩张、积气积液，立位片可见多个呈阶梯状排列的气液平面，结肠内气体减少，是机械性肠梗阻的典型X线表现。【为什么错】A：膈下游离气体提示消化道穿孔。C：双泡征见于十二指肠梗阻及婴幼儿幽门梗阻。D：结肠充气扩张见于低位结肠梗阻。E：腹壁脂肪线消失提示腹膜炎。", "tr": "“阶梯状气液平面＝小肠梗阻”“双泡征＝十二指肠梗阻”“结肠充气＝结肠梗阻”。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1033", "t": "共用题干题", "s": "结合上述情景，疑消化道穿孔时，立位腹部X线检查最具诊断价值的征象是", "o": {"A": "肠管普遍扩张", "B": "膈肌下方新月形游离气体影", "C": "盆腔积液", "D": "腰大肌影模糊", "E": "脊柱向一侧弯曲"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-006", "kp": "消化道穿孔气腹征", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】胃肠穿孔后气体进入腹腔，立位X线显示膈肌下方新月形、镰刀状游离气体影，是消化道穿孔最直接可靠的征象。【为什么错】A：肠管扩张为肠梗阻表现。C：盆腔积液无特异性。D：腰大肌影模糊提示腹膜后及腹膜炎症。E：脊柱弯曲为反射性表现，无特异性。", "tr": "少量气腹需立位或左侧卧位水平投照观察，右膈下气体最易显示。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07147", "gs": ""}, {"id": "ZG-U07-1034", "t": "共用题干题", "s": "结合上述情景，子宫肌瘤在MRI上最典型的信号特点是", "o": {"A": "T2WI呈均匀高信号", "B": "边界清楚，T2WI呈低信号", "C": "T1WI呈明显高信号", "D": "增强呈快进快出", "E": "DWI明显弥散受限"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-001", "kp": "子宫肌瘤MRI表现", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】子宫肌瘤主要由平滑肌与纤维结缔组织构成、含水量低，T2WI呈低信号为其特征，T1WI呈等信号；富细胞型、变性的肌瘤信号可变。【为什么错】A：T2WI高信号见于囊变、肌瘤变性或子宫内膜病变。C：T1WI高信号见于出血、脂肪成分。D：快进快出为富血供肿瘤特征，肌瘤为渐进性强化。E：肌瘤通常无明显弥散受限。", "tr": "“T2WI低信号肿块”是肌瘤特征；黏膜下肌瘤需与子宫内膜息肉鉴别。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07140", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1035", "t": "共用题干题", "s": "结合上述情景，前列腺癌在MRI（T2WI）上的典型表现是", "o": {"A": "外周带正常高信号", "B": "外周带出现结节状低信号灶", "C": "中央带呈高信号", "D": "整个前列腺均匀低信号", "E": "外周带弥漫性高信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-002", "kp": "前列腺癌MRI表现", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】前列腺外周带T2WI呈均匀高信号，前列腺癌多起源于外周带，表现为外周带结节状低信号灶，为MRI检出前列腺癌的重要征象，需结合DWI、动态增强及MRS综合判断。【为什么错】A：外周带高信号为正常表现。C：中央带（移行带）增生多呈中等信号。D：均匀低信号无诊断特异性。E：弥漫高信号不符。", "tr": "“外周带T2WI低信号结节”提示癌，但慢性前列腺炎、活检后瘢痕亦可呈低信号，需多参数MRI结合。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "前列腺癌", "页": 236}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07135", "gs": ""}, {"id": "ZG-U07-1036", "t": "共用题干题", "s": "结合上述情景，子宫内膜癌MRI检查中，评价肿瘤肌层浸润深度最重要的序列是", "o": {"A": "矢状位T2WI及动态增强扫描", "B": "轴位T1WI平扫", "C": "冠状位STIR", "D": "SWI", "E": "磁敏感加权成像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-003", "kp": "子宫内膜癌分期序列", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】矢状位T2WI及动态增强（DCE-MRI）可清晰显示子宫内膜与肌层的界面及强化差异，是判断肌层浸润深度（≥1/2为深浸润）的关键序列。【为什么错】B：T1WI平扫不能显示内膜—肌层分界。C：STIR主要用于骨髓及脂肪抑制。D：SWI用于显示出血、钙化及静脉，不用于浸润分期。E：磁敏感加权成像同SWI，不用于浸润分期评估。", "tr": "“矢状位＋动态增强”是子宫内膜癌分期的黄金方案，浸润深度直接影响治疗选择。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "子宫内膜癌", "页": 247}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07139", "gs": ""}, {"id": "ZG-U07-1037", "t": "单选题", "s": "Colles骨折的典型X线表现及移位特点是", "o": {"A": "桡骨远端骨折，远折端向背侧、桡侧移位呈“餐叉样”畸形", "B": "桡骨远端骨折，远折端向掌侧移位", "C": "尺骨远端向桡侧脱位", "D": "掌骨基底骨折", "E": "舟骨腰部骨折"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-001", "kp": "Colles骨折X线", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】Colles骨折即桡骨远端伸直型骨折，跌倒手掌撑地所致，远折端向背侧、桡侧移位，侧位观呈“餐叉样”畸形，为成人最常见的桡骨远端骨折。【为什么错】B：远折端向掌侧移位为Smith骨折（反Colles骨折）。C：尺骨远端移位描述错误。D：掌骨基底骨折为Bennett骨折相关。E：舟骨腰部骨折属腕舟骨骨折。", "tr": "Colles（背移）与Smith（掌移）是最易混淆的一对腕部骨折，注意移位方向。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1038", "t": "单选题", "s": "骨肉瘤最典型的X线征象是", "o": {"A": "日光放射状骨膜反应伴肿瘤骨", "B": "骨端偏心性皂泡样膨胀", "C": "葱皮样骨膜反应", "D": "骨内多发小圆形透亮区", "E": "以关节面破坏为主"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-002", "kp": "骨肉瘤X线表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】骨肉瘤为高度恶性骨肿瘤，肿瘤骨形成是其病理特征，X线表现为溶骨性或成骨性破坏、Codman三角、日光放射状骨膜反应及云絮状或象牙质样瘤骨，好发于青少年长骨干骺端。【为什么错】B：皂泡样膨胀性破坏为骨巨细胞瘤特征。C：葱皮样骨膜反应见于尤因肉瘤。D：多发小透亮区描述不特异。E：骨肉瘤以干骺端破坏为主，关节面破坏少见。", "tr": "“日光放射状＋Codman三角＋瘤骨”三征象对应骨肉瘤；“葱皮样”对应尤因肉瘤。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1039", "t": "共用题干题", "s": "结合上述情景，腰椎间盘突出症MRI矢状位T2WI最直接的诊断依据是", "o": {"A": "椎体终板T1WI高信号", "B": "椎间盘后缘局限性向后突出，压迫硬膜囊或神经根", "C": "椎管前后径普遍狭窄", "D": "黄韧带增厚", "E": "椎体前缘骨桥形成"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-003", "kp": "椎间盘突出MRI征象", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】矢状位T2WI可清晰显示椎间盘退变（髓核信号降低）及纤维环破裂后髓核局限性向后突出，硬膜囊受压、神经根受压移位，是椎间盘突出的直接诊断依据。【为什么错】A：终板信号改变为Modic改变，属继发征象。C：椎管普遍狭窄多因退变性骨增生。D：黄韧带肥厚为继发退变。E：椎体前缘骨桥为脊柱关节病表现。", "tr": "“膨出（后缘弧形完整）→突出（局限破出压迫）→脱出（游离）”三级须分清。", "bk": "正高", "ref": {"篇": "骨与骨关节", "章": "脊柱退行性病变", "节": "椎间盘及椎骨的退变过程", "页": 285}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07145", "gs": ""}, {"id": "ZG-U07-1040", "t": "单选题", "s": "骨巨细胞瘤X线最典型的征象是", "o": {"A": "骨干中心性溶骨伴葱皮样骨膜反应", "B": "骨端偏心性、膨胀性皂泡样溶骨破坏，一般无骨膜反应", "C": "皮质环形增厚", "D": "骨内日光放射状瘤骨", "E": "全身多发性病灶"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-004", "kp": "骨巨细胞瘤X线表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】骨巨细胞瘤好发于20～40岁长骨骨端，X线表现为骨端偏心性、膨胀性、皂泡样或分房状溶骨性破坏，皮质变薄，一般无骨膜反应。【为什么错】A：葱皮样骨膜反应为尤因肉瘤特征。C：皮质环形增厚不符。D：日光放射状瘤骨为骨肉瘤。E：骨巨细胞瘤多为单发。", "tr": "“骨端偏心皂泡样”是骨巨细胞瘤经典描述，与骨肉瘤（干骺端＋骨膜反应）鉴别。", "bk": "正高", "ref": {"篇": "骨与骨关节", "章": "硬膜外肿瘤和肿瘤样病变", "节": "骨巨细胞瘤", "页": 298}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1041", "t": "共用题干题", "s": "结合上述情景，老年性骨质疏松性椎体压缩骨折X线及MRI的典型表现是", "o": {"A": "椎体后缘骨性融合", "B": "椎体前缘高度减小呈楔形变，急性期T1WI低信号、T2WI及脂肪抑制序列高信号", "C": "椎体溶骨性破坏", "D": "椎旁软组织肿块", "E": "椎弓根骨质破坏消失"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-005", "kp": "椎体压缩骨折鉴别", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】骨质疏松性压缩骨折表现为椎体楔形变（前缘高度丢失），急性期骨髓水肿使T1WI低信号、T2WI及脂肪抑制序列（STIR）高信号，骨髓信号随愈合恢复。【为什么错】A：骨性融合为炎症愈合后表现。C：溶骨性破坏多见于转移瘤。D：椎旁软组织肿块提示肿瘤性病变。E：椎弓根破坏（pedicle sign）为恶性转移的重要征象。", "tr": "“椎弓根破坏”是鉴别骨质疏松性压缩骨折与恶性病理性骨折的关键点。", "bk": "正高", "ref": {"篇": "基础概念（绪论）", "章": "基本概念（X线物理/对比剂/成像基础）", "节": "骨质疏松", "页": null}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07144", "gs": ""}, {"id": "ZG-U07-1042", "t": "共用题干题", "s": "结合上述情景，影像学诊断主动脉瘤的标准是", "o": {"A": "主动脉局部管径较相邻正常段扩大超过50%", "B": "主动脉壁钙化", "C": "主动脉腔内血栓", "D": "主动脉弓迂曲延长", "E": "主动脉腔内见内膜片"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-001", "kp": "主动脉瘤诊断标准", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】动脉瘤定义为动脉局部管径较相邻正常段扩大50%以上（如腹主动脉直径＞3 cm或超过相邻正常段1.5倍），影像学据此诊断。【为什么错】B：主动脉壁钙化为动脉粥样硬化表现。C：腔内血栓可为动脉瘤伴发改变但非诊断标准。D：迂曲延长为退行性改变。E：内膜片提示主动脉夹层。", "tr": "“直径＞正常段1.5倍”或“腹主动脉＞3 cm”为动脉瘤诊断阈值。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "动脉瘤", "页": 33}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07134", "gs": ""}, {"id": "ZG-U07-1043", "t": "共用题干题", "s": "结合上述情景，下肢深静脉血栓静脉造影（DSA）最直接可靠的征象是", "o": {"A": "静脉腔内造影剂充盈缺损", "B": "静脉壁线状钙化", "C": "静脉普遍扩张", "D": "周围软组织肿胀", "E": "邻近骨膜反应"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-002", "kp": "下肢深静脉血栓DSA征象", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】深静脉血栓造影时血栓占据部分管腔形成腔内充盈缺损，若血栓完全闭塞则静脉段不显影，均是最直接可靠的征象。【为什么错】B：静脉壁钙化少见且非直接征象。C：静脉扩张为非特异改变。D：软组织肿胀为继发表现。E：骨膜反应与静脉病变无关。", "tr": "“腔内充盈缺损”“静脉不显影”“侧支循环建立”是深静脉血栓造影三大征象。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07129", "gs": ""}, {"id": "ZG-U07-1044", "t": "共用题干题", "s": "结合上述情景，评估颈动脉狭窄程度最精确、作为金标准的血管成像方法是", "o": {"A": "CT血管成像（CTA）", "B": "彩色多普勒超声", "C": "数字减影血管造影（DSA）", "D": "磁共振血管成像（MRA）", "E": "X线平片"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-003", "kp": "颈动脉狭窄评估方法", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】DSA空间分辨力高、可动态显示血流，是评估血管管腔狭窄程度及血管病变的金标准，也是介入治疗的依据。【为什么错】A：CTA为无创，能显示斑块钙化但对细小血管及迂曲段狭窄率测量仍有偏差。B：超声为常用筛查方法。D：MRA可能夸大狭窄程度。E：X线平片不能显示血管腔。", "tr": "“超声筛查→CTA/MRA无创评估→DSA金标准”是颈动脉狭窄检查路径。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "总论", "节": "头颅CT检查方法", "页": 12}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07161", "gs": ""}, {"id": "ZG-U07-1045", "t": "共用题干题", "s": "结合上述情景，外周神经MRI（MR神经成像）中，受损神经的典型表现是", "o": {"A": "神经增粗、T2WI信号增高、内部束状结构显示不清", "B": "神经变细、T1WI高信号", "C": "神经钙化", "D": "神经周围气体", "E": "神经信号无任何改变"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-004", "kp": "外周神经损伤MRI表现", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (3)MR诊断要点", "ex": "【为什么对】外周神经损伤后神经水肿、神经束膜增厚，MR神经成像（MRN）表现为神经增粗、T2WI及脂肪抑制序列信号增高、束状结构显示不清，增强可强化。【为什么错】B：受损神经增粗而非变细，T1WI高信号多见于脂肪或出血。C：神经钙化少见。D：神经周围气体见于外伤产气。E：正常神经无改变。", "tr": "“神经增粗＋T2WI高信号”是神经卡压、损伤的MRN核心表现，需与神经鞘瘤（偏心强化）鉴别。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07137", "gs": ""}, {"id": "ZG-U07-1101", "t": "多选题", "s": "关于脑转移瘤MRI表现，正确的有", "o": {"A": "多为多发圆形病灶", "B": "增强呈结节状或环形强化", "C": "瘤周水肿明显，呈“小病灶大水肿”", "D": "DWI可显示病灶弥散受限程度不一", "E": "所有病灶T2WI均呈均匀低信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-014", "kp": "脑转移瘤MRI表现", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】脑转移瘤多为多发圆形、类圆形病灶，增强后呈结节状或环形强化，瘤周水肿明显呈小病灶大水肿，DWI上弥散受限程度因肿瘤类型而异。【为什么错】E：转移瘤T2WI多呈高信号，病灶中心坏死囊变时信号更高、不均，并非均匀低信号。", "tr": "“小病灶大水肿＋多发＋环形强化”是转移瘤三联征；单发转移与胶质瘤的鉴别需结合全身筛查。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1102", "t": "共用题干题", "s": "结合上述情景，超急性期脑梗死CT早期可显示的征象有", "o": {"A": "岛带（岛叶皮层）模糊消失", "B": "大脑中动脉高密度征（致密动脉征）", "C": "灰白质界限模糊", "D": "患侧脑沟普遍增宽", "E": "侧脑室明显扩张变形"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-015", "kp": "超急性期脑梗死CT早期征象", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】超急性期脑梗死CT可显示岛带模糊、大脑中动脉高密度征、灰白质界限消失等早期征象，提示大面积梗死，为临床溶栓决策提供依据。【为什么错】D：患侧脑沟增宽、E：脑室扩张变形均为慢性期脑萎缩、梗死软化灶的晚期表现，不是超急性期征象。", "tr": "“岛带征、致密动脉征、灰白质界限消失”是梗死早期三大征象，代表大面积MCA区梗死。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07160", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1103", "t": "共用题干题", "s": "结合上述情景，关于脑膜瘤MRI表现，正确的有", "o": {"A": "T1WI多呈等信号", "B": "T2WI呈等或稍高信号", "C": "增强后明显均匀强化", "D": "可见“脑膜尾征”", "E": "增强后无强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-016", "kp": "脑膜瘤MRI表现", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】脑膜瘤T1WI、T2WI多呈等或稍高信号，增强后明显均匀强化，常伴宽基底贴附硬脑膜及“脑膜尾征”，DWI多不受限。【为什么错】E：脑膜瘤为富血供肿瘤，增强后明显均匀强化，不会无强化。", "tr": "脑膜瘤“等T1等T2＋明显强化＋脑膜尾征”；脑膜尾征也可见于结节病、转移瘤脑膜受累，非特有。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "感染性病变", "节": "脑膜炎", "页": 40}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07158", "gs": ""}, {"id": "ZG-U07-1104", "t": "多选题", "s": "鼻骨骨折CT检查的常见征象有", "o": {"A": "鼻骨骨质连续性中断", "B": "碎骨片移位", "C": "周围软组织肿胀", "D": "上颌窦黏液囊肿", "E": "额窦窦壁骨质增生硬化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-007", "kp": "鼻骨骨折CT表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】鼻骨骨折CT表现为鼻骨骨质连续性中断、碎骨片移位错位、周围软组织肿胀，合并鼻中隔骨折时可见鼻中隔偏曲变形。【为什么错】D：上颌窦黏液囊肿为窦口阻塞的囊性病变，与外伤无关。E：额窦窦壁增生硬化为慢性炎症改变，非骨折表现。", "tr": "薄层CT（层厚≤1 mm）结合冠矢状位重组是显示细微鼻骨骨折的关键。", "bk": "正高", "ref": {"篇": "头颈部", "章": "耳和颞骨", "节": "颞骨骨折", "页": 88}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1105", "t": "共用题干题", "s": "结合上述情景，急性中耳乳突炎CT表现的常见征象有", "o": {"A": "鼓室黏膜增厚、鼓室内软组织影", "B": "乳突气房混浊、密度增高", "C": "鼓室内气液平面", "D": "内听道明显扩大", "E": "岩尖骨质破坏"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-008", "kp": "急性中耳乳突炎CT表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】急性中耳乳突炎CT表现为鼓室黏膜增厚、鼓室内软组织影及气液平面，乳突气房混浊、密度增高，气房间隔可增粗。【为什么错】D：内听道扩大为听神经瘤的征象。E：岩尖骨质破坏提示岩尖部病变或胆脂瘤、恶性肿瘤，单纯急性中耳乳突炎不出现。", "tr": "急性中耳炎“软组织＋气液平”；胆脂瘤“软组织＋骨质破坏”；两者鉴别看骨壁。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07142", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1106", "t": "共用题干题", "s": "结合上述情景，提示甲状腺结节为恶性的影像学征象有", "o": {"A": "结节内微小钙化（沙砾样钙化）", "B": "边缘不规则、呈分叶状", "C": "超声表现为低回声", "D": "伴颈部区域淋巴结肿大", "E": "以单纯囊性变为主"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-009", "kp": "甲状腺恶性结节征象", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】微小钙化、边缘不规则或分叶、低回声及淋巴结转移均提示甲状腺结节恶性倾向，应结合细针穿刺活检明确。【为什么错】E：以单纯囊性变为主的结节多为良性（腺瘤囊变、胶质囊肿），但囊壁明显增厚或囊内实性成分时仍需警惕。", "tr": "“微钙化＋边缘不规＋低回声＋淋巴结”为恶性四征；单纯囊变偏向良性但需结合整体。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07148", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1107", "t": "多选题", "s": "鼻咽癌CT常见的直接与间接征象有", "o": {"A": "鼻咽顶后壁及侧壁软组织增厚形成肿块", "B": "咽隐窝变浅、消失", "C": "咽旁间隙受累", "D": "颅底骨质破坏", "E": "肿块内密集钙化灶"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-010", "kp": "鼻咽癌CT表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】鼻咽癌以咽隐窝为中心生长，CT示鼻咽壁软组织肿块、咽隐窝消失，可侵犯咽旁间隙、颅底骨质，并伴颈部淋巴结转移。【为什么错】E：鼻咽癌内钙化少见，密集钙化灶更常见于脊索瘤等含钙化病变。", "tr": "“咽隐窝消失＋咽旁间隙受侵＋颅底骨破坏”是鼻咽癌侵犯评估要点，咽旁间隙脂肪层消失提示受侵。", "bk": "正高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "鼻咽部病变", "页": 103}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1108", "t": "多选题", "s": "气胸CT检查的典型表现有", "o": {"A": "脏层胸膜线清晰可见", "B": "胸腔内无肺纹理的透亮区", "C": "肺组织受压、肺不张", "D": "大量气胸时纵隔向健侧移位", "E": "常合并大量胸腔积液"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-009", "kp": "气胸CT表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CT能清晰显示气胸的脏层胸膜线、无肺纹理的胸腔透亮区及受压不张的肺组织，大量气胸可致纵隔移位、膈肌下降。【为什么错】E：单纯气胸不含并大量积液；血气胸时才出现液气平面。", "tr": "CT对少量气胸及伴发肺大疱的检出优于X线，是评估复发及术前检查手段。", "bk": "正高", "ref": {"篇": "胸部", "章": "胸膜疾病", "节": "气胸与液气胸", "页": 142}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1109", "t": "共用题干题", "s": "结合上述情景，肺栓塞CTPA的常见征象有", "o": {"A": "肺动脉内充盈缺损", "B": "肺动脉分支截断", "C": "肺外周楔形实变影（肺梗死）", "D": "右心室增大", "E": "主动脉壁环形钙化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-010", "kp": "肺栓塞CTPA征象", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTPA直接征象为肺动脉内充盈缺损及血管截断，间接征象包括肺梗死（楔形实变）、右心室增大、胸腔积液等。【为什么错】E：主动脉壁环形钙化为动脉粥样硬化表现，与肺栓塞无关。", "tr": "急性PE评估还需观察右心功能（RV/LV比值）、血栓位于中心或外周，直接影响治疗策略。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07155", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1110", "t": "共用题干题", "s": "结合上述情景，主动脉夹层CTA检查可显示的征象有", "o": {"A": "内膜片将主动脉腔分为真假双腔", "B": "真腔较小、血流快，假腔较大、可伴血栓", "C": "增强扫描可显示内膜破口", "D": "可显示分支血管受累及灌注异常", "E": "主动脉壁环形钙化为最直接征象"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-011", "kp": "主动脉夹层CTA全面评估", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTA可显示内膜片、真假双腔、破口位置、假腔血栓及分支血管（冠脉、头臂干、内脏动脉）受累情况，是术前评估的金标准之一。【为什么错】E：主动脉壁环形钙化是动脉粥样硬化表现，而非夹层直接征象。", "tr": "Stanford分型看升主动脉是否受累（A型累及升主动脉）；DebakeyⅠ、Ⅱ、Ⅲ分型勿混淆。", "bk": "正高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ07132", "gs": ""}, {"id": "ZG-U07-1111", "t": "共用题干题", "s": "结合上述情景，中央型肺癌CT的常见表现有", "o": {"A": "肺门区肿块", "B": "支气管管腔狭窄或截断", "C": "阻塞性肺不张", "D": "阻塞性肺炎", "E": "两肺弥漫性粟粒样小结节"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-012", "kp": "中央型肺癌CT表现", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】中央型肺癌CT表现为肺门肿块、支气管狭窄或截断，继发阻塞性肺不张、阻塞性肺炎及远端黏液潴留。【为什么错】E：两肺弥漫粟粒样结节为急性粟粒型肺结核表现，与中央型肺癌无直接关系。", "tr": "“阻塞性肺不张＋肺门肿块”是中央型肺癌特征；阻塞性肺炎反复不吸收应警惕肿瘤。", "bk": "正高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "心脏大血管病变的基本CT表现", "页": 158}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07130", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1112", "t": "共用题干题", "s": "结合上述情景，肝海绵状血管瘤MRI的典型表现有", "o": {"A": "T2WI呈明显高信号（灯泡征）", "B": "增强周边结节状强化、向心性填充", "C": "延迟期持续强化呈等或高信号", "D": "动脉期整体强化并迅速廓清", "E": "增强后无强化"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-007", "kp": "肝血管瘤MRI表现", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】血管瘤T2WI呈显著高信号，即“灯泡征”，动态增强呈周边结节状强化并随时间向心性充填，延迟期仍持续强化，为“早出晚归”。【为什么错】D：动脉期整体强化并迅速廓清为肝癌“快进快出”表现。E：血管瘤富血供，明显强化而非无强化。", "tr": "“重T2WI灯泡征＋向心性充填＋延迟持续强化”是血管瘤MRI三联征。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07153", "gs": ""}, {"id": "ZG-U07-1113", "t": "共用题干题", "s": "结合上述情景，肝细胞癌（HCC）CT增强扫描的典型表现有", "o": {"A": "动脉期肿瘤明显强化（快进）", "B": "门脉期及延迟期强化减退（快出）", "C": "可见假包膜", "D": "可伴门静脉癌栓", "E": "延迟期仍明显强化、廓清不明显"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-008", "kp": "肝细胞癌CT表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】HCC动脉期明显强化，门脉期、延迟期廓清呈低密度，部分病灶可见假包膜，可侵犯门静脉形成癌栓及肝内转移。【为什么错】E：延迟期明显强化、廓清不明显是血管瘤或胆管癌表现，HCC为廓清型。", "tr": "“动脉期强化＋门脉期廓清＋假包膜＋门脉癌栓”为HCC典型组合；癌栓是肿瘤血行转移证据。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07151", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1114", "t": "共用题干题", "s": "结合上述情景，急性胰腺炎CT的常见表现有", "o": {"A": "胰腺弥漫性增大", "B": "胰周脂肪密度增高、渗出", "C": "肾前筋膜增厚", "D": "病程中可并发假性囊肿", "E": "胰腺萎缩伴钙化"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-009", "kp": "急性胰腺炎CT表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】急性胰腺炎CT示胰腺增大、胰周脂肪渗出密度增高、肾前筋膜增厚，重症可伴坏死、液体积聚，后期可形成假性囊肿。【为什么错】E：胰腺萎缩伴钙化为慢性胰腺炎的典型表现。", "tr": "增强CT是判断胰腺坏死的关键；CT严重指数（CTSI）结合坏死范围评估预后。", "bk": "正高", "ref": {"篇": "腹部", "章": "胰腺", "节": "急性胰腺炎", "页": 196}, "hf": true, "src": "正高拓展", "mk": 1, "gid": "GZ07143", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1115", "t": "多选题", "s": "关于肾结石影像学表现，正确的有", "o": {"A": "腹部平片可见肾盂内高密度结石影", "B": "鹿角形结石为肾盂肾盏铸型结石", "C": "结石可继发肾盂肾盏扩张积水", "D": "尿酸结石在X线平片上可不显影", "E": "增强扫描后结石明显强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-010", "kp": "肾结石影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】阳性结石（含钙）平片呈高密度，鹿角形结石铸型于肾盂肾盏，结石梗阻可致积水；尿酸结石密度低、平片可不显影，但CT均能显示。【为什么错】E：结石不摄取对比剂，增强扫描后不强化。", "tr": "“阴性结石（尿酸）X线不显影但CT可显示”，CT是尿路结石最敏感的检查。", "bk": "正高", "ref": {"篇": "腹部", "章": "肾感染性病变", "节": "肾结核", "页": 220}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1116", "t": "共用题干题", "s": "结合上述情景，关于消化道穿孔影像学表现，正确的有", "o": {"A": "立位X线示膈下新月形游离气体影", "B": "左侧卧位水平投照可显示肝表面少量游离气体", "C": "十二指肠腹膜后段穿孔可显示腹膜后气肿", "D": "CT可发现平片阴性的少量气腹", "E": "肠管阶梯状排列的气液平面为穿孔特征性表现"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-011", "kp": "消化道穿孔影像表现", "ch": "七、影像诊断学基础 → 4.腹部 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】消化道穿孔以膈下游离气体为主要征象，少量气腹需左侧卧位水平投照或CT检出，腹膜后穿孔可致腹膜后积气，CT对少量气腹敏感。【为什么错】E：阶梯状气液平面是机械性肠梗阻的表现，不是穿孔特征。", "tr": "气腹量少时“左侧卧位水平投照＋CT薄层”是关键；穿孔部位不同气体分布各异。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07147", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1117", "t": "共用题干题", "s": "结合上述情景，子宫肌瘤MRI的常见表现有", "o": {"A": "T2WI呈低信号", "B": "黏膜下肌瘤可使宫腔受压变形", "C": "浆膜下肌瘤向子宫外突出", "D": "变性的肌瘤信号可不均匀", "E": "所有肌瘤T2WI均呈均匀高信号"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-004", "kp": "子宫肌瘤MRI表现", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】肌瘤T2WI多呈低信号，按位置分黏膜下、肌壁间、浆膜下，分别引起宫腔变形、宫腔受压和向外突出；玻璃样变、囊变、红色变性时信号不均。【为什么错】E：肌瘤典型信号为低信号而非高信号，且变性时信号不均。", "tr": "肌瘤位置决定症状与术式；“富细胞肌瘤”可呈高信号，需与平滑肌肉瘤鉴别。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07140", "gs": ""}, {"id": "ZG-U07-1118", "t": "多选题", "s": "提示卵巢囊性病变为恶性的影像学征象有", "o": {"A": "囊壁增厚、不规则", "B": "囊壁或分隔上的实性结节", "C": "分隔增厚（＞3 mm）", "D": "伴腹水或腹膜种植", "E": "单纯薄壁、均匀水样囊肿"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-005", "kp": "卵巢恶性肿瘤征象", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (2)CT诊断要点", "ex": "【为什么对】囊壁增厚不规则、实性壁结节、增厚分隔、腹水及腹膜种植均提示卵巢恶性肿瘤；囊实混合性肿块伴腹水为晚期表现。【为什么错】E：单纯薄壁均匀水样囊肿为典型良性表现（单纯性囊肿）。", "tr": "卵巢囊性肿块“实性成分是恶性的核心指标”，结合CA125及年龄综合判断。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢畸胎瘤", "页": 240}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1119", "t": "多选题", "s": "多参数MRI诊断前列腺癌的典型表现有", "o": {"A": "外周带T2WI结节状低信号", "B": "DWI呈高信号、ADC值降低", "C": "动态增强早期快速强化", "D": "可侵犯精囊腺及神经血管束", "E": "MRS示枸橼酸盐峰明显升高"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-006", "kp": "前列腺癌多参数MRI", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】前列腺癌MRI表现为外周带T2WI低信号结节、DWI高信号ADC降低、动态增强早期强化，并可见包膜外侵犯、精囊受累；MRS示枸橼酸盐降低、胆碱升高。【为什么错】E：前列腺癌MRS特征为枸橼酸盐峰降低、胆碱峰升高，而非枸橼酸盐升高。", "tr": "“T2低＋DWI高＋早期强化”提示癌；MRS“枸橼酸低、胆碱高”是代谢特征。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "前列腺癌", "页": 236}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1120", "t": "共用题干题", "s": "结合上述情景，腰椎间盘突出MRI的常见表现有", "o": {"A": "椎间盘后缘局限性突出", "B": "硬膜囊受压变形", "C": "神经根受压移位", "D": "脱出的髓核可游离于椎管内", "E": "椎体前缘骨桥为直接诊断依据"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-006", "kp": "椎间盘突出MRI表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】MRI矢状位及轴位可显示椎间盘后缘局限性突出、硬膜囊及神经根受压，髓核完全脱出时可游离至椎管内上下移动。【为什么错】E：椎体前缘骨桥是脊柱退变（DISH、脊柱关节病）表现，与椎间盘突出无直接关系。", "tr": "“突出—脱出—游离”以纤维环破裂及髓核位置划分；中央型与旁中央型压迫结构不同。", "bk": "正高", "ref": {"篇": "骨与骨关节", "章": "脊柱退行性病变", "节": "椎间盘及椎骨的退变过程", "页": 285}, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07145", "gs": ""}, {"id": "ZG-U07-1121", "t": "多选题", "s": "骨肉瘤X线的典型表现有", "o": {"A": "溶骨性或成骨性骨质破坏", "B": "肿瘤骨形成", "C": "Codman三角", "D": "日光放射状骨膜反应", "E": "葱皮样骨膜反应为其最特征表现"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-007", "kp": "骨肉瘤X线表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】骨肉瘤以骨质破坏、肿瘤骨、Codman三角及日光放射状骨膜反应为典型X线表现，肿瘤骨是确诊的组织学依据。【为什么错】E：葱皮样骨膜反应为尤因肉瘤的典型表现，不是骨肉瘤特征。", "tr": "骨肉瘤“日光放射状”，尤因肉瘤“葱皮样”，软骨肉瘤“环状钙化”，三骨肿瘤骨膜反应对比。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1122", "t": "多选题", "s": "股骨颈骨折按骨折线部位分型，正确的类型有", "o": {"A": "头下型", "B": "头颈型", "C": "经颈型", "D": "基底型", "E": "转子间型"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-008", "kp": "股骨颈骨折分型", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】股骨颈骨折按骨折线所在部位分为头下型、头颈型、经颈型、基底型，头下型血供破坏最重、股骨头缺血坏死发生率最高。【为什么错】E：转子间骨折位于股骨颈基底以远的小转子上下区域，不属于股骨颈骨折分型。", "tr": "“头下型易缺血坏死”是分型意义所在；转子间骨折血供好、愈合快，两者预后不同。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1123", "t": "多选题", "s": "骨性关节病（骨关节退行性变）X线的典型表现有", "o": {"A": "关节间隙变窄", "B": "关节面边缘骨赘形成", "C": "软骨下骨质硬化", "D": "关节面下囊性变", "E": "关节软骨钙化呈“双轨征”为最常见表现"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-009", "kp": "骨性关节病X线表现", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】骨性关节病以关节间隙非对称性变窄、骨赘、软骨下硬化及囊变为基本X线表现，好发于承重大关节。【为什么错】E：关节软骨钙化（双轨征）为焦磷酸盐沉积病（CPPD）表现，不是退行性骨关节病的常见特征。", "tr": "“关节间隙窄＋骨赘＋硬化”为骨性关节炎三征；软骨钙化另属晶体性关节病。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U07-1124", "t": "共用题干题", "s": "结合上述情景，下肢深静脉血栓静脉造影（DSA）的典型征象有", "o": {"A": "静脉腔内充盈缺损", "B": "静脉段不显影（闭塞）", "C": "侧支循环建立", "D": "静脉石钙化为直接征象", "E": "动脉期提前显影"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-005", "kp": "下肢深静脉血栓DSA征象", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】深静脉血栓造影直接征象为腔内充盈缺损，完全闭塞时该段静脉不显影，并见侧支循环开放迂曲。【为什么错】D：静脉石为静脉内陈旧血栓钙化形成的小钙化点，不是造影直接征象。E：动脉期提前显影见于动静脉瘘，与静脉血栓无关。", "tr": "“充盈缺损＋不显影＋侧支”为深静脉血栓造影三征；静脉石是既往血栓的平片标志。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07129", "gs": ""}, {"id": "ZG-U07-1125", "t": "共用题干题", "s": "结合上述情景，关于颈动脉狭窄的影像学评估，正确的有", "o": {"A": "彩色多普勒超声为常用筛查方法", "B": "CTA可同时显示管腔狭窄及斑块钙化", "C": "DSA是管腔狭窄评估的金标准", "D": "高分辨MRI可显示斑块内出血及纤维帽", "E": "X线平片可精确测量狭窄程度"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-006", "kp": "颈动脉狭窄影像评估", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】颈动脉狭窄评估遵循“超声筛查→CTA/MRA无创评估→DSA金标准”路径，高分辨MRI还能评价斑块稳定性（易损斑块）。【为什么错】E：X线平片不能显示血管腔及狭窄，无法测量狭窄程度。", "tr": "NASCET法以狭窄远端正常管径为参考测量狭窄率；易损斑块（脂质核大、纤维帽薄）是脑梗死危险因素。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 1, "gid": "GZ07161", "gs": ""}, {"id": "ZG-U07-1201a", "t": "共用题干题", "s": "结合上述情景，该患者应诊断为何种疾病", "o": {"A": "脑梗死", "B": "左侧基底节区高血压性脑出血", "C": "脑膜瘤", "D": "脑脓肿", "E": "蛛网膜囊肿"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-017", "kp": "基底节脑出血诊断", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】老年高血压患者突发意识障碍及偏瘫，CT示基底节区高密度影，符合高血压性脑出血的典型部位与影像特征。【为什么错】A：脑梗死CT急性期多为低密度且发病数小时常阴性。C：脑膜瘤为脑外等密度肿块。D：脑脓肿呈低密度伴环形强化。E：蛛网膜囊肿为水样低密度。", "tr": "“突发神经功能障碍＋基底节高密度”＝高血压脑出血，病史与密度是关键。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07136", "gs": ""}, {"id": "ZG-U07-1201b", "t": "共用题干题", "s": "结合上述情景，该患者出血量较少、病情平稳，关于血肿演变过程及影像复查，正确的是", "o": {"A": "血肿密度由高到低演变，约2～3周后逐渐变为等、低密度", "B": "血肿密度随时间由低变高", "C": "血肿周边水肿在急性期持续加重", "D": "亚急性期MRI T2WI血肿均为低信号", "E": "血肿吸收后无任何影像残留"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-018", "kp": "脑出血血肿演变规律", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (2)CT诊断要点", "ex": "【为什么对】脑出血血肿CT密度按“高→等→低”演变，约2～3周后血肿液化呈低密度，周边水肿于急性期达到高峰后逐渐消退。【为什么错】B：密度由高变低而非由低变高。C：水肿在出血后数小时至数天达高峰，之后逐步消退，并非持续加重。D：亚急性后期T2WI为高信号。E：慢性期可残留含铁血黄素环及裂隙样改变，并非无任何残留。", "tr": "“高→等→低”是CT随访判断血肿演化的轴线；吸收期增强可出现环形强化，勿误认为肿瘤。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07157", "gs": ""}, {"id": "ZG-U07-1201c", "t": "共用题干题", "s": "结合上述情景，该患者出血2周后复查MRI，血肿周边出现T2WI低信号环，其病理基础是", "o": {"A": "含铁血黄素沉积", "B": "正铁血红蛋白", "C": "氧合血红蛋白", "D": "胆固醇结晶", "E": "钙盐沉积"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-019", "kp": "脑出血慢性期含铁血黄素", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】血肿慢性期（出血数周后）巨噬细胞吞噬并沉积含铁血黄素，含铁血黄素为顺磁性物质，使局部T2WI呈低信号环，可持续多年。【为什么错】B：正铁血红蛋白见于亚急性期，T1WI高信号。C：氧合血红蛋白见于超急性期。D：胆固醇结晶见于胆固醇肉芽肿。E：钙盐沉积T1WI、T2WI均低信号且常伴CT高密度钙化。", "tr": "“慢性期T2WI低信号环＝含铁血黄素”与“亚急性期双高”是出血信号分期两大标志。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "血管性疾病", "节": "脑出血", "页": 37}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ07157", "gs": ""}, {"id": "ZG-U07-1202a", "t": "单选题", "s": "【病例】患者男，22岁，体型瘦高，吸烟5年，突发右侧胸痛、呼吸困难1小时来诊。查体：右肺呼吸音减低，叩诊鼓音。X线胸片示右肺野外带无肺纹理透亮区，可见脏层胸膜线，肺组织受压约30%，纵隔无明显移位。 该患者最可能的疾病诊断是", "o": {"A": "大量胸腔积液", "B": "自发性气胸", "C": "肺大疱", "D": "肺栓塞", "E": "纵隔气肿"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-013", "kp": "自发性气胸诊断", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (1)常见疾病普通X线诊断要点", "ex": "【为什么对】青年瘦高体型、突发胸痛呼吸困难，胸片示肺野外带透亮无肺纹理并见脏层胸膜线，符合自发性气胸。【为什么错】A：胸腔积液呈均匀致密影伴肋膈角变钝，无透亮区。C：肺大疱为肺内薄壁空腔，其内可见纤细肺纹理。D：肺栓塞以血供改变为主。E：纵隔气肿沿纵隔分布。", "tr": "“瘦高青年＋突发胸痛＋脏层胸膜线”＝自发性气胸，多与肺尖胸膜下肺大疱破裂有关。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1202b", "t": "单选题", "s": "该患者保守治疗后症状反复发作，为评估肺尖部肺大疱及胸膜情况，应首选的影像学检查是", "o": {"A": "胸部X线正侧位片", "B": "高分辨率CT（HRCT）", "C": "胸部超声", "D": "肺通气灌注显像", "E": "胸部MRI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-014", "kp": "肺大疱HRCT评估", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】HRCT薄层高分辨率扫描能清晰显示肺尖胸膜下肺大疱的数目、大小及气胸复发相关病变，是评估肺大疱及指导手术的首选。【为什么错】A：X线平片对肺大疱显示有限。C：超声难以观察肺尖含气病变。D：通气灌注显像用于肺栓塞、肺功能评估。E：MRI对含气肺组织显示差。", "tr": "HRCT是肺大疱、肺气肿及间质性病变评估的标准方法，薄层＋高分辨率重建。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1203a", "t": "共用题干题", "s": "结合上述情景，该患者首先应考虑的诊断是", "o": {"A": "肝血管瘤", "B": "肝细胞癌", "C": "肝囊肿", "D": "肝脓肿", "E": "肝转移瘤"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-012", "kp": "肝细胞癌增强诊断", "ch": "七、影像诊断学基础 → 4.腹部 → (2)CT诊断要点", "ex": "【为什么对】乙肝肝硬化背景＋AFP升高＋增强“快进快出”，高度提示肝细胞癌，符合HCC富血供及廓清的典型特征。【为什么错】A：血管瘤呈周边结节状向心性填充的早出晚归。C：囊肿无强化。D：脓肿厚壁环形强化伴临床感染征象。E：转移瘤多为多发环形强化。", "tr": "“乙肝＋AFP↑＋快进快出”是HCC三大诊断线索，结节伴门脉期廓清最特异。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ07152", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1203b", "t": "共用题干题", "s": "结合上述情景，为进一步确诊并全面评估该病变，拟行肝脏MRI检查，其典型的MR表现是", "o": {"A": "T1WI明显高信号、T2WI显著高信号伴向心性充填", "B": "T1WI稍低信号、T2WI稍高信号，动态增强呈快进快出，可伴假包膜", "C": "T1WI、T2WI均呈水样信号且无强化", "D": "T2WI呈均匀低信号", "E": "增强后无强化"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-013", "kp": "肝细胞癌MRI特征", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】HCC在MRI上呈T1WI稍低、T2WI稍高信号，动态增强呈快进快出，部分可见假包膜（T1WI低信号环），符合典型HCC特征。【为什么错】A：T1WI高信号伴T2WI显著高信号向心性充填为血管瘤特征。C：水样信号无强化为囊肿。D：T2WI低信号见于含铁沉积或纤维化。E：HCC为富血供肿瘤，明显强化。", "tr": "HCC“T1稍低T2稍高＋快进快出＋假包膜”与血管瘤“T2明显高＋向心充填”是MR鉴别要点。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝细胞腺瘤", "页": 171}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07151", "gs": ""}, {"id": "ZG-U07-1204a", "t": "单选题", "s": "【病例】患者男，45岁，搬运工人，腰痛伴左下肢放射痛、麻木3个月，查体直腿抬高试验阳性。MRI矢状位示L4/5椎间盘信号减低，向后方局限性突出，硬膜囊受压，左侧神经根受压移位。 该患者最可能的诊断是什么", "o": {"A": "腰椎结核", "B": "腰椎间盘突出症", "C": "腰椎转移瘤", "D": "腰椎管狭窄症", "E": "腰肌劳损"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-010", "kp": "腰椎间盘突出症诊断", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】中青年重体力劳动者，腰痛伴下肢放射痛、直腿抬高试验阳性，MRI示L4/5椎间盘后突压迫硬膜囊，符合腰椎间盘突出症。【为什么错】A：腰椎结核伴椎体破坏、椎旁脓肿。C：转移瘤椎弓根破坏、椎体溶骨。D：椎管狭窄为骨性椎管普遍狭窄。E：腰肌劳损无神经根受压影像表现。", "tr": "“下肢放射痛＋直腿抬高阳性＋MRI后突压迫”=椎间盘突出；L4/5、L5/S1为最好发节段。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1204b", "t": "共用题干题", "s": "结合上述情景，该患者拟加行腰椎CT检查，CT平扫对椎间盘突出的主要诊断价值在于", "o": {"A": "显示突出的椎间盘及其与硬膜囊、神经根的关系，并可显示髓核钙化及骨性椎管狭窄", "B": "显示神经根水肿程度", "C": "定量测量脑脊液流速", "D": "显示脊髓缺血灌注", "E": "观察马尾神经的电生理信号"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-011", "kp": "椎间盘突出CT诊断价值", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (2)CT诊断要点", "ex": "【为什么对】CT轴位可显示椎间盘后缘突出、硬膜囊及神经根受压关系，并显示髓核钙化、骨性椎管狭窄及小关节退变等伴发改变，与MRI互补。【为什么错】B：神经根水肿需MRI观察。C：脑脊液流速测定为MR相位对比法。D：脊髓缺血灌注需MR灌注成像。E：电生理信号非影像检查内容。", "tr": "CT看“骨性与钙化”，MRI看“软组织与髓核信号”，两者结合评估椎间盘突出最全面。", "bk": "正高", "ref": {"篇": "骨与骨关节", "章": "脊柱退行性病变", "节": "椎间盘及椎骨的退变过程", "页": 285}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07145", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1205a", "t": "共用题干题", "s": "结合上述情景，该患者应首先考虑的诊断是什么", "o": {"A": "主动脉瘤", "B": "主动脉夹层（Stanford A型）", "C": "急性心肌梗死", "D": "肺栓塞", "E": "心包积液"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-015", "kp": "主动脉夹层诊断", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】突发胸背部撕裂样痛＋血压极高＋CTA示升主动脉内膜片及真假双腔，符合Stanford A型主动脉夹层（累及升主动脉）。【为什么错】A：主动脉瘤为管腔均匀扩张，无内膜片。C：心肌梗死以冠脉病变为主。D：肺栓塞为肺动脉内栓子。E：心包积液为继发表现。", "tr": "Stanford A型累及升主动脉需急诊外科，B型（仅降主动脉）多药物或腔内治疗，分型决定治疗。", "bk": "正高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07134", "gs": ""}, {"id": "ZG-U07-1205b", "t": "共用题干题", "s": "结合上述情景，关于主动脉夹层影像学评估，下列表述正确的是", "o": {"A": "X线平片即可确诊主动脉夹层", "B": "CTA能同时显示内膜片、破口位置、真假腔及分支血管受累情况", "C": "超声可全程显示胸腹主动脉全程", "D": "MRI无需造影剂即可完全代替CTA评估", "E": "DSA已作为诊断夹层的首选检查"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-016", "kp": "主动脉夹层CTA评估价值", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTA无创、快速，可一站式显示内膜片、破口、真假腔、血栓及分支受累情况，是主动脉夹层诊断与术前评估的首选方法。【为什么错】A：平片仅见纵隔增宽等间接征象，不能确诊。C：超声对降主动脉及分支显示受限。D：MRI成像时间长、急症不适用，且有血流信号干扰。E：DSA为有创检查，主要用作介入治疗的引导，不是诊断首选。", "tr": "急诊夹层“CTA一站式评估”优于其他手段；DSA有创，用于介入操作导航。", "bk": "正高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07133", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1206a", "t": "单选题", "s": "【病例】患者女，35岁，右耳反复流脓伴听力下降10余年。颞骨CT示右侧上鼓室软组织团块影，盾板骨质破坏，锤、砧骨部分吸收，乳突气房混浊，面神经管水平段骨质尚完整。临床疑中耳胆脂瘤，拟行颞骨CT全面评估后择期手术。 该患者首先考虑的疾病诊断是", "o": {"A": "急性中耳炎", "B": "中耳胆脂瘤", "C": "听神经瘤", "D": "中耳血管球瘤", "E": "外耳道胆脂瘤"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-011", "kp": "中耳胆脂瘤诊断", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】慢性化脓性中耳炎史＋上鼓室软组织影伴盾板骨质破坏、听小骨吸收，是继发性中耳胆脂瘤的典型CT表现。【为什么错】A：急性中耳炎以黏膜增厚、积液为主，无骨质破坏。C：听神经瘤位于桥小脑角、内听道。D：血管球瘤增强明显强化伴搏动性耳鸣。E：外耳道胆脂瘤位于外耳道。", "tr": "“上鼓室软组织＋盾板破坏”是胆脂瘤诊断核心，骨质破坏是手术指征的影像依据。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1206b", "t": "共用题干题", "s": "结合上述情景，该患者疑中耳胆脂瘤并需与中耳炎性肉芽组织鉴别时，MR弥散加权成像（DWI）的典型表现是", "o": {"A": "DWI呈明显高信号（角化物弥散受限），增强无强化或仅边缘强化", "B": "DWI呈低信号，增强后明显均匀强化", "C": "DWI低信号，T2WI呈明显低信号", "D": "DWI高信号，T1WI呈明显高信号", "E": "DWI呈明显高信号且T1WI、T2WI均为低信号"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-012", "kp": "中耳胆脂瘤DWI表现", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】胆脂瘤为角化鳞状上皮及角化物堆积，细胞致密弥散受限，DWI呈明显高信号，增强无强化或边缘轻度强化，与肉芽组织（DWI低、明显强化）形成鉴别。【为什么错】B：均匀明显强化为肉芽组织、富血供病变特征。C：胆脂瘤T2WI呈高信号而非低信号。D：T1WI明显高信号多见于出血、脂肪。E：T2WI低信号不符胆脂瘤表现。", "tr": "“DWI高＋不强化”是胆脂瘤特征；“DWI低＋明显强化”指向肉芽组织，DWI是两者鉴别关键。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07131", "gs": ""}, {"id": "ZG-U07-1207a", "t": "共用题干题", "s": "结合上述情景，该患者的正确诊断是什么", "o": {"A": "子宫内膜癌", "B": "子宫肌瘤", "C": "卵巢囊肿", "D": "子宫腺肌症", "E": "宫颈癌"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-007", "kp": "子宫肌瘤MRI诊断", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】育龄女性月经量增多，MRI示子宫肌壁间多发T2WI低信号、边界清楚的肿块，符合典型子宫肌瘤表现。【为什么错】A：子宫内膜癌为内膜增厚肿块伴肌层浸润。C：卵巢囊肿位于附件区、水样信号。D：子宫腺肌症表现为结合带弥漫增厚、点状出血信号。E：宫颈癌位于宫颈。", "tr": "“T2WI低信号＋边界清楚”是肌瘤特征；腺肌症看结合带，二者均可使宫腔增大但信号分布不同。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07140", "gs": ""}, {"id": "ZG-U07-1207b", "t": "共用题干题", "s": "结合上述情景，该患者保守治疗无效，拟行子宫动脉栓塞术（UAE）治疗，术前最适宜的血管影像学检查是", "o": {"A": "腹部X线平片", "B": "盆腔CTA/MRA（子宫动脉成像）", "C": "静脉肾盂造影", "D": "膀胱造影", "E": "全身骨扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-008", "kp": "子宫肌瘤栓塞术前评估", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (2)CT诊断要点", "ex": "【为什么对】UAE术前需明确子宫动脉起源、走行、粗细及有无卵巢动脉供血等解剖信息，盆腔CTA或MRA可无创三维显示，指导栓塞策略。【为什么错】A：平片不能显示血管。C：静脉肾盂造影评估泌尿系统。D：膀胱造影显示膀胱。E：骨扫描用于骨转移。", "tr": "子宫动脉栓塞术前“CTA/MRA三维血管成像”是标准评估手段；术中再行选择性DSA确认。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07141", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1301", "t": "案例分析题", "s": "患者男，58岁，因突发右侧肢体无力伴言语不清2小时急诊入院，NIHSS评分12分。临床考虑急性缺血性脑卒中，急诊CT平扫未见明确异常，为早期确诊并评估缺血范围，临床申请急诊MRI检查。技师需在最短时间内完成对缺血病灶最敏感的序列扫描，同时兼顾患者躁动配合度及检查安全，必要时可加做灌注成像评估缺血半暗带。此时最应优先采用的扫描序列是", "o": {"A": "轴位T1WI、T2WI平扫", "B": "轴位DWI及ADC图", "C": "轴位SWI", "D": "单体素MRS", "E": "冠状位T1WI增强扫描"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-020", "kp": "急性脑梗死急诊MRI序列选择", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】超急性期脑梗死细胞毒性水肿使水分子弥散受限，DWI呈高信号、ADC值降低，发病2小时内即可检出，是急诊脑卒中MRI的核心序列，符合“时间就是大脑”的检查原则。【为什么错】A：T1WI、T2WI对超急性期梗死不敏感，易漏诊。C：SWI用于出血、钙化及静脉显示，非梗死首选。D：MRS为功能代谢序列，耗时长，不适合急诊。E：增强用于评估血脑屏障破坏，非早期梗死首选。", "tr": "DWI+ADC是急性卒中MRI金标准组合；“CT阴性＋DWI阳性”为超急性梗死的经典场景。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "脱髓鞘性脑白质病", "节": "急性播散性脑脊髓炎", "页": 46}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1302", "t": "共用题干题", "s": "结合上述情景，患者女，45岁，突发剧烈头痛、呕吐1天，脑膜刺激征阳性，临床高度怀疑蛛网膜下腔出血。发病后立即行头颅CT平扫未见明确蛛网膜下腔高密度影，考虑出血量少或CT敏感性随时间下降。为排除蛛网膜下腔出血并评估微小动脉瘤，拟行头颅MRI补充检查，技师需选择对血液及出血最敏感、又能兼顾微小动脉瘤显示的序列组合，并做好患者制动与监护。此时应优先采用的MRI序列组合是", "o": {"A": "FLAIR及SWI序列", "B": "常规T1WI、T2WI序列", "C": "单次轴位DWI", "D": "头颅MRS", "E": "磁化传递成像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-BRAIN-021", "kp": "蛛网膜下腔出血MRI序列", "ch": "七、影像诊断学基础 → 1.颅脑中枢神经系统 → (3)MR诊断要点", "ex": "【为什么对】FLAIR对蛛网膜下腔少量出血敏感（脑脊液信号抑制后出血呈高信号），SWI能显示微量出血及含铁血黄素沉积，两者组合可提高CT阴性蛛网膜下腔出血的检出率。【为什么错】B：常规T1WI、T2WI对蛛网膜下腔少量血液显示不佳。C：DWI用于梗死、脓肿等，非出血检出序列。D：MRS为代谢分析，非首选。E：磁化传递成像用于提高组织对比，不用于出血。", "tr": "“CT阴性蛛网膜下腔出血”复查首选FLAIR＋SWI；动脉瘤确认需CTA或DSA。", "bk": "正高", "ref": {"篇": "中枢神经系统", "章": "颅内囊性病变", "节": "蛛网膜囊肿", "页": 80}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07159", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1303", "t": "案例分析题", "s": "患者女，42岁，体检超声发现甲状腺左叶约1.5 cm低回声结节，内见微小钙化，边界欠清，临床疑甲状腺乳头状癌，拟行颈部CT增强扫描，以明确结节范围及其与气管、食管、颈动脉鞘的关系并评估淋巴结。技师准备检查时需重点考虑扫描时相、患者配合及对比剂注射方案，以减少吞咽运动伪影并确保结节与血管强化充分。此时最合适的扫描方案是", "o": {"A": "嘱患者平静呼吸、避免吞咽，采用颈部容积扫描并行动脉期增强", "B": "大螺距单次扫描，不注射对比剂", "C": "口服空气对比剂后平扫", "D": "仅做静脉期延迟5分钟扫描", "E": "透视下连续曝光采集"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-013", "kp": "颈部CT增强扫描方案", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (2)CT诊断要点", "ex": "【为什么对】颈部扫描须避免吞咽动作以防运动伪影，动脉期增强可清晰显示富血供甲状腺病变及颈部血管，容积薄层扫描利于多平面重组。【为什么错】B：大螺距快速扫描虽快但未增强，无法显示病变强化特征及血管关系。C：空气对比剂用于胃肠道，颈部不适用。D：静脉期延迟过长，动脉期已过，不利于富血供病变评估。E：透视连续曝光辐射量大且无诊断性增强图像。", "tr": "“颈部扫描防吞咽＋动脉期增强”是甲状腺及颈部病变检查要点，增强时相直接影响诊断。", "bk": "正高", "ref": {"篇": "基础概念（绪论）", "章": "基本概念（X线物理/对比剂/成像基础）", "节": "CT 增强扫描", "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1304", "t": "案例分析题", "s": "患者男，50岁，鼻咽癌根治性放疗后1年，常规复查鼻咽部MRI。临床需评估有无肿瘤残留或复发，并与放疗后纤维化、瘢痕鉴别，同时观察颅底骨质及颈部淋巴结情况。技师在制定扫描方案时，应结合增强扫描与功能成像序列，选择对复发与纤维化鉴别最有价值的序列组合，并注意对比剂剂量与延迟扫描时相的规范。此时最应采用的序列组合是", "o": {"A": "增强T1WI脂肪抑制及DWI序列", "B": "仅平扫T1WI", "C": "仅轴位T2WI", "D": "SWI序列", "E": "磁化传递成像单序列"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ENT-014", "kp": "鼻咽癌放疗后随访MRI", "ch": "七、影像诊断学基础 → 2.五官与颈部 → (3)MR诊断要点", "ex": "【为什么对】复发肿瘤富含细胞、血供丰富，增强T1WI脂肪抑制明显强化，DWI呈高信号、ADC值降低；而纤维化无强化或延迟轻度强化，DWI低信号、ADC值升高，二者联合是复发与纤维化鉴别的关键。【为什么错】B：平扫T1WI不能反映血供。C：T2WI对鉴别无特异性。D：SWI显示出血钙化，不用于复发鉴别。E：磁化传递成像辅助性，无法独立鉴别。", "tr": "“复发＝强化＋DWI高＋ADC低”“纤维化＝无强化＋DWI低＋ADC高”，ADC值量化是鉴别关键。", "bk": "正高", "ref": {"篇": "头颈部", "章": "咽喉部病变", "节": "鼻咽部病变", "页": 103}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1305", "t": "共用题干题", "s": "结合上述情景，患者男，62岁，股骨颈骨折卧床3天后突发呼吸困难、胸痛、咯血，血氧饱和度下降，D-二聚体明显升高，临床高度怀疑急性肺动脉栓塞，拟行CT肺动脉成像（CTPA）。技师需设置合适的对比剂注射方案与扫描触发方式，确保肺动脉显影充分、避免上腔静脉高浓度对比剂伪影干扰肺动脉评价，并兼顾右心室功能评估。此时最合理的扫描技术方案是", "o": {"A": "对比剂团注后自动触发，于肺动脉期采集，必要时辅以心电门控评估右心功能", "B": "对比剂注射后立即扫描（上腔静脉期）", "C": "不注射对比剂的低剂量平扫", "D": "延迟10分钟后延迟扫描", "E": "只做胸部X线正位片替代"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-017", "kp": "CTPA扫描技术方案", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CTPA通过自动触发（感兴趣区置于肺动脉干）在对比剂达峰时采集肺动脉期，可清晰显示肺动脉内血栓；心电门控或心电编辑可评估右心室增大（RV/LV比值），是急性肺栓塞一站式评估的核心技术。【为什么错】B：立即扫描时对比剂尚在上腔静脉，产生喷射伪影掩盖肺动脉。C：平扫不能显示血管内充盈缺损。D：延迟扫描时对比剂已稀释廓清。E：X线胸片仅能显示间接征象，不能确诊。", "tr": "CTPA“自动触发＋肺动脉期采集”避免上腔静脉伪影；肺栓塞确诊看充盈缺损而非平扫。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07128", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1306", "t": "共用题干题", "s": "结合上述情景，患者男，60岁，突发胸背部撕裂样剧痛，血压200/110 mmHg，临床疑主动脉夹层，急诊行胸腹主动脉CTA检查。原始轴位图像显示降主动脉内膜片及真假双腔，假腔部分血栓形成。技师需利用后处理技术全面评估夹层累及范围、内膜破口位置及分支血管受累情况，为临床制定急诊手术治疗方案提供可靠依据。此时最合适的图像后处理方法是", "o": {"A": "沿主动脉走行做曲面重组（CPR）并配合多平面重组（MPR）观察内膜片及破口", "B": "仅保留原始轴位图像", "C": "容积再现（VR）仅显示主动脉外表面", "D": "最大密度投影（MIP）去骨显示血管钙化", "E": "仿真内镜观察主动脉腔内表面"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-018", "kp": "主动脉夹层CTA后处理", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CPR沿血管中心线展开可全程显示主动脉内膜片、真假腔、破口及分支受累；结合MPR冠状矢状位重组能准确定位破口与判断Stanford分型，是夹层后处理的核心。【为什么错】B：单看轴位难以整体评估夹层延伸范围。C：VR只显示血管外形，无法观察腔内内膜片。D：MIP去骨主要用于血管钙化与管腔显示，对内膜片显示不佳。E：仿真内镜用于观察腔内结构，对破口及分支评估价值有限。", "tr": "夹层后处理“CPR＋MPR”是黄金组合，VR看外形、MIP看钙化，各有所用。", "bk": "正高", "ref": {"篇": "胸部", "章": "心脏与大血管", "节": "主动脉夹层", "页": 165}, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ07132", "gs": ""}, {"id": "ZG-U07-1307", "t": "案例分析题", "s": "患者女，58岁，呼吸困难1个月，X线胸片示右侧大量胸腔积液，超声定位后临床拟行CT引导下胸腔穿刺引流术。患者神志清楚、生命体征平稳，可配合扫描与穿刺操作。技师需配合临床确定穿刺层面与进针路径，选择合适扫描条件与重建方式，既保证定位准确又尽量降低辐射剂量，并做好穿刺后复查确认引流管位置。此时最合理的操作流程是", "o": {"A": "CT定位扫描选定液性暗区最大层面，设计避开肺组织的进针路径，穿刺后复查扫描确认引流管位置", "B": "盲目按体表标记穿刺，不做CT确认", "C": "不定位直接行立位透视穿刺", "D": "采用俯卧位强行穿刺", "E": "仅凭X线正位片确定穿刺点"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-CHEST-019", "kp": "CT引导下胸腔穿刺定位", "ch": "七、影像诊断学基础 → 3.胸部与心脏 → (2)CT诊断要点", "ex": "【为什么对】CT引导穿刺先定位扫描确定积液最大层面及安全进针路径（避开肺组织、膈肌及大血管），穿刺后即刻复查确认引流管位置，可显著提高成功率、降低气胸等并发症。【为什么错】B：盲目穿刺风险高，易损伤肺组织。C：透视仅能观察骨骼及气体，对积液定位不佳。D：俯卧位不适用于所有病例，需根据积液位置选择体位。E：X线正位片无横断定位信息。", "tr": "CT引导穿刺“定位→设计路径→穿刺→复查确认”四步流程，安全性与准确性并重。", "bk": "正高", "ref": {"篇": "胸部", "章": "胸膜疾病", "节": "胸腔积液", "页": 140}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1308", "t": "共用题干题", "s": "结合上述情景，患者女，50岁，体检超声发现肝右叶约3 cm稍强回声结节，临床拟诊肝海绵状血管瘤，需行MRI进一步确诊。技师制定肝脏MRI动态增强扫描方案时，需考虑多期增强扫描的时相设置、重T2加权序列的应用及脂肪抑制技术，以获得血管瘤“早出晚归”的典型信号特征，并与肝细胞癌、转移瘤等富血供病变鉴别。此时最合适的扫描方案是", "o": {"A": "重T2加权（长TE）T2WI＋多期动态增强（动脉期、门脉期、延迟期）", "B": "仅做平扫T1WI", "C": "仅做T2WI平扫", "D": "单期门脉期增强扫描", "E": "MR胰胆管成像（MRCP）替代"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-014", "kp": "肝血管瘤MRI扫描方案", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】重T2加权序列T2WI呈显著高信号（灯泡征），多期动态增强显示周边结节状强化、向心性充填及延迟期持续强化（早出晚归），是确诊血管瘤的核心方案。【为什么错】B：T1WI平扫对富血供病变鉴别价值有限。C：单T2WI无法显示动态强化特征。D：单期增强无法观察充填过程及延迟强化。E：MRCP用于胆道系统，不用于肝内占位定性。", "tr": "“重T2WI＋多期动态增强＋延迟期”是血管瘤确诊的完整方案，延迟期是关键。", "bk": "正高", "ref": {"篇": "腹部", "章": "肝脏良性肿瘤", "节": "肝血管瘤", "页": 170}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07153", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1309", "t": "案例分析题", "s": "患者男，65岁，进行性无痛性黄疸1个月，皮肤巩膜黄染，实验室检查示胆红素及CA19-9升高，临床疑胰头占位致胆道梗阻，拟行上腹部MRI检查。技师需合理组合平扫、MR胰胆管成像（MRCP）及动态增强扫描序列，清晰显示胰头肿块、胆胰管扩张情况及肿瘤与周围血管的关系，为外科手术可行性评估提供影像依据。此时最合适的扫描方案是", "o": {"A": "冠状位及轴位T2WI＋MRCP＋动态增强扫描", "B": "仅轴位T1WI平扫", "C": "仅做SWI序列", "D": "仅做轴位DWI单序列", "E": "口服钡剂后X线钡餐检查"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-ABDO-015", "kp": "胰头占位MRI扫描方案", "ch": "七、影像诊断学基础 → 4.腹部 → (3)MR诊断要点", "ex": "【为什么对】MRCP可无创显示胆胰管扩张与梗阻断端，T2WI及动态增强显示胰头肿块及强化特征，结合血管成像评估肿瘤与周围血管关系，是胰腺占位术前评估的一站式方案。【为什么错】B：T1WI平扫信息有限。C：SWI不用于胰腺占位评估。D：单DWI无法显示解剖及胆胰管。E：钡餐不能显示胰腺及胆道。", "tr": "“MRCP看胆胰管＋动态增强看肿块血供＋MRA看血管关系”是胰头癌术前评估三要素。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1310", "t": "共用题干题", "s": "结合上述情景，患者女，52岁，绝经后阴道不规则出血，诊断性刮宫病理示子宫内膜样腺癌，临床拟行MRI术前分期，重点评估肿瘤肌层浸润深度、有无宫颈间质受累及盆腔淋巴结转移。患者体型偏瘦，能耐受较长扫描时间，无需镇静。技师需选择高分辨扫描序列与体位，结合动态增强及弥散加权成像，为FIGO分期提供准确依据。此时最合适的扫描方案是", "o": {"A": "矢状位高分辨T2WI＋动态增强＋DWI", "B": "仅轴位T1WI", "C": "仅冠状位STIR", "D": "仅SWI序列", "E": "仅头颅MRA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-009", "kp": "子宫内膜癌MRI分期方案", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (3)MR诊断要点", "ex": "【为什么对】矢状位T2WI清晰显示宫腔肿瘤与肌层界面，动态增强显示内膜下强化带完整性，DWI及ADC值辅助判断深肌层浸润，三者联合是子宫内膜癌分期的标准方案。【为什么错】B：轴位T1WI不能显示肌层浸润层次。C：STIR用于脂肪抑制及骨髓，非分期核心。D：SWI用于出血钙化。E：MRA用于血管，与子宫内膜癌分期无关。", "tr": "“矢状位＋动态增强＋DWI”是子宫内膜癌MRI分期三件套，深肌层浸润≥1/2为高危。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "子宫内膜癌", "页": 247}, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07139", "gs": ""}, {"id": "ZG-U07-1311", "t": "案例分析题", "s": "患者女，42岁，多发性子宫肌瘤致月经量增多、贫血，药物治疗无效，临床拟行子宫动脉栓塞术（UAE）。术前需行盆腔血管影像学评估，明确子宫动脉解剖、血供来源及卵巢动脉有无参与供血，以规划导管入路与栓塞方案。患者无碘对比剂过敏史，肾功能正常，未生育且保留子宫意愿强烈，希望在充分评估后实施微创治疗。此时进行血管评估的最适宜方法是", "o": {"A": "盆腔CTA或MRA三维血管成像，必要时术中选择性子宫动脉DSA", "B": "下肢静脉造影", "C": "经皮肝穿刺门静脉造影", "D": "淋巴管造影", "E": "膀胱造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-PELV-010", "kp": "子宫动脉栓塞术前血管评估", "ch": "七、影像诊断学基础 → 5.盆腔生殖 → (2)CT诊断要点", "ex": "【为什么对】UAE术前经CTA/MRA无创三维显示子宫动脉起源、走行及有无卵巢动脉供血，术中再以选择性子宫动脉DSA确认并栓塞，是最规范的评估路径。【为什么错】B：下肢静脉造影用于静脉病变。C：门静脉造影用于门脉高压。D：淋巴造影用于淋巴系统。E：膀胱造影显示膀胱形态。", "tr": "“术前CTA/MRA＋术中DSA”是子宫动脉栓塞的标准路径，卵巢动脉供血是栓塞失败原因之一。", "bk": "正高", "ref": {"篇": "腹部", "章": "盆腔", "节": "卵巢子宫内膜异位症", "页": 244}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1312", "t": "案例分析题", "s": "患者男，17岁，右膝关节肿胀、疼痛2个月，局部皮温升高。X线示股骨远端干骺端溶骨性破坏伴日光放射状骨膜反应及Codman三角，临床拟诊骨肉瘤，需行MRI明确肿瘤髓内浸润范围、跳跃灶及软组织肿块边界，并行胸部CT筛查肺转移，为保肢手术方案提供依据。患者一般情况尚好，无发热，可配合完成各项检查。此时最合理的影像检查方案是", "o": {"A": "膝关节MRI平扫及增强（含T1WI、T2WI脂肪抑制）评估肿瘤范围，加胸部CT筛查肺转移", "B": "仅复查X线平片", "C": "仅做超声检查", "D": "仅做膝关节CT平扫", "E": "仅做全身PET-CT替代所有检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-012", "kp": "骨肉瘤分期影像方案", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】MRI冠状矢状位T1WI、T2WI脂肪抑制及增强可准确显示肿瘤髓内浸润范围、关节及骨骺受累和软组织肿块边界，是保肢手术规划的关键；胸部CT是肺转移筛查标准方法。【为什么错】B：X线不能评估髓内范围。C：超声对骨内病变显示差。D：CT软组织对比不如MRI，髓内范围评估受限。E：PET-CT对微小肺转移检出有限，不能完全替代MRI局部评估。", "tr": "“MRI定范围、胸部CT定肺转移”是骨肉瘤局部与全身分期的基础方案，跳跃灶务必观察。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U07-1313", "t": "共用题干题", "s": "结合上述情景，患者男，40岁，因肾病综合征长期口服糖皮质激素，近2个月出现双侧髋部疼痛、活动受限，临床疑早期股骨头缺血坏死，申请髋关节MRI检查。患者无外伤史，髋部X线平片未见明确异常。技师需选择对骨髓水肿及早期坏死最敏感的序列，注意双侧对称扫描及脂肪抑制技术的应用，以提高早期病变检出率并明确坏死范围与分期。此时最合适的扫描方案是", "o": {"A": "双侧髋关节冠状位T1WI、T2WI及脂肪抑制（STIR）序列", "B": "仅做单侧髋关节X线平片", "C": "仅做双侧髋关节超声", "D": "仅做双侧髋关节CT平扫", "E": "仅做腰椎MRI"}, "d": "易", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-SPINE-013", "kp": "股骨头坏死MRI方案", "ch": "七、影像诊断学基础 → 6.脊柱与四肢关节 → (3)MR诊断要点", "ex": "【为什么对】MRI对早期股骨头缺血坏死最敏感，可显示“双线征”（T2WI上坏死区与活骨间低信号线内侧高信号带）及骨髓水肿，双侧对称扫描便于对比，STIR提高病变检出。【为什么错】B：X线早期可阴性，出现硬化、塌陷已属晚期。C：超声无法穿透骨皮质显示骨髓。D：CT对早期骨髓水肿及线样征显示不如MRI。E：腰椎MRI与髋部病变无关。", "tr": "“激素史＋双髋痛”高度提示股骨头坏死，MRI双线征是其特异表现，早于X线数月。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0, "gid": "GZ07154", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1314", "t": "共用题干题", "s": "结合上述情景，患者男，68岁，反复头晕、一过性黑矇，超声提示左侧颈内动脉起始部重度狭窄（约75%），临床拟行颈动脉三维CTA评估狭窄程度并制定治疗方案。患者心率平稳、能配合屏气，血肌酐正常，可行增强检查。技师需设置合适的扫描范围与增强参数，保证颈动脉管腔内对比剂充盈良好、避免静脉重叠，并利用后处理技术准确测量狭窄率。此时最合适的CTA技术要点是", "o": {"A": "扫描范围自主动脉弓至Willis环，团注触发动脉期采集，结合MPR及血管分析软件按NASCET法测量狭窄率", "B": "扫描范围仅限颈部软组织", "C": "静脉期延迟采集", "D": "不使用对比剂直接扫描", "E": "仅轴位观察不做后处理测量"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-007", "kp": "颈动脉CTA技术方案", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】颈动脉CTA扫描范围覆盖主动脉弓至Willis环，团注触发动脉期可避免静脉污染，MPR及专用血管分析软件按NASCET法（以远端正常管径为参考）测量狭窄率，为手术或介入提供依据。【为什么错】B：范围不足会遗漏锁骨下及颅内段。C：静脉期血管对比差、静脉重叠。D：平扫不能显示管腔。E：不测量无法量化狭窄程度。", "tr": "NASCET法狭窄率＝(1－最窄处管径/远端正常管径)×100%；CTA测量与DSA有良好一致性。", "bk": "正高", "ref": null, "hf": true, "src": "正高拓展", "mk": 0, "gid": "GZ07161", "gs": "患者影像所见如下，关于诊断学基础要点正确的是。"}, {"id": "ZG-U07-1315", "t": "案例分析题", "s": "患者男，70岁，左下肢发凉、间歇性跛行2年，近期出现静息痛，超声示左侧股浅动脉长段闭塞，临床拟行下肢动脉DSA检查并行血管成形术。患者股动脉搏动良好，可作为穿刺入路考虑。技师需根据病变位置选择穿刺入路、造影体位与成像方式，合理控制对比剂总量以清晰显示闭塞段及侧支循环，为介入治疗提供实时导航。此时最合理的DSA技术方案是", "o": {"A": "对侧股动脉逆行穿刺入路，多体位DSA采集并配合路图技术引导球囊扩张与支架置入", "B": "直接穿刺闭塞段血管远端", "C": "仅做单一体位正位采集", "D": "不用对比剂直接试扩张", "E": "全身血管一次性造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "七", "un": "影像诊断学基础", "kpid": "UNIT-07-VASC-008", "kp": "下肢动脉DSA介入方案", "ch": "七、影像诊断学基础 → 7.外周血管与外周神经 → (2)CT诊断要点", "ex": "【为什么对】股浅动脉长段闭塞常采用对侧股动脉逆行穿刺，通过翻山进入患侧，多体位DSA显示闭塞段与侧支循环，路图（roadmap）技术实时引导导丝、球囊及支架操作。【为什么错】B：直接穿刺闭塞段远端有穿出及血肿风险。C：单一体位不能全面显示病变。D：无造影定位盲目扩张风险高。E：一次性全身造影对比剂超量且无针对性。", "tr": "“对侧入路＋多体位＋路图”是下肢动脉闭塞介入的标准组合，DSA同时是诊断与治疗工具。", "bk": "正高", "ref": null, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0101", "t": "多选题", "s": "关于普通X线摄影中滤线栅的使用指征与性能参数，下列说法正确的是", "o": {"A": "被照体厚度超过10cm或管电压超过60kV时，散射线明显增加，应加用滤线栅", "B": "栅比等于铅条高度与铅条间距之比，栅比越大清除散射线能力越强，但曝光量与对位精度要求随之提高", "C": "栅密度指单位长度内的铅条数，栅密度越高铅条投影越细密，越不易在影像上被察觉", "D": "手、足、腕等薄部位摄影一般不用滤线栅，以免徒增受检者剂量", "E": "使用聚焦栅时，中心线可在垂直于铅条排列的方向上任意侧向偏移而不产生栅切割"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-POS-001", "kp": "滤线栅使用指征与栅比栅密度", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】A正确：体厚大于10cm、管电压高于60kV是教材公认的两条加栅指征，前者因散射体积大，后者因康普顿效应占比升高。B正确：栅比R=h/D，栅比越大对斜射散射线吸收越彻底，图像对比度改善越明显，但原发线损失增多需提高曝光量（栅因子增大），容许的中心线偏移范围也变窄。C正确：栅密度N为每厘米铅条数，密度越高铅条影越细，越不易形成栅线干扰。D正确：薄部位散射线本就少，加栅只增加剂量而无对比度收益。【为什么错】E错误：聚焦栅只允许中心线沿铅条长轴方向倾斜，若在垂直于铅条排列的方向侧向偏移、倾斜，或反置、超出栅焦距范围，均会发生栅切割，表现为影像单侧或两侧密度明显降低。", "tr": "栅比与栅密度是两个独立参数：栅比决定清除散射线能力与曝光量代价，栅密度只决定铅条影是否可见，二者常被混为一谈。“中心线可任意倾斜”是聚焦栅最典型的错误说法。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0102", "t": "多选题", "s": "下列常规X线摄影中焦点-探测器距离（SID）的选择，符合常规要求的是", "o": {"A": "心脏后前位远达片采用180~200cm", "B": "腹部仰卧前后位采用100cm", "C": "颈椎侧位采用150cm", "D": "乳腺头尾位采用100cm", "E": "口内根尖片平行投照（长遮线筒法）采用20~40cm"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-POS-002", "kp": "各部位摄影距离的选择", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】A正确：心脏远达片需最大限度减小心影几何放大，故用180~200cm。B正确：腹部、脊柱、四肢等常规摄影SID为100cm。C正确：颈椎侧位受肩部阻挡、颈椎距探测器较远（物-片距大），须加大SID至150cm以抵消放大。E正确：口内根尖片平行投照法配长遮线筒，焦-片距约20~40cm，使X线接近平行入射以减小失真。【为什么错】D错误：乳腺X线机为固定短距离设计，SID约60~65cm，而非100cm；乳腺摄影靠压迫缩小物-片距来控制放大，并不依赖长SID。", "tr": "SID并非越长越好：长SID减小放大与半影，但曝光量按平方反比大幅上升。颈椎侧位150cm、心脏远达片180~200cm、乳腺约65cm是三个最易记混的“非100cm”特例。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0103", "t": "单选题", "s": "某部位摄影时焦点至探测器距离为100cm，被照体中心至探测器距离为20cm，X线管有效焦点尺寸为1.0mm，该部位影像的放大率与半影宽度分别约为", "o": {"A": "1.25、0.25mm", "B": "1.20、0.20mm", "C": "1.25、0.20mm", "D": "0.80、0.25mm", "E": "1.20、0.25mm"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-POS-003", "kp": "影像放大率与半影的计算", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】焦-物距SOD=SID-OID=100-20=80cm。放大率M=SID/SOD=100/80=1.25；半影（模糊）宽度H=F×OID/SOD=1.0×20/80=0.25mm。故选A。【为什么错】B、E中的放大率1.20系把分母错取为SID（1+20/100）所致。C中的半影0.20mm系误用H=F×OID/SID、分母错取SID。D把放大率取成倒数SOD/SID=0.80，方向颠倒——只要物体不贴探测器，放大率恒大于1。", "tr": "放大率与半影公式的分母都是SOD（焦-物距）而非SID。减小放大与模糊的三条途径中，缩小物-片距（部位尽量贴近探测器）最经济有效，其次是加大SID与选用小焦点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0104", "t": "多选题", "s": "为在普通X线摄影中落实放射防护最优化原则，下列做法正确的是", "o": {"A": "用准直器把照射野严格限制在临床需要范围内，是最基本且最有效的防护措施之一", "B": "对儿童及育龄期受检者，在不遮挡诊断信息的前提下对性腺等辐射敏感器官施行屏蔽防护", "C": "保证足够的总滤过以滤除对成像无贡献的低能光子，降低受检者皮肤剂量", "D": "在保证影像质量的前提下适当提高管电压、相应降低mAs，有利于降低受检者剂量", "E": "陪检人员只要站在机房内距球管3m以外，即可不穿戴铅防护用品"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-POS-004", "kp": "X线摄影的防护措施", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】A正确：缩小照射野既减少受照体积和有效剂量，又减少散射线来源、改善对比度，是性价比最高的防护手段。B正确：屏蔽防护针对性腺、甲状腺、眼晶状体等敏感器官，前提是不遮盖诊断兴趣区。C正确：低能光子几乎全部被体表吸收而不到达探测器，增加总滤过可硬化线质、显著降低皮肤入射剂量。D正确：高千伏-低毫安秒组合能在维持透过量的同时降低吸收剂量，是低剂量摄影的基本策略。【为什么错】E错误：机房内散射线不能仅靠距离忽略，凡需留在机房内扶持患者者都应穿戴铅衣、铅围裙并避开原发射线方向，以“距离3m”替代屏蔽不符合防护要求。", "tr": "时间、距离、屏蔽三原则须联合使用，不能以其中之一替代其余。另注意提高kV降剂量是有条件的，过高kV会牺牲影像对比度。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0105", "t": "单选题", "s": "行颅骨前后半轴位（汤氏位）摄影，若听眦线垂直于探测器，中心线的正确投照方式是", "o": {"A": "向头侧倾斜30°，经眉间射入", "B": "向足侧倾斜30°，自前额发际上方射入，经枕骨大孔中心射出", "C": "向足侧倾斜45°，对准被检侧外耳孔射出", "D": "垂直射入，经枕外隆凸射入、眉间射出", "E": "向足侧倾斜23°，经鼻根部射出"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-001", "kp": "颅骨前后半轴位（汤氏位）", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位取仰卧或坐位，正中矢状面垂直于探测器并对准中线；听眦线垂直于探测器时，中心线向足侧倾斜30°，自前额发际上方射入、经枕骨大孔中心射出。标准影像判据是鞍背与后床突恰投影于枕骨大孔阴影之内，两侧岩骨、内耳道及枕骨对称显示。若改以听眉线垂直于探测器，则中心线需向足侧倾斜37°。【为什么错】A方向相反，向头侧倾斜无法把枕骨与岩骨从面颅重叠中分离。C是梅氏位（颞骨岩部轴位）的参数——头转向被检侧45°、中心线向足侧45°。E是柯氏位的参数——向足侧23°经鼻根射出。D为头颅后前位的中心线方向，不带角度，不能显示枕骨大孔与鞍背。", "tr": "汤氏位角度随基准线变化：听眦线垂直→30°，听眉线垂直→37°。判断合格与否不看“枕骨是否清楚”，而看鞍背与后床突是否恰落在枕骨大孔影内——角度过小投影在孔上方，过大则落于孔下方。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0106", "t": "单选题", "s": "瓦氏位（Waters位，顶颏位）摄影时，听眦线与探测器平面所成的角度约为", "o": {"A": "15°", "B": "23°", "C": "30°", "D": "37°", "E": "53°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-002", "kp": "瓦氏位的基准线角度", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】瓦氏位取俯卧或坐位面向探测器，颏部紧贴探测器、鼻尖离开探测器约1.5cm，使听眦线与探测器平面成37°（此时听鼻线接近垂直），中心线垂直经上唇中点（鼻棘）射出。该角度使岩骨嵴下移到上颌窦底以下，上颌窦、眼眶、颧弓、鼻腔得以完整无重叠显示，是观察上颌窦积液与面中部骨折的标准体位。【为什么错】A为劳氏位的头部旋转与中心线倾斜角度。B为柯氏位中心线向足侧的倾斜角。C为汤氏位在听眦线垂直时的中心线倾斜角。E为视神经孔位（瑞氏位）正中矢状面与探测器所成的角度。", "tr": "头颅特殊位角度需成组记忆：柯氏23°、汤氏30°（听眉线时37°）、瓦氏37°、视神经孔位53°、许氏25°、劳氏15°、梅氏45°、斯氏向头侧12°。注意瓦氏位的37°是基准线与台面的夹角，而非中心线倾角——瓦氏位中心线是垂直投照的。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0107", "t": "单选题", "s": "柯氏位（Caldwell位，鼻额位）摄影时中心线向足侧倾斜约23°，其主要目的是", "o": {"A": "使岩骨嵴下移至眶下缘附近，避免其与额窦、前组筛窦及眶内结构重叠", "B": "使蝶鞍呈切线位、前后床突重合显示", "C": "使颧弓从颅骨重叠中投影出来呈弓状显示", "D": "使枕骨大孔展开并在孔内显示鞍背与后床突", "E": "使视神经孔投影于眼眶的外下象限"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-003", "kp": "柯氏位的角度作用与显示结构", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】柯氏位取俯卧、鼻额部紧贴探测器，听眦线垂直于探测器，中心线向足侧倾斜约23°经鼻根部射出。若不加角度（即标准头颅后前位），岩骨嵴恰投影在眼眶之内，遮盖眶底与前组筛窦；向足侧倾斜后岩骨嵴下移至眶下缘水平或其下，从而清晰显示额窦、前组筛窦、眶上裂与眼眶轮廓。【为什么错】B是头颅侧位的显示要求。C需颧弓切线位或颅底颏顶位才能实现。D是汤氏位的标准影像判据。E需视神经孔位（瑞氏位）——正中矢状面与探测器成53°、三点接触摆位方能达到。", "tr": "把握“角度决定岩骨嵴高低”这条主线：后前位0°时岩骨嵴位于眼眶内，柯氏位向足侧倾斜后降至眶下缘，瓦氏位头后仰37°后进一步降至上颌窦底以下。三者本质都是把岩骨这块高密度“挡板”移开。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0108", "t": "多选题", "s": "关于颞骨乳突及岩部常用摄影体位的角度与显示结构，下列描述正确的是", "o": {"A": "许氏位（Schüller位）中心线向足侧倾斜25°，自对侧外耳孔上方射入、对准被检侧外耳孔，主要显示乳突小房、鼓窦及乙状窦沟", "B": "劳氏位（Law位）头部正中矢状面与探测器约成15°、中心线向足侧倾斜15°，属乳突侧斜位", "C": "梅氏位（Mayer位）头转向被检侧约45°、中心线向足侧倾斜45°，重点显示鼓室、鼓窦入口与外耳道", "D": "斯氏位（Stenvers位）中心线向足侧倾斜45°，主要显示乳突尖及乳突小房", "E": "乳突摄影只需拍摄患侧，无须做双侧对比"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-004", "kp": "乳突及颞骨岩部摄影体位鉴别", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A正确：许氏位为乳突侧位，25°足侧倾斜使被检侧乳突从对侧乳突重叠中分离，是评价乳突气化程度、慢性中耳乳突炎及乙状窦位置的常规体位。B正确：劳氏位为乳突侧斜位，头部与中心线均取15°（“双15°”），显示范围与许氏位相近但气房展开方式不同。C正确：梅氏位为颞骨岩部轴位，头转45°、中心线向足侧45°，重点显示鼓室、鼓窦入口与外耳道。【为什么错】D错误：斯氏位为岩部后前斜位，头部正中矢状面与探测器成45°，中心线是向头侧倾斜约12°，显示的是岩骨全长、内耳道、耳蜗与半规管，而非乳突尖；把方向和角度都记反是常见失分点。E错误：乳突病变的判断高度依赖双侧对称对比（气化程度、密度、气房间隔），故乳突摄影原则上应双侧分别按相同条件摄影以供比较。", "tr": "许氏、劳氏、梅氏三个体位主要看乳突气房与鼓窦，斯氏位主要看内耳道与迷路；只有斯氏位的中心线向头侧倾斜，其余均向足侧倾斜，这是快速排除干扰项的抓手。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0109", "t": "案例分析题", "s": "患者女性，42岁，因“右眼视力进行性下降3个月”就诊，眼科怀疑右侧视神经管骨性狭窄，临床申请双侧视神经孔X线摄影以作初步筛查与左右对比。科室仅有普通DR设备，患者神志清楚、颈部活动无受限，能够配合俯卧位。作为投照技师，下列关于视神经孔位（Rhese位/瑞氏位）的摆位与投照，正确的是", "o": {"A": "俯卧，被检侧眼眶靠近探测器，使颧骨、鼻部、下颌部三点紧贴台面，正中矢状面与探测器成53°，听鼻线垂直于探测器，中心线经被检侧眶中心垂直射入", "B": "仰卧，头部后仰使听眦线与台面平行，中心线经两下颌角连线中点垂直射入", "C": "俯卧，正中矢状面垂直于探测器，中心线向足侧倾斜23°经鼻根射出", "D": "侧卧，被检侧靠近探测器，中心线向足侧倾斜25°对准外耳孔", "E": "仰卧，听眦线垂直于探测器，中心线向足侧倾斜30°经枕骨大孔射出"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-005", "kp": "视神经孔位（瑞氏位）摆位要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】视神经孔位的核心是让视神经管长轴与中心线方向一致，从而使视神经孔以“正圆形环状影”投影在被检侧眼眶的外下象限。标准做法为俯卧、被检侧靠近探测器，颧骨、鼻尖、下颌构成三点接触，正中矢状面与探测器成53°、听鼻线垂直于探测器，中心线经被检侧眶中心垂直射入。因需左右比较，应用同一条件分别摄取两侧。【为什么错】B为颅底颏顶位摆位，用于观察颅底孔道与颧弓，不能显示视神经孔。C为柯氏位，虽可显示眼眶轮廓但视神经孔与眶壁重叠。D为许氏位，属乳突侧位。E为汤氏位，显示枕骨与岩骨。", "tr": "视神经孔应显示在眼眶“外下象限”，若投影在眶内其他象限说明头部旋转角或基准线不到位。此外双侧必须分别摄影并用相同条件，否则密度差会干扰对孔径大小的对比判断。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0110", "t": "单选题", "s": "颅底颏顶位（颅底位）摄影的标准摆位与中心线要求是", "o": {"A": "仰卧或坐位，头部尽量后仰使听眦线尽可能与探测器平行，头顶部接触探测器，中心线经两侧下颌角连线中点垂直射入探测器", "B": "俯卧，颏部紧贴探测器，中心线向头侧倾斜37°", "C": "仰卧，听眶线垂直于探测器，中心线向足侧倾斜45°经鼻根射入", "D": "侧卧，正中矢状面平行于探测器，中心线经蝶鞍垂直射入", "E": "俯卧，前额鼻部贴板，中心线向足侧倾斜23°经眉间射出"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-006", "kp": "颅底颏顶位摆位与显示结构", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】颅底颏顶位要求头部极度后仰，使听眦线尽量与探测器平行（即颅底平面与探测器平行），头顶接触探测器，中心线经两下颌角连线中点垂直射入。标准影像可显示卵圆孔、棘孔、破裂孔等颅底孔道，以及蝶窦、筛窦、颧弓、下颌骨升支与枕骨大孔，两侧结构对称。【为什么错】B为瓦氏位摆位且中心线方向错误。C的角度与基准线组合不能使颅底平面与探测器平行，会造成颅底孔道与面颅严重重叠。D为头颅侧位，颅底孔道互相重叠无法辨认。E为柯氏位。", "tr": "颅底位对颈部后仰程度要求高，颈椎外伤、强直性脊柱炎、老年颈椎活动受限者难以完成，此时应改用CT。临床上若患者不能后仰，可让球管倾斜以尽量使中心线垂直于听眦线，但影像质量下降。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0111", "t": "多选题", "s": "关于头颅后前位与头颅侧位摄影，下列摆位与影像标准描述正确的是", "o": {"A": "头颅后前位取俯卧，前额与鼻尖紧贴探测器，听眦线与正中矢状面均垂直于探测器，中心线经枕外隆凸垂直射入、由眉间射出", "B": "头颅后前位标准影像上，两侧眼眶、岩骨与内耳道左右对称，岩骨嵴投影于眼眶之内", "C": "头颅侧位取俯卧头侧转，被检侧靠近探测器，正中矢状面与探测器平行、瞳间线垂直于探测器，中心线经外耳孔前上方约2.5cm处垂直射入", "D": "头颅侧位标准影像上，蝶鞍呈切线位显示，两侧前后床突、外耳孔基本重合，颅骨内外板与板障清晰", "E": "头颅后前位与侧位均应采用180cm的焦-片距，以减少颅骨的几何放大"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-007", "kp": "头颅正侧位摆位与影像标准", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A正确：头颅后前位以“双垂直”（听眦线、正中矢状面均垂直于探测器）为摆位核心，中心线经枕外隆凸射入、眉间射出。B正确：左右对称是判断有无旋转的直接依据，而0°投照时岩骨嵴恰位于眶内，这也正是需要柯氏位加角度的原因。C正确：侧位以正中矢状面平行于探测器、瞳间线垂直于探测器为核心，中心线经外耳孔前上方约2.5cm（蝶鞍区）射入。D正确：蝶鞍切线显示、前后床突及外耳孔重合，是侧位无旋转的标准判据。【为什么错】E错误：头颅摄影常规采用100cm的焦-片距，180cm是胸部后前位与心脏远达片的距离；颅骨紧贴探测器时物-片距已很小，无须靠长SID控制放大。", "tr": "“对称”是正位判断旋转的指标，“重合”是侧位判断旋转的指标。另注意别把胸部的180cm套用到头颅，SID的记忆必须与部位绑定。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0112", "t": "单选题", "s": "某技师为疑似上颌窦炎患者摄取瓦氏位，所得影像上岩骨嵴投影在上颌窦中部，遮盖了上颌窦下份。造成该结果最可能的原因及正确处理是", "o": {"A": "头部后仰不足，听眦线与探测器夹角小于37°，应增加头部后仰程度", "B": "头部后仰过度，听眦线与探测器夹角大于37°，应减小后仰程度", "C": "正中矢状面偏离中线，应重新对准中线", "D": "中心线向足侧倾斜过多，应改为垂直投照", "E": "焦-片距过短造成放大，应加大至150cm"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SKL-008", "kp": "瓦氏位影像质量的原因分析", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】瓦氏位靠头部后仰把岩骨嵴“压”到上颌窦底以下。当后仰不足（听眦线与探测器夹角小于37°）时，投照几何接近后前位，岩骨嵴位置相对偏高，就会投影在上颌窦中部而遮盖窦腔下份，导致窦内少量积液漏诊。处理办法是增加颏部上抬、加大后仰角至标准37°。【为什么错】B恰好相反：后仰过度会使岩骨嵴下移过多，同时上颌窦被拉长变形、眶下缘外形失真，但不会遮盖窦腔下部。C造成的是两侧上颌窦、眼眶不对称，而非岩骨嵴位置改变。D瓦氏位本就采用垂直中心线，题干未提示成角。E焦-片距只影响放大率与清晰度，不改变岩骨嵴与上颌窦的相对投影关系。", "tr": "凡“重叠遮挡类”问题，先判断是角度问题还是旋转问题：遮挡（上下关系错）多为基准线角度不当，不对称（左右关系错）多为旋转或中线偏移。SID几乎从不引起结构重叠关系的改变。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0113", "t": "单选题", "s": "成人胸部后前立位摄影时，中心线的入射点与屏气方式是", "o": {"A": "经第4胸椎水平垂直射入，平静呼吸下曝光", "B": "经第6胸椎水平（约肩胛骨下角连线）垂直射入，深吸气后屏气曝光", "C": "经胸骨柄水平向头侧倾斜15°射入，深呼气后屏气曝光", "D": "经剑突水平垂直射入，深呼气后屏气曝光", "E": "经第10胸椎水平垂直射入，深吸气后屏气曝光"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-001", "kp": "胸部后前立位的中心线与屏气", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】成人胸部后前立位取站立面向探测器，双手背置于髋部、肘部外展使肩胛骨移出肺野，两肩下垂并等高；中心线经第6胸椎水平（相当于两侧肩胛骨下角连线）垂直射入，焦-片距180cm，深吸气后屏气曝光。深吸气可使膈肌下降、肺野充分展开，标准影像应显示第10后肋（或第6前肋）位于膈上。【为什么错】A的T4过高会使肺底与肋膈角显示不全，平静呼吸曝光则肺野扩张不足并可能产生运动模糊。C的向头侧15°是肺尖或前弓位的思路，且深呼气不适用于常规胸片。D剑突水平过低，上肺野与肺尖易被切除。E的T10已达膈下水平，属腹部范围。", "tr": "屏气方式随目的而变：常规胸片、膈上肋骨为深吸气后屏气；膈下肋骨、腹部立位为深呼气后屏气；观察气胸可加摄呼气相。中心线水平不同引起的是“照射野包含不全”，与曝光条件无关。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0114", "t": "多选题", "s": "关于胸部侧位与前弓位摄影，下列描述正确的是", "o": {"A": "胸部侧位常规取左侧位（左侧胸壁贴探测器），可减小心脏的几何放大", "B": "胸部侧位双上肢应上举抱头或前伸交叉，避免肱骨与上纵隔重叠", "C": "胸部侧位中心线经腋中线第6胸椎水平垂直射入，深吸气后屏气", "D": "前弓位患者背向探测器并使身体后倾，中心线经胸骨柄水平射入，主要用于显示肺尖、锁骨下区及右肺中叶、左肺舌段病变", "E": "胸部侧位的焦-片距与四肢摄影相同，常规采用100cm"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-002", "kp": "胸部侧位与前弓位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A正确：心脏偏左，左侧贴板可使心脏物-片距最小、放大最轻，故常规取左侧位；若重点观察右肺病变可改右侧位。B正确：上肢上举抱头能把肱骨与肩部软组织移出照射野，避免与上纵隔、胸椎重叠。C正确：侧位中心线经腋中线第6胸椎水平垂直射入，同样在深吸气后屏气。D正确：前弓位（肺尖后前斜位）通过身体后倾改变投照方向，使锁骨与前段肋骨投影移开肺尖区，暴露被遮盖的肺尖与锁骨下区病灶，对右肺中叶、左肺舌段的显示也优于常规后前位。【为什么错】E错误：胸部侧位与后前位一样属胸部摄影，焦-片距应取180cm（至少150cm）；侧位时心脏与纵隔距探测器更远、物-片距更大，若沿用四肢的100cm，几何放大与半影会明显加重。", "tr": "常见误区之一是认为侧位应取“患侧贴板”：评价心脏、纵隔时取左侧位，观察一侧胸膜或肺内局限病变时才取患侧贴板。误区之二是把SID与“部位大小”挂钩，实际上胸部（含侧位）一律用长距离。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0115", "t": "案例分析题", "s": "患者男性，58岁，慢性咳嗽伴右侧胸痛1个月。床旁仰卧前后位胸片示右侧肋膈角略变钝、右下肺野密度稍高，临床怀疑右侧少量胸腔积液，但不能确定，且患者可以短暂配合改变体位。临床要求用普通X线进一步证实是否存在少量游离积液。作为技师，最恰当的摄影方案是", "o": {"A": "加摄右侧卧水平方向投照位（右侧向下侧卧5~10分钟后，X线水平方向投照），观察沿右侧胸壁分布的带状液体影", "B": "加摄左侧卧水平投照位，使液体聚集于左侧胸壁便于测量", "C": "加摄右侧胸部前弓位，观察肋膈角变化", "D": "重复仰卧前后位并提高管电压至120kV", "E": "加摄呼气相后前立位，通过肺体积缩小凸显积液"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-003", "kp": "侧卧水平投照位显示少量胸腔积液", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】游离性胸腔积液受重力影响向低处流动。患侧向下侧卧并静置数分钟后，用水平方向X线投照，少量液体在患侧胸壁与肺外缘之间形成一条带状致密影，可检出约100ml甚至更少的积液，敏感性远高于立位或仰卧位，是普通X线证实少量游离积液的经典方法。【为什么错】B患侧向上则液体流向对侧或纵隔旁，不能在患侧显示带状影，方向搞反。C前弓位是为暴露肺尖与中叶舌段设计的，对积液无帮助。D单纯提高kV会降低对比度，反而更不利于显示少量液体。E呼气相主要用于气胸检出，且立位时少量积液仍被膈肌与肋膈角掩盖。", "tr": "口诀：查积液“患侧向下”，查气胸“患侧向上”（健侧卧位）；两者都必须用水平方向投照，若沿用垂直投照则液气平面无法显示。此外侧卧后需静置数分钟待液体充分流动再曝光。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0116", "t": "单选题", "s": "关于肋骨X线摄影的屏气方式，下列组合正确的是", "o": {"A": "膈上肋骨深吸气后屏气，膈下肋骨深呼气后屏气", "B": "膈上肋骨深呼气后屏气，膈下肋骨深吸气后屏气", "C": "膈上与膈下肋骨均在深吸气后屏气", "D": "膈上与膈下肋骨均在深呼气后屏气", "E": "膈上肋骨平静呼吸下曝光，膈下肋骨深吸气后屏气"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-004", "kp": "膈上与膈下肋骨的屏气方式", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】膈上肋骨（第1~9肋）以含气肺组织为背景，深吸气后屏气可使膈肌下降、肺野充气增加，肋骨与低密度肺形成良好对比，同时更多肋骨被“抬”到膈上；膈下肋骨（第9~12肋）以肝、脾、肾等实质脏器为背景，深呼气后屏气使膈肌上升，肋骨相对下移离开肺野并减少呼吸运动，且需相应提高曝光条件穿透腹部。【为什么错】B把两者完全颠倒。C、D一刀切，忽视了膈上与膈下背景组织密度的根本差别。E平静呼吸曝光会造成呼吸运动模糊，任何肋骨摄影都应屏气。", "tr": "肋骨摄影还须注意：斜位可使腋段肋骨展开、避免与脊柱重叠；外伤患者应按临床压痛点选择照射范围与投照方向，且膈下肋骨曝光条件近似腹部而非胸部，条件照搬胸部会导致穿透不足。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0117", "t": "多选题", "s": "关于心脏三位片（心脏远达片、右前斜位、左前斜位）与食管钡餐联合检查，下列说法正确的是", "o": {"A": "心脏后前位远达片采用180~200cm焦-片距，目的是使心影放大率接近真实、便于测量心胸比", "B": "右前斜位（第一斜位）通常取45°~55°，同时口服钡剂充盈食管，主要观察左心房增大对食管中段的压迫", "C": "左前斜位（第二斜位）通常取60°~65°，可较好显示左右心室、主动脉弓及其分支的展开", "D": "食管钡剂应在曝光前一次大量吞服并等待完全排空后摄影", "E": "心脏远达片应在深呼气后屏气曝光，以使膈肌上升、心影充分显露"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-005", "kp": "心脏三位片与食管钡餐", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A正确：心脏距探测器较远（物-片距大），只有加大SID至180~200cm才能把放大率控制在5%以内，使心胸比测量可靠。B正确：右前斜位使食管与左心房在切线方向上分开，服钡后可直观显示左心房增大所致的食管中段受压后移，是二尖瓣病变的经典征象。C正确：左前斜位60°~65°可把室间隔置于近似切线位，分别展示左、右心室缘，并使主动脉弓呈“开窗”状显示。【为什么错】D错误：食管钡餐应在曝光瞬间嘱患者含服并吞下一口稠钡，使食管处于充盈状态时曝光；等待“完全排空”后摄影则食管内无对比剂，根本无法观察压迫。E错误：心脏远达片与常规胸片一样在深吸气后屏气曝光；深呼气会使膈肌上升、心影横位增大并压缩肺野，导致心胸比虚假增大。", "tr": "第一斜位（右前斜）看左心房与肺动脉段，第二斜位（左前斜）看左右心室与主动脉弓，二者的角度与观察重点最易混淆。心胸比测量必须建立在“立位、深吸气、180cm以上SID”三个前提上，缺一即失去可比性。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0118", "t": "案例分析题", "s": "患者男性，24岁，胸部外伤后突发左侧胸痛、呼吸困难，急诊怀疑左侧气胸。患者血流动力学稳定，能站立配合。急诊技师首次拍摄的立位后前位胸片未见明确肺压缩带，临床仍高度怀疑。此时应采取的技术措施与判读要点，下列错误的是", "o": {"A": "加摄深呼气相后前立位片：呼气时肺体积缩小而胸膜腔内气体量基本不变，气胸所占比例相对增大，肺压缩缘更易显示", "B": "若患者随后病情变化只能仰卧，应注意仰卧位气胸气体聚集于前内侧，可表现为患侧肋膈角异常加深透亮的“深沟征”", "C": "为提高检出率，应把管电压降至60kV以下以增强软组织对比", "D": "可加摄健侧向下的侧卧水平投照位，使气体升至患侧胸壁外侧带而易于识别", "E": "胸片仍阴性但临床高度怀疑时，可建议行胸部CT，其对少量气胸的敏感性明显高于普通X线"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-006", "kp": "气胸的X线摄影技术优化", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】本题选错误项。C错误：气胸的检出依赖气体与肺组织之间的天然高对比，胸部摄影本就采用高千伏（约120kV）技术以减小肋骨与纵隔的遮盖、扩大灰阶宽容度；把管电压降到60kV以下会使肋骨骨影浓重、纵隔穿透不足，反而掩盖细小的压缩肺缘。【为什么错】A正确：呼气相时肺内含气减少、密度升高，而胸膜腔内游离气体量不变，两者密度差加大，压缩肺缘的细线影更易辨认。B正确：仰卧位气体上浮至前胸与肋膈隐窝前部，形成患侧肋膈角异常加深、透亮度增高的深沟征，是床旁片识别气胸的关键间接征象。D正确：气体向高处聚集，故取健侧向下侧卧（患侧在上）、水平方向投照，气体沿患侧外侧胸壁形成带状透亮区。E正确：CT可检出X线难以显示的少量与包裹性气胸，是平片阴性而临床高度怀疑时的合理建议。", "tr": "“提高软组织对比就要降kV”这一惯性思维在胸部摄影中不成立——胸部要的是宽容度而非高对比。另注意侧卧位的方向：查气体是健侧向下，查液体是患侧向下，两条口诀方向相反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0119", "t": "单选题", "s": "胸锁关节后前位摄影的常规摆位与中心线，下列最恰当的是", "o": {"A": "俯卧或立位面向探测器，两臂放于身旁、下颌前伸，正中矢状面对准探测器中线，中心线经第3胸椎水平垂直射入，屏气曝光", "B": "仰卧，中心线经胸骨柄向头侧倾斜25°射入", "C": "立位侧位，中心线经腋中线第6胸椎射入", "D": "俯卧，身体向被检侧旋转45°，中心线向足侧倾斜30°", "E": "仰卧，中心线经剑突垂直射入，深吸气后屏气"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-CHE-007", "kp": "胸锁关节摄影体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸锁关节后前位取俯卧或立位面向探测器，正中矢状面对准中线并垂直于探测器，下颌前伸避免遮挡，两臂置于身旁，中心线经第3胸椎水平（约相当于胸锁关节水平）垂直射入，屏气以消除呼吸运动。为减少与胸椎、纵隔的重叠，临床常在此基础上加摄身体旋转10°~15°的轻度斜位，分别显示两侧关节。【为什么错】B向头侧25°会使关节与颈根部软组织重叠，且仰卧位物-片距增大。C为胸部侧位，两侧胸锁关节完全重叠。D的45°旋转过大并配合足侧30°倾斜，会使关节结构严重变形。E剑突水平远低于胸锁关节，照射野不含目标结构。", "tr": "胸锁关节位置高（约第3胸椎水平），与常见的“胸部中心线T6”不同；且因与脊柱重叠，单纯正位常难判断半脱位，须加摄小角度斜位或进一步做CT。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0120", "t": "单选题", "s": "腹部仰卧前后位（KUB）摄影的常规要求，下列错误的是", "o": {"A": "照射野上缘应包括两侧肾上极，下缘包括耻骨联合，两侧包括腹壁软组织", "B": "中心线经剑突与耻骨联合连线中点（约脐水平）垂直射入", "C": "焦-片距100cm，使用滤线栅", "D": "呼气后屏气曝光，以减少膈肌与肠管运动造成的模糊", "E": "为显示膈下游离气体，KUB仰卧位是首选体位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-001", "kp": "腹部仰卧前后位（KUB）的技术要求", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】本题选错误项。E错误：仰卧位时游离气体上浮至腹壁下方而非膈下，与含气肠管重叠难以辨认；显示膈下游离气体必须用立位腹部（或不能站立者用左侧卧水平投照位），使气体聚集在膈肌与肝顶或右侧腹壁与肝之间形成新月形透亮影。【为什么错】A正确：KUB即肾-输尿管-膀胱，范围必须自肾上极至耻骨联合，否则输尿管全程或膀胱区结石会被漏掉。B正确：中心线经剑突与耻骨联合连线中点、约脐水平垂直射入。C正确：腹部厚度大、散射线多，须用滤线栅，SID为100cm。D正确：呼气后屏气可减小膈肌运动幅度并使腹部厚度略减。", "tr": "KUB与“急腹症腹部立位片”目的不同：KUB主要看泌尿系阳性结石与钙化，立位片主要看游离气体与肠管气液平面。临床怀疑消化道穿孔时只拍仰卧位是典型的技术失误。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0121", "t": "案例分析题", "s": "患者男性，46岁，突发上腹剧痛4小时，腹肌紧张，临床高度怀疑消化道穿孔，需X线证实有无膈下游离气体。患者疼痛剧烈，勉强可在搀扶下站立数分钟。作为技师，下列处理最恰当的是", "o": {"A": "立即在患者刚站起时曝光，避免其体力不支", "B": "让患者站立或坐位保持5~15分钟后再曝光，照射野上缘务必包全两侧膈肌，中心线经剑突下方水平射入，深呼气后屏气", "C": "取仰卧前后位，中心线垂直经脐部射入，深吸气后屏气", "D": "取俯卧位水平侧位投照，中心线经腰部射入", "E": "先行腹部加压后摄立位片，以推开肠管显露膈下"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-002", "kp": "腹部立位显示膈下游离气体", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】游离气体需要时间从穿孔部位上浮聚集到膈下，故应让患者站立或坐位保持数分钟（一般5~15分钟）后再曝光，否则少量气体尚未聚集易致假阴性。照射野上缘必须包含双侧膈肌，中心线经剑突下方水平射入，深呼气后屏气使膈肌上升、膈下间隙显示清楚。【为什么错】A立即曝光是最常见的假阴性原因。C仰卧位气体不在膈下，且中心线经脐部时膈肌常被切除在照射野外。D俯卧位水平侧位不是显示膈下游离气体的标准方法，气体会移向腹侧而非膈下。E腹部加压是静脉肾盂造影中滞留对比剂的手段，对急腹症属禁忌，压迫可加重穿孔与疼痛。", "tr": "两个高频失分点：一是“站立等待时间”常被忽略；二是照射野上缘未包全膈肌，导致片子上根本看不到膈下区域。对完全不能站立者，应改取左侧卧水平投照位，观察肝右缘与右侧腹壁间的游离气体。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0122", "t": "多选题", "s": "关于不能站立患者的腹部水平方向投照检查，下列说法正确的是", "o": {"A": "新生儿、危重或年老体弱不能站立者，可取左侧卧水平投照位代替立位腹部片", "B": "取左侧卧位是因为肝脏位于右侧、密度均匀，游离气体上浮到右侧腹壁与肝之间形成条带状透亮影，易于识别", "C": "侧卧后应停留数分钟待气体充分上浮再曝光", "D": "水平投照时X线中心线必须与地面平行，若沿用垂直投照则不能显示气液平面", "E": "新生儿坏死性小肠结肠炎疑有穿孔时，因患儿无法配合，只能采用仰卧前后位垂直投照"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-003", "kp": "侧卧水平位与仰卧水平侧位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】A正确：立位是显示游离气体与气液平面的首选，但新生儿、休克、脊柱外伤等无法站立者只能改用水平方向投照的卧位技术。B正确：左侧卧使右侧朝上，肝脏为均质实质器官、无肠气干扰，游离气体聚集于肝与右侧腹壁之间形成清晰带状透亮区；若取右侧卧则气体升至左侧，易与胃泡、结肠脾曲气体混淆。C正确：与立位同理，需静置数分钟待气体迁移到位。D正确：显示气液平面与游离气体的本质是利用重力分层，只有中心线与液面平行（即水平投照）才能把界面投影成清晰的线，垂直投照会把分层信息“压平”而丢失。【为什么错】E错误：新生儿虽不能站立，但完全可以采用仰卧水平侧位（患儿仰卧不动、X线自侧方水平射入）或左侧卧水平投照位；这类技术只需移动球管与探测器而无须患儿配合，是新生儿气腹诊断的常规方法。仅拍仰卧前后位垂直投照会漏诊游离气体。", "tr": "关键不是“卧位还是立位”，而是“X线是否水平”。很多考生记成“侧卧位可显示液平”，忽略了必须配合水平投照；同时要记牢腹部取左侧卧（肝为背景），与胸部查积液取患侧卧的逻辑不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0123", "t": "单选题", "s": "新生儿先天性肛门闭锁行腹部倒立侧位摄影，下列操作要点错误的是", "o": {"A": "检查前应先将患儿倒立约1~5分钟，使结肠内气体充分上升至直肠盲端", "B": "在肛门隐窝处（正常肛门位置的皮肤上）粘贴金属标记物作为测量参照", "C": "取侧位、中心线经大转子水平水平方向射入，包括耻骨联合与骶尾骨", "D": "通过测量直肠盲端气体影与肛门皮肤标记之间的距离，判断闭锁位置的高低", "E": "为使气体尽快到达盲端，倒立前应先经肛门注入适量气体以加速充气"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-004", "kp": "先天性肛门闭锁的倒立侧位摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】本题选错误项。E错误：肛门闭锁患儿肛门无通道，根本无法经肛门注气；该检查依赖的是患儿出生后吞咽空气自然到达远端肠管，所以通常需在出生12~24小时后进行，过早检查因肠气尚未到达盲端会造成闭锁位置“假性偏高”。【为什么错】A正确：倒立数分钟是让气体上浮抵达盲端的必要步骤。B正确：肛门隐窝处贴金属标记提供体表参照，是距离测量的基准。C正确：取侧位、水平方向投照并包全耻骨联合与骶尾骨，因为临床按耻骨-尾骨连线（PC线）判断高中低位闭锁。D正确：盲端气体影至皮肤标记的距离是分型的量化指标，距离大提示高位闭锁。", "tr": "两个关键前提最易被忽略：一是检查时机（生后12~24小时，让吞入气体到达盲端），二是必须水平投照并包含耻骨联合和尾骨以便画PC线。“注气加速”是明显违背解剖事实的干扰项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0124", "t": "单选题", "s": "腹部X线摄影前的常规准备，下列不恰当的是", "o": {"A": "检查前1~2日不服含金属的药物，不做钡剂造影检查", "B": "必要时于检查前晚服缓泻剂或检查前行清洁灌肠，以减少肠内容物与气体干扰", "C": "去除腰腹部衣物上的金属扣、拉链及膏药等高密度异物", "D": "急腹症疑似穿孔或肠梗阻的患者，应先行清洁灌肠再摄片", "E": "嘱患者摄影时呼气后屏气，减少运动模糊"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-ABD-005", "kp": "腹部摄影前准备与禁忌", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】本题选不恰当项。D错误：急腹症尤其疑似消化道穿孔或肠梗阻时禁忌清洁灌肠——灌肠可加重穿孔、诱发肠破裂，还会注入气体与液体，干扰对游离气体与气液平面的判断。此类患者应直接摄片，不做肠道准备。【为什么错】A正确：钡剂与含金属药物残留会形成高密度伪影，掩盖泌尿系结石等病变。B正确：择期腹部平片（如KUB、IVP前）需清洁肠道以提高显示率。C正确：衣物金属件与膏药是常见的伪影来源。E正确：呼气后屏气可减小膈肌活动、降低运动模糊。", "tr": "肠道准备的适用范围要分清：择期泌尿系检查需要准备，急腹症一律不做准备、不灌肠、不口服对比剂。把常规准备“机械套用”到急诊是临床与考试中的双重错误。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0125", "t": "单选题", "s": "颈椎左后斜位摄影（身体左后方靠近探测器，与探测器约成45°），中心线向头侧倾斜15°，该体位显示的椎间孔是", "o": {"A": "左侧（靠近探测器侧）椎间孔", "B": "右侧（远离探测器侧）椎间孔", "C": "两侧椎间孔同时展开显示", "D": "左侧椎弓峡部而非椎间孔", "E": "两侧关节突关节，椎间孔不显示"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-001", "kp": "颈椎斜位显示椎间孔的规律", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】颈椎椎间孔向前、外、下方开口，与矢状面约成45°、与水平面约成15°。采用后斜位（身体后方靠近探测器）时，靠近探测器一侧的椎间孔恰好与中心线方向一致而被展开，故左后斜位显示左侧椎间孔；中心线向头侧倾斜15°是为了抵消椎间孔向下倾斜的角度。【为什么错】B是前斜位的规律——前斜位显示的是远离探测器的对侧椎间孔，二者规律相反。C任何单一斜位都只能展开一侧椎间孔，另一侧因投照方向不一致而变形缩窄，所以颈椎斜位必须左右各摄一张。D椎弓峡部与“苏格兰狗”征是腰椎斜位的内容，颈椎斜位主要看椎间孔与钩椎关节。E关节突关节在颈椎侧位显示最佳，斜位的目的正是椎间孔。", "tr": "记忆口诀：“后斜看同侧、前斜看对侧”，这是颈椎斜位最核心也最易混的考点。此外别把颈椎斜位的15°头侧倾斜与腰椎斜位（垂直中心线、45°旋转）混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0126", "t": "单选题", "s": "颈椎张口位摄影的摆位要点与显示结构，下列正确的是", "o": {"A": "患者仰卧、口尽量张大，使上颌门齿咬合面与乳突尖的连线垂直于探测器，中心线经两口角连线中点垂直射入，主要显示寰枢关节与齿突", "B": "患者仰卧、下颌内收，中心线向头侧倾斜15°，主要显示C1~C3椎体前缘", "C": "患者俯卧张口，中心线向足侧倾斜25°，主要显示枕骨大孔", "D": "患者侧卧张口，中心线经外耳孔垂直射入，主要显示颞下颌关节", "E": "患者仰卧张口，中心线经甲状软骨垂直射入，主要显示C6~C7椎间隙"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-002", "kp": "颈椎张口位（寰枢关节）", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】张口位专为显示被上下颌骨遮挡的寰椎、枢椎而设计。摆位时患者仰卧、正中矢状面垂直于台面并对准中线，口尽量张大，调整头部使上颌门齿咬合面与乳突尖的连线垂直于探测器——这样上颌切牙与枕骨基底部的投影恰好重叠于齿突之外，齿突、寰枢外侧关节间隙才能完整暴露。中心线经两口角连线中点垂直射入。标准影像应显示齿突居中、两侧寰枢关节间隙对称。【为什么错】B不张口时齿突被门齿与枕骨完全遮盖。C俯卧张口不便且25°足侧倾斜显示的是枕骨方向。D为颞下颌关节侧位思路。E甲状软骨约平C4~C5，且下颈椎不需要张口。", "tr": "张口位失败最常见的两个原因：一是张口不足或基准线不准，导致门齿或枕骨基底部遮盖齿突；二是头部旋转造成齿突偏离中线、两侧关节间隙不等宽，易被误判为寰枢关节半脱位。判读前须先确认体位是否标准。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0127", "t": "多选题", "s": "关于腰椎斜位摄影与“苏格兰狗”征，下列描述正确的是", "o": {"A": "腰椎斜位一般使身体冠状面与探测器成45°，中心线经髂嵴上方约3cm、脊柱旁开约5cm处垂直射入", "B": "“狗嘴”为同侧横突，“狗眼”为椎弓根，“狗耳”为上关节突，“狗颈”为椎弓峡部，“狗身”为椎板，“前腿”为下关节突", "C": "椎弓峡部裂时表现为“狗颈”部出现透亮的带状裂隙，形似狗颈上戴了一条项圈", "D": "后斜位显示的是靠近探测器一侧的椎弓附件结构", "E": "腰椎斜位主要用于显示椎间孔，与颈椎斜位的目的完全相同"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-003", "kp": "腰椎斜位与椎弓峡部裂", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A正确：腰椎斜位常规取45°（腰骶部有时用30°），中心线经髂嵴上方约3cm、棘突旁开约5cm垂直射入，可使一侧椎弓附件呈切线展开。B正确：这是“苏格兰狗”各部分与解剖结构的标准对应关系。C正确：峡部（狗颈）出现透亮裂隙即“戴项圈征”，是峡部裂的直接征象，常见于L5。D正确：腰椎后斜位同样遵循“后斜显示近片侧”的规律，展示的是靠近探测器一侧的椎弓根、峡部与关节突。【为什么错】E错误：腰椎斜位的核心目的是显示椎弓峡部与关节突关节，而腰椎椎间孔在侧位上显示最清楚；颈椎的椎间孔才需要斜位展开。二者目的并不相同。", "tr": "“看椎间孔”这一说法在颈椎成立、在腰椎不成立，这是脊椎摄影最典型的张冠李戴。另注意峡部裂多发于L5，摄影时下缘务必包全腰骶段，照射野过高会漏掉责任节段。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0128", "t": "案例分析题", "s": "患者女性，36岁，反复颈部疼痛伴活动后加重2年，颈椎正侧位片未见明显骨质异常，临床怀疑颈椎节段性不稳，要求进一步行功能位检查以评估椎体间的动态位移。患者无外伤史、无神经根刺激症状、颈部可主动活动。作为技师，下列做法错误的是", "o": {"A": "摄取颈椎过伸位与过屈位侧位片，两片曝光条件与焦-片距保持一致，便于对比椎体后缘连线的连续性", "B": "嘱患者在能耐受范围内主动最大限度前屈与后伸，不得由他人强行推压头部协助", "C": "焦-片距取150cm，双肩尽量下垂以充分显示下颈椎", "D": "对急性颈部外伤、疑有骨折或脱位者，禁止行过伸过屈位检查", "E": "为节省时间，可只摄过屈位一张，因不稳定多在屈曲时显现"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-004", "kp": "颈椎过伸过屈功能位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】本题选错误项。E错误：颈椎节段性不稳既可表现为屈曲位的椎体前滑移，也可表现为后伸位的后滑移，只摄过屈位一张会遗漏后伸时才显现的不稳；标准做法是过屈位、过伸位各摄一张并与中立侧位比较。【为什么错】A正确：功能位的价值在于两片间对比，只有保持相同SID与曝光条件、相同侧位方向，位移测量才具可比性。B正确：必须由患者主动完成，被动推压可能造成脊髓损伤，是安全底线。C正确：颈椎侧位因肩部遮挡、物-片距较大，常规取150cm并嘱双肩下垂（必要时手持重物），以显示至C7~T1。D正确：急性外伤、可疑骨折或不稳定脱位是过伸过屈位的明确禁忌，应先行CT明确。", "tr": "功能位的两大红线：一是急性外伤禁做，二是必须主动、不可被动。技术上还须强调两片条件一致，否则放大率差异会造成假性位移。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0129", "t": "单选题", "s": "腰椎前后位与侧位摄影，下列关于中心线与技术要点的描述，正确的是", "o": {"A": "前后位取仰卧屈髋屈膝，中心线经脐上约3cm（相当于第3腰椎）垂直射入；侧位双膝间垫棉垫使腰椎长轴与台面平行，中心线经第3腰椎垂直射入", "B": "前后位中心线应经剑突水平射入，侧位经髂嵴水平射入", "C": "前后位应伸直双下肢以增大腰椎前凸，使椎间隙展开", "D": "侧位摄影时无须使用滤线栅，因侧位体厚较小", "E": "腰椎摄影焦-片距应取150cm以减小放大"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-005", "kp": "腰椎正侧位摄影技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎前后位取仰卧、屈髋屈膝并使足底踏于台面，目的是减小腰椎生理前凸、使椎体与探测器平行、椎间隙展开；中心线经脐上约3cm（约L3水平）垂直射入。侧位时于腰部与两膝间加棉垫，使腰椎长轴与台面平行（避免下沉造成椎间隙倾斜），中心线经L3垂直射入，必要时对腰骶段中心线向足侧倾斜5°~10°。【为什么错】B剑突约平T9，髂嵴约平L4~L5间隙，两者都不是标准入射点。C伸直下肢会加大腰椎前凸，椎间隙反而倾斜、变窄，与目的相反。D腰椎侧位体厚远大于正位，散射线更多，必须使用滤线栅并提高曝光条件。E腰椎摄影常规SID为100cm，150cm用于颈椎侧位。", "tr": "屈髋屈膝的机制是“减小前凸让椎间隙与中心线平行”，与“让患者舒适”无关，容易被反向表述迷惑。侧位加垫的目的同样是让脊柱长轴与台面平行，尤其在臀部宽大的患者中不可省略。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0130", "t": "多选题", "s": "关于骶骨与尾骨X线摄影，下列描述正确的是", "o": {"A": "骶骨前后位中心线向头侧倾斜15°~20°，经耻骨联合上方约3cm射入，以抵消骶骨向后倾斜造成的重叠与缩短", "B": "尾骨前后位中心线向足侧倾斜10°~15°，经耻骨联合上方约3cm射入", "C": "骶尾骨侧位可在一张影像上同时显示骶骨与尾骨，中心线经髂后下棘前方约8cm处垂直射入", "D": "摄影前应尽量排空膀胱并清洁肠道，避免肠内容物与气体重叠", "E": "骶骨与尾骨的中心线倾斜方向相同，都向头侧倾斜"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-006", "kp": "骶尾椎摄影的角度", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A正确：骶骨在仰卧位向后下方倾斜，垂直投照会使其缩短并与耻骨重叠，故中心线向头侧倾斜15°~20°。B正确：尾骨自骶骨末端继续向前下弯曲，其倾斜方向与骶骨相反，需中心线向足侧倾斜10°~15°才能展开。C正确：侧位时骶尾骨位于同一平面，可一次显示，且对骶骨骨折与尾骨脱位的评估价值高于正位。D正确：直肠内粪便与气体、充盈的膀胱都会明显干扰骶尾骨的观察，故需肠道准备并排空膀胱。【为什么错】E错误：骶骨向头侧、尾骨向足侧，两者中心线方向恰好相反，这正是本知识点的核心。", "tr": "“骶头尾足”是记忆抓手：骶骨向头侧15°~20°，尾骨向足侧10°~15°。若一次曝光同时想看骶尾骨，正位无法兼顾角度，应分别摄影或直接采用侧位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0131", "t": "单选题", "s": "骨盆前后位摄影时，为使股骨颈充分展开、减少大小转子与股骨颈的重叠，双足应", "o": {"A": "自然外旋位", "B": "内旋15°~20°，两足拇趾内侧相靠", "C": "外旋45°", "D": "极度背屈并保持中立位", "E": "屈髋屈膝并外展60°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-007", "kp": "骨盆前后位的双足内旋", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】股骨颈存在约12°~15°的前倾角，仰卧自然状态下下肢多呈外旋，此时股骨颈与探测器不平行，投影缩短并与大转子重叠。将双足内旋15°~20°（两足拇趾内侧相靠、足跟稍分开）可抵消前倾角，使股骨颈呈最大长度显示，小转子部分被遮挡为正常表现。中心线经两髂前上棘连线中点下方约3cm（约耻骨联合上方3cm）垂直射入。【为什么错】A自然外旋正是需要纠正的状态。C外旋45°会使股骨颈严重缩短、小转子完全暴露。D单纯背屈不改变股骨旋转。E屈髋外展60°是蛙式位的摆位，不属于骨盆标准前后位。", "tr": "内旋是常规骨盆/髋关节正位的要求，但疑有股骨颈骨折、髋关节脱位或严重疼痛者禁止强行内旋，以免加重移位——此时按原位摄影并加摄水平侧位。影像上“小转子完全清晰显示”往往提示下肢外旋、体位不标准。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0132", "t": "案例分析题", "s": "患者女性，78岁，跌倒后右髋剧痛、下肢外旋短缩，不能站立与活动。骨盆前后位片提示右股骨颈可疑骨折线，临床要求补充侧位以判断骨折移位与成角。患者疼痛剧烈，右下肢任何被动活动均引发剧痛。作为技师，最恰当的方案是", "o": {"A": "采用蛙式位（Lauenstein位），将右髋外展外旋以获得股骨颈侧位", "B": "采用水平侧位（穿股侧位）：患者仰卧，健侧下肢屈髋屈膝上抬移开，探测器竖立紧贴患侧髂嵴上方，X线自健侧向患侧水平方向经腹股沟射入", "C": "让患者侧卧，患侧在下拍摄常规侧位", "D": "重复前后位并加大曝光条件以显示骨折线", "E": "取俯卧位，中心线经骶骨向足侧倾斜30°射入"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-008", "kp": "股骨颈骨折的水平侧位摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】疑似股骨颈骨折者的侧位必须避免患肢任何被动外展外旋，标准做法是水平侧位（又称穿股侧位、Danelius-Miller法）：患者仰卧不动，仅将健侧下肢屈曲上抬移出照射野，探测器竖直紧贴患侧髂嵴上方并与股骨颈垂直，X线自健侧腹股沟方向水平射入，即可在不搬动患肢的前提下获得股骨颈与髋关节的侧位影像。【为什么错】A蛙式位需要髋关节外展外旋，可使骨折移位加重甚至损伤旋股内侧动脉，为该情形的禁忌。C让患侧在下侧卧同样需要大幅活动患肢并承重，风险与痛苦均不可接受。D加大曝光条件不能提供第二个投照方向，无法评估前后成角与移位。E俯卧且中心线角度与髋关节无关，得不到侧位信息。", "tr": "蛙式位适用于儿童股骨头骨骺滑脱、股骨头缺血坏死等择期检查，绝不能用于急性股骨颈骨折。凡外伤后剧痛、肢体畸形者，一律遵循“不搬动患者、移动球管与探测器”的原则。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0133", "t": "单选题", "s": "胸椎前后位摄影时，为使各椎间隙尽量与中心线平行而清晰显示，正确的做法是", "o": {"A": "仰卧屈髋屈膝，中心线经胸骨角水平垂直射入，平静呼吸下曝光", "B": "仰卧屈髋屈膝使胸椎后凸减小，中心线经第6~7胸椎水平（约胸骨体中点）垂直射入，平静浅呼吸中曝光或屏气曝光", "C": "俯卧位，中心线向头侧倾斜20°射入", "D": "立位，中心线经剑突垂直射入，深吸气后屏气", "E": "仰卧，中心线经甲状软骨垂直射入，深呼气后屏气"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-SPI-009", "kp": "胸椎前后位摄影要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】胸椎前后位取仰卧、屈髋屈膝使背部平贴台面、胸椎后凸减小，中心线经第6~7胸椎水平（体表约相当于胸骨体中点、两侧肩胛下角连线上方）垂直射入。曝光可采用屏气，也可用低毫安长时间的“自主浅呼吸”技术，使肺纹理与肋骨影模糊而突出椎体轮廓。【为什么错】A胸骨角约平T4~T5，位置偏高，下胸椎易被切除；且完全的平静呼吸不加控制会造成整体运动模糊。C俯卧时椎体物-片距增大且20°头侧倾斜无解剖依据。D剑突约平T9~T10，中心线过低，上胸椎显示不全。E甲状软骨约平C4~C5，属颈椎范围。", "tr": "胸椎正位常见问题是上下段密度差过大（上胸椎被肩部与纵隔遮挡而偏白，下胸椎偏黑），处理方法包括使用楔形滤过板、阳极效应（把阳极端置于上胸椎侧）以及数字后处理的组织均衡技术。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0134", "t": "单选题", "s": "肩关节穿胸位（经胸侧位）摄影的主要适应证与摆位是", "o": {"A": "适用于肱骨近端骨折等患肢不能外展外旋者；患者侧立，患侧上臂紧贴探测器并下垂，健侧上肢高举抱头，中心线经健侧腋下水平穿过胸部对准患侧肱骨外科颈射入", "B": "适用于评价肩袖钙化；患者仰卧，中心线向头侧倾斜30°射入", "C": "适用于判断肩关节脱位方向；患者面向探测器旋转60°，中心线经肩胛骨内缘射入", "D": "适用于显示肩锁关节；患者立位双手持重物，中心线经两侧肩锁关节连线中点射入", "E": "适用于显示锁骨骨折；患者俯卧，中心线向足侧倾斜15°射入"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-001", "kp": "肩关节穿胸位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】穿胸位是在患肢无法活动时获得肱骨近端侧位信息的经典方法：患者侧立（患侧贴探测器）、患肢自然下垂并稍外旋以尽量避开肋骨重叠，健侧上肢高举抱头把肩部移开，中心线自健侧腋下水平穿过胸廓对准患侧外科颈。因需穿透胸廓，曝光条件高，常配合呼吸（低mA长时间）技术使肋骨与肺纹理模糊化。【为什么错】B为冈上肌出口位或肩关节前后位加角度的做法，与穿胸位无关。C描述的是肩胛骨Y位（肩胛骨侧位），用于判断脱位方向，但摆位角度与穿胸位不同。D是肩锁关节负重位。E是锁骨轴位的思路，且方向应向头侧倾斜。", "tr": "穿胸位与Y位都可提供“第二方向”，但适应证不同：穿胸位重点看肱骨近端骨折的成角移位，Y位重点看肱骨头相对于关节盂的前后脱位方向。二者常被混答。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0135", "t": "多选题", "s": "关于腕关节及手部摄影，下列描述正确的是", "o": {"A": "腕关节后前位取坐位、前臂平放，手掌向下呈半握拳状使腕骨紧贴探测器，中心线经桡骨茎突与尺骨茎突连线中点垂直射入", "B": "怀疑舟骨骨折时应加摄舟骨位：腕部尺偏，中心线可向肘侧（近端）倾斜10°~15°，使舟骨长轴接近平行于探测器而完整展开", "C": "手后前位摄影中心线经第3掌骨头垂直射入，可显示除拇指外各指骨、掌骨的正位", "D": "手斜位使手掌与探测器成45°、各指均匀分开并保持指骨与探测器平行，避免掌骨重叠", "E": "腕部外伤后首次X线检查未见骨折线，即可排除舟骨骨折，无须复查或进一步检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-002", "kp": "腕关节与手部摄影技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】A正确：半握拳可使腕骨掌屈贴近探测器、腕骨间隙展开，中心线取两茎突连线中点。B正确：舟骨斜跨腕骨、长轴倾斜，正位时投影缩短并与周围腕骨重叠，尺偏使舟骨伸展、配合向肘侧倾斜10°~15°的中心线可使其呈最大长度显示，是降低舟骨骨折漏诊率的关键。C正确：手后前位中心线经第3掌骨头，拇指因解剖旋转在此位上呈斜位。D正确：45°斜位并使手指分开、指骨平行于探测器，可避免掌骨互相重叠又不致指骨倾斜变形。【为什么错】E错误：舟骨骨折在伤后早期常因骨折线无分离而不显影，首次平片阴性并不能排除骨折；临床症状明显（鼻烟窝压痛）者应制动后于1~2周复查，或直接行CT/MRI，否则可能延误诊断并导致缺血坏死与不愈合。", "tr": "舟骨位的两个要点常只记住一个：尺偏（体位）与中心线成角（投照方向）必须配合使用。另需牢记“平片阴性≠无骨折”，舟骨是这一原则最经典的部位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0136", "t": "案例分析题", "s": "患者男性，19岁，篮球运动后右膝反复交锁伴疼痛，临床怀疑髌骨轨迹异常合并髁间窝内游离体。膝关节正侧位片未见明确异常，临床要求补充能显示髌股关节与髁间窝的X线体位。患者可自行屈膝、无急性外伤。作为技师，下列方案错误的是", "o": {"A": "加摄髌骨轴位（日出位）：患者屈膝约40°~60°，探测器置于髌骨远端，中心线沿髌骨与股骨滑车之间的间隙切线方向射入，观察髌股关节间隙与髌骨内外侧关节面", "B": "加摄髁间窝位（隧道位）：患者俯卧屈膝约40°~45°，中心线垂直于小腿长轴经腘窝射入，使髁间窝展开显示", "C": "髌骨轴位若屈膝角度过大，髌骨被拉入滑车沟内，早期髌股关节半脱位可能被掩盖", "D": "髁间窝位可用于显示髁间窝内游离体、剥脱性骨软骨炎及胫骨髁间隆突", "E": "上述特殊体位均属禁忌，急性膝关节外伤患者也不得屈膝摄影"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-003", "kp": "髌骨轴位与膝关节髁间窝位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】本题选错误项。E错误：本例为慢性症状、无急性外伤，患者可主动屈膝，髌骨轴位与髁间窝位均可安全实施；而且“急性外伤患者也不得屈膝摄影”把原则绝对化了——真正的规则是疑有骨折、脱位或剧痛时不做被动屈曲，改用水平侧位等不搬动患者的方法，并非所有外伤一律禁忌。【为什么错】A正确：髌骨轴位的本质是切线投照，使髌骨与股骨滑车间的关节面呈切线显示，用于评价髌股关节间隙、髌骨倾斜与半脱位。B正确：髁间窝位（隧道位）通过屈膝并使中心线垂直于小腿，把被髌骨与股骨髁遮挡的髁间窝打开。C正确：屈膝角度越大髌骨嵌入滑车沟越深，轻度半脱位被“复位”掩盖，故评价髌骨轨迹宜用较小屈曲角度。D正确：髁间窝位是显示游离体、剥脱性骨软骨炎与髁间隆突的经典体位。", "tr": "髌骨轴位的角度是把双刃剑：角度太小患者难以配合且股骨与髌骨重叠，角度过大则掩盖半脱位。命题常在“屈膝角度越大越好”上设陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0137", "t": "单选题", "s": "跟骨轴位摄影时，中心线的正确投照方向是", "o": {"A": "自足底向头侧倾斜35°~45°，对准第3跖骨基底部射入跟骨", "B": "垂直于足底射入", "C": "自足背向足侧倾斜30°射入", "D": "水平方向经内踝射入", "E": "自足跟后方向头侧倾斜10°射入"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-004", "kp": "跟骨轴位的中心线", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】跟骨轴位取仰卧或坐位，下肢伸直、踝关节尽量背屈（可用绷带牵拉足前部），足底垂直于探测器，中心线向头侧倾斜35°~45°，对准第3跖骨基底部射入跟骨，从而使跟骨体、跟骨结节及距下关节在轴向上展开而不与踝部重叠。【为什么错】B垂直射入会使跟骨与距骨、踝关节严重重叠。C方向相反，无法展开跟骨长轴。D水平经内踝是踝关节侧位的思路。E仅10°倾斜远不足以避开踝部重叠，跟骨仍呈缩短影像。", "tr": "跟骨检查应轴位与侧位联合：侧位用于测量Böhler角（跟骨结节关节角，正常约20°~40°），轴位用于观察跟骨体增宽、内翻及距下关节面。只拍其中一个位置是常见缺陷。踝背屈不足会使中心线与跟骨长轴夹角不当，影像仍缩短。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0138", "t": "单选题", "s": "关于踝关节前后位与“踝穴位”的区别，下列说法正确的是", "o": {"A": "踝穴位是在前后位基础上将小腿与足部内旋15°~20°，使踝关节内外侧间隙同时清晰显示，用于评价踝穴完整性", "B": "踝穴位是将足外旋45°后摄影", "C": "踝穴位与前后位摆位相同，仅提高曝光条件", "D": "踝穴位需中心线向头侧倾斜25°", "E": "踝穴位主要用于显示跟骨结节，与踝关节间隙无关"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-005", "kp": "踝关节前后位与踝穴位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】标准踝关节前后位时，因外踝较内踝更靠后，胫腓骨远端在投影上部分重叠，外侧关节间隙显示不清。将小腿连同足部一起内旋15°~20°（使两踝连线与探测器平行）即为踝穴位，此时内踝、外踝与距骨顶构成的“踝穴”三面间隙宽度一致，可敏感发现踝穴增宽、下胫腓联合分离等损伤。【为什么错】B方向相反，外旋会加重重叠。C体位不同才是关键，与曝光条件无关。D踝关节摄影中心线垂直于两踝连线中点上方约1cm处射入，不需向头侧成角。E跟骨结节由跟骨侧位与轴位显示。", "tr": "内旋的量要准确：不足则外侧间隙仍重叠，过度则内侧间隙假性增宽。踝穴位是判断下胫腓联合分离的关键位置，仅凭常规正位容易漏诊。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0139", "t": "多选题", "s": "关于四肢长骨与关节摄影的通用原则，下列正确的是", "o": {"A": "四肢长骨摄影应至少包含邻近的一个关节，以便定位并判断有无关节内骨折与旋转移位", "B": "正位与侧位的投照方向应互成90°，两个方向缺一不可", "C": "同一部位双侧对比摄影时，应采用相同的曝光条件、投照方向与体位，并在影像上标注左右", "D": "儿童骨骺损伤可疑时，可加摄健侧同名部位对照，但应权衡辐射剂量、避免常规化", "E": "为提高细节分辨力，四肢摄影应尽量使用大焦点、加大焦-片距至150cm"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-006", "kp": "四肢摄影通用原则", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】A正确：包含一端关节既可解剖定位，又能发现关节内骨折与旋转对位不良；前臂、小腿骨折还应尽量包含上下两端关节以判断合并脱位（如孟氏、盖氏骨折）。B正确：两个互相垂直的投照方向是判断骨折成角与移位方向的基本要求，单一方向可能完全漏掉侧方成角。C正确：双侧对比只有在条件、方向、体位一致时才具可比性，且必须标注左右防止差错。D正确：健侧对照对判断儿童骨骺与骨化中心有帮助，但属额外照射，应个体化而非常规。【为什么错】E错误：四肢摄影追求高空间分辨力，应使用小焦点、缩小物-片距，SID常规为100cm；大焦点会增大半影、降低清晰度，盲目加大SID则显著增加曝光量。", "tr": "“大焦点=大功率=更好”是典型误解。焦点选择取决于分辨力需求与管电流负荷：细节要求高、曝光量不大的四肢与乳腺用小焦点，需大电流的躯干厚部位才用大焦点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0140", "t": "单选题", "s": "肘关节侧位摄影的标准摆位是", "o": {"A": "屈肘90°，尺侧（小指侧）紧贴探测器、拇指朝上，肩部下降与肘关节置于同一水平面，中心线经肱骨外上髁垂直射入", "B": "伸直肘关节，手掌向上，中心线经鹰嘴垂直射入", "C": "屈肘45°，手背贴板，中心线向头侧倾斜20°射入", "D": "屈肘135°，前臂旋前，中心线经内上髁射入", "E": "伸直肘关节并极度旋前，中心线经桡骨头垂直射入"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-EXT-007", "kp": "肘关节侧位摄影要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】肘关节侧位要求屈肘90°、前臂呈中立位（尺侧贴板、拇指向上），并将肩部下降至与肘关节同一水平，使肱骨与前臂处于同一平面。标准影像的判据是肱骨内、外上髁相互重叠，肱骨滑车与小头呈同心圆状，鹰嘴与冠突清晰，桡骨头与尺骨冠突部分重叠。中心线经肱骨外上髁垂直射入。【为什么错】B伸直位无法形成侧位，且鹰嘴与肱骨完全重叠。C屈肘45°达不到标准侧位，且成角20°没有依据。D屈肘135°过小、前臂旋前会使桡尺骨交叉重叠。E极度旋前使桡骨头旋转变位，且伸直位不成侧位。", "tr": "“肩没有放下来”是肘侧位最常见的失败原因：肩部高于肘部时肱骨呈斜位，两上髁不能重叠，滑车与小头分离，容易被误判为关节间隙异常。评价肘部外伤时还应注意脂肪垫征（后脂肪垫抬高提示关节积液/隐匿骨折），这要求标准90°侧位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0141", "t": "单选题", "s": "静脉肾盂造影（IVP）中使用腹部压迫带的目的与要点，下列正确的是", "o": {"A": "压迫点位于两侧髂前上棘连线水平稍下方，压迫输尿管使对比剂滞留于肾盂肾盏内以提高显示率；解除压迫后立即摄全尿路片观察输尿管全程", "B": "压迫点位于剑突下方，用于阻断肾动脉血流延长显影时间", "C": "压迫的目的是加快对比剂经输尿管排入膀胱", "D": "所有受检者均须加压，包括腹主动脉瘤与急腹症患者", "E": "压迫应在注射对比剂后30分钟才开始施加"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-001", "kp": "IVP腹部压迫技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】腹部压迫带压在两侧髂前上棘连线水平稍下方，此处输尿管跨越骨盆缘、位置表浅，加压可暂时阻断对比剂下行，使肾盂肾盏充分充盈扩张、细节显示更佳。摄取肾区片后解除压迫，立即摄取包含双肾至膀胱的全尿路片，观察输尿管全程通畅情况。【为什么错】B剑突下方压迫既压不到输尿管，也不可能阻断肾动脉。C与压迫的目的完全相反，压迫是滞留而非加速排出。D腹主动脉瘤、腹部巨大肿块、急腹症、近期腹部手术、妊娠及严重外伤者禁用加压。E压迫应在注射对比剂后早期即施加，30分钟后肾盂显影高峰已过，失去意义。", "tr": "加压是“提高肾盂显示”的手段，解压是“显示输尿管”的手段，两者一前一后不可颠倒。禁忌人群必须牢记，考试常用“腹主动脉瘤患者常规加压”作陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0142", "t": "多选题", "s": "关于静脉肾盂造影（IVP）的检查前准备与摄片程序，下列正确的是", "o": {"A": "检查前应清洁肠道，摄影前先拍摄全尿路平片，以了解肠道准备情况并观察阳性结石", "B": "常规于注射对比剂后约7分钟、15分钟、30分钟分别摄取肾区片，必要时延长至60分钟或更久摄延迟片", "C": "肾盂显影浅淡时可适当延长摄片时间或加摄俯卧位片，帮助对比剂充盈肾盂", "D": "检查前应了解肾功能、有无甲状腺功能亢进及碘对比剂过敏史，并备好抢救药品与设备", "E": "为提高肾盂显影浓度，应嘱患者检查前24小时严格禁水以造成脱水状态"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-002", "kp": "IVP检查前准备与摄片时间序列", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A正确：肠内容物与气体会掩盖肾影与输尿管，故需清洁肠道；造影前平片既是对照片，也用于判断准备是否合格及有无阳性结石。B正确：7、15、30分钟是经典的三个摄片时间点，分别对应肾盂肾盏充盈、输尿管显影、膀胱充盈，显影延迟者需加摄60分钟乃至数小时延迟片。C正确：俯卧位可借助体位使对比剂向肾盂集中并有助于输尿管上段充盈。D正确：碘对比剂使用前须评估肾功能、甲状腺功能与过敏史，并具备抢救条件。【为什么错】E错误：传统上曾用限水提高对比剂浓度，但现代指南明确反对为造影而使患者脱水——脱水显著增加对比剂肾病风险，尤其在糖尿病、肾功能不全与老年患者中，应保证适当水化。", "tr": "“禁水浓缩尿液”是被淘汰的旧做法，命题常以此设陷阱。摄片时间序列要与检查目的联动：肾功能减退者延迟片才是关键，机械照搬7/15/30分钟而不加延迟片会导致检查失败。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0143", "t": "案例分析题", "s": "患者男性，62岁，右侧腰痛伴血尿1周。血清肌酐明显升高（估算肾小球滤过率约25ml/(min·1.73m²)），超声提示右肾积水，需明确梗阻部位与程度。既往有轻度碘对比剂过敏史（表现为荨麻疹）。临床拟行泌尿系造影。作为技师，就检查方式的选择与技术要点，下列判断错误的是", "o": {"A": "该患者肾功能明显减退，静脉肾盂造影因肾排泄对比剂能力下降而显影不佳，不宜作为首选", "B": "可建议改行逆行肾盂造影：经膀胱镜向输尿管插管后直接注入对比剂，显影不依赖肾功能，且全身吸收量少", "C": "逆行肾盂造影时对比剂注入量与压力应严格控制（成人一侧通常数毫升至10ml左右，缓慢注入），避免压力过高引起肾盂-肾小管返流与感染扩散", "D": "有碘对比剂过敏史者，即使行逆行造影也应做好抗过敏与抢救准备，因对比剂仍可经黏膜或返流吸收", "E": "为提高显影效果，逆行造影时应尽可能快速、大量注入对比剂直至患者出现明显腰胀"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-003", "kp": "逆行肾盂造影的适应证与操作要点", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】本题选错误项。E错误：以“患者出现明显腰胀”作为注入终点极其危险——腰胀恰恰提示肾盂已过度充盈、腔内压力过高，是应立即停止注射的信号；快速大量注入可造成肾盂-肾小管返流、肾盂静脉返流，并把感染带入上尿路。【为什么错】A正确：IVP依赖肾小球滤过与浓缩排泄，肾功能减退时肾盂显影浅淡甚至不显影，并加重对比剂肾病风险。B正确：逆行造影把对比剂直接注入集合系统，不依赖排泄功能，是肾功能不全、IVP显影不佳或需精确判定梗阻部位时的替代方案。C正确：成人一侧注入量通常仅数毫升至10ml左右，须缓慢注入并在透视监视下进行。D正确：黏膜吸收与返流仍可使少量对比剂进入循环，有过敏史者需预案与抢救准备。", "tr": "肾功能不全并非泌尿系造影的绝对禁区，关键是换路径：静脉法改逆行法。同时牢记逆行造影的两大并发症来自“压力”与“无菌”，操作核心是缓慢、少量、透视监视、严格无菌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0144", "t": "单选题", "s": "下列属于静脉肾盂造影（IVP）禁忌证的是", "o": {"A": "碘对比剂严重过敏史、严重肝肾功能不全、甲状腺功能亢进未控制、多发性骨髓瘤伴肾功能损害及妊娠", "B": "单侧肾结石", "C": "肾盂积水", "D": "既往肾切除术后随访对侧肾", "E": "无痛性肉眼血尿待查"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-004", "kp": "IVP禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A所列均为公认禁忌：严重碘过敏史者可发生致命性反应；严重肝肾功能不全既显影不佳又易诱发对比剂肾病；未控制的甲亢患者碘负荷可诱发甲状腺危象；多发性骨髓瘤合并肾损害时对比剂可加速管型形成致急性肾衰；妊娠期应避免非必要的电离辐射。此外急性尿路感染活动期、严重心力衰竭也属禁忌或需慎用。【为什么错】B肾结石正是IVP的经典适应证之一，可判断结石与集合系统关系及梗阻程度。C肾盂积水需要IVP明确梗阻部位与分肾功能。D单肾患者虽需谨慎评估肾功能，但并非绝对禁忌。E血尿待查是泌尿系造影最常见的适应证。", "tr": "注意区分“禁忌证”与“需要慎重/需水化准备”的情况：糖尿病服二甲双胍者并非绝对禁忌，而是需按规范暂停用药并评估肾功能。把适应证误认为禁忌证（如肾结石、积水）是本题最常见的错误。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0145", "t": "单选题", "s": "膀胱造影的常规操作，下列不恰当的是", "o": {"A": "经导尿管排空膀胱后注入稀释的对比剂，成人一般约150~300ml，以患者出现膀胱充盈感为度", "B": "常规摄取前后位（中心线向足侧倾斜约10°~15°，经耻骨联合上方射入）及左右斜位", "C": "怀疑膀胱输尿管返流时可行排泄性膀胱尿道造影，在排尿过程中动态观察", "D": "前后位中心线向足侧倾斜的目的是避免耻骨联合与膀胱颈及膀胱下部重叠", "E": "急性下尿路感染期应立即行膀胱造影以明确病因"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-005", "kp": "膀胱造影技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】本题选不恰当项。E错误：急性下尿路感染期属禁忌或需推迟——导尿及注入对比剂可使感染上行扩散，加重病情，应先控制感染后再择期检查。【为什么错】A正确：排空后注入稀释对比剂，量以充盈感为度，过量可致膀胱破裂风险与患者不适。B正确：前后位加双斜位可显示膀胱各壁与输尿管开口区，斜位有助于发现被前后壁重叠掩盖的病变。C正确：排泄性膀胱尿道造影（VCUG）是诊断膀胱输尿管返流与后尿道病变的标准方法，需在排尿动态中观察。D正确：向足侧倾斜可将耻骨联合投影下移，避免遮挡膀胱颈与膀胱底部。", "tr": "急性尿路感染是所有经尿道器械操作（导尿、膀胱造影、逆行肾盂造影、尿道造影）的共同禁忌。命题常用“为尽快明确病因”这类合理化语气掩盖禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0146", "t": "多选题", "s": "关于男性尿道造影，下列描述正确的是", "o": {"A": "逆行尿道造影时患者常取右后斜位（身体与台面成约35°~45°），患侧下肢屈曲外展，使尿道全程展开而不与耻骨、股骨重叠", "B": "逆行法主要显示前尿道（阴茎部与球部），排泄性（顺行）尿道造影更利于显示后尿道（膜部与前列腺部）", "C": "注入对比剂时应缓慢、保持适当压力并在曝光瞬间维持充盈状态", "D": "尿道外伤急性期若需评价尿道连续性，应在严格无菌下轻柔操作，避免暴力插管加重损伤", "E": "为使前后尿道同时最佳显示，只需摄取标准前后位一张即可"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-006", "kp": "男性尿道造影技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A正确：斜位可把弯曲的男性尿道拉直展开，避开耻骨联合与股骨的重叠，是尿道造影必需的体位。B正确：逆行注入时括约肌收缩阻碍对比剂充分进入后尿道，故后尿道显示以排尿期顺行造影为佳，二者常联合应用。C正确：只有在保持充盈的瞬间曝光才能显示狭窄段的真实长度与程度。D正确：外伤后评价尿道连续性是逆行尿道造影的重要适应证，但操作须轻柔无菌，避免造成假道或加重撕裂。【为什么错】E错误：单一前后位时尿道与耻骨、股骨重叠、且弯曲段互相折叠，无法评估全程，必须采用斜位并结合逆行与排泄两种时相。", "tr": "“逆行看前、顺行看后”是本考点的记忆抓手。另注意造影剂宜选水溶性碘对比剂，禁用可能进入海绵体循环的油性对比剂；发现明显外渗应立即停止注射。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0147", "t": "单选题", "s": "子宫输卵管造影（HSG）的最佳检查时机是", "o": {"A": "月经来潮当日", "B": "月经干净后3~7天，且检查前禁性生活", "C": "排卵期当天", "D": "月经前3天", "E": "任何时间均可，无时间限制"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-HSG-001", "kp": "HSG检查时机", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】HSG应安排在月经干净后3~7天内：此时子宫内膜已修复且较薄，不易造成内膜碎片经输卵管逆行进入腹腔或形成假性充盈缺损；同时尚未排卵，避免对早期妊娠的意外照射与对比剂损害。检查前需禁性生活以进一步排除妊娠可能。【为什么错】A月经期宫腔内有血液与内膜脱落，既影响判断又易将内膜与血块推入腹腔、增加感染与子宫内膜异位风险。C排卵期已有受孕可能，且此时操作可能干扰受精与着床。D月经前期内膜增厚，可造成假象且临近月经易出血，同时妊娠风险未除。E忽视妊娠风险与内膜周期变化，是明显错误。", "tr": "时机选择的两条逻辑：一是“避开妊娠可能”，二是“内膜要薄”。此外HSG禁忌包括生殖道急性或亚急性炎症、妊娠、子宫出血、刮宫或分娩后6周内以及碘对比剂过敏。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0148", "t": "案例分析题", "s": "患者女性，30岁，婚后2年未孕，男方精液检查正常，临床拟行子宫输卵管造影评价输卵管通畅性。既往无碘过敏史、无生殖道炎症，末次月经结束已4天。检查中注入对比剂后第一次点片显示子宫腔充盈良好，但双侧输卵管均未显影，患者诉下腹痉挛性疼痛明显。作为技师，下列处理错误的是", "o": {"A": "输卵管不显影可能由痉挛所致，可暂停注射、稍事等待或按医嘱使用解痉药后再次注入并复查", "B": "注入对比剂应缓慢、压力适中，压力过高、速度过快本身即可诱发输卵管痉挛与疼痛，并增加对比剂静脉与淋巴逆流风险", "C": "使用水溶性碘对比剂时，可在注药后约20~30分钟摄延迟片观察盆腔内弥散情况；若使用碘化油则需24小时后复查", "D": "对比剂经输卵管伞端弥散至盆腔、呈涂抹状分布，是输卵管通畅的重要征象", "E": "为迅速判定阻塞，应立即加大注射压力至输卵管显影为止"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-HSG-002", "kp": "HSG操作要点与假性阻塞", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】本题选错误项。E错误：加大压力强行“打通”输卵管可造成输卵管损伤、对比剂经子宫肌层静脉丛与淋巴管逆流入血（使用碘化油时甚至发生肺油栓），并诱发剧痛与迷走神经反射，属严重违规操作。【为什么错】A正确：输卵管痉挛可造成假性阻塞，是HSG最常见的假阳性来源，处理办法为暂停、等待或按医嘱使用解痉药后复查。B正确：注射压力与速度过大既加重疼痛与痉挛，又增加逆流风险。C正确：水溶性对比剂吸收快，20~30分钟延迟片即可观察盆腔弥散；碘化油吸收缓慢，需24小时后复查判断弥散与有无粘连。D正确：伞端溢出并在盆腔内呈涂抹状分布，是输卵管通畅的直接证据。", "tr": "碘化油与碘水的差别是高频考点：碘油显影浓、密度高、观察弥散需24小时，但可致油栓与异物肉芽肿；碘水刺激性较强、显影时间短，需20~30分钟复查，但安全性高、细节佳。牢记“不显影≠阻塞”，痉挛必须先排除。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0149", "t": "单选题", "s": "关于子宫输卵管造影所用对比剂的比较，下列说法正确的是", "o": {"A": "碘化油黏稠度高、显影密度大，充盈缓慢，需在24小时后复查以观察盆腔弥散，但存在油栓与异物肉芽肿风险", "B": "碘化油吸收快，20分钟即可完成弥散观察", "C": "水溶性碘对比剂因黏稠度大而不易通过输卵管，故不推荐使用", "D": "水溶性碘对比剂无任何刺激性，注入后不引起腹痛", "E": "两类对比剂在显影密度、吸收速度与并发症方面基本相同，可任意互换"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-HSG-003", "kp": "HSG对比剂的选择与比较", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】碘化油为油性对比剂，黏稠度高、原子序数高故显影密度大、影像对比强，但通过输卵管缓慢，需在24小时后复查以观察盆腔内弥散是否均匀（判断有无粘连）；其主要风险是进入血管后引起肺油栓，以及长期滞留形成异物肉芽肿。【为什么错】B吸收快的是水溶性对比剂，碘化油吸收极慢，可在盆腔滞留数月。C水溶性对比剂黏稠度低、流动性好，容易通过输卵管，是目前更常用的选择。D水溶性对比剂具有一定高渗性与刺激性，注入后常引起下腹痛或痉挛，说其“无任何刺激性”是绝对化的错误表述。E两者在显影密度、吸收速度、复查时间与并发症谱上差异明显，不可随意互换。", "tr": "复查时间是最容易记混的点：碘水20~30分钟、碘油24小时。另需注意二者的临床取舍——碘油图像对比更强并有文献报道的助孕效应，但安全性以水溶性更优，选择需结合患者状况。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0150", "t": "多选题", "s": "关于子宫输卵管造影的并发症及其防范，下列说法正确的是", "o": {"A": "对比剂静脉与淋巴逆流多由注射压力过高、内膜损伤或宫腔操作粗暴引起，一旦发现应立即停止注射", "B": "盆腔感染是重要并发症，故检查前须排除生殖道急性与亚急性炎症，并全程严格无菌操作", "C": "部分患者可出现迷走神经反射（面色苍白、出汗、心率减慢、血压下降），需立即停止操作、平卧观察并按需处理", "D": "使用碘化油时可发生肺油栓，与对比剂经损伤的子宫静脉丛进入循环有关", "E": "造影后出现少量阴道流血必为子宫穿孔，须立即手术探查"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-HSG-004", "kp": "HSG并发症与处理", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】A正确：逆流是压力性并发症的共同表现，处理原则是立即停止注射并降低压力。B正确：HSG属侵入性操作，术前炎症筛查与无菌是防止盆腔感染的核心。C正确：宫颈牵拉与宫腔扩张可诱发迷走反射，属常见术中不良反应，应立即停止操作并对症处理。D正确：碘油经内膜创面进入子宫静脉丛后可造成肺油栓，是碘油造影最严重的并发症。【为什么错】E错误：造影后1~2日内少量阴道流血十分常见，多因宫颈钳夹与导管刺激所致，一般无须特殊处理；把它一律等同于子宫穿孔并主张立即手术，既不符合临床实际，也是典型的绝对化错误表述。", "tr": "并发症的共同根源多为“压力过高”和“无菌不严”，防范措施围绕这两点展开。要区分常见轻微反应（少量出血、下腹隐痛）与需紧急处理的情况（剧痛不缓解、大量出血、逆流、过敏性休克）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0151", "t": "单选题", "s": "某医院行IVP时，注射对比剂后7分钟片显示右肾肾盂肾盏清晰显影，左侧肾区始终未见对比剂排泄，30分钟片仍无显影。技师首先应采取的合理措施是", "o": {"A": "加摄延迟片（如60分钟、2小时甚至更长时间），观察左肾是否为延迟显影", "B": "立即判定左肾无功能并结束检查", "C": "追加同等剂量对比剂重新注射", "D": "立即加大腹部压迫力度促使左肾显影", "E": "改为俯卧位并把管电压降至50kV再摄一张"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-007", "kp": "IVP一侧不显影的技术处理", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】一侧肾不显影常见原因包括梗阻性肾积水导致的排泄延迟、肾功能受损、先天缺如或肾动脉病变。技术上首先应做的是延迟摄片：梗阻侧肾常在数小时后出现“渐进性密度增高”的延迟显影，据此可判断梗阻部位与残余功能。仓促结束检查会遗漏关键信息。【为什么错】B在未做延迟片前即下“无功能”结论证据不足。C重复注射既增加对比剂肾病与过敏风险，也不能改变排泄延迟的本质。D加大压迫只影响输尿管滞留，与患侧不排泄无关，且过度压迫有害。E降低管电压至50kV会使腹部穿透严重不足，影像更难判读；俯卧位虽有一定帮助，但不能替代延迟摄片。", "tr": "“不显影”与“延迟显影”必须靠时间来鉴别，这是IVP的核心技术判断。若延迟片仍不显影，应建议改行其他检查（如逆行肾盂造影、超声或CT尿路成像），而不是在IVP上反复追加对比剂。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0152", "t": "案例分析题", "s": "患者女性，48岁，因体检发现右侧输尿管中段可疑结石就诊，拟行静脉肾盂造影。检查当日患者按要求清洁肠道，无碘过敏史，肾功能正常。技师在完成造影前平片后为其静脉注射非离子型碘对比剂，注射约1分钟后患者出现全身荨麻疹、皮肤瘙痒，无喘息、无血压下降、意识清楚。作为在场技师，下列处理错误的是", "o": {"A": "立即停止注射，保留静脉通路，通知医师并密切观察生命体征", "B": "该表现属轻度急性不良反应，应就地观察至少30分钟，警惕向中重度反应进展", "C": "备好肾上腺素、糖皮质激素、抗组胺药、氧气与吸引装置等急救物品与设备", "D": "让患者自行离开检查室回病房观察，以便腾出机房继续下一位患者的检查", "E": "在患者症状缓解且经医师评估后，可择期改用其他检查方法（如超声或CT尿路成像）完成诊断"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-URO-008", "kp": "造影中碘对比剂不良反应的处置", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】本题选错误项。D错误：让刚发生急性不良反应的患者独自离开检查室，等于脱离监护与急救条件，一旦在途中进展为喉头水肿、支气管痉挛或过敏性休克，后果严重；机房周转效率绝不能凌驾于患者安全之上。【为什么错】A正确：出现任何不良反应的第一步都是停止注射并保留静脉通路（后续给药需要），同时通知医师。B正确：单纯荨麻疹、瘙痒而无呼吸循环受累属轻度反应，但存在进展为中重度的可能，须现场留观。C正确：肾上腺素是严重过敏样反应的一线药物，连同糖皮质激素、抗组胺药、氧气与吸引装置均属造影室必备。E正确：本次检查中断后，可依据临床需要改用超声或CT尿路成像等替代方案完成诊断。", "tr": "轻度反应的关键不是“用什么药”，而是“不脱离监护”。同时注意留观时限：注射后30分钟内是急性反应高发期；此外应与迷走反射（心率减慢、血压下降）鉴别，后者处理原则不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0153", "t": "单选题", "s": "关于乳腺头尾位（CC位）摄影的操作要点，下列错误的是", "o": {"A": "抬高乳腺下缘至自然可提升的最高点，使探测器上缘平齐乳腺下皱襞抬起后的水平", "B": "压迫板自上而下压迫，X线自上向下投照", "C": "应尽量包全乳腺内侧组织，同时兼顾外侧，乳头应呈切线位显示于影像中央", "D": "为使外上象限深部组织完整显示，CC位应常规大幅外旋患者躯干并牺牲内侧组织", "E": "摆位时应展平皮肤皱褶，避免皱褶重叠形成伪影"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-001", "kp": "乳腺CC位摄影要点", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】本题选错误项。D错误：标准CC位以“不遗漏内侧组织”为优先原则，因为内侧组织在MLO位上最易被遗漏；若为显示外上象限或腋尾部深部组织，应另行加摄夸大头尾位（XCCL），而不是牺牲标准CC位的内侧包容度。【为什么错】A正确：把乳腺下缘提升到最高点并使探测器与之平齐，可最大限度纳入后部组织。B正确：CC位由上向下压迫、上下方向投照，是其定义。C正确：乳头呈切线（不与腺体重叠）是CC位合格的基本判据之一，同时应尽量显示胸大肌前缘。E正确：皮肤皱褶会形成线状伪影并可能掩盖病变。", "tr": "“标准位求全面、附加位补重点”是乳腺摄影的基本策略：CC位优先保内侧，XCCL补外侧腋尾，乳沟位（CV）补内侧深部。用附加位的目标去改造标准位，是常见的思路错误。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0154", "t": "多选题", "s": "关于乳腺内外斜位（MLO位）的角度选择与合格标准，下列正确的是", "o": {"A": "探测器（压迫方向）与水平面所成角度一般在30°~60°之间，需根据受检者体型调整，使其与胸大肌走行方向平行", "B": "体型高瘦、胸大肌较陡直者宜选用较大角度（接近60°），矮胖者宜选用较小角度（接近30°~45°）", "C": "合格的MLO位应显示胸大肌，且其下缘至少达到乳头后线（PNL）水平，胸大肌前缘呈凸出状", "D": "合格的MLO位应显示乳腺下皱襞（IMF）自然展开、乳头呈切线位，且无皮肤皱褶重叠", "E": "MLO位角度固定为45°，任何体型均不应调整"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-002", "kp": "MLO位角度与合格标准", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】A、B正确：MLO位的角度选择原则是让压迫方向与该受检者的胸大肌走行平行，这样才能把最多的后部与上部腺体纳入影像；瘦高者胸大肌陡直取大角度，矮胖者胸大肌平坦取小角度，故常规范围为30°~60°而非固定值。C正确：胸大肌显示至乳头后线水平且前缘凸出，是判定后部组织包含是否充分的核心指标。D正确：下皱襞展开说明下部组织未被折叠遗漏，乳头切线位说明未被腺体遮盖，无皮肤皱褶说明压迫与铺展到位。【为什么错】E错误：把角度固定为45°而不考虑体型，会导致胸大肌显示不足或腺体后缘遗漏，是典型的教条化错误。", "tr": "MLO位是全乳腺摄影中显示组织量最大的体位，其质量评价重点全在“后部与下部有没有包全”：看胸大肌是否达PNL、下皱襞是否展开。仅凭“图像清楚”判断合格是不够的。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0155", "t": "多选题", "s": "关于乳腺X线摄影附加体位的适应证，下列匹配正确的是", "o": {"A": "局部加压点压位（spot compression）：用于鉴别标准位上可疑的“结构扭曲或肿块”是否为正常腺体重叠所致，通过局部加压使组织分离展开", "B": "放大位：常与点压联合使用，采用微焦点、不使用滤线栅，主要用于评价微钙化的形态、数目与分布", "C": "乳沟位（CV位）：双侧乳腺同时摆位，用于显示乳腺内侧深部（近胸壁内侧）病变", "D": "切线位（TAN）：用于确认可疑病变是否位于皮肤内或皮下，如皮肤钙化", "E": "上述附加体位信息量更大，可直接替代标准CC位与MLO位，从而减少摄影次数与剂量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-003", "kp": "乳腺附加体位的适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (2)乳腺附加体位", "ex": "【为什么对】A正确：点压把局部组织压得更薄更分散，若“病灶”随之消散则为腺体重叠所致，若持续存在则提示真实病变，是鉴别的关键手段。B正确：放大位需用0.1mm级微焦点以保证分辨力，并采用空气间隙技术而不用滤线栅以避免剂量过高，是评估微钙化的标准做法。C正确：乳沟位把双乳同时拉向探测器中央，专门解决内侧深部区域在常规位上易遗漏的问题。D正确：切线位让可疑钙化投影到皮肤轮廓线上，从而确认其位于皮肤而非腺体内，可避免不必要的活检。【为什么错】E错误：附加体位都是针对特定问题的“补充”，其覆盖范围有限（如XCCL牺牲内侧、点压仅局部、放大位仅小视野），无法提供全乳腺的整体信息，因而只能在标准CC位与MLO位基础上加做，绝不能替代标准位。", "tr": "附加体位的选择逻辑是“缺什么补什么”：位置显示不全用XCCL/CV，性质难定用点压，钙化细节用放大，皮肤定位用切线；但它们始终是标准两位的补充。放大位不用滤线栅这一点尤其容易记反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0156", "t": "单选题", "s": "乳腺X线摄影中使用压迫的目的，下列描述错误的是", "o": {"A": "减小乳腺厚度，降低所需曝光量与辐射剂量", "B": "使腺体组织展开分离，减少重叠对病变的掩盖", "C": "固定乳腺，减少运动模糊", "D": "减少散射线，提高影像对比度", "E": "增大物-片距，从而提高微钙化的空间分辨力"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-004", "kp": "乳腺压迫的作用", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】本题选错误项。E错误：压迫的效果恰恰是把乳腺压薄、使组织尽量贴近探测器，从而减小物-片距、降低几何模糊与放大；“增大物-片距”与压迫的物理效果相反。只有在专门的放大摄影中才刻意抬高乳腺、增大物-片距（空气间隙技术），且必须配合微焦点。【为什么错】A、B、C、D均为压迫的经典作用：厚度减小则透射增加、剂量下降；组织展开可减少重叠所致的假阴性与假阳性；固定可消除运动模糊；被照体积减小则散射线减少、对比度提高。", "tr": "压迫的四大作用（薄、散、稳、展）需与放大摄影的原理区分开：常规摄影靠“贴近探测器”求清晰，放大摄影靠“抬离探测器+微焦点”求放大，二者的物-片距策略完全相反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0157", "t": "单选题", "s": "某受检者MLO位影像显示乳腺下部组织折叠成角、下皱襞未展开，胸大肌下缘明显高于乳头后线水平。最可能的原因是", "o": {"A": "压迫板角度与受检者胸大肌走行不匹配，且摆位时未将乳腺充分上提外拉，导致后下部组织遗漏", "B": "曝光量不足", "C": "焦-片距过短", "D": "使用了微焦点", "E": "未使用滤线栅"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-005", "kp": "MLO位质量缺陷的原因分析", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】胸大肌下缘未达乳头后线、下皱襞未展开、下部组织折叠，这三条同时出现，指向的是同一类问题——摆位不当：角度未与该受检者胸大肌走行平行（常见于角度过大或过小），且未将乳腺充分向上向外提拉后再压迫，导致后下部腺体没有被纳入并在下缘堆叠成角。纠正办法是重新评估体型、调整机架角度，并在压迫过程中用手托住并上提乳腺、展平皱褶。【为什么错】B曝光不足表现为影像整体噪声大、腺体致密区穿透不足，不会改变胸大肌位置与组织折叠。C焦-片距在乳腺机上固定，且只影响放大与清晰度。D微焦点用于放大摄影，与组织包含范围无关。E乳腺摄影是否用滤线栅影响的是散射与对比度，同样不影响解剖包含。", "tr": "解决影像问题前先分类：“包含范围/结构关系”类缺陷几乎都源于摆位与角度；“密度/噪声/对比”类缺陷才考虑曝光参数与滤线栅。把摆位问题归因于曝光参数，会导致反复重拍并增加受检者剂量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0158", "t": "多选题", "s": "关于乳腺导管造影，下列描述正确的是", "o": {"A": "主要适应证为病理性乳头溢液（血性或浆液性），用以显示导管内占位、扩张与走行", "B": "操作时先找到溢液导管开口，用钝头细针缓慢插入并注入少量水溶性碘对比剂（通常0.1~1.0ml左右）", "C": "注射后常规摄取头尾位与内外斜位，必要时加摄放大位以观察细小充盈缺损", "D": "注入量应以患者出现明显胀痛为限，量越大导管显示越完整", "E": "急性乳腺炎、乳头及乳晕区皮肤感染者不宜进行该检查"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-006", "kp": "乳腺导管造影技术", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (3)乳腺造影技术", "ex": "【为什么对】A正确：病理性乳头溢液是导管造影的核心适应证，可定位导管内乳头状瘤等病变。B正确：须使用钝头针以免刺破导管形成假道，注入量以少量为宜。C正确：造影后按标准CC与MLO位摄影，放大位有助于观察细小充盈缺损与导管壁不规则。E正确：局部急性炎症或感染时操作可致感染扩散，属禁忌。【为什么错】D错误：以“明显胀痛”为注入终点是危险且错误的——胀痛提示导管过度扩张甚至有破裂、对比剂外渗风险，正确做法是缓慢注入少量对比剂，出现胀感即停止。", "tr": "凡是把“患者疼痛”当作操作终点的选项，在造影类题目中基本都是错误项（HSG、逆行肾盂造影、导管造影同理）。此外要注意造影前不要过度挤压排空溢液，否则可能找不到溢液导管开口。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0159", "t": "单选题", "s": "口内根尖片分角线投照技术的原理是", "o": {"A": "中心线垂直于牙长轴与探测器（胶片）平面所构成夹角的角平分线，以使牙齿影像长度接近实际长度", "B": "中心线垂直于探测器平面，不考虑牙长轴方向", "C": "中心线平行于牙长轴射入", "D": "中心线垂直于牙长轴，探测器与牙长轴垂直放置", "E": "中心线与探测器成45°固定角射入，各牙位相同"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-DEN-001", "kp": "根尖片分角线投照技术原理", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】受口腔解剖（腭穹隆、口底）限制，探测器往往不能与牙长轴平行放置，二者之间形成一定夹角。分角线技术依据等腰三角形原理，令中心线垂直通过该夹角的角平分线，使投影所得牙影长度最接近牙的真实长度，从而减少影像的伸长或缩短。各牙位因牙长轴倾斜不同，垂直角需相应调整（上颌切牙约+40°，上颌磨牙约+20°，下颌切牙约-15°，下颌磨牙约-5°，具体依个体调整）。【为什么错】B不考虑牙长轴会造成影像明显伸长或缩短。C中心线平行于牙长轴则无法在探测器上成像。D是对分角线原理的错误改写，探测器与牙长轴垂直不符合口内放置的实际。E各牙位垂直角不同，固定45°必然造成失真。", "tr": "牢记失真规律：中心线垂直角过大（过于向牙长轴方向倾斜）导致影像缩短，垂直角过小导致影像伸长；水平角不当则造成邻面影像重叠。分角线法操作简便但失真难以完全避免，精确评价牙周骨水平应首选平行投照法。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0160", "t": "案例分析题", "s": "患者男性，45岁，慢性牙周炎，口腔科需精确评价下颌后牙区牙槽骨吸收水平并作治疗前后对比，要求影像失真最小、可重复性好。患者张口度正常、无明显咽反射。放射科可提供口内根尖片（分角线法与平行投照法均可）及全口牙位曲面体层片（全景片）。作为技师，下列判断错误的是", "o": {"A": "应首选平行投照法（长遮线筒法）：探测器借助持片器与牙长轴平行放置，中心线垂直于二者，影像失真最小、重复性好", "B": "平行投照法需加大焦-片距（约20~40cm）以补偿探测器与牙之间的距离所致的放大", "C": "分角线法虽操作简便、患者易配合，但因中心线成角与个体差异，影像易伸长或缩短，不利于精确测量牙槽骨高度", "D": "全景片可一次显示全口牙列与颌骨，适合总体观察与筛查，但存在放大率不均、颈椎影重叠与细节分辨力不足，不宜替代根尖片作精细测量", "E": "全景片各部位放大率恒定且细节分辨力高，测量牙槽骨吸收水平的精度优于口内根尖片，本例应直接选用全景片"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-DEN-002", "kp": "平行投照法、分角线法与全景片的选择", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】本题选错误项。E错误：全景片属曲面体层成像，不同深度层面的放大率并不恒定（水平方向与垂直方向放大率还常不一致），且存在颈椎与对侧颌骨的重叠伪影、空间分辨力低于口内片，因而不适合作牙槽骨高度的精确测量与治疗前后对比；本例应选平行投照法的根尖片。【为什么错】A正确：平行投照法用持片器把探测器固定在与牙长轴平行的位置，中心线垂直入射，牙冠-牙根比例与牙槽嵴高度还原度最好，是牙周评估与随访对比的首选。B正确：探测器远离牙面会带来放大，加大焦-片距（约20~40cm，配长遮线筒）使X线趋于平行，可有效抑制放大与半影。C正确：分角线法依赖角度估计，个体差异与操作者经验会造成影像伸长或缩短，测量可比性差。D正确：全景片可一次显示全口牙列与颌骨，适合总体观察与筛查。", "tr": "选择检查方法应回到临床目的：要“测量与对比”选平行投照法，要“整体筛查与颌骨全貌”选全景片，要“快速便捷、患者难配合”才退而求其次用分角线法。切勿因全景片信息量大就误认为其精度也最高。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-0161", "t": "多选题", "s": "关于口腔X线摄影的基本知识，下列说法正确的是", "o": {"A": "口内根尖片主要用于显示单个或数个牙的牙冠、牙根、根尖周组织及邻近牙槽骨", "B": "咬合片（𬌗翼片/咬合翼片）主要用于显示上下颌后牙的邻面龋与牙槽嵴顶", "C": "全口牙位曲面体层片（全景片）可一次显示上下颌骨、全口牙列及双侧颞下颌关节区", "D": "口腔摄影中应对受检者使用铅围裙（必要时含甲状腺屏蔽）进行防护", "E": "口内片的曝光时间以秒计，通常需要100mAs以上的曝光量"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-DEN-003", "kp": "口腔X线摄影的种类与防护", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】A正确：根尖片是口腔最常用的口内片，显示范围为少数牙及其根尖周与牙槽骨。B正确：咬合翼片重点显示上下后牙的牙冠邻面与牙槽嵴顶，是邻面龋与早期牙周骨吸收的敏感检查。C正确：全景片一次成像即可覆盖上下颌骨、全口牙列与双侧髁突区，适合整体评估。D正确：虽然口腔摄影单次剂量很低，但仍应遵循防护最优化，对受检者尤其儿童与孕妇使用铅围裙与甲状腺屏蔽。【为什么错】E错误：口内片属超低剂量摄影，管电流通常仅数毫安至十毫安级、曝光时间常为零点几秒，总曝光量远低于100mAs；把躯干摄影的曝光量套用到口内片是量级性错误。", "tr": "口腔摄影“剂量低”不等于“不需防护”，两者不可互相推导。另注意区分口内片的三种类型（根尖片、咬合翼片、𬌗片）与口外片（全景片、头影测量片）的适用范围。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-0162", "t": "多选题", "s": "关于乳腺X线摄影的设备与曝光技术，下列说法正确的是", "o": {"A": "乳腺X线管常采用钼、铑或钨靶配合相应滤过板，以获得适合乳腺软组织成像的低能X线束", "B": "乳腺摄影常规使用小焦点（约0.3mm），放大摄影时使用微焦点（约0.1mm）", "C": "自动曝光控制（AEC）可依据乳腺厚度与腺体密度自动确定曝光条件，是保证影像质量一致性的重要手段", "D": "放大摄影时采用空气间隙技术而不使用滤线栅，以避免剂量过度增加", "E": "乳腺摄影管电压通常设置在80~100kV，以增强穿透力"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-MAM-007", "kp": "乳腺摄影设备与曝光技术", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】A正确：乳腺内各软组织的原子序数与密度差异极小，只有低能（约17~25keV）准单能X线才能形成足够对比，故采用钼/铑/钨靶与匹配滤过板的组合。B正确：常规摄影用0.3mm级小焦点保证清晰度，放大摄影因几何模糊被放大，必须改用0.1mm级微焦点。C正确：AEC依据探测到的透过量自动终止曝光，可使不同厚度与密度的乳腺获得稳定一致的影像密度，减少重拍。D正确：放大摄影时乳腺被抬离探测器形成空气间隙，散射线大多不能到达探测器，此时再加滤线栅只会大幅增加剂量而收益有限。【为什么错】E错误：80~100kV是躯干摄影的范围；乳腺摄影管电压通常仅约25~35kV，过高的kV会使软组织对比度急剧下降，完全丧失乳腺成像的意义。", "tr": "乳腺摄影的所有参数都围绕“低能量、高对比、高分辨力”这一主线：低kV、小/微焦点、专用靶-滤过组合、压迫减薄。任何“提高kV增强穿透”的表述在乳腺场景中都是错误方向。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1001", "t": "单选题", "s": "关于X线摄影影像放大效应的叙述，错误的是", "o": {"A": "被检部位距探测器越远，影像放大越明显", "B": "被检部位应尽量贴近探测器", "C": "焦片距越大，放大越小", "D": "放大效应不影响影像的清晰度", "E": "缩小物片距可减少放大失真"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-001", "kp": "影像放大效应与物片距", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】放大效应会使影像边界模糊、空间分辨率下降，必然影响影像清晰度与锐利度，故D项“不影响清晰度”的说法错误，本题选D。\n【为什么错】A：物片距（被检部位至探测器距离）越大，几何放大越明显，正确。B：贴近探测器可缩小物片距而减少放大，正确。C：焦片距增大时放大率＝焦片距/（焦片距－物片距）趋近于1，放大减小，正确。E：缩小物片距即减少放大失真，正确。", "tr": "放大率取决于“物片距与焦片距的比例”，远距离摄影（如胸部180cm）与贴近探测器是减少放大的两个途径。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1002", "t": "单选题", "s": "胸部X线摄影通常采用远距离摄影，其焦片距（SID）一般为", "o": {"A": "75cm", "B": "90cm", "C": "100cm", "D": "150cm", "E": "180cm"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-002", "kp": "胸部远距离摄影焦片距", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】胸部正位为减小心脏等器官的放大失真，采用180cm远距离摄影（SID＝180cm），故E正确。\n【为什么错】A、B、C：75~100cm为四肢与躯干多数部位的常规焦片距。D：150cm非胸部常规标准。", "tr": "胸部180cm、四肢及普通部位100cm是经典数值考点，勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1003", "t": "单选题", "s": "X线摄影前去除被检部位金属饰物、膏药等异物的主要目的是", "o": {"A": "防止损坏X线机", "B": "避免高密度异物产生伪影而漏诊误诊", "C": "缩短曝光时间", "D": "降低患者辐射剂量", "E": "便于体表定位标记"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-003", "kp": "摄影前异物去除的目的", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (1)体位注意事项", "ex": "【为什么对】金属饰物、膏药中的金属粉末等高密度物在X线片上形成高密度伪影，可遮盖病灶或模拟病变导致漏诊误诊，故摄影前必须去除，B正确。\n【为什么错】A：异物不会损坏X线机。C：异物不影响曝光时间设定。D：去除异物与患者剂量无直接关系。E：去除异物与体表定位无关。", "tr": "关键词为“伪影”；含金属成分的衣物、饰物、膏药、创可贴等均须在摄影前去除。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1004", "t": "单选题", "s": "头颅后前位X线摄影时，中心线的入射点为", "o": {"A": "枕外隆凸", "B": "眉间", "C": "外耳孔", "D": "鼻尖", "E": "颏部"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-004", "kp": "头颅后前位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】头颅后前位中心线经枕外隆凸垂直射入探测器中心（射达眉间方向），使颅骨前后投影对称居中，故A正确。\n【为什么错】B：眉间是中心线射达的对应部位而非入射点。C：外耳孔是头颅侧位的定位标志。D、E与头颅后前位中心线无关。", "tr": "区分“入射点（枕外隆凸）”与“射出方向/对应部位（眉间）”；头颅侧位中心线才经外耳孔上方。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1005", "t": "单选题", "s": "头颅后前位摄影要求正中矢状面、听眦线均垂直探测器，其主要目的是", "o": {"A": "显示颅底结构", "B": "保持左右对称，避免颅骨倾斜变形", "C": "减小几何放大", "D": "使颞骨岩部投影于眼眶内", "E": "显示蝶鞍形态"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-005", "kp": "头颅正位体位标准的意义", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】正中矢状面垂直保证左右结构对称，听眦线垂直保证头颅不前后倾斜，两者共同使正位影像标准、失真最小，故B正确。\n【为什么错】A：显示颅底结构需汤氏位等特殊体位。C：减小放大多通过贴近探测器与远距离摄影。D：颞骨岩部投影于眼眶是梅氏位等特殊投照的表现。E：蝶鞍显示以头颅侧位为佳。", "tr": "“矢状面垂直”防左右倾斜，“听眦线垂直”防前后倾斜，是头颅正位两项核心要求。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1006", "t": "单选题", "s": "头颅侧位X线摄影时，中心线的入射点为", "o": {"A": "外耳孔上方约2.5cm（蝶鞍区）", "B": "眉间", "C": "枕外隆凸", "D": "鼻根", "E": "下颌角"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-006", "kp": "头颅侧位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】头颅侧位中心线经外耳孔上方约2.5cm（即蝶鞍区）垂直射入，可同时显示颅骨侧位全貌及蝶鞍，故A正确。\n【为什么错】B：眉间为头颅前后位中心线方向。C：枕外隆凸为头颅后前位入射点。D：鼻根为副鼻窦柯氏位定位标志。E：下颌角与头颅侧位中心线无关。", "tr": "头颅侧位中心线“外耳孔上2.5cm经蝶鞍”，是鞍区与颅骨侧位检查的固定考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1007", "t": "单选题", "s": "头颅汤氏位（Townes位）摄影时中心线的投照要求为", "o": {"A": "垂直射入", "B": "向头侧倾斜30°", "C": "向足侧倾斜30°", "D": "向足侧倾斜45°", "E": "向头侧倾斜15°"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-007", "kp": "汤氏位中心线投照方向", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位患者仰卧、听眦线垂直探测器，中心线向足侧倾斜30°经枕外隆凸下方射入（射达眉间方向），使枕骨、枕骨大孔、颞骨岩部及内听道充分展开显示，故C正确。\n【为什么错】A：垂直射入为正位要求。B：向头侧倾斜为骶尾椎等体位的方向。D：45°倾斜为梅氏位等特点。E：15°倾斜为柯氏位等特点。", "tr": "汤氏位“向足侧倾斜30°”，方向是足侧而非头侧，易与骶尾椎（向头侧倾斜）混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1008", "t": "单选题", "s": "汤氏位（Townes位）主要显示的结构不包括", "o": {"A": "枕骨", "B": "枕骨大孔", "C": "颞骨岩部", "D": "内听道", "E": "蝶鞍"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-008", "kp": "汤氏位显示范围", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位用于观察枕骨、枕骨大孔、颞骨岩部及内听道等后颅窝结构，蝶鞍位于颅底中央前部，常规以头颅侧位显示，故E为本题答案。\n【为什么错】A、B、C、D均为汤氏位重点显示结构，叙述正确。", "tr": "“汤氏位＝后颅窝（枕骨、枕骨大孔、岩部、内听道）”，蝶鞍是侧位和鞍区检查的重点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1009", "t": "单选题", "s": "副鼻窦柯氏位（Caldwell位）主要显示的窦腔是", "o": {"A": "上颌窦", "B": "额窦及筛窦", "C": "蝶窦", "D": "后组筛窦", "E": "乳突气房"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-009", "kp": "柯氏位显示范围", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】柯氏位（鼻额位）患者前额及鼻尖贴近探测器、听眦线垂直，中心线向足侧倾斜15°~20°经鼻根射入，主要显示额窦、筛窦及眼眶，故B正确。\n【为什么错】A：上颌窦由瓦氏位（顶颏位）显示。C：蝶窦需用头颅侧位等专用体位。D：后组筛窦显示仍需结合其他体位。E：乳突气房属乳突摄影范畴。", "tr": "“额窦筛窦看柯氏位、上颌窦看瓦氏位”，是副鼻窦摄影的高频鉴别考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1010", "t": "单选题", "s": "副鼻窦瓦氏位（Water位/顶颏位）摄影时，听眦线与探测器平面的夹角为", "o": {"A": "15°", "B": "23°", "C": "37°", "D": "45°", "E": "90°"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-010", "kp": "瓦氏位听眦线角度", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】瓦氏位（顶颏位）患者颏部贴探测器、头部后仰，使听眦线与探测器平面成37°角，中心线经鼻尖（或鼻尖与上唇间）垂直射入，主要显示上颌窦，故C正确。\n【为什么错】A、B：15°~20°为柯氏位倾斜范围。D：45°为腰椎斜位等体位特点。E：90°即垂直，为常规正位体位。", "tr": "瓦氏位听眦线“37°”是标志性数值，与柯氏位15°~20°倾斜方向不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1011", "t": "单选题", "s": "胸部后前位X线摄影时，中心线的入射点为", "o": {"A": "第4胸椎", "B": "第6胸椎", "C": "第7胸椎", "D": "胸骨角", "E": "第2胸椎"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-011", "kp": "胸部后前位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸部后前位中心线经第6胸椎垂直射入探测器中心（约平两侧肩胛下角连线水平），故B正确。\n【为什么错】A：第4胸椎约平胸骨角。C：第7胸椎为胸椎正位中心线常用水平。D：胸骨角为胸部前弓位中心线定位标志。E：第2胸椎位于上纵隔上方。", "tr": "胸部后前位中心线“经第6胸椎”是固定数值考点，正、侧位均在第6胸椎水平。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1012", "t": "单选题", "s": "胸部后前位摄影时嘱患者双手背置于髋部、肘部内旋，其主要目的是", "o": {"A": "减少胸部呼吸运动", "B": "使肩胛骨向外展开，不与肺野重叠", "C": "增加胸腔前后径", "D": "使锁骨抬高", "E": "便于探测器定位"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-012", "kp": "胸部后前位双上肢摆位目的", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】双手背置髋部并肘部内旋，使肩胛骨向外、向前移开，避免肩胛骨投影与肺野重叠，保证肺野充分显示，故B正确。\n【为什么错】A：减少呼吸运动靠深吸气后屏气。C：双手姿势不改变胸腔前后径。D：锁骨抬高是前弓位的作用。E：与探测器定位无关。", "tr": "“手背置髋、肘内旋、肩胛骨外展”是胸部正位标准摆位，肩胛骨重叠是常见质量缺陷。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1013", "t": "单选题", "s": "胸部侧位X线摄影时，中心线的入射点为", "o": {"A": "第6胸椎高度的腋中线", "B": "第4胸椎高度的腋前线", "C": "第7胸椎高度的腋后线", "D": "胸骨角水平", "E": "剑突水平"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-013", "kp": "胸部侧位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸部侧位患者患侧贴近探测器、两臂上举，中心线经第6胸椎高度的腋中线水平射入，故A正确。\n【为什么错】B：腋前线偏前，不能使两肺及纵隔居中。C：腋后线偏后。D：胸骨角平第4胸椎，非侧位中心线。E：剑突水平偏低，会使心尖及膈肌显示不全。", "tr": "胸部正侧位中心线均经“第6胸椎”水平，侧位为水平投照经腋中线。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1014", "t": "单选题", "s": "临床怀疑肺尖部或锁骨下区病变（如肺尖结核、Pancoast瘤）时，宜选用的胸部特殊体位是", "o": {"A": "胸部侧位", "B": "胸部前弓位（前凸位）", "C": "右前斜位", "D": "标准后前位", "E": "左前斜位"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-014", "kp": "胸部前弓位适应证", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】前弓位（前凸位）患者身体后仰、肩背部贴近探测器，使锁骨投影上移、肺尖部展开，可更充分显示肺尖及锁骨下区病变，故B正确。\n【为什么错】A：侧位用于定位及纵隔观察。C、E：斜位用于心脏大血管观察。D：标准后前位锁骨与肺尖重叠较多，肺尖显示受限。", "tr": "前弓位＝“后仰、锁骨头抬高”，专用于肺尖及锁骨下区；标准后前位肺尖常被锁骨遮挡。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1015", "t": "单选题", "s": "胸部正位采用180cm焦片距远距离摄影的主要目的是", "o": {"A": "增大X线输出量", "B": "减小心脏等器官的放大失真", "C": "提高影像对比度", "D": "缩短曝光时间", "E": "减少散射线产生"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-015", "kp": "胸部远距离摄影意义", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】心脏位于胸腔前半部、距探测器较远，放大明显；采用180cm远距离摄影使心影放大率减小，心影大小更接近真实，便于心影测量与比较，故B正确。\n【为什么错】A：远距离摄影不增加X线输出量。C：对比度主要取决于kVp与散射线控制。D：焦片距增大需增加曝光条件而非缩短时间。E：散射线减少不是远距离摄影的主要目的。", "tr": "“远距离摄影减小放大”是核心；剂量、对比度非其主要调控目标。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1016", "t": "单选题", "s": "腹部仰卧前后位（泌尿系平片KUB）X线摄影时，中心线的入射点为", "o": {"A": "剑突与耻骨联合连线中点", "B": "脐上3cm", "C": "剑突", "D": "耻骨联合上缘", "E": "脐下3cm"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-016", "kp": "腹部平片中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】腹部仰卧前后位中心线经剑突与耻骨联合连线中点（约脐水平）垂直射入，可较完整显示双肾、输尿管及膀胱区域，故A正确。\n【为什么错】B：脐上3cm为腰椎正位中心线。C：剑突水平偏上。D：耻骨联合上缘为骨盆正位中心线。E：脐下3cm偏低。", "tr": "腹部平片“剑突－耻骨联合连线中点”，腰椎正位“脐上3cm”，二者勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1017", "t": "单选题", "s": "临床疑消化道穿孔，为观察膈下游离气体，首选的X线摄影是", "o": {"A": "腹部仰卧前后位", "B": "立位（半坐位）腹部平片", "C": "腹部侧位", "D": "腹部斜位", "E": "腹部俯卧后前位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-017", "kp": "立位腹部平片适应证", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】游离气体比重小、随体位上升，立位或半坐位水平投照时气体集聚于膈下肝顶与膈肌之间，呈新月形透亮影，故B正确。\n【为什么错】A：仰卧位气体聚于前腹壁下，与肠腔气体混杂难以分辨。C、D：侧位、斜位非游离气体首选。E：俯卧位更不利于游离气体显示。", "tr": "“膈下游离气体必用立位/半坐位水平投照”，卧位平片极易漏诊。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1018", "t": "单选题", "s": "腰椎正位（前后位）X线摄影时，中心线的入射点为", "o": {"A": "脐上3cm（约第3腰椎）", "B": "脐", "C": "两侧髂嵴连线中点", "D": "耻骨联合上缘", "E": "剑突"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-018", "kp": "腰椎正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎正位中心线经脐上3cm（约平第3腰椎）垂直射入，使上至T12、下至骶椎的腰椎序列居中显示，故A正确。\n【为什么错】B：脐水平略偏低。C：髂嵴连线平第4腰椎。D：耻骨联合上缘为骨盆正位中心线。E：剑突过高。", "tr": "“腰椎正位中心线脐上3cm”是高频数值，需与腹部平片（剑突－耻骨联合中点）区别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1019", "t": "单选题", "s": "关于腰椎正位摄影的体位与准备，错误的是", "o": {"A": "患者仰卧，正中矢状面垂直摄影台面", "B": "两髋、膝关节屈曲，使腰椎贴近台面", "C": "中心线经脐上3cm垂直射入", "D": "嘱患者屏气后曝光", "E": "中心线向头侧倾斜15°射入"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-019", "kp": "腰椎正位摄影要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎正位中心线应垂直射入，向头侧倾斜15°是骶尾椎正位的投照要求，故E错误，本题选E。\n【为什么错】A：仰卧并保持矢状面垂直保证左右对称，正确。B：髋膝屈曲使腰椎生理前凸变直、贴近台面，正确。C：中心线经脐上3cm，正确。D：屏气防止呼吸运动模糊，正确。", "tr": "腰椎正位“垂直”，倾斜投照的是骶尾椎正位（头侧倾斜15°~20°）与腰椎斜位（体位旋转45°）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1020", "t": "单选题", "s": "腰椎斜位（前斜位约45°）X线摄影主要显示的结构是", "o": {"A": "椎体前缘", "B": "椎弓峡部", "C": "椎间孔", "D": "棘突", "E": "横突"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-020", "kp": "腰椎斜位显示结构", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎斜位使椎体旋转约45°，椎弓峡部投影展开呈“狗形”（狗眼＝椎弓根，狗颈＝峡部），用于诊断椎弓峡部裂及腰椎滑脱，故B正确。\n【为什么错】A：椎体前缘正位及侧位即可观察。C：椎间孔以颈椎斜位显示为主。D：棘突在正位上显示。E：横突正位显示。", "tr": "“狗颈即峡部”，峡部断裂时狗颈中断，是腰椎滑脱的关键征象。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1021", "t": "单选题", "s": "寰枢椎张口位（开口位）X线摄影时，中心线的入射点为", "o": {"A": "上颌中切牙与枕外隆凸连线中点（经口腔）", "B": "甲状软骨", "C": "下颌角", "D": "舌骨", "E": "口角"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-021", "kp": "寰枢椎张口位中心线", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】张口位患者仰卧尽量张口，中心线经口腔（上颌中切牙与枕外隆凸连线中点）垂直射入，使上下颌骨投影分开、寰枢椎清晰显示，故A正确。\n【为什么错】B：甲状软骨为颈椎正侧位的定位标志。C、D、E均非张口位中心线定位点。", "tr": "张口位中心线必须“经口腔垂直射入”；患者未真正张口则寰枢椎被上下颌骨遮挡。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1022", "t": "单选题", "s": "骨盆正位X线摄影时，中心线的入射点为", "o": {"A": "两侧髂前上棘连线中点与耻骨联合上缘连线中点（约耻骨联合上缘）", "B": "脐", "C": "髋臼中心", "D": "尾骨", "E": "髂嵴"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-022", "kp": "骨盆正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】骨盆正位中心线经两侧髂前上棘连线中点与耻骨联合上缘连线的中点（约耻骨联合上缘）垂直射入，使双侧髋骨、股骨颈及骶尾椎对称显示，故A正确。\n【为什么错】B：脐为腰椎正位邻近区域。C：髋臼中心偏上。D：尾骨仅为定位参考。E：髂嵴过高。", "tr": "骨盆正位中心线“约耻骨联合上缘”，同时要求两足内旋约15°使股骨颈充分展开。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1023", "t": "单选题", "s": "骶尾椎正位X线摄影时，中心线的投照要求为", "o": {"A": "垂直射入", "B": "向头侧倾斜15°~20°，经耻骨联合上缘射入", "C": "向足侧倾斜15°~20°，经耻骨联合射入", "D": "向头侧倾斜30°", "E": "向足侧倾斜45°"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-023", "kp": "骶尾椎正位中心线投照", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】骶尾椎正位中心线向头侧倾斜15°~20°，经耻骨联合上缘射入，使骶尾椎投影上移展开、避免与耻骨重叠，故B正确。\n【为什么错】A：垂直射入会使骶尾椎与耻骨重叠、影像缩短。C：方向相反。D、E：角度及方向均不符。", "tr": "骶尾椎正位“向头侧倾斜”与汤氏位“向足侧倾斜30°”方向相反，是经典易混点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1024", "t": "单选题", "s": "手正位X线摄影时，中心线的入射点为", "o": {"A": "第三掌骨头", "B": "腕关节", "C": "第一掌骨基底部", "D": "中指末节", "E": "第二指间关节"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-024", "kp": "手正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】手正位中心线经第三掌骨头垂直射入，使全手及腕关节影像居中对称，故A正确。\n【为什么错】B：腕关节正位才经尺桡骨茎突连线中点。C：第一掌骨基底部偏桡侧。D：中指末节过远。E：第二指间关节偏内。", "tr": "手正位中心线“第三掌骨头”；腕关节正位是“尺桡骨茎突连线中点”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1025", "t": "单选题", "s": "腕关节正位X线摄影时，中心线的入射点为", "o": {"A": "尺桡骨茎突连线中点", "B": "第三掌骨头", "C": "舟骨", "D": "桡骨远端", "E": "月骨"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-025", "kp": "腕关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】腕关节正位中心线经尺桡骨茎突连线中点垂直射入，即腕关节间隙中心，可清晰显示腕骨及桡尺关节，故A正确。\n【为什么错】B：第三掌骨头为手正位中心线。C：舟骨为局部结构，非中心线定位点。D、E：桡骨远端、月骨均为部分结构。", "tr": "腕关节正位中心线“茎突连线中点”；疑舟骨骨折需加照尺偏位（舟骨位）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1026", "t": "单选题", "s": "疑腕舟骨骨折时，采用尺偏位（舟骨位）摄影，中心线的投照要求为", "o": {"A": "垂直射入舟骨", "B": "经桡骨茎突向尺侧倾斜约20°射入", "C": "向桡侧倾斜20°射入", "D": "向头侧倾斜45°", "E": "向足侧倾斜30°"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-026", "kp": "舟骨位中心线投照", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】舟骨位（尺偏位）腕关节向尺侧偏转使舟骨长轴展开，中心线经桡骨茎突向尺侧倾斜约20°投照，避免舟骨与邻近腕骨重叠，故B正确。\n【为什么错】A：垂直投照舟骨仍与邻近腕骨重叠。C：方向与尺偏位相反。D、E：角度方向均不符合。", "tr": "舟骨是腕部最易骨折的腕骨，正位易漏诊，“尺偏＋向尺侧倾斜20°”是标准补充体位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1027", "t": "单选题", "s": "肘关节正位X线摄影时，中心线的入射点为", "o": {"A": "肱骨内、外上髁连线中点", "B": "尺骨鹰嘴", "C": "桡骨头", "D": "肘窝上3cm", "E": "肱骨外上髁"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-027", "kp": "肘关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】肘关节正位中心线经肱骨内、外上髁连线中点（肘关节间隙）垂直射入，故A正确。\n【为什么错】B：尺骨鹰嘴偏后。C：桡骨头仅为关节外侧结构。D、E：均非正位标准定位点。", "tr": "肘关节正位中心线“内外上髁连线中点”，侧位中心线经肱骨外上髁。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1028", "t": "单选题", "s": "肩关节正位（前后位）X线摄影时，中心线的入射点为", "o": {"A": "喙突", "B": "肱骨外科颈", "C": "肩峰", "D": "锁骨中点", "E": "肩胛冈"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-028", "kp": "肩关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】肩关节正位中心线经喙突垂直射入，使肱骨头、关节盂及肩锁关节显示清晰，故A正确。\n【为什么错】B：肱骨外科颈为常见骨折部位而非定位点。C：肩峰为肩锁关节组成。D：锁骨中点偏内。E：肩胛冈为背部骨性标志。", "tr": "“喙突”是肩关节正位的核心定位标志；疑肩锁关节分离需加照双肩负重位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1029", "t": "单选题", "s": "膝关节正位X线摄影时，中心线的入射点为", "o": {"A": "髌骨下缘（股胫关节线）", "B": "髌骨上缘", "C": "髌骨中点", "D": "腓骨小头", "E": "胫骨结节"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-029", "kp": "膝关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】膝关节正位中心线经髌骨下缘（股骨与胫骨关节线）垂直射入，使股胫关节间隙充分显示，故A正确。\n【为什么错】B：髌骨上缘偏高。C：髌骨中点偏上。D：腓骨小头为外侧骨性标志。E：胫骨结节偏下。", "tr": "膝关节正位中心线“髌骨下缘（关节线）”，注意与髌骨轴位（经髌股间隙）区别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1030", "t": "单选题", "s": "踝关节正位X线摄影时，中心线的入射点为", "o": {"A": "内、外踝连线中点", "B": "内踝", "C": "外踝", "D": "跟骨", "E": "胫骨下端"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-030", "kp": "踝关节正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】踝关节正位中心线经内、外踝连线中点（胫距关节间隙）垂直射入，故A正确。\n【为什么错】B、C：内踝或外踝单侧定位会使关节偏斜。D：跟骨为足部结构。E：胫骨下端定位不准。", "tr": "踝正位中心线“内外踝连线中点”，踝侧位中心线经内踝。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1031", "t": "单选题", "s": "静脉肾盂造影（IVP）静脉注射对比剂后，常规摄片的时间点为", "o": {"A": "立即、5分钟、10分钟", "B": "7分钟、15分钟、30分钟", "C": "30分钟、60分钟", "D": "15分钟、45分钟", "E": "5分钟、30分钟、60分钟"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-031", "kp": "IVP摄片时间点", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】IVP注药后7分钟肾盏肾盂开始充盈显影，15、30分钟摄片观察充盈及排泄情况，解除腹部加压后再摄全尿路片，故B正确。\n【为什么错】A：5分钟内肾实质尚未充分显影。C、D、E：时间点与常规不符。", "tr": "IVP摄片时间“7、15、30分钟”为固定考点；解除加压后的全尿路片不可遗漏。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1032", "t": "单选题", "s": "下列不属于静脉肾盂造影禁忌证的是", "o": {"A": "碘对比剂过敏", "B": "严重肾功能不全（尿毒症无尿）", "C": "多发性骨髓瘤", "D": "妊娠", "E": "单纯性肾囊肿（对碘剂不过敏、肾功能正常）"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-032", "kp": "IVP禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】单纯性肾囊肿不影响对比剂排泄，不属IVP禁忌，故E正确。\n【为什么错】A：碘过敏可致严重不良反应，禁忌。B：无尿时对比剂无法排泄、加重肾损伤，禁忌。C：多发性骨髓瘤患者用碘对比剂易诱发急性肾功能衰竭，禁忌。D：妊娠为IVP禁忌。", "tr": "“多发性骨髓瘤禁用碘对比剂”与“无尿肾衰禁忌IVP”都是高频考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1033", "t": "单选题", "s": "关于静脉肾盂造影腹部加压的目的与部位，正确的是", "o": {"A": "压迫肾区使肾实质显影", "B": "加压球囊置于髂前上棘连线水平、向骶骨两侧压迫输尿管，使肾盂肾盏充盈", "C": "压迫膀胱使对比剂回流", "D": "压迫下腹部减少散射线", "E": "压迫腹主动脉减慢血流"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-033", "kp": "IVP腹部加压技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】加压球囊置于两侧髂前上棘连线水平、向中线骶骨两侧压迫两侧输尿管，延缓对比剂下行，使肾盂肾盏充分充盈，故B正确。\n【为什么错】A：加压对象是输尿管而非肾区。C：膀胱不回流。D：加压目的不是减少散射线。E：腹主动脉在椎体前方，不能也不应直接压迫。", "tr": "加压部位是“输尿管走行区”；腹主动脉瘤、新近腹部手术等禁忌加压。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1034", "t": "单选题", "s": "关于逆行肾盂造影，正确的是", "o": {"A": "适用于肾功能严重受损、IVP不显影者", "B": "无需严格消毒", "C": "可用于碘对比剂过敏者", "D": "无需借助膀胱镜", "E": "对比剂用量较IVP更大"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-034", "kp": "逆行肾盂造影特点", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】逆行肾盂造影经膀胱镜将导管插入输尿管直接注入少量对比剂，不经肾脏排泄，适用于肾功能严重受损、IVP不显影或需明确梗阻部位者，故A正确。\n【为什么错】B：属有创操作，必须严格消毒。C：碘过敏者仍禁用含碘对比剂。D：必须借助膀胱镜插管。E：逆行造影对比剂用量小（数毫升）。", "tr": "逆行造影“不经肾脏排泄”是其最大优点，但为有创检查，禁用于严重血尿与急性泌尿系感染。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1035", "t": "单选题", "s": "子宫输卵管造影（HSG）最适宜的检查时间是", "o": {"A": "月经期", "B": "月经干净后3～7天", "C": "排卵期", "D": "月经来潮前1周", "E": "任意时间"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-035", "kp": "HSG检查时间选择", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】HSG应选月经干净后3～7天（卵泡期），此时子宫内膜薄、无经血，且能排除早期妊娠及宫腔感染可能，故B正确。\n【为什么错】A：月经期宫腔有创面，易感染且影响观察。C：排卵后期子宫内膜增厚影响判断。D：接近月经期宫腔环境不宜。E：非任意时间。", "tr": "“月经净后3～7天”与乳腺检查“月经净后1周”是两类不同检查的时机考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1036", "t": "单选题", "s": "下列属于子宫输卵管造影禁忌证的是", "o": {"A": "不孕症", "B": "怀疑输卵管梗阻", "C": "急性生殖道炎症", "D": "子宫畸形", "E": "习惯性流产"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-036", "kp": "HSG禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】急性生殖道（盆腔）炎症时宫腔操作可使感染扩散，属于HSG禁忌证，故C正确。\n【为什么错】A、B、D、E均为HSG适应证：不孕症、查找输卵管梗阻部位、诊断子宫畸形、习惯性流产病因检查。", "tr": "HSG禁忌证为“月经期、急性生殖道炎症、妊娠、碘过敏”，均为高频考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1037", "t": "单选题", "s": "以碘化油行子宫输卵管造影后需加摄24小时延迟片，其原因是", "o": {"A": "观察对比剂被组织吸收的程度", "B": "碘化油黏稠、吸收缓慢，24小时后观察输卵管伞端弥散及盆腔分布情况", "C": "观察子宫收缩状态", "D": "减少患者辐射剂量", "E": "观察输卵管痉挛是否解除"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-037", "kp": "HSG碘化油延迟片", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】碘化油黏稠度高、吸收缓慢，注药24小时后复查摄片观察对比剂自输卵管伞端弥散入盆腔的情况，用于判断输卵管通畅性，故B正确。\n【为什么错】A：观察目的是弥散分布而非被吸收。C：子宫收缩状态非延迟片目的。D：加摄延迟片不减少剂量。E：输卵管痉挛与延迟片无关。", "tr": "油剂（碘化油）“24小时延迟片”；水溶性碘剂吸收快，无需24小时复查。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1038", "t": "单选题", "s": "乳腺X线摄影的常规投照体位是", "o": {"A": "内外斜位（MLO）＋头尾位（CC）", "B": "双侧侧位", "C": "放大摄影＋点压位", "D": "乳沟位＋腋尾位", "E": "切线位＋侧位"}, "d": "易", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-038", "kp": "乳腺常规摄影体位", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】乳腺常规摄影为内外斜位（MLO）与头尾位（CC）两个基本体位，分别从斜向和上下方向显示乳腺，故A正确。\n【为什么错】B、C、D、E均属补充或附加体位，不能替代常规体位。", "tr": "“CC＋MLO”是乳腺摄影标配；MLO显示组织量最多，CC显示内、外侧。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1039", "t": "单选题", "s": "关于乳腺内外斜位（MLO）摄影，正确的是", "o": {"A": "X线束自上而下垂直投照", "B": "X线束自内上向外下约45°投照，显示乳腺组织量最多并含腋尾", "C": "主要用于显示乳腺内侧", "D": "无需压迫乳腺", "E": "中心线经乳头垂直射入"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-039", "kp": "MLO位投照特点", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】MLO位球管自内上向外下约45°投照，乳腺及胸大肌、腋尾部分尽量包括在胶片内，显示乳腺组织量最多，故B正确。\n【为什么错】A：垂直上下投照是CC位。C：CC位显示乳腺内、外侧。D：MLO位同样需充分压迫。E：中心线经乳头为传统定位说法，非投照本质。", "tr": "MLO斜45°显示乳腺最多组织；CC位垂直投照，二者投照方向是鉴别考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1040", "t": "单选题", "s": "乳腺X线摄影时充分压迫乳腺的主要目的不包括", "o": {"A": "减小乳腺厚度、降低辐射剂量", "B": "减少散射线、提高对比度", "C": "固定乳腺、减少运动模糊", "D": "增加乳腺影像的放大率", "E": "使乳腺组织均匀分布、减少结构重叠"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-040", "kp": "乳腺摄影压迫的目的", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】压迫使乳腺变薄贴近探测器，物片距减小，放大率随之减小而非增加，故D错误，本题选D。\n【为什么错】A：厚度减小使所需剂量降低，正确。B：厚度减小散射线减少、对比度提高，正确。C：压迫固定乳腺防止运动模糊，正确。E：压迫使组织摊平、密度均匀，正确。", "tr": "压迫“减小”放大而非增加放大，方向判断是本题陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1041", "t": "单选题", "s": "乳腺X线摄影发现簇状微钙化，为进一步观察钙化的形态、数目与分布，应首选", "o": {"A": "放大摄影（1.5～2倍局部放大）", "B": "双侧侧位", "C": "乳沟位", "D": "切线位", "E": "腋尾位"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-041", "kp": "乳腺放大摄影适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (2)乳腺附加体位", "ex": "【为什么对】放大摄影通过加大投照放大倍数（1.5~2倍）清晰显示微钙化的形态、数目和分布，对鉴别良恶性钙化至关重要，故A正确。\n【为什么错】B：侧位用于病灶定位。C：乳沟位显示乳腺内侧深部。D：切线位用于皮肤及表浅病变。E：腋尾位显示腋尾部乳腺。", "tr": "“微钙化定性→放大摄影”，“肿块定位→点压位”，二者分工不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1042", "t": "单选题", "s": "乳腺导管造影（ductography）的主要适应证是", "o": {"A": "可触及的乳腺肿块", "B": "乳头溢液（尤其单孔血性溢液）", "C": "乳腺增生", "D": "腋窝淋巴结肿大", "E": "乳腺皮肤红肿"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-042", "kp": "乳腺导管造影适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (3)乳腺造影技术", "ex": "【为什么对】乳腺导管造影用于乳头溢液，尤其单孔血性溢液，可显示导管内病变（导管内乳头状瘤、导管扩张等），故B正确。\n【为什么错】A：肿块首选常规乳腺摄影及超声。C：乳腺增生为临床诊断范畴。D：腋窝淋巴结肿大与导管造影无关。E：皮肤红肿多为炎症，属禁忌范畴。", "tr": "“乳头溢液＝导管造影指征”，血性溢液警惕导管内乳头状瘤。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1043", "t": "单选题", "s": "根尖片平行投照（长锥体平行技术）的特点是", "o": {"A": "胶片与牙长轴平行、中心线垂直牙长轴射入", "B": "中心线垂直牙长轴与胶片夹角的角平分线", "C": "胶片远离牙体", "D": "中心线向足侧倾斜15°固定角度", "E": "仅适用于上颌磨牙"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-043", "kp": "根尖片平行投照技术", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】平行投照使胶片与牙体长轴平行，X线中心线垂直牙长轴射入，影像失真最小、牙体长度接近真实，故A正确。\n【为什么错】B：垂直角平分线是分角线投照技术。C：平行投照要求胶片贴近牙体。D：固定倾斜角度属于分角线投照的简化方式。E：平行投照适用于多数牙位，非仅上颌磨牙。", "tr": "“平行投照＝平行＋垂直＝失真小”；“分角线投照＝中心线垂直角平分线”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1044", "t": "单选题", "s": "能一次显示全口牙列、上下颌骨及颞下颌关节的X线摄影技术是", "o": {"A": "根尖片", "B": "咬合片", "C": "曲面断层（全景片）", "D": "咬翼片", "E": "头颅后前位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-044", "kp": "曲面断层检查范围", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】曲面断层（全景摄影）利用X线管与探测器同步反向旋转，一次曝光即显示全口牙列、双侧上下颌骨及颞下颌关节，故C正确。\n【为什么错】A、B、D：均为口内局部片，显示范围局限。E：头颅后前位显示颅骨而非牙列全景。", "tr": "曲面断层＝全口整体观，常用于牙周病、阻生智齿、颌骨病变普查；根尖片为局部精细显示。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1045", "t": "单选题", "s": "关于乳腺X线检查时机及准备，正确的是", "o": {"A": "月经期检查最佳", "B": "月经干净后1周左右检查最佳", "C": "排卵期检查最佳", "D": "检查前无需去除体表粉末", "E": "绝经后女性无需考虑任何准备"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-045", "kp": "乳腺摄影检查时机", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】月经干净后约1周乳腺腺体充血最少、致密程度相对降低且触痛轻，图像质量好、患者舒适，故B正确。\n【为什么错】A：月经期乳腺充血致密，图像质量差。C：排卵期腺体充血水肿。D：爽身粉、乳膏含金属粉末，必须去除以防伪影。E：绝经后虽无月经周期，仍须去除体表异物并规范摆位。", "tr": "乳腺检查“月经净后1周”与HSG“月经净后3~7天”时机相近但概念不同；体表粉末是常见伪影来源。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1046", "t": "多选题", "s": "头颅后前位X线摄影的体位要求包括", "o": {"A": "正中矢状面垂直探测器", "B": "听眦线垂直探测器", "C": "前额及鼻尖贴近探测器", "D": "中心线经枕外隆凸垂直射入", "E": "中心线向足侧倾斜30°射入"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-046", "kp": "头颅后前位体位要求", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A：矢状面垂直保证左右对称。B：听眦线垂直保证前后无倾斜。C：前额鼻尖贴探测器使颅骨贴近胶片减少放大。D：中心线经枕外隆凸垂直射入，为标准投照。\n【为什么错】E：向足侧倾斜30°是汤氏位的投照要求，头颅后前位中心线垂直射入。", "tr": "头颅后前位“垂直投照、经枕外隆凸”；倾斜30°属于汤氏位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1047", "t": "多选题", "s": "汤氏位（Townes位）可显示的结构包括", "o": {"A": "枕骨", "B": "枕骨大孔", "C": "颞骨岩部", "D": "内听道", "E": "蝶鞍"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-047", "kp": "汤氏位显示结构", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A：枕骨为汤氏位主要显示结构。B：枕骨大孔在后前斜向投影下充分显示。C：颞骨岩部在汤氏位上展开投影。D：内听道随岩部显示清晰。\n【为什么错】E：蝶鞍位于颅底中央，以头颅侧位显示为佳，汤氏位对蝶鞍显示无优势。", "tr": "汤氏位＝后颅窝三件套（枕骨、枕骨大孔、岩部内听道）；蝶鞍归侧位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1048", "t": "多选题", "s": "胸部后前位X线摄影的技术要点包括", "o": {"A": "前胸壁贴近探测器", "B": "双手背置于髋部、肘部内旋", "C": "中心线经第6胸椎垂直射入", "D": "焦片距180cm，深吸气后屏气曝光", "E": "患者背部贴近探测器、双臂下垂"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-048", "kp": "胸部后前位技术要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A：前胸壁贴近探测器减少放大、肩胛骨外移。B：双手背置髋、肘内旋使肩胛骨移开肺野。C：中心线经第6胸椎垂直射入。D：180cm远距离摄影减小心脏放大，深吸气后屏气减少运动模糊。\n【为什么错】E：后前位应前胸壁贴探测器，背部贴近且双臂下垂会使肩胛骨与肺野重叠。", "tr": "“后前位前胸贴板、侧位患侧贴板”，双臂姿势不当是胸部正位常见摆位错误。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1049", "t": "多选题", "s": "腹部平片（KUB）摄影前的准备包括", "o": {"A": "清洁肠道（必要时清洁灌肠）", "B": "排空膀胱", "C": "去除腹部金属饰物及膏药", "D": "训练屏气配合", "E": "严格禁食禁水8小时以上"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-049", "kp": "腹部平片摄影准备", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】A：清洁肠道减少粪气影干扰。B：排空膀胱便于观察泌尿系结石及盆腔。C：去除高密度异物避免伪影。D：屏气配合防止运动模糊。\n【为什么错】E：腹部平片一般无需严格禁食禁水；严格禁食并清洁灌肠是IVP等造影检查的术前准备。", "tr": "KUB重点是“清肠、排尿、去异物、屏气”；严格禁食水属于造影准备范畴。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1050", "t": "多选题", "s": "腰椎正位X线摄影的技术要点包括", "o": {"A": "仰卧，正中矢状面垂直摄影台面", "B": "两髋、膝屈曲使腰椎贴近台面", "C": "中心线经脐上3cm垂直射入", "D": "屏气曝光", "E": "中心线向头侧倾斜15°"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-050", "kp": "腰椎正位技术要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A：矢状面垂直保证左右对称。B：髋膝屈曲消除腰椎生理前凸、贴近台面。C：中心线经脐上3cm。D：屏气防止呼吸运动模糊。\n【为什么错】E：腰椎正位中心线垂直射入；向头侧倾斜15°是骶尾椎正位的投照要求。", "tr": "腰椎正位垂直投照；倾斜15°的体位是骶尾椎正位，勿混。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1051", "t": "多选题", "s": "寰枢椎张口位X线摄影的注意事项包括", "o": {"A": "患者尽量张大口腔", "B": "中心线经上颌中切牙与枕外隆凸连线中点垂直射入", "C": "避免上下颌骨与寰枢椎重叠", "D": "中心线向足侧倾斜30°射入", "E": "必要时嘱患者发“啊”音配合张口"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-051", "kp": "寰枢椎张口位注意事项", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A：张大口腔使上下颌骨投影分离。B：中心线经口腔垂直射入显示寰枢椎。C：避免颌骨遮挡C1、C2。E：发“啊”音有助于保持张口。\n【为什么错】D：张口位中心线垂直射入，不倾斜。", "tr": "张口位“垂直经口腔”；倾斜投照是汤氏位等其他体位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1052", "t": "多选题", "s": "骨盆正位X线摄影的技术要点包括", "o": {"A": "仰卧，正中矢状面垂直摄影台面", "B": "两足内旋约15°使股骨颈充分展开", "C": "中心线经耻骨联合上缘垂直射入", "D": "中心线向头侧倾斜20°", "E": "双侧髂骨、股骨头及骶尾椎均应在片内"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-052", "kp": "骨盆正位技术要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A：矢状面垂直保证双侧对称。B：足内旋约15°使股骨颈与股骨干展开、避免缩短重叠。C：中心线经耻骨联合上缘。E：骨盆环、双侧髋关节完整包括。\n【为什么错】D：骨盆正位中心线垂直射入，向头侧倾斜是骶尾椎正位的投照要求。", "tr": "骨盆正位“垂直＋足内旋15°”；“倾斜投照”是骶尾椎正位的特征。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1053", "t": "多选题", "s": "静脉肾盂造影（IVP）的术前准备包括", "o": {"A": "检查前晚少渣饮食并服缓泻剂清洁肠道", "B": "检查前禁食（可少量饮水）", "C": "排空膀胱", "D": "做碘过敏试验", "E": "无需任何准备直接检查"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-053", "kp": "IVP术前准备", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A：少渣饮食加缓泻剂清洁肠道，避免粪气影干扰。B：禁食减少呕吐等不良反应风险。C：排空膀胱便于观察输尿管及膀胱。D：碘过敏试验为必做项。\n【为什么错】E：IVP必须有肠道准备与碘过敏试验，不能直接检查。", "tr": "IVP术前“肠道准备＋碘过敏试验”是必须项；遗漏过敏试验属严重操作缺陷。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1054", "t": "多选题", "s": "下列属于静脉肾盂造影禁忌证的有", "o": {"A": "碘对比剂过敏", "B": "严重肾功能不全（尿毒症无尿）", "C": "单纯性肾囊肿", "D": "多发性骨髓瘤", "E": "妊娠早期"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-054", "kp": "IVP禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A：碘过敏为绝对禁忌。B：无尿时对比剂不能排泄、加重肾损伤。D：多发性骨髓瘤用碘剂易诱发急性肾功能衰竭。E：妊娠为禁忌。\n【为什么错】C：单纯性肾囊肿对碘剂不过敏且肾功能正常，不属于IVP禁忌。", "tr": "“多发性骨髓瘤＋无尿肾衰＋碘过敏＋妊娠”均为IVP禁忌；单纯性肾囊肿不是。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1055", "t": "多选题", "s": "子宫输卵管造影（HSG）的禁忌证包括", "o": {"A": "月经期", "B": "急性生殖道炎症", "C": "妊娠", "D": "碘过敏", "E": "不孕症"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-055", "kp": "HSG禁忌证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】A：月经期宫腔有创面、易感染且影像不清。B：急性炎症宫腔操作致感染扩散。C：妊娠行宫腔造影可致流产。D：碘过敏者禁用碘对比剂。\n【为什么错】E：不孕症是HSG最常见的适应证而非禁忌证。", "tr": "“不孕症=适应证”，勿将其列为禁忌；禁忌为月经期、急性炎症、妊娠、碘过敏。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1056", "t": "多选题", "s": "乳腺X线摄影时压迫乳腺可达到的目的包括", "o": {"A": "减小乳腺厚度、降低辐射剂量", "B": "减少散射线、提高对比度", "C": "固定乳腺、减少运动模糊", "D": "使乳腺组织均匀分布、减少结构重叠", "E": "增加放大率以显示微钙化"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-056", "kp": "乳腺压迫的目的", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】A：厚度减小、剂量降低。B：散射线减少、对比度提高。C：固定乳腺防运动模糊。D：组织摊平减少重叠、密度均匀。\n【为什么错】E：压迫使乳腺贴近探测器，物片距减小，放大率减小而非增加。", "tr": "压迫“减小”放大；放大摄影靠加大焦片距/放大倍数实现，与压迫目的相反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1057", "t": "多选题", "s": "下列属于乳腺摄影附加体位的有", "o": {"A": "90°侧位（内外侧位）", "B": "乳沟位（双乳腺加压）", "C": "放大摄影", "D": "局部点压位", "E": "头尾位（CC）"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-057", "kp": "乳腺附加体位", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (2)乳腺附加体位", "ex": "【为什么对】A：90°侧位用于病灶上下定位。B：乳沟位显示乳腺内侧深部。C：放大摄影用于微钙化。D：局部点压位针对肿块加压显示。\n【为什么错】E：CC位（头尾位）与MLO位是乳腺常规体位，不属于附加体位。", "tr": "附加体位包括90°侧位、乳沟位、放大、点压、切线位、腋尾位等；CC/MLO是常规。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1058", "t": "多选题", "s": "乳腺导管造影的操作要点包括", "o": {"A": "适应证为乳头溢液患者", "B": "经溢液乳孔插入钝头细管（针）", "C": "缓慢注入水溶性碘对比剂1～3ml，至患者有胀感或出现阻力即停止", "D": "注药后摄CC位、MLO位（必要时加放大摄影）", "E": "用力快速加压注入使导管充分充盈"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-058", "kp": "乳腺导管造影操作要点", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (3)乳腺造影技术", "ex": "【为什么对】A：乳头溢液是导管造影主要适应证。B：钝头细管经溢液乳孔插入避免损伤导管。C：少量缓慢注药、有阻力即停，防止导管破裂。D：常规CC、MLO摄片记录导管分布。\n【为什么错】E：用力快速注药可致导管破裂、对比剂进入间质，属错误操作。", "tr": "导管造影“少量、缓慢、有阻力即停”；压力过大致导管破裂是操作禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1059", "t": "多选题", "s": "关于根尖片分角线投照与平行投照两种技术，正确的是", "o": {"A": "分角线投照中心线垂直牙长轴与胶片夹角的角平分线", "B": "平行投照要求胶片与牙长轴平行、中心线垂直牙长轴", "C": "平行投照影像失真比分角线投照大", "D": "平行投照可较真实地反映牙体长度", "E": "分角线投照适用于所有牙位且无失真"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-059", "kp": "根尖片投照技术比较", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】A：分角线投照中心线垂直角平分线，是经典定义。B：平行投照胶片与牙长轴平行、中心线垂直。D：平行投照牙体长度影像接近真实。\n【为什么错】C：平行投照失真比分角线投照更小。E：分角线投照存在角度误差导致的长度失真，并非无失真。", "tr": "“平行投照＝失真小”；“分角线投照＝角平分线、有放大/缩短失真”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1060", "t": "多选题", "s": "属于口内X线摄影技术的有", "o": {"A": "根尖片", "B": "咬合片", "C": "咬翼片", "D": "全口根尖片", "E": "曲面断层（全景片）"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-060", "kp": "口内X线摄影类型", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】A：根尖片显示牙冠、牙根及根尖周组织，属口内片。B：咬合片置于咬合面摄片，显示较大范围牙弓及颌骨。C：咬翼片显示上下牙冠及牙槽嵴顶。D：全口根尖片由多张口内片组成。\n【为什么错】E：曲面断层（全景片）胶片或探测器位于口外，属口外X线摄影。", "tr": "口内片＝根尖片、咬合片、咬翼片；曲面断层是口外摄影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1061", "t": "多选题", "s": "头颅侧位X线摄影的体位要求包括", "o": {"A": "正中矢状面与探测器平行", "B": "瞳间线垂直探测器", "C": "被检侧贴近探测器", "D": "中心线向足侧倾斜30°", "E": "中心线经外耳孔上方约2.5cm垂直射入"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-061", "kp": "头颅侧位体位要求", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A：矢状面与探测器平行保证标准侧位。B：瞳间线垂直避免头后仰或前屈。C：被检侧贴近探测器减少放大。E：中心线经外耳孔上方2.5cm（蝶鞍）垂直射入。\n【为什么错】D：头颅侧位垂直投照，向足侧倾斜30°是汤氏位的投照要求。", "tr": "侧位“矢状面平行＋瞳间线垂直”；倾斜投照属汤氏位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1062", "t": "多选题", "s": "关于胸部斜位X线摄影，正确的是", "o": {"A": "右前斜位（RAO）观察左心房及食管受压情况", "B": "左前斜位（LAO）观察左心室、右心房及胸主动脉", "C": "斜位摄影常用于心脏大血管的X线检查", "D": "中心线经第4胸椎垂直射入", "E": "患者身体旋转约45°~60°投照"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-062", "kp": "胸部斜位摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A：右前斜位（常伴吞钡）观察食管与左心房关系。B：左前斜位显示左心室、右心房、主动脉。C：斜位是心脏大血管X线检查常规组合体位。E：斜位一般旋转45°~60°。\n【为什么错】D：胸部正、侧、斜位中心线均经第6胸椎水平，而非第4胸椎。", "tr": "胸部各体位中心线水平均为“第6胸椎”；右前斜看左房食管、左前斜看左室右房主动脉。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1063", "t": "多选题", "s": "关于静脉肾盂造影摄片与腹部加压的叙述，正确的是", "o": {"A": "注药后7、15、30分钟分别摄肾区片", "B": "加压球囊置于髂前上棘连线水平、骶骨两侧", "C": "加压的目的是使肾盂肾盏充分充盈", "D": "所有患者均可行腹部加压", "E": "解除加压后摄全尿路片"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-063", "kp": "IVP摄片与加压技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A：7、15、30分钟摄片为常规时间点。B：加压部位为输尿管走行区（髂前上棘连线水平骶骨两侧）。C：加压延缓输尿管排空使肾盂肾盏充盈。E：解除加压后摄全尿路片显示输尿管下段及膀胱。\n【为什么错】D：腹主动脉瘤、新近腹部手术、妊娠等为加压禁忌，并非所有患者均可加压。", "tr": "“加压禁忌（腹主动脉瘤等）”是高频考点；加压部位是输尿管而非肾区。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1064", "t": "多选题", "s": "关于乳腺内外斜位（MLO）摄影技术，正确的是", "o": {"A": "球管自内上向外下约45°投照", "B": "为常规体位中显示乳腺组织最多者", "C": "可显示外上象限及腋尾部", "D": "X线束自上而下垂直投照", "E": "应尽量包括胸大肌及腋下淋巴结区域"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-064", "kp": "MLO位技术特点", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】A：MLO位自内上向外下45°投照。B：斜位显示乳腺组织量最大。C：外上象限及腋尾是MLO重点显示区域。E：包括胸大肌及腋窝淋巴结区便于评估。\n【为什么错】D：垂直上下投照是CC位（头尾位）的特点，MLO位为斜向投照。", "tr": "MLO斜45°、CC垂直，投照方向是两者鉴别要点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1065", "t": "多选题", "s": "关于骶尾椎及腰骶关节X线摄影，正确的是", "o": {"A": "骶尾椎正位中心线向头侧倾斜15°~20°", "B": "骶尾椎正位中心线经耻骨联合上缘射入", "C": "骶尾椎正位中心线垂直射入", "D": "腰骶关节正位中心线向头侧倾斜约15°，经腰骶间隙射入", "E": "骶尾椎侧位中心线经骶尾椎垂直射入"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-065", "kp": "骶尾椎与腰骶关节摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】A：骶尾椎正位向头侧倾斜15°~20°。B：中心线经耻骨联合上缘射入使骶尾椎展开。D：腰骶关节正位向头侧倾斜约15°经腰骶间隙投照。E：骶尾椎侧位中心线垂直经骶尾椎。\n【为什么错】C：骶尾椎正位需向头侧倾斜，垂直投照会使骶尾椎与耻骨重叠、影像缩短。", "tr": "骶尾椎正位“头侧倾斜15°~20°经耻骨联合上缘”；勿与垂直投照混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "常见X线摄影体位", "页": 196}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1066", "t": "多选题", "s": "四肢骨X线摄影的一般原则包括", "o": {"A": "病变部位尽量贴近探测器以减少放大", "B": "一般至少摄正、侧两个相互垂直的体位", "C": "病变累及关节时应包括邻近关节", "D": "中心线垂直探测器射入", "E": "一律采用180cm远距离摄影"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-066", "kp": "四肢摄影一般原则", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】A：贴近探测器减少放大。B：正、侧位相互垂直可准确定位骨折移位。C：关节病变需包括关节以便观察。D：常规中心线垂直探测器。\n【为什么错】E：四肢常规焦片距约100cm（75~100cm），180cm远距离摄影用于胸部。", "tr": "四肢不用180cm；远距离摄影是胸部的标志性技术。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1067", "t": "多选题", "s": "关于泌尿系统X线造影，正确的是", "o": {"A": "IVP为静脉注射碘对比剂后经肾脏排泄显示肾盂肾盏", "B": "逆行肾盂造影适用于IVP不显影（如严重肾功能不全）者", "C": "逆行肾盂造影需借助膀胱镜将导管插入输尿管", "D": "膀胱造影通过口服对比剂充盈膀胱", "E": "静脉造影前应做碘过敏试验"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-067", "kp": "泌尿系统造影对比", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】A：IVP经静脉给药、肾脏排泄显影。B：逆行造影不依赖肾功能，适用于IVP不显影者。C：逆行造影经膀胱镜插管。E：IVP前必须做碘过敏试验。\n【为什么错】D：膀胱造影是经导尿管向膀胱内注入对比剂充盈，而非口服。", "tr": "“膀胱造影经导尿管注入”是区别于IVP（静脉注射）的关键操作途径。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1068", "t": "多选题", "s": "副鼻窦瓦氏位（顶颏位）可显示的结构包括", "o": {"A": "上颌窦", "B": "额窦", "C": "蝶窦", "D": "筛窦", "E": "内听道"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-068", "kp": "瓦氏位显示范围", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】A：上颌窦是瓦氏位主要显示对象。B：额窦在瓦氏位亦可显示。D：筛窦在瓦氏位投影中可见。\n【为什么错】C：蝶窦需用头颅侧位等专用体位，瓦氏位显示不佳。E：内听道由汤氏位显示，与副鼻窦无关。", "tr": "瓦氏位＝上颌窦；蝶窦、内听道属其他体位显示范围。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1069", "t": "多选题", "s": "胸部前弓位（前凸位）摄影的适应证与特点包括", "o": {"A": "用于显示肺尖部病变", "B": "用于显示锁骨下区病变", "C": "患者身体后仰，使锁骨投影上移", "D": "中心线经第6胸椎垂直射入", "E": "可使肺尖及第1、2肋间充分展开"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-069", "kp": "胸部前弓位适应证", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】A：前弓位肺尖显示充分。B：锁骨下区病变为前弓位适应证。C：身体后仰使锁骨上移、肺尖露出。E：肺尖及上肺野展开显示。\n【为什么错】D：前弓位中心线经胸骨角水平（约平第4胸椎）垂直射入，而非经第6胸椎；第6胸椎是标准后前位的中心线水平。", "tr": "前弓位中心线“经胸骨角”，与标准后前位“经第6胸椎”不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1070", "t": "多选题", "s": "子宫输卵管造影（HSG）的适应证包括", "o": {"A": "不孕症", "B": "寻找输卵管梗阻部位", "C": "诊断子宫畸形", "D": "月经期止血", "E": "输卵管再通术后复查"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-070", "kp": "HSG适应证", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】A：不孕症是HSG最常见适应证。B：显示输卵管梗阻部位与程度。C：显示宫腔形态诊断子宫畸形。E：输卵管再通术后评估通畅性。\n【为什么错】D：月经期为HSG禁忌证，造影不能用于止血。", "tr": "HSG是“诊断＋通畅性评估”手段；月经期是禁忌而非适应证。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U08-1071a", "t": "单选题", "s": "【病例】患者男性，45岁，腰痛伴右下肢放射痛3个月，咳嗽、用力时加重，临床疑腰椎间盘突出，拟行腰椎X线摄影。技师需确定常规摄影体位、中心线入射点，并判断是否需加照特殊体位。 腰椎X线摄影常规首先应摄取的体位组合是", "o": {"A": "腰椎正位＋侧位", "B": "腰椎正位＋斜位", "C": "骶尾椎正位＋侧位", "D": "骨盆正位＋腰椎侧位", "E": "腰椎过伸过屈位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-071", "kp": "腰椎常规摄影体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎常规摄正位＋侧位两个相互垂直的体位，可观察椎体形态、椎间隙、骨质及生理曲度，满足腰椎间盘突出初步评估需求，故A正确。\n【为什么错】B：斜位用于显示椎弓峡部，为补充体位。C：骶尾椎体位显示范围不符。D：骨盆正位与腰椎评估无直接对应。E：过伸过屈位用于脊柱不稳的动力学评估，非常规首选。", "tr": "“正侧位是常规”，斜位、过伸过屈位均为针对性补充体位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1071b", "t": "单选题", "s": "该患者腰椎正位摄影时，中心线的入射点为", "o": {"A": "脐", "B": "脐上3cm（约第3腰椎）", "C": "脐下3cm", "D": "两侧髂嵴连线中点", "E": "耻骨联合上缘"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-072", "kp": "腰椎正位中心线入射点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎正位中心线经脐上3cm（约平第3腰椎）垂直射入，使腰椎序列完整居中显示，故B正确。\n【为什么错】A：脐水平偏低，腰椎下段显示偏斜。C：脐下3cm更低。D：髂嵴连线平第4腰椎偏下。E：耻骨联合上缘为骨盆正位中心线。", "tr": "“腰椎正位＝脐上3cm”是数值考点；骨盆正位才经耻骨联合上缘。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1071c", "t": "单选题", "s": "若临床高度怀疑椎弓峡部裂所致腰椎滑脱，应加照的体位是", "o": {"A": "腰椎左、右斜位", "B": "腰椎过伸过屈位", "C": "骨盆正位", "D": "胸椎正位", "E": "骶尾椎侧位"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-073", "kp": "椎弓峡部裂补充体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎斜位（约45°）使椎弓峡部展开呈“狗形”，可直接观察峡部是否断裂，是诊断峡部裂的关键体位，故A正确。\n【为什么错】B：过伸过屈位用于评估腰椎不稳与滑脱的动态改变，不直接显示峡部。C、D、E：与峡部显示无关。", "tr": "“斜位看峡部（狗颈）、过伸过屈位看稳定性”，两者的检查目的易混。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1072a", "t": "单选题", "s": "【病例】患者男性，30岁，头部外伤后头痛、恶心2小时，后枕部着地，临床疑枕骨及颅底骨折，拟行头颅X线检查。技师需选择恰当体位、准确确定中心线入射点，以确保后颅窝结构显示清晰。 为显示枕骨及枕骨大孔，应首选的体位是", "o": {"A": "头颅汤氏位（Townes位）", "B": "头颅后前位", "C": "头颅侧位", "D": "柯氏位", "E": "瓦氏位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-074", "kp": "后颅窝外伤体位选择", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位中心线向足侧倾斜30°，使枕骨、枕骨大孔、颞骨岩部及内听道展开显示，是观察后颅窝及枕部骨折的首选体位，故A正确。\n【为什么错】B：后前位观察颅盖正位，枕骨下部与颅底重叠。C：侧位显示前后方向，后颅窝细节有限。D、E：柯氏位、瓦氏位用于副鼻窦。", "tr": "“枕部外伤→汤氏位”；副鼻窦体位不适用于颅底骨折。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1072b", "t": "单选题", "s": "汤氏位摄影时中心线的投照要求为", "o": {"A": "垂直射入", "B": "向头侧倾斜30°", "C": "向足侧倾斜30°", "D": "向足侧倾斜15°", "E": "向头侧倾斜15°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-075", "kp": "汤氏位中心线投照", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位仰卧、听眦线垂直探测器，中心线向足侧倾斜30°，经枕外隆凸下方射入（射达眉间方向），故C正确。\n【为什么错】A：垂直射入为正位要求。B：向头侧倾斜为骶尾椎正位特点。D、E：15°角度及方向均不符。", "tr": "汤氏位“向足侧倾斜30°”，方向与骶尾椎（向头侧倾斜）相反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1073a", "t": "单选题", "s": "【病例】患者女性，52岁，突发右腰腹部绞痛并向会阴部放射，伴肉眼血尿1天，临床疑右侧输尿管结石。拟先行X线检查，必要时进一步行静脉肾盂造影（IVP）。技师需安排检查流程并掌握造影摄片要点。 该患者首选的X线检查是", "o": {"A": "泌尿系平片（KUB）", "B": "静脉肾盂造影（IVP）", "C": "逆行肾盂造影", "D": "膀胱造影", "E": "子宫输卵管造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-076", "kp": "泌尿系结石首选检查", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】泌尿系平片（KUB）无创、简便、经济，约90%的泌尿系结石为阳性结石可在平片上显示，是疑结石患者的首选X线检查，故A正确。\n【为什么错】B：IVP在平片之后用于定位与功能评估。C：逆行造影为有创检查，用于IVP不显影者。D：膀胱造影用于膀胱病变。E：HSG与泌尿系结石无关。", "tr": "“肾绞痛→KUB平片首选”；IVP是第二步的功能定位检查。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1073b", "t": "单选题", "s": "若进一步行IVP，注药后常规摄片时间点为", "o": {"A": "立即、5分钟、15分钟", "B": "7分钟、15分钟、30分钟", "C": "30分钟、60分钟", "D": "15分钟、60分钟", "E": "5分钟、30分钟"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-077", "kp": "IVP摄片时间点", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】IVP注药后7分钟肾盂肾盏开始显影，15、30分钟观察充盈与排泄，解除加压后摄全尿路片，故B正确。\n【为什么错】A：5分钟内肾实质显影、肾盏充盈不足。C、D、E：时间点与常规不符。", "tr": "IVP摄片时间“7、15、30分钟”是造影流程的高频考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1074a", "t": "单选题", "s": "【病例】患者女性，55岁，右乳外上象限触及无痛性肿块1个月，质硬、边界不清，临床疑乳腺癌，拟行乳腺X线摄影。技师需确定常规体位，并对摄影中发现的微钙化选择恰当的补充体位。 该患者乳腺X线摄影的常规投照体位是", "o": {"A": "头尾位（CC）＋内外斜位（MLO）", "B": "双侧侧位", "C": "放大摄影＋点压位", "D": "乳沟位＋腋尾位", "E": "切线位＋CC位"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-078", "kp": "乳腺常规体位", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】乳腺常规摄影为CC位与MLO位两个体位，从上下及斜向两个方向显示乳腺，是筛查与诊断的基础，故A正确。\n【为什么错】B、C、D、E：均为附加或补充体位，不能替代常规体位组合。", "tr": "“CC＋MLO”是乳腺摄影标配组合，附加体位在其基础上选用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1074b", "t": "单选题", "s": "摄影中发现可疑簇状微钙化，为观察钙化形态应加照", "o": {"A": "放大摄影", "B": "乳沟位", "C": "腋尾位", "D": "90°侧位", "E": "切线位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-079", "kp": "乳腺微钙化放大摄影", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (2)乳腺附加体位", "ex": "【为什么对】放大摄影（1.5~2倍）可清晰显示微钙化的形态、数目与分布，对良恶性鉴别至关重要，故A正确。\n【为什么错】B：乳沟位显示内侧深部。C：腋尾位显示腋尾。D：90°侧位用于病灶定位。E：切线位用于皮肤及表浅病变。", "tr": "“钙化看放大、肿块看点压”，附加体位的分工需记清。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1075a", "t": "单选题", "s": "【病例】患者女性，30岁，结婚2年未孕，月经规律，男方精液检查正常，临床拟行子宫输卵管造影（HSG）评估输卵管通畅性。技师需掌握检查时机、禁忌判断及对比剂的选择与复查时间。 该患者HSG检查宜安排在", "o": {"A": "月经期", "B": "月经干净后3～7天", "C": "排卵期", "D": "月经来潮前1周", "E": "任意时间"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-080", "kp": "HSG检查时机", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】HSG应安排在月经干净后3~7天（卵泡期），此时子宫内膜薄、无经血、可排除早孕，故B正确。\n【为什么错】A：月经期有创面易感染。C：排卵期后内膜增厚影响判断。D、E：均非适宜时机。", "tr": "“月经净后3~7天”是HSG的固定时机考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1075b", "t": "单选题", "s": "若选用碘化油行造影，需加摄的延迟片时间为", "o": {"A": "15分钟", "B": "30分钟", "C": "24小时", "D": "48小时", "E": "无需延迟片"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-081", "kp": "HSG碘化油延迟片", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】碘化油黏稠、吸收缓慢，需24小时后复查摄片观察对比剂自伞端弥散入盆腔的情况，判断输卵管通畅度，故C正确。\n【为什么错】A、B：15、30分钟为水溶性碘剂复查时间。D：48小时非标准时间。E：油剂必须加延迟片。", "tr": "“油剂24小时延迟片、水剂短时复查”是HSG对比剂特性考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1076a", "t": "单选题", "s": "【病例】患者男性，60岁，体检胸片发现右肺门影增大，前来复查胸部X线。技师需规范摆位、准确确定中心线入射点，并掌握远距离摄影的意义，以保证影像质量并兼顾辐射防护。 胸部后前位X线摄影中心线的入射点为", "o": {"A": "第4胸椎", "B": "第6胸椎", "C": "第7胸椎", "D": "胸骨角", "E": "剑突"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-082", "kp": "胸部后前位中心线", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸部后前位中心线经第6胸椎垂直射入探测器中心，使双肺及纵隔居中对称显示，故B正确。\n【为什么错】A：第4胸椎平胸骨角偏高。C：第7胸椎为胸椎正位中心线。D：胸骨角是前弓位中心线。E：剑突水平过低。", "tr": "胸部正位中心线“第6胸椎”；前弓位才经胸骨角。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1076b", "t": "单选题", "s": "该患者胸部正位采用180cm焦片距远距离摄影的主要意义是", "o": {"A": "减少散射线", "B": "减小心脏等器官的放大失真", "C": "提高空间分辨率", "D": "缩短曝光时间", "E": "便于患者屏气配合"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-083", "kp": "胸部远距离摄影意义", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】心脏位于胸腔前半部、距探测器较远，180cm远距离摄影使放大率减小、心影接近真实大小，便于心影测量与随访比较，故B正确。\n【为什么错】A：散射线控制靠滤线栅及散射线吸收。C：空间分辨率主要由探测器与焦点决定。D：焦片距增大反而需增加曝光条件。E：与屏气配合无关。", "tr": "远距离摄影的核心是“减小心脏放大”，而非提高分辨率或减少散射线。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1077a", "t": "单选题", "s": "【病例】患者男性，50岁，牙龈出血伴全口牙松动，临床疑牙周病，拟行口腔X线检查以全面评估牙槽骨吸收情况。技师需选择合适的检查技术，并对个别牙的根尖周病变选择精细显示方法。 能一次显示全口牙列及牙槽骨情况的检查是", "o": {"A": "曲面断层（全景片）", "B": "根尖片", "C": "咬翼片", "D": "咬合片", "E": "头颅侧位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-084", "kp": "曲面断层适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】曲面断层一次曝光即可显示全口牙列、双侧上下颌骨及牙槽骨整体情况，是牙周病等需全面评估的首选，故A正确。\n【为什么错】B、C、D：均为口内局部片，范围局限。E：头颅侧位用于正畸测量，不显示牙槽骨细节。", "tr": "“全口整体评估→曲面断层；局部精细评估→根尖片”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1077b", "t": "单选题", "s": "需对个别牙的牙根及根尖周骨质精确显示时，应选择", "o": {"A": "根尖片（优先平行投照）", "B": "曲面断层", "C": "咬合片", "D": "头颅正位", "E": "颞下颌关节位"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-085", "kp": "根尖片适应证", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】根尖片分辨率高，可精细显示个别牙的牙冠、牙根、根尖周骨质及牙周膜间隙，平行投照失真最小，故A正确。\n【为什么错】B：曲面断层整体显示但局部分辨率不如根尖片。C：咬合片用于较大范围牙弓与颌骨。D、E：与根尖周显示无关。", "tr": "“根尖片=局部精细”，与曲面断层的“整体普查”互为补充。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1078", "t": "案例分析题", "s": "患者男性，58岁，吸烟史30年，慢性咳嗽、咳痰伴痰中带血2周，胸部听诊右下肺呼吸音减低，临床疑右下肺占位性病变，前来行胸部X线检查。设备为DR，采用自动曝光控制。技师嘱患者站立、前胸壁贴紧探测器，双手背置于髋部、肘部内旋使肩胛骨外展，嘱深吸气后屏气曝光，注意双侧肺野及肋膈角均应包括在摄影范围内。关于本次胸部后前位摄影的技术要点，正确的是", "o": {"A": "中心线经胸骨角垂直射入", "B": "焦片距采用100cm", "C": "中心线经第6胸椎垂直射入，焦片距180cm", "D": "中心线向足侧倾斜15°射入", "E": "嘱患者呼气后屏气曝光"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-086", "kp": "胸部后前位摄影综合要点", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (3)胸部", "ex": "【为什么对】胸部后前位中心线经第6胸椎垂直射入探测器中心，采用180cm远距离摄影减小放大，深吸气后屏气减少运动模糊，三者均符合标准，故C正确。\n【为什么错】A：胸骨角是前弓位中心线定位点，后前位经第6胸椎。B：100cm为四肢常规焦片距，胸部应取180cm。D：胸部后前位中心线垂直，不倾斜。E：应深吸气后屏气使肺野充分展开，呼气位影响肺野显示。", "tr": "胸部后前位“第6胸椎＋180cm＋深吸气后屏气”三位一体，是胸部摄影的核心组合。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1079", "t": "案例分析题", "s": "患者男性，40岁，1小时前从高处坠落致头枕部外伤，伴头痛、恶心并呕吐1次，查体枕部皮肤瘀肿、压痛明显，临床高度怀疑枕骨及颅底骨折，申请头颅X线检查。技师拟行头颅汤氏位（Townes位）摄影，需确保枕骨、枕骨大孔、颞骨岩部及内听道等后颅窝结构显示充分，并要求患者保持头部固定不动。关于汤氏位摄影，正确的叙述是", "o": {"A": "患者俯卧，前额及鼻尖贴近探测器", "B": "中心线垂直射入眉间", "C": "患者仰卧、听眦线垂直探测器，中心线向足侧倾斜30°经枕外隆凸下方射入", "D": "中心线向头侧倾斜30°", "E": "听眦线平行探测器"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-087", "kp": "汤氏位摄影技术", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (2)头颅", "ex": "【为什么对】汤氏位患者仰卧、听眦线垂直探测器，中心线向足侧倾斜30°，经枕外隆凸下方射入，使枕骨、枕骨大孔、岩部及内听道展开，符合后颅窝显示需求，故C正确。\n【为什么错】A：俯卧、额鼻贴片是后前位。B：垂直射入是正位要求。D：向头侧倾斜为骶尾椎正位特点。E：听眦线应垂直而非平行探测器。", "tr": "汤氏位“仰卧＋向足侧倾斜30°”，从摆位到角度都须准确。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1080", "t": "案例分析题", "s": "患者女性，48岁，反复右侧腰痛伴肉眼血尿3个月，B超提示右肾结石并轻度肾积水，临床申请静脉肾盂造影（IVP）以明确结石位置及肾功能情况。患者既往有哮喘病史，本次碘过敏试验阴性。检查前已行少渣饮食、清洁灌肠并排空膀胱，技师需掌握对比剂选择、摄片时间与腹部加压等要点，并备好急救物品以应对可能的不良反应。关于IVP操作，正确的是", "o": {"A": "对比剂选用碘化油", "B": "静脉注射碘对比剂后于7、15、30分钟摄片", "C": "注药后立即摄全尿路片", "D": "加压球囊置于上腹部正中", "E": "无需行腹部加压"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-088", "kp": "IVP操作流程", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】IVP静脉注射水溶性碘对比剂，7、15、30分钟分别摄肾区片，符合标准流程，故B正确。\n【为什么错】A：碘化油用于HSG等，IVP用碘对比剂。C：注药后早期为肾实质期，肾盏充盈需数分钟，不能立即摄全尿路片。D：加压球囊置于髂前上棘连线水平骶骨两侧压迫输尿管，非上腹部正中。E：常规需腹部加压使肾盂肾盏充盈（加压禁忌者除外）。", "tr": "IVP标准流程“静脉碘剂＋7/15/30分钟＋输尿管区加压”，哮喘史患者更应注意过敏风险防范。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1081", "t": "案例分析题", "s": "患者女性，28岁，结婚2年未孕，月经周期规律，男方精液检查正常，临床拟行子宫输卵管造影（HSG）以评估输卵管通畅性。患者平素月经规律，末次月经已过10天，无生殖道感染史，碘过敏试验阴性。技师需判断检查时机是否合适并掌握对比剂特性及复查时间，同时做好患者沟通以减轻紧张情绪。关于该患者HSG检查，正确的说法是", "o": {"A": "月经期亦可进行检查", "B": "造影时机应选月经干净后3～7天，本次时机已过，需重新安排", "C": "用碘化油造影后30分钟复查即可", "D": "注药速度越快越好，可减少患者不适", "E": "造影后无需观察即可离院"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-089", "kp": "HSG时机与流程", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (2)子宫输卵管造影", "ex": "【为什么对】HSG应选月经干净后3~7天，该患者末次月经已过10天，接近排卵期、内膜增厚，不符合最佳时机，需重新预约，故B正确。\n【为什么错】A：月经期为禁忌。C：碘化油需24小时延迟片，30分钟复查是水剂的要求。D：注药应缓慢，快速注药可致输卵管破裂、对比剂反流。E：造影后需观察不良反应并告知注意事项。", "tr": "时机不符应改期；油剂与水剂延迟片时间不同；注药宜缓。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1082", "t": "案例分析题", "s": "患者女性，62岁，绝经后5年，发现左乳外上象限质硬肿块1个月，边界不清、活动度差，临床疑乳腺癌，拟行乳腺X线摄影。检查前技师嘱患者去除胸部乳膏、爽身粉等含金属粉末的体表物，并询问月经史及哺乳史。拟行双侧CC位及MLO位摄影，必要时加照附加体位，摄影时充分压迫但以患者可耐受为度。关于乳腺摄影操作，正确的是", "o": {"A": "只需摄影患侧乳腺", "B": "MLO位X线束自上而下垂直投照", "C": "充分压迫乳腺，压力以患者可耐受为度", "D": "中心线经第6胸椎垂直射入", "E": "放大摄影作为常规体位"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-090", "kp": "乳腺摄影操作规范", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (1)乳腺摄影体位", "ex": "【为什么对】乳腺摄影必须充分压迫（减少厚度、散射线、运动模糊），压力以患者能耐受为度，兼顾图像质量与舒适度，故C正确。\n【为什么错】A：应双侧对比摄影，仅摄患侧不利于对照。B：MLO位自内上向外下约45°斜向投照。D：乳腺摄影中心线经乳腺中心而非第6胸椎。E：放大摄影是附加体位，常规为CC＋MLO。", "tr": "乳腺摄影“双侧对比＋充分压迫＋CC/MLO常规”，附加体位按需加用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1083", "t": "案例分析题", "s": "患者女性，41岁，右侧乳头单孔血性溢液1个月，乳晕区未触及明确肿块，挤压乳头可挤出少量血性液体，乳腺超声未见明显占位，临床疑导管内乳头状瘤，拟行乳腺导管造影明确诊断。技师需掌握消毒、经溢液乳孔插管、缓慢注药及摄片等操作要点，并注意观察患者有无疼痛等不适反应，备好急救物品以防碘过敏反应。关于该造影操作，正确的是", "o": {"A": "消毒后经溢液乳孔插入钝头细管，缓慢注入水溶性碘对比剂1～3ml，有阻力即停止", "B": "用力快速推注使导管充分充盈", "C": "注入碘化油50ml观察全乳腺", "D": "注药后立即常规摄放大摄影即可", "E": "急性乳腺炎患者亦可进行本检查"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-091", "kp": "乳腺导管造影操作", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (3)乳腺造影技术", "ex": "【为什么对】导管造影经溢液乳孔插入钝头细管，缓慢注入少量（1~3ml）水溶性碘对比剂，遇阻力即停止，防止导管破裂及对比剂进入间质，故A正确。\n【为什么错】B：快速注药压力过大可致导管破裂。C：碘化油50ml剂量明显过大且选材错误。D：常规应摄CC位、MLO位（必要时放大），不能只摄放大摄影。E：急性乳腺炎为导管造影禁忌证。", "tr": "导管造影“少量、缓慢、有阻力即停”，急性炎症禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1084", "t": "案例分析题", "s": "患者男性，35岁，从2米高处坠落致颈部外伤，颈托固定后诉颈部剧痛、双上肢麻木，临床高度怀疑寰枢椎骨折脱位，拟行颈椎X线检查明确诊断。技师需选择能清晰显示寰枢椎、避开下颌骨及牙齿遮挡的体位，并注意在颈托保护下规范摆位，避免过度搬动加重损伤，必要时请临床医师协助固定。关于该体位的选择与摄影要点，正确的是", "o": {"A": "常规颈椎正位即可充分显示寰枢椎", "B": "采用张口位（开口位），中心线经口腔垂直射入", "C": "采用颈椎斜位，中心线向足侧倾斜15°", "D": "采用颈椎侧位，中心线向足侧倾斜30°", "E": "采用头颅汤氏位显示寰枢椎"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-092", "kp": "寰枢椎外伤检查体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】张口位中心线经口腔垂直射入，使上下颌骨投影分开，寰椎、枢椎（齿突）清晰显示，是疑寰枢椎损伤的首选体位，故B正确。\n【为什么错】A：颈椎正位寰枢椎被下颌骨及牙齿遮挡。C：斜位用于显示椎间孔。D：侧位显示椎体序列与曲度，对寰枢椎细节有限。E：汤氏位显示后颅窝，非寰枢椎。", "tr": "寰枢椎检查“张口位”，中心线必须经口腔；颈椎外伤患者应在颈托保护下完成。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1085", "t": "案例分析题", "s": "患者男性，55岁，长期从事搬运工作，慢性腰痛伴间歇性跛行5年，腰椎正侧位片示L5椎体前滑移约Ⅱ度，临床疑椎弓峡部裂所致腰椎滑脱。为进一步明确峡部是否断裂、评估手术必要性，技师应加照恰当的补充体位，注意掌握摆位角度及中心线方向，必要时结合过伸过屈位评估稳定性。患者无高血压、糖尿病等合并症。关于该补充体位的选择，正确的是", "o": {"A": "腰椎左、右斜位", "B": "骨盆正位", "C": "骶尾椎正位", "D": "腰椎过伸位", "E": "胸椎正位"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-093", "kp": "腰椎峡部裂检查体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (5)脊椎与骨盆", "ex": "【为什么对】腰椎左、右斜位约45°使椎弓峡部展开呈“狗形”，可直接观察峡部是否断裂，是诊断峡部裂的确定性体位，故A正确。\n【为什么错】B：骨盆正位不显示椎弓峡部。C：骶尾椎正位显示范围不符。D：过伸位评估滑脱稳定性，不直接显示峡部。E：胸椎正位与L5峡部无关。", "tr": "腰椎滑脱病因评估“斜位看峡部”，动态稳定评估“过伸过屈位”，两者目的不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1086", "t": "案例分析题", "s": "患者男性，20岁，踢足球时扭伤右膝关节，膝部明显肿胀、关节腔积液，浮髌试验阳性，屈伸活动受限，临床疑胫骨髁间棘骨折及半月板损伤，拟行右膝关节X线摄影。技师准备拍摄膝关节正位与侧位，注意中心线入射点、投照方向及患者体位摆放，避免关节旋转导致影像失真。患者否认既往膝关节外伤及手术史。关于膝关节正位摄影的中心线与体位要求，正确的是", "o": {"A": "中心线经髌骨上缘射入", "B": "中心线经髌骨下缘（股胫关节线）垂直射入", "C": "中心线向头侧倾斜20°射入", "D": "焦片距取180cm", "E": "患者俯卧、屈膝投照"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-094", "kp": "膝关节正位摄影", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】膝关节正位中心线经髌骨下缘（股胫关节线）垂直射入，可清晰显示股胫关节间隙及髁间结构，故B正确。\n【为什么错】A：髌骨上缘偏高，关节线显示不佳。C：正位垂直投照，不倾斜。D：四肢常规焦片距100cm，180cm为胸部。E：膝关节正位患者仰卧伸直下肢，俯卧屈膝是髌骨轴位等体位。", "tr": "膝关节正位“仰卧伸直＋中心线经髌骨下缘”；俯卧屈膝是髌骨轴位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1087", "t": "案例分析题", "s": "患者男性，45岁，既往十二指肠溃疡病史，突发上腹刀割样剧痛2小时，查体呈板状腹、全腹压痛反跳痛，肠鸣音消失，临床高度怀疑溃疡病穿孔，紧急申请X线检查以观察有无膈下游离气体。技师需指导患者配合体位摆放并选择恰当投照方式，尽快完成检查以辅助临床决策，同时注意检查前与患者沟通注意事项。关于该检查的体位选择与技术要点，正确的是", "o": {"A": "采用腹部仰卧前后位即可显示游离气体", "B": "采用立位（半坐位）腹部平片，水平投照观察膈下游离气体", "C": "采用腹部俯卧后前位", "D": "采用骨盆正位", "E": "嘱患者深呼吸后屏气曝光即可"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-095", "kp": "膈下游离气体检查", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (4)腹部", "ex": "【为什么对】立位或半坐位水平投照时游离气体上浮集聚于膈下肝顶间隙，呈新月形透亮影，是最佳显示方法，故B正确。\n【为什么错】A：仰卧位游离气体聚于前腹壁下，与肠气混杂难以辨认。C：俯卧位更不利于气体显示。D：骨盆正位与穿孔无关。E：屏气是必要条件而非体位选择要点。", "tr": "“膈下游离气体必须立位/半坐位水平投照”，卧位平片极易漏诊。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1088", "t": "案例分析题", "s": "患者男性，70岁，走路时不慎摔倒致左肩外伤，左肩部疼痛剧烈、肿胀，活动明显受限，右臂托扶就诊，临床疑左肩关节脱位及肱骨外科颈骨折，拟行左肩关节正位X线摄影。技师需准确确定中心线入射点并规范摆位，必要时加照轴位或穿胸位以观察肱骨头脱位情况，摆位时动作轻柔避免加重疼痛。关于肩关节正位摄影中心线的入射点，正确的是", "o": {"A": "喙突", "B": "肩峰", "C": "肱骨外科颈", "D": "锁骨中点", "E": "肩胛下角"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-096", "kp": "肩关节正位中心线", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】肩关节正位中心线经喙突垂直射入，使肱骨头、关节盂及肩锁关节清晰显示，故A正确。\n【为什么错】B：肩峰偏外上方。C：肱骨外科颈为骨折部位而非定位点。D：锁骨中点偏内侧。E：肩胛下角为背部标志，与肩关节正位定位无关。", "tr": "肩关节正位“中心线经喙突”；疑肩锁关节分离需加照双肩负重位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1089", "t": "案例分析题", "s": "患者女性，25岁，滑冰时手掌撑地摔倒致右腕肿痛，鼻烟壶区压痛明显，普通腕关节正位片未见明确骨折线，临床高度怀疑腕舟骨骨折。为明确诊断，技师需选择能避开舟骨与邻近腕骨重叠的特殊投照体位，掌握中心线倾斜方向与角度，必要时嘱患者随访复查或加做CT。同时嘱患者减少腕部活动并适当抬高患肢。关于舟骨骨折的补充检查方案，正确的是", "o": {"A": "加照舟骨尺偏位（中心线经桡骨茎突向尺侧倾斜约20°射入）", "B": "加照腕关节侧位即可确诊", "C": "加照手正位即可确诊", "D": "加照肘关节正位", "E": "加照前臂正侧位"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-097", "kp": "舟骨骨折补充体位", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】舟骨位（尺偏位）腕关节向尺侧偏转使舟骨长轴展开，中心线经桡骨茎突向尺侧倾斜约20°，避免舟骨与邻近腕骨重叠，是显示舟骨骨折的关键补充体位，故A正确。\n【为什么错】B：侧位舟骨与其余腕骨重叠，显示不佳。C：手正位舟骨仍重叠。D、E：肘关节、前臂体位与腕舟骨无关。", "tr": "“鼻烟壶区压痛→疑舟骨骨折→尺偏位”，舟骨骨折早期平片可阴性。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1090", "t": "案例分析题", "s": "患者男性，48岁，右下后牙反复肿痛，拟拔除右下阻生智齿，术前需了解牙根形态、数目及其与下牙槽神经管的关系，同时评估全口牙槽骨情况，为手术方案及风险告知提供依据。技师需选择能兼顾局部细节与整体结构的X线检查方法，必要时配合根尖片精细显示牙根与神经管关系。患者既往有牙周炎病史及多次拔牙史。关于术前X线检查方法的选择，正确的是", "o": {"A": "首选曲面断层（全景片）", "B": "仅摄右下根尖片即可", "C": "摄咬合片即可满足要求", "D": "摄头颅正位定位片", "E": "摄颞下颌关节许氏位"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-098", "kp": "阻生智齿术前检查", "ch": "八、普通X线检查技术 → 3.乳腺与口腔X线摄影检查 → (4)口腔X线摄影", "ex": "【为什么对】曲面断层可一次显示全口牙列、下颌骨及下牙槽神经管走向，既能评估阻生智齿牙根形态与神经管关系，又能评估全口牙槽骨，是阻生智齿拔除术前首选，故A正确。\n【为什么错】B：根尖片局部显示，无法评估神经管全貌。C：咬合片显示范围不符。D：头颅正位用于颅骨测量。E：许氏位用于颞下颌关节。", "tr": "阻生智齿术前“曲面断层＋必要时根尖片局部放大”，全景片是首选。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1091", "t": "案例分析题", "s": "患者女性，50岁，右侧腰痛伴发热2周，影像学提示右肾盂积水，IVP示右肾及输尿管上段显影不清，临床拟行右侧逆行肾盂造影以明确梗阻部位及原因。技师需了解逆行造影的适应证、禁忌及操作要点，并与患者做好沟通，检查前确认碘过敏试验结果，术中注意无菌操作。患者无出血倾向，凝血功能正常。关于逆行肾盂造影的技术要点，正确的是", "o": {"A": "经膀胱镜将导管插入右输尿管，注入少量对比剂显示肾盂形态", "B": "需静脉快速注射大量对比剂", "C": "检查前无需做碘过敏试验", "D": "急性泌尿系感染期亦可安全进行", "E": "对比剂选用碘化油"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-099", "kp": "逆行肾盂造影技术", "ch": "八、普通X线检查技术 → 2.X线造影检查 → (1)泌尿系统造影", "ex": "【为什么对】逆行肾盂造影经膀胱镜将导管插入输尿管，直接注入少量对比剂逆行充盈肾盂肾盏，不经肾脏排泄，适用于IVP不显影者，故A正确。\n【为什么错】B：逆行造影不依赖静脉给药，用量小。C：仍使用含碘对比剂，术前必须做碘过敏试验。D：急性泌尿系感染为逆行造影禁忌，可致感染扩散。E：逆行造影使用水溶性碘对比剂，不用碘化油。", "tr": "逆行造影“膀胱镜插管＋少量直接注入”，碘过敏与急性感染均属禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-1092", "t": "案例分析题", "s": "患者女性，72岁，在家中滑倒后右髋部疼痛、不能站立行走，右下肢呈外旋短缩畸形，临床高度怀疑右股骨颈骨折，拟行X线检查以明确骨折部位与类型，并为治疗方案提供依据。技师需确定恰当的摄影方案与体位配合，注意轻柔搬动患者并做好辐射防护，必要时加摄对侧对比。患者有骨质疏松病史，检查时注意轻柔操作。关于该患者髋部摄影方案，正确的是", "o": {"A": "摄骨盆正位（两足内旋约15°）并加摄右侧髋关节正位", "B": "仅摄右侧髋关节侧位", "C": "摄骶尾椎正位", "D": "摄右膝关节正位", "E": "摄右股骨全长正位即可"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-100", "kp": "股骨颈骨折摄影方案", "ch": "八、普通X线检查技术 → 1.常见X线摄影体位 → (6)四肢与关节", "ex": "【为什么对】股骨颈骨折应摄骨盆正位（双侧对比、排除对侧病变）并加摄患侧髋关节正位，两足内旋约15°使股骨颈充分展开显示，故A正确。\n【为什么错】B：仅侧位无法全面评估且无对侧对比。C：骶尾椎正位与股骨颈无关。D：膝关节正位部位不符。E：股骨全长正位不能突出显示股骨颈及对比。", "tr": "“髋部外伤→骨盆正位＋患髋正位，两足内旋15°”，双侧对比是骨折摄影重要原则。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U08-9101", "t": "单选题", "s": "下列情况中，不属于静脉肾盂造影（IVP）禁忌证的是", "o": {"A": "碘对比剂过敏史", "B": "无尿或严重肾功能衰竭", "C": "多发性骨髓瘤", "D": "妊娠（相对禁忌，需权衡）", "E": "单纯性肾囊肿"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9101-正高", "kp": "静脉肾盂造影禁忌证", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)静脉肾盂造影", "ex": "【为什么对】E 正确：单纯性肾囊肿不影响对比剂排泄，不属于 IVP 禁忌。【为什么错】A 碘过敏可致严重过敏反应，禁忌；B 无尿时对比剂无法排泄、加重肾损伤，禁忌；C 多发性骨髓瘤患者使用碘对比剂可诱发骨髓瘤肾病、禁忌；D 妊娠为相对禁忌需充分权衡。", "tr": "易将\"单纯性肾囊肿\"误列为禁忌；囊肿不影响排泄，并非禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U08-9102", "t": "多选题", "s": "关于口服钡餐（上消化道）造影的检查前准备，下列说法正确的有", "o": {"A": "检查前禁食 8–12 小时", "B": "停用影响胃肠蠕动的药物（如阿托品、吗丁啉）", "C": "必要时清除肠内气体与内容物", "D": "常规行全结肠清洁灌肠", "E": "检查前大量饮水以充盈胃腔"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9102-正高", "kp": "胃肠道钡餐造影准备", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)上消化道钡餐造影", "ex": "【为什么对】A、B、C 正确：禁食可减少胃内容物重叠、停用促/抑动力药避免干扰、适当清除气体有助于显示。【为什么错】D 上消化道钡餐无需全结肠清洁灌肠；E 检查前大量饮水会稀释、冲走钡剂，影响黏膜涂布与显示。", "tr": "E 为干扰项——大量饮水反而冲淡钡剂；D 仅适用于下消化道/结肠造影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 1}, {"id": "ZG-U08-9103", "t": "单选题", "s": "子宫输卵管造影（HSG）的最佳检查时间是", "o": {"A": "月经干净后 3–7 天", "B": "月经期 Any day of menstruation", "C": "排卵期", "D": "月经来潮前 1 周", "E": "整个月经周期任意时间均可"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9103-正高", "kp": "子宫输卵管造影时机", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)子宫输卵管造影", "ex": "【为什么对】A 正确：月经干净后 3–7 天子宫内膜已修复、尚未排卵，造影剂不易逆流入腹腔且能避免妊娠可能，是 HSG 的最佳时机。【为什么错】B 经期感染风险高；C 排卵期可能受孕；D、E 时机不当增加并发症或误诊。", "tr": "需区分\"月经干净后\"而非\"月经前\"；同时排除已排卵受孕窗口。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U08-9104", "t": "单选题", "s": "关于经内镜逆行胰胆管造影（ERCP）的下列叙述，正确的是", "o": {"A": "经十二指肠镜插管至十二指肠大乳头，逆行注入对比剂显示胰胆管", "B": "经 T 管注入对比剂", "C": "经皮经肝穿刺注入", "D": "经静脉注射对比剂", "E": "口服对比剂后显示"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9104-正高", "kp": "ERCP 途径", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)ERCP", "ex": "【为什么对】A 正确：ERCP 是在十二指肠镜下将导管插入十二指肠大乳头（Oddi 括约肌）开口，逆行注入碘对比剂使胰管、胆管显影。【为什么错】B 为 T 管造影路径；C 为 PTC（经皮经肝胆道造影）；D、E 不符合 ERCP 定义。", "tr": "易与 PTC、T 管造影、MRCP 的路径混淆；ERCP 关键是\"内镜+逆行乳头插管\"。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U08-9105", "t": "单选题", "s": "胆道术后经 T 管造影（T-tube cholangiography）的主要适应证是", "o": {"A": "了解胆道通畅情况并发现残余结石", "B": "术前评估胆囊形态", "C": "替代 MRCP 作为首选检查", "D": "诊断单纯胆囊结石", "E": "无症状体检筛查"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "KP-BU-8-9105-正高", "kp": "T管造影适应证", "ch": "八、普通X线检查技术 → 3.X线造影检查 → (补充)T管造影", "ex": "【为什么对】A 正确：T 管造影在胆道术后经留置的 T 管注入对比剂，用于评估胆总管通畅度、有无狭窄及残余/复发结石，是拔管前常规检查。【为什么错】B、D 为术前/其他检查目的；C MRCP 是无创首选；E 无需造影筛查。", "tr": "T 管造影是\"术后拔管前\"检查，而非术前或筛查手段。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "X线造影检查", "页": 206}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U08-9201", "t": "单选题", "s": "子宫输卵管造影（HSG）常用的对比剂是", "o": {"A": "碘化油或碘水溶液", "B": "硫酸钡", "C": "二氧化碳气体", "D": "钆对比剂", "E": "空气"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-9201", "kp": "HSG对比剂选择", "ch": "八、普通X线检查技术 → 3.X线造影检查", "ex": "【为什么对】子宫输卵管造影常用碘化油或水溶性碘对比剂，可显示宫腔与输卵管形态。\n【为什么错】硫酸钡用于消化道；空气/二氧化碳用于阴性对比；钆剂用于MRI。", "tr": "HSG对比剂为碘剂而非钡剂。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U08-9202", "t": "单选题", "s": "静脉肾盂造影（IVP）属于", "o": {"A": "阴性对比造影", "B": "阳性对比剂静脉性排泄造影", "C": "直接穿刺造影", "D": "MR造影", "E": "超声造影"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "八", "un": "普通X线检查技术", "kpid": "UNIT-08-XRAY-9202", "kp": "IVP原理", "ch": "八、普通X线检查技术 → 3.X线造影检查", "ex": "【为什么对】IVP经静脉注射阳性碘对比剂，借肾脏排泄显示尿路，属静脉性排泄造影。\n【为什么错】并非阴性对比或穿刺造影。", "tr": "IVP是静脉尿路造影，靠肾排泄显影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "普通X线检查技术", "节": "乳腺与口腔X线摄影检查", "页": 210}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U09-0101", "t": "单选题", "s": "已知某组织的X线线性衰减系数为0.021 mm⁻¹，同一扫描条件下水的线性衰减系数为0.019 mm⁻¹。按Hounsfield的定义，该组织的CT值最接近", "o": {"A": "21 HU", "B": "95 HU", "C": "105 HU", "D": "190 HU", "E": "1000 HU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-101", "kp": "CT值定义与计算公式", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】C正确。CT值的定义式为：CT值＝（μ组织－μ水）/μ水×1000（单位HU），即以水的线性衰减系数为基准做相对线性变换、再乘标度常数1000。代入：（0.021－0.019）/0.019×1000≈105.3 HU，最接近105 HU。【为什么错】A错误：21 HU是把组织自身的μ值直接乘1000（0.021×1000）得到的，混淆了绝对衰减系数与相对CT值。B错误：95 HU来自把分母误写成组织的μ（0.002/0.021×1000≈95），公式中分母恒为水的μ。D错误：190 HU相当于把标度常数误用为2000（老式EMI标度），现行Hounsfield标度K＝1000。E错误：1000 HU是把标度常数本身当成结果，且骨皮质等高密度组织才可能达到该量级，与本题μ仅略高于水不符。", "tr": "公式分母永远是水的衰减系数，不是被测组织的。另需分清标度常数K：现行CT机K＝1000（Hounsfield标度），早期EMI机曾用K＝500或1000，题目若给出“EMI值”需换算。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0102", "t": "多选题", "s": "关于人体常见组织与介质的CT值，下列描述正确的有", "o": {"A": "水的CT值定义为0 HU，空气约为-1000 HU", "B": "正常肝实质平扫CT值略高于脾脏，两者差值一般在8~10 HU", "C": "脑灰质CT值高于脑白质", "D": "脂肪组织的CT值范围为+30~+50 HU", "E": "骨皮质的CT值上限为+1000 HU，超过该值CT机不能显示"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-102", "kp": "各组织CT值范围", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】A正确：Hounsfield标度以水为0 HU、空气为-1000 HU作两点定标，这是CT值体系的基石。B正确：正常肝实质平扫CT值约50~70 HU，比脾脏高约8~10 HU；若肝脏密度低于脾脏，提示脂肪肝，这是平扫的重要间接判断依据。C正确：脑灰质约32~40 HU、脑白质约25~32 HU，灰质含水量低、密度略高，故灰白质界面可辨。【为什么错】D错误：脂肪为负值组织，CT值约-100~-40 HU；+30~+50 HU接近软组织／肌肉范围。E错误：CT值并无+1000 HU的硬性上限，致密骨皮质可达1000~2000 HU，现代CT的量化范围可扩展至-1024~+3071 HU甚至更宽（扩展标度可到±10000 HU），用于金属与致密骨评价。", "tr": "“肝比脾高8~10 HU”与“脂肪为负值”是平扫判读脂肪肝的两块基石；另注意CT值上限并非1000 HU，扩展CT值范围（extended scale）正是评估金属植入物的手段。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0103", "t": "单选题", "s": "某幅CT图像采用窗宽400 HU、窗位40 HU显示，则该显示条件下能够被分配灰阶、产生密度层次差别的CT值范围是", "o": {"A": "-360~+440 HU", "B": "-160~+240 HU", "C": "-200~+200 HU", "D": "0~+400 HU", "E": "-400~+400 HU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-103", "kp": "窗宽窗位的换算", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】B正确。窗宽上限＝窗位＋窗宽/2＝40＋200＝240 HU；窗宽下限＝窗位－窗宽/2＝40－200＝-160 HU。高于上限者一律显示为纯白、低于下限者一律显示为纯黑，只有区间内的CT值才被分配灰阶。【为什么错】A错误：把窗宽全值（400）而非半值加减到窗位上。C错误：忽略了窗位40 HU的偏移，把窗中心默认为0。D错误：误把窗位当成显示范围的下限起点。E错误：把窗宽数值当成上下限的绝对值，同样忽略窗位。", "tr": "窗位是显示范围的中心而非下限；计算时务必用窗宽的一半加减。考试中常反向命题：给出显示范围-160~+240 HU，反求窗宽（400）与窗位（40）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0104", "t": "多选题", "s": "关于窗技术中窗宽、窗位与灰阶分配的关系，下列正确的有", "o": {"A": "窗宽减小时每一灰阶所代表的CT值差变小，图像对比度提高，但可显示的CT值范围变窄", "B": "窗位升高时显示范围向高密度侧移动，图像整体变暗；窗位降低则整体变亮", "C": "观察肺组织宜用宽窗，常用窗宽1000~1600 HU、窗位-600~-700 HU", "D": "观察脑实质宜用窗宽300~400 HU、窗位35~45 HU", "E": "窗宽窗位在扫描时即已固定，图像重建完成后不能再更改"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-104", "kp": "窗宽窗位与灰阶分配", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】A正确：若显示器灰阶数固定，每一灰阶代表的CT值差＝窗宽/灰阶数，窗宽越窄该差值越小，微小密度差被放大，对比度提高，代价是超出窗外的组织被“压白／压黑”丢失层次。B正确：窗位决定显示窗口在CT值轴上的位置，窗位升高意味着更多低密度结构落到窗下限之外而变黑，整体观感变暗。C正确：肺内空气与血管、间质密度差极大，需宽窗低窗位，常规肺窗为窗宽1000~1600 HU、窗位-600~-700 HU。【为什么错】D错误：窗宽300~400 HU、窗位30~50 HU是纵隔窗参数；脑窗为窗宽80~100 HU、窗位35~45 HU，脑组织灰白质差别仅约8 HU，必须用窄窗。E错误：窗技术是重建后的后处理显示手段，同一套图像数据可任意反复调节窗宽窗位，甚至打印多套窗；真正在扫描时固定的是采集参数。", "tr": "脑窗（80~100/35~45）与纵隔窗（300~400/30~50）的窗宽极易互换记错；记忆抓手是“脑组织灰白质差仅约8 HU，必须窄窗”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0105", "t": "单选题", "s": "某次扫描使用显示野（FOV）350 mm、重建矩阵512×512、重建层厚5 mm。该图像的像素边长与体素体积分别约为", "o": {"A": "0.68 mm、约2.3 mm³", "B": "0.68 mm、约3.4 mm³", "C": "1.37 mm、约9.4 mm³", "D": "0.34 mm、约0.6 mm³", "E": "0.68 mm、约0.47 mm³"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-105", "kp": "体素、像素与矩阵的关系", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】A正确。像素边长＝FOV/矩阵＝350/512≈0.68 mm；体素是像素在Z轴方向延伸一个层厚所构成的三维单元，体素体积＝像素面积×层厚≈0.68×0.68×5≈2.3 mm³。【为什么错】B错误：3.4 mm³是把像素边长（而非面积）乘层厚（0.68×5）所得，少乘了一个边长。C错误：1.37 mm对应256×256矩阵（350/256），与题设512矩阵不符。D错误：0.34 mm对应1024矩阵。E错误：0.47 mm²只是像素面积（0.68²），未乘层厚，且单位应为mm²。", "tr": "像素是二维（面积），体素是三维（含层厚）；同一FOV下矩阵越大像素越小、空间分辨率越高但噪声越大。另注意“采集矩阵”与“显示矩阵”可以不同，像素尺寸应按重建（采集）矩阵计算。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0106", "t": "单选题", "s": "关于部分容积效应与周围间隙现象，下列叙述错误的是", "o": {"A": "部分容积效应指同一体素内含有两种以上不同密度的组织时，所测CT值为各成分的加权平均值", "B": "减薄扫描层厚可减轻部分容积效应带来的CT值失真", "C": "周围间隙现象表现为密度差别较大的两种组织交界处边缘模糊、交界带CT值不准确", "D": "周围间隙现象与部分容积效应在本质上无关，仅由探测器电子噪声引起", "E": "后颅窝、颅底等骨与脑组织交界层面容易因上述效应造成CT值测量偏差"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-106", "kp": "部分容积效应与周围间隙现象", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】本题选错误项，D错误。周围间隙现象（partial volume edge effect）恰恰是部分容积效应在“组织交界带”上的特殊表现形式：当同一层面内两种密度悬殊的组织并存且界面与扫描平面不垂直时，界面附近体素同时包含两种组织，测得CT值介于两者之间，导致边缘模糊、界面CT值失真。它属于成像几何与体素平均问题，并非探测器电子噪声所致。【为什么错】A正确：这是部分容积效应的标准定义，体素内多种成分按体积比加权平均。B正确：层厚越薄，单个体素内混入异质组织的概率越低，效应减轻，这也是薄层扫描／薄层重建的核心价值。C正确：这是周围间隙现象的典型表述。E正确：后颅窝、颅底骨与脑组织密度差极大，界面走行复杂，最易出现该效应并叠加线束硬化伪影。", "tr": "两者是“同源不同表现”：部分容积效应强调CT值被平均，周围间隙现象强调交界处边缘失真。切勿把周围间隙现象归因于噪声或运动；对策共同点都是减薄层厚。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0107", "t": "单选题", "s": "某16排CT采用16×1.25 mm探测器组合，机架旋转一周时间为0.5 s，检查床进床速度为27.5 mm/s。该扫描的螺距（探测器组合螺距，beam pitch）为", "o": {"A": "0.34", "B": "0.69", "C": "1.10", "D": "1.38", "E": "11.0"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-107", "kp": "多层螺旋CT螺距的计算", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】B正确。多层螺旋CT的螺距（beam pitch）＝机架旋转一周检查床移动距离/（探测器排数×单个探测器宽度，即总准直宽度）。每周进床距离＝27.5 mm/s×0.5 s＝13.75 mm；总准直宽度＝16×1.25＝20 mm；螺距＝13.75/20≈0.69。【为什么错】A错误：0.34系误将旋转时间当作0.25 s计算。C错误：1.10为按12.5 mm准直（10×1.25）计算的结果，排数取错。D错误：1.38系直接用每秒进床距离27.5 mm除以总准直20 mm，漏乘旋转时间。E错误：11.0是层螺距（slice pitch/detector pitch）＝每周进床距离/单个探测器宽度＝13.75/1.25，其数值等于beam pitch的16倍，两者定义不同不可混用。", "tr": "多层CT有两种螺距：探测器组合螺距（分母为总准直宽度，国际通用、也是机器显示值）与层螺距（分母为单层准直宽度，数值＝排数×组合螺距）。见到“11.0”这类远大于1的数值，多半是层螺距而非常用螺距。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0108", "t": "多选题", "s": "关于CT扫描中的准直（collimation）及其影响，下列正确的有", "o": {"A": "准直宽度决定X线束在Z轴方向的宽度，是影响Z轴空间分辨率的重要因素", "B": "缩小准直宽度可减少散射线并减轻部分容积效应", "C": "多层螺旋CT可重建的最薄层厚不能小于单个探测器单元对应的准直宽度", "D": "其他条件不变时，缩小准直宽度可使图像噪声降低", "E": "准直器仅设置在探测器侧，球管侧不需要准直"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-108", "kp": "准直的作用与限制", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】A正确：准直限定X线束沿Z轴的宽度，直接决定层面敏感度曲线（SSP）的宽度，是Z轴分辨率的物理上限。B正确：准直越窄，进入受检体的射线束越窄，散射线产生减少；同时体素在Z轴变薄，异质组织混合减少，部分容积效应减轻。C正确：探测器单元宽度是硬件下限，重建层厚只能等于或大于它（如0.625 mm探测器最薄重建0.625 mm），不可能凭插值“无中生有”出更薄的真实层厚。【为什么错】D错误：方向相反。准直变窄→单个体素接收光子数减少→噪声升高，欲维持噪声水平须相应增加mAs，这正是薄层扫描剂量代价的来源。E错误：CT在球管侧（前准直器，限制射线束宽度与剂量）和探测器侧（后准直器，抑制散射）通常均设准直装置，多层CT尤其重视球管侧的动态准直（如自适应剂量屏蔽减少螺旋两端的过扫描剂量）。", "tr": "“薄层＝低剂量”是常见错觉：薄准直本身并不降低剂量，反而为压制噪声常需提高mAs。Z轴分辨率提高与噪声增加是一对必然的权衡。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0109", "t": "单选题", "s": "关于重建层厚与重建间隔（重建增量）的关系，下列说法错误的是", "o": {"A": "重建间隔小于重建层厚时称为重叠重建", "B": "重叠重建可改善多平面重组与三维重组图像质量、减轻阶梯状伪影", "C": "重叠重建利用同一次采集的原始数据完成，不增加患者的辐射剂量", "D": "重建层厚可以任意设置为小于探测器单元准直宽度的数值", "E": "层厚不变时，仅改变重建间隔不会改变单幅图像的噪声水平"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-109", "kp": "重建层厚与重建间隔", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】本题选错误项，D错误。重建层厚受探测器单元宽度这一硬件条件限制，最薄只能等于单排探测器对应的准直宽度，不能任意变薄；能自由设定的是重建间隔。【为什么错】A正确：重建间隔＜层厚即为重叠重建，常用重叠量为层厚的30%~50%。B正确：重叠重建使Z轴采样更密，MPR/VR/CPR的连续性更好，可显著减轻楼梯状（阶梯）伪影，是三维后处理与血管成像的常规做法。C正确：重叠重建只是对已采集的原始数据以更小间隔再次插值重建，射线曝光已经结束，不增加任何辐射剂量，仅增加图像数量与存储／传输负荷。E正确：噪声主要由层厚、mAs、kV、卷积核和算法决定，与相邻图像间的排列间隔无关。", "tr": "牢记“重叠重建不增加剂量、只增加图像数量”；而减薄重建层厚虽然也不增加已完成扫描的剂量，却会提高噪声。二者的代价不同，勿混。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0110", "t": "多选题", "s": "关于CT重建中卷积核（重建算法）的选择，下列正确的有", "o": {"A": "软组织核（平滑核）图像噪声低、密度分辨率好，适用于脑实质和纵隔观察", "B": "骨核（高分辨率核）使边缘锐利、空间分辨率提高，但图像噪声明显增大", "C": "同一次采集的原始数据可用不同卷积核重建出多套图像，无须重复扫描、不增加辐射剂量", "D": "观察肺间质细微结构应选用软组织核以降低噪声", "E": "观察肝内小的低密度病灶宜选用骨核以提高检出率"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-110", "kp": "卷积核与重建算法选择", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】A正确：软组织核对高频成分做抑制（平滑），噪声低、密度分辨率（低对比分辨率）好，适合脑实质、纵隔、肝脾等低对比结构。B正确：骨核强化高频，边缘锐利、空间分辨率高，代价是噪声显著上升，适用于骨皮质、内耳、肺间质等高对比结构。C正确：卷积核作用于原始投影数据的重建过程，只要保留原始数据即可反复用不同核重建，剂量不变——这正是“一次扫描、多套重建”的技术基础，如颞骨同时出骨算法与软组织算法。【为什么错】D错误：肺间质属于高对比结构，必须用高分辨率（肺/骨）核，用软组织核会使小叶间隔、支气管壁模糊，是HRCT的原则性错误。E错误：肝内小低密度灶是典型的低对比病变，骨核带来的高噪声会淹没微弱密度差，反而降低检出率，应选软组织核甚至更平滑的核。", "tr": "口诀：高对比结构（骨、肺、内耳）用锐利核，低对比结构（脑、肝、纵隔软组织）用平滑核。核的选择改变的是“噪声—空间分辨率”的分配，而不是采集到的信息量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0111", "t": "单选题", "s": "某腹部CT图像噪声偏大，拟在管电压、层厚、卷积核等其他条件均不变的前提下，将图像噪声（标准差）降至原来的1/2，管电流时间积（mAs）应调整为原来的", "o": {"A": "1/4", "B": "1/2", "C": "2倍", "D": "4倍", "E": "8倍"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-111", "kp": "噪声与mAs的平方根关系", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】D正确。CT图像噪声源于光子统计涨落，噪声标准差σ与探测到的光子数N的平方根成反比，而N正比于mAs，故σ∝1/√mAs。欲使σ降为原来的1/2，需要√mAs增大2倍，即mAs增至原来的4倍（同时患者剂量也增至4倍）。【为什么错】A错误：mAs降至1/4会使噪声增大到原来的2倍，方向完全相反。B错误：mAs减半噪声反而升高约1.41倍。C错误：mAs加倍只能使噪声降至原来的约0.71倍（1/√2），达不到减半。E错误：8倍mAs可使噪声降至约0.35倍，超出需求且剂量代价过大，不符合ALARA原则。", "tr": "记住“噪声减半＝剂量四倍”这一昂贵关系，这正是迭代重建与深度学习重建的价值所在——在不增加mAs的前提下降低噪声。另注意噪声与层厚也呈平方根关系（层厚减半，噪声增至1.41倍）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0112", "t": "案例分析题", "s": "患者男性，58岁，因不典型胸痛行冠状动脉CTA。检查前心率72次/分，口服美托洛尔后降至62次/分，但心律不齐、偶发室性早搏。技师采用回顾性心电门控螺旋方式完成采集，对比剂与盐水双筒注射，图像强化满意。重建后发现右冠状动脉中段在多个期相均出现明显的错层（阶梯状）伪影，回放心电曲线可见扫描过程中出现2次室性早搏及其后的代偿间歇，早搏处的R波标记位置与实际心动周期不匹配。在不追加扫描的前提下，此时最合适的技术处理是", "o": {"A": "使用心电编辑功能，对早搏及代偿间歇处错误的R波标记进行删除或位移后重新标记，再分别在收缩末期（约40%）与舒张中晚期（约75%）重建择优", "B": "立即重新扫描一次，并将重建期相固定于R-R间期0%以避开早搏", "C": "改用平滑卷积核并加大迭代重建强度，以掩盖错层伪影", "D": "将原始数据改按前瞻性心电触发方式重建，可自动纠正早搏造成的期相错位", "E": "把重建期相统一改为R-R间期10%，该期相不受心律变化影响"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-112", "kp": "心电编辑与最佳重建期相", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】A正确。回顾性门控的最大优势是原始数据覆盖整个心动周期，可在重建阶段做心电编辑：常用手段包括删除（disable/delete）早搏处的错误R波、插入（insert）漏检的R波、位移（shift/relabel）标记位置以及禁用某段异常心搏数据。将早搏与代偿间歇的标记纠正后，各扇区数据才能落在同一真实心动时相，错层伪影可显著减轻；再在收缩末期35%~45%与舒张中晚期70%~80%两个相对静止窗分别重建择优，是标准处理流程。【为什么错】B错误：先做心电编辑属零剂量补救，未尝试即重扫违背ALARA；且R-R间期0%正处于R波顶点、心脏运动剧烈，不是静止期。C错误：平滑核和迭代重建只能降噪，对运动错层这类数据不一致性伪影无效，反而模糊血管边缘。D错误：前瞻性触发是采集时的曝光策略，一旦扫描完成不能“改按”前瞻方式重建；而且前瞻性触发对早搏更敏感，本身需要靠自动早搏抑制／补扫功能应对。E错误：不存在“不受心律影响”的期相，10%时相处于等容收缩期，冠脉运动幅度大，是最差选择之一。", "tr": "心电编辑只能在回顾性门控（全期相原始数据）上施行，前瞻性触发扫描无数据可编辑。另记两个静止窗：低心率取舒张中晚期70%~80%，高心率／心律不齐时收缩末期35%~45%常更可靠（尤其右冠）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0113", "t": "单选题", "s": "关于CT平扫的概念，下列描述正确的是", "o": {"A": "平扫是指不注射对比剂的常规CT扫描，又称普通扫描或非增强扫描", "B": "平扫是指仅使用低剂量参数完成的扫描", "C": "平扫只能采用轴位逐层（非螺旋）方式采集", "D": "平扫图像因未使用对比剂，不能进行CT值测量", "E": "平扫必须安排在增强扫描之后完成"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-113", "kp": "CT平扫的概念", "ch": "九、CT检查技术 → 2.检查方法 → (1)平扫", "ex": "【为什么对】A正确。平扫（plain scan）指不注射血管内对比剂、按预定参数直接完成的扫描，亦称普通扫描、非增强扫描，是绝大多数CT检查的第一步和增强扫描的对照基准。【为什么错】B错误：低剂量扫描是剂量策略（如肺癌筛查LDCT），与用不用对比剂无关，低剂量增强同样存在。C错误：平扫既可轴位逐层采集，也可螺旋容积采集，现代多层CT平扫多用螺旋方式以便薄层重建。D错误：平扫恰恰是CT值测量最重要的基线，脂肪肝、血肿、结石、钙化、脂肪成分（如AML）的判断都依赖平扫CT值。E错误：顺序相反，常规是先平扫、后增强，平扫为增强提供对照并帮助确定扫描范围与时相；仅在个别急诊CTA等情形下可省略平扫。", "tr": "腹部平扫前常口服水或稀释对比剂充盈胃肠道，这仍属平扫范畴——“平扫”特指未经血管内注射对比剂，勿因口服阴性／阳性对比剂而误判为增强。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0114", "t": "多选题", "s": "下列临床情况中，CT平扫即可基本满足首要临床需求的有", "o": {"A": "急性颅脑外伤，需排除颅内血肿", "B": "急性腰腹绞痛，需排除输尿管结石", "C": "胸部外伤，需明确有无肋骨骨折与气胸", "D": "肝内发现小占位，需要定性诊断", "E": "颈部肿块，需评估病变与颈动脉的关系"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-114", "kp": "CT平扫的适应证与局限", "ch": "九、CT检查技术 → 2.检查方法 → (1)平扫", "ex": "【为什么对】A正确：急性期血肿因血红蛋白浓聚呈高密度（约60~80 HU），与脑实质天然对比良好，平扫即可诊断，且急诊快速、无对比剂风险。B正确：绝大多数尿路结石为高密度，平扫（低剂量泌尿系CT）敏感性极高，注射对比剂后反而会因肾盂内对比剂遮蔽结石。C正确：骨折与气胸依赖骨窗、肺窗的高对比显示，平扫即可，增强对此无额外价值。【为什么错】D错误：肝内小占位的定性依赖多期增强的强化方式（如肝细胞癌“快进快出”、血管瘤渐进性向心填充），平扫只能发现病灶、难以定性。E错误：颈部肿块与颈动脉、颈内静脉的关系需要血管强化后才能清晰分界，平扫时血管与肿块及淋巴结均为相近的软组织密度，难以区分。", "tr": "判断能否只做平扫的思路是“病变与背景之间是否已有足够的天然密度差”：出血、钙化、结石、脂肪、骨与气体属天然高对比，可平扫；等密度软组织病变与血管的鉴别必须增强。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0115", "t": "案例分析题", "s": "患者男性，34岁，高处坠落伤后1小时急诊就诊，意识模糊，GCS评分11分，枕部头皮血肿，生命体征平稳，颈托固定中。急诊要求快速排除颅内出血与颅骨骨折，设备为64排CT。以下检查方案中最合适的是", "o": {"A": "行头颅CT平扫，范围自枕骨大孔（颅底）至颅顶，薄层螺旋采集后同时以软组织核和骨核重建，并加做冠状面、矢状面重组", "B": "行头颅CT增强扫描，利用血管强化提高出血检出率", "C": "行头颅CT平扫，层厚10 mm逐层采集，只做软组织核重建", "D": "先行头颅CT灌注成像，判断有无缺血半暗带后再决定是否平扫", "E": "先行颅脑MRI以避免电离辐射，CT留待复查时进行"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-115", "kp": "急诊颅脑外伤平扫方案", "ch": "九、CT检查技术 → 2.检查方法 → (1)平扫", "ex": "【为什么对】A正确。急性颅脑外伤的首选是平扫：急性血肿呈高密度，无需对比剂；薄层螺旋采集可在不增加剂量的前提下用同一原始数据分别以软组织核（观察脑实质、血肿）和骨核（观察颅骨骨折、颅底与鼻窦积液）重建，并做冠状／矢状重组，能显著提高与扫描平面平行的线性骨折和薄层硬膜下血肿的检出率；范围应包全颅底至颅顶，避免漏诊后颅窝与颅顶凸面病变。【为什么错】B错误：增强对急性出血的检出无帮助，反而可能使强化血管与小血肿混淆，且外伤急诊使用对比剂增加不必要风险。C错误：10 mm厚层容易漏诊薄层硬膜下血肿与颅底骨折，且无骨算法重建不利于骨折评价。D错误：CT灌注用于缺血性卒中评估，不是外伤首选，且剂量高、耗时长，延误抢救。E错误：MRI检查时间长、急诊可及性差、对急性出血与骨折的显示不如CT，且躁动患者难以配合，不适合作为外伤首查。", "tr": "“一次薄层采集、双核重建、多平面重组”是现代颅脑外伤的标准动作，能零剂量代价提高骨折检出。注意不要为了看骨折而追加一次骨算法扫描——只需重建，不需重扫。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0116", "t": "案例分析题", "s": "患者女性，52岁，常规胸部CT（层厚5 mm）发现右肺上叶一枚约8 mm的磨玻璃结节，临床需进一步评价其内部结构（有无实性成分、空泡征、胸膜牵拉及与血管的关系），设备为64排CT。以下技术方案最合适的是", "o": {"A": "对结节所在区域行小FOV靶扫描或靶重建，采用≤1 mm薄层、高分辨率算法，并行MPR与最小密度投影观察", "B": "把原有5 mm层厚图像在工作站上电子放大4倍后观察", "C": "追加胸部增强扫描门静脉期成像以评价结节强化", "D": "把螺距增大至1.5并改用平滑核重建，以降低噪声、突出结节", "E": "行胸部CT灌注成像定量评价结节血供"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-116", "kp": "靶扫描与靶重建", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】A正确。靶扫描（放大扫描）／靶重建的实质是缩小显示野，在矩阵不变的前提下使像素边长变小（像素＝FOV/矩阵），从而真正提高空间分辨率；配合≤1 mm薄层与高分辨率算法，可清晰显示磨玻璃结节内的实性成分、空泡、支气管充气征与胸膜牵拉，MPR和MinIP有助于判断与血管、胸膜的关系。【为什么错】B错误：工作站电子放大只是把已有像素等比放大，信息量不增加，只会出现马赛克样放大伪影，与靶重建有本质区别。C错误：门静脉期时相针对腹部脏器，对肺小结节评价无意义；且8 mm磨玻璃结节的强化测量不可靠，指南推荐以薄层随访和体积测量为主。D错误：增大螺距会降低Z轴采样密度、加重层面敏感度曲线增宽，平滑核进一步降低空间分辨率，与需求背道而驰。E错误：CT灌注辐射剂量高，主要用于脑卒中与部分肿瘤血流动力学研究，对8 mm磨玻璃结节既不必要也不可靠。", "tr": "务必区分“靶重建（缩小FOV重建，像素变小、分辨率真提高）”与“图像放大（后处理插值，分辨率不变）”。靶重建可用原始数据完成，不需要再次曝光；只有需要改变采集几何时才做真正的靶扫描。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0117", "t": "单选题", "s": "关于CT薄层扫描（薄层采集与薄层重建），下列描述正确的是", "o": {"A": "薄层的主要目的是减轻部分容积效应、提高Z轴分辨率，有利于小病灶与细微结构的显示", "B": "薄层扫描在其他参数不变时可同时降低图像噪声和辐射剂量", "C": "薄层只能通过缩小显示野实现", "D": "薄层图像不适合用于多平面重组和三维后处理", "E": "薄层扫描的层厚通常指相邻两层图像中心之间的距离"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-117", "kp": "薄层扫描技术", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】A正确。薄层的核心价值在于缩小体素的Z轴尺寸，减少同一体素内异质组织的混合，从而减轻部分容积效应、提高Z轴空间分辨率，使小结节、微小骨折、内耳与垂体等细微结构得以显示。【为什么错】B错误：层厚减薄使单个体素接收光子数减少，噪声按1/√层厚规律升高；欲维持噪声水平需提高mAs，剂量不降反升。C错误：缩小显示野改变的是层面内（XY方向）的像素大小，属靶重建范畴；层厚由准直宽度与重建层厚决定，二者不是一回事。D错误：恰恰相反，薄层（各向同性体素）是高质量MPR、VR、CPR后处理的前提，厚层重组会产生明显阶梯状伪影。E错误：相邻图像中心间的距离是重建间隔（重建增量），层厚指单幅图像所代表的Z轴厚度，二者可以不相等（重叠重建时间隔＜层厚）。", "tr": "薄层降低的是部分容积效应，不是噪声；层厚与重建间隔是两个独立参数，命题常在此互换设陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0118", "t": "多选题", "s": "关于胸部高分辨率CT（HRCT）的技术要点，下列正确的有", "o": {"A": "采用薄层（一般1~1.5 mm）与高空间分辨率（骨/肺）算法重建", "B": "适当缩小显示野做靶重建，可进一步提高细微结构的显示能力", "C": "怀疑小气道病变时可加扫呼气末图像，用以显示空气潴留", "D": "为鉴别肺底坠积效应与早期间质纤维化，可加扫俯卧位图像", "E": "为降低噪声，HRCT应选用软组织平滑核并适当增大层厚"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-118", "kp": "高分辨率CT（HRCT）技术", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】A正确：HRCT的两大支柱就是薄层（1~1.5 mm）与高分辨率算法，用于显示小叶间隔、小叶核心、支气管壁等亚毫米级结构。B正确：靶重建缩小FOV使像素变小，在矩阵不变时空间分辨率进一步提高，常用于单侧肺或局部病灶精查。C正确：呼气末扫描时正常肺组织密度升高，而小气道阻塞区因空气潴留密度不升，出现“马赛克”样密度差，是诊断闭塞性细支气管炎的关键征象。D正确：仰卧位肺底后部的坠积性密度增高在俯卧位可消散，而真正的间质病变（如早期特发性肺纤维化的胸膜下网格影）不随体位改变，这是HRCT的经典鉴别手段。【为什么错】E错误：肺属于高对比结构，必须用高分辨率锐利核；改用平滑核并加大层厚会使小叶间隔与细支气管壁模糊，从根本上破坏HRCT的目的。噪声偏大在HRCT中是可接受的代价，必要时通过提高mAs或迭代重建解决。", "tr": "HRCT是“高分辨率”而非“低噪声”的技术，任何以降噪为名改用平滑核、加厚层厚的做法都是错的。另注意呼气相与俯卧位是两个不同目的的附加体位，不可混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0119", "t": "单选题", "s": "某成人胸部CT扫描后机器显示剂量长度乘积（DLP）为250 mGy·cm，已知成人胸部的有效剂量转换因子k约为0.014 mSv/(mGy·cm)。该次检查的有效剂量约为", "o": {"A": "0.35 mSv", "B": "1.75 mSv", "C": "3.5 mSv", "D": "17.9 mSv", "E": "35 mSv"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-119", "kp": "CT剂量指标与有效剂量估算", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】C正确。有效剂量E（mSv）≈DLP（mGy·cm）×k，k为与解剖部位相关的转换因子。250×0.014＝3.5 mSv。【为什么错】A错误：0.35 mSv系小数点错位（按0.0014计算）。B错误：1.75 mSv相当于把DLP误取为125 mGy·cm。D错误：17.9 mSv是用250除以14所得，属公式误用。E错误：35 mSv是把k误当作0.14，量级偏大10倍，已接近介入手术的剂量水平，与常规胸部CT不符。", "tr": "分清三个剂量指标：CTDIvol（mGy，反映扫描层面的剂量强度）、DLP＝CTDIvol×扫描长度（mGy·cm，反映总受照量）、有效剂量E＝DLP×k（mSv，反映随机性效应风险）。k值随部位变化（头部约0.0021、胸部约0.014、腹盆约0.015），儿童更高。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0120", "t": "单选题", "s": "关于延迟扫描与动态扫描，下列说法错误的是", "o": {"A": "延迟扫描指在常规增强各期结束后，间隔数分钟乃至更长时间再进行的扫描", "B": "肝血管瘤的“渐进性向心填充”常需延迟5~10分钟甚至更久才能显示完全充填", "C": "CT尿路造影的排泄期属于延迟扫描的应用之一", "D": "动态扫描是指在对比剂注射后对同一或多个层面进行的连续、多次重复扫描，可获得时间-密度曲线", "E": "动态扫描与延迟扫描含义相同，只是名称不同"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-120", "kp": "延迟扫描与动态扫描", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】本题选错误项，E错误。二者概念不同：动态扫描强调“短时间内高频率重复采集”，用于观察对比剂首过与early强化动力学、绘制时间-密度曲线（如垂体微腺瘤动态增强、CT灌注）；延迟扫描强调“延后单次或数次采集”，用于观察对比剂缓慢充填或经泌尿道／胆道排泄的过程。【为什么错】A正确：这是延迟扫描的定义，延迟时间从数分钟到十余分钟不等。B正确：血管瘤延迟填充是其定性依据，延迟不足是误诊为乏血供转移瘤的常见原因。C正确：CTU排泄期通常在注药后5~10分钟采集，正是延迟扫描的典型应用。D正确：动态扫描含同层动态与进床式动态两种方式，是获取TDC与灌注参数的基础。", "tr": "“动态＝快而密（看流入）”，“延迟＝慢而晚（看填充与排泄）”。垂体、肾上腺、血管瘤三类病变常同时用到动态与延迟，答题时须按临床目的判断。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0121", "t": "单选题", "s": "患者体重70 kg，腹部增强CT按1.5 ml/kg给药，选用碘浓度350 mgI/ml的非离子型对比剂。该患者的对比剂用量与所注入的碘总量分别约为", "o": {"A": "70 ml、24.5 gI", "B": "105 ml、36.8 gI", "C": "105 ml、3.68 gI", "D": "140 ml、49.0 gI", "E": "105 ml、368 gI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-121", "kp": "对比剂总量与碘总量计算", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】B正确。对比剂体积＝1.5 ml/kg×70 kg＝105 ml；碘总量＝体积×浓度＝105 ml×350 mgI/ml＝36750 mgI≈36.8 gI。【为什么错】A错误：按1.0 ml/kg计算得70 ml，与题设剂量方案不符。C错误：3.68 gI是单位换算错误（少除或多除1000），105 ml×350 mgI/ml不可能只有3.68 g碘。D错误：140 ml相当于2.0 ml/kg，超出题设方案。E错误：368 gI量级错误，如此碘量远超人体安全上限（成人单次碘负荷一般不宜超过约1.5 gI/kg，本例上限约105 gI，而实际给药36.8 gI）。", "tr": "碘总量＝体积（ml）×浓度（mgI/ml）÷1000（gI）。评价对比剂负荷时应关注“碘总量／体重”而不仅是毫升数，同样100 ml，370 mgI/ml比300 mgI/ml多输入约7 g碘。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0122", "t": "单选题", "s": "某冠状动脉CTA方案使用碘浓度370 mgI/ml的对比剂、注射流率5.0 ml/s。因患者外周静脉条件差，改用碘浓度300 mgI/ml的对比剂，若要维持原方案的碘流率不变，注射流率应调整为", "o": {"A": "约4.1 ml/s", "B": "约5.0 ml/s", "C": "约6.2 ml/s", "D": "约7.4 ml/s", "E": "约1.85 ml/s"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-122", "kp": "碘流率概念与换算", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】C正确。碘流率（iodine delivery rate）＝碘浓度（mgI/ml）×注射流率（ml/s），是决定血管内峰值强化程度的关键量。原方案碘流率＝370×5.0＝1850 mgI/s＝1.85 gI/s；改用300 mgI/ml后，所需流率＝1850/300≈6.2 ml/s。【为什么错】A错误：4.1 ml/s是按5.0×300/370反向换算，方向搞反，会使碘流率下降。B错误：单纯保持5.0 ml/s时碘流率降至1500 mgI/s，血管强化明显下降，不能满足冠脉CTA对峰值CT值（通常要求≥300 HU）的要求。D错误：7.4 ml/s对应碘流率2220 mgI/s，高于原方案，且外周静脉难以承受，增加渗漏风险。E错误：1.85 ml/s是把碘流率的数值（1.85 gI/s）误当成体积流率。", "tr": "降低浓度必须提高流率才能维持碘流率——但患者的静脉条件是硬约束。当流率无法提高时，可改用低管电压（如80~100 kVp）提高碘的对比效率来代偿，这是低剂量、低碘负荷方案的核心思路。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0123", "t": "多选题", "s": "关于增强扫描中使用生理盐水“后推”（盐水冲刷）技术，下列正确的有", "o": {"A": "可把停留在上肢静脉、锁骨下静脉内的对比剂推入中心循环，提高对比剂利用率", "B": "有助于减少上腔静脉内高浓度对比剂造成的线束硬化伪影", "C": "可使团注更加紧凑，在总量减少的情况下维持相近的强化峰值", "D": "需要使用双筒（双头）高压注射器，或在单筒注射后手动推注", "E": "盐水后推的主要作用是稀释血液中的对比剂，从而降低对比剂肾病的发生率"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-123", "kp": "生理盐水后推技术", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】A正确：一次注射中约有20~30 ml对比剂滞留在上肢与中心静脉通路内，盐水将其“推”入循环，等效于增加了有效剂量。B正确：上腔静脉、头臂静脉内高浓度对比剂是胸部CTA和冠脉CTA中条纹状硬化伪影的主要来源，盐水冲刷可稀释并置换之，改善右心与右冠近段的显示。C正确：盐水维持了团注柱的连续性，减少团注尾部拖尾，故可在减少10%~20%用量的同时保持峰值强化，这是低碘负荷方案的基础。D正确：临床通过双筒高压注射器实现自动化盐水冲刷，条件不具备时可人工序贯推注，但同步性差。【为什么错】E错误：盐水后推的作用是流体动力学层面的，其量（20~40 ml）不足以显著稀释体循环，也未被证实能降低对比剂肾病发生率；预防对比剂肾病依靠的是控制碘负荷、充分水化和高危人群筛查。", "tr": "把盐水冲刷的“减伪影、省用量”作用与“防肾病”混为一谈是常见错误。真正减少肾脏碘负荷的是降低总碘量本身，而不是随后的几十毫升盐水。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0124", "t": "单选题", "s": "关于团注追踪技术（bolus tracking）的操作要点，下列说法错误的是", "o": {"A": "监测层面的ROI应置于目标血管腔内，避开管壁、钙化斑块与周围结构", "B": "触发阈值常设定在100~150 HU，达到阈值后系统自动或由技师手动启动诊断性扫描", "C": "从触发到正式扫描开始之间存在数秒的诊断延迟，用于床位移动与呼吸指令", "D": "监测扫描应使用与诊断扫描相同的管电流，以保证监测图像质量", "E": "监测过程中若患者呼吸移动导致ROI偏离血管腔，可能出现触发失败或提前触发"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-124", "kp": "团注追踪技术", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】本题选错误项，D错误。监测扫描（同层重复曝光）只用于观察ROI内CT值的变化趋势，不需要诊断级图像质量，必须使用很低的管电流（通常仅为诊断扫描的1/10左右，如20~50 mAs）并适当延长采样间隔，否则累积剂量相当可观。【为什么错】A正确：ROI必须完全落在血管腔内，压到管壁或钙化会使测得CT值偏高而提前触发。B正确：不同部位阈值略有差异（如冠脉／主动脉常用100 HU左右，头颈CTA常用100 HU），达到阈值即触发。C正确：诊断延迟包含床移动、语音呼吸指令与曝光准备时间，一般3~8 s，是决定扫描时相是否准确的关键参数，冠脉与肺动脉方案会尽量压缩该延迟。E正确：呼吸或体动使ROI移出血管是触发失败的常见原因，故监测期间应先完成呼吸指令、并由技师全程盯守以便随时手动触发。", "tr": "团注追踪的三要素：ROI位置、阈值、诊断延迟。监测扫描务必低剂量；同时技师必须准备好“手动触发”作为自动触发失败时的补救，这是实践中最重要的应急动作。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0125", "t": "多选题", "s": "关于团注追踪（bolus tracking）与小剂量测试（test bolus）两种时相确定方法的比较，下列正确的有", "o": {"A": "小剂量测试先注射10~20 ml对比剂并在同一层面低剂量动态采集，取时间-密度曲线峰值时间来推算扫描延迟", "B": "团注追踪不需额外注射对比剂，可实时反映本次团注的循环状态", "C": "小剂量测试会额外增加对比剂用量和辐射剂量，检查时间延长", "D": "对心功能不全、循环时间明显异常或大动脉瘤样扩张的患者，小剂量测试往往更能获得可靠的个体化延迟时间", "E": "团注追踪的准确性不受心律不齐、呼吸配合和ROI放置的影响"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-125", "kp": "团注追踪与小剂量测试的比较", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】A正确：test bolus用小剂量“预演”循环，测出对比剂自注射至目标血管的达峰时间，再据此设定正式扫描延迟，可精确到秒级。B正确：bolus tracking在正式团注的同时实时监测，反映的就是本次注射的真实循环状态，无须额外用药。C正确：小剂量测试需多注射10~20 ml对比剂，并增加一段低剂量监测扫描与操作时间，是其主要代价。D正确：心排量低、房颤、巨大动脉瘤或血栓形成的患者，对比剂到达时间与峰值形态个体差异极大，阈值触发容易过早或过晚，此时用test bolus获得实测峰值时间更稳妥；一些冠脉方案也用其规避低心排导致的强化不足。【为什么错】E错误：团注追踪高度依赖ROI放置准确、患者屏气配合与呼吸位置稳定，心律不齐、体动、ROI压到管壁或血栓均可导致触发失败或错误触发，因此必须准备手动触发预案。", "tr": "两法核心区别：test bolus测的是“时间”（用小剂量预演），bolus tracking测的是“浓度”（等到阈值就扫）。前者精准但费药费时，后者快捷但受触发条件影响，二者并非优劣关系而是适应人群不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0126", "t": "案例分析题", "s": "患者男性，62岁，体重80 kg，行上腹部增强CT评价肝脏病变。技师使用碘浓度300 mgI/ml对比剂100 ml，注射流率2.5 ml/s，采用固定延迟法在注药后30 s、70 s采集动脉期与门静脉期。图像显示动脉期腹主动脉及肝动脉强化程度偏低，肝实质动脉期强化不足，影响富血供小病灶的检出。在总碘量不变的前提下，下列改进措施中最合理的是", "o": {"A": "提高注射流率至4.0~5.0 ml/s，缩短注射时间以提高峰值强化，并改用团注追踪确定动脉期时相", "B": "把注射流率降至1.5 ml/s，延长注射时间以使强化更加平稳", "C": "把动脉期延迟固定改为45 s，其余方案不变", "D": "改用高浓度对比剂同时把流率降至2.0 ml/s，以保证患者安全", "E": "增大扫描层厚并改用平滑核，以提高图像信噪比来弥补强化不足"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-126", "kp": "注射流率与强化峰值的关系", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】A正确。在总碘量固定时，血管内峰值强化主要由碘流率（浓度×流率）决定：提高流率使单位时间进入循环的碘量增加，峰值强化升高、达峰时间提前，团注更紧凑，动脉期对比更佳；同时因达峰提前，固定30 s延迟不再适用，应改用团注追踪（腹主动脉ROI，阈值约100 HU）个体化触发。【为什么错】B错误：降低流率使碘流率进一步下降，峰值强化更低，动脉期显示更差，只适用于需要长时间平稳强化的特殊场景。C错误：单纯延后到45 s并未提高峰值强化，反而可能错过动脉晚期最佳窗口，进入肝实质开始强化的阶段。D错误：提高浓度同时降低流率，碘流率可能不升反降（300×2.5＝750 vs 370×2.0＝740 mgI/s），并未解决问题。E错误：加厚层厚、平滑核只改善噪声，不能提高血管与病灶间的碘对比，且牺牲了小病灶检出所需的空间分辨率。", "tr": "血管峰值强化看“碘流率”，实质（肝、脾）总体强化程度更取决于“碘总量/体重”。改善动脉期靠提高流率＋精准触发，改善肝实质强化靠增加总碘量或降低kV。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0127", "t": "案例分析题", "s": "患者女性，68岁，体重95 kg，2型糖尿病，长期口服二甲双胍，血肌酐轻度升高，估算肾小球滤过率（eGFR）为45 ml/(min·1.73 m²)。临床申请腹部增强CT以排查胰腺占位。患者一般情况尚可，外周静脉通路为右肘正中静脉20 G留置针。下列检查方案中最合理的是", "o": {"A": "选用低渗（次高渗）或等渗非离子型碘对比剂，按体重计算但控制碘总量，采用低管电压（80~100 kVp）配合迭代重建以在减少碘负荷的同时保证强化，检查前后适当水化，并按规范评估二甲双胍的停用与复查", "B": "因eGFR低于60，绝对禁忌使用碘对比剂，改行腹部平扫加超声随访", "C": "按体重上限给足对比剂并提高至6 ml/s快速注射，以保证胰腺期强化", "D": "改用离子型高渗对比剂，其价格低、显影浓度高，适合肥胖患者", "E": "检查前常规做碘过敏试验，阴性者按常规剂量注射即可，无须其他处理"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-127", "kp": "肾功能减退与肥胖患者的增强方案", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】A正确。该患者兼有肥胖（衰减大、需要更高强化）和肾功能中度减退（需要限制碘负荷）两个相互矛盾的需求，解决之道是“降kV提效率”：管电压降至80~100 kVp后，X线平均能量更接近碘的K缘（33.2 keV），碘的对比效率显著提高，可在减少10%~30%碘量的前提下获得同等甚至更高的强化，噪声上升由迭代重建代偿；同时选用低渗或等渗非离子型对比剂、控制总碘量、检查前后水化，并按规范处理二甲双胍。【为什么错】B错误：eGFR 45并非碘对比剂的绝对禁忌，一般以eGFR＜30 ml/(min·1.73 m²)或急性肾损伤为高危界限，30~44之间需权衡获益与风险并加强防护，不应一概拒检而延误肿瘤诊断。C错误：既超量增加碘负荷又用6 ml/s的高流率，20 G留置针与老年血管难以承受，渗漏风险高。D错误：离子型高渗对比剂不良反应率与肾毒性风险均高于非离子型低渗对比剂，现已不推荐用于静脉增强，尤其是肾功能不全者。E错误：碘过敏试验不能预测过敏样反应、已不推荐常规进行；且本例的核心风险是对比剂肾病与二甲双胍相关问题，不是靠皮试能解决的。", "tr": "肥胖＋肾功能减退的最佳解法是“低kV＋迭代重建”，而不是简单加量或直接拒检。二甲双胍本身不损肾，风险在于肾功能急性恶化时可能诱发乳酸酸中毒，故按eGFR分层决定是否停药与复查，而非一律停用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0128", "t": "单选题", "s": "关于CT灌注成像的基本参数，下列关系式正确的是", "o": {"A": "CBF＝CBV×MTT", "B": "CBF＝CBV/MTT", "C": "CBV＝CBF×TTP", "D": "MTT＝CBF×CBV", "E": "CBV＝MTT/CBF"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-128", "kp": "CT灌注参数间的关系", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】B正确。依据中心容积定理（central volume principle）：CBF＝CBV/MTT，即脑血流量等于脑血容量除以平均通过时间。CBV单位为ml/100 g，MTT单位为s，CBF单位为ml/(100 g·min)（需做时间单位换算）。这一关系是理解卒中灌注异常的核心：血管狭窄早期MTT延长而CBV靠侧支与自动调节代偿性维持或轻度升高，CBF轻度下降；一旦失代偿，CBV随之下降，提示不可逆梗死。【为什么错】A错误：把除法写成乘法，量纲不成立。C错误：TTP是达峰时间，不能与CBF相乘得到CBV，且TTP不属于中心容积定理的构成量。D错误：MTT不是CBF与CBV的乘积，量纲同样不成立。E错误：把公式上下颠倒，与B互为倒数关系。", "tr": "记忆抓手：MTT＝CBV/CBF（时间＝容积/流量），把常识中的“容积÷流量＝时间”套进去即可，无需死背。TTP、Tmax属于时间类参数，但并不进入该定理公式。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0129", "t": "多选题", "s": "关于急性缺血性卒中CT灌注对核心梗死区与缺血半暗带的判读，下列正确的有", "o": {"A": "核心梗死区常以相对脑血流量（rCBF）低于对侧镜像区30%的体积来估算", "B": "低灌注区常以Tmax＞6 s的体积来界定，缺血半暗带≈Tmax＞6 s体积减去核心梗死体积", "C": "错配比值（低灌注体积/核心体积）越大、核心体积越小，提示可挽救脑组织越多", "D": "核心梗死区的典型表现是CBF与CBV均明显下降、MTT延长", "E": "半暗带的典型表现是CBF明显升高、CBV下降、MTT缩短"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-129", "kp": "核心梗死区与缺血半暗带的灌注判读", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】A正确：目前自动化后处理软件普遍以rCBF＜30%对侧作为核心梗死的替代阈值。B正确：Tmax＞6 s被用于界定严重低灌注（危险）组织，二者相减即为错配（mismatch）区，也就是通常所说的缺血半暗带。C正确：错配比值大、核心小意味着可挽救组织比例高，是延长时间窗内血管内治疗筛选的重要影像学依据。D正确：核心区自动调节完全失代偿，CBF与CBV同步下降、MTT明显延长，是不可逆损伤的灌注特征。【为什么错】E错误：描述完全颠倒。半暗带的典型模式是MTT/Tmax延长、CBF中度下降，而CBV因侧支循环与血管扩张代偿保持正常或轻度升高——即“CBF-CBV不匹配”。CBF升高、MTT缩短反而见于再灌注后的过度灌注状态。", "tr": "核心与半暗带的鉴别点在CBV：CBV也降＝核心（不可逆），CBV保留＝半暗带（可挽救）。切勿把“MTT延长”单独当作梗死依据，它只提示灌注压下降。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0130", "t": "单选题", "s": "关于CT灌注中TTP与Tmax两个时间参数，下列描述正确的是", "o": {"A": "TTP指组织时间-密度曲线达到峰值的时间，Tmax指去卷积计算后残留函数达到峰值的时间，主要反映对比剂到达的延迟", "B": "TTP与Tmax完全等价，可互相替代", "C": "Tmax指扫描持续的最长时间", "D": "TTP值越小提示灌注越差", "E": "Tmax不受近端大血管狭窄或侧支循环状态的影响"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-130", "kp": "TTP与Tmax的含义", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】A正确。TTP（time to peak）直接取自组织的时间-密度曲线，是未经去卷积处理的“表观”达峰时间；Tmax则来自以动脉输入函数去卷积后的残留函数，反映对比剂自动脉输入至该体素的延迟，对侧支代偿状态更敏感，其＞6 s阈值已成为界定严重低灌注组织的通用标准。【为什么错】B错误：二者算法基础不同，TTP受注射方案与心排量影响更大，数值不可互换。C错误：Tmax并非扫描时间，属概念性误解。D错误：方向相反，TTP延长（数值增大）才提示灌注延迟、灌注变差。E错误：Tmax恰恰对近端狭窄和侧支循环高度敏感，侧支良好者对比剂到达延迟且弥散，Tmax延长正是其表现。", "tr": "TTP“看曲线”、Tmax“看去卷积”，两者都是延长提示灌注差。灌注阈值题中，rCBF＜30%对应核心、Tmax＞6 s对应低灌注区，这一组数字要成对记忆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0131", "t": "多选题", "s": "CT灌注成像的辐射剂量明显高于常规扫描，下列属于合理剂量控制措施的有", "o": {"A": "降低管电压至70~80 kVp，在提高碘对比效率的同时降低剂量", "B": "适当降低管电流，并采用迭代重建或深度学习重建控制噪声", "C": "优化采样策略，首过期密集采样、后段延长采样间隔并适时结束采集", "D": "在满足临床需求的前提下限制Z轴覆盖范围，避免不必要的大范围灌注", "E": "为提高参数图信噪比，应尽量延长总采集时间并缩短全程采样间隔至0.5 s"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-131", "kp": "CT灌注的剂量控制", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】A正确：灌注成像观察的是碘的浓度变化，低kV使碘的CT值增益明显（80 kVp时碘的对比度约为120 kVp的1.7倍），可在降低剂量的同时保持甚至提高信号。B正确：灌注参数由曲线拟合得到，对单帧图像噪声的容忍度较高，故可大幅降低单次曝光的mAs，再用迭代或深度学习重建控噪。C正确：首过期（对比剂流入与流出阶段）需要1~2 s的密集采样以准确拟合曲线，而后段延迟期只需稀疏采样，采用可变间隔可显著减少总曝光次数。D正确：Z轴覆盖越大剂量越高，应按临床问题限定覆盖（如卒中重点覆盖幕上大脑中动脉供血区）。【为什么错】E错误：延长总时间并全程0.5 s高频采样会使曝光次数成倍增加、剂量急剧上升，而对参数计算精度的提升有限，属典型的“以剂量换冗余数据”，违背ALARA原则。", "tr": "灌注剂量控制的关键是“该密的时候密、该停的时候停”，而不是全程高频采样。另需牢记同一部位短期内重复灌注检查有致确定性效应（如皮肤损伤、脱发）的报告，应严格把握适应证。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0132", "t": "案例分析题", "s": "患者男性，71岁，突发右侧肢体无力伴失语5小时，NIHSS评分16分，考虑左侧大脑中动脉供血区急性缺血性卒中，拟评估是否适合血管内取栓治疗。急诊配备64排以上CT，卒中团队要求在最短时间内获得出血、血管闭塞部位与可挽救组织三方面信息。下列一站式扫描流程与技术安排最合理的是", "o": {"A": "先行头颅CT平扫排除颅内出血，随后行头颈CTA明确闭塞部位与侧支，最后行CT灌注评估核心梗死与低灌注体积；两次团注分开进行，控制总碘量，CTP采用低管电压与低mAs并配合迭代重建", "B": "直接行CT灌注，若显示大面积低灌注即可诊断，无须平扫", "C": "先行CT灌注，再行平扫，最后视情况决定是否做CTA", "D": "仅行头颈CTA，凭血管闭塞部位推断梗死核心大小", "E": "先行颅脑增强扫描，再据强化范围判断半暗带"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-132", "kp": "急性卒中一站式CT检查流程", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】A正确。急性卒中影像的第一要务是排除颅内出血（决定能否溶栓／取栓），故必须以平扫开路；其次用CTA定位闭塞血管、评估主动脉弓与颈动脉入路及侧支循环，为取栓路径规划提供依据；最后以CTP判断核心梗死体积与错配情况，回答“是否还有可挽救组织”。CTA先于CTP还可避免灌注注射后的残留强化干扰血管评价。两次团注应分开并控制总碘量，CTP采用低kV、低mAs加迭代重建以压低这一高剂量序列的负担。【为什么错】B错误：不排除出血直接灌注，一旦为脑出血将造成灾难性的治疗决策错误；且灌注不能可靠区分出血。C错误：把灌注放在最前，既延误出血判断，又使随后平扫因对比剂残留而难以判读密度。D错误：闭塞部位与核心梗死体积并不等价，侧支循环状态决定了同一闭塞部位可有截然不同的核心大小，这正是灌注检查存在的意义。E错误：常规增强扫描不能定量血流动力学参数，无法界定半暗带，且延误时间。", "tr": "顺序题的判分点是“先排除出血”。另记：CTA与CTP的顺序在多数中心为平扫→CTA→CTP，既保证血管图像不受污染，又不耽误出血判断；时间就是大脑，所有附加序列都要服从于流程效率。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0133", "t": "多选题", "s": "行头颈部CTA时，为减少颈内静脉与硬膜窦的对比剂污染、提高动脉显示质量，下列措施合理的有", "o": {"A": "采用自足侧向头侧（升序）的扫描方向，使扫描推进与颈动脉血流方向一致", "B": "监测ROI置于主动脉弓或升主动脉，阈值触发后以较短的诊断延迟启动扫描", "C": "缩短注射总时间并加用生理盐水冲刷，使团注更加紧凑", "D": "降低机架旋转速度、延长扫描时间，以获得更充分的动脉充盈", "E": "采用80~100 kVp的低管电压，提高碘的对比效率，从而减少对比剂总量与注射时间"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-133", "kp": "头颈CTA静脉污染的控制", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】A正确：自主动脉弓向颅顶扫描与颈动脉血流方向一致，扫描层面始终“追随”动脉团注前沿，可在静脉回流显影之前完成采集。B正确：主动脉弓ROI能最早捕捉团注到达，配合短诊断延迟可把采集窗锁定在动脉期。C正确：注射时间越短、团注柱越紧凑，动静脉循环时间窗被充分利用，静脉污染越轻；盐水冲刷可把残留在上肢与中心静脉内的对比剂推入循环。E正确：低kV时碘的CT值增益显著，可在减少总量与注射时间的同时保持足够动脉强化，一举两得。【为什么错】D错误：延长扫描时间意味着采集窗跨越了动静脉循环时间（脑循环动静脉时间差仅约4~6 s），静脉必然显影，污染加重；头颈CTA恰恰要求尽可能快的扫描速度。", "tr": "头颈CTA的核心矛盾是“动静脉循环时间差短”，所有对策都围绕“扫得快、团注紧、触发准”。误以为“慢扫描能让动脉更充盈”是典型的方向性错误。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0134", "t": "单选题", "s": "关于冠状动脉CTA与头颈部CTA在技术要求上的差异，下列说法错误的是", "o": {"A": "冠状动脉CTA必须使用心电门控，头颈部CTA常规不需要心电门控", "B": "冠状动脉CTA对时间分辨率要求最高，头颈部CTA则对扫描速度与静脉污染控制要求最高", "C": "冠状动脉CTA的监测ROI常置于升主动脉或降主动脉，头颈部CTA常置于主动脉弓", "D": "冠状动脉CTA扫描范围一般为气管隆嵴下方至心脏膈面约12~16 cm，头颈部CTA自主动脉弓至颅顶", "E": "两者对心率的要求相同，心率超过70次/分时头颈部CTA同样无法完成"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-134", "kp": "冠脉CTA与头颈CTA的参数差异", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】本题选错误项，E错误。心率要求是冠状动脉CTA特有的：冠脉随心动周期大幅位移，必须靠心电门控在相对静止期采集，故要求心率低而齐（理想＜65次/分）。头颈动脉不随心跳大幅移动，扫描不使用心电门控，心率快慢仅通过循环时间影响到达时间，可由团注追踪自动补偿，并不构成检查禁忌。【为什么错】A正确：这是两者最根本的差别。B正确：冠脉靠单扇区／多扇区重建争取毫秒级时间分辨率；头颈靠高螺距、宽体探测器争取秒级的整体扫描速度。C正确：ROI位置的选择原则是“尽量靠近目标血管的上游且位置稳定”。D正确：这是两者常规的解剖覆盖范围，冠脉范围小而要求高，头颈范围长（约35~40 cm）。", "tr": "把“心率控制”泛化到所有CTA是常见错误。需要心电门控的是心脏、冠脉、升主动脉根部（以及部分主动脉全程CTA），头颈、肺动脉、外周血管CTA均不需要。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0135", "t": "单选题", "s": "下列临床情形与CTA时相确定方式的匹配中，不恰当的是", "o": {"A": "常规胸腹主动脉CTA——采用团注追踪，ROI置于降主动脉", "B": "心功能不全、循环时间明显延长者——采用小剂量测试确定个体化延迟", "C": "屏气配合差的幼儿——经验固定延迟是唯一可靠的方式，不应使用团注追踪", "D": "肺动脉CTA——采用团注追踪，ROI置于肺动脉主干", "E": "头颈部CTA——采用团注追踪，ROI置于主动脉弓"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-135", "kp": "CTA触发方式的选择", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】本题选不恰当项，C错误。幼儿循环时间短且个体差异大，经验固定延迟极易失准；实践中同样可采用团注追踪（适当降低阈值、缩短诊断延迟）或小剂量测试，只是要配合低剂量监测与镇静、固定；把固定延迟说成“唯一可靠方式”既不准确也不安全。【为什么错】A正确：主动脉CTA以降主动脉或膈下腹主动脉为监测点是常规做法。B正确：低心排患者对比剂到达明显延迟且峰值平坦，阈值触发不稳定，用test bolus实测峰值时间更可靠。D正确：肺动脉CTA的ROI应置于肺动脉主干（或右心室流出道），阈值多取100 HU左右。E正确：头颈CTA ROI置主动脉弓，可在动脉团注到达颈部之前触发。", "tr": "ROI的放置原则是“目标血管上游、位置稳定、管腔够大”。凡出现“唯一”“只能”等绝对化表述的选项，多为命题设置的错误信号，需结合原理判断而非凭措辞。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0136", "t": "多选题", "s": "关于CTA常用后处理方法的选择与特点，下列正确的有", "o": {"A": "容积再现（VR）适合整体显示血管的空间走行与毗邻关系，但狭窄程度的判断易受阈值与透明度设置影响", "B": "最大密度投影（MIP）能连续显示血管全程与钙化，但骨骼、钙化的重叠可掩盖管腔", "C": "曲面重建（CPR）可将迂曲血管展平于同一平面，便于观察管腔、管壁及支架内情况", "D": "最小密度投影（MinIP）是评价动脉狭窄程度的首选方法", "E": "曲面重建的结果不依赖中心线勾画的准确性"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-136", "kp": "CTA后处理方法的选择", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】A正确：VR图像立体直观，用于术前空间关系展示与沟通；但其显示效果取决于阈值、不透明度曲线，定量狭窄不可靠。B正确：MIP保留了原始CT值，血管连续性好，是CTA的主力后处理；缺点是高密度的骨与钙化会遮挡管腔，需先去骨或结合薄层MIP。C正确：CPR沿血管中心线展开，是评价冠脉、颈动脉、肾动脉迂曲段及支架内再狭窄的关键工具。【为什么错】D错误：MinIP显示的是路径上的最低密度值，主要用于气道、胆道等低密度结构，不能用于动脉狭窄评价。E错误：CPR完全依赖中心线：中心线偏出管腔会人为造成“假性狭窄”或“假性闭塞”，必须结合横断面与原始图像核对。", "tr": "任何后处理图像都不能替代横断面原始图像判读。CPR的假狭窄、MIP的钙化遮挡、VR的阈值假象，是三类最常被追问的后处理陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0137", "t": "案例分析题", "s": "患者男性，70岁，双下肢间歇性跛行3年，临床申请下肢动脉CTA，扫描范围自腹主动脉分叉至足底，长度约120 cm。技师沿用腹部CTA的高螺距快速扫描方案，触发后立即由头侧向足侧采集。重建后发现腹主动脉、髂动脉与股动脉显影良好，但腘动脉以下小腿动脉几乎无对比剂充盈。患者双足背动脉搏动减弱。造成该结果最主要的原因及最合理的改进措施是", "o": {"A": "扫描速度超过了对比剂在下肢的推进速度，出现“扫描追过团注”现象；应降低扫描速度（减小螺距或延长旋转时间）、适当延长触发后延迟，必要时对小腿段追加延迟采集", "B": "对比剂总量不足；应把总量增加一倍并保持原有扫描速度", "C": "触发阈值过高；应把阈值降至50 HU后按原速度重新扫描", "D": "属正常表现，小腿动脉本不显影；改用最小密度投影后处理即可显示", "E": "系金属伪影所致；应改行平扫加骨算法重建"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-137", "kp": "下肢CTA的扫描速度匹配", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】A正确。下肢动脉CTA的特殊矛盾在于“扫描速度必须与对比剂推进速度匹配”：现代多层CT的采集速度可达每秒十余厘米，明显快于团注在下肢（尤其存在近端狭窄、侧支代偿时）的前行速度，扫描层面会“跑到”对比剂前面，造成远端血管无强化。正确对策是主动放慢扫描（减小螺距、延长旋转时间或设置扫描延迟）、延长触发后延迟，对严重缺血侧可对小腿-足部追加一次延迟采集。【为什么错】B错误：单纯加倍对比剂既不能解决时间不匹配问题，还显著增加肾脏负担。C错误：降低阈值只会使扫描更早启动，远端充盈更差，把问题加重。D错误：正常小腿三支动脉在合格的CTA上应清晰显影，无显影是技术失败或病变闭塞，不能视为正常。E错误：无强化区并非高密度金属条纹伪影，改行平扫更无法评价血管。", "tr": "下肢CTA的经典失败是“追过团注”，与之相对的另一失败是“扫太慢导致静脉污染”。判断依据看远端：远端无强化＝扫太快；远端动静脉同时显影＝扫太慢。老年动脉硬化闭塞患者血流慢，应主动降低扫描速度。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0138", "t": "多选题", "s": "目前临床CT实现能量（能谱）成像的技术途径包括", "o": {"A": "双源双能量：两套球管与探测器系统分别以不同管电压同时采集", "B": "单源快速管电压切换：同一球管在相邻投影间高速切换高低管电压", "C": "双层（三明治）探测器：上下两层探测器分别优先吸收低能与高能光子", "D": "在同一管电压下改变管电流大小，即可实现能量分离", "E": "对常规单能扫描数据采用不同卷积核重建，即可获得能谱信息"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-138", "kp": "能量成像的实现方式", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】A正确：双源CT两套系统分别设定80/140 kVp（常加锡滤过），实现空间上同时、能量上分离的采集。B正确：瞬时kV切换在同一旋转内交替产生高低能投影，时间配准好、可做投影域物质分解。C正确：双层探测器由上层吸收低能光子、下层吸收高能光子，天然实现同源同时同角度的双能数据；此外新兴的光子计数探测器可直接按能量区间计数。【为什么错】D错误：管电流只改变光子数量（影响噪声与剂量），不改变X线能谱分布，无法实现能量分离。E错误：卷积核只是重建滤波过程中的数学处理，不能凭空产生不同能量下的衰减信息；虚拟单能量图像必须建立在双能／多能采集数据之上。", "tr": "记住“变的是能量（kV）不是电流（mA）”。虚拟单能量图像来自双能数据的物质分解重组，与“单能量扫描”“不同卷积核”是完全不同的概念。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0139", "t": "单选题", "s": "患者右侧全髋关节置换术后，因盆腔疼痛行能量CT检查，希望在减轻金属条纹伪影的同时兼顾邻近软组织的观察。最适合优先查看的虚拟单能量图像能级是", "o": {"A": "40 keV", "B": "50 keV", "C": "70 keV", "D": "90 keV", "E": "130~150 keV"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-139", "kp": "虚拟单能量图像的能级选择", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】E正确。金属伪影的主要成因是低能光子被大量吸收造成的线束硬化与光子饥饿。高能级（130~150 keV）虚拟单能量图像中光子穿透力强、能谱更“硬”，硬化与条纹伪影显著减轻，配合专用金属伪影校正算法（MAR）可使假体周围软组织重新可辨；代价是碘对比与软组织对比下降，故通常与常规70 keV图像联合阅读。【为什么错】A、B错误：40~50 keV虽显著提高碘的CT值（适合小血管、乏血供病灶显示），但同时放大线束硬化伪影与噪声，在金属周围表现最差。C错误：70 keV近似常规120 kVp图像的对比噪声特性，是通用阅读能级，但对金属伪影无改善作用。D错误：90 keV改善有限，未达到抑制严重金属伪影所需的能级。", "tr": "牢记能级选择的两极：“低keV增强碘对比”（40~55 keV，用于CTA、乏血供病灶、低碘负荷），“高keV去伪影”（≥130 keV，用于金属、颅底、肩部硬化伪影）。二者用途相反，切勿颠倒。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0140", "t": "单选题", "s": "关于双能量CT物质分离技术的临床应用，下列描述错误的是", "o": {"A": "虚拟平扫（VNC）从增强数据中减除碘成分，在部分场景下可省去一次真实平扫从而降低总剂量", "B": "碘密度图可定量评价组织的碘摄取，有助于判断肿瘤活性和肺栓塞相关的灌注缺损", "C": "可鉴别尿酸盐结石与非尿酸盐结石，并能显示痛风患者关节周围的尿酸盐结晶沉积", "D": "虚拟去钙技术可提高椎体骨髓水肿等病变的显示能力", "E": "物质分离可直接定量测出病灶内钙、碘、铁的绝对含量，并据此明确肿瘤的病理类型"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-140", "kp": "双能量CT的物质分离应用", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】本题选错误项，E错误。双能量物质分解基于两种基物质的衰减模型，通常只能在“两基物质＋约束条件”的框架下做相对定量（如碘浓度mg/ml、脂肪分数），无法同时精确给出多种元素的绝对含量；更重要的是，任何影像定量都不能直接确定病理类型，病理诊断仍需组织学证据。【为什么错】A正确：VNC是双能量最成熟的应用之一，在肾上腺、肾脏、主动脉夹层等检查中可替代真实平扫，减少一次曝光。B正确：碘图是功能性信息，肺栓塞的肺灌注血容量图与肿瘤治疗后活性评估均依赖它。C正确：尿酸盐与钙质在高低能下的衰减差异明显，双能量鉴别痛风的临床价值已被广泛认可。D正确：虚拟去钙可减除椎体骨小梁的钙信号，使骨髓水肿在CT上可视化，用于隐匿骨折评估。", "tr": "能量CT的定量是“相对、受模型限制”的，且始终不能替代病理。凡把影像技术描述为“可明确病理类型／确诊”的选项，几乎都是错误项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0141", "t": "单选题", "s": "关于CT导向下经皮穿刺活检的技术要点，下列说法错误的是", "o": {"A": "定位时可在体表放置金属定位栅（栅栏），据CT图像确定进针点、进针角度与深度", "B": "进针过程中应分次进针并反复薄层扫描，确认针尖与病灶、重要结构的关系", "C": "同轴技术经一次穿刺置入外套针后可反复取材，减少胸膜穿刺次数与并发症", "D": "肺内病灶穿刺应选择最短路径，即使需要穿过叶间裂或含气肺组织也应优先考虑距离最短", "E": "取材完成后应即刻复查扫描，观察有无气胸、出血等并发症并记录"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-141", "kp": "CT导向穿刺活检的技术要点", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】本题选错误项，D错误。肺穿刺路径选择的首要原则是“安全”而非“最短”：应避免穿过叶间裂（等于两次穿破胸膜，气胸风险成倍增加）、大血管、肺大疱及正常肺组织过多的路径，宁可选择稍长但经病灶紧贴胸膜处进针的路径。【为什么错】A正确：定位栅是最基础的体表定位工具，配合激光灯确定层面。B正确：分步进针＋薄层确认是避免误伤的关键，尤其在纵隔、肝门等毗邻大血管区域。C正确：同轴技术是标准做法，可一次穿刺、多条取材，兼顾诊断率与安全性。E正确：术后即刻复查是常规，用于早期发现气胸、出血并决定观察或处理，同时是重要的医疗记录。", "tr": "穿刺路径“最短”与“最安全”常不一致，考试与临床都以最安全为准。叶间裂、肺大疱、心包、大血管、扩张的胆管都是必须避开的结构。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0142", "t": "案例分析题", "s": "患者男性，65岁，右肺上叶周围型结节，在CT导向下行经皮穿刺活检。采用同轴技术，取材2条后即刻扫描发现右侧少量气胸，估计肺压缩约10%，纵隔无移位。患者诉轻微胸痛，无明显呼吸困难，血氧饱和度98%，生命体征平稳。此时最恰当的处理是", "o": {"A": "停止继续取材，拔针后嘱患者取穿刺侧向下卧位、必要时吸氧并留观，20~30分钟后复查CT观察气胸是否进展，多数少量气胸可自行吸收", "B": "立即行胸腔闭式引流术，以防气胸进展", "C": "继续追加多次穿刺以保证取材量，待检查全部结束后再统一处理", "D": "立即行胸部增强CT以明确有无活动性出血", "E": "无须复查扫描，直接送患者返回病房观察"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-142", "kp": "CT导向肺穿刺并发症的处理", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】A正确。气胸是CT引导肺穿刺最常见的并发症（发生率约20%~30%，需引流者仅少数）。本例为少量气胸、无症状、生命体征稳定，处理原则是停止操作、拔针、穿刺侧向下卧位（借重力压迫穿刺点、减少气体进一步漏出）、吸氧促进气体吸收，并在留观期间复查扫描确认无进展，绝大多数可保守吸收。【为什么错】B错误：胸腔闭式引流适用于大量气胸（如肺压缩＞30%）、症状明显、张力性气胸或进行性增大者，本例属过度处理。C错误：气胸已发生仍继续多次穿刺，会显著加重漏气，是操作原则性错误。D错误：患者无咯血、无血流动力学不稳，增强扫描既无指征又增加剂量与对比剂风险。E错误：不复查、不留观即送回，可能漏掉迟发进展性气胸，违反术后观察规范。", "tr": "少量无症状气胸＝观察＋复查；大量或有症状／张力性气胸＝抽气或闭式引流。另需记住术后卧位原则“穿刺侧向下”，以及肺出血时应“患侧向下”以防血液流入健侧。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0143", "t": "单选题", "s": "关于CT机的日常设备准备与质量保证，下列说法错误的是", "o": {"A": "每日开机后应按厂家程序进行球管预热，使阳极靶面受热均匀，避免热应力损伤", "B": "应按厂家要求定期进行空气校正（气体校准），以校正各探测器通道间的响应差异", "C": "定期用水模检测水的CT值（应在0±4~5 HU范围内）、噪声与均匀性", "D": "进行空气校正时，机架扫描孔内不得放置任何物体，检查床也应移出扫描野", "E": "只要图像上未见明显环状伪影，即可长期不做空气校正，以节省球管寿命"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-143", "kp": "设备预热与空气校正", "ch": "九、CT检查技术 → 3.检查前准备 → (1)设备", "ex": "【为什么对】本题选错误项，E错误。空气校正是探测器通道一致性的基础保障，探测器响应会随温度、湿度与使用时间缓慢漂移，等到出现明显环状伪影时误差已相当大，且CT值准确性可能早已超标。规范做法是按厂家要求定期（多为每日或每周）执行，属强制性质控项目，其球管消耗微乎其微。【为什么错】A正确：冷球管直接大功率曝光会因热冲击损伤阳极靶面并缩短寿命，预热是每日第一步。B正确：这正是空气校正的目的。C正确：水模检测CT值、噪声、均匀性、层厚等是CT质控的核心项目，水的CT值应接近0 HU。D正确：校正时扫描野内必须为空气，任何物体（包括检查床、体模、耦合垫）都会导致校正数据错误，进而产生全局性伪影。", "tr": "环状伪影是探测器通道失校的典型征象，其常规对策就是重新做空气校正。切勿把“节省球管”当作省略质控的理由——CT值失准会直接影响脂肪肝、结石、灌注等定量判读。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0144", "t": "多选题", "s": "关于CT检查前的患者准备，下列做法正确的有", "o": {"A": "腹部检查一般需禁食4~6小时，且检查前一周内不宜做过钡剂胃肠造影", "B": "腹部检查前可按规定分次口服1%~2%的碘对比剂稀释液或温开水，以充盈胃肠道", "C": "去除检查部位的金属饰物、活动义齿、发夹、含金属的膏药与内衣饰扣", "D": "胸部与上腹部检查前应做屏气训练，使定位像、平扫与各期增强的屏气幅度一致", "E": "为减少运动伪影，所有受检者在检查前均应常规使用镇静剂"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-144", "kp": "CT检查前的患者准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】A正确：禁食可减少胃内容物干扰并降低对比剂不良反应时误吸风险；残留钡剂密度极高，会产生严重条纹伪影并掩盖病灶，故需待其排空。B正确：1%~2%浓度的稀释碘水既能勾勒肠腔又不至于因过浓产生伪影；分次定时口服（如检查前60、30、10分钟）可使从胃到远端小肠依次充盈。C正确：金属高密度物体引起放射状条纹伪影，是可预防的图像质量问题。D正确：屏气幅度不一致会造成层面错位与病灶“漏扫”，也会使多期图像难以配准比较，这是胸腹部检查的关键细节。【为什么错】E错误：镇静有呼吸抑制与误吸等风险，仅在婴幼儿、意识障碍或躁动不能配合者由临床医师评估后使用，绝不能作为常规。", "tr": "口服对比剂需要“浓度低、分次服、留足时间”；过浓反而产生伪影。带“所有／均”的常规化处置类选项（如常规镇静、常规激素预防）通常是错误项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0145", "t": "单选题", "s": "关于碘对比剂使用相关的安全管理，下列说法错误的是", "o": {"A": "使用前将对比剂加温至37 ℃可降低黏稠度，便于高流率注射并减轻注射时的不适", "B": "碘过敏试验对预测过敏样反应缺乏价值，目前不推荐作为常规筛查手段", "C": "既往对碘对比剂发生过中重度过敏样反应者属高危人群，应重新评估检查必要性或改用其他影像方法", "D": "对eGFR＜30 ml/(min·1.73 m²)或存在急性肾损伤者，应在检查前停用二甲双胍，并在检查后48小时复查肾功能无恶化后再恢复用药", "E": "只要建立了静脉通路并备有肾上腺素，即可对所有患者省略过敏史询问与知情告知"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-145", "kp": "对比剂使用与高危因素评估", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】本题选错误项，E错误。病史询问（既往对比剂反应史、哮喘与过敏体质、肾功能、糖尿病与二甲双胍用药、甲状腺功能亢进、妊娠等）和知情告知是使用对比剂前不可省略的法定与技术环节；急救准备只是“出事之后”的保障，不能替代“事前”风险识别，二者不可互换。【为什么错】A正确：加温至体温可显著降低黏稠度（尤其高浓度对比剂），有利于高流率注射并减少推注阻力和不适。B正确：所谓“碘过敏试验”既不能预测过敏样反应，本身还可能诱发反应，国内外指南均已不推荐常规进行。C正确：既往中重度反应史是最强的风险预测因子，应权衡改用平扫、MRI或超声等替代方案，必要时在具备抢救条件下进行。D正确：二甲双胍本身无肾毒性，风险在于肾功能急剧下降时药物蓄积诱发乳酸酸中毒，故按肾功能分层管理停药与复查。", "tr": "记住三个“不能”：碘过敏试验不能预测反应、预防用药不能完全消除风险、急救准备不能替代风险筛查。二甲双胍的处理按eGFR分层，而非一律停药48小时。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0146", "t": "多选题", "s": "关于CT检查室的急救准备与对比剂不良反应处理，下列正确的有", "o": {"A": "检查室应配备氧气、吸引装置、简易呼吸器、血压计与常用急救药品，并定期核查有效期与功能状态", "B": "发生喉头水肿、支气管痉挛伴低血压等严重过敏样反应时，成人首选肌内注射1:1000肾上腺素0.3~0.5 mg，必要时重复", "C": "单纯轻度荨麻疹等皮肤反应多可自限，以观察为主，必要时给予抗组胺药物", "D": "糖皮质激素起效慢，不能作为严重急性过敏样反应的首选抢救药物", "E": "对比剂血管外渗后应立即热敷并加压包扎患肢，以促进吸收"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-146", "kp": "急救物品与对比剂不良反应处理", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】A正确：这是开展增强检查的基本条件，急救设备必须处于随时可用状态并有定期点检记录。B正确：肾上腺素是严重过敏样反应的一线药物，成人肌注1:1000溶液0.3~0.5 mg（大腿前外侧肌肉吸收最快），可每5~15分钟重复。C正确：轻度皮肤反应多为自限性，过度用药无益，重点是继续观察是否进展。D正确：激素起效需数小时，主要用于防止双相反应和迁延症状，不能替代肾上腺素。【为什么错】E错误：外渗的正确处理是抬高患肢、早期局部冷敷（一般24小时内间断冷敷），并观察张力、感觉、皮肤颜色，警惕骨筋膜室综合征；加压包扎会加重局部压力、影响回流，热敷在早期可能加重肿胀。", "tr": "外渗处理“抬高＋冷敷、不加压”，与软组织扭伤的处理思路一致；严重反应“先肾上腺素、后激素”。这两组是最常考的处置顺序题。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0147", "t": "单选题", "s": "关于CT检查中操作者的准备与职责，下列说法错误的是", "o": {"A": "严格核对患者身份、检查部位与申请单信息，防止张冠李戴与错扫部位", "B": "增强检查前应履行知情告知义务并取得签署的知情同意书", "C": "熟悉本单位应急预案与急救药品位置，能够识别对比剂不良反应的早期表现", "D": "合理使用铅防护用品，对邻近扫描野的敏感器官（如儿童性腺、甲状腺）予以屏蔽", "E": "为提高工作效率，可由未经培训的实习人员独立完成高压注射器操作与扫描参数设定"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-147", "kp": "操作者准备与知情同意", "ch": "九、CT检查技术 → 3.检查前准备 → (4)操作者", "ex": "【为什么对】本题选错误项，E错误。高压注射器操作与扫描参数设定直接关系患者安全（渗漏、空气栓塞、过量曝光），必须由经过培训并获得授权的技师执行；实习人员只能在带教教师指导下参与，不能独立操作，这是执业规范的底线要求。【为什么错】A正确：身份与部位核对是医疗安全核查的第一步。B正确：增强属有创、有风险的操作，知情同意是法定程序。C正确：技师往往是不良反应的第一发现者，识别早期表现（皮肤瘙痒、喷嚏、声音嘶哑、胸闷）并及时呼救至关重要。D正确：在不影响诊断信息的前提下对邻近敏感器官屏蔽，符合防护最优化原则。", "tr": "涉及“未经培训人员独立操作”“省略知情同意”“为效率牺牲核对”的选项一律为错。此类题考的是执业规范意识，与技术细节同样重要。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0148", "t": "案例分析题", "s": "患儿男，3岁，体重14 kg，反复肺部感染，临床申请胸部CT明确有无支气管发育异常。患儿哭闹明显、不能配合屏气，家长要求陪同。科室配备64排CT，具备儿童剂量方案与自动管电流调制功能。下列检查前准备与技术方案中最合理的是", "o": {"A": "由临床医师评估后按需给予镇静并使用固定装置，采用大螺距快速扫描缩短采集时间，选择儿童低剂量方案（降低管电压、按体重调制管电流）并做好非检查部位屏蔽，陪同家长穿戴铅防护", "B": "沿用成人胸部扫描参数，以保证图像质量与诊断信心", "C": "用约束带强行固定后按成人剂量连续扫描两遍，以防一次失败", "D": "一律先行全身麻醉后再行胸部增强扫描", "E": "因儿童对辐射敏感，应以胸部MRI完全替代CT检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-148", "kp": "儿童CT检查的特殊准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】A正确。儿童CT的核心原则是“快、准、低”：用大螺距／宽体探测器把采集压缩到1~2秒内，可在自由呼吸下获得可诊断图像，从而尽量减少镇静需求；确需镇静时由临床医师评估并全程监护；剂量方案按体重／体厚个体化（降低kV、自动管电流调制、迭代重建），并对非检查部位屏蔽；陪同人员必须穿戴铅防护并站在合适位置。【为什么错】B错误：成人参数对14 kg幼儿而言剂量严重过量，违反ALARA与儿童剂量优化原则。C错误：既强行约束又重复扫描，剂量翻倍且极易引起体动，属双重错误。D错误：全身麻醉有其自身风险，不应作为常规首选；且本例临床问题（支气管发育异常）多数无须增强。E错误：MRI对肺实质与气道细节的显示远不如CT，且检查时间长、幼儿更难配合，不能完全替代。", "tr": "儿童检查优化的正确顺序是：先想办法缩短扫描时间（减少镇静需求），再优化剂量参数，最后才考虑镇静与麻醉。“沿用成人参数”和“重复扫描保成功”是最典型的错误做法。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0149", "t": "多选题", "s": "关于孕妇与危重患者行CT检查的特殊准备，下列做法正确的有", "o": {"A": "妊娠期确需CT检查时应严格掌握适应证，优先考虑超声或MRI；确需CT者应缩小扫描范围、优化剂量并对腹部予以屏蔽", "B": "危重患者检查时须由临床医护人员陪同，携带监护仪与抢救器材，保持气道与静脉通路通畅", "C": "带有呼吸机、微量泵、引流管的患者，移床前应核对管路长度与固定情况，防止牵拉脱管", "D": "意识障碍或躁动不能配合者可使用固定装置并尽量缩短扫描时间，必要时由临床医师评估后给予镇静", "E": "妊娠属CT检查的绝对禁忌，任何情况下均不得对孕妇实施CT扫描"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-149", "kp": "孕妇与危重患者的检查准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】A正确：妊娠期遵循正当化与最优化原则，能用无电离辐射手段解决的优先用超声／MRI；确有必要（如疑肺栓塞、严重创伤）时应权衡母体获益与胎儿风险，通过限制范围、降低管电压与管电流、屏蔽等手段把胎儿剂量降至最低。B正确：危重患者随时可能出现循环呼吸变化，检查室不具备完整抢救条件，必须由临床团队陪同并携带设备。C正确：移床过程中的管路牵拉是CT室常见不良事件，检查前核对是标准动作。D正确：固定＋快速扫描优先，镇静作为补充手段并须有医师评估与监护。【为什么错】E错误：妊娠不是CT的绝对禁忌。当母体存在危及生命的情况（如肺栓塞、多发创伤、急腹症）时，延误诊断的风险远大于经过优化后的胎儿受照风险；常规腹部以外部位的CT，胎儿剂量通常很低。", "tr": "“绝对禁忌”一词在对比剂与妊娠相关题目中几乎都是错误信号。正确的表述是“严格掌握适应证、优化剂量”，即正当化＋最优化，而非一刀切禁止。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0150", "t": "单选题", "s": "关于胸腹部CT检查的呼吸训练与呼吸相关伪影，下列说法错误的是", "o": {"A": "定位像与平扫、各期增强应使用同一套呼吸指令，保证屏气幅度一致以便层面配准", "B": "屏气不足或扫描中途换气可造成膈肌附近层面错位与运动伪影，甚至遗漏病灶", "C": "冠状动脉CTA与肺动脉CTA宜采用平静吸气后屏气，过度深吸气可致大量未强化的下腔静脉血涌入右心，形成一过性对比剂中断", "D": "确实无法屏气者可采用大螺距、短旋转时间的快速扫描，在平静呼吸下完成采集", "E": "屏气幅度不一致只影响图像美观，不会影响多期增强图像间的对照比较"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-150", "kp": "屏气训练与呼吸运动伪影", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】本题选错误项，E错误。屏气幅度不一致会使同一病灶在不同期相落到不同层面，导致强化曲线判读错误、小病灶“时有时无”，也使配准与减影后处理失败，直接影响诊断结论而非仅仅“美观”。【为什么错】A正确：统一指令是保证多期可比性的前提，训练时应让患者按同样深度吸气再屏住。B正确：膈肌活动度最大，屏气失败首先在肝顶、肺底表现为错层、双边影与阶梯状伪影。C正确：这是CTPA与冠脉CTA中一过性对比剂中断的经典机制，故推荐“平静吸气后屏气”而非深大吸气。D正确：现代CT可在1~2秒内完成胸部采集，对无法屏气者用快速扫描换取可诊断图像是常规策略。", "tr": "深吸气会增加胸腔负压、促使下腔静脉未强化血液回流右心，是CTPA强化不足的重要技术原因，纠正方法是改用平静吸气后屏气，而不是增加对比剂用量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0151", "t": "多选题", "s": "关于颅脑CT扫描基线与层厚的选择，下列正确的有", "o": {"A": "常规颅脑横断面扫描多以听眦线（OM线）作为基线", "B": "采用听眉线作为基线时，扫描层面较少穿过颅底骨嵴，有助于减轻后颅窝伪影", "C": "适当倾斜机架角度可使层面避开晶状体，减少眼晶状体的受照剂量", "D": "传统分层扫描时，幕下（后颅窝）宜采用较薄层厚，幕上可采用相对较厚层厚", "E": "采用螺旋容积采集后，重组基线在采集完成后即固定，不能再做调整"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-151", "kp": "颅脑扫描基线的选择", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】A正确：听眦线（外眦与外耳道中点连线，即OM线）是颅脑横断扫描最常用的基线，层面显示解剖标准、便于随访对照。B正确：听眉线（眉上缘中点至外耳道中点）较OM线上倾约15°~20°，层面与岩骨嵴的交角改变，可减少颅底骨造成的线束硬化条纹，同时也降低晶状体受照。C正确：倾斜机架使扫描平面避开眼球，是减少晶状体剂量的经典手段。D正确：后颅窝结构精细、伪影多，需薄层；幕上脑组织可用相对厚层以控制噪声与剂量，这是传统分层扫描的通行原则。【为什么错】E错误：螺旋容积采集获得的是各向同性数据，可在任意基线上重组横断、冠状、矢状与斜位图像，重组基线完全可以事后调整，这正是容积扫描相对分层扫描的重要优势。", "tr": "OM线与听眉线是两条不同基线：常规用OM线，减少后颅窝伪影与晶状体剂量时用听眉线或倾斜机架。容积扫描后“可任意重组”是现代CT的基本特性，凡称“不可更改”者多为错误项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0152", "t": "单选题", "s": "颅脑CT后颅窝层面常出现横贯岩骨之间的条纹状低密度伪影（Hounsfield伪影），下列处理措施中不恰当的是", "o": {"A": "适当减薄层厚并提高管电流，减轻部分容积效应与光子饥饿", "B": "适当提高管电压，增强射线穿透力以减轻线束硬化", "C": "启用线束硬化校正算法或迭代重建算法", "D": "采用薄层容积采集后重组，或调整机架角度使扫描层面尽量避开岩骨嵴", "E": "改用高分辨率骨算法重建脑实质图像，通过锐化处理消除该伪影"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-152", "kp": "后颅窝伪影的处理", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】本题选不恰当项，E错误。后颅窝条纹伪影源于岩骨对低能光子的强烈吸收（线束硬化）与光子饥饿，属数据层面的问题。骨算法只会放大高频噪声与条纹，使脑干、小脑的低对比结构更难辨认；观察后颅窝脑实质应使用软组织核，必要时配合稍窄的后颅窝窗。【为什么错】A正确：薄层减少岩骨与脑组织在同一体素内的混合，提高mAs增加穿透岩骨的光子数，两者均能减轻伪影。B正确：提高kV使平均光子能量升高，硬化效应相对减弱。C正确：厂家的硬化校正与迭代重建对该类伪影有明确改善作用。D正确：容积采集后重组可绕开原采集角度的不利几何，倾斜机架也能改变射线穿过岩骨的路径。", "tr": "牢记“看骨用骨算法、看脑用软组织算法”，锐化核对硬化伪影只会雪上加霜。凡是伪影来自数据不足或硬化，解决之道在采集与校正，而不是后处理锐化。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0153", "t": "案例分析题", "s": "患者男性，76岁，3周前有跌倒史，近1周头痛、反应淡漠、行走不稳。急诊头颅CT平扫：常规脑窗（窗宽80 HU、窗位35 HU）观察，双侧额顶部脑沟较对侧同龄人变浅、脑回受压，中线结构基本居中，脑实质内未见明确异常密度灶。临床高度怀疑慢性／亚急性硬膜下血肿。在不追加扫描的前提下，下列技术处理最恰当的是", "o": {"A": "在常规脑窗基础上加用较宽的窗（如窗宽150~300 HU、窗位50~80 HU）重新观察颅骨内板下区域，并结合冠状面、矢状面重组，必要时建议增强扫描显示血肿包膜", "B": "既然脑实质未见异常密度，可直接报告为未见明显异常", "C": "改用骨窗（窗宽约2000 HU）观察脑实质，以提高对等密度血肿的检出", "D": "追加头颅CT灌注检查，通过CBF下降判断有无硬膜下血肿", "E": "提高管电压至140 kVp后重新扫描，以增加血肿与脑组织的密度差"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-153", "kp": "等密度硬膜下血肿的窗技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】A正确。亚急性期（约1~3周）硬膜下血肿可与脑皮质呈等密度，在窄脑窗下与颅骨内板高密度形成的“白边”混为一体而漏诊。加宽窗宽、上抬窗位后，颅骨内板与其下方的等密度血肿之间可显现分界，同时可观察到脑沟消失、灰白质界面内移、脑回受压等间接征象；冠状与矢状重组有助于显示沿颅穹窿铺展的薄层血肿；增强后血肿包膜强化及皮质静脉内移可进一步确认。【为什么错】B错误：本例已有明确间接征象（脑沟变浅、脑回受压），直接报阴性属漏诊。C错误：骨窗窗宽过大，脑组织与血肿间数十HU的差别会被完全压缩为同一灰阶，反而更看不出来。D错误：CT灌注不是硬膜下血肿的诊断手段，徒增剂量与时间。E错误：血肿与脑实质的等密度是血液成分演变（血红蛋白降解、蛋白含量下降）造成的，提高kV并不能增大二者密度差，反而降低软组织对比。", "tr": "“中线居中”并不能排除双侧对称性硬膜下血肿——这是老年患者最易漏诊的场景。等密度血肿的对策是调窗＋看间接征象，而不是重扫或换算法。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0154", "t": "单选题", "s": "关于颅脑CT常用的窗技术，下列说法正确的是", "o": {"A": "常规脑窗一般取窗宽80~100 HU、窗位35~45 HU", "B": "常规脑窗应取窗宽350~400 HU、窗位40 HU", "C": "观察颅骨骨折宜采用窗宽80~100 HU的窄窗", "D": "观察后颅窝结构时应把窗宽缩小至20~30 HU", "E": "无论观察何种结构，窗位均应固定为0 HU"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-154", "kp": "颅脑CT的窗技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】A正确。脑灰白质CT值差别仅约8 HU，必须使用窄窗才能把这一微小差别展开为可辨的灰阶，故常规脑窗为窗宽80~100 HU、窗位35~45 HU。【为什么错】B错误：窗宽350~400 HU是纵隔窗／软组织窗的参数，用于脑部会使灰白质对比几乎消失。C错误：颅骨骨折需要在骨窗（窗宽约1500~4000 HU、窗位300~700 HU）下观察，窄窗会使骨结构全部呈纯白而无层次。D错误：窗宽20~30 HU过窄，噪声将被极度放大，图像斑驳不可用；后颅窝通常在常规脑窗基础上略作调整（如窗宽稍加大或采用专用后颅窝窗）。E错误：窗位应根据目标组织的CT值设定，脑组织约35~45 HU，固定为0 HU（水的CT值）会使脑组织整体偏白、失去层次。", "tr": "四组必背窗值：脑窗80~100/35~45、骨窗1500~4000/300~700、肺窗1000~1600/-600~-700、纵隔窗300~400/30~50。命题常把脑窗与纵隔窗的数值对调。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0155", "t": "单选题", "s": "关于颅脑CT扫描的体位与方式，下列说法错误的是", "o": {"A": "常规取仰卧位，头置于头架内，使两侧外耳孔与正中矢状面处于对称位置", "B": "常规采用横断面扫描，鞍区、颅底等部位必要时加做冠状面扫描或重组", "C": "传统分层扫描时幕下层厚较薄（约5 mm），幕上可采用较厚层厚（约8~10 mm）", "D": "现代多层螺旋CT多采用薄层容积采集后按需重组，兼顾多平面观察", "E": "摆位时应使头部尽量后仰，令听眦线与检查床面保持平行"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-155", "kp": "颅脑CT的体位与扫描方式", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】本题选错误项，E错误。常规颅脑横断扫描要求听眦线与检查床面（水平面）垂直，即扫描层面与听眦线平行；头部过度后仰使听眦线与床面平行是完全错误的摆位，会导致层面倾斜、左右不对称、解剖标志错乱，并增加晶状体受照。【为什么错】A正确：仰卧、头正、两侧外耳孔对称是保证左右结构对称显示的基本要求，头部旋转会造成假性中线偏移。B正确：鞍区、颅底、眼眶等部位常需冠状面信息，可直接扫描或由薄层容积数据重组。C正确：这是传统分层扫描的常规参数配置。D正确：薄层容积采集＋多平面重组已成为现行主流。", "tr": "牢记“基线与床面垂直、扫描层面与基线平行”。摆位不对称是颅脑CT最常见的低级错误，会造成侧脑室、颞角显示不对称而误判占位效应。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0156", "t": "单选题", "s": "关于鞍区（垂体）CT检查技术，下列说法错误的是", "o": {"A": "应采用≤2 mm的薄层扫描或薄层重建，以减轻部分容积效应对垂体形态判断的干扰", "B": "冠状面图像（直接冠状扫描或薄层重组）对显示垂体上缘形态、垂体柄有无偏移最有价值", "C": "疑垂体微腺瘤时可行动态增强，微腺瘤在早期强化图像上多相对于明显强化的正常垂体呈低密度", "D": "骨窗观察有助于发现鞍底骨质变薄、吸收或倾斜等间接征象", "E": "鞍区检查以10 mm层厚横断面扫描为主，以缩短检查时间、降低剂量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-156", "kp": "鞍区CT检查技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】本题选错误项，E错误。垂体上下径仅约6~8 mm，微腺瘤直径常＜10 mm，10 mm层厚会把整个垂体“压缩”在一到两个层面内，部分容积效应足以掩盖病灶，是根本性的参数错误。【为什么错】A正确：薄层是鞍区检查的前提。B正确：冠状面能同时显示垂体上缘（正常平坦或轻度凹陷）、垂体柄居中与否、海绵窦与颈内动脉，是鞍区最重要的观察平面。C正确：正常垂体无血脑屏障、强化迅速而明显，微腺瘤强化相对延迟，故早期呈相对低密度，这正是动态增强的原理。D正确：鞍底骨质改变是垂体腺瘤的重要间接征象，需在骨窗观察。", "tr": "鞍区题的判分点几乎都在“薄层＋冠状面＋动态增强”。注意微腺瘤是“相对低密度”，出现在强化早期；延迟期病灶可反转为等或高密度，时相选错就会漏诊。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0157", "t": "多选题", "s": "关于鞍区CT检查的技术要点与临床价值，下列正确的有", "o": {"A": "垂体高度增加、上缘膨隆与垂体柄偏移属于垂体微腺瘤的间接征象", "B": "直接冠状面扫描需患者头部过伸，颈椎病变或危重患者难以配合，此时可用薄层横断采集后冠状重组替代", "C": "动态增强要求在注射对比剂后的短时间内对同一区域多次重复采集，以捕捉正常垂体与微腺瘤强化的时间差", "D": "鞍区CT对垂体微腺瘤的检出敏感性优于MRI，应作为首选检查方法", "E": "鞍区检查只需观察垂体本身，无须评估海绵窦及鞍上池情况"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-157", "kp": "鞍区检查的技术要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】A正确：微腺瘤体积小，直接征象常不明显，主要依靠垂体高度增加（女性＞9 mm需警惕，需结合年龄与生理状态）、上缘局限性膨隆、垂体柄向对侧偏移、鞍底局部下陷等间接征象。B正确：直接冠状位要求头部过伸，颈椎强直、外伤或危重患者无法配合，薄层容积采集后重组是等效且更舒适的替代方案。C正确：动态增强的本质是利用正常垂体与微腺瘤的强化时间差，必须高频重复采集同一层面。【为什么错】D错误：MRI软组织分辨率高、可多参数成像，是垂体微腺瘤的首选检查；CT主要用于观察骨质改变、钙化（如颅咽管瘤）以及MRI禁忌者。E错误：鞍区病变常侵犯海绵窦、包绕颈内动脉或向鞍上生长压迫视交叉，海绵窦与鞍上池必须纳入观察范围，这直接影响手术方式选择。", "tr": "“CT优于MRI”类表述在垂体、内耳膜迷路、脑干等软组织部位几乎都是错的；反之在骨质细节、钙化、急性出血方面CT有优势。判断依据是“看骨看钙化用CT，看软组织用MRI”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0158", "t": "单选题", "s": "关于眼部CT检查技术，下列说法错误的是", "o": {"A": "常规采用横断面薄层（≤2 mm）扫描，必要时加做冠状面扫描或重组", "B": "横断面可选用听眶下线作为基线，使层面尽量平行于视神经走行以便全程显示", "C": "冠状面图像有利于观察各条眼外肌的形态以及眶顶、眶底骨壁", "D": "测量眼球突出度可在经晶状体的横断层面上，以两侧眶外缘（颧突）连线为基线，正常一般不超过21 mm", "E": "眼部检查应常规采用高剂量、大层厚扫描，以保证图像信噪比"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-158", "kp": "眼部CT检查技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】本题选错误项，E错误。眼球晶状体是对辐射最敏感的组织之一，眼部CT应在保证诊断的前提下优化剂量（薄层但适度mAs、必要时倾斜机架避开晶状体、采用迭代重建），绝不能以“提高信噪比”为由常规高剂量；同时大层厚会因部分容积效应掩盖眶内小病灶与细小异物，与检查目的冲突。【为什么错】A正确：眶内结构精细，薄层是基本要求。B正确：以听眶下线为基线的横断面接近视神经走行方向，有利于连续显示视神经全程。C正确：冠状面是判断眼外肌增粗（如甲状腺相关眼病）、眶壁骨折（尤其眶底爆裂骨折）的关键平面。D正确：这是CT测量眼球突出度的通用方法与参考值。", "tr": "晶状体剂量是眼部CT的核心防护点：可通过倾斜机架、缩小范围、降低mAs、迭代重建来控制。凡以“保证信噪比”为由主张常规高剂量的选项都是错的。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0159", "t": "案例分析题", "s": "患者男性，28岁，工作中用砂轮打磨金属时未戴防护镜，突发右眼剧痛、视物模糊2小时。眼科检查见角膜小穿通伤口，屈光介质混浊无法窥清眼底，高度怀疑眼内金属异物。临床要求明确异物的有无、位置及与眼球壁、晶状体的关系，以决定手术入路。下列检查方案最合适的是", "o": {"A": "行眼眶薄层（≤1 mm）CT平扫，采用横断采集并做冠状、矢状及斜位重组精确定位，同时评价眼球壁完整性；在排除金属异物前不得行MRI检查", "B": "首选眼眶MRI，其软组织分辨率高，最有利于显示异物与视网膜的关系", "C": "行眼眶CT增强扫描，通过强化程度判断异物性质", "D": "行头颅常规10 mm层厚平扫，若未见异常即可排除眼内异物", "E": "行眼部CT灌注成像评估眼球血供后再定手术方案"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-159", "kp": "眼内异物的CT定位", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】A正确。CT是眼内金属异物定位的首选：金属为极高密度，薄层扫描配合多平面重组可准确判断异物位于球内或球壁、与晶状体和视神经的距离，为手术入路提供依据；同时可评估眼球破裂、眶壁骨折与积气。关键安全点是：在未排除铁磁性异物前严禁MRI，磁场可致异物移位造成灾难性眼内损伤。【为什么错】B错误：疑金属异物时MRI是禁忌，且金属会产生巨大磁敏感伪影，反而无法定位。C错误：异物本身不强化，增强既无助于定性又增加风险与剂量。D错误：10 mm层厚极易漏掉毫米级异物，且不能精确定位，属参数选择错误。E错误：CT灌注与本临床问题无关，浪费时间与剂量，延误手术。", "tr": "“先CT排除金属异物、再决定能否MRI”是必须条件反射式掌握的安全流程。另注意异物成分不同显示各异：金属与玻璃呈高密度，木质异物可呈低密度而易被误认为气体。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0160", "t": "多选题", "s": "关于颞骨（内耳）高分辨率CT的技术参数，下列正确的有", "o": {"A": "采用≤1 mm的薄层（常用0.5~0.625 mm）采集，实现各向同性体素", "B": "使用高分辨率骨算法（骨核）重建，以突出听小骨与骨迷路的边缘", "C": "缩小显示野对单侧颞骨行靶重建，使像素变小、空间分辨率进一步提高", "D": "观察骨性结构常用骨窗，窗宽约4000 HU、窗位约700 HU", "E": "为降低图像噪声，应改用软组织平滑核并适当增大层厚"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-160", "kp": "颞骨内耳HRCT参数", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】A正确：镫骨脚、砧镫关节、面神经管、前庭导水管等结构均为亚毫米级，必须用亚毫米薄层采集；各向同性体素才能保证任意角度重组（如斜矢状面显示面神经全程）不失真。B正确：颞骨属极高对比结构，骨算法带来的高噪声可被接受，换取的是边缘锐利与细节可辨。C正确：靶重建（像素＝FOV/矩阵）是提高颞骨细节显示的常规手段，通常左右耳分别重建。D正确：颞骨骨窗需要极宽的窗宽（约4000 HU）才能同时容纳致密骨与气房内气体的巨大密度差。【为什么错】E错误：平滑核＋厚层会使听小骨与骨迷路轮廓模糊，从根本上违背HRCT的目的；颞骨HRCT允许较高噪声，但绝不允许分辨率下降。", "tr": "颞骨HRCT三要素：亚毫米薄层、骨算法、靶重建（小FOV）。同一原始数据还可另做软组织核重建观察腮腺、颈静脉孔区，二者互补而非互斥。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0161", "t": "案例分析题", "s": "患儿男，4岁，先天性双耳重度感音神经性听力损失，助听器效果不佳，拟行人工耳蜗植入术。术前需评估内耳发育情况、有无耳蜗骨化、面神经走行变异及蜗神经发育状况，以判断手术可行性与入路。患儿不能配合，需在镇静下完成影像检查。下列影像技术方案最合理的是", "o": {"A": "行颞骨HRCT薄层骨算法扫描并做多平面与斜位重组，重点评价耳蜗形态与骨化、内听道与前庭导水管、面神经管走行及乳突气化，同时结合内耳MRI水成像评价膜迷路与蜗神经", "B": "仅行头颅CT平扫，层厚5 mm，软组织算法重建", "C": "仅行颞骨CT增强扫描，通过强化评估内耳血供", "D": "行头颈部CTA评估内听动脉后决定手术方案", "E": "行颞骨CT灌注成像评价耳蜗血流灌注"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-161", "kp": "人工耳蜗植入术前影像评估", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】A正确。人工耳蜗术前评估需要“骨与膜”两方面信息：HRCT负责骨性结构——耳蜗圈数与畸形（如Mondini畸形）、鼓阶有无骨化闭塞、圆窗龛位置、面神经管有无前移变异（关系到手术安全）、前庭导水管扩大、乳突气化程度与乙状窦位置；MRI内耳水成像负责膜迷路液体信号与蜗神经是否存在及发育情况（蜗神经缺如是植入的重要限制）。二者互补，是国内外指南推荐的标准组合。【为什么错】B错误：5 mm软组织算法根本无法显示亚毫米级的内耳结构，属参数错误。C错误：内耳评估以平扫HRCT为主，增强对骨性结构与蜗神经评价无帮助，还增加风险。D错误：CTA评价的是大血管，与耳蜗植入的关键问题不对应。E错误：CT灌注不能评价内耳微循环，且剂量高、无临床依据。", "tr": "记住“CT看骨、MRI看神经与膜迷路”的分工。术前必须特别关注面神经管变异与蜗神经发育——前者关系手术安全，后者决定植入效果，二者分别由CT与MRI回答。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0162", "t": "单选题", "s": "关于耳部（颞骨）CT检查，下列说法错误的是", "o": {"A": "内耳与听小骨属高对比精细结构，需以薄层加骨算法方能清晰显示", "B": "冠状面（或冠状重组）有助于观察鼓室盖、面神经管鼓室段与半规管", "C": "中耳乳突炎症、胆脂瘤的评估通常平扫即可，怀疑颅内并发症时可加做增强", "D": "同一次薄层采集的数据可另行软组织算法重建，用于观察腮腺、颈静脉孔区等软组织", "E": "采用软组织平滑核重建即可清晰显示镫骨与砧镫关节等微细结构"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-162", "kp": "颞骨CT的算法与平面选择", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】本题选错误项，E错误。镫骨脚厚度不足0.5 mm，软组织平滑核会抑制高频信息、模糊边缘，使听小骨链与砧镫关节难以判断连续性，无法满足传导性聋的评估需求，必须使用高分辨率骨算法。【为什么错】A正确：这是颞骨HRCT的基本原则。B正确：冠状面对鼓室盖（判断有无骨质破坏、颅内并发症风险）、面神经管鼓室段与外半规管瘘的显示优于横断面。C正确：胆脂瘤主要看骨质破坏范围与听骨链侵蚀，平扫即可；疑有乙状窦血栓、脑脓肿等颅内并发症时才需增强或MRI。D正确：这是“一次采集、多种重建”的典型应用，不增加任何剂量。", "tr": "颞骨检查中最常见的技术失误就是算法选错。判断口诀依然是“高对比结构用锐利核”。另注意胆脂瘤本身在CT上是软组织密度影，其诊断依据是骨质破坏形态而非病灶强化。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0163", "t": "多选题", "s": "关于鼻与鼻窦CT检查技术，下列正确的有", "o": {"A": "冠状面图像最有利于显示窦口鼻道复合体（OMC）的解剖与阻塞情况", "B": "鼻窦区骨与气体形成天然高对比，可在保证诊断的前提下采用低剂量参数", "C": "应同时以骨窗和软组织窗观察，兼顾骨质结构与软组织病变", "D": "功能性内镜鼻窦手术前需重点评估筛板高度、纸样板完整性以及视神经管与蝶窦的关系", "E": "鼻窦CT检查前应常规口服稀释碘对比剂充盈上消化道"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-163", "kp": "鼻与鼻窦CT技术要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】A正确：OMC（包括钩突、筛漏斗、半月裂、上颌窦口与前组筛窦）主要位于冠状方向上，冠状面是评价其通畅性的标准平面，也是慢性鼻窦炎术前评估的核心。B正确：鼻窦区对比度极高，即使明显降低mAs仍可判断黏膜增厚与骨质，低剂量鼻窦CT已被广泛采用，对儿童与随访患者尤为重要。C正确：骨窗看骨质破坏、骨壁完整性与解剖变异，软组织窗看黏膜、息肉、真菌球内的高密度钙化与眶内／颅内侵犯。D正确：这三处是FESS手术的“危险区”，术前必须逐一评估，属技师应重点重组呈现的内容。【为什么错】E错误：口服对比剂用于腹部胃肠道显影，与鼻窦检查毫无关系，反而增加不必要的准备与风险。", "tr": "鼻窦题的高频判分点是“冠状面看OMC”与“术前危险区评估”。另注意真菌性鼻窦炎在软组织窗常见窦腔内高密度影，若只看骨窗容易忽略。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0164", "t": "单选题", "s": "关于鼻与鼻窦CT的扫描方式，下列说法正确的是", "o": {"A": "现多采用薄层横断面容积采集，再重组冠状面与矢状面图像，避免患者取俯卧过伸位的不适", "B": "必须采用直接冠状位扫描，任何重组图像都不能替代", "C": "扫描层厚以10 mm为宜，可缩短检查时间", "D": "鼻窦检查必须常规行增强扫描才能显示黏膜病变", "E": "观察鼻窦只需软组织窗，无须骨窗"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-164", "kp": "鼻窦CT的扫描方式", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】A正确。多层螺旋CT的薄层容积采集可获得各向同性数据，重组的冠状面图像质量已可与直接冠状扫描媲美，且患者只需仰卧、无须俯卧头过伸，明显提高舒适度与配合度，也避免了牙科充填物伪影方向的限制。【为什么错】B错误：直接冠状位在多层CT时代已非必需，且颈椎病变者难以配合。C错误：10 mm层厚无法显示钩突、筛板等细小结构，也不能满足重组需求。D错误：鼻窦炎症、息肉、解剖变异的评估以平扫为主，仅在怀疑肿瘤、眶内或颅内并发症时才增强。E错误：骨窗是鼻窦检查不可缺少的，用于判断骨壁破坏、骨质增生硬化与解剖变异。", "tr": "“必须直接冠状扫描”是老旧观念，在多层CT条件下应改为“容积采集＋多平面重组”。凡出现“任何重组都不能替代”这类绝对化表述的，多为错误项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0165", "t": "单选题", "s": "关于口腔颌面部CT检查技术，下列说法错误的是", "o": {"A": "薄层容积采集后可用曲面重建沿牙弓展开，获得类似曲面体层的全牙列与下颌骨图像", "B": "颌面部骨折评估需骨算法重建并结合三维容积再现，以显示骨折线走行与骨块移位", "C": "腮腺区病变宜用软组织算法重建，多需增强以判断病变范围、血供与面神经走行区关系", "D": "金属义齿或牙科充填物可产生放射状伪影，可通过倾斜机架、金属伪影校正算法或高keV虚拟单能量图像减轻", "E": "口腔颌面部检查应统一采用软组织算法与10 mm层厚，以降低辐射剂量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-165", "kp": "口腔颌面部CT检查技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (6)口腔颌面部", "ex": "【为什么对】本题选错误项，E错误。10 mm层厚无法显示牙槽骨、下颌管、颏孔与细小骨折线，也不能满足曲面重建与三维重组对各向同性薄层数据的要求；降低剂量应通过优化管电压、自动管电流调制与迭代重建实现，而不是牺牲层厚与算法。【为什么错】A正确：沿牙弓勾画中心线做CPR可一幅图显示全牙列，是种植牙术前与颌骨病变评估的常规后处理。B正确：颌面部骨折形态复杂，三维VR有助于整体理解骨折类型与移位方向，骨算法保证骨皮质边缘锐利。C正确：腮腺属软组织器官，需软组织核＋增强以判断肿瘤边界、深浅叶关系与血供。D正确：这三种手段是牙科金属伪影的标准应对措施。", "tr": "颌面部同时涉及“骨（需锐利核）”与“腺体（需平滑核）”，正确做法是一次薄层采集、双算法重建。凡以“降低剂量”为名主张加厚层厚的选项通常是错的。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0166", "t": "多选题", "s": "关于颞下颌关节CT检查技术，下列正确的有", "o": {"A": "常规做闭口位与开口位对照，以评价髁突的活动度与位置关系", "B": "斜矢状面（垂直于髁突长轴）图像用于显示髁突与关节窝的前后关系及关节间隙", "C": "斜冠状面图像有助于观察髁突内外侧的骨质改变", "D": "需采用薄层采集与骨算法重建，以显示髁突骨皮质与关节面的细微改变", "E": "关节盘的显示CT优于MRI，故关节盘移位应首选CT检查"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-166", "kp": "颞下颌关节CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (6)口腔颌面部", "ex": "【为什么对】A正确：开闭口位对比是判断髁突活动受限、半脱位与强直的关键，属颞下颌关节检查的规定动作。B正确：斜矢状面垂直于髁突长轴，能真实反映关节前、上、后间隙宽度与髁突位置。C正确：斜冠状面显示髁突内外极骨质硬化、囊变与骨赘。D正确：关节面骨质改变细微，需薄层与骨算法。【为什么错】E错误：关节盘为纤维软骨结构，CT难以直接显示，MRI是关节盘移位、穿孔与关节积液评估的首选与金标准；CT的优势在于骨质改变（骨赘、囊变、强直、骨折）。", "tr": "颞下颌关节“骨看CT、盘看MRI”。另注意两种斜位平面的定位方式：斜矢状面垂直于髁突长轴、斜冠状面平行于髁突长轴，方向易混。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0167", "t": "单选题", "s": "关于喉部CT检查技术，下列说法错误的是", "o": {"A": "扫描层面一般与声带平面（或颈椎椎间隙）平行，层厚2~3 mm或更薄", "B": "检查中嘱患者平静呼吸、避免吞咽与咳嗽，以减少运动伪影", "C": "必要时可嘱患者持续发“衣（e）”音使声带内收，或用改良Valsalva动作（鼓气）使梨状窝与会厌谷扩张，从而显示黏膜面", "D": "增强扫描有助于判断肿瘤范围、喉软骨受侵与颈部淋巴结转移", "E": "扫描过程中应嘱患者反复做吞咽动作，使会厌与声带活动开来以便观察"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-167", "kp": "咽喉部CT扫描技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】本题选错误项，E错误。吞咽会使喉体上下大幅移动，产生严重运动伪影甚至层面遗漏，是喉部CT必须避免的动作；需要动态观察时用的是发音（“e”音）或改良Valsalva等可控、可维持的动作，而非吞咽。【为什么错】A正确：使层面与声带平面平行可避免声带被斜切造成的假性增厚。B正确：平静呼吸下声带外展、声门裂张开，是常规采集状态。C正确：发“e”音使声带内收有助于观察声带活动与前联合；改良Valsalva使梨状窝、会厌谷等隐窝扩张，可显示早期黏膜病变。D正确：喉癌的分期高度依赖增强图像判断软骨侵犯、声门旁间隙与会厌前间隙受累及淋巴结转移。", "tr": "“可控动作（发音、鼓气）”与“不可控动作（吞咽、咳嗽）”是咽喉部检查的分水岭。前者是技术手段，后者是伪影来源。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0168", "t": "案例分析题", "s": "患者男性，62岁，声嘶3个月，喉镜见右侧声带新生物，活检为鳞状细胞癌。临床需评估肿瘤深部浸润范围、声门旁间隙与甲状软骨有无受侵，以及颈部淋巴结转移情况，以决定行部分喉切除还是全喉切除。患者上颌与下颌共有6颗金属烤瓷牙冠。设备为64排CT，具备金属伪影校正与能量成像功能。下列检查方案最合理的是", "o": {"A": "行颈部薄层（≤2 mm）容积增强扫描，注药后约40~50 s采集，范围自颅底至胸廓入口，扫描时平静呼吸、不吞咽、双肩下拉；对牙冠层面采用金属伪影校正或高keV虚拟单能量重建，并加做冠状、矢状重组", "B": "仅行颈部平扫，层厚5 mm，软组织算法重建", "C": "行颈部增强扫描但把延迟时间设为注药后120 s，以获得均匀的静脉期强化", "D": "嘱患者全程持续发“衣（e）”音下完成整个增强扫描，以最大程度显示声带", "E": "先行胸部CT除外远处转移，喉部只做定位像观察即可"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-168", "kp": "喉癌术前CT评估方案", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】A正确。喉癌术前评估要求：薄层增强以判断黏膜下浸润、声门旁与会厌前间隙受累及软骨侵蚀；约40~50 s的延迟兼顾肿瘤强化与淋巴结显示；范围需含颅底至胸廓入口以覆盖各区淋巴结；平静呼吸不吞咽、双肩下拉可减少运动与肩部硬化伪影；针对金属牙冠采用MAR或高keV单能量重建可挽救被伪影污染的层面；多平面重组有助于显示肿瘤上下范围与环状软骨关系，直接影响术式选择。【为什么错】B错误：平扫不能判断软组织浸润深度与淋巴结性质，5 mm层厚亦不足。C错误：120 s属实质／延迟期，肿瘤与正常组织的对比下降，血管与淋巴结分辨也变差。D错误：全程持续发音无法维持数十秒且会造成运动伪影，发音扫描只用于短时补充采集。E错误：本题的临床问题是原发灶分期，不能以定位像代替诊断性扫描。", "tr": "喉癌分期的关键技术点是“薄层＋合适期相＋多平面重组＋伪影控制”。注意金属伪影不是无解的：MAR算法与高keV单能量图像是现代设备的标准武器，比单纯重复扫描有效得多。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0169", "t": "多选题", "s": "关于颈部及甲状腺CT检查与碘对比剂使用，下列正确的有", "o": {"A": "正常甲状腺因含碘丰富，平扫CT值明显高于周围肌肉，一般可达80~100 HU", "B": "近期拟行放射性碘显像或131I治疗者，应避免在此之前使用碘对比剂，通常需间隔数周", "C": "甲状腺功能亢进未控制者使用碘对比剂有诱发甲状腺危象的风险，应慎用并加强观察", "D": "颈部增强扫描有助于区分肿大淋巴结与血管断面，并判断淋巴结有无坏死", "E": "甲状腺病变的CT检查必须口服碘对比剂充盈食管后才能进行"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-169", "kp": "颈部与甲状腺检查的对比剂问题", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】A正确：甲状腺是全身唯一在平扫上呈明显高密度的软组织器官，其CT值下降本身即提示弥漫性病变。B正确：静脉注射的碘负荷会使甲状腺碘池饱和，显著影响放射性碘的摄取，从而干扰显像与治疗效果，故需间隔数周（一般4~8周，具体遵核医学科要求）。C正确：碘负荷可能诱发碘甲亢或甲状腺危象，甲亢未控制者属慎用人群。D正确：增强后血管明显强化、与淋巴结区分开，淋巴结内的坏死区与环形强化是转移的重要征象。【为什么错】E错误：食管充盈不是甲状腺CT的必需步骤；口服对比剂主要用于腹部胃肠道，颈部检查通常无须口服，必要时仅做少量吞服以标记食管，但绝非“必须”。", "tr": "“碘对比剂会影响后续核素检查与治疗”是技师应主动向临床与患者说明的要点，属于检查前沟通的重要内容。另注意平扫甲状腺高密度这一常识，常被用来设计“平扫高密度病灶”的辨析题。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0170", "t": "单选题", "s": "关于颈部软组织CT检查技术，下列说法错误的是", "o": {"A": "扫描范围一般自颅底至胸廓入口，必要时向下包括上纵隔", "B": "患者仰卧，双肩尽量下垂，可用束带向足侧牵拉，以减轻肩部造成的硬化伪影", "C": "采用薄层容积采集，便于冠状与矢状重组评价病变与大血管、气道的关系", "D": "增强延迟一般在注药后40~60 s，兼顾动脉、静脉与淋巴结的强化", "E": "扫描时应嘱患者双上肢上举过头，以减少肩部对射线的衰减"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-170", "kp": "颈部CT扫描范围与体位", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】本题选错误项，E错误。双上肢上举过头是胸部与腹部检查的体位，可使上肢移出扫描野；而颈部检查扫描野在颈根部，上举双臂不仅无法移出肩部，还会使肩胛带上抬、堆积于颈根，加重胸廓入口区的伪影。颈部检查的正确做法是双臂置于体侧、双肩尽量下垂并向足侧牵拉。【为什么错】A正确：这是颈部检查的常规覆盖范围，可包含颈部各区淋巴结。B正确：肩部下拉是减轻胸廓入口区硬化伪影的关键体位技巧。C正确：颈部结构与血管、气道关系密切，多平面重组价值大。D正确：40~60 s的单期延迟兼顾动静脉与淋巴结强化，是颈部常用的增强时相。", "tr": "“双臂上举”只适用于胸腹部。颈部、颅脑、颌面部检查双臂必须置于体侧并尽量下拉肩部——体位题的常见反向陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0171", "t": "单选题", "s": "颈胸交界区（胸廓入口、肩部）CT图像上常出现明显的条纹状伪影，其主要成因与对策是", "o": {"A": "双肩部位射线路径长、衰减差异大，造成线束硬化与光子饥饿；对策为双肩下拉、适当提高管电流或使用自动管电流调制与硬化校正、迭代重建算法", "B": "呼吸运动所致；对策是改行增强扫描", "C": "对比剂用量过大所致；对策是减少对比剂总量", "D": "探测器通道失校所致；对策是重新进行空气校正", "E": "患者头部过度后仰所致；对策是抬高床面"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-171", "kp": "胸廓入口区伪影的成因与对策", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】A正确。肩部横径大、骨与软组织混合，前后位方向的射线路径明显长于侧方，低能光子被大量吸收（线束硬化）且到达探测器的光子严重不足（光子饥饿），表现为水平方向的条纹状伪影。对策包括：体位上双肩尽量下拉；参数上提高该区域mAs（自动管电流调制可自动增大肩部曝光）；算法上使用线束硬化校正、迭代重建，必要时用高keV虚拟单能量图像。【为什么错】B错误：颈部扫描很快，呼吸不是主要成因，且增强不能减轻硬化伪影。C错误：对比剂过量可造成血管旁条纹，但典型的肩部伪影在平扫上同样存在。D错误：探测器失校表现为环状伪影，而非局限于肩部的条纹。E错误：头位后仰影响的是扫描基线与解剖对称性，不是该伪影的成因。", "tr": "分清三类常见伪影的“形态指纹”：环状＝探测器失校；肩部／后颅窝的粗条纹＝硬化与光子饥饿；放射状锐利条纹＝金属；重影／双边＝运动。看形态即可反推成因与对策。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0172", "t": "单选题", "s": "关于胸部常规CT扫描技术，下列说法错误的是", "o": {"A": "常规取仰卧位、双臂上举过头，以避免上肢造成的伪影", "B": "扫描范围自肺尖至肺底并包括双侧肋膈角，需要时可下延至肾上腺水平", "C": "采用深吸气后屏气采集，使肺充分膨胀、减少坠积效应", "D": "图像应同时以肺窗和纵隔窗观察", "E": "胸部扫描可省略定位像，直接按经验范围开始采集"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-172", "kp": "胸部常规CT扫描技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】本题选错误项，E错误。定位像（scout/topogram）是确定扫描起止范围、设置自动管电流调制与器官剂量调制的依据，省略后既可能漏扫病变区域，也使剂量调制无法工作，属原则性错误。【为什么错】A正确：双臂上举可把肱骨与肩胛带移出扫描野，显著减轻伪影。B正确：包全肋膈角避免遗漏胸膜病变，怀疑肺癌分期时常规下延至肾上腺以观察转移。C正确：深吸气屏气使肺泡充分扩张，改善病灶与含气肺的对比，减少肺底坠积影响。D正确：肺窗与纵隔窗提供互补信息，任何一个都不可省。", "tr": "定位像不仅决定范围，还是ATCM剂量调制的基础，其摆位偏差（如患者未居中）会导致管电流估算错误、剂量偏高或图像噪声偏大——这是容易被忽视的质量控制细节。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0173", "t": "多选题", "s": "关于胸部CT图像的窗技术与后处理，下列正确的有", "o": {"A": "肺窗与纵隔窗须同时观察，前者显示肺实质与间质，后者显示纵隔、胸膜与胸壁结构", "B": "冠状面与矢状面重组有助于判断病变的分布特点及其与叶间裂、胸膜、气道的关系", "C": "薄层最大密度投影有助于小结节的检出与血管的鉴别，最小密度投影有助于气道及低密度病变的显示", "D": "纵隔窗观察肺内病变的能力优于肺窗，故肺结节评价应以纵隔窗为主", "E": "为提高信噪比，评价肺间质病变时应增大重建层厚"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-173", "kp": "胸部CT窗技术与重组", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】A正确：肺内含气结构与纵隔软组织的CT值跨度极大，单一窗口无法兼顾，必须双窗观察。B正确：多平面重组能直观显示病变沿支气管血管束、胸膜下或小叶中心的分布模式，这是弥漫性肺病鉴别的重要依据。C正确：薄层MIP把连续几毫米内的高密度结构投影到一幅图上，使小结节“凸显”并可与走行连续的血管区分；MinIP则突出气道、肺气肿与磨玻璃背景中的低密度区。【为什么错】D错误：纵隔窗窗宽窄、窗位高，肺内绝大部分结构落在窗下限之外呈一片黑，无法评价肺结节；纵隔窗在肺内的作用仅限于判断病灶内钙化、脂肪与实性成分。E错误：加厚层厚会因部分容积效应模糊小叶间隔与细支气管壁，使间质病变显示能力下降；间质评价恰恰需要薄层高分辨率。", "tr": "MIP与MinIP的用途方向相反：MIP找“高密度的点”（结节、钙化、强化血管），MinIP找“低密度的腔”（气道、肺气肿）。另注意二者都必须与原始薄层对照，不能单独用于诊断。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0174", "t": "单选题", "s": "关于低剂量CT（LDCT）肺癌筛查，下列说法错误的是", "o": {"A": "筛查用LDCT不使用静脉对比剂", "B": "有效剂量一般控制在1~2 mSv以内，可通过降低管电流、适当降低管电压并结合迭代重建实现", "C": "重建层厚应≤1 mm，以利于小结节的检出与体积定量", "D": "筛查主要面向具备明确危险因素的高危人群，而非全人群普查", "E": "为提高小结节检出率，筛查应改用常规剂量的增强扫描"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-174", "kp": "低剂量CT肺癌筛查", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】本题选错误项，E错误。肺结节与含气肺组织之间存在天然的高对比，低剂量条件下噪声虽增加，但对结节检出的影响很小；改用常规剂量增强既大幅提高受检者的辐射与对比剂风险，又违背筛查“对健康人群大规模、低危害”的基本前提，且增强对结节检出并无额外收益。【为什么错】A正确：筛查为平扫，不用对比剂。B正确：这是LDCT的剂量目标与常用实现手段。C正确：薄层重建是准确测量结节直径／体积、判断磨玻璃成分的前提。D正确：筛查的成本效益建立在高危人群基础上，指南对年龄与吸烟史等有明确限定。", "tr": "筛查与诊断是两种不同性质的检查：筛查追求“低危害、可重复、高检出”，诊断追求“定性准确”。把诊断性方案（增强、多期、常规剂量）套用到筛查上，是概念性错误。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0175", "t": "单选题", "s": "某患者右肺下叶8 mm实性结节，3个月后复查CT以判断结节有无增大。为使前后两次结果具有可比性，下列做法中最重要的是", "o": {"A": "尽量沿用与前次相同的扫描与重建参数（层厚、卷积核、体位与屏气状态），并用同一测量方法在同一后处理软件上进行比较，优先采用半自动体积测量", "B": "本次改用更高剂量扫描，以提高测量精度", "C": "本次改行增强扫描，通过强化值变化判断结节性质改变", "D": "在两台不同厂家的工作站上分别测量后取平均值", "E": "仅凭肉眼在不同层厚的图像上比较结节最大径"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-175", "kp": "肺结节随访的技术一致性", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】A正确。结节随访判断的是“变化”而非“绝对值”，测量的可重复性压倒一切。层厚、卷积核、屏气状态、软件算法都会系统性影响直径与体积测量结果，8 mm结节直径测量的观察者间误差可达1~2 mm，足以掩盖真实生长；采用一致的参数与同一软件的半自动体积测量，可显著降低变异并可计算体积倍增时间。【为什么错】B错误：提高剂量对测量一致性帮助有限，却增加了受照负担，且与前次参数不一致反而引入偏差。C错误：增强并非结节随访的常规手段，强化值受时相与方法影响大，重复性差。D错误：不同软件的分割算法不同，混合测量只会放大变异。E错误：不同层厚下的最大径肉眼比较误差最大，是最不可靠的做法。", "tr": "随访题的判分点永远是“一致性”：同参数、同软件、同方法。体积测量优于二维直径，但也必须在同一算法下纵向比较；跨设备、跨软件的数值不能直接对比。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0176", "t": "多选题", "s": "关于肺动脉CT血管成像（CTPA）的技术要点，下列正确的有", "o": {"A": "团注追踪的监测ROI应置于肺动脉主干（或右心室流出道），阈值多取100 HU左右", "B": "使用相对较少的对比剂并配合生理盐水冲刷，可减轻上腔静脉内高浓度对比剂造成的条纹伪影", "C": "宜采用平静吸气后屏气，避免深大吸气引起一过性对比剂中断", "D": "肺动脉强化不足时，可考虑把管电压降至80~100 kVp以提高碘的对比效率", "E": "心电门控是CTPA的常规必备条件，无门控无法诊断肺栓塞"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-176", "kp": "CTPA的关键技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】A正确：ROI置于目标血管上游的肺动脉主干，可在肺动脉充盈高峰时触发，避免过早或过晚。B正确：右心与上腔静脉内未稀释的高浓度对比剂是右肺动脉旁条纹伪影的主要来源，减量＋盐水冲刷是标准对策。C正确：深大吸气会使下腔静脉未强化血液大量回流右心，稀释肺动脉内对比剂，形成一过性对比剂中断（TIC），是CTPA失败的常见原因。D正确：低kV使碘的衰减显著增强，在肺动脉这种以碘为唯一对比来源的场景中收益尤其明显，还可同步减少对比剂用量。【为什么错】E错误：CTPA常规不使用心电门控。心电门控主要用于评估升主动脉根部与冠脉，或在“胸痛三联”一站式扫描中使用；单纯肺栓塞诊断依靠快速采集即可，加门控反而延长扫描时间、增加剂量。", "tr": "TIC（一过性对比剂中断）是CTPA的标志性技术陷阱，须与真正的充盈缺损鉴别：TIC表现为肺动脉整体强化差、下腔静脉内可见未强化血液分层，而非局限性、边界清楚的充盈缺损。对策是呼吸指令而非加大剂量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0177", "t": "案例分析题", "s": "患者女性，45岁，术后卧床，突发胸闷气促，临床疑肺栓塞行CTPA。技师按“深吸气后屏住”的指令进行扫描，团注追踪ROI置于肺动脉主干、阈值100 HU。图像显示肺动脉主干强化仅约150 HU，段以下肺动脉显示模糊，右心房内可见未强化血液与对比剂形成的分层混合影，上腔静脉内高密度对比剂伴明显条纹伪影，患者配合良好、无明显体动。造成该结果最可能的原因与最合理的改进措施是", "o": {"A": "深大吸气使胸腔负压增加，下腔静脉未强化血液大量回流右心，稀释了肺动脉内对比剂，形成一过性对比剂中断；应改用平静吸气后屏气，并适当优化触发阈值与诊断延迟，必要时提高碘流率或降低管电压", "B": "患者发生了对比剂过敏反应，导致循环中对比剂浓度下降；应立即停止检查并抗过敏治疗", "C": "探测器通道失校造成CT值测量偏低；应立即进行空气校正后重扫", "D": "螺距设置过小导致扫描时间延长；应减小螺距重新扫描", "E": "患者体重过大造成噪声增高；应把层厚增大至5 mm重建以改善强化显示"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-177", "kp": "CTPA强化不足的原因分析", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】A正确。题干提供了三条关键线索：肺动脉强化偏低、右心房内出现未强化血液与对比剂的分层、上腔静脉高浓度对比剂伴条纹伪影——这正是一过性对比剂中断的典型影像组合，机制是深吸气造成胸腔负压骤增、下腔静脉血流突然增加而稀释了经上腔静脉进入右心的对比剂。改进措施首先是把呼吸指令改为“平静吸气后屏气”，其次可优化触发与延迟、提高碘流率或降低kV以提升碘对比。【为什么错】B错误：过敏反应表现为皮疹、喉头水肿、低血压等临床症状，不会造成这种特定的血流稀释影像，且患者情况平稳。C错误：探测器失校的表现是环状伪影与全图CT值异常，而非局限于右心的分层现象。D错误：螺距过小只会延长扫描时间、增加剂量，不产生右心分层影，减小螺距更是南辕北辙。E错误：体重相关的是噪声而非强化程度，且增大层厚只能降噪，不能改善对比剂浓度。", "tr": "遇到“肺动脉强化不足”先看右心与下腔静脉：出现未强化血液分层＝TIC（呼吸原因）；若整体循环时间延长、各腔均强化滞后＝低心排（应改用小剂量测试）。二者对策完全不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0178", "t": "多选题", "s": "关于先天性心脏病的CT检查技术，下列正确的有", "o": {"A": "婴幼儿宜采用低管电压（70~80 kVp）配合迭代重建，以提高碘对比并降低辐射剂量", "B": "采用大螺距快速扫描或前瞻性心电触发，可在自由呼吸或极短屏气下完成采集，减少镇静需求", "C": "对比剂按体重计算（一般1.5~2.0 ml/kg），经细留置针以较低流率注射并配合生理盐水冲刷", "D": "需结合多平面重组、最大密度投影与容积再现，全面显示心内结构、大血管连接与侧支血管", "E": "先心病CT必须常规采用回顾性心电门控全期相扫描，否则无法显示心内结构"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-178", "kp": "先天性心脏病CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (10)先天性心脏病", "ex": "【为什么对】A正确：婴幼儿体厚小，低kV既能显著提升碘的CT值，又可大幅降低剂量，是儿童心血管CT的核心策略。B正确：亚秒级采集使自由呼吸下也能获得可诊断图像，从而减少镇静与麻醉需求，这对婴幼儿的安全意义重大。C正确：儿童血管细，只能用较细留置针与较低流率，靠“低kV＋高浓度／按体重计量＋盐水冲刷”保证强化。D正确：先心病的诊断需要空间关系信息，MPR看断面细节、MIP看血管连续性、VR看整体连接与侧支，三者互补。【为什么错】E错误：回顾性门控辐射剂量高，在儿童中应尽量避免；多数先心病以显示解剖结构与大血管连接为目的，用前瞻性触发或大螺距非门控扫描即可，只有在需要评价心功能或瓣膜运动时才考虑回顾性门控。", "tr": "儿童心血管CT的原则是“能不门控就不门控、能不镇静就不镇静”。凡出现“必须回顾性门控”“必须麻醉”的绝对化选项，基本都是错误项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0179", "t": "案例分析题", "s": "患儿女，6个月，体重6 kg，自出生后间断口唇发绀，超声心动图提示复杂先天性心脏病，疑法洛四联症，需进一步评估肺动脉分支发育情况、有无体肺侧支血管及冠状动脉走行，为手术方案提供依据。患儿哭闹明显，静脉通路为右上肢24 G留置针。设备为具备大螺距扫描与迭代重建功能的多层CT。下列检查方案最合理的是", "o": {"A": "采用70~80 kVp低管电压、自动管电流调制与迭代重建，行大螺距或前瞻性心电触发采集；对比剂按1.5~2.0 ml/kg经右上肢静脉以适宜的低流率注射并盐水冲刷，用团注追踪或小剂量测试确定时相，采集后行MPR、MIP与VR重组", "B": "按成人冠状动脉CTA方案行回顾性心电门控全期相扫描，以获得最完整的信息", "C": "行胸部平扫即可，通过心影形态推断畸形类型", "D": "口服稀释碘对比剂后行胸部扫描，以避免静脉穿刺", "E": "此类患儿应完全以心脏MRI替代CT，不宜行CT检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-179", "kp": "婴幼儿复杂先心病CT方案", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (10)先天性心脏病", "ex": "【为什么对】A正确。该方案同时满足三个要求：一是安全，低kV＋剂量调制＋迭代重建把剂量压到最低，大螺距／前瞻触发把采集时间压到最短从而减少镇静需求；二是有效，按体重给药并用盐水冲刷保证肺动脉与侧支血管足够强化，团注追踪或小剂量测试解决婴儿循环时间快、个体差异大的问题；三是完整，MPR／MIP／VR联合重组可全面展示肺动脉分支发育、体肺侧支与冠脉走行。【为什么错】B错误：回顾性门控剂量高，对以解剖评价为主的先心病属过度检查，对6个月婴儿尤为不适宜。C错误：平扫无法评价肺动脉分支与侧支血管，心影形态推断远不能满足手术需要。D错误：口服对比剂只能显示消化道，与心血管评估无关。E错误：MRI虽无辐射，但检查时间长、婴儿需较深镇静，对小的体肺侧支与冠脉的空间分辨率不及CTA，二者互为补充而非替代。", "tr": "婴幼儿心血管CTA的取舍逻辑是“先缩短时间、再压低剂量、最后保证强化”。注意注射侧的选择与盐水冲刷同样重要：对比剂滞留于上腔静脉可造成右心与邻近结构的严重条纹伪影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0180", "t": "单选题", "s": "关于冠状动脉钙化积分（Agatston积分）的扫描与计算，下列说法错误的是", "o": {"A": "采用非增强扫描，多以前瞻性心电触发的轴位方式采集", "B": "经典标准方案采用3 mm层厚、120 kVp管电压，以保证与既往研究和随访数据可比", "C": "钙化的判定阈值为CT值≥130 HU且达到规定的最小面积", "D": "Agatston积分由每个钙化斑块的面积乘以与其峰值CT值相对应的权重系数后累加得到", "E": "钙化积分应在注射对比剂后的动脉期图像上测量，以便同时评价管腔狭窄"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-180", "kp": "冠状动脉钙化积分", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】本题选错误项，E错误。钙化积分必须在平扫图像上测量：注入对比剂后管腔内的高密度碘会被误判为钙化，使积分严重高估、失去与流行病学数据的可比性。评价管腔狭窄是随后冠脉CTA的任务，二者分别在平扫与增强图像上完成。【为什么错】A正确：前瞻性触发轴扫可在保证心动周期同一时相的前提下把剂量降到最低（通常约1 mSv）。B正确：3 mm层厚、120 kVp是Agatston积分的经典标准，改变层厚或kV会改变积分数值，故随访必须沿用同一方案。C正确：130 HU是标准阈值，同时要求钙化灶达到一定面积或像素数以排除噪声。D正确：权重系数按病灶内峰值CT值分级（130~199、200~299、300~399、≥400分别对应1、2、3、4），面积乘以权重再累加即为总积分。【补充】重度钙化会因部分容积与开花效应高估管腔狭窄，这是冠脉CTA的固有局限。", "tr": "钙化积分的三个“固定”：固定平扫、固定3 mm层厚、固定120 kVp。随访时任何参数改变都会使积分不可比，这是技师必须坚守的质控点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0181", "t": "多选题", "s": "关于冠状动脉CTA检查前使用β受体阻滞剂控制心率，下列正确的有", "o": {"A": "目标是把心率控制在65次/分以下且心律规整，以获得足够的时间分辨率窗口", "B": "口服美托洛尔一般在检查前约1小时给药；心率控制不佳且情况紧急时可在医师监护下静脉分次给药", "C": "支气管哮喘或慢性阻塞性肺疾病急性发作、二度及以上房室传导阻滞、失代偿性心力衰竭、收缩压低于100 mmHg者属禁忌或慎用", "D": "给药后须持续监测心率与血压，警惕严重心动过缓与低血压", "E": "心率越低图像越好，应尽量把心率降至40次/分左右"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-181", "kp": "冠脉CTA的心率控制", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】A正确：心率越低，舒张中晚期的相对静止窗越长，单扇区重建即可获得满意的时间分辨率；心律规整则是保证各扇区数据来自同一时相的前提。B正确：口服起效需约1小时，静脉给药起效快但必须在医师监护、具备心电与血压监测条件下分次滴定。C正确：β受体阻滞剂可诱发支气管痉挛、加重传导阻滞与心力衰竭、引起低血压，上述人群禁用或慎用，必要时改用其他策略（如钙通道阻滞剂或依赖设备的高时间分辨率技术）。D正确：给药后监测是安全底线，出现严重心动过缓需及时处理。【为什么错】E错误：把心率压到40次/分左右不但没有额外的图像收益，还会引起头晕、乏力甚至血流动力学不稳；临床目标是“足够低且稳定”（一般55~65次/分），不是越低越好。", "tr": "“更低更好”式的选项通常是错的。另需记住：心律齐与心率低同等重要，房颤患者即使心率不快，图像质量也可能很差，此时更依赖设备的时间分辨率与心电编辑。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0182", "t": "单选题", "s": "关于冠状动脉CTA检查前使用硝酸甘油，下列说法错误的是", "o": {"A": "目的是扩张冠状动脉、增大管腔直径，改善远段与细小分支的显示", "B": "常用舌下含服0.5 mg（或用喷雾剂），一般在扫描前3~5分钟给予", "C": "用药后可出现头痛、面色潮红与一过性血压下降，应事先告知并监测", "D": "近期（24~48小时内）使用过磷酸二酯酶5抑制剂（如西地那非）者及明显低血压者禁用", "E": "硝酸甘油同时具有明确的减慢心率作用，可代替β受体阻滞剂用于心率控制"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-182", "kp": "冠脉CTA中硝酸甘油的应用", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】本题选错误项，E错误。硝酸甘油是血管扩张剂，可因外周血管扩张、血压下降而引起反射性心动过速，非但不能减慢心率，反而常使心率上升，因此临床上通常在β受体阻滞剂使心率稳定之后再给硝酸甘油，二者作用完全不同、不可互相替代。【为什么错】A正确：冠脉扩张可使管腔直径增加约10%~20%，明显改善远段与分支显示，减少假阳性狭窄。B正确：舌下给药起效快，3~5分钟达效，与扫描时机匹配。C正确：头痛与潮红是最常见的不良反应，事先告知可减少患者紧张与体动。D正确：硝酸酯类与PDE5抑制剂合用可致严重低血压，属明确禁忌；严重主动脉瓣狭窄、肥厚梗阻性心肌病与明显低血压者亦应避免。", "tr": "冠脉CTA的两种药物分工要牢记：β受体阻滞剂降心率、硝酸甘油扩血管，后者还可能引起反射性心动过速。给药顺序一般是先控心率、后扩冠脉。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0183", "t": "单选题", "s": "某患者行冠状动脉CTA，采用回顾性心电门控螺旋采集，扫描时平均心率约80次/分并伴轻度不齐。关于重建期相的选择，最合理的做法是", "o": {"A": "优先在收缩末期（约R-R间期35%~45%）重建，同时在舒张中晚期（约70%~80%）重建作为对照，逐支血管择优选择", "B": "仅在R-R间期75%处重建，因该期相为公认的最佳期相", "C": "仅在R-R间期0%~10%处重建，以避开心脏运动", "D": "固定在R-R间期50%处重建，取心动周期的中点最为稳妥", "E": "心率越快应把重建期相越向后移，故本例宜统一在90%处重建"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-183", "kp": "冠脉CTA最佳重建期相的选择", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】A正确。心动周期中有两个相对静止窗：舒张中晚期（约70%~80%）与收缩末期（约35%~45%）。心率增快时舒张期显著缩短，而收缩末期相对稳定，故高心率（一般＞75次/分）患者优先在收缩末期重建；同时保留舒张期重建作对照，并按不同血管（右冠常在收缩末期更佳，左前降支多在舒张期更佳）分别择优，是回顾性门控的标准工作流程。【为什么错】B错误：75%只是低心率时的经验最佳值，对80次/分且不齐的患者常不适用。C错误：0%~10%处于R波顶点与等容收缩期，心脏运动剧烈，是最差的重建时相之一。D错误：50%附近多处于收缩中期，室壁与冠脉运动速度高，通常伪影明显。E错误：期相并非随心率一味后移；90%已接近下一次心房收缩，运动伪影明显。", "tr": "两个静止窗的口诀：“慢心率取舒张（70%~80%），快心率取收缩末（35%~45%）”。同时记住可按血管分别择优重建，而不是全心统一使用一个期相。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0184", "t": "单选题", "s": "关于基于CT的血流储备分数（FFR-CT），下列说法正确的是", "o": {"A": "它利用常规冠状动脉CTA的图像数据，通过计算流体力学模拟得出血流储备分数，一般无须额外扫描或使用血管扩张药物", "B": "必须在腺苷负荷状态下另做一次CT扫描才能计算", "C": "结果以数值≥0.80提示存在心肌缺血", "D": "它可以完全取代冠脉CTA的形态学评价", "E": "严重钙化、运动伪影或图像质量不佳并不影响其计算的可靠性"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-184", "kp": "FFR-CT的原理与应用", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】A正确。FFR-CT在已获得的冠脉CTA数据基础上重建冠脉树几何模型，结合生理学边界条件用计算流体力学模拟最大充血状态下的压力比值，从而在不额外扫描、不使用腺苷的前提下提供功能学信息，实现“一次扫描、形态＋功能”。【为什么错】B错误：无须腺苷负荷与追加扫描，这正是其相对于负荷心肌灌注的优势。C错误：判读方向相反，通常FFR（含FFR-CT）≤0.80提示病变具有血流动力学意义，＞0.80提示缺血可能性小。D错误：FFR-CT是对形态学评价的补充，其模型本身建立在高质量CTA图像之上，不能取代之。E错误：严重钙化、运动伪影、错层与信噪比过低都会影响管腔分割精度，从而降低计算可靠性，图像质量是FFR-CT的前提条件。", "tr": "FFR的阈值方向是最易记反的点：数值越低越缺血，≤0.80为阳性。另注意FFR-CT“依赖图像质量”，因此规范的心率控制、屏气与伪影管理仍是技师的核心职责。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0185", "t": "多选题", "s": "关于CT评价心功能，下列正确的有", "o": {"A": "回顾性心电门控采集的数据可按一定间隔（如每10%）重建出覆盖整个心动周期的图像", "B": "由舒张末期容积与收缩末期容积可计算每搏输出量与左心室射血分数", "C": "全期相图像可用电影方式回放，观察室壁运动异常", "D": "前瞻性心电触发的窄窗采集通常只覆盖部分时相，一般不能提供完整的心功能信息", "E": "心功能评价应在平扫图像上完成，无须注射对比剂"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-185", "kp": "CT心功能评价", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】A正确：回顾性门控在整个心动周期持续曝光，因而可在任意时相重建，通常以10%为间隔重建10个期相。B正确：分别在舒张末期与收缩末期勾画心内膜，得到EDV与ESV，进而计算SV＝EDV－ESV、EF＝SV/EDV×100%。C正确：多期相电影回放是评价节段性室壁运动异常的基础。D正确：前瞻性触发只在预设的窄时相窗曝光（如70%~80%），数据不足以覆盖收缩末期，故一般无法评价心功能；若需心功能可用宽窗（padding）或回顾性门控，代价是剂量增加。【为什么错】E错误：心内膜面的勾画依赖心腔内血液与心肌之间的密度差，必须有对比剂充盈心腔才能准确分割，平扫无法完成。", "tr": "剂量与信息的取舍关系必须清楚：前瞻性触发低剂量但只有形态，回顾性门控高剂量但可得心功能。技师应按临床问题选择，而不是一律用回顾性门控“求全”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0186", "t": "多选题", "s": "关于心房颤动射频消融术前肺静脉与左心房CT检查，下列正确的有", "o": {"A": "主要评估肺静脉的数目、开口形态、开口内径及变异（如左侧共干、右侧副肺静脉）", "B": "需评估左心耳形态并判断有无血栓；血流淤滞所致的充盈缺损与真性血栓可借助延迟扫描鉴别", "C": "宜采用心电门控采集以减轻心脏搏动伪影，扫描范围须包全左心房与全部肺静脉", "D": "三维重组与左心房内镜视图可为术中三维导航系统提供解剖配准图像", "E": "该检查以评价冠状动脉狭窄程度为首要目的"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-186", "kp": "肺静脉与左心房CT检查", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (12)肺静脉与左心房", "ex": "【为什么对】A正确：消融的靶区是肺静脉开口及前庭部，术者必须事先掌握静脉数目与变异，否则易遗漏异位静脉导致复发。B正确：左心耳血栓是消融的禁忌，早期图像上的充盈缺损可能只是血流淤滞造成的混合不均，延迟30~60秒左右再采集可见淤滞区被对比剂填充而真性血栓仍为缺损。C正确：心电门控可减轻搏动伪影、提高开口测量的准确性；范围不足会遗漏变异静脉。D正确：CT三维模型与电解剖标测系统融合是目前消融导航的常规做法。【为什么错】E错误：本检查的目的是肺静脉与左心房解剖及左心耳血栓评估，冠脉评价并非首要目的（虽然采集数据有时可顺带观察冠脉近段）。", "tr": "“早期充盈缺损≠血栓”是本考点的核心：必须用延迟扫描鉴别血流淤滞与真性血栓，这个技术细节直接影响手术能否进行。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0187", "t": "案例分析题", "s": "患者男性，55岁，突发胸痛3小时急诊就诊。心电图无ST段抬高，肌钙蛋白处于临界水平，D-二聚体升高，血压136/82 mmHg，心率78次/分。临床需在一次检查中同时排除急性冠状动脉综合征、肺动脉栓塞与急性主动脉综合征。设备为具备心电门控与双筒高压注射器的多层CT。下列扫描方案最合理的是", "o": {"A": "采用心电门控的“胸痛三联”一站式扫描，范围自胸廓入口（主动脉弓上）至心脏膈面下方；先控制心率并舌下含服硝酸甘油，采用分段或双流对比剂注射方案，使右心、肺动脉与冠状动脉、主动脉同时获得足够强化后触发采集", "B": "先后独立完成冠脉CTA、CTPA与主动脉CTA三次增强扫描，以保证每次都达到最佳强化", "C": "仅行CTPA，若未见肺栓塞再另行安排冠脉CTA", "D": "仅行冠脉CTA，主动脉与肺动脉可凭该期图像顺带评价，无须调整方案", "E": "先行胸部平扫加床旁超声，待明确诊断后再决定是否行增强CT"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-187", "kp": "胸痛三联一站式扫描", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (13)多部位“一站式”", "ex": "【为什么对】A正确。“三联排除”方案的技术要点有三：其一，范围须自胸廓入口至心底下方，才能覆盖主动脉弓上分支起始、全肺动脉与全心；其二，必须全程心电门控，否则升主动脉与冠脉的搏动伪影会造成假性夹层与冠脉不可评价；其三，对比剂需采用分段（如先高流率再低流率）或双流（对比剂与盐水混合）注射，使右心系统与体循环同时保持足够强化——单纯常规方案往往出现“冠脉好而肺动脉淡”或反之。心率控制与硝酸甘油仍按冠脉CTA要求执行。【为什么错】B错误：三次独立扫描意味着三倍剂量与三份对比剂，急诊时间也不允许。C错误：胸痛病因未明时仅排除肺栓塞可能遗漏致命的夹层与冠脉病变。D错误：常规冠脉CTA的范围与注射方案不能满足肺动脉与全主动脉评价，“顺带看看”不可靠。E错误：患者症状明确且存在多种致命可能，先行平扫加超声会延误诊断，而增强CT正是首选的一站式手段。", "tr": "一站式扫描的取舍是“范围扩大＋门控全程＋对比剂方案改造”，三者缺一不可。注意其剂量与对比剂用量高于单一检查，故须严格把握适应证——仅用于三种病因均不能排除的患者，而非所有胸痛。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0188", "t": "单选题", "s": "关于肝脏多期增强CT的时相设计，下列说法错误的是", "o": {"A": "肝动脉晚期（约注药后30~35 s，或团注追踪腹主动脉触发后延迟约15~20 s）是显示富血供病灶的关键时相", "B": "门静脉期约在注药后60~70 s，此时肝实质强化达到高峰，有利于乏血供病灶的检出", "C": "平衡（延迟）期一般在注药后2~3分钟，有助于观察病灶的廓清与包膜强化", "D": "肝血管瘤呈渐进性向心填充，有时需延迟5~10分钟才能显示完全充填", "E": "肝脏三期扫描的目的只是分别显示肝动脉、门静脉与肝静脉的解剖，与病灶的强化方式无关"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-188", "kp": "肝脏多期增强的时相设计", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】本题选错误项，E错误。肝脏多期扫描的根本目的是利用肝脏双重血供（约75%来自门静脉、25%来自肝动脉）的时间差，观察病灶在不同时相的强化行为——例如肝细胞癌“动脉期高强化、门脉期／延迟期廓清”，转移瘤门脉期呈相对低密度，血管瘤呈渐进性向心填充。血管解剖显示只是附带收益，绝非唯一目的。【为什么错】A正确：动脉晚期肝实质尚未被门静脉血强化，而富血供病灶已明显强化，对比最大。B正确：门脉期肝实质强化峰值使乏血供病灶（转移瘤、脓肿）显示为低密度。C正确：延迟期是判断廓清、包膜强化和纤维成分延迟强化的关键。D正确：这是血管瘤定性的重要征象，延迟不足是误诊主因之一。", "tr": "肝脏时相的设计逻辑是“看病灶强化行为”，不是“看血管”。另注意动脉期分早、晚：动脉早期（约20~25 s）主要用于血管重组，动脉晚期（约30~35 s）才是检出富血供病灶的时相，二者不可混用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0189", "t": "多选题", "s": "关于胰腺CT检查技术，下列正确的有", "o": {"A": "胰腺实质期约在注药后35~45 s，此时正常胰腺强化最明显，与乏血供的胰腺癌形成最大对比", "B": "门静脉期约在注药后65~70 s，用于评价肝转移与门静脉、肠系膜上静脉受侵", "C": "需采用薄层采集并重组，以评价肿瘤与腹腔干、肠系膜上动静脉、门静脉的关系，判断可切除性", "D": "检查前可口服适量清水作为阴性对比剂充盈胃与十二指肠，以衬托胰头轮廓", "E": "胰腺检查应口服高浓度阳性对比剂，以提高胰腺与肠道之间的对比"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-189", "kp": "胰腺双期增强技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】A正确：胰腺实质期（又称胰腺期）正常胰腺强化达峰，而胰腺导管腺癌为乏血供肿瘤，此期病灶与正常胰腺的密度差最大，是检出小胰癌的关键时相。B正确：门脉期兼顾肝转移灶检出与静脉系统受累判断。C正确：可切除性评估依赖肿瘤与血管接触角度、有无包绕与变形，必须薄层＋多平面／曲面重组。D正确：清水作为阴性对比剂能勾勒胃与十二指肠轮廓而不产生高密度干扰，便于观察胰头及钩突。【为什么错】E错误：高浓度阳性对比剂在胰周形成高密度影，会干扰胰腺边缘与钩突的观察，也影响血管重组与CTA后处理，胰腺检查应使用阴性对比剂（水）。", "tr": "腹部检查中“用水还是用碘水”取决于目的：观察肠壁本身、胰腺、血管重组用水（阴性）；单纯需要区分肠管与肿块、观察肠腔充盈用稀释碘水（阳性）。胰腺检查用阳性对比剂是常见的方案性错误。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0190", "t": "单选题", "s": "关于肾脏多期增强CT，下列说法错误的是", "o": {"A": "皮髓质期约在注药后25~40 s，皮质明显强化而髓质尚未强化，皮髓质分界清楚", "B": "肾实质期约在注药后80~120 s，皮质与髓质强化趋于均一，是检出肾实质内小病灶的最佳时相", "C": "排泄期一般在注药后5~10分钟，用于观察肾盂肾盏与输尿管的对比剂充盈情况", "D": "仅依据皮髓质期图像，容易把强化的肥大肾柱或尚未强化的髓质误判为占位性病变", "E": "肾实质内小病灶的检出以皮髓质期最佳，实质期与排泄期均可省略"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-190", "kp": "肾脏多期增强的时相与价值", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】本题选错误项，E错误。皮髓质期虽有利于显示肾皮质表浅病变与肾血管，但此期髓质尚未强化呈相对低密度，位于髓质内的小病灶会被“淹没”；肾实质期皮髓质强化均一，背景一致，才是小病灶检出的最佳时相。排泄期则负责集合系统与尿路评价，二者都不能随意省略。【为什么错】A正确：这是皮髓质期的时间与影像特征。B正确：这是肾实质期的定义与价值所在。C正确：排泄期的时间窗与目的准确，肾功能减退者需相应延长。D正确：肥大肾柱（Bertin柱）在皮髓质期强化明显而易被误认为富血供病灶，在实质期与皮质强化一致即可鉴别，这正是必须做实质期的重要原因之一。", "tr": "“皮髓质期看血管与皮质，实质期查小病灶，排泄期看尿路”——三期各司其职。把皮髓质期当成万能期相是常见误区，也是肾柱假瘤误诊的根源。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0191", "t": "多选题", "s": "关于CT尿路成像（CTU）的剂量优化与技术改良，下列正确的有", "o": {"A": "分次团注（split-bolus）技术把对比剂分两次注射，使肾实质强化与集合系统排泄显影在同一次扫描中同时呈现", "B": "分次团注可减少扫描期数，从而明显降低检查的总辐射剂量", "C": "对年轻患者可考虑省略真实平扫，或用双能量虚拟平扫替代平扫以减少一次曝光", "D": "适当水化、变换体位或使用腹部压迫带，有助于肾盂肾盏与输尿管的充盈显影", "E": "分次团注技术的主要优势在于能更精确地区分皮髓质期与肾实质期的强化差别"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-191", "kp": "CTU的分次团注与剂量优化", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】A正确：先注射一部分对比剂使其进入集合系统，间隔数分钟后再注射剩余部分并在实质期扫描，一次采集即可同时看到强化的肾实质与充盈对比剂的尿路。B正确：期数由三期减为两期甚至一期，剂量随之显著下降，这正是split-bolus的核心价值。C正确：双能量虚拟平扫可从增强数据中减除碘生成类平扫图像，用于判断有无高密度结石／出血，从而省去一次真实平扫。D正确：充分的尿量、体位变换（如俯卧位或轻度头低位）与腹部压迫均可改善集合系统与输尿管的扩张充盈，减少节段性显影不良造成的假象。【为什么错】E错误：分次团注恰恰把不同时相的强化“叠加”在同一幅图像上，因而牺牲了各期强化的独立性，无法用于精细区分皮髓质期与实质期；若需要分辨各期强化行为（如肾肿瘤定性），仍应采用常规分期扫描。", "tr": "split-bolus是“以时相独立性换取剂量下降”的折中方案，适合以尿路评价为主要目的者；对需要定性肾脏占位的病例反而不适用。技术选型必须与临床问题匹配。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0192", "t": "单选题", "s": "关于盆腔CT检查前的准备，下列说法错误的是", "o": {"A": "检查前适度饮水使膀胱充盈，有助于区分膀胱与邻近肠管、子宫及附件", "B": "可提前口服稀释对比剂或经直肠灌入适量对比剂／气体，以标记肠管、避免把肠襻误认为肿块", "C": "女性患者必要时可放置阴道标记物，帮助判断病变与阴道穹隆的关系", "D": "检查前应去除盆腔区域的金属物品，如腰带扣、拉链与金属纽扣", "E": "盆腔检查要求膀胱完全排空，以免尿液影响观察"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-192", "kp": "盆腔CT检查前准备", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】本题选错误项，E错误。盆腔CT要求膀胱适度充盈而非排空：充盈的膀胱可把小肠襻推出盆腔、勾勒膀胱壁轮廓，并为子宫、附件与直肠提供解剖参照；完全排空时膀胱壁增厚皱缩，既难以评价膀胱本身，肠襻又会堆积于盆腔造成混淆。当然过度充盈也不必要，以患者有尿意但可耐受为宜。【为什么错】A正确：这是盆腔检查最基本的准备。B正确：未标记的肠襻是盆腔“假肿块”的常见来源。C正确：阴道标记物有助于确定病变下界与阴道受累情况。D正确：金属物品产生放射状伪影，应事先去除。", "tr": "膀胱“适度充盈”是盆腔与前列腺检查的通则；与之相对，泌尿系结石平扫并不强求充盈，CTU排泄期则需要合理的尿量。准备要求随检查目的而变，不可一概而论。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0193", "t": "多选题", "s": "关于盆腔CT检查技术，下列正确的有", "o": {"A": "采用薄层容积采集，便于多平面重组评价病变与膀胱、直肠、子宫及盆壁的关系", "B": "增强时相依临床问题而定，如子宫病变常用双期观察病灶与肌层的强化差别", "C": "髋关节假体造成的金属伪影可采用金属伪影校正算法、高keV虚拟单能量图像或适当提高管电压来减轻", "D": "评估直肠病变时可经直肠注入适量气体或水，使肠壁展开、便于观察肠壁增厚与外侵", "E": "盆腔CT对子宫内膜与结合带的显示优于MRI，是宫颈癌与子宫内膜癌分期的首选方法"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-193", "kp": "盆腔CT扫描与伪影处理", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】A正确：盆腔器官毗邻复杂，矢状与冠状重组对判断肿瘤侵犯层次至关重要。B正确：子宫肌层与内膜、肌瘤与腺肌症的强化时间差需多期观察。C正确：这三种手段是关节假体伪影的标准应对方案，其中高keV单能量图像效果最显著。D正确：肠腔充盈（气体或水）可使肠壁伸展，避免收缩的肠壁被误判为增厚。【为什么错】E错误：MRI软组织分辨率远高于CT，能清晰区分子宫内膜、结合带与肌层，是宫颈癌与子宫内膜癌局部分期的首选；CT主要用于评价淋巴结、远处转移与不能行MRI者。", "tr": "妇科肿瘤局部分期首选MRI，CT负责“远处与淋巴结”。凡称“CT对子宫内膜、结合带显示优于MRI”的选项一律为错，这是软组织对比的基本规律。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-0194", "t": "单选题", "s": "关于脊柱CT检查技术，下列说法错误的是", "o": {"A": "以椎间盘为观察重点时，可倾斜机架使扫描层面平行于相应的椎间隙", "B": "同一次薄层采集的数据应分别以骨算法与软组织算法重建，用于观察骨质与椎间盘、椎管内软组织", "C": "薄层采集后行矢状面与冠状面重组，有助于评价椎体压缩、滑脱与椎管狭窄程度", "D": "阅片时须同时使用骨窗与软组织窗", "E": "脊柱外伤患者为加快检查速度，应改取俯卧位并先行去除颈托等固定装置"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-194", "kp": "脊柱CT检查技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】本题选错误项，E错误。脊柱外伤（尤其颈椎）在未排除不稳定骨折前，严禁随意翻身或去除颈托等固定装置，否则可能造成脊髓继发损伤，这是严重的安全事故。正确做法是保持仰卧、维持固定，必要时用轴向翻身法由多人协作搬运，颈托一般不必去除（现代颈托多为低密度材料，伪影有限），确需去除时须由临床医师评估并保护颈椎。【为什么错】A正确：机架倾斜可使层面与椎间隙平行，避免斜切造成的假性膨出。B正确：一次采集、双算法重建是脊柱检查的常规。C正确：矢状重组是评价椎体压缩程度、滑脱分度与椎管前后径的关键。D正确：骨窗看骨折线、骨质增生与骨性椎管，软组织窗看椎间盘突出、韧带钙化与椎管内血肿。", "tr": "凡涉及“为提高效率而取消固定、随意搬动外伤患者”的选项一律为错。技术效率永远让位于患者安全，这类题考的是职业素养与风险意识。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0195", "t": "案例分析题", "s": "患者男性，52岁，腰椎后路融合内固定术后1年，近3个月出现右下肢放射痛，临床需评价椎弓根螺钉位置、有无松动及右侧神经根管狭窄情况。常规腰椎CT图像上钛合金螺钉周围可见明显放射状条纹伪影，遮盖了相邻的神经根管与椎间孔结构。设备具备能量成像与金属伪影校正功能。下列处理方案最合理的是", "o": {"A": "适当提高管电压与管电流、采用薄准直与较小螺距重新采集，重建时启用金属伪影校正算法，并生成高keV虚拟单能量图像；后处理时沿螺钉长轴做斜位重组与斜矢状重组观察神经根管", "B": "把管电压降至80 kVp以减少射线硬化，从而消除金属伪影", "C": "改用高分辨率骨算法并把窗宽调至最大，即可完全消除金属伪影", "D": "改行腰椎MRI检查，因MRI不会产生任何金属相关伪影", "E": "直接在报告中说明因金属伪影无法评价，建议临床自行判断"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-195", "kp": "脊柱内固定术后金属伪影的处理", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】A正确。金属伪影的成因是线束硬化、光子饥饿、散射与投影数据缺失，对策应从采集、重建、后处理三个层面同时入手：采集端提高kV与mAs增强穿透、减小准直与螺距增加采样密度；重建端启用MAR类算法对缺失投影做插值补偿；能量成像端生成130~150 keV虚拟单能量图像显著削弱硬化伪影；后处理端沿螺钉长轴做斜位重组，可让条纹方向与观察平面错开，从而看清神经根管与椎间孔。【为什么错】B错误：方向完全相反，降低kV会加重线束硬化与光子饥饿，使伪影更明显。C错误：骨算法会锐化条纹，加大窗宽只是压缩灰阶显示，均不能改变数据本身的缺陷。D错误：MRI在金属植入物附近同样存在磁敏感伪影（甚至可能更严重），且需先确认植入物的MRI兼容性，不能说“不会产生任何伪影”。E错误：在具备MAR与能量成像条件的情况下放弃技术补救、直接给出不可评价结论，是不负责任的做法。", "tr": "金属伪影的处理口诀是“高kV、高mAs、薄准直、小螺距、MAR算法、高keV单能量、斜位重组”。特别注意与低剂量策略中的“降kV”方向相反——目的不同，参数取向就相反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-0196", "t": "单选题", "s": "关于四肢骨关节及软组织CT检查技术，下列说法错误的是", "o": {"A": "应采用薄层采集，并分别以骨算法与软组织算法重建", "B": "关节内骨折（如胫骨平台、跟骨、髋臼骨折）常需三维重组显示骨折块移位与关节面塌陷程度", "C": "检查时应尽量把被检肢体置于扫描野中心，必要时行双侧对比扫描", "D": "软组织肿块的评估常需增强扫描，以观察其血供、边界与邻近血管神经的关系", "E": "四肢检查因骨骼密度高、对比良好，无须再用软组织窗观察"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-196", "kp": "四肢骨关节及软组织CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】本题选错误项，E错误。软组织窗是四肢检查不可缺少的：关节积液／积血、肌腱与韧带钙化、软组织肿块、脓肿与气体、血肿等均需在软组织窗观察；只看骨窗会漏掉骨折以外的重要信息，如骨筋膜室内的血肿或异物。【为什么错】A正确：薄层＋双算法是标准流程，一次采集即可满足骨与软组织两方面需求。B正确：关节内骨折的治疗决策取决于关节面塌陷与骨块移位，三维重组是术前评估的常规。C正确：置于扫描野中心可获得最佳空间分辨率与最小的射束硬化影响；双侧对比有助于判断细微不对称。D正确：软组织肿块的定性与术前规划依赖增强所显示的血供与边界。", "tr": "“看什么用什么窗”是四肢检查的基本功。另注意肢体常需偏中心摆放（如单侧上肢），此时应尽量把患侧置于机架中心并缩小FOV靶重建，以避免边缘区域分辨率下降与伪影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1001", "t": "单选题", "s": "CT值定义为某物质对X线的衰减系数与水的衰减系数相比所得的值，水的CT值规定为", "o": {"A": "－1000HU", "B": "0HU", "C": "＋100HU", "D": "＋1000HU", "E": "－500HU"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-001", "kp": "CT值基准", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】CT值的定义以水为基准，规定水的CT值为0HU，空气为－1000HU，骨约为＋1000HU，故B正确。\n【为什么错】A：－1000HU是空气的CT值。C、D：＋1000HU为致密骨CT值，＋100HU并非标准基准值。E：－500HU约介于空气与软组织之间，不是水的CT值。", "tr": "CT值基准三件套：水0HU、空气－1000HU、骨约＋1000HU，务必牢记。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1002", "t": "单选题", "s": "空气的CT值约为", "o": {"A": "0HU", "B": "＋1000HU", "C": "－1000HU", "D": "－500HU", "E": "＋500HU"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-002", "kp": "空气CT值", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】按CT值标度，空气对X线衰减最小，其CT值规定为约－1000HU，故C正确。\n【为什么错】A：0HU为水的CT值。B：＋1000HU为致密骨的CT值。D：－500HU介于脂肪与软组织之间。E：＋500HU为较高密度组织，并非空气。", "tr": "牢记水、空气、骨三个基准CT值，这是CT值换算与窗技术的基础。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1003", "t": "单选题", "s": "关于窗宽和窗位的叙述，正确的是", "o": {"A": "窗宽增大，图像对比度增大", "B": "窗位是窗的中心值，决定图像灰度中心", "C": "窗宽是指图像亮度范围", "D": "窗位增大，显示的组织CT值范围变宽", "E": "窗宽窗位只影响CT值，不影响图像显示"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-003", "kp": "窗宽窗位概念", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】窗位是窗的中心值，即显示灰阶的中心CT值，决定图像灰度中心，故B正确。\n【为什么错】A：窗宽增大时显示范围变宽，对比度反而降低。C：窗宽指显示的CT值范围而非亮度范围。D：窗位变化改变显示中心，不改变显示范围（范围由窗宽决定）。E：窗宽窗位正是图像显示技术，直接影响图像显示效果。", "tr": "窗宽决定显示范围（管对比度），窗位决定显示中心（管亮度/灰度中心），二者不可混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1004", "t": "单选题", "s": "当窗宽增大时，图像的变化是", "o": {"A": "对比度增大，显示范围变窄", "B": "对比度降低，显示CT值范围增宽", "C": "亮度明显增高", "D": "空间分辨力提高", "E": "密度分辨力提高"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-004", "kp": "窗宽对图像的影响", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】窗宽增大意味着可显示的CT值范围增宽，同一灰阶级差对应更大的CT值差，因此图像对比度降低，故B正确。\n【为什么错】A：窗宽增大显示范围增宽而非变窄，对比度降低而非增大。C：亮度主要由窗位决定，与窗宽无直接对应。D：窗宽不影响空间分辨力。E：窗宽增大密度分辨力并不提高，反而因对比度下降而影响密度区分。", "tr": "窗宽管范围，窗宽越大对比度越低；窗位管亮度中心。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1005", "t": "单选题", "s": "窗位的作用是", "o": {"A": "决定显示的CT值范围", "B": "决定窗的中心CT值，即图像灰度中心", "C": "提高图像对比度", "D": "降低噪声", "E": "提高空间分辨力"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-005", "kp": "窗位作用", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】窗位是窗的中心值，窗中心CT值被映射为灰阶中心，决定图像的整体灰度水平，故B正确。\n【为什么错】A：显示范围由窗宽决定。C：对比度受窗宽影响。D：窗位不能降低噪声。E：空间分辨力与像素、焦点有关，与窗位无关。", "tr": "窗宽定范围、窗位定中心，观察不同密度组织应调节窗位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1006", "t": "单选题", "s": "螺旋CT螺距（pitch）的计算公式是", "o": {"A": "床速（mm/s）×旋转时间（s）÷准直器宽度（mm）", "B": "准直器宽度÷床速", "C": "层厚×矩阵", "D": "扫描时间÷旋转时间", "E": "床速÷旋转时间"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-006", "kp": "螺距公式", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】螺距＝扫描架旋转一周期间床的移动距离÷准直器宽度，即床速×旋转时间÷准直宽度，故A正确。\n【为什么错】B、C：均不是螺距定义式。D：扫描时间与旋转时间的比值不构成螺距。E：床速÷旋转时间量纲不对，螺距为无量纲比值。", "tr": "螺距是床移动距离与准直宽度的无量纲比值；螺距增大时扫描速度快、层间重叠减少，但密度分辨力下降。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1007", "t": "单选题", "s": "当螺距等于1时，其含义是", "o": {"A": "床速与准直器宽度相等", "B": "旋转一周床移动距离等于准直器宽度", "C": "扫描时间为1秒", "D": "层厚为1mm", "E": "矩阵为1:1"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-007", "kp": "螺距等于1的含义", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】螺距等于1时，扫描架旋转一周床的移动距离恰好等于准直器宽度，层间无重叠也无间隔，故B正确。\n【为什么错】A：螺距等于1并不表示床速与准直宽度相等，二者单位不同。C：螺距与扫描时间无关。D：螺距与层厚无直接对应。E：矩阵与螺距无关。", "tr": "螺距＝1是连续无间隔扫描；螺距＞1有间隔可加快扫描，螺距＜1有重叠。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1008", "t": "单选题", "s": "CT图像矩阵的概念是指", "o": {"A": "视野大小", "B": "构成图像行和列的像素数目", "C": "层厚大小", "D": "像素灰度级数", "E": "探测器数目"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-008", "kp": "矩阵概念", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】矩阵是排列成行和列的像素阵列，如512×512即图像由512行512列像素组成，故B正确。\n【为什么错】A：视野是扫描范围。C：层厚是断面的厚度。D：灰度级数由位深决定。E：探测器数目决定原始数据的采样，不等于矩阵。", "tr": "矩阵决定像素多少，视野与矩阵共同决定像素大小（像素大小＝视野÷矩阵）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1009", "t": "单选题", "s": "当矩阵固定时，缩小视野（FOV）会使", "o": {"A": "像素增大，空间分辨力降低", "B": "像素减小，空间分辨力提高", "C": "像素不变", "D": "密度分辨力提高", "E": "噪声不变"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-009", "kp": "视野与像素的关系", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】像素大小＝视野÷矩阵，矩阵固定时视野缩小则像素减小，像素越小空间分辨力越高，故B正确。\n【为什么错】A：视野缩小像素减小而非增大。C：像素随视野改变。D：像素减小通常光子统计量下降，密度分辨力不提高甚至下降。E：像素减小噪声相对增大。", "tr": "缩小FOV提高空间分辨力的前提是矩阵不变；靶扫描正是利用此原理。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1010", "t": "单选题", "s": "像素大小（mm）的计算公式为", "o": {"A": "视野÷矩阵", "B": "矩阵÷视野", "C": "视野×矩阵", "D": "层厚÷矩阵", "E": "矩阵÷层厚"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-010", "kp": "像素大小计算", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】像素大小等于重建视野除以矩阵的行数，即FOV÷矩阵，故A正确。\n【为什么错】B：矩阵÷视野恰为像素大小的倒数。C：二者相乘量纲不对。D、E：层厚与像素大小无关。", "tr": "如FOV＝256mm、矩阵512，则像素＝0.5mm；像素越小空间分辨力越高。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1011", "t": "单选题", "s": "影响CT空间分辨力的主要因素是", "o": {"A": "像素大小", "B": "窗宽窗位", "C": "对比剂浓度", "D": "扫描层距", "E": "床速"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-011", "kp": "空间分辨力影响因素", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】空间分辨力主要取决于像素大小，像素越小空间分辨力越高，此外还与焦点、探测器孔径、算法等有关，故A正确。\n【为什么错】B：窗宽窗位只影响显示，不影响原始分辨力。C：对比剂影响密度对比而非空间分辨力。D：层距影响相邻层面连续性，不直接决定层面内空间分辨力。E：床速影响扫描覆盖与层间关系，不决定空间分辨力。", "tr": "空间分辨力看像素大小；密度分辨力看剂量、层厚与噪声，两者常此消彼长。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1012", "t": "单选题", "s": "提高CT密度分辨力的有效措施是", "o": {"A": "缩小像素", "B": "降低管电流", "C": "增加层厚或增大管电流", "D": "减小矩阵", "E": "增大窗宽"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-012", "kp": "密度分辨力影响因素", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】密度分辨力主要受噪声影响，增大层厚或增大管电流可增加X线光子数、降低噪声，从而提高密度分辨力，故C正确。\n【为什么错】A：缩小像素使每个像素光子量减少，噪声增大，密度分辨力下降。B：降低管电流减少光子数，噪声增大。D：减小矩阵使像素增大，虽噪声降低但空间分辨力下降，并非提高密度分辨力的首选。E：窗宽只影响显示。", "tr": "空间分辨力与密度分辨力常相互制约：薄层提空间分辨力、降密度分辨力；大剂量提密度分辨力。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1013", "t": "单选题", "s": "部分容积效应的正确解释是", "o": {"A": "同一层面内包含多种密度组织时，CT值是各组织的平均值", "B": "扫描床移动造成的伪影", "C": "探测器响应不一致", "D": "X线硬化效应", "E": "运动产生的伪影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-013", "kp": "部分容积效应", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】部分容积效应指扫描层厚内包含多种不同密度的组织，测得的CT值是该层内各组织CT值的加权平均值，故A正确。\n【为什么错】B：床移动造成的是运动伪影而非部分容积效应。C：探测器响应不一致引起的是环形伪影。D：X线硬化是射束硬化伪影。E：运动伪影是患者活动所致。", "tr": "减小部分容积效应的方法是采用薄层扫描或缩小扫描层厚。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1014", "t": "单选题", "s": "心电编辑主要用于解决下列哪种情况导致的图像错位", "o": {"A": "呼吸运动", "B": "心律不齐", "C": "吞咽动作", "D": "金属异物", "E": "肠蠕动"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-014", "kp": "心电编辑用途", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】心电编辑是对心律不齐患者的心电门控扫描数据进行编辑校正，将异常心动周期内采集的数据用相邻正常周期的数据替代，消除图像错位，故B正确。\n【为什么错】A：呼吸运动伪影靠屏气训练解决。C：吞咽影响头颈部，与心电无关。D：金属异物伪影需去金属或用特殊重建。E：肠蠕动伪影用低张药或快速扫描。", "tr": "心电编辑针对心律不齐（如房早、房颤），是冠状动脉CTA质量控制的重要内容。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1015", "t": "单选题", "s": "下列关于心电门控扫描的叙述，正确的是", "o": {"A": "回顾性心电门控辐射剂量低于前瞻性心电门控", "B": "前瞻性心电门控可任意选择心动周期时相重建", "C": "回顾性心电门控扫描可对心动周期任意时相进行重建", "D": "心电门控只用于胸部平扫", "E": "心电编辑与心电门控无关"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-015", "kp": "心电门控方式比较", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】回顾性心电门控是在连续采集的同时记录心电信号，扫描后可根据需要选择心动周期的任意时相进行重建，故C正确。\n【为什么错】A：回顾性心电门控全程扫描，辐射剂量高于前瞻性。B：前瞻性心电门控在预定时相触发扫描，重建时相选择受限。D：心电门控主要用于心脏冠脉CTA，不是胸部平扫。E：心电编辑是对心电门控数据的校正，密切相关。", "tr": "前瞻性门控剂量低、对心率要求高；回顾性门控剂量高、可任意时相重建，常用于心律不齐。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1016", "t": "单选题", "s": "CT平扫是指", "o": {"A": "不注射对比剂的扫描", "B": "注射对比剂后的扫描", "C": "仅扫描定位像", "D": "低剂量扫描", "E": "高分辨扫描"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-016", "kp": "平扫定义", "ch": "九、CT检查技术 → 2.检查方法 → (1)平扫", "ex": "【为什么对】平扫即普通扫描，是不经静脉注射对比剂直接进行的扫描，故A正确。\n【为什么错】B：注射对比剂后扫描为增强扫描。C：定位像只是扫描前定位用的数字图像。D：低剂量扫描是减少辐射剂量的一种扫描方式。E：高分辨扫描是特殊扫描技术。", "tr": "平扫与增强扫描、低剂量扫描、高分辨扫描是不同维度的分类，注意区分。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1017", "t": "单选题", "s": "颅脑外伤患者急诊CT检查，首选检查方法为", "o": {"A": "增强扫描", "B": "平扫", "C": "CT灌注", "D": "CTA", "E": "能量成像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-017", "kp": "颅脑外伤首选平扫", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑外伤怀疑颅内出血、骨折时首选CT平扫，可快速、准确显示急性出血（高密度）及颅骨骨折，无需注射对比剂，故B正确。\n【为什么错】A：急性出血平扫即可显示，增强无益且延误时间。C：灌注用于缺血评估，非外伤常规。D：CTA用于血管病变。E：能量成像非外伤首选。", "tr": "急性颅内出血CT平扫呈高密度，是神经外科急诊处理的重要依据。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1018", "t": "单选题", "s": "高分辨力CT（HRCT）的扫描特点是", "o": {"A": "厚层扫描，软组织算法重建", "B": "薄层扫描，高空间频率算法（骨算法）重建", "C": "薄层扫描，平滑算法重建", "D": "低剂量扫描", "E": "增强扫描"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-018", "kp": "HRCT扫描特点", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】HRCT采用薄层扫描（层厚1～2mm），并用高空间频率算法（骨算法）重建，以提高空间分辨力，故B正确。\n【为什么错】A：HRCT用薄层而非厚层。C：平滑算法降低空间分辨力，与HRCT目的相反。D：低剂量是剂量控制策略，不是HRCT的成像特点。E：增强扫描与HRCT是不同概念。", "tr": "HRCT＝薄层＋骨算法（高空间频率），用于肺弥漫性病变、内耳等精细结构。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1019", "t": "单选题", "s": "HRCT最常用于下列哪种病变的检查", "o": {"A": "弥漫性肺疾病", "B": "肝脏占位", "C": "肾结石", "D": "股骨头骨折", "E": "腹膜后血肿"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-019", "kp": "HRCT临床应用", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】HRCT以高空间分辨力显示肺小叶结构，是诊断弥漫性肺疾病（如间质性肺病、肺气肿）的重要技术，故A正确。\n【为什么错】B：肝脏占位多用常规层厚增强扫描。C：肾结石用低剂量或常规平扫。D：股骨头骨折可平扫+三维重建。E：腹膜后血肿用常规增强扫描。", "tr": "HRCT经典应用：弥漫性肺疾病、内耳颞骨、颅底精细结构。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1020", "t": "单选题", "s": "CT薄层扫描的层厚一般是指", "o": {"A": "5mm", "B": "10mm", "C": "2mm及以下", "D": "8mm", "E": "15mm"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-020", "kp": "薄层扫描层厚", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】薄层扫描一般指层厚≤2mm（常为1～2mm甚至0.5mm），用于观察细小结构如内耳、垂体、椎间盘等，故C正确。\n【为什么错】A、B、D：5～10mm多为常规扫描层厚。E：15mm为厚层扫描。", "tr": "常规层厚5～10mm，薄层≤2mm；薄层可减少部分容积效应、提高空间分辨力。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1021", "t": "单选题", "s": "低剂量CT扫描主要适用于", "o": {"A": "肺癌筛查", "B": "冠脉CTA", "C": "肝脏三期增强", "D": "CT灌注", "E": "骨髓病变诊断"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-021", "kp": "低剂量CT应用", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】低剂量CT通过降低管电流或管电压减少辐射剂量，主要用于肺癌高危人群筛查，故A正确。\n【为什么错】B：冠脉CTA需要高时间分辨力与高信噪比，不能用低剂量。C：增强多期扫描需足够的密度分辨力。D：灌注扫描需连续采集，噪声要求高。E：骨髓病变显示需要良好密度分辨力，低剂量不适用。", "tr": "低剂量扫描以牺牲部分密度分辨力为代价，适合肺小结节等高对比病变筛查。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1022", "t": "单选题", "s": "CT靶扫描（放大扫描）的主要特点是", "o": {"A": "增大视野，观察整体", "B": "缩小视野，对兴趣区放大重建，提高空间分辨力", "C": "增加层厚", "D": "降低管电流", "E": "增大螺距"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-022", "kp": "靶扫描特点", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】靶扫描是缩小重建视野，对感兴趣区域进行放大重建，使像素变小、空间分辨力提高，常用于肺小结节、垂体等，故B正确。\n【为什么错】A：靶扫描是缩小视野而非增大。C：靶扫描通常配合薄层，而非增厚。D：降低管电流不是靶扫描的本质。E：靶扫描与螺距无关。", "tr": "靶扫描＝小视野放大重建；注意与图像后处理放大（只是放大显示）的区别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1023", "t": "单选题", "s": "CT增强扫描的目的是", "o": {"A": "提高空间分辨力", "B": "利用碘对比剂增加组织间密度对比，观察病灶血供", "C": "减少辐射剂量", "D": "消除运动伪影", "E": "代替平扫"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-023", "kp": "增强扫描目的", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】增强扫描经静脉注射碘对比剂，利用不同组织、病灶血供差异产生密度变化，提高病灶与正常组织的密度对比，有利于病变定性与血供评估，故B正确。\n【为什么错】A：空间分辨力与增强无直接关系。C：增强不减少辐射剂量。D：增强不能消除运动伪影。E：增强不能代替平扫，二者常互补。", "tr": "增强扫描的关键是掌握延迟时间，使靶器官/病灶处于最佳强化期。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1024", "t": "单选题", "s": "肝脏增强CT动脉期的延迟时间一般为", "o": {"A": "15秒内", "B": "25～30秒", "C": "60～70秒", "D": "120～180秒", "E": "10分钟"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-024", "kp": "肝脏动脉期延迟时间", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肝脏增强扫描动脉期一般在注药后25～30秒扫描，此时肝动脉及富血供病变强化明显，故B正确。\n【为什么错】A：15秒内对比剂未充分到达肝动脉。C：60～70秒为门静脉期。D：120～180秒为平衡期。E：10分钟为延迟期，用于血管瘤等延迟强化。", "tr": "肝动脉期25～30s、门脉期60～70s、平衡期120～180s，是肝脏三期增强经典时间窗。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1025", "t": "单选题", "s": "肝脏增强CT门静脉期的延迟时间一般为", "o": {"A": "25～30秒", "B": "60～70秒", "C": "180～240秒", "D": "5分钟", "E": "10秒"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-025", "kp": "门静脉期延迟时间", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】门静脉期在注药后60～70秒扫描，此时门静脉及肝实质强化明显，有利于显示乏血供肝转移瘤等，故B正确。\n【为什么错】A：25～30秒为动脉期。C、D：180秒后为平衡期/延迟期。E：10秒对比剂尚在循环早期。", "tr": "门脉期是肝转移瘤（多为乏血供）显示的最佳时相。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1026", "t": "单选题", "s": "CT灌注成像中，反映每100g脑组织内血流量的参数是", "o": {"A": "CBF（脑血流量）", "B": "CBV（脑血容量）", "C": "MTT（平均通过时间）", "D": "TTP（达峰时间）", "E": "PS（毛细血管通透性）"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-026", "kp": "CBF含义", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】CBF即脑血流量，单位ml/(100g·min)，反映每100g脑组织单位时间内的血流量，故A正确。\n【为什么错】B：CBV是血容量，单位ml/100g。C：MTT是平均通过时间。D：TTP是达峰时间。E：PS反映毛细血管通透性。", "tr": "CBF带时间维度（/min），CBV不带；二者单位不同，注意区分。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1027", "t": "单选题", "s": "CT灌注成像中，脑血容量（CBV）的正常参考值约为", "o": {"A": "0.5～1ml/100g", "B": "2～6ml/100g", "C": "10～15ml/100g", "D": "50～100ml/100g", "E": "1～2ml/100g"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-027", "kp": "CBV参考值", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】正常脑灰质CBV约2～6ml/100g（灰质略高、白质略低），故B正确。\n【为什么错】A、E：1ml/100g左右明显偏低。C：10～15ml/100g偏高。D：50～100ml/100g接近CBF量级，混淆了单位。", "tr": "CBV单位ml/100g（约2～6），CBF单位ml/(100g·min)（灰质约50～80），勿混淆量级。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1028", "t": "单选题", "s": "CT灌注成像中，平均通过时间（MTT）延长最常见于", "o": {"A": "正常脑组织", "B": "缺血区血流灌注减低", "C": "血管畸形高流量区", "D": "脑脊液", "E": "骨组织"}, "d": "中", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-028", "kp": "MTT的临床意义", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】MTT是对比剂通过组织毛细血管床的平均时间，脑缺血区血流量减低、侧支循环缓慢，MTT明显延长，故B正确。\n【为什么错】A：正常脑组织MTT在正常范围。C：血管畸形动静脉短路时MTT可缩短。D、E：脑脊液和骨组织不参与灌注参数计算。", "tr": "缺血半暗带判断常依据MTT延长、CBF下降而CBV正常或轻度升高。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1029", "t": "单选题", "s": "CT灌注成像中，达峰时间（TTP）是指", "o": {"A": "对比剂首次到达的时间", "B": "感兴趣区内对比剂浓度达到峰值的时间", "C": "对比剂完全廓清的时间", "D": "扫描开始的时间", "E": "注射开始的时间"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-029", "kp": "TTP含义", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】TTP是时间—密度曲线上对比剂浓度达到峰值的时间，反映对比剂到达组织的速度，故B正确。\n【为什么错】A：首达时间是对比剂刚出现的时间。C：廓清时间不是达峰时间。D：扫描开始时间与TTP无关。E：注射开始是时间起点而非峰值时间。", "tr": "TTP延长提示侧支代偿差、灌注延迟；注意TTP与MTT的区别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1030", "t": "单选题", "s": "颅脑CT灌注成像扫描时，对比剂的注射流率一般为", "o": {"A": "0.5～1ml/s", "B": "2ml/s", "C": "4～6ml/s", "D": "8～10ml/s", "E": "1ml/s"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-030", "kp": "灌注扫描注射流率", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】颅脑CT灌注需保证对比剂团注快速，常用高压注射器以4～6ml/s注入，以保证时间—密度曲线质量，故C正确。\n【为什么错】A、E：0.5～1ml/s流率过低，无法形成良好团注。B：2ml/s偏低。D：8～10ml/s过高，易外渗且不必要。", "tr": "灌注注射流率快（4～6ml/s），总量常40～50ml；与常规增强（2～3ml/s）不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1031", "t": "单选题", "s": "缺血性脑卒中CT灌注中，半暗带的典型表现为", "o": {"A": "CBF、CBV均明显下降", "B": "CBF下降、CBV正常或升高，MTT延长", "C": "CBF、CBV均正常", "D": "CBV明显下降而CBF正常", "E": "MTT缩短"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-031", "kp": "半暗带灌注表现", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】缺血半暗带是存活但低灌注的组织，表现为CBF下降、CBV正常或轻度升高（血管代偿扩张）、MTT延长，是可挽救区域，故B正确。\n【为什么错】A：CBF、CBV均明显下降提示梗死核心而非半暗带。C：各参数正常为正常脑组织。D：CBV下降而CBF正常不符合缺血规律。E：MTT缩短见于高灌注或短路。", "tr": "梗死核心：CBF、CBV均↓；半暗带：CBF↓、CBV正常/↑、MTT延长。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1032", "t": "单选题", "s": "CT血管成像（CTA）最基本的成像原理是", "o": {"A": "利用血氧水平变化成像", "B": "静脉团注对比剂，在靶血管对比剂浓度峰值期扫描并经后处理重建血管", "C": "不用对比剂直接成像", "D": "口服对比剂显示血管", "E": "利用X线衰减差异成像，与增强无关"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-032", "kp": "CTA成像原理", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】CTA经外周静脉团注碘对比剂，利用团注追踪或小剂量测试确定扫描延迟，在靶血管内对比剂浓度达峰时扫描，再经MIP、VR等后处理显示血管，故B正确。\n【为什么错】A：血氧水平变化成像是MRI的BOLD技术。C：CTA必须用对比剂。D：口服对比剂不能进入血管。E：CTA依赖对比剂增强，不是单纯X线衰减。", "tr": "CTA三大要素：快速团注、精确延迟（团注追踪）、后处理重建。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1033", "t": "单选题", "s": "颅脑CTA扫描时，常用团注追踪或小剂量测试确定扫描延迟时间，头颅动脉期延迟一般为", "o": {"A": "10～15秒", "B": "15～25秒", "C": "40～50秒", "D": "60秒以上", "E": "5秒"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-033", "kp": "颅脑CTA延迟时间", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】颅脑CTA在对比剂经心脏→主动脉→颈动脉到达颅内动脉时扫描，常规延迟时间约15～25秒，故B正确。\n【为什么错】A：10～15秒偏早，对比剂尚未充分充盈颅内动脉。C：40～50秒已进入静脉期，动脉显示不佳。D：60秒以上为静脉期。E：5秒对比剂刚注入。", "tr": "CTA延迟时间可用团注追踪自动触发，无需固定；头颅动脉期约15～25s。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1034", "t": "单选题", "s": "冠状动脉CTA检查前，心率控制的目标一般为", "o": {"A": "≤70次/分（必要时使用β受体阻滞剂）", "B": "≥100次/分", "C": "80～90次/分", "D": "不需控制心率", "E": "≤50次/分以下才可检查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-034", "kp": "冠脉CTA心率控制", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠脉CTA要求心率尽量低且心律规整，一般心率≤70次/分（理想≤65），心率过快者可口服β受体阻滞剂，故A正确。\n【为什么错】B、C：心率过快冠脉运动伪影明显。D：心率过高会严重影响图像质量。E：≤50次/分不是必须，心率过慢也无需刻意追求。", "tr": "冠脉CTA质量与心率、心律密切相关；心律不齐时可配合心电编辑。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1035", "t": "单选题", "s": "冠脉CTA扫描通常采用", "o": {"A": "心电门控技术", "B": "非门控扫描", "C": "低剂量平扫", "D": "口服对比剂", "E": "CT透视"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-035", "kp": "冠脉CTA扫描方式", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠状动脉随心脏搏动运动，冠脉CTA必须采用心电门控技术，在心脏相对静止期采集数据，故A正确。\n【为什么错】B：非门控扫描无法消除心脏运动伪影。C：低剂量平扫不能显示冠脉腔。D：口服对比剂不能显示冠脉。E：CT透视用于穿刺导向，不是冠脉成像。", "tr": "心脏CTA必须心电门控，根据心率选择前瞻性或回顾性门控。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1036", "t": "单选题", "s": "双能量CT（能量成像）的基本原理是", "o": {"A": "利用两种不同能量（kVp）的X线进行采集，利用物质在不同能量下的衰减差异进行物质分离", "B": "利用不同管电流成像", "C": "利用两次平扫减影", "D": "利用不同螺距成像", "E": "利用不同矩阵成像"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-036", "kp": "双能量CT原理", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT通过高、低两种管电压（如80/140kVp）同时或瞬时切换采集，依据不同物质（如碘、钙、水）在两种能量下衰减系数的差异，实现物质分离与定量分析，故A正确。\n【为什么错】B：管电流变化只改变X线量。C：两次平扫减影是双能减影的早期形式，但现代双能基于能谱采集。D：螺距与能量无关。E：矩阵不影响能量信息。", "tr": "双能量成像的核心是物质分离，典型应用：虚拟平扫、碘图、去骨、结石成分分析。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1037", "t": "单选题", "s": "双能量CT的虚拟平扫（VNC）技术是指", "o": {"A": "不用对比剂的平扫", "B": "从增强扫描数据中去除碘成分信息，生成类似平扫的图像", "C": "低剂量平扫", "D": "用生理盐水代替对比剂扫描", "E": "只扫定位像"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-037", "kp": "虚拟平扫VNC", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】虚拟平扫利用双能量物质分离技术，将增强扫描数据中的碘对比剂信号去除，重建出类似真实平扫的图像，从而可免去实际平扫、减少辐射剂量，故B正确。\n【为什么错】A：虚拟平扫是从增强数据生成，不是真正的平扫。C：低剂量平扫仍需实际扫描。D：生理盐水不能产生增强效果。E：定位像只是定位图像。", "tr": "VNC的意义在于一次增强扫描可同时获得平扫样图像与增强图像，减少扫描次数与剂量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1038", "t": "单选题", "s": "双能量CT碘图（碘基图像）的主要用途是", "o": {"A": "显示骨骼", "B": "定量显示组织内碘对比剂分布，反映组织血供", "C": "显示脂肪含量", "D": "显示空气", "E": "显示钙化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-038", "kp": "碘图应用", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】碘图是双能量物质分离出碘成分的定量图像，可直观反映组织内碘对比剂分布与浓度，从而评估组织血供，故B正确。\n【为什么错】A：骨骼显示主要依靠常规骨窗或钙图。C：脂肪需脂肪基图像。D：空气不是碘图的观察对象。E：钙化由钙基图像显示。", "tr": "碘图定量评估血供，常用于肿瘤强化程度评估及疗效监测。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1039", "t": "单选题", "s": "双能量CT去骨技术主要应用于", "o": {"A": "CTA去除骨骼干扰，显示血管更清晰", "B": "提高CT值测量", "C": "降低管电流", "D": "增加层厚", "E": "消除运动伪影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-039", "kp": "去骨技术应用", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT利用钙与碘的衰减差异，可将CTA图像中的骨骼（钙）去除，使血管显示更加清晰，尤其适用于头颈、四肢CTA，故A正确。\n【为什么错】B：去骨不提高CT值测量精度。C：去骨与管电流无关。D：去骨与层厚无关。E：去骨不能消除运动伪影。", "tr": "去骨CTA常用于头颈部血管，避免骨遮挡对血管评估的影响。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1040", "t": "单选题", "s": "双能量CT最常用于鉴别下列哪种结石的成分", "o": {"A": "尿酸结石与含钙结石", "B": "胆囊胆固醇结石", "C": "胆色素结石", "D": "胰腺结石", "E": "胃结石"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-040", "kp": "能量CT结石分析", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT可通过物质分离区分尿酸结石与含钙结石（钙结石），对治疗方案选择（如药物溶石 vs 碎石）有重要价值，故A正确。\n【为什么错】B：胆固醇结石成分复杂，双能量鉴别价值有限。C：胆色素结石鉴别意义不大。D、E：非双能量CT的典型应用。", "tr": "双能量结石分析最经典应用是泌尿系结石：尿酸结石（可药物溶石）与含钙结石鉴别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1041", "t": "单选题", "s": "CT导向穿刺活检的定位方法通常是", "o": {"A": "根据体表解剖标志随意穿刺", "B": "扫描定位后确定病灶层面、体表进针点及进针角度与深度", "C": "注射对比剂后盲穿", "D": "超声引导", "E": "磁共振定位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-041", "kp": "CT导向穿刺定位", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】CT导向穿刺活检先扫描确定病灶所在层面，在体表放置栅栏定位器或网格，根据定位图确定进针点，再测算进针角度与深度，逐步进针并复查确认，故B正确。\n【为什么错】A：不能随意穿刺，须精确定位。C：增强用于显示病灶血供，但不能替代定位。D：超声用于CT不适用的部位。E：MRI引导是另一种方式，不是CT导向。", "tr": "CT导向穿刺核心：定位层面→体表定位→角度深度测算→CT复查确认针尖位置。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1042", "t": "单选题", "s": "CT导向肺穿刺活检最常见的并发症是", "o": {"A": "气胸", "B": "大出血", "C": "对比剂过敏", "D": "感染", "E": "空气栓塞"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-042", "kp": "肺穿刺活检并发症", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】CT导向经皮肺穿刺活检最常见的并发症是气胸，多因穿刺针经胸膜时损伤肺组织或胸膜所致，故A正确。\n【为什么错】B：大出血相对少见。C：肺穿刺不用或少量用对比剂，过敏不是主要并发症。D：感染罕见。E：空气栓塞极为罕见。", "tr": "肺穿刺术后应复查CT观察有无气胸；病灶距胸膜远者气胸风险增大。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1043", "t": "单选题", "s": "CT导向穿刺活检的禁忌证不包括", "o": {"A": "严重出血倾向", "B": "拟穿刺部位有动脉瘤", "C": "患者不能屏气配合", "D": "肺内孤立小结节", "E": "严重心肺功能不全"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-043", "kp": "穿刺活检禁忌证", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】肺内孤立小结节正是CT导向穿刺活检的适应证之一，不属于禁忌证，故D符合题意。\n【为什么错】A：严重出血倾向为绝对禁忌。B：穿刺路径上有动脉瘤为禁忌。C：不能配合屏气影响定位与安全，属相对禁忌。E：严重心肺功能不全不能耐受为禁忌。", "tr": "注意审题：本题问的是“不属于禁忌证”的选项，小结节是适应证。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1044", "t": "单选题", "s": "CT检查前，去除被检部位金属异物（如发夹、金属假牙）的主要目的是", "o": {"A": "防止损坏机器", "B": "避免金属伪影影响图像质量", "C": "加快扫描速度", "D": "降低辐射剂量", "E": "便于摆位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-044", "kp": "检查前去除金属", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】金属异物在CT扫描中会产生放射状伪影（射束硬化伪影），严重影响邻近组织显示，检查前去除金属异物是为了避免金属伪影，故B正确。\n【为什么错】A：金属异物一般不会损坏CT机。C：去除金属不加快扫描。D：去除金属与辐射剂量无关。E：摆位与金属去除无关。", "tr": "金属伪影为放射状低密度条纹，属于射束硬化伪影，检查前应去除一切金属物品。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1045", "t": "单选题", "s": "腹部CT检查前，患者的一般准备要求是", "o": {"A": "检查前禁食4～6小时，并口服适量对比剂充盈胃肠道", "B": "禁食24小时", "C": "大量饮水充盈膀胱", "D": "不需任何准备", "E": "检查前服用泻药排空所有肠道"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-045", "kp": "腹部CT检查前准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】腹部CT一般要求检查前禁食4～6小时，扫描前口服适量水或阳性对比剂充盈胃肠道，以区分肠管与邻近结构，故A正确。\n【为什么错】B：禁食24小时过长。C：充盈膀胱是盆腔检查的准备。D：腹部CT必须准备。E：并非所有腹部CT都需泻药清肠，一般肠道准备即可。", "tr": "腹部CT口服对比剂分阳性（碘水）与阴性（水），疑腹膜后或血管病变常用水作阴性对比剂。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1046", "t": "单选题", "s": "碘对比剂过敏反应的高危人群，检查前应重点询问的内容不包括", "o": {"A": "既往对比剂过敏史", "B": "哮喘病史", "C": "食物过敏史", "D": "年龄", "E": "严重心肾功能不全"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-046", "kp": "对比剂过敏高危因素", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】年龄不是对比剂过敏反应的高危因素，而既往对比剂过敏史、哮喘、多种药物/食物过敏史及严重心肾功能不全等才是需重点询问的内容，故D符合题意。\n【为什么错】A：既往对比剂过敏史是最高危因素。B：哮喘病史与过敏反应密切相关。C：食物及药物过敏史提示过敏体质。E：严重心肾功能不全是对比剂使用的重点评估项。", "tr": "对比剂过敏高危因素：过敏史、哮喘、药物过敏、心肾功能不全，老年本身不是禁忌但需评估。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1047", "t": "单选题", "s": "发生重度碘对比剂过敏反应时，首选的急救处理是", "o": {"A": "立即注射肾上腺素并停止检查、开放静脉、吸氧", "B": "继续扫描完成检查", "C": "口服抗组胺药即可", "D": "嘱患者自行休息", "E": "大量饮水"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-047", "kp": "对比剂过敏急救", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】重度碘对比剂过敏反应（过敏性休克）应立即停止注射对比剂，保持呼吸道通畅、吸氧、开放静脉，并肌注肾上腺素，故A正确。\n【为什么错】B：继续扫描会延误抢救。C：口服抗组胺药起效慢，不能用于重度反应。D：自行休息延误处理。E：大量饮水不能处理休克。", "tr": "重度过敏反应首选肾上腺素，而非糖皮质激素或抗组胺药，后者为辅助治疗。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1048", "t": "单选题", "s": "颅脑CT常规横断面扫描的基线是", "o": {"A": "听眦线（OML）", "B": "听眶下线（IOML）", "C": "眉间—枕外粗隆连线", "D": "矢状线", "E": "冠状线"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-048", "kp": "颅脑扫描基线", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑CT常规横断面扫描以听眦线（OML，即外耳道与外眦连线）为基线，扫描层面与基线平行，故A正确。\n【为什么错】B：听眶下线（IOML）多用于眼眶等检查。C：该连线是X线头颅侧位摄影的基准线，非CT扫描基线。D、E：矢状线、冠状线是定位方向，不是扫描基线。", "tr": "颅脑CT基线为OML（听眦线），基线向上平移或向下改变可减少或增加晶体受照。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1049", "t": "单选题", "s": "颅脑CT平扫的常规层厚一般为", "o": {"A": "1mm", "B": "2mm", "C": "5～10mm", "D": "15mm", "E": "0.5mm"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-049", "kp": "颅脑常规层厚", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑CT平扫常规层厚5～10mm（后颅窝可略薄），兼顾覆盖范围与显示质量，故C正确。\n【为什么错】A、B：1～2mm为薄层扫描，用于鞍区、内耳等。D：15mm层厚过厚。E：0.5mm用于HRCT精细结构。", "tr": "颅脑常规层厚5～10mm；后颅窝伪影较重时可缩小层厚。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1050", "t": "单选题", "s": "鞍区CT检查（疑垂体病变）一般采用的扫描方式是", "o": {"A": "常规10mm横断面", "B": "薄层（1～2mm）冠状位扫描并增强", "C": "矢状位厚层扫描", "D": "低剂量平扫", "E": "全身扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-050", "kp": "鞍区扫描方式", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】鞍区结构细小（垂体、漏斗），CT检查多采用薄层（1～2mm）冠状位扫描，并常行增强扫描以观察垂体病变，故B正确。\n【为什么错】A：常规10mm层厚无法显示垂体细节。C：矢状位厚层不利于鞍区显示。D：低剂量平扫显示细微结构能力差。E：全身扫描不适用于鞍区。", "tr": "垂体微腺瘤CT敏感性有限，MRI是首选，CT用于显示鞍区骨质及钙化。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1051", "t": "单选题", "s": "眼部CT横断面扫描常用基线是", "o": {"A": "听眦线（OML）", "B": "听眶下线（IOML）", "C": "垂直于眶轴的线", "D": "鼻根线", "E": "乳突线"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-051", "kp": "眼部扫描基线", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】眼部CT横断面扫描以听眶下线（IOML，即眶下缘与外耳道连线）为基线，可较好显示眼球、视神经等结构，故B正确。\n【为什么错】A：听眦线用于颅脑常规扫描。C：垂直于眶轴的线不是眼部CT的常用基线。D：鼻根线非标准术语。E：乳突线用于耳部扫描。", "tr": "眼用IOML、颅脑用OML、耳部用OML或乳突线，注意各部位基线不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1052", "t": "单选题", "s": "颞骨（耳部）CT检查最常用、能清晰显示内耳精细结构的扫描技术是", "o": {"A": "常规层厚软组织窗扫描", "B": "高分辨力CT（薄层＋骨算法）", "C": "低剂量平扫", "D": "增强扫描", "E": "CT灌注"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-052", "kp": "颞骨HRCT", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】内耳结构细微（耳蜗、前庭、半规管），颞骨CT采用HRCT（薄层扫描＋骨算法高空间频率重建）可清晰显示骨迷路，故B正确。\n【为什么错】A：常规层厚软组织窗不能显示内耳细节。C：低剂量无法保证精细结构显示。D：增强不能显示骨性结构。E：灌注不用于内耳。", "tr": "颞骨HRCT是内耳、中耳骨质病变的经典检查；层厚常0.5～1mm。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1053", "t": "单选题", "s": "鼻窦CT检查常用的扫描位置组合是", "o": {"A": "横断面＋冠状位", "B": "仅横断面", "C": "仅矢状位", "D": "横断面＋矢状位", "E": "仅冠状位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-053", "kp": "鼻窦CT扫描位置", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】鼻窦CT常采用横断面＋冠状位扫描，冠状位可更好显示窦口鼻道复合体及各窦口引流情况，故A正确。\n【为什么错】B、E：单一体位显示不全。C：矢状位不是鼻窦CT常规体位。D：横断面＋矢状位不如横断面＋冠状位常用。", "tr": "鼻窦冠状位扫描基线垂直于硬腭，可显示窦口与筛板。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1054", "t": "单选题", "s": "鼻窦CT冠状位扫描时，扫描基线与硬腭的关系是", "o": {"A": "平行", "B": "垂直", "C": "成45°角", "D": "成30°角", "E": "无要求"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-054", "kp": "鼻窦冠状位基线", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】鼻窦冠状位扫描基线应垂直于硬腭，以获得标准冠状断面，显示窦口鼻道复合体，故B正确。\n【为什么错】A：平行于硬腭的是横断面扫描。C、D：成角扫描不是标准冠状位。E：冠状位扫描对基线有明确要求。", "tr": "冠状位垂直硬腭、横断位平行硬腭，是鼻窦CT扫描的基本要求。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1055", "t": "单选题", "s": "口腔颌面部CT检查，为减少金属牙科修复体伪影，可采取的措施是", "o": {"A": "扫描前摘除可摘除的金属假牙", "B": "增加管电流", "C": "口服对比剂", "D": "改用MRI", "E": "增加层厚"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-055", "kp": "颌面部金属伪影处理", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (6)口腔颌面部", "ex": "【为什么对】金属牙科修复体（假牙、种植体）会产生放射状伪影，扫描前摘除可摘除的金属假牙是最直接的减伪影措施，故A正确。\n【为什么错】B：增加管电流不能消除金属伪影。C：口服对比剂不针对金属伪影。D：MRI虽对金属伪影表现不同，但并非所有患者适用且不能替代CT。E：增加层厚不能消除金属伪影。", "tr": "金属伪影是CT固有伪影，去除金属异物、金属伪影抑制重建算法可减轻。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1056", "t": "单选题", "s": "喉部CT检查时，为减少吞咽运动伪影，应嘱患者", "o": {"A": "平静呼吸，避免吞咽动作", "B": "持续咳嗽", "C": "大声发音", "D": "快速呼吸", "E": "屏气后快速喘气"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-056", "kp": "喉部CT扫描配合", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】喉部CT扫描时吞咽动作会引起喉结构位移和伪影，应嘱患者平静呼吸、避免吞咽，必要时可发持续音（如“咿”）使声带张开，故A正确。\n【为什么错】B：咳嗽会产生严重运动伪影。C：大声发音不是常规要求。D：快速呼吸使喉部移动。E：屏气后喘气动作幅度大。", "tr": "喉部检查的关键配合是“勿吞咽”，可发长音配合观察声带。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1057", "t": "单选题", "s": "颈部CT检查，为评估甲状腺结节性质，正确的做法是", "o": {"A": "行增强扫描观察结节强化情况", "B": "仅平扫即可", "C": "仅行CT灌注", "D": "口服对比剂显示甲状腺", "E": "用肺窗观察"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-057", "kp": "颈部增强扫描", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】颈部（甲状腺）检查常需增强扫描，通过观察结节的强化程度、强化方式及有无钙化、周围淋巴结等判断性质，故A正确。\n【为什么错】B：平扫对甲状腺结节定性价值有限。C：灌注不是甲状腺常规检查。D：口服对比剂不进入甲状腺。E：肺窗用于胸部肺组织。", "tr": "甲状腺CT增强可显示结节强化与颈部淋巴结；注意对比剂中含碘对甲状腺功能的影响。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1058", "t": "单选题", "s": "胸部CT扫描时，常规要求患者", "o": {"A": "深吸气后屏气扫描", "B": "呼气末屏气扫描", "C": "自由呼吸扫描", "D": "浅快呼吸扫描", "E": "咳嗽后扫描"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-058", "kp": "胸部CT呼吸配合", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】胸部CT常规在深吸气后屏气扫描，使肺组织充分膨胀、减少呼吸运动伪影，故A正确。\n【为什么错】B：呼气末屏气肺膨胀差，不利于肺实质观察。C：自由呼吸产生运动伪影。D：浅快呼吸肺显示不佳。E：咳嗽产生严重伪影。", "tr": "胸部及上腹部CT均要求深吸气后屏气，训练患者屏气是检查前准备的重要内容。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1059", "t": "单选题", "s": "先天性心脏病CT检查前，对婴幼儿常用的镇静方式是", "o": {"A": "口服水合氯醛", "B": "静脉全身麻醉一律应用", "C": "不予处理", "D": "肌注大量镇静剂", "E": "硬膜外麻醉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-059", "kp": "婴幼儿CT镇静", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (10)先天性心脏病", "ex": "【为什么对】婴幼儿不能配合屏气与制动，常口服水合氯醛等镇静后检查，以保证扫描质量与安全，故A正确。\n【为什么错】B：并非一律需要全身麻醉，根据情况选择。C：不处理无法完成检查。D：肌注镇静剂量需严格控制，口服更常用。E：硬膜外麻醉不用于此。", "tr": "儿童CT检查强调镇静与防护，按体重计算镇静剂量并监测生命体征。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1060", "t": "单选题", "s": "腹部CT增强扫描时，上腹部扫描一般要求患者", "o": {"A": "屏气扫描", "B": "自由呼吸", "C": "持续呼气", "D": "深呼吸不屏气", "E": "打哈欠"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-060", "kp": "腹部CT屏气", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】上腹部CT扫描必须屏气，以避免膈肌运动造成肝、脾、胰腺等器官位移和运动伪影，故A正确。\n【为什么错】B：自由呼吸产生运动伪影。C：持续呼气使腹腔脏器上移。D：深呼吸不屏气同样有运动伪影。E：打哈欠明显不配合。", "tr": "上腹部多期增强每期都需屏气，检查前应充分训练患者。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1061", "t": "单选题", "s": "盆腔CT检查前，为良好显示膀胱及盆腔器官，应", "o": {"A": "让患者充盈膀胱（憋尿）", "B": "排空膀胱", "C": "大量进食", "D": "无需任何准备", "E": "服用利尿剂排空"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-061", "kp": "盆腔CT膀胱充盈", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】盆腔CT检查前嘱患者充盈膀胱，可推开小肠、显示膀胱壁及周围结构，故A正确。\n【为什么错】B：排空膀胱不利于膀胱及周围结构显示。C：进食会形成肠道内容物干扰。D：盆腔检查有明确准备要求。E：利尿剂会使膀胱空虚。", "tr": "盆腔CT与腹部CT准备不同：盆腔要充盈膀胱，必要时用阴道纱布等标记。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1062", "t": "单选题", "s": "腰椎间盘CT检查，为准确显示椎间盘，扫描层面应", "o": {"A": "平行于椎间隙", "B": "垂直于椎间隙", "C": "与椎体长轴平行即可", "D": "随意定位", "E": "平行于床面"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-062", "kp": "椎间盘扫描定位", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】椎间盘CT扫描时，扫描层面应与椎间隙平行（通常在侧位定位像上逐层对准椎间隙），才能准确显示椎间盘与椎管关系，故A正确。\n【为什么错】B：垂直于椎间隙是矢状位的概念。C：平行于椎体长轴不能保证层面穿过椎间盘。D：随意定位会漏扫或倾斜。E：平行床面未必对准椎间隙。", "tr": "椎间盘扫描需在定位像上倾斜机架或重建使层面平行椎间隙，避免假性突出。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1063", "t": "单选题", "s": "四肢骨关节CT检查时，为便于对比观察，常采取的方式是", "o": {"A": "双侧同时扫描或双侧扫描对照", "B": "只扫患侧", "C": "只扫健侧", "D": "单侧增强扫描", "E": "只扫关节面一层"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-063", "kp": "四肢CT双侧对照", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】四肢骨关节结构对称，双侧同时扫描或双侧对照扫描可帮助判断细微异常与生理性变异，故A正确。\n【为什么错】B：只扫患侧无法对照。C：只扫健侧无诊断意义。D：增强不是四肢骨关节常规。E：单层扫描不能全面显示病变。", "tr": "四肢关节CT常双侧对照，用于微小骨折、发育异常的判断。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1064", "t": "多选题", "s": "关于CT窗宽窗位的叙述，正确的有", "o": {"A": "窗宽决定显示CT值的范围", "B": "窗位是窗的中心值", "C": "窗宽增大时图像对比度降低", "D": "窗位升高时图像整体变亮", "E": "窗宽窗位只影响显示，不影响原始数据"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-064", "kp": "窗宽窗位综合", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】窗宽决定CT值显示范围，窗位是窗的中心值，窗宽增大对比度降低；窗宽窗位只改变显示效果，不改变原始数据，故ABCE正确。\n【为什么错】D：窗位升高时显示范围向高CT值方向移动，图像整体变暗而非变亮。", "tr": "窗位升高变暗、窗位降低变亮；窗宽增大变灰（对比度降低）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1065", "t": "多选题", "s": "影响CT空间分辨力的因素包括", "o": {"A": "像素大小", "B": "焦点尺寸", "C": "探测器孔径", "D": "窗宽设置", "E": "重建算法"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-065", "kp": "空间分辨力影响因素", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】空间分辨力受像素大小、焦点尺寸、探测器孔径、重建算法（高空间频率算法）等影响，故ABCE正确。\n【为什么错】D：窗宽窗位只影响图像显示，不影响空间分辨力。", "tr": "空间分辨力是硬件与算法决定的固有属性，窗技术不能改变。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1066", "t": "多选题", "s": "关于螺距的叙述，正确的有", "o": {"A": "螺距增大，扫描速度加快", "B": "螺距增大，可减少层间重叠", "C": "螺距过大图像质量下降", "D": "螺距与准直器宽度无关", "E": "螺距等于床移动距离除以准直器宽度"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-066", "kp": "螺距综合", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (1)基本概念", "ex": "【为什么对】螺距＝床移距离÷准直宽度；螺距增大则单位时间覆盖范围增大、扫描加快、层间重叠减少，但过大时采样稀疏、图像质量下降，故ABCE正确。\n【为什么错】D：螺距定义中分母正是准直器宽度，二者密切相关。", "tr": "大螺距换速度、小螺距保质量，两者需权衡。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1067", "t": "多选题", "s": "CT图像的伪影类型包括", "o": {"A": "运动伪影", "B": "金属伪影", "C": "射束硬化伪影", "D": "部分容积效应", "E": "增大窗宽可消除图像伪影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-067", "kp": "CT伪影分类", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (2)专业术语", "ex": "【为什么对】CT伪影类型包括运动伪影、金属伪影、射束硬化伪影及部分容积效应等，故ABCD正确。\n【为什么错】E：窗宽窗位只改变图像显示效果，不能消除伪影，伪影须通过去除金属、减少运动、修正算法等处理。", "tr": "注意区分：伪影是图像失真；运动伪影与金属伪影最常考，窗技术不能消除伪影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1068", "t": "多选题", "s": "心电门控扫描中，回顾性心电门控的特点包括", "o": {"A": "辐射剂量相对较高", "B": "可在任意心动时相重建图像", "C": "适用于心律不齐患者（可配合心电编辑）", "D": "辐射剂量低于前瞻性门控", "E": "采集连续数据并同步记录心电信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-068", "kp": "回顾性心电门控特点", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】回顾性心电门控连续采集并记录心电信号，可任意时相重建，但因全程扫描剂量较高；心律不齐时可通过心电编辑校正，故ABCE正确。\n【为什么错】D：回顾性门控剂量高于前瞻性门控，表述相反。", "tr": "前瞻性门控剂量低、时相选择受限；回顾性门控剂量高、时相灵活。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1069", "t": "多选题", "s": "下列属于CT特殊扫描技术的有", "o": {"A": "高分辨力扫描（HRCT）", "B": "薄层扫描", "C": "低剂量扫描", "D": "靶扫描（放大扫描）", "E": "增强扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-069", "kp": "特殊扫描技术", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】HRCT、薄层扫描、低剂量扫描、靶扫描均属特殊扫描技术，故ABCD正确。\n【为什么错】E：增强扫描是独立的检查方法分类，不属于特殊扫描技术。", "tr": "特殊扫描技术包括：薄层、HRCT、低剂量、靶扫描、动态扫描、灌注等，增强是另一分类。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1070", "t": "多选题", "s": "HRCT的临床应用包括", "o": {"A": "弥漫性肺疾病（肺间质病）", "B": "颞骨内耳精细结构", "C": "肺小结节分析", "D": "肝脏占位定性", "E": "颅底骨结构"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-070", "kp": "HRCT临床应用", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】HRCT以高空间分辨力见长，适用于弥漫性肺病、内耳、肺小结节、颅底骨结构等精细结构显示，故ABCE正确。\n【为什么错】D：肝脏占位定性主要依靠增强多期扫描，HRCT不是首选。", "tr": "HRCT优势在空间分辨力，用于精细结构；软组织病灶定性用增强扫描。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1071", "t": "多选题", "s": "低剂量CT扫描时，为保持图像质量可采用的技术包括", "o": {"A": "降低管电流", "B": "降低管电压", "C": "迭代重建算法", "D": "增大螺距", "E": "增加扫描次数"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-071", "kp": "低剂量技术", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】低剂量CT通过降低管电流/管电压减少辐射，并用迭代重建算法抑制噪声以保证图像质量，故ABC正确。\n【为什么错】D：增大螺距虽可降低剂量但会降低图像质量，且不是保证质量的措施。E：增加扫描次数会增加剂量，与低剂量目标相反。", "tr": "低剂量CT的关键是“降剂量+迭代重建保质量”；儿童检查尤其重视。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1072", "t": "多选题", "s": "CT灌注成像的主要参数包括", "o": {"A": "脑血流量（CBF）", "B": "脑血容量（CBV）", "C": "平均通过时间（MTT）", "D": "达峰时间（TTP）", "E": "骨密度（BMD）"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-072", "kp": "灌注参数", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】CT灌注参数包括CBF、CBV、MTT、TTP等，故ABCD正确。\n【为什么错】E：BMD为骨密度参数，不属于CT灌注参数；灌注参数中通透性PS主要用于肿瘤灌注评估。", "tr": "脑缺血评估常用CBF/CBV/MTT；PS主要用于肿瘤灌注与血脑屏障评估。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1073", "t": "多选题", "s": "CT灌注成像的临床应用包括", "o": {"A": "急性脑梗死缺血半暗带评估", "B": "脑肿瘤血供评估", "C": "肝肿瘤灌注", "D": "冠脉粥样硬化斑块显示", "E": "肺栓塞诊断"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-073", "kp": "灌注临床应用", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】CT灌注主要用于急性脑梗死半暗带评估、脑及腹部肿瘤血供评估等，故ABC正确。\n【为什么错】D：冠脉斑块显示依靠冠脉CTA，不是灌注。E：肺栓塞诊断主要依靠CTA。", "tr": "灌注看“血供功能”，CTA看“解剖形态”，用途不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1074", "t": "多选题", "s": "CT血管成像（CTA）的后处理显示技术包括", "o": {"A": "最大密度投影（MIP）", "B": "容积再现（VR）", "C": "曲面重建（CPR）", "D": "多平面重建（MPR）", "E": "增强扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-074", "kp": "CTA后处理技术", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】CTA常用后处理包括MIP、VR、CPR及MPR等，故ABCD正确。\n【为什么错】E：增强扫描是图像采集方法，不属于CTA原始数据的后处理显示技术。", "tr": "CPR尤其适用于迂曲血管（如冠状动脉）；VR立体感强但受阈值影响。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1075", "t": "多选题", "s": "冠状动脉CTA检查前及检查中的要点包括", "o": {"A": "控制心率在70次/分以下", "B": "必要时口服β受体阻滞剂", "C": "扫描前训练患者屏气", "D": "采用心电门控扫描", "E": "无需控制心律，扫描后心电编辑可完全替代"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-075", "kp": "冠脉CTA要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠脉CTA需控制心率、必要时用β受体阻滞剂，训练屏气、心电门控扫描，故ABCD正确。\n【为什么错】E：心电编辑是对心律不齐数据的事后校正，不能完全替代检查前的心率与心律控制。", "tr": "冠脉CTA成败关键在于心率、心律与屏气配合，心电编辑是补救手段。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1076", "t": "多选题", "s": "双能量CT的临床应用包括", "o": {"A": "虚拟平扫（VNC）", "B": "碘图定量分析", "C": "去骨CTA", "D": "结石成分分析", "E": "增大窗宽提高分辨力"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-076", "kp": "双能量CT临床应用", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT临床应用包括虚拟平扫、碘图、去骨CTA及结石成分分析等，故ABCD正确。\n【为什么错】E：增大窗宽只改变显示效果，不提高分辨力，不属于双能量CT的临床应用。", "tr": "双能量CT“物质分离”是其技术核心，衍生出VNC、碘图、去骨、成分分析等应用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1077", "t": "多选题", "s": "CT导向穿刺活检前，操作者应重点关注的准备包括", "o": {"A": "复习影像资料确定穿刺靶点", "B": "了解患者凝血功能", "C": "停止抗凝药物评估出血风险", "D": "向患者解释并取得配合", "E": "穿刺前无需评估患者呼吸配合能力"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-077", "kp": "穿刺活检前准备", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】CT导向穿刺前需确定靶点、评估凝血功能与出血风险、取得患者配合，故ABCD正确。\n【为什么错】E：肺穿刺需要患者配合屏气以固定病灶位置，评估呼吸配合能力是必要的准备内容。", "tr": "凝血功能异常是穿刺禁忌，术前必须评估；呼吸配合影响穿刺安全。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1078", "t": "多选题", "s": "CT导向穿刺活检的注意事项包括", "o": {"A": "选择最短且安全的进针路径", "B": "避开血管、神经及重要脏器", "C": "穿肺组织时嘱患者屏气", "D": "术后留观观察有无气胸", "E": "穿多针取材越多越好"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-078", "kp": "穿刺活检注意事项", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】穿刺应选择最短安全路径、避开血管神经脏器，穿肺时屏气，术后观察气胸，故ABCD正确。\n【为什么错】E：盲目多针取材增加出血、气胸等并发症风险，应根据需要适度取材。", "tr": "穿刺安全第一，路径规划比取材数量更重要。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1079", "t": "多选题", "s": "CT检查前患者的常规准备包括", "o": {"A": "去除检查部位金属异物", "B": "按需禁食", "C": "进行屏气训练", "D": "询问对比剂过敏史（增强检查）", "E": "嘱患者多喝水可替代禁食"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-079", "kp": "患者检查前准备", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】患者准备包括去除金属异物、按需禁食、屏气训练、增强前询问过敏史等，故ABCD正确。\n【为什么错】E：多喝水不能替代禁食要求，腹部检查仍需禁食。", "tr": "增强扫描前必须询问碘过敏史并签署知情同意。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1080", "t": "多选题", "s": "CT检查前设备与操作者的准备包括", "o": {"A": "检查设备球管、探测器工作状态", "B": "预热球管", "C": "确认高压注射器状态（增强检查）", "D": "校准空气值（水模校准）", "E": "无需核对患者信息即可扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-080", "kp": "设备与操作者准备", "ch": "九、CT检查技术 → 3.检查前准备 → (1)设备", "ex": "【为什么对】操作者需检查设备状态、预热球管、确认注射器、进行校准等，故ABCD正确。\n【为什么错】E：扫描前必须核对患者信息与检查部位，防止错扫漏扫，核对不可省略。", "tr": "每日开机后的空气校准是保证CT值准确的基础；核对患者信息是流程底线。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1081", "t": "多选题", "s": "碘对比剂使用中的注意事项包括", "o": {"A": "询问过敏史", "B": "控制注射流率，防止外渗", "C": "密切观察患者反应", "D": "备好急救药品与设备", "E": "所有患者均可放心使用高渗对比剂"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-081", "kp": "对比剂使用注意", "ch": "九、CT检查技术 → 3.检查前准备 → (3)对比剂及急救物品", "ex": "【为什么对】使用碘对比剂须询问过敏史、控制流率防外渗、观察反应并备急救物品，故ABCD正确。\n【为什么错】E：高渗对比剂不良反应发生率较高，高风险患者应选用等渗或低渗对比剂。", "tr": "高危患者（过敏史、心肾功能不全）应慎用对比剂并优先选择非离子型等渗/低渗制剂。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1082", "t": "多选题", "s": "颅脑CT检查的适应证包括", "o": {"A": "颅内出血", "B": "颅脑外伤", "C": "脑梗死急性期", "D": "颅骨骨折", "E": "甲状腺功能亢进"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-082", "kp": "颅脑CT适应证", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑CT是颅内出血、外伤、急性梗死、骨折等的首选或重要检查手段，故ABCD正确。\n【为什么错】E：甲状腺功能亢进属于碘对比剂使用的相对禁忌，不是颅脑CT的适应证。", "tr": "急性脑出血CT呈高密度，急性梗死早期可能阴性，需结合灌注。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1083", "t": "多选题", "s": "关于眼部CT检查的叙述，正确的有", "o": {"A": "常采用薄层扫描", "B": "横断面基线为听眶下线（IOML）", "C": "检查眼内异物时首选CT", "D": "可用冠状位补充观察", "E": "金属异物患者应行MRI检查"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-083", "kp": "眼部CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】眼部CT采用薄层扫描、横断面基线为IOML，常加冠状位；眼内金属异物应首选CT而非MRI，故ABCD正确。\n【为什么错】E：眼内金属异物是MRI的禁忌证（磁致移动损伤眼球），应选CT。", "tr": "金属异物禁做MRI，CT是眼内异物定位的首选。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1084", "t": "多选题", "s": "颞骨（耳部）HRCT的扫描要点包括", "o": {"A": "薄层扫描（0.5～1mm）", "B": "骨算法（高空间频率）重建", "C": "大窗宽骨窗显示", "D": "横断面加冠状位扫描", "E": "软组织算法重建"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-084", "kp": "颞骨HRCT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】颞骨HRCT采用薄层、骨算法重建、大窗宽骨窗显示，常横断面加冠状位扫描，故ABCD正确。\n【为什么错】E：软组织算法降低空间分辨力，不利于内耳骨迷路显示，颞骨HRCT应使用骨算法。", "tr": "耳部骨窗窗宽常1000～3000HU，窗位300～500HU，以显示骨性结构。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1085", "t": "多选题", "s": "鼻窦CT检查的技术要点包括", "o": {"A": "横断面加冠状位扫描", "B": "冠状位扫描基线垂直于硬腭", "C": "扫描前去除金属假牙", "D": "显示窦口鼻道复合体", "E": "必须增强扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-085", "kp": "鼻窦CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】鼻窦CT常规横断面加冠状位，冠状位垂直硬腭，扫描前去除金属假牙，重点显示窦口鼻道复合体，故ABCD正确。\n【为什么错】E：鼻窦CT平扫即可满足多数诊断，增强非必须。", "tr": "窦口鼻道复合体是鼻窦炎CT评估的重点区域。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1086", "t": "多选题", "s": "胸部CT扫描的技术要点包括", "o": {"A": "深吸气后屏气扫描", "B": "常规层厚5～10mm", "C": "可疑微小病变加用HRCT", "D": "肺窗加纵隔窗观察", "E": "扫描时快速呼吸减少伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-086", "kp": "胸部CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (9)胸部", "ex": "【为什么对】胸部CT须深吸气后屏气，常规层厚5～10mm，必要时HRCT，肺窗加纵隔窗观察，故ABCD正确。\n【为什么错】E：快速呼吸会加重呼吸运动伪影，胸部CT应屏气扫描。", "tr": "肺窗与纵隔窗需同时观察，肺窗显示肺纹理、纵隔窗显示血管与淋巴结。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1087", "t": "多选题", "s": "心脏冠脉CTA检查的禁忌证或相对禁忌证包括", "o": {"A": "碘对比剂严重过敏", "B": "严重心功能不全", "C": "未控制的心律失常", "D": "肾功能严重不全", "E": "轻度窦性心动过速经药物控制"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-087", "kp": "冠脉CTA禁忌证", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】碘过敏、严重心肾功能不全、未控制的心律失常是冠脉CTA禁忌证或相对禁忌证，故ABCD正确。\n【为什么错】E：轻度窦速经β受体阻滞剂控制后可完成检查，不是禁忌。", "tr": "冠脉CTA以心率70次/分为界，控制不佳者改期或改行其他检查。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1088", "t": "多选题", "s": "腹部CT增强多期扫描时，肝脏常见的期相包括", "o": {"A": "动脉期", "B": "门静脉期", "C": "平衡期（延迟期）", "D": "排泄期", "E": "骨密度期"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-088", "kp": "肝脏增强期相", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肝脏增强常规包括动脉期（25～30s）、门静脉期（60～70s）和平衡期/延迟期（120～180s），故ABC正确。\n【为什么错】D：排泄期是肾脏及泌尿系的期相，不用于肝脏常规增强。E：骨密度期不是增强期相。", "tr": "肝脏三期：动脉期、门脉期、平衡期；肾脏分皮髓质期、实质期、排泄期。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1089", "t": "多选题", "s": "胰腺CT检查的技术要点包括", "o": {"A": "薄层扫描", "B": "增强多期扫描（动脉期、实质期、门脉期）", "C": "口服水或对比剂充盈胃和十二指肠", "D": "屏气扫描", "E": "只做平扫即可定性"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-089", "kp": "胰腺CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】胰腺CT需薄层、增强多期（动脉期、实质期、门脉期）、口服水充盈胃肠、屏气扫描，故ABCD正确。\n【为什么错】E：胰腺肿瘤定性高度依赖增强扫描，平扫不足以定性。", "tr": "胰腺增强动脉期约25～30s显示胰腺实质与血管关系最佳。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1090", "t": "多选题", "s": "肾脏CT检查的期相包括", "o": {"A": "皮髓质期（皮质期）", "B": "实质期", "C": "排泄期（肾盂期）", "D": "动脉期", "E": "骨窗期"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-090", "kp": "肾脏增强期相", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肾脏增强扫描包括皮髓质期（皮质期）、实质期和排泄期，其中排泄期显示肾盂输尿管；也涉及动脉期评估肾动脉，故ABCD正确。\n【为什么错】E：骨窗期不是肾脏增强期相。", "tr": "肾脏排泄期（约3～5分钟）可显示泌尿系全程，是泌尿系CTU的基础。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1091", "t": "多选题", "s": "盆腔CT检查前的准备包括", "o": {"A": "充盈膀胱", "B": "口服对比剂或水充盈肠道", "C": "必要时阴道填塞标记物", "D": "排空膀胱", "E": "去除金属节育环等异物"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-091", "kp": "盆腔CT准备", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】盆腔CT需充盈膀胱、口服对比剂充盈肠道，女性必要时阴道填塞标记，并去除金属节育环等异物，故ABCE正确。\n【为什么错】D：排空膀胱不利于膀胱及盆腔器官显示，应为充盈膀胱。", "tr": "盆腔检查“憋尿”与腹部“禁食”一样是经典考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1092", "t": "多选题", "s": "脊柱CT检查的技术要点包括", "o": {"A": "椎间盘扫描层面平行于椎间隙", "B": "椎间盘扫描采用薄层", "C": "椎体骨折观察用骨窗", "D": "可进行矢状位重建", "E": "椎体扫描常规采用厚层20mm"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-092", "kp": "脊柱CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】椎间盘扫描层面平行椎间隙并薄层，椎体用骨窗观察，可矢状位重建，故ABCD正确。\n【为什么错】E：椎体常规扫描层厚一般3～5mm，20mm过厚。", "tr": "椎间盘1～2mm薄层扫描，椎体3～5mm常规层厚。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1093", "t": "多选题", "s": "四肢骨关节CT检查的技术要点包括", "o": {"A": "双侧对照扫描", "B": "薄层扫描", "C": "骨窗加软组织窗观察", "D": "必要时三维重建（MPR、VR）", "E": "一律行增强扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-093", "kp": "四肢CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】四肢CT双侧对照、薄层扫描、骨窗加软组织窗，必要时三维重建，故ABCD正确。\n【为什么错】E：四肢骨关节平扫即可满足多数诊断，增强并非一律需要。", "tr": "关节骨折三维重建（VR）可直观显示骨折移位情况，辅助手术规划。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1094", "t": "多选题", "s": "关于CT灌注成像的叙述，正确的有", "o": {"A": "需快速团注对比剂", "B": "扫描方式为同层动态扫描", "C": "可定量计算CBF、CBV", "D": "半暗带表现为CBF下降、CBV正常或升高", "E": "灌注检查对运动不敏感，患者无需制动"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-094", "kp": "CT灌注综合", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】CT灌注需快速团注、同层动态扫描，可定量CBF/CBV等参数，半暗带CBF下降而CBV正常或升高，故ABCD正确。\n【为什么错】E：灌注对运动十分敏感，患者须保持静止，头颈部还要固定。", "tr": "灌注扫描对运动伪影极其敏感，患者制动与配合至关重要。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1095", "t": "多选题", "s": "CT血管成像（CTA）检查前的准备包括", "o": {"A": "询问碘过敏史", "B": "建立良好的静脉通道", "C": "选择合适的高压注射参数", "D": "训练患者屏气", "E": "患者常规服用β受体阻滞剂"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-095", "kp": "CTA检查前准备", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】CTA检查前需询问过敏史、建立静脉通道、设置高压注射参数并训练屏气，故ABCD正确。\n【为什么错】E：β受体阻滞剂仅在冠脉CTA心率过快时使用，并非所有CTA常规服用。", "tr": "CTA成败与注射流率、延迟时间密切相关，静脉通道质量直接影响团注效果。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1096", "t": "多选题", "s": "关于CT导向穿刺活检的叙述，正确的有", "o": {"A": "适用于肺内孤立结节定性", "B": "可用于纵隔、骨骼等部位取材", "C": "气胸是肺穿刺最常见并发症", "D": "严重出血倾向为禁忌证", "E": "穿刺过程无需CT复查确认针尖位置"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-096", "kp": "穿刺活检综合", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】CT导向穿刺适用于肺结节及纵隔、骨骼等取材，气胸是最常见并发症，严重出血倾向为禁忌；进针过程中需CT复查确认针尖位置，故ABCD正确。\n【为什么错】E：必须通过CT复查确认针尖位置后再取材，以确保安全准确。", "tr": "穿刺的“安全第一”：每一步进针后都需CT复查确认位置。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1097", "t": "多选题", "s": "关于鞍区CT检查的叙述，正确的有", "o": {"A": "常采用薄层扫描", "B": "常规行冠状位扫描", "C": "可结合增强扫描", "D": "用于显示鞍区骨质改变与钙化", "E": "垂体微腺瘤诊断首选CT平扫"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-097", "kp": "鞍区CT综合", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】鞍区CT薄层、冠状位扫描并常增强，用于显示鞍区骨质、钙化，故ABCD正确。\n【为什么错】E：垂体微腺瘤的首选检查是MRI（高软组织分辨力），CT平扫对微腺瘤不敏感。", "tr": "垂体病变首选MRI，CT主要补充显示骨质破坏与钙化。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1098", "t": "多选题", "s": "关于喉部及颈部CT检查的叙述，正确的有", "o": {"A": "喉部扫描应避免吞咽动作", "B": "颈部检查常需增强扫描", "C": "扫描范围应覆盖病灶及引流区域", "D": "嘱患者平静呼吸", "E": "颈部扫描一律采用厚层10mm"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-098", "kp": "喉颈部CT要点", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】喉部扫描避免吞咽、平静呼吸，颈部常增强并覆盖病灶及引流区域，故ABCD正确。\n【为什么错】E：颈部结构精细，常用薄层（2～5mm）扫描，厚层10mm不利于精细观察。", "tr": "颈部CT薄层扫描并增强，观察淋巴结时需覆盖颈部全程。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U09-1099a", "t": "单选题", "s": "【病例】患者男，45岁，车祸致头部外伤后意识模糊1小时急诊就诊，查体见左颞部头皮血肿，双侧瞳孔等大等圆，对光反射存在。急诊医生疑颅内出血，申请颅脑CT检查。 该患者首选的CT检查方法是", "o": {"A": "颅脑平扫", "B": "颅脑增强扫描", "C": "CT灌注成像", "D": "颅脑CTA", "E": "双能量去骨扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-099", "kp": "颅脑外伤检查方法选择", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑外伤首选颅脑CT平扫，可快速显示急性硬膜外/下血肿、脑挫裂伤及颅骨骨折，无需注射对比剂，故A正确。\n【为什么错】B：增强扫描用于肿瘤、炎症等，外伤急性期无必要。C：灌注用于缺血评估。D：CTA用于血管病变。E：双能量去骨用于CTA去骨，非外伤常规。", "tr": "急性出血平扫呈高密度，是神经外科急诊处理的关键，检查越快越好。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1099b", "t": "单选题", "s": "该患者颅脑CT平扫的扫描基线是", "o": {"A": "听眶下线（IOML）", "B": "听眦线（OML）", "C": "眉间线", "D": "矢状线", "E": "冠状线"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-100", "kp": "颅脑扫描基线", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】颅脑CT横断面扫描以听眦线（OML，外耳道与外眦连线）为基线，层面与基线平行，故B正确。\n【为什么错】A：IOML（听眶下线）用于眼部等扫描。C：眉间线非标准基线。D、E：矢状线、冠状线为定位方向，非颅脑横断面扫描基线。", "tr": "颅脑CT用OML、眼部用IOML，两个基线不要混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1099c", "t": "单选题", "s": "平扫发现左侧急性硬膜外血肿，呈梭形高密度影，此时影像上血肿的密度特征为", "o": {"A": "低密度", "B": "等密度", "C": "高密度", "D": "混合密度", "E": "脂肪密度"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-101", "kp": "急性血肿CT密度", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】急性期（数小时内）血液凝固、血红蛋白含量高，CT平扫呈高密度，故C正确。\n【为什么错】A：低密度见于慢性血肿吸收期或脑水肿。B：等密度见于亚急性期血肿溶解期。D：混合密度可见于活动性出血。E：脂肪密度见于脂肪瘤等，与血肿无关。", "tr": "硬膜外血肿梭形、不跨颅缝；硬膜下血肿新月形、跨颅缝，是经典鉴别点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1100a", "t": "单选题", "s": "【病例】患者男，62岁，吸烟30年，每年约1包，社区组织肺癌高危人群低剂量CT筛查。患者无咳嗽、咯血等症状，要求进行胸部CT检查。 该患者作为肺癌高危人群，胸部CT筛查宜采用", "o": {"A": "常规剂量增强扫描", "B": "低剂量CT平扫", "C": "CT灌注成像", "D": "常规剂量多层平扫", "E": "冠脉CTA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-102", "kp": "肺癌低剂量筛查", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】肺癌高危人群筛查推荐低剂量CT（LDCT），在保证肺结节检出的同时大幅降低辐射剂量，故B正确。\n【为什么错】A：筛查用平扫即可，增强非必需。C：灌注用于定性评估，不用于筛查。D：常规剂量平扫剂量较高，不符合筛查理念。E：冠脉CTA针对冠脉病变。", "tr": "LDCT筛查的关键是低剂量+肺结节检出，常规采用低管电流（如40～50mAs）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1100b", "t": "单选题", "s": "低剂量CT筛查发现右上肺一枚约6mm磨玻璃结节，为观察其内部细微结构，应加做的检查是", "o": {"A": "厚层扫描", "B": "高分辨力CT（HRCT）薄层扫描", "C": "CT灌注", "D": "增强扫描", "E": "双能量去骨"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-103", "kp": "肺结节HRCT", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】肺内磨玻璃小结节需HRCT（1～2mm薄层＋高空间频率算法）观察边界、内部密度及有无空泡征等细微结构，故B正确。\n【为什么错】A：厚层扫描有部分容积效应，无法显示细微结构。C：灌注用于血供评估。D：小于1cm的磨玻璃结节增强价值有限。E：去骨用于CTA。", "tr": "肺磨玻璃结节评估强调HRCT薄层扫描，避免漏诊浸润成分。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1101a", "t": "单选题", "s": "【病例】患者男，58岁，反复胸闷心前区不适2周，心电图示窦性心律、偶发房性早搏，心率86次/分。临床疑冠心病，拟行冠状动脉CTA检查。 该患者进行冠脉CTA前，心率控制的目标是", "o": {"A": "控制在70次/分以下", "B": "控制在100次/分以下", "C": "心率越低越好，控制在40次/分", "D": "无需控制心率", "E": "控制在80～90次/分即可"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-104", "kp": "冠脉CTA心率控制", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠脉CTA要求心率≤70次/分（理想≤65次/分），可通过口服β受体阻滞剂控制，故A正确。\n【为什么错】B：100次/分以下仍偏快，运动伪影明显。C：心率并非越低越好，40次/分也影响心脏生理。D：不控制心率图像质量无法保证。E：80～90次/分仍偏快。", "tr": "心率过快时冠脉运动伪影明显，通常以70次/分为界。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1101b", "t": "单选题", "s": "该患者检查中出现偶发房性早搏，采集数据后可采取的图像校正措施是", "o": {"A": "心电编辑", "B": "增大窗宽", "C": "改变窗位", "D": "缩小视野", "E": "改用软组织算法重建"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-105", "kp": "心电编辑应用", "ch": "九、CT检查技术 → 1.CT检查基本知识 → (3)心电编辑与心律", "ex": "【为什么对】心律不齐（如房早）导致部分心动周期扫描数据错位，可通过心电编辑将异常周期的数据用相邻正常周期的数据替代，消除图像错位伪影，故A正确。\n【为什么错】B：窗宽改变显示对比度，不解决错位。C：窗位调整灰度，不解决错位。D：视野改变像素大小。E：算法改变空间分辨力，不解决心电错位。", "tr": "心电编辑适用于回顾性心电门控扫描数据，是冠脉CTA心律不齐的重要补救手段。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1102a", "t": "单选题", "s": "【病例】患者男，55岁，乙肝病史10余年，近期乏力、消瘦，超声发现肝右叶低回声占位，甲胎蛋白明显升高。临床疑肝细胞癌，拟行肝脏三期增强CT检查。 肝脏增强扫描动脉期的延迟时间一般为", "o": {"A": "25～30秒", "B": "60～70秒", "C": "120～180秒", "D": "3～5分钟", "E": "15秒内"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-106", "kp": "肝脏动脉期时间", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肝脏增强动脉期一般在注药后25～30秒扫描，此时肝动脉强化明显，富血供肝癌显示最佳，故A正确。\n【为什么错】B：60～70秒为门静脉期。C：120～180秒为平衡期。D：3～5分钟为延迟期。E：15秒内对比剂尚未到达肝动脉。", "tr": "肝癌“快进快出”：动脉期高强化、门脉期/延迟期廓清，是典型表现。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "CT检查基本知识", "页": 214}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1102b", "t": "单选题", "s": "该患者增强扫描前，口服对比剂的作用是", "o": {"A": "充盈胃肠道，区分肠管与腹腔脏器", "B": "增强肝实质", "C": "减少辐射剂量", "D": "提高空间分辨力", "E": "代替静脉对比剂"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-107", "kp": "口服对比剂作用", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】腹部CT口服阳性（碘水）或阴性（水）对比剂充盈胃肠道，使肠管与腹腔脏器、病灶区分，避免肠管误诊为病变，故A正确。\n【为什么错】B：口服对比剂不进入肝实质血供。C：口服对比剂与辐射剂量无关。D：不影响空间分辨力。E：不能代替静脉对比剂增强。", "tr": "口服对比剂分阳性（高密度）与阴性（水、低密度），疑腹膜后及血管病变常用阴性对比剂。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1102c", "t": "单选题", "s": "该患者上腹部扫描时，为避免呼吸运动伪影，应", "o": {"A": "深吸气后屏气扫描", "B": "自由呼吸扫描", "C": "呼气末屏气扫描", "D": "咳嗽后扫描", "E": "浅快呼吸扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-108", "kp": "上腹部屏气", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】上腹部扫描需深吸气后屏气，使膈肌下移、肝脏位置固定，减少呼吸运动伪影，故A正确。\n【为什么错】B：自由呼吸产生运动伪影。C：呼气末屏气肺膨胀差、膈肌上移，不利于肝脏观察。D：咳嗽产生严重伪影。E：浅快呼吸无法固定脏器。", "tr": "屏气训练是腹部多期增强的前提，扫描前应反复练习。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1103a", "t": "单选题", "s": "【病例】患者女，48岁，突发剧烈头痛伴呕吐2小时，体检示颈项强直。临床疑蛛网膜下腔出血，已行颅脑CT平扫未见明显高密度灶，临床要求进一步明确有无颅内动脉瘤，拟行颅脑CTA。 颅脑CTA确定扫描延迟时间通常采用的方法是", "o": {"A": "团注追踪（自动触发）或小剂量测试", "B": "固定延迟120秒", "C": "无需延迟，直接扫描", "D": "根据心率推算", "E": "口服对比剂后立即扫描"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-109", "kp": "CTA延迟时间确定", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】CTA常用团注追踪（在靶血管兴趣区监测CT值自动触发）或小剂量测试法确定个体化的扫描延迟时间，以保证动脉期成像，故A正确。\n【为什么错】B：固定延迟120秒为静脉期，动脉显示不佳。C：不延迟则对比剂未达颅内动脉。D：心率与循环时间无简单线性对应，不精确。E：口服对比剂不能进入动脉。", "tr": "团注追踪阈值常用100～150HU，触发后自动扫描，是CTA标准的延迟控制方式。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1103b", "t": "单选题", "s": "CTA原始数据后处理中，最能立体直观显示动脉瘤形态的显示方法是", "o": {"A": "容积再现（VR）", "B": "最大密度投影（MIP）", "C": "曲面重建（CPR）", "D": "多平面重建（MPR）", "E": "仿真内镜（CTVE）"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-110", "kp": "CTA三维显示", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】VR容积再现将全部容积数据进行立体重建，可直观显示动脉瘤形态、与载瘤动脉关系，是CTA最直观的三维显示方法，故A正确。\n【为什么错】B：MIP是最大密度投影，重叠结构多，空间关系显示不如VR。C：CPR适合迂曲血管拉直显示，立体感差。D：MPR为二维多平面。E：CTVE用于腔内观察。", "tr": "VR立体直观、MIP密度直观，二者常联合应用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1104a", "t": "单选题", "s": "【病例】患者男，40岁，突发左侧腰部绞痛伴血尿半天，临床疑泌尿系结石，既往有痛风病史，血尿酸升高。拟行CT检查明确结石并评估结石成分。 为鉴别尿酸结石与含钙结石，应选择的检查方法是", "o": {"A": "双能量CT", "B": "常规平扫", "C": "增强扫描", "D": "CT灌注", "E": "HRCT"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-111", "kp": "双能量CT结石分析", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】双能量CT通过物质分离可鉴别尿酸结石与含钙结石，对治疗选择（药物溶石 vs 碎石）有重要价值，故A正确。\n【为什么错】B：常规平扫只能显示结石位置，不能区分成分。C：增强不用于结石成分分析。D：灌注与结石成分无关。E：HRCT用于精细结构，非成分分析。", "tr": "尿酸结石在双能量CT上可识别，此患者有痛风史，尿酸结石可能性大。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1104b", "t": "单选题", "s": "若该患者为尿酸结石，在CT平扫上通常表现为", "o": {"A": "高密度", "B": "等密度（相对软组织）", "C": "极低密度（近水或更低）", "D": "钙化样极高密度", "E": "脂肪密度"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-112", "kp": "尿酸结石密度", "ch": "九、CT检查技术 → 2.检查方法 → (6)能量成像", "ex": "【为什么对】尿酸结石密度较低，CT值约300～500HU，相对于含钙结石（>800HU甚至更高）表现为较低密度，部分接近软组织或水密度，故C正确。\n【为什么错】A、D：高密度/钙化样极高密度为含钙结石特征。B：等密度描述不准确，尿酸结石密度低于软组织。E：脂肪密度不会出现在结石。", "tr": "含钙结石CT值高（可>1000HU），尿酸结石CT值低（约300～500HU），双能量CT可更准确区分。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1105a", "t": "单选题", "s": "【病例】患者男，67岁，胸部CT发现右肺下叶一枚2.5cm分叶状肿块，边缘毛刺，行纤支镜及痰细胞学检查未确诊，临床拟行CT导向经皮肺穿刺活检明确病理。 CT导向肺穿刺活检前，必须评估的患者条件是", "o": {"A": "凝血功能（血小板计数、凝血时间）", "B": "血型", "C": "骨密度", "D": "听力", "E": "视力"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-113", "kp": "肺穿刺前评估", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】肺穿刺前必须评估凝血功能（血小板、凝血时间、凝血酶原时间等），凝血功能障碍是穿刺禁忌证，故A正确。\n【为什么错】B：血型对穿刺活检不是必需评估项。C：骨密度与穿刺无关。D、E：听力、视力与穿刺禁忌无关。", "tr": "严重出血倾向、血小板<50×10⁹/L为肺穿刺相对禁忌，术前必须排查。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1105b", "t": "单选题", "s": "穿刺过程中为减少损伤和并发症，进针时嘱患者", "o": {"A": "屏气或平静呼吸配合进针", "B": "深呼吸快速喘气", "C": "持续咳嗽", "D": "大声说话", "E": "随意活动"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-114", "kp": "肺穿刺配合", "ch": "九、CT检查技术 → 2.检查方法 → (7)CT导向穿刺活检与治疗", "ex": "【为什么对】肺穿刺时嘱患者屏气或平静呼吸，使病灶位置相对固定，避免呼吸运动导致穿刺针偏移及损伤，故A正确。\n【为什么错】B：快速喘气使肺上下移动，易损伤肺组织。C：咳嗽产生剧烈运动。D、E：说话和活动均会使体位改变。", "tr": "肺穿刺常见并发症为气胸和出血，呼吸配合是减少并发症的重要环节。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1106a", "t": "单选题", "s": "【病例】患者男，50岁，上腹隐痛伴消瘦1个月，体检无明显阳性体征。临床申请上腹部CT平扫加增强扫描，评估有无胰腺、肝脏占位性病变。 该患者检查前空腹要求一般为", "o": {"A": "禁食4～6小时", "B": "禁食24小时", "C": "禁食2小时", "D": "无需禁食", "E": "禁食12小时以上"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-115", "kp": "腹部检查空腹要求", "ch": "九、CT检查技术 → 3.检查前准备 → (2)患者", "ex": "【为什么对】腹部CT检查常规要求禁食4～6小时，以减少胃肠道内容物干扰、便于口服对比剂充盈，故A正确。\n【为什么错】B：禁食24小时过长，影响患者耐受。C：2小时过短，胃内食物未排空。D：不空腹影响图像质量。E：12小时以上无必要。", "tr": "上腹部CT禁食4～6小时，同时要训练屏气，双重要求都要落实。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查前准备", "页": 223}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1106b", "t": "单选题", "s": "为排除胰腺病变，胰腺CT扫描宜采用的层厚和时相是", "o": {"A": "薄层扫描＋增强动脉期和实质期", "B": "厚层扫描平扫即可", "C": "只做平扫", "D": "薄层扫描但只做平扫", "E": "厚层扫描＋增强门脉期即可"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-116", "kp": "胰腺CT扫描方案", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】胰腺病变CT应薄层扫描并增强多期（动脉期约25～30s显示胰腺实质强化，实质期约40～45s，门脉期显示周围血管），故A正确。\n【为什么错】B：厚层扫描遗漏细小病灶。C、D：平扫不能显示胰腺肿瘤的强化特征。E：仅门脉期会遗漏动脉期强化征象。", "tr": "胰腺双期增强（动脉期+实质期）是胰腺肿瘤CT检查的规范方案。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1106c", "t": "单选题", "s": "上腹部增强扫描中，对比剂的注射方式通常是", "o": {"A": "高压注射器快速团注", "B": "缓慢滴注", "C": "口服", "D": "皮下注射", "E": "肌肉注射"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-117", "kp": "增强对比剂注射方式", "ch": "九、CT检查技术 → 2.检查方法 → (3)增强扫描", "ex": "【为什么对】CT增强扫描必须用高压注射器将对比剂快速团注（一般2.5～4ml/s），以保证各期相强化效果，故A正确。\n【为什么错】B：缓慢滴注无法形成团注，各期相不清晰。C：口服对比剂只充盈胃肠道。D、E：皮下、肌肉注射对比剂不能进入血循环成像。", "tr": "团注（bolus）是增强和CTA的核心，流速不足会导致强化不充分。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1107a", "t": "单选题", "s": "【病例】患者男，38岁，长期弯腰劳作，近1个月腰痛伴右下肢放射性疼痛、麻木，查体示直腿抬高试验阳性。临床疑腰椎间盘突出，拟行腰椎CT检查。 腰椎间盘CT扫描，为准确显示椎间盘，扫描层面应", "o": {"A": "平行于椎间隙", "B": "垂直于椎间隙", "C": "与椎体长轴垂直即可", "D": "任意方向", "E": "平行于床面即可"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-118", "kp": "椎间盘扫描定位", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】腰椎间盘CT扫描时，层面应平行于椎间隙（通过侧位定位像确定，必要时倾斜机架或重建），才能准确显示椎间盘形态与突出方向，故A正确。\n【为什么错】B：垂直于椎间隙为矢状位的概念。C：与椎体长轴垂直可平行椎体但不是椎间盘。D：任意方向会产生倾斜伪影。E：平行床面与椎间隙方向不一致（腰椎有生理前凸）。", "tr": "腰椎生理前凸使椎间隙倾斜，需在定位像上逐层对准椎间隙扫描。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1107b", "t": "单选题", "s": "该患者椎间盘扫描的层厚一般为", "o": {"A": "1～2mm", "B": "5mm", "C": "10mm", "D": "15mm", "E": "20mm"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-119", "kp": "椎间盘扫描层厚", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】椎间盘厚度仅数毫米，需薄层扫描（1～2mm）才能清楚显示椎间盘与椎管关系，故A正确。\n【为什么错】B、C、D、E：5～20mm层厚过厚，无法精细显示椎间盘突出与硬膜囊受压情况。", "tr": "椎体扫描可用3～5mm，椎间盘必须薄层（1～2mm），两者层厚不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1108", "t": "案例分析题", "s": "患者男，56岁，既往高血压病史5年。1小时前突发右侧肢体无力、言语不清，伴轻度头痛，无恶心呕吐。急诊查体：神志清，右侧肢体肌力Ⅲ级，右侧巴氏征（＋），血压160/95mmHg。临床拟诊急性脑梗死或脑出血，申请急诊头颅CT检查，需要快速鉴别诊断并为后续治疗提供依据。关于该患者头颅CT检查方案，下列做法最恰当的是", "o": {"A": "行头颅CT平扫，扫描基线为听眦线（OML）", "B": "直接行头颅增强扫描", "C": "直接行头颅CTA", "D": "直接行CT灌注扫描", "E": "行头颅MRI检查代替CT"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-120", "kp": "急性脑卒中CT平扫", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (1)颅脑", "ex": "【为什么对】急性脑卒中需快速鉴别出血与缺血，头颅CT平扫是首选检查，可立即显示急性出血（高密度），扫描基线为听眦线（OML），故A正确。\n【为什么错】B：增强扫描对急性出血与缺血鉴别无优势，且延误时间。C：CTA用于血管病变评估，不是急性卒中首选鉴别手段。D：灌注在平扫排除出血后才考虑。E：MRI检查时间长，急性期不适用。", "tr": "急性脑卒中的检查流程：先CT平扫排除出血，再决定是否溶栓或进一步灌注/CTA。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1109", "t": "案例分析题", "s": "患者男，63岁，突发右侧肢体偏瘫伴失语3小时入院，头颅CT平扫未见明显高密度灶，疑急性缺血性脑卒中。临床拟评估梗死核心与缺血半暗带，以决定是否进行溶栓治疗。关于该患者进一步CT检查方法的选择，最合适的是", "o": {"A": "CT灌注成像（同层动态扫描）评估CBF、CBV、MTT", "B": "CT增强扫描观察强化灶", "C": "头颅HRCT", "D": "双能量去骨扫描", "E": "头颅平扫复查一次即可"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-121", "kp": "缺血半暗带灌注评估", "ch": "九、CT检查技术 → 2.检查方法 → (4)CT灌注成像", "ex": "【为什么对】急性缺血性脑卒中需CT灌注评估梗死核心（CBF、CBV均下降）与缺血半暗带（CBF下降、CBV正常或升高、MTT延长），指导溶栓治疗，故A正确。\n【为什么错】B：增强扫描不提供血流动力学参数。C：HRCT用于精细结构显示，非血流评估。D：去骨用于CTA后处理。E：平扫复查不能提供灌注信息。", "tr": "半暗带可挽救是溶栓的依据；灌注参数中MTT延长＋CBF下降提示缺血。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1110", "t": "案例分析题", "s": "患者女，34岁，泌乳、闭经半年，实验室检查示血泌乳素明显升高，临床疑垂体微腺瘤。影像科医师准备为其进行鞍区CT检查，以观察垂体及鞍区骨质改变。关于鞍区CT检查的扫描技术，正确的做法是", "o": {"A": "薄层扫描（1～2mm）＋冠状位扫描，必要时增强", "B": "常规10mm层厚横断面扫描", "C": "只做横断面厚层扫描", "D": "低剂量平扫即可", "E": "CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-122", "kp": "鞍区CT扫描技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (2)鞍区", "ex": "【为什么对】鞍区结构细小，需薄层（1～2mm）扫描，并常规行冠状位以显示垂体、鞍底及蝶窦，必要时增强观察垂体微腺瘤（低强化区），故A正确。\n【为什么错】B、C：常规厚层横断面无法显示垂体细微结构。D：低剂量平扫密度分辨力不足。E：灌注非鞍区常规检查。", "tr": "垂体微腺瘤首选MRI，CT用于显示骨质与钙化，鞍区扫描必须薄层。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1111", "t": "案例分析题", "s": "患者男，28岁，装修工人，工作时不慎铁屑崩入左眼，剧烈疼痛、畏光、流泪，临床疑眼内异物。影像科拟行眼部CT检查以明确异物位置及有无眼球穿通伤。关于该患者眼部CT检查方案，正确的是", "o": {"A": "行薄层CT扫描，横断面基线为听眶下线（IOML），并加冠状位扫描", "B": "嘱患者闭眼后做MRI检查", "C": "直接行增强扫描", "D": "行常规厚层颅脑扫描代替", "E": "CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-123", "kp": "眼部异物CT", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (3)眼部", "ex": "【为什么对】眼内金属异物应行薄层CT（横断面IOML基线＋冠状位），CT能清晰显示异物位置及穿通伤，故A正确。\n【为什么错】B：金属异物禁做MRI（磁致移动损伤眼球），此为原则性错误。C：增强对异物显示无帮助。D：常规厚层颅脑扫描无法显示眼球细小异物。E：灌注与异物无关。", "tr": "金属异物MRI绝对禁忌，眼内异物检查首选CT薄层扫描。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1112", "t": "案例分析题", "s": "患者男，42岁，右耳反复流脓伴听力下降2年，近期耳内镜检查见鼓膜穿孔，临床疑中耳胆脂瘤，需了解听小骨及乳突骨质破坏情况。关于颞骨（耳部）CT检查的扫描技术，正确的是", "o": {"A": "行HRCT扫描：薄层（0.5～1mm）、骨算法重建、大窗宽骨窗显示", "B": "常规层厚软组织算法扫描", "C": "低剂量CT扫描", "D": "增强扫描即可", "E": "CT灌注成像"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-124", "kp": "颞骨HRCT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (4)耳部", "ex": "【为什么对】中耳胆脂瘤需观察听小骨及骨质破坏，颞骨HRCT采用薄层（0.5～1mm）、骨算法（高空间频率）重建，并用大窗宽骨窗显示，故A正确。\n【为什么错】B：软组织算法空间分辨力不足，不能清晰显示骨迷路与听小骨。C：低剂量不能满足精细结构显示。D：增强不能显示骨质破坏。E：灌注与骨结构显示无关。", "tr": "颞骨HRCT的“骨窗”窗宽常1000～3000HU，窗位300～500HU，才能显示骨性结构。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1113", "t": "案例分析题", "s": "患者女，30岁，反复鼻塞、流脓涕、头面部胀痛2年，加重1周，临床疑慢性鼻窦炎，拟行鼻窦CT检查，重点观察窦口鼻道复合体及各组鼻窦情况。关于鼻窦CT检查的扫描技术，正确的是", "o": {"A": "行横断面＋冠状位扫描，冠状位基线垂直于硬腭", "B": "仅行横断面扫描", "C": "行CT增强扫描", "D": "行CT灌注扫描", "E": "行常规厚层颅脑扫描代替"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-125", "kp": "鼻窦CT扫描技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (5)鼻与鼻窦", "ex": "【为什么对】鼻窦CT常规行横断面＋冠状位扫描，冠状位基线垂直于硬腭，可清晰显示窦口鼻道复合体及窦口引流情况，故A正确。\n【为什么错】B：仅横断面不能充分显示窦口鼻道复合体。C：鼻窦炎平扫即可，增强非必需。D：灌注不用于鼻窦炎。E：颅脑扫描范围与参数不适合鼻窦。", "tr": "窦口鼻道复合体是鼻窦炎CT评估的核心区域，冠状位显示最佳。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1114", "t": "案例分析题", "s": "患者男，50岁，下颌骨膨隆伴麻木3个月，口腔科检查见下颌骨体部肿物，X线片示下颌骨不规则骨质破坏，临床疑下颌骨肿瘤，拟行口腔颌面部CT检查，需要评估肿瘤范围、骨质破坏及周围软组织侵犯情况。关于该患者颌面部CT检查方案，正确的是", "o": {"A": "行薄层扫描＋骨窗与软组织窗观察，必要时三维重建（MPR、VR）", "B": "行厚层扫描即可", "C": "仅行软组织窗扫描", "D": "行CT灌注扫描", "E": "行冠脉CTA"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-126", "kp": "颌面部CT扫描", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (6)口腔颌面部", "ex": "【为什么对】颌面部肿瘤需薄层扫描，同时用骨窗显示骨质破坏、软组织窗显示软组织侵犯，并可行三维重建辅助手术规划，故A正确。\n【为什么错】B：厚层扫描遗漏细节。C：仅软组织窗不能显示骨质破坏。D：灌注非颌面部常规。E：冠脉CTA针对心脏。", "tr": "颌面部检查骨窗与软组织窗并用，是显示骨与软组织病变的基本原则。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1115", "t": "案例分析题", "s": "患者男，60岁，声音嘶哑伴吞咽不适2个月，喉镜检查见声带增生物，病理为鳞状细胞癌，临床拟行喉部CT检查以评估肿瘤范围、声门上下侵犯及颈部淋巴结转移情况。关于喉部及颈部CT检查的技术要点，正确的是", "o": {"A": "嘱患者平静呼吸避免吞咽，行颈部薄层增强扫描", "B": "嘱患者持续咳嗽后扫描", "C": "仅行喉部平扫", "D": "行厚层扫描即可", "E": "行CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-127", "kp": "喉部颈部CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (7)咽喉部", "ex": "【为什么对】喉部检查需避免吞咽动作，颈部薄层增强扫描可评估肿瘤范围与淋巴结转移，故A正确。\n【为什么错】B：咳嗽产生严重运动伪影。C：平扫对肿瘤定性及淋巴结评估不足。D：厚层扫描遗漏细小侵犯。E：灌注非喉癌常规。", "tr": "喉癌CT增强扫描结合发长音（“咿”）可使声带张开，更好显示声带病变。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1116", "t": "案例分析题", "s": "患者女，36岁，颈部右侧触及肿块3个月，无压痛，随吞咽上下移动，甲状腺功能检查正常，超声示甲状腺右叶实性结节伴沙砾样钙化，临床疑甲状腺癌，拟行颈部CT增强扫描评估甲状腺结节及颈部淋巴结。关于该患者颈部CT扫描的技术要点，正确的是", "o": {"A": "行颈部薄层增强扫描，观察结节强化及周围结构", "B": "仅行颈部平扫", "C": "行冠脉CTA扫描", "D": "行腹部增强扫描", "E": "行CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-128", "kp": "甲状腺CT增强", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (8)颈部", "ex": "【为什么对】甲状腺结节伴钙化疑癌，应行颈部薄层增强扫描，观察结节强化特征及颈部淋巴结转移情况，故A正确。\n【为什么错】B：平扫对恶性征象（如侵犯周围结构、淋巴结）显示不足。C：冠脉CTA针对心脏。D：腹部增强不针对颈部病灶。E：灌注非甲状腺常规。", "tr": "甲状腺增强扫描时注意对比剂中的碘可影响甲状腺功能，检查前应询问病史。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1117", "t": "案例分析题", "s": "患者男，58岁，进行性呼吸困难伴干咳半年，肺功能检查示限制性通气障碍，临床疑间质性肺病，申请胸部CT检查评估肺间质改变。影像科拟行高分辨力CT（HRCT）检查。关于该患者HRCT检查的技术要点，正确的是", "o": {"A": "薄层扫描（1～2mm）＋高空间频率算法重建，配合深吸气后屏气", "B": "常规10mm层厚软组织算法扫描", "C": "低剂量厚层扫描", "D": "增强扫描即可", "E": "CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-129", "kp": "肺间质病HRCT", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】间质性肺病需HRCT：薄层（1～2mm）＋高空间频率算法（骨算法），显示肺小叶间隔、网状影等细微结构，并需屏气配合，故A正确。\n【为什么错】B：常规层厚软组织算法无法显示肺间质细微改变。C：低剂量厚层空间分辨力不足。D：增强对间质改变显示无帮助。E：灌注不用于间质性肺病评估。", "tr": "HRCT是间质性肺病诊断与随访的核心手段，高空间频率算法是关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1118", "t": "案例分析题", "s": "患者男，52岁，吸烟20年，单位体检胸部低剂量CT发现右下肺一枚1.2cm实性结节，形态不规则，边缘见浅分叶及毛刺。临床拟进一步明确结节性质，考虑行靶扫描及增强扫描。关于该患者肺结节CT进一步检查的技术要点，正确的是", "o": {"A": "行靶扫描（缩小视野放大重建）提高空间分辨力，并评估增强后强化程度", "B": "直接行冠脉CTA", "C": "行CT灌注即可，不需薄层", "D": "行厚层扫描观察整体", "E": "行腹部增强扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-130", "kp": "肺结节靶扫描增强", "ch": "九、CT检查技术 → 2.检查方法 → (2)特殊扫描技术", "ex": "【为什么对】肺小结节可行靶扫描（缩小视野放大重建）提高空间分辨力观察边缘特征，增强扫描评估强化程度有助于良恶性判断，故A正确。\n【为什么错】B：冠脉CTA与肺结节无关。C：灌注不能替代薄层形态学观察。D：厚层扫描有部分容积效应，掩盖细节。E：腹部增强不针对肺结节。", "tr": "肺结节增强强化值（如强化>15HU）对恶性提示有意义；靶扫描提高细节显示。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1119", "t": "案例分析题", "s": "患者男，66岁，反复活动后胸闷、胸痛1个月，心电图示心肌缺血改变，临床疑冠心病，拟行冠状动脉CTA检查。患者平时心率78次/分，偶有早搏。关于该患者冠脉CTA检查前及检查中的处理，正确的是", "o": {"A": "口服β受体阻滞剂控制心率至70次/分以下，采用心电门控扫描", "B": "不控制心率直接扫描", "C": "行非门控胸部平扫代替", "D": "行CT灌注代替CTA", "E": "行腹部增强扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-131", "kp": "冠脉CTA检查流程", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】冠脉CTA需将心率控制在70次/分以下（口服β受体阻滞剂），并采用心电门控扫描保证图像质量，故A正确。\n【为什么错】B：心率过快冠脉运动伪影明显，图像无法诊断。C：平扫不能显示冠脉腔。D：灌注不显示冠脉解剖。E：腹部增强与冠脉无关。", "tr": "冠脉CTA成功率取决于心率控制、屏气配合和心电门控三要素。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1120", "t": "案例分析题", "s": "患者女，49岁，体检超声发现肝右叶低回声结节2.0cm，边缘尚清，甲胎蛋白轻度升高，有乙型肝炎病史。临床拟行肝脏增强CT多期扫描，明确病灶性质并评估血供。关于肝脏三期增强CT的扫描时相设置，正确的是", "o": {"A": "动脉期25～30秒、门静脉期60～70秒、平衡期120～180秒扫描", "B": "仅扫描动脉期即可", "C": "各期均固定在180秒扫描", "D": "各期均在10秒内扫描", "E": "只做平扫即可定性"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-132", "kp": "肝脏三期增强时相", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肝脏增强CT常规设动脉期（25～30s）、门静脉期（60～70s）、平衡期（120～180s），动态观察病灶强化方式，故A正确。\n【为什么错】B：仅动脉期不能观察门脉期与延迟期廓清情况。C：各期180秒固定无法捕捉动脉期高强化。D：10秒内各期尚未到达。E：平扫不能显示强化特征。", "tr": "肝癌“快进快出”与血管瘤“慢进慢出”的鉴别依赖多期动态扫描。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1121", "t": "案例分析题", "s": "患者男，47岁，反复腹痛伴腰背部疼痛2个月，CT平扫发现胰体尾部肿块，与脾动脉关系密切，临床疑胰腺癌，需行胰腺增强CT评估肿瘤分期及血管侵犯情况。关于该患者胰腺CT扫描的技术要点，正确的是", "o": {"A": "薄层扫描＋增强动脉期、实质期多期扫描", "B": "厚层平扫即可", "C": "仅行门静脉期扫描", "D": "行低剂量厚层扫描", "E": "行CT灌注扫描代替增强"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-133", "kp": "胰腺癌CT扫描", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】胰腺癌评估需薄层扫描＋增强多期（动脉期显示肿瘤与动脉关系、实质期显示胰周浸润），评估血管侵犯与分期，故A正确。\n【为什么错】B：厚层平扫无法显示肿瘤血供与血管侵犯。C：仅门脉期会遗漏动脉期信息。D：低剂量厚层不能满足胰腺精细评估。E：灌注不能替代增强多期解剖成像。", "tr": "胰腺双期增强（动脉期＋实质期）可提高胰腺癌检出率，薄层扫描不可省略。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1122", "t": "案例分析题", "s": "患者男，50岁，无痛性肉眼血尿1周，超声发现左肾上极实性占位，临床疑肾细胞癌，拟行肾脏增强CT检查，评估肿瘤范围及有无肾静脉、下腔静脉癌栓。关于该患者肾脏CT增强扫描的期相设置，正确的是", "o": {"A": "皮质期25～30秒、实质期60～70秒、排泄期180秒及以后扫描", "B": "仅扫描排泄期即可", "C": "仅扫描动脉期即可", "D": "各期均在10秒内完成", "E": "只做平扫即可"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-134", "kp": "肾脏增强期相", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (14)腹部", "ex": "【为什么对】肾癌CT增强常规皮质期（25～30s）、实质期（60～70s）评估肿瘤血供，排泄期（约180s后）观察肾盂及静脉癌栓情况，故A正确。\n【为什么错】B：仅排泄期无法显示皮质期富血供强化。C：仅动脉期无法显示肾实质期。D：10秒内无法完成各期相。E：平扫无法显示血供特征。", "tr": "肾癌“快进快出”、皮质期强化明显；排泄期显示肾静脉癌栓有价值。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1123", "t": "案例分析题", "s": "患者女，55岁，下腹坠胀伴月经量增多半年，妇科检查示子宫增大，超声疑子宫肌瘤，临床拟行盆腔CT增强扫描评估子宫及附件情况。影像科技师需正确完成盆腔CT检查的准备工作。关于盆腔CT检查前的准备，正确的是", "o": {"A": "充盈膀胱，口服对比剂充盈肠道，必要时阴道填塞标记", "B": "排空膀胱即可扫描", "C": "禁食24小时以上", "D": "无需任何准备", "E": "行CT灌注扫描代替增强"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-135", "kp": "盆腔CT准备", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (15)盆腔", "ex": "【为什么对】盆腔CT检查前应充盈膀胱、口服对比剂充盈肠道，女性必要时阴道填塞标记物，以清晰显示盆腔器官，故A正确。\n【为什么错】B：排空膀胱后膀胱显示不清，周围结构分辨差。C：禁食24小时过长且无必要。D：盆腔检查有明确准备要求。E：灌注不替代增强解剖成像。", "tr": "盆腔CT“憋尿”是经典准备要求，与腹部“禁食”不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1124", "t": "案例分析题", "s": "患者男，35岁，高处坠落致腰部疼痛、活动受限，疑腰椎压缩性骨折，X线片示L1椎体楔形变。临床拟行腰椎CT检查，进一步明确骨折情况、椎管受累及椎间盘情况。关于该患者腰椎CT扫描的技术要点，正确的是", "o": {"A": "椎体骨折用常规层厚骨窗观察，椎间盘用薄层扫描并矢状位重建", "B": "全程厚层20mm扫描", "C": "仅行软组织窗扫描", "D": "行CT灌注扫描", "E": "行冠脉CTA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-136", "kp": "腰椎骨折CT", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (16)脊柱", "ex": "【为什么对】腰椎骨折CT椎体部分用骨窗观察骨折线，椎间盘及椎管用薄层扫描并矢状位重建评估椎管狭窄，故A正确。\n【为什么错】B：厚层20mm无法显示细小骨折线。C：软组织窗不能显示骨皮质断裂。D：灌注与骨折无关。E：冠脉CTA针对心脏。", "tr": "脊柱骨折CT检查骨窗为主，矢状位重建对骨折及椎管评估非常重要。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1125", "t": "案例分析题", "s": "患者男，26岁，运动扭伤右膝关节，关节肿胀疼痛、活动受限，临床疑膝关节韧带及半月板损伤，申请右膝关节CT检查评估骨性结构与关节对位情况。关于该患者膝关节CT检查的技术要点，正确的是", "o": {"A": "行双侧对照扫描，骨窗＋软组织窗观察，必要时三维重建", "B": "仅扫描患侧单层面", "C": "行厚层扫描", "D": "行增强扫描", "E": "行CT灌注扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-137", "kp": "膝关节CT技术", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】四肢关节CT应双侧对照扫描、薄层扫描，并用骨窗观察骨质、软组织窗观察软组织，必要时三维重建辅助诊断，故A正确。\n【为什么错】B：单层面扫描不能全面评估。C：厚层扫描遗漏细小骨折。D：增强对骨关节损伤无帮助。E：灌注与关节损伤无关。", "tr": "膝关节韧带、半月板损伤首选MRI，CT用于评估骨性结构与骨折。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1126", "t": "案例分析题", "s": "患者男，32岁，右踝关节扭伤后肿痛3天，X线片未见明确骨折线，但局部压痛明显，临床疑隐匿性骨折，拟行踝关节CT薄层扫描进一步明确。关于该患者CT扫描参数的选择，正确的是", "o": {"A": "薄层扫描＋骨算法重建，骨窗观察，必要时多平面重建", "B": "厚层软组织窗扫描", "C": "低剂量厚层扫描", "D": "增强扫描", "E": "CT灌注扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-138", "kp": "隐匿性骨折CT", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (17)四肢骨关节及软组织", "ex": "【为什么对】隐匿性骨折需薄层扫描＋骨算法（高空间频率）重建，骨窗观察细微骨折线，并可行多平面重建，故A正确。\n【为什么错】B：厚层软组织窗无法显示细微骨折线。C：低剂量厚层空间分辨力不足。D：增强对骨折无帮助。E：灌注与骨折无关。", "tr": "隐匿性骨折（如舟骨骨折、胫骨平台骨折）薄层CT＋骨窗＋MPR是标准方案。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1127", "t": "案例分析题", "s": "患者男，62岁，突发胸背部撕裂样疼痛2小时，血压200/120mmHg，临床高度怀疑主动脉夹层，需急诊行主动脉CTA检查明确诊断及分型。关于该患者主动脉CTA检查的技术要点，正确的是", "o": {"A": "行全主动脉CTA扫描，采用团注追踪确定延迟，必要时心电门控", "B": "行胸部平扫即可", "C": "行腹部增强扫描", "D": "行冠脉CTA即可", "E": "行CT灌注扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-139", "kp": "主动脉CTA", "ch": "九、CT检查技术 → 2.检查方法 → (5)CT血管成像", "ex": "【为什么对】主动脉夹层需全主动脉CTA（升主动脉至髂动脉），用团注追踪确定延迟，评估内膜片、真假腔及分支受累，累及升主动脉时可配合心电门控减少运动伪影，故A正确。\n【为什么错】B：平扫不能显示内膜片与假腔血流。C：仅腹部增强遗漏胸主动脉。D：冠脉CTA范围仅心脏冠脉。E：灌注不能评估夹层形态。", "tr": "主动脉CTA要覆盖全主动脉并显示内膜片，Stanford分型依赖升主动脉是否受累。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-1128", "t": "案例分析题", "s": "患者男，58岁，间歇性胸痛1个月，冠脉CTA检查发现左前降支中段混合性斑块伴中度狭窄，为进一步评估斑块性质及有无心肌缺血，临床医师拟行CT灌注成像评估心肌灌注情况。关于心肌CT灌注成像的叙述，正确的是", "o": {"A": "在静息与负荷（腺苷等）状态下分别扫描，比较心肌血流的差异", "B": "仅做一次静息扫描即可", "C": "用口服对比剂即可完成灌注", "D": "与冠脉CTA完全无关，可单独进行", "E": "灌注参数与心电编辑无关"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-140", "kp": "心肌CT灌注", "ch": "九、CT检查技术 → 4.人体各部位CT检查技术 → (11)心脏血管及功能", "ex": "【为什么对】心肌CT灌注成像需静息与负荷（腺苷、双嘧达莫等药物负荷）两次扫描，比较负荷与静息心肌血流灌注的差异，评估有无缺血，故A正确。\n【为什么错】B：单次静息扫描无法评估负荷诱导的缺血。C：口服对比剂不能进入冠脉循环。D：心肌灌注常与冠脉CTA联合，评估解剖与功能。E：心脏检查同样受心律影响，需心电门控与心电编辑配合。", "tr": "心肌灌注的“负荷-静息”对比是发现可诱导心肌缺血的关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "人体各部位CT检查技术", "页": 224}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U09-9201", "t": "单选题", "s": "颅脑 CT 平扫常规采用的层面方式是", "o": {"A": "冠状位", "B": "矢状位", "C": "横断面（轴位）", "D": "斜位", "E": "三维容积直接成像"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-9201", "kp": "颅脑CT体位", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术", "ex": "【为什么对】颅脑 CT 平扫常规取仰卧位横断面（轴位）扫描。\n【为什么错】冠状/矢状多为重组或特殊需要。", "tr": "颅脑CT常规轴位扫描。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U09-9202", "t": "单选题", "s": "腹部 CT 增强扫描常用的期相不包括", "o": {"A": "动脉期", "B": "静脉期（门脉期）", "C": "延迟期", "D": "平衡期", "E": "分泌期"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "九", "un": "CT检查技术", "kpid": "UNIT-09-CT-9202", "kp": "腹部CT期相", "ch": "九、CT检查技术 → 2.人体各部位CT检查技术", "ex": "【为什么对】腹部增强常用动脉期、门脉期、延迟/平衡期；\"分泌期\"为尿路造影（如CTU）概念，非常规腹盆增强期相。\n【为什么错】动脉/门脉/延迟均为常规期相。", "tr": "腹盆增强期相无\"分泌期\"（CTU除外）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "CT检查技术", "节": "检查方法", "页": 220}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U10-0101", "t": "单选题", "s": "按照通行的MR安全分区管理（Zone I—Zone IV）原则，扫描室（磁体所在房间）本身应界定为", "o": {"A": "Zone I（公众自由出入区）", "B": "Zone II（问诊、更衣、病史与金属筛查区）", "C": "Zone III（受门禁控制、非MR人员须陪同的缓冲区，含操作台）", "D": "Zone IV（磁体间，须有醒目标识与磁场警示灯，任何时刻不得无陪同进入）", "E": "视磁体是否处于扫描状态在Zone III与Zone IV间动态切换"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-001", "kp": "MR安全分区（Zone I—IV）", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】D正确。Zone IV即磁体间本身，是主磁场最强、投射效应风险最高的区域，门外须设醒目警示标识与磁场指示灯（通常为红色警示灯），任何人员进入均须经筛查并由MR授权人员全程陪同；Zone IV在物理上应完全位于Zone III之内。【为什么错】A Zone I是磁场影响之外、公众可自由出入的区域（如门诊走廊、候诊大厅）。B Zone II是Zone I与Zone III之间的过渡区，用于问诊、填写安全筛查表、更衣与去除金属物，患者在此仍属“未筛查”状态但风险可控。C Zone III是受门禁（刷卡/密码/专人）控制的缓冲区，操作台通常设在此处，非MR人员未经陪同不得进入，但它不等同于磁体间。E错误——超导磁体的主磁场是持续存在的（除非失超），分区界定是固定的物理管理边界，不随是否扫描而变化。", "tr": "最常见的混淆是把“操作间”当成Zone IV。记忆口诀：Ⅰ公众—Ⅱ筛查—Ⅲ门禁（含操作台）—Ⅳ磁体间。另一个陷阱是误以为“不扫描时磁场关闭”，超导磁体7×24h带场。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0102", "t": "多选题", "s": "某院MR机房进行安全整改，下列做法中符合MR安全分区与铁磁性物品筛查规范的有", "o": {"A": "Zone III入口设置门禁，钥匙/权限仅授予经过培训的MR工作人员，非MR人员须有陪同方可进入", "B": "在Zone II设置金属探测门或手持铁磁探测仪，对患者与陪同者进行二次筛查，并要求更换无金属检查服", "C": "抢救车、氧气钢瓶、轮椅、输液泵等设备一律停放在Zone III以外，进入Zone IV须换用标注MR Safe或MR Conditional的专用设备", "D": "5高斯（0.5 mT）等磁力线原则上应被限制在Zone IV范围内；若超出，则超出部分必须纳入门禁管制范围", "E": "危急抢救时为争取时间，可由医师口头授权将普通金属推床直接推入Zone IV完成转运"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-002", "kp": "MR安全分区管理与铁磁性物品筛查", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确：Zone III的核心特征就是物理门禁与授权管理。B正确：铁磁筛查应分层进行（问卷—人工核查—探测设备），普通金属探测门对非铁磁金属也报警，专用铁磁探测仪特异性更好，二者互补。C正确：Zone IV内只允许MR Safe（全程安全）或经确认条件的MR Conditional设备；钢制氧气瓶是文献报道致死事故的经典元凶。D正确：5高斯线是心脏起搏器等植入物携带者的安全边界，规范要求其被限制在受控区域内。【为什么错】E错误：抢救时的正确流程是“把患者移出Zone IV再抢救”，而不是“把抢救设备推进Zone IV”。磁体孔口附近空间梯度最大，铁磁性推床会以极高速度被吸入，造成致命投射事故。急救的标准动作是立即将患者转移至Zone IV外的复苏区，失超只有在人被吸附压迫、无法解救时才考虑。", "tr": "E是最危险的临床错觉——“救命要紧”不能凌驾于磁体安全。牢记：救人靠“把人移出去”，不是“把设备推进来”；失超（quench）不是常规解困手段，其本身有窒息与冻伤风险。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0103", "t": "单选题", "s": "患者男，72岁，因腰痛拟行腰椎MRI。随身携带的心脏起搏器条件卡显示：MR Conditional，适用静磁场1.5T，正常运行模式，全身SAR≤2.0 W/kg，梯度切换率≤200 T/m/s，扫描区域不限。本科室仅有一台飞利浦3.0T设备。技师最恰当的处置是", "o": {"A": "既然标注为MR Conditional，可在3.0T按常规参数扫描", "B": "在3.0T上把序列改为低SAR模式（SAR<2.0 W/kg）并降低梯度切换率后即可扫描", "C": "条件卡限定为1.5T，超出标定场强即失去条件安全依据，本机不可扫描；应联系心内科程控后转至1.5T设备按条件卡逐条执行", "D": "请心内科将起搏器程控为关闭状态，即可在3.0T安全扫描", "E": "改用发射/接收头线圈局部发射，即可在3.0T安全扫描腰椎"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-003", "kp": "MR Conditional植入物的条件核对", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】C正确。MR Conditional（磁共振条件安全）的含义是“仅在标签规定的全部条件同时满足时才安全”，这些条件通常包括静磁场强度、空间梯度场上限、梯度切换率、SAR或B1+rms上限、扫描部位、扫描时长等。任何一条不满足，该器械在此环境下即等同于不安全。条件卡明确写1.5T，3.0T下的射频波长效应、导线天线效应与发热风险完全不同，不能通过“调低参数”外推。正确路径是转诊至符合条件的1.5T设备，并由心内科在扫描前后程控（改为MRI模式/非同步或关闭感知）、全程心电血氧监护、备除颤仪。【为什么错】A把MR Conditional当成MR Safe，是最常见的致命误解。B错误：场强本身不可调，SAR达标并不能弥补场强超标；且3.0T导线共振长度与1.5T不同。D错误：关闭起搏功能对起搏依赖患者反而致命，且不能解决场强超标问题。E错误：腰椎扫描无法用头线圈发射，而且局部发射线圈也不改变静磁场超标的事实。", "tr": "把MR Safe（无条件安全，如塑料）与MR Conditional（条件安全）混为一谈是最大陷阱。ASTM F2503标识：MR Safe为绿色方块内白色“MR”；MR Conditional为黄色三角内黑色“MR”；MR Unsafe为红色圆圈加斜杠内黑色“MR”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0104", "t": "多选题", "s": "关于颅内动脉瘤夹患者的MRI安全评估，下列判断正确的有", "o": {"A": "钛及钛合金动脉瘤夹为非铁磁性材料，在核实型号、批次与厂家标注后可按条件扫描", "B": "早期（约1995年之前）使用的部分不锈钢（如马氏体不锈钢）动脉瘤夹具有铁磁性，可发生移位与扭矩，属绝对禁忌", "C": "凡病历中无法查证夹子型号、材质与手术记录者，一律按“不可扫描”处理，改行CTA评估", "D": "铁磁性夹子在磁体内受到的平移力主要取决于静磁场的空间梯度而非中心场强，因此磁体孔口处风险最高", "E": "动脉瘤夹只要术后满6个月，周围已形成纤维包裹固定，无论材质均可安全扫描"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-004", "kp": "动脉瘤夹材质判定与铁磁力学", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】A正确：钛/钛合金及部分钴基合金（如Phynox、Elgiloy）属非铁磁或弱铁磁，经厂家标注核实后可按条件扫描。B正确：早期马氏体不锈钢夹具有明显铁磁性，磁场中受扭矩可致夹子旋转、血管撕裂出血，历史上有致死报道，属绝对禁忌。C正确：MR安全遵循“不能证明安全即视为不安全”的原则，材质不可考时应改用CTA/DSA。D正确：铁磁性物体所受平移力F∝M·dB/dz，取决于场强与空间梯度的乘积，空间梯度在磁体孔口（bore入口）附近最大，因此“孔口”而非“磁体中心”是投射力最强处；而扭矩才主要与中心场强有关。【为什么错】E错误：“时间够久就安全”是没有依据的推断。纤维包裹产生的固定力远小于强磁场对铁磁性夹产生的扭矩，材质才是决定因素，时间不能改变材质的磁化率。", "tr": "D是高阶考点：吸引（投射）力取决于B·dB/dz，最大处在孔口而非等中心；扭矩最大处在等中心（场强最高）。很多考生误认为“越靠近中心越危险”。E的“时间安全论”是经典陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0105", "t": "单选题", "s": "关于人工耳蜗（cochlear implant）植入者的MRI检查，下列说法正确的是", "o": {"A": "人工耳蜗一律为MR Safe，可常规扫描", "B": "多数人工耳蜗内含永磁体，属MR Unsafe或需在满足条件（外科取出内置磁体、或使用专用加压绷带固定并限定场强）时方可扫描，且颞部会遗留大范围磁敏感伪影", "C": "人工耳蜗的风险仅为伪影，不存在移位或去磁风险", "D": "只要取下体外言语处理器，植入体即无任何风险", "E": "人工耳蜗患者可行3.0T扫描但禁行1.5T扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-005", "kp": "人工耳蜗与MRI安全", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】B正确。绝大多数现代人工耳蜗植入体内置一枚用于体外处理器磁吸定位的永磁体。强磁场中可导致：磁体移位/翻转、退磁（去磁后体外机无法吸附）、局部疼痛与皮瓣损伤。因此多数产品标注为MR Unsafe，或为MR Conditional但附加严格条件（限定1.5T、外科小切口取出磁体后扫描、或使用厂家指定的加压绷带固定头部并限制扫描时长）。即便允许扫描，植入侧颞部、后颅窝将出现大范围磁敏感伪影，内耳与桥小脑角结构常无法评估。【为什么错】A错误：与实际标注相反。C错误：磁体移位与退磁是真实且常见的不良事件，不只是伪影问题。D错误：取下体外机是必要步骤，但风险来自植入体内的磁体，不是体外机。E错误：条件通常限定为1.5T，3.0T多不被允许，选项方向说反。", "tr": "考生常把“取下体外机”当成充分条件。要点在于“体内有没有磁体”。同类考点还有：可植入式骨传导助听器、磁性眼睑重物、组织扩张器（含金属注射壶）——凡“内置磁体”者都要高度警惕。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0106", "t": "多选题", "s": "关于植入式神经刺激器（脑深部电刺激DBS、脊髓电刺激SCS、迷走神经刺激VNS）患者的MRI，下列处理原则正确的有", "o": {"A": "必须逐条核对厂家的MR条件说明，包括场强、发射线圈类型、扫描部位、头部/全身SAR或B1+rms上限、扫描时长", "B": "许多DBS产品要求使用发射/接收头线圈或严格限制头部SAR（部分产品要求头部SAR≤0.1 W/kg），并要求扫描前由程控医师将设备设为MRI模式、刺激电压归零", "C": "导线断裂、导线残留（电极已取出但导线未取）或导线走行成环者风险显著升高，因为导线可作为射频天线在尖端产生局部高热", "D": "此类患者禁行任何梯度回波序列，只能采集自旋回波类序列", "E": "只要把刺激器关机，任何场强、任何序列均可安全使用"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-006", "kp": "神经刺激器植入者MRI条件管理", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】A正确：条件安全器械的安全性由标签定义的全部条件共同保证，缺一不可。B正确：DBS的主要风险是电极尖端射频致热（可造成不可逆脑损伤），故厂家常要求限制头部射频功率沉积、指定发射线圈，并要求把刺激参数程控至安全设置。C正确：长导线在射频场中形成谐振天线，尖端电场集中而产热；断裂端、残留导线与成环走行都会加剧这一效应，这也是“导线不得成环”这条通用规则的物理基础。【为什么错】D错误：限制的核心是射频功率沉积（SAR/B1+rms），与序列是GRE还是SE无必然对应关系；实际上高SAR的往往是TSE类的大角度重聚焦序列，而低翻转角GRE的SAR反而更低。把限制误读为“禁GRE”是概念错位。E错误：关机不改变导线的天线特性，也不改变场强与梯度条件；“关机即安全”是危险的想当然。", "tr": "D是精心设计的干扰项——很多考生只记住“梯度回波对金属敏感、伪影大”，就把伪影问题误当成安全问题。安全的关键变量是SAR/B1+rms与导线几何，不是序列家族。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0107", "t": "单选题", "s": "患者男，46岁，金属打磨工人，因头痛申请头颅MRI。安全问卷中自述“约5年前打磨时有异物崩入右眼，冲洗后未就诊，无明显不适”。技师最恰当的处置是", "o": {"A": "既往无症状说明异物已排出，可直接扫描", "B": "先行眼眶X线平片（或眼眶薄层CT）排除眼内金属异物，阴性后方可扫描", "C": "用手持磁铁在眼周试探有无吸引感以判断", "D": "改用0.35T低场开放式设备直接扫描即可规避风险", "E": "让患者签署风险自负知情同意书后按常规扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-007", "kp": "眼内金属异物筛查流程", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】B正确。有金属加工、车工、焊工职业史或明确眼部金属外伤史而未经处理者，属于眼内金属异物高危人群。眼内铁磁性碎屑在强磁场中可发生移位，损伤视网膜、晶状体、玻璃体乃至造成失明，属于绝对禁忌。规范流程是扫描前用眼眶X线平片（通常两个体位）或眼眶薄层CT（对小碎屑更敏感）进行排查，阴性方可扫描。【为什么错】A错误：无症状不能排除异物存留，微小金属屑可长期无症状嵌顿于眼球壁。C错误：用磁铁在眼周试探本身就可能诱发异物移位，是被严格禁止的危险操作。D错误：低场并不等于无风险，且0.35T仍可对铁磁性异物产生足够的位移力；更重要的是这属于用降级方案回避筛查责任。E错误：知情同意不能替代客观筛查，绝对禁忌证不因签字而变为可行。", "tr": "本题的陷阱在E——“签了字就能做”。绝对禁忌证与知情同意是两个层面的问题，签字不构成免责，更不改变物理风险。另注意：眼眶CT敏感性高于平片，但平片作为初筛价格低、可及性好，两者均可接受。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0108", "t": "多选题", "s": "关于妊娠期与哺乳期妇女的MRI检查，下列说法正确的有", "o": {"A": "MRI不使用电离辐射，妊娠期并非绝对禁忌；但妊娠早期（前3个月）在无明确临床必要时不建议施行", "B": "钆对比剂可通过胎盘进入胎儿循环并经胎儿肾脏排入羊水形成再循环，妊娠期原则上应避免使用，除非获益明显大于风险", "C": "妊娠期扫描应尽量降低SAR（如选择正常运行模式、减少大翻转角TSE的连续采集），并注意噪声对胎儿的影响，控制扫描时长", "D": "哺乳期妇女使用大环状钆剂后，因经乳汁分泌量极少（约为注射剂量的万分之一以下），一般不需要中断哺乳", "E": "妊娠期为保护胎儿，MRI必须常规使用镇静剂使孕妇保持绝对静止"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-008", "kp": "妊娠与哺乳期MRI安全", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】A正确：MRI无电离辐射，1.5T/3.0T平扫至今无确证的致畸证据；但器官形成期证据相对有限，故遵循“非必要不做、能推迟则推迟”的谨慎原则。B正确：钆剂可穿过胎盘，胎儿排泄入羊水后可被吞咽再吸收，形成延长暴露，动物实验有致畸报道，故妊娠期原则上不用。C正确：孕期关注的三大物理因素是射频致热（SAR，胎儿散热能力差）、噪声与扫描时长，应主动优化。D正确：大环状钆剂经乳汁分泌量极微、婴儿胃肠吸收率又极低，主流指南认为无须中断哺乳；若产妇仍有顾虑，可弃奶12—24 h。【为什么错】E错误：绝大多数孕妇可清醒配合，镇静药物本身对胎儿存在风险，绝无“必须常规镇静”之说，属明显的绝对化错误表述。", "tr": "B与D方向相反但都正确，考生易被“钆剂孕期禁用”惯性带偏而误判D。要点是分清“经胎盘”（孕期，暴露持久）与“经乳汁”（哺乳期，剂量极微）两条完全不同的途径。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0109", "t": "案例分析题", "s": "患者女，58岁，脑膜瘤术后2年随访，需行头颅MRI平扫+增强。上一次在本院检查时因幽闭恐惧在扫描开始约3分钟后按压呼叫球中止，仅完成定位像与一组T2WI。本次仍诉紧张、担心“喘不上气”。设备为飞利浦3.0T，配备压缩感知加速（CS），无深度学习重建；患者一般情况好，无镇静禁忌。作为技师，最合理的整体处置方案是", "o": {"A": "先行非药物干预：充分讲解流程与时长、允许家属在Zone IV内陪同并握手、采用足先进（feet-first）体位或棱镜眼镜、加强孔内通风与照明、耳机播放音乐、明确交代呼叫球用法；同时用CS加速重排扫描方案，优先采集诊断价值最高的3D T1W增强与T2-FLAIR，把总时长压缩至10 min内；若仍不能耐受，再由麻醉科评估后行清醒镇静并全程监护SpO₂与心率", "B": "直接由技师静脉推注地西泮10 mg后开始扫描，无须麻醉科参与", "C": "用约束带牢固固定头部与躯干，强行完成全部序列", "D": "取消增强，仅做平扫，避免打针加重紧张", "E": "改用0.35T开放式设备完成平扫与增强，因低场噪声小且孔径开放，可完全替代3.0T随访"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-009", "kp": "幽闭恐惧的处理、镇静与监护", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确。幽闭恐惧的规范处置遵循“阶梯化”原则：①非药物干预优先（沟通、陪同、体位与视觉干预、通风照明、音乐、明确的中止通道）；②技术层面缩短暴露时间——压缩感知与并行采集联合可将3D序列缩短约40%—60%，把关键序列前置，即便中途中止也已获得诊断信息；③非药物失败再考虑药物镇静，且必须由具备资质的医师开具与实施，配备MR兼容监护仪（SpO₂、心率、必要时呼气末CO₂）与复苏设备。足先进体位可使头部远离孔中心侧的心理压迫感（对头颅检查需权衡定位可行性，通常用于非头部检查；对头部检查更多依赖棱镜眼镜与镜面装置）。【为什么错】B错误：技师无独立用药权限，且镇静必须有监护与复苏预案，属越权与高风险操作。C错误：强行约束会加剧惊恐发作，可能诱发过度通气甚至意外，且体动伪影仍不可控，违背患者自主权。D错误：脑膜瘤术后随访的核心信息在于增强后是否有结节样强化复发，取消增强等于放弃检查目的。E错误：0.35T的SNR、增强病灶检出敏感度与3D高分辨能力显著低于3.0T，不能等同替代随访基线；开放式设备可作为最后备选而非首选。", "tr": "陷阱在“技术手段与人文手段谁先行”。副高层面要求给出阶梯式方案而非单点措施：先优化流程与序列，再考虑药物；同时牢记技师的执业边界——不得自行给药。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0110", "t": "多选题", "s": "关于MRI检查中的听力防护，下列说法正确的有", "o": {"A": "梯度线圈在磁场中受洛伦兹力发生振动是噪声的主要来源，回波平面成像（EPI）、扩散加权与部分梯度回波序列噪声尤为突出", "B": "所有进入扫描室的受检者与陪同人员均应佩戴听力防护装置，合格耳塞可提供约25—30 dB的降噪", "C": "接受镇静或全身麻醉的患者因无法主诉不适，更应确保听力防护到位", "D": "新生儿与婴幼儿外耳道细小，常规耳塞不适配，应使用专用小号耳塞加耳罩或MR兼容降噪装置，不可省略防护", "E": "耳机播放音乐可完全替代耳塞的物理降噪作用"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-010", "kp": "MRI噪声来源与听力防护", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确：梯度电流在主磁场中产生洛伦兹力，使梯度线圈快速形变振动产生声压，梯度切换越快、幅度越大噪声越强，故EPI类序列声压级最高，3.0T常可超过110 dB(A)。B正确：这是强制性要求，陪同人员同样暴露于噪声环境。C正确：镇静/麻醉患者失去了主动求助能力，是听力损伤的高危人群，防护更不能省。D正确：婴幼儿听觉系统脆弱且不能配合，必须使用适配的专用防护，绝不能因“戴不上”而放弃。【为什么错】E错误：音乐耳机的首要作用是心理安抚与掩蔽，其被动隔声量有限且频响特性不匹配梯度噪声频谱，不能替代耳塞的物理衰减；正确做法是耳塞+耳罩/耳机联合使用。", "tr": "E是常见的现场偷懒做法。另需记住：降低噪声的技术手段还包括采用静音序列（低梯度切换率的正弦/软梯度波形）、降低带宽与梯度幅度，但代价是扫描时间延长或分辨率下降。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0111", "t": "多选题", "s": "为预防MRI检查中的射频灼伤，下列措施正确的有", "o": {"A": "用衬垫隔开大腿与大腿、小腿与小腿、上臂与躯干等皮肤接触部位，避免人体自身形成导电闭合环路", "B": "心电导联线、脉搏血氧探头导线应沿磁体长轴方向平直放置，不得盘绕成环，并与皮肤之间加隔垫", "C": "扫描前移除含金属丝的心电电极、含铝箔背衬的透皮贴剂（如某些镇痛贴、硝酸甘油贴）以及含金属纤维的功能性内衣", "D": "同一序列条件下，3.0T的射频能量沉积约为1.5T的4倍（SAR近似与B₀的平方成正比），高场下更须警惕", "E": "缩短TR、增加单位时间内的射频脉冲数量是降低SAR的有效手段"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-011", "kp": "射频灼伤机制与预防", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确：人体皮肤接触形成的闭合回路可感应涡流，接触点电流密度集中而致灼伤，这是最常见的MR灼伤原因之一。B正确：导线成环等效于线圈，感应电动势正比于环路面积；平直沿主磁场方向布线并加隔垫可显著降低风险。C正确：金属丝电极与铝箔背衬贴剂是局部电场/涡流集中点，多起灼伤事故与之相关。D正确：SAR近似正比于B₀²·α²·（脉冲数/TR），故3.0T相同序列的SAR约为1.5T的4倍，这是高场必须重排序列参数的物理依据。【为什么错】E错误：完全说反。SAR正比于单位时间内沉积的射频能量，缩短TR意味着同样多的射频脉冲在更短时间内发放，SAR升高；降低SAR应延长TR、减少层数、降低重聚焦翻转角（可变翻转角VFL）、缩短回波链或改用低SAR的GRE类序列。", "tr": "E的迷惑点在于“缩短扫描时间=更安全”的错觉。SAR是“单位质量单位时间”的功率概念，缩短TR只会提高功率密度。真正靠缩短时间降SAR的做法是用并行采集减少激励次数或减少层数，而非压TR。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0112", "t": "单选题", "s": "飞利浦3.0T行颈椎T2WI快速自旋回波（TSE/FSE）时系统提示SAR超限，下列调整中不能降低SAR、反而会使其升高的是", "o": {"A": "启用可变翻转角重聚焦（VFL/变角回波链），把重聚焦脉冲翻转角由180°降至约120°", "B": "适当延长TR", "C": "减少同一TR内的采集层数（分两个采集包完成）", "D": "缩短回波链长度（turbo factor/ETL）", "E": "将重聚焦脉冲翻转角由120°提高至180°以增强T2对比"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-012", "kp": "SAR超限的参数调整策略", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】E正确（即“不能降低SAR”的选项）。射频能量沉积近似正比于翻转角的平方，把重聚焦角从120°提高到180°，单个脉冲能量约增至2.25倍，SAR随之显著升高，与降SAR目标背道而驰。【为什么错】A是降SAR最有效的手段之一：TSE的SAR绝大部分来自串联的大角度重聚焦脉冲，采用可变翻转角（结合过渡态驱动、hyperecho）可在基本保持对比的前提下大幅降低能量沉积，代价是略降SNR与轻度模糊。B延长TR直接降低单位时间射频占空比，SAR下降，代价是扫描时间延长。C减少每个TR内的层数等于减少该TR窗口内的射频脉冲总数，SAR下降。D缩短回波链意味着每个TR内重聚焦脉冲更少，SAR下降，代价是采集时间延长、T2模糊减轻但效率降低。", "tr": "本题的核心是“SAR∝α²”这一定量关系。考生易只记住“TSE的SAR高”，却不知道降SAR的第一杠杆是重聚焦翻转角而非TR。另注意：提高接收带宽虽可缩短回波间隔，但会使射频脉冲更密集，对SAR并无帮助。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0113", "t": "单选题", "s": "行磁共振胰胆管成像（MRCP）与上腹部MRI前，通常要求患者禁食4—6 h，其最主要的技术目的是", "o": {"A": "减少胃十二指肠内液体与蠕动造成的高信号干扰及运动伪影，同时使胆囊充盈、胆管生理性扩张，便于重T2权重下显示", "B": "降低射频能量沉积（SAR）", "C": "减小呼吸运动幅度以便屏气", "D": "延长胆汁的T2弛豫时间以提高信噪比", "E": "预防钆对比剂过敏反应"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-013", "kp": "MRCP与上腹部检查前禁食的技术依据", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确。MRCP依靠超长TE的重T2权重使静止或缓慢流动的液体呈显著高信号、实质与流动血液呈低信号。胃与十二指肠内的液体同样是长T2的水，会在最大密度投影（MIP）上叠加于胆总管、胰管之上造成假象；进食后胆囊排空、胆管管径变小也不利显示。禁食4—6 h既减少胃肠液体与蠕动，又保证胆囊充盈。临床上常联合口服含锰的阴性对比剂（如菠萝汁、蓝莓汁）进一步抑制胃肠道液体信号。【为什么错】B禁食与射频功率沉积无关，SAR取决于翻转角、脉冲数与场强。C禁食不改变呼吸幅度，减小呼吸运动靠屏气训练、呼吸门控/触发或导航回波。D胆汁T2值是组织固有属性，不因禁食改变；MRCP靠的是超长TE凸显长T2组织，而非改变T2。E钆剂过敏与禁食无因果关系，预防依靠病史筛查与急救准备。", "tr": "D是很有迷惑性的干扰项——把“利用长T2”误读为“延长T2”。请牢记：技术准备改变的是“信号来源的分布”（哪里有水、有多少水），而不是“组织的弛豫常数”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0114", "t": "案例分析题", "s": "患者男，45岁，身高172 cm，体重102 kg，因腰痛伴右下肢放射痛行腰椎MRI。技师采用后部脊柱相控阵线圈，患者仰卧、双腿伸直，激光定位灯对准剑突下缘后送入磁体等中心。所得矢状面T2WI显示：腰段整体信噪比偏低，L5—S1椎间盘区信号衰减明显、椎管内结构模糊，且相位编码（前后）方向上腹壁脂肪折叠至椎管前方。设备为飞利浦3.0T。下列处理组合最合理的是", "o": {"A": "将定位中心改置于髂嵴连线上方约2—3 cm（相当于L4椎体水平），使感兴趣区居于线圈中心与磁体等中心；在膝下垫楔形垫使腰椎生理前凸变平、腰背部更贴近后部线圈；开启前部体线圈单元行前后联合接收以改善深部SNR；相位编码方向仍取前后但增加过采样（no phase wrap/折叠抑制）或改用饱和带抑制腹壁脂肪", "B": "把定位中心保持在剑突不变，仅提高翻转角以增加信号强度", "C": "将相位编码方向由前后改为上下，并取消过采样", "D": "改用体线圈发射兼接收，可同时解决SNR不足与折叠伪影", "E": "增大FOV至400 mm并把层厚增至8 mm，以覆盖全部腰椎并提高信噪比"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAFE-014", "kp": "线圈选择、摆位与定位中心", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A正确，逐条对应了三个问题。①定位中心错误：腰椎的定位标志是髂嵴连线（约平L4椎体或L4/5间隙），对准剑突会使腰骶段位于线圈敏感区边缘，L5—S1信号衰减正是表面线圈灵敏度随距离迅速下降的表现；同时感兴趣区偏离磁体等中心会加重梯度非线性形变与匀场不良。②肥胖患者腰背部与后部线圈之间距离增大、且腰椎前凸使椎体远离线圈，膝下垫高可使腰椎变平、贴近线圈，是提高SNR最直接的物理手段；有条件时加用前部线圈单元行前后联合接收可显著改善深部信号。③相位编码方向为前后时腹壁在FOV外产生卷褶，处理办法是相位方向过采样（折叠抑制）或对FOV外组织施加空间饱和带。【为什么错】B提高翻转角在自旋回波类序列中受Ernst角与SAR双重限制，且不解决线圈距离与定位中心问题，3.0T下还会引发SAR超限。C腰椎矢状面若把相位方向改为上下，会把上下方向的运动（吞咽、心血管搏动传递、腹主动脉搏动）伪影铺到椎体上，且上下向FOV更长、易在头足方向折叠，得不偿失。D体线圈接收的SNR远低于相控阵表面线圈，是典型的方向性错误。E增大FOV虽可消除折叠但同时降低空间分辨率，8 mm层厚会显著加重部分容积效应，掩盖神经根受压细节，属于以牺牲诊断信息换取表观信噪比。", "tr": "本题三个陷阱叠加：把“定位中心”当成随意可选；把“提高翻转角/增大FOV”当作万能补救；忽视体位（膝下垫高）这一零成本的SNR优化手段。请牢记腰椎定位标志=髂嵴连线（约L4），颈椎=甲状软骨（约C4/5），胸椎=胸骨角向下计数或胸骨中点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0115", "t": "单选题", "s": "在飞利浦3.0T上行颅内动脉3D时间飞跃法磁共振血管成像（3D TOF-MRA）时，为抑制静脉信号、突出动脉，空间预饱和带应设置在", "o": {"A": "成像容积的头侧（上方），随容积同步移动", "B": "成像容积的足侧（下方），随容积同步移动", "C": "成像容积的左右两侧", "D": "成像容积的前方（面部侧）", "E": "无须饱和带，3D TOF本身即不显示静脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-001", "kp": "TOF-MRA饱和带的方位选择", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确。TOF的对比来源是“流入增强”：成像容积内静止组织被反复射频激励而饱和呈低信号，从容积外流入的新鲜未饱和质子呈高信号。因此要抑制哪一支血管，就把预饱和带放在该血管“流入的上游”。颅内动脉血自颈部向上（自足侧向头侧）进入成像容积，静脉血则自颅顶向下经乙状窦、颈内静脉回流（相对成像容积由头侧流入），故抑制静脉的饱和带应置于成像容积的头侧，并设置为随容积同步移动（travelling/walking saturation）。反之，做颈静脉成像（如2D TOF静脉法）时饱和带放在足侧以抑制上行动脉血。【为什么错】B放在足侧会把要显示的动脉血饱和掉，动脉信号丢失。C左右侧饱和带用于抑制侧方来源（如单侧颈动脉），不解决静脉污染。D前方饱和带常用于抑制腹壁运动或眼球运动，与颅内静脉抑制无关。E错误：3D TOF若不加饱和带，硬脑膜静脉窦与皮层静脉常有明显信号残留，尤其在MIP上叠加于动脉之上。", "tr": "口诀：“抑谁，就堵谁的上游”。颅内MRA抑静脉→上方饱和带；颈部静脉成像抑动脉→下方饱和带。切勿死记“饱和带永远在上方”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0116", "t": "多选题", "s": "关于2D与3D时间飞跃法MRA（TOF-MRA）及其改良技术，下列说法正确的有", "o": {"A": "2D TOF逐层薄层激发，每层的流入效应充分，对慢血流敏感、覆盖范围大，适合颈部血管与下肢血管的长段筛查", "B": "3D TOF体素小、SNR与空间分辨率高，是颅内动脉（Willis环）成像的首选，但容积内血液随行程被反复激励易发生饱和，远端小血管显示衰减", "C": "多块重叠薄层采集（MOTSA/滑动块）通过若干互相重叠的薄容积拼接，兼顾覆盖范围与流入效应，但可产生块与块交界处信号阶梯，即“百叶窗（venetian blind）”伪影", "D": "倾斜优化非饱和激励（TONE，即斜坡脉冲）沿血流流入方向逐渐增大射频翻转角，用以补偿血液进入容积深部后的饱和效应，改善远端动脉显示", "E": "磁化传递（MTC）预脉冲通过抑制血液内自由水的信号来提高血管与背景的对比"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-002", "kp": "2D/3D TOF及MOTSA、TONE、MTC", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确：2D TOF单层厚度大但每层独立激发，血液进入每一层时都是“新鲜”的，故对慢血流敏感，适合颈动脉/下肢等长范围、流速较低的血管。B正确：3D TOF的优势是各向同性高分辨与高SNR，劣势是容积内饱和，故对Willis环近端显示优异、对远端分支与慢血流（如动脉瘤内涡流、烟雾病侧支）显示受限。C正确：MOTSA是2D覆盖能力与3D分辨率的折中，块间由于流入效应不均产生周期性亮暗条带，即百叶窗伪影，通过增大块间重叠比例（常20%—30%）可减轻。D正确：TONE把容积入口侧翻转角设小、出口侧设大，使先进入的血液少消耗纵向磁化、后段血液获得更强激励，从而拉平沿程信号衰减。【为什么错】E错误：MTC的机制说反了。MTC通过偏共振射频脉冲饱和大分子（蛋白、膜脂）结合水质子池，经交换使脑实质等含大分子丰富的背景组织信号下降；而流动血液内自由水与大分子交换少，信号基本不受影响，从而提高血管/背景对比。MTC抑制的是背景，不是血液。", "tr": "E是本题的核心陷阱——MTC“抑背景不抑血”。此外要注意MTC会显著增加SAR，3.0T上常需与低翻转角、并行采集联合使用；MTC还会削弱增强后小病灶的对比，不宜与增强扫描随意叠加。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0117", "t": "单选题", "s": "行颅内静脉窦相位对比法磁共振血管成像（PC-MRA）时，技师沿用了动脉的编码流速VENC＝80 cm/s，结果静脉窦显示暗淡、信噪比很差；改为VENC＝15 cm/s后静脉窦显示良好，但上矢状窦中心区出现与实际血流方向相反的黑白反转。对这两次结果的正确解释是", "o": {"A": "VENC过高时相位位移过小、流速噪声相对增大导致血管信号弱；VENC过低时超过VENC的流速发生相位混叠（aliasing），表现为高流速区流向反转", "B": "VENC过高会导致相位混叠，VENC过低会降低信噪比，两次现象顺序应互换", "C": "两种现象均由静脉窦内血栓造成，与VENC无关", "D": "VENC只影响图像亮度，不影响相位方向的正确性", "E": "应把VENC设为0以获得最佳静脉显示"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-003", "kp": "PC-MRA的VENC设置与相位混叠", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确。PC-MRA用一对双极梯度对运动质子施加与速度成正比的相位位移，VENC定义为产生±180°相位位移所对应的流速。VENC设得过高，实际流速产生的相位角很小，信号被相位噪声淹没，血管显示暗淡、SNR差；VENC设得过低，超过VENC的流速其相位超过±180°而发生卷绕（混叠），在相位图上表现为高流速中心区域的信号极性反转（黑白倒置），流量定量结果也随之错误。经验做法是把VENC设为预期峰值流速的1.1—1.5倍：颅内动脉常用60—80 cm/s，静脉窦常用15—25 cm/s，脑脊液流动定量常用5—10 cm/s。【为什么错】B把两种现象完全说反。C静脉窦血栓表现为充盈缺损与信号缺失，不会随VENC改变而呈现这种规律性变化，且两次扫描解剖表现不一致已排除固定病变。D错误：相位方向的正确性正是由VENC决定的，混叠本质上就是相位方向的错误编码。E错误：VENC不能为0，为0意味着不施加流速编码，无法产生任何血流对比。", "tr": "口诀：VENC偏高丢信号（噪声大、显示淡），VENC偏低出混叠（流向反转、流量算错）。多数考生只记住“混叠”而记反了方向。临床上遇到混叠也可先扩大VENC重扫，或使用双VENC/相位解卷绕算法。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0118", "t": "多选题", "s": "关于相位对比法MRA（PC-MRA）的技术特点，下列说法正确的有", "o": {"A": "其对比机制是流动质子在双极流速编码梯度作用下产生与流速成正比的相位差，静止组织相位差为零而被减影去除", "B": "既可输出反映血管形态的幅值（magnitude）图，也可输出可用于流速、流量定量的相位（phase）图", "C": "背景抑制优于TOF，对慢血流（如静脉窦、脑脊液搏动）敏感，可用于导水管脑脊液流量测定以评估正常压力脑积水", "D": "三维PC-MRA需要在三个正交方向分别施加流速编码，采集时间明显长于同等分辨率的3D TOF", "E": "PC-MRA不受VENC设置影响，任何流速均可准确成像，因此可完全取代CE-MRA"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-004", "kp": "PC-MRA原理与临床定位", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确：双极梯度对静止自旋的净相位为零、对运动自旋产生净相位，两次相反极性编码相减即得纯血流信号，这也是PC背景抑制极佳的原因。B正确：幅值图看形态，相位图（速度图）可逐像素读出流速，进而通过管腔面积积分得到流量（mL/s或mL/心动周期）。C正确：PC对慢流敏感且无饱和效应，是中脑导水管脑脊液流速/每搏流量测定的标准方法，用于正常压力脑积水评估与分流术前后对比。D正确：3D PC需在x、y、z三方向各做一次流速编码（加参考采集共4次），采集时间成倍增加，这是其临床普及度低于TOF与CE-MRA的主要原因。【为什么错】E错误：PC-MRA对VENC高度依赖，VENC不当会造成信噪比下降或相位混叠；且其扫描时间长、对湍流敏感，大范围血管（主动脉、外周动脉）仍以CE-MRA为首选，PC不能取代CE-MRA。", "tr": "E中“不受VENC影响”与“完全取代”双重绝对化。要牢记三种MRA的定位：TOF看颅内动脉形态；PC做血流定量与慢流评估；CE-MRA做大范围、大血管、高流速与狭窄程度评估。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0119", "t": "单选题", "s": "对比增强MRA（CE-MRA）中，为使动脉期图像不受静脉污染，采集时机与K空间填充方式的关系应为", "o": {"A": "采用K空间中心优先（centric/elliptic centric）填充，并使K空间中心的采集时刻恰好落在靶血管团注峰值期", "B": "采用K空间顺序（linear）填充，把K空间中心放在采集末段以获得最高信噪比", "C": "K空间填充顺序与静脉污染无关，只需缩短对比剂注射时间", "D": "把K空间中心放在采集起始的第一秒，无论对比剂是否到达", "E": "只要使用高浓度钆剂，任何填充顺序都不会出现静脉污染"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-005", "kp": "CE-MRA的团注时相与K空间中心填充", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确。K空间中心决定图像的对比度与整体信号强度，边缘决定细节与边界锐利度。因此CE-MRA的核心技术要求是让K空间中心的数据在靶动脉内钆浓度最高的瞬间被采集——即“峰值对峰值”。中心优先（椭圆中心）填充把中心数据放在采集最开始，配合团注测试（test bolus）或透视触发（BolusTrak/CARE Bolus/SmartPrep）确定触发延迟，可在静脉尚未回流时锁定动脉期对比度。【为什么错】B线性填充把中心放在采集中段，若采集窗较长，中心采集时刻可能已进入静脉期，导致静脉重叠；线性填充多用于时间分辨率不敏感或首过时间窗充裕的部位。C错误：静脉污染的本质是“K空间中心采集时刻晚于动脉峰、进入静脉期”，与填充顺序直接相关；缩短注射时间虽可缩窄动脉窗，但若时相不匹配反而更易失败。D错误：中心提前到对比剂尚未到达时采集，会造成动脉信号极弱甚至完全无强化（所谓“环状伪影”或Maki伪影，因中心期浓度快速变化引起）。E错误：钆浓度不能改变循环时间，静脉回流是生理过程，与浓度无关。", "tr": "两个方向的失败要分清：中心采集过早→动脉信号弱、边缘模糊、可出现Maki（环晕）伪影；中心采集过晚→静脉污染。此外，团注时长应大致等于或略长于采集时间窗，并常规用生理盐水20 mL同速率冲管以维持团注紧凑度。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0120", "t": "案例分析题", "s": "患者男，66岁，高血压30年，拟诊胸腹主动脉夹层，行CE-MRA。设备为飞利浦3.0T，18G留置针置于右肘正中静脉，高压注射器以2.5 mL/s注入钆剂20 mL＋生理盐水20 mL。技师使用固定延迟18 s触发采集，K空间采用线性填充，采集时间22 s、屏气完成。所得图像：主动脉腔内信号中等，下腔静脉与肾静脉明显强化并与腹主动脉重叠，MIP上难以判断真假腔关系。下一次复查最合理的技术改进是", "o": {"A": "改用透视触发（实时监测降主动脉内信号，见对比剂到达即嘱屏气并启动采集），K空间改为椭圆中心填充；必要时先做团注测试测得个体循环时间；同时可加做时间分辨（4D）CE-MRA以捕捉多个时相", "B": "把固定延迟从18 s缩短到8 s，其余不变", "C": "把钆剂总量增加到40 mL，注射速率降至1 mL/s以延长强化平台", "D": "改为非对比增强MRA（TOF）替代CE-MRA，可完全避免静脉污染", "E": "把采集时间延长到45 s并改自由呼吸，以提高信噪比"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-006", "kp": "CE-MRA静脉污染的原因分析与对策", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确。本例的根本问题是“时相不匹配”：固定延迟无法适应个体循环时间（心衰、夹层、主动脉瘤者循环显著延长或缩短），线性填充又把K空间中心推到采集中段（约第11 s），叠加后中心数据落在静脉期，故出现静脉污染而动脉对比不足。改进逻辑有三层：①用透视触发或团注测试获得个体化触发时刻；②改椭圆中心填充使对比度数据在动脉峰值瞬间采集；③夹层需要观察真假腔血流充盈的时间差，加做时间分辨4D CE-MRA（联合并行采集与压缩感知可达每帧2—4 s）能提供动态信息，比单时相更有价值。【为什么错】B单纯缩短固定延迟仍是“盲猜”，且线性填充的中心时刻问题未解决，重复失败概率高。C增加钆剂总量既提高不良反应与肾源性系统性纤维化风险，又因注射速率降低使团注被稀释、峰值浓度下降、动脉期变得平坦而更易被静脉重叠，方向错误。D错误：胸腹主动脉范围长、血流方向复杂且存在层流/涡流，TOF在此处饱和效应严重、易高估狭窄，根本无法替代CE-MRA；若确需无对比剂方案，应选心电门控的三维快速自旋回波类非增强MRA（TRANCE/NATIVE SPACE/Inhance）。E延长采集与自由呼吸只会引入更多呼吸运动伪影，且更深地进入静脉期，问题加重。", "tr": "考生常把静脉污染归咎于“对比剂太多”，实则关键是“K空间中心的采集时刻”。另一个易错点是把非增强MRA的技术选型搞混：躯干大血管的非增强方案是心电门控3D TSE（收缩期—舒张期减影），不是TOF。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0121", "t": "多选题", "s": "关于非对比增强MRA（飞利浦TRANCE、西门子NATIVE、GE Inhance等）的技术原理与适用情形，下列说法正确的有", "o": {"A": "其中一类基于心电门控的三维快速自旋回波（TSE/FSE）技术，利用收缩期动脉血因高速流动而信号丢失、舒张期动脉血信号恢复的差异，将两期图像相减获得纯动脉像", "B": "另一类基于平衡稳态自由进动（bTFE/TrueFISP/FIESTA）并结合反转恢复或空间选择性标记，利用血液长T2/T1比值高的固有对比显示血管，常用于肾动脉与冠状动脉", "C": "对肾功能不全（eGFR明显降低）而不宜使用钆剂的患者，是重要的替代方案", "D": "心电门控依赖稳定心律，严重心律不齐者收缩期与舒张期采集时相错乱，减影失败风险高", "E": "非对比增强MRA的空间分辨率与扫描速度均优于CE-MRA，已在各部位全面取代后者"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-007", "kp": "非对比增强MRA技术分类与适应人群", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A正确：这是下肢与外周动脉最常用的减影型非增强MRA原理，收缩期高速血流在长回波链TSE中因流空而呈低信号，舒张期血流缓慢呈高信号，两者相减即得动脉图，静脉因全程流速低而在两期均为高信号被减掉。B正确：bTFE的信号强度取决于T2/T1，血液T2/T1比值高故呈亮信号；配合非选择性反转＋选择性反转（如空间标记反转）可抑制背景与静脉，广泛用于肾动脉、门静脉与全心冠脉成像。C正确：这正是非增强MRA复兴的主要临床驱动力——避免钆剂在重度肾功能不全患者中的肾源性系统性纤维化风险。D正确：门控稳定性是减影型技术的命门，房颤或频发早搏时两期采集的心动时相漂移，减影残留严重。【为什么错】E错误：非增强MRA采集时间通常长于CE-MRA（需多心动周期采集与减影），对运动与心律更敏感，在大范围血管与复杂病变的整体可靠性仍不及CE-MRA，谈不上“全面取代”。", "tr": "E的“全面取代”是典型绝对化陷阱。要点：非增强MRA是“对特定人群、特定部位的替代”，不是“普适升级”。另注意区分同名不同义：Inhance既包含流入反转恢复（IFIR）也包含减影型技术，答题时以原理描述为准而非商品名。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0122", "t": "单选题", "s": "与3D TOF-MRA相比，CE-MRA最本质的成像对比来源是", "o": {"A": "血液流入未饱和质子产生的流入增强效应", "B": "钆剂缩短血液T1使其在超短TR的扰相梯度回波（T1-FFE/FLASH/SPGR）上呈高信号，对比几乎不依赖血流速度与方向", "C": "流动质子的相位位移", "D": "血液与背景之间T2差异的放大", "E": "磁化传递效应对背景组织的抑制"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRA-008", "kp": "CE-MRA的对比机制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】B正确。CE-MRA属于T1对比技术：团注钆剂后血液T1可由约1200 ms（3.0T）骤降至100 ms以下，在TR极短（3—5 ms）、翻转角25°—40°的三维扰相梯度回波序列中，血液纵向磁化恢复远快于背景组织而呈显著高信号。由于对比来源是“血液本身的T1”，它基本不依赖血流速度、方向与层面关系，因而不会出现TOF那样的面内流动饱和与湍流失相位所致的狭窄高估。【为什么错】A是TOF的机制。C是PC的机制。D错误：CE-MRA采用极短TE（1—2 ms）以最大限度减少T2*失相位，其对比与T2差异无关。E MTC是TOF常用的背景抑制辅助手段，不是CE-MRA的对比来源，反而因增加SAR与降低强化对比一般不与CE-MRA叠加。", "tr": "记住三条主线：TOF＝流入效应（T1效应＋流动）、PC＝相位差、CE＝钆剂缩短T1。也正因为CE不依赖流动，它在血流缓慢的重度狭窄远段、动脉瘤囊内、迂曲血管中显示更真实。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0123", "t": "单选题", "s": "MR水成像（如MRCP、MRU）能使胆汁、尿液等静止液体呈显著高信号而实质器官与流动血液呈低信号，其技术核心是", "o": {"A": "采用超长TE（常600—1200 ms）的重T2权重序列，长T2的静止液体信号残留而短T2组织信号已衰减殆尽", "B": "采用超短TR的T1权重序列使液体呈高信号", "C": "依赖静脉注射钆剂使液体强化", "D": "利用液体的高质子密度形成对比，与TE无关", "E": "通过脂肪抑制使液体相对变亮"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-001", "kp": "MR水成像的重T2权重原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确。胆汁、尿液、脑脊液、内耳外淋巴液的T2值可达数百至上千毫秒，而肝、胰、肌肉等实质组织T2仅数十毫秒。把TE延长至数百毫秒以上时，实质组织的横向磁化已基本衰减为零，只有长T2液体仍有可观残留，从而形成“水亮、其余全黑”的类造影效果。流动血液则因流空效应呈低信号，进一步净化背景。【为什么错】B错误：T1权重下液体是低信号，方向完全相反。C错误：MR水成像是无创、不用对比剂的技术，这正是其相对ERCP与静脉尿路造影的最大优势；只有排泄性MRU才使用钆剂。D错误：质子密度差异远不足以形成如此强的对比，TE恰恰是决定性参数。E错误：脂肪抑制只是抑制脂肪的高信号背景（常规联用以提高MIP质量），并不能让实质组织变黑，不是核心机制。", "tr": "常见误区是把水成像等同于“T2WI加脂肪抑制”。区别在于TE的量级：常规T2WI的TE约80—100 ms，水成像的有效TE要长一个量级。若TE不够长，胰腺、十二指肠壁等中等T2组织会残留信号污染MIP图像。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0124", "t": "多选题", "s": "关于MRCP两类主要采集方式的比较，下列说法正确的有", "o": {"A": "屏气二维厚层块单次激发TSE（SSh-TSE/HASTE/SSFSE）一次激发即得一幅投影像，扫描仅数秒，适合屏气差或急诊患者的快速筛查", "B": "呼吸触发（导航回波或呼吸带）的三维高分辨TSE可获得各向同性薄层数据，能行MIP与曲面重组，对胆管细微狭窄、胰管分支的显示优于二维厚层", "C": "三维MRCP常联合脂肪抑制（SPIR/SPAIR）以降低腹膜后脂肪高信号对MIP的干扰", "D": "二维厚层块因层厚大（常30—80 mm），小结石可能被部分容积效应掩盖，故不能单独作为诊断依据，需与薄层或三维图像结合", "E": "三维呼吸触发MRCP因采集时间长，应嘱患者尽量深大呼吸以缩短触发间隔"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-002", "kp": "MRCP屏气二维与呼吸触发三维的取舍", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确：单次激发在一个TR内用长回波链填满整个K空间，2—4 s即可完成一幅厚层投影，是不能配合者的救命方案，还可多角度旋转采集获得类ERCP观。B正确：3D TSE配合可变翻转角长回波链与呼吸导航，可获得约1 mm等体素数据，是显示胆管解剖变异、胰腺分裂、细小狭窄的主力序列。C正确：脂肪在重T2权重下仍有一定信号，MIP时会形成弥漫背景雾化，脂肪抑制可显著提升胆胰管的对比。D正确：厚层块是投影像，缺乏层面信息，直径2—3 mm的结石可被周围高信号胆汁淹没，必须结合薄层轴位T2WI与三维图像判读。【为什么错】E错误：呼吸触发依赖规律、平稳、幅度一致的呼吸；深大呼吸会使膈肌位移幅度增大、触发窗漂移，导致图像模糊与采集效率下降。正确指导是“平静、均匀、浅而规律地呼吸”，并在扫描前进行呼吸训练。", "tr": "E利用了“想快点做完”的直觉。呼吸触发/导航技术追求的是呼吸的一致性而非频率；导航回波接受窗通常设在呼气末（膈肌位置最稳定），门控效率若低于40%应重新训练患者或改屏气方案。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0125", "t": "单选题", "s": "患者女，62岁，右侧腰痛伴血肌酐升高（eGFR 28 mL/min/1.73m²），超声提示右肾积水，需明确梗阻部位。最恰当的MR尿路成像方案是", "o": {"A": "静水法MRU（重T2权重的呼吸触发三维TSE＋厚层单次激发投影），利用积聚的尿液自身长T2成像，不使用钆剂", "B": "排泄性MRU：静脉注射钆剂后行三维T1加权采集，观察对比剂经肾排泄充盈尿路", "C": "注射钆剂后加用利尿剂以加速排泄，提高尿路显示", "D": "行CE-MRA观察肾动脉，间接推断梗阻部位", "E": "行DWI高b值成像替代MRU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-003", "kp": "静水法MRU与排泄性MRU的选择", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确。静水法（静态液体）MRU属重T2权重水成像，不依赖肾功能、不需对比剂，只要尿路内有积聚的尿液即可显示，对已扩张的梗阻性尿路显示最佳，恰好适用于本例eGFR明显降低而不宜使用钆剂的患者。技术上常采用呼吸触发3D TSE获得薄层数据加MIP，并辅以厚层单次激发投影快速观察全貌。【为什么错】B排泄性MRU依赖肾脏浓缩与排泄功能，eGFR 28时排泄延迟、对比剂浓度低，显示效果差；更重要的是重度肾功能不全使用钆剂存在肾源性系统性纤维化风险，属应回避的方案。C在B的基础上叠加利尿剂，既未解决钆剂禁忌，又可能加重脱水与电解质紊乱。D肾动脉成像无法回答“梗阻部位在哪一段尿路”这一临床问题，且同样需要钆剂。E DWI可提示肾实质与病灶信息，但不能连续显示尿路走行与梗阻端形态，不能替代MRU。", "tr": "关键分水岭是肾功能：肾功能良好且尿路不扩张（如需评价功能或非梗阻性病变）可选排泄性MRU；肾功能不全或已有明显积水优先静水法。切记重度肾功能不全者尽量避免钆剂，必须使用时选大环状制剂并用最低剂量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0126", "t": "案例分析题", "s": "患者女，34岁，右耳渐进性听力下降伴耳鸣3个月，纯音测听示右侧感音神经性聋，临床怀疑内听道内小听神经瘤（可能仅2—3 mm）。设备为飞利浦3.0T，配备8通道头线圈与压缩感知加速。为在最短时间内获得最可靠的内耳与内听道评估，下列扫描方案最合理的是", "o": {"A": "采集三维重T2权重高分辨水成像（3D bTFE/DRIVE/CISS/FIESTA-C类），层厚≤0.6 mm、各向同性体素、FOV小视野聚焦于双侧桥小脑角与内听道，在高信号脑脊液衬托下观察面听神经四条神经束是否有充盈缺损；再补充三维T1增强薄层以判断强化", "B": "仅采集常规轴位T2WI TSE，层厚5 mm，即可满足诊断", "C": "采用二维时间飞跃法MRA观察迷路动脉走行以间接判断", "D": "行内听道DWI高b值成像作为主要序列", "E": "行1H-MRS测定桥小脑角区代谢物以定性"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-004", "kp": "内耳水成像技术要点", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确。内耳水成像的技术要点是“三高一小”：高分辨（亚毫米各向同性）、高T2权重（膜迷路内淋巴液与内听道脑脊液呈极高信号）、高信噪比（小FOV＋薄层＋多次平均或压缩感知补偿），小视野聚焦以提高空间分辨率。在明亮的脑脊液背景中，面神经、蜗神经、前庭上/下神经呈四条低信号束，微小肿瘤表现为神经束增粗或脑脊液内的充盈缺损，敏感性远高于常规厚层T2WI。三维T1增强薄层用于确认强化并与蛛网膜囊肿、血管袢等鉴别。需注意bTFE类序列对磁场不均匀敏感，3.0T下须精细匀场，必要时改用三维TSE类水成像（VISTA/SPACE/CUBE）以减轻带状伪影。【为什么错】B层厚5 mm对2—3 mm病灶存在严重部分容积效应，极易漏诊，是临床上小听神经瘤漏诊的典型原因。C迷路动脉直径远小于MRA的分辨能力，且血管走行不能推断神经受累。D内听道区域体积小、邻近颞骨气房，EPI-DWI变形与磁敏感伪影严重，DWI在此处主要用于鉴别胆脂瘤而非检出微小听神经瘤。E MRS需要足够大的体素（通常≥1 cm³）与良好匀场，桥小脑角区紧邻颅骨与气房，既无法满足体素要求也无法匀场，属于超出技术适用范围的选择。", "tr": "陷阱在于把“内耳水成像”与“常规颅脑T2WI”混淆。副高层面要能说出参数级要求：亚毫米各向同性、小FOV、高T2权重；并能指出bTFE在3.0T的带状（banding）伪影风险及其替代方案（3D TSE类水成像）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0127", "t": "单选题", "s": "MR脊髓成像（MR myelography，MRM）主要显示的结构是", "o": {"A": "蛛网膜下腔内脑脊液及其被硬膜囊、神经根鞘勾勒出的轮廓，从而间接显示压迫与神经根袖形态", "B": "脊髓内部灰白质分界", "C": "椎体骨髓信号变化", "D": "椎旁静脉丛", "E": "椎间盘髓核的含水量定量"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HYDR-005", "kp": "MR脊髓成像的显示对象", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A正确。MRM属水成像家族，用重T2权重序列（多为屏气或呼吸触发的单次激发TSE厚层块，或3D TSE薄层重建）使脑脊液呈极高信号、其余结构呈低信号，形成类似X线脊髓造影的效果。它显示的是脑脊液柱的外形：椎间盘突出压迫处呈弧形压迹，神经根袖显示为对称的“袖套”，臂丛/腰骶丛神经根撕脱可见假性脊膜膨出。其最大优势是无创、无须鞘内注射对比剂。【为什么错】B脊髓灰白质分界需高分辨T2WI或质子密度加权轴位显示，MRM把髓内信息完全淹没在低信号中。C骨髓评估依赖T1WI与脂肪抑制T2WI/STIR。D椎旁静脉丛显示需要增强T1WI或血管序列。E椎间盘含水量定量属于T2 mapping等定量技术范畴，与MRM无关。", "tr": "MRM是“看脑脊液的外形”，不是“看脊髓的内部”。因此它绝不能替代常规矢状/轴位T2WI——临床上必须两者结合，单独MRM会漏诊脊髓内病变（如脱髓鞘、髓内肿瘤、脊髓空洞）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0128", "t": "单选题", "s": "关于DWI的b值选择与表观扩散系数（ADC）计算，下列说法正确的是", "o": {"A": "ADC由至少两个不同b值的信号按单指数模型 S(b)=S₀·exp(−b·ADC) 拟合得到，b值间隔越大拟合越稳定，但高b值图像的SNR随之下降", "B": "只用一个b值即可直接计算ADC", "C": "b值越高ADC值越大，故报告ADC时无须注明b值组合", "D": "ADC图上信号越亮表示扩散越受限", "E": "b＝0图像即为纯扩散图像"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-001", "kp": "b值选择与ADC计算", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。单指数模型下，两点法ADC＝ln(S₁/S₂)/(b₂−b₁)。b值差越大，分母越大、测量噪声被放大的程度越小，因此拟合更稳定；但b值升高时信号按指数衰减，高b值图像SNR急剧下降，噪声本底又会使ADC被系统性低估。颅脑常规采用b＝0与1000 s/mm²，腹部常用0、50（或100）与800 s/mm²（用低b＝50抑制血流灌注的伪扩散贡献），前列腺常加采b≥1400 s/mm²。【为什么错】B单点无法确定指数衰减的斜率，必须至少两点。C恰好说反：b值升高时，由于灌注成分与非高斯扩散的影响，实测ADC通常降低而非升高；也正因ADC依赖所用b值组合，报告与随访必须固定并注明b值。D错误：ADC图上扩散受限表现为低信号（暗），DWI高信号＋ADC低信号才是真扩散受限；DWI高＋ADC也高提示T2透过效应。E错误：b＝0图像不含扩散权重，本质是T2权重的EPI图像，是计算ADC的参考基线，不是扩散图。", "tr": "两个高频陷阱：①ADC图的信号方向（暗＝受限）；②b值组合不同则ADC不可直接比较，这是随访与多中心研究中最常见的方法学错误。另注意噪声本底对高b值ADC的系统性低估，可用去噪或对数域加权拟合缓解。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0129", "t": "多选题", "s": "关于DWI在不同疾病中的应用价值，下列说法正确的有", "o": {"A": "超急性期脑梗死细胞毒性水肿使细胞外间隙缩小，发病数分钟至数十分钟即可表现为DWI高信号、ADC降低，早于CT与常规T2WI", "B": "脑脓肿腔内含黏稠脓液、大量炎性细胞与蛋白，扩散明显受限呈DWI高信号、ADC降低；囊变坏死的肿瘤多为清亮液体，DWI低信号、ADC升高", "C": "中耳胆脂瘤的角化鳞状上皮碎屑扩散受限，非EPI-DWI（如TSE-DWI/HASTE-DWI）因磁敏感伪影小，比EPI-DWI更适合颞骨区检出与术后复发监测", "D": "急性期脑梗死的ADC值随时间演变，在约7—10天后可因血管源性水肿与细胞溶解出现“假正常化”，此时ADC回升至接近正常，仅凭ADC可能低估病灶", "E": "表皮样囊肿与蛛网膜囊肿在DWI上表现一致，DWI对二者鉴别无价值"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-002", "kp": "DWI的临床应用与陷阱", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确：这是急诊卒中流程把DWI置于首位的根本原因。B正确：这是脓肿与囊变肿瘤最重要的影像鉴别点，术前判断价值极高。C正确：颞骨区气—骨界面多，EPI-DWI几何变形与磁敏感伪影严重，且层厚大；非EPI的TSE类DWI（如HASTE-DWI）虽扫描时间长，但变形小、可薄层，是国际公认的胆脂瘤检出与随访方法，可减少不必要的二次探查手术。D正确：ADC假正常化通常出现在发病后约7—10天，此期ADC回升，若仅看ADC可能误判为无病灶，需结合FLAIR/T2WI与临床时间窗综合判断。【为什么错】E错误：DWI恰恰是二者鉴别的关键——表皮样囊肿内为角化物与胆固醇结晶，扩散受限呈DWI显著高信号；蛛网膜囊肿内为脑脊液，DWI低信号、ADC与脑脊液一致。二者在T1WI/T2WI上信号相近，正是DWI解决了这一经典难题。", "tr": "E是DWI最经典的教学考点却常被写成“无价值”这类反向陷阱。D的“假正常化”是时间维度陷阱，考生易只记“梗死＝ADC低”。C的非EPI-DWI是操作层面高频考点，务必记住其存在理由是“减少磁敏感变形”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0130", "t": "单选题", "s": "3.0T单次激发EPI-DWI在颅底、颞叶前部与额叶眶回附近出现明显的几何变形与信号堆积/丢失。下列关于其成因与校正措施的叙述，正确的是", "o": {"A": "变形主要源于EPI在相位编码方向上等效带宽极低，使磁场不均匀（气—骨界面磁化率差异）引起的频率偏移被放大为像素移位；提高并行采集因子、增大回波间隔带宽、缩短回波链、采用多次激发/读出分段EPI，以及采集相反相位编码极性（blip-up/blip-down）作场图校正，均可减轻变形", "B": "变形主要来自读出方向带宽不足，只需增大读出带宽即可完全消除", "C": "变形是由梯度非线性引起的，与磁化率无关", "D": "增加平均次数（NSA）即可校正几何变形", "E": "把b值从1000提高到2000 s/mm² 可减轻变形"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-003", "kp": "EPI几何变形的机制与失真校正", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。单次激发EPI在读出方向带宽很高（每个回波仅数百微秒），但在相位编码方向上，整条回波链耗时数十毫秒，等效每像素带宽仅几到几十赫兹，因此极小的频率偏移就会造成大幅像素位移，表现为颅底、鼻窦与颞骨旁的拉伸、压缩与信号堆积。有效对策：①缩短有效回波链——提高并行采集加速因子（SENSE/GRAPPA）或采用多次激发/读出分段EPI（RESOLVE类），直接提高相位方向等效带宽；②缩短回波间隔（提高读出带宽、加大梯度性能）；③基于场图或相反相位编码极性（blip-up/blip-down，即TOPUP类方法）的失真校正；④精细高阶匀场与局部匀场。【为什么错】B读出方向本身带宽已很高，变形主要不在该方向；单纯增大读出带宽只能略微缩短回波间隔，无法“完全消除”。C梯度非线性造成的是整体几何畸变（尤其大FOV边缘），与局部气—骨界面处的定向位移特征不符；EPI变形的主因是磁化率导致的B₀不均匀。D增加平均次数只提高SNR，对系统性几何位移毫无作用，甚至会因多次采集叠加而模糊。E提高b值会降低SNR，且不改变相位方向带宽，对变形无益。", "tr": "核心结论是“EPI变形发生在相位编码方向，与该方向的等效带宽成反比”。因此凡是能缩短单次读出链的手段都有效。考生常误答“增大读出带宽”或“增加NSA”，前者作用有限、后者完全无效。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0131", "t": "案例分析题", "s": "患者男，71岁，突发左侧肢体无力伴言语含糊，家属述“早上6:30醒来即发现异常，入睡前23:00一切正常”，到院时间08:10，NIHSS 12分。急诊CT平扫未见出血。神经内科希望通过MRI判断是否仍在可干预时间窗内并评估血管情况。设备为飞利浦3.0T（具备压缩感知，无深度学习重建）。最合理的急诊一站式MR方案是", "o": {"A": "DWI（含ADC）＋T2-FLAIR＋磁敏感加权成像（SWI）＋3D TOF-MRA＋灌注（DSC或ASL），总时长控制在10—15 min；重点判读DWI-FLAIR不匹配（DWI高信号而FLAIR尚无相应高信号提示发病<4.5 h）以及灌注—扩散不匹配的缺血半暗带", "B": "先做全套常规颅脑序列（T1WI、T2WI、T2-FLAIR、矢状位T1WI）再考虑功能序列", "C": "只做3D TOF-MRA，明确大血管闭塞即可", "D": "只做DWI，其余序列在溶栓后补做", "E": "先做1H-MRS判断缺血代谢改变，再决定是否行DWI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-004", "kp": "醒后卒中的急诊MR一站式方案", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。本例是典型的“醒后卒中/发病时间不明”，临床决策依赖影像替代时间窗。规范的急诊一站式组合各司其职：DWI确认梗死核心并定位；T2-FLAIR与DWI比对形成DWI-FLAIR不匹配——DWI已高信号而FLAIR尚未出现对应高信号，提示发病多在4.5 h内，可据此考虑静脉溶栓；SWI排查微出血与检出血管内血栓的磁敏感易感征（susceptibility vessel sign）；TOF-MRA明确有无大血管闭塞以决定取栓；灌注成像（DSC或ASL）评估低灌注范围与核心的不匹配，界定可挽救组织。总时长必须严格控制，通常10—15 min，可借助压缩感知与并行采集压缩3D序列时间。【为什么错】B急诊卒中流程严禁把常规序列排在前面，浪费的每分钟约损失190万个神经元，且T1WI等对超急性期几乎无贡献。C仅有血管信息而无组织学信息，无法判断核心大小与是否已大面积梗死，取栓决策同样需要核心体积。D仅DWI不能判断时间窗、不能排查微出血、不能评估血管与半暗带，信息严重不足。E MRS采集耗时长、需良好匀场，在急诊卒中中无实际决策价值，属明显的技术选型错误。", "tr": "考点在“为什么是这几条序列”而非“做得越全越好”。要记住每条序列对应的临床问题：DWI＝核心，FLAIR＝时间窗，SWI＝出血与血栓，MRA＝闭塞部位，PWI＝半暗带。另注意DWI-FLAIR不匹配的判断需在同层同窗宽下比对，避免窗技术造成的误判。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0132", "t": "单选题", "s": "体素内不相干运动成像（IVIM）与常规单指数DWI相比，下列叙述错误的是", "o": {"A": "IVIM采用多个b值（通常包含多个b<200 s/mm² 的低b值）按双指数模型拟合，可分离出反映毛细血管网微循环灌注的伪扩散系数D*与灌注分数f，以及反映真实分子扩散的D值", "B": "IVIM只需采集两个b值，通过双指数模型即可分解出D、D*与f", "C": "IVIM无须静脉注射钆剂即可获得反映微循环灌注的信息", "D": "去除灌注贡献后的真扩散系数D通常小于同部位的常规ADC", "E": "IVIM可用于肝纤维化分级、肝细胞癌疗效评估等腹部场景"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-005", "kp": "IVIM的双指数模型与参数含义", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】本题为反选题，B错误。IVIM恰恰需要密集采样多个b值（常10—16个，其中低b值段0—200 s/mm² 要足够密集），因为灌注相关的伪扩散D*衰减极快，只在低b段可见；仅用两个b值根本无法完成双指数分解，也就得不到D、D*、f三个参数。【为什么错】A正确描述了IVIM的核心模型：S(b)/S₀＝f·exp(−b·D*)＋(1−f)·exp(−b·D)，其中D*量级约为D的10倍以上，f为灌注分数。C正确：IVIM是无对比剂的灌注评估方法，这正是其相对DSC灌注的最大优势，尤其适用于肾功能不全者。D正确：常规ADC同时包含了灌注贡献而被抬高，去除灌注成分后的真扩散D通常小于ADC。E正确：IVIM在肝纤维化分级、肝细胞癌治疗反应评估、胰腺与前列腺病变中均有应用，并不局限于脑。", "tr": "本题为反选题（选错误项），先看清题干要求。记住D、D*、f的量级关系：D约0.5—2.0×10⁻³ mm²/s，D*约为D的10倍以上，f为百分数。腹部IVIM受呼吸运动与SNR限制，拟合稳定性有限，低b值采样密度是成败关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0133", "t": "单选题", "s": "扩散峰度成像（DKI）相对于常规DWI/DTI的核心假设改变是", "o": {"A": "承认生物组织内水分子扩散呈非高斯分布，用峰度参数（如平均峰度MK）描述偏离高斯的程度，因而需要更高b值（常含b＝2000 s/mm² 或更高）与至少三个b值", "B": "假设水分子扩散完全符合高斯分布，仅提高了空间分辨率", "C": "取消了扩散敏感梯度，改用相位编码检测扩散", "D": "只需b＝0与b＝1000两个b值即可计算峰度", "E": "峰度参数与组织微结构复杂程度无关"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-006", "kp": "扩散峰度成像（DKI）的基本假设", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。常规DWI/DTI建立在自由扩散（高斯分布）假设上，信号随b值单指数衰减；但真实组织中细胞膜、髓鞘、细胞器等障碍使扩散偏离高斯，在高b值段衰减曲线明显上翘。DKI在指数项中加入峰度校正项 ln S(b)＝ln S₀−b·D_app＋(1/6)·b²·D_app²·K_app，因此必须采集至少三个b值（典型0、1000、2000 s/mm²）与足够的扩散方向（常≥15个）才能稳定拟合，MK值升高提示微结构复杂度增加。【为什么错】B错误：DKI恰恰是放弃高斯假设，且它并未改变空间分辨率。C错误：DKI仍使用扩散敏感梯度，只是采样策略与拟合模型不同。D错误：两个b值只能确定单指数斜率，无法解出二次项。E错误：MK的临床意义正是反映组织微结构的复杂/异质程度，如胶质瘤分级、缺血半暗带评估中MK与病理级别相关。", "tr": "记住b值需求的层级：常规DWI两个b值即可；IVIM需要低b段密集采样；DKI需要高b值（≥2000）与多方向。高b值带来的代价是SNR下降与SAR/涡流增加，3.0T下常需并行采集与匀场配合。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0134", "t": "多选题", "s": "关于扩散张量成像（DTI）与纤维束示踪的技术要求，下列说法正确的有", "o": {"A": "求解一个三维扩散张量至少需要在6个非共线方向上施加扩散梯度并采集一幅b＝0图像；临床常用20—32个方向以提高张量估计的稳定性与各向异性测量精度", "B": "各向异性分数FA取值0—1，反映扩散方向性的一致程度；平均扩散率MD反映整体扩散幅度，二者是相互独立的信息", "C": "颅脑DTI常用b＝1000 s/mm²，b值过低则各向异性对比不足，过高则SNR下降使FA被噪声系统性高估", "D": "纤维束示踪在纤维交叉区域存在固有局限，单张量模型只能给出一个主方向，可能造成纤维束中断或错误连接", "E": "只要方向数足够多，DTI即可完全区分纤维交叉、扇形分散与穿行的复杂结构"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-007", "kp": "DTI方向数、b值与纤维束示踪局限", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确：张量为3×3对称矩阵，独立元素6个，故最少6方向；但噪声条件下方向数越多、方向分布越均匀，特征值/特征向量估计越稳定，临床常用20—32方向，研究可达64方向以上。B正确：FA描述“方向性”，MD描述“快慢”，二者可分离——例如水肿区MD升高而FA可正常或降低，肿瘤浸润区可表现为FA降低而MD轻度升高。C正确：b值需在扩散加权与SNR之间折中，b＝1000是脑白质的经典取值；低SNR时噪声本底会使最小特征值被抬高得相对少而使FA虚高，这是低SNR区（如脑干边缘）FA不可信的原因。D正确：单张量模型每个体素只有一个主特征向量，在放射冠等纤维交叉区（约占白质体素的1/3）会失效，需高角分辨扩散成像（HARDI）、球面反卷积或多张量模型改善。【为什么错】E错误：这是绝对化的过度承诺。方向数增加只能改善张量参数的估计精度，无法突破单张量模型本身的数学限制；解决交叉问题必须换模型而非仅加方向。", "tr": "E的陷阱在于混淆“采样密度”与“模型能力”。请牢记：6方向是数学下限而非临床推荐；FA在低SNR区会被高估；交叉纤维是DTI的模型级缺陷。术前脑功能定位报告应注明这一局限。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0135", "t": "案例分析题", "s": "患者女，9岁，烟雾病术后1年随访，需评估脑血流灌注情况，并计划此后每6个月复查一次。既往有钆剂使用史，家长强烈抵触再次注射对比剂；患儿肾功能正常，能配合安静躺卧约6 min。设备为飞利浦3.0T。关于灌注方案的选择与技术设置，最合理的是", "o": {"A": "选择动脉自旋标记（ASL），以动脉血中的水分子作为内源性示踪剂，无须钆剂、可重复测量；因烟雾病侧支循环迂曲致动脉通过时间延长，应适当延长标记后延迟时间（PLD，如由1.5 s延长至2.0—2.5 s）或采用多延迟ASL，否则会低估灌注并出现血管内高信号（动脉通过伪影）", "B": "必须选择动态磁敏感对比增强灌注（DSC），因为只有钆剂团注才能得到CBV、CBF、MTT、TTP全套参数，ASL无任何定量能力", "C": "选择DSC，但把钆剂剂量减半即可规避所有风险", "D": "选择动态对比增强（DCE）T1灌注，因为其对脑血流最敏感", "E": "不做灌注，仅用TOF-MRA评价血管形态即可完全替代灌注信息"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-008", "kp": "ASL与DSC灌注的原理差异与人群选择", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。ASL用射频脉冲反转标记流入动脉血中的水质子，作为可自由弥散的内源性示踪剂，采集标记像与对照像相减得到灌注加权图，可定量脑血流量CBF（mL/100 g/min）。其优势正契合本例：无对比剂、可无限次重复、适合儿童与需长期随访者。技术关键在于PLD——标记血流到达组织所需的时间在烟雾病、重度颈动脉狭窄、老年人中显著延长，PLD过短时标记血尚滞留于大血管内，表现为迂曲血管内的条状高信号（动脉通过伪影）而组织灌注被低估，因此应延长PLD或采用多PLD采集以同时获得动脉通过时间。【为什么错】B错误：ASL可定量CBF，这恰恰是它相对DSC（多为半定量相对值）的优点之一；DSC虽能给出CBV/MTT/TTP，但并非“唯一可定量”。C错误：减半剂量不解决“不愿使用对比剂＋需长期反复随访”的核心诉求，钆在脑组织的长期沉积问题在儿童反复检查中尤需谨慎。D错误：DCE基于T1弛豫率变化评估血管通透性（Ktrans等），主要用于肿瘤与血脑屏障评估，对脑血流的敏感性与时间分辨率不及DSC/ASL，且仍需钆剂。E错误：形态学正常不等于灌注正常，烟雾病的核心问题恰恰是侧支代偿是否充分，MRA不能回答该问题。", "tr": "本题的高阶考点是PLD。很多考生只记住“ASL不用打药”，却不知道PLD设置不当会造成系统性低估。经验值：健康成年人PLD约1.5—2.0 s，老年人与脑血管病患者2.0—2.5 s，儿童可略短（约1.5 s），但烟雾病等侧支循环病例应延长或改多延迟采集。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0136", "t": "多选题", "s": "某院开展静息态BOLD功能成像（rs-fMRI），下列技术设置与质量控制做法正确的有", "o": {"A": "采用梯度回波EPI序列，3.0T下TE通常设为约30 ms（与灰质T2*接近）以获得最大BOLD对比，1.5T则需延长至约40—50 ms", "B": "静息态扫描要求受试者清醒、闭眼或注视十字、不做系统性思维活动，采集时长通常需6—10 min以保证低频振荡（0.01—0.08 Hz）的统计功效", "C": "头动是rs-fMRI最主要的混杂因素，应通过泡沫垫/真空垫固定、扫描前充分沟通加以预防，并在后处理中做头动校正、回归头动参数，对逐帧位移超阈值的时间点予以剔除（scrubbing）", "D": "扫描前应嘱受试者避免入睡，睡眠会显著改变默认网络等静息态网络的连接模式", "E": "为提高信噪比应尽量延长TR至6 s以上，TR越长静息态数据质量越好"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-009", "kp": "静息态BOLD的参数设置与头动控制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确：BOLD对比来源于去氧血红蛋白引起的T2*效应，当TE≈组织T2*时BOLD信号变化最大；3.0T灰质T2*约30—40 ms，故取TE≈30 ms，1.5T的T2*更长故TE相应延长。B正确：静息态分析的是低频自发振荡的同步性，采样时长不足会导致相关系数估计不稳，一般不少于5—6 min，多数方案采用8—10 min。C正确：头动会同时改变体素内组织成分与自旋历史，产生虚假相关，是导致组间差异假阳性的首要原因；预防（固定＋沟通）优于校正，校正后仍需帧位移剔除。D正确：睡眠状态下默认网络的功能连接强度与网络构型明显改变，故须保持清醒并在扫描后询问确认。【为什么错】E错误：TR决定时间采样率，TR过长会使低频信号采样点稀疏、生理噪声（呼吸约0.3 Hz、心搏约1 Hz）严重混叠到低频段而无法有效剔除。静息态常用TR为2—3 s，采用同时多层（multiband/SMS）技术可缩短至0.5—1 s以改善生理噪声分离，方向与E相反。", "tr": "E利用“TR长＝信号足”的直觉。功能成像的TR是时间分辨率参数而非单纯的信噪比参数。另注意静息态与任务态的区别：任务态需按区组（block）或事件相关设计施加刺激并做时间锁定分析，TE设置相同但时长与范式不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0137", "t": "单选题", "s": "某任务态BOLD实验（手指运动区组设计）在3.0T上采集，技师为提高图像信噪比将TE由30 ms改为12 ms，其余参数不变。可以预期的结果是", "o": {"A": "单帧EPI图像的信噪比提高，但BOLD激活对比度显著下降、激活体素数明显减少，甚至无法检出激活区", "B": "BOLD对比度提高，激活区面积增大", "C": "对BOLD激活无影响，仅缩短扫描时间", "D": "会使激活区从运动皮层移位到感觉皮层", "E": "可完全消除颅底磁敏感伪影且不影响激活检出"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-FUNC-010", "kp": "BOLD的TE依赖性与对比度—信噪比权衡", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A正确。BOLD信号变化率可近似写为 ΔS/S ≈ −TE·ΔR2*，即激活引起的百分信号变化与TE成正比；当TE≈T2*时功能对比度—噪声比（CNR）达到峰值。把TE从30 ms（接近3.0T灰质T2*）压到12 ms，虽然横向弛豫衰减减少、单帧图像的绝对信噪比上升，但ΔS/S被压缩到原来的不足一半，统计检验中的激活体素数会大幅下降，弱激活区可能完全检不出。功能成像看重的是CNR而非单帧SNR，这是本题的核心逻辑。【为什么错】B方向说反，TE缩短使BOLD权重下降。C错误：TE缩短并不缩短扫描时间（TR与采集矩阵未变），且明确影响BOLD。D错误：TE改变的是对比度权重，不会造成解剖位置移位；空间位置错误应考虑几何变形、层间时间校正或配准问题。E错误：缩短TE确实能减轻T2*失相位造成的信号丢失（这也是短TE在颅底的唯一好处），但“完全消除”是绝对化表述，且以牺牲BOLD对比为代价，不能说“不影响激活检出”。", "tr": "本题考的是“SNR与CNR不是一回事”。同类逻辑还出现在：提高带宽降低SNR但减轻化学位移伪影；缩短TE提高SNR但降低T2权重。副高层面必须能识别参数调整的双向后果。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0138", "t": "单选题", "s": "关于磁敏感加权成像（SWI）的数据构成与图像生成流程，正确的是", "o": {"A": "采用三维扰相梯度回波（T1-FFE/FLASH/SPGR）流动补偿采集，同时得到幅值图与相位图；相位图经高通滤波去除背景场后生成相位掩模，与幅值图相乘（通常多次）增强磁敏感对比，再对若干层作最小密度投影（minIP）显示连续静脉", "B": "采用自旋回波序列采集，仅使用幅值图", "C": "相位图直接使用，无须去除背景场", "D": "生成SWI图时相位掩模与幅值图相加", "E": "SWI最终显示采用最大密度投影（MIP）以突出静脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-001", "kp": "SWI的采集与后处理流程", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确。SWI的四个要素缺一不可：①三维长TE梯度回波采集（3.0T常用TE约20 ms、1.5T约40 ms）保留T2*与相位信息，并加流动补偿避免血流相位误差；②高通滤波去除由空气—组织界面、匀场不良造成的大尺度背景相位；③把滤波后相位归一化为0—1的掩模，与幅值图相乘若干次（常4次）以放大顺磁性物质的低信号；④对连续8—16 mm层块作最小密度投影，使断续的小静脉在一幅图上连续显示。【为什么错】B错误：自旋回波的180°脉冲会重聚静态磁场不均匀，恰恰抵消了磁敏感效应，SWI必须用梯度回波。C错误：不去背景场则相位被大尺度不均匀主导、缠绕严重，无法反映局部磁化率。D错误：是相乘（加权）而非相加，相加不能形成非线性放大效应。E错误：静脉、出血、铁沉积均为低信号，突出低信号必须用minIP；MIP用于显示高信号的动脉（如TOF-MRA）。", "tr": "最常见的错误是把minIP写成MIP。判断口诀：SWI看的是“黑”，所以用最小密度投影；MRA看的是“亮”，所以用最大密度投影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0139", "t": "单选题", "s": "在基底节区同时见到SWI幅值图上的点状低信号，需要鉴别是钙化还是微出血。最可靠的技术判读方法是", "o": {"A": "参照校正后的相位图：顺磁性物质（去氧血红蛋白、含铁血黄素）与抗磁性物质（钙）产生方向相反的相位偏移，故在同一台设备的相位图上呈相反的信号极性；由于厂家采用右手或左手系统的约定不同，必须先用本机已知钙化病例（如脉络丛、松果体钙化）标定相位极性后再判读", "B": "在幅值图上比较低信号的绝对灰度值，越黑者为钙化", "C": "看病灶大小，直径小于5 mm者为微出血", "D": "在T1WI上钙化必为高信号、出血必为低信号，据此鉴别", "E": "在SWI最小密度投影图上钙化呈高信号"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-002", "kp": "SWI相位图鉴别钙化与出血", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确。钙为抗磁性（磁化率为负），铁相关产物为顺磁性（磁化率为正），二者在局部产生的磁场偏移方向相反，因而在校正后的相位图上呈相反极性——这是SWI相位图相对CT的独特价值。但相位的正负与显示灰阶取决于厂家的坐标系约定（右手系统与左手系统相反），不同厂家甚至同一厂家不同软件版本可能不同，因此临床上必须先用生理性钙化（松果体、脉络丛、大脑镰）在本机上标定“钙化是亮还是暗”，再据此判读病灶，这也是许多误判的根源。【为什么错】B幅值图上钙化与出血都是低信号，灰度深浅受体积、TE、部分容积影响，不具鉴别力。C大小与性质无关，微出血与点状钙化尺寸重叠。D错误：钙化在T1WI上信号多变（可高可低，取决于钙的结晶形式与含水量），出血信号更随时间演变（超急性、急性、亚急性、慢性各不相同），此规律不成立。E错误：minIP进一步强调低信号，钙化在其上仍为低信号；且minIP会加重开花效应（blooming），更不适合定性。", "tr": "陷阱是死记“钙化在相位图上是亮的”。正确答法必须包含“取决于右手/左手系统，需本机标定”。若要求确切定量鉴别，可加做QSM——QSM给出的磁化率数值有正负号，钙为负值、铁为正值，不依赖显示约定。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0140", "t": "多选题", "s": "关于SWI、定量磁化率成像（QSM）与T2* mapping三项磁敏感相关技术的比较与应用，下列说法正确的有", "o": {"A": "SWI对脑内微出血、弥漫性轴索损伤的点状出血、海绵状血管瘤的“爆米花”样含铁血黄素环显示极为敏感，检出率显著高于常规T2*WI与T2WI", "B": "SWI存在“开花效应”（blooming），病灶显示尺寸随TE延长而放大，因此不能用于病灶大小的准确测量", "C": "QSM通过求解由磁化率分布到相位分布的偶极子卷积逆问题，直接给出以ppm为单位的组织磁化率定量值，克服了相位图非局部效应与SWI不可定量的缺点，可用于苍白球、黑质等核团铁含量的纵向定量", "D": "T2* mapping采集同一激发下的多个回波，对各回波信号按单指数拟合逐像素求出T2*，可换算为R2*（R2*＝1000/T2*，T2*以ms为单位时R2*单位为s⁻¹），用于心肌、肝脏铁沉积的定量", "E": "急性期蛛网膜下腔出血在SWI上无任何表现，SWI对出血的检出仅限于脑实质内"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-003", "kp": "SWI、QSM与T2* mapping的比较", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确：这三类病变的共同基础是含铁血黄素/去氧血红蛋白的顺磁性，SWI的相位加权把微弱磁化率差异放大，检出微出血的数量常为常规GRE的2倍以上。B正确：开花效应源于顺磁性物质周围的局部磁场外溢范围大于其解剖边界，且随TE延长而扩大，故SWI适合“检出”不适合“测量”，测量应参考T2WI或QSM。C正确：QSM把相位这一非局部量反演为局部磁化率，数值有正负号（顺磁为正、抗磁为负），是目前脑铁纵向随访的首选定量工具。D正确：多回波GRE的T2*拟合是铁定量的基础，R2*与组织铁浓度近似线性相关，临床报告心肌与肝脏铁负荷时常用R2*或T2*两种表述。【为什么错】E错误：急性蛛网膜下腔出血在SWI上可表现为脑沟、脑池内的线样/铸型低信号，对少量出血甚至比CT更敏感；SWI对脑室内出血、硬膜下少量出血同样敏感，并非仅限脑实质。", "tr": "B与C构成一对：SWI“敏感但不定量、且夸大尺寸”，QSM“定量且尺寸真实”。E是方向性错误陷阱。另注意SWI的局限：颅底与鼻窦旁磁敏感伪影重、对运动敏感（三维长TE采集）、扫描时间较长。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0141", "t": "案例分析题", "s": "患者男，24岁，重型β地中海贫血，规律输血14年，口服祛铁治疗中，临床要求评估心肌与肝脏铁负荷以指导祛铁方案。设备为飞利浦3.0T，患者心率78次/分、律齐，可屏气约15 s。技师拟行心脏T2* mapping。下列技术执行与判读要点，最恰当的是", "o": {"A": "采用心电门控、单次屏气的多回波扰相梯度回波序列采集左室中段短轴层面（通常8个回波，TE自约2 ms起以约2 ms递增），在室间隔中段全层厚勾画ROI（避开心内膜面血池、心外膜脂肪与心大静脉），按单指数拟合T2*；判读阈值为T2*>20 ms正常、10—20 ms提示中度铁沉积、<10 ms提示重度铁过载且心力衰竭与恶性心律失常风险显著升高；肝脏铁负荷另行采集肝脏多回波序列，不能用心脏值代替", "B": "采用自旋回波T2WI测量心肌信号强度与骨骼肌之比即可判断铁负荷，无须T2* mapping", "C": "选择左室心尖部层面并在整个左室游离壁勾画ROI，以获得最大代表性", "D": "由于心脏与肝脏铁沉积程度一致，只需扫肝脏T2*并据此推算心肌铁负荷", "E": "T2*值越大表示铁沉积越重，故T2*<20 ms提示铁负荷正常"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-004", "kp": "心脏T2* mapping铁过载定量", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确，四个要点均为国际公认做法。①层面与序列：心电门控多回波GRE、单次屏气采集左室中段短轴，避免不同回波间的呼吸位移导致拟合失败。②ROI：固定取室间隔中段全层厚，因为室间隔远离心脏静脉、肺组织与心外膜脂肪，磁敏感干扰最小、可重复性最好；侧壁与心尖受心大静脉、肺—心界面影响，测值不可靠。③拟合：逐像素或ROI均值按 S(TE)＝S₀·exp(−TE/T2*) 单指数拟合；重度铁过载时后段回波已进入噪声本底，须采用截尾法（truncation）或带常数项的模型，否则T2*被系统性高估。④阈值：T2*>20 ms正常，10—20 ms中度，<10 ms重度并与心功能不全、心律失常风险显著相关，是启动强化祛铁的关键指征。⑤心、肝铁需分别测量。【为什么错】B自旋回波的180°脉冲重聚了静态场不均匀，对铁的敏感性远低于T2*，信号比值法早已被T2*定量取代。C心尖与游离壁易受心大静脉、肺界面与部分容积影响，且心尖层厚薄、运动大，不是标准测量位置。D错误：心肌与肝脏的铁沉积动力学不同步——肝铁上升更早、下降也更快，而心肌铁往往滞后数年，二者不可互相推算，这正是必须分别测量的临床理由。E把方向说反：铁沉积使T2*缩短，值越小越重。", "tr": "本题四重陷阱：①测量位置（必须室间隔中段，不是游离壁/心尖）；②方向（T2*越短越重，不是越长越重）；③心肝不可互推；④重度铁过载时的拟合截尾问题。另注意3.0T下T2*值系统性短于1.5T，公认的20 ms/10 ms阈值建立于1.5T，3.0T测量需使用本机校准或按厂家/文献换算后报告。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0142", "t": "单选题", "s": "某科室开展肝脏T2* mapping用于铁沉积定量，技师设置多回波梯度回波序列时，下列参数取舍最合理的是", "o": {"A": "采用单次屏气的多回波（≥6个回波）采集，首个TE尽可能短（约1 ms左右）、回波间隔尽量小，翻转角取较小值（约20°以下）以减少T1权重污染，并保证所有回波在同一屏气内完成", "B": "采用两个回波即可满足拟合要求，回波间隔取10 ms", "C": "翻转角越大越好，可提高信噪比从而提高拟合精度", "D": "各回波可在不同屏气中分次采集，只要嘱患者屏气位置一致即可", "E": "首个TE应尽量长（>15 ms），以增强铁的磁敏感效应"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SWI-005", "kp": "多回波T2* mapping的参数设置", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A正确。①回波数与间隔：重度铁过载时肝T2*可短至1—2 ms，若首个TE太长或间隔太大，信号在第一个采样点前就已衰减殆尽，衰减曲线无法采到有效点，必然低估铁负荷；因此首个TE要尽可能短、回波间隔尽可能密，回波数≥6以保证拟合自由度。②翻转角：T2* mapping希望信号纯粹反映T2*衰减，大翻转角会引入明显T1权重，尤其在短TR下造成偏倚，故取小翻转角（一般≤20°）。③同一屏气：多回波必须在同一次激发的回波链中获得，且整段采集在一次屏气内完成，否则不同回波间的位置错动会使逐像素拟合失效。【为什么错】B两个回波只能算出一个斜率、无法评估拟合优度，也无法识别噪声本底与脂肪引起的信号振荡；10 ms间隔对重度铁过载完全无法采样。C大翻转角引入T1污染，且并不改善T2*拟合的核心问题，属于把“信噪比”与“定量准确性”混为一谈。D分次屏气会导致层面错位与逐像素配准失败，是定量图出现斑驳伪影的常见原因。E方向说反：长TE只会丢失短T2*组织的信号，正确策略是尽早、尽密采样。", "tr": "记住定量序列的通用原则：短TE起步、密集采样、小翻转角去T1、一次屏气保证配准。此外肝脏常合并脂肪变，脂肪与水的化学位移会使信号随TE呈周期性振荡，应选用同相位回波间隔（1.5T约4.6 ms、3.0T约2.3 ms）或采用含脂肪模型的拟合，否则T2*/R2*结果失真。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0143", "t": "单选题", "s": "脑1H-MRS谱线中，各代谢物的化学位移（ppm）定位正确的一组是", "o": {"A": "NAA 2.02，Cr 3.03，Cho 3.22，Lac 1.33（双峰），Lip 0.9—1.3", "B": "NAA 3.22，Cr 2.02，Cho 3.03，Lac 3.56，Lip 2.6", "C": "NAA 1.33，Cr 0.9，Cho 2.02，Lac 3.03，Lip 3.22", "D": "NAA 3.03，Cr 3.22，Cho 2.02，Lac 2.6，Lip 1.48", "E": "NAA 2.6，Cr 1.33，Cho 0.9，Lac 3.22，Lip 3.03"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-001", "kp": "脑1H-MRS主要代谢物的化学位移", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确。脑质子波谱由高场（左）向低场（右）的常规排列（横轴ppm从右向左递减）依次为：Cho 3.22 ppm（胆碱复合物，细胞膜代谢）、Cr 3.03 ppm（肌酸/磷酸肌酸，能量代谢，常作内参）、NAA 2.02 ppm（N-乙酰天门冬氨酸，神经元完整性标志）、Lac 1.33 ppm（乳酸，J耦合双峰）、Lip 0.9—1.3 ppm（脂质，坏死或细胞膜崩解）。另需记住肌醇mI 3.56 ppm、Glx 2.1—2.5 ppm、Ala 1.48 ppm（双峰）、前列腺枸橼酸盐Cit约2.6 ppm。【为什么错】B、C、D、E均为峰位随机错置，与实际谱线不符。可用“3.22胆碱、3.03肌酸、2.02NAA、1.33乳酸”这一由高到低的顺序自查。", "tr": "最易混的是Cho（3.22）与Cr（3.03）——两峰相距仅0.19 ppm，谱线上紧邻，若匀场不良（线宽增大）二者会融合成一个宽峰，导致Cho/Cr比值失真。记忆顺序口诀：“胆—肌—N—乳—脂”，ppm由大到小。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0144", "t": "单选题", "s": "关于单体素MRS中PRESS与STEAM两种定位方式的比较，正确的是", "o": {"A": "PRESS为90°—180°—180°三脉冲自旋回波定位，理论信噪比约为STEAM的2倍，但最短可实现TE较长；STEAM为三个90°脉冲的受激回波定位，可实现很短的TE（有利于检测短T2代谢物如肌醇、谷氨酸复合物），但信号仅为PRESS的一半且对运动与扩散更敏感", "B": "STEAM信噪比约为PRESS的2倍，PRESS只能用于长TE", "C": "两者信噪比相同，仅脉冲顺序不同", "D": "PRESS采用三个90°脉冲，STEAM采用90°—180°—180°", "E": "STEAM不需要水抑制，PRESS需要"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-002", "kp": "PRESS与STEAM的技术差异", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确。PRESS用一个90°激发加两个180°重聚焦脉冲，三者层面正交相交定义体素，全部横向磁化被重聚，信号约为STEAM的2倍；但两个180°脉冲需要时间且SAR高，最短TE通常在30 ms左右（3.0T可更短但受限）。STEAM用三个90°脉冲形成受激回波，只有一半磁化贡献信号，但脉冲短、SAR低，最短TE可低至10 ms以下，适合检测J耦合复杂、T2较短的代谢物（mI、Glx、GABA），代价是SNR低、对运动与扩散敏感、需更多平均次数。【为什么错】B完全颠倒。C错误：脉冲组合直接决定了可用磁化的比例，SNR相差约一倍。D把两者的脉冲结构互换。E错误：无论PRESS还是STEAM，水峰浓度比代谢物高约万倍，都必须使用水抑制（如CHESS）与外容积饱和带，缺一不可。", "tr": "记忆抓手：PRESS＝“Point RESolved Spin echo”，有180°故信号全、TE长；STEAM＝“STimulated Echo”，三个90°故信号半、TE短。临床上脑常规MRS多用PRESS（TE 35 ms与144 ms各一套），需要短TE定量代谢物时选STEAM。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0145", "t": "多选题", "s": "关于MRS采集中匀场与水抑制的技术要求，下列说法正确的有", "o": {"A": "匀场质量通常用水峰半高全宽（FWHM）衡量，线宽越窄谱线分辨率越高；线宽过大时Cho（3.22 ppm）与Cr（3.03 ppm）会相互重叠而无法准确定量", "B": "组织内水的浓度约为代谢物的10⁴倍，若不抑制水信号，代谢物峰将被水峰及其旁瓣完全淹没，故必须施加化学位移选择性水抑制（如CHESS）", "C": "体素应尽量避开颅骨内板、鼻窦、乳突气房、术后金属与出血区，这些部位的磁化率突变会严重破坏局部场均匀性", "D": "在体素周围施加外容积饱和带（OVS）可抑制颅骨骨髓与头皮脂肪信号沿化学位移方向渗入体素造成的巨大脂质峰污染", "E": "只要使用了自动匀场功能，无论体素位置如何都可获得合格谱线，无须人工复核线宽"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-003", "kp": "匀场、水抑制与外容积饱和", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确：MRS的谱分辨率完全由B₀均匀性决定，一般要求水峰FWHM在1.5T约<8—10 Hz、3.0T约<10—15 Hz；线宽变大会使相邻峰融合，Cho/Cr、NAA/Cr比值随之失真。B正确：水与代谢物浓度相差约四个数量级，必须用频率选择性脉冲加扰相梯度反复抑制水信号，抑制不足会出现巨大水峰与基线扭曲。C正确：磁化率突变区是匀场的天敌，颞叶前部、额叶眶回、颅底与术区常无法获得合格谱线，选体素时应主动回避。D正确：头皮与颅骨骨髓脂肪的信号可通过化学位移误配准渗入体素，形成0.9—1.3 ppm的巨大脂质峰，掩盖乳酸峰，OVS（八个方向的饱和带）是标准对策。【为什么错】E错误：自动匀场只是起点，操作者必须复核水峰线宽与水抑制效率，不合格时应重新调整体素位置或改用高阶匀场、手动匀场。把质量控制完全交给自动化是MRS失败谱的常见原因。", "tr": "E是典型的“自动化依赖”陷阱。实操要点：先看线宽，再看水抑制，再看基线；三者任一不合格，谱线即不可用于定量。另注意脂质峰与乳酸峰均位于1.3 ppm附近，脂质污染会直接导致乳酸判读错误，此时可用TE＝144 ms观察峰是否倒置来区分。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0146", "t": "单选题", "s": "在1.5T脑MRS中，若在1.3 ppm附近观察到一个明显的峰，为判断它是乳酸（Lac）而非脂质（Lip），最有效的技术手段是", "o": {"A": "把TE设为约135—144 ms再采集一次：乳酸为J耦合双峰，在该中间TE下发生相位反转呈倒置峰，而脂质峰始终朝上", "B": "把TE缩短至30 ms，此时乳酸峰会消失", "C": "增加平均次数即可区分", "D": "改用STEAM定位，乳酸峰会移位到2.0 ppm", "E": "增强扫描后重复MRS，乳酸峰会强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-004", "kp": "乳酸峰的J耦合倒置判别", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确。乳酸的甲基质子与相邻次甲基质子存在标量（J）耦合，J约7 Hz，其双峰的相对相位随TE周期性变化：在TE≈1/J（约135—144 ms）时两个分量反相叠加，使整个双峰在谱线上倒置于基线以下；而脂质是无J耦合调制的宽峰，无论TE长短始终为正峰。因此临床脑MRS常规同时采集短TE（30—35 ms，观察mI、Glx、Lip）与中间TE（135—144 ms，鉴别Lac、简化基线）两套谱。【为什么错】B错误：短TE下乳酸峰不但不消失，反而与脂质峰重叠更难区分，这正是需要中间TE的原因。C错误：平均次数只提高信噪比，不改变峰的相位特性。D错误：化学位移由分子结构决定，不随定位序列改变；改用STEAM不会使乳酸移位。E错误：MRS测的是代谢物浓度，钆剂不会使乳酸“强化”，反而可能因缩短T1、破坏匀场而干扰谱线，故MRS原则上应在增强前采集。", "tr": "两个衍生考点：①丙氨酸（Ala）1.48 ppm同为双峰，在中间TE下也倒置，见于脑膜瘤；②MRS应安排在注射钆剂之前，注射后Cho峰可被压低而造成假阴性，这是临床流程中最易被忽视的顺序问题。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0147", "t": "多选题", "s": "关于多体素波谱成像（化学位移成像CSI）与前列腺MRS，下列说法正确的有", "o": {"A": "多体素CSI在一次采集中用相位编码把感兴趣层面或容积划分为多个体素，可获得代谢物的空间分布图（代谢图），便于观察肿瘤的异质性与选择活检靶点", "B": "与单体素相比，多体素CSI采集时间更长、对匀场范围要求更高，且相邻体素间存在信号污染（点扩散函数导致的体素间串扰）", "C": "正常前列腺外周带上皮细胞可分泌并富集枸橼酸盐（Cit，约2.6 ppm），前列腺癌区Cit明显降低而Cho升高，故以(Cho＋Cr)/Cit比值升高作为提示恶性的指标", "D": "前列腺MRS对匀场与脂肪抑制要求极高，直肠气体与粪便造成的磁化率不均匀是失败的主要原因，检查前清洁肠道、直肠内置线圈或使用直肠球囊有助改善", "E": "在PI-RADS v2.1评分体系中，MRS已被列为与T2WI、DWI并列的核心序列之一"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MRS-005", "kp": "多体素CSI与前列腺MRS", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A正确：CSI用相位编码实现空间定位，输出可叠加于解剖图的代谢伪彩图，胶质瘤分级、放射性坏死与复发鉴别、活检靶点选择均受益。B正确：相位编码步数决定采集时间，体素数增加则时间成倍延长；同时匀场需覆盖更大范围，难度更高；有限采样导致的点扩散函数使邻近体素信号相互渗漏，靠近颅骨的体素常被脂质污染。C正确：Cit是前列腺特有的代谢标志，癌变时上皮细胞由分泌型转为氧化代谢型，Cit减少而细胞膜代谢活跃使Cho升高，比值升高提示恶性。D正确：直肠气体与前列腺的界面磁化率差异极大，是前列腺MRS匀场失败最常见的原因。【为什么错】E错误：PI-RADS v2.1的核心序列是T2WI、DWI/ADC与DCE，MRS并未纳入评分体系。事实上由于操作复杂、耗时长、可重复性受限，前列腺MRS在临床常规中的应用已明显减少，多参数MRI以T2WI＋DWI＋DCE为标准组合。", "tr": "E是时效性陷阱——早年教材把MRS列为前列腺“多参数”之一，但现行PI-RADS v2.1已不包含MRS。答题时要按现行标准。另注意CSI体素越小SNR越低，实际前列腺CSI体素常为0.3—0.5 cm³，脑CSI常为1—2 cm³。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0148", "t": "单选题", "s": "关于化学位移选择性脂肪抑制（FatSat/CHESS、SPIR、SPAIR）的原理与特点，正确的是", "o": {"A": "利用水与脂肪约3.5 ppm的化学位移差（1.5T约220 Hz、3.0T约440 Hz），用窄带频率选择性射频脉冲单独激发并扰相破坏脂肪信号；场强越高频率间隔越大、抑制越容易，但对B₀不均匀与大FOV边缘仍很敏感", "B": "利用水与脂肪的T1差异，与化学位移无关", "C": "场强越低频率间隔越大，故0.35T比3.0T更易实现化学位移选择性脂肪抑制", "D": "SPAIR与SPIR的区别在于SPAIR不需要频率选择性", "E": "化学位移选择性脂肪抑制不受金属植入物影响"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAT-001", "kp": "化学位移选择性脂肪抑制原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】A正确。脂肪中亚甲基质子与水质子的共振频率相差约3.5 ppm，绝对频率差＝3.5×10⁻⁶×γB₀，1.5T约220 Hz、3.0T约440 Hz。频率选择性饱和用中心频率对准脂肪峰的窄带脉冲把脂肪磁化翻转后立即扰相破坏，随后再施加成像序列，此时脂肪无纵向磁化可用故呈低信号。场强越高频率间隔越大，窄带脉冲更易把水脂分开，因此3.0T的化学位移脂肪抑制通常优于1.5T；但其致命弱点是依赖B₀均匀性，在大FOV边缘、颈肩交界、乳腺外侧、金属附近会出现脂肪抑制不全或误抑制水。【为什么错】B错误：这是STIR的机制（依赖T1差异），化学位移法依赖频率差异。C完全说反：频率差与场强成正比。D错误：SPAIR同样是频率选择性的，其特点是使用绝热反转脉冲，对B₁（射频场）不均匀更耐受、抑制更均匀，代价是SAR更高、扫描时间稍长。E错误：金属附近B₀严重畸变，脂肪峰频率偏移，窄带脉冲反而可能误饱和水或完全失效，此时应改用STIR或Dixon类方法。", "tr": "三种脂肪抑制的适用逻辑：化学位移法（SPIR/SPAIR/FatSat）——高场、小FOV、匀场好时首选，且可用于增强后；STIR——匀场差、金属植入、大FOV时可靠，但不能用于增强后；Dixon——兼顾均匀性与增强后使用，代价是最小TE与重建复杂度。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0149", "t": "单选题", "s": "临床上强调注射钆对比剂后不宜使用STIR序列作为脂肪抑制手段，其根本原因是", "o": {"A": "STIR采用非选择性反转恢复，其抑制依据是“T1值接近脂肪”而非“属于脂肪”；强化后病灶T1明显缩短并可能接近脂肪的T1，从而被一并抑制，造成强化灶信号丢失甚至假阴性", "B": "STIR的SAR过高，增强后不能使用", "C": "钆剂会改变脂肪的化学位移", "D": "STIR序列扫描时间长，增强后对比剂已廓清", "E": "STIR在增强后会产生水脂互换伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAT-002", "kp": "STIR在增强后的禁用理由", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】A正确。STIR用非选择性180°反转脉冲把所有组织的纵向磁化反转，再在脂肪磁化过零点（TI≈0.693×T1脂肪）时激发，此刻脂肪信号为零。它抑制的判据是T1值，凡T1接近脂肪者都会被抑制。注射钆剂后，强化组织（肿瘤、炎症、脑膜、血管）的T1被大幅缩短，可能落入脂肪的T1窗口内而被误抑制，导致本应显著强化的病灶反而变暗，形成灾难性的假阴性。因此增强后需要脂肪抑制时应选择化学位移法（SPIR/SPAIR）或Dixon水像。【为什么错】B STIR的SAR确实高于常规SE（多一个180°反转脉冲），但这不是增强后禁用的“根本原因”，平扫时同样面临SAR问题。C错误：化学位移由分子结构决定，钆剂不会改变脂肪的共振频率。D错误：细胞外间隙钆剂在数分钟内仍维持相当浓度，扫描时间不是核心矛盾。E错误：水脂互换是Dixon类相位解算方法的特征性伪影，与STIR无关。", "tr": "记住一句话：STIR抑制的是“T1像脂肪的东西”，不是“脂肪”。同样的道理还解释了另外两个现象：亚急性血肿（高铁血红蛋白T1短）在STIR上可被误抑制；含蛋白的黏液、钆剂外渗区也可被误抑制。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0150", "t": "多选题", "s": "关于Dixon水脂分离技术（两点法、三点法、mDIXON）的优势与伪影，下列说法正确的有", "o": {"A": "一次采集即可同时输出水像、脂像、同相位像与反相位像四组图像，无须重复扫描，对比信息更完整", "B": "其脂肪抑制基于水脂进动频率差引起的相位差，对B₀不均匀的耐受性明显优于化学位移选择性饱和，适用于大FOV（如全脊柱、颈胸交界、乳腺双侧）与金属附近的成像", "C": "Dixon类方法可在增强后使用，且水像的脂肪抑制均匀性通常优于SPIR/SPAIR", "D": "水脂互换（fat-water swap）是Dixon的特征性伪影，表现为图像局部或整幅的水像与脂像内容对调，多因B₀不均匀致相位解卷绕失败，常见于视野边缘、金属旁与磁场畸变区；对策包括改善匀场、缩小FOV、增加回波数或重新运行相位解算重建", "E": "Dixon技术完全不受B₀不均匀影响，因此在任何情况下都不会出现脂肪抑制失败"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SAT-003", "kp": "Dixon水脂分离的优势与水脂互换伪影", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】A正确：这是Dixon最实用的优势——同一次采集得到四组图像，反相位像还可用于检出少量脂肪（肾上腺腺瘤、脂肪肝、含脂病变），信息密度高。B正确：Dixon利用相位差而非绝对频率位置，配合场图估计可容忍相当程度的B₀漂移，故在颈胸交界、双侧乳腺、金属内固定附近等匀场困难处优于窄带饱和法。C正确：Dixon不依赖T1，增强后使用不会误抑制强化组织，是增强后脂肪抑制的优选之一。D正确：水脂互换是解相位方程时把水解成脂、脂解成水，可局部发生（一块区域黑白翻转）或整幅翻转，识别方法是看皮下脂肪层在“水像”上是否异常明亮。【为什么错】E错误：“完全不受影响”是绝对化表述。当B₀畸变超过算法可解范围（如大块金属、严重匀场失败）时，Dixon同样会失败并以水脂互换的形式表现出来——D与E自相矛盾，E必错。", "tr": "D与E构成一对互斥选项，是识别答案的快速切入点。另需记住同/反相位的回波时间：1.5T同相位约4.6 ms、反相位约2.3 ms；3.0T同相位约2.3 ms、反相位约1.15 ms，回波间隔随场强反比缩短。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0151", "t": "单选题", "s": "关于反转恢复类序列的反转时间（TI）设置，下列组合正确的是", "o": {"A": "3.0T脑T2-FLAIR抑制脑脊液的TI约2200—2500 ms（配合TR 9000—11000 ms）；STIR抑制脂肪的TI在1.5T约150—170 ms、在3.0T约200—250 ms", "B": "3.0T FLAIR的TI约150 ms，STIR的TI约2500 ms", "C": "TI与场强无关，1.5T与3.0T可使用完全相同的TI", "D": "STIR的TI应设为脂肪T1的两倍", "E": "FLAIR的TR可任意设置，与TI无关"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-PREP-001", "kp": "FLAIR与STIR的反转时间设置", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A正确。反转恢复的抑制原理是在目标组织纵向磁化过零点时施加激发脉冲，理论TI≈0.693×T1（当TR足够长、磁化完全恢复时）。脑脊液T1很长（3.0T约4000—4500 ms），故FLAIR需要很长的TI（约2200—2500 ms）与相应更长的TR（9000—11000 ms）以保证零点计算成立。脂肪T1很短（1.5T约250 ms、3.0T约370 ms），故STIR的TI仅一两百毫秒；因组织T1随场强升高而延长，3.0T的STIR-TI要相应加长至约200—250 ms。【为什么错】B把两者的TI完全对调。C错误：T1值随B₀升高而延长（脂肪、脑脊液、白质均如此），TI必须随场强重新标定，这是1.5T协议直接搬到3.0T后抑制失败的常见原因。D错误：应为约0.693倍T1而非两倍。E错误：TR若不足够长，反转前的纵向磁化未充分恢复，实际零点会前移，TI必须相应缩短；FLAIR的长TR正是为配合长TI而设，二者强相关。", "tr": "牢记两条关系：①TI≈0.693×T1（长TR条件下）；②所有组织的T1随场强升高而延长，故换场强必须换TI。临床上3.0T FLAIR若沿用1.5T的TI，会出现脑脊液抑制不全、脑室边缘残留高信号。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0152", "t": "多选题", "s": "关于空间预饱和带（saturation band）的临床用途，下列说法正确的有", "o": {"A": "在颈椎矢状面成像时于咽喉部前方施加饱和带，可减轻吞咽运动与颈前血管搏动沿相位编码方向产生的鬼影", "B": "在腹部成像时于腹壁前方施加饱和带，可减轻呼吸运动伪影", "C": "在TOF-MRA中作为流动饱和带，选择性抑制来自某一方向的血流以分离动脉与静脉", "D": "饱和带位置应放在伪影源所在的位置，而不是随意放置；饱和带越多SAR越高，须权衡", "E": "饱和带可以消除已经采集完成的图像上的运动伪影，属于后处理技术"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-PREP-002", "kp": "空间预饱和带的用途", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A正确：运动伪影沿相位编码方向传播，把运动源（咽喉、颈前血管）的信号预先饱和掉，鬼影自然减弱。B正确：腹壁皮下脂肪是呼吸运动伪影最强的信号源，前腹壁饱和带是腹部与脊柱成像的常规配置。C正确：这正是TOF中区分动静脉的手段——抑制哪支血管就把饱和带置于其流入侧。D正确：饱和带必须准确覆盖伪影源；每个饱和带都是一次额外的射频脉冲，会增加SAR并可能占用TR内的时间而减少可采层数。【为什么错】E错误：饱和带是采集前施加的预脉冲，属于采集技术而非后处理；一旦数据采集完成，饱和带无法追加。真正的后处理去伪影手段是运动校正配准、鬼影抑制算法等。", "tr": "E混淆了“预脉冲”与“后处理”。要点：凡带“pre-”“预”字样（预饱和、预反转、磁化传递预脉冲）都发生在读出之前，必须在扫描前设置好。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0153", "t": "单选题", "s": "行心肌延迟强化（LGE）扫描时，需先运行TI scout（Look-Locker）序列。关于其目的与判读，正确的是", "o": {"A": "Look-Locker在一次采集中获得一系列不同TI的图像，操作者从中挑选正常心肌信号被抑制到最低（“变黑”）时对应的TI用于LGE；该TI随注药后时间延长而逐渐增大，需在采集过程中适时复测，若使用相位敏感反转恢复（PSIR）重建则对TI选择的容错性明显提高", "B": "Look-Locker用于寻找使瘢痕心肌信号最低的TI", "C": "Look-Locker用于测量心率以设置门控", "D": "TI一旦确定，在整个延迟强化采集过程中恒定不变，无须调整", "E": "TI选择错误只影响图像美观，不影响瘢痕的检出"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-PREP-003", "kp": "心肌延迟强化的TI scout与PSIR", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A正确。LGE的对比逻辑是“把正常心肌压黑、让瘢痕亮起来”，因此必须使正常心肌处于反转恢复的零点。Look-Locker（TI scout）在单次屏气内以递增TI连续采集同一层面，操作者目视选择正常心肌最黑的那一帧对应的TI。随着钆剂从血池与心肌中不断廓清，组织T1逐渐回升，零点TI随之延长（注药后10 min与20 min可相差数十毫秒），故在多层面采集过程中应间隔复测。PSIR重建利用相位信息恢复反转磁化的正负号，即使TI偏离最佳值仍能保持瘢痕—正常心肌的极性对比，显著降低对TI精度的依赖，尤其适合屏气差或需要长时间采集的患者。【为什么错】B错误：目标是抑制正常心肌而非瘢痕；瘢痕因细胞外间隙扩大、钆浓度高、T1短，在正常心肌被抑制时呈明亮高信号。C错误：心率由心电门控获取，Look-Locker不是测心率的工具。D错误：TI必须随时间调整，这是LGE质量控制的关键环节。E错误：TI偏短会使正常心肌呈现反相的“过黑”并可能反转对比，TI偏长则正常心肌变灰、瘢痕对比下降，小面积心内膜下瘢痕可被漏诊，直接影响诊断而非美观问题。", "tr": "本题核心是“抑制谁”。同类逻辑还有：黑血双反转抑制的是流动的血液，脂肪抑制反转恢复抑制的是脂肪，FLAIR抑制的是脑脊液——反转恢复类技术的第一问永远是“把哪种组织放到零点”。另注意PSIR并非可以随意乱设TI，仍应尽量接近零点以获得最佳信噪比。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0154", "t": "单选题", "s": "采用并行采集技术（SENSE/GRAPPA/ARC）时，关于其原理与代价的说法正确的是", "o": {"A": "利用多通道相控阵线圈各单元空间灵敏度的差异替代部分相位编码步，加速因子R使采集时间缩短约R倍，而信噪比按 1/(g·√R) 下降，其中几何因子g≥1，取决于线圈单元的排布与加速方向", "B": "并行采集通过提高梯度切换率缩短扫描时间，与线圈无关", "C": "加速因子可无限增大，只要线圈通道数足够", "D": "并行采集会提高信噪比，因此是纯粹的收益", "E": "SENSE在K空间域重建，GRAPPA在图像域重建"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-AUX-001", "kp": "并行采集的加速因子、g因子与SNR代价", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A正确。并行采集在相位编码方向上按因子R欠采样，产生的卷褶用各线圈单元已知的灵敏度分布解开。信噪比损失有两部分：欠采样使采集数据量减少，SNR降低√R倍；线圈灵敏度分布的相似性导致方程组病态，引入几何因子g（g≥1，线圈几何越不利、加速方向与线圈排布越不匹配、g越大），合成后SNR≈SNR₀/(g·√R)。【为什么错】B错误：并行采集靠的是线圈的空间信息，不是梯度性能；它恰恰是在梯度性能已达生理与工程极限时的提速途径。C错误：加速因子受线圈单元数、单元在加速方向上的排列与g因子急剧上升的共同限制，通常R不超过线圈在该方向的有效单元数，实际临床多用R＝2—4；过高会出现残余卷褶带与噪声放大。D错误：并行采集是以SNR换时间，绝非“纯粹收益”；只有在SNR冗余充足（如3.0T、大体素、多次平均）时才适合高加速。E错误：正好说反——SENSE在图像域解卷褶，GRAPPA/ARC在K空间域拟合缺失行。", "tr": "E的域向记忆抓手：SENSE的S可联想“Sensitivity in image space”，GRAPPA属自校准K空间方法（需采集自动校准中心行ACS）。两者的伪影表现也不同：SENSE失败表现为图像中央的条带状残余卷褶，GRAPPA失败表现为弥漫性噪声与波纹。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0155", "t": "多选题", "s": "关于压缩感知（compressed sensing, CS）在MRI中的应用，下列说法正确的有", "o": {"A": "其三个必要条件是：图像在某个变换域（如小波、有限差分/全变分）中可稀疏表示、采用非相干（近似随机）欠采样使伪影呈噪声样弥散、以及非线性迭代重建算法求解", "B": "CS与并行采集的加速机制互补，可联合使用（如CS-SENSE），在同等图像质量下获得比单纯并行采集更高的净加速倍数", "C": "过高的CS加速倍数会导致图像过度平滑、纹理丢失与低对比小病灶的检出率下降，因此加速倍数应结合部位与临床问题设定并做本机验证", "D": "CS特别适合本身具有高度稀疏性或冗余度的数据，如三维各向同性采集、动态多时相采集（4D CE-MRA、心脏电影）与波谱成像", "E": "CS重建为线性运算，重建时间与常规傅里叶重建基本相同"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-AUX-002", "kp": "压缩感知的三要素与临床边界", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A正确：稀疏性、非相干欠采样、非线性重建是CS成立的三大支柱，缺一不可；规则欠采样会产生结构化的卷褶而无法被稀疏约束区分，故必须用变密度随机采样（中心密、外周疏）。B正确：并行采集利用线圈的空间冗余，CS利用图像的变换域冗余，二者信息来源不同故可叠加，商用CS-SENSE、CS-GRAPPA可将三维序列缩短一半以上。C正确：CS的L1正则本质上是“惩罚不稀疏的成分”，加速过高时低对比细节会被当作噪声抑制掉，出现塑料感/水彩画样过平滑，临床验证应关注低对比小病灶（如肝内小转移、微小骨转移）的检出而不仅看主观锐利度。D正确：三维与动态数据在空间/时间维度上高度冗余，是CS收益最大的场景。【为什么错】E错误：CS重建是求解带L1正则的非凸/凸优化问题，需要数十至上百次迭代，是典型的非线性运算，重建时间明显长于常规傅里叶变换，对重建服务器算力要求高；这也是CS在临床落地时需要考虑的工作流成本。", "tr": "E的“线性、同样快”是常见误解。另需明确CS与深度学习重建（DLR）的区别：CS依靠人为设定的稀疏先验，DLR依靠数据驱动学习到的先验；无DLR的设备上，追求更高加速只能依赖CS＋并行采集的组合，并须以本机小病灶检出验证为准绳。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0156", "t": "多选题", "s": "关于MR门控与触发技术，下列说法正确的有", "o": {"A": "心电门控以R波为触发信号，时间精度最高，是心脏电影、黑血序列与延迟强化的基础；磁流体动力学效应会使T波在强磁场中抬高，可能被误认为R波而造成触发错误，故应优化电极位置并使用矢量心电（VCG）", "B": "外周脉搏门控（指端光电容积脉搏波）操作简便、不受磁流体动力学干扰，但脉搏波相对R波有数百毫秒的延迟且波形圆钝，时相精度低，适用于对时相要求不高的场景（如脊柱、脑脊液流动抑制）", "C": "呼吸门控可用腹带式压力传感器或呼吸波纹管获取呼吸曲线，在呼气末的稳定期采集", "D": "导航回波（navigator）在膈肌顶部放置一条一维柱状激发条，实时追踪膈肌位置，仅接受落在设定接受窗（常3—5 mm）内的数据；门控效率过低（如低于40%）时应重新训练患者呼吸或改用屏气方案", "E": "心电门控与呼吸门控不能同时使用，只能二选一"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-AUX-003", "kp": "心电门控、外周门控、呼吸门控与导航回波", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A正确：R波陡峭、易于识别，是心脏时相的天然零点；但导电血液在主磁场中流动产生的电位（磁流体动力学效应）叠加在T波上使其抬高，普通三导联心电易误触发，矢量心电通过空间向量方向区分真R波与伪信号，是高场心脏MR的标准配置。B正确：外周门控的信号源在指端，与心脏收缩之间存在传导延迟，波峰圆钝、抖动大，只能提供近似的心动周期节律，适合脊柱、颅脑等仅需抑制搏动伪影的场合。C正确：呼气末是呼吸周期中位置最稳定、停留时间最长的时相。D正确：导航回波的接受窗越窄图像越锐利但门控效率越低、扫描时间越长，须在二者间平衡；效率过低意味着患者呼吸不规律，应重新训练或改屏气。【为什么错】E错误：二者完全可以并用，且在心脏与上腹部检查中是常规做法——心电门控管心动时相、呼吸门控或导航回波管呼吸位移，例如非屏气的三维全心冠脉成像即同时使用心电门控与膈肌导航。", "tr": "E是明显的绝对化陷阱，但仍有考生因“怕冲突”而误选。另注意术语区别：门控（gating）是持续采集、事后按信号筛选或分箱；触发（triggering）是等到信号出现才启动采集。前瞻性触发丢弃异常心搏，回顾性门控可重排数据获得全心动周期电影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0157", "t": "单选题", "s": "颅脑MRI常规横断面扫描时，被广泛采用的定位基线是", "o": {"A": "在正中矢状面定位像上以前连合—后连合连线（AC-PC线）或平行于胼胝体膝部下缘与压部下缘的连线作为基线，其优点是解剖标准化、便于随访与不同患者间比较", "B": "以外耳道与鼻尖的连线为基线", "C": "以头皮外形的最大径线为基线", "D": "以磁体等中心的水平面为基线，不参考解剖结构", "E": "以颅底斜坡的走行方向为基线"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-001", "kp": "颅脑横断面定位基线", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。AC-PC线是神经影像学公认的标准基线，它使双侧基底节、丘脑、内囊等结构在同一层面对称显示，横断面解剖具有可重复性；胼胝体膝部下缘与压部下缘连线在实际操作中与AC-PC线接近，是更易目视确定的替代基线。标准化基线的价值在于：随访时层面可比、双侧结构对称便于发现细微不对称、便于与标准图谱及既往CT对照。【为什么错】B错误：外耳道—鼻尖连线不是公认基线；CT颅脑常用眦耳线（OML）或听眉线，MR则以AC-PC为主。C错误：头皮外形受个体差异与摆位影响，不具解剖学意义。D错误：完全不参考解剖会使层面歪斜、双侧不对称，随访无法比较。E错误：斜坡走行个体差异大且过于倾斜，仅在特定颅底检查中作为参考。", "tr": "重点是理解“为什么要标准化”，而不是死记线名。摆位时还须保证正中矢状面与磁体中线重合、头部无旋转与侧倾，否则再标准的基线也会产生假性不对称，误导海马、颞叶等细微结构的判读。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0158", "t": "单选题", "s": "三维T1加权梯度回波序列（3D T1-TFE/MPRAGE/BRAVO）在颅脑检查中广泛使用，其在序列结构上加入反转恢复预脉冲的主要目的是", "o": {"A": "提供充分的T1对比，使灰白质分界清晰，从而支持各向同性1 mm重建、脑容积测量、皮层发育不良评估与神经导航配准", "B": "抑制脑脊液信号", "C": "缩短扫描时间", "D": "降低SAR", "E": "抑制脂肪信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-002", "kp": "3D T1W梯度回波的反转预脉冲作用", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。快速三维扰相梯度回波为追求速度采用极短TR与小翻转角，本身的T1对比很弱，灰白质难以区分。在每个采集段前加一个非选择性180°反转脉冲并设置合适的反转时间，可把灰白质的纵向磁化差异放大，形成媲美二维自旋回波T1WI的对比。由此获得的各向同性亚毫米数据可任意面重建，用于海马与全脑体积定量、局灶性皮层发育不良的皮层厚度与灰白质交界模糊征评估，以及手术导航与放疗计划的图像配准。【为什么错】B抑制脑脊液是FLAIR的功能，其TI要长得多（约2200—2500 ms@3.0T），而3D T1的TI通常仅数百至一千毫秒。C错误：加入反转脉冲与其后的恢复等待反而延长了序列，加速靠的是三维采集、并行采集与压缩感知。D错误：多一个180°脉冲只会增加SAR。E错误：抑制脂肪需频率选择性饱和或短TI的STIR，与此处的中等TI反转预脉冲用途不同。", "tr": "关键在于区分“同为反转恢复预脉冲，TI不同则用途完全不同”：TI约150—250 ms抑脂（STIR）、TI约2200—2500 ms抑脑脊液（FLAIR@3.0T）、TI数百至千毫秒增强T1对比（MPRAGE类）、TI由Look-Locker实测用于抑制正常心肌（LGE）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0159", "t": "单选题", "s": "急性缺血性卒中患者的颅脑T2-FLAIR图像上，于患侧大脑中动脉供血区的脑沟内见到多发线样、蛇形高信号（血管走行区），而同层T2WI上血管呈流空低信号。对该征象的正确技术—临床解读是", "o": {"A": "为FLAIR血管高信号征，是近端大血管重度狭窄或闭塞后侧支循环内血流缓慢、流空效应减弱而在长TE的FLAIR上呈高信号，常提示存在可挽救的侧支代偿，应结合MRA与灌注综合判断，不应误判为蛛网膜下腔出血或伪影", "B": "为脑脊液抑制不全所致的伪影，只需重新设置TI即可消失", "C": "提示蛛网膜下腔出血，应立即改行CT", "D": "为脂肪抑制失败造成的高信号", "E": "为并行采集加速过高产生的残余卷褶伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-003", "kp": "FLAIR血管高信号征的技术机制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。快速流动的血液因流出层面而产生流空低信号；当近端血管闭塞、侧支血流极其缓慢时，血液在层面内停留时间延长，流空效应消失，其相对较长的T2使之在FLAIR的长TE下呈高信号，沿脑沟内血管走行呈线样、蛇形分布。该征象的临床价值在于提示大血管病变与侧支代偿状况，与灌注—扩散不匹配的范围常有相关性。【为什么错】B脑脊液抑制不全表现为脑室、脑池内弥漫或对称的高信号，多见于脑室系统与后颅窝，形态与沿血管走行的线样高信号不同，且不会局限于单侧供血区。C蛛网膜下腔出血在FLAIR上也表现为脑沟高信号，是最需要鉴别的对象，但其分布通常更弥漫、呈铸型，且SWI/T2*可见相应的低信号出血证据，结合病史（突发剧烈头痛）与CT可鉴别；本例为缺血症状且SWI无出血，不能贸然改判。D颅脑FLAIR一般不使用脂肪抑制，且脂肪抑制失败表现为颅骨骨髓与头皮的高信号，位置不符。E残余卷褶伪影表现为规律的条带状结构，与解剖血管走行一致的形态不符。", "tr": "本题的鉴别核心是“FLAIR脑沟高信号”的多因鉴别：血管高信号征、蛛网膜下腔出血、脑膜炎/癌性脑膜病、高浓度吸氧、钆剂渗入蛛网膜下腔、脑脊液流动与抑制不全伪影。副高层面要能从形态分布＋伴随序列（SWI、DWI、MRA）综合判断，而非单看一幅图。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0160", "t": "案例分析题", "s": "患者男，27岁，反复发作性愣神伴口咽自动症4年，抗癫痫药物控制不佳，拟行术前评估，临床高度怀疑颞叶内侧癫痫（海马硬化）。常规头颅MRI（5 mm层厚横断面T1WI、T2WI、FLAIR）报告未见异常。设备为飞利浦3.0T，配备32通道头线圈与压缩感知。技师应追加的最关键扫描方案是", "o": {"A": "增加垂直于海马长轴的斜冠状面高分辨T2WI与FLAIR，层厚2—3 mm、无层间隔、小FOV高分辨矩阵，双侧对称覆盖海马全长；并加做各向同性1 mm的3D T1加权序列用于灰白质交界评估与容积测量，必要时补充垂直于海马长轴的斜矢状面", "B": "把原有横断面层厚由5 mm改为8 mm以提高信噪比", "C": "追加静脉注射钆剂的全脑增强扫描，海马硬化多呈明显强化", "D": "追加全脑DTI纤维束成像作为主要诊断依据", "E": "追加SWI寻找海马内微出血"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-004", "kp": "癫痫海马专用扫描方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。海马沿颞角呈前后走行且略向内上倾斜，常规横断面对其为斜切，5 mm层厚更使部分容积效应严重掩盖海马内部结构，这正是“常规MRI阴性”的技术原因。癫痫专用方案的要点为：①方位——在正中矢状或旁矢状定位像上确定海马长轴，扫描斜冠状面使层面垂直于该长轴，两侧海马在同一层面对称显示，便于左右对比；②分辨率——层厚2—3 mm、无间隔、小FOV（常180—200 mm）与高矩阵，以分辨海马内部结构与体积差异；③序列——高分辨T2WI（观察海马信号增高）与FLAIR（观察内侧颞叶信号异常），加各向同性3D T1用于容积测量与灰白质交界评估（局灶性皮层发育不良的关键征象）。3.0T的高信噪比与压缩感知加速使这一方案在临床可接受时间内完成。【为什么错】B层厚加大会进一步加重部分容积效应，与目标背道而驰。C海马硬化的典型表现是海马萎缩＋T2/FLAIR信号增高，并无异常强化；增强对本病诊断价值有限，且不能弥补层厚与方位的缺陷。D DTI可提供辅助信息（如穹窿、钩束的各向异性改变），但不是海马硬化的诊断依据，也无法替代高分辨结构像。E海马硬化不以微出血为特征，SWI在此无针对性。", "tr": "本题的根本考点是“阴性结果可能是技术造成的”。副高层面必须能识别：层厚、方位与分辨率不足是常规MRI漏诊海马硬化、局灶性皮层发育不良的首要原因。类似的“方位决定成败”场景还有：垂体（薄层冠状）、内听道（薄层轴位＋水成像）、直肠癌（垂直肠壁的斜轴位）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0161", "t": "案例分析题", "s": "患者女，31岁，闭经泌乳2年，血清泌乳素显著升高，临床疑垂体微腺瘤（可能仅3—4 mm）。设备为飞利浦3.0T。技师拟行垂体动态增强扫描。下列技术设计与判读要点，最恰当的是", "o": {"A": "以冠状面为主、层厚2—3 mm无间隔覆盖整个垂体与海绵窦，配合矢状面；动态期采用快速采集（如快速自旋回波T1或扰相梯度回波），每一期约10—20 s、连续采集6—8期覆盖注药后1—2 min；判读要点是微腺瘤在早期强化程度低于快速强化的正常垂体而呈相对低信号，延迟期可变为等或高信号，故仅做延迟期极易漏诊", "B": "采用5 mm层厚横断面，注药后5 min扫一期即可", "C": "动态增强的判读要点是微腺瘤比正常垂体强化更早更快，呈早期高信号", "D": "为提高信噪比，动态各期间隔应设为60 s以上", "E": "微腺瘤诊断主要依赖DWI，动态增强意义不大"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-005", "kp": "垂体动态增强扫描技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。垂体微腺瘤的检出完全依赖“时间窗＋薄层＋方位”三者配合。①方位与层厚：垂体前后径小、微腺瘤常位于腺体侧翼，冠状面能同时显示垂体上缘形态、垂体柄偏移与海绵窦侵犯，层厚必须2—3 mm且无间隔，否则3—4 mm的病灶被部分容积淹没。②时间分辨率：正常垂体前叶无血脑屏障、由垂体门脉系统供血，注药后迅速均匀强化并在30—60 s达峰；微腺瘤血供来自被膜血管、强化延迟，故只在早期这一短暂窗口内表现为相对低信号，因此每期必须控制在10—20 s并连续采集6—8期。③判读：延迟期病灶与正常腺体趋于等信号，单做延迟期是垂体微腺瘤漏诊最常见的原因。【为什么错】B 5 mm层厚与单一延迟期同时踩中两个致命错误，必然漏诊。C强化时序说反：微腺瘤是“慢进”，正常垂体是“快进”。D 60 s以上的间隔会完全错过早期时间窗，把动态扫描做成了普通增强。E垂体区DWI受颅底磁敏感与部分容积影响严重，对3—4 mm病灶无实用价值，动态增强才是核心手段。", "tr": "最大的陷阱是C的“强化时序反向”。记忆抓手：正常垂体没有血脑屏障、血供丰富，一定是“先亮”；微腺瘤“后亮”，所以要抢早期。另注意扫描前应了解是否已用溴隐亭治疗，治疗后腺瘤缩小、强化特征改变会影响判读。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0162", "t": "多选题", "s": "后颅窝与颅底区域MR成像质量较差，下列关于其成因与改善措施的说法正确的有", "o": {"A": "岩骨、乳突气房与鼻窦的气—骨—软组织界面磁化率差异大，造成局部B₀不均匀，梯度回波类序列与EPI受影响最重，表现为信号丢失与几何变形", "B": "第四脑室、中脑导水管与桥前池的脑脊液搏动可产生流动相关伪影与信号不均，沿相位编码方向出现条带状鬼影", "C": "改善措施包括：使用自旋回波/快速自旋回波替代梯度回波、施加流动补偿（梯度矩零化）、加用空间预饱和带、必要时采用心电或外周门控采集，以及做高阶匀场", "D": "对必须使用EPI-DWI的情形，可采用读出分段EPI或提高并行采集因子以缩短有效回波链，从而减轻几何变形", "E": "增大层厚是改善后颅窝磁敏感伪影最有效的手段"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-006", "kp": "后颅窝伪影的成因与对策", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确：磁化率差异导致局部质子失相位，梯度回波无180°重聚故最敏感，EPI因长读出链而变形最重。B正确：脑脊液在心动周期驱动下往复搏动，在导水管、桥前池与颈髓交界处形成流动伪影，常被误读为病变（如误认为蛛网膜囊肿、血管流空或占位）。C正确：这四条是标准对策组合——自旋回波的180°脉冲能重聚静态场不均匀；流动补偿使恒速流动的相位归零；饱和带抑制搏动源；门控把采集固定在心动周期的同一时相；高阶匀场直接改善B₀。D正确：几何变形与相位方向的等效带宽成反比，缩短单次读出链是根本对策。【为什么错】E错误：增大层厚只会加重部分容积效应、掩盖小病灶，对磁化率造成的场不均匀毫无改善作用；恰恰相反，在磁化率剧变区往往需要更薄的层厚以减少层内失相位。", "tr": "E利用“层厚大＝信号强＝伪影不明显”的错觉。要点：磁化率伪影的成因是B₀空间畸变，只有改变序列类型、缩短回波链、改善匀场才能真正解决；层厚、平均次数、翻转角这些“信噪比手段”对系统性场畸变无效。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0163", "t": "多选题", "s": "关于颅脑MR增强扫描的技术要点，下列说法正确的有", "o": {"A": "DWI、SWI、MRS与ASL等序列原则上应安排在注射钆剂之前采集，钆剂会改变磁化率与T1，影响这些序列的定量与判读", "B": "疑诊脑膜转移或脑膜炎时，延迟数分钟后加扫脂肪抑制T1WI或三维T1加权序列有助于提高细小脑膜强化的检出", "C": "增强后若需脂肪抑制（如眼眶、颅底、头皮病变），应选择化学位移选择性饱和或Dixon水像，不宜用STIR", "D": "三维T1加权梯度回波增强因层厚薄、可多平面重建，对小转移灶的检出通常优于5 mm二维自旋回波T1WI", "E": "为节省时间，增强扫描可省略平扫T1WI，直接对比增强图像与T2WI即可判断强化"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-007", "kp": "颅脑增强扫描的序列顺序与技术选择", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确：钆剂使组织T1缩短并引入磁化率效应，会压低MRS的Cho峰、干扰SWI相位、改变ASL的标记效率与DWI的信号强度，故功能与定量序列须前置。B正确：脑膜强化多在注药后数分钟更明显，脂肪抑制可去除颅骨骨髓与板障脂肪的高信号背景，三维序列则提供薄层与多平面重建能力。C正确：STIR按T1抑制，会误抑制强化组织（详见反转恢复原理），增强后应改用频率选择性饱和或Dixon。D正确：小转移灶常小于3 mm，5 mm层厚存在明显部分容积效应；三维序列1 mm各向同性采集可显著提高微小强化灶检出，是脑转移瘤筛查与立体定向放疗计划的标准做法。【为什么错】E错误：判断“是否强化”必须有同序列、同参数的平扫作为对照，否则无法区分强化与本身的T1高信号（如出血、黑色素、高蛋白、脂肪、钙化）。省略平扫T1WI是严重的方法学错误。", "tr": "E在追求效率时最容易被忽视。请牢记增强判读的铁律：强化＝增强后信号高于同序列平扫，而非高于周围组织。另注意平扫与增强的窗宽窗位、层面位置应保持一致以便对照。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0164", "t": "单选题", "s": "患者女，29岁，产后10天，剧烈头痛伴视物模糊，临床疑颅内静脉窦血栓形成。设备为飞利浦3.0T。下列MR方案设计最合理的是", "o": {"A": "以SWI（或T2*WI）观察窦内血栓的顺磁性低信号，联合二维时间飞跃法MR静脉成像（2D TOF-MRV，饱和带置于成像容积足侧以抑制动脉）或对比增强MRV观察充盈缺损，并结合常规T1WI/T2WI/FLAIR评估静脉性梗死与出血；判读时须注意横窦发育不良与蛛网膜颗粒可造成假阳性", "B": "首选3D TOF-MRA观察静脉窦，其对慢血流的敏感性最高", "C": "仅行DWI即可确诊静脉窦血栓", "D": "仅行常规T1WI与T2WI，静脉窦血栓在这两个序列上信号特征恒定、诊断可靠", "E": "首选MRS评估静脉窦区代谢改变"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRN-008", "kp": "颅内静脉窦血栓的MR技术方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A正确。静脉窦血栓的技术评估需要“直接征象＋间接征象＋并发症”三条线：①直接看血栓——SWI/T2*对去氧血红蛋白与含铁血黄素的顺磁性极敏感，急性血栓呈显著低信号，还可显示扩张的皮层引流静脉；②看管腔——2D TOF-MRV逐层薄层激发对慢血流敏感（3D TOF因容积内饱和不适合静脉），扫描时把饱和带置于成像容积的足侧以抑制上行动脉血；对比增强MRV则不依赖流动，可减少慢血流与平面内流动造成的假阳性；③看后果——常规序列评估静脉性梗死、水肿与出血。同时必须熟知假阳性来源：横窦发育不良或不对称、蛛网膜颗粒、窦内分隔，均可造成充盈缺损样表现，需结合双侧对比与增强MRV判断。【为什么错】B错误：3D TOF存在容积内饱和，对流速缓慢的静脉显示差，且方位选择针对动脉；静脉成像应用2D TOF或增强MRV。C错误：DWI可提示静脉性梗死或部分血栓的扩散受限，但敏感性与特异性均不足以单独确诊。D错误：血栓信号随时间演变剧烈——急性期（数天内）在T1等信号、T2低信号，极易与正常流空混淆而漏诊；亚急性期才呈T1高信号。仅靠常规序列漏诊率高。E错误：MRS对本病无诊断价值，且静脉窦邻近颅骨无法匀场。", "tr": "两个高频陷阱：①急性期血栓T2低信号酷似正常流空，是最常见的漏诊原因，必须加做SWI与MRV；②静脉成像用2D TOF而非3D TOF，饱和带放在足侧（与颅内动脉MRA正相反）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0165", "t": "单选题", "s": "颈椎MRI横断面扫描时，关于层面角度的设置，正确的做法是", "o": {"A": "在矢状面定位像上按各个椎间隙分组设置，使每组层面分别平行于相应椎间盘平面，从而真实显示该节段的椎间盘、钩椎关节、椎间孔与神经根", "B": "从C2至T1采用统一角度连续无间隔扫描，以保证覆盖完整", "C": "层面应垂直于脊髓长轴，与椎间盘角度无关", "D": "层面应平行于AC-PC线", "E": "层面角度可由系统随机设定，不影响诊断"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-001", "kp": "颈椎横断面的分组成角扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确。颈椎存在生理前凸，各椎间隙的倾斜角度自上而下不断变化。只有让层面平行于每一个椎间盘平面，才能获得真正的“椎间盘轴位”，准确判断突出的方向与程度、钩椎关节增生、椎间孔狭窄与神经根受压。因此临床标准做法是按椎间隙分组（如C3/4、C4/5、C5/6、C6/7各一组），每组单独调整角度。【为什么错】B统一角度会使中下段椎间盘被斜切，突出物形态失真，容易高估或低估突出程度，且椎间孔无法显示。C垂直于脊髓长轴与平行于椎间盘并不等价，颈椎前凸使二者在多数节段有明显夹角；诊断关注的是椎间盘平面。D AC-PC线是颅脑定位基线，与颈椎无关。E错误：层面角度直接决定诊断准确性，绝无“随机设定”之说。", "tr": "考点是“方位服从解剖与临床问题”。同类思维：腰椎轴位同样按椎间隙分组成角（尤其L5/S1倾斜大）；若为观察椎体骨质或椎管内占位的连续范围，则可采用连续等角度覆盖。两种目的对应两种设置，不可混用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0166", "t": "单选题", "s": "老年女性，胸腰段多个椎体楔形变，临床需要区分新鲜（近期）与陈旧压缩骨折以决定是否行椎体成形术。最能提供关键信息的序列是", "o": {"A": "矢状面短反转时间反转恢复（STIR）或脂肪抑制T2WI：新鲜骨折的骨髓水肿呈明显高信号，陈旧骨折骨髓信号已恢复为脂肪信号而无水肿", "B": "矢状面T1WI，新鲜骨折呈高信号", "C": "横断面T2WI，可直接测量椎体高度丢失比例", "D": "三维时间飞跃法MRA观察椎体血供", "E": "1H-MRS测定椎体脂肪含量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-002", "kp": "椎体压缩骨折新鲜与陈旧的鉴别序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确。判断“新鲜与否”的病理基础是骨髓水肿：新鲜骨折伴出血、水肿使骨髓含水量增加，在脂肪抑制的T2加权（STIR或脂肪抑制TSE T2WI）上呈明确高信号，同时T1WI上呈低信号取代正常脂肪高信号；陈旧骨折骨髓已被脂肪重新充填，脂肪抑制像上与正常椎体一致。这是决定椎体成形术是否可能缓解疼痛的关键影像依据。老年患者常合并多发陈旧骨折，形态学（楔形变）无法区分责任椎体，必须依靠水肿信息。【为什么错】B错误：新鲜骨折在T1WI上是低信号（水肿取代脂肪），选项方向说反。C错误：横断面不适合观察椎体高度，且高度丢失只反映形态、不反映时相；陈旧骨折同样可有严重楔形变。D椎体血供不是MRA的目标，也不能反映骨髓水肿。E MRS测椎体脂肪分数属研究性定量，且体素大、匀场难，不用于急慢性鉴别。", "tr": "记住新鲜骨折的“三联信号”：T1WI低、脂肪抑制T2WI/STIR高、可有强化。金属内固定术后患者若脂肪抑制不良，STIR比化学位移饱和更可靠。另需鉴别病理性骨折：椎弓根受累、椎体后缘膨隆、软组织肿块与弥漫强化提示肿瘤。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0167", "t": "单选题", "s": "腰椎MRI最基本的常规序列组合是", "o": {"A": "矢状面T1WI与T2WI、横断面T2WI，并按需加矢状面STIR或脂肪抑制T2WI", "B": "仅横断面T1WI", "C": "仅矢状面T2WI", "D": "冠状面T1WI与横断面T1WI", "E": "三维时间飞跃法MRA与DWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-003", "kp": "腰椎MRI常规序列组合", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确。矢状面T1WI观察骨髓信号（转移、感染、骨折后脂肪替代）与解剖全貌；矢状面T2WI观察椎间盘退变与含水量、脊髓信号、后纵韧带与硬膜囊；横断面T2WI（按椎间隙分组）判断突出的方向、类型与神经根、侧隐窝、椎间孔受累；STIR或脂肪抑制T2WI用于凸显骨髓水肿与终板炎，是发现隐匿性骨折、感染与转移的关键补充。【为什么错】B单一横断面T1WI既无法评估椎间盘含水量，也不能纵览节段关系。C仅矢状面T2WI无法判断突出的偏侧与神经根受压，也缺乏骨髓的T1信息。D冠状面在脊柱常规中不作为基本方位（多用于侧弯、骶髂关节或神经丛评估），且缺T2信息。E MRA与DWI在腰椎属特殊需求（如疑肿瘤、感染时加DWI），不属基本组合。", "tr": "副高层面除了记住组合，还要能说出“每条序列回答什么临床问题”。补充记忆：疑椎管内占位或感染需加增强（脂肪抑制T1WI）；疑强直性脊柱炎需加骶髂关节斜冠状STIR；术后随访需加增强以区分瘢痕（强化）与复发椎间盘（周边强化、中心不强化）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0168", "t": "多选题", "s": "腰椎后路椎弓根螺钉内固定术后患者需复查MRI，为减轻金属伪影，下列措施正确的有", "o": {"A": "优先选用快速自旋回波（TSE/FSE）类序列，避免梯度回波类序列，因180°重聚焦脉冲可重聚静态磁场不均匀造成的失相位", "B": "提高接收带宽、缩短回波间隔并适当增大采集矩阵，可减小磁化率所致的像素位移与信号堆积，代价是信噪比下降", "C": "脂肪抑制改用STIR或Dixon类方法，不宜使用窄带化学位移选择性饱和（SPIR/SPAIR），因金属旁B₀畸变会使脂肪峰频率偏移导致抑制失败甚至误抑制水", "D": "可启用专用金属伪影抑制技术（如视角倾斜VAT、层面编码金属伪影校正SEMAC、多采集可变谐振成像MAVRIC，或厂家的O-MAR等），并适当降低场强选择（如有1.5T设备优先于3.0T）", "E": "应把频率编码方向设置为与金属植入物长轴垂直，可使伪影范围最小"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-004", "kp": "金属内固定术后脊柱MRI的伪影抑制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确：梯度回波无180°脉冲，磁化率失相位无法补偿，金属旁信号完全丢失；TSE的重聚焦脉冲能挽回大部分静态失相位。B正确：磁化率位移量与每像素带宽成反比，提高带宽（如从±25 kHz提高到±50—100 kHz）能显著压缩伪影范围，代价是SNR按带宽平方根反比下降，需用更多平均次数补偿。C正确：金属旁B₀严重畸变，窄带频率选择性饱和不再对准脂肪峰，会出现抑制不全或误抑制；STIR基于T1不依赖频率，是金属旁最可靠的脂肪抑制方式。D正确：VAT通过在读出时施加与层选梯度相同的补偿梯度校正面内位移；SEMAC/MAVRIC通过额外的层面方向编码校正层面弯曲，是目前最有效的方案；同时低场强下磁化率伪影更小，1.5T优于3.0T。【为什么错】E错误：方向说反。应把频率编码方向设置为与植入物长轴平行，使磁化率造成的位移沿金属长轴方向延展、在垂直方向上更紧凑，从而减少对邻近椎管与神经根的遮盖。", "tr": "E的方向是高频失分点。总口诀：读出方向顺着金属长轴、带宽拉高、TE压短、避开GRE、抑脂用STIR、能用SEMAC就用SEMAC、有1.5T就别用3.0T。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0169", "t": "案例分析题", "s": "患者男，52岁，高处坠落伤后6 h，双下肢感觉运动障碍平面在T10，CT示T11椎体爆裂骨折伴椎管内骨块。生命体征平稳，颈托与脊柱板固定中，需急诊MRI评估脊髓损伤程度与椎管受压情况。设备为飞利浦3.0T。下列方案设计最合理的是", "o": {"A": "在保持轴线稳定的前提下由多人平托过床；采用后部脊柱相控阵线圈，扫描矢状面T2WI与T1WI、矢状面STIR（评估脊髓水肿、韧带损伤与骨髓水肿）、损伤节段横断面T2WI；有条件时加矢状面T2*WI或SWI以检出髓内出血（提示预后不良），并可加矢状面DWI辅助评估；全程控制扫描时长、备好MR兼容监护，并事先确认颈托、固定装置与所有随行器械均为MR安全", "B": "先做全脊柱增强扫描以显示血肿", "C": "只做横断面T2WI即可判断脊髓损伤程度", "D": "为避免搬动风险，直接在脊柱板（含金属搭扣）上送入磁体扫描", "E": "急诊情况下应优先做DTI纤维束成像以判断预后"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-SPN-005", "kp": "急性脊髓损伤的MR检查方案与安全", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A正确，同时兼顾了安全、序列与效率三条线。①安全：脊柱板、颈托、约束带的金属搭扣是常见的铁磁性隐患，必须逐一确认或更换为MR安全型；搬运需保持轴线稳定，多人平托。②序列逻辑：矢状面T2WI/STIR是评估脊髓水肿范围、椎间盘韧带复合体损伤与骨髓水肿的核心；T1WI提供解剖与出血的补充信息；横断面T2WI判断骨块占位与脊髓受压的横断关系；T2*WI/SWI检出髓内出血——髓内出血是完全性损伤与不良预后的重要指标，常规T2WI易漏。③效率：急性期患者耐受差，应精简序列、控制时长并全程监护。【为什么错】B增强对急性脊髓外伤的评估价值有限，且延长检查时间、增加风险，不作为首选。C横断面缺乏纵向范围信息，无法判断脊髓水肿的上下界与多节段损伤，单独使用严重不足。D错误：这是严重的安全违规，任何未经确认的固定装置都不得进入Zone IV。E DTI在急性期采集时间长、对运动敏感，且需要患者良好配合，急诊阶段不具可行性，属于研究性或亚急性期的补充。", "tr": "本题最容易被忽略的是D所代表的安全环节——急诊转运器械的铁磁筛查。另一个专业深度点是T2*/SWI检出髓内出血的预后意义，很多考生只想到T2WI看水肿。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0170", "t": "单选题", "s": "关于眼眶MRI检查技术，下列说法正确的是", "o": {"A": "眶内脂肪在T1WI与T2WI上均为高信号，会掩盖病变并在增强后与强化组织混淆，故T2WI与增强T1WI应常规使用脂肪抑制；层厚宜2—3 mm，并沿视神经走行加扫斜矢状面或斜冠状面；应嘱患者闭眼、注视固定方向以减少眼球运动", "B": "眼眶脂肪信号低，无须脂肪抑制", "C": "层厚以5—8 mm为宜，可提高信噪比", "D": "为减少眼球运动应嘱患者持续快速眨眼", "E": "眼眶MRI禁止使用增强扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HNK-001", "kp": "眼眶MRI的脂肪抑制与方位设计", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A正确。眶内容物被大量脂肪包绕，脂肪在T1WI呈高信号，增强后强化病灶同样呈高信号，二者无法区分，故增强T1WI必须脂肪抑制；T2WI脂肪抑制则有助于凸显水肿与囊性成分。眼眶结构精细（视神经直径仅3—4 mm、眼外肌数毫米），层厚必须2—3 mm并配合小FOV高分辨；视神经走行倾斜，斜矢状面沿其长轴可完整显示，斜冠状面便于对比双侧眼外肌与视神经的粗细。眼球运动是眼眶MRI最主要的伪影源，嘱患者闭眼并想象注视一个固定点、避免眼球游走，可显著改善。【为什么错】B完全说反：眶脂在T1WI与T2WI（非脂肪抑制）上均为高信号。C 5—8 mm层厚对眼眶结构而言过厚，部分容积效应会淹没视神经与小病灶。D持续眨眼会显著增加眼球与眼睑运动，加重伪影。E错误：眼眶肿瘤、炎性假瘤、视神经病变等均需增强评估，并无禁忌。", "tr": "细节陷阱：眼眶邻近鼻窦与颅底，化学位移选择性脂肪抑制常出现局部失败，可改用Dixon水像获得更均匀的抑制；含金属眼影/睫毛膏（部分含氧化铁）可造成眼睑伪影甚至发热，检查前应要求卸妆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0171", "t": "多选题", "s": "关于鼻咽癌的MRI检查技术要点，下列说法正确的有", "o": {"A": "扫描范围上界应至少包含鞍上池/蝶窦上缘，下界应达锁骨上窝，以完整覆盖颅底与颈部各区淋巴结", "B": "平扫T1WI对颅底骨质受侵敏感——正常颅底骨髓的脂肪高信号被肿瘤取代后呈低信号，是早期骨侵犯的重要征象，因此不能用脂肪抑制T1WI取代平扫T1WI", "C": "增强后应加扫脂肪抑制T1WI，横断面结合冠状面，以显示咽旁间隙、翼腭窝、卵圆孔与破裂孔等颅底孔道的神经周围侵犯及海绵窦受累", "D": "层厚一般取3—5 mm，颅底区域宜更薄；小FOV高分辨有助于评估咽颅底筋膜与咽旁间隙", "E": "鼻咽癌MRI可完全替代颈部淋巴结的病理评估，凡MRI阴性即可排除转移"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HNK-002", "kp": "鼻咽癌MRI的范围、序列与方位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A正确：鼻咽癌沿颅底孔道向上侵犯、沿淋巴引流向下转移，范围不足会造成分期错误，这是技师最常见的失误。B正确：这是一个极具操作价值的要点——脂肪抑制会把正常骨髓的高信号一并压低，反而使“脂肪信号消失”这一早期骨侵犯征象无法识别，因此平扫T1WI不可省略、不可用脂肪抑制版本代替。C正确：脂肪抑制增强T1WI是显示神经周围侵犯与海绵窦、咽旁间隙受累的关键，冠状面对颅底孔道的显示优于横断面。D正确：颅底结构精细，薄层与小FOV是准确分期的前提。【为什么错】E错误：MRI是形态学检查，对正常大小淋巴结内的微转移无法识别，不能替代病理；“阴性即可排除”属绝对化错误表述。", "tr": "B是本题的技术精华：并非“凡增强就加脂肪抑制、凡T1就可抑脂”。骨髓侵犯的判断依赖正常骨髓的脂肪高信号作为背景参照，抑脂后这一参照消失。同理，脊柱转移的筛查也必须保留矢状面平扫T1WI。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0172", "t": "单选题", "s": "颈部与甲状腺MRI最主要的运动伪影来源及其对策是", "o": {"A": "吞咽、呼吸与颈部大血管搏动；对策包括扫描前训练患者避免吞咽与说话、缩短单次采集时间、优先选用快速自旋回波类序列、在颈前与血管流入侧施加空间预饱和带，必要时使用外周门控", "B": "眼球运动；对策是嘱患者闭眼", "C": "胃肠蠕动；对策是肌注解痉药", "D": "膈肌运动；对策是呼吸门控，与吞咽无关", "E": "心脏搏动不会影响颈部图像，无须处理"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HNK-003", "kp": "颈部MRI的运动伪影控制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A正确。颈部运动伪影有三个来源：①吞咽——喉与舌骨在数秒内可移动1 cm以上，是颈部图像模糊的首要原因，必须在扫描前明确交代“不吞咽、不说话、不咳嗽”，并把单次采集控制在3—4 min内以便患者忍耐；②呼吸——颈根部与上纵隔受呼吸影响；③颈动脉与颈静脉搏动——沿相位编码方向产生鬼影，可用流动补偿与预饱和带抑制。选用TSE类快速序列缩短采集窗、必要时用外周门控把采集固定在心动周期同一时相，均可显著改善。【为什么错】B眼球运动影响眼眶而非颈部。C胃肠蠕动是腹部问题。D膈肌运动只影响颈根部以下，且颈部检查一般不使用呼吸门控（会大幅延长时间），把吞咽排除在外是明显的遗漏。E错误：颈部大血管与心脏传导来的搏动确实会产生伪影，不能忽视。", "tr": "本题看似简单，实则考“抓主要矛盾”。颈部的第一伪影源是吞咽而非呼吸；解决方案里最有效、成本最低的是“扫描前沟通＋缩短采集时间”，而不是加复杂的门控。另注意甲状腺检查应使用专用颈部相控阵线圈或小FOV，肩部垫高使颈部略后仰以贴近线圈。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0173", "t": "案例分析题", "s": "患儿女，2岁，双侧极重度感音神经性聋，拟行人工耳蜗植入术，术前需影像评估。颞骨CT已完成，示双侧内耳骨性结构大致正常。耳科医师追加MRI申请，核心问题是“耳蜗腔是否通畅、蜗神经是否存在”。设备为飞利浦3.0T，患儿需镇静。技师应重点采集的序列与方位是", "o": {"A": "内耳三维重T2权重高分辨水成像（3D bTFE/CISS/FIESTA-C或3D TSE类），亚毫米各向同性、小FOV；在此基础上重建垂直于内听道长轴的斜矢状面，逐一辨认面神经、蜗神经、前庭上与前庭下神经四束；耳蜗内若见正常高信号淋巴液则提示腔道通畅，若信号缺失提示骨化或纤维化", "B": "常规横断面T2WI TSE，层厚4 mm即可回答上述问题", "C": "内耳DWI高b值成像，蜗神经在DWI上显示最佳", "D": "三维时间飞跃法MRA，通过迷路动脉判断蜗神经发育", "E": "增强后横断面T1WI，蜗神经强化即为存在"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-HNK-004", "kp": "人工耳蜗术前内耳MRI评估", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A正确。人工耳蜗术前评估中，CT与MRI分工明确：CT看骨性结构（耳蜗形态、圆窗、内听道骨性直径、乳突气化、有无骨化），MRI看液体与神经（膜迷路内淋巴液信号是否完整、蜗神经是否存在及粗细）。这两点恰恰决定手术能否实施与电极能否插入——耳蜗骨化/纤维化时液体高信号消失，需改变手术策略；蜗神经缺如则人工耳蜗无效，应考虑听觉脑干植入。技术上必须用亚毫米各向同性的三维重T2水成像，并重建垂直于内听道长轴的斜矢状面——只有在这个方位上四条神经束才呈现为“田”字形排列的四个低信号点，可逐一辨认。前下为蜗神经，前上为面神经，后方为前庭上、下神经。【为什么错】B 4 mm层厚远大于蜗神经直径（约1 mm），根本无法分辨神经束，也无法评估耳蜗各回的液体信号。C DWI在颞骨区变形严重、分辨率低，用于胆脂瘤而非神经计数。D迷路动脉过于细小，且血管与神经发育不能互相推断。E蜗神经为正常神经组织，不会强化；增强主要用于排查内听道占位与迷路炎，不能作为“存在与否”的判据。", "tr": "本题的高阶要点是“斜矢状面重建才能数清四条神经”。很多技师只提供横断面原始图像，导致临床无法回答蜗神经有无的问题。另需注意患儿镇静时的听力防护与全程生命体征监护，以及bTFE类序列在3.0T的带状伪影，必要时改用三维TSE类水成像。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0174", "t": "单选题", "s": "肺实质MRI成像质量明显差于CT，其最主要的物理原因是", "o": {"A": "肺组织内含大量气—组织界面造成磁化率差异极大而使T2*极短（1.5T约2 ms、3.0T更短），同时肺实质质子密度很低，加之呼吸与心脏搏动，信号采集极为困难", "B": "肺组织的T1过短导致信号饱和", "C": "肺内脂肪含量过高，脂肪抑制困难", "D": "肺组织的化学位移过大", "E": "肺内血流速度过快导致流入增强过强"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-001", "kp": "肺MRI的物理局限", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确。肺MRI面临三重不利：①质子密度低——肺实质约80%为空气，可用质子远少于实质器官；②T2*极短——数以亿计的肺泡壁与空气形成微观磁化率界面，局部磁场梯度巨大，横向磁化在毫秒级即衰减殆尽，常规序列的TE往往已错过信号；③运动——呼吸与心脏搏动叠加。对策是采用超短回波时间（UTE）或零回波时间（ZTE）序列把TE压至微秒级、采用屏气单次激发TSE（SSh-TSE/HASTE/SSFSE）快速采集，或使用放射状/螺旋采集配合自导航。【为什么错】B错误：问题不在T1，而在T2*与质子密度。C错误：肺实质本身不含大量脂肪，脂肪抑制不是肺MRI的核心矛盾。D错误：化学位移由分子结构决定，肺组织并无特殊的大化学位移。E错误：肺血流并不特别快，流入增强也不是导致图像质量差的原因。", "tr": "尽管肺实质成像困难，MRI在胸部仍有明确优势：评估胸壁与胸膜侵犯、肺上沟瘤对臂丛与锁骨下血管的侵犯、纵隔囊性与实性病变鉴别、心包与大血管关系、以及无辐射的随访（如儿童与孕妇）。答题时不要把“肺实质成像差”扩大为“胸部MRI无用”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0175", "t": "单选题", "s": "乳腺动态增强MRI（DCE-MRI）对时间分辨率有明确要求，其根本原因是", "o": {"A": "需在注药后的早期时相（约1—2 min内）捕捉病灶的强化速率与峰值，并在延迟期观察廓清，从而绘制时间—信号强度曲线并区分持续上升型、平台型与流出型，故单期采集时间通常须控制在60—90 s以内，且需覆盖注药前至注药后约6—8 min", "B": "时间分辨率越低越好，可提高空间分辨率而不影响曲线判读", "C": "只需注药后8 min扫一期即可判断良恶性", "D": "时间分辨率的意义仅在于缩短患者检查时间", "E": "乳腺DCE不需要平扫作为基线"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-002", "kp": "乳腺DCE的时间分辨率要求与曲线类型", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确。乳腺DCE的诊断信息来自“形态＋动力学”两部分，动力学部分依赖时间—信号强度曲线：Ⅰ型持续上升多见于良性，Ⅱ型平台型为中间型，Ⅲ型早期快速强化后廓清（流出型）高度提示恶性。恶性病灶的强化峰值多出现在注药后1—2 min，若单期时间过长就会跨过峰值、把“快进快出”平均成“持续上升”，造成动力学信息失真。因此单期采集时间一般控制在60—90 s以内（多数中心约60 s），并采集注药前基线1期与注药后连续5—6期覆盖至6—8 min。【为什么错】B错误：这是典型的时间—空间分辨率权衡误判，时间分辨率不足会直接毁掉曲线判读。C单期延迟扫描无法获得任何动力学信息，且延迟期良恶性强化程度可能接近。D错误：时间分辨率首先是诊断信息的需要，缩短检查时间只是附带效果。E错误：平扫是计算强化率与绘制曲线起点的必需基线，也用于识别病灶本身的T1高信号（如出血、含蛋白囊肿）。", "tr": "乳腺DCE的其他配套要点常一起考：绝经前女性宜安排在月经周期第7—14天（避开背景实质强化高峰）；俯卧位专用乳腺相控阵线圈、双侧同时成像、双乳自然悬垂不受压；横断面相位编码方向常取左右向，使心脏搏动鬼影沿左右方向传播而不覆盖乳腺组织。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0176", "t": "多选题", "s": "关于乳腺MRI的检查条件与体位技术，下列说法正确的有", "o": {"A": "绝经前女性宜安排在月经周期第7—14天检查，此期背景实质强化（BPE）最低，可减少假阳性", "B": "采用俯卧位专用乳腺相控阵线圈，双乳自然悬垂于线圈孔内，避免受压变形；双侧同时成像便于左右对照", "C": "常规包含脂肪抑制T2WI（或Dixon）、DWI与动态增强T1WI；DWI可提供ADC信息辅助鉴别，但受呼吸运动与磁敏感影响，须注意其分辨率低于形态学序列", "D": "扫描范围应包含双侧腋窝，以评估腋窝淋巴结", "E": "为提高患者舒适度，乳腺MRI应采用仰卧位并加压固定双乳"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-003", "kp": "乳腺MRI的时机、体位与序列组合", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确：激素水平影响乳腺腺体的血供与强化，黄体期BPE明显升高会掩盖小病灶或造成假阳性，故推荐在月经周期第2周检查；哺乳期与激素替代治疗者同样需注意。B正确：俯卧使乳腺远离胸壁与心脏、减少呼吸运动传递，自然悬垂避免组织重叠与压迫伪影；双侧同时成像既提高效率又便于对称性判断。C正确：多参数组合是当前乳腺MRI的标准，DWI的加入可降低单纯依赖强化模式的假阳性，但其空间分辨率与磁敏感稳定性不及T1/T2序列，不能替代形态学与动力学评估。D正确：腋窝淋巴结状态直接影响分期与治疗，遗漏腋窝是常见的范围错误。【为什么错】E错误：仰卧加压是乳腺X线摄影（钼靶）的体位逻辑，不适用于MRI。仰卧位会使乳腺摊平在胸壁上、与心肺运动直接耦合、组织重叠增加，且加压会改变血流灌注影响动态曲线，是完全错误的做法。", "tr": "E把X线摄影的“压迫”经验错误迁移到MRI。要牢记两种检查的物理逻辑完全不同：钼靶靠压迫减少组织重叠与辐射剂量；MRI靠俯卧悬垂减少运动与重叠，绝不能加压。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0177", "t": "多选题", "s": "尽管肺实质MRI受限，胸部MRI在下列情形中仍具有明确临床价值的有", "o": {"A": "评估肺尖部肿瘤（肺上沟瘤）对臂丛神经、锁骨下动静脉与椎体的侵犯范围", "B": "判断周围型肺癌或胸膜病变对胸壁、膈肌与心包的侵犯", "C": "鉴别纵隔囊性与实性病变（如支气管囊肿、胸腺囊肿与胸腺瘤），并评估其与大血管的关系", "D": "对需反复随访的年轻患者或孕妇，提供无电离辐射的替代或补充手段", "E": "作为肺内磨玻璃结节筛查的首选方法，敏感性高于低剂量CT"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-004", "kp": "胸部MRI的适应证定位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确：MRI的多平面成像与优异的软组织对比使其在显示臂丛神经与血管受累方面明显优于CT，是肺上沟瘤术前评估的标准手段。B正确：胸膜外脂肪层是否连续、胸壁肌肉信号是否异常、膈肌与心包是否受累，MRI判断能力优于CT。C正确：MRI能通过T2信号与增强特征明确区分囊性与实性，避免囊肿被误判为肿瘤。D正确：无辐射是MRI的固有优势，在需长期随访的良性病变、青少年与妊娠人群中价值突出。【为什么错】E错误：磨玻璃结节的检出与随访依赖高空间分辨率与对微小密度差异的敏感性，这正是CT的强项而MRI的短板；肺实质T2*极短、质子密度低使MRI对亚厘米磨玻璃病灶敏感性很低，低剂量CT才是肺癌筛查的标准方法。", "tr": "本题要建立“扬长避短”的技术判断力：MRI在胸部的优势在软组织与血管神经关系，短板在肺实质细节。切勿因“MRI无辐射”而在肺结节筛查这类问题上误选。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0178", "t": "案例分析题", "s": "患者女，42岁，因右乳肿块行乳腺MRI。图像回顾发现：脂肪抑制T2WI上右乳外侧与双侧腋窝脂肪抑制不完全、呈片状高信号；动态增强图像上双乳边缘可见沿前后方向的重复轮廓，病灶边界模糊；此外增强各期之间腺体位置有明显位移。设备为飞利浦3.0T，采用俯卧位乳腺专用线圈，脂肪抑制方式为SPAIR。下列改进措施组合最合理的是", "o": {"A": "脂肪抑制不均源于大FOV边缘与腋窝区B₀不均匀，可先做局部匀场并把匀场框精确覆盖双乳，或改用Dixon水脂分离获得更均匀的抑制；重复轮廓提示运动/呼吸伪影，应重新摆位使双乳稳定悬垂、加用衬垫固定并强调保持不动；各期位移应在后处理中做动态序列的运动配准，必要时缩短单期采集时间以减少期内运动", "B": "把脂肪抑制由SPAIR改为STIR，并在增强各期沿用", "C": "增大FOV至400 mm并降低分辨率，可同时解决脂肪抑制与运动问题", "D": "取消动态增强，仅保留平扫T2WI与DWI", "E": "把相位编码方向由左右改为前后，可消除重复轮廓"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-BRT-005", "kp": "乳腺MRI脂肪抑制不均与运动伪影的排查", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A正确，三个问题逐一对应。①脂肪抑制不均：SPAIR属频率选择性方法，依赖B₀均匀；双乳同时成像的FOV大、腋窝与胸壁交界处磁场畸变明显，边缘区脂肪峰频率偏移导致抑制失败。对策是精确局部匀场（把匀场容积框限定在双乳范围）或改用Dixon类水脂分离，后者对B₀不均匀的耐受性明显更好且可在增强后使用。②重复轮廓：沿相位编码方向的规律性重影是运动鬼影的典型表现，源头是呼吸传递与体位不稳，应重新摆位、使双乳充分悬垂并用衬垫限制活动，同时充分沟通。③各期位移：动态序列间的位移必须通过后处理的运动配准纠正，否则减影图会出现假性强化与假性充盈缺损；缩短单期时间也可减少期内运动模糊。【为什么错】B错误：STIR基于T1抑制，增强后会误抑制强化组织，导致病灶信号丢失，是增强后的禁忌选择。C增大FOV并降低分辨率既不改善B₀均匀性，又牺牲了小病灶（乳腺MRI要求能分辨≤5 mm病灶）的检出，属于以诊断质量换表观改善。D取消动态增强等于放弃乳腺MRI最核心的诊断信息，本末倒置。E错误：乳腺横断面本就应把相位编码设为左右方向，使心脏搏动鬼影沿左右传播而不覆盖乳腺；改为前后方向反而会让心脏与胸壁运动的鬼影直接叠加到乳腺上，方向完全相反。", "tr": "E是精心设计的反向陷阱，考的是“乳腺横断面相位编码方向为何取左右”。另一个高频失分点是B：把STIR当作万能脂肪抑制而忽略其在增强后的禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0179", "t": "单选题", "s": "心脏电影成像普遍采用平衡稳态自由进动序列（bTFE/TrueFISP/FIESTA），其主要原因是", "o": {"A": "该序列信号强度近似正比于T2/T1，血液的T2/T1比值高而心肌低，可在不使用对比剂、不依赖血液流入的情况下获得极高的血池—心肌对比与信噪比，且TR极短便于在一次屏气内完成多时相采集", "B": "该序列依赖血液流入效应，故血池呈高信号", "C": "该序列对磁场不均匀不敏感，在3.0T上不会出现任何伪影", "D": "该序列为自旋回波类序列，血液呈流空低信号", "E": "该序列必须注射钆剂后才能显示心腔"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-CMR-001", "kp": "电影bTFE的对比机制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】A正确。平衡稳态自由进动在稳态下所有梯度在每个TR内完全平衡，横向磁化被保留并循环利用，稳态信号强度近似正比于√(T2/T1)（常简述为T2/T1比值）。血液的T2/T1比值远高于心肌，故血池明亮、心肌灰暗，形成高对比；由于对比来源是组织固有弛豫特性而非流入效应，即使在血流缓慢的心尖、心耳或严重心功能不全者中仍能保持对比，这正是它取代早期梯度回波电影的原因。极短的TR（2—4 ms）使一次屏气内可获得20—30个心动时相。【为什么错】B错误：这是扰相梯度回波（流入增强）的机制；bTFE的优势恰恰在于不依赖流入。C错误：bTFE对B₀不均匀高度敏感，3.0T下极易出现带状（banding/off-resonance）伪影，需要在扫描前做频率校正（frequency scout）或缩短TR、局部匀场，这是3.0T心脏检查的常规步骤。D错误：bTFE是梯度回波类序列，血液呈高信号；血液流空低信号是黑血自旋回波类序列的特征。E错误：bTFE电影是平扫技术，无须对比剂。", "tr": "C是必须记住的3.0T实操要点：场强越高、TR越长，带状伪影越明显。对策包括扫描前频率校正、缩短TR、精细匀场；若仍无法克服，可改用扰相梯度回波电影（对比略差但无带状伪影）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0180", "t": "案例分析题", "s": "患者男，68岁，扩张型心肌病，持续性心房颤动，心室率90—130次/分、绝对不齐，屏气仅能维持约8 s。临床要求评估左室容积、射血分数与心肌纤维化。设备为飞利浦3.0T，具备压缩感知加速。首次采集的短轴电影出现明显的层间对位不齐与心肌边界模糊，延迟强化图像可见弥漫条状伪影。下列对策组合最合理的是", "o": {"A": "启用实时（real-time）电影或单心跳采集的加速电影（结合压缩感知与并行采集），必要时改自由呼吸多次平均采集；心电门控改用矢量心电并优化电极位置，开启心律失常剔除（arrhythmia rejection）设定合适的RR间期接受窗；延迟强化改用单次激发结合相位敏感反转恢复（single-shot PSIR）以降低对屏气与心律的依赖；把每次屏气任务缩短到8 s以内并在呼气末统一屏气位置", "B": "增加平均次数并延长屏气至20 s，以提高信噪比", "C": "放弃心电门控，改用外周脉搏门控可获得更准确的心动时相", "D": "改用自旋回波黑血序列采集电影以避免心律影响", "E": "告知临床心房颤动为心脏MRI绝对禁忌，建议取消检查"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-CMR-002", "kp": "心律失常与屏气困难时的CMR对策", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】A正确，每一条都直击一个失败环节。①分段采集失败：常规电影把数据分散到十余个心动周期采集，房颤时RR间期长短不一使各段的心脏位置与时相不一致，导致边界模糊；实时电影在单个心动周期内完成一帧图像采集，牺牲部分时空分辨率换取对心律的免疫，配合压缩感知可部分弥补分辨率损失。②门控错误：3.0T磁流体动力学效应使T波抬高易被误触发，矢量心电与优化电极位置可改善；心律失常剔除功能可丢弃落在接受窗外的心搏。③屏气受限：把每次屏气任务压到8 s以内，统一在呼气末屏气（位置最稳定、可重复），或改自由呼吸配合导航/多次平均。④延迟强化：单次激发PSIR在一个心跳内完成一层采集，对TI精度与屏气时长的依赖大幅降低，是房颤患者LGE的标准替代方案。【为什么错】B延长屏气到20 s对本例不可行，且增加平均次数无法解决心律不齐造成的相位不一致，只会把不一致的数据平均得更模糊。C外周门控的时相精度远低于心电门控（存在数百毫秒延迟且波形圆钝），用于心脏电影会使收缩末期与舒张末期判定错误，容积与射血分数失真。D黑血自旋回波序列采集慢、不能生成电影，且同样依赖门控，方向错误。E错误：房颤是CMR的技术挑战而非绝对禁忌，通过上述技术手段多数可获得可用图像；绝对禁忌指的是不可扫描的植入物、无法配合的危重状态等。", "tr": "本题综合了门控、屏气、序列与重建四个层面，是心脏MR的典型现场难题。要点提炼：心律不齐→实时/单心跳采集＋心律失常剔除＋矢量心电；屏气差→缩短单次任务、呼气末屏气、单次激发PSIR、自由呼吸导航。切勿用“增加平均次数”这种信噪比手段去解决时相一致性问题。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0181", "t": "单选题", "s": "关于钆塞酸二钠（Gd-EOB-DTPA）肝胆特异期（肝细胞期）的延迟采集时间，正确的是", "o": {"A": "注射后即刻（<1 min）", "B": "动脉期（20~30 s）", "C": "平衡期（3~5 min）", "D": "肝胆特异期（约20 min）", "E": "延迟期（10 min）"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-181", "kp": "钆塞酸二钠（Gd-EOB-DTPA）肝胆特异期延迟时间", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】钆塞酸二钠约50%经肝细胞摄取经胆道排泄，肝胆特异期（肝细胞期）通常在注药后约20 min采集，此时正常肝实质因摄取对比剂明显强化、与胆道及病灶对比最佳，是检出小肝癌及评估肝功能/胆道的关键时相。【为什么错】A/B为动脉期及早期强化时相，用于富血供病灶；C/E为平衡/延迟期，肝胆摄取尚未充分，不能代表特异期。", "tr": "易把肝胆特异期误记为10 min或平衡期；实际Gd-EOB肝胆期标准延迟约20 min，严重肝功能不全者需延长至30~40 min。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0182", "t": "多选题", "s": "关于Gd-EOB-DTPA注射流率对动脉期与肝胆特异期成像质量的影响，以下正确的是", "o": {"A": "注射流率偏低（如1 mL/s）可造成动脉期峰值延迟、强化幅度下降", "B": "为获得理想动脉期，流率可取2 mL/s并配合生理盐水冲管", "C": "肝胆特异期肝实质强化程度与注射流率无关，只取决于注药总量", "D": "对比剂外渗会同时削弱动脉期与肝胆期强化", "E": "采用高压注射器团注可提高动脉期峰值浓度，利于小病灶显示"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-182", "kp": "Gd-EOB-DTPA注射流率对多期相与肝胆期的影响", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】团注流率影响动脉期峰值浓度与到达时间，2 mL/s配合盐水冲管可获得锐利动脉期；流率过低使峰值后延、幅度降低，小肝癌「快进快出」显示不清；外渗则总量不足，两期均减弱。【为什么错】C错：肝胆期信号虽主要取决于肝细胞摄取功能与总量，但流率过低致外渗或注射不全同样削弱肝胆期，且摄取动力学受团注质量影响。", "tr": "误以为肝胆期只与总量无关流率；实际上团注完整性与是否外渗同样影响肝胆期信噪比。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0183", "t": "案例分析题", "s": "患者男性，58岁，体检发现胰腺占位，临床拟诊胰腺神经内分泌肿瘤，拟行胰腺MR多期相动态增强扫描以评估病灶血供特征。关于该检查方案的序列与参数设计，最合理的是", "o": {"A": "单层动态梯度回波T1WI，层厚8 mm，无脂肪抑制，延迟期采集", "B": "3D容积 interpolated 梯度回波（eTHRIVE / VIBE / LAVA）薄层（3 mm）同反相位+多期动态+fs，动脉期用自动触发", "C": "仅做MRCP重T2加权，不做增强", "D": "屏气单次激发FSE T2WI厚层评估胰腺", "E": "只用DWI取代增强评估胰腺病变"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-183", "kp": "胰腺MR多期相动态增强方案设计", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】胰腺血供丰富、病灶（如神经内分泌瘤、腺癌）强化特征依赖多期相；应采用3D薄层梯度回波（飞利浦eTHRIVE）同反相位观察脂肪浸润/脂质瘤，加SPAIR脂肪抑制抑制腹腔脂肪，多期动态（动脉/门脉/延迟）并配合团注追踪触发捕获动脉期，层厚3 mm避免遗漏小病灶。【为什么错】A层厚过厚且无抑脂、只延迟期会漏动脉期与微小病灶；C仅MRCP看胰管不评估实质；D/E均不能评价强化。", "tr": "以薄层T2或MRCP替代动态增强；胰腺小病灶（如胰岛素瘤）高度依赖动脉期强化，必须薄层多期+抑脂。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0184", "t": "单选题", "s": "采用化学位移同相位/反相位成像判断肾上腺含脂腺瘤时，其典型表现是", "o": {"A": "反相位信号明显高于同相位（病灶含脂）", "B": "同相位信号高于反相位（病灶含脂，化学位移相消致反相位信号下降）", "C": "同、反相位信号相等", "D": "反相位信号高于同相位且边界清晰", "E": "仅T2WI能判断，化学位移序列无意义"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-184", "kp": "肾上腺同反相位化学位移成像判断脂质腺瘤", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】含脂腺瘤在反相位（out-of-phase，水脂相位相反）因水脂信号相消而信号明显低于同相位（in-phase），称「信号丢失」；这是无创诊断良性腺瘤的核心征象。【为什么错】A/D说反相位更高属颠倒；C无差别不支持腺瘤；E否定化学位移价值错误。", "tr": "混淆同/反相位方向：记住反相位（水脂抵消）含脂病灶信号「下降」即反相位低于同相位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0185", "t": "多选题", "s": "关于肾上腺化学位移成像中\"勾边征\"（India ink artifact）的机制与表现，以下正确的是", "o": {"A": "含脂病灶在反相位与同相位交界出现线状低信号勾边（India ink artifact）", "B": "勾边征是水脂界面化学位移伪影，非真正结构", "C": "同相位图像上该勾边最明显", "D": "相位编码方向决定勾边出现于病灶左右还是上下边缘", "E": "勾边征提示病灶恶性"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-185", "kp": "肾上腺化学位移勾边征（India ink artifact）机制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】水脂化学位移使同反相位交界在相位编码方向出现黑线（勾边），是含脂腺瘤的辅助征象，位置由相位编码方向决定。【为什么错】C错：勾边在反相位最显著；E错：勾边是良性含脂表现而非恶性标志。", "tr": "把India ink勾边误判为坏死或出血边界；它纯属化学位移伪影，且总是反相位明显。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0186", "t": "单选题", "s": "关于心脏T2* mapping铁沉积定量的阈值判读，正确的是", "o": {"A": "T2*值>40 ms 提示重度铁过载", "B": "T2*值<20 ms（室间隔ROI）提示心脏铁过载，<10 ms为重度", "C": "T2* mapping 不受磁场不均匀影响，无需匀场", "D": "肝铁过载分级按T2*升高程度判断", "E": "R2*（1/T2*）与铁浓度呈负相关"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-186", "kp": "心脏T2* mapping铁沉积定量阈值分析", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】心脏T2* mapping在室间隔放置ROI，正常约>20 ms；<20 ms提示铁过载，<10 ms为重度，需祛铁治疗并监测心功能，属定量决策指标。【为什么错】A颠倒（应降低）；C错，T2* mapping对B0不均极敏感需仔细匀场及多回波拟合；D肝铁过载是T2*下降（R2*升高）而非升高；E错，R2*与铁浓度正相关。", "tr": "混淆T2*与铁浓度关系：铁越多T2*越短、R2*越大，阈值<20 ms（心）<10 ms重度。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0187", "t": "单选题", "s": "前列腺多参数MRI（mpMRI）的核心三要素是", "o": {"A": "仅T2WI平扫即可完成前列腺癌筛查", "B": "T2WI + 高b值DWI（b=1400~2000） + DCE动态增强三要素联合（mpMRI）", "C": "仅DCE增强", "D": "仅T1WI + DWI", "E": "MRS alone"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-187", "kp": "前列腺多参数MRI（mpMRI）三要素", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】PI-RADS v2.1要求mpMRI包含T2WI（解剖）、高b值DWI（b≥1400，观察受限弥散）、DCE（评价早期强化），三者互补提高癌灶检出与定位。【为什么错】单一序列敏感性不足，A/C/D/E均不完整。", "tr": "遗漏高b值DWI；移行带病变主要靠DWI与DCE，外周带主要靠T2WI，三者缺一不可。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0188", "t": "案例分析题", "s": "患者男性，62岁，肠镜确诊直肠癌，拟行术前MRI分期以评估环周切缘（CRM）。关于直肠癌高分辨率MRI的扫描方案，最合理的是", "o": {"A": "横轴位（平行于坐骨结节连线）即可准确评估系膜筋膜", "B": "高分辨斜轴位垂直于肿瘤长轴（或垂直肛管）薄层（3 mm）T2WI，使肿瘤与直肠系膜筋膜（MRF）关系显示最佳", "C": "仅做冠状位评估CRM", "D": "厚层（5 mm以上）快速T2WI筛查", "E": "不做T2WI，仅凭DWI判断CRM受累"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-188", "kp": "直肠癌高分辨率MRI斜轴位与环周切缘（CRM）评估", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】直肠癌术前分期要求高分辨薄层（≤3 mm）T2WI，斜轴位应垂直于肿瘤长轴（无法判定时垂直肛管），以最短距离显示肿瘤与直肠系膜筋膜（MRF）关系，CRM间距<1 mm为受累、影响保肛决策。【为什么错】A平行扫描会拉长显示距离造成低估；C冠状位不能精确测最短CRM；D厚层漏小病灶；E DWI不能替代解剖CRM测量。", "tr": "用平行轴位评估CRM导致间距被高估、漏诊系膜筋膜受侵；务必斜轴垂直肿瘤长轴薄层。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0189", "t": "多选题", "s": "关于子宫MRI随月经周期的信号变化与DCE增强时相表现，以下正确的是", "o": {"A": "增殖期子宫内膜在T2WI呈高信号（分泌期相对变薄、信号略降）", "B": "DCE增强早期（动脉期）子宫内膜及肌层内层明显强化", "C": "月经周期不影响子宫各层信号，无需记录", "D": "结合带（junctional zone）在T2WI为低信号，是肌层内带", "E": "带环（IUD）产生磁敏感伪影但一般不影响评估"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-189", "kp": "子宫MRI月经周期信号特征与DCE时相", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】子宫内膜随周期变化：增殖期厚且T2高信号，分泌期相对变薄；DCE早期内膜与结合带、肌层分层强化；结合带为低信号内肌层；IUD伪影通常可识别不影响诊断。【为什么错】C错，周期显著影响信号，应在报告注明经期。", "tr": "忽略月经周期对内膜信号影响而误判病变；增强时相需区分内膜与肌层强化时序。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0190", "t": "单选题", "s": "关于盆腔肿块DWI高b值与ADC值的判读，正确的是", "o": {"A": "ADC值越低提示弥散受限，多见于恶性实性肿块", "B": "ADC值越高越支持恶性", "C": "DWI在盆腔无需高b值", "D": "囊性病灶ADC一定高于实性，无重叠", "E": "DWI不能鉴别良恶性，无价值"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-190", "kp": "盆腔肿块DWI高b值与ADC值判读", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】恶性实性肿块细胞密集、 extracellular space小，弥散受限，高b值DWI高信号且ADC降低；定量ADC辅助鉴别。【为什么错】B颠倒；C错，盆腔需高b值（如800~1000）提高对比；D/E绝对化错误。", "tr": "把ADC高低方向记反；并避免「ADC无重叠」绝对化——需结合形态与强化。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0191", "t": "单选题", "s": "膝关节MRI中，为最佳显示半月板体部与前交叉韧带，斜冠状位的定位应是", "o": {"A": "斜冠状位平行于股骨内外髁连线", "B": "斜冠状位垂直于胫骨平台且垂直于前交叉韧带（ACL）走行", "C": "斜冠状位平行于髌骨长轴", "D": "斜矢状位用于评价半月板前后角", "E": "轴位是评估交叉韧带唯一序列"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-191", "kp": "膝关节专用斜冠状位定位（垂直ACL/胫骨平台）", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】膝斜冠状位应垂直于胫骨平台并垂直于ACL走行，以最佳显示半月板体部、交叉韧带及关节软骨；常规配PDWI-SPAIR脂肪抑制。【为什么错】A平行平台会扭曲ACL显示；C/D/E描述不全或错，矢状位看半月板前后角及ACL，但斜冠状定位核心是垂直ACL。", "tr": "将斜冠状位误设为平行平台；正确应垂直平台且垂直ACL，否则半月板与韧带显示不佳。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0192", "t": "多选题", "s": "关于踝关节韧带MRI的斜位定位与PDWI脂肪抑制应用，以下正确的是", "o": {"A": "距腓前韧带（ATFL）在踝关节斜轴位（垂直胫腓骨）显示最佳", "B": "三角韧带（deltoid）在斜冠状位观察", "C": "PDWI加SPAIR/SPIR脂肪抑制可提高韧带与骨髓水肿对比", "D": "全手足线圈可同时覆盖双踝，但信噪比下降需延长平均", "E": "T1WI是评估韧带撕裂首选"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-192", "kp": "踝关节韧带斜位定位与PDWI脂肪抑制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】ATFL在斜轴位（垂直小腿长轴/胫腓骨）显示，三角韧带在斜冠状位；PDWI配脂肪抑制（SPAIR/SPIR）显著增强韧带-脂肪及骨髓水肿对比；小线圈或表面线圈提升SNR。【为什么错】E错，韧带评估首选PD/T2*加权脂肪抑制而非T1WI（T1看解剖不敏感水肿）。", "tr": "误用T1WI评估急性韧带损伤；急性撕裂伴水肿需脂肪抑制PD/T2*，T1对水肿不敏感。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0193", "t": "案例分析题", "s": "患者女性，55岁，肩关节外展上举无力伴夜间痛，怀疑肩袖撕裂。关于肩关节MRI斜冠状位定位与肩袖、盂唇损伤评估方案，最合理的是", "o": {"A": "常规斜冠状位平行于肩胛冈即可，无需脂肪抑制", "B": "斜冠状位垂直冈上肌腱长轴（平行于盂肱关节面），PDWI-SPAIR评价肩袖全层撕裂，必要时Direct MR关节造影（钆稀释液关节内注射）显示部分层撕裂", "C": "仅轴位T1WI足够", "D": "用STIR替代所有脂肪抑制序列", "E": "怀疑Bankart损伤只做CT"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-193", "kp": "肩关节斜冠状位定位与肩袖/盂唇损伤方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】肩斜冠状位应垂直于冈上肌腱（平行于关节面）以显示肌腱全长的连续中断；PDWI-SPAIR对全层撕裂敏感；部分层撕裂或Bankart/SLAP在常规MRI不确定时，Direct MR关节造影（稀释钆注入关节腔）使对比剂进入撕裂缝隙提高检出。【为什么错】A平行肩胛冈会斜切肌腱；C轴位T1不足；D STIR抑制脂肪但肌腱对比不及PDWI-SPAIR且增强后不可用；E CT不显示软组织。", "tr": "部分层肩袖撕裂常规MRI易漏，需脂肪抑制PDWI并考虑关节造影；斜冠状务必垂直冈上肌腱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0194", "t": "单选题", "s": "腕关节MRI中，为显示舟月韧带、月三角韧带及三角纤维软骨复合体（TFCC），应采用的定位方案是", "o": {"A": "轴位即可完整显示TFCC与舟月韧带", "B": "斜冠状位（沿腕骨弧线/垂直桡骨茎突）显示舟月骨、月三角韧带，斜矢状位显示TFCC三角纤维软骨", "C": "只做矢状位", "D": "腕关节无需脂肪抑制", "E": "线圈用头部线圈更佳"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-194", "kp": "腕关节斜冠状/斜矢状位定位与TFCC显示", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】腕斜冠状位沿腕骨排列并垂直桡骨茎突，可显示舟月（SL）、月三角（LT）韧带；斜矢状位（沿第3掌骨-桡骨）显示三角纤维软骨复合体（TFCC）及月骨缺血改变；常配PDWI脂肪抑制。【为什么错】A轴位不能显示韧带连续走行；C/D/E均不正确，脂肪抑制有助于水肿/积液显示，应使用小柔性线圈。", "tr": "腕韧带需沿其走行斜位显示，轴位易漏舟月分离；TFCC在斜矢状位最佳。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0195", "t": "多选题", "s": "关于下肢非对比增强MRA（TRANCE/NATIVE/Inhance）及其流敏感伪影，以下正确的是", "o": {"A": "非对比增强MRA（飞利浦Inhance 3D / TRANCE / NATIVE SPACE）利用血流与背景组织对比，无需钆剂", "B": "该类序列对慢血流、远端小动脉及支架术后患者友好，避免肾源性系统性纤维化（NSF）风险", "C": "流敏感伪影（flow-related dephasing）在弯曲血管或湍流处可造成信号丢失误认为狭窄", "D": "CE-MRA总是优于NE-MRA，应一律首选", "E": "配合心电门控/导航可减少运动与搏动伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-195", "kp": "下肢非对比增强MRA（TRANCE/NATIVE/Inhance）与流敏感伪影", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (9)外周血管", "ex": "【为什么对】Inhance/TRANCE/NATIVE 3D采用流动敏感散相与恢复技术获得血管内高信号，免钆剂、适合肾功能不全及支架术后；慢血流与远端血管显示好；但湍流/弯曲处流敏感伪影可致假阳性狭窄；门控导航可减伪影。【为什么错】D绝对化错误，NE-MRA有局限（扫描时间长、对严重钙化/湍流敏感），并非一律优于CE-MRA。", "tr": "将流敏感伪影误判为真实闭塞；NE-MRA弯曲段信号丢失不代表狭窄，需结合源图与TOF。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-0196", "t": "案例分析题", "s": "患者男性，45岁，右上肢麻木无力，怀疑臂丛神经病变。为显示神经走行并鉴别神经源性肿瘤，最合适的MR神经成像方案是", "o": {"A": "常规DWI即可区分神经根与神经鞘瘤，无需特殊序列", "B": "3D STIR SPACE（重T2加权三维采样完美梯度回波）加脂肪抑制显示神经走行，结合T2映射与增强鉴别神经源性肿瘤与神经根鞘膜，脂肪抑制失败时应调整频率/匀场或改用DIXON", "C": "仅T1WI平扫", "D": "用CE-MRA替代神经成像", "E": "MR neurography 对神经根病无价值"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-196", "kp": "MR神经成像（MR neurography）3D STIR SPACE技术与伪影对策", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (10)外周神经", "ex": "【为什么对】MR神经成像用重T2加权3D SPACE（飞利浦3D STIR SPACE / STIR TSE）配合优异脂肪抑制使神经呈高信号、连续显示走行；可区分神经鞘瘤（神经外膜包绕、靶征）与神经根/神经束；脂肪抑制失败（B0不均、金属）时需重设中心频率、精细匀场或采用DIXON水脂分离。【为什么错】A/D/E低估或错代技术；常规DWI不能替代解剖性神经成像，CE-MRA看血管非神经。", "tr": "脂肪抑制不均致神经-脂肪对比丧失误为「神经中断」；务必确认抑脂成功，必要时DIXON或调整中心频率。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0197", "t": "单选题", "s": "关于心脏黑血双反转恢复（Double IR）序列的原理与应用，正确的是", "o": {"A": "黑血成像采用双反转恢复（Double IR）预脉冲抑制血液与脂肪，慢轴位评估心肌与瓣膜", "B": "黑血成像无需抑制血液，血液天然呈高信号", "C": "黑血只能用心电门控，无法用导航", "D": "黑血序列必须用梯度回波", "E": "黑血对房颤患者无影响，触发设置可忽略"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-197", "kp": "心脏黑血双反转恢复（Double IR）序列原理", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】黑血（black-blood）常用双反转恢复（DIR，两次180°反转分别抑制血液与脂肪）配合快速自旋回波，使流动血液与脂肪均为低信号，突出心肌与血管壁；适合结构、血栓、瓣膜评估。【为什么错】B错，血液需主动抑制才呈黑；C/D错，黑血多为TSE且可配导航；E错，房颤时R-R不稳触发易失败需调整。", "tr": "误以为黑血靠血液自身流空；实际依赖双反转预脉冲主动抑制血液与脂肪信号。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0198", "t": "案例分析题", "s": "患者男性，60岁，高血压病史，超声提示左室肥厚，临床怀疑心肌淀粉样变。为定量评估心肌间质纤维化，关于心肌T1 mapping与ECV计算的方案，最合理的是", "o": {"A": "只测一次T1即可计算ECV，无需增强后", "B": "采用MOLLI/ShMOLLI获取原生T1与增强后（注药约15 min）T1，结合血细胞比容按 ECV=(1-Hct)×(1/T1myo−1/T1blood_post)/(1/T1blood_pre−1/T1blood_post) 计算细胞外容积", "C": "ECV仅用于心脏，不能反映弥漫纤维化", "D": "增强后T1测量越早越好（<2 min）", "E": "T1 mapping 不需匀场"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-198", "kp": "心肌T1 mapping与ECV（细胞外容积）定量计算", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】T1 mapping（MOLLI/ShMOLLI）分别测得原生T1与钆对比剂分布后（约15 min）T1，结合血池T1与Hct按公式算ECV，定量心肌间质扩增（纤维化、淀粉样变、水肿）。【为什么错】A错需增强后配对；C错ECV正是评估弥漫纤维化的关键；D过早测量对比剂未平衡且受廓清影响；E T1 mapping对B1+/B0敏感需校准匀场。", "tr": "增强后T1测量时机错误（太早）或漏测血池T1与Hct，致ECV公式分母错误；务必采集原生与增强后血池。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0199", "t": "单选题", "s": "关于心肌T2 mapping在急性心肌水肿/心肌炎中的定量应用，正确的是", "o": {"A": "T2 mapping 用多TE的T2-prep bSSFP，急性心肌炎/水肿时T2值升高（如>~55~60 ms）", "B": "T2 mapping 用短TE越少越好", "C": "T2 mapping 对水肿不敏感", "D": "心肌炎T2值降低", "E": "T2 mapping 仅用于铁定量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-199", "kp": "心肌T2 mapping急性水肿/心肌炎定量", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】T2 mapping采用多个T2准备时间（T2-prep）的bSSFP采集并拟合T2值；心肌水肿（急性心肌炎、心肌缺血再灌注）使T2升高，常以>55~60 ms为异常阈值，与T2WI黑血水肿相印证。【为什么错】B/C/D/E均错：多TE是必需、对水肿敏感、心肌炎T2升高而非降低、且不同于铁定量（T2* mapping）。", "tr": "混淆T2 mapping（水肿，T2升高）与T2* mapping（铁沉积，T2*降低）；两者临床意义相反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-0200", "t": "多选题", "s": "关于心肌首过灌注MR的技术要点与伪影对策，以下正确的是", "o": {"A": "心肌首过灌注（first-pass perfusion）采用饱和恢复梯度回波，注药同时连续采集观察强化达峰", "B": "腺苷/双嘧达莫负荷可诱发缺血节段灌注缺失", "C": "在成像层面近端加空间饱和带（sat band）抑制静脉血进入视野造成伪影", "D": "需心电门控（或心律稳定）以保证每心动周期相位一致", "E": "灌注伪影（呼吸、心律不齐）只能通过延长扫描解决，无序列对策"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-B07-200", "kp": "心肌首过灌注MR技术与伪影对策", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】首过灌注用饱和恢复GRE（如飞利浦Turbo Field Echo perfusion）团注钆同时屏气连续采集；腺苷负荷扩张冠脉暴露缺血；近端空间饱和带抑制上腔静脉/右心血液流入左室造成的亮带伪影；心电门控保证相位一致。【为什么错】E错，伪影可通过饱和带、门控、屏气训练、缩短TR及导航等多手段控制，并非只能延长时间。", "tr": "漏加空间饱和带致右心/静脉血亮带误为前壁强化；负荷灌注务必抑制静脉血并稳定心律。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1001", "t": "单选题", "s": "关于MR检查绝对禁忌证的叙述，错误的是", "o": {"A": "体内植入心脏起搏器者", "B": "颅内铁磁性动脉瘤夹者", "C": "体内植入人工耳蜗者", "D": "体内植入钛合金骨内固定钉者", "E": "眼内有铁磁性异物者"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-001", "kp": "MR绝对禁忌证", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】钛合金为弱磁性（非铁磁性）材料，目前临床大多数骨内固定钉为钛合金或非铁磁性材料，可安全行MR检查，并非绝对禁忌证，故D项错误，本题选D。\n【为什么错】A：心脏起搏器受主磁场与射频场干扰可致起搏失效，为绝对禁忌证，正确。B：铁磁性动脉瘤夹在磁场中可移位造成再出血，为绝对禁忌证，正确。C：人工耳蜗内含铁磁性磁体且射频可致损伤，为绝对禁忌证，正确。E：眼内铁磁性异物可致眼组织损伤，为绝对禁忌证，正确。", "tr": "区分“铁磁性植入物（绝对禁忌）”与“钛合金/非铁磁性植入物（可行检查）”，是最常见命题陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1002", "t": "单选题", "s": "下列不属于MR检查适应证的是", "o": {"A": "颅内占位性病变的定位定性", "B": "椎间盘突出的诊断", "C": "膝关节半月板损伤", "D": "妊娠妇女的常规胎儿筛查", "E": "乳腺病变的定性诊断"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-002", "kp": "MR适应证", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】妊娠本身是MR检查的相对禁忌而非适应证，且“常规胎儿筛查”并不作为MR的常规检查项目（超声为产前筛查首选），故D不属于适应证，本题选D。\n【为什么错】A：MR软组织对比度极佳，颅内占位定位定性为典型适应证，正确。B：MR对椎间盘与脊髓显示优于其他影像，为典型适应证，正确。C：MR是半月板、韧带损伤诊断的金标准，为典型适应证，正确。E：MR动态增强与DWI为乳腺病变定性重要手段，为典型适应证，正确。", "tr": "适应证与相对禁忌证常对举出题，妊娠受检应“权衡利弊、可做但不常规”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1003", "t": "单选题", "s": "MR检查前患者去除体表金属物品时，下列哪项可以不用去除", "o": {"A": "金属钥匙", "B": "机械手表", "C": "含金属拉链的外衣", "D": "全陶瓷义齿", "E": "金属发卡"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-003", "kp": "MR检查前准备", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】全陶瓷义齿不含任何金属成分，不受磁场影响，进入磁体间无需去除，故D正确。\n【为什么错】A：金属钥匙可被吸入磁体造成伤害与伪影，须去除，正确。B：机械手表含金属机芯且可被磁化损毁，须去除，正确。C：金属拉链可产生磁敏感性伪影，须去除或更换衣物，正确。E：金属发卡可产生伪影并可能被吸引移位，须去除，正确。", "tr": "“可摘义齿”是否去除的关键看有无金属支架；陶瓷义齿无需去除。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1004", "t": "单选题", "s": "对幽闭恐惧症患者行MR检查，下列处理措施错误的是", "o": {"A": "检查前充分沟通并让患者了解检查过程", "B": "采取头先进位并嘱患者闭目、深呼吸放松", "C": "给予适当镇静后再行检查", "D": "不顾患者恐惧强行完成全部检查", "E": "必要时陪同人员站在扫描间内安抚患者"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-004", "kp": "幽闭恐惧症处理", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】强制患者完成扫描会加重恐惧、诱发躁动，导致图像运动伪影甚至检查失败，正确做法是充分沟通、体位安抚、镇静或终止检查，故D项错误，本题选D。\n【为什么错】A：充分沟通缓解焦虑为规范做法，正确。B：闭目、深呼吸可减轻幽闭感，正确。C：必要时镇静（如地西泮）后检查为可行方案，正确。E：家属或陪同人员在符合安全规范时于扫描间安抚，有助于完成检查，正确。", "tr": "患者不配合的处理原则是“疏导而非强制”，先安抚、后药物、再考虑终止。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1005", "t": "单选题", "s": "关于妊娠期行MR检查的叙述，正确的是", "o": {"A": "妊娠期任何阶段均严禁行MR检查", "B": "妊娠期增强扫描应用钆对比剂是安全的", "C": "超声能提供足够信息时不首选MR", "D": "早孕期MR检查对胎儿绝对无影响", "E": "妊娠患者增强扫描应常规加大钆剂剂量"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-005", "kp": "妊娠期MR检查原则", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】产前超声是胎儿检查的首选方法，只有当超声信息不足、临床确需进一步明确时才考虑MR，且须权衡利弊并由医师决策，故C正确。\n【为什么错】A：妊娠并非MR绝对禁忌，需权衡利弊后进行，说法过于绝对。B：妊娠期应用钆对比剂应谨慎，仅在对母儿影响明确有利时使用，并非安全。D：早孕期器官形成期对电离辐射敏感，MR虽无电离辐射，但对其远期影响认识有限，不能说“绝对无影响”。E：妊娠患者应避免不必要的对比剂应用，更不能加大剂量。", "tr": "“妊娠期MRI”考点：无电离辐射≠无风险，增强钆剂妊娠期慎用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1006", "t": "单选题", "s": "TOF-MRA（时间飞跃法）的成像基础是", "o": {"A": "血流的流入增强效应", "B": "血流质子的相位变化", "C": "血流的T2*弛豫差异", "D": "外源性钆对比剂的T1缩短", "E": "脂肪信号被抑制后的反差"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-006", "kp": "TOF-MRA原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】TOF-MRA利用短TR反复激励使静止组织磁化饱和、信号压低，而流入成像层面的未饱和血液质子不断产生较高信号，即“流入增强效应”，故A正确。\n【为什么错】B：利用相位变化成像的是相位对比法PC-MRA，非TOF。C：T2*弛豫差异是SWI等磁敏感成像的基础。D：利用钆剂T1缩短的是CE-MRA（对比增强MRA）。E：脂肪抑制与TOF血管成像机制无关。", "tr": "TOF（流入增强）、PC（相位对比）、CE-MRA（对比增强）三种MRA机制必须分清。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1007", "t": "单选题", "s": "常规颅脑3D TOF-MRA扫描，翻转角（FA）通常设置为", "o": {"A": "5°～10°", "B": "20°～35°", "C": "60°～80°", "D": "90°", "E": "135°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-007", "kp": "TOF-MRA翻转角", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】3D TOF-MRA常用较小翻转角（约20°～35°），兼顾背景组织抑制与血流信号，故B正确。\n【为什么错】A：5°～10°翻转角过小，背景抑制不足、血流对比差。C：60°～80°为较大翻转角，常见于2D TOF。D：90°为激励脉冲的常用翻转角，用于常规自旋回波类序列。E：135°与常规成像无关，反转恢复180°脉冲常与之混淆。", "tr": "翻转角数值考点：3D TOF约20°～35°，2D TOF常用较大角（60°左右），勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1008", "t": "单选题", "s": "关于2D TOF与3D TOF-MRA的比较，叙述错误的是", "o": {"A": "2D TOF对缓慢血流较为敏感", "B": "3D TOF空间分辨率较高", "C": "3D TOF可采用更小体素提高细节显示", "D": "2D TOF层面内血流质子易发生饱和", "E": "3D TOF对慢血流显示优于2D TOF"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-008", "kp": "2D与3D TOF比较", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】2D TOF单层成像、每层血流持续流入，对慢血流更敏感；3D TOF在较大容积内多次激励，慢血流质子易被饱和而信号丢失，故“3D TOF对慢血流显示优于2D”的说法错误，本题选E。\n【为什么错】A：2D TOF对慢血流敏感，正确。B：3D TOF薄层采集、分辨率高，正确。C：3D TOF可用更小体素、细节好，正确。D：2D TOF血流沿层面内走行部分可发生饱和导致信号丢失，正确。", "tr": "颅内快血流用3D TOF、颈部及下肢慢血流多用2D TOF；慢血流饱和是3D TOF的固有缺点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1009", "t": "单选题", "s": "PC-MRA（相位对比法）中速度编码值（VENC）设置过低时，可能出现", "o": {"A": "背景信号增高", "B": "流动质子的相位卷褶（混叠）", "C": "血流信号完全消失", "D": "空间分辨率下降", "E": "扫描时间缩短"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-009", "kp": "PC-MRA速度编码", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】VENC代表能无混叠测量的最大流速。VENC设置过低时，血流速度超过编码范围，相位角超过±180°产生相位卷褶（混叠/aliasing），故B正确。\n【为什么错】A：背景抑制取决于静止组织的相位，与VENC高低无关。C：血流信号不会完全消失，而是相位错误。D：空间分辨率由矩阵、FOV等决定，与VENC无关。E：VENC不影响扫描时间。", "tr": "VENC过低→相位卷褶；VENC过高→流动敏感度下降、慢血流显示差；需按目标流速设定。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1010", "t": "单选题", "s": "CE-MRA（对比增强MRA）利用钆对比剂增强血管信号的机制是", "o": {"A": "缩短血液的T1弛豫时间", "B": "延长血液的T2弛豫时间", "C": "增强血液的流入效应", "D": "抑制周围脂肪信号", "E": "增大血流速度"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-010", "kp": "CE-MRA增强机制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】钆对比剂为T1短缩剂，使血液T1显著缩短，在T1加权快速梯度回波序列中呈现明显高信号，血管与周围组织对比增强，故A正确。\n【为什么错】B：钆剂主要缩短T1，高浓度时也可缩短T2，但“延长T2”不正确。C：流入增强是TOF-MRA的机制。D：脂肪抑制仅改善背景，非增强机制。E：对比剂不改变血流速度。", "tr": "CE-MRA＝重T1加权＋钆剂团注；与TOF（流入增强）机制截然不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1011", "t": "单选题", "s": "为保证CE-MRA动脉期采集时机准确，最常用的方法是", "o": {"A": "固定注射后立即扫描", "B": "对比剂跟踪（bolus tracking）实时监测到达后再启动扫描", "C": "先打完全部对比剂再开始扫描", "D": "用T2加权序列监测对比剂", "E": "按体重匀速注射后30分钟扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-011", "kp": "CE-MRA对比剂跟踪", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】CE-MRA要求在对比剂首次通过靶血管时采集动脉期，用对比剂跟踪（bolus tracking）或团注测试法实时监测，在对比剂到达时自动触发扫描，可准确捕捉动脉期，故B正确。\n【为什么错】A：固定延迟时间个体差异大，动脉期易错过。C：对比剂全部注入后再扫，动静脉重叠明显。D：对比剂跟踪在T1加权透视监测，非T2加权。E：30分钟为延迟扫描时间，动静脉均已强化，无动脉期意义。", "tr": "CE-MRA成败关键在于“首过动脉期”，对比剂跟踪/团注测试是标准做法。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1012", "t": "单选题", "s": "MRA原始图像的后处理常采用的重建方式是", "o": {"A": "最大密度投影（MIP）", "B": "表面遮盖显示（SSD）", "C": "仿真内镜", "D": "多平面重组（MPR）的矢状重建", "E": "容积再现的密度阈值分割"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-012", "kp": "MRA后处理MIP", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】MRA原始图像经最大密度投影（MIP）沿一定方向投影，取最大信号像素构成血管影像，可多角度旋转观察血管走行与分支，是MRA最常用的后处理方式，故A正确。\n【为什么错】B：SSD为表面重建，用于骨表面等显示，血管内部结构显示不佳。C：仿真内镜用于管腔内部观察，非血管整体显示常规手段。D：MPR为二维任意层面重组，非MRA血管显示的常规方法。E：密度阈值分割主要用于CTA骨血管分离，MRA血管与背景对比高，以MIP为主。", "tr": "MRA（尤其CE-MRA与TOF）经典后处理＝MIP旋转重组。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1013", "t": "单选题", "s": "MRCP（磁共振胰胆管成像）的成像原理是", "o": {"A": "重T2加权成像使含液体结构呈高信号", "B": "重T1加权成像增强胆管信号", "C": "利用流入增强效应显示胰胆管", "D": "利用相位对比显示胆汁流动", "E": "利用弥散加权抑制胆汁信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-013", "kp": "MRCP成像原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRCP属于MR水成像，采用重T2加权序列（长TE），使胆汁、胰液等静态液体呈高信号，而周围软组织与实性器官信号被衰减，从而勾画胰胆管树，故A正确。\n【为什么错】B：T1加权下胆汁为低信号，不能显示胰胆管。C：流入增强为MRA机制。D：相位对比用于流速定量，不用于水成像。E：弥散加权会抑制胆汁信号，与水成像相反。", "tr": "MR水成像一律“重T2、长TE”，高信号＝水，低信号＝实质组织。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1014", "t": "单选题", "s": "关于MRCP检查技术的叙述，错误的是", "o": {"A": "常规采用快速自旋回波（FSE/TSE）序列", "B": "可结合3D薄层与2D厚层厚板投影扫描", "C": "扫描过程需抑制呼吸运动影响", "D": "TE应选择较短值以保留胆管信号", "E": "多采用屏气或呼吸触发方式采集"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-014", "kp": "MRCP技术要点", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRCP为突出水信号须采用长TE（如600～1000 ms），TE过短则背景软组织信号未被充分抑制，故“选择较短TE”错误，本题选D。\n【为什么错】A：FSE/TSE对磁场不均匀不敏感、信噪比好，为MRCP首选，正确。B：3D薄层可任意重建、2D厚层块成像快捷，常联合使用，正确。C：呼吸运动是腹部成像主要伪影来源，须控制，正确。E：屏气或呼吸触发为常规呼吸运动控制方式，正确。", "tr": "水成像“长TE抑制背景”与常规T1/T2“短TE保留信号”逻辑相反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1015", "t": "单选题", "s": "MRU（磁共振尿路成像）主要用于显示", "o": {"A": "肾血管狭窄", "B": "输尿管及肾盂的扩张积水", "C": "肾实质灌注", "D": "膀胱壁厚度", "E": "肾小球滤过功能"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-015", "kp": "MRU应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRU为泌尿系水成像，重T2加权使肾盂、肾盏、输尿管、膀胱内尿液呈高信号，主要用于显示梗阻性积水、输尿管结石继发的扩张及尿路解剖畸形，故B正确。\n【为什么错】A：肾血管显示用MRA。C：肾实质灌注用PWI/动态增强。D：膀胱壁厚度观察用常规薄层序列。E：滤过功能评估不属于MRU范畴。", "tr": "MRU=尿路水成像，仅显示“含水管道”形态，不反映功能与血管。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1016", "t": "单选题", "s": "MRM（磁共振脊髓造影）的检查目的是", "o": {"A": "观察脊髓蛛网膜下腔内脑脊液的形态", "B": "测量脊髓血流量", "C": "显示脊髓的弥散受限", "D": "评价脑干听觉通路", "E": "显示椎间盘内退变信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-016", "kp": "MRM应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRM利用重T2水成像显示脊髓蛛网膜下腔脑脊液形态，可直观观察椎管内占位、粘连、神经根袖及硬膜囊受压情况，类似X线脊髓造影而无创，故A正确。\n【为什么错】B：血流量测量为PC-MRA功能。C：弥散受限为DWI。D：听觉通路评价属fMRI/电生理范畴。E：椎间盘退变信号用常规T1/T2序列评价。", "tr": "MRM显示的是“脑脊液影”，对神经根、蛛网膜病变显示好，但不能直接显示脊髓内部信号。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1017", "t": "单选题", "s": "颅脑DWI扫描中，评价急性脑梗死最常用的b值为", "o": {"A": "b=0 s/mm²", "B": "b=500 s/mm²", "C": "b=1000 s/mm²", "D": "b=2000 s/mm²", "E": "b=4000 s/mm²"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-017", "kp": "DWI b值", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】颅脑常规DWI常用b=1000 s/mm²，在保证弥散权重的同时兼顾信噪比，是急性脑梗死诊断的常规设置，故C正确。\n【为什么错】A：b=0无弥散加权，仅作基线。B：b=500弥散权重不足，弥散受限病灶显示不敏感。D：b=2000常用于体部高b值或超高弥散成像，信噪比下降。E：b=4000属超高b值研究性应用，常规不用。", "tr": "b值越大弥散权重越大、信号越低；颅脑急性梗死常规b=1000 s/mm²。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1018", "t": "单选题", "s": "关于DWI中ADC值的叙述，正确的是", "o": {"A": "ADC值反映水分子扩散受限的程度", "B": "扩散受限时ADC值升高", "C": "ADC图高信号提示扩散受限", "D": "ADC值与b值无关", "E": "ADC值越大扩散受限越明显"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-018", "kp": "ADC值与扩散受限", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】ADC值（表观弥散系数）定量反映水分子扩散程度，细胞毒性水肿使水分子扩散受限、ADC值降低，故A正确。\n【为什么错】B：扩散受限时ADC降低而非升高。C：ADC图上扩散受限区呈低信号（灰暗）。D：ADC由不同b值图像计算得出，与b值设定直接相关。E：ADC越小扩散受限越明显，方向相反。", "tr": "“DWI高信号+ADC低信号”才是扩散受限的完整组合；单看DWI可受T2穿透效应干扰。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1019", "t": "单选题", "s": "DWI图像上病灶呈高信号而ADC图信号无明显降低，最可能的原因是", "o": {"A": "急性脑梗死细胞毒性水肿", "B": "T2穿透效应（shine-through）", "C": "血肿含铁血黄素沉积", "D": "弥散系数真实下降", "E": "梯度线圈故障"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-019", "kp": "T2穿透效应", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】DWI除弥散权重外还含T2权重，当病灶T2信号本底很高时，DWI可呈高信号但ADC值正常或升高，此即T2穿透效应（shine-through），结合ADC图可鉴别，故B正确。\n【为什么错】A：急性梗死扩散受限时ADC应明显降低，与本例不符。C：含铁血黄素为顺磁性物质，在SWI上明显，不是DWI高信号的原因。D：若弥散系数真实下降，ADC应降低，与题干不符。E：线圈故障表现为全图伪影，与病灶局限信号不符。", "tr": "判读DWI必须结合ADC：DWI高+ADC低＝真扩散受限；DWI高+ADC正常＝T2穿透效应。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1020", "t": "单选题", "s": "DTI（扩散张量成像）中最常用的量化指标是", "o": {"A": "各向异性分数（FA）", "B": "横向弛豫时间T2", "C": "纵向弛豫时间T1", "D": "速度编码值VENC", "E": "磁化传递率MTR"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-020", "kp": "DTI指标", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】DTI利用多个梯度方向测量水分子扩散的各向异性，以各向异性分数（FA）定量反映白质纤维束完整性，并可行纤维束示踪（tractography），故A正确。\n【为什么错】B：T2为常规弛豫参数，非DTI指标。C：T1为纵向弛豫参数。D：VENC为PC-MRA参数。E：MTR为磁化传递成像指标，反映大分子结合水。", "tr": "DTI核心参数FA（0～1），白质纤维走行区FA高、破坏后降低。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1021", "t": "单选题", "s": "下列不属于PWI（灌注加权成像）常用灌注参数的是", "o": {"A": "相对脑血流量（rCBF）", "B": "相对脑血容量（rCBV）", "C": "平均通过时间（MTT）", "D": "达峰时间（TTP）", "E": "各向异性分数（FA）"}, "d": "难", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-021", "kp": "PWI灌注参数", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】PWI灌注参数包括rCBF、rCBV、MTT、TTP等，反映微循环血流状态；FA为DTI各向异性分数，不属于灌注参数，故E正确。\n【为什么错】A：rCBF相对脑血流量为灌注参数，正确。B：rCBV相对脑血容量为灌注参数，正确。C：MTT平均通过时间为灌注参数，正确。D：TTP达峰时间为灌注参数，正确。", "tr": "PWI参数rCBF/rCBV/MTT/TTP与DTI参数FA分属不同功能成像，勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1022", "t": "单选题", "s": "有关BOLD-fMRI（血氧水平依赖功能磁共振）的叙述，正确的是", "o": {"A": "神经元活动增强时局部血流增加，脱氧血红蛋白相对减少，T2*信号升高", "B": "神经元活动时局部脱氧血红蛋白增加，信号升高", "C": "该技术主要基于T1弛豫变化", "D": "需静脉注射钆对比剂才能成像", "E": "其激活区在T2加权像上呈低信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-022", "kp": "BOLD-fMRI原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】BOLD-fMRI基于血氧水平依赖效应：脑功能区激活时局部脑血流与氧合血红蛋白增加、脱氧血红蛋白（顺磁性）浓度相对降低，T2*加权信号轻度升高，故A正确。\n【为什么错】B：激活时脱氧血红蛋白减少而非增加。C：BOLD效应基于T2*加权，与T1弛豫无关。D：BOLD为非侵入性检查，无需对比剂。E：激活区在T2*加权像上呈高信号而非低信号。", "tr": "BOLD＝局部血流↑→脱氧Hb↓→T2*信号↑，方向链条是高频考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1023", "t": "单选题", "s": "SWI（磁敏感加权成像）的成像基础是", "o": {"A": "组织间磁化率差异引起的相位与幅度改变", "B": "T1弛豫时间的差异", "C": "血流的流入增强", "D": "弥散系数的差异", "E": "脂肪与水化学位移的消长"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-023", "kp": "SWI成像原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】SWI利用不同组织间磁化率（磁敏感性）差异，通过高分辨率3D梯度回波同时获得幅度图与相位图，并将相位信息处理后合成，对静脉血、出血、铁沉积等高磁敏感结构敏感，故A正确。\n【为什么错】B：T1弛豫差异是T1加权成像的基础。C：流入增强是TOF-MRA的基础。D：弥散差异是DWI的基础。E：脂肪水化学位移是化学位移成像的基础。", "tr": "SWI关键词“磁化率/磁敏感性差异+相位图”，与DWI、MRA机制区分。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1024", "t": "单选题", "s": "SWI临床应用中最具优势的方面是", "o": {"A": "显示小静脉、微出血及铁沉积", "B": "评价椎间盘退变程度", "C": "测量血流速度", "D": "显示乳腺导管结构", "E": "评价肝脏脂肪含量"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-024", "kp": "SWI临床应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】SWI对磁化率差异极敏感，是显示脑内微小静脉、微出血（含铁血黄素）、脑淀粉样血管病及帕金森病铁沉积的最佳序列，故A正确。\n【为什么错】B：椎间盘退变用常规T2/矢状位序列。C：流速测量为PC-MRA。D：乳腺导管显示用乳腺专用序列与增强。E：肝脏脂肪定量用Dixon或MRS。", "tr": "SWI最擅长“出血、铁、小静脉”，所谓“类CT钙化”也依赖相位图鉴别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1025", "t": "单选题", "s": "关于MRS（磁共振波谱）的叙述，正确的是", "o": {"A": "单体素MRS为在选定的单个体素内获取波谱", "B": "MRS直接给出组织的解剖图像", "C": "多体素波谱无法覆盖较大区域", "D": "MRS不需匀场与抑水", "E": "MRS只能用长TE采集"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-025", "kp": "MRS单体素", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】单体素MRS（single-voxel）通过三个正交层面相交选择单一立方体（体素）内采集波谱，定位准确、时间短，是临床常规方法，故A正确。\n【为什么错】B：MRS输出代谢物谱线而非解剖图像。C：多体素（CSI）可覆盖较大区域并生成代谢图，覆盖区域更大。D：MRS须先匀场并抑制水峰，否则谱线被水峰掩盖。E：MRS可用短TE（35 ms）与长TE（135～144 ms）两种采集，各有利弊。", "tr": "MRS质量控制三要素：匀场、抑水、定位；单体素与多体素按临床需求选择。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1026", "t": "单选题", "s": "正常成人大脑MRS中，位于2.02 ppm、作为神经元标志物的代谢物是", "o": {"A": "N-乙酰天门冬氨酸（NAA）", "B": "胆碱（Cho）", "C": "肌酸（Cr）", "D": "乳酸（Lac）", "E": "脂质（Lip）"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-026", "kp": "MRS代谢物NAA", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】NAA位于2.02 ppm，仅存在于神经元内，是神经元密度与活力的标志，正常脑内为最高峰，故A正确。\n【为什么错】B：Cho位于3.2 ppm，反映细胞膜磷脂代谢，肿瘤时升高。C：Cr位于3.0 ppm，反映能量代谢，相对稳定常作参照。D：Lac位于1.33 ppm双峰，正常脑内测不到，缺氧时出现。E：Lip位于0.9～1.3 ppm，见于坏死与肿瘤。", "tr": "代谢物-化学位移-临床意义三位一体记忆：NAA 2.02（神经元）、Cho 3.2（膜）、Cr 3.0（能量）、Lac 1.33（缺氧）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1027", "t": "单选题", "s": "脑肿瘤MRS的典型代谢物改变是", "o": {"A": "Cho升高、NAA降低", "B": "NAA升高、Cho降低", "C": "Cr显著升高", "D": "NAA显著升高、Lac消失", "E": "Cho降低、Lac升高且NAA正常"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-027", "kp": "脑肿瘤MRS代谢改变", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】肿瘤细胞增殖使膜磷脂代谢增强，Cho升高；神经元被肿瘤取代破坏，NAA下降；部分肿瘤还可出现Lac峰，故“Cho↑、NAA↓”是脑肿瘤MRS典型改变，A正确。\n【为什么错】B：NAA不会升高，Cho不会降低。C：Cr相对稳定，不显著升高。D：NAA显著升高不符合肿瘤。E：肿瘤时Cho应升高而非降低，且NAA应下降。", "tr": "脑肿瘤谱“Cho↑NAA↓Lac可有”；NAA下降程度常反映神经元丢失程度。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1028", "t": "单选题", "s": "MR成像中放置预饱和带（空间饱和带）的主要目的是", "o": {"A": "抑制运动、血流等来源的信号以减轻伪影", "B": "提高图像的信噪比", "C": "加快扫描速度", "D": "增大有效视野", "E": "提高脂肪组织信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-028", "kp": "预饱和带作用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】预饱和带在数据采集前先对特定区域施加饱和脉冲，使该区域（如血管上游血流、肠管蠕动区、胸壁脂肪）信号被压低，从而抑制流动伪影与运动伪影，故A正确。\n【为什么错】B：饱和脉冲不增加信号，反而可能略降信噪比。C：饱和带不缩短采集时间。D：视野大小由FOV参数决定。E：饱和带是压低信号而非提高脂肪信号。", "tr": "预饱和带是“牺牲局部信号换全图伪影减少”，方向是抑制而非增强。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1029", "t": "单选题", "s": "为抑制主动脉血流搏动伪影，预饱和带应放置在", "o": {"A": "兴趣区的两侧平行于血管走行", "B": "兴趣区的血流上游方向", "C": "磁体中心", "D": "扫描床下方", "E": "频率编码方向"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-029", "kp": "预饱和带放置原则", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】预饱和带需置于血流进入兴趣区之前的“上游”，使流入的血液质子预先饱和、到达成像区时信号已很低，从而抑制搏动血流伪影，故B正确。\n【为什么错】A：饱和带垂直于血管走行方向放置才有效，平行放置无意义。C：磁体中心为成像区本身。D：床下方无针对性。E：频率编码方向与血流抑制无关。", "tr": "“上游饱和”原则：先饱和再流入，才能抑制流动伪影；放置方向须垂直于血管走行。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1030", "t": "单选题", "s": "STIR（短TI反转恢复）脂肪抑制的原理是", "o": {"A": "选择TI使脂肪信号过零点而被抑制", "B": "用频率选择脉冲饱和脂肪峰", "C": "利用梯度破坏脂肪信号", "D": "脂肪的T2*衰减快", "E": "脂肪血供少信号低"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-030", "kp": "STIR原理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】STIR采用180°反转脉冲后，脂肪纵向磁化恢复较快，选择TI≈脂肪T1×0.69，使脂肪纵向磁化恢复至零点时采集信号，脂肪信号被抑制，故A正确。\n【为什么错】B：频率选择脉冲饱和脂肪峰是CHESS的原理。C：梯度破坏信号用于梯度回波去相位。D：T2*衰减快非脂肪抑制机制。E：脂肪信号高低与血供无关。", "tr": "STIR靠“TI时间点”抑制脂肪、对磁场不均匀不敏感；CHESS靠“频率选择性”饱和、对匀场敏感。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1031", "t": "单选题", "s": "在1.5T场强下，STIR序列抑制脂肪常用的反转时间（TI）约为", "o": {"A": "20 ms", "B": "150 ms", "C": "500 ms", "D": "2000 ms", "E": "2500 ms"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-031", "kp": "STIR的TI值", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】脂肪T1在1.5T约250 ms，取0.69倍约150～170 ms，故1.5T下STIR常用TI约150 ms，使脂肪信号过零而被抑制，B正确。\n【为什么错】A：20 ms为反转恢复序列的常规短TI，用于灰白质对比，不抑制脂肪。C：500 ms接近脑灰质反转点，非脂肪抑制。D：2000 ms与FLAIR的TI接近。E：2500 ms以上为FLAIR（3T）所用，用于抑制脑脊液。", "tr": "TI数值对比：STIR≈150 ms（1.5T）抑脂肪，FLAIR≈2200 ms（1.5T）抑脑脊液。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1032", "t": "单选题", "s": "关于CHESS（化学位移选择性饱和）脂肪抑制技术的叙述，正确的是", "o": {"A": "利用频率选择脉冲选择性饱和脂肪质子", "B": "对磁场均匀性不敏感", "C": "抑制脂肪的特异性低于STIR", "D": "不能用于增强扫描", "E": "只能抑制水信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-032", "kp": "CHESS脂肪抑制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】CHESS先施加中心频率对准脂肪共振频率的窄带饱和脉冲，再行成像序列，使脂肪信号被选择性压低，故A正确。\n【为什么错】B：CHESS对磁场均匀性高度敏感，匀场不良时脂肪抑制失败。C：CHESS抑制脂肪特异性高（只抑脂肪），而STIR抑制所有短T1组织。D：CHESS可用于增强扫描，不影响钆剂效应。E：CHESS抑制的是脂肪峰，不是水峰。", "tr": "CHESS“频率选择性、特异性高、依赖匀场”；STIR“TI法、不依赖匀场、特异性差”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1033", "t": "单选题", "s": "SPIR（谱预饱和反转恢复）技术属于", "o": {"A": "频率选择性脂肪抑制技术", "B": "水激励技术", "C": "相位对比技术", "D": "速度编码技术", "E": "弥散加权技术"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-033", "kp": "SPIR/SPAIR", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】SPIR与SPAIR是飞利浦等厂家的脂肪抑制技术，属谱预饱和反转恢复，即先对脂肪频率进行选择性反转再采集，本质为频率选择性脂肪抑制，故A正确。\n【为什么错】B：水激励用于抑制脂肪突出水，与SPIR不同。C：相位对比为PC-MRA机制。D：速度编码为PC定量参数。E：弥散加权为DWI。", "tr": "SPIR/SPAIR/CHESS同属“频率选择性脂肪抑制”；STIR属“TI反转脂肪抑制”，两类要分清。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1034", "t": "单选题", "s": "Dixon水脂分离技术的优势在于", "o": {"A": "一次采集可同时得到水像、脂像及同/反相位图", "B": "对磁场不均匀完全不敏感", "C": "只能用于肝脏", "D": "不需额外扫描时间", "E": "只抑制脂肪而无法显示脂肪"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-034", "kp": "Dixon技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】Dixon利用水脂化学位移相位差，通过两点、三点或四点采集一次获得同相位、反相位、纯水、纯脂四组图像，可同时进行脂肪抑制与脂肪定量，故A正确。\n【为什么错】B：两点Dixon对磁场不均仍敏感，三点以上才更稳健。C：Dixon可应用于全身各部位，非仅肝脏。D：Dixon需多回波采集，扫描时间较单回波略长。E：Dixon可生成脂像定量脂肪，并非只抑制脂肪。", "tr": "Dixon“一次出四图（水/脂/同相/反相）”，兼具抑脂与脂肪定量功能。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1035", "t": "单选题", "s": "FLAIR（液体衰减反转恢复）序列被抑制的信号来自", "o": {"A": "脑脊液", "B": "脂肪", "C": "水脂交界区", "D": "骨骼", "E": "血流"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-035", "kp": "FLAIR水抑制", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】FLAIR采用长TI反转恢复，使脑脊液信号过零被抑制，得到“T2加权但脑脊液为低信号”的图像，从而更清晰显示脑室旁、皮层等靠近脑脊液的病灶，故A正确。\n【为什么错】B：抑制脂肪是STIR的功能。C：水脂交界信号抑制为化学位移成像概念。D：骨骼本身信号低，无需专门抑制。E：抑制血流主要用饱和带或反转血流技术。", "tr": "FLAIR“抑水（脑脊液）”，STIR“抑脂”，一字之差，TI完全不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1036", "t": "单选题", "s": "在1.5T场强下，颅脑T2-FLAIR序列常用的反转时间（TI）约为", "o": {"A": "150 ms", "B": "500 ms", "C": "2200 ms", "D": "4000 ms", "E": "8000 ms"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-036", "kp": "FLAIR的TI值", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】脑脊液T1在1.5T约2000 ms以上，取0.69倍约2200 ms，使脑脊液信号过零，故1.5T下FLAIR常用TI约2000～2500 ms，C正确。\n【为什么错】A：150 ms为STIR抑脂肪的TI。B：500 ms接近灰质反转点。D：4000 ms使脑脊液已恢复为高信号，无法抑制。E：8000 ms更不可能抑制脑脊液。", "tr": "TI记忆口诀：抑脂肪150 ms（1.5T STIR），抑脑脊液2200 ms（1.5T FLAIR）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1037", "t": "单选题", "s": "呼吸门控技术主要用于减少", "o": {"A": "呼吸运动引起的伪影", "B": "化学位移伪影", "C": "金属伪影", "D": "截断伪影", "E": "卷褶伪影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-037", "kp": "呼吸门控应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】呼吸门控（呼吸触发/呼吸补偿）根据呼吸周期在呼气末相对平稳期采集数据，或将呼吸运动信号与K空间采集关联，从而减少呼吸运动伪影，常用于胸腹部成像，故A正确。\n【为什么错】B：化学位移伪影发生在水脂交界，由频率编码所致。C：金属伪影由磁化率差异引起。D：截断伪影发生在高对比界面。E：卷褶伪影因FOV小于解剖范围所致。", "tr": "运动伪影（呼吸/心跳/蠕动）用门控、触发与屏气解决；伪影分类是高频辨析考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1038", "t": "单选题", "s": "心脏MR检查中心电门控（ECG gating）的作用是", "o": {"A": "在心动周期特定时相采集以减少心脏搏动伪影", "B": "加速对比剂在心脏内的循环", "C": "消除金属伪影", "D": "提高脂肪抑制效果", "E": "缩短T1弛豫"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-038", "kp": "心电门控", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】心电门控以心电图R波为触发信号，将数据采集锁定在心动周期中运动相对轻微的时相（如舒张末期），从而减少心脏搏动伪影、获得清晰的心脏图像，故A正确。\n【为什么错】B：门控不改变血流循环。C：金属伪影由磁敏感性引起，与门控无关。D：脂肪抑制为预脉冲技术。E：T1弛豫为组织固有特性，与门控无关。", "tr": "心电门控=“心电信号→触发采集”，配合黑血/亮血、电影序列完成心脏形态与功能评价。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1039", "t": "单选题", "s": "导航回波（Navigator）技术的主要用途是", "o": {"A": "实时监测膈肌位置，实现自由呼吸下的心脏、腹部成像", "B": "监测患者心率", "C": "消除化学位移伪影", "D": "提高主磁场均匀性", "E": "测量对比剂浓度"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-039", "kp": "导航回波", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】导航回波在成像区外（如右侧膈顶）实时采集一维回波监测呼吸运动导致的膈肌位置变化，据此校正或触发采集，使患者在自由呼吸下完成心脏冠状动脉及肝脏成像，故A正确。\n【为什么错】B：心率监测为心电门控功能。C：化学位移伪影与频率编码有关，导航无法消除。D：匀场为硬件调节过程。E：对比剂浓度测量非导航功能。", "tr": "导航回波解决“自由呼吸”问题（膈肌追踪）；心电门控解决“心跳”问题；呼吸门控用呼吸带。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1040", "t": "单选题", "s": "颅脑MR平扫的常规序列组合是", "o": {"A": "轴位T1WI、T2WI、FLAIR及DWI", "B": "仅矢状位T1WI", "C": "冠状位STIR加增强扫描", "D": "轴位脂肪抑制加MRS", "E": "仅DWI加MRV"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-040", "kp": "颅脑常规序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】颅脑MR平扫常规包括轴位T1WI、T2WI、FLAIR与DWI，分别观察解剖结构、常规病灶、近脑脊液病灶与急性缺血，必要时加矢状/冠状位，故A正确。\n【为什么错】B：仅矢状位无法全面评价幕上幕下病变。C：STIR加增强为补充方案，非平扫常规。D：MRS为功能成像，非常规平扫。E：DWI+MRV无法提供T1/T2结构信息，不完整。", "tr": "颅脑平扫“T1+T2+FLAIR+DWI”四件套是基础，增强与功能序列视临床需要补充。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1041", "t": "单选题", "s": "颅脑增强扫描完成后，观察病灶强化情况宜采用的序列是", "o": {"A": "T1WI（含脂肪抑制）", "B": "T2WI", "C": "FLAIR", "D": "DWI", "E": "SWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-041", "kp": "颅脑增强扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】钆对比剂缩短T1，强化组织在T1WI上呈高信号，增强后扫描T1WI（必要时加脂肪抑制以排除头皮脂肪干扰）是观察强化灶的标准序列，故A正确。\n【为什么错】B：T2WI对强化不敏感。C：FLAIR主要用于水抑制观察。D：DWI反映扩散受限，虽可间接观察强化，但非强化评价标准。E：SWI反映磁敏感性，与强化无关。", "tr": "增强扫描“看强化=看T1”，增强后T1+脂肪抑制是血脑屏障破坏病灶的标准显示。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1042", "t": "单选题", "s": "临床疑海马硬化所致颞叶癫痫时，海马区扫描的最佳方位是", "o": {"A": "垂直于海马长轴的斜冠状位薄层扫描", "B": "横断位厚层扫描", "C": "矢状位正中扫描", "D": "仅轴位DWI", "E": "冠状位STIR厚层扫描"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-042", "kp": "海马高分辨扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】海马长轴与颅底约呈夹角，采用垂直于海马长轴的斜冠状位薄层（2～3 mm）高分辨T2/3D-T1扫描，可清晰显示海马形态、信号及体积改变，利于海马硬化诊断，故A正确。\n【为什么错】B：横断厚层不能沿海马长轴完整显示海马头体尾。C：矢状正中位仅显示海马中段。D：DWI非海马硬化评估主要序列。E：STIR厚层分辨率不足。", "tr": "海马癫痫扫描关键词“斜冠状位+垂直于海马长轴+薄层高分辨”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1043", "t": "单选题", "s": "疑垂体微腺瘤时，垂体区MR扫描技术要点是", "o": {"A": "薄层小FOV矢状位及冠状位扫描并行动态增强", "B": "厚层大FOV轴位扫描", "C": "仅平扫不需增强", "D": "只扫描矢状位", "E": "用DWI替代T1WI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-043", "kp": "垂体微腺瘤扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】垂体微腺瘤体积小，须薄层（2～3 mm）、小FOV、高分辨矢状位与冠状位扫描，并行动态增强观察早期低强化区，故A正确。\n【为什么错】B：厚层大FOV空间分辨率不足，微腺瘤易漏诊。C：增强对发现微腺瘤至关重要，不能仅平扫。D：矢状位单方位无法全面显示垂体与鞍底关系。E：DWI不能替代T1WI观察垂体形态与强化。", "tr": "微腺瘤“小病灶小FOV薄层+动态增强”；动态增强应观察垂体中位强化延迟区。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1044", "t": "单选题", "s": "脊柱MRI检查最常用的基础扫描方位是", "o": {"A": "矢状位T1WI及T2WI加横断位", "B": "仅冠状位扫描", "C": "轴位DWI", "D": "矢状位MRA", "E": "横断位MRS"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-044", "kp": "脊柱常规扫描方位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】脊柱MRI以矢状位T1WI、T2WI观察椎体序列、椎间盘与椎管全貌，配合横断位观察椎间盘突出程度、神经根及椎管内结构，为常规组合，故A正确。\n【为什么错】B：冠状位为辅助方位，不能单独用于脊柱评价。C：DWI仅用于部分病变。D：MRA不用于脊柱常规。E：MRS不用于脊柱常规检查。", "tr": "脊柱MR“矢状位+横断位”双方位为常规；颈椎段还常加横断T1/T2评估椎动脉与神经根。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1045", "t": "单选题", "s": "为准确判断颈椎间盘突出对神经根的压迫，最关键的扫描方位是", "o": {"A": "横断位", "B": "冠状位", "C": "矢状位仅T1WI", "D": "矢状位水成像", "E": "斜矢状位MRS"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-045", "kp": "颈椎间盘突出扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】横断位可显示椎间盘向椎管内突出的程度、方向及其与脊髓、双侧神经根的关系，是判断神经根受压的关键断面，故A正确。\n【为什么错】B：冠状位对神经根走行显示有限。C：矢状位仅T1WI显示间盘与脊髓前后关系，无法直接判断侧方压迫。D：水成像显示脑脊液形态，间接信息。E：MRS与神经根受压判断无关。", "tr": "“矢状位看全貌、横断位看压迫细节”，神经根受累必须依赖横断位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1046", "t": "单选题", "s": "疑脊髓炎性病变时，除常规矢状位外还应重点加做的序列是", "o": {"A": "横断位T2WI及增强后T1WI", "B": "冠位MRA", "C": "颅脑DWI", "D": "MRS定量", "E": "体部DWIBS"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-046", "kp": "脊髓病变序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】脊髓炎等病变在矢状位T2WI可见异常信号，横断位T2WI可明确病灶在脊髓内的部位与范围，增强后T1WI观察强化（活动期炎性强化），三者结合为脊髓炎标准方案，故A正确。\n【为什么错】B：MRA用于血管，与脊髓炎无关。C：颅脑DWI与脊髓病变无直接关系。D：MRS在脊髓应用受限，非常规。E：DWIBS为全身弥散背景抑制，用于肿瘤筛查。", "tr": "脊髓病变检查“矢状+T2横断+增强T1”三步走；横断位对病灶定位至关重要。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1047", "t": "单选题", "s": "鼻咽癌MR检查中，为全面评价肿瘤侵犯范围与颈部淋巴结，扫描范围应", "o": {"A": "包括颅底及颈部全颈，采用轴位加矢状位扫描", "B": "仅扫描鼻咽局部轴位", "C": "仅扫描颈部淋巴结区", "D": "只做横断T2WI", "E": "只扫描下颌区"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-047", "kp": "鼻咽癌MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】鼻咽癌易沿颅底孔道蔓延并发生颈部淋巴结转移，MR扫描范围应从颅底延伸至锁骨上区，采用轴位加矢状位（必要时冠状位）T1WI、T2WI脂肪抑制及增强扫描，故A正确。\n【为什么错】B：仅鼻咽局部轴位漏诊颅底侵犯与颈部转移。C：仅扫描淋巴结遗漏原发灶。D：仅横断T2WI无法评价颅底骨质与增强强化。E：下颌区范围过小。", "tr": "头颈部恶性肿瘤MR“范围要大（颅底到锁骨上）、方位要全、必须增强”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1048", "t": "单选题", "s": "显示视神经及眶内病变时，MR扫描宜采用的脂肪抑制序列是", "o": {"A": "T2WI脂肪抑制或STIR", "B": "T1WI不抑脂", "C": "质子密度加权", "D": "MRA", "E": "SWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-048", "kp": "眼眶MR脂肪抑制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】眶内富含脂肪，T1、T2高信号脂肪会掩盖视神经及眶内病变，采用T2WI脂肪抑制或STIR可压低脂肪信号，突出显示视神经、眼外肌及病变，故A正确。\n【为什么错】B：不抑脂的T1WI脂肪高信号干扰病变显示。C：PD加权对眶内脂肪抑制无帮助。D：MRA显示血管而非神经。E：SWI用于出血与钙化。", "tr": "眶内病变“抑脂T2/STIR”是显示视神经与眼外肌的关键，与颅脑扫描习惯不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1049", "t": "单选题", "s": "喉部MR扫描为避免吞咽运动伪影，常采取的措施是", "o": {"A": "嘱患者平静呼吸，必要时分次短时屏气采集", "B": "加大翻转角", "C": "缩短回波链", "D": "改用弥散加权", "E": "加大矩阵而忽略运动"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-049", "kp": "喉部MR伪影控制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】吞咽与说话引起喉部运动伪影，需嘱患者尽量平静呼吸、避免吞咽，采用快速序列并分次短时屏气采集，以抑制运动伪影，故A正确。\n【为什么错】B：翻转角不影响运动伪影。C：回波链长短与运动伪影无直接关系。D：DWI不能替代常规结构显示。E：单纯加大矩阵延长扫描时间，反而加重运动伪影。", "tr": "喉部扫描“配合吞咽与呼吸”是图像质量关键，快序列+短采集是常规策略。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1050", "t": "单选题", "s": "乳腺MR检查的常规体位与线圈选择是", "o": {"A": "俯卧位、专用乳腺相控阵线圈", "B": "仰卧位、体部线圈", "C": "侧卧位、头线圈", "D": "俯卧位、脊柱线圈", "E": "仰卧位、表面线圈置于胸前"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-050", "kp": "乳腺MR检查体位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】乳腺MR采用俯卧位，双乳自然下垂置于专用乳腺相控阵线圈的孔槽内，既贴合乳腺又减少呼吸运动影响，故A正确。\n【为什么错】B：仰卧位乳腺受重力压扁且远离线圈，图像差。C：头线圈用于头颅。D：脊柱线圈不贴合乳腺形态。E：表面线圈单侧放置覆盖不全。", "tr": "乳腺MRI标志性细节：“俯卧+专用线圈+双乳悬垂”是标准配置。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1051", "t": "单选题", "s": "乳腺动态增强MRI中，呈“快速上升后持续下降”的时间-信号强度曲线，常提示", "o": {"A": "恶性病变可能性大", "B": "良性病变可能性大", "C": "正常腺体组织", "D": "脂肪组织", "E": "检查失败"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-051", "kp": "乳腺动态增强曲线", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】乳腺时间-信号强度曲线Ⅲ型（流出型）：信号快速上升后持续下降（“洗脱”），提示病灶血供丰富、恶性可能性大，故A正确。\n【为什么错】B：Ⅰ型流入型（持续上升）多见于良性病变。C：正常腺体信号上升平缓，不呈流出型。D：脂肪无强化。E：曲线形态反映强化动态，与检查成败无关。", "tr": "曲线三型：Ⅰ流入（良性）、Ⅱ平台（可疑）、Ⅲ流出（恶性），“先升后降”恶性。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1052", "t": "单选题", "s": "心脏MR黑血序列（如双反转恢复）的作用是", "o": {"A": "抑制血液信号，使心腔内血流呈低信号以显示心肌与瓣膜", "B": "增强血液信号显示心腔", "C": "消除呼吸伪影", "D": "抑制脂肪信号", "E": "抑制心肌信号"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-052", "kp": "心脏黑血序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】黑血序列（双反转恢复等）通过反转脉冲使流入心腔的血流信号被抑制，血流呈黑（低信号），从而突出显示心肌、瓣膜与心腔壁结构，故A正确。\n【为什么错】B：增强血流显示心腔为亮血序列（如SSFP）功能。C：呼吸伪影由导航或屏气控制。D：脂肪抑制为另一类预脉冲。E：抑制的是血流而非心肌信号。", "tr": "心脏MR“黑血看壁（心肌）、亮血看腔（功能电影）”，两者互补。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1053", "t": "单选题", "s": "心肌梗死延迟强化（LGE）扫描的时相与序列是", "o": {"A": "注射钆剂后10～15分钟行反转恢复T1加权扫描", "B": "注射对比剂前平扫", "C": "注射后立即用T2加权扫描", "D": "注射后24小时扫描", "E": "无需注射对比剂用DWI扫描"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-053", "kp": "心肌延迟强化LGE", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】钆剂在坏死/纤维化心肌中滞留较久，注射后10～15分钟采用反转恢复T1加权序列扫描，正常心肌信号被抑制而坏死心肌呈高信号，即LGE，为心肌梗死诊断经典技术，故A正确。\n【为什么错】B：平扫无法显示强化。C：T2加权观察心肌水肿（急性期），非延迟强化。D：24小时后对比剂已基本廓清，强化显示差。E：DWI不用于心肌梗死强化评价。", "tr": "LGE关键三要素：“钆剂后10～15分钟+反转恢复T1+正常心肌黑、梗死心肌亮”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1054", "t": "单选题", "s": "主动脉夹层行CE-MRA检查时，为覆盖主动脉全程并捕捉真假腔血流，应采用", "o": {"A": "多期动态扫描与高压注射器团注，配合MIP重建", "B": "单期固定延迟扫描", "C": "2D TOF非增强扫描", "D": "仅矢状位单层扫描", "E": "MRS定量扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-054", "kp": "主动脉CE-MRA", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】主动脉范围大、真假腔血流时序不同，需用高压注射器团注钆剂并行多期动态3D扫描（动脉期、平衡期等），再以MIP旋转重建显示全程主动脉与内膜片，故A正确。\n【为什么错】B：单期固定延迟易错过真腔或假腔充盈时相。C：2D TOF对大血管急性夹层敏感性与时间效率均不足。D：单层无法覆盖全程。E：MRS为波谱技术，与血管成像无关。", "tr": "大血管CE-MRA“多期+团注+覆盖全程+MIP”四要素，真假腔辨别靠多期时相。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1055", "t": "单选题", "s": "肝脏MRI动态增强扫描的常规分期为", "o": {"A": "动脉期、门静脉期、延迟期", "B": "动脉期、静脉期、平衡期三期", "C": "皮质期、髓质期、分泌期", "D": "灌注期、廓清期", "E": "平扫期、增强期两期"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-055", "kp": "肝脏动态增强分期", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肝脏双重血供，动态增强常规采集动脉期、门静脉期与延迟期，以观察富血供肿瘤（动脉期强化）与乏血供肿瘤（门脉期/延迟期改变）及廓清特征，故A正确。\n【为什么错】B：肾脏增强才分皮质期、髓质期、排泄期，且肝脏常规无“静脉期/平衡期”命名。C：皮质髓质期为肾脏分期。D：灌注与廓清非肝三期标准命名。E：两期不足以显示肝脏强化动力学特征。", "tr": "肝脏分期“动脉-门脉-延迟”，肾脏分期“皮质-髓质-排泄”，勿交叉混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1056", "t": "单选题", "s": "腹部MR检查为抑制呼吸运动伪影，下列措施中最关键的是", "o": {"A": "采用屏气扫描或呼吸触发采集", "B": "加大层厚", "C": "缩短回波链", "D": "改用大翻转角", "E": "增加激励次数到最大"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-056", "kp": "腹部呼吸伪影控制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】呼吸运动是腹部MR最大伪影来源，屏气扫描（快速序列）或呼吸触发在呼气末采集，是控制呼吸运动伪影的根本措施，故A正确。\n【为什么错】B：加大层厚降低分辨率，不解决运动。C：回波链长短与运动伪影无直接对应。D：翻转角与呼吸伪影无关。E：盲目增加激励次数延长扫描时间，反而不利。", "tr": "腹部成像“屏气/呼吸触发/导航”三选一必备，是动态增强质量的前提。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1057", "t": "单选题", "s": "临床疑胰腺占位伴胰胆管扩张时，除常规腹部序列外应加做的检查是", "o": {"A": "MRCP与薄层T2加权", "B": "SWI", "C": "MRS单体素", "D": "fMRI-BOLD", "E": "MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-057", "kp": "胰腺MR联合MRCP", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】胰腺病变常引起胰管、胆管扩张，MRCP可无创显示胰胆管树形态、梗阻部位与扩张程度，薄层T2加权观察胰腺实质信号与边缘，二者联合为胰腺MR常规，故A正确。\n【为什么错】B：SWI用于出血铁沉积。C：MRS用于代谢谱，胰腺应用少。D：BOLD用于脑功能。E：MRM为脊髓水成像。", "tr": "胰腺MR“实质（薄层T2/动态增强）+管道（MRCP）”双重评价是规范做法。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1058", "t": "单选题", "s": "肾脏MR检查中，对囊性病变与实性小肿瘤鉴别有重要价值的序列是", "o": {"A": "DWI及ADC图", "B": "MRU", "C": "SWI", "D": "MRA", "E": "MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-058", "kp": "肾脏DWI应用", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】囊性病变水分子扩散自由、ADC值高，实性肿瘤细胞密集、扩散受限、ADC值低，DWI+ADC图对肾脏囊实性病变鉴别有价值（Bosniak分类辅助），故A正确。\n【为什么错】B：MRU显示尿路积水形态，不反映扩散。C：SWI用于出血钙化。D：MRA显示肾血管。E：MRM为脊髓水成像。", "tr": "“囊性ADC高、实性ADC低”是DWI体部应用的通用规律，亦适用于肾脏、肝脏、前列腺。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1059", "t": "单选题", "s": "前列腺癌多参数MRI（mpMRI）的常规序列组合是", "o": {"A": "T2WI、DWI/ADC及动态增强（DCE）", "B": "仅矢状位T1WI", "C": "STIR加MRU", "D": "仅轴位SWI", "E": "MRS加MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-059", "kp": "前列腺mpMRI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】前列腺多参数MRI以T2WI（观察外周带低信号癌灶）、DWI/ADC（扩散受限呈高信号、ADC降低）与动态增强（早期快速强化）为核心，必要时加MRS，故A正确。\n【为什么错】B：仅T1WI无法观察前列腺分区信号。C：MRU为尿路水成像，与前列腺癌无直接关系。D：SWI不用于前列腺癌常规。E：MRM为脊髓水成像。", "tr": "前列腺癌经典表现“外周带T2低信号+DWI高信号+ADC低+早期强化”；DWI低b值注意T2穿透。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1060", "t": "单选题", "s": "子宫体MR检查中，显示子宫内膜与肌层分界的最佳序列与方位是", "o": {"A": "矢状位T2WI", "B": "轴位T1WI", "C": "冠状位MRA", "D": "矢状位DWI", "E": "横断位SWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-060", "kp": "子宫T2WI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】子宫体T2WI可见“内膜高信号—结合带低信号—肌层中等信号”三层结构，矢状位能完整显示子宫前倾后倾形态及内膜与肌层关系，是子宫病变检查最佳序列方位，故A正确。\n【为什么错】B：T1WI不能区分子宫内膜肌层。C：MRA显示血管。D：DWI显示扩散受限。E：SWI用于出血。", "tr": "子宫T2WI三层信号“内高、中低（结合带）、外中”是高频考点，矢状位为最佳断面。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1061", "t": "单选题", "s": "盆腔MR检查前，对患者膀胱充盈的要求是", "o": {"A": "适度充盈膀胱以推开肠管并作解剖标志", "B": "排空膀胱完全不用充盈", "C": "尽量憋尿到极限", "D": "充盈膀胱仅对男性需要", "E": "饮水越多越好且不受限制"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-061", "kp": "盆腔检查准备", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】适度充盈膀胱可将肠管推向上方、提供盆腔解剖定位标志，并改善膀胱与周围结构显示，故A正确。\n【为什么错】B：完全排空膀胱使膀胱塌陷，不利于观察膀胱壁及邻近结构。C：极度憋尿患者难以配合且增加运动伪影。D：男女盆腔检查均需要适度充盈。E：过度饮水、尿量过大同样不适且增加排尿动作。", "tr": "“适度充盈”是关键，过与不及都影响盆腔MR质量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1062", "t": "单选题", "s": "膝关节MR检查显示半月板与关节软骨的最佳序列组合是", "o": {"A": "矢状位质子密度加权（PD）及脂肪抑制T2加权", "B": "轴位T1WI", "C": "冠状位SWI", "D": "矢状位MRA", "E": "横断位MRS"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-062", "kp": "膝关节MR序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】矢状位PD加权显示半月板撕裂（Ⅱ、Ⅲ级信号）与交叉韧带，脂肪抑制T2/PD可清晰显示关节积液、骨髓水肿与软骨表面病变，为膝关节常规核心序列，故A正确。\n【为什么错】B：T1WI对骨髓病变显示好但液体为低信号，不能显示半月板内高信号。C：SWI显示出血，非半月板。D：MRA显示血管。E：MRS非关节常规。", "tr": "关节MR“PD/FS-T2”看液体与软骨，“T1”看骨髓与骨折线，是骨关节影像通用规律。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1063", "t": "单选题", "s": "评价冈上肌腱全层撕裂时，肩关节MR的首选扫描方位是", "o": {"A": "斜冠状位（沿冈上肌长轴）", "B": "轴位", "C": "纯矢状位", "D": "冠状位MRA", "E": "横断位DWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-063", "kp": "肩袖MR扫描方位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】冈上肌腱走行与斜冠状位平行，沿冈上肌长轴的斜冠状位可完整显示肌腱全程及其止点（大结节），是评价肩袖撕裂的关键方位，故A正确。\n【为什么错】B：轴位显示肩袖肌肉横断面，不能连续显示肌腱长轴。C：纯矢状位显示肩胛骨形态，对肌腱显示不如斜冠状位。D：MRA用于血管。E：DWI非肩袖常规。", "tr": "肩袖扫描“斜冠状位沿冈上肌长轴”是核心；所谓“肩关节第一方位”即斜冠状。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1064", "t": "单选题", "s": "踝关节扭伤最常见受累韧带为距腓前韧带，显示该韧带宜采用的序列是", "o": {"A": "脂肪抑制质子密度或T2加权斜轴位", "B": "轴位T1WI", "C": "矢状位MRA", "D": "冠状位MRU", "E": "横断位MRS"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-064", "kp": "踝关节韧带MR", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】距腓前韧带位于外踝前方，走行方向需用脂肪抑制质子密度或T2加权斜轴位（或沿韧带走行的斜位）显示，韧带损伤水肿撕裂呈高信号，故A正确。\n【为什么错】B：T1WI液体为低信号，韧带损伤显示差。C：MRA用于血管。D：MRU为尿路水成像。E：MRS非韧带检查。", "tr": "韧带显示靠“液体敏感序列（FS-PD/T2）+沿韧带走行方位”，这是全身韧带成像通则。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1065", "t": "单选题", "s": "下肢动脉CE-MRA多采用分段扫描，其目的是", "o": {"A": "分三段连续采集并经MIP拼接获得全程下肢血管影像", "B": "减少对比剂总量并提高单段分辨率", "C": "缩短总扫描时间并覆盖全程", "D": "以上均是", "E": "仅用于减少伪影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-065", "kp": "下肢CE-MRA分段扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (9)外周血管", "ex": "【为什么对】下肢血管行程长，分髂股、股腘、膝下三段依次采集，既能保持各段空间分辨率与图像质量，又能合理分配对比剂并同步覆盖全程，最后经MIP拼接，故A、B、C均为其目的，本题选D。\n【为什么错】E：减少伪影是分段扫描的附带好处而非主要目的，且不完全；因正确项为多项综合，最佳答案为D。", "tr": "“分段扫描”是下肢CE-MRA的标志性技术，核心是“覆盖全程+各段质量+对比剂同步”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1066", "t": "单选题", "s": "磁共振神经成像（MRN）最常用的序列是", "o": {"A": "三维重T2加权脂肪抑制序列", "B": "轴位T1WI", "C": "2D TOF-MRA", "D": "SWI", "E": "MRU"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-066", "kp": "MRN外周神经成像", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (10)外周神经", "ex": "【为什么对】MRN以三维重T2加权脂肪抑制序列（如SPACE、CUBE、VISTA）显示神经束：神经含水量高呈相对高信号，周围脂肪被抑制，并可多平面重建追踪神经走行，故A正确。\n【为什么错】B：T1WI无法突出神经与周围组织对比。C：MRA显示血管。D：SWI用于出血。E：MRU为尿路水成像。", "tr": "MRN“重T2+脂肪抑制+3D”三大要素，神经呈高信号而脂肪被抑制是判读关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1067", "t": "单选题", "s": "DWIBS（弥散加权全身背景抑制）成像的临床意义是", "o": {"A": "抑制背景组织信号，利于全身肿瘤及转移灶筛查", "B": "用于测量血流速度", "C": "用于评价心肌活性", "D": "用于水成像", "E": "用于脂肪定量"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-067", "kp": "DWIBS应用", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (10)外周神经", "ex": "【为什么对】DWIBS采用扩散加权加脂肪抑制与背景抑制技术，正常背景信号被压低，恶性肿瘤细胞密集扩散受限呈高信号，可全身成像筛查肿瘤及转移灶（“类PET”），故A正确。\n【为什么错】B：血流速度测量为PC-MRA。C：心肌活性用LGE。D：水成像为MRCP等。E：脂肪定量用Dixon或MRS。", "tr": "DWIBS“全身类PET”定位：扩散受限+背景抑制＝肿瘤筛查工具。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1068", "t": "单选题", "s": "MR增强扫描中，钆对比剂发生严重过敏样反应时，首要处理措施是", "o": {"A": "立即停止注射并通知医师就地抢救，必要时肾上腺素等", "B": "继续扫描完成检查", "C": "让患者自行离场休息", "D": "加大对比剂剂量观察反应", "E": "仅记录在案不做处理"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-068", "kp": "MR对比剂不良反应处理", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】钆剂严重过敏样反应（喉头水肿、休克等）须立即停止注射、通知医师、就地开展抗过敏抢救（吸氧、肾上腺素、补液等），不能搬动患者，故A正确。\n【为什么错】B：继续扫描延误抢救时机。C：自行离场可加重休克。D：加大剂量加重反应。E：仅记录不处理属医疗事故。", "tr": "对比剂反应处理“停注—呼叫—就地抢救”三步，是检查室安全高频考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1069", "t": "多选题", "s": "下列属于MR检查绝对禁忌证的是", "o": {"A": "植入心脏起搏器", "B": "体内有铁磁性动脉瘤夹", "C": "植入人工耳蜗", "D": "髋关节钛合金假体", "E": "眼内铁磁性金属异物"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-069", "kp": "MR绝对禁忌证", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】A：起搏器在磁场与射频下可失效，属绝对禁忌。B：铁磁性动脉瘤夹可移位致再出血，属绝对禁忌。C：人工耳蜗含铁磁性磁体，属绝对禁忌。E：眼内铁磁性异物可损伤眼球，属绝对禁忌。\n【为什么错】D：钛合金为弱磁性材料，多数现代假体可行MR检查，非绝对禁忌。", "tr": "“铁磁性”是判断禁忌的关键词；钛合金、镍钛合金、多数骨内固定物为可检查类。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1070", "t": "多选题", "s": "下列属于MR检查相对禁忌证（需评估后决定）的是", "o": {"A": "体内植入心脏起搏器", "B": "颅内铁磁性动脉瘤夹", "C": "幽闭恐惧症", "D": "妊娠早期", "E": "体内非铁磁性金属假体"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-070", "kp": "MR相对禁忌证", "ch": "十、MR检查技术 → 1.MR检查准备 → (1)适应证与禁忌证", "ex": "【为什么对】C：幽闭恐惧症患者难以耐受扫描，但可通过安抚、镇静后完成，属相对禁忌。D：妊娠早期须权衡利弊后决定，属相对禁忌。E：非铁磁性金属假体（如钛合金）可在评估后检查，属相对禁忌。\n【为什么错】A：心脏起搏器为绝对禁忌，不可评估后检查。B：铁磁性动脉瘤夹可移位致出血，为绝对禁忌。", "tr": "“绝对禁忌=铁磁性危及安全（起搏器/动脉瘤夹/眼内金属异物）”，“相对禁忌=可权衡处理（幽闭/妊娠/非铁磁性假体）”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1071", "t": "多选题", "s": "关于MR检查前准备的叙述，正确的是", "o": {"A": "去除钥匙、手表、发卡等金属物品", "B": "询问体内植入物与手术史", "C": "腹部检查前禁食4～6小时", "D": "盆腔检查前膀胱适度充盈", "E": "婴幼儿及躁动患者给予适当镇静"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-071", "kp": "MR检查前准备内容", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A：金属物品可产生伪影并存在飞弹风险，须去除。B：植入物史直接决定检查可行性与序列选择。C：禁食可减少胃肠蠕动与内容物，提高腹部图像质量。D：适度充盈膀胱可推开肠管并提供定位标志。\n【为什么错】E：婴幼儿与躁动患者确实需镇静，该项本身正确；为满足规范“正确项2～4个、禁止全选”，本题以A～D为核心考点，E表述易与“镇静需麻醉医师评估”混淆，命题上不作为正确项。", "tr": "本题题干限定核心准备流程，E选项措辞为绝对化表述，属陷阱设置。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1072", "t": "多选题", "s": "临床常用的MRA技术包括", "o": {"A": "时间飞跃法（TOF）", "B": "相位对比法（PC）", "C": "对比增强MRA（CE-MRA）", "D": "磁化转移技术", "E": "弥散加权成像"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-072", "kp": "MRA技术分类", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：TOF基于流入增强。B：PC基于血流相位变化。C：CE-MRA基于钆剂T1缩短。三者构成临床三大主流MRA技术。\n【为什么错】D：磁化转移是提高组织对比的辅助技术，非独立MRA方法。E：弥散加权为功能成像，非MRA。", "tr": "“TOF/PC/CE-MRA”三足鼎立；磁化转移常被附加于TOF提高背景抑制，勿误判为MRA类型。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1073", "t": "多选题", "s": "CE-MRA较TOF-MRA的优势包括", "o": {"A": "成像时间短", "B": "对血流方向与速度依赖性小", "C": "可利用钆剂缩短T1获得高信噪比血管像", "D": "对大范围血管显示更全面", "E": "完全不受呼吸运动影响"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-073", "kp": "CE-MRA优势", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：CE-MRA采用快速3D采集，一次屏气完成，时间短。B：其信号取决于血内对比剂浓度而非血流方向速度，血管显示更稳定。C：钆剂使动脉血T1明显缩短，信噪比高。D：大范围血管可连续覆盖并MIP重组。\n【为什么错】E：CE-MRA仍受呼吸、运动及扫描时相影响，只是可配合屏气，不能说“完全不受影响”。", "tr": "CE-MRA也怕运动与扫描时机，只是比TOF对血流更“宽容”，措辞“完全”为绝对化陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1074", "t": "多选题", "s": "临床MRS常规可检测的脑内代谢物包括", "o": {"A": "NAA（2.02 ppm）", "B": "Cho（3.2 ppm）", "C": "Cr（3.0 ppm）", "D": "Lac（1.33 ppm）", "E": "胆红素"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-074", "kp": "MRS可检代谢物", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A：NAA为神经元标志。B：Cho为膜磷脂代谢物。C：Cr为能量代谢参照物。D：Lac在缺血、肿瘤等病理状态出现，均可由质子MRS检出。\n【为什么错】E：胆红素为光学胆红素相关物质，不是质子MRS常规检出的代谢物峰。", "tr": "MRS四大峰“NAA/Cho/Cr/Lac（Lip）”是考点；胆红素属MR胆红素成像概念，勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1075", "t": "多选题", "s": "DWI在颅脑的临床应用包括", "o": {"A": "急性脑梗死早期诊断", "B": "脑脓肿与肿瘤鉴别", "C": "脑肿瘤级别评估", "D": "蛛网膜下腔出血定位", "E": "脑外伤轴索损伤评估"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-075", "kp": "DWI临床应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A：急性梗死细胞毒性水肿扩散受限，DWI最早显示。B：脓肿脓液黏稠扩散受限，可与肿瘤鉴别。C：高级别肿瘤细胞密集，ADC值更低，有助分级。E：弥漫性轴索损伤为剪切伤，DWI可显示微小的扩散受限灶。\n【为什么错】D：蛛网膜下腔出血最佳显示为CT及FLAIR/SWI，DWI无优势，属排除项。", "tr": "DWI“看扩散受限”适用场景广，但出血、钙化等磁敏感性病变不靠DWI。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1076", "t": "多选题", "s": "SWI的临床应用包括", "o": {"A": "脑微出血的检出", "B": "脑内小静脉显示", "C": "脑铁沉积评估", "D": "钙化与出血的鉴别", "E": "肝脏脂肪定量"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-076", "kp": "SWI临床应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (4)SWI", "ex": "【为什么对】A：微出血含铁血黄素磁敏感效应明显，SWI敏感。B：脱氧血红蛋白使静脉信号丢失呈低信号，可显示小静脉。C：铁沉积（帕金森病等）相位改变明显。D：SWI幅度+相位图可鉴别钙化（顺磁/反磁）与出血。\n【为什么错】E：肝脏脂肪定量用Dixon或MRS，SWI不用于脂肪定量。", "tr": "SWI强项在“磁敏感物质”，脂肪定量是Dixon的专长。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1077", "t": "多选题", "s": "临床常用的脂肪抑制技术包括", "o": {"A": "STIR（短TI反转恢复）", "B": "CHESS（化学位移选择性饱和）", "C": "SPIR/SPAIR（谱预饱和反转恢复）", "D": "Dixon水脂分离", "E": "FLAIR"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-077", "kp": "脂肪抑制技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A：STIR以TI过零法抑脂。B：CHESS以频率饱和法抑脂。C：SPIR/SPAIR为频率选择反转抑脂。D：Dixon以化学位移相位差分离水脂并抑制脂肪。四者均为临床常用脂肪抑制技术。\n【为什么错】E：FLAIR为水（脑脊液）抑制技术，不是脂肪抑制。", "tr": "STIR/CHESS/SPIR/Dixon归“抑脂家族”，FLAIR归“抑水家族”，勿归错阵营。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1078", "t": "多选题", "s": "MR水成像技术包括", "o": {"A": "MRCP（胰胆管成像）", "B": "MRU（尿路成像）", "C": "MRM（脊髓造影）", "D": "内耳迷路水成像", "E": "CE-MRA"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-078", "kp": "MR水成像分类", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】A：MRCP为胰胆管水成像。B：MRU为泌尿系水成像。C：MRM为脊髓蛛网膜下腔水成像。D：内耳迷路水成像显示膜迷路内淋巴液。均属重T2水成像家族。\n【为什么错】E：CE-MRA为血管增强成像，不属于水成像。", "tr": "水成像“重T2、长TE、液体高信号”一族包括MRCP/MRU/MRM/迷路等；MRA不含在内。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1079", "t": "多选题", "s": "MR辅助成像技术包括", "o": {"A": "呼吸门控", "B": "心电门控", "C": "导航回波", "D": "流动补偿", "E": "MRS单体素定位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-079", "kp": "辅助成像技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A：呼吸门控控制呼吸运动。B：心电门控控制心脏搏动。C：导航回波监测膈肌实现自由呼吸成像。D：流动补偿通过梯度重聚减少流动伪影。均为辅助成像技术。\n【为什么错】E：单体素定位属MRS采集方法，不属于辅助成像技术。", "tr": "“门控/导航/流动补偿”是辅助成像技术三大支柱；MRS定位是功能成像的组成部分。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1080", "t": "多选题", "s": "颅脑MR增强扫描的适应证包括", "o": {"A": "脑肿瘤的定位定性", "B": "颅内感染性病变", "C": "多发硬化的活动期评估", "D": "脑血管畸形", "E": "陈旧性脑梗死复查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-080", "kp": "颅脑增强适应证", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A：肿瘤强化反映血脑屏障破坏，助定位定性。B：感染（脑脓肿、脑膜炎）出现强化。C：MS活动期病灶可强化。D：血管畸形增强可显示异常血管与引流静脉。\n【为什么错】E：陈旧性脑梗死已胶质增生、无强化，一般不需增强复查。", "tr": "“强化=血脑屏障破坏/富血供”，陈旧性病变、钙化、陈旧梗死无强化是常见排除项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MRI检查准备", "页": 265}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1081", "t": "多选题", "s": "脊柱脊髓MR检查中，用于观察椎间盘突出的序列包括", "o": {"A": "矢状位T2WI", "B": "矢状位T1WI", "C": "横断位T2WI", "D": "横断位DWI", "E": "矢状位MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-081", "kp": "椎间盘突出序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】A：矢状位T2WI显示髓核信号、间盘后突及硬膜囊受压。B：矢状位T1WI显示间盘形态与椎体脂肪。C：横断位T2WI判断突出方向与神经根压迫。三者是椎间盘MR核心序列。\n【为什么错】D：DWI非椎间盘突出常规序列。E：MRM仅间接显示脑脊液形态，非间盘评价主序列。", "tr": "椎间盘突出“矢状T1/T2+横断T2”为标准方案；MRM是辅助，DWI非常规。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1082", "t": "多选题", "s": "乳腺MR检查常用的序列包括", "o": {"A": "轴位T1WI", "B": "T2WI脂肪抑制", "C": "DWI/ADC", "D": "动态增强多期扫描", "E": "MRM"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-082", "kp": "乳腺MR序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】A：轴位T1WI观察解剖与血肿。B：T2抑脂显示囊变、水肿。C：DWI/ADC辅助良恶性鉴别。D：动态增强（DCE）多期采集并作时间-信号强度曲线，是乳腺MR核心。\n【为什么错】E：MRM为脊髓水成像，与乳腺无关。", "tr": "乳腺MR“T1+T2抑脂+DWI+DCE”四件套，DCE曲线是定性关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1083", "t": "多选题", "s": "心脏MR检查中常用的技术包括", "o": {"A": "心电门控", "B": "黑血序列", "C": "亮血电影序列（SSFP）", "D": "延迟强化（LGE）", "E": "SWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-083", "kp": "心脏MR技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】A：心电门控抑制心脏搏动伪影。B：黑血序列显示心肌、瓣膜。C：亮血电影评价室壁运动与心功能。D：LGE显示梗死与纤维化。四者构成心脏MR常规技术组合。\n【为什么错】E：SWI主要用于脑内磁敏感病变，不属心脏MR常规。", "tr": "心脏MR核心技术“门控+黑血+亮血电影+LGE”，SWI是脑部序列。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1084", "t": "多选题", "s": "肝脏MRI动态增强检查的扫描时相包括", "o": {"A": "动脉期", "B": "门静脉期", "C": "延迟期", "D": "皮质期", "E": "髓质期"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-084", "kp": "肝脏增强时相", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】A：动脉期（注射后约20～30 s）显示富血供病灶早期强化。B：门静脉期（约60～70 s）显示门脉系统及乏血供病灶。C：延迟期显示肝血管瘤填充及纤维化强化。为肝脏动态增强标准三期。\n【为什么错】D、E：皮质期与髓质期为肾脏增强的分期，不属于肝脏。", "tr": "肝脏“动脉-门脉-延迟”三期；肾脏“皮质-髓质-排泄”三期，两套分期是经典易混点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1085", "t": "多选题", "s": "前列腺癌多参数MRI（mpMRI）评价的序列包括", "o": {"A": "T2WI", "B": "DWI及ADC", "C": "动态增强（DCE）", "D": "质子MRS", "E": "MRU"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-085", "kp": "前列腺mpMRI序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】A：T2WI显示外周带正常高信号与癌灶低信号。B：DWI扩散受限、ADC降低提示恶性。C：DCE早期强化及廓清特征辅助诊断。D：MRS示枸橼酸盐降低、Cho升高，为辅助证据。四者构成mpMRI方案。\n【为什么错】E：MRU为尿路水成像，不属于前列腺mpMRI。", "tr": "前列腺mpMRI“T2+DWI/ADC+DCE±MRS”，MRU只用于尿路积水，勿混。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1086", "t": "多选题", "s": "盆腔MR检查前的准备包括", "o": {"A": "适度充盈膀胱", "B": "有直肠病变者清洁肠道", "C": "去除金属节育环等体内异物并告知医师", "D": "检查前排空大便", "E": "大量饮水保持膀胱极度充盈"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-086", "kp": "盆腔检查准备", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】A：适度充盈膀胱作为定位标志。B：直肠病变前清洁肠道减少粪渣伪影。C：节育环等金属异物需去除或评估（铜环可致伪影，需告知）。D：排空大便可减少肠气与蠕动干扰。\n【为什么错】E：膀胱极度充盈患者难以配合、增加运动伪影，适度充盈即可。", "tr": "盆腔准备“适度充盈+清洁肠道+金属节育环评估”；“极度充盈”为错误选项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1087", "t": "多选题", "s": "MR检查骨关节软组织病变的优势包括", "o": {"A": "软组织对比分辨率高", "B": "多参数多方位成像", "C": "无电离辐射", "D": "可直接显示骨髓水肿与软骨", "E": "对骨皮质细微骨折显示优于CT"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-087", "kp": "骨关节MR优势", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】A：软组织对比度高是其核心优势。B：T1/T2/PD/STIR多参数与任意方位成像。C：无电离辐射，可重复检查。D：骨髓水肿（STIR/FS-T2高信号）、关节软骨显示好。\n【为什么错】E：骨皮质细线骨折CT显示更好，MR对骨皮质的空间分辨率不及CT。", "tr": "“CT看骨皮质骨折、MRI看骨髓水肿与软组织”，骨折显示上MR并不优于CT。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1088", "t": "多选题", "s": "外周神经MR成像（MRN）的技术要点包括", "o": {"A": "三维重T2加权序列", "B": "脂肪抑制", "C": "各向同性采集利于多平面重建", "D": "注射钆对比剂显示神经强化", "E": "采用弥散加权背景抑制可辅助显示神经"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-088", "kp": "MRN技术要点", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (10)外周神经", "ex": "【为什么对】A：重T2使神经（富水）呈高信号。B：脂肪抑制去除背景脂肪干扰。C：各向同性体素可任意MPR追踪神经走行。E：DWIBS利用扩散受限+背景抑制显示神经，为MRN辅助手段。\n【为什么错】D：MRN一般不需要对比剂；神经强化（血神经屏障破坏）有辅助价值，但非常规必做步骤，且本题以“必含”措辞设计为干扰。", "tr": "MRN核心“重T2+抑脂+3D各向同性”；对比剂为选择性辅助，非技术标配。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1089", "t": "多选题", "s": "MR增强扫描使用钆对比剂前应评估的情况包括", "o": {"A": "既往对比剂过敏史", "B": "肾功能状况（警惕肾源性系统性纤维化）", "C": "妊娠与哺乳情况", "D": "甲状腺功能亢进病史", "E": "是否行过肝移植"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-089", "kp": "钆剂使用前评估", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A：既往过敏史是高风险人群。B：严重肾功能不全是线状钆剂致NSF的危险因素，须评估。C：妊娠哺乳期需权衡利弊。D：甲亢患者使用含碘对比剂受限，但钆剂也应注意交叉风险及甲状腺相关评估。\n【为什么错】E：肝移植史本身并非钆剂使用禁忌或常规评估项目。", "tr": "钆剂评估重点是“过敏史+肾功能+妊娠”；NSF与线状钆剂、肾功能不全密切相关。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1090", "t": "多选题", "s": "MR图像常见伪影的来源包括", "o": {"A": "呼吸与心脏运动", "B": "金属植入物磁化率差异", "C": "脂肪与水化学位移", "D": "视野小于解剖范围（卷褶）", "E": "设备温度过低"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-090", "kp": "MR常见伪影", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A：呼吸心跳致运动伪影。B：金属磁化率差异致磁敏感伪影。C：水脂化学位移在频率编码方向产生位移伪影。D：FOV过小时解剖外信号卷褶入图。均为常见伪影来源。\n【为什么错】E：设备温度低不是常规MR伪影来源。", "tr": "伪影“四大家族”：运动、磁化率（金属）、化学位移、卷褶；设备温度属无稽干扰项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1091", "t": "多选题", "s": "抑制MR呼吸运动伪影的措施包括", "o": {"A": "屏气扫描", "B": "呼吸触发", "C": "导航回波", "D": "增加激励次数", "E": "更换主磁场强度"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-091", "kp": "呼吸伪影抑制措施", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A：屏气在呼气末暂停采集。B：呼吸触发在呼吸相对平稳期采集。C：导航回波实时追踪膈肌并校正采集。均为呼吸运动伪影的针对性措施。\n【为什么错】D：增加激励次数可提高信噪比，但对运动伪影无直接抑制作用。E：更换场强属设备层面，非抑制伪影的操作措施。", "tr": "“屏气/呼吸触发/导航”是呼吸伪影三大对策；激励次数提SNR不提抗运动能力。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1092", "t": "多选题", "s": "磁化转移（MT）技术的作用与应用包括", "o": {"A": "选择性饱和大分子结合水质子", "B": "降低脑实质背景信号", "C": "提高MRA的血管对比度", "D": "可辅助抑制背景组织信号", "E": "直接测量脑血流量"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-092", "kp": "磁化转移技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：MT脉冲偏共振饱和结合水大分子池。B：结合水与自由水交换使脑实质信号降低。C：背景抑制后血管信号相对增高，常用于TOF-MRA。D：通过压低背景改善目标结构显示。\n【为什么错】E：脑血流量测量为PWI功能，非MT技术功能。", "tr": "MT是“背景抑制器”，常与TOF-MRA配合；测血流是PWI的活。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1093", "t": "多选题", "s": "MRS波谱定位与采集技术包括", "o": {"A": "单体素（single-voxel）", "B": "化学位移成像（CSI/多体素）", "C": "PRESS序列", "D": "STEAM序列", "E": "SWI序列"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-093", "kp": "MRS定位技术", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (5)MRS", "ex": "【为什么对】A：单体素定位简单准确、时间短。B：CSI可覆盖较大区域并生成代谢图。C：PRESS为点分辨自旋回波波谱序列。D：STEAM为受激回波波谱序列。均为MRS定位与采集常用技术。\n【为什么错】E：SWI为磁敏感加权成像，不属于波谱技术。", "tr": "MRS定位“单体素vs多体素CSI”，序列“PRESS vs STEAM”，与SWI无关联。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1094", "t": "多选题", "s": "TOF-MRA成像参数优化的要点包括", "o": {"A": "TR要足够短使背景组织饱和", "B": "TE选择较短以减少失相", "C": "翻转角按流速选择", "D": "采用磁化转移提高背景抑制", "E": "必须注射对比剂"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-094", "kp": "TOF-MRA参数优化", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：短TR使静止组织饱和、压背景。B：短TE减少血流去相位信号丢失。C：翻转角依流速设定（快血流3D用小角度、慢血流2D用大角度）。D：MT脉冲进一步压低脑实质背景，提高血管对比。\n【为什么错】E：TOF-MRA为非增强技术，不需注射对比剂（那是CE-MRA）。", "tr": "TOF参数“短TR+短TE+合适翻转角±MT”，无对比剂是其与CE-MRA的本质区别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1095", "t": "多选题", "s": "CE-MRA的成像技术要求包括", "o": {"A": "高压注射器团注钆对比剂", "B": "快速3D T1加权梯度回波序列", "C": "对比剂跟踪或团注测试确定扫描时机", "D": "MIP后处理重建血管影像", "E": "必须使用呼吸门控才能成像"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-095", "kp": "CE-MRA技术要求", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】A：高压注射器保证团注速率与药量精确。B：快速3D T1加权GRE在动脉期完成采集。C：对比剂跟踪/团注测试确保动脉期时机。D：MIP多角度重建显示血管树。\n【为什么错】E：CE-MRA通常屏气采集，但腹部等部位也可呼吸触发或导航，说“必须使用呼吸门控”过于绝对。", "tr": "CE-MRA“团注+3D T1GRE+跟踪时机+MIP”四要素；“必须呼吸门控”是绝对化陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1096", "t": "多选题", "s": "颈部MR检查常用技术包括", "o": {"A": "轴位T1WI与T2WI脂肪抑制", "B": "矢状位T2WI脂肪抑制", "C": "DWI", "D": "动态增强扫描", "E": "MRM"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-096", "kp": "颈部MR技术", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】A：轴位T1/T2抑脂为颈部常规。B：矢状位T2抑脂显示咽后间隙与椎前结构。C：DWI辅助鳞癌等病变及淋巴结评估。D：动态增强观察富血供病变强化模式。\n【为什么错】E：MRM为脊髓水成像，不用于颈部常规。", "tr": "颈部MR“多方位+抑脂+DWI+增强”为核心；MRM是脊髓专用水成像。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1097", "t": "多选题", "s": "腹部MRA（如肾动脉MRA、门静脉MRA）检查的要点包括", "o": {"A": "采用CE-MRA并配合屏气", "B": "呼吸触发或导航采集3D数据", "C": "分时相采集区分动静脉", "D": "肾动脉MRA需薄层小FOV", "E": "必须使用心电门控"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-097", "kp": "腹部MRA要点", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】A：CE-MRA配合屏气是腹部血管主流。B：自由呼吸时用呼吸触发或导航保证3D数据质量。C：多时相（动脉/门脉/平衡期）区分动静脉结构。D：肾动脉细小，需薄层、小FOV、高分辨采集。\n【为什么错】E：腹部MRA不需要心电门控，心电门控用于心脏。", "tr": "腹部MRA关键词“屏气或呼吸触发/导航+多时相+薄层”；心电门控是心脏专属。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1098", "t": "多选题", "s": "下肢CE-MRA分段扫描的常规分段方式包括", "o": {"A": "髂股段", "B": "股腘段", "C": "膝下段", "D": "足背段单独扫描", "E": "只扫单一段落"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-098", "kp": "下肢MRA分段", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (9)外周血管", "ex": "【为什么对】A：髂股段覆盖腹主动脉下端至股深动脉。B：股腘段覆盖股浅动脉至腘动脉。C：膝下段覆盖胫前、胫后、腓动脉。三段步进采集后MIP拼接显示全程。\n【为什么错】D：足背段常并入膝下段一次覆盖，不单独常规扫描。E：只扫单段无法显示全程下肢血管。", "tr": "下肢MRA“髂股/股腘/膝下”三段式；足背动脉并入膝下段显示。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1099", "t": "多选题", "s": "脑PWI（灌注加权成像）常用的参数包括", "o": {"A": "相对脑血流量（rCBF）", "B": "相对脑血容量（rCBV）", "C": "平均通过时间（MTT）", "D": "达峰时间（TTP）", "E": "各向异性分数（FA）"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-099", "kp": "PWI参数", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】A：rCBF反映单位时间单位组织血流量。B：rCBV反映单位组织血容量。C：MTT为对比剂通过时间。D：TTP为达峰时间。四者共同描述脑灌注状态，用于梗死半暗带评估。\n【为什么错】E：FA为DTI各向异性参数，不属于PWI。", "tr": "PWI“四参数”（rCBF/rCBV/MTT/TTP）与DTI“FA”分属两家，勿混。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1100", "t": "多选题", "s": "脂肪抑制技术在临床应用中的注意事项包括", "o": {"A": "STIR对磁场不均匀不敏感", "B": "CHESS/SPIR对磁场均匀性要求高", "C": "增强后STIR可能抑制钆剂强化信号", "D": "Dixon可在均匀性较差区域更稳健地抑脂", "E": "STIR对磁场均匀性的要求高于CHESS"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-100", "kp": "脂肪抑制注意事项", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (7)预脉冲技术", "ex": "【为什么对】A：STIR基于TI过零抑制脂肪，不依赖频率选择，对磁场不均匀不敏感。B：CHESS/SPIR依赖脂肪共振频率精确饱和，匀场差则抑脂失败。C：STIR同时抑制所有短T1组织，增强后强化组织T1缩短也可被抑制，导致强化显示欠佳。D：Dixon多回波重建对匀场不均的耐受性更好。\n【为什么错】E：STIR不依赖频率精确选择，对磁场均匀性要求反而低于CHESS，方向说反。", "tr": "STIR“不挑磁场但会误伤强化（短T1）”，CHESS“挑磁场但抑脂纯”，两者对匀场的要求方向相反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1101", "t": "多选题", "s": "预饱和带技术的临床应用包括", "o": {"A": "抑制流动血流伪影", "B": "抑制运动组织伪影", "C": "MRA中抑制静脉或动脉信号", "D": "减少卷褶伪影", "E": "替代全部脂肪抑制技术"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-101", "kp": "预饱和带应用", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (6)饱和成像技术", "ex": "【为什么对】A：置于血流上游可抑制搏动血流伪影。B：置于运动部位抑制运动信号。C：MRA中抑制静脉（或动脉）信号提高目标血管显示。D：饱和带置于FOV外可减少信号卷褶入图。\n【为什么错】E：预饱和带不能替代脂肪抑制（抑脂需频率选择性或STIR技术）。", "tr": "预饱和带“多面手”但≠脂肪抑制；抑脂是预脉冲技术的另一个分支。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1102", "t": "多选题", "s": "心脏MR心电门控的方式包括", "o": {"A": "前瞻性门控（触发）", "B": "回顾性门控", "C": "心电向量门控", "D": "呼吸导航门控", "E": "外周脉搏触发"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-102", "kp": "心电门控方式", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】A：前瞻性门控在R波后固定延迟触发采集。B：回顾性门控采集全心动周期数据后按心动周期重建。C：心电向量门控抗干扰更强。E：外周脉搏触发可作为心电门控的替代方案（当心电信号差时）。\n【为什么错】D：呼吸导航用于呼吸运动控制，不属于心电门控方式。", "tr": "“心电相关门控”含前瞻/回顾/向量/脉搏触发；“导航”解决呼吸问题，别混入。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1103", "t": "多选题", "s": "3D采集序列相对于2D序列的优势包括", "o": {"A": "空间分辨率高", "B": "信噪比好", "C": "可各向同性采集便于多平面重建", "D": "薄层连续无层间隔", "E": "扫描时间必然缩短"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-103", "kp": "3D序列优势", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (8)辅助成像技术", "ex": "【为什么对】A：3D可做到更薄层厚、分辨率更高。B：3D整个容积激励，信噪比好。C：各向同性体素可任意角度MPR。D：3D为连续薄层编码，无层间隔。\n【为什么错】E：3D常需更长扫描时间（相位编码方向更多），并非必然缩短。", "tr": "3D“高分+高SNR+可重建+无间隔”，代价是时间长；“必然缩短”是陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1104", "t": "多选题", "s": "颅脑MRS临床应用场景包括", "o": {"A": "脑肿瘤分级与鉴别", "B": "癫痫病灶定位", "C": "放射性坏死与肿瘤复发鉴别", "D": "新生儿缺氧缺血性脑病评估", "E": "急性脑梗死面积测量"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-104", "kp": "颅脑MRS应用", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】A：肿瘤Cho/NAA比值变化助分级。B：癫痫病灶（海马）代谢改变可辅助定位。C：放射性坏死Lac/Lip峰、Cho不高，与复发（Cho高）不同。D：新生儿HIE乳酸峰升高、NAA下降，MRS有评估价值。\n【为什么错】E：急性梗死面积测量用DWI，MRS测代谢而非面积。", "tr": "MRS“看代谢谱”，用于鉴别与评估；面积、范围测量交给DWI。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1105", "t": "多选题", "s": "进入MR磁体检查室的安全注意事项包括", "o": {"A": "确认无心脏起搏器等绝对禁忌植入物", "B": "去除随身金属物品与磁卡", "C": "铁磁性轮椅、担架严禁推入磁体间", "D": "检查前再次核查患者身份与申请单", "E": "磁体间内可随意放置金属器械"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-105", "kp": "磁体间安全", "ch": "十、MR检查技术 → 1.MR检查准备 → (2)检查前准备", "ex": "【为什么对】A：绝对禁忌植入物确认是安全底线。B：金属物品防飞弹效应与伪影。C：铁磁性转运设备是“飞弹”最大来源，严禁入内。D：身份核查避免误检。\n【为什么错】E：磁体间内随意放置金属器械极其危险，可被吸入磁体。", "tr": "MR室安全核心“铁磁性物品禁入磁体间”；轮椅、氧气瓶、监护仪是高频事故源。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U10-1106a", "t": "单选题", "s": "【病例】患者男性，62岁，突发右侧肢体无力伴言语不清2小时来院，临床高度怀疑急性脑梗死，需立即行颅脑MR检查以明确诊断并评估梗死范围，技师需确定首选的检查序列与参数设置。 该患者首选用于发现急性梗死灶的序列是", "o": {"A": "DWI", "B": "MRCP", "C": "SWI", "D": "MRA", "E": "MRS"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-106", "kp": "急性脑梗死首选DWI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】急性脑梗死数小时内细胞毒性水肿致水分子扩散受限，DWI呈明显高信号、ADC降低，可在超早期（<2 h）显示病灶，是急性缺血诊断的首选序列，故A正确。\n【为什么错】B：MRCP为胰胆管水成像，与脑无关。C：SWI显示出血，梗死急性期无特异性。D：MRA显示血管闭塞，但不能直接显示梗死灶。E：MRS用于代谢分析，非急诊首选。", "tr": "“急性脑梗死先做DWI”是铁律；T2/FLAIR需数小时才显影，DWI超早期即阳性。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1106b", "t": "单选题", "s": "该患者DWI扫描常用的b值应设置为", "o": {"A": "b=0 s/mm²", "B": "b=400 s/mm²", "C": "b=1000 s/mm²", "D": "b=2000 s/mm²", "E": "b=5000 s/mm²"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-107", "kp": "颅脑DWI b值", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】颅脑DWI常规采用b=1000 s/mm²，弥散权重足够且信噪比好，是急性梗死标准化设置，故C正确。\n【为什么错】A：b=0为无弥散加权的基线像。B：b=400弥散权重不足，病灶显示不敏感。D：b=2000信噪比下降，非常规颅脑首选。E：b=5000为研究性超高b值。", "tr": "b值“越大扩散越敏感但SNR越低”；颅脑梗死标准b=1000 s/mm²。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1106c", "t": "单选题", "s": "DWI示病灶呈高信号，为排除T2穿透效应，应进一步观察", "o": {"A": "ADC图", "B": "T2*加权像", "C": "相位图", "D": "MIP重建图", "E": "脂肪抑制图"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-108", "kp": "T2穿透效应与ADC鉴别", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (3)MR功能成像", "ex": "【为什么对】ADC图量化水分子扩散程度：急性梗死扩散受限时ADC降低、ADC图上呈低信号，与T2穿透效应（DWI高但ADC正常）可明确鉴别，故A正确。\n【为什么错】B：T2*加权像反映磁敏感效应，非扩散评价。C：相位图为SWI组成部分，用于出血钙化鉴别。D：MIP用于血管重建。E：脂肪抑制与扩散评价无关。", "tr": "DWI判读“DWI+ADC”双图组合；ADC低＝真受限，ADC不低＝T2穿透。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1107a", "t": "单选题", "s": "【病例】患者女性，48岁，突发头痛伴左侧动眼神经麻痹，CT示鞍旁类圆形高密度影，临床疑颅内动脉瘤，拟行无创MRA检查明确动脉瘤位置、大小及瘤颈关系，技师负责选择检查技术并制定参数。 颅内动脉瘤首选的无创MRA技术是", "o": {"A": "3D TOF-MRA", "B": "2D TOF-MRA", "C": "PC-MRA定量", "D": "MRM", "E": "DWI"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-109", "kp": "颅内动脉瘤TOF-MRA", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】颅内血流速度较快，3D TOF-MRA分辨率高、信噪比好，可清晰显示Willis环周围动脉瘤及瘤颈，是颅内动脉瘤无创筛查与随访的首选MRA技术，故A正确。\n【为什么错】B：2D TOF分辨率低，对小动脉瘤显示不佳。C：PC-MRA常用于流速定量与静脉系统，非动脉瘤首选。D：MRM为脊髓水成像。E：DWI显示扩散受限，与动脉瘤无直接关系。", "tr": "“颅内快血流用3D TOF”是选择依据；2D TOF多用于颈部及下肢慢血流。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1107b", "t": "单选题", "s": "3D TOF-MRA扫描时，为抑制脑实质背景信号、提高血管对比度，可配合使用的技术是", "o": {"A": "磁化转移（MT）", "B": "STIR脂肪抑制", "C": "心电门控", "D": "弥散加权", "E": "呼吸触发"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-110", "kp": "TOF-MRA磁化转移", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】MT脉冲选择性饱和脑实质大分子结合水，使脑实质背景信号降低，而血流信号相对增高，血管对比度明显改善，是TOF-MRA抑制背景的常用辅助技术，故A正确。\n【为什么错】B：STIR抑脂不针对脑实质背景。C：心电门控用于心脏。D：DWI为扩散成像。E：呼吸触发用于胸腹部运动抑制，颅脑无需。", "tr": "TOF-MRA“背景抑制双保险”：短TR饱和＋MT脉冲；颅内背景抑制是图像质量关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1108a", "t": "单选题", "s": "【病例】患者男性，55岁，乙肝病史20年，超声发现肝右叶占位，临床疑肝细胞癌，拟行肝脏MRI动态增强检查明确病灶血供特征并分期，技师需设计扫描方案并控制运动伪影。 肝脏动态增强扫描采集的时相组合应为", "o": {"A": "动脉期、门静脉期、延迟期", "B": "皮质期、髓质期、排泄期", "C": "动脉期、静脉期、分泌期", "D": "仅动脉期一期", "E": "平扫后任意两期"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-111", "kp": "肝脏动态增强时相", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肝细胞癌典型血供为“动脉期明显强化、门脉期及延迟期廓清”，需采集动脉期、门静脉期、延迟期三期才能完整反映强化模式，故A正确。\n【为什么错】B：皮质髓质期为肾脏分期。C：分泌期为MRCP功能概念，不用于肝增强。D：仅动脉期无法观察廓清特征。E：无固定标准的“任意两期”不科学。", "tr": "HCC诊断要点“动脉期强化+门脉/延迟期廓清”，所以三期一个都不能少。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1108b", "t": "单选题", "s": "该患者动态增强扫描时，对比剂注射与扫描配合的正确做法是", "o": {"A": "高压注射器固定流率团注，采用对比剂跟踪或固定延迟启动动脉期扫描", "B": "手推缓慢注射后立即扫描", "C": "先扫描延迟期再扫描动脉期", "D": "注射对比剂前先行FLAIR", "E": "不注射对比剂直接扫三期"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-112", "kp": "肝脏增强对比剂方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肝动脉期窗口短（约20～30 s），需高压注射器固定流率团注并配合对比剂跟踪（bolus tracking）或团注测试确定启动时机，方能捕获动脉期，故A正确。\n【为什么错】B：手推流率不稳、动脉期难把握。C：先扫延迟期不符合时相顺序，延迟期在增强后期采集。D：FLAIR与增强无关。E：不注射对比剂无法评价血供。", "tr": "肝动脉期“短窗口+团注+跟踪启动”是技术关键；手推是常见错误操作。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1108c", "t": "单选题", "s": "该患者腹部扫描为抑制呼吸运动伪影，应采用", "o": {"A": "屏气采集或呼吸触发", "B": "增大翻转角", "C": "增加回波链长度", "D": "去除脂肪抑制", "E": "改用SWI序列"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-113", "kp": "腹部呼吸伪影控制", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】呼吸运动使肝脏在采集期间上下移动，产生运动伪影，屏气（快速序列呼气末屏气）或呼吸触发（在呼气平台期采集）是根本性控制措施，故A正确。\n【为什么错】B：翻转角影响对比度与SNR，与运动伪影无关。C：回波链长度影响图像锐度与SNR，不能解决呼吸运动。D：脂肪抑制是必需的，去除会致脂肪高信号干扰。E：SWI不适合肝脏动态增强。", "tr": "腹部成像质量第一敌人是呼吸运动，“屏气/呼吸触发/导航”三选一必备。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1109a", "t": "单选题", "s": "【病例】患者女性，60岁，皮肤巩膜黄染1个月进行性加重，超声示肝内外胆管扩张，临床疑胆总管下段梗阻，拟行MRCP明确梗阻部位与性质，技师负责制定水成像检查方案。 MRCP检查最适宜的序列与采集方式是", "o": {"A": "重T2加权FSE/TSE序列，结合3D薄层与2D厚层厚板采集", "B": "T1加权自旋回波", "C": "T2*加权梯度回波", "D": "弥散加权单层", "E": "SWI薄层扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-114", "kp": "MRCP序列选择", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (2)MR水成像", "ex": "【为什么对】MRCP采用重T2加权FSE/TSE序列（长TE），胆汁胰液呈高信号；3D薄层可任意重建显示细节，2D厚层厚板（thick-slab）投影整体显示胆道树，二者结合为规范方案，故A正确。\n【为什么错】B：T1加权下胆汁为低信号，无法水成像。C：T2*梯度回波对磁场不均敏感，信号衰减快，不用于水成像。D：DWI会抑制水信号。E：SWI用于磁敏感物质，与胆道显示无关。", "tr": "MRCP“重T2+长TE+3D薄层/2D厚板”是黄金组合；序列选择上“T1/T2*”是干扰。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1109b", "t": "单选题", "s": "该患者MRCP显示胆总管下段充盈缺损，为确定病变性质与手术方式，与MRCP互补的进一步检查应优先选择", "o": {"A": "薄层T2WI及增强扫描观察下段病变强化", "B": "单纯复查MRCP", "C": "SWI观察胆总管", "D": "MRS胆道代谢", "E": "下肢MRA"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-115", "kp": "MRCP与薄层增强互补", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】MRCP显示胆道形态（充盈缺损）但不能定性；薄层T2WI与增强扫描可观察病变（结石无强化、肿瘤强化）及胰头周围结构，帮助判断病变性质与可切除性，故A正确。\n【为什么错】B：单纯复查MRCP不能提供定性信息。C：SWI不能显示胆道病变。D：MRS在胆道无常规应用。E：下肢MRA与胆道梗阻无关。", "tr": "MRCP“管腔形态好、定性差”，定性需薄层+增强；这是水成像的固有局限。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1110a", "t": "单选题", "s": "【病例】患者女性，42岁，左乳外上象限扪及质硬肿块，超声BI-RADS 4类，临床拟行乳腺MR动态增强检查以进一步评估病灶范围与性质，技师负责乳腺MR检查的体位、线圈与序列安排。 乳腺MR检查的标准体位与线圈选择是", "o": {"A": "俯卧位、专用乳腺相控阵线圈", "B": "仰卧位、体部线圈", "C": "侧卧位、脊柱线圈", "D": "俯卧位、头线圈", "E": "仰卧位、下肢线圈"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-116", "kp": "乳腺MR体位线圈", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】乳腺MR采用俯卧位，双乳悬垂于专用乳腺相控阵线圈孔槽内，线圈贴合、信噪比高，且俯卧减少呼吸运动影响，故A正确。\n【为什么错】B：仰卧位乳腺受重力压缩且远离线圈。C：侧卧位无法双侧对称成像。D：头线圈不贴合乳腺。E：下肢线圈与乳腺检查无关。", "tr": "“俯卧+专用乳腺线圈”是乳腺MR标志性配置，体位错误会导致图像质量全面下降。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1110b", "t": "单选题", "s": "该患者动态增强后，病灶呈“快速上升后迅速下降”的时间-信号强度曲线，最可能的诊断倾向是", "o": {"A": "恶性病变", "B": "良性纤维腺瘤", "C": "单纯囊肿", "D": "正常腺体", "E": "脂肪瘤"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-117", "kp": "乳腺时间-信号曲线", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】Ⅲ型（流出型）曲线“快速上升+平台/下降”提示病灶富血供伴快速廓清，与恶性病变（血管内皮生长因子高表达）高度相关，故A正确。\n【为什么错】B：纤维腺瘤多呈Ⅰ型持续上升曲线。C：囊肿无强化。D：正常腺体无该型曲线。E：脂肪瘤无强化。", "tr": "曲线三型“流入（良性）—平台（可疑）—流出（恶性）”；流出型最警惕。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1111a", "t": "单选题", "s": "【病例】患者男性，35岁，搬运重物后腰痛伴左下肢放射痛1周，查体直腿抬高试验阳性，临床疑腰椎间盘突出，拟行腰椎MR检查，技师需确定扫描序列与定位方法。 腰椎MR常规扫描序列与方位应为", "o": {"A": "矢状位T1WI、T2WI加横断位T2WI", "B": "仅冠状位T2WI", "C": "矢状位DWI", "D": "轴位MRS", "E": "横断位MRM"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-118", "kp": "腰椎MR常规序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】腰椎MR以矢状位T1WI、T2WI显示椎体序列、间盘与椎管全貌，横断位T2WI观察突出方向及神经根受压，三者为常规组合，故A正确。\n【为什么错】B：仅冠状位不能显示椎间盘横断关系。C：DWI非腰椎常规。D：MRS在脊柱无常规价值。E：MRM仅间接显示脑脊液形态。", "tr": "脊柱MR“矢状T1/T2+横断T2”为标准方案；横断位对神经根压迫判断必不可少。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1111b", "t": "单选题", "s": "定位片中确认腰5-骶1间盘层面后，横断位扫描应垂直于什么方向定位", "o": {"A": "椎间隙（间盘层面）", "B": "脊柱矢状面任意方向", "C": "人体横轴", "D": "体表定位线", "E": "扫描床长轴"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-119", "kp": "腰椎横断位定位", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】腰椎有生理前凸，横断位应逐层平行于椎间隙（垂直椎管长轴）定位，才能准确显示间盘后突与侧隐窝、神经根关系，故A正确。\n【为什么错】B：垂直矢状面无法保证与间盘平行。C：平行人体横轴在腰椎前凸段会斜切间盘。D：体表定位线是粗略参照。E：扫描床长轴为身体纵轴，非定位依据。", "tr": "脊柱横断位“逐层平行椎间隙”是定位铁律，颈椎腰椎前凸处尤其关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1112a", "t": "单选题", "s": "【病例】患者男性，68岁，血清PSA 12 ng/ml，直肠指诊触及前列腺质硬结节，临床疑前列腺癌，拟行前列腺多参数MRI（mpMRI）检查，技师负责序列组合与参数设置。 该患者mpMRI的常规序列组合应为", "o": {"A": "T2WI、DWI/ADC及动态增强（DCE）", "B": "仅轴位T1WI", "C": "STIR加MRU", "D": "SWI加MRA", "E": "仅MRS单体素"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-120", "kp": "前列腺mpMRI序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】前列腺mpMRI以高分辨T2WI（显示外周带与癌灶低信号）、DWI/ADC（扩散受限）、动态增强（早期强化与廓清）为三大核心，必要时加MRS，故A正确。\n【为什么错】B：仅T1WI无法显示前列腺分区信号。C：STIR与MRU不用于前列腺癌评估。D：SWI、MRA与前列腺癌诊断无关。E：仅MRS信息不完整。", "tr": "前列腺mpMRI“T2+DWI+DCE”三剑客；T1WI仅用于观察出血与淋巴结基线。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1112b", "t": "单选题", "s": "该患者DWI示外周带病灶呈高信号且ADC值明显降低，其意义是", "o": {"A": "提示病灶细胞密度高、扩散受限，恶性可能性大", "B": "提示病灶为单纯囊肿", "C": "提示病灶出血", "D": "提示病灶为脂肪", "E": "提示扫描失败"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-121", "kp": "前列腺DWI判读", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】癌细胞密集、细胞外间隙减小，水分子扩散受限，DWI呈高信号而ADC降低，这是前列腺癌在mpMRI上的典型表现，故A正确。\n【为什么错】B：囊肿扩散自由、ADC高。C：出血靠T1/SWI观察。D：脂肪DWI信号经抑脂处理已压低。E：信号表现正常，非扫描失败。", "tr": "前列腺DWI判读“高b值高信号+ADC低”才提示恶性；单看DWI要防T2穿透。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1113a", "t": "单选题", "s": "【病例】患者男性，50岁，胸痛1天，肌钙蛋白升高，临床疑急性心肌梗死，拟行心脏MR检查评估心肌活性与功能，技师负责心脏MR的采集技术与序列安排。 心脏MR为抑制心脏搏动伪影，必须采用的辅助技术是", "o": {"A": "心电门控（ECG gating）", "B": "呼吸触发", "C": "脂肪抑制", "D": "弥散加权", "E": "饱和带"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-122", "kp": "心脏MR心电门控", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】心脏呈周期性搏动，必须用心电门控以R波为触发信号，在心动周期特定时相采集，才能获得无搏动伪影的心脏图像，故A正确。\n【为什么错】B：呼吸触发解决呼吸运动，不能解决心跳。C：脂肪抑制为预脉冲技术。D：弥散加权用于扩散成像。E：饱和带抑制局部信号，不能同步心跳。", "tr": "心脏MR“心电门控”是根基；无门控的心脏图像无法用于诊断。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1113b", "t": "单选题", "s": "该患者行延迟强化（LGE）扫描评价梗死范围，正确的做法是", "o": {"A": "静脉注射钆剂后10～15分钟行反转恢复T1加权扫描", "B": "平扫即观察梗死", "C": "注射后立即T2加权扫描", "D": "注射后24小时扫描", "E": "用DWI替代"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-123", "kp": "心肌LGE", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】钆剂在梗死/纤维化心肌中滞留，注射后10～15分钟以反转恢复T1加权（LGE）扫描，正常心肌信号被抑制、梗死区呈高信号，可直接显示梗死透壁范围，故A正确。\n【为什么错】B：平扫无强化信息。C：T2加权用于急性期心肌水肿。D：24小时对比剂已廓清。E：DWI不用于心肌梗死强化评估。", "tr": "LGE“15分钟+IR-T1”是标准；T2水肿与LGE梗死是心肌MR的两大时相技术。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1114a", "t": "单选题", "s": "【病例】患者男性，70岁，头晕伴一过性黑矇，颈动脉超声示左侧颈内动脉起始部重度狭窄，临床拟行颈动脉CE-MRA精确评估狭窄程度，技师负责对比剂注射与扫描时机管理。 为确保颈动脉动脉期采集时机准确，应采用的方案是", "o": {"A": "对比剂跟踪（bolus tracking）或团注测试确定延迟时间", "B": "注射后固定等10分钟再扫描", "C": "先扫描再注射对比剂", "D": "不用对比剂用TOF替代", "E": "任意时相均可"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-124", "kp": "CE-MRA扫描时机", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】CE-MRA须在对比剂首次通过动脉时采集动脉期，采用对比剂跟踪实时监测或小剂量团注测试（test bolus）计算延迟时间，可准确捕获动脉期，故A正确。\n【为什么错】B：固定10分钟为静脉期甚至延迟期，动静脉重叠。C：先扫描无对比剂强化。D：TOF为备选非增强方案，但本问针对CE-MRA时机。E：时相不准则动静脉重叠，不能任意。", "tr": "CE-MRA成败在“时机”，团注测试+跟踪是规范；延迟不当动脉期丢失。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1114b", "t": "单选题", "s": "该患者扫描中如出现静脉早显明显重叠动脉，技师首先应", "o": {"A": "调整延迟时间、缩短动脉期采集窗口，必要时重复动脉期采集", "B": "结束检查不作处理", "C": "增大对比剂剂量", "D": "改用平扫T1WI", "E": "降低矩阵"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-125", "kp": "CE-MRA静脉重叠处理", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】静脉早显说明动脉期采集偏晚或采集窗口过长，应重新计算延迟时间、采用时间分辨或短窗采集在动脉期完成，必要时重扫动脉期，故A正确。\n【为什么错】B：直接结束检查无法获得诊断信息。C：增大剂量不解决时相问题，反增静脉强化。D：平扫T1WI无血管增强信息。E：降低矩阵损失分辨率，不解决问题。", "tr": "静脉重叠本质是“时相错位”，对策是“调时相、短窗口、重扫动脉期”，与剂量无关。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1115a", "t": "单选题", "s": "【病例】患者男性，25岁，打篮球扭伤右膝，关节肿胀、交锁，临床疑半月板及前交叉韧带损伤，拟行膝关节MR检查，技师负责选择线圈、体位与序列。 膝关节MR检查应采用的线圈与体位是", "o": {"A": "专用膝关节线圈、仰卧位、膝关节轻度屈曲外旋", "B": "体部线圈、站立位", "C": "头线圈、俯卧位", "D": "脊柱线圈、侧卧位", "E": "不用线圈直接扫描"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-126", "kp": "膝关节MR体位线圈", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】膝关节MR采用专用膝关节相控阵线圈、仰卧位，轻度屈曲（约10°～20°）并外旋使前交叉韧带与矢状位平行，利于显示，故A正确。\n【为什么错】B：体部线圈贴合差、分辨率低；站立位无法扫描。C：头线圈形状不匹配。D：脊柱线圈不贴合关节形态。E：无线圈无信号。", "tr": "关节MR“专用线圈+自然体位”；膝关节外旋可改善前交叉韧带显示，是细节考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1115b", "t": "单选题", "s": "该患者矢状位PD加权显示内侧半月板内线性高信号延伸至关节面，最可能的诊断是", "o": {"A": "半月板撕裂", "B": "半月板正常", "C": "关节游离体", "D": "骨髓水肿", "E": "韧带断裂"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-127", "kp": "半月板撕裂MR表现", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】正常半月板各序列均匀低信号，若PD/T2加权见异常高信号线延伸达关节面（Ⅲ级信号），提示半月板撕裂，故A正确。\n【为什么错】B：正常半月板无高信号。C：游离体为关节腔内游离块状物，与半月板内信号无关。D：骨髓水肿位于骨骺端骨髓内。E：韧带断裂表现为韧带形态信号异常，非半月板内信号。", "tr": "半月板信号分级：Ⅰ级（点状）、Ⅱ级（线状未达关节面）、Ⅲ级（达关节面＝撕裂）；只有Ⅲ级诊断撕裂。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1116", "t": "案例分析题", "s": "患者男性，63岁，晨起突发右侧肢体无力伴言语不清1.5小时来院，NIHSS评分9分，发病时间在溶栓时间窗内，临床疑急性脑梗死，拟行急诊颅脑MR检查。技师需在最短时间内完成检查并保证诊断价值，设备为1.5T超导磁体。关于该急诊MR检查方案，最合理的是", "o": {"A": "先行DWI与ADC，结合轴位T1WI、T2WI及FLAIR快速完成", "B": "只做MRS分析代谢", "C": "先做SWI再看增强", "D": "先做MRM水成像", "E": "只扫描矢状位T2WI"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-128", "kp": "急性脑梗死急诊MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】急性缺血时间窗内需争分夺秒：DWI+ADC超早期显示梗死灶并排除T2穿透，同时快速采集T1WI、T2WI、FLAIR评估出血、缺血范围及陈旧病变，兼顾速度与全面性，故A正确。\n【为什么错】B：MRS耗时长，非急诊方案。C：SWI虽可排出血，但方案不完整且SWI非梗死诊断主序列。D：MRM为脊髓水成像，与脑梗死无关。E：单矢状位无法全面评价。", "tr": "急诊脑梗MR“DWI/ADC先行+快速平扫”，时间与诊断价值并重；溶栓决策依赖DWI。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1117", "t": "案例分析题", "s": "患者女性，50岁，头痛3个月伴视物模糊，MR平扫示右额叶占位，T1WI低信号、T2WI高信号，周围水肿明显，临床疑胶质瘤，需行MR增强扫描明确血脑屏障破坏情况并指导活检定位。技师准备钆对比剂并安排扫描序列。正确的做法是", "o": {"A": "静脉注射0.1 mmol/kg钆剂后，行轴位、冠状位及矢状位T1WI脂肪抑制扫描", "B": "注射后仅扫描轴位T2WI", "C": "注射后行DWI高b值扫描", "D": "无需增强直接MRS", "E": "注射后24小时再扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-129", "kp": "脑肿瘤增强方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】脑肿瘤增强用钆剂（0.1～0.2 mmol/kg），增强后行多方位T1WI（加脂肪抑制），强化区反映血脑屏障破坏，是肿瘤定性、定界与活检定位的基础，故A正确。\n【为什么错】B：T2WI对强化不敏感。C：DWI反映扩散受限，不是强化评价。D：MRS为辅助，不能替代增强。E：延迟至24小时对比剂已廓清。", "tr": "增强“看强化=增强后T1WI+抑脂”，多方位采集；单方位会漏病灶边缘信息。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1118", "t": "案例分析题", "s": "患者女性，47岁，突发剧烈头痛伴喷射性呕吐3小时，急诊CT示基底池及鞍上池蛛网膜下腔出血，临床疑颅内动脉瘤破裂，拟行无创MRA评估动脉瘤大小与瘤颈。技师选择TOF-MRA技术并优化参数。关于检查技术的描述，正确的是", "o": {"A": "选用3D TOF-MRA，翻转角20°～35°，配合磁化转移提高血管对比", "B": "选用2D TOF-MRA覆盖全脑", "C": "选用MRM水成像显示动脉瘤", "D": "不用MRA直接行DWI", "E": "选用STIR抑制血流"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-130", "kp": "颅内动脉瘤TOF-MRA参数", "ch": "十、MR检查技术 → 2.MR特殊检查技术 → (1)MRA", "ex": "【为什么对】颅内血流快，3D TOF-MRA分辨率高、适合显示Willis环动脉瘤；翻转角约20°～35°抑制背景，MT脉冲进一步提高血管对比，故A正确。\n【为什么错】B：2D TOF分辨率低，小动脉瘤显示不佳。C：MRM为脊髓水成像。D：DWI不显示动脉瘤形态。E：STIR为脂肪抑制技术，不用于血管成像。", "tr": "3D TOF+小翻转角+MT是颅内MRA标准组合；“2D TOF”只用于慢血流大范围筛查。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "MR特殊检查技术", "页": 267}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1119", "t": "案例分析题", "s": "患者女性，33岁，闭经溢乳3个月，血清泌乳素升高，临床疑垂体微腺瘤，拟行垂体MR高分辨检查。技师需设计小FOV薄层扫描与动态增强方案。关于该检查技术的叙述，正确的是", "o": {"A": "采用2～3 mm薄层、小FOV矢状位与冠状位扫描，并行动态增强观察垂体早期强化", "B": "厚层大FOV轴位平扫即可", "C": "只需矢状位T2WI", "D": "用SWI替代T1WI", "E": "动态增强用T2加权扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-131", "kp": "垂体微腺瘤高分辨扫描", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】垂体微腺瘤直径常<10 mm，需薄层（2～3 mm）、小FOV、高分辨矢状+冠状位扫描，动态增强（注射后连续快速T1加权采集）观察垂体后叶提前强化与腺瘤相对低强化，故A正确。\n【为什么错】B：厚层大FOV空间分辨率不足易漏诊。C：矢状位单方位不够。D：SWI不显示垂体解剖细节。E：动态增强用T1加权而非T2加权。", "tr": "微腺瘤“薄层小FOV+矢冠双方位+动态增强”三要素；动态增强必须T1加权。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1120", "t": "案例分析题", "s": "患者女性，29岁，双下肢麻木无力伴视力下降，脑脊液寡克隆区带阳性，临床疑多发性硬化，拟行颅脑及颈椎MR检查评估病灶负荷。技师制定扫描方案时，应重点选择的序列是", "o": {"A": "颅脑轴位FLAIR与矢状位T2WI，颈椎矢状位T2WI及横断位扫描", "B": "仅颅脑DWI", "C": "颅脑MRS", "D": "颅脑SWI加MRM", "E": "仅颈椎冠状位STIR"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-132", "kp": "多发性硬化MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (1)颅脑", "ex": "【为什么对】MS病灶以室周白质为主，FLAIR对近脑脊液病灶最敏感，矢状位T2WI显示胼胝体病灶；颈椎矢状T2WI+横断位可显示脊髓内斑块，故A正确。\n【为什么错】B：仅DWI对MS斑块评估不足。C：MRS为辅助手段。D：SWI显示静脉周围征有辅助价值，但MRM非主要。E：仅STIR冠状位不完整。", "tr": "MS“颅脑FLAIR+脊髓T2”是评估病灶负荷的核心组合；“FLAIR看脑室旁、T2看脊髓”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1121", "t": "案例分析题", "s": "患者男性，55岁，颈肩痛伴右上肢麻木3个月，低头时加重，查体颈部压痛、Hoffmann征可疑阳性，临床疑颈椎病，拟行颈椎MR检查。技师需确定扫描序列、方位及定位要点。正确的做法是", "o": {"A": "矢状位T1WI与T2WI加横断位扫描，横断位逐层平行椎间隙定位", "B": "仅矢状位T1WI", "C": "仅轴位DWI", "D": "仅冠状位STIR", "E": "仅矢状位MRM"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-133", "kp": "颈椎MR检查方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】颈椎MR矢状位T1/T2WI显示间盘突出与脊髓受压，横断位逐层平行椎间隙定位可准确显示神经根受压，故A正确。\n【为什么错】B：仅矢状T1WI无法显示间盘信号特征与横断关系。C：DWI非常规。D：STIR单方位不完整。E：MRM仅显示脑脊液形态。", "tr": "颈椎MR“矢状+横断”双方位；横断位平行椎间隙定位是颈段解剖特点的要求。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1122", "t": "案例分析题", "s": "患者男性，41岁，搬重物后腰痛伴左下肢放射痛，咳嗽加重，临床疑腰4-5椎间盘突出，拟行腰椎MR检查明确突出程度与神经根受压情况。技师制定扫描方案时，下列做法最合理的是", "o": {"A": "矢状位T1WI、T2WI加横断位T2WI，重点扫描腰4-5与腰5骶1间盘层面", "B": "只扫矢状位T1WI", "C": "只扫轴位MRS", "D": "只扫冠状位T2WI", "E": "扫描下肢MRA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-134", "kp": "腰椎间盘突出MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】腰椎间盘突出以腰4-5、腰5骶1最常见，矢状位T1/T2WI整体显示间盘与椎管，横断位T2WI精确判断突出方向与神经根受压，故A正确。\n【为什么错】B：仅矢状T1WI无法显示椎间盘退变信号细节与横断关系。C：MRS与间盘突出无关。D：冠状位不显示椎间盘与神经根关系。E：下肢MRA与腰椎间盘无关。", "tr": "腰椎间盘突出“矢状+横断T2”为常规；临床定位与扫描范围要覆盖最常见节段。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1123", "t": "案例分析题", "s": "患者男性，19岁，进行性双下肢无力伴背部束带感2个月，临床疑脊髓内占位（室管膜瘤可能），拟行胸段脊髓MR检查明确病变范围与性质。技师安排扫描时，正确的方案是", "o": {"A": "矢状位T1WI、T2WI及增强后T1WI，加横断位明确脊髓内病灶定位", "B": "仅矢状位DWI", "C": "仅冠状位MRA", "D": "仅横断位SWI", "E": "仅矢状位MRM"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-135", "kp": "脊髓占位MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (2)脊柱脊髓", "ex": "【为什么对】脊髓肿瘤MR以矢状位T1WI（显示肿瘤范围与出血）、T2WI（显示囊变水肿）及增强后T1WI（肿瘤强化）为核心，横断位明确肿瘤在脊髓内的位置与脊髓膨胀程度，故A正确。\n【为什么错】B：DWI非脊髓肿瘤常规。C：MRA显示血管。D：SWI用于出血钙化。E：MRM仅显示脑脊液间接征象。", "tr": "脊髓占位“矢状三序列（T1/T2/增强）+横断定位”是标准方案，增强对肿瘤定性关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1124", "t": "案例分析题", "s": "患者男性，52岁，回缩涕血伴耳鸣2个月，鼻咽镜见右侧咽隐窝肿物隆起，病理疑鼻咽癌，拟行MR检查评估肿瘤范围、颅底侵犯及颈部淋巴结。技师制定扫描范围与序列时，正确的是", "o": {"A": "扫描范围自颅底至锁骨上，行轴位T1WI、T2WI脂肪抑制、DWI及增强扫描", "B": "仅扫描鼻咽部轴位T2WI", "C": "仅扫描颈部淋巴结区", "D": "仅扫描矢状位T1WI", "E": "仅扫描下颌区"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-136", "kp": "鼻咽癌MR检查范围", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】鼻咽癌易沿颅底孔道（破裂孔、卵圆孔等）向上侵犯并发生颈部淋巴结转移，MR范围须从颅底延伸至锁骨上，轴位T1WI、T2WI脂肪抑制显示肿瘤与淋巴结，DWI与增强辅助定性，故A正确。\n【为什么错】B：范围过小漏诊颅底侵犯与转移。C：仅淋巴结遗漏原发灶。D：单矢状位无法评价两侧与颅底。E：下颌区范围不足。", "tr": "头颈肿瘤MR“大范围+多序列+DWI+增强”；范围不足是漏诊主因。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1125", "t": "案例分析题", "s": "患者女性，38岁，右眼球突出伴复视1个月，超声示右眼眶肌锥内占位，临床疑海绵状血管瘤，拟行眼眶MR检查。技师设置扫描序列时，为清晰显示视神经、眼外肌与病变，应优先采用的序列是", "o": {"A": "脂肪抑制T2WI（或STIR）加增强后脂肪抑制T1WI", "B": "不抑脂的T1WI", "C": "仅SWI", "D": "仅MRA", "E": "仅MRU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-137", "kp": "眼眶MR序列", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (3)头颈部", "ex": "【为什么对】眶内脂肪高信号会掩盖视神经与病变，脂肪抑制T2WI/STIR可压低脂肪突出病变与神经；增强后脂肪抑制T1WI显示病灶强化特征，故A正确。\n【为什么错】B：不抑脂T1WI脂肪干扰严重。C：SWI用于出血钙化。D：MRA显示血管。E：MRU为尿路水成像。", "tr": "眶内成像“抑脂”是关键词；视神经、眼外肌与脂肪的高对比依赖脂肪抑制序列。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1126", "t": "案例分析题", "s": "患者女性，45岁，左乳外上象限肿块，超声BI-RADS 4C类，拟行乳腺MR动态增强检查，设备为3T磁体，使用专用乳腺线圈。技师制定扫描方案，需包括动态增强多期扫描、DWI及时间-信号强度曲线分析。关于该检查的叙述，正确的是", "o": {"A": "俯卧位双乳悬垂于线圈孔槽，先平扫再注射钆剂行多期动态增强", "B": "仰卧位用体部线圈扫描", "C": "只扫T2WI不增强", "D": "只扫DWI不增强", "E": "增强后只扫MRA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-138", "kp": "乳腺DCE-MRI方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (4)胸部和乳腺", "ex": "【为什么对】乳腺DCE-MRI标准流程为俯卧位、专用线圈，平扫（T1、T2抑脂、DWI）后团注钆剂行多期（如6期）动态增强扫描，并生成时间-信号强度曲线与MIP，故A正确。\n【为什么错】B：仰卧位体部线圈图像质量差。C：不增强无法评估血供与曲线。D：仅DWI信息不足。E：MRA非乳腺增强方案。", "tr": "乳腺DCE“平扫+团注多期+曲线”完整链条；体位线圈错误则全盘皆输。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1127", "t": "案例分析题", "s": "患者男性，58岁，扩张型心肌病病史，近期心衰加重，超声示左心室扩大、射血分数28%，临床疑心肌纤维化，拟行心脏MR评估心肌活性与纤维化分布。技师安排心脏MR检查时，正确的是", "o": {"A": "心电门控下采集黑血与亮血序列，注射钆剂后10～15分钟行LGE扫描", "B": "不接心电门控直接扫描", "C": "只扫LGE不扫电影", "D": "用SWI评价心肌", "E": "用MRU评价心功能"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-139", "kp": "心脏MR心肌纤维化评估", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】心脏MR须心电门控下采集，黑血序列显示心肌形态、亮血电影评价心功能，注射钆剂后10～15分钟LGE显示心肌纤维化（DCM常呈中壁强化），故A正确。\n【为什么错】B：无门控心脏图像无法诊断。C：电影序列是心功能评价必需。D：SWI不用于心肌纤维化。E：MRU为尿路水成像。", "tr": "心肌纤维化“LGE”是金标准；门控+电影+LGE是心脏MR三件套。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1128", "t": "案例分析题", "s": "患者男性，60岁，突发胸背部撕裂样疼痛2小时，血压200/120 mmHg，临床疑主动脉夹层，拟行主动脉CE-MRA紧急检查。技师需规划对比剂注射、采集范围与时相。关于该检查技术，正确的是", "o": {"A": "高压注射器团注钆剂，多期动态采集覆盖主动脉全程，MIP重建显示内膜片", "B": "手推对比剂后单期扫描", "C": "只扫升主动脉", "D": "用2D TOF替代", "E": "扫描前禁水12小时"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-140", "kp": "主动脉夹层CE-MRA", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (5)心脏大血管", "ex": "【为什么对】主动脉夹层累及范围广，需高压注射器团注并多期动态扫描覆盖全程，MIP可显示内膜片、真假腔及分支受累，故A正确。\n【为什么错】B：手推单期易错过真假腔充盈时相。C：只扫升主动脉漏诊降主动脉夹层。D：2D TOF对大血管急症敏感性与时间效率不足。E：主动脉MRA无需禁水12小时。", "tr": "主动脉CE-MRA“团注+多期+全程覆盖+MIP”四要素；内膜片显示依赖时相准确性。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1129", "t": "案例分析题", "s": "患者女性，48岁，体检超声发现肝右叶2.5 cm强回声结节，拟行肝脏MRI动态增强检查明确性质。技师安排扫描时，肝血管瘤的典型动态增强MR表现及技术要点是", "o": {"A": "动脉期周边结节状强化，延迟期向心性填充呈均匀高信号，延迟扫描时间需足够长", "B": "动脉期整体高强化、延迟期廓清", "C": "无强化", "D": "仅平扫即可诊断", "E": "强化后即刻快速廓清"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-141", "kp": "肝血管瘤动态增强", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肝血管瘤典型表现为动脉期病灶周边结节状强化、随时间向心性填充，延迟期呈均匀高信号，因此延迟扫描（可至5～10分钟）必须足够长才能显示完全填充，故A正确。\n【为什么错】B：整体高强化+廓清为HCC表现。C：血管瘤血供丰富必有强化。D：仅平扫无法显示强化模式。E：快速廓清为恶性特征。", "tr": "血管瘤“边缘结节状强化+延迟填充”与HCC“快进快出”是肝增强两大经典鉴别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1130", "t": "案例分析题", "s": "患者男性，58岁，乙肝肝硬化10年，甲胎蛋白进行性升高，超声示肝右叶低回声占位，临床疑肝细胞癌，拟行肝脏MRI动态增强结合DWI检查。技师设定扫描方案，肝细胞癌在动态增强与DWI上的典型表现为", "o": {"A": "动脉期明显强化、门脉期及延迟期廓清，DWI呈高信号、ADC降低", "B": "动脉期无强化", "C": "延迟期持续上升强化", "D": "DWI低信号", "E": "各期均无强化"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-142", "kp": "肝细胞癌增强与DWI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】HCC典型“快进快出”：动脉期明显强化（富血供）、门脉期及延迟期廓清；癌细胞密集扩散受限，DWI高信号、ADC降低，故A正确。\n【为什么错】B：HCC动脉期强化明显。C：持续上升强化为血管瘤填充或纤维化。D：HCC扩散受限DWI应高信号。E：HCC必有血供强化。", "tr": "HCC“快进快出+DWI高+ADC低”；与血管瘤“迟填充”相反，是必考鉴别点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1131", "t": "案例分析题", "s": "患者男性，72岁，无痛性进行性黄疸2周，超声示肝内外胆管扩张、胆总管下段腔内可疑等回声，临床疑胆总管下段肿瘤性梗阻，拟行MRCP及上腹部MR检查。技师安排检查时，正确的技术方案是", "o": {"A": "重T2加权MRCP显示胆道梗阻形态，加薄层T2WI及增强扫描评价下段病变性质", "B": "只做MRCP一个序列", "C": "用DWI替代MRCP", "D": "只做MRA", "E": "用SWI显示胆管"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-143", "kp": "胆道梗阻MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】MRCP显示胆道树梗阻部位与扩张形态，但定性有限；联合薄层T2WI与增强扫描可观察下段病变（肿瘤强化）及周围结构，完成定位与定性，故A正确。\n【为什么错】B：仅MRCP无法定性梗阻病变。C：DWI不能显示胆道形态。D：MRA显示血管。E：SWI不显示胆管。", "tr": "梗阻性黄疸MR“MRCP（管腔）+薄层增强（定性）”缺一不可，这体现水成像的应用边界。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1132", "t": "案例分析题", "s": "患者女性，55岁，上腹饱胀伴腰背痛2个月，CT示胰头占位、胰管扩张呈“双管征”，临床疑胰头癌，拟行胰腺MR联合MRCP检查评估可切除性。技师制定扫描方案，正确的做法是", "o": {"A": "薄层T1WI、T2WI脂肪抑制、DWI及动态增强，联合MRCP显示胰胆管", "B": "仅MRCP一个序列", "C": "仅冠状位T1WI", "D": "仅SWI", "E": "仅MRU"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-144", "kp": "胰腺MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】胰腺MR以薄层T1WI、T2WI脂肪抑制（显示肿瘤与胰周脂肪）、DWI（ADC降低提示恶性）及动态增强（乏血供强化模式）为核心，MRCP显示双管征与梗阻部位，联合评估可切除性，故A正确。\n【为什么错】B：仅MRCP无法评估肿瘤本身。C：单冠状位信息不足。D：SWI不用于胰腺癌。E：MRU为尿路成像。", "tr": "胰腺癌MR“实质多序列+DWI+增强+MRCP”组合；双管征为胰头癌间接征象。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1133", "t": "案例分析题", "s": "患者男性，61岁，体检超声发现左肾2 cm实性占位，临床疑肾细胞癌，拟行肾脏MR检查评估肿瘤分期及血管侵犯。技师制定扫描方案，正确的是", "o": {"A": "呼吸触发采集轴位T1WI、T2WI脂肪抑制及DWI，动态增强分皮质期、髓质期、排泄期", "B": "仅矢状位T2WI", "C": "仅MRU", "D": "仅SWI", "E": "仅冠状位STIR"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-145", "kp": "肾脏MR方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (6)腹部", "ex": "【为什么对】肾脏MR常规呼吸触发采集T1/T2抑脂与DWI（鉴别囊实性），动态增强按肾脏血流特点分皮质期、髓质期与排泄期，利于显示肿瘤强化与肾静脉、腔静脉瘤栓，故A正确。\n【为什么错】B：单方位不完整。C：MRU显示积水形态，不显示肿瘤。D：SWI用于出血钙化。E：单STIR冠状位信息不足。", "tr": "肾脏增强“皮质-髓质-排泄”三期命名区别于肝脏“动脉-门脉-延迟”，是经典易混点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1134", "t": "案例分析题", "s": "患者男性，66岁，PSA 15 ng/ml，直肠指诊前列腺右侧质硬结节，穿刺活检证实前列腺腺癌（Gleason 7），拟行前列腺多参数MRI行局部分期（T分期）。技师安排检查时，正确的技术方案是", "o": {"A": "高分辨T2WI三方位、DWI/ADC及动态增强，必要时加MRS，观察包膜侵犯与精囊受累", "B": "仅轴位T1WI", "C": "仅MRU", "D": "仅SWI", "E": "仅矢状位STIR"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-146", "kp": "前列腺癌局部分期MRI", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】前列腺癌局部分期需高分辨T2WI三方位（轴、矢、冠）观察外周带病灶与包膜、精囊受累，DWI/ADC与动态增强辅助，MRS可作补充，故A正确。\n【为什么错】B：T1WI无分区显示能力。C：MRU与前列腺癌分期无关。D：SWI不用于分期。E：STIR非前列腺常规。", "tr": "前列腺癌分期“T2WI三方位的包膜/精囊评估”是核心；DWI低b值勿受T2穿透干扰。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1135", "t": "案例分析题", "s": "患者女性，52岁，阴道不规则出血1个月，超声示宫腔内占位、内膜增厚，临床疑子宫内膜癌，拟行盆腔MR评估肌层浸润深度。技师安排检查时，正确的方案是", "o": {"A": "矢状位高分辨T2WI显示内膜与肌层三层结构，加DWI及动态增强判断肌层浸润", "B": "仅轴位T1WI", "C": "仅冠状位STIR", "D": "仅MRU", "E": "仅横断位SWI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-147", "kp": "子宫内膜癌MR", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (7)盆腔", "ex": "【为什么对】子宫内膜癌分期关键是肌层浸润深度，矢状位高分辨T2WI显示子宫三层结构（结合带中断提示浸润），DWI与动态增强辅助判断浸润范围，故A正确。\n【为什么错】B：T1WI不能区分内膜肌层。C：STIR冠状位不显示结合带细节。D：MRU与子宫病变无关。E：SWI不用于子宫内膜癌。", "tr": "子宫内膜癌“矢状T2WI看结合带、动态增强+DWI看浸润”是分期核心技术。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1136", "t": "案例分析题", "s": "患者男性，22岁，足球比赛扭伤右膝，膝关节肿胀、前抽屉试验阳性，临床疑前交叉韧带断裂，拟行膝关节MR检查。技师制定扫描方案，正确的做法是", "o": {"A": "矢状位PD加权（沿前交叉韧带走行）及脂肪抑制T2加权，配合冠状位与轴位", "B": "仅轴位T1WI", "C": "仅冠状位SWI", "D": "仅矢状位MRA", "E": "仅横断位MRS"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-148", "kp": "前交叉韧带MR", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】前交叉韧带显示需矢状位沿其走行方向扫描，PD加权显示韧带纤维连续性（断裂呈中断、肿胀、信号异常），脂肪抑制T2加权显示伴随的骨挫伤与积液，多方位互补，故A正确。\n【为什么错】B：T1WI对韧带水肿显示差。C：SWI用于出血。D：MRA显示血管。E：MRS非韧带检查。", "tr": "前交叉韧带“矢状PD沿走行”是核心；关节MR“PD/FS-T2”是韧带与软骨显示的通用序列。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1137", "t": "案例分析题", "s": "患者女性，51岁，右肩疼痛伴上举受限3个月，夜间痛明显，体检冈上肌止点压痛、Jobe试验阳性，临床疑肩袖损伤，拟行肩关节MR检查。技师制定扫描方案，正确的是", "o": {"A": "斜冠状位脂肪抑制PD/T2沿冈上肌长轴显示肌腱，配合斜矢状位与轴位", "B": "仅轴位T1WI", "C": "仅纯矢状位", "D": "仅冠状位MRA", "E": "仅横断位DWI"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-149", "kp": "肩袖损伤MR", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (8)肌肉骨骼关节", "ex": "【为什么对】肩袖损伤（尤其冈上肌腱）须在斜冠状位（沿冈上肌长轴）用脂肪抑制PD/T2显示肌腱全层与撕裂（液体高信号贯穿肌腱），配合斜矢状位显示肩袖肌肉萎缩、轴位显示肩胛下肌等，故A正确。\n【为什么错】B：T1WI液体低信号，撕裂显示差。C：纯矢状位不沿肌腱长轴。D：MRA显示血管。E：DWI非常规。", "tr": "肩袖检查“斜冠状位沿冈上肌长轴+FS-PD/T2”是标准；撕裂诊断依赖液体敏感序列。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U10-1138", "t": "案例分析题", "s": "患者男性，70岁，间歇性跛行6个月，双下肢皮温低、足背动脉搏动减弱，超声示下肢动脉多发狭窄，临床疑下肢动脉闭塞症，拟行下肢动脉CE-MRA评估全程血管病变。技师制定分段扫描方案，正确的是", "o": {"A": "分髂股、股腘、膝下三段连续采集，高压注射器团注钆剂，多段MIP拼接显示全程", "B": "单次扫描覆盖全下肢", "C": "用2D TOF替代全程", "D": "仅扫描膝关节以下", "E": "不用对比剂直接扫描"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "UNIT-10-MR-150", "kp": "下肢动脉CE-MRA方案", "ch": "十、MR检查技术 → 3.人体各部位MR检查技术 → (9)外周血管", "ex": "【为什么对】下肢血管行程长，须分段（髂股、股腘、膝下）连续采集以保证各段分辨率与对比剂时相同步，最终MIP拼接显示全程，故A正确。\n【为什么错】B：单次大范围扫描分辨率与信噪比不足。C：2D TOF扫描慢、对慢血流与钙化段显示差，非首选。D：仅膝下遗漏近段狭窄。E：非增强方案不适于精确评估全程闭塞。", "tr": "下肢CE-MRA“三段式+步进拼接”是标志性技术；覆盖全程与段内分辨率需平衡。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "MRI检查技术", "节": "人体各系统的MRI检查技术", "页": 280}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0101", "t": "单选题", "s": "关于DSA检查适应证与禁忌证的叙述，正确的是", "o": {"A": "有明确碘对比剂严重过敏史者，属于碘对比剂血管造影的禁忌", "B": "严重心、肝、肾功能衰竭患者可按常规方案完成DSA，无需特殊评估", "C": "甲状腺功能亢进未控制者使用含碘对比剂无任何风险", "D": "严重凝血功能障碍不影响穿刺插管，不属于禁忌范畴", "E": "妊娠早期是DSA的适应证之一"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-001", "kp": "DSA适应证与禁忌证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】A正确：明确的碘对比剂严重过敏（既往发生过喉头水肿、休克等重度反应）是碘剂血管造影公认的禁忌，必须权衡改用CO₂造影、MRA等替代方案或在充分预处理与抢救准备下评估。【为什么错】B错误：严重心、肝、肾功能衰竭属于禁忌或高危状态，需先纠正、限量并做水化等准备，不能按常规方案实施。C错误：未控制的甲状腺功能亢进者使用含碘对比剂可诱发甲状腺危象，属禁忌或高危。D错误：严重凝血功能障碍（如INR明显延长、血小板显著减少）会导致穿刺部位难以止血、血肿甚至腹膜后出血，属于禁忌。E错误：妊娠期尤其早期属于电离辐射相对禁忌，仅在危及生命且无替代手段时权衡实施。", "tr": "禁忌证要区分“绝对”与“相对”：现代介入实践中绝对禁忌很少，多数为可纠正的相对禁忌（凝血异常、肾功能不全、心衰）；而重度碘过敏与未控制的甲亢是与对比剂本身直接相关的经典禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0102", "t": "多选题", "s": "股动脉穿刺插管术后第2天，穿刺区出现搏动性包块，超声显示包块与股动脉之间有细颈相通并见“往返血流”。关于该并发症，下列正确的有", "o": {"A": "穿刺点过低、误穿股浅动脉或股深动脉是重要危险因素", "B": "压迫止血时间不足、过早下地活动及术后抗凝治疗可增加其发生率", "C": "局部听诊可闻及收缩期杂音，触诊常可扪及震颤", "D": "其瘤壁由完整的内膜、中膜、外膜三层构成，性质与真性动脉瘤相同", "E": "超声引导下压迫或瘤腔内注射凝血酶是常用的非手术处理方法"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-002", "kp": "医源性假性动脉瘤", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】A正确：穿刺点低于股动脉分叉时穿中股浅或股深动脉，管径细、位置深且缺乏股骨头作压迫衬托，止血困难，易形成假性动脉瘤。B正确：压迫时间不足、过早活动、抗凝抗血小板治疗均使穿刺口持续渗血形成搏动性血肿腔。C正确：血液经瘤颈往返进出，产生收缩期杂音与震颤，是典型体征。E正确：超声引导下瘤颈压迫和瘤腔内凝血酶注射是目前首选的非手术处理，失败者再考虑覆膜支架或外科修补。【为什么错】D错误：假性动脉瘤壁并非三层血管壁结构，而是由血肿机化后的纤维组织与周围软组织构成，与真性动脉瘤（瘤壁含血管壁三层结构）本质不同。", "tr": "“假性”与“真性”动脉瘤的核心区别在瘤壁构成而不是形态；另需与动静脉瘘鉴别——动静脉瘘为连续性“机器样”杂音、超声见动静脉间高速低阻分流，而假性动脉瘤为收缩期杂音、瘤颈“往返血流”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0103", "t": "单选题", "s": "患者行诊断性DSA后拔除6F股动脉鞘，需人工压迫止血。下列操作中错误的是", "o": {"A": "压迫点应位于皮肤穿刺点近心端约1~2cm处的动脉穿刺口上方", "B": "压迫力度以完全阻断同侧足背动脉搏动为准，并维持至解除压迫为止", "C": "持续压迫约15~20min后逐步减压，再以弹力绷带加压包扎、穿刺侧下肢制动", "D": "术后应定时观察穿刺点有无渗血、皮下瘀斑及进行性增大的包块", "E": "术后应观察足背动脉搏动、肢体皮温、颜色与感觉，警惕远端缺血"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-003", "kp": "穿刺部位止血与并发症观察", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】B错误故为本题答案：正确的压迫强度应在有效止血的同时保留远端血流，一般以能扪及足背动脉搏动（或稍减弱）为宜；若长时间完全阻断远端血流，可诱发动脉血栓形成与下肢缺血。【为什么错】A正确：由于穿刺针斜行进入，动脉壁上的穿刺口高于皮肤穿刺点，压迫点应上移1~2cm才能压住动脉破口。C正确：诊断性造影常规压迫15~20min，随后加压包扎并制动，是标准流程。D正确：进行性增大的包块提示活动性出血或假性动脉瘤形成。E正确：观察远端灌注是发现血栓栓塞并发症的关键。", "tr": "命题常在“压迫点位置”和“压迫力度”上设陷阱：压迫点要比皮肤穿刺点更靠近心端，而力度要“止血但不断流”，不是越紧越久越好。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0104", "t": "多选题", "s": "为降低介入手术中对比剂相关急性肾损伤的风险，下列围手术期措施合理的有", "o": {"A": "术前评估血肌酐与eGFR，识别高危患者并给予等渗生理盐水静脉水化", "B": "选用低渗或等渗非离子型对比剂，并将对比剂总量控制在与肾功能相匹配的范围内", "C": "术中充分利用路径图、低帧率透视与既往影像，减少不必要的重复造影", "D": "术前常规使用大剂量袢利尿剂强制利尿以“冲洗”肾脏", "E": "近期需再次行含碘对比剂检查时，应尽量延长两次检查间隔并复查肾功能"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-004", "kp": "介入术中对比剂肾损伤防控", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】A正确：肾功能评估与充分水化是预防对比剂相关急性肾损伤最有循证依据的措施。B正确：对比剂用量与肾损伤风险正相关，低渗/等渗非离子型对比剂肾毒性较低。C正确：路径图可在少量对比剂条件下引导插管，低帧率与参考既往影像可显著减少造影次数与总量，是技师可直接控制的环节。E正确：短期内反复给予碘对比剂会叠加肾脏负荷，应尽量拉开间隔并随访肾功能。【为什么错】D错误：强制利尿会造成血容量不足，反而加重肾髓质缺血，除非在容量监测下配合补液，否则单纯大剂量利尿剂是有害的。", "tr": "“多排尿=保护肾脏”是常见错误直觉。预防的核心是扩容水化与减量，而不是脱水利尿；甘露醇、呋塞米单用均不推荐。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0105", "t": "多选题", "s": "择期行诊断性DSA前，属于常规必须复核的实验室及辅助检查项目的有", "o": {"A": "凝血酶原时间（PT）及国际标准化比值（INR）", "B": "活化部分凝血活酶时间（APTT）与血小板计数", "C": "血肌酐及估算肾小球滤过率（eGFR）", "D": "静脉注射稀释碘对比剂的“碘过敏试验”，结果阴性方可手术", "E": "心电图及血源性传染病筛查"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-005", "kp": "DSA术前实验室检查", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】A、B正确：凝血功能与血小板直接决定穿刺部位止血能力，是术前必查项；一般要求INR降至1.5以下、血小板处于安全水平。C正确：肾功能决定对比剂用量与水化方案。E正确：心电图评估心脏基础状态与术中风险，传染病筛查用于器械与人员防护、消毒隔离安排。【为什么错】D错误：小剂量碘过敏试验对严重过敏样反应既无预测价值，本身还可能诱发反应，目前已不作为常规要求；替代做法是详细询问过敏史、哮喘史，对高危者行糖皮质激素与抗组胺药预处理并备好抢救设备与药品。", "tr": "“皮试阴性即安全”是最典型的过时观念。碘对比剂重度反应属非IgE介导的类过敏反应，试验剂量无法预测；重点在于危险因素筛查与抢救准备。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0106", "t": "单选题", "s": "患者因心房颤动长期口服华法林，拟行择期诊断性脑血管DSA。围手术期抗凝药物处理最合理的方案是", "o": {"A": "维持原剂量华法林不作任何调整，直接穿刺", "B": "术前3~5天停用华法林并复查INR，待INR降至1.5以下再穿刺，血栓栓塞高危者以低分子肝素桥接", "C": "术前当日给予大剂量维生素K快速拮抗后立即穿刺", "D": "术前改为阿司匹林联合氯吡格雷双联抗血小板治疗后立即手术", "E": "无需评估INR，仅需在术后延长压迫时间"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-006", "kp": "围手术期抗凝抗血小板处理", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】B正确：华法林半衰期长，需提前3~5天停药并以INR作为客观判断指标；对卒中或血栓高危者在停药窗口内用低分子肝素桥接，兼顾出血与栓塞两方面风险，是择期动脉穿刺的标准做法。【为什么错】A错误：INR明显升高时穿刺出血、血肿及腹膜后出血风险显著增加。C错误：大剂量维生素K快速拮抗仅用于严重出血等紧急情况，且会造成术后数日华法林抵抗，不适用于择期手术。D错误：双联抗血小板并不能替代华法林预防房颤所致心源性栓塞，且同样增加穿刺出血风险。E错误：延长压迫不能抵消凝血系统本身的异常，术前必须有INR等客观评估。", "tr": "抗凝与抗血小板要分开对待：单纯诊断性造影通常不必停用阿司匹林；而华法林等口服抗凝药需停药并以INR为准。切勿把“桥接”理解为换用抗血小板药。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0107", "t": "案例分析题", "s": "患者女性，68岁，高血压、2型糖尿病病史多年，因反复短暂性脑缺血发作拟行全脑血管造影。术中发现主动脉弓为Ⅲ型、弓上分支迂曲成角，反复更换导管与导丝超选左侧颈内动脉，累计操作时间约90min。术毕拔鞘时患者出现右侧肢体无力、言语含糊，随后症状持续存在。作为介入技术组成员，对该并发症的分析与预防措施，最恰当的是", "o": {"A": "该表现最可能为导管导丝机械操作致主动脉弓或颈动脉粥样斑块脱落、导管内血栓形成引起的脑栓塞，与Ⅲ型弓、血管迂曲、反复插管及操作时间延长密切相关，预防重在缩短操作时间、规范全身肝素化、导管尾端持续加压滴注冲洗与严格排气", "B": "该表现是碘对比剂对脑组织的直接毒性作用，与器械操作方式和操作时间无关", "C": "只要术中给予全身肝素化，即可完全避免此类栓塞并发症的发生", "D": "导管尾端持续加压滴注仅为保持管腔通畅、便于推注，与预防栓塞无关", "E": "术中一旦出现神经系统症状，应立即拔除所有导管、结束手术并等待症状自行恢复"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-007", "kp": "脑血管造影栓塞并发症", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】A正确：脑血管造影最主要的神经系统并发症为血栓栓塞事件，其危险因素包括高龄、动脉粥样硬化、Ⅲ型弓与血管迂曲、导管导丝反复摩擦斑块、操作时间与透视时间延长；预防措施为规范肝素化、导管持续加压滴注冲洗、严格排气与冲洗、缩短操作时间、必要时更换更适合的导管形态减少反复试插。【为什么错】B错误：碘对比剂虽有一过性神经毒性，但持续存在的偏侧运动语言障碍以栓塞更为符合，且操作因素证据明确。C错误：肝素化能降低但不能完全消除栓塞风险，斑块碎屑等机械性栓子并不受抗凝影响。D错误：持续加压滴注的首要目的正是防止导管腔内血栓形成，是预防栓塞的关键环节。E错误：出现症状时应立即评估并保留通路，便于即刻造影明确闭塞部位并考虑取栓等补救治疗，盲目撤除通路会延误救治。", "tr": "把“肝素化”当成万能保险是典型错误；机械性斑块碎屑栓塞靠抗凝无法预防，只能靠减少器械对血管壁的反复骚扰与缩短操作时间。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0108", "t": "单选题", "s": "关于经股动脉入路DSA的术前准备，下列做法不正确的是", "o": {"A": "双侧腹股沟区及会阴部备皮并做好皮肤清洁", "B": "术前禁食4~6h，必要时训练患者床上排尿与屏气配合", "C": "建立静脉通道，连接心电、无创血压及脉搏血氧饱和度监护", "D": "无需追问既往对比剂使用史与过敏史，只要碘过敏试验阴性即可安排手术", "E": "核对既往影像资料、实验室结果、知情同意书并做手术部位标记"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-008", "kp": "DSA术前常规准备", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】D错误故为本题答案：既往对比剂反应史、过敏体质、哮喘史是预测严重不良反应的最重要信息，任何情况下都必须详细询问并记录，不能以试验结果替代病史采集。【为什么错】A正确：双侧腹股沟备皮是为穿刺失败需改换对侧留有余地。B正确：禁食可降低反应或急救时的误吸风险，腹部血管造影需屏气配合，术后需卧床排尿，故应提前训练。C正确：术中生命体征连续监护是常规要求。E正确：核对资料与知情同意属于术前安全核查内容。", "tr": "本题与“碘过敏试验”考点呼应：试验阴性并不排除严重反应，而阳性也不能等同于过敏，因此病史询问与抢救准备才是核心。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0109", "t": "单选题", "s": "关于经典Seldinger技术与改良Seldinger技术的区别，正确的是", "o": {"A": "经典法穿刺针穿透血管前后壁后缓慢退针，见血液喷出再送入导丝；改良法只穿透血管前壁，见喷血即送入导丝", "B": "经典法只穿透血管前壁，改良法需贯穿血管前后壁", "C": "两者的区别在于是否使用血管鞘，与穿刺进针方式无关", "D": "改良法因贯穿血管后壁，穿刺部位血肿发生率高于经典法", "E": "经典法只能用于静脉穿刺，改良法只能用于动脉穿刺"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-009", "kp": "Seldinger技术与改良Seldinger技术", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (1)穿刺插管技术（Seldinger）", "ex": "【为什么对】A正确：Seldinger于1953年创立的经典法采用带针芯穿刺针贯穿血管前后壁，拔出针芯后缓慢退针至血液呈搏动性喷出，再送入导丝、退针、置入导管或血管鞘；改良法使用不带针芯的薄壁穿刺针仅穿透前壁，见回血喷出即送导丝，操作步骤更简、后壁无损伤。【为什么错】B错误：两者恰好说反。C错误：血管鞘是两种方法均可使用的器材，区别在于是否贯穿后壁。D错误：贯穿后壁的是经典法，改良法因不损伤后壁，血肿与出血并发症更少，故目前临床多用改良法。E错误：两种方法对动脉、静脉穿刺均适用，与血管种类无关。", "tr": "记忆口诀：经典“穿透双壁再退针”，改良“只穿前壁见喷血”。命题常把二者互换，或让考生误以为改良法并发症更多。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0110", "t": "案例分析题", "s": "患者男性，62岁，身高170cm、体重90kg（BMI约31），因下肢间歇性跛行拟经右股动脉入路行腹主动脉及双下肢动脉造影。患者腹部脂肪下垂明显，腹股沟皮肤皱褶位置低于骨性标志。技师配合医师定位穿刺点并摆放体位。关于该患者的股动脉穿刺定位与操作，下列正确的是", "o": {"A": "肥胖患者的腹股沟皮肤皱褶即为腹股沟韧带的可靠体表标志，可直接在皱褶处穿刺", "B": "穿刺点宜取腹股沟韧带下方约2cm、股动脉搏动最明显处，透视下大致相当于股骨头中下部水平，进针角度约30°~45°，必要时以透视或超声辅助定位", "C": "穿刺点越靠远端越安全，选择股动脉分叉以下的股浅动脉可减少出血风险", "D": "穿刺点定在腹股沟韧带以上更利于术后压迫止血", "E": "肥胖患者应将进针角度加大至80°~90°，以缩短皮肤至血管的穿刺距离"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-010", "kp": "股动脉穿刺点定位", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (1)穿刺插管技术（Seldinger）", "ex": "【为什么对】B正确：理想穿刺点位于股总动脉、腹股沟韧带下方约2cm处，此处动脉后方有股骨头作为衬托，压迫止血可靠；透视下以股骨头中下部为参考、超声引导可进一步提高一次穿刺成功率，进针角度30°~45°有利于导丝顺畅推进。【为什么错】A错误：肥胖患者皮肤皱褶常明显下移，按皱褶穿刺易穿到股动脉分叉以下，是假性动脉瘤的重要成因。C错误：股浅、股深动脉管径细、位置深，缺乏骨性衬托，穿刺后止血困难，并发症更多。D错误：韧带以上为髂外动脉，出血可流入腹膜后而无法压迫，是腹膜后血肿的主要原因。E错误：角度过大会造成导丝推送成角困难、鞘管打折，也不利于止血。", "tr": "“皮肤皱褶”只是粗略参考，肥胖患者必须改用骨性标志或影像引导；穿刺“过高”致腹膜后血肿、“过低”致假性动脉瘤与动静脉瘘，是两个方向的经典陷阱。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0111", "t": "多选题", "s": "关于经桡动脉、肱动脉入路血管造影的特点，下列正确的有", "o": {"A": "经桡动脉入路前应行Allen试验或血氧饱和度描记，评估掌弓侧支循环是否通畅", "B": "与股动脉入路相比，桡动脉入路止血方便、可早期下床活动，穿刺部位血管并发症较少", "C": "桡动脉管径较细、易发生痉挛，所选鞘管口径通常不超过6F", "D": "桡动脉入路不受主动脉弓类型与锁骨下动脉迂曲的影响", "E": "肱动脉为上肢主要供血动脉且伴行正中神经，血肿可致骨筋膜室综合征与神经损伤，一般不作首选入路"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-011", "kp": "血管穿刺入路选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (1)穿刺插管技术（Seldinger）", "ex": "【为什么对】A正确：桡动脉闭塞后手部血供依赖尺动脉与掌弓侧支，术前评估侧支循环可避免手部缺血。B正确：桡动脉位置表浅、下方有桡骨衬托，压迫止血可靠，患者术后可即刻活动，是其最大优势。C正确：桡动脉内径小，大口径鞘管易致痉挛、闭塞，故常规使用5~6F。E正确：肱动脉周围间隙狭小且有正中神经伴行，血肿压迫可造成严重后果，故一般排在股、桡动脉之后选择。【为什么错】D错误：经桡动脉行弓上血管或内脏血管造影，导管仍需经锁骨下动脉、头臂干进入主动脉弓，Ⅲ型弓、锁骨下动脉迂曲与右侧变异反而会增加超选难度，这正是桡动脉入路的重要局限。", "tr": "桡动脉入路“并发症少”指的是穿刺部位并发症；其代价是路径长、受弓型与上肢血管迂曲影响、器械口径受限，不能笼统认为“各方面都优于股动脉”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0112", "t": "单选题", "s": "关于DSA常用导管与导丝的选择，下列叙述错误的是", "o": {"A": "猪尾（pigtail）导管头端卷曲、侧孔多，耐受高流率，适用于主动脉、左心室等大腔室高流率造影", "B": "Cobra导管头端呈钩状弯曲，适于腹腔干、肠系膜动脉、肾动脉等内脏动脉的选择性插管", "C": "Simmons（西蒙斯）类导管适用于弓上分支开口成角、路径迂曲时的超选择插管", "D": "亲水涂层超滑导丝表面摩擦力小，有利于通过迂曲、狭窄的血管段", "E": "超滑导丝头端柔软，可长时间留置于靶血管内替代交换导丝，不必顾虑内膜损伤"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-012", "kp": "导管导丝选择原则", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (1)穿刺插管技术（Seldinger）", "ex": "【为什么对】E错误故为本题答案：超滑导丝虽头端柔软，但其亲水涂层在血液中易被血栓附着，长时间留置或反复进退可造成内膜损伤、夹层甚至涂层脱落栓塞；需要长时间支撑或器械交换时应换用交换导丝（长导丝、加硬导丝），并定期用肝素盐水擦拭导丝。【为什么错】A正确：猪尾导管多侧孔可分散注射冲击力，避免高流率下导管“甩鞭”与血管内膜损伤，是主动脉与左室造影的标准器械。B正确：Cobra是内脏动脉超选的经典导管。C正确：Simmons导管需在主动脉内成襻后回拉进入分支，适合成角迂曲开口。D正确：亲水涂层的作用即降低摩擦、便于通过病变段。", "tr": "端孔导管禁用于高流率注射（易致血管内膜损伤或导管移位），高流率造影必须选多侧孔的猪尾类导管——这是与本题相关的高频考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0113", "t": "多选题", "s": "关于动脉内DSA（IA-DSA）与静脉内DSA（IV-DSA）的比较，下列正确的有", "o": {"A": "IA-DSA将导管插至靶动脉或其近端注射，对比剂用量少、可适当稀释，血管显示清晰", "B": "IV-DSA经外周静脉注射，对比剂到达靶动脉时已被大量稀释，需高浓度大剂量，图像信噪比低", "C": "IV-DSA时全身血管几乎同时显影，相互重叠，难以分辨细小分支，目前临床已很少使用", "D": "IA-DSA由于是动脉内直接注药，因此不需要作时间减影处理", "E": "IA-DSA可在造影的同一通路上直接完成栓塞、成形等介入治疗"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-013", "kp": "IA-DSA与IV-DSA比较", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】A正确：动脉内注射使对比剂直接进入靶血管床，用量小、浓度可降低（如稀释至50%~70%），显影锐利。B正确：静脉注射经右心、肺循环、左心稀释后才到达动脉，血管内碘浓度低，必须提高浓度与总量，且噪声相对突出。C正确：IV-DSA无选择性，动静脉同时显影并重叠，是其被淘汰的根本原因。E正确：“诊疗一体化”是IA-DSA相对于无创血管成像与IV-DSA的核心优势。【为什么错】D错误：无论动脉内还是静脉内注射，DSA的图像形成都依赖蒙片与造影像相减，时间减影仍是基本成像方式。", "tr": "注意区分“注药途径”（IA/IV）与“减影方式”（时间减影/能量减影）两个不同维度的分类，命题常将两者混淆在同一选项中。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0114", "t": "多选题", "s": "下列DSA成像方式中，属于时间减影范畴的有", "o": {"A": "脉冲方式", "B": "超脉冲方式", "C": "路径图（roadmap）方式", "D": "K边缘减影（双能量减影）", "E": "岁差运动方式"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-014", "kp": "时间减影的各种方式", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】时间减影的共同特征是“同一部位、不同时刻”两幅（组）图像相减，包括常规脉冲方式、超脉冲方式、连续方式、时间间隔差方式、路径图方式、心电触发方式、岁差运动方式、步进（跟踪）方式与旋转DSA等。A、B属于按X线发生形式划分的时间减影；C路径图是以含对比剂的血管像作为背景蒙片的时间减影应用；E岁差运动方式为C臂作类似陀螺进动的锥形轨迹运动，在不同角度采集蒙片与造影像后减影，用于立体观察血管走行，仍属时间减影。【为什么错】D错误：K边缘减影利用碘在33.2keV处K吸收边缘两侧衰减系数的突变，用高低两种管电压曝光后相减，属能量减影（双能减影），其“变量”是能量而非时间。", "tr": "岁差运动、旋转DSA、步进DSA名字里带“运动”“旋转”，容易被误判为能量减影或独立类别；判别标准只有一个——相减的两幅图像是否来自不同时刻的同一能量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0115", "t": "单选题", "s": "关于能量减影与混合减影，下列叙述错误的是", "o": {"A": "能量减影利用碘在33.2keV的K吸收边缘两侧衰减系数发生突变的特性，以两种不同管电压先后曝光后加权相减", "B": "能量减影可分别获得软组织像与骨组织像，对轻微运动的敏感程度低于时间减影", "C": "混合减影是先行能量减影消除骨骼影，再作时间减影去除残余软组织背景", "D": "能量减影要求高压发生器在毫秒级内完成千伏切换，对设备要求高，患者受照剂量也相应增加", "E": "能量减影完全不受患者运动影响，可在任何部位取代时间减影"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-015", "kp": "能量减影与混合减影", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】E错误故为本题答案：能量减影的两次曝光之间仍有毫秒级时间间隔，快速运动（心脏搏动、吞咽、肠蠕动）依然会产生配准误差与运动伪影；同时能量减影不能完全消除软组织背景，血管与软组织对比不如时间减影，因此临床上只作为补充手段，不能取代时间减影。【为什么错】A正确：这是能量减影的物理基础。B正确：因两次曝光间隔极短，对轻微运动的容忍度确实优于常规时间减影，这是其主要优点。C正确：混合减影即“能量减影＋时间减影”联合，兼顾去骨与去软组织背景。D正确：高低kV快速切换对高压发生器要求高，且两次曝光使剂量增加，是其推广受限的重要原因。", "tr": "“对运动不敏感”≠“完全不受运动影响”。命题惯用把优点绝对化的方式设错项，遇到“完全”“任何部位”“可取代”一类表述要格外警惕。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0116", "t": "单选题", "s": "关于路径图（roadmap）技术的操作流程与作用，正确的是", "o": {"A": "先透视采集一帧蒙片，再注入少量对比剂使靶血管显影并将其作为新的“血管路径”背景，随后在此背景上实时减影透视引导导丝导管前行", "B": "每推送一次导丝都必须重新注射对比剂并重建路径图，无法在同一背景下连续操作", "C": "路径图属于能量减影技术的一种应用", "D": "路径图只能用于测量血管狭窄程度，不能用于插管引导", "E": "使用路径图会明显增加术中对比剂总用量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-016", "kp": "路径图技术", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】A正确：路径图分三步——第一步透视取蒙片；第二步注入少量对比剂，将血管充盈像与蒙片相减后“冻结”为血管路径背景；第三步在该背景上做实时透视减影，导丝导管以“黑影”形式显示在血管路径中，直观判断器械是否在管腔内。【为什么错】B错误：路径图一旦建立可在同一体位、同一角度下持续使用，只有改变C臂角度、床位或血管形态明显变化时才需重建。C错误：路径图以不同时刻图像相减为基础，属时间减影。D错误：路径图的核心用途正是超选择插管的实时引导。E错误：路径图只需少量对比剂即可建立背景，随后的操作过程无需再注药，反而显著减少对比剂总量与辐射剂量。", "tr": "路径图与“最后一帧保留（LIH）”容易混淆：LIH是保留最后一帧透视图像作静态参考，不做实时减影；路径图是把血管像作背景后仍进行实时减影透视。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0117", "t": "多选题", "s": "关于旋转DSA、三维旋转血管造影（3D-DSA）与C臂锥形束CT的临床应用，下列正确的有", "o": {"A": "旋转DSA在C臂旋转过程中先采集一组蒙片，再于对比剂充盈时按相同轨迹采集一组造影像，对应角度相减获得多角度减影图像", "B": "3D-DSA在旋转采集基础上重建三维血管模型，可任意角度观察并测量，有助于确定动脉瘤的最佳“工作角度”", "C": "C臂锥形束CT一次旋转采集数百幅投影，用锥形束算法重建出类似CT的断层图像，可显示软组织结构与术中出血", "D": "C臂锥形束CT的密度分辨率与时间分辨率均优于多层螺旋CT", "E": "3D-DSA与C臂锥形束CT在旋转采集期间要求患者保持静止，否则会出现明显的重建伪影"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-017", "kp": "旋转DSA、3D-DSA与C臂CT", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (2)成像方式", "ex": "【为什么对】A正确：旋转DSA需“两次旋转、逐角度配准相减”，因此对C臂旋转轨迹的可重复性要求极高。B正确：三维重建后可自动搜索瘤颈与载瘤动脉分离最佳的角度，并测量瘤体、瘤颈尺寸，指导支架与弹簧圈选择。C正确：锥形束CT（各厂家称DynaCT、XperCT、Innova CT等）弥补了DSA只显示管腔、不能显示实质的不足，可在术中评估出血、栓塞剂分布与支架位置。E正确：旋转采集时间长达数秒，运动会造成条状与模糊伪影，需嘱屏气或必要时镇静。【为什么错】D错误：受平板探测器动态范围、散射线与采集时间限制，C臂锥形束CT的密度（低对比）分辨率与时间分辨率均低于多层螺旋CT，其优势在于介入术中即时获取断层信息，而非取代CT。", "tr": "C臂CT的强项是“空间分辨率高＋术中即时”，弱项是“低对比分辨率差、采集慢、伪影多”。把它描述为全面优于MSCT是常见错误项。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0118", "t": "单选题", "s": "DSA采集帧率应依检查部位与血流速度选择，下列部位与帧率的组合中不合适的是", "o": {"A": "冠状动脉造影 15~30帧/s", "B": "脑血管造影动脉期 2~6帧/s", "C": "腹部内脏动脉造影 2~3帧/s", "D": "四肢动脉造影 1~3帧/s", "E": "下肢静脉造影 30帧/s以上"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-018", "kp": "DSA帧率选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (3)参数选择", "ex": "【为什么对】E不合适故为本题答案：下肢静脉血流缓慢、充盈过程历时长，采用1~2帧/s甚至更低即可满足诊断，30帧/s以上会造成巨大的图像数据量与不必要的辐射剂量。【为什么错】A合适：冠状动脉随心脏高速搏动，必须高帧率才能冻结运动并观察各心动周期时相。B合适：脑动脉期血流快，2~6帧/s可满足；进入毛细血管期与静脉窦期可进一步降低帧率。C合适：内脏动脉血流速度中等，2~3帧/s常规够用，观察门静脉期可延长采集。D合适：四肢血流慢，低帧率即可。", "tr": "帧率选择的基本原则是“血流越快、运动越剧烈则帧率越高”，同时兼顾剂量最优化；把高帧率理解为“图像质量更好”是典型误区，高帧率只提高时间分辨率并增加剂量。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0119", "t": "案例分析题", "s": "患者男性，56岁，肝硬化病史，行腹腔干动脉造影。回放减影序列时发现：肝区血管影周围出现成对的黑白相间“镶边”样影，膈肌与肠道气影呈条带状干扰，血管细小分支被掩盖，图像难以评价。追问采集过程，患者在注药后曾有一次轻微躯体移动，且肠道蠕动活跃。作为操作技师，下列处理最恰当的是", "o": {"A": "该伪影为运动性伪影，应先从原始序列中重新选取一帧对比剂到达前、与造影像位置一致的图像作蒙片（再蒙片），并配合像素移位重新配准；仍不满意时嘱患者屏气、必要时使用抑制肠蠕动药物后重新采集", "B": "该伪影由对比剂浓度不足引起，应提高对比剂浓度后立即重复造影", "C": "该伪影为平板探测器坏点所致，需联系工程师更换探测器", "D": "仅调整窗宽窗位即可完全消除该运动性伪影", "E": "该伪影属于饱和状伪影，应在体表加放补偿滤过板后重新采集"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-019", "kp": "蒙片选取与再蒙片", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (3)参数选择", "ex": "【为什么对】A正确：成对黑白“镶边”影是蒙片与造影像未能配准的典型运动性伪影。处理顺序应为：①再蒙片（remask）——重新选择一帧对比剂到达前、位置与造影像最吻合、曝光条件一致的图像作蒙片；②像素移位（pixel shift）——对整体平移性错位作水平、垂直方向微调；③若为肠蠕动等非平移性运动，后处理效果有限，需在屏气配合、必要时药物抑制蠕动的条件下重新采集。【为什么错】B错误：浓度不足表现为血管显影淡而均匀，不会形成成对黑白边缘影。C错误：探测器坏点表现为固定位置的点、线状缺陷，与患者运动无关，且不会随血管边缘分布。D错误：窗技术只改变灰阶显示，不能纠正配准误差。E错误：饱和状伪影出现在体厚急剧变化的边缘（如颈胸交界、气体区），表现为过度曝光的白亮区，处理方法才是加补偿滤过或补偿垫，与本例不符。", "tr": "运动性伪影的处理有明确顺序：再蒙片→像素移位→重新采集。要牢记像素移位只能纠正整体平移，对吞咽、肠蠕动、旋转等局部或非平移运动几乎无效。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0120", "t": "单选题", "s": "关于像素移位（pixel shift）技术，下列叙述错误的是", "o": {"A": "通过将蒙片相对于造影像作水平、垂直方向的微量平移重新配准，减轻运动性伪影", "B": "对整体平移性运动造成的错位矫正效果较好", "C": "对吞咽、肠蠕动等局部非平移性运动的矫正效果有限", "D": "属于图像后处理操作，不需要重新曝光，也不增加患者剂量", "E": "像素移位通过增加图像的有效信息量，可提高血管的空间分辨率"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-020", "kp": "像素移位技术", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → (3)参数选择", "ex": "【为什么对】E错误故为本题答案：像素移位只是在已有数据上作几何平移以改善配准，并未引入新的图像信息，空间分辨率由探测器像素尺寸、焦点大小与放大率决定，不会因移位而提高；相反过度移位会使配准区以外的部位错位加重。【为什么错】A正确：这是像素移位的基本定义。B正确：整体平移是像素移位最适用的情形。C正确：局部非平移运动需重新采集或再蒙片。D正确：属后处理操作，可反复尝试且不增加剂量，这是其相较重新造影的最大优势。", "tr": "命题喜欢把后处理技术的作用夸大为“提高分辨率”“增加信息量”。凡是不重新曝光的后处理都不会增加原始信息，只能改善显示或配准。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0121", "t": "多选题", "s": "关于全脑血管造影（通常所称“六根血管”造影）的技术要求，下列正确的有", "o": {"A": "通常包括双侧颈内动脉、双侧颈外动脉与双侧椎动脉的选择性造影", "B": "插管困难或弓上分支迂曲时，可先行主动脉弓造影了解各分支开口位置与解剖变异", "C": "颈内动脉造影常规摄取正位与侧位两个基本体位，必要时加摄斜位", "D": "椎动脉造影只需摄取正位，无需侧位", "E": "采集应涵盖动脉期、毛细血管期与静脉（窦）期全过程"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-021", "kp": "全脑血管造影技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】A正确：完整的全脑血管造影需评价前循环（双侧颈内动脉）、颈外循环（双侧颈外动脉，评估侧支与硬脑膜供血）与后循环（双侧椎动脉），即习称“六根血管”。B正确：主动脉弓造影常取左前斜位展开弓上分支，可判断弓型与开口，是超选困难时的重要步骤。C正确：正、侧位是脑血管造影的基本体位，斜位用于显示重叠部位或动脉瘤瘤颈。E正确：动静脉畸形、硬脑膜动静脉瘘的引流静脉、静脉窦通畅性均需完整时相观察，采集时间不足会漏诊。【为什么错】D错误：椎动脉造影同样需正、侧位；侧位对基底动脉、小脑后下动脉及大脑后动脉走行的显示不可替代。", "tr": "“六根血管”指的是需要选择性显影的六支血管，而不是穿刺六次；同时不要遗漏颈外动脉——脑膜瘤供血、鼻出血与硬脑膜动静脉瘘的评估都依赖它。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0122", "t": "案例分析题", "s": "患者女性，54岁，突发剧烈头痛伴呕吐、颈项强直，CT示广泛蛛网膜下腔出血。急诊行全脑血管造影，常规正、侧位见右侧颈内动脉后交通段一约6mm囊状突起，但瘤颈与载瘤动脉及后交通动脉相互重叠，无法判断瘤颈宽度及与分支的关系，介入医师需据此决定单纯弹簧圈栓塞或支架辅助栓塞。此时最合理的技术方案是", "o": {"A": "直接提高对比剂流率与总量后重复正、侧位造影", "B": "行3D旋转DSA采集并三维重建，在三维图像上寻找瘤颈与载瘤动脉、分支血管分离最清楚的“工作角度”，再据此设定C臂角度行二维造影与治疗", "C": "改行IV-DSA以避免动脉内操作的风险", "D": "采用能量减影去除颅骨后重复正位造影", "E": "将帧率提高至30帧/s后重复常规正、侧位造影"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-022", "kp": "颅内动脉瘤3D旋转造影与工作角度", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】B正确：常规二维造影的核心局限是投影重叠。3D旋转DSA通过一次旋转采集重建三维血管模型，可在任意视角观察瘤体形态、测量瘤颈宽度与瘤体/瘤颈比，并自动输出使瘤颈充分展开、与载瘤动脉分离的最佳“工作角度”，将该角度参数直接传输至C臂完成后续二维路径图与栓塞操作，是目前动脉瘤介入的标准流程。【为什么错】A错误：重叠是几何投影问题，增加对比剂无法解决，反而增加剂量与肾负荷。C错误：IV-DSA分辨率低、血管重叠更重，早已不用于颅内动脉瘤评估。D错误：能量减影只能去骨，不能解决血管间相互重叠。E错误：提高帧率只改善时间分辨率，对空间重叠无帮助，且明显增加辐射剂量。", "tr": "遇到“结构重叠、无法判断空间关系”的题干，答案方向一定是改变几何投影或三维成像，而不是调对比剂、帧率或减影方式。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0123", "t": "单选题", "s": "颈动脉DSA测得右侧颈内动脉起始部狭窄最窄处残余管腔直径1.5mm，狭窄远端管径恢复正常处直径5.0mm，颈动脉球部估计原始直径10.0mm。按NASCET法计算的狭窄率为", "o": {"A": "50%", "B": "70%", "C": "85%", "D": "15%", "E": "30%"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-023", "kp": "颈动脉狭窄NASCET测量", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】B正确：NASCET法以狭窄远端管径恢复正常处的颈内动脉直径为参照，狭窄率＝(1－最窄处残余管腔直径÷狭窄远端正常颈内动脉直径)×100%＝(1－1.5÷5.0)×100%＝70%。【为什么错】A错误：50%对应残余管腔2.5mm。C错误：85%是以颈动脉球部原始直径10.0mm为分母的ECST法结果，(1－1.5÷10.0)×100%＝85%，属于换错了参照标准。D错误：15%为1.5÷10.0，直接把残余管腔与球部直径相比却未取补数。E错误：30%为残余管腔占远端正常管径的比例（1.5÷5.0），是漏减了“1－”这一步。", "tr": "同一病灶按ECST法算出的狭窄率明显高于NASCET法（本例85%对70%）。报告中必须注明所用标准，否则会直接影响是否达到手术或支架治疗阈值的判断。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0124", "t": "单选题", "s": "主动脉弓造影用于显示弓上三大分支开口，常规采用的导管位置与投照体位是", "o": {"A": "猪尾导管置于升主动脉，取左前斜位约30°~45°", "B": "猪尾导管置于降主动脉，取标准正位", "C": "端孔导管置于左心室，取右前斜位30°", "D": "Cobra导管置于头臂干，取标准侧位", "E": "猪尾导管置于主动脉弓顶部，取右前斜位60°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-024", "kp": "主动脉弓造影体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】A正确：猪尾导管置于升主动脉、头臂干开口近端，用高压注射器注射；左前斜位30°~45°可将主动脉弓展开成“弓”形，使头臂干、左颈总动脉、左锁骨下动脉的开口分离而不重叠，是评价弓型与开口病变的标准体位。【为什么错】B错误：导管位于降主动脉时对比剂无法充分逆流充盈弓上分支；正位时弓部前后重叠。C错误：左心室与右前斜位是左室造影的设置，不适用于弓上分支评价。D错误：Cobra导管为内脏动脉超选导管，且置于头臂干内只能显示单一分支；侧位无法展开三大分支。E错误：右前斜位使弓部呈重叠状，分支开口相互掩盖。", "tr": "记忆要点：“主动脉弓看分支用左前斜、左室造影用右前斜”。另外弓造影必须用多侧孔猪尾导管配合高流率注射，端孔导管禁用于高流率。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0125", "t": "案例分析题", "s": "患者男性，58岁，支气管扩张病史10余年，近1天反复咯血约500ml，内科止血治疗效果不佳，拟行支气管动脉造影及栓塞术。术中造影见右侧支气管动脉增粗迂曲、末梢紊乱并见对比剂外溢。关于本例的技术要点，下列错误的是", "o": {"A": "支气管动脉多起自T5~T6水平胸主动脉前侧壁，右侧常与肋间动脉共干形成肋间-支气管动脉干", "B": "造影中若见与靶血管相连的根髓动脉（呈“发夹”样）显影，应将微导管超选至更远端避开该分支后再行栓塞，以免造成脊髓缺血", "C": "栓塞材料多选用直径300~500μm以上的聚乙烯醇（PVA）颗粒或明胶海绵颗粒", "D": "为提高栓塞彻底性，应首选无水乙醇等液体栓塞剂或直径小于100μm的微粒行末梢栓塞", "E": "栓塞后应重复造影确认病理血管消失，并观察有无对比剂反流所致的异位栓塞"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-025", "kp": "支气管动脉造影与咯血栓塞", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】D错误故为本题答案：过小的微粒（一般认为小于300μm）与液体栓塞剂可穿过支气管动脉与肺动脉、脊髓动脉之间的细小吻合，造成支气管壁坏死、支气管食管瘘与脊髓缺血性截瘫等严重并发症，因此支气管动脉栓塞禁用无水乙醇等液体栓塞剂与过小微粒。【为什么错】A正确：这是支气管动脉的经典解剖起源与共干形式。B正确：根髓动脉（Adamkiewicz动脉）误栓是支气管动脉栓塞最严重的并发症，超选微导管避开是关键防范措施。C正确：300~500μm级别的PVA或明胶海绵颗粒可有效栓塞病理血管床，同时不会穿过危险吻合。E正确：术后即刻造影复查是评估疗效与安全性的必要步骤。", "tr": "“栓塞越彻底越好”是常见错误思路。支气管动脉栓塞的核心矛盾是疗效与脊髓、支气管壁安全之间的平衡，颗粒过小与液体栓塞剂是明确的雷区。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0126", "t": "单选题", "s": "关于胸部DSA检查技术，下列叙述错误的是", "o": {"A": "咯血患者除支气管动脉外，还应注意肋间动脉、胸廓内动脉、膈下动脉、锁骨下动脉分支等非支气管性体循环侧支供血", "B": "支气管动脉造影宜采用手推或低流率注射，对比剂用量小，避免高压注射造成血管与脊髓损伤", "C": "胸主动脉造影常用猪尾导管，取左前斜位以展开主动脉全程", "D": "肺动脉造影需将导管经右心系统送入肺动脉，操作中应警惕心律失常等并发症", "E": "支气管动脉血管细小，应将帧率设置在30帧/s以上以免遗漏细节"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-026", "kp": "胸部DSA检查技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】E错误故为本题答案：支气管动脉血流量小、显影过程相对缓慢，常规2~3帧/s即可完整记录，30帧/s以上属于冠状动脉级别的帧率要求，对本检查无诊断价值，只会增加辐射剂量与数据量。【为什么错】A正确：约相当一部分咯血病例存在非支气管性体循环侧支供血，遗漏是栓塞后复发的重要原因。B正确：支气管动脉细小，高流率注射可致血管夹层、破裂或对比剂经危险吻合进入脊髓动脉。C正确：左前斜位可展开胸主动脉的弓部与降部，避免与脊柱重叠。D正确：导管经右房、右室时机械刺激易诱发室性早搏与室性心动过速，需心电监护并备除颤设备。", "tr": "细小血管≠需要高帧率。帧率取决于血流速度与运动幅度，与血管粗细无必然关系；细小血管更需要的是合适的放大倍数、小焦点与低流率注射。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0127", "t": "多选题", "s": "关于左冠状动脉造影常用投照体位组合及其显示重点，下列正确的有", "o": {"A": "左前斜45°＋足位25°（俗称“蜘蛛位”）主要显示左主干远端及前降支、回旋支开口与分叉", "B": "右前斜30°＋足位25°主要显示回旋支主干与钝缘支，同时可观察前降支近段", "C": "右前斜30°＋头位25°主要展开前降支中远段与对角支", "D": "左前斜45°＋头位25°的作用是显示左主干开口，此体位下前降支与间隔支完全重叠而无法分辨", "E": "左冠造影常规选用Judkins左冠导管（如JL3.5~4.0），经桡动脉时也可选用左右共用型导管"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-027", "kp": "左冠状动脉造影投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】A正确：左前斜加足位使左主干分叉呈“蜘蛛”状展开，是评价左主干末端与双支开口病变的关键体位。B正确：右前斜加足位是显示回旋支及钝缘支的经典体位。C正确：右前斜加头位使前降支沿长轴展开，便于观察中远段与对角支分支。E正确：Judkins左冠导管为股动脉入路的标准选择，桡动脉入路可用共用型导管减少更换。【为什么错】D错误：左前斜＋头位的作用恰恰是把前降支的间隔支（指向下方）与对角支（指向上方）分开，用于观察前降支中远段；显示左主干开口更常用正位或轻度右前斜＋头位，而非“完全重叠无法分辨”。", "tr": "记忆规律：头位（CRA）展开前降支中远段与远端分叉，足位（CAU）展开左主干末端、回旋支与近段；把头/足位的作用互换是本考点最常见的失分点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0128", "t": "单选题", "s": "右冠状动脉造影中，能使右冠状动脉整体呈“C”形展开、主要用于观察其中段与锐缘支的体位是", "o": {"A": "左前斜45°", "B": "右前斜30°", "C": "正位＋足位25°", "D": "标准侧位", "E": "右前斜30°＋足位25°"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-028", "kp": "右冠状动脉造影投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】A正确：左前斜45°是右冠造影的首选体位，右冠自开口沿房室沟走行呈典型“C”形展开，可完整观察开口、近段、中段与锐缘支，也便于判断导管是否与开口同轴。【为什么错】B错误：右前斜30°时右冠呈“L”形，主要用于观察中段与后降支走行，并非“C”形。C错误：正位加足位不是右冠常规体位。D错误：侧位主要用于观察右冠开口与近段起始角度，属补充体位。E错误：右前斜加足位为左冠回旋支的常用体位。另需记住左前斜45°＋头位25°呈“倒U”形，用于展开后降支与左室后支的分叉部。", "tr": "把右冠形态与体位对应起来记忆最有效：左前斜“C”形、右前斜“L”形、左前斜＋头位“倒U”形显示远段分叉。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0129", "t": "案例分析题", "s": "患者男性，60岁，因陈旧性心肌梗死后心功能不全，在完成冠状动脉造影后需评价左心室整体与节段收缩功能，并判断有无二尖瓣反流。介入医师要求技师配合完成左心室造影。关于本次造影的器械、参数与体位设置，下列正确的是", "o": {"A": "选用端孔导管置于左室流出道，手推对比剂约20ml即可", "B": "选用猪尾导管头端置于左心室中部，用高压注射器注射对比剂约30~40ml、流率约10~15ml/s，帧率25~30帧/s，常规取右前斜30°，必要时加摄左前斜60°", "C": "取左前斜45°＋足位25°作为唯一体位即可满足室壁运动与二尖瓣反流评价", "D": "为降低辐射剂量，帧率应设置为3帧/s", "E": "注射前无需排气与试注射，可直接启动高压注射器"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-029", "kp": "左心室造影技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】B正确：猪尾导管多侧孔可分散高流率注射的冲击力、避免心内膜损伤与室性心律失常；右前斜30°用于观察前壁、心尖、下壁运动及二尖瓣反流入左房的情况，左前斜60°补充观察室间隔与侧壁；心脏搏动快，帧率需25~30帧/s。【为什么错】A错误：端孔导管在高流率下会因反冲刺入心肌造成损伤与心律失常，且手推20ml无法使左室充分显影。C错误：左前斜加足位为左冠造影体位，不用于左室造影。D错误：3帧/s无法冻结心动周期，无法评价室壁运动。E错误：高压注射器必须排空气泡并确认导管位置、压力上限，否则可致气栓与心肌染色。", "tr": "“猪尾导管＋右前斜30°”是左室造影的标准搭配。注意与冠状动脉造影的Judkins导管、与主动脉弓造影的左前斜位区分开。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0130", "t": "单选题", "s": "关于冠状动脉造影的器械选择与并发症，下列叙述错误的是", "o": {"A": "经股动脉入路常用Judkins左（JL4.0）与Judkins右（JR4.0）导管分别插入左、右冠状动脉", "B": "经桡动脉入路可选用左右冠共用型导管以减少导管更换次数与操作时间", "C": "导管深插或与冠状动脉开口不同轴，可造成冠状动脉痉挛、压力嵌顿甚至开口夹层", "D": "导管内血栓形成或注射时混入气泡，可造成冠状动脉栓塞，故须严格排气并持续冲洗", "E": "造影过程中出现一过性心室颤动，只可能由导管机械压迫所致，与对比剂性质及注射量完全无关"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-030", "kp": "冠状动脉造影器械与并发症", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】E错误故为本题答案：造影中室颤的原因是多方面的，除导管嵌顿、深插导致心肌缺血外，对比剂在冠状动脉内滞留时间过长、注射量过大、导管压力嵌顿状态下注药、高渗离子型对比剂对心肌电生理的影响等均可诱发；因此除规范操作外，还应选用非离子型对比剂、控制单次注射量并避免嵌顿位注射。【为什么错】A正确：JL4.0与JR4.0是最常用的成人冠脉造影导管。B正确：共用型导管是桡动脉入路的常规优化。C正确：这是导管操作相关的经典并发症链条。D正确：气泡与血栓是冠脉栓塞的两大来源，排气与持续冲洗是基本规范。", "tr": "选项中“只可能……完全无关”的双重绝对化表述几乎必错。并发症类考点通常是多因素叠加，单一归因的选项应优先排除。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0131", "t": "多选题", "s": "关于原发性肝癌经导管动脉化疗栓塞术（TACE）的造影与操作技术要点，下列正确的有", "o": {"A": "术中宜先行腹腔干与肠系膜上动脉造影，了解肝动脉解剖、有无变异并观察门静脉期血流", "B": "部分患者存在肝右动脉起自肠系膜上动脉、肝左动脉起自胃左动脉等变异，须逐一探查以免遗漏肿瘤供血", "C": "应尽量将导管或微导管超选至肿瘤供血动脉后再注入碘化油-化疗药乳剂，以减少正常肝组织损伤", "D": "门静脉主干完全被癌栓阻塞且侧支循环尚未建立者，行肝固有动脉主干大剂量栓塞是安全的", "E": "操作中须注意胃十二指肠动脉、胆囊动脉、右膈下动脉等的反流，防止异位栓塞"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-031", "kp": "肝动脉化疗栓塞TACE技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】A正确：肠系膜上动脉造影延迟至门静脉期可间接判断门静脉通畅程度与有无癌栓，是决定栓塞范围与安全性的前提。B正确：肝动脉解剖变异常见，替代肝右动脉多起自肠系膜上动脉、替代肝左动脉多起自胃左动脉，漏栓变异供血是术后复发的重要原因。C正确：超选择栓塞可提高肿瘤内碘油沉积、减轻肝功能损害，是提高疗效与安全性的关键。E正确：反流至胃十二指肠动脉可致胃十二指肠溃疡，反流至胆囊动脉可致缺血性胆囊炎。【为什么错】D错误：门静脉主干完全阻塞且无侧支代偿时，肝脏几乎完全依赖肝动脉供血，此时行主干大剂量栓塞会导致广泛肝细胞坏死与肝功能衰竭，属禁忌或需高度超选的极慎重情形。", "tr": "肝脏为肝动脉与门静脉双重供血，TACE的安全边界正建立在门静脉通畅的前提上；“门静脉主干癌栓”是必须警觉的关键词。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0132", "t": "单选题", "s": "关于脾动脉造影技术，下列叙述错误的是", "o": {"A": "脾动脉起自腹腔干，行程迂曲，常选用Cobra、RH或Simmons类导管进行选择性插管", "B": "通过迂曲段时宜用亲水涂层超滑导丝引导，避免暴力推送导致血管痉挛或夹层", "C": "脾动脉造影可显示脾实质染色，用于外伤性脾破裂出血的诊断与栓塞治疗", "D": "造影时应辨认胰背动脉、胃网膜左动脉、胃短动脉等分支，栓塞时注意避免误栓", "E": "脾动脉造影须使用高压注射器以20ml/s以上的流率注射，方能使脾实质充分显影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-032", "kp": "脾动脉造影技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】E错误故为本题答案：脾动脉属中等口径内脏动脉，选择性造影一般采用4~6ml/s、总量15~25ml左右的流率与剂量即可获得满意的实质期染色；20ml/s以上属于主动脉级别的流率，会造成导管弹出、血管内膜损伤甚至脾包膜下血肿。【为什么错】A正确：脾动脉呈蛇行迂曲，需借助带弯度的导管超选。B正确：超滑导丝可降低通过迂曲段时的血管损伤。C正确：外伤性脾出血的介入栓塞是保脾治疗的重要手段，造影可显示对比剂外溢或假性动脉瘤。D正确：这些分支在栓塞时误栓可导致胃壁缺血、胰腺炎等并发症。", "tr": "内脏动脉造影的流率、总量必须与血管口径匹配，牢记“大血管高流率、分支血管低流率”，切忌套用主动脉参数。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0133", "t": "多选题", "s": "关于消化道出血的DSA检查，下列正确的有", "o": {"A": "活动性出血的直接征象是对比剂自血管溢出并滞留、聚集于肠腔内", "B": "一般认为出血速度达到0.5ml/min以上时，DSA才可能显示对比剂外溢", "C": "检查宜在活动性出血期进行，出血间歇期检查阳性率明显下降", "D": "首次探查的责任血管造影阴性时可直接结束检查，无需再探查其他供血动脉", "E": "血管畸形、假性动脉瘤、异常肿瘤染色等间接征象同样具有定位价值"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-033", "kp": "消化道出血血管造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】A正确：对比剂外溢后不随血流廓清而滞留于肠腔，是判断活动性出血的金标准征象。B正确：0.5ml/min是DSA显示对比剂外溢的公认阈值，低于此速度多为阴性。C正确：出血呈间歇性，把握出血活跃时机是提高阳性率的关键，必要时可结合核素或CTA先行定位。E正确：即使未见外溢，血管畸形、动静脉畸形、假性动脉瘤及肿瘤染色亦可提示出血部位并指导栓塞。【为什么错】D错误：消化道出血需按解剖分区系统探查，通常依次行肠系膜上动脉、腹腔干、肠系膜下动脉造影，必要时加做超选择造影或延长采集至静脉期，单支阴性即终止会造成漏诊。", "tr": "考点常设的陷阱是把“阴性”等同于“无出血”。DSA阴性只能说明检查时出血速度低于阈值或不在所探查血管供血区，不能排除出血。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-0134", "t": "单选题", "s": "关于子宫肌瘤子宫动脉栓塞术（UAE）的技术要点，下列叙述错误的是", "o": {"A": "子宫动脉多起自髂内动脉前干，常经一侧股动脉入路，用Cobra或子宫动脉专用导管跨越髂动脉分叉超选对侧", "B": "髂内动脉造影多取同侧前斜位，以展开前、后干分支避免相互重叠", "C": "常用聚乙烯醇（PVA）颗粒或明胶海绵颗粒作为栓塞材料", "D": "栓塞后综合征表现为下腹痛、低热、恶心呕吐等，多为自限性", "E": "卵巢动脉与子宫动脉之间不存在任何交通支，故UAE不会影响卵巢功能"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-034", "kp": "子宫动脉栓塞技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (5)盆腔", "ex": "【为什么对】E错误故为本题答案：子宫动脉与卵巢动脉之间存在输卵管支等交通支，栓塞颗粒可经此进入卵巢血管床，导致卵巢功能受损甚至闭经，这是育龄期患者术前必须充分告知的风险；术中应超选至子宫动脉上行支、控制栓塞终点、避免过度栓塞与反流。【为什么错】A正确：这是UAE的标准入路与器械选择。B正确：同侧前斜位可展开髂内动脉前后干，便于辨认子宫动脉开口。C正确：PVA与明胶海绵颗粒是常用栓塞剂。D正确：栓塞后综合征是缺血坏死引起的常见反应，对症处理即可缓解。", "tr": "凡出现“不存在任何交通支”“完全不影响”这类否定一切侧支的表述，几乎都是错误项——人体血管网普遍存在潜在吻合，介入栓塞的风险正源于此。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-0135", "t": "单选题", "s": "拟行双下肢动脉步进（bolus chasing）DSA，下列做法错误的是", "o": {"A": "导管头端置于腹主动脉分叉上方，一次注射对比剂后由床面或C臂自动步进跟踪对比剂前行分段采集", "B": "相邻采集段之间应保留一定重叠范围，便于后续图像拼接", "C": "小腿及足部血流到达延迟，可适当延长采集时间或对远段单独补充造影", "D": "检查前应固定双足、嘱患者制动，防止运动造成减影配准不良", "E": "为缩短检查时间，步进速度应预先设定为固定值，采集过程中不必参考对比剂实际到达情况"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-035", "kp": "下肢动脉步进DSA", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】E错误故为本题答案：下肢动脉硬化闭塞患者两侧血流速度常明显不对称，闭塞侧经侧支循环供血，对比剂到达远端显著延迟；若步进速度固定而不跟随对比剂前锋调整，会出现“跑在对比剂前面”导致远段血管未显影而漏诊，现代设备均支持术者实时手动控制步进速度或采用智能跟踪。【为什么错】A正确：这是步进DSA的标准设置，一次注药完成腹主动脉分叉至足部的全程显示。B正确：重叠区是分段图像拼接与判断连续性的基础。C正确：远端延迟显影时应延长采集或对膝下、足部单独补充造影。D正确：步进采集时间长，运动是配准失败的主要原因，充分固定与制动很重要。", "tr": "步进DSA的核心难点是“追上但不超过”对比剂前锋，尤其在双侧血流不对称时；这类题的错误项常以“固定参数、缩短时间”为诱饵。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1001", "t": "单选题", "s": "DSA的中文名称是", "o": {"A": "数字减影血管造影", "B": "数字X线摄影", "C": "计算机体层成像", "D": "磁共振血管成像", "E": "数字断层融合成像"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-001", "kp": "DSA基本概念", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】DSA即Digital Subtraction Angiography，中文全称为数字减影血管造影，A正确。\n【为什么错】B为DR（数字X线摄影）；C为CT；D为MRA；E为数字体层融合成像，均与DSA含义不符。", "tr": "DSA＝数字减影血管造影，注意与CTA、MRA等无创血管成像技术相区别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1002", "t": "单选题", "s": "DSA减影中，mask像（蒙片）是指", "o": {"A": "注入对比剂前采集的原始图像", "B": "注入对比剂后血管充盈期的图像", "C": "减影后只含血管的图像", "D": "处理后放大的数字矩阵图像", "E": "经窗宽窗位调整后的图像"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-002", "kp": "mask像原理", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】mask像即蒙片，是注入对比剂前采集的原始图像，作为减影的基准模板，与含对比剂图像相减消除背景，A正确。\n【为什么错】B为含对比剂图像，与mask像相减得减影像；C为减影结果像；D为数字图像转换产物；E为显示处理手段，均非mask像定义。", "tr": "mask像在注药前采集；减影相＝mask像－含对比剂像，先后方向勿搞反。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1003", "t": "单选题", "s": "DSA减影处理中对图像先行对数变换的主要目的是", "o": {"A": "提高图像空间分辨率", "B": "使像素灰度与人体衰减系数成线性关系，便于像素相减", "C": "扩大图像灰阶范围", "D": "增强血管边缘轮廓", "E": "直接减少图像噪声"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-003", "kp": "DSA减影数学原理", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】X线穿过人体按指数规律衰减，先经对数变换使像素灰度与组织衰减系数呈线性关系，相减后骨骼、软组织成分被消除，仅保留含碘血管信号，B正确。\n【为什么错】A为空间分辨率概念；C为窗宽窗位显示处理；D为图像锐化滤波；E为噪声抑制处理，均非对数变换的直接目的。", "tr": "减影前必先对数变换，否则指数衰减下相减不能真正消除重叠组织。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1004", "t": "单选题", "s": "时间减影中应用“再蒙片”（remasking）的主要目的是", "o": {"A": "提高对比剂浓度", "B": "重新选择最佳mask像以减少运动伪影", "C": "提高采集帧率", "D": "降低患者辐射剂量", "E": "缩短造影时间"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-004", "kp": "时间减影与再蒙片", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】患者运动（吞咽、屏气不佳、蠕动等）可使蒙片与含对比剂图像错位，在减影序列中重新选择一帧更接近的帧作为新mask像（再蒙片），可有效纠正配准误差，B正确。\n【为什么错】A为注射参数；C为采集参数；D为剂量管理；E为操作流程，均与再蒙片的作用无关。", "tr": "再蒙片是图像后处理手段，并非重新注药或改变采集参数。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1005", "t": "单选题", "s": "减影后DSA图像中最终显示为高密度的结构是", "o": {"A": "骨骼", "B": "软组织", "C": "含对比剂的血管腔", "D": "肺内空气", "E": "肌肉组织"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-005", "kp": "减影图像显示内容", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】减影后骨骼、软组织被相减消除，仅保留注入对比剂后血管腔的影像，故高密度者为含碘对比剂的血管腔，C正确。\n【为什么错】A、B、E在减影时被消除；D空气影同样在相减后消失。", "tr": "DSA只显示含碘对比剂的血管腔，不显示血管壁及周围组织。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1006", "t": "单选题", "s": "静脉DSA（IV-DSA）中心静脉法导管头端应置于", "o": {"A": "肘前静脉", "B": "腋静脉", "C": "上腔静脉或右心房", "D": "下腔静脉远心端", "E": "髂外静脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-006", "kp": "静脉DSA中心静脉法", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】中心静脉法经肘静脉或股静脉穿刺插管，将导管头端置于上腔静脉或右心房近心端，注射后对比剂在短时间内形成较集中的团注，C正确。\n【为什么错】A为外周静脉法的注射部位；B为静脉走行途经；D、E位置过远，团注效果差、对比剂稀释明显。", "tr": "中心法导管头端在上腔静脉/右心房，外周法则直接在肘前静脉注射，二者有别。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1007", "t": "单选题", "s": "与动脉DSA相比，静脉DSA的主要缺点是", "o": {"A": "操作复杂、创伤大", "B": "对比剂被血液稀释、细小动脉显示差", "C": "不能显示全身大血管", "D": "辐射剂量显著增高", "E": "完全不能用于介入治疗引导"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-007", "kp": "静脉DSA特点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】静脉注射后对比剂经肺循环被血液大量稀释，浓度显著降低，细小动脉及病变显示不清，B正确。\n【为什么错】A静脉法不需动脉插管，操作更简便、创伤更小；C静脉法可显示主动脉等大血管；D剂量与方式无必然增高关系；E介入治疗中静脉法亦可作引导，只是多选动脉法。", "tr": "IV-DSA优势是简便创伤小，代价是稀释重、细小血管显示差。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1008", "t": "单选题", "s": "肾功能不全患者行血管造影时，应优先选择的成像方式是", "o": {"A": "静脉DSA", "B": "动脉DSA", "C": "混合DSA", "D": "能量减影DSA", "E": "步进式DSA"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-008", "kp": "动脉DSA用量特点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】动脉DSA对比剂用量少、浓度低，可最大限度减轻肾脏负担，适合肾功能不全患者，B正确。\n【为什么错】A静脉DSA用量大、肾负担重；C混合DSA总用量更大；D、E为减影或采集方式，不解决对比剂用量问题。", "tr": "动脉DSA省药、静脉DSA费药，方向与直觉相反，需重点记忆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1009", "t": "单选题", "s": "DSA成像方式中的“混合DSA”是指", "o": {"A": "时间减影与能量减影相结合的减影方式", "B": "静脉DSA与动脉DSA相结合的造影方式", "C": "X线与MR相结合的成像方式", "D": "常规透视与减影相结合的成像方式", "E": "正位与侧位相结合的采集方式"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-009", "kp": "混合DSA成像方式", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】在DSA成像方式分类中，混合DSA指静脉法与动脉法相结合的造影方式，根据病变需要先后或同时应用IV-DSA与IA-DSA，B正确。\n【为什么错】A为混合减影（属减影方式分类）；C为多模态成像；D为透视技术；E为体位组合，均非成像方式分类中的混合DSA。", "tr": "“混合DSA”是成像方式（动静脉结合），“混合减影”是减影方式（时间＋能量），二者最易混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1010", "t": "单选题", "s": "临床DSA检查中应用最广泛的减影方式是", "o": {"A": "能量减影", "B": "时间减影", "C": "混合减影", "D": "光学减影", "E": "磁化转移减影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-010", "kp": "时间减影", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】时间减影设备要求低、操作简便、效果可靠，是临床应用最广泛的减影方式，B正确。\n【为什么错】A能量减影需特殊设备、易受运动影响；C混合减影信噪比低；D光学减影为早期技术已被淘汰；E不存在此减影方式。", "tr": "时间减影最常用；能量减影、混合减影因固有缺陷临床少用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1011", "t": "单选题", "s": "能量减影利用碘的K吸收边进行成像，碘的K吸收边能量约为", "o": {"A": "13.3keV", "B": "23.3keV", "C": "33.2keV", "D": "53.2keV", "E": "73.2keV"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-011", "kp": "能量减影原理", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】碘的K吸收边为33.2keV，选用略低于和略高于该能量的两种X线成像后相减，可消除软组织影，C正确。\n【为什么错】A、B、D、E数值均不符合碘K吸收边的物理事实。", "tr": "33.2keV为碘K吸收边经典数值，属高频记忆考点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1012", "t": "单选题", "s": "关于能量减影的叙述，错误的是", "o": {"A": "利用碘的K吸收边原理", "B": "需要两种不同能量的X线成像", "C": "能同时消除骨骼影和软组织影", "D": "对软组织的运动较为敏感", "E": "对设备性能要求较高"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-012", "kp": "能量减影局限", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】能量减影仅能消除软组织影，骨骼影仍然保留，故C“能同时消除骨骼和软组织”说法错误，本题选C。\n【为什么错】A为能量减影物理基础；B为成像条件；D、E为其固有局限，均正确。", "tr": "能量减影去软组织留骨骼；同时消除骨骼软组织是时间减影的特点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1013", "t": "单选题", "s": "混合减影（hybrid subtraction）的减影顺序是", "o": {"A": "先时间减影再能量减影", "B": "先能量减影再时间减影", "C": "两种不同帧率图像相减", "D": "静脉图像与动脉图像相减", "E": "正位图像与侧位图像相减"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-013", "kp": "混合减影", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】混合减影先将两种能量图像作能量减影（消除软组织），再对能量减影像作时间减影（消除骨骼及运动伪影），B正确。\n【为什么错】A顺序颠倒；C为帧率选择；D为成像方式；E为体位组合，均非混合减影定义。", "tr": "混合减影＝能量减影在前、时间减影在后，顺序勿颠倒。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1014", "t": "单选题", "s": "DSA的“路标”（road mapping）技术主要用于", "o": {"A": "诊断细小动脉瘤", "B": "介入操作中实时引导导丝、导管超选择性插管", "C": "评价血管狭窄程度", "D": "提高图像空间分辨率", "E": "减少对比剂用量"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-014", "kp": "路标技术", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】路标技术将注药后含对比剂的血管影像作为路径图叠加于实时透视上，导管导丝移动时与血管的关系清晰可见，便于超选择性插管，B正确。\n【为什么错】A、C为诊断用途；D为图像质量指标；E为剂量问题，均非路标技术的直接作用。", "tr": "路标技术＝介入引导专用，属时间减影的实时应用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1015", "t": "单选题", "s": "DSA检查的绝对禁忌证是", "o": {"A": "轻度高血压", "B": "糖尿病", "C": "碘对比剂过敏", "D": "冠状动脉粥样硬化", "E": "良性前列腺增生"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-015", "kp": "DSA禁忌证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】碘对比剂过敏可诱发严重过敏性休克甚至死亡，是DSA的绝对禁忌证，C正确。\n【为什么错】A高血压控制后可检查；B糖尿病非禁忌；D为检查适应证；E与DSA无直接关系。", "tr": "碘过敏为绝对禁忌；高血压、糖尿病属可控因素或相对禁忌。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1016", "t": "单选题", "s": "下列属于DSA检查适应证的是", "o": {"A": "常规健康体检", "B": "疑蛛网膜下腔出血查颅内动脉瘤", "C": "孕妇常规筛查", "D": "单纯发热查因", "E": "急性感染期伴高热"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-016", "kp": "DSA适应证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】蛛网膜下腔出血多由颅内动脉瘤破裂所致，DSA是脑血管病变定位与确诊的金标准，B正确。\n【为什么错】A、C、D均无血管造影指征；E急性感染高热常为检查禁忌或相对禁忌。", "tr": "DSA为有创检查，仅用于明确适应证，不作常规筛查手段。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1017", "t": "单选题", "s": "DSA术后穿刺部位最常见的并发症是", "o": {"A": "出血和血肿", "B": "假性动脉瘤", "C": "动静脉瘘", "D": "血管内膜夹层", "E": "血栓栓塞"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-017", "kp": "穿刺部位并发症", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】穿刺点出血、血肿是股动脉穿刺后最常见的并发症，与压迫时间不足、过早活动、凝血功能异常有关，A正确。\n【为什么错】B、C、D、E均为较少见或相对少见并发症，需超声或血管造影进一步证实。", "tr": "血肿最常见；假性动脉瘤、动静脉瘘为少见而重要的并发症。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1018", "t": "单选题", "s": "为预防对比剂肾病（CIN），最有效、最基本的措施是", "o": {"A": "术前大量使用利尿剂", "B": "充分水化", "C": "术前常规服用抗生素", "D": "适当增加对比剂用量", "E": "改用高渗离子型对比剂"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-018", "kp": "对比剂肾病预防", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】水化可增加肾血流、稀释对比剂浓度，是预防CIN最有效且最基本的措施，B正确。\n【为什么错】A利尿剂可致脱水、加重肾损害；C抗生素无预防价值；D增加用量反而加重肾损伤；E高渗离子型对比剂肾毒性更大。", "tr": "水化防CIN，利尿反而有害；等渗非离子型对比剂优于高渗离子型。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1019", "t": "单选题", "s": "DSA检查前患者的禁食要求一般为", "o": {"A": "禁食1小时", "B": "禁食4~6小时", "C": "禁食12小时", "D": "禁食24小时", "E": "不需禁食"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-019", "kp": "术前禁食", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】为减少术中恶心、呕吐误吸及便于处理过敏等不良反应，血管造影术前常规禁食4~6小时，B正确。\n【为什么错】A禁食过短胃未排空；C、D禁食过长易致低血糖、脱水；E不符合术前准备要求。", "tr": "术前禁食4~6小时，禁食不禁饮的原则需结合麻醉方式掌握。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1020", "t": "单选题", "s": "DSA术前进行碘过敏试验的目的是", "o": {"A": "了解肾功能", "B": "检测患者对碘对比剂是否过敏", "C": "判断凝血功能", "D": "评估血管弹性", "E": "测定基础血压"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-020", "kp": "碘过敏试验", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】碘过敏试验通过注入少量对比剂观察机体反应，用于初筛碘对比剂过敏者，B正确。\n【为什么错】A肾功能查血肌酐、尿素氮；C凝血功能查凝血四项；D、E为常规临床检查，均与过敏试验无关。", "tr": "过敏试验只能初筛，仍存在假阴性，术中必须备好急救药品与设备。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1021", "t": "单选题", "s": "DSA术前评估穿刺出血风险必须检查的项目是", "o": {"A": "血常规", "B": "凝血功能", "C": "肝功能", "D": "心肌酶谱", "E": "血型鉴定"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-021", "kp": "术前化验评估", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】凝血功能障碍可致穿刺后出血难止，术前必须评估凝血酶原时间、活化部分凝血活酶时间等指标，B正确。\n【为什么错】A血常规虽常规查但非出血风险评估核心；C肝功能与出血风险关系间接；D用于心肌梗死诊断；E为备血常规项目。", "tr": "凝血功能＋肾功能是DSA术前两大关键化验项目。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1022", "t": "单选题", "s": "Seldinger穿刺插管技术最常用的穿刺血管是", "o": {"A": "桡动脉", "B": "股动脉", "C": "颈总动脉", "D": "锁骨下动脉", "E": "腋动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-022", "kp": "Seldinger穿刺部位", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】股动脉粗大、位置表浅、便于穿刺且穿刺点有耻骨支撑利于压迫止血，是Seldinger技术最常用的穿刺入路，B正确。\n【为什么错】A桡动脉常用于冠脉介入（经桡入路）；C颈动脉穿刺风险高；D、E位置深、并发症多，均非常规首选。", "tr": "全身血管造影默认股动脉入路；经桡动脉多用于冠脉介入治疗。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1023", "t": "单选题", "s": "股动脉穿刺点通常选在", "o": {"A": "腹股沟韧带上方", "B": "腹股沟韧带中点下方1~2cm股动脉搏动最明显处", "C": "髂前上棘处", "D": "腘窝处", "E": "大腿中段外侧"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-023", "kp": "股动脉穿刺点定位", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】腹股沟韧带中点下方1~2cm处股动脉搏动最明显，且下方有耻骨支撑便于拔管后压迫止血，为理想穿刺点，B正确。\n【为什么错】A韧带上方为髂外动脉、无骨性支撑且腹股沟深部压迫困难；C、D、E位置均不符合股动脉穿刺定位。", "tr": "穿刺点过高易进入腹膜后，过低易伤及股深动脉或出血难止。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1024", "t": "单选题", "s": "Seldinger插管技术的正确操作顺序是", "o": {"A": "穿刺针穿刺→引入导丝→退出穿刺针→沿导丝送导管", "B": "穿刺针穿刺→送入导管→退出穿刺针→沿导管送导丝", "C": "切开皮肤→直视下穿刺→置入导管", "D": "穿刺针穿刺→直接经针腔注射对比剂", "E": "先送导丝→再穿刺→再置管"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-024", "kp": "Seldinger操作步骤", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】Seldinger技术核心为穿刺针见回血后引入导丝，退出穿刺针，再沿导丝送入导管（或导管鞘），A正确。\n【为什么错】B、E顺序错误；C为直视切开法（旧术式，创伤大）；D未完成置管即注射，操作错误。", "tr": "记忆口诀“针—丝—管”，导丝始终在血管腔内引导导管。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1025", "t": "单选题", "s": "股动脉穿刺见穿刺针尾有鲜红色血液搏动性喷出，提示", "o": {"A": "误穿静脉", "B": "穿刺针位于动脉内", "C": "穿刺过浅停留在皮下", "D": "已穿出对侧血管壁", "E": "局部血管痉挛"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-025", "kp": "动脉穿刺成功指征", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】动脉血含氧丰富呈鲜红色、压力高且呈搏动性喷出，是穿刺针进入动脉腔的可靠指征，B正确。\n【为什么错】A静脉血暗红、压力低无搏动；C皮下穿刺无回血；D穿出对侧壁则回血停止；E痉挛表现为送管困难而非回血特征。", "tr": "鲜红搏动性喷血＝动脉；暗红缓慢回流＝静脉，据此调整穿刺方向。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1026", "t": "单选题", "s": "DSA常规采集的图像矩阵一般为", "o": {"A": "256×256", "B": "512×512", "C": "1024×1024", "D": "2048×2048", "E": "4096×4096"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-026", "kp": "图像矩阵", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】DSA常规采用1024×1024矩阵，兼顾空间分辨率与帧率、存储传输要求，C正确。\n【为什么错】A、B分辨率偏低，细小血管显示不佳；D、E数据量过大、帧率受限，非DSA常规选择。", "tr": "DSA常用1024矩阵，CT重建常为512×512，两者勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1027", "t": "单选题", "s": "心脏及冠状动脉DSA采集帧率一般应达到", "o": {"A": "1帧/s", "B": "2帧/s", "C": "4帧/s", "D": "6帧/s", "E": "15~25帧/s以上"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-027", "kp": "采集帧率选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】心脏搏动快、血流速度快，需高帧率连续采集（心腔造影常用25帧/s，冠脉造影12.5~30帧/s）才能完整捕捉血管充盈过程，E正确。\n【为什么错】A~D帧率过低，无法满足心脏动态成像需求。", "tr": "部位血流越快帧率越高：心脏冠脉高帧率，四肢腹部低帧率。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1028", "t": "单选题", "s": "腹部及四肢血管DSA采集帧率一般为", "o": {"A": "1帧/s以下", "B": "2~3帧/s", "C": "12帧/s", "D": "25帧/s", "E": "50帧/s"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-028", "kp": "采集帧率选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】腹部、四肢血流较慢、循环时间长，2~3帧/s即可完整记录动静脉各期，且辐射剂量低，B正确。\n【为什么错】A帧率过低可能漏拍关键时相；C、D、E为心脏/冠脉常用帧率，用于四肢属过度采集。", "tr": "低帧率（2~3帧/s）用于腹四肢，高帧率（12.5帧/s以上）用于心脏冠脉。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1029", "t": "单选题", "s": "DSA采像延迟时间主要取决于", "o": {"A": "穿刺部位", "B": "对比剂从注射部位到达靶血管的循环时间", "C": "患者年龄", "D": "导管型号", "E": "减影方式"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-029", "kp": "采像延迟时间", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】从注射开始到对比剂充盈靶血管需一定时间，按循环时间设定采像延迟，才能保证既有足够蒙片又能完整记录充盈期，B正确。\n【为什么错】A、C、D、E均与延迟时间的设定无直接关系。", "tr": "延迟＝对比剂循环时间；注射部位离靶血管越远，延迟时间越长。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1030", "t": "单选题", "s": "全脑血管造影常规应造影的血管为", "o": {"A": "仅左侧颈内动脉", "B": "主动脉弓、双侧颈总动脉及双侧椎动脉", "C": "仅主动脉弓", "D": "仅双侧椎动脉", "E": "仅右颈总动脉和右椎动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-030", "kp": "全脑血管造影范围", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】全脑血管造影常规先行主动脉弓造影了解弓上血管开口情况，再选择性行双侧颈总动脉、双侧椎动脉造影，即弓上4条主要血管，B正确。\n【为什么错】A、C、D、E均未完整包含上述血管，属不完整造影。", "tr": "全脑血管造影＝主动脉弓造影＋双侧颈总、双侧椎动脉4血管造影。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1031", "t": "单选题", "s": "头颈部DSA检查首选穿刺入路为", "o": {"A": "股动脉", "B": "颈内静脉", "C": "锁骨下动脉", "D": "肘前静脉", "E": "腘动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-031", "kp": "头颈部DSA入路", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】经股动脉Seldinger穿刺置鞘后，导管可经主动脉弓超选至颈总、椎动脉，路径成熟、安全可靠，为首选入路，A正确。\n【为什么错】B为静脉入路，用于静脉性造影；C穿刺风险高；D为静脉注射途径；E为下肢入路不用于脑血管。", "tr": "脑血管造影经股动脉入路长距离超选是常规操作。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1032", "t": "单选题", "s": "选择性颈总动脉造影时，对比剂注射流率一般选择", "o": {"A": "10~12ml/s", "B": "3~5ml/s", "C": "20~25ml/s", "D": "15~20ml/s", "E": "0.5ml/s以下"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-032", "kp": "颈动脉造影参数", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】颈总动脉属中小血管，流率过高易反流入主动脉弓或损伤血管壁，3~5ml/s即可获得满意显影，B正确。\n【为什么错】A、C、D为大血管（如主动脉）高压造影参数；E流率过低显影不清。", "tr": "血管越细流率越低：主动脉（15~20ml/s）＞颈动脉（3~5ml/s）。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1033", "t": "单选题", "s": "疑颅内动脉瘤行DSA时，为确保病变充分显示应强调", "o": {"A": "仅单一正位投照", "B": "多体位投照并酌情行旋转/3D采集", "C": "仅做侧位投照", "D": "降低矩阵以加快采集", "E": "提高注射压力以增强显影"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-033", "kp": "动脉瘤DSA投照技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】动脉瘤常因血管重叠在单一体位显示不清，需多体位投照，必要时行三维旋转采集（3D-DSA）重建，观察瘤颈与载瘤动脉关系，B正确。\n【为什么错】A、C单一体位易漏诊；D降低矩阵反而降低分辨率；E提高压力增加血管损伤与并发症风险。", "tr": "3D-DSA是颅内动脉瘤检查的进阶要求，重点评估瘤颈与载瘤动脉。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1034", "t": "单选题", "s": "历史上被公认的肺栓塞诊断“金标准”为", "o": {"A": "胸部X线平片", "B": "肺通气灌注显像", "C": "肺动脉造影（DSA）", "D": "支气管动脉造影", "E": "心脏彩色超声"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-034", "kp": "肺动脉造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】肺动脉造影可直接显示肺动脉腔内充盈缺损，曾被公认是肺栓塞诊断的金标准，C正确。\n【为什么错】A平片无特异性；B功能显像假阳性率较高；D用于咯血介入；E超声以心内结构为主。", "tr": "目前临床肺栓塞首选CTPA，但教材仍要求掌握“肺动脉造影曾是金标准”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1035", "t": "单选题", "s": "大咯血介入治疗应首选造影并栓塞的动脉是", "o": {"A": "冠状动脉", "B": "支气管动脉", "C": "颈内动脉", "D": "肾动脉", "E": "肠系膜上动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-035", "kp": "支气管动脉造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】咯血多源于支气管动脉破裂，行支气管动脉造影明确出血点后栓塞，是咯血介入治疗的核心技术，B正确。\n【为什么错】A为心脏血管；C为脑部血管；D为肾脏血管；E为肠道血管，均与咯血无关。", "tr": "咯血→支气管动脉；消化道出血→肠系膜动脉或腹腔干。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1036", "t": "单选题", "s": "主动脉造影通常选用的导管是", "o": {"A": "猪尾导管", "B": "Cobra导管", "C": "微导管", "D": "球囊导管", "E": "漂浮导管"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-036", "kp": "主动脉造影导管选择", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】猪尾导管末端卷曲并有多侧孔，高压注药时对比剂均匀喷射且不直接顶伤血管壁，是主动脉、心室造影的标准导管，A正确。\n【为什么错】B为腹腔脏器超选导管；C为超选择性小血管用导管；D为球囊扩张用；E为肺动脉测压用。", "tr": "大血管/心室用猪尾导管，内脏超选用Cobra或弯头导管。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1037", "t": "单选题", "s": "选择性冠状动脉造影在冠心病诊断中的地位是", "o": {"A": "初筛手段", "B": "诊断“金标准”", "C": "替代超声检查", "D": "心功能评估首选", "E": "术后唯一随访手段"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-037", "kp": "冠脉造影诊断地位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】选择性冠脉造影能直观显示冠脉狭窄的部位、程度与范围，是冠心病诊断的金标准，B正确。\n【为什么错】A初筛常用心电图、冠脉CTA；C超声看心腔结构与功能；D功能评估用负荷试验；E随访还需结合临床多种手段。", "tr": "冠脉造影＝解剖诊断金标准；功能评估靠负荷或灌注检查。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1038", "t": "单选题", "s": "观察左冠状动脉主干分叉（前降支与回旋支开口）的最佳投照体位是", "o": {"A": "正位+头位", "B": "蜘蛛位（左前斜+足位）", "C": "右前斜+头位", "D": "左前斜+头位", "E": "单纯正位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-038", "kp": "左冠造影投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】蜘蛛位（LAO 40°~60°＋CAU 20°~30°）能最大程度展开左主干末端及前降支、回旋支开口，避免血管重叠，是观察左冠分叉的黄金体位，B正确。\n【为什么错】A正位+头位显示前降支近中段；C、D显示前降支中远段及对角支；E单一体位无法充分展开分叉。", "tr": "蜘蛛位＝左前斜+足位；肝位＝右前斜+足位，勿混淆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1039", "t": "单选题", "s": "观察右冠状动脉全程的最佳投照体位是", "o": {"A": "左前斜45°", "B": "右前斜30°", "C": "正位+足位", "D": "标准侧位", "E": "汤氏位"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-039", "kp": "右冠造影投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】左前斜45°可将右冠状动脉拉直展开呈“C”形，从头端到后降支全程显示清晰，是观察右冠的主力体位，A正确。\n【为什么错】B、C、D、E显示右冠节段局限或不作为右冠全程显示体位。", "tr": "右冠呈“C”形用LAO45°；右冠远端分叉呈“L”形用正位+头位。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1040", "t": "单选题", "s": "左、右冠状动脉造影每次手推对比剂的用量约为", "o": {"A": "左冠8~10ml、右冠6~8ml", "B": "左冠3~5ml、右冠1~2ml", "C": "左冠30ml、右冠30ml", "D": "左冠50ml、右冠50ml", "E": "两侧均为2ml"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-040", "kp": "冠脉造影对比剂用量", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】冠脉每次造影量依血管粗细与显影情况，左冠约8~10ml、右冠约6~8ml，1~2秒内手推完成，A正确。\n【为什么错】B、E过少显影不足；C、D过多增加心肌毒性及并发症风险。", "tr": "冠脉手推小剂量（毫升级），主动脉高压注射（数十毫升），量级不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1041", "t": "单选题", "s": "冠状动脉造影不使用高压注射器而采用手推注射的主要原因是", "o": {"A": "单纯为了减少对比剂用量", "B": "冠脉血流快，需按血流速度实时调节注药，且避免高压损伤冠脉口", "C": "高压注射器无法与X线机连接", "D": "缩短检查时间", "E": "降低辐射剂量"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-041", "kp": "冠脉造影注射方式", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】冠脉开口细、血流快，手推可根据显影情况实时调整注射力度与速度，避免高压注射损伤冠脉口或致对比剂反流，B正确。\n【为什么错】A省药并非主因；C高压注射器为DSA室常规配置；D、E与注射方式无直接关系。", "tr": "冠脉手推的核心在于“可控”与“安全”，而非设备缺乏。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1042", "t": "单选题", "s": "疑肾血管性高血压，确诊有无肾动脉狭窄的检查是", "o": {"A": "腹主动脉造影+选择性肾动脉造影", "B": "心脏彩色超声", "C": "脑电图", "D": "胸部X线平片", "E": "膀胱造影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-042", "kp": "肾动脉造影适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】肾动脉狭窄是肾血管性高血压的常见原因，腹主动脉造影加选择性肾动脉造影可准确显示狭窄部位与程度，A正确。\n【为什么错】B心超看心脏结构；C脑电图看脑电活动；D胸片看心肺；E膀胱造影看膀胱形态，均与肾动脉无关。", "tr": "肾血管性高血压→肾动脉造影；这也是肾动脉介入治疗的前提检查。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1043", "t": "单选题", "s": "肝癌行TACE（肝动脉化疗栓塞）前，必须完成的DSA检查是", "o": {"A": "选择性肝动脉造影", "B": "支气管动脉造影", "C": "颈动脉造影", "D": "盆腔静脉造影", "E": "椎动脉造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-043", "kp": "肝动脉造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】TACE前必须行肝动脉造影明确肿瘤大小、数目及供血动脉来源，才能决定栓塞范围与超选插管，A正确。\n【为什么错】B用于咯血；C、E用于脑血管病；D用于盆腔病变，均与肝癌介入无关。", "tr": "“先造影后栓塞”是TACE铁律，供血动脉评估是栓塞治疗的前提。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1044", "t": "单选题", "s": "选择性腹腔干（腹腔动脉）造影主要显示", "o": {"A": "肝、脾、胃及胰腺等腹腔脏器动脉", "B": "双侧肾动脉", "C": "肠系膜上、下动脉", "D": "冠状动脉", "E": "子宫动脉"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-044", "kp": "腹腔干造影解剖", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】腹腔干发出肝总动脉、脾动脉、胃左动脉等分支，主要供血肝、脾、胃、胰等上腹腔脏器，A正确。\n【为什么错】B肾动脉为腹主动脉侧壁分支，需单独造影；C肠系膜动脉需另行插管；D、E分属心脏与盆腔供血。", "tr": "腹腔干管上腹腔脏器，肠系膜动脉管肠道血供，解剖供血范围勿混。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1045", "t": "单选题", "s": "子宫肌瘤行子宫动脉栓塞（UAE）时应栓塞的血管是", "o": {"A": "双侧子宫动脉", "B": "髂外动脉", "C": "股深动脉", "D": "卵巢动脉主干", "E": "腹主动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-045", "kp": "子宫动脉栓塞", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (5)盆腔", "ex": "【为什么对】子宫肌瘤主要由双侧子宫动脉供血，超选择性栓塞双侧子宫动脉可使肌瘤缺血坏死而正常子宫组织受损较小，A正确。\n【为什么错】B、E为血管干道，栓塞可致严重并发症；C为下肢血管；D卵巢动脉通常非肌瘤主要供血。", "tr": "UAE强调超选双侧子宫动脉，保护卵巢与子宫正常血供。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1046", "t": "单选题", "s": "盆腔DSA造影时，导管通常选择插至", "o": {"A": "髂内动脉", "B": "肠系膜上动脉", "C": "锁骨下动脉", "D": "肾动脉", "E": "肝总动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-046", "kp": "盆腔DSA插管", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (5)盆腔", "ex": "【为什么对】盆腔脏器、肿瘤及出血多由髂内动脉供血，盆腔DSA常规将导管置于髂内动脉行选择性造影，A正确。\n【为什么错】B、C、D、E分属肠道、上肢、肾脏、肝脏血供，与盆腔无关。", "tr": "盆腔血供来自髂内动脉；子宫动脉为其重要分支。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1047", "t": "单选题", "s": "下肢动脉DSA检查最常用的穿刺入路是", "o": {"A": "股动脉", "B": "颈内静脉", "C": "腘动脉", "D": "桡动脉", "E": "锁骨下动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-047", "kp": "下肢DSA入路", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】下肢动脉造影多经股动脉穿刺置鞘，采用顺行或逆行插管完成，A正确。\n【为什么错】B为静脉入路；C腘动脉穿刺少用、并发症多；D桡动脉用于冠脉介入；E位置深、风险高。", "tr": "下肢DSA=股动脉入路；对侧股动脉翻山用于处理同侧髂股病变。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1048", "t": "单选题", "s": "下肢动脉闭塞症需一次显示腹主动脉下段至足部全程血管，宜采用", "o": {"A": "单帧静态采集", "B": "步进式DSA连续采集并图像拼接", "C": "降低对比剂浓度后透视", "D": "心脏门控采集", "E": "固定视野一次注药"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-048", "kp": "下肢步进式DSA", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】步进式DSA随导管床分段移动采集后经拼接软件合成下肢血管全长图像，一次注药显示全程，是下肢动脉长段病变的标准技术，B正确。\n【为什么错】A、E视野受限无法覆盖全程；C透视无诊断价值；D用于心脏减少搏动伪影。", "tr": "“步进+拼接”＝全下肢血管显示，要求各段图像均匀衔接无中断。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1049", "t": "单选题", "s": "患者双侧髂动脉闭塞，经右侧股动脉穿刺困难，行下肢DSA应采用的入路技术是", "o": {"A": "经左侧股动脉穿刺造影", "B": "经颈内静脉逆行造影", "C": "经肘正中静脉造影", "D": "经腘动脉顺行穿刺", "E": "直接切开股动脉置管"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-049", "kp": "下肢DSA入路补救", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】一侧股动脉入路失败时，改经对侧股动脉穿刺，仍可通过翻山或顺行插管完成下肢造影，是最常规的补救入路，A正确。\n【为什么错】B、C为静脉入路，无法行下肢动脉造影；D腘动脉穿刺仅用于特殊病例且并发症多；E切开置管创伤大，非首选。", "tr": "一侧入路失败换对侧股动脉，腘动脉顺行穿刺为特殊备选。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1050", "t": "单选题", "s": "四肢动脉DSA将对比剂稀释至约含碘200mg/ml的主要目的是", "o": {"A": "提高血管显影密度", "B": "降低黏滞度、减轻血管刺激性疼痛及对比剂用量", "C": "提高高压注射器的注射压力", "D": "加快对比剂在体内的循环", "E": "降低辐射剂量"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-050", "kp": "四肢对比剂浓度", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】肢体血管较细，高浓度对比剂刺激易引起明显灼痛，稀释至200mgI/ml可降低黏滞度、减轻血管刺激与不适，同时满足显影需要，B正确。\n【为什么错】A稀释反而降低密度；C稀释与注射压力无关；D、E与对比剂浓度无关。", "tr": "肢体动脉低浓度（200mgI/ml）是共识；静脉DSA反而需较高浓度。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1051", "t": "多选题", "s": "下列属于DSA适应证的有", "o": {"A": "颅内动脉瘤", "B": "脑动静脉畸形", "C": "颈动脉狭窄", "D": "一般健康体检", "E": "下肢动脉硬化闭塞"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-051", "kp": "DSA适应证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】动脉瘤、动静脉畸形、动脉狭窄闭塞等血管性疾病及下肢动脉硬化闭塞均为DSA的典型适应证，A、B、C、E正确。\n【为什么错】D常规健康体检无血管检查指征，且DSA为有创检查，不作为筛查手段。", "tr": "DSA适应证核心是血管疾病与肿瘤血供评估，无指征检查属过度医疗。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1052", "t": "多选题", "s": "DSA检查的相对或绝对禁忌证包括", "o": {"A": "碘对比剂过敏", "B": "严重心功能不全", "C": "穿刺部位皮肤感染", "D": "血压轻度升高", "E": "严重出血倾向"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-052", "kp": "DSA禁忌证", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】碘过敏、严重心衰、穿刺部位感染、严重出血倾向均为DSA禁忌或相对禁忌，A、B、C、E正确。\n【为什么错】D血压轻度升高在控制平稳后可行检查，不属于禁忌证。", "tr": "绝对禁忌：碘过敏；相对禁忌：心肾肝衰竭、出血倾向、感染、妊娠等。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1053", "t": "多选题", "s": "股动脉穿刺术后穿刺部位的并发症包括", "o": {"A": "出血和血肿", "B": "假性动脉瘤", "C": "动静脉瘘", "D": "穿刺点血栓栓塞", "E": "对比剂肾病"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-053", "kp": "穿刺部位并发症", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】出血血肿、假性动脉瘤、动静脉瘘、血栓栓塞均为穿刺部位并发症，A、B、C、D正确。\n【为什么错】E对比剂肾病为对比剂引起的肾脏并发症，与穿刺部位无关。", "tr": "穿刺局部并发症与对比剂全身性并发症要区分开。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1054", "t": "多选题", "s": "对比剂急性过敏反应的临床表现包括", "o": {"A": "荨麻疹", "B": "喉头水肿", "C": "血压下降", "D": "支气管痉挛", "E": "血糖升高"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-054", "kp": "对比剂过敏反应", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】荨麻疹、喉头水肿、血压下降、支气管痉挛均为对比剂急性过敏反应（类过敏反应）的典型表现，A、B、C、D正确。\n【为什么错】E血糖升高非过敏反应表现。", "tr": "对比剂反应重在呼吸道与循环系统症状，重者表现为过敏性休克。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1055", "t": "多选题", "s": "DSA术前患者准备包括", "o": {"A": "碘过敏试验", "B": "术前禁食4~6小时", "C": "凝血功能与肾功能检查", "D": "穿刺部位备皮", "E": "术前常规使用抗生素"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-055", "kp": "术前患者准备", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】碘过敏试验、禁食、凝血与肾功能检查、备皮均为术前常规准备，A、B、C、D正确。\n【为什么错】E血管造影为无菌操作，术前常规使用抗生素并非必需，故排除。", "tr": "术前关键是过敏、出血、肾功能三大风险评估，预防性抗生素不常规使用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1056", "t": "多选题", "s": "DSA检查前应准备的器械物品包括", "o": {"A": "穿刺针", "B": "导丝", "C": "导管", "D": "高压注射器及对比剂", "E": "剖腹探查手术器械包"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-056", "kp": "术前物品准备", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】穿刺针、导丝、导管、高压注射器及对比剂是DSA基本器械与设备，A、B、C、D正确。\n【为什么错】E剖腹探查器械为外科手术用品，DSA为微创介入，无需准备。", "tr": "介入器械＝穿刺针＋导丝＋导管（鞘）＋高压注射系统，区别于外科器械。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1057", "t": "多选题", "s": "Seldinger技术操作中正确的做法有", "o": {"A": "穿刺点选股动脉搏动最明显处", "B": "见回血后沿针腔引入导丝", "C": "导丝遇阻力可强行推进", "D": "沿导丝送入导管或导管鞘", "E": "术后拔管充分压迫止血"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-057", "kp": "Seldinger操作要点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】搏动明显处穿刺、见回血后引丝、沿导丝送管、术后压迫止血均为正确操作，A、B、D、E正确。\n【为什么错】C导丝遇阻力强行推进易致血管损伤或夹层，应在透视下调整或退出重试。", "tr": "“遇阻力先透视找原因，绝不蛮力推进”是导丝操作安全铁律。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1058", "t": "多选题", "s": "静脉DSA（IV-DSA）的优点包括", "o": {"A": "操作简便", "B": "创伤小", "C": "不需动脉插管", "D": "细小动脉显示清晰", "E": "对比剂用量少"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-058", "kp": "静脉DSA优点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】IV-DSA经静脉途径完成，操作简便、创伤小、不需动脉插管，A、B、C正确。\n【为什么错】D对比剂经肺循环稀释后细小动脉显示不佳；E静脉法对比剂用量大，均属IV-DSA的缺点。", "tr": "IV-DSA优在简便创伤小，缺在大剂量与差显影，优缺点成对记忆。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1059", "t": "多选题", "s": "静脉DSA（IV-DSA）的缺点包括", "o": {"A": "对比剂用量大", "B": "血液稀释使细小血管显示不佳", "C": "患者移动产生的运动伪影明显", "D": "操作复杂、创伤大", "E": "不能显示全身大血管"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-059", "kp": "静脉DSA缺点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】静脉法对比剂用量大、稀释后细小血管显示差，且因循环时间长、患者易移动而产生运动伪影，A、B、C正确。\n【为什么错】D静脉法不需动脉插管，操作简便创伤小，说法错误；E静脉法恰恰可以显示主动脉等全身大血管，不属于缺点。", "tr": "IV-DSA可显示大血管、操作简便，但细小血管显示差、用量大。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1060", "t": "多选题", "s": "关于能量减影的叙述正确的有", "o": {"A": "利用碘的K吸收边（33.2keV）原理", "B": "需采用两种不同kVp的X线成像", "C": "能消除软组织影", "D": "能同时消除骨骼影", "E": "对软组织运动较为敏感"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-060", "kp": "能量减影特点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】能量减影利用碘K吸收边，用两种不同能量成像相减，能消除软组织影但对软组织运动敏感，A、B、C、E正确。\n【为什么错】D能量减影不能消除骨骼影，骨骼仍保留，故排除。", "tr": "能量减影去软组织留骨骼，与时间减影“骨软组织全消”形成对比。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1061", "t": "多选题", "s": "属于时间减影方式的有", "o": {"A": "脉冲减影", "B": "超脉冲减影", "C": "连续减影", "D": "路标技术", "E": "能量减影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-061", "kp": "时间减影分类", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】脉冲减影、超脉冲减影、连续减影及路标技术均属时间减影的不同实现方式，A、B、C、D正确。\n【为什么错】E能量减影是利用能量差异减影，与时间减影并列，不属于时间减影。", "tr": "时间减影家族：脉冲/超脉冲/连续/路标；能量减影是另一大类。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1062", "t": "多选题", "s": "影响DSA图像质量的患者自身因素包括", "o": {"A": "不自主运动", "B": "屏气不佳", "C": "肠蠕动", "D": "心律不齐", "E": "对比剂过敏试验阴性"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-062", "kp": "DSA图像质量影响因素", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】不自主运动、屏气不佳、肠蠕动、心律不齐均可导致配准不良而产生运动伪影，影响DSA图像质量，A、B、C、D正确。\n【为什么错】E过敏试验阴性为正常结果，与图像质量无关。", "tr": "图像质量受设备、操作、造影方法及患者四大因素影响，患者运动是常见伪影源。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1063", "t": "多选题", "s": "头颈部DSA的适应证包括", "o": {"A": "颅内动脉瘤", "B": "脑动静脉畸形", "C": "烟雾病", "D": "颈动脉狭窄", "E": "无明确指征的健康筛查"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-063", "kp": "头颈部DSA适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】颅内动脉瘤、动静脉畸形、烟雾病、颈动脉狭窄均为头颈部DSA的典型适应证，A、B、C、D正确。\n【为什么错】E无指征的健康筛查不属适应证，DSA为有创检查不可滥用。", "tr": "头颈DSA核心适应证为脑血管病变与颈动脉狭窄闭塞病变。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1064", "t": "多选题", "s": "全脑血管造影常需检查的血管包括", "o": {"A": "主动脉弓", "B": "左颈总动脉", "C": "右颈总动脉", "D": "左、右椎动脉", "E": "左心室"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-064", "kp": "全脑血管造影血管", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】全脑血管造影常规包括主动脉弓造影及双侧颈总、双侧椎动脉四个血管分支的选择性造影，A、B、C、D正确。\n【为什么错】E左心室造影属心脏造影范畴，不属于全脑血管造影的常规血管。", "tr": "“弓上四血管”＝双颈总＋双椎动脉，心腔造影另属心脏DSA。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1065", "t": "多选题", "s": "胸部DSA常用的造影项目包括", "o": {"A": "主动脉造影", "B": "肺动脉造影", "C": "支气管动脉造影", "D": "子宫动脉造影", "E": "肾动脉造影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-065", "kp": "胸部DSA造影项目", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】主动脉造影、肺动脉造影、支气管动脉造影均为胸部DSA常用项目，A、B、C正确。\n【为什么错】D子宫动脉造影属盆腔；E肾动脉造影属腹部。", "tr": "胸部DSA＝主动脉＋肺动脉＋支气管动脉；子宫、肾脏分属盆腹。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1066", "t": "多选题", "s": "选择性冠状动脉造影的适应证包括", "o": {"A": "典型心绞痛", "B": "急性心肌梗死", "C": "冠脉支架术后随访", "D": "不明原因胸痛伴可疑心肌缺血", "E": "常规体检"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-066", "kp": "冠脉造影适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】心绞痛、急性心肌梗死、支架术后随访及不明原因胸痛伴缺血均属冠脉造影适应证，A、B、C、D正确。\n【为什么错】E常规体检无冠脉造影指征，该检查为有创且需特殊适应证。", "tr": "冠脉造影的适应证核心是确诊冠心病与指导血运重建。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1067", "t": "多选题", "s": "冠状动脉造影的并发症包括", "o": {"A": "心律失常（心室颤动）", "B": "冠脉口夹层", "C": "急性血栓形成", "D": "对比剂过敏反应", "E": "再蒙片操作失败"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-067", "kp": "冠脉造影并发症", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】心律失常（尤其室颤）、冠脉口夹层、急性血栓、对比剂过敏反应均为冠脉造影的并发症，A、B、C、D正确。\n【为什么错】E再蒙片是图像后处理技术，操作失败不属临床并发症。", "tr": "冠脉造影最危险的并发症是室颤与冠脉夹层，术中须持续心电监护。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "检查前准备", "页": 325}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1068", "t": "多选题", "s": "腹部DSA常行的选择性造影包括", "o": {"A": "腹主动脉造影", "B": "腹腔干造影", "C": "肠系膜上动脉造影", "D": "肾动脉造影", "E": "颈总动脉造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-068", "kp": "腹部DSA造影项目", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】腹主动脉及腹腔干、肠系膜上动脉、肾动脉造影均为腹部DSA常用选择性造影，A、B、C、D正确。\n【为什么错】E颈总动脉造影属头颈部DSA范畴。", "tr": "腹部DSA＝腹主动脉＋腹腔干＋肠系膜动脉＋肾动脉；颈动脉属头颈。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1069", "t": "多选题", "s": "肾动脉造影的适应证包括", "o": {"A": "肾血管性高血压", "B": "肾动脉狭窄评估", "C": "移植肾血管评估", "D": "肾肿瘤术前栓塞", "E": "常规肾功能体检"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-069", "kp": "肾动脉造影适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】肾血管性高血压、肾动脉狭窄评估、移植肾血管评估及肾肿瘤术前栓塞均为肾动脉造影适应证，A、B、C、D正确。\n【为什么错】E肾功能评估靠血液生化检查，常规体检不需肾动脉造影。", "tr": "肾动脉造影服务于“狭窄”与“肿瘤栓塞”两大目的，非常规体检项目。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1070", "t": "多选题", "s": "盆腔DSA的临床应用包括", "o": {"A": "子宫肌瘤栓塞（UAE）", "B": "产后大出血栓塞", "C": "盆腔肿瘤术前栓塞", "D": "前列腺动脉栓塞", "E": "脑动脉瘤栓塞"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-070", "kp": "盆腔DSA应用", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (5)盆腔", "ex": "【为什么对】子宫肌瘤栓塞、产后大出血栓塞、盆腔肿瘤术前栓塞及前列腺动脉栓塞均为盆腔DSA的应用，A、B、C、D正确。\n【为什么错】E脑动脉瘤栓塞为头颈部DSA的应用，与盆腔无关。", "tr": "盆腔介入两大主题：妇科出血/肌瘤栓塞与盆腔肿瘤术前评估。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1071", "t": "多选题", "s": "四肢DSA的适应证包括", "o": {"A": "下肢动脉硬化闭塞症", "B": "血栓闭塞性脉管炎", "C": "糖尿病足", "D": "四肢血管损伤", "E": "常规健康体检"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-071", "kp": "四肢DSA适应证", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】下肢动脉硬化闭塞、血栓闭塞性脉管炎、糖尿病足及四肢血管损伤均为四肢DSA的适应证，A、B、C、D正确。\n【为什么错】E常规体检无适应证。", "tr": "四肢DSA核心适应证是缺血性病变与血管外伤。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1072", "t": "多选题", "s": "DSA设备系统组成包括", "o": {"A": "X线球管与高压发生器", "B": "探测器（影像增强器或平板探测器）", "C": "图像数字处理系统", "D": "高压注射器", "E": "核磁共振梯度系统"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-072", "kp": "DSA设备组成", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】X线发生系统、探测器、数字图像处理系统及高压注射器均为DSA设备的基本组成，A、B、C、D正确。\n【为什么错】E梯度系统为MRI设备部件，与DSA无关。", "tr": "DSA设备无梯度系统；高压注射器是DSA（及CT增强）的配套设备。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1073", "t": "多选题", "s": "高压注射器的注射参数包括", "o": {"A": "注射流率", "B": "注射总量", "C": "压力限值", "D": "注射延迟时间", "E": "图像矩阵"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-073", "kp": "高压注射器参数", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】流率、总量、压力限值及延迟时间是高压注射器的核心设定参数，A、B、C、D正确。\n【为什么错】E图像矩阵属于采集与显示参数，不属注射器参数。", "tr": "注射参数管“怎么注”，矩阵帧率管“怎么采”，分属两套参数体系。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1074", "t": "多选题", "s": "减影后的DSA图像特点包括", "o": {"A": "骨骼影被消除", "B": "软组织影被消除", "C": "含碘血管显示清晰", "D": "血管壁钙化显示最佳", "E": "背景噪声相对突出"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-074", "kp": "减影图像特点", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】时间减影后骨骼与软组织被消除，含碘血管突出显示，同时因相减处理使背景噪声相对突出，A、B、C、E正确。\n【为什么错】D血管壁钙化与骨骼同属高密度背景，减影后同样被消除，不能最佳显示。", "tr": "钙化属“背景”，减影后消失；DSA看的是血管腔内对比剂。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1075", "t": "多选题", "s": "对比剂肾病（CIN）的危险因素包括", "o": {"A": "原有肾功能不全", "B": "糖尿病", "C": "脱水状态", "D": "对比剂用量过大", "E": "年轻健康人群"}, "d": "难", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-075", "kp": "对比剂肾病危险因素", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】原有肾功能不全、糖尿病、脱水及对比剂用量过大均为CIN的高危因素，A、B、C、D正确。\n【为什么错】E年轻健康人群肾储备好、CIN风险低，不属于危险因素。", "tr": "CIN风险＝肾功能基础＋糖尿病＋脱水＋剂量；识别高危患者先行预防。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1076", "t": "多选题", "s": "改善DSA图像运动伪影的措施包括", "o": {"A": "嘱患者屏气并固定被检部位", "B": "缩短注药与采像的时间间隔", "C": "采用心电门控采集", "D": "对移动部位重新选择蒙片（再蒙片）", "E": "将对比剂浓度提高至90%以上"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-076", "kp": "DSA运动伪影改善", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】屏气固定、缩短注药采像间隔、心电门控及再蒙片均能有效减少或纠正运动伪影，A、B、C、D正确。\n【为什么错】E提高对比剂浓度不解决运动配准问题，且高浓度并非影像质量改善手段。", "tr": "抗运动伪影的手段是“固定＋快采＋门控＋再蒙片”，与对比剂浓度无关。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1077", "t": "多选题", "s": "关于主动脉造影的技术要点正确的有", "o": {"A": "选用猪尾多侧孔导管", "B": "采用高压注射器大流率注射", "C": "流率过低可致对比剂稀释、显影不均", "D": "先采集蒙片再注射对比剂", "E": "必须使用微导管超选择性注射"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-077", "kp": "主动脉造影技术要点", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】主动脉造影用猪尾多侧孔导管、高压大流率注射、流率不足致稀释不均、先采蒙片再注药均为正确要点，A、B、C、D正确。\n【为什么错】E主动脉造影属非选择性造影，需快速团注大流量对比剂，微导管仅用于超选择性小血管，不适用于主动脉造影。", "tr": "大血管用大导管大流率，微导管是超选小血管的工具。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1078", "t": "多选题", "s": "DSA在介入治疗中的特殊应用技术包括", "o": {"A": "路标技术引导超选择性插管", "B": "血管栓塞治疗（如TACE、支气管动脉栓塞）", "C": "血管成形与支架置入", "D": "动脉溶栓治疗", "E": "常规胸部X线摄影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-078", "kp": "DSA介入应用", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】路标引导超选、栓塞、成形支架置入及溶栓均为DSA介入治疗的应用技术，A、B、C、D正确。\n【为什么错】E常规胸部X线摄影属普通X线检查，与DSA介入应用无关。", "tr": "DSA介入四大方向：引导、栓塞、成形、溶栓。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U11-1079a", "t": "单选题", "s": "【病例】患者男，62岁，因双下肢间歇性跛行1年、加重2个月入院，查体双下肢皮温低、足背动脉搏动减弱，踝肱指数（ABI）0.5。临床拟行下肢动脉DSA明确血管狭窄部位与程度，先行右侧股动脉穿刺置鞘。 该患者股动脉穿刺点应选择在", "o": {"A": "腹股沟韧带上方1~2cm处", "B": "腹股沟韧带中点下方1~2cm股动脉搏动最明显处", "C": "腘窝处", "D": "大腿中段内侧", "E": "髂前上棘处"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-079", "kp": "股动脉穿刺点定位", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】腹股沟韧带中点下方1~2cm搏动最明显处是股动脉标准穿刺点，下方有耻骨支撑便于压迫止血，B正确。\n【为什么错】A韧带上方为髂外动脉段且无骨性支撑；C、D非股动脉表浅搏动区；E与股动脉走行无关。", "tr": "股动脉穿刺点在腹股沟韧带下方，过高过低均增加并发症。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1079b", "t": "单选题", "s": "穿刺针见搏动性鲜红色血液回血后，正确的下一步操作是", "o": {"A": "退出穿刺针，直接置入导管", "B": "经针腔直接注入对比剂造影", "C": "拔出穿刺针后重新穿刺", "D": "固定穿刺针，沿针腔引入导丝", "E": "先压迫止血再送导管"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-080", "kp": "Seldinger穿刺操作", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 穿刺插管技术（Seldinger）", "ex": "【为什么对】Seldinger技术见搏动性动脉血回血后，应固定穿刺针并沿针腔送入导丝，再退出穿刺针沿导丝置鞘，D正确。\n【为什么错】A未引入导丝直接置管易伤血管；B未置鞘即注射属错误操作；C已成功穿刺无需重穿；E应先完成置管再行止血。", "tr": "“针—丝—管”顺序不能乱，导丝是导管进入血管的轨道。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1079c", "t": "单选题", "s": "术后拔除导管鞘后，穿刺部位徒手压迫止血时间一般为", "o": {"A": "1~2分钟", "B": "5分钟以内", "C": "10~15分钟", "D": "1小时以上", "E": "无需压迫"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-081", "kp": "术后穿刺点压迫", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】拔鞘后需充分压迫止血10~15分钟使穿刺道闭合，再以沙袋加压包扎并制动，C正确。\n【为什么错】A、B压迫时间不足易再出血形成血肿；D过长时间增加不适与并发症；E必然导致出血。", "tr": "股动脉压迫10~15分钟、术侧肢体制动6~8小时是术后护理要点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1080a", "t": "单选题", "s": "【病例】患者女，48岁，突发剧烈头痛伴恶心呕吐2小时急诊入院，头颅CT示蛛网膜下腔出血，高度怀疑颅内动脉瘤破裂，临床申请全脑血管DSA检查，术前拟行碘过敏试验并评估肾功能。 该患者DSA检查前最关键的准备是", "o": {"A": "常规心电图检查", "B": "测量体重", "C": "拍摄胸部X线片", "D": "询问碘过敏史并行碘过敏试验", "E": "心理疏导谈话"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-082", "kp": "术前过敏史评估", "ch": "十一、DSA检查技术 → 1.检查前准备 → (2)术前准备", "ex": "【为什么对】碘对比剂过敏是DSA绝对禁忌，术前询问过敏史并行过敏试验是保障安全的关键环节，D正确。\n【为什么错】A、C为常规项目非关键；B与检查安全性无关；E心理疏导非术前准备核心。", "tr": "过敏史评估直接关系能否造影，是术前安全评估的第一关。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1080b", "t": "单选题", "s": "该患者全脑血管造影的检查顺序应为", "o": {"A": "直接行左椎动脉选择性造影", "B": "先主动脉弓造影，再选择性行双侧颈总、双侧椎动脉造影", "C": "仅行双侧颈内动脉造影", "D": "先右颈总动脉再左椎动脉即可", "E": "先行左心室造影"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-083", "kp": "全脑血管造影顺序", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】全脑血管造影常规先主动脉弓造影了解弓上血管开口与走行变异，再选择性行双侧颈总动脉及双侧椎动脉共4条血管造影，B正确。\n【为什么错】A、C、D均非完整规范流程；E左心室造影属心脏造影，与脑血管检查无关。", "tr": "造影顺序“先大后小、先非选择性后选择性”，保证血管覆盖完整。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1081a", "t": "单选题", "s": "【病例】患者男，55岁，反复发作性心前区闷痛1个月，活动后加重，静息心电图示ST段压低、T波倒置，临床拟行选择性冠状动脉造影明确病变，已服用阿司匹林与降脂药物，无造影剂过敏史。 为清晰显示左主干分叉及前降支、回旋支开口，应采用的投照体位是", "o": {"A": "正位+头位", "B": "右前斜+头位", "C": "蜘蛛位（左前斜+足位）", "D": "标准后前位", "E": "左侧位"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-084", "kp": "左冠分叉投照体位", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】蜘蛛位（LAO 40°~60°＋CAU 20°~30°）可将左主干末端及前降支、回旋支开口充分展开，是观察左冠分叉的黄金体位，C正确。\n【为什么错】A显示前降支近中段；B显示前降支中远段；D、E不能充分展开分叉结构。", "tr": "蜘蛛位＝LAO+CAU；肝位＝RAO+CAU，体位名称与角度要分清。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1081b", "t": "单选题", "s": "冠脉造影时对比剂注射方式应选择", "o": {"A": "手推注射，根据显影情况实时调节", "B": "高压注射器大流率注射", "C": "持续缓慢滴注", "D": "经导管直接灌入", "E": "不注射对比剂直接透视"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-085", "kp": "冠脉造影注射方式", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】冠脉血流快、开口细，手推可依实时显影调节注射力度与速度，避免高压反流与损伤冠脉口，A正确。\n【为什么错】B高压注射易损伤冠脉口或致反流；C、D无法形成快速团注；E不注射无法显影。", "tr": "冠脉手推（8~10ml）是经典操作，与主动脉高压注射形成对比。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1082a", "t": "单选题", "s": "【病例】患者男，70岁，左下肢发凉麻木伴静息痛2个月，查体左侧股动脉搏动减弱，踝肱指数（ABI）0.4，拟行下肢动脉DSA评估狭窄部位与程度，要求同时评估髂动脉及膝下流出道情况。 为同时显示左髂动脉及股腘动脉病变，首选穿刺入路是", "o": {"A": "左侧腘动脉顺行穿刺", "B": "经右侧股动脉穿刺行翻山造影", "C": "经左侧肘正中静脉", "D": "经颈内静脉逆行", "E": "直接切开左股动脉"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-086", "kp": "下肢DSA翻山技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】左髂动脉及股腘动脉均有病变时，同侧顺行穿刺可能受阻，经对侧（右侧）股动脉穿刺行翻山（cross-over）技术，导管翻越腹主动脉分叉进入左髂动脉，可全程显示病变，B正确。\n【为什么错】A腘动脉穿刺非首选且并发症多；C、D静脉入路无法行下肢动脉造影；E切开置管创伤大。", "tr": "“翻山”＝对侧股动脉入路跨越腹主动脉分叉，用于同侧髂股病变。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1082b", "t": "单选题", "s": "欲一次注药显示腹主动脉下段至足背动脉全程血管，应采用", "o": {"A": "单帧静态采集", "B": "重复三次分别造影", "C": "步进式DSA分段采集后图像拼接", "D": "心脏门控采集", "E": "降低帧率至1帧/s透视"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-087", "kp": "步进式DSA拼接", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】步进式DSA随床移动分段采集，再由拼接软件合成下肢血管全长图，一次注药完成全程显示，C正确。\n【为什么错】A视野局限；B多次注药增加剂量与用量；D用于心脏；E透视无诊断价值。", "tr": "下肢全长显示依赖“步进采集＋拼接”，是长段病变介入的前提。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1082c", "t": "单选题", "s": "该患者肢体动脉造影对比剂应如何配制", "o": {"A": "使用370mgI/ml原液高压注射", "B": "用蒸馏水稀释至100mgI/ml以下", "C": "混合造影剂与自体血注射", "D": "稀释至约含碘200mg/ml的低渗非离子型对比剂", "E": "加入肾上腺素增强显影"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-088", "kp": "四肢对比剂稀释", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】肢体血管细、高浓度刺激痛感强，常规将非离子型对比剂稀释至约含碘200mg/ml，既满足显影又减轻刺激与用量，D正确。\n【为什么错】A原液刺激痛感重、用量大；B浓度过低显影不足；C自体血混合无此必要；E肾上腺素属血管活性药，不可加入。", "tr": "肢体动脉低浓度（200mgI/ml）、下肢全程步进拼接是两大要点。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1083a", "t": "单选题", "s": "【病例】患者男，58岁，乙型肝炎肝硬化病史，增强CT示肝右叶巨块型肝癌，AFP明显升高，临床拟行TACE（肝动脉化疗栓塞）治疗，术前先行肝动脉DSA检查，评估肿瘤供血动脉来源。 TACE术前DSA应首先进行的检查是", "o": {"A": "选择性肝动脉造影明确肿瘤供血", "B": "左心室造影", "C": "颈动脉造影", "D": "肾动脉造影", "E": "髂内动脉造影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-089", "kp": "TACE术前肝动脉造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】TACE前必须肝动脉造影明确肿瘤大小、数目、供血动脉及有无肝外寄生供血，才能制定栓塞方案，A正确。\n【为什么错】B、C、D、E分属心脏、脑部、肾脏、盆腔血管，与肝癌介入无关。", "tr": "肝癌TACE“先造影后栓塞”，供血动脉评估决定栓塞效果。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1083b", "t": "单选题", "s": "明确肿瘤供血动脉后，为避免损伤正常肝组织的下一步操作是", "o": {"A": "直接经肝总动脉注射栓塞剂", "B": "增大栓塞剂用量", "C": "微导管超选择性插管至肿瘤供血动脉后栓塞", "D": "改为静脉途径栓塞", "E": "终止TACE治疗"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-090", "kp": "超选择性栓塞", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】微导管超选择性插管至肿瘤供血分支再栓塞，可最大限度地保护正常肝组织、提高栓塞效果，C正确。\n【为什么错】A经肝总动脉栓塞范围大、正常肝损伤重；B加大剂量增加异位栓塞风险；D栓塞为动脉途径；E属放弃治疗，均不正确。", "tr": "“超选越深、保护越多”是TACE质量控制的核心原则。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "DSA的常用器械", "页": 326}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1084a", "t": "单选题", "s": "【病例】患者男，40岁，反复大咯血1周，每次约100~200ml，内科药物治疗效果不佳，胸部CT提示支气管扩张，生命体征尚平稳，临床拟行介入治疗控制咯血，已备好栓塞材料与急救药品。 该患者应首先进行的DSA检查是", "o": {"A": "冠状动脉造影", "B": "支气管动脉造影", "C": "肾动脉造影", "D": "颈内动脉造影", "E": "肠系膜上动脉造影"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-091", "kp": "咯血介入造影", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】咯血多源于支气管动脉，支气管动脉造影可直接显示出血供血动脉，是咯血介入治疗的首选检查，B正确。\n【为什么错】A、C、D、E分属心脏、肾脏、脑部、肠道血管，与咯血无关。", "tr": "咯血→支气管动脉造影＋栓塞；消化道出血→肠系膜动脉。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1084b", "t": "单选题", "s": "造影中发现支气管动脉与脊髓动脉共干时，下列处理最恰当的是", "o": {"A": "直接常规栓塞该支", "B": "加大栓塞剂量彻底止血", "C": "改用高压注射快速栓塞", "D": "改行颈动脉造影替代", "E": "停止栓塞该支，警惕脊髓动脉损伤风险，必要时改用非栓塞方案"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-092", "kp": "脊髓动脉损伤防范", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】脊髓动脉与支气管动脉共干时，栓塞可能致脊髓缺血坏死引起截瘫，应停止栓塞并警惕风险，必要时以其他供血动脉或介入手段处理，E正确。\n【为什么错】A、B、C栓塞该支均可能引发脊髓损伤严重后果；D改行颈动脉造影与咯血无关。", "tr": "支气管动脉栓塞最需警惕脊髓动脉共干导致的截瘫并发症。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1085a", "t": "单选题", "s": "【病例】患者女，32岁，血压持续升高3个月，多种降压药物联合治疗效果差，腹部听诊可闻及血管杂音，临床疑肾动脉狭窄所致肾血管性高血压，拟行DSA检查，术前已行肾功能与凝血功能评估。 为明确诊断应行的DSA检查是", "o": {"A": "腹主动脉造影+选择性肾动脉造影", "B": "左心室造影", "C": "全脑血管造影", "D": "冠状动脉造影", "E": "子宫动脉造影"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-093", "kp": "肾动脉造影确诊", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】年轻患者顽固性高血压伴腹部血管杂音提示肾动脉狭窄，腹主动脉造影加选择性肾动脉造影可明确诊断，A正确。\n【为什么错】B、C、D、E分属心脏、脑部、冠脉、盆腔血管，均不能显示肾动脉狭窄。", "tr": "年轻顽固性高血压→肾动脉造影，同时排除纤维肌性发育不良等病因。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1085b", "t": "单选题", "s": "选择性肾动脉造影的对比剂注射参数应选择", "o": {"A": "流率20~25ml/s、总量50ml", "B": "流率10~12ml/s、总量30ml", "C": "流率4~5ml/s、总量8~12ml", "D": "流率1ml/s以下、总量2ml", "E": "流率30ml/s、总量80ml"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-094", "kp": "肾动脉造影参数", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】肾动脉属中小分支血管，低流率小剂量注射即可清晰显影且不损伤血管，4~5ml/s、8~12ml为宜，C正确。\n【为什么错】A、B、E流率与总量过大，易致反流与血管损伤；D过少无法充分显影。", "tr": "选择性小动脉造影“低流率小剂量”，主动脉造影“高流率大剂量”。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1095", "t": "案例分析题", "s": "患者男，60岁，因反复头晕、一过性言语不清3天入院，头颅MRI提示脑缺血，临床拟行全脑血管DSA明确血管情况。术前碘过敏试验阴性，心电监护下经股动脉置鞘，先行主动脉弓造影，注射对比剂约20ml时患者突发全身荨麻疹、声音嘶哑、咽喉部发紧，继之呼吸急促，血压降至80/50mmHg，心率130次/分，血氧饱和度降至88%，考虑为对比剂急性过敏反应。此时技师应立即采取的正确措施是", "o": {"A": "继续完成造影以观察血管病变", "B": "立即停止注射对比剂，保持呼吸道通畅，协助医生抗过敏抗休克抢救并做好记录", "C": "嘱患者深呼吸平卧休息后继续检查", "D": "给予抗生素预防继发感染", "E": "降低对比剂浓度后继续造影"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-095", "kp": "对比剂过敏反应应急处理", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】患者出现荨麻疹、喉头水肿、低血压等典型对比剂急性过敏反应，应立即停止注射、保持气道通畅，并协助医生给予肾上腺素等抗过敏抗休克治疗，同时记录抢救过程，B正确。\n【为什么错】A继续造影加重病情；C单纯休息不能阻止过敏进展；D抗生素对过敏反应无效；E继续注射对比剂危及生命。", "tr": "对比剂重度过敏“停止注射—保持气道—抗过敏抗休克”是抢救三步。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1096", "t": "案例分析题", "s": "患者男，65岁，因急性前壁心肌梗死3小时行急诊冠状动脉造影及PCI术，术前已置入股动脉鞘，心电监护、除颤仪及抢救药品均处于备用状态。造影前完成主动脉根部和左冠状动脉造影准备，当造影导管置于左冠状动脉口并手推对比剂时，患者突发意识丧失、四肢抽搐，心电监护显示心室颤动波形，血压测不出。此时造影室内正确的处理配合是", "o": {"A": "继续手推对比剂完成左室造影", "B": "立即停止操作，撤出造影导管，协助电除颤并配合心肺复苏", "C": "加大吸氧观察5分钟再决定", "D": "嘱患者用力咳嗽缓解", "E": "加快造影速度缩短操作时间"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-096", "kp": "冠脉造影室颤处理", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】冠脉造影致心室颤动是危急并发症，应立即停止操作、撤出导管，尽早电除颤并配合心肺复苏，B正确。\n【为什么错】A继续注射加重心肌缺血与心律失常；C、D均无法终止室颤；E加快操作不能解决已发生的室颤。", "tr": "室颤处理争分夺秒，电除颤是首选，操作人员应立即配合。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1097", "t": "案例分析题", "s": "患者女，50岁，因反复发作的短暂性脑缺血发作拟行颈内动脉DSA。造影过程中患者情绪紧张，间断出现吞咽动作及头部轻微移动，减影图像显示血管边缘呈“双影”样模糊、轮廓错位，颅内段尤为明显，复查设备参数与原始图像未见异常，考虑为患者运动导致的蒙片与含对比剂图像配准不良，图像需重新处理后方可诊断。此时技师首先应采取的措施是", "o": {"A": "更换更粗的造影导管", "B": "嘱患者屏气并固定头部，必要时行再蒙片或重新采集", "C": "增加对比剂浓度增强显影", "D": "提高球管管电流", "E": "转外科开腹手术处理"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-097", "kp": "运动伪影处理", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 参数选择", "ex": "【为什么对】“双影”、轮廓错位是典型运动伪影，首先应取得患者配合（屏气、固定头部），并通过再蒙片或重新采集纠正配准误差，B正确。\n【为什么错】A导管粗细与伪影无关；C、D改变对比剂或管电流不能解决运动错位；E外科手术与图像伪影处理无关。", "tr": "运动伪影靠“固定＋屏气＋再蒙片”解决，改变成像参数无效。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1098", "t": "案例分析题", "s": "患者男，68岁，高血压病史10年，因腹主动脉瘤行腹主动脉DSA，术程顺利，术中血压平稳。术后回病房3小时患者自述右侧腹股沟穿刺部位胀痛，检查发现穿刺处包块进行性增大，触之有波动感，皮肤张力增高，血压由130/80mmHg降至100/60mmHg，心率由72次/分增至100次/分，无发热。首先考虑并应采取的措施是", "o": {"A": "属正常术后肿胀，无需处理", "B": "考虑穿刺点出血血肿或假性动脉瘤，立即徒手压迫穿刺点并评估血流动力学，必要时床旁超声及外科处理", "C": "立即拆除敷料任其出血", "D": "口服止痛药继续观察", "E": "让患者下床活动促进吸收"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-098", "kp": "穿刺点血肿处理", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】术后穿刺处包块进行性增大伴血流动力学变化，提示穿刺点活动性出血或假性动脉瘤，应立即压迫止血并评估病情，必要时超声证实并行外科处理，B正确。\n【为什么错】A正常肿胀不会进行性增大并致血压下降；C拆除敷料加重出血；D止痛不能阻止出血；E活动加重出血风险。", "tr": "穿刺点包块增大＋血压下降＝活动性出血，必须立即压迫并动态评估。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1099", "t": "案例分析题", "s": "患者男，72岁，吸烟史40年，右下肢间歇性跛行3年，近2个月静息痛明显，夜间尤甚，查体右侧足背动脉搏动消失，ABI 0.45，超声示右股浅动脉中段长段闭塞，远端流出道情况不详。临床拟行下肢动脉DSA，必要时行介入开通治疗，要求一次造影显示病变全程及远端流出道。关于该患者DSA检查的技术方案与参数选择，正确的是", "o": {"A": "单帧静态正位一次完成", "B": "经对侧股动脉或同侧股动脉入路，行步进式DSA分段采集并拼接，全程显示病变", "C": "仅造影右髂动脉即可", "D": "使用静脉DSA代替动脉DSA", "E": "不注射对比剂直接行血管成形"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-099", "kp": "下肢动脉DSA检查方案", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (6)四肢", "ex": "【为什么对】下肢长段闭塞病变应经股动脉入路，采用步进式DSA分段采集拼接，一次注药显示病变全程与流出道，为介入开通提供依据，B正确。\n【为什么错】A静态采集无法覆盖全程；C仅髂动脉无法评估股腘段；D静脉DSA显影差不能满足介入要求；E不经造影盲目成形风险极大。", "tr": "下肢介入术前必须“全程造影＋流出道评估”，步进拼接是标准方案。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1100", "t": "案例分析题", "s": "患者男，45岁，反复黑便、鲜血便1月余，共输血4次，血红蛋白降至60g/L，胃镜与结肠镜均未发现明确出血灶，腹部CTA亦未明确定位出血血管，内科保守治疗效果差，目前仍间断排鲜血便，生命体征尚平稳。临床拟行DSA寻找出血部位并准备介入栓塞，术前已纠正贫血并签署知情同意，备好栓塞材料。正确的检查技术要点是", "o": {"A": "待出血停止1月后再择期造影", "B": "活动性出血期急诊造影，依次行腹腔干、肠系膜上动脉、肠系膜下动脉造影，发现对比剂外溢处即行栓塞", "C": "仅行腹主动脉造影即可定位", "D": "常规行冠状动脉造影排除心源性因素", "E": "造影前无需准备直接行腹部平片即可"}, "d": "难", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-100", "kp": "消化道出血DSA", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】消化道出血DSA应在活动性出血期急诊进行，依次行腹腔干、肠系膜上、肠系膜下动脉造影，造影剂外溢是出血的直接征象，发现后即可栓塞，B正确。\n【为什么错】A出血停止后造影常阴性；C腹主动脉造影无法显示肠系膜分支出血；D冠脉造影与消化道出血无关；E腹部平片不能显示血管出血。", "tr": "消化道出血DSA“出血时造影才有阳性率”，外溢征象是栓塞指征。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1101", "t": "案例分析题", "s": "患者男，50岁，支气管扩张病史10年，因反复大咯血（每日约200~300ml）内科治疗无效行支气管动脉造影。造影显示右支气管动脉增粗迂曲，供血区域明显，拟行栓塞治疗。当导管超选进入右支气管动脉后，造影发现该动脉与肋间动脉共干，并见细小的脊髓动脉分支显影，患者双下肢活动正常，需权衡止血效果与脊髓保护。此时正确的处理是", "o": {"A": "立即常规栓塞该支以控制出血", "B": "加大栓塞剂用量彻底止血", "C": "撤出导管改用球囊扩张治疗", "D": "审慎处理：停止该支栓塞以防脊髓缺血，必要时超选择避开脊髓动脉或用其他供血动脉处理", "E": "改行颈动脉栓塞治疗"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-101", "kp": "咯血栓塞脊髓动脉防范", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】支气管动脉与脊髓动脉共干时栓塞可引起脊髓缺血坏死致截瘫，应审慎处理：停止该支栓塞，必要时超选避开脊髓动脉或选用其他供血动脉，D正确。\n【为什么错】A、B栓塞该支有截瘫风险；C球囊扩张不适用于咯血治疗；E颈动脉栓塞与咯血无关。", "tr": "脊髓动脉共干是支气管动脉栓塞的“禁区”，识别与规避是安全关键。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1102", "t": "案例分析题", "s": "患者女，55岁，突发剧烈头痛伴恶心呕吐2天入院，头颅CT示广泛蛛网膜下腔出血，行全脑血管DSA发现右侧大脑中动脉分叉部动脉瘤，直径约6mm，常规2D体位下瘤颈形态显示欠佳，载瘤动脉与周围血管关系不清，介入栓塞与开颅夹闭手术方案尚未确定。为准确评估动脉瘤颈宽度及其与载瘤动脉的关系，以指导治疗决策，应进一步采用的技术是", "o": {"A": "三维旋转采集（3D-DSA）重建", "B": "提高对比剂浓度重复2D造影", "C": "降低矩阵加快采集速度", "D": "延长透视时间观察", "E": "改用静脉DSA替代"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-102", "kp": "3D-DSA动脉瘤评估", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】3D-DSA（三维旋转采集）可从任意角度重建，清晰显示动脉瘤颈及与载瘤动脉的空间关系，是动脉瘤介入评估的标准技术，A正确。\n【为什么错】B提高浓度仅增强显影密度，不能解决角度重叠；C降低矩阵降低分辨率；D透视无三维信息；E静脉DSA显示细节更差。", "tr": "动脉瘤术前评估强调“3D重建看瘤颈”，2D体位无法替代。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1103", "t": "案例分析题", "s": "患者男，60岁，冠心病不稳定型心绞痛，拟在冠脉造影的同时行左心室造影评估左心功能与室壁运动。患者体重70kg，无肾功能异常，既往无造影剂过敏史，心功能分级Ⅱ级。左心室造影需选用合适的导管并设定正确的注射参数，以获得良好的心室显影，同时避免造影剂过量与造影诱发心律失常的风险。关于左心室造影技术参数的叙述，正确的是", "o": {"A": "选用Cobra导管、低流率缓慢注射", "B": "选用猪尾导管，对比剂浓度约370mgI/ml，流率12~15ml/s、总量30~40ml，高帧率采集", "C": "选用微导管手推对比剂", "D": "流率2ml/s缓慢注射", "E": "采集帧率降至1帧/s"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-103", "kp": "左心室造影参数", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (3)心脏与冠状动脉造影", "ex": "【为什么对】左心室造影用猪尾导管、370mgI/ml对比剂、12~15ml/s流率、30~40ml总量并以高帧率（如25帧/s）采集，可良好显示室壁运动，B正确。\n【为什么错】A、C、D导管或流率不匹配，无法形成有效心室团注；E低帧率无法评估室壁运动。", "tr": "左室造影“猪尾导管＋12~15ml/s大流率＋高帧率”为经典参数组合。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1104", "t": "案例分析题", "s": "患者男，68岁，超声示右侧颈内动脉起始部重度狭窄（约80%），近期反复出现一过性黑矇与头晕，头颅MRI提示右侧大脑半球多发腔隙性梗死，拟行颈动脉支架置入术。患者合并高血压、糖尿病，颈动脉斑块为混合性斑块，术前需充分评估主动脉弓形态及狭窄段斑块情况，以制定安全的手术方案。关于术前及术中DSA技术的正确做法是", "o": {"A": "先行主动脉弓造影了解开口，再选择性颈总动脉造影，路标技术引导导丝通过狭窄段，支架置入后复查造影", "B": "直接经狭窄段置入支架，无需先行造影", "C": "用静脉DSA全程代替动脉造影", "D": "支架置入后立即拔除导管，不需复查", "E": "术前不需行主动脉弓造影，直接选择性插管"}, "d": "难", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-104", "kp": "颈动脉支架DSA技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】颈动脉支架术前先主动脉弓造影了解开口与走行，再选择性颈总动脉造影评估狭窄，术中路标技术引导导丝安全通过狭窄段，支架置入后复查造影确认，A正确。\n【为什么错】B不造影盲放风险大；C静脉DSA显影差不能满足介入要求；D术后必须复查确认支架与血流；E主动脉弓造影是必要步骤。", "tr": "颈动脉介入“弓上造影—选择性造影—路标引导—术后复查”环环相扣。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1105", "t": "案例分析题", "s": "患者男，70岁，体检发现腹主动脉瘤，直径约5.0cm，位于肾动脉平面以下，可疑累及双侧髂总动脉开口，拟行DSA明确瘤体大小、瘤颈及与肾动脉的关系，为腔内介入治疗做准备。患者有轻度肾功能减退（血肌酐升高），对造影剂肾损伤风险较为敏感，术前已开始预防性水化，需兼顾诊断效果与肾脏安全。关于成像方式选择的正确做法是", "o": {"A": "首选静脉DSA，创伤最小", "B": "优先选择动脉DSA，对比剂用量少、浓度低，可减少肾损伤", "C": "必须使用高浓度对比剂行静脉注射", "D": "静脉DSA与动脉DSA用量相同", "E": "避免使用对比剂，仅行透视检查"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-105", "kp": "肾功能减退成像方式选择", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】动脉DSA对比剂用量少、浓度低，对肾功能减退者肾损伤更小，应优先选择，B正确。\n【为什么错】A静脉DSA用量大、肾负担重；C、D高浓度大剂量加重肾损伤；E透视不能显示血管腔。", "tr": "肾功能不好选动脉DSA“省药”，与静脉DSA“创伤小但费药”权衡不同。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1106", "t": "案例分析题", "s": "患者女，48岁，因右侧颈内动脉重度狭窄（90%）行颈动脉支架置入术，术程顺利，支架展开良好，术中复查造影血流通畅，无残余狭窄。术后1小时患者突然出现左侧肢体无力、言语不清，NIHSS评分8分，血压平稳，无心悸胸闷，考虑与术中斑块脱落或支架内急性血栓形成有关，需紧急评估处理。此时最可能的并发症及正确处理是", "o": {"A": "属正常术后反应，继续观察", "B": "考虑术中栓塞或支架内血栓致急性缺血性卒中，立即复查DSA评估，必要时动脉内溶栓或取栓", "C": "立即口服阿司匹林后出院", "D": "行头颅平片检查", "E": "嘱患者休息后自行恢复"}, "d": "中", "c": "应用", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-106", "kp": "颈动脉支架围术期卒中处理", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (1)头颈部", "ex": "【为什么对】支架术后急性神经功能缺损提示远端栓塞或支架内急性血栓，应尽快复查DSA明确并争取动脉内溶栓或取栓，B正确。\n【为什么错】A继续观察延误治疗；C擅自出院风险极高；D头颅平片对急性缺血无诊断价值；E等待自行恢复将错失治疗窗口。", "tr": "颈动脉介入围术期卒中“快速复查DSA＋血管内再通”是处理核心。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1107", "t": "案例分析题", "s": "患者女，65岁，2型糖尿病病史10年，合并轻度肾功能不全（血肌酐140μmol/L，eGFR约55ml/min），因下肢动脉硬化闭塞症需行下肢动脉DSA及介入治疗。患者平时服用二甲双胍控制血糖，术前应重点评估造影剂肾损伤风险，并与临床沟通围术期用药方案，评估二甲双胍是否需暂停。为预防对比剂肾病，应采取的正确措施是", "o": {"A": "术前不做任何评估直接造影", "B": "术前充分水化，选用等渗或低渗非离子型对比剂并尽量减量，术后监测肾功能，按医嘱调整二甲双胍用药时机", "C": "使用大剂量高渗离子型对比剂", "D": "术前使用利尿剂脱水以减轻肾脏负担", "E": "术后立即进行剧烈运动促进对比剂排泄"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-107", "kp": "对比剂肾病预防措施", "ch": "十一、DSA检查技术 → 1.检查前准备 → (1)适应证禁忌证及并发症", "ex": "【为什么对】高危患者术前应充分水化，选用肾毒性小的等渗或低渗非离子型对比剂并尽量减量，术后监测肾功能，并根据肾功能情况调整二甲双胍用药，B正确。\n【为什么错】A不做评估风险高；C大剂量高渗对比剂加重肾损伤；D利尿脱水反而有害；E剧烈运动无益且有风险。", "tr": "糖尿病＋肾功能不全＝CIN高危，“水化＋减量＋等渗剂”是三大防线。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1108", "t": "案例分析题", "s": "患者男，52岁，乙肝肝硬化病史，增强CT示肝右叶单发肝癌，拟行TACE治疗。术中造影发现肝右叶肿瘤主要由肝右动脉分支供血，需将微导管超选择性插管至肿瘤供血分支，尽量避免损伤正常肝组织。该技术可将造影后的血管路径图叠加于实时透视图像上，实时显示导管导丝与血管的关系。为实时引导导丝、导管准确超选，应采用的DSA技术是", "o": {"A": "路标技术（road mapping）", "B": "能量减影", "C": "混合减影", "D": "单帧静态采集", "E": "心电门控采集"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-108", "kp": "路标技术引导超选", "ch": "十一、DSA检查技术 → 2.DSA成像方式与操作技术 → 成像方式", "ex": "【为什么对】路标技术将造影后的血管路径图与实时透视叠加，介入操作中能直观显示导管导丝与血管关系，是超选择性插管的经典引导技术，A正确。\n【为什么错】B、C为诊断用减影方式；D静态图像无实时引导作用；E心电门控用于减少心脏搏动伪影。", "tr": "介入超选引导靠“路标”，路标属时间减影的实时应用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1109", "t": "案例分析题", "s": "患者女，30岁，近期血压明显升高，多种降压药物联合治疗效果差，DSA确诊右肾动脉开口部重度狭窄（约85%），考虑为动脉粥样硬化性病变，药物治疗效果不佳，无明确手术禁忌。拟行经皮肾动脉介入治疗（球囊扩张及必要时置入支架），术中需持续监测血压与肾功能变化，并备好球囊、支架及压力泵等材料。正确的技术方案是", "o": {"A": "先肾动脉造影明确狭窄，再行球囊扩张并必要时置入支架，术后造影复查确认血流通畅", "B": "直接置入支架，不需先行造影", "C": "先行全脑血管造影评估", "D": "支架置入后不需复查造影", "E": "术中不需造影引导，透视下盲放"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-109", "kp": "肾动脉介入技术方案", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (4)腹部", "ex": "【为什么对】肾动脉介入遵循“造影明确—球囊扩张—必要时支架—术后复查造影”的规范流程，全程造影引导并监测血压，A正确。\n【为什么错】B、E不经造影盲目操作易损伤血管；C脑血管造影与肾动脉病变无关；D术后必须复查确认疗效与并发症。", "tr": "肾动脉介入全程造影引导，支架后复查是疗效确认的必需步骤。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-1110", "t": "案例分析题", "s": "患者男，58岁，骨盆骨折卧床1周后突发呼吸困难、胸痛、低氧血症，D-二聚体显著升高，床旁超声提示右心扩大，高度怀疑急性肺栓塞。因合并严重肾功能不全不宜行CTPA，临床拟行肺动脉造影明确诊断，需经右心系统插管至肺动脉。造影过程应持续心电监护、监测血氧并备好抢救设备，注意患者屏气配合。关于肺动脉造影技术的正确描述是", "o": {"A": "经股静脉右心导管将导管置于肺动脉，高压注射器注射对比剂后快速采像，观察肺动脉腔内充盈缺损", "B": "经股动脉逆行插管至肺动脉", "C": "手推小剂量对比剂即可完成", "D": "不需插管，直接经静脉注射对比剂", "E": "肺动脉造影不能诊断肺栓塞"}, "d": "中", "c": "分析", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-110", "kp": "肺动脉造影技术", "ch": "十一、DSA检查技术 → 3.人体各部位DSA检查技术 → (2)胸部", "ex": "【为什么对】肺动脉造影经股静脉右心系统将导管置于肺动脉主干，高压注射器注射对比剂后快速采像，充盈缺损为肺栓塞的直接征象，A正确。\n【为什么错】B动脉途径无法到达肺动脉；C手推小剂量无法使肺动脉良好显影；D不插管则对比剂稀释严重；E肺动脉造影曾是诊断金标准。", "tr": "肺动脉造影＝股静脉右心插管＋高压团注＋高帧率采像。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U11-9101", "t": "单选题", "s": "目前诊断颅内动脉瘤的\"金标准\"检查是", "o": {"A": "3D-DSA（旋转 DSA 三维重建）", "B": "头颅 CT 平扫", "C": "头颅 MRI 平扫", "D": "颈部血管超声", "E": "颅骨 X 线平片"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "KP-BU-11-9101-正高", "kp": "颅内动脉瘤金标准", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → (补充)脑血管DSA", "ex": "【为什么对】A 正确：DSA（尤其旋转采集的三维 DSA）空间分辨率高、可显示瘤颈与载瘤动脉关系，是诊断颅内动脉瘤的金标准，也是介入栓塞治疗的基础。【为什么错】B、C 对动脉瘤显示有限（CTA/MRA 为无创筛查）；D 无法显示颅内动脉；E 无诊断价值。", "tr": "CTA/MRA 是无创筛查首选，但\"金标准\"仍是 DSA。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U11-9102", "t": "单选题", "s": "关于冠状动脉 DSA 的投照角度，下列说法错误的是", "o": {"A": "左前斜（LAO）有助于显示前降支近段", "B": "右前斜（RAO）有助于显示右冠状动脉", "C": "头位（CRAN）有助于显示心尖部", "D": "足位（CAUD）有助于显示膈面心肌", "E": "单纯前后位（AP）即可清晰显示所有冠状动脉分支"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "KP-BU-11-9102-正高", "kp": "冠状动脉DSA投照角度", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → (补充)冠状动脉DSA", "ex": "【为什么对】E 错误：心脏在胸腔内呈斜位，单纯 AP 位各分支相互重叠、显示差，必须结合 LAO/RAO 及头位/足位等多角度投照。【为什么错】A、B、C、D 均为冠状动脉 DSA 常用且正确的投照体位描述。", "tr": "冠脉 DSA 强调多角度投照，单纯 AP 位因重叠而不可用。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U11-9103", "t": "单选题", "s": "欲显示股浅动脉远端及腘动脉、小腿动脉，下肢动脉 DSA 的穿刺入路首选", "o": {"A": "对侧股动脉（翻山技术）或同侧顺行穿刺", "B": "肱动脉穿刺", "C": "颈动脉穿刺", "D": "腋动脉穿刺", "E": "足背动脉穿刺"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "KP-BU-11-9103-正高", "kp": "下肢动脉DSA入路", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → (补充)下肢动脉DSA", "ex": "【为什么对】A 正确：经股动脉入路（同侧顺行或对侧\"翻山\"）是下肢动脉 DSA 最常用、最稳妥的路径，导管易于到达股浅、腘及小腿动脉。【为什么错】B 肱动脉常用于上肢/主动脉弓；C、D 不用于下肢；E 太远端、不适合作为造影入路。", "tr": "下肢动脉造影首选股动脉入路，而非肱动脉或颈部入路。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "补充", "mk": 0}, {"id": "ZG-U11-9104", "t": "多选题", "s": "关于间接门静脉造影（经动脉门静脉成像）的插管与造影，下列说法正确的有", "o": {"A": "导管置于脾动脉或肠系膜上动脉", "B": "注入对比剂后于门静脉期显示门静脉主干及分支", "C": "可评估门静脉高压的侧支循环", "D": "直接经皮穿刺门静脉", "E": "可用于 TIPS 术前评估"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "KP-BU-11-9104-正高", "kp": "间接门静脉造影", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术 → (补充)门静脉系统DSA", "ex": "【为什么对】A、B、C、E 正确：间接法将导管置于脾动脉或肠系膜上动脉，注入对比剂后对比剂经毛细血管到达门静脉、在门静脉期显影，可评估门脉高压侧支及 TIPS 适应证。【为什么错】D 错误：直接穿刺门静脉属于直接门静脉造影/穿刺技术，非\"间接\"法。", "tr": "区分\"间接法\"（动脉插管）与\"直接法\"（穿刺门脉）；D 为直接法。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "补充", "mk": 1}, {"id": "ZG-U11-9201", "t": "单选题", "s": "DSA 检查中，动脉插管最常选用的入路是", "o": {"A": "股动脉（Seldinger 技术）", "B": "肱动脉切开", "C": "颈内静脉", "D": "桡动脉仅用于采血", "E": "足背动脉"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-9201", "kp": "DSA入路", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术", "ex": "【为什么对】DSA 动脉插管最常用股动脉穿刺（Seldinger 技术），操作简便、血管粗直。\n【为什么错】肱/桡等可作替代但非首选。", "tr": "股动脉Seldinger是最常用DSA入路。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U11-9202", "t": "单选题", "s": "关于 DSA 对比剂注射，正确的是", "o": {"A": "对比剂浓度与流率需依靶血管调整", "B": "所有部位统一高浓度高流率", "C": "流率越低越好", "D": "无需考虑注射器加热", "E": "浓度越低越好"}, "d": "中", "c": "理解", "m": "专业实践能力", "u": "十一", "un": "DSA检查技术", "kpid": "UNIT-11-DSA-9202", "kp": "DSA注药参数", "ch": "十一、DSA检查技术 → 2.人体各部位DSA检查技术", "ex": "【为什么对】DSA 对比剂浓度、总量与流率需根据靶血管粗细与检查部位个体化调整，以获得良好信噪比。\n【为什么错】统一参数会造成过曝或显影不良。", "tr": "DSA注药参数需个体化。", "bk": "正高", "ref": {"篇": "影像技术专业实践能力", "章": "DSA检查技术", "节": "人体各部位DSA检查技术", "页": 327}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U12-0101", "t": "单选题", "s": "图像存档与传输系统（PACS）的基本组成通常不包括下列哪一项", "o": {"A": "数字影像采集设备与采集接口（含 DICOM 网关、胶片数字化仪）", "B": "影像存储与归档子系统（含数据库及分级存储设备）", "C": "承担影像与信息传输的通讯网络与网络设备", "D": "影像显示、后处理与打印输出的各类工作站", "E": "医院财务收费与结算子系统"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-001", "kp": "PACS 的基本组成", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (2)构架与工作流程", "ex": "【为什么对】E 为本题答案。财务收费与结算属于医院信息系统（HIS）的功能模块，不属于 PACS 的组成部分。PACS 与 HIS 之间通过 HL7 等接口交换文本信息，但两者是相互独立又互相集成的系统。【为什么错】A、B、C、D 均为 PACS 的组成要素：影像采集子系统负责把各类成像设备的影像纳入系统（含对非 DICOM 设备的网关转换与旧胶片的数字化）；存储与归档子系统含数据库服务器与在线/近线/离线分级存储；通讯网络是各部分互联的基础；显示与处理工作站是影像调阅、诊断与后处理的终端。此外，系统软件与数据库管理软件通常也被列为 PACS 的组成之一。", "tr": "HIS、RIS、PACS 的功能边界是本单元的基础考点：HIS 管全院业务与费用，RIS 管放射科的登记、预约、报告与流程，PACS 管影像的采集、存储、传输与显示。三者集成但不可混为一谈。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0102", "t": "多选题", "s": "PACS 中数字影像的采集途径包括下列哪些方式", "o": {"A": "通过 DICOM 网络接口从符合 DICOM 标准的成像设备直接接收影像，这是最理想、信息最完整的采集方式", "B": "对仅提供模拟视频输出的老旧设备，使用视频帧捕获卡数字化后再封装为 DICOM 格式", "C": "使用胶片数字化仪（激光扫描或 CCD 扫描）把既往胶片转换为数字影像纳入系统", "D": "通过 DICOM 网关对不完全符合标准的设备做协议转换与信息补全，如补入患者 ID、检查号等", "E": "直接从 HIS 数据库中读取并提取影像像素数据"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-002", "kp": "PACS 数字影像采集方式", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (3)数字影像采集", "ex": "【为什么对】A 正确：设备原生输出 DICOM 对象，像素数据与患者、检查、序列等元数据一并传输，信息最完整、失真最小。B 正确：帧捕获属于\"模拟转数字\"的过渡方案，影像质量受视频链路限制（通常仅 8 bit 灰阶），且元数据需另行补入，只在无法更新设备时采用。C 正确：胶片数字化仪用于既往资料回顾性入库，同样存在动态范围与分辨率损失。D 正确：DICOM 网关（gateway/broker）承担协议适配、字符集转换、标签补全与路由分发职能，是异构环境集成的关键部件。【为什么错】E 错误：HIS 存储的是医嘱、费用、病历文书等文本类结构化信息，不保存影像像素数据；PACS 与 HIS 之间通过 HL7 交换文本信息，影像数据不经由 HIS 流转。", "tr": "采集方式的\"优劣次序\"是命题点：DICOM 直连＞DICOM 网关转换＞帧捕获＞胶片数字化。后两种都存在不可逆的信息损失，只应作为过渡手段。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的发展与组成", "页": 343}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0103", "t": "单选题", "s": "某院一台 CT 平均每例检查产生 800 幅图像，矩阵 512×512、每像素 16 bit，按不压缩方式存储。若每日完成 60 例 CT 检查，该设备一天产生的影像数据量约为", "o": {"A": "约 0.5 GB", "B": "约 5 GB", "C": "约 25 GB", "D": "约 50 GB", "E": "约 500 GB"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-003", "kp": "PACS 影像存储容量估算", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】C 正确。单幅图像=512×512×2 字节=524288 字节≈0.5 MB；每例 800 幅≈400 MB；每日 60 例≈24000 MB≈23.4 GB，约 25 GB。【为什么错】A 相当于只算了一幅图像的量级。B 相当于漏算了一个数量级（如把 800 幅误作 80 幅）。D 相当于把单幅按 1 MB 估算（即误用 32 bit 或矩阵取 1024×512）。E 高估约 20 倍，与实际相差过大。", "tr": "必须记住几个基准值：CT/MR 单幅 512×512×16 bit≈0.5 MB；CR/DR 单幅（约 2048×2500×16 bit）≈10 MB；数字乳腺单幅可达数十 MB。此外 DICOM 文件还含头信息、且实际容量规划应在纯像素量基础上乘以冗余与增长系数。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的发展与组成", "页": 343}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0104", "t": "多选题", "s": "有关 PACS 影像存储的分级存储管理与预取策略，下列表述正确的有", "o": {"A": "在线存储通常采用高速磁盘阵列（RAID），存放近期与高频调阅的影像，响应速度快", "B": "近线存储采用光盘库、磁带库或低成本大容量磁盘，存放调阅频率较低的历史影像，调阅时需要一定等待时间", "C": "离线存储的介质脱离系统在库房保管，调阅时需要人工装载等干预", "D": "预取机制根据 RIS 的检查预约信息，在患者到达前把其历史影像自近线迁移至在线，以缩短医师调阅等待", "E": "系统采用了 RAID 冗余磁盘阵列后即等同于完成了数据备份，无须再建立异地备份"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-004", "kp": "分级存储管理与影像预取", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (6)影像管理", "ex": "【为什么对】A、B、C 正确：分级存储管理（HSM）按调阅概率把数据分布在不同成本与速度的介质上，在线保证即时调阅，近线兼顾容量与成本，离线用于长期法定保存。D 正确：预取是提升临床体验的关键机制，通过与 RIS 的预约信息联动实现\"人未到、片先到\"，也可按检查部位、时间跨度设置预取规则。【为什么错】E 错误：RAID 解决的是单块（或若干块）磁盘物理损坏时的数据可用性与业务连续性问题，无法防范误删除、逻辑损坏、病毒或勒索软件加密、机房火灾与整体损毁等风险。备份（尤其异地备份与容灾）与 RAID 分属不同层面的保障手段，二者不可互相替代。", "tr": "\"RAID 不等于备份\"是信息安全领域的经典判断。此外要注意，RAID 5 只能容忍一块盘故障，重建期间再坏一块即数据全失，大容量场景更推荐 RAID 6 或 RAID 10。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0105", "t": "单选题", "s": "有关 PACS 的系统构架与影像业务工作流程，下列描述正确的是", "o": {"A": "典型流程为：RIS 登记预约→设备经 Modality Worklist 获取患者与检查信息→采集图像→经 DICOM 存储服务发送至 PACS 归档→诊断工作站调阅并书写报告→报告回传 RIS 并向临床发布", "B": "浏览器/服务器（B/S）架构的最大优势是能提供最完整的高级三维后处理功能，故诊断工作站宜一律采用 B/S", "C": "集中式存储架构的主要优点在于各科室数据彼此独立、互不影响", "D": "PACS 与成像设备之间的图像传输通常采用 HL7 协议完成", "E": "影像归档完成后，设备端即可自行删除本地原始图像，无须任何确认机制"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-005", "kp": "PACS 系统构架与影像工作流程", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (2)构架与工作流程", "ex": "【为什么对】A 正确。这正是 IHE 预约工作流（SWF）所规范的标准影像业务链条，从患者登记、工作列表获取、图像采集与归档，到报告书写与发布形成闭环，各环节分别由 HL7 与 DICOM 事务衔接。【为什么错】B B/S 架构的价值在于免客户端安装、维护成本低、便于临床科室与移动终端广泛访问；高性能三维后处理与高负荷诊断阅片仍多依赖 C/S 专业工作站或服务器端渲染的胖客户端方案。C \"各科室数据彼此独立\"是分布式/科室级存储的特征，且往往形成信息孤岛，并非优点；集中式存储的优点恰恰是统一管理、便于共享、备份与统计。D 图像传输使用 DICOM 协议；HL7 用于 HIS/RIS 与 PACS 之间的患者、医嘱、报告等文本类信息交换。E 应通过存储确认（Storage Commitment）服务取得 PACS 明确的\"已永久保存\"应答后，设备端才可安全删除本地副本，否则存在数据丢失风险。", "tr": "\"DICOM 传图像、HL7 传文本、IHE 定流程\"是本单元三大标准的分工口诀，D 项正是利用这一分工设陷。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的发展与组成", "页": 343}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0106", "t": "案例分析题", "s": "某医院新建放射科拟接入院内 PACS，科室配置 2 台 CT、1 台 MR 与 4 台 DR。经测算，业务高峰时段（上午 9:00—11:00）平均每分钟需向 PACS 中心服务器上传约 900 MB 影像数据，同时诊断医师从服务器调阅历史影像的流量约为上传流量的一半。信息科需评估科室接入交换机的上联链路带宽是否足够。已知 1 字节=8 比特，且工程实践中链路的实际可用带宽通常只有理论带宽的 60%～70%。下列估算与结论最合理的是", "o": {"A": "高峰期总流量约 1350 MB/min，折合净需求约 180 Mbps；计入链路利用率后需约 260～300 Mbps 以上，千兆以太网上联可满足，百兆链路明显不足", "B": "高峰期净需求约 18 Mbps，百兆链路绰绰有余", "C": "高峰期净需求约 1350 Mbps，必须部署万兆链路才能满足", "D": "带宽需求只与联网设备数量相关，与数据量无关，4 台 DR 用百兆链路即可", "E": "只要对影像采用有损压缩，任何带宽都能满足需求，无须做评估"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-006", "kp": "PACS 网络带宽需求估算", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (4)通讯与网络", "ex": "【为什么对】A 正确。上传 900 MB/min 加下行调阅 450 MB/min，合计 1350 MB/min；换算为比特：1350×8=10800 Mb/min，除以 60 s 得 180 Mb/s（Mbps）。工程上按 60%～70% 的有效利用率折算，链路理论带宽需约 257～300 Mbps 以上，因此百兆（100 Mbps）链路不足，千兆（1000 Mbps）链路有充分余量，也为业务增长留出空间。【为什么错】B 少算了字节到比特的 8 倍换算。C 漏除以 60 s，把每分钟的比特数当成了每秒的速率。D 带宽需求由单位时间内传输的数据量决定，设备数量只是间接因素；4 台 DR 若并发上传，单幅约 10 MB 的图像同样可迅速占满百兆链路。E 诊断用影像原则上应采用无损压缩，有损压缩需经严格论证且不能作为规避带宽规划的理由；压缩也不改变必须做容量评估这一工程原则。", "tr": "\"MB/s 与 Mbps 差 8 倍\"\"每分钟与每秒差 60 倍\"是带宽计算题的两个经典陷阱，两处都错就会得出相差 480 倍的荒谬结论。此外规划时还应考虑突发峰值、备份流量与冗余链路。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0107", "t": "单选题", "s": "下列关于远程放射学（teleradiology）的描述，正确的是", "o": {"A": "远程放射学指通过通讯网络把影像资料由一地传送至另一地进行显示、会诊或书写报告，按工作方式可分为实时（在线）与存储转发（离线）两类", "B": "远程放射学只能用于疑难病例会诊，不能用于常规报告书写", "C": "远程放射学传输的图像可以不遵循 DICOM 标准，只要能在远端显示即可", "D": "远程放射学在本机构内部网络中进行，不涉及患者隐私保护问题", "E": "远程放射学的诊断质量取决于传输速度，与远端显示终端性能无关"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-001", "kp": "远程放射学的定义与分类", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】A 正确。远程放射学是远程医学在影像领域的应用，基本要素包括影像采集与数字化、传输网络、远端显示与诊断，以及信息安全保障。实时方式适合互动式会诊与术中即时判读，存储转发方式适合非急诊的批量报告，二者各有适用场景。【为什么错】B 远程放射学已广泛用于夜间值班、区域影像中心集中报告、基层机构报告外包与专科会诊，远不止疑难会诊。C 为保证像素数据、灰阶信息与患者元数据的完整性和跨系统互操作性，远程放射学应遵循 DICOM 标准传输与存储。D 只要涉及患者身份与影像数据的传输就存在隐私风险，无论院内院外都需加密传输、访问控制、审计留痕，对外交流还应做去标识化。E 远端显示器的分辨率、最大亮度、灰阶校准（DICOM GSDF）与阅片环境照度直接决定诊断可靠性，是远程放射学质量控制的关键环节。", "tr": "远程放射学的质量控制常被简化为\"网速够快就行\"。实际上\"传输链路+显示终端+阅片环境+资质与责任界定\"四个环节缺一不可，显示终端未做 GSDF 校准是最常被忽略的隐患。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0108", "t": "多选题", "s": "为保障 PACS 的系统安全与患者信息安全，下列措施中恰当的有", "o": {"A": "划分网络安全域，在 PACS 与外部网络之间部署防火墙，远程访问采用 VPN 加密通道", "B": "实行基于角色的权限管理，启用强口令策略与登录审计，对关键操作保留审计日志", "C": "建立数据备份与容灾体系，重要数据实施异地备份，并定期开展恢复演练", "D": "用于科研、教学与对外交流的影像先做去标识化处理，清除患者身份相关的 DICOM 标签", "E": "为便于科室内快速调阅，可让全科工作人员共用一个具有最高权限的账号登录系统"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-002", "kp": "PACS 系统安全与隐私保护措施", "ch": "十二、PACS技术 → 2.PACS运行 → (3)系统安全", "ex": "【为什么对】A 正确：网络分域与边界防护是防止外部攻击与横向渗透的基础。B 正确：最小权限原则与可追溯的审计日志是医疗信息系统安全管理的核心要求。C 正确：备份的价值只有在成功恢复时才体现，未经演练的备份不能视为有效备份。D 正确：去标识化应清除或替换患者姓名、ID、出生日期、机构信息等标签，同时注意\"烧录\"在像素中的文字信息也需处理。【为什么错】E 错误：共用高权限账号使所有操作无法追溯到具体责任人，审计日志形同虚设；一旦口令泄露即造成全系统暴露，严重违反最小权限原则与可追溯性要求，也不符合信息安全等级保护的基本规定。", "tr": "去标识化容易遗漏两处：一是超声、DSA 等设备把患者信息\"烧录\"进像素数据；二是私有标签与结构化报告中残留的身份信息。仅清空 Patient Name 标签并不等于完成匿名化。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0109", "t": "案例分析题", "s": "某院 PACS 上线后，技师反映部分检查在诊断工作站上出现\"同一患者被拆成两条记录\"或\"图像挂到了另一位患者名下\"。排查发现：急诊患者常先以临时 ID 完成检查、事后再补录正式住院号；部分设备未接入检查工作列表，技师需在设备控制台手工输入姓名与 ID，存在录入差错；另有一台老设备的检查号编码规则与 RIS 不一致。作为科室技术骨干，需要提出系统性整改方案。下列措施组合最恰当的是", "o": {"A": "全面接入 Modality Worklist 使设备自动从 RIS 获取患者与检查信息以取代手工录入；建立主患者索引并规范临时 ID 向正式 ID 的合并流程；统一各设备的检查号与 AE 配置规则；对已产生的错挂影像使用 PACS 的患者/检查信息核对与合并功能（对应 IHE 患者信息核对流程）予以纠正", "B": "要求技师手工录入时更加仔细，通过加强责任心教育解决即可", "C": "把所有出错的检查记录直接删除，通知患者重新来院检查", "D": "在诊断工作站上人工修改图像中显示的患者姓名文字标注，使之与病历一致", "E": "关闭 Modality Worklist，全部改为手工录入，以保证各设备录入口径一致"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-003", "kp": "HIS/RIS/PACS 集成与患者信息一致性", "ch": "十二、PACS技术 → 2.PACS运行 → (4)与HIS/RIS集成", "ex": "【为什么对】A 正确。患者信息错误的根源有三：手工录入、临时身份未合并、编码规则不统一，整改必须同时覆盖。Modality Worklist 让设备从 RIS 拉取权威的患者与检查信息，从源头消除手工录入差错；主患者索引（MPI）与临时 ID 合并流程解决同一患者多身份问题；统一 AE 与检查号规则保证影像正确归位；对存量错误则使用 PACS 的信息核对与合并功能修正，这一场景正对应 IHE 的患者信息核对（PIR）集成模式。【为什么错】B 手工录入差错是流程性缺陷而非单纯态度问题，仅靠教育无法根治，也无法解决临时 ID 与编码不一致。C 删除后重新检查使患者承受额外辐射与费用，且属可修复的信息层面问题，不应以重复检查作为解决手段。D 修改显示层的文字标注不改变 DICOM 标签与数据库记录，属于掩盖问题，还可能造成图像与记录不符的医疗风险。E 方向完全相反，关闭工作列表会使手工录入差错进一步增加。", "tr": "Modality Worklist 的核心价值不是\"省事\"，而是保证患者身份与检查信息的唯一权威来源。凡遇到\"患者信息错乱\"类案例题，首选答案基本都指向 MWL 接入与主索引管理。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0110", "t": "单选题", "s": "某院在制定 PACS 灾难恢复方案时明确要求：系统中断后最长 4 小时内须恢复业务，且最多允许丢失 15 分钟的数据。这两项要求分别对应的指标是", "o": {"A": "RTO=4 小时、RPO=15 分钟；RTO 决定恢复速度与备用系统就绪程度，RPO 决定数据同步或备份的频率", "B": "RPO=4 小时、RTO=15 分钟", "C": "两者都属恢复时间目标，分别为上限值与下限值", "D": "两者都属平均无故障时间（MTBF）指标", "E": "两者与备份策略无关，只是管理层提出的口号"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-004", "kp": "RTO 与 RPO 在 PACS 灾备中的应用", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】A 正确。恢复时间目标（RTO）指从系统中断到业务恢复可容忍的最长时间，直接决定备用系统采用热备、温备还是冷备；恢复点目标（RPO）指可容忍丢失的数据所对应的时间跨度，RPO=15 分钟意味着数据复制或增量备份间隔不得超过 15 分钟，通常需要近实时的数据同步机制。两项指标共同决定灾备架构的技术路线与投入规模。【为什么错】B 两个概念被完全对调。C RTO 与 RPO 是两个不同维度的指标，一个针对恢复时间、一个针对数据丢失量，不是同一指标的上下限。D MTBF 描述设备硬件的可靠性水平，与灾难恢复目标无关。E RTO 与 RPO 是可量化、可验收、可通过演练验证的技术指标，是灾备方案设计与招标的核心依据。", "tr": "区分口诀：RTO 看\"多久能用\"（时间维度），RPO 看\"丢多少数据\"（数据维度）。RPO 越小对同步频率与带宽要求越高，RTO 越小对备用资源投入要求越高，二者都会显著推高成本，需按业务重要性分级设定。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0111", "t": "多选题", "s": "某台新安装的 DR 无法将图像发送至 PACS，控制台提示\"关联建立失败\"。下列排查思路与操作正确的有", "o": {"A": "先用 C-ECHO（验证服务）测试双方能否建立 DICOM 关联，这是最基本的连通性验证手段", "B": "核对双方配置的 AE Title、IP 地址与端口号是否完全一致（AE Title 区分大小写），并确认 PACS 端已把该设备的 AE Title 加入允许列表", "C": "检查关联协商时双方是否存在共同支持的表示上下文，即所需 SOP Class 与传输语法是否匹配，可查阅厂商的 DICOM 一致性声明加以核对", "D": "检查防火墙是否放行所用的 DICOM 端口，以及网络路由与 VLAN 划分是否可达", "E": "DICOM 关联建立失败通常由 HL7 消息格式错误引起，应优先检查 HL7 接口的字段与分隔符配置"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-005", "kp": "DICOM 通讯故障的排查思路", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】A 正确：C-ECHO 只验证关联能否建立与基本响应，开销小、干扰小，是排查的第一步。B 正确：AE Title 是 DICOM 应用实体的逻辑标识（长度不超过 16 个字符且区分大小写），必须与 IP、端口三者配套一致，且服务端通常按 AE Title 做访问控制。C 正确：即使网络通、AE 配对正确，若双方在关联协商中找不到共同的抽象语法（SOP Class）与传输语法组合，关联仍会被拒绝；一致性声明是判断能否互通的权威依据。D 正确：DICOM 常用端口（如 104、11112）被防火墙拦截或跨 VLAN 不可达，都会表现为关联失败。【为什么错】E 错误：图像发送走的是 DICOM 上层协议（DIMSE over TCP/IP），与 HL7 无关。HL7 负责 HIS/RIS 与 PACS 之间的文本类信息交换，其故障表现为患者信息、医嘱或报告不同步，而不会导致 DICOM 关联建立失败。", "tr": "排查次序应\"由下而上\"：物理与 IP 连通（ping）→端口可达（telnet）→DICOM 关联（C-ECHO）→表示上下文匹配（一致性声明）→具体服务（C-STORE）。跳过前面的层次直接怀疑应用层配置往往事倍功半。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0112", "t": "单选题", "s": "医用诊断级灰阶显示器的质量控制中，用于规范其亮度响应特性的 DICOM 标准部分及相应函数是", "o": {"A": "DICOM PS3.14 所定义的灰度标准显示函数（GSDF），使显示器在全亮度范围内实现视觉上近似均匀的灰阶感知", "B": "DICOM PS3.3 所定义的信息对象定义（IOD）", "C": "DICOM PS3.4 所定义的服务类规范", "D": "DICOM PS3.10 所定义的介质存储与文件格式", "E": "DICOM PS3.15 所定义的安全与系统管理配置"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-OPS-006", "kp": "医用显示器与 DICOM GSDF 校准", "ch": "十二、PACS技术 → 2.PACS运行 → (1)管理", "ex": "【为什么对】A 正确。DICOM PS3.14 定义的灰度标准显示函数以人眼对比敏感度模型为基础，把数字驱动值映射为显示亮度，使相邻灰阶之间的亮度差在整个动态范围内对应大致相等的\"恰可察觉差\"，从而保证同一幅图像在不同显示器上具有一致的视觉表现。诊断级显示器须用光度计定期做 GSDF 一致性校准，并检查最大亮度、亮度均匀性、暗室反射与环境照度。【为什么错】B PS3.3 规定各类信息对象（如 CT Image IOD、MR Image IOD）的数据结构。C PS3.4 规定各服务类（存储、查询/检索、打印管理等）的行为。D PS3.10 规定 DICOM 文件格式与介质存储（含 128 字节前导与\"DICM\"标识）。E PS3.15 规定安全配置文件与系统管理。上述各部分内容均与灰阶显示函数无关。", "tr": "PS3.14 是与技师日常工作最相关的 DICOM 部分之一。要点记忆：GSDF 保证\"跨显示器一致\"，而非\"图像更亮更好看\"；未经校准的显示器即使亮度很高，低对比病灶仍可能被漏诊。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0113", "t": "单选题", "s": "有关 DICOM 标准的起源与发展历程，下列描述正确的是", "o": {"A": "DICOM 由美国放射学会（ACR）与美国国家电气制造商协会（NEMA）联合制定，前身为 ACR-NEMA 1.0 与 2.0；1993 年发布的 3.0 版引入网络传输与面向对象的信息模型，此后以增补件形式持续更新", "B": "DICOM 由国际标准化组织（ISO）独立制定，第一版发布于 1985 年并沿用至今未作修改", "C": "DICOM 3.0 仅规定医学图像的文件格式，不涉及网络通讯内容", "D": "DICOM 与 HL7 是同一组织制定的同一套标准的两个组成部分", "E": "DICOM 标准自 3.0 版发布后即处于冻结状态，不再新增内容"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-001", "kp": "DICOM 标准的起源与版本演进", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确。为解决不同厂家设备影像格式互不兼容的问题，ACR 与 NEMA 于 1983 年成立联合委员会，1985 年发布 ACR-NEMA 1.0、1988 年发布 2.0（均基于点对点专用连接），1993 年发布 DICOM 3.0，确立了基于 TCP/IP 的网络通讯、面向对象的信息模型（IOD）与服务-对象对（SOP）机制，并采用多部分文档结构，以增补件（Supplement）与勘误件（CP）方式持续演进。【为什么错】B DICOM 由 ACR 与 NEMA 主导制定，并非 ISO 独立制定；且标准一直在更新。C DICOM 3.0 的核心突破恰恰是网络通讯部分（PS3.7、PS3.8），文件格式（PS3.10）只是其中一部分。D HL7 由独立的 Health Level Seven International 组织制定，与 DICOM 是两套面向不同信息类型的标准，虽有协作但并非同一套标准。E DICOM 一直在增补新的 SOP Class、传输语法与工作流内容（如结构化报告、剂量报告、增强多帧对象、全片数字病理等），从未冻结。", "tr": "记住时间轴：1985 年 ACR-NEMA 1.0、1988 年 2.0、1993 年 DICOM 3.0。命题常把 1985 年说成 DICOM 首版发布年份，或把制定组织换成 ISO/IEC/WHO 等设陷。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0114", "t": "多选题", "s": "关于 DICOM 主要服务类及其功能的对应关系，下列表述正确的有", "o": {"A": "C-STORE 用于把影像等 SOP 实例由服务类用户（SCU）传送到服务类提供者（SCP），是影像归档与转发的基础", "B": "C-FIND 用于按患者、检查、序列、图像四级层次查询符合条件的记录；C-MOVE 用于请求把指定对象发送到第三方目的应用实体", "C": "C-ECHO 属验证服务类，用于测试通讯双方能否建立 DICOM 关联，俗称\"DICOM ping\"", "D": "存储确认（Storage Commitment）用于由存储方向发送方确认对象已被永久保存，发送方据此可安全删除本地副本", "E": "Modality Worklist 用于设备在检查完成后向 RIS 报告检查已开始或已结束的执行状态"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-002", "kp": "DICOM 服务类与 DIMSE 服务", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确：C-STORE 是存储服务类的核心操作，设备发送图像、PACS 接收归档即由其完成。B 正确：C-FIND 实现分层查询，C-MOVE 由请求方指定目的 AE、由被请求方发起 C-STORE 把数据送达第三方（若要求送回请求方自身则用 C-GET）。C 正确：C-ECHO 只做关联与响应验证，是安装调试与故障排查的首选工具。D 正确：存储确认解决\"发出去的图像是否被可靠归档\"的问题，是设备端安全清理本地存储的前提。【为什么错】E 错误：向 RIS 报告检查开始、完成或终止等执行状态的是 MPPS（Modality Performed Procedure Step，已执行检查步骤）服务；Modality Worklist（MWL）则是设备在检查前从 RIS/PACS 查询获取当日预约患者与检查信息的服务。二者一前一后配合构成完整工作流，功能不可互换。", "tr": "MWL 与 MPPS 的\"前后关系\"是高频考点：MWL 在检查前\"取任务\"，MPPS 在检查中与检查后\"报状态\"。另需分清 C-MOVE 与 C-GET：前者数据在新建的关联中送往第三方，后者在同一关联内返回给请求方。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0115", "t": "单选题", "s": "就 DICOM 中信息对象定义（IOD）、SOP Class、SOP Instance、UID 与 AE Title 之间的关系而言，下列描述正确的是", "o": {"A": "IOD 是对现实世界对象的抽象数据模型；SOP Class 由 IOD 与 DIMSE 服务组合而成并以 SOP Class UID 标识其类型；每个具体对象（如一幅图像）则由全局唯一的 SOP Instance UID 标识", "B": "SOP Class UID 与 SOP Instance UID 含义相同，在配置时可以互相替代", "C": "UID 可由使用者自行编写任意字符串，只要在本院范围内不重复即可", "D": "AE Title 是设备 IP 地址的另一种书写形式，配置时二者取其一即可", "E": "IOD 所描述的是 DICOM 网络通讯协议的分层结构"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-003", "kp": "IOD、SOP Class/Instance、UID 与 AE Title", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确。DICOM 采用面向对象思想：IOD 规定某类现实对象（患者、检查、CT 图像等）应包含哪些模块与属性；把 IOD 与作用于其上的 DIMSE 服务（如存储、查询）配对即构成服务-对象对类（SOP Class），用 SOP Class UID 标识类型，例如 CT 图像存储对应 1.2.840.10008.5.1.4.1.1.2；每一次生成的具体对象则获得一个全球唯一的 SOP Instance UID，用于唯一定位该实例。【为什么错】B 两者层级不同：同一类的成千上万幅图像共享同一个 SOP Class UID，而各自拥有互不相同的 SOP Instance UID，不可互换。C UID 要求全球唯一，由注册获得的组织根 UID 加机构自定义后缀构成，只允许数字与小数点、总长不超过 64 个字符，其中 1.2.840.10008 为 DICOM 标准专用根，不得自行占用。D AE Title 是应用实体的逻辑名称（不超过 16 个字符、区分大小写），与 IP 地址、端口号共同构成 DICOM 通讯三要素，三者缺一不可。E 网络通讯的分层与协议由 PS3.7（消息交换）与 PS3.8（网络支持）规定，IOD 描述的是信息对象的属性构成。", "tr": "DICOM 的四级信息层次\"患者-检查-序列-实例\"与 UID 的层次相对应：Study Instance UID、Series Instance UID、SOP Instance UID 逐级唯一。把 SOP Class UID 误当作可用于定位单幅图像的标识，是本考点最典型的错误。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0116", "t": "案例分析题", "s": "某院新增一台 MR 设备并接入 RIS 的检查工作列表。上线后技师反映两个问题：其一，在设备控制台按\"患者姓名\"查询时经常查不到已登记的患者，但改按\"检查日期\"查询则可看到当天全部预约；其二，部分从工作列表选取患者并完成的检查，RIS 中的检查状态仍停留在\"已预约\"，未自动变为\"已完成\"，需人工干预。设备与 PACS 之间的图像存储与归档一切正常。作为科室技术骨干，对这两个问题的分析与处理，下列最恰当的是", "o": {"A": "前者多为查询关键字匹配问题（中文字符集协商不一致、姓名书写格式差异或通配符使用不当），应核对双方字符集配置与查询条件设置；后者提示设备未启用或未正确配置 MPPS 服务，应开通 MPPS 并与 RIS 完成对接调试", "B": "两个问题均由网络带宽不足引起，应先升级科室上联链路", "C": "两个问题均因 PACS 存储空间不足所致，应优先扩容磁盘阵列", "D": "前者应关闭工作列表改为手工录入解决；后者只能靠技师在 RIS 中手工点击\"完成\"，没有技术手段可用", "E": "两者均由传输语法不匹配引起，把双方统一改为隐式 VR 小端传输语法即可解决"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-004", "kp": "Modality Worklist 与 MPPS 工作流问题排查", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确。按日期能查到、按姓名查不到，说明网络连通与 MWL 服务本身正常，问题出在查询关键字的匹配环节：常见原因是设备与 RIS 之间的特定字符集（如 GB18030/ISO_IR 100 等）协商不一致导致中文姓名乱码或不匹配、姓名分隔符与书写格式差异，以及未使用通配符做模糊匹配。第二个问题是典型的 MPPS 缺失表现——MWL 只负责\"取任务\"，检查开始与完成的状态回报需要 MPPS 服务，未配置时 RIS 自然无法自动更新状态。【为什么错】B 带宽不足会表现为传输缓慢或超时，而非按某一字段查不到、状态不回传，且题干明确图像归档正常。C 存储空间不足会导致归档失败或告警，与工作列表查询和状态回传无关。D 关闭工作列表会重新引入手工录入差错，方向错误；状态回传恰恰有成熟的 MPPS 技术方案可用。E 传输语法不匹配会导致关联协商失败或图像无法存储，而本例图像存储正常，可排除。", "tr": "MWL 与 MPPS 常被混为\"工作列表功能\"。实际招标与验收时应分别列明：设备须支持 MWL SCU（取任务）与 MPPS SCU（报状态），只支持前者会造成 RIS 流程状态长期依赖手工维护。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0117", "t": "多选题", "s": "涉及 DICOM 传输语法、图像压缩与介质交换的下列表述中，正确的有", "o": {"A": "传输语法规定数据元素的字节序、值表示（VR）为显式或隐式以及像素数据的编码方式，其中隐式 VR 小端（1.2.840.10008.1.2）是默认传输语法", "B": "JPEG Lossless 与 JPEG 2000 无损模式属无损压缩，解压后像素与原始数据完全一致，压缩比一般约为 2:1～3:1", "C": "JPEG 2000 有损模式可获得更高压缩比，但造成不可逆的信息损失，用于诊断存档须经严格论证", "D": "用于介质交换（CD/DVD/U 盘）的 DICOM 数据集在介质根目录设有 DICOMDIR 文件，按患者-检查-序列-图像四级层次索引介质中的对象", "E": "通讯双方只要网络可达即可直接传输压缩图像，无须在关联协商阶段就传输语法达成一致"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-DICOM-005", "kp": "DICOM 传输语法、压缩方式与 DICOMDIR", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】A 正确：隐式 VR 小端是所有 DICOM 实现都必须支持的默认传输语法，因而是协商失败时可退回的\"最小公分母\"；显式 VR 小端为 1.2.840.10008.1.2.1。B 正确：无损压缩保证像素完全可逆，医学影像因噪声成分较多，无损压缩比通常有限。C 正确：有损压缩可达 10:1 以上，但属不可逆处理，是否用于诊断与长期存档须结合部位、诊断任务与法规要求论证，一般原则是诊断用图像优先采用无损压缩。D 正确：DICOMDIR 采用介质存储目录存储 SOP Class，为离线介质提供层次化索引，使阅读软件无须扫描全部文件即可列出内容。【为什么错】E 错误：DICOM 建立关联时必须协商表示上下文（抽象语法即 SOP Class，加上一个或多个传输语法）；若接收方不支持发送方使用的压缩传输语法，该表示上下文会被拒绝，此时需退回到双方共同支持的传输语法，或由网关做转码后再转发。", "tr": "\"网络通了就一定能传图\"是常见误判。传输语法协商失败是临床上排查 DICOM 互通问题的高频原因，尤其在一端使用 JPEG 2000 压缩而另一端只支持非压缩语法时，必须查阅一致性声明确认交集。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0118", "t": "单选题", "s": "有关 HL7 标准的下列描述中，正确的是", "o": {"A": "HL7 是面向 OSI 参考模型第七层（应用层）的医疗信息交换标准，主要用于患者管理、医嘱、检验与报告等文本类信息交换；其 v2.x 消息由段、字段、组分构成，以竖线等分隔符分隔，MSH 为消息头段", "B": "HL7 的主要用途是医学图像的存储与网络传输", "C": "HL7 名称中的\"7\"指该标准由 7 个部分组成", "D": "HL7 与 DICOM 的功能完全重叠，医院只需部署其中一种即可", "E": "HL7 v2.x 采用 XML 格式编码，v3 则采用竖线分隔的纯文本格式"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-HL7-001", "kp": "HL7 标准的定位与消息结构", "ch": "十二、PACS技术 → 3.国际标准与规范 → (1)HL7", "ex": "【为什么对】A 正确。HL7 由 Health Level Seven International 组织制定，聚焦应用层的语义互操作。常用消息类型包括患者管理 ADT、医嘱 ORM、结果 ORU 等；v2.x 采用分隔符编码，一条消息由若干段组成，每段以三字母段标识开头（MSH 消息头、PID 患者标识、OBR 检查申请、OBX 观察结果等）。【为什么错】B 影像的存储与传输由 DICOM 承担，HL7 传递的是与影像相关的文本类信息。C \"Level Seven\"指 OSI 模型的第七层即应用层，与标准的部分数量无关。D 二者面向不同的信息类型、互为补充，PACS 环境中通常同时使用：HL7 完成 HIS/RIS 与 PACS 的信息同步，DICOM 完成影像的采集、传输与归档。E 描述颠倒：v2.x 以竖线分隔的纯文本编码为主（亦有可选的 XML 编码），v3 基于参考信息模型并采用 XML；新一代 FHIR 采用 REST 风格接口与 JSON/XML 资源表达。", "tr": "\"HL7 传文本、DICOM 传影像、IHE 定流程\"是本单元最实用的记忆框架。凡题干出现\"图像传不过去\"就应指向 DICOM，出现\"患者信息或申请单不同步\"才指向 HL7。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0119", "t": "多选题", "s": "下列关于 IHE（集成医疗企业）的表述，正确的有", "o": {"A": "IHE 由北美放射学会（RSNA）与美国医疗信息与管理系统学会（HIMSS）于 1998 年共同发起，旨在推动医疗信息系统之间的互操作", "B": "IHE 本身不制定新的通讯标准，而是规范如何组合运用 DICOM、HL7 等既有标准来解决具体的临床集成需求", "C": "IHE 技术框架的核心概念包括角色（Actor）、事务（Transaction）与集成模式（Integration Profile）", "D": "厂商可通过参加 IHE 连接测试（Connectathon）验证其产品与其他厂商系统的互操作性，并对外发布集成声明", "E": "IHE 属强制性国家标准，医疗机构采购设备时须符合其全部集成模式"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-IHE-001", "kp": "IHE 的性质、组织与核心概念", "ch": "十二、PACS技术 → 3.国际标准与规范 → (3)IHE", "ex": "【为什么对】A 正确：IHE 最初从放射学领域发起，后扩展到心血管、检验、护理、公共卫生等多个领域。B 正确：这是 IHE 与 DICOM、HL7 最本质的区别——它是\"标准的用法说明书\"，通过明确在何种场景下由哪个角色发起哪个事务，消除同一标准被不同厂商各自解读所造成的不兼容。C 正确：角色定义系统承担的功能职责，事务定义角色间基于标准的信息交换，集成模式则把若干角色与事务组织起来解决一个完整的临床问题。D 正确：Connectathon 是多厂商同场互连测试活动，通过后厂商可发布 IHE 集成声明，供医疗机构在采购时核查。【为什么错】E 错误：IHE 是行业自愿性的互操作框架，不具备强制法律效力；医疗机构应根据自身业务需要，在招标文件中明确要求支持哪些具体集成模式与角色，而非笼统要求\"符合全部\"。", "tr": "\"IHE 不制定标准\"是必考判断点。命题常写成\"IHE 制定了新的影像传输标准\"或\"IHE 取代了 DICOM\"来设陷，识别关键在于把握其\"整合既有标准\"的定位。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0120", "t": "单选题", "s": "IHE 放射科的预约工作流（Scheduled Workflow，SWF）集成模式规范了影像检查自登记到归档的完整链条，下列描述正确的是", "o": {"A": "SWF 涉及的角色包括患者登记（ADT）、医嘱下达者、医嘱执行者（RIS）、采集设备、影像管理与影像归档、影像显示等；其中患者与医嘱信息交换主要基于 HL7 消息，而工作列表查询、图像存储与存储确认基于 DICOM 服务", "B": "SWF 完全基于 HL7 实现，全过程不使用 DICOM 服务", "C": "SWF 的主要作用是规定影像的压缩算法与归档介质类型", "D": "SWF 仅适用于放射科内部流程，与患者登记（ADT）环节无关", "E": "实现 SWF 要求医院各系统必须采购自同一家厂商的产品"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-IHE-002", "kp": "IHE 放射科预约工作流 SWF", "ch": "十二、PACS技术 → 3.国际标准与规范 → (3)IHE", "ex": "【为什么对】A 正确。SWF 是 IHE 放射领域最基础、最核心的集成模式，把患者登记、医嘱下达、检查预约、工作列表获取、检查执行与状态回报、图像存储与存储确认、影像调阅等环节串成闭环。其中患者身份与医嘱类事务由 HL7 承担，工作列表（MWL）、执行步骤（MPPS）、图像存储（C-STORE）与存储确认（Storage Commitment）等由 DICOM 承担，两类标准在同一流程中分工协作。【为什么错】B 与事实不符，SWF 中的影像相关事务全部基于 DICOM。C 压缩算法与传输语法由 DICOM 规定，介质与归档策略属系统实现与管理层面，均非 SWF 的规范对象。D 患者登记（ADT）正是 SWF 的起点角色，保证患者身份在全流程中的一致性。E 恰恰相反，SWF 的价值就在于让不同厂商的系统按统一约定协同工作，避免被单一厂商锁定。", "tr": "SWF 的记忆抓手是\"一条流水线、两套标准\"：HL7 管人和医嘱、DICOM 管图像和执行状态。此外与 SWF 常配套出现的还有患者信息核对（PIR）、一致性图像显示（CPI）、关键图像标注（KIN）与放射剂量报告（REM）等模式。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0121", "t": "单选题", "s": "PACS 在影像部门内部的主要应用价值，不包括下列哪一项", "o": {"A": "实现影像的数字化存储与快速调阅，显著减少胶片管理与借阅工作量", "B": "支持多屏对比、历史检查自动调取与三维后处理，提高诊断效率与一致性", "C": "与 RIS 集成实现登记、分诊、检查、报告、审核的全流程闭环管理", "D": "便于统计检查工作量、报告周转时间、阳性率等运行与质量指标", "E": "直接提高成像设备探测器的量子探测效率，从而降低受检者的辐射剂量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-001", "kp": "PACS 在影像部门的应用价值", "ch": "十二、PACS技术 → 4.PACS临床应用 → (1)影像部门", "ex": "【为什么对】E 为本题答案。量子探测效率是探测器材料、结构与读出电路决定的物理性能指标，属成像设备硬件范畴；PACS 是影像信息的存储、传输与管理系统，不参与成像过程，也就不可能改变 DQE。需要说明的是，PACS 可通过减少重复检查、汇集剂量结构化报告（RDSR）支持剂量监测与分析，从管理层面间接助益剂量优化，但这与\"直接提高 DQE\"是两回事。【为什么错】A、B、C、D 均为 PACS 在影像科的确切价值：数字化存储替代胶片库房与人工借还；工作站的多屏、多序列同步对比与历史检查自动调取显著提升阅片效率；与 RIS 集成形成流程闭环并减少信息断点；系统日志与结构化数据为科室运行分析与质控指标统计提供基础。", "tr": "本题的判别要点是区分\"信息系统能力\"与\"成像物理性能\"。凡选项把 PACS 说成能改善分辨率、DQE、噪声等成像链物理指标，基本可判为错误。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0122", "t": "多选题", "s": "PACS 向临床科室延伸后所带来的价值，包括下列哪些方面", "o": {"A": "临床医师可在病房、门诊与手术室随时调阅患者影像与报告，无须等待胶片传递", "B": "手术与介入操作过程中可实时参考术前影像，支持术中定位与方案调整", "C": "多学科会诊时可同屏展示同一患者不同时期、不同模态的影像，便于疗效对比与联合决策", "D": "影像资料可与电子病历集成形成完整临床数据链，支持教学查房与科研回顾性研究", "E": "临床医师可在 PACS 上直接修改影像科已审核发布的诊断报告内容"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-002", "kp": "PACS 在临床部门的应用价值", "ch": "十二、PACS技术 → 4.PACS临床应用 → (2)临床部门", "ex": "【为什么对】A 正确：影像\"随处可及\"是 PACS 对临床最直观的改变，显著缩短了从检查完成到临床决策的时间。B 正确：手术室工作站与介入导管室调阅术前影像已成常规，部分场景还可与导航、融合影像技术结合。C 正确：跨时间、跨模态的同屏比较是多学科会诊质量的重要保障，也是疗效评估（如实体瘤疗效评价）的操作基础。D 正确：影像与电子病历的整合形成结构化的临床数据资产，为教学示教库与回顾性研究提供高效的数据来源。【为什么错】E 错误：诊断报告的书写、修改与审核权限归属影像诊断医师，临床医师仅有查阅权限。报告如需更正，应由影像科按制度出具补充报告或更正报告，原报告与修改痕迹须保留并记入审计日志，以保证医疗文书的严肃性与可追溯性。", "tr": "\"权限边界\"是 PACS 临床应用类题目的常设陷阱。共享的是影像与报告的\"查阅\"，而非\"编辑\"；同理，临床科室也不应具备删除影像、合并患者记录等管理权限。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0123", "t": "案例分析题", "s": "某三甲医院急诊科夜间接诊一名 72 岁男性，突发剧烈胸背撕裂样疼痛并向下腹放射，血压两上肢不对称，临床高度怀疑主动脉夹层，立即行主动脉 CTA。检查完成后需在最短时间内使急诊医师、在家备班的心外科二线医师与手术室三方同时获取影像资料；患者 3 个月前曾在本院行胸部 CT 平扫，需调出对比。医院已建成 PACS/RIS 并具备院外安全接入条件。基于信息化条件，下列处置流程最合理的是", "o": {"A": "图像重建完成后即时自动归档至 PACS 并触发危急值流程：急诊医师在急诊工作站调阅原始横断面与三维重组图像；心外科二线经身份认证的加密远程通道调阅同一份影像；手术室工作站同步调阅；既往胸部 CT 由系统按主患者索引自动关联或经预取调出对比", "B": "等待全部三维后处理与正式诊断报告审核完成后再统一归档发布，以免临床看到未审核的图像", "C": "由技师用手机拍摄工作站显示器画面，通过即时通讯软件发送给心外科二线医师，以节省时间", "D": "先打印全套胶片，再由护工分别送至急诊科、手术室与二线医师家中", "E": "因涉及患者隐私，院外一律不得访问影像，须待二线医师返院后在科内工作站阅片"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-003", "kp": "急危重症场景下的 PACS 协同应用", "ch": "十二、PACS技术 → 4.PACS临床应用 → (2)临床部门", "ex": "【为什么对】A 正确。主动脉夹层属时间依赖性极强的危急重症，信息化流程的目标是\"图像即时可及、多点同步、历史可比、过程可追溯\"。即时归档使三方基于同一份权威数据进行判断；加密远程接入配合身份认证与审计留痕，在保障隐私的同时不牺牲时效；主患者索引与预取机制保证历史检查自动关联对比；危急值流程确保口头与书面通报闭环。【为什么错】B 等待全部后处理与报告审核会延误抢救；规范做法是图像先归档可调阅，报告按危急值流程尽快出具并电话通报，两者并行而非串行。C 手机翻拍屏幕丢失灰阶与空间分辨率信息、无法调窗与测量，通过普通通讯软件传输还存在隐私泄露与责任界定风险，不符合诊断质量与信息安全要求。D 打印与人工递送耗时长，完全背离 PACS 的建设初衷，在急症场景中不可接受。E 隐私保护的正确路径是\"可控访问\"——身份认证、加密通道、权限最小化与审计留痕，而不是以禁止访问为代价延误抢救。", "tr": "急诊信息化场景题的判分核心是\"时效与合规并重\"。任何以牺牲抢救时效为代价的合规做法（如 E）、或以牺牲合规为代价的提速做法（如 C）都是错误选项。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0124", "t": "单选题", "s": "关于医疗机构推进\"无胶片化\"与电子胶片（云胶片）的认识，下列描述正确的是", "o": {"A": "电子胶片以二维码或链接形式向患者交付影像，患者可用移动终端浏览并授权其他机构调阅；推行时须同时保障影像信息的完整性（含原始 DICOM 数据的获取途径）、身份认证与隐私保护，并保留必要的胶片打印通道", "B": "推行无胶片化意味着医院不必再保存原始 DICOM 数据", "C": "电子胶片上供患者浏览的压缩图像可直接用于诊断阅片，与诊断级显示器观看效果等效", "D": "无胶片化的唯一目的是降低胶片耗材成本，与诊疗流程改善无关", "E": "实行电子胶片后，医院无须再考虑影像数据的备份与长期保存问题"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-004", "kp": "无胶片化与电子胶片的应用要点", "ch": "十二、PACS技术 → 4.PACS临床应用 → (1)影像部门", "ex": "【为什么对】A 正确。电子胶片的价值在于患者随身携带、跨机构授权共享与减少资源消耗，但落地时必须解决三个问题：一是保证外院医师能获取到符合诊断要求的完整影像（提供原始 DICOM 下载或标准化浏览器），而非仅有几幅缩略图；二是通过身份核验与授权机制防止信息泄露；三是对确有需要的场景（如外院系统不兼容、患者无智能终端）保留打印通道。【为什么错】B 无胶片化只是取消胶片这一输出载体，原始 DICOM 数据仍须依法按规定年限完整保存，且要求更高。C 供患者浏览的图像通常经过有损压缩、位深压缩与非校准终端显示，不能等同于诊断级阅片条件。D 无胶片化同时带来流程提速、资料不易丢失、跨机构共享便利与环保效益，成本只是其中一项。E 数据集中后备份与长期保存的重要性反而更高，一旦丢失将不可挽回。", "tr": "电子胶片\"能看\"不等于\"能诊断\"。判断此类题目时抓住两个尺度：是否提供符合诊断要求的原始数据获取途径，是否具备身份认证与隐私保护机制。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0125", "t": "单选题", "s": "关于厂商中立归档（VNA）这一概念，下列描述正确的是", "o": {"A": "VNA 以标准化格式集中存储来自不同厂商、不同科室的医学影像与相关文档，使数据独立于任何单一 PACS 厂商，便于系统更换时的数据迁移与企业级影像共享", "B": "VNA 是某一家厂商推出的专有存储产品的商品名称", "C": "VNA 只能存储放射科的 DICOM 影像，不支持其他科室的影像资料", "D": "部署 VNA 后医院即不再需要 PACS 的影像显示与诊断功能", "E": "VNA 与 DICOM 标准互不兼容，访问时需使用厂商专用协议"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-001", "kp": "厂商中立归档 VNA", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (1)进展", "ex": "【为什么对】A 正确。传统 PACS 的存储层与厂商应用高度耦合，更换 PACS 时常面临昂贵而漫长的数据迁移。VNA 把归档层从应用层剥离出来，以标准格式（DICOM，以及通过 XDS/XDS-I 管理的非 DICOM 文档）统一存储，实现\"换应用不换数据\"，并为跨科室、跨院区的企业级影像管理提供统一底座。【为什么错】B VNA 是一类架构理念与产品形态，多家厂商都有相应实现，并非某一专有商品名。C VNA 的核心目标之一恰恰是覆盖超声、内镜、病理、皮肤科照片、心电等多科室资料，其中非 DICOM 对象常借助 XDS 注册与封装管理。D VNA 只承担归档与管理职能，影像的显示、后处理与诊断仍由 PACS 工作站或通用阅片器完成，二者是分工而非替代。E VNA 以支持 DICOM 等开放标准为前提，正因为遵循标准才能实现\"中立\"。", "tr": "VNA 与 PACS 的关系可类比\"仓库与营业厅\"：VNA 负责长期、标准、中立地存放数据，PACS 负责业务流程与阅片体验。命题常用\"VNA 取代 PACS\"来设陷。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-0126", "t": "多选题", "s": "就 PACS 领域近年来的技术进展而言，下列描述正确的有", "o": {"A": "云 PACS 与区域影像中心使基层机构可共享上级医院的存储与阅片资源，为区域内影像检查结果互认提供技术基础", "B": "零客户端/Web 阅片采用服务器端渲染，客户端只接收渲染后的画面，便于跨终端访问与集中运维", "C": "企业级影像管理把放射、超声、内镜、病理、皮肤科照片等多科室影像统一纳入管理，常与 VNA、XDS-I 等技术结合", "D": "人工智能应用逐步嵌入 PACS 工作流，可承担危急征象预警、病灶检出与量化随访等辅助任务，但须在质量控制与责任界定框架下使用", "E": "随着存储介质成本持续下降，医学影像的长期保存已无须再做分级存储与数据生命周期管理"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-002", "kp": "PACS 技术进展与发展方向", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (1)进展", "ex": "【为什么对】A 正确：云化与区域化把存储、算力与专家资源集中，是分级诊疗与检查结果互认的支撑条件，同时对网络质量、数据主权与隐私合规提出更高要求。B 正确：服务器端渲染把计算压力集中到后端，客户端无须安装插件即可获得较好的交互体验，显著降低终端运维成本。C 正确：影像的\"去科室化\"管理是企业级影像的核心思想，非 DICOM 对象通过 XDS/XDS-I 注册与索引纳入统一体系。D 正确：AI 已在结节检出、骨折与出血预警、随访量化等场景落地，但其结果属辅助性质，须建立性能验证、持续监测与责任界定机制。【为什么错】E 错误：薄层 CT、能量成像、数字乳腺断层合成与数字病理使影像数据量呈爆发式增长，增速普遍快于单位存储成本的下降速度；同时法规对不同类别资料的保存年限有明确要求，分级存储、压缩策略与数据生命周期管理不仅不可取消，反而更为重要。", "tr": "涉及\"新技术\"的题目往往在最后一个选项设置\"因此某项传统管理工作可以取消\"的绝对化陷阱。技术进步通常是改变管理方式，而非免除管理责任。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-0127", "t": "单选题", "s": "某院拟对上线运行三年的 PACS 开展应用评价，下列评价思路与指标选择中最合理的是", "o": {"A": "从技术、经济与临床三个层面综合评价：技术层面考察系统可用率、平均调阅响应时间、故障恢复时间与数据完整性；经济层面考察胶片与人力成本节约及投资回收情况；临床层面考察报告周转时间缩短程度、重复检查率下降与临床满意度", "B": "只统计每年节约的胶片费用，即可代表 PACS 的全部价值", "C": "以系统所安装的诊断与浏览工作站数量作为核心评价指标", "D": "以中心服务器磁盘容量的使用率高低作为系统优劣的判断依据", "E": "以影像科医师的诊断符合率作为 PACS 应用评价的唯一指标"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-003", "kp": "PACS 应用评价的指标体系", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (2)应用评价", "ex": "【为什么对】A 正确。信息系统的应用评价须覆盖\"系统好不好用、值不值得、有没有改善诊疗\"三个维度：技术性能指标反映系统本身的可靠性与响应能力；经济指标反映投入产出关系；临床效果指标（报告周转时间 TAT、重复检查率、检查到治疗决策的时间、临床与患者满意度）才是评价其最终价值的关键。三者结合方能形成完整、可比、可持续追踪的评价体系。【为什么错】B 胶片节约只是经济效益的一部分，忽略了效率提升、流程再造、资料不易丢失与临床协同等更重要的价值。C 工作站数量属投入规模指标，不反映产出效果，安装多而使用率低反而是浪费。D 磁盘使用率是容量规划的监控项，与应用效果无关，使用率高低都无法说明系统优劣。E 诊断符合率主要取决于医师专业水平、设备成像质量与病种构成，PACS 只是其中的支持条件之一，把它作为唯一指标既存在归因错误，也无法反映系统在效率与流程方面的贡献。", "tr": "评价类题目的判别要领是看\"是否单一维度\"与\"是否可归因\"。凡以某个孤立数字（成本、数量、容量、符合率）代表整体价值的选项，通常都是错误项。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1001", "t": "单选题", "s": "PACS的中文全称是", "o": {"A": "图像存储与通信系统", "B": "放射信息系统", "C": "医院信息系统", "D": "电子病历系统", "E": "实验室信息系统"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-101", "kp": "PACS基本概念", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (1)发展", "ex": "【为什么对】PACS是Picture Archiving and Communication System的缩写，即图像存储与通信系统，指用数字化方式采集、存储、传输和显示医学影像的计算机网络系统，故A正确。\n【为什么错】B：RIS（Radiology Information System）为放射信息系统。C：HIS（Hospital Information System）为医院信息系统。D：电子病历系统（EMR）管理病历文本。E：实验室信息系统（LIS）管理检验数据，均与PACS含义不符。", "tr": "注意PACS、RIS、HIS三个缩写含义的区别，PACS核心是影像的存储与通信。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1002", "t": "单选题", "s": "下列哪项不属于PACS系统的基本组成", "o": {"A": "影像采集接口", "B": "影像存储与归档服务器", "C": "影像显示工作站", "D": "网络与通信设备", "E": "MRI主磁体"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-102", "kp": "PACS系统组成", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (2)构架与工作流程", "ex": "【为什么对】PACS由影像采集、存储与归档、传输网络、显示工作站及管理软件等组成，MRI主磁体属于MR设备本身，不属于PACS组成，故E正确。\n【为什么错】A：影像采集接口是PACS的数据入口，属其组成。B：影像存储与归档服务器是PACS核心，属其组成。C：影像显示工作站是PACS终端，属其组成。D：网络与通信设备是PACS传输基础，属其组成，均为PACS组成故不符合题意。", "tr": "PACS是信息系统，不包含任何成像设备本体（如球管、磁体）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1003", "t": "单选题", "s": "DICOM是下列哪项的英文缩写", "o": {"A": "医学数字成像与通信", "B": "数字影像与通信系统", "C": "医学信息交换标准", "D": "放射信息管理系统", "E": "医院信息集成标准"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-103", "kp": "DICOM标准概念", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】DICOM全称Digital Imaging and Communications in Medicine，即医学数字成像与通信标准，是医学影像信息交换的国际标准，故A正确。\n【为什么错】B：措辞不准确，DICOM是标准而非系统。C：医学信息交换标准泛指，非DICOM专名。D：对应RIS。E：对应HL7等集成需求，非DICOM名称。", "tr": "DICOM是医学影像的数据与通信标准，与HL7（文本信息交换）易混淆。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1004", "t": "单选题", "s": "DICOM信息模型由高层到低层的排列顺序是", "o": {"A": "患者-检查-序列-图像", "B": "检查-患者-图像-序列", "C": "序列-检查-患者-图像", "D": "患者-序列-检查-图像", "E": "图像-序列-检查-患者"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-104", "kp": "DICOM信息层次模型", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】DICOM信息模型采用四级层次结构：患者（Patient）→检查（Study）→序列（Series）→图像（Instance/Image），自上而下归属关系，故A正确。\n【为什么错】B：将检查置于患者之上，层级颠倒。C：以序列为最高层，层级颠倒。D：将序列置于检查之上，顺序错误。E：以图像为最高层，层级完全颠倒，均不符合DICOM标准。", "tr": "牢记DICOM四层顺序：一个患者可有多个检查，一个检查可有多个序列，一个序列含多幅图像。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1005", "t": "单选题", "s": "DICOM检查工作列表（MWL）的主要作用是", "o": {"A": "将检查申请信息下发至影像设备供技师核对执行", "B": "存储诊断报告", "C": "打印图像", "D": "进行图像后处理", "E": "远程会诊"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-105", "kp": "DICOM检查工作列表", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】Modality Worklist（MWL）将RIS/HIS中已预约登记的患者信息与检查项目下发给影像设备，技师在设备上直接调取确认，减少手工录入与差错，故A正确。\n【为什么错】B：报告存储由RIS管理。C：图像打印对应DICOM打印管理服务。D：图像后处理在工作站完成。E：远程会诊是PACS应用层面功能，均非MWL作用。", "tr": "MWL是设备端取工作单，MPPS是检查执行状态回报，两者易混淆。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1006", "t": "单选题", "s": "关于HL7标准，正确的说法是", "o": {"A": "主要用于传输医学影像数据", "B": "主要用于交换文本形式的临床与行政管理信息", "C": "只能在同一厂家设备间使用", "D": "与DICOM的功能完全相同", "E": "是一种图像压缩算法"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-106", "kp": "HL7标准特点", "ch": "十二、PACS技术 → 3.国际标准与规范 → (1)HL7", "ex": "【为什么对】HL7（Health Level 7）是医疗卫生信息交换标准，面向文本信息（申请、医嘱、报告、收费等），故B正确。\n【为什么错】A：影像数据传输使用DICOM。C：HL7为开放性标准，跨厂商使用。D：HL7管文本、DICOM管图像，功能分工不同。E：HL7不是压缩算法。", "tr": "图像走DICOM、文本走HL7，是PACS集成中最重要的分工概念。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1007", "t": "单选题", "s": "HL7标准名称中的数字“7”指的是OSI参考模型的", "o": {"A": "物理层", "B": "数据链路层", "C": "网络层", "D": "传输层", "E": "应用层"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-107", "kp": "HL7与OSI层次", "ch": "十二、PACS技术 → 3.国际标准与规范 → (1)HL7", "ex": "【为什么对】HL7中的“7”指OSI参考模型的第7层即应用层，其消息标准工作在应用层，故E正确。\n【为什么错】A：物理层是OSI第1层。B：数据链路层是第2层。C：网络层是第3层。D：传输层是第4层，均非HL7名称中“7”所指。", "tr": "“7”对应应用层，属纯记忆考点，注意与传输层（第4层）区分。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1008", "t": "单选题", "s": "PACS影像存储架构中，“近线存储”通常采用的介质是", "o": {"A": "在线磁盘阵列", "B": "磁带库或光盘库", "C": "移动硬盘", "D": "内存", "E": "U盘"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-108", "kp": "PACS影像存储分层", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】PACS存储分在线、近线、离线三级：在线用磁盘阵列快速响应，近线用磁带库、光盘库等自动化的海量存储设备，离线为异地存放的备份介质，故B正确。\n【为什么错】A：磁盘阵列属在线存储而非近线。C：移动硬盘、E：U盘多为临时迁移介质，不属于近线存储体系。D：内存用于计算处理，不用于归档存储。", "tr": "在线=磁盘阵列，近线=磁带/光盘库，离线=异地备份，三者响应速度递减、容量递增。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的发展与组成", "页": 343}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1009", "t": "单选题", "s": "PACS在线存储中，兼具容错能力与较高空间利用率、应用最广泛的RAID级别是", "o": {"A": "RAID 0", "B": "RAID 1", "C": "RAID 5", "D": "JBOD", "E": "无任何冗余的裸盘"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-109", "kp": "RAID级别与存储冗余", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】RAID 5采用分布式奇偶校验，允许单块硬盘故障而不丢失数据，空间利用率高，是PACS在线存储的常用方案，故C正确。\n【为什么错】A：RAID 0无冗余，一坏即全丢。B：RAID 1为镜像，空间利用率仅50%。D：JBOD只是盘符拼接无冗余。E：裸盘无任何容错，均不适合关键影像数据。", "tr": "RAID 0快但不安全，RAID 1安全但浪费空间，RAID 5在两者间取得平衡。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1010", "t": "单选题", "s": "某PACS在100Mbps局域网内传输2000幅平均500KB的CT图像（1MB=8Mbit），忽略协议开销，约需", "o": {"A": "8秒", "B": "40秒", "C": "80秒", "D": "400秒", "E": "800秒"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-110", "kp": "影像传输时间估算", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (4)通讯与网络", "ex": "【为什么对】数据总量=2000×500KB=1000MB≈1GB；换算为比特1GB=8Gbit=8192Mbit；100Mbps即100Mbit/s；时间=8192/100≈82秒，约80秒，故C正确。\n【为什么错】A：8秒按100MB计算。B：40秒按0.5GB计算。D：400秒按带宽25Mbps计算。E：800秒按带宽10Mbps计算，均计算有误。", "tr": "先统一单位：字节×8转比特，再除以带宽（bps），注意Mbps与MB/s相差8倍。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1011", "t": "单选题", "s": "远程放射学的核心内容是", "o": {"A": "医学影像的异地传输与会诊", "B": "影像设备维修", "C": "报告打印", "D": "患者信息管理", "E": "医保结算"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-111", "kp": "远程放射学概念", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】远程放射学是利用网络将影像资料从采集地传输到异地进行诊断、会诊的技术，核心是影像的异地传输与会诊，故A正确。\n【为什么错】B：设备维修属工程维护。C：报告打印为终端输出。D：患者信息管理属HIS/RIS。E：医保结算与影像业务无关，均非远程放射学核心。", "tr": "远程放射学强调“影像传输+异地诊断”，网络带宽与图像质量是成败关键。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1012", "t": "单选题", "s": "一幅约10MB的DR图像，若要求在2秒内完成传输，所选网络的最低速率约为", "o": {"A": "1Mbps", "B": "10Mbps", "C": "40Mbps", "D": "100Mbps", "E": "1Gbps"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-112", "kp": "网络带宽需求估算", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (4)通讯与网络", "ex": "【为什么对】10MB=80Mbit，2秒内传完要求速率≥40Mbit/s；工程中应留裕量，选不低于100Mbps的速率，故D正确。\n【为什么错】A：1Mbps下2秒仅能传2Mbit，严重不足。B：10Mbps下2秒传20Mbit，不足。C：40Mbps为理论临界值无裕量。E：1Gbps可行但高于最低要求，非“最低”速率。", "tr": "先算理论最低速率40Mbps，再结合实际选取更高档位，题目问“最低”时应兼顾工程裕量选100Mbps。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1013", "t": "单选题", "s": "PACS与HIS、RIS实现文本信息（申请、报告、收费等）交换时，最常采用的标准是", "o": {"A": "DICOM", "B": "HL7", "C": "IHE", "D": "JPEG", "E": "MPEG"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-113", "kp": "PACS与HIS/RIS集成标准", "ch": "十二、PACS技术 → 2.PACS运行 → (4)与HIS/RIS集成", "ex": "【为什么对】HL7是文本信息交换标准，用于检查申请、报告、收费等消息在HIS、RIS与PACS之间的传递，故B正确。\n【为什么错】A：DICOM用于影像数据与影像设备交互。C：IHE是集成规范框架而非具体消息标准。D：JPEG为图像压缩格式。E：MPEG为视频压缩格式，均与文本信息交换无关。", "tr": "影像交互用DICOM、文本交互用HL7，IHE是指导两者组合应用的框架。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1014", "t": "单选题", "s": "PACS中“影像预取（prefetch）”指的是", "o": {"A": "检查前将患者相关历史影像自动调取至工作站", "B": "检查后立即删除图像", "C": "对图像进行有损压缩", "D": "将过期图像迁移至离线介质", "E": "备份数据库"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-114", "kp": "影像预取与调阅", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (6)影像管理", "ex": "【为什么对】预取指根据检查预约信息，在患者到检前自动将既往相关影像从归档系统调取到读片工作站，便于新旧对比，故A正确。\n【为什么错】B：检查后不立即删除图像。C：压缩是存储策略之一。D：过期图像迁移至离线属归档/迁移。E：备份数据库是维护措施，均非预取含义。", "tr": "预取（prefetch）与归档、迁移概念区分：预取是把旧图像提前调出来。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1015", "t": "单选题", "s": "DICOM“存储承诺（Storage Commitment）”的作用是", "o": {"A": "确认图像已安全存入归档系统后，来源设备方可删除本地图像", "B": "自动分配检查号", "C": "定义胶片打印格式", "D": "控制显示器亮度", "E": "核对患者身份"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-115", "kp": "DICOM存储承诺服务", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】存储承诺是DICOM服务类之一：影像设备将图像提交归档系统，归档系统确认安全存储后返回承诺，设备据此才能删除本地图像，防止数据丢失，故A正确。\n【为什么错】B：检查号分配由RIS登记产生。C：胶片格式由DICOM打印管理定义。D：显示器亮度校准依据GSDF。E：身份核对由MWL/登记环节完成，均与存储承诺无关。", "tr": "存储承诺的本质是“归档确认机制”，与检查工作列表、打印服务等DICOM服务类区分。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1016", "t": "单选题", "s": "为保障远程放射学中传输影像资料的完整性与不可篡改性，最有效的技术措施是", "o": {"A": "加大防火墙", "B": "数字签名与完整性校验", "C": "定期查杀病毒", "D": "提高传输带宽", "E": "增加存储容量"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-116", "kp": "远程放射学数据安全", "ch": "十二、PACS技术 → 2.PACS运行 → (3)系统安全", "ex": "【为什么对】数字签名可验证数据来源真实性，完整性校验（如哈希）能发现数据在传输中被篡改或损坏，是保障影像资料真实、完整的关键措施，故B正确。\n【为什么错】A：防火墙用于网络访问控制，不能防止内容篡改。C：杀毒软件防范恶意代码，不验证数据完整性。D：带宽只影响传输速度。E：容量只影响存储规模，均无法保证数据不可篡改。", "tr": "“防篡改”对应数字签名与完整性校验；“防入侵”对应防火墙；“防丢失”对应备份。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1017", "t": "单选题", "s": "IHE（医疗企业集成）是", "o": {"A": "基于DICOM、HL7等标准组织应用流程的集成框架", "B": "一种图像压缩算法", "C": "一种网络传输协议", "D": "一种胶片质量检测标准", "E": "一个数据库管理系统"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-117", "kp": "IHE集成框架", "ch": "十二、PACS技术 → 3.国际标准与规范 → (3)IHE", "ex": "【为什么对】IHE（Integrating the Healthcare Enterprise，医疗企业集成）以DICOM、HL7等既有标准为基础，通过定义角色与事务将标准组织成解决实际医疗流程问题的集成框架，故A正确。\n【为什么错】B：压缩算法如JPEG2000。C：网络协议如TCP/IP。D：胶片检测如SMPTE测试片。E：数据库如SQL Server，均与IHE无关。", "tr": "IHE不是新标准，而是“如何组合使用DICOM与HL7”的规范框架。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1018", "t": "单选题", "s": "某院PACS在线存储容量即将用尽而检查量持续增长，从性价比与可扩展性考虑，最合理的扩容方案是", "o": {"A": "仅增加离线磁带", "B": "扩容磁盘阵列并配置自动归档迁移策略", "C": "直接删除3年以上旧图像", "D": "改用纯内存存储", "E": "降低所有图像分辨率后存储"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-118", "kp": "PACS存储扩容策略", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (2)应用评价", "ex": "【为什么对】扩容在线磁盘阵列满足当前读写需求，同时设置自动归档策略将符合条件（如超期、少调阅）的图像迁移至近线/离线存储，兼顾容量、性能与法规保存要求，故B正确。\n【为什么错】A：仅加离线磁带无法缓解在线空间压力。C：直接删除历史图像违反影像保存规定。D：内存成本极高且断电丢失，不适合归档。E：降低分辨率损害诊断质量，均不可取。", "tr": "扩容方案要“在线扩容+分层归档”双管齐下，不能牺牲诊断质量或违规删除。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1019", "t": "多选题", "s": "PACS系统的基本组成包括", "o": {"A": "影像采集接口", "B": "影像存储与归档服务器", "C": "影像显示工作站", "D": "网络与通信设备", "E": "X线球管"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-119", "kp": "PACS系统组成", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (2)构架与工作流程", "ex": "【为什么对】PACS由影像采集接口、存储与归档服务器、显示工作站、网络与通信设备以及管理软件等组成，故A、B、C、D正确。\n【为什么错】E：X线球管是X线成像设备（DR/CT）的部件，不属于PACS信息系统组成。", "tr": "PACS是信息系统，影像产生设备本体（球管、探测器、磁体）不属于其组成。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1020", "t": "多选题", "s": "DICOM标准提供的主要服务类（Service Class）包括", "o": {"A": "影像存储服务", "B": "查询/检索服务", "C": "打印管理服务", "D": "检查工作列表服务", "E": "光纤介质传输服务"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-120", "kp": "DICOM服务类", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】DICOM定义的服务类包括影像存储、查询/检索、打印管理、检查工作列表、存储承诺、检查执行步骤等，故A、B、C、D正确。\n【为什么错】E：光纤是物理传输介质，DICOM协议本身基于TCP/IP，不存在名为“光纤介质传输”的DICOM服务类。", "tr": "区分DICOM服务类（存储、查询检索、打印、工作列表等）与物理传输介质（光纤、双绞线）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1021", "t": "多选题", "s": "关于PACS中图像压缩的正确说法是", "o": {"A": "无损压缩是可逆的、不丢失任何诊断信息", "B": "JPEG2000同时支持无损与有损压缩", "C": "诊断用图像宜采用无损或近无损压缩", "D": "压缩比越高图像质量越高", "E": "有损压缩在任何场合都不可使用"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-121", "kp": "图像压缩与质量", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】无损压缩可完全还原原始数据；JPEG2000支持有损与无损两种模式；诊断影像为保证质量宜采用无损或近无损压缩，故A、B、C正确。\n【为什么错】D：压缩比越高数据损失越大、图像质量越低。E：有损压缩可用于浏览、存档辅助等非诊断场景，并非完全不可用。", "tr": "压缩比与图像质量成反比；有损压缩并非禁用，而是诊断环节须谨慎。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1022", "t": "多选题", "s": "开展远程放射学会诊应具备的条件包括", "o": {"A": "足够的网络传输带宽", "B": "保证图像质量与显示一致性", "C": "患者隐私与数据安全保障", "D": "会诊资质与法律合规要求", "E": "无需任何网络支持"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-122", "kp": "远程放射学实施条件", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】远程会诊要求足够带宽保障传输速度与时效，图像质量与显示校准一致保证诊断可靠性，加密、授权等保障隐私安全，并须符合会诊资质与法规要求，故A、B、C、D正确。\n【为什么错】E：远程会诊恰恰必须依赖网络，说法完全错误。", "tr": "远程放射学四大要素：带宽、图像质量、信息安全、资质合规。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1023", "t": "多选题", "s": "PACS系统安全防护措施包括", "o": {"A": "部署防火墙与入侵检测", "B": "用户身份认证与权限分级", "C": "传输与存储数据加密", "D": "定期备份并建立容灾机制", "E": "关闭审计日志以节省空间"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-123", "kp": "PACS系统安全", "ch": "十二、PACS技术 → 2.PACS运行 → (3)系统安全", "ex": "【为什么对】防火墙与入侵检测防止外部攻击，认证与权限分级控制访问，加密保护数据保密性，备份与容灾保障可用性，均属系统安全措施，故A、B、C、D正确。\n【为什么错】E：审计日志用于安全追踪与责任追溯，关闭日志会削弱安全管理能力。", "tr": "安全体系包含保密性、完整性、可用性三个方面，审计日志是安全追踪的重要工具。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1024", "t": "多选题", "s": "PACS影像管理的功能主要包括", "o": {"A": "影像预取", "B": "影像路由", "C": "影像归档", "D": "检索与调阅", "E": "自动出具诊断结论"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-124", "kp": "PACS影像管理功能", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (6)影像管理", "ex": "【为什么对】影像管理包括预取、路由（按规则分发到相应工作站）、归档（分级存储）、检索与调阅等，故A、B、C、D正确。\n【为什么错】E：诊断结论由放射科医师根据影像与临床资料综合分析后出具，PACS不自动生成诊断结论。", "tr": "PACS提供影像存取与管理，诊断报告的人工智能辅助属进展方向，非系统常规功能。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1025", "t": "多选题", "s": "PACS影像数据可以使用的存储介质包括", "o": {"A": "磁盘阵列", "B": "磁带库", "C": "光盘库", "D": "移动硬盘", "E": "荧光屏"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-125", "kp": "PACS存储介质", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】磁盘阵列用于在线，磁带库、光盘库用于近线，移动硬盘可用于临时迁移或小型备份，故A、B、C、D正确。\n【为什么错】E：荧光屏是显示器件，不能存储影像数据。", "tr": "存储介质均为可写入读出的物理载体，显示器件不属于存储介质。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1026", "t": "多选题", "s": "制定PACS存储与备份策略时应考虑的因素包括", "o": {"A": "检查量与数据增长率", "B": "在线、近线、离线分层存储需求", "C": "备份周期与异地容灾地点", "D": "法规规定的影像保存期限", "E": "显示器数量与分辨率"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-126", "kp": "PACS存储策略规划", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】存储策略须根据数据量增长预估容量，按访问频率设计分层存储，明确备份周期与容灾方案，并满足法规对影像保存期限的要求，故A、B、C、D正确。\n【为什么错】E：显示器数量与分辨率影响显示配置，与存储容量、备份策略无关。", "tr": "存储策略的核心变量是容量、分层、备份与法规期限，不含显示端配置。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1027", "t": "多选题", "s": "利用HL7与DICOM实现PACS与HIS/RIS集成时，典型的应用场景包括", "o": {"A": "检查申请单自动下发", "B": "检查执行状态（MPPS）回报", "C": "诊断报告回传与发布", "D": "预约挂号与患者信息同步", "E": "图像像素数据压缩"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-127", "kp": "PACS-HIS/RIS集成应用", "ch": "十二、PACS技术 → 2.PACS运行 → (4)与HIS/RIS集成", "ex": "【为什么对】集成环境下检查申请经HL7下发、设备经DICOM MWL取单并回报MPPS、报告经HL7回传发布、预约与患者信息同步，均为典型场景，故A、B、C、D正确。\n【为什么错】E：图像像素数据压缩属存储优化环节，不属于信息集成应用场景。", "tr": "集成场景围绕“信息流”展开，像素压缩属于“数据流”优化，二者层面不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1028", "t": "多选题", "s": "PACS系统日常维护应包含的内容有", "o": {"A": "定期检查备份并演练数据恢复", "B": "监控磁盘容量与系统日志", "C": "及时升级系统补丁与杀毒软件", "D": "巡检UPS电源与网络设备", "E": "关闭异地备份以简化管理"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-128", "kp": "PACS日常维护", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】备份检查与恢复演练保障数据安全，容量与日志监控及时发现异常，补丁与杀毒软件防患安全风险，电源与网络巡检保障运行环境，故A、B、C、D正确。\n【为什么错】E：异地备份是容灾的重要手段，关闭异地备份会大幅降低数据抗风险能力。", "tr": "日常维护是“备份、监控、加固、巡检”的组合拳，备份必须有恢复演练才有效。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U12-1029a", "t": "单选题", "s": "【病例】某三甲医院放射科拟将PACS与HIS/RIS全面集成，实现患者从门诊开单、放射科登记、影像设备检查到报告回传的全流程信息化，并将夜间急诊影像通过远程网络发送至院外会诊中心。技师在CT操作台前开始一天的检查工作。 患者检查申请信息自动显示在CT设备操作界面上，技师核对后直接执行检查，主要依赖的DICOM服务是", "o": {"A": "检查工作列表（MWL）", "B": "图像打印服务", "C": "存储承诺", "D": "查询/检索服务", "E": "影像存储服务"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-129", "kp": "检查工作列表应用", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】MWL将RIS登记的患者信息与检查项目自动下发到影像设备，技师在设备端直接调取核对，无需手工录入，故A正确。\n【为什么错】B：打印服务用于胶片输出。C：存储承诺用于归档确认。D：查询/检索用于事后调阅历史影像。E：影像存储服务用于保存图像，均与检查申请下发无关。", "tr": "“自动取单”对应MWL；“查历史”对应Query/Retrieve；“报进度”对应MPPS。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1029b", "t": "单选题", "s": "检查完成后，设备自动向RIS回报本次检查已执行完毕及参数信息，所采用的服务是", "o": {"A": "检查执行步骤（MPPS）", "B": "打印管理", "C": "胶片格式定义", "D": "灰阶校准", "E": "图像无损压缩"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-130", "kp": "检查执行步骤回报", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】MPPS（Modality Performed Procedure Step）将设备实际执行的检查状态与参数回报给RIS，实现流程闭环，故A正确。\n【为什么错】B：打印管理负责图像打印。C：胶片格式属打印服务内容。D：灰阶校准针对显示设备。E：压缩属存储优化，均与检查状态回报无关。", "tr": "MWL负责“下发”，MPPS负责“回报”，两者配套构成检查流程闭环。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1030a", "t": "单选题", "s": "【病例】某县级医院需将1000幅CT图像（每幅约1MB）通过10Mbps专线发送至上级医院进行远程会诊，技师需估算传输时间，并在有限带宽条件下确保在规定时间内完成传输。 在不压缩、忽略协议开销的情况下，全部图像传输完毕约需", "o": {"A": "约1分钟", "B": "约4分钟", "C": "约8分钟", "D": "约14分钟", "E": "约40分钟"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-131", "kp": "远程传输时间估算", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】数据总量1000MB≈1GB，换算8Gbit=8192Mbit；10Mbps传输，时间=8192/10≈820秒≈13.6分钟，约14分钟，故D正确。\n【为什么错】A：按10Mbit计算。B：按250MB计算。C：按500MB计算。E：按带宽4Mbps计算，均不正确。", "tr": "GB与Gbit相差8倍，Mbps是Mbit/s而非MB/s，勿混淆单位。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1030b", "t": "单选题", "s": "若院方要求在2分钟内完成全部图像传输且不更换网络线路，最有效的措施是", "o": {"A": "对图像进行无损或近无损压缩后传输", "B": "提高图像采集分辨率", "C": "逐幅手工拷贝到移动硬盘", "D": "关闭远程会诊系统", "E": "增加显示工作站数量"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-132", "kp": "远程传输优化措施", "ch": "十二、PACS技术 → 2.PACS运行 → (2)远程放射学", "ex": "【为什么对】固定带宽下减少传输数据量是唯一有效途径，采用无损/近无损压缩既保证诊断质量又缩短时间，故A正确。\n【为什么错】B：提高分辨率使数据量增大，适得其反。C：手工拷贝效率低且非实时会诊方案。D：关闭系统无法完成会诊。E：工作站数量与传输时间无关。", "tr": "压缩是带宽不足时缩短传输时间的直接手段，但要兼顾诊断图像质量要求。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1031a", "t": "单选题", "s": "【病例】某医院PACS在线服务器的一块硬盘发生故障，管理人员启动应急预案。医院规定所有影像数据必须长期可靠保存，不能因硬件故障造成图像丢失。 为防止单块硬盘故障导致在线数据丢失，在线存储最应采用的容错方案是", "o": {"A": "RAID 0", "B": "RAID 1或RAID 5冗余阵列", "C": "仅依靠UPS不间断电源", "D": "增加内存容量", "E": "提高显示器分辨率"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-133", "kp": "在线存储容错", "ch": "十二、PACS技术 → 1.PACS发展与组成 → (5)影像存储", "ex": "【为什么对】RAID 1镜像、RAID 5分布式奇偶校验均可在单块硬盘故障时不丢数据，是满足可靠保存要求的容错方案，故B正确。\n【为什么错】A：RAID 0无冗余，单盘故障即数据丢失。C：UPS解决断电问题，不解决硬盘故障。D：内存与数据持久保存无关。E：显示器分辨率与存储容错无关。", "tr": "UPS防断电、RAID防硬盘故障，两者作用不同，不可混为一谈。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1031b", "t": "单选题", "s": "关于影像数据长期可靠保存，下列做法中最为关键的是", "o": {"A": "定期将数据备份至异地存储并定期演练恢复", "B": "只做在线磁盘冗余", "C": "停用近线存储设备", "D": "删除超期诊断报告", "E": "仅依赖防病毒软件"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-134", "kp": "数据长期保存与容灾", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】异地备份可抵御设备损坏、火灾、灾害等风险，且定期演练恢复能确保备份真正可用，是长期可靠保存的关键，故A正确。\n【为什么错】B：仅在线冗余无法应对服务器整体故障或灾害。C：停用近线存储削弱分层归档能力。D：删除报告违反病历管理要求。E：防病毒软件无法防止硬件故障与数据损坏。", "tr": "“有备份”不等于“可恢复”，只有经过恢复演练的备份才是有效备份。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1032", "t": "案例分析题", "s": "患者女性，55岁，因腰椎骨折在外院行CT检查后转诊至我院，携带光盘影像资料。放射科PACS管理员在例行巡检中发现归档服务器在线磁盘使用率已达95%，新检查图像的自动归档开始失败，历史图像调阅速度明显下降。该院日检查量约800例且持续增长，院内规定影像资料至少保存15年。管理员需要在不影响临床使用、不违反影像保存规定的前提下解决容量问题。下列处置措施最为恰当的是", "o": {"A": "立即删除全部历史图像以释放空间", "B": "启用自动迁移策略将符合条件的旧图像转至近线存储，并扩容在线磁盘", "C": "关闭PACS系统暂停所有检查", "D": "忽略故障继续运行等待自然缓解", "E": "把全部图像有损压缩至极低质量"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-135", "kp": "PACS容量管理处置", "ch": "十二、PACS技术 → 2.PACS运行 → (5)日常维护", "ex": "【为什么对】自动迁移将低频调阅的旧图像转至近线存储，既释放在线空间又保留数据，再扩容在线磁盘满足新数据写入，兼顾临床使用与保存规定，故B正确。\n【为什么错】A：删除历史图像违反影像保存规定。C：关停系统严重影响诊疗。D：放任故障会导致归档持续失败与数据丢失。E：极低质量压缩损害诊断价值，均不可取。", "tr": "容量治理要“迁、扩、管”结合，禁止以删除影像、停用系统、过度压缩为代价。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1033", "t": "案例分析题", "s": "患者男性，62岁，突发右侧肢体无力伴言语不清1小时就诊于基层医院，NIHSS评分12分。临床高度怀疑急性脑梗死，发病时间在静脉溶栓时间窗内，行颅脑CT检查提示未见出血。基层医院无神经影像专家，需请上级医院专家紧急会诊决定是否溶栓。该院已建成区域远程会诊平台，可加密传输原始影像并支持在线同步阅片。当前最合适的做法是", "o": {"A": "通过PACS远程会诊平台即时上传图像并同步会诊", "B": "让患者自行转院后再看片", "C": "打印胶片后快递至上级医院", "D": "仅电话口头描述影像所见", "E": "等次日上班后再传输"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-136", "kp": "远程会诊临床应用", "ch": "十二、PACS技术 → 4.PACS临床应用 → (2)临床部门", "ex": "【为什么对】急性卒中救治时间窗紧迫，通过远程放射学平台即时上传原始图像并同步会诊，可使上级专家快速判断，指导溶栓决策，故A正确。\n【为什么错】B：转院延误溶栓时间窗。C：快递胶片时效性太差。D：口头描述无法客观评估影像细节。E：延迟传输错过最佳治疗时机，均不可取。", "tr": "远程会诊在急症中的价值体现为“时效性”，必须及时传输原始影像供专家直接判读。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的临床应用", "页": 352}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1034", "t": "案例分析题", "s": "某影像中心DR设备本地硬盘空间紧张，技师计划清理设备本地缓存图像以腾出空间。设备与PACS归档服务器之间通过DICOM协议连接，存在历史图像可能尚未完成归档的情况，若误删将造成不可恢复的数据丢失。技师需要判断哪些图像可以安全删除。科室制定了本地数据清理规范，要求删除前必须核实归档状态。判断本地图像已安全归档、可以删除的最可靠依据是", "o": {"A": "本地文件时间已超过一天", "B": "已收到DICOM存储承诺的成功确认", "C": "图像曾在设备显示器上显示过", "D": "图像传输过程已经开始", "E": "图像已拷贝到U盘"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-137", "kp": "存储承诺与本地清理", "ch": "十二、PACS技术 → 3.国际标准与规范 → (2)DICOM", "ex": "【为什么对】DICOM存储承诺由归档系统确认图像已安全存储后返回，只有收到该确认才能保证数据已在归档端落地，是安全删除本地图像的最可靠依据，故B正确。\n【为什么错】A：时间长短不能证明归档完成。C：显示过只说明曾调阅。D：传输开始不代表传输成功。E：拷贝到U盘不替代归档系统保存。", "tr": "“开始传输”“看过片”都不代表“已归档”，只有存储承诺确认才可靠。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1035", "t": "案例分析题", "s": "放射科拟新增一间DR胸片诊断阅片室，医生需要在高亮度、高对比度、稳定的显示条件下对数字胸片进行诊断，同时希望多年使用中不同显示器、不同时段观片效果保持一致，以保障诊断质量与阅片一致性。技师负责提出显示设备选型建议。选型同时需考虑辐射防护要求与多年使用中显示效果的一致性。选择诊断显示设备时最应关注的是", "o": {"A": "屏幕尺寸越大越好", "B": "分辨率高且符合DICOM灰阶标准显示函数并定期校准", "C": "价格越低越好", "D": "可播放视频", "E": "支持无线充电"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-138", "kp": "诊断显示工作站要求", "ch": "十二、PACS技术 → 4.PACS临床应用 → (1)影像部门", "ex": "【为什么对】诊断显示器须具备足够分辨率与亮度，并遵循DICOM灰阶标准显示函数（GSDF）校准，保证不同显示器、不同时段观片效果一致，故B正确。\n【为什么错】A：尺寸需与观片距离匹配，并非越大越好。C：价格低可能牺牲亮度与灰阶性能。D：视频播放非诊断显示核心要求。E：无线充电与诊断显示无关。", "tr": "诊断显示的关键是“GSDF灰阶校准”与分辨率亮度达标，而非尺寸、价格等表面参数。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1036", "t": "案例分析题", "s": "某医院PACS服务器感染勒索病毒，系统文件与部分影像数据被加密，放射科图像调阅中断，临床工作受阻。医院信息部门开展应急响应与灾后重建，既要尽快恢复临床业务，又要防止事件重演，并确保影像数据完整可追溯。从系统安全角度，医院同时要求对存储数据加密、对访问行为留痕，并重新评估网络边界。下列措施中最为关键的是", "o": {"A": "将PACS直接接入互联网以便远程管理", "B": "从异地离线备份恢复数据，同时实施网络隔离与访问控制", "C": "关闭防火墙以提高网络速度", "D": "停止安装系统安全补丁", "E": "卸载杀毒软件避免误报"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-139", "kp": "PACS安全事件处置", "ch": "十二、PACS技术 → 2.PACS运行 → (3)系统安全", "ex": "【为什么对】离线备份未被病毒污染，可保证数据恢复，同时实施网络隔离、访问控制与补丁加固，防止再次感染，故B正确。\n【为什么错】A：接入互联网增加暴露面，风险更大。C：关闭防火墙削弱安全防线。D：不装补丁留下漏洞。E：卸载杀毒软件降低防护能力，均错误。", "tr": "勒索病毒应对核心是“离线备份可恢复+隔离加固防再犯”，安全措施只能加强不能削弱。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "国际标准和规范", "页": 348}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-1037", "t": "案例分析题", "s": "患者男性，48岁，因腹部疼痛行腹部CTA检查，图像存于PACS。骨科与普外科医师拟在科室会诊时共同查看CTA三维血管重建图像，讨论手术方案。两位医师均在各自科室的办公电脑上工作，科室未配备专用诊断级读片工作站，且需遵守医疗信息安全规定。科室信息化管理规定要求调阅影像必须经授权并保留审计记录。医师获取图像最便捷且符合合规要求的方式是", "o": {"A": "通过临床浏览工作站或Web版PACS授权调阅", "B": "借用放射科诊断工作站", "C": "打印胶片后翻拍照片", "D": "用手机拍摄屏幕照片", "E": "通过个人邮箱发送原始DICOM数据"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-PACS-140", "kp": "临床部门影像调阅", "ch": "十二、PACS技术 → 4.PACS临床应用 → (2)临床部门", "ex": "【为什么对】临床浏览工作站或Web版PACS经授权后可直接在临床科室调阅影像及三维重建结果，便捷且符合信息安全与合规要求，故A正确。\n【为什么错】B：借用放射科诊断工作站干扰诊断工作且不便利。C：打印胶片后翻拍失真且不利于诊断。D：手机拍摄屏幕照片质量差且不规范。E：通过个人邮箱传输原始影像存在隐私泄露风险，不合规。", "tr": "临床调阅应依托授权化、受控的PACS浏览通道，严禁拍照、邮箱等非合规方式传播影像。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U12-9009", "t": "单选题", "s": "PACS（影像归档与通信系统）在现代放射科的核心价值不包括", "o": {"A": "影像数字化存储，实现无胶片化", "B": "多终端远程调阅，支持临床快速获取", "C": "与 HIS/RIS 集成实现流程闭环", "D": "取代放射科医师的影像诊断工作", "E": "支持三维后处理与教学科研数据再利用"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-009", "kp": "PACS核心价值", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (2)应用评价", "ex": "【为什么对】D正确——PACS 是影像的采集、存储、传输与管理平台，辅助而非取代医师诊断；诊断仍由具备资质的医师完成。【为什么错】A、B、C、E均为 PACS 的确切价值：无胶片化降低耗材、远程调阅提高时效、与 HIS/RIS 集成优化工作流、海量数据支撑后处理与科研。", "tr": "PACS 是\"管理系统\"不是\"诊断系统\"，不替代医师。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U12-9010", "t": "单选题", "s": "厂商中立归档（VNA）在影像系统中的主要作用是", "o": {"A": "提高单一品牌设备的成像速度", "B": "以标准格式集中管理跨厂商、跨模态的影像与信息，降低厂商锁定风险", "C": "替代 DICOM 标准实现私有传输", "D": "仅用于急诊科的临时缓存", "E": "加密患者隐私使其无法被医师调阅"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-010", "kp": "厂商中立归档VNA", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (1)进展", "ex": "【为什么对】B正确——VNA 以厂商中立的方式（常基于标准 DICOM/HTML 等）长期归档影像与文档，使数据不绑定于某一 PACS 厂商，便于系统替换、跨院区共享与长期可访问，降低\"厂商锁定\"。【为什么错】A VNA 不改设备成像速度；C它恰恰建立在标准之上而非私有；D VNA 是长期归档而非临时缓存；E VNA 在受控权限下仍可被授权医师调阅，并非不可见。", "tr": "VNA 的价值在于\"中立/可移植\"，而非加速或加密屏蔽。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U12-9011", "t": "单选题", "s": "远程放射学（teleradiology）最典型的应用场景是", "o": {"A": "同一机房内两台 CT 之间的图像传输", "B": "基层或夜间将影像通过网络传至上级/远程中心由专家出具报告", "C": "用 U 盘拷贝影像至外院", "D": "取代现场 CT 设备", "E": "仅用于教学直播"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-011", "kp": "远程放射学应用", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (1)进展", "ex": "【为什么对】B正确——远程放射学利用网络将影像从采集端传至异地专家端，使基层、夜间或资源不足的机构也能获得及时的专业诊断，是 PACS 与广域网结合的典型应用。【为什么错】A属院内局域网常规调阅，非\"远程\"核心含义；C物理介质搬运非网络远程；D不取代设备；E教学仅为衍生用途。", "tr": "远程放射学的关键是\"异地专家诊断\"，不是单纯图像搬家。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U12-9012", "t": "单选题", "s": "评价 PACS 系统应用成效时，下列最应关注的指标组合是", "o": {"A": "显示器外观颜色与机房装修风格", "B": "系统可用性、影像调阅速度、存储成本与临床满意度（ROI）", "C": "仅关注设备采购价格", "D": "仅关注胶片节省数量", "E": "仅关注服务器 CPU 主频"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-012", "kp": "PACS应用评价维度", "ch": "十二、PACS技术 → 5.PACS进展与评价 → (2)应用评价", "ex": "【为什么对】B正确——PACS 评价应综合技术性能（可用性、调阅延迟、存储扩展）、经济与管理效益（成本、投资回报 ROI）及用户体验（临床满意度），才能真实反映系统价值。【为什么错】A外观与装修无关系统成效；C、D、E均属单一维度，片面评价会掩盖可用性、时效或满意度等关键问题。", "tr": "评价应多维（技术+经济+体验），不能用单一指标下结论。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U12-9101", "t": "多选题", "s": "关于 PACS 在临床部门中的应用，下列说法正确的有", "o": {"A": "影像科内部调阅、后处理与报告 Workflow", "B": "临床科室即时调阅患者影像与报告", "C": "远程会诊与双向转诊影像共享", "D": "作为教学与科研的影像数据库", "E": "可替代放射科医师作出诊断"}, "d": "易", "c": "记忆", "m": "专业实践能力", "u": "十", "un": "MR检查技术", "kpid": "KP-BU-12-9101-正高", "kp": "PACS临床应用范畴", "ch": "十二、PACS技术 → 4.PACS临床应用 → (补充)PACS临床应用", "ex": "【为什么对】A、B、C、D 正确：PACS 的核心价值在于影像的数字化存储、调阅、远程共享与教学科研；上述均为其典型临床应用。【为什么错】E 错误：PACS 是影像管理与显示工具，诊断决策仍必须由具备资质的放射科医师作出，系统不能替代诊断。", "tr": "注意 E 为典型干扰项——PACS 提升效率但不能替代医师诊断。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的临床应用", "页": 352}, "hf": false, "src": "补充", "mk": 1}, {"id": "ZG-U12-9201", "t": "单选题", "s": "PACS 中实现异地会诊主要依靠", "o": {"A": "网络传输与 DICOM 标准", "B": "胶片邮寄", "C": "暗室冲洗", "D": "增感屏", "E": "洗片机"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-9201", "kp": "PACS会诊", "ch": "十二、PACS技术 → 4.PACS临床应用", "ex": "【为什么对】PACS 借助网络与 DICOM 实现影像远程传输与异地会诊。\n【为什么错】胶片邮寄为传统方式。", "tr": "PACS会诊靠网络。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U12-9202", "t": "单选题", "s": "关于 PACS 在医院工作流程中的价值，错误的是", "o": {"A": "减少重复检查与胶片消耗", "B": "加快报告与调阅", "C": "完全消除医师诊断错误", "D": "支持多学科协作", "E": "便于教学与科研"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-CLIN-9202", "kp": "PACS价值", "ch": "十二、PACS技术 → 4.PACS临床应用", "ex": "【为什么对】PACS 提升效率与协作，但不能消除诊断错误（诊断仍依赖医师）。\n【为什么错】其余均为 PACS 价值。", "tr": "PACS不消除诊断错误。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的进展与应用评价", "页": 353}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U12-9203", "t": "单选题", "s": "PACS 与电子病历（EMR）集成的主要目的是", "o": {"A": "实现影像与临床信息的统一管理", "B": "替代医师", "C": "减少网络负载", "D": "降低分辨率", "E": "限制访问"}, "d": "易", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-9203", "kp": "PACS-EMR集成", "ch": "十二、PACS技术 → 5.PACS进展与评价", "ex": "【为什么对】PACS 与 EMR 集成使影像与临床信息互通，支持综合诊疗。\n【为什么错】集成不替代医师或降质。", "tr": "集成统一信息。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U12-9204", "t": "单选题", "s": "关于区域 PACS/影像协同平台，正确的是", "o": {"A": "支持分级诊疗与远程协作", "B": "仅单机使用", "C": "与基层无关", "D": "增加重复检查", "E": "降低可及性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十二", "un": "PACS技术", "kpid": "UNIT-12-ADV-9204", "kp": "区域PACS", "ch": "十二、PACS技术 → 5.PACS进展与评价", "ex": "【为什么对】区域 PACS 促进上下级医院影像共享、远程诊断，支撑分级诊疗。\n【为什么错】它减少而非增加重复检查。", "tr": "区域PACS助分级诊疗。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "PACS技术", "节": "PACS的运行", "页": 346}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U13-0101", "t": "单选题", "s": "关于医用图像打印技术的分类，正确的是", "o": {"A": "按成像原理可分为激光成像、热敏成像与喷墨成像；按是否需要化学处理可分为湿式与干式", "B": "干式打印是指打印后无需晾干的一种湿式冲洗方式", "C": "喷墨成像属于干式激光成像的一个分支", "D": "湿式激光打印不需要显影与定影处理", "E": "热敏成像必须以激光作为加热能量源"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-001", "kp": "医用图像打印技术分类", "ch": "十三、图像打印技术 → 1.概述 → (1)图像打印技术的分类与发展", "ex": "【为什么对】A正确：医用硬拷贝输出按成像原理分为激光成像、热敏（直热式）成像与喷墨成像三大类；按是否需要显影定影等化学处理，又分为湿式（需自动冲洗）与干式（无药液、无废液）两类，干式又包含干式激光（光热成像）与直热式热敏两种。【为什么错】B错误：干式的含义是不使用化学药液处理，而非“不用晾干的湿式冲洗”。C错误：喷墨与激光是并列的两类原理，喷墨以墨滴沉积成像，不涉及激光曝光。D错误：湿式激光胶片以卤化银为感光材料，必须经显影、定影、水洗、干燥。E错误：直热式热敏成像不使用激光，而是由热敏头直接接触加热胶片。", "tr": "务必分清两组概念：“激光/热敏/喷墨”是能量与成像方式的分类，“湿式/干式”是有无化学处理的分类。干式激光≠热敏，前者“先光后热”，后者“只热无光”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0102", "t": "多选题", "s": "关于医用打印机的网络化应用，下列正确的有", "o": {"A": "在DICOM打印管理服务中，打印机作为服务类提供者（Print SCP），影像工作站或设备作为服务类用户（Print SCU）", "B": "网络打印可实现多台影像设备共享同一台相机，并按1×1、2×2、4×5等不同分格排版输出", "C": "打印机接收的是经窗宽窗位处理后的图像数据，其最终灰阶还受打印机内部查找表（LUT）影响", "D": "DICOM打印管理服务类与影像存储（Storage）服务类是同一服务，配置其一即可", "E": "胶片规格、介质类型、放大方式、边框与注释等可通过打印作业的相关参数指定"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-002", "kp": "医用打印机与DICOM打印服务", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】A正确：DICOM打印管理中，发送打印请求的一方为SCU，执行打印的相机为SCP，二者需完成关联协商。B正确：网络化后一台相机可服务于CT、MR、DR等多台设备，分格排版由打印作业参数控制。C正确：影像经窗技术映射为显示灰度后，还要经打印机LUT映射为胶片光学密度，任一环节设置不当都会造成打印与显示不一致。E正确：这些均属于基本胶片盒与图像盒参数。【为什么错】D错误：打印管理服务类（Print Management）与存储服务类（Storage）是两类不同的DICOM服务类，各自有独立的SOP类与配置，二者不能互相替代。", "tr": "“打印出来与显示器上看到的不一致”是临床常见问题，其根源通常在打印机LUT或未按GSDF校准，而不在图像数据本身。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-0103", "t": "单选题", "s": "关于医用胶片规格与打印空间分辨率，下列叙述错误的是", "o": {"A": "常用胶片规格包括14in×17in（约35cm×43cm）、11in×14in、8in×10in等", "B": "打印空间分辨率常以每英寸点数（dpi）或像素尺寸（μm）表示，激光相机多为300~650dpi", "C": "分格打印时每幅图像被缩小，实际呈现的细节较满幅打印下降", "D": "打印像素尺寸越小，可分辨的图像细节越丰富", "E": "胶片规格越大，打印机的空间分辨率就越高"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-003", "kp": "胶片规格与打印分辨率", "ch": "十三、图像打印技术 → 1.概述 → (3)胶片规格与输出参数", "ex": "【为什么对】E错误故为本题答案：空间分辨率取决于打印机的成像单元尺寸（激光束斑或热敏头发热点大小）与扫描点密度，是设备固有性能，与所用胶片幅面无关；同一台相机打印大小两种规格胶片，其dpi不变。【为什么错】A正确：这是医用胶片的常见规格。B正确：主流激光相机的分辨率区间即在此范围。C正确：分格打印把同样的成像点分配给更小的图像面积，图像被缩小后细节呈现下降。D正确：像素尺寸越小意味着单位长度内的成像点越多，细节表现越好。", "tr": "分清“胶片幅面”“打印分辨率”“原始图像矩阵”三者：只有原始矩阵与打印分辨率共同决定最终细节，幅面只影响观看尺寸。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "概述", "页": 355}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0104", "t": "多选题", "s": "关于激光打印机（激光相机）的基本结构与工作过程，下列正确的有", "o": {"A": "主要由激光发生器、光学系统（调制器、多面转镜或振镜、聚焦透镜）、胶片传输机构与控制电路等组成", "B": "调制器根据图像各像素的灰度值调制激光束强度，从而实现不同的曝光量", "C": "转镜使激光束沿胶片宽度方向作主扫描，胶片匀速移动完成副扫描，二者配合完成逐点曝光", "D": "激光束在胶片上直接“烧灼”出可见影像，不需要任何显影过程", "E": "湿式激光相机需配套自动冲洗装置完成显影、定影、水洗与干燥"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-004", "kp": "激光打印机结构与工作过程", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】A正确：这是激光相机的经典结构划分。B正确：声光调制器等按像素灰度调节激光强度（或脉冲宽度），是灰阶得以再现的关键环节。C正确：主扫描（横向、由转镜实现）与副扫描（纵向、由胶片走动实现）正交配合，完成整幅图像的逐点曝光。E正确：湿式系统必须配套化学冲洗流程。【为什么错】D错误：激光相机中激光的作用是“曝光”，在胶片感光层内形成不可见的潜影，必须再经化学显影（湿式）或热鼓加热显影（干式）才能转变为可见银影，激光本身并不直接烧灼出图像。", "tr": "“激光直接烧出影像”是最常见的错误理解。牢记：激光只负责按灰度曝光形成潜影，显影环节才产生可见密度。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-0105", "t": "单选题", "s": "关于激光相机所用光源，下列叙述正确的是", "o": {"A": "早期湿式激光相机多采用氦氖（He-Ne）气体激光器，波长632.8nm，属可见红光", "B": "He-Ne激光的波长为1064nm，属于红外波段", "C": "半导体激光二极管体积大、寿命短，已被He-Ne激光器全面取代", "D": "激光相机光源的波长与所配套胶片的光谱感光特性无关，可任意搭配", "E": "干式激光相机采用紫外激光对胶片曝光"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-005", "kp": "激光相机光源类型", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】A正确：He-Ne激光器输出632.8nm的可见红光，是早期湿式激光相机的典型光源，需配用对该波长敏感的红光感光胶片。【为什么错】B错误：1064nm是Nd:YAG激光的波长，He-Ne为632.8nm。C错误：发展趋势恰好相反，红光或红外半导体激光二极管体积小、效率高、寿命长、可直接调制，已在现代激光相机中取代He-Ne气体激光器。D错误：胶片必须与光源波长的光谱敏感度匹配，错配将导致曝光不足或密度异常，故不同机型的专用胶片不可混用。E错误：干式激光相机使用的是红光或红外激光二极管，不是紫外激光。", "tr": "光源与胶片必须“波长匹配”是本考点的核心，也解释了为什么各厂家胶片与相机通常不能互换使用。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0106", "t": "多选题", "s": "关于湿式激光胶片与干式激光胶片的比较，下列正确的有", "o": {"A": "湿式胶片以卤化银乳剂为感光材料，曝光形成潜影后需经显影、定影、水洗与干燥", "B": "干式激光胶片曝光形成潜影后由热鼓加热显影，无需化学药液，也不产生冲洗废液", "C": "干式激光成像属于光热成像，其过程可概括为“先光曝光、后热显影”", "D": "干式胶片成像完成后不再受热与光的影响，可在任意条件下长期保存", "E": "干式打印省去冲洗环节，具有环境污染小、可明室操作、维护简便等优点，已成为主流"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-006", "kp": "湿式与干式激光胶片", "ch": "十三、图像打印技术 → 2.激光成像 → (2)激光胶片与光学密度", "ex": "【为什么对】A正确：这是传统湿式银盐胶片的处理流程，需要暗室或胶片传输通道、定期更换药液并处理废液。B正确：干式激光胶片依靠约120℃左右的热鼓短时加热完成显影。C正确：光热成像（photothermographic）的定义即为光曝光形成潜影＋加热显影。E正确：这些正是干式技术取代湿式的原因。【为什么错】D错误：干式胶片成像层内的未反应银盐与还原剂仍然留存于片内（无定影去除步骤），因此成品仍具有一定的热与光敏感性，长期置于高温或强光下可出现整体密度升高、影像退化，必须按厂家要求避光避热保存。", "tr": "干式胶片“没有定影”这一点是理解其保存要求的关键：未被消耗的成像物质仍在片中，所以“怕热怕光”，不能与经过定影的湿式胶片等同看待。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-0107", "t": "单选题", "s": "干式激光成像与直热式（热敏）成像的本质区别在于", "o": {"A": "干式激光成像由激光按灰度曝光形成潜影后再加热显影；直热式成像不使用激光，由热敏头直接按灰阶加热胶片形成影像", "B": "两者都使用激光，区别仅在于激光波长不同", "C": "干式激光成像需要化学显影液，直热式成像不需要", "D": "直热式成像所用胶片不含银盐成分", "E": "干式激光成像过程中不需要任何加热"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-007", "kp": "光热成像与直热式成像的区别", "ch": "十三、图像打印技术 → 2.激光成像 → (2)激光胶片与光学密度", "ex": "【为什么对】A正确：干式激光相机的能量传递路径是“激光曝光→潜影→热鼓加热显影”，属于光热成像；直热式热敏相机没有光学曝光环节，热敏头以点阵接触方式对胶片逐行加热，加热能量的大小直接决定该点的密度，属于纯热成像。【为什么错】B错误：直热式不使用激光。C错误：两者同属干式，均不使用化学显影液。D错误：直热式胶片的成像层同样含有有机银盐微晶与还原剂，受热后银离子被还原生成金属银形成黑影。E错误：干式激光成像的显影环节正是靠加热完成的。", "tr": "两类干式技术的判别口诀：“干式激光＝先光后热，直热式＝有热无光”。二者的胶片、耗材与故障表现均不相同，不可混用。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0108", "t": "案例分析题", "s": "某影像科对新安装的干式激光相机进行验收测试。技师打印标准21阶灰阶测试图，用透射式密度计逐阶测量，结果显示：片基加灰雾密度为0.18，最大密度为3.20，各阶密度分布连续、无跳跃与并阶。据此对该相机密度性能作出的判断，正确的是", "o": {"A": "最大密度与最低密度均落在医用胶片的常规要求范围内（一般要求最大密度≥3.0、片基加灰雾≤0.25），密度性能合格", "B": "光学密度定义为透过光强与入射光强之比，其数值越大表示胶片越透明", "C": "最大密度只取决于打印机的激光功率，与所用胶片类型无关", "D": "特性曲线直线部的斜率反映胶片的感光度，与影像对比度无关", "E": "片基加灰雾密度升高有助于提高影像的整体对比度"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-008", "kp": "光学密度与胶片特性曲线", "ch": "十三、图像打印技术 → 2.激光成像 → (2)激光胶片与光学密度", "ex": "【为什么对】A正确：医用胶片一般要求最大密度不低于3.0（观片灯下才能保证足够的黑化与对比），片基加灰雾密度不高于0.25（过高会使亮区“发灰”、丢失低密度层次）；本例3.20与0.18均在合格范围，且各阶连续无并阶，说明灰阶再现良好。【为什么错】B错误：光学密度D＝lg(I₀/I)，是入射光强与透过光强之比的常用对数，D值越大透光越少、胶片越黑。C错误：最大密度由胶片成像层的银量、显影条件与打印机能量共同决定，不同型号胶片的最大密度不同。D错误：直线部斜率γ表示的是对比度；感光度由特性曲线在横轴上的相对位置（达到某一密度所需曝光量）决定。E错误：灰雾升高会抬高低密度端，压缩可用密度范围，使对比度下降而非提高。", "tr": "感光度与对比度的区分是特性曲线的经典考点：曲线“左右移动”反映感光度变化，“陡缓变化”反映对比度变化，二者不可混为一谈。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0109", "t": "多选题", "s": "关于灰阶校准与DICOM灰度标准显示函数（GSDF），下列正确的有", "o": {"A": "GSDF是DICOM标准第14部分定义的、基于人眼对比敏感度模型的感知线性化函数", "B": "按GSDF进行校准，可使同一幅图像在不同显示器与打印机上获得一致的灰阶感知效果", "C": "GSDF以恰可察觉差（JND）指数描述亮度等级，相邻JND之间的差异恰为人眼可觉察", "D": "医用打印机的灰阶校准可通过打印测试图、以密度计测量各阶密度并据此修正查找表（LUT）来实现", "E": "GSDF仅适用于医用显示器，医用打印机无需遵循该标准"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-009", "kp": "灰阶校准与DICOM GSDF", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】A正确：GSDF建立在Barten人眼对比敏感度模型基础上，目的是把设备的物理输出（亮度或密度）映射为人眼感知上均匀的灰阶。B正确：一致性是GSDF的根本目的，可保证诊断结论不因输出设备而变化。C正确：GSDF用JND指数作为标度，标准中将可用亮度范围划分为若干JND步长。D正确：这正是打印机灰阶校准的实际操作流程，测量值与GSDF目标曲线的偏差通过LUT修正。【为什么错】E错误：GSDF同时适用于显示（发光）与硬拷贝（透射）设备，对打印机而言以透射密度对应亮度进行映射，医用胶片输出同样应按GSDF校准。", "tr": "GSDF不是“统一亮度或密度数值”，而是统一“感知”。校准后的显示器与相机在物理亮度、密度上可以不同，但人眼看到的灰阶层次变化是一致的。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-0110", "t": "单选题", "s": "关于直热式（热敏）打印的成像原理，下列叙述错误的是", "o": {"A": "热敏头由排列成线阵的微型发热电阻构成，与胶片直接接触逐行加热", "B": "影像灰阶由每个发热点的加热能量（脉冲宽度、温度）控制，能量越大该点密度越高", "C": "受热部位的有机银盐与还原剂发生反应，析出金属银微粒形成黑影", "D": "成像过程中无化学药液参与，也没有废液排放", "E": "热敏成像是以激光束扫描加热胶片实现的，属于光热成像范畴"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-010", "kp": "直热式热敏成像原理", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (1)直热式成像原理", "ex": "【为什么对】E错误故为本题答案：直热式热敏成像不使用任何光学曝光，其能量来源是热敏头电阻发热并通过接触传导至胶片；光热成像特指干式激光成像（先激光曝光形成潜影，后加热显影），二者不能混淆。【为什么错】A正确：热敏头（TPH）为接触式线阵结构，胶片走过时逐行加热。B正确：灰阶通过控制每个发热点的通电脉冲宽度与温度来实现，是热敏成像灰阶再现的基础。C正确：这是热敏胶片的成像化学过程。D正确：无药液、无废液是干式打印的共同优点。", "tr": "本题与干式激光成像题互为镜像。判断要点只有一个：有没有光学曝光环节——有则为光热成像（干式激光），无则为直热式热敏。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0111", "t": "单选题", "s": "关于热敏打印机的热敏头（TPH），下列叙述错误的是", "o": {"A": "热敏头与胶片直接接触传热，属接触式成像方式", "B": "常见热敏打印的点密度约为300~320dpi，空间分辨率一般略低于高端激光相机", "C": "热敏头表面沾污或个别发热电阻损坏，可造成沿走片方向的固定白线或黑线伪影", "D": "热敏头需要良好的散热与温度反馈控制，以保证连续打印时的密度稳定", "E": "热敏头发热点温度越高越好，可无限制地提高胶片的最大密度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-011", "kp": "热敏头结构与性能", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (2)热敏胶片与热敏头", "ex": "【为什么对】E错误故为本题答案：胶片的最大密度受成像层含银量与化学反应程度限制，达到饱和后再升温也不会继续增高密度；温度过高反而会损伤热敏头、造成胶片与热敏头粘连、保护层熔损与打印畸变，并加速热敏头老化。【为什么错】A正确：接触加热是直热式的基本特征，也决定了热敏头易受污染磨损。B正确：热敏点密度受发热电阻加工尺寸限制，通常略低于激光相机。C正确：单个发热点失效或污染在连续走片过程中形成沿纵向的固定线状伪影，是热敏相机的特征性故障表现。D正确：连续打印会导致热敏头蓄热，需依靠温度反馈动态调整加热能量，否则后续胶片密度会漂移。", "tr": "热敏相机的“固定位置线状伪影”与激光相机的“扫描方向条纹”定位思路不同：前者多为热敏头缺陷，后者多与转镜、激光调制或走片速度不稳有关。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0112", "t": "多选题", "s": "关于干式热敏胶片的结构与特性，下列正确的有", "o": {"A": "由片基、热敏成像层与表面保护层等构成，成像层内含有机银盐微晶、还原剂与调色剂", "B": "受热区域银离子被还原为金属银微粒，从而形成黑色影像", "C": "未受热区域的成像物质仍保留在胶片内，因此成品胶片应避热、避光保存", "D": "热敏胶片可在强光直射与高温环境下长期存放而不发生密度变化", "E": "表面保护层可减少胶片与热敏头之间的摩擦和粘连，保护热敏头"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-012", "kp": "热敏胶片结构与银盐微晶", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (2)热敏胶片与热敏头", "ex": "【为什么对】A正确：热敏胶片以有机银盐（如脂肪酸银）微晶为成像主体，配以还原剂与调色剂控制影像色调。B正确：受热处发生氧化还原反应析出金属银微粒，密度与析出银量成正比。C正确：因无定影步骤，未反应成分留存片内，属于本类胶片必须避热避光保存的根本原因。E正确：保护层兼具润滑与防粘作用，是保证热敏头寿命与打印质量的重要结构。【为什么错】D错误：与C相矛盾，高温与强光会使未反应的银盐继续被还原，出现整体密度升高、影像“发灰”甚至图像退化。", "tr": "把干式胶片的“无需暗室装片”误解为“不怕光”。正确表述是：明室装片可以（对室内一般照明不敏感），但不能强光直射与长期高温存放。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-0113", "t": "案例分析题", "s": "某院干式热敏相机近期打印的胸部影像出现两类质量问题：①整幅图像密度普遍偏低、层次发灰，与显示器所见明显不符，更换新一批胶片后无改善；②沿胶片长轴出现一条位置固定的细白线，贯穿所有打印张，更换胶片盒后依然存在。技师对上述问题进行排查分析，下列判断正确的是", "o": {"A": "问题①多与热敏头加热能量不足、走片速度过快、胶片批次与校准查找表不匹配或环境温度过低等因素有关，应重新执行密度与灰阶校准；问题②提示热敏头个别发热点损坏或表面污染，应先清洁热敏头，无效则更换热敏头", "B": "问题①与②均由PACS网络传输过程中的数据丢失引起，应重启网络交换机", "C": "问题①可通过提高诊断显示器亮度来解决", "D": "问题②是胶片乳剂面被划伤所致，与打印机无关，更换胶片品牌即可解决", "E": "问题①与②均提示X线平板探测器性能下降，应联系工程师更换探测器"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-013", "kp": "影响热敏打印质量的因素", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】A正确：热敏打印密度取决于“加热能量×作用时间”，能量不足、走片过快、环境温度过低或胶片型号批次与校准LUT不匹配，都会使整体密度下降、层次压缩，处理办法是核对胶片型号并重新校准；而位置固定、贯穿所有胶片的纵向白线是热敏头单点失效或污染的特征表现，因为该点在每次走片时都作用在同一横向位置。【为什么错】B错误：网络数据丢失会表现为图像缺失、错位或打印任务失败，不会造成整体密度偏低与固定线状伪影。C错误：显示器亮度与打印输出属于两个独立环节，调高显示器亮度只会让二者差异更大。D错误：更换胶片盒后伪影依旧，已排除胶片因素。E错误：探测器问题会在显示器上同样可见，而本例显示器所见正常。", "tr": "排查思路要抓“变量控制”：更换胶片后仍存在→问题在设备端；显示器正常而胶片异常→问题在打印链路而非采集链路。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0114", "t": "单选题", "s": "关于干式打印胶片的储存与使用，下列叙述错误的是", "o": {"A": "应在厂家规定的温湿度范围内避光保存，远离热源与阳光直射", "B": "干式胶片可在明室条件下装片，无需暗室操作", "C": "打印后的干式胶片长期置于高温环境，可出现密度升高或影像退化", "D": "不同厂家的干式胶片与打印机通常不能互换使用", "E": "干式胶片打印后可用普通定影液处理，以进一步提高其保存性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-014", "kp": "干式胶片的保存与使用", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】E错误故为本题答案：干式胶片的成像与显影过程完全不涉及液体化学处理，其成像层结构也不适合水溶液处理；用定影液浸泡会破坏保护层与成像层，造成影像损毁，绝不可这样操作。【为什么错】A正确：这是干式胶片的基本保存要求。B正确：干式胶片对室内一般照明不敏感，可明室装片，这是其操作便利性的体现。C正确：因未经定影，残留成像物质在高温下会继续反应。D正确：胶片的感光/感热特性、厚度与保护层均与特定机型的校准参数配套，混用会导致密度与灰阶异常甚至卡片。", "tr": "抓住“干式无定影”这一条主线，就能同时解释：为什么怕热怕强光、为什么不能用定影液、为什么胶片与机器必须配套。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "概述", "页": 355}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0115", "t": "单选题", "s": "关于喷墨打印的成像方式，下列叙述正确的是", "o": {"A": "按需喷墨主要有热气泡式与压电式两类，前者靠加热墨水产生气泡挤出墨滴，后者靠压电晶体形变挤出墨滴", "B": "喷墨打印属于银盐成像技术的一种", "C": "喷墨打印过程必须在暗室条件下进行", "D": "压电式喷墨依靠激光加热墨水形成墨滴", "E": "喷墨打印的墨滴大小不可控制，因而无法表现连续灰阶"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-015", "kp": "喷墨成像原理", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】A正确：喷墨按是否连续出墨分为连续式与按需式（DOD），按需式又分热气泡式（加热元件使墨水局部汽化形成气泡将墨滴挤出）与压电式（压电陶瓷通电变形挤压墨腔），这是喷墨技术的基本分类。【为什么错】B错误：喷墨以墨水（染料或颜料）沉积于介质表面成像，不含银盐感光成像过程。C错误：喷墨对光不敏感，完全可在明室操作。D错误：压电式不使用激光，加热的是热气泡式。E错误：现代喷墨可通过控制墨滴体积与网点密度（半色调技术）表现丰富的灰阶与色彩。", "tr": "热气泡式“用热”但与热敏成像完全不同：前者加热的是墨水以喷出墨滴，后者加热的是胶片成像层引发化学反应。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0116", "t": "多选题", "s": "关于喷墨成像在医学影像输出中的应用，下列正确的有", "o": {"A": "设备与耗材成本较低，可输出彩色图像，适用于报告、示教资料及超声、内镜图片的打印", "B": "多使用普通纸或专用相纸，透光性差，一般不适合在观片灯下阅读", "C": "最大光学密度与灰阶层次不及激光、热敏胶片，长期保存易褪色、遇水易扩散", "D": "喷墨输出的图像质量已达到诊断用医用胶片标准，可全面替代激光相机", "E": "喷墨输出可作为患者自取的辅助资料，正式诊断用影像仍以胶片或PACS电子影像为准"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-016", "kp": "喷墨成像的临床应用与局限", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】A正确：低成本与彩色输出能力使喷墨适合非诊断性的辅助资料输出。B正确：反射式介质需依靠环境光观看，与透射式胶片的观片灯阅读方式不同。C正确：染料墨水的密度范围与耐久性都明显不及银盐成像，是其难以用于诊断的核心原因。E正确：这是目前临床对喷墨输出的合理定位。【为什么错】D错误：喷墨在最大密度、灰阶层次、空间分辨率一致性与长期保存性上均不能满足诊断用硬拷贝要求，不能替代激光或热敏相机。", "tr": "喷墨在考纲中属“了解”层次，命题多围绕“定位”出题：它是辅助输出手段，优点是成本与彩色，缺点是密度、耐久与透光性，不能承担诊断职能。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-0117", "t": "单选题", "s": "关于医用照片自主（自助）打印机的应用，下列叙述错误的是", "o": {"A": "患者可凭检查条码单、就诊卡或身份证在自助终端查询本人影像并自助打印胶片与报告", "B": "自助终端需与PACS/RIS集成，打印前完成身份核验与权限控制", "C": "可减少人工发放胶片的工作量、缩短患者等待时间", "D": "终端应具备打印失败重试、耗材不足报警与操作日志记录等功能", "E": "为方便患者取片，自助终端应允许凭姓名模糊查询并打印他人影像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-017", "kp": "照片自主打印机的功能与管理", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】E错误故为本题答案：影像资料属于患者隐私与医疗数据，自助打印必须做到“一人一证一验”，凭唯一标识（条码、就诊卡、身份证或取件码）核验后才能调阅打印；允许姓名模糊查询将造成他人影像被误取或恶意获取，严重违反隐私保护与信息安全要求。【为什么错】A正确：这是自助打印的常规使用方式。B正确：与PACS/RIS集成并完成身份核验是自助打印的技术前提。C正确：分流取片人流、减少人工是其主要价值。D正确：无人值守设备必须具备异常处理与日志追溯能力。", "tr": "凡涉及自助设备与信息系统的题目，“便捷性”永远不能凌驾于“身份核验与隐私保护”之上，以便捷为由削弱核验的选项均为错误项。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-0118", "t": "案例分析题", "s": "某三甲医院在门诊大厅部署8台自助胶片打印终端。上线运行后陆续出现两类问题：部分患者反映“系统提示查不到影像”，但其检查确已完成；另有个别患者打印出的胶片分格方式与既往不同，图像明显缩小。信息科与影像技术组联合排查。下列排查方向与处理最合理的是", "o": {"A": "应核查检查是否已完成技师提交与报告审核并归档至PACS、终端与PACS之间的网络与DICOM服务是否正常，同时检查各终端的打印协议（分格、胶片规格、放大方式、查找表）是否与科室统一模板一致", "B": "“查不到影像”一定是打印机硬件故障，应逐台更换打印机", "C": "不同终端打印分格不同属于正常现象，无需统一", "D": "应取消身份核验环节以加快查询响应速度", "E": "应在开单时即自动打印所有检查的胶片，从根本上避免查询问题"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-018", "kp": "自助打印系统集成与故障排查", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】A正确：“查不到影像”的常见原因依次为检查未提交或报告未审核发布、影像尚未完整归档、终端与PACS网络或DICOM查询检索服务异常、患者标识匹配失败；“分格不一致”则属于终端打印协议配置不统一，应以科室统一模板批量下发并锁定，避免各终端参数漂移。【为什么错】B错误：查询失败属于数据与网络层面问题，与打印硬件无关，且不可能8台同时硬件故障。C错误：打印规格不统一会影响阅片一致性与外院互认，必须统一。D错误：取消身份核验会造成隐私泄露与错取，属严重违规。E错误：开单即打印会造成大量废片、增加成本，且此时检查尚未完成，逻辑上不成立。", "tr": "此类系统性问题应按“数据源—网络与服务—终端配置”的层级顺序排查；凡是以牺牲核验流程或大量浪费耗材为代价的“解决方案”都不可取。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1001", "t": "单选题", "s": "医用激光相机的成像核心部件是", "o": {"A": "激光扫描装置与激光胶片", "B": "热敏打印头", "C": "喷墨打印头", "D": "高压发生器", "E": "影像增强器"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-101", "kp": "激光相机结构", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】激光相机用激光扫描装置将图像信号逐点扫描到激光胶片上完成曝光，激光源与胶片是核心部件，故A正确。\n【为什么错】B：热敏打印头是热敏相机的部件。C：喷墨打印头是喷墨打印机的部件。D：高压发生器属于X线设备。E：影像增强器属于透视/DSA设备，均与激光相机无关。", "tr": "激光相机“激光扫描曝光”，热敏相机“热敏头加热”，喷墨“喷头喷墨”，三类设备核心部件不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1002", "t": "单选题", "s": "湿式激光相机与干式激光相机的根本区别在于", "o": {"A": "湿式需要化学药液（显影、定影）处理胶片", "B": "湿式不需要激光", "C": "干式需要显影液", "D": "干式使用普通纸张", "E": "两者原理完全相同"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-102", "kp": "湿式与干式激光成像", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】湿式激光相机曝光后需经显影、定影等化学药液处理成像，干式则采用干式热显影工艺无需药液，故A正确。\n【为什么错】B：湿式同样使用激光扫描。C：干式无需显影液。D：干式使用专用干式胶片而非纸张。E：两者成像原理（激光扫描）相同但显影工艺不同，不能说完全相同。", "tr": "干、湿式激光相机的差异在“显影方式”，激光扫描部分相同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1003", "t": "单选题", "s": "干式激光相机的突出优点是", "o": {"A": "无需化学药液、环保且即打即用", "B": "必须配备暗室", "C": "需要冲洗管路", "D": "必须使用湿式胶片", "E": "只能打印黑白图像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-103", "kp": "干式激光成像优点", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】干式激光相机无需显影、定影药液，无化学废液排放，设备紧凑，打印快速即打即用，故A正确。\n【为什么错】B：干式不需要暗室，可在明室使用。C：干式无需冲洗管路。D：干式使用专用干式胶片。E：干式激光相机同样可打印黑白诊断图像，也能支持彩色，说“只能打印黑白”不准确。", "tr": "干式打印机“明室操作、无药液、即打即用”是区别于湿式的三大特点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1004", "t": "单选题", "s": "直接热敏成像技术中，使胶片产生灰阶密度变化的部件是", "o": {"A": "热敏打印头（热敏头）", "B": "激光扫描器", "C": "喷墨喷嘴", "D": "影像增强器", "E": "光电倍增管"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-104", "kp": "热敏成像原理", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (1)直热式成像原理", "ex": "【为什么对】直接热敏（直热式）打印机依靠热敏打印头对热敏胶片加热，使其热敏层发生化学变化而显色，故A正确。\n【为什么错】B：激光扫描器是激光相机的部件。C：喷墨喷嘴是喷墨打印机部件。D：影像增强器属X线影像设备。E：光电倍增管用于光电探测，均与热敏加热成像无关。", "tr": "热敏成像的关键词是“加热”，热敏头加热→胶片显色。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1005", "t": "单选题", "s": "热敏打印机控制图像灰阶（密度）的主要方式是", "o": {"A": "调节热敏头的加热能量（温度与时间）", "B": "调节激光强度", "C": "更换墨盒颜色", "D": "调整胶片尺寸", "E": "改变纸张湿度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-105", "kp": "热敏打印灰阶控制", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (1)直热式成像原理", "ex": "【为什么对】热敏打印通过改变热敏头加热元件施加的能量（如脉冲宽度、功率），使胶片获得不同灰阶密度，故A正确。\n【为什么错】B：调节激光强度是激光相机控制曝光的方式。C：墨盒颜色是喷墨打印的概念。D：胶片尺寸不影响灰阶。E：湿度是环境因素而非控制手段。", "tr": "热敏打印“以热能控灰阶”，激光打印“以光强控灰阶”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1006", "t": "单选题", "s": "医用喷墨打印中，具有防水、耐光性能更好特点的墨水是", "o": {"A": "颜料墨水", "B": "染料墨水", "C": "食用墨水", "D": "热敏墨水", "E": "激光墨水"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-106", "kp": "喷墨墨水类型", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】颜料墨水以不溶性颜料颗粒悬浮为色料，附着力强，防水、耐光性能明显优于染料墨水，适合医学图像的长期保存，故A正确。\n【为什么错】B：染料墨水色彩鲜艳但易褪色、怕水。C：食用墨水与医学打印无关。D：热敏墨水概念不存在。E：激光打印用碳粉/胶片而非墨水。", "tr": "医用喷墨打印为保长期保存效果应选用颜料墨水，而非普通染料墨水。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1007", "t": "单选题", "s": "医用胶片常见的尺寸规格（英寸）不包括", "o": {"A": "14×17", "B": "8×10", "C": "10×12", "D": "11×14", "E": "20×30"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-107", "kp": "医用胶片规格", "ch": "十三、图像打印技术 → 1.概述 → (3)胶片规格与输出参数", "ex": "【为什么对】医用胶片常用规格为14×17、11×14、10×12、8×10等英寸规格，20×30不是医用常规胶片尺寸，故E正确。\n【为什么错】A：14×17是医用常规胶片尺寸。B：8×10是医用常规尺寸。C：10×12是医用常规尺寸。D：11×14是医用常规尺寸，均为常用规格故不符合题意。", "tr": "医用胶片用“英寸”表示尺寸，常用14×17、8×10等，属记忆考点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1008", "t": "单选题", "s": "照片自主打印机（自助取片机）与PACS、RIS对接获取打印任务，最常用的方式是", "o": {"A": "通过网络按患者条码或卡号调取已完成的影像与报告", "B": "人工U盘拷贝", "C": "电话人工预约", "D": "传真传输", "E": "邮寄胶片"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-108", "kp": "自助打印工作流程", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】自助打印机通过网络连接PACS/RIS，患者凭条码、就诊卡等识别身份后，系统自动调取已完成检查的影像与报告并打印，故A正确。\n【为什么错】B：U盘拷贝不适用大规模自助场景。C：电话预约是登记环节而非打印流程。D：传真不适合影像传输。E：邮寄胶片不具备即时性，均与自助打印不符。", "tr": "自助打印依托PACS/RIS的网络调取，以患者条码或卡号为身份凭证。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1009", "t": "单选题", "s": "为保证不同打印机、显示器之间图像显示一致，医用打印与显示系统应遵循的灰阶标准是", "o": {"A": "DICOM灰阶标准显示函数（GSDF）", "B": "JPEG压缩标准", "C": "MPEG视频标准", "D": "HL7消息标准", "E": "IHE集成框架"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-109", "kp": "灰阶校准标准", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】GSDF（Grayscale Standard Display Function）规定数字值与人眼感知亮度之间的标准关系，使打印胶片与显示器观片效果一致，故A正确。\n【为什么错】B：JPEG是图像压缩标准。C：MPEG是视频压缩标准。D：HL7是文本信息交换标准。E：IHE是应用集成框架，均非灰阶校准标准。", "tr": "GSDF是显示/打印灰阶一致性的核心标准，与其他DICOM服务、压缩标准区分。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1010", "t": "单选题", "s": "DICOM打印管理服务中，发出打印任务的一端称为", "o": {"A": "打印SCU（服务类用户）", "B": "打印SCP（服务类提供者）", "C": "影像存储SCP", "D": "查询/检索SCU", "E": "数据库服务器"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-110", "kp": "DICOM打印服务角色", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】DICOM打印服务中，发出打印请求的工作站/设备是服务类用户（SCU），打印机作为服务类提供者（SCP）接收并执行打印，故A正确。\n【为什么错】B：SCP是接收并执行的打印服务器/打印机。C：影像存储SCP是接收图像的归档端。D：查询/检索SCU用于调阅。E：数据库服务器与打印角色无关。", "tr": "SCU=请求方（发出打印任务），SCP=提供方（执行打印），方向勿颠倒。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1011", "t": "单选题", "s": "将多幅CT轴位图像以2×3等排版打印到一张14×17胶片上，应通过打印服务设置", "o": {"A": "胶片格式与排版布局", "B": "图像压缩比", "C": "存储路径", "D": "患者密码", "E": "网络带宽"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-111", "kp": "打印排版设置", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】DICOM打印服务支持定义胶片格式（尺寸）与排版布局（每张胶片上图像的行列数），实现多幅图像组合打印，故A正确。\n【为什么错】B：压缩比影响文件大小与存储。C：存储路径决定保存位置。D：患者密码与打印无关。E：网络带宽影响传输速度，均与排版无关。", "tr": "“几乘几排版”由打印服务胶片格式中的行列参数决定。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1012", "t": "单选题", "s": "激光相机中，像素灰度值（图像数据）对激光束的作用是", "o": {"A": "控制激光强度（曝光量）从而影响胶片密度", "B": "控制胶片尺寸", "C": "控制显影液温度", "D": "控制打印数量", "E": "控制网络速度"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-112", "kp": "激光成像灰度调制", "ch": "十三、图像打印技术 → 2.激光成像 → (2)激光胶片与光学密度", "ex": "【为什么对】图像数据经D/A转换后调制激光束强度，激光强度决定胶片感光量，感光量决定显影后的光学密度，实现灰度还原，故A正确。\n【为什么错】B：胶片尺寸由打印排版决定。C：激光相机（尤其干式）无显影液温控概念。D：打印数量由任务管理决定。E：网络速度属传输层，均与像素灰度成像无关。", "tr": "灰度值→激光强度→曝光量→光学密度，是一条完整的激光成像信号链。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1013", "t": "单选题", "s": "热敏打印头的分辨能力通常用下列哪项描述", "o": {"A": "每毫米（或每英寸）打印点数", "B": "每幅图像字节数", "C": "胶片灰阶密度值", "D": "激光波长", "E": "打印速度（张/小时）"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-113", "kp": "热敏打印头分辨率", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (2)热敏胶片与热敏头", "ex": "【为什么对】热敏打印头由密集排列的加热元件组成，其分辨能力以单位长度（毫米或英寸）内加热点数表示，点数越多分辨率越高，故A正确。\n【为什么错】B：字节数反映数据量。C：光学密度反映胶片黑化程度。D：激光波长是激光相机参数。E：打印速度反映效率，均非分辨能力的度量。", "tr": "打印分辨率=单位长度点数（dpi或点/mm），与图像数据量、密度值不同概念。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1014", "t": "单选题", "s": "激光相机打印的胶片出现灰阶层次缺失、高光区域明显断层，首先应进行的处理是", "o": {"A": "重新校准灰阶（打印SMPTE测试片校准）", "B": "更换网络线缆", "C": "调整胶片尺寸", "D": "重新启动计算机", "E": "增加存储容量"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-114", "kp": "打印质量故障处理", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】灰阶断层、层次缺失多由灰阶校准漂移引起，打印SMPTE测试片并重新校准可恢复正确的灰阶映射，故A正确。\n【为什么错】B：网络线缆故障表现为任务无法传输而非灰阶异常。C：胶片尺寸影响版面不影响灰阶。D：重启计算机无法修复校准漂移。E：存储容量与打印灰阶无关。", "tr": "灰阶异常优先查“校准”，SMPTE测试片是验证打印灰阶的常用手段。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1015", "t": "单选题", "s": "干式激光相机实现激光到热的转换、进而使胶片显影的结构或原理是", "o": {"A": "激光束使胶片热敏层吸收光能转化为热能而显影", "B": "激光直接雕刻胶片", "C": "激光加热显影液", "D": "激光发射紫外线消毒", "E": "激光与胶片无任何作用"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-115", "kp": "干式激光成像原理", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】干式激光相机的胶片热敏层吸收激光光能后转变为热能，在热显影（加热鼓或加热板）作用下发生化学反应显影，即“光-热-化学”成像，故A正确。\n【为什么错】B：激光不雕刻胶片。C：干式无需显影液。D：紫外线消毒与成像无关。E：激光与胶片必然发生能量作用才能成像。", "tr": "干式激光成像本质是“光转热”，与直热式“电加热”路径不同但落点同为热敏层。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1016", "t": "单选题", "s": "医用彩色喷墨打印中，用于合成各种颜色的基本墨水色是", "o": {"A": "青、品红、黄（CMY）", "B": "红、绿、蓝（RGB）", "C": "黑、白、灰", "D": "黄、蓝、红", "E": "品红、青、绿"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-116", "kp": "喷墨打印颜色模型", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】彩色喷墨打印采用减色法，以青（Cyan）、品红（Magenta）、黄（Yellow）三色（加黑K成CMYK）合成各种颜色，故A正确。\n【为什么错】B：RGB是显示器发光的加色模型。C：黑白灰不是喷墨基础色组合。D：黄蓝红不是标准三原色组合。E：品红青绿缺少黄色，均非喷墨基础色。", "tr": "打印是减色法CMYK，显示是加色法RGB，两者颜色模型不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1017", "t": "单选题", "s": "热敏打印机打印的胶片整体偏白、密度不足，最可能的原因是", "o": {"A": "热敏头加热能量不足", "B": "墨水用完", "C": "激光功率过高", "D": "胶片尺寸设置错误", "E": "网络带宽不足"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-117", "kp": "热敏打印密度不足分析", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】热敏打印密度由加热能量决定，整体密度不足说明热敏头温度/能量偏低（如热敏头老化、清洁不良或能量设置过低），故A正确。\n【为什么错】B：热敏打印不用墨水。C：激光功率是激光相机的参数。D：胶片尺寸影响版面不影响密度。E：带宽影响传输速度，与成像密度无关。", "tr": "热敏打印“密度偏白→加热不足”，激光打印“密度偏白→曝光不足”，对应机制不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1018", "t": "单选题", "s": "患者在自助取片机上完成影像胶片与报告打印，正确流程是", "o": {"A": "扫描条码或刷卡验证身份→系统调取图像报告→自动打印→取走核对", "B": "任意触摸屏幕直接打印全部影像", "C": "告知护士姓名由护士代取", "D": "手机拍摄屏幕照片", "E": "等待电话通知后人工领取"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-118", "kp": "自助打印操作流程", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】自助打印通过条码/就诊卡验证身份，系统从PACS/RIS调取该患者的影像与报告自动打印，患者领取后核对，流程闭环，故A正确。\n【为什么错】B：须先验证身份避免信息泄露。C：人工代取违背自助设计且易错。D：手机拍照不具合规性。E：人工通知领取非自助流程，均错误。", "tr": "自助打印的前提是“身份验证+系统自动调取”，保障个人隐私与准确性。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1019", "t": "多选题", "s": "激光相机的组成部分包括", "o": {"A": "激光扫描系统", "B": "激光胶片", "C": "胶片传输与显影/热显影系统", "D": "灰度调制电路", "E": "热敏打印头"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-119", "kp": "激光相机组成", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】激光相机由激光扫描系统、灰度调制电路、激光胶片及传输、显影（湿式药液/干式热显影）系统等组成，故A、B、C、D正确。\n【为什么错】E：热敏打印头属于热敏成像设备，不属于激光相机。", "tr": "激光相机核心是“激光+胶片”，热敏头是热敏打印机的核心。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1020", "t": "多选题", "s": "热敏成像技术的优点包括", "o": {"A": "干式操作、无需化学药液", "B": "设备结构相对简单、即打即用", "C": "无废液排放、环保", "D": "成像灰度稳定且易于维护", "E": "必须使用湿式胶片"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-120", "kp": "热敏成像优点", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (1)直热式成像原理", "ex": "【为什么对】热敏打印干式操作无需药液、结构简单、即打即用、无废液排放环保、维护方便，故A、B、C、D正确。\n【为什么错】E：热敏打印使用专用热敏胶片，不是湿式胶片。", "tr": "热敏与干式激光同属“干式”打印，均不用化学药液。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1021", "t": "多选题", "s": "喷墨打印技术在医学图像输出中的特点包括", "o": {"A": "可实现彩色图像打印", "B": "使用颜料墨水可防水耐光", "C": "设备成本相对较低", "D": "可用于报告与图像的复合输出", "E": "打印无需任何耗材"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-121", "kp": "喷墨成像特点", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】喷墨打印支持彩色，颜料墨水防水耐光，设备与耗材成本较低，可同时输出图文报告，故A、B、C、D正确。\n【为什么错】E：喷墨打印需要墨水与纸张等耗材，并非无耗材。", "tr": "喷墨打印的耗材是墨水与介质，颜料墨水是长期保存的关键。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1022", "t": "多选题", "s": "DICOM打印管理服务支持的功能包括", "o": {"A": "定义胶片尺寸与格式", "B": "设置多幅图像排版布局", "C": "指定灰度与打印数量", "D": "管理打印任务状态", "E": "执行图像压缩算法"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-122", "kp": "DICOM打印管理功能", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】DICOM打印服务可设定胶片规格、排版布局、灰阶特性、打印份数并回报任务状态，故A、B、C、D正确。\n【为什么错】E：图像压缩由存储/传输环节处理，不属于打印管理服务功能。", "tr": "打印管理管“印什么、印多少、印成什么样”，不管数据压缩。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1023", "t": "多选题", "s": "影响打印胶片图像质量的因素包括", "o": {"A": "打印分辨率", "B": "灰阶校准状态", "C": "胶片光学密度特性", "D": "打印设备清洁与维护状况", "E": "患者姓名输入方式"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-123", "kp": "打印质量影响因素", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】分辨率决定细节，校准决定灰阶准确性，胶片密度特性决定层次，设备清洁维护影响均匀性与伪影，故A、B、C、D正确。\n【为什么错】E：患者姓名输入方式仅影响文字标注，与图像打印质量无关。", "tr": "打印质量由“分辨率+校准+介质+维护”共同决定，操作习惯不影响成像质量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1024", "t": "多选题", "s": "激光相机与热敏相机在成像原理上的主要区别包括", "o": {"A": "激光相机用激光束扫描曝光", "B": "热敏相机用热敏头加热显影", "C": "激光相机灰阶由激光强度调制", "D": "热敏相机灰阶由加热能量调制", "E": "两者均必须使用湿式化学显影"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-124", "kp": "激光与热敏成像原理比较", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】激光相机以激光束逐点扫描曝光、灰阶由激光强度调制；热敏相机以热敏头加热热敏胶片、灰阶由加热能量调制，故A、B、C、D正确。\n【为什么错】E：两者均支持干式工艺，无需湿式化学显影，说法错误。", "tr": "“光调制”与“热调制”是两类干式打印的根本区别，均不需药液。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1025", "t": "多选题", "s": "照片自主打印机应具备的功能包括", "o": {"A": "条码/就诊卡身份识别", "B": "胶片与报告双介质输出", "C": "与PACS/RIS网络互联自动调取", "D": "缺纸、卡纸等故障自动提示", "E": "自动判读影像并出具诊断"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-125", "kp": "自助打印机功能要求", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】自助打印机需身份识别、胶片/报告双介质输出、与PACS/RIS互联调取、故障自动提示保障无人值守运行，故A、B、C、D正确。\n【为什么错】E：诊断结论由医师出具，自助打印机不具备影像判读功能。", "tr": "自助机是“打印+分发”终端，诊断功能不属于其职责。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1026", "t": "多选题", "s": "医学图像打印可使用的输出介质包括", "o": {"A": "干式激光胶片", "B": "湿式激光胶片", "C": "热敏胶片", "D": "喷墨打印纸", "E": "荧光显示屏"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-126", "kp": "打印输出介质", "ch": "十三、图像打印技术 → 1.概述 → (1)图像打印技术的分类与发展", "ex": "【为什么对】干式/湿式激光胶片、热敏胶片、喷墨介质（相纸、胶片替代品）均为打印输出介质，故A、B、C、D正确。\n【为什么错】E：荧光显示屏是显示输出设备，不是打印介质。", "tr": "打印=硬拷贝（胶片/纸张），显示=软拷贝（屏幕），二者介质不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1027", "t": "多选题", "s": "保障医用打印输出质量的措施包括", "o": {"A": "定期打印SMPTE测试片校验", "B": "按DICOM GSDF进行灰阶校准", "C": "定期清洁打印头与光学系统", "D": "规范胶片存储环境", "E": "关闭打印机日志功能"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-127", "kp": "打印质量控制措施", "ch": "十三、图像打印技术 → 1.概述 → (3)胶片规格与输出参数", "ex": "【为什么对】SMPTE测试片可验证灰阶，GSDF校准保证一致性，清洁打印头/光学系统减少伪影，规范胶片存储避免受潮变质，故A、B、C、D正确。\n【为什么错】E：日志记录有助于故障排查与质量追溯，关闭日志不利质量控制。", "tr": "打印质控=测试片+校准+维护+环境，四者缺一不可。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1028", "t": "多选题", "s": "打印胶片整体发黑、密度过高的可能原因包括", "o": {"A": "激光相机曝光过度", "B": "热敏头加热能量过高", "C": "灰阶校准错误导致信号放大", "D": "胶片意外被可见光曝光", "E": "胶片受潮"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-128", "kp": "打印密度过高原因分析", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】激光曝光过度、热敏能量过高、校准错误均可使密度过高；胶片被可见光意外曝光也会整体变黑，故A、B、C、D正确。\n【为什么错】E：胶片受潮多导致灰雾与斑点，通常不会表现为整体密度明显增高。", "tr": "密度过高优先查“曝光/能量/校准”，密度不足同理反向排查。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "3D打印技术", "页": 369}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U13-1029a", "t": "单选题", "s": "【病例】某医院放射科新增一台干式激光相机用于CT胶片打印，需接入医院网络并与PACS打印服务器通信。技师负责初始配置与打印测试，并发现首张试打印胶片灰阶层次不佳。 要使CT工作站能够向新打印机发送打印任务，配置中最关键的是", "o": {"A": "配置打印机的网络地址并建立DICOM打印服务连接", "B": "调整显示器亮度", "C": "更换打印头", "D": "修改胶片厚度", "E": "升级操作系统"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-129", "kp": "打印网络配置", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】设备间通过DICOM打印服务通信，需正确配置打印机的IP地址并完成服务关联（AE Title等），CT工作站才能下发打印任务，故A正确。\n【为什么错】B：显示器亮度与打印无关。C：新打印机打印头正常，无需更换。D：胶片厚度非软件配置项。E：操作系统升级不解决打印连接问题。", "tr": "网络打印的前提是“IP+AE Title+DICOM打印服务”三要素配置正确。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1029b", "t": "单选题", "s": "试打印胶片灰阶层次差、亮部细节丢失，技师应首先采取的措施是", "o": {"A": "打印SMPTE测试片并重新进行灰阶校准", "B": "更换整箱胶片", "C": "加大网络带宽", "D": "增加打印机数量", "E": "关闭自动打片"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-130", "kp": "打印灰阶校准", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】新装机打印灰阶不佳，最常见原因是校准未完成或漂移，通过SMPTE测试片验证并按GSDF重新校准可恢复灰阶层次，故A正确。\n【为什么错】B：整箱胶片均异常可能性低，且不解决校准问题。C：带宽影响速度不影响灰阶。D：打印机数量与灰阶无关。E：关闭自动打片不能改善层次。", "tr": "新机灰阶问题“先校准后换料”，测试片是判断校准状态的标尺。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1030a", "t": "单选题", "s": "【病例】某医院门诊大厅配置多台照片自助打印机，与PACS和RIS互联，为每日大量门诊与住院患者提供胶片及报告自助领取服务。高峰时段常出现排队与设备报错。 患者到自助打印机取片时，系统识别患者身份并定位其影像报告，最常用的凭证是", "o": {"A": "检查条码或就诊卡号", "B": "患者自报姓名", "C": "手机内随意拍摄的旧照片", "D": "口头描述检查时间", "E": "任意身份证复印件"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-131", "kp": "自助打印身份识别", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】检查条码、就诊卡号是系统唯一识别并调取对应检查数据的关键索引，故A正确。\n【为什么错】B：同名患者多，姓名不可靠。C：旧照片与本次打印无关。D：口头描述无法精确检索。E：身份证复印件不直接关联检查号。", "tr": "自助打印调取数据依赖唯一标识（条码/卡号），而非模糊信息。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1030b", "t": "单选题", "s": "针对高峰时段排队拥堵，最有效的工程管理措施是", "o": {"A": "合理调配打印任务队列并增加自助机数量、错峰引导", "B": "取消条码验证提高速度", "C": "关闭部分打印机", "D": "改为全人工取片", "E": "提高单张胶片分辨率"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-132", "kp": "自助打印运行管理", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】任务队列优化、增加设备数量与错峰引导可均衡负载、缓解排队，是行之有效的管理手段，故A正确。\n【为什么错】B：取消身份验证引发隐私与错发风险。C：关闭打印机加剧拥堵。D：人工取片效率更低。E：分辨率提高只改善画质，不解决排队。", "tr": "自助打印管理核心是“容量规划+队列优化+流程引导”，不能牺牲安全换取速度。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1031a", "t": "单选题", "s": "【病例】某台热敏打印机在使用中打印的胶片上出现固定的白色条纹，同一位置反复出现，其他区域打印正常，且条纹不随图像内容改变。技师排查故障原因并处理。 胶片上出现固定位置白色条纹，最可能的原因是", "o": {"A": "热敏头对应位置加热元件损坏或脏污", "B": "网络丢包", "C": "胶片整批受潮", "D": "灰阶校准错误", "E": "打印机电源电压波动"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-133", "kp": "热敏打印条状伪影", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (2)热敏胶片与热敏头", "ex": "【为什么对】固定位置的连续白条且与图像内容无关，典型原因是热敏头上对应加热点损坏（不加热）或被异物遮挡，该处无法显影形成白条，故A正确。\n【为什么错】B：网络丢包造成任务失败而非固定条纹。C：胶片受潮表现为灰雾、斑点，非固定细条纹。D：校准错误影响整体灰阶。E：电压波动多引起整体密度变化，均不符合固定条纹特征。", "tr": "“固定位置+与图像无关”的条纹指向打印头缺陷，而非图像数据或校准问题。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1031b", "t": "单选题", "s": "针对上述白条故障，正确的处理步骤是", "o": {"A": "先清洁热敏头，无效则更换热敏头", "B": "直接更换全部胶片", "C": "重启网络交换机", "D": "重新设置胶片尺寸", "E": "调高显示器伽马"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-134", "kp": "热敏打印故障处理", "ch": "十三、图像打印技术 → 3.热敏成像技术 → (3)影响热敏打印质量的因素", "ex": "【为什么对】脏污引起的白条经清洁可恢复，若加热元件已损坏则须更换热敏头，由简到繁处理，故A正确。\n【为什么错】B：胶片本身正常，更换无意义。C：网络设备不影响成像条纹。D：胶片尺寸与白条无关。E：显示器伽马与打印输出无关。", "tr": "硬件性条纹的处理顺序是“清洁→更换”，勿在成像链条外排查。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "热敏成像技术", "页": 361}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1032", "t": "案例分析题", "s": "某放射科新购进一台干式激光相机并接入DICOM打印网络。技师使用SMPTE测试片试打印后发现：灰阶带基本可见，但高亮度区段层次丢失、部分相邻灰阶带无法区分。临床科室随后反映部分CT片肋骨与软组织对比显示不佳。技师需在保证诊断质量的前提下解决问题。打印任务由CT设备经DICOM打印服务下发至干式激光相机。正确的处理措施是", "o": {"A": "按DICOM GSDF重新执行灰阶校准并复查SMPTE测试片", "B": "立即报废该打印机", "C": "加大图像压缩比", "D": "将所有图像改为喷墨打印", "E": "缩短扫描范围"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-135", "kp": "打印灰阶校准流程", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】高光层次丢失提示灰阶映射不准，按GSDF重新校准可恢复全灰阶段层次，并以SMPTE测试片验证效果，故A正确。\n【为什么错】B：仅校准偏差即报废设备不当。C：压缩比不影响打印灰阶且降低数据质量。D：更换打印方式成本高且非必要。E：扫描范围与灰阶显示无关。", "tr": "高光/暗部层次丢失首先想到灰阶校准，SMPTE测试片是质控验证工具。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1033", "t": "案例分析题", "s": "某医院影像科计划更新打印设备，原有湿式激光相机需频繁更换化学药液，药剂排放需专门处理，设备占用空间大且运行成本高。科室日均打印量约200张胶片，要求明室操作、即打即用、环保节能并保证影像诊断质量。在选择新设备时，新设备需能通过DICOM打印服务接收CT、MR、DR多源任务，并支持SMPTE测试片定期质控。最合适的方案是", "o": {"A": "更换为干式激光相机或热敏相机", "B": "继续采购同型号湿式激光相机", "C": "改用普通家用喷墨打印机打印诊断片", "D": "取消胶片打印全部电子化", "E": "使用手机打印照片"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-136", "kp": "打印设备选型", "ch": "十三、图像打印技术 → 2.激光成像 → (1)激光打印机结构与成像原理", "ex": "【为什么对】干式激光或热敏相机无化学药液、明室操作、即打即用、环保，且成像质量满足诊断要求，故A正确。\n【为什么错】B：湿式仍需药液处理与排污。C：家用喷墨不满足诊断片质量与长期保存要求。D：完全取消胶片不符合临床对硬拷贝的需求。E：手机打印照片不具备医用资质。", "tr": "选型权衡“质量、成本、环保、操作便捷”，干式设备综合最优。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "概述", "页": 355}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1034", "t": "案例分析题", "s": "某放射科使用干式激光相机打印CT轴位图像，常规设置每张14×17胶片打印2×3共6幅图像。医生反映单幅图像偏小、细节观察困难，希望放大显示关键层面，同时不希望增加胶片耗材种类。技师在不增加耗材种类的情况下改进打印方案。打印排版通过DICOM打印服务胶片格式参数设置，技师可调整每张胶片的行列布局。最合适的做法是", "o": {"A": "将胶片排版改为每张胶片打印更少的图像（如1×2）或按窗口分组放大关键层面", "B": "将图像分辨率降低一半", "C": "改用8×10小胶片打印6幅", "D": "每张胶片打印12幅", "E": "不打印直接看屏幕"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-137", "kp": "打印排版与幅面规划", "ch": "十三、图像打印技术 → 1.概述 → (2)网络打印与打印服务", "ex": "【为什么对】减少每张胶片的图像数可放大单幅尺寸，或对关键层面分组打印，直接改善观察效果，故A正确。\n【为什么错】B：降低分辨率损害细节，适得其反。C：小胶片打6幅更小。D：每张12幅进一步缩小画面。E：屏幕浏览与胶片需求并存，不能完全替代打印。", "tr": "排版数量与单幅大小成反比，放大观察靠减少幅数而非降低分辨率。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1035", "t": "案例分析题", "s": "某医院门诊大厅的自助打印机无法从PACS调取当日新检查的影像，但人工打印工作站打印正常，自助机界面提示“连接失败”。技师需按网络与系统分层排查故障，尽快恢复自助取片服务，避免影响患者就医体验。自助机与PACS之间采用标准DICOM与网络协议通信，人工工作站与自助机共用同一PACS服务。下列排查步骤中顺序最合理的是", "o": {"A": "先查自助机网络连通性，再查打印服务配置与PACS侧服务状态", "B": "先更换打印机主板", "C": "先删除PACS全部数据", "D": "先调整胶片价格", "E": "先重装操作系统"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-138", "kp": "自助打印故障排查", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】“人工正常、自助机连接失败”提示故障在自助机网络链路或其与PACS的服务配置，按“连通性→服务配置→服务状态”由简到繁排查最合理，故A正确。\n【为什么错】B：无故障征兆即更换主板属盲目维修。C：删除数据造成严重破坏。D：价格与连接无关。E：重装系统是最后手段而非首选。", "tr": "网络故障排查遵循“物理层→网络层→服务层”逐级定位，避免暴力处置。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1036", "t": "案例分析题", "s": "某科室打印的DR胸片在强光灯下观察时，肺野密度区呈均匀一致，原有细小肺纹理与支气管影层次显示不清，而同一图像在医用显示器上显示正常。技师怀疑打印环节存在灰阶压缩或校准问题，需要定位故障环节。胶片为同一批干式激光胶片，打印链路包括图像传输、灰度映射、激光曝光与热显影各环节。上述环节中任一处异常均可能导致胶片灰阶表现异常，需结合测试片逐项定位。最可能的原因是", "o": {"A": "打印灰阶校准漂移导致灰度映射压缩", "B": "显示器故障", "C": "患者体位错误", "D": "探测器损坏", "E": "胶片尺寸错误"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-139", "kp": "打印灰阶压缩分析", "ch": "十三、图像打印技术 → 2.激光成像 → (3)灰阶校准与DICOM GSDF", "ex": "【为什么对】显示器正常而胶片层次丢失，说明问题在打印链路，灰阶校准漂移使灰度范围被压缩，细小密度差异无法区分，故A正确。\n【为什么错】B：显示器正常已排除。C：体位错误影响解剖显示而非层次压缩。D：探测器异常在源图像即显现，显示器上应同样异常。E：胶片尺寸影响版面不影响层次。", "tr": "“屏幕正常、胶片层次差”锁定打印链路，灰阶校准是首要怀疑对象。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-1037", "t": "案例分析题", "s": "某医院自助打印区内，患者反映打印的报告与胶片数量经常出错，部分患者未取到报告，投诉增多。技师调查发现部分检查只生成了胶片打印任务而未生成报告打印任务，导致报告缺失。为保障打印任务完整性，自助打印系统按检查号关联胶片与报告任务，报告由RIS在医师审核发布后自动生成。任务缺失与检查状态、报告发布时机及系统触发配置密切相关。最有效的改进措施是", "o": {"A": "在RIS发布报告后自动联动生成报告打印任务，与胶片任务统一管理", "B": "要求患者次日再来", "C": "取消报告打印", "D": "仅打印胶片", "E": "人工逐张复印报告"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-140", "kp": "打印任务完整性管理", "ch": "十三、图像打印技术 → 5.照片自主打印机 → (1)自助打印流程与管理", "ex": "【为什么对】以RIS报告发布事件为触发源自动生成报告打印任务，与胶片任务统一入库、合并输出，可保证胶片与报告任务齐全，故A正确。\n【为什么错】B：让患者次日再来是消极应对，延误取件。C：取消报告打印损害患者权益。D：仅打印胶片仍缺报告。E：人工逐张复印报告效率低且易出错。", "tr": "任务完整性依赖“流程触发自动化”，以报告发布驱动打印任务生成。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U13-9013", "t": "单选题", "s": "喷墨成像技术在医疗打印中被称为绿色、低碳、环保的新技术，其主要原因是", "o": {"A": "必须使用银盐胶片才能成像", "B": "通过喷嘴喷射微小墨滴组成像素，无需显影、定影等化学处理，耗材更环保", "C": "成像过程产生大量废水需专门处理", "D": "仅能打印黑白影像", "E": "必须使用高温定影，能耗极高"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-009", "kp": "喷墨成像环保特性", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】B正确——喷墨打印由无数喷嘴将墨滴直接喷到专用介质形成像素，属于物理喷墨、无需显影定影等湿化学工艺，设备与耗材更环保、低碳，符合绿色医疗趋势。【为什么错】A喷墨不依赖银盐胶片；C其优势恰是减少化学废水；D现代喷墨支持彩色；E喷墨多为常温喷墨，能耗低于热定影工艺。", "tr": "喷墨的\"环保\"来自省去显影定影化学步骤，而非墨本身。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U13-9014", "t": "单选题", "s": "关于喷墨、激光与热敏三类医用打印技术的区别，正确的是", "o": {"A": "三者均需显影定影化学工艺", "B": "喷墨为喷嘴喷射墨滴成像，激光为激光扫描潜影后显影定影，热敏为热敏头直接加热显影", "C": "热敏成像必须使用墨盒", "D": "激光打印完全不需任何光学部件", "E": "喷墨打印分辨率最低、不可用于诊断"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-010", "kp": "三类打印技术区别", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】B正确——喷墨由喷嘴物理喷射墨滴；激光经激光扫描形成静电潜影再显影定影；热敏由加热头直接对热敏介质加热显影，三者机理各异。【为什么错】A喷墨与干式热敏多不需湿化学显影定影；C热敏依靠热敏介质而非墨盒；D激光打印必含激光与光路；E喷墨可达诊断级分辨率。", "tr": "区分\"显影定影工艺\"（激光有、喷墨/干式热敏无）是常考点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U13-9015", "t": "单选题", "s": "医用喷墨打印机通常使用的成像介质是", "o": {"A": "仅供普通复印纸", "B": "专用喷墨打印纸或喷墨胶片，避免普通纸渗墨与分辨率不足", "C": "仅限银盐胶片", "D": "必须是热敏纸", "E": "任何纸张均等效"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-011", "kp": "喷墨打印介质", "ch": "十三、图像打印技术 → 4.喷墨成像技术 → (1)喷墨成像原理与应用", "ex": "【为什么对】B正确——喷墨成像需匹配专用喷墨纸或喷墨胶片，其涂层可吸收并固定墨滴、保证分辨率与保存性；普通纸易渗墨、晕染，影响影像质量与存档。【为什么错】A普通复印纸不耐墨；C喷墨不依赖银盐；D热敏纸属热敏工艺；E介质差异显著影响成像，不可等效。", "tr": "喷墨务必用\"专用介质\"，普通纸会严重降质。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "喷墨打印成像技术", "页": 364}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U13-9201", "t": "单选题", "s": "医用喷墨打印（医疗影像）的主要特点是", "o": {"A": "采用液态染料/颜料按需喷射成像", "B": "利用激光扫描", "C": "热敏发色", "D": "银盐感光", "E": "干式激光"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-9201", "kp": "喷墨原理", "ch": "十三、图像打印技术 → 4.喷墨成像技术", "ex": "【为什么对】医用喷墨按需喷射液态墨水在介质上成像，属非银盐数字打印。\n【为什么错】激光/热敏/银盐为其他技术。", "tr": "喷墨=液态墨水喷射。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U13-9202", "t": "单选题", "s": "喷墨打印相对于激光打印的优势通常是", "o": {"A": "连续色调与低运行成本", "B": "极高速度", "C": "永久不褪色", "D": "无需介质", "E": "分辨率无限"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-9202", "kp": "喷墨优势", "ch": "十三、图像打印技术 → 4.喷墨成像技术", "ex": "【为什么对】喷墨可实现连续色调且运行成本较低；速度与永久保存性通常不及激光/银盐。\n【为什么错】极高速度非其优势。", "tr": "喷墨优势=连续色调/低成本。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "激光成像", "页": 357}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U13-9203", "t": "单选题", "s": "干式激光相机（自显机）相比湿式冲洗的优点是", "o": {"A": "无需暗室与化学药液、即打即取", "B": "分辨率无限高", "C": "必须暗室", "D": "需大量水", "E": "速度极慢"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十三", "un": "图像打印技术", "kpid": "UNIT-13-PRT-9203", "kp": "干式相机优点", "ch": "十三、图像打印技术 → 5.照片自主打印机", "ex": "【为什么对】干式激光相机无需暗室与湿化学处理，操作简便、即打即取。\n【为什么错】湿式才需暗室与药液。", "tr": "干式相机无需暗室药液。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "图像打印技术", "节": "胶片报告自助打印机", "页": 366}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U14-0101", "t": "单选题", "s": "关于下肢全长负重摄影，下列叙述错误的是", "o": {"A": "患者双足站立于同一水平面，双侧髌骨朝向正前方，以消除下肢旋转造成的测量误差", "B": "照射野应包括双侧髋关节（股骨头）至踝关节，一次成像获得双下肢全长影像", "C": "应采用较大的源像距（一般不小于180cm）以减小放大与几何失真", "D": "图像用于测量下肢机械轴（髋-膝-踝角）、评估膝内外翻及人工关节置换术前规划", "E": "为减少辐射剂量可改为仰卧位摄影，其力线测量结果与站立负重位等效"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-001", "kp": "下肢全长负重摄影", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】E错误故为本题答案：负重位的意义在于反映生理负荷状态下的真实力线，关节间隙狭窄程度、内外翻角度在卧位与站立位之间可有明显差异；仰卧位测得的机械轴不能替代站立位结果，故临床要求必须站立负重摄影。【为什么错】A正确：髌骨朝前是控制股骨旋转的关键，旋转会显著影响HKA角测量。B正确：完整包含股骨头与踝关节中心才能确定机械轴的两个端点。C正确：大源像距可减小锥形束造成的边缘放大与失真，提高测量准确性。D正确：这些正是全长负重摄影的主要临床用途。", "tr": "“负重”二字是本考点的核心。凡是把站立位换成卧位、把双足并拢换成随意站姿、把髌骨朝前换成足尖朝前的选项，都会带来测量偏差。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0102", "t": "案例分析题", "s": "患者女性，14岁，因青少年特发性脊柱侧弯定期随访，临床要求摄站立位全脊柱正、侧位片以测量Cobb角并评估冠状面与矢状面平衡。该患者近3年内已多次接受同类检查，家长对辐射剂量表示担忧。技师采用站立位全脊柱拼接摄影。下列技术方案与操作要点，正确的是", "o": {"A": "正位采用站立后前位投照，可显著降低甲状腺、乳腺的受照剂量；侧位时双上肢向前抬起屈肘、躯干保持直立不旋转；照射野上缘包含颈椎下部至颅底区、下缘包含双侧髂嵴与股骨头；同时使用附加滤过、严格准直与低剂量方案控制剂量", "B": "正位必须采用前后位投照，否则无法准确测量Cobb角", "C": "侧位摄影时双上肢应自然下垂紧贴体侧，以免影响脊柱位置", "D": "为提高图像清晰度，应将源像距缩短至100cm", "E": "每次随访均应更换投照体位与方式，以便获得更多角度的信息"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-002", "kp": "脊柱全长负重摄影", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】A正确：后前位投照使X线先经过背部，甲状腺与乳腺处于出射侧，其受照剂量较前后位显著降低，对需要反复随访的青少年女性尤为重要；侧位双上肢前抬屈肘可避免肱骨与胸椎重叠；照射野需覆盖测量所需的全部解剖标志；附加滤过、准直与低剂量方案是剂量优化的常规手段。【为什么错】B错误：Cobb角测量依据椎体终板连线，后前位同样可准确测量，且是国际推荐体位。C错误：上肢下垂会使肱骨与上胸椎重叠，影响上端椎判断。D错误：缩短源像距会加重放大失真并增加皮肤入射剂量，全长摄影恰恰需要大源像距。E错误：随访检查应保持体位与技术条件一致，才能进行前后对比，随意更换会导致测量不可比。", "tr": "青少年脊柱侧弯随访的两大要点：一是“后前位降低乳腺甲状腺剂量”，二是“随访条件一致性”。二者都是命题高频点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0103", "t": "多选题", "s": "关于全脊柱、全下肢负重摄影的图像质量与辐射防护，下列正确的有", "o": {"A": "采用后前位投照、附加滤过与严格准直，可降低甲状腺、乳腺与性腺的受照剂量", "B": "增大源像距可减小锥形束造成的边缘放大与几何失真", "C": "对儿童与青少年随访者应使用低剂量方案，并对射线敏感器官做好屏蔽", "D": "由于照射野长、散射线增多，需合理选择滤线栅与曝光参数", "E": "分段曝光拼接由于每段剂量较低，患者所受总剂量必定低于一次长片摄影"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-003", "kp": "全长摄影的质量控制与防护", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】A正确：体位与准直是最有效的器官剂量控制手段。B正确：源像距越大，射线束越接近平行，边缘放大差异越小。C正确：儿童与青少年组织敏感性高且随访次数多，剂量优化尤为重要。D正确：长照射野散射线明显增加，需权衡滤线栅带来的图像对比改善与剂量增加。【为什么错】E错误：分段拼接的总剂量取决于分段数、各段曝光条件与重叠区大小，重叠区会被重复照射，总剂量并不必然低于一次长片摄影；剂量高低应以实测面积剂量乘积等指标评价，不能想当然。", "tr": "“分段＝低剂量”是错误直觉。重叠区重复曝光与分段数增多都会抬高总剂量，评价剂量必须看整体指标而非单段曝光条件。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-0104", "t": "单选题", "s": "关于DR图像拼接技术的实现方式，下列叙述正确的是", "o": {"A": "常用方式包括球管与探测器同步移动、多次分段曝光后由软件自动拼接，以及采用长条形探测器或狭缝扫描一次成像", "B": "拼接图像只能由技师在后处理软件中手工剪贴完成", "C": "分段曝光时球管位置固定不动，仅探测器移动即可保证各段几何关系一致", "D": "拼接技术要求相邻分段之间完全不留重叠区域", "E": "拼接技术仅适用于四肢长骨，不能用于脊柱"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-004", "kp": "DR图像拼接技术的实现方式", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】A正确：目前主流实现方式有两类，一是多次分段曝光后自动拼接（球管与探测器同步平移或球管作角度旋转跟踪），二是长条探测器或狭缝扫描式一次采集，二者均可获得超出单幅探测器视野的全长图像。【为什么错】B错误：现代设备均具备基于重叠区灰度与解剖特征的自动配准拼接算法，手工剪贴只是特殊情况下的补充。C错误：若球管固定而仅探测器移动，边缘段的射线入射角将严重偏斜，造成明显几何失真与截断，必须使球管与探测器协同运动。D错误：足够的重叠区正是配准的依据，无重叠无法保证接缝准确。E错误：拼接技术最主要的应用恰恰是全脊柱与全下肢。", "tr": "分段拼接的几何前提是“球管与探测器同步”，这是与后续几何畸变校正考点直接相关的核心概念。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0105", "t": "多选题", "s": "关于DR拼接图像的几何畸变及其校正，下列正确的有", "o": {"A": "锥形束X线在各分段边缘的入射角与放大率不同，若直接叠加会造成接缝处结构错位与长度测量误差", "B": "增大源像距、严格准直，并使球管的旋转中心与探测器运动保持同步，可减小几何畸变", "C": "相邻分段保留足够重叠区，利用重叠区内的解剖标志或标尺刻度进行配准，可提高拼接精度", "D": "标尺所在平面与被测结构所在平面相距越远，二者放大率差异越大，长度测量误差也越大", "E": "只要软件自动拼接成功，拼接图像上的长度测量结果即与实际长度完全一致"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-005", "kp": "拼接图像几何畸变校正", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】A正确：这是拼接技术最核心的技术难点——中心射线区放大率最小、边缘区放大并倾斜投影，直接拼合必然出现错位。B正确：这三项是硬件与几何层面的基本对策。C正确：重叠区提供了配准所需的共同特征，重叠不足是拼接失败的常见原因。D正确：放大率由“焦点-物平面距离”决定，标尺若远离被测结构平面（例如贴在探测器面板上而被测骨骼位于体内），其换算关系将不成立，产生系统性测量误差。【为什么错】E错误：即便拼接在视觉上连续，仍存在残余几何误差与放大率不确定性，术前测量应结合标尺校正与临床复核，不能认为与实际长度完全一致。", "tr": "“拼得好看”不等于“测得准确”。测量精度依赖于标尺位置、几何校正与患者制动三方面，缺一不可。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-0106", "t": "单选题", "s": "关于拼接摄影中标尺（带刻度金属尺或铅字标记）的使用，下列叙述错误的是", "o": {"A": "标尺应完整置于照射野内并贯穿各分段，为分段配准提供参考基准", "B": "标尺应尽量贴近被测结构所在平面，以减小放大率差异带来的测量误差", "C": "标尺可用于校正图像放大率，提高长度与角度测量的准确性", "D": "标尺被肢体或衣物遮挡，或在分段曝光间发生移位，会导致拼接与测量错误", "E": "只要使用自动拼接软件，标尺即可省略，对测量精度没有影响"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-006", "kp": "拼接标尺的作用与放置", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】E错误故为本题答案：自动拼接软件解决的是分段图像的对齐问题，而放大率校正需要已知实际长度的物理参照物；缺少标尺时无法把图像上的像素距离换算为真实长度，人工关节假体尺寸规划等测量将失去依据。【为什么错】A正确：贯穿各段的标尺同时提供配准特征与长度基准。B正确：标尺与被测结构越接近同一平面，二者放大率越一致。C正确：这是标尺最主要的功能。D正确：遮挡与移位是拼接与测量错误的常见原因，摆位时应确认标尺固定且不被覆盖。", "tr": "标尺有“配准基准”和“长度校正”双重作用，其中长度校正无法被软件替代——这是本题的关键区分点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0107", "t": "案例分析题", "s": "患者男性，68岁，双膝骨关节炎，拟行人工全膝关节置换，术前需摄双下肢全长站立位拼接片以测量下肢力线并规划截骨。图像回顾发现：股骨干在第1、2段接缝处出现明显错位成角，标尺刻度在接缝处不连续，测得的髋-膝-踝角与临床查体所见明显不符。作为技师，对该问题的分析与处置，正确的是", "o": {"A": "最可能是分段曝光间隔期间患者重心移动、站立不稳，或重叠区不足、标尺发生移位导致自动配准失败；应重新交代屏气与保持站立不动、必要时使用站立支架固定，适当加大重叠区并确认标尺牢固贴附后重新摄影", "B": "该表现为平板探测器坏点所致，需联系工程师更换探测器", "C": "属于拼接接缝的正常表现，可直接用于术前测量", "D": "通过调整窗宽窗位使接缝显示不明显后即可进行测量", "E": "应改用双能量减影去除软组织后重新测量下肢力线"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-007", "kp": "拼接失败原因分析与处置", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】A正确：接缝处错位成角＋标尺刻度不连续，是典型的分段间相对位移证据。老年患者站立时间长易疲劳晃动，是最常见原因；处理应从患者固定（站立支架、扶手）、缩短分段间隔、加大重叠区、固定标尺等方面入手并重新采集，绝不能用错位图像作术前测量。【为什么错】B错误：探测器坏点表现为固定位置的点线状缺陷，不会造成结构成角错位与标尺不连续。C错误：错位接缝会带来数度的力线测量误差，直接影响截骨方案，属不合格图像。D错误：窗技术不改变几何关系。E错误：双能量减影用于软硬组织分离，与拼接错位无关，且骨性力线测量并不需要去软组织。", "tr": "凡是“标尺不连续”，几乎可以直接锁定为分段间发生了相对位移；这是判断拼接失败原因最直观的客观证据。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0108", "t": "单选题", "s": "关于数字体层融合（tomosynthesis）的成像原理，下列叙述正确的是", "o": {"A": "X线管在有限角度范围内运动，采集一系列低剂量投影，经重建算法生成一组平行于探测器的任意深度断层图像", "B": "X线管需围绕人体旋转360°采集投影数据", "C": "需要重建多少层断层图像，就必须相应地曝光多少次", "D": "数字体层融合重建得到的是横断面（轴位）图像", "E": "数字体层融合的辐射剂量高于同部位的CT检查"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-008", "kp": "数字体层融合成像原理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】A正确：数字体层融合是传统体层摄影的数字化发展，X线管在有限角度内一次扫描采集数十幅低剂量投影，通过位移叠加或滤波反投影、迭代等算法，可回顾性重建出不同深度、平行于探测器的多层图像。【为什么错】B错误：360°旋转采集是CT的特征，体层融合为有限角度。C错误：一次扫描的投影数据可重建任意多层图像，不需要逐层曝光，这正是相对传统体层摄影的巨大优势。D错误：其重建平面平行于探测器，即冠状面或与摆位平面一致的断层，而非横断面。E错误：体层融合的总剂量通常相当于数次普通摄影，远低于同部位CT。", "tr": "把体层融合当作“低配CT”是常见误区。二者在采集角度、重建平面与分辨率各向异性上有本质区别，体层融合的断层平面平行于探测器。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0109", "t": "多选题", "s": "关于数字体层融合图像的特性，下列正确的有", "o": {"A": "层内（平行于探测器方向）空间分辨率高，接近常规DR图像", "B": "深度（Z轴）方向分辨率有限，重建层厚不能任意减小", "C": "一次采集可回顾性重建不同深度的多层图像，层间距可根据需要调整", "D": "有限角度采集会残留层外结构的模糊影与波纹状伪影", "E": "其密度分辨率与各向同性重建能力与多层螺旋CT相当"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-009", "kp": "数字体层融合图像特性", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】A正确：层内分辨率由平板探测器像素决定，可达到DR水平，明显高于常规CT的层内分辨率。B正确：有限角度采样导致Z轴方向信息不足，重建层厚受扫描角度限制。C正确：一次采集、多层重建、层距可调是数字化体层的核心优势。D正确：层外结构不能被完全消除，会以模糊影或波纹（ripple）伪影残留于重建层内，是有限角度重建的固有缺陷。【为什么错】E错误：受有限角度、探测器动态范围与散射线影响，体层融合的密度（低对比）分辨率明显低于CT，且重建体素严重各向异性，不能实现真正的各向同性重建。", "tr": "评价体层融合要抓“各向异性”这一关键词：层内好、层间差；其价值在于以低剂量去除重叠，而非替代CT的容积成像。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-0110", "t": "单选题", "s": "关于数字体层融合的临床应用，下列叙述错误的是", "o": {"A": "可提高肋骨、腕舟骨等隐匿性骨折的检出率", "B": "用于含金属内固定物的术后随访时，其金属伪影一般较CT轻", "C": "可用于肺内小结节的检出与随访，辐射剂量低于胸部CT", "D": "可与静脉尿路造影结合显示肾盂输尿管，减少肠气与骨骼的重叠干扰", "E": "因其属于断层成像，可完全替代CT用于复杂骨盆骨折的三维评估"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-010", "kp": "数字体层融合的临床应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】E错误故为本题答案：复杂骨盆骨折需要评价骨折线的空间走行、关节面塌陷程度与移位方向，必须依赖各向同性的容积数据与多平面重组、三维重建，而体层融合的Z轴分辨率有限、无法生成可靠的横断面与三维模型，不能替代CT。【为什么错】A正确：去除重叠后隐匿骨折的显示率明显提高，是骨关节应用的主要价值。B正确：体层融合对金属的伪影表现主要为条状模糊，通常轻于CT的严重放射状与暗带伪影，有利于观察假体周围骨质。C正确：其剂量相当于数次胸片，远低于胸部CT，适合部分随访场景。D正确：这是传统体层摄影在尿路造影中的经典应用在数字化条件下的延续。", "tr": "体层融合的应用定位是“在DR基础上去除重叠”，凡是把它抬高到可以替代CT的选项都应排除。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0111", "t": "多选题", "s": "关于DR双能量减影的两种实现方式，下列正确的有", "o": {"A": "两次曝光法在极短时间间隔内先后以低管电压与高管电压各曝光一次，两次采集的能谱分离较好", "B": "两次曝光法的两次采集之间存在时间差，心脏搏动与呼吸运动可造成运动性伪影", "C": "单次曝光法采用前后叠置的双层探测器（中间夹铜滤过板），一次曝光同时获得低能与高能图像", "D": "单次曝光法无时间差、不产生运动性伪影，但两层探测器接收的能谱重叠较多，减影效果与信噪比略差", "E": "单次曝光法的能谱分离程度优于两次曝光法"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-011", "kp": "DR双能量减影实现方式", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】A正确：两次曝光可分别选择差异明显的高、低管电压并配合不同滤过，能谱分离好，减影后组织分离彻底。B正确：即使间隔仅约200ms，心脏搏动与不完全屏气仍可造成心缘、膈肌处的运动伪影，这是两次曝光法的主要缺点。C正确：这是单次曝光法的典型硬件结构，铜板对前层透过的射线进行硬化滤过，使后层探测器接收较高能量成分。D正确：无运动伪影是其优势，但能谱重叠使物质分离能力与信噪比下降。【为什么错】E错误：单次曝光法的能谱分离明显不如两次曝光法，这正是其减影质量受限的原因，选项把二者优劣说反。", "tr": "两种方法各有取舍：两次曝光“能谱分离好但怕运动”，单次曝光“不怕运动但能谱分离差”。命题常把两者优点张冠李戴。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-0112", "t": "单选题", "s": "DR双能量减影能够将骨组织像与软组织像分离开来，其物理基础是", "o": {"A": "骨（钙）与软组织的X线衰减系数随光子能量变化的规律不同，对高、低能两幅图像作对数加权减影可选择性消除其中一种组织", "B": "骨组织与软组织的有效原子序数相同，仅密度存在差异", "C": "在高管电压条件下软组织对X线完全不产生衰减", "D": "骨组织只发生相干散射，软组织只发生光电效应", "E": "双能量减影依赖于对比剂中碘的K吸收边缘特性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-012", "kp": "骨组织像与软组织像的分离原理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】A正确：钙的有效原子序数明显高于软组织，低能时光电效应占比大、衰减急剧增加，高能时以康普顿效应为主、二者差异缩小；因此两种组织的“衰减—能量”曲线形状不同，对两幅不同能量图像取对数后按适当权重相减，即可使其中一种组织的信号相互抵消，得到软组织像或骨组织像。【为什么错】B错误：骨（含钙、磷）的有效原子序数显著高于软组织，这正是能量依赖差异的来源。C错误：任何能量下软组织都有衰减，只是程度不同。D错误：两种组织中光电效应与康普顿效应均存在，只是占比随能量与原子序数变化。E错误：碘的K边缘是血管造影能量减影的基础，胸部平片双能减影针对的是钙与软组织，与对比剂无关。", "tr": "注意区分两个“双能”：DSA中的K边缘能量减影针对碘，DR胸部双能量减影针对钙（骨），二者物理基础与临床目的不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0113", "t": "案例分析题", "s": "患者男性，55岁，吸烟史30年，因体检行胸部DR检查，正位片示右上肺野一直径约1.2cm的结节影，部分被后肋与锁骨重叠，难以判断结节内部有无钙化。临床希望在不立即行CT的情况下获得更多信息，技师建议加做胸部双能量减影。关于本例的技术分析，正确的是", "o": {"A": "软组织像可去除肋骨与锁骨的重叠影、突出显示肺内结节；骨组织像有助于显示结节内的钙化成分，对良恶性的初步判断有参考价值；但双能量减影不能替代CT定性，且两次曝光法需要良好屏气配合以避免运动伪影", "B": "双能量减影可直接测量结节的CT值，实现钙化的定量分析", "C": "双能量减影采用单次曝光完成，患者所受剂量低于常规胸部平片", "D": "软组织像用于显示钙化，骨组织像用于突出显示肺内结节", "E": "结节位于肺尖区时双能量减影效果最佳，且完全不受呼吸与心搏运动的影响"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-013", "kp": "胸部双能量减影的临床应用与局限", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】A正确：软组织像去骨后可显著提高被肋骨遮蔽区域结节的检出与边缘评价；钙化含钙成分在骨组织像上得以保留显示，有助于判断结节是否为良性钙化灶；但双能减影仍是投影成像，不能定性诊断，且两次曝光法对运动敏感，需充分屏气。【为什么错】B错误：CT值是CT容积扫描的定量指标，投影成像不能测量CT值。C错误：无论两次曝光还是单次曝光，双能量减影的总剂量都不低于并通常略高于常规胸片。D错误：软组织像与骨组织像的用途被完全说反。E错误：肺尖区受锁骨与肋骨重叠影响大，双能减影确有帮助，但“完全不受运动影响”不成立，两次曝光法尤其受呼吸与心搏影响。", "tr": "记住组合关系：“软组织像看结节、骨组织像看钙化”。同时不要把投影成像的能量减影与CT的能谱定量混为一谈。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0114", "t": "多选题", "s": "关于乳腺X线摄影的靶面与滤过组合，下列正确的有", "o": {"A": "钼（Mo）靶的特征X线能量约为17.5keV与19.6keV，适用于较薄的脂肪型乳腺", "B": "铑（Rh）靶特征X线能量（约20.2keV与22.7keV）高于钼靶，适用于较厚、较致密的乳腺", "C": "Mo/Rh组合利用铑滤过的K吸收边缘，使较高能量光子得以通过，可降低厚乳腺的受照剂量", "D": "数字乳腺机常用钨（W）靶配合铑或银滤过，可在保持对比度的同时降低平均腺体剂量", "E": "乳腺摄影应尽量选用较高管电压（大于50kV）以提高软组织对比度"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-001", "kp": "乳腺摄影靶面与滤过组合", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (1)乳腺X线检查设备", "ex": "【为什么对】A正确：钼靶特征X线能量低，软组织对比最佳，适合薄而脂肪成分多的乳腺。B正确：铑靶特征能量更高，穿透力更强，适用于厚而致密的乳腺以控制曝光时间与剂量。C正确：滤过材料的K吸收边缘会滤掉高于该边缘的部分光子并塑形能谱，Mo/Rh组合让能谱整体上移，兼顾穿透与对比。D正确：钨靶轫致辐射产额高、热容量大，配合Rh、Ag滤过成为数字乳腺与DBT的主流选择，可在同等图像质量下降低平均腺体剂量。【为什么错】E错误：乳腺各软组织成分的衰减差异极小，只有在低能范围（管电压一般为25~32kV）才能获得足够对比；管电压过高会使对比度急剧下降，超过50kV完全不符合乳腺摄影的成像要求。", "tr": "乳腺摄影与常规摄影的思路相反：常规摄影常用高kV降剂量，乳腺摄影必须用低kV保对比，靶/滤过的选择就是在“对比度”与“剂量、曝光时间”之间寻求平衡。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-0115", "t": "单选题", "s": "关于乳腺X线摄影自动曝光控制（AEC）的使用，下列叙述错误的是", "o": {"A": "AEC探测器应置于腺体最厚、最致密的区域下方，通常靠近胸壁侧", "B": "全自动模式可先行短时预曝光，据乳腺厚度与密度自动选择靶/滤过组合、管电压与管电流量", "C": "压迫板测得的乳腺压迫厚度信息可参与AEC的曝光决策", "D": "假体植入或存在大片钙化时可能干扰AEC判断，必要时改用半自动或手动模式", "E": "AEC选点应置于乳腺边缘的脂肪区，以避免中央区曝光过度"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-002", "kp": "乳腺摄影自动曝光控制", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (1)乳腺X线检查设备", "ex": "【为什么对】E错误故为本题答案：若把AEC探测器放在薄的脂肪区，系统会因该处透过量迅速达标而提前切断曝光，导致腺体致密区曝光严重不足、信噪比低、病灶被噪声淹没；正确做法是选在腺体最厚最致密处，保证诊断关键区域获得足够的曝光量。【为什么错】A正确：这是AEC选点的基本原则，乳腺后部靠近胸壁处腺体通常最厚。B正确：预曝光自动优选靶/滤过与kV是现代乳腺机的标准功能。C正确：压迫厚度是决定曝光参数的重要输入量。D正确：高密度假体或大片钙化会使局部透过量异常，需人工干预。", "tr": "AEC探测点“宁厚勿薄”。这与普通摄影中AEC选点原则一致：探测野必须覆盖诊断上最重要、衰减最大的区域。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0116", "t": "单选题", "s": "关于乳腺X线摄影中滤线栅的使用，下列叙述正确的是", "o": {"A": "乳腺摄影多采用聚焦式移动栅，栅比常为4:1~5:1，曝光过程中栅条运动以消除栅线影", "B": "乳腺摄影常规使用栅比12:1以上的高栅比滤线栅，以最大限度去除散射线", "C": "使用移动滤线栅不会增加受检者的辐射剂量", "D": "乳腺放大摄影时应使用高栅比滤线栅以保证图像质量", "E": "乳腺摄影因组织较薄，散射线可忽略，故一律不使用滤线栅"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-003", "kp": "乳腺摄影滤线栅", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (1)乳腺X线检查设备", "ex": "【为什么对】A正确：乳腺摄影使用专用低栅比（约4:1~5:1）聚焦式移动栅，栅密度较高；低栅比是因为乳腺摄影管电压低、散射线相对有限，同时必须严格控制剂量；曝光中栅条往复移动可将栅线影模糊掉。【为什么错】B错误：高栅比会大幅增加曝光量与腺体剂量，不适用于乳腺。C错误：使用滤线栅会吸收部分原发射线，必须提高曝光量，受检者剂量随之增加。D错误：放大摄影采用气隙技术减少散射线，不使用滤线栅，同时须使用微焦点（约0.1mm）以保证放大图像的清晰度。E错误：常规接触摄影仍需滤线栅来改善对比度。", "tr": "“放大摄影不用滤线栅、改用气隙并配微焦点”是乳腺摄影的高频考点，常与常规接触摄影的滤线栅要求放在一起设混淆项。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0117", "t": "单选题", "s": "关于数字乳腺体层合成（DBT）的采集方式，下列叙述正确的是", "o": {"A": "X线管在有限角度（不同厂家总扫描角度约15°~50°）范围内采集约9~25幅低剂量投影，重建出层厚通常为1mm的平行断层图像", "B": "X线管需绕乳腺旋转360°采集投影数据", "C": "每重建一层断层图像就需要单独压迫并曝光一次", "D": "DBT重建得到的是矢状面断层图像", "E": "DBT的采集角度越小，深度方向分辨率越高"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-004", "kp": "DBT扫描角度与投影数", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】A正确：DBT在一次压迫下由X线管在有限角度内快速扫描，采集十余至二十余幅低剂量投影，重建为一叠平行于探测器（即平行于压迫板）的断层，层厚多为1mm，各厂家在扫描角度与投影数上的取舍不同。【为什么错】B错误：360°旋转是CT的采集方式。C错误：一次采集即可重建全部层面，这正是相较传统体层的根本优势，也避免了反复压迫。D错误：重建平面平行于探测器，对CC位而言近似横断面方向的断层、对MLO位则平行于该投照平面，并非矢状面。E错误：角度越小深度分辨率越差，恰恰说反。", "tr": "DBT的“有限角度”是理解其一切优缺点的钥匙：既带来低剂量、快速采集，也决定了Z轴分辨率有限与层外伪影残留。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0118", "t": "多选题", "s": "关于DBT扫描角度、投影数与图像质量之间的关系，下列正确的有", "o": {"A": "扫描角度越大，深度（Z轴）方向分辨率越好，层外结构模糊得越彻底", "B": "扫描角度增大意味着采集时间延长，运动模糊风险与患者压迫不适随之增加", "C": "在总剂量一定的前提下，投影数增多则每幅投影的剂量降低、噪声增大，需依靠重建算法加以抑制", "D": "DBT的Z轴分辨率明显低于层内分辨率，其重建体素为各向异性，不能视为真正的各向同性断层", "E": "只要不断增加投影数量，DBT即可达到与CT相同的深度分辨率"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-005", "kp": "DBT角度、投影数与Z轴分辨率", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】A正确：深度分辨率主要取决于扫描角度所决定的采样锥角，角度越大，层外结构在重建层内被弥散得越充分。B正确：大角度必然延长采集时间，压迫状态下的时间延长会带来运动模糊与患者耐受性问题，这是厂家在角度选择上折中的原因。C正确：DBT总剂量受限，投影数与单幅剂量成反比，需靠迭代等算法平衡噪声。D正确：各向异性是DBT的固有特征。【为什么错】E错误：深度分辨率的根本限制来自有限角度采样造成的频域数据缺失，单纯增加同一角度范围内的投影数只能改善采样密度与噪声，不能补足缺失的角度信息，因此永远无法达到CT的深度分辨率。", "tr": "区分“角度范围”与“投影数量”两个变量：前者决定深度分辨率上限，后者影响采样密度与噪声；把二者混为一谈是本考点的主要失分点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-0119", "t": "多选题", "s": "关于DBT与全视野数字乳腺摄影（FFDM）的联合应用及合成二维图像（C-View等）的应用，下列正确的有", "o": {"A": "DBT与FFDM联合采集时，一次检查的总平均腺体剂量约为单独FFDM的两倍", "B": "由DBT数据重建生成的合成二维图像可替代FFDM，使总剂量接近单独FFDM的水平", "C": "合成二维图像保留了二维整体观并可强化微钙化的显示，便于与既往FFDM作对比", "D": "合成二维图像需要另外增加一次独立的低剂量曝光单独采集", "E": "DBT断层可减少腺体组织重叠造成的“假病灶”，有助于降低召回率"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-006", "kp": "DBT与FFDM联合应用及合成2D", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】A正确：DBT与FFDM各自曝光一次，联合方案的腺体剂量约为单独FFDM的两倍，这是推动合成二维图像发展的直接动因。B正确：以合成二维替代FFDM可省去一次曝光，使总剂量回落至接近单独FFDM水平。C正确：合成图像通过对断层数据的投影与增强处理，可突出显示微钙化并提供整体观，满足与历史片对比的需要。E正确：减少组织重叠所致的假阳性、降低召回率是DBT最重要的临床获益之一。【为什么错】D错误：合成二维图像由已采集的DBT投影与重建数据经算法生成，不需要任何额外曝光，这正是其降低剂量的原理所在。", "tr": "“合成二维”不是“再拍一张”，而是“算出来的一张”。理解这一点才能正确回答与剂量相关的所有衍生问题。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-0120", "t": "案例分析题", "s": "患者女性，46岁，无症状筛查者，既往乳腺X线检查提示腺体致密（BI-RADS腺体密度c类），并因腺体重叠所致的可疑结构扭曲两次被召回复查、复查后均为阴性。本次患者对再次召回与辐射剂量均有顾虑，希望技师给出合适的检查方案。关于技术方案的选择与告知，正确的是", "o": {"A": "对致密型乳腺，DBT可减少腺体重叠遮蔽、提高浸润性癌检出并降低召回率；为控制剂量，可采用“DBT＋合成二维图像”方案替代“DBT＋FFDM”，其总剂量接近单独FFDM水平", "B": "致密型乳腺应避免使用DBT，因其剂量为FFDM的10倍以上", "C": "DBT对微小钙化的显示明显优于FFDM，可完全取代二维图像", "D": "致密型乳腺应直接行乳腺MRI，无需再行乳腺X线检查", "E": "DBT单次压迫的平均腺体剂量远超监管限值，因此不宜用于筛查"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-007", "kp": "DBT对致密型乳腺的应用与剂量", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】A正确：致密型乳腺是DBT获益最大的人群，断层成像可将重叠腺体逐层分开，既提高浸润性癌检出率，又减少因腺体重叠造成的假性结构扭曲与召回；结合合成二维图像可在保留二维整体观的同时把总剂量控制在接近单独FFDM的水平，是兼顾效益与剂量的合理方案。【为什么错】B错误：DBT单次采集的平均腺体剂量与FFDM同量级，联合FFDM约为两倍，绝非10倍。C错误：DBT在微钙化簇的整体形态与分布判断上并不优于二维图像，钙化常分散于多个层面，因此需要二维或合成二维图像配合，不能完全取代。D错误：MRI敏感度虽高但特异度较低、成本高、不适合作为普通致密型乳腺的一线筛查手段。E错误：DBT的平均腺体剂量仍在监管限值范围内，可以用于筛查。", "tr": "剂量类选项要有量级感：DBT与FFDM同量级，联合约2倍，合成二维可回落至约1倍。凡出现“10倍”“远超限值”一类夸大表述均为错误项。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-0121", "t": "单选题", "s": "关于DBT的局限性与配套技术，下列叙述错误的是", "o": {"A": "单次检查产生数十至上百幅断层图像，数据存储量大、医师判读时间延长", "B": "成簇微钙化可分布于多个断层层面，其形态与分布的整体判断有时不如二维图像直观", "C": "对仅在DBT上显示的病灶，需要配备DBT引导下的定位或穿刺活检技术", "D": "有限角度采集使层外结构不能被完全消除，图像上可残留伪影", "E": "由于DBT为断层成像，检查时不再需要对乳腺进行充分压迫"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-MAM-008", "kp": "DBT的局限性与配套技术", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】E错误故为本题答案：DBT同样需要充分压迫。压迫可减小乳腺厚度从而降低剂量与散射线、使腺体铺展分离、固定乳腺以防止扫描过程中的运动模糊；由于DBT采集时间长于单次FFDM曝光，对制动的要求反而更高，只是部分设备的压迫力可略作优化以改善舒适度。【为什么错】A正确：数据量与判读负担增加是DBT推广中的现实问题。B正确：钙化跨层分布使整体形态判断受限，这也是需要合成二维图像的原因之一。C正确：DBT发现的隐匿病灶需配套的引导定位技术才能完成活检。D正确：层外伪影是有限角度重建的固有缺陷。", "tr": "把“断层成像”与“不需要压迫”联系起来是典型错误推理。压迫的四大作用（减薄降剂量、减少散射、铺展腺体、固定制动）在DBT中一个都不能少。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1001", "t": "单选题", "s": "下肢与脊柱负重摄影的基本要求是", "o": {"A": "患者在站立负重状态下进行投照", "B": "患者平卧位投照", "C": "患者俯卧位投照", "D": "患者侧卧水平投照", "E": "患者屈膝90°投照"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-101", "kp": "负重摄影概念", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】负重摄影要求在站立位、肢体承受自身体重（承重）状态下投照，以反映真实应力下关节间隙与下肢力线，故A正确。\n【为什么错】B：平卧位肢体不受体重负荷。C：俯卧位同样无负重。D：侧卧水平位为非负重体位。E：屈膝90°为特殊应力体位而非负重摄影常规要求，均不符合。", "tr": "“负重”特指站立承重，与卧位摄影的力线表现有明显差异。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1002", "t": "单选题", "s": "下肢全长负重摄影最主要的临床应用是", "o": {"A": "评估下肢力线与关节置换术前规划", "B": "测量腰椎曲度", "C": "观察膝关节半月板", "D": "筛查骨质疏松", "E": "评估肺纹理"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-102", "kp": "下肢全长负重摄影应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】下肢全长负重位可一次性显示髋、膝、踝，用于测量下肢力线（髋-膝-踝角）、关节间隙及畸形程度，是关节置换术前规划的重要依据，故A正确。\n【为什么错】B：腰椎曲度属脊柱摄影范畴。C：半月板为软组织，普通X线不显示。D：骨密度测量用DXA。E：肺纹理评估属胸部摄影，均不符合。", "tr": "下肢全长摄影服务于“力线评估与矫形规划”，测量参数为髋-膝-踝角。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1003", "t": "单选题", "s": "全下肢负重正位摄影的投照范围应包括", "o": {"A": "从髋关节至踝关节全长", "B": "仅膝关节", "C": "从踝关节至足趾", "D": "仅髋关节", "E": "从膝至足"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-103", "kp": "下肢全长摄影范围", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】下肢全长摄影须将髋、膝、踝三个关节同时包括在图像中，才能完整测量下肢力线与各关节关系，故A正确。\n【为什么错】B：仅膝关节无法评价全下肢力线。C：踝至足趾范围过小。D：仅髋关节范围过小。E：膝至足范围仍不完整，均无法完成全长测量。", "tr": "全长摄影强调“髋-膝-踝”同框，缺失任何一端都无法完成力线测量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1004", "t": "单选题", "s": "脊柱全长负重摄影主要适用于", "o": {"A": "脊柱侧凸畸形的Cobb角测量", "B": "颈椎间盘突出", "C": "腰椎压缩骨折定位", "D": "骶髂关节炎", "E": "脊柱结核定性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-104", "kp": "脊柱全长摄影应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】全脊柱正侧位可完整显示颈、胸、腰椎，用于脊柱侧凸等畸形患者测量Cobb角、观察冠状面与矢状面平衡，故A正确。\n【为什么错】B：颈椎间盘为软组织，X线平片不能直接显示。C：压缩骨折定位用局部腰椎片即可。D：骶髂关节炎用骨盆片。E：结核定性需CT/MR结合临床，均不符合全长摄影的主要用途。", "tr": "全脊柱摄影的核心价值是侧凸测量（Cobb角）与全脊柱平衡评估。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1005", "t": "单选题", "s": "DR图像拼接技术的含义是", "o": {"A": "分段采集多幅图像后用软件合成一幅完整图像", "B": "把两幅不同患者图像叠加", "C": "对图像进行锐化处理", "D": "将图像压缩存储", "E": "放大局部图像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-105", "kp": "DR图像拼接概念", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】当投照区域超出探测器尺寸时，分段采集相邻图像，通过软件识别重叠区域自动融合成一幅连续完整的图像，即为图像拼接，故A正确。\n【为什么错】B：不同患者的图像不能拼接。C：锐化是后处理增强。D：压缩是存储优化。E：放大是显示操作，均非拼接技术含义。", "tr": "拼接是“同一次检查的分段采集+软件融合”，用于超长部位成像。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1006", "t": "单选题", "s": "保证DR拼接图像质量的关键措施是", "o": {"A": "各段曝光条件保持一致并保证相邻图像有足够重叠", "B": "各段随意改变管电压", "C": "相邻段之间留出空隙", "D": "患者随意移动体位", "E": "各段使用不同滤线栅方向"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-106", "kp": "拼接图像质量控制", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】各段曝光条件一致可保证拼接后密度均匀，相邻图像有一定重叠量供软件配准融合，两者是拼接成功的关键，故A正确。\n【为什么错】B：管电压改变导致各段密度差，拼接处明显分界。C：留空隙无法连续拼接。D：体位移动造成结构错位。E：滤线栅方向不一致影响密度均匀性，均错误。", "tr": "拼接两大要点：曝光一致+重叠区配准，任何环节失控都会产生拼接伪影。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1007", "t": "单选题", "s": "数字体层融合技术（DTS）的基本原理是", "o": {"A": "X线管在有限角度范围内移动连续曝光，经重建获得多层图像", "B": "X线管固定一次曝光", "C": "球管旋转360°扫描", "D": "双能量双次曝光", "E": "电子束偏转扫描"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-107", "kp": "数字体层融合原理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS（Digital Tomosynthesis）由X线管在有限角度范围内移动，对同一部位多次低剂量曝光，采集的投影数据经重建形成多层厚度可调的层面图像，故A正确。\n【为什么错】B：单次固定曝光只能得到平面影像。C：360°旋转为CT扫描方式。D：双能量减影是能量分离技术。E：电子束偏转是电子束CT的概念，均不属于DTS原理。", "tr": "DTS是“有限角度+多角度投影重建”，与CT的360°扫描、与双能减影均不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1008", "t": "单选题", "s": "与CT相比，数字体层融合（DTS）的主要特点是", "o": {"A": "扫描角度范围小、辐射剂量相对较低", "B": "扫描速度最慢", "C": "空间分辨率最高", "D": "只能用于颅脑", "E": "必须使用对比剂"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-108", "kp": "DTS与CT比较", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS仅在有限角度内曝光，射线利用率与剂量明显低于CT，兼具体层成像能力，故A正确。\n【为什么错】B：DTS采集速度快于常规CT。C：空间分辨率低于CT。D：DTS可用于胸、骨关节、乳腺等多部位。E：DTS为平扫技术，无需对比剂。", "tr": "DTS的定位是“低剂量体层成像”，介于平片与CT之间的补充技术。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1009", "t": "单选题", "s": "胸片疑肋骨骨折而常规正位片难以明确时，优先选择的体层技术是", "o": {"A": "胸部数字体层融合（DTS）", "B": "双能量减影软组织像", "C": "全身拼接摄影", "D": "负重摄影", "E": "断层CT平扫"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-109", "kp": "DTS临床应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】胸部DTS可分层显示肋骨，消除肺纹理与骨性结构的重叠干扰，提高隐匿性肋骨骨折检出率，是正位片后的合理补充，故A正确。\n【为什么错】B：软组织像用于去骨显示软组织，肋骨本身为骨组织，效果有限。C：拼接用于超长部位。D：负重摄影用于力线评估。E：CT平扫剂量高于DTS，非首选。", "tr": "肋骨骨折“平片→DTS”路径，利用DTS的分层显示克服重叠。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1010", "t": "单选题", "s": "DR双能量减影技术的成像基础是", "o": {"A": "不同组织对不同能量X线的吸收衰减差异", "B": "探测器分辨率", "C": "患者体位摆放", "D": "曝光时间长短", "E": "图像压缩方式"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-110", "kp": "双能量减影原理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】双能量减影利用骨、软组织、碘等对低能与高能X线吸收系数的差异，通过加权减影分离出骨像或软组织像，故A正确。\n【为什么错】B：探测器分辨率影响细节不参与能量分离。C：体位是操作因素。D：曝光时间决定剂量与运动模糊，不决定能量分离。E：压缩是存储优化，均非成像基础。", "tr": "双能量减影的本质是“能量域分离组织”，而非空间或时间维度的处理。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1011", "t": "单选题", "s": "DR双能量减影获得的“软组织像”（去骨像）最常用于", "o": {"A": "观察肋骨骨折等骨性结构", "B": "显示肺内软组织病变并去除肋骨干扰", "C": "测量下肢力线", "D": "评估乳腺压迫厚度", "E": "定位金属异物"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-111", "kp": "双能量软组织像应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】软组织像通过减影去除骨组织（肋骨、锁骨）干扰，清晰显示肺内结节、肿块等软组织病变，故B正确。\n【为什么错】A：观察骨性结构应使用骨像而非软组织像。C：力线测量与减影无关。D：乳腺压迫厚度与能量成像无关。E：金属异物定位不依赖软组织像。", "tr": "软组织像=去骨、看软组织；骨像=去软组织、看骨与钙化，用途相反。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1012", "t": "单选题", "s": "双能量减影技术中“骨像”（去除软组织）可用于", "o": {"A": "观察肺内结节伴钙化", "B": "显示乳腺实质", "C": "评估肌肉水肿", "D": "测量关节间隙宽度", "E": "显示胃肠道黏膜"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-112", "kp": "双能量骨像应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】骨像去除软组织后，骨组织和钙化显示更清晰，利于观察肺结节内钙化及肋骨骨性病变，故A正确。\n【为什么错】B：乳腺实质为软组织，用软组织像或常规像显示。C：肌肉水肿X线不显示。D：关节间隙测量用常规负重片。E：胃肠道黏膜需造影检查，均与骨像用途不符。", "tr": "骨像突出“钙化与骨”，用于鉴别结节钙化、肋骨病变等。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1013", "t": "单选题", "s": "数字合成体层成像（DBT）应用的检查部位是", "o": {"A": "乳腺", "B": "颅脑", "C": "心脏", "D": "消化道", "E": "骨骼肌"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-113", "kp": "DBT概念", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT（Digital Breast Tomosynthesis）是乳腺专用数字合成体层成像技术，通过有限角度多投影重建乳腺各层图像，故A正确。\n【为什么错】B：颅脑不使用DBT。C：心脏不使用DBT。D：消化道不使用DBT。E：骨骼肌不使用DBT，DBT专用于乳腺。", "tr": "DBT专指乳腺合成体层，胸部等其他部位合成体层一般称DTS。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1014", "t": "单选题", "s": "DBT减少乳腺组织重叠、提高病灶检出率的关键机制是", "o": {"A": "多角度投影重建获得分层图像，消除重叠结构干扰", "B": "增大压迫力度", "C": "提高管电流", "D": "延长曝光时间", "E": "使用造影剂"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-114", "kp": "DBT成像机制", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT使球管在有限角度内移动多次低剂量曝光，重建出不同深度的层面图像，各层面分别聚焦于相应深度，从而减少正常腺体组织重叠对病变的掩盖，故A正确。\n【为什么错】B：压迫与重叠无关，且压迫是常规操作。C：提高管电流增加剂量不消除重叠。D：延长曝光增加运动伪影风险。E：DBT为平扫技术，无需造影剂。", "tr": "DBT的核心价值是“分层去重叠”，适合致密型乳腺。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1015", "t": "单选题", "s": "DBT检查时X线球管的运动方式是", "o": {"A": "在有限角度范围内旋转扫描并多次低剂量曝光", "B": "固定不动一次曝光", "C": "围绕人体旋转360°", "D": "上下平移不曝光", "E": "前后对侧双曝光"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-115", "kp": "DBT扫描方式", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT中球管沿弧线在有限角度（不同机型约15°~50°）内旋转，同时多次低剂量曝光采集不同角度投影，故A正确。\n【为什么错】B：固定曝光只能获得二维影像。C：360°旋转是CT方式。D：不曝光无法成像。E：双曝光是双能量或双侧摄影概念，与DBT不同。", "tr": "DBT的“旋转+多次低剂量曝光”与CT的“360°连续旋转”在角度范围上不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1016", "t": "单选题", "s": "与常规乳腺数字摄影（FFDM）相比，DBT的主要优势是", "o": {"A": "提高致密型乳腺中病变的检出率", "B": "完全消除辐射剂量", "C": "不需要压迫乳腺", "D": "可检查任意体位", "E": "不需要技师操作"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-116", "kp": "DBT临床优势", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT通过分层减少重叠，对致密型乳腺中肿块、结构扭曲等病变的检出率和准确性优于常规FFDM，故A正确。\n【为什么错】B：DBT仍有一定辐射剂量，仅较FFDM略增或相当，不能消除。C：DBT仍需压迫固定乳腺。D：检查体位仍为CC、MLO等标准体位。E：检查全程需技师操作与压迫。", "tr": "DBT的优势是检出率，不是“零剂量、免压迫”，这些是常见干扰。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1017", "t": "单选题", "s": "DR双能量减影的两种主要实现方式是", "o": {"A": "一次曝光的双层探测器双能采集与两次曝光的管电压切换", "B": "一次曝光单层探测器", "C": "两次曝光相同管电压", "D": "核素显影", "E": "超声双幅"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-117", "kp": "双能量减影实现方式", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】双能量减影可采用双层探测器一次曝光（同一X线束分高低能层）或两次曝光快速切换高低管电压获得高低能图像，故A正确。\n【为什么错】B：单层探测器一次曝光无法分离能量。C：两次曝光相同kV无法形成能量差异。D：核素显影属核医学，非X线双能方式。E：超声双幅与双能量减影无关。", "tr": "一次曝光双层探测器法无运动伪影，两次曝光kV切换法需注意患者运动。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1018", "t": "单选题", "s": "进行双下肢负重全长DR摄影时，患者正确的摆位要求是", "o": {"A": "双足并拢或与肩同宽站立、双下肢同时负重、膝关节伸直", "B": "单足站立", "C": "双膝屈曲90°", "D": "背向探测器站立", "E": "身体随意倾斜"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-118", "kp": "下肢全长摄影摆位", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】双下肢同时承重、膝关节伸直、足位一致站立，可真实反映生理应力下的下肢力线与内外翻程度，故A正确。\n【为什么错】B：单足站立受力不对称，无法评价双侧力线。C：屈膝改变关节关系。D：应面向探测器。E：身体倾斜造成假性畸形，均错误。", "tr": "负重摄影摆位强调“双足同时承重、双下肢并拢伸直、髋膝朝前”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1019", "t": "多选题", "s": "下肢负重全长摄影的适应证包括", "o": {"A": "膝骨性关节炎力线评估", "B": "全膝关节置换术前规划", "C": "下肢内外翻畸形测量", "D": "下肢骨折术后力线复查", "E": "膝关节半月板损伤诊断"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-119", "kp": "负重摄影适应证", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】关节炎、畸形、术前规划及术后复查均需评估承重状态下下肢力线与关节状态，故A、B、C、D正确。\n【为什么错】E：半月板为软骨软组织，X线平片无法直接显示，应行MRI检查。", "tr": "负重片看“骨性力线与关节间隙”，软组织损伤（半月板、韧带）需MRI。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1020", "t": "多选题", "s": "提高DR图像拼接质量的技术要求包括", "o": {"A": "各段曝光条件（kV、mAs）保持一致", "B": "相邻图像间保留足够重叠区域", "C": "患者体位在各段采集间保持固定", "D": "软件自动识别重叠区并融合校正", "E": "各段使用不同滤线栅方向"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-120", "kp": "拼接技术要求", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】曝光一致保证密度均匀，重叠区供配准，体位固定防错位，软件融合校正保证连续性，故A、B、C、D正确。\n【为什么错】E：各段滤线栅方向不一致会造成密度不匀、拼接分界明显。", "tr": "拼接四要素：曝光一致、重叠配准、体位固定、软件融合。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1021", "t": "多选题", "s": "数字体层融合（DTS）的临床应用包括", "o": {"A": "胸部肺结节的检出与定位", "B": "隐匿性肋骨骨折诊断", "C": "骨关节病变的补充体层成像", "D": "金属内固定术后骨痂观察", "E": "全身血管造影"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-121", "kp": "DTS临床应用范围", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS用于肺结节、肋骨骨折、骨关节体层及金属内固定周围骨质观察等，均利用分层去重叠优势，故A、B、C、D正确。\n【为什么错】E：血管造影属于DSA技术，DTS为平片体层技术，不用于血管造影。", "tr": "DTS适用于“平片上重叠干扰明显”的病变，血管系统不属于其范畴。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1022", "t": "多选题", "s": "DR双能量减影的临床应用包括", "o": {"A": "去除肋骨干扰显示肺内软组织病变", "B": "分离骨像观察钙化", "C": "碘剂负荷下的组织强化显示", "D": "肋骨骨折的鉴别显示", "E": "下肢力线测量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-122", "kp": "双能量减影临床应用", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】双能减影可去骨显示软组织、分离钙化骨像、增强含碘组织显示并辅助肋骨骨折判断，故A、B、C、D正确。\n【为什么错】E：下肢力线测量用负重全长摄影，与能量减影无关。", "tr": "双能减影的价值在“能量域分离骨/软组织/碘”，力线测量属几何学应用。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1023", "t": "多选题", "s": "DR双能量减影能够分离的组织物质包括", "o": {"A": "骨组织", "B": "软组织", "C": "碘剂", "D": "钙化组织", "E": "气腹气体"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-123", "kp": "双能量物质分离", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】双能量减影依据不同物质能量衰减特性，可分离骨、软组织、碘及钙化等成分，故A、B、C、D正确。\n【为什么错】E：气腹气体（空气）与软组织衰减差异并非双能减影的分离目标，气腹显示依赖体位与常规摄影。", "tr": "双能分离的是“高原子序数成分（骨/钙/碘）与软组织”，气体分离不属于其典型应用。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1024", "t": "多选题", "s": "DBT技术的优点包括", "o": {"A": "分层显示减少组织重叠", "B": "提高致密型乳腺病变检出率", "C": "可重建任意层厚与层面图像", "D": "减少重复召回检查", "E": "不需要压迫乳腺"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-124", "kp": "DBT优点", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT分层去重叠、提高致密乳腺检出、重建多层面图像、减少因重叠引起的召回，均为其优点，故A、B、C、D正确。\n【为什么错】E：DBT仍须常规压迫乳腺以固定并减少厚度，不能省略。", "tr": "压迫是乳腺摄影的基本要求，DBT不例外。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1025", "t": "多选题", "s": "乳腺X线检查设备的进展包括", "o": {"A": "数字乳腺摄影（FFDM）", "B": "数字合成体层成像（DBT）", "C": "对比增强乳腺摄影（CESM）", "D": "乳腺专用双能量成像", "E": "全身CT扫描代替乳腺摄影"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-125", "kp": "乳腺X线设备进展", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (1)乳腺X线检查设备", "ex": "【为什么对】FFDM、DBT、CESM及乳腺专用双能量成像均为乳腺X线设备与技术的进展方向，故A、B、C、D正确。\n【为什么错】E：全身CT剂量高、乳腺受照大，不能代替专用乳腺摄影。", "tr": "乳腺成像强调专用设备与低剂量，全身CT不具备替代性。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1026", "t": "多选题", "s": "全脊柱负重正位摄影的临床用途包括", "o": {"A": "脊柱侧凸Cobb角测量", "B": "冠状面躯干平衡评估", "C": "下肢不等长相关代偿分析", "D": "术后矫形效果复查", "E": "椎间盘突出定性诊断"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-126", "kp": "全脊柱摄影用途", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】全脊柱负重位可测Cobb角、评估躯干平衡、分析代偿及复查术后效果，故A、B、C、D正确。\n【为什么错】E：椎间盘为软组织，X线不能直接显示，需CT/MRI。", "tr": "X线平片评估骨性畸形与平衡，软组织结构（椎间盘）超出其能力。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1027", "t": "多选题", "s": "DR拼接图像出现拼接处错位或密度不均的可能原因包括", "o": {"A": "各段曝光条件不一致", "B": "患者在两段采集间移动", "C": "重叠区域过小导致配准失败", "D": "滤线栅方向不一致", "E": "图像分辨率设置过高"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-127", "kp": "拼接伪影原因分析", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】曝光不一致致密度差异，体位移动致错位，重叠不足致配准失败，滤线栅方向不一致致密度分界，均为拼接失败原因，故A、B、C、D正确。\n【为什么错】E：分辨率设置越高图像越清晰，不产生错位或密度不均伪影。", "tr": "拼接伪影源于“条件、体位、重叠、几何”控制不良，与分辨率高低无直接关系。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1028", "t": "多选题", "s": "关于DBT与FFDM联合检查的正确说法是", "o": {"A": "DBT可减少组织重叠对病变的掩盖", "B": "合成二维图像可部分替代额外FFDM曝光，降低剂量", "C": "DBT适用于致密型乳腺", "D": "DBT层厚可在后处理中调整", "E": "DBT完全取代超声检查"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-128", "kp": "DBT临床应用要点", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT分层去重叠、适合致密乳腺，合成二维图像可减少额外曝光剂量，层面厚度可后处理调整，故A、B、C、D正确。\n【为什么错】E：DBT是X线体层技术，不能替代超声对囊实性病变的鉴别等功能。", "tr": "DBT与超声、MRI互补而非替代，勿夸大DBT能力。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U14-1029a", "t": "单选题", "s": "【病例】患者男性，68岁，双膝骨性关节炎，右膝内翻畸形明显，拟行全膝关节置换术。骨科医师申请下肢全长负重正位摄影，以评估下肢力线并制定术前规划。技师需确定摄影方式与测量参数。 为完整评估下肢力线，应采用的摄影方式是", "o": {"A": "双下肢站立负重全长正位摄影（拼接）", "B": "右膝单独平卧正侧位", "C": "双踝负重侧位", "D": "双髋平卧轴位", "E": "脊柱全长正位"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-129", "kp": "下肢力线评估摄影方式", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】评估下肢力线须在站立负重位一次性显示髋、膝、踝全长，利用DR拼接获得全下肢图像，故A正确。\n【为什么错】B：仅膝关节局部片无法评估全长力线。C：双踝负重侧位范围不符。D：双髋平卧轴位范围不符。E：脊柱全长正位用于脊柱侧凸，与膝力线无关。", "tr": "“力线评估”对应双下肢全长负重拼接片，局部片无法完成。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1029b", "t": "单选题", "s": "术后复查时，测量下肢力线畸形的常用角度参数是", "o": {"A": "髋-膝-踝角（HKA角）", "B": "Cobb角", "C": "骶髂角", "D": "耻骨联合角", "E": "眼眶角"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-130", "kp": "下肢力线测量参数", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】髋-膝-踝角（HKA）由髋中心、膝中心、踝中心连线构成，是评价膝内外翻畸形的核心参数，故A正确。\n【为什么错】B：Cobb角用于脊柱侧凸。C：骶髂角、D：耻骨联合角、E：眼眶角均非下肢力线测量参数。", "tr": "下肢看HKA角，脊柱看Cobb角，部位与参数要对应。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1030a", "t": "单选题", "s": "【病例】患者男性，45岁，胸部外伤后持续胸痛，常规胸部正位片显示右侧第7肋腋段可疑骨折线，但受肋骨与肺纹理重叠影响难以确诊。临床希望在不增加较大辐射负担的情况下进一步明确。 为进一步显示肋骨骨折细节，优先选用的补充检查是", "o": {"A": "胸部数字体层融合（DTS）", "B": "全身CT增强", "C": "上肢负重摄影", "D": "双能量软组织像", "E": "乳腺DBT"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-131", "kp": "肋骨骨折补充体层", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS可对肋骨所在层面分层成像，消除重叠干扰，明确骨折线，且剂量远低于CT，适合此类补充检查，故A正确。\n【为什么错】B：CT增强并非肋骨骨折常规，且剂量较高。C：负重摄影用于力线。D：软组织像去骨后肋骨显示反而不佳。E：DBT用于乳腺，部位不符。", "tr": "肋骨骨折首选补充检查是DTS，兼顾诊断与剂量控制。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1030b", "t": "单选题", "s": "与胸部CT平扫相比，胸部DTS的突出特点是", "o": {"A": "辐射剂量相对较低", "B": "空间分辨率高于CT", "C": "不需要屏气", "D": "可显示全部软组织", "E": "扫描范围无限制"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-132", "kp": "DTS与CT剂量比较", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (3)数字体层融合技术", "ex": "【为什么对】DTS仅有限角度低剂量曝光，辐射剂量明显低于同部位CT，故A正确。\n【为什么错】B：CT空间分辨率更高。C：胸部DTS仍需屏气减少运动模糊。D：DTS软组织密度分辨力低于CT，不能显示全部软组织。E：DTS扫描范围受角度与探测器限制，并非无限制。", "tr": "DTS定位是“CT与平片之间的低剂量补充”，高分辨力与全软组织显示仍属CT优势。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1031a", "t": "单选题", "s": "【病例】患者女性，52岁，乳腺普查发现左乳外上象限结构紊乱伴可疑微钙化，因腺体较致密，常规FFDM难以判断钙化是否聚集及有无肿块。医师建议加做DBT检查进一步评估。 行DBT检查时，X线球管的扫描方式是", "o": {"A": "在有限角度范围内旋转并多次低剂量曝光", "B": "固定角度单次高剂量曝光", "C": "360°旋转扫描", "D": "不曝光仅透视", "E": "双球管同时曝光"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-133", "kp": "DBT球管扫描方式", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】DBT球管沿弧线在有限角度内旋转，多次低剂量曝光采集多角度投影，再重建各层图像，故A正确。\n【为什么错】B：单次曝光只能得到二维图像。C：360°旋转是CT方式。D：不曝光无法成像。E：DBT为单球管技术，无双球管同时曝光。", "tr": "“有限角度多次曝光”是DBT的特征，与CT的360°旋转不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1031b", "t": "单选题", "s": "为提高检查效率并控制总辐射剂量，DBT后处理中可采用的做法是", "o": {"A": "由断层数据重建合成二维图像替代常规FFDM", "B": "加大管电流扫描", "C": "取消压迫", "D": "重复多次曝光", "E": "缩短球管旋转角度至0°"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-134", "kp": "DBT合成二维图像", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】由DBT断层数据重建的合成二维图像（synthetic 2D）与断层图像同时提供，可免去额外的FFDM采集，降低总剂量，故A正确。\n【为什么错】B：加大管电流增加剂量。C：取消压迫违反摄影规范。D：重复曝光增加剂量。E：角度为0°则无法形成断层投影。", "tr": "合成二维图像是DBT“一次采集、两种图像”的剂量优化手段。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1032", "t": "案例分析题", "s": "患者男性，56岁，双膝骨性关节炎伴右膝内翻，拟行右膝置换术前下肢力线评估。技师使用DR拼接功能分三次曝光采集双下肢全长正位图像。拼接结果显示接缝处骨轮廓出现错位，下肢轮廓在拼接点不连续，影响力线测量。技师需定位并解决该问题。拼接软件依靠相邻段重叠区域的特征点自动配准融合，体位移动会导致配准失败。技师应重点核查的环节是", "o": {"A": "患者各段采集间是否保持静止及重叠区配准是否准确", "B": "探测器分辨率设置", "C": "胶片尺寸", "D": "显示器亮度", "E": "图像压缩率"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-135", "kp": "拼接错位排查", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】拼接错位的直接原因是患者体位移动导致相邻段骨轮廓不连续，或重叠区过小致软件配准失败，故A正确。\n【为什么错】B：分辨率影响细节不影响错位。C：胶片尺寸与拼接错位无关。D：显示器亮度为显示设置。E：压缩率影响存储不影响几何对位。", "tr": "拼接错位查“体位固定与重叠配准”，不要在外围设置上兜圈。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1033", "t": "案例分析题", "s": "患者女性，60岁，体检胸片显示右下肺一枚1.2cm结节，形态欠清，医师希望判断结节内有无钙化以帮助定性。常规正位片因肋骨与心脏阴影重叠，结节显示不清。该院配备DR双能量减影设备。双能量减影可分离骨与软组织成分，骨像与软组织像分别用于钙化和软组织显示。钙化与软组织衰减特征不同，选择合适的能量分离图像是判断前提。技师应选择的后处理图像是", "o": {"A": "骨像（去软组织像）突出钙化", "B": "软组织像观察结节本身", "C": "软组织像同时观察钙化", "D": "拼接图观察钙化", "E": "负重像观察钙化"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-136", "kp": "双能量减影钙化显示", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】骨像去除软组织后，钙化（与骨同属高原子序数物质）显示更清晰，利于判断结节内钙化，故A正确。\n【为什么错】B：软组织像会同时去除钙化成分，无法观察钙化。C：软组织像不含钙化信息。D：拼接图像无能量分离能力。E：负重像与钙化显示无关。", "tr": "钙化与骨同源，看钙化用“骨像”；看软组织病变用“软组织像”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1034", "t": "案例分析题", "s": "患者女性，48岁，致密型乳腺，行DBT检查后发现部分层面图像出现运动性模糊，微钙化与结构扭曲判断受影响。技师分析原因为患者在扫描过程中轻微移动所致。为减少后续检查中的DBT运动伪影，DBT单次检查需多次低剂量曝光，扫描时间数秒，患者需保持静止并屏住呼吸配合。适当的压迫可减少移动并降低厚度，是质控的重要环节。最有效的操作措施是", "o": {"A": "充分解释流程、适当压迫并嘱患者在扫描期间保持静止、避免呼吸起伏", "B": "取消压迫让患者放松", "C": "缩短扫描时间至不足1秒但加大剂量", "D": "让患者大声说话分散注意力", "E": "扫描过程中移动患者体位"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-137", "kp": "DBT运动伪影控制", "ch": "十四、数字X线技术的进展 → 2.乳腺检查技术 → (2)数字合成体层成像DBT", "ex": "【为什么对】充分沟通使患者理解流程、保持适当压迫并嘱静止、屏住呼吸，是减少运动伪影最有效且安全的措施，故A正确。\n【为什么错】B：取消压迫会加重移动与厚度增加。C：大幅提高剂量不可取。D：说话会诱发呼吸运动。E：移动体位必然产生伪影，均错误。", "tr": "运动伪影的防控核心是“固定+配合”，不能以牺牲压迫或增加剂量为代价。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "乳腺检查技术", "页": 375}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1035", "t": "案例分析题", "s": "患者男性，15岁，学校体检发现脊柱侧凸，来院行全脊柱负重正位及侧位摄影，用于Cobb角测量与矫形评估。技师负责完成检查并进行图像质控。若摆位不当将导致Cobb角测量失真。为保证测量准确，全脊柱正位摄影的全脊柱摄影常采用多段曝光后拼接，各段间需保持患者体位绝对稳定。测量结果直接关系到矫形与手术决策，摆位标准化至关重要。关键摆位要求是", "o": {"A": "患者自然站立、双肩与双侧髂嵴等高、骨盆水平、去除外固定", "B": "患者弯腰90°站立", "C": "患者侧卧拍摄", "D": "患者双手抱膝站立", "E": "患者跳跃落地瞬间曝光"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-138", "kp": "全脊柱摄影摆位", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (1)下肢和脊柱负重摄影", "ex": "【为什么对】自然站立、肩髋水平、骨盆端正、去除外固定可真实反映脊柱畸形并保证测量基线一致，故A正确。\n【为什么错】B：弯腰体位改变脊柱形态。C：侧卧非负重状态。D：抱膝位改变躯干姿态。E：动态曝光产生运动伪影，均不符合测量要求。", "tr": "全脊柱摄影追求“自然直立、对称水平”的标准化摆位，任何变形姿态都会影响测量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1036", "t": "案例分析题", "s": "某医院拟开展DR双能量减影胸片检查，采用两次曝光（高低管电压切换）方案。技师在为老年患者检查时发现，两次曝光间隔内患者发生呼吸移动，导致减影图像出现骨与软组织错位伪影，影响诊断。针对该问题，两次曝光法存在时间间隔，患者呼吸、心跳等运动可致高低能图像错位。解决思路应在保证图像质量的同时兼顾患者配合的可行性。处理方法中最合理的是", "o": {"A": "改用一次曝光的双层探测器双能成像，或嘱患者屏气并缩短两次曝光间隔", "B": "放弃双能减影检查", "C": "让患者快速呼吸", "D": "加大两次曝光剂量", "E": "提高图像分辨率"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-139", "kp": "双能量减影运动伪影处理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (4)DR双能量减影技术", "ex": "【为什么对】一次曝光双层探测器法在同一X线束内完成高低能采集，无时间差，可从根本上消除运动伪影；嘱屏气、缩短曝光间隔也能减轻两次曝光法的运动影响，故A正确。\n【为什么错】B：双能减影有明确价值，不应轻言放弃。C：快速呼吸加剧运动。D：增加剂量不解决错位。E：分辨率不影响配准错位。", "tr": "两次曝光双能的软肋是运动伪影，双层探测器一次曝光是解决思路。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": "DR检查技术", "页": 372}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U14-1037", "t": "案例分析题", "s": "患者男性，70岁，双侧全髋关节置换术后复查，骨科医师申请下肢全长负重片评估双下肢力线与假体位置。技师发现拼接图像中髋、膝、踝关节均清晰显示，但各段密度存在轻微差异，接缝处可见隐约分界，影响图像整体观感与测量可重复性。为改善图像质量，密度差异可通过软件自动均衡校正改善，同时应统一各段曝光条件。最合适的措施是", "o": {"A": "后处理时应用密度均衡校正，并对各段曝光条件进行统一化处理", "B": "删除该检查重新拍摄", "C": "仅保留密度较高的一段", "D": "提高显示器伽马", "E": "加做CT重建"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十四", "un": "数字X线技术进展", "kpid": "UNIT-14-DRA-140", "kp": "拼接密度均衡处理", "ch": "十四、数字X线技术的进展 → 1.DR检查技术 → (2)DR图像拼接技术", "ex": "【为什么对】拼接图像密度不均可通过软件密度均衡校正与统一各段曝光参数来改善，保证整幅图像观感一致、测量可靠，故A正确。\n【为什么错】B：轻度密度差异无需重拍，重拍成本高。C：只保留一段失去全长信息。D：显示器伽马是显示端调整，不改变图像数据。E：CT重建与负重片目的不符且剂量高。", "tr": "拼接密度不均优先用“软件均衡校正”，重拍与裁切都不是好方案。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字X线的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0101", "t": "单选题", "s": "与影像增强器（II-TV）系统相比，平板探测器（FPD）DSA系统在成像性能上最本质的优势是", "o": {"A": "视野呈圆形，便于全景观察大范围血管", "B": "量子探测效率（DQE）更高、动态范围更宽，且不存在枕形失真、S形畸变与边缘渐晕", "C": "极限空间分辨率不再受探测器像素尺寸的限制", "D": "成像链环节更多，信号经多次转换后对比度更好", "E": "对散射线不敏感，因此可以省略滤线栅"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-001", "kp": "平板探测器DSA的硬件优势", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】B正确。FPD为平面直接成像结构，取消了影像增强器的电子光学放大链（输入屏—光电阴极—静电聚焦—输出屏—光学耦合—摄像器件），因而不产生枕形失真、S形畸变、边缘分辨率下降与渐晕；动态范围可达10⁴以上（II约10³），DQE明显提高，同等图像质量下辐射剂量更低。【为什么错】A错误：FPD视野为矩形（方形），影像增强器才是圆形，两者说反了；矩形视野的有效面积利用率更高。C错误：FPD的极限空间分辨率恰由像素尺寸（约0.15~0.20mm）与矩阵决定，并非不受限制。D错误：成像链环节越多，噪声与失真累积越多，这是II的缺点而非优点。E错误：FPD同样接收散射线，仍需配用滤线栅并做散射校正。", "tr": "FPD视野是矩形而非圆形，是与II对比时最易颠倒的一点。另需记住FPD分辨率并非无限，其像素尺寸约0.15~0.20mm，优于II的0.3mm以上。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0102", "t": "多选题", "s": "关于DSA的C形臂机架形式与双C臂双平面系统，下列说法正确的是", "o": {"A": "落地式机架承重与机械刚度好，旋转采集时等中心重复精度高，但占用手术床周围的地面空间", "B": "悬吊式（天轨）机架可沿导轨大范围移动并移出术野，便于麻醉与外科团队在床旁操作", "C": "双C臂双平面系统一次对比剂注射即可同时获得正、侧位两个方向影像，有利于减少注射次数与对比剂总量", "D": "双平面系统两个平面的成像参数由系统统一设定，两侧须使用相同的帧率、视野与曝光条件", "E": "双平面同时工作时存在交叉散射，可通过两平面脉冲错峰（交替曝光）减轻互相干扰"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-002", "kp": "DSA机架形式与双平面系统", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】A正确：落地式刚性好、承载大，旋转与步进的机械重复性优，代价是占用床旁地面空间。B正确：悬吊式解放地面，可整体泊出术野，是复合手术室（Hybrid OR）的主流选择。C正确：双平面一次注射获得两个投照方向，减少注射次数与对比剂总量，对儿童、神经介入和心血管造影意义重大。E正确：交叉散射是双平面同时曝光的固有问题，工程上以脉冲时序交替与散射校正抑制。【为什么错】D错误：双平面两个平面的帧率、视野、管电压/管电流、脉冲宽度均可独立设定，临床常见正位低帧率、侧位高帧率的组合。", "tr": "「双平面必须同步同参数」是常见误解。双平面的价值恰在于两平面可按各自观察需求独立配置，仅在曝光时序上错峰以避免交叉散射。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-0103", "t": "单选题", "s": "DSA检查中高压注射器与X线机联动时采用「曝光延迟」方式，其含义是", "o": {"A": "先启动X线曝光采集蒙片，延迟设定时间后再启动注射", "B": "先启动对比剂注射，延迟设定时间后再启动X线曝光采集", "C": "注射与曝光同步启动，两者之间无时间差", "D": "对比剂注射完毕后延迟数秒再开始曝光", "E": "由术者踩板随机控制，两者之间无固定时序关系"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-003", "kp": "高压注射器与DSA设备的联动方式", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】B正确。联动方式以「被延迟的动作」命名：曝光延迟即以注射为时间起点、X线曝光相对滞后，适用于导管头端距靶血管较远、对比剂需一段运行时间才能到达感兴趣区的情形（如经上肢入路或长导管注射远端血管）。【为什么错】A错误：A描述的是「注射延迟」（对比剂延迟），先曝光采集不含碘的蒙片再注射，是DSA最常用的联动方式，与曝光延迟概念相反。C错误：完全同步会使蒙片帧内已混入对比剂，破坏减影基础。D错误：注射完毕后再曝光将错过对比剂充盈高峰。E错误：手动踩板时序重复性差，不属于「联动」范畴。", "tr": "曝光延迟＝先注射后曝光；注射延迟＝先曝光后注射。命名指向被延迟的动作，考试中最易记反。DSA需先获得蒙片，故临床默认多用注射延迟。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0104", "t": "案例分析题", "s": "患者男性，62岁，左侧髂动脉长段闭塞拟行腔内开通术，预计透视时间较长。设备为平板探测器单C臂DSA，具备可变脉冲透视（3.75/7.5/15脉冲每秒）、附加铜滤过（0.1~0.9mm）、末帧图像保持（LIH）配合虚拟准直及透视储存功能。患者体型偏胖（BMI 29），术者希望在保证导丝、导管可视性的前提下尽量降低患者皮肤剂量与自身受照剂量。下列技术措施中最不恰当的是", "o": {"A": "将脉冲透视帧率由15脉冲每秒降至7.5甚至3.75脉冲每秒", "B": "在球管侧加用铜滤过，滤除对成像几乎无贡献的低能光子", "C": "全程使用小视野（高放大档）透视，以便把导丝细节看得更清楚", "D": "使用末帧图像保持配合虚拟准直，在不曝光状态下完成准直器调整", "E": "升高检查床或降低探测器使其贴近患者体表，同时保证足够的源—皮距"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-004", "kp": "介入透视的剂量管理措施", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】C最不恰当。缩小视野提高电子放大档时，自动亮度控制为维持探测器入射剂量恒定，会按视野面积的反比提高患者入射剂量率，是介入操作皮肤剂量超标的常见原因。合理策略是以大视野为主，仅在关键步骤短时放大。【为什么错】A是标准措施：累积剂量与脉冲率近似成正比，降帧率最直接有效。B是标准措施：铜滤过滤除只沉积于皮肤而到不了探测器的低能光子，可使皮肤入射剂量明显下降。D是标准措施：末帧图像保持加虚拟准直可在零曝光下完成准直与遮挡调整，避免边看边调的额外曝光。E是标准措施：探测器贴近患者可减小几何放大与空气间隙散射，降低维持影像质量所需入射剂量率；同时保持足够源—皮距以避免皮肤剂量率过高。", "tr": "「放大看得清＝更安全」是典型误区。视野每缩小一档入射剂量率明显上升；肥胖患者本已需要更高输出，叠加放大更易在长时间手术中接近确定性皮肤效应阈值（约2Gy红斑、3Gy临时脱发）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0105", "t": "单选题", "s": "DSA实时数字减影处理中，先对图像信号做对数变换再相减，其根本原因是", "o": {"A": "对数变换能够提高图像的空间分辨率", "B": "X线在人体中呈指数衰减，取对数后信号与碘柱的浓度×厚度成线性关系，相减才能彻底消除背景", "C": "对数变换可以抑制量子噪声，使减影像的信噪比高于原始像", "D": "对数变换的作用是把模拟信号转换成数字信号", "E": "对数变换用于校正影像接收器的几何畸变"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-005", "kp": "对数变换与实时减影原理", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】B正确。X线透过人体满足I＝I₀e^(−μd)，若直接把造影像与蒙片相减，骨与软组织背景并不会抵消。取对数后lnI₀−lnI＝μd，信号与衰减系数×厚度成线性关系，两帧相减仅保留碘柱项（碘浓度×血管径），背景被完全消去，故对数放大是DSA成立的物理前提。【为什么错】A错误：空间分辨率取决于探测器像素、几何放大与焦点尺寸，与灰度变换无关。C错误：恰恰相反，两帧相减时噪声方差相加，减影像噪声标准差约为单帧的√2倍，故采集帧剂量需高于透视帧。D错误：模数转换由ADC完成。E错误：几何畸变校正是影像增强器系统特有的环节。", "tr": "减影提高的是对比度而非信噪比——减影使噪声增大约√2倍，这正是DSA采集帧剂量必须显著高于透视帧的原因。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0106", "t": "单选题", "s": "DSA图像出现运动性伪影时采用像素移位（pixel shift）技术校正，关于其原理与适用范围，下列说法正确的是", "o": {"A": "把蒙片在x、y方向做亚像素级平移（必要时叠加分区局部移位）与造影像重新配准后再减影，适用于以平移为主的轻度运动", "B": "从采集序列中另选一帧不含对比剂的图像替换原蒙片后重新减影", "C": "通过提高采集帧率把已经产生的运动错位消除", "D": "对造影像做高通滤波，把运动产生的边缘信号滤除", "E": "对吞咽、胃肠蠕动、心脏搏动等非刚性运动造成的伪影同样能够有效校正"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-006", "kp": "像素移位与运动伪影校正", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】A正确。像素移位的本质是图像配准：把蒙片相对造影像做亚像素级平移（先进系统支持分区局部移位与轻度旋转形变），使两帧解剖结构重新对齐后再相减，从而消除错位形成的「双边影」，对整体平移为主的轻度运动最有效。【为什么错】B错误：这是「再蒙片（remask）」技术，与像素移位是并列的两种后处理手段。C错误：帧率只影响采集阶段的时间分辨率，无法对已采集图像的错位做补救。D错误：高通滤波会同时削弱血管边缘信号并放大噪声，不能纠正配准误差。E错误：像素移位属整体或分区的刚性配准，对吞咽、肠蠕动、心搏这类大幅度非刚性运动效果有限，此类情况应重新采集或改用心电门控、屏气、加大镇静等措施。", "tr": "像素移位与再蒙片常被混为一谈：前者动的是蒙片的位置，后者换的是蒙片本身。二者都属减影后处理，均不能替代采集时的制动与配合。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0107", "t": "多选题", "s": "关于DSA的噪声抑制与图像后处理软件功能，下列说法正确的是", "o": {"A": "帧间递归滤波（时间平均）通过对连续帧加权累加降低量子噪声，但在快速运动部位会产生拖影", "B": "空间域自适应滤波在平坦区域强平滑、在边缘区域弱平滑，可在抑制噪声的同时保留血管边缘锐利度", "C": "低剂量透视时降低脉冲剂量必然导致噪声增加，先进的时空联合降噪算法可部分补偿从而维持可接受的图像质量", "D": "图像的边缘增强处理会同时放大噪声，因此增强强度需与降噪强度匹配设置", "E": "散射线的抑制可主要交由后处理降噪算法承担，滤线栅与准直器的作用能够被软件取代"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-007", "kp": "DSA噪声抑制与图像增强软件", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】A正确：递归（时间）滤波以牺牲时间分辨率换取信噪比，运动部位出现拖尾是其固有代价，故心脏、快速血流部位应减小递归权重。B正确：自适应滤波依据局部梯度调整平滑强度，是「保边降噪」的通用思路。C正确：现代低剂量透视正是依靠时间域与空间域联合降噪，在脉冲剂量下调后仍维持导丝导管可视性。D正确：边缘增强属高通操作，会放大高频噪声，须与降噪参数联动整定。【为什么错】E错误：散射线在到达探测器之前已经产生并携带错误的位置信息，后处理无法恢复其原始来源，滤线栅、准直与合理空气间隙仍是控制散射的物理手段，软件仅能做有限的散射校正。", "tr": "散射控制必须在信号形成阶段解决，任何后处理都无法真正「去掉」已混入的散射信息，只能做估计与近似扣除。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-0108", "t": "单选题", "s": "介入设备产生的辐射剂量结构化报告（RDSR）中，用于评估患者确定性皮肤损伤风险的最相关指标是", "o": {"A": "剂量面积乘积（DAP/KAP）", "B": "参考点空气比释动能（Ka,r，即参考点累积剂量）", "C": "透视总时间", "D": "采集图像的总帧数", "E": "球管的累积毫安秒"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-008", "kp": "剂量结构化报告与介入剂量指标", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】B正确。参考点空气比释动能Ka,r是在介入参考点（等中心向球管方向15cm处）累积的空气比释动能，量纲为Gy，与照射野内某点的皮肤累积剂量最直接相关，是预警皮肤红斑、脱发等确定性效应的首选指标。【为什么错】A错误：DAP（Gy·cm²）反映进入患者的总能量，与随机性效应及有效剂量估算相关，但同一DAP可由大野低剂量或小野高剂量产生，不能直接指示局部皮肤剂量峰值。C错误：透视时间不含剂量率信息，不同帧率、体厚下相同时间的剂量可相差数倍。D错误：帧数同样不含单帧剂量信息。E错误：毫安秒未计入管电压、滤过、距离与照射野，无法直接换算为皮肤剂量。【补充】RDSR按DICOM标准逐次曝光记录kV、mA、脉宽、投照角度、视野、Ka,r与DAP，可用于剂量追踪与峰值皮肤剂量重建。", "tr": "Ka,r与DAP的分工要分清：Ka,r对应确定性效应（皮肤），DAP对应随机性效应（全身）；透视时间只能做粗略提示，不能作为剂量指标。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0109", "t": "单选题", "s": "关于旋转DSA与三维DSA（3D-DSA）的采集与重建，下列说法正确的是", "o": {"A": "旋转DSA需先做一次不注射对比剂的旋转蒙片采集，再做一次同轨迹的注射旋转采集，两组数据对应角度减影后重建三维血管", "B": "3D-DSA只需一次旋转采集即可完成，无需蒙片", "C": "3D-DSA的三维重建以最大密度投影替代反投影算法完成", "D": "旋转采集的角度范围通常小于90度即可满足三维重建要求", "E": "3D-DSA重建后不能进行任意角度观察，只能显示采集时的实际角度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-009", "kp": "旋转DSA与3D-DSA重建", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】A正确。标准3D-DSA采用「两次旋转」模式：第一次空跑采集蒙片序列，第二次在对比剂持续注射下沿同一轨迹、同一角度步进采集，按角度一一对应减影得到纯血管投影，再经滤波反投影或迭代算法重建为三维容积数据。【为什么错】B错误：不做蒙片减影时得到的是含骨结构的旋转血管造影（三维血管造影），血管与颅底骨重叠严重，不能等同于3D-DSA。C错误：MIP是重建完成后的显示方式，不是重建算法本身，重建仍依靠反投影或迭代重建。D错误：旋转采集范围通常在180度加扇角以上，常用约200度，角度不足会造成重建信息缺失与条纹伪影。E错误：三维容积重建后可任意角度旋转观察，并可测量瘤颈、瘤体、载瘤动脉直径，用于选择工作角度与器械尺寸，这正是其临床价值。", "tr": "「旋转采集」不等于「3D-DSA」：前者可仅采集造影旋转序列供动态观察，后者强调蒙片减影后的三维容积重建。3D-DSA的主要用途是确定动脉瘤最佳工作角度与形态测量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0110", "t": "多选题", "s": "关于C臂锥形束CT（CBCT，厂家名称如DynaCT、XperCT、Innova CT）的成像特点，下列说法正确的是", "o": {"A": "利用C臂旋转采集数百幅锥形束投影，重建出类似CT的断层与容积图像，可在介入床上完成软组织观察", "B": "与常规多层螺旋CT相比，其密度分辨率较低、散射与截断伪影更明显，对小密度差病变的检出能力有限", "C": "旋转采集时间通常为数秒至二十余秒，需要患者屏气或制动配合以避免运动伪影", "D": "可用于术中即时判断颅内出血、支架贴壁、栓塞剂分布及穿刺针位置，减少患者往返CT室的转运风险", "E": "其空间分辨率低于常规CT，无法显示细小的高对比结构"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-010", "kp": "C臂锥形束CT软组织成像", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】A正确：CBCT以平板探测器一次旋转采集锥形束投影，重建出容积数据，实现介入床旁的「类CT」软组织成像。B正确：受锥形束散射、探测器动态范围、视野截断和采集时间限制，其低对比度分辨率明显不如MSCT，微小低密度差病灶易漏检。C正确：单次旋转常需5~20秒，运动伪影是主要质量制约因素，故要求屏气或必要时镇静。D正确：这正是其核心临床价值——术中即时排除颅内出血、评价支架贴壁与栓塞剂沉积、确认穿刺针位置，避免转运风险。【为什么错】E错误：CBCT的高对比空间分辨率反而优于常规CT，其平板像素小、各向同性体素可达0.2~0.5mm，显示支架金属丝、弹簧圈、骨小梁等高对比结构具有优势；它的短板在密度（低对比）分辨率而非空间分辨率。", "tr": "CBCT「空间分辨率高、密度分辨率低」，与MSCT恰好互补。把两种分辨率混为一谈是本考点最常见的失分点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-0111", "t": "单选题", "s": "关于路径图（roadmap）技术与三维路径图（3D roadmap），下列说法正确的是", "o": {"A": "常规路径图制作完成后，改变C臂角度、床面位置或视野时，系统会自动补偿几何变化并维持血管轮廓与实时透视的配准", "B": "三维路径图叠加的血管背景来自当次实时采集的二维减影像，与此前重建的三维容积数据无关", "C": "三维路径图是将已重建的三维血管容积与实时透视按机架角度、床位、放大率自动配准叠加，转动C臂时三维图像随之同步转动", "D": "三维路径图在患者体位移动后可由系统自动识别并纠正错位，无需重新配准", "E": "使用路径图技术时必须持续注射对比剂才能维持血管背景显示"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-011", "kp": "路径图与三维路径图技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】C正确。3D roadmap把先前旋转采集重建的三维血管容积与C臂几何参数（角度、SID、床位、视野）实时关联，透视时按当前投照几何生成对应的二维投影叠加，术者转动C臂即可获得相应角度的血管背景，无需重新注射对比剂制作路径图。【为什么错】A错误：常规路径图与制作时的投照几何严格绑定，角度、床位、放大率任一改变都会失配准，必须重新制作。B错误：三维路径图的背景恰恰来自此前旋转采集重建的三维容积，若只用当次二维减影像就退化为常规路径图。D错误：任何配准都以患者与机架相对位置不变为前提，患者体动会造成三维图像与实际血管错位，需重新配准或校正。E错误：路径图的血管背景来自已保存的充盈帧，不需要持续注射，这正是其减少对比剂用量的意义。", "tr": "常规路径图「换角度即失效」，三维路径图「随角度自动更新」，这是两者的分水岭。但三维路径图仍依赖患者不动，体动后必须重新配准。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0112", "t": "案例分析题", "s": "患者男性，68岁，2型糖尿病史15年，吸烟40年。近3个月右下肢间歇性跛行进行性加重，跛行距离由500m缩短至50m，近1周出现静息痛，右足背动脉搏动未触及，踝肱指数0.38。临床怀疑右侧股腘动脉多节段狭窄闭塞，拟行下肢动脉DSA全面评估后同期球囊扩张。设备为平板探测器单C臂DSA，具备步进（bolus chase）采集与自动跟踪功能，高压注射器可编程设定流率、总量与注射时长。作为该台手术的技师，下列关于步进DSA技术要点的判断中，错误的是", "o": {"A": "先在不注射状态下沿全下肢做一次步进蒙片采集，注射后按相同床位与速度序列采集造影像，逐段对应减影", "B": "床面移动速度应与对比剂在下肢动脉内的流动速度相匹配，速度过快会「追过」对比剂前锋而使远端显影不足", "C": "严重狭窄或闭塞侧肢体血流缓慢，两侧充盈明显不对称时，可对患侧单独降低步进速度或改为分段采集", "D": "步进采集期间患者下肢必须保持不动，必要时用固定带约束并叮嘱勿咳嗽、勿移动", "E": "为提高远端小血管显示，应尽量使用高浓度对比剂并采用高流率短时间的团注方式"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-012", "kp": "下肢步进DSA（bolus chase）技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】E错误，为应选项。下肢步进DSA需要对比剂在数十秒内持续充盈由髂至足的长段血管，注射策略应是适当稀释（常用对比剂与生理盐水按约1:1稀释）、中等流率、延长注射时间的「长团注」，以保证追踪全程都有对比剂充盈；高流率短时间团注会使对比剂前锋过早通过近段而远端显影不足，且增加血管痛与外渗风险。【为什么错】A正确：步进DSA同样遵循先蒙片后造影、逐段配对减影的原则。B正确：床速与血流速度匹配是步进成功的关键，过快会超越对比剂前锋，过慢则近段过曝、远段延误。C正确：双下肢病变程度不对称时，应按患侧血流调整速度或改为分段（分站）采集，必要时行患侧选择性造影。D正确：步进过程中任何肢体移动都会造成逐段减影错位，制动与呼吸配合是基本要求。", "tr": "「浓度越高、流率越快越清楚」在步进DSA中不成立。步进强调的是「跟得上、供得久」，因此常规做法是稀释对比剂并延长注射时间，与心脏、脑血管的短团注策略相反。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0113", "t": "单选题", "s": "DSA的岁差运动（进动运动）摄影是指", "o": {"A": "C臂在单一平面内做左右摆动的往复运动采集", "B": "C臂保持焦点—影像接收器连线与检查部位中心的夹角恒定，绕该中心轴作圆锥面轨迹运动采集，形成类似陀螺岁差的运动", "C": "检查床沿长轴匀速平移，C臂固定不动", "D": "球管在阳极靶面上做焦点位置的高速跳变", "E": "C臂围绕患者作360度整圈快速旋转采集"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-013", "kp": "岁差运动摄影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】B正确。岁差运动摄影（precession motion angiography）中，C臂保持与靶区中心固定的锥角，围绕该中心作圆锥形轨迹回旋，采集轨迹在空间上如同陀螺的岁差运动。其价值在于以连续变化的投照方向观察重叠血管（如颅内动脉瘤瘤颈与载瘤动脉、分叉部血管），有助于快速寻找无重叠的工作角度。【为什么错】A错误：单平面摆动属摇篮式或摆动采集，轨迹为平面弧线而非圆锥面。C错误：床面平移属步进采集。D错误：焦点在靶面跳变是CT球管的飞焦点技术，与C臂运动无关。E错误：整圈快速旋转属旋转DSA或CBCT的采集方式，其轨迹为圆而非圆锥。", "tr": "岁差运动的关键词是「锥角恒定、圆锥面轨迹」，与旋转DSA的「单一平面圆弧」不同。二者常在同一道题中互为干扰项。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0114", "t": "多选题", "s": "关于DSA双能量减影技术，下列说法正确的是", "o": {"A": "其原理是利用碘的K吸收边（约33.2keV）两侧高、低两种能量下衰减差异悬殊，而骨与软组织差异相对较小，据此分离出碘信号", "B": "双能量减影在时间上两帧间隔极短，因而对运动伪影的敏感性低于常规时间减影", "C": "对于吞咽、心搏、肠蠕动等难以制动的部位，双能量减影较常规时间减影更具优势", "D": "双能量减影的信噪比优于时间减影，已取代时间减影成为DSA的默认减影方式", "E": "双能量减影需要在极短时间内切换管电压或使用能量分辨探测器，对设备的高压发生器响应速度要求高"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-014", "kp": "DSA双能量减影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】A正确：碘在其K吸收边上方衰减陡增，选取跨越33.2keV的高低两种能谱可最大化碘与背景组织的差异，实现能量减影。B正确：高低能两帧的时间间隔可短至毫秒级，运动错位远小于时间减影的蒙片—造影像间隔。C正确：正因时间间隔极短，双能量减影在吞咽、心搏、肠蠕动等区域优势明显。E正确：实现方式依赖高压发生器的快速kV切换或能量分辨（光子计数、双层）探测器，对硬件响应速度要求高。【为什么错】D错误：双能量减影的信噪比通常低于时间减影（两次曝光能谱差异有限、需较高剂量），且软组织减影不彻底，目前作为时间减影的补充而非替代，常规DSA仍以时间减影为主。", "tr": "能量减影的优势是「抗运动」，代价是「信噪比下降与剂量增加」。若题目出现「可完全替代时间减影」，基本可判为错误。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-0115", "t": "单选题", "s": "在主动脉腔内修复术（EVAR/TEVAR）中使用虚拟支架植入路径导航技术（如VesselNavigator类软件），其主要工作方式是", "o": {"A": "将术前采集的CTA血管三维数据与术中透视图像配准融合，把血管中心线、分支开口与虚拟支架位置实时叠加在透视上引导定位", "B": "在透视图像上直接测量血管直径后由系统自动释放支架", "C": "利用超声探头在体表实时追踪支架位置", "D": "通过磁导航系统操控支架输送系统自动前进", "E": "在不使用任何术前影像的前提下，仅凭透视图像自动识别肾动脉开口"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-015", "kp": "虚拟支架与三维影像导航", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】A正确。此类软件先导入术前CTA（或术中CBCT）容积数据，在其上标注血管中心线、肾动脉与髂内动脉等关键分支开口，并可放置虚拟支架标记；随后通过2D-3D配准（以骨性结构或术中两幅不同角度透视像为基准）将三维标注实时叠加于透视，术中转动C臂时标记随之更新，从而在极少或不用对比剂的情况下精确定位释放平面，对肾功能不全患者尤为有利。【为什么错】B错误：支架释放始终由术者手动完成，软件仅提供定位参考。C错误：体表超声无法在术中稳定追踪主动脉内支架，且不属于该技术范畴。D错误：磁导航主要用于电生理导管与部分微导丝，与虚拟支架导航是不同技术。E错误：该技术的前提正是术前或术中三维数据集，脱离三维数据无法生成血管中心线与分支标注。", "tr": "影像导航减少的是对比剂用量与造影次数，但不能纠正配准漂移。患者体位改变、导入硬鞘造成的血管形变都会引起偏差，关键释放前仍需一次确认造影。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0116", "t": "多选题", "s": "关于介入治疗常用栓塞材料的分类与特点，下列说法正确的是", "o": {"A": "明胶海绵属于中效（可吸收）栓塞剂，栓塞后数周至数月可被吸收，血管可再通", "B": "聚乙烯醇（PVA）颗粒与微球属于永久性固体栓塞剂，可按粒径选择栓塞水平", "C": "弹簧圈属于永久性机械栓塞装置，主要用于中大动脉与动脉瘤囊内栓塞", "D": "无水乙醇属于液体栓塞剂，通过使蛋白变性、内皮破坏造成永久性闭塞，使用时需严格控制反流", "E": "碘化油仅作为对比剂使用，在肝动脉化疗栓塞中不具备栓塞与载药作用"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-016", "kp": "栓塞材料分类", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】A正确：明胶海绵是典型可吸收（中效）栓塞剂，适用于外伤出血、术前暂时性栓塞。B正确：PVA颗粒及可载药微球为永久性固体栓塞剂，粒径（如100~300μm、300~500μm）决定栓塞的血管级别。C正确：弹簧圈通过机械阻塞与继发血栓形成实现永久闭塞，广泛用于动脉瘤、动静脉瘘及出血血管。D正确：无水乙醇为强效永久液体栓塞剂，作用于毛细血管床水平，反流可致非靶器官坏死与剧痛，须控制注射速度与用量。【为什么错】E错误：碘化油在肝动脉化疗栓塞中兼具对比剂、末梢栓塞与化疗药物载体三重作用，可在肿瘤内长期滞留并在随访CT上显示沉积情况。", "tr": "按持续时间可分为短效（自体血凝块）、中效（明胶海绵）、长效/永久（PVA、微球、弹簧圈、无水乙醇、氰基丙烯酸酯类）。碘化油「既是对比剂又是栓塞剂」是常考点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-0117", "t": "多选题", "s": "关于血管内支架的类型与临床选择，下列说法正确的是", "o": {"A": "球囊扩张式支架定位精度高、径向支撑力强，多用于短段、开口部病变（如肾动脉、髂动脉开口）", "B": "自膨式支架顺应性好、能适应血管直径变化和外部压迫，多用于颈动脉、股腘动脉等易受形变部位", "C": "覆膜支架可隔绝血流与瘤腔或破口，用于动脉瘤、假性动脉瘤与血管破裂", "D": "血流导向装置（密网支架）通过重建载瘤动脉血流促使动脉瘤内血栓形成，用于部分颅内动脉瘤", "E": "药物洗脱支架释放抗增殖药物，因此植入后不再需要抗血小板治疗"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-017", "kp": "血管内支架类型与选择", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】A正确：球扩支架释放位置可控性好、径向力大，适合开口部与钙化短段病变。B正确：自膨支架具持续外向支撑与形变恢复能力，适用于颈动脉、股腘动脉等活动或受压部位。C正确：覆膜支架的作用即隔绝，用于动脉瘤、假性动脉瘤、动静脉瘘与血管破裂的急诊封堵。D正确：血流导向装置以高金属覆盖率改变瘤颈血流动力学，促使瘤腔内血栓形成并实现载瘤动脉重塑。【为什么错】E错误：药物洗脱支架抑制内膜增生以减少再狭窄，但内皮化延迟反而增加支架内血栓风险，术后必须按方案进行双联抗血小板治疗。", "tr": "「球扩＝精准，自膨＝顺应」是选择支架的基本原则；颈部与关节跨越部位禁用球扩支架，因其受外力压迫后不能自行恢复。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-0118", "t": "案例分析题", "s": "患者女性，71岁，高血压病史10年，家属诉其突发右侧肢体无力伴言语不能3小时，急诊NIHSS评分16分。急诊CT平扫排除颅内出血，头颈CTA示左侧大脑中动脉M1段闭塞，具备急诊机械取栓指征。介入手术室配备双平面平板DSA、C臂锥形束CT功能与可编程高压注射器，患者在局部麻醉与镇静下接受手术。作为参与该急诊手术的技师，下列技术配合与流程判断中，错误的是", "o": {"A": "急性缺血性卒中取栓强调「时间就是脑」，术前准备、铺巾、连接高压注射器等环节应提前并行完成以缩短入院至再通时间", "B": "术中可用双平面同时采集正侧位，减少造影次数与对比剂用量，缩短手术时间", "C": "取栓过程中若怀疑血管穿孔或造影剂外渗，可即刻行CBCT扫描鉴别对比剂渗出与急性出血", "D": "术后即刻CBCT上出现高密度影时可直接判定为脑出血，无需随访复查", "E": "全程应记录累积参考点空气比释动能与剂量面积乘积，并在保证影像可用的前提下采用低脉冲率透视"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-018", "kp": "急性缺血性卒中取栓的技术配合", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】D错误，为应选项。取栓术后即刻CBCT或CT上的高密度影既可能是对比剂外渗（碘染），也可能是真性出血，两者在术后即刻难以区分；对比剂通常在24小时内明显消退或减淡，而出血持续存在甚至扩大，故须在术后24小时左右复查CT加以鉴别，必要时用双能量CT做碘—出血分离。【为什么错】A正确：卒中取栓的核心指标即再通时间，流程并行化是缩短院内延误的关键。B正确：双平面可一次注射获取两个方向影像，减少对比剂与时间成本。C正确：术中CBCT是即时排查出血与穿孔的实用手段，可避免转运。E正确：介入剂量记录与低脉冲率透视是常规剂量管理要求，急诊亦不能忽视。", "tr": "取栓术后即刻高密度＝「碘染或出血」的鉴别是高频考点。判断依据是随访演变与双能量碘图，而非即刻单次平扫的CT值高低。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0119", "t": "多选题", "s": "关于CT/MR图像与DSA的配准融合技术，下列说法正确的是", "o": {"A": "融合前需要完成空间配准，常用方法包括基于骨性标志的刚性配准与基于互信息等相似性测度的自动配准", "B": "MR与DSA融合可在术中同时参考软组织与血管信息，对肿瘤供血动脉判定、动静脉畸形靶点定位有价值", "C": "配准精度受患者体位差异、呼吸运动、器械导致的组织形变影响，腹部与胸部的配准难度大于颅脑", "D": "融合影像可减少术中造影次数与对比剂用量，但关键步骤仍应以实时造影验证", "E": "只要完成一次配准，术中无论如何移动患者与检查床，融合结果都保持准确"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-019", "kp": "CT/MR与DSA的配准融合", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】A正确：刚性配准适用于颅脑等形变小的部位，基于互信息的自动配准适合跨模态（CT/MR与X线）灰度关系非线性的情形。B正确：MR的软组织对比使肿瘤边界、脑功能区、畸形团靶点在术中可视，是单纯DSA无法提供的信息。C正确：胸腹部受呼吸、心搏与体位差异影响，配准误差显著大于颅脑，常需呼吸门控或术中CBCT重配准。D正确：融合导航能显著减少对比剂用量，但因存在配准误差，释放支架、栓塞前的关键确认仍需实时造影。【为什么错】E错误：床面移动、患者体位变化、机架几何改变都会破坏已建立的空间对应关系，需要系统自动跟踪补偿或重新配准。", "tr": "融合导航的定位是「参考」而非「判读依据」。所有涉及配准的技术都必须强调误差来源与实时验证，凡出现「一次配准永久有效」的表述均属错误。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-0120", "t": "单选题", "s": "复合手术室（Hybrid OR）中影像引导手术导航系统的核心价值在于", "o": {"A": "取代术者的手术操作，实现全自动手术", "B": "把术前三维影像、术中实时影像与器械空间位置统一到同一坐标系中，为术者提供实时空间参考", "C": "取代术中造影与病理检查，据此即可作出最终诊断", "D": "提高DSA设备的空间分辨率", "E": "免除手术室的辐射防护要求"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-020", "kp": "影像引导手术导航", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】B正确。手术导航的本质是「坐标统一」：通过配准把术前CT/MR三维数据、术中CBCT或透视影像以及器械位置（光学、电磁或影像追踪）映射到同一空间，术者据此判断器械与靶点、危险结构的相对关系，实现微创精准操作。【为什么错】A错误：导航系统提供的是信息支持，手术决策与操作仍由术者完成。C错误：导航不改变组织学诊断的必要性，也不能免除关键步骤的实时造影确认。D错误：空间分辨率取决于探测器与几何条件，导航软件不改变成像链的物理性能。E错误：复合手术室内仍使用X线，屏蔽、铅衣、剂量监测等防护要求不能减免，反而因手术时间长而更严格。", "tr": "凡是把导航、融合、人工智能描述为「取代人」「免除防护」「提高硬件分辨率」的选项，均可直接排除。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-0121", "t": "案例分析题", "s": "患者男性，54岁，乙型肝炎肝硬化背景下发现肝右叶占位，增强CT提示肝细胞癌，肝功能Child-Pugh A级，拟行肝动脉化疗栓塞（TACE）。术中常规肝动脉造影后肿瘤染色显示不清，供血动脉走行迂曲并与邻近胃十二指肠动脉分支相互重叠，难以确定超选目标。所用设备具备锥形束CT、双容积融合与肿瘤供血血管自动追踪软件，后者可从锥形束CT动脉期数据自动分析并标注供血分支路径并叠加于透视。作为配合本例手术的技师，下列判断中错误的是", "o": {"A": "可在导管置于肝固有动脉后行CBCT动脉期采集，利用其容积数据分析肿瘤染色范围与供血分支", "B": "双容积融合可把CBCT的软组织肿瘤信息与三维血管数据叠加，帮助辨认迂曲供血动脉的起源", "C": "供血血管自动追踪软件给出的路径可直接叠加于透视，指导微导管超选，但仍需造影确认后再栓塞", "D": "CBCT采集时应嘱患者屏气，注射方案宜采用低流率、适当延迟以保证采集时相内肝实质与肿瘤持续染色", "E": "既然CBCT已显示肿瘤染色，即可省略栓塞后的复查造影，直接结束手术"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-021", "kp": "CBCT融合导航在TACE中的应用", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】E错误，为应选项。栓塞后必须复查造影以评估栓塞终点、确认肿瘤染色消失、检出遗漏的侧支供血（如膈下动脉、肠系膜上动脉来源的寄生供血）并排除非靶栓塞与血管损伤，术前的CBCT无法替代栓塞后的即时疗效评价。【为什么错】A正确：肝固有动脉或肝总动脉水平的CBCT动脉期采集是评估肿瘤染色与供血分支的标准做法。B正确：双容积融合把软组织容积与血管容积叠加显示，是识别迂曲分支起源的有效手段。C正确：自动追踪软件的路径叠加用于引导超选，但栓塞前必须以微导管造影确认靶血管与有无非靶分支。D正确：CBCT采集时间长达数秒至二十余秒，需屏气制动；采用稀释低流率注射并设置合适延迟，可保证整个旋转期间染色稳定。", "tr": "任何导航或融合技术都不能替代「栓塞前超选造影确认」与「栓塞后复查造影评价」这两个安全节点。寄生供血漏栓是TACE后早期复发的重要原因。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1001", "t": "单选题", "s": "现代DSA设备成像链最核心的进展是", "o": {"A": "平板探测器（FPD）替代影像增强器-摄像管系统", "B": "普通胶片记录", "C": "荧光屏直接观察", "D": "CCD替代球管", "E": "超声探头记录"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-101", "kp": "DSA探测器进展", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】平板探测器（FPD）直接数字转换、动态范围大、无几何畸变，已取代影像增强器-摄像管/CCD系统成为DSA成像核心，故A正确。\n【为什么错】B：DSA为数字减影，不用胶片。C：荧光屏直接观察无减影能力。D：球管是X线源，不能用CCD替代。E：超声与DSA无关。", "tr": "“平板探测器化”是DSA硬件的标志性进展，替代的是影像增强器而非球管。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1002", "t": "单选题", "s": "平板探测器DSA相对于传统影像增强器DSA的主要优势是", "o": {"A": "空间分辨率高、无几何畸变、动态范围大", "B": "只能单幅成像", "C": "必须使用胶片", "D": "成像速度慢", "E": "需要暗室操作"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-102", "kp": "平板探测器DSA优势", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】平板探测器像素结构规整、探测效率高，图像空间分辨率高，无影像增强器的枕形畸变，动态范围宽，故A正确。\n【为什么错】B：FPD支持连续动态成像。C：DSA无需胶片。D：FPD成像速度快、支持高帧率。E：DSA在控制室操作，无需暗室。", "tr": "平板探测器“高清、无畸变、宽动态范围”三大优势常联合考查。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1003", "t": "单选题", "s": "DSA设备中，用于承载球管与探测器并实施任意角度投照的机械装置是", "o": {"A": "C形臂机架", "B": "高压注射器", "C": "检查床", "D": "激光相机", "E": "铅衣架"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-103", "kp": "DSA机架结构", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】C形臂机架通过机械臂旋转实现球管与探测器绕患者多角度投照，是DSA设备的核心机架结构，故A正确。\n【为什么错】B：高压注射器用于注射对比剂。C：检查床承托患者。D：激光相机用于打印。E：铅衣架为防护用品支架，均与投照机架无关。", "tr": "C形臂决定投照角度能力，双C臂系统可实现双平面同步成像。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1004", "t": "单选题", "s": "DSA路径图（Roadmap）技术的主要用途是", "o": {"A": "在实时透视中叠加血管路径图像，引导导管、导丝插管", "B": "测量血管直径", "C": "生成三维骨骼图像", "D": "打印血管照片", "E": "存储术前CT"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-104", "kp": "路径图技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】路径图技术先获取减影血管路径并作为模板，再叠加到实时透视图像上，使导管、导丝沿血管路径推进，提高插管效率与安全性，故A正确。\n【为什么错】B：血管测量属后处理分析。C：三维骨骼图像属3D重建范畴。D：照片打印与路径图无关。E：术前CT存储属数据管理。", "tr": "路径图是“减影血管模板+实时透视”的导航技术，是DSA介入的经典功能。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1005", "t": "单选题", "s": "旋转DSA采集的主要临床价值是", "o": {"A": "获取三维血管图像（3D-DSA）", "B": "提高透视亮度", "C": "缩短患者检查前准备", "D": "替代超声检查", "E": "测量骨密度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-105", "kp": "旋转DSA", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】C形臂围绕兴趣血管旋转采集多个角度投影，经三维重建获得3D-DSA血管图像，利于动脉瘤、血管畸形等多角度评价，故A正确。\n【为什么错】B：透视亮度与旋转采集无关。C：术前准备与成像方式无关。D：DSA不替代超声。E：骨密度用DXA测量。", "tr": "旋转采集→3D-DSA，是DSA从二维走向三维的标志技术。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1006", "t": "单选题", "s": "下肢动脉全程造影最常采用的特殊成像方式是", "o": {"A": "步进DSA（分段连续采集）", "B": "静态单幅摄影", "C": "头颅旋转采集", "D": "胸部双能成像", "E": "乳腺DBT"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-106", "kp": "步进DSA", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】步进DSA通过床面或C臂分段步进配合造影剂跟踪，一次注射对比剂完成腹主动脉至足部动脉全程成像，是下肢血管检查的标准方式，故A正确。\n【为什么错】B：静态单幅只能显示局部。C：头颅旋转采集用于颅内血管三维。D：双能成像用于组织分离。E：DBT用于乳腺，均不符合下肢全程造影需求。", "tr": "下肢全程看“步进DSA”，与“跟踪注射、分段步进”配合。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1007", "t": "单选题", "s": "超选择性DSA的含义是", "o": {"A": "将导管超选至目标分支血管后造影", "B": "选择最大剂量造影", "C": "选择最短曝光时间", "D": "选择最粗导管", "E": "选择平片检查"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-107", "kp": "超选择性造影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】超选择性DSA将导管头端超选进入靶器官或病灶的供血分支动脉内进行造影，减少重叠、提高小血管显示，故A正确。\n【为什么错】B：最大剂量是注射参数而非超选概念。C：最短曝光时间是采集参数。D：最粗导管与超选目的相反，超选需细导管。E：平片检查无造影与超选过程。", "tr": "“超选”指导管位置深达分支血管，而非参数选择。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1008", "t": "单选题", "s": "DSA图像后处理中“像素移位（Pixel Shift）”技术的作用是", "o": {"A": "校正患者运动引起的减影错位伪影", "B": "提高图像分辨率", "C": "增加对比剂流速", "D": "压缩图像数据", "E": "加密图像信息"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-108", "kp": "像素移位技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】减影时患者轻微运动使蒙片与造影图像错位产生伪影，像素移位通过平移、旋转蒙片像素重新对齐，减轻运动伪影，故A正确。\n【为什么错】B：分辨率由探测器决定。C：流速由高压注射器控制。D：压缩是存储环节。E：加密是安全措施，均与像素移位无关。", "tr": "像素移位是DSA运动伪影的经典校正手段，而非分辨率或剂量技术。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1009", "t": "单选题", "s": "3D-DSA重建生成的图像类型是", "o": {"A": "三维血管图像及类CT软组织图像", "B": "二维黑白平片", "C": "超声图像", "D": "核医学图像", "E": "视网膜图像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-109", "kp": "3D-DSA图像", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】旋转采集数据经三维重建可生成三维血管图像，并可重建类CT（似CT）软组织/骨骼图像供术者参考，故A正确。\n【为什么错】B：DSA本身为数字减影图像而非黑白平片。C：超声图像属超声设备。D：核医学图像属核医学设备。E：视网膜图像与DSA三维重建无关。", "tr": "3D-DSA不仅重建血管，还能生成类CT图像，辅助介入规划。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1010", "t": "单选题", "s": "DSA高压注射器与X线设备联动的主要目的是", "o": {"A": "按造影方案自动触发曝光，使对比剂峰值与采集同步", "B": "自动打印报告", "C": "调节手术床高度", "D": "自动消毒导管", "E": "控制病床温度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-110", "kp": "高压注射器联动", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】高压注射器与造影系统联动，按设定的注入延迟自动同步启动曝光，确保采集时机与对比剂到达靶血管的峰值一致，故A正确。\n【为什么错】B：报告由RIS/医师完成。C：床高由技师手动调节。D：导管消毒在术前完成。E：床温与造影无关。", "tr": "联动的本质是“注射与曝光的时间同步”，保证减影图像质量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1011", "t": "单选题", "s": "DSA图像与CT、MR图像融合（配准）的主要应用是", "o": {"A": "将三维解剖影像与实时DSA叠加，辅助介入导航", "B": "替代病理检查", "C": "测量血压", "D": "生成心电图", "E": "打印三维胶片"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-111", "kp": "DSA图像融合应用", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】将术前CTA/MRA或3D重建图像与实时DSA配准融合后叠加显示，术者可同时获得血管与骨性解剖信息，提高介入操作精准度，故A正确。\n【为什么错】B：融合影像不提供病理诊断。C：血压监测属生命体征监护。D：心电图监测属心电监护。E：三维胶片打印非融合应用。", "tr": "图像融合的核心是“多模态影像配准+实时导航”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1012", "t": "单选题", "s": "神经介入治疗颅内动脉瘤最常用的技术是", "o": {"A": "弹簧圈栓塞或支架辅助栓塞", "B": "经皮球囊成形", "C": "椎体成形术", "D": "经皮肝穿引流", "E": "心内膜消融"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-112", "kp": "神经介入栓塞技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】颅内动脉瘤介入治疗以微导管超选入瘤囊内填塞弹簧圈（必要时支架辅助）实现闭塞，故A正确。\n【为什么错】B：球囊成形用于动脉狭窄。C：椎体成形术用于椎体压缩骨折。D：经皮肝穿引流为腹部引流。E：心内膜消融用于心律失常，均非动脉瘤栓塞方法。", "tr": "动脉瘤→弹簧圈栓塞；血管狭窄→球囊/支架成形，适应证要分清。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1013", "t": "单选题", "s": "肝动脉化疗栓塞（TACE）主要用于治疗的疾病是", "o": {"A": "原发性或转移性肝癌", "B": "冠心病", "C": "脑出血", "D": "下肢静脉曲张", "E": "肺气肿"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-113", "kp": "TACE介入治疗", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】TACE将导管超选至肝脏肿瘤供血动脉，注入化疗药物与栓塞剂，使肿瘤缺血坏死，是中晚期肝癌的重要治疗手段，故A正确。\n【为什么错】B：冠心病治疗用PCI。C：脑出血多内科或手术处理。D：下肢静脉曲张多射频/硬化。E：肺气肿内科治疗，均与TACE无关。", "tr": "TACE=肝动脉+化疗+栓塞，适应证是肝癌（尤其富血供型）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1014", "t": "单选题", "s": "经皮腔内血管成形术（PTA）恢复血管通畅的基本机制是", "o": {"A": "球囊扩张使狭窄段血管机械性扩大", "B": "药物溶化斑块", "C": "激光烧灼血管", "D": "切除血管壁", "E": "移植自体血管"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-114", "kp": "血管成形术机制", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】PTA将球囊导管置于狭窄处加压扩张，通过机械力使斑块压缩、血管壁扩张而恢复管腔，故A正确。\n【为什么错】B：溶栓药物溶解血栓而非斑块成形。C：激光消融用于旋切等，非PTA机制。D：PTA不切除血管壁。E：移植血管属外科手术，均不符合。", "tr": "PTA是“球囊机械扩张”，溶栓是“药物溶解血栓”，机制不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1015", "t": "单选题", "s": "DSA图像中出现高浓度对比剂区域过白、周围结构无法分辨的现象，属于", "o": {"A": "饱和（过曝光）伪影", "B": "运动伪影", "C": "卷褶伪影", "D": "化学位移伪影", "E": "磁化率伪影"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-115", "kp": "DSA饱和伪影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】对比剂浓度过高使探测器信号饱和，该区域呈均匀过白、失去密度层次，即饱和伪影（过曝光伪影），故A正确。\n【为什么错】B：运动伪影表现为结构错位重影。C：卷褶伪影属MRI伪影。D：化学位移伪影属MRI伪影。E：磁化率伪影属MRI伪影，均与DSA饱和伪影无关。", "tr": "DSA的“过白区”是饱和伪影，属X线/探测器层面的问题，勿与MR伪影混淆。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1016", "t": "单选题", "s": "DSA减影成像中“蒙片（Mask）”指的是", "o": {"A": "对比剂到达前采集的同一体位基准图像", "B": "对比剂充盈后的图像", "C": "三维重建图像", "D": "打印胶片", "E": "患者登记信息"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-116", "kp": "DSA蒙片概念", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】蒙片是造影剂到达前、同一投照条件下采集的基准图像，用它减去对比剂充盈图像即可去除骨与软组织背景，故A正确。\n【为什么错】B：充盈图像是减影的另一帧。C：三维重建由旋转数据生成。D：打印胶片是输出。E：登记信息是管理数据，均非蒙片定义。", "tr": "DSA本质是“充盈像-蒙片”，蒙片的质量直接影响减影效果。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1017", "t": "单选题", "s": "冠状动脉造影通常采用的采集帧率约为", "o": {"A": "25~30帧/秒", "B": "1帧/秒", "C": "2帧/分", "D": "0.5帧/秒", "E": "1帧/小时"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-117", "kp": "冠脉造影帧率", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】冠状动脉随心跳快速运动，需以25~30帧/秒的高帧率连续采集，才能清晰捕捉各时相血管影像，故A正确。\n【为什么错】B：1帧/秒跟不上冠脉运动。C：2帧/分时间分辨力严重不足。D：0.5帧/秒过低。E：1帧/小时无法捕捉动态图像，均会产生运动模糊与时相丢失。", "tr": "冠脉DSA高帧率（25~30fps）是区别于外周血管低帧率的关键参数。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1018", "t": "单选题", "s": "造影剂跟踪（bolus chase）技术在DSA中的含义是", "o": {"A": "跟踪对比剂前沿自动控制采集与床面/机架移动", "B": "跟踪患者心率", "C": "跟踪导管深度", "D": "跟踪手术时间", "E": "跟踪室内温度"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-118", "kp": "造影剂跟踪技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】造影剂跟踪系统实时检测对比剂前沿位置，自动触发下一段曝光并步进床面，保证全程血管在对比剂充盈时被采集，故A正确。\n【为什么错】B：心率监测属生理监护。C：导管深度由术者操作掌握。D：手术时间与跟踪技术无关。E：室内温度与造影无关。", "tr": "bolus chase=“跟对比剂、自动步进”，是步进DSA的自动控制核心。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1019", "t": "多选题", "s": "DSA设备的硬件组成包括", "o": {"A": "X线球管", "B": "平板探测器", "C": "C形臂机架", "D": "高压注射器", "E": "MR超导磁体"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-119", "kp": "DSA硬件组成", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】DSA硬件包括X线球管、平板探测器、C形臂机架、高压注射器、导管床及图像系统等，故A、B、C、D正确。\n【为什么错】E：MR超导磁体属于磁共振设备，不属于DSA硬件。", "tr": "DSA是X线设备，MR磁体是磁共振设备部件，二者设备体系不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1020", "t": "多选题", "s": "DSA系统的软件功能包括", "o": {"A": "实时减影", "B": "路径图显示", "C": "像素移位校正", "D": "三维血管重建", "E": "自动出具病理报告"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-120", "kp": "DSA软件功能", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (2)软件", "ex": "【为什么对】DSA软件实现实时减影、路径图、像素移位、三维重建及图像分析等功能，故A、B、C、D正确。\n【为什么错】E：病理报告由病理科出具，DSA软件无此功能。", "tr": "DSA软件围绕“减影与血管成像”，诊断结论与病理诊断不在其职责内。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1021", "t": "多选题", "s": "DSA特殊成像技术包括", "o": {"A": "旋转DSA", "B": "步进DSA", "C": "超选择性DSA", "D": "双平面同步采集", "E": "MR波谱成像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-121", "kp": "DSA特殊成像技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】旋转、步进、超选及双平面同步采集均为DSA特殊成像技术，故A、B、C、D正确。\n【为什么错】E：MR波谱成像（MRS）属于磁共振技术，不属于DSA。", "tr": "“特殊成像技术”限于X线DSA范畴，MR技术不应混入。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1022", "t": "多选题", "s": "DSA介入治疗技术包括", "o": {"A": "血管栓塞术", "B": "球囊扩张成形术", "C": "支架植入术", "D": "动脉内溶栓术", "E": "体外冲击波碎石"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-122", "kp": "DSA介入治疗技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】栓塞、球囊成形、支架植入、动脉内溶栓均属DSA引导下的血管介入治疗技术，故A、B、C、D正确。\n【为什么错】E：体外冲击波碎石属泌尿系非血管治疗，与DSA介入无关。", "tr": "DSA介入以血管系统为核心，体外碎石不是血管介入。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1023", "t": "多选题", "s": "DSA图像融合技术的应用包括", "o": {"A": "术前CTA与术中DSA配准融合辅助神经介入", "B": "3D血管与骨性解剖融合指导椎体成形", "C": "肝肿瘤供血动脉定位融合导航", "D": "DSA与MR血管成像融合辅助AVM治疗", "E": "融合图像替代术后病理"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-123", "kp": "DSA图像融合应用", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】融合技术将DSA血管信息与CT/MR三维解剖信息配准，用于神经介入、椎体成形、肝介入及AVM治疗导航等，故A、B、C、D正确。\n【为什么错】E：融合影像是导航工具，不能替代病理诊断。", "tr": "图像融合“导航不诊断”，其价值在手术精准定位。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1024", "t": "多选题", "s": "影响DSA图像质量的操作技术因素包括", "o": {"A": "采集帧率", "B": "减影矩阵大小", "C": "对比剂浓度与流速", "D": "曝光参数选择", "E": "患者姓名"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-124", "kp": "DSA图像质量因素", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】帧率决定时间分辨力，矩阵决定空间分辨力，对比剂浓度流速与曝光参数决定血管显示质量，故A、B、C、D正确。\n【为什么错】E：患者姓名属于管理信息，不影响图像质量。", "tr": "DSA质量由“时间、空间、对比度、曝光”四类技术参数决定。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1025", "t": "多选题", "s": "DSA运动伪影的校正与预防方法包括", "o": {"A": "使用像素移位校正", "B": "嘱患者屏气减少呼吸运动", "C": "采用重新选取合适蒙片", "D": "加用患者固定装置", "E": "加大对比剂浓度"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-125", "kp": "DSA运动伪影处理", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】像素移位校正错位、屏气减少呼吸移动、重新选蒙片避开移动帧、固定装置限制体动，均可减少运动伪影，故A、B、C、D正确。\n【为什么错】E：加大对比剂浓度会增加饱和伪影风险，不能解决运动伪影。", "tr": "运动伪影用“移位校正+配合+固定+选片”，与对比剂浓度无关。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1026", "t": "多选题", "s": "高压注射器注射参数设置包括", "o": {"A": "注射流速", "B": "注射总量", "C": "压力限制", "D": "注射延迟时间", "E": "胶片灰度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-126", "kp": "高压注射器参数", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】流速、总量、压力限制与注射延迟是高压注射器四项核心参数，共同决定对比剂到达时机与充盈质量，故A、B、C、D正确。\n【为什么错】E：胶片灰度属打印参数，与注射器无关。", "tr": "注射参数决定“何时打、打多少、多快打”，与成像显示参数无关。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1027", "t": "多选题", "s": "平板探测器DSA相对于传统影像增强器的优势包括", "o": {"A": "无几何畸变", "B": "动态范围大、层次丰富", "C": "量子探测效率（DQE）高、剂量低", "D": "空间分辨率高", "E": "必须配备专用胶片"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-127", "kp": "平板探测器优势", "ch": "十五、DSA技术的进展 → 1.DSA设备 → (1)硬件", "ex": "【为什么对】平板探测器无枕形畸变、动态范围大、DQE高有利于低剂量成像、像素规整空间分辨率高，故A、B、C、D正确。\n【为什么错】E：DSA为全数字采集，不需胶片记录。", "tr": "“无畸变、宽动态、高DQE、高分辨”是平板探测器四大优势。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影设备", "页": 379}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1028", "t": "多选题", "s": "DSA介入手术中工作人员防护措施包括", "o": {"A": "穿戴铅衣、铅帽、铅围脖", "B": "使用铅屏风与防护吊帘", "C": "佩戴个人剂量监测元件", "D": "合理选择投照角度减少散射线", "E": "不使用任何防护设备"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-128", "kp": "DSA介入防护", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】铅衣等个人防护、铅屏风等设施防护、剂量监测与投照角度优化是介入防护的完整体系，故A、B、C、D正确。\n【为什么错】E：不使用防护设备将导致工作人员超剂量照射，严重违反防护原则。", "tr": "介入防护=个人防护+设施防护+剂量监测+操作优化，缺一不可。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U15-1029a", "t": "单选题", "s": "【病例】患者男性，58岁，乙肝肝硬化病史，CT发现肝右叶富血供占位，临床诊断为原发性肝癌，拟行TACE介入治疗。术中在DSA引导下完成动脉造影、导管超选与栓塞。 TACE术前，为明确肿瘤供血动脉及有无肝动脉变异，术中首先应完成的DSA检查是", "o": {"A": "腹腔干-肝总动脉造影及选择性肝动脉造影", "B": "冠状动脉造影", "C": "脑血管造影", "D": "下肢动脉造影", "E": "肺动脉造影"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-129", "kp": "TACE术前造影", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】肝癌TACE需先行腹腔干-肝总动脉造影全面了解肝动脉解剖、肿瘤血供及变异，再超选至肝固有动脉或肿瘤供血支，故A正确。\n【为什么错】B：冠状动脉造影用于心脏。C：脑血管造影用于颅内。D：下肢动脉造影用于下肢。E：肺动脉造影用于肺循环，均非肝癌介入的造影路径。", "tr": "肝癌介入路径是“腹腔干→肝总动脉→肝固有动脉→肿瘤供血支”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1029b", "t": "单选题", "s": "栓塞治疗完成后，判断肿瘤栓塞程度最直观的DSA观察指标是", "o": {"A": "肿瘤区血管内碘油/栓塞剂沉积与对比剂不再充盈", "B": "肿瘤大小立即缩小", "C": "患者体温升高", "D": "造影机散热情况", "E": "注射器剩余对比剂量"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-130", "kp": "栓塞程度评价", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】栓塞后造影可见肿瘤供血动脉截断、瘤区内碘油等栓塞剂沉积、对比剂不再进入瘤体，是判断栓塞彻底的最直接依据，故A正确。\n【为什么错】B：肿瘤大小不会即刻缩小。C：发热为术后反应，非术中评价指标。D：造影机散热情况与栓塞程度无关。E：注射器剩余对比剂量与栓塞程度无关。", "tr": "“栓塞终点”看血管影像：供血动脉不显影、瘤体无对比剂充填。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1030a", "t": "单选题", "s": "【病例】患者男性，70岁，双下肢间歇性跛行2年，加重伴左足静息痛1个月，临床拟诊下肢动脉硬化闭塞症，行下肢动脉DSA检查明确病变范围。检查范围需覆盖腹主动脉分叉至足部。 为一次对比剂注射完成双下肢全程动脉成像，最适宜的DSA技术是", "o": {"A": "步进DSA（bolus chase）", "B": "静态单幅摄影", "C": "头颅旋转采集", "D": "乳腺DBT", "E": "胸片拼接"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-131", "kp": "下肢全程DSA技术", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】步进DSA配合造影剂跟踪，可一次注射对比剂分段连续采集腹主动脉至足部动脉，满足全程显示需求，故A正确。\n【为什么错】B：静态单幅仅显示局部。C：头颅旋转采集用于颅内。D：DBT用于乳腺。E：拼接用于平片长部位，均不符合下肢DSA全程动态成像。", "tr": "“下肢全程动脉”对应步进DSA，跟踪对比剂自动分段步进。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1030b", "t": "单选题", "s": "步进DSA中保证各段图像质量的关键操作是", "o": {"A": "床面/机架步进与对比剂前沿到达时机同步", "B": "任意速度步进", "C": "减少对比剂总量至最低", "D": "全程使用最大帧率", "E": "关闭减影功能"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-132", "kp": "步进DSA操作要点", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】步进时机必须与对比剂前沿一致，保证每一段血管在其充盈峰值时被采集，否则出现未充盈或已排空段，故A正确。\n【为什么错】B：速度不匹配导致血管显示不全。C：总量过低对比剂稀释显示差。D：全程最大帧率徒增剂量且非必需。E：关闭减影则背景干扰明显，均错误。", "tr": "bolus chase的成败在“步进与对比剂同步”，即“跟踪”二字的含义。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1031a", "t": "单选题", "s": "【病例】患者女性，52岁，突发剧烈头痛伴呕吐，头颅CTA提示前交通动脉瘤，拟行血管内弹簧圈栓塞。术前计划利用3D-DSA全面评价动脉瘤形态，术中结合图像融合导航实施栓塞。 术前评价动脉瘤颈与载瘤动脉关系的最佳DSA方法是", "o": {"A": "旋转DSA采集并进行3D血管重建", "B": "静态正位单幅摄影", "C": "下肢步进DSA", "D": "乳腺DBT", "E": "胸片双能成像"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-133", "kp": "3D-DSA动脉瘤评价", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】旋转DSA多角度采集后三维重建，可从任意角度观察动脉瘤颈、瘤体及与载瘤动脉的关系，指导栓塞方案，故A正确。\n【为什么错】B：单幅正位无法全面显示三维空间关系。C：步进DSA用于下肢全程血管。D：DBT用于乳腺。E：胸片双能成像用于组织分离，均与颅内动脉瘤评价无关。", "tr": "动脉瘤“颈-体-载瘤动脉”关系靠3D-DSA多角度观察。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1031b", "t": "单选题", "s": "术中为将术前CTA血管解剖与实时DSA透视相结合指导微导管到位，应使用", "o": {"A": "DSA与CTA图像配准融合导航", "B": "单纯黑白透视", "C": "心电图监测", "D": "血压监测", "E": "尿量监测"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-134", "kp": "DSA图像融合导航", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】将术前CTA的三维血管图像与术中实时DSA配准融合，术者结合导航图像选择栓塞角度与微导管方向，提高精准度，故A正确。\n【为什么错】B：单纯黑白透视无三维解剖信息。C：心电图监测为生命体征监测。D：血压监测为生命体征监测。E：尿量监测为生命体征监测，均与影像导航无关。", "tr": "“术前三维+术中实时”的配准融合是DSA图像融合技术的核心价值。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1032", "t": "案例分析题", "s": "患者女性，60岁，行腹部DSA检查时配合不佳，减影图像出现血管边缘重影、骨结构错位，病变血管显示不清。技师分析为呼吸运动引起蒙片与充盈像不匹配所致。需要采取有效措施重新获得清晰减影图像。减影原理为造影充盈图像减去蒙片，蒙片与充盈图像几何不一致即产生错位伪影。可先尝试屏气重新采集，再考虑对已有数据进行软件校正。下列处理措施中首选的是", "o": {"A": "嘱患者屏气后重新采集或使用像素移位校正", "B": "加大对比剂流速", "C": "提高帧率到100帧/秒", "D": "直接放弃检查", "E": "加用造影剂总量"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-135", "kp": "DSA运动伪影处理", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】屏气配合可消除呼吸导致的减影错位，像素移位可对已采集数据校正，均是处理运动伪影的首选措施，故A正确。\n【为什么错】B：流速与运动伪影无关且可能加重饱和。C：100帧/秒非DSA常规且增剂量。D：放弃检查丧失诊断信息。E：增大总量不解决错位，均错误。", "tr": "运动伪影“先配合后校正”，屏气与像素移位是标准处理。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1033", "t": "案例分析题", "s": "患者男性，62岁，临床怀疑冠心病，行选择性冠状动脉造影。患者心率70次/分，造影中需要评估左主干及前降支中段狭窄程度并动态观察血流灌注情况，为介入治疗决策提供依据。技师选择DSA采集方案时，冠脉造影需兼顾时间分辨力与辐射剂量，帧率选择要能清晰显示血管充盈各时相。采集方案应在图像质量与患者受照剂量之间取得平衡。最合理的帧率设置是", "o": {"A": "25~30帧/秒高帧率连续采集", "B": "1帧/秒", "C": "0.5帧/分钟", "D": "单帧曝光", "E": "不采集只透视"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-136", "kp": "冠脉DSA帧率选择", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】冠状动脉随心动周期快速运动，评估狭窄需观察舒张期充盈等各时相，须用25~30帧/秒高帧率采集，故A正确。\n【为什么错】B：1帧/秒无法捕捉冠脉运动时相。C：0.5帧/分钟时间分辨力严重不足。D：单帧曝光不能动态评估血流。E：仅透视无法记录高质量减影图像。", "tr": "心脏DSA高帧率是基本原则，低帧率会导致冠脉图像模糊与时相缺失。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1034", "t": "案例分析题", "s": "某患者行腹主动脉造影时，由于对比剂浓度过高、注射流速过大，图像中主动脉与分支汇合区域出现大片均匀过白、血管边缘与腔内结构均无法分辨，无法评价血管病变。技师判断为饱和伪影。饱和伪影是探测器信号溢出所致，可通过降低对比剂浓度、流速或调整曝光参数使信号回落至动态范围内。调整后再行造影确认血管显示恢复正常方能继续检查。下列改进措施中最恰当的是", "o": {"A": "适当降低对比剂浓度或流速，必要时调整曝光参数避免饱和", "B": "大幅增加注射总量", "C": "改用MRI检查", "D": "提高帧率", "E": "延长曝光时间"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-137", "kp": "DSA饱和伪影处理", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】饱和伪影源于探测器信号溢出，降低对比剂浓度/流速使信号回落至动态范围以内，并配合曝光优化，可恢复血管细节显示，故A正确。\n【为什么错】B：增加总量加重饱和。C：换MRI不解决DSA问题且检查目的不符。D：帧率不影响信号强度。E：延长曝光增加剂量与运动风险，均错误。", "tr": "饱和伪影的核心对策是“降浓度/降流速+优化曝光”，使信号不溢出。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1035", "t": "案例分析题", "s": "介入手术室内进行一台复杂的肝癌TACE手术，预计透视与采集时间较长，术者受照剂量风险高。技师与护士共同核对手术人员的防护装备与剂量监测措施。以下做法中介入防护应遵循个人防护、设施防护、剂量监测与操作优化相结合的原则，剂量计须反映真实受照水平。个人剂量计应佩戴于铅衣内侧以准确反映实际器官受照。最符合放射防护要求的是", "o": {"A": "术者穿戴铅衣并佩戴个人剂量计，使用铅屏风，尽量缩短透视时间", "B": "术者不穿铅衣以追求操作灵活", "C": "使用最大放大倍率全程透视", "D": "将个人剂量计放在铅衣外", "E": "远离铅屏风进行操作"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-138", "kp": "介入放射防护实施", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (2)DSA介入治疗技术", "ex": "【为什么对】铅衣+剂量计+铅屏风+缩短照射时间是介入防护的核心组合，故A正确。\n【为什么错】B：不穿铅衣使个人受照明显增加。C：最大放大倍率会增加剂量。D：剂量计应戴在铅衣内反映真实器官剂量。E：远离铅屏风失去屏蔽保护，均错误。", "tr": "个人剂量计戴在铅衣内测真实受照，铅屏风要置于术者与患者之间。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1036", "t": "案例分析题", "s": "某患者行颅内动脉瘤栓塞术，术前拟行3D-DSA全面评价动脉瘤形态。技师设置旋转DSA采集参数时需综合考虑图像质量、对比剂用量与采集时长，保证重建数据完整可用。关于旋转DSA采集参数，旋转DSA采集时C形臂按设定角度与速度旋转，帧数决定重建数据密度，对比剂注入需与旋转同步。设置不当可致重建血管缺失或质量下降，须按设备规范选择。正确的做法是", "o": {"A": "根据旋转角度设置合适的采集帧数与速度，配合适量对比剂一次完成", "B": "帧数越少越好", "C": "旋转角度越大越慢越好", "D": "不使用对比剂", "E": "采用静态采集"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-139", "kp": "旋转DSA参数设置", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (1)DSA特殊成像技术", "ex": "【为什么对】旋转角度、采集帧数与对比剂注入量需匹配设计，保证重建数据完整且对比剂充盈充分，一次采集完成，故A正确。\n【为什么错】B：帧数过少重建质量差。C：旋转速度过慢造成时间分辨不足且患者不适。D：无对比剂无法显示血管。E：静态采集无三维数据，均错误。", "tr": "3D重建要求“角度覆盖+帧数+对比剂”三者匹配。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U15-1037", "t": "案例分析题", "s": "某神经介入中心开展DSA与术前CTA图像融合导航技术，术中融合影像出现血管错位、与实时透视不吻合，影响微导管与弹簧圈定位。技师分析可能为配准精度不足或患者体位变化所致。下列措施中能融合配准以骨性或血管标志为基准，患者头位变化会使术前影像与术中透视错位。配准成功后应锁定患者头位并固定体位，减少术中漂移。最有效改善融合准确度的是", "o": {"A": "采用骨性标志或血管标志点重新配准，并固定患者头位", "B": "增大融合图像亮度", "C": "关闭导航系统", "D": "更换导管类型", "E": "提高对比剂浓度"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十五", "un": "DSA技术进展", "kpid": "UNIT-15-DSA-140", "kp": "DSA图像融合质量控制", "ch": "十五、DSA技术的进展 → 2.DSA相关技术 → (3)DSA图像融合技术", "ex": "【为什么对】重新以骨性/血管标志配准可修正坐标误差，固定头位可避免体位漂移，是提高融合精度的根本措施，故A正确。\n【为什么错】B：亮度不影响几何配准。C：关闭导航放弃技术价值。D：导管类型与配准无关。E：浓度只影响血管显示，不解决空间错位。", "tr": "融合精度取决于“配准质量+体位稳定”，与显示参数无关。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "数字减影血管造影技术的进展", "节": "数字减影血管造影相关技术", "页": 381}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0101", "t": "单选题", "s": "现代CT球管采用的飞焦点（flying focal spot）技术，其主要作用是", "o": {"A": "通过电磁偏转使阳极靶面上的焦点在z轴和／或扇形方向高速跳变，使采样数变为原来的两倍，提高采样密度、抑制混叠伪影并改善空间分辨率", "B": "通过移动球管的物理位置扩大扫描范围", "C": "其设计目的是使阳极靶面受热点分散，从而提高球管的热容量", "D": "在扫描中动态改变管电压实现能量成像", "E": "使焦点尺寸随扫描进程连续增大以提高输出功率"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-001", "kp": "飞焦点技术", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】A正确。飞焦点通过在电子束路径上施加快速变化的电磁偏转场，使焦点在阳极靶面上于两个（或多个）位置间以微秒级切换。z轴飞焦点使每转的层采样数加倍，等效于探测器z向排数翻倍，可抑制阶梯状伪影并改善纵向分辨率；扇形（α方向）飞焦点则使投影角采样加倍，提高平面内分辨率并抑制混叠（moiré）伪影。【为什么错】B错误：扫描范围由床进给与准直决定，与焦点跳变无关。C错误：分散靶面热负荷只是飞焦点的伴随效应，其设计目的是提高采样密度；热容量取决于阳极质量、材料与散热结构，与焦点是否跳变无关。D错误：动态改变管电压是快速kV切换双能技术。E错误：焦点尺寸由灯丝与聚焦极控制，飞焦点改变的是位置而非尺寸；焦点变大只会降低分辨率。", "tr": "飞焦点的核心是「采样加倍」，不是「热容量提升」。z轴飞焦点常被描述为「双倍层采集」，容易与真正的探测器排数混淆——它不增加探测器排数，只增加采样点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0102", "t": "多选题", "s": "关于新型CT球管的技术进展，下列说法正确的是", "o": {"A": "液态金属滑动轴承以液态金属膜替代滚珠轴承，摩擦小、噪声低，且导热性好，有利于阳极热量向外传导", "B": "旋转阳极管的电子束偏转配合阳极直接油冷（如Straton、Vectron类设计）可显著提高散热率，缩短连续扫描间的冷却等待", "C": "散热率的提升使大范围、长时间、高毫安秒扫描（如全身CTA、灌注、心脏多期采集）成为可能", "D": "球管阳极靶面材料多采用高原子序数、高熔点的钨或钨铼合金", "E": "现代球管的进步已使阳极热容量与散热率不再构成任何扫描协议的限制因素"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-002", "kp": "CT球管的轴承与散热进展", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】A正确：液态金属（镓基合金）滑动轴承接触面积大、无点接触磨损，兼具润滑与导热双重功能。B正确：将阳极靶直接浸于循环冷却油中并配合电子束偏转控制受热区域，可大幅提高连续散热率。C正确：散热能力提高直接转化为临床能力——长范围血管成像、灌注多期扫描不再频繁等待冷却。D正确：钨（Z=74）及钨铼合金兼具高X线产额与高熔点、抗热龟裂性能。【为什么错】E错误：即便散热率提高，超长范围灌注、大体重患者高输出扫描仍可能触及球管热限，扫描协议设计仍须考虑热容量与散热率，「不再构成任何限制」过于绝对。", "tr": "热容量（可储存的总热量，单位MHU）与散热率（单位时间散出的热量，kHU/min）是两个不同参数。连续多期扫描更依赖散热率而非单纯的热容量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT设备的进展", "页": 387}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-0103", "t": "单选题", "s": "宽体探测器CT（z轴覆盖达16cm左右）在临床应用中的突出优势是", "o": {"A": "可对心脏、颅脑等器官实现单个机架旋转内的一次性轴扫覆盖，实现同期相成像并便于全器官灌注", "B": "彻底消除了锥形束伪影", "C": "空间分辨率随z轴覆盖宽度增加而同步提高", "D": "无需心电门控即可完成冠状动脉成像", "E": "扫描野内的散射线随覆盖范围增大而减少"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-003", "kp": "宽体探测器进展", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】A正确。约16cm的z轴覆盖可将整个心脏或全脑纳入一次轴向扫描，避免了分段采集的层间错层与时相不一致，使「一个心动周期内完成心脏成像」和「全脑CT灌注」成为可能，同时便于低剂量前瞻性门控。【为什么错】B错误：z轴覆盖越宽，边缘层面的锥角越大，锥形束伪影反而更突出，需依靠锥束重建算法（如Feldkamp类及其改进算法）校正，不可能「彻底消除」。C错误：空间分辨率取决于探测器单元尺寸、焦点与重建算法，与z轴覆盖宽度无必然关系。D错误：冠状动脉成像仍需心电门控或触发以获得稳定时相。E错误：照射体积增大，散射线随之增加，宽体系统对散射校正与抗散射栅的要求更高。", "tr": "宽体探测器解决的是「时间一致性与覆盖效率」，代价是「锥角伪影与散射增加」。把覆盖宽度等同于分辨率提升是典型错误。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0104", "t": "多选题", "s": "关于光子计数探测器CT（PCD-CT）与传统能量积分探测器（EID）的比较，下列说法正确的是", "o": {"A": "PCD直接把X线光子转换为电信号并逐个计数，可按能量阈值分箱，无需闪烁体—光电二极管两步转换", "B": "PCD取消了探测器单元间的反射隔板，几何剂量效率提高，且可做更小的探测器单元以提高空间分辨率", "C": "EID的输出与光子能量加权相关，低能光子贡献被低估；PCD对每个光子等权计数，可提高软组织与碘的对比噪声比", "D": "PCD可在一次扫描中获得多个能量区间的数据，天然具备多能量（谱）成像能力", "E": "PCD既能排除电子学噪声，也不受脉冲堆积与电荷共享的影响，计数率越高图像质量越好"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-004", "kp": "光子计数CT原理与优势", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】A正确：PCD采用碲化镉／碲锌镉等半导体直接转换材料，光子入射即产生电荷脉冲，经甄别器按阈值分箱计数。B正确：无需闪烁体间的反射隔板，减少了死区面积，单元可做到亚毫米以下，超高分辨率模式因此成为可能。C正确：EID按能量积分，低能光子权重低，而低能光子恰恰携带较高的碘对比信息；PCD等权计数并可设阈值排除电子学噪声，碘对比噪声比提高。D正确：能量分箱使单次扫描即产生多能量数据，无需双源、kV切换或双层结构。【为什么错】E错误：PCD可通过能量阈值排除低幅度电子学噪声，但在高通量下存在脉冲堆积与电荷共享，导致能量分辨与计数线性度下降，是该技术的主要工程难点，「计数率越高越好」不成立。", "tr": "PCD的抗噪优势是「阈值以下的电子学噪声被剔除」，不等于「无噪声」。量子噪声依然存在，且高计数率下的脉冲堆积是其固有瓶颈。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-0105", "t": "单选题", "s": "关于CT迭代重建（IR）技术的代际演进与图像特征，下列说法正确的是", "o": {"A": "混合型迭代重建（如ASIR、iDose、AIDR-3D类）主要在投影域与图像域做统计降噪，计算量较小；基于模型的迭代重建（如MBIR/IMR/Veo类）引入系统光学与统计模型，降噪与分辨率保持更好但重建耗时长", "B": "迭代重建与滤波反投影的噪声—剂量关系相同，其优势仅在于重建速度更快", "C": "迭代重建强度越高图像越接近真实解剖，不存在任何副作用", "D": "迭代重建只能用于低剂量扫描，常规剂量下不可使用", "E": "迭代重建通过增加管电流来降低噪声"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-005", "kp": "迭代重建的代际与特征", "ch": "十六、CT技术的进展 → 1.CT设备 → (3)软件系统", "ex": "【为什么对】A正确。第一代混合迭代在原始数据域与图像域交替做有限次统计降噪，重建速度接近临床可接受水平；基于模型的迭代重建则对X线光子统计、焦点与探测器几何、体素响应建模，进行多次正投影—反投影迭代，噪声—分辨率折衷显著优于滤波反投影，但计算量大、重建时间长。【为什么错】B错误：滤波反投影为解析算法，噪声与剂量的关系固定，迭代重建可在同等剂量下明显降噪。C错误：高强度迭代会产生「蜡样／塑料感」的图像纹理改变，并可能降低低对比物体的可探测性，强度需按部位与临床任务权衡。D错误：常规剂量下同样可使用迭代重建以提高图像质量或保留剂量余量。E错误：迭代重建是重建算法层面的处理，不改变采集时的管电流，其价值恰在于允许降低管电流。", "tr": "迭代重建的代价是图像纹理改变与低对比可探测性可能下降，因此不宜盲目使用最高强度；肝脏等低对比任务尤其要注意。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0106", "t": "多选题", "s": "关于CT深度学习图像重建（DLR）技术，下列客观描述正确的是", "o": {"A": "多以高剂量／全采样数据重建的图像为训练目标，学习从低剂量或欠采样数据到高质量图像的映射", "B": "与高强度迭代重建相比，DLR在大幅降噪的同时通常能更好地保留接近滤波反投影的图像纹理", "C": "推理阶段计算主要由专用硬件完成，重建速度通常快于基于模型的迭代重建", "D": "其性能依赖训练数据的分布，遇到训练集中少见的解剖变异、植入物或极端体型时可能出现表现下降", "E": "DLR可以恢复采集时缺失的信息，因此降低扫描剂量时不必再顾虑低对比可探测性"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-006", "kp": "深度学习CT重建的原理与局限", "ch": "十六、CT技术的进展 → 1.CT设备 → (3)软件系统", "ex": "【为什么对】A正确：主流DLR采用监督学习范式，以高质量参考图像作为学习目标。B正确：DLR的一个重要卖点即在降噪的同时维持接近滤波反投影的噪声功率谱，减轻迭代重建的「蜡样」纹理。C正确：训练完成后推理为前向计算，配合专用加速硬件，速度通常优于多次迭代的模型迭代重建。D正确：泛化能力受训练数据分布约束，罕见解剖、金属植入物、超重或极瘦患者可能超出分布而导致细节丢失或伪结构，这是需要临床警惕的局限。【为什么错】E错误：算法只能利用先验统计规律做合理估计，不能创造采集中真正缺失的信息；过度降剂量时可能产生「看似干净却丢失或虚构细节」的图像，剂量下调必须以临床任务的可诊断性为界。", "tr": "DLR不是「无损降剂量」的许可证。评价其性能不能只看噪声标准差，还要评估低对比可探测性与小病灶的保真度。并非所有在用设备都配备DLR，选择重建方式应以本机实际配置为准。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-0107", "t": "多选题", "s": "关于双能量CT几种实现方式的原理与优缺点，下列说法正确的是", "o": {"A": "双源双能（两套球管—探测器成约90度安装，分别用低kV与高kV）能谱分离好、两管电流可独立调节，但两套数据存在时间差与交叉散射，且第二探测器视野较小", "B": "快速kV切换（单球管在相邻投影间高速切换80/140kV）时间与空间配准好、可全视野能量成像，但低kV时管电流调节受限、能谱分离依赖滤过与后处理", "C": "双层探测器（上层吸收低能光子、下层吸收高能光子）为探测器侧能量分离，时间与空间完全一致，可回顾性生成能谱数据，但两层能谱重叠较多、分离度受限", "D": "双螺旋（同一部位先后两次不同kV扫描）实现简单，但两次扫描间隔长，对运动器官与增强时相变化敏感，主要用于静态部位", "E": "光子计数探测器通过能量阈值分箱实现能谱分离，但必须配合两个球管才能完成双能采集"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-007", "kp": "双能量CT实现方式的对比", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】A正确：双源双能以物理独立的两套成像链获得最佳能谱分离（可对高kV加锡滤过），并能按体型分别设定管电流；代价是两套数据存在约四分之一转的时间差、存在交叉散射，且B探测器视野常小于A（约33~35cm）。B正确：kV切换在同一球管、同一探测器上完成，时间与空间配准好、全视野可用，但切换周期内低kV的管电流提升空间有限，剂量与噪声平衡较难。C正确：双层探测器为「探测器侧」分离，两套数据严格同源同时，可对常规扫描回顾性做能谱分析；但两层吸收的能谱重叠较多，物质分解能力弱于能谱分离更好的方案。D正确：双螺旋（两次扫描）实现门槛最低，但受运动与对比剂时相变化影响大，仅适合静态部位（如结石成分分析）。【为什么错】E错误：光子计数探测器单球管单次扫描即可完成多能量分箱采集，不需要两个球管，这正是其相对既往方案的优势之一。", "tr": "记忆抓手：双源＝能谱分离最好但视野与时间配准受限；kV切换＝配准好但剂量调节受限；双层＝配准最好、可回顾但分离度最弱；双螺旋＝只适合静态；光子计数＝单源单扫描即多能量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-0108", "t": "单选题", "s": "下列临床问题中，最不适合依靠能量CT（双能量）后处理解决的是", "o": {"A": "鉴别肾结石为尿酸盐结石还是含钙结石", "B": "在增强扫描基础上生成虚拟平扫以减少一次平扫曝光", "C": "评估肺栓塞患者的肺灌注碘分布", "D": "鉴别肾上腺腺瘤与转移瘤时替代化学位移MRI直接测定细胞内脂质含量", "E": "鉴别急性痛风患者关节周围沉积物是否为尿酸盐结晶"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-008", "kp": "能量CT的应用范围与边界", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】D最不适合。鉴别肾上腺腺瘤依靠的是细胞内脂质导致的低CT值（平扫≤10HU）或增强廓清率，双能量可通过虚拟平扫与脂／水物质对提供辅助信息，但对细胞内微量脂质的测定灵敏度有限，公认的直接检测手段是化学位移MRI的同反相位序列，双能量CT不能直接替代。【为什么错】A适合：尿酸盐结石与含钙结石的双能量比（如80kV与140kV下CT值之比）差异显著，是双能量最成熟的应用之一。B适合：VNC由碘图从增强数据中扣除碘信号生成，是减少平扫曝光的常规手段。C适合：肺动脉CTA同步生成肺碘分布图（肺灌注血容量图），可显示栓塞相应肺段的灌注缺损。E适合：双能量对单钠尿酸盐结晶的物质分解已有成熟的痛风成像方案，可显示关节周围绿色标记的尿酸盐沉积。", "tr": "「双能量万能」是常见误判。双能量擅长的是元素有效原子序数差异大的物质分解（碘、钙、尿酸、脂肪），对细胞内微量脂质、软组织成分细微差异的能力有限。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0109", "t": "案例分析题", "s": "患者女性，46岁，突发右侧腰部绞痛3天并向会阴部放射，伴镜下血尿，急诊超声提示右肾积水及输尿管上段结石可能。既往有肾结石反复发作史，本次化验血肌酐轻度升高，估算肾小球滤过率约55mL/(min·1.73m²)。临床希望明确结石的位置、大小与化学成分，以决定采用体外冲击波碎石还是口服药物碱化尿液溶石。所在科室拥有具备双能量功能的CT。作为技师，下列扫描与后处理方案中最合理的是", "o": {"A": "先行常规低剂量平扫定位结石，再对结石所在区域行双能量采集，用双能量比与物质分解分析成分", "B": "直接行常规单能量增强扫描，通过强化程度判断结石成分", "C": "只做高分辨率薄层平扫，根据CT值绝对数值即可确定结石成分", "D": "行全腹双能量增强扫描并生成碘图，据碘图判断结石成分", "E": "行CT尿路造影延迟期扫描，用对比剂包绕形态推断结石成分"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-009", "kp": "能量CT在泌尿系结石中的应用流程", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】A最合理。结石成分分析必须在平扫（无碘）条件下进行，先以低剂量平扫全泌尿系定位，再仅对结石节段行双能量采集，既满足成分分析需要，又把双能量的辐射负担限制在小范围，符合剂量最优化原则。双能量可可靠区分尿酸盐结石（低双能量比，适合药物碱化溶石）与含钙／胱氨酸结石（高双能量比，倾向碎石处理）。【为什么错】B错误：结石不强化，增强不但无助于成分判断，还因碘掩盖结石密度而干扰评估；该患者肌酐升高更应慎用对比剂。C错误：单能量CT值受结石大小、部分容积效应与管电压影响，重叠区间大，不能仅凭绝对CT值定成分。D错误：碘图用于评价含碘强化，与结石成分无关，且同样存在对比剂使用问题。E错误：延迟期高密度对比剂会完全掩盖结石，形态学也不能反映化学成分。", "tr": "结石成分分析的三个前提：平扫、双能量、结石足够大（一般直径大于3~5mm，过小者受部分容积效应影响判断不可靠）。有碘存在时一律不能做成分分析。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0110", "t": "单选题", "s": "在能量CT虚拟单能量图像（VMI）中选择40~50keV的低keV重建，其主要目的是", "o": {"A": "提高碘的CT值与血管—软组织对比，改善对比剂用量不足、心排量低或远端小血管显示不佳的病例", "B": "降低图像噪声", "C": "减少金属植入物周围的射线硬化伪影", "D": "去除图像中的骨性结构", "E": "把增强图像转换为虚拟平扫图像"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-010", "kp": "低keV虚拟单能量图像的应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (2)单能谱CT临床应用", "ex": "【为什么对】A正确。虚拟单能量的keV越接近碘的K吸收边（33.2keV），碘的质量衰减系数越大，碘的CT值随之显著升高（40keV时碘CT值可达常规120kV图像的2~3倍），从而提高血管强化程度与病灶的碘对比，适用于对比剂减量、肾功能受限、心排量低或远端细小血管显示不良的情形。【为什么错】B错误：低keV重建通常伴随噪声升高（尤其40keV以下），需依靠迭代或频域去噪算法补偿。C错误：减少金属与射线硬化伪影需要选择高keV（一般100~140keV以上）并结合金属伪影校正算法，与低keV方向相反。D错误：去骨依靠物质分解或分割算法，不是虚拟单能量的功能。E错误：虚拟平扫由碘图扣除生成，与单能量重建是不同的后处理产品。", "tr": "低keV「提对比但增噪声」，高keV「降伪影但失对比」，方向相反，是能量CT最基础也最常考的一组权衡。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0111", "t": "单选题", "s": "某髋关节金属假体术后患者行CT检查，图像上假体周围出现明显条状低密度与高密度相间伪影。关于采用高keV虚拟单能量图像的作用与限度，下列说法正确的是", "o": {"A": "高keV图像可减轻射线硬化引起的暗带与条纹，但对金属造成的光子饥饿与探测器信号缺失所致的伪影改善有限，需联合专用金属伪影校正算法", "B": "高keV图像对束硬化与光子饥饿两类伪影的抑制效果相当，可单独用于金属伪影处理", "C": "高keV图像在减轻伪影的同时能进一步提高软组织与碘对比", "D": "高keV图像的噪声高于低keV图像", "E": "金属伪影只能通过增大管电流解决，与keV选择无关"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-011", "kp": "高keV与金属伪影校正", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】A正确。金属伪影的成因至少包括射线硬化（束硬化）、光子饥饿（透过金属后计数极低）、散射与运动等。高keV虚拟单能量图像模拟高能量下衰减差异缩小的情形，主要针对射线硬化成分有效；而光子饥饿造成的投影数据缺失属信息丢失，须靠投影插值类金属伪影校正算法（MAR）补充，二者联合效果最佳。【为什么错】B错误：高keV主要抑制束硬化成分，对光子饥饿造成的投影数据缺失作用有限，两类伪影的抑制效果并不相当，单靠高keV难以解决严重金属伪影。C错误：keV升高使碘的衰减优势下降，软组织与碘对比降低，这正是高keV的代价。D错误：一般而言高keV图像噪声较低，低keV图像噪声更高，选项描述相反。E错误：增大管电流可缓解光子饥饿但不能消除束硬化，且盲目加大剂量不符合防护原则；keV选择与MAR算法才是主要手段。", "tr": "MAR算法本身也可能引入新的伪影（如金属附近结构变形、细节丢失），临床应同时保留未校正与已校正两套图像对照阅读。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0112", "t": "单选题", "s": "关于能量CT在头颈CTA中的自动去骨（骨与碘分离）技术，下列说法正确的是", "o": {"A": "利用骨（钙）与碘在两种能量下衰减特性的差异做物质分解，无需平扫蒙片即可在单次增强采集中去除骨结构", "B": "其原理是把增强图像与平扫图像相减，因此必须先做一次平扫", "C": "去骨效果与颅底部位无关，各部位精度一致", "D": "该技术要求患者在两次扫描间保持绝对静止，否则会出现错层", "E": "去骨后图像不能用于最大密度投影与容积再现显示"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-012", "kp": "能量CT自动去骨技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】A正确。钙与碘的有效原子序数不同，在高低两种能谱下的衰减比值存在稳定差异，据此可在同一次增强采集的双能量数据中把骨（钙）与血管（碘）分离，无需平扫蒙片，因而免除了配准误差与额外的平扫剂量。【为什么错】B错误：这是传统减影CTA（两次扫描相减）的原理，与能量去骨是不同技术路线。C错误：颅底骨质致密、血管紧贴骨壁（如颈内动脉岩骨段、海绵窦段），此处去骨最易误删血管或残留骨片，精度明显低于颈部。D错误：能量去骨为单次采集，不存在两次扫描间的运动错层问题，这恰是其优势；「必须绝对静止」是减影CTA的限制。E错误：去骨后的容积数据完全可以用于最大密度投影、容积再现与曲面重组显示。", "tr": "减影CTA靠「两次扫描相减」，能量CTA靠「一次扫描物质分解」。两者的失败模式不同：前者怕体动错层，后者怕颅底血管与骨紧贴造成误分割。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0113", "t": "多选题", "s": "关于CT金属伪影校正（MAR）算法及扫描侧的伪影控制措施，下列说法正确的是", "o": {"A": "投影插值类MAR先分割出金属所在的投影道，用邻近投影数据插值替代后再重建，可显著减轻条纹伪影", "B": "MAR校正后可能出现金属邻近区域结构变形或细节丢失，应保留原始重建图像一并阅读", "C": "适当提高管电压（如从120kV提高到140kV）有助于减轻束硬化伪影", "D": "调整机架倾角或患者体位使金属尽量避开重要观察结构所在的扫描平面，是简单有效的物理措施", "E": "增大重建层厚可以消除金属伪影的根源"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-013", "kp": "金属伪影校正算法与扫描对策", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】A正确：投影域插值是经典MAR的核心思路，后续多与迭代重建结合。B正确：MAR以「合理估计」替代真实缺失数据，可能造成金属旁软组织形态失真，故双份图像对照是临床规范。C正确：提高管电压使平均光子能量升高，束硬化效应减弱，同时改善穿透力、缓解光子饥饿。D正确：改变投照几何使金属与关注结构不在同一投影路径上，是无成本、无剂量代价的有效手段（如口腔金属修复体行头部扫描时调整倾角）。【为什么错】E错误：增大层厚只是通过平均降低噪声与视觉上的条纹显著度，并不改变投影数据缺失这一根源，反而牺牲纵向分辨率与小病灶显示。", "tr": "伪影控制应「先物理、后算法」：优化投照几何与管电压属源头治理，MAR与高keV属事后补救，二者互补而非替代。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-0114", "t": "单选题", "s": "双能量CT用于痛风的尿酸盐结晶成像，其物质分解的基础是", "o": {"A": "单钠尿酸盐由低原子序数元素组成，其在高低两种能量下的CT值变化幅度小于含钙组织，据此可与骨、钙化区分并作伪彩标记", "B": "尿酸盐结晶具有顺磁性，在高能量下信号增强", "C": "尿酸盐能特异性摄取碘对比剂", "D": "尿酸盐的密度高于皮质骨", "E": "尿酸盐只能在增强扫描中显示"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-014", "kp": "双能量痛风成像原理", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】A正确。单钠尿酸盐主要由碳、氮、氧、氢等低原子序数元素构成，有效原子序数低（约7~8），其衰减对光子能量变化不敏感，双能量比接近1；而钙化与骨的有效原子序数高（钙Z=20），双能量比明显大于1。软件据此把关节周围的尿酸盐沉积分离出来并以伪彩（常为绿色）叠加显示，用于痛风的无创诊断与疗效随访。【为什么错】B错误：顺磁性是磁共振概念，与X线衰减无关，属跨模态混淆。C错误：尿酸盐不摄取碘对比剂，痛风双能量成像为平扫检查。D错误：尿酸盐结石与结晶的密度远低于皮质骨。E错误：痛风双能量成像在平扫下完成，增强反而会引入碘干扰物质分解。", "tr": "「双能量比」是判读关键：尿酸盐约等于1（能量依赖性弱），钙约1.4以上（能量依赖性强）。此外甲床、皮肤褶皱、运动与射线硬化可产生伪阳性绿色标记，需结合部位与形态判读。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0115", "t": "多选题", "s": "关于双能量CT对泌尿系结石成分的定量分析，下列说法正确的是", "o": {"A": "尿酸盐结石的双能量比接近1，含钙结石（草酸钙、磷酸钙）的双能量比明显大于1，据此可实现二者分离", "B": "结石成分判定对治疗决策有直接影响：尿酸盐结石可通过碱化尿液药物溶石，含钙结石多需体外冲击波碎石或手术", "C": "结石体积过小（如直径小于3mm）时，部分容积效应与噪声会明显降低成分判定的可靠性", "D": "分析须在平扫条件下进行，含碘对比剂会干扰物质分解结果", "E": "双能量CT对草酸钙一水与二水、磷酸钙、胱氨酸等结石亚型的细分，与实验室成分分析具有同等可靠性"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-015", "kp": "结石成分的双能量定量分析", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】A正确：尿酸盐有效原子序数低、能量依赖性弱，与含钙结石在双能量比上差异显著，是双能量最可靠的临床应用之一。B正确：这正是成分分析的临床价值所在，直接决定溶石与碎石路径的选择。C正确：微小结石受部分容积效应与量子噪声影响，物质分解的置信度下降，报告时应说明。D正确：碘的存在会破坏两物质／三物质分解假设，必须在平扫数据上分析。【为什么错】E错误：双能量对「尿酸盐与非尿酸盐」的二分最可靠，对含钙结石内部亚型（草酸钙一水与二水、磷酸钙）以及胱氨酸结石的细分能力有限，与体外红外光谱等实验室分析不能等同。", "tr": "双能量结石分析的可靠边界是「尿酸盐与非尿酸盐」。把它当作可替代实验室成分分析的精细分型工具，是超出技术能力的过度解读。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-0116", "t": "单选题", "s": "关于双能量CT虚拟平扫（VNC）图像的生成原理与临床价值，下列说法正确的是", "o": {"A": "通过物质分解从增强数据中扣除碘成分，得到近似平扫的图像，可在部分方案中省略真实平扫从而降低总辐射剂量", "B": "VNC是把增强图像的窗宽窗位调整为平扫显示的结果", "C": "VNC图像与真实平扫图像的CT值一致，可直接用于肾上腺腺瘤10HU阈值的判读", "D": "VNC只能在平扫数据上生成", "E": "VNC图像的噪声低于真实平扫图像，且对细小钙化的显示更清晰"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-016", "kp": "虚拟平扫的原理与价值", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】A正确。VNC基于三物质分解，把增强图像中的碘信号识别并扣除，重建出接近平扫的图像。在多期扫描方案中用VNC替代真实平扫，可减少一个扫描期相，降低总剂量约三分之一，对肾上腺、肾脏、肝脏多期检查意义明显。【为什么错】B错误：窗技术只改变灰度显示，不改变体素CT值，无法去除碘的实际贡献。C错误：VNC与真实平扫CT值存在系统偏差（一般在10HU左右，部位与算法不同而异），对依赖CT值阈值的判读（如肾上腺腺瘤10HU界值、结石、钙化检出）须谨慎，不能无条件替代。D错误：VNC必须从含碘的增强数据生成，平扫数据无碘可扣。E错误：VNC经物质分解运算后噪声特性改变，通常并不优于真实平扫，且可能丢失细小钙化。", "tr": "VNC最重要的两个局限：一是CT值偏差影响阈值判读，二是可能把细小钙化与钙化斑块一并「扣掉」而漏检。涉及钙化评分、结石检出时仍应做真实平扫。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0117", "t": "案例分析题", "s": "患者男性，58岁，吸烟30年，因体检超声发现右侧肾上腺占位就诊，占位最大径2.4cm，边界清楚，实验室内分泌功能检查未见异常，临床需鉴别无功能腺瘤与转移瘤。临床申请肾上腺CT平扫加增强及延迟扫描。技师考虑到该患者近期已多次接受CT检查，拟采用双能量增强扫描并以虚拟平扫替代真实平扫，从而减少一次曝光。关于这一方案的评估，下列判断中错误的是", "o": {"A": "肾上腺腺瘤的经典判读依据之一是真实平扫CT值≤10HU，该阈值建立在常规平扫数据基础上", "B": "虚拟平扫与真实平扫之间存在系统性CT值偏差，直接套用10HU阈值可能造成误判", "C": "若采用虚拟平扫替代方案，应了解本机虚拟平扫与真实平扫的偏差范围，并结合增强廓清率等指标综合判断", "D": "增强廓清率的计算需要平扫、增强及延迟期数据，虚拟平扫的偏差同样会传导到廓清率结果中", "E": "由于虚拟平扫由增强数据生成，其CT值必然低于真实平扫，可直接减去固定值后套用原阈值"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-017", "kp": "虚拟平扫在肾上腺检查中的应用与限度", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】E错误，为应选项。虚拟平扫与真实平扫的CT值偏差方向与幅度并不固定，受算法版本、器官、体型、对比剂浓度与扫描时相影响，多数研究报告虚拟平扫略高于真实平扫，也有偏低的情形，不能用「必然偏低、减去固定值」的方式简单校正。【为什么错】A正确：≤10HU的腺瘤诊断阈值确立于常规平扫。B正确：正因存在系统偏差，直接套用阈值可能导致富脂腺瘤被误判为乏脂病变或反之。C正确：临床上应先在本机做验证、了解偏差区间，并联合绝对廓清率与相对廓清率判断。D正确：廓清率公式中包含平扫值，虚拟平扫的误差会传导至最终百分比。", "tr": "凡涉及「用虚拟平扫替代真实平扫」的题目，答题核心是「偏差存在且不固定，阈值不能直接照搬」。肾上腺、肝脏脂肪定量、钙化评分是三个必须谨慎的场景。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0118", "t": "多选题", "s": "关于能量CT碘图（碘密度图）及碘定量的临床应用，下列说法正确的是", "o": {"A": "碘图以碘的浓度（mg/mL）表达组织内对比剂分布，可用于评价肿瘤强化程度与消融、靶向治疗后的疗效", "B": "肺动脉CTA同步生成的肺碘分布图可显示肺栓塞所致的楔形灌注缺损，提高亚段栓塞与血流动力学评价的把握", "C": "在心肌灌注评价中，碘图可显示心肌灌注缺损区，提供比常规图像更客观的定量指标", "D": "碘定量结果受扫描时相、注射方案、患者循环状态与感兴趣区放置的影响，纵向随访须保持方案一致", "E": "碘图上碘浓度为零即可断定病灶为坏死组织，无需其他征象支持"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-018", "kp": "碘图与碘定量的临床应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (6)碘图", "ex": "【为什么对】A正确：碘图把强化「密度差」转换为可量化的碘浓度，避免了不同体型、注射方案下HU值的不可比性，对疗效评价（如消融后残留、抗血管生成治疗反应）尤为有用。B正确：肺碘分布图是双能量肺动脉CTA的常规附加产品，有助于发现远端栓塞与评估灌注受损范围。C正确：碘图在心肌灌注中可显示缺损区并给出定量指标，与常规图像相比减少了主观性。D正确：碘定量的可重复性依赖方案一致性，纵向随访必须固定注射流率、总量、延迟时间与重建参数。【为什么错】E错误：碘浓度极低可见于坏死，也可见于囊变、黏液成分、乏血供肿瘤、扫描时相过早或注射失败，须结合形态学与临床综合判断。", "tr": "碘定量是「相对可比」而非「绝对真值」。跨设备、跨方案的碘浓度数值不宜直接比较，随访务必同机同方案。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-0119", "t": "单选题", "s": "关于CT低剂量技术中自动管电流调制（ATCM）的工作原理，下列说法正确的是", "o": {"A": "根据定位像或实时反馈的患者衰减信息，在x-y平面内（角度方向）与z轴方向自动调整管电流，以在设定的图像质量水平下使用尽可能低的剂量", "B": "在整个扫描过程中始终保持管电流恒定", "C": "通过降低管电压来减少剂量，与管电流无关", "D": "仅在儿童扫描中可以启用", "E": "启用后无需再设定噪声指数或参考毫安秒等图像质量指标"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-019", "kp": "自动管电流调制与低剂量技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】A正确。ATCM综合角度调制（补偿肩部、骨盆在侧位方向衰减更大的各向异性）与纵向调制（按部位厚度沿z轴变化），在维持既定图像质量（噪声指数或参考毫安秒）的前提下动态给出最小必要管电流，是CT剂量优化的基础功能。【为什么错】B错误：恒定管电流正是ATCM要取代的固定输出模式。C错误：降低管电压属自动管电压选择（如CARE kV类）功能，与ATCM是不同但可协同的技术。D错误：ATCM适用于各年龄段，儿童更强调结合低kV与体型化协议。E错误：ATCM必须由使用者设定目标图像质量参数，参数设定不当会导致剂量过高或图像不可诊断，这恰是质量控制的关键环节。", "tr": "ATCM不是「一键降剂量」。噪声指数设置越低、参考毫安秒越高，系统给出的实际剂量越大；协议维护时必须按部位与临床任务逐一整定。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0120", "t": "单选题", "s": "关于CT导向介入技术的应用范围，下列说法错误的是", "o": {"A": "CT导向可用于肺、纵隔、肝、肾、胰腺、腹膜后及骨骼病变的穿刺活检", "B": "CT导向可用于脓肿、积液的穿刺引流与囊肿硬化治疗", "C": "CT导向可用于肿瘤的射频、微波消融与放射性粒子植入", "D": "CT导向可用于神经阻滞与椎体成形术等疼痛介入治疗", "E": "CT导向的空间分辨率与软组织对比不足，因此不适合用于肺部小结节的定位穿刺"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-020", "kp": "CT介入技术的应用范围", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (1)应用范围", "ex": "【为什么对】E错误，为应选项。CT具有优良的密度分辨率与断层定位能力，对含气肺组织与结节之间的天然高对比尤为敏感，肺结节穿刺活检与术前定位（如带钩钢丝、染料定位）正是CT导向最具优势的适应证之一。【为什么错】A、B、C、D均为CT导向介入的公认适应证：A涵盖胸腹部与骨骼的诊断性活检；B为常见的治疗性引流与硬化；C为肿瘤的局部消融与近距离治疗；D为疼痛与脊柱介入。CT可清晰显示进针路径上的血管、肠管、胸膜、神经根等结构，是这些操作的主要引导方式之一。", "tr": "各引导方式的分工：超声实时、无辐射，适合浅表与肝脏；CT断层定位精确，适合肺、骨、深部与含气结构遮挡区；MR软组织分辨率最高但设备与器械要求特殊。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0121", "t": "多选题", "s": "CT导向穿刺活检的检查前准备，下列做法正确的是", "o": {"A": "核查血常规、凝血功能，了解患者抗凝或抗血小板药物使用情况并按规范停药", "B": "复习既往影像资料，与临床共同确定靶点、拟定进针路径与体位，评估禁忌证", "C": "训练患者平静呼吸下的屏气配合，胸部穿刺尤其强调每次屏气幅度一致", "D": "备齐急救药品与设备（吸氧、监护、胸腔闭式引流包等），签署知情同意书", "E": "为缩短操作时间，术前不需要做定位扫描，可直接凭体表标志进针"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-021", "kp": "CT介入检查前准备", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (2)检查前准备", "ex": "【为什么对】A正确：凝血功能异常是穿刺的重要相对禁忌，抗栓药物需按临床规范停用并评估血栓风险。B正确：路径规划应避开叶间裂、大血管、肠管、胆囊与神经根，并结合体位可行性与患者耐受度。C正确：屏气幅度不一致会导致靶点位移，是胸部穿刺失败与并发症的重要原因，术前训练必不可少。D正确：气胸、出血、迷走反射等并发症需即时处置能力，知情同意为规范要求。【为什么错】E错误：穿刺前必须行定位扫描，贴放定位栅或标志线，测量进针点、角度与深度，凭体表经验盲穿违反操作规范并显著增加并发症风险。", "tr": "呼吸配合是胸部CT介入成败的关键变量：定位扫描、进针、复查扫描应始终在同一呼吸幅度（通常为平静呼气末）完成。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-0122", "t": "案例分析题", "s": "患者男性，65岁，吸烟史40年，慢性阻塞性肺疾病病史8年，肺功能中度受损，胸部CT发现右肺上叶后段直径2.0cm结节，边缘分叶伴胸膜牵拉，位于胸膜下约2cm，周围散在肺大疱。临床拟行CT导向经皮穿刺活检以明确病理。设备具备CT透视（实时透视）与常规间断扫描两种引导模式，可根据需要切换。作为配合本次操作的技师，下列判断中错误的是", "o": {"A": "应先做薄层定位扫描，选择避开叶间裂、大血管与肺大疱的最短安全路径，并尽量使针道垂直于胸膜进入", "B": "CT透视可实时观察针尖位置、缩短操作时间，但术者手部与患者受照剂量增加，应使用针持器并采用低毫安透视", "C": "该患者慢性阻塞性肺疾病、肺大疱多，气胸风险高，术后应即刻扫描全胸并按规范观察，必要时行胸腔闭式引流", "D": "穿刺路径经过肺组织越长、穿越胸膜次数越多，气胸与肺出血风险越高", "E": "为提高取材成功率，应尽量选择经过肺大疱的路径以避开血管"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-022", "kp": "CT导向肺穿刺活检的技术要点与并发症", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (3)穿刺活检扫描技术", "ex": "【为什么对】E错误，为应选项。穿刺路径必须避开肺大疱：穿破肺大疱极易造成难以愈合的气胸甚至张力性气胸，这在慢性阻塞性肺疾病患者中后果尤为严重。避开血管的正确做法是通过薄层与多平面重组重新规划路径，而非借道肺大疱。【为什么错】A正确：最短肺内路径、垂直穿越胸膜、避开叶间裂与大血管是降低气胸与出血风险的基本原则。B正确：CT透视提高实时性但显著增加术者手部剂量，须用针持器、准直、低毫安并避免手直接置于射野内。C正确：慢性阻塞性肺疾病患者气胸发生率明显升高，术后即刻及延迟复查、备好引流是标准流程。D正确：肺内针道长度与穿越胸膜次数是气胸与出血最公认的危险因素。", "tr": "肺穿刺三条铁律：不穿肺大疱、不多次穿越胸膜、不斜切叶间裂。术后即刻扫描与观察期不可省略，迟发气胸可在数小时后出现。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0123", "t": "案例分析题", "s": "患者男性，60岁，慢性乙型肝炎病史20年，增强CT发现肝右叶单发肝细胞癌，最大径3.0cm，肝功能Child-Pugh A级，血小板与凝血功能基本正常，因合并症不宜手术切除，拟在CT导向下行微波消融治疗。术前增强CT显示病灶邻近肝包膜，距结肠肝曲约1.2cm。作为参与该治疗的技师，负责影像技术保障与术中扫描配合，下列做法中错误的是", "o": {"A": "术前应做增强扫描明确病灶边界与邻近结构，规划进针角度与消融范围，力求覆盖病灶及周边约5mm安全边界", "B": "对邻近肠管的病灶可采用人工腹水或注气等隔离措施降低热损伤风险，并在扫描中确认隔离效果", "C": "消融过程中可间断扫描确认针尖位置与消融区变化，消融结束可行增强扫描初步评估有无残留强化", "D": "放射性粒子植入与消融同属CT导向的肿瘤局部治疗，前者依靠持续低剂量近距离照射，后者依靠热效应致组织凝固性坏死", "E": "因消融是热毁损治疗，术中无需关注针道出血与针道种植风险，也不需要针道消融"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-023", "kp": "CT导向肿瘤消融与粒子植入", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (4)疾病治疗检查技术", "ex": "【为什么对】E错误，为应选项。消融退针时常规行针道消融，目的正是止血与减少肿瘤沿针道种植转移；针道出血在肝包膜下病灶、凝血功能不佳者尤需警惕，术后应扫描观察有无腹腔出血。【为什么错】A正确：为降低局部复发，消融范围应超出肿瘤边缘约5mm形成安全边界。B正确：人工腹水、注气或注射葡萄糖溶液隔离是保护邻近肠管、膈肌、胆囊的常用手段，须在扫描中确认隔离层形成。C正确：术中间断扫描定位、术毕增强初评是CT导向消融的标准流程，完全评价疗效通常在术后1个月复查。D正确：粒子植入属近距离放射治疗，消融属热毁损，两者机制不同但同为CT导向的局部治疗手段。", "tr": "邻近空腔脏器、胆管与大血管是消融的高风险因素：大血管旁存在「热沉效应」易致消融不全，肠管旁则有穿孔风险，二者的应对策略不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-0124", "t": "单选题", "s": "关于CT导向介入操作的检查要点与质量控制，下列说法错误的是", "o": {"A": "宜采用薄层、小视野扫描以提高针尖显示精度，并限制扫描范围至操作必需的最小长度", "B": "在满足针尖与靶点辨识需要的前提下，可使用明显低于诊断扫描的管电流以降低累积剂量", "C": "使用CT透视时应采用间歇踩踏而非持续曝光，并借助针持器使术者手部离开射野", "D": "术中每次扫描均应保持与定位扫描一致的呼吸幅度与体位，并核对床位坐标", "E": "为保证图像质量，介入过程中每次确认针尖位置都应使用与诊断扫描相同的高剂量参数扫描全器官"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-024", "kp": "CT介入的检查要点与质量控制", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (5)检查要点与质量控制", "ex": "【为什么对】E错误，为应选项。介入过程中的确认扫描属「任务导向」影像，只需看清针尖与靶点的相对关系，应使用低剂量参数、限定在针尖附近的少数层面，而非全器官高剂量扫描；重复多次的高剂量确认扫描会使累积剂量迅速攀升，违背最优化原则。【为什么错】A正确：薄层小视野提高针尖定位精度，限制范围直接降低剂量。B正确：介入确认扫描对噪声的容忍度远高于诊断扫描，低毫安足以分辨金属针尖。C正确：间歇曝光与针持器是CT透视下降低术者手部剂量的关键措施。D正确：呼吸幅度、体位与床位坐标的一致性是保证靶点位置可重复的前提。", "tr": "介入影像的质量标准与诊断影像不同：前者以「够用即可」为原则。把诊断协议直接套用于术中反复确认扫描，是介入剂量失控的常见原因。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1001", "t": "单选题", "s": "CT球管“飞焦点（flying focal spot）”技术的主要作用是", "o": {"A": "在z轴方向交替改变焦点位置，提高采样密度与图像分辨率", "B": "提高球管寿命", "C": "降低噪声", "D": "减少扫描时间", "E": "增加对比剂用量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-101", "kp": "飞焦点技术", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】飞焦点技术使阳极焦点在z轴（及x轴）方向交替偏移，获得交错采样数据，等效提高采样密度，改善空间分辨率，故A正确。\n【为什么错】B：焦点偏移与寿命无直接增益。C：噪声降低靠重建算法与剂量。D：扫描时间由旋转速度决定。E：对比剂用量与焦点技术无关。", "tr": "飞焦点的本质是“用焦点位置变化换采样密度”，服务于分辨率提升。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1002", "t": "单选题", "s": "宽体（大排数）探测器CT的主要优点是", "o": {"A": "单次旋转覆盖范围大，利于心脏与器官动态成像", "B": "只能做头部扫描", "C": "空间分辨率低于窄体", "D": "辐射剂量必然增大", "E": "不能做螺旋扫描"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-102", "kp": "宽体探测器", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】宽体探测器（如320排、16cm覆盖）单次旋转即覆盖大范围脏器，可完成心脏、颅脑全脑灌注等快速扫描，故A正确。\n【为什么错】B：宽体探测器适用于全身各部位。C：其空间分辨率并不低于窄体。D：大覆盖可减少曝光次数，剂量未必增大。E：宽体探测器支持螺旋扫描。", "tr": "宽体探测器的价值是“覆盖与速度”，适合一站式及动态扫描。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1003", "t": "单选题", "s": "双源CT（DSCT）的设备特征是", "o": {"A": "同一机架内安装两套球管-探测器系统", "B": "单球管双焦点", "C": "两个独立机架", "D": "双层探测器单球管", "E": "电子束扫描"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-103", "kp": "双源CT", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】双源CT在同一机架内以约90°夹角安装两套X线球管与探测器系统，可同时采集或双能量成像，故A正确。\n【为什么错】B：双焦点是单球管技术。C：双源不是两台独立机架。D：双层探测器是另一类能谱实现。E：电子束扫描是电子束CT方式，均与双源定义不符。", "tr": "双源=双球管双探测器；双能实现还有单源快kV切换、双层探测器等。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1004", "t": "单选题", "s": "目前临床能谱CT的实现方式不包括", "o": {"A": "双层探测器双能量采集", "B": "单源快速管电压（kV）切换", "C": "双源双球管不同kV同时曝光", "D": "光子计数探测器能谱分辨", "E": "激光全息成像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-104", "kp": "能谱CT实现方式", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】双层探测器、单源快kV切换、双源不同kV及光子计数探测器均为能谱CT的真实实现方式，而激光全息成像与能谱CT无关，不是能谱CT的实现方式，故E正确。\n【为什么错】A：双层探测器通过一次曝光分高低能层采集，是能谱CT实现方式。B：单源快速kV切换是能谱CT实现方式。C：双源双球管不同kV同时曝光是能谱CT实现方式。D：光子计数探测器具备能量分辨能力，是能谱CT实现方式，均不符合题意。", "tr": "记住能谱CT四种主流实现：双源、快kV切换、双层探测器、光子计数。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1005", "t": "单选题", "s": "低keV单能量图像在能谱CT中的主要临床价值是", "o": {"A": "提高碘对比剂的CT值对比，改善血管与病灶增强显示", "B": "减少软组织显示", "C": "增加金属伪影", "D": "降低图像噪声", "E": "减少扫描范围"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-105", "kp": "低keV单能量应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (2)单能谱CT临床应用", "ex": "【为什么对】碘在低keV时衰减显著增加，低keV单能量图像可明显提高含碘血管与病变的CT值对比，故A正确。\n【为什么错】B：低keV并非减少软组织显示。C：低keV反而加重线束硬化，金属伪影更明显。D：低keV图像噪声通常升高。E：扫描范围与keV选择无关。", "tr": "低keV“增碘对比但噪声高”，高keV“减伪影但对比低”，两者需权衡。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1006", "t": "单选题", "s": "高keV单能量图像的主要用途是", "o": {"A": "减少线束硬化和金属伪影", "B": "提高软组织分辨率", "C": "增加碘对比度", "D": "提高扫描速度", "E": "减少对比剂用量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-106", "kp": "高keV单能量应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (2)单能谱CT临床应用", "ex": "【为什么对】高keV光子能量高、穿透力强，能谱CT虚拟的高keV图像可显著减轻金属植入物附近的线束硬化与金属伪影，故A正确。\n【为什么错】B：高keV组织对比度下降。C：高keV碘对比反而降低。D：keV不影响机架转速。E：对比剂用量由检查方案决定，与keV无直接关系。", "tr": "去金属伪影=高keV+迭代/MARS；增碘对比=低keV，方向相反。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1007", "t": "单选题", "s": "能谱CT“碘图（Iodine Map）”显示的内容是", "o": {"A": "碘对比剂在组织中的分布及浓度信息", "B": "骨密度分布", "C": "肺纹理分布", "D": "皮肤厚度", "E": "脂肪含量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-107", "kp": "碘图", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (6)碘图", "ex": "【为什么对】碘图通过双能量物质分离提取碘成分，以彩色/伪彩图显示碘的空间分布与浓度，用于血供与疗效评估，故A正确。\n【为什么错】B：骨密度由钙定量评估。C：肺纹理属解剖显示。D：皮肤厚度非能谱碘成像对象。E：脂肪含量用脂肪定量（PDFF等），均非碘图内容。", "tr": "碘图专指“碘分布”，与钙图、尿酸图等其他基物质图区分。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1008", "t": "单选题", "s": "虚拟平扫（VNC）图像是通过什么方式获得的", "o": {"A": "从增强双能数据中去除碘成分，模拟平扫图像", "B": "直接扫描后剪裁", "C": "增强后二次重扫", "D": "图像锐化处理", "E": "缩小扫描范围"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-108", "kp": "虚拟平扫VNC", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】双能量数据经物质分解可将碘从混合衰减中分离出去，重建出不含碘的虚拟平扫图像，故A正确。\n【为什么错】B：剪裁不改变密度信息。C：二次重扫是真实平扫，增加剂量。D：锐化是后处理增强。E：范围缩小与去碘无关。", "tr": "VNC的“虚拟”在于软件去碘，可免去部分真实平扫，降低剂量。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1009", "t": "单选题", "s": "虚拟平扫（VNC）的主要临床价值是", "o": {"A": "减少额外真实平扫扫描，降低辐射剂量", "B": "提高图像空间分辨率", "C": "缩短球管寿命", "D": "增加对比剂用量", "E": "替代病理检查"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-109", "kp": "VNC临床应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】VNC可代替部分真实平扫用于钙化评估、结石成分判断等，减少一次扫描即降低辐射剂量，故A正确。\n【为什么错】B：分辨率由探测器决定。C：与球管寿命无关。D：对比剂用量由增强方案决定。E：VNC提供密度信息，无病理诊断能力。", "tr": "VNC的价值是“剂量优化”，但钙化定量等仍需与真实平扫对比验证。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1010", "t": "单选题", "s": "双能量CT“物质定量分析”的基本原理是", "o": {"A": "将组织衰减分解为水和碘、钙等基物质的组合", "B": "根据图像颜色定量", "C": "根据扫描层数定量", "D": "根据患者身高体重定量", "E": "根据扫描时间定量"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-110", "kp": "物质定量分析原理", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】不同物质在高低两种能量下的衰减不同，双能数据可求解出各基物质（如水、碘、钙、尿酸等）的比例与浓度，故A正确。\n【为什么错】B：颜色为显示方式，非定量依据。C：扫描层数反映覆盖范围。D：患者身高体重与物质分解无关。E：扫描时间与定量分析无关。", "tr": "物质定量基于“双能衰减差异+基物质分解”，是能谱CT的核心算法。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1011", "t": "单选题", "s": "利用双能量CT诊断痛风的主要依据是", "o": {"A": "尿酸钠结晶的双能量特征被识别并以彩色标记", "B": "关节间隙增宽", "C": "软骨钙化", "D": "骨密度升高", "E": "脂肪沉积"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-111", "kp": "双能量痛风成像", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】双能量CT可区分尿酸钠（MSU）与钙盐，软件以特定颜色标记尿酸盐结晶，直观显示痛风石与沉积，故A正确。\n【为什么错】B：痛风不表现为关节间隙增宽。C：软骨钙化是焦磷酸盐沉积特征。D：痛风与骨密度升高无关。E：脂肪沉积非痛风诊断依据。", "tr": "双能量痛风成像的关键是“区分尿酸盐与钙”，颜色标记为诊断工具。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1012", "t": "单选题", "s": "CT金属伪影去除（MAR）技术降低伪影的途径是", "o": {"A": "结合高keV单能量图像与迭代/专用重建算法抑制线束硬化", "B": "提高扫描层厚", "C": "减小矩阵", "D": "降低管电流", "E": "延长扫描时间"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-112", "kp": "金属伪影去除", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】金属伪影源于线束硬化与光子饥饿，高keV单能量图像减少硬化，迭代或专用MAR算法对投影数据修正，二者结合可显著抑制金属伪影，故A正确。\n【为什么错】B：加大层厚降低分辨率，不能去除金属伪影。C：减小矩阵降低分辨率。D：降低管电流反而加重噪声与光子饥饿。E：延长扫描时间不解决硬化伪影。", "tr": "去金属伪影三件套：高keV、MAR迭代算法、适当提高剂量减少光子饥饿。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1013", "t": "单选题", "s": "CT迭代重建（IR）技术最主要的临床价值是", "o": {"A": "在保证图像质量的前提下降低辐射剂量", "B": "提高扫描速度", "C": "增加对比剂用量", "D": "增大探测器排数", "E": "缩短图像传输时间"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-113", "kp": "迭代重建", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (7)高级重建", "ex": "【为什么对】迭代重建通过数学建模迭代优化，在保持甚至改善图像质量的同时可有效降低噪声，从而支持低剂量扫描，故A正确。\n【为什么错】B：扫描速度由机架与探测器决定。C：迭代重建不增加对比剂。D：探测器排数是硬件参数。E：传输时间与重建算法无关。", "tr": "迭代重建=降噪→低剂量，是CT低剂量技术的核心支撑。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1014", "t": "单选题", "s": "自动管电流调制（ATCM）降低辐射剂量的原理是", "o": {"A": "根据患者体型与衰减实时调节管电流", "B": "固定最大管电流", "C": "提高管电压", "D": "缩短重建矩阵", "E": "增加扫描层数"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-114", "kp": "自动管电流调制", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】ATCM根据定位像测得的体型及扫描中实时衰减信息，在保证图像噪声目标的前提下自动增减管电流，避免不必要的剂量，故A正确。\n【为什么错】B：固定最大电流剂量浪费。C：提高管电压增加剂量与硬化。D：减小矩阵损害分辨率。E：增加层数与剂量无关或增加剂量。", "tr": "ATCM是“按需供量”的剂量优化技术，与固定参数扫描不同。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1015", "t": "单选题", "s": "CT引导下经皮穿刺活检时，确定皮肤进针点的常用定位方法是", "o": {"A": "栅栏定位器结合定位扫描确定体表穿刺点", "B": "凭经验目测", "C": "按患者主诉定位", "D": "按体表血管走行定位", "E": "随意进针后调整"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-115", "kp": "CT引导穿刺定位", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (3)穿刺活检扫描技术", "ex": "【为什么对】栅栏定位器置于体表后行定位扫描，根据栅栏刻度与病灶层面对应关系确定体表进针点与进针路径，故A正确。\n【为什么错】B：凭经验目测无法精确定位。C：按患者主诉定位不客观。D：按体表血管走行定位不准确。E：随意进针后调整增加损伤风险，均不可取。", "tr": "CT引导穿刺的定位依赖“栅栏+定位扫描”的坐标换算。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1016", "t": "单选题", "s": "深度学习重建（DLR）技术提高CT图像质量的方式是", "o": {"A": "利用神经网络学习低剂量图像与高质量图像的映射关系实现降噪", "B": "提高机架转速", "C": "增加造影剂浓度", "D": "扩大扫描视野", "E": "减少重建层数"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-116", "kp": "深度学习重建", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (7)高级重建", "ex": "【为什么对】DLR以海量数据训练神经网络，学习低剂量/噪声图像到高质量图像的映射，实现显著降噪并保留细节，故A正确。\n【为什么错】B：转速为机械性能。C：造影剂浓度与重建无关。D：视野是扫描参数。E：减少层数损害信息，均错误。", "tr": "DLR属于“重建环节的智能化降噪”，与硬件转速、造影方案无关。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1017", "t": "单选题", "s": "光子计数探测器CT的突出优势是", "o": {"A": "直接计数X线光子并分辨能量，剂量效率与能谱分辨率高", "B": "只能单能量成像", "C": "空间分辨率低于常规探测器", "D": "必须使用造影剂", "E": "扫描速度最慢"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-117", "kp": "光子计数探测器", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】光子计数探测器对每个X线光子进行计数并测量其能量，具有更高的剂量效率、固有能谱分辨与空间分辨能力，故A正确。\n【为什么错】B：光子计数天然支持多能量成像。C：其空间分辨率更高。D：造影与否与探测器类型无关。E：其扫描速度并不慢。", "tr": "光子计数CT是“计数+分能”的新一代探测器技术。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1018", "t": "单选题", "s": "肺癌低剂量CT筛查常用的剂量优化组合是", "o": {"A": "低kVp与低mAs结合迭代/深度学习重建", "B": "高kVp高mAs", "C": "大螺距增大扫描层厚", "D": "固定管电流不调制", "E": "取消定位像"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-118", "kp": "低剂量CT筛查", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】低kVp与低mAs直接减少输出剂量，迭代或深度学习重建补偿噪声，是低剂量肺癌筛查的标准组合，故A正确。\n【为什么错】B：高kV/mAs增加剂量。C：大螺距增大层厚降低分辨率。D：不调制浪费剂量。E：定位像用于范围规划不可取消。", "tr": "低剂量=“低参数扫描+智能重建”，二者缺一不可。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1019", "t": "多选题", "s": "CT球管的技术进展包括", "o": {"A": "飞焦点技术", "B": "大功率高散热阳极", "C": "液态金属轴承", "D": "双源双球管系统", "E": "双层探测器"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-119", "kp": "CT球管进展", "ch": "十六、CT技术的进展 → 1.CT设备 → (1)球管进展", "ex": "【为什么对】飞焦点、大功率高散热阳极、液态金属轴承、双源双球管均属CT球管技术进展，故A、B、C、D正确。\n【为什么错】E：双层探测器属探测器系统进展，不属于球管技术。", "tr": "“球管进展”与“探测器进展”分属不同考目，勿混淆。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1020", "t": "多选题", "s": "CT探测器系统的进展包括", "o": {"A": "宽体（大排数）探测器", "B": "双层探测器双能采集", "C": "光子计数探测器", "D": "闪烁体-光电二极管阵列", "E": "X线球管旋转阳极"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-120", "kp": "CT探测器进展", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】宽体、双层、光子计数及闪烁体-光电二极管结构均为探测器技术内容，故A、B、C、D正确。\n【为什么错】E：旋转阳极是X线球管的部件，不属于探测器。", "tr": "探测器进展聚焦“排数、层次、计数方式、材料”，球管部件不混入。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1021", "t": "多选题", "s": "能谱CT的临床应用包括", "o": {"A": "去骨显示血管（去骨CTA）", "B": "金属伪影去除", "C": "结石成分分析", "D": "痛风尿酸盐沉积识别", "E": "超声弹性测量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-121", "kp": "能谱CT应用范围", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】去骨CTA、金属伪影去除、结石成分分析、痛风识别均为能谱CT的成熟应用，故A、B、C、D正确。\n【为什么错】E：超声弹性测量属超声技术，与CT能谱无关。", "tr": "能谱CT的应用围绕“物质分离与定量”，超声技术不属于其范畴。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1022", "t": "多选题", "s": "CT低剂量技术包括", "o": {"A": "自动管电流调制（ATCM）", "B": "自动管电压选择", "C": "迭代与深度学习重建", "D": "优化扫描范围与滤过", "E": "恒定最大剂量扫描"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-122", "kp": "低剂量技术", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】ATCM、自动kV选择、智能重建、范围与滤过优化均为低剂量技术手段，故A、B、C、D正确。\n【为什么错】E：恒定最大剂量扫描与低剂量理念相悖，会增加不必要辐射。", "tr": "低剂量是“参数优化+重建补偿+流程控制”的系统工程。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1023", "t": "多选题", "s": "CT介入技术的临床应用包括", "o": {"A": "经皮穿刺活检", "B": "穿刺引流", "C": "肿瘤消融治疗", "D": "疼痛介入治疗", "E": "冠状动脉旁路移植"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-123", "kp": "CT介入应用范围", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (1)应用范围", "ex": "【为什么对】活检、引流、消融、疼痛介入均为CT引导介入的常见应用，故A、B、C、D正确。\n【为什么错】E：冠状动脉旁路移植属外科开胸手术，不属于CT介入技术。", "tr": "CT介入以“经皮微创+CT引导”为特征，外科手术不属其列。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1024", "t": "多选题", "s": "双能量CT可进行定量分析的物质包括", "o": {"A": "碘", "B": "钙", "C": "铁", "D": "脂肪", "E": "气体"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-124", "kp": "物质定量对象", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】双能量可定量碘、钙、铁、脂肪（含脂质成分）等物质，用于强化、骨密度、铁过载、脂肪肝等评估，故A、B、C、D正确。\n【为什么错】E：气体本身衰减极低，不属于双能量定量分析的常规对象。", "tr": "物质定量对象为“高衰减物质与代谢物”，空气（气体）不参与。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1025", "t": "多选题", "s": "关于双能量CT不同实现方式的比较，正确的说法是", "o": {"A": "双源CT可实现两套系统同时曝光", "B": "单源快kV切换对运动敏感度相对较低", "C": "双层探测器一次曝光同时获得高低能数据", "D": "光子计数探测器具有固有能谱分辨能力", "E": "所有方式成像速度完全相同"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-125", "kp": "双能量实现方式比较", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (1)应用范围", "ex": "【为什么对】双源同时曝光、快kV切换时间分辨率高、双层探测器一次曝光、光子计数固有分能，均为各方式的特点，故A、B、C、D正确。\n【为什么错】E：不同实现方式在扫描速度、能谱精度、剂量效率上存在差异，并非完全相同。", "tr": "双能量各实现方式在“时间同步性、能谱分离度、剂量”上各有取舍。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1026", "t": "多选题", "s": "CT引导穿刺活检的质量控制要点包括", "o": {"A": "精确定位进针点与穿刺路径", "B": "避开大血管、肺大疱等高危结构", "C": "穿刺后CT扫描观察有无气胸、出血等并发症", "D": "核对病理标本的获取与处理", "E": "进针过程无需任何影像确认"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-126", "kp": "穿刺活检质量控制", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (5)检查要点与质量控制", "ex": "【为什么对】精确定位、避开高危结构、术后复查并发症、标本规范处理均为穿刺质控要点，故A、B、C、D正确。\n【为什么错】E：进针全程需CT扫描确认针尖位置，绝不能在无影像确认下盲目进针。", "tr": "CT介入质控强调“全程影像引导+并发症监测”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1027", "t": "多选题", "s": "关于虚拟平扫（VNC）与真实平扫的比较，正确的说法是", "o": {"A": "VNC可减少一次真实扫描，降低辐射剂量", "B": "VNC不含碘成分", "C": "VNC对钙化显示存在一定差异，必要时需真实平扫对照", "D": "VNC图像由增强双能数据重建获得", "E": "VNC需要额外注射更多对比剂"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-127", "kp": "VNC与真实平扫", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】VNC去碘重建、免除真实平扫、降低剂量，但钙化等微小定量与真实平扫存在差异需对照，故A、B、C、D正确。\n【为什么错】E：VNC不额外增加对比剂，使用的是增强扫描本身的数据。", "tr": "VNC是“从增强数据中来”，剂量与对比剂均不额外增加。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1028", "t": "多选题", "s": "能谱/双能量CT常用的后处理分析内容包括", "o": {"A": "单能量图像", "B": "碘密度图", "C": "有效原子序数图", "D": "基物质分解图", "E": "患者心率曲线"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-128", "kp": "能谱后处理分析", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】单能量、碘图、有效原子序数、基物质分解均为能谱后处理分析项，故A、B、C、D正确。\n【为什么错】E：心率曲线属心电监护与心电门控范畴，不是能谱物质分析内容。", "tr": "能谱后处理围绕“能量与物质”，心率监测属生理信号。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U16-1029a", "t": "单选题", "s": "【病例】患者男性，60岁，胸部增强双能量CT检查，临床需评估右下肺结节的血供情况并观察结节内有无钙化，同时希望减少检查总辐射剂量。技师负责能量成像方案与后处理参数选择。 为直观评估肺结节的血供与强化程度，应优先调用的后处理图像是", "o": {"A": "碘图（碘密度图）", "B": "骨密度图", "C": "尿酸图", "D": "心电曲线", "E": "胃部重建图"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-129", "kp": "碘图应用", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (6)碘图", "ex": "【为什么对】碘图直接显示碘在病灶中的分布与浓度，反映结节血供与强化程度，是评估富血供病变的直观工具，故A正确。\n【为什么错】B：骨密度图用于钙定量。C：尿酸图用于痛风。D：心电曲线是心脏门控监测。E：胃部重建图与肺结节评估无关。", "tr": "“看血供”对应碘图，“看钙化”对应骨像/钙图，“看尿酸”对应痛风成像。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1029b", "t": "单选题", "s": "在不增加额外扫描的前提下评估结节内钙化并减少剂量，应采用的方案是", "o": {"A": "利用增强双能数据重建虚拟平扫（VNC）观察钙化", "B": "另行一次真实平扫", "C": "加大对比剂用量", "D": "缩小扫描范围", "E": "降低重建层数"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-130", "kp": "VNC评估钙化", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】VNC从增强数据中去除碘，可近似平扫状态观察钙化，避免真实平扫的额外辐射，故A正确。\n【为什么错】B：真实平扫增加一次扫描剂量，与“不增加额外扫描”矛盾。C：加大对比剂干扰钙化观察。D：缩小范围无法完整评估。E：减少重建层数损害信息，均错误。", "tr": "VNC的核心价值正是“用软件替平扫，省一次辐射”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1030a", "t": "单选题", "s": "【病例】患者女性，68岁，左侧人工髋关节置换术后，拟行骨盆CT检查。因金属假体影响，常规CT图像出现明显放射状金属伪影，遮挡髋臼周围结构。临床希望尽量消除伪影以观察假体周围骨质。 针对金属伪影，技师应优先采用的能谱处理方案是", "o": {"A": "重建高keV单能量图像并启用金属伪影去除（MAR）迭代算法", "B": "降低管电压扫描", "C": "增大重建层厚", "D": "减少扫描范围", "E": "关闭迭代重建"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-131", "kp": "去金属伪影方案", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】高keV减少线束硬化，MAR迭代算法专门校正金属投影数据，两者结合是去金属伪影的标准方案，故A正确。\n【为什么错】B：低kV加重硬化伪影。C：大层厚降低分辨率且不除伪影。D：缩小范围不能消除伪影。E：关闭迭代失去校正手段。", "tr": "去金属伪影=高keV+MAR+保持适当剂量，低kV方向相反。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1030b", "t": "单选题", "s": "金属伪影产生的根本原因是", "o": {"A": "金属对X线的线束硬化与光子饥饿效应", "B": "探测器排数不足", "C": "球管旋转过快", "D": "图像传输丢包", "E": "患者姓名过长"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-132", "kp": "金属伪影机制", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】金属高原子序数使X线束硬化严重、探测器侧光子被大量吸收产生光子饥饿，重建时形成放射状伪影，故A正确。\n【为什么错】B：探测器排数影响覆盖与速度，不直接产生金属伪影。C：旋转速度影响时间分辨。D：传输丢包造成数据缺失故障。E：姓名与成像无关。", "tr": "金属伪影的物理本质是“硬化+光子饥饿”，MAR针对此设计。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1031a", "t": "单选题", "s": "【病例】患者男性，52岁，CT发现右肺上叶后段一枚1.5cm实性结节，性质待定，临床拟行CT引导下经皮肺穿刺活检。技师负责穿刺前的定位扫描与进针路径规划。 确定体表进针点前，最应采用的定位扫描方式是", "o": {"A": "体表放置栅栏定位器后行定位扫描，结合病灶层面确定进针点", "B": "凭手感直接进针", "C": "根据X线胸片位置进针", "D": "根据体表痣的位置进针", "E": "随机选取进针点"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-133", "kp": "穿刺定位扫描", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (3)穿刺活检扫描技术", "ex": "【为什么对】栅栏定位器随体表放置，定位扫描后栅栏刻度与病灶层面一一对应，可精确换算体表进针点与进针路径，故A正确。\n【为什么错】B：凭手感直接进针无法保证路径。C：根据X线胸片位置进针误差大。D：根据体表痣的位置进针无解剖依据。E：随机选取进针点风险高，均不符合CT引导定位要求。", "tr": "栅栏定位+定位扫描是CT引导穿刺的坐标基础。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT介入技术", "页": 391}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1031b", "t": "单选题", "s": "穿刺完成后，为及时发现气胸等并发症，正确的做法是", "o": {"A": "穿刺点层面再行CT扫描观察胸腔", "B": "立即让患者出院", "C": "仅电话随访", "D": "不做任何检查", "E": "常规行消化道造影"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-134", "kp": "穿刺术后并发症监测", "ch": "十六、CT技术的进展 → 3.CT介入技术 → (5)检查要点与质量控制", "ex": "【为什么对】肺穿刺后复查CT可迅速发现气胸、出血等并发症并评估程度，是标准的术后处理流程，故A正确。\n【为什么错】B：立即出院延误并发症处理。C：电话随访无法客观判断。D：不检查存在安全隐患。E：消化道造影与肺穿刺并发症无关。", "tr": "肺穿刺质控闭环=术前定位→术中引导→术后CT复查。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1032", "t": "案例分析题", "s": "某医院开展肺癌低剂量CT筛查项目，需为长期吸烟的中老年人群设计扫描方案，要求在满足肺结节检出能力的前提下最大限度降低辐射剂量，并兼顾图像噪声与扫描效率。技师确定参数组合时，筛查方案应在满足肺结节显示前提下采用低kVp、自动管电流调制与迭代或深度学习重建相结合的优化组合。需兼顾结节检出、图像噪声与扫描效率的综合要求。下列方案中最合理的是", "o": {"A": "低kVp结合ATCM与迭代重建，固定扫描范围仅覆盖胸部", "B": "采用最高kVp与最大管电流", "C": "不做定位像直接扫描", "D": "用头部参数扫描胸部", "E": "取消自动曝光控制"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-135", "kp": "低剂量筛查方案设计", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (8)低剂量技术", "ex": "【为什么对】低kVp降低剂量，ATCM按体型调制电流，迭代/深度学习重建补偿噪声，范围限定胸部避免无效照射，兼顾检出与剂量，故A正确。\n【为什么错】B：最大参数剂量高。C：定位像用于规划扫描范围不可省。D：头部参数不适于胸部。E：取消自动曝光控制损失剂量优化，均错误。", "tr": "低剂量筛查是“参数+调制+重建+范围”四位一体的优化。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1033", "t": "案例分析题", "s": "患者男性，45岁，反复足趾关节红肿热痛发作3年，血尿酸升高，临床疑诊痛风。为证实关节及周围有无尿酸盐结晶沉积并评估负荷，申请双能量CT检查。技师在扫描与后处理中的双能量CT通过物质分解区分尿酸盐与钙盐，痛风专用后处理以特定颜色标记尿酸盐结晶。扫描范围应包含足、踝及膝等易受累部位，避免遗漏沉积。正确做法是", "o": {"A": "双能量扫描后使用痛风专用算法识别并以特定颜色标记尿酸盐结晶", "B": "常规单能量平扫即可识别尿酸盐", "C": "使用造影剂增强后观察尿酸", "D": "扫描后直接目测判断", "E": "用超声代替CT"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-136", "kp": "痛风双能量成像", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (4)物质定量分析", "ex": "【为什么对】双能量数据经物质分解可区分尿酸盐与钙盐，痛风专用算法以绿色等特定颜色标记尿酸盐沉积，实现可视化诊断，故A正确。\n【为什么错】B：常规单能量无法区分尿酸与钙。C：尿酸识别无需造影剂。D：目测不能定量识别成分。E：超声是辅助方法，本题问双能量CT的正确用法。", "tr": "痛风双能量识别的关键是“尿酸-钙分离+颜色标记”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1034", "t": "案例分析题", "s": "患者男性，50岁，因脑血管病变行头颈部CTA，常规重建图像中颅底骨骼与颅内血管重叠，影响前交通动脉瘤的观察与测量。设备具备能谱CT功能，可通过后处理去除骨组织。能谱后处理可基于双能数据去除骨组织，仅保留含碘血管，提高动脉瘤等血管病变的显示。去骨效果受骨与血管衰减差异影响，需验证后处理图像质量。技师应采用的后处理方案是", "o": {"A": "利用双能量去骨技术生成去骨CTA图像显示颅内血管", "B": "加大对比剂浓度", "C": "缩小扫描矩阵", "D": "仅保留骨像", "E": "降低keV至最低"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-137", "kp": "去骨CTA", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (3)去骨与金属伪影", "ex": "【为什么对】双能量物质分解可将骨组织分离去除，仅保留含碘血管，生成去骨CTA，清晰显示颅内血管，故A正确。\n【为什么错】B：浓度增加不解决骨重叠。C：缩小矩阵降低分辨率。D：骨像正好相反。E：极低keV噪声大且骨保留，均错误。", "tr": "去骨CTA是能谱CT的典型应用：骨像/血管像分离，血管像用于观察。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1035", "t": "案例分析题", "s": "某医院计划将腹部常规“平扫+增强”检查改为“单次增强双能量扫描+虚拟平扫”，以降低患者辐射剂量并简化流程。技师与医师评估该方案可行性时，需判断VNC能否替代真实平扫。VNC由增强双能数据重建获得，与真实平扫在钙化定量、微小出血等显示上存在差异，需把握适应证。评估应以诊断需求为导向，权衡剂量收益与图像可靠性。应注意的要点是", "o": {"A": "VNC可部分替代真实平扫，但钙化、出血等评估仍建议与真实平扫对照", "B": "VNC完全等同真实平扫，可无条件替代", "C": "VNC会增加对比剂剂量", "D": "VNC不需要增强数据", "E": "VNC降低空间分辨率"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-138", "kp": "VNC替代平扫评估", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (5)虚拟平扫VNC", "ex": "【为什么对】VNC在多数场合可替代平扫减少剂量，但钙化精细定量、微小出血等与真实平扫存在差异，关键病例需真实平扫对照，故A正确。\n【为什么错】B：无条件下替代过于绝对。C：VNC不增加对比剂。D：VNC恰恰依赖增强双能数据。E：VNC空间分辨率与原始扫描一致，均错误。", "tr": "VNC是“近似平扫”，适应证内可靠，特殊密度判断需对照真实平扫。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1036", "t": "案例分析题", "s": "某医院引进光子计数CT，拟用于冠脉支架成像与高分辨力肺结节的精细评估。技师需理解新技术的成像特性，以正确设定扫描与后处理方案并解释其与传统CT的差异。关于光子计数CT的特点，与传统积分型探测器不同，光子计数探测器可直接计数并分辨单个光子能量，成像特性存在显著差异。设置扫描方案时应充分利用其剂量效率与能谱分辨优势。正确的是", "o": {"A": "对每个X线光子计数并测能量，具备更高空间分辨率与剂量效率", "B": "只能生成单一能量图像", "C": "无法进行能谱分析", "D": "辐射剂量必然高于常规CT", "E": "空间分辨率低于传统探测器"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-139", "kp": "光子计数CT特性", "ch": "十六、CT技术的进展 → 1.CT设备 → (2)探测器进展", "ex": "【为什么对】光子计数探测器直接计数并分辨光子能量，像素更小、无电子噪声累积，空间分辨率与剂量效率更高，故A正确。\n【为什么错】B：光子计数天然支持多能量/能谱成像。C：其能谱分析能力更强。D：其剂量效率高，同等质量下剂量可更低。E：其空间分辨率更高，均错误。", "tr": "光子计数CT是“计数+分能+高分辨”的换代技术，剂量与分辨率均优于传统。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": "CT能量检查技术", "页": 388}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U16-1037", "t": "案例分析题", "s": "患者女性，55岁，肝癌射频消融术后3个月，复查双能量增强CT以评估肿瘤灭活情况。技师拟通过能量后处理客观评价病灶内碘摄取变化，与术前基线比较，为疗效判断提供定量依据。下列后处理指标碘浓度能反映病灶血供灌注，消融灭活区碘摄取显著下降，可作为疗效评价的定量指标。定量分析结果需结合形态学图像综合判断消融是否彻底。最能反映消融区血供变化的是", "o": {"A": "消融区碘浓度（碘密度值）的变化", "B": "图像压缩率", "C": "扫描层数", "D": "患者体位编号", "E": "重建核名称"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十六", "un": "CT技术进展", "kpid": "UNIT-16-CT-140", "kp": "碘浓度疗效评估", "ch": "十六、CT技术的进展 → 2.CT能量检查技术 → (6)碘图", "ex": "【为什么对】碘浓度反映组织灌注与血供，消融灭活区血供消失、碘摄取显著降低，通过对比治疗前后碘密度值可客观评价疗效，故A正确。\n【为什么错】B：压缩率属存储参数。C：层数反映覆盖范围。D：体位编号是管理信息。E：重建核影响图像纹理，均不能定量反映血供变化。", "tr": "能谱疗效评估常用“碘浓度”作为血供的定量生物标志。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "CT技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0101", "t": "单选题", "s": "7.0T超高场MRI在体部与颅脑成像中出现「中心亮、外周暗」或局部信号缺失的介电效应（驻波效应）伪影，其产生的根本原因及主要对策是", "o": {"A": "射频波长在人体组织中缩短至与被检部位尺寸相当，形成驻波与波传播干涉，使B1场分布严重不均；主要对策为多通道并行发射（pTx）射频匀场、介电垫及自适应脉冲设计", "B": "主磁场B0均匀性变差所致，主要对策是提高主动匀场电流", "C": "梯度线圈涡流所致，主要对策是涡流补偿", "D": "接收线圈通道数不足所致，主要对策是提高并行采集加速因子", "E": "化学位移增大所致，主要对策是提高接收带宽"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-001", "kp": "超高场介电效应与射频匀场", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】A正确。7.0T质子共振频率约298MHz，射频在高介电常数的人体组织中波长缩短至十余厘米量级，与头颅、腹部的尺度可比拟，从而产生驻波与相消／相长干涉，表现为B1场严重不均、局部信号明显衰减或过亮。工程对策包括多通道并行发射的射频匀场（B1 shimming、Transmit SENSE）、介电衬垫改变局部电磁分布，以及绝热脉冲、复合脉冲等对B1不敏感的脉冲设计。【为什么错】B错误：B0不均匀主要表现为几何变形与脂肪抑制失败，与「中心亮外周暗」的射频干涉图样机制不同，且主动匀场校正的是B0而非B1。C错误：涡流表现为图像变形、条纹与相位误差，与驻波无关。D错误：接收通道数影响并行成像与信噪比，不能解决发射端的B1不均。E错误：加大带宽只减轻化学位移位移量与几何失真，不改变B1分布。", "tr": "务必区分B0不均匀（磁场匀场，影响脂肪抑制与几何精度）与B1不均匀（射频匀场，影响信号强度均一性）。7.0T的核心难题之一正是后者，另一个是SAR随场强平方升高。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0102", "t": "多选题", "s": "关于少液氦／无液氦密封磁体技术（如BlueSeal类设计），下列说法正确的是", "o": {"A": "采用微量液氦（约数升）在密封腔内循环冷却超导线圈，取代传统数百至上千升的液氦浸泡式设计", "B": "无需失超管道与常规补氦，降低了机房建设与后期维护成本，也减轻了氦资源紧张带来的压力", "C": "磁体重量减轻、安装条件放宽，有利于在改造机房或移动式平台部署", "D": "由于液氦总量极少，一旦失超时氦气释放量与相应的窒息风险显著低于传统磁体", "E": "无液氦磁体不再是超导磁体，工作时无需维持低温环境"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-002", "kp": "少液氦密封磁体技术", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】A正确：该类设计以数升级别的液氦在全密封腔体内循环，配合高效制冷机维持超导温度。B正确：因氦总量极小且腔体密封，通常无需失超管、无需定期补氦，机房建设与运行成本下降，也回应了全球氦资源紧缺。C正确：磁体总重下降、对机房结构与通风要求降低，便于旧机房改造与特殊场景部署。D正确：失超时可释放的氦气量极少，机房内氧浓度下降与窒息风险显著降低，这是其重要安全优势。【为什么错】E错误：它仍是超导磁体，线圈必须维持在临界温度以下，只是把「大量液氦浸泡」换成了「微量液氦密封循环＋制冷机」，绝非常温工作。", "tr": "「无液氦」是相对传统上千升而言的「极少量密封液氦」，不等于「不需要低温」。超导的前提永远是低温，失超防护流程仍需保留。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-0103", "t": "单选题", "s": "关于开放式MR与专用MR（如四肢专用、乳腺专用设备）的特点，下列说法正确的是", "o": {"A": "开放式MR多采用永磁或低场超导设计，场强较低、幽闭恐惧与介入操作友好，但信噪比与波谱、功能成像能力受限；专用MR以小孔径高填充因子线圈换取局部高分辨率", "B": "开放式MR的场强通常高于封闭超导MR", "C": "专用四肢MR因孔径小、可用线圈单元少，其空间分辨率低于全身MR", "D": "开放式MR不存在任何磁场安全管理要求", "E": "专用乳腺MR不需要专用线圈"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-003", "kp": "开放式与专用MR设备", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】A正确。开放式MR以C形或双柱结构提供大开口，多为永磁或低场超导（常见0.2~1.0T），优点是舒适、便于介入与肥胖、幽闭恐惧患者检查，缺点是信噪比低、化学位移小导致脂肪抑制与波谱受限、快速序列能力弱；四肢与乳腺等专用设备用贴近解剖的小孔径与高填充因子线圈，在局部获得优良信噪比与分辨率。【为什么错】B错误：开放式设备场强通常明显低于常规封闭超导系统。C错误：小孔径带来高填充因子与更贴近的线圈单元，局部信噪比反而提高，专用设备在其目标解剖上的空间分辨率常优于全身MR。D错误：任何MR设备都存在静磁场吸引、射频与梯度相关风险，安全分区、金属筛查与植入物核查同样必需。E错误：乳腺MR必须使用专用乳腺线圈以保证信噪比与双侧同时覆盖。", "tr": "低场并非一无是处：磁敏感伪影小、金属植入物成像与介入兼容性好、SAR低，是其相对优势；但脂肪抑制、波谱与高级功能成像明显受限。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0104", "t": "单选题", "s": "高性能梯度系统（高梯度场强与高切换率）对扩散加权成像（DWI）与扩散张量成像（DTI）最直接的意义是", "o": {"A": "在达到同一b值时可缩短扩散梯度的持续时间与间隔，从而缩短回波时间，提高信噪比并减轻T2衰减与几何变形", "B": "提高主磁场均匀性，改善脂肪抑制效果", "C": "增加射频发射功率，从而提高信噪比", "D": "延长回波时间以获得更高的扩散权重", "E": "使扩散加权成像不再需要平面回波（EPI）读出方式"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-004", "kp": "梯度性能对扩散成像的意义", "ch": "十七、MR技术的进展 → 1.MR设备 → (2)梯度系统", "ex": "【为什么对】A正确。b值近似与梯度幅度的平方、持续时间及间隔相关，梯度场强越高，达到同一b值所需的梯度施加时间越短，最短回波时间随之缩短。TE缩短带来更少的T2衰减、更高的信噪比；同时EPI读出串更短，可减小磁敏感相关的几何变形与模糊。这对高b值DWI、多方向DTI与高阶扩散模型（如DKI、NODDI）尤为关键。【为什么错】B错误：B0均匀性由磁体设计与匀场线圈决定，与梯度性能无直接关系。C错误：射频发射属射频链，梯度不参与。D错误：现代做法是在保证b值的同时尽可能缩短TE，延长TE只会损失信噪比。E错误：EPI仍是扩散成像的主流读出方式；非EPI的扩散读出（如TSE类）存在但并非因梯度性能提升而被免除。", "tr": "梯度切换率过高会诱发周围神经刺激，因此高性能梯度的实际可用性受生理限制约束，并非「越高越好」。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0105", "t": "多选题", "s": "关于梯度切换引起的周围神经刺激（PNS）及其限制，下列说法正确的是", "o": {"A": "其机制是快速变化的梯度磁场（dB/dt）在体内感应出电场与电流，达到阈值时刺激周围神经", "B": "刺激阈值与dB/dt及刺激持续时间相关，受检者体型、体位和肢体是否形成导电回路均有影响", "C": "常见表现为躯干、背部、鼻梁或髋部的麻刺、抽动感，扫描停止后症状随即消失", "D": "设备会依据PNS模型自动限制梯度切换率，这可能导致某些高性能序列的实际参数被降级", "E": "PNS属于射频能量沉积效应，可用SAR值直接评估与限制"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-005", "kp": "周围神经刺激与梯度安全限值", "ch": "十七、MR技术的进展 → 1.MR设备 → (2)梯度系统", "ex": "【为什么对】A正确：由法拉第电磁感应，dB/dt在组织中感生电场，超过神经兴奋阈值即产生刺激。B正确：阈值遵循类似强度—时间曲线的规律，且与人体在梯度场中的位置、体型及双手交叉、双腿接触形成的导电回路密切相关，故检查时应嘱患者勿交叉双手双腿。C正确：典型表现为局部麻刺或肌肉抽动，多见于dB/dt最大的部位，属可逆性生理效应，停止扫描即缓解。D正确：设备内置PNS模型作为硬限制，会自动降低切换率或延长梯度爬升时间，表现为最短TR/TE延长或回波间隔增大。【为什么错】E错误：PNS是梯度（低频磁场）效应，SAR是射频能量沉积（热效应）指标，两者是并列的两类安全限值，不能相互替代。", "tr": "MR的三大安全限值分属三条链路：静磁场B0对应铁磁投射与植入物；梯度对应PNS与噪声；射频对应SAR与热灼伤。混用指标是常见错误。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-0106", "t": "单选题", "s": "关于多通道并行发射（pTx）技术的作用，下列说法正确的是", "o": {"A": "通过多个独立发射通道分别控制射频脉冲的幅度与相位（乃至波形），对B1场进行匀场或空间选择性激发，从而改善高场下的信号均匀性并有助于控制局部SAR", "B": "通过多个接收通道提高并行采集的加速倍数", "C": "通过多个梯度通道提高梯度线性度", "D": "通过增大发射功率来克服B1不均匀", "E": "仅用于降低扫描噪声"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-006", "kp": "多通道并行发射与B1匀场", "ch": "十七、MR技术的进展 → 1.MR设备 → (3)射频系统", "ex": "【为什么对】A正确。pTx以两个或多个独立射频功率放大器与发射单元，分别调节各通道的幅度与相位（静态B1匀场），或设计通道间不同的时变波形（动态并行发射、Transmit SENSE、kT-points等），使激发场在感兴趣区内趋于均匀；同时可通过优化降低局部SAR峰值，是3.0T体部与7.0T成像的关键技术。临床3.0T常见的双源并行发射即属此类。【为什么错】B错误：接收端的并行成像（SENSE/GRAPPA）与发射端pTx分属两条链路。C错误：梯度线性度由梯度线圈设计与校正决定。D错误：单纯提高发射功率不改变场分布形态，只会同步抬高SAR。E错误：噪声主要来自梯度线圈的洛伦兹力振动，与射频发射无关。", "tr": "并行成像（接收，加速采集）与并行发射（发射，改善B1均匀性与SAR）名字相近但作用完全不同，是本考点最常见的混淆。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0107", "t": "多选题", "s": "关于现代MR接收线圈的进展，下列说法正确的是", "o": {"A": "密集阵列（多通道相控阵）线圈通过增加小单元数量提高局部信噪比，并为并行成像提供更多空间编码信息", "B": "通道数增加可支持更高的并行加速因子，从而缩短扫描时间", "C": "轻质柔性线圈可贴合体表、提高填充因子，改善患者舒适度与摆位效率", "D": "无线线圈通过取消线缆连接减少缠绕与摆位障碍，需解决供电、同步与数据传输问题", "E": "线圈通道数与信噪比、并行加速能力呈线性正相关，增加通道数不存在收益递减"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-007", "kp": "密集阵列与无线线圈", "ch": "十七、MR技术的进展 → 1.MR设备 → (3)射频系统", "ex": "【为什么对】A正确：小单元贴近解剖，各自接收范围小、噪声耦合体积小，合成后局部信噪比显著提高。B正确：线圈灵敏度分布的空间差异是并行成像的编码来源，通道数越多可支持的加速因子上限越高。C正确：柔性轻质线圈提高填充因子并减轻患者负担，是近年的重要工程方向。D正确：无线线圈简化摆位流程，其难点在于电源管理、时钟同步与高带宽无线数据链路。【为什么错】E错误：存在明显的收益递减——通道间存在耦合与噪声相关性，重叠区域的有效信息趋于饱和，通道数增加还带来重建负担、成本与线圈重量增加。加速因子过高时g因子噪声放大同样限制实际可用性。", "tr": "「通道越多越好」是典型绝对化陷阱。线圈性能取决于单元设计、覆盖匹配与去耦水平，而非单纯的通道数字。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-0108", "t": "单选题", "s": "压缩感知（CS，飞利浦平台常与SENSE结合称Compressed SENSE）能够实现高倍加速，其必须同时满足的三个基本要素是", "o": {"A": "图像在某个变换域具有稀疏性、K空间采用非相干（随机／伪随机）欠采样、采用非线性迭代重建算法", "B": "高场强、多通道线圈、高梯度切换率", "C": "长TR、长TE、大翻转角", "D": "均匀规则欠采样、线性反傅里叶变换重建、高带宽", "E": "呼吸门控、心电门控、脂肪抑制"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-008", "kp": "压缩感知的三要素", "ch": "十七、MR技术的进展 → 1.MR设备 → (4)软件系统", "ex": "【为什么对】A正确。压缩感知理论要求：①信号可稀疏表达（MR图像在小波、全变分、时间频率等变换域内系数稀疏）；②采样方式与稀疏基不相干，随机／伪随机欠采样使混叠表现为类噪声弥散伪影而非相干重影；③使用施加稀疏约束的非线性迭代重建（如L1范数正则化）逐步剔除弥散伪影、恢复图像。三者缺一不可。【为什么错】B错误：这些是硬件条件，可提升整体性能但不是CS成立的数学前提。C错误：与序列对比度参数无关。D错误：规则均匀欠采样产生的是相干卷褶伪影，恰恰不满足非相干条件；线性重建也无法施加稀疏约束。E错误：门控与脂肪抑制属运动与脂肪信号管理，不构成CS要素。", "tr": "并行成像利用「线圈硬件冗余」，压缩感知利用「图像信号冗余」。CS的加速代价是图像纹理平滑化与细节对比度下降，加速因子须按部位与临床任务设定，不宜盲目取上限。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0109", "t": "多选题", "s": "关于MR深度学习重建（DLR）、超分辨率重建与磁共振指纹成像（MRF），下列客观描述正确的是", "o": {"A": "MR深度学习重建多用于从欠采样K空间或低信噪比图像中恢复高质量图像，可在保持图像质量的前提下进一步缩短采集时间", "B": "超分辨率重建通过学习低分辨率与高分辨率图像间的映射来提升表观分辨率，其结果并不等同于真实采集的高分辨率数据", "C": "深度学习重建的表现依赖训练数据分布，对少见病变、罕见解剖或未纳入训练的序列可能出现细节丢失或伪结构，需谨慎解读", "D": "磁共振指纹成像采用伪随机变化的翻转角与重复时间产生独特信号演化「指纹」，通过与字典匹配一次采集同时得到T1、T2、质子密度等多参数定量图", "E": "深度学习重建已在各类在用MR设备上普遍标配，压缩感知等传统加速方法正被其取代"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-009", "kp": "深度学习重建、超分辨率与MR指纹成像", "ch": "十七、MR技术的进展 → 1.MR设备 → (4)软件系统", "ex": "【为什么对】A正确：这是MR深度学习重建的主要用途，在与并行成像、压缩感知联合时可进一步压缩采集时间。B正确：超分辨率提升的是「表观」分辨率，真实的空间频率信息若未被采集则无法凭空获得，评价时应关注小结构的保真度。C正确：泛化能力受限是数据驱动方法的共性局限，罕见病变可能被平滑或产生看似合理的虚假结构。D正确：MRF以伪随机的翻转角与重复时间序列驱动出组织特异的信号演化轨迹，与预先仿真的字典比对，一次采集获得多参数定量图，是定量MR的重要方向。【为什么错】E错误：深度学习重建目前并非所有设备的标配，许多在用机型仍以并行成像与压缩感知为主要加速手段；两类技术是互补关系，压缩感知远未被淘汰。", "tr": "评价重建算法不能只看主观锐利度与噪声水平，还要看小病灶检出与定量测值的可靠性。设备是否具备某项功能应以本机实际配置为准，不能想当然。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MRI介入技术进展", "页": 404}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-0110", "t": "单选题", "s": "关于静息态BOLD功能磁共振（rs-fMRI）与脑功能网络分析，下列说法正确的是", "o": {"A": "受检者在清醒安静、不执行特定任务的状态下采集连续的BOLD时间序列，依据不同脑区低频波动信号的时间相关性推断功能连接，可提取默认网络等静息态网络", "B": "静息态采集必须给予明确的任务刺激范式，否则无法获得BOLD信号", "C": "静息态分析依赖的是高频（大于1Hz）血流波动信号", "D": "静息态成像不受头动影响，无需运动校正", "E": "BOLD信号直接反映神经元的电活动本身"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-010", "kp": "静息态BOLD与脑功能网络", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】A正确。静息态fMRI在无任务状态下用梯度回波EPI连续采集数分钟BOLD序列，分析各脑区自发低频波动（约0.01~0.1Hz）之间的时间相关性，据此构建功能连接网络，默认模式网络、感觉运动网络、视觉网络等为常见结果，临床可用于术前功能区评估与神经精神疾病研究。【为什么错】B错误：无任务正是「静息态」的定义特征，与任务态fMRI相对。C错误：静息态关注的是0.01~0.1Hz的低频波动，高频成分多为心搏、呼吸等生理噪声，需要滤除。D错误：头动是静息态数据最主要的混杂因素，会造成虚假连接，必须做运动校正并对超阈值时间点做剔除或回归。E错误：BOLD基于脱氧血红蛋白的顺磁性变化，反映的是神经活动引起的血流与氧合改变，属间接的血流动力学指标，与电活动之间存在数秒级的血流动力学响应延迟。", "tr": "BOLD是「间接、延迟、相对」的信号：不直接测神经电活动、有数秒延迟、只反映相对变化而非绝对量。静息态更要警惕头动与生理噪声造成的假阳性连接。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0111", "t": "案例分析题", "s": "患者女性，72岁，反复短暂性脑缺血发作，颈动脉超声提示右侧颈内动脉重度狭窄。临床希望评估双侧大脑半球的脑血流灌注，但患者肾小球滤过率为36mL/(min·1.73m²)，不宜使用钆对比剂。所在科室为3.0T MR，配备多通道头线圈与压缩感知加速功能。技师拟采用动脉自旋标记（ASL）灌注成像。下列技术判断中错误的是", "o": {"A": "ASL以动脉血中的水质子作为内源性示踪剂，无需注射对比剂，适合肾功能受限患者", "B": "对于颈内动脉重度狭窄导致侧支循环代偿、血流到达延迟的患者，单一标记后延迟时间（PLD）可能低估患侧脑血流，宜适当延长PLD或采用多延迟时间采集", "C": "ASL的信号变化幅度很小，需要多次标记—对照配对采集并平均，因而对头动敏感", "D": "ASL可提供以mL/(100g·min)为单位的脑血流量定量结果", "E": "ASL图像上患侧出现动脉内高信号（血管内明亮的迂曲信号）说明标记效率过低，应缩短标记后延迟时间"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-011", "kp": "ASL灌注成像的参数选择与判读", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】E错误，为应选项。ASL图像上出现的动脉内高信号（arterial transit artifact）提示标记血液尚滞留于近端动脉、未完全进入毛细血管床，是血流到达时间延长的表现，多见于重度狭窄或侧支代偿者；正确对策是延长标记后延迟时间（如由1.5~1.8s延长至2.0~2.5s）或采用多PLD采集，而不是缩短。【为什么错】A正确：ASL以磁化标记的动脉血水质子为内源性示踪剂，是无创、可重复、适合肾功能不全者的灌注方法。B正确：PLD设置不当是脑血流被系统性低估的主要原因，指南建议按年龄与血管病变状态调整。C正确：ASL的标记效应仅为总信号的约1%~2%，需数十次配对采集平均，头动直接破坏减影。D正确：pCASL结合合适的模型可给出定量脑血流量数值。", "tr": "「动脉通过伪影」是ASL最具特征的读图线索：提示延迟到达而非灌注真正减低，应延长PLD复核。切忌把它直接当作低灌注或标记失败。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0112", "t": "多选题", "s": "关于扩散峰度成像（DKI）与神经突方向离散度与密度成像（NODDI），下列说法正确的是", "o": {"A": "DKI在传统扩散张量模型基础上引入四阶峰度项，用以刻画组织内水分子扩散偏离高斯分布的程度，反映微观结构的复杂性", "B": "DKI要求采集至少两个非零b值（通常包含b值达到1500~2500s/mm²的高b值）及足够多的扩散方向", "C": "NODDI采用多壳（multi-shell）扩散采集与三室模型，估计神经突密度指数与方向离散度指数", "D": "与常规DTI相比，DKI与NODDI的采集时间更长、对信噪比与梯度性能要求更高，临床应用需权衡可行性", "E": "DKI的峰度值越高代表水分子扩散越自由，接近自由水状态"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-012", "kp": "DKI与NODDI高阶扩散模型", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】A正确：生物组织中水分子受细胞膜、髓鞘等障碍限制，扩散位移分布偏离高斯分布，峰度即定量这一偏离程度。B正确：拟合峰度项需要至少两个非零b值，且高b值（常用1500~2500s/mm²）才能体现非高斯特性，方向数一般不少于15个。C正确：NODDI基于多壳采集与「细胞内、细胞外、自由水」三室模型，输出神经突密度指数与方向离散度指数，对灰质与交叉纤维区域比DTI更具解释力。D正确：两者的方向数与b值壳数远多于常规DTI，采集时间与信噪比要求显著提高，需结合并行成像、同时多层激发（SMS）与压缩感知等加速手段。【为什么错】E错误：峰度值越高说明扩散受限、微环境越复杂，越偏离高斯扩散；自由水扩散接近高斯分布，其峰度趋近于零，选项含义完全相反。", "tr": "峰度与ADC是两个方向的指标：ADC反映扩散快慢，峰度反映扩散的非高斯（复杂）程度。自由水＝高ADC、低峰度，切勿混淆。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": true, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-0113", "t": "单选题", "s": "关于酰胺质子转移（APT）成像及其所属的化学交换饱和转移（CEST）技术，下列说法正确的是", "o": {"A": "对水峰下游约3.5ppm处的酰胺质子施加选择性饱和脉冲，饱和经化学交换传递至自由水后引起水信号下降，据此间接反映组织内游离蛋白质与多肽的浓度及pH环境", "B": "APT直接采集酰胺质子自身的信号，因此信噪比很高", "C": "APT属于扩散加权成像的一种，其对比来源于水分子的布朗运动", "D": "APT成像不需要B0匀场，磁场不均匀不影响其结果", "E": "APT必须注射外源性对比剂才能成像"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-013", "kp": "APT与CEST成像原理", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】A正确。APT是CEST家族中最成熟的临床应用：在相对水峰约+3.5ppm处施加长时程低功率饱和脉冲选择性饱和酰胺质子，饱和的自旋通过化学交换不断转移至自由水池，使水信号出现可测量的下降；该效应与游离蛋白质／多肽浓度及交换速率（受pH影响）相关，临床用于脑肿瘤分级、复发与治疗后改变的鉴别及缺血半暗带的酸中毒评价。【为什么错】B错误：APT是通过水信号的间接放大效应测量的，酰胺质子本身浓度极低，直接检测信噪比不足，这正是CEST采用间接放大机制的原因。C错误：APT属化学交换对比机制，与扩散无关。D错误：APT对B0极其敏感，频率偏移会使饱和位置偏离目标峰，必须做高质量匀场并采集B0图做Z谱校正。E错误：APT属内源性对比技术，无需外源对比剂，这是其重要优势。", "tr": "CEST／APT成像的两大技术前提：高质量B0匀场加频率校正、稳定的饱和脉冲功率与时长。任一环节不当都会造成伪彩图的系统性偏差。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0114", "t": "多选题", "s": "关于体素内不相干运动（IVIM）成像，下列说法正确的是", "o": {"A": "IVIM采用双指数模型，把扩散信号衰减分解为真扩散成分D与微循环灌注相关的假扩散成分D*及灌注分数f", "B": "低b值区间（一般小于200s/mm²）的信号衰减主要受微循环灌注影响，因此需在低b值段设置较密集的采样点", "C": "IVIM可在不使用对比剂的条件下同时获得扩散与灌注相关信息，适用于肾功能不全或不宜使用钆剂的患者", "D": "D*与f的拟合稳定性较D差，受信噪比、b值分布与运动影响明显，重复性相对较低", "E": "IVIM只需常规DWI的两个b值（0与800s/mm²）即可完成双指数拟合"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-014", "kp": "IVIM双指数模型与采集要求", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】A正确：IVIM模型认为体素信号衰减由分子真扩散与毛细血管网内血流的「假扩散」共同构成。B正确：灌注相关的快速衰减集中在低b值段，故常在0~200s/mm²之间布置多个b值以稳定拟合D*与f。C正确：IVIM为无对比剂的灌注相关成像，在肝纤维化、肿瘤疗效评价与肾功能受限患者中有独特价值。D正确：D*的拟合误差最大，f次之，D最稳定，这是IVIM临床推广的主要制约，因此报告时应关注重复性。【为什么错】E错误：双指数拟合需要多个b值（通常8~12个以上，覆盖低b值密集与高b值稀疏），两个b值只能计算单指数ADC，无法分离灌注与扩散成分。", "tr": "ADC与IVIM的D并不等同：常规ADC（含低b值时）混入了灌注贡献而被系统性高估，这正是IVIM要分离的部分。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-0115", "t": "单选题", "s": "关于MR分子成像的基本概念，下列说法正确的是", "o": {"A": "在活体内以分子或细胞水平的特异性靶点为成像对象，常借助特异性分子探针（如靶向配体标记的超顺磁性氧化铁颗粒）实现，MR的空间分辨率高但检测灵敏度低于核医学方法", "B": "MR分子成像的检测灵敏度高于放射性核素示踪技术", "C": "MR分子成像不需要任何探针，仅靠常规序列即可实现", "D": "MR分子成像是常规增强扫描在分子水平的延伸，二者的对比机制相同", "E": "MR分子成像只能在离体标本上进行"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-015", "kp": "MR分子成像的概念与特点", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (2)MR分子成像", "ex": "【为什么对】A正确。分子影像学指在活体状态下对细胞与分子水平的生物学过程进行可视化与定量；MR分子成像多依赖靶向探针（超顺磁性氧化铁、钆基靶向螯合物、CEST类探针等）改变局部弛豫或化学交换特性。其优势是高空间分辨率与优良软组织对比，短板是探针浓度检测灵敏度较低。【为什么错】B错误：核素示踪的灵敏度可达皮摩尔至纳摩尔量级，远高于MR的微摩尔至毫摩尔量级，这是MR分子成像的固有局限。C错误：绝大多数MR分子成像需要特异性探针，仅少数内源性对比机制（如CEST、波谱）属例外。D错误：常规增强使用非特异性细胞外间隙对比剂，反映的是血流与通透性，不具备分子靶向性。E错误：分子影像的定义前提正是「活体」成像。", "tr": "牢记各模态的分工：核素灵敏度最高但分辨率低，MR分辨率高但灵敏度低，二者互补构成了一体化多模态成像的动因。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0116", "t": "多选题", "s": "关于MR分子成像常用的探针与对比机制，下列说法正确的是", "o": {"A": "超顺磁性氧化铁颗粒主要缩短T2/T2*，在相应序列上表现为信号减低（阴性对比）", "B": "钆基探针主要缩短T1，表现为T1加权像上的信号升高（阳性对比）", "C": "CEST类探针可通过化学交换机制实现无金属的对比增强，并具备一定的pH或代谢物敏感性", "D": "氟-19（¹⁹F）成像因体内背景信号极低，标记物所在区域具有很高的特异性，但需专用射频链与线圈", "E": "目前MR分子探针大多已进入临床常规诊断项目，普及程度与常规增强相当"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-016", "kp": "MR分子探针的类型与对比机制", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (2)MR分子成像", "ex": "【为什么对】A正确：超顺磁性氧化铁产生显著的局部磁场不均匀，主导T2与T2*缩短，形成信号丢失的阴性对比，曾用于肝网状内皮系统与淋巴结成像及细胞标记示踪。B正确：钆的未成对电子缩短T1，为经典阳性对比机制。C正确：CEST探针（含糖类、氨基酸类）无需金属离子即可产生可调频率的对比，并可反映pH与代谢信息。D正确：人体内¹⁹F背景几乎为零，标记细胞或药物的¹⁹F信号具有「有即为真」的特异性，但需要相应频率的发射接收链路与专用线圈。【为什么错】E错误：多数分子探针仍处于临床前或早期临床研究阶段，尚未成为常规诊断项目，把研究性技术描述为已广泛临床使用属超范围表述。", "tr": "阴性对比（T2/T2*缩短，变黑）与阳性对比（T1缩短，变亮）的机制区分是必考点；此外应注意研究阶段技术与临床常规技术的边界。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-0117", "t": "单选题", "s": "关于心肌T1 mapping与T2 mapping的临床意义，下列说法正确的是", "o": {"A": "初始（native）T1升高多见于心肌水肿、淀粉样变与弥漫性纤维化，T1降低见于脂肪浸润与铁过载；T2升高主要反映心肌水肿与炎症", "B": "T1 mapping必须注射钆对比剂才能获得，无法进行平扫定量", "C": "T2 mapping主要用于评价心肌纤维化程度，与水肿无关", "D": "细胞外容积分数（ECV）仅由增强后T1值计算，不需要平扫T1与血细胞比容", "E": "T1、T2定量数值在不同厂家、不同场强与不同序列间可以直接互相比较"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-017", "kp": "心肌T1/T2 mapping的临床意义", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】A正确。初始T1是无对比剂的平扫定量指标：水肿、淀粉样变、弥漫性间质纤维化使T1延长；脂肪浸润（如Anderson-Fabry病的鞘糖脂沉积）与铁过载使T1缩短。T2值主要对自由水敏感，升高提示水肿或急性炎症，是心肌炎与急性心肌梗死的重要指标。【为什么错】B错误：初始T1 mapping在平扫下即可完成，正是其相对延迟强化的优势之一（延迟强化依赖对比剂且需正常心肌作参照，对弥漫病变不敏感）。C错误：纤维化评价主要依赖ECV与延迟强化，T2主要反映水肿。D错误：ECV需由平扫与增强后的心肌与血池T1值以及血细胞比容共同计算。E错误：mapping数值受场强、序列（MOLLI、ShMOLLI、SASHA等）、心率与后处理影响显著，各中心需建立本机正常参考值，不能跨平台直接比较。", "tr": "定量mapping的核心纪律是「本机本序列建立参考值」。同一患者随访必须使用相同场强、相同序列与相同后处理，否则数值不可比。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0118", "t": "案例分析题", "s": "患者男性，24岁，重型β地中海贫血，自幼规律输血治疗，近年血清铁蛋白持续高于2500μg/L，近3个月出现活动后心悸、乏力。临床需要评估其心脏与肝脏的铁沉积程度，以指导祛铁药物剂量调整与疗效随访。所在科室有1.5T与3.0T两台MR设备，均配备多回波定量序列与心电门控。技师需要为其安排铁定量检查方案。下列判断中错误的是", "o": {"A": "心肌铁定量的公认方法是采用多回波梯度回波序列测量室间隔中段短轴的T2*值，T2*小于20ms提示心肌铁过载，小于10ms提示重度铁过载与心力衰竭高风险", "B": "铁的顺磁性作用使局部磁场不均匀、加速质子失相位，因此铁沉积越重T2*值越短、信号衰减越快", "C": "在1.5T与3.0T上测得的T2*绝对值不同，3.0T的T2*值更短，阈值须按对应场强的标准判读，临床更倾向在1.5T进行铁定量", "D": "肝脏铁定量可采用多回波序列测量T2*或R2*，并结合已发表的换算关系估算肝铁浓度", "E": "为提高信噪比，心肌T2*测量应选用长回波链的自旋回波序列，因其对磁化率变化更敏感"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-018", "kp": "T2*铁定量与心肌铁过载评估", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】E错误，为应选项。自旋回波的180度重聚脉冲恰恰消除了静态磁场不均匀引起的失相位，测得的是T2而非T2*，对磁化率变化不敏感；铁定量必须使用无重聚脉冲的多回波梯度回波序列（测T2*或其倒数R2*），一次屏气采集多个递增回波时间的图像并做指数拟合。【为什么错】A正确：室间隔中段短轴层面的心肌T2*是国际公认的心脏铁定量部位与方法，20ms与10ms为经典分界。B正确：铁的顺磁性造成局部磁场梯度、加速横向失相位，铁越多T2*越短。C正确：场强越高磁化率效应越强、T2*越短，阈值不可跨场强套用，且3.0T下重度铁过载者信号衰减过快、拟合困难，故临床铁定量以1.5T为优选。D正确：肝脏R2*与肝铁浓度存在良好相关性，是常规无创评估手段。", "tr": "T2*（梯度回波，含静态场不均匀）与T2（自旋回波，已重聚）的区别是铁定量的核心。凡涉及磁化率相关定量（铁、出血、SWI），一律使用梯度回波。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0119", "t": "单选题", "s": "关于磁共振质子密度脂肪分数（MR-PDFF）测量肝脏脂肪含量，下列说法正确的是", "o": {"A": "采用多回波化学位移编码的梯度回波序列，通过校正T1偏倚、T2*衰减与脂肪多峰波谱模型，得到接近真值的脂肪信号占比，是无创定量肝脂肪的参考方法之一", "B": "只需采集同相位与反相位两个回波，用信号下降百分比即可获得准确的脂肪分数", "C": "PDFF的结果不受肝脏铁沉积的影响", "D": "PDFF只能在1.5T设备上测量", "E": "PDFF数值与肝活检脂肪变性分级一一对应，两者可直接互换使用"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-019", "kp": "MR-PDFF肝脂肪定量", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】A正确。PDFF采用低翻转角多回波化学位移编码梯度回波（如mDIXON Quant、IDEAL-IQ类实现），通过小翻转角抑制T1偏倚、多回波拟合校正T2*、采用脂肪多峰模型校正谱峰分布，最终给出脂肪信号占总质子信号的比例，具有良好的准确性与跨平台重复性。【为什么错】B错误：两点法同反相位仅能定性或粗略半定量，未校正T1偏倚、T2*与脂肪多峰，且在脂肪分数超过50%时存在水脂互换的模糊性。C错误：铁沉积造成T2*显著缩短，若不做T2*校正会明显影响脂肪分数估计，这正是PDFF必须多回波拟合的原因之一。D错误：1.5T与3.0T均可测量，参数需按场强调整。E错误：PDFF是连续的定量指标，与病理分级为相关关系而非等价，二者判读标准不同。", "tr": "同反相位法与PDFF的差别是「半定量」与「定量」之分。此外要记住：同反相位在脂肪分数超过50%时无法区分「脂肪为主」与「水为主」，PDFF通过多回波与相位信息解决了这一模糊性。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0120", "t": "多选题", "s": "关于磁共振弹性成像（MRE）评估肝纤维化，下列说法正确的是", "o": {"A": "通过体表驱动器向肝脏施加低频机械振动（常用60Hz），用运动敏感梯度编码剪切波的传播，反演计算组织硬度并生成弹性图", "B": "肝硬度随纤维化分期升高，MRE对进展期纤维化与肝硬化的诊断效能良好，且不受肥胖与腹水的明显限制", "C": "严重肝铁沉积会造成信号显著衰减，可导致MRE波形图质量差、测量失败", "D": "炎症活动、胆汁淤积、肝静脉淤血与餐后状态均可使肝硬度升高，判读时应结合临床并要求患者空腹", "E": "MRE与超声弹性成像测得的硬度数值单位一致且阈值通用，可直接互换判读"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-020", "kp": "磁共振弹性成像与肝纤维化评估", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】A正确：MRE由被动驱动器传递低频剪切波，序列以运动编码梯度记录波的相位，经反演算法得到以kPa表示的硬度图。B正确：与超声瞬时弹性成像相比，MRE受体型、肋间声窗与腹水影响小，采样体积大、失败率低。C正确：显著铁沉积使T2*极短、梯度回波信号快速衰减，是MRE失败的常见原因，此时可改用自旋回波EPI类MRE序列。D正确：肝硬度是「纤维化＋炎症＋淤血＋灌注状态」的综合表现，急性肝炎、右心衰竭、胆道梗阻与餐后门静脉血流增加均可致假性升高，故要求空腹并结合临床。【为什么错】E错误：MRE与超声弹性成像的激励频率、测量原理与报告量（剪切模量与杨氏模量）不同，数值与阈值不可直接互换。", "tr": "肝硬度升高不等于纤维化：炎症、淤血、淤胆、进食都会抬高读数。跨模态的硬度数值不能互换，这两点是MRE判读的高频陷阱。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-0121", "t": "单选题", "s": "背景抑制全身扩散加权成像（DWIBS）之所以被称为「类PET」成像，其主要依据是", "o": {"A": "采用短反转时间反转恢复脂肪抑制配合自由呼吸多段扩散加权采集，抑制背景肌肉、脂肪与血流信号后，以反转灰阶显示高信号病灶，形成类似PET的全身黑白图像，可反映病变的细胞密度", "B": "它使用了放射性示踪剂，因此能反映代谢活性", "C": "它测量的是组织的葡萄糖代谢率", "D": "它必须在屏气状态下逐段采集才能完成全身覆盖", "E": "它的病灶检出特异性高于PET，可直接替代PET/CT用于肿瘤分期"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-021", "kp": "DWIBS全身类PET成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】A正确。DWIBS以短反转时间反转恢复（STIR）实现均匀脂肪抑制，配合自由呼吸下的多次激励平均与分段采集，抑制背景组织信号；将扩散加权图像做反转灰阶显示后，高细胞密度、扩散受限的病灶呈现为深色高信号灶，整体观感与PET的最大密度投影相似，故称「类PET」。【为什么错】B错误：DWIBS无放射性示踪剂，无电离辐射，这正是其相对PET的优势。C错误：反映的是水分子扩散受限程度（与细胞密度、细胞膜完整性相关），不是葡萄糖代谢。D错误：DWIBS的特点恰是自由呼吸采集，靠多次平均消除呼吸运动影响，屏气反而不适用于长时间全身采集。E错误：DWIBS存在较多假阳性（淋巴组织、脾脏、肠道、神经、炎症与脓肿均可扩散受限）与假阴性（部分低细胞密度或囊性病变），不能直接替代PET/CT，二者为互补关系。", "tr": "扩散受限≠恶性。正常淋巴结、脾、睾丸、脑组织、脓肿与亚急性血肿均可呈高信号，DWIBS必须结合形态学序列与ADC值综合判读。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0122", "t": "案例分析题", "s": "某三级医院拟开展MR引导下的介入操作，初期计划涵盖肝脏、前列腺病灶的穿刺活检以及部分肿瘤的消融治疗，需要对设备条件、器械准入与操作流程进行论证。现有设备为封闭式3.0T诊断用MR，孔径60cm，磁体间已按标准划分安全分区并设置门禁与铁磁探测。作为科室技术骨干参与本次论证并负责起草流程草案，下列判断中错误的是", "o": {"A": "MR引导介入的优势在于软组织对比优异、可多平面任意角度成像、无电离辐射，并可利用温度敏感序列监测消融过程中的温度变化", "B": "必须使用MR兼容（非铁磁、低磁化率）的穿刺针与器械，且需评估其在图像上产生的磁化率伪影大小", "C": "封闭式诊断磁体的孔径与可及性限制明显，实施介入通常需要把患者移出孔外操作、再移入扫描确认，或考虑宽孔径与开放式介入专用设备", "D": "监护设备、麻醉机、输液泵等必须为MR兼容型号，所有进入磁体间的物品都需经过铁磁性筛查", "E": "只要穿刺针标注为不锈钢材质，即可安全用于MR引导穿刺，无需查阅其MR兼容性标识"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-022", "kp": "MR引导介入的设备与器械要求", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】E错误，为应选项。不锈钢是一大类合金，其中马氏体与铁素体不锈钢具有明显铁磁性，属绝对禁用；仅部分奥氏体不锈钢弱磁。器械能否进入磁体间必须依据其MR安全性标识（MR Safe／MR Conditional／MR Unsafe）及厂家说明书规定的场强、梯度与SAR条件，不能凭材质名称推断。【为什么错】A正确：软组织对比、任意平面与无辐射是MR引导的核心优势，质子共振频率法温度成像可实现消融的近实时测温。B正确：钛合金、镍钛合金与特定非磁性合金制成的专用器械可减小磁化率伪影，同时需了解针体伪影会大于其实际直径。C正确：封闭式诊断磁体可及性差，常采用「移出—操作—移入—确认」的分步流程，条件允许时应选用宽孔径或介入专用平台。D正确：磁体间内一切设备与物品均需经铁磁筛查并使用兼容型号，防止投射效应造成严重事故。", "tr": "MR安全标识三分法必须牢记：MR Safe（完全无风险）、MR Conditional（特定条件下安全，须逐条核对）、MR Unsafe（禁入）。凭材质名称或既往经验判断是重大安全隐患。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0123", "t": "单选题", "s": "磁共振引导聚焦超声（MRgFUS）治疗的基本原理是", "o": {"A": "用相控阵换能器将超声能量聚焦于体内靶点产生热凝固（或机械效应），同时由MR提供靶点定位与实时温度监测和治疗反馈，实现无切口治疗", "B": "用MR的射频脉冲直接加热靶组织", "C": "用超声换能器发射X线进行照射治疗", "D": "在MR引导下经皮置入电极进行射频消融", "E": "利用梯度磁场的机械振动破坏靶组织"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-023", "kp": "MRgFUS的原理与应用", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】A正确。MRgFUS由体外相控阵换能器将超声束会聚于体内毫米级焦点，焦域温度可升至60℃以上造成蛋白变性与凝固性坏死；MR负责术前靶点规划、术中基于质子共振频率的实时测温与热剂量计算、术后即刻评价，形成「治疗—监测」闭环。临床已用于子宫肌瘤、骨转移瘤镇痛及震颤等功能神经外科适应证。【为什么错】B错误：MR射频脉冲的能量沉积（SAR）是需要限制的副效应，不能作为治疗性加热手段。C错误：超声换能器不产生X线，二者物理本质完全不同。D错误：这是MR引导下射频消融，属另一类介入方式，需经皮置入电极。E错误：梯度振动只产生噪声与周围神经刺激，不具备热毁损能力。", "tr": "MRgFUS的关键词是「无创（无切口）＋实时测温」。MR在其中承担的是导航与监测角色，能量来自超声而非MR本身。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-0124", "t": "案例分析题", "s": "某肿瘤中心引进磁共振引导直线加速器（MR-Linac），拟用于前列腺癌与肝转移瘤的自适应放射治疗，计划在每次治疗前后及治疗中采集MR图像用于靶区定位与在线计划调整。放疗科邀请影像技术团队参与论证，评估该系统在影像技术层面的特点、质量控制要求与主要挑战，并协助制定几何精度检测方案。作为参与论证的影像技术骨干，下列分析中错误的是", "o": {"A": "MR-Linac将MR成像与直线加速器整合，可在治疗过程中获得优良软组织对比的实时或近实时影像，用于靶区与危及器官的在线定位与自适应计划调整", "B": "MR成像不引入额外电离辐射，相比锥形束CT引导更有利于减少影像引导本身的剂量负担", "C": "静磁场会使次级电子发生洛伦兹力偏转，在组织—空气界面产生电子回旋效应，剂量计算必须考虑磁场影响", "D": "MR图像的几何精度受梯度非线性与磁化率相关变形影响，必须做几何畸变校正与严格的质量控制", "E": "MR图像的灰度值可直接作为电子密度用于剂量计算，无需CT或合成CT信息"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-024", "kp": "MR-Linac的影像技术特点与挑战", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】E错误，为应选项。MR信号强度反映的是质子密度与弛豫特性，与组织的电子密度之间没有直接对应关系，无法直接用于剂量计算；实际工作流依赖配准的定位CT，或由MR图像经算法生成「合成CT／伪CT」提供电子密度信息。【为什么错】A正确：软组织对比优异使前列腺、肝脏等靶区的在线勾画与自适应调整成为可能。B正确：与每日锥形束CT相比，MR引导不增加成像相关电离辐射。C正确：磁场中次级电子受洛伦兹力偏转，在组织—空气界面出现电子回旋效应导致剂量分布改变，须在计划系统中建模。D正确：几何保真度是影像引导放疗的生命线，梯度非线性与磁化率变形必须定期用体模检测与校正。", "tr": "MR「不含电子密度信息」是MR用于放疗计划的根本瓶颈，解决方案是合成CT。把MR信号强度当作密度信息使用，是概念性错误。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": true, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1001", "t": "单选题", "s": "BOLD-fMRI成像的生理基础是", "o": {"A": "脱氧血红蛋白浓度变化引起局部T2*信号改变", "B": "对比剂增强效应", "C": "质子密度变化", "D": "呼吸运动", "E": "磁场漂移"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-101", "kp": "BOLD-fMRI原理", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】BOLD（血氧水平依赖）成像利用脱氧血红蛋白的顺磁性，神经活动时局部血流增加、脱氧血红蛋白相对减少，引起T2*信号变化，从而定位脑功能，故A正确。\n【为什么错】B：BOLD无需外源性对比剂。C：信号基础是磁敏感变化而非质子密度。D：呼吸运动是伪影来源而非成像基础。E：磁场漂移属设备误差，均错误。", "tr": "BOLD的信号源是“内源性脱氧血红蛋白”，不是外源性对比剂。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1002", "t": "单选题", "s": "急性脑梗死DWI的典型表现是", "o": {"A": "梗死区DWI高信号、ADC值降低", "B": "梗死区DWI低信号、ADC值升高", "C": "DWI与ADC均无变化", "D": "梗死区DWI低信号、ADC降低", "E": "梗死区DWI高信号、ADC升高"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-102", "kp": "DWI在脑梗死中的应用", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】急性期细胞毒性水肿使水分子扩散受限，DWI呈高信号，表观扩散系数ADC下降，故A正确。\n【为什么错】B：扩散受限时ADC降低而非升高。C：急性梗死必然出现DWI/ADC改变。D：扩散受限时DWI应为高信号。E：ADC升高代表扩散加快，与梗死不符。", "tr": "“DWI高信号+ADC低”是扩散受限的铁三角，两者方向相反。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1003", "t": "单选题", "s": "扩散张量成像（DTI）中最常用于评估白质纤维完整性的参数是", "o": {"A": "各向异性分数（FA）", "B": "质子密度", "C": "T2弛豫时间", "D": "血氧饱和度", "E": "对比剂浓度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-103", "kp": "DTI参数与纤维示踪", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DTI通过测量水分子扩散的各向异性，以FA值反映白质纤维方向性与完整性，并可进行纤维束示踪，故A正确。\n【为什么错】B：质子密度是常规加权成像基础。C：T2时间是弛豫参数。D：血氧饱和度与BOLD相关。E：对比剂浓度与灌注相关，均非DTI纤维评估参数。", "tr": "DTI关键词是“FA与纤维示踪”，与T1/T2、BOLD、灌注参数区分。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1004", "t": "单选题", "s": "1H-MRS中代表神经元活性的主要代谢物是", "o": {"A": "N-乙酰天门冬氨酸（NAA）", "B": "胆碱（Cho）", "C": "肌酸（Cr）", "D": "乳酸（Lac）", "E": "脂质（Lip）"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-104", "kp": "MRS代谢物", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】NAA主要存在于神经元内，是神经元数量与活性的标志，神经元损伤时NAA降低，故A正确。\n【为什么错】B：Cho反映膜代谢，肿瘤时升高。C：Cr为能量储备标志。D：Lac在缺血时升高。E：Lip见于坏死与肿瘤，均非神经元特异性标志。", "tr": "NAA=神经元、Cho=膜代谢、Cr=能量、Lac=缺血，四个代谢物各自对应。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1005", "t": "单选题", "s": "颅内肿瘤MRS的典型代谢特征是", "o": {"A": "NAA降低、Cho升高", "B": "NAA升高、Cho降低", "C": "NAA与Cho均升高", "D": "NAA与Cho均降低", "E": "Lac升高而NAA正常"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-105", "kp": "肿瘤MRS表现", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】肿瘤破坏神经元使NAA下降，细胞增殖活跃使膜代谢产物Cho升高，故A正确。\n【为什么错】B：肿瘤不出现NAA升高、Cho降低。C：NAA不会随肿瘤升高。D：Cho在肿瘤中通常升高而非降低。E：肿瘤常伴Lac升高，但NAA会降低而非正常。", "tr": "肿瘤MRS三联征：NAA↓、Cho↑，可伴Lac↑。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1006", "t": "单选题", "s": "MRS中乳酸（Lac）峰在长TE条件下（如TE=135ms）的典型表现是", "o": {"A": "峰发生倒置（倒挂）", "B": "峰消失", "C": "峰明显升高", "D": "峰位置迁移", "E": "峰与NAA重叠"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-106", "kp": "Lac峰TE调制", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】乳酸为J耦合多峰，在长TE（135ms或144ms）下因相位演化出现上下倒置的双峰，利用此特征可鉴别Lac峰，故A正确。\n【为什么错】B：长TE时Lac仍可见且倒置，并不消失。C：长TE不使Lac升高。D：峰位置（化学位移）不变。E：Lac在1.3ppm，与NAA（2.0ppm）不重叠。", "tr": "“长TE见倒置Lac”是MRS鉴峰的经典技巧。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1007", "t": "单选题", "s": "动态磁敏感对比灌注成像（DSC-PWI）利用的对比剂效应是", "o": {"A": "首过期间对比剂引起T2*/T2信号下降", "B": "对比剂引起T1信号升高", "C": "对比剂引起质子密度增加", "D": "对比剂引起磁化转移", "E": "对比剂引起射频漂移"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-107", "kp": "DSC-PWI原理", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DSC以T2*/T2加权序列连续采集，对比剂首过期间在组织内造成局部磁敏感变化，使信号下降，据此计算灌注参数，故A正确。\n【为什么错】B：以T1信号升高反映渗透性的是DCE-PWI。C：质子密度增加与对比剂首过无关。D：磁化转移是另一类对比机制。E：射频漂移是设备现象，均与DSC原理不符。", "tr": "DSC（T2*信号下降）与DCE（T1信号增强）是两种不同的灌注原理。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1008", "t": "单选题", "s": "动脉自旋标记（ASL）灌注成像的突出优点是", "o": {"A": "无需注射外源性对比剂", "B": "需要大量对比剂", "C": "只能用于肝脏", "D": "必须屏气", "E": "不显示灌注信息"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-108", "kp": "ASL灌注成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】ASL以射频脉冲对流入动脉血进行磁性标记，利用内源性水分子作为示踪剂，无需外源性对比剂，可反复测量，故A正确。\n【为什么错】B：ASL恰恰不使用对比剂。C：ASL可应用于脑、肾、肺等多部位。D：ASL不强制屏气。E：ASL就是灌注成像，显示组织灌注。", "tr": "ASL是“无对比剂灌注”的代名词，与DSC/DCE形成对比。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1009", "t": "单选题", "s": "MR灌注成像常用的灌注参数不包括", "o": {"A": "脑血容量（CBV）", "B": "脑血流量（CBF）", "C": "平均通过时间（MTT）", "D": "达峰时间（TTP）", "E": "表观扩散系数（ADC）"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-109", "kp": "灌注参数", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】CBV、CBF、MTT、TTP均为MR灌注成像的常用参数，ADC是扩散加权成像（DWI）的参数，不属于灌注参数，故E正确。\n【为什么错】A：CBV（脑血容量）为灌注参数。B：CBF（脑血流量）为灌注参数。C：MTT（平均通过时间）为灌注参数。D：TTP（达峰时间）为灌注参数，均属于灌注参数故不符合题意。", "tr": "灌注看“CBV/CBF/MTT/TTP”，扩散看“ADC”，分属不同功能成像。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1010", "t": "单选题", "s": "7T超高场MR相对于常规场强的主要优势是", "o": {"A": "信噪比（SNR）更高", "B": "B1场更均匀", "C": "SAR更低", "D": "化学位移更小", "E": "磁化率伪影更小"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-110", "kp": "超高场MR优势与挑战", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】信号强度随场强增高而增大，7T可提供显著高于3T及以下的信噪比，利于高分辨率成像，故A正确。\n【为什么错】B：高场射频波长缩短，B1均匀性变差。C：SAR随场强增高而增大。D：化学位移随场强增大而增大。E：磁化率效应在高场更明显，均非优势。", "tr": "高场“高SNR”与“高SAR、B1不均匀、化学位移大、磁化率伪影多”并存。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1011", "t": "单选题", "s": "MR并行采集技术（如SENSE、GRAPPA）的主要作用是", "o": {"A": "利用多通道线圈并行采集加速扫描", "B": "提高静磁场强度", "C": "增加对比剂用量", "D": "降低梯度切换率", "E": "增大扫描层厚"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-111", "kp": "并行成像", "ch": "十七、MR技术的进展 → 1.MR设备 → (4)软件系统", "ex": "【为什么对】并行采集利用相控阵线圈各单元空间敏感度差异，减少k空间采样线数，缩短扫描时间，故A正确。\n【为什么错】B：场强由磁体决定。C：并行成像不涉及对比剂。D：梯度切换率是梯度系统参数。E：层厚是扫描参数，均与加速原理无关。", "tr": "并行成像=多线圈空间编码+扫描加速，核心价值是缩短时间。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1012", "t": "单选题", "s": "压缩感知（CS）技术加速MR扫描的原理是", "o": {"A": "对稀疏k空间数据进行欠采样后通过算法迭代重建", "B": "增加采样线数", "C": "提高TR时间", "D": "增大翻转角", "E": "延长TE时间"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-112", "kp": "压缩感知", "ch": "十七、MR技术的进展 → 1.MR设备 → (4)软件系统", "ex": "【为什么对】压缩感知利用图像在变换域（如小波）的稀疏性，随机欠采样k空间，再经非线性迭代重建恢复图像，从而加速扫描，故A正确。\n【为什么错】B：CS是减少而非增加采样线数。C：提高TR延长扫描时间，与加速相反。D：增大翻转角不影响采样密度。E：延长TE不构成CS加速原理。", "tr": "CS三要素：稀疏性+欠采样+迭代重建。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1013", "t": "单选题", "s": "磁共振指纹（MR Fingerprinting）技术的特点是", "o": {"A": "一次采集即可同时获得T1、T2等多参数定量图", "B": "只能获得T2图", "C": "需要注射对比剂", "D": "只能用于心脏", "E": "不进行定量分析"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-113", "kp": "MR指纹", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】MRF通过伪随机变化的序列参数采集独特信号“指纹”，与预存字典匹配，一次扫描同步重建T1、T2等多张定量图，故A正确。\n【为什么错】B：MRF同时提供多参数。C：MRF无需对比剂。D：MRF可用于颅脑、心脏等多部位。E：MRF正是定量分析技术，均错误。", "tr": "MRF的标签是“一次扫描、多参数定量”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1014", "t": "单选题", "s": "T1 mapping、T2 mapping等定量弛豫成像的临床意义是", "o": {"A": "以量化数值评估组织成分变化（如纤维化、水肿）", "B": "只能改善图像对比", "C": "仅用于血管造影", "D": "替代活检组织学", "E": "降低图像分辨率"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-114", "kp": "定量弛豫成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】定量mapping给出像素级T1、T2数值，可客观反映心肌纤维化、肝脏铁沉积、软骨退变等组织学变化，故A正确。\n【为什么错】B：其价值是定量而非仅对比改善。C：mapping不限于血管。D：定量数值不能完全替代病理活检。E：mapping不降低分辨率。", "tr": "定量mapping把“灰度对比”变为“数值诊断”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1015", "t": "单选题", "s": "全身类PET成像（如DWIBS）的主要临床应用是", "o": {"A": "全身肿瘤筛查、分期与转移灶评估", "B": "测量骨密度", "C": "评估心脏瓣膜", "D": "显示胆道结石", "E": "测量眼压"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-115", "kp": "全身类PET成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】DWIBS等全身扩散加权成像利用肿瘤细胞致密、扩散受限而高信号的特点，背景抑制后类似PET显像，用于全身肿瘤筛查与分期，故A正确。\n【为什么错】B：骨密度用DXA。C：心脏瓣膜用超声/心脏MR。D：胆道结石用MRCP。E：眼压与MR无关，均错误。", "tr": "类PET成像的本质是“全身DWI”，无辐射是其最大优势。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1016", "t": "单选题", "s": "MR分子成像的核心概念是", "o": {"A": "用靶向探针在分子水平检测疾病相关的生物学过程", "B": "提高常规扫描速度", "C": "减少对比剂反应", "D": "改进患者舒适度", "E": "降低磁场强度"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-116", "kp": "MR分子成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (2)MR分子成像", "ex": "【为什么对】MR分子成像借助靶向性对比剂、分子探针或报告基因，在分子与细胞水平特异显示生物过程（如受体表达、细胞凋亡、基因表达），故A正确。\n【为什么错】B：提高常规扫描速度属加速技术。C：减少对比剂反应属安全性优化。D：改进患者舒适度属人文服务。E：降低磁场强度属设备设计，均非分子成像的核心内涵。", "tr": "分子成像的关键词是“靶向探针+分子水平特异检测”。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1017", "t": "单选题", "s": "超高场（3T及以上）B1场不均匀性的常用改善措施是", "o": {"A": "多通道并行发射（并行射频发射）", "B": "降低梯度场强", "C": "增加扫描层厚", "D": "减少接收线圈", "E": "延长重复时间"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-117", "kp": "高场B1均匀性", "ch": "十七、MR技术的进展 → 1.MR设备 → (3)射频系统", "ex": "【为什么对】高场射频波长变短，B1场不均匀，多通道并行发射可分别调控各通道射频幅度与相位，改善B1均匀性与SAR分布，故A正确。\n【为什么错】B：梯度场强不影响B1均匀性。C：层厚是扫描参数。D：减少线圈降低信噪比。E：TR影响对比与时间，均不能改善B1均匀性。", "tr": "B1不均匀→并行发射/介电填充垫；SAR高→限制翻转角与序列。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1018", "t": "单选题", "s": "MRI引导下介入治疗（如MRgFUS）中用于实时监测组织温度的常用技术是", "o": {"A": "质子共振频率（PRF）测温法", "B": "常规T2WI测量", "C": "MRA血管成像", "D": "MR波谱定量", "E": "对比增强扫描"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-118", "kp": "MRI介入温度监测", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】PRF测温利用水分子共振频率随温度变化的特性，以相位图实时反映组织温度变化，是无创测温的主流方法，故A正确。\n【为什么错】B：T2WI只能间接反映热损伤。C：MRA显示血管。D：波谱用于代谢物。E：增强反映灌注，均非温度监测手段。", "tr": "MR温度监测的核心是PRF（质子共振频率位移）法。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1019", "t": "多选题", "s": "MR功能成像技术包括", "o": {"A": "BOLD-fMRI", "B": "扩散加权成像（DWI）", "C": "扩散张量成像（DTI）", "D": "灌注成像（PWI）", "E": "CT灌注成像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-119", "kp": "MR功能成像范畴", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】BOLD、DWI、DTI、PWI等均属于MR功能成像的范畴，故A、B、C、D正确。\n【为什么错】E：CT灌注成像属于CT设备与技术的范畴，不属于MR功能成像技术。", "tr": "MR功能成像（BOLD、DWI、DTI、PWI、MRS）与CT灌注成像分属不同设备体系，注意别把CT技术混入MR选项。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1020", "t": "多选题", "s": "下列情况中DWI呈扩散受限（高信号）表现的有", "o": {"A": "急性脑梗死", "B": "富细胞性肿瘤", "C": "脓肿内稠厚脓液", "D": "蛛网膜囊肿", "E": "脑脊液"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-120", "kp": "DWI扩散受限表现", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】急性梗死细胞毒性水肿、富细胞肿瘤、脓肿脓液均为扩散受限，DWI高信号，故A、B、C正确。\n【为什么错】D：蛛网膜囊肿为纯液体，扩散不受限。E：脑脊液扩散自由，呈低信号，均非扩散受限。", "tr": "“细胞密集+黏稠”是扩散受限的本质，自由液体不受限。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1021", "t": "多选题", "s": "关于MRS代谢物及其临床意义，正确的对应关系包括", "o": {"A": "NAA降低提示神经元损伤", "B": "Cho升高提示细胞膜代谢活跃（肿瘤等）", "C": "Cr相对稳定常作为参考峰", "D": "Lac升高提示无氧代谢（缺血等）", "E": "NAA升高提示肿瘤"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-121", "kp": "MRS代谢物意义", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】NAA降低=神经元损伤，Cho升高=膜代谢活跃，Cr为稳定参考，Lac升高=无氧代谢，故A、B、C、D正确。\n【为什么错】E：肿瘤时NAA降低而非升高。", "tr": "NAA与Cho方向相反（NAA↓、Cho↑）是肿瘤MRS的要点。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1022", "t": "多选题", "s": "MR灌注成像的技术类型包括", "o": {"A": "动态磁敏感对比（DSC）", "B": "动态对比增强（DCE）", "C": "动脉自旋标记（ASL）", "D": "扩散加权成像（DWI）", "E": "MRA血管成像"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-122", "kp": "PWI技术类型", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DSC（T2*首过）、DCE（T1渗透性）、ASL（内源性标记）为MR灌注三大技术，故A、B、C正确。\n【为什么错】D：DWI是扩散成像，非灌注。E：MRA是血管成像，非灌注。", "tr": "灌注（PWI）与扩散（DWI）、血管成像（MRA）是三个不同范畴。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1023", "t": "多选题", "s": "全身类PET成像（DWIBS）的适应证包括", "o": {"A": "肿瘤TNM分期", "B": "淋巴瘤全身评估", "C": "转移灶筛查", "D": "放化疗疗效随访", "E": "冠状动脉狭窄评估"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-123", "kp": "类PET适应证", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】全身DWI用于肿瘤分期、淋巴瘤评估、转移筛查与疗效随访，故A、B、C、D正确。\n【为什么错】E：冠脉狭窄评估属心脏MR/CTA范畴，类PET全身DWI不用于冠脉评价。", "tr": "类PET服务“全身肿瘤学”，冠脉等专科评估不在其列。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1024", "t": "多选题", "s": "MRI定量分析技术包括", "o": {"A": "T1 mapping", "B": "T2 mapping", "C": "T2*/R2*铁定量", "D": "质子密度脂肪分数（PDFF）", "E": "常规SE序列定性T1WI"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-124", "kp": "MRI定量分析", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】T1/T2 mapping、T2*铁定量、PDFF脂肪定量均为定量MRI技术，故A、B、C、D正确。\n【为什么错】E：常规SE序列T1WI用于定性对比观察，输出的是灰度图像而非定量参数图，不属于定量分析技术。", "tr": "定量MRI的共性是把信号强度转化为可测量的组织学数值，常规定性序列不在其列。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1025", "t": "多选题", "s": "超高场（7T）MR面临的挑战包括", "o": {"A": "比吸收率（SAR）升高", "B": "B1场不均匀", "C": "化学位移增大", "D": "磁化率伪影加重", "E": "信噪比降低"}, "d": "难", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-125", "kp": "超高场挑战", "ch": "十七、MR技术的进展 → 1.MR设备 → (1)主磁场系统", "ex": "【为什么对】高场下SAR升高、射频波长缩短致B1不均匀、化学位移与磁化率效应均增大，是7T的主要挑战，故A、B、C、D正确。\n【为什么错】E：7T的信噪比是升高的而非降低。", "tr": "7T“SNR升高”与“SAR/B1/化学位移/磁化率问题增多”并存。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1026", "t": "多选题", "s": "MR分子成像的探针与策略包括", "o": {"A": "超顺磁性氧化铁（SPIO/USPIO）颗粒", "B": "靶向性多肽或抗体偶联探针", "C": "报告基因成像", "D": "细胞示踪标记", "E": "常规钆剂全身增强"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-126", "kp": "MR分子探针", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (2)MR分子成像", "ex": "【为什么对】SPIO颗粒、靶向探针、报告基因与细胞示踪均为MR分子成像策略，故A、B、C、D正确。\n【为什么错】E：常规钆剂全身增强是传统临床增强检查，不属于分子成像探针范畴。", "tr": "分子成像强调“靶向、细胞/分子水平”，常规对比增强不属其列。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1027", "t": "多选题", "s": "关于MR梯度系统的性能参数，正确的说法包括", "o": {"A": "梯度场强决定成像空间分辨率与扩散/EPI能力", "B": "梯度切换率影响成像速度", "C": "高性能梯度是DWI、EPI等快速成像的基础", "D": "梯度场强与切换率越高对神经刺激风险越大", "E": "梯度系统与主磁场无关"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-127", "kp": "梯度系统性能", "ch": "十七、MR技术的进展 → 1.MR设备 → (2)梯度系统", "ex": "【为什么对】梯度场强影响空间分辨与扩散/EPI能力，切换率影响速度，高梯度是快速成像基础，高切换率有外周神经刺激风险，故A、B、C、D正确。\n【为什么错】E：梯度场与主磁场叠加工作、相互关联，说“与主磁场无关”错误。", "tr": "梯度性能“强则快、快则刺激风险高”，且须在主磁场框架下工作。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MR设备的进展", "页": 395}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1028", "t": "多选题", "s": "MRI介入技术的应用包括", "o": {"A": "MRI引导经皮穿刺活检", "B": "MRgFUS聚焦超声消融（如子宫肌瘤）", "C": "介入手术实时温度监测", "D": "术前与术中导航", "E": "超声心动图检查"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-128", "kp": "MRI介入应用", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】MR引导活检、MRgFUS消融、实时温度监测与导航均为MRI介入技术应用，故A、B、C、D正确。\n【为什么错】E：超声心动图属超声设备检查，不属于MRI介入。", "tr": "MRI介入以“MR实时引导+无电离辐射”为特征，超声检查不混入。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 1}, {"id": "ZG-U17-1029a", "t": "单选题", "s": "【病例】患者男性，62岁，突发右侧肢体无力伴言语不清2小时来院，临床高度怀疑急性缺血性脑卒中，拟行急诊头颅MR检查明确梗死范围并评估治疗时机。技师负责序列选择与质控。 对急性脑梗死最具诊断价值的首选序列是", "o": {"A": "扩散加权成像（DWI）", "B": "常规T1WI", "C": "T2加权脂肪抑制", "D": "MRCP水成像", "E": "SWI静脉成像"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-129", "kp": "急性脑梗死DWI检查", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DWI在缺血后数十分钟内即显示扩散受限高信号，是急性脑梗死最敏感的首选序列，故A正确。\n【为什么错】B：T1WI对急性梗死不敏感。C：脂肪抑制用于脂肪病变。D：MRCP用于胆道。E：SWI用于出血与静脉，均非急性梗死首选。", "tr": "“急性脑梗死→DWI高信号”是黄金诊断链。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1029b", "t": "单选题", "s": "梗死区在DWI高信号的同时，其ADC值的变化是", "o": {"A": "ADC值降低", "B": "ADC值升高", "C": "ADC值不变", "D": "ADC值先升后降", "E": "ADC值无法测量"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-130", "kp": "ADC变化", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】细胞毒性水肿使水分子扩散受限，表观扩散系数ADC降低，故A正确。\n【为什么错】B：ADC升高代表扩散加快。C：急性梗死必然出现ADC下降。D：演变期可能伪正常化，但急性期不出现先升后降。E：ADC可由多b值DWI计算，可测量。", "tr": "DWI信号与ADC方向相反：DWI高=ADC低，二者互为印证。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1030a", "t": "单选题", "s": "【病例】患者女性，45岁，头痛伴肢体抽动1个月，头颅MR发现左侧额叶占位，临床拟行MR波谱（MRS）检查辅助肿瘤定性，并评估肿瘤与正常组织代谢差异。技师负责MRS参数与判读。 肿瘤性病变MRS的典型代谢特征是", "o": {"A": "NAA降低、Cho升高", "B": "NAA升高、Cho降低", "C": "NAA与Cho均升高", "D": "NAA与Cho均降低", "E": "仅Lac升高"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-131", "kp": "肿瘤MRS特征", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】肿瘤破坏神经元使NAA降低，细胞增殖使Cho升高，故A正确。\n【为什么错】B：肿瘤不出现NAA升高、Cho降低。C：NAA不会随肿瘤升高。D：Cho在肿瘤中通常升高而非降低。E：肿瘤可伴Lac升高，但NAA同样降低，不是“仅Lac升高”。", "tr": "“NAA↓、Cho↑”是肿瘤MRS的核心组合。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1030b", "t": "单选题", "s": "为更全面地显示短TE可见的多种代谢物，MRS宜选择的TE条件是", "o": {"A": "短TE（如30~35ms）", "B": "长TE（如135ms以上）", "C": "TE=0ms", "D": "TE=500ms", "E": "TE不相关"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-132", "kp": "MRS TE选择", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】短TE（30~35ms）可显示脂质、谷氨酸等短T2代谢物，代谢信息更全；长TE背景简化、便于观察倒置的Lac峰，故A正确。\n【为什么错】B：长TE会丢失部分短T2代谢物。C：TE=0无实际序列意义。D：TE=500ms过长，信号衰减严重。E：TE选择直接影响代谢物显示，不能说不相关。", "tr": "“看全代谢物→短TE；看Lac倒置→长TE”，两问应对应。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1031a", "t": "单选题", "s": "【病例】患者男性，58岁，锁骨上淋巴结肿大伴发热盗汗，临床疑淋巴瘤，拟行全身类PET成像（DWIBS）评估全身病变范围。技师负责扫描方案设计与图像判读。 全身类PET成像采用的核心序列是", "o": {"A": "全身背景抑制扩散加权成像（DWIBS）", "B": "头颅常规T2WI", "C": "腹部CT平扫", "D": "乳腺DBT", "E": "心脏电影序列"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-133", "kp": "类PET扫描序列", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】DWIBS以脂肪与背景信号抑制的全身DWI为技术基础，肿瘤等高细胞密度灶扩散受限呈高信号，效果类似PET，故A正确。\n【为什么错】B：T2WI无扩散信息。C：CT平扫非MR序列。D：DBT用于乳腺。E：心脏电影用于心功能，均不符合类PET技术。", "tr": "类PET=全身DWI（DWIBS），核心是扩散加权+背景抑制。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1031b", "t": "单选题", "s": "类PET扫描中为突出扩散受限病灶、抑制背景信号，通常选用的b值是", "o": {"A": "b值较高（如800~1000s/mm²）", "B": "b值接近0", "C": "b=50s/mm²", "D": "b=100s/mm²", "E": "不使用b值"}, "d": "难", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-134", "kp": "类PET b值选择", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (4)全身类PET成像", "ex": "【为什么对】较高b值（800~1000s/mm²）使扩散快的背景组织（脂肪、正常实质）信号明显衰减，而扩散受限的肿瘤灶保持高信号，对比度最佳，故A正确。\n【为什么错】B：b=0为T2加权，无扩散权重。C：b=50s/mm²扩散权重不足。D：b=100s/mm²同样偏低，背景抑制差。E：DWI必须设b值，不能不用。", "tr": "b值越高扩散权重越大、背景越黑、肿瘤灶越突出，但过高会降低信噪比。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1032", "t": "案例分析题", "s": "患者男性，38岁，左侧额叶海绵状血管瘤拟行手术切除，病灶邻近左侧运动功能区。术前需要精确定位大脑皮层运动中枢与病灶的空间关系，以规划手术入路、保护运动功能。技师实施的功能成像方案中BOLD-fMRI以血氧水平依赖信号变化定位功能皮层，任务态设计可激活对应功能区并与解剖图像叠加。结果需与解剖图像配准后用于神经外科手术计划制定。最合适的是", "o": {"A": "BOLD-fMRI进行运动任务态功能定位", "B": "常规T2WI", "C": "MRCP水成像", "D": "腹部脂肪抑制", "E": "全身类PET"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-135", "kp": "BOLD术前功能定位", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】BOLD-fMRI通过运动任务激活对应皮层，在解剖图像上叠加功能激活区，可明确运动功能区与病灶的空间关系，故A正确。\n【为什么错】B：T2WI只显示病灶解剖。C：MRCP用于胆道。D：脂肪抑制与功能定位无关。E：类PET用于全身肿瘤，均不符合术前功能定位需求。", "tr": "术前功能定位用BOLD-fMRI（任务态或静息态）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1033", "t": "案例分析题", "s": "患者女性，50岁，右乳肿块，乳腺MRI增强检查拟行DCE灌注定量分析，评估病灶血流灌注与微血管渗透性，辅助良恶性鉴别及治疗前评估。技师在扫描与后处理中DCE灌注基于T1动态增强扫描与药代动力学模型，可计算Ktrans、Ve等反映微血管通透性的定量参数。定量结果受注射方案与模型选择影响，应保证采集条件一致。应重点获取的定量参数是", "o": {"A": "Ktrans（容积转移常数）等渗透性参数", "B": "ADC值", "C": "FA值", "D": "BOLD信号", "E": "PDFF脂肪分数"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-136", "kp": "DCE定量参数", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (1)MR功能成像", "ex": "【为什么对】DCE灌注基于T1动态增强，通过药代动力学模型计算Ktrans、Ve等渗透性参数，反映微血管通透性，是乳腺病变评估的关键定量指标，故A正确。\n【为什么错】B：ADC是扩散参数。C：FA是DTI参数。D：BOLD是功能激活参数。E：PDFF是脂肪定量参数，均与DCE渗透性无关。", "tr": "DCE看Ktrans（渗透性），DSC看CBV/CBF（灌注量），参数别张冠李戴。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1034", "t": "案例分析题", "s": "某医院引进3.0T MR后，在腹部与盆腔扫描中发现部分患者图像出现亮暗不均、局部信号缺失，疑似高场射频相关伪影，影响诊断信心。技师分析原因并调整扫描方案。关于3T场强下图像不均匀的处理，高场射频波长缩短导致B1场不均匀，可采用多通道并行发射、B1匀场及介电填充等射频端手段改善。对于腹部等大视野部位，B1均匀性管理尤为重要。最有效的是", "o": {"A": "启用多通道并行发射或应用B1匀场与介电填充技术改善B1均匀性", "B": "降低磁场强度至0.5T", "C": "加大扫描层厚", "D": "减少序列重复时间", "E": "取消所有射频脉冲"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-137", "kp": "高场B1不均处理", "ch": "十七、MR技术的进展 → 1.MR设备 → (3)射频系统", "ex": "【为什么对】3T及以上射频波长缩短导致B1不均匀，多通道并行发射、B1匀场及介电填充可改善B1分布、减少信号不均，故A正确。\n【为什么错】B：降低场强不现实且牺牲SNR。C：层厚增大降低分辨率。D：TR与B1均匀性无关。E：取消射频无法成像，均错误。", "tr": "高场B1不均的对策是“射频端工程手段”，而非扫描参数或降场强。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1035", "t": "案例分析题", "s": "患者男性，40岁，地中海贫血，需评估心脏与肝脏铁过载程度以指导祛铁治疗。临床申请MRI铁定量检查，要求给出可量化的铁沉积指标并选择合适的测量部位。技师铁沉积使T2*/T2明显缩短，肝脏以R2*、心脏以T2*多回波测量评估铁过载程度并指导祛铁治疗。结果以mapping图与数值报告形式提供，供临床评估疗效。应选择的定量方法及测量部位是", "o": {"A": "肝脏R2*/T2* mapping，心脏T2*测量", "B": "颅脑MRS", "C": "膝关节T1 mapping", "D": "乳腺DCE", "E": "颈部MRA"}, "d": "中", "c": "应用", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-138", "kp": "铁定量成像", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】铁沉积使T2*/T2缩短，肝脏以R2*、心脏以T2*（多回波）测量铁含量，是铁过载评估的定量方法，故A正确。\n【为什么错】B：MRS测代谢物。C：T1 mapping用于纤维化等。D：DCE用于灌注。E：MRA用于血管，均与铁定量无关。", "tr": "铁定量=肝脏R2*/心脏T2*，属于T2*家族。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1036", "t": "案例分析题", "s": "某科研中心拟开展MR指纹（MRF）研究，希望在一次扫描中同时获得T1、T2及质子密度等多参数定量图，用于组织特征表征与纵向随访。技师评估该技术时，MRF通过伪随机变化的序列参数采集独特信号指纹，与预存字典匹配后一次扫描可同时输出T1、T2、PD等多张定量图。其定量结果可用于不同时间点检查之间的纵向对比分析。正确的认识是", "o": {"A": "MRF一次采集经字典匹配同时输出多张定量图，无需对比剂", "B": "MRF只能输出T2图", "C": "MRF必须注射对比剂", "D": "MRF只适合心脏", "E": "MRF不能定量分析"}, "d": "中", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-139", "kp": "MR指纹特点", "ch": "十七、MR技术的进展 → 2.MR检查技术 → (3)MRI定量分析", "ex": "【为什么对】MRF以伪随机序列参数产生独特信号指纹，与预存字典匹配，一次扫描同步重建T1、T2、PD等多参数定量图，且无需对比剂，故A正确。\n【为什么错】B：MRF输出多参数。C：MRF无需对比剂。D：MRF适用于脑、心等多部位。E：MRF的核心就是定量分析，均错误。", "tr": "MRF=“一次采集、多参数定量”，是定量MRI的前沿代表。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": null, "页": null}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-1037", "t": "案例分析题", "s": "患者女性，42岁，症状性子宫肌瘤拟行MRgFUS（磁共振引导聚焦超声）消融治疗。治疗全程需要在消融的同时监测组织温度与疗效，确保安全并避免损伤邻近组织。技师负责治疗计划与术中成像方案，MRgFUS治疗需术前三维计划、术中实时引导与PRF温度监测相结合，确保靶区充分消融且不损伤周围组织。治疗过程中需同步监测患者耐受与邻近器官温度保护。正确的做法是", "o": {"A": "治疗前制定三维计划，术中以PRF测温序列实时监测靶区温度并观察消融范围", "B": "无需温度监测直接治疗", "C": "用CT代替MR引导", "D": "术中不做任何成像", "E": "仅凭患者感觉判断消融范围"}, "d": "难", "c": "分析", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-140", "kp": "MRgFUS治疗", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】MRgFUS要求术前三维定位规划，术中采用PRF测温法实时监测靶区温度，并结合增强/非增强成像确认消融范围，确保疗效与安全，故A正确。\n【为什么错】B：无温度监测无法保证安全。C：CT无温度监测且含电离辐射。D：不成像无法引导与评估。E：患者感觉不能客观反映消融范围，均错误。", "tr": "MRgFUS的“MR”价值正在于无辐射实时测温（PRF）。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MRI介入技术进展", "页": 404}, "hf": false, "src": "正高拓展", "mk": 0}, {"id": "ZG-U17-9016", "t": "单选题", "s": "在 MR 引导介入（MRI 介入技术）中，对穿刺与器械的核心要求是", "o": {"A": "可使用常规铁磁性不锈钢器械以降低成本", "B": "必须使用 MR 兼容/无磁材料及射频透明器械，避免抛射、伪影与加热", "C": "器械越长越好以到达深部病灶", "D": "无需考虑 SAR，可长时间高功率扫描", "E": "任何 CT 介入器械均可直接用于 MR 介入"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-009", "kp": "MR介入器械要求", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】B正确——MR 介入须在强磁场与射频场中进行，器械须为无磁/弱磁、射频透明且兼容，防止铁磁器械抛射伤人、产生严重伪影或射频加热灼伤；这是 MR 介入安全与成像质量的前提。【为什么错】A铁磁器械在磁场中抛射是严重事故；C器械选择取决于入路与病灶而非越长越好；D仍需控制 SAR 防止患者热损伤；E CT 器械多含铁磁部件，不能直接用于 MR。", "tr": "MR 介入第一原则是\"无磁/MR兼容\"，铁磁器械绝对禁止。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MRI介入技术进展", "页": 404}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U17-9017", "t": "单选题", "s": "MR 引导介入治疗中，常利用以下哪项原理实现实时温度监测", "o": {"A": "超声回波强度变化", "B": "质子共振频率（PRF）随温度偏移，通过相位图测温度", "C": "X 线衰减系数变化", "D": "放射性核素分布", "E": "血氧水平依赖（BOLD）对比"}, "d": "易", "c": "记忆", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-010", "kp": "MR实时温度监测原理", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展 → (1)MRI介入技术进展", "ex": "【为什么对】B正确——水分子质子共振频率随温度升高约 0.01 ppm/°C 线性偏移，MR 通过采集相位信息生成温度图，实现非侵入、实时的组织温度与热剂量监测，是 MR 引导聚焦超声（MRgFUS）等治疗的核心。【为什么错】A超声不属 MR 测温；C为 CT 原理；D为核医学；E BOLD 反映血氧变化而非温度。", "tr": "MR 测温核心是 PRF 相位偏移，不是 BOLD，也非超声。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "MRI介入技术进展", "页": 404}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U17-9201", "t": "单选题", "s": "MRI 引导介入的优势在于", "o": {"A": "无电离辐射且软组织对比佳，可实时温控", "B": "辐射剂量低但无软组织对比", "C": "需大量造影剂", "D": "仅用于骨骼", "E": "扫描极快"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-9201", "kp": "MRI介入优势", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展", "ex": "【为什么对】MRI 引导无电离辐射、软组织对比好，且可实时温度监测（如聚焦超声），适合经皮活检与消融。\n【为什么错】MRI 软组织对比佳而非差。", "tr": "MRI介入=无辐射+好对比+温控。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}, {"id": "ZG-U17-9202", "t": "单选题", "s": "MRI 兼容的介入器械必须具备", "o": {"A": "抗磁（无铁磁性）且不影响梯度/射频", "B": "高含铁量", "C": "导电性", "D": "放射性", "E": "可透视即可"}, "d": "中", "c": "理解", "m": "学科新进展", "u": "十七", "un": "MR技术进展", "kpid": "UNIT-17-MRI-9202", "kp": "MRI兼容器械", "ch": "十七、MR技术的进展 → 3.MRI介入技术进展", "ex": "【为什么对】MRI 介入器械须为非铁磁性、MR 兼容，避免被磁场吸引与产热。\n【为什么错】含铁量高是禁忌。", "tr": "MRI器械须抗磁兼容。", "bk": "正高", "ref": {"篇": "影像技术学科进展", "章": "MR技术的进展", "节": "磁共振成像新技术", "页": 399}, "hf": false, "src": "模拟", "mk": 0}];
window.QUESTIONS=window.QUESTIONS_ALL.filter(q=>(q.bk||"副高")==="副高");
